INSERT INTO "analysis_memo" VALUES('f7bbd69804d9c16f924166a1bf21e6c6a22f3f0f6faa0d2b62e63ea929ab375b','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект регулирует профессию диетолога: вводит право выполнения профессии, реестр и профессиональное самоуправление (Krajowa Izba Dietetyków). Для иностранцев как таковых он ничего не меняет, кроме общих правил признания квалификаций из ЕС/ЕЭЗ/Швейцарии.","key_changes":["Введение обязательного права выполнения профессии диетолога и реестра","Признание дипломов из ЕС/ЕЭЗ/Швейцарии и стран вне ЕС по общим правилам","Требование знания польского языка на уровне B2 для лиц без польского гражданства","Возможность временного и окказионального оказания услуг диетологами из ЕС/ЕЭЗ","При заявлении требуется документ, подтверждающий право пребывания в Польше"],"affected_groups":["иностранцы с дипломом диетолога","специалисты из стран ЕС/ЕЭЗ/Швейцарии","диетологи с дипломами из третьих стран"],"practical_impact":"Иностранец, желающий работать диетологом в Польше, должен будет подтвердить квалификацию, знание польского на уровне B2, приложить документ о праве пребывания и получить право выполнения профессии; сам статус пребывания законопроект не меняет.","effective_date":"1 января 2027 г., за исключением ст. 23–28 и ст. 10 п. 1, 2 и 4 — через 36 месяцев со дня опубликования","confidence":0.8,"rationale":"Законопроект касается регулирования профессии в целом; иностранцы упоминаются лишь в контексте признания квалификаций и языкового требования, что не меняет условий их пребывания или трудоустройства как таковых.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":290493,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:28Z","input_tokens":144600,"output_tokens":622,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3126/3126.pdf","source_kind":"print","revision":1,"text_sha256":"b0e16463e3e5b28d5492452462d95d52417194eab2452557d16b2542e3396dec","source_checked_at":"2026-09-17T19:46:28Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('f725583e82f844458d58d9d909efc5108422591f9c9c82a8b6560057338aee29','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Prawo ochrony środowiska (закон об охране окружающей среды): звук колоколов и звукоусиливающих систем религиозного культа выводится из-под норм шума и решений о допустимом уровне шума. Для иностранцев никаких правовых последствий нет.","key_changes":["Исключение систем нагłaśniających религиозного культа из решений о допустимом уровне шума (art. 115a ust. 2)","Запрет на использование звукоусиливающих устройств в общественных местах не применяется к практике религиозного культа (art. 156 ust. 2)"],"affected_groups":["приходы и религиозные общины","жители домов рядом с храмами"],"practical_impact":"Ничего не меняется в вопросах пребывания, работы или социальных прав иностранцев; изменение касается только шума от религиозных объектов.","effective_date":"Через 14 дней после публикации.","confidence":0.95,"rationale":"Тема — шум от церковных колоколов; иностранцы упомянуты лишь риторически в обосновании, правовых последствий для них нет.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":18591,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:37Z","input_tokens":9214,"output_tokens":408,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31346-2026/$file/10-RPW-31346-2026.pdf","source_kind":"print","revision":1,"text_sha256":"cd7a7425e388f5525a3ab2097f03939e9d5e158eb9092f2cdc2bf31741cfead3","source_checked_at":"2026-09-17T19:46:37Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('0d2742c9b566fe6075a45ed378a660a1a58c9af2643abf652dfc968c71f3caa4','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект внедряет европейский кошелёк цифровой идентичности (EUDI Wallet) в рамках mObywatel и меняет правила электронной идентификации и доверенных услуг. Кошелёк должны получить все физические лица в Польше, включая иностранцев-резидентов, а не только граждан. Предусмотрены пункты подтверждения личности, в том числе у воеводы.","key_changes":["Министр цифровизации обеспечивает европейский кошелёк цифровой идентичности для физических и юридических лиц","Подтверждение личности возможно у wojewoda, в банке или в органе гмины при личном присутствии","Набор данных кошелька: имя, фамилия, дата и место рождения, PESEL, гражданство, пол, фото","Кошелёк приравнивается к документу, удостоверяющему личность, при очной проверке (с 24.12.2027)","Бесплатная квалифицированная электронная подпись для непрофессиональных целей","Централизованная система сопоставления личности с реестром PESEL для иностранных средств идентификации"],"affected_groups":["иностранцы, постоянно проживающие в Польше","лица с номером PESEL","лица без PESEL, пользующиеся электронной идентификацией из других стран ЕС","юридические лица и предприниматели"],"practical_impact":"Иностранцы-резиденты, не имеющие польского удостоверения личности, смогут получить цифровой кошелёк, подтвердив личность лично в пункте у воеводы, банка или гмины; кошелёк позволит подтверждать личность и подписывать документы онлайн.","effective_date":"Закон вступает в силу 24 декабря 2026 г., с исключениями: часть норм — на следующий день после публикации, отдельные — 31.12.2027, 30.06.2028, 24.12.2027, 31.12.2029 и через 18/24 месяца после публикации","confidence":0.75,"rationale":"Проект не касается легализации пребывания, но прямо предусматривает доступ к цифровой идентичности для резидентов-неграждан и подтверждение личности через воеводу, что даёт косвенное воздействие.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":296222,"truncated":false,"text_source":"documents","created_at":"2026-09-18T09:55:32Z","input_tokens":141318,"output_tokens":773,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12407350/13188189/13188190/dokument791977.zip","source_kind":"rcl","revision":1,"text_sha256":"ed6e19bc686b1886fa0aa33cf222c8cc825c857aea502a54756ef9cc4915b84c","source_checked_at":"2026-09-18T09:55:32Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('ee447f12bc093fedc2e017a32afb0ef39f6348b1605921e52f342a1176f5e46a','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Реформа Krajowy Rejestr Sądowy (судебный реестр): полная электронизация процедур, счета компаний в судебной системе, новые пометки о непредставлении финансовой отчётности и упрощённая ликвидация «мёртвых» фирм. Для иностранцев значение имеет уточнение заявлений о статусе cudzoziemiec при покупке долей и акций.","key_changes":["Заявитель обязан указать, является ли приобретатель долей/акций cudzoziemcem по ustawa z 1920 r. o nabywaniu nieruchomości","При статусе cudzoziemca — дополнительное заявление о наличии у компании недвижимости в Польше","Обязательное наличие правового титула на помещение по адресу siedziby и приложение документа к заявке","Все заявления и письма в реестровый суд — только через teleinformatyczny счёт компании","Новая пометка в KRS о непредставлении финансовых документов; через год — роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — участники и акционеры польских компаний","иностранные предприниматели, регистрирующие компании в KRS","фонды и объединения с иностранным участием"],"practical_impact":"Иностранцу, покупающему доли или акции польской компании, придётся точнее декларировать свой статус и наличие недвижимости у фирмы; при регистрации или смене адреса потребуется документ о праве на помещение, а вся переписка с судом пойдёт через электронный счёт компании.","effective_date":"Закон вступает в силу 1 октября 2027 г., за исключением отдельных норм о пометке о непредставлении финансовых документов — с 1 октября 2028 г.","confidence":0.85,"rationale":"Закон касается реестра предпринимателей, а иностранцы затрагиваются лишь косвенно — через заявления о статусе cudzoziemca при приобретении долей и общие правила для компаний.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":188666,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:34Z","input_tokens":94070,"output_tokens":1006,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","source_kind":"print","revision":1,"text_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","source_checked_at":"2026-09-18T19:07:34Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('3f091b012cf8c832c7f583b9acc432bc0209e0cd6071475e1e17a75522d0898a','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет правила информирования участников уголовного процесса (обвиняемых, потерпевших, свидетелей) об их правах. Образцы таких уведомлений будут утверждены министром и опубликованы на сайте Ministerstwo Sprawiedliwości вместе с переводами на иностранные языки, чаще всего используемые в уголовных делах.","key_changes":["Единые образцы письменных pouczeń для обвиняемых, потерпевших, свидетелей на судебной стадии","Публикация образцов на сайте MS с переводом на самые частые иностранные языки","Расширение информирования задержанного о праве и сроке требовать компенсацию за необоснованное задержание","Аналогичное информирование при tymczasowe aresztowanie и при необоснованном осуждении","Свидетелю сообщат о праве на помощь представителя и о возможности допроса консулом"],"affected_groups":["иностранцы — участники уголовного процесса в Польше","задержанные и арестованные иностранцы","свидетели и потерпевшие, не владеющие польским языком"],"practical_impact":"Иностранец, участвующий в уголовном деле, получит стандартное письменное разъяснение своих прав, доступное в переводе на распространённые иностранные языки, включая информацию о праве на переводчика, адвоката и компенсацию за необоснованное задержание.","effective_date":"Закон вступает в силу 1 января 2027 года; новые нормы применяются также к делам, начатым ранее.","confidence":0.82,"rationale":"Норма касается уголовной процедуры в целом, но прямо предусматривает переводы уведомлений и права неговорящих по-польски, что даёт косвенное значение для иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":159462,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:27Z","input_tokens":82049,"output_tokens":628,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2997/2997.pdf","source_kind":"print","revision":1,"text_sha256":"4de1a98333983b34fcca93efc8641bdeaa8323d09fbbe52b80ffa5e365197b1b","source_checked_at":"2026-09-18T19:07:27Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('27bbe0f88317802ceab3ef360344ac055b7a341c57d9d37afa91b3e5b231372f','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Законопроект вводит «статус артиста» (status artysty) и доплату государства к взносам ZUS и на медстрахование для людей творческих профессий с низкими доходами. Иностранцы с определёнными видами легального пребывания в Польше прямо включены в круг заявителей.","key_changes":["Статус артиста на 5 лет (после трёх раз — на 8) выдаёт dyrektor Instytucji, решение обжалуется министру","Право подать заявление имеют граждане ЕС/ЕЭЗ/Швейцарии и члены семей с правом пребывания","Иностранцы с pobyt stały, rezydent UE, рядом zezwoleń na pobyt czasowy (в т.ч. ст. 114, 127, 151, 139a), беженцы и лица с доп. защитой — тоже","Исключены лица с разрешением на пребывание и работу до 9 месяцев (или до 6 мес. для научных случаев)","Доплата назначается ZUS при среднем доходе за 3 года не выше 125% годового минимального заработка"],"affected_groups":["граждане ЕС/ЕЭЗ/Швейцарии и члены их семей в Польше","иностранцы с pobyt stały и rezydent długoterminowy UE","обладатели отдельных zezwoleń na pobyt czasowy (работа, ICT, научные исследования)","беженцы и лица с дополнительной защитой","граждане Великобритании по Brexit-соглашению"],"practical_impact":"Иностранцы-творческие работники с подходящим основанием пребывания смогут получить статус артиста и войти в систему ZUS/NFZ, а при низких доходах — государственную доплату к взносам. Заявление на статус подаётся в Instytucję, на доплату — в ZUS электронно через profil informacyjny.","effective_date":"Первый день месяца, следующего за истечением 9 месяцев со дня опубликования.","confidence":0.85,"rationale":"Закон касается социального страхования и взносов, прямо перечисляя категории иностранцев, имеющих право на статус артиста, — это социальная сфера, а не легализация пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":86933,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:51Z","input_tokens":44861,"output_tokens":851,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf","source_kind":"committee_report","revision":1,"text_sha256":"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72","source_checked_at":"2026-09-18T19:07:51Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('79f783469271105517ebb6c902d1d5c485f34a8fd61a3021b75fcf2d2470fdd6','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Уголовно-процессуальный кодекс и связанные законы: доступ к защитнику, права задержанных, порядок временного ареста, право на переводчика для тех, кто не владеет польским. Это общие процессуальные гарантии, а не нормы о пребывании или работе иностранцев.","key_changes":["Расширено право на бесплатного переводчика для обвиняемого, не владеющего польским языком","Право требовать перевода документов, важных для защиты, и жаловаться на качество перевода","Постоянное место жительства в другой стране ЕС приравнено к проживанию в Польше при оценке риска побега","Обязательное участие защитника при допросе подозреваемого младше 18 лет","Доступ задержанного и защитника к материалам, обосновывающим задержание и арест"],"affected_groups":["иностранцы, оказавшиеся подозреваемыми или задержанными в Польше","лица, не владеющие польским языком, в уголовном процессе","граждане других стран ЕС, проживающие за пределами Польши"],"practical_impact":"Иностранец, попавший в уголовный процесс в Польше, получит более широкий доступ к переводчику и защитнику, а проживание в другой стране ЕС больше не будет само по себе основанием считать его склонным к побегу. На легализацию пребывания или работу это не влияет.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.85,"rationale":"Это реформа уголовного процесса; положения о переводчике и о месте жительства в ЕС касаются иностранцев лишь косвенно и не меняют их статуса пребывания или занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":449323,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:02Z","input_tokens":227761,"output_tokens":614,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2802/2802.pdf","source_kind":"print","revision":1,"text_sha256":"1495a1bc2a8b6f5353e9f6670c0d7bc3dcdaf5c4e511d900e692aabe1aeccccb","source_checked_at":"2026-09-18T19:08:02Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('7cd73aed2c10fe0e6913e8bfc97e0e281e2c9e64b70f26d956a16ea8c92eadb7','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект ужесточает условия доплаты пенсии до минимальной из ZUS: помимо возраста и стажа потребуется накопить на пенсионном счёте взносы не ниже 25-кратного минимального вознаграждения (в 2026 г. — около 120 150 zł). Формально касается всех, но по обоснованию нацелен на иностранцев с коротким стажем работы в Польше.","key_changes":["Новое условие в art. 87 ust. 1 ustawy o emeryturach i rentach z FUS для доплаты до минимальной пенсии","Требуется валоризованная сумма взносов на счёте не ниже 25-кратного минимального вознаграждения (~120 150 zł в 2026 г.)","Условия возраста (65/60 лет) и стажа (25/20 лет) сохраняются","Новые правила применяются и к делам, начатым, но не завершённым до вступления в силу","Цель обоснования — ограничить доплаты лицам с минимальным стажем работы в Польше"],"affected_groups":["Иностранцы, работавшие в Польше и получающие пенсию из ZUS","Граждане Украины и других стран с договорами о социальном обеспечении с Польшей","Лица с коротким периодом уплаты взносов в Польше","Граждане Польши с низкими накоплениями в ZUS"],"practical_impact":"Если сумма взносов на счёте в ZUS ниже указанного порога, доплата до минимальной пенсии не будет назначена, даже при достаточном общем стаже с учётом периодов работы за границей. Это касается и заявлений, поданных до вступления закона в силу, но ещё не рассмотренных.","effective_date":"Через 14 дней со дня опубликования","confidence":0.9,"rationale":"Проект напрямую влияет на социальные выплаты (пенсии) иностранцам, работавшим в Польше, но не затрагивает легализацию пребывания или работу.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":38308,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:16Z","input_tokens":20036,"output_tokens":700,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31544-2026/$file/10-RPW-31544-2026.pdf","source_kind":"print","revision":1,"text_sha256":"7aae2f3eaa2548b831721657874f012c71cfa9ad6d26f74c06d1f4b75e9c11e2","source_checked_at":"2026-09-18T19:08:16Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('fc06c8abc44bf2ec45706c79184fe29843ed1978dbcf795d123174c03cf5b776','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет Prawo o notariacie (закон о нотариате) и Kodeks postępowania cywilnego. Для иностранцев значим один пункт: при покупке недвижимости или приобретении долей/акций польской компании нотариальный акт должен содержать сведения о гражданстве и номер PESEL. Остальное касается организации работы нотариусов.","key_changes":["В акте о покупке недвижимости иностранцем указываются гражданство и номер PESEL физлица","Для субъекта с местом нахождения в РП — заявление, является ли он cudzoziemcem, с обоснованием и REGON","Требование распространено и на приобретение долей, акций или прав и обязанностей в польской компании","В akt poświadczenia dziedziczenia добавляются PESEL наследников и REGON юрлиц","Нотариус сможет подавать заявления в księga wieczysta и вне связи с собственной сделкой (платно)"],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранцы, приобретающие доли и акции польских компаний","наследники-иностранцы","клиенты нотариальных контор"],"practical_impact":"При сделке с недвижимостью или долями компании нотариус потребует данные о гражданстве и номер PESEL, а при отсутствии однозначности — заявление о статусе cudzoziemca. Дополнительно появится платная возможность подать заявление в земельную книгу через нотариуса.","effective_date":"Через 14 дней после опубликования; изменение ст. 1 п. 23 lit. b (подача заявлений в księga wieczysta) — через 6 месяцев после опубликования.","confidence":0.85,"rationale":"Основная часть проекта касается профессии нотариуса, но есть конкретное новое требование к данным иностранцев в нотариальных актах при сделках с недвижимостью и долями — косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":128815,"truncated":false,"text_source":"documents","created_at":"2026-09-21T10:53:18Z","input_tokens":61122,"output_tokens":806,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12414851/13227172/13227173/dokument798038.docx","source_kind":"rcl","revision":1,"text_sha256":"abdffc03069000691d48f86368d70d0afb5fb4f86460d0cac453a21aa6c8daba","source_checked_at":"2026-09-21T10:53:18Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('1601068bf49fc0fd5df11b1fac074578a38675857242151e23e947806a52ab90','{"triage":{"affects_foreigners":false,"confidence":0.65,"rationale":"Projekt dotyczy głównie procedur notarialnych i postępowania wieczystoksięgowego (organizacja kancelarii, kadencje samorządu notarialnego, archiwizacja dokumentów), a wzmianka o cudzoziemcach ogranicza się do technicznego obowiązku odnotowania obywatelstwa przy nabywaniu nieruchomości, co nie zmienia praw ani obowiązków cudzoziemców w sposób istotny."},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_tokens":7726,"output_tokens":562,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('22487ee77f4d537b75a66c07298e6f4725f58b53832290b0ecf453b811968d6f','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект вводит новый закон о стажировках (staże) вместо ustawa o praktykach absolwenckich (закон о выпускных практиках): стажировки становятся обязательно оплачиваемыми, с письменным договором и страхованием. Закон распространяется на граждан ЕС/ЕЭЗ и на иностранцев, перечисленных в ст. 3 ч. 1 ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom (закон о допустимости поручения работы иностранцам).","key_changes":["Отмена ustawa o praktykach absolwenckich; бесплатные выпускные практики больше невозможны","Круг участников: поляки, граждане ЕС/ЕЭЗ и иностранцы из ст. 3 ч. 1 закона о поручении работы иностранцам","Денежная выплата стажёру: не менее 35% среднего заработка и не выше среднего заработка","Договор о стажировке — письменный, максимум 6 месяцев, срок предупреждения 7 или 14 дней","Стажёр подлежит соцстрахованию как исполнитель zlecenie и медстрахованию NFZ через организатора"],"affected_groups":["граждане ЕС/ЕЭЗ в Польше","иностранцы со свободным доступом к рынку труда по ст. 3 ч. 1 закона о поручении работы иностранцам","граждане Украины, охваченные специальным законом (в части ст. 26)","молодёжь и выпускники, включая несовершеннолетних стажёров"],"practical_impact":"Иностранцы, имеющие доступ к польскому рынку труда, смогут проходить стажировку только по письменному договору и за оплату не ниже 35% среднего заработка, с социальным и медицинским страхованием; бесплатные практики исчезнут. Для иностранцев без такого доступа стажировки по этому закону недоступны.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.8,"rationale":"Закон прямо определяет круг иностранцев, которым разрешены стажировки, и регулирует условия их оплачиваемого труда, что относится к сфере занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v9","input_chars":96624,"truncated":false,"text_source":"documents","created_at":"2026-09-22T16:00:01Z","input_tokens":49715,"output_tokens":1125,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171166/13171167/dokument749803.pdf","source_kind":"rcl","revision":1,"text_sha256":"96b2a36ffb972cede864176f0bd61797487a2189acea3e6a32c4a293080369d1","source_checked_at":"2026-09-22T16:00:01Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('ac09e4b43838e3b29ce4aeeb55f4f30e1cc5fe32684cc52a17c8f187bf1e7bb8','{"triage":{"affects_foreigners":true,"confidence":0.95,"rationale":"Ustawa o stażach wprost obejmuje swoim zakresem cudzoziemców z UE, EOG oraz innych, którzy mogą korzystać ze swobody przepływu osób lub są objęci przepisami o powierzaniu pracy cudzoziemcom, a także zmienia zasady stażu dla obywateli Ukrainy w ramach ustawy o pomocy obywatelom Ukrainy."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":10562,"output_tokens":174,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('c839d68b9f7e7d36b6c14a475e751d2b84e40ac4969dd39114f9a317e0c027a1','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Закон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с перечисленными видами легального пребывания в Польше получают это право наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.","key_changes":["Право на услугу: ПМЖ, резидент ЕС, беженцы и доп. защита, граждане ЕС/ЕЭЗ/Швейцарии и члены семей","Включены разрешения по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust. 1, 186 ust. 1 pkt 3, научная виза, Brexit-соглашение","Карта побыту с отметкой ''dostęp do rynku pracy'' даёт право, кроме студентов, сезонных и краткосрочных работников","Объём: 20–240 часов в месяц (18–65 лет), 20–80 часов (13–18 лет); ставки 49–55 zł брутто в час","Заявление подаётся электронно; иностранец прилагает документ, дающий право на пребывание в Польше"],"affected_groups":["иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС","беженцы и лица с дополнительной защитой","граждане ЕС/ЕЭЗ/Швейцарии и члены их семей","обладатели карты побыту с отметкой ''dostęp do rynku pracy''","работники по внутрикорпоративному переводу и научные работники","граждане Великобритании по Brexit-соглашению"],"practical_impact":"Иностранец с инвалидностью, проживающий в Польше и имеющий соответствующее решение об уровне потребности в поддержке, может бесплатно получить личного ассистента; заявление подаётся только электронно с приложением документа о праве на пребывание.","effective_date":"Через 14 дней после опубликования, с исключениями: ст. 6 ust. 1 pkt 1 и часть ст. 8 — через 12 месяцев; ст. 6 ust. 1 pkt 2 и ст. 7 ust. 2–7 — через 14 месяцев; ст. 58–67 и ст. 99 — с первого дня месяца после 5 месяцев от опубликования.","confidence":0.85,"rationale":"Закон касается социальной поддержки и прямо перечисляет категории иностранцев, получающих право на услугу, но не затрагивает легализацию пребывания или работу.","changes_since_previous":["В перечень оснований добавлены разрешения по ст. 159 ust. 1 и ст. 186 ust. 1 pkt 3 ustawy o cudzoziemcach","Добавлены переходные ограничения максимума часов: 200 часов в 2028 г. и 220 часов в 2029 г.","Уточнены сроки рассмотрения заявлений: до 120 дней (до 31.12.2028), 90 дней, затем 60 дней","Детализирован поэтапный запуск: 90 баллов — через 12/16 месяцев от публикации, 85 — через 17/21, 80 — с 01.09.2028/01.01.2029","Для лиц 13–18 лет и проживающих в учреждениях круглосуточного ухода — заявления с 01.05.2029, право с 01.01.2030"]},"model":"claude-opus-5","prompt_version":"2026-09-v9","input_chars":154338,"truncated":false,"text_source":"pdf","created_at":"2026-09-22T16:01:14Z","input_tokens":77754,"output_tokens":1429,"cache_read_input_tokens":2652,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2","source_checked_at":"2026-09-22T16:01:14Z"}',NULL,NULL,NULL);
INSERT INTO "analysis_memo" VALUES('48d799a9349d69336bb88c4d5c29a9489f4cf53a51eb7dc7c7f43ba075cb0b5f','{"analysis":{"relevant":true,"score":4,"category":"social","summary":"Проект изменяет спецзакон о помощи гражданам Украины. Он отменяет ряд норм, дающих украинцам льготный доступ к социальным выплатам и медицинской помощи, а также к работе в научных институтах без конкурса. После этого украинцы пользовались бы этими правами на общих условиях, как другие иностранцы.","key_changes":["Отмена ряда статей спецзакона (в т.ч. ст. 26, 26a, 27b, 27c, 29, 32, 33, 37) о льготном доступе к соцвыплатам","По обоснованию, отменяется автоматический доступ к медпомощи NFZ для легально пребывающих украинцев","Отмена ст. 47–49: приём украинцев на работу в институты PAN и Łukasiewicz без конкурса, по заявлению","Повят будет финансировать только пребывание в приёмной семье лиц из ст. 27a (новая редакция ст. 27d)","Замена в тексте закона «w Ukrainie» на «na Ukrainie» (языковая правка)"],"affected_groups":["граждане Украины, пребывающие в Польше на основании спецзакона","украинцы, получающие социальные выплаты и медицинскую помощь по спецзакону","украинские учёные, трудоустраивающиеся в научные учреждения"],"practical_impact":"Украинцы со статусом по спецзакону утратили бы льготный доступ к части соцвыплат и медпомощи и могли бы получать их только на общих основаниях, например при наличии карты побыту, статуса беженца или страховки NFZ. Для работы в институтах PAN и Łukasiewicz потребовался бы обычный конкурс.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.75,"rationale":"Проект меняет спецзакон о помощи гражданам Украины (уровень 4), а основное содержание касается социальных выплат и медпомощи, отсюда категория social.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":19248,"truncated":false,"text_source":"pdf","created_at":"2026-09-25T03:08:29Z","input_tokens":10115,"output_tokens":1101,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1039/1039.pdf","source_kind":"print","revision":1,"text_sha256":"7a8ee05156b9bdcefe6bc193021025bfd9c53c6366467170baa828991ffa8cd9","source_checked_at":"2026-09-25T03:08:29Z"}',10,'1039','2026-09-25T03:08:29+00:00');
INSERT INTO "analysis_memo" VALUES('0b8634bb1a3c19e43e3b810ec8e4508720059112c08e1aaec598715745688722','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект ужесточает условия получения 800+ (świadczenie wychowawcze) для граждан Украины, находящихся в Польше по спецзакону. Выплата будет зависеть от работы или бизнеса в Польше и уплаты налогов; при невыполнении условий пособие приостанавливается.","key_changes":["Новое условие для 800+: трудоустройство или ведение działalności gospodarczej в Польше","Новое условие: исполнение налоговых обязательств перед государством","Исключение: законные освобождения, отсрочки, рассрочка или приостановление решения органа","Приостановление выплаты при выявлении отсутствия работы или неуплаты налогов","Возобновление выплаты с месяца, когда условия снова выполнены"],"affected_groups":["Граждане Украины с легальным пребыванием на основании art. 2 ust. 1 спецзакона","Украинские родители, получающие или подающие заявление на 800+"],"practical_impact":"Чтобы получать 800+ на ребёнка, гражданину Украины нужно будет работать или вести бизнес в Польше и не иметь налоговых задолженностей; иначе ZUS приостановит выплату. Новые условия впервые применяются к заявлениям, подаваемым с 1 февраля по 30 апреля 2025 г.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования; новые условия впервые применяются к заявлениям, подаваемым с 1 февраля 2025 г. по 30 апреля 2025 г.","confidence":0.9,"rationale":"Поправка к ustawa o pomocy obywatelom Ukrainy (закон о помощи гражданам Украины), связывающая доступ к 800+ с занятостью, относится по шкале к уровню 4 и напрямую затрагивает украинцев под временной защитой.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":7982,"truncated":false,"text_source":"pdf","created_at":"2026-09-25T03:08:29Z","input_tokens":4708,"output_tokens":673,"cache_read_input_tokens":0,"cache_creation_input_tokens":2652,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1040/1040.pdf","source_kind":"print","revision":1,"text_sha256":"346991616e45f3d862e55248ae507d523c88265ad987e0419165eb54a1009af7","source_checked_at":"2026-09-25T03:08:29Z"}',10,'1040','2026-09-25T03:08:29+00:00');
INSERT INTO "analysis_memo" VALUES('6a25be7efddb76263815da1d8934b17d60e33ea40cdcbe934d087e4eb8ab0d8c','{"triage":{"affects_foreigners":true,"confidence":0.75,"rationale":"Законопроект о судебных экспертах требует польское гражданство (или ЕС/EFTA/Швейцария) для получения статуса присяжного эксперта, а также содержит положения об идентификации иностранцев (документ, подтверждающий личность иностранца) в реестре, что напрямую затрагивает иностранцев, желающих выполнять эту функцию."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12093,"output_tokens":152,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12408900','2026-09-28T11:41:04+00:00');
INSERT INTO "analysis_memo" VALUES('1ca28423810a37685936d33799609691a60e4e03890add4bf9b14e9dd48b5140','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект вводит новую систему судебных экспертов (biegli sądowi): сертификация через Państwowa Komisja Certyfikacyjna и единый реестр. Иностранцев касается требование гражданства: экспертом может стать только гражданин Польши, ЕС, ЕАСТ/ЕЭЗ или Швейцарии, владеющий польским языком.","key_changes":["Судебным экспертом может быть только гражданин Польши, ЕС, ЕАСТ/ЕЭЗ или Швейцарии","Обязательно достаточное владение польским языком, возраст от 25 лет, 5 лет практики","Иностранные документы подаются с заверенным переводом на польский язык","Без PESEL в заявлении указывается паспорт или документ иностранца по ustawa o cudzoziemcach","Сертификат на 5 лет выдаёт Państwowa Komisja Certyfikacyjna, эксперт вносится в общенациональный реестр"],"affected_groups":["граждане третьих стран, желающие работать судебными экспертами в Польше","граждане ЕС/ЕАСТ/Швейцарии — кандидаты в судебные эксперты","действующие судебные эксперты"],"practical_impact":"Граждане стран вне ЕС/ЕАСТ/Швейцарии (например, Украины или Беларуси) не смогут получить сертификат судебного эксперта, даже при наличии квалификации. Граждане ЕС должны подтвердить знание польского языка и предоставить заверенные переводы документов.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 55–63 (реестр) — с 1 апреля 2027 г. и ст. 88–90 — с 1 октября 2026 г.","confidence":0.8,"rationale":"Общий закон о профессии судебного эксперта с конкретным аспектом для иностранцев — требованием гражданства Польши/ЕС/ЕАСТ/Швейцарии, поэтому косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":305859,"truncated":false,"text_source":"documents","created_at":"2026-09-28T11:48:49Z","input_tokens":150243,"output_tokens":1042,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408900/13196264/13196265/dokument770060.docm","source_kind":"rcl","revision":1,"text_sha256":"1356ca7516fc78b98838020f119582553ec383c6571febcb797990440caef1be","source_checked_at":"2026-09-28T11:48:49Z"}',10,'RCL/12408900','2026-09-28T11:48:49+00:00');
INSERT INTO "analysis_memo" VALUES('9513ced30289602e70c00a79e6616f283e50d4c2a010b5c76c6c6ce6f6e608a9','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Это ратификация международного соглашения о партнёрстве и сотрудничестве ЕС с Киргизией, касающегося торговли, борьбы с преступностью и общих рамок миграционного диалога, но, как прямо указано в обосновании, документ не изменяет польского законодательства и не касается напрямую физических лиц, включая иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12327,"output_tokens":148,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3139','2026-09-28T15:33:31+00:00');
INSERT INTO "analysis_memo" VALUES('7dc2122dc508fc2268c00425d178ea4bd7b0a258102497fd335b1f23cde6d941','{"triage":{"affects_foreigners":true,"confidence":0.55,"rationale":"Проект касается финансирования лечения ВИЧ для лиц без права на медицинское страхование, что может включать иностранцев, находящихся в Польше без страхования, хотя прямо о них не упоминается в приведённых фрагментах."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":4499,"output_tokens":111,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3143','2026-09-28T15:33:31+00:00');
INSERT INTO "analysis_memo" VALUES('fcd1d6cb54261efd1d4d3afe6aa2a6350defeb45ab4ec3a986a886059f570e24','{"triage":{"affects_foreigners":true,"confidence":0.75,"rationale":"Проект в основном касается организационных вопросов Straży Granicznej и сотрудничества с Frontex, но включает поправки к ustawie o cudzoziemcach (операции и интервенции по возвращению мигрантов), что напрямую затрагивает процедуры в отношении иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":13856,"output_tokens":129,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3146','2026-09-28T15:33:53+00:00');
INSERT INTO "analysis_memo" VALUES('14256896f1b9a16ff26644a5d8ba88f11d78344f2fb1610f0763be64cff6de82','{"triage":{"affects_foreigners":true,"confidence":0.75,"rationale":"Projekt dotyczy koordynacji systemów zabezpieczenia społecznego, poboru składek zdrowotnych z emerytur transferowanych z zagranicy oraz zwrotu kosztów transgranicznej opieki zdrowotnej w UE/EFTA/UK, co bezpośrednio dotyczy osób korzystających z tych świadczeń, w tym cudzoziemców i Polaków mieszkających za granicą."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":9548,"output_tokens":181,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3141','2026-09-28T15:33:53+00:00');
INSERT INTO "analysis_memo" VALUES('de38b0ec57105d6e1aafca380b73db45b949b4a566ed6070da07fd1e52fbf268','{"triage":{"affects_foreigners":false,"confidence":0.65,"rationale":"Это законопроект о ратификации рамочного соглашения ЕС-Узбекистан о партнёрстве, которое, согласно обоснованию, «не касается непосредственно физических или юридических лиц» и не меняет внутреннее польское законодательство, хотя содержит общие положения о сотрудничестве по миграции и реадмиссии на уровне ЕС."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12080,"output_tokens":501,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3140','2026-09-28T15:33:53+00:00');
INSERT INTO "analysis_memo" VALUES('b01bc3b166094237181b72138d5d90b0c6db00ed632fe36c6d26d6d5640fbb35','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию Расширенного соглашения о партнёрстве и сотрудничестве между ЕС и Узбекистаном. Соглашение в основном касается торговли и сотрудничества, но содержит положения о миграции, реадмиссии граждан без права пребывания и деловых поездках. Прямо польское право оно не меняет.","key_changes":["Узбекистан и страны ЕС обязуются без промедления принимать обратно своих граждан, не имеющих права на пребывание","Документы для возврата выдаются в течение 30 дней после запроса о реадмиссии","Предусмотрен диалог о легальной миграции, защите прав легальных мигрантов и интеграции","Стороны могут начать переговоры о соглашении об упрощении визового режима","Внутрикорпоративный перевод: пребывание до 3 лет; бизнес-визиты для создания компании — до 90 дней"],"affected_groups":["граждане Узбекистана в Польше","граждане Узбекистана без законного права на пребывание","сотрудники компаний, переводимые внутри корпорации","поставщики услуг по контракту из Узбекистана"],"practical_impact":"Для граждан Узбекистана, не имеющих законного права на пребывание в Польше, упрощается процедура возврата на родину (реадмиссии). Требования ustawa o cudzoziemcach (закон об иностранцах) к въезду, пребыванию и работе продолжают действовать; соглашение не даёт физическим лицам прав, на которые можно ссылаться напрямую.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения с миграционными и реадмиссионными положениями, не меняющего польское право напрямую, относится к косвенному влиянию (балл 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1199982,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":504067,"output_tokens":685,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3140/3140.pdf","source_kind":"print","revision":1,"text_sha256":"c9e3239a71f94f23614e5789a1164dce5b9300379487c172b974aeb046cf0215","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3140','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('877da56b50df00e2980adba3c00b49d5d9d9298b2eaed1df3fbd58f566fe158b','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Поправки к закону о медицинском страховании NFZ. Страховку получат выпускники медвузов на практическом обучении и слушатели курсов польского языка. Меняются правила взносов с пенсий из стран ЕС, EFTA и Великобритании, а также порядок возмещения расходов на лечение за границей.","key_changes":["Обязательное страхование в NFZ для слушателей курсов польского языка и подготовительных курсов, если у них нет другого основания","Страхование для выпускников медвузов (в т.ч. с обучением не на польском) на практическом обучении по art. 15p","Пенсионеры, закончившие работу в ЕС/EFTA/UK, обязаны сообщить об этом в ZUS/KRUS в течение 14 дней, иначе долг по взносам удержат из пенсии","NFZ сможет сам задним числом зарегистрировать члена семьи, застрахованного по ошибке в другом государстве ЕС","Новая процедура возмещения NFZ расходов на лечение в ЕС/EFTA/UK; к заявке можно приложить заключение зарубежного врача с присяжным переводом"],"affected_groups":["иностранцы на курсах польского языка и подготовительных курсах","выпускники медицинских факультетов, в т.ч. англоязычных программ","получатели пенсий из стран ЕС, EFTA и Великобритании, живущие в Польше","члены семей застрахованных в трансграничных ситуациях","пациенты, лечащиеся в других странах ЕС/EFTA/UK"],"practical_impact":"Слушатели курсов польского языка и выпускники медвузов на практике получат страховку NFZ через вуз, а получатели иностранных пенсий будут платить взнос на здравоохранение через банк и должны вовремя уведомлять ZUS об окончании работы за рубежом. Для людей без места жительства в Польше отделение NFZ определяется по последнему адресу в Польше или по месту нахождения плательщика, без выбора.","effective_date":"Через 14 дней после опубликования, кроме: art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.75,"rationale":"Законопроект меняет доступ к медицинскому страхованию NFZ и взносы для групп, среди которых много иностранцев (курсы польского, иностранные пенсии, трансграничные ситуации), что относится к социальной сфере.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":151007,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":78995,"output_tokens":1474,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf","source_kind":"print","revision":1,"text_sha256":"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3141','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('c846641f6d1e600153381c2bc29d8b11fd3d72a529370874c345796cd41ea0d1','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию нового соглашения о партнёрстве и сотрудничестве ЕС с Кыргызстаном, заменяющего договор 1995 года. Соглашение касается торговли, инвестиций, защиты географических указаний, а также сотрудничества в сфере миграции, реадмиссии и правовой помощи. Прямо права граждан Кыргызстана в Польше не меняет.","key_changes":["Кыргызстан обязуется принимать обратно своих граждан, не имеющих права находиться в странах ЕС, без дальнейших формальностей","Допускается использование европейского проездного документа для возврата нелегально пребывающих лиц","Стороны могут договориться о соглашении ЕС–Кыргызстан об упрощении визового режима и о реадмиссии","Внутрикорпоративные переводы: руководители и специалисты — до 3 лет, стажёры — до 1 года, при соблюдении национальных правил","Граждане Кыргызстана могут получать консульскую защиту в странах ЕС без его представительства"],"affected_groups":["граждане Кыргызстана в Польше и ЕС","граждане Кыргызстана без законных оснований для пребывания","сотрудники кыргызских компаний, переводимые внутри корпорации","инвесторы из Кыргызстана"],"practical_impact":"Для граждан Кыргызстана в Польше правила получения виз, разрешений на пребывание и работу не меняются: соглашение прямо указывает, что национальное законодательство о въезде, пребывании и работе продолжает действовать. Возможно упрощение возврата лиц без законного статуса в Кыргызстан.","effective_date":"Закон вступает в силу через 14 дней со дня опубликования; само соглашение — в первый день второго месяца после взаимного уведомления сторон о завершении внутренних процедур.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения, затрагивающего миграцию и реадмиссию лишь на уровне рамочного сотрудничества без изменения национальных правил пребывания, соответствует косвенному влиянию (оценка 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1268621,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":550072,"output_tokens":779,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3139/3139.pdf","source_kind":"print","revision":1,"text_sha256":"f95398d40b3ad92b97a13150325f6533e52d48eed4dc3c935c8b00a65d342a7f","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3139','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('2b462f967e1ee179a2d78482a09163adf2aeb203266f3249f2e3eaab1d37dafe','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект уточняет, кто оплачивает медицинские услуги в двух государственных программах: лечение ВИЧ для людей без медицинской страховки и лечение гепатита C у заключённых. Визиты и анализы в программе лечения ВИЧ для незастрахованных будут оплачиваться из госбюджета. Иностранцы прямо не упоминаются, но касается это и незастрахованных иностранцев.","key_changes":["Услуги, связанные с антиретровирусным лечением ВИЧ, для лиц без права на страховку NFZ оплачиваются из госбюджета (бюджет министра здравоохранения)","Цель — устранить практику, когда за визиты и анализы в программе лечения ВИЧ с незастрахованных брали плату","NFZ сможет финансировать не только лекарства, но и медицинские услуги в программе лечения гепатита C у заключённых","Средства NFZ на программы передаются на счета бюджетных учреждений в сроках и суммах, определяемых министром здравоохранения"],"affected_groups":["люди, живущие с ВИЧ, без медицинской страховки в Польше, в том числе иностранцы","заключённые с хроническим гепатитом C","медучреждения, реализующие программу лечения ВИЧ"],"practical_impact":"Незастрахованный иностранец с ВИЧ, находящийся в Польше, должен получать в рамках программы не только бесплатные лекарства, но и бесплатные визиты к врачу и анализы, без оплаты из собственного кармана.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.65,"rationale":"Законопроект не касается иностранцев как таковых, но улучшает доступ к лечению ВИЧ для всех незастрахованных, среди которых значительную часть составляют иностранцы, поэтому влияние косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":23123,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":14785,"output_tokens":1046,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3143/3143.pdf","source_kind":"print","revision":1,"text_sha256":"8bb9393c139e45c2aaf392d29025b78844821bb0d8aedc9feba2246a43f5b254","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3143','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('5eedd907f384ba51e7c5e1ac0d1e208fee9a970e8269c2a05d375af82ba3a9ba','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект адаптирует польское право к регламенту ЕС 2019/1896 о Frontex. Главным образом он касается Straż Graniczna (Пограничной службы) и её сотрудничества с агентством. Для иностранцев важно, что в ustawa o cudzoziemcach (закон об иностранцах) вводятся правила проведения в Польше операций Frontex по возвращению мигрантов.","key_changes":["В ustawa o cudzoziemcach добавлены понятия «операция по возвращению» и «интервенция по возвращению» (Frontex)","Komendant Główny SG сможет запрашивать у Frontex организацию операций по возвращению или соглашаться на них","Персонал Frontex и других стран ЕС сможет выполнять в Польше задачи по возвращению, включая применение оружия и мер принуждения","Сотрудников SG разрешат направлять в третьи страны как офицеров связи по возвращению (EURLO) для установления личности иностранцев","Frontex получит право регистрировать свои служебные автомобили как транспорт спецслужб"],"affected_groups":["иностранцы, обязанные покинуть Польшу (с решением о zobowiązanie do powrotu)","иностранцы без урегулированного статуса"],"practical_impact":"Процедуры и основания выдворения не меняются, но исполнять решения о возвращении в Польше смогут и команды Frontex, в том числе на совместных рейсах. Польские офицеры в третьих странах будут помогать подтверждать личность иностранцев и получать документы для их возвращения.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Законопроект в основном институциональный (Frontex, Straż Graniczna), но касается исполнения возвращений иностранцев, то есть иммиграционного контроля, поэтому это косвенное влияние с оценкой 2.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":118838,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":61448,"output_tokens":872,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf","source_kind":"print","revision":1,"text_sha256":"e4d525e776970059034fef2588e362ef0b3f7fa209c5cc7bdcce3efc3dbd753a","source_checked_at":"2026-09-28T15:56:31Z"}',10,'3146','2026-09-28T15:56:31+00:00');
INSERT INTO "analysis_memo" VALUES('95a10ff3ab8322dc1b16a86e14c5d9a2e92a0ecadbaf721748cbc98c77c2ce10','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила медстрахования NFZ и возмещения расходов на лечение в ЕС/EFTA/Великобритании. Он вводит обязанности для получателей польских и зарубежных пенсий и включает в медстрахование выпускников медицинских направлений на практическом обучении и слушателей курсов польского языка.","key_changes":["Отдельная процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)","К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Возврат за лекарство в ЕС/ЕЭЗ по польскому рецепту на возмещение, не только по трансграничному","Медстрахование для выпускников на практическом обучении (art. 15p) и слушателей подготовительных курсов польского языка","Сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK в течение 14 дней, иначе долг по взносам удержат из пенсии"],"affected_groups":["выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше","слушатели курсов польского языка и подготовительных курсов к учёбе на польском","получатели пенсий из ЕС/EFTA/UK, живущие в Польше","застрахованные в NFZ, лечащиеся в других странах ЕС/EFTA/UK","члены семей застрахованных в трансграничных ситуациях"],"practical_impact":"Выпускники-медики на практическом обучении и слушатели подготовительных курсов польского языка получают медстрахование, если не застрахованы по другому основанию. Лечение за границей проще согласовать с NFZ по заключению иностранного врача. Пенсионерам после окончания работы в ЕС/EFTA/UK нужно в течение 14 дней уведомить ZUS/KRUS.","effective_date":"Через 14 дней после опубликования; art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.8,"rationale":"Проект касается медстрахования NFZ и трансграничного лечения, в том числе групп, где много иностранцев (выпускники иноязычных медицинских программ, слушатели курсов польского языка), поэтому это социальная сфера, оценка 3.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":148783,"truncated":false,"text_source":"documents","created_at":"2026-09-28T15:56:32Z","input_tokens":76387,"output_tokens":1419,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412454/13215502/13215503/dokument797859.zip","source_kind":"rcl","revision":2,"text_sha256":"6f722062659c34910b5eef1ce1542166e5b8b7aafdcc48621ceae7deaf0e6f6b","source_checked_at":"2026-09-28T15:56:32Z"}',10,'RCL/12412454','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('00ab501419f20515388b8880dc6f206dbbc28bee071a566d358fce21c6102dd6','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Закон устанавливает, как Польша исполняет решения Европейского суда по правам человека (ЕСПЧ): кто отвечает за исполнение, как выплачивается компенсация и как соблюдаются временные меры суда. Норм об иностранцах в тексте нет, но закон касается и иностранцев, подавших жалобу в ЕСПЧ против Польши.","key_changes":["MSZ координирует исполнение решений ЕСПЧ, при министре создаётся межведомственный Zespół","Компенсация выплачивается по заверенному формуляру платежа, при его отсутствии сумма идёт в судебный депозит","Временную меру ЕСПЧ исполняют и тогда, когда о ней сообщил представитель заявителя, если документ достоверен","По временной мере орган прекращает или не начинает указанное судом действие и может изменить или отменить решение","Окончательное решение ЕСПЧ становится исполнительным документом (art. 777 KPC)"],"affected_groups":["заявители, подавшие жалобу в ЕСПЧ против Польши, в том числе иностранцы","лица, в делах которых ЕСПЧ назначил временную меру"],"practical_impact":"Заявителю, выигравшему дело в ЕСПЧ, нужно без промедления подать в MSZ заверенный формуляр платежа, иначе сумма попадёт в судебный депозит. Временные меры ЕСПЧ обязательны для органов власти, в том числе если о них сообщил представитель заявителя.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.6,"rationale":"Закон общий и процедурный, иностранцы в нём прямо не упоминаются, поэтому для них он маргинален, хотя механизм временных мер ЕСПЧ может затрагивать и их дела.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":46453,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":26181,"output_tokens":1181,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2271/attachment/2271_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"e22f0142ed0f6306ff7f712868af66cb47da2c50ad880759c7b83b7ebf15d8b9","source_checked_at":"2026-09-28T15:56:32Z"}',10,'2271','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('7aecd9bb5c73ce9649b1ba011ff3efd15f3b8fdd058527a3f20be5a75744222a','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Законопроект создаёт статус mediator sądowy (судебный медиатор) и электронный Krajowy Rejestr Mediatorów (национальный реестр медиаторов), вводит единые стандарты обучения. Иностранцы затронуты лишь как возможные кандидаты в медиаторы.","key_changes":["Вместо списков постоянных медиаторов вводится единый электронный Krajowy Rejestr Mediatorów","Без PESEL в заявлении указывается паспорт, документ путешественника или документ по ustawa o cudzoziemcach","Лица без польского гражданства прилагают подтверждение знания польского языка не ниже B2","Требования: 26 лет, высшее образование, базовое (40 ч) и специализированное обучение, несудимость","Учитывается зарубежное высшее образование, признанное в Польше; в реестре можно указать языки медиации"],"affected_groups":["иностранцы, желающие стать судебными медиаторами","иностранцы, работающие медиаторами по действующим спискам"],"practical_impact":"Иностранец без PESEL сможет подать заявление о внесении в реестр, указав паспорт или документ по ustawa o cudzoziemcach, но обязан подтвердить знание польского на уровне B2. Для большинства иностранцев ничего не меняется.","effective_date":"Закон вступает в силу 1 сентября 2027 г.","confidence":0.85,"rationale":"Иностранцы упоминаются лишь в контексте формальных требований к кандидатам в медиаторы, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":138006,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":71032,"output_tokens":581,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3008/3008.pdf","source_kind":"print","revision":2,"text_sha256":"05f8b358d8b13983313de7c36a3987d45a652f65878c2f5d5c8b123702bad1ab","source_checked_at":"2026-09-28T15:56:32Z"}',10,'3008','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('d79f11953db40f7520b4fbe37731ae4df6a51880df4add33462bf3c6a90c4d7b','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Закон вводит «umowa o wspólnym pożyciu» (договор о совместной жизни): это нотариальный договор для пар независимо от пола, дающий статус ближайшего лица. Заключить его могут и иностранцы, но права на пребывание в Польше он не даёт.","key_changes":["Договор заключается у нотариуса в Польше, при одновременном присутствии обеих сторон","В заверениях указываются гражданство, PESEL (если присвоен) и данные документа личности","Нельзя заключить договор, если человек уже состоит в браке или в зарубежном союзе, не признаваемом браком","По умолчанию действует раздельность имущества; можно выбрать общность или выравнивание достижений","Регистрация в urząd stanu cywilnego, opłata skarbowa 100 zł; возможны доверенности, доступ к медданным, завещания"],"affected_groups":["иностранцы, живущие в Польше в неформальных парах","пары одного пола, в том числе с участием иностранцев","иностранцы без PESEL"],"practical_impact":"Иностранец может заключить договор с партнёром у польского нотариуса по документу личности, даже без PESEL, и получить права по имуществу, медицинской информации и представительству. Если он состоит в зарубежном союзе, не признаваемом в Польше браком, заключить договор нельзя; легализации пребывания договор не даёт.","effective_date":"Закон вступает в силу в срок, определённый в отдельном законе «Przepisy wprowadzające ustawę o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu» (вводные положения).","confidence":0.8,"rationale":"Это общий гражданско-правовой закон, доступный иностранцам, с отдельными нормами о гражданстве, PESEL и зарубежных союзах, но без влияния на право пребывания, поэтому воздействие косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":24882,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":15787,"output_tokens":1129,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2110/attachment/2110_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"86421a120c0194a37f061d6829b176f10ad4c45d25b2c2ec92f6aa50793d1969","source_checked_at":"2026-09-28T15:56:32Z"}',10,'2110','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('204f450615c0c25a8368fe9b48a19d7f084abf838a287455f97f1d6b105b5c67','{"analysis":{"relevant":true,"score":3,"category":"legal_stay","summary":"Специальный закон об организации Всемирного скаутского Джамбори в Гданьске в 2027 году. Для иностранцев главное: участники освобождаются от консульского сбора за национальную и шенгенскую визу, а их заявления рассматриваются без лишней задержки. Остальные нормы касаются медицины, санитарии, строительства и безопасности.","key_changes":["Освобождение от консульского сбора за национальную визу и визу Шенген для участников Джамбори","Нужно приложить подтверждение регистрации участия или иной документ об участии","Рассмотрение «без излишней задержки», если консула уведомили не позднее чем за 6 недель до начала","Срок 6 недель не действует для глав государств, членов правительств, монархов и официальных делегаций","Волонтёры не из ЕС должны представить справки о несудимости из стран гражданства и проживания за 10 лет"],"affected_groups":["иностранные участники Всемирного скаутского Джамбори, нуждающиеся в визе","иностранные волонтёры, работающие с несовершеннолетними участниками","официальные иностранные делегации"],"practical_impact":"Иностранные участники Джамбори не платят консульский сбор за визу при наличии подтверждения регистрации и получают ускоренное рассмотрение при уведомлении консула за 6 недель. Волонтёры-иностранцы для работы с детьми обязаны собрать справки о несудимости из стран гражданства и проживания за последние 10 лет.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Закон содержит визовые льготы (сфера легализации въезда), но узкие и разовые — только для участников одного мероприятия, поэтому оценка средняя.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":27534,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":17389,"output_tokens":1155,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a","source_checked_at":"2026-09-28T15:56:32Z"}',10,'2846','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('eb33d25d3d43f7c55420fe8e7c5ef9b9baaa23db70ded1d5dd0bc78cdbe4671a','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет работу KRS (Krajowy Rejestr Sądowy, судебный реестр компаний и организаций): вся переписка с судом идёт через электронную систему и счёт организации, упрощается ликвидация «мёртвых» фирм. Иностранцев касается лишь уточнённое заявление о статусе cudzoziemca у покупателя долей и акций.","key_changes":["В заявке о покупке долей/акций указывается, является ли приобретатель cudzoziemcem по ustawa z 1920 r.","Если приобретатель — иностранец, заявляется, владеет ли компания недвижимостью в Польше","Для адреса регистрации фирмы нужно правовое основание на помещение, документ прилагается к заявке","Заявления и письма в реестровый суд — только через ИТ-систему и счёт организации","Пометка в KRS о несдаче финансовой отчётности; через год — роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — покупатели и учредители долей и акций польских компаний","иностранцы — владельцы и члены правления компаний, зарегистрированных в KRS"],"practical_impact":"При покупке долей или акций польской компании иностранцем в заявке в KRS нужно указать его статус и наличие у компании недвижимости в Польше. Для всех фирм, включая принадлежащие иностранцам, обязательны электронная переписка с судом и документ о праве на помещение по адресу регистрации.","effective_date":"Закон вступает в силу 1 октября 2027 г., за исключением положений о пометке о несдаче финансовой отчётности и связанных норм, которые вступают в силу 1 октября 2028 г.","confidence":0.8,"rationale":"Проект касается корпоративного реестра в целом, а иностранцы затронуты лишь уточнением декларации по закону о приобретении недвижимости иностранцами, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":188666,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":97076,"output_tokens":1085,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","source_kind":"print","revision":2,"text_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","source_checked_at":"2026-09-28T15:56:32Z"}',10,'3004','2026-09-28T15:56:32+00:00');
INSERT INTO "analysis_memo" VALUES('e33f74e61cdf519193215751dbfa66b4adb634cc7de23a06ef8ffc17addf40a8','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект приводит польское законодательство в соответствие с регламентом ЕС 2019/1896 о Frontex. Для иностранцев главное: в ustawa o cudzoziemcach (закон об иностранцах) появляется правовая база для операций и интервенций по возвращению (выдворению) при участии Frontex на территории Польши.","key_changes":["В ustawa o cudzoziemcach вводятся понятия «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС 2019/1896","Komendant Główny SG сможет запрашивать у Frontex операции возвращения и давать согласие на них в Польше","Персонал Frontex и погранслужб стран ЕС сможет выполнять задачи по возвращению в Польше, включая применение силы","Польских пограничников можно будет направлять офицерами по возвращению (EURLO) в третьи страны для установления личности иностранцев","Frontex получает право регистрировать свои служебные машины, которые приравнены к спецтранспорту"],"affected_groups":["иностранцы, обязанные покинуть Польшу по решению о возвращении","иностранцы на внешней границе ЕС","сотрудники Straży Granicznej"],"practical_impact":"Права и процедуры для иностранцев не меняются, но выдворение из Польши и контроль на внешней границе смогут проводиться с участием сотрудников Frontex и других стран ЕС, в том числе с применением силы по правилам регламента ЕС.","effective_date":"Через 14 дней со дня опубликования.","confidence":0.85,"rationale":"Проект касается исполнения возвращений и пограничного контроля, но не меняет основания легализации и права иностранцев, поэтому это косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":118838,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T16:14:59Z","input_tokens":61870,"output_tokens":1005,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf","source_kind":"print","revision":2,"text_sha256":"e4d525e776970059034fef2588e362ef0b3f7fa209c5cc7bdcce3efc3dbd753a","source_checked_at":"2026-09-28T16:14:59Z"}',10,'3146','2026-09-28T16:14:59+00:00');
INSERT INTO "analysis_memo" VALUES('da61bf6ec5df8c5f77f74e7fa19ae4880e7e3f6d755cc6926118495ca56a5756','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила opłata miejscowa и opłata uzdrowiskowa (местный и курортный сборы). Их будет платить каждый, кто хотя бы одну ночь проживает в гостинице, пансионате или санатории в таких местностях, а удерживать сбор будет объект размещения. Кроме того, растёт порог освобождения от PCC при продаже движимых вещей.","key_changes":["Сбор взимается за каждую ночь проживания в объекте размещения, независимо от цели поездки","Максимальные ставки: 5,00 zł и 5,50 zł (местный), 6,86 zł за ночь (курортный)","Освобождение при проживании более 29 ночей подряд в объектах одной гмины","Сбор удерживают объекты размещения (płatnik); они могут требовать предоплату за заявленные ночи","Лимит освобождения от PCC при продаже движимых вещей: с 1000 до 3000 zł"],"affected_groups":["иностранные туристы и гости","иностранцы, живущие в гостиницах и хостелах в курортных и туристических местностях","сотрудники дипломатических и консульских представительств, не являющиеся гражданами Польши"],"practical_impact":"При заселении в гостиницу или санаторий в местности со сбором иностранец, как и гражданин Польши, платит его объекту размещения, возможно авансом за заявленные ночи; при проживании более 29 ночей подряд сбор не взимается. Иностранцы специально не выделяются, кроме сохранённого освобождения для дипперсонала без постоянного места пребывания в Польше.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 3 и ст. 10 (изменения PCC), которые вступают в силу через 14 дней после опубликования.","confidence":0.8,"rationale":"Это общая реформа местных сборов и налогов, которая касается всех одинаково; иностранцы упомянуты только в связи с освобождением для дипперсонала, поэтому влияние маргинальное.","changes_since_previous":["Изменены максимальные ставки местного сбора: теперь до 5,00 zł и до 5,50 zł за ночь вместо указанных ранее 3,56 zł и 5,03 zł; курортный сбор остался до 6,86 zł","Из условий введения местного сбора исключён критерий благоприятных климатических условий; достаточно ландшафтных достоинств местности, критерии которых определит rozporządzenie Rady Ministrów","Рада гмины может дифференцировать ставки или вводить освобождения по месту жительства, возрасту, наличию Karta Dużej Rodziny, степени инвалидности, сезону и длительности пребывания","Для объектов размещения до конца 2029 г. разрешена подача ежемесячной информации о сборе в бумажном виде"]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":25964,"truncated":false,"text_source":"documents","created_at":"2026-09-28T16:14:59Z","input_tokens":16308,"output_tokens":1514,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206829/13206830/dokument796915.zip","source_kind":"rcl","revision":2,"text_sha256":"c2f429077b42f7e6a40a19d8dfd9157ac90fcc055b0f22523eb1ffdcb833dfc2","source_checked_at":"2026-09-28T16:14:59Z"}',10,'RCL/12410853','2026-09-28T16:14:59+00:00');
INSERT INTO "analysis_memo" VALUES('a80c32b84a2398d2a40a33a2da02ae05e1b351a7294a2a5007c66f54372e1965','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила медстрахования NFZ в трансграничных ситуациях ЕС/EFTA/Великобритании и порядок возмещения расходов на лечение за границей. Он также включает в медстрахование слушателей курсов польского языка и выпускников медицинских направлений на практическом обучении.","key_changes":["Новая процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)","К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Медстрахование для слушателей курсов польского языка и подготовительных курсов, если нет другого основания","Пенсионеры должны в течение 14 дней сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK, иначе долг удержат из пенсии","NFZ сможет сам зарегистрировать члена семьи в медстраховании, если по правилам координации он должен быть застрахован в Польше"],"affected_groups":["слушатели курсов польского языка и подготовительных курсов к учёбе на польском","выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше","получатели пенсий из ЕС/EFTA/UK, проживающие в Польше","члены семей застрахованных в трансграничных ситуациях","пациенты, лечащиеся в других странах ЕС/EFTA/UK"],"practical_impact":"Слушатели курсов польского языка и выпускники-медики на практике получают право на медстрахование NFZ, если у них нет другого основания, а пенсионеры с работой в ЕС/EFTA/UK должны в течение 14 дней уведомить пенсионный орган об её окончании. Возмещение расходов на лечение за границей получает единую процедуру; к заявлению можно приложить заключение зарубежного врача с присяжным переводом.","effective_date":"Через 14 дней после опубликования, кроме art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев, а также art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.85,"rationale":"Проект касается медстрахования NFZ и доступа к лечению, в том числе для слушателей языковых курсов и лиц в трансграничных ситуациях, что относится к социальной сфере (оценка 3).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":151007,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T17:19:34Z","input_tokens":79397,"output_tokens":1310,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3141/3141.pdf","source_kind":"print","revision":3,"text_sha256":"113c0c5c2684218532aecbd424c368a1387f7d38da08037118210464ea3724bf","source_checked_at":"2026-09-28T17:19:34Z"}',10,'3141','2026-09-28T17:19:34+00:00');
INSERT INTO "analysis_memo" VALUES('27452ec86925d6181d2b752deaac4d74879ff791f8d7419f88e904eda52c09e8','{"triage":{"affects_foreigners":false,"confidence":0.85,"rationale":"Проект касается банковского права, надзора за банками и финансовыми холдингами, требований к капиталу и оценке членов правления банков; упоминание гражданства и Straży Granicznej — лишь техническая деталь среди перечня требований, не создающая изменений в правах или процедурах для иностранцев как таковых."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":7326,"output_tokens":137,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12341804','2026-09-29T17:22:33+00:00');
INSERT INTO "analysis_memo" VALUES('014f1cb5b542853c1ccb3f0cf63e821a4b405c04a8964b15848b4261b350a3f8','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Законопроект касается системы рефинансирования лекарств, медицинских изделий и процедур в аптеках, упоминание граждан Украины и координации ЕС носит второстепенный технический характер и не меняет существенно положение иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":9090,"output_tokens":111,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12398102','2026-09-30T11:17:40+00:00');
INSERT INTO "analysis_memo" VALUES('0e5b8dd9afd55f3164e3bf6217d0a226579471ed037d42183c5a9f56dc5a946f','{"triage":{"affects_foreigners":true,"confidence":0.55,"rationale":"Это проект бюджета на 2027 год, который включает конкретные статьи расходов, касающиеся иностранцев (Urząd do Spraw Cudzoziemców, pomoc dla cudzoziemców, Karta Polaka, репатрианты), хотя это в основном финансовый документ, а не изменение прав, но затрагивает финансирование программ для иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":12955,"output_tokens":157,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/32733/2026','2026-09-30T11:17:40+00:00');
INSERT INTO "analysis_memo" VALUES('354b140a3974c9fcac4670e7f7b4440deef319746773ce49a5d274d693d7c7fd','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект полностью перестраивает правила рефундации лекарств и медизделий за счёт NFZ, вводит новые ИТ‑системы и упрощённые процедуры. Это может улучшить доступ к дорогим и редким лекарствам для всех застрахованных, в т.ч. иностранцев, и меняет данные, которые указываются в рецептах и заявках на возмещение.","key_changes":["Новые процедуры и ИТ‑системы для рефундации и мониторинга программ лековых (SOLR, SOID, System Monitorowania Programów Lekowych, SWDPL)","Подробная регламентация импортa целевого и его рефундации, в т.ч. по заявлению пациента с PESEL или с паспортом, если PESEL нет","Отдельный учёт пациентов с правами по координации ЕС: личный идентификационный номер и данные иностранной институции на рецептах","Расширение и упорядочение рефундации редких («сиротских») лекарств, с новой многофакторной оценкой","Уточнение данных в рецептах и отчётности аптек (коды болезней ICD‑10, номера документов, коды для координации ЕС и пр.)"],"affected_groups":["Все застрахованные пациенты NFZ, включая иностранцев","Иностранцы без номера PESEL, подающие заявки на индивидуальную рефундацию импортируемых лекарств/питания","Пациенты, имеющие право на лечение по правилам координации ЕС (EHIC, S1 и др.)","Аптеки и врачи, выписывающие рецепты иностранцам"],"practical_impact":"В повседневности у иностранцев с правом на NFZ изменится форма рецептов и заявлений: чаще потребуется указывать PESEL либо данные паспорта/личный номер по координации ЕС. Потенциально возрастает доступность дорогостоящих и редких лекарств за счёт упрощённых и быстрее проводимых процедур рефундации.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением указанных статей, которые начнут действовать: через 14 дней, через 6 месяцев от дня оглашения, либо с 1 апреля 2027 г., 1 июля 2027 г. и 1 января 2028 г.","confidence":0.88,"rationale":"Акт комплексно меняет правила рефундации и доступа к лекарствам в системе NFZ, что прямо затрагивает и иностранцев‑пациентов, но не меняет специальных иммиграционных режимов, поэтому это социальная сфера средней важности.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":495380,"truncated":false,"text_source":"documents","created_at":"2026-09-30T11:32:33Z","input_tokens":154731,"output_tokens":1760,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129955/13129956/dokument782506.zip","source_kind":"rcl","revision":1,"text_sha256":"524157fa25a212119ccdf0eaa03ac7361481e0897a566f90548b9b3a13c50ed6","law_sha256":"ba40ef050ccbcbe4812e32bd7981f599b3c5ccf103eeb19131577128dc57c845","source_checked_at":"2026-09-30T11:32:33Z"}',10,'RCL/12398102','2026-09-30T11:32:33+00:00');
INSERT INTO "analysis_memo" VALUES('22f3e42631fcb9a27a0e8fce717c9dae7262d1fa44cfa30e27d0be54c68ea2fe','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается изменения порогов налогообложения PIT и программы сотрудничества с крупными налогоплательщиками CIT, не затрагивая специфических положений о пребывании, работе или правах иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":6326,"output_tokens":104,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3156','2026-09-30T12:58:27+00:00');
INSERT INTO "analysis_memo" VALUES('ad3cc402417e258c8d78bf2ae82564d853c67dfb04b6d7f2a0b3f408f4c6f1e2','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект государственного бюджета Польши на 2027 год: доходы, расходы, дефицит и распределение средств по ведомствам. Иностранцы упоминаются лишь косвенно — в строках финансирования UdSC, помощи иностранцам и Karta Polaka; новых правил для них закон не вводит.","key_changes":["Доходы бюджета — 696,4 млрд зл., расходы — 977,6 млрд зл., дефицит не более 281,2 млрд зл.","На Urząd do Spraw Cudzoziemców (UdSC) запланировано около 108 млн зл.","На помощь иностранцам (раздел 85231) — около 175 млн зл. в MSWiA и около 33 млн зл. у воевод","Резервы: 55 млн зл. на задачи по ustawa o Karcie Polaka и 70,2 млн зл. на помощь репатриантам","1 млрд зл. перечисляется в Fundusz Pomocy (помощь Украине и её гражданам)"],"affected_groups":["получатели социальной помощи для иностранцев (беженцы, лица с защитой, толерированным пребыванием)","обладатели Karta Polaka","репатрианты","граждане Украины"],"practical_impact":"Бюджет не меняет правил легализации, работы или получения пособий для иностранцев; он лишь определяет объём финансирования ведомств и программ, с которыми они имеют дело.","effective_date":"Закон вступает в силу 1 января 2027 года.","confidence":0.8,"rationale":"Это общий бюджетный закон, в котором иностранцы затронуты только через строки финансирования UdSC, помощи иностранцам и Karta Polaka, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1482496,"truncated":true,"text_source":"pdf","created_at":"2026-09-30T22:41:33Z","input_tokens":815438,"output_tokens":634,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-32733-2026/$file/10-RPW-32733-2026.pdf","source_kind":"print","revision":1,"text_sha256":"e6e53f93843e3fee083b8b4a247f9ee8b622136bae33dbcfb44951e9cc3d148b","law_sha256":"ad2ecc79e07e5b233fd271a5c20286a8e2b8f818f5bcdc9d3e061e8cf4a6b0d5","source_checked_at":"2026-09-30T22:41:33Z"}',10,'3150','2026-09-30T22:41:33+00:00');
INSERT INTO "analysis_memo" VALUES('6f2b2b2282484a9d856652a789baffbf174ddf0fa61dd1ae33989c522ed2f490','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект государственного бюджета Польши на 2027 год: доходы, расходы, дефицит и распределение средств по ведомствам. Новых правил для иностранцев закон не вводит — они затронуты лишь косвенно через финансирование UdSC, помощи иностранцам, Karta Polaka и репатриации.","key_changes":["Доходы бюджета — 696,4 млрд зл., расходы — 977,6 млрд зл., дефицит не более 281,2 млрд зл.","На Urząd do Spraw Cudzoziemców (UdSC) запланировано около 108,1 млн зл.","Помощь иностранцам (раздел 85231): около 175,2 млн зл. в MSWiA и около 33 млн зл. у воевод","Резервы: 55 млн зл. на задачи по ustawa o Karcie Polaka и 70,2 млн зл. на помощь репатриантам","1 млрд зл. перечисляется в Fundusz Pomocy; 125 млн зл. — на строительство и модернизацию пограничных переходов"],"affected_groups":["лица, обращающиеся в UdSC","иностранцы, получающие социальную помощь (статус беженца, дополнительная защита, толерированное пребывание, жертвы торговли людьми)","владельцы Karty Polaka","репатрианты"],"practical_impact":"Прямых изменений в правилах пребывания, работы или выплат для иностранцев нет; бюджет лишь определяет объём финансирования ведомств и программ, с которыми они имеют дело.","effective_date":"Закон вступает в силу 1 января 2027 г.","confidence":0.8,"rationale":"Бюджетный закон не меняет правовой статус иностранцев, а лишь упоминает статьи расходов на UdSC, помощь иностранцам и Karta Polaka, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1486063,"truncated":false,"text_source":"pdf","created_at":"2026-09-30T23:02:33Z","input_tokens":859755,"output_tokens":681,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3150/3150-ustawa%20i%20za%C5%82%C4%85czniki%20do%20ustawy.pdf","source_kind":"print","revision":2,"text_sha256":"b08a12f8480a1d44f3caea9f9368f76fb6e0fc7b12743f659880de25e65b948a","law_sha256":"c2134ccc99f5138a749d2764233d4203940e9d1d141f202d69478566f89a2363","source_checked_at":"2026-09-30T23:02:33Z"}',10,'3150','2026-09-30T23:02:33+00:00');
INSERT INTO "analysis_memo" VALUES('3f6c8ce85ad77fc4e31c6d79b43b7350bd67deddbdc7d288c254da285bcbb268','{"triage":{"affects_foreigners":true,"confidence":0.6,"rationale":"Законопроект об инвестиционной поддержке затрагивает в том числе поправку к закону о приобретении недвижимости иностранцами (uchyla się art. 3a), что напрямую касается прав иностранцев, хотя основная часть проекта посвящена экономическим вопросам и налоговым льготам для инвесторов."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":5756,"output_tokens":140,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3160','2026-10-01T18:58:15+00:00');
INSERT INTO "analysis_memo" VALUES('098277dd2b8c5de79ff2043ebd9608696b7f2d81f9d912e71650e8f970c57b3e','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Законопроект касается правил найма и оплаты труда медицинского персонала и равного обращения с пациентами независимо от гражданства и национальности, но не вводит специальных изменений для иностранцев в части их пребывания, виз, работы или гражданства - упоминание обывательства лишь как один из признаков недискриминации."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":10342,"output_tokens":138,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3157','2026-10-01T18:58:15+00:00');
INSERT INTO "analysis_memo" VALUES('50fc099f86c26307376ef3dbb04c4bce363326e9e96744bbf0dd02c676127d21','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект реформирует систему налоговых льгот для новых инвестиций (Polska Strefa Inwestycji), упрощая правила и продлевая срок льгот. Одновременно отменяется одна из статей закона о приобретении недвижимости иностранцами, что меняет правила таких покупок.","key_changes":["Отменяется ст. 3a закона о покупке недвижимости иностранцами.","Упрощаются и расширяются налоговые льготы PIT/CIT для DoW.","Срок действия decyzja o wsparciu увеличивается до 15–20 лет.","Вводится электронная платформа ePSI для подачи заявлений онлайн.","Запускается механизм обязательного заключения Szef KAS по крупным льготам."],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранные предприниматели и инвесторы, получающие decyzja o wsparciu в PSI","иностранные владельцы и совладельцы польских компаний, пользующихся льготами PIT/CIT"],"practical_impact":"Иностранцам, планирующим покупку недвижимости, нужно будет ориентироваться на новые правила вместо отменённой ст. 3a. Иностранные инвесторы с бизнесом в Польше смогут иначе планировать налоговые льготы и сроки проектов в системе PSI.","effective_date":"Основные положения вступают в силу 1 января 2027 г.; нормы об ePSI и части процедур — с 1 января 2029 г.; изменения закона о покупке недвижимости иностранцами и отмена SSE — с 31 декабря 2027 г.","confidence":0.86,"rationale":"Projekt bezpośrednio zmienia ustawę o nabywaniu nieruchomości przez cudzoziemców oraz istotnie modyfikuje podatkowe i inwestycyjne warunki dla inwestorów (w tym zagranicznych), co wpływa na sferę mieszkaniową i ekonomiczną cudzoziemców.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":213997,"truncated":false,"text_source":"pdf","created_at":"2026-10-01T19:41:36Z","input_tokens":70069,"output_tokens":2224,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf","source_kind":"print","revision":1,"text_sha256":"4feff41a210c26678e4711a52a917ad9f8909cb8cb69d394d92d4c275a6e7513","law_sha256":"e257300fab0b2458adf6b8fa43994e7b37f61f4ae7fb8202bd90c6cc97dbfdc0","source_checked_at":"2026-10-01T19:41:36Z"}',10,'3160','2026-10-01T19:41:36+00:00');
INSERT INTO "analysis_memo" VALUES('dda9379b84f662c9d4ff390a99760a9ca0a5d5960b53843a75a10933c39a643d','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект ужесточает правила найма и оплаты труда медперсонала по контрактам с NFZ и усиливает контроль NFZ. Вводится прямое право пациента на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.","key_changes":["Лимит общего рабочего времени медиков и потолки почасовой/месячной оплаты по контрактам с NFZ","Запрет привязки зарплаты медиков к проценту от контракта NFZ, жёсткие условия договоров","Сокращение схем через компании/спółki: заказы в основном напрямую физлицам‑медикам","NFZ получает расширенный доступ к меддокументации и документам о занятости, вводятся штрафы","В законе о правах пациента закреплён запрет дискриминации, в т.ч. по гражданству и национальности"],"affected_groups":["иностранцы, пользующиеся медицинской помощью в Польше (NFZ и частной)","иностранные врачи, медсёстры, физиотерапевты и др., работающие в Польше по контрактам с NFZ","иностранные пациенты, жалующиеся РПП на неравное обращение"],"practical_impact":"Иностранные пациенты получают прямую законную защиту от худшего обращения или отказа в помощи из‑за гражданства/национальности, проще ссылаться на это в жалобе. Иностранным медикам придётся подстраивать графики и зарплатные условия под новые лимиты времени работы и оплаты у всех работодателей.","effective_date":"Закон вступает в силу по истечении месяца со дня его опубликования.","confidence":0.93,"rationale":"Проект системно меняет условия работы медиков и вводит прямой запрет дискриминации пациентов по гражданству и национальности, что затрагивает как иностранных пациентов, так и иностранных медработников, поэтому значимость для иностранцев средняя в социальной сфере.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":182345,"truncated":false,"text_source":"pdf","created_at":"2026-10-01T19:41:36Z","input_tokens":57664,"output_tokens":1424,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf","source_kind":"print","revision":1,"text_sha256":"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06","law_sha256":"91f20470de90c8ae40b69032937a961b66736ee658335374ed0715585d2d7093","source_checked_at":"2026-10-01T19:41:36Z"}',10,'3157','2026-10-01T19:41:36+00:00');
INSERT INTO "analysis_memo" VALUES('1b72456a9a4141ca3aac0dc3ecaefe87365bfaea2c20dee48c06570481cf48cd','{"number":"","title":"Do druku nr 3039 - ocena skutków regulacji","source_kind":"impact_assessment","source_url":"","digest":{"summary":"Документ описывает, что проект расширяет поддержку для бенефициаров временной защиты со статusem UKR (около 8,5 тыс. людей в оśrodkach zbiorowego zakwaterowania и 176 тыс. вне них) и может стоить сектору финансов общественных свыше 1,2 млрд зł в год. Эксперты указывают на риск завышения/неправильной оценки прав на льготы (в т.ч. медуслуги по одному лишь заявлению), спорные критерии «групп уязвимых» и возможное несоответствие нормам ЕС по zamówienia publiczne при передаче управления центрами без конкурса.","points":["Проект охватывает 8 544 жителей OZZ и 176 000 уязвимых лиц вне центров","Месячный koszt по расчётам MRPiPS – 18,6 млн зł плюс 85,36 млн зł на медпомощь","Годовой совокупный koszt может превысить 1,247 млрд зł, а не 223 млн зł","Есть риск дискриминации: проект отдельно защищает только «матерей-одиночек», а не отцов","Самодекларация для доступа к медуслугам и отсутствие документов могут вести к злоупотреблениям","Передача OZZ НПО и профсоюзам без конкурса может противоречить dyrektywa 2014/24/UE","Проект может восприниматься как дающий преференции бенефициарам ochrony czasowej над поляками"],"supports":null,"affects_foreigners":true,"confidence":0.9},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","created_at":"2026-10-01T20:23:30Z","input_tokens":24182,"output_tokens":878,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3039','2026-10-01T20:23:30+00:00');
INSERT INTO "analysis_memo" VALUES('supplement-delivery:c78209f7ba82db79713ab956008399647a24febed16ce82477e7c638bba7c3af','{"number":"","title":"Do druku nr 3039 - ocena skutków regulacji","source_kind":"impact_assessment","source_url":"","digest":{"summary":"Документ описывает, что проект расширяет поддержку для бенефициаров временной защиты со статusem UKR (около 8,5 тыс. людей в оśrodkach zbiorowego zakwaterowania и 176 тыс. вне них) и может стоить сектору финансов общественных свыше 1,2 млрд зł в год. Эксперты указывают на риск завышения/неправильной оценки прав на льготы (в т.ч. медуслуги по одному лишь заявлению), спорные критерии «групп уязвимых» и возможное несоответствие нормам ЕС по zamówienia publiczne при передаче управления центрами без конкурса.","points":["Проект охватывает 8 544 жителей OZZ и 176 000 уязвимых лиц вне центров","Месячный koszt по расчётам MRPiPS – 18,6 млн зł плюс 85,36 млн зł на медпомощь","Годовой совокупный koszt может превысить 1,247 млрд зł, а не 223 млн зł","Есть риск дискриминации: проект отдельно защищает только «матерей-одиночек», а не отцов","Самодекларация для доступа к медуслугам и отсутствие документов могут вести к злоупотреблениям","Передача OZZ НПО и профсоюзам без конкурса может противоречить dyrektywa 2014/24/UE","Проект может восприниматься как дающий преференции бенефициарам ochrony czasowej над поляками"],"supports":null,"affects_foreigners":true,"confidence":0.9},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","created_at":"2026-10-01T20:23:30Z","input_tokens":24182,"output_tokens":878,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3039','2026-10-01T20:28:27+00:00');
INSERT INTO "analysis_memo" VALUES('6551e0976b239592373cdd90b1d5a32a872b072a4804be12ff5672218fc1da68','{"triage":{"affects_foreigners":true,"confidence":0.85,"rationale":"Проект вводит систему санкционных ограничительных мер, включая внесение иностранцев в список лиц, чьё пребывание в Польше нежелательно, отказ во въезде и пребывании, а также изменения в законе о чужеземцах, что напрямую затрагивает права и процедуры в отношении иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":13583,"output_tokens":138,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12399355','2026-10-02T14:33:38+00:00');
INSERT INTO "analysis_memo" VALUES('6c85c7cb78c4684d7847e9bf125348613c46b5045367e393c8e2e5da8e756764','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается защиты несовершеннолетних от порнографического контента в интернете и обязанностей поставщиков услуг, не затрагивая правового статуса, пребывания или прав иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":6547,"output_tokens":99,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12394953','2026-10-02T14:33:38+00:00');
INSERT INTO "analysis_memo" VALUES('0bf4dc9d26336722a916faec399eb5f014f5e61c711751e693bb1263bd67ce90','{"triage":{"affects_foreigners":false,"confidence":0.95,"rationale":"Законопроект касается изменений в законодательстве об возобновляемых источниках энергии (ОЗЕ), биометане и системе аукционов для производителей энергии, и не затрагивает вопросы пребывания, работы или прав иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_tokens":6958,"output_tokens":113,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12405700','2026-10-02T14:33:41+00:00');
INSERT INTO "analysis_memo" VALUES('9114565e5857f4faf8d58380d97e113b2563c24e0967c7a2606618762f714426','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит общую систему санкций в Польше и национальный санкционный список. Для иностранцев: попадание в этот список автоматически ведёт к признанию пребывания нежелательным и запрету въезда, с возможными исключениями по решению UdSC.","key_changes":["Создаётся единый национальный санкционный список лиц и компаний","Для лиц из списка можно вводить запрет въезда и пребывания в Польше","В \"ustawa o cudzoziemcach\" добавляется новая причина внесения в реестр нежелательных иностранцев","Szef UdSC получает полномочия применять и смягчать санкции по въезду/пребыванию","Для работников фирм под санкциями вводится защита зарплат через FGŚP"],"affected_groups":["иностранцы, внесённые в национальный санкционный список","граждане ЕС и члены их семей, на которых распространяются санкции","иностранные работники компаний, чьи активы заморожены","иностранные предприниматели, работающие с государствами под санкциями"],"practical_impact":"Если иностранец попадёт в польский санкционный список, его данные автоматически вносятся в реестр лиц с нежелательным пребыванием, что блокирует выдачу виз и разрешений и может повлечь отказ во въезде. При этом UdSC сможет в отдельных случаях дать исключение из запрета на въезд/пребывание.","effective_date":"Уступает в силу через 30 дней со дня опубликования, за исключением art. 73, который вступает в силу через 6 месяцев со дня опубликования.","confidence":0.89,"rationale":"Проект комплексно регулирует санкции и прямо меняет \"ustawa o cudzoziemcach\", добавляя новые основания для запрета въезда и пребывания и полномочия UdSC, что существенно влияет на правовой статус иностранцев (категория legal_stay, значимость 5).","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":372343,"truncated":false,"text_source":"documents","created_at":"2026-10-02T14:56:36Z","input_tokens":122174,"output_tokens":1131,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12399355/13139730/13139731/dokument790400.zip","source_kind":"rcl","revision":1,"text_sha256":"3d562527af94da07b7b1946ed4fab8c29d6e1552cdbe8fc618cf4ea4799d3ae3","law_sha256":"5109dc4580dc43d8ce730232ab10e106d20ef8e88d779125a2d919e46bac5402","source_checked_at":"2026-10-02T14:56:36Z"}',10,'RCL/12399355','2026-10-02T14:56:36+00:00');
INSERT INTO "analysis_memo" VALUES('59134925bcefe08004293633dcf275c60c38e4caa239dfda27484f47aa0dc70f','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект полностью перестраивает систему регистрации судов и реестра, вводит электронный реестр и сервис на английском. Важное для иностранцев: расширяются правила временного признания дипломов моряков из третьих стран и допуска их к работе на судах под польским флагом до 3 месяцев.","key_changes":["Моряки с документами из третьих стран могут получить признание диплома максимум на 3 месяца","Признание документов стран не из списка ЕС/KE – только если в KE подан запрос о признании этой страны","Моряки с поданным заявлением на признание диплома могут до 3 мес. работать на судах под польской флагом","И то, и другое допускается лишь после проверки подлинности иностранного документа квалификации","За выдачу подтверждения подачи заявления на признание взимается 30 PLN"],"affected_groups":["иностранные моряки с дипломами/свидетельствами третьих стран","иностранные члены экипажей, нанимающиеся на суда под польским флагом","иностранные судовладельцы из państw UE/EFTA, регистрирующие суда в польском реестре"],"practical_impact":"Иностранец‑моряк с дипломом из третьей страны сможет быстрее выйти в рейс на судне под польским флагом: до 3 месяцев на основании временного признания или подтверждения подачи заявления. Нужно пройти проверку подлинности документа и оплатить 30 PLN за подтверждение.","effective_date":"Изменения по признанию документов квалификационных (art. 6 pkt 1–3, 5–7, 10) вступают в силу через 14 дней со дня официального опубликования закона.","confidence":0.86,"rationale":"Проект прямо изменяет правила признания иностранных морских дипломов и допуска иностранных моряков к работе на судах под польским флагом, что существенно для занятости (категория „employment”, важность 4).","changes_since_previous":["Уточнено, что для документов из стран, не признанных Еврокомиссией, временное признание возможно только после подачи Польшей официального wniosku do KE о признании этой страны (новый ust. 6 art. 67).","Чётко разделены два механизма: краткосрочное признание зарубежного документа (до 3 мес.) и допуск к работе по одному лишь подтверждению подачи заявления (также до 3 мес., ust. 7–8).","В тексте подробно прописано, что и временное признание, и подтверждение подачи заявления выдаются только после позитивной проверки подлинности иностранного документа квалификации.","Сохранена, но теперь явно указана в załączniku фиксированная плата 30 PLN за подтверждение подачи wniosku о признании документа."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":288205,"truncated":false,"text_source":"documents","created_at":"2026-10-02T14:56:37Z","input_tokens":97196,"output_tokens":1855,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402353/13157968/13157969/dokument800294.zip","source_kind":"rcl","revision":2,"text_sha256":"f80b38830cd42ba5dcec1207547dea96d3a21b7ebd28b1a2dac0a251aea614cb","law_sha256":"9905bda2732b2835f7398323ab30026ea480ae68a1f1ab65d544e9a5f1c1d2ab","source_checked_at":"2026-10-02T14:56:37Z"}',10,'RCL/12402353','2026-10-02T14:56:37+00:00');
INSERT INTO "analysis_memo" VALUES('60b2f4ede8061596e9c98fbde9f6073cf5d5a0b08e4e7161c11e7c3f656f763c','{"triage":{"affects_foreigners":false,"confidence":0.85,"rationale":"Законопроект касается изменений в системе противодействия отмыванию денег и финансированию терроризма, доступа к реестру бенефициаров и санкционных мер против ОМУ; упоминание воевод, консулов и иностранцев носит технический характер (доступ к реестру для целей оценки риска при визовых процедурах) и не меняет напрямую права или обязанности иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":13795,"output_tokens":160,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/32532/2026','2026-10-03T14:00:52+00:00');
INSERT INTO "analysis_memo" VALUES('1fef763f93b8e7bb261f458049a8d2d243c257fef63f9489b88beb5bb90c666c','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается технических изменений в системе социальной защиты работников энергетического сектора и буроугольной отрасли Польши (мониторинг занятости и финансирование дотаций ZUS) и не затрагивает права, обязанности или процедуры, касающиеся иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":15618,"output_tokens":126,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/31567/2026','2026-10-03T14:30:05+00:00');
INSERT INTO "analysis_memo" VALUES('c4621201a44490a4ddf11eaa1a4631b0d1dca917167e712cc989aa07515c6ac5','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект реформирует систему налоговых льгот для новых инвестиций (Polska Strefa Inwestycji) и одновременно отменяет ст. 3a в законе о покупке недвижимости иностранцами. Это немного меняет правила приобретения недвижимости для нерезидентов.","key_changes":["Отменяется ст. 3a закона от 24.03.1920 о приобретении недвижимости иностранцами."],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранные инвесторы, планирующие покупку земли или объектов в Польше"],"practical_impact":"Правила получения разрешений на покупку недвижимости иностранцами изменятся из‑за отмены ст. 3a: часть нынешних исключений или условий может исчезнуть или измениться. Перед сделкой нужно будет сверяться с обновлённой версией закона и, при необходимости, получать новое разрешение МВД.","effective_date":"Для изменений в законе о приобретении недвижимости иностранцами (art. 2): с 31 декабря 2027 г.","confidence":0.74,"rationale":"Проект прямо изменяет ustawę o nabywaniu nieruchomości przez cudzoziemców, влияя на условия покупки недвижимости иностранцами, но не затрагивает правила легализации пребывания, поэтому значение среднее и категория – косвенное воздействие.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":213997,"truncated":false,"text_source":"pdf","created_at":"2026-10-05T21:29:37Z","input_tokens":70387,"output_tokens":1412,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf","source_kind":"print","revision":2,"text_sha256":"text-v2:82e96f6568b7893f7cf0cf0474d26b5fb441d49c2642665ac71cdf6e3faed013","law_sha256":"law-v2:216077303ec00b1e1d64dfc9c53aa3df3621b86744306112a0020dafa93b77f2","source_checked_at":"2026-10-05T21:29:37Z"}',10,'3160','2026-10-05T21:29:37+00:00');
INSERT INTO "analysis_memo" VALUES('b1cd6b34f5ff7162e2dfda86019a9e622b82d913a13f8ec5add5d2442ecbc446','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект внедряет в польское право новую категорию записей в SIS – «информационные записи» о гражданах третьих стран по запросу Europol и описывает, какие польские службы их вносят и используют. Это касается в первую очередь лиц, подозреваемых в терроризме и тяжкой преступности, а не обычных иностранцев.","key_changes":["Вводится понятие «впис информационный» для граждан третьих стран по ст. 37a регламента 2018/1862","Определён перечень польских служб, которые могут вносить такие записи в SIS","Расписана процедура проверки и анализа запросов Europol перед внесением записи","Расширён круг органов с доступом к данным этих записей и обязанностью уведомлять biuro SIRENE","Prezes UODO назначен ответственным за годовые отчёты по правам субъектов данных в SIS/VIS"],"affected_groups":["граждане третьих стран, попавшие под подозрение в терроризме или тяжких преступлениях","иностранцы, о которых уже есть или могут быть записи в SIS","лица, обжалывающие обработку своих данных в SIS/VIS"],"practical_impact":"Для иностранцев, попавших в поле зрения Europol, данные могут быть внесены в SIS как отдельная «информационная запись» и будут быстрее доступны польским службам. Для большинства иностранных жителей и заявителей на визу или ВНЖ прямых изменений процедур не предусмотрено, но проверки по SIS фактически усилятся для лиц из группы риска.","effective_date":"Закон вступает в силу в день, указанный в решении Европейской комиссии, в соответствии со ст. 79 ч. 7 регламента 2018/1862, за исключением art. 1 pkt 8, который вступает в силу через 14 дней после опубликования.","confidence":0.9,"rationale":"Регулируется использование SIS в отношении граждан третьих стран (записи по запросу Europol и доступ служб), что влияет на пограничный и полицейский контроль, но не меняет правил проживания или труда; это косвенное, но специфически «иностранческое» регулирование.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":65799,"truncated":false,"text_source":"documents","created_at":"2026-10-06T07:59:44Z","input_tokens":24285,"output_tokens":1240,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223883/13223887/dokument800703.pdf","source_kind":"rcl","revision":2,"text_sha256":"text-v2:8dcd45e2466a52456e763029377734c15c461118b6b59fff3aaa6223e2e8dd15","law_sha256":"law-v2:768ce2ff5d13f7192754631dc47a7932793186deb01ed174a8151c88a66a65d4","source_checked_at":"2026-10-06T07:59:44Z"}',10,'RCL/12414100','2026-10-06T07:59:44+00:00');
INSERT INTO "analysis_memo" VALUES('291b8cd621944d0cfe6dca995296c7c0799bacf7d75663a79c259d6fa3909dd0','{"triage":{"affects_foreigners":true,"confidence":0.85,"rationale":"Проект изменяет Консульское право и попутно вносит поправки в закон о иностранцах (приоритет рассмотрения виз для научных работников, возможность передачи процедур внешним поставщикам услуг), а также регулирует отдельные аспекты, касающиеся почётных консулов-иностранцев и иностранцев-стипендиатов NAWA, что напрямую затрагивает процедуры для иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":13697,"output_tokens":172,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12408952','2026-10-07T19:24:45+00:00');
INSERT INTO "analysis_memo" VALUES('72ca97237e8799983c3cf599826ff8a3fe3afa1e2999c3d5df4f38a0e0218870','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается исключительно обязанности операторов связи предоставлять поставщикам платёжных услуг данные об освобождённых номерах телефонов для предотвращения ошибочных переводов «на телефон», и никак не затрагивает иностранцев, их пребывание, работу или документы."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":21791,"output_tokens":129,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3176','2026-10-07T19:24:45+00:00');
INSERT INTO "analysis_memo" VALUES('f3073a181256b200f66759db42ddc05b8ca363b15ab4aa989159a9fba071e242','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект меняет «Право консульское», закон о иностранцах и др. Появится электронная платформа ePUK для связи с консулом, шире привлекаются внешние визовые центры и собираются данные при записи на визу. Визы для докторантов и стипендиатов NAWA получат приоритет.","key_changes":["Запись на подачу на нацвизу и повторный приём заявлений можно поручать визовым центрам за плату","При онлайн‑записи на визу консул/центр может временно обрабатывать биометрию и больше данных из паспорта","Нацвизы для докторантов, исследователей и стипендиатов NAWA и Минкультуры рассматриваются в приоритете","Создаётся реестр иностранцев‑стипендиатов и участников программ NAWA с доступом МИД и консулов","Консулы подтверждают profil zaufany только гражданам Польши, ЕС и ЕАСТ, а не всем иностранцам"],"affected_groups":["иностранцы, подающие на национальную визу в Польшу","иностранные студенты и докторанты, исследователи","иностранные стипендиаты и участники программ NAWA","иностранцы, пользующиеся услугами визовых центров","иностранные охранники официальных делегаций с оружием"],"practical_impact":"Для заявителей на визу станет шире использование внешних визовых центров с дополнительной сервисной оплатой и сбором более полного набора данных при онлайн‑записи. Докторанты, исследователи и стипендиаты NAWA/Минкульт смогут рассчитывать на более быстрый приём и рассмотрение заявлений.","effective_date":"В целом закон вступает в силу через 14 дней после опубликования; нормы о квалификации консулов (art. 1 pkt 5–13) – через 3 месяца; przepisy art. 9 (реестр NAWA) – через 6 месяцев; положения о системе ePUK (art. 1 pkt 29, 36–37, 43 lit. b–c, 44, 47–48 и art. 11 ust. 2) – с даты, указанной в официальном сообщении министра иностранных дел.","confidence":0.86,"rationale":"Проект прямо изменяет ustawę o cudzoziemcach в части визовых процедур и приоритета рассмотрения, а также вводит реестр иностранных стипендиатов NAWA, что затрагивает легализацию въезда и статус иностранцев.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":227202,"truncated":false,"text_source":"documents","created_at":"2026-10-07T19:38:39Z","input_tokens":74213,"output_tokens":2825,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument791693.pdf","source_kind":"rcl","revision":1,"text_sha256":"text-v2:2eb2bdff200ad583e341c313896b4652ff2957b20faea77bba18668220b8f90c","law_sha256":"law-v2:dfb553aba9fca7357cf37e7ee22a6a74faf1cf4bdfe128d611b535ced4bb5fee","source_checked_at":"2026-10-07T19:38:39Z"}',10,'RCL/12408952','2026-10-07T19:38:39+00:00');
INSERT INTO "analysis_memo" VALUES('a2c00be9d6df12a4d9efb3cf67e202e1a2d601b86ea77de8364de79efa38cb65','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект упорядочивает и расширяет письменные уведомления о правах для подозреваемых, обвиняемых, осуждённых, потерпевших и свидетелей в уголовных делах. Шаблоны таких уведомлений будут публиковаться на сайте Ministerstwo Sprawiedliwości с переводами на часто используемые иностранные языки.","key_changes":["Обязательная публикация всех шаблонов pouczeń на сайте Минюста с переводами на частые иностранные языки","Расширенные перечни прав в уведомлениях для подозреваемых, обвиняемых, потерпевших и свидетелей","Прямое информирование о праве на компенсацию за незаконное задержание, арест, осуждение и меры zabezpieczające","Стандартизированные письменные pouczenia и для осуждённых и участников частного обвинения","Расширенные pouczenia для лиц по европейскому ордеру на арест, в т.ч. для несовершеннолетних и их опекунов"],"affected_groups":["Иностранцы, участвующие в уголовном процессе в Польше как подозреваемые или обвиняемые","Иностранные потерпевшие и свидетели в уголовных делах","Иностранцы, задержанные по европейскому ордеру на арест (nakaz europejski)","Несовершеннолетние иностранцы в уголовном процессе и их законные представители"],"practical_impact":"Иностранный участник дела будет получать более подробные и понятные письменные уведомления о своих правах и обязанностях, а шаблоны этих уведомлений с переводами можно будет найти на сайте Ministerstwo Sprawiedliwości. Это облегчает понимание права на адвоката, компенсацию за незаконное задержание или осуждение и других процессуальных прав.","effective_date":"Закон вступает в силу 1 марта 2027 г.","confidence":0.93,"rationale":"Проект напрямую не меняет миграционный статус, но затрагивает права иностранцев как участников уголовного процесса и вводит переводы уведомлений, поэтому оценка 2 и категория „indirect”.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":25504,"truncated":false,"text_source":"pdf","created_at":"2026-10-07T19:38:40Z","input_tokens":11381,"output_tokens":2354,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3170/3170.pdf","source_kind":"committee_report","revision":2,"text_sha256":"text-v2:7145f31bf567b02bb514d52e14337e715f0e9b85996c69faa8c8a43c23a160f0","law_sha256":"law-v2:d8a70fc1f63ed5a49237b087c35ad410fdf7cb27a6151442bafa9fc2a1140428","source_checked_at":"2026-10-07T19:38:40Z"}',10,'2997','2026-10-07T19:38:40+00:00');
INSERT INTO "analysis_memo" VALUES('0fca2c36919ffefb93d6e90eec77d4bd37614ef6a431a66d5ccd6958e4f9d8a6','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Законопроект касается правил приостановления обучения докторантов, их социального страхования и доступа к научной инфраструктуре, без упоминания особых положений для иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":4497,"output_tokens":88,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/33929/2026','2026-10-09T07:29:30+00:00');
INSERT INTO "analysis_memo" VALUES('2995e74e80bf94ef7f94171b80e9f229fc259ac2d7b96c004f6341f54b99e12e','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.","key_changes":["Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией","Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии","Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS","Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу","Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты"],"affected_groups":["иностранные докторанты польских школ докторантских","иностранцы, завершившие обучение в школе докторантской и готовящие защиту","вузы и научные учреждения, ведущие школы докторантские с иностранцами"],"practical_impact":"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.","effective_date":"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.","confidence":0.93,"rationale":"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":68211,"truncated":false,"text_source":"pdf","created_at":"2026-10-09T07:38:31Z","input_tokens":23645,"output_tokens":1111,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-33929-2026/$file/10-RPW-33929-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:671110a797f75f62e946bcd580fb507f4f591a40dec42fc59e7874e69a5abde7","law_sha256":"law-v2:8c9f289a9c507825256be59e5306e676356ecd300e9c57646c1ece5096ee9060","source_checked_at":"2026-10-09T07:38:31Z"}',10,'RPW/33929/2026','2026-10-09T07:38:31+00:00');
INSERT INTO "analysis_memo" VALUES('6a72bb2c12d8c42711641c6db6786fd7dc3d2648eaed4f9ba0a5ff1f9d7fb5e2','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет закон о kierujących pojazdami (о водителях) и ещё несколько актов в сфере автотранспорта. Текста нет, поэтому неизвестно, какие именно правила и для кого изменятся.","key_changes":["Изменяются общие положения ustawa o kierujących pojazdami; деталей нет","Корректируются также отдельные нормы в других законах о дорожном транспорте","Конкретные статьи, сроки и категории водителей в доступных материалах не указаны"],"affected_groups":["Иностранцы, имеющие или планирующие получать польские водительские права","Иностранные профессиональные водители, работающие в автотранспорте в Польше"],"practical_impact":"Возможны новые требования к получению/обмену прав или работе водителем, но без текста невозможно сказать, какие именно и с какой даты.","effective_date":null,"confidence":0.25,"rationale":"Изменения в ustawa o kierujących pojazdami могут затронуть правила получения и обмена прав для иностранцев, но без текста виден только общий, косвенный характер влияния.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":0,"truncated":false,"text_source":"metadata_only","created_at":"2026-10-09T14:38:37Z","input_tokens":304,"output_tokens":2120,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":null,"source_kind":"metadata","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":"2026-10-09T14:38:37Z"}',10,'RCL/12411950','2026-10-09T14:38:37+00:00');
INSERT INTO "analysis_memo" VALUES('7c3724c90f5f264eeba825fdbbb772645c81babb545f7c1dac4a86447d85cf0f','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект полностью меняет систему обучения и экзаменов на польские права, вводит цифровую карту курсанта, запись видео экзаменов и новые сроки действия результатов. Для шеринговых самокатов и велосипедов вводится парковка только в специально обозначенных местах под угрозой эвакуации и сборов.","key_changes":["Вводится цифровая карта курсанта с GPS‑записью маршрутов и часов вождения","Видео‑ и аудиозапись практических экзаменов (внутренних и госэкзаменов) для всех категорий","Убирается экзамен на плацу для категорий B и B1, меняются правила повторной сдачи","Результат теории и части плаца (другие категории) действует 24 месяца, одно‑дневные повторы ограничены","Шеринговые самокаты/велосипеды можно оставлять только в обозначенных зонах, иначе эвакуация и платёж"],"affected_groups":["иностранцы, проходящие курс и экзамен на польские права (все категории, особенно B/B1)","иностранные инструкторы и владельцы автошкол","пользователи шеринговых самокатов и велосипедов, включая туристов"],"practical_impact":"Кандидату на польские права придётся учитывать цифровую фиксацию всех уроков и то, что теория и часть результатов практики «сгорают» через 24 месяца. Пользователи шеринговых самокатов и велосипедов должны парковать их только в отмеченных местах, иначе транспорт могут увезти на платную стоянку.","effective_date":"Основное: с 1 января 2027 г. Исключения: часть норм о видеозаписи экзаменов и требования к инструкторам – с 1 июля 2027 г.; przepisy о Centrum Egzaminowania, mikromobilności i др. указанные в art. 10 pkt 2–3 – соответственно с 1 января 2028 г. и 1 января 2029 г.","confidence":0.9,"rationale":"Проект затрагивает правила получения польских водительских прав и пользования шеринговой микромобильностью, что напрямую влияет на быт иностранцев, но не меняет zasady pobytu, поэтому категория «social» и важность 3.","changes_since_previous":["Ранее текста не было; теперь ясно, что вводится цифровая карта курсанта с GPS и двусторонним подтверждением занятий","Появились точные правила видеозаписи внутренних и госэкзаменов и сроки хранения записей","Уточнено, что для категорий B/B1 отменяется плац, меняются условия повторной сдачи и срок важности теории 24 месяца","Появились нормы о Centrum Egzaminowania и сокращении базы тестовых вопросов до 1500","Добавлены конкретные правила для шеринговых самокатов/велосипедов: обязательные места парковки, эвакуация и тарифы","Wskazano dokładne daty wejścia w życie poszczególnych grup przepisów (2027–2029)"]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":127449,"truncated":false,"text_source":"documents","created_at":"2026-10-09T14:59:32Z","input_tokens":41821,"output_tokens":1220,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument784828.pdf","source_kind":"rcl","revision":2,"text_sha256":"text-v2:373b3fe1580566c755268bed86e244514711999ed475d7dbc4ed7f1fd1f4f91e","law_sha256":"law-v2:ffc6d32a0cd0a25dd5729bb79e8443596a5eaded4b5ce2a13ac77ebe34f226e7","source_checked_at":"2026-10-09T14:59:32Z"}',10,'RCL/12411950','2026-10-09T14:59:32+00:00');
INSERT INTO "analysis_memo" VALUES('d7c246689ccb91e1e019681b6e81abb762e28420e8c33f129cfda874feb3d536','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.","key_changes":["В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС","Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы","Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу","В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex","В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше"],"affected_groups":["иностранцы с решениями о возврате/выдворении","мигранты с неурегулированным статусом, подлежащие депортации","лица, находящиеся в процедурах принудительного возвращения"],"practical_impact":"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.","effective_date":"закон вступает в силу через 14 дней со дня его официального опубликования.","confidence":0.94,"rationale":"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":25424,"truncated":false,"text_source":"pdf","created_at":"2026-10-09T14:59:32Z","input_tokens":11171,"output_tokens":3225,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf","source_kind":"committee_report","revision":3,"text_sha256":"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61","law_sha256":"law-v2:d8f3ef852ea1e280e0266d4fd204414510c5915f5b455b687f48e404e70b1825","source_checked_at":"2026-10-09T14:59:32Z"}',10,'3146','2026-10-09T14:59:32+00:00');
INSERT INTO "analysis_memo" VALUES('5cf56300192838c7e71e39415fae22d98a33fc5e2456d3df7229b8386b731869','{"triage":{"affects_foreigners":false,"confidence":0.85,"rationale":"Законопроект касается планирования и застройки территорий (условия застройки, зонирование, сельская застройка) и не затрагивает статус, пребывание или права иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":13903,"output_tokens":88,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3175','2026-10-12T21:48:12+00:00');
INSERT INTO "analysis_memo" VALUES('54f161f94dc3e7f7764e9582966fe5830d9a3760a94d67ae96b47a71756b51d4','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Законопроект касается порядка констатации смерти, оформления электронных карт смерти/рождения и актов гражданского состояния в системе здравоохранения; упоминания обывательства и пограничной службы технические и не вводят специальных норм для иностранцев, проживающих в Польше."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":13487,"output_tokens":125,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12403003','2026-10-12T21:48:13+00:00');
INSERT INTO "analysis_memo" VALUES('5400f72222a672013b7e351873129ff2829a571203cd99831be11377a5bbd302','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается ликвидации Центрального антикоррупционного бюро и создания нового органа по координации антикоррупционной деятельности, а упоминания Straży Granicznej относятся лишь к перечню служб в рамках технических поправок к другим законам, без изменений в статусе или правах иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_tokens":13728,"output_tokens":135,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12385657','2026-10-12T21:48:14+00:00');
INSERT INTO "analysis_memo" VALUES('3d77e1bc930dd21fedbb55b9fd403012545bada6524f4ca2b6c110a1ab4ccba3','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет оформление рождения, мертворождения и смерти: вводит электронные медкарты и автоматическую передачу данных в ЗАГС, статистику и санэпиднадзор. Касается всех, у кого рождение или смерть происходят в Польше, независимо от гражданства.","key_changes":["Вводятся e‑карта рождения, e‑карта смерти и e‑карта мертворождения.","ЗАГС будет получать данные напрямую из медсистемы, без большинства бумажных справок.","Появляется «urzędowy lekarz» для констатации смерти вне больницы.","При рождении/смерти фиксируются гражданство, страна проживания и срок пребывания в Польше.","Если у умершего нет PESEL, родственники по‑прежнему лично заявляют о смерти в ЗАГС."],"affected_groups":["Иностранцы, рождающие детей в Польше","Семьи умерших иностранцев в Польше","Иностранцы без номера PESEL, оформляющие смерть родственника"],"practical_impact":"Оформление рождения и смерти будет происходить через электронные медкарты, а ЗАГС сам получит почти все нужные данные. Иностранцам реже придётся относить медсправки в ЗАГС, но при отсутствии PESEL сохраняется обязанность личного заявления о смерти.","effective_date":"Закон в целом вступает в силу 1 февраля 2027 г., за исключением указанных статей, которые начнут действовать на следующий день после опубликования, с 1 января 2028 г. или с 1 января 2030 г. (по перечню в ст. 20).","confidence":0.78,"rationale":"Проект не меняет правил легализации пребывания, но существенно реформирует регистрацию рождений и смертей (ZUSC, PESEL, сбор данных о гражданстве и проживании), что затрагивает иностранцев в Польше по линии актов гражданского состояния, поэтому категория «social» и средняя важность.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":208433,"truncated":false,"text_source":"documents","created_at":"2026-10-12T22:14:37Z","input_tokens":71129,"output_tokens":1853,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12403003/13163123/13163124/dokument801853.zip","source_kind":"rcl","revision":1,"text_sha256":"text-v2:c9d455c0bd3f56ed8c53887c30172d348e7765b91f9c286be14f94b9703e3498","law_sha256":"law-v2:8d38a1abeb29e5fe8e3e9dc967ad5528bdffb820e4abb25830c26c3b136ef8f0","source_checked_at":"2026-10-12T22:14:37Z"}',10,'RCL/12403003','2026-10-12T22:14:37+00:00');
INSERT INTO "analysis_memo" VALUES('cd312ff0c2a77b353518a327d42effcc2e911ad9bac721cd0f2885c49de8a7c7','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект вводит новый закон о стажах вместо практик absolwenckich: все стажи на открытом рынке становятся платными и оформляются как umowa o pracę. Участвовать смогут поляки, граждане ЕС/ЕЭЗ, некоторые британцы и иностранцы с полным доступом к рынку труда по спецзакону.","key_changes":["Стаж = работа по umowa o pracę na czas określony, максимум 6 месяцев","Минимальная оплата стажа: не ниже 65% минимальной зарплаты","Круг участников: поляки, ЕС/ЕЭЗ, часть британцев, иностранцы из art. 3 ust. 1 i 5 pkt 1‑5 спецзакона","Отмена ustawa o praktykach absolwenckich, бесплатные практики исчезают","Стажёр получает соцстрахование как работник; данные о стажах передаются в ZUS и МРPiPS"],"affected_groups":["Иностранцы с правом работы без zezwoleń по ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom","Граждане ЕС/ЕЭЗ, Швейцарии и иных стран со свободой передвижения","Некоторые граждане Великобритании и члены их семей по Umowa o wystąpieniu","Иностранные выпускники и студенты, ищущие стаж на открытом рынке","Организаторы стажей, нанимающие иностранных стажёров"],"practical_impact":"Иностранец с полным доступом к рынку труда сможет проходить только оплачиваемый стаж по umowa o pracę с взносами в ZUS и защитой по Kodeks pracy. Бесплатные «praktyki absolwenckie» исчезнут, но появятся чёткие минимальные ставки оплаты и стандарты стажа.","effective_date":"Закон вступает в силу с 1 января 2027 года.","confidence":0.95,"rationale":"Акт комплексно регулирует стажи как форму работы, прямо определяет круг допущенных иностранцев и условия их оплаты и страхования, что существенно для трудовых прав, но не меняет правил легализации пребывания.","changes_since_previous":["Минимальная оплата стажа изменена: было ≥35% средней зарплаты, стало ≥65% минимальной зарплаты без верхнего предела.","Umowa o staż прямо признана umowa o pracę na czas określony с частичным применением Kodeks pracy, а не отдельным гражданско‑правовым договором.","Расширен и уточнён круг иностранцев: добавлены отдельные категории граждан Великобритании и их семей и ссылка на art. 3 ust. 5 pkt 1‑5 спецзакона о работе иностранцев.","Изменена модель соцстраха: взрослые стажёры страхуются как работники, а несовершеннолетние стажисты освобождены от обязательных пенсионных и рентных взносов.","Подробно урегулирован «staż z małoletnim stażystą» с выплатой минимум 500 zł стажисту и дотацией 750 zł организатору за месяц.","Закреплена дата вступления в силу (1.01.2027), добавлены численные лимиты на количество стажёров у одного организатора и новые составы нарушений с крупными штрафами."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":115478,"truncated":false,"text_source":"documents","created_at":"2026-10-12T22:14:38Z","input_tokens":39775,"output_tokens":2405,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171191/13171192/dokument801844.zip","source_kind":"rcl","revision":2,"text_sha256":"text-v2:3cb0bf125f8d9ffba6558af943a27d6f02bb6f6b19f0ae555d738b02c8ec2244","law_sha256":"law-v2:fde80988ad0ee8ddd1ca1ce8b82bdfbbe171fcfa38a854db236375da77d851b7","source_checked_at":"2026-10-12T22:14:38Z"}',10,'RCL/12404454','2026-10-12T22:14:38+00:00');
INSERT INTO "analysis_memo" VALUES('f3091efae3d2d3985d1dbc6a570a1aeba7291acc2e8fe20dea4e56a47ac59249','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит «молчаливое одобрение» ВНЖ (pobyt czasowy) для граждан избранных развитых безвизовых стран. Если воевода не вынесет решение за 60 дней, разрешение считается выданным на 2 года, при усиленных проверках безопасности и возможности немедленного отзыва.","key_changes":["«Молчаливое» одобрение pobyt czasowy для граждан стран из списка Rady Ministrów","Нет решения воеводы за 60 дней — ВНЖ считается выданным автоматически","Срок такого pobyt czasowy: 2 года (157a – 6 мес., 157g – 1 год)","Воевода: 14 дней на вызов по ошибкам заявки, 30 дней на запрос проверок","Отзыв ВНЖ по угрозе безопасности подлежит немедленному исполнению"],"affected_groups":["граждане развитых безвизовых стран (Австралия, Япония, Корея, США, Великобритания и др.) после включения в список","иностранцы из этих стран, подающие на zezwolenie na pobyt czasowy по основным целям (работа, бизнес, учёба, исследования, стажировка, волонтариат)"],"practical_impact":"Для граждан стран из правительственного списка оформление ВНЖ ускоряется: при e‑заявлении через MOS и отсутствии решения за 60 дней разрешение считается выданным на стандартный срок. Однако нужно вовремя явиться, сдать отпечатки и документы, а при выявлении угрозы безопасности ВНЖ могут быстро и сразу исполнимо отозвать.","effective_date":"Закон вступает в силу через 14 дней после опубликования, за исключением ст. 1 п. 4 в части ст. 112f ч. 2–4, которые вступают в силу через 3 месяца после опубликования.","confidence":0.9,"rationale":"Проект напрямую меняет правила и сроки получения/отзыва zezwoleń na pobyt czasowy, вводя «молчаливое» одобрение для части иностранцев, что является ключевым изменением миграционного статуса.","changes_since_previous":["Срок на направление вызова для устранения формальных недостатков увеличен с 7 до 14 дней.","Срок на обращение за информацией от служб безопасности увеличен с 10 до 30 дней.","Исключение по сроку для разрешений по ст. 144 (15 месяцев) убрано: для них теперь действует общий 2‑летний срок."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":55561,"truncated":false,"text_source":"documents","created_at":"2026-10-12T22:14:38Z","input_tokens":19829,"output_tokens":3463,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213534/13213535/dokument801836.zip","source_kind":"rcl","revision":2,"text_sha256":"text-v2:aea480a4ba1f22a27e7809aea785e605263b7137bf5905cdfd4c067f19d6610e","law_sha256":"law-v2:8eaf7fc1e85cc1b678ac64a17595246ff703b356105055b0f90489ff6f942052","source_checked_at":"2026-10-12T22:14:38Z"}',10,'RCL/12412103','2026-10-12T22:14:38+00:00');
INSERT INTO "analysis_memo" VALUES('53ea1faf6477499b0474866655d69abb8e6e94518e034e145cc4d4483fd77791','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект вводит систему Оśrodków Eksperckich Chorób Rzadkich (центров по редким болезням) и меняет правила медстрахования NFZ в трансграничных ситуациях с ЕС/EFTA/Великобританией. Уточняются группы лиц, застрахованных в NFZ, и порядок возмещения расходов на лечение за рубежом.","key_changes":["Новая процедура NFZ по возврату расходов на лечение в ЕС/EFTA/Великобритании во время пребывания там","К заявлению на согласие/возмещение можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Медстрахование NFZ для выпускников-медиков на практике и слушателей курсов польского языка/подготовительных курсов","NFZ может сам зарегистрировать члена семьи в медстраховании, если по правилам ЕС он должен быть застрахован в Польше","Пенсионеры с работой в ЕС/EFTA/UK должны в 14 дней сообщить об окончании, долг по взносам могут удержать из пенсии"],"affected_groups":["иностранцы, лечащиеся по NFZ и выезжающие в страны ЕС/EFTA/Великобританию","иностранные слушатели курсов польского языка и подготовительных курсов к обучению на польском","выпускники медицинских направлений (в т.ч. из-за рубежа), проходящие практическое обучение в Польше","пенсионеры и получатели рент с польскими и иностранными доходами/работой","члены семей застрахованных, живущие между Польшей и другими странами ЕС/EFTA/Великобританией"],"practical_impact":"Иностранцам с правом на NFZ будет проще вернуть расходы за необходимое лечение, полученное во время поездки в ЕС/EFTA/UK, в т.ч. на основе заключения местного врача. Слушатели языковых и подготовительных курсов и выпускники‑медики на практике получают право на медстрахование NFZ, а пенсионерам с зарубежной работой нужно строго соблюдать сроки уведомлений, иначе недоплаченные взносы удержат из пенсии.","effective_date":"Закон вступает в силу по истечении 14 дней со дня обнародования, за исключением art. 1 pkt 9 lit. e и g и pkt 13 и art. 2, которые вступают в силу по истечении 12 месяцев со дня обнародования, а также art. 1 pkt 25 и art. 3, которые вступают в силу по истечении 9 месяцев со дня обнародования.","confidence":0.86,"rationale":"Акт меняет правила доступа к медицинскому страхованию NFZ и возмещению стоимости лечения за рубежом в контексте координации систем соцобеспечения ЕС/EFTA/UK, что напрямую затрагивает иностранцев, пользующихся польской системой здравоохранения, но не затрагивает легализацию их пребывания.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":42282,"truncated":false,"text_source":"pdf","created_at":"2026-10-12T22:14:38Z","input_tokens":15654,"output_tokens":3930,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3201/3201.pdf","source_kind":"committee_report","revision":4,"text_sha256":"text-v2:7aa5a1e4449c4a5ff027c159ffa1944993938ff9dccc8cbbb119fc646d460126","law_sha256":"law-v2:7893a81afe0c09ad32d3f64ecb7219f3f33ec2127c4e19bf92e9fd82e70e4659","source_checked_at":"2026-10-12T22:14:38Z"}',10,'3141','2026-10-12T22:14:38+00:00');
INSERT INTO "analysis_memo" VALUES('a7a7c36a832a4ee5f4e3ec34d04fcf0fcd8767fa92b8ab323ddb1c9eb96e641b','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект усиливает контроль NFZ над медучреждениями и условия найма/оплаты медиков. В закон о правах пациента вводится прямое право на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.","key_changes":["В закон о правах пациента вводится право на равное обращение","Прямой запрет дискриминации по гражданству, национальности и др.","Обязанность медорганизаций активно предотвращать дискриминацию","Расширяется доступ NFZ к меддокументации и контролю учреждений","Жёстко регулируются время работы и максимум оплат для медиков NFZ"],"affected_groups":["иностранцы, пользующиеся услугами NFZ","иностранные работники и студенты с правом на медобслуживание в Польше","пациенты‑иностранцы в государственных и контрактных клиниках"],"practical_impact":"Иностранец, имеющий право на лечение в Польше, получает чёткую юридическую базу требовать одинакового доступа к услугам и условиям приёма вне зависимости от гражданства. Жалобы на отказ или худшие условия из‑за паспорта можно опирать на прямую норму закона о правах пациента.","effective_date":"Устawa wchodzi w życie po upływie miesiąca od dnia ogłoszenia (через месяц со дня официального опубликования).","confidence":0.94,"rationale":"Проект прямо вводит в закон о правах пациента запрет дискриминации, включая по гражданству, что существенно влияет на социальные права иностранцев в системе здравоохранения (категория „social”, важность 3).","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":81176,"truncated":false,"text_source":"pdf","created_at":"2026-10-12T22:14:38Z","input_tokens":28580,"output_tokens":1608,"cache_read_input_tokens":1024,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf","source_kind":"committee_report","revision":2,"text_sha256":"text-v2:5dd8519f8dbf37d9ed90080a6224c539a78b2c705c073ae7ee01f6488f9a839b","law_sha256":"law-v2:1ea862ae2d11a96f555c0ce8737e38455e925538f24d9d6e71ee8a04d682afda","source_checked_at":"2026-10-12T22:14:38Z"}',10,'3157','2026-10-12T22:14:38+00:00');
INSERT INTO "analysis_memo" VALUES('bd7fa3135083dae8f26b01a2dd901881e802ef3289c6298d25cfce83a5b134a2','{"triage":{"affects_foreigners":false,"confidence":0.85,"rationale":"Законопроект касается создания медицинских информационных систем (e-Transplant, e-Hemofilia и др.) и обработки данных доноров и пациентов, включая поле «гражданство», но это общие технические изменения системы здравоохранения, не меняющие прав, обязанностей или процедур именно для иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v11","input_tokens":11828,"output_tokens":137,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12399050','2026-10-13T19:54:53+00:00');
INSERT INTO "analysis_memo" VALUES('e66c9d9480a5a3891a646770765caf3d6d430d253301e6b3f4695a0c34b00502','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет закон «Право авиационное», чтобы улучшить работу органов гражданской авиации и повысить уровень безопасности полётов. Речь идёт о новых советах по защите и удобству в авиации, правилах отчётности о происшествиях и штрафах.","key_changes":["Разделение существующей Рады на две: по защите и по упрощениям в авиации","Новые правила классификации авиационных происшествий по уровню риска","Закрепление задач ULC по системе just culture и сообщениям о её нарушениях","Уточнение правил и санкций за лазеры, свет и другие объекты в воздушном пространстве","Введение админштрафа за несдачу отчётов по авиационным операциям"],"affected_groups":["Авиакомпании, выполняющие рейсы в/из Польши","Польские аэропорты и наземные службы","Лётный и технический персонал гражданской авиации"],"practical_impact":"Для обычных пассажиров, в том числе иностранцев, изменения выражаются главным образом в повышении стандартов безопасности и внутренней организации авиации, без отдельных специальных правил для иностранцев.","effective_date":null,"confidence":0.71,"rationale":"Проект системно обновляет организацию и безопасность гражданской авиации, но не вводит особых норм именно для иностранцев, поэтому влияние на иностранцев как группу отсутствует.","mnemonic_candidate":"Двойной авиационный совет","mnemonic_fallback":"Реформа совета по авиации","mnemonic_basis":"Проект расформировывает одну Раду Охраны и Упрощений и создаёт две отдельные – по защите и по упрощениям в гражданской авиации.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v11","input_chars":0,"truncated":false,"text_source":"metadata_only","created_at":"2026-10-13T20:31:49Z","input_tokens":3406,"output_tokens":866,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":null,"source_kind":"metadata","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":"2026-10-13T20:31:49Z"}',10,'WPL/UD488','2026-10-13T20:31:49+00:00');
INSERT INTO "analysis_memo" VALUES('document-review:6b28b30337eb00bc0d5447bb03b5217f899c31011257b288a46fb88723566591','{"review":{"purpose":"consultation_review","complete":false,"summary":"Консультации по проекту ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) показали две основные группы постулатów.\n\nKonfederacja Lewiatan запросила:\n- существенное сокращение 90‑дневного срока на ponowne rozpatrzenie sprawy по ETIAS (Art. 16 ust. 2),\n- полное удаление projektowanego art. 321 ust. 3–4 ustawy o cudzoziemcach, которые многократно удлиняют сроки рассмотрения odwołań и przekazania skarg do sąду в делах о zobowiązaniu do powrotu и zakazie ponownego wjazdu.\n\nStowarzyszenie Interwencji Prawnej указало на несоответствие части изменений в ustawie o udzielaniu cudzoziemcom ochrony na terytorium RP (art. 40 ust. 2 pkt 7 i 8 u.u.c.o.) Dyrektywie 2013/32/UE и предложило:\n- полностью wykreślić projektowany art. 40 ust. 2 pkt 8 u.u.c.o.,\n- uzupełnić projektowany art. 40 ust. 2 pkt 7 u.u.c.o. дополнительным условием, аналогичным obowiązującому pkt 6, дающим заявителю возможность usprawiedliwić brak odpowiedzi.\n\nВ представленных материалах отсутствуют официальные ответы проектодателя на эти uwagi. Поэтому исход всех постулатов по состоянию на данный этап оценки следует считать неустановленным.","consultation_findings":[{"proposal":"Skrócić 90‑dniowy termin na rozpatrzenie wniosku o ponowne rozpatrzenie sprawy (Art. 16 ust. 2 projektu) – postulowana zmiana np. do 14 dni, aby termin był proporcjonalny do krótkich terminów na wydanie decyzji w I instancji w ETIAS.","respondent":"","outcome":"unknown","reason":"","affected_groups":[],"evidence":null,"text_change":null,"text_evidence":null},{"proposal":"Usunąć z projektu art. 46 pkt 28 (w aktualnym brzmieniu projektu: art. 47 pkt 30) dodający art. 321 ust. 3 i 4 ustawy o cudzoziemcach, które wydłużają termin rozpatrzenia odwołania do 6 miesięcy i termin przekazania skargi do sądu do 90 dni w sprawach zobowiązania cudzoziemca do powrotu, przedłużenia terminu dobrowolnego wyjazdu i cofnięcia zakazu ponownego wjazdu.","respondent":"","outcome":"unknown","reason":"","affected_groups":[],"evidence":null,"text_change":null,"text_evidence":null},{"proposal":"Wykreślić projektowany art. 40 ust. 2 pkt 8 ustawy o udzielaniu cudzoziemcom ochrony na terytorium RP (u.u.c.o.), który przewiduje uznanie wniosku o udzielenie ochrony międzynarodowej za wycofany w sposób dorozumiany w razie odmowy udostępnienia dowodów potwierdzających okoliczności wskazane we wniosku; postulat motywowany wyczerpującym charakterem katalogu z art. 28 ust. 1 lit. a Dyrektywy 2013/32/UE.","respondent":"","outcome":"unknown","reason":"","affected_groups":[],"evidence":null,"text_change":null,"text_evidence":null},{"proposal":"Zmodyfikować projektowany art. 40 ust. 2 pkt 7 u.u.c.o., tak aby – zgodnie z art. 28 ust. 1 lit. a Dyrektywy 2013/32/UE – dorozumiane wycofanie wniosku o udzielenie ochrony międzynarodowej następowało tylko wtedy, gdy wnioskodawca nie udzielił wymaganych informacji oraz w rozsądnym terminie nie wykazał, że zaniechanie było spowodowane okolicznościami od niego niezależnymi; w praktyce SIP proponuje dodanie klauzuli: „i nie wykazał w terminie 7 dni od daty upływu terminu na przedstawienie niezbędnych informacji, że niedopełnienie tego obowiązku było spowodowane okolicznościami, za które nie ponosi odpowiedzialności”.","respondent":"","outcome":"unknown","reason":"","affected_groups":[],"evidence":null,"text_change":null,"text_evidence":null}],"effective_rules":[],"unresolved":["Brak w przekazanych dokumentach oficjalnej odpowiedzi projektodawcy na postulat Konfederacji Lewiatan skrócenia terminu z art. 16 ust. 2 projektu (90 dni na ponowne rozpatrzenie sprawy).","Brak w przekazanych dokumentach oficjalnej odpowiedzi projektodawcy na postulat Konfederacji Lewiatan usunięcia projektowanego art. 321 ust. 3–4 ustawy o cudzoziemcach (art. 47 pkt 30 projektu).","Brak w przekazanych dokumentach oficjalnego stanowiska projektodawcy wobec uwag Stowarzyszenia Interwencji Prawnej dotyczących projektowanych art. 40 ust. 2 pkt 7 i 8 ustawy o udzielaniu cudzoziemcom ochrony na terytorium RP; brak też pełnego tekstu tych projektowanych jednostek w aktualnej wersji projektu, co uniemożliwia ocenę, czy uwagi zostały choć częściowo odzwierciedlone.","Official response/final act unavailable; source coverage is incomplete.","Outcome unconfirmed: Skrócić 90‑dniowy termin na rozpatrzenie wniosku o ponowne rozpatrzenie sprawy (Art. 16 ust. 2 projektu) – postulowana zmiana np. do 14 dni, aby termin był proporcjonalny do krótkich terminów na wydanie decyzji w I instancji w ETIAS.","Outcome unconfirmed: Usunąć z projektu art. 46 pkt 28 (w aktualnym brzmieniu projektu: art. 47 pkt 30) dodający art. 321 ust. 3 i 4 ustawy o cudzoziemcach, które wydłużają termin rozpatrzenia odwołania do 6 miesięcy i termin przekazania skargi do sądu do 90 dni w sprawach zobowiązania cudzoziemca do powrotu, przedłużenia terminu dobrowolnego wyjazdu i cofnięcia zakazu ponownego wjazdu.","Outcome unconfirmed: Wykreślić projektowany art. 40 ust. 2 pkt 8 ustawy o udzielaniu cudzoziemcom ochrony na terytorium RP (u.u.c.o.), który przewiduje uznanie wniosku o udzielenie ochrony międzynarodowej za wycofany w sposób dorozumiany w razie odmowy udostępnienia dowodów potwierdzających okoliczności wskazane we wniosku; postulat motywowany wyczerpującym charakterem katalogu z art. 28 ust. 1 lit. a Dyrektywy 2013/32/UE.","Outcome unconfirmed: Zmodyfikować projektowany art. 40 ust. 2 pkt 7 u.u.c.o., tak aby – zgodnie z art. 28 ust. 1 lit. a Dyrektywy 2013/32/UE – dorozumiane wycofanie wniosku o udzielenie ochrony międzynarodowej następowało tylko wtedy, gdy wnioskodawca nie udzielił wymaganych informacji oraz w rozsądnym terminie nie wykazał, że zaniechanie było spowodowane okolicznościami od niego niezależnymi; w praktyce SIP proponuje dodanie klauzuli: „i nie wykazał w terminie 7 dni od daty upływu terminu na przedstawienie niezbędnych informacji, że niedopełnienie tego obowiązku było spowodowane okolicznościami, za które nie ponosi odpowiedzialności”."]},"context":{"number":"RCL/12400563","title":"Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)","purpose":"consultation_review","documents":[{"identity":"rcl/740046","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146303/13146312/dokument740046.pdf","role":"position","text":"Konfederacja Lewiatan\nul. Zbyszka Cybulskiego 5\n00-727 Warszawa\ntel. +48 22 55 99 900\nlewiatan@lewiatan.org\nwww.lewiatan.org\n\nPolish Confederation\nLewiatan\nBrussels Office\nAvenue de Cortenbergh 168\ntel. +32 2 732 12 10\n\nNIP 5262353400\nKRS 0000053779\nSąd Rejonowy dla\nm. st. Warszawy w Warszawie XIII\nWydział Gospodarczy\n\n  - 1 -\n\nUwagi Konfederacji Lewiatan do projektu ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie\ninformacji o podróży oraz zezwoleń na podróż (ETIAS).\nNumer w wykazie prac legislacyjnych Rady Ministrów: UC104\n\nL.P.\nJednostka\nredakcyjna,\nktórej\nuwaga\ndotyczy\nTreść przepisu Propozycja\nzmiany Uzasadnienie/Uwagi\n1.  Art. 16 ust. 2\n2. Wniosek o ponowne rozpatrzenie\nsprawy rozpatruje się w terminie nie\ndłuższym niż 90 dni. (...)\nPostulujemy\nskrócenie\nterminu (np. do\n14 dni).\n\nZgodnie z art. 32 rozporządzenia 2018/1240, decyzja w sprawie wniosku o\nzezwolenie na podróż jest podejmowana w I instancji nie później niż 96\ngodzin po złożeniu wniosku. Termin może być przedłużony o dalsze 96 godzin\nw razie przedstawienia przez wnioskoda wcę dodatkowych informacji lub\ndokumentów, lub o dalsze 48 godzin jeśli wnioskodawca zapraszany jest na\nrozmowę zgodnie z art. 27 ust. 4 rozporządzenia.\n\nNawet uwzględniając powyższe przedłużenia, decyzja w pierwszej instancji\njest więc podejmowana w max. 240 godzin (czyli max. 10 dni).\n\nWyznaczenie 9-krotnie dłuższego terminu na ponowne rozpatrzenie wniosku\njest bezpodstawne.\n \f\n\nKonfederacja Lewiatan\nul. Zbyszka Cybulskiego 5\n00-727 Warszawa\ntel. +48 22 55 99 900\nlewiatan@lewiatan.org\nwww.lewiatan.org\n\nPolish Confederation\nLewiatan\nBrussels Office\nAvenue de Cortenbergh 168\ntel. +32 2 732 12 10\n\nNIP 5262353400\nKRS 0000053779\nSąd Rejonowy dla\nm. st. Warszawy w Warszawie XIII\nWydział Gospodarczy\n\n  - 2 -\n\nCo więcej, tak długi termin w praktyce uniemożliwia skorzystanie z prawa do\nponownego rozpatrzenia wniosku (ponieważ wymaga złożenia pierwotnego\nwniosku o udzielenie zezwolenia na podróż z kilkumiesięcznym\nwyprzedzeniem przed planowaną podróżą).\n2.  Art. 46 pkt 28\nArt. 46. W ustawie z dnia 12 grudnia 2013\nr. o cudzoziemcach (Dz. U. z 2024 r. poz.\n769, 1222 i 1688 oraz z 2025 r. poz. 619,\n621 i 622) wprowadza się następujące\nzmiany:\n28) w art. 321 dodaje się ust. 3 i 4 w\nbrzmieniu:\n„3. Załatwienie sprawy w postępowaniu\nodwoławczym powinno nastąpić nie\npóźniej niż w terminie sześciu miesięcy od\ndnia otrzymania odwołania. Jeżeli\nodwołanie nie spełnia wymogów\nprzewidzianych przepisami prawa, termin\nzałatwienia sprawy biegnie od dnia\nuzupełnienia braków.\n4. W sprawach, o których mowa w ust. 1,\nobowiązek, o którym mowa w art. 54 § 2\nustawy z dnia 30 sierpnia 2002 r. Prawo o\npostępowaniu przed sądami\nadministracyjnymi (Dz. U. z 2024 r. poz.\n935 i 1685), właściwy organ realizuje w\nPostulujemy\nusunięcie\nprzepisu.\nWprowadzany ustawą art. 321 ust. 3 ustawy o cudzoziemcach wydłuża\ntermin na rozpatrzenie odwołania w sprawach o zobowiązanie cudzoziemca\ndo powrotu, przedłużenie terminu dobrowolnego wyjazdu oraz cofnięcie\nzakazu ponownego wjazdu do 6 miesięcy (z 1 miesiąc a, który wynika z\nogólnego przepisu art. 35 §3 kpa).\nTakie sześciokrotne wydłużenie terminu na rozpatrzenie odwołania w\npowyższych sprawach nie ma związku z głównym przedmiotem ustawy\n(udziału Polski w systemie ETIAS) i nie znajduje żadnego uzasadnienia,\nnatomiast w praktyce czyni prawo do odwołania od negat ywnej decyzji\niluzorycznym.\nWprowadzany ustawą art. 321 ust. 4 ustawy o cudzoziemcach przewiduje, że\nw razie wniesienia przez stronę skargi do sądu administracyjnego na decyzję\n(lub na bezczynność/przewlekłe prowadzenie sprawy) organu straży\ngranicznej, organ ten będzie mieć 90 dni na przekazanie do sądu skargi wraz\naktami sprawy (a nie 30 dni zgodnie z ogólnym przepisem art. 54 §2 ustawy\nprawo o postępowaniu przed sądami administracyjnymi).\nTakie trzykrotne wydłużenie terminu na przekazanie do sądu skargi wraz z\naktami też nie ma związku z głównym przedmiotem ustawy, nie znajduje\nżadnego uzasadnienia i w praktyce czyni dodatkowo iluzorycznym prawo do\nodwołania od negatywnej decyzji w powyższych sprawach.\n \f\n\nKonfederacja Lewiatan\nul. Zbyszka Cybulskiego 5\n00-727 Warszawa\ntel. +48 22 55 99 900\nlewiatan@lewiatan.org\nwww.lewiatan.org\n\nPolish Confederation\nLewiatan\nBrussels Office\nAvenue de Cortenbergh 168\ntel. +32 2 732 12 10\n\nNIP 5262353400\nKRS 0000053779\nSąd Rejonowy dla\nm. st. Warszawy w Warszawie XIII\nWydział Gospodarczy\n\n  - 3 -\n\nterminie 90 dni od dnia otrzymania\nskargi.”;\n\nKL/370/126/NW/2025","sha256":"0412b17d44261ac106c3718f6ed71ba3ea1ff695acd965af5dcf98ff4bfcd196","normalized_sha256":"text-v2:7b3ae6e498bbe2dd047f6dbafaf4053e17d0c1232ecbba3e9d741b5d9698f68a","complete":true,"file_sha256":"faa042bd12e40609f6d0a77c0c9229b394b2732b2e56e5fe67e53b0463f86b0f","author":"Minister Spraw Wewnętrznych i Administracji"},{"identity":"rcl/740047","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146303/13146312/dokument740047.pdf","role":"position","text":"Stowarzyszenie Interwencji Prawnej\nUl. Siedmiogrodzka 5/51 • 01-204 Warszawa • TEL: +48 792 568 561 • FAX: +48 (22) 621 51 65\nEMAIL: biuro@interwencjaprawna.pl\nNIP 524-255-00-20, KRS 0000240024, REGON 140229381\nwww.interwencjaprawna.pl\n\nWarszawa, 18 sierpnia 2025 r.\n\n1/08/2025/KS\n\nPan Marcin Kierwiński\nMinister Spraw Wewnętrznych i Administracji\n\nSzanowny Panie Ministrze,\n\nNiniejszym w imieniu Stowarzyszenia Interwencji Prawnej przedstawiam uwagi do projektu\nustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży\noraz zezwoleń na podróż (ETIAS) (UC104).\n\nZ wyrazami szacunku,\n\nKatarzyna Słubik\nPrezeska Zarządu\n\n\f\nStowarzyszenie Interwencji Prawnej\nUl. Siedmiogrodzka 5/51 • 01-204 Warszawa • TEL: +48 792 568 561 • FAX: +48 (22) 621 51 65\nEMAIL: biuro@interwencjaprawna.pl\nNIP 524-255-00-20, KRS 0000240024, REGON 140229381\nwww.interwencjaprawna.pl\n\nKOMENTARZ DO PROJEKTU USTAWY O UDZIALE\nRZECZYPOSPOLITEJ POLSKIEJ W EUROPEJSKIM SYSTEMIE INFORMACJI O PODRÓŻY ORAZ\nZEZWOLEŃ NA PODRÓŻ (ETIAS) (UC104).\n\nArt. 41 projektu ustawy  dot. zmiany ustawy o udzielaniu cudzoziemcom ochrony na\nterytorium Rzeczpospolitej Polskiej (dalej jako: „u.u.c.o.”)\n\nUmorzenie postępowania\nProjektowana regulacja prawna dodaje dwie przesłanki uznania wniosku o udzielenie\nochrony międzynarodowej za wycofany w sposób dorozumiany, co prowadzi do umorzenia\nwskazanego postępowania. Są to: (1) odmówienie przedstawienia informacji niezbędnych\ndo ustalenia stanu faktycznego (dot.  art. 40 ust. 2 pkt 7 projektowanej u.u.c.o.); (2)\nodmówienie udostępnienia dowodów potwierdzających okoliczności wskazane w\nuzasadnieniu wniosku o udzielenie ochrony międzynarodowej (dot. art. 40 ust. 2 pkt 8\nprojektowanej u.u.c.o.).\n\nProponowane zmiany w aktualnym brzmieniu są niezgodne z art. 28 ust. 1 lit a  Dyrektywy\nParlamentu Europejskiego i Rady 2013/32/UE  z dnia 26 czerwca 2013 r.  w sprawie\nwspólnych procedur udzielania i cofania ochrony międzynarodowej (wersja\nprzekształcona, dalej jako: „Dyrektywa 2013/32/UE”).\n\nDyrektywa 2013/32/UE w sposób wyczerpujący reguluje sytuacje kiedy dopuszczalne jest\nprzyjęcie domniemania, ze wnioskodawca w sposób dorozumiany wycofał wniosek o\nudzielenie ochrony międzynarodowej. Ustawodawca krajowy nie może tym samym\nwprowadzić innych, nieznanych dyrektywie przesłanek uzasadniających uznanie wniosku o\nudzielenie ochrony międzynarodowej za wycofany w sposób dorozumiany  (por.\nanalogicznie wyrok TSUE, C -483/20, par. 23 dot. wyczerpującego charakteru przesłanek\nuznania wniosku o udzielenie ochrony międzynarodowej za niedopuszczalny; wyrok TSUE,\nC-36/20 PPU, par. 104 dot. wyczerpującego charakteru przesłanek uzasadniających\ndetencję osób ubiegających się o udzielenie ochrony międzynaro dowej). Innymi słowy,\nkatalog sytuacji pozwalających uznać wniosek za wycofany w sposób dorozumiany został\nokreślony na poziomie unijnym i państwa członkowskie nie mogą go rozszerzać.\n\nPo pierwsze, D yrektywa 2013/32/UE nie przewiduje możliwości uznania wniosku za\nniedopuszczalny w przypadku odmowy przedstawienia dowodów potwierdzających\nokoliczności wskazane w e wniosku o udzielenie ochrony międzynarodowej. Tym samym\nprojektowany art. 40 ust. 2 pkt 8 u.u.c.o . wykracza tym samym poza ramy dopuszczalne\nDyrektywą 2013/32/UE i jako taki jest z nią niezgodny . Ustawodawca unijny celowo\nposługuje się różnymi pojęciami: „dostarczenia informacji” oraz „przedstawienia \f\nStowarzyszenie Interwencji Prawnej\nUl. Siedmiogrodzka 5/51 • 01-204 Warszawa • TEL: +48 792 568 561 • FAX: +48 (22) 621 51 65\nEMAIL: biuro@interwencjaprawna.pl\nNIP 524-255-00-20, KRS 0000240024, REGON 140229381\nwww.interwencjaprawna.pl\n\ndowodów” (np. art. 42 ust. 2 lit a Dyrektywy 2013/32/UE), których nie można utożsamiać.\nZgodnie z zasadą racjonalnego prawodawcy różnymi terminami nie oznacza się tego\nsamego pojęcia. Tym samym nie można przyjąć, że intencją art. 28 ust. 1 lit a Dyrektywy\n2013/32/UE było objęcie także odmowy przedstawienia dowodów przez wnioskodawcę .\nPrzepis ten wyraźnie wskazuje jedynie na odmowę dostarczenia określonych informacji\njako przesłankę przyjęcia dorozumianego wycofania wniosku . Zgodnie z przepisami\nDyrektywy 2013/32/UE odmowa przekazania dokumentów może mieć znaczenie dla oceny\nwiarygodności wnioskodawcy (zgodnie z art. 42 ust. 2 Dyrektywy 2013/32/UE), jednak nie\nmoże stanowić podstawy uznania wniosku o udzielenie ochrony międzynarodowej za\nwycofany w sposób dorozumiany. W związku z powyższym, projektowany art. 40 ust. 2 pkt\n8 u.u.c.o. winien zostać wykreślony jako sprzeczny z prawem UE.\n\nPo drugie, art. 28 ust. 1 lit. a Dyrektywy 2013/32/UE dopuszcza możliwość uznania wniosku\no udzielenie ochrony międzynarodowej za wycofany w sposób dorozumiany jedynie po\nkumulatywnym spełnieniu dwóch przesłanek:\n(1) wnioskodawca nie odpowiedział na żądania dostarczenia informacji mających znaczenie\nz punktu widzenia wniosku o udzielenie ochrony międzynarodowej, oraz\n(2) wnioskodawca nie wykazał w rozsądnym terminie, że to zaniechanie było\nspowodowane okolicznościami, na które nie miał wpływu.\n\nW projektowanym art. 40 ust. 2 pkt 7 u.u.c.o. ustawodawca pominął drugą z powyższych\nprzesłanek. Aby projektowana regulacja była zgodna z Dyrektywą 2013/32/UE do\nprojektowanego przepisu należy dodać analogiczny warunek jak w obecnym art. 40 ust. 2\npkt 6 u.u.c.o.  (dotyczącym niestawienia się na przesłuchanie). Innymi słowy  przed\nśrednikiem należy dodać następujący zapis „i nie wykazał w terminie 7 dni od daty upływu\nterminu na przedstawienie niezbędnych informacji, że niedopełnienie tego obowiązku było\nspowodowane okolicznościami, za które nie ponosi odpowiedzialności.”  Dopiero po\nuzupełnieniu przepisu o taki bądź analogiczny warunek dający wnioskodawcy możliwość\nusprawiedliwienia ewentualnego braku odpowiedzi na wezwanie projektowana regulacja\nkrajowa będzie zgodna z art. 28 ust. 1 lit. a Dyrektywy 2013/32/UE.","sha256":"fe09a86f8fc817b189cb207445c8d40ee12411eb806be50d8555a357a0d56f29","normalized_sha256":"text-v2:030e0b53c7f111f5783306ce7995fe0740c22ecfad3e809f414d3f1f5b08bc83","complete":true,"file_sha256":"f78ee1050dfc09d243ba872fbd697964238c3856504755675616891ed9406da9","author":"Minister Spraw Wewnętrznych i Administracji"},{"identity":"rcl/790412","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146396/13146399/dokument790412.zip","role":"project_text","text":"Projekt z dnia 10 lipca 2026 r.\nEtap: Stały Komitet Rady Ministrów\nUSTAWA\nz dnia <data wydania aktu> r.\no udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS))\nRozdział 1\nPrzepisy ogólne\nArt. l. Ustawa określa zasady i sposób realizacji udziału Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż, zwanym dalej „ETIAS”, w tym:\n1)\tobowiązki i uprawnienia organów w zakresie przetwarzania danych zawartych w ETIAS poprzez Krajowy System Informatyczny do spraw ETIAS, zwany dalej „KSI ETIAS”;\n2)\twłaściwy organ, o którym mowa w art. 8 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240”;\n3)\torgan pełniący rolę centralnego punktu dostępu, o którym mowa w art. 50 ust. 2 rozporządzenia 2018/1240, zwanego dalej „centralnym punktem dostępu”;\f4)\tzakres i sposób przeprowadzania konsultacji krajowych, w tym w przypadku ręcznego przetwarzania wniosków o wydanie zezwolenia na podróż, o którym mowa w art. 26 rozporządzenia 2018/1240;\n5)\twłaściwy organ oraz sposób i tryb prowadzenia postępowania odwoławczego, o którym mowa w art. 37 ust. 3, art. 40 ust. 3 i art. 41 ust. 7 rozporządzenia 2018/1240;\n6)\torgan odpowiedzialny za wprowadzanie danych do listy ostrzegawczej ETIAS, o której mowa w art. 34 ust. 3 rozporządzenia 2018/1240, podmioty uprawnione do występowania z wnioskiem o wpis do listy ostrzegawczej ETIAS oraz sposób postępowania w tych sprawach.\nArt. 2. Ilekroć w ustawie jest mowa o:\n1)\tadresie poczty elektronicznej – rozumie się przez to adres email podany przez wnioskodawcę zgodnie z art. 15 ust. 3 rozporządzenia 2018/1240;\n2)\tagencji euLISA – rozumie się przez to Agencję Unii Europejskiej ds. Zarządzania Operacyjnego Wielkoskalowymi Systemami Informatycznymi w Przestrzeni Wolności, Bezpieczeństwa i Sprawiedliwości, ustanowioną rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2018/1726 z dnia 14 listopada 2018 r. w sprawie Agencji Unii Europejskiej ds. Zarządzania Operacyjnego Wielkoskalowymi Systemami Informatycznymi w Przestrzeni Wolności, Bezpieczeństwa i Sprawiedliwości (euLISA), zmiany rozporządzenia (WE) nr 1987/2006 i decyzji Rady 2007/533/WSiSW oraz uchylenia rozporządzenia (UE) nr 1077/2011 (Dz. Urz. UE L 295 z 21.11.2018, str. 99, z późn. zm.);\n3)\taplikacji WWW ETIAS – rozumie się przez to komponent KSI ETIAS umożliwiający użytkownikom indywidualnym dostęp do danych ETIAS i funkcjonalności związanych z ETIAS, bez konieczności integracji KSI ETIAS z systemami teleinformatycznymi organów uprawnionych do przetwarzania danych ETIAS;\n4)\tbezpośrednim dostępie – rozumie się przez to dostęp do danych ETIAS poprzez KSI ETIAS, realizowany samodzielnie przez organy i służby, o których mowa w art. 3 ust. 1, zgodnie z ich uprawnieniami;\n5)\tcudzoziemcu – rozumie się przez to obywatela państwa trzeciego, o którym mowa w art. 2 ust. 1 rozporządzenia 2018/1240;\n6)\tdanych ETIAS – rozumie się przez to dane przetwarzane w systemie informacyjnym ETIAS;\f7)\teuropejskim oprogramowaniu dla jednostek krajowych ETIAS – rozumie się przez to oprogramowanie, o którym mowa w art. 6 ust. 2 lit. m rozporządzenia 2018/1240;\n8)\tgranicy zewnętrznej – rozumie się przez to granicę zewnętrzną, zgodnie z  art. 2 pkt 2 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2016/399 z dnia 9 marca 2016 r. w sprawie unijnego kodeksu zasad regulujących przepływ osób przez granice (kodeks graniczny Schengen) (Dz. Urz. UE L 77 z 23.03.2016, str. 1, z późn. zm.);\n9)\tjednolitym interfejsie krajowym – rozumie się przez to interfejs, o którym mowa w art. 6 ust. 2 lit. b rozporządzenia 2018/1240;\n10)\tjednostce krajowej ETIAS – rozumie się przez to jednostkę, o której mowa w art. 8 ust. 1 rozporządzenia 2018/1240;\n11)\tjednostce operacyjnej – rozumie się przez to jednostkę, o której mowa w art. 50 ust. 3 rozporządzenia 2018/1240, wyznaczoną przez organ lub służbę, o których mowa w art. 4 ust. 1, działającą w ich strukturze;\n12)\tkrajowej infrastrukturze granicznej – rozumie się przez to wszelkie urządzenia, sprzęt lub sieci teleinformatyczne służące ochronie granicy państwowej i kontroli ruchu granicznego, posiadające funkcjonalności niezbędne dla udziału Rzeczypospolitej Polskiej w ETIAS;\n13)\tkrajowym oprogramowaniu dla jednostki krajowej ETIAS – rozumie się przez to krajowe oprogramowanie informatyczne wykorzystywane w ramach KSI ETIAS, umożliwiające realizację zadań jednostki krajowej ETIAS;\n14)\tKrajowym Systemie Informatycznym do spraw ETIAS (KSI ETIAS) – rozumie się przez to system teleinformatyczny, o którym mowa w art. 3 pkt 3 ustawy z dnia 17 lutego 2005 r. o informatyzacji działalności podmiotów realizujących zadania publiczne (Dz. U. z 2025 r. poz. 1703 oraz z 2026 r. poz. 160), spełniający wymagania niezbędne do udziału Rzeczypospolitej Polskiej w ETIAS, umożliwiające realizację zadań wynikających z tego udziału;\n15)\tochronie porządku publicznego – rozumie się przez to ochronę porządku publicznego, o której mowa w art. 3 ust. 1 pkt 2 rozporządzenia 2018/1240;\n16)\torganach uprawnionych do przetwarzania danych ETIAS – rozumie się przez to organy i służby, o których mowa w art. 3 ust. 1 i art. 4 ust. 1, uprawnione do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS;\n17)\tpaństwie członkowskim – rozumie się przez to państwo, które stosuje przepisy rozporządzenia 2018/1240;\f18)\tpliku wniosku – rozumie się przez to plik wniosku, o którym mowa w art. 19 ust. 2 rozporządzenia 2018/1240;\n19)\tpośrednim dostępie – rozumie się przez to wgląd do danych ETIAS poprzez KSI ETIAS, przez organy i służby, o których mowa w art. 4 ust. 1, realizowany za pośrednictwem centralnego punktu dostępu;\n20)\trozpatrywaniu wniosków o wydanie zezwolenia na podróż – rozumie się przez to ręczne przetwarzanie wniosków o wydanie zezwolenia na podróż przez jednostkę krajową ETIAS, zgodnie z art. 26 rozporządzenia 2018/1240;\n21)\tryzyku dla bezpieczeństwa – rozumie się przez to ryzyko, o którym mowa w art. 3 ust. 1 pkt 6 rozporządzenia 2018/1240;\n22)\tryzyku nielegalnej imigracji – rozumie się przez to ryzyko, o którym mowa w art. 3 ust. 1 pkt 7 rozporządzenia 2018/1240;\n23)\tsystemie centralnym ETIAS – rozumie się przez to system centralny, o którym mowa w art. 3 ust. 1 pkt 25 rozporządzenia 2018/1240;\n24)\tsystemie informacyjnym ETIAS – rozumie się przez to system informacyjny, o którym mowa w art. 6 rozporządzenia 2018/1240;\n25)\ttrafieniu – rozumie się przez to trafienie, o którym mowa w art. 3 ust. 1 pkt 14 rozporządzenia 2018/1240;\n26)\tużytkowniku indywidualnym – rozumie się przez to funkcjonariusza albo pracownika upoważnionego w ramach organu uprawnionego do przetwarzania danych ETIAS do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS z wykorzystaniem aplikacji WWW ETIAS;\n27)\tużytkowniku końcowym – rozumie się przez to funkcjonariusza albo pracownika upoważnionego w ramach organu uprawnionego do przetwarzania danych ETIAS do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS z wykorzystaniem systemu teleinformatycznego tego organu;\n28)\twprowadzaniu danych – rozumie się przez to czynności polegające na zapisywaniu danych ETIAS w systemie centralnym ETIAS, obejmujące rejestrowanie danych w pliku wniosku lub wprowadzanie ich do listy ostrzegawczej ETIAS;\n29)\twysokim ryzyku epidemicznym – rozumie się przez to ryzyko, o którym mowa w art. 3 ust. 1 pkt 8 rozporządzenia 2018/1240;\n30)\tzezwoleniu na podróż – rozumie się przez to zezwolenie na podróż, o którym mowa w art. 3 ust. 1 pkt 5 rozporządzenia 2018/1240.\fRozdział 2\nOrgany uprawnione do przetwarzania danych ETIAS\nArt. 3. 1. Uprawnienie do bezpośredniego dostępu w celu:\n1)\tweryfikacji statusu zezwolenia na podróż cudzoziemca przekraczającego granicę państwową stanowiącą granicę zewnętrzną, zgodnie z art. 47 rozporządzenia 2018/1240, przysługuje Straży Granicznej;\n2)\tweryfikacji, czy spełnione są warunki wjazdu lub pobytu na terytorium Rzeczypospolitej Polskiej, zgodnie z art. 49 rozporządzenia 2018/1240, przysługuje Straży Granicznej, wojewodzie, Szefowi Urzędu do Spraw Cudzoziemców, Policji i Służbie CelnoSkarbowej;\n3)\tprzekazania danych ETIAS państwom trzecim, zgodnie z art. 65 ust. 3 rozporządzenia 2018/1240, przysługuje Straży Granicznej;\n4)\tpodejmowania decyzji w sprawie wniosku o wydanie wizy lub dokumentu pobytowego, zgodnie z art. 49a rozporządzenia 2018/1240, przysługuje Straży Granicznej, wojewodzie, Szefowi Urzędu do Spraw Cudzoziemców, Radzie do Spraw Uchodźców, ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych i konsulowi;\n5)\tprzekazania informacji będących podstawą do usunięcia pliku wniosku cudzoziemca posiadającego ważne zezwolenie na podróż, zgodnie z art. 55 ust. 5 i 6 rozporządzenia 2018/1240, przysługuje Straży Granicznej, wojewodzie, Szefowi Urzędu do Spraw Cudzoziemców, Radzie do Spraw Uchodźców, ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych i konsulowi;\n6)\twprowadzania danych, ich zmiany lub usunięcia, przysługuje Straży Granicznej.\n2. Komendantowi Głównemu Straży Granicznej przysługuje dostęp do informacji z rejestrów operacji przetwarzania danych, o których mowa w art. 45 ust. 7 rozporządzenia 2018/1240. Informacje te mogą zostać wykorzystane w toku prowadzonego postępowania na podstawie art. 462 ustawy z dnia 13 grudnia 2013 r. o cudzoziemcach (Dz. U. z 2025 r. poz. 1079 i 1794 oraz z 2026 r. poz. 203).\n3. Dostęp do przeglądania danych, wyłącznie do celów sporządzania sprawozdań i statystyk, zgodnie z art. 84 ust. 1 rozporządzenia 2018/1240, przysługuje Straży Granicznej, wojewodzie, Szefowi Urzędu do Spraw Cudzoziemców, ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych i konsulowi.\f4. Komendant Główny Straży Granicznej zapewnia zgodność z prawem, dokładność i aktualność danych wprowadzanych do systemu centralnego ETIAS oraz w razie potrzeby ich zmianę lub usunięcie zgodnie z procedurami, o których mowa w art. 55 rozporządzenia 2018/1240.\n5. Organ uprawniony do przetwarzania danych ETIAS niezwłocznie informuje Komendanta Głównego Straży Granicznej o okolicznościach wskazujących, że dane przechowywane w systemie centralnym ETIAS mogą podlegać zmianie lub usunięciu, są niezgodne z prawdą lub że dane były przetwarzane przez system centralny ETIAS z naruszeniem przepisów rozporządzenia 2018/1240.\n6. W przypadku gdy okoliczności wskazują, że dane ETIAS przechowywane w systemie centralnym ETIAS podlegają zmianie lub usunięciu, są niezgodne z prawdą lub że dane były przetwarzane przez system centralny ETIAS z naruszeniem przepisów rozporządzenia 2018/1240, Komendant Główny Straży Granicznej może wystąpić o informacje lub dokumenty do innych organów administracji publicznej w celu weryfikacji tych okoliczności i danych. Odpowiedź w tych sprawach udzielana jest w terminie nie dłuższym niż 7 dni roboczych.\nArt. 4. 1. Uprawnienie do pośredniego dostępu, zgodnie z art. 50 ust. 1 rozporządzenia 2018/1240, przysługuje prokuratorowi, sądowi, Policji, Straży Granicznej, Krajowej Administracji Skarbowej, Agencji Bezpieczeństwa Wewnętrznego, Agencji Wywiadu, Centralnemu Biuru Antykorupcyjnemu, Służbie Ochrony Państwa, Służbie Kontrwywiadu Wojskowego, Służbie Wywiadu Wojskowego i Żandarmerii Wojskowej.\n2. Organy i służby, o których mowa w ust. 1, niezwłocznie wyznaczają jednostki operacyjne, oraz zawiadamiają, w formie pisemnej, w postaci papierowej lub elektronicznej, Komendanta Głównego Straży Granicznej o wyznaczonych jednostkach operacyjnych i ich danych teleadresowych, a w szczególności o adresie, numerze telefonu, adresie email, a także o wszelkich zmianach ich dotyczących.\n3. Pośredni dostęp jest realizowany przez Komendanta Głównego Straży Granicznej na wniosek jednostki operacyjnej, jeżeli spełnione są warunki określone w art. 52 ust. 1 rozporządzenia 2018/1240.\n4. Wniosek, o którym mowa w ust. 3, jest przekazywany w formie elektronicznej z  wykorzystaniem aplikacji WWW ETIAS albo systemu teleinformatycznego organu lub służby, o których mowa w ust. 1. W wyjątkowych przypadkach, po wcześniejszym ustaleniu z Komendantem Głównym Straży Granicznej, wniosek może zostać przekazany za \fpośrednictwem alternatywnego kanału wymiany informacji zapewniającego bezpieczne warunki przekazywania danych i informacji.\n5. Komendant Główny Straży Granicznej niezwłocznie dokonuje sprawdzeń danych ETIAS, informując o ich wynikach wnioskującą jednostkę operacyjną albo informuje ją o braku możliwości dokonania sprawdzeń danych ETIAS oraz jego przyczynach.\n6. W przypadkach, o których mowa w art. 51 ust. 4 rozporządzenia 2018/1240, jednostki operacyjne powiadamiają niezwłocznie Komendanta Głównego Straży Granicznej o usunięciu danych ETIAS uzyskanych w wyniku pośredniego dostępu, jednak nie później niż w terminie 3 dni od dnia otrzymania informacji, że uzyskanie tych danych ETIAS było nieuzasadnione.\n7. Organy i służby, o których mowa w ust. 1, są właściwe do przekazania danych ETIAS, uzyskanych w wyniku pośredniego dostępu, państwu trzeciemu na zasadach określonych w art. 65 ust. 5 rozporządzenia 2018/1240.\n8. Minister właściwy do spraw wewnętrznych określi, w drodze rozporządzenia, wzór wniosku o pośredni dostęp do danych ETIAS przekazywanego za pośrednictwem alternatywnego kanału wymiany informacji, mając na względzie konieczność zapewnienia bezpiecznego i efektywnego przekazywania danych oraz bezpieczeństwo i ochronę danych przetwarzanych poprzez KSI ETIAS.\nRozdział 3\nJednostka krajowa ETIAS i Centralny Organ Techniczny Krajowego Systemu Informatycznego ETIAS\nArt. 5. 1. Komendant Główny Straży Granicznej jest właściwym organem, o którym mowa w art. 8 ust. 1 rozporządzenia 2018/1240.\n2. Komendant Główny Straży Granicznej realizuje obowiązki i korzysta z uprawnień jednostki krajowej ETIAS w zakresie i na zasadach określonych w rozporządzeniu 2018/1240 oraz innych przepisach prawa Unii Europejskiej dotyczących jednostki krajowej ETIAS.\n3. Do zadań Komendanta Głównego Straży Granicznej należy również:\n1)\tpełnienie roli centralnego punktu dostępu;\n2)\trozpatrywanie wniosków o ponowne rozpatrzenie sprawy, zgodnie z art. 37 ust. 3 rozporządzenia 2018/1240, w przypadku wydania decyzji o odmowie wydania zezwolenia na podróż albo decyzji o odmowie wydania zezwolenia na podróż o ograniczonej ważności terytorialnej, zgodnie z art. 12 pkt 2 i 3;\f3)\trozpatrywanie wniosków o ponowne rozpatrzenie sprawy, zgodnie z art. 40 ust. 3  oraz art. 41 ust. 7 rozporządzenia 2018/1240, w przypadku wydania decyzji o unieważnieniu albo cofnięciu zezwolenia na podróż albo zezwolenia na podróż o ograniczonej ważności terytorialnej, zgodnie z art. 13 ust. 1;\n4)\tprowadzenie konsultacji krajowych z właściwymi organami krajowymi w przypadku rozpatrywania wniosków o wydanie zezwolenia na podróż, unieważnienia albo cofnięcia zezwolenia na podróż albo zezwolenia na podróż o ograniczonej ważności terytorialnej oraz prowadzenia postępowań o ponowne rozpatrzenie sprawy, a także prowadzenie konsultacji z jednostkami krajowymi ETIAS innych państw członkowskich oraz innymi organami w zakresie wpisu do listy ostrzegawczej ETIAS;\n5)\tprowadzenie ewidencji osób posiadających upoważnienia w ramach centralnego punktu dostępu, o których mowa w art. 50 ust. 4 rozporządzenia 2018/1240;\n6)\tzarządzanie dostępem użytkowników indywidualnych, w tym nadawanie i cofanie uprawnień do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS z wykorzystaniem aplikacji WWW ETIAS, a także prowadzenie ewidencji uprawnień tych użytkowników;\n7)\tprowadzenie wykazu jednostek operacyjnych, o którym mowa w art. 50 ust. 3 rozporządzenia 2018/1240;\n8)\trealizacja czynności, o których mowa w art. 55 ust. 7 rozporządzenia 2018/1240;\n9)\tprowadzenie rejestrów operacji przetwarzania danych, o których mowa w art. 70 ust. 2 rozporządzenia 2018/1240;\n10)\tpowiadamianie Komisji Europejskiej, zgodnie z art. 87 ust. 1 rozporządzenia 2018/1240, o organie uznawanym za administratora, o którym mowa w art. 57 ust. 2 rozporządzenia 2018/1240;\n11)\tpowiadamianie Komisji Europejskiej i agencji euLISA, zgodnie z art. 87 ust. 2 rozporządzenia 2018/1240, o właściwych organach wskazanych w art. 13 ust. 5 rozporządzenia 2018/1240;\n12)\tpowiadamianie Komisji Europejskiej i agencji euLISA, zgodnie z art. 87 ust. 3 rozporządzenia 2018/1240, o wyznaczonych organach i centralnym punkcie dostępu, o których mowa w art. 50 ust. 1 i 2 rozporządzenia 2018/1240;\n13)\tprzygotowywanie informacji, o których mowa w art. 92 ust. 6 rozporządzenia 2018/1240 oraz sprawozdań, o których mowa w art. 92 ust. 8 rozporządzenia 2018/1240;\f14)\twspółpraca z Komisją Europejską w celu przyjęcia praktycznego podręcznika zgodnie z art. 93 rozporządzenia 2018/1240.\n4. Komendant Główny Straży Granicznej w celu realizacji zadań związanych z udziałem Rzeczypospolitej Polskiej w ETIAS, posiada uprawnienie do bezpośredniego dostępu do KSI ETIAS.\n5. Komendant Główny Straży Granicznej może upoważnić funkcjonariuszy lub pracowników Straży Granicznej do udzielania i cofania, w jego imieniu, upoważnień, o których mowa w art. 50 ust. 4 rozporządzenia 2018/1240.\n6. Komendant Główny Straży Granicznej zapewnia funkcjonariuszom lub pracownikom Straży Granicznej szkolenia dotyczące zasad bezpieczeństwa danych i praw podstawowych, w szczególności ochrony danych, zgodnie z art. 76 ust. 1 lit. g i ust. 3 rozporządzenia 2018/1240.\nArt. 6. 1. Komendant Główny Straży Granicznej pełni rolę Centralnego Organu Technicznego Krajowego Systemu Informatycznego do spraw ETIAS, zwanego dalej „COT KSI ETIAS”, odpowiedzialnego od strony technicznej za właściwe funkcjonowanie, eksploatację, rozwój i utrzymanie KSI ETIAS.\n2. Do zadań COT KSI ETIAS należy:\n1)\tzapewnienie pod względem technicznym integracji krajowej infrastruktury granicznej usytuowanej w Komendzie Głównej Straży Granicznej w celu jej połączenia z jednolitym interfejsem krajowym usytuowanym w Komendzie Głównej Policji oraz w Komendzie Stołecznej Policji, zgodnie z art. 76 ust. 1 lit. a rozporządzenia 2018/1240;\n2)\tzapewnienie połączenia centralnego punktu dostępu z jednolitym interfejsem krajowym w ramach istniejącej sieci łączności, zgodnie z art. 76 ust. 1 lit. c rozporządzenia 2018/1240;\n3)\tzapewnienie, pod względem technicznym, możliwości stosowania automatycznych procesów wyszukiwania w systemie centralnym ETIAS na granicy państwowej stanowiącej granicę zewnętrzną;\n4)\tzapewnienie środków technicznych organom uprawnionym do przetwarzania danych ETIAS, do dostępu do danych ETIAS poprzez:\na)\tdostarczenie interfejsów programistycznych, będących elementem krajowej infrastruktury granicznej, umożliwiających integrację systemów teleinformatycznych organów uprawnionych do przetwarzania danych ETIAS, a także ich rozwój i utrzymanie,\fb)\trozwój i utrzymanie aplikacji WWW ETIAS;\n5)\tzapewnienie wydajności technicznej i dostępności infrastruktury KSI ETIAS;\n6)\tzapewnienie bezpiecznych rozwiązań technicznych mających na celu ochronę danych ETIAS oraz innych danych przetwarzanych poprzez KSI ETIAS;\n7)\tprzyjęcie niezbędnych środków w odniesieniu do krajowej infrastruktury granicznej, w tym planu bezpieczeństwa oraz planu ciągłości działania i przywrócenia gotowości do pracy po wystąpieniu sytuacji nadzwyczajnej, w celach, o których mowa w art. 59 ust. 3 rozporządzenia 2018/1240;\n8)\tzapewnienie na poziomie krajowym interoperacyjności KSI ETIAS z krajowymi systemami teleinformatycznymi, rejestrami i bazami danych oraz innymi systemami informacyjnymi Unii Europejskiej oraz z danymi Europolu, o których mowa w art. 3 ust. 1 pkt 17 rozporządzenia 2018/1240;\n9)\todbieranie i przetwarzanie powiadomień, o których mowa w art. 46 ust. 1 i ust. 3 rozporządzenia 2018/1240;\n10)\todbieranie i przetwarzanie powiadomień, o których mowa w art. 48 ust. 1 i ust. 2 rozporządzenia 2018/1240;\n11)\topracowywanie krajowych planów awaryjnych w przypadku braku technicznej możliwości uzyskania dostępu do danych ETIAS na granicy państwowej stanowiącej granicę zewnętrzną, o których mowa w art. 48 ust. 4 rozporządzenia 2018/1240;\n12)\tpowiadamianie o incydentach bezpieczeństwa, o których mowa w art. 60 ust. 1 rozporządzenia 2018/1240, podmiotów wskazanych w art. 60 ust. 3 rozporządzenia 2018/1240;\n13)\todbieranie i przetwarzanie informacji przekazywanych przez agencję euLISA o incydentach bezpieczeństwa, o których mowa w art. 60 ust. 4 rozporządzenia 2018/1240;\n14)\twspółpraca z podmiotami wskazanymi w art. 60 ust. 5 rozporządzenia 2018/1240, w przypadku zaistnienia incydentu bezpieczeństwa.\n3. Organ uprawniony do bezpośredniego dostępu niezwłocznie informuje COT KSI ETIAS o zaistnieniu incydentów bezpieczeństwa, o których mowa w art. 60 ust. 1 rozporządzenia 2018/1240.\n4. W przypadku zaistnienia incydentów bezpieczeństwa, o których mowa w art. 60 ust. 1 rozporządzenia 2018/1240, COT KSI ETIAS ma prawo ograniczyć lub wyłączyć organowi uprawnionemu do bezpośredniego dostępu, dostęp do krajowej infrastruktury \fgranicznej do czasu usunięcia stwierdzonych nieprawidłowości. O stwierdzonych nieprawidłowościach działania lub zabezpieczenia KSI ETIAS, COT KSI ETIAS niezwłocznie powiadamia organ uprawniony do bezpośredniego dostępu.\n5. COT KSI ETIAS powiadamia ministra właściwego do spraw wewnętrznych oraz ministra właściwego do spraw informatyzacji o przypadkach, o których mowa w ust. 4.\nArt. 7. W celu właściwego funkcjonowania KSI ETIAS, Komendant Główny Policji:\n1)\tzapewnia całodobową dostępność obsługi, zasilanie oraz bezpieczeństwo fizyczne elementów jednolitego interfejsu krajowego oraz jego łączność z systemem centralnym ETIAS;\n2)\tzapewnia podłączenie krajowej infrastruktury granicznej do jednolitego interfejsu krajowego w ramach ośrodka podstawowego i zapasowego;\n3)\tzapewnia niezbędną liczbę kluczowych elementów systemu, tak aby w razie awarii jednego z nich element zapasowy natychmiast przejął jego rolę bez zatrzymywania procesu produkcyjnego, i wydajną łączność na potrzeby KSI ETIAS;\n4)\twspółpracuje z COT KSI ETIAS w zakresie doprowadzenia sieci łączności do jednolitego interfejsu krajowego w celu podłączenia krajowej infrastruktury granicznej.\nRozdział 4\nRozpatrywanie wniosków o wydanie zezwolenia na podróż\nArt. 8. 1. Komendant Główny Straży Granicznej rozpatruje wnioski o wydanie zezwolenia na podróż oraz wnioski o wydanie zezwolenia na podróż o ograniczonej ważności terytorialnej za pośrednictwem europejskiego oprogramowania dla jednostek krajowych ETIAS, a dodatkowo może wykonywać czynności w tym zakresie także za pośrednictwem krajowego oprogramowania dla jednostki krajowej ETIAS.\n2. Językiem wykorzystywanym podczas rozpatrywania wniosków o wydanie zezwolenia na podróż oraz zezwolenia na podróż o ograniczonej ważności terytorialnej w zakresie wymiany informacji oraz kontaktu z cudzoziemcem, który złożył wniosek, jest język polski albo język angielski. Wykorzystanie innych języków jest możliwe po uprzednim uzgodnieniu z Komendantem Głównym Straży Granicznej, zgodnie z art. 27 ust. 2 i 8 oraz art. 44 ust. 3 rozporządzenia 2018/1240.\n3. Ilekroć w dalszych przepisach jest mowa o wniosku o wydanie zezwolenia na podróż, rozumie się przez to również wniosek o wydanie zezwolenia na podróż o ograniczonej ważności terytorialnej, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240.\fArt. 9. 1. Wnioski o wydanie zezwolenia na podróż rozpatruje się na zasadach określonych w rozporządzeniu 2018/1240.\n2. Zapis rozmowy z cudzoziemcem przeprowadzonej z wykorzystaniem środków komunikacji audiowizualnej na odległość, zgodnie z art. 27 ust. 8 rozporządzenia 2018/1240, przechowuje się w krajowym oprogramowaniu dla jednostki krajowej ETIAS.\n3. W przypadku, o którym mowa w art. 27 ust. 4 rozporządzenia 2018/1240, Komendant Główny Straży Granicznej niezwłocznie zwraca się do konsula o przeprowadzenie rozmowy z cudzoziemcem. Sporządzoną opinię z rozmowy z cudzoziemcem przekazuje się niezwłocznie Komendantowi Głównemu Straży Granicznej, za pośrednictwem kanału wymiany informacji zapewniającego bezpieczne warunki przekazywania danych i informacji, celem zapisu w pliku wniosku zgodnie z art. 27 ust. 8 rozporządzenia 2018/1240. Jeżeli konsul dokonał zapisu rozmowy z cudzoziemcem, zapis tej rozmowy przekazuje się wraz ze sporządzoną opinią.\n4. W celu indywidualnej oceny ryzyka dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemicznego, Komendant Główny Straży Granicznej przeprowadzając kompleksową weryfikację dotyczącą cudzoziemca, który złożył wniosek o wydanie zezwolenia na podróż, może:\n1)\tdokonywać sprawdzeń:\na)\tz wykorzystaniem rejestrów, systemów teleinformatycznych i baz danych Straży Granicznej, w szczególności Centralnego Systemu Informatycznego Straży Granicznej (CSI SG), o którym mowa w art. 2b ustawy z dnia 12 października 1990 r. o Straży Granicznej oraz Krajowego Rejestru Cudzoziemców (KRC), o którym mowa w art. 2c ustawy z dnia 12 października 1990 r. o Straży Granicznej,\nb)\tw innych systemach informacyjnych Unii Europejskiej, o których mowa w art. 3 ust. 1 pkt 28 rozporządzenia 2018/1240, oraz innych krajowych systemach teleinformatycznych, bazach danych i rejestrach, do których posiada dostęp, lub z których może uzyskiwać dane i informacje w związku z realizacją zadań;\n2)\tprzeprowadzać konsultacje krajowe, w przypadku zaistnienia potrzeby uzyskania opinii innych organów o cudzoziemcu, czy zachodzą okoliczności uzasadniające odmowę wydania zezwolenia na podróż w zakresie stwarzania ryzyka dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemicznego, w tym uzyskiwać dodatkowe informacje lub dokumenty;\n3)\tdokonywać ustaleń dotyczących przedstawionych informacji lub dokumentów.\f5. W ramach sprawdzeń, o których mowa w ust. 4 pkt 1 lit. b, Komendant Główny Straży Granicznej, w celu indywidualnej oceny ryzyka dla bezpieczeństwa, może uzyskiwać wszystkie dane sprawdzanego cudzoziemca zgromadzone w Krajowym Rejestrze Karnym.\n6. Przepis ust. 4 stosuje się odpowiednio do czynności prowadzonych z urzędu przez Komendanta Głównego Straży Granicznej, o których mowa w art. 44 ust. 1 rozporządzenia 2018/1240, a także do osoby sprawującej władzę rodzicielską lub opiekuna prawnego albo firmy lub organizacji w przypadku trafień w wyniku weryfikacji albo porównania, o których mowa w art. 20 ust. 2 lit. m i ust. 4 rozporządzenia 2018/1240.\nArt. 10. 1. W przypadku konsultacji krajowych, o których mowa w art. 9 ust. 4 pkt 2, Komendant Główny Straży Granicznej może zwrócić się do:\n1)\tsądu;\n2)\tprokuratora;\n3)\tKomendanta Głównego Policji;\n4)\tSzefa Agencji Bezpieczeństwa Wewnętrznego;\n5)\tSzefa Agencji Wywiadu;\n6)\tKomendanta Głównego Żandarmerii Wojskowej;\n7)\tKomendanta Służby Ochrony Państwa;\n8)\tSzefa Centralnego Biura Antykorupcyjnego;\n9)\tSzefa Krajowej Administracji Skarbowej;\n10)\tSzefa Służby Kontrwywiadu Wojskowego;\n11)\tSzefa Służby Wywiadu Wojskowego;\n12)\tSzefa Urzędu do Spraw Cudzoziemców;\n13)\tministra właściwego do spraw zagranicznych;\n14)\tministra właściwego do spraw wewnętrznych;\n15)\tGłównego Inspektora Sanitarnego;\n16)\tinnych organów niż wymienione w pkt 1–15, w razie potrzeby.\n2. Organy, o których mowa w ust. 1, przekazują, w zakresie właściwości, uzasadnioną opinię, pozytywną albo negatywną, w terminie nie dłuższym niż 48 godzin od otrzymania wniosku w tej sprawie. W pilnych przypadkach, Komendant Główny Straży Granicznej może wyznaczyć termin przekazania opinii krótszy niż 48 godzin.\n3. Nieprzekazanie opinii w wyznaczonym terminie traktuje się jako pozytywną opinię dotyczącą cudzoziemca.\f4. Opinia:\n1)\tpozytywna – oznacza, że nie stwierdzono istnienia przesłanek faktycznych ani wynikających z takich przesłanek uzasadnionych podstaw, by uznać, że obecność cudzoziemca na terytorium państw członkowskich stwarza lub stworzy ryzyko dla bezpieczeństwa, ryzyko nielegalnej imigracji lub wysokie ryzyko epidemiczne;\n2)\tnegatywna – oznacza, że stwierdzono istnienie przesłanek faktycznych, by uznać, że obecność cudzoziemca na terytorium państw członkowskich stwarza lub stworzy ryzyko dla bezpieczeństwa, ryzyko nielegalnej imigracji lub wysokie ryzyko epidemiczne.\n5. Organy, o których mowa w ust. 1 pkt 1–15, wyznaczają punkt kontaktowy właściwy w sprawach konsultacji krajowych oraz niezwłocznie zawiadamiają pisemnie, w postaci papierowej lub elektronicznej, Komendanta Głównego Straży Granicznej o wyznaczonym punkcie kontaktowym oraz o jego danych teleadresowych, a w szczególności o adresie, numerze telefonu i adresie email.\n6. Organy, o których mowa w ust. 1 pkt 1–15, niezwłocznie zawiadamiają, w formie pisemnej, w postaci papierowej lub elektronicznej, Komendanta Głównego Straży Granicznej o każdej zmianie dotyczącej wyznaczonego punktu kontaktowego.\n7. Dla organów, o których mowa w ust. 1 pkt 1 i 2, Minister Sprawiedliwości prowadzi jeden wspólny punkt kontaktowy właściwy w sprawach konsultacji krajowych dla tych organów.\n8. Wymiana informacji między organami, o których mowa w ust. 1, a Komendantem Głównym Straży Granicznej, odbywa się w formie elektronicznej. W przypadku organów, o których mowa w ust. 1 pkt 1–15, wymiana informacji następuje za pośrednictwem punktów kontaktowych, o których mowa w ust. 5 i 7. W wyjątkowych przypadkach, wniosek oraz opinia o cudzoziemcu mogą zostać przekazane za pośrednictwem alternatywnego kanału wymiany informacji, zapewniającego bezpieczne warunki przekazywania danych i informacji.\n9. W przypadku wystąpienia nowych okoliczności lub pojawienia się dalszych wątpliwości dotyczących cudzoziemca, Komendant Główny Straży Granicznej może ponownie zwrócić się o wydanie opinii o cudzoziemcu do organów, o których mowa w ust. 1.\nArt. 11. 1. W przypadku gdy jednostka krajowa ETIAS innego państwa członkowskiego zwróci się, zgodnie z art. 28 lub art. 44 ust. 1 rozporządzenia 2018/1240, o opinię w sprawie wniosku o wydanie zezwolenia na podróż, Komendant Główny Straży Granicznej przed przedstawieniem opinii może dokonać sprawdzeń, przeprowadzić konsultacje krajowe lub \fdokonać ustaleń dotyczących przedstawionych informacji lub dokumentów, o których mowa w art. 9 ust. 4. Do konsultacji stosuje się przepisy art. 10.\n2. Na negatywną opinię Komendanta Głównego Straży Granicznej w sprawie wniosku o wydanie zezwolenia na podróż, o której mowa w art. 28 ust. 3 lit. b rozporządzenia 2018/1240, cudzoziemcowi przysługuje skarga do sądu administracyjnego w terminie 30 dni od dnia wysłania na adres poczty elektronicznej przez jednostkę krajową ETIAS innego państwa członkowskiego decyzji o odmowie wydania zezwolenia na podróż zgodnie z art. 28 ust. 7 rozporządzenia 2018/1240.\nRozdział 5\nZezwolenie na podróż i ponowne rozpatrzenie sprawy\nArt. 12. Po rozpatrzeniu wniosku o wydanie zezwolenia na podróż, Komendant Główny Straży Granicznej:\n1)\twydaje zezwolenie na podróż, w przypadkach, o których mowa w art. 36 rozporządzenia 2018/1240;\n2)\todmawia wydania zezwolenia na podróż, w przypadkach, o których mowa w art. 37 rozporządzenia 2018/1240;\n3)\tmoże wydać zezwolenie na podróż o ograniczonej ważności terytorialnej, w przypadkach, o których mowa w art. 44 ust. 1 rozporządzenia 2018/1240, albo odmawia wydania takiego zezwolenia.\nArt. 13. 1. Komendant Główny Straży Granicznej:\n1)\tunieważnia zezwolenie na podróż, w przypadkach, o których mowa w art. 40 ust. 1 i 2 rozporządzenia 2018/1240;\n2)\tcofa zezwolenie na podróż, w przypadkach, o których mowa w art. 41 ust. 1–5 i 8 rozporządzenia 2018/1240.\n2. Organ administracji publicznej, w szczególności organ, o którym mowa w art. 10 ust. 1 pkt 1–15, który powziął informacje, że warunki wydania zezwolenia na podróż nie były spełnione w momencie jego wydania albo w przypadku gdy cudzoziemiec przestał spełniać warunki, przekazuje niezwłocznie te informacje wraz z uzasadnieniem Komendantowi Głównemu Straży Granicznej. Wymiana informacji w tych sprawach między organami administracji publicznej a Komendantem Głównym Straży Granicznej odbywa się w formie elektronicznej. W przypadku organów, o których mowa w art. 10 ust. 1 pkt 1–15, wymiana informacji następuje  za pośrednictwem punktów kontaktowych, o których mowa \fw art. 10  ust. 5 i 7. W wyjątkowych przypadkach, informacje mogą zostać przekazane za pośrednictwem alternatywnego kanału wymiany informacji, zapewniającego bezpieczne warunki przekazywania danych i informacji.\n3. Komendant Główny Straży Granicznej przed unieważnieniem albo cofnięciem zezwolenia na podróż, w szczególności w przypadku konieczności weryfikacji otrzymanych informacji, o których mowa w ust. 2, może wykonywać czynności w tym zakresie za pośrednictwem europejskiego oprogramowania dla jednostek krajowych ETIAS oraz dodatkowo za pośrednictwem krajowego oprogramowania dla jednostki krajowej ETIAS, a także dokonać sprawdzeń, przeprowadzić konsultacje krajowe lub dokonać ustaleń dotyczących przedstawionych informacji lub dokumentów, o których mowa w art. 9 ust. 4. Do konsultacji stosuje się przepisy art. 10.\n4. Językiem wykorzystywanym podczas czynności unieważnienia albo cofnięcia zezwolenia na podróż, w zakresie wymiany informacji oraz kontaktu z cudzoziemcem, jest język polski albo język angielski. Wykorzystanie innych języków jest możliwe po uprzednim uzgodnieniu z Komendantem Głównym Straży Granicznej, zgodnie z art. 27 ust. 2 i 8 oraz art. 44 ust. 3 rozporządzenia 2018/1240.\nArt. 14. 1. Decyzje w sprawach, o których mowa w art. 12 i 13 ust. 1, są wydawane w postaci elektronicznej przez europejskie oprogramowanie dla jednostek krajowych ETIAS oraz doręczane na adres poczty elektronicznej w formie powiadomień, o których mowa w art. 38 ust. 1 i 2, art. 42 oraz art. 44 ust. 7 rozporządzenia 2018/1240.\n2. Decyzje o odmowie wydania, o unieważnieniu albo cofnięciu zezwolenia na podróż są wydawane z wykorzystaniem standardowego formularza, o którym mowa w art. 38 ust. 3 rozporządzenia 2018/1240.\nArt. 15. 1. Od decyzji o:\n1)\todmowie wydania zezwolenia na podróż,\n2)\todmowie wydania zezwolenia na podróż o ograniczonej ważności terytorialnej,\n3)\tunieważnieniu zezwolenia na podróż,\n4)\tcofnięciu zezwolenia na podróż, z wyjątkiem decyzji wydanej na wniosek cudzoziemca, o której mowa w art. 41 ust. 8 rozporządzenia 2018/1240\n–\tprzysługuje wniosek o ponowne rozpatrzenie sprawy przez Komendanta Głównego Straży Granicznej.\f2. Cudzoziemiec składa wniosek o ponowne rozpatrzenie sprawy w terminie 7 dni od dnia doręczenia na adres poczty elektronicznej powiadomienia, o którym mowa w art. 38 ust. 2 i art. 42 rozporządzenia 2018/1240.\n3. Wniosek o ponowne rozpatrzenie sprawy może złożyć upoważniony przez cudzoziemca pełnomocnik do złożenia wniosku w jego imieniu, a w przypadku małoletnich, wniosek składa osoba sprawująca władzę rodzicielską lub opiekun prawny.\n4. Wniosek o ponowne rozpatrzenie sprawy zawiera:\n1)\tnumer wniosku, o którym mowa w art. 19 ust. 2 rozporządzenia 2018/1240;\n2)\tdane, o których mowa w art. 17 ust. 2 lit. a, aa oraz d–g rozporządzenia 2018/1240;\n3)\tinformacje o treści rozstrzygnięcia i dacie wydania decyzji, której dotyczy wniosek;\n4)\tdane osoby sprawującej władzę rodzicielską lub opiekuna prawnego, o których mowa w art. 17 ust. 2 lit. k rozporządzenia 2018/1240 – w przypadku, o którym mowa w ust. 3;\n5)\tuzasadnienie.\n5. Do wniosku o ponowne rozpatrzenie sprawy dołącza się w postaci elektronicznej odwzorowanie cyfrowe:\n1)\twszystkich stron dokumentu podróży, o którym mowa w art. 17 ust. 2 lit. d rozporządzenia 2018/1240;\n2)\tpisemnego oświadczenia podpisanego przez osobę składającą wniosek, że podane we wniosku informacje i przedstawione dokumenty są kompletne, autentyczne i prawidłowe zawierającego klauzulę o treści: „Podane we wniosku informacje i przedstawione dokumenty są kompletne, autentyczne i prawidłowe. Jestem świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia.”;\n3)\tpełnomocnictwa wraz z dowodem wniesienia opłaty skarbowej w przypadkach określonych w ustawie z dnia 16 listopada 2006 r. o opłacie skarbowej (Dz. U. z 2025 r. poz. 1154, 1795 i 1847 oraz z 2026 r. poz. 846, 875 i 912) oraz wskazuje dane, o których mowa w art. 17 ust. 2 lit. m rozporządzenia 2018/1240 – w przypadku, o którym mowa w ust. 3;\n4)\tinnych dokumentów – w przypadku, gdy cudzoziemiec je posiada.\n6. Oświadczenie, o którym mowa w ust. 5 pkt 2, składa się pod rygorem odpowiedzialności karnej za złożenie fałszywego oświadczenia. Klauzula, o której mowa w ust. 5 pkt 2, zastępuje pouczenie organu uprawnionego do odebrania oświadczenia o odpowiedzialności karnej za złożenie fałszywego oświadczenia.\f7. Wniosek, o którym mowa w ust. 1, wraz z informacjami lub dokumentami, składa się w języku polskim w postaci elektronicznej za pośrednictwem narzędzia teleinformatycznego Straży Granicznej, po dokonaniu uwierzytelnienia na podstawie danych, o których mowa w ust. 4 pkt 1 i 2.\n8. Za przyjęcie i rozpatrzenie przez Komendanta Głównego Straży Granicznej wniosku o ponowne rozpatrzenie sprawy pobiera się opłatę, która stanowi dochód budżetu państwa. Opłaty nie pobiera się od cudzoziemca, który w dniu składania wniosku o ponowne rozpatrzenie sprawy nie ukończył lat osiemnastu albo ukończył lat siedemdziesiąt, a także od cudzoziemca, o którym mowa w art. 2 ust. 1 lit. c rozporządzenia 2018/1240.\n9. Cudzoziemiec uiszcza opłatę, o której mowa w ust. 8, z chwilą składania wniosku o ponowne rozpatrzenie sprawy za pośrednictwem narzędzia teleinformatycznego Straży Granicznej. Brak uiszczenia opłaty skutkuje niezłożeniem wniosku o ponowne rozpatrzenie sprawy.\n10. W przypadku niedostępności narzędzia teleinformatycznego Straży Granicznej, o którym mowa w ust. 7, informacja o tym oraz o przywróceniu dostępności, jest niezwłocznie publikowana na stronie internetowej urzędu obsługującego Komendanta Głównego Straży Granicznej.\n11. W przypadku, o którym mowa w ust. 10, termin złożenia wniosku o ponowne rozpatrzenie sprawy ulega zawieszeniu do czasu przywrócenia dostępności narzędzia teleinformatycznego Straży Granicznej.\n12. Dokumenty lub informacje sporządzone w języku obcym, służące za dowód w postępowaniu o ponowne rozpatrzenie sprawy, składa się wraz z ich tłumaczeniem na język polski, dokonanym przez tłumacza zawierającym jego imię i nazwisko, adres, numer telefonu kontaktowego oraz podpis tłumacza, który dokonał przekładu, a także datę sporządzenia przekładu.\n13. Komendant Główny Straży Granicznej może w razie wątpliwości żądać elektronicznego poświadczenia zgodności z oryginałem:\n1)\tudzielonego pełnomocnictwa, lub\n2)\twłasnoręczności podpisu pełnomocnictwa przez cudzoziemca, lub\n3)\tdokumentu potwierdzającego sprawowanie władzy rodzicielskiej lub pozostawania opiekunem prawnym, lub\n4)\tinnego dokumentu dołączonego do wniosku o ponowne rozpatrzenie sprawy.\f14. Adwokat, radca prawny, rzecznik patentowy, a także doradca podatkowy mogą sami poświadczyć za zgodność z oryginałem dokument udzielonego im pełnomocnictwa, dokument potwierdzający sprawowanie władzy rodzicielskiej lub pozostawanie opiekunem prawnym lub inny dokument dołączony do wniosku o ponowne rozpatrzenie sprawy. Jeżeli dokument został sporządzony na piśmie utrwalonym w postaci elektronicznej, poświadczenia jego zgodności z oryginałem dokonuje się przy użyciu kwalifikowanego podpisu elektronicznego, podpisu zaufanego lub podpisu osobistego. Dokumenty poświadczane elektronicznie są sporządzane w formatach danych określonych w przepisach wydanych na podstawie art. 18 pkt 1 ustawy z dnia 17 lutego 2005 r. o informatyzacji działalności podmiotów realizujących zadania publiczne. Przepis stosuje się odpowiednio do dokumentów złożonych w toku postępowania o ponowne rozpatrzenie sprawy.\n15. Cudzoziemiec może cofnąć wniosek o ponowne rozpatrzenie sprawy przed wydaniem decyzji w tej sprawie przez Komendanta Głównego Straży Granicznej.\n16. Minister właściwy do spraw wewnętrznych w porozumieniu z ministrem właściwym do spraw finansów publicznych określi, w drodze rozporządzenia, wysokość opłaty pobieranej za przyjęcie i rozpatrzenie przez Komendanta Głównego Straży Granicznej wniosku o ponowne rozpatrzenie sprawy oraz sposób uiszczania tej opłaty, mając na względzie, że opłata nie może być niższa niż 100 złotych i wyższa niż 6,54% przeciętnego miesięcznego wynagrodzenia w gospodarce narodowej oraz jej wysokość nie powinna stanowić dla cudzoziemca przeszkody w złożeniu wniosku o ponowne rozpatrzenie sprawy.\nArt. 16. 1. Jeżeli wniosek o ponowne rozpatrzenie sprawy nie spełnia wymogów formalnych, Komendant Główny Straży Granicznej wzywa cudzoziemca do usunięcia braków w terminie 7 dni od dnia doręczenia wezwania na adres poczty elektronicznej, pod rygorem pozostawienia wniosku bez rozpoznania. Przepis stosuje się odpowiednio do informacji i dokumentów dołączonych do wniosku o ponowne rozpatrzenie sprawy.\n2. Wniosek o ponowne rozpatrzenie sprawy rozpatruje się w terminie nie dłuższym niż 90 dni. Jeżeli wniosek nie spełnia wymogów formalnych przewidzianych przepisami prawa, termin załatwienia sprawy biegnie od dnia usunięcia braków formalnych wniosku o ponowne rozpatrzenie sprawy, a także informacji lub dokumentów dołączonych do tego wniosku. W uzasadnionych przypadkach, Komendant Główny Straży Granicznej powiadamia cudzoziemca o nowym terminie załatwienia sprawy oraz wskazuje powody niezałatwienia sprawy w terminie. Powiadomienie doręcza się na adres poczty elektronicznej.\f3. Złożenie wniosku o ponowne rozpatrzenie sprawy nie skutkuje wstrzymaniem lub zawieszeniem wykonania zaskarżonej decyzji.\n4. Przepisu ust. 3 nie stosuje się do decyzji dotyczących cudzoziemców, o których mowa w art. 2 ust. 1 lit. c rozporządzenia 2018/1240, będących członkami rodziny obywateli Unii Europejskiej lub cudzoziemców korzystających z prawa do swobodnego przemieszczania się równoważnego prawu przysługującemu obywatelom Unii Europejskiej na mocy umowy między Unią Europejską i jej państwami członkowskimi z jednej strony a państwem trzecim z drugiej strony – z wyjątkiem sytuacji, w której wjazd lub pobyt wskazanych cudzoziemców może stanowić zagrożenie dla porządku publicznego, bezpieczeństwa wewnętrznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich.\n5. Informacje dotyczące ponownego rozpatrzenia sprawy są zapisywane przez Komendanta Głównego Straży Granicznej w pliku wniosku.\n6. Do postępowania o ponowne rozpatrzenie sprawy stosuje się odpowiednio przepisy art. 9 ust. 2–6 i art. 10, a także przepisy art. 25a–29, art. 36–37, art. 40, art. 41 i art. 44 rozporządzenia 2018/1240 w zakresie rozpatrywania wniosków o wydanie zezwolenia na podróż, ich unieważnienia albo cofnięcia.\n7. Cudzoziemcy i ich przedstawiciele mają obowiązek niezwłocznie zawiadomić Komendanta Głównego Straży Granicznej o każdej zmianie danych, o których mowa w art. 17 ust. 2 rozporządzenia 2018/1240, zawartych w pliku wniosku, w tym adresie poczty elektronicznej. W razie niedopełnienia tego obowiązku, doręczenie na dotychczasowy adres poczty elektronicznej uważa się za dokonane.\nArt. 17. 1. W przypadku gdy przed upływem terminu na złożenie wniosku o ponowne rozpatrzenie sprawy lub terminu na rozpatrzenie wniosku, o którym mowa w art. 16 ust. 2, cudzoziemcowi:\n1)\twydano zezwolenie na podróż w wyniku rozpatrzenia odrębnego wniosku lub\n2)\tusunięto plik wniosku w związku z okolicznościami, o których mowa w art. 54 ust. 1 lit. b rozporządzenia 2018/1240, lub\n3)\tusunięto plik wniosku w związku z okolicznościami, o których mowa w art. 55 ust. 5–7 rozporządzenia 2018/1240\n– wniosek o ponowne rozpatrzenie sprawy pozostawia się bez rozpoznania.\n2. Przepis ust. 1 stosuje się odpowiednio, jeżeli cudzoziemiec nie usunął w terminie braków formalnych wniosku o ponowne rozpatrzenie sprawy, cofnął wniosek o ponowne rozpatrzenie sprawy, a także gdy postępowanie było albo stało się bezprzedmiotowe.\f3. O pozostawieniu wniosku bez rozpoznania w przypadkach, o których mowa w ust. 1 i 2, powiadamia się cudzoziemca, wskazując przyczyny pozostawienia wniosku o ponowne rozpatrzenie sprawy bez rozpoznania. Powiadomienie doręcza się na adres poczty elektronicznej.\nArt. 18. Po upływie terminu na złożenie wniosku o ponowne rozpatrzenie sprawy albo uprzednim złożeniu takiego wniosku, cudzoziemiec po dokonaniu uwierzytelnienia, o którym mowa w art. 15 ust. 7, otrzymuje za pośrednictwem narzędzia teleinformatycznego Straży Granicznej, informację o braku możliwości złożenia wniosku o ponowne rozpatrzenie sprawy.\nArt. 19. 1. Cudzoziemcowi, w przypadku złożenia wniosku o ponowne rozpatrzenie sprawy dotyczącej decyzji, o których mowa w art. 15 ust. 1 pkt 3 i 4, udostępnia się na jego wniosek informacje zawarte w pliku wniosku związane odpowiednio z cofnięciem albo unieważnieniem zezwolenia na podróż, z wyjątkiem sytuacji gdy informacje te są dostępne dla cudzoziemca za pośrednictwem ogólnodostępnej strony internetowej lub aplikacji na urządzenia mobilne, o których mowa w art. 16 rozporządzenia 2018/1240.\n2. Wniosek o udostępnienie informacji zawartych w pliku wniosku, składa się w języku polskim razem z wnioskiem o ponowne rozpatrzenie sprawy, o którym mowa w ust. 1.\n3. Informacje zawarte w pliku wniosku doręcza się na adres poczty elektronicznej w terminie 14 dni od dnia otrzymania wniosku o udostępnienie informacji zawartych w pliku wniosku.\n4. W uzasadnionych przypadkach Komendant Główny Straży Granicznej może nie uwzględnić wniosku o udostępnienie informacji zawartych w pliku wniosku, o czym informuje wnioskodawcę w formie powiadomienia. Powiadomienie zawiera wskazanie przyczyny nieuwzględnienia wniosku o udostępnienie informacji zawartych w pliku wniosku. W powiadomieniu można odstąpić od wskazania powodów nieuwzględnienia wniosku, jeżeli wymagają tego względy obronności lub bezpieczeństwa państwa lub ochrony bezpieczeństwa i porządku publicznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich. Powiadomienie doręcza się na adres poczty elektronicznej.\nArt. 20. 1. W wyniku ponownego rozpatrzenia sprawy dotyczącej decyzji o:\n1)\todmowie wydania zezwolenia na podróż, Komendant Główny Straży Granicznej wydaje decyzję, w której:\na)\tutrzymuje w mocy zaskarżoną decyzję,\nb)\tuchyla zaskarżoną decyzję i wydaje zezwolenie na podróż;\f2)\todmowie wydania zezwolenia na podróż o ograniczonej ważności terytorialnej, Komendant Główny Straży Granicznej wydaje decyzję, w której:\na)\tutrzymuje w mocy zaskarżoną decyzję,\nb)\tuchyla zaskarżoną decyzję i wydaje zezwolenie na podróż o ograniczonej ważności terytorialnej.\n2. Decyzje, o których mowa w ust. 1, doręcza się na adres poczty elektronicznej.\nArt. 21. 1. W wyniku ponownego rozpatrzenia sprawy dotyczącej decyzji o unieważnieniu albo cofnięciu zezwolenia na podróż, Komendant Główny Straży Granicznej wydaje decyzję, w której:\n1)\tutrzymuje w mocy zaskarżoną decyzję;\n2)\tuchyla zaskarżoną decyzję.\n2. Decyzje, o których mowa w ust. 1, doręcza się na adres poczty elektronicznej.\nArt. 22. 1. Na decyzje, o których mowa w art. 20 ust. 1 pkt 1 lit. a i pkt 2 lit. a oraz art. 21 ust. 1 pkt 1, przysługuje skarga do sądu administracyjnego w terminie 30 dni od dnia doręczenia decyzji na adres poczty elektronicznej. Art. 52 § 3 ustawy z dnia 30 sierpnia 2002 r. – Prawo o postępowaniu przed sądami administracyjnymi (Dz. U. z 2026 r. poz. 143 i 846) nie stosuje się.\n2. Decyzje, o których mowa w art. 20 ust. 1 pkt 1 lit. a i pkt 2 lit. a oraz art. 21 ust. 1 pkt 1, zawierają oznaczenie organu, oznaczenie strony, numer wniosku, o którym mowa w art. 19 ust. 2 rozporządzenia 2018/1240, rozstrzygnięcie, oznaczenie decyzji, która jest utrzymywana w mocy, podstawę prawną oraz powody rozstrzygnięcia, datę wydania decyzji, podpis pracownika działającego w imieniu organu z podaniem imienia, nazwiska oraz zajmowanego stanowiska, a w przypadku funkcjonariusza także stopnia służbowego, a ponadto pouczenie o dopuszczalności i trybie wniesienia skargi do sądu administracyjnego oraz wysokości opłaty od wpisu od skargi, jeżeli mają one charakter stały, albo podstawie do wyliczenia opłaty od wpisu o charakterze stosunkowym, a także możliwości ubiegania się przez stronę o zwolnienie od kosztów albo przyznanie prawa pomocy. W decyzji można odstąpić od wskazania powodów rozstrzygnięcia faktycznego, jeżeli wymagają tego względy obronności lub bezpieczeństwa państwa lub ochrony bezpieczeństwa i porządku publicznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich. Decyzje wydaje się w postaci elektronicznej.\n3. Decyzje, o których mowa w art. 20 ust. 1 pkt 1 lit. b i pkt 2 lit. b oraz art. 21 ust. 1 pkt 2, zawierają oznaczenie organu, numer wniosku, o którym mowa w art. 19 \fust. 2 rozporządzenia 2018/1240, oznaczenie strony, rozstrzygnięcie, oznaczenie decyzji, która jest uchylana, podstawę prawną oraz powody rozstrzygnięcia, datę wydania decyzji, podpis pracownika działającego w imieniu organu z podaniem imienia, nazwiska oraz zajmowanego stanowiska, a w przypadku funkcjonariusza także stopnia służbowego. W decyzji można odstąpić od wskazania powodów rozstrzygnięcia, gdy uwzględnia ona w całości żądanie strony. Decyzje wydaje się w postaci elektronicznej.\nArt. 23. 1. Za dzień doręczenia decyzji, wezwań oraz powiadomień, o których mowa w niniejszym rozdziale, uznaje się dzień ich wysłania na adres poczty elektronicznej.\n2. Wymiana informacji oraz kontakt z cudzoziemcem, a także z jego przedstawicielami, odbywa się w języku polskim za pośrednictwem adresu poczty elektronicznej. Podania (żądania, wyjaśnienia, wnioski) wniesione w inny sposób niż zgodnie z wymaganiami określonymi w przepisach ustawy lub rozporządzenia 2018/1240, pozostawia się bez rozpoznania.\n3. Komendant Główny Straży Granicznej prowadzi postępowanie o ponowne rozpatrzenie sprawy w sposób elektroniczny za pośrednictwem krajowego oprogramowania dla jednostki krajowej ETIAS.\nArt. 24. Do postępowania o ponowne rozpatrzenie sprawy nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego (Dz. U. z 2025 r. poz. 1691), z wyjątkiem art. 14 § 1a zdanie drugie, art. 32, art. 33 § 1–3 oraz działu IV.\n\nRozdział 6\nLista ostrzegawcza ETIAS\n\nArt. 25. 1. Komendant Główny Straży Granicznej wprowadza, aktualizuje lub usuwa dane z listy ostrzegawczej ETIAS zgodnie z art. 34 i art. 35 rozporządzenia 2018/1240, a także jest odpowiedzialny za:\n1)\tzarządzanie krajowymi wpisami do tej listy;\n2)\tprowadzenie konsultacji, o których mowa art. 9 ust. 2 lit. b rozporządzenia 2018/1240.\n2. Dane do listy ostrzegawczej ETIAS są wprowadzane, aktualizowane lub usuwane na wniosek organu, w którego posiadaniu znajdują się informacje dotyczące przestępstw terrorystycznych lub innych poważnych przestępstw zgodnie z art. 34 ust. 2 rozporządzenia 2018/1240. Aktualizacja lub usunięcie danych z listy ostrzegawczej ETIAS następuje \fwyłącznie na wniosek organu, którego dane zostały wprowadzone do listy ostrzegawczej ETIAS.\n3. Wniosek o wprowadzenie lub aktualizację danych do listy ostrzegawczej ETIAS zawiera dane zgodnie z zakresem art. 34 ust. 4 rozporządzenia 2018/1240, umotywowanie wprowadzenia lub aktualizacji danych oraz datę początkową oraz datę końcową okresu ważności wpisu.\n4. Wnioski, o których mowa w ust. 2, są przekazywane w  formie elektronicznej z wykorzystaniem aplikacji WWW ETIAS albo systemu teleinformatycznego organu lub służby, o których mowa w art. 26. W wyjątkowych przypadkach, po wcześniejszym ustaleniu z Komendantem Głównym Straży Granicznej, wniosek może zostać przekazany za pośrednictwem alternatywnego kanału wymiany informacji, zapewniającego bezpieczne warunki przekazywania danych i informacji.\n5. Informacji dotyczących wprowadzonych danych do listy ostrzegawczej ETIAS, o których mowa w ust.  3, nie udostępnia się w związku z realizacją praw osoby, której dane dotyczą, o których mowa w ustawie z dnia 14 grudnia 2018 r. o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości (Dz. U. z 2023 r. poz. 1206).\n6. Minister właściwy do spraw wewnętrznych określi, w drodze rozporządzenia, wzór wniosku o wprowadzenie, aktualizację albo usunięcie danych z listy ostrzegawczej ETIAS przekazywanego za pośrednictwem alternatywnego kanału wymiany informacji, mając na względzie zapewnienie sprawności zarządzania krajowymi wpisami do listy ostrzegawczej ETIAS.\nArt. 26. Uprawnienie do występowania z wnioskiem o wprowadzanie, aktualizację lub usunięcie danych z listy ostrzegawczej ETIAS, przysługuje ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych, prokuratorowi, Straży Granicznej, Policji, Krajowej Administracji Skarbowej, Szefowi Urzędu do Spraw Cudzoziemców, Agencji Bezpieczeństwa Wewnętrznego, Agencji Wywiadu, Centralnemu Biuru Antykorupcyjnemu, Służbie Ochrony Państwa, Służbie Kontrwywiadu Wojskowego, Służbie Wywiadu Wojskowego i Żandarmerii Wojskowej.\nArt. 27. 1. Organ:\n1)\twystępujący z wnioskiem o wprowadzenie lub aktualizację danych do listy ostrzegawczej ETIAS, lub\f2)\tw okresie obowiązywania wpisu do listy ostrzegawczej ETIAS\n– jest odpowiedzialny za weryfikację czy dane wniosku o wprowadzenie lub aktualizację lub obowiązujący wpis do listy ostrzegawczej ETIAS nie odpowiada wpisowi dokonanemu w Systemie Informacyjnym Schengen, celem uniknięcia powielenia wpisów\t danych zgodnie z art. 35 ust. 3 rozporządzenia 2018/1240.\n2. W przypadku stwierdzenia powielenia wpisów, o którym mowa w ust. 1, nie wprowadza lub aktualizuje się danych do listy ostrzegawczej ETIAS, a wprowadzone dane usuwa się.\nArt. 28. 1. Komendant Główny Straży Granicznej w zakresie wprowadzania danych do listy ostrzegawczej ETIAS oraz zarządzania krajowymi wpisami do tej listy jest uprawniony do:\n1)\toceny wniosku o wprowadzenie, aktualizację lub usunięcie danych z listy ostrzegawczej ETIAS w zakresie warunków określonych w art. 35 ust. 1 rozporządzenia 2018/1240;\n2)\twystąpienia o przekazanie dodatkowych informacji w zakresie wniosku o wprowadzenie, aktualizację albo usunięcie danych z listy ostrzegawczej ETIAS lub obowiązujących wpisów na tej liście;\n3)\taktualizacji lub usunięcia danych wprowadzonych do listy ostrzegawczej ETIAS zgodnie z art. 35 ust.  4 i 6 rozporządzenia 2018/1240;\n4)\tnieuwzględnienia wniosku o wprowadzenie, aktualizację lub usunięcie danych z listy ostrzegawczej ETIAS w wyniku dokonanej oceny, o której mowa w pkt 1.\n2. W przypadku, o którym mowa w ust. 1 pkt 4, Komendant Główny Straży Granicznej powiadamia organ wnioskujący o przyczynach nieuwzględnienia wniosku.\n3. W przypadku, o którym mowa w ust. 1 pkt 2, udzielenie odpowiedzi następuje w terminie nie dłuższym niż 7 dni od dnia wystąpienia przez Komendanta Głównego Straży Granicznej do organu wnioskującego o przekazanie dodatkowych informacji.\nArt. 29. 1. Za terminową weryfikację, w tym ocenę aktualności oraz prawdziwości wprowadzonych danych do listy ostrzegawczej ETIAS zgodnie z art. 35 ust. 4 i 6 rozporządzenia 2018/1240, odpowiada organ, na wniosek którego dane zostały wprowadzone do listy ostrzegawczej ETIAS.\n2. Weryfikacja, o której mowa w ust. 1, jest przeprowadzana:\n1)\tnie rzadziej niż raz na 12 miesięcy – w przypadku wpisów ważnych powyżej 12 miesięcy, lub\f2)\tprzed upływem terminu ważności wpisu – w przypadku wpisów ważnych 12 miesięcy albo poniżej 12 miesięcy\n– zgodnie z art. 35 ust. 5 rozporządzenia 2018/1240.\n3. Organ, na wniosek którego dane zostały wprowadzone do listy ostrzegawczej ETIAS, niezwłocznie powiadamia Komendanta Głównego Straży Granicznej o wyniku weryfikacji, o której mowa w ust. 1, celem aktualizacji lub usunięcia danych z listy ostrzegawczej ETIAS.\n4. Brak powiadomienia o wyniku dokonanej weryfikacji w terminach, o których mowa w ust. 2, skutkuje usunięciem wpisu z listy ostrzegawczej ETIAS.\nArt. 30. 1. Komendant Główny Straży Granicznej w przypadku:\n1)\ttrafienia w wyniku porównania, o którym mowa w art. 20 ust. 4 rozporządzenia 2018/1240, albo\n2)\tpowiadomienia, o którym mowa w art. 35a ust. 1 rozporządzenia 2018/1240, albo\n3)\tweryfikacji zapytania, o którym mowa w art. 8 ust. 2 lit. h rozporządzenia 2018/1240\n– dotyczącego krajowego wpisu do listy ostrzegawczej ETIAS, może przeprowadzić dodatkowe czynności, o których mowa w art. 9 ust. 4, w tym konsultacje z organem, na wniosek którego dane zostały wprowadzone do listy ostrzegawczej ETIAS oraz uzyskać szczegółowe informacje i dokumenty uzasadniające wpis do listy ostrzegawczej ETIAS.\n2. Organy, o których mowa w art. 26, wyznaczają punkty kontaktowe do prowadzenia konsultacji oraz niezwłocznie zawiadamiają, w formie pisemnej, w postaci papierowej lub elektronicznej, Komendanta Głównego Straży Granicznej o wyznaczonych punktach kontaktowych i ich danych teleadresowych, a w szczególności o adresie, numerze telefonu, adresie email, a także o wszelkich zmianach ich dotyczących.\n3. Do konsultacji prowadzonych zgodnie z ust. 1 oraz ich terminów stosuje się odpowiednio przepisy art. 10 ust. 2–9.\nRozdział 7\nBezpieczeństwo KSI ETIAS\nArt. 31. Organy, o których mowa w rozdziale 2, są obowiązane, w zakresie swojej właściwości, do współpracy z Komendantem Głównym Straży Granicznej w celu realizacji ich zadań związanych z udziałem Rzeczypospolitej Polskiej w ETIAS, w tym do przekazywania dokumentów, udzielania informacji oraz aktualnych i niezbędnych danych do prowadzenia wykazu jednostek operacyjnych oraz w celu przekazywania powiadomień o organach uprawnionych do przetwarzania danych ETIAS, a także niezwłocznego zgłaszania \fujawnionych incydentów bezpieczeństwa i nieprawidłowości w związku z dostępem do KSI ETIAS oraz przetwarzaniem danych poprzez KSI ETIAS.\nArt. 32. Komendant Główny Straży Granicznej przedstawia ministrowi właściwemu do spraw wewnętrznych w terminie do dnia 31 marca każdego roku, sprawozdanie dotyczące oceny funkcjonowania KSI ETIAS w poprzednim roku kalendarzowym.\nArt. 33. 1. Minister właściwy do spraw wewnętrznych sprawuje nadzór nad funkcjonowaniem KSI ETIAS.\n2. Minister właściwy do spraw wewnętrznych, w celu sprawowania nadzoru, ma prawo do:\n1)\tdostępu do informacji, o których mowa w art. 59 ust. 3 lit. k rozporządzenia 2018/1240;\n2)\tsprawdzania, czy KSI ETIAS spełnia wymagania techniczne niezbędne do udziału Rzeczypospolitej Polskiej w ETIAS;\n3)\tsprawdzania, czy osoby mające dostęp do KSI ETIAS posiadają ważne upoważnienie do dostępu do KSI ETIAS, przetwarzania danych poprzez KSI ETIAS oraz zaświadczenie o przeszkoleniu w zakresie zasad bezpieczeństwa danych oraz ich ochrony, a także w zakresie praw podstawowych;\n4)\tsprawdzania prawidłowości opisu zadań i funkcji osób mających dostęp do KSI ETIAS;\n5)\tsprawdzania zapewnienia odpowiedniej ochrony fizycznej KSI ETIAS przez organy mające do niego bezpośredni dostęp, w szczególności poprzez uniemożliwianie dostępu osobom nieuprawnionym do KSI ETIAS.\nArt. 34. Minister właściwy do spraw wewnętrznych sprawując nadzór, o którym mowa w art. 33 ust. 1, może:\n1)\tżądać przedłożenia informacji w zakresie niezbędnym do ustalenia stanu faktycznego;\n2)\tprzeprowadzać, w godzinach urzędowania danego organu, oględziny urządzeń, nośników oraz systemów informatycznych włączonych do KSI ETIAS w ramach danego organu;\n3)\tzlecać sporządzanie ekspertyz i opinii;\n4)\tżądać zablokowania bezpośredniego dostępu do KSI ETIAS do czasu usunięcia stwierdzonych nieprawidłowości.\nArt. 35. 1. Organy uprawnione do przetwarzania danych ETIAS współpracują z Komendantem Głównym Straży Granicznej na podstawie pisemnego porozumienia dotyczącego realizacji wymagań technicznych i organizacyjnych w zakresie przygotowania i podłączenia do KSI ETIAS, dostępu do tego systemu oraz zapewnienia bezpieczeństwa KSI \fETIAS, niezbędnych do wypełnienia obowiązków Rzeczypospolitej Polskiej wynikających z udziału w ETIAS.\n2. Porozumienie, o którym mowa w ust. 1, Komendant Główny Straży Granicznej zawiera z organem centralnym, jeżeli inne organy lub podmioty w ramach danej służby lub instytucji korzystają z tych samych systemów teleinformatycznych.\nRozdział 8\nOchrona danych osobowych w KSI ETIAS\nArt. 36. 1. Organ uprawniony do przetwarzania danych ETIAS, każdy we własnym zakresie, udziela oraz cofa upoważnienie do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS użytkownikowi indywidualnemu lub użytkownikowi końcowemu, a także prowadzi ewidencję tych upoważnień.\n2. Warunkiem udzielenia upoważnienia, o którym mowa w ust. 1, jest odbycie szkolenia dotyczącego dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS, w szczególności w zakresie zasad bezpieczeństwa danych oraz ich ochrony, a także w zakresie praw podstawowych.\n3. Organ uprawniony do przetwarzania danych ETIAS zapewnia szkolenie, o którym mowa w ust. 2.\n4. Szkolenie, o którym mowa w ust. 2, jest prowadzone na podstawie programu szkolenia opracowanego i zatwierdzonego przez Komendanta Głównego Straży Granicznej. Szkolenie kończy się uzyskaniem zaświadczenia o jego ukończeniu.\n5. Upoważnienie, o którym mowa w ust. 1, zawiera:\n1)\timię i nazwisko użytkownika indywidualnego lub użytkownika końcowego;\n2)\tnumer PESEL użytkownika indywidualnego lub użytkownika końcowego;\n3)\tzakres upoważnienia użytkownika indywidualnego lub użytkownika końcowego;\n4)\tokres, na który udziela się upoważnienia;\n5)\tnazwę organu uprawnionego do przetwarzania danych ETIAS;\n6)\tinformację o odbyciu szkolenia, o którym mowa w ust. 2;\n7)\tadres email użytkownika indywidualnego lub użytkownika końcowego;\n8)\tnumer telefonu kontaktowego użytkownika indywidualnego lub użytkownika końcowego;\n9)\tnumer upoważnienia.\f6. Użytkownik indywidualny oraz użytkownik końcowy składa oświadczenie o zobowiązaniu do zapewnienia bezpieczeństwa danych osobowych, w tym ochrony przed niedozwolonym lub niezgodnym z prawem przetwarzaniem danych osobowych oraz ich przypadkową utratą, zniszczeniem lub uszkodzeniem, które dołącza się do upoważnienia, o którym mowa w ust. 1.\n7. Organ uprawniony do przetwarzania danych ETIAS może upoważnić podległych mu funkcjonariuszy lub pracowników do udzielania i cofania w jego imieniu upoważnień, o których mowa w ust. 1.\n8. Komendant Główny Straży Granicznej, na wniosek organu uprawnionego do przetwarzania danych ETIAS, nadaje albo zmienia użytkownikowi indywidualnemu uprawnienie do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS z wykorzystaniem aplikacji WWW ETIAS i przydziela w tym celu spersonalizowany identyfikator i hasło tego użytkownika. W przypadku zmiany zakresu uprawnień, użytkownikowi indywidualnemu nie przydziela się ponownie spersonalizowanego identyfikatora i hasła.\n9. Wniosek, o którym mowa w ust. 8, zawiera:\n1)\timię i nazwisko użytkownika indywidualnego;\n2)\tnumer PESEL użytkownika indywidualnego;\n3)\tzakres uprawnień, który nadaje albo zmienia się użytkownikowi indywidualnemu;\n4)\tokres, na który nadaje albo zmienia się uprawnienia użytkownikowi indywidualnemu;\n5)\tnazwę organu uprawnionego do przetwarzania danych ETIAS;\n6)\tinformację o wydaniu upoważnienia, o którym mowa w ust. 1, w tym załączone odwzorowanie cyfrowe tego upoważnienia;\n7)\tinformację o odbyciu szkolenia, o którym mowa w ust. 2;\n8)\tadres email użytkownika indywidualnego;\n9)\tnumer telefonu kontaktowego użytkownika indywidualnego.\n10. Zakres wnioskowanych uprawnień, o których mowa w ust. 9 pkt 3, nie może być szerszy niż zakres udzielonego upoważnienia użytkownika indywidualnego wskazany w ust. 5 pkt 3.\n11. Komendant Główny Straży Granicznej cofa uprawnienie użytkownikowi indywidualnemu do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS, \fz wykorzystaniem aplikacji WWW ETIAS na wniosek organu, który wystąpił o nadanie uprawnień użytkownikowi indywidualnemu, zawierający:\n1)\timię i nazwisko użytkownika indywidualnego;\n2)\tnumer PESEL użytkownika indywidualnego;\n3)\tnazwę organu uprawnionego do przetwarzania danych ETIAS;\n4)\tspersonalizowany identyfikator.\n12. Wnioski, o których mowa w ust. 8 lub 11, składa się w formie elektronicznej z wykorzystaniem aplikacji WWW ETIAS.\n13. W przypadku braków formalnych wniosku, o którym mowa w ust. 8 lub 11, a w szczególności gdy wniosek jest niekompletny, zawiera niepoprawne informacje lub jest niezasadny, Komendant Główny Straży Granicznej nie uwzględnia wniosku o nadanie, zmianę lub cofnięcie uprawnień użytkownikowi indywidualnemu oraz informuje organ uprawniony do przetwarzania danych ETIAS o przyczynach nieuwzględnienia wniosku.\n14. Organ uprawniony do przetwarzania danych ETIAS wyznacza podległych funkcjonariuszy lub pracowników upoważnionych w ramach organu do:\n1)\tskładania wniosków z wykorzystaniem aplikacji WWW ETIAS o nadanie, zmianę lub cofnięcie uprawnień, o których mowa ust. 8 i 11;\n2)\tprzeglądania ewidencji uprawnień, o której mowa w art. 5 ust. 3 pkt 6, w zakresie zgodnym z przypisaniem użytkownika indywidualnego do struktury organizacyjnej danego organu uprawnionego do przetwarzania danych ETIAS, określonej w słownikach systemowych KSI ETIAS;\n3)\taktualizowania słowników systemowych KSI ETIAS w zakresie udostępnionym w aplikacji WWW ETIAS.\n15. Organ uprawniony do przetwarzania danych ETIAS informuje Komendanta Głównego Straży Granicznej w formie pisemnej, w postaci papierowej lub elektronicznej, o wyznaczonych osobach, o których mowa w ust. 14, w celu nadania im uprawnień do aplikacji WWW ETIAS oraz przydzielania spersonalizowanego identyfikatora i hasła, przekazując informacje i dane o tych osobach, a także o każdej zmianie ich dotyczącej. Do zakresu przekazywanych informacji i danych przepisy ust. 9 pkt 1, 2, 4, 5 i 7–9 stosuje się odpowiednio.\n16. Komendant Główny Straży Granicznej może upoważnić funkcjonariuszy lub pracowników Straży Granicznej do nadawania i cofania, w jego imieniu, uprawnień, o których mowa w ust. 8 i 15.\f17. Ewidencja upoważnień, o której mowa w ust. 1, zawiera elementy wymienione w ust. 5 pkt 1–5 i 7–9, a także datę udzielenia lub cofnięcia upoważnienia. Ewidencja upoważnień może być prowadzona w formie elektronicznej.\n18. Ewidencja uprawnień, o której mowa w art. 5 ust. 3 pkt 6, zawiera elementy wymienione w ust. 9 oraz spersonalizowany identyfikator użytkownika indywidualnego lub osób, o których mowa w ust. 14, i datę nadania lub cofnięcia uprawnień. Ewidencja uprawnień może być prowadzona w formie elektronicznej.\n19. Administratorem danych przetwarzanych w KSI ETIAS jest Komendant Główny Straży Granicznej.\n20. Minister właściwy do spraw wewnętrznych określi, w drodze rozporządzenia:\n1)\twzór upoważnienia do dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS, o którym mowa w ust. 1,\n2)\twzór oświadczenia, o którym mowa w ust. 6,\n3)\tsposób przekazywania informacji o przydzielonym spersonalizowanym identyfikatorze i haśle\n–\tmając na względzie zapewnienie bezpieczeństwa danych oraz prawidłową realizację przez Rzeczpospolitą Polską obowiązków wynikających z udziału w ETIAS.\nArt. 37. 1. Prezes Urzędu Ochrony Danych Osobowych jest organem nadzorczym w rozumieniu art. 66 rozporządzenia 2018/1240.\n2. Prezes Urzędu Ochrony Danych Osobowych w ramach sprawowanego nadzoru, o którym mowa w art. 66 rozporządzenia 2018/1240:\n1)\tmonitoruje, czy przetwarzanie danych osobowych w KSI ETIAS odbywa się zgodnie z prawem;\n2)\tpublikuje co roku, do dnia 31 marca, na stronie internetowej Urzędu Ochrony Danych Osobowych informacje, o których mowa w art. 64 ust. 6 rozporządzenia 2018/1240, przekazywane przez Komendanta Głównego Straży Granicznej na temat liczby wniosków o sprostowanie, uzupełnienie, usunięcie lub ograniczenie przetwarzania danych, działań podjętych w ramach odpowiedzi na wnioski i liczby sprostowań, uzupełnień, usunięć i ograniczeń przetwarzania dokonanych w odpowiedzi na wnioski zainteresowanych osób.\n3. W zakresie nieuregulowanym w ustawie, do monitoringu oraz kontroli operacji przetwarzania danych, o których mowa odpowiednio w art. 66 ust. 3 i ust. 4 rozporządzenia \f2018/1240, stosuje się przepisy odpowiednio rozdziału 9 ustawy z dnia 10 maja 2018 r. o ochronie danych osobowych (Dz. U. z 2019 r. poz. 1781 oraz z 2026 r. poz. 252 i 548) albo art. 6 ustawy z dnia 14 grudnia 2018 r. o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości.\nArt. 38. 1. Do rozpatrywania wniosków cudzoziemców dotyczących realizacji praw, o których mowa w art. 64 rozporządzenia 2018/1240, nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego.\n2. Wnioski, o których mowa w ust. 1, składa się za pośrednictwem ogólnodostępnej strony internetowej lub aplikacji na urządzenia mobilne, o których mowa w art. 16 rozporządzenia 2018/1240, a w przypadku ich niedostępności, wniosek składa się w postaci elektronicznej za pośrednictwem narzędzia teleinformatycznego Straży Granicznej. W przypadku małoletnich, wniosek składa osoba sprawująca władzę rodzicielską lub opiekun prawny.\n3. Wniosek składany za pośrednictwem narzędzia teleinformatycznego Straży Granicznej, zawiera:\n1)\tnumer wniosku, o którym mowa w art. 19 ust. 2 rozporządzenia 2018/1240;\n2)\tdane cudzoziemca, o których mowa w art. 17 ust. 2 lit. a, aa oraz d–g rozporządzenia 2018/1240;\n3)\tinformacje o rodzaju wniosku: dostęp do danych osobowych, ich sprostowanie, uzupełnienie, usunięcie lub ograniczenie przetwarzania;\n4)\tuzasadnienie;\n5)\tdane osoby sprawującej władzę rodzicielską lub opiekuna prawnego, o których mowa w art. 17 ust. 2 lit. k rozporządzenia 2018/1240 – w przypadku, o którym mowa w ust. 2 zdanie drugie;\n6)\todwzorowanie cyfrowe innych dokumentów – w przypadku, gdy cudzoziemiec je posiada;\n7)\todwzorowanie cyfrowe podpisanego przez osobę składającą wniosek, pisemnego oświadczenia, że podane we wniosku informacje i przedstawione dokumenty są kompletne, autentyczne i prawidłowe zawierającego klauzulę o treści: „Podane we wniosku informacje i przedstawione dokumenty są kompletne, autentyczne i prawidłowe. Jestem świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia.”.\n4. Oświadczenie, o którym mowa w ust. 3 pkt 7, składa się pod rygorem odpowiedzialności karnej za złożenie fałszywego oświadczenia. Klauzula, o której mowa \fw ust. 3 pkt 7, zastępuje pouczenie organu uprawnionego do odebrania oświadczenia o odpowiedzialności karnej za złożenie fałszywego oświadczenia.\n5. Złożenie wniosku za pośrednictwem narzędzia teleinformatycznego Straży Granicznej następuje w języku polskim, po dokonaniu uwierzytelnienia na podstawie danych, o których mowa w ust. 3 pkt 1 i 2.\n6. Dokumenty lub informacje sporządzone w języku obcym, służące za dowód w postępowaniu dotyczącym realizacji praw, o których mowa w art. 64 rozporządzenia 2018/1240, składa się wraz z ich tłumaczeniem na język polski, dokonanym przez tłumacza zawierającym jego imię i nazwisko, adres, numer telefonu kontaktowego oraz podpis tłumacza, który dokonał przekładu, a także datę sporządzenia przekładu.\n7. Informacja o przyczynie odmowy, o której mowa w art. 64 ust. 3 rozporządzenia 2018/1240, jest sporządzana przez Komendanta Głównego Straży Granicznej w postaci elektronicznej i jest opatrywana podpisem elektronicznym dostępnym w europejskim oprogramowaniu dla jednostek krajowych ETIAS albo kwalifikowanym podpisem elektronicznym, podpisem zaufanym, podpisem osobistym, kwalifikowaną pieczęcią elektroniczną upoważnionego pracownika lub funkcjonariusza ze wskazaniem w treści pisma osoby opatrującej pismo pieczęcią, o których mowa w ustawie z dnia 17 lutego 2005 r. o informatyzacji działalności podmiotów realizujących zadania publiczne, oraz doręczana na adres poczty elektronicznej.\n8. W przypadku, o którym mowa w ust. 7, cudzoziemcowi przysługuje prawo wniesienia skargi do Prezesa Urzędu Ochrony Danych Osobowych lub sądu powszechnego. Cudzoziemca poucza się o sposobie wniesienia skargi oraz informuje na temat pomocy, o której w art. 64 ust. 4 rozporządzenia 2018/1240.\n9. Komendant Główny Straży Granicznej prowadzi rejestr złożonych wniosków i sposobu ich rozpatrzenia zgodnie z art. 64 ust. 6 rozporządzenia 2018/1240. Rejestr prowadzi się w formie elektronicznej.\n10. Komendant Główny Straży Granicznej przekazuje Prezesowi Urzędu Ochrony Danych Osobowych informacje z rejestru, o którym mowa w ust. 9, w terminie wskazanym w art. 64 ust. 6 rozporządzenia 2018/1240.\fRozdział 9\nZmiany w przepisach\nArt. 39. W ustawie z dnia 12 października 1990 r. o Straży Granicznej (Dz. U. z 2026 r. poz. 367, 646, 815, 821 i 864) wprowadza się następujące zmiany:\n1)\tpo art. 2b dodaje się art. 2c w brzmieniu:\n„Art. 2c. 1. Komendant Główny Straży Granicznej tworzy, prowadzi, rozwija i utrzymuje Krajowy Rejestr Cudzoziemców, zwany dalej „KRC”, w celu:\n1)\tidentyfikowania i weryfikowania danych cudzoziemców za pomocą zaawansowanych algorytmów porównywania tych danych;\n2)\tumożliwiania organom administracji publicznej oraz innym podmiotom realizującym zadania publiczne weryfikacji danych cudzoziemców dla zapewnienia właściwej ich jakości oraz poprawności;\n3)\tzapewniania funkcjonowania wyspecjalizowanego narzędzia teleinformatycznego wykorzystywanego w zakresie:\na)\tochrony bezpieczeństwa i porządku publicznego w Rzeczypospolitej Polskiej,\nb)\tprzeciwdziałania nielegalnej migracji, wsparcia monitorowania i analizowania zjawisk migracyjnych, w tym rozpoznawania zagrożeń migracyjnych,\nc)\twspierania realizacji działań umożliwiających przeciwdziałanie nadużyciom w zakresie korzystania przez cudzoziemców z pomocy udzielanej ze środków publicznych, w tym pomocy społecznej,\nd)\twspierania realizacji obowiązków wynikających z udziału Rzeczypospolitej Polskiej w wielkoskalowych systemach informacyjnych Unii Europejskiej w celu zapewnienia wysokiego poziomu bezpieczeństwa w ramach unijnej przestrzeni wolności, bezpieczeństwa i sprawiedliwości,\ne)\twspierania realizacji czynności administracyjnych podejmowanych wobec cudzoziemców przez organy administracji publicznej i inne podmioty realizujące zadania publiczne,\nf)\twspierania wymiany informacji na podstawie umów międzynarodowych w kontekście nielegalnej imigracji.\n2. KRC jest prowadzony w systemie teleinformatycznym w rozumieniu ustawy z dnia 17 lutego 2005 r. o informatyzacji działalności podmiotów realizujących zadania publiczne (Dz. U. z 2025 r. poz. 1703 oraz z 2026 r. poz. 160).\f3. KRC jest zasilany w drodze teletransmisji, w zakresie przetwarzanych danych i informacji o cudzoziemcach, przez  systemy teleinformatyczne, w tym rejestry i bazy danych prowadzone przez:\n1)\tministra właściwego do spraw wewnętrznych, na podstawie przepisów art. 59 ust. 1 ustawy z dnia 2 kwietnia 2009 r. o obywatelstwie polskim (Dz. U. z 2025 r. poz. 1611) oraz art. 34 ust. 1 ustawy z dnia 9 listopada 2000 r. o repatriacji (Dz. U. z 2026 r. poz. 90),\n2)\tministra właściwego do spraw zagranicznych, na podstawie przepisów art. 23 ust. 3 ustawy z dnia 7 września 2007 r. o Karcie Polaka (Dz. U. z 2026 r. poz. 76),\n3)\tministra właściwego do spraw informatyzacji, na podstawie przepisów art. 6 i art. 44c ustawy z dnia 24 września 2010 r. o ewidencji ludności (Dz. U. z 2026 r. poz. 384),\n4)\tministra właściwego do spraw pracy, na podstawie przepisów art. 26 ust. 1 ustawy z dnia 20 marca 2025 r. o rynku pracy i służbach zatrudnienia (Dz. U. z 2025 r. poz. 620, 1746 i 1794 oraz z 2026 r. poz. 451, 507 i 734),\n5)\tministra właściwego do spraw szkolnictwa wyższego i nauki, na podstawie przepisów art. 342 ustawy z dnia 20 lipca 2018 r. – Prawo o szkolnictwie wyższym i nauce (Dz. U. z 2024 r. poz. 1571, z późn. zm.)),\n6)\tministra właściwego do spraw zabezpieczenia społecznego, na podstawie przepisów art. 23 ust. 4a ustawy z dnia 12 marca 2004 r. o pomocy społecznej (Dz. U. z 2026 r. poz. 639),\n7)\tSzefa Urzędu do Spraw Cudzoziemców, na podstawie przepisów art. 449 ust. 1 ustawy z dnia 12 grudnia 2013 r. o cudzoziemcach w zakresie danych, o których mowa w art. 449 ust. 2 pkt 1–7, 8–12, 16, 17 i 19 tej ustawy,\n8)\tKomendanta Głównego Straży Granicznej, na podstawie przepisów art. 2b,\n9)\tDyrektora Generalnego Służby Więziennej, na podstawie przepisów art. 2 ust. 2 pkt 7a ustawy z dnia 9 kwietnia 2010 r. o Służbie Więziennej (Dz. U. z 2025 r. poz. 1750 i 1823),\f10)\tZakład Ubezpieczeń Społecznych, na podstawie przepisów art. 33 ust. 1 pkt 1 i 2 ustawy z dnia 13 października 1998 r. o systemie ubezpieczeń społecznych (Dz. U z 2026 r. poz. 199 i 252, 426, 473, 507 i 734)\n–\tzwane dalej „systemami źródłowymi.”.\n4. Cudzoziemcowi, którego dane są przetwarzane w KRC, jest nadawany Główny Identyfikator Cudzoziemca, zwany dalej „GIC”.\n5. GIC jest symbolem alfanumerycznym identyfikującym cudzoziemca, generowanym automatycznie, przy wsparciu algorytmów porównywania danych alfanumerycznych.\n6. W KRC przetwarza się następujące dane i informacje dotyczące cudzoziemców:\n1)\timię (imiona);\n2)\tnazwisko (nazwiska);\n3)\timiona poprzednie;\n4)\tnazwiska poprzednie;\n5)\tdata urodzenia;\n6)\tpłeć;\n7)\timię (imiona) ojca;\n8)\timię (imiona) matki;\n9)\tkraj urodzenia;\n10)\tmiejsce urodzenia;\n11)\tobywatelstwa;\n12)\tnarodowość;\n13)\tinformacje o wydanych cudzoziemcowi lub posiadanych przez cudzoziemca dokumentach:\na)\trodzaj dokumentu,\nb)\tseria i numer dokumentu,\nc)\tdata wydania dokumentu,\nd)\tdata ważności dokumentu,\ne)\tkraj wydania dokumentu,\nf)\torgan wydający dokument,\ng)\tmiejsce wydania dokumentu;\n14)\todciski linii papilarnych;\n15)\twizerunek twarzy;\f16)\tGIC;\n17)\tnumer PESEL, o ile został nadany;\n18)\tinne krajowe lub zagraniczne numery identyfikacyjne, o ile zostały nadane;\n19)\tidentyfikatory cudzoziemca w systemie źródłowym, jeśli istnieją;\n20)\tidentyfikator systemu źródłowego, jeśli istnieje;\n21)\tinformacje o: wnioskach, postanowieniach, decyzjach, wyrokach sądów, kontrolach, czynnościach w zakresie wydania, odmowy wydania, unieważnienia lub cofnięcia dokumentów oraz o innych rozstrzygnięciach lub czynnościach, w tym czynnościach materialnotechnicznych obejmujących w szczególności wpis, rejestrację, dotyczących cudzoziemca, przetwarzanych w systemie źródłowym, zwanych dalej „zdarzeniami”, obejmujących:\na)\toznaczenie systemu źródłowego,\nb)\tidentyfikator zdarzenia,\nc)\tnazwę organu rejestrującego zdarzenie,\nd)\tnazwę zdarzenia,\ne)\tdatę zdarzenia,\nf)\tidentyfikator sprawy, jeśli istnieje.\n7. Organ lub podmiot, o którym mowa w ust. 3 pkt 1–7 i 9–10, informuje niezwłocznie Komendanta Głównego Straży Granicznej o każdej zmianie w zakresie danych i informacji dotyczących cudzoziemców, przetwarzanych w systemie źródłowym, a także innych zasad i sposobu prowadzenia systemu źródłowego, mogących mieć wpływ na ciągłość zasilania KRC.\n8. Organ lub podmiot, o którym mowa w ust. 3 pkt 1–7 i 9–10, oraz Komendant Główny Straży Granicznej współdziałają w przypadku awarii KRC lub systemu źródłowego,  mających wpływ na ciągłość zasilania KRC.\n9. Dane i informacje dotyczące cudzoziemców przetwarzane w KRC udostępnia się wyłącznie w drodze teletransmisji i w zakresie niezbędnym do realizacji ustawowych zadań, następującym organom i podmiotom:\n1)\tministrowi właściwemu do spraw wewnętrznych;\n2)\tministrowi właściwemu do spraw zagranicznych;\n3)\tministrowi właściwemu do spraw pracy;\n4)\tministrowi właściwemu do spraw rodziny;\n5)\tministrowi właściwemu do spraw zabezpieczenia społecznego;\f6)\tministrowi właściwemu do spraw szkolnictwa wyższego i nauki;\n7)\tSzefowi Urzędu do Spraw Cudzoziemców;\n8)\tStraży Granicznej;\n9)\tPolicji;\n10)\tkonsulom;\n11)\twojewodom;\n12)\tPaństwowej Inspekcji Pracy;\n13)\tZakładowi Ubezpieczeń Społecznych;\n14)\tRadzie do Spraw Uchodźców;\n15)\torganom ochrony porządku publicznego i bezpieczeństwa państwa;\n16)\tinnym organom administracji publicznej realizującym czynności administracyjne dotyczące cudzoziemców.\n10. Dane oraz informacje, o których mowa w ust. 6 pkt 12, 14, 15 i 19–21, są udostępniane jeżeli organy i inne podmioty, o których mowa w ust. 9, posiadają na podstawie odrębnych przepisów uprawnienia do dostępu do tych danych lub informacji przetwarzanych w systemach źródłowych.\n11. Organy i inne podmioty, o których mowa w ust. 9 pkt 1–7 i 9–16, w celu uzyskania danych przetwarzanych w KRC, spełniają łącznie następujące warunki:\n1)\tposiadają urządzenia umożliwiające odnotowanie w ich systemie teleinformatycznym kto, kiedy, w jakim celu oraz jakie dane uzyskał,\n2)\tposiadają zabezpieczenia techniczne i organizacyjne uniemożliwiające wykorzystanie danych niezgodnie z celem ich uzyskania\n– uzgodnione z Komendantem Głównym Straży Granicznej w drodze pisemnego porozumienia.\n12. Dane przetwarzane w KRC są przechowywane przez okres ich przechowywania w systemach źródłowych, określony w odrębnych przepisach dotyczących tych systemów. Po upływie tego okresu, dane są automatycznie usuwane z KRC.\n13. Komendant Główny Straży Granicznej jest administratorem danych przetwarzanych w KRC.\n14. Komendant Główny Straży Granicznej zapewnia właściwą eksploatację techniczną i bezpieczeństwo funkcjonowania KRC oraz ochronę danych przetwarzanych w KRC.\f15. Komendant Główny Straży Granicznej stosuje środki techniczne i organizacyjne w celu skutecznej ochrony danych osobowych, odpowiednie do zagrożeń oraz do kategorii danych objętych ochroną. Środki te w szczególności zapewniają, aby dane osobowe nie były udostępniane nieupoważnionym osobom fizycznym lub innym nieupoważnionym podmiotom.\n16. W przypadku gdy Komendant Główny Straży Granicznej, inny organ administracji publicznej lub inny podmiot realizujący zadania publiczne posiada informacje, że dane przetwarzane w systemie źródłowym są niezgodne z prawdą lub są nieaktualne, informuje o tym, w formie elektronicznej, organ lub inny podmiot, który prowadzi system źródłowy. Właściwy organ lub podmiot, który prowadzi system źródłowy, dokonuje weryfikacji danych i w przypadku potwierdzenia, że dane są niezgodne z prawdą lub nieaktualne, dokonuje odpowiednich zmian danych przetwarzanych w systemie źródłowym, zawiadamiając o tym organ lub podmiot, który przekazał informacje.\n17. Minister właściwy do spraw wewnętrznych uczestniczy w realizacji zadań związanych z rozwojem i utrzymaniem KRC.\n18. Minister właściwy do spraw wewnętrznych określi, w drodze rozporządzenia, warunki techniczne umożliwiające integrację systemów źródłowych z KRC w celu jego zasilania w zakresie danych i informacji przetwarzanych w tych systemach, a także terminy oraz sposób postępowania w przypadku awarii KRC lub systemu źródłowego, mając na względzie zapewnienie bezpieczeństwa i ochrony danych.”;\n2)\tw art. 3a w pkt 8 kropkę zastępuje się średnikiem i dodaje się pkt 9 w brzmieniu:\n„9)\tpełnienie funkcji jednostki krajowej ETIAS, o której mowa w rozporządzeniu Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.).”.\fArt. 40. W ustawie z dnia 24 maja 2000 r. o Krajowym Rejestrze Karnym (Dz. U. z 2024 r. poz. 276, z 2025 r. poz. 1235 oraz z 2026 r. poz. 252, 421 i 760) wprowadza się następujące zmiany:\n1)\tw art. 6 w ust. 1:\na)\tw pkt 7 po wyrazach „w ustawie” dodaje się wyrazy „lub przepisach prawa Unii Europejskiej”,\nb)\tpkt 9–10a otrzymują brzmienie:\n„9)\torganom administracji rządowej, organom samorządu terytorialnego oraz innym organom wykonującym zadania publiczne, w przypadkach kiedy jest to uzasadnione potrzebą wykonania nałożonych na nie zadań, określonych w ustawie lub przepisach prawa Unii Europejskiej;\n10)\tpracodawcom, w zakresie niezbędnym dla zatrudnienia pracownika, co do którego z przepisów ustawy lub przepisów prawa Unii Europejskiej wynika wymóg niekaralności, korzystania z pełni praw publicznych, a także ustalenia uprawnienia do zajmowania określonego stanowiska, wykonywania określonego zawodu lub prowadzenia określonej działalności gospodarczej;\n10a)\tosobom prawnym oraz jednostkom organizacyjnym niebędącym osobami prawnymi, którym ustawa przyznaje zdolność prawną – w przypadkach, w których z przepisów ustawy lub przepisów prawa Unii Europejskiej wynika wymóg niekaralności członków ich organów, wspólników lub prokurentów, w odniesieniu do członków lub kandydatów na członków tych organów, wspólników lub prokurentów;”;\n2)\tw art. 19 ust. 1aa otrzymuje brzmienie:\n„1aa. Jeżeli przepisy szczególne nie ograniczają zakresu udzielonej informacji, podmioty wymienione w art. 6 ust. 1 pkt 4–7 i 8 mogą uzyskiwać informacje o osobie lub informacje o podmiocie zbiorowym na podstawie danych zgromadzonych w Rejestrze także na żądanie, z wyjątkiem przypadku gdy występują o informację o osobie będącej obywatelem państwa trzeciego lub obywatelem państwa członkowskiego Unii Europejskiej, która posiada co najmniej jedno obywatelstwo państwa trzeciego, w celach, o których mowa w art. 7 ust. 1 rozporządzenia 2019/816, chyba że wystąpienie o informację następuje po uprzednim sprawdzeniu osoby w systemie ECRISTCN albo podmiot występujący o informację odstąpił od skorzystania z systemu ECRISTCN.”.\fArt. 41. W ustawie z dnia 13 czerwca 2003 r. o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej (Dz. U. z 2026 r. poz. 862) wprowadza się następujące zmiany:\n1)\tw art. 88b ust. 1 otrzymuje brzmienie:\n„1. Sąd rejonowy właściwy ze względu na siedzibę wnioskującego organu Straży Granicznej, wydaje postanowienie o umieszczeniu wnioskodawcy lub osoby, w której imieniu wnioskodawca występuje, w strzeżonym ośrodku lub o zastosowaniu wobec niej aresztu dla cudzoziemców. Sąd wydaje postanowienie po wysłuchaniu wnioskodawcy lub osoby, w której imieniu wnioskodawca występuje.”;\n2)\tw art. 89n dodaje się ust. 4 i 5 w brzmieniu:\n„4. Szef Urzędu niezwłocznie informuje Komendanta Głównego Straży Granicznej o wydaniu dokumentu podróży, o którym mowa w ust. 1, cudzoziemcowi posiadającemu ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 i 44 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240”.\n5. W przypadku, o którym mowa w art. 55 ust. 6 rozporządzenia 2018/1240, Szef Urzędu po wydaniu karty pobytu cudzoziemcowi, jej wymianie lub wydaniu kolejnej karty pobytu cudzoziemcowi przekazuje niezwłocznie, na wniosek cudzoziemca, Komendantowi Głównemu Straży Granicznej, informacje o posiadaniu przez cudzoziemca, któremu została wydana lub wymieniona karta pobytu, ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 lub art. 44 ust.1 rozporządzenia 2018/1240.”.\nArt. 42. W ustawie z dnia 14 lipca 2006 r. o wjeździe na terytorium Rzeczypospolitej Polskiej, pobycie oraz wyjeździe z tego terytorium obywateli państw członkowskich Unii Europejskiej i członków ich rodzin (Dz. U. z 2025 r. poz. 1164 i 1794) wprowadza się następujące zmiany:\n1)\tpo art. 8c dodaje się art. 8d w brzmieniu:\n„Art. 8d. Wojewoda, który wydał, wymienił lub wydał nową kartę pobytową lub kartę stałego pobytu albo który wydał, wymienił lub wydał nowe zaświadczenie o zarejestrowaniu pobytu lub dokument potwierdzający prawo stałego pobytu \fobywatelowi Zjednoczonego Królestwa niezwłocznie informuje Komendanta Głównego Straży Granicznej o wydaniu tego dokumentu cudzoziemcowi posiadającemu ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 i 44 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240”„;\n2)\tw art. 9 dodaje się ust. 4 w brzmieniu:\n„4. Członek rodziny niebędący obywatelem UE, o którym mowa w ust. 3 pkt 1, może wjechać na terytorium Rzeczypospolitej Polskiej, o ile posiada ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 lub 44 ust. 1 rozporządzenia 2018/1240, uprawniające do wjazdu na terytorium Rzeczypospolitej Polskiej, jeżeli jest wymagane.”;\n3)\tw art. 11 w ust. 1 pkt 3 otrzymuje brzmienie:\n„3)\tnie posiada dokumentu, o którym mowa odpowiednio w art. 9 ust. 1 lub 2, lub zezwolenia na podróż, o którym mowa w art. 9 ust. 4, chyba że udowodni w inny, niebudzący wątpliwości sposób, że jest uprawniony do korzystania ze swobody przepływu osób, lub”;”;\n4)\tart. 12 otrzymuje brzmienie:\n„Art. 12. Komendant placówki Straży Granicznej umożliwia obywatelowi UE lub członkowi rodziny niebędącemu obywatelem UE, przez okres nie dłuższy niż 72 godziny przed wydaniem decyzji o odmowie wjazdu na terytorium Rzeczypospolitej Polskiej, podjęcie działań zmierzających do uzyskania dokumentów, o których mowa odpowiednio w art. 9 ust. 1 lub 2, lub zezwolenia na podróż, o którym mowa w art. 9 ust. 4, albo do udowodnienia w inny, niebudzący wątpliwości sposób, że osoby te są uprawnione do korzystania ze swobody przepływu osób.”;\n5)\tw art. 78e ust. 2 otrzymuje brzmienie:\n„2. Postanowienie, o którym mowa w ust. 1, wydaje na wniosek organu Straży Granicznej, sąd rejonowy właściwy ze względu na siedzibę wnioskującego organu Straży Granicznej.”.\nArt. 43. W ustawie z dnia 16 listopada 2006 r. o opłacie skarbowej (Dz. U. z 2025 r. poz. 1154, 1795 i 1847 oraz z 2026 r. poz. 846, 875 i 912) w załączniku do ustawy wprowadza się następujące zmiany:\f1)\tw części I po ust. 52d dodaje się ust. 52e w brzmieniu:\n\t52e. Przyjęcie i rozpatrzenie wniosku o cofnięcie zakazu ponownego wjazdu: 1) na terytorium Rzeczypospolitej Polskiej  2) na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen\t  350 zł\t \n2)\tw części III w kolumnie 3:\na)\tw ust. 6:\n– w pkt 1 wyrazy „40 euro” zastępuje się wyrazami „45 euro”,\n– w pkt 2 wyrazy „80 euro” zastępuje się wyrazami „90 euro”,\nb)\tw ust. 6a wyrazy „120 lub 160 euro” zastępuje się wyrazami „135 lub 180 euro”.\n\nArt. 44. W ustawie z dnia 24 sierpnia 2007 r. o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym (Dz. U. z 2023 r. poz. 1355 oraz z 2024 r. poz. 1688) wprowadza się następujące zmiany:\n1)\tw art. 4 po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Uprawnienie do bezpośredniego dostępu do Krajowego Systemu Informatycznego (KSI) w celu wglądu do danych SIS przysługuje Straży Granicznej również w związku z rozpatrywaniem wniosku o wydanie zezwolenia na podróż, unieważnieniem albo cofnięciem zezwolenia na podróż, zgodnie z art. 8 ust. 2 lit. a, d, e albo g rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży  oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240”.”;\n2)\tw art. 6 po pkt 8 dodaje się pkt 8a w brzmieniu:\n„8a)\trozpatrzenia wniosku o wydanie zezwolenia na podróż, unieważnienia albo cofnięcia zezwolenia na podróż, zgodnie z art. 8 ust. 2 lit. a, d, e albo g rozporządzenia 2018/1240, przysługuje Straży Granicznej;”.\fArt. 45. W ustawie z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (Dz. U. z 2025 r. poz. 1675 oraz z 2026 r. poz. 26 i 791) wprowadza się następujące zmiany:\n1)\tpo art. 25 dodaje się art. 25a i art. 25b w brzmieniu:\n„Art. 25a. 1. Główny Inspektor Sanitarny, państwowi wojewódzcy inspektorzy sanitarni oraz państwowi graniczni inspektorzy sanitarni tworzą Wspólny Punkt Kontaktowy Państwowej Inspekcji Sanitarnej, zwany dalej „Wspólnym Punktem Kontaktowym”, właściwy w sprawach zagrożeń transgranicznych, w szczególności współpracy z właściwymi organami Straży Granicznej.\n2. Współpraca, o której mowa w ust. 1, obejmuje w szczególności wydawanie opinii w ramach konsultacji krajowych, o których mowa w art. 10 ustawy z dnia …… o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) (Dz. U. poz. …).\n3. W ramach działalności Wspólnego Punktu Kontaktowego państwowi wojewódzcy inspektorzy sanitarni oraz graniczni inspektorzy sanitarni posiadają dostęp do danych przetwarzanych w rejestrze, o którym mowa w art. 30 ust. 1, niezależnie od swojej właściwości miejscowej.\n4. Główny Inspektor Sanitarny określi, w drodze zarządzenia, w dzienniku urzędowym ministra właściwego do spraw zdrowia, organizację Wspólnego Punktu Kontaktowego, sposobu jego funkcjonowania i realizacji zadań.\nArt. 25b. 1. Jeżeli w toku kontroli granicznej jest konieczne zasięgnięcie opinii Wspólnego Punktu Kontaktowego z uwagi na zagrożenie dla zdrowia publicznego jakie może stanowić wjazd lub pobyt cudzoziemca na terytorium Rzeczypospolitej Polskiej, w tym wysokie ryzyko epidemiczne związane z markerem, o którym mowa w art. 47 ust. 2 lit. b rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem (UE) 2018/1240”, komendant placówki Straży Granicznej występuje o przedstawienie takiej opinii.\n2. Komendant placówki Straży Granicznej przekazuje Wspólnemu Punktowi Kontaktowemu dokumenty, informacje lub wyjaśnienia przedstawione przez \fcudzoziemca w toku kontroli granicznej, celem dokonania weryfikacji i oceny stwarzania zagrożenia dla zdrowia publicznego, w tym wysokiego ryzyka epidemicznego.\n3. Wspólny Punkt Kontaktowy przekazuje komendantowi placówki Straży Granicznej opinię, o której mowa w ust. 1, niezwłocznie, lecz nie później niż w ciągu 12 godzin od momentu wystąpienia o jej przedstawienie.\n4. Nieprzekazanie opinii w wyznaczonym terminie, o którym mowa w ust. 3, traktuje się jako pozytywną opinię dotyczącą cudzoziemca w zakresie braku stwarzania zagrożenia dla zdrowia publicznego, w tym wysokiego ryzyka epidemicznego.”;\n2)\tw art. 30 po ust. 4 dodaje się ust. 4a w brzmieniu:\n„4a. Zgromadzone w rejestrze chorób zakaźnych dane cudzoziemców w zakresie, o którym mowa w ust. 2 pkt 1–8, a także aktualne dane o:\n1)\tprzebywaniu na izolacji lub izolacji w warunkach domowych lub naruszeniu tego obowiązku,\n2)\tprzebywaniu na kwarantannie lub naruszeniu tego obowiązku,\n3)\tobowiązku leczenia lub naruszeniu tego obowiązku\n–\tsą udostępniane, w drodze teletransmisji, właściwym organom Straży Granicznej w związku z prowadzonymi przez nie czynnościami realizowanymi w celu weryfikacji zagrożenia dla zdrowia publicznego, w tym wysokiego ryzyka epidemicznego w związku z rozporządzeniem (UE) 2018/1240.”.\nArt. 46. W ustawie z dnia 2 kwietnia 2009 r. o obywatelstwie polskim (Dz. U. z 2025 r. poz. 1611) wprowadza się następujące zmiany:\n1)\tpo art. 4 dodaje się art. 4a w brzmieniu:\n„Art. 4a. Wojewoda lub minister właściwy do spraw wewnętrznych, każdy w zakresie swojej właściwości, niezwłocznie informuje Komendanta Głównego Straży Granicznej o nabyciu obywatelstwa polskiego przez osobę posiadającą ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 i 44 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240.”;\f2)\tpo art. 55 dodaje się art. 55a w brzmieniu:\n„Art. 55a. Wojewoda lub minister właściwy do spraw wewnętrznych, w zakresie swojej właściwości, niezwłocznie informuje Komendanta Głównego Straży Granicznej o potwierdzeniu, na podstawie art. 55, posiadania obywatelstwa polskiego przez osobę, która posiada ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 lub  44 ust. 1 rozporządzenia 2018/1240.”.\nArt. 47. W ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach (Dz. U. z 2025 r. poz. 1079 i 1794 oraz z 2026 r. poz. 203) wprowadza się następujące zmiany:\n1)\tw art. 28 w ust. 1 po pkt 7 dodaje się pkt 7a w brzmieniu:\n„7a)\tjego wjazd następuje w okresie obowiązywania zakazu ponownego wjazdu na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen albo zakazu ponownego wjazdu tylko na terytorium Rzeczypospolitej Polskiej, lub”;\n2)\tpo art. 79b dodaje się art. 79c:\n„Art. 79c. W przypadku, o którym mowa w art. 55 ust. 6 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240”, organ, który wydał wizę Schengen lub wizę krajową, przekazuje niezwłocznie, na wniosek cudzoziemca, Komendantowi Głównemu Straży Granicznej informacje o wydaniu tej wizy cudzoziemcowi posiadającemu ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 lub 44 ust. 1 rozporządzenia 2018/1240.”;\n3)\tw art. 85 w ust. 1 po wyrazach „Rzeczypospolitej Polskiej” dodaje się wyrazy „na podstawie tej wizy”;\n4)\tw art. 99 w ust. 1 po pkt 8 dodaje się pkt 8a w brzmieniu:\n„8a)\tprzebywa na terytorium Rzeczypospolitej Polskiej w ramach ruchu bezwizowego i posiada zezwolenie na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, lub”;\n5)\tw art. 100 w ust. 1 w pkt 9 kropkę zastępuje się przecinkiem, dodaje się wyraz „lub” oraz dodaje się pkt 10 w brzmieniu:\n„10)\tzłożył wniosek podczas pobytu na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia \f2018/1240, jeżeli było ono wymagane zgodnie z rozporządzeniem 2018/1240, lub przebywa na tym terytorium bez tego zezwolenia, jeżeli jest ono wymagane.”;\n6)\tw art. 105 ust. 1 otrzymuje brzmienie:\n„1. Cudzoziemiec składa wniosek o udzielenie mu zezwolenia na pobyt czasowy nie później niż w ostatnim dniu jego legalnego pobytu na terytorium Rzeczypospolitej Polskiej oraz nie później niż w ostatnim dniu ważności zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem.”;\n7)\tużyte w art. 132 we wprowadzeniu do wyliczenia, w art.137c, w art. 147 w ust. 1 we wprowadzeniu do wyliczenia i w ust. 2, w art. 154 w ust. 1–3, w art. 157d w ust. 1 we wprowadzeniu do wyliczenia i w ust. 2, w art. 157j w ust. 1 we wprowadzeniu do wyliczenia i w ust. 2, w art. 164 oraz w art. 165 w ust. 1a, w różnej liczbie i różnym przypadku wyrazy „art. 100 ust. 1 pkt 1–5, 8 i 9” zastępuje się użytymi w odpowiedniej liczbie i odpowiednim przypadku wyrazami „art. 100 ust. 1 pkt 1–5 i 8–10”;\n8)\tw art. 139f w ust. 2 pkt 3 otrzymuje brzmienie:\n„3)\twniosek o udzielenie tego zezwolenia został złożony podczas nielegalnego pobytu na terytorium Rzeczypospolitej Polskiej cudzoziemca, któremu ma być ono udzielone, albo podczas pobytu tego cudzoziemca na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli było ono wymagane zgodnie z tym rozporządzeniem.”;\n9)\tw art. 139l ust. 1 otrzymuje brzmienie:\n„1. Jednostka przyjmująca składa wniosek o udzielenie kolejnego zezwolenia, o którym mowa w art. 139a ust. 1, nie później niż w ostatnim dniu legalnego pobytu cudzoziemca na terytorium Rzeczypospolitej Polskiej na podstawie tego zezwolenia.”;\n10)\tw art. 139s w ust. 1 pkt 5 otrzymuje brzmienie:\n„5)\twniosek o udzielenie zezwolenia na pobyt czasowy został złożony podczas nielegalnego pobytu na terytorium Rzeczypospolitej Polskiej cudzoziemca, któremu ma być ono udzielone albo podczas pobytu tego cudzoziemca na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli było ono wymagane zgodnie z tym rozporządzeniem.”;\f11)\tw art. 139t ust. 1 otrzymuje brzmienie:\n„1. Jednostka przyjmująca składa wniosek o udzielenie zezwolenia, o którym mowa w art. 139o ust. 1, cudzoziemcowi, który przebywa na terytorium Rzeczypospolitej Polskiej, nie później niż w ostatnim dniu jego legalnego pobytu na tym terytorium oraz nie później niż w ostatnim dniu ważności zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem.”;\n12)\tw art. 141 wyrazy „Przepisu art. 100 ust. 1 pkt 9” zastępuje się wyrazami „Przepisów art. 100 ust. 1 pkt 9 i 10”;\n13)\tw art. 165:\na)\tust. 3 otrzymuje brzmienie:\n„3. Cudzoziemcowi, o którym mowa w art. 158 ust. 1 pkt 2 lub art. 160 pkt 2, nie można odmówić udzielenia zezwolenia na pobyt czasowy, jeżeli wyłączną przyczyną odmowy byłby nielegalny pobyt tego cudzoziemca na terytorium Rzeczypospolitej Polskiej albo pobyt tego cudzoziemca na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli było ono wymagane zgodnie z tym rozporządzeniem.”,\nb)\tw ust. 4 wyrazy „przepisu art. 100 ust. 1 pkt 9” zastępuje się wyrazami „przepisów art. 100 ust. 1 pkt 9 i 10”;\n14)\tw art. 178 wyrazy „art. 100 ust. 1 pkt 2, 3 i 6–9” zastępuje się wyrazami „art. 100 ust. 1 pkt 2, 3 i 6–10”;\n15)\tw art. 185b wyrazy „art. 100 ust. 1 pkt 2–9” zastępuje się wyrazami „art. 100 ust. 1 pkt 2–10”;\n16)\tw art. 187 w pkt 6 i 7 po wyrazach „cudzoziemiec przebywa na terytorium Rzeczypospolitej Polskiej nielegalnie” dodaje się wyrazy „albo bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem”;\n17)\tw art. 191:\na)\tw ust. 1:\n–\tw pkt 1 wyrazy „art. 100 ust. 1 pkt 9” zastępuje się wyrazami „art. 100 ust. 1 pkt 9 i 10”,\f–\tw pkt 4 wyrazy „art. 100 ust. 1 pkt 2 i 3 oraz 6–9” zastępuje się wyrazami „art. 100 ust. 1 pkt 2 i 3 oraz 6–10”,\nb)\tust. 2 otrzymuje brzmienie:\n„2. Cudzoziemcowi, który osiągnął pełnoletność w trakcie pobytu na terytorium Rzeczypospolitej Polskiej i złożył wniosek o udzielenie mu zezwolenia na pobyt czasowy ze względu na inne okoliczności w ciągu 1 roku od dnia, w którym osiągnął pełnoletność, nie można odmówić udzielenia tego zezwolenia, gdy przemawia za tym szczególnie ważny interes cudzoziemca, a wyłączną podstawą odmowy byłby jego nielegalny pobyt na terytorium Rzeczypospolitej Polskiej albo jego pobyt na tym terytorium bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240,  jeżeli jest ono wymagane zgodnie z tym rozporządzeniem.”;\n18)\tw art. 196:\na)\tw ust. 1 w pkt 1:\n–\tpo lit. a dodaje się lit. aa w brzmieniu:\n„aa)\tbez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli było ono wymagane zgodnie z tym rozporządzeniem, lub”,\n–\tdodaje się lit. e w brzmieniu:\n„e)\tw ramach ruchu bezwizowego i posiada zezwolenie na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, lub”,\nb)\tw ust. 3 wyrazy „Przepisu ust. 1 pkt 1 lit. a” zastępuje się wyrazami „Przepisów ust. 1 pkt 1 lit. a, aa oraz e”;\n19)\tw art. 202 ust. 1 otrzymuje brzmienie:\n„1. Cudzoziemiec składa wniosek o udzielenie mu zezwolenia na pobyt stały, nie później niż w ostatnim dniu jego legalnego pobytu na terytorium Rzeczypospolitej Polskiej oraz nie później niż w ostatnim dniu ważności zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem.”;\n20)\tw art. 206 w ust. 1 wprowadzenie do wyliczenia otrzymuje brzmienie:\n„Jeżeli termin na złożenie wniosku o udzielenie cudzoziemcowi zezwolenia na pobyt stały został zachowany i wniosek nie zawiera braków formalnych lub braki formalne zostały uzupełnione w terminie:”;\f21)\tw art. 213 w ust. 1 w pkt 1:\na)\tpo lit. a dodaje się lit. aa w brzmieniu:\n„aa)\tbez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem, lub”,\nb)\tdodaje się lit. i w brzmieniu:\n„i)\tw ramach ruchu bezwizowego oraz posiada zezwolenie na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, lub”;\n22)\tw art. 218a ust. 1 otrzymuje brzmienie:\n„1. Cudzoziemiec składa wniosek o udzielenie mu zezwolenia na pobyt rezydenta długoterminowego UE, nie później niż w ostatnim dniu jego legalnego pobytu na terytorium Rzeczypospolitej Polskiej oraz nie później niż w ostatnim dniu ważności zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem.”;\n23)\tw art. 222a w ust. 1 wprowadzenie do wyliczenia otrzymuje brzmienie:\n„Jeżeli termin na złożenie wniosku o udzielenie cudzoziemcowi zezwolenia na pobyt rezydenta długoterminowego UE został zachowany i wniosek nie zawiera braków formalnych lub braki formalne zostały uzupełnione w terminie:”;\n24)\tpo art. 248a dodaje się art. 248b w brzmieniu:\n„Art. 248b. W przypadku, o którym mowa w art. 55 ust. 6 rozporządzenia 2018/1240, organ, który wydał lub wymienił kartę pobytu, przekazuje niezwłocznie, na wniosek cudzoziemca, Komendantowi Głównemu Straży Granicznej, informacje o wydaniu lub wymianie karty pobytu cudzoziemcowi posiadającemu ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 lub art. 44 ust. 1 rozporządzenia 2018/1240.”;\n25)\tw art. 299:\na)\tpo ust. 2 dodaje się ust. 2a w brzmieniu:\n„2a. Cudzoziemiec jest obowiązany opuścić terytorium Rzeczypospolitej Polskiej przed upływem okresu ważności zezwolenia na podróż uprawniającego do wjazdu i pobytu na terytorium Rzeczypospolitej Polskiej, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240.”,\nb)\tust. 7 i 8 otrzymują brzmienie:\n„7. Pobyt cudzoziemca na terytorium Rzeczypospolitej Polskiej w okresie, o którym mowa w ust. 6 i 6a, uważa się za legalny, chyba że wniosek o przedłużenie \fmu wizy Schengen lub wizy krajowej lub o udzielenie mu zezwolenia na pobyt czasowy, zezwolenia na pobyt stały lub zezwolenia na pobyt rezydenta długoterminowego UE został złożony po upływie okresu jego legalnego pobytu na tym terytorium lub po upływie ważności zezwolenia na podróż, jeżeli było ono wymagane zgodnie z rozporządzeniem 2018/1240.\n8. Przepisów ust. 1, 2, 56a nie stosuje się, jeżeli cudzoziemiec posiada ważny dokument uprawniający go do pobytu na terytorium Rzeczypospolitej Polskiej lub z niniejszej ustawy, z innych ustaw lub aktów prawa Unii Europejskiej wynika, że jego pobyt na tym terytorium uważa się za legalny oraz posiada ważne zezwolenie na podróż, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240.”,\nc)\tpo ust. 8a dodaje się ust. 8b w brzmieniu:\n„8b. Przepisów ust. 2a nie stosuje się, jeżeli cudzoziemiec posiada ważny dokument uprawniający go do pobytu na terytorium Rzeczypospolitej Polskiej lub z niniejszej ustawy, z innych ustaw lub aktów prawa Unii Europejskiej wynika, że jego pobyt na tym terytorium uważa się za legalny, z wyłączeniem pobytu, o którym mowa w art. 299 ust. 2.”,\nd)\t\tw ust. 9 pkt 2 otrzymuje brzmienie:\n„2)\tdecyzja o odmowie nadania statusu uchodźcy lub udzielenia ochrony uzupełniającej lub o uznaniu wniosku o udzielenie ochrony międzynarodowej za niedopuszczalny lub o umorzeniu postępowania w sprawie udzielenia ochrony międzynarodowej została wydana w związku ze złożeniem kolejnego wniosku o udzielenie ochrony międzynarodowej, lub”;\n26)\tw art. 300\na)\tust. 2 otrzymuje brzmienie:\n„2. Cudzoziemiec składa wniosek o przedłużenie okresu pobytu w ramach ruchu bezwizowego na terytorium Rzeczypospolitej Polskiej osobiście, nie później niż w ostatnim dniu roboczym jego legalnego pobytu na tym terytorium w ramach ruchu bezwizowego oraz nie później niż w ostatnim dniu ważności zezwolenia na podróż, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240, i uzasadnia ten wniosek.”,\nb)\tpo ust. 2 dodaje się ust. 2a w brzmieniu:\n„2a. Cudzoziemcowi odmawia się przedłużenia okresu pobytu w ramach ruchu bezwizowego na terytorium Rzeczypospolitej Polskiej, jeżeli w dniu złożenia \fwniosku przebywał na tym terytorium bez ważnego zezwolenia na podróż, jeżeli było ono wymagane zgodnie z rozporządzeniem 2018/1240, lub przebywa na tym terytorium bez tego zezwolenia, jeżeli jest wymagane.”;\n27)\tw art. 302:\na)\tw ust. 1:\n–\tpo pkt 1 dodaje się pkt 1a w brzmieniu:\n„1a)\tprzebywa lub przebywał na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż uprawniającego do wjazdu i pobytu na terytorium Rzeczypospolitej Polskiej, jeżeli jest lub było ono wymagane zgodnie z rozporządzeniem 2018/1240, lub”,\n–\tpo pkt 7 dodaje się pkt 7a w brzmieniu:\n„7a)\tobowiązuje zakaz ponownego wjazdu cudzoziemca na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen albo zakaz ponownego wjazdu tylko na terytorium Rzeczypospolitej Polskiej, lub”,\nb)\tpo ust. 3 dodaje się ust. 3a w brzmieniu:\n„3a. Przepisów ust. 1 pkt 1a nie stosuje się w przypadkach, o których mowa w art. 299 ust. 8b.”;\n28)\tw art. 314 ust. 1 otrzymuje brzmienie:\n„1. Organ właściwy do wydania decyzji o zobowiązaniu cudzoziemca do powrotu, w przypadkach, o których mowa w art. 302 ust. 1 pkt 1–8 i 10–16, poucza cudzoziemca posiadającego zezwolenie na pobyt lub zezwolenie na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, które nie uprawnia do wjazdu i pobytu na terytorium Rzeczypospolitej Polskiej, lub inne zezwolenie uprawniające go do pobytu, udzielone przez państwo stosujące dyrektywę 2008/115/WE, o obowiązku niezwłocznego wyjazdu na terytorium tego państwa.”;\n29)\tw art. 320:\na)\tust. 1 otrzymuje brzmienie:\n„1. Organ, który w pierwszej instancji wydał decyzję o zobowiązaniu cudzoziemca do powrotu, może cofnąć zakaz, o którym mowa w art. 318, na wniosek cudzoziemca, w drodze decyzji, jeżeli cudzoziemiec wykaże, że wykonał obowiązki wynikające z decyzji o zobowiązaniu cudzoziemca do powrotu, chyba że jego ponowny wjazd na terytorium Rzeczypospolitej Polskiej lub innych państw \fobszaru Schengen ma nastąpić ze względu na uzasadnione okoliczności, zwłaszcza ze względów humanitarnych.”,\nb)\tdodaje się ust. 4 w brzmieniu:\n„4. W sprawach o cofnięcie zakazu ponownego wjazdu nie stosuje się przepisu art. 261 § 4 pkt 3 Kodeksu postępowania administracyjnego.”;\n30)\tw art. 321 dodaje się ust. 3 i 4 w brzmieniu:\n„3. Załatwienie sprawy w postępowaniu odwoławczym powinno nastąpić nie później niż w terminie sześciu miesięcy od dnia otrzymania odwołania. Jeżeli odwołanie nie spełnia wymogów przewidzianych przepisami prawa, termin załatwienia sprawy biegnie od dnia uzupełnienia braków.\n4. W sprawach, o których mowa w ust. 1, obowiązek, o którym mowa w art. 54 § 2 ustawy z dnia 30 sierpnia 2002 r. Prawo o postępowaniu przed sądami administracyjnymi (Dz. U. z 2026 r. poz. 143), właściwy organ realizuje w terminie 90 dni od dnia otrzymania skargi.”;\n31)\tw art. 334:\na)\tw ust. 2 w pkt 7 kropkę zastępuje się przecinkiem i dodaje się wyraz „lub” oraz pkt 8 w brzmieniu:\n„8)\t\tna wniosek którego zostało umorzone postępowanie o udzielenie mu zezwolenia na pobyt czasowy, zezwolenia na pobyt stały lub zezwolenia na pobyt rezydenta długoterminowego UE.”,\nb)\tw ust. 5 po pkt 1 dodaje się pkt 1a w brzmieniu:\n„1a)\tw terminie 7 dni przed upływem terminu, o którym mowa w art. 299 ust. 6 pkt 1 lit. a – w przypadku, o którym mowa w ust. 2 pkt 8.”;\n32)\tw art. 397 w ust. 1 pkt 2 otrzymuje brzmienie:\n„2)\tStraż Graniczna – występuje do sądu rejonowego właściwego ze względu na siedzibę wnioskującego organu Straży Granicznej z wnioskiem o umieszczenie małoletniego cudzoziemca w placówce opiekuńczo–wychowawczej lub w strzeżonym ośrodku.”;\n33)\tw art. 401 ust. 2 otrzymuje brzmienie:\n„2. Postanowienie, o którym mowa w ust. 1, wydaje, na wniosek organu Straży Granicznej, sąd rejonowy właściwy ze względu na siedzibę wnioskującego organu Straży Granicznej.”;\f34)\tw art. 428 w ust. 1 pkt 6 otrzymuje brzmienie:\n„6)\trejestr pouczeń udzielonych cudzoziemcom posiadającym ważne zezwolenie na pobyt lub zezwolenie na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, które nie uprawnia do wjazdu i pobytu na terytorium Rzeczypospolitej Polskiej lub inne zezwolenie uprawniające do pobytu, udzielone przez państwo stosujące dyrektywę 2008/115/WE, o obowiązku niezwłocznego wyjazdu na terytorium tego państwa;”;\n35)\tw art. 430 ust. 8 otrzymuje brzmienie:\n„8. W rejestrze, o którym mowa w art. 428 ust. 1 pkt 6, przechowuje się dane cudzoziemców, którzy zostali pouczeni o obowiązku niezwłocznego wyjazdu z terytorium Rzeczypospolitej Polskiej na terytorium państwa członkowskiego Unii Europejskiej, które udzieliło im zezwolenia na pobyt lub zezwolenia na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, lub innego zezwolenia uprawniającego do pobytu.”;\n36)\tw art. 459 w ust. 1 po wyrazach „wymaganą wizę” dodaje się przecinek i wyrazy „ważne zezwolenie na podróż, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240”;\n37)\tw art. 462:\na)\tw ust. 1 po wyrazach „wymaganej wizy” dodaje się przecinek i wyrazy „ważnego zezwolenia na podróż, jeżeli jest ono wymagane, zgodnie z rozporządzeniem 2018/1240”,\nb)\tpo ust. 2 dodaje się ust. 2a w brzmieniu:\n„2a. Organ prowadzący postępowanie administracyjne w sprawie nałożenia kary administracyjnej, o której mowa w ust. 1, może wystąpić do Komendanta Głównego Straży Granicznej o udostępnienie danych z operacji przetwarzania danych przeprowadzonych przez przewoźnika w ramach portalu dla przewoźników, o którym mowa w art. 6 ust. 2 lit. k rozporządzenia 2018/1240.”,\nc)\tw ust. 3 w pkt 2 kropkę zastępuje się średnikiem i dodaje się pkt 3 w brzmieniu:\n„3)\tz powodu braku technicznej możliwości spowodowanej awarią jakiejkolwiek części systemu informacyjnego ETIAS, określonego w art. 6 rozporządzenia 2018/1240, nie mógł dokonać zapytania i uzyskać dostępu do danych dla przewoźników, o którym mowa w art. 45 ust. 1 rozporządzenia 2018/1240.”.\fArt. 48. W ustawie z dnia 25 czerwca 2015 r. Prawo konsularne (Dz. U. z 2026 r. poz. 711) w art. 34  po pkt 3 dodaje się pkt 3a w brzmieniu:\n„3a)\tprzeprowadza rozmowę z cudzoziemcem w sprawach dotyczących zezwolenia na podróż, sporządza i przekazuje opinię z tej rozmowy, a jeżeli dokonał zapisu rozmowy, przekazuje także jej zapis.”.\nArt. 49. W ustawie z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej (Dz. U. poz. 621 i 1794 oraz z 2026 r. poz. 203, 473 i 734):\n1)\tw art. 3 w ust. 3 w pkt 6 i w ust. 5 we wprowadzeniu do wyliczenia po wyrazach „ruchu bezwizowego” dodaje się wyrazy „oraz posiada ważne zezwolenia na podróż, o którym mowa w rozporządzeniu Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.), jeżeli jest ono wymagane.”;\n2)\tw art. 73 ust. 4–6 otrzymują brzmienie:\n„4. W rejestrze spraw dotyczących zezwoleń na pracę przetwarza się dane, o których mowa w art. 9 ust. 1, dane, o których mowa w art. 2c ust. 4 ustawy z dnia 12 października 1990 r. o Straży Granicznej (Dz. U. z 2026 r. poz. 367, 646, 815, 821, 864 i …. ), jak również informacje o dokumentach dołączanych w postępowaniu, postanowieniach, decyzjach administracyjnych i orzeczeniach sądu, w celu prowadzenia postępowań w sprawach zezwoleń na pracę oraz udostępniania danych uprawnionym organom i instytucjom.\n5. W rejestrze spraw dotyczących zezwoleń na pracę sezonową przetwarza się dane, o których mowa w art. 9 ust. 1 i art. 47, dane, o których mowa w art. 2c ust. 4 ustawy z dnia 12 października 1990 r. o Straży Granicznej, jak również informacje o dokumentach dołączanych w postępowaniu, postanowieniach, wpisach do ewidencji wniosków, zaświadczeniach, decyzjach administracyjnych i orzeczeniach sądu, w celu prowadzenia postępowań w sprawach zezwoleń na pracę sezonową oraz udostępniania danych uprawnionym organom i instytucjom.\n6. W rejestrze spraw dotyczących oświadczeń o powierzeniu pracy cudzoziemcowi przetwarza się dane, o których mowa w art. 62 ust. 1–3 i art. 70 ust. 1, 2 i 5, dane, o których mowa w art. 2c ust. 4 ustawy z dnia 12 października 1990 r. o Straży \fGranicznej, jak również informacje o dokumentach dołączanych w postępowaniu, postanowieniach, wpisach do ewidencji oświadczeń, decyzjach administracyjnych i orzeczeniach sądu, w celu prowadzenia postępowań w sprawach oświadczeń o powierzeniu pracy cudzoziemcowi oraz udostępniania danych uprawnionym organom i instytucjom.”;\n3)\tw art. 75 po ust. 4 dodaje się ust. 4a w brzmieniu:\n„4a. Organ prowadzący postępowanie w sprawie zezwolenia na pracę lub oświadczenia o powierzeniu pracy cudzoziemcowi wykorzystuje dane i informacje dotyczące cudzoziemca uzyskane z Krajowego Rejestru Cudzoziemców, o których mowa w art. 2c ust. 6 ustawy z dnia 12 października 1990 r. o Straży Granicznej.”.\n\nArt. 50. W ustawie z dnia 20 marca 2025 r. o rynku pracy i służbach zatrudnienia (Dz. U. poz. 620, 1746 i 1794 oraz z 2026 r. poz. 451, 507 i 734) w art. 47 wprowadza się następujące zmiany:\n1)\tw ust. 2 w pkt 22 kropkę zastępuje się przecinkiem i dodaje się pkt 23 w brzmieniu:\n„23)\tGłówny Identyfikator Cudzoziemca, o którym mowa w art. 2c ust. 4 ustawy z dnia 12 października 1990 r. o Straży Granicznej (Dz. U. z 2026 r. poz. 367, 646, 815, 821, 864 i …).”;\n2)\tw ust. 3:\na)\tw pkt 1 wyrazy „ust. 2 pkt 1–11, 13–15 i 20–22” zastępuje się wyrazami „ust. 2 pkt 1–11, 13–15 i 20–23”,\nb)\tw pkt 2 we wprowadzeniu do wyliczenia wyrazy „ust. 2 pkt 1–13, pkt 14 lit. e, pkt 15, 20 i 22” zastępuje się wyrazami „ust. 2 pkt 1–13, pkt 14 lit. e, pkt 15, 20, 22 i 23”,\nc)\tw pkt 3 wyrazy „ust. 2 pkt 1, 3, 4, pkt 5 lit. a, pkt 6 i 20” zastępuje się wyrazami „ust. 2 pkt 1, 3, 4, pkt 5 lit. a, pkt 6, 20 i 23”,\nd)\tw pkt 4 wyrazy „ust. 2 pkt 1–3, 7, pkt 8 lit. a i b, pkt 10 i 17” zastępuje się wyrazami „ust. 2 pkt 1–3, 7, pkt 8 lit. a i b, pkt 10, 17 i 23”,\ne)\tw pkt 6 we wprowadzeniu do wyliczenia wyrazy „ust. 2 pkt 1–7, 11, pkt 15 lit. a i pkt 21” zastępuje się wyrazami „ust. 2 pkt 1–7, 11, pkt 15 lit. a, pkt 21 i 23”,\nf)\tw pkt 9 wyrazy „ust. 2 pkt 1, 7, 8 i 10” zastępuje się wyrazami „ust. 2 pkt 1, 7, 8 ,10 i 23”,\fg)\tw pkt 10 wyrazy „ust. 2 pkt 1, 3 i 7” zastępuje się wyrazami „ust. 2 pkt 1, 3, 7 i 23”.”.\nArt. 51. W ustawie z dnia 15 maja 2026 r. o udziale Rzeczypospolitej Polskiej w systemie Eurodac (Dz. U. poz. 760) wprowadza się następujące zmiany:\n1)\tw art. 3:\na)\tw ust. 1 skreśla się wyrazy „w tym celu”,\nb)\tw ust. 2 wyrazy „COT Eurodac” zastępuje się wyrazami „komórki organizacyjnej, o której mowa w ust. 1”;\n2)\tw art. 5 w ust. 12 po wyrazach „dotyczących tych organów” dodaje się wyrazy „i jednostek”;\n3)\tw art. 17 w ust. 5 po wyrazach „art. 26 ust. 1” dodaje się wyrazy „rozporządzenia 2024/1358”;\n4)\tw art. 22 w ust. 4 po wyrazach „w tym” dodaje się wyraz „dotyczących”;\n5)\tw art. 26 ust. 1 otrzymuje brzmienie:\n„1. Osoba, której dane dotyczą, może zwrócić się z wnioskiem o dostęp do danych osobowych zapisanych w systemie Eurodac lub o ich sprostowanie, uzupełnienie, usunięcie lub ograniczenie ich przetwarzania, na podstawie art. 43 ust. 1 lub 2 rozporządzenia 2024/1358, do organu, który pobrał jej dane zgodnie z art. 9–15.”.\nRozdział 10\nPrzepisy przejściowe, dostosowujące i końcowe\nArt. 52. 1. Okres przejściowy oraz okres karencji w zakresie wymogu posiadania ważnego zezwolenia na podróż, na zasadach określonych w art. 83 rozporządzenia 2018/1240, stosuje się od daty uruchomienia systemu ETIAS, zgodnie z art. 88 ust. 5 rozporządzenia 2018/1240.\n2. W okresie przejściowym, o którym mowa w art. 83 ust. 1 rozporządzenia 2018/1240, nie stosuje się przepisów art. 99 ust. 1 pkt 8a, art. 100 ust. 1 pkt 10, art. 105 ust. 1, art. 132, art. 139f ust. 2 pkt 3, art. 139s ust. 1 pkt 5, art. 139t ust. 1, art. 141, art. 147 ust. 1 i 2, art. 154 ust. 1–3, art. 157d ust. 1 i 2, art. 164, art. 165 ust. 1a i 4, art. 178, art. 185b, art. 187 pkt 6 i 7, art. 191 ust. 1 pkt 1 i 4, art. 196 ust. 1 pkt 1 lit. aa oraz e, art. 202 ust. 1, art. 213 ust. 1 pkt 1 lit. aa oraz i, art. 218a ust 1, art. 299 ust. 2a oraz 7 i 8, art. 300 ust. 2 i 2a, art. 302 ust. 1 pkt 1a, art. 314 ust. 1, art. 459 ust. 1, art. 462 ust. 1, 2a i ust. 3 pkt 3 ustawy zmienianej w art. 47 w brzmieniu nadanym niniejszą ustawą.\f3. Jeżeli w okresie karencji, o którym mowa w art. 83 ust. 3 zdanie pierwsze rozporządzenia 2018/1240, zezwolono cudzoziemcowi na przekroczenie granicy zewnętrznej w przypadku, o którym mowa w art. 83 ust. 3 zdanie trzecie rozporządzenia 2018/1240, nie stosuje się do niego przepisów art. 99 ust. 1 pkt 8a, art. 100 ust. 1 pkt 10, art. 105 ust. 1, art. 132, art. 139f ust. 2 pkt 3, art. 139s ust. 1 pkt 5, art. 139t ust. 1, art. 141, art. 147 ust. 1 i 2, art. 154 ust. 1–3, art. 157d ust. 1 i 2, art. 164, art. 165 ust. 1a i 4, art. 178, art. 185b, art. 187 pkt 6 i 7, art. 191 ust. 1 pkt 1 i 4, art. 196 ust. 1 pkt 1 lit. aa oraz e, art. 202 ust. 1, art. 213 ust. 1 pkt 1 lit. aa oraz i, art. 218a ust 1, art. 299 ust. 2a oraz 7 i 8, art. 300 ust. 2 i 2a, art. 302 ust. 1 pkt 1a, art. 314 ust. 1, art. 459 ust. 1, art. 462 ust. 1, 2a i ust. 3 pkt 3 ustawy zmienianej w art. 47 w brzmieniu nadanym niniejszą ustawą w okresie jego pobytu na terytorium Rzeczypospolitej Polskiej następującego po tym przekroczeniu.\nArt. 53. Straż Graniczna i konsulowie współpracują z Komisją Europejską w celu realizacji kampanii informacyjnej zgodnie z art. 72 w związku z art. 83 ust. 2–4 i 5 rozporządzenia 2018/1240.\nArt. 54. Komendant Główny Straży Granicznej współpracuje w zakresie przeprowadzania kompleksowego testu ETIAS, zgodnie z art. 88 ust. 2 rozporządzenia 2018/1240.\nArt. 55. 1. Komendant Główny Straży Granicznej, przed uruchomieniem KSI ETIAS, występuje do Prezesa Urzędu Ochrony Danych Osobowych z wnioskiem o przeprowadzenie kontroli w zakresie spełniania przez KSI ETIAS wymogów określonych w przepisach o ochronie danych osobowych.\n2. Wniosek, o którym mowa w ust. 1, zawiera opis środków technicznych i organizacyjnych, w szczególności w zakresie zapobiegania dostępowi osób nieuprawnionych do KSI ETIAS.\n3. Komendant Główny Straży Granicznej współpracuje z Prezesem Urzędu Ochrony Danych Osobowych w celu przeprowadzenia kontroli, o której mowa w ust. 1, w szczególności w zakresie udzielania informacji i wyjaśnień.\f4. W celu realizacji kontroli, o której mowa w ust. 1, Prezes Urzędu Ochrony Danych Osobowych, zastępca Prezesa Urzędu lub upoważnieni przez niego pracownicy Urzędu Ochrony Danych Osobowych, mają prawo do:\n1)\twstępu do pomieszczenia, w którym zlokalizowany jest KSI ETIAS i przeprowadzenia niezbędnych badań lub innych czynności kontrolnych – w godzinach od 6.00 do 22.00 i za okazaniem imiennego upoważnienia oraz legitymacji służbowej;\n2)\tżądania złożenia, w wyznaczonym terminie, pisemnych lub ustnych wyjaśnień oraz wzywania i przyjmowania oświadczeń osób w zakresie niezbędnym do ustalenia stanu faktycznego;\n3)\tprzetwarzania informacji, wglądu do dokumentów i dostępu do danych mających bezpośredni związek z przedmiotem kontroli oraz sporządzania ich kopii;\n4)\tprzeprowadzania oględzin poszczególnych elementów KSI ETIAS, w tym urządzeń lub oprogramowania;\n5)\tzlecania sporządzania ekspertyz i opinii.\n5. Po przeprowadzeniu kontroli, o której mowa w ust. 1, Prezes Urzędu Ochrony Danych Osobowych przedstawia Komendantowi Głównemu Straży Granicznej pisemną opinię w zakresie spełnienia przez KSI ETIAS wymogów określonych w przepisach o ochronie danych osobowych, a w przypadku stwierdzenia nieprawidłowości w KSI ETIAS przekazuje Komendantowi Głównemu Straży Granicznej zalecenia pokontrolne w formie pisemnej.\n6. W przypadku przedstawienia przez Prezesa Urzędu Ochrony Danych Osobowych zaleceń pokontrolnych, Komendant Główny Straży Granicznej ma prawo zgłoszenia na piśmie umotywowanych zastrzeżeń odnośnie do przekazanych zaleceń pokontrolnych – w terminie 7 dni od dnia otrzymania tych zaleceń.\n7. W razie zgłoszenia zastrzeżeń, o których mowa w ust. 6, Prezes Urzędu Ochrony Danych Osobowych może:\n1)\tuznać zgłoszone zastrzeżenia za niezasadne i podtrzymać zalecenia pokontrolne;\n2)\tuwzględnić zgłoszone zastrzeżenia w części, a w pozostałym zakresie podtrzymać zalecenia pokontrolne;\n3)\tuwzględnić zgłoszone zastrzeżenia w całości i wydać pozytywną opinię.\n8. W przypadku niezgłoszenia przez Komendanta Głównego Straży Granicznej zastrzeżeń, jak również w przypadku nieuwzględnienia zastrzeżeń przez Prezesa Urzędu Ochrony Danych Osobowych, Komendant Główny Straży Granicznej jest obowiązany wykonać zalecenia pokontrolne, a następnie wystąpić z wnioskiem do organu, który \fprzedstawił zalecenia pokontrolne, o ponowne przeprowadzenie kontroli, o której mowa w ust. 1.\nArt. 56. Komendant Główny Straży Granicznej, przed uruchomieniem KSI ETIAS, informuje ministra właściwego do spraw wewnętrznych o gotowości do uruchomienia produkcyjnego KSI ETIAS.\nArt. 57. Minister właściwy do spraw wewnętrznych, przed uruchomieniem KSI ETIAS, sprawdza gotowość do prawidłowej eksploatacji KSI ETIAS przez poszczególne organy uprawnione do przetwarzania danych ETIAS. W celu sprawdzenia gotowości, ministrowi właściwemu do spraw wewnętrznych przysługują uprawnienia, o których mowa w art. 33 ust. 2 i art. 34.\nArt. 58. Od dnia wejścia w życie art. 39 pkt 2 Komendant Główny Straży Granicznej zapewnia zasilanie, w drodze teletransmisji, Krajowego Rejestru Cudzoziemców, o którym mowa w art. 2c ust. 1 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą, zwanego dalej „KRC”, danymi i informacjami przez system teleinformatyczny prowadzony na podstawie art. 2b ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą.\nArt. 59. 1. Organy administracji publicznej oraz inne podmioty realizujące zadania publiczne, o których mowa w art. 2c ust. 3 pkt 1–7 i 9–10 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą, współpracują z Komendantem Głównym Straży Granicznej w zakresie niezbędnym do integracji ich własnych systemów teleinformatycznych z KRC, w celu zapewnienia zasilania KRC danymi i informacjami na podstawie art. 2c ust. 3 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą.\n2. Organ lub podmiot, o którym mowa w art. 2c ust. 3 pkt 1–7 i 9–10 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą:\n1)\tprzygotowuje prowadzony przez siebie system teleinformatyczny lub systemy teleinformatyczne do integracji z KRC na podstawie dokumentacji technicznej opracowanej przez Komendanta Głównego Straży Granicznej;\n2)\twystępuje do Komendanta Głównego Straży Granicznej o sprawdzenie i potwierdzenie poprawnej integracji.\n3. Integracja systemów teleinformatycznych prowadzonych przez organy i podmioty, o których mowa w art. 2c ust. 3 pkt 1–7 i 9–10 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą, z KRC, następuje w terminie nie dłuższym niż 24 miesiące od dnia wejścia w życie art. 39 pkt 1.\f4. Komendant Główny Straży Granicznej informuje ministra właściwego do spraw wewnętrznych o zakończeniu integracji danego systemu teleinformatycznego prowadzonego przez organ lub podmiot, o którym mowa w art. 2c ust. 3 pkt 1–7 i 9–10 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą, a w przypadku gdy taki organ lub podmiot prowadzi więcej niż jeden system teleinformatyczny podlegający integracji z KRC, o zakończeniu integracji ze wszystkimi systemami teleinformatycznymi prowadzonymi przez ten organ lub podmiot.\nArt. 60. 1. Przepis art. 2c ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą, w zakresie obowiązku zasilania KRC, w drodze teletransmisji, danymi i informacjami, stosuje się do danego organu lub podmiotu, o którym mowa w art. 2c ust. 3 pkt 1–7 i 9–10 tej ustawy, od dnia określonego w komunikacie, o którym mowa w art. 61.\n2. Przepis art. 2c ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą, w zakresie udostępniania, w drodze teletransmisji, danych i informacji przetwarzanych w KRC, stosuje się od momentu pierwszego zasilenia KRC danymi i informacjami na podstawie art. 2c ust. 3 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą.\nArt. 61. Minister właściwy do spraw wewnętrznych ogłosi w Dzienniku Urzędowym Rzeczypospolitej Polskiej „Monitor Polski” komunikat określający dzień rozpoczęcia zasilania KRC, w drodze teletransmisji, danymi i informacjami z systemu teleinformatycznego lub systemów teleinformatycznych jednego lub kilku organów lub podmiotów, o których mowa w art. 2c ust. 3 pkt 1–7 i 9–10 ustawy zmienianej w art. 39 w brzmieniu nadanym niniejszą ustawą.\nArt. 62. Wysokość opłaty skarbowej ustalonej w ustawie zmienianej w art. 43 pkt 1, w brzmieniu nadanym niniejszą ustawą, stosuje się do wniosków o cofnięcie zakazu ponownego wjazdu na terytorium Rzeczypospolitej Polskiej oraz na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen składanych od dnia wejścia w życie niniejszej ustawy.\nArt. 63. Do czasu zapewnienia rozwiązań technicznych i organizacyjnych umożliwiających udostępnianie właściwym organom Straży Granicznej, w drodze teletransmisji, danych zgromadzonych w rejestrze chorób zakaźnych, o którym mowa w art. 30 ust. 4a ustawy zmienianej w art. 45, w brzmieniu nadanym niniejszą ustawą:\n1)\tKomendant Główny Straży Granicznej, przeprowadzając konsultacje krajowe, zwraca się jednocześnie do organu, o którym mowa w art. 10 ust. 1 pkt 15,\f2)\tkomendant placówki Straży Granicznej, występując o przedstawienie opinii, o której mowa w art. 25b ust. 1 ustawy zmienianej w art. 45, zwraca się jednocześnie do Wspólnego Punktu Kontaktowego\n– o dokonanie sprawdzenia w tym rejestrze.\nArt. 64. 1. W latach 2027–2036 maksymalny limit wydatków budżetu państwa będących skutkiem finansowym ustawy wynosi dla Komendanta Głównego Straży Granicznej 174 956 tys. zł, z czego w:\n1)\t2027 r. – 1 062 tys. zł;\n2)\t2028 r. – 12 478 tys. zł;\n3)\t2029 r. – 23 040 tys. zł;\n4)\t2030 r. – 30 750 tys. zł;\n5)\t2031 r. – 7 175 tys. zł;\n6)\t2032 r. – 22 038 tys. zł;\n7)\t2033 r. – 0 zł;\n8)\t2034 r. – 12 300 tys. zł;\n9)\t2035 r. – 66 113 tys. zł;\n10)\t2036 r. – 0 zł.\n2. Komendant Główny Straży Granicznej monitoruje wykorzystanie limitu wydatków, o którym mowa w ust. 1, a w przypadku zagrożenia przekroczenia przyjętego na dany rok budżetowy maksymalnego limitu wydatków, o którym mowa w ust. 1, wdraża mechanizm korygujący, polegający na zmniejszeniu wydatków budżetu państwa będących skutkiem finansowym ustawy, do poziomu zgodnego z limitem wydatków przyjętym dla danego roku budżetowego oraz kolejnych lat poprzez:\n1)\trozłożenie wymiany sprzętu na kolejne lata – w przypadku wymiany sprzętu;\n2)\tzakup wsparcia do licencji na krótszy okres – w przypadku zakupu wsparcia do licencji.\nArt. 65. 1. W latach 2027–2036 maksymalny limit wydatków budżetu państwa będących skutkiem finansowym ustawy wynosi dla ministra właściwego do spraw wewnętrznych 4 884 tys. zł, z czego w:\n1)\t2027 r. – 436 tys. zł;\n2)\t2028 r. – 447 tys. zł;\n3)\t2029 r. – 458 tys. zł;\n4)\t2030 r. – 469 tys. zł;\n5)\t2031 r. – 482 tys. zł;\f6)\t2032 r. – 493 tys. zł;\n7)\t2033 r. – 505 tys. zł;\n8)\t2034 r. – 517 tys. zł;\n9)\t2035 r. – 532 tys. zł;\n10)\t2036 r. – 545 tys. zł.\n2. Minister właściwy do spraw wewnętrznych monitoruje wykorzystanie limitu wydatków, o którym mowa w ust 1, i dokonuje oceny wykorzystania tego limitu według stanu na koniec każdego kwartału, a w przypadku IV kwartału – według stanu na dzień 20 listopada danego roku.\n3. W przypadku gdy wielkość wydatków, o których mowa w ust. 1, po trzech kwartałach wyniesie łącznie więcej niż 75% limitu przewidzianego na ten rok, wielkość wydatków w IV kwartale obniża się o kwotę przekroczenia, określając zakres ograniczeń dla poszczególnych zadań realizowanych na podstawie ustawy.\nArt. 66. 1. W latach 2026–2036 maksymalny limit wydatków budżetu państwa będących skutkiem finansowym ustawy wynosi dla Szefa Urzędu do Spraw Cudzoziemców 14 059 tys. zł, z czego w:\n1)\t2027 r. – 6 385 tys. zł;\n2)\t2028 r. – 1 881 tys. zł;\n3)\t2029 r. – 662 tys. zł;\n4)\t2030 r. – 679 tys. zł;\n5)\t2031 r. – 696 tys. zł;\n6)\t2032 r. – 713 tys. zł;\n7)\t2033 r. – 731 tys. zł;\n8)\t2034 r. – 749 tys. zł;\n9)\t2035 r. – 768 tys. zł;\n10)\t2036 r. – 795 tys. zł.\n2. Szef Urzędu do Spraw Cudzoziemców monitoruje wykorzystanie limitu wydatków, o którym mowa w ust 1, i dokonuje oceny wykorzystania tego limitu według stanu na koniec każdego kwartału, a w przypadku IV kwartału – według stanu na dzień 20 listopada danego roku.\n3. W przypadku gdy wielkość wydatków, o których mowa w ust. 1, po trzech kwartałach wyniesie łącznie więcej niż 75 % limitu przewidzianego na ten rok, wielkość wydatków w IV \fkwartale obniża się o kwotę przekroczenia, określając zakres ograniczeń dla poszczególnych zadań realizowanych na podstawie ustawy.\nArt. 67. 1. W latach 2027–2036 maksymalny limit wydatków budżetu państwa będących skutkiem finansowym ustawy wynosi dla Komendanta Głównego Policji 140 tys. zł, z czego w:\n1)\t2027 r. – 140 tys. zł;\n2)\t2028 r. – 0 zł;\n3)\t2029 r. – 0 zł;\n4)\t2030 r. – 0 zł;\n5)\t2031 r. – 0 zł;\n6)\t2032 r. – 0 zł;\n7)\t2033 r. – 0 zł;\n8)\t2034 r. – 0 zł;\n9)\t2035 r. –  0 zł;\n10)\t2036 r. –  0 zł.\n2. Komendant Główny Policji monitoruje wykorzystanie limitu wydatków, o którym mowa w ust 1, i dokonuje oceny wykorzystania tego limitu według stanu na koniec każdego kwartału, a w przypadku IV kwartału – według stanu na dzień 20 listopada danego roku.\n3. W przypadku gdy wielkość wydatków, o których mowa w ust. 1, po trzech kwartałach wyniesie łącznie więcej niż 75 % limitu przewidzianego na ten rok, wielkość wydatków w IV kwartale obniża się o kwotę przekroczenia, określając zakres ograniczeń dla poszczególnych zadań realizowanych na podstawie ustawy.\nArt. 68. Ustawa wchodzi w życie z dniem określonym w decyzji Komisji Europejskiej, zgodnie z art. 88 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226, z wyjątkiem:\n1)\tart. 3 ust. 1 pkt 4 i art. 30 ust. 1 pkt 3, które wchodzą w życie z dniem określonym w decyzji Komisji Europejskiej, zgodnie z art. 11 ust.1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2021/1134 z dnia 7 lipca 2021 r. w sprawie zmiany rozporządzeń Parlamentu Europejskiego i Rady (WE) nr 767/2008, (WE) nr 810/2009, (UE) 2016/399, (UE) 2017/2226, (UE) 2018/1240, (UE) 2018/1860, (UE) 2018/1861, (UE) 2019/817 i (UE) 2019/1896 oraz uchylenia decyzji Rady 2004/512/WE i (WE) \fnr 2008/633/ WSiSW w celu zreformowania Wizowego Systemu Informacyjnego (Dz. Urz. UE L 248 z 13.07.2021, str. 11);\n2)\tart. 6 ust. 1 i ust. 2 pkt 1, 3–6 i 8, art. 7, art. 31, art. 33 ust. 2 i art. 34 w zakresie, o którym mowa w art. 56, art. 35, art. 36, art. 39 pkt 1, art. 40, art. 41 pkt 1, art. 42 pkt 5, art. 43, art. 47 pkt 1, 3, 25 lit. d, 27 lit. b, 29–33, art. 50 i 51, art. 53–62 oraz art. 64–67, które wchodzą w życie po upływie 14 dni od dnia ogłoszenia.\n\fUZASADNIENIE\n\nI. Potrzeba i cel uchwalenia ustawy\nProjektowana ustawa służy zapewnieniu stosowania rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. U. UE L 236 z 19.09.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem 2018/1240”.\nRozporządzenie 2018/1240 ustanawia europejski system informacji o podróży oraz zezwoleń na podróż, zwany dalej „ETIAS”, dla obywateli państw trzecich zwolnionych z obowiązku posiadania wizy przy przekraczaniu granic zewnętrznych Unii Europejskiej, umożliwiający sprawdzenie czy obecność tych osób na terytorium państw członkowskich UE stworzyłaby ryzyko dla bezpieczeństwa, ryzyko nielegalnej imigracji lub wysokie ryzyko epidemiczne.\nWskazane rozporządzenie 2018/1240 ustanawia również zezwolenie na podróż oraz określa warunki i procedury wydania lub odmowy wydania takiego zezwolenia, reguluje architekturę techniczną ETIAS, zasady dotyczące jego funkcjonowania i użytkowania oraz interoperacyjność z innymi systemami informacyjnymi UE, a także określa warunki, na jakich wyznaczone organy państw członkowskich UE oraz Europol mogą przeglądać dane przechowywane w systemie centralnym ETIAS.\nCelem projektu ustawy jest zagwarantowanie na poziomie prawa krajowego rozwiązań o charakterze instytucjonalno-organizacyjnym oraz proceduralnym pozostawionych przez prawodawcę unijnego dla państw członkowskich UE, niezbędnych do pełnego stosowania rozporządzenia 2018/1240. \n\nII. Szczegółowe rozwiązania projektowanej ustawy\n1. Przepisy ogólne\nW art. 1 został określony zakres przedmiotowy projektowanej ustawy, obejmujący zasady i sposób realizacji udziału Rzeczypospolitej Polskiej w ETIAS, w tym obowiązki i uprawnienia organów w zakresie wprowadzania danych oraz wglądu do danych zawartych w ETIAS poprzez Krajowy System Informatyczny do Spraw Systemu ETIAS, zwany dalej ,,KSI ETIAS”, wyznaczenie organu krajowego realizującego obowiązki jednostki krajowej ETIAS, a także organu pełniącego rolę centralnego punktu dostępu i organu odpowiedzialnego za wprowadzanie danych do listy ostrzegawczej ETIAS, ponadto zakres i sposób przeprowadzania konsultacji krajowych, w przypadku ręcznego przetwarzania wniosków o \fwydanie zezwolenia na podróż, a także właściwy organ oraz sposób i tryb prowadzenia postępowania odwoławczego.\nW art. 2 projekt wprowadza definicje podstawowych pojęć na potrzeby tego aktu prawnego, w tym poprzez odesłania do odpowiednich przepisów rozporządzenia 2018/1240. Ma to na celu zapewnienie skrótowości aktu normatywnego, a także spójności przepisów poprzez powiązanie rozwiązań krajowych z regulacjami rozporządzenia 2018/1240, w zakresie niezbędnym do zapewnienia ich stosowania. Odnosząc się do definicji jednostki operacyjnej (art. 2 pkt 13) należy podkreślić, iż zgodnie z art. 4 pkt 7 ustawy z dnia 14 grudnia 2018 r. o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości (Dz. U. z 2023 r. poz. 1206), organ publiczny działając w ramach ustawowego upoważnienia oraz konkretnego postępowania zgodnie z prawem Unii Europejskiej lub prawem państwa członkowskiego wyłączony jest z definicji odbiorcy na mocy przepisów rozporządzenia 2016/679, dyrektywy 2016/680, a w szczególności ustawy o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości.\n\n2. Uprawnienia organów krajowych w zakresie dostępu do danych ETIAS\nRealizując jeden z głównych celów projektu określono organy uprawnione do bezpośredniego dostępu do danych ETIAS poprzez KSI ETIAS, dostosowując jego zakres do celów i zadań dotyczących cudzoziemców, realizowanych przez te podmioty (art. 3 projektu). Uprawnienia te będą przysługiwały Straży Granicznej, wojewodom, Szefowi Urzędu do Spraw Cudzoziemców, Policji, Służbie Celno-Skarbowej, Radzie do Spraw Uchodźców, ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych i konsulom.\nNajszerszy dostęp do danych ETIAS uwzględniający ich wprowadzanie, zmianę lub usunięcie będzie przysługiwał Straży Granicznej. Pozostałe organy będą miały dostęp ograniczony tylko do wglądu do danych ETIAS. Jednocześnie należy mieć na względzie, że przez wprowadzanie danych, zgodnie z definicją art. 2 pkt 30, rozumie się czynności polegające na zapisywaniu danych ETIAS w systemie centralnym ETIAS, obejmujące rejestrowanie danych w pliku wniosku lub wprowadzanie ich do listy ostrzegawczej ETIAS.\nKomendant Główny Straży Granicznej będzie posiadał dostęp również do rejestrów operacji przetwarzania danych przeprowadzonych przez przewoźników, w ramach portalu dla przewoźników, do celów art. 45 ust. 7 rozporządzenia 2018/1240, związanych z przywozem przez przewoźnika cudzoziemca nieposiadającego ważnego zezwolenia na podróż, nakładaniem kar administracyjnych na przewoźników oraz do rozstrzygania ewentualnych sporów z tym związanych. Przedmiotowe dane z rejestrów będą mogły zostać wykorzystane w toku prowadzonego postępowania administracyjnego dotyczącego nałożenia kary \fadministracyjnej na przewoźnika, jako materiał dowodowy w sprawie.\nDostęp do przeglądania danych do celów sporządzania sprawozdań i statystyk przysługiwać będzie Straży Granicznej, wojewodzie, Szefowi Urzędu do Spraw Cudzoziemców, ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych i konsulowi.\nZ uwagi na to, że projektowana regulacja nakłada na Komendanta Głównego Straży Granicznej obowiązek zapewnienia zgodności z prawem, dokładności i aktualności wprowadzanych danych do systemu centralnego ETIAS, będzie on mógł wystąpić – w przypadku gdy okoliczności wskazują, że dane przechowywane w systemie centralnym ETIAS podlegają zmianie lub usunięciu, są niezgodne z prawdą lub że dane były przetwarzane przez system centralny ETIAS z naruszeniem przepisów rozporządzenia 2018/1240 – do innych organów administracji publicznej w celu weryfikacji tych okoliczności i danych. Odpowiedź w tych sprawach będzie udzielana w terminie nie dłuższym niż 7 dni roboczych w celu dochowania terminów określonych w art. 55 rozporządzenia 2018/1240. Wymiana informacji w podanym zakresie przyczyni się do właściwej realizacji zadań wynikających z udziału RP w ETIAS oraz wpłynie na jakość przetwarzanych danych ETIAS w tym systemie.\nW art. 4 projektu określono organy uprawnione do pośredniego dostępu do danych ETIAS, które zgodnie z art. 50 ust. 1 rozporządzenia 2018/1240, są upoważnione do przeglądania danych ETIAS w celu określonym w art. 52 ust. 1 rozporządzenia 2018/1240, związanym z zapobieganiem przestępstwom terrorystycznym lub innym poważnym przestępstwom, ich wykrywaniem lub prowadzeniem w ich sprawach postępowań przygotowawczych. Należy wskazać, że dostęp do danych ETIAS w konkretnej sprawie musi być niezbędny i proporcjonalny oraz muszą istnieć dowody lub uzasadnione podstawy, aby uznać, że przeglądanie danych przechowywanych w systemie centralnym ETIAS przyczyni się do zapobiegania przedmiotowym przestępstwom, ich wykrywania lub prowadzenia postępowań przygotowawczych.\nW związku z powyższym uprawnienie to będzie przysługiwało prokuraturze, sądom, Policji, Straży Granicznej, Krajowej Administracji Skarbowej, Agencji Bezpieczeństwa Wewnętrznego, Agencji Wywiadu, Centralnemu Biuru Antykorupcyjnemu, Służbie Ochrony Państwa, Służbie Kontrwywiadu Wojskowego, Służbie Wywiadu Wojskowego i Żandarmerii Wojskowej. Pośredni dostęp do danych ETIAS będzie realizowany poprzez centralny punkt dostępu (CPD), wskazany w art. 50 ust. 2 rozporządzenia 2018/1240. Wymienione organy będą również uprawnione, w indywidualnych przypadkach, do przekazania lub udostępnienia danych ETIAS wyznaczonemu organowi państwa trzeciego, zgodnie z art. 65 ust. 5 rozporządzenia 2018/1240, w przypadku zagrożenia przestępstwem terrorystycznym lub zapobieżenia przestępstwu terrorystycznemu lub innemu poważnemu przestępstwu, do ich \fwykrycia lub do prowadzenia w ich sprawie postępowania przygotowawczego. Wniosek o dostęp do danych ETIAS będzie przekazywany w sposób elektroniczny jako docelowe rozwiązanie sposobu komunikacji z CPD (za pośrednictwem aplikacji WWW ETIAS lub własnego system teleinformatycznego wnioskującego organu). W wyjątkowych przypadkach, np. awarii systemów teleinformatycznych, za zgodą Komendanta Głównego Straży Granicznej, po wcześniejszym kontakcie organu wnioskującego, wniosek może zostać przekazany za pośrednictwem uzgodnionego alternatywnego kanału wymiany informacji. Wzór takiego wniosku zostanie określony w przepisach wykonawczych przez ministra właściwego do spraw wewnętrznych.\nW przypadku gdy weryfikacja ex post pilnego wniosku o dostęp pośredni do danych ETIAS (weryfikacja spełnienia warunków dostępu do danych ETIAS po fakcie ich uzyskania) wykaże, że przeglądanie danych zapisanych w systemie centralnym ETIAS lub dostęp do tych danych były nieuzasadnione, organy będą obowiązane usunąć wszelkie uzyskane dane ETIAS niezwłocznie, nie później niż w ciągu 3 dni po dokonaniu weryfikacji oraz otrzymaniu informacji, że uzyskanie tych danych ETIAS było nieuzasadnione, a następnie będą powiadamiały CPD o usunięciu tych danych. Wyznaczenie terminu usunięcia danych ETIAS służy zapewnieniu właściwych standardów ich ochrony i ma na celu wzmocnienie gwarancji w zakresie niezwłocznego zaprzestania ich przetwarzania w przypadku stwierdzenia, że jest ono w danym przypadku i okolicznościach (sprawie) nieuprawnione.\nWprowadzane regulacje w art. 3 i art. 4 projektu uwzględniają brzmienie art. 13 ust. 5 rozporządzenia 2018/1240, który wskazuje, że każde państwo członkowskie UE niezwłocznie przekazuje wykaz organów uprawnionych do dostępu bezpośredniego oraz pośredniego do danych ETIAS. Wykaz określa, do jakich celów przewidzianych w rozporządzeniu 2018/1240, ma dostęp należycie upoważniony personel każdego z uprawnionych organów. Organy, o których mowa w rozdziale 2, będą obowiązane, w zakresie swojej właściwości, do współpracy do przekazywania dokumentów, udzielania informacji oraz aktualnych i niezbędnych danych do prowadzenia wykazu jednostek operacyjnych oraz w celu przekazywania powiadomień o organach uprawnionych do przetwarzania danych ETIAS.\n\n3. Centralny punkt dostępu (CPD)\nUregulowanie struktury i sposobu przepływu danych ETIAS poprzez wyznaczenie pojedynczego centralnego punktu dostępu jest zasadne ze względów prawnych, organizacyjnych i technicznych. Powyższe znalazło odzwierciedlenie zarówno w projekcie ustawy, jak i w budowanym „systemie krajowym” (krajowe oprogramowanie dla jednostki krajowej ETIAS). Wyznaczenie centralnego punktu dostępu do danych ETIAS, przetwarzanych w systemie centralnym ETIAS – Komendanta Głównego Straży Granicznej, \fzostało zaakceptowane przez Pełnomocnika Rządu do spraw Wielkoskalowych Systemów Informacyjnych Unii Europejskiej oraz stanowiło podstawę do rozpoczęcia przez Straż Graniczną działań zmierzających do wdrożenia na gruncie krajowym europejskiego systemu informacji o podróży oraz zezwoleń na podróż (ETIAS).\nPowołanie jednego centralnego punktu dostępu do danych ETIAS dla wszystkich wyznaczonych organów w Rzeczypospolitej Polskiej jest uzasadnione pod względem prawnym, gdyż:\nKomendant Główny Straży Granicznej spełnia określone w rozporządzeniu 2018/1240 przesłanki, m.in. w zakresie sprawowania władzy publicznej;\nStraż Graniczna będzie pełniła funkcję organu uprawnionego do dostępu do danych ETIAS, co jest dopuszczalne w świetle przepisów art. 50 ust. 2 rozporządzenia 2018/1240;\nproces legislacyjny w zakresie ustanowienia centralnego punktu dostępu jest ograniczony do jednego organu administracji rządowej;\nwyodrębnienie centralnego punktu dostępu w niektórych organach administracji rządowej, szczególnie w służbach specjalnych z uwagi na ich podległość, a także obowiązującą hierarchię służbową oraz wykonywanie ustawowych zadań mogłoby być utrudnione.\nPonadto, pod względem organizacyjnym, powołanie centralnego punktu dostępu:\npowoduje zmiany o charakterze strukturalno-organizacyjnym tylko w ramach funkcjonowania jednego organu administracji rządowej;\nułatwia ustalenie jednolitych trybów postępowania i warunków dostępu do danych ETIAS dla wszystkich wyznaczonych organów za pośrednictwem centralnego punktu dostępu;\nskupia w jednym miejscu odpowiedzialność za realizację zadań centralnego punktu dostępu, w szczególności w zakresie prowadzenia wykazu jednostek operacyjnych uprawnionych do dostępu do danych ETIAS za pośrednictwem tego punktu;\nzapewnia niezwłoczny dostęp do danych ETIAS, w tym w pilnych przypadkach, gdy zachodzi potrzeba aby zapobiec bezpośredniemu zagrożeniu życia osoby w związku z przestępstwem terrorystycznym lub innym poważnym przestępstwem.\nPełnienie roli centralnego punktu dostępu przez Komendanta Głównego Straży Granicznej jest rozwiązaniem korzystnym także ze względu na:\njednolity nadzór nad przestrzeganiem przepisów, w szczególności w zakresie:\n\tdostępu wyznaczonych organów do danych ETIAS,\n\t\frejestrowania i dokumentowania wszystkich operacji przetwarzania danych ETIAS związanych z wnioskami wyznaczonych organów,\n\todpowiedniego upoważnienia osób mających uprawnienia do dostępu do danych ETIAS;\nzapewnienie przez Komendanta Głównego Straży Granicznej, jako administratora wyznaczonego na podstawie art. 57 rozporządzenia 2018/1240, właściwego nadzoru nad przetwarzaniem danych ETIAS;\nopracowanie jednego systemu wnioskowego dla wyznaczonych organów w zakresie:\n\twytworzenia, wdrożenia oraz utrzymania i rozwoju systemu (tworzenie oprogramowania i administracja oprogramowaniem, help desk, obsługa problemów, naprawa błędów itp.),\n\trozliczalności systemu,\n\tprzygotowywania sprawozdań dla Komisji Europejskiej (możliwość przygotowania dedykowanych raportów),\n\tzarządzania użytkownikami i dostępu do danych ETIAS (w przypadku formy scentralizowanej jest o wiele łatwiejsze i tańsze),\n\tprzygotowania rozwiązania opartego na eksploatowanej w Straży Granicznej architekturze i technologii (niższe koszty),\n\tobsługi informatycznej (niższe koszty utrzymania jednego centralnego punktu dostępu),\n\tbezpieczeństwa przetwarzania i przechowywania danych ETIAS;\nmożliwość skorzystania z posiadanego przez Straż Graniczną doświadczenia w zakresie budowy KSI PNR, w którym działa system wnioskowy (KSI PNR wraz z aplikacją dla organów właściwych („AOW”));\nwymiany informacji i podjęcie dalszych działań związanych z wydaniem, odmową wydania, cofnięciem lub unieważnieniem zezwolenia na podróż.\nStworzenie pojedynczego centralnego punktu dostępu (CPD) przełoży się również na wysokość kosztów jakie towarzyszą budowie, a następnie utrzymaniu systemu teleinformatycznego wykorzystywanego do realizacji zadań w ramach CPD (krajowe oprogramowanie dla jednostki krajowej ETIAS). Zastosowanie odmiennej koncepcji wiązałoby się z koniecznością całkowitej przebudowy systemu, dostosowania infrastruktury w służbach, a co się z tym wiąże brakiem możliwości zrealizowania założeń oraz procesu testów systemu ETIAS, zaś w konsekwencji przełożyłoby się na znaczne opóźnienie wdrożenia systemu ETIAS oraz znaczne koszty dla budżetu państwa, a ponadto uniemożliwiłoby zastosowanie jednolitego schematu działania i rozwiązywania problemów systemu.\fZ chwilą wejścia w życie przepisów ustawy w zakresie CPD, organy będą zobowiązane do niezwłocznego wyznaczenia jednostek operacyjnych oraz zawiadomienia, w formie pisemnej, w postaci papierowej lub elektronicznej, Komendanta Głównego Straży Granicznej o wyznaczonych jednostkach operacyjnych i ich danych teleadresowych, a w szczególności o adresie, numerze telefonu, adresie e-mail, a także w przyszłości o wszelkich zmianach ich dotyczących. Podane informacje będą również wykorzystywane do prowadzenia wykazu jednostek operacyjnych.\n\n4. Organ, o którym mowa w art. 8 ust 1 rozporządzenia 2018/1240 oraz Centralny Organ Techniczny KSI ETIAS\nJednym z podstawowych założeń projektu jest określenie właściwego organu, o którym mowa w art. 8 ust 1 rozporządzenia 2018/1240. W art. 5 wyznaczono Komendanta Głównego Straży Granicznej jako właściwy organ krajowy, wskazując jednocześnie, że realizuje on zadania i korzysta z uprawnień jednostki krajowej ETIAS w zakresie i na zasadach określonych w rozporządzeniu oraz innych przepisach prawa Unii Europejskiej dotyczących tej jednostki, np. w przyszłych aktach prawnych dotyczących rozporządzenia 767/2008 VIS Recast i rozporządzenia Parlamentu Europejskiego i Rady (UE) 2024/1356 z dnia 14 maja 2024 r. w sprawie wprowadzenia kontroli przesiewowej obywateli państw trzecich na granicach zewnętrznych. \nPonadto, określono dodatkowe zadania, które realizuje Komendant Główny Straży Granicznej, obejmujące pełnienie roli CPD, rozpatrywanie wniosków o ponowne rozpatrzenie sprawy, inicjowanie i prowadzenie konsultacji z właściwymi organami krajowymi lub jednostkami krajowymi ETIAS innych państw członkowskich UE, prowadzenie ewidencji uprawnień do dostępu do aplikacji WWW ETIAS oraz zarządzanie dostępem użytkowników indywidualnych, powiadamianie Komisji Europejskiej i Agencji eu-LISA, zgodnie z art. 87 ust. 1–3 rozporządzenia 2018/1240, a także współpraca z Komisją Europejską w celu przyjęcia praktycznego podręcznika.\nProjektowany przepis art. 6 wskazuje, iż Komendant Główny Straży Granicznej pełni również rolę Centralnego Organu Technicznego KSI ETIAS (COT KSI ETIAS), który będzie realizował zadania o charakterze technicznym wynikające z udziału Rzeczypospolitej Polskiej w ETIAS, a także określono jego zadania wynikające m.in. z art. 76 rozporządzenia 2018/1240. Jest to niezbędne dla prawidłowej organizacji, zarządzania i utrzymania infrastruktury krajowej ETIAS, zapewnienia niezbędnych środków technicznych organom uprawnionym do przetwarzania danych ETIAS oraz zapewnienia bezpiecznych rozwiązań technicznych jako odpowiedzialnego od strony technicznej za właściwą eksploatację, rozwój i utrzymanie KSI ETIAS. Na COT KSI ETIAS zostały również nałożone obowiązki, w tym wynikające \fz art. 46 i art. 48 rozporządzenia 2018/1240 (odbieranie i przetwarzanie powiadomień), art. 60 ust. 3–5 rozporządzenia 2018/1240 (postępowanie w przypadku zaistnienia incydentów bezpieczeństwa) oraz w zakresie opracowywania krajowych planów bezpieczeństwa, planów ciągłości działania i przywrócenia gotowości. COT KSI ETIAS przygotowywać będzie również przekazywane przez Komendanta Głównego Straży Granicznej sprawozdanie dotyczące oceny funkcjonowania KSI ETIAS w poprzednim roku kalendarzowym, które przedstawia się ministrowi właściwemu do spraw wewnętrznych w terminie do dnia 31 marca każdego roku.\nW projektowanym art. 7 określono sposób realizacji zadań Komendanta Głównego Policji w celu właściwego funkcjonowania KSI ETIAS. \nKomendant Główny Policji jest dysponentem jednolitego interfejsu krajowego (NUI) dostarczanego przez Agencję eu-LISA. Bez dostępności wskazanego interfejsu, nie jest możliwe połączenie z centralnym systemem ETIAS. Z tego faktu wynika odpowiedzialność Komendanta Głównego Policji za całodobową dostępność obsługi technicznej, zasilanie oraz bezpieczeństwo fizyczne elementów jednolitego interfejsu krajowego, łączność z systemem centralnym ETIAS poprzez łącze telekomunikacyjne dostarczane przez Agencję eu-Lisa, a także zapewnienie podłączenia krajowej infrastruktury granicznej do jednolitego interfejsu krajowego, rozumiane jako zapewnienie połączenia pomiędzy jednolitym interfejsem krajowym a urządzeniami sieciowymi Straży Granicznej, umiejscowionymi w serwerowniach Policji w ramach ośrodka podstawowego i zapasowego oraz zapewnienie niezbędnej liczby kluczowych elementów systemu tak, aby w razie awarii jednego z elementów, ośrodek zapasowy natychmiast przejął jego rolę bez wpływu na dostęp do środowiska produkcyjnego KSI ETIAS.\nZapewnienie wszystkich wymienionych wymaganych elementów oraz współpraca z COT KSI ETIAS jest zatem niezbędna w celu właściwej realizacji obowiązków wynikających z udziału w ETIAS.\n\n5. Rozpatrywanie wniosków o wydanie zezwolenia na podróż\nKolejnym istotnym założeniem projektu jest stworzenie niezbędnych ram prawno-organizacyjnych dla „ręcznego rozpatrywania wniosków o wydanie zezwolenia na podróż”, zgodnie z art. 26 rozporządzenia 2018/1240. Należy wyjaśnić, że procedura rozpatrywania wniosków określona w rozporządzeniu 2018/1240 ma charakter zautomatyzowany, gdyż wszystkie czynności łącznie z weryfikacją oraz wydaniem zezwolenia na podróż następują w systemie. Jedynie w przypadku trafienia, tj. stwierdzenia istnienia informacji lub danych, jednostka krajowa ETIAS państwa członkowskiego UE, które wprowadziło te dane, dokonuje dalszego bezpośredniego rozpatrzenia takiego wniosku. W projekcie określono, że Komendant Główny Straży Granicznej rozpatruje wnioski o wydanie zezwolenia na podróż za \fpośrednictwem europejskiego oprogramowania dla jednostek krajowych ETIAS lub może dodatkowo za pośrednictwem krajowego oprogramowania dla jednostki krajowej ETIAS. Czynności w ramach krajowego oprogramowania dla jednostki krajowej ETIAS będą obejmować m.in. dokonywanie sprawdzeń w systemach informacyjnych UE, krajowych systemach teleinformatycznych i bazach danych, czy też prowadzenie konsultacji krajowych z innymi organami i służbami. Funkcja automatycznie udostępniająca dane z europejskiego oprogramowania dla jednostek krajowych ETIAS do pobrania pliku zawierającego dane z pliku wniosku, umożliwiająca wyszukanie rekordu, pliku lub wpisu wywołującego trafienie w systemach informacyjnych UE, w których przeprowadzono kwerendę, a w przypadku gdy dodatkowe informacje związane z trafieniem w systemie informacyjnym UE, o którym mowa w art. 20 rozporządzenia 2018/1240, są przechowywane w krajowym systemie lub bazie danych, umożliwia przeszukanie systemu krajowego lub krajowej bazy danych w celu wsparcia oceny ryzyka względem cudzoziemca. \nZgodnie z rozporządzeniem 2018/1240, wszelki kontakt z cudzoziemcem odbywać się będzie za pośrednictwem adresu poczty elektronicznej. Adres e-mail wskazany w formularzu wniosku o wydanie zezwolenia na podróż będzie wykorzystywany zgodnie z art. 15 ust. 3 rozporządzenia 2018/1240. Tym samym, adres poczty elektronicznej wykorzystuje się do doręczeń w sprawach dotyczących zezwolenia na podróż. W związku z tym odpowiedzialność za aktualność, prawidłowość oraz bieżący dostęp do adresu poczty elektronicznej spoczywa na cudzoziemcu. Ewentualna aktualizacja adresu poczty elektronicznej, a tym samym zmiana adresu właściwego do wymiany informacji oraz kontaktu z cudzoziemcem będzie odbywała się z uwzględnieniem przepisów art. 64 rozporządzenia 2018/1240. \nJęzykiem wykorzystywanym podczas rozpatrywania wniosku o wydanie zezwolenia na podróż w zakresie wymiany informacji (m.in. wydanie wszelkich rozstrzygnięć w sprawach o zezwolenie na podróż, wezwanie o dodatkowe dokumenty/informacje, przeprowadzenie rozmowy z cudzoziemcem) oraz kontaktu z cudzoziemcem, który złożył wniosek o wydanie zezwolenia na podróż, będzie język polski albo język angielski. Wybór języka przez cudzoziemca będzie następował w momencie składania wniosku za pośrednictwem ogólnodostępnej strony internetowej lub aplikacji na urządzenia mobilne. W wykazie języków w rozporządzeniu wymieniono m.in. język angielski jako co najmniej wymagany podczas rozpatrywania wniosków o wydanie zezwolenia na podróż (w tym podczas cofnięcia i unieważnienia zezwolenia na podróż). Podany zakres wykorzystywanych języków będzie obligował cudzoziemca do odbycia rozmowy, przedstawienia dodatkowych informacji lub dokumentów w języku polskim albo w języku angielskim. Wykorzystanie innych języków wymagać będzie wcześniejszego kontaktu cudzoziemca i uzgodnienia z  Komendantem Głównym Straży Granicznej. \fZgodnie z projektem, w celu zgromadzenia całościowego materiału dowodowego w sprawie, zapis rozmowy z cudzoziemcem przeprowadzonej z wykorzystaniem środków komunikacji audiowizualnej na odległość będzie przechowywany w krajowym oprogramowaniu dla jednostki krajowej ETIAS). Zapis rozmowy będzie mógł zostać wykorzystany w toku ewentualnych postępowań o unieważnienie lub cofnięcie zezwolenia na podróż oraz w postępowaniach w sprawie wniosku o ponowne rozpatrzenie sprawy, czy też w ramach postępowania sądowo-administracyjnego. Rozmowa z cudzoziemcem za pośrednictwem konsula będzie odbywała się na zasadach określonych w art. 27 ust. 4 i 8 rozporządzenia 2018/1240 oraz dotychczasowych, obowiązujących już przepisach art. 26 ust. 1 pkt 2 ustawy z dnia 25 czerwca 2015 r. – Prawo konsularne, w zakresie pomocy prawnej dokonywanej przez konsulaty na rzecz innych organów administracji publicznej. W projekcie doprecyzowano sposób postępowania konsula w takich przypadkach, uwzględniając konieczność dokonania zapisu w pliku wniosku tego samego dnia, w którym odbyła się rozmowa, kwestii jej dotyczących (zapis rozmowy, opinia).\nW toku rozpatrywania wniosku, w celu indywidualnej oceny ryzyka dla bezpieczeństwa, nielegalnej imigracji lub wysokiego ryzyka epidemicznego, Komendant Główny Straży Granicznej będzie mógł dokonywać sprawdzeń w systemach informacyjnych Unii Europejskiej, krajowych systemach teleinformatycznych, do których posiada dostęp, a także przeprowadzić konsultacje krajowe.\nSprawdzenie w krajowych systemach teleinformatycznych dotyczyć będzie systemów i baz danych Straży Granicznej, w szczególności dostępnych modułów Centralnego Systemu Informatycznego Straży Granicznej (CSI SG), o którym mowa w art. 2b ustawy z dnia 12 października 1990 r. o Straży Granicznej oraz Krajowego Rejestru Cudzoziemców, o którym mowa w projektowanym art. 2c tej ustawy (art. 39 projektu). Sprawdzenie to dotyczyć będzie także innych krajowych systemów teleinformatycznych i baz danych, np. Krajowego Rejestru Karnego określonego w ustawie z dnia 24 maja 2000 r. o Krajowym Rejestrze Karnym, w przypadkach trafień, o których mowa w art. 20 ust. 2 lit. n w związku z art. 25a ust. 2 rozporządzenia 2018/1240, tj. czy wnioskodawca odpowiada osobie, której dane są zapisane w ECRIS-TCN i do których dołączono marker zgodnie z art. 5 ust. 1 lit. c rozporządzenia (UE) 2019/816. Takie sprawdzenie – na podstawie  art. 6 ust. 1 pkt 7 wyżej wymienionej ustawy o Krajowym Rejestrze Karnym – wykaże cudzoziemców, którzy zostali skazani za przestępstwo terrorystyczne, inne poważne przestępstwo lub jakiekolwiek inne przestępstwo, które mogą mieć wpływ na ostateczną ocenę ryzyka w zakresie wystąpienia zagrożenia dla porządku publicznego, bezpieczeństwa wewnętrznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich UE. Dostęp Komendanta Głównego Straży Granicznej do innych krajowych systemów teleinformatycznych i baz danych oraz \fprzetwarzanych w nich informacji w zakresie mogącym mieć wpływ na indywidualną ocenę ryzyka dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemicznego, jest niezbędny do prawidłowego wykonywania zadań związanych z udziałem Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż ETIAS. Brak pełnych informacji o cudzoziemcu może negatywnie wpłynąć na końcową ocenę ryzyka, a tym samym na prawidłowość rozstrzygnięcia w zakresie wydanej decyzji odnośnie zezwolenia na podróż.\nPonadto, dokonywanie dodatkowych ustaleń ma na celu wyjaśnienie wątpliwości co do przekazanych przez cudzoziemca informacji i złożonych dokumentów, tj. weryfikacji wiarygodności i autentyczności przedstawionych dokumentów poprzez konsultacje z podmiotem, który je wydał lub wystawił, np. potwierdzenia, zaproszenia, wezwania, zaświadczenia, wyroki, decyzje, jak również wskazywanych okoliczności planowanego wjazdu i pobytu w ramach ruchu bezwizowego.  \nOcena ryzyka dla bezpieczeństwa powinna być oparta na wszechstronnej analizie całokształtu materiału dowodowego w toku postępowania o wydanie zezwolenia na podróż. Dotychczasowe doświadczenia w tym obszarze, dotyczące stosowania krajowych przepisów w zakresie przesłanek związanych z ochroną bezpieczeństwa czy porządku publicznego, potwierdzają konieczność prowadzenia szerokiej weryfikacji informacji i dokumentów celem prawidłowej oceny cudzoziemca, także z uwzględnieniem wcześniejszych pobytów, składanych wniosków, naruszeń porządku prawnego itp. \nJednocześnie ryzyko nielegalnej imigracji, zgodnie ze wskazaną w rozporządzeniu 2018/1240 definicją, oznacza ryzyko, że obywatel państwa trzeciego nie spełnia warunków wjazdu i pobytu, określonych w art. 6 rozporządzenia (UE) 2016/399. Ocena wskazanego ryzyka odnosić się będzie do możliwych przyszłych działań cudzoziemca, z uwzględnieniem informacji na temat przekraczania przez cudzoziemca dozwolonego okresu pobytu, decyzji negatywnych związanych z pobytem na terytorium państw członkowskich, w tym decyzji o zobowiązaniu do powrotu lub dotyczących odmowy wjazdu.\nWysokie ryzyko epidemiczne oznacza natomiast każdą chorobę mogącą przerodzić się w epidemię według definicji Międzynarodowych Przepisów Zdrowia (2005) lub Europejskiego Centrum ds. Zapobiegania i Kontroli Chorób (ECDC) czy inną chorobę zakaźną lub zaraźliwą chorobę pasożytniczą, jeżeli są one objęte przepisami dotyczącymi ochrony, mającymi zastosowanie do obywateli państw członkowskich. Ryzyko to będzie oceniane przez Komendanta Głównego Straży Granicznej przy współpracy z Państwową Inspekcją Sanitarną (organem centralnym wykonującym te zadania jest Główny Inspektor Sanitarny), która jest powołana do realizacji zadań z zakresu zdrowia publicznego, w celu ochrony zdrowia ludzkiego przed niekorzystnym wpływem szkodliwości i uciążliwości środowiskowych, \fzapobiegania powstawaniu chorób, w tym chorób zakaźnych i zawodowych, zgodnie z ustawą z dnia 14 marca 1985 r. o Państwowej Inspekcji Sanitarnej. Wykonywanie wskazanych zadań polega na sprawowaniu zapobiegawczego i bieżącego nadzoru sanitarnego oraz prowadzeniu działalności zapobiegawczej i przeciwepidemicznej w zakresie chorób zakaźnych i innych chorób powodowanych warunkami środowiska. Wobec powyższego Komendant Główny Straży Granicznej podczas rozpatrywania wniosków o wydanie zezwolenia na podróż, dokonując indywidualnej oceny przesłanek stwarzających wysokie ryzyko epidemiczne, może dokonywać sprawdzeń za pośrednictwem systemu teleinformatycznego Straży Granicznej przez interfejs programowania aplikacji (API) do systemu teleinformatycznego lub systemów teleinformatycznych, w którym organy Państwowej Inspekcji Sanitarnej prowadzą Rejestr chorób zakaźnych, o którym mowa w art. 30 ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi. W przypadku stwierdzenia – w drodze sprawdzenia – istnienia w rejestrze przesłanek faktycznych mogących potencjalnie stanowić odmowę wydania zezwolenia na podróż Komendant Główny Straży Granicznej, w razie konieczności, może zwrócić się dodatkowo o opinię do Głównego Inspektora Sanitarnego. Tym samym, opinia ta zostanie uwzględniona w całościowej ocenie cudzoziemca w zakresie możliwości wydania bądź odmowy wydania zezwolenia na podróż. \nWskazane czynności kompleksowej weryfikacji będą dotyczyły cudzoziemca, który złożył wniosek o wydanie zezwolenia na podróż oraz cudzoziemca, wobec którego Komendant Główny Straży Granicznej z urzędu będzie mógł prowadzić czynności także w celu wydania zezwolenia na podróż o ograniczonej ważności terytorialnej, o których mowa w art. 44 ust. 1 rozporządzenia 2018/1240. Powyższe będzie miało również zastosowanie do osoby sprawującej władzę rodzicielską lub opiekuna prawnego albo firmy lub organizacji w przypadku trafień w wyniku weryfikacji albo porównania, o których mowa w art. 20 ust. 2 lit. m i ust. 4 rozporządzenia 2018/1240.\nZgodnie z projektowanym przepisem art. 10 konsultacje krajowe będą prowadzone poprzez pojedyncze wyznaczone centralne punkty kontaktowe dla sądów, prokuratorów, Komendanta Głównego Policji, Szefa Agencji Bezpieczeństwa Wewnętrznego, Szefa Agencji Wywiadu, Komendanta Głównego Żandarmerii Wojskowej, Komendanta Służby Ochrony Państwa, Szefa Centralnego Biura Antykorupcyjnego, Szefa Krajowej Administracji Skarbowej, Szefa Służby Kontrwywiadu Wojskowego, Szefa Służby Wywiadu Wojskowego, Szefa Urzędu do Spraw Cudzoziemców, ministra właściwego do spraw zagranicznych, ministra właściwego do spraw wewnętrznych oraz Głównego Inspektora Sanitarnego, przy czym dla sądów i prokuratorów, będzie mógł być prowadzony jeden wspólny punkt kontaktowy. Właściwość merytoryczna wymienionych organów, w tym ich specjalistyczne kompetencje, zagwarantują dokonanie szczegółowej i wnikliwej oceny ryzyka dla bezpieczeństwa, \fnielegalnej imigracji lub wysokiego ryzyka epidemicznego. \nW odniesieniu do skali konsultacji krajowych, o których mowa w projektowanym art. 10, należy przyjąć szacowaną liczbę konsultacji krajowych w uśrednionej liczbie 1825 na rok.\nWskazać należy, że konsultacje krajowe zostaną przeprowadzone tylko w przypadku zaistnienia potrzeby uzyskania opinii o cudzoziemcu od innych organów przez Komendanta Głównego Straży Granicznej. Organy będą mogły wyrazić opinię o cudzoziemcu, która zostanie uwzględniona w końcowej ocenie cudzoziemca, w zakresie możliwości wydania bądź odmowy wydania zezwolenia na podróż, jego cofnięcia albo unieważnienia, czy też wydania opinii w trakcie konsultacji z jednostką krajową ETIAS innego państwa członkowskiego UE. Uzyskanie opinii o cudzoziemcu przez Komendanta Głównego Straży Granicznej, może być zatem niezbędne do właściwej interpretacji sytuacji faktycznej oraz prawnej cudzoziemca. Jednocześnie wydanie pozytywnej (w tym w wyniku tzw. „cichej zgody”) albo negatywnej opinii o cudzoziemcu nie będzie przesądzać o końcowym rozstrzygnięciu, które będzie podejmował Komendant Główny Straży Granicznej.\nZe względu na czas na rozpatrzenie wniosku o wydanie zezwolenia na podróż (96 godzin na przeprowadzenie czynności przez Jednostkę Centralną ETIAS oraz jednostkę krajową ETIAS (KGSG)) istnieje konieczność wprowadzenia punktów kontaktowych dla wyżej wymienionych organów w celu właściwej realizacji zadań przez Komendanta Głównego Straży Granicznej na gruncie stosowania ETIAS. \nW razie potrzeby, konsultacje krajowe będą mogły być przeprowadzone również z innymi organami (art. 10 ust. 1 pkt 16). Organy przekazują opinię (pozytywną albo negatywną) oraz informacje lub dokumenty w terminie nie dłuższym niż 48 godzin, a brak udzielenia odpowiedzi w wyznaczonym terminie, uznawany będzie za pozytywną opinię w sprawie wnioskodawcy (cudzoziemca). \nZe względu na czas trwania poszczególnych czynności wynikający z rozporządzenia 2018/1240, konsultacje krajowe będą prowadzone w formie elektronicznej. W wyjątkowych i szczególnych przypadkach, po wcześniejszym uzgodnieniu organu administracji publicznej z jednostką krajową ETIAS, wskazane konsultacje mogą być prowadzone za pośrednictwem alternatywnego kanału wymiany informacji, np. poczty e-mail. Jednocześnie ze względu na charakter czynności (m.in. elektroniczne prowadzenie spraw o wydanie zezwolenia na podróż) oraz konieczność zapisywania informacji i dowodów w pliku wniosku w ramach europejskiego oprogramowania dla jednostek krajowych ETIAS (opracowane narzędzie przez Agencję eu-Lisa) oraz krajowego oprogramowania dla jednostki krajowej ETIAS, należy przyjąć, że czynności konsultacji krajowych powinny zostać w pełni zdigitalizowane i prowadzone wyłącznie w sposób elektroniczny. Z chwilą wejścia przepisów w życie w zakresie konsultacji \fkrajowych, organy, o których mowa w art. 10 ust. 1 pkt 1–15 projektu, wyznaczą punkt kontaktowy właściwy w sprawach konsultacji krajowych, oraz zawiadomią pisemnie, w postaci papierowej lub elektronicznej, Komendanta Głównego Straży Granicznej o wyznaczonym punkcie kontaktowym oraz o jego danych teleadresowych. Analogiczne zawiadomienie będzie dotyczyć punktu kontaktowego do spraw listy ostrzegawczej ETIAS (istnieje możliwość prowadzenia przez organy i służby jednego wspólnego punktu kontaktowego w tych celach).\nW przypadku wystąpienia nowych okoliczności w sprawie lub pojawienia się dalszych wątpliwości dotyczących sytuacji cudzoziemca, Komendant Główny Straży Granicznej będzie uprawniony do ponownego zwrócenia się o wydanie opinii o cudzoziemcu.  \nZgodnie z art. 11 projektu ustawy, w przypadku gdy jednostka krajowa ETIAS innego państwa członkowskiego zwróci się, zgodnie z art. 28 lub art. 44 ust. 1 rozporządzenia 2018/1240, o opinię w sprawie wniosku o wydanie zezwolenia na podróż, Komendant Główny Straży Granicznej przed przedstawieniem opinii może dokonać sprawdzeń, przeprowadzić konsultacje krajowe lub dokonać ustaleń dotyczących przedstawionych informacji lub dokumentów. Na negatywną opinię Komendanta Głównego Straży Granicznej w sprawie wniosku o wydanie zezwolenia na podróż (w tym wniosku o wydanie zezwolenia na podróż o ograniczonej ważności terytorialnej), o której mowa w art. 28 ust. 3 lit. b rozporządzenia 2018/1240, cudzoziemcowi przysługuje skarga do sądu administracyjnego w terminie 30 dni od dnia wysłania na adres poczty elektronicznej przez jednostkę krajową ETIAS innego państwa członkowskiego decyzji o odmowie wydania zezwolenia na podróż zgodnie z art. 28 ust. 7 rozporządzenia 2018/1240. Możliwość zaskarżenia negatywnej opinii wynika ze wzorów decyzji o odmowie wydania zezwolenia na podróż, w tym zezwolenia na podróż o ograniczonej ważności terytorialnej, zgodnie z art. 38 ust. 3 rozporządzenia 2018/1240.\nAnalogiczne czynności Komendant Główny Straży Granicznej będzie mógł również przeprowadzić przed unieważnieniem albo cofnięciem zezwolenia na podróż (sprawdzenia w systemach teleinformatycznych i bazach danych oraz konsultacje krajowe z innymi organami). \nKonieczność unieważnienia albo cofnięcia zezwolenia na podróż będzie analizowana przez Komendanta Głównego Straży Granicznej także w przypadku uzyskania informacji od innych organów administracji publicznej, które w wyniku własnej działalności będą posiadały dowody świadczące o tym, że warunki wydania zezwolenia na podróż nie były spełnione w momencie jego wydania lub, że cudzoziemiec przestał spełniać te warunki. Wskazać należy, że katalog organów administracji publicznej jest katalogiem otwartym. Takie rozwiązanie służy umożliwieniu pełnej realizacji obowiązków wynikających z udziału RP w ETIAS, w tym ma na celu podejmowanie wszelkich niezbędnych kroków w zakresie przyczyniania się do \fwysokiego poziomu bezpieczeństwa przez umożliwienie dokładnej oceny prawnej i faktycznej cudzoziemców pod kątem ryzyka dla bezpieczeństwa, zapobiegania nielegalnej imigracji oraz ochrony zdrowia publicznego. Każdy z organów w zakresie swojej właściwości rzeczowej przekazywał będzie informacje dotyczące cofnięcie albo unieważnienia zezwolenia na podróż. \nInformacje od organów przekazywane będą w formie elektronicznej. \n\n6. Ponowne rozpatrzenie sprawy\nWażny cel, realizowany poprzez opracowanie projektu przedmiotowej ustawy, stanowi konieczność określenia sposobu i trybu prowadzenia postępowania odwoławczego. W myśl art. 37 ust. 3 rozporządzenia 2018/1240 postępowanie takie prowadzi się zgodnie z prawem krajowym.  \nW projektowanej ustawie określono, że przysługującym cudzoziemcowi środkiem odwoławczym będzie wniosek o ponowne rozpatrzenie sprawy w przypadku decyzji o odmowie wydania zezwolenia na podróż, odmowie wydania zezwolenia na podróż o ograniczonej ważności terytorialnej, unieważnieniu oraz cofnięciu zezwolenia na podróż, w tym zezwolenia na podróż o ograniczonej ważności terytorialnej (z wyjątkiem cofnięcia zezwolenia na podróż na wniosek cudzoziemca posiadającego ważne zezwolenie na podróż), który rozpatruje Komendant Główny Straży Granicznej (art. 15). W celu zagwarantowania szybkiej oraz przejrzystej i zrozumiałej procedury dla wnioskodawcy (cudzoziemca), przewidziano możliwość złożenia elektronicznego wniosku o ponowne rozpatrzenie sprawy w terminie 7 dni od dnia wysłania powiadomienia o wydanej decyzji na adres poczty elektronicznej cudzoziemca. \nZe względu na rozpatrywanie wniosku o wydanie zezwolenia na podróż w sposób elektroniczny, również wniosek o ponowne rozpatrzenie sprawy będzie składany za pośrednictwem narzędzia teleinformatycznego Straży Granicznej (planowana jest dedykowana strona internetowa/narzędzie teleinformatyczne SG wskazane w powiadomieniu o decyzji, zgodnie z art. 38 ust. 2 i art. 42 rozporządzenia 2018/1240). Narzędzie teleinformatyczne Straży Granicznej jako narzędzie w ramach krajowego oprogramowania dla jednostki krajowej ETIAS będzie ułatwieniem dla cudzoziemców w zakresie możliwości dochodzenia swoich praw związanych ze sprawami o wydanie zezwolenia na podróż oraz kontynuacją czynności odwoławczych rozpoczętych w oparciu o tożsame rozwiązania techniczne. \nKomendant Główny Straży Granicznej będzie prowadził postępowanie w sprawie wniosku o ponowne rozpatrzenie sprawy tylko i wyłącznie w sposób elektroniczny za pośrednictwem krajowego oprogramowania dla jednostki krajowej ETIAS.\nZ uwagi na charakter prowadzonych czynności i narzędzia do tego wykorzystywane, do postępowania o ponowne rozpatrzenie sprawy nie będą miały zastosowania przepisy ustawy \fz dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego z wyjątkiem rozstrzygnięć w zakresie składania podpisów (art. 14 § 1a zdanie drugie Kpa), pełnomocnika (art. 32, art. 33 § 1–3 Kpa) oraz udziału prokuratora w postępowaniu (dział IV). Wnioskodawca będzie miał możliwość (w tym z dowolnego miejsca na świecie – wykluczenie barier formalnych) złożenia wniosku o ponowne rozpatrzenie sprawy za pomocą swojego uwierzytelnionego adresu poczty elektronicznej, a sama procedura będzie dla niego jasna i klarowna, nie powodując przy tym wątpliwości związanych ze stosowaniem procedur administracyjnych (różnorodność procedur odwoławczych stosowanych w państwach członkowskich zgodnie z ich prawem krajowym). \nZakres informacji niezbędnych do zainicjowania postępowania w przedmiocie ponownego rozpatrzenia sprawy nie będzie wpływał negatywnie na prawa cudzoziemców odnośnie możliwości skorzystania ze skutecznego prawa do środka odwoławczego. Możliwość złożenia wniosku (jednokrotnego) wygaśnie automatycznie z chwilą upływu terminu na jego złożenie, tj. po 7 dniach od dnia wysłania powiadomienia o wydaniu decyzji na adres poczty elektronicznej cudzoziemca, lub z chwilą, gdy wniosek taki zostanie już (we wskazanym terminie) prawidłowo złożony. Termin ten będzie liczony na zasadach ogólnych, zgodnie z którymi, jeżeli początkiem terminu określonego w dniach jest pewne zdarzenie, przy obliczaniu tego terminu nie uwzględnia się dnia, w którym zdarzenie nastąpiło (dzień wysłania powiadomienia o decyzji). Upływ ostatniego z wyznaczonej liczby dni uważa się za koniec terminu do złożenia wniosku o ponowne rozpatrzenie sprawy. Jednakże ze względu na całodobową dostępność narzędzia teleinformatycznego Straży Granicznej, nie będzie miał znaczenia fakt upływu terminu na złożenie wniosku o ponowne rozpatrzenie sprawy, jeżeli przypadnie on w dzień uznany ustawowo za wolny od pracy lub w sobotę. \nPonadto w przypadku niedostępności narzędzia teleinformatycznego Straży Granicznej, informacja o tym lub o usunięciu tej niedostępności, będzie publikowana w narzędziu teleinformatycznym Straży Granicznej, a termin złożenia wniosku o ponowne rozpatrzenie sprawy ulegnie zawieszeniu do czasu przywrócenia dostępności narzędzia teleinformatycznego Straży Granicznej, tj. termin ten zacznie biec ponownie z chwilą usunięcia wskazanej niedostępności i ulegnie wydłużeniu o okres niedostępności tego narzędzia. \nCelem właściwej identyfikacji wnioskodawcy (cudzoziemca), formularz wniosku będzie wskazywał konieczność podania, m.in. numeru wniosku o wydanie zezwolenia na podróż, o którym mowa w art. 19 ust. 2 rozporządzenia 2018/1240, numeru dokumentu podróży, daty urodzenia i adresu poczty elektronicznej, a także innych danych cudzoziemca. Wstępny etap złożenia wniosku będzie obejmował uwierzytelnienie za pomocą narzędzia uwierzytelniającego, przesłanego na adres poczty elektronicznej – analogicznie do procesów przetwarzania wniosków o wydanie zezwolenia na podróż lub samodzielnego cofnięcia \fzezwolenia na podróż. Pozytywne uwierzytelnienie, a następnie zawarcie uzasadnienia oraz załączenie dodatkowych dokumentów i informacji, niezbędnych do ponownej weryfikacji sprawy (sytuacji prawnej i faktycznej cudzoziemca), doprowadzi do poprawnego złożenia wniosku o ponowne rozpatrzenie sprawy. Wniosek o ponowne rozpatrzenie sprawy będzie zawierał dane i informacje, wypełnione w języku polskim, a także dokumenty wraz z ich tłumaczeniem na język polski oraz dołączone obligatoryjnie odwzorowanie cyfrowe (postać elektroniczna) dokumentu podróży, o którym mowa w art. 17 ust. 2 lit. d rozporządzenia 2018/1240 (dokument podróży wykorzystany przez cudzoziemca w ramach wniosku o wydanie zezwolenia na podróż) i podpisane oświadczenie osoby składającej wniosek, że podane informacje i przedstawione dokumenty są kompletne, autentyczne i prawidłowe, pod rygorem odpowiedzialności karnej wynikającej z art. 233 ustawy z dnia 6 czerwca 1997 r. – Kodeks karny. Klauzula złożona przez cudzoziemca, zastąpi pouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń.\nZa przyjęcie i rozpatrzenie przez Komendanta Głównego Straży Granicznej wniosku o ponowne rozpatrzenie sprawy będzie pobierana opłata, mająca stanowić dochód budżetu państwa, z wyłączeniem cudzoziemców, którzy w dniu składania wniosku o ponowne rozpatrzenie sprawy nie ukończyli osiemnastu lub ukończyli siedemdziesiąt lat, a także cudzoziemców zwolnionych z obowiązku wizowego, którzy spełniają określone warunki (są członkami rodziny obywatela Unii, do których ma zastosowanie dyrektywa 2004/38/WE, lub obywatela państwa trzeciego korzystającego z prawa do swobodnego przemieszczania się równoważnego prawu przysługującemu obywatelom Unii na mocy umowy między Unią i jej państwami członkowskimi z jednej strony a państwem trzecim z drugiej strony oraz nie posiadają karty pobytowej przewidzianej w dyrektywie 2004/38/WE ani dokumentu pobytowego przewidzianego w rozporządzeniu (WE) nr 1030/2002) – analogicznie do rozwiązań przyjętych w rozporządzeniu 2018/1240.\nOpłata ta będzie pobierana w chwili składania wniosku o ponowne rozpatrzenie sprawy, wyłącznie za pośrednictwem narzędzie teleinformatycznego Straży Granicznej, stanowiąc jeden z obligatoryjnych elementów procesu prawidłowego złożenia wniosku. Ponieważ wnioski wraz z opłatami będą wnoszone za pomocą narzędzia teleinformatycznego Straży Granicznej, wyeliminowane zostaną problemy i wątpliwości związane z mogącymi wystąpić przypadkami omyłkowego wniesienia opłaty. Jednocześnie brak uiszczenia opłaty nie będzie traktowany jako brak formalny, który może być uzupełniony, ze względu na obligatoryjność jej uiszczenia w toku procesu składania wniosku o ponowne rozpatrzenie sprawy. Brak uiszczenia takiej opłaty skutkować będzie niezłożeniem wniosku o ponowne rozpatrzenie sprawy.\nW projekcie ustawy przewidziano jednoznacznie, że opłata jest związana z czynnością \fprzyjęcia i rozpatrzenia wniosku o ponowne rozpatrzenie sprawy. Opłata ta wnoszona jest  za przyjęcie wniosku (za pośrednictwem narzędzia teleinformatycznego Straży Granicznej) i jego rozpatrzenie (rozpoznanie wniosku niezależnie od sposobu jego załatwienia, tj. decyzją kończącą postępowanie w zakresie zezwolenia na podróż albo powiadomieniem o pozostawieniu bez rozpoznania takiego wniosku). Wymagalność opłaty za przyjęcie i rozpatrzenie wniosku o ponowne rozpatrzenie sprawy jest zatem analogiczna do opłaty wnoszonej od każdego wniosku o wydanie zezwolenia na podróż, o której mowa w art. 18 rozporządzenia 2018/1240  bez względu na sposób jego rozstrzygnięcia. W związku z tym brak uiszczenia opłaty w chwili składania wniosku za pośrednictwem narzędzia teleinformatycznego Straży Granicznej uniemożliwi jego skuteczne złożenie. Proces złożenia wniosku będzie mógł być ponawiany do momentu skutecznego uiszczenia opłaty przez cudzoziemca, analogicznie do rozwiązań przyjętych w ramach procedury ubiegania się o wydanie zezwolenia na podróż. \nW zakresie wysokości przedmiotowej opłaty została przewidziana delegacja ustawowa dla ministra właściwego do spraw wewnętrznych do jej określenia w porozumieniu z ministrem właściwym do spraw finansów publicznych, a także ustawowo został określony zakres jej wysokości minimalnej oraz maksymalnej (nie niższa niż 100 złotych i nie wyższa niż 6,54% przeciętnego miesięcznego wynagrodzenia w gospodarce narodowej). \nWprowadzenie opłaty od wniosku o ponowne rozpatrzenie sprawy przyczyni się do zwiększenia efektywności postępowania administracyjnego (wpływ na dostęp innych cudzoziemców do procedur administracyjnych), ograniczenia nadużyć polegających na instrumentalnym składaniu wniosków (ograniczenie nadmiernej liczby wniosków, poprawa jakości składanych środków zaskarżenia) oraz racjonalizacji kosztów ponoszonych przez administrację publiczną. System opłat przewidziany w projektowanej ustawie jednakowo obowiązywać będzie wszystkich cudzoziemców, ze wskazanymi wyjątkami, zbieżnymi do przyjętych w rozporządzeniu 2018/1240. Zapewni to przejrzystość i równość stron w dostępie do środków zaskarżenia. \nOpłata ta jest formą ekwiwalentu za czynności podejmowane w sprawie indywidulanej cudzoziemca i ma na celu pokrycie kosztów administracyjnych za czynności urzędowe (opłata realizuje zasadę, że osoba która korzysta z określonych czynności administracyjnych powinna również partycypować w ich kosztach). Do tych kosztów zalicza się m.in.: konieczność zapewnienia tłumacza w przypadku gdy postępowanie nie będzie prowadzone w języku polskim, tj. może być wykorzystywany język angielski, a wykorzystanie innych języków jest możliwe po wcześniejszym uzgodnieniu (w celu możliwości zapewnienia udziału tłumacza w tych czynnościach – tłumaczenie ustne oraz pisemne), praca urzędników obsługujących organ, zabezpieczenie techniczne, w tym sprzęt teleinformatyczny oraz narzędzia \fteleinformatyczne uprawniające do złożenia wniosku o ponowne rozpatrzenie sprawy, inne koszty bezpośrednio związane z rozstrzygnięciem sprawy, np. inne czynności podejmowane wobec przedstawionych dokumentów i informacji przez cudzoziemca.\nJednocześnie opłata ta ma na celu znalezienie równowagi między powszechnym dostępem do środków zaskarżenia a potrzebą efektywnego zarządzania zasobami publicznymi i unikania nadmiernego obciążania systemu administracyjnego, przez co skraca się czas oczekiwania na wydanie rozstrzygnięcia. W założeniu projektodawcy wprowadzenie opłaty zachęci wnioskodawców (cudzoziemców) do staranniejszego zapoznania się z uzasadnieniem decyzji i podjęcia czynności w postaci, np. złożenia nowego wniosku o wydanie zezwolenia na podróż wraz z nowym dokumentem podróży, który nie został zgłoszony jako zagubiony.\nOpłata za przeprowadzone czynności związane z przyjęciem i rozpatrzeniem wniosku o ponowne rozpatrzenie sprawy ma charakter fiskalny i regulacyjny (zapewnienie dochodów dla budżetu państwa oraz uporządkowanie działań administracyjnych). Jednocześnie wnoszenie opłat od czynności jest powszechną praktyką mającą źródło w polskim systemie prawnym, np. złożenie wniosku o udzielenie cudzoziemcowi zezwolenia na pobyt lub zezwolenia na pracę, wydanie dokumentów pobytowych, wniesienie skargi do WSA/NSA lub zażaleń w sprawach sądowo-administracyjnych oraz w sprawach cywilnych w zakresie apelacji, zażaleń, skarg. Państwa członkowskie UE oraz państwa stosujące dorobek Schengen stosują zróżnicowane procedury odwoławcze względem decyzji administracyjnych. W niektórych państwach obowiązuje model dwuinstancyjności postępowania administracyjnego, gdzie decyzje administracyjne mogą być zaskarżone do organu odwoławczego, a następnie do sądu administracyjnego. W innych krajach skarga do sądu administracyjnego może być składana bezpośrednio, bez konieczności wcześniejszego odwołania się do organu odwoławczego. Krajowe procedury przewidują również obowiązek wniesienia opłat od składanych środków zaskarżenia (np. Dania, Portugalia, Austria).\nW kolejnych przepisach określono kwestie poświadczania zgodności z oryginałem dokumentów dołączanych do wniosku, a w celu usprawnienia procedury przewidziano, że te czynności, wzorem innych ustaw, będzie mógł dokonać również adwokat, radca prawny, rzecznik patentowy, a także doradca podatkowy. \nPodkreślić należy, że w celu dostępu do weryfikacji poprawności wymaganych danych składanych w ramach wniosku o ponowne rozpatrzenie sprawy, cudzoziemiec będzie miał zapewniony dostęp za pośrednictwem ogólnodostępnej strony internetowej i aplikacji na urządzenia mobilne. Udostępnienie informacji w trakcie postępowania odwoławczego, zawartych w pliku wniosku będzie odbywało się zgodnie z art. 37 ust. 3 rozporządzenia 2018/1240.\nWskazać należy, że złożenie wniosku o ponowne rozpatrzenie sprawy jest niezależną \fczynnością i w trakcie jego prowadzenia cudzoziemiec jest uprawniony do złożenia nowego odrębnego wniosku o wydanie zezwolenia na podróż oraz uzyskania pozytywnego rozstrzygnięcia, w tym uzyskania zezwolenia na podróż lub zezwolenia na podróż o ograniczonej ważności terytorialnej (LTV). Jednakże uzyskanie zezwolenia na podróż, na skutek ponownego wniosku, będzie wpływać na dalszą możliwość prowadzenia postępowania w zakresie wniosku o ponowne rozpatrzenie sprawy – pozostawienie wniosku bez rozpoznania. Wniosek o ponowne rozpatrzenie sprawy będą mogli składać cudzoziemcy (wnioskodawca) lub osoby upoważnione przez nich do złożenia wniosku w ich imieniu (pełnomocnicy posiadający stosowne pełnomocnictwo, którzy uiścili opłatę skarbową za złożenie pełnomocnictwa). Złożenie wniosku przez osobę upoważnioną przez wnioskodawcę, podlega opłacie skarbowej, o której mowa w art. 1 ust. 1 pkt 2 ustawy z dnia 16 listopada 2006 r. o opłacie skarbowej. W przypadku małoletnich, wniosek składa osoba sprawująca władzę rodzicielską lub opiekun prawny.\nCudzoziemiec (w tym jego przedstawiciele lub pełnomocnicy) będzie uprawniony do cofnięcia wniosku o ponowne rozpatrzenie sprawy przed wydaniem decyzji w tej sprawie przez Komendanta Głównego Straży Granicznej. W takim przypadku  będą miały zastosowanie przepisy dotyczące pozostawienia wniosku bez rozpoznania.\nW projekcie przewidziano możliwość uzupełnienia wniosku, który nie spełnia wymogów formalnych (np. złożenie wniosku bez wymaganego pełnomocnictwa lub przedstawienie informacji lub dokumentów w innym języku niż język polski), co będzie realizowane na wezwanie  Komendanta Głównego Straży Granicznej, w terminie 7 dni od dnia wysłania wezwania na adres poczty elektronicznej, pod rygorem pozostawienia wniosku bez rozpoznania.\nKompletny wniosek o ponowne rozpatrzenie sprawy rozpatruje się w terminie nie dłuższym niż 90 dni od dnia jego złożenia (w przypadku gdy cudzoziemiec uzupełni braki formalne wniosku lub informacje i dokumenty – termin ten liczony będzie od dnia ich uzupełnienia). Zważywszy na stopień złożoności ponownego rozpatrzenia sprawy oraz przewidzianą w projekcie konstrukcję tego procesu, obejmującego konieczność przeprowadzenia postępowania na nowo, z możliwością wezwania do dostarczenia dodatkowych dokumentów lub informacji, a także przeprowadzenia rozmowy z cudzoziemcem, dla wskazanego postępowania należy określić inny niż przewidziane w Kodeksie postępowania administracyjnego termin załatwienia sprawy. Z uwagi na złożoność tego postępowania podyktowaną rozmaitymi, nieraz niejednoznacznymi stanami faktycznymi oraz wysokim stopniem skomplikowania tych postępowań, zasadne jest ustanowienie przepisów dotyczących terminu załatwienia sprawy w tym przedmiocie, tj. w terminie nie dłuższym niż 90 dni.\fW uzasadnionych przypadkach termin ten będzie mógł zostać wydłużony – wskazanie nowego terminu załatwienia sprawy. Komendant Główny Straży Granicznej wskaże w takich okolicznościach powody niezałatwienia sprawy w terminie oraz doręczy takie powiadomienie na adres poczty elektronicznej. Do czynności podejmowanych w toku prowadzonego postępowania o ponowne rozpatrzenie sprawy, a także terminów ich realizacji, będą miały zastosowanie odpowiednio przepisy rozporządzenia 2018/1240. \nWskazać należy, że złożenie wniosku o ponowne rozpatrzenie sprawy nie będzie skutkować wstrzymaniem lub zawieszeniem wykonania zaskarżonych decyzji w związku z tym, że proces doręczenia powiadomień o wydanych decyzjach, zgodnie z art. 38 ust. 2 i art. 42 rozporządzenia 2018/1240, a następnie ich skutek (usunięcie zezwolenia na podróż z systemu centralnego ETIAS w związku z decyzją o unieważnieniu lub cofnięciu) wpływa automatycznie na brak uprawnień (odebranie tych uprawnień) związanych z posiadaniem ważnego zezwolenia na podróż. Powyższe wynika bezpośrednio z konstrukcji systemu informacyjnego ETIAS, jak i rozporządzenia 2018/1240, które obowiązuje jednakowo we wszystkich państwach członkowskich UE. W tym też względzie, informacje dotyczące ponownego rozpatrzenia sprawy będą zapisywane przez Komendanta Głównego Straży Granicznej w pliku wniosku (wywoływanie skutków prawnych, które wynikają z rozstrzygnięcia organu z chwilą jego wydania). \nPowyższe nie będzie miało zastosowania w przypadku decyzji wydawanych cudzoziemcom będącym członkami rodzin obywateli Unii Europejskiej lub cudzoziemców korzystających z prawa do swobodnego przemieszczania się równoważnego prawu przysługującemu obywatelom Unii Europejskiej na mocy umowy między Unią Europejską i jej państwami członkowskimi z jednej strony a państwem trzecim z drugiej, zgodnie z art. 24 ust. 6 lit. b rozporządzenia 2018/1240, z wyjątkiem sytuacji, w której wjazd lub pobyt wskazanych cudzoziemców może stanowić zagrożenie dla porządku publicznego, bezpieczeństwa wewnętrznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich. Wniesienie odwołania, o którym mowa w art. 37 ust. 3 rozporządzenia 2018/1240, odbywa się zgodnie z dyrektywą 2004/38/WE. \nZe względu na możliwość zmiany w dowolnym czasie przez cudzoziemca danych zawartych w pliku wniosku, zgodnie z art. 64 rozporządzenia 2018/1240 (np. przez stronę internetową lub aplikację na urządzenia mobilne), cudzoziemcy i ich przedstawiciele będą zobowiązani zawiadomić Komendanta Głównego Straży Granicznej o każdej zmianie danych, o których mowa w art. 17 ust. 2 rozporządzenia 2018/1240, zawartych w pliku wniosku, w tym o adresie poczty elektronicznej. Ma to na celu właściwą realizację czynności dotyczących ponownego rozpatrzenia sprawy oraz orzekanie w tych sprawach w oparciu o aktualne dane i okoliczności. W razie niedopełnienia tego obowiązku, związanego w szczególności \fze wskazaniem aktualnego adresu poczty elektronicznej, doręczenie na dotychczasowy adres poczty elektronicznej będzie miało skutek prawny.\nW projekcie ustawy określono przypadki, kiedy wniosek o ponowne rozpatrzenie sprawy zostanie pozostawiony bez rozpoznania. Przede wszystkim dotyczy to sytuacji, gdy w terminie na złożenie wniosku o ponowne rozpatrzenie sprawy lub w terminie załatwienia tej sprawy, w wyniku odrębnego wniosku zostanie wydane zezwolenie na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240. Wskazać należy, że wydanie nowego zezwolenia na podróż prowadzi do bezprzedmiotowości prowadzonego postępowania w sprawie wniosku o ponowne rozpatrzenie sprawy. Jednocześnie cudzoziemiec nie jest uprawniony do posiadania wielu ważnych zezwoleń na podróż (bez uszczerbku dla zezwoleń na podróż o ograniczonej ważności terytorialnej) – posiadacz zezwolenia na podróż (cudzoziemiec) może złożyć wniosek o nowe zezwolenie na podróż najwcześniej 120 dni przed utratą ważności posiadanego zezwolenia na podróż. System centralny ETIAS uniemożliwia dublowanie wniosków o wydanie zezwolenia na podróż czy też uzyskiwanie wielu takich zezwoleń.  \nPonadto dotyczyć to będzie przypadków, gdy usunięto plik wniosku, w związku z okolicznościami, o których mowa w art. 54 ust. 1 lit. b rozporządzenia 2018/1240 (po okresie 5 lat lub usunięciu danych wywołujących trafienie) albo zgodnie z procedurą określoną w art. 55 ust. 5 i 6 rozporządzenia 2018/1240, m.in. uzyskanie obywatelstwa państwa członkowskiego, statusu uchodźcy, bezpaństwowca albo jeżeli cudzoziemiec nie uzupełni w terminie wymogów formalnych wniosku o ponowne rozpatrzenie sprawy, a także gdy postępowanie stanie się bezprzedmiotowe z powodu innych okoliczności faktycznych lub prawnych (np. upływ ważności dokumentu podróży związanego z zezwoleniem na podróż, śmierć strony, upływ ważności zezwolenia na podróż w przypadku postępowań dotyczących cofnięcia lub unieważnienia tego zezwolenia albo cofnięcia wniosku o ponowne rozpatrzenie sprawy). Powiadomienie w takim przypadku będzie również doręczane na adres poczty elektronicznej.\n\tCelem zagwarantowania jasności postępowania prowadzonego z wykorzystaniem narzędzia teleinformatycznego, po upływie terminu na złożenie wniosku o ponowne rozpatrzenie sprawy, cudzoziemiec otrzyma automatyczną informację o braku możliwości złożenia wniosku o ponowne rozpatrzenie sprawy. Tym samym ewentualna próba złożenia takiego wniosku po upływie terminu nie będzie możliwa. Jednocześnie prawidłowość złożenia takiego wniosku, skutkować będzie przesłaniem powiadomienia na adres poczty elektronicznej o złożeniu wniosku o ponowne rozpatrzenie sprawy dotyczącej zezwolenia na podróż.\nCelem zabezpieczenia właściwego interesu strony w toku prowadzonego postępowania odwoławczego (ponowne rozpatrzenie sprawy), w kolejnym przepisie wskazano, że cudzoziemiec wraz ze składanym wnioskiem o ponowne rozpatrzenie sprawy może \fjednocześnie zawnioskować o udostępnienie informacji zawartych w pliku wniosku (art. 19). Jednakże nie będzie to dotyczyć sytuacji, gdy wskazane informacje cudzoziemiec będzie mógł uzyskać samodzielnie za pośrednictwem ogólnodostępnej strony internetowej lub aplikacji na urządzenia mobilne, o których mowa w art. 16 rozporządzenia 2018/1240 zgodnie z prawami dostępu do danych, o których mowa w art. 64 rozporządzenia 2018/1240. Spowoduje to nieuwzględnienie wniosku w związku z możliwością bezpośredniego uzyskania tych informacji przez cudzoziemca. \nInformacje z pliku wniosku doręcza się w terminie 14 dni od dnia złożenia wniosku, zgodnie z przepisami art. 56 rozporządzenia 2018/1240. Termin ten będzie liczony od dnia złożenia kompletnego wniosku (w przypadku gdy cudzoziemiec uzupełnił wymogi formalne wniosku – termin ten liczony będzie od dnia ich uzupełnienia). Jednocześnie w uzasadnionych przypadkach Komendant Główny Straży Granicznej będzie miał możliwość nieuwzględnienia wniosku, np. w związku z okolicznościami wynikającymi z ustawy z dnia 14 grudnia 2018 r. o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości lub ustawy z dnia 5 sierpnia 2010 r. o ochronie informacji niejawnych. Komendant Główny Straży Granicznej będzie przekazywał powiadomienie o przyczynach nieuwzględnienia wniosku o udostępnienie informacji zawartych w pliku wniosku na adres poczty elektronicznej. Odstąpienie od wskazania powodów nieuwzględnienia wniosku będzie możliwe z uwagi na względy obronności lub bezpieczeństwa państwa lub ochrony bezpieczeństwa i porządku publicznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich.\nCelem zapewnienia pełnej regulacji w zakresie krajowego postępowania odwoławczego, w projektowanych przepisach określono rodzaje rozstrzygnięć (decyzji) wydawanych przez Komendanta Głównego Straży Granicznej w wyniku ponownego rozpatrzenia sprawy (utrzymanie w mocy zaskarżonej decyzji lub jej uchylenie, a odnośnie decyzji o odmowie wydania zezwolenia na podróż – w przypadku jej uchylenia – także wydanie zezwolenia na podróż lub zezwolenia na podróż o ograniczonej ważności terytorialnej), a ponadto sposób doręczenia wskazanych decyzji (na adres poczty elektronicznej). Utrzymanie w mocy zaskarżonej decyzji oznaczać będzie zatem, że w ocenie organu nadal istnieją przesłanki negatywnie do wydania cudzoziemcowi zezwolenia na podróż zgodnie z art. 37 ust. 1 i 2 rozporządzenia 2018/1240 oraz przesłanki do cofnięcia albo unieważnienia zezwolenia na podróż zgodnie z art.  40 i art. 41 rozporządzenia 2018/1240.\nW przepisach projektowanej ustawy wskazano decyzje wydawane w wyniku ponownego rozpatrzenia sprawy (o utrzymaniu w mocy decyzji o odmowie wydania zezwolenia na podróż, odmowie wydania zezwolenia na podróż o ograniczonej ważności terytorialnej, o unieważnieniu lub cofnięciu zezwolenia na podróż, w tym zezwolenia na podróż \fo ograniczonej ważności terytorialnej), od których cudzoziemcowi będzie przysługiwało uprawnienie do wniesienia skargi do sądu administracyjnego, w terminie 30 dni od dnia doręczenia decyzji na adres poczty elektronicznej. Jednocześnie, nie będzie miał zastosowania art. 52 § 3 ustawy z dnia 30 sierpnia 2002 r. – Prawo o postępowaniu przed sądami administracyjnymi. Brak przeprowadzenia całej procedury odwoławczej (ponownego rozpatrzenia sprawy), stanowić będzie zatem niespełnienie wymogu koniecznego do rozpoczęcia procedury sądowo-administracyjnej. Wobec powyższego decyzja wydana w wyniku ponownego rozpatrzenia sprawy umożliwi cudzoziemcowi dalsze dochodzenie swoich praw przed sądem administracyjnym. Decyzje będą zawierać pouczenie o dopuszczalności i trybie wniesienia skargi do sądu administracyjnego oraz wysokości opłaty od wpisu od skargi, jeżeli mają one charakter stały, albo podstawie do wyliczenia opłaty od wpisu o charakterze stosunkowym, a także możliwości ubiegania się przez stronę o zwolnienie od kosztów albo przyznanie prawa pomocy.\nW kolejnych przepisach określono elementy decyzji wydawanej po przeprowadzeniu ponownego rozpatrzenia sprawy i formę ich wydania (art. 22 ust. 2 i 3), a także kwestie podstaw odstąpienia od ich uzasadnienia (można odstąpić od wskazania powodów rozstrzygnięcia faktycznego, jeżeli wymagają tego względy obronności lub bezpieczeństwa państwa lub ochrony bezpieczeństwa i porządku publicznego lub stosunków międzynarodowych któregokolwiek z państw członkowskich), a ponadto terminy doręczeń decyzji, wezwań oraz powiadomień (za dzień doręczenia uznaje się dzień wysłania korespondencji na adres poczty elektronicznej wnioskodawcy za pośrednictwem europejskiego oprogramowania dla jednostek krajowych ETIAS lub za pośrednictwem krajowego oprogramowania dla jednostki krajowej ETIAS).\nPrzyjęty tryb oraz wskazanie dnia doręczenia odnosi się do rozporządzenia 2018/1240 w zakresie rozpoczęcia terminów na wykonanie określonych czynności, m.in. zgodnie z art. 27 ust. 6 rozporządzenia 2018/1240 przeprowadzenie rozmowy z wnioskodawcą odbywa się w ciągu 10 dni od dnia wysłania zaproszenia. Wykorzystanie przez cudzoziemców komercyjnych skrzynek pocztowych (adresów poczty elektronicznej) nie potwierdza czasu doręczenia oraz doręczonej treści, co w sposób zasadniczy wpływa na pewność doręczeń elektronicznych (nie daje rzeczywistej daty odbioru korespondencji). Wysłanie korespondencji na komercyjny adres poczty elektronicznej nie spełnia wymogów związanych z zasadą komunikacji elektronicznej z organami administracji publicznej z wykorzystaniem spełniającej standard usługi rejestrowanego doręczenia elektronicznego lub publicznej usługi hybrydowej, o których mowa w ustawie z dnia 18 listopada 2020 r. o doręczeniach elektronicznych (brak możliwości zastosowana wskazanej ustawy w związku z rozwiązaniami systemowymi przyjętymi w rozporządzeniu 2018/1240). Tym samym to wnioskodawca (cudzoziemiec) \fbędzie odpowiedzialny za aktualność, prawidłowość oraz bieżący dostęp do adresu poczty elektronicznej celem odbioru wszelkiej korespondencji w jego sprawie. \n\n7. Lista ostrzegawcza ETIAS\nProjektowany rozdział 6 dotyczy listy ostrzegawczej ETIAS, która będzie zawierała dane dotyczące osób podejrzanych o popełnienie przestępstwa terrorystycznego lub innego poważnego przestępstwa lub o udział w nich, lub osób, względem których istnieją przesłanki faktyczne lub uzasadnione podstawy – oparte na ogólnej ocenie danej osoby – aby sądzić, że osoby te popełnią przestępstwo terrorystyczne lub inne poważne przestępstwo. Wskazać należy, że dane zawarte na liście ostrzegawczej ETIAS będą nie tylko wykorzystane do celów rozporządzenia 2018/1240, tj. spraw związanych z zezwoleniami na podróż, lecz także w ramach narzędzi interoperacyjności systemów wielkoskalowych Unii Europejskiej w zakresie automatycznej wymiany informacji między nimi o obywatelach państw trzecich, tj. System Wjazdu/Wyjazdu („EES”), ustanowiony rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2017/2226, Wizowy System Informacyjny („VIS”), ustanowiony rozporządzeniem Parlamentu Europejskiego i Rady (WE) 767/2008, System Informacyjny Schengen („SIS”), ustanowiony rozporządzeniami Parlamentu Europejskiego i Rady (UE) 2018/1860, 2018/1861 i 2018/1862, system Eurodac, ustanowiony rozporządzeniem Parlamentu Europejskiego i Rady (UE) nr 603/2013, oraz europejski system przekazywania informacji z rejestrów karnych – obywatele państw trzecich („ECRIS-TCN”), ustanowiony rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2019/816. \nLista ostrzegawcza ETIAS będzie składać się z danych zawierających co najmniej jeden z następujących elementów: nazwisko, nazwisko przy urodzeniu, data urodzenia, inne imiona i nazwiska (pseudonimy, pseudonimy artystyczne, imiona i nazwiska zwyczajowe), dokument lub dokumenty podróży (rodzaj, numer i państwo wydania dokumentu lub dokumentów podróży), adres domowy, adres e-mail, numer telefonu, nazwa, adres e-mail, adres pocztowy, numer telefonu firmy lub organizacji, adres IP, a ponadto – o ile będą dostępne – imię (imiona), miejsce urodzenia, państwo urodzenia, płeć i obywatelstwo (tylko w połączeniu z danymi wskazanymi enumeratywnie).\nZgodnie z art. 25 projektu organem właściwym do wprowadzania danych do listy ostrzegawczej ETIAS oraz zarządzającym wpisami krajowymi w liście ostrzegawczej ETIAS będzie Komendant Główny Straży Granicznej, a dane będą wprowadzane na wniosek organu, w którego posiadaniu się znajdują. Dane będą wprowadzane (lub w stosownych przypadkach modyfikowane, uzupełniane lub usuwane) w związku z przesłaniem elektronicznego wniosku organu będącego właścicielem danych, zgodnie z zakresem danych wskazanych w art. 34 ust. 4 rozporządzenia 2018/1240. Wskazany wniosek będzie zawierać umotywowanie (faktyczne \foraz prawne) uzasadnienie wprowadzenia lub aktualizacji danych do listy ostrzegawczej ETIAS oraz datę początkową i datę końcową okresu ważności wpisu. Ze względu na elektroniczny sposób prowadzenia listy ostrzegawczej ETIAS, wniosek o dokonanie wpisu (w tym usunięcie lub modyfikację wpisu) będzie przekazywany w formie elektronicznej, tj. za pośrednictwem własnego systemu teleinformatycznego  albo aplikacji WWW ETIAS. W wyjątkowych przypadkach, za zgodą Komendanta Głównego Straży Granicznej, wniosek będzie mógł zostać przekazany za pośrednictwem alternatywnego kanału elektronicznej wymiany informacji.\nDanych wprowadzonych do listy ostrzegawczej ETIAS, w tym informacji o ich zakresie, nie udostępnia się w związku z ustawą z dnia 14 grudnia 2018 r. o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości, która określa zasady i warunki ochrony danych osobowych przetwarzanych przez właściwe organy w celu rozpoznawania, zapobiegania, wykrywania i zwalczania czynów zabronionych, w tym zagrożeń dla bezpieczeństwa i porządku publicznego, a także wykonywania tymczasowego aresztowania, kar porządkowych i środków przymusu skutkujących pozbawieniem wolności oraz prawa osób, których dane osobowe są przetwarzane przez właściwe organy.\nPrawo do wystąpienia o wprowadzenie danych (w tym usunięcie lub modyfikację wpisu) do listy ostrzegawczej ETIAS, zgodnie z art. 26, będzie przysługiwało: prokuratorowi, Straży Granicznej, Policji, Krajowej Administracji Skarbowej, Szefowi Urzędu do Spraw Cudzoziemców, ministrowi właściwemu do spraw wewnętrznych, ministrowi właściwemu do spraw zagranicznych, Agencji Bezpieczeństwa Wewnętrznego, Agencji Wywiadu, Centralnemu Biuru Antykorupcyjnemu, Służbie Ochrony Państwa, Służbie Kontrwywiadu Wojskowego, Służbie Wywiadu Wojskowego i Żandarmerii Wojskowej. Prawo to dotyczyć będzie również aktualizacji lub usuwania danych już wprowadzonych do listy ostrzegawczej ETIAS (właściwość organu w zakresie obowiązującego własnego wpisu na liście ostrzegawczej ETIAS).\nProjektowany art. 27 ma zagwarantować brak powielania danych wskazanych w art. 34 ust. 4 rozporządzenia 2018/1240 na liście ostrzegawczej ETIAS oraz tożsamych danych w Systemie Informacyjnym Schengen. Celem tego rozwiązania jest nadanie priorytetu wpisom dokonywanym w Systemie Informacyjnym Schengen. Jeżeli spełnione będą warunki dokonania wpisu w Systemie Informacyjnym Schengen (w odniesieniu do warunków wskazanych w rozporządzeniach: UE 2018/1860, UE 2018/1861 oraz UE 2018/1862) organy nie powinny wnioskować o wprowadzenie danych do listy ostrzegawczej ETIAS. Organ będący właścicielem danych i występujący z wnioskiem o wpis na liście ostrzegawczej ETIAS, będzie zatem odpowiedzialny za dokonanie sprawdzeń obowiązywania wpisów w Systemie Informacyjnym Schengen na etapie złożenia takiego wniosku o wpis na liście ostrzegawczej \fETIAS oraz już podczas obowiązywania tego wpisu na liście ostrzegawczej ETIAS. \nKolejny przepis wskazuje na uprawnienia Komendanta Głównego Straży Granicznej w procesie zarządzania krajowymi wpisami na liście ostrzegawczej ETIAS. Krajowe wpisy na liście ostrzegawczej ETIAS dotyczą tylko wpisów dokonanych na podstawie wniosków uprawnionych organów, o których mowa w art. 26. W tym miejscu należy wskazać, że za merytoryczną część adekwatności i zasadności wpisu, odpowiedzialny będzie kompetentny organ wnioskujący o wprowadzenie, aktualizację (modyfikację lub uzupełnienie) lub usunięcie danych z listy ostrzegawczej ETIAS. Komendant Główny Straży Granicznej, jako organ wyznaczony do zarządzania tymi wpisami, czuwać będzie nad procesem wprowadzania danych do listy poprzez ocenę wniosku w celu ustalenia, czy dane w nim zawarte są adekwatne, dokładne i wystarczająco ważne, aby zostały włączone do listy ostrzegawczej ETIAS i że wprowadzenie tych danych nie będzie prowadziło do nieproporcjonalnie dużej liczby wniosków, które miałyby być przetwarzane ręcznie przez jednostkę krajową ETIAS w wyniku weryfikacji przeprowadzonej z wykorzystaniem dedykowanego narzędzia oceny wpływu wskazanego w art. 6 ust. 2 lit. j i art. 35 ust. 1 lit. b rozporządzenia 2018/1240. Jednocześnie wpisy w liście ostrzegawczej ETIAS będą podlegać późniejszym weryfikacjom, o których mowa w art. 9e rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 767/2008 oraz art. 35a rozporządzenia 2018/1240. Ocena formalna wniosku (nie jest to merytoryczna ocena wprowadzanych względem właściwości każdego z wymienionych organów i służb) prowadzić będzie do wpisu danych do listy ostrzegawczej ETIAS lub nieuwzględnienia wniosku o wprowadzenie danych.\nJednocześnie w zakresie wniosku o wprowadzenie, aktualizacje lub usunięcie danych z listy ostrzegawczej ETIAS lub już obowiązujących wpisów na tej liście, Komendant Główny Straży Granicznej będzie uprawniony do wystąpienia o przekazanie dodatkowych informacji, w terminie na udzielenie odpowiedzi nie dłuższym niż 7 dni. Brak udzielenia takiej odpowiedzi w nieprzekraczalnym terminie 7 dni, skutkować będzie mógł nieuwzględnieniem wniosku o wprowadzenie, aktualizacje lub usunięcie danych z listy ostrzegawczej ETIAS lub też aktualizacją lub usunięciem danych wprowadzonych do listy ostrzegawczej ETIAS zgodnie z art. 35 ust. 4 i 6 rozporządzenia 2018/1240 w oparciu o posiadane informacje przez Komendanta Głównego Straży Granicznej.\nW przypadku nieuwzględnienia wniosku o wprowadzenie, aktualizację lub usunięcie danych z listy ostrzegawczej ETIAS, Komendant Główny Straży Granicznej będzie obowiązany powiadomić organ wnioskujący o powodach nieuwzględnienia wniosku. Wpis danych do listy ostrzegawczej ETIAS nie będzie wymagał stosowania przepisów Kodeksu postępowania administracyjnego, a tym samym wydania odrębnej decyzji administracyjnej umożliwiającej dokonanie wpisu oraz przekazania informacji obywatelowi państwa trzeciego \fo wpisaniu jego danych do listy ostrzegawczej ETIAS.\nOrgan będący właścicielem danych, które zostały wprowadzone do listy ostrzegawczej ETIAS, będzie odpowiedzialny za weryfikację i ocenę ich aktualności oraz prawdziwości, zgodnie z wymogami rozporządzenia 2018/1240, tj. nie rzadziej, niż raz w roku od daty zarejestrowania danych na liście ostrzegawczej ETIAS lub przed terminem utraty ważności danego wpisu, w przypadku wpisów ważnych poniżej 12 miesięcy. Dokonanie takiej weryfikacji będzie podstawą do przedłużenia obowiązywania wpisu (wniosek o aktualizację wpisu). Jeżeli okres ważności danego wpisu figurującego na liście ostrzegawczej ETIAS będzie krótszy niż dwanaście miesięcy, wpis ten będzie automatycznie usuwany po upływie okresu ważności, chyba że przed tą datą okres ten zostanie przedłużony (aktualizacja okresu obowiązywania wpisu) w związku z przeprowadzoną weryfikacją przez właściwy organ wnioskujący. Jednocześnie system centralny ETIAS, przed automatycznym usunięciem wpisu figurującego na liście ostrzegawczej ETIAS, prześle użytkownikowi, automatyczne powiadomienie o upływie terminu jego obowiązywania (takie powiadomienie będzie również widoczne dla organu będącego właścicielem danych za pośrednictwem dedykowanego narzędzia i rozwiązania teleinformatycznego udostępnionego innym organom przez Straż Graniczną).\nDalsze projektowane rozwiązania dotyczą sytuacji uzyskania trafienia krajowego (polskiego) wpisu na liście ostrzegawczej ETIAS. W takim przypadku Komendant Główny Straży Granicznej będzie uprawniony do przeprowadzenia czynności sprawdzenia cudzoziemca w krajowych bazach danych oraz konsultacji krajowych z organem będącym właścicielem danych, które zostały zarejestrowane oraz uzyskania opinii i danych szczegółowych uzasadniających wpis do listy ostrzegawczej ETIAS (w tym materiałów niejawnych). \nOrgany będące właścicielami danych na liście ostrzegawczej ETIAS (wymienione w art. 26) wyznaczą punkty kontaktowe w celu wydania opinii o cudzoziemcu, którego dane zostały zarejestrowane na liście ostrzegawczej ETIAS. Jednocześnie, zgodnie z art. 28 rozporządzenia 2018/1240, sytuacja cudzoziemca będzie przedmiotem dalszych konsultacji w celu wydania opinii z odpowiedzialnymi jednostkami krajowymi ETIAS innych państw członkowskich UE (wskazane punkty kontaktowe mogą być tożsame względem punktów kontaktowych, o których mowa w art. 10 projektu). \n\n8. Bezpieczeństwo KSI ETIAS i ochrona danych osobowych w KSI ETIAS\nIstotnym rozstrzygnięciem w kontekście bezpieczeństwa KSI ETIAS jest określony w art. 31 obowiązek współpracy wskazanych organów, uprawnionych do przetwarzania danych ETIAS, z Komendantem Głównym Straży Granicznej w celu realizacji zadań związanych \fz udziałem w systemie ETIAS, w tym odnośnie przekazywania dokumentów, udzielania informacji oraz przekazywania aktualnych danych niezbędnych do prowadzenia wykazu jednostek operacyjnych (w ramach wyznaczonych organów) oraz organów uprawnionych do przetwarzania danych ETIAS i mających dostęp do ETIAS, celem dalszego przesyłania informacji w tym zakresie przez Komendanta Głównego Straży Granicznej, a także zgłaszania przez wskazane organy ujawnionych nieprawidłowości w związku z przetwarzaniem danych ETIAS poprzez KSI ETIAS.\nOkreślono także organ sprawujący nadzór nad prawidłowością działania KSI ETIAS oraz zakres uprawnień mu przyznanych w celu wykonywania nadzoru. Organem tym będzie minister właściwy do spraw wewnętrznych. Ponadto celem zapewnienia właściwego przepływu informacji w tym obszarze nałożony został obowiązek Komendanta Głównego Straży Granicznej względem ministra właściwego do spraw wewnętrznych, odnośnie konieczności przedstawiania w terminie do dnia 31 marca każdego roku, informacji dotyczących oceny funkcjonowania KSI ETIAS w poprzednim roku kalendarzowym, w tym technicznego działania KSI ETIAS. \nArt. 35 zawiera delegację ustawową do wydania przez ministra właściwego do spraw wewnętrznych aktu wykonawczego określającego warunki techniczne dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS.\n\nW projekcie ustawy określono zasady ochrony danych osobowych w KSI ETIAS, które w ocenie projektodawcy skutecznie wyeliminują wszelkie niebezpieczeństwa, które mogłyby wpływać na realizację przepisów ustawy oraz udział RP w systemie ETIAS.\nRozporządzenie 2018/1240 w rozdziale XII bezpośrednio reguluje kwestie ochrony danych odnosząc się zarówno do roli i zadań jednostki krajowej ETIAS, jak również innych służb i organów przetwarzających dane osobowe. \nSzczególna rola przypisana jednostce krajowej ETIAS wynika przede wszystkim z art. 57 ust. 2 rozporządzenia 2018/1240, zgodnie z którym jest ona uznawana za administratora danych. Tylko jednostka krajowa ETIAS wprowadza dane do systemu centralnego ETIAS, dokonuje ich sprostowania lub usunięcia (art. 64 ust. 2 rozporządzenia 2018/1240), przyjmuje niezbędne środki, w tym plan bezpieczeństwa, ciągłości działania oraz przywrócenia ciągłości działania, w celach określonych w art. 59 ust. 3 rozporządzenia 2018/1240, a także informuje oraz jest informowana o incydentach bezpieczeństwa (art. 60 rozporządzenia 2018/1240). Wskazane rozstrzygnięcia znalazły odzwierciedlenie w projektowanej ustawie, w kontekście przypisania określonemu organowi krajowym obowiązków informacyjnych, w szczególności art. 5 ust. 3 pkt 10 oraz art. 6 ust. 2 pkt 11–14 projektu.\nW odniesieniu do organów i służb przetwarzających dane osobowe w związku \fz realizacją zadań prawodawca unijny w art. 56 rozporządzenia 2018/1240 określił wprost przepisy, które znajdują tu zastosowanie. Będzie to odpowiednio, w zależności od celu przetwarzania, rozporządzenie (UE) 2016/679 albo dyrektywa (UE) 2016/680. Należy przyjąć, że obowiązki i uprawnienia określonych w ustawie organów uprawnionych do przetwarzania danych ETIAS, w odniesieniu do przetwarzanych danych osobowych będą realizowane i wykorzystywane analogicznie, jak w przypadku danych osobowych pozyskiwanych z innych źródeł, zgodnie z przyznanymi uprawnieniami i w celu realizacji zadań wynikających z ustaw, a także przepisów prawa UE. \nW związku z powyższym przedmiot regulacji ustawowej został ograniczony do wprowadzanych rozwiązań krajowych w zakresie dostępu do KSI ETIAS oraz przetwarzania danych poprzez KSI ETIAS.\nW projektowanym art. 36, w szczególności:\n1)\tokreślono obowiązek wykonywania przez organ uprawniony do dostępu do KSI ETIAS oraz przetwarzania danych ETIAS poprzez KSI ETIAS, szkoleń wszystkich osób, które mają realizować w jego imieniu to uprawnienie, w zakresie użytkowania KSI ETIAS – przed wydaniem upoważnienia użytkownika końcowego i użytkownika indywidualnego (niezależnie czy będzie to realizowane za pośrednictwem własnego systemu teleinformatycznego organu uprawnionego do przetwarzania danych czy też aplikacji WWW ETIAS);\n2)\twskazano, że zadania administratora danych osobowych przetwarzanych w KSI ETIAS będzie wykonywał Komendant Główny Straży Granicznej, który jest zarządzającym systemem i administratorem danych w tym systemie przetwarzanych;\n3)\twprowadzono pojęcia użytkownika indywidualnego i końcowego, w celu zróżnicowania rodzajów i zakresów dostępu dla użytkowników systemu KSI ETIAS,\n4)\twskazano jakie elementy powinno zawierać upoważnienie oraz doprecyzowano tryb udzielania i cofania upoważnień;\n5)\twskazano jakie elementy powinien zawierać wniosek o nadanie i cofnięcie uprawnień dla użytkownika indywidualnego;\n6)\tokreślono elementy ewidencji uprawnień i upoważnień.\nPonadto wprowadzono delegację do wydania przez ministra właściwego do spraw wewnętrznych rozporządzenia, w którym zostanie określony wzór upoważnienia do dostępu do KSI ETIAS oraz przetwarzania danych ETIAS poprzez KSI ETIAS użytkownika końcowego i użytkownika indywidualnego, wzór oświadczenia o zobowiązaniu do zapewnienia bezpieczeństwa danych osobowych, w tym ochrony przed niedozwolonym lub niezgodnym z prawem przetwarzaniem danych osobowych oraz ich przypadkową utratą, zniszczeniem lub uszkodzeniem, a także sposób przekazywania informacji o przydzielonym spersonalizowanym identyfikatorze i haśle (do aplikacji WWW ETIAS) – mając na względzie zapewnienie \fbezpieczeństwa danych oraz prawidłową realizację przez Rzeczpospolitą Polską obowiązków wynikających z udziału w ETIAS.\nOrgan uprawniony do przetwarzania danych ETIAS, będzie decydował samodzielnie o udzieleniu lub cofnięciu upoważnienia do dostępu do KSI ETIAS oraz przetwarzania danych ETIAS poprzez KSI ETIAS użytkownikowi indywidualnemu lub użytkownikowi końcowemu. Proces ten będzie obejmował możliwość dostępu do danych ETIAS za pośrednictwem własnego systemu teleinformatycznego (użytkownik końcowy) albo aplikacji WWW ETIAS (użytkownik indywidualny). Wzór upoważnienia obejmie zatem możliwość udzielenia upoważnienia funkcjonariuszowi lub pracownikowi dla obu rodzajów użytkowników. W gestii organu będzie pozostawała decyzja z jakiego narzędzia dostępu do danych ETIAS będzie korzystał upoważniony w ramach tego organu funkcjonariusz lub pracownik. Istnieje zatem możliwość realizacji części udzielonego upoważnienia jako użytkownik końcowy oraz jako użytkownik indywidualny, jak również korzystania z obu narzędzi łącznie, np. ze względu na specyfikę zadań. Takie rozwiązanie stanowi uproszczenie procedur związanych z udzielaniem upoważnień oraz nadawaniem uprawnień względem dotychczasowych rozwiązań funkcjonujących w ramach innych systemów informacyjnych Unii Europejskiej.\nW sytuacji gdy organ zdecyduje się udzielić upoważnienia swojemu funkcjonariuszowi lub pracownikowi jako użytkownikowi indywidualnemu, organ ten w celu nadania uprawnień do aplikacji WWW ETIAS, złoży wniosek o nadanie takich uprawnień do Komendanta Głównego Straży Granicznej. Poprzez nadanie uprawnień należy rozumieć również możliwość zmiany zakresu takich uprawnień (jako ponowne nadanie) dla już istniejącego użytkownika indywidualnego (dodanie kolejnych uprawnień albo ograniczenie zakresu uprawnień do aplikacji WWW ETIAS). Nadanie uprawnień do aplikacji WWW ETIAS zostanie potwierdzone przydzielonym spersonalizowanym identyfikatorem oraz hasłem (które umożliwią logowanie do aplikacji WWW ETIAS i dostęp do danych ETIAS).  W przypadku gdy użytkownik indywidualny posiada spersonalizowany identyfikator oraz hasło posiada, nie będą one ponownie przydzielanie w związku ze zmianą zakresu uprawnień do aplikacji WWW ETIAS. \nW celu składania wniosków o nadanie lub cofnięcie uprawnień dla użytkowników indywidualnych, organ w ramach swojej struktury wyznaczy upoważnione osoby, np. lokalnych administratorów bezpieczeństwa zbiorów lub inne osoby, o których poinformuje Komendanta Głównego Straży Granicznej. Wskazane osoby będą uprawnione do składania ww. wniosków oraz zarządzania uprawnieniami do aplikacji WWW ETIAS w ramach organu. Wymienionym osobom zostanie również przydzielony spersonalizowany identyfikator oraz hasło (umożliwiające logowanie do aplikacji WWW ETIAS oraz składanie wniosków o nadanie lub cofnięcie uprawnień dla użytkowników indywidualnych). \fW sytuacji gdy osoba będzie już wcześniej miała nadany spersonalizowany identyfikator oraz hasło, będą one dalej wykorzystywane w celu, np. nadania kolejnych uprawnień związanych z aplikacją WWW ETIAS, ich rozszerzenia lub ograniczenia.\nJednocześnie, Komendant Główny Straży Granicznej, w przypadku nieuwzględnienia wniosku o nadanie uprawnień użytkownikowi indywidualnemu, będzie informował organ uprawniony do przetwarzania danych ETIAS o przyczynach nieuwzględnienia wniosku.\nW związku z przyjęciem rozwiązań w zakresie nadawania uprawnień dla użytkowników indywidualnych w formie elektronicznej, koniecznym było wypracowanie metod umożliwiających uprawnionym organom realizację tego procesu. \nEwidencja uprawnień do aplikacji WWW ETIAS będzie prowadzona przez Komendanta Głównego Straży Granicznej i obejmie użytkowników indywidualnych, jak również osoby, które w ramach organu są upoważnione do wnioskowania o nadanie uprawnień dla użytkowników indywidualnych. \nEwidencję upoważnień (udzielonych upoważnień dla użytkowników końcowych i użytkowników indywidualnych) będzie prowadził każdy organ, który takich upoważnień udzielił. Powyższe rozwiązanie pozwoli organom na właściwe zarządzanie dostępem do danych ETIAS przez podległych funkcjonariuszy oraz pracowników.\nOrganem nadzorczym w rozumieniu art. 66 rozporządzenia 2018/1240, zgodnie z właściwością będzie Prezes Urzędu Ochrony Danych Osobowych, któremu został przypisany zakres czynności wykonywanych podczas tego nadzoru, zgodnie z art. 37 projektu ustawy.\nW odniesieniu do danych osobowych przetwarzanych poprzez KSI ETIAS projekt przewiduje, że zastosowanie będą miały ogólne przepisy obowiązujące w tym zakresie z odrębnościami wynikającymi z rozporządzenia 2018/1240. Co do zasady zastosowanie będzie mieć rozporządzenie Parlamentu Europejskiego i Rady (UE) 2016/679 z dnia 27 kwietnia 2016 r. w sprawie ochrony osób fizycznych w związku z przetwarzaniem danych osobowych i w sprawie swobodnego przepływu takich danych oraz uchylenia dyrektywy 95/46/WE (zwane dalej ,,RODO”) oraz ustawa z dnia 10 maja 2018 r. o ochronie danych osobowych. Natomiast w przypadku przetwarzania danych osobowych w celu zwalczania przestępczości co do zasady będzie stosowana ustawa z dnia 14 grudnia 2018 r. o ochronie danych osobowych przetwarzanych w związku z zapobieganiem i zwalczaniem przestępczości.\nW myśl tych przepisów za właściwe postępowanie w przypadku wystąpienia naruszenia przepisów o ochronie danych osobowych odpowiada administrator, u którego naruszenie nastąpiło. W przypadku incydentów bezpieczeństwa (które nie muszą być naruszeniami przepisów prawa, a mogą prowadzić do  zakłóceń pracy systemu centralnego lub w inny sposób wpływać na KSI ETIAS), konieczne jest informowanie o takich zdarzeniach i zagrożeniach oraz wymagana jest współpraca administratora danych u którego nastąpiło naruszenie \fz Komendantem Głównym Straży Granicznej.\nSzczególne wymagania, wynikające z art. 64 rozporządzenia 2018/1240, to 30-dniowy termin na rozpatrzenie wniosku, wymóg informowania wnioskodawców na piśmie o podjęciu czynności mających na celu rozpatrzenie złożonego wniosku, a w przypadku odmowy uwzględnienia wniosku, wymogi w zakresie uzasadnienia rozstrzygnięcia organu oraz pouczenia o przysługujących środkach zaskarżenia. Organem uprawnionym do rozpatrywania przedmiotowych wniosków będzie Komendant Główny Straży Granicznej. Rozporządzenie 2018/1240 przewiduje również obowiązek prowadzenia określonego rejestru, który ma być udostępniany Prezesowi UODO w sposób elektroniczny.\nPrzepisy art. 64 ust. 3 i 4 rozporządzenia 2018/1240 posługują się wprawdzie pojęciem decyzji administracyjnej na określenie rozstrzygnięcia organu rozpatrującego wniosek obywatela państwa trzeciego, jednak w ocenie projektodawcy nie można uznać, że prawodawca unijny przyjmując rozporządzenie miał na myśli odwołania do konkretnych przepisów proceduralnych poszczególnych państw członkowskich, tj. w przypadku Polski do przepisów Kodeksu postępowania administracyjnego. W ocenie projektodawcy prawodawca unijny poprzez posłużenie się sformułowaniem decyzji administracyjnej miał na celu zapewnienie odpowiednich gwarancji podczas rozpatrywania wniosków obywateli państw trzecich dotyczących ich uprawnień w zakresie ich danych osobowych przetwarzanych przez ETIAS, tj. rozpatrzenie wniosku w określonym terminie przez właściwy organ oraz zawarcie określonych informacji, które otrzymywać mają wnioskodawcy. W ocenie projektodawcy projektowana ustawa gwarantuje uwzględnienie wszystkich tych wymogów. Przysługujące obywatelom państw trzecich środki zaskarżenia określone są w RODO oraz ustawie o ochronie danych osobowych (skarga do Prezesa Urzędu do Spraw Ochrony Danych Osobowych lub sądu powszechnego). \nWnioski, o których mowa w art. 64 rozporządzenia 2018/1240, będzie można złożyć za pośrednictwem ogólnodostępnej strony internetowej lub aplikacji na urządzenia mobilne, o których mowa w art. 16 rozporządzenia 2018/1240. Jednocześnie wniosek taki będzie można złożyć również w przypadku niedostępności ogólnodostępnej strony internetowej lub aplikacji na urządzenia mobilne, za pomocą narzędzia teleinformatycznego Straży Granicznej (wskazanie dodatkowego sposobu możliwości złożenia takiego wniosku w celu zagwarantowania realizacji praw związanych z rozporządzeniem Parlamentu Europejskiego i Rady (UE) 2016/679 z dnia 27 kwietnia 2016 r. w sprawie ochrony osób fizycznych w związku z przetwarzaniem danych osobowych i w sprawie swobodnego przepływu takich danych oraz uchylenia dyrektywy 95/46/WE (ogólne rozporządzenie o ochronie danych) (Dz. Urz. UE L 119 z 4.05.2016, str. 1). Powyższe ma na celu przyjęcie jednolitego wymogu składania takich wniosków oraz właściwą identyfikację wnioskujących cudzoziemców. \fW przypadku małoletnich, wniosek będzie mogła złożyć osoba sprawująca władzę rodzicielską lub opiekun prawny. Złożenie wniosku za pośrednictwem narzędzia teleinformatycznego Straży Granicznej będzie możliwe wyłącznie w języku polskim, po dokonaniu wcześniejszego uwierzytelnienia na podstawie danych zawartych w pliku wniosku. \nZ przepisu art. 64 ust. 2 rozporządzenia 2018/1240 bezpośrednio wynika prawo wskazujące, że każdy wnioskodawca ma prawo skontaktować się z jednostką centralną ETIAS lub jednostką krajową ETIAS odpowiedzialną za jego wniosek. Jednostka, która otrzymuje wniosek, musi go zbadać i udzielić odpowiedzi w jak najkrótszym terminie, nieprzekraczającym 30 dni. Prawo to dotyczy dostępu do danych osobowych, ich sprostowania, uzupełnienia, usunięcia oraz do ograniczenia przetwarzania.\nW odniesieniu do decyzji, o której mowa w art. 64 ust. 3 rozporządzenia 2018/1240, cudzoziemcowi będzie przysługiwało prawo wniesienia skargi do Prezesa Urzędu Ochrony Danych Osobowych lub sądu powszechnego.\n\n9. Zmiany w innych ustawach \nArt. 39 projektu wprowadza zmiany w ustawie z dnia 12 października 1990 r. o Straży Granicznej. Pierwsza zmiana dotyczy utworzenia Krajowego Rejestru Cudzoziemców, który jest uregulowany w dodawanym art. 2c ustawy o Straży Granicznej (art. 39 pkt 1). Na szczeblu krajowym KSI ETIAS będzie ściśle skorelowany z Krajowym Rejestrem Cudzoziemców, zwanym dalej „KRC”, a Komendant Główny Straży Granicznej na kolejnych etapach będzie odpowiedzialny za rozwój uruchamianego systemu. KRC będzie narzędziem teleinformatycznym funkcjonującym w obszarze systemowym Straży Granicznej, jako baza danych cudzoziemców przebywających na terytorium Rzeczypospolitej Polskiej oraz ubiegających się o wjazd przez granice zewnętrzne Unii Europejskiej. Przedmiotowy system będzie importował informacje i dane dotyczące cudzoziemców z krajowych systemów źródłowych, funkcjonujących w obszarze migracyjnym, zarówno cudzoziemców wjeżdżających, przebywających, jak i wyjeżdzających przez granicę zewnętrzną Unii Europejskiej przez polskie przejścia graniczne zlokalizowane na tej granicy. Ponadto dane cudzoziemców, którzy w trakcie pobytu na terytorium Rzeczypospolitej Polskiej byli objęci m.in. postępowaniami karnymi i wyrokami sądowymi, postępowaniami administracyjnymi i innymi czynnościami kontrolnymi, a także przebywali nielegalnie, ubiegali się o ochronę międzynarodową lub inne formy legalizacji pobytu i zatrudnienia, jak również pozostawali w zainteresowaniu, m.in. Straży Granicznej, w kontekście stwarzania ryzyka nielegalnej migracji, ryzyka bezpieczeństwa lub ryzyka dla zdrowia publicznego.\nKRC będzie narzędziem teleinformatycznym wspierającym system ETIAS na gruncie krajowym w zakresie dokonywanej weryfikacji danych cudzoziemca w krajowych systemach \fi bazach danych, tym samym KRC będzie wspomagał pracę jednostki krajowej ETIAS poprzez interoperacyjność krajowych baz danych – jako zdolność do pełnej współpracy z innymi systemami migracyjnymi i przetwarzającymi informacje o cudzoziemcach. \nW przypadku otrzymania przez Komendanta Głównego Straży Granicznej wniosku o wydanie zezwolenia na podróż, który wymagał będzie ręcznego przetwarzania, jednostka krajowa ETIAS, przy wykorzystaniu systemu KRC, będzie w stanie sprawnie uzyskać podstawowe informacje na temat danego cudzoziemca i bez zbędnej zwłoki przekazać opinię na temat wniosku oraz ocenić ryzyko nielegalnej imigracji, ryzyko bezpieczeństwa lub ryzyko dla zdrowia publicznego. Wykorzystanie KRC będzie pozwalało w sposób zautomatyzowany z wykorzystaniem jednego punktu dostępowego zainicjować szybkie i równoczesne odpytanie kilku lub kilkunastu systemów źródłowych, zarówno zarządzanych przez Straż Graniczną, jak i inne organy (np. Policja, Służba Więzienna, Szef Urzędu do Spraw Cudzoziemców), celem uzyskania wyczerpujących i aktualnych danych oraz informacji dotyczących m.in. statusu pobytowego danego cudzoziemca na terytorium Rzeczypospolitej Polskiej. Mając na uwadze ograniczenia czasowe nałożone na jednostki krajowe ETIAS w kontekście ręcznego procedowania wniosków o zezwolenie na podróż (96 godzin), wykorzystanie KRC w tym zakresie będzie kluczowe i niezbędne celem zagwarantowania sprawnej realizacji zadań jednostki krajowej ETIAS przez Straż Graniczną na gruncie krajowym. \nJednocześnie wskazać należy, że przedmiotowe narzędzie teleinformatyczne będzie dostępne również dla innych organów administracji publicznej i podmiotów w celu wykonywania zadań związanych z obsługą cudzoziemców. Projektowane rozwiązanie techniczne umożliwi docelowo szybki, sprawny, wydajny, systematyczny i kontrolowany dostęp organów do informacji o cudzoziemcach. \nW projektowanym art. 2c ust. 1 ustawy o Straży Granicznej określono w jakim celu tworzy się KRC. Zgodnie z tym przepisem stworzenie rozwiązania integrującego, zawierającego informacje o cudzoziemcach wynika z konieczności realizacji celów państwa, związanych z prowadzeniem skutecznej polityki migracyjnej, zapewnienia organom dostępu do informacji o cudzoziemcach przebywających na terytorium RP w sposób prosty i jednolity, czy też przeciwdziałania nadużyciom w zakresie korzystania z pomocy \nCelem utworzenia i prowadzenia KRC jest skuteczne identyfikowanie i weryfikowanie danych cudzoziemców za pomocą zaawansowanych algorytmów porównywania danych, zapewnianie organom administracji publicznej weryfikacji poprawności jakości danych cudzoziemców, zagwarantowanie organom wyspecjalizowanego narzędzia teleinformatycznego wykorzystywanego w zakresie zapewnienia ochrony bezpieczeństwa i porządku publicznego w Rzeczypospolitej Polskiej, przeciwdziałania nielegalnej migracji, w tym monitorowania zjawisk migracyjnych, rozpoznawania zagrożeń migracyjnych oraz \fprzeciwdziałania nadużyciom w zakresie korzystania przez cudzoziemców z pomocy państwa, w tym pomocy społecznej, realizacji obowiązków wynikających z udziału Rzeczypospolitej Polskiej w wielkoskalowych systemach informacyjnych Unii Europejskiej w celu zapewnienia wysokiego poziomu bezpieczeństwa w ramach unijnej przestrzeni wolności, bezpieczeństwa i sprawiedliwości, realizacji czynności administracyjnych wobec cudzoziemców przez organy administracji publicznej i inne podmioty realizujące zadania publiczne w zakresie, w jakim jest to konieczne do wykonywania nałożonych na nie zadań określonych w ustawie.\nKRC to narzędzie teleinformatyczne integrujące dane z systemów źródłowych organów administracji publicznej oraz innych podmiotów wykonujących zadania publiczne, które będzie stanowiło pojedynczy punkt dostępu do pełnej informacji o cudzoziemcach. Gromadzone dane będą dotyczyć każdej osoby nieposiadającej obywatelstwa polskiego.\nInformacje o relacjach między cudzoziemcem a organami administracji publicznej, w szczególności o wjeździe, pobycie i zatrudnieniu cudzoziemców na terytorium RP, są gromadzone w wielu rozproszonych zbiorach administracji publicznej. Skutkuje to wielokrotnym rejestrowaniem danych, zwłaszcza danych osobowych, dotyczących tego samego cudzoziemca w ramach pojedynczego zbioru, co utrudnia jego jednoznaczną identyfikację. Proces wyszukiwania danych dotyczących cudzoziemca jest obecnie niejednolity oraz nieusystematyzowany. Otrzymanie pełnej informacji o danym cudzoziemcu wymaga wykonania kwerend w bazie danych każdej instytucji oddzielnie, przy jednoczesnym braku pewności, co do ich wzajemnej zgodności. W przypadku braku możliwości dokonania sprawdzenia drogą elektroniczną, w cały proces angażowane są zasoby osobowe poszczególnych podmiotów. Powyższe może prowadzić również do generowania niespójnych raportów statystycznych dotyczących tej samej materii, a pochodzących z systemów źródłowych różnych organów.\nW art. 2c ust. 2 określono, że KRC jest prowadzony w systemie teleinformatycznym w rozumieniu ustawy z dnia 17 lutego 2005 r. o informatyzacji działalności podmiotów realizujących zadania publiczne, natomiast w ust. 3 projektowanego artykułu określono źródła zasilania, czyli pochodzenia danych w narzędziu integrującym. KRC będzie zasilany w drodze teletransmisji danych przez systemy źródłowe prowadzone przez wymienione organy i podmioty, na podstawie wskazanych odrębnych ustaw, co umożliwi uzyskanie informacji o cudzoziemcu, jednoznaczną weryfikację i identyfikację cudzoziemca. Z uwagi na zmieniający się zakres danych przetwarzanych w systemach źródłowych każdego z organów zasilających KRC, szczegółowy zakres lub typ zdarzeń zostanie uregulowany na podstawie porozumień dwustronnych pomiędzy Komendantem Głównym Straży Granicznej a organami zaangażowanymi w proces zasilania KRC. Zakres zdarzeń o cudzoziemcach będzie określony na podstawie celów w jakim tworzony i prowadzony jest KRC wskazanych w art. 2c ust. 1. \fW KRC będą gromadzone niezbędne dane osobowe cudzoziemca wraz z odwołaniem do poszczególnych systemów źródłowych oraz dane niezbędne do wykonania zdefiniowanych zapytań identyfikujących dane i informacje o cudzoziemcach. \nPowyższe rozwiązanie pozwoli na wyeliminowanie zjawiska polegającego na nieuprawnionym korzystaniu przez cudzoziemców z wielu tożsamości, które niejednokrotnie zostały zidentyfikowane jako nadużycia, m.in. na gruncie prawa administracyjnego (postępowania powrotowe i określone w decyzjach zakazy wjazdu), karnego (oszustwa, w tym wyłudzenia kredytów), jak i skarbowego (drenowanie systemu fiskalnego państwa przez nieuprawnione korzystanie z pomocy państwa).\nW kolejnych przepisach ust. 4 i 5 projektowanego artykułu 2c określono, że cudzoziemcowi jest nadawany w KRC unikalny Główny Identyfikator Cudzoziemca, zwany dalej „GIC”, przy wsparciu algorytmów porównywania danych alfanumerycznych. Każdy cudzoziemiec zidentyfikowany za pomocą zaawansowanych algorytmów porównywania danych alfanumerycznych otrzyma unikalny identyfikator – GIC. Pozwoli to uprościć proces wyszukiwania, ograniczy liczbę powielanych informacji oraz wymiernie podniesie ich jakość. W procesie scalania GIC mogą być wykorzystywane następujące dane: imię (imiona), nazwisko (nazwiska), data urodzenia, płeć, obywatelstwa, rodzaj dokumentu, seria i numer dokumentu, kraj wydania dokumentu, numer ewidencyjny Powszechnego Elektronicznego Systemu Ewidencji Ludności (PESEL), o ile został nadany,  inne krajowe lub zagraniczne numery identyfikacyjne, identyfikatory osoby w systemie źródłowym, identyfikator zdarzenia z systemu źródłowego. GIC to unikatowy numer porządkowy służący do jednoznacznej identyfikacji cudzoziemca. Numer jest jednorazowy i nie zostanie nadany ponownie. GIC jest nadawany z urzędu, a jego nadanie stanowi czynność techniczną.\nDocelowo identyfikacja cudzoziemca będzie mogła odbywać się z wykorzystaniem identyfikatorów biometrycznych, które są optymalnym sposobem ustalania tożsamości. \nPowyższe rozwiązania są również odpowiedzią na politykę unijną w obszarze migracji oraz progresywne podejście do wypełniania wymogów określonych w rozporządzeniach unijnych dotyczących wielkoskalowych systemów informacyjnych Unii Europejskiej, a także rozporządzenia dotyczące ram interoperacyjności tych systemów wielkoskalowych. Interoperacyjność przewiduje bowiem identyfikację osoby za pomocą cech biometrycznych.\nW art. 2c ust. 6 określono dane i informacje przetwarzane w KRC. Katalog danych pozwoli dokonać weryfikacji tożsamości cudzoziemca oraz chronologicznej historii migracyjnej cudzoziemca na terytorium Rzeczypospolitej Polskiej na podstawie danych z dostępnych systemów źródłowych. Szczegółowe informacje dotyczące zdarzeń dostępne \fbędą dla organów i służb już w ramach systemów źródłowych, zgodnie z posiadanym na podstawie odrębnych przepisów, zakresem dostępu. Celem KRC jest zatem zasygnalizowanie zdarzeń i incydentów związanych z wjazdem i pobytem cudzoziemca w Polsce, w celu zobrazowania pełnej sytuacji dotyczącej cudzoziemca, a także wyeliminowanie potencjalnych naruszeń z ich strony.\nKolejny przepis nakłada na organy lub podmioty, których systemy zasilają KRC w dane i informacje, obowiązek informowania o każdej zmianie dotyczącej zakresu informacji i danych przetwarzanych w systemie źródłowym, a także innych zasad i sposobu prowadzenia systemu źródłowego, mających wpływ na zasilanie KRC. Ma to na celu właściwą harmonizację i interoperacyjność przepływu danych pomiędzy systemami źródłowymi a KRC, np. ze względu na różny format zapisu danych w tych systemach, a także ich możliwy rozwój i przebudowę. \nOkreślając podmioty, którym będą mogły być udostępnione dane i informacje dotyczące cudzoziemców przetwarzane w KRC, uwzględniono zakres niezbędny do realizacji ich ustawowych zadań. Dostęp ten jednak nie będzie dotyczył danych, o których mowa w ust. 6 pkt 12, 14, 15 i 19–21 (narodowość, odciski linii papilarnych, wizerunek twarzy, identyfikatory cudzoziemca w systemie źródłowym, identyfikator systemu źródłowego oraz informacje o zdarzeniach dotyczących cudzoziemca). Zgodnie z ustępem 9, dostęp ten zarezerwowany będzie tylko dla organów i podmiotów, które posiadają na podstawie odrębnych przepisów, uprawnienia do dostępu do tych kategorii danych lub informacji przetwarzanych w danym systemie źródłowym. Warunkiem do uzyskania ww. dostępu będzie spełnienie łącznie wymogów wymienionych w art. 2c ust. 10, tj. organy i inne podmioty posiadają urządzenia umożliwiające odnotowanie w ich systemie teleinformatycznym kto, kiedy, w jakim celu oraz jakie dane uzyskał oraz posiadają zabezpieczenia techniczne i organizacyjne uniemożliwiające wykorzystanie danych niezgodnie z celem ich uzyskania. Niniejsze musi zostać uzgodnione z Komendantem Głównym Straży Granicznej, w drodze pisemnego porozumienia.\nKolejne przepisy odnoszą się do zasad przetwarzania danych. Wskazano, że dane KRC będą mogły być przechowywane przez okres ich przechowywania w systemach źródłowych, określony w odrębnych przepisach dotyczących tych systemów. Po upływie tego okresu, nastąpi ich automatyczne usunięcie z KRC.\nW art. 2c ust. 12 wskazano administratora danych przetwarzanych w KRC, o których mowa w ust. 6 projektowanego artykułu. Będzie nim Komendant Główny Straży Granicznej. Jest to uzasadnione zarówno z technicznego, jak i praktycznego punktu widzenia. Komendant Główny Straży Granicznej tworzy, prowadzi, rozwija i utrzymuje KRC. W konsekwencji powyższego, w ust. 13 projektowanego artykułu, wskazano Komendanta Głównego Straży Granicznej jako podmiot zapewniający właściwą eksploatację techniczną i bezpieczeństwo \ffunkcjonowania KRC oraz ochronę danych przetwarzanych w KRC. W związku z powyższym, w art. 2c ust. 14 wskazuje się, że to Komendant Główny Straży Granicznej stosuje środki techniczne i organizacyjne w celu skutecznej ochrony danych osobowych, odpowiednie do zagrożeń oraz do kategorii danych objętych ochroną. Środki te w szczególności zapewniają, aby dane osobowe nie były udostępnione nieupoważnionym osobom fizycznym lub innym nieupoważnionym podmiotom.\nW art. 2c ust. 15 określono procedury zapewniające weryfikację poprawności danych cudzoziemców. Zgodnie z tym przepisem, w przypadku gdy Komendant Główny Straży Granicznej, inny organ administracji publicznej lub inny podmiot realizujący zadania publiczne posiada informacje, że dane przetwarzane w systemie źródłowym są niezgodne z prawdą lub są nieaktualne, informuje o tym w drodze teletransmisji organ lub inny podmiot, który prowadzi system źródłowym. Właściwy organ lub podmiot, który prowadzi system źródłowy, dokonuje weryfikacji danych i w przypadku potwierdzenia, że dane są niezgodne z prawdą lub nieaktualne, dokonuje odpowiednich zmian danych przetwarzanych w systemie źródłowym, zawiadamiając o tym organ lub podmiot, który przekazał informacje.\nW art. 2c ust. 16 wskazano, że minister właściwy do spraw wewnętrznych uczestniczy w realizacji zadań związanych z rozwojem i utrzymaniem KRC przez Komendanta Głównego Straży Granicznej. Ze względu na zasięg i oddziaływanie systemu, konieczność integracji prawnej oraz technicznej wielu systemów źródłowych oraz właściwość wskazanych organów w tym zakresie, organy te uczestniczyć będą w realizacji zadań związanych z rozwojem i utrzymaniem KRC, w celu zapewnienia właściwej architektury teleinformatycznej związanej z celami projektowanego systemu. \nW projekcie wprowadzono (w ust. 17) delegację ustawową do wydania rozporządzenia przez ministra właściwego do spraw wewnętrznych określającego warunki techniczne umożliwiające integrację systemów źródłowych z KRC, w celu jego zasilania w zakresie danych i informacji przetwarzanych w tych systemach, mając na względzie zapewnienie bezpieczeństwa i ochrony danych.\nKolejna zmiana ustawy z dnia 12 października 1990 r. o  Straży Granicznej ma na celu rozszerzenie zakresu działania Komendanta Głównego Straży Granicznej o pełnienie funkcji jednostki krajowej ETIAS, gdyż zgodnie z prawem krajowym, będzie on organem właściwym w tym zakresie (art. 39 pkt 2).\nArt. 40 projektu wprowadza zmianę w ustawie z dnia 24 maja 2000 r. o Krajowym Rejestrze Karnym, polegającą na modyfikacji w art. 6 w ust. 1 pkt 7, poprzez dodanie na końcu tego przepisu wyrazów „lub przepisach prawa Unii Europejskiej”. Wskazane ma na celu doprecyzowanie, gdyż obecnie źródłem zadań nałożonych na organy są zarówno ustawy, jak i bezpośrednio stosowane przepisy prawne Unii Europejskiej. W przypadku dotyczącym \fjednostki krajowej ETIAS, jej zadania, w szczególności w zakresie rozpatrywania wniosku o wydanie zezwolenia na podróż, są określone w rozporządzeniu 2018/1240, natomiast projektowana ustawa o udziale RP w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) wskazuje organ krajowy – Komendanta Głównego Straży Granicznej – który będzie pełnił funkcję tej jednostki. Dodatkowo projektowana ustawa precyzuje uprawnienia Komendanta Głównego Straży Granicznej służące właściwej realizacji jego zdań jako jednostki krajowej ETIAS, w tym prawo dokonania sprawdzeń w innych systemach (np. art. 9 ust. 4 i 5, art. 10). Ponadto art. 19 ust. 1aa ustawy o KRK wprowadza możliwość złożenia zapytania w formie żądania po uprzednim sprawdzeniu osoby w systemie ECRIS-TCN.\nArt. 41 projektu wprowadza zmiany w ustawie z dnia 13 czerwca 2003 r. o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej, Nałożono obowiązek informacyjny na Szefa Urzędu do Spraw Cudzoziemców dotyczący wydania dokumentu podróży cudzoziemcowi, który zgodnie z art. 2 ust. 2 rozporządzenia 2018/1240 nie podlega stosowaniu rozporządzenia w zakresie obowiązku posiadania zezwolenia na podróż. Niniejszy obowiązek odnosi się do przepisu art. 55 ust. 5 lit. a rozporządzenia 2018/1240, zgodnie z którym jeżeli obywatel państwa trzeciego uzyskał dokument podróży, jednostka krajowa ETIAS w stosownych przypadkach niezwłocznie usuwa plik wniosku obywatela państwa trzeciego z systemu centralnego ETIAS. Ponadto w celu ujednolicenia właściwości sądów rejonowych orzekających w sprawach detencji administracyjnej cudzoziemców w art. 88b ust. 1 wskazano, że sąd rejonowy właściwy ze względu na siedzibę wnioskującego organu Straży Granicznej, będzie wydawał takie postanowienie. Zmiany celem ujednolicenia brzmienia wprowadzane są również w ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach oraz w ustawie z dnia 14 lipca 2006 r. o wjeździe na terytorium Rzeczypospolitej Polskiej, pobycie oraz wyjeździe z tego terytorium obywateli państw członkowskich Unii Europejskiej i członków ich rodzin. \nArt. 42 projektu wprowadza zmiany w ustawie z dnia z 14 lipca 2006 r. o wjeździe na terytorium Rzeczypospolitej Polskiej, pobycie oraz wyjeździe z tego terytorium obywateli państw członkowskich Unii Europejskiej i członków ich rodzin poprzez nałożenie obowiązku informacyjnego na wojewodę o wydaniu karty pobytu albo karty stałego pobytu cudzoziemcowi, do którego zgodnie z art. 2 ust. 2 rozporządzenia 2018/1240 nie stosuje się tego rozporządzenia. Niniejszy obowiązek odnosi się do przepisu art. 55 ust. 5 lit. c rozporządzenia 2018/1240, zgodnie z którym jeżeli obywatel państwa trzeciego uzyskał kartę pobytową lub dokument pobytowy (kartę pobytu albo kartę stałego pobytu), jednostka krajowa ETIAS niezwłocznie usuwa plik wniosku obywatela państwa trzeciego z systemu centralnego ETIAS. Ponadto wskazano, że postanowienie o umieszczeniu cudzoziemca w strzeżonym \fośrodku dla cudzoziemców wydaje na wniosek organu Straży Granicznej sąd rejonowy właściwy ze względu na siedzibę wnioskującego organu Straży Granicznej.\nW art. 43 dotyczącym zmian w ustawie z dnia 16 listopada 2006 r. o opłacie skarbowej, proponuje się w załączniku do ustawy w części I opłatą skarbową objąć nową czynność urzędową polegającą na przyjęciu i rozpatrzeniu wniosku o cofnięcie zakazu ponownego wjazdu na terytorium Rzeczypospolitej Polskiej lub na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen – wprowadzenie nowego przedmiotu opłaty skarbowej w wysokości 350 zł wpłynie na wzrost dochodów budżetów gmin. Obecna wysokość opłaty skarbowej podlega przepisom ogólnym i wynosi 10 zł – pkt 53 załącznika do ww. ustawy, tj. „decyzja inna, niż wymieniona w niniejszym załączniku, do której mają zastosowanie przepisy Kodeksu postępowania administracyjnego”. Wskazana kwota nie jest adekwatna do charakteru czynności związanych z wcześniejszym cofnięciem zakazu ponownego wjazdu na terytorium RP i innych państw obszaru Schengen. Orzeczenie zakresu tego zakazu (okres oraz obszar) następuje w ramach wydanej cudzoziemcowi decyzji o zobowiązaniu do powrotu w związku z naruszeniem przepisów migracyjnych. Ze względu na charakter postępowania o cofnięcie zakazu wjazdu, jego tryb wnioskowy w celu zniesienia sankcji administracyjnej oraz możliwość skorzystania z przywileju jakim jest wcześniejsze cofnięcie tego zakazu, opłata skarbowa powinna być adekwatna do zakresu i rodzaju czynności prowadzonych na wniosek cudzoziemca. Opłata pobierana będzie za przyjęcie każdego wniosku o cofnięcie zakazu ponownego wjazdu i jego rozpatrzenie (niezależnie od sposobu jego rozstrzygnięcia przez organ tj. w formie decyzji lub innego aktu).\nOrzeczony w decyzji o zobowiązaniu do powrotu zakaz ponownego wjazdu jest uzasadnioną konsekwencją naruszenia przepisów prawa obowiązującego w Polsce i na podstawie okoliczności sprawy powinien odnieść wymierny skutek prewencyjno-wychowawczy. Zatem cofnięcie zakazu ponownego wjazdu jest dla cudzoziemca szczególnym uprawnieniem w celu zniesienia sankcji administracyjnej, dzięki któremu będzie uprawniony do ponownego ubiegania się o wjazd i pobyt na terytorium RP i innych państw obszaru Schengen. Wprowadzenie opłaty od przyjęcia i rozpatrzenia wniosku o cofnięcie zakazu ponownego wjazdu przyczyni się do zwiększenia efektywności postępowania administracyjnego, ograniczenia nadużyć polegających na instrumentalnym składaniu wniosków oraz racjonalizacji kosztów ponoszonych przez administrację publiczną. Proponowana wysokość opłaty skarbowej jest formą ekwiwalentu za czynności podejmowane w sprawie indywidulanej cudzoziemca i ma na celu: pokrycie kosztów administracyjnych za czynności urzędowe (opłata realizuje zasadę, że osoba która korzysta z określonych czynności administracyjnych powinna również partycypować w ich kosztach); ograniczenie nadmiernej liczby wniosków, które nie zawierają uzasadnienia, informacji lub dokumentów i mogłyby \fprzeciążyć system administracyjny (zdyscyplinowanie wnioskodawców przez skłonienie do większej staranności przy składaniu wniosku przez co skraca się czas na oczekiwanie na wydanie rozstrzygnięcia przez innych cudzoziemców); utrzymanie porządku prawnego i wyrównanie obciążeń podatkowych pełniąc funkcję redystrybucyjną, obciążając opłatą cudzoziemców dokonujących czynności wymagających na ich wniosek interwencji organów administracji. Jednocześnie leży to w interesie społecznym, gdyż opłata ta ma na celu znalezienie równowagi między powszechnym dostępem do środków dochodzenia praw przez cudzoziemca a potrzebą efektywnego zarządzenia zasobami publicznymi oraz wpływami do budżetu organów podatkowych. Pomoże to również organizować obieg spraw oraz pracę organu. Jednocześnie wprowadzenie opłaty skarbowej w wysokości 350 zł zachęca wnioskodawców (cudzoziemców) do staranniejszego zapoznania się z uzasadnieniem decyzji i podjęcia czynności, których niewykonanie miało wpływ na wydanie uprzedniej decyzji o zobowiązaniu do powrotu oraz powstrzymanie się w przyszłości od dokonywania dalszych naruszeń przepisów imigracyjnych.\nKolejna zmiana w art. 43 dotyczącym ustawy z dnia 16 listopada 2006 r. o opłacie skarbowej (pkt 2) jest konsekwencją zmiany rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 810/2009 z dnia 13 lipca 2009 r. ustanawiającego Wspólnotowy Kodeks Wizowy (kodeks wizowy) ((Dz. Urz. UE L 243 z 15.09.2009, str. 1, z późn. zm.)  w zakresie przepisu art. 16 ust. 1–2a, która została dokonana z dniem 11 czerwca 2024 r.,  na mocy rozporządzenia delegowanego Komisji (UE) 2024/1415 z dnia 14 marca 2024 r. zmieniającego rozporządzenie (WE) nr 810/2009 w zakresie wysokości opłat wizowych (Dz. Urz. UE L 1415 z 22.05.2024). Wynika ona z konieczności  dostosowania krajowego porządku prawnego celem zapewnienia spójności z prawodawstwem unijnym, poprzez dokonanie zmiany w części III w ust. 6 i 6a załącznika do ustawy o opłacie skarbowej. Polega ona na  odpowiedniej zmianie wysokości opłat za wizy, stosownie do aktualnej wysokości ustalonej w art. 16 ust. 1–2a rozporządzenia nr 810/2009. Zmiana wysokości opłaty skarbowej będzie dotyczyć wiz wydawanych przez komendanta placówki Straży Granicznej dla dziecka w wieku od 6 do 12 lat – na równowartość 45 euro (obecnie 40 euro, w pozostałych przypadkach na równowartość 90 euro (obecnie 80 euro) oraz w przypadku wydania przez Radę decyzji wykonawczej na podstawie art. 25a ust. 5 lit. b rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 810/2009, tj. na równowartość 135 lub 180 euro (obecnie 120 lub 160 euro).\nArt. 44 projektu wprowadza zmiany w ustawie z dnia 24 sierpnia 2007 r. o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym dotyczące bezpośredniego dostępu do KSI SIS i VIS dla Straży Granicznej (Komendanta Głównego Straży Granicznej pełniącego rolę jednostki krajowej ETIAS jako organu właściwego w sprawach dotyczących zezwoleń na podróż) w związku \fz rozpatrywaniem (w tym prowadzeniem konsultacji z innymi jednostkami krajowymi ETIAS państw członkowskich) wniosku o wydanie zezwolenia na podróż, jego unieważnieniem albo cofnięciem, zgodnie z art. 8 ust. 2 lit. a, d, e albo g rozporządzenia 2018/1240. \nKolejny przepis art. 45 dotyczy zmian w ustawie z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, mających na celu umożliwienie udostępniania Straży Granicznej danych zgromadzonych w rejestrze chorób zakaźnych dotyczących cudzoziemców, którzy ze względu na narażanie, zakażanie lub chorobę zakaźną oraz związane z nimi okoliczności stwarzają wysokie ryzyko epidemiczne. Do celów ETIAS oraz prowadzonej kontroli granicznej w zakresie oceny zdrowia publicznego, utworzony zostanie Wspólny Punkt Kontaktowy w sprawach konsultacji krajowych, który tworzą Główny Inspektor Sanitarny, państwowi wojewódzcy inspektorzy sanitarni oraz państwowi graniczni inspektorzy sanitarni, celem przedstawiania opinii w zakresie zagrożenia dla zdrowia publicznego, w tym wysokiego ryzyka epidemicznego, o którym mowa w przepisach odrębnych dotyczących udziału Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) oraz opinii na potrzeby kontroli granicznej.\nArt. 46 wprowadza zmiany w ustawie z dnia 2 kwietnia 2009 r. o obywatelstwie polskim przez nałożenie obowiązku informacyjnego na wojewodę lub ministra właściwego do spraw wewnętrznych, każdego w zakresie swojej właściwości, o nabyciu lub potwierdzeniu posiadania obywatelstwa polskiego przez cudzoziemca, który zgodnie z art. 2 ust. 2 rozporządzenia 2018/1240 nie podlega temu rozporządzeniu. Obowiązek ten odnosi się do przepisu art. 55 ust. 5 lit. b rozporządzenia 2018/1240, zgodnie z którym jeżeli obywatel państwa trzeciego uzyskał obywatelstwo państwa członkowskiego, jednostka krajowa ETIAS niezwłocznie usuwa plik wniosku obywatela państwa trzeciego z systemu centralnego ETIAS.\nW art. 47 projektu wprowadza się zmiany w ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach poprzez dodanie nowej przesłanki do wydania decyzji o odmowie wjazdu (zmiana w art. 28 w ust. 1). Projekt wprowadza również nową przesłankę do wydania decyzji o zobowiązaniu cudzoziemca do powrotu (art. 302 ust. 1). Będzie można wydać taką decyzję wobec cudzoziemca, który przebywa lub przebywał na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, jeżeli jest lub było ono wymagane zgodnie z rozporządzeniem 2018/1240. Przesłanka ta jest uzasadniona z uwagi na fakt, iż od orzeczenia cudzoziemcowi zakazu wjazdu do wpisania cudzoziemca do wykazu cudzoziemców, których pobyt jest niepożądany, na podstawie art. 435 ust. 1 pkt 1 ustawy o cudzoziemcach, odbywa się niekiedy dopiero po upływie czasu od przekazania Szefowi Urzędu do Spraw Cudzoziemców informacji o rozstrzygnięciu, co jest spowodowane względami technicznymi.\nObecna sytuacja stwarza lukę polegającą na tym, że cudzoziemiec, któremu orzeczono zakaz wjazdu, do czasu wpisu jego danych do wykazu może przebywać na terytorium państw \fczłonkowskich, co stoi w sprzeczności z ideą zakazu wjazdu, jak również z celem art. 11 ust. 1 dyrektywy Parlamentu Europejskiego i Rady 2008/115/WE z dnia 16 grudnia 2008 r. w sprawie wspólnych norm i procedur stosowanych przez państwa członkowskie w odniesieniu do powrotów nielegalnie przebywających obywateli państw trzecich.\nAnalogicznie, w powyższej sytuacji cudzoziemiec nie powinien mieć możliwości wjazdu na terytorium państw członkowskich podczas odprawy granicznej, co znajduje odzwierciedlenie w proponowanej treści art. 28 ust. 1 pkt 7a ustawy o cudzoziemcach.\nPonadto ustawa wprowadza zmiany przez dodanie art. 79c i nałożenie obowiązku informacyjnego na organ, który wydał wizę Schengen lub wizę krajową cudzoziemcowi, który, zgodnie z art. 2 ust. 2 rozporządzenia, nie podlega rozporządzeniu 2018/1240. Niniejszy obowiązek odnosi się do przepisu art. 55 ust. 6 rozporządzenia 2018/1240, zgodnie z którym jeżeli obywatel państwa trzeciego uzyskał wizę jednolitą lub krajową wizę długoterminową, na wniosek cudzoziemca, jednostka krajowa ETIAS niezwłocznie usuwa plik wniosku obywatela państwa trzeciego z systemu centralnego ETIAS. \nW art. 85 w ust. 1 po wyrazach „Rzeczypospolitej Polskiej” dodaje się wyrazy „na podstawie tej wizy” – ma to na celu wyeliminowanie wątpliwości związanych z okresem, w którym cudzoziemiec jest uprawniony do złożenia wniosku o przedłużenie wizy. Tym samym przedłużenie wizy będzie możliwe, jeżeli wniosek zostanie złożony podczas legalnego pobytu (zgodnego z wszystkimi warunkami) cudzoziemca na terytorium Rzeczypospolitej Polskiej na podstawie tej wizy, która ma być przedłużona. \nW art. 99 dodano kolejną przesłankę odmowy wszczęcia postępowania w sprawie udzielenia zezwolenia na pobyt czasowy – gdy w dniu złożenia wniosku o udzielenie tego zezwolenia cudzoziemiec przebywa na terytorium RP w ramach ruchu bezwizowego oraz na podstawie zezwolenia na podróż o ograniczonej ważności terytorialnej, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240. Ze względu na to, że wobec cudzoziemca stwierdzono istnienie przesłanek faktycznych, by uznać, że obecność danej osoby na terytorium państw członkowskich stwarza lub stworzy ryzyko dla bezpieczeństwa, ryzyko nielegalnej imigracji lub wysokie ryzyko epidemiczne, czyli ograniczono ważność terytorialną zezwolenia na podróż zgodnie z art. 44 rozporządzenia 2018/1240, projekt ustawy wyklucza możliwość skutecznego ubiegania się o udzielenie zezwolenia na pobyt czasowy takiemu cudzoziemcowi. Tym samym, złożenie wniosku podczas przebywania cudzoziemca na terytorium Rzeczypospolitej Polskiej w ramach ruchu bezwizowego i posiadanie zezwolenia na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, prowadzić będzie do odmowy wszczęcia postępowania administracyjnego.\nW art. 100 ust. 1 ustanowiono koleją przesłankę do odmowy wydania decyzji o udzieleniu zezwolenia na pobyt czasowy, gdy wniosek o udzielenie zezwolenia na pobyt \fczasowy został złożony podczas pobytu na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli było ono wymagane zgodnie z tym rozporządzeniem, lub przebywa na tym terytorium bez tego zezwolenia, jeżeli jest ono wymagane. Jednocześnie wymóg posiadania takiego zezwolenia na podróż został wskazany w art. 105 ust. 1. Tym samym posiadanie ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240 będzie wymogiem, który będzie uprawniał cudzoziemca do podjęcia dalszych kroków legalizacyjnych na terytorium RP. Wymóg posiadania zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240 wskazano również w zmienianych art. 139f, art. 139l, art. 139s, art. 139t, art. 196, art. 202 ust. 1, art. 206 ust. 1, art. 213 ust. 1 czy też ustanowiono wyjątki od wymogu jego posiadania w art. 165 ust. 3, art. 187 pkt 6 i 7. \nW przepisach tych przyjęto założenie, że pojęcie legalnego lub nielegalnego pobytu cudzoziemca, występujące w ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach, będzie w dalszym ciągu odnosiło się do wymogu posiadania podstawy legalnego pobytu cudzoziemca na terytorium Polski np. w postaci wizy, zezwolenia pobytowego lub legalnego pobytu wynikającego z przepisów prawa. Wymóg posiadania zezwolenia na podróż dla obywateli krajów trzecich, o którym mowa w rozporządzeniu 2018/1240, będzie stanowił dodatkowy warunek wjazdu i pobytu tych obywateli, wjeżdżających lub przebywających na terytorium Polski w ramach ruchu bezwizowego, wynikający z prawa UE.\nW art. 196 ust. 1 dodano kolejną przesłankę odmowy wszczęcia postępowania w sprawie udzielenia zezwolenia na pobyt stały – gdy w dniu złożenia wniosku o udzielenie tego zezwolenia cudzoziemiec przebywał na terytorium RP na podstawie zezwolenia na podróż z art. 44 ust. 1 rozporządzenia 2018/1240 lub bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli było ono wymagane zgodnie z tym rozporządzeniem. Jednocześnie wymóg posiadania takiego zezwolenia na podróż w dniu złożenia wniosku o pobyt stały został wskazany w art. 202 ust. 1.\nPonadto w art. 213 dodano kolejną przesłankę odmowy wszczęcia postępowania w sprawie udzielenia zezwolenia na pobyt rezydenta długoterminowego UE – gdy w dniu złożenia wniosku o udzielenie tego zezwolenia cudzoziemiec przebywał na terytorium RP na podstawie zezwolenia na podróż, o którym mowa w art. 44 ust. 1 (art. 213 ust. 1) oraz bez ważnego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240, jeżeli jest ono wymagane zgodnie z tym rozporządzeniem.\nRozszerzenie przesłanek odmowy wszczęcia postępowania w sprawie udzielenia zezwolenia na pobyt stały oraz udzielenia zezwolenia na pobyt rezydenta długoterminowego UE ma na celu zapobieżenie nadużyciom ze strony cudzoziemców nieposiadających wymaganego zezwolenia na podróż, o którym mowa w art. 36 ust. 1 rozporządzenia 2018/1240 \flub przebywających w szczególnych okolicznościach na terytorium RP na podstawie zezwolenia na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240. \nProjektowany art. 248b wskazuje, że w przypadku, o którym mowa w art. 55 ust. 6 rozporządzenia 2018/1240, organ, który wydał lub wymienił kartę pobytu, przekazuje niezwłocznie, na wniosek cudzoziemca, Komendantowi Głównemu Straży Granicznej, informacje o wydaniu lub wymianie karty pobytu cudzoziemcowi posiadającemu ważne zezwolenie na podróż, o którym mowa w art. 36 ust. 1 lub art. 44 ust. 1 rozporządzenia 2018/1240. Jednostka krajowa ETIAS niezwłocznie usuwa plik wniosku obywatela państwa trzeciego z systemu centralnego ETIAS.\nW projektowanym art. 299 ust. 2a wskazano, że cudzoziemiec jest obowiązany opuścić terytorium Rzeczypospolitej Polskiej przed upływem okresu pobytu objętego wizą Schengen, wizą krajową lub zezwoleniem na podróż, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240 oraz przed upływem okresu ważności tej wizy lub zezwolenia. Tym samym dodano zezwolenie na podróż jak nowy warunek wjazdu i pobytu, wymagany w przypadku cudzoziemców objętych zakresem art. 2 ust. 1 rozporządzenia 2018/1240. Posiadanie ważnego zezwolenia na podróż stanowi warunek pobytu, który musi być spełniony przez cały okres pobytu krótkoterminowego na terytorium państw członkowskich. Samo złożenie, a następnie oczekiwanie na rozpatrzenie przedmiotowego wniosku o wydanie zezwolenia na podróż, nie jest realizacją obowiązku (warunku koniecznego) posiadania ważnego zezwolenia na podróż. Złożenie takiego wniosku powinno odbyć się z odpowiednim wyprzedzeniem przed planowaną podróżą lub, jeśli obywatel państwa trzeciego znajduje się na terytorium państw członkowskich, przed utratą ważności posiadanego przez niego już zezwolenia na podróż. Jednocześnie posiadacz zezwolenia na podróż może złożyć wniosek o wydanie nowego zezwolenia na podróż 120 dni przed utratą ważności posiadanego zezwolenia na podróż. Tym samym, celem zapewnienia ciągłości pobytu zgodnego z warunkami rozporządzenia 2018/1240 (posiadanie ważnego zezwolenia na podróż) oraz ze względu na wyprzedzającą możliwość ponownego ubiegania się o wydanie zezwolenia na podróż przed utratą ważności poprzedniego, złożenie samego wniosku o wydanie tego zezwolenia nie prowadzi do spełnienia warunków wjazdu i pobytu na terytorium państw członkowskich. Dopiero wydane zezwolenie na podróż potwierdza, że obywatel państwa trzeciego zwolniony z obowiązku wizowego kwalifikuje się do odbycia podróży lub dalszego pobytu w strefie Schengen, oraz że taka podróż lub dalszy pobyt nie stwarza ryzyka dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemicznego. Brak uzyskania kolejnego zezwolenia na podróż (w tym o ograniczonej ważności terytorialnej na terytorium Rzeczypospolitej Polskiej) będzie skutkował obowiązkiem opuszczenia przez cudzoziemca terytorium Rzeczypospolitej Polskiej przed upływem okresu pobytu objętego tym zezwoleniem. Obowiązek ten, zgodnie z dodawanym \fw art. 299 ust. 8b nie będzie dotyczył sytuacji, gdy cudzoziemiec posiada ważny dokument uprawniający go do pobytu na terytorium Rzeczypospolitej Polskiej lub gdy z przedmiotowej ustawy lub z innych ustaw wynika, że jego pobyt na tym terytorium uważa się za legalny. Ponadto w art. 299 w ust. 7 wskazano, że aby pobyt został uznany za legalny w trakcie czasu na opuszczenie terytorium Rzeczypospolitej Polskiej (30 dni), wniosek legalizacyjny nie może zostać złożony po upływie ważności zezwolenia na podróż, jeżeli było ono wymagane zgodnie z rozporządzeniem 2018/1240. Art. 299 w ust. 8 wskazuje na zakres wyłączeń z obowiązku opuszczenia terytorium Rzeczypospolitej Polskiej w terminie 30 dni, w sytuacji, gdy pobyt cudzoziemca na tym terytorium uważa się za legalny oraz posiada ważne zezwolenie na podróż. Kolejny ust. 8b doprecyzowuje zakres wyłączeń w odniesieniu do przepisów ust. 2a, których nie stosuje się, jeżeli cudzoziemiec posiada ważny dokument uprawniający go do pobytu na terytorium Rzeczypospolitej Polskiej lub z ustawy, z innych ustaw lub aktów prawa Unii Europejskiej wynika, że jego pobyt na tym terytorium uważa się za legalny.\nProjektowane nowe brzmienie art. 299 ust. 9 pkt 2 polega na dodaniu w jego treści odniesienia do decyzji o uznaniu wniosku o udzielenie ochrony międzynarodowej za niedopuszczalny. W dotychczasowej praktyce prowadziło to do wątpliwości interpretacyjnych w związku z brakiem wskazania przedmiotowej decyzji w katalogu wyłączeń.\nW art. 300 uszczegółowiono kwestie złożenia wniosku o przedłużenie okresu pobytu w ramach ruchu bezwizowego na terytorium Rzeczypospolitej Polskiej poprzez wskazanie, że musi zostać dokonane nie później niż w ostatnim dniu ważności zezwolenia na podróż, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240. Ponadto dodano ust. 2a, który stanowi, że cudzoziemcowi odmawia się przedłużenia okresu pobytu w ramach ruchu bezwizowego na terytorium Rzeczypospolitej Polskiej, jeżeli w dniu złożenia wniosku przebywał na tym terytorium bez ważnego zezwolenia na podróż, jeżeli było ono wymagane zgodnie z rozporządzeniem 2018/1240, lub przebywa na tym terytorium bez tego zezwolenia, jeżeli jest wymagane. Tym samym cudzoziemiec jest obowiązany do posiadania zezwolenia na podróż w dniu złożenia wniosku o przedłużenie okresu pobytu w ramach ruchu bezwizowego, jak i w trakcie całego postępowania administracyjnego niezależnie od treści rozstrzygnięcia (decyzji pozytywnej lub negatywnej dla cudzoziemca). Wskazać należy, że każdy pobyt w ramach ruchu bezwizowego powinien uwzględniać konieczność spełniania warunku jakim jest posiadanie ważnego zezwolenia na podróż.\n\tProjektowana regulacja przewiduje również zmiany w zakresie przesłanek do wydania decyzji o zobowiązaniu cudzoziemca do powrotu, przez dodanie w art. 302 ust. 1 nowego pkt 1a dotyczącego sytuacji, gdy cudzoziemiec przebywa lub przebywał na terytorium Rzeczypospolitej Polskiej bez ważnego zezwolenia na podróż, jeżeli jest lub było ono wymagane zgodnie z rozporządzeniem 2018/1240. Brak ważnego zezwolenia na podróż będzie \fkolejną odrębną przesłanką umożliwiającą wydanie cudzoziemcowi decyzji powrotowej. Jednocześnie rozporządzenie 2018/1240 wskazuje, że ważne zezwolenie na podróż jest warunkiem pobytu, który musi być spełniony przez cały okres pobytu krótkoterminowego na terytorium państw członkowskich, dlatego w projekcie ustawy jest odniesienie do czasu teraźniejszego oraz przeszłego, związanego z przedmiotem dodawanej regulacji. Ponadto dodaje się przesłankę wydania decyzji o zobowiązaniu cudzoziemca do powrotu (pkt 7a) dotyczącą obowiązywania zakazu ponownego wjazdu cudzoziemca na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen albo zakazu ponownego wjazdu tylko na terytorium Rzeczypospolitej Polskiej.\n\tProjektowane nowe brzmienie art. 314 ust. 1 wskazuje, że organ właściwy do wydania decyzji o zobowiązaniu cudzoziemca do powrotu, w przypadkach, o których mowa w art. 302 ust. 1 pkt 1–8 i 10–16 przedmiotowej ustawy, poucza cudzoziemca posiadającego zezwolenie na podróż, o którym mowa w art. 44 ust. 1 rozporządzenia 2018/1240, które nie uprawnia do wjazdu i pobytu na terytorium Rzeczypospolitej Polskiej, o obowiązku niezwłocznego wyjazdu na terytorium tego państwa lub państw członkowskich, do których posiadacz zezwolenia na podróż w trakcie jego ważności ma prawo się udać. \nJednocześnie zmiany w art. 428 ust. 1 pkt 6 oraz art. 430 ust. 8 ustawy o cudzoziemcach, odnoszą się do prowadzonych w zakresie wyżej wymienionych pouczeń rejestrów.\n\tZmiana brzmienia art. 320 ust. 1 polega na doprecyzowaniu przesłanek, celem wyeliminowania wątpliwości dotyczących cofnięcia zakazu ponownego wjazdu orzeczonego w decyzji o zobowiązaniu cudzoziemca do powrotu. Organ, który w pierwszej instancji wydał decyzję o zobowiązaniu cudzoziemca do powrotu, może cofnąć zakaz, o którym mowa w art. 318, na wniosek cudzoziemca, w drodze decyzji, jeżeli cudzoziemiec wykaże, że wykonał obowiązki wynikające z decyzji o zobowiązaniu cudzoziemca do powrotu, chyba że jego ponowny wjazd na terytorium Rzeczypospolitej Polskiej lub innych państw obszaru Schengen ma nastąpić ze względu na uzasadnione okoliczności, zwłaszcza ze względów humanitarnych.\nPostępowania o cofnięcie zakazu ponownego wjazdu dotyczą skrócenia obowiązywania sankcji administracyjnej jaką jest nałożenie na cudzoziemca zakazu ponownego wjazdu na terytorium RP i innych państw obszaru Schengen. Orzeczenie zakresu tego zakazu (okres oraz obszar) następuje w ramach wydanej cudzoziemcowi decyzji o zobowiązaniu do powrotu. Wykonanie takiej decyzji prowadzi do tego, iż cudzoziemiec nie zamieszkuje na terytorium RP – należy uznać, że jest „osobą zamieszkałą za granicą”. \nW chwili obecnej, brak wniesienia opłaty skarbowej (10 zł) przez wnioskującego cudzoziemca (zamieszkałego za granicą) o cofnięcie zakazu ponownego wjazdu, prowadzi i tak do konieczności załatwienia sprawy przez organy Straży Granicznej i rozpatrzenie podania. \fJednocześnie prowadzi to do konieczności podjęcia dalszych kroków tj. zgodnie z art. 265 Kpa – egzekucji administracyjnej kosztów i opłat (co w chwili obecnej ze względu na niski koszt wniesienia podania, tj. 10 zł jest nierentowne dla organów podatkowych). \nWprowadzenie wskazanego rozwiązania przez dodanie ust. 4 w art. 320 będzie zatem obligowało cudzoziemca do wniesienia opłaty skarbowej W przypadku gdy taka opłata skarbowa nie zostanie wniesiona z chwilą wniesienia podania oraz na wezwanie organu nie zostanie wniesiona w wyznaczonym terminie, podanie będzie podlegało zwrotowi lub czynność uzależniona od opłaty zostanie zaniechana (z wyjątkiem przypadków kodeksowych, tj. art. 261 par. 4 pkt 1–2 Kpa jeżeli za niezwłocznym załatwieniem przemawiają względy społeczne lub wzgląd na ważny interes strony oraz jeżeli wniesienie podania stanowi czynność, dla której jest ustanowiony termin zawity).\nCofnięcie zakazu ponownego wjazdu jest dla cudzoziemca pozytywnym uprawnieniem w celu zniesienia sankcji administracyjnej, dzięki któremu będzie uprawniony do ponownego ubiegania się o wjazd i pobyt na terytorium RP i innych państw obszaru Schengen. Cofnięcie zakazu wjazdu niezależenie od sytuacji powinno podlegać opłacie skarbowej. Tym samym obowiązek wniesienia opłaty skarbowej z wydanie decyzji za przyjęcie i rozpatrzenie wniosku o cofnięcie zakazu ponownego wjazdu na terytorium Rzeczypospolitej Polskiej i innych państw obszaru Schengen, będzie obowiązywał bez względu na miejsce zamieszkania osoby wnoszącej o cofnięcie zakazu ponownego wjazdu. \nJednocześnie obecne rozwiązania systemów płatniczych pozwalają na bezproblemowe wniesienie takiej opłaty przez osoby zamieszkujące (przebywające) za granicą przez wskazanie przez właściwy organ podatkowy danych do międzynarodowego przelewu bankowego na jego numer rachunku bankowego.\n\tDodawany w art. 321 ustawy o cudzoziemcach ust. 3 i ust. 4, stanowić będzie lex specialis względem art. 35 § 3 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego. Przepis określa, że załatwienie sprawy w postępowaniu odwoławczym, jako szczególnie skomplikowanej ze względu na charakter postępowania dowodowego i jego złożoność, powinno nastąpić nie później niż w ciągu sześciu miesięcy od dnia otrzymania odwołania. Jeżeli to odwołanie nie spełnia wymogów przewidzianych przepisami prawa, wskazany termin biegnie od dnia uzupełnienia braków. Ewentualne dalsze prowadzenie sprawy i wyznaczenie nowego terminu jej załatwienia po upływie terminu sześciu miesięcy będzie podlegać przepisom ogólnym ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego. Termin ten będzie miał zastosowanie w postępowaniach odwoławczych w sprawach o zobowiązanie cudzoziemca do powrotu, przedłużenie terminu dobrowolnego wyjazdu oraz cofnięcie zakazu ponownego wjazdu, w trybach określonych w ustawie z dnia 14 czerwca 1960 r. Kodeks postępowania administracyjnego dotyczących wymienionych \fspraw. Ponadto obowiązek, o którym mowa w art. 54 § 2 ustawy z dnia 30 sierpnia 2002 r. – Prawo o postępowaniu przed sądami administracyjnymi, właściwy organ będzie realizował w terminie 90 dni od dnia otrzymania skargi. Zważywszy na stopień złożoności spraw o zobowiązanie cudzoziemca do powrotu oraz przewidzianą w ustawie o cudzoziemcach konstrukcję tego procesu, zawierającego faktycznie kilka rozstrzygnięć w jednej decyzji, tj. nakaz opuszczenia kraju, rozstrzygnięcie co do terminu dobrowolnego wyjazdu oraz co do zakazu wjazdu do Polski i innych państw obszaru Schengen, co do zgody na pobyt ze względów humanitarnych, jak również odnośnie zgody na pobyt tolerowany w Rzeczypospolitej Polskiej, należy wskazać, iż do postępowania w tym przedmiocie nie powinny mieć zastosowania przepisy Kodeksu postępowania administracyjnego w zakresie terminów załatwienia sprawy.  Z uwagi na złożoność postępowania podyktowaną rozmaitymi, nieraz niejednoznacznymi stanami faktycznymi oraz wysoki stopień skomplikowania tych postępowań, zasadne jest ustanowienie przepisów szczególnych dotyczących terminów załatwienia sprawy administracyjnej w tym przedmiocie. \nKomendant Główny Straży Granicznej w powyższych sprawach, jako że rozstrzyga sprawę całkowicie na nowo zgodnie z zasadą dwuinstancyjności postępowania, to mając na względzie liczbę postępowań oraz opisany już stopień zawiłości i wielowątkowości orzeczeń zapadających w jednej decyzji, organ wyższego stopnia powinien mieć zapewniony adekwatny czas pozwalający na rzetelne i kompleksowe rozpoznanie sprawy, zapewniające realny dostęp stronie do skutecznego środka odwoławczego.\n\tW zakresie zmian w art. 334, Straż Graniczna w swej praktyce służbowej na kanwie udzielania pomocy w dobrowolnym powrocie zidentyfikowała potrzebę objęcia pomocą w dobrowolnym powrocie cudzoziemców, na wniosek których następuje umorzenie postępowania w sprawie dotyczącej legalizacji pobytu (tj. o zezwolenie na pobyt czasowy, stały lub rezydenta długoterminowego UE) toczącego się przed wojewodą lub Szefem Urzędu do Spraw Cudzoziemców. W takiej sytuacji zgodnie z art. 299 ust. 6 lit. a ustawy o cudzoziemcach, osoby te mają obowiązek opuszczenia terytorium Polski przed upływem 30 dni od dnia, gdy decyzja w przedmiocie umorzenia postępowania stała się ostateczna, a w przypadku wydania decyzji przez organ wyższego stopnia – od dnia, w którym decyzja została cudzoziemcowi doręczona – gdyż po tym okresie ich pobyt będzie uznany za nielegalny, w rozumieniu art. 302 ust. 1 ustawy o cudzoziemcach. \nCudzoziemcy objęci tym obowiązkiem niejednokrotnie występują do Komendanta Głównego Straży Granicznej z wnioskiem o udzielenie pomocy w dobrowolnym powrocie, jednakże w obecnym stanie prawnym brak jest przesłanki umożliwiającej udzielenie tym osobom pomocy. W związku z tym proponuje się dodanie nowej przesłanki udzielenia przez Komendanta Głównego Straży Granicznej pomocy w dobrowolnym powrocie w przypadku, \fgdy postępowanie o zezwolenie na pobyt czasowy, zezwolenie na pobyt stały lub zezwolenie na pobyt rezydenta długoterminowego UE zostało umorzone na wniosek cudzoziemca. W takiej sytuacji cudzoziemiec będzie mógł wystąpić z wnioskiem co najmniej na 7 dni przed upływem terminu, o którym mowa w art. 299 ust. 6 pkt 1 lit. a ustawy o cudzoziemcach, aby zapewnić Komendantowi Głównemu Straży Granicznej niezbędny czas na rozpatrzenie wniosku.\nZmieniany art. 397 ust. 1 pkt 2 i art. 401 ust. 2 określa, że Straż Graniczna będzie uprawniona do wystąpienia do sądu właściwego ze względu na siedzibę wnioskującego organu Straży Granicznej z wnioskiem o umieszczenie cudzoziemca w placówce opiekuńczo-wychowawczej lub w strzeżonym ośrodku. Obecna regulacja wskazuje na konieczność złożenia takiego wniosku do sądu właściwego ze względu na miejsce zatrzymania małoletniego, co ze względu na zasięg terytorialny jednostek organizacyjnych Straży Granicznej i umiejscowienie ich siedzib na terenie służbowej odpowiedzialności obejmującej kilka lub kilkanaście powiatów, negatywnie wpływa na czas realizowanych czynności względem tak szczególnej grupy cudzoziemców jaką stanowią małoletni bez opieki.\nNowelizowane artykuły 459 i 462 odnoszą się do obowiązków przewoźników, którzy drogą powietrzną, morską lub lądową zamierzają przywieźć cudzoziemców do granicy. Przewoźnicy będą zobligowani do podjęcia wszelkich niezbędnych środków, aby zapewnić, że cudzoziemiec zamierzający wjechać na terytorium Rzeczypospolitej Polskiej ma ważne zezwolenie na podróż, jeżeli jest ono wymagane zgodnie z rozporządzeniem 2018/1240. W przypadku, gdy wymóg ten nie zostanie spełniony przez przewoźnika, komendant placówki Straży Granicznej, który odmówił cudzoziemcowi z tego powodu wjazdu na terytorium Rzeczypospolitej Polskiej, będzie uprawniony do nałożenia kary administracyjnej na przewoźnika. Jednocześnie projektowana ustawa zawiera wyłączenie w zakresie nakładania kar administracyjnych na przewoźników w przypadku, gdy przewoźnik z powodu braku technicznej możliwości spowodowanej awarią jakiejkolwiek części systemu ETIAS nie będzie mógł dokonać zapytania i uzyskać dostępu do danych dla przewoźników, o którym mowa w art. 45 ust. 1 rozporządzenia 2018/1240. \nArt. 48 wprowadza w ustawie z dnia 25 czerwca 2015 r. Prawo konsularne zadania konsuli w zakresie przeprowadzenia rozmowy z cudzoziemcem w sprawach dotyczących zezwolenia na podróż, sporządzenia i przekazania opinii z tej rozmowy, a jeżeli dokonał zapisu rozmowy, przekazania także jej zapis.\nArt. 49 wprowadza zmiany w ustawie z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej, tj. cudzoziemcy przebywający w ramach ruchu bezwizowego będą zobowiązani do posiadania ważnego zezwolenia na podróż w celu możliwości legalnego wykonywania pracy na terytorium Rzeczypospolitej Polskiej. \fUstawa wprowadza możliwość przetwarzania w rejestrze spraw dotyczących zezwoleń na pracę, spraw dotyczących zezwoleń na pracę sezonową oraz spraw dotyczących oświadczeń o powierzeniu pracy cudzoziemcowi – Głównego Identyfikatora Cudzoziemca, nadawanego i przetwarzanego w Krajowym Rejestrze Cudzoziemców.\nPozyskanie tych danych od organów Straży Granicznej nastąpi w drodze teletransmisji, a jego podstawą będą przepisy dotyczące udostępniania danych z Krajowego Rejestru Cudzoziemców. Zakres pozyskiwanych danych obejmować będzie informacje i dane udostępniane z KRC. Do celów prowadzenia postępowanie w sprawie zezwolenia na pracę lub oświadczenia o powierzeniu pracy cudzoziemcowi, organy prowadzące te postępowania będą zatem wykorzystywały dane i informacje dotyczące cudzoziemca, w tym Główny Identyfikator Cudzoziemca.\nDalsze udostępnianie pozyskanych danych uprawnionym organom i instytucjom, odbędzie się na podstawie przepisów szczególnych regulujących zasady ich dostępu do danych gromadzonych w Krajowym Rejestrze Cudzoziemców. \nArt. 50 wprowadza zmiany w art. 47 ust. 2 i 3 ustawy z dnia 20 marca 2025 r. o rynku pracy i służbach zatrudnienia. Zmiana umożliwi wojewódzkim i powiatowym urzędom pracy przetwarzanie danych osobowych cudzoziemca w postaci Głównego Identyfikatora Cudzoziemca.\nArt. 51 wprowadza zmiany o charakterze redakcyjno-legislacyjnym w ustawie z dnia 15 maja 2026 r. o udziale Rzeczypospolitej Polskiej w systemie Eurodac, mające na celu jedynie doprecyzowanie obowiązujących przepisów.\n\n10. Przepisy przejściowe, dostosowujące i końcowe\nW projektowanym art. 52 ustawy uregulowano wymóg posiadania ważnego zezwolenia na podróż, który stosuje się od daty uruchomienia i rozpoczęcia wykorzystywania systemu ETIAS, zgodnie z art. 88 ust. 5 rozporządzenia 2018/1240, tj. od daty ustalonej przez Komisję Europejską z uwzględnieniem okresu przejściowego – 6 miesięcy, który może być jednokrotnie przedłużony przez Komisję o maksymalnie 6 miesięcy – podczas którego wymóg posiadania ważnego zezwolenia na podróż nie ma zastosowania, oraz okresu karencji – 6 miesięcy – podczas którego służby graniczne wyjątkowo zezwalają cudzoziemcom objętym wymogiem posiadania zezwolenia na podróż na przekroczenie granicy zewnętrznej pomimo braku posiadania tego zezwolenia, jeżeli pozostałe warunki wjazdu są spełnione. \nJednocześnie wskazano, że w okresie przejściowym, o którym mowa w art. 83 ust. 1 rozporządzenia 2018/1240, nie stosuje się przepisów art. 99 ust. 1 pkt 8a, art. 100 ust. 1 pkt 10, art. 105 ust. 1, art. 132, art. 139f ust. 2 pkt 3, art. 139s ust. 1 pkt 5, art. 139t ust. 1, art. 141, art. 147 ust. 1 i 2, art. 154 ust. 1–3, art. 157d ust. 1 i 2, art. 164, art. 165 ust. 1a i 4, art. 178, \fart. 185b, art. 187 pkt 6 i 7, art. 191 ust. 1 pkt 1 i 4, art. 196 ust. 1 pkt 1 lit. aa oraz e, art. 202 ust. 1, art. 213 ust. 1 pkt 1 lit. aa oraz i, art. 299 ust. 2a oraz 7 i 8, art. 300 ust. 2 i 2a, art. 302 ust. 1 pkt 1a, art. 314 ust. 1, art. 459 ust. 1, art. 462 ust. 1, ust. 2a i ust. 3 pkt 3 ustawy zmienianej w art. 46 w brzmieniu nadanym niniejszą ustaw. \nPonadto w okresie karencji, o którym mowa w art. 83 ust. 3 zdanie pierwsze rozporządzenia 2018/1240, cudzoziemcowi będzie się zezwalało na przekroczenie granicy zewnętrznej w przypadku, o którym mowa w art. 83 ust. 3 zdanie trzecie rozporządzenia 2018/1240, i nie będą miały do niego zastosowania przepisy art. 99 ust. 1 pkt 8a, art. 100 ust. 1 pkt 10, art. 105 ust. 1, art. 132, art. 139f ust. 2 pkt 3, art. 139s ust. 1 pkt 5, art. 139t ust. 1, art. 141, art. 147 ust. 1 i 2, art. 154 ust. 1–3, art. 157d ust. 1 i 2, art. 164, art. 165 ust. 1a i 4, art. 178, art. 185b, art. 187 pkt 6 i 7, art. 191 ust. 1 pkt 1 i 4, art. 196 ust. 1 pkt 1 lit. aa oraz e, art. 202 ust. 1, art. 213 ust. 1 pkt 1 lit. aa oraz i, art. 299 ust. 2a oraz 7 i 8, art. 300 ust. 2 i 2a, art. 302 ust. 1 pkt 1a, art. 314 ust. 1, art. 459 ust. 1, art. 462 ust. 1, ust. 2a i ust. 3 pkt 3 ustawy zmienianej w art. 46 w brzmieniu nadanym projektowaną ustawą w okresie jego pobytu na terytorium Rzeczypospolitej Polskiej rozpoczętym bezpośrednio po tym przekroczeniu granicy zewnętrznej. Wskazane rozwiązania mają na celu usystematyzowanie zakresu obowiązywania przepisów wpływających na prawa i obowiązki cudzoziemców w zakresie legalizacji ich pobytu na terytorium Rzeczypospolitej Polskiej.\nKolejny przepis, tj. art. 53 określa obowiązek zapewnienia przez Straż Graniczną i konsulów istotnych informacji dotyczących składania wniosków o zezwolenie na podróż. Kampania informacyjna będzie miała na celu poinformowanie obywateli państw trzecich, objętych zakresem podmiotowym rozporządzenia 2018/1240, o wymogu posiadania przez nich ważnego zezwolenia na podróż, w celu przekroczenia granic zewnętrznych i posiadania takiego zezwolenia przez cały okres pobytu krótkoterminowego na terytorium państw członkowskich oraz m.in. o kryteriach, warunkach i procedurach składania wniosków o zezwolenie na podróż. Okres zapewniania informacji będzie trwał przez 3 lata, a jego początek nastąpi na 6 miesięcy przed datą uruchomienia systemu ETIAS.\nW projekcie uregulowano także zagadnienia o charakterze dostosowującym, zapewniających właściwy przebieg przygotowań po stronie organów krajowych do uruchomienia i wykorzystywania systemu ETIAS poprzez KSI ETIAS. \nW art. 54 wskazano, że Komendant Główny Straży Granicznej (COT KSI ETIAS) prowadzi współpracę w zakresie przeprowadzania kompleksowego testu ETIAS.\nZgodnie z projektowanymi przepisami (art. 55), celem zapewnienia prawidłowości i bezpieczeństwa funkcjonowania systemu i przetwarzanych poprzez ten system danych ETIAS Komendant Główny Straży Granicznej, przed uruchomieniem KSI ETIAS, wystąpi do Prezesa Urzędu Ochrony Danych Osobowych z wnioskiem o przeprowadzenie kontroli w zakresie \fspełniania przez KSI ETIAS wymogów określonych w przepisach o ochronie danych osobowych. Określone zostały również uprawnienia Prezesa Urzędu Ochrony Danych Osobowych, zastępcy Prezesa Urzędu lub upoważnionych przez niego pracowników w zakresie prowadzenia kontroli spełnienia przez KSI ETIAS wymogów określonych w przepisach o ochronie danych osobowych. W projekcie wskazano także podmiot właściwy do wykonywania uprawnień, o których mowa w art. 84 ustawy z dnia 10 maja 2018 r. o ochronie danych osobowych. Prezes Urzędu Ochrony Danych Osobowych wykonując powyższe uprawnienia, przedstawi Komendantowi Głównemu Straży Granicznej pisemną opinię w zakresie spełnienia przez KSI ETIAS wymogów określonych w przepisach o ochronie danych osobowych, a w przypadku stwierdzenia nieprawidłowości w KSI ETIAS przekaże Komendantowi Głównemu Straży Granicznej zalecenia pokontrolne w formie pisemnej.\nProjektowana ustawa określa również sposób postępowania w przypadku przedstawienia przez Prezesa Urzędu Ochrony Danych Osobowych zaleceń pokontrolnych. Zgodnie z projektowanym przepisem Komendant Główny Straży Granicznej ma prawo zgłoszenia na piśmie umotywowanych zastrzeżeń odnośnie przekazanych zaleceń pokontrolnych, w terminie 7 dni od dnia ich otrzymania. W przypadku niezgłoszenia zastrzeżeń, jak również w przypadku nieuwzględnienia zastrzeżeń przez Prezesa Urzędu Ochrony Danych Osobowych, Komendant Główny Straży Granicznej jest obowiązany wykonać zalecenia pokontrolne, a następnie wystąpić z wnioskiem o przeprowadzenie ponownej kontroli.\nKolejne przepisy art. 56 i art. 57 zobowiązują Komendanta Głównego Straży Granicznej do poinformowania, przed uruchomieniem KSI ETIAS, ministra właściwego do spraw wewnętrznych o gotowości do uruchomienia produkcyjnego KSI ETIAS. Minister sprawdza gotowość do prawidłowej eksploatacji KSI ETIAS przez poszczególne organy uprawnione do bezpośredniego dostępu do KSI ETIAS. Do celów efektywnego i skutecznego wykonania tych czynności, ministrowi właściwemu do spraw wewnętrznych przysługują uprawnienia, o których mowa w art. 33 ust. 2 i art. 34 ustawy.\nArtykuły 58–61 zawierają rozwiązania o charakterze dostosowującym, związanym z wdrożeniem Krajowego Rejestru Cudzoziemców. Projekt ustawy regulującej udział Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) przewiduje wdrożenie tego systemu jako jedno z zadań Straży Granicznej (jako koordynatora) określone w ramach przyjętego w dniu 10 marca 2023 r. przez Radę Ministrów Planu dostosowania organów polskiej administracji do współpracy z przebudowanymi wielkoskalowymi systemami informacyjnymi UE „MasterPlan”.\nStraż Graniczna w ramach środków finansowych z budżetu krajowego i środków unijnych z Funduszu Bezpieczeństwa Wewnętrznego w latach 2021–2023 dokonała zakupu \fm.in.: infrastruktury mocy obliczeniowej i sieciowej wraz z niezbędnym oprogramowaniem, subskrypcji oraz urządzeń bezpieczeństwa wraz z komponentami sieciowymi, infrastruktury sprzętowo-programowej na potrzeby wdrożenia, utrzymania oraz funkcjonowania systemu ETIAS, wysokiej jakości sprzętu informatycznego dla zespołu programistów funkcjonującego w ramach Straży Granicznej oraz personelu jednostki krajowej ETIAS, a także sprzętu biurowego dla przedmiotowej jednostki. Sfinansowano ponadto szereg specjalistycznych szkoleń dla funkcjonariuszy SG odpowiadających za wdrożenie wskazanego systemu.\nMając na uwadze przepisy rozporządzenia 2018/1240 i zapisy „MasterPlanu”, podstawowym zadaniem jest dalsza rozbudowa wdrażanego systemu, jak również jego dalsze utrzymanie oraz zarządzanie. W tym celu Straż Graniczna zaplanowała do realizacji w latach 2025–2034 szereg zadań, m.in. rozbudowę oraz utrzymanie wsparcia w zakresie urządzeń bezpieczeństwa sieciowego, systemu mocy obliczeniowej i pamięci masowej, urządzeń telekomunikacyjnych oraz sprzętu i systemu wykorzystywanego w przyszłości do realizacji zadań z zakresu interoperacyjności systemów wielkoskalowych UE.\nKomendant Główny Straży Granicznej zapewni zasilanie, w drodze teletransmisji, Krajowego Rejestru Cudzoziemców z chwilą jego utworzenia, danymi i informacjami przez system teleinformatyczny tj. Centralny System Informatyczny Straży Granicznej (CSI SG). Ponadto w celu zasilania KRC przez systemy źródłowe innych organów, organy te będą zobowiązane do współpracy z Komendantem Głównym Straży Granicznej w zakresie niezbędnym do konfiguracji ich własnych systemów teleinformatycznych z KRC. W tym celu organ lub podmiot zasilający przygotuje prowadzony przez siebie system teleinformatyczny lub systemy teleinformatyczne do integracji z KRC, na podstawie dokumentacji technicznej opracowanej przez Komendanta Głównego Straży Granicznej, a następnie wystąpi do Komendanta Głównego Straży Granicznej o sprawdzenie i potwierdzenie poprawnego podłączenia ich systemu źródłowego do KRC. Jednocześnie Komendant Główny Straży Granicznej opracuje niezbędną dokumentacje techniczną, która doprowadzi do połączenia systemów teleinformatycznych organów administracji publicznej oraz innych podmiotów realizujących zadania publiczne. Konfiguracja systemów źródłowych z Krajowym Rejestrem Cudzoziemców powinna nastąpić w okresie 24 miesięcy od dnia wejścia w życie przepisów dotyczących KRC. Rozpoczęcie zasilania KRC w drodze teletransmisji, danymi i informacjami z systemu źródłowego lub systemów źródłowych jednego lub kilku organów lub podmiotów nastąpi po ogłoszeniu komunikatu przez ministra właściwego do spraw wewnętrznych w Dzienniku Urzędowym Rzeczypospolitej Polskiej „Monitor Polski”, określającego dzień rozpoczęcia zasilania KRC.\nW art. 62-67 zostały zawarte przepisy przejściowe. Art. 62 wskazuje, że opłata skarbowa za przyjęcie i rozpatrzenie wniosku o cofnięcie zakazu ponownego wjazdu \fwprowadzana w ustawie z dnia 16 listopada 2006 r. o opłacie skarbowej będzie stosowana do wniosków składanych od dnia wejścia w życie projektowanej ustawy. Art. 63 dotyczy z kolei sytuacji udostępniania właściwym organom Straży Granicznej danych zgromadzonych w rejestrze chorób zakaźnych do czasu zapewnienia rozwiązań technicznych i organizacyjnych umożliwiających ich udostępnianie w drodze teletransmisji.\nW art. 64–67 określono limit wydatków dla Komendanta Głównego Straży Granicznej, ministra właściwego do spraw wewnętrznych, Szefa Urzędu do Spraw Cudzoziemców i Komendanta Głównego Policji.\nW odniesieniu do źródeł finansowania, o których mowa w pkt 6 Oceny Skutków Regulacji, należy wskazać, że Straż Graniczna pozyskała środki z budżetu Unii Europejskiej na realizację wyszczególnionych potrzeb, m.in. na zakup sprzętu teleinformatycznego dla jednostki krajowej ETIAS. W ramach Planu Dostosowania Organów Polskiej Administracji do Współpracy z przebudowanymi Wielkoskalowymi Systemami Informacyjnymi UE – MasterPlan, zaplanowany został do realizacji, m.in. projekt pn. Wdrożenie systemu ETIAS. Założenia finansowe do omawianego projektu wielkoskalowego, opracowano w oparciu o realizowane na przestrzeni ostatnich lat w ww. obszarze umowy, przeprowadzone analizy rynku, które uwzględniały jednocześnie ryzyko inflacji i ryzyko walutowe (kurs USD oraz EUR). Jednakże należy mieć na uwadze, iż wskazane skutki finansowe są szacunkowe, w związku z tym dokonanie rozbicia tych skutków na poszczególne rodzaje wydatków może nie być wiążące i ulec zmianie w perspektywie wydłużonego okresu wejścia w życie regulacji.\nZ uwagi na fakt, że wejście w życie projektowanej ustawy będzie powodowało skutki finansowe dla sektora finansów publicznych polegające na konieczności zwiększenia limitu wydatków w części 42 – Sprawy wewnętrzne dla środków zaplanowanych na funkcjonowanie Straży Granicznej, koniecznym było zamieszczenie w treści normatywnej projektu stosownego przepisu dotyczącego reguły wydatkowej (tj. maksymalnego limitu tych wydatków wyrażonego kwotowo, na okres 10 lat budżetowych wykonywania ustawy, oddzielnie dla każdego roku). \nW art. 68 wskazano, że ustawa wejdzie w życie z dniem określonym w decyzji Komisji Europejskiej, zgodnie z art. 88 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 z wyjątkiem wskazanych przepisów, które wejdą w życie w innych terminach. Powyższe jest uwarunkowane koniecznością wydania niezbędnych aktów normatywnych na szczeblu Unii Europejskiej, po stwierdzeniu gotowości do uruchomienia określonych w nich narzędzi, a także wynika z potrzeby podjęcia prac o charakterze dostosowawczym służących przygotowaniu RP do \fudziału w systemie ETIAS, w tym wdrożenia Krajowego Rejestru Cudzoziemców. \nW ocenie projektodawcy projekt ustawy jest zgodny z prawem Unii Europejskiej.\nProjektowana ustawa nie ma wpływu na działalność mikroprzedsiębiorców, małych i średnich przedsiębiorców.\nProjekt został udostępniony w Biuletynie Informacji Publicznej na stronie internetowej Rządowego Centrum Legislacji w serwisie Rządowy Proces Legislacyjny, zgodnie z § 52 uchwały nr 190 Rady Ministrów z dnia 29 października 2013 r. – Regulamin pracy Rady Ministrów (M.P. z 2026 r. poz. 404) oraz stosownie do wymogów art. 5 ustawy z dnia 7 lipca 2005 r. o działalności lobbingowej w procesie stanowienia prawa (Dz. U. z 2025 r. poz. 677, \nz późn. zm.). Nie zgłosił się żaden podmiot zainteresowany pracami nad projektem w trybie przepisów o działalności lobbingowej. \nProjektowany akt prawny nie podlega procedurze notyfikacji określonej w przepisach rozporządzenia Rady Ministrów z dnia 23 grudnia 2002 r. w sprawie sposobu funkcjonowania krajowego systemu notyfikacji norm i aktów prawnych (Dz. U. poz. 2039, z późn zm.).\nProjektowany akt prawny nie wymaga przedłożenia właściwym instytucjom i organom UE, w tym Europejskiemu Bankowi Centralnemu, w celu uzyskania opinii, dokonania powiadomienia, konsultacji albo uzgodnienia.\nProjekt nie podlegał dokonaniu oceny OSR przez koordynatora OSR w trybie § 32 uchwały nr 190 Rady Ministrów z dnia 29 października 2013 r. – Regulamin pracy Rady Ministrów.\n\fNazwa projektu Ustawa o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)  Ministerstwo wiodące i ministerstwa współpracujące Ministerstwo Spraw Wewnętrznych i Administracji  Osoba odpowiedzialna za projekt w randze Ministra, Sekretarza Stanu lub Podsekretarza Stanu: Pan Tomasz Szymański – Sekretarz Stanu w Ministerstwie Spraw Wewnętrznych i Administracji, Pełnomocnik Rządu do spraw Wielkoskalowych Systemów Informacyjnych Unii Europejskiej    Kontakt do opiekuna merytorycznego projektu: płk SG Aleksander Ulański – Zastępca Dyrektora Zarządu do Spraw Cudzoziemców Komendy Głównej Straży Granicznej tel. 22 500 4576, e-mail: aleksander.ulanski@strazgraniczna.pl płk SG Mariusz Kijowski – Dyrektor Biura Łączności i Informatyki Komendy Głównej Straży Granicznej tel. 22 500 4010, e-mail: mariusz.kijowski@strazgraniczna.pl\tData sporządzenia: 9 lipca 2026 r.   Źródło:  Prawo UE – rozporządzenie Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiające europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniające rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.)  Numer w wykazie prac legislacyjnych Rady Ministrów: UC104\nOCENA SKUTKÓW REGULACJI\nJaki problem jest rozwiązywany?\nW związku z wejściem w życie rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenie (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226, zwanego dalej „rozporządzeniem 2018/1240”, konieczne jest określenie krajowych ram prawnych służących zapewnieniu jego stosowania. Rozporządzenie 2018/1240 ustanawia europejski system informacji o podróży oraz zezwoleń na podróż, który ma na celu zwiększenie bezpieczeństwa wewnętrznego oraz poprawę skuteczności ochrony granic zewnętrznych Unii Europejskiej przez zagwarantowanie możliwości wyprzedzającej oceny podróżnych (cudzoziemców) pod kątem występowania ryzyka dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemicznego dla państw członkowskich Unii Europejskiej, bezpośrednio przed ich przybyciem na przejście graniczne, zlokalizowane na granicy zewnętrznej Unii Europejskiej. System ETIAS będzie uzupełniał i wspierał cele Systemu Wjazdu/Wyjazdu („Entry/Exit System”, EES) w zakresie obywateli państw trzecich zwolnionych z obowiązku wizowego, jak również Wizowy System Informacyjny (VIS), mający obecnie zastosowanie w stosunku do obywateli państw trzecich, podlegających obowiązkowi wizowemu.  Tym samym, system ETIAS przyczyni się do zwiększenia efektywności działań realizowanych przez organy państw członkowskich Unii Europejskiej w kontekście zapobiegania nielegalnej imigracji, zwiększenia skuteczności odpraw granicznych, a także czynności weryfikacyjnych prowadzonych wobec cudzoziemców. System ETIAS w sposób wymierny przyczyni się do zapobiegania przestępstwom terrorystycznym i innym poważnym przestępstwom, popełnianym przez obywateli państw trzecich na terytorium państw członkowskich Unii Europejskiej.  Rozporządzenie 2018/1240 zakłada, że wszyscy obywatele państw trzecich, którzy na mocy przepisów szczególnych są zwolnieni z obowiązku wizowego, zamierzający wjechać na terytorium państw członkowskich Unii Europejskiej, przed rozpoczęciem swojej podróży, będą musieli złożyć za pośrednictwem systemu ETIAS elektroniczny wniosek o zezwolenie na podróż. Informacje gromadzone przez system umożliwią – przy pełnym poszanowaniu praw podstawowych i zasad ochrony danych osobowych – wcześniejszą weryfikację istnienia potencjalnych zagrożeń dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemicznego wynikających z wjazdu, a następnie pobytu cudzoziemca na terytorium państw członkowskich UE. W razie zidentyfikowania potencjalnego zagrożenia system ETIAS skieruje wniosek do dalszej weryfikacji przez odpowiedzialne państwo członkowskie UE (właściwą Jednostkę Krajową ETIAS) w celu podjęcia decyzji o odmowie wydania bądź wydaniu zezwolenia na podróż, umożliwiającego wjazd i pobyt na terytorium państw członkowskich UE. Tym samym, system ETIAS będzie wspierał działania wpływające na poprawę bezpieczeństwa wewnętrznego, zapobieganie nielegalnej imigracji oraz ochronę zdrowia publicznego przez przeciwdziałanie zagrożeniu epidemicznemu. Wyprzedzająca identyfikacja osób i zagrożeń, jakie mogą one stwarzać, w wymiernym stopniu wpłynie również na zwiększenie przepustowości na przejściach granicznych oraz usprawni procedury odpraw granicznych i czynności rejestracyjne wymagane przez system EES na granicy zewnętrznej.  System ETIAS zostanie uruchomiony z datą określoną w decyzji Komisji Europejskiej wydanej zgodnie z art. 88 ust. 1 rozporządzenia 2018/1240, po spełnieniu warunków wskazanych w tym przepisie. Celem zapewnienia właściwego stosowania rozporządzenia należy określić rozwiązania instytucjonalne i proceduralne na szczeblu krajowym obejmujące, w szczególności, obowiązki i uprawnienia organów w zakresie przetwarzania danych zawartych w ETIAS, właściwy organ, o którym mowa w art. 8 ust. 1 rozporządzenia 2018/1240, realizujący zadania Jednostki Krajowej ETIAS, organ pełniący rolę centralnego punktu dostępu, o którym mowa w art. 50 ust. 2 rozporządzenia 2018/1240, organ odpowiedzialny za wprowadzanie i zarządzanie krajowymi wpisami do listy ostrzegawczej ETIAS, zgodnie z art. 34 ust. 3 i art. 35 ust. 4 rozporządzenia \f2018/1240, organy i służby uprawnione do występowania z wnioskiem o taki wpis, a także właściwy organ w zakresie prowadzenia postępowania odwoławczego, o którym mowa w art. 37 ust. 3 rozporządzenia 2018/1240, oraz sposób i tryb prowadzenia takiego postępowania.\fRekomendowane rozwiązanie, w tym planowane narzędzia interwencji, i oczekiwany efekt\nProjektowana ustawa o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) służy zapewnieniu stosowania na gruncie krajowym rozporządzenia 2018/1240. W projekcie ustawy określono zasady i sposób realizacji udziału Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS), w tym obowiązki i uprawnienia organów dotyczące wprowadzania danych oraz wglądu do danych zawartych w tym systemie poprzez Krajowy System Informatyczny ds. Systemu ETIAS. Projekt reguluje również kwestie sprawowania nadzoru nad prawidłowością działania KSI ETIAS.  W projekcie określono przede wszystkim organ krajowy pełniący funkcję Jednostki Krajowej ETIAS, którym będzie Komendant Główny Straży Granicznej. Komendant Główny Straży Granicznej będzie realizował obowiązki i korzystał z uprawnień Jednostki Krajowej ETIAS w zakresie i na zasadach określonych w rozporządzeniu 2018/1240 oraz innych przepisach dotyczących Jednostki Krajowej ETIAS. Dane przetwarzane w systemie ETIAS będą wykorzystywane na potrzeby realizacji zadań ustawowych, m.in. Straży Granicznej, Policji, wojewodów, Szefa Urzędu do Spraw Cudzoziemców, sądów, prokuratury, Służby Celno-Skarbowej oraz innych określonych służb krajowych. Zakres dostępu do danych ETIAS przysługujący poszczególnym organom i służbom, określony w art. 3 ustawy, uwzględnia rodzaj i charakter zadań realizowanych przez wskazane organy i służby, w szczególności w zakresie kontroli ruchu granicznego (kontroli granicznej), kontroli legalności pobytu cudzoziemców na terytorium Rzeczypospolitej Polskiej, a także do celu podejmowania decyzji w sprawie wniosku o wydanie wizy krótkoterminowej, wizy długoterminowej lub dokumentu pobytowego zgodnie z art. 13 ust. 4b i art. 49a rozporządzenia 2018/1240. Ponadto określono uprawnienia organów krajowych i służb do dostępu do danych dotyczących tożsamości i danych dokumentów podróży przechowywanych we wspólnym repozytorium danych umożliwiających identyfikację do celów określonych w art. 20 i 21 rozporządzenia (UE) 2019/817 zgodnie z art. 13 ust. 4a rozporządzenia 2018/1240. Organy i służby określone w art. 3 będą uprawnione do bezpośredniego dostępu do KSI ETIAS w celu przetwarzania danych ETIAS. W projektowanej ustawie wskazano również podmioty uprawnione do pośredniego dostępu do danych ETIAS, tj. dostępu do danych przez wyznaczone organy i służby krajowe, zgodnie z art. 50 ust. 3 rozporządzenia 2018/1240, upoważnione do przeglądania danych ETIAS w celu zapobiegania przestępstwom terrorystycznym lub innym poważnym przestępstwom, ich wykrywania i prowadzenia w ich sprawie postępowań przygotowawczych. Wskazany dostęp realizuje się, jeżeli jest w danej sprawie niezbędny i proporcjonalny oraz istnieją dowody lub uzasadnione podstawy, aby uznać, że przeglądanie danych przechowywanych w systemie centralnym ETIAS przyczyni się do zapobiegania przedmiotowym przestępstwom, ich wykrywania lub prowadzenia w ich sprawie postępowań przygotowawczych, w szczególności jeżeli zachodzi uzasadnione podejrzenie, że osoba podejrzana o popełnienie przestępstwa terrorystycznego lub innego poważnego przestępstwa, jego sprawca lub ofiara należą do jednej z kategorii cudzoziemców objętych rozporządzeniem. Uprawnienie to będzie przysługiwało prokuraturze, sądom, Policji, Straży Granicznej, Krajowej Administracji Skarbowej, Agencji Bezpieczeństwa Wewnętrznego, Agencji Wywiadu, Centralnemu Biuru Antykorupcyjnemu, Służbie Ochrony Państwa, Służbie Kontrwywiadu Wojskowego, Służbie Wywiadu Wojskowego lub Żandarmerii Wojskowej. Dostęp pośredni będzie realizowany przez pojedynczy centralny punkt dostępu, o którym mowa w art. 50 ust. 2 rozporządzenia 2018/1240, którego rolę będzie pełnił Komendant Główny Straży Granicznej. Projektowana ustawa zobowiązuje organy przetwarzające dane ETIAS do zapewnienia zgodności ich przetwarzania z rozporządzeniem 2018/1240, w tym przyjęcia środków niezbędnych do zapewnienia przestrzegania praw podstawowych i bezpieczeństwa danych. W projekcie określono również podmiot realizujący zadania Centralnego Organu Technicznego KSI ETIAS (COT KSI ETIAS) – zakłada się powierzenie tej funkcji Komendantowi Głównemu Straży Granicznej – oraz wskazano jego zadania, obejmujące techniczne zagadnienia wynikające z udziału Rzeczypospolitej Polskiej w ETIAS. W związku z powyższym uregulowano także obowiązek współpracy określonych organów i służb z COT KSI ETIAS w celu realizacji zadań związanych z udziałem RP w ETIAS, w tym w zakresie przekazywania dokumentów, udzielania informacji oraz przekazywania aktualnych danych niezbędnych do prowadzenia wykazów jednostek organizacyjnych organów uprawnionych do przetwarzania danych ETIAS i wszystkich jednostek operacyjnych mających dostęp do ETIAS, a także zgłaszania ujawnionych nieprawidłowości w związku z przetwarzaniem danych ETIAS przez KSI ETIAS. W projektowanej ustawie w zakresie prowadzenia ręcznego przetwarzania wniosku o wydanie zezwolenia na podróż przez Jednostkę Krajową ETIAS, o którym mowa w art. 26 rozporządzenia 2018/1240, wprowadzono możliwość prowadzenia krajowych konsultacji, celem wszechstronnej analizy wniosku i weryfikacji oraz oceny cudzoziemca, który złożył wniosek o wydanie zezwolenia na podróż. Wskazane konsultacje będą mogły być prowadzone także w przypadku, jeżeli jednostka krajowa ETIAS innego państwa członkowskiego Unii Europejskiej zwróci się, zgodnie z art. 28 rozporządzenia 2018/1240, do Komendanta Głównego Straży Granicznej o opinię w sprawie wniosku o zezwolenie na podróż. Kolejną kwestię, która wymaga uregulowania na poziomie prawa krajowego, stanowi zapewnienie cudzoziemcom, którym odmówiono wydania zezwolenia na podróż, cofnięto albo unieważniono to zezwolenie, prawa do wniesienia odwołania. Zgodnie z rozporządzeniem 2018/1240 postępowanie odwoławcze jest prowadzone w państwie członkowskim UE, którego jednostka krajowa ETIAS podjęła decyzję w sprawie dotyczącej zezwolenia na podróż i zgodnie z prawem krajowym tego państwa. W celu zagwarantowania szybkiej oraz przejrzystej i zrozumiałej procedury dla cudzoziemca, określono możliwość złożenia elektronicznego wniosku o ponowne rozpatrzenie sprawy w ciągu 7 dni od dnia wysłania powiadomienia o wydanej decyzji na adres poczty elektronicznej. Postępowanie to będzie prowadzone z uwzględnieniem rozwiązań i narzędzi wykorzystanych już podczas rozpatrywania pierwotnej sprawy, celem indywidualnej \foceny wnioskodawcy lub osoby objętej wnioskiem pod kątem ryzyka dla bezpieczeństwa, ryzyka nielegalnej imigracji lub wysokiego ryzyka epidemiologicznego. Projektowana ustawa określa procedurę oraz organy uprawnione do wystąpienia o wprowadzenie danych do listy ostrzegawczej ETIAS. Dane przekazywane do listy ostrzegawczej ETIAS będą dotyczyć osób, które są podejrzane o popełnienie przestępstwa terrorystycznego lub innego poważnego przestępstwa, bądź o udział w nich, lub osób, względem których istnieją przesłanki faktyczne lub uzasadnione podstawy, oparte na ogólnej ocenie danej osoby, aby sądzić, że popełnią przestępstwo terrorystyczne lub inne poważne przestępstwo. Komendant Główny Straży Granicznej będzie uprawniony do zarządzania krajowymi wpisami na liście ostrzegawczej ETIAS, a przed wprowadzaniem danych do tej listy, będzie upoważniony do weryfikacji, czy dane są adekwatne, dokładne i wystarczająco ważne, aby zostały wpisane do tej listy oraz czy wprowadzenie tych danych nie będzie prowadziło do nieproporcjonalnie dużej liczby wniosków o wydanie zezwoleń na podróż, które miałyby być przetwarzane ręcznie. Celem zapewnienia na bieżąco prawdziwości tych danych, organy wnioskujące będą odpowiedzialne za terminową weryfikację własnych wpisów nie rzadziej niż raz w roku, skutkującą koniecznością aktualizacji lub usunięcia danych z listy ostrzegawczej ETIAS. Projektowana ustawa zawiera także regulacje odnoszące się do zasad bezpieczeństwa w związku z przetwarzaniem danych ETIAS poprzez Krajowy System Informatyczny do Spraw Systemu ETIAS. Ponadto ustawa dotyczy zagadnień związanych z ochroną danych osobowych, w tym rozpatrywaniem wniosków obywateli państw trzecich o dostęp do danych ETIAS (celem ich sprostowania, uzupełnienia lub usunięcia), nadawaniem i cofaniem uprawnień użytkownikom indywidualnym do dostępu do KSI ETIAS oraz przetwarzaniem danych przez KSI ETIAS. Projektowana ustawa zakłada zmiany w innych aktach normatywnych, tj. ustawie z dnia 12 października 1990 r. o Straży Granicznej, ustawie z dnia 24 maja 2000 r. o Krajowym Rejestrze Karnym, ustawie z dnia 13 czerwca 2003 r. o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej, ustawie z dnia 14 lipca 2006 r. o wjeździe na terytorium Rzeczypospolitej Polskiej, pobycie oraz wyjeździe z tego terytorium obywateli państw członkowskich Unii Europejskiej i członków ich rodzin, ustawie z dnia 16 listopada 2006 r. o opłacie skarbowej, ustawie z dnia 24 sierpnia 2007 r. o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym, ustawie z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, ustawie z dnia 2 kwietnia 2009 r. o obywatelstwie polskim, ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach, w ustawie z dnia 25 czerwca 2015 r. – Prawo konsularne, ustawie z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej, ustawie z dnia 20 marca 2025 r. o rynku pracy i służbach zatrudnienia oraz w ustawie z dnia 15 maja 2026 r. o udziale Rzeczypospolitej Polskiej w systemie Eurodac. W ustawie z dnia 12 października 1990 r. o Straży Granicznej zakłada się dodanie nowych zadań związanych z udziałem Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) oraz Krajowym Rejestrem Cudzoziemców (dalej „KRC”) – w szczególności w celu identyfikowania i weryfikowania danych cudzoziemców za pomocą zaawansowanych algorytmów porównywania danych alfanumerycznych oraz Systemu Porównywania Danych Biometrycznych (Biometric Matching System) i umożliwiania organom administracji publicznej oraz innym podmiotom realizującym zadania publiczne weryfikacji danych cudzoziemców dla zapewnienia właściwej ich jakości oraz poprawności. Zgodnie z projektem Komendant Główny Straży Granicznej tworzy, prowadzi, rozwija i utrzymuje KRC, a w konsekwencji zapewnia właściwą eksploatację techniczną i bezpieczeństwo funkcjonowania KRC oraz ochronę danych przetwarzanych w KRC. Komendant Główny Straży Granicznej będzie administratora danych przetwarzanych w tym rejestrze. KRC będzie zasilany w drodze teletransmisji danych przez systemy źródłowe. W KRC będą gromadzone niezbędne dane osobowe cudzoziemca wraz z odwołaniem do poszczególnych systemów źródłowych, obejmujące w szczególności imię (imiona) i nazwisko (nazwiska) cudzoziemca, imiona lub nazwiska poprzednie, datę urodzenia, płeć, imię (imiona) ojca i matki cudzoziemca, kraj urodzenia, miejsce urodzenia, obywatelstwa, narodowość, odciski linii papilarnych, wizerunek twarzy, numer PESEL, o ile został nadany, a także informacje o wydanych cudzoziemcowi lub posiadanych przez cudzoziemca dokumentach, informacje o wnioskach, postanowieniach, decyzjach, wyrokach sądów, kontrolach, czynnościach w zakresie wydania, odmowy wydania, unieważnienia lub cofnięcia dokumentów oraz o innych rozstrzygnięciach lub czynnościach dotyczących cudzoziemca, przetwarzanych w systemie źródłowym (szczegółowo określone w art. 2c ust. 6 ustawy o Straży Granicznej). Wskazane dane będą mogły być udostępnione, z uwzględnieniem zakresu niezbędnego do realizacji ustawowych zadań, ministrom właściwym do spraw: wewnętrznych, zagranicznych, pracy, spraw rodziny, zabezpieczenia społecznego, szkolnictwa wyższego i nauki oraz Szefowi Urzędu do Spraw Cudzoziemców, Straży Granicznej, Policji, konsulom, wojewodom, Państwowej Inspekcji Pracy, Zakładowi Ubezpieczeń Społecznych, Radzie do Spraw Uchodźców, organom ochrony porządku publicznego i bezpieczeństwa państwa oraz innym organom administracji publicznej realizującym czynności administracyjne z udziałem cudzoziemców. Jednocześnie dostęp do wskazanych kategorii danych (narodowość, odciski linii papilarnych, wizerunek twarzy, identyfikatory cudzoziemca w systemie źródłowym, identyfikator systemu źródłowego oraz informacje o zdarzeniach dotyczących cudzoziemca) będzie zarezerwowany tylko dla organów i podmiotów, które posiadają na podstawie odrębnych przepisów, uprawnienia do dostępu do tych kategorii danych lub informacji przetwarzanych w danym systemie źródłowym. Konieczność utworzenia tego rejestru wynika przede wszystkim z potrzeby uproszczenia procesu wyszukiwania, ograniczenia liczby powielanych danych i informacji oraz podniesienia ich jakość. Informacje o relacjach między cudzoziemcem a organami administracji publicznej, w szczególności o wjeździe, pobycie i zatrudnieniu cudzoziemców na terytorium RP, są gromadzone w wielu rozproszonych zbiorach administracji publicznej. Skutkuje to wielokrotnym rejestrowaniem danych, zwłaszcza danych osobowych, dotyczących tego samego cudzoziemca w ramach pojedynczego zbioru, co utrudnia jego jednoznaczną identyfikację. Proces wyszukiwania danych dotyczących cudzoziemca jest obecnie niejednolity oraz nieusystematyzowany. Otrzymanie pełnej informacji o danym cudzoziemcu wymaga wykonania kwerend w bazie danych każdej instytucji oddzielnie, przy jednoczesnym braku pewności, co do ich wzajemnej zgodności. W przypadku braku możliwości dokonania sprawdzenia drogą elektroniczną, w cały proces \fangażowane są zasoby osobowe poszczególnych podmiotów. Funkcjonowanie wskazanego narzędzia przyczyni się do wyeliminowania zjawiska polegającego na nieuprawnionym korzystaniu przez cudzoziemców z wielu tożsamości, które niejednokrotnie zostały zidentyfikowane jako nadużycia, m.in. na gruncie prawa administracyjnego (postępowania powrotowe i określone w decyzjach zakazy wjazdu), karnego (oszustwa, w tym wyłudzenia kredytów), jak i skarbowego (drenowanie systemu fiskalnego państwa przez nieuprawnione korzystanie z pomocy państwa).  W odniesieniu do zagadnień związanych z udziałem Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS), nowelizowana ustawa z dnia 12 grudnia 2013 r. o cudzoziemcach wprowadza m.in. sankcję administracyjną w postaci możliwości zobowiązania cudzoziemca do powrotu w sytuacji jego pobytu na terytorium RP bez ważnego zezwolenia na podróż.  W pozostałych ustawach planuje się uregulować obowiązki informacyjne organów administracji publicznej posiadających informacje o obywatelach państw trzecich, wobec których wymóg posiadania zezwolenia na podróż nie ma już zastosowania, celem usunięcia pliku wniosku z systemu centralnego ETIAS. Projekt wprowadza przepisy, które wykraczają poza minimalne regulacje wymagane do realizacji obowiązków wynikających z rozporządzenia 2018/1240, dotyczące:  – utworzenia Krajowego Systemu Informatycznego do Spraw Systemu ETIAS (KSI ETIAS), krajowego oprogramowania dla Jednostki Krajowej ETIAS, Centralnego Organu Technicznego Krajowego Systemu Informacyjnego do Spraw Systemu ETIAS (COT KSI ETIAS), określenia warunków technicznych przetwarzania danych ETIAS przez KSI ETIAS oraz zadań KGSG i KGP z tym związanych, – sprawowania nadzoru nad funkcjonowaniem KSI ETIAS przez ministra właściwego do spraw wewnętrznych, – określenia krajowej procedury wymiany informacji i danych w celu zmiany lub usunięcia danych przechowywanych w systemie centralnym ETIAS, w sytuacji gdy są niezgodne z prawdą lub były przetwarzane z naruszeniem przepisów, – wprowadzenia terminu 3 dni na usunięcie danych ETIAS uzyskanych w wyniku pośredniego dostępu, w sytuacji negatywnej weryfikacji ex-post, – uregulowania zakresu i sposobu przeprowadzania konsultacji krajowych w przypadku ręcznego przetwarzania wniosków o wydanie zezwolenia na podróż, w tym w ramach konsultacji z innymi państwami członkowskimi UE, a także trafień na liście ostrzegawczej ETIAS, – przechowywania w krajowym oprogramowaniu dla Jednostki Krajowej ETIAS zapisu rozmowy przeprowadzonej z cudzoziemcem z wykorzystaniem środków komunikacji audiowizualnej na odległość, – sposobu zarządzania wpisami w liście ostrzegawczej ETIAS, a także organy odpowiedzialne za ocenę aktualności oraz prawdziwości danych wprowadzonych do listy ostrzegawczej ETIAS, – krajowego sposobu składania wniosku o prawo do dostępu do danych osobowych, ich sprostowania, uzupełnienia, usunięcia oraz do ograniczenia przetwarzania, a także czynności związanych z wydaniem decyzji negatywnej w tych sprawach, – utworzenia Krajowego Rejestru Cudzoziemców, – przeprowadzenia kontroli  przed uruchomieniem KSI ETIAS przez Prezesa Urzędu Ochrony Danych Osobowych. Powyższe uregulowania mają na celu dookreślenie stosunków między organami administracji publicznej, w tym dodatkowych czynności dla tych organów, zapewniają kompleksowe rozwiązania o charakterze organizacyjnym w zakresie infrastruktury technicznej (łączności), bezpieczeństwa i ochrony przetwarzanych danych, które służą właściwemu stosowaniu rozporządzenia 2018/1240. Nie wpływają one na sytuację cudzoziemców oraz innych podmiotów spoza administracji przez nakładanie kolejnych obowiązków (obciążeń) niż te minimalne, które wynikają z rozporządzenia 2018/1240.\fJak problem został rozwiązany w innych krajach, w szczególności krajach członkowskich OECD/UE? \nPaństwa członkowskie UE oraz państwa stosujące dorobek Schengen znajdują się obecnie na różnych etapach przygotowań mających na celu dostosowanie swoich krajowych porządków prawnych do przepisów rozporządzenia 2018/1240. Wskazane działania są prowadzone z uwzględnieniem obowiązujących w każdym państwie rozwiązań instytucjonalnych oraz proceduralnych. Wskazane państwa podjęły lub prowadzą obecnie ocenę skutków regulacji pod względem budżetu, zasobów ludzkich, organizacji i przepisów krajowych. Potencjalne różnice w treści projektowanych przepisów w innych krajach UE mogą wynikać ze specyfiki organizacji podziału zadań i kompetencji podmiotów, które będą korzystać z systemu ETIAS, jak również indywidualnych zasad związanych z implementacją przepisów UE w prawie krajowym tych państw (m.in. dostępu do danych ETIAS, organów właściwych do realizacji czynności związanych z ETIAS, w zakresie prowadzonego postępowania odwoławczego).  W zakresie pobierania opłaty od wniosku o ponowne rozpatrzenie sprawy dotyczącej zezwolenia na podróż, analogiczne rozwiązania są już stosowane w innych państwach członkowskich UE oraz państwach stosujących dorobek Schengen dotyczących decyzji wydawanych wobec cudzoziemców, a w szczególności w sprawach wizowych, pobytowych oraz powrotu do kraju pochodzenia: Dania Opłatę należy zazwyczaj uiścić, gdy cudzoziemiec odwołuje się od decyzji wydanej przez Agencję ds. Międzynarodowej Rekrutacji i Integracji lub Duńską Służbę Imigracyjną. Opłatę należy również uiścić, jeśli cudzoziemiec zwróci się do Rady Apelacyjnej ds. Imigracji o ponowne otwarcie sprawy, a pierwotna sprawa podlegała opłacie. Niektóre sprawy są zwolnione z opłaty. Opłatę należy uiścić najpóźniej w tym samym czasie, w którym składane jest odwołanie. W przeciwnym razie odwołanie zostanie odrzucone.  Źródło: https://home-affairs.ec.europa.eu/policies/migration-and-asylum/eu-immigration-portal/international-service-provider-denmark_en https://udln.dk/da/GlobalMenu/english/Information_for_Applicants Austria  Od decyzji organów wizowych można odwołać się do Federalnego Sądu Administracyjnego. Odwołania podlegają opłacie, chyba że przepisy prawa przewidują zwolnienie z opłat. Źródło:  \fhttps://www.bvwg.gv.at/In-English/Proceedings.html https://home-affairs.ec.europa.eu/policies/migration-and-asylum/eu-immigration-portal/international-service-provider-austria_en Portugalia Wnioskodawcy mogą odwołać się od odmowy wydania wizy zgodnie z prawem krajowym Portugalii. Dostępne opcje to: złożenie skargi do organu, który wydał akt w ciągu 15 dni od powiadomienia w Urzędzie Konsularnym/Wydziale Konsularnym. Odwołanie hierarchiczne w ciągu trzech miesięcy od powiadomienia do członka Rządu odpowiedzialnego za obszar Spraw Zagranicznych w Urzędzie Konsularnym/Wydziale Konsularnym. Wszczęcie postępowania administracyjnego w celu zakwestionowania aktów w ciągu trzech miesięcy od powiadomienia w Sądzie Administracyjnym Okręgu Lizbońskiego. Przedstawione opcje nie wykluczają się wzajemnie. W związku z tym wnioskodawca może odwołać się do Ministra i w zależności od wyników takiego odwołania, kontynuować postępowanie sądowe. Wnioskodawca może również odwołać się od decyzji i jednocześnie wnieść powództwo do sądu administracyjnego, nie czekając na wynik odwołania. Za koszty administracyjne związane z każdą procedurą odwoławczą należna jest opłata w wysokości 75 € za skorzystanie z gwarancji administracyjnej w celu zakwestionowania decyzji w sprawie wniosku wizowego, z wyjątkiem wniosków wynikających z zezwoleń na łączenie rodzin. Źródło: https://home-affairs.ec.europa.eu/policies/migration-and-asylum/eu-immigration-portal/international-service-provider-portugal_en https://vistos.mne.gov.pt/en/short-stay-visas-schengen/appeal-mechanisms\fPodmioty, na które oddziałuje projekt  \nGrupa\tWielkość\tŹródło danych \tOddziaływanie\nKomendant Główny Straży Granicznej\t1\t\t\tPełnienie funkcji Jednostki Krajowej ETIAS w zakresie czynności związanych z ręczną weryfikacją wniosków o wydanie zezwoleń na podróż, prowadzenia konsultacji z jednostkami krajowymi ETIAS innych państw członkowskich, rozpatrywanie wniosków \no ponowne rozpatrzenie sprawy od decyzji w sprawie zezwolenia na podróż, sporządzanie sprawozdań i statystyk, zarządzanie krajową listą ostrzegawczą ETIAS oraz pełnienie roli centralnego punktu dostępu poprzez przekazywanie danych ETIAS na wniosek wskazanych w projektowanej ustawie organów w celu zapobiegania, wykrywania, zwalczania oraz ścigania sprawców przestępstw. \t \tPełnienie funkcji Centralnego Organu Technicznego KSI ETIAS. Zapewnienie rozwiązań technicznych umożliwiających określonym w projektowanej ustawie organom dostęp do danych ETIAS. \t \tTworzy, prowadzi, rozwija i utrzymuje Krajowy Rejestr Cudzoziemców (KRC). \t \tZasilanie KRC danymi w zakresie przetwarzanych danych \ni informacji o  cudzoziemcach. \t \tProwadzenie kampanii informacyjnej związanej z uruchomieniem ETIAS. \t \tPełnienie funkcji administratora danych osobowych przetwarzanych w  KSI ETIAS. \t \tZarządzanie dostępem upoważnionego personelu organów oraz dostępem personelu uprawnionych organów posiadającego odpowiednie upoważnienia do korzystania z ETIAS oraz prowadzenie wykazu tego personelu.\nStraż Graniczna\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych w projektowanej ustawie. Pośredni dostęp do danych ETIAS przez centralny punkt dostępu - prawo do wystąpienia z wnioskiem o przekazanie przetwarzanych w systemie danych obywateli państw trzecich w celu zapobiegania, wykrywania, zwalczania oraz ścigania sprawców przestępstw.   Prowadzenie kampanii informacyjnej związanej                                           z uruchomieniem ETIAS.  Obowiązek wyznaczenia jednostek operacyjnych, które będą uprawnione do składania wniosków o przekazanie danych ETIAS.  Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy.  Prowadzenie postępowań administracyjnych wobec cudzoziemców nieposiadających ważnego zezwolenia na podróż.  Nakładanie kar administracyjnych na przewoźników.\fKomendant Główny Policji\t1\t\tObowiązki w zakresie podłączenia zarządzanych przez                           KGP systemów do KSI ETIAS: 1) zapewnia całodobową dostępność obsługi, zasilanie oraz bezpieczeństwo fizyczne elementów jednolitego interfejsu krajowego oraz jego łączność z systemem                               centralnym ETIAS; 2)\tzapewnia podłączenie krajowej infrastruktury granicznej do jednolitego interfejsu krajowego w ramach ośrodka podstawowego i zapasowego; 3)\tzapewnia niezbędną liczbę kluczowych elementów systemu tak, aby w razie awarii jednego z nich element zapasowy natychmiast przejął jego rolę bez zatrzymywania procesu produkcyjnego, i wydajną łączność na potrzeby KSI ETIAS; 4)\twspółpracuje z COT KSI ETIAS w zakresie doprowadzenia sieci łączności do jednolitego interfejsu krajowego w celu podłączenia krajowej infrastruktury granicznej.  Obowiązek wyznaczenia punktu kontaktowego w zakresie prowadzenia konsultacji.\n\tPolicja\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych w projektowanej ustawie. Pośredni dostęp do danych ETIAS przez centralny punkt dostępu - prawo do wystąpienia z wnioskiem o przekazanie przetwarzanych w systemie danych obywateli państw trzecich w celu zapobiegania, wykrywania, zwalczania oraz ścigania sprawców przestępstw.   Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy.  Obowiązek wyznaczenia jednostek operacyjnych, które będą uprawnione do składania wniosków o przekazanie danych ETIAS.\n\twojewodowie\t16\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach  określonych w projektowanej ustawie.\n\tSzef Urzędu do Spraw Cudzoziemców\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych w projektowanej ustawie.  Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy.  Obowiązek wyznaczenia punktu kontaktowego w zakresie prowadzenia konsultacji.\n\tminister właściwy \ndo spraw zagranicznych\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych w projektowanej ustawie.  Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy.  Obowiązek wyznaczenia punktu kontaktowego w zakresie prowadzenia konsultacji.  Zasilanie KRC danymi w zakresie przetwarzanych danych i informacji o cudzoziemcach.\n\t\fminister właściwy \ndo spraw wewnętrznych\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych w projektowanej ustawie.  Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy.  Obowiązek wyznaczenia punktu kontaktowego w zakresie prowadzenia konsultacji.  Sprawdzenie gotowości do prawidłowej eksploatacji KSI ETIAS przez poszczególne organy uprawnione do bezpośredniego dostępu do KSI ETIAS.  Nadzór nad prawidłowością funkcjonowania KSI ETIAS.  Wydanie aktów wykonawczych do ustawy.  Uczestniczy w realizacji zadań związanych z tworzeniem, prowadzeniem, rozwojem i utrzymaniem Krajowego Rejestru Cudzoziemców.  Zasilanie KRC danymi w zakresie przetwarzanych danych i informacji o cudzoziemcach.\n\tminister właściwy do spraw informatyzacji\t1\t\tZapewnia funkcjonowanie Krajowego Rejestru Cudzoziemców oraz uczestniczy w realizacji zadań związanych z tworzeniem, prowadzeniem, rozwojem i utrzymaniem Krajowego Rejestru Cudzoziemców.  Zasilanie KRC danymi w zakresie przetwarzanych danych i informacji o cudzoziemcach.\n\tminister właściwy do spraw pracy\t\t\tZasilanie KRC danymi w zakresie przetwarzanych danych i informacji o cudzoziemcach.\n\tminister właściwy do spraw szkolnictwa wyższego i nauki\t\t\tZasilanie KRC danymi w zakresie przetwarzanych danych i informacji o cudzoziemcach.\n\tminister właściwy do spraw zabezpieczenia społecznego\t\t\tZasilanie KRC danymi w zakresie przetwarzanych danych i informacji o cudzoziemcach.\n\tMinister Sprawiedliwości\t\t\tObowiązek wyznaczenia i zawiadomienia o punkcie kontaktowym w zakresie prowadzenia konsultacji (jeden wspólny punkt kontaktowy odpowiednio dla prokuratur oraz sądów).  Udostępnienie danych z Krajowego Rejestru Karnego na potrzeby spraw o zezwolenia na podróż.\n\tkonsulowie\t36 konsulatów generalnych 2 agencje konsularne 91 wydziałów konsularnych\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych                                    w projektowanej ustawie. Prowadzenie kampanii informacyjnej związanej z uruchomieniem ETIAS.\n\tSłużba Celno-Skarbowa\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych  w nim danych w celach i na zasadach określonych                                     w projektowanej ustawie.\n\tKrajowa Administracja Skarbowa\t1\t\tObowiązek wyznaczenia jednostek operacyjnych, które będą uprawnione do składania wniosków o przekazanie danych ETIAS.   Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy.  Obowiązek wyznaczenia punktu kontaktowego w zakresie prowadzenia konsultacji.\n\tRada do Spraw Uchodźców\t1\t\tBezpośredni dostęp do ETIAS w celu wglądu do przetwarzanych w nim danych w celach i na zasadach określonych w projektowanej ustawie.\n\tGłówny Inspektor Sanitarny\t\t\tObowiązek wyznaczenia punktu kontaktowego w zakresie prowadzenia konsultacji.  \n\t\fDyrektor Generalny Służby Więziennej\t\t\tZasilanie KRC danymi w zakresie przetwarzanych danych i informacji o  cudzoziemcach.\n\tZakład Ubezpieczeń Społecznych\t\t\tZasilanie KRC danymi w zakresie przetwarzanych danych i informacji o  cudzoziemcach.\nProkuratura        Sądy   Agencja Bezpieczeństwa Wewnętrznego   Agencja Wywiadu   Centralne Biuro Antykorupcyjne  Służba Ochrony Państwa   Służba Kontrwywiadu Wojskowego   Służba Wywiadu Wojskowego   Żandarmeria  Wojskowa \t \tKrajowa Administracja Skarbowa\t358 prokuratur rejonowych  45 prokuratur okręgowych  11 prokuratur regionalnych 1 Prokuratura Krajowa 374 sądy powszechne  1 Agencja Bezpieczeństwa Wewnętrznego  1 Agencja Wywiadu  1 Centralne Biuro Antykorupcyjne  1 Służba Ochrony Państwa  1 Służba Kontrwywiadu Wojskowego  1 Służba Wywiadu Wojskowego  1 Żandarmeria Wojskowa  1 Krajowa Administracja Skarbowa\t\tPośredni dostęp do danych ETIAS przez centralny punkt dostępu - prawo do wystąpienia z wnioskiem o przekazanie przetwarzanych w systemie danych obywateli państw trzecich w celu zapobiegania, wykrywania, zwalczania oraz ścigania sprawców przestępstw.   Obowiązek wyznaczenia jednostek operacyjnych, które będą uprawnione do składania wniosków o przekazanie danych ETIAS.  Prawo wystąpienia z wnioskiem o rejestrację danych na liście ostrzegawczej ETIAS lub modyfikację i usunięcie danych z tej listy. \nPrezes Urzędu Ochrony Danych \tOsobowych\t1\t\tSprawowanie nadzoru nad przetwarzaniem danych osobowych obywateli państw trzecich poprzez KSI ETIAS.  Rozpatrywanie skarg obywateli państw trzecich od decyzji.  Przeprowadzenie kontroli KSI ETIAS przed jego uruchomieniem w celu zapewnienia spełniania wymagań przewidzianych w przepisach o ochronie danych osobowych.\nNarodowy Instytut Zdrowia Publicznego PZH\t1\t\tZapewnienie SG dostępu do danych w rejestrze chorób zakaźnych w drodze teletransmisji danych. \n\tPrzewoźnicy\tTrudne do oszacowania\t\tNakładanie kar administracyjnych na przewoźników lotniczych, morskich i przewoźników międzynarodowych przewożących grupy cudzoziemców drogą lądową autokarami.\n\tObywatele państw trzecich uprawnieni do pobytu krótkoterminowego i jednocześnie zwolnieni z obowiązku wizowego\tTrudne do oszacowania. W zakresie posiadanych danych ruch graniczny w ramach ruchu bezwizowego cudzoziemców w 2025 r. wyniósł: przyjazd – 8 882 122, wyjazd – 9 \f527 632, razem – 18 409 754 (przekroczeń granicy)\t\tPrzetwarzanie ich danych w systemie ETIAS na zasadach określonych w projektowanej ustawie.\nInformacje na temat zakresu, czasu trwania i podsumowanie wyników konsultacji\nStosownie do wymogów art. 5 ustawy z dnia 7 lipca 2005 r. o działalności lobbingowej w procesie stanowienia prawa (Dz. U. z 2025 r. poz. 677, z późn. zm.) oraz § 52 ust. 1 uchwały nr 190 Rady Ministrów z dnia 29 października 2013 r. – Regulamin pracy Rady Ministrów                              (M.P. z 2026 r. poz. 404), projekt ustawy został zamieszczony w Biuletynie Informacji Publicznej Rządowego Centrum Legislacji w serwisie Rządowy proces legislacyjny. Nie zgłosił się żaden podmiot zainteresowany pracami nad projektem w trybie przepisów \no działalności lobbingowej.  Ze względu na zakres przedmiotowy, projektowana ustawa została skierowana do zaopiniowania przez: Wojewodów; Pierwszego Prezesa Sądu Najwyższego; Rzecznika Praw Obywatelskich; Rzecznika Praw Dziecka; Prokuratora Krajowego; Prezesa Zakładu Ubezpieczeń Społecznych; Prezesa Urzędu Ochrony Danych Osobowych; Radę do Spraw Uchodźców; Głównego Inspektora Sanitarnego; Narodowy Instytut Zdrowia Publicznego PZH; Szefa Krajowej Administracji Skarbowej; Polską Wytwórnię Papierów Wartościowych. Ponadto, m.in. w związku z tym, że projektowane rozwiązania wiążą się z kwestią przetwarzania danych, w tym danych osobowych, projekt został skierowany do konsultacji publicznych do następujących podmiotów: Centrum Cyfrowe Projekt: Polska; Fundacja Bezpieczeństwa Informacji Polska; Fundacja Bezpieczna Cyberprzestrzeń; Fundacja Panoptykon; SABI - Stowarzyszenie Inspektorów Ochrony Danych; Stowarzyszenie Inspektorów Ochrony Danych Osobowych; Stowarzyszenie Sieć Obywatelska – Watchdog Polska; Konfederacja „Lewiatan”; Business Centre Club – Związek Pracodawców; Pracodawcy Rzeczypospolitej Polskiej; Europejska Unii Małych i Średnich Przedsiębiorstw oraz Klasy Średniej UNICORN; Federacja Przedsiębiorców Polskich; Helsińska Fundacja Praw Człowieka; Stowarzyszenie Amnesty International; Instytut na Rzecz Państwa Prawa; Stowarzyszenie Interwencji Prawnej; Centrum Pomocy Prawnej im. Haliny Nieć; PLL LOT; Rada Przedstawicieli Linii Lotniczych w Polsce (BARIP); Polska Izba Gospodarcza Transportu Samochodowego i Spedycji; Związek Armatorów Polskich; Krajowa Izba Gospodarki Morskiej; Zrzeszenie Międzynarodowych Przewoźników Drogowych w Polsce; Polskie Stowarzyszenie Przewoźników Autokarowych. Uwagi zgłosili (w ramach I i II tury): Prezes Urzędu Ochrony Danych Osobowych, Prokurator Krajowy, Prezes Zakładu Ubezpieczeń Społecznych, Konfederacja Lewiatan, Wojewoda Podkarpacki, Wojewoda Zachodnio – Pomorski, Wojewoda Opolski, Wojewoda Kujawsko – Pomorski, Wojewoda Lubuski, Polska Wytwórnia Papierów Wartościowych, Rzecznik Praw Obywatelskich, Pierwszy Prezes Sądu Najwyższego, Stowarzyszenie Interwencji Prawnej, Rzecznik Praw Dziecka, Główny Inspektor Sanitarny, Narodowy Instytut Zdrowia Publicznego PZH – PIB. Uwagi zostały omówione w raporcie z konsultacji publicznych i opiniowania. Projekt ustawy został przekazany również pod obrady Komisji Wspólnej Rządu i Samorządu Terytorialnego, która zaopiniowała go pozytywnie.\nWpływ na sektor finansów publicznych (ceny stałe z 2026 r.)\tSkutki w okresie 10 lat od wejścia w życie zmian [mln zł] \t0 2026\t1 2027\t2 2028\t3 2029\t4 2030\t5 2031\t6 2032\t7 2033\t8 2034\t9 2035\t10 2036\tŁącznie     (0-10) Dochody ogółem\t0,000\t2,227\t2,230\t2,235\t1,788\t1,793\t1,798\t1,802\t1,809\t1,814\t1,818\t19,314 Budżet państwa\t0,000\t0,314\t0,314\t0,314\t0,247\t0,247\t0,247\t0,247\t0,248\t0,248\t0,248\t2,672 \fJST\t0,000\t1,779\t1,779\t1,780\t1,397\t1,398\t1,399\t1,400\t1,401\t1,402\t1,402\t15,139 Narodowy Fundusz Zdrowia\t0,000\t0,025\t0,026\t0,027\t0,027\t0