},{"kind":"official_link","value":"rcl/12408952/stage/13196550","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","text_sha256":"17433d201fc2d487374264c80933a1e02968958b01b96c8568241b09dd4ee587","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","text_sha256":"17433d201fc2d487374264c80933a1e02968958b01b96c8568241b09dd4ee587","block_id":"part:0","start":0,"end":118,"quote":"Projekt z 05.10.2026 r.\nU S T A W A\nz dnia …\no zmianie ustawy – Prawo konsularne oraz niektórych innych ustaw1)\nArt. 1"},{"kind":"draft_date","value":"2026-10-05","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","text_sha256":"17433d201fc2d487374264c80933a1e02968958b01b96c8568241b09dd4ee587","block_id":"part:0","start":0,"end":20,"quote":"Projekt z 05.10.2026"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","text_sha256":"17433d201fc2d487374264c80933a1e02968958b01b96c8568241b09dd4ee587","block_id":"part:0","start":66109,"end":66131,"quote":"Ustawa wchodzi w życie"}],"limitations":["support_applicability_unknown"],"links":[{"kind":"supporting","source_part":1,"target_part":0,"status":"confirmed","evidence":[0]},{"kind":"supporting","source_part":2,"target_part":0,"status":"unknown","evidence":[]}],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":66825,"page_start":1,"page_end":33,"losses":[]},{"part_index":1,"stage":"extraction","start":0,"end":95646,"page_start":1,"page_end":39,"losses":[]},{"part_index":2,"stage":"extraction","start":0,"end":86105,"page_start":1,"page_end":20,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":66825,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"7202fd2486fb3ad6b6072a6a5d3bf0a11902cce40e7cfe0573bd9beb5723de76"},"law_sha256":"law-v2:a35097e1ec99542d15b26e3dac16886995982f09781cd89e820536191d24d1ac","source_checked_at":"2026-10-17T09:07:43Z"}',10,'RCL/12408952','2026-10-17T09:07:43+00:00');
INSERT INTO "analysis_memo" VALUES('9ddb3e30e608b4886b0831f289342c440959f9cc8ed9c2eb00dfd53ef99b719d','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект серьёзно меняет обучение и экзамены на польские права, вводит пилот цифровой карты курсанта и обязательную видеозапись практики. Уточняются правила обмена иностранных прав без срока действия и упрощается подтверждение кода 95 для водителей-профессионалов.","key_changes":["Новый порядок для обмена иностранных прав без срока действия на польские с обычными сроками","Пилот «cyfrowa karta kursanta» с записью часов вождения и GPS‑маршрутов в e‑системе","Обязательная видеозапись практики: внутренний экзамен (видео), госэкзамен (видео+аудио)","Теория действует 12 мес., результат плаца (другие категории) хранится 24 мес. и повторно не сдаётся","Шеринг‑самокаты/велосипеды можно оставлять только в спецзонах; вне зоны — эвакуация и платёж"],"affected_groups":["иностранцы, проходящие курсы в польских автошколах","владельцы национальных прав из стран вне ЕС/EFTA/Швейцарии, обменивающие их на польские","иностранные водители‑профессионалы, получающие świadectwo kierowcy в Польше","иностранные родители и дети, получающие kartę rowerową","иностранцы, пользующиеся шеринг‑самокатами и велосипедами в Польше"],"practical_impact":"Иностранцам, обменивающим права третьих стран без указанного срока, польское право будет выдаваться на стандартный ограниченный срок. Обучение и экзамены на права будут фиксироваться в видео и цифровых записях, теория будет действовать только 12 месяцев, а шеринг‑самокаты придётся оставлять в отмеченных парковках, иначе грозит эвакуация и сборы.","effective_date":"Закон вступает в силу 1 января 2027 г., кроме: части норм (цифровая карта курсанта, видеозапись внутренних экзаменов, повышенные требования к инструкторам и переходные правила) – с 1 июля 2027 г.; положений о Центрум ds. Szkolenia i Egzaminowania и новых правилах микромобильности и транспорта drogowego – с 1 января 2028 г.; детальных норм о пилотном проекте cyfrowa karta kursanta – с 1 января 2029 г.","confidence":0.84,"rationale":"Акт комплексно меняет систему обучения и экзаменов на права, обмен иностранных прав и доступ к профессии водителя, что затрагивает многих иностранцев как участников дорожного движения, поэтому категория «social» и значимость 3.","mnemonic_candidate":"Цифровой курсант","mnemonic_fallback":"Реформа обучения водителей","mnemonic_basis":"Проект вводит пилот цифровой карты курсанта и обязательную видеозапись практических экзаменов.","mnemonic_language":"ru","changes_since_previous":["Цифровая карта курсанта теперь запускается как добровольный пилот, а не сразу как единая обязательная система.","Срок действия теоретического экзамена установлен на 12 месяцев, а не на 24, как описывалось ранее.","Добавлены специальные правила для обмена иностранных прав без указанного срока действия на польские.","Введена аболиция для добросовестных водителей при выявлении подлога документов автошколой и предел 2 лет на аннулирование экзамена.","Точно прописаны размеры сборов за эвакуацию и хранение шеринг‑самокатов/велосипедов (200 zł + 50 zł/сутки).","Существенно расширены и детализированы правила детского велодвижения и karty rowerowej (возраст, опека, стандарты экзамена)."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":182566,"truncated":false,"text_source":"documents","created_at":"2026-10-17T09:07:43Z","input_tokens":58599,"output_tokens":3071,"cache_read_input_tokens":1280,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument800663.pdf","source_kind":"rcl","revision":3,"text_sha256":"text-v2:e269ba14f2def14a7f75e5e59ac1b780a3dbfa9b61528de4ab8ff2718d14a151","selection":{"question":"bill_text","state":"selected","belonging":[],"role":[],"version":["rcl/12411950/stage/13212208","25.09.2026 UD 402_projekt ustawy-3.pdf"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/do