INSERT INTO "analysis_memo" VALUES('9c843cc5d38ddd86f24aebda618d7497f323240d123389d2c1e327e1c3b2d346','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Закон запускает с 2027 года статус «ближайшего лица» и договор о совместной жизни, вносит поправки в закон о чужеземцах, о въезде граждан ЕС и о работе иностранцев. Партнёр по зарегистрированному договору почти во всех миграционных нормах приравнивается к супругу.","key_changes":["В ustawa o cudzoziemcach партнёр по umowa o wspólnym pożyciu приравнен к супругу (ВНЖ, ПМЖ, депортация)","В законе о въезде граждан ЕС партнёр признан членом семьи с правом въезда, проживания и ПМЖ","В законе о работе иностранцев партнёр поляка/оседлого иностранца может работать на правах супруга","В законе о NFZ партнёр беженца/просителя убежища признаётся членом семьи для медпомощи","Создан реестр партнёрств в USC и отдельное справочное «заświadczenie o statusie osoby najbliższej»"],"affected_groups":["иностранцы в зарегистрированной umowa o wspólnym pożyciu с гражданами Польши","иностранцы‑партнёры граждан ЕС, пользующиеся свободой передвижения","граждане третьих стран — члены семей иностранцев с ВНЖ/ПМЖ","соискатели убежища и их партнёры","работодатели, нанимающие иностранцев‑партнёров поляков"],"practical_impact":"Партнёр по зарегистрированному договору сможет подавать на ВНЖ, ПМЖ и воссоединение семьи, как супруг, а также работать и пользоваться рядом соц‑ и медправ. Для этого нужен нотариальный договор, его регистрация в USC и справка о статусе, а отношения проверяются на фиктивность, как брак.","effective_date":"Основной закон о статусе osoby najbliższej i umowie o wspólnym pożyciu и настоящая вводящая его ustawa входят в силу с 1 января 2027 г.; статья 256 (о доработке ИТ‑систем) – со следующего дня после опубликования.","confidence":0.86,"rationale":"Поправки глубоко меняют законы о чужеземцах, о въезде граждан ЕС и о работе иностранцев, приравнивая зарегистрированного партнёра к супругу в миграционных и связанных правах.","mnemonic_candidate":"Партнёр как супруг","mnemonic_fallback":"Статус партнёра","mnemonic_basis":"В ustawa o cudzoziemcach и законе о въезде граждан ЕС партнёр по umowa o wspólnym pożyciu признаётся членом семьи наравне с супругом (виды на жительство, ПМЖ, проверка фиктивности).","mnemonic_language":"ru","changes_since_previous":["Подробно переписаны разделы ustawa o cudzoziemcach: для почти всех семейных ВНЖ/ПМЖ прямо добавлена umowa o wspólnym pożyciu, а не только отдельные случаи","В законе о въезде граждан ЕС добавлены специальные процедуры проверки фиктивности именно договора о совместной жизни, а не только брака","В закон о работе иностранцев внесён прямой пункт, что партнёр по umowa o wspólnym pożyciu с поляком/оседлым иностранцем входит в льготную категорию без обычного разрешения на работу","В законе о NFZ уточнено, что партнёр просителя международной защиты учитывается как член семьи для медстрахования","Создан отдельный реестр партнёрств в USC и предусмотрено специальное заświadczenie о статусе osoby najbliższej w związku","Введены переходные нормы: старые миграционные дела и решения о выдворении, начатые до вступления закона в силу, ведутся по прежним (брачно‑ориентированным) правилам"]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":664717,"truncated":false,"text_source":"pdf","created_at":"2026-10-17T09:07:43Z","input_tokens":236861,"output_tokens":2716,"cache_read_input_tokens":1280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2111/attachment/2111_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"text-v2:6af9660d9f0772d8ebc8e22bd36b98bd91c63c76872d04134dca6143470bf8b1","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/2111/attachment/2111_u3.pdf","members":[],"container_sha256":"4929d334700b4ec7a61dd1c99b5e8c8f878dd67698669d1a770b3ae06256f2aa","sha256":"4929d334700b4ec7a61dd1c99b5e8c8f878dd67698669d1a770b3ae06256f2aa","role":"bill","text":"","pages":312,"page_start":1,"page_end":312,"text_start":0,"text_end":664717,"text_sha256":"651b459f75de64e9c2b84722b4c0f262a24995d7cc015189e66e300b6bebacd8","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2111/attachment/2111_u3.pdf","text_sha256":"651b459f75de64e9c2b84722b4c0f262a24995d7cc015189e66e300b6bebacd8","block_id":"part:0","start":0,"end":231,"quote":"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\n\nUSTAWA\nz dnia 29 maja 2026 r.\nPrzepisy wprowadzające ustawę o statusie osoby najbliższej w związku\ni umowie o wspólnym pożyciu1)\nRozdział 1\nPrzepis ogólny\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":664717,"page_start":1,"page_end":312,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":664717,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"c6efff95884f9832b82caa39d77acf66355d44e976e8f9541284a89eecf5d565"},"law_sha256":"law-v2:f31bfb1966d3a512d91fe675f809ed50d8f620743022d97f919f574f2af516fa","source_checked_at":"2026-10-17T09:07:43Z"}',10,'2111','2026-10-17T09:07:43+00:00');
INSERT INTO "analysis_memo" VALUES('d3b0ea0c41084683d14284dbea462c3f07f7c2bdaef02638b7a8575fc6a47e9d','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Специальный закон для проведения Всемирного скаутского Джамбори в Гданьске в 2027 г. Участники освобождаются от консульского сбора за польскую и шенгенскую визу, а их заявления обещают рассматривать без лишних задержек. Для волонтёров вводятся детальные проверки несудимости.","key_changes":["Участники Джамбори не платят консульский сбор за визу на въезд в Польшу","К заявлению на визу нужно приложить подтверждение регистрации участия","При подаче списка за 6 недель визы рассматривают без лишней задержки","Волонтёры‑иностранцы должны предоставить справки о несудимости за 10 лет","Организатор проверяет волонтёров в КРК и реестрах по преступлениям против детей"],"affected_groups":["иностранные участники и гости Джамбори 2027","иностранные волонтёры на Джамбори","члены иностранных официальных делегаций, едущие на Джамбори"],"practical_impact":"Иностранные участники экономят на визовом сборе и могут рассчитывать на более быстрое рассмотрение заявлений при своевременной подаче. Волонтёрам понадобятся официальные справки о несудимости из стран гражданства и проживания за последние 10 лет.","effective_date":"Закон вступает в силу через 14 дней со дня опубликования.","confidence":0.96,"rationale":"Закон прямо вводит льготы по визам для участников Джамбори и специальные требования проверки волонтёров‑иностранцев, что относится к сфере виз и легализации пребывания.","mnemonic_candidate":"Бесплатные визы Джамбори","mnemonic_fallback":"Закон о визах Джамбори","mnemonic_basis":"Статья 20 освобождает участников Джамбори от консульского сбора за национальную и шенгенскую визы при наличии подтверждения участия.","mnemonic_language":"ru","changes_since_previous":["Уточнены категории волонтёров: отдельно описаны граждане ЕС и не‑ЕС и набор проверок для них.","Для волонтёров‑граждан ЕС добавлена обязанность приносить справки о несудимости из стран проживания вне ЕС за последние 10 лет.","Закреплено, что организатор запрашивает через КРК данные о судимости волонтёров‑граждан ЕС в их стране гражданства.","Расширён период, к которому привязаны специальные меры закона: теперь с 14 июля по 16 августа 2027 года."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":27534,"truncated":false,"text_source":"pdf","created_at":"2026-10-19T06:47:45Z","input_tokens":11271,"output_tokens":2633,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"text-v2:f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","members":[],"container_sha256":"f88cad4bec78dab024c2dfc612fd95dc58bc9a160d82e2ae7cbd1b123fced776","sha256":"f88cad4bec78dab024c2dfc612fd95dc58bc9a160d82e2ae7cbd1b123fced776","role":"bill","text":"","pages":13,"page_start":1,"page_end":13,"text_start":0,"text_end":27534,"text_sha256":"cd1d300fca04381f23bbdd95dfcde2691b3205c2b8426049d3b3a916aaddf1a5","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","text_sha256":"cd1d300fca04381f23bbdd95dfcde2691b3205c2b8426049d3b3a916aaddf1a5","block_id":"part:0","start":0,"end":238,"quote":"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\n\nUSTAWA\nz dnia 18 września 2026 r.\no szczególnych rozwiązaniach związanych z organizacją XXVI Światowego\nJamboree Skautowego w Rzeczypospolitej Polskiej w 2027 r.\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf","text_sha256":"cd1d300fca04381f23bbdd95dfcde2691b3205c2b8426049d3b3a916aaddf1a5","block_id":"part:0","start":27426,"end":27448,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":27534,"page_start":1,"page_end":13,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":27534,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"483dadd76045041e7386267f20834fb7625c1ff5c723da87a149bd3ef02365f1"},"law_sha256":"law-v2:7a613a479dd0ec93f8e71e3e2a43ab84c179dba165ae9c962ecec27aea6fcecc","source_checked_at":"2026-10-19T06:47:45Z"}',10,'2846','2026-10-19T06:47:45+00:00');
INSERT INTO "analysis_memo" VALUES('44ba2094017958560e9242c93b8269d1fea94ae5c11144d170a84d84950e0d1f','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается доступа к данным и их использования в рамках регламента ЕС о данных (Data Act), не затрагивает статус, пребывание или права иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":4366,"output_tokens":88,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/35146/2026','2026-10-19T22:29:07+00:00');
INSERT INTO "analysis_memo" VALUES('b1f774f862a3f88c956db9b997b614b965806265a535ea24a3bca55988660323','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект вводит в польское право механизмы исполнения общеевропейского «Акта о данных» (Data Act). Президент UKE становится главным органом по надзору за справедливым доступом к данным, рассмотрением жалоб и наложением штрафов, а министр цифровизации – контактным органом для ЕС. Предусмотрены процедуры сертификации органов внесудебного разрешения споров и система административных штрафов.","key_changes":["Определяется Президент UKE как единственный «надлежащий орган» по Data Act, координационный центр по данным и орган по сертификации органов разрешения споров.","Устанавливаются административные процедуры рассмотрения жалоб пользователей, третьих лиц, держателей данных и органов сектора публичного на нарушения правил доступа и обмена данными по Data Act.","Вводится процедура сертификации органов внесудебного разрешения споров по вопросам доступа и использования данных, с пятилетним сроком действия сертификата и возможностью его продления или отзыва.","Создаётся система административных штрафов за невыполнение ключевых обязанностей по Data Act (для фирм до 4% годового оборота, для прочих – до 100 000 злотых).","Закрепляются обязанности министра цифровизации информировать Еврокомиссию о некоторых нормах польского права и замечаниях к техническим спецификациям, а также вносятся изменения в «Prawo komunikacji elektronicznej» для формального закрепления новых задач UKE."],"affected_groups":["Пользователи устройств интернета вещей и связанных цифровых услуг в Польше (включая потребителей, вне зависимости от гражданства)","Предприятия и другие держатели данных (производители, продавцы, арендаторы, поставщики услуг, получатели данных, «стражи доступа»)","Поставщики услуг обработки данных (в т.ч. облачные провайдеры и другие провайдеры IT‑инфраструктуры)","Органы сектора публичного Польши, а также институты ЕС (Комиссия Европейская, ЕЦБ, иные органы ЕС), когда они запрашивают данные у частного сектора","Президент Urzędu Komunikacji Elektronicznej (UKE) и его администрация","Министр цифровизации / министр по делам информатизации","Prezes Urzędu Ochrony Danych Osobowych (UODO) как орган по защите персональных данных","Административные суды (в т.ч. Войводский административный суд в Варшаве и Нaczelny Sąd Administracyjny)"],"practical_impact":"Для обычных пользователей (включая иностранцев, живущих в Польше) проект не создаёт новых материальных прав сверх уже действующего Акта о данных ЕС, но даёт понятный национальный механизм: можно жаловаться в Президента UKE, если, например, производитель «умного» устройства или облачный сервис не даёт доступ к данным или необоснованно отказывается ими делиться. Для компаний и держателей данных появляются чётко описанные процедуры споров с пользователями, третьими лицами и органами власти, а также риск значительных штрафов за невыполнение обязанностей по Data Act (доступ к данным IoT, условия обмена данными B2B/B2C/B2G, защита коммерческих тайн, правила смены облачного провайдера, требования по интероперабельности). Поставщики услуг обработки данных получают ясные национальные правила по передаче не персональных данных в третьи страны и контролю за интероперабельностью. Органы госсектора получают формальную процедуру запроса данных у частных компаний «в случае исключительной необходимости», но при этом сами могут быть объектом жалоб держателей данных. UKE существенно расширяет свои функции как цифровой регулятор (надзор, расследования, штрафы, координация), получает на это целевой бюджет до 2036 года; министр цифровизации формально отвечает перед Еврокомиссией за уведомления о некоторых польских законах и технических сомнениях по общим спецификациям ЕС. Все решения UKE по штрафам можно обжаловать в административных судах.","effective_date":"Вступит в силу через 3 месяца после официального опубликования в Dziennik Ustaw (конкретная дата ещё не известна, так как это только проект).","confidence":0.84,"rationale":"Проект реализует требования Регламента (ЕС) 2023/2854 (Data Act), который уже действует напрямую в странах ЕС. Поскольку множество его норм требует национальных процедур и органов, Польша должна определить: какой орган отвечает за применение и контроль, как именно подаются и рассматриваются жалобы, какие штрафы взимаются за нарушения и кто общается с Еврокомиссией по техническим вопросам. Законопроект делает Президентa UKE единственным компетентным органом по Data Act, совмещающим функции: регулятора, координационного центра по данным и органа по сертификации органов разрешения споров.\n\nДля рынка данных он устанавливает детализированные административные процедуры. В разделах 3 и 4 описано, как UKE рассматривает жалобы:\n- пользователей и третьих лиц на договорные ограничения доступа к данным и на отказ делиться данными (особенно при ссылке на коммерческую тайну),\n- держателей данных на действия органов публичного сектора или институтов ЕС, которые запрашивали или распространяли данные по режиму «исключительной необходимости»,\n- органов публичного сектора/ЕС на отказ компаний предоставить данные или на спор о размере компенсации.\nВ каждом случае закон указывает, какая жалоба запускает производство, кто является сторонами (пользователь, держатель данных, орган сектора публичного, орган ЕС) и что в итоге решает UKE (административное решение).\n\nПроцедуры опираются на «Kodeks postępowania administracyjnego» (Кодекс административного производства) с оговорёнными исключениями. Особо регулируется общая «скарга до Prezesa UKE» по ст. 38 Data Act: это не обычная жалоба гражданина по КАП, а специальный механизм, когда любой считает, что его право по Data Act нарушено. UKE обязан в течение 2 месяцев (максимум 4) уведомить заявителя о результатах: какие меры приняты либо почему их не будет. Такая жалоба может привести к запуску отдельного надзорного производства о применении Регламента.\n\nЗакон подробно описывает надзорное производство UKE: регулятор может начать дело по собственной инициативе, идентифицировать нарушения, дать стороне срок на объяснения, затем выдать предупреждение с требованием прекратить нарушение и установить срок устранения. Только если адресат не исправился, UKE в решении одновременно обязует устранить нарушения и накладывает административный штраф. При прекращении нарушения или отсутствии его факта дело подлежит прекращению. Это создаёт «каскадную» модель: вначале мягкое воздействие (предупреждение), потом санкция.\n\nРаздел о штрафах (Rozdział 9) специально перелопачивает многочисленные обязанности из Data Act по типам адресатов:\n- производители и продавцы/арендодатели «скоммуницированных продуктов» (подключённых устройств) и связанных услуг,\n- держатели данных (posiadacze danych),\n- пользователи,\n- «стражи доступа» и третьи лица, которым передаются данные,\n- получатели данных,\n- органы, получающие данные по режиму исключительной необходимости,\n- поставщики услуг обработки данных (облачные провайдеры и т.п.),\n- любые субъекты, предлагающие подключённые продукты или услуги в ЕС и подпадающие под ст. 37(11) Data Act.\nДля каждой группы перечислено, нарушение каких конкретных статей Регламента влечёт штраф. Максимум: до 100 000 PLN для непредпринимателей и до 4% оборота за предыдущий год для предприятий. Закон компонует правила расчёта оборота (в т.ч. после слияний, при отсутствии отчётности), критерии определения размера штрафа и возможность отказаться от штрафа с учётом тех же критериев из ст. 40(3) Data Act. Специально исключено применение ст. 189e КАП (об освобождении от санкции при форс‑мажоре), чтобы не расходиться с Регламентом ЕС, но при этом форс‑мажорные обстоятельства могут смягчать ответственность через общие критерии.\n\nОтдельный блок касается сертификации органов внесудебного разрешения споров. Любой орган, желающий выступать посредником по спорам о доступе к данным, может запросить у UKE сертификат при подтверждении требований Data Act (независимость, компетенции, ресурсы и т.п.). Сертификат выдаётся на 5 лет, можно продлить при повторной проверке, отказ или отзыв оформляются решением, а информация о сертифицированных и лишённых сертификата органах направляется в Еврокомиссию для европейского реестра. Отзыв сертификата действует немедленно, чтобы «несоответствующий» орган не продолжал выдавать себя за сертифицированный.\n\nМинистр цифровизации получает узкоспециализированные обязанности: уведомлять Еврокомиссию, если польское право запрещает продажу данных для нужд официальной статистики (это влияет на возможность требовать компенсацию за предоставление данных по Data Act), а также направлять возражения, если Польша считает, что утверждённые Комиссией общие спецификации по интероперабельности или «умным контрактам» не полностью отвечают основным требованиям Регламента.\n\nЗакон вносит изменение в «Prawo komunikacji elektronicznej», формально добавляя к задачам Президента UKE исполнение функций по Data Act (орган надзора, орган по сертификации, координатор данных). Также в нём установлен многолетний лимит бюджетных расходов для UKE до 2036 года, что нужно для организационного наращивания компетенций.\n\nДля иностранцев, живущих в Польше, актуально следующее. Существо их прав по данным (например, право получить телеметрию своего подключённого автомобиля и передать её независимому сервису, сменить облачного провайдера, защитить свои интересы при доступе госорганов к данным частного сектора) уже установлено непосредственно Регламентом ЕС и не зависит от гражданства. Этот проект создаёт для них практические инструменты в Польше: куда подать жалобу, как она будет рассмотрена, какие последствия наступят для нарушителя. Уточняется право любой «особы» (физической или юридической), имеющей обычное место жительства, работы или регистрации в стране ЕС, пожаловаться в орган, а также защищать свои интересы через административные суды. Это затрагивает сферу потребительских и цифровых прав, а не миграционный статус, трудоустройство или социальные выплаты, поэтому влияние для иностранцев оценивается как косвенное (категория indirect, балл 2).","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":134403,"truncated":false,"text_source":"pdf","created_at":"2026-10-19T23:22:33Z","input_tokens":43539,"output_tokens":3497,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35146-2026/$file/10-RPW-35146-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:ab95406be8ee1bb434dc529cb306f14bafd861ba5ed3effa31ee654c40cdca6b","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35146-2026/$file/10-RPW-35146-2026.pdf","members":[],"container_sha256":"a1adc3180e5b7c777f7855bfe63cf3b545a43c93e4951b06dcc97181c27a170a","sha256":"a1adc3180e5b7c777f7855bfe63cf3b545a43c93e4951b06dcc97181c27a170a","role":"bill","text":"","pages":360,"page_start":1,"page_end":360,"text_start":0,"text_end":806526,"text_sha256":"656bf3b05a6abaaaa5c68db496cb001d71c3460151a053c6881f4ca2bb4ad627","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35146-2026/$file/10-RPW-35146-2026.pdf","text_sha256":"656bf3b05a6abaaaa5c68db496cb001d71c3460151a053c6881f4ca2bb4ad627","block_id":"part:0","start":0,"end":801,"quote":"tel. +48 (22) 694 75 00 Al. Ujazdowskie 1/3; 00-583\ndkpl@kprm.gov.pl Warszawa\ngov.pl/premier\nDonald Tusk\n\nWarszawa, dnia /elektroniczny znacznik czasu/\n\nRM-0610-175-26\nUC114\n\nPan Włodzimierz CZARZASTY\nMarszałek Sejmu\n\nSzanowny Panie Marszałku,\n\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam Sejmowi\nprojekt ustawy o sprawiedliwym dostępie do danych i ich wykorzystywaniu.\nProjekt ma na celu wykonanie prawa Unii Europejskiej.\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac parlamentarnych został\nupoważniony Minister Cyfryzacji.\n\nZ poważaniem\nDonald Tusk\n/podpisano kwalifikowanym podpisem elektronicznym/\n\nDo wiadomości:\nwnioskodawca \fProjekt\nU S T AWA\nz dnia\no sprawiedliwym dostępie do danych i ich wykorzystywaniu 1)\nRozdział 1\nPrzepisy ogólne\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35146-2026/$file/10-RPW-35146-2026.pdf","text_sha256":"656bf3b05a6abaaaa5c68db496cb001d71c3460151a053c6881f4ca2bb4ad627","block_id":"part:0","start":30334,"end":30356,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":806526,"page_start":1,"page_end":360,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":806526,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"594832035a5716a98a1ab857fa26e3fb96d0ca384a97ee01d5c1b9bdc6298a15"},"law_sha256":"law-v2:22e4aa28bcee8fd007e60bba959f74c4d6d679248b53e94abd33960f46d3fa91","source_checked_at":"2026-10-19T23:22:33Z"}',10,'RPW/35146/2026','2026-10-19T23:22:56+00:00');
INSERT INTO "analysis_memo" VALUES('9ff7ce59d9c3def8c9c47a2718a61cd20f2fc6892419167d881e48df9b964454','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается создания Академии Влоцлавской на базе существующего вуза и не затрагивает права, обязанности или процедуры, связанные с иностранцами."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":6269,"output_tokens":87,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3235','2026-10-20T18:03:28+00:00');
INSERT INTO "analysis_memo" VALUES('34dea9ef90c60eded2345624814bb02e985177fafc78d9f0ab33be1a6e2d2c3e','{"triage":{"affects_foreigners":false,"confidence":0.9,"rationale":"Законопроект касается продления обязанности гмины предоставлять нанимателям жилья замену и покрытие расходов на переезд при сносе или ремонте дома, и никак не затрагивает иностранцев как отдельную категорию."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":15456,"output_tokens":108,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3234','2026-10-20T18:03:30+00:00');
INSERT INTO "analysis_memo" VALUES('32eac6ee8413489db8364580c960870eb91ded38494d616b5be20a697d57cf12','{"triage":{"affects_foreigners":false,"confidence":0.82,"rationale":"Проект касается полномочий городской/гминной стражи, Полиции и Страже Гранична в части видеомониторинга, идентификации лиц и организации контроля, а упоминание документа, подтверждающего личность иностранца, носит технический характер (один из способов удостоверения личности при легитимации), не меняя прав или обязанностей иностранцев."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":8784,"output_tokens":149,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12415910','2026-10-20T18:03:31+00:00');
INSERT INTO "analysis_memo" VALUES('49972dc27dc42b8b236390119727a6b42939b1b244b7316fa66ed8da6cbb7f10','{"triage":{"affects_foreigners":false,"confidence":0.85,"rationale":"Проект касается цифровизации гражданского процесса (электронные акты, портал информационный, верификация статуса профессиональных участников процесса), упоминание ''prawnika zagranicznego'' лишь как категории профессионального статуса, не затрагивает права или процедуры для иностранцев как таковых."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":7629,"output_tokens":131,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12415901','2026-10-20T18:03:34+00:00');
INSERT INTO "analysis_memo" VALUES('426588e7336be42fffdc392b5548b8a6bac3d7b752eb67e030a35206069ed30f','{"triage":{"affects_foreigners":true,"confidence":0.6,"rationale":"Законопроект в основном касается автоматического продления права на пособие 800+ для граждан, но также уточняет правила для «опекуна ребёнка, назначенного властями страны происхождения» и ссылается на закон о помощи гражданам Украины, что может затрагивать иностранцев.»}.text()} ,"},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":5469,"output_tokens":256,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/35455/2026','2026-10-21T18:09:07+00:00');
INSERT INTO "analysis_memo" VALUES('7aaf0785b1de83e5ece46e1d543952856cc02603825fb1c1bd6ac1bd1195805e','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила пособия 800+: ZUS сам будет продлевать право на выплату на следующий год без ежегодной заявки, если ситуация семьи не изменилась. Расширяется круг получателей за счёт лиц, которым суд передал текущую опеку над ребёнком.","key_changes":["ZUS автоматически продляет право на 800+ на следующий период при наличии права на 31 мая","Новые получатели: лица с текущей опекой над ребёнком по решению польского суда","При изменении ситуации (в т.ч. выезд за границу) сохраняется обязанность сообщать в ZUS","Данные заявлений через банки и e‑системы можно хранить до 10 лет для рекламаций","Уточняются правила при одновременных заявках двух опекунов и при смерти опекуна"],"affected_groups":["иностранные родители с правом на świadczenie wychowawcze (800+)","иностранные опекуны детей по решению польского суда","иностранцы, являющиеся опекунами детей, указанных властями страны происхождения"],"practical_impact":"Иностранным семьям, уже получающим 800+, не придётся каждый год подавать новый электронный заявлений – ZUS сам продлит право, если нет изменений. Нужно внимательно сообщать ZUS о переезде за границу, смене состава семьи или опекуна, иначе могут возникнуть переплаты или отказ.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования, за исключением art. 1 pkt 4 lit. a, pkt 5, pkt 9 lit. a и pkt 10–13 и art. 3, которые вступают в силу 1 февраля 2027 г.","confidence":0.94,"rationale":"Проект меняет правила назначения и продления семейного пособия 800+, которое доступно не только гражданам Польши, поэтому это социально важное изменение для иностранцев с детьми.","mnemonic_candidate":"Автопродление 800 плюс","mnemonic_fallback":"Автопродление пособия 800+","mnemonic_basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":42107,"truncated":false,"text_source":"pdf","created_at":"2026-10-21T18:29:51Z","input_tokens":15180,"output_tokens":1164,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35455-2026/$file/10-RPW-35455-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:22527ae36364ed66a6d55811671abc768d7227a14a181b8cdb67ec956852a927","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35455-2026/$file/10-RPW-35455-2026.pdf","members":[],"container_sha256":"0d783f9c2ae9a82ab1244bd0fcd82b49a235c9f4ab6c55bb07518045e10dc201","sha256":"0d783f9c2ae9a82ab1244bd0fcd82b49a235c9f4ab6c55bb07518045e10dc201","role":"bill","text":"","pages":62,"page_start":1,"page_end":62,"text_start":0,"text_end":110930,"text_sha256":"6af140db547368b6707230a94bbacfad1ad81815218d3de5f7a30af34236c021","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35455-2026/$file/10-RPW-35455-2026.pdf","text_sha256":"6af140db547368b6707230a94bbacfad1ad81815218d3de5f7a30af34236c021","block_id":"part:0","start":0,"end":852,"quote":"tel. +48 (22) 694 75 00 Al. Ujazdowskie 1/3; 00-583\ndkpl@kprm.gov.pl Warszawa\ngov.pl/premier\nDonald Tusk\n\nWarszawa, dnia /elektroniczny znacznik czasu/\n\nRM-0610-171-26\nUDER106\nderegulacja\npriorytet\n\nPan Włodzimierz CZARZASTY\nMarszałek Sejmu\n\nSzanowny Panie Marszałku,\n\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam Sejmowi\nprojekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci.\nProjekt ma charakter deregulacyjny oraz realizuje priorytet polityki Rady Ministrów.\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac parlamentarnych został\nupoważniony Minister Rodziny, Pracy i Polityki Społecznej.\n\nZ poważaniem\nDonald Tusk\n/podpisano kwalifikowanym podpisem elektronicznym/\n\nDo wiadomości:\nwnioskodawca \fProjekt\nU S T A W A\nz dnia\no zmianie ustawy o pomocy państwa w wychowywaniu dzieci\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":110930,"page_start":1,"page_end":62,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":110930,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"999ce52066a39797c962ae92213be3badd8b8f6c71116489e60d9040b94bbb7c"},"law_sha256":"law-v2:d83673b42b2f9050ba6a6fd9c844cfb417f84b6296f185c3820ff266c9006c2b","source_checked_at":"2026-10-21T18:29:51Z"}',10,'RPW/35455/2026','2026-10-21T18:29:51+00:00');
INSERT INTO "analysis_memo" VALUES('cf4c167f67585e578404d1de7e40e3b70245872eab258a4b1f8d1622d2827c0b','{"amendments":{"summary":"Документ комиссии не описывает содержание поправок Сената, а лишь рекомендует Сейму принять все 35 поправок к закону об личной ассистенции лиц с инвалидностью. Неясно, изменяют ли эти поправки объём прав или условия доступа к услуге для иностранцев.\n","changes":["Комиссия Polityki Społecznej i Rodziny рекомендует принять все 35 поправок Сената к закону.","Часть поправок предлагается голосовать совместно с другими (10 с 14; 13 с 15 и 28; 23 с 26; 24 с 29; 31 с 35).","Текст спrawozdania не содержит описания содержания поправок и их материальных последствий."],"affects_foreigners":false,"confidence":0.23,"source_evidence":{"subject":"Sprawozdanie Komisji Polityki Społecznej i Rodziny o uchwale Senatu w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami","adopted_on":"2026-10-21","decision":"amendments","complete":true,"resolution_page":null,"amendment_pages":[],"amendment_quote":"Komisja Polityki Społecznej i Rodziny ... wnosi: Wysoki Sejm raczy poprawki Senatu zawarte w: pkt 1 – przyjąć ... pkt 35 – przyjąć."}},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"","source_kind":"committee_amendments","created_at":"2026-10-21T18:29:52Z","input_tokens":1798,"output_tokens":1479,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'1929','2026-10-21T18:53:58+00:00');
INSERT INTO "analysis_memo" VALUES('a930410df593393404c7fc1b3a578c158dc9f8dec87d61bc0d4f8d4041e7e30f','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Закон вводит общий режим санкций ЕС и польских «środki ograniczające», в т.ч. за вмешательство и манипуляцию информацией против безопасности Польши. Для иностранцев важно, что включение в санкционный список МВД автоматически ведёт к занесению в реестр нежелательных лиц и отказу во въезде, визе и ВНЖ.","key_changes":["Единый порядок применения санкций ЕС и польских «środki ograniczające».","Новое основание санкций — вмешательство и манипуляция информацией.","Внесение в санкционный список МВД ведёт к записи в wykaz cudzoziemców.","Запись в wykaz — новое основание отказа во въезде, визе и виде на жительство.","За помощь въезду лица под санкциями предусмотрена уголовная ответственность."],"affected_groups":["иностранцы, попавшие в санкционный список МВД","иностранцы, которым могут отказать во въезде, визе или ВНЖ из‑за санкций","иностранные работники компаний, попавших под санкции"],"practical_impact":"Если иностранец будет включён в польский санкционный список, его автоматически внесут в реестр нежелательных лиц, что повлечёт запрет въезда и отказы в визе и виде на жительство; обжалование возможно только в административном суде, при этом данные списка будут публичны. Работники санкционированных работодателей (включая иностранцев) смогут требовать выплату задолженной зарплаты из FGŚP.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования, за исключением ст. 73, которая вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.9,"rationale":"Акт прямо меняет ustawę o cudzoziemcach, делая санкционный список основанием для внесения в реестр нежелательных иностранцев и отказа во въезде, визе и ВНЖ, поэтому это ключевое регулирование легализации пребывания.","mnemonic_candidate":"Санкционный въездной барьер","mnemonic_fallback":"Санкционный запрет на въезд","mnemonic_basis":"Иностранец, внесённый в санкционный список МВД, автоматически попадает в wykaz cudzoziemców, których pobyt jest niepożądany, что влечёт запрет въезда и негативные визово‑миграционные решения.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":3453,"truncated":false,"text_source":"scan","created_at":"2026-10-21T18:29:53Z","input_tokens":46600,"output_tokens":5656,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3251/3251.pdf","source_kind":"committee_report","revision":2,"text_sha256":"07df84716fdb16a3e27e382699ddff8cc3f0ab167334031ea4c64459c4bfdf7a","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3251/3251.pdf","members":[],"container_sha256":"","sha256":"07df84716fdb16a3e27e382699ddff8cc3f0ab167334031ea4c64459c4bfdf7a","role":"unknown","text":"","pages":69,"page_start":1,"page_end":69,"text_start":0,"text_end":null,"text_sha256":"","losses":["text unavailable; sent as PDF pages"]}],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":"2026-10-21T18:29:53Z"}',10,'3003','2026-10-21T18:29:53+00:00');
INSERT INTO "analysis_memo" VALUES('30525322658ec31987cc604da5eec64d3fa59b3b65492cbd0ac4b58d964b76a5','{"amendments":{"summary":"Комиссия предлагает принять лишь часть поправок: они уточняют новые ограничения по занятости и оплате труда медработников, а также действие переходных норм. Более радикальные изменения (повышение гарантированного финансирования, иная формула расчёта лимитов вознаграждений, расширение их на услуги вне договоров с NFZ) комиссия рекомендует отклонить.","changes":["Время дежурства вне медучреждения и на дому не войдёт в общий лимит занятости медиков.","Стационар и приём в больничной поликлинике должны вести медики с нагрузкой не менее 0,5 ставки.","Из этого требования выведены дежурства, работа вне обычных часов и услуги гериатров, патоморфологов, психиатров.","Процедура второй работы: при кадровом дефиците работодатель сперва предлагает поднять ставку, затем решает о согласии/увольнении.","Льготные лимиты оплаты в трансплантологии уточнены: касаются операций по изъятию и пересадке органов.","Нормы распространены и на служебные/иные отношения; часть переходных правил ст. 4 изменена или исключена, конфликтующие коллективные нормы действуют лишь в несопротиворечащей части."],"affects_foreigners":false,"confidence":0.73,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"","source_kind":"committee_amendments","created_at":"2026-10-21T18:29:54Z","input_tokens":6834,"output_tokens":3506,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3157','2026-10-21T18:54:01+00:00');
INSERT INTO "analysis_memo" VALUES('e1bc4411da83c854e6478a0fa342600ba089db18ed4464590b8b70a2691a9693','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит в Польше систему ETIAS: гражданам безвизовых стран понадобится электронное разрешение на поездку, иначе могут отказать во въезде и в легализации пребывания. Создаётся единый Krajowy Rejestr Cudzoziemców с главным идентификатором для всех ведомств.","key_changes":["Обязательное разрешение ETIAS для въезда и всего периода безвизового пребывания, связанное с подачей на ВНЖ/ПМЖ/резидента ЕС","Без действующего ETIAS могут отказать во въезде, продлении безвиза и принять решение о возврате из Польши","Повторное рассмотрение отказа/отмены ETIAS: 7 дней, только онлайн, платно; размер пошлины установят в диапазоне, а не фиксировано","Создаётся Krajowy Rejestr Cudzoziemców и присваивается GIC – единый идентификатор иностранца, которым пользуются UdSC, ZUS, органы работы, вузы и др.","Пошлина 350 zł за отмену запрета въезда; повышаются визовые сборы (45/90 евро и 135/180 евро в указанных категориях)"],"affected_groups":["Граждане безвизовых стран, въезжающие в Польшу/Шенген","Иностранцы, находящиеся в Польше по безвизу и подающие на ВНЖ, ПМЖ, резидента ЕС","Иностранцы с польскими визами и картами pobytu","Иностранцы, работающие в Польше по разрешениям на работу, сезонной работе и по заявлениям о powierzeniu pracy","Лица с запретом въезда в Польшу/Шенген, данные которых вносятся в реестры"],"practical_impact":"Перед поездкой без визы придётся заранее оформить онлайн‑разрешение ETIAS и следить за его сроком, иначе не впустят в Польшу и не примут многие заявления на легализацию. Обжалование отказа по ETIAS возможно только электронно, в жёсткий 7‑дневный срок и с платой; данные иностранцев будут сведены в единый реестр, что упростит проверку, но усилит контроль и обмен информацией между ведомствами.","effective_date":"Закон вступает в силу в день, указанный в решении Европейской комиссии на основании ст. 88 ч. 1 регламента (ЕС) 2018/1240, за исключением части технических и переходных положений, которые начнут действовать через 14 дней после опубликования.","confidence":0.93,"rationale":"Проект напрямую привязывает электронное разрешение ETIAS к праву въезда и законности пребывания, широко меняет ustawę o cudzoziemcach и создаёт единый реестр иностранцев, что делает его ключевым актом о миграционном статусе.","mnemonic_candidate":"Пропуск ETIAS","mnemonic_fallback":"Закон о системе ETIAS","mnemonic_basis":"Проект вводит обязательное электронное разрешение ETIAS для безвизовых иностранцев и связывает его наличие с въездом, пребыванием и подачей заявлений на ВНЖ/ПМЖ в Польше.","mnemonic_language":"ru","changes_since_previous":["Размер пошлины за повторное рассмотрение дела по ETIAS больше не фиксирован в 200 zł: в проекте предусмотрено, что её точное значение установят в регламенте МВД в диапазоне от 100 zł до 6,54% средней зарплаты."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":134180,"truncated":false,"text_source":"documents","created_at":"2026-10-21T18:50:51Z","input_tokens":52184,"output_tokens":3305,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","source_kind":"rcl","revision":3,"text_sha256":"text-v2:2d99dcb260ddf31b4e17d6400164b0a97ba7aa76be5ebf50dcb8d3aa40cd096f","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":["rcl/12400563/stage/13146411","KP2 - MSWiA - PROJEKT PO KOMISJI PRAWNICZEJ.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","members":[],"container_sha256":"22edc0d40591f58922c6cdc9f9652c804a333d855fd02de1797f3136c10c2718","sha256":"22edc0d40591f58922c6cdc9f9652c804a333d855fd02de1797f3136c10c2718","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":134181,"t