CX"],"container_sha256":"37be7c0c11d763035eee006196414daf9f8176b7ab848874b4318b78389aed54","sha256":"77abbbf39b02f1abcbd54e33df35650bdb6a1471b2ea0e000b1b26f92c214533","role":"unknown","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":62302,"text_sha256":"5bae251627e4f238cb94b49c4aa5d4c764b3f81d4e288ccdc9ed721bcdd2af84","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12400563/stage/13146411","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","block_id":"part:0","start":0,"end":1576,"quote":"Projekt z dnia 29 września 2026 r.\nEtap: po komisji prawniczej\nUSTAWA\nz dnia <data wydania aktu> r.\no udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) [przypis 2: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 12 października 1990 r. o Straży Granicznej, ustawę z dnia 24 maja 2000 r. o Krajowym Rejestrze Karnym, ustawę z dnia 13 czerwca 2003 r. o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej, ustawę z dnia 14 lipca 2006 r. o wjeździe na terytorium Rzeczypospolitej Polskiej, pobycie oraz wyjeździe z tego terytorium obywateli państw członkowskich Unii Europejskiej i członków ich rodzin, ustawę z dnia 16 listopada 2006 r. o opłacie skarbowej, ustawę z dnia 24 sierpnia 2007 r. o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym, ustawę z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, ustawę z dnia 2 kwietnia 2009 r. o obywatelstwie polskim, ustawę z dnia 12 grudnia 2013 r. o cudzoziemcach, ustawę z dnia 25 czerwca 2015 r. – Prawo konsularne, ustawę z dnia 20 marca 2025 r. o rynku pracy i służbach zatrudnienia, ustawę z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej, ustawę z dnia 13 lutego 2026 r. o zmianie ustawy o Krajowym Rejestrze Karnym oraz niektórych innych ustaw oraz ustawę z dnia 15 maja 2026 r. o udziale Rzeczypospolitej Polskiej w systemie Eurodac.] )\nRozdział 1\nPrzepisy ogólne\nArt. 1"},{"kind":"draft_date","value":"2026-09-29","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","block_id":"part:0","start":0,"end":31,"quote":"Projekt z dnia 29 września 2026"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":134181,"page_start":null,"page_end":null,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":134181,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"53415ee5c621f32188c54ba23135f5c7363f6f3ac945e4d28572e6fa03173276"},"law_sha256":"law-v2:f56b59c9b3e30f001b85337344eafb7befdafd15e8a976d62bb3bab41f082fa9","source_checked_at":"2026-10-21T18:50:51Z"}',10,'RCL/12400563','2026-10-21T18:50:51+00:00');
INSERT INTO "analysis_memo" VALUES('bdd7edf6de33874766cf3d1fae699f3f1ec3e78010819bdbf1e92d5dc6f047cc','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет работу реестра PESEL, актов гражданского состояния и паспортного реестра. Иностранцам сложнее получить PESEL только ради профиля zaufany, в PESEL добавят данные о типе проездного документа и упростят выписку из адреса.","key_changes":["Нельзя будет просить PESEL только из‑за требования для профиля zaufany","В реестре PESEL появится тип проездного документа/удостоверения личности иностранца","Выписаться и заявить выезд за границу можно будет в любой гмине, а не только по месту жительства","Снять зastrzeżenie номера PESEL сможет представитель по адвокатской или нотариальной доверенности","Возврат к добрачной фамилии после развода можно будет оформить онлайн через USC"],"affected_groups":["Иностранцы, получающие или уже имеющие номер PESEL","Иностранцы, обращающиеся за profil zaufany через консульства","Иностранцы, снимающиеся с регистрации по месту жительства или выезжающие из Польши","Разведённые иностранцы, чей брак зарегистрирован в Польше"],"practical_impact":"Иностранцы вне Польши не смогут получить PESEL, ссылаясь лишь на необходимость профиля zaufany; нужен иной правовой повод (пребывание, работа, налоги и т.п.). В базе PESEL будет храниться тип вашего проездного документа, проще подать заявление о выписке в любой гмине и через представителя разблокировать PESEL.","effective_date":"Закон вступит в силу через 14 дней после опубликования, кроме ст. 1, ст. 2 пп. 1, 2, 10 и 11 и ст. 3, которые вступят в силу 1 февраля 2028 г.","confidence":0.88,"rationale":"Проект явно меняет правила присвоения и использования PESEL и связанных услуг (meldunek, данные документов), важные для иностранцев, но не затрагивает напрямую легализацию пребывания, поэтому это социальная сфера средней важности (3).","mnemonic_candidate":"PESEL только при связи","mnemonic_fallback":"Изменения PESEL и реестров","mnemonic_basis":"Проект прямо исключает возможность просить PESEL лишь ради профиля zaufany и подчёркивает, что номер должен даваться лицам, имеющим связь с Польшей, одновременно расширяя данные и услуги в реестрах.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":41393,"truncated":false,"text_source":"documents","created_at":"2026-10-21T18:50:51Z","input_tokens":15154,"output_tokens":2022,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","source_kind":"rcl","revision":2,"text_sha256":"text-v2:af89cf71126263629e7d5155c327939bce49eae1b7c2dc1f14cb8a78952c4f96","selection":{"question":"bill_text","state":"selected","belonging":[],"role":[],"version":["rcl/12405805/stage/13179001","KP - MC - projekt ustawy, uzasadnienie w tym OSR.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","members":[],"container_sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":41394,"text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","members":[],"container_sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":41394,"text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178996/13178997/dokument791976.zip","members":["SKRM_SRP_UD337 