al do raportu tabela uwag konsultacje.docx"],"container_sha256":"d807fe9ccccdd9866ab1b2b80e35273f2b91db4b909ef1d1910054eecd31c987","sha256":"967b1ca1f97c0c2e18c2d6add401c2064f5957c26b255e1671b025fc4e5e6e63","role":"unknown","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":5309,"text_sha256":"09b804a4dff7017aa173e47bd6b96b4587e6cc9319ddaf6d3fe73843ea16a8f2","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178996/13178997/dokument791976.zip","members":["SKRM_SRP_UD337 - zal do raportu tabela uwag opiniowanie.docx"],"container_sha256":"d807fe9ccccdd9866ab1b2b80e35273f2b91db4b909ef1d1910054eecd31c987","sha256":"eb8af6e011207ad753d4ed3886551eee5b8c608cb90675b5ad29c89a5e3a889b","role":"unknown","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":29208,"text_sha256":"cdf4c8d1141a21b65d8eed7d37a206a99bdb26e9b39d7a3a73a5cdf24a02fb08","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12405805/stage/13179001","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":0,"end":506,"quote":"Projekt z dnia 22 września 2026 r.\nUSTAWA\nz dnia … 2026 r.\no zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych [przypis 1: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 25 lutego 1964 r. – Kodeks rodzinny i opiekuńczy, ustawę z dnia 24 września 2010 r. o ewidencji ludności, ustawę z dnia 28 listopada 2014 r. – Prawo o aktach stanu cywilnego oraz ustawę z dnia 27 stycznia 2022 r. o dokumentach paszportowych.] ) \nArt. 1"},{"kind":"draft_date","value":"2026-09-22","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":0,"end":31,"quote":"Projekt z dnia 22 września 2026"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":7144,"end":7166,"quote":"Ustawa wchodzi w życie"}],"limitations":[],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":41394,"page_start":null,"page_end":null,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":41394,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"4ea49e8f91006dfc77d766c940626a7a5054c89346b023b92cc7339cf4f65a88"},"law_sha256":"law-v2:263a0df106d7a25988ed2cc28e61224b078eee31b91e61e99b8c2b5451c4ce48","source_checked_at":"2026-10-21T18:50:51Z"}',10,'RCL/12405805','2026-10-21T18:50:51+00:00');
INSERT INTO "analysis_memo" VALUES('b422e06c39d9fab7073f910b66ce11172192698d3b189343fa96fd7f073a4eec','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет систему налоговых льгот для новых инвестиций (Polska Strefa Inwestycji) и переводит заявки в электронный формат. Одновременно отменяется ст. 3a в законе о покупке недвижимости иностранцами, что изменит условия сделок для нерезидентов.","key_changes":["Отменяется ст. 3a в законе о покупке недвижимости иностранцами.","Перестраиваются налоговые льготы PSI и расчёт льготного дохода.","Вводится подача заявок на поддержку инвестиций только через e‑систему.","Уточняются налоговые и соцссылки на доходы, льготируемые в PSI."],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранные инвесторы и компании, использующие PSI","иностранные предприниматели, у которых доходы подпадают под льготы PSI"],"practical_impact":"Иностранцам, планирующим покупку недвижимости, придётся учитывать новые правила вместо ст. 3a, влияющие на необходимость разрешений и условия сделки. Иностранным бизнесам с поддержкой PSI нужно будет адаптировать налоговое планирование к новым правилам расчёта льготного дохода.","effective_date":"Основные изменения вступают в силу 1 января 2027 г., а отмена ст. 3a в законе о покупке недвижимости иностранцами – 31 декабря 2027 г.","confidence":0.86,"rationale":"Закон прямо изменяет регулирование сделок с недвижимостью для «cudzoziemcy» и косвенно влияет на иностранные инвесторы через налоговые льготы PSI, но не затрагивает легализацию пребывания или доступа к рынку труда.","mnemonic_candidate":"Сделки без 3a","mnemonic_fallback":"Отмена ст. 3a о недвижимости","mnemonic_basis":"Текст проекта прямо предусматривает отмену ст. 3a в законе о nabywaniu nieruchomości przez cudzoziemców, что меняет режим покупки недвижимости иностранцами.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":50033,"truncated":false,"text_source":"pdf","created_at":"2026-10-21T19:11:53Z","input_tokens":19770,"output_tokens":2332,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3243/3243.pdf","source_kind":"committee_report","revision":3,"text_sha256":"text-v2:52bb06ec7573eb34df226c6e2e060e4c399f389efe5495f0c9bbda3df2869845","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3243/3243.pdf","members":[],"container_sha256":"e796c4e395af53f69ba8fe74844172870f304d8950f89bb338c25155a49ef271","sha256":"e796c4e395af53f69ba8fe74844172870f304d8950f89bb338c25155a49ef271","role":"bill","text":"","pages":24,"page_start":1,"page_end":24,"text_start":0,"text_end":50033,"text_sha256":"9eb7f58dc22b0f049beb6fc6c5a81a078fc6561183e0bf8b7b39adf97067e1c8","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3243/3243.pdf","text_sha256":"9eb7f58dc22b0f049beb6fc6c5a81a078fc6561183e0bf8b7b39adf97067e1c8","block_id":"part:0","start":0,"end":1017,"quote":"Druk nr 3243\n\nX  kadencja\n\nS P R A W O Z D A N I E\nKOMISJI GOSPODARKI I ROZWOJU\n\no rządowym projekcie ustawy  o zmianie ustawy\no wspieraniu nowych inwestycji oraz niektórych\ninnych ustaw (druk nr 3160)\n\nSejm na 66. posiedzeniu w dniu 8 października 2026 r., zgodnie z art. 39 ust . 2 regulaminu\nSejmu skierował powyższy projekt ustawy do Komisji Gospodarki i Rozwoju  w celu\nrozpatrzenia.\n\nKomisja Gospodarki i Rozwoju po roz patrzeniu powyższego projektu ustawy na\nposiedzeniu w dniu 21 października 2026 r.\n\nwnosi:\n\nW y s o k i  S e j m  uchwalić raczy załączony projekt ustawy.\n\nWarszawa, dnia 21 października 2026 r.\n\nSprawozdawca\n\n(-) Jerzy Meysztowicz\nPrzewodniczący Komisji\n\n(-) Rafał Komarewicz\n\n Tłoczono z polecenia Marszałka Sejmu Rzeczypospolitej Polskiej\n\nSEJM\nRZECZYPOSPOLITEJ POLSKIE J \fLiczba stron :  23     Data :   2026-10-21      Nazwa pliku :   V6_2037-1.NK   1\nX kadencja/druk nr 3160\nProjekt\nU S T AWA\nz dnia\no zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw1)\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":50033,"page_start":1,"page_end":24,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":50033,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"b435fedf4e7aedd8ffa699c9d347c261d31d715cfc266dcbcb00790a0cb6ec09"},"law_sha256":"law-v2:368989bd7e27e754dc3a1eb79a0300fa2c27207ef2fa4602bf9a9f431692e15b","source_checked_at":"2026-10-21T19:11:53Z"}',10,'3160','2026-10-21T19:11:53+00:00');
INSERT INTO "analysis_memo" VALUES('89d8022a6cb015f25d46af5f445bc1740ca862b722b86e1fe68933abd2fd80c7','{"amendments":{"summary":"Документ не содержит содержания поправок, только указывает, что комиссия Sejmu рекомендует принять все poprawki Senatu do ustawy o asystencji osobistej osób z niepełnosprawnościami. Часть поправок предлагается голосовать совместно пакетами.","changes":["Комиссия Sejmu рекомендует принять все 35 поправок Senatu к закону","Часть поправок должна голосоваться совместно (напр. 10 с 14, 13 с 15 и 28)","Совместное голосование также предусмотрено для пакетов 23–26, 24–29 и 31–35"],"affects_foreigners":false,"confidence":0.15,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf","source_kind":"committee_amendments","created_at":"2026-10-21T20:55:57Z","input_tokens":134,"output_tokens":709,"cache_read_input_tokens":1664,"cache_creation_input_tokens":0}',10,'1929','2026-10-21T20:55:57+00:00');
INSERT INTO "analysis_memo" VALUES('5605fbe17f440940a5ea95bd179f5d7e391493f63b67f41d03697e8a42da7c03','{"amendments":{"summary":"Поправки Сената расширяют помощь при подаче заявлений, делают использование часов асистенции гибче, вводят новые реестры, переходные правила для ассистентов и уточняют финансирование и процедуры. Komisja Polityki Społecznej i Rodziny рекомендует Сейму все поправки Сената принять без изменений.","changes":["Расширяется помощь ZUS и повята при подаче, дополнении и исправлении заявлений и просьб о повторном рассмотрении.","Неиспользованные часы асистенции можно переносить в другие месяцы того же года, но запас не выше двукратной месячной нормы.","Создаётся реестр получателей асистенции в программах Fundusz Solidarnościowy с данными PESEL или номера документа.","Лицо, получающее асистенцию до 18 лет, сможет просить оценку уровня нуждаемости уже после достижения 16 лет.","До конца 2029 г. ассистентом может быть и человек без требуемых квалификаций, если его выбрал пользователь или он учится.","Уточнены правила замены ассистента при его отсутствии и введена возможность индексации почасовых ставок решением Rady Ministrów."],"affects_foreigners":true,"confidence":0.86,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3213/3213-uchwa%C5%82a.docx","source_kind":"senate_amendments","created_at":"2026-10-21T21:37:51Z","input_tokens":14035,"output_tokens":3866,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'1929','2026-10-21T21:37:51+00:00');
INSERT INTO "analysis_memo" VALUES('008afea795c5fb3c64e50ca5abc7862b6bf5d786f506e4d258fc3a53d6c5e132','{"proposal":{"name":"Онлайн реестр сделок","fallback":"Электронный реестр уведомлений","basis":"Проект переводит уведомление МВД о сделках иностранцев с недвижимостью в электронный реестр CREWAN через нотариусов."},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","created_at":"2026-10-22T08:26:57Z","input_tokens":561,"output_tokens":336,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'2699','2026-10-22T08:36:24+00:00');
INSERT INTO "analysis_memo" VALUES('075869b931689e566fa5fd45d7263378558ca2c0fd5dafb5a0459895334dc782','{"proposal":{"name":"Гражданство 10 лет","fallback":"Признание гражданства 10 лет","basis":"Проект увеличивает минимальный срок непрерывного проживания для признания гражданства с 3 до 10 лет."},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","created_at":"2026-10-22T08:26:57Z","input_tokens":563,"output_tokens":288,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'1759','2026-10-22T08:36:24+00:00');
INSERT INTO "analysis_memo" VALUES('0dd1f1c8e141bc42eb324621fb4d0194135b6677462eff6cf75e6d7011b74773','{"proposal":{"name":"Страны без разрешения","fallback":"Освобождение от разрешения","basis":"Проект даёт Совету министров право освобождать граждан отдельных стран от требования иметь разрешение на работу в Польше."},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","created_at":"2026-10-22T08:26:57Z","input_tokens":624,"output_tokens":546,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RCL/12412403','2026-10-22T08:36:24+00:00');
INSERT INTO "analysis_memo" VALUES('0ff4ac0d3e6c78f2de12bf6be632f89fa1fbdf009823a43684ac32990bd84e20','{"proposal":{"name":"Барьер доплаты ZUS","fallback":"Порог доплаты до минимальной пенсии","basis":"Проект вводит высокий порог накопленных взносов для получения доплаты пенсии до минимальной из ZUS, что особенно затронет иностранцев с коротким стажем работы в Польше."},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","created_at":"2026-10-22T08:26:57Z","input_tokens":586,"output_tokens":334,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3205','2026-10-22T08:36:24+00:00');
