INSERT INTO "analysis_memo" VALUES('2f4bb69b55c645413d8d8f40059932174fdf656550808e3cfeb3a1d337294076','{"amendments":{"summary":"Поправки дорабатывают регулирование спецтранспорта Agencji Frontex и исключают один блок изменений (art.9); комиссия рекомендует принять только поправки KO (9–10 и 12), а все поправки KP PiS (1–8 и 11) об удалении частей проекта – отклонить.\nВ результате ключевые положения о сотрудничестве со Strażą Graniczną и об участии Frontex остаются в правительственной редакции, лишь технически уточняется режим для транспортных средств агентства.","changes":["В art.66 добавляется прямое упоминание Agencji Frontex в перечне субъектов, для чьего спецтранспорта задаются техтребования","Вводится новый ust.7a art.66: министр внутренних дел с минтрансом будет в регламенте определять техусловия спецтранспорта Agencji Frontex","Расширяется отсылка в art.66 ust.8 так, чтобы она охватывала также новый ust.7a о транспорте Agencji Frontex","Изменения в art.4 перегруппированы: правка art.66 выделена в отдельный pkt 3a вместо прежнего включения в pkt 3","Полностью исключается art.9 проекта (один из блоков изменений в другом законе)","Поправки KP PiS об удалении отдельных подпунктов и целых статей (1–8,11) отклонены, правительственный текст там не меняется"],"affects_foreigners":false,"confidence":0.62,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"","source_kind":"committee_amendments","created_at":"2026-10-22T18:13:48Z","input_tokens":2221,"output_tokens":3298,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3146','2026-10-22T18:17:41+00:00');
INSERT INTO "analysis_memo" VALUES('89f703fb9830e39bd7ea5cc3140dce9d2b369c6857a5c6022cbb036e819ac1c4','{"amendments":{"summary":"Поправки, внесённые клубом KP PSL, расширяют перечень целей поддержки инвестиций, смягчают новое правило по снижению занятости и меняют переходные нормы для уже начатых дел, а также вычеркивают несколько пунктов и статей проекта. Комиссия Gospodarki i Rozwoju рекомендует Сейму все эти поправки отклонить.","changes":["Добавляется цель поддержки: помощь предпринимателям в доступе к энергии, особенно из возобновляемых источников.","Из одной нормы убираются ссылки на spółka komandytowa и spółka komandytowo‑akcyjna.","Предлагается вычеркнуть два пункта изменений в основной статье, изменяющей базовый закон.","Предлагается полностью удалить из проекта статьи 16 и 23.","Снижение занятости: не более 20% от среднего за 12 мес. до заявки, с исключением на случаи ошибки.","Переходные нормы: для незавершённых и части старых дел о поддержке инвестиций уточняется, какие старые правила применять."],"affects_foreigners":false,"confidence":0.63,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"","source_kind":"committee_amendments","created_at":"2026-10-22T18:13:48Z","input_tokens":2065,"output_tokens":3145,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'3160','2026-10-22T18:17:45+00:00');
