INSERT INTO "analysis_memo" VALUES('0ca8b995d78b3d698bc4a5035feb6c9fa2cfdf18c1fbf6a0d9783be2d8fb9de2','{"triage":{"affects_foreigners":false,"confidence":0.75,"rationale":"Законопроект лишь продлевает срок действия подзаконного акта о порядке предоставления информации из Национального реестра судимостей до запуска системы ECRIS-TCN и носит чисто технический, процедурный характер, не меняя прав, обязанностей или процедур для иностранцев напрямую."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":6581,"output_tokens":132,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/35783/2026','2026-10-23T17:57:06+00:00');
INSERT INTO "analysis_memo" VALUES('617ea3a1573b7fcfa793c398bb6f5672733d1df52f249408115316273507a43c','{"triage":{"affects_foreigners":true,"confidence":0.95,"rationale":"Проект прямо вносит изменения в ustawę o cudzoziemcach, вводя новые основания для обязательства покинуть страну, запрет на повторный въезд и внесение в реестр нежелательных иностранцев для лиц, осуждённых за пропаганду идеологии OUN-B/UPA или отрицание этого геноцида."},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_tokens":13504,"output_tokens":146,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',10,'RPW/35640/2026','2026-10-23T17:57:08+00:00');
INSERT INTO "analysis_memo" VALUES('3ba785b173ff872fea93ba69d19f4f2d41764471edd908dda221dbe569e6d60c','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект продлевает действие текущих правил выдачи сведений из Krajowy Rejestr Karny, чтобы не было перерыва до запуска системы ECRIS‑TCN. Для людей, которым нужна справка о несудимости, порядок останется таким же дольше.","key_changes":["Исключается ссылка на art. 21 из переходного положения прежней новелизации KRK","Вводится новое правило: старое распоряжение действует до nowych przepisów, но максимум 24 месяца","До запуска ECRIS‑TCN информация из KRK выдается по нынешним процедурам","Избегается период, когда справки из KRK нельзя было бы выдавать из‑за отсутствия акта","Не меняется содержание справок, только срок действия старых процедур"],"affected_groups":["все, кто запрашивает справку из Krajowy Rejestr Karny (в т.ч. иностранцы)","работодатели и организации, требующие справку о несудимости","иностранцы – граждане третьих стран, чьи данные есть в KRK"],"practical_impact":"Порядок получения справки о несудимости из Krajowy Rejestr Karny останется прежним ещё до 24 месяцев после вступления этих поправок. Новые, связаныe с ECRIS‑TCN, процедуры начнут действовать позже, без «провала» в доступе к справкам.","effective_date":"Закон вступает в силу по истечении 14 дней со дня его официального объявления.","confidence":0.86,"rationale":"Проект лишь продлевает действие подзаконных правил выдачи справок из KRK, затрагивая иностранцев косвенно через порядок получения этих справок, поэтому категория «indirect» и важность 2.","mnemonic_candidate":"Продление справки KRK","mnemonic_fallback":"Продление регламента KRK","mnemonic_basis":"Проект прямо продлевает срок действия распоряжения 2015 г. о выдаче информации из Krajowy Rejestr Karny до появления нового акта, связанного с ECRIS‑TCN.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":25183,"truncated":true,"text_source":"pdf","created_at":"2026-10-23T18:21:00Z","input_tokens":9949,"output_tokens":1654,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35783-2026/$file/10-RPW-35783-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:8482705eb3aaeec60d599b411490eb67a310a425ad38bc8f499b2665e5314b92","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35783-2026/$file/10-RPW-35783-2026.pdf","members":[],"container_sha256":"f1399ebb12e6887b8c316c8130ed0fff3f319905d8880be3a746089954f6fa36","sha256":"f1399ebb12e6887b8c316c8130ed0fff3f319905d8880be3a746089954f6fa36","role":"bill","text":"","pages":20,"page_start":1,"page_end":20,"text_start":0,"text_end":25183,"text_sha256":"47f9079a689e09fe22a9cbb072154a48568c848b09d1d7a640749aea6adffb02","losses":["text page coverage differs from the PDF page count"]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35783-2026/$file/10-RPW-35783-2026.pdf","text_sha256":"47f9079a689e09fe22a9cbb072154a48568c848b09d1d7a640749aea6adffb02","block_id":"part:0","start":0,"end":128,"quote":"Projekt\nU S T A W A\nz dnia …\nzmieniająca ustawę o zmianie ustawy o Krajowym Rejestrze Karnym oraz niektórych\ninnych ustaw\nArt. 1"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":25183,"page_start":1,"page_end":20,"losses":["text page coverage differs from the PDF page count"]},{"part_index":0,"stage":"analysis","start":0,"end":25183,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"88e6e613863a8a956f580d9b2409421cacb9c08faf6b4f4d73f9a0a07c9c5c15"},"law_sha256":"law-v2:bd4d237b4cd4adba7dfeedd12718a0788eb76bd26fcea3bb1ce0857dd2d00f61","source_checked_at":"2026-10-23T18:21:00Z"}',10,'RPW/35783/2026','2026-10-23T18:21:00+00:00');
INSERT INTO "analysis_memo" VALUES('d1bc89747dc9761a422eb8fa921208211a3a296d99ab66a81aad2636dea3517d','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит уголовную ответственность за публичную пропаганду идеологии и символики ОУН‑Б и УПА, отрицание и прославление их преступлений. Для иностранцев такие действия станут отдельным основанием для решения о выдворении и многолетнем запрете въезда в Польшу.","key_changes":["Прямая криминализация идеологии и символики ОУН-Б и УПА в Kodeks karny","Кара за отрицание, похвалу и героизацию волынских преступлений в ustawa o IPN","Новые основания выдворения иностранца после приговора за такие преступления","Возможен занос иностранца в реестр нежелательных и запрет въезда до 5 лет","Запрет тратить польские госcредства (в т.ч. за рубежом) на прославление ОУН-Б/УПА"],"affected_groups":["иностранцы, публично продвигающие идеологию или символику ОУН-Б/УПА","иностранцы, отрицающие или прославляющие волынское преступление и другие описанные злодеяния","иностранные НКО и проекты, получающие польские госcредства"],"practical_impact":"Иностранец, публично прославляющий ОУН-Б/УПА или отрицающий описанные в законе преступления, может получить уголовный приговор, после чего воевода вынесет решение о выезде с запретом въезда на 3–5 лет. Даже без приговора такие действия могут привести к занесению в реестр нежелательных и запрету въезда до 5 лет, а проекты не получат польское госфинансирование.","effective_date":"Через 30 дней после опубликования, кроме норм о названиях и памятниках, которые вступают в силу через 3 месяца после опубликования.","confidence":0.93,"rationale":"Проект прямо меняет ustawę o cudzoziemcach, вводя новые основания для решения о возвращении и запрете въезда иностранцев за пропаганду идеологии ОУН-Б/УПА и отрицание или прославление связанных с ними преступлений.","mnemonic_candidate":"Депортация за УПА","mnemonic_fallback":"Выдворение за УПА","mnemonic_basis":"Проект добавляет в ustawę o cudzoziemcach отдельное основание для решения о возвращении и запрете въезда за преступления, связанные с идеологией или символикой ОУН-Б/УПА и отрицанием их зločинów.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":48328,"truncated":true,"text_source":"pdf","created_at":"2026-10-23T18:21:00Z","input_tokens":18580,"output_tokens":2016,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:ee1a33cdce683dffb0cc9c49bd99ff6619e9c2a702c9a98db0f4ef525622cfe9","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf","members":[],"container_sha256":"9a8d3709ce89cdf307d21392082f7bc25342ca86d1f22e641e9586aa8d5b66a6","sha256":"9a8d3709ce89cdf307d21392082f7bc25342ca86d1f22e641e9586aa8d5b66a6","role":"bill","text":"","pages":24,"page_start":1,"page_end":24,"text_start":0,"text_end":48328,"text_sha256":"568ace2a76b0b32ce9455786b2c186e0cd8265507ddf72260d319613b983fef7","losses":["text page coverage differs from the PDF page count"]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf","text_sha256":"568ace2a76b0b32ce9455786b2c186e0cd8265507ddf72260d319613b983fef7","block_id":"part:0","start":0,"end":181,"quote":"1\n\nProjekt\nUSTAWA\nz dnia …………………… 2026 r.\no zmianie ustawy o Instytucie Pamięci Narodowej – Komisji Ścigania Zbrodni przeciwko\nNarodowi Polskiemu oraz niektórych innych ustaw\nArt. 1"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":48328,"page_start":1,"page_end":24,"losses":["text page coverage differs from the PDF page count"]},{"part_index":0,"stage":"analysis","start":0,"end":48328,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"b113474d7b94bc20bf3b81e7ac2f238f635fc41154e574967a3b871ca87e119e"},"law_sha256":"law-v2:2ba1e1aa4180b97f67e338b498bb3be748fb0090e996fa97194c6ce4ab3de8a2","source_checked_at":"2026-10-23T18:21:00Z"}',10,'RPW/35640/2026','2026-10-23T18:21:00+00:00');
INSERT INTO "analysis_memo" VALUES('746b1ee1091ed97fc1f56b05eb857c4cba1845eea6f2c983af48a284e614c206','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект обновляет систему налоговых льгот и процедур для инвестиций в рамках Польской инвестиционной зоны (PSI) и переводит подачу заявок в электронный вид. Одновременно отменяется ст. 3a в законе о покупке недвижимости иностранцами, что изменит условия таких сделок.","key_changes":["Отменяется ст. 3a в законе о покупке недвижимости иностранцами.","Налоговая льгота PSI чётко привязана к указанной в решении деятельности и территории.","Освобождение от налога по PSI начинается после окончания инвестпроекта или начала затрат на новые рабочие места.","Заявления, жалобы и переписка по PSI подаются только через электронное индивидуальное konto.","Крупные решения о поддержке (от 40 млн zł помощи) требуют мнения Шефа KAS."],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранные инвесторы, пользующиеся поддержкой PSI","иностранные владельцы и со‑владельцы польских компаний в PSI"],"practical_impact":"Покупка недвижимости иностранцами будет регулироваться без ст. 3a, что приведёт к изменению части требований или процедуры сделок. Иностранные инвесторы в PSI столкнутся с новыми правилами расчёта налоговой льготы и обязательной электронной подачей всех документов.","effective_date":"Закон вступает в силу 1 января 2027 г., при этом ст. 2 (отмена ст. 3a) начинает действовать с 31 декабря 2027 г.","confidence":0.83,"rationale":"Акт прямо меняет закон о покупке недвижимости иностранцами и режим налоговых льгот для инвестиций, что затрагивает интересы нерезидентов, но не регулирует их пребывание или гражданство.","mnemonic_candidate":"Сделка без 3a","mnemonic_fallback":"Отмена статьи 3a","mnemonic_basis":"Текст проекта прямо предусматривает отмену статьи 3a в ustawa o nabywaniu nieruchomości przez cudzoziemców, влияя на правила сделок с недвижимостью для иностранцев.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":47274,"truncated":false,"text_source":"pdf","created_at":"2026-10-23T18:21:01Z","input_tokens":18630,"output_tokens":1833,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf","source_kind":"text_after3","revision":4,"text_sha256":"text-v2:2375b8cb3b541819ef76d7a4084c995b7914bfa2c37751a3d0c839f3e9c75f52","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf","members":[],"container_sha256":"63d00e254ea123a05cc9e5577836450de6c1e61c8a579c7122882058d63c197b","sha256":"63d00e254ea123a05cc9e5577836450de6c1e61c8a579c7122882058d63c197b","role":"bill","text":"","pages":23,"page_start":1,"page_end":23,"text_start":0,"text_end":47274,"text_sha256":"84b3afbc8208c7a42a865d64661a9dccc38a7f9161cf3e53cfea81e151db6590","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf","text_sha256":"84b3afbc8208c7a42a865d64661a9dccc38a7f9161cf3e53cfea81e151db6590","block_id":"part:0","start":0,"end":193,"quote":"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\n\nUSTAWA\nz dnia 22 października 2026 r.\no zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw1)\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":47274,"page_start":1,"page_end":23,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":47274,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"848084ca67e543ec94a891868e990b1d2f6d3f9e60817057ad1dfc7180865b90"},"law_sha256":"law-v2:7c9b78a00f9bab8aafdedf8c12815c7bd1cd97ba6a82c64082b63f90b83a9350","source_checked_at":"2026-10-23T18:21:01Z"}',10,'3160','2026-10-23T18:21:01+00:00');
INSERT INTO "analysis_memo" VALUES('62323dfc1da9b2aae569757f7b568dec3e840ebefe6d35a046c949de30eec474','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Закон разрешает ратификацию договора Польши с Филиппинами о передаче осуждённых для отбывания наказания в своей стране. Это касается в частности граждан Филиппин в польских тюрьмах и граждан Польши в тюрьмах на Филиппинах.","key_changes":["Польша даёт согласие на ратификацию договора с Филиппинами","Договор касается передачи лиц, осуждённых к лишению свободы","Рассматривается сотрудничество в уголовно‑правовой сфере","Закон о ратификации вступит в силу через 14 дней после опубликования"],"affected_groups":["граждане Филиппин, осуждённые в Польше","граждане Польши, осуждённые на Филиппинах","члены семей таких осуждённых"],"practical_impact":"Для осуждённых появится международно‑правовая основа просить перевод для отбывания наказания в государстве своего гражданства; конкретная процедура будет определяться самим договором Польша–Филиппины.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.73,"rationale":"Акт касается только передачи уже осуждённых между Польшей и Филиппинами и затрагивает иностранцев косвенно, без изменения правил пребывания или работы.","mnemonic_candidate":"филиппинский обмен заключённых","mnemonic_fallback":"договор о передаче осуждённых","mnemonic_basis":"Закон разрешает ратификацию договора Польша–Филиппины о передаче осуждённых для отбытия наказания в государстве их гражданства.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":599,"truncated":false,"text_source":"pdf","created_at":"2026-10-23T18:21:01Z","input_tokens":753,"output_tokens":2416,"cache_read_input_tokens":1280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"text-v2:cacac4badbcb206708724fa4fb8df6cef21f0d3c38fef2c7b0d08a3fa9e2a50f","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","members":[],"container_sha256":"e71112a667cbb2c6754e057a114524726937ca881259d85fa72e22541acb2bd9","sha256":"e71112a667cbb2c6754e057a114524726937ca881259d85fa72e22541acb2bd9","role":"bill","text":"","pages":1,"page_start":1,"page_end":1,"text_start":0,"text_end":599,"text_sha256":"aaa48ea0b36aeb3b6aa58a1e2a37943518ad3d1ca2df269727204cdaf04ead9c","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","text_sha256":"aaa48ea0b36aeb3b6aa58a1e2a37943518ad3d1ca2df269727204cdaf04ead9c","block_id":"part:0","start":0,"end":262,"quote":"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\n\nUSTAWA\nz dnia 22 października 2026 r.\no ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Filipin\no przekazywaniu osób skazanych, podpisanej w Warszawie dnia 8 czerwca 2026 r.\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","text_sha256":"aaa48ea0b36aeb3b6aa58a1e2a37943518ad3d1ca2df269727204cdaf04ead9c","block_id":"part:0","start":491,"end":513,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":599,"page_start":1,"page_end":1,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":599,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"9958fc521a502a9279d5ad85b42dec8c7cbd9b1585b893b3472fae8333dde4c5"},"law_sha256":"law-v2:5ec139a25cef02d0889ba895113f0ab5ab058abfa18851259c0988bd14dc2e4f","source_checked_at":"2026-10-23T18:21:01Z"}',10,'3013','2026-10-23T18:21:01+00:00');
INSERT INTO "analysis_memo" VALUES('8893afc07cb0f334263bf7a14825559eaaab82414d70967521caf91f05a626c4','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект полностью перестраивает систему рефундации лекарств NFZ, вводит новые ИТ‑системы и детальные правила рецептов. Для застрахованных иностранцев упрощается указание документов и идентификаторов при рецептах и заявлениях на возмещение, в т.ч. без PESEL.","key_changes":["В заявлении на индивидуальную рефундацию можно указать PESEL или серию и номер паспорта/иного документа","На электронных рецептах вводятся отдельные коды для PESEL, иностранцев без PESEL, Карты Поляка и координации ЕС","Система мониторинга программ лековых учитывает пациентов без PESEL по данным паспорта/другого документа","Автоопределение уровня доплаты по рецепту по коду ICD и статусу застрахованного снижает риск ошибок для иностранцев","Уточнены данные о праве на świadczenia по координации ЕС, которые передаются вместе с рецептом"],"affected_groups":["Иностранцы, застрахованные в NFZ с номером PESEL","Иностранцы, застрахованные в NFZ без PESEL (по паспорту или иному документу)","Обладатели Карты Поляка, использующие её как основание для медпомощи","Пациенты из ЕС/ЕЭЗ со świadczeniami по правилам координации ЕС","Иностранные пациенты в программах лековых (программы NFZ)"],"practical_impact":"Иностранный пациент сможет оформлять возмещение за импортируемые препараты, указывая либо PESEL, либо паспорт/иной документ. На рецептах и в системах NFZ появятся чёткие коды для разных типов иностранных идентификаторов, что уменьшит отказы из‑за формальных ошибок.","effective_date":"Закон вступает в силу 1 января 2027 года, за исключением ряда положений, для которых установлены более ранние или поздние сроки (14 дней, 6 месяцев после ogłoszenia, 1 апреля 2027 г., 1 июля 2027 г. и 1 января 2028 г.).","confidence":0.88,"rationale":"Акт детально регулирует рефундацию лекарств и работу рецептов с отдельными полями для иностранцев (паспорт, координация ЕС, Карта Поляка), что влияет на доступ застрахованных иностранцев к лекарственному возмещению, но не меняет иммиграционный статус.","mnemonic_candidate":"Рецепт по паспорту","mnemonic_fallback":"Идентификаторы в рецептах","mnemonic_basis":"Проект прямо разрешает в заявлениях на рефундацию и на рецептах использовать вместо PESEL серию и номер паспорта или другого документа, а также вводит отдельные коды для иностранцев и Карты Поляка.","mnemonic_language":"ru","changes_since_previous":["Уточнены виды идентификаторов на рецептах: коды для PESEL, иностранцев без PESEL, держателей Карты Поляка и пациентов по координации ЕС.","В заявлении на индивидуальную рефундацию (art. 39) теперь прямо указано: указывать PESEL или, при его отсутствии, серию и номер паспорта/иного документа.","Система мониторинга программ лековых оформлена как модуль SIM и явно предусматривает идентификацию пациентов без PESEL по документу личности.","Расширён перечень данных по координации ЕС, передаваемых с рецептом (данные иностранной институции, период права на świadczenia).","Уточнены коды дополнительных прав на медпомощь и документы, подтверждающие эти права, что затрагивает и некоторых иностранцев с особыми статусами."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":451156,"truncated":false,"text_source":"documents","created_at":"2026-10-26T19:32:49Z","request_sha256":"a8b741f9686b21deecf317c31330d0c7ba52aea02285a10e01f3293953531bb0","input_tokens":142158,"output_tokens":2273,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","source_kind":"rcl","revision":2,"text_sha256":"text-v2:33167a27b28e6b847a92b2b9ad0baf932127a77ef1d9abe491b177c5543b9512","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":["bill heading"],"version":["rcl/12398102/stage/13129966","Projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (UD187), RM-0610-180-26.zip"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","members":["na RM ustawa refundacyjna 14.10.2026.docx"],"container_sha256":"152801efdb2625ace4a86e3b00b288c50b178ba2186feb71e9cc41aab39aab44","sha256":"ae759de50ea10201e2237e7e8d524275bcf8cc18718fe3898a6978ebdc0d57e7","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":151254,"text_sha256":"f8b3149402ed547503a7465d32b087439decb8c6f1fcb3f7b535e568cabadec9","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","members":["na RM UZASADNIENIE 14.10.2026.docx"],"container_sha256":"152801efdb2625ace4a86e3b00b288c50b178ba2186feb71e9cc41aab39aab44","sha256":"615889623ce45ed1185bfa1d0b5e069a335482faf2278e0fcd45cb3d191c7092","role":"justification","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":233140,"text_sha256":"b39aaba485a62b2b2fa6990e1ffca13a45cd73c28421f164b79f120ce53204d5","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","members":["na RM OSR2 zmiana ustawy.docx"],"container_sha256":"152801efdb2625ace4a86e3b00b288c50b178ba2186feb71e9cc41aab39aab44","sha256":"f7ec01dd2dff88739b286b0f1a18d4a83b7b611b0952f4a66d485ccfc53b6790","role":"osr","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":96363,"text_sha256":"a3462389cec9768bcc971ea03dc53a5b79b0ac2728e261875cf5c45d54b497a0","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","members":["MZ na RM - protokól rozbieznosci.pdf"],"container_sha256":"152801efdb2625ace4a86e3b00b288c50b178ba2186feb71e9cc41aab39aab44","sha256":"b5c21fd8d5d942a8cd0bd1c78b50f512480d568aaba781d80f7e5975efcb49e1","role":"unknown",