INSERT INTO "bills" VALUES(10,'316','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-10-23T08:51:43+00:00','2026-10-22',1,'analyzed','[]','{"term":10,"number":"316","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania korzystania przez osoby z niepełnosprawnościami z usługi asystencji osobistej i stworzenia w ten sposób trwałych warunków dla osób z niepełnosprawnościami do realizacji możliwie pełnego samodzielnego życia","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-03-04","document_date":"2024-03-04","change_date":"2026-10-23T08:51:43Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["1929","1933"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2024-03-04","print_number":"316","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2024-03-11","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2024-04-24","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2024-04-24","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2024-10-01","sitting_num":18,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2024-10-01","committee_code":"PSR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/spr_316_1929_1933.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":14,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"niedokończone II czytanie","sub_committee":false,"children":[]}]','942080c2e359c871d443ab63f7304df360b75913c6b2dbbdc3c863c110be94a2','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Законопроект вводит государственную услугу персонального ассистента (asystencja osobista) для людей с инвалидностью. Право на неё получают не только граждане Польши, но и определённые категории иностранцев с легальным пребыванием в Польше. Услуга бесплатная, назначается решением starosty powiatu.","key_changes":["Право на услугу у иностранцев с pobyt stały, pobyt rezydenta długoterminowego UE","Право у лиц с zezwolenie na pobyt czasowy по art. 159 ust. 1 pkt 1 lit. c/d или art. 186 ust. 1 pkt 3","Право у лиц со статусом беженца или дополнительной защитой","Право у граждан ЕС/EFTA/Швейцарии и членов их семей с правом пребывания","К заявлению иностранец прилагает документ, дающий право на пребывание"],"affected_groups":["иностранцы с постоянным пребыванием","резиденты ЕС","обладатели некоторых zezwoleń na pobyt czasowy","беженцы и лица с дополнительной защитой","граждане ЕС/EFTA и члены их семей"],"practical_impact":"Иностранец с указанным видом пребывания и решением об уровне потребности в поддержке (70–100 баллов) сможет подать заявление в starostwo powiatowe и бесплатно получать от 40 до 200 часов помощи ассистента в месяц.","effective_date":"Закон вступает в силу 1 января 2025 г., кроме art. 11 ust. 3-6 и art. 30 ust. 2 pkt 2 (с 1 января 2026 г.) и части art. 4 ust. 1 для 70–84 баллов (с 1 января 2027 г.).","confidence":0.88,"rationale":"Новая социальная услуга прямо перечисляет категории иностранцев, имеющих на неё право, что относится к социальной сфере.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":966,"truncated":false,"text_source":"scan","created_at":"2026-09-14T21:58:20Z","input_tokens":124658,"output_tokens":794,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/316/316.pdf","source_kind":"print","revision":1,"text_sha256":"9deeeb9f5b26d0c47bcab860623124c40657b55ce58f4547f0358a2cf295bc49","source_checked_at":null}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"comparison":{"same_substance":false,"summary":"Президентский проект даёт наиболее узкий круг иностранцев (без карты с ''dostęp do rynku pracy'' и большинства ВНЖ), решение выдаёт starosta, объём 40–200 часов при 70–100 баллах поддержки; заявление подаётся в starostwo, а не электронно.","differences":["Решение принимает starosta powiatu, а в druk 1929 и 1933 — wojewódzki zespół ds. orzekania o niepełnosprawności","Круг иностранцев уже: нет карты с ''dostęp do rynku pracy'', ст. 127, 137a, 151 и др., в отличие от druk 1929 и 1933","Объём помощи 40–200 часов в месяц против 20–240 в druk 1929 и 1933","Порог поддержки 70–100 баллов сразу, без поэтапного снижения из druk 1929 (90→85→80)","Заявление в starostwo powiatowe, а не только электронно (druk 1929) или через систему ZUS (druk 1933)"],"confidence":0.85},"compared_with":["1929","1933"],"model":"claude-opus-5","prompt_version":"2026-09-v7","created_at":"2026-09-14T21:58:29Z","input_tokens":2233,"output_tokens":375,"cache_read_input_tokens":0,"cache_creation_input_tokens":1216}',NULL,NULL,0,NULL,NULL,NULL,'full','relevant_analysis',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'1387','Poselski projekt ustawy o zmianie ustawy o ochronie przyrody oraz niektórych innych ustaw','2026-10-09T12:19:14+00:00','2026-10-08',1,'analyzed','["text:cudzoziemcy", "text:migracja"]','{"term":10,"number":"1387","title":"Poselski projekt ustawy o zmianie ustawy o ochronie przyrody oraz niektórych innych ustaw","description":"projekt dotyczy m. in. dodania do katalogu gatunków m. in. kormorana czarnego, żurawia, dzikich gęsi z rodzaju Anser, łabędzi, kruka i czapli siwej, za których szkody przysługuje rekompensata, określenia podmiotu odpowiedzialnego za szacowanie i wypłatę odszkodowań (dyrektor oddziału terenowego Krajowego Ośrodka Wsparcia rolnictwa), zapewnienia udziału izb rolniczych oraz jednostek doradztwa rolniczego w procesie potwierdzania i dokumentowania szkód wyrządzonych przez ptaki","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-06-03","document_date":"2025-06-03","change_date":"2026-10-09T12:19:14Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["258"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-06-03","print_number":"1387","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-06-10","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-07-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-07-22","committee_code":"RRW","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-07-22","committee_code":"OSZ","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2025-10-15","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2025-11-06","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2025-11-06","print_number":"1661","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/1661/1661.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-04","sitting_num":64,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-04","committee_code":"RRW","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-04","committee_code":"OSZ","sub_committee":false,"children":[]}]}]','d2474d7d51b5add060aa5af65c6a52bfad813db3b84b58c4fb1a421a1844f927','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается изменения правил компенсации ущерба от птиц для сельского и рыбного хозяйства и не затрагивает статус, права или обязанности иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.95,"rationale":"Проект касается изменения правил компенсации ущерба от птиц для сельского и рыбного хозяйства и не затрагивает статус, права или обязанности иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v3","input_chars":18120,"truncated":true,"text_source":"excerpts","created_at":"2026-09-09T17:57:15Z","input_tokens":11014,"output_tokens":88,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-10T12:46:19+00:00',NULL,NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PSL-TD",30]],"signatories":30,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'metadata','not_relevant',NULL,