INSERT INTO "bills" VALUES(10,'1933','Poselski projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-10-23T08:51:43+00:00','2026-10-22',1,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:ochrona_miedzynarodowa", "text:status_uchodzcy"]','{"term":10,"number":"1933","title":"Poselski projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania dostępu do formy wsparcia, jaką jest asystencja osobista","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-16","document_date":"2025-10-16","change_date":"2026-10-23T08:51:43Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["316","1929"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-10-16","print_number":"1933","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-27","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-11-07","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-07","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2025-11-21","sitting_num":45,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-21","committee_code":"PSR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-05-14","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1933/attachment/spr_316_1929_1933.pdf","sub_committee":true,"children":[]},{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-08","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/1933/attachment/spr_316_1929_1933_1.pdf","sub_committee":true,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-30","print_number":"2792","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"niedokończone II czytanie","sub_committee":false,"children":[]}]','aa0cd7575fa6ece82523226dcfdadded598ef0d411a0fd5dbb8e351cff1d25ad','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект вводит системную услугу личного ассистента для людей с инвалидностью, финансируемую из госбюджета. В законе прямо перечислены категории иностранцев, имеющих право подать заявление: граждане ЕС/ЕЭЗ/Швейцарии, обладатели ПМЖ, статуса долгосрочного резидента ЕС, беженцы, лица с картой побыта с отметкой «доступ к рынку труда» и др. Обязательное условие — проживание в Польше в период пользования услугой.","key_changes":["Право на бесплатную ассистенцию для иностранцев с ПМЖ, статусом резидента ЕС, беженцев и лиц с доп. защитой","Право для граждан ЕС/ЕЭЗ/Швейцарии и членов их семей с правом пребывания","Право для обладателей карты побыта с отметкой «dostęp do rynku pracy», кроме сезонных работников, студентов и работающих по визе","Включены обладатели ВНЖ по ст. 127, 137a, 139a, 139o, 151, 151b, 159, 186 ustawy o cudzoziemcach и научные визы","Требование фактического проживания в Польше; заявление подаётся электронно, нужен PESEL или документ, удостоверяющий личность","Иностранцы также могут работать личными ассистентами (требуется внесение в Rejestr asystentów)"],"affected_groups":["Иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС","Беженцы и лица с дополнительной защитой","Граждане ЕС/ЕЭЗ/Швейцарии и члены их семей","Обладатели карты побыта с доступом к рынку труда","Иностранцы, желающие работать личными ассистентами"],"practical_impact":"Иностранцы указанных категорий с инвалидностью смогут подать заявление на бесплатную помощь личного ассистента (от 20 до 240 часов в месяц) через электронную систему ZUS; решение выдаёт wojewódzki zespół ds. orzekania o niepełnosprawności на срок от 1 до 5 лет. Исключены лица с краткосрочными разрешениями (до 6-9 месяцев), студенты, сезонные работники и работающие по визе.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением: положений о задачах Уполномоченного, госзакупках и лимитах расходов — через 14 дней после опубликования; ст. 51–60 и 122 — с 30 июня 2026 г.; ст. 6 ч. 1 и ст. 7 — через 14 месяцев после опубликования. Фактическое оказание услуг начинается с 1 апреля 2027 г. (для лиц с 90+ баллами), с 1 января 2028 г. — для лиц с 85+ баллами и подростков 13–18 лет.","confidence":0.9,"rationale":"Законопроект напрямую определяет круг иностранцев, имеющих право на новую социальную услугу, что относится к социальной сфере (услуги, льготы) без влияния на легализацию пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":625066,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:57:07Z","input_tokens":305132,"output_tokens":1100,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1933/1933.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/34400/2025","title":"Poselski projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"systemowego uregulowania dostępu do formy wsparcia, jaką jest asystencja osobista","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-10-16","print_number":"1933","eu_related":false,"public_consultation":true,"consultation_start":"2025-10-17","consultation_end":"2025-11-16","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["Lewica",20],["Polska2050",10],["Centrum",8],["niez.",1]],"signatories":39,"unresolved":0}','[{"kind": "committee", "ref": "PSR/139/2026-09-15", "date": "2026-09-15", "end_date": null, "start_time": "08:30:00", "committee_code": "PSR", "committee_name": "Komisja Polityki Społecznej i Rodziny", "sitting_number": 139, "room": "sala im. Olgi Krzyżanowskiej (nr 412, bud. U)", "text": "Rozpatrzenie poprawek zgłoszonych w czasie drugiego czytania do projektu ustawy o asystencji osobistej osób z niepełnosprawnościami (druki nr 316, 1929, 1933 i 2792).", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=DB511B56293B5C6FC1258E6E003B4E09"}]',NULL,NULL,NULL,NULL,NULL,'{"comparison":{"same_substance":false,"summary":"Депутатский проект почти совпадает с правительственным (druk 1929) по кругу иностранцев и объёму 20–240 часов, но прямо требует фактического проживания в Польше, допускает подачу по PESEL или документу личности и отдельно регулирует работу иностранцев ассистентами через Rejestr asystentów.","differences":["druk 1929: не упоминает Rejestr asystentów и работу иностранцев в роли ассистентов","druk 316: круг иностранцев уже (без карты с ''dostęp do rynku pracy'' и научных виз)","druk 316: заявление в starostwo, решение starosty; здесь — электронно, решение wojewódzki zespół","druk 316: 40–200 часов и порог 70–100 баллов; здесь 20–240 часов","druk 1929: этапный порог баллов (90→85→80) и ставка 49–55 zł/час не указаны в этом проекте"],"confidence":0.7},"compared_with":["316","1929"],"model":"claude-opus-5","prompt_version":"2026-09-v7","created_at":"2026-09-14T21:58:38Z","input_tokens":2233,"output_tokens":339,"cache_read_input_tokens":1216,"cache_creation_input_tokens":0}',NULL,NULL,0,NULL,NULL,NULL,'full','relevant_analysis',NULL,NULL,NULL,NULL,NULL,NULL);
