_committee":false,"voting":{"yes":241,"no":161,"abstain":38,"not_participating":20,"sitting":64,"voting_number":33,"date":"2026-09-04T09:50:01Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/64/33/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-09-24","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Wniosek Prezydenta (weto)","stage_type":"Veto","date":"2026-10-15","print_number":"3229","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','9554997243f70f95c944fd11d21d76783a757a6d061d5ccab96ba1c61b860af7','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Закон устанавливает, как Польша исполняет решения Европейского суда по правам человека (ЕСПЧ): кто отвечает за исполнение, как выплачивается компенсация и как соблюдаются временные меры суда. Норм об иностранцах в тексте нет, но закон касается и иностранцев, подавших жалобу в ЕСПЧ против Польши.","key_changes":["MSZ координирует исполнение решений ЕСПЧ, при министре создаётся межведомственный Zespół","Компенсация выплачивается по заверенному формуляру платежа, при его отсутствии сумма идёт в судебный депозит","Временную меру ЕСПЧ исполняют и тогда, когда о ней сообщил представитель заявителя, если документ достоверен","По временной мере орган прекращает или не начинает указанное судом действие и может изменить или отменить решение","Окончательное решение ЕСПЧ становится исполнительным документом (art. 777 KPC)"],"affected_groups":["заявители, подавшие жалобу в ЕСПЧ против Польши, в том числе иностранцы","лица, в делах которых ЕСПЧ назначил временную меру"],"practical_impact":"Заявителю, выигравшему дело в ЕСПЧ, нужно без промедления подать в MSZ заверенный формуляр платежа, иначе сумма попадёт в судебный депозит. Временные меры ЕСПЧ обязательны для органов власти, в том числе если о них сообщил представитель заявителя.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.6,"rationale":"Закон общий и процедурный, иностранцы в нём прямо не упоминаются, поэтому для них он маргинален, хотя механизм временных мер ЕСПЧ может затрагивать и их дела.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":46453,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2271/attachment/2271_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"e22f0142ed0f6306ff7f712868af66cb47da2c50ad880759c7b83b7ebf15d8b9","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-29T19:06:31+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'2026-09-04','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-02-13","print_number":"2271","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-02-25","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-02-25","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-04-17","sitting_num":55,"s