INSERT INTO "bills" VALUES(10,'2411','Rządowy projekt ustawy o zmianie niektórych ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną','2026-10-02T05:58:39+00:00','2026-09-04',1,'analyzed','["straz_graniczna"]','{"term":10,"number":"2411","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną","description":"projekt dotyczy wzmocnienia kontroli sądów nad działaniami służb stosujących tzw. kontrolę operacyjną. Chodzi o niejawne działania, np. podsłuchy czy obserwację, które są wykorzystywane do zapobiegania i wykrywania przestępstw. Zmiany wzmocnią ochronę praw obywateli - zwłaszcza prawa do prywatności - oraz zwiększą przejrzystość działań służb. Nowe przepisy będą dotyczyć m.in. służb specjalnych, Policji oraz Straży Granicznej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-01","document_date":"2026-04-01","change_date":"2026-10-02T05:58:39Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-44-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-44-26","prints_considered_jointly":[],"eli":"DU/2026/1281","display_address":"Dz.U. 2026 poz. 1281","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001281","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-04-01","print_number":"2411","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-04-14","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-14","committee_code":"SPC","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-14","committee_code":"KSS","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-14","committee_code":"ASW","s