czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-31","sitting_num":63,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2411/attachment/2411_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-07-31","sub_committee":false,"voting":{"yes":264,"no":1,"abstain":176,"not_participating":19,"sitting":63,"voting_number":18,"date":"2026-07-31T09:48:48Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/63/18/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-08-06","print_number":"2991","position":"wniósł poprawki","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-07","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-07","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Praca w komisjach nad stanowiskiem Senatu","stage_type":"CommitteeWork","date":"2026-09-02","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-02","print_number":"3023","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3023/3023.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"Rozpatrywanie na forum Sejmu stanowiska Senatu","stage_type":"SenatePositionConsideration","date":"2026-09-04","sitting_num":64,"decision":"przyjęto część poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-04","sub_committee":false,"children":[]},{"stage_name":"Prezydent podpisał ustawę","stage_type":"PresidentSignature","date":"2026-09-25","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','729c88f635935e3e269645d9f4161833945512949c8ff0751e6456aa7caaa109','{"analysis":{"relevant":false,"score":1,"category":"marginal","summary":"Правительственный проект усиливает судебный контроль за так называемым «kontrola operacyjna» (оперативный контроль — скрытая прослушка, наблюдение), который применяют Полиция, Straż Graniczna (Пограничная служба), ABW, CBA, SKW, KAS, Żandarmeria Wojskowa и SOP. Суды будут обязаны обосновывать каждое постановление о назначении или продлении такого контроля, получать информацию о его результатах и ходе, а также смогут в любой момент прекратить контроль. Вводятся сроки уничтожения материалов (3 месяца с возможным продлением на 3 месяца) и обязанность информировать суд об их уничтожении. Инспектор внутреннего надзора (INW) лишается права применять оперативный контроль и «контролируемую закупку». Проект не касается пребывания, работы или социальных прав иностранцев — он относится к процедурам спецслужб и защите приватности всех лиц на территории Польши.","key_changes":["Обязанность суда обосновывать постановления о назначении и продлении оперативного контроля","Суд и прокурор получают право в любой момент постановить о прекращении оперативного контроля","Службы обязаны информировать суд о результатах и, по требованию, о ходе контроля","Материалы, непригодные для уголовного процесса, уничтожаются в течение 3 месяцев (+3 месяца в особых случаях) с уведомлением суда","Отмена права Инспектора внутреннего надзора на оперативный контроль и контролируемую закупку","Ежегодный отчёт МВД Сейму и Сенату о деятельности Straż Graniczna в этой сфере (первый — до 30 июня 2027 г.)"],"affected_groups":["Все лица на территории Польши, включая иностранцев, в отношении которых применяется оперативный контроль","Сотрудники служб и судов"],"practical_impact":"Для иностранца в повседневной жизни ничего не меняется: документы, сроки и разрешения на пребывание не затрагиваются. Косвенно усиливаются гарантии приватности при скрытых мероприятиях служб, в том числе Пограничной службы.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.9,"rationale":"Проект регулирует процедуры судебного надзора над спецслужбами и не изменяет правил пребывания, работы или социальных прав иностранцев, поэтому значение для них минимальное.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v1","input_chars":64556,"truncated":false,"text_source":"pdf","created_at":"2026-09-07T13:52:39Z","input_tokens":33683,"output_tokens":987,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2411/2411.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:41+00:00',NULL,'RCL/12404202','{"eli":"DU/2026/1281","display_address":"Dz.U. 2026 poz. 1281","title":"Ustawa z dnia 4 września 2026 r. o zmianie ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną","act_date":"2026-09-04","promulgation_date":"2026-09-30","entry_into_force":"2026-10-31","in_force":"IN_FORCE","status":"obowiązujący","text_pdf_url":"https://api.sejm.gov.pl/eli/acts/DU/2026/1281/text.pdf","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001281","fetched_at":"2026-10-02T07:06:37.350938Z"}','2026-10-31',NULL,NULL,NULL,NULL,'UD278',NULL,'["2411-001", "2411-002", "2411-003"]',NULL,'2026-09-04','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-04-01","print_number":"2411","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-04-14","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-14","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-0