INSERT INTO "bills" VALUES(10,'2530','Poselski projekt ustawy o kryptoaktywach','2026-09-07T10:38:20+00:00','2026-09-04',0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2530","title":"Poselski projekt ustawy o kryptoaktywach","description":"projekt dotyczy zapewnienia stosowania na terytorium RP rozporządzenia PE i Rady (UE) 2023/1114 z dnia 31 maja 2023 r. w sprawie rynków kryptoaktywów oraz zmiany rozporządzeń (UE) nr 1093/2010 i (UE) nr 1095/2010 oraz dyrektyw 2013/36/UE i (UE) 2019/1937 i ustanowienia krajowych rozwiązań organizacyjnych i proceduralnych, w szczególności w zakresie wskazania właściwego organu, trybów prowadzenia postępowań oraz zasad finansowania kosztów nadzoru w granicach dopuszczonych prawem","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-27","document_date":"2026-02-27","change_date":"2026-09-07T10:38:20Z","closure_date":"2026-09-04","passed":false,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":["2363","2528","2529"]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×2)','2026-09-07T13:52:14+00:00','2026-09-09T08:59:55+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2580','Rządowy projekt ustawy o osobistych kontach inwestycyjnych','2026-08-27T09:16:56+00:00','2026-07-03',1,'analyzed','["text:cudzoziemcy", "text:obywatelstwo"]','{"term":10,"number":"2580","title":"Rządowy projekt ustawy o osobistych kontach inwestycyjnych","description":"projekt dotyczy wprowadzenia nowych, dobrowolnych i bezpłatnych narzędzi do oszczędzania oraz inwestowania - Osobiste Konto Inwestycyjne (OKI). Rozwiązanie umożliwi inwestowanie w akcje, obligacje oraz inne instrumenty finansowe z pełnym zwolnieniem od podatku dochodowego do 100 tys. zł. Dla aktywów oszczędnościowych, takich jak lokaty czy obligacje oszczędnościowe, zwolnienie wyniesie do 25 tys. zł. Projekt stanowi realizację priorytetów rządu. Nowe przepisy zaczną obowiązywać od 2027 roku.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-08","document_date":"2026-05-08","change_date":"2026-08-27T09:16:56Z","closure_date":"2026-07-03","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-63-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-63-26","prints_considered_jointly":[],"eli":"DU/2026/1098","display_address":"Dz.U. 2026 poz. 1098","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001098","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-05-08","print_number":"2580","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-05-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-05-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-06-09","sitting_num":59,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-09","committee_c