INSERT INTO "bills" VALUES(10,'2649','Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym','2026-10-02T05:59:32+00:00','2026-09-04',1,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2649","title":"Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym","description":"projekt dotyczy ujednolicenia przepisów w zakresie biernego prawa wyborczego (prawa wybieralności) w organach jednostek samorządu terytorialnego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-15","document_date":"2026-05-15","change_date":"2026-10-02T05:59:32Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"eli":"DU/2026/1273","display_address":"Dz.U. 2026 poz. 1273","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001273"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-10-03T11:51:30+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2667','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.','2026-08-27T09:19:19+00:00','2026-07-17',1,'analyzed','["text:cudzoziemcy", "text:migracja", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:granica_panstwowa", "text:ochrona_miedzynarodowa", "text:schengen", "text:pracownicy_delegowani", "text:status_uchodzcy"]','{"term":10,"number":"2667","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.","description":"projekt dotyczy uregulowania między Polską a Albanią wzajemnych stosunków w dziedzinie zabezpieczenia społecznego, w tym wprowadzenia możliwości korzystania przy ustalaniu prawa do świadczeń długoterminowych (emerytur i rent) z zasady sumowania okresów ubezpieczenia oraz możliwości transferu świadczeń nabytych na podstawie ustawodawstwa Polski, w przypadku przeniesienia swojego miejsca zamieszkania na terytorium Albanii i odwrotnie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T09:19:19Z","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":[],"eli":"DU/2026/1100","display_address":"Dz.U. 2026 poz. 1100","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001100","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2667","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-11","com