INSERT INTO "bills" VALUES(10,'2694','Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw','2026-10-12T11:59:48+00:00','2026-09-04',1,'skipped_text_prefilter','["text:prawnicy_zagraniczni"]','{"term":10,"number":"2694","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw","description":"projekt dotyczy ustanowienia Prezesa Urzędu Komunikacji Elektronicznej głównym organem nadzorującym stosowanie nowych przepisów i pełniącym funkcję koordynatora ds. usług cyfrowych; wprowadzenia nowych mechanizmów rozpatrywania sporów, zgłoszeń nielegalnych treści oraz dostępu do danych dużych platform internetowych, w celach naukowych dotyczących m.in. dezinformacji czy bezpieczeństwa w sieci","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-10-12T11:59:48Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":[],"eli":"DU/2026/1296","display_address":"Dz.U. 2026 poz. 1296","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001296"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (prawnicy_zagraniczni×2)','2026-09-07T13:52:14+00:00','2026-10-13T19:54:03+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
