INSERT INTO "bills" VALUES(10,'2699','Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie','2026-08-27T09:18:01+00:00','2026-07-17',1,'analyzed','["cudzoziemcy", "nieruchomosci_cudzoziemcy"]','{"term":10,"number":"2699","title":"Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie","description":"projekt dotyczy usprawnienia kontroli nabywania przez cudzoziemców nieruchomości w Polsce. Notariusze będą przesyłać dokumenty do Ministerstwa Spraw Wewnętrznych i Administracji wyłącznie w formie elektronicznej. Dzięki temu ich obieg stanie się szybszy, bezpieczniejszy i bardziej przejrzysty. Zmiany wpisują się w proces cyfryzacji administracji publicznej i poprawiają nadzór nad zakupem nieruchomości przez cudzoziemców","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T09:18:01Z","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-81-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-81-26","prints_considered_jointly":[],"eli":"DU/2026/1099","display_address":"Dz.U. 2026 poz. 1099","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001099","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2699","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"SPC","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-02","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-07-02","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-02","print_number":"2755","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2755/2755.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-15","sitting_num":62,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-17","sitting_num":62,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2699/attachment/2699_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-07-17","sub_committee":false,"voting":{"yes":261,"no":0,"abstain":182,"not_participating":17,"sitting":62,"voting_number":16,"date":"2026-07-17T07:45:59Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/62/16/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-07-22","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-07-27","sub_committee":false,"children":[]},{"stage_name":"Prezydent podpisał ustawę","stage_type":"PresidentSignature","date":"2026-08-13","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"title_final":"o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2699","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-02","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-07-02","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-02","print_number":"2755","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2755/2755.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-15","sitting_num":62,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-17","sitting_num":62,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2699/attachment/2699_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-07-17","sub_committee":false,"voting":{"yes":261,"no":0,"abstain":182,"not_participating":17,"sitting":62,"voting_number":16,"date":"2026-07-17T07:45:59Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/62/16/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-07-22","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-07-27","sub_committee":false,"children":[]},{"stage_name":"Prezydent podpisał ustawę","stage_type":"PresidentSignature","date":"2026-08-13","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','e5f70fefbeb72530a78121526b37689046f2f6e79537583eaed383eac3fdadac','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект переводит передачу нотариальных документов о покупке недвижимости иностранцами в электронный вид: нотариус размещает выписки в репозитории CREWAN, а Krajowa Rada Notarialna пересылает их в МВД. Сами правила приобретения недвижимости иностранцами (разрешения, исключения) не меняются. За размещение документа нотариус берёт с сторон сделки плату.","key_changes":["Нотариус исполняет обязанность уведомления МВД через размещение электронных выписок в Repozytorium (CREWAN)","Krajowa Rada Notarialna незамедлительно пересылает документы министру внутренних дел через телеинформационную систему","Введена плата со сторон сделки за размещение документа в репозитории; размер определит распоряжение МВД","Срок хранения документов в репозитории установит министр внутренних дел в распоряжении","К документам, составленным до вступления закона в силу, применяются прежние правила"],"affected_groups":["Иностранцы, покупающие недвижимость в Польше","Иностранные компании и лица, приобретающие доли/акции компаний-владельцев недвижимости","Нотариусы"],"practical_impact":"При сделке с недвижимостью иностранец не подаёт ничего дополнительно, но оплачивает нотариусу небольшую плату за электронное размещение документа; контроль МВД становится быстрее и полнее.","effective_date":"Закон вступает в силу по истечении 3 месяцев со дня опубликования","confidence":0.9,"rationale":"Изменение носит процедурно-технический характер и лишь косвенно затрагивает иностранцев — покупателей недвижимости, не меняя правил получения разрешений.","changes_since_previous":["Это текст закона после III чтения, переданный в Сенат (ранее — проект)","Уточнено, что размер и способ уплаты платы за размещение документа определит распоряжение министра внутренних дел (конкретной суммы 5 zł в тексте закона нет)","Терминология изменена: «Minister Spraw Wewnętrznych» заменён на «minister właściwy do spraw wewnętrznych»","Прямо указано, что прежние подзаконные акты по art. 92a § 7 Prawa o notariacie теряют силу","Установлен срок вступления в силу: через 3 месяца после опубликования"]},"model":"claude-opus-5","prompt_version":"2026-09-v2","input_chars":5083,"truncated":false,"text_source":"pdf","created_at":"2026-09-08T09:27:43Z","input_tokens":3594,"output_tokens":835,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2699/attachment/2699_u3.pdf","source_kind":"text_after3","revision":2}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:17+00:00',NULL,NULL,'{"eli":"DU/2026/1099","display_address":"Dz.U. 2026 poz. 1099","title":"Ustawa z dnia 17 lipca 2026 r. o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie","act_date":"2026-07-17","promulgation_date":"2026-08-18","entry_into_force":"2026-11-19","in_force":"IN_FORCE","status":"obowiązujący","text_pdf_url":"https://api.sejm.gov.pl/eli/acts/DU/2026/1099/text.pdf","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001099","fetched_at":"2026-09-08T09:27:45.494607Z"}','2026-11-19',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'2026-07-17','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2699","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawied