INSERT INTO "bills" VALUES(10,'2801','Rządowy projekt ustawy o zmianie ustawy o związkach zawodowych oraz ustawy o informowaniu pracowników i przeprowadzaniu z nimi konsultacji','2026-10-19T06:12:40+00:00','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2801","title":"Rządowy projekt ustawy o zmianie ustawy o związkach zawodowych oraz ustawy o informowaniu pracowników i przeprowadzaniu z nimi konsultacji","description":"projekt dotyczy ułatwienia komunikacji między pracodawcą, zakładową organizacją związkową oraz radą pracowników. Zamiast obowiązkowego obiegu dokumentów w formie papierowej możliwe będzie korzystanie również z formy elektronicznej lub dokumentowej (np. PDF), o ile strony wyrażą na to zgodę. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-10","document_date":"2026-07-10","change_date":"2026-10-19T06:12:40Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"eli":"DU/2026/1340","display_address":"Dz.U. 2026 poz. 1340","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001340"}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-20T18:01:38+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2810','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.','2026-10-19T06:14:05+00:00','2026-09-18',1,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:ochrona_miedzynarodowa", "text:pracownicy_delegowani"]','{"term":10,"number":"2810","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.","description":"projekt dotyczy m.in. możliwości sumowania polskich oraz japońskich okresów ubezpieczenia, w celu przyznania prawa do świadczeń oraz możliwości dokonywania wypłaty\npolskich świadczeń osobom uprawnionym mającym miejsce zamieszkania na terytorium Japonii","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-13","document_date":"2026-07-13","change_date":"2026-10-19T06:14:05Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"eli":"DU/2026/1326","display_address":"Dz.U. 2026 poz. 1326","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001326","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-13","print_number":"2810","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"PSR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"SZA","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-03","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po