do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-03","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-03","print_number":"3062","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3062/3062.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-16","sitting_num":65,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2810/attachment/2810_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":389,"no":22,"abstain":1,"not_participating":48,"sitting":65,"voting_number":143,"date":"2026-09-18T10:00:44Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/143/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-09-24","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Prezydent podpisał ustawę","stage_type":"PresidentSignature","date":"2026-10-09","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','0eb559af361768a57cad868c02efa47d569ec4c3dc997cf91a440ea46b6ebfc9','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект закона разрешает ратификацию договора между Польшей и Японией о социальном обеспечении, подписанного в Токио 15 апреля 2026 г. Договор позволяет суммировать польские и японские периоды страхования для назначения пенсий и переводить польские выплаты людям, живущим в Японии. Он касается всех, кто платил взносы в одной или обеих странах, независимо от гражданства.","key_changes":["Суммирование польских и японских периодов страхования для права на пенсию и пособия","Перевод польских пенсий и пособий получателям, проживающим в Японии","Принцип уплаты взносов только в одной стране (по месту работы), исключение двойных взносов","Командированные работники и самозанятые остаются в системе своей страны до 5 лет (+ продление до 3 лет)","Освобождение супруга и детей командированного из Польши от взносов в пенсионную систему Японии"],"affected_groups":["граждане Японии, работающие или ведущие бизнес в Польше","граждане Польши и другие лица, работавшие в Японии","командированные работники и члены их семей","самозанятые, работающие временно в другой стране"],"practical_impact":"Периоды страхования в Японии можно будет засчитать для польской пенсии и наоборот, а польские выплаты можно будет получать на счёт в Японии. Командированным не придётся платить взносы дважды.","effective_date":"Закон вступает в силу через 14 дней после опубликования; сам договор — после завершения процедуры ратификации (финансовые последствия ожидаются не ранее первой половины 2027 г.).","confidence":0.9,"rationale":"Ратификация двустороннего соглашения о социальном обеспечении — косвенное влияние на иностранцев (в первую очередь японцев в Польше и лиц со стажем в обеих странах), что соответствует уровню 2.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":90284,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T18:00:12Z","input_tokens":44862,"output_tokens":838,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2810/2810.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:42+00:00',NULL,NULL,'{"eli":"DU/2026/1326","display_address":"Dz.U. 2026 poz. 1326","title":"Ustawa z dnia 18 września 2026 r. o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.","act_date":"2026-09-18","promulgation_date":"2026-10-13","entry_into_force":"2026-10-28","in_force":"IN_FORCE","status":"akt jednorazowy","text_pdf_url":"https://api.sejm.gov.pl/eli/acts/DU/2026/1326/text.pdf","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001326","fetched_at":"2026-10-19T06:24:26.177085Z"}','2026-10-28',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'2026-09-18','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-13","print_number":"2810","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026