INSERT INTO "bills" VALUES(10,'2821','Rządowy projekt ustawy o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw','2026-10-19T06:16:59+00:00','2026-09-04',1,'analyzed','[]','{"term":10,"number":"2821","title":"Rządowy projekt ustawy o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw","description":"projekt dotyczy m.in.: powstania nowego systemu wsparcia dla instalacji produkujących biometan o mocy większej niż 1 MW, złagodzenia zasad udziału części instalacji wykorzystujących biogaz i biomasę w systemie aukcyjnym OZE, ułatwienia zasad budowy tzw. gazociągów bezpośrednich, czyli połączeń, które umożliwiają dostarczanie biogazu lub biometanu bezpośrednio od producenta do odbiorcy, z pominięciem ogólnej sieci gazowej, doprecyzowania zasad działania spółdzielni energetycznych, czyli grup mieszkańców, przedsiębiorców lub samorządów, które wspólnie produkują i wykorzystują energię","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-15","document_date":"2026-07-15","change_date":"2026-10-19T06:16:59Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-101-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-101-26","prints_considered_jointly":[],"eli":"DU/2026/1347","display_address":"Dz.U. 2026 poz. 1347","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001347","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-15","print_number":"2821","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-16","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-16","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-