ранцах он не содержит.","key_changes":[],"affected_groups":[],"practical_impact":"Для иностранцев в Польше ничего не меняется: речь идёт об энергетических предприятиях и кооперативах.","effective_date":null,"confidence":0.75,"rationale":"Тема сугубо энергетическая, без норм о пребывании, работе или социальных правах иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":false,"text_source":"metadata_only","created_at":"2026-09-15T14:59:03Z","input_tokens":414,"output_tokens":239,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":null,"source_kind":"metadata","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:42+00:00',NULL,'RCL/12405700','{"eli":"DU/2026/1347","display_address":"Dz.U. 2026 poz. 1347","title":"Ustawa z dnia 4 września 2026 r. o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw","act_date":"2026-09-04","promulgation_date":"2026-10-16","entry_into_force":"2026-12-01","in_force":"IN_FORCE","status":"obowiązujący","text_pdf_url":"https://api.sejm.gov.pl/eli/acts/DU/2026/1347/text.pdf","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001347","fetched_at":"2026-10-19T19:28:27.486217Z"}','2026-12-01',NULL,NULL,NULL,NULL,'UD332',NULL,'["2821-001", "2821-002", "2821-004", "2821-005"]',NULL,'2026-09-04','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-15","print_number":"2821","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-16","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-16","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-29","sitting_num":63,"sub_committee":fal