INSERT INTO "bills" VALUES(10,'2865','Rządowy projekt ustawy o zmianie ustawy o usługach hotelarskich oraz usługach pilotów wycieczek i przewodników turystycznych oraz niektórych innych ustaw','2026-10-09T12:06:11+00:00','2026-10-08',1,'analyzed','["text:uchodzcy", "text:legalizacja"]','{"term":10,"number":"2865","title":"Rządowy projekt ustawy o zmianie ustawy o usługach hotelarskich oraz usługach pilotów wycieczek i przewodników turystycznych oraz niektórych innych ustaw","description":"projekt dotyczy doprecyzowania pojęcia usługi hotelarskiej poprzez przyjęcie, że za usługę hotelarską uznaje się krótkotrwałą usługę trwającą nie dłużej niż 30 dni i że pojęcie to jest tożsame z pojęciem \"najmu krótkoterminowego\", utworzenia Centralnego Wykazu Turystycznego Obiektów Noclegowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-21","document_date":"2026-07-21","change_date":"2026-10-09T12:06:11Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-87-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-87-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-21","print_number":"2865","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-29","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-29","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-02","committee_code":"STR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-02","committee_code":"INF","sub_committe