INSERT INTO "bills" VALUES(10,'2867','Rządowy projekt ustawy o zmianie ustawy - Prawo o ustroju sądów powszechnych oraz niektórych innych ustaw','2026-10-23T08:25:42+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"2867","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o ustroju sądów powszechnych oraz niektórych innych ustaw","description":"projekt dotyczy uregulowania na nowo dwóch obszarów dotyczących funkcjonowania sądownictwa powszechnego, odnoszących się do sytuacji prawnej sędziów: możliwości dalszego pełnienia służby przez sędziego po osiągnięciu wieku uprawniającego do przejścia w stan spoczynku oraz delegowań, w szczególności delegowań pozaorzeczniczych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-10-23T08:25:42Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2869','Rządowy projekt ustawy o zmianie ustawy o Żandarmerii Wojskowej i wojskowych organach porządkowych oraz niektórych innych ustaw','2026-10-23T07:16:33+00:00',NULL,0,'skipped_text_prefilter','["text:straz_graniczna", "text:granica_panstwowa"]','{"term":10,"number":"2869","title":"Rządowy projekt ustawy o zmianie ustawy o Żandarmerii Wojskowej i wojskowych organach porządkowych oraz niektórych innych ustaw","description":"projekt dotyczy rozszerzenia właściwości podmiotowej formacji i poszerzenia możliwości wykorzystywania funkcjonujących już w strukturach Żandarmerii Wojskowej narzędzi do wykrywania i ścigania sprawców przestępstw i wykroczeń, w tym skarbowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-10-23T07:16:33Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (straz_graniczna×7, granica_panstwowa×9)','2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2870','Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych','2026-10-23T08:54:29+00:00','2026-10-22',1,'analyzed','["text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"2870","title":"Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych","description":"projekt dotyczy wprowadzenia stałych i jednolitych zasad przygotowania i zabezpieczania najważniejszych wydarzeń państwowych oraz międzynarodowych organizowanych w Polsce. Dzięki nowym przepisom służby będą mogły sprawniej planować działania i skuteczniej reagować na zagrożenia, w tym o charakterze terrorystycznym. Rozwiązania zastąpią przepisy przygotowywane dotychczas odrębnie dla poszczególnych wydarzeń","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-10-23T08:54:29Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-114-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-114-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-22","print_number":"2870","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-29","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-29","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-03","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-03","print_number":"3063","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3063/3063.pdf