INSERT INTO "bills" VALUES(10,'2883','Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym','2026-09-01T19:48:08',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2883","title":"Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym","description":"projekt dotyczy wyznaczenia stref wielofunkcyjnych z zabudową zagrodową bez konieczności uwzględniania posiadanych już rezerw terenów budowlanych w gminie; umożliwienia wydawania decyzji o warunkach zabudowy zagrodowej, czyli zabudowy powiązanej z prowadzonym gospodarstwem, również poza obszarami uzupełnienia zabudowy, pod warunkiem spełnienia ustawowych przesłanek dotyczących statutu rolnika, ładu przestrzennego, dostępu do drogi publicznej, uzbrojenia terenu oraz kontynuacji funkcji i parametrów zabudowy wynikających z analizy urbanistycznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-20","document_date":"2026-07-20","change_date":"2026-09-01T19:48:08","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2884','Poselski projekt ustawy o zmianie ustawy o znakach Sił Zbrojnych Rzeczypospolitej Polskiej','2026-09-21T09:49:14+00:00',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2884","title":"Poselski projekt ustawy o zmianie ustawy o znakach Sił Zbrojnych Rzeczypospolitej Polskiej","description":"projekt dotyczy zmiany zapisów dotyczących prawa posiadania sztandaru jednostki wojskowej. Nowelizacja zakłada, że prawo do posiadania sztandaru będzie przysługiwało jednostkom wojskowym Sił Zbrojnych Rzeczypospolitej Polskiej przeznaczonym do prowadzenia walki zbrojnej lub zabezpieczenia bojowego działań oraz szkołom wojskowym. Zgodnie z obowiązującym stanem prawnym prawo posiadania sztandaru przysługuje jednostkom liniowym wszystkich rodzajów sił zbrojnych oraz szkołom wojskowym. W rozumieniu zmienianej ustawy jednostką liniową jest samodzielna jednostka organizacyjna zdolna do prowadzenia walki zbrojnej lub zabezpieczenia bojowego działań.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-20","document_date":"2026-07-20","change_date":"2026-09-21T09:49:14Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-09-22T10:06:24+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2885','Poselski projekt ustawy o zmianie ustawy o działalności leczniczej i ustawy o finansach publicznych','2026-09-01T17:51:32+00:00',NULL,0,'analyzed','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"2885","title":"Poselski projekt ustawy o zmianie ustawy o działalności leczniczej i ustawy o finansach publicznych","description":"projekt dotyczy objęcia obowiązkiem zamieszczania informacji w Centralnym Rejestrze Umów Jednostek Sektora Finansów Publicznych podmiotów leczniczych działających w formie spółek kapitałowych, w których wskazane podmioty publiczne, samodzielnie albo wspólnie, bezpośrednio lub pośrednio, dysponują większością głosów. Projekt nie obejmuje prywatnych podmiotów leczniczych wyłącznie z tego powodu, że zawarły umowę z Narodowym Funduszem Zdrowia. Projekt reguluje również zakładanie kont objętych nim podmiotów w systemie CRU.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-17","document_date":"2026-07-17","change_date":"2026-09-01T17:51:32Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-17","print_number":"2885","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-07-23","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"ZDR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"FPB","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-17","print_number":"2885","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-07-23","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]}]','071ac52b9a8726ebe38dde2721ac79378acf7953274b6c3b6b96f0a423eb3f44','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается обязанности публикации информации о договорах медицинских учреждений в форме капитальных обществ в Центральном реестре договоров, что не затрагивает прав, обязанностей или процедур, касающихся иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.95,"rationale":"Проект касается обязанности публикации информации о договорах медицинских учреждений в форме капитальных обществ в Центральном реестре договоров, что не затрагивает прав, обязанностей или процедур, касающихся иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":9417,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T13:51:34Z","input_tokens":6030,"output_tokens":108,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:43+00:00',NULL,NULL,NULL,NULL,'{"representative":"Anna Żukowska","representative_club":"Lewica","clubs":[["Lewica",21]],"signatories":21,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["2885-001", "2885-002", "2885-003"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-17","print_number":"2885","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-07-23","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":["2885-001","2885-002","2885-003"]}',0,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'2998','Rządowy projekt ustawy o zmianie ustawy o finansowym wspieraniu produkcji audiowizualnej oraz niektórych innych ustaw','2026-10-23T08:58:09+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"2998","title":"Rządowy projekt ustawy o zmianie ustawy o finansowym wspieraniu produkcji audiowizualnej oraz niektórych innych ustaw","description":"projekt dotyczy: uproszczenia procedur i zwalczenia negatywnych zjawisk w dziedzinie produkcji audiowizualnej. Proponowane rozwiązania w szczególności polegają na wprowadzeniu: nowych okresów rozliczeniowych dla wniosków o wsparcie finansowe i nowego terminu na składanie takich wniosków, możliwości ustanawiania zabezpieczenia na środkach zdeponowanych na kontach powierniczych w bankach jako zachęty, zmian dotyczących raportowania przed podmioty prowadzące kina, a także zmian dotyczących przekazywania kopii filmu do Filmoteki Narodowej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-10-23T08:58:09Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2999','Rządowy projekt ustawy o zmianie ustawy o rybołówstwie morskim oraz ustawy o organizacji rynku rybnego','2026-10-09T12:06:59+00:00','2026-10-08',1,'analyzed','["text:obywatelstwo", "text:legalizacja", "text:straz_graniczna"]','{"term":10,"number":"2999","title":"Rządowy projekt ustawy o zmianie ustawy o rybołówstwie morskim oraz ustawy o organizacji rynku rybnego","description":"projekt dotyczy umożliwienia stosowania w krajowym porządku prawnym zrewidowanych przepisów Unii Europejskiej w zakresie kontroli rybołówstwa; projekt reguluje raportowanie działalności połowowej, monitorowanie statków rybackich, zdalne monitorowanie elektroniczne, weryfikację mocy silników i pojemności statków, ważenie produktów rybołówstwa, rejestry naruszeń i kapitanów, system punktów za poważne naruszenia, rybołówstwo rekreacyjne, elektroniczny obieg dokumentów na rynku rybnym oraz sankcje pieniężne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-10-09T12:06:59Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-95-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-95-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-30","print_number":"2999","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"GMZ","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-02","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-17","sub_committee":false,"children":[{"stage_n