INSERT INTO "bills" VALUES(10,'3002','Rządowy projekt ustawy o zmianie ustawy - Prawo farmaceutyczne','2026-10-23T08:57:06+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3002","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo farmaceutyczne","description":"projekt dotyczy uchylenia obowiązującego od 2012 r. całkowitego zakazu reklamy aptek i punktów aptecznych; umożliwienia reklamowania usług świadczonych przez farmaceutów, takich jak: opieka farmaceutyczna, szczepienia, przeglądy lekowe czy podstawowe badania diagnostyczne; podwyższenia wysokości kary za prowadzenie reklamy niezgodnej z przepisami z 50 tys. zł do 100 tys. zł","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-05","document_date":"2026-08-05","change_date":"2026-10-23T08:57:06Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3003','Rządowy projekt ustawy o środkach ograniczających','2026-10-23T13:15:21+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:straz_graniczna", "text:schengen", "text:nieruchomosci_cudzoziemcy"]','{"term":10,"number":"3003","title":"Rządowy projekt ustawy o środkach ograniczających","description":"projekt dotyczy określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-06","document_date":"2026-08-06","change_date":"2026-10-23T13:15:21Z","passed":false,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-126-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-126-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3003","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-03","sitting_num":64,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"ASW","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"GOR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","