ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"GOR","sub_committee":false,"committee_name":"Komisja Gospodarki i Rozwoju","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-19","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-10-19","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/3003/attachment/spr_3003.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3251","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3251/3251.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":5,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-23","sitting_num":67,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"GOR","sub_committee":false,"committee_name":"Komisja Gospodarki i Rozwoju","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]}]','b76012c755944d2531b7d5dfbb1a123301c2f7b1f5603153fb35eab5d0d18ffd','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Закон вводит общий режим санкций ЕС и польских «środki ograniczające», в т.ч. за вмешательство и манипуляцию информацией против безопасности Польши. Для иностранцев важно, что включение в санкционный список МВД автоматически ведёт к занесению в реестр нежелательных лиц и отказу во въезде, визе и ВНЖ.","key_changes":["Единый порядок применения санкций ЕС и польских «środki ograniczające».","Новое основание санкций — вмешательство и манипуляция информацией.","Внесение в санкционный список МВД ведёт к записи в wykaz cudzoziemców.","Запись в wykaz — новое основание отказа во въезде, визе и виде на жительство.","За помощь въезду лица под санкциями предусмотрена уголовная ответственность."],"affected_groups":["иностранцы, попавшие в санкционный список МВД","иностранцы, которым могут отказать во въезде, визе или ВНЖ из‑за санкций","иностранные работники компаний, попавших под санкции"],"practical_impact":"Если иностранец будет включён в польский санкционный список, его автоматически внесут в реестр нежелательных лиц, что повлечёт запрет въезда и отказы в визе и виде на жительство; обжалование возможно только в административном суде, при этом данные списка будут публичны. Работники санкционированных работодателей (включая иностранцев) смогут требовать выплату задолженной зарплаты из FGŚP.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования, за исключением ст. 73, которая вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.9,"rationale":"Акт прямо меняет ustawę o cudzoziemcach, делая санкционный список основанием для внесения в реестр нежелательных иностранцев и отказа во въезде, визе и ВНЖ, поэтому это ключевое регулирование легализации пребывания.","mnemonic_candidate":"Санкционный въездной барьер","mnemonic_fallback":"Санкционный запрет на въезд","mnemonic_basis":"Иностранец, внесённый в санкционный список МВД, автоматически попадает в wykaz cudzoziemców, których pobyt jest niepożądany, что влечёт запрет въезда и негативные визово‑миграционные решения.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":3453,"truncated":false,"text_source":"scan","created_at":"2026-10-21T18:29:53Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3251/3251.pdf","source_kind":"committee_report","revision":2,"text_sha256":"07df84716fdb16a3e27e382699ddff8cc3f0ab167334031ea4c64459c4bfdf7a","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3251/3251.pdf","members":[],"container_sha256":"","sha256":"07df84716fdb16a3e27e382699ddff8cc3f0ab167334031ea4c64459c4bfdf7a","role":"unknown","text":"","pages":69,"page_start":1,"page_end":69,"text_start":0,"text_end":null,"text_sha256":"","losses":["text unavailable; sent as PDF pages"]}],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":"2026-10-23T18:01:03Z"}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:17+00:00','{"term":10,"number":"RPW/27024/2026","title":"Rządowy projekt ustawy o środkach ograniczających","description":"określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-06","print_number":"3003","eu_related":true,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdraw