INSERT INTO "bills" VALUES(10,'3007','Rządowy projekt ustawy o pomocy beneficjentom - osobom fizycznym poszkodowanym w związku z realizacją Programu Priorytetowego "Czyste Powietrze"','2026-10-09T12:14:12+00:00','2026-10-08',1,'skipped_text_prefilter','[]','{"term":10,"number":"3007","title":"Rządowy projekt ustawy o pomocy beneficjentom - osobom fizycznym poszkodowanym w związku z realizacją Programu Priorytetowego \"Czyste Powietrze\"","description":"projekt dotyczy pomocy osobom, które skorzystały z programu \"Czyste Powietrze\", ale z powodu np. nieuczciwych działań wykonawców nie zrealizowały prawidłowo inwestycji i muszą oddać otrzymane dofinansowanie. Nowe przepisy mają chronić poszkodowanych przed koniecznością zwrotu pieniędzy, jeżeli nieprawidłowości powstały bez ich winy. W określonych przypadkach będą oni mogli zawiesić spłatę, uzyskać ulgę, a nawet zostać zwolnieni z obowiązku zwrotu dofinansowania.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-13","document_date":"2026-08-13","change_date":"2026-10-09T12:14:12Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-10T12:46:19+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3008','Rządowy projekt ustawy o mediatorach sądowych, instytucjach szkolących w zakresie mediacji i Krajowym Rejestrze Mediatorów','2026-09-22T09:08:39+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3008","title":"Rządowy projekt ustawy o mediatorach sądowych, instytucjach szkolących w zakresie mediacji i Krajowym Rejestrze Mediatorów","description":"projekt dotyczy usunięcia dotychczas zidentyfikowanych dysfunkcyjności m.in. przez utworzenie Krajowego Rejestru Mediatorów w formie systemu teleinformatycznego, wprowadzenia jednolitych standardów szkoleniowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-07","document_date":"2026-08-07","change_date":"2026-09-22T09:08:39Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-119-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-119-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-07","print_number":"3008","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-07","print_number":"3008","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]}]}]','1b3d3a3e7b8aa2df320568f3b1e3a2678400818833120f9da0c16399a0624cba','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Законопроект создаёт статус mediator sądowy (судебный медиатор) и электронный Krajowy Rejestr Mediatorów (национальный реестр медиаторов), вводит единые стандарты обучения. Иностранцы затронуты лишь как возможные кандидаты в медиаторы.","key_changes":["Вместо списков постоянных медиаторов вводится единый электронный Krajowy Rejestr Mediatorów","Без PESEL в заявлении указывается паспорт, документ путешественника или документ по ustawa o cudzoziemcach","Лица без польского гражданства прилагают подтверждение знания польского языка не ниже B2","Требования: 26 лет, высшее образование, базовое (40 ч) и специализированное обучение, несудимость","Учитывается зарубежное высшее образование, признанное в Польше; в реестре можно указать языки медиации"],"affected_groups":["иностранцы, желающие стать судебными медиаторами","иностранцы, работающие медиаторами по действующим спискам"],"practical_impact":"Иностранец без PESEL сможет подать заявление о внесении в реестр, указав паспорт или документ по ustawa o cudzoziemcach, но обязан подтвердить знание польского на уровне B2. Для большинства иностранцев ничего не меняется.","effective_date":"Закон вступает в силу 1 сентября 2027 г.","confidence":0.85,"rationale":"Иностранцы упоминаются лишь в контексте формальных требований к кандидатам в медиаторы, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":138006,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3008/3008.pdf","source_kind":"print","revision":2,"text_sha256":"05f8b358d8b13983313de7c36a3987d45a652f65878c2f5d5c8b123702bad1ab","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:43+00:00',NULL,'RCL/12400301',NULL,NULL,NULL,NULL,NULL,NULL,'UD237',NULL,'["3008-001", "3008-002"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-07","print_number":"3008","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-20","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3008/3008.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"05f8b358d8b13983313de7c36a3987d45a652f65878c2f5d5c8b123702bad1ab","analysis_revision":2,"seen_supplements":["3008-001","3008-002"]}',2,NULL,NULL,NULL,'metadata','below_bar',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3009','Rządowy projekt ustawy o zmianie ustawy - Kodeks karny wykonawczy','2026-10-23T08:31:37+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3009","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks karny wykonawczy","description":"projekt dotyczy rozszerzenia możliwości odbywania kary pozbawienia wolności w systemie dozoru elektronicznego (SDE)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-07","document_date":"2026-08-07","change_date":"2026-10-23T08:31:37Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3010','Rządowy projekt ustawy o umorzeniu należności dochodzonych przez Zakład Ubezpieczeń Społecznych powstałych przed dniem 1 stycznia 1999 r.','2026-10-14T12:11:49+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"3010","title":"Rządowy projekt ustawy o umorzeniu należności dochodzonych przez Zakład Ubezpieczeń Społecznych powstałych przed dniem 1 stycznia 1999 r.","description":"projekt dotyczy umorzenia starych zobowiązań wobec ZUS. Chodzi o należności dotyczące składek powstałych przed 1 stycznia 1999 r., czyli przed reformą systemu ubezpieczeń społecznych. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-12","document_date":"2026-08-12","change_date":"2026-10-14T12:11:49Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-15T17:48:35+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3011','Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania cywilnego','2026-10-09T12:15:59+00:00','2026-10-08',1,'skipped_text_prefilter','[]','{"term":10,"number":"3011","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania cywilnego","description":"projekt dotyczy usprawnienia rozpatrywania spraw dotyczących ubezpieczeń społecznych. Sądy będą mogły w większej liczbie przypadków uchylić błędną decyzję organu rentowego, np. Zakładu Ubezpieczeń Społecznych, i przekazać sprawę do ponownego rozpatrzenia. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-12","document_date":"2026-08-12","change_date":"2026-10-09T12:15:59Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-10T12:46:19+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
