ge_type":"CommitteeReport","date":"2026-09-16","print_number":"3098","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3098/3098.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-09","sitting_num":66,"decision":"zakończono II czytanie","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":435,"no":2,"abstain":0,"not_participating":23,"sitting":67,"voting_number":202,"date":"2026-10-22T17:19:05Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/202/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','2fd6d4be9d82b1316a0621c95ecb082bd9af4c4bc3aff871aa4feb28a263746d','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Закон разрешает ратификацию договора Польши с Филиппинами о передаче осуждённых для отбывания наказания в своей стране. Это касается в частности граждан Филиппин в польских тюрьмах и граждан Польши в тюрьмах на Филиппинах.","key_changes":["Польша даёт согласие на ратификацию договора с Филиппинами","Договор касается передачи лиц, осуждённых к лишению свободы","Рассматривается сотрудничество в уголовно‑правовой сфере","Закон о ратификации вступит в силу через 14 дней после опубликования"],"affected_groups":["граждане Филиппин, осуждённые в Польше","граждане Польши, осуждённые на Филиппинах","члены семей таких осуждённых"],"practical_impact":"Для осуждённых появится международно‑правовая основа просить перевод для отбывания наказания в государстве своего гражданства; конкретная процедура будет определяться самим договором Польша–Филиппины.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.73,"rationale":"Акт касается только передачи уже осуждённых между Польшей и Филиппинами и затрагивает иностранцев косвенно, без изменения правил пребывания или работы.","mnemonic_candidate":"филиппинский обмен заключённых","mnemonic_fallback":"договор о передаче осуждённых","mnemonic_basis":"Закон разрешает ратификацию договора Польша–Филиппины о передаче осуждённых для отбытия наказания в государстве их гражданства.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":599,"truncated":false,"text_source":"pdf","created_at":"2026-10-23T18:21:01Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"text-v2:cacac4badbcb206708724fa4fb8df6cef21f0d3c38fef2c7b0d08a3fa9e2a50f","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","members":[],"container_sha256":"e71112a667cbb2c6754e057a114524726937ca881259d85fa72e22541acb2bd9","sha256":"e71112a667cbb2c6754e057a114524726937ca881259d85fa72e22541acb2bd9","role":"bill","text":"","pages":1,"page_start":1,"page_end":1,"text_start":0,"text_end":599,"text_sha256":"aaa48ea0b36aeb3b6aa58a1e2a37943518ad3d1ca2df269727204cdaf04ead9c","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3013/attachment/3013_u3.pdf","text_sha256":"aaa48ea0b36aeb3b6aa58a1e2a37943518ad3d1ca2df269727204cdaf04ead9c","block_i