INSERT INTO "bills" VALUES(10,'3033','Poselski projekt ustawy o zmianie ustawy o transporcie kolejowym','2026-09-02T06:41:16+00:00',NULL,0,'analyzed','["text:obywatelstwo"]','{"term":10,"number":"3033","title":"Poselski projekt ustawy o zmianie ustawy o transporcie kolejowym","description":"projekt dotyczy wprowadzenia mechanizmów ochrony polskiego oraz unijnego rynku kolejowych przewozów rzeczy przed sytuacjami, w których przedsiębiorcy kontrolowani przez podmioty pochodzące z państw trzecich uzyskują dostęp do rynku Rzeczypospolitej Polskiej, podczas gdy przewoźnicy kolejowi z Polski oraz innych państw członkowskich Unii Europejskiej nie posiadają rzeczywistego, porównywalnego i niedyskryminacyjnego dostępu do rynku kolejowych przewozów rzeczy w tych państwach","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-11","document_date":"2026-06-11","change_date":"2026-09-02T06:41:16Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-11","print_number":"3033","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-11","print_number":"3033","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]}]}]','7a31a4771a25c52a34eb84e11caaccf5acd63914f0b5dc1c96fc379ac18172a9','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Projekt dotyczy zasad licencjonowania przewoźników kolejowych przewożących towary i ochrony rynku przed podmiotami kontrolowanymi przez kapitał spoza UE, a nie praw czy obowiązków cudzoziemców jako osób fizycznych przebywających w Polsce.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Projekt dotyczy zasad licencjonowania przewoźników kolejowych przewożących towary i ochrony rynku przed podmiotami kontrolowanymi przez kapitał spoza UE, a nie praw czy obowiązków cudzoziemców jako osób fizycznych przebywających w Polsce.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v3","input_chars":11858,"truncated":true,"text_source":"excerpts","created_at":"2026-09-09T18:00:20Z","input_tokens":7418,"output_tokens":137,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:45+00:00',NULL,NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PiS",47],["RozwojPlus",5]],"signatories":52,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["3033-001"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-11","print_number":"3033","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":["3033-001"]}',0,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3034','Poselski projekt ustawy o zmianie ustawy - Kodeks rodzinny i opiekuńczy i niektórych innych ustaw','2026-09-04T10:14:50',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3034","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks rodzinny i opiekuńczy i niektórych innych ustaw","description":"projekt dotyczy wprowadzenia szeregu zmian prawnych dotyczących modelu opieki nad dzieckiem, którego rodzice nie mieszkają razem czyli tzw. pieczy współdzielonej, polegającej na naprzemiennym mieszkaniu w powtarzających się porównywalnych okresach z dwojgiem rodziców","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-31","document_date":"2026-07-31","change_date":"2026-09-04T10:14:50","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3035','Poselski projekt ustawy o zmianie ustawy o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawy o Centralnym Biurze Antykorupcyjnym, ustawy o Służbie Kontrwywiadu Wojskowego oraz niektórych innych ustaw','2026-10-23T06:24:57+00:00',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3035","title":"Poselski projekt ustawy o zmianie ustawy o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawy o Centralnym Biurze Antykorupcyjnym, ustawy o Służbie Kontrwywiadu Wojskowego oraz niektórych innych ustaw","description":"projekt dotyczy wyłączenia obiektów budowlanych usytuowanych na terenach zamkniętych ustalonych decyzją szefów służb specjalnych od obowiązku zamieszczania informacji dotyczących inwestycji na stronach Biuletynu Informacji Publicznej właściwego organu administracji architektoniczno-budowlanej, nie będzie wymagana decyzja o pozwoleniu na rozbiórkę oraz zgłoszenie rozbiórki budynków i budowli zlokalizowanych na terenach zamkniętych ustalonych również decyzją szefów służb specjalnych oraz wyłączenia obowiązku zgłoszenia zmiany sposobu użytkowania obiektu budowlanego lub jego części w zakresie obiektów budowlanych zlokalizowanych na tych terenach; Poszerza się ustawowy katalog zadań ABW, AW, CBA, SKW i SWW o zapewnienie ochrony Szefom tych służb (oraz w uzasadnionych przypadkach wskazanemu funkcjonariuszowi lub pracownikowi)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-10-23T06:24:57Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×2)','2026-09-07T13:52:14+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3036','Poselski projekt ustawy o zmianie ustawy o elektromobilności i paliwach alternatywnych','2026-09-07T06:15:16+00:00',NULL,0,'analyzed','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3036","title":"Poselski projekt ustawy o zmianie ustawy o elektromobilności i paliwach alternatywnych","description":"projekt dotyczy rozszerzenia katalogu dopuszczalnych sposobów wykorzystania dochodów z opłat o finansowanie zadań własnych gminy w zakresie lokalnego transportu zbiorowego, o których mowa w art. 7 ust. 1 pkt 4 ustawy o samorządzie gminnym. Projektowana zmiana zwiększy swobodę gmin w wykorzystywaniu tych środków, przy zachowaniu ich przeznaczenia na cele związane z transportem zbiorowym.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-07T06:15:16Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-22","print_number":"3036","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-07-27","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"STR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-22","print_number":"3036","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-07-27","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"STR","sub_committee":false,"committee_name":"Komisja Samorządu Terytorialnego i Polityki Regionalnej","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]}]}]','6ee2e3f0f593e02aed68e9628a634f1737bbdbb908bc7c8aef4a610dc4be03be','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект расширяет перечень целей, на которые гмины могут тратить доходы от платы за въезд в зоны чистого транспорта (SCT), добавляя финансирование местного общественного транспорта. Касается бюджетных полномочий гмин, а не иностранцев.","key_changes":["В art. 39 ust. 6 ustawy o elektromobilności добавляется пункт 7 о финансировании задач гмины","Доходы от платы за въезд в SCT можно направлять на организацию перевозок, новые маршруты, частоту"],"affected_groups":["жители гмин с зонами чистого транспорта (SCT)","органы местного самоуправления"],"practical_impact":"Для иностранцев ничего не меняется в правовом статусе; возможное косвенное улучшение местного общественного транспорта в городах с SCT.","effective_date":"Вступает в силу через 14 дней со дня опубликования","confidence":0.95,"rationale":"Проект касается только правил расходования гминных доходов от платы за въезд в SCT и не затрагивает права иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":13014,"truncated":false,"text_source":"pdf","created_at":"2026-09-15T13:51:13Z","input_tokens":6797,"output_tokens":393,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3036/3036.pdf","source_kind":"print","revision":1,"text_sha256":"d6b187fe7fd3b526f85f4a507d1e335c7ef6fa3bcda3fa258500d42422bf9ac5",