INSERT INTO "bills" VALUES(10,'3038','Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska','2026-10-22T10:25:58+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3038","title":"Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"projekt dotyczy stworzenia prawnych podstaw do uwzględniania przez organy ochrony środowiska szczególnego charakteru obiektów sportowych o istotnym znaczeniu dla szkolenia sportowego oraz krajowego i międzynarodowego współzawodnictwa sportowego przy określaniu dopuszczalnych poziomów hałasu oraz warunków ich funkcjonowania","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-03","document_date":"2026-07-31","change_date":"2026-10-22T10:25:58Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-10-23T17:54:29+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3039','Poselski projekt ustawy o zmianie ustawy o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej','2026-09-04T09:09:10+00:00',NULL,0,'analyzed','["cudzoziemcy", "ochrona_cudzoziemcow"]','{"term":10,"number":"3039","title":"Poselski projekt ustawy o zmianie ustawy o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej","description":"projekt dotyczy rozszerzenia katalogu osób uprawnionych do nieodpłatnego pobytu w obiektach zbiorowego zakwaterowania, umożliwienia wojewodom finansowania transportu mieszkańców tych obiektów w sytuacji wymagającej relokacji lub zapewnienia świadczeń zdrowotnych, umożliwienie organizacjom pozarządowym prowadzenia tego typu obiektów z pominięciem otwartego konkursu ofert","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-03","document_date":"2026-08-03","change_date":"2026-09-04T09:09:10Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-03","print_number":"3039","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"ASW","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-03","print_number":"3039","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]}]','cb84442d86c41c7859428d34b37b92124473038d0b68849912688cd593427255','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект вносит изменения в ustawa o udzielaniu cudzoziemcom ochrony na terytorium RP (закон о предоставлении иностранцам защиты в Польше) в части работы центров коллективного размещения и доступа к медицинской помощи для лиц под временной защитой. Расширяется список тех, кто может бесплатно проживать в таких центрах: несовершеннолетние под опекой проживающих, учащиеся до 26 лет, одинокие матери и получатели минимальной польской пенсии. Те же категории получают право на медицинские услуги, даже если они не живут в центре коллективного размещения — подтверждение через заявление под угрозой уголовной ответственности за ложные сведения. Воеводы смогут финансировать транспорт жильцов при релокации или для доступа к медпомощи, а также поручать управление центрами НГО и профсоюзам без открытого конкурса. Оценочная стоимость — около 223 млн зл. в год.","key_changes":["Право на бесплатное проживание в центрах коллективного размещения для несовершеннолетних под опекой проживающих там лиц","Право проживания для лиц до 26 лет, которые жили в центре до 1 июля 2026 г. и продолжают учёбу в дневной школе или на стационаре в вузе","Право проживания для одиноких матерей (без супруга или чей супруг вне территории Польши)","Право проживания для лиц пенсионного возраста с польской пенсией не выше минимальной","Право на медицинские услуги для этих категорий, даже если они не живут в центре, подтверждаемое заявлением под уголовной ответственностью","Воеводы могут оплачивать транспорт жильцов и передавать управление центрами НГО/профсоюзам без открытого конкурса"],"affected_groups":["лица под временной защитой (в основном граждане Украины)","несовершеннолетние под опекой жильцов центров","учащиеся и студенты до 26 лет","одинокие матери с детьми","получатели минимальной польской пенсии"],"practical_impact":"Перечисленные категории смогут бесплатно жить в центрах коллективного размещения и получать медицинскую помощь даже при проживании вне центра, подав заявление о соответствии условиям. Для подтверждения права потребуется письменное заявление под угрозой уголовной ответственности за ложные сведения.","effective_date":"Закон вступает в силу через 14 дней после опубликования.","confidence":0.9,"rationale":"Проект не меняет основания легализации пребывания, но напрямую расширяет социальные права (жильё, медпомощь) для лиц под временной защитой, что соответствует категории social и оценке 3.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v1","input_chars":20001,"truncated":false,"text_source":"pdf","created_at":"2026-09-07T13:53:03Z","input_tokens":10317,"output_tokens":951,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3039/3039.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:17+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["3039-001", "3039-002", "3039-003", "3039-004", "3039-005", "3039-006"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-03","print_number":"3039","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3039/3039.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_revision":1,"seen_supplements":["3039-001","3039-002","3039-003","3039-004","3039-005","3039-006"]}',0,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Льготы в центрах размещения","language":"ru","basis":"Проект расширяет право уязвимых групп под временной защитой на бесплатное проживание в центрах коллективного размещения и доступ к медпомощи, в том числе вне центров.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3066','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw','2026-09-18T12:52:53+00:00',NULL,0,'analyzed','["text:obywatele_ukrainy", "text:straz_graniczna"]','{"term":10,"number":"3066","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw","description":"projekt dotyczy dostosowania obowiązujących regulacji prawa karnego procesowego do standardów konstytucyjnych oraz międzynarodowych, w szczególności w zakresie wdrożenia wybranych przepisów Unii Europejskiej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-27","document_date":"2026-03-27","change_date":"2026-09-18T12:52:53Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-03-27","print_number":"3066","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-03-27","print_number":"3066","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}]','7448223276dac7cd223094a588925715d3c5394cee777d50c71ac44b1be18e96','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Президентский проект реформы Kodeks postępowania karnego (Уголовно-процессуальный кодекс) и ряда других законов. Для иностранцев важны расширенные права на переводчика и перевод документов в уголовном процессе, обязательное разъяснение прав тем, кто плохо владеет польским, и изменение основания для ареста при отсутствии постоянного места пребывания.","key_changes":["Art. 72 k.p.k.: перевод документов по требованию обвиняемого и право жаловаться на качество перевода","Новый art. 300 §1a: обязательное письменное разъяснение прав лицу, не владеющему польским","Art. 258 §1 пкт 1: риск побега оценивается с учётом места пребывания в Польше и других странах ЕС","Расширены гарантии доступа к адвокату при первом допросе (art. 301) и по европейскому ордеру на арест","Тайна присяжного переводчика включена в перечень защищённых тайн (art. 180 §2)","Техническая поправка к art. 72 ustawy o pomocy obywatelom Ukrainy (закон о помощи гражданам Украины)"],"affected_groups":["иностранцы, участвующие в уголовном процессе в Польше (подозреваемые, обвиняемые)","лица, не владеющие польским языком","граждане других стран ЕС","присяжные переводчики","граждане Украины (техническая поправка)"],"practical_impact":"Иностранец, оказавшийся подозреваемым или обвиняемым, сможет требовать перевода дополнительных документов и оспаривать качество перевода, а также получит письменное разъяснение прав; отсутствие постоянного места пребывания в Польше по-прежнему может служить аргументом для ареста, но учитывается и место жительства в других странах ЕС.","effective_date":"Закон вступает в силу через 3 месяца со дня опубликования.","confidence":0.85,"rationale":"Проект не касается легализации пребывания или работы, но содержит конкретные процессуальные гарантии для иностранцев и неполяков в уголовном процессе, что даёт косвенное влияние.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":72553,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T18:00:45Z","input_tokens":38344,"output_tokens":997,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3066/3066.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-10-28T19:18:45+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-03-27","print_number":"3066","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-03","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3066/3066.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"anal