INSERT INTO "bills" VALUES(10,'RCL/12410853','Projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych','2026-10-01T00:00:00+00:00',NULL,NULL,'linked','["text:pobyt_kwalifikowany"]','{"term":10,"number":"RCL/12410853","title":"Projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych","description":"FINANSE PUBLICZNE; OPŁATY; PODATKI; finanse publiczne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-01","document_date":"2026-09-14","change_date":"2026-10-01T00:00:00Z","eu_related":false,"rcl_num":"RM-0610-148-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12410853","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2026-06-01","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","date":"2026-06-01","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","date":"2026-06-01","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','8d7551a058d37cfb2266321e3776260789132559862c4ea087f5a7eb36e2da9a','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила opłata miejscowa и opłata uzdrowiskowa (местный и курортный сборы). Их будет платить каждый, кто хотя бы одну ночь проживает в гостинице, пансионате или санатории в таких местностях, а удерживать сбор будет объект размещения. Кроме того, растёт порог освобождения от PCC при продаже движимых вещей.","key_changes":["Сбор взимается за каждую ночь проживания в объекте размещения, независимо от цели поездки","Максимальные ставки: 5,00 zł и 5,50 zł (местный), 6,86 zł за ночь (курортный)","Освобождение при проживании более 29 ночей подряд в объектах одной гмины","Сбор удерживают объекты размещения (płatnik); они могут требовать предоплату за заявленные ночи","Лимит освобождения от PCC при продаже движимых вещей: с 1000 до 3000 zł"],"affected_groups":["иностранные туристы и гости","иностранцы, живущие в гостиницах и хостелах в курортных и туристических местностях","сотрудники дипломатических и консульских представительств, не являющиеся гражданами Польши"],"practical_impact":"При заселении в гостиницу или санаторий в местности со сбором иностранец, как и гражданин Польши, платит его объекту размещения, возможно авансом за заявленные ночи; при проживании более 29 ночей подряд сбор не взимается. Иностранцы специально не выделяются, кроме сохранённого освобождения для дипперсонала без постоянного места пребывания в Польше.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 3 и ст. 10 (изменения PCC), которые вступают в силу через 14 дней после опубликования.","confidence":0.8,"rationale":"Это общая реформа местных сборов и налогов, которая касается всех одинаково; иностранцы упомянуты только в связи с освобождением для дипперсонала, поэтому влияние маргинальное.","changes_since_previous":["Изменены максимальные ставки местного сбора: теперь до 5,00 zł и до 5,50 zł за ночь вместо указанных ранее 3,56 zł и 5,03 zł; курортный сбор остался до 6,86 zł","Из условий введения местного сбора исключён критерий благоприятных климатических условий; достаточно ландшафтных достоинств местности, критерии которых определит rozporządzenie Rady Ministrów","Рада гмины может дифференцировать ставки или вводить освобождения по месту жительства, возрасту, наличию Karta Dużej Rodziny, степени инвалидности, сезону и длительности пребывания","Для объектов размещения до конца 2029 г. разрешена подача ежемесячной информации о сборе в бумажном виде"]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":25964,"truncated":false,"text_source":"documents","created_at":"2026-09-28T16:14:59Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206829/13206830/dokument796915.zip","source_kind":"rcl","revision":2,"text_sha256":"c2f429077b42f7e6a40a19d8dfd9157ac90fcc055b0f22523eb1ffdcb833dfc2","source_checked_at":"2026-09-28T16:14:59Z"}',0,NULL,'2026-09-09T14:40:20+00:00','2026-10-01T18:56:20+00:00',NULL,'3099',NULL,NULL,NULL,NULL,'{"id":12410853,"title":"Projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych","applicant":"Minister Finansów i Gospodarki","wykaz_number":"UD372","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-podatkach-i-oplatach-lokalnych-oraz-ustawy-o-podatku-od-czynnosci-cywilnoprawnych","created":"2026-06-01","modified":"2026-09-16","departments":["finanse publiczne"],"keywords":["FINANSE PUBLICZNE","OPŁATY","PODATKI"],"status":"otwarty","term_label":"X","rm_number":"RM-0610-148-26","sejm_url":"http://www.sejm.gov.pl/Sejm7.nsf/agent.xsp?symbol=RPL&Id=RM-0610-148-26","print_number":"3099","stages":[{"id":13206780,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13206781,"number":2,"name":"Uzgodnienia","state":"reached","started":"2026-06-01","modified":"2026-08-07","folders":[{"id":13206782,"name":"Projekt","modified":"2026-06-01","documents":[{"id":779235,"name":"Projekt ustawy.docm","url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206781/13206782/dokument779235.docm","created":"2026-06-01","author":"Minister Finansów i Gospodarki"},{"id":779236,"name":"Uzasadnienie do proje