INSERT INTO "bills" VALUES(10,'RCL/12408751','Projekt ustawy o zmianie niektórych ustaw w związku z usprawnieniem funkcjonowania rynku kapitałowego','2026-10-27T00:00:00+00:00',NULL,NULL,'analyzed','[]','{"term":10,"number":"RCL/12408751","title":"Projekt ustawy o zmianie niektórych ustaw w związku z usprawnieniem funkcjonowania rynku kapitałowego","description":"RYNEK KAPITAŁOWY; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: 1) Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/2811 z dnia 23 października 2024 r. w sprawie zmiany dyrektywy 2014/65/UE w celu zwiększenia atrakcyjności publicznych rynków kapitałowych w Unii dla spółek i ułatwienia małym i średnim przedsiębiorstwom dostępu do kapitału oraz uchylenia dyrektywy 2001/34/WE (Dz. Urz. UE L 2024/2811 z 14.11.2024); 2) Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/2809 z dnia 23 października 2024 r. w sprawie zmiany rozporządzenia (UE) 2017/1129, (UE) nr 596/2014 i (UE) nr 600/2014 w celu zwiększenia atrakcyjności publicznych rynków kapitałowych w Unii dla spółek oraz ułatwienia małym i średnim przedsiębiorstwom dostępu do kapitału (Dz. Urz. UE L 2024/2809 z 14.11.2024); 3) Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/3005 z dnia 27 listopada 2024 r. w sprawie przejrzystości i rzetelności działalności ratingowej z zakresu ochrony środowiska, polityki społecznej i ładu korporacyjnego (ESG) oraz zmiany rozporządzeń (UE) 2019/2088 i (UE) 2023/2859 (Dz. Urz. UE L 2024/3005 z 12.12.2024).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-31","document_date":"2026-10-26","change_date":"2026-10-27T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12408751","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-06-26","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','d688c6ab9f93bda7ea7599377a6fce33134ecb763be2b501318591893b05b511','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается регулирования рынка капитала, проспектов эмиссии ценных бумаг и надзора за финансовыми инструментами, и не затрагивает права, статус или процедуры для иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.92,"rationale":"Законопроект касается регулирования рынка капитала, проспектов эмиссии ценных бумаг и надзора за финансовыми инструментами, и не затрагивает права, статус или процедуры для иностранцев.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":6005,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T15:47:58Z","input_tokens":4836,"output_tokens":102,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-09T14:40:41+00:00','2026-10-28T19:17:32+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12408751,"t