ders":[],"catalog_read":false},{"id":13221098,"number":5,"name":"Komitet Rady Ministrów do Spraw Cyfryzacji","state":"not_started","folders":[],"catalog_read":false},{"id":13221103,"number":6,"name":"Komitet do Spraw Europejskich","state":"not_started","folders":[],"catalog_read":false},{"id":13221108,"number":7,"name":"Komitet Społeczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13221113,"number":8,"name":"Komitet Ekonomiczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13221118,"number":9,"name":"Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13221123,"number":10,"name":"Komisja Prawnicza","state":"not_started","folders":[],"catalog_read":false},{"id":13221124,"number":11,"name":"Potwierdzenie projektu przez Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13221129,"number":12,"name":"Rada Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13221135,"number":13,"name":"Notyfikacja","state":"not_started","folders":[],"catalog_read":false},{"id":13221136,"number":14,"name":"Skierowanie projektu ustawy do Sejmu","state":"not_started","folders":[],"catalog_read":false}],"consultation_attempts":0}',NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]}],"document":{"url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221082/dokument792537.pdf","kind":"rcl","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"2d69b90bbda899ac516b9a483744c828e6c0f70f7fe9aef3a8f26c05a8a111f9","analysis_revision":1}',0,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12401805','Projekt ustawy o zapewnieniu gospodarce krajowej dostępu do surowców, w tym surowców krytycznych','2026-10-29T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12401805","title":"Projekt ustawy o zapewnieniu gospodarce krajowej dostępu do surowców, w tym surowców krytycznych","description":"GEOLOGICZNE PRAWO; gospodarka surowcami energetycznymi. Numer i tytuł aktu prawnego Unii Europejskiej: rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/1252 z dnia 11 kwietnia 2024 r. w sprawie ustanowienia ram na potrzeby zapewnienia bezpiecznych i zrównoważonych dostaw surowców krytycznych oraz zmiany rozporządzeń (UE) nr 168/2013, (UE) 2018/858, (UE) 2018/1724 i (UE) 2019/1020 (Dz. Urz. UE L 1252 z 3.5.2024, str. 1, z późn. zm.)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-05","document_date":"2025-09-05","change_date":"2026-10-29T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12401805","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-06-30","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','990bd1b565b3719cd71982e62e20ad6b1469bd0853c08cabe03f06c069c2739b',NULL,0,'text prefilter: no keyword hits','2026-09-09T14:41:28+00:00','2026-10-29T19:00:22+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12401805,"title":"Projekt ustawy o zapewnieniu gospodarce krajowej dostępu do surowców, w tym surowców krytycznych","applicant":"Minister Klimatu i Środowiska