INSERT INTO "bills" VALUES(10,'RCL/12400563','Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)','2026-10-20T00:00:00+00:00',NULL,NULL,'analyzed','["cudzoziemcy"]','{"term":10,"number":"RCL/12400563","title":"Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)","description":"CUDZOZIEMCY; sprawy wewnętrzne. Numer i tytuł aktu prawnego Unii Europejskiej: projektowana ustawa służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-31","document_date":"2026-10-09","change_date":"2026-10-20T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12400563","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-05-22","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','2774d093c90ce43756ceb3a86e5a5487bd3bf4e0efb8a7086cd7edd8616e8a84','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит в Польше систему ETIAS: гражданам безвизовых стран понадобится электронное разрешение на поездку, иначе могут отказать во въезде и в легализации пребывания. Создаётся единый Krajowy Rejestr Cudzoziemców с главным идентификатором для всех ведомств.","key_changes":["Обязательное разрешение ETIAS для въезда и всего периода безвизового пребывания, связанное с подачей на ВНЖ/ПМЖ/резидента ЕС","Без действующего ETIAS могут отказать во въезде, продлении безвиза и принять решение о возврате из Польши","Повторное рассмотрение отказа/отмены ETIAS: 7 дней, только онлайн, платно; размер пошлины установят в диапазоне, а не фиксировано","Создаётся Krajowy Rejestr Cudzoziemców и присваивается GIC – единый идентификатор иностранца, которым пользуются UdSC, ZUS, органы работы, вузы и др.","Пошлина 350 zł за отмену запрета въезда; повышаются визовые сборы (45/90 евро и 135/180 евро в указанных категориях)"],"affected_groups":["Граждане безвизовых стран, въезжающие в Польшу/Шенген","Иностранцы, находящиеся в Польше по безвизу и подающие на ВНЖ, ПМЖ, резидента ЕС","Иностранцы с польскими визами и картами pobytu","Иностранцы, работающие в Польше по разрешениям на работу, сезонной работе и по заявлениям о powierzeniu pracy","Лица с запретом въезда в Польшу/Шенген, данные которых вносятся в реестры"],"practical_impact":"Перед поездкой без визы придётся заранее оформить онлайн‑разрешение ETIAS и следить за его сроком, иначе не впустят в Польшу и не примут многие заявления на легализацию. Обжалование отказа по ETIAS возможно только электронно, в жёсткий 7‑дневный срок и с платой; данные иностранцев будут сведены в единый реестр, что упростит проверку, но усилит контроль и обмен информацией между ведомствами.","effective_date":"Закон вступает в силу в день, указанный в решении Европейской комиссии на основании ст. 88 ч. 1 регламента (ЕС) 2018/1240, за исключением части технических и переходных положений, которые начнут действовать через 14 дней после опубликования.","confidence":0.93,"rationale":"Проект напрямую привязывает электронное разрешение ETIAS к праву въезда и законности пребывания, широко меняет ustawę o cudzoziemcach и создаёт единый реестр иностранцев, что делает его ключевым актом о миграционном статусе.","mnemonic_candidate":"Пропуск ETIAS","mnemonic_fallback":"Закон о системе ETIAS","mnemonic_basis":"Проект вводит обязательное электронное разрешение ETIAS для безвизовых иностранцев и связывает его наличие с въездом, пребыванием и подачей заявлений на ВНЖ/ПМЖ в Польше.","mnemonic_language":"ru","changes_since_previous":["Размер пошлины за повторное рассмотрение дела по ETIAS больше не фиксирован в 200 zł: в проекте предусмотрено, что её точное значение установят в регламенте МВД в диапазоне от 100 zł до 6,54% средней зарплаты."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":134180,"truncated":false,"text_source":"documents","created_at":"2026-10-21T18:50:51Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","source_kind":"rcl","revision":3,"text_sha256":"text-v2:2d99dcb260ddf31b4e17d6400164b0a97ba7aa76be5ebf50dcb8d3aa40cd096f","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":["rcl/12400563/stage/13146411","KP2 - MSWiA - PROJEKT PO KOMISJI PRAWNICZEJ.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","members":[],"container_sha256":"22edc0d40591f58922c6cdc9f9652c804a333d855fd02de1797f3136c10c2718","sha256":"22edc0d40591f58922c6cdc9f9652c804a333d855fd02de1797f3136c10c2718","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":134181,"text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","losses":[]}],"observed