7abbbf39b02f1abcbd54e33df35650bdb6a1471b2ea0e000b1b26f92c214533","role":"unknown","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":62302,"text_sha256":"5bae251627e4f238cb94b49c4aa5d4c764b3f81d4e288ccdc9ed721bcdd2af84","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12400563/stage/13146411","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","block_id":"part:0","start":0,"end":1576,"quote":"Projekt z dnia 29 września 2026 r.\nEtap: po komisji prawniczej\nUSTAWA\nz dnia <data wydania aktu> r.\no udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS) [przypis 2: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 12 października 1990 r. o Straży Granicznej, ustawę z dnia 24 maja 2000 r. o Krajowym Rejestrze Karnym, ustawę z dnia 13 czerwca 2003 r. o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej, ustawę z dnia 14 lipca 2006 r. o wjeździe na terytorium Rzeczypospolitej Polskiej, pobycie oraz wyjeździe z tego terytorium obywateli państw członkowskich Unii Europejskiej i członków ich rodzin, ustawę z dnia 16 listopada 2006 r. o opłacie skarbowej, ustawę z dnia 24 sierpnia 2007 r. o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym, ustawę z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, ustawę z dnia 2 kwietnia 2009 r. o obywatelstwie polskim, ustawę z dnia 12 grudnia 2013 r. o cudzoziemcach, ustawę z dnia 25 czerwca 2015 r. – Prawo konsularne, ustawę z dnia 20 marca 2025 r. o rynku pracy i służbach zatrudnienia, ustawę z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej, ustawę z dnia 13 lutego 2026 r. o zmianie ustawy o Krajowym Rejestrze Karnym oraz niektórych innych ustaw oraz ustawę z dnia 15 maja 2026 r. o udziale Rzeczypospolitej Polskiej w systemie Eurodac.] )\nRozdział 1\nPrzepisy ogólne\nArt. 1"},{"kind":"draft_date","value":"2026-09-29","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx","text_sha256":"2a7fe4119323d62e59b8eaea48e257681ecf1b7a232177aaab2a0a2a09f473df","block_id":"part:0","start":0,"end":31,"quote":"Projekt z dnia 29 września 2026"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":134181,"page_start":null,"page_end":null,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":134181,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"53415ee5c621f32188c54ba23135f5c7363f6f3ac945e4d28572e6fa03173276"},"law_sha256":"law-v2:f56b59c9b3e30f001b85337344eafb7befdafd15e8a976d62bb3bab41f082fa9","source_checked_at":"2026-10-21T18:50:51Z"}',0,NULL,'2026-09-09T14:42:18+00:00','2026-10-28T19:16:25+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12400563,"title":"Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UC104","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2025-07-31","modified":"2026-10-20","departments":["sprawy wewnętrzne"],"keywords":["CUDZOZIEMCY"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: projektowana ustawa służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.).","term_label":"X","stages":[{"id":13146281,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13146285,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-03-23","folders":[{"id":13146288,"name":"Projekt","modified":"2025-12-23","documents":[{"id":730178,"name":"OSR ETIAS","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument730178.doc","created":"2025-07-31","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":730179,"name":"Projekt","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument730179.docx","created":"2025-07-31","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":730180,"name":"Uzasadnienie","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument730180.docx","created":"2025-07-31","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":730181,"name":"Załącznik do OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument730181.XLSX","created":"2025-07-31","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":755886,"name":"PROJEKT - wersja 2","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument755886.DOCX","created":"2025-12-23","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":755887,"name":"UZASADNIENIE - 2 wersja","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument755887.DOCX","created":"2025-12-23","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":755888,"name":"OSR - wersja 2","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument7558