INSERT INTO "bills" VALUES(10,'RCL/12402353','Projekt ustawy o rejestracji statków pod polską banderą','2026-10-26T00:00:00+00:00',NULL,NULL,'analyzed','["text:wizy", "text:straz_graniczna", "text:schengen", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12402353","title":"Projekt ustawy o rejestracji statków pod polską banderą","description":"STATKI MORSKIE; gospodarka morska","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-22","document_date":"2026-10-02","change_date":"2026-10-26T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12402353","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','5425c3d95c66829d71c3eb75bb86431972449ffa51c244a7b77e6beaaeb645fe','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект полностью перестраивает систему регистрации судов и реестра, вводит электронный реестр и сервис на английском. Важное для иностранцев: расширяются правила временного признания дипломов моряков из третьих стран и допуска их к работе на судах под польским флагом до 3 месяцев.","key_changes":["Моряки с документами из третьих стран могут получить признание диплома максимум на 3 месяца","Признание документов стран не из списка ЕС/KE – только если в KE подан запрос о признании этой страны","Моряки с поданным заявлением на признание диплома могут до 3 мес. работать на судах под польской флагом","И то, и другое допускается лишь после проверки подлинности иностранного документа квалификации","За выдачу подтверждения подачи заявления на признание взимается 30 PLN"],"affected_groups":["иностранные моряки с дипломами/свидетельствами третьих стран","иностранные члены экипажей, нанимающиеся на суда под польским флагом","иностранные судовладельцы из państw UE/EFTA, регистрирующие суда в польском реестре"],"practical_impact":"Иностранец‑моряк с дипломом из третьей страны сможет быстрее выйти в рейс на судне под польским флагом: до 3 месяцев на основании временного признания или подтверждения подачи заявления. Нужно пройти проверку подлинности документа и оплатить 30 PLN за подтверждение.","effective_date":"Изменения по признанию документов квалификационных (art. 6 pkt 1–3, 5–7, 10) вступают в силу через 14 дней со дня официального опубликования закона.","confidence":0.86,"rationale":"Проект прямо изменяет правила признания иностранных морских дипломов и допуска иностранных моряков к работе на судах под польским флагом, что существенно для занятости (категория „employment”, важность 4).","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":["Уточнено, что для документов из стран, не признанных Еврокомиссией, временное признание возможно только после подачи Польшей официального wniosku do KE о признании этой страны (новый ust. 6 art. 67).","Чётко разделены два механизма: краткосрочное признание зарубежного документа (до 3 мес.) и допуск к работе по одному лишь подтверждению подачи заявления (также до 3 мес., ust. 7–8).","В тексте подробно прописано, что и временное признание, и подтверждение подачи заявления выдаются только после позитивной проверки подлинности иностранного документа квалификации.","Сохранена, но теперь явно указана в załączniku фиксированная плата 30 PLN за подтверждение подачи wniosku о признании документа."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":288205,"truncated":false,"text_source":"documents","created_at":"2026-10-02T14:56:37Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402353/13157968/13157969/dokument800294.zip","source_kind":"rcl","revision":2,"text_sha256":"f80b38830cd42ba5dcec1207547dea96d3a21b7ebd28b1a2dac0a251aea614cb","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":"9905bda2732b2835f7398323ab30026ea480ae68a1f1ab65d544e9a5f1c1d2ab","source_checked_at":"2026-10-02T14:56:37Z"}',0,NULL,'2026-09-11T09:51:44+00:00','2026-10-28T19:16:25+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12402353,"title":"Projekt ustawy o rejestracji statków pod polską banderą","applicant":"Minister Infrastruktury","wykaz_number":"UDER84","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-rejestracji-statkow-pod-polska-bandera","created":"2025-09-22","modified":"2026-10-26","departments":["gospodarka morska"],"keywords":["STATKI MORSKIE"],"status":"otwarty","term_label":"X","stages":[{"id":13157930,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13157931,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-09-11","folders":[{"id":13157932,"name":"Projekt","modified":"2026-05-15","documents":[{"id":738389,"name":"projekt-uzgodnienia.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument738389.pdf","created":"2025-09-22","author":"Minister Infrastruktury"},{"id":738391,"name":"uzasadnienie-uzgodnienia.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument738391.pdf","created":"2025-09-22","author":"Minister Infrastruktury"},{"id":738393,"name":"OSR-uzgodnienia.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument738393.pdf","cr