INSERT INTO "bills" VALUES(10,'1039','Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa','2025-03-05T10:13:09+00:00',NULL,0,'analyzed','["obywatele_ukrainy"]','{"term":10,"number":"1039","title":"Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa","description":"projekt dotyczy usunięcia przepisów pozwalających na uprzywilejowane traktowanie obywateli Ukrainy względem obywateli Rzeczypospolitej Polskiej w zakresie dostępu do określonych świadczeń socjalnych oraz w zakresie możliwości zatrudnienia ich odpowiednio w jednostkach naukowych oraz innych jednostkach organizacyjnych PAN, instytucie badawczym oraz Centrum Łukasiewicz lub instytucie działającym w ramach Sieci Badawczej Łukasiewicz bez przeprowadzania konkursu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-01-23","document_date":"2025-01-23","change_date":"2025-03-05T10:13:09Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-01-23","print_number":"1039","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-03-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-03-05","committee_code":"PSR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-01-23","print_number":"1039","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-03-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-03-05","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}]','aa1546e0382267490ef77ef55e4c4b65c52426f9dd0f98b2e533f5dfc18122df','{"analysis":{"relevant":true,"score":4,"category":"social","summary":"Проект изменяет спецзакон о помощи гражданам Украины. Он отменяет ряд норм, дающих украинцам льготный доступ к социальным выплатам и медицинской помощи, а также к работе в научных институтах без конкурса. После этого украинцы пользовались бы этими правами на общих условиях, как другие иностранцы.","key_changes":["Отмена ряда статей спецзакона (в т.ч. ст. 26, 26a, 27b, 27c, 29, 32, 33, 37) о льготном доступе к соцвыплатам","По обоснованию, отменяется автоматический доступ к медпомощи NFZ для легально пребывающих украинцев","Отмена ст. 47–49: приём украинцев на работу в институты PAN и Łukasiewicz без конкурса, по заявлению","Повят будет финансировать только пребывание в приёмной семье лиц из ст. 27a (новая редакция ст. 27d)","Замена в тексте закона «w Ukrainie» на «na Ukrainie» (языковая правка)"],"affected_groups":["граждане Украины, пребывающие в Польше на основании спецзакона","украинцы, получающие социальные выплаты и медицинскую помощь по спецзакону","украинские учёные, трудоустраивающиеся в научные учреждения"],"practical_impact":"Украинцы со статусом по спецзакону утратили бы льготный доступ к части соцвыплат и медпомощи и могли бы получать их только на общих основаниях, например при наличии карты побыту, статуса беженца или страховки NFZ. Для работы в институтах PAN и Łukasiewicz потребовался бы обычный конкурс.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.75,"rationale":"Проект меняет спецзакон о помощи гражданам Украины (уровень 4), а основное содержание касается социальных выплат и медпомощи, отсюда категория social.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":19248,"truncated":false,"text_source":"pdf","created_at":"2026-09-25T03:08:29Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1039/1039.pdf","source_kind":"print","revision":1,"text_sha256":"7a8ee05156b9bdcefe6bc193021025bfd9c53c6366467170baa828991ffa8cd9","source_checked_at":"2026-09-25T03:08:29Z"}',0,NULL,'2026-09-11T14:43:40+00:00','2026-10-28T19:18:16+00:00','{"term":10,"number":"RPW/2793/2025","title":"Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa","description":"usunięcia przepisów pozwalających na uprzywilejowane traktowanie obywateli Ukrainy względem obywateli Rzeczypospolitej Polskiej w zakresie dostępu do określonych świadczeń socjalnych oraz w zakresie możliwości zatrudnienia ich odpowiednio w jednostkach naukowych oraz innych jednostkach organizacyjnych PAN, instytucie badawczym oraz Centrum Łukasiewicz lub instytucie działającym w ramach Sieci Badawczej Łukasiewicz bez przeprowadzania konkursu","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-01-23","print_number":"1039","eu_related":false,"public_consultation":true,"consultation_start":"2025-01-24","consultation_end":"2025-02-23","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Przemysław Wipler","representative_club":"Konfederacja","clubs":[["Konfederacja",15],["Konfederacja_KP",2]],"signatories":17,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["1039-001"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-01-23","print_number":"1039","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-03-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-03-05","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/1039/1039.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"7a8ee05156b9bdcefe6bc193021025bfd9c53c6366467170baa828991ffa8cd9","analysis_revision":1,"seen_supplements":["1039-001"]}',2,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Отмена льгот украинцам","language":"ru","basis":"Проект отменяет спецнормы о льготном доступе граждан Украины к соцвыплатам, медпомощи NFZ и трудоустройству, приравнивая их к другим иностранцам.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'1040','Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa','2025-03-05T10:15:17+00:00',NULL,0,'analyzed','["obywatele_ukrainy"]','{"term":10,"number":"1040","title":"Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa","description":"projekt dotyczy propozycji wprowadzenia dwóch dodatkowych warunków, od których uzależnione jest otrzymanie świadczenia wychowawczego przez obywateli Ukrainy na podstawie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium: 1) warunek zatrudnienia lub prowadzenia działalności gospodarczej na terytorium Rzeczypospolitej Polskiej,2) warunek realizowania zobowiązania podatkowego wobec Skarbu Państwa, chyba, że zaległości z uiszczeniem podatków wynikają z uzyskania przewidzianych prawem zwolnienia, odroczenia, rozłożenia na raty zaległych płatności lub wstrzymania w całości wykonania decyzji właściwego organu. Projekt wprowadza również przepisy, które zakładają wstrzymanie wypłaty świadczenia w przypadku podjęcia przez właściwe organy informacji o pozostawaniu bez pracy, jak również nie odprowadzaniu podatku i  przywrócenia świadczenia w przypadku ponownego spełnienia tych warunków.\n","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-01-20","document_date":"2025-01-20","change_date":"2025-03-05T10:15:17Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-01-20","print_number":"1040","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-03-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-03-05","committee_code":"PSR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-01-20","print_number":"1040","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-03-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-03-05","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}]','7c566ff411a50170979cb17fbde9e6a3a7a97e46e712fb36a796e3ed98160182','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект ужесточает условия получения 800+ (świadczenie wychowawcze) для граждан Украины, находящихся в Польше по спецзакону. Выплата будет зависеть от работы или бизнеса в Польше и уплаты налогов; при невыполнении условий пособие приостанавливается.","key_changes":["Новое условие для 800+: трудоустройство или ведение działalności gospodarczej в Польше","Новое условие: исполнение налоговых обязательств перед государством","Исключение: законные освобождения, отсрочки, рассрочка или приостановление решения органа","Приостановление выплаты при выявлении отсутствия работы или неуплаты налогов","Возобновление выплаты с месяца, когда условия снова выполнены"],"affected_groups":["Граждане Украины с легальным пребыванием на основании art. 2 ust. 1 спецзакона","Украинские родители, получающие или подающие заявление на 800+"],"practical_impact":"Чтобы получать 800+ на ребёнка, гражданину Украины нужно будет работать или вести бизнес в Польше и не иметь налоговых задолженностей; иначе ZUS приостановит выплату. Новые условия впервые применяются к заявлениям, подаваемым с 1 февраля по 30 апреля 2025 г.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования; новые условия впервые применяются к заявлениям, подаваемым с 1 февраля 2025 г. по 30 апреля 2025 г.","confidence":0.9,"rationale":"Поправка к ustawa o pomocy obywatelom Ukrainy (закон о помощи гражданам Украины), связывающая доступ к 800+ с занятостью, относится по шкале к уровню 4 и напрямую затрагивает украинцев под временной защитой.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":7982,"truncated":false,"text_source":"pdf","created_at":"2026-09-25T03:08:29Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1040/1040.pdf","source_kind":"print","revision":1,"text_sha256":"346991616e45f3d862e55248ae507d523c88265ad987e0419165eb54a1009af7","source_checked_at":"2026-09-25T03:08:29Z"}',0,NULL,'2026-09-11T14:44:07+00:00','2026-10-28T19:18:16+00:00','{"term":10,"number":"RPW/1978/2025","title":"Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa","description":"propozycji wprowadzenia dwóch dodatkowych warunków, od których uzależnione jest otrzymanie świadczenia wychowawczego przez obywateli Ukrainy na podstawie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium: 1) warunek zatrudnienia lub prowadzenia działalności gospodarczej na terytorium Rzeczypospolitej Polskiej,2) warunek realizowania zobowiązania podatkowego wobec Skarbu Państwa, chyba, że zaległości z uiszczeniem podatków wynikają z uzyskania przewidzianych prawem zwolnienia, odroczenia, rozłożenia na raty zaległych płatności lub wstrzymania w całości wykonania decyzji właściwego organu. Projekt wprowadza również przepisy, które zakładają wstrzymanie wypłaty świadczenia w przypadku podjęcia przez właściwe organy informacji o pozostawaniu bez pracy, jak również nie odprowadzaniu podatku i  przywrócenia świadczenia w przypadku ponownego spełnienia tych warunków.\n","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-01-20","print_number":"1040","eu_related":false,"public_consultation":true,"consultation_start":"2025-01-21","consultation_end":"2025-02-20","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Zbigniew Bogucki","representative_club":"PiS","clubs":[["PiS",24],["RozwojPlus",3]],"signatories":27,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["1040-001", "1040-002", "1040-003"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-01-20","print_number":"1040","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-03-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-03-05","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/1040/1040.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"346991616e45f3d862e55248ae507d523c88265ad987e0419165eb54a1009af7","analysis_revision":1,"seen_supplements":["1040-001","1040-002","1040-003"]}',2,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"800+ за занятость","language":"ru","basis":"Проект делает выплату 800+ для граждан Украины зависимой от работы/бизнеса в Польше и уплаты налогов, с приостановкой при невыполнении условий.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'1273','Poselski projekt ustawy o zmianie ustawy o obywatelstwie polskim','2025-06-10T10:27:06+00:00',NULL,0,'analyzed','["cudzoziemcy", "obywatelstwo", "zezwolenie_pobyt", "pobyt_kwalifikowany"]','{"term":10,"number":"1273","title":"Poselski projekt ustawy o zmianie ustawy o obywatelstwie polskim","description":"projekt dotyczy wydłużenia z 3 do 10 lat okresu nieprzerwanego pobytu cudzoziemca na terytorium Rzeczypospolitej Polskiej, na podstawie zezwolenia na pobyt stały, zezwolenia na pobyt rezydenta długoterminowego, UE lub prawa stałego pobytu, wymaganego do uznania go za obywatela polskiego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-05-05","document_date":"2025-05-05","change_date":"2025-06-10T10:27:06Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-05-05","print_number":"1273","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-05-08","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-06-10","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-06-10","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2025-08-21","sub_committee":false,"children":[]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-05-05","print_number":"1273","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-05-08","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-06-10","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-06-10","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2025-08-21","sub_committee":false,"children":[]}]','0d4d5825d878b1f4fc503a5dab1cf626f7cce1497d2d3b9d54b96d55daa034a5','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Депутатский проект продлевает с 3 до 10 лет срок непрерывного проживания в Польше, необходимый для признания польским гражданином (uznanie za obywatela polskiego). Остальные условия — стабильный доход, право на жильё, язык B1 — сохраняются. Заявления, поданные до вступления закона в силу, рассматриваются по старым правилам.","key_changes":["Срок непрерывного пребывания для uznanie za obywatela polskiego: с 3 до 10 лет","Касается лиц с pobyt stały, rezydenta długoterminowego UE или prawem stałego pobytu","Условия дохода, жилья и языка B1 не меняются","Сокращённые сроки для супругов граждан Польши (2 года) и владельцев Karta Polaka (1 год) не затрагиваются","Начатые и незавершённые дела рассматриваются по прежним нормам"],"affected_groups":["владельцы zezwolenia na pobyt stały","владельцы zezwolenia na pobyt rezydenta długoterminowego UE","лица с prawem stałego pobytu (граждане ЕС и члены семей)","граждане Украины, планирующие натурализацию"],"practical_impact":"Для тех, кто планирует получить гражданство через uznanie za obywatela polskiego по общему основанию, ожидание после получения постоянного статуса вырастет с 3 до 10 лет. Успеть подать заявление по старым правилам можно до вступления закона в силу.","effective_date":"Через 30 дней со дня опубликования","confidence":0.95,"rationale":"Проект напрямую меняет условия приобретения польского гражданства, что относится к легализации пребывания и статуса.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":28203,"truncated":false,"text_source":"pdf","created_at":"2026-09-11T14:45:15Z","input_tokens":14725,"output_tokens":626,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1273/1273.pdf","source_kind":"print","revision":1,"text_sha256":"c6c57c7c8a0148ffa5e6eeeb4b2cf28f1183954ef543b8b0046073470e48a95e","source_checked_at":null}',0,NULL,'2026-09-11T14:44:53+00:00','2026-10-28T19:18:16+00:00','{"term":10,"number":"RPW/15086/2025","title":"Poselski projekt ustawy o zmianie ustawy o obywatelstwie polskim","description":"wydłużenia z 3 do 10 lat okresu nieprzerwanego pobytu cudzoziemca na terytorium Rzeczypospolitej Polskiej, na podstawie zezwolenia na pobyt stały, zezwolenia na pobyt rezydenta długoterminowego, UE lub prawa stałego pobytu, wymaganego do uznania go za obywatela polskiego","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-05-05","print_number":"1273","eu_related":false,"public_consultation":true,"consultation_start":"2025-05-06","consultation_end":"2025-06-05","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PiS",49],["RozwojPlus",9],["niez.",1]],"signatories":59,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["1273-001", "1273-002", "1273-s"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-05-05","print_number":"1273","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-05-08","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-06-10","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-06-10","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2025-08-21","sub_committee":false,"children":[]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/1273/1273.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"c6c57c7c8a0148ffa5e6eeeb4b2cf28f1183954ef543b8b0046073470e48a95e","analysis_revision":1,"seen_supplements":["1273-001","1273-002","1273-s"]}',0,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Гражданство 10 лет","language":"ru","basis":"Проект увеличивает срок непрерывного проживания для uznanie za obywatela polskiego с 3 до 10 лет.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'1759','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o obywatelstwie polskim','2025-11-04T18:29:34+00:00',NULL,0,'analyzed','["cudzoziemcy", "obywatelstwo", "zezwolenie_pobyt", "pobyt_kwalifikowany"]','{"term":10,"number":"1759","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o obywatelstwie polskim","description":"projekt dotyczy wydłużenia z 3 do 10 lat minimalnego okresu nieprzerwanego pobytu w Polsce (na podstawie zezwolenia na pobyt stały, zezwolenia na pobyt rezydenta długoterminowego Unii Europejskiej lub prawa stałego pobytu) wymaganego do uznania cudzoziemca za obywatela polskiego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-29","document_date":"2025-09-26","change_date":"2025-11-04T18:29:34Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-09-29","print_number":"1759","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-03","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-11-04","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-04","committee_code":"ASW","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-09-29","print_number":"1759","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-03","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-11-04","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-04","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]}]','f2125ced687ad884d36b169b62fa0eeb07889a1ef13f863b620c99380cf236fb','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Президентский проект продлевает с 3 до 10 лет минимальный срок непрерывного проживания в Польше, необходимый для признания иностранца гражданином Польши (uznanie za obywatela polskiego). Речь о проживании на основании pobyt stały, rezydenta długoterminowego UE или prawa stałego pobytu. Заявления, поданные до вступления закона в силу, рассматриваются по старым правилам.","key_changes":["Срок непрерывного проживания для uznanie za obywatela polskiego: с 3 до 10 лет","Учитывается пребывание по pobyt stały, rezydent długoterminowy UE или prawo stałego pobytu","Остальные условия без изменений: стабильный доход, право на жильё, польский язык B1","Дела, начатые до вступления в силу, рассматриваются по прежним нормам","Вступление в силу — через 30 дней после опубликования"],"affected_groups":["обладатели zezwolenie na pobyt stały","обладатели статуса rezydenta długoterminowego UE","граждане ЕС с prawem stałego pobytu","иностранцы, планирующие подать на признание гражданином Польши"],"practical_impact":"Подать заявление о признании гражданином Польши можно будет только после 10 лет постоянного проживания вместо 3 лет; тем, кто уже подал заявление до вступления закона в силу, применяются прежние правила.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.97,"rationale":"Проект напрямую меняет условия получения польского гражданства — ключевой вопрос легализации статуса.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":11266,"truncated":false,"text_source":"pdf","created_at":"2026-09-11T14:46:03Z","input_tokens":5948,"output_tokens":608,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1759/1759.pdf","source_kind":"print","revision":1,"text_sha256":"5383637b2f3a5d6d28913bd2fdeb8272c71d3747627229c1bb0ccb690d5376d4","source_checked_at":null}',0,NULL,'2026-09-11T14:45:18+00:00','2026-10-28T19:18:16+00:00','{"term":10,"number":"RPW/32133/2025","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o obywatelstwie polskim","description":"wydłużenia z 3 do 10 lat minimalnego okresu nieprzerwanego pobytu w Polsce (na podstawie zezwolenia na pobyt stały, zezwolenia na pobyt rezydenta długoterminowego Unii Europejskiej lub prawa stałego pobytu) wymaganego do uznania cudzoziemca za obywatela polskiego","applicant":"president","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-09-29","print_number":"1759","eu_related":false,"public_consultation":true,"consultation_start":"2025-09-30","consultation_end":"2025-10-30","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["1759-001", "1759-002", "1759-003", "1759-004"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-09-29","print_number":"1759","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-03","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-11-04","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-11-04","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/1759/1759.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"5383637b2f3a5d6d28913bd2fdeb8272c71d3747627229c1bb0ccb690d5376d4","analysis_revision":1,"seen_supplements":["1759-001","1759-002","1759-003","1759-004"]}',0,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Гражданство 10 лет","language":"ru","basis":"Проект увеличивает минимальный срок непрерывного проживания для признания гражданства с 3 до 10 лет.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'1812','Poselski projekt ustawy o czasowym zakazie wjazdu obywateli państw trzecich na terytorium Rzeczypospolitej Polskiej','2025-10-15T06:54:09+00:00',NULL,0,'analyzed','["straz_graniczna", "obywatele_innych_panstw"]','{"term":10,"number":"1812","title":"Poselski projekt ustawy o czasowym zakazie wjazdu obywateli państw trzecich na terytorium Rzeczypospolitej Polskiej","description":"projekt dotyczy wprowadzenia czasowego (nie dłuższy niż 12 miesięcy, z możliwością przedłużenia) zakazu wjazdu dla obywateli państw niebędących państwem członkowskim Unii Europejskiej, państwem członkowskim Europejskiego Porozumienia Wolnego Handlu (EFTA) - stron umowy o Europejskim Obszarze Gospodarczym lub Konfederacji Szwajcarskiej, w przypadku gdy ich pobyt na terytorium Rzeczypospolitej Polskiej może stanowić zagrożenie dla bezpieczeństwa państwa, dla ochrony bezpieczeństwa i porządku publicznego, dla zdrowia publicznego lub w przypadku realizacji zobowiązań międzynarodowych. Projekt ustawy przyznaje kompetencje Straży Granicznej w zakresie weryfikacji uprawnień do wjazdu oraz wydawania odmowy wjazdu lub natychmiastowego wydalenia obywatela państwa trzeciego w przypadku uzasadnionego podejrzenia, że nie spełnia on warunków wjazdu określonych w niniejszej ustawie lub rozporządzeniu Rady Ministrów wydanym na jej podstawie.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-02","document_date":"2025-07-02","change_date":"2025-10-15T06:54:09Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-07-02","print_number":"1812","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-10-14","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-10-14","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2026-02-06","sub_committee":false,"children":[]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-07-02","print_number":"1812","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-10-14","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-10-14","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2026-02-06","sub_committee":false,"children":[]}]','c4558b12e9733cdd94599b1ca84b481433202d37ea93e66729b0a9782466b608','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Депутатский проект позволяет Совету министров вводить временный запрет на въезд в Польшу для граждан стран вне ЕС/ЕАСТ/ЕЭП/Швейцарии — до 12 месяцев с возможностью продления. Straż Graniczna сможет отказывать во въезде и немедленно выдворять. Запрет не касается тех, у кого есть pobyt stały, czasowy или резидент ЕС.","key_changes":["Rada Ministrów по заявке MSWiA вводит запрет на въезд для граждан конкретных стран (до 12 мес., с продлением)","Исключения: обладатели zezwolenie na pobyt stały/czasowy и резиденты ЕС, члены семей граждан Польши, дипломаты, часть граждан Великобритании","Отказ во въезде равнозначен выдворению; обжалование Шефу UdSC в течение 7 дней без приостановки выдворения","Немедленное выдворение при обоснованном подозрении нарушения условий въезда, объявляется устно","Обязанность SG не принимать граждан третьих стран, переданных другой страной ЕС вне процедуры реадмиссии","Штраф до 100 000 zł и запрет на повторный въезд до 5 лет за нарушение запрета"],"affected_groups":["граждане стран вне ЕС/ЕАСТ/ЕЭП/Швейцарии","лица, въезжающие по визам и безвизово","соискатели защиты на границе","обладатели pobyt stały/czasowy и резиденты ЕС (исключены из запрета)","члены семей граждан Польши"],"practical_impact":"При введении такого запрета гражданам указанных стран могут отказать во въезде на границе и немедленно выдворить, при этом жалоба в UdSC (7 дней) не остановит выдворение. Лица с действующим разрешением на пребывание в Польше под запрет не попадают.","effective_date":"Закон вступает в силу на следующий день после опубликования.","confidence":0.95,"rationale":"Проект напрямую регулирует условия въезда, отказ во въезде и выдворение иностранцев, что относится к легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":28506,"truncated":false,"text_source":"pdf","created_at":"2026-09-11T14:46:53Z","input_tokens":14989,"output_tokens":804,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1812/1812.pdf","source_kind":"print","revision":1,"text_sha256":"b122a2a2dac3d2297630aea7fbeb57ef26db02b5cedcc59eb664d5442375d58e","source_checked_at":null}',0,NULL,'2026-09-11T14:46:10+00:00','2026-10-28T19:18:16+00:00','{"term":10,"number":"RPW/22187/2025","title":"Poselski projekt ustawy o czasowym zakazie wjazdu obywateli państw trzecich na terytorium Rzeczypospolitej Polskiej","description":"wprowadzenia czasowego (nie dłuższy niż 12 miesięcy, z możliwością przedłużenia) zakazu wjazdu dla obywateli państw niebędących państwem członkowskim Unii Europejskiej, państwem członkowskim Europejskiego Porozumienia Wolnego Handlu (EFTA) - stron umowy o Europejskim Obszarze Gospodarczym lub Konfederacji Szwajcarskiej, w przypadku gdy ich pobyt na terytorium Rzeczypospolitej Polskiej może stanowić zagrożenie dla bezpieczeństwa państwa, dla ochrony bezpieczeństwa i porządku publicznego, dla zdrowia publicznego lub w przypadku realizacji zobowiązań międzynarodowych. Projekt ustawy przyznaje kompetencje Straży Granicznej w zakresie weryfikacji uprawnień do wjazdu oraz wydawania odmowy wjazdu lub natychmiastowego wydalenia obywatela państwa trzeciego w przypadku uzasadnionego podejrzenia, że nie spełnia on warunków wjazdu określonych w niniejszej ustawie lub rozporządzeniu Rady Ministrów wydanym na jej podstawie.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-07-02","print_number":"1812","eu_related":false,"public_consultation":true,"consultation_start":"2025-07-02","consultation_end":"2025-08-01","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PiS",48],["RozwojPlus",15]],"signatories":64,"unresolved":1}',NULL,NULL,NULL,NULL,NULL,'["1812-s"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-07-02","print_number":"1812","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-10-14","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-10-14","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2026-02-06","sub_committee":false,"children":[]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/1812/1812.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"b122a2a2dac3d2297630aea7fbeb57ef26db02b5cedcc59eb664d5442375d58e","analysis_revision":1,"seen_supplements":["1812-s"]}',0,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Шлагбаум для третьих стран","language":"ru","basis":"Проект позволяет правительству вводить временный запрет на въезд граждан стран вне ЕС и немедленно их выдворять.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'RCL/12412103','Projekt ustawy o zmianie ustawy o cudzoziemcach','2026-10-20T00:00:00+00:00',NULL,NULL,'analyzed','["cudzoziemcy"]','{"term":10,"number":"RCL/12412103","title":"Projekt ustawy o zmianie ustawy o cudzoziemcach","description":"CUDZOZIEMCY; sprawy wewnętrzne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-10-12","change_date":"2026-10-20T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12412103","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','0c83e9f85570649a8150f2fa0485db5c568449c3ee30039c6bc4e8f42fe376c7','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит «молчаливое одобрение» ВНЖ (pobyt czasowy) для граждан избранных развитых безвизовых стран. Если воевода не вынесет решение за 60 дней, разрешение считается выданным на 2 года, при усиленных проверках безопасности и возможности немедленного отзыва.","key_changes":["«Молчаливое» одобрение pobyt czasowy для граждан стран из списка Rady Ministrów","Нет решения воеводы за 60 дней — ВНЖ считается выданным автоматически","Срок такого pobyt czasowy: 2 года (157a – 6 мес., 157g – 1 год)","Воевода: 14 дней на вызов по ошибкам заявки, 30 дней на запрос проверок","Отзыв ВНЖ по угрозе безопасности подлежит немедленному исполнению"],"affected_groups":["граждане развитых безвизовых стран (Австралия, Япония, Корея, США, Великобритания и др.) после включения в список","иностранцы из этих стран, подающие на zezwolenie na pobyt czasowy по основным целям (работа, бизнес, учёба, исследования, стажировка, волонтариат)"],"practical_impact":"Для граждан стран из правительственного списка оформление ВНЖ ускоряется: при e‑заявлении через MOS и отсутствии решения за 60 дней разрешение считается выданным на стандартный срок. Однако нужно вовремя явиться, сдать отпечатки и документы, а при выявлении угрозы безопасности ВНЖ могут быстро и сразу исполнимо отозвать.","effective_date":"Закон вступает в силу через 14 дней после опубликования, за исключением ст. 1 п. 4 в части ст. 112f ч. 2–4, которые вступают в силу через 3 месяца после опубликования.","confidence":0.9,"rationale":"Проект напрямую меняет правила и сроки получения/отзыва zezwoleń na pobyt czasowy, вводя «молчаливое» одобрение для части иностранцев, что является ключевым изменением миграционного статуса.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":["Срок на направление вызова для устранения формальных недостатков увеличен с 7 до 14 дней.","Срок на обращение за информацией от служб безопасности увеличен с 10 до 30 дней.","Исключение по сроку для разрешений по ст. 144 (15 месяцев) убрано: для них теперь действует общий 2‑летний срок."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":55561,"truncated":false,"text_source":"documents","created_at":"2026-10-12T22:14:38Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213534/13213535/dokument801836.zip","source_kind":"rcl","revision":2,"text_sha256":"text-v2:aea480a4ba1f22a27e7809aea785e605263b7137bf5905cdfd4c067f19d6610e","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":"law-v2:8eaf7fc1e85cc1b678ac64a17595246ff703b356105055b0f90489ff6f942052","source_checked_at":"2026-10-12T22:14:38Z"}',0,NULL,'2026-09-11T18:19:31+00:00','2026-10-28T19:16:55+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12412103,"title":"Projekt ustawy o zmianie ustawy o cudzoziemcach","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UD408","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-07-06","modified":"2026-10-20","departments":["sprawy wewnętrzne"],"keywords":["CUDZOZIEMCY"],"status":"otwarty","term_label":"X","stages":[{"id":13213496,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13213497,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-10-08","folders":[{"id":13213498,"name":"Projekt","modified":"2026-09-28","documents":[{"id":785926,"name":"Projekt","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument785926.docx","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":785927,"name":"OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument785927.docx","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":785928,"name":"Uzasadnienie","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument785928.docx","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":797422,"name":"OSR 2.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument797422.docx","created":"2026-09-16","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":797423,"name":"PROJEKT 2.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument797423.docx","created":"2026-09-16","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":797424,"name":"Uzasadnienie 2.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument797424.docx","created":"2026-09-16","autho