INSERT INTO "bills" VALUES(10,'RCL/12412403','Projekt ustawy o zmianie ustawy o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej','2026-07-14T00:00:00+00:00',NULL,NULL,'analyzed','["cudzoziemcy", "zatrudnianie_cudzoziemcow"]','{"term":10,"number":"RCL/12412403","title":"Projekt ustawy o zmianie ustawy o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej","description":"CUDZOZIEMCY; praca","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-14","document_date":"2026-07-14","change_date":"2026-07-14T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12412403","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','2eedc48212101033f90fbfc646938cad9f711611c82572f192ca4adfb8cad8d5','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект правительства меняет закон 2025 г. о допустимости поручения работы иностранцам. Ключевое: Совет министров сможет освободить граждан отдельных развитых стран (например США, Великобритании, Японии, Кореи) от разрешения на работу. Также уточняются процедуры, вводится обязанность уведомлять PUP о работе иностранцев без разрешения и усиливаются штрафы для работодателей.","key_changes":["Возможность освобождения граждан отдельных стран от zezwolenie na pracę (по распоряжению Rady Ministrów)","Работодатель обязан уведомить powiatowy urząd pracy в течение 7 дней о работе иностранца без разрешения","Zezwolenie na pracę — максимум 3 года и не дольше срока действия паспорта","Освобождение от разрешения для водителей, делегированных в Польшу, до 30 дней в году","Новые основания отказа: невыплата зарплаты иностранцу, препятствование процедуре; штрафы 3000–50 000 zł за каждого иностранца","Минимум по гражданско-правовому договору — 40 ч/мес, максимум 184 ч/мес; паспортные данные убраны из текста разрешения"],"affected_groups":["Граждане развитых стран (США, Великобритания, Япония, Корея и др.)","Иностранцы, работающие по zezwolenie na pracę или oświadczenie","Граждане Украины, работающие в Польше","Водители-иностранцы, делегированные в Польшу","Работодатели, поручающие работу иностранцам"],"practical_impact":"Часть иностранцев сможет начать работу без разрешения, но работодатель должен будет подать уведомление в PUP в течение 7 дней. Разрешение на работу теперь ограничено сроком действия паспорта, а работодателям грозят более высокие штрафы и отказы при невыплате зарплаты.","effective_date":"Закон вступает в силу через 60 дней после публикации; ИТ-системы адаптируются в течение 6 месяцев, к начатым делам применяются прежние нормы.","confidence":0.9,"rationale":"Проект напрямую меняет правила доступа иностранцев к рынку труда и процедуры разрешений на работу, что соответствует категории employment и оценке 4.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":146575,"truncated":false,"text_source":"documents","created_at":"2026-09-11T18:20:58Z","input_tokens":73439,"output_tokens":817,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412403/13215193/13215194/dokument787456.docx","source_kind":"rcl","revision":1,"text_sha256":"83ae993c7e05b9e9ee361d07700f0ebcae977d58b13685affeaa8e58669e5dc5","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"s