INSERT INTO "bills" VALUES(10,'RCL/12414100','Projekt ustawy o zmianie ustawy o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym','2026-10-19T00:00:00+00:00',NULL,NULL,'analyzed','["wizy", "schengen", "obywatele_innych_panstw"]','{"term":10,"number":"RCL/12414100","title":"Projekt ustawy o zmianie ustawy o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym","description":"SYSTEM INFORMACYJNY SCHENGEN ORAZ WIZOWY SYSTEM INFORMACYJNY; sprawy wewnętrzne. Numer i tytuł aktu prawnego Unii Europejskiej: Projektowana ustawa w zakresie swojej regulacji służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2022/1190 z dnia 6 lipca 2022 r. w sprawie zmiany rozporządzenia (UE) 2018/1862 w odniesieniu do wprowadzania do Systemu Informacyjnego Schengen (SIS) wpisów informacyjnych służących interesom Unii i dotyczących obywateli państw trzecich (Dz. Urz. UE L 185/1 z 12.7.2022).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-31","document_date":"2026-10-06","change_date":"2026-10-19T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12414100","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-10-06","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','5694480c1d0d7c5e1df78f44bfc02a84c992cf2e9e0099d9747447b005290773','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект внедряет в польское право новую категорию записей в SIS – «информационные записи» о гражданах третьих стран по запросу Europol и описывает, какие польские службы их вносят и используют. Это касается в первую очередь лиц, подозреваемых в терроризме и тяжкой преступности, а не обычных иностранцев.","key_changes":["Вводится понятие «впис информационный» для граждан третьих стран по ст. 37a регламента 2018/1862","Определён перечень польских служб, которые могут вносить такие записи в SIS","Расписана процедура проверки и анализа запросов Europol перед внесением записи","Расширён круг органов с доступом к данным этих записей и обязанностью уведомлять biuro SIRENE","Prezes UODO назначен ответственным за годовые отчёты по правам субъектов данных в SIS/VIS"],"affected_groups":["граждане третьих стран, попавшие под подозрение в терроризме или тяжких преступлениях","иностранцы, о которых уже есть или могут быть записи в SIS","лица, обжалывающие обработку своих данных в SIS/VIS"],"practical_impact":"Для иностранцев, попавших в поле зрения Europol, данные могут быть внесены в SIS как отдельная «информационная запись» и будут быстрее доступны польским службам. Для большинства иностранных жителей и заявителей на визу или ВНЖ прямых изменений процедур не предусмотрено, но проверки по SIS фактически усилятся для лиц из группы риска.","effective_date":"Закон вступает в силу в день, указанный в решении Европейской комиссии, в соответствии со ст. 79 ч. 7 регламента 2018/1862, за исключением art. 1 pkt 8, который вступает в силу через 14 дней после опубликования.","confidence":0.9,"rationale":"Регулируется использование SIS в отношении граждан третьих стран (записи по запросу Europol и доступ служб), что влияет на пограничный и полицейский контроль, но не меняет правил проживания или труда; это косвенное, но специфически «иностранческое» регулирование.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":65799,"truncated":false,"text_source":"documents","created_at":"2026-10-06T07:59:44Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223883/13223887/dokument800703.pdf","source_kind":"rcl","revision":2,"text_sha256":"text-v2:8dcd45e2466a52456e763029377734c15c461118b6b59fff3aaa6223e2e8dd15","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":"law-v2:768ce2ff5d13f7192754631dc47a7932793186deb01ed174a8151c88a66a65d4","source_checked_at":"2026-10-06T07:59:44Z"}',0,NULL,'2026-09-11T18:22:22+00:00','2026-10-28T19:17:55+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12414100,"title":"Projekt ustawy o zmianie ustawy o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UC164","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-08-31","modified":"2026-10-19","departments":["sprawy wewnętrzne"],"keywords":["SYSTEM INFORMACYJNY SCHENGEN ORAZ WIZOWY SYSTEM INFORMACYJNY"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: Projektowana ustawa w zakresie swojej regulacji służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2022/1190 z dnia 6 lipca 2022 r. w sprawie zmiany rozporządzenia (UE) 2018/1862 w odniesieniu do wprowadzania do Systemu Informacyjnego Schengen (SIS) wpisów informacyjnych służących interesom Unii i dotyczących obywateli państw trzecich (Dz. Urz. UE L 185/1 z 12.7.2022).","term_label":"X","stages":[{"id":13223901,"number":1,"n