INSERT INTO "bills" VALUES(10,'RCL/12405351','Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych','2026-10-06T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12405351","title":"Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz ustawy o dokumentach paszportowych","description":"KARNE POSTĘPOWANIE; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-17","document_date":"2026-09-30","change_date":"2026-10-06T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405351","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','3a8d51acfe7c0df6652e305dcb29ced506f7dc56696fa726e043103627759eec','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект вводит в уголовном процессе отдельные меры: запрет выезда из Польши или из ЕС и самостоятельное изъятие, аннулирование или отказ в выдаче паспорта. Для иностранцев такая мера станет прямым основанием отказать или аннулировать документы по закону об иностранцах.","key_changes":["Запрет выезда может касаться не только Польши, но и всей территории ЕС","Задержание, аннулирование или отказ в выдаче паспорта станут отдельной мерой пресечения","Любая из этих мер к иностранцу в Польше даёт основание для отказа/аннулирования док-та по ustawa o cudzoziemcach","Аннулировать паспорт в деле о преступлении сможет суд или орган, ведущий дело, а не только администрация","При отмене аннулирования новый паспорт выдаётся без госпошлины"],"affected_groups":["иностранцы — подозреваемые или обвиняемые в уголовных и налоговых преступлениях в Польше","иностранцы, получающие документы по ustawa o cudzoziemcach","иностранцы с польским паспортом или иным документом для пересечения границы"],"practical_impact":"Если к иностранцу применят такую меру пресечения, ему могут запретить выезд из Польши или ЕС и изъять/аннулировать паспорт или иной пограндокумент, а также отказать в его выдаче. Обжалование идёт в рамках уголовного процесса; после отмены аннулирования паспорт можно получить без оплаты.","effective_date":"Закон вступает в силу 1 октября 2027 г.","confidence":0.9,"rationale":"Проект меняет k.p.k., ustawa o cudzoziemcach и правила паспортов в части запрета выезда и аннулирования документов, затрагивая иностранцев лишь при наличии уголовного дела, что даёт косвенное, но ощутимое влияние.","mnemonic_candidate":"Паспортный стоп‑сигнал","mnemonic_fallback":"Запрет выезда и паспорта","mnemonic_basis":"Проект позволяет суду или органу следствия запрещать выезд из ЕС и самостоятельно аннулировать или не выдавать паспорт, а для иностранцев это связывается с отказом или аннулированием документов по ustawa o cudzoziemcach.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":42286,"truncated":false,"text_source":"documents","created_at":"2026-10-17T09:07:43Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176282/13176283/dokument799609.zip","source_kind":"rcl","revision":2,"text_sha256":"text-v2:532895488f3b9fc8e82ad854460926e01e3752964b523bb33d18c0c533eace90","selection":{"question":"bill_text","state":"selected","belonging":[],"role":["bill heading"],"version":["rcl/12405351/stage/13176282","nowy tekst projektu ustawy o zmianie ustawy – Kodeks postępowania karnego, ustawy o cudzoziemcach oraz ustawy o dokumentach paszportowych (UD319), KRM-0610-145-26.zip"],"completeness":["all selected members extracted"],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176282/13176283/dokument799609.zip","members":["Projekt ustawy z uzsadnieniem.pdf"],"container_sha256":"79db76b499410cd2893f8d2fc6de91f781ed60343745930483f984171f089708","sha256":"2430ac7bc19bbdb8980303c47b9981b2053986da3340debb978d5649fbb9c802","role":"bill","text":"","pages":10,"page_start":1,"page_end":10,"text_start":0,"text_end":19064,"text_sha256":"c4eca2cadf159c8413101807fe509759f0b9573f97b42340cc4e27af7aafb670","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176282/13176283/dokument799609.zip","members":["Ocena Skutków Regulacji UD319.doc"],"container_sha256":"79db76b499410cd2893f8d2fc6de91f781ed60343745930483f984171f089708","sha256":"7aadca595b1189abecc34190c50fb18327dc7edbedd6bd1ce3537ac91a3ece0d","role":"osr","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":40437,"text_sha256":"2916500abce0a94c78ed4759b80386e450c588502b95f0953ac56eba7cf3b77c","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176282/13176283/dokument799609.zip","members":["Ocena Skutków Regulacji UD319.doc"],"container_sha256":"79db76b499410cd2893f8d2fc6de91f781ed60343745930483f984171f089708","sha256":"7aadca595b1189abecc34190c50fb18327dc7edbedd6bd1ce3537ac91a3ece0d","role":"osr","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":40437,"text_sha256":"2916500abce0a94c78ed4759b80386e450c588502b95f0953ac56eba7cf3b77c","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176282/13176283/dokument799609.zip","members":["Projekt ustawy z uzsadnieniem.pdf"],"container_sha256":"79db76b499410cd2893f8d2fc6de91f78