9-14","departments":["budżet","finanse publiczne","instytucje finansowe"],"keywords":["RACHUNKOWOŚĆ"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2026/470 z dnia 24 lutego 2026 r. w sprawie zmiany dyrektyw 2006/43/WE, 2013/34/UE, (UE) 2022/2464 i (UE) 2024/1760 w odniesieniu do niektórych wymogów dotyczących sprawozdawczości przedsiębiorstw w zakresie zrównoważonego rozwoju i niektórych wymogów w zakresie należytej staranności przedsiębiorstw w zakresie zrównoważonego rozwoju","term_label":"X","stages":[{"id":13214501,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13214502,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-09-02","folders":[],"catalog_read":false},{"id":13214508,"number":3,"name":"Konsultacje publiczne","state":"reached","modified":"2026-09-02","folders":[],"catalog_read":false},{"id":13214514,"number":4,"name":"Opiniowanie","state":"reached","modified":"2026-07-10","folders":[],"catalog_read":false},{"id":13214519,"number":5,"name":"Komitet Rady Ministrów do Spraw Cyfryzacji","state":"not_started","folders":[],"catalog_read":false},{"id":13214524,"number":6,"name":"Komitet do Spraw Europejskich","state":"active","started":"2026-09-04","ended":"2026-09-14","modified":"2026-09-14","folders":[],"catalog_read":true},{"id":13214529,"number":7,"name":"Komitet Społeczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13214534,"number":8,"name":"Komitet Ekonomiczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13214539,"number":9,"name":"Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13214544,"number":10,"name":"Komisja Prawnicza","state":"not_started","folders":[],"catalog_read":false},{"id":13214545,"number":11,"name":"Potwierdzenie projektu przez Stały Komitet Rady Ministrów","state":"not_start