INSERT INTO "bills" VALUES(10,'RCL/12412454','Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw','2026-10-16T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RCL/12412454","title":"Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"OCHRONA ZDROWIA; zdrowie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-15","document_date":"2026-09-18","change_date":"2026-10-16T00:00:00Z","eu_related":false,"rcl_num":"RM-0610-155-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12412454","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','e5d8650d3ad60fa115aaa36eab77c7d0904aead071b65a6822dc81ad66d66706','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила медстрахования NFZ и возмещения расходов на лечение в ЕС/EFTA/Великобритании. Он вводит обязанности для получателей польских и зарубежных пенсий и включает в медстрахование выпускников медицинских направлений на практическом обучении и слушателей курсов польского языка.","key_changes":["Отдельная процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации (art. 42ia)","К заявлению на согласие NFZ можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Возврат за лекарство в ЕС/ЕЭЗ по польскому рецепту на возмещение, не только по трансграничному","Медстрахование для выпускников на практическом обучении (art. 15p) и слушателей подготовительных курсов польского языка","Сообщить в ZUS/KRUS об окончании работы в ЕС/EFTA/UK в течение 14 дней, иначе долг по взносам удержат из пенсии"],"affected_groups":["выпускники медицинских направлений на иностранном языке, проходящие практическое обучение в Польше","слушатели курсов польского языка и подготовительных курсов к учёбе на польском","получатели пенсий из ЕС/EFTA/UK, живущие в Польше","застрахованные в NFZ, лечащиеся в других странах ЕС/EFTA/UK","члены семей застрахованных в трансграничных ситуациях"],"practical_impact":"Выпускники-медики на практическом обучении и слушатели подготовительных курсов польского языка получают медстрахование, если не застрахованы по другому основанию. Лечение за границей проще согласовать с NFZ по заключению иностранного врача. Пенсионерам после окончания работы в ЕС/EFTA/UK нужно в течение 14 дней уведомить ZUS/KRUS.","effective_date":"Через 14 дней после опубликования; art. 1 pkt 9 lit. e и g, pkt 13 и art. 2 — через 12 месяцев; art. 1 pkt 25 и art. 3 — через 9 месяцев после опубликования.","confidence":0.8,"rationale":"Проект касается медстрахования NFZ и трансграничного лечения, в том числе групп, где много иностранцев (выпускники иноязычных медицинских программ, слушатели курсов польского языка), поэтому это социальная сфера, оценка 3.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":148783,"truncated":false,"text_source":"documents","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412454/13215502/13215503/dokument797859.zip","source_kind":"rcl","revision":2,"text_sha256":"6f722062659c34910b5eef1ce1542166e5b8b7aafdcc48621ceae7deaf0e6f6b","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-14T20:21:01+00:00','2026-10-16T17:31:03+00:00',NULL,'3141',NULL,NULL,NULL,NULL,'{"id":12412454,"title":"Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","applicant":"Minister Zdrowia","wykaz_number":"UD428","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-07-15","modified":"2026-09-23","departments":["zdrowie"],"keywords":["OCHRONA ZDROWIA"],"status":"otwarty","term_label":"X","rm_number":"RM-0610-155-26","sejm_url":"http://www.sejm.gov.pl/Sejm7.nsf/agent.xsp?symbol=RPL&Id=RM-0610-155-26","print_number":"3141","stages":[{"id":13215453,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13215454,"number":2,"name":"Uzgodnienia","state":"not_started","folders":[],"catalog_read":false},{"id":13215460,"number":3,"name":"Konsultacje publiczne","state":"not_started","folders":[],"catalog_read":false},{"id":13215466,"number":4,"name":"Opiniowanie","state":"not_started","folders":[],"catalog_read":false},{"id":13215471,"number":5,"name":"Komitet Rady Ministrów do Spraw Cyfryzacji","state":"not_started","folders":[],"catalog_read":false},{"id":13215476,"number":6,"name":"Komitet do Spraw Europejskich","state":"not_started","folders":[],"catalog_read":false},{"id":13215481,"number":7,"name":"Komitet Społeczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13215486,"number":8,"name":"Komitet Ekonomiczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13215491,"number":9,"name":"Stały Komitet Rady Ministrów","state":"reached","modified":"2026-07-29","folders":[{"id":13215492,"name":"Projekt","modified":"2026-07-29","documents":[{"id":787723,"name":"Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (UD428), KRM-0610-104-26.zip","url":"https://legislacja.rcl.gov.pl/docs//2/12412454/13215491/13215492/dokument787723.zip","created":"2026-07-16","author":"Departament Koordyn