INSERT INTO "bills" VALUES(10,'RCL/12405005','Projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw','2026-10-16T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:migracja", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen", "text:pracownicy_delegowani"]','{"term":10,"number":"RCL/12405005","title":"Projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","description":"STRAŻ GRANICZNA; sprawy wewnętrzne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-08","document_date":"2026-09-14","change_date":"2026-10-16T00:00:00Z","eu_related":true,"rcl_num":"RM-0610-143-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405005","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-03-25","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','d091ff7eb033c0983ba7801c3a73658a537227373907f832bf6d874225423339','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект приводит польские законы в соответствие с регламентом ЕС о Frontex. Он определяет полномочия Коменданта Главного Straży Granicznej, правила командирования польских пограничников в Frontex и регистрацию служебных машин Агентства. Для иностранцев значение имеет новая правовая база для операций и интервенций по возвращению (депортации), проводимых при поддержке Frontex на территории Польши.","key_changes":["В ustawa o cudzoziemcach вводятся понятия «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС 2019/1896","Новый art. 329b: Komendant Główny SG запрашивает и согласовывает операции возврата с участием Frontex в Польше","Сотрудники Frontex и погранслужб других стран ЕС смогут выполнять задачи по возвратам в Польше, включая применение силы","Komendant Główny SG назначается национальным контактным пунктом и координационным центром для Frontex (EUROSUR)","Frontex получит право регистрировать свои служебные автомобили и пользоваться статусом привилегированного транспорта"],"affected_groups":["иностранцы с решением о возврате (депортации)","лица, пересекающие внешнюю границу Польши","иностранцы без урегулированного статуса"],"practical_impact":"Процедуры депортации из Польши могут чаще проводиться в рамках совместных операций с Frontex, с участием иностранного персонала, имеющего право применять силу. На порядок выдачи разрешений на пребывание или работу проект не влияет.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Проект в основном институциональный (Frontex, Straż Graniczna), но меняет ustawa o cudzoziemcach в части операций по возвращению, что косвенно затрагивает иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":116489,"truncated":false,"text_source":"documents","created_at":"2026-09-14T20:21:47Z","input_tokens":55992,"output_tokens":697,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174615/13174616/dokument796916.zip","source_kind":"rcl","revision":1,"text_sha256":"3ef925cd0b4e25bcc121073127a2525eadd183dab133c4c6aed39031ece5f2e6","source_che