Spraw Europejskich","state":"not_started","folders":[],"catalog_read":false},{"id":13210779,"number":7,"name":"Komitet Społeczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13210784,"number":8,"name":"Komitet Ekonomiczny Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13210789,"number":9,"name":"Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13210794,"number":10,"name":"Komisja Prawnicza","state":"not_started","folders":[],"catalog_read":false},{"id":13210795,"number":11,"name":"Potwierdzenie projektu przez Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13210800,"number":12,"name":"Rada Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13210806,"number":13,"name":"Notyfikacja","state":"not_started","folders":[],"catalog_read":false},{"id":13210807,"number":14,"name":"Skierowanie projektu ustawy do Sejmu","state":"not_started","folders":[],"catalog_read":false}],"consultation":{"letter_url":"https://legislacja.rcl.gov.pl/docs//2/12411650/13210758/13210760/dokument783206.pdf","letter_date":"2026-06-19","days":30,"deadline":"2026-07-19","email":"sekretariatDGMiZS@mi.gov.pl","positions":13,"response_published":true,"letters_read":["https://legislacja.rcl.gov.pl/docs//2/12411650/13210758/13210760/dokument783206.pdf"],"letter_parser":2},"consultation_attempts":0}',NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}],"document":{"url":"https://legislacja.rcl.gov.pl/docs//2/12411650/13210764/13210765/dokument783211.pdf","kind":"rcl","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"48c4fa6122b06be1ee3d21ff6a70ca34f66153682d68f3fc8fbea0d4db0c1919","analysis_revision":1}',0,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Иностранная минималка морякам","language":"ru","basis":"Проект привязывает минимальную зарплату моряков-нерезидентов к минималке в стране их постоянного проживания и меняет для них правила соцстрахования в Польше.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12410308','Projekt ustawy o zawodzie pielęgniarki i zawodzie położnej','2026-05-15T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:legalizacja", "text:granica_panstwowa", "text:ochrona_miedzynarodowa", "text:zatrudnianie_cudzoziemcow", "text:status_uchodzcy", "text:obywatele_innych_panstw", "text:zezwolenie_praca", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RCL/12410308","title":"Projekt ustawy o zawodzie pielęgniarki i zawodzie położnej","description":"OCHRONA ZDROWIA; zdrowie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-15","document_date":"2026-05-15","change_date":"2026-05-15T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12410308","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]}]','c379539fc296a88087d780e8276d09f4b09ba9a3be5db946b603327d59607046','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Новый закон о профессии медсестры и акушерки меняет правила допуска к профессии для иностранцев. Вводится государственный верификационный экзамен (PEW) для обладателей дипломов, полученных вне ЕС, и обязательный экзамен по польскому языку, который будет принимать Naczelna Rada Pielęgniarek i Położnych.","key_changes":["Введён экзамен PEW в CEM для дипломов, полученных вне ЕС — альтернатива нострификации","Экзамен по польскому языку через Naczelna Rada, платный, с выдачей справки","Иностранцу право на профессию даётся при виде на жительство stały; возможен и срок при иных условиях","Обязательный адаптационный стаж: 6 мес. для иностранцев, 12 мес. для выпускников (не требует разрешения на работу)","Право на профессию прекращается при утрате PESEL-статуса: отзыве pobytu stałego или статуса резидента ЕС"],"affected_groups":["медсёстры и акушерки с дипломами вне ЕС","граждане ЕС и члены их семей","обладатели статуса беженца и дополнительной защиты","долгосрочные резиденты ЕС","иностранные студенты медицинских направлений","обладатели Blue Card и разрешений на временное пребывание"],"practical_impact":"Иностранная медсестра или акушерка сможет подтвердить квалификацию через экзамен PEW вместо сложной нострификации диплома, но должна будет сдать платный экзамен по польскому и пройти 6-месячный адаптационный стаж. Право на профессию будет прекращаться при отзыве постоянного вида на жительство или статуса долгосрочного резидента ЕС.","effective_date":"Закон вступает в силу 1 марта 2027 г.; практический экзамен PESP впервые — в весеннюю сессию 2032 г.","confidence":0.85,"rationale":"Закон напрямую регулирует допуск иностранцев к профессии и работе в Польше, включая новые экзамены и стажи, а также связывает право на профессию со статусом пребывания.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":401677,"truncated":false,"text_source":"documents","created_at":"2026-09-15T01:42:49Z","input_tokens":198721,"output_tokens":764,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12410308/13204102/13204103/dokument776516.pdf","source_kind":"rcl","revision":1,"text_sha256":"8a8275745cdd4a404f9a6c6ac286b1e133d43ea9b64dff88158303be22692a09","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T01:38:42+00:00','2026-10-28T19:16:54+00:00',NULL,