INSERT INTO "bills" VALUES(10,'RCL/12405503','projekt ustawy o zmianie ustawy - Kodeks karny oraz ustawy - Kodeks postępowania karnego','2026-05-26T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo"]','{"term":10,"number":"RCL/12405503","title":"projekt ustawy o zmianie ustawy - Kodeks karny oraz ustawy - Kodeks postępowania karnego","description":"KARNE PRAWO; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-22","document_date":"2026-02-26","change_date":"2026-05-26T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405503","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"1. Zgłoszenia lobbingowe","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2025-12-22","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","date":"2025-12-22","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","date":"2025-12-22","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','98606b171b6a76adc8dfd8d0666fc83bfe1b48611ef5783e0216ab0b5dec28c2','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила универсальной юрисдикции: польский уголовный закон уточняется в части преследования самых тяжких международных преступлений (ст. 5–8bis Римского статута) и позволяет начинать дела против иностранцев, находящихся за пределами Польши. На такое преследование потребуется согласие Prokurator Generalny.","key_changes":["Ст. 113 Kodeks karny ограничивается преступлениями из ст. 5–8bis Римского статута","Убрано условие «которого не решено выдать» — дела можно вести против иностранцев за границей","Новый ст. 10 § 3 k.p.k.: согласие Prokurator Generalny на преследование иностранца вне Польши","Дела по ст. 70 Римского статута, начатые ранее, подлежат прекращению (с исключениями)","Уточнена ст. 237 § 3 п. 19 k.p.k. (прослушивание) — добавлена ссылка на ст. 8bis"],"affected_groups":["иностранцы, находящиеся за пределами Польши и подозреваемые в международных или террористических преступлениях","прокуратура и суды"],"practical_impact":"Для иностранцев, законно живущих в Польше, ничего не меняется: речь идёт только о юрисдикции по тягчайшим международным и террористическим преступлениям, совершённым за границей.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.9,"rationale":"Иностранцы упомянуты лишь как субъекты уголовной юрисдикции за границей, статус и права проживающих в Польше не затрагиваются.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":35374,"truncated":false,"text_source":"documents","created_at":"2026-09-15T01:42:42Z","input_tokens":17560,"output_tokens":653,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405503/13177018/13177019/dokument764748.zip","source_kind":"rcl","revision":1,"text_sha256":"3cbece85608871064d4daae81a6f7fd4ee9c463d98b6b4fe54d16f70ef1aec5e","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T01:39:17+00:00','2026-10-28T19:17:21+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12405503,"title":"projekt ustawy o zmianie ustawy - Kodeks karny oraz ustawy - Kodeks postępowania karnego","applicant":"Minister Sprawiedliwości","wykaz_number":"UD344","wykaz_url":"https://legislacja.rcl.gov.pl/","created":"2025-12-22","mod