INSERT INTO "bills" VALUES(10,'RCL/12405805','Projekt ustawy o zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych','2026-10-19T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:obywatele_ukrainy", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:zezwolenie_praca"]','{"term":10,"number":"RCL/12405805","title":"Projekt ustawy o zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych","description":"INFORMATYZACJA; informatyzacja","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-01-05","document_date":"2026-10-19","change_date":"2026-10-19T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405805","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','28948bced019d59f38d3fb042f5abee70e0421ba664b7e175cafcfb1c76d9459','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет работу реестра PESEL, актов гражданского состояния и паспортного реестра. Иностранцам сложнее получить PESEL только ради профиля zaufany, в PESEL добавят данные о типе проездного документа и упростят выписку из адреса.","key_changes":["Нельзя будет просить PESEL только из‑за требования для профиля zaufany","В реестре PESEL появится тип проездного документа/удостоверения личности иностранца","Выписаться и заявить выезд за границу можно будет в любой гмине, а не только по месту жительства","Снять зastrzeżenie номера PESEL сможет представитель по адвокатской или нотариальной доверенности","Возврат к добрачной фамилии после развода можно будет оформить онлайн через USC"],"affected_groups":["Иностранцы, получающие или уже имеющие номер PESEL","Иностранцы, обращающиеся за profil zaufany через консульства","Иностранцы, снимающиеся с регистрации по месту жительства или выезжающие из Польши","Разведённые иностранцы, чей брак зарегистрирован в Польше"],"practical_impact":"Иностранцы вне Польши не смогут получить PESEL, ссылаясь лишь на необходимость профиля zaufany; нужен иной правовой повод (пребывание, работа, налоги и т.п.). В базе PESEL будет храниться тип вашего проездного документа, проще подать заявление о выписке в любой гмине и через представителя разблокировать PESEL.","effective_date":"Закон вступит в силу через 14 дней после опубликования, кроме ст. 1, ст. 2 пп. 1, 2, 10 и 11 и ст. 3, которые вступят в силу 1 февраля 2028 г.","confidence":0.88,"rationale":"Проект явно меняет правила присвоения и использования PESEL и связанных услуг (meldunek, данные документов), важные для иностранцев, но не затрагивает напрямую легализацию пребывания, поэтому это социальная сфера средней важности (3).","mnemonic_candidate":"PESEL только при связи","mnemonic_fallback":"Изменения PESEL и реестров","mnemonic_basis":"Проект прямо исключает возможность просить PESEL лишь ради профиля zaufany и подчёркивает, что номер должен даваться лицам, имеющим связь с Польшей, одновременно расширяя данные и услуги в реестрах.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":41393,"truncated":false,"text_source":"documents","created_at":"2026-10-21T18:50:51Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","source_kind":"rcl","revision":2,"text_sha256":"text-v2:af89cf71126263629e7d5155c327939bce49eae1b7c2dc1f14cb8a78952c4f96","selection":{"question":"bill_text","state":"selected","belonging":[],"role":[],"version":["rcl/12405805/stage/13179001","KP - MC - projekt ustawy, uzasadnienie w tym OSR.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","members":[],"container_sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":41394,"text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","members":[],"container_sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","sha256":"25a6a8e0a7bf81c5d6a7748159b649c4e5595147eb4d8800218e3bd181aed95b","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":41394,"text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178996/13178997/dokument791976.zip","members":["SKRM_SRP_UD337 - pismo.pdf"],"container_sha256":"d807fe9ccccdd9866ab1b2b80e35273f2b91db4b909ef1d1910054eecd31c987","sha256":"f10c20785d79f621142f858be30b9d96cadc3cdbd9268177b6c28b3b555a65fd","role":"unknown","text":"","pages":2,"page_start":1,"page_end":2,"text_start":0,"text_end":3202,"text_sha256":"63a8c1d2a36f4fa73a163a1c7d2311ecfaf3be31bd0585158dcbfff315943347","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178996/13178997/dokument791976.zip",