3178996/13178997/dokument791976.zip","members":["SKRM_SRP_UD337 - zal do raportu tabela uwag opiniowanie.docx"],"container_sha256":"d807fe9ccccdd9866ab1b2b80e35273f2b91db4b909ef1d1910054eecd31c987","sha256":"eb8af6e011207ad753d4ed3886551eee5b8c608cb90675b5ad29c89a5e3a889b","role":"unknown","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":29208,"text_sha256":"cdf4c8d1141a21b65d8eed7d37a206a99bdb26e9b39d7a3a73a5cdf24a02fb08","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12405805/stage/13179001","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":0,"end":506,"quote":"Projekt z dnia 22 września 2026 r.\nUSTAWA\nz dnia … 2026 r.\no zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych [przypis 1: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 25 lutego 1964 r. – Kodeks rodzinny i opiekuńczy, ustawę z dnia 24 września 2010 r. o ewidencji ludności, ustawę z dnia 28 listopada 2014 r. – Prawo o aktach stanu cywilnego oraz ustawę z dnia 27 stycznia 2022 r. o dokumentach paszportowych.] ) \nArt. 1"},{"kind":"draft_date","value":"2026-09-22","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13179001/dokument802926.docx","text_sha256":"4f308bd7de7a478d479370153c81eb21ad8da0f8ab91f1cb543ec07319c2c35d","block_id":"part:0","start":0,"end":31,"quote":"Projekt z dnia 22 września 2026"},{"kind":"cover