INSERT INTO "bills" VALUES(10,'RCL/12407104','Projekt ustawy o zmianie ustaw w celu optymalizacji niektórych procesów w zakresie spraw obywatelskich','2026-07-14T00:00:00+00:00',NULL,NULL,'analyzed','["text:obywatelstwo", "text:straz_graniczna", "text:schengen"]','{"term":10,"number":"RCL/12407104","title":"Projekt ustawy o zmianie ustaw w celu optymalizacji niektórych procesów w zakresie spraw obywatelskich","description":"DOWODY OSOBISTE; PASZPORTY I INNE DOKUMENTY PODRÓŻY; sprawy wewnętrzne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-12","document_date":"2026-02-12","change_date":"2026-07-14T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12407104","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','8d07b827eeb6235c9afb76a33dc629a33bb4a21e63f1ebbb5588ed12c0bb13f1','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект касается польских граждан: dowody osobiste, паспорта, акты гражданского состояния. Для иностранцев прямых изменений нет; косвенно затрагиваются дела о гражданстве — MSWiA получит доступ к Rejestr Dokumentów Paszportowych и Rejestr Dowodów Osobistych при проверке данных.","key_changes":["MSWiA получит доступ к паспортному реестру и реестру dowodów osobistych в делах о гражданстве","Признание гражданином без транскрипции иностранного акта — основание отказать в приёме заявления на паспорт","Возможность убрать «скрытые» данные отца из акта о рождении по заявлению","Dowód osobisty для лиц старше 70 лет — срок действия 15 лет","Получение dowodu osobistego в любой выбранной гмине"],"affected_groups":["лица, ходатайствующие о польском гражданстве или его подтверждении","лица, признанные гражданами Польши, проживающие за границей","обладатели Karty Polaka и репатрианты — не затрагиваются"],"practical_impact":"Для иностранцев без польского гражданства практически ничего не меняется; заявители по делам о гражданстве могут столкнуться с более тщательной проверкой данных по реестрам, а признанные гражданами за границей — с отказом в приёме паспортного заявления без транскрипции акта.","effective_date":"Закон вступает в силу 1 июля 2026 г., отдельные положения — в дни, указанные в сообщениях министра (не ранее чем через 14 дней после объявления).","confidence":0.85,"rationale":"Документ регулирует сферу граждан Польши; иностранцев затрагивает лишь косвенно через процедуры по делам о гражданстве.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":106046,"truncated":false,"text_source":"documents","created_at":"2026-09-15T01:42:02Z","input_tokens":52661,"output_tokens":635,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12407104/13186901/13186902/dokument762718.docx","source_kind":"rcl","revision":1,"text_sha256":"7b89c260f4635e34771bd7610e3618f513720de56beb3219d2e772f42d7fa3c3","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T01:40:07+00:00','2026-10-28T19:17:32+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12407104,"title":"Projekt ustawy o zmianie ustaw w celu optymalizacji niektórych procesów w zakresie spraw obywatelskich","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UD329","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-02-12","mo