INSERT INTO "bills" VALUES(10,'RCL/12402301','Projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw','2026-10-02T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RCL/12402301","title":"Projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw","description":"KRAJOWY REJESTR SĄDOWY; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-19","document_date":"2025-09-19","change_date":"2026-10-02T00:00:00Z","eu_related":false,"rcl_num":"RM-0610-125-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12402301","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2025-09-19","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","date":"2025-09-19","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","date":"2025-09-19","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','b6ec7ed06538640c05d5db6324dff864a302cacf2040763b6ea7675ba5666db2','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила работы KRS (судебного реестра): электронизация дел, новые пометки о несдаче финансовой отчётности, упрощённая ликвидация «мёртвых» компаний, обязательное правовое основание на помещение для адреса фирмы. Иностранцы упоминаются лишь как лица, о статусе которых подаётся заявление при покупке долей и акций.","key_changes":["Уточнено заявление о том, является ли приобретатель долей/акций cudzoziemcem по ustawa z 1920 r.","Заявление о том, владеет ли компания недвижимостью в Польше, при участии иностранца","Обязанность иметь правовое основание на помещение по адресу регистрации фирмы","Все обращения и переписка с реестровым судом — только через ИТ-систему и счёт подмиота","Новая пометка в KRS о несдаче финансовых документов и роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — участники и акционеры польских компаний","предприниматели, зарегистрированные в KRS","нотариусы"],"practical_impact":"Иностранцам, покупающим доли или акции польских компаний, придётся точнее указывать свой статус в заявлениях в KRS; фирмам понадобится документ о праве на помещение по адресу регистрации.","effective_date":"Закон вступает в силу 1 октября 2027 г., отдельные положения — 1 октября 2028 г.","confidence":0.85,"rationale":"Иностранцы затронуты лишь косвенно — через уточнение заявлений о статусе cudzoziemca при приобретении долей, что не влияет на пребывание, работу или социальные права.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":196209,"truncated":false,"text_source":"documents","created_at":"2026-09-15T15:48:21Z","input_tokens":95125,"output_tokens":604,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402301/13157458/13157459/dokument790436.zip","source_kind":"rcl","revision":1,"text_sha256":"5361109f4f3f8b80ade4be8a27eedab4a3d3db104bfb26198fb7a27270563468","source_checked_at":null}',0,NULL,'2026-09-15T01:41:01+00:00','2026-10-02T14:31:51+00:00',NULL,'3004',NULL,NULL,NULL,NULL,'{"id":12402301,"title":"Projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw","applicant":"Minister Sprawiedliwości","wykaz_number":"UDER49","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-ksiegach-wieczystych-i-hipotece","created":"2025-09-19","modified":"2026-09-03","departments":["sprawiedliwość"],"keywords":["KRAJOWY REJESTR SĄDOWY"],"status":"otwarty","term_label":"X","rm_number":"RM-0610-125-26","sejm_url":"http://www.sejm.gov.pl/Sejm7.nsf/agent.xsp?symbol=RPL&Id=RM-0610-125-26","print_number":"3004","stages":[{"id":13157409,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13157410,"number":2,"name":"Uzgodnienia","state":"reached","started":"2025-09-19","modified":"2025-10-28","folders":[{"id":13157411,"name":"Projekt","modified":"2025-09-19","documents":[{"id":738207,"name":"Projekt ustawy o zmianie uKRS UDER49","url":"https://legislacja.rcl.gov.pl/docs//2/12402301/13157410/13157411/dokument738207.docm","created":"2025-09-19","author":"Minister Sprawiedliwości"},{"id":738208,"name":"Uzasadnienie do projektu UDER49","url":"https://legislacja.rcl.gov.pl/docs//2/12402301/13157410/13157411/dokument738208.docx","created":"2025-09-19","author":"Minister Sprawiedliwości"},{"id":738209,"name":"Ocena Skutków Regulacji 19.09.25 KRS","url":"https://legislacja.rcl.gov.pl/docs//2/12402301/13157410/13157411/dokument738209.doc","created":"2025-09-19","author":"Minister Sprawiedliwości"}]},{"id":13157412,"name":"Pisma kierujące projekt do uzgodnień","modified":"2025-09-19","documents":[{"id":738210,"name":"Pismo - uzgodnienia międzyresortowe - rozdzielnik","url":"https://legislacja.rcl.gov.pl/docs//2/12402301/13157410/13157412/dokument738210.pdf","created":"2025-09-19","author":"Minister Sprawiedliwości"}]},{"id":13157413,"name":"Stanowiska zgłoszone w ramach uzgodnień","modified":"2025-10-28","documents":[{"id":744951,"name":"Uwagi - uzgodnienia - RCL (brak uwag)","url":"https://legislacja.rcl.gov.pl/docs//2/12402301/13157410/13157413/dokument744951.pdf","created":"2025-10-28","author":"Minister Sprawiedliwości"},{"id":744952,"name":"Uwagi - uzgodnienia - Koordy