INSERT INTO "bills" VALUES(10,'RCL/12400301','Projekt ustawy o mediatorach sądowych, instytucjach szkolących w zakresie mediacji i Krajowym Rejestrze Mediatorów (POPRZEDNI TYTUŁ: Projekt ustawy o mediatorach sądowych, akredytowanych ośrodkach mediacyjnych i Krajowym Rejestrze Mediatorów)','2026-10-20T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RCL/12400301","title":"Projekt ustawy o mediatorach sądowych, instytucjach szkolących w zakresie mediacji i Krajowym Rejestrze Mediatorów (POPRZEDNI TYTUŁ: Projekt ustawy o mediatorach sądowych, akredytowanych ośrodkach mediacyjnych i Krajowym Rejestrze Mediatorów)","description":"MEDIACYJNE POSTĘPOWANIE; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-24","document_date":"2025-07-24","change_date":"2026-10-20T00:00:00Z","eu_related":false,"rcl_num":"RM-0610-119-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12400301","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"1. Zgłoszenia lobbingowe","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','0f2117b0badf97a7ffb56b1625fb1dbe71b03333455641c4f3879c4a0ea72015','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Законопроект вводит новую профессию \"mediator sądowy\" (судебный медиатор), Krajowy Rejestr Mediatorów (национальный реестр медиаторов) и требования к обучающим организациям. Иностранцы упоминаются лишь в контексте возможности стать медиатором: вместо PESEL можно указать паспорт или документ по ustawa o cudzoziemcach, а неграждане подтверждают знание польского на уровне B2.","key_changes":["Вводится статус mediator sądowy с записью в Krajowy Rejestr Mediatorów","При отсутствии PESEL в заявлении указываются паспорт или документ по ustawa o cudzoziemcach","Лица без польского гражданства прилагают документ о знании польского языка на уровне B2","Требования: 26 лет, высшее образование, базовое и специализационное обучение, несудимость","Возможен учёт зарубежного образования, признанного в Польше"],"affected_groups":["Иностранцы, желающие работать судебными медиаторами в Польше","Действующие медиаторы без польского гражданства","Участники судебных процессов, ищущие медиатора, говорящего на иностранном языке"],"practical_impact":"Иностранец, желающий быть судебным медиатором, должен подтвердить знание польского языка на уровне B2 и может использовать паспорт или документ по ustawa o cudzoziemcach вместо PESEL. В реестре можно указать языки, кроме польского, что упрощает поиск медиатора для иностранцев.","effective_date":"Закон вступает в силу 1 сентября 2027 года.","confidence":0.85,"rationale":"Закон касается организации медиации, а иностранцы фигурируют лишь эпизодически (идентификация без PESEL и требование B2), поэтому значимость маргинальная.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":135549,"truncated":false,"text_source":"documents","created_at":"2026-09-15T15:48:29Z","input_tokens":65485,"output_tokens":664,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/1