INSERT INTO "bills" VALUES(10,'3085','Rządowy projekt ustawy o zmianie ustawy - Prawo upadłościowe, ustawy - Prawo restrukturyzacyjne oraz ustawy o Krajowym Rejestrze Zadłużonych','2026-09-15T08:57:43+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3085","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo upadłościowe, ustawy - Prawo restrukturyzacyjne oraz ustawy o Krajowym Rejestrze Zadłużonych","description":"projekt dotyczy usprawnienia postępowań dotyczących oddłużania osób fizycznych. Zmiany mają przede wszystkim usprawnić upadłość osób fizycznych, zarówno prowadzących działalność gospodarczą, jak i tzw. upadłość konsumencką. Chodzi w szczególności o etap, w którym osoba zadłużona realizuje plan spłaty wierzycieli, czyli ustalony przez sąd sposób i okres spłacania części swoich długów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-04","document_date":"2026-09-04","change_date":"2026-09-15T08:57:43Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-15T10:11:52+00:00','2026-09-16T10:05:08+00:00','{"term":10,"number":"RPW/29806/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo upadłościowe, ustawy - Prawo restrukturyzacyjne oraz ustawy o Krajowym Rejestrze Zadłużonych","description":"usprawnienia postępowań dotyczących oddłużania osób fizycznych. Zmiany mają przede wszystkim usprawnić upadłość osób fizycznych, zarówno prowadzących działalność gospodarczą, jak i tzw. upadłość konsumencką. Chodzi w szczególności o etap, w którym osoba zadłużona realizuje plan spłaty wierzycieli, czyli ustalony przez sąd sposób i okres spłacania części swoich długów.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-04","print_number":"3085","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3086','Rządowy projekt ustawy o zmianie ustawy o służbie zagranicznej oraz ustawy o finansach publicznych','2026-10-23T08:21:23+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3086","title":"Rządowy projekt ustawy o zmianie ustawy o służbie zagranicznej oraz ustawy o finansach publicznych","description":"projekt dotyczy przedłużenia obowiązujących przepisów dotyczących polskich placówek zagranicznych oraz usprawnienia ich funkcjonowania. Chodzi o uporządkowanie zasad pracy osób delegowanych przez inne resorty oraz wprowadzenie możliwości wspólnej obsługi finansowej placówek. Zmiany pozwolą ograniczyć obciążenia administracyjne, lepiej wykorzystać dostępne zasoby i zapewnić jednolite standardy obsługi finansowej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-03","document_date":"2026-09-03","change_date":"2026-10-23T08:21:23Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-15T10:11:53+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/29632/2026","title":"Rządowy projekt ustawy o zmianie ustawy o służbie zagranicznej oraz ustawy o finansach publicznych","description":"przedłużenia obowiązujących przepisów dotyczących polskich placówek zagranicznych oraz usprawnienia ich funkcjonowania. Chodzi o uporządkowanie zasad pracy osób delegowanych przez inne resorty oraz wprowadzenie możliwości wspólnej obsługi finansowej placówek. Zmiany pozwolą ograniczyć obciążenia administracyjne, lepiej wykorzystać dostępne zasoby i zapewnić jednolite standardy obsługi finansowej.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-03","print_number":"3086","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3087','Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz ustawy - Kodeks karny skarbowy','2026-10-09T13:41:15+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3087","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz ustawy - Kodeks karny skarbowy","description":"projekt dotyczy wprowadzenia rozwiązań, które mają przyspieszyć postępowania karne i ułatwić szybkie naprawienie szkody wyrządzonej pokrzywdzonym. W przypadkach, w których okoliczności popełnienia przestępstwa są jasne, strony będą mogły szerzej korzystać z porozumień prowadzących do szybkiego zakończenia sprawy. W zamian za współpracę i spełnienie określonych warunków oskarżony będzie mógł skorzystać z łagodniejszej kary.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-09","document_date":"2026-09-09","change_date":"2026-10-09T13:41:15Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-138-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-138-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-09","print_number":"3087","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-09","sitting_num":66,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-09","committee_code":"NKK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-09","print_number":"3087","sub_committee":false,"children