INSERT INTO "bills" VALUES(10,'3088','Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw','2026-10-23T08:33:19+00:00','2026-10-22',1,'analyzed','[]','{"term":10,"number":"3088","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"projekt dotyczy zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-10","document_date":"2026-09-10","change_date":"2026-10-23T08:33:19Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-141-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-141-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-10","print_number":"3088","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"GOR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"DER","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-08","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-08","sub_committee":fals