INSERT INTO "bills" VALUES(10,'2007','Poselski projekt ustawy o zmianie ustawy o wychowaniu w trzeźwości i przeciwdziałaniu alkoholizmowi oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych','2026-10-09T12:20:50+00:00','2026-10-08',1,'analyzed','[]','{"term":10,"number":"2007","title":"Poselski projekt ustawy o zmianie ustawy o wychowaniu w trzeźwości i przeciwdziałaniu alkoholizmowi oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych","description":"projekt dotyczy ograniczenia nadmiernej dostępności alkoholu i przeciwdziałanie jego promocji poprzez m.in całkowity zakaz reklamy i promocji wszystkich napojów alkoholowych, w tym piwa; zakaz sprzedaży alkoholu na stacjach paliw, w zakładach leczniczych oraz w godzinach nocnych na terenie całego kraju (22-6), wprowadzenie obowiązku weryfikacji wieku przy zakupie; zakaz sprzedaży alkoholu poniżej sumy podatku akcyzowego i VAT; uregulowanie sprzedaży internetowej wyłącznie z odbiorem osobistym po okazaniu dokumentu tożsamości","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-23","document_date":"2025-09-22","change_date":"2026-10-09T12:20:50Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["2010"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-09-23","print_number":"2007","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-01","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-12-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-12-05","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-01-23","sitting_num":50,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-01-23","committee_code":"ZDR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Sprawozdanie podkomisji","stage_type":"CommitteeReport","date":"2026-07-15","report_file":"https://api.sejm.gov.pl/sejm/term10/processes/2007/attachment/spr_2007_2010.pdf","sub_committee":true,"minority_motions":0,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-29","print_number":"2856","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2856/2856.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-15","sitting_num":65,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"ZDR","sub_committee":false,"children":[]}]}]','35861de2a2e3766465acda99ad2b2a898297bc5891902515a67ad14df573626b','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается ограничения продажи, рекламы и продвижения алкогольных напитков в Польше и не содержит положений, затрагивающих правовой статус, пребывание или права иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается ограничения продажи, рекламы и продвижения алкогольных напитков в Польше и не содержит положений, затрагивающих правовой статус, пребывание или права иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T12:29:30Z","input_tokens