INSERT INTO "bills" VALUES(10,'RCL/12414651','Projekt ustawy o zmianie ustawy o działalności ubezpieczeniowej i reasekuracyjnej oraz ustawy o nadzorze nad rynkiem finansowym','2026-10-27T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12414651","title":"Projekt ustawy o zmianie ustawy o działalności ubezpieczeniowej i reasekuracyjnej oraz ustawy o nadzorze nad rynkiem finansowym","description":"UBEZPIECZENIA MAJĄTKOWE I OSOBOWE; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2025/2 z dnia 27 listopada 2024 r. w sprawie zmiany dyrektywy 2009/138/WE w odniesieniu do proporcjonalności, jakości nadzoru, sprawozdawczości, środków dotyczących gwarancji długoterminowych, narzędzi makroostrożnościowych, ryzyk dla zrównoważonego rozwoju oraz nadzoru nad grupą i nadzoru transgranicznego, a także w sprawie zmiany dyrektyw 2002/87/WE i 2013/34/UE (Dz. Urz. UE L 2025/2 z 08.01.2025).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-10-27T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12414651","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','9f1b489ed54ad62351cd91869685246a1d39525561a8df063f393374fb253565',NULL,0,'text prefilter: no keyword hits','2026-09-15T13:50:18+00:00','2026-10-27T18:45:06+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12414651,"title":"Projekt ustawy o zmianie ustawy o działalności ubezpieczeniowej i reasekuracyjnej oraz ustawy o nadzorze nad rynkiem finansowym","applicant":"Minister Finansów i Gospodarki","wykaz_number":"UC159","wykaz_ur