INSERT INTO "bills" VALUES(10,'3099','Rządowy projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych','2026-10-26T09:34:42+00:00','2026-09-18',1,'analyzed','["text:pobyt_kwalifikowany"]','{"term":10,"number":"3099","title":"Rządowy projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych","description":"projekt dotyczy podwyższenia z 1 tys. zł do 3 tys. zł limitu zwolnienia z podatku od czynności cywilnoprawnych przy sprzedaży rzeczy ruchomych. Chodzi np. o odsprzedawane przez osoby prywatne meble, telefony, komputery czy sprzęt AGD. Nowe przepisy wprowadzają także zmiany dotyczące opłaty miejscowej i opłaty uzdrowiskowej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-10-26T09:34:42Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-148-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-148-26","prints_considered_jointly":["2033","2127","2872"],"eli":"DU/2026/1354","display_address":"Dz.U. 2026 poz. 1354","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001354"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-15","print_number":"3099","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-16","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-16","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-16","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-16","print_number":"3118","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3118/3118.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":3,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2033/attachment/2033_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":269,"no":141,"abstain":28,"not_participating":22,"sitting":65,"voting_number":132,"date":"2026-09-18T09:47:51Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/132/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-09-24","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','d2360e8bfbc22918c1c165b25b49cbebf67d58368f004a68ec16ca51928a1e88','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила opłata miejscowa и opłata uzdrowiskowa (местный и курортный сборы). Их будет платить каждый, кто хотя бы одну ночь проживает в гостинице, пансионате или санатории в таких местностях, а удерживать сбор будет объект размещения. Кроме того, растёт порог освобождения от PCC при продаже движимых вещей.","key_changes":["Сбор взимается за каждую ночь проживания в объекте размещения, независимо от цели поездки","Максимальные ставки: 5,00 zł и 5,50 zł (местный), 6,86 zł за ночь (курортный)","Освобождение при проживании более 29 ночей подряд в объектах одной гмины","Сбор удерживают объекты размещения (płatnik); они могут требовать предоплату за заявленные ночи","Лимит освобождения от PCC при продаже движимых вещей: с 1000 до 3000 zł"],"affected_groups":["иностранные туристы и гости","иностранцы, живущие в гостиницах и хостелах в курортных и туристических местностях","сотрудники дипломатических и консульских представительств, не являющиеся гражданами Польши"],"practical_impact":"При заселении в гостиницу или санаторий в местности со сбором иностранец, как и гражданин Польши, платит его объекту размещения, возможно авансом за заявленные ночи; при проживании более 29 ночей подряд сбор не взимается. Иностранцы специально не выделяются, кроме сохранённого освобождения для дипперсонала без постоянного места пребывания в Польше.","effective_date":"Закон вступает в силу 1 января 2027 г., за исключением ст. 3 и ст. 10 (изменения PCC), которые вступают в силу через 14 дней после опубликования.","confidence":0.8,"rationale":"Это общая реформа местных сборов и налогов, которая касается всех одинаково; иностранцы упомянуты только в связи с освобождением для дипперсонала, поэтому влияние маргинальное.","changes_since_previous":["Изменены максимальные ставки местного сбора: теперь до 5,00 zł и до 5,50 zł за ночь вместо указанных ранее 3,56 zł и 5,03 zł; курортный сбор остался до 6,86 zł","Из условий введения местного сбора исключён критерий благоприятных климатических условий; достаточно ландшафтных достоинств местности, критерии которых определит rozporządzenie Rady Ministrów","Рада гмины может дифференцировать ставки или вводить освобождения по месту жительства, возрасту, наличию Karta Dużej Rodziny, степени инвалидности, сезону и длительности пребывания","Для объектов размещения до конца 2029 г. разрешена подача ежемесячной информации о сборе в бумажном виде"]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":25964,"truncated":false,"text_source":"documents","created_at":"2026-09-28T16:14:59Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206829/13206830/dokument796915.zip","source_kind":"rcl","revision":2,"text_sha256":"c2f429077b42f7e6a40a19d8dfd9157ac90fcc055b0f22523eb1ffdcb833dfc2","source_checked_at":"2026-09-28T16:14:59Z"}',0,NULL,'2026-09-15T15:46:09+00:00','2026-10-27T18:44:55+00:00','{"term":10,"number":"RPW/31028/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych","description":"podwyższenia z 1 tys. zł do 3 tys. zł limitu zwolnienia z podatku od czynności cywilnoprawnych przy sprzedaży rzeczy ruchomych. Chodzi np. o odsprzedawane przez osoby prywatne meble, telefony, komputery czy sprzęt AGD. Nowe przepisy wprowadzają także zmiany dotyczące opłaty miejscowej i opłaty uzdrowiskowej.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-15","print_number":"3099","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RCL/12410853',NULL,NULL,NULL,NULL,NULL,NULL,'UD372',NULL,NULL,NULL,'2026-09-18','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-15","print_number":"3099","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-16","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-16","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-16","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-16","print_number":"3118","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3118/3118.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":3,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2033/attachment/2033_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-18","sub_committee":false,"voting":{"yes":269,"no":141,"abstain":28,"not_participating":22,"sitting":65,"voting_number":132,"date":"2026-09-18T09:47:51Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/132/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-09-24","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"closure_date":"2026-09-18","passed":true,"document":{"url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206829/13206830/dokument796915.zip","kind":"rcl","extra_urls":[]},"analysis_sha256":"c2f429077b42f7e6a40a19d8dfd9157ac90fcc055b0f22523eb1ffdcb833dfc2","analysis_revision":2}',1,NULL,NULL,NULL,'metadata','below_bar',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3100','Rządowy projekt ustawy o podatku od nadzwyczajnych zysków osiągniętych w okresie od marca do grudnia 2026 r. ze zbycia paliw ciekłych','2026-10-02T05:57:07+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"3100","title":"Rządowy projekt ustawy o podatku od nadzwyczajnych zysków osiągniętych w okresie od marca do grudnia 2026 r. ze zbycia paliw ciekłych","description":"projekt dotyczy wprowadzenia czasowego podatku od nadzwyczajnych zysków osiąganych przez przedsiębiorstwa zajmujące się produkcją i handlem paliwami sprowadzanymi z zagranicy. Nowe przepisy pomogą sfinansować rządowe działania, które mają chronić obywateli przed skutkami wzrostu cen paliw wywołanego kryzysem na światowych rynkach energii, czyli tzw. CPN.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-10-02T05:57:07Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"eli":"DU/2026/1287","display_address":"Dz.U. 2026 poz. 1287","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001287"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-15","print_number":"3100","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','bbeea684b8e4569cfb9c232b3d502bf1f88c5848b793e1bb671279582a313602',NULL,0,'text prefilter: no keyword hits','2026-09-15T15:46:11+00:00','2026-10-03T11:51:30+00:00','{"term":10,"number":"RPW/31041/2026","title":"Rządowy projekt ustawy o podatku od nadzwyczajnych zysków osiągniętych w okresie od marca do grudnia 2026 r. ze zbycia paliw ciekłych","description":"wprowadzenia czasowego podatku od nadzwyczajnych zysków osiąganych przez przedsiębiorstwa zajmujące się produkcją i handlem paliwami sprowadzanymi z zagranicy. Nowe przepisy pomogą sfinansować rządowe działania, które mają chronić obywateli przed skutkami wzrostu cen paliw wywołanego kryzysem na światowych rynkach energii, czyli tzw. CPN.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-15","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/31041/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3101','Rządowy projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw','2026-10-14T12:10:31+00:00','2026-10-08',1,'skipped_text_prefilter','[]','{"term":10,"number":"3101","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw","description":"projekt dotyczy ograniczenia liczby zdarzeń drogowych na przejazdach kolejowych poprzez: 1) wprowadzenie instrumentu natychmiastowego zatrzymania na 3 miesiące prawa jazdy za najbardziej niebezpieczne naruszenia popełnione na przejazdach kolejowych, 2) zaostrzenie sądowego środka karnego w postaci zakazu prowadzenia pojazdów w przypadku przestępstw popełnionych na przejazdach kolejowych.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-10-14T12:10:31Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-15T15:46:15+00:00','2026-10-15T17:48:35+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
