INSERT INTO "bills" VALUES(10,'3102','Rządowy projekt ustawy o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw','2026-10-19T06:26:44+00:00','2026-09-18',1,'analyzed','["text:migracja"]','{"term":10,"number":"3102","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw","description":"projekt dotyczy zwiększenia bezpieczeństwa i efektywności funkcjonowania rynku energii elektrycznej. Nowe przepisy porządkują zasady działania centralnego systemu informacji rynku energii, ułatwią rozliczenia w przypadku problemów z systemami informatycznymi oraz wzmocnią obowiązek przekazywania danych potrzebnych do bezpiecznego zarządzania siecią. Projekt upraszcza także rozliczenia związane z ograniczeniami w poborze energii i porządkuje zasady dotyczące liczników zdalnego odczytu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-10-19T06:26:44Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-154-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-154-26","prints_considered_jointly":[],"eli":"DU/2026/1348","display_address":"Dz.U. 2026 poz. 1348","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001348","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-15","print_number":"3102","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"ESK","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-16","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"202