itteeReport","date":"2026-09-16","print_number":"3110","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3110/3110.pdf","proposal":"uchwalić ponownie","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"Rozpatrywanie na forum Sejmu wniosku Prezydenta","stage_type":"PresidentMotionConsideration","date":"2026-09-17","sitting_num":65,"decision":"nie uchwalona ponownie","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-17","sub_committee":false,"voting":{"yes":232,"no":199,"abstain":0,"not_participating":29,"sitting":65,"voting_number":10,"date":"2026-09-17T15:22:31Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/65/10/pdf","clubs":[]},"children":[]}]},{"stage_name":"nie uchwalona ponownie po wecie Prezydenta","stage_type":"End","sub_committee":false,"children":[]}]','dfaa9194b7bb0cca4bcc0b444615ee63c2ac2e50af313d2186adfc1ff90df0f0','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Закон вводит «umowa o wspólnym pożyciu» (договор о совместной жизни): это нотариальный договор для пар независимо от пола, дающий статус ближайшего лица. Заключить его могут и иностранцы, но права на пребывание в Польше он не даёт.","key_changes":["Договор заключается у нотариуса в Польше, при одновременном присутствии обеих сторон","В заверениях указываются гражданство, PESEL (если присвоен) и данные документа личности","Нельзя заключить договор, если человек уже состоит в браке или в зарубежном союзе, не признаваемом браком","По умолчанию действует раздельность имущества; можно выбрать общность или выравнивание достижений","Регистрация в urząd stanu cywilnego, opłata skarbowa 100 zł; возможны доверенности, доступ к медданным, завещания"],"affected_groups":["иностранцы, живущие в Польше в неформальных парах","пары одного пола, в том числе с участием иностранцев","иностранцы без PESEL"],"practical_impact":"Иностранец может заключить договор с партнёром у польского нотариуса по документу личности, даже без PESEL, и получить права по имуществу, медицинской информации и представительству. Если он состоит в зарубежном союзе, не признаваемом в Польше браком, заключить договор нельзя; легализации пребывания договор не даёт.","effective_date":"Закон вступает в силу в срок, определённый в отдельном законе «Przepisy wprowadzające ustawę o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu» (вводные положения).","confidence":0.8,"rationale":"Это общий гражданско-правовой закон, доступный иностранцам, с отдельными нормами о гражданстве, PESEL и зарубежных союзах, но без влияния на право пребывания, поэтому воздействие косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":24882,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2110/attachment/2110_u3.pdf","source_kind":"text_after3","revision":2,"text_sha256":"86421a120c0194a37f061d6829b176f10ad4c45d25b2c2ec92f6aa50793d1969","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-16T19:35:38+00:00','2026-10-28T19:18:40+00:00','{"term":10,"number":"RPW/43918/2025","title":"Rządowy projekt ustawy o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu","description":"uregulowania kwestii związków nieformalnych; osoby żyjące w takich związkach będą mogły zawrzeć przed notariuszem umowę cywilnoprawną, która następnie zostanie zarejestrowana w urzędzie stanu cywilnego i dzięki której zyskają możliwość kształtowania wzajemnych praw i obowiązków w sferze majątkowej, rodzinnej i osobistej m. in. będą mogły razem rozliczać PIT, zyskają dostęp do informacji i dokumentacji medycznej partnera oraz uprawnienia dotyczące ubezpieczenia zdrowotnego, renty rodzinnej, prawa do pochówku czy zasiłku opiekuńczego. Będą także uprawnione do dziedziczenia testamentowego. Nowe przepisy zwiększą też ochronę osób tworzących niesformalizowane związki, niezależnie od płci.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-12-30","print_number":"2110","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["2110-001", "2110-002", "2110-003", "2110-004", "2110-005", "2110-006", "2110-007", "2110-008", "2110-009", "2110-010", "2110-011", "2110-012", "2110-013", "2110-014", "2110-015"]',NULL,'2026-09-17','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-12-30","print_number":"2110","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-12-31","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-12-31","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-02-13","sitting_num":51,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-02-13","committee_code":"NON","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do rozpatrzenia projektów ustaw dotyczących statusu osoby najbliższej w związku i umowy o wspólnym pożyciu","children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-02-13","sub_committee":false,"voting":{"yes":199,"no":233,"abstain":3,"not_participating":25,"sitting":51,"voting_number":72,"date":"2026-02-13T09:38:51Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/51/72/pdf","clubs":[]},"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-05-26","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"