INSERT INTO "bills" VALUES(10,'RCL/12396501','Projekt ustawy o zmianie ustawy o przeciwdziałaniu praniu pieniędzy oraz finansowaniu terroryzmu','2026-10-16T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:migracja", "text:azyl", "text:obywatelstwo", "text:wizy", "text:legalizacja", "text:straz_graniczna", "text:nieruchomosci_cudzoziemcy", "text:prawnicy_zagraniczni"]','{"term":10,"number":"RCL/12396501","title":"Projekt ustawy o zmianie ustawy o przeciwdziałaniu praniu pieniędzy oraz finansowaniu terroryzmu","description":"PRANIE PIENIĘDZY; finanse publiczne. Numer i tytuł aktu prawnego Unii Europejskiej: Wdraża: dyrektywę Parlamentu Europejskiego i Rady (UE) 2015/849 z dnia 20 maja 2015 r. w sprawie zapobiegania wykorzystywaniu systemu finansowego do prania pieniędzy lub finansowania terroryzmu, zmieniającą rozporządzenie Parlamentu Europejskiego i Rady (UE) nr 648/2012 i uchylającą dyrektywę Parlamentu Europejskiego i Rady 2005/60/WE oraz dyrektywę Komisji 2006/70/WE (Dz. Urz. UE L 141 z 05.06.2015, str. 73, Dz. Urz. UE L 156 z 19.06.2018, str. 43, Dz. Urz. UE L 334 z 27.12.2019, str. 155 oraz Dz. Urz. UE L 150 z 31.05.2023, str. 1), dyrektywę Parlamentu Europejskiego i Rady (UE) 2024/1640 z dnia 31 maja 2024 r. w sprawie mechanizmów, które państwa członkowskie powinny wprowadzić w celu zapobiegania wykorzystywaniu systemu finansowego do prania pieniędzy lub finansowania terroryzmu, zmieniającą dyrektywę (UE) 2019/1937 oraz zmieniającą i uchylającą dyrektywę (UE) 2015/849 (Dz. Urz. UE L 2024/1640 z 19.6.2024).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-04-07","document_date":"2026-09-16","change_date":"2026-10-16T00:00:00Z","eu_related":true,"rcl_num":"RM-0610-147-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12396501","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2025-10-16","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','8dd07b48596ea388893d4116560de01f908b2f5d145f3de0cdaba2eacb6375d1','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается противодействия отмыванию денег и финансированию терроризма, реестра бенефициаров и системы обмена информацией между госорганами; упоминания о воеводах и консулах, работающих с иностранцами, носят второстепенный характер и не меняют прав или обязанностей иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Законопроект касается противодействия отмыванию денег и финансированию терроризма, реестра бенефициаров и системы обмена информацией между госорганами; упоминания о воеводах и консулах, работающих с иностранцами, носят второстепенный характер и не меняют прав или обязанностей иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":23539,"truncated":true,"text_source":"excerpts","created_at":"2026-09-16T19:37:22Z","input_tokens":13950,"output_tokens":134,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-16T19:36:18+00:00','2026-1