INSERT INTO "bills" VALUES(10,'3125','Poselski projekt ustawy o zmianie ustawy o zasadach zarządzania mieniem państwowym','2026-09-17T17:25:57+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3125","title":"Poselski projekt ustawy o zmianie ustawy o zasadach zarządzania mieniem państwowym","description":"projekt dotyczy wprowadzenia corocznej informacji Rady Ministrów dla Sejmu o działalności i wynikach przedsiębiorstw państwowych i spółek z udziałem Skarbu Państwa oraz o celowości dalszego zaangażowania państwa; nałożenia obowiązku udostępniania w portalu danych zbiorczej informacji w formacie otwartym i przetwarzalnym maszynowo - informacja ta obejmie wielopoziomową strukturę właścicielską oraz fundusze inwestycyjne zamknięte, ze wskazaniem składników lokat funduszu przy udziale certyfikatów wynoszącym co najmniej 25%","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-29","document_date":"2026-07-29","change_date":"2026-09-17T17:25:57Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-29","print_number":"3125","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"ESK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-29","print_number":"3125","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"ESK","sub_committee":false,"committee_name":"Komisja do Spraw Energii, Klimatu i Aktywów Państwowych","children":[]}]}]','a604b98f808fac7ee07005c7512b113efeb3e9205b8695c1796b01bd3b54bcb7','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается управления государственным имуществом и отчётности перед Сеймом о деятельности госпредприятий и компаний с участием Казны государства, не затрагивая прав, обязанностей или процедур иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается управления государственным имуществом и отчётности перед Сеймом о деятельности госпредприятий и компаний с участием Казны государства, не затрагивая прав, обязанностей или процедур иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-17T19:46:15Z","input_tokens":13985,"output_tokens":107,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-17T19:45:18+00:00','2026-10-28T19:18:48+00:00','{"term":10,"number":"RPW/26215/2026","title":"Poselski projekt ustawy o zmianie ustawy o zasadach zarządzania mieniem państwowym","description":"wprowadzenia corocznej informacji Rady Ministrów dla Sejmu o działalności i wynikach przedsiębiorstw państwowych i spółek z udziałem Skarbu Państwa oraz o celowości dalszego zaangażowania państwa; nałożenia obowiązku udostępniania w portalu danych zbiorczej informacji w formacie otwartym i przetwarzalnym maszynowo - informacja ta obejmie wielopoziomową strukturę właścicielską oraz fundusze inwestycyjne zamknięte, ze wskazaniem składników lokat funduszu przy udziale certyfikatów wynoszącym co najmniej 25%","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-29","print_number":"3125","eu_related":false,"public_consultation":true,"consultation_start":"2026-07-30","consul