INSERT INTO "bills" VALUES(10,'3121','Rządowy projekt ustawy o zmianie ustawy o finansowym wsparciu niektórych przedsięwzięć mieszkaniowych oraz niektórych innych ustaw','2026-10-23T08:23:04+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3121","title":"Rządowy projekt ustawy o zmianie ustawy o finansowym wsparciu niektórych przedsięwzięć mieszkaniowych oraz niektórych innych ustaw","description":"projekt dotyczy zmian w dwóch programach wsparcia mieszkalnictwa: programie budownictwa socjalnego i komunalnego (BSK) oraz programie TERMO, wspierającym termomodernizację, remonty i instalację odnawialnych źródeł energii w budynkach wielorodzinnych. Zmiany pozwolą wykorzystać wolne środki z programu Stop Smog na zwiększenie wsparcia dla wspólnot i spółdzielni mieszkaniowych, gmin oraz innych właścicieli i zarządców budynków, w ramach programu TERMO.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-16","document_date":"2026-09-16","change_date":"2026-10-23T08:23:04Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-16","print_number":"3121","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]}]','98fd3f5c480ff671d4481027209b9633c0b97853db0f668fd97b05b73855bf1c',NULL,0,'text prefilter: no keyword hits','2026-09-17T19:46:38+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/31193/2026","title":"Rządowy projekt ustawy o zmianie ustawy o finansowym wsparciu niektórych przedsięwzięć mieszkaniowych oraz niektórych innych ustaw","description":"zmian w dwóch programach wsparcia mieszkalnictwa: programie budownictwa socjalnego i komunalnego (BSK) oraz programie TERMO, wspierającym termomodernizację, remonty i instalację odnawialnych źródeł energii w budynkach wielorodzinnych. Zmiany pozwolą wykorzystać wolne środki z programu Stop Smog na zwiększenie wsparcia dla wspólnot i spółdzielni mieszkaniowych, gmin oraz innych właścicieli i zarządców budynków, w ramach programu TERMO.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-16","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/31193/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-16","print_number":"3121","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-17","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2996','Rządowy projekt ustawy o zmianie ustawy o ewidencji ludności','2026-10-09T12:17:38+00:00','2026-10-08',1,'skipped_text_prefilter','[]','{"term":10,"number":"2996","title":"Rządowy projekt ustawy o zmianie ustawy o ewidencji ludności","description":"projekt dotyczy rozszerzenia o zakłady ubezpieczeń katalogu podmiotów uprawnionych do pozyskiwania z rejestru PESEL danych w zakresie serii, numeru oraz daty ważności dowodu osobistego po wymianie dokumentu na nowy. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-10-09T12:17:38Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-18T09:54:10+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/26574/2026","title":"Rządowy projekt ustawy o zmianie ustawy o ewidencji ludności","description":"rozszerzenia o zakłady ubezpieczeń katalogu podmiotów uprawnionych do pozyskiwania z rejestru PESEL danych w zakresie serii, numeru oraz daty ważności dowodu osobistego po wymianie dokumentu na nowy. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-30","print_number":"2996","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3001','Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska oraz niektórych innych ustaw','2026-10-09T12:13:09+00:00','2026-10-08',1,'skipped_text_prefilter','["text:granica_panstwowa"]','{"term":10,"number":"3001","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska oraz niektórych innych ustaw","description":"projekt dotyczy uproszczenia zasad dotyczących pozwoleń zintegrowanych, czyli pozwoleń wymaganych dla instalacji przemysłowych, które ze względu na rodzaj i skalę mogą powodować znaczne zanieczyszczenie środowiska. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-06","document_date":"2026-08-05","change_date":"2026-10-09T12:13:09Z","closure_date":"2026-10-08","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (granica_panstwowa×2)','2026-09-18T09:54:11+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/26934/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska oraz niektórych innych ustaw","description":"uproszczenia zasad dotyczących pozwoleń zintegrowanych, czyli pozwoleń wymaganych dla instalacji przemysłowych, które ze względu na rodzaj i skalę mogą powodować znaczne zanieczyszczenie środowiska. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-05","print_number":"3001","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RPW/31391/2026','Rządowy projekt ustawy o zmianie ustawy o systemie monitorowania i kontrolowania jakości paliw','2026-09-17T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RPW/31391/2026","title":"Rządowy projekt ustawy o zmianie ustawy o systemie monitorowania i kontrolowania jakości paliw","description":"wprowadzenia jednolitych wymagań jakościowych dla biopaliw stałych oraz objęcie ich systemem kontroli jakości paliw. Dzięki temu do sprzedaży nie będzie mogła trafiać biomasa niespełniająca określonych wymagań, co ma ograniczyć spalanie paliw złej jakości i przyczynić się do poprawy jakości powietrza. Projekt umożliwia objęcie normami jakości zarówno biopaliwa pochodzenia drzewnego, jak i rolniczego. Da to podstawy do rozwoju rynku biopaliw pochodzenia rolniczego, w tym agropeletu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-17","document_date":"2026-09-17","change_date":"2026-09-17T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-18T09:54:12+00:00','2026-09-18T09:54:12+00:00','{"term":10,"number":"RPW/31391/2026","title":"Rządowy projekt ustawy o zmianie ustawy o systemie monitorowania i kontrolowania jakości paliw","description":"wprowadzenia jednolitych wymagań jakościowych dla biopaliw stałych oraz objęcie ich systemem kontroli jakości paliw. Dzięki temu do sprzedaży nie będzie mogła trafiać biomasa niespełniająca określonych wymagań, co ma ograniczyć spalanie paliw złej jakości i przyczynić się do poprawy jakości powietrza. Projekt umożliwia objęcie normami jakości zarówno biopaliwa pochodzenia drzewnego, jak i rolniczego. Da to podstawy do rozwoju rynku biopaliw pochodzenia rolniczego, w tym agropeletu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-17","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','3134',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
