INSERT INTO "bills" VALUES(10,'RCL/12407350','projekt ustawy o zmianie ustawy o usługach zaufania oraz identyfikacji elektronicznej oraz niektórych innych ustaw','2026-10-07T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"RCL/12407350","title":"projekt ustawy o zmianie ustawy o usługach zaufania oraz identyfikacji elektronicznej oraz niektórych innych ustaw","description":"INFORMATYZACJA; informatyzacja. Numer i tytuł aktu prawnego Unii Europejskiej: Rozporządzenie Parlamentu Europejskiego i Rady (UE) nr 910/2014 z dnia 23 lipca 2014 r. w sprawie identyfikacji elektronicznej i usług zaufania w odniesieniu do transakcji elektronicznych na rynku wewnętrznym oraz uchylającego dyrektywę 1999/93/WE (Dz. Urz. UE L 257 z 28.08.2014, str. 73, Dz. Urz. UE L 333 z 27.12.2022, str. 80 oraz Dz. Urz. UE L 2024/1183 z 30.04.2024)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-19","document_date":"2026-08-12","change_date":"2026-10-07T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12407350","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-05-29","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','d6ae318059e512dd7feda19de05371c11e50dd0a31d324a875ab19045662af68','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект внедряет европейский кошелёк цифровой идентичности (EUDI Wallet) в рамках mObywatel и меняет правила электронной идентификации и доверенных услуг. Кошелёк должны получить все физические лица в Польше, включая иностранцев-резидентов, а не только граждан. Предусмотрены пункты подтверждения личности, в том числе у воеводы.","key_changes":["Министр цифровизации обеспечивает европейский кошелёк цифровой идентичности для физических и юридических лиц","Подтверждение личности возможно у wojewoda, в банке или в органе гмины при личном присутствии","Набор данных кошелька: имя, фамилия, дата и место рождения, PESEL, гражданство, пол, фото","Кошелёк приравнивается к документу, удостоверяющему личность, при очной проверке (с 24.12.2027)","Бесплатная квалифицированная электронная подпись для непрофессиональных целей","Централизованная система сопоставления личности с реестром PESEL для иностранных средств идентификации"],"affected_groups":["иностранцы, постоянно проживающие в Польше","лица с номером PESEL","лица без PESEL, пользующиеся электронной идентификацией из других стран ЕС","юридические лица и предприниматели"],"practical_impact":"Иностранцы-резиденты, не имеющие польского удостоверения личности, смогут получить цифровой кошелёк, подтвердив личность лично в пункте у воеводы, банка или гмины; кошелёк позволит подтверждать личность и подписывать документы онлайн.","effective_date":"Закон вступает в силу 24 декабря 2026 г., с исключениями: часть норм — на следующий день после публикации, отдельные — 31.12.2027, 30.06.2028, 24.12.2027, 31.12.2029 и через 18/24 месяца после публикации","confidence":0.75,"rationale":"Проект не касается легализации пребывания, но прямо предусматривает доступ к цифровой идентичности для резидентов-неграждан и подтверждение личности через воеводу, что даёт косвенное воздействие.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":296222,"truncated":false,"text_source":"documents","created_at":"2026-09-18T09:55:32Z","input_tokens":141318,"output_tokens":773,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12407350/13188189/13188190/dokument791977.zip","source_kind":"rcl","revision":1,"text_sha256":"ed6e19bc686b1886fa0aa33cf222c8cc825c857aea502a54756ef9cc4915b84c","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":"2026-09-18T09:55:32Z"}',0,NULL,'2026-09-18T09:54:46+00:00','2026-10-28T19:17:32+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12407350,"title":"projekt ustawy o zmianie ustawy o usługach zaufania oraz identyfikacji elektronicznej oraz niektórych innych ustaw","applicant":"Minister Cyfryzacji","wykaz_number":"UC122","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-02-19","modified":"2026-10-07","departments":["informatyzacja"],"keywords":["INFORMATYZACJA"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: Rozporządzenie Parlamentu Europejskiego i Rady (UE) nr 910/2014 z dnia 23 lipca 2014 r. w sprawie identyfikacji elektronicznej i usług zaufania w odniesieniu do transakcji elektronicznych na rynku wewnętrznym oraz uchylającego dyrektywę 1999/93/WE (Dz. Urz. UE L 257 z 28.08.2014, str. 73, Dz. Urz. UE L 333 z 27.12.2022, str. 80 oraz Dz. Urz. UE L 2024/1183 z 30.04.2024)","term_label":"X","stages":[{"id":13188151,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13188152,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-04-20","folders":[{"id":13188153,"name":"Projekt","modified":"2026-02-19","documents":[{"id":763630,"name":"uzasadnienie_eIDAS 2.0_18.02.2026.docx