66,"voting_number":106,"date":"2026-10-08T18:56:58Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/66/106/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"title_final":"o zabezpieczeniu społecznym osób wykonujących zawód artystyczny"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-03","print_number":"2644","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-06-09","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-09","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-06-19","sitting_num":60,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-19","committee_code":"KSP","sub_committee":false,"committee_name":"Komisja Kultury, Dziedzictwa Narodowego i Środków Przekazu","children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-06-19","sub_committee":false,"voting":{"yes":199,"no":233,"abstain":1,"not_participating":27,"sitting":60,"voting_number":61,"date":"2026-06-19T08:12:01Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/60/61/pdf","clubs":[]},"children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-06-19","sub_committee":false,"voting":{"yes":38,"no":220,"abstain":176,"not_participating":26,"sitting":60,"voting_number":62,"date":"2026-06-19T08:13:10Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/60/62/pdf","clubs":[]},"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-07-14","sub_committee":false,"children":[{"stage_name":"Wysłuchanie publiczne","stage_type":"PublicHearing","date":"2026-07-14","sub_committee":false,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-15","print_number":"3082","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2644/attachment/2644_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-08","sub_committee":false,"voting":{"yes":232,"no":197,"abstain":4,"not_participating":27,"sitting":66,"voting_number":106,"date":"2026-10-08T18:56:58Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/66/106/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','8a4c07d185dcdc95dd6b5abad48bd9f194fc67961c1a12eaf80db22d420a588a','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Законопроект вводит «статус артиста» (status artysty) и доплату государства к взносам ZUS и на медстрахование для людей творческих профессий с низкими доходами. Иностранцы с определёнными видами легального пребывания в Польше прямо включены в круг заявителей.","key_changes":["Статус артиста на 5 лет (после трёх раз — на 8) выдаёт dyrektor Instytucji, решение обжалуется министру","Право подать заявление имеют граждане ЕС/ЕЭЗ/Швейцарии и члены семей с правом пребывания","Иностранцы с pobyt stały, rezydent UE, рядом zezwoleń na pobyt czasowy (в т.ч. ст. 114, 127, 151, 139a), беженцы и лица с доп. защитой — тоже","Исключены лица с разрешением на пребывание и работу до 9 месяцев (или до 6 мес. для научных случаев)","Доплата назначается ZUS при среднем доходе за 3 года не выше 125% годового минимального заработка"],"affected_groups":["граждане ЕС/ЕЭЗ/Швейцарии и члены их семей в Польше","иностранцы с pobyt stały и rezydent długoterminowy UE","обладатели отдельных zezwoleń na pobyt czasowy (работа, ICT, научные исследования)","беженцы и лица с дополнительной защитой","граждане Великобритании по Brexit-соглашению"],"practical_impact":"Иностранцы-творческие работники с подходящим основанием пребывания смогут получить статус артиста и войти в систему ZUS/NFZ, а при низких доходах — государственную доплату к взносам. Заявление на статус подаётся в Instytucję, на доплату — в ZUS электронно через profil informacyjny.","effective_date":"Первый день месяца, следующего за истечением 9 месяцев со дня опубликования.","confidence":0.85,"rationale":"Закон касается социального страхования и взносов, прямо перечисляя категории иностранцев, имеющих право на статус артиста, — это социальная сфера, а не легализация пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":86933,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:07:51Z","input_tokens":44861,"output_tokens":851,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf","source_kind":"committee_report","revision":1,"text_sha256":"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72","source_checked_at":"2026-09-18T19:07:51Z"}',0,NULL,'2026-09-18T19:03:49+00:00','2026-10-29T19:06:28+00:00','{"term":10,"number":"RPW/19231/2026","title":"Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny","description":"włączenie artystów zawodowych do systemu zabezpieczenia społecznego; stworzenia możliwości aplikowania o przyznanie im uprawnienia do otrzymania dopłaty celem uzupełnienia finansowania ich składek na ubezpieczenia społeczne i zdrowotne do poziomu składek wynikających z minimalnego wynagrodzenia za pracę. Dopłata ma obejmować również składki na Fundusz Pracy oraz Fundusz Emerytur Pomostowych. Artyści osiągający tym samym najniższe dochody będą uprawnieni do wsparcia finansowego w opłaceniu składek w okresach, w których ich własne dochody nie będą pozwalać na pokrycie składek.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-06-03","print_number":"2644","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["2644-001", "2644-002", "2644-003"]',NULL,'2026-10-08','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-03","print_number":"2644","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-06-09","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-09","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-06-19","sitting_num":60,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-19","committee_code":"KSP","sub_committee":false,"committee_name":"Komisja Kultury, Dziedzictwa Narodowego i Środków Przekazu","children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-06-19","sub_committee":false,"voting":{"yes":199,"no":233,"abstain":1,"not_participating":27,"sitting":60,"voting_number":61,"date":"2026-06-19T08:12:01Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/60/61/pdf","clubs":[]},"children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-06-19","sub_committee":false,"voting":{"yes":38,"no":220,"abstain":176,"not_participating":26,"sitting":60,"voting_number":62,"date":"2026-06-19T08:13:10Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/60/62/pdf","clubs":[]},"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-07-14","sub_committee":false,"children":[{"stage_name":"Wysłuchanie publiczne","stage_type":"PublicHearing","date":"2026-07-14","sub_committee":false,"children":[]},{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-15","print_number":"3082","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2644/attachment/2644_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-08","sub_committee":false,"voting":{"yes":232,"no":197,"abstain":4,"not_participating":27,"sitting":66,"voting_number":106,"date":"2026-10-08T18:56:58Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/66/106/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"closure_date":"2026-10-08","passed":true,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf","kind":"committee_report","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72","analysis_revision":1,"seen_supplements":["2644-001","2644-002","2644-003"]}',0,NULL,'{"url":"https://www.