INSERT INTO "bills" VALUES(10,'2802','Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw','2026-09-18T12:53:55+00:00',NULL,0,'analyzed','["text:migracja", "text:obywatele_ukrainy", "text:straz_graniczna", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"2802","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw","description":"projekt dotyczy potrzeby dostosowania obowiązujących regulacji prawa karnego procesowego do standardów konstytucyjnych i międzynarodowych mi.n. przez zmiany w sposobie przesłuchiwania podejrzanego, który nie ukończył 18 lat (m.in. obowiązkowy udział obrońcy); zapewnienie prawa do pomocy tłumacza języka migowego oskarżonemu, który jest głuchy lub niemy również na potrzeby jego udziału w czynnościach postępowania (np. rozprawie lub posiedzeniach) oraz kontaktów z obrońcą","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-01","document_date":"2026-06-01","change_date":"2026-09-18T12:53:55Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-01","print_number":"2802","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-01","print_number":"2802","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}]','b4e7ff32208e5a6c4cfb0cc9ac4967af11e3f76abd0fe0a5a064b2a440172a37','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Уголовно-процессуальный кодекс и связанные законы: доступ к защитнику, права задержанных, порядок временного ареста, право на переводчика для тех, кто не владеет польским. Это общие процессуальные гарантии, а не нормы о пребывании или работе иностранцев.","key_changes":["Расширено право на бесплатного переводчика для обвиняемого, не владеющего польским языком","Право требовать перевода документов, важных для защиты, и жаловаться на качество перевода","Постоянное место жительства в другой стране ЕС приравнено к проживанию в Польше при оценке риска побега","Обязательное участие защитника при допросе подозреваемого младше 18 лет","Доступ задержанного и защитника к материалам, обосновывающим задержание и арест"],"affected_groups":["иностранцы, оказавшиеся подозреваемыми или задержанными в Польше","лица, не владеющие польским языком, в уголовном процессе","граждане других стран ЕС, проживающие за пределами Польши"],"practical_impact":"Иностранец, попавший в уголовный процесс в Польше, получит более широкий доступ к переводчику и защитнику, а проживание в другой стране ЕС больше не будет само по себе основанием считать его склонным к побегу. На легализацию пребывания или работу это не влияет.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня опубликования.","confidence":0.85,"rationale":"Это реформа уголовного процесса; положения о переводчике и о месте жительства в ЕС касаются иностранцев лишь косвенно и не меняют их статуса пребывания или занятости.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":449323,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:02Z","input_tokens":227761,"output_tokens":614,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2802/2802.pdf","source_kind":"print","revision":1,"text_sha256":"1495a1bc2a8b6f5353e9f6670c0d7bc3dcdaf5c4e511d900e692aabe1aeccccb","source_checked_at":"2026-09-18T19:08:02Z"}',0,NULL,'2026-09-18T19:03:51+00:00','2026-10-28T19:18:42+00:00','{"term":10,"number":"RPW/18910/2026","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks postępowania karnego oraz niektórych innych ustaw","description":"potrzeby dostosowania obowiązujących regulacji prawa karnego procesowego do standardów konstytucyjnych i międzynarodowych mi.n. przez zmiany w sposobie przesłuchiwania podejrzanego, który nie ukończył 18 lat (m.in. obowiązkowy udział obrońcy); zapewnienie prawa do pomocy tłumacza języka migowego oskarżonemu, który jest głuchy lub niemy również na potrzeby jego udziału w czynnościach postępowania (np. rozprawie lub posiedzeniach) oraz kontaktów z obrońcą","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-06-01","print_number":"2802","eu_related":false,"public_consultation":true,"consultation_start":"2026-06-03","consultation_end":"2026-07-03","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Maciej Tomczykiewicz","representative_club":"KO","clubs":[["KO",25]],"signatories":25,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["2802-001", "2802-002", "2802-003", "2802-004"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-01","print_number":"2802","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-07-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-15","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/2802/2802.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"1495a1bc2a8b6f5353e9f6670c0d7bc3dcdaf5c4e511d900e692aabe1aeccccb","analysis_revision":1,"seen_supplements":["2802-001","2802-002","2802-003","2802-004"]}',0,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
