ber":"3170","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3170/3170.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2997/attachment/2997_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":422,"no":19,"abstain":0,"not_participating":19,"sitting":67,"voting_number":178,"date":"2026-10-22T17:04:50Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/178/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','3173676e8357ff1440baf2831e30ee33042252d851c6e7a0aadc2518ac197c24','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект упорядочивает и расширяет письменные уведомления о правах для подозреваемых, обвиняемых, осуждённых, потерпевших и свидетелей в уголовных делах. Шаблоны таких уведомлений будут публиковаться на сайте Ministerstwo Sprawiedliwości с переводами на часто используемые иностранные языки.","key_changes":["Обязательная публикация всех шаблонов pouczeń на сайте Минюста с переводами на частые иностранные языки","Расширенные перечни прав в уведомлениях для подозреваемых, обвиняемых, потерпевших и свидетелей","Прямое информирование о праве на компенсацию за незаконное задержание, арест, осуждение и меры zabezpieczające","Стандартизированные письменные pouczenia и для осуждённых и участников частного обвинения","Расширенные pouczenia для лиц по европейскому ордеру на арест, в т.ч. для несовершеннолетних и их опекунов"],"affected_groups":["Иностранцы, участвующие в уголовном процессе в Польше как подозреваемые или обвиняемые","Иностранные потерпевшие и свидетели в уголовных делах","Иностранцы, задержанные по европейскому ордеру на арест (nakaz europejski)","Несовершеннолетние иностранцы в уголовном процессе и их законные представители"],"practical_impact":"Иностранный участник дела будет получать более подробные и понятные письменные уведомления о своих правах и обязанностях, а шаблоны этих уведомлений с переводами можно будет найти на сайте Ministerstwo Sprawiedliwości. Это облегчает понимание права на адвоката, компенсацию за незаконное задержание или осуждение и других процессуальных прав.","effective_date":"Закон вступает в силу 1 марта 2027 г.","confidence":0.93,"rationale":"Проект напрямую не меняет миграционный статус, но затрагивает права иностранцев как участников уголовного процесса и вводит переводы уведомлений, поэтому оценка 2 и категория „indirect”.","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":25504,"truncated":false,"text_source":"pdf","created_at":"2026-10-07T19:38:40Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3170/3170.pdf","source_kind":"committee_report","revision":2,"text_sha256":"text-v2:7145f31bf567b02bb514d52e14337e715f0e9b85996c69faa8c8a43c23a160f0","law_sha256":"law-v2:d8a70fc1f63ed5a49237b087c35ad410fdf7cb27a6151442bafa9fc2a1140428","source_checked_at":"2026-10-07T19:38:40Z"}',0,NULL,'2026-09-18T19:03:52+00:00','2026-10-29T19:06:33+00:00','{"term":10,"number":"RPW/26576/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania karnego","description":"wprowadzenia prostszych i bardziej przejrzystych pouczeń dla świadków, pokrzywdzonych i oskarżonych oraz rozszerzenia informacji o przysługujących im prawach","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-30","print_number":"2997","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'2026-10-22','{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-30","print_number":"2997","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"NKK","sub_committee":false,"committee_name":"Komisja Nadzwyczajna do spraw zmian w kodyfikacjach","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-06","print_number":"3170","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3170/3170.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2997/attachment/2997_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","d