INSERT INTO "bills" VALUES(10,'3004','Rządowy projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw','2026-10-28T13:10:43+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3004","title":"Rządowy projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw","description":"projekt dotyczy: zmniejszenia obciążeń administracyjnych związanych z funkcjonowaniem Krajowego Rejestru Sądowego dzięki automatyzacji i informatyzacji procesów. Stworzenie specjalnych kont i automatyczna aktualizacja danych z rejestru PESEL ograniczy liczbę dokumentów papierowych i czynności kancelaryjnych. Uproszczone zostaną także zasady postępowania dotyczące tzw. \"martwych podmiotów\" oraz składania sprawozdań finansowych. Zmiany usprawnią też pracę sądów rejestrowych. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-06","document_date":"2026-08-06","change_date":"2026-10-28T13:10:43Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-125-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-125-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3004","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-07","committee_code":"DER","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-22","print_number":"3252","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3252/3252.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3004","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-07","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-22","print_number":"3252","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3252/3252.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]}]','933b61e97ab6cfff921233aecc4a9b9a6e715b41f17c55d58547ed5333291531','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет работу KRS (Krajowy Rejestr Sądowy, судебный реестр компаний и организаций): вся переписка с судом идёт через электронную систему и счёт организации, упрощается ликвидация «мёртвых» фирм. Иностранцев касается лишь уточнённое заявление о статусе cudzoziemca у покупателя долей и акций.","key_changes":["В заявке о покупке долей/акций указывается, является ли приобретатель cudzoziemcem по ustawa z 1920 r.","Если приобретатель — иностранец, заявляется, владеет ли компания недвижимостью в Польше","Для адреса регистрации фирмы нужно правовое основание на помещение, документ прилагается к заявке","Заявления и письма в реестровый суд — только через ИТ-систему и счёт организации","Пометка в KRS о несдаче финансовой отчётности; через год — роспуск фирмы без ликвидации"],"affected_groups":["иностранцы — покупатели и учредители долей и акций польских компаний","иностранцы — владельцы и члены правления компаний, зарегистрированных в KRS"],"practical_impact":"При покупке долей или акций польской компании иностранцем в заявке в KRS нужно указать его статус и наличие у компании недвижимости в Польше. Для всех фирм, включая принадлежащие иностранцам, обязательны электронная переписка с судом и документ о праве на помещение по адресу регистрации.","effective_date":"Закон вступает в силу 1 октября 2027 г., за исключением положений о пометке о несдаче финансовой отчётности и связанных норм, которые вступают в силу 1 октября 2028 г.","confidence":0.8,"rationale":"Проект касается корпоративного реестра в целом, а иностранцы затронуты лишь уточнением декларации по закону о приобретении недвижимости иностранцами, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":188666,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","source_kind":"print","revision":2,"text_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","source_checked_at":"2026-09-28T15:56:32Z"}',0,NULL,'2026-09-18T19:03:52+00:00','2026-10-29T19:06:33+00:00','{"term":10,"number":"RPW/27047/2026","title":"Rządowy projekt ustawy o zmianie ustawy o Krajowym Rejestrze Sądowym oraz niektórych innych ustaw","description":"zmniejszenia obciążeń administracyjnych związanych z funkcjonowaniem Krajowego Rejestru Sądowego dzięki automatyzacji i informatyzacji procesów. Stworzenie specjalnych kont i automatyczna aktualizacja danych z rejestru PESEL ograniczy liczbę dokumentów papierowych i czynności kancelaryjnych. Uproszczone zostaną także zasady postępowania dotyczące tzw. \"martwych podmiotów\" oraz składania sprawozdań finansowych. Zmiany usprawnią też pracę sądów rejestrowych. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-06","print_number":"3004","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RCL/12402301',NULL,NULL,NULL,NULL,NULL,NULL,'UDER49',NULL,'["3004-001"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-06","print_number":"3004","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-08-11","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-08-11","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-18","sitting_num":65,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-18","committee_code":"SPC","sub_committee":false,"committee_name":"Komisja Sprawiedliwości i Praw Człowieka","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-07","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-22","print_number":"3252","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3252/3252.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3004/3004.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"6de93675eb8a39b3ebdbc22f6ce78a830901c2feeeaca7cc1938b70d36843812","analysis_revision":2,"seen_supplements":["3004-001"]}',2,NULL,NULL,NULL,'metadata','below_bar',NULL,NULL,NULL,NULL,NULL,'[]');
