INSERT INTO "bills" VALUES(10,'RPW/31543/2026','Poselski projekt ustawy o zmianie ustawy o systemie ubezpieczeń społecznych','2026-09-18T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RPW/31543/2026","title":"Poselski projekt ustawy o zmianie ustawy o systemie ubezpieczeń społecznych","description":"zwolnienia osób mających ustalone prawo do emerytury i podlegających obowiązkowo ubezpieczeniom emerytalnemu i rentowym z opłacania należnych składek na ubezpieczenia rentowe w części finansowanej przez ubezpieczonych w wysokości 1,5% podstawy wymiaru","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-18","document_date":"2026-09-18","change_date":"2026-09-18T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,'{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Projekt dotyczy zwolnienia pracujących emerytów z części składki rentowej w systemie ubezpieczeń społecznych i nie zawiera żadnych przepisów odnoszących się do cudzoziemców, ich pobytu, pracy czy praw.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Projekt dotyczy zwolnienia pracujących emerytów z części składki rentowej w systemie ubezpieczeń społecznych i nie zawiera żadnych przepisów odnoszących się do cudzoziemców, ich pobytu, pracy czy praw.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-18T19:07:58Z","input_tokens":13865,"output_tokens":122,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-18T19:03:54+00:00','2026-09-19T13:56:40+00:00','{"term":10,"number":"RPW/31543/2026","title":"Poselski projekt ustawy o zmianie ustawy o systemie ubezpieczeń społecznych","description":"zwolnienia osób mających ustalone prawo do emerytury i podlegających obowiązkowo ubezpieczeniom emerytalnemu i rentowym z opłacania należnych składek na ubezpieczenia rentowe w części finansowanej przez ubezpieczonych w wysokości 1,5% podstawy wymiaru","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-18","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-09-21","consultation_end":"2026-10-21","consultation_results":false,"withdrawn_date":null}','3177',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RPW/31544/2026','Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych','2026-09-18T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:obcokrajowcy", "text:migracja", "text:obywatelstwo", "text:obywatele_ukrainy", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/31544/2026","title":"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych","description":"wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegający na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-18","document_date":"2026-09-18","change_date":"2026-09-18T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,'{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект ужесточает условия доплаты пенсии до минимальной из ZUS: помимо возраста и стажа потребуется накопить на пенсионном счёте взносы не ниже 25-кратного минимального вознаграждения (в 2026 г. — около 120 150 zł). Формально касается всех, но по обоснованию нацелен на иностранцев с коротким стажем работы в Польше.","key_changes":["Новое условие в art. 87 ust. 1 ustawy o emeryturach i rentach z FUS для доплаты до минимальной пенсии","Требуется валоризованная сумма взносов на счёте не ниже 25-кратного минимального вознаграждения (~120 150 zł в 2026 г.)","Условия возраста (65/60 лет) и стажа (25/20 лет) сохраняются","Новые правила применяются и к делам, начатым, но не завершённым до вступления в силу","Цель обоснования — ограничить доплаты лицам с минимальным стажем работы в Польше"],"affected_groups":["Иностранцы, работавшие в Польше и получающие пенсию из ZUS","Граждане Украины и других стран с договорами о социальном обеспечении с Польшей","Лица с коротким периодом уплаты взносов в Польше","Граждане Польши с низкими накоплениями в ZUS"],"practical_impact":"Если сумма взносов на счёте в ZUS ниже указанного порога, доплата до минимальной пенсии не будет назначена, даже при достаточном общем стаже с учётом периодов работы за границей. Это касается и заявлений, поданных до вступления закона в силу, но ещё не рассмотренных.","effective_date":"Через 14 дней со дня опубликования","confidence":0.9,"rationale":"Проект напрямую влияет на социальные выплаты (пенсии) иностранцам, работавшим в Польше, но не затрагивает легализацию пребывания или работу.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":38308,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:16Z","input_tokens":20036,"output_tokens":700,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31544-2026/$file/10-RPW-31544-2026.pdf","source_kind":"print","revision":1,"text_sha256":"7aae2f3eaa2548b831721657874f012c71cfa9ad6d26f74c06d1f4b75e9c11e2","source_checked_at":"2026-09-18T19:08:16Z"}',0,NULL,'2026-09-18T19:03:54+00:00','2026-09-19T13:56:40+00:00','{"term":10,"number":"RPW/31544/2026","title":"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych","description":"wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-18","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-09-21","consultation_end":"2026-10-21","consultation_results":false,"withdrawn_date":null}','3205',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'full','telegram_thread',NULL,NULL,NULL,NULL,NULL,NULL);
