INSERT INTO "bills" VALUES(10,'3123','Poselski projekt ustawy o zmianie ustawy o ochronie zwierząt','2026-10-06T09:06:52+00:00',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3123","title":"Poselski projekt ustawy o zmianie ustawy o ochronie zwierząt","description":"projekt dotyczy przyznania prokuratorowi kompetencji do wydania postanowienia o odebraniu psa właścicielowi albo opiekunowi w sytuacji, gdy atak psa spowodował uszkodzenie ciała, uszczerbek na zdrowiu, rozstrój zdrowia albo śmierć człowieka lub zwierzęcia, a jednocześnie zachodzi uzasadnione ryzyko ponownego ataku","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-27","document_date":"2026-08-27","change_date":"2026-10-06T09:06:52Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-21T10:51:35+00:00','2026-10-07T19:23:36+00:00','{"term":10,"number":"RPW/28884/2026","title":"Poselski projekt ustawy o zmianie ustawy o ochronie zwierząt","description":"przyznania prokuratorowi kompetencji do wydania postanowienia o odebraniu psa właścicielowi albo opiekunowi w sytuacji, gdy atak psa spowodował uszkodzenie ciała, uszczerbek na zdrowiu, rozstrój zdrowia albo śmierć człowieka lub zwierzęcia, a jednocześnie zachodzi uzasadnione ryzyko ponownego ataku","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-27","print_number":"3123","eu_related":false,"public_consultation":true,"consultation_start":"2026-08-28","consultation_end":"2026-09-27","consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12414851','Projekt ustawy o zmianie ustawy – Prawo o notariacie oraz ustawy – Kodeks postępowania cywilnego','2026-10-27T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:nieruchomosci_cudzoziemcy"]','{"term":10,"number":"RCL/12414851","title":"Projekt ustawy o zmianie ustawy – Prawo o notariacie oraz ustawy – Kodeks postępowania cywilnego","description":"CYWILNE PRAWO; NOTARIAT; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-21","document_date":"2026-09-21","change_date":"2026-10-27T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12414851","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2026-09-21","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','10fd71ba976e12871b64541066f6dbbb33bc3b75f915bf7073f8c77a7b08e270','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет Prawo o notariacie (закон о нотариате) и Kodeks postępowania cywilnego. Для иностранцев значим один пункт: при покупке недвижимости или приобретении долей/акций польской компании нотариальный акт должен содержать сведения о гражданстве и номер PESEL. Остальное касается организации работы нотариусов.","key_changes":["В акте о покупке недвижимости иностранцем указываются гражданство и номер PESEL физлица","Для субъекта с местом нахождения в РП — заявление, является ли он cudzoziemcem, с обоснованием и REGON","Требование распространено и на приобретение долей, акций или прав и обязанностей в польской компании","В akt poświadczenia dziedziczenia добавляются PESEL наследников и REGON юрлиц","Нотариус сможет подавать заявления в księga wieczysta и вне связи с собственной сделкой (платно)"],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранцы, приобретающие доли и акции польских компаний","наследники-иностранцы","клиенты нотариальных контор"],"practical_impact":"При сделке с недвижимостью или долями компании нотариус потребует данные о гражданстве и номер PESEL, а при отсутствии однозначности — заявление о статусе cudzoziemca. Дополнительно появится платная возможность подать заявление в земельную книгу через нотариуса.","effective_date":"Через 14 дней после опубликования; изменение ст. 1 п. 23 lit. b (подача заявлений в księga wieczysta) — через 6 месяцев после опубликования.","confidence":0.85,"rationale":"Основная часть проекта касается профессии нотариуса, но есть конкретное новое требование к данным иностранцев в нотариальных актах при сделках с недвижимостью и долями — косвенное влияние.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":128815,"truncated":false,"text_source":"documents","created_at":"2026-09-21T10:53:18Z","input_tokens":61122,"output_tokens":806,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12414851/13227172/13227173/dokument798038.docx","source_kind":"rcl","revision":1,"text_sha256":"abdffc03069000691d48f86368d70d0afb5fb4f86460d0cac453a21aa6c8daba","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":"2026-09-21T10:53:18Z"}',0,NULL,'2026-09-21T10:52:18+00:00','2026-10-28T19:17:57+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12414851,"title":"Projekt ustawy o zmianie ustawy – Prawo o notariacie oraz ustawy – Kodeks postępowania cywilnego","applicant":"Minister