INSERT INTO "bills" VALUES(10,'RCL/12400450','Projekt ustawy o zmianie ustawy – Prawo lotnicze','2026-10-28T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12400450","title":"Projekt ustawy o zmianie ustawy – Prawo lotnicze","description":"LOTNICZE PRAWO; transport. Numer i tytuł aktu prawnego Unii Europejskiej: 1) rozporządzenie Parlamentu Europejskiego i Rady (UE) 2023/1804 z dnia 13 września 2023 r. w sprawie rozwoju infrastruktury paliw alternatywnych i uchylenia dyrektywy 2014/94/UE (Dz. Urz. UE L 234 z 22.09.2023, str. 1); 2) rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/1679 z dnia 13 czerwca 2024 r. w sprawie unijnych wytycznych dotyczących rozwoju transeuropejskiej sieci transportowej, zmieniającego rozporządzenia (UE) 2021/1153 i (UE) nr 913/2010 oraz uchylającego rozporządzenie (UE) nr 1315/2013 (Dz. Urz. UE L 2024/1679 z 28.06.2024).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-29","document_date":"2026-08-03","change_date":"2026-10-28T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12400450","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-06-30","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','696b8f66e8df04232a3c425fe6b260d3282f15f430ada09597b0e581b397f4df',NULL,0,'text prefilter: no keyword hits','2026-09-21T10:52:30+00:00','2026-10-28T18:55:50+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12400450,"title":"Projekt ustawy o zmianie ustawy – Prawo lotn