INSERT INTO "bills" VALUES(10,'RPW/31837/2026','Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe','2026-09-22T00:00:00+00:00',NULL,NULL,'linked','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/31837/2026","title":"Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe","description":"rozszerzenia katalogu źródeł dochodów wydzielonego rachunku, obejmując nim odpłatne udostępnianie mienia (kuchnie i stołówki, sale lekcyjne i gimnastyczne, pracownie, aule, sale koncertowe i baletowe, boiska, sprzęt sportowy i muzyczny), odpłatne świadczenie usług przy jego wykorzystaniu, sprzedaż rzeczy wytworzonych oraz odsetki. Wprowadzenia warunków dopuszczalności tj. zakazu ograniczania zadań statutowych oraz wymogu ustalania wynagrodzenia na poziomie nie niższym niż suma kosztów. Projekt ustawy uchyla obowiązek odprowadzania środków na koniec roku budżetowego, utrzymuje limit wydatków do wysokości środków zgromadzonych na rachunku, nakłada obowiązek wyodrębnionej ewidencji księgowej oraz rocznej informacji dla organu wykonawczego. Projekt ustawy przesądza dopuszczalność odpłatnego przygotowywania i wydawania posiłków na rzecz osób spoza szkoły, po zapłacie pełnego kosztu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-22","document_date":"2026-09-22","change_date":"2026-09-22T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-09-22T15:58:29+00:00','2026-09-23T00:53:04+00:00','{"term":10,"number":"RPW/31837/2026","title":"Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe","description":"rozszerzenia katalogu źródeł dochodów wydzielonego rachunku, obejmując nim odpłatne udostępnianie mienia, odpłatne świadczenie usług przy jego wykorzystaniu, sprzedaż rzeczy wytworzonych oraz wprowadza warunki dopuszczalności tj. zakaz  ograniczenia zadań statutowych oraz wymóg ustalania wynagrodzenia na poziomie nie niższym niż suma kosztów a także  uchyla obowiązek odprowadzania środków na koniec roku budżetowego i utrzymuje limit wydatków do wysokości środków zgromadzonych na rachunku i nakłada obowiązek wyodrębnionej ewidencji księgowej oraz rocznej informacji dla organu wykonawczego","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-22","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-09-23","consultation_end":"2026-10-23","consultation_results":false,"withdrawn_date":null}','3206',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12404454','Projekt ustawy o stażach','2026-10-29T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatele_ukrainy", "text:zatrudnianie_cudzoziemcow", "text:pracownicy_delegowani", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RCL/12404454","title":"Projekt ustawy o stażach","description":"PRACA; praca","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-11-21","document_date":"2026-10-12","change_date":"2026-10-29T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12404454","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','36efeac379a7c031e9de5e16bbe981102fb807304730f8ec8336a204d0f5e87c','{"analysis":{"relevant":true,"score":4,"category":"employment","summary":"Проект вводит новый закон о стажах вместо практик absolwenckich: все стажи на открытом рынке становятся платными и оформляются как umowa o pracę. Участвовать смогут поляки, граждане ЕС/ЕЭЗ, некоторые британцы и иностранцы с полным доступом к рынку труда по спецзакону.","key_changes":["Стаж = работа по umowa o pracę na czas określony, максимум 6 месяцев","Минимальная оплата стажа: не ниже 65% минимальной зарплаты","Круг участников: поляки, ЕС/ЕЭЗ, часть британцев, иностранцы из art. 3 ust. 1 i 5 pkt 1‑5 спецзакона","Отмена ustawa o praktykach absolwenckich, бесплатные практики исчезают","Стажёр получает соцстрахование как работник; данные о стажах передаются в ZUS и МРPiPS"],"affected_groups":["Иностранцы с правом работы без zezwoleń по ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom","Граждане ЕС/ЕЭЗ, Швейцарии и иных стран со свободой передвижения","Некоторые граждане Великобритании и члены их семей по Umowa o wystąpieniu","Иностранные выпускники и студенты, ищущие стаж на открытом рынке","Организаторы стажей, нанимающие иностранных стажёров"],"practical_impact":"Иностранец с полным доступом к рынку труда сможет проходить только оплачиваемый стаж по umowa o pracę с взносами в ZUS и защитой по Kodeks pracy. Бесплатные «praktyki absolwenckie» исчезнут, но появятся чёткие минимальные ставки оплаты и стандарты стажа.","effective_date":"Закон вступает в силу с 1 января 2027 года.","confidence":0.95,"rationale":"Акт комплексно регулирует стажи как форму работы, прямо определяет круг допущенных иностранцев и условия их оплаты и страхования, что существенно для трудовых прав, но не меняет правил легализации пребывания.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":["Минимальная оплата стажа изменена: было ≥35% средней зарплаты, стало ≥65% минимальной зарплаты без верхнего предела.","Umowa o staż прямо признана umowa o pracę na czas określony с частичным применением Kodeks pracy, а не отдельным гражданско‑правовым договором.","Расширен и уточнён круг иностранцев: добавлены отдельные категории граждан Великобритании и их семей и ссылка на art. 3 ust. 5 pkt 1‑5 спецзакона о работе иностранцев.","Изменена модель соцстраха: взрослые стажёры страхуются как работники, а несовершеннолетние стажисты освобождены от обязательных пенсионных и рентных взносов.","Подробно урегулирован «staż z małoletnim stażystą» с выплатой минимум 500 zł стажисту и дотацией 750 zł организатору за месяц.","Закреплена дата вступления в силу (1.01.2027), добавлены численные лимиты на количество стажёров у одного организатора и новые составы нарушений с крупными штрафами."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":115478,"truncated":false,"text_source":"documents","created_at":"2026-10-12T22:14:38Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171191/13171192/dokument801844.zip","source_kind":"rcl","revision":2,"text_sha256":"text-v2:3cb0bf125f8d9ffba6558af943a27d6f02bb6f6b19f0ae555d738b02c8ec2244","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":"law-v2:fde80988ad0ee8ddd1ca1ce8b82bdfbbe171fcfa38a854db236375da77d851b7","source_checked_at":"2026-10-12T22:14:38Z"}',0,NULL,'2026-09-22T15:59:03+00:00','2026-10-29T19:06:26+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12404454,"title":"Projekt ustawy o stażach","applicant":"Minister Rodziny, Pracy i Polityki Społecznej","wykaz_number":"UD307","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2025-11-21","modified":"2026-10-29","departments":["praca"],"keywords":["PRACA"],"status":"otwarty","term_label":"X","stages":[{"id":13171153,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13171154,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-09-23","folders":[{"id":13171155,"name":"Projekt","modified":"2026-04-21","documents":[{"id":749794,"name":"Projekt ustawy o stażach 17.11.2025","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument749794.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":749795,"name":"Uzasadnienie do projektu ustawy o stażach 17.11.2025","url":"https://legislacja.rcl.gov.pl/docs//2/12404454/13171154/13171155/dokument749795.pdf","created":"2025-11-21","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":749796,"name":"OSR do projektu ustawy o stażach 17.11.2025","ur