INSERT INTO "bills" VALUES(10,'3135','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług','2026-10-28T11:14:54+00:00','2026-10-22',1,'skipped_text_prefilter','["text:pobyt_kwalifikowany"]','{"term":10,"number":"3135","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług","description":"projekt dotyczy zlikwidowania preferencyjnego opodatkowania napojów będących bezalkoholowymi odpowiednikami napojów alkoholowych, jak również napojów energetyzujących; podwyższenia stawki VAT do 23% na określone napoje bezalkoholowe, które zawierają w swoim składzie co najmniej 20% soku owocowego, warzywnego lub owocowo-warzywnego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-23","change_date":"2026-10-28T11:14:54Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (pobyt_kwalifikowany×1)','2026-09-28T11:48:52+00:00','2026-10-29T19:00:06+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3137','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne','2026-10-28T11:12:10+00:00','2026-10-22',1,'analyzed','[]','{"term":10,"number":"3137","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne","description":"projekt dotyczy ujednolicenia m.in. zasad opodatkowania świadczeń na zaspokojenie potrzeb rodziny, rozszerzenia zwolnienia podatkowego dla organizacji pozarządowych oraz doprecyzowania zasad obliczania daniny solidarnościowej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-24","change_date":"2026-10-28T11:12:10Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-158-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-158-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3137","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-06","sitting_num":66,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"FPB","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_t