INSERT INTO "bills" VALUES(10,'3138','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób prawnych oraz ustawy o portach i przystaniach morskich','2026-10-23T07:18:45+00:00',NULL,0,'skipped_text_prefilter','["text:straz_graniczna"]','{"term":10,"number":"3138","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób prawnych oraz ustawy o portach i przystaniach morskich","description":"projekt dotyczy dostosowania zasad korzystania ze zwolnienia podatkowego przez podmioty zarządzające portami morskimi do wymogów unijnego prawa pomocy publicznej. Zwolnieniem zostaną objęte m.in. wydatki na: budowę, wymianę i modernizację infrastruktury portowej oraz infrastruktury zapewniającej dostęp do portów od strony morza i lądu, pogłębianie, planowanie tych inwestycji, zadania o charakterze niegospodarczym, m.in. związane z bezpieczeństwem ruchu morskiego, ochroną przeciwpożarową i ochroną portów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-23T07:18:45Z","passed":false,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (straz_graniczna×2)','2026-09-28T11:48:53+00:00','2026-10-24T11:20:58+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3136','Rządowy projekt ustawy o zmianie ustawy o podatku akcyzowym oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych','2026-10-28T11:15:52+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3136","title":"Rządowy projekt ustawy o zmianie ustawy o podatku akcyzowym oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych","description":"projekt dotyczy podwyżki stawek akcyzy w 2027 r. na alkohol etylowy, piwo, wino, napoje fermentowane i wyroby pośrednie; przeznaczenia dodatkowych wpływów z akcyzy na zwiększenie dotacji podmiotowej dla Narodowego Funduszu Zdrowia, a tym samym na finansowanie świadczeń opieki zdrowotnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-24","change_date":"2026-10-28T11:15:52Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:09+00:00','2026-10-29T19:00:06+00:00','{"term":10,"number":"RPW/32222/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku akcyzowym oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych","description":"podwyżki stawek akcyzy w 2027 r. na alkohol etylowy, piwo, wino, napoje fermentowane i wyroby pośrednie; przeznaczenia dodatkowych wpływów z akcyzy na zwiększenie dotacji podmiotowej dla Narodowego Funduszu Zdrowia, a tym samym na finansowanie świadczeń opieki zdrowotnej","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-24","print_number":"3136","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)