INSERT INTO "bills" VALUES(10,'3139','Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Kirgiską, z drugiej strony, sporządzonej w Brukseli dnia 25 czerwca 2024 r.','2026-10-22T07:50:46+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:migracja", "text:azyl", "text:uchodzcy", "text:repatriacja", "text:obywatelstwo", "text:wizy", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:ochrona_miedzynarodowa", "text:nostryfikacja", "text:status_uchodzcy", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji", "text:nierezydenci"]','{"term":10,"number":"3139","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Kirgiską, z drugiej strony, sporządzonej w Brukseli dnia 25 czerwca 2024 r.","description":"projekt dotyczy wprowadzenia lepszej ochrony praw własności intelektualnej poprzez ustanowienie 167 oznaczeń geograficznych produktów pochodzących z Unii Europejskiej, które będą chronione w Republice Kirgiskiej bezpośrednio na podstawie Umowy. W przypadku Rzeczypospolitej Polskiej, postanowienia te dotyczą napojów spirytusowych, a w szczególności Wódki ziołowej z Niziny Północnopodlaskiej aromatyzowanej ekstraktem z trawy żubrowej i Polskiej Wódki. Umowa stworzy również ramy prawne do bardziej zaawansowanej współpracy w dziedzinie wzajemnej pomocy prawnej i ekstradycji w oparciu o odpowiednie umowy międzynarodowe","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-22T07:50:46Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3139","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-21","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3217","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3217/3217.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3139","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-21","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3217","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3217/3217.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}]','e42b9cc79aeff2098d90b199c489aa3cec8288b313e6a3952e217ef4192d855e','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию нового соглашения о партнёрстве и сотрудничестве ЕС с Кыргызстаном, заменяющего договор 1995 года. Соглашение касается торговли, инвестиций, защиты географических указаний, а также сотрудничества в сфере миграции, реадмиссии и правовой помощи. Прямо права граждан Кыргызстана в Польше не меняет.","key_changes":["Кыргызстан обязуется принимать обратно своих граждан, не имеющих права находиться в странах ЕС, без дальнейших формальностей","Допускается использование европейского проездного документа для возврата нелегально пребывающих лиц","Стороны могут договориться о соглашении ЕС–Кыргызстан об упрощении визового режима и о реадмиссии","Внутрикорпоративные переводы: руководители и специалисты — до 3 лет, стажёры — до 1 года, при соблюдении национальных правил","Граждане Кыргызстана могут получать консульскую защиту в странах ЕС без его представительства"],"affected_groups":["граждане Кыргызстана в Польше и ЕС","граждане Кыргызстана без законных оснований для пребывания","сотрудники кыргызских компаний, переводимые внутри корпорации","инвесторы из Кыргызстана"],"practical_impact":"Для граждан Кыргызстана в Польше правила получения виз, разрешений на пребывание и работу не меняются: соглашение прямо указывает, что национальное законодательство о въезде, пребывании и работе продолжает действовать. Возможно упрощение возврата лиц без законного статуса в Кыргызстан.","effective_date":"Закон вступает в силу через 14 дней со дня опубликования; само соглашение — в первый день второго месяца после взаимного уведомления сторон о завершении внутренних процедур.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения, затрагивающего миграцию и реадмиссию лишь на уровне рамочного сотрудничества без изменения национальных правил пребывания, соответствует косвенному влиянию (оценка 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1268621,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3139/3139.pdf","source_kind":"print","revision":1,"text_sha256":"f95398d40b3ad92b97a13150325f6533e52d48eed4dc3c935c8b00a65d342a7f","law_sha256":"456b4c65ebdae98b25e579ecef9dbc4d7ec5e2abc38426606a68d427b162151a","source_checked_at":"2026-10-01T19:47:47Z"}',0,NULL,'2026-09-28T15:32:09+00:00','2026-10-28T19:18:50+00:00','{"term":10,"number":"RPW/32110/2026","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Kirgiską, z drugiej strony, sporządzonej w Brukseli dnia 25 czerwca 2024 r.","description":"wprowadzenia lepszej ochrony praw własności intelektualnej poprzez ustanowienie 167 oznaczeń geograficznych produktów pochodzących z Unii Europejskiej, które będą chronione w Republice Kirgiskiej bezpośrednio na podstawie Umowy. W przypadku Rzeczypospolitej Polskiej, postanowienia te dotyczą napojów spirytusowych, a w szczególności Wódki ziołowej z Niziny Północnopodlaskiej aromatyzowanej ekstraktem z trawy żubrowej i Polskiej Wódki. Umowa stworzy również ramy prawne do bardziej zaawansowanej współpracy w dziedzinie wzajemnej pomocy prawnej i ekstradycji w oparciu o odpowiednie umowy międzynarodowe","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3139","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3139","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-21","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3217","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3217/3217.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3139/3139.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"f95398d40b3ad92b97a13150325f6533e52d48eed4dc3c935c8b00a65d342a7f","analysis_revision":1,"seen_supplements":[]}',2,NULL,NULL,NULL,'full','relevant_analysis',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3140','Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Uzbekistanu, z drugiej strony, sporządzonej w Brukseli dnia 24 października 2025 r','2026-10-22T07:48:52+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:migracja", "text:azyl", "text:uchodzcy", "text:repatriacja", "text:obywatelstwo", "text:wizy", "text:ochrona_miedzynarodowa", "text:zatrudnianie_cudzoziemcow", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji", "text:nierezydenci"]','{"term":10,"number":"3140","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Uzbekistanu, z drugiej strony, sporządzonej w Brukseli dnia 24 października 2025 r","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-22T07:48:52Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3140","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-21","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3218","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3218/3218.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3140","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-21","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3218","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3218/3218.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}]','85ce0db1cfb80865fe74872e8e8bf5886cb30f6dadc6a50b1bbd066c8c97450e','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект даёт согласие на ратификацию Расширенного соглашения о партнёрстве и сотрудничестве между ЕС и Узбекистаном. Соглашение в основном касается торговли и сотрудничества, но содержит положения о миграции, реадмиссии граждан без права пребывания и деловых поездках. Прямо польское право оно не меняет.","key_changes":["Узбекистан и страны ЕС обязуются без промедления принимать обратно своих граждан, не имеющих права на пребывание","Документы для возврата выдаются в течение 30 дней после запроса о реадмиссии","Предусмотрен диалог о легальной миграции, защите прав легальных мигрантов и интеграции","Стороны могут начать переговоры о соглашении об упрощении визового режима","Внутрикорпоративный перевод: пребывание до 3 лет; бизнес-визиты для создания компании — до 90 дней"],"affected_groups":["граждане Узбекистана в Польше","граждане Узбекистана без законного права на пребывание","сотрудники компаний, переводимые внутри корпорации","поставщики услуг по контракту из Узбекистана"],"practical_impact":"Для граждан Узбекистана, не имеющих законного права на пребывание в Польше, упрощается процедура возврата на родину (реадмиссии). Требования ustawa o cudzoziemcach (закон об иностранцах) к въезду, пребыванию и работе продолжают действовать; соглашение не даёт физическим лицам прав, на которые можно ссылаться напрямую.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.8,"rationale":"Ратификация двустороннего соглашения с миграционными и реадмиссионными положениями, не меняющего польское право напрямую, относится к косвенному влиянию (балл 2).","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1199982,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3140/3140.pdf","source_kind":"print","revision":1,"text_sha256":"c9e3239a71f94f23614e5789a1164dce5b9300379487c172b974aeb046cf0215","law_sha256":"bd63c7778e67c215a4e785407220c9c4a908b870e4e689e9f59c4d1200c0254d","source_checked_at":"2026-10-01T19:48:22Z"}',0,NULL,'2026-09-28T15:32:10+00:00','2026-10-28T19:18:50+00:00','{"term":10,"number":"RPW/32104/2026","title":"Rządowy projekt ustawy o ratyfikacji Wzmocnionej umowy o partnerstwie i współpracy między Unią Europejską i jej państwami członkowskimi, z jednej strony, a Republiką Uzbekistanu, z drugiej strony, sporządzonej w Brukseli dnia 24 października 2025 r","description":null,"applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3140","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3140","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SZA","sub_committee":false,"committee_name":"Komisja Spraw Zagranicznych","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"SUE","sub_committee":false,"committee_name":"Komisja do Spraw Unii Europejskiej","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-21","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3218","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3218/3218.pdf","proposal":"uchwalić projekt ustawy bez poprawek","sub_committee":false,"minority_motions":0,"children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3140/3140.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analys