INSERT INTO "bills" VALUES(10,'3141','Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw','2026-10-23T08:10:28+00:00','2026-10-22',1,'analyzed','[]','{"term":10,"number":"3141","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-23","change_date":"2026-10-23T08:10:28Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-155-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-155-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3141","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-08","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-08","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-08","print_number":"3201","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3201/3201.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-20","sitting_num":67,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3141/attachment/3141_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":439,"no":1,"abstain":0,"not_participating":20,"sitting":67,"voting_number":152,"date":"2026-10-22T16:47:47Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/152/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"title_final":"o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-24","print_number":"3141","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-08","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-08","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-08","print_number":"3201","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3201/3201.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-20","sitting_num":67,"decision":"niezwłocznie przystąpiono do III czytania","sub_committee":false,"children":[]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3141/attachment/3141_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":439,"no":1,"abstain":0,"not_participating":20,"sitting":67,"voting_number":152,"date":"2026-10-22T16:47:47Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/152/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','85861df78b399132d95e60ed542622d19cee918284f272918d6e1d1875b810af','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект вводит систему Оśrodków Eksperckich Chorób Rzadkich (центров по редким болезням) и меняет правила медстрахования NFZ в трансграничных ситуациях с ЕС/EFTA/Великобританией. Уточняются группы лиц, застрахованных в NFZ, и порядок возмещения расходов на лечение за рубежом.","key_changes":["Новая процедура NFZ по возврату расходов на лечение в ЕС/EFTA/Великобритании во время пребывания там","К заявлению на согласие/возмещение можно приложить заключение врача из ЕС/EFTA/UK с присяжным переводом","Медстрахование NFZ для выпускников-медиков на практике и слушателей курсов польского языка/подготовительных курсов","NFZ может сам зарегистрировать члена семьи в медстраховании, если по правилам ЕС он должен быть застрахован в Польше","Пенсионеры с работой в ЕС/EFTA/UK должны в 14 дней сообщить об окончании, долг по взносам могут удержать из пенсии"],"affected_groups":["иностранцы, лечащиеся по NFZ и выезжающие в страны ЕС/EFTA/Великобританию","иностранные слушатели курсов польского языка и подготовительных курсов к обучению на польском","выпускники медицинских направлений (в т.ч. из-за рубежа), проходящие практическое обучение в Польше","пенсионеры и получатели рент с польскими и иностранными доходами/работой","члены семей застрахованных, живущие между Польшей и другими странами ЕС/EFTA/Великобританией"],"practical_impact":"Иностранцам с правом на NFZ будет проще вернуть расходы за необходимое лечение, полученное во время поездки в ЕС/EFTA/UK, в т.ч. на основе заключения местного врача. Слушатели языковых и подготовительных курсов и выпускники‑медики на практике получают право на медстрахование NFZ, а пенсионерам с зарубежной работой нужно строго соблюдать сроки уведомлений, иначе недоплаченные взносы удержат из пенсии.","effective_date":"Закон вступает в силу по истечении 14 дней со дня обнародования, за исключением art. 1 pkt 9 lit. e и g и pkt 13 и art. 2, которые вступают в силу по истечении 12 месяцев со дня обнародования, а также art. 1 pkt 25 и art. 3, которые вступают в силу по истечении 9 месяцев со дня обнародования.","confidence":0.86,"rationale":"Акт меняет правила доступа к медицинскому страхованию NFZ и возмещению стоимости лечения за рубежом в контексте координации систем соцобеспечения ЕС/EFTA/UK, что напрямую затрагивает иностранцев, пользующихся польской системой здравоохранения, но не затрагивает легализацию их пребывания.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":42282,"truncated":false,"text_source":"pdf","created_at":"2026-10-12T22:14:38Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3201/3201.pdf","source_kind":"committee_report","revision":4,"text_sha256":"text-v2:7aa5a1e4449c4a5ff027c159ffa1944993938ff9dccc8cbbb119fc646d460126","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3201/3201.pdf","members":[],"container_sha256":"e70afa46b57591269a4de9788d27d9d82fbed753032961b754d9bdd17d5d15fa","sha256":"e70afa46b57591269a4de9788d27d9d82fbed753032961b754d9bdd17d5d15fa","role":"bill","text":"","pages":20,"page_start":1,"page_end":20,"text_start":0,"text_end":42282,"text_sha256":"0f3fb257d5e5a8796068f12780df1ab4fc0d1581b178fc572bbebff65e15dc35","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3201/3201.pdf","text_sha256":"0f3fb257d5e5a8796068f12780df1ab4fc0d1581b178fc572bbebff65e15dc35","block_id":"part:0","start":0,"end":1101,"quote":"Druk nr 3201\nSEJM\nRZECZYPOSPOLITEJ POLSKIEJ\nX kadencja\n\nS P R A W O Z D A N I E\nKOMISJI ZDROWIA\n\no rządowym projekcie ustawy o zmianie ustawy\no świadczeniach opieki zdrowotnej\nfinansowanych ze środków publicznych oraz\nniektórych innych ustaw (druk nr 3141)\n\nMarszałek Sejmu, zgodnie z art. 37 ust. 1 i art. 40 ust. 1 regulaminu Sejmu skierował\nw dniu 28 września 2026 r. powyższy projekt ustawy do Komisji Zdrowia do  pierwszego\nczytania.\nKomisja Zdrowia po przeprowadzeniu pierwszego czytania oraz rozpatrzeniu tego\nprojektu ustawy na posiedzeniu w dniu 8 października 2026 r.\n\nwnosi:\n\nWysoki Sejm  uchwalić raczy załączony projekt ustawy.\n\nWarszawa, dnia 8 października 2026 r.\n\n  Sprawozdawca\n\n  (-) Iwona Kozłowska\n\nPrzewodnicząca Komisji\nZdrowia\n\n(-)  Marta Golbik\n\n Tłoczono z polecenia Marszałka Sejmu Rzeczypospolitej Polskiej\n\n\fLiczba stron :  19     Data :   2026-10-12      Nazwa pliku :   V3_481-91.NK  1\nX kadencja/druk nr 3141\nProjekt\nU S T AWA\nz dnia … 2026 r.\no zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków\npublicznych oraz niektórych innych ustaw1)\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":42282,"page_start":1,"page_end":20,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":42282,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"527876d81d404f09212dfcabfc61bc121fdabf0824880c3dee05d4e05204f63c"},"law_sha256":"law-v2:7893a81afe0c09ad32d3f64ecb7219f3f33ec2127c4e19bf92e9fd82e70e4659","source_checked_at":"2026-10-21T18:11:06Z"}',0,NULL,'2026-09-28T15:32:10+00:00','2026-10-29T19:06:28+00:00','{"term":10,"number":"RPW/32097/2026","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"wprowadzenia zasad powoływania Ośrodków Eksperckich Chorób Rzadkich; uszczelnienia systemu ubezpieczenia zdrowotnego w stosunku do osób w sytuacjach transgranicznych związanych ze stosowaniem unijnych przepisów o koordynacji systemów zabezpieczenia społecznego wobec braku zgodności przepisów w zakresie transgranicznej opieki zdrowotnej z wymogami prawa unijnego oraz występowania tzw. luk prawnych w zakresie uregulowań dotyczących pobierania składek na ubezpieczenie zdrowotne z emerytur i rent transferowanych na rachunki bankowe z innych państw członkowskich Unii Europejskiej lub państwa członkowskiego Europejskiego Porozumienia o Wolnym Handlu i Zjednoczonego Królestwa Wielkiej Brytanii i Irlandii Północnej","applicant":"government","status":"A