INSERT INTO "bills" VALUES(10,'3142','Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi','2026-10-23T08:08:32+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3142","title":"Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"projekt dotyczy zmiany daty końcowej obowiązywania wykazu świadczeniodawców zakwalifikowanych do systemu podstawowego szpitalnego zabezpieczenia świadczeń opieki\nzdrowotnej, z dnia 30 czerwca 2027 r., na dzień 30 czerwca 2029 r","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-23T08:08:32Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:10+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/32087/2026","title":"Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"zmiany daty końcowej obowiązywania wykazu świadczeniodawców zakwalifikowanych do systemu podstawowego szpitalnego zabezpieczenia świadczeń opieki\nzdrowotnej, z dnia 30 czerwca 2027 r., na dzień 30 czerwca 2029 r","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3142","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3143','Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi','2026-10-23T08:13:01+00:00','2026-10-22',1,'analyzed','["text:obywatele_ukrainy"]','{"term":10,"number":"3143","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"projekt dotyczy określenia sposobu finansowania świadczeń opieki zdrowotnej udzielanych: osadzonym w zakładach penitencjarnych w ramach programu polityki zdrowotnej leczenia wirusowego zapalenia wątroby typu C (HCV) i osobom nieposiadającym uprawnień z tytułu ubezpieczenia zdrowotnego w ramach programu polityki zdrowotnej leczenia antyretrowirusowego osób zakażonych HIV. Świadczenia te będą finansowane przez NFZ, niezależnie od tego, czy dana osoba posiada ubezpieczenie zdrowotne.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-23T08:13:01Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-159-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-159-26","prints_considered_jointly":["3153"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3143","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}]','ab53bdb954d41412af5191888e8bf74911a521ac2caed09d988ff90acf4241df','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект уточняет, кто оплачивает медицинские услуги в двух государственных программах: лечение ВИЧ для людей без медицинской страховки и лечение гепатита C у заключённых. Визиты и анализы в программе лечения ВИЧ для незастрахованных будут оплачиваться из госбюджета. Иностранцы прямо не упоминаются, но касается это и незастрахованных иностранцев.","key_changes":["Услуги, связанные с антиретровирусным лечением ВИЧ, для лиц без права на страховку NFZ оплачиваются из госбюджета (бюджет министра здравоохранения)","Цель — устранить практику, когда за визиты и анализы в программе лечения ВИЧ с незастрахованных брали плату","NFZ сможет финансировать не только лекарства, но и медицинские услуги в программе лечения гепатита C у заключённых","Средства NFZ на программы передаются на счета бюджетных учреждений в сроках и суммах, определяемых министром здравоохранения"],"affected_groups":["люди, живущие с ВИЧ, без медицинской страховки в Польше, в том числе иностранцы","заключённые с хроническим гепатитом C","медучреждения, реализующие программу лечения ВИЧ"],"practical_impact":"Незастрахованный иностранец с ВИЧ, находящийся в Польше, должен получать в рамках программы не только бесплатные лекарства, но и бесплатные визиты к врачу и анализы, без оплаты из собственного кармана.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.65,"rationale":"Законопроект не касается иностранцев как таковых, но улучшает доступ к лечению ВИЧ для всех незастрахованных, среди которых значительную часть составляют иностранцы, поэтому влияние косвенное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":23123,"truncated":false,"text_source":"pdf","created_at":"2026-09-28T15:56:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3143/3143.pdf","source_kind":"print","revision":1,"text_sha256":"8bb9393c139e45c2aaf392d29025b78844821bb0d8aedc9feba2246a43f5b254","law_sha256":"a7143e39f1a65909586956a7ca2e0d937977f74b5b7559dfc13a64a5459c6a7c","source_checked_at":"2026-10-01T19:48:30Z"}',0,NULL,'2026-09-28T15:32:11+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/32111/2026","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"określenia sposobu finansowania świadczeń opieki zdrowotnej udzielanych: osadzonym w zakładach penitencjarnych w ramach programu polityki zdrowotnej leczenia wirusowego zapalenia wątroby typu C (HCV) i osobom nieposiadającym uprawnień z tytułu ubezpieczenia zdrowotnego w ramach programu polityki zdrowotnej leczenia antyretrowirusowego osób zakażonych HIV. Świadczenia te będą finansowane przez NFZ, niezależnie od tego, czy dana osoba posiada ubezpieczenie zdrowotne.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3143","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,'[{"kind": "committee", "ref": "ZDR/169/2026-10-08+13:00+sala im. Leszka Moczulskiego (nr 211, bud. U)", "date": "2026-10-08", "end_date": null, "start_time": "13:00:00", "committee_code": "ZDR", "committee_name": "Komisja Zdrowia", "sitting_number": 168, "room": "sala im. Leszka Moczulskiego (nr 211, bud. U)", "text": "Pierwsze czytanie rządowego projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (druk nr 3143)", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=356C25BF3DD66CD1C1258E8200442D99", "condition": null, "closed": false, "apply_email": null, "apply_by": null}]',NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3143","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3143/3143.pdf","kind":"print","extra_urls":[]},"analysis_sha256":"8bb9393c139e45c2aaf392d29025b78844821bb0d8aedc9feba2246a43f5b254","analysis_revision":1,"seen_supplements":[]}',2,NULL,NULL,NULL,'full','relevant_analysis',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3144','Rządowy projekt ustawy o zmianie ustawy o działalności leczniczej oraz ustawy o systemie informacji w ochronie zdrowia','2026-10-23T08:16:20+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3144","title":"Rządowy projekt ustawy o zmianie ustawy o działalności leczniczej oraz ustawy o systemie informacji w ochronie zdrowia","description":"projekt dotyczy wprowadzenia większej jawności konkursów na udzielanie świadczeń zdrowotnych oraz zawieranych umów. Podmioty lecznicze będą publikować m.in. informacje o konkursach, ich wynikach oraz warunkach finansowych ofert. Dane będą udostępniane na stronach internetowych, jak i w centralnej aplikacji","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-23T08:16:20Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:11+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/32098/2026","title":"Rządowy projekt ustawy o zmianie ustawy o działalności leczniczej oraz ustawy o systemie informacji w ochronie zdrowia","description":"wprowadzenia większej jawności konkursów na udzielanie świadczeń zdrowotnych oraz zawieranych umów. Podmioty lecznicze będą publikować m.in. informacje o konkursach, ich wynikach oraz warunkach finansowych ofert. Dane będą udostępniane na stronach internetowych, jak i w centralnej aplikacji","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-23","print_number":"3144","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3145','Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym oraz niektórych innych ustaw','2026-10-09T12:22:00+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3145","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym oraz niektórych innych ustaw","description":"projekt dotyczy uproszczenia poboru opłaty od środków spożywczych oraz wyeliminowania zidentyfikowanych ograniczeń i wątpliwości interpretacyjnych związanych ze stosowaniem obowiązujących przepisów dotyczących opłaty od środków spożywczych. W szczególności proponuje się doprecyzowanie definicji napoju podlegającego opłacie oraz skonkretyzowanie zdarzeń powodujących powstanie obowiązku zapłaty opłaty. Istotną zmianą zaproponowaną w projekcie jest powiązanie obowiązku zapłaty opłaty z pierwszą sprzedażą napoju, a nie jak było dotychczas - z wprowadzeniem napoju na rynek krajowy.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-24","document_date":"2026-09-24","change_date":"2026-10-09T12:22:00Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-28T15:32:12+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/32223/2026","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym oraz niektórych innych ustaw","description":"uproszczenia poboru opłaty od środków spożywczych oraz wyeliminowania zidentyfikowanych ograniczeń i wątpliwości interpretacyjnych związanych ze stosowaniem obowiązujących przepisów dotyczących opłaty od środków spożywczych. W szczególności proponuje się doprecyzowanie definicji napoju podlegającego opłacie oraz skonkretyzowanie zdarzeń powodujących powstanie obowiązku zapłaty opłaty. Istotną zmianą zaproponowaną w projekcie jest powiązanie obowiązku zapłaty opłaty z pierwszą sprzedażą napoju, a nie jak było dotychczas ? z wprowadzeniem napoju na rynek krajowy.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-24","print_number":"3145","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3146','Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw','2026-10-28T11:16:32+00:00','2026-10-22',1,'analyzed','["text:cudzoziemcy", "text:migracja", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen", "text:pracownicy_delegowani"]','{"term":10,"number":"3146","title":"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","description":"projekt dotyczy zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-28T11:16:32Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-143-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3146","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-28","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-28","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-08","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-08","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-08","print_number":"3196","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-22","print_number":"3196-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":251,"no":144,"abstain":41,"not_participating":24,"sitting":67,"voting_number":177,"date":"2026-10-22T17:04:08Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/177/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-10-27","print_number":"3275","position":"wniósł poprawki","sub_committee":false,"children"