api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":251,"no":144,"abstain":41,"not_participating":24,"sitting":67,"voting_number":177,"date":"2026-10-22T17:04:08Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/177/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-10-27","print_number":"3275","position":"wniósł poprawki","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-28","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','758cc3cfd5f3f42d5ce873d1e9186cc4ac36ae647edf296e2eebb55de8b89691','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.","key_changes":["В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС","Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы","Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу","В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex","В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше"],"affected_groups":["иностранцы с решениями о возврате/выдворении","мигранты с неурегулированным статусом, подлежащие депортации","лица, находящиеся в процедурах принудительного возвращения"],"practical_impact":"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.","effective_date":"закон вступает в силу через 14 дней со дня его официального опубликования.","confidence":0.94,"rationale":"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":25424,"truncated":false,"text_source":"pdf","created_at":"2026-10-09T14:59:32Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"text-v2:9a627081d5ebee24320cd3df17b863358eac053a2ca96a3a63930842c85ef393","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf","members":[],"container_sha256":"a81d8c71ca12c5ffe4113001b6173e2cf5c787bf5d22d935190e55393148f319","sha256":"a81d8c71ca12c5ffe4113001b6173e2cf5c787bf5d22d935