INSERT INTO "bills" VALUES(10,'RCL/12399111','Projekt ustawy o zmianie ustawy – Prawo bankowe oraz niektórych innych ustaw','2026-09-29T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:obywatelstwo"]','{"term":10,"number":"RCL/12399111","title":"Projekt ustawy o zmianie ustawy – Prawo bankowe oraz niektórych innych ustaw","description":"BANKOWE PRAWO; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/1619 z dnia 31 maja 2024 r. w sprawie zmiany dyrektywy 2013/36/UE w odniesieniu do uprawnień nadzorczych, sankcji, oddziałów z państw trzecich i ryzyk środowiskowych, społecznych i z zakresu ładu korporacyjnego (Dz. Urz. UE L 2024/1619 z 19.06.2024), Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/2994 z dnia 27 listopada 2024 r. zmieniającej dyrektywy 2009/65/WE, 2013/36/UE i (UE) 2019/2034 w odniesieniu do sposobu traktowania ryzyka koncentracji z tytułu ekspozycji wobec kontrahentów centralnych i ryzyka kontrahenta w przypadku rozliczanych centralnie transakcji na instrumentach pochodnych (Dz. Urz. UE L 2024/2994 z 04.12.2024);","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-06-20","document_date":"2026-05-20","change_date":"2026-09-29T00:00:00Z","eu_related":true,"rcl_num":"RM-0610-76-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12399111","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"1. Zgłoszenia lobbingowe","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-01-08","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komi