INSERT INTO "bills" VALUES(10,'RCL/12393951','Projekt ustawy o zmianie niektórych ustaw w związku z przekazywaniem informacji do europejskiego pojedynczego punktu dostępu','2026-09-29T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12393951","title":"Projekt ustawy o zmianie niektórych ustaw w związku z przekazywaniem informacji do europejskiego pojedynczego punktu dostępu","description":"INSTRUMENTY FINANSOWE; INFORMACJA FINANSOWA; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2023/2864 z dnia 13 grudnia 2023 r. zmieniająca niektóre dyrektywy w odniesieniu do ustanowienia i działania europejskiego pojedynczego punktu dostępu Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/790 z dnia 28 lutego 2024 r. zmieniająca dyrektywę 2014/65/UE w sprawie rynków instrumentów finansowych Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2023/2859 w sprawie ustanowienia europejskiego pojedynczego punktu dostępu zapewniającego scentralizowany dostęp do publicznie dostępnych informacji mających znaczenie dla usług finansowych, rynków kapitałowych i zrównoważonego rozwoju Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2023/2869 z dnia 13 grudnia 2023 r. zmieniające niektóre rozporządzenia w odniesieniu do ustanowienia i działania europejskiego pojedynczego punktu dostępu Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/791 z dnia 28 lutego 2024 r. zmieniające rozporządzenie (UE) nr 600/2014 w odniesieniu do zwiększenia przejrzystości danych, usuwania przeszkód w powstawaniu systemów publikacji informacji skonsolidowanych, optymalizacji obowiązków obrotu oraz zakazu otrzymywania płatności za przepływ zleceń","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-01-28","document_date":"2026-01-07","change_date":"2026-09-29T00:00:00Z","eu_related":true,"rcl_num":"RM-0610-241-25","rcl_link":"https://legislacja.rcl.gov.pl/projekt/123