INSERT INTO "bills" VALUES(10,'3150','Rządowy projekt ustawy budżetowej na rok 2027','2026-10-09T12:27:07+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:migracja", "text:azyl", "text:uchodzcy", "text:repatriacja", "text:obywatelstwo", "text:obywatele_ukrainy", "text:pobyt_kwalifikowany", "text:legalizacja", "text:karta_polaka", "text:straz_graniczna", "text:granica_panstwowa", "text:ochrona_miedzynarodowa", "text:status_uchodzcy", "text:nierezydenci"]','{"term":10,"number":"3150","title":"Rządowy projekt ustawy budżetowej na rok 2027","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-10-09T12:27:07Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3150","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-08","committee_code":"FPB","sub_committee":false,"children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-08","sub_committee":false,"voting":{"yes":198,"no":237,"abstain":5,"not_participating":20,"sitting":66,"voting_number":161,"date":"2026-10-08T19:39:31Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/66/161/pdf","clubs":[]},"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3150","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-08","committee_code":"FPB","sub_committee":false,"committee_name":"Komisja Finansów Publicznych","children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-08","sub_committee":false,"voting":{"yes":198,"no":237,"abstain":5,"not_participating":20,"sitting":66,"voting_number":161,"date":"2026-10-08T19:39:31Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/66/161/pdf","clubs":[]},"children":[]}]}]','ead66f52fae65f1d644e573bb68b33d253b45d4e042e4a82dc2d76dcf9e802f7','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект государственного бюджета Польши на 2027 год: доходы, расходы, дефицит и распределение средств по ведомствам. Новых правил для иностранцев закон не вводит — они затронуты лишь косвенно через финансирование UdSC, помощи иностранцам, Karta Polaka и репатриации.","key_changes":["Доходы бюджета — 696,4 млрд зл., расходы — 977,6 млрд зл., дефицит не более 281,2 млрд зл.","На Urząd do Spraw Cudzoziemców (UdSC) запланировано около 108,1 млн зл.","Помощь иностранцам (раздел 85231): около 175,2 млн зл. в MSWiA и около 33 млн зл. у воевод","Резервы: 55 млн зл. на задачи по ustawa o Karcie Polaka и 70,2 млн зл. на помощь репатриантам","1 млрд зл. перечисляется в Fundusz Pomocy; 125 млн зл. — на строительство и модернизацию пограничных переходов"],"affected_groups":["лица, обращающиеся в UdSC","иностранцы, получающие социальную помощь (статус беженца, дополнительная защита, толерированное пребывание, жертвы торговли людьми)","владельцы Karty Polaka","репатрианты"],"practical_impact":"Прямых изменений в правилах пребывания, работы или выплат для иностранцев нет; бюджет лишь определяет объём финансирования ведомств и программ, с которыми они имеют дело.","effective_date":"Закон вступает в силу 1 января 2027 г.","confidence":0.8,"rationale":"Бюджетный закон не меняет правовой статус иностранцев, а лишь упоминает статьи расходов на UdSC, помощь иностранцам и Karta Polaka, поэтому влияние маргинальное.","changes_since_previous":[]},"model":"claude-opus-5-5","prompt_version":"2026-09-v9","input_chars":1486063,"truncated":false,"text_source":"pdf","created_at":"2026-09-30T23:02:33Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3150/3150-ustawa%20i%20za%C5%82%C4%85czniki%20do%20ustawy.pdf","source_kind":"print","revision":2,"text_sha256":"b08a12f8480a1d44f3caea9f9368f76fb6e0fc7b12743f659880de25e65b948a","law_sha256":"c2134ccc99f5138a749d2764233d4203940e9d1d141f202d69478566f89a2363","source_checked_at":"2026-09-30T23:02:33Z"}',0,NULL,'2026-09-30T11:14:20+00:00','2026-10-28T19:18:50+00:00','{"term":10,"number":"RPW/32733/2026","title":"Rządowy projekt ustawy budżetowej na rok 2027","description":null,"applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-29","print_number":"3150","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/32733/2026',NULL,NULL,NULL,'[{"kind": "committee", "ref": "FPB/349/2026-11-05+12:00+sala im. Konstytucji 3-go Maja (nr 118, bud. C)", "date": "2026-11-05", "end_date": null, "start_time": "12:00:00", "committee_code": "FPB", "committee_name": "Komisja Finansów Publicznych", "sitting_number": 349, "room": "sala im. Konstytucji 3-go Maja (nr 118, bud. C)", "text": "Rozpatrzenie rządowego projektu ustawy budżetowej na rok 2027 (druk nr 3150) w zakresie części 