INSERT INTO "bills" VALUES(10,'3153','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi','2026-10-23T08:13:01+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3153","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"projekt dotyczy zapewnienia komplementarności finansowania interwencji medycznych (w tym świadczeń zdrowotnych)  zaplanowanych w ramach programu polityki zdrowotnej oraz doprecyzowania przepisów ustawy o zapobieganiu i zwalczaniu zakażeń i chorób zakaźnych u ludzi w zakresie finansowania świadczeń opieki zdrowotnej niezbędnych do realizacji programu polityki zdrowotnej leczenia antyretrowirusowego osób żyjących z wirusem HIV","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-12","document_date":"2026-06-11","change_date":"2026-10-23T08:13:01Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["3143"]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-30T11:14:21+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/20264/2026","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi","description":"zapewnienia komplementarności finansowania interwencji medycznych (w tym świadczeń zdrowotnych)  zaplanowanych w ramach programu polityki zdrowotnej oraz doprecyzowania przepisów ustawy o zapobieganiu i zwalczaniu zakażeń i chorób zakaźnych u ludzi w zakresie finansowania świadczeń opieki zdrowotnej niezbędnych do realizacji programu polityki zdrowotnej leczenia antyretrowirusowego osób żyjących z wirusem HIV","applicant":"president","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-06-12","print_number":"3153","eu_related":false,"public_consultation":true,"consultation_start":"2026-07-16","consultation_end":"2026-08-15","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3154','Rządowy projekt ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2027','2026-10-09T12:28:05+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3154","title":"Rządowy projekt ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2027","description":"projekt dotyczy zabezpieczenia środków w formie pożyczki z budżetu państwa dla Polskiej Agencji Żeglugi Powietrznej do kwoty 1,5 mld zł., ponadto w 2027 r. Fundusz Inwestycji Kapitałowych będzie mógł dysponować skarbowymi papierami wartościowymi. Stworzono podstawę prawną do przekazania dotacji dla Centrum Obsługi Administracji Rządowej, aby podnieść odporność cyfrową jednostki. Zabezpieczone zostały środki na realizację programu wieloletniego pod nazwą Program Wzmocnienia Krajowej Sieci Drogowej do 2030 roku.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-10-09T12:28:05Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-173-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-173-26","prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3154","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','2b06ecb2762f284c17fede0fc937fa4fb1bd25713f273f769e9795edea371a4e',NULL,0,'text prefilter: no keyword hits','2026-09-30T11:14:21+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/32720/2026","title":"Rządowy projekt ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2027","description":"zabezpieczenia środków w formie pożyczki z budżetu państwa dla Polskiej Agencji Żeglugi Powietrznej do kwoty 1,5 mld zł., ponadto w 2027 r. Fundusz Inwestycji Kapitałowych będzie mógł dysponować skarbowymi papierami wartościowymi. Stworzono podstawę prawną do przekazania dotacji dla Centrum Obsługi Administracji Rządowej, aby podnieść odporność cyfrową jednostki. Zabezpieczone zostały środki na realizację programu wieloletniego pod nazwą Program Wzmocnienia Krajowej Sieci Drogowej do 2030 roku.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-29","print_number":"3154","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/32720/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3154","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3155','Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym','2026-10-28T11:14:33+00:00','2026-10-22',1,'skipped_text_prefilter','["text:pobyt_kwalifikowany"]','{"term":10,"number":"3155","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym","description":"projekt dotyczy zwiększenia skuteczności poboru opłaty od środków spożywczych (tzw. opłaty cukrowej) przez rozszerzenie katalogu napojów objętych opłatą oraz aktualizację jej wysokości. Projektowane zmiany umożliwią również zwiększenie przychodów Narodowego Funduszu Zdrowia, które zostaną przeznaczone na działania edukacyjne i profilaktyczne oraz na finansowanie świadczeń opieki zdrowotnej, w szczególności w zakresie leczenia chorób związanych z nieprawidłowymi\nnawykami żywieniowymi, takich jak nadwaga i otyłość.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-29","document_date":"2026-09-29","change_date":"2026-10-28T11:14:33Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-166-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-166-26","prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3155","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','785c6cb2e9d6a80793020e75a8f8c33dd2ef33d0a1be7885cf01d5358b630f01',NULL,0,'text prefilter: under the threshold of 2 distinct patterns (pobyt_kwalifikowany×1)','2026-09-30T11:14:23+00:00','2026-10-29T19:00:06+00:00','{"term":10,"number":"RPW/32721/2026","title":"Rządowy projekt ustawy o zmianie ustawy o zdrowiu publicznym","description":"zwiększenia skuteczności poboru opłaty od środków spożywczych (tzw. opłaty cukrowej) przez rozszerzenie katalogu napojów objętych opłatą oraz aktualizację jej wysokości. Projektowane zmiany umożliwią również zwiększenie przychodów Narodowego Funduszu Zdrowia, które zostaną przeznaczone na działania edukacyjne i profilaktyczne oraz na finansowanie świadczeń opieki zdrowotnej, w szczególności w zakresie leczenia chorób związanych z nieprawidłowymi\nnawykami żywieniowymi, takich jak nadwaga i otyłość.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-29","print_number":"3155","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/32721/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-29","print_number":"3155","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"Sejm","sub_committee":false,"children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
