,"facts":[{"kind":"official_link","value":"rcl/12398102/stage/13129966","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","text_sha256":"f8b3149402ed547503a7465d32b087439decb8c6f1fcb3f7b535e568cabadec9","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","text_sha256":"f8b3149402ed547503a7465d32b087439decb8c6f1fcb3f7b535e568cabadec9","block_id":"part:0","start":0,"end":795,"quote":"Projekt z dnia 14 października 2026 r. \nUstawa\nz dnia ………..…….. 2026 r.\no zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw [przypis 2: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 5 grudnia 1996 r. o zawodach lekarza i lekarza dentysty, ustawę z dnia 6 września 2001 r. – Prawo farmaceutyczne, ustawę z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, ustawę z dnia 25 sierpnia 2006 r. o bezpieczeństwie żywności i żywienia, ustawę z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia, ustawę z dnia 15 lipca 2011 r. o zawodach pielęgniarki i położnej oraz ustawę z dnia 7 października 2020 r. o Funduszu Medycznym. ] )\nArt. 1"},{"kind":"draft_date","value":"2026-10-14","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip","text_sha256":"f8b3149402ed547503a7465d32b087439decb8c6f1fcb3f7b535e568cabadec9","block_id":"part:0","start":0,"end":35,"quote":"Projekt z dnia 14 października 2026"}],"limitations":["annex_link_unknown","support_applicability_unknown","missing_evidence"],"links":[{"kind":"supporting","source_part":1,"target_part":0,"status":"unknown","evidence":[