INSERT INTO "bills" VALUES(10,'RCL/12385851','Projekt ustawy o zmianie ustawy – Kodeks cywilny oraz ustawy – Kodeks postępowania cywilnego','2026-10-23T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:straz_graniczna", "text:granica_panstwowa"]','{"term":10,"number":"RCL/12385851","title":"Projekt ustawy o zmianie ustawy – Kodeks cywilny oraz ustawy – Kodeks postępowania cywilnego","description":"CYWILNE POSTĘPOWANIE; CYWILNE PRAWO; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-06-05","document_date":"2026-09-30","change_date":"2026-10-23T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12385851","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2025-11-06","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","date":"2025-11-06","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","date":"2025-11-06","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','8fcc0aa86b55ca396543d743243fe6b6aea212060ae9ccc3df0bb5f73ec37243',NULL,0,'text prefilter: weak patterns only (straz_graniczna×9, granica_panstwowa×9)','2026-09-30T11:15:17+00:00','2026-10-23T17:54:41+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12385851,"title":"Projekt ustawy o zmianie ustawy – Kodeks cywilny oraz ustawy – Kodeks postępowania cywilnego","applicant":"Minister Sprawiedliwości","wykaz_number":"UD30","wykaz_url":"https://www.gov.pl/web/sprawiedliwosc/a-projekty","created":"2024-06-05","modified":"2026-09-30","departments":["sprawiedliwość"],"keywords":["CYWILNE POSTĘPOWANIE","CYWILNE PRAWO"],"status":"otwarty","term_label":"X","stages"