INSERT INTO "bills" VALUES(10,'3157','Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw','2026-10-23T08:06:30+00:00','2026-10-22',1,'analyzed','["text:migracja", "text:obywatelstwo", "text:przekraczanie_granicy"]','{"term":10,"number":"3157","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"projekt dotyczy uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-28","document_date":"2026-09-28","change_date":"2026-10-23T08:06:30Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-160-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-160-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-28","print_number":"3157","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"ZDR","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-07","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-07","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-07","print_number":"3193","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":9,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-20","sitting_num":67,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"ZDR","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3193-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3157/attachment/3157_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":229,"no":144,"abstain":67,"not_participating":20,"sitting":67,"voting_number":149,"date":"2026-10-22T16:45:08Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/149/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"title_final":"o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-28","print_number":"3157","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-30","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-30","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-07","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-10-07","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-07","print_number":"3193","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":9,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-20","sitting_num":67,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"ZDR","sub_committee":false,"committee_name":"Komisja Zdrowia","children":[]}]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-10-21","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-10-21","print_number":"3193-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf","proposal":"przyjąć część poprawek","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3157/attachment/3157_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":229,"no":144,"abstain":67,"not_participating":20,"sitting":67,"voting_number":149,"date":"2026-10-22T16:45:08Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/149/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','cf85347cc358f9d07e063ff8e58ce6654ca6d83a91cb2fd2a48067b71d0ef034','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Закон усиливает контроль NFZ над больницами и ограничивает время работы и максимальные ставки оплаты для врачей и медперсонала, работающих по контрактам NFZ. Вводится прямое право пациента на равное отношение и запрет дискриминации, в т.ч. по гражданству и национальности, а также реестр врачей, лишённых права работать за счёт NFZ.","key_changes":["В закон о правах пациента вводится право на равное обращение и запрет дискриминации, в т.ч. по гражданству","Медучреждения обязаны активно предотвращать дискриминацию пациентов по перечисленным признакам","Создаётся публичный реестр врачей с запретом на работу по контрактам NFZ и правила информирования пациентов","Ужесточается контроль NFZ и Agencja HTA: доступ к меддокументации, новые обязанности по передаче данных","Вводятся лимиты общего рабочего времени и максимального дохода медиков по контрактам NFZ, с обязанностью деклараций"],"affected_groups":["иностранцы‑пациенты, пользующиеся NFZ","иностранные врачи и другой медперсонал, работающие в Польше","медучреждения и частные практики с контрактами NFZ"],"practical_impact":"Иностранец‑пациент получает прямое право на недискриминацию из‑за гражданства и может жаловаться в Rzecznik Praw Pacjenta (омбудсмен по правам пациента). Иностранные медики должны вписаться в лимиты часов и оплаты по NFZ и правдиво декларировать занятость, иначе возможны штрафы и расторжение договоров.","effective_date":"Через месяц после опубликования, кроме ст. 1 п. 19, п. 25 (в части ст. 132ad) и п. 28 (в части ст. 193 ч. 1 п. 15–16 и распространения ч. 2 на эти пункты), ст. 2, ст. 3 п. 2–5 и ст. 4, которые вступают в силу через 6 месяцев после опубликования.","confidence":0.95,"rationale":"Закон прямо вводит право пациента на недискриминацию по гражданству и др. признакам и существенно меняет правила работы медиков в системе NFZ, что затрагивает как иностранных пациентов, так и иностранных врачей в социальной сфере.","mnemonic_candidate":"Антидискриминация пациентов","mnemonic_fallback":"Равное лечение пациентов","mnemonic_basis":"В ustawa o prawach pacjenta i Rzeczniku Praw Pacjenta добавлен art. 8a с правом на равное обращение и прямым запретом дискриминации, в т.ч. по obywatelstwo и narodowość.","mnemonic_language":"ru","changes_since_previous":["Подробно введён механизм запрета NFZ для врачей (zakaz udzielania świadczeń) с публичным реестром и обменом данными с ZUS.","Пациент получил право на информацию о таком запрете у лечащего врача и введены крупные штрафы для учреждений за его сокрытие.","Расширены обязанности клиник ежедневно проверять реестр запретов и хранить доказательства такой проверки.","Конкретизированы лимиты совокупного рабочего времени и максимального дохода медиков по контрактам NFZ, с жёсткими последствиями за превышение.","Добавлены новые составы правонарушений и штрафы до 30 000 zł за работу под запретом и нарушение новых лимитов и обязанностей.","Установлен 6‑месячный переходный период на приведение действующих договоров и правил оплаты труда медиков в соответствие новым требованиям."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":75147,"truncated":false,"text_source":"pdf","created_at":"2026-10-27T17:30:26Z","computation_id":"result-v1:184f3d2e1a51b254cce761e69ab3ab3aa0a118601f3c0ea9569d23c374e85297","request_sha256":"c5813beb590fdb03b3a24f26d6f2fe41064c7c93e1b735b45e7b118abf5efe05","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_ur