INSERT INTO "bills" VALUES(10,'3159','Rządowy projekt ustawy o wsparciu przedsiębiorców sektorów energochłonnych z tytułu ponoszenia kosztów energii elektrycznej','2026-10-28T11:15:34+00:00','2026-10-22',1,'skipped_text_prefilter','[]','{"term":10,"number":"3159","title":"Rządowy projekt ustawy o wsparciu przedsiębiorców sektorów energochłonnych z tytułu ponoszenia kosztów energii elektrycznej","description":"projekt dotyczy wprowadzenia programu wsparcia dla przedsiębiorstw energochłonnych, który pozwoli czasowo obniżyć koszty energii elektrycznej. Firmy korzystające z pomocy będą jednocześnie zobowiązane do inwestowania w zieloną transformację, czyli m.in. w odnawialne źródła energii, magazyny energii, poprawę efektywności energetycznej i elektryfikację. Źródłem finansowania mają być m.in. dodatkowe wpływy z czasowego podwyższenia podatku CIT dla największych firm z wybranych segmentów sektora energetycznego i paliwowego.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-30","document_date":"2026-09-30","change_date":"2026-10-28T11:15:34Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-168-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-168-26","prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-10-01T18:56:06+00:00','2026-10-29T19:00:06+00:00','{"term":10,"number":"RPW/32907/2026","title":"Rządowy projekt ustawy o wsparciu przedsiębiorców sektorów energochłonnych z tytułu ponoszenia kosztów energii elektrycznej","description":"wprowadzenia programu wsparcia dla przedsiębiorstw energochłonnych, który pozwoli czasowo obniżyć koszty energii elektrycznej. Firmy korzystające z pomocy będą jednocześnie zobowiązane do inwestowania w zieloną transformację, czyli m.in. w odnawialne źródła energii, magazyny energii, poprawę efektywności energetycznej i elektryfikację. Źródłem finansowania mają być m.in. dodatkowe wpływy z czasowego podwyższenia podatku CIT dla największych firm z wybranych segmentów sektora energetycznego i paliwowego.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-30","print_number":"3159","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3160','Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw','2026-10-28T11:16:44+00:00','2026-10-22',1,'analyzed','["text:cudzoziemcy", "text:nieruchomosci_cudzoziemcy", "text:praca_sezonowa"]','{"term":10,"number":"3160","title":"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw","description":"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-01","document_date":"2026-10-01","change_date":"2026-10-28T11:16:44Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-169-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-01","print_number":"3160","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-10-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-01","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-08","sitting_num":66,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-08","committee_code":"GOR","sub_c