omisji","stage_type":"CommitteeReport","date":"2026-10-22","print_number":"3243-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3243-A/3243-A.pdf","proposal":"odrzucić poprawki","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-10-22","sitting_num":67,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-10-22","sub_committee":false,"voting":{"yes":231,"no":6,"abstain":200,"not_participating":23,"sitting":67,"voting_number":124,"date":"2026-10-22T16:29:14Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/67/124/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-10-27","position":"nie wniósł poprawek","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-10-28","sub_committee":false,"children":[]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','3a5d7f4d8aafaccfc0f1a9348e0c219f258debf37a948728b5558fa838b6abf1','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект обновляет систему налоговых льгот и процедур для инвестиций в рамках Польской инвестиционной зоны (PSI) и переводит подачу заявок в электронный вид. Одновременно отменяется ст. 3a в законе о покупке недвижимости иностранцами, что изменит условия таких сделок.","key_changes":["Отменяется ст. 3a в законе о покупке недвижимости иностранцами.","Налоговая льгота PSI чётко привязана к указанной в решении деятельности и территории.","Освобождение от налога по PSI начинается после окончания инвестпроекта или начала затрат на новые рабочие места.","Заявления, жалобы и переписка по PSI подаются только через электронное индивидуальное konto.","Крупные решения о поддержке (от 40 млн zł помощи) требуют мнения Шефа KAS."],"affected_groups":["иностранцы, покупающие недвижимость в Польше","иностранные инвесторы, пользующиеся поддержкой PSI","иностранные владельцы и со‑владельцы польских компаний в PSI"],"practical_impact":"Покупка недвижимости иностранцами будет регулироваться без ст. 3a, что приведёт к изменению части требований или процедуры сделок. Иностранные инвесторы в PSI столкнутся с новыми правилами расчёта налоговой льготы и обязательной электронной подачей всех документов.","effective_date":"Закон вступает в силу 1 января 2027 г., при этом ст. 2 (отмена ст. 3a) начинает действовать с 31 декабря 2027 г.","confidence":0.83,"rationale":"Акт прямо меняет закон о покупке недвижимости иностранцами и режим налоговых льгот для инвестиций, что затрагивает интересы нерезидентов, но не регулирует их пребывание или гражданство.","mnemonic_candidate":"Сделка без 3a","mnemonic_fallback":"Отмена статьи 3a","mnemonic_basis":"Текст проекта прямо предусматривает отмену статьи 3a в ustawa o nabywaniu nieruchomości przez cudzoziemców, влияя на правила сделок с недвижимостью для иностранцев.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":47274,"truncated":false,"text_source":"pdf","created_at":"2026-10-23T18:21:01Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf","source_kind":"text_after3","revision":4,"text_sha256":"text-v2:2375b8cb3b541819ef76d7a4084c995b7914bfa2c37751a3d0c839f3e9c75f52","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf","members":[],"container_sha256":"63d00e254ea123a05cc9e5577836450de6c1e61c8a579c71