INSERT INTO "bills" VALUES(10,'RCL/12399355','Projekt ustawy o środkach ograniczających','2026-10-02T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:obywatelstwo", "text:straz_graniczna", "text:schengen", "text:nieruchomosci_cudzoziemcy", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12399355","title":"Projekt ustawy o środkach ograniczających","description":"UNIA EUROPEJSKA; sprawy zagraniczne. Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/1226 z dnia 24 kwietnia 2024 r. w sprawie określenia przestępstw związanych z naruszeniem unijnych środków ograniczających i sankcji za takie naruszenia oraz zmiany dyrektywy (UE) 2018/1673 (Dz. Urz. UE. L. z 2024 r. poz. 1226)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-06-27","document_date":"2026-08-03","change_date":"2026-10-02T00:00:00Z","eu_related":true,"rcl_num":"RM-0610-126-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12399355","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-03-09","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','2bbc64e27b7009fa310ca174dc716525c50f5af65aaf9a361d5b248de009023b','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит общую систему санкций в Польше и национальный санкционный список. Для иностранцев: попадание в этот список автоматически ведёт к признанию пребывания нежелательным и запрету въезда, с возможными исключениями по решению UdSC.","key_changes":["Создаётся единый национальный санкционный список лиц и компаний","Для лиц из списка можно вводить запрет въезда и пребывания в Польше","В \"ustawa o cudzoziemcach\" добавляется новая причина внесения в реестр нежелательных иностранцев","Szef UdSC получает полномочия применять и смягчать санкции по въезду/пребыванию","Для работников фирм под санкциями вводится защита зарплат через FGŚP"],"affected_groups":["иностранцы, внесённые в национальный санкционный список","граждане ЕС и члены их семей, на которых распространяются санкции","иностранные работники компаний, чьи активы заморожены","иностранные предприниматели, работающие с государствами под санкциями"],"practical_impact":"Если иностранец попадёт в польский санкционный список, его данные автоматически вносятся в реестр лиц с нежелательным пребыванием, что блокирует выдачу виз и разрешений и может повлечь отказ во въезде. При этом UdSC сможет в отдельных случаях дать исключение из запрета на въезд/пребывание.","effective_date":"Уступает в силу через 30 дней со дня опубликования, за исключением art. 73, который вступает в силу через 6 месяцев со дня опубликования.","confidence":0.89,"rationale":"Проект комплексно регулирует санкции и прямо меняет \"ustawa o cudzoziemcach\", добавляя новые основания для запрета въезда и пребывания и полномочия UdSC, что существенно влияет на правовой статус иностранцев (категория legal_stay, значимость 5).","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-09-v9","input_chars":372343,"truncated":false,"text_source":"documents","created_at":"2026-10-02T14:56:36Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12399355/13139730/13139731/dokument790400.zip","source_kind":"rcl","revision":1,"text_sha256":"3d562527af94da07b7b1946ed4fab8c29d6e1552cdbe8fc618cf4ea4799d3ae3","law_sha256":"5109dc4580dc43d8ce730232ab10e106d20ef8e88d779125a2d919e46bac5402","source_checked_at":"2026-10-02T14:56:36Z"}',0,NULL,'2026-10-02T14:32:22+00:00','2026-10-02T14:32:22+00:00',NULL,'3003',NULL,NULL,NULL,NULL,'{"id":12399355,"title":"Projekt ustawy o środkach ograniczających","applicant":"Minister Spraw Zagranicznych","wykaz_number":"UC92","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2025-06-27","modified":"2026-10-02","departments":["sprawy zagraniczne"],"keywords":["UNIA EUROPEJSKA"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/1226 z dnia 24 kwietnia 2024 r. w sprawie określenia przestępstw związanych z naruszeniem unijnych środków ograniczających i sankcji za takie naruszenia oraz zmiany dyrektywy (UE) 2018/1673 (Dz. Urz. UE. L. z 2024 r. poz. 1226)","term_label":"X","rm_number":"RM-0610-126-26","sejm_url":"http://www.sejm.gov.pl/Sejm7.nsf/agent.xsp?symbol=RPL&Id=RM-0610-126-26","print_number":"3003","stages":[{"id":13139681,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13139682,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-03-06","folders":[],"catalog_read":false},{"id":13139688,"number":3,"name":"Konsultacje publiczne","state":"reached","modified":"2026-03-06","folders":[{"id":13139689,"name":"Projekt","modified":"2025-06-27","documents":[{"id":724539,"name":"2. UZASADNIENIE ustawa sankcyjna_2025_6_26.doc","url":"https://legislacja.rcl.gov.pl/docs//2/12399355/13139688/13139689/dokument724539.doc","created":"2025-06-27","author":"Minister Spraw Zagranicznych"},{"id":724540,"name":"3. OSR ustawa sankcyjna_2025_6_26.doc","url":"https://legislacja.