INSERT INTO "bills" VALUES(10,'2697','Rządowy projekt ustawy o ochronie małoletnich przed dostępem do treści pornograficznych w internecie','2026-06-17T09:19:40+00:00',NULL,0,'analyzed','["text:uchodzcy", "text:obywatele_innych_panstw"]','{"term":10,"number":"2697","title":"Rządowy projekt ustawy o ochronie małoletnich przed dostępem do treści pornograficznych w internecie","description":"projekt dotyczy zwiększenia bezpieczeństwa dzieci w internecie i ograniczenia ich dostępu do treści pornograficznych poprzez nałożenie obowiązku na dostawców usług cyfrowych, aby skuteczniej weryfikować wiek użytkowników i chronić niepełnoletnich przed szkodliwymi treściami i ma na celu zmniejszenie ryzyka kontaktu dzieci i młodzieży z pornografią w sieci oraz wzmocnienie ochrony ich zdrowia psychicznego i prawidłowego rozwoju","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-06-17T09:19:40Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-86-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-86-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2697","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"DIM","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"CNT","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-01","sub_committee":false,"children":[]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2697","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"DIM","sub_committee":false,"committee_name":"Komisja do Spraw Dzieci i Młodzieży","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"CNT","sub_committee":false,"committee_name":"Komisja Cyfryzacji, Innowacyjności i Nowoczesnych Technologii","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-07-01","sub_committee":false,"children":[]}]','21134c626db87c8b5b09a001fbfdad2a5784d3af879b88200fb886c2d7b92c1d','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается защиты несовершеннолетних от порнографического контента в интернете и обязанностей поставщиков услуг, не затрагивая правового статуса, пребывания или прав иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается защиты несовершеннолетних от порнографического контента в интернете и обязанностей поставщиков услуг, не затрагивая правового статуса, пребывания или прав иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v9","input_chars":11323,"truncated":true,"text_source":"excerpts","created_at":"2026-10-02T14:33:37Z","input_tokens":6547,"output_tokens":99,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-10-02T14:36:06+00:00','2026-10-28T19:18:42+00:00',NULL,'RCL/12394953',NULL,NULL,NULL,NULL,NULL,NULL,'UD179',NULL,'["2697-001", "2697-002"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2697","sub_committee":fa