INSERT INTO "bills" VALUES(10,'RCL/12390757','Ustawa o wyrobach zawierających azbest','2026-10-21T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12390757","title":"Ustawa o wyrobach zawierających azbest","description":"AZBEST; gospodarka. Numer i tytuł aktu prawnego Unii Europejskiej: 1) Dyrektywa Parlamentu Europejskiego i Rady (UE) 2023/2668 z dnia 22 listopada 2023 r. w sprawie zmiany dyrektywy 2009/148/WE w sprawie ochrony pracowników przed ryzykiem związanym z narażeniem na działanie azbestu w miejscu pracy (Dz. Urz. UE L 2023/2668 z 30.11.2023), 2) Dyrektywa Parlamentu Europejskiego i Rady 2009/148/WE z dnia 30 listopada 2009 r. w sprawie ochrony pracowników przed ryzykiem związanym z narażeniem na działanie azbestu w miejscu pracy (wersja ujednolicona) (Dz. Urz. UE L 330 z 16.12.2009, str. 28 oraz Dz. Urz. L 198 z 25.07.2019, str. 241), 3) Dyrektywa Rady 87/217/EWG z dnia 19 marca 1987 r. w sprawie ograniczania zanieczyszczenia środowiska azbestem i zapobiegania temu zanieczyszczeniu (Dz. Urz. WE L 85 z 28.3.1987, s. 40 – Dz. Urz. UE Polskie wydanie specjalne, rozdz. 13, t. 8, str. 269, Dz. Urz. WE L 377 z 31.12.1991, str. 48 – Dz. Urz. UE Polskie wydanie specjalne, rozdz. 5, t. 2, str. 10, Dz. Urz. WE C 241 z 29.08.1994, str. 9, Dz. Urz. UE L 122 z 16.05.2003, str. 36 – Dz. Urz. UE Polskie wydanie specjalne, rozdz. 1, t. 4, str. 335 oraz Dz. Urz. UE L 150 z 14.06.2018, str. 155).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-10-22","document_date":"2026-04-08","change_date":"2026-10-21T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12390757","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_