INSERT INTO "bills" VALUES(10,'3184','Obywatelski projekt ustawy o zmianie ustawy - Prawo łowieckie oraz niektórych innych ustaw','2026-10-12T08:26:55+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3184","title":"Obywatelski projekt ustawy o zmianie ustawy - Prawo łowieckie oraz niektórych innych ustaw","description":"projekt dotyczy zmiany modelu prawnej regulacji łowiectwa poprzez zwiększenie bezpieczeństwa społecznego w związku z prowadzonymi polowaniami; zwiększenie udziału społeczeństwa w decydowaniu o kształcie i sposobie wykonywania gospodarki łowieckiej; ograniczenia wpływu myśliwych na kształt gospodarki łowieckiej i wprowadzenia kontroli organów ochrony przyrody","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-17","document_date":"2026-09-03","change_date":"2026-10-12T08:26:55Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3184","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-17","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"Sejm","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3184","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-17","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','04e49ce8fd890ade80643b00acd432cf2bf0f823907b21a1a2f3484d68c56158','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается изменения Закона об охоте (Prawo łowieckie) — регулирует охоту, планы охотничьих хозяйств и охрану природы, не затрагивая статус, пребывание или права иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается изменения Закона об охоте (Prawo łowieckie) — регулирует охоту, планы охотничьих хозяйств и охрану природы, не затрагивая статус, пребывание или права иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-17T19:46:27Z","input_tokens":13923,"output_tokens":105,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-10-06T19:01:58+00:00','2026-10-28T19:18:51+00:00','{"term":10,"number":"RPW/29629/2026","title":"Obywatelski projekt ustawy o zmianie ustawy - Prawo łowieckie oraz niektórych innych ustaw","description":"zmiany modelu prawnej regulacji łowiectwa poprzez zwiększenie bezpieczeństwa społecznego w związku z prowadzonymi polowaniami; zwiększenie udziału społeczeństwa w decydowaniu o kształcie i sposobie wykonywania gospodarki łowieckiej; ograniczenia wpływu myśliwych na kształt gospodarki łowieckiej i wprowadzenia kontroli organów ochrony przyrody","applicant":"citizens","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-17","print_number":"3184","eu_related":false,"public_consultation":true,"consultation_start":"2026-09-18","consultation_end":"2026-10-18","consultation_results":false,"withdrawn_date":null}','RPW/29629/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["3184-002", "3184-003", "3184-004", "3184-005", "3184-006"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3184","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-17","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"Sejm","sub_committee":false,"children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":["3184-002","3184-003","3184-004","3184-005","3184-006"]}',1,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3172','Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska','2026-10-20T09:00:18+00:00',NULL,0,'analyzed','["text:migracja", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"3172","title":"Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"projekt dotyczy wyłączenia dzwonów kościelnych spod restrykcyjnych limitów hałasu, przypisując im status podobny do infrastruktury transportowej (np. linii tramwajowych czy kolejowych), dla których tradycyjne pomiary hałasu przemysłowego nie mają zastosowania w ten sam sposób","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-17","document_date":"2026-09-17","change_date":"2026-10-20T09:00:18Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3172","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"OSZ","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3172","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"OSZ","sub_committee":false,"committee_name":"Komisja Ochrony Środowiska, Zasobów Naturalnych i Leśnictwa","children":[]}]}]','14f46fc837f46ccb624520a1dd3e36319a8d1315b566818684f8fc741b936bd8','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет Prawo ochrony środowiska (закон об охране окружающей среды): звук колоколов и звукоусиливающих систем религиозного культа выводится из-под норм шума и решений о допустимом уровне шума. Для иностранцев никаких правовых последствий нет.","key_changes":["Исключение систем нагłaśniających религиозного культа из решений о допустимом уровне шума (art. 115a ust. 2)","Запрет на использование звукоусиливающих устройств в общественных местах не применяется к практике религиозного культа (art. 156 ust. 2)"],"affected_groups":["приходы и религиозные общины","жители домов рядом с храмами"],"practical_impact":"Ничего не меняется в вопросах пребывания, работы или социальных прав иностранцев; изменение касается только шума от религиозных объектов.","effective_date":"Через 14 дней после публикации.","confidence":0.95,"rationale":"Тема — шум от церковных колоколов; иностранцы упомянуты лишь риторически в обосновании, правовых последствий для них нет.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":18591,"truncated":false,"text_source":"pdf","created_at":"2026-09-17T19:46:37Z","input_tokens":9214,"output_tokens":408,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31346-2026/$file/10-RPW-31346-2026.pdf","source_kind":"print","revision":1,"text_sha256":"cd7a7425e388f5525a3ab2097f03939e9d5e158eb9092f2cdc2bf31741cfead3","law_sha256":null,"source_checked_at":"2026-09-17T19:46:37Z"}',0,NULL,'2026-10-06T19:01:58+00:00','2026-10-28T19:18:50+00:00','{"term":10,"number":"RPW/31346/2026","title":"Poselski projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"wyłączenia dzwonów kościelnych spod restrykcyjnych limitów hałasu, przypisując im status podobny do infrastruktury transportowej (np. linii tramwajowych czy kolejowych), dla których tradycyjne pomiary hałasu przemysłowego nie mają zastosowania w ten sam sposób","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-17","print_number":"3172","eu_related":false,"public_consultation":true,"consultation_start":"2026-09-18","consultation_end":"2026-10-18","consultation_results":false,"withdrawn_date":null}','RPW/31346/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["3172-001"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-17","print_number":"3172","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-24","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"OSZ","sub_committee":false,"committee_name":"Komisja Ochrony Środowiska, Zasobów Naturalnych i Leśnictwa","children":[]}]}],"passed":false,"document":{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-31346-2026/$file/10-RPW-31346-2026.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"cd7a7425e388f5525a3ab2097f03939e9d5e158eb9092f2cdc2bf31741cfead3","analysis_revision":1,"seen_supplements":["3172-001"]}',1,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
