INSERT INTO "bills" VALUES(10,'3176','Poselski projekt ustawy o zmianie ustawy - Prawo komunikacji elektronicznej','2026-10-06T09:30:09+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3176","title":"Poselski projekt ustawy o zmianie ustawy - Prawo komunikacji elektronicznej","description":"projekt dotyczy wprowadzenia obowiązku udostępniania przez przedsiębiorców telekomunikacyjnych sektorowi płatniczemu informacji o zwalnianych numerach telefonu (projektowany art. 396a). Obowiązek ten powstanie, jeżeli przy wykonywaniu transakcji płatniczych w ramach usługi płatniczej świadczonej przez dostawcę usług\npłatniczych albo schematu płatniczego prowadzonego przez organizację płatniczą będzie wykorzystywany unikatowy identyfikator powiązany z numerem telefonu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-19","document_date":"2026-06-19","change_date":"2026-10-06T09:30:09Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-19","print_number":"3176","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"CNT","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-23","sub_committee":false,"children":[]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-19","print_number":"3176","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"CNT","sub_committee":false,"committee_name":"Komisja Cyfryzacji, Innowacyjności i Nowoczesnych Technologii","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-23","sub_committee":false,"children":[]}]','245ae86e998adc52897ceb9097b322f50f9b6a83674d1bd0ca37b99818a54dca','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается исключительно обязанности операторов связи предоставлять поставщикам платёжных услуг данные об освобождённых номерах телефонов для предотвращения ошибочных переводов «на телефон», и никак не затрагивает иностранцев, их пребывание, работу или документы.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается исключительно обязанности операторов связи предоставлять поставщикам платёжных услуг данные об освобождённых номерах телефонов для предотвращения ошибочных переводов «на телефон», и никак не затрагивает иностранцев, их пребывание, работу или документы.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-10-07T19:24:45Z","input_tokens":21791,"output_tokens":129,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-10-07T07:19:24+00:00','2026-10-28T19:18:50+00:00','{"term":10,"number":"RPW/21178/2026","title":"Poselski projekt ustawy o zmianie ustawy - Prawo komunikacji elektronicznej","description":"wprowadzenia obowiązku udostępniania przez przedsiębiorców telekomunikacyjnych sektorowi płatniczemu informacji o zwalnianych numerach telefonu (projektowany art. 396a). Obowiązek ten powstanie, jeżeli przy wykonywaniu transakcji płatniczych w ramach usługi płatniczej świadczonej przez dostawcę usług\npłatniczych albo schematu płatniczego prowadzonego przez organizację płatniczą będzie wykorzystywany unikatowy identyfikator powiązany z numerem telefonu.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-06-19","print_number":"3176","eu_related":false,"public_consultation":true,"consultation_start":"2026-06-29","consultation_end":"2026-07-29","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":"Michał Gramatyka","representative_club":"Polska2050","clubs":[["Polska2050",12],["Razem",4],["niez.",4],["Demokracja",2],["PSL-TD",2],["PiS",2],["Konfederacja",1],["RozwojPlus",1]],"signatories":28,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,'["3176-001", "3176-002"]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-19","print_number":"3176","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-06","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-06","committee_code":"CNT","sub_committee":false,"committee_name":"Komisja Cyfryzacji, Innowacyjności i Nowoczesnych Technologii","children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-10-23","sub_committee":false,"children":[]}],"passed":false,"analysis_revision":1,"seen_supplements":["3176-001","3176-002"]}',1,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
