INSERT INTO "bills" VALUES(10,'RPW/33663/2026','Poselski projekt ustawy o zmianie ustawy - Kodeks karny','2026-10-07T00:00:00+00:00',NULL,NULL,'linked','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/33663/2026","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks karny","description":"rozszerzenia i doprecyzowania zakresu odpowiedzialności karnej za nadużycia związane z wykorzystaniem technik cyfrowych, w szczególności sztucznej inteligencji do produkcji treści o charakterze pornograficznym, a także używanych w celu pokrzywdzenia indywidualnych osób prezentowanych w sytuacjach intymnych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-07","document_date":"2026-10-07","change_date":"2026-10-07T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-10-07T19:23:37+00:00','2026-10-09T07:28:41+00:00','{"term":10,"number":"RPW/33663/2026","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks karny","description":"rozszerzenia i doprecyzowania zakresu odpowiedzialności karnej za nadużycia związane z wykorzystaniem technik cyfrowych, w szczególności sztucznej inteligencji do produkcji treści o charakterze pornograficznym, a także używanych w celu pokrzywdzenia indywidualnych osób prezentowanych w sytuacjach intymnych","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-07","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-10-08","consultation_end":"2026-11-07","consultation_results":false,"withdrawn_date":null,"senders_number":null}','3268',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
