INSERT INTO "bills" VALUES(10,'RCL/12408952','Projekt ustawy o zmianie ustawy – Prawo konsularne oraz niektórych innych ustaw','2026-10-07T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:wizy", "text:legalizacja", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12408952","title":"Projekt ustawy o zmianie ustawy – Prawo konsularne oraz niektórych innych ustaw","description":"KONSULARNE PRAWO; sprawy zagraniczne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-07","document_date":"2026-10-07","change_date":"2026-10-07T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12408952","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','001397c25223b452241e49fcbebd2d6c8a5b613c271c50f0bfec61e826798378','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект меняет консульское право и визовые процедуры. Запускается онлайн‑система ePUK для связи с консулом и оплат, часть операций отдадут визовым центрам. Нацвизы для докторантов, исследователей и стипендиатов будут рассматривать приоритетно.","key_changes":["Создаётся система ePUK для подачи заявлений к консулу и получения ответов онлайн","Запись на приём и часть визовых процедур можно передавать визовым центрам за плату","При онлайн‑записи на нацвизу консул/центр временно обрабатывает биометрию и все данные из паспорта","Нацвизы с приоритетом для докторантов, исследователей, стипендиатов NAWA и программ ЕС","Консул подтверждает profil zaufany только гражданам Польши, ЕС и ЕАСТ"],"affected_groups":["иностранцы, подающие на польскую национальную визу","иностранные студенты, докторанты, исследователи и стипендиаты NAWA","иностранцы, пользующиеся услугами консульств Польши за рубежом"],"practical_impact":"Часть контактов с консулом и оплат можно будет делать через ePUK или визовый центр, но возможны дополнительные сборы и сбор биометрии уже при записи. Для выбранных студентов и исследователей нацвизы должны рассматривать быстрее, а большинству иностранцев консул больше не подтвердит profil zaufany.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования, кроме: норм о квалификации консулов — через 3 месяца; норм о реестре NAWA — через 6 месяцев; положений о системе ePUK — в день, указанный в официальном сообщении министра иностранных дел.","confidence":0.9,"rationale":"Проект прямо меняет ustawę o cudzoziemcach и визовые процедуры, поэтому это важные изменения правил выдачи виз и доступа к пребыванию (категория legal_stay, высокий приоритет).","mnemonic_candidate":"Консульский ePUK","mnemonic_fallback":"Электронные услуги консула","mnemonic_basis":"Проект вводит Elektroniczną Platformę Usług Konsularnych (System ePUK) для электронного ведения дел с консулом, включая визовые обращения и оплаты.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":228592,"truncated":false,"text_source":"documents","created_at":"2026-10-17T09:07:43Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","source_kind":"rcl","revision":2,"text_sha256":"text-v2:559c3fe3f4c4aae96220072d090e61bf3acb2495023ea00be621419d24f0aa74","selection":{"question":"bill_text","state":"selected","belonging":[],"role":[],"version":["rcl/12408952/stage/13196550","projekt UPK III.pdf"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","members":[],"container_sha256":"bf3d56cf5e8cb011dd81f1bd54924e82390627aa98339e014dbc88df10dd798a","sha256":"bf3d56cf5e8cb011dd81f1bd54924e82390627aa98339e014db