INSERT INTO "bills" VALUES(10,'RPW/33787/2026','Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym oraz niektórych innych ustaw','2026-10-08T00:00:00+00:00',NULL,NULL,'linked','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/33787/2026","title":"Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym oraz niektórych innych ustaw","description":"wprowadzenia jednolitych zapisów zakazujących łączenia funkcji radnych gminnych, powiatowych oraz wojewódzkich z członkostwem w organie wykonawczym jednostek pomocniczych dzielnic m.st. Warszawy","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-08T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-10-08T17:29:30+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/33787/2026","title":"Poselski projekt ustawy o zmianie ustawy o samorządzie gminnym oraz niektórych innych ustaw","description":"wprowadzenia niepołączalności mandatu radnego gminy, powiatu i województwa z członkostwem w organie wykonawczym jednostek pomocniczych (dzielnic) m.st. Warszawy","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-08","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-10-09","consultation_end":"2026-11-08","consultation_results":false,"withdrawn_date":null,"senders_number":null}','3269',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3205','Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych','2026-10-23T08:02:23+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:migracja", "text:obywatelstwo", "text:obywatele_ukrainy", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"3205","title":"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych","description":"projekt dotyczy wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-18","document_date":"2026-09-18","change_date":"2026-10-23T08:02:23Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-18","print_number":"3205","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"PSR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-18","print_number":"3205","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}]','473f0724b67a7f1a15aa97fbfa3bd6ecbce8229809c82f4e3b132eeeb218242b','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект ужесточает условия доплаты пенсии до минимальной из ZUS: помимо возраста и стажа потребуется накопить на пенсионном счёте взносы не ниже 25-кратного минимального вознаграждения (в 2026 г. — около 120 150 zł). Формально касается всех, но по обоснованию нацелен на иностранцев с коротким стажем работы в Польше.","key_changes":["Новое условие в art. 87 ust. 1 ustawy o emeryturach i rentach z FUS для доплаты до минимальной пенсии","Требуется валоризованная сумма взносов на счёте не ниже 25-кратного минимального вознаграждения (~120 150 zł в 2026 г.)","Условия возраста (65/60 лет) и стажа (25/20 лет) сохраняются","Новые правила применяются и к делам, начатым, но не завершённым до вступления в силу","Цель обоснования — ограничить доплаты лицам с минимальным стажем работы в Польше"],"affected_groups":["Иностранцы, работавшие в Польше и получающие пенсию из ZUS","Граждане Украины и других стран с договорами о социальном обеспечении с Польшей","Лица с коротким периодом уплаты взносов в Польше","Граждане Польши с низкими накоплениями в ZUS"],"practical_impact":"Если сумма взносов на счёте в ZUS ниже указанного порога, доплата до минимальной пенсии не будет назначена, даже при достаточном общем стаже с учётом периодов работы за границей. Это касается и заявлений, поданных до вступления закона в силу, но ещё не рассмотренных.","effective_date":"Через 14 дней со дня опубликования","confidence":0.9,"rationale":"Проект напрямую влияет на социальные выплаты (пенсии) иностранцам, работавшим в Польше, но не затрагивает легализацию пребывания или работу.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":38308,"truncated":false,"text_source":"pdf","created_at":"2026-09-18T19:08:16Z","input_tokens":20036,"output_tokens":700,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3205/3205.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:4abee9811eff6947d721e858763a885f13f24a4695205ca3d47af330d8ae24cf","law_sha256":"law-v2:3198311dc715b17383e0ca232f3b80f6c1e87c1a624af2f0653b2347f289e9f9","source_checked_at":"2026-10-09T07:44:09Z"}',0,NULL,'2026-10-08T17:29:48+00:00','2026-10-28T19:18:36+00:00','{"term":10,"number":"RPW/31544/2026","title":"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych","description":"wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-18","print_number":"3205","eu_related":false,"public_consultation":true,"consultation_start":"2026-09-21","consultation_end":"2026-10-21","consultation_results":true,"withdrawn_date":null,"senders_number":null}','RPW/31544/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-18","print_number":"3205","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3205/3205.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"text-v2:4abee9811eff6947d721e858763a885f13f24a4695205ca3d47af330d8ae24cf","analysis_revision":1,"seen_supplements":[]}',3,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Барьер доплаты ZUS","language":"ru","basis":"Проект вводит высокий порог накопленных взносов для получения доплаты пенсии до минимальной из ZUS, что особенно затронет иностранцев с коротким стажем работы в Польше.","selected_at":"2026-10-22T08:26:57Z","origin":"backfill","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":1}',NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3204','Poselski projekt ustawy o zmianie ustawy o osłonach socjalnych dla pracowników sektora elektroenergetycznego i branży górnictwa węgla brunatnego','2026-10-23T08:07:09+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3204","title":"Poselski projekt ustawy o zmianie ustawy o osłonach socjalnych dla pracowników sektora elektroenergetycznego i branży górnictwa węgla brunatnego","description":"projekt dotyczy doprecyzowania sposobu monitorowania zmian stanu zatrudnienia przez Zarządcę Rozliczeń wskazując zakres informacji, o które może on występować do Zakładu Ubezpieczeń Społecznych tak, aby  z jednej strony ograniczyć do niezbędnego minimum zakres przekazywania informacji, a z drugiej zapewnić jej precyzyjność i jednoznaczność w procesie monitoringu poprzez powiązanie jej z rzeczywistym poziomem wykorzystania środków przez beneficjentów","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-18","document_date":"2026-09-18","change_date":"2026-10-23T08:07:09Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-18","print_number":"3204","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"ESK","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-18","print_number":"3204","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"ESK","sub_committee":false,"committee_name":"Komisja do Spraw Energii, Klimatu i Aktywów Państwowych","children":[]}]}]','fff4e8dbd929e31546f0c059f9df54ece01061131dc59dd0e4fe9ce52ddaf984','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается технических изменений в системе социальной защиты работников энергетического сектора и буроугольной отрасли Польши (мониторинг занятости и финансирование дотаций ZUS) и не затрагивает права, обязанности или процедуры, касающиеся иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается технических изменений в системе социальной защиты работников энергетического сектора и буроугольной отрасли Польши (мониторинг занятости и финансирование дотаций ZUS) и не затрагивает права, обязанности или процедуры, касающиеся иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-10-03T14:30:05Z","input_tokens":15618,"output_tokens":126,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-10-08T17:29:52+00:00','2026-10-28T19:18:51+00:00','{"term":10,"number":"RPW/31567/2026","title":"Poselski projekt ustawy o zmianie ustawy o osłonach socjalnych dla pracowników sektora elektroenergetycznego i branży górnictwa węgla brunatnego","description":"doprecyzowania sposobu monitorowania zmian stanu zatrudnienia przez Zarządcę Rozliczeń wskazując zakres informacji, o które może on występować do Zakładu Ubezpieczeń Społecznych tak, aby  z jednej strony ograniczyć do niezbędnego minimum zakres przekazywania informacji, a z drugiej zapewnić jej precyzyjność i jednoznaczność w procesie monitoringu poprzez powiązanie jej z rzeczywistym poziomem wykorzystania środków przez beneficjentów","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-18","print_number":"3204","eu_related":false,"public_consultation":true,"consultation_start":"2026-09-22","consultation_end":"2026-10-22","consultation_results":false,"withdrawn_date":null}','RPW/31567/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-18","print_number":"3204","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"ESK","sub_committee":false,"committee_name":"Komisja do Spraw Energii, Klimatu i Aktywów Państwowych","children":[]}]}],"passed":false,"analysis_revision":1,"seen_supplements":[]}',1,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'3206','Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe','2026-10-23T08:11:46+00:00',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3206","title":"Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe","description":"projekt dotyczy rozszerzenia katalogu źródeł dochodów wydzielonego rachunku, obejmując nim odpłatne udostępnianie mienia, odpłatne świadczenie usług przy jego wykorzystaniu, sprzedaż rzeczy wytworzonych oraz wprowadza warunki dopuszczalności tj. zakaz  ograniczenia zadań statutowych oraz wymóg ustalania wynagrodzenia na poziomie nie niższym niż suma kosztów a także  uchyla obowiązek odprowadzania środków na koniec roku budżetowego i utrzymuje limit wydatków do wysokości środków zgromadzonych na rachunku i nakłada obowiązek wyodrębnionej ewidencji księgowej oraz rocznej informacji dla organu wykonawczego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-22","document_date":"2026-09-22","change_date":"2026-10-23T08:11:46Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-22","print_number":"3206","sub_committee":false,"children":[]}]','99de3c9f6d25faff9b5ed9c24b2db4ec91dd83be9915fdc6c31a945883805225',NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-10-08T17:29:53+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/31837/2026","title":"Poselski projekt ustawy o zmianie ustawy o finansach publicznych oraz ustawy - Prawo oświatowe","description":"rozszerzenia katalogu źródeł dochodów wydzielonego rachunku, obejmując nim odpłatne udostępnianie mienia, odpłatne świadczenie usług przy jego wykorzystaniu, sprzedaż rzeczy wytworzonych oraz wprowadza warunki dopuszczalności tj. zakaz  ograniczenia zadań statutowych oraz wymóg ustalania wynagrodzenia na poziomie nie niższym niż suma kosztów a także  uchyla obowiązek odprowadzania środków na koniec roku budżetowego i utrzymuje limit wydatków do wysokości środków zgromadzonych na rachunku i nakłada obowiązek wyodrębnionej ewidencji księgowej oraz rocznej informacji dla organu wykonawczego","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-22","print_number":"3206","eu_related":false,"public_consultation":true,"consultation_start":"2026-09-23","consultation_end":"2026-10-23","consultation_results":false,"withdrawn_date":null}','RPW/31837/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-22","print_number":"3206","sub_committee":false,"children":[]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RPW/33928/2026','Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce','2026-10-08T00:00:00+00:00',NULL,NULL,'linked','["text:legalizacja"]','{"term":10,"number":"RPW/33928/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce","description":"wprowadzenia możliwości potwierdzenia przez uczelnię danych zawartych w wydanym w postaci papierowej dyplomie ukończenia studiów, jeśli pracodawca ma uzasadnione wątpliwości co do ich prawdziwości. Dzięki zmianom pracodawcy zyskają narzędzie, które pozwoli sprawdzić, czy informacje przedstawione przez kandydata do pracy lub pracownika są zgodne z dokumentacją uczelni. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-08T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,'text prefilter: weak patterns only (legalizacja×2)','2026-10-08T19:18:52+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/33928/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce","description":"wprowadzenia możliwości potwierdzenia przez uczelnię danych zawartych w wydanym w postaci papierowej dyplomie ukończenia studiów, jeśli pracodawca ma uzasadnione wątpliwości co do ich prawdziwości. Dzięki zmianom pracodawcy zyskają narzędzie, które pozwoli sprawdzić, czy informacje przedstawione przez kandydata do pracy lub pracownika są zgodne z dokumentacją uczelni. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-08","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','3232',NULL,NULL,NULL,NULL,NULL