INSERT INTO "bills" VALUES(10,'RPW/33930/2026','Rządowy projekt ustawy o uregulowaniu praw do niektórych gruntów znajdujących się we władaniu spółdzielni mieszkaniowych','2026-10-08T00:00:00+00:00',NULL,NULL,'linked','[]','{"term":10,"number":"RPW/33930/2026","title":"Rządowy projekt ustawy o uregulowaniu praw do niektórych gruntów znajdujących się we władaniu spółdzielni mieszkaniowych","description":"rozwiązania problemu gruntów, z których spółdzielnie mieszkaniowe korzystają od wielu lat, ale nie mają do nich trwałego tytułu prawnego. Nowe przepisy mają umożliwić przyznanie spółdzielniom praw do takich nieruchomości.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-08T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-10-09T07:28:41+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/33930/2026","title":"Rządowy projekt ustawy o uregulowaniu praw do niektórych gruntów znajdujących się we władaniu spółdzielni mieszkaniowych","description":"rozwiązania problemu gruntów, z których spółdzielnie mieszkaniowe korzystają od wielu lat, ale nie mają do nich trwałego tytułu prawnego. Nowe przepisy mają umożliwić przyznanie spółdzielniom praw do takich nieruchomości.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-08","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','3233',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RPW/33929/2026','Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw','2026-10-08T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:obcokrajowcy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany"]','{"term":10,"number":"RPW/33929/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw","description":"zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-08T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,'{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.","key_changes":["Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией","Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии","Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS","Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу","Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты"],"affected_groups":["иностранные докторанты польских школ докторантских","иностранцы, завершившие обучение в школе докторантской и готовящие защиту","вузы и научные учреждения, ведущие школы докторантские с иностранцами"],"practical_impact":"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.","effective_date":"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.","confidence":0.93,"rationale":"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":68211,"truncated":false,"text_source":"pdf","created_at":"2026-10-09T07:38:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-33929-2026/$file/10-RPW-33929-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:671110a797f75f62e946bcd580fb507f4f591a40dec42fc59e7874e69a5abde7","law_sha256":"law-v2:8c9f289a9c507825256be59e5306e676356ecd300e9c57646c1ece5096ee9060","source_checked_at":"2026-10-09T07:38:31Z"}',0,NULL,'2026-10-09T07:28:41+00:00','2026-10-10T12:46:19+00:00','{"term":10,"number":"RPW/33929/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw","description":"zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-08","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','3231',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'full','telegram_thread',NULL,NULL,NULL,NULL,NULL,NULL);
