INSERT INTO "bills" VALUES(10,'3175','Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym oraz niektórych innych ustaw','2026-10-20T09:05:50+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3175","title":"Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym oraz niektórych innych ustaw","description":"projekt dotyczy ograniczenia ryzyka powstania luki inwestycyjnej związanej z wdrażaniem reformy planowania przestrzennego, a także ułatwienia realizacji inwestycji mieszkaniowych na własne potrzeby oraz inwestycji w ramach zabudowy zagrodowej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-04","document_date":"2026-09-04","change_date":"2026-10-20T09:05:50Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-04","print_number":"3175","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-14","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"STR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"INF","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-04","print_number":"3175","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2026-09-14","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"STR","sub_committee":false,"committee_name":"Komisja Samorządu Terytorialnego i Polityki Regionalnej","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]}]}]','0dc02ecff7a7fd2c38580291ee3508d08b1e2f52b8a45fb5c3d1ab9efb835154','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается планирования и застройки территорий (условия застройки, зонирование, сельская застройка) и не затрагивает статус, пребывание или права иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Законопроект касается планирования и застройки территорий (условия застройки, зонирование, сельская застройка) и не затрагивает статус, пребывание или права иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-10-v10","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-10-12T21:48:12Z","input_tokens":13903,"output_tokens":88,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":null}',0,NULL,'2026-10-12T21:46:29+00:00','2026-10-28T19:18:50+00:00','{"term":10,"number":"RPW/29813/2026","title":"Poselski projekt ustawy o zmianie ustawy o planowaniu i zagospodarowaniu przestrzennym oraz niektórych innych ustaw","description":"ograniczenia ryzyka powstania luki inwestycyjnej związanej z wdrażaniem reformy planowania przestrzennego, a także ułatwienia realizacji inwestycji mieszkaniowych na własne potrzeby oraz inwestycji w ramach zabudowy zagrodowej","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-04","print_number":"3175","eu_related":false,"public_consultation":true,"consultation_start