.gov.pl/sejm/term10/prints/2257/2257.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-03-11","sitting_num":53,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-03-11","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-03-11","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-03-11","print_number":"2257-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2257-A/2257-A.pdf","proposal":"odrzucić wniosek o odrzucenie","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-03-13","sitting_num":53,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/1884/attachment/1884_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-03-13","sub_committee":false,"voting":{"yes":231,"no":180,"abstain":18,"not_participating":31,"sitting":53,"voting_number":68,"date":"2026-03-13T10:53:47Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/53/68/pdf","clubs":[]},"children":[]}]},{"stage_name":"Stanowisko Senatu","stage_type":"SenatePosition","date":"2026-04-08","print_number":"2400","position":"wniósł poprawki","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-09","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Praca w komisjach nad stanowiskiem Senatu","stage_type":"CommitteeWork","date":"2026-04-14","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-04-14","print_number":"2405","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2405/2405.pdf","proposal":"przyjąć poprawki","sub_committee":false,"minority_motions":0,"children":[]}]},{"stage_name":"Rozpatrywanie na forum Sejmu stanowiska Senatu","stage_type":"SenatePositionConsideration","date":"2026-04-17","sitting_num":55,"decision":"przyjęto poprawki","sub_committee":false,"children":[]},{"stage_name":"Ustawę przekazano Prezydentowi do podpisu","stage_type":"ToPresident","date":"2026-04-20","sub_committee":false,"children":[]},{"stage_name":"Wniosek Prezydenta (weto)","stage_type":"Veto","date":"2026-05-11","print_number":"2548","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-05-12","committee_code":"ASW","sub_committee":false,"committee_name":"Komisja Administracji i Spraw Wewnętrznych","children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}],"closure_date":"2026-04-17","passed":true,"analysis_revision":1,"seen_supplements":["1884-001","1884-002","1884-003","1884-004","1884-005","1884-006","1884-007","1884-008"]}',1,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,'[]');
INSERT INTO "bills" VALUES(10,'WPL/UD488','Projekt ustawy o zmianie ustawy - Prawo lotnicze','2026-10-13T12:14:00+00:00',NULL,NULL,'analyzed','["ochrona_miedzynarodowa"]','{"term":10,"number":"WPL/UD488","title":"Projekt ustawy o zmianie ustawy - Prawo lotnicze","description":"Projekt wprowadza zmiany w ustawie z dnia 3 lipca 2002 r. – Prawo lotnicze (Dz. U. z 2025 r. poz. 1431, z późn. zm.), zwanej dalej „ustawą”, mające na celu usprawnienie wykonywania zadań i procedur realizowanych na podstawie ustawy oraz podniesienie poziomu bezpieczeństwa w lotnictwie cywilnym, w szczególności: \n1)\tUtworzenie w miejsce istniejącej jednej Rady Ochrony i Ułatwień Lotnictwa Cywilnego dwóch rad: Rady Ochrony Lotnictwa Cywilnego oraz Rady Ułatwień Lotnictwa Cywilnego, w celu rozłączenia w ramach działalności opiniodawczo-doradczej tematyki ochrony i tematyki ułatwień w lotnictwie cywilnym, co ułatwi zabezpieczanie informacji dotyczących ochrony lotnictwa oraz zapraszanie do udziału w posiedzeniach organu zajmującego się ułatwieniami większej liczby podmiotów. Zmiana ta pociąga za sobą zmiany w zakresie zadań Prezesa Urzędu Lotnictwa Cywilnego dotyczące przedkładania tym organom do zaopiniowania Krajowego Programu Ochrony Lotnictwa Cywilnego i Krajowego Programu Ułatwień Lotnictwa Cywilnego.\n2)\tWprowadzenie przepisów dotyczących dokonywania przez Prezesa Urzędu Lotnictwa Cywilnego przeglądu, zmiany oraz zatwierdzenia klasyfikacji zdarzeń lotniczych pod względem ryzyka dla bezpieczeństwa, zgodnie ze wspólną europejską klasyfikacją ryzyka, o której mowa w art. 7 ust. 2  rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 376/2014 z dnia 3  kwietnia 2014 r. w sprawie zgłaszania i analizy zdarzeń w lotnictwie cywilnym oraz podejmowanych w związku z nimi działań następczych, zmiany rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 996/2020 oraz uchylenia dyrektywy 2003/42/WE Parlamentu Europejskiego i Rady i rozporządzeń Komisji (WE) nr 1321/2007 i (WE) nr 1330/2007 (Dz. Urz. UE L 122 z 24.04.2014, str. 18, z późn. zm.), zwanego dalej „rozporządzeniem nr 376/2014/UE”.\n3)\tWpisanie w zadania Prezesa Urzędu Lotnictwa Cywilnego zadań dotyczących podejmowania działań zapobiegawczych lub naprawczych oraz informowania pracowników Urzędu Lotnictwa Cywilnego i personelu kontraktowego Urzędu Lotnictwa Cywilnego, o których mowa w art. 16 ust. 9 rozporządzenia nr 376/2014/UE, o sposobie zgłaszania domniemanego naruszenia zasady just culture.\n4)\tDoprecyzowanie przepisów dotyczących zapewnienia bezpieczeństwa w przestrzeni powietrznej w przypadkach emisji lasera lub światła z innych źródeł oraz wypuszczania w przestrzeń powietrzną innych obiektów, a także zmianę przepisów karnych za naruszenie norm w tym zakresie.\n5)\tDoprecyzowanie terminu zgłaszania zdarzeń lotniczych.\n6)\tZmianę kompetencji organów w zakresie wznawiania badania przez Państwową Komisję Badania Wypadków Lotniczych, zwaną dalej „Komisją”, oraz przekazywania raportów końcowych i uchwał Komisji.\n7)\tWprowadzenie ustawowego umocowania dla opracowania Krajowego Programu Bezpieczeństwa Lotniczego (ang. State Safety Programme – SSP), zwanego dalej „KPBL”,  w tym Krajowego Planu Bezpieczeństwa, oraz jego szerokich konsultacji z udziałem innych organów kompetentnych w sprawach lotnictwa, tj. m.in. z organami, którym podlega lotnictwo wojskowe, państwowe, służby poszukiwania i ratownictwa lotniczego oraz służby informacji meteorologicznej dla lotnictwa.\n8)\tNałożenie na podmioty obowiązane na podstawie przepisów prawa Unii Europejskiej, przepisów międzynarodowych lub przepisów krajowych do wdrożenia zintegrowanego systemu zarządzania lub systemu zarządzania bezpieczeństwem obowiązku wdrożenia wskaźników poziomu bezpieczeństwa określonych w Krajowym Planie Bezpieczeństwa oraz obowiązku przekazania Prezesowi Urzędu Lotnictwa Cywilnego wartości wskaźników poziomu bezpieczeństwa określone w Krajowym Planie Bezpieczeństwa, we wskazanych w nim odstępach czasowych.\n9)\tUchylenie obowiązujących przepisów odnoszących się do certyfikatu członka załogi (CMC).\n10)\tZmianę zasad opracowania Krajowego Programu Ułatwień Lotnictwa Cywilnego, o którym mowa w Załączniku 9 Konwencji o międzynarodowym lotnictwie cywilnym, sporządzonej w Chicago dnia 7 grudnia 1944 r. (Dz. U. z 1959 r. poz. 212 i 214, z późn. zm.), zwanej dalej „Konwencją”.\n11)\tDodanie administracyjnej kary pieniężnej w zakresie składania sprawozdań z wykonywania operacji lotniczych.\n\nZmiana art. 19 ustawy (art. 1 pkt 1 projektu ustawy)\nDziałająca obecnie Rada Ochrony i Ułatwień Lotnictwa Cywilnego zajmuje się zagadnieniami dotyczącymi jednocześnie ochrony i ułatwień w lotnictwie cywilnym, co powoduje, że zakres zagadnień będących przedmiotem działalności Rady jest zbyt szeroki i nie powinien być łączony ze względu na potrzebę ochrony informacji oraz zapewnienia udziału w organie zajmującym się ułatwieniami większej liczbie podmiotów, zarówno w charakterze członków jak i gości zapraszanych na posiedzenia. Konieczność rozłączenia w ramach działalności opiniodawczo-doradczej tematyki ochrony i tematyki ułatwień w lotnictwie cywilnym wynika z zaleceń zawartych w Załączniku 17 do Konwencji, który dotyczy ochrony międzynarodowego lotnictwa cywilnego przed aktami bezprawnej ingerencji. Zgodnie z zaleceniem zawartym w punkcie 2.1.4 Załącznika 17 do Konwencji „Każde Umawiające się Państwo powinno zapewnić odpowiednie zabezpieczenie informacji dotyczących ochrony lotnictwa.”. Stąd prowadzenie działalności opiniodawczo-doradczej w ramach jednej rady zajmującej się zarówno zagadnieniami ochrony, jak i ułatwień w lotnictwie cywilnym nastręcza trudności związane z koniecznością wyłączania niektórych zagadnień dotyczących ochrony w lotnictwie cywilnym z omawiania na posiedzeniu całej Rady. Zmiana ułatwi również zapraszanie na posiedzenia organu zajmującego się ułatwieniami większej liczby gości i ekspertów, bez konieczności specjalnego organizowania posiedzeń w celu ochrony informacji. Uzasadnione jest zatem utworzenie dwóch odrębnych rad, które formalnie osobno będą się zajmować sprawami dotyczącymi ochrony i sprawami dotyczącymi ułatwień w lotnictwie cywilnym, co nie wyklucza przepływu informacji między radami w razie potrzeby. \nW wyniku projektowanych zmian w miejsce istniejącej jednej Rady Ochrony i","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-13","document_date":"2026-10-13","change_date":"2026-10-13T12:14:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}','[]','c7afdb27125a2372efbbc6e73848030e65bc3240da1b02c66bf199d51cbd144b','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет закон «Право авиационное», чтобы улучшить работу органов гражданской авиации и повысить уровень безопасности полётов. Речь идёт о новых советах по защите и удобству в авиации, правилах отчётности о происшествиях и штрафах.","key_changes":["Разделение существующей Рады на две: по защите и по упрощениям в авиации","Новые правила классификации авиационных происшествий по уровню риска","Закрепление задач ULC по системе just culture и сообщениям о её нарушениях","Уточнение правил и санкций за лазеры, свет и другие объекты в воздушном пространстве","Введение админштрафа за несдачу отчётов по авиационным операциям"],"affected_groups":["Авиакомпании, выполняющие рейсы в/из Польши","Польские аэропорты и наземные службы","Лётный и технический персонал гражданской авиации"],"practical_impact":"Для обычных пассажиров, в том числе иностранцев, изменения выражаются главным образом в повышении стандартов безопасности и внутренней организации авиации, без отдельных специальных правил для иностранцев.","effective_date":null,"confidence":0.71,"rationale":"Проект системно обновляет организацию и безопасность гражданской авиации, но не вводит особых норм именно для иностранцев, поэтому влияние на иностранцев как группу отсутствует.","mnemonic_candidate":"Двойной авиационный совет","mnemonic_fallback":"Реформа совета по авиации","mnemonic_basis":"Проект расформировывает одну Раду Охраны и Упрощений и создаёт две отдельные – по защите и по упрощениям в гражданской авиации.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v11","input_chars":0,"truncated":false,"text_source":"metadata_only","created_at":"2026-10-13T20:31:49Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":null,"source_kind":"metadata","revision":1,"text_sha256":null,"law_sha256":null,"source_checked_at":"2026-10-13T20:31:49Z"}',0,NULL,'2026-10-13T19:54:09+00:00','2026-10-13T19:54:09+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"number":"UD488","title":"Projekt ustawy o zmianie ustawy - Prawo lotnicze","kind":"Projekty ustaw","doc_type":"D – pozostałe projekty","goals":"Projekt wprowadza zmiany w ustawie z dnia 3 lipca 2002 r. – Prawo lotnicze (Dz. U. z 2025 r. poz. 1431, z późn. zm.), zwanej dalej „ustawą”, mające na celu usprawnienie wykonywania zadań i procedur realizowanych na podstawie ustawy oraz podniesienie poziomu bezpieczeństwa w lotnictwie cywilnym, w szczególności: \n1)\tUtworzenie w miejsce istniejącej jednej Rady Ochrony i Ułatwień Lotnictwa Cywilnego dwóch rad: Rady Ochrony Lotnictwa Cywilnego oraz Rady Ułatwień Lotnictwa Cywilnego, w celu rozłączenia w ramach działalności opiniodawczo-doradczej tematyki ochrony i tematyki ułatwień w lotnictwie cywilnym, co ułatwi zabezpieczanie informacji dotyczących ochrony lotnictwa oraz zapraszanie do udziału w posiedzeniach organu zajmującego się ułatwieniami większej liczby podmiotów. Zmiana ta pociąga za sobą zmiany w zakresie zadań Prezesa Urzędu Lotnictwa Cywilnego dotyczące przedkładania tym organom do zaopiniowania Krajowego Programu Ochrony Lotnictwa Cywilnego i Krajowego Programu Ułatwień Lotnictwa Cywilnego.\n2)\tWprowadzenie przepisów dotyczących dokonywania przez Prezesa Urzędu Lotnictwa Cywilnego przeglądu, zmiany oraz zatwierdzenia klasyfikacji zdarzeń lotniczych pod względem ryzyka dla bezpieczeństwa, zgodnie ze wspólną europejską klasyfikacją ryzyka, o której mowa w art. 7 ust. 2  rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 376/2014 z dnia 3  kwietnia 2014 r. w sprawie zgłaszania i analizy zdarzeń w lotnictwie cywilnym oraz podejmowanych w związku z nimi działań następczych, zmiany rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 996/2020 oraz uchylenia dyrektywy 2003/42/WE Parlamentu Europejskiego i Rady i rozporządzeń Komisji (WE) nr 1321/2007 i (WE) nr 1330/2007 (Dz. Urz. UE L 122 z 24.04.2014, str. 18, z późn. zm.), zwanego dalej „rozporządzeniem nr 376/2014/UE”.\n3)\tWpisanie w zadania Prezesa Urzędu Lotnictwa Cywilnego zadań dotyczących podejmowania działań zapobiegawczych lub naprawczych oraz informowania pracowników Urzędu Lotnictwa Cywilnego i personelu kontraktowego Urzędu Lotnictwa Cywilnego, o których mowa w art. 16 ust. 9 rozporządzenia nr 376/2014/UE, o sposobie zgłaszania domniemanego naruszenia zasady just culture.\n4)\tDoprecyzowanie przepisów dotyczących zapewnienia bezpieczeństwa w przestrzeni powietrznej w przypadkach emisji lasera lub światła z innych źródeł oraz wypuszczania w przestrzeń powietrzną innych obiektów, a także zmianę przepisów karnych za naruszenie norm w tym zakresie.\n5)\tDoprecyzowanie terminu zgłaszania zdarzeń lotniczych.\n6)\tZmianę kompetencji organów w zakresie wznawiania badania przez Państwową Komisję Badania Wypadków Lotniczych, zwaną dalej „Komisją”, oraz przekazywania raportów końcowych i uchwał Komisji.\n7)\tWprowadzenie ustawowego umocowania dla opracowania Krajowego Programu Bezpieczeństwa Lotniczego (ang. State Safety Programme – SSP), zwanego dalej „KPBL”,  w tym Krajowego Planu Bezpieczeństwa, oraz jego szerokich konsultacji z udziałem innych organów kompetentnych w sprawach lotnictwa, tj. m.in. z organami, którym podlega lotnictwo wojskowe, państwowe, służby poszukiwania i ratownictwa lotniczego oraz służby informacji meteorologicznej dla lotnictwa.\n8)\tNałożenie na podmioty obowiązane na podstawie przepisów prawa Unii Europejskiej, przepisów międzynarodowych lub przepisów krajowych do wdrożenia zintegrowanego systemu zarządzania lub systemu zarządzania bezpieczeństwem obowiązku wdrożenia wskaźników poziomu bezpieczeństwa określonych w Krajowym Planie Bezpieczeństwa oraz obowiązku przekazania Prezesowi Urzędu Lotnictwa Cywilnego wartości wskaźników poziomu bezpieczeństwa określone w Krajowym Planie Bezpieczeństwa, we wskazanych w nim odstępach czasowych.\n9)\tUchylenie obowiązujących przepisów odnoszących się do certyfikatu członka załogi (CMC).\n10)\tZmianę zasad opracowania Krajowego Programu Ułatwień Lotnictwa Cywilnego, o którym mowa w Załączniku 9 Konwencji o międzynarodowym lotnictwie cywilnym, sporządzonej w Chicago dnia 7 grudnia 1944 r. (Dz. U. z 1959 r. poz. 212 i 214, z późn. zm.), zwanej dalej „Konwencją”.\n11)\tDodanie administracyjnej kary pieniężnej w zakresie składania sprawozdań z wykonywania operacji lotniczych.","essence":"Zmiana art. 19 ustawy (art. 1 pkt 1 projektu ustawy)\nDziałająca obecnie Rada Ochrony i Ułatwień Lotnictwa Cywilnego zajmuje się zagadnieniami dotyczącymi jednocześnie ochrony i ułatwień w lotnictwie cywilnym, co powoduje, że zakres zagadnień będących przedmiotem działalności Rady jest zbyt szeroki i nie powinien być łączony ze względu na potrzebę ochrony informacji oraz zapewnienia udziału w organie zajmującym się ułatwieniami większej liczbie podmiotów, zarówno w charakterze członków jak i gości zapraszanych na posiedzenia. Konieczność rozłączenia w ramach działalności opiniodawczo-doradczej tematyki ochrony i tematyki ułatwień w lotnictwie cywilnym wynika z zaleceń zawartych w Załączniku 17 do Konwencji, który dotyczy ochrony międzynarodowego lotnictwa cywilnego przed aktami bezprawnej ingerencji. Zgodnie z zaleceniem zawartym w punkcie 2.1.4 Załącznika 17 do Konwencji „Każde Umawiające się Państwo powinno zapewnić odpowiednie zabezpieczenie informacji dotyczących ochrony lotnictwa.”. Stąd prowadzenie działalności opiniodawczo-doradczej w ramach jednej rady zajmującej się zarówno zagadnieniami ochrony, jak i ułatwień w lotnictwie cywilnym nastręcza trudności związane z koniecznością wyłączania niektórych zagadnień dotyczących ochrony w lotnictwie cywilnym z omawiania na posiedzeniu całej Rady. Zmiana ułatwi również zapraszanie na posiedzenia organu zajmującego się ułatwieniami większej liczby gości i ekspertów, bez konieczności specjalnego organizowania posiedzeń w celu ochrony informacji. Uzasadnione jest zatem utworzenie dwóch odrębnych rad, które formalnie osobno będą się zajmować sprawami dotyczącymi ochrony i sprawami dotyczącymi ułatwień w lotnictwie cywilnym, co nie wyklucza przepływu informacji między radami w razie potrzeby. \nW wyniku projektowanych zmian w miejsce istniejącej jednej Rady Ochrony i Ułatwień Lotnictwa Cywilnego zostaną utworzone dwie rady: Rada Ochrony Lotnictwa Cywilnego oraz Rada Ułatwień Lotnictwa Cywilnego. Podstawą prawną do utworzenia przy ministrze właściwym do spraw transportu takiego organu opiniodawczo-doradczego są przepisy międzynarodowe, a mianowicie postanowienia Załączników do Konwencji, które, w przeciwieństwie do Konwencji, nie są ratyfikowane, co pociąga za sobą konieczność ich wdrażania do polskiego porządku prawnego. \nJeżeli chodzi o zagadnienia dotyczące ochrony w lotnictwie cywilnym, podstawa do utworzenia organu znajduje się w punkcie 3.1.7 Załącznika 17 do Konwencji, zgodnie z którym „Każde Umawiające się Państwo powołuje krajowy komitet ochrony lotnictwa cywilnego lub stosuje podobne rozwiązania, w celu koordynacji działań pomiędzy departamentami, agencjami i innymi instytucjami tego Państwa, zarządzającymi lotniskami i przewoźnikami lotniczymi, instytucjami zapewniającymi służby żeglugi powietrznej i innymi podmiotami zaangażowanymi lub odpowiedzialnymi za wdrażanie różnych aspektów krajowego programu ochrony lotnictwa cywilnego.”. \nW kwestii zagadnień dotyczących ułatwień w lotnictwie cywilnym, podstawa do utworzenia organu znajduje się w punkcie 8.15 Załącznika 9 do Konwencji, zgodnie z którym „Każde Umawiające się Państwo stworzy Komitet ds. Ułatwień w Krajowym Transporcie Lotniczym oraz Komitety ds. Ułatwień na Terenie Portów Lotniczych lub podobne koordynujące organy, w celach koordynowania działań, dotyczących ułatwień pomiędzy poszczególnymi wydziałami, agencjami oraz innymi organizacjami Państwa zainteresowanego lub odpowiedzialnego za różne aspekty międzynarodowego ruchu cywilnego, a także za porty lotnicze i przewoźników lotniczych.”.\nJednocześnie w Załączniku 9 do Konwencji zawarte są zalecenia odnośnie do relacji między komitetami do spraw ochrony i komitetami do spraw ułatwień, z których wynika możliwość powołania niektórych osób zarówno do jednego jak i drugiego komitetu, natomiast nie ma konieczności ustanawiania jednego komitetu do zajmowania się obydwoma obszarami. Zgodnie zatem z punktem 8.16 Załącznika 9 do Konwencji „Zaleca się podjęcie przez Umawiające się Państwa prób ustanowienia bliskiej, przystosowanej do okoliczności, koordynacji pomiędzy ochroną lotnictwa i programami ułatwień. Z tego powodu zaleca się, aby niektórzy członkowie Komitetów ds. Ułatwień byli również członkami Komitetów ds. Ochrony.”. Podobnie w zdaniu trzecim punktu 3.4 Załącznika 12 do Załącznika 9 do Konwencji, Organizacja Międzynarodowego Lotnictwa Cywilnego zaleca: „W celu utrzymania bliskich relacji pomiędzy Krajowym Komitetem ds. Ułatwień i Krajowym Komitetem ds. Ochrony Lotnictwa Cywilnego, odpowiedni członkowie Komitetu ds. Ochrony Lotnictwa Cywilnego mogą być również członkami Komitetu ds. Ułatwień i vice-versa.”.\nPonadto, w projektowanej ustawie proponuje się w inny sposób, a mianowicie nie bezpośrednio w ustawie, lecz w akcie wykonawczym wydawanym przez Prezesa Rady Ministrów, określić szczegółowe zadania, szczegółowy skład organów opiniodawczo-doradczych oraz podmioty uprawnione do powoływania i odwoływania członków tych organów, a także wymagania, których spełnienie przez osoby uczestniczące w posiedzeniach Rady Ochrony Lotnictwa Cywilnego jest konieczne do ochrony informacji ujawnianych na tych posiedzeniach. \nZ przyjętego w Konstytucji Rzeczypospolitej Polskiej modelu wykonywania władzy wykonawczej oraz obowiązujących w tym zakresie pozostałych przepisów wynika, że minister kierujący określonym działem administracji rządowej nie może zobowiązać innego członka Rady Ministrów do udziału w wykonywaniu zadań obejmujących ten dział. Te uprawnienia są przypisane Prezesowi Rady Ministrów, który m.in. reprezentuje Radę Ministrów, kieruje pracami Rady Ministrów oraz koordynuje i kontroluje pracę członków Rady Ministrów (art. 148 pkt 1, 2 i 5 Konstytucji Rzeczypospolitej Polskiej). Odzwierciedla to w szczególności art. 7 ust. 4 pkt 4 ustawy z dnia 8 sierpnia 1996 r. o Radzie Ministrów (Dz. U. z 2025 r. poz. 780, z późn. zm.), zgodnie z którym członek Rady Ministrów, realizując politykę ustaloną przez Radę Ministrów, występuje do Prezesa Rady Ministrów o powołanie zespołów międzyresortowych do wykonywania zadań wykraczających poza zakres jego działania. \nPonadto, wykonywanie zadań wykraczających poza dział administracji rządowej może być określone w przepisach odrębnych zgodnie z art. 4 ust. 3 ustawy z dnia 4 września 1997 r. o działach administracji rządowej (Dz. U. z 2025 r. poz. 1275, z późn. zm.), według którego ministrowie właściwi do spraw oznaczonych nazwą danego działu mogą wykonywać inne zadania i kompetencje, jeżeli przewidują to przepisy odrębne. Przy czym w przypadku określania składu oraz zmian w składzie organów opiniodawczo-doradczych w drodze ustawy jest to rozwiązanie bardziej czasochłonne niż dokonywanie tego w drodze rozporządzenia, stąd zaproponowano zmianę w tym zakresie.\nW związku z powyższym, do wydania zarządzenia dotyczącego m.in. składu Rady Ochrony Lotnictwa Cywilnego oraz Rady Ułatwień Lotnictwa Cywilnego został ustawowo upoważniony Prezes Rady Ministrów. Zapewniona zostanie w ten sposób możliwość szybszego wprowadzenia zmian prawnych, co jest niezbędne w przypadku stwierdzenia zasadności zmian w składzie organów, w tym uzupełnienia składu o przedstawicieli pomiotów, których wiedza i doświadczenie będzie przydatna w pracach organów opiniodawczo-doradczych. \nIstotne jest również ustawowe ograniczenie dostępności do informacji zawartych w dokumentach takich jak protokoły z posiedzeń oraz sprawozdania z pracy organów opiniodawczo-doradczych, które nie będą stanowić informacji publicznej w rozumieniu ustawy z dnia 6 września 2001 r. o dostępie do informacji publicznej (Dz. U. z 2022 r. poz. 902, z późn. zm.). Podczas posiedzeń są bowiem poruszane między innymi kwestie związane z zabezpieczeniem lotnisk, w tym infrastruktury krytycznej, oraz statków powietrznych przed aktami zagrażającymi bezpieczeństwu, a zatem takie informacje powinny mieć charakter chroniony, aby zapewnić możliwość swobodnego wyrażania opinii członków organów opiniodawczo-doradczych\nZmiany w art. 21 ust. 2 pkt 15, 21 oraz 24 ustawy\nW zakresie brzmienia pkt 15: Aktualne brzmienie art. 21 ust. 2 pkt 15 lit. c odnosi się do wydawania zaleceń profilaktycznych przez Prezesa Urzędu Lotnictwa Cywilnego dla użytkowników statków powietrznych, zarządzających portem lotniczym, producentów, przewoźników lotniczych, ośrodków szkolenia lotniczego, organów zarządzania ruchem lotniczym oraz innych podmiotów lotniczych. W związku z wdrożeniem przepisów oraz ustandaryzowaniem terminologii stosowanej w rozporządzeniu nr 376/2014/UE, w którym mowa o opracowywaniu przez każde państwo członkowskie oraz Agencję Unii Europejskiej ds. Bezpieczeństwa Lotniczego (EASA), procedur analiz informacji dotyczących zdarzeń, które zostały bezpośrednio zgłoszone w celu zidentyfikowania zagrożeń dla bezpieczeństwa, konieczne stało się wprowadzenie zmian w ustawie – Prawo lotnicze, mających na celu podkreślenie roli analiz ryzyka bazujących na zdarzeniach lotniczych. W oparciu o te analizy określa się wszelkie odpowiednie działania naprawcze lub zapobiegawcze, wymagane w celu poprawy bezpieczeństwa lotniczego. Zmiana obowiązującego przepisu pozwoli na podejmowanie działań rekomendowanych w ramach przeprowadzonych analiz, co pozwoli na zarządzanie bezpieczeństwem w większym stopniu w oparciu o dane z systemów zgłaszania zdarzeń. Analizy te w rezultacie wskazywać będą również najistotniejsze obszary zagrożeń. W zależności od specyfiki danego zdarzenia lotniczego prowadzenie działań zapobiegawczych i naprawczych pozwala eliminować przyczyny potencjalnych zagrożeń lub ograniczać ich dotkliwość i/lub częstość występowania. Działania te powinny być dostosowane do przewidywanych skutków realizacji zagrożeń w postaci zdarzeń niepożądanych i problemów wpływających na bezpieczeństwo. Aktualny przepis pozwala zalecać podmiotom lotniczym działania profilaktyczne w danej sytuacji i nie obliguje do podjęcia konkretnych działań zapobiegawczych bądź naprawczych już z inicjatywy samego podmiotu lotniczego. W związku z powyższym, projektowana regulacja jest potrzebna do ustandaryzowania sposobów zarządzania bezpieczeństwem przez podmioty lotnicze, gdyż każdy z tych podmiotów mających siedzibę w państwie członkowskim określa działania naprawcze lub zapobiegawcze wymagane w celu wyeliminowania rzeczywistych lub potencjalnych uchybień w zakresie bezpieczeństwa lotniczego. Równolegle nadzór lotniczy prowadzi niezależnie analizy zdarzeń i wprowadza swoje działania zapobiegawcze i naprawcze.\nWprowadzenie nowego przepisu art. 21 ust. 2 pkt 15 lit. f ma na celu pełną realizację art. 16 ust. 9 rozporządzenia nr 376/2014/UE. Obecnie ww. wymogi są realizowane częściowo zapewniając ochronę osobom zatrudnionym w podmiotach prowadzących działalność w zakresie lotnictwa cywilnego. Dodawany przepis ma na celu wskazanie Prezesa Urzędu Lotnictwa Cywilnego jako organu informującego pracowników Urzędu  Lotnictwa Cywilnego i osoby zatrudnione w Urzędzie na umowy cywilnoprawne (personel kontraktowy w rozumieniu rozporządzenia UE) o sposobie zgłaszania domniemanego naruszenia „zasady just culture”. Podmiotem rozpatrującym ww. zgłoszenia nie może być Prezes Urzędu Lotnictwa Cywilnego (konieczne jest zapewnienie podmiotowi niezależności).\nDodawany przepis art. 21 ust. 2 pkt 15 lit. g wprowadza obowiązek dokonywania przeglądu i w razie konieczności zmiany oraz zatwierdzenia klasyfikacji zdarzeń lotniczych pod względem ryzyka dla bezpieczeństwa, o której mowa w art. 7 ust. 2 rozporządzenia nr 376/2014/UE. Zgodnie z przepisami Unii Europejskiej od 1 stycznia 2023 r., każde zgłoszone zdarzenie podlega zastosowaniu wspólnej europejskiej klasyfikacji ryzyka. Jest to dodatkowy wymóg nałożony na organ nadzoru lotniczego wymagający do wdrożenia dodatkowych sił i środków w celu spełnienia tych wymagań.\nW zakresie pkt 21 i 24 wprowadzone zmiany mają charakter wynikowy i są związane ze zmianą organu, któremu Prezes Urzędu Lotnictwa Cywilnego będzie przedkładał do zaopiniowania Krajowy Program Ochrony Lotnictwa Cywilnego oraz Krajowy Programu Ułatwień Lotnictwa Cywilnego i ich aktualizacje, a mianowicie odpowiednio Radzie Ochrony Lotnictwa Cywilnego oraz Radzie Ułatwień Lotnictwa Cywilnego. \nZmiana brzmienia art. 87a ustawy \nAktualnie obowiązująca konstrukcja art. 87a ustawy, a w szczególności zawarty w ust. 4 tego artykułu przepis upoważniający do wydania rozporządzenia, uniemożliwia kompleksowe uregulowanie problemu, jakimi są emisje lasera lub światła z innych źródeł oraz innych przedmiotów, takich jak sztuczne ognie, lampiony, balony, balony z diodami LED, w kierunku statków powietrznych w strefach przestrzeni powietrznej wykorzystywanej do żeglugi powietrznej. Ponadto, obowiązujący przepis uniemożliwia określenie właściwego organu, który byłby odpowiedzialny za wydawanie zgody w odniesieniu do przestrzeni powietrznej, dla której nie ma właściwej instytucji zapewniającej służby ruchu lotniczego.\nW związku z powyższym, w art. 87a ust. 1 proponuje się zmiany wynikające z doświadczeń stosowania dotychczasowych przepisów określających zakaz emitowania lub powodowania emisji wiązki lasera lub światła z innych źródeł w kierunku statku powietrznego. W związku z tym zakaz będzie dotyczył emitowania lub powodowania emisji wiązki lasera lub światła z innych źródeł w kierunku statku powietrznego w sposób mogący spowodować olśnienie, oślepienie, wystąpienie poświaty lub w inny sposób mogący spowodować zagrożenie bezpieczeństwa statku powietrznego lub życia lub zdrowia załogi lub pasażerów znajdujących się na jego pokładzie.\nW projektowanym art. 87a ust. 2 wprowadza się wyjątek od powyższego zakazu, dopuszczając emitowanie lub powodowanie emisji wiązki lasera o natężeniu do 50 nW/cm². Wartość ta jest odzwierciedleniem wartości określonej przez Organizację Międzynarodowego Lotnictwa Cywilnego (The International Civil Aviation Organization), zwanej dalej „ICAO”, w dokumencie Manual on Laser Emitters and Flight Safety.\nWśród nowych propozycji przepisów w ust. 7 proponuje się wydłużenie terminu na złożenie wniosku przed planowaną emisją lasera lub światła z innych źródeł oraz wypuszczeniem obiektów, o których mowa w ust. 3, do 28 dni, celem zapewnienia wystarczającej ilości czasu na przeprowadzenie przez instytucję zapewniającą służby ruchu lotniczego niezbędnych analiz bezpieczeństwa oraz przekazania informacji do zainteresowanych organów służby ruchu lotniczego.\n\nZmiana brzmienia art. 135a ust. 3 ustawy \nObowiązujące brzmienie art. 135a ust. 3 ustawy zawiera niespójność w zakresie kwestii zgłaszania zdarzeń lotniczych w stosunku do innych aktów normatywnych, które wymagają dokonania zgłoszenia zdarzenia niezwłocznie po zaistnieniu zdarzenia, ale nie później niż 72 godziny od chwili powzięcia informacji o jego zaistnieniu. Niniejszy przepis w nowym brzmieniu ujednolica i likwiduje wspomnianą wyżej niespójność z innymi przepisami, które wymagają dokonania zgłoszenia zdarzenia niezwłocznie po zaistnieniu zdarzenia, ale nie później niż 72 godziny od chwili powzięcia informacji o jego zaistnieniu. Obecne brzmienie „72 godziny od jego zaistnienia” zmieniono na „nie później niż 72 godziny od chwili powzięcia informacji o jego zaistnieniu”. W praktyce dla części zdarzeń, ustalenie precyzyjnie momentu ich zaistnienia jest bardzo trudne lub wręcz niewykonalne. Dotyczy to m.in. części zdarzeń z udziałem ptaków (kiedy i w jakiej fazie lotu nastąpiło zderzenie) lub części zdarzeń technicznych (są wykrywane podczas okresowych dużych przeglądów technicznych).\n\nZmiana brzmienia art. 138 ust. 2–4 ustawy\nKomisja, jest organem do spraw badania zdarzeń lotniczych, o którym mowa w art. 4 ust. 1 rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 996/2010 z dnia 20 października 2010 r. w sprawie badania wypadków i incydentów w lotnictwie cywilnym oraz zapobiegania im oraz uchylającego dyrektywę 94/56/WE (Dz. Urz. UE L 295 z 12.11.2010, str. 35, z późn. zm.). Istotnym elementem podkreślonym w ww. rozporządzeniu jest niezależność Komisji. Ustawa, jakkolwiek tę niezależność uznaje w art. 17 ust. 1, to treść art. 138 ust. 4 może poddawać ją w wątpliwość. Stwierdzenie: „w razie ujawnienia nowych faktów mogących mieć wpływ na ustalenie przyczyn i okoliczności wypadku lub incydentu lotniczego, minister właściwy do spraw transportu może zlecić Komisji wznowienie już zakończonego badania”, może być uznane za ingerencję podmiotu zewnętrznego w pracę Komisji. Ponadto, za zbyteczne i przedłużające proces przekazywania dokumentacji dotyczącej badania wypadków lotniczych uznano przepisy zawarte w art. 138 ust. 3 ustawy, nadające ministrowi właściwemu ds. transportu funkcję pośrednika między Komisją a Prezesem Urzędu Lotnictwa Cywilnego w tym zakresie.\nW związku z powyższym, za zbyteczne i przedłużające proces przekazywania dokumentacji dotyczącej badania wypadków lotniczych uznano przepisy zawarte w art. 138 ust. 2 ustawy, nadające ministrowi właściwemu do spraw transportu funkcję pośrednika między Komisją a Prezesem Urzędu Lotnictwa Cywilnego w tym zakresie. W związku z tym art. 138 ust. 2 zmieniono w ten sposób, aby proces przekazania dokonywał się bezpośrednio między Komisją a Prezesem Urzędu Lotnictwa Cywilnego. Takie rozwiązanie powinno przyczynić się do szybszego przepływu informacji pomiędzy tymi podmiotami.\nPonadto zmieniono brzmienie ust. 4 tak, aby Komisja mogła wznowić badanie bez wcześniejszego zlecania tego badania przez ministra właściwego do spraw transportu, co przyczyni się do wzmocnienia niezależności tego podmiotu.\n\nDodanie art. 139a–139c ustawy \nOpracowanie KPBL jest jedną z najważniejszych zmian w koncepcji zarządzania bezpieczeństwem lotniczym w ostatniej dekadzie. Światowe standardy w tym obszarze zostały ustanowione w Załączniku 19 do Konwencji. Jednocześnie na mocy postanowień Konwencji strony Konwencji zostały zobowiązane do opracowania i implementowania takich programów. \nDodatkowo przepisy art. 7 i art. 8 rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 2018/1139 z dnia 4 lipca 2018 r. w sprawie wspólnych zasad w dziedzinie lotnictwa cywilnego i utworzenia Agencji Unii Europejskiej ds. Bezpieczeństwa Lotniczego oraz zmieniającego rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 2111/2005, (WE) nr 1008/2008, (UE) nr 996/2010, (UE) nr 376/2014 i dyrektywy Parlamentu Europejskiego i Rady 2014/30/UE i 2014/53/UE, a także uchylającego rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 552/2004 i (WE) nr 216/2008 i rozporządzenie Rady  (EWG) nr 3922/91 (Dz. Urz. UE L 212 z 22.08.2018, str. 1, z późn. zm.), zwanego dalej „rozporządzeniem (UE) nr 2018/1139”, nakładają na państwa członkowskie Unii Europejskiej wymóg posiadania systemów pozwalających na podnoszenie poziomu bezpieczeństwa z uwzględnieniem systemów zarządzania bezpieczeństwem. \nKPBL ma być zbiorem regulacji i działań, które mają na celu poprawę bezpieczeństwa i służą do zarządzania bezpieczeństwem w lotnictwie cywilnym na poziomie całego państwa. KPBL ma na celu przede wszystkim zintegrowanie działań państwa związanych z zarządzaniem bezpieczeństwem w obszarze legislacji, polityki i celów, jak również promowanie bezpieczeństwa oraz nadzór nad systemami zarządzania bezpieczeństwem podmiotów lotniczych. W chwili obecnej w Rzeczpospolitej Polskiej poziom bezpieczeństwa w lotnictwie cywilnym utrzymywany jest na podstawie obowiązujących przepisów, które nie posiadają cech KPBL, o jakich mowa w Konwencji. Część podmiotów lotniczych w Rzeczpospolitej Polskiej stosuje już zasady zarządzania bezpieczeństwem oparte na koncepcji wyartykułowanej w podręczniku ICAO Doc. 9859 (Safety Management Manual), jak również zgodnie z europejskimi wymaganiami rozporządzeń wykonawczych w obszarach: operacyjnym, służb żeglugi powietrznej, lotnisk, szkolenia personelu lotniczego, a od 2020 r. w zakresie ciągłej zdatności do lotu. Jednakże, aby można było te obszary działalności lotniczej uregulować i nadzorować, stosując metodologię proponowaną przez ICAO, państwo powinno ustanowić odpowiedni program zawierający politykę bezpieczeństwa oraz kryteria i zasady funkcjonowania dla wszystkich elementów tworzących system bezpieczeństwa w krajowym lotnictwie cywilnym. Program ten powinien być udostępniony do konsultacji innym właściwym dla lotnictwa organom państwa, w tym m.in. organom, którym podlega lotnictwo wojskowe, państwowe, służby poszukiwania i ratownictwa lotniczego oraz służby informacji meteorologicznej dla lotnictwa. Postawione przez państwo wymagania dotyczące zarządzania bezpieczeństwem przez podmioty lotnicze powinny być oparte na podstawach formalnych określonych w przepisach prawa oraz o właściwie dobrane wskaźniki. Nadzór nad bezpieczeństwem w lotnictwie cywilnym w głównej mierze opierał się dotychczas na weryfikacji i egzekwowaniu przez organy państwowe wszystkich norm i standardów z zakresu prawa lotniczego w podmiotach lotniczych i lotnictwie ogólnym. W związku z rozwojem lotnictwa cywilnego oraz mając na uwadze nowoczesne podejście do zarządzania bezpieczeństwem, pojawiła się koncepcja uzupełnienia weryfikacji poziomu bezpieczeństwa w podmiotach lotniczych o działania w zakresie zarządzania bezpieczeństwem osób lub gremiów zarządzających tymi podmiotami lotniczymi. Przy takim założeniu, dodatkowy wewnętrzny nadzór podmiotu lotniczego nad swoim bezpieczeństwem jest uzupełnieniem nadzoru państwowego. Systemy Zarządzania Bezpieczeństwem (Safety Management System – „SMS”) mają przede wszystkim za zadanie zwrócić uwagę osób zarządzających w podmiotach lotniczych odpowiednimi zasobami (m. in. personelem, czasem, środkami finansowymi) na zdarzenia niepożądane, które mogą mieć miejsce w danym środowisku w przyszłości (tzw. podejście proaktywne), a do których zaistnienia/wystąpienia można nie dopuścić przez wcześniej podjęte odpowiednie działania. Identyfikowanie przyszłych zagrożeń ma być formą zarządzania znacznie bardziej efektywną od podejmowania działań o charakterze korygującym i naprawczym (tzw. podejście reaktywne), kiedy już doszło do niepożądanych zdarzeń, a tym samym nie można cofnąć ich skutków. SMS zakłada podjęcie stosownych działań zapobiegawczych przez konkretny podmiot lotniczy w sytuacji identyfikacji możliwości wystąpienia konkretnego zagrożenia, a jeszcze przed jego zmaterializowaniem się w postaci zdarzenia lotniczego. Działania obejmują indywidualną, choć usystematyzowaną, ocenę prawdopodobieństwa i możliwych skutków zdarzenia w oparciu m. in. o doświadczenia własne lub innych podmiotów lotniczych.\nElementy systemu zarządzania bezpieczeństwem (zwane również „komponentami” lub „filarami” SMS-a) są takie same dla organizacji i dla państwa. Obejmują: 1) politykę i cele bezpieczeństwa, 2) zarządzanie ryzykiem bezpieczeństwa, 3) zapewnianie bezpieczeństwa oraz 4) promocję bezpieczeństwa. W ramach pierwszego filaru określa się podstawowe przesłanki dla wdrażania systemu, priorytety w zakresie bezpieczeństwa oraz zaangażowanie kierownictwa/osób zarządzających w działania na rzecz poprawy bezpieczeństwa. Zarządzanie ryzykiem to proces identyfikacji zagrożeń, oceny ryzyk z nimi powiązanych (w oparciu o przyjętą metodę oceny ryzyka), wskazania działań ograniczających ryzyko dla tych obszarów, gdzie wynik analizy ryzyka jest na poziomie nieakceptowalnym i/lub wymagającym podjęcia takich działań. Skuteczność wdrożonych środków powinna być oceniana i mierzona oraz spójna z celami bezpieczeństwa i określana na podstawie wyników monitorowania przyjętych wskaźników poziomu bezpieczeństwa. Jest to element zapewniania bezpieczeństwa, niezbędny do zapewnienia skutecznego wdrożenia systemu oraz jego doskonalenia. Wskaźniki poziomu bezpieczeństwa wskazane w Krajowym Planie Bezpieczeństwa, stanowiącym załącznik do KPBL, raportowane przez organizacje pozwalają monitorować, oceniać i mierzyć efektywność działań w zakresie ograniczania ryzyka i skuteczności systemu zarządzania bezpieczeństwem na poziomie krajowym. Proponowane brzmienie art. 139b i art. 139c dodawanych do ustawy ma na celu zapewnienie możliwości zbierania danych niezbędnych do realizacji obowiązku wynikającego z przepisów międzynarodowych odnoszących się do wdrożenia KPBL oraz Krajowego Planu Bezpieczeństwa w obszarze zapewniania bezpieczeństwa.\nDodane przepisy sytuują KPBL na poziomie krajowym, który nie jest wyłącznie dokumentem Urzędu Lotnictwa Cywilnego, lecz stanowi program państwa, którego celem jest zapewnienie akceptowalnego poziomu bezpieczeństwa w całym krajowym systemie lotnictwa. Wynika to z obowiązujących aktów prawa międzynarodowego i unijnego, skąd wynika także konieczność zapewnienia możliwości konsultacji dokumentu z zainteresowanymi stronami mającymi wpływ na bezpieczeństwo lotnicze.\nZałącznik 19 do Konwencji wskazuje, że KPBL musi obejmować cały system lotnictwa cywilnego państwa, „Państwo (State) zapewnia udział wszystkich odpowiednich organów i podmiotów w identyfikacji zagrożeń bezpieczeństwa, ocenie ryzyka oraz wdrażaniu środków łagodzących”. Dodatkowo Załącznik 19 wymaga określenia w KPBL ról i odpowiedzialności wszystkich zainteresowanych organów państwowych. Dokument ICAO Doc. 9859 (Safety Management Manual), rozdz. 8.3.6 i 8.6.8, do którego Załącznik 19 się odwołuje, wskazuje, że skuteczny KPBL wymaga utworzenia grupy koordynacyjnej (State Safety Programme Committee/SSP Coordination Group), zapewniającej właściwą komunikację w obszarze informacji bezpieczeństwa, doświadczenia, zasad i procedur\nZgodnie z rozporządzeniem (UE) nr 2018/1139 KPBL obejmuje zarządzanie ryzykiem bezpieczeństwa na poziomie państwa, a art. 7 ust. 1 nakłada na państwa członkowskie obowiązek zapewnienia konsultacji między wszystkimi zainteresowanymi stronami, co EASA w swoich audytach wielokrotnie podkreśla, tj. brak udziału innych stron w konsultacjach nad KPBL stanowi poważne uchybienie (finding).\nW związku z powyższym, do powołanego przez Prezesa Urzędu Lotnictwa Cywilnego Zespołu do spraw wdrożenia i aktualizacji Krajowego Programu Bezpieczeństwa Lotniczego oraz Krajowego Planu Bezpieczeństwa powinni być zapraszani co najmniej przedstawiciele:\n-\tMinistra Obrony Narodowej z uwagi na współpracę z Władzą Lotnictwa Wojskowego oraz Komisją Badania Wypadków Lotniczych Lotnictwa Państwowego,\n-\tministra właściwego do spraw wewnętrznych jako organu nadzorującego służbę Lotnictwo Policji i Lotnictwo Straży Granicznej,\n-\tMinistra Sprawiedliwości, którego obecność jest wymagana z uwagi na konieczność realizacji przepisów art. 16 rozporządzenia nr 376/2014/UE w zakresie ochrony zgłaszającego i stosowania zasad kultury sprawiedliwego traktowania (just culture),\n-\tPaństwowej Komisji Badania Wypadków Lotniczych w związku z prowadzoną przez Komisję działalnością w zakresie badania zdarzeń lotniczych, w tym wydawaniem zaleceń bezpieczeństwa,\n-\tInstytutu Meteorologii i Gospodarki Wodnej – Państwowego Instytutu Badawczego,\n-\tcywilno–wojskowego ośrodka koordynacji poszukiwania i ratownictwa lotniczego.\nNależy podkreślić, że KPBL nie zawiera regulacji o charakterze norm prawnych. Ze swojej istoty stanowi zintegrowany zbiór reguł i przedsięwzięć mających na celu poprawę bezpieczeństwa w lotnictwie cywilnym. Zgodnie z koncepcją ICAO, dokument ten ma być wyrazem podejścia państwa do kwestii bezpieczeństwa w lotnictwie cywilnym, zinstytucjonalizowaną formą zarządzania bezpieczeństwem operacji i zarządzania ryzykiem, mającą na celu zmianę podejścia do kwestii bezpieczeństwa w lotnictwie cywilnym z „reaktywnego” na „proaktywny”. \nProponowane dostosowanie obowiązujących przepisów do nowych standardów dotyczy zagadnień zarządzania bezpieczeństwem w lotnictwie cywilnym na poziomie nadzoru krajowego nad podmiotami lotniczymi, z uwzględnieniem rozwiązań zawartych w:\n1)\tZałączniku 19 do Konwencji i bardziej szczegółowych wytycznych znajdujących się w Podręczniku Zarządzania Bezpieczeństwem (ICAO SMM – Doc. 9859);\n2)\trozporządzeniu (UE) nr 2018/1139;\n3)\tEuropejskim Programie Bezpieczeństwa w Lotnictwie Cywilnym (European Aviation Safety Programme – EASP);\n4)\tEuropejskim Planie Bezpieczeństwa w Lotnictwie Cywilnym (European Plan for Aviation Safety – EPAS);\n5)\tGlobalnym Planie Bezpieczeństwa w Lotnictwie Cywilnym (Global Aviation Safety Plan- GASP);\n6)\tRegionalnym Planie Bezpieczeństwa w Lotnictwie Cywilnym (Regional Aviation Safety Plan – EUR RASP).\nReasumując, dodawane w tym przedmiocie regulacje obejmują:\n1)\tnałożenie na Prezesa Urzędu Lotnictwa Cywilnego obowiązku opracowania, poddania konsultacjom, w tym z właściwymi organami państwa, którym podlega lotnictwo wojskowe, państwowe, służby poszukiwania i ratownictwa lotniczego oraz służby informacji meteorologicznej dla lotnictwa, zatwierdzenia i publikacji KPBL, w tym Krajowego Planu Bezpieczeństwa stanowiącego załącznik do KPBL;\n2)\tnałożenie na Prezesa Urzędu Lotnictwa Cywilnego obowiązku aktualizacji KPBL nie rzadziej niż raz na 4 lata, co pozwoli na zachowanie aktualności KPBL w przypadku zmian w prawodawstwie krajowym, unijnym i międzynarodowym (art. 139a ust. 4);\n3)\tnałożenie na Prezesa Urzędu Lotnictwa Cywilnego obowiązku corocznej aktualizacji Krajowego Planu Bezpieczeństwa (art. 139a ust. 5) tak, aby obszary zdefiniowanych zagrożeń oraz dobrane do nich wskaźniki poziomu bezpieczeństwa jak najdokładniej odzwierciedlały poziom bezpieczeństwa w obszarze transportu lotniczego;\n4)\tnałożenie na podmioty lotnicze, obowiązane na podstawie przepisów prawa Unii Europejskiej, przepisów międzynarodowych lub przepisów krajowych do wdrożenia zintegrowanego systemu zarządzania lub systemu zarządzania bezpieczeństwem, obowiązku przekazywania Prezesowi Urzędu Lotnictwa Cywilnego wartości wskaźników poziomu bezpieczeństwa określonych w Krajowym Planie Bezpieczeństwa, we wskazanych w nim odstępach czasowych (art. 139c); w przepisach ujęte są następujące podmioty:\na)\tzatwierdzone organizacje szkolenia lotniczego (ATO) – rozporządzenie Komisji (UE) nr 1178/2011 z dnia 3 listopada 2011 r. ustanawiające wymagania techniczne i procedury administracyjne odnoszące się do załóg w lotnictwie cywilnym zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (WE) nr 216/2008 (Dz. Urz. UE L 311 z 25.11.2011, str. 1, z późn. zm.),\nb)\tposiadacze certyfikatu operatora lotniczego (AOC) – rozporządzenie Komisji (UE) nr 965/2012 z dnia 5 października 2012 r. ustanawiające wymagania techniczne i procedury administracyjne odnoszące się do operacji lotniczych zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (WE) nr 216/2008 (Dz. Urz. UE L 296 z 25.10.2012, str. 1, z późn. zm.),\nc)\toperatorzy lotnisk (ADR) – rozporządzenie Komisji (UE) nr 139/2014 z dnia 12 lutego 2014 r. ustanawiające wymagania oraz procedury administracyjne dotyczące lotnisk zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (WE) nr 216/2008 (Dz. Urz. UE L 44 z 14.02.2014, str. 1, z późn. zm.),\nd)\tsłużby żeglugi powietrznej (ATM/ANS) – rozporząd powietrznej i inne funkcje sieciowe zarządzania ruchem lotniczym oraz nadzoru nad nimi, uchylające rozporządzenie (WE) nr 482/2008, rozporządzenia wykonawcze (UE) nr 1034/2011, (UE) nr 1035/2011 i (UE) 2016/1377 oraz zmieniające rozporządzenie (UE) nr 677/2011 (Dz. Urz. UE L 62 z 08.03.2017, str. 1, z późn. zm.),\ne)\torganizacje szkolące kontrolerów ruchu lotniczego (ATCO) – rozporządzenie Komisji (UE) 2015/340 z dnia 20 lutego 2015 r. ustanawiające wymagania techniczne i procedury administracyjne dotyczące licencji i certyfikatów kontrolerów ruchu lotniczego zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (WE) nr 216/2008, zmieniające rozporządzenie wykonawcze Komisji (UE) nr 923/2012 i uchylające rozporządzenie Komisji (UE) nr 805/2011 (Dz. Urz. UE L 63 z 06.03.2015, str. 1, z późn. zm.),\nf)\torganizacje zarządzające ciągłą zdatnością do lotu (CAMO) oraz organizacje obsługowe (Part 145) – rozporządzenie Komisji (UE) nr 1321/2014 z dnia 26 listopada 2014 r. w sprawie ciągłej zdatności do lotu statków powietrznych oraz wyrobów lotniczych, części i wyposażenia, a także w sprawie zatwierdzeń udzielanych organizacjom i personelowi zaangażowanym w takie zadania (Dz. Urz. UE L 362 z 17.12.2014, str. 1, z późn. zm.),\ng)\torganizacje produkujące i projektujące (Part 21 – POA, DOA) – rozporządzenie Komisji (UE) nr 748/2012 z dnia 3 sierpnia 2012 r. ustanawiające przepisy wykonawcze dotyczące certyfikacji statków powietrznych i związanych z nimi wyrobów, części i akcesoriów w zakresie zdatności do lotu i ochrony środowiska oraz dotyczące certyfikacji organizacji projektujących i produkujących (Dz. Urz. UE L 224 z 21.08.2012, str. 1, z późn. zm.),\nh)\toperatorzy systemów bezzałogowych statków powietrznych – rozporządzenie wykonawcze Komisji (UE) 2019/947 z dnia 24 maja 2019 r. w sprawie przepisów i procedur dotyczących eksploatacji bezzałogowych statków powietrznych (Dz. Urz. UE L 152 z 11.06.2019, str. 45, z późn. zm.).\nDodatkowo w przyszłości planowane jest objęcie obowiązkiem wdrożenia systemu zarządzania bezpieczeństwem również agentów obsługi naziemnej (AHAC).\nUchylenie art. 188b ustawy \nProponuje się wykreślenie z obowiązującej ustawy przepisów dotyczących wydawania certyfikatów CMC. \nNależy wskazać, że na forum organizacji ECAC i ICAO obecnie podnoszona jest kwestia zasadności wydawania certyfikatów CMC. Wiele państw stosuje środki ułatwiające, które wyróżniają załogę od pasażerów, w tym zwolnienia z wymogów wizowych i zezwoleń na podróż. \nHistorycznie rzecz biorąc, certyfikaty członków załogi (CMC) zostały wprowadzone jako instrument ułatwiający przekraczanie granic przez personel przewoźników lotniczych. Jednak w obecnych ramach ustanowionych w Załączniku 9 ICAO, ułatwienia do Konwencji i CMC nieumyślnie stały się czynnikiem ograniczającym. Pomimo włączenia norm dotyczących CMC do Załącznika 9, od czasu jego pierwszego wydania w 1949 r. tylko 16 państw obecnie wydaje takie certyfikaty, w tym tylko 4 państwa europejskie. Ta rozbieżność w realizacji podważa pierwotny cel, jakim było globalne ułatwienie pracy załóg lotniczych. Od 1997 r. oczekuje się, że CMC będą wydawane w formie kart nadających się do odczytu maszynowego, zgodne ze specyfikacjami określonymi w dokumencie ICAO Doc 9303 jak określają dane techniczne oficjalnych dokumentów podróży (MRTD). Niniejsze specyfikacje nie doczekały się aktualizacji w ostatnich latach, co rodzi pytanie, czy pozostają one w pełni dostosowane do obecnych możliwości technologicznych i potrzeb w zakresie ułatwień. Na spotkaniach Grupy Roboczej Ułatwień w ECAC podnoszono również kwestię zasadności wydawania CMC i zaznaczono, że wdrożenie norm Załącznika 9 dotyczących CMC wymaga przeglądu i modernizacji w celu dostosowania do obowiązujących praktyk większości państw członkowskich. Współcześnie, połączenie dokumentów identyfikacyjnych i dokumentów kwalifikacji zawodowych załogi z technologiami stosowanymi w środkach ochrony lotnictwa umożliwiają państwom weryfikację tożsamości załogi i ocenę potencjalnych zagrożeń bez konieczności wydania i posiadania certyfikatu CMC. Wystarczające zazwyczaj są dokumenty już posiadane przez załogę podczas wykonywania operacji lotniczej, a obejmują one między innymi ważny paszport, licencję pilota, kartę identyfikacyjną członka załogi wydaną przez przewoźnika lotniczego lub przepustkę wstępu do strefy zastrzeżonej na lotnisku.\nOgraniczone wykorzystanie CMC przez państwa sugeruje, że jego funkcja potwierdzania tożsamości nie została przyjęta priorytetowo na świecie i jest zdominowana przez paszporty, które mają znacznie wyższe zabezpieczenia i dają lepsze gwarancje bezpieczeństwa. Wśród podawanych przez władze państw powodów niewydawania CMC na pierwszym miejscu są koszty związane z takim programem oraz konieczność zapewnienia dużych zasobów w instytucjach odpowiedzialnych, wymaganych do zarządzania i administrowania całym procesem. Jednocześnie daje się zauważyć trend w środowiskach lotniczych do opracowania innych, bezkosztowych rozwiązań, które zmierzają w kierunku rozszerzenia funkcji dokumentów już używanych. \nPaństwa priorytetowo potraktowały zwiększenie bezpieczeństwa paszportów, które pozostają najpowszechniej uznawanym, bezpiecznym dokumentem tożsamości w podróżach międzynarodowych. Opracowanie specyfikacji technicznych w ramach Doc 9303 zaowocowało wprowadzeniem paszportu elektronicznego, obecnie uznawanego za najbezpieczniejszą formę dokumentu podróży. Znaczna część członków załóg na świecie posiada już takie paszporty. \nNależy wskazać, że funkcja identyfikacyjna przewidziana dla CMC w praktyce została zdystansowana przez doskonałe zabezpieczenia i szeroką międzynarodową akceptację paszportu elektronicznego. Z punktu widzenia kontroli granicznej wykorzystanie CMC jako podstawy do zwolnienia z obowiązku wizowego ma ograniczone zastosowanie, a ponadto wymaga wcześniejszych uzgodnień z państwem przyjmującym. Spostrzeżenie to jest poparte analizą przeprowadzoną przez Międzynarodową Organizację Transportu Lotniczego (IATA) w ramach działań Grupy Roboczej ds. Organów Kontrolnych (CAWG), na podstawie danych zebranych między końcem 2024 r. a początkiem 2025 r. z różnych źródeł, w tym z IATA Dane Timatic ze 121 państw. Tylko 25 z tych państw nie wymaga paszportu przy okazywaniu CMC, w celu ułatwienia  państwom członkowskim bezwizowego przekraczania granic, a niektóre państwa nakładają na załogę obowiązek wizowy, nawet jeśli załoga posiada certyfikat CMC.\n\nZmiany w art. 189a ustawy \nObowiązujący art. 189a ust. 2 ustawy zawiera delegację ustawową do wydania przez ministra właściwego do spraw transportu, w drodze rozporządzenia, Krajowego Programu Ułatwień Lotnictwa Cywilnego. Do chwili obecnej delegacja ta nie została zrealizowana. Wynika to z faktu, że regulacje składające się na system ułatwień lotnictwa cywilnego znajdują się w różnych aktach prawnych pozostających we właściwości różnych resortów, natomiast Krajowy Program Ułatwień Lotnictwa Cywilnego ma być zbiorem regulacji i działań, które mają na celu uporządkować system ułatwień w lotnictwie cywilnym. Uregulowanie kwestii sposobów i warunków realizacji systemu ułatwień lotnictwa cywilnego w akcie rangi rozporządzenia mogłoby więc stanowić naruszenie zasady hierarchii źródeł prawa oraz niepotrzebnie prowadziłoby do powtarzania już obowiązujących przepisów. Uwzględniając dodawany do ustawy art. 189a ust. 1a, który przewiduje kompetencję do opracowania, zatwierdzenia i publikacji przez Prezesa Urzędu Lotnictwa Cywilnego Krajowego Programu Ułatwień Lotnictwa Cywilnego, który wcześniej zostanie zaopiniowany przez Radę Ułatwień Lotnictwa Cywilnego, oraz propozycję wykreślenia z obwiązującej ustawy przepisów dotyczących certyfikatów CMC, proponuje się uchylenie art. 189a ust. 2 ustawy i tym samym upoważnienia do wydania rozporządzenia. Jednocześnie nastąpi zmiana formy, w jakiej ma być określany Krajowy Program Ułatwień Lotnictwa Cywilnego. Program ten nie będzie określony w rozporządzeniu wykonawczym do ustawy, lecz będzie dokumentem opracowywanym w Urzędzie Lotnictwa Cywilnego, konsultowanym z zainteresowanymi stronami, opiniowanym przez Radę Ułatwień Lotnictwa Cywilnego oraz zatwierdzanym i publikowanym przez Prezesa Urzędu Lotnictwa Cywilnego. \nZgodnie z projektem nowelizacji ustawy Krajowy Program Ułatwień Lotnictwa Cywilnego będzie opracowywany, zatwierdzany i publikowany przez Prezesa Urzędu Lotnictwa Cywilnego, po jego uprzednim skonsultowaniu z zainteresowanymi stronami oraz pozytywnym zaopiniowaniu przez Radę Ułatwień Lotnictwa Cywilnego. Dokument nie będzie zawierał norm prawnych, lecz zestawienie zadań wynikających z Załącznika 9 do Konwencji z odpowiednimi przepisami prawa krajowego, jak również listę podmiotów odpowiedzialnych za ich realizację zgodnie z prawem krajowym. Takie podejście do tworzenia Krajowego Programu Ułatwień Lotnictwa Cywilnego jest zgodne z modelem wzorcowym dla krajowego programu ułatwień w lotnictwie cywilnym, który stanowi załącznik 12 do Załącznika 9 do Konwencji.\n\nZmiana art. 189c ust. 2 pkt 3 ustawy \nZmiana ta wynika z wykreślenia przepisów obowiązującej ustawy kwestii dotyczących certyfikatów CMC, w związku z tym zbędny jest przepis, zgodnie z którym rozszerzone sprawdzenie przeszłości przeprowadza się wobec posiadaczy CMC.\n\nDodanie art. 209up do ustawy\nWprowadza się karę pieniężną w wysokości od 500 do 5 000 zł dla użytkownika statku powietrznego, który nie złożył Prezesowi Urzędu Lotnictwa Cywilnego w określonym terminie sprawozdania za rok ubiegły z wykonywania operacji lotniczych, o którym mowa w art. 135d ustawy. Przy nakładaniu kary Prezes Urzędu Lotnictwa Cywilnego weźmie pod uwagę przesłanki określone w art. 209w ust. 2 ustawy.\nProponowana kara pieniężna wynika z wieloletnich doświadczeń Urzędu Lotnictwa Cywilnego. Dla przykładu należy wskazać, że w 2022 roku właściciele i użytkownicy statków powietrznych przesłali dane tylko dla 43% statków powietrznych zarejestrowanych w rejestrze cywilnych statków powietrznych.\nDane dotyczące nalotów (liczb operacji i wylatanych godzin) są niezbędne do prowadzenia bardziej zaawansowanych analiz bezpieczeństwa zwłaszcza w przypadku statków powietrznych spoza CAT (Commercial Air Transport – zarobkowy transport lotniczy), gdzie brak jest innych źródeł danych odniesienia. Bezwzględne liczby zdarzeń lotniczych, bez uwzględniania liczb operacji i wylatanych godzin, nie dają wystarczającego obrazu sytuacji, aby stanowić dobrą podstawę do podejmowania skutecznych działań naprawczo-zapobiegawczych, czy decydowania w zakresie zmian intensywności prowadzonego nadzoru w celu skupienia się na najbardziej problematycznych obszarach o najwyższym ryzyku.\n\nZmiana brzmienia art. 209w ustawy\nZmiana brzmienia art. 209w spowodowana jest wprowadzeniem w projektowanym art. 209up nowej kary administracyjnej nakładanej przez Prezesa Urzędu Lotnictwa Cywilnego w drodze decyzji administracyjnej.\n\nZmiany w art. 211\nPonadto, w związku ze zmianami zaproponowanymi w zakresie art. 87a ustawy konieczne stało się wprowadzenie adekwatnych zmian w art. 211 ust. 1 pkt 12 ustawy, określającym sankcje za działanie wbrew zakazom wynikającym z art. 87a ustawy, przez doprecyzowanie znamion obecnie istniejącego przestępstwa (w szczególności dodanie wyrazów „lub życia”) oraz dodanie nowego czynu zabronionego w projektowanej lit. b.\nJednocześnie należy wskazać na znaczną liczbę zdarzeń z użyciem laserów prowadzących do oślepienia pilotów statków powietrznych wiązkami lasera albo innymi źródłami światła (tabela zdarzeń na podstawie ECCAIRS poniżej), co w rezultacie może stworzyć zagrożenie dla bezpieczeństwa statku powietrznego lub zdrowia załogi i pasażerów na jego pokładzie, w krytycznych fazach lotu, jakimi są start i lądowanie, gdzie czas akomodacji oka pilota po oślepieniu ma olbrzymie znaczenie dla bezpieczeństwa żeglugi powietrznej. Szczególnie narażeni na oślepienie są piloci Lotniczego Pogotowia Ratunkowego (LPR), ze względu na łatwiejsze dotarcie z promieniem lasera do śmigłowców LPR wykonujących operacje lotnicze na lądowiskach szpitalnych.\nZdarzenia lotnicze z udziałem laserów w latach 2009–2025 r.: 2009 r. – 12, 2010 r. – 36, 2011 r. – 57, 2012 r. – 97, 2013 r. – 90, 2014 r. – 131, 2015 r. – 110, 2016 r. – 103, 2017 r. – 136, 2018 r. – 112, 2019 r. – 172, 2020 r. (COVID) – 100, 2021 r. (COVID) – 137, 2022 r. – 216, 2023 r. – 193, 2024 r. – 247, 2025 r. – 166.","organ":"MI","person":"Piotr Malepszak Podsekretarz Stanu","planned_adoption":"II kwartał 2027 r.","status":"","resignation":"","published_at":"2026-10-13T12:14:00Z","web_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy--prawo-lotnicze8","rcl_project_id":null}',NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'metadata','not_relevant',NULL,NULL,NULL,NULL,NULL,NULL);
