INSERT INTO "bills" VALUES(10,'RCL/12409404','Projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci','2026-10-21T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:obywatele_ukrainy"]','{"term":10,"number":"RCL/12409404","title":"Projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci","description":"RODZINNE I OPIEKUŃCZE PRAWO; rodzina","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-20","document_date":"2026-10-14","change_date":"2026-10-21T00:00:00Z","eu_related":false,"rcl_num":"RM-0610-171-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12409404","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"14. Skierowanie projektu ustawy do Sejmu","stage_type":"RclStage","sub_committee":false,"children":[]}]','453d52f18894ae758152cd1036a587a23d444c65013491673c15205f9af7eaf7','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила пособия на ребёнка 800+. ZUS будет сам продлевать право на выплату тем, кто уже его получает, а круг получателей расширят на некоторых опекунов по решению суда.","key_changes":["ZUS автоматически продлевает право на 800+ тем, у кого оно есть на 31 мая.","Добавлены получатели: лица с «bieżąca piecza» по решению польского суда.","Уточнены категории временного опекуна и опекуна, назначенного властями страны происхождения.","Банки и системы e‑ZUS могут хранить заявки и вложения до 10 лет для рекламаций.","Уточнено финансирование вещевой формы 800+ для опекуна ребёнка, указанного страной происхождения."],"affected_groups":["иностранцы с детьми, уже получающие пособие 800+","иностранцы, впервые оформляющие 800+ на ребёнка в Польше","иностранные опекуны детей по решению польского суда (bieżąca piecza)","опекуны детей, указанных властями страны происхождения ребёнка"],"practical_impact":"Иностранным семьям, которые уже получают 800+ на 31 мая, обычно не придётся подавать ежегодные заявки: ZUS сам продлит выплату. При первом оформлении и при изменении ситуации (особенно выезд семьи за границу) по‑прежнему нужно подавать заявление и уведомлять ZUS; новые категории опекунов смогут получать 800+ напрямую.","effective_date":"Закон вступает в силу через 14 дней после опубликования, за исключением ст. 1 п. 4 лит. a, п. 5, п. 9 лит. a и п. 10–13 и ст. 3, которые вступают в силу 1 февраля 2027 г.","confidence":0.93,"rationale":"Проект меняет порядок назначения и продления пособия 800+, которым могут пользоваться иностранцы с детьми в Польше, поэтому это важное изменение в социальной сфере.","mnemonic_candidate":"Автообновление 800+","mnemonic_fallback":"Автопродление пособия 800+","mnemonic_basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze (800+) без повторной заявки для лиц, уже получающих выплату.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v11","input_chars":41339,"truncated":false,"text_source":"documents","created_at":"2026-10-14T16:08:45Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12409404/13198704/13198705/dokument802150.zip","source_kind":"rcl","revision":1,"text_sha256":"text-v2:57833ee7f7e58bce903afef37933eddd113258f57ca4536092fdb1b27ff1d7b6","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":"law-v2:d83673b42b2f9050ba6a6fd9c844cfb417f84b6296f185c3820ff266c9006c2b","source_checked_at":"2026-10-14T16:08:45Z"}',0,NULL,'2026-10-14T15:53:14+00:00','2026-10-22T18:16:14+00:00',NULL,'3267',NULL,NULL,NULL,NULL,'{"id":12409404,"title":"Projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci","applicant":"Minister Rodziny, Pracy i Polityki Społecznej","wykaz_number":"UDER106","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-pomocy-panstwa-w-wychowywaniu-dzieci4","created":"2026-04-20","modified":"2026-10-21","departments":["rodzina"],"keywords":["RODZINNE I OPIEKUŃCZE PRAWO"],"status":"otwarty","term_label":"X","rm_number":"RM-0610-171-26","sejm_url":"http://www.sejm.gov.pl/Sejm7.nsf/agent.xsp?symbol=RPL&Id=RM-0610-171-26","print_number":"3267","stages":[{"id":13198655,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13198656,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-06-01","folders":[{"id":13198657,"name":"Projekt","modified":"2026-04-20","documents":[{"id":772513,"name":"PROJEKT - 13.04.2026.","url":"https://legislacja.rcl.gov.pl/docs//2/12409404/13198656/13198657/dokument772513.doc","created":"2026-04-20","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":772514,"name":"UZASADNIENIE - 13.04.2026.","url":"https://legislacja.rcl.gov.pl/docs//2/12409404/13198656/13198657/dokument772514.doc","created":"2026-04-20","author":"Minister Rodziny, Pracy i Polityki Społecznej"},{"id":772515,"name":"OSR - 13.04.2026.","url":"https://legislacja.rcl.gov.pl/docs//2/12409404/13198656/13198657/dokument772515.doc","created":"2026-04-20","author":"Minister Rodziny, Pracy i Polityki Społecznej"}]},{"id":13198658,"name":"Pisma kierujące 