INSERT INTO "bills" VALUES(10,'RPW/35146/2026','Rządowy projekt ustawy o sprawiedliwym dostępie do danych i ich wykorzystywaniu','2026-10-19T00:00:00+00:00',NULL,NULL,'linked','["text:prawnicy_zagraniczni"]','{"term":10,"number":"RPW/35146/2026","title":"Rządowy projekt ustawy o sprawiedliwym dostępie do danych i ich wykorzystywaniu","description":"wprowadzenia przepisów, które zapewnią stosowanie unijnych zasad dostępu do danych i ich wykorzystywania. Chodzi m.in. o dane w urządzeniach podłączonych do internetu. Prezes Urzędu Komunikacji Elektronicznej będzie odpowiadał za nadzór nad przestrzeganiem tych zasad, rozpatrywanie skarg i certyfikowanie podmiotów rozstrzygających spory. Obowiązki informacyjne wobec Komisji Europejskiej będzie realizował Minister Cyfryzacji","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-19","document_date":"2026-10-19","change_date":"2026-10-19T00:00:00Z","eu_related":true,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,'{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается доступа к данным и их использования в рамках регламента ЕС о данных (Data Act), не затрагивает статус, пребывание или права иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается доступа к данным и их использования в рамках регламента ЕС о данных (Data Act), не затрагивает статус, пребывание или права иностранцев.","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-10-v12","input_chars":6007,"truncated":true,"text_source":"excerpts","created_at":"2026-10-19T22:29:07Z","input_tokens":4366,"output_tokens":88,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"selection":{"quest