INSERT INTO "bills" VALUES(10,'1529','Poselski projekt ustawy o zmianie ustawy - Kodeks wyborczy','2026-10-23T07:56:57+00:00','2026-10-22',0,'skipped_text_prefilter','[]','{"term":10,"number":"1529","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks wyborczy","description":"projekt dotyczy zniesienia obowiązującego ograniczenia liczby kadencji, które może sprawować wójt (odpowiednio burmistrz lub prezydent miasta). Dodatkowo wnioskodawcy proponują likwidację zakazu kandydowania przez kandydata na wójta/burmistrza/prezydenta do rady powiatu i do sejmiku województwa.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-04","document_date":"2025-07-04","change_date":"2026-10-23T07:56:57Z","closure_date":"2026-10-22","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-10-20T18:01:38+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/22565/2025","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks wyborczy","description":"zniesienia obowiązującego ograniczenia liczby kadencji, które może sprawować wójt (odpowiednio burmistrz lub prezydent miasta). Dodatkowo wnioskodawcy proponują likwidację zakazu kandydowania przez kandydata na wójta/burmistrza/prezydenta do rady powiatu i do sejmiku województwa.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-07-04","print_number":"1529","eu_related":false,"public_consultation":true,"consultation_start":"2025-07-08","consultation_end":"2025-08-07","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3234','Poselski projekt ustawy o zmianie ustawy o ochronie praw lokatorów, mieszkaniowym zasobie gminy i o zmianie Kodeksu cywilnego','2026-10-26T08:38:14+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"3234","title":"Poselski projekt ustawy o zmianie ustawy o ochronie praw lokatorów, mieszkaniowym zasobie gminy i o zmianie Kodeksu cywilnego","description":"projekt dotyczy wydłużenia o 4 lata okresu, w którym to na gminie spoczywa obowiązek zapewnienia najemcom prawa do lokalu zamiennego oraz pokrycia kosztów przeprowadzki w związku z koniecznością remontu lub rozbiórki budynków, który wymaga opróżnienia","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-12-20","document_date":"2024-12-20","change_date":"2026-10-26T08:38:14Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2024-12-20","print_number":"3234","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-01-02","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"STR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"INF","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2024-12-20","print_number":"3234","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-01-02","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"sta