INSERT INTO "bills" VALUES(10,'3245','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw','2026-10-22T07:42:25+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3245","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw","description":"projekt dotyczy odroczenia do końca 2027 r. nakładania kar pieniężnych za błędy związane z Krajowym Systemem e-Faktur (KSeF). Chodzi także o przedłużenie o 3,5 roku mechanizmu odwrotnego obciążenia VAT dla gazu, energii elektrycznej i uprawnień do emisji gazów cieplarnianych. Proponowane przepisy ułatwią przedsiębiorcom dostosowanie się do nowego systemu oraz zapewnią większą przewidywalność prowadzenia działalności gospodarczej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-20","document_date":"2026-10-20","change_date":"2026-10-22T07:42:25Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-181-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-181-26","prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-10-20T18:01:39+00:00','2026-10-23T17:54:29+00:00','{"term":10,"number":"RPW/35304/2026","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zmianie ustawy o podatku od towarów i usług oraz niektórych innych ustaw","description":"odroczenia do końca 2027 r. nakładania kar pieniężnych za błędy związane z Krajowym Systemem e-Faktur (KSeF). Chodzi także o przedłużenie o 3,5 roku mechanizmu odwrotnego obciążenia VAT dla gazu, energii elektrycznej i uprawnień do emisji gazów cieplarnianych. Proponowane przepisy ułatwią przedsiębiorcom dostosowanie się do nowego systemu oraz zapewnią większą przewidywalność prowadzenia działalności 