INSERT INTO "bills" VALUES(10,'3232','Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce','2026-10-20T09:10:49+00:00',NULL,0,'skipped_text_prefilter','["text:legalizacja"]','{"term":10,"number":"3232","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce","description":"projekt dotyczy wprowadzenia możliwości potwierdzenia przez uczelnię danych zawartych w wydanym w postaci papierowej dyplomie ukończenia studiów, jeśli pracodawca ma uzasadnione wątpliwości co do ich prawdziwości. Dzięki zmianom pracodawcy zyskają narzędzie, które pozwoli sprawdzić, czy informacje przedstawione przez kandydata do pracy lub pracownika są zgodne z dokumentacją uczelni. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-20T09:10:49Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-172-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-172-26","prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-08","print_number":"3232","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"ENM","sub_committee":false,"committee_name":"Komisja Edukacji i Nauki","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]}]}]','fbf7945aa4d4d1161744184dc101f6f8a5234fa8e0d54dea3683cd475f49b534',NULL,0,'text prefilter: weak patterns only (legalizacja×2)','2026-10-20T18:03:36+00:00','2026-10-21T18:07:13+00:00','{"term":10,"number":"RPW/33928/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce","description":"wprowadzenia możliwości potwierdzenia przez uczelnię danych zawartych w wydanym w postaci papierowej dyplomie ukończenia studiów, jeśli pracodawca ma uzasadnione wątpliwości co do ich prawdziwości. Dzięki zmianom pracodawcy zyskają narzędzie, które pozwoli sprawdzić, czy informacje przedstawione przez kandydata do pracy lub pracownika są zgodne z dokumentacją uczelni. Nowe przepisy realizują działania deregulacyjne rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-08","print_number":"3232","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/33928/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-08","print_number":"3232","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"ENM","sub_committee":false,"committee_name":"Komisja Edukacji i Nauki","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3233','Rządowy projekt ustawy o uregulowaniu praw do niektórych gruntów znajdujących się we władaniu spółdzielni mieszkaniowych','2026-10-20T09:21:13+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3233","title":"Rządowy projekt ustawy o uregulowaniu praw do niektórych gruntów znajdujących się we władaniu spółdzielni mieszkaniowych","description":"projekt dotyczy rozwiązania problemu gruntów, z których spółdzielnie mieszkaniowe korzystają od wielu lat, ale nie mają do nich trwałego tytułu prawnego. Nowe przepisy mają umożliwić przyznanie spółdzielniom praw do takich nieruchomości.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-20T09:21:13Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-151-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-151-26","prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-08","print_number":"3233","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"STR","sub_committee":false,"committee_name":"Komisja Samorządu Terytorialnego i Polityki Regionalnej","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]}]}]','8578b4a3e8e6c23e00e10f6eaefb85447b71f9e560257354dc842c9a37cd3af2',NULL,0,'text prefilter: no keyword hits','2026-10-20T18:03:36+00:00','2026-10-21T18:07:13+00:00','{"term":10,"number":"RPW/33930/2026","title":"Rządowy projekt ustawy o uregulowaniu praw do niektórych gruntów znajdujących się we władaniu spółdzielni mieszkaniowych","description":"rozwiązania problemu gruntów, z których spółdzielnie mieszkaniowe korzystają od wielu lat, ale nie mają do nich trwałego tytułu prawnego. Nowe przepisy mają umożliwić przyznanie spółdzielniom praw do takich nieruchomości.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-08","print_number":"3233","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/33930/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-08","print_number":"3233","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"STR","sub_committee":false,"committee_name":"Komisja Samorządu Terytorialnego i Polityki Regionalnej","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"INF","sub_committee":false,"committee_name":"Komisja Infrastruktury","children":[]}]}],"passed":false,"analysis_revision":0}',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3231','Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw','2026-10-20T09:04:06+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obcokrajowcy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany"]','{"term":10,"number":"3231","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw","description":"projekt dotyczy zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-08","document_date":"2026-10-08","change_date":"2026-10-20T09:04:06Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-170-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-170-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-08","print_number":"3231","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"DER","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"ENM","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-08","print_number":"3231","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-20","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-20","committee_code":"ENM","sub_committee":false,"committee_name":"Komisja Edukacji i Nauki","children":[]}]}]','ce84531a49b298be4c7ea39e83097baaf00de88b348952a502180b6584011449','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.","key_changes":["Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией","Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии","Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS","Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу","Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты"],"affected_groups":["иностранные докторанты польских школ докторантских","иностранцы, завершившие обучение в школе докторантской и готовящие защиту","вузы и научные учреждения, ведущие школы докторантские с иностранцами"],"practical_impact":"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.","effective_date":"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.","confidence":0.93,"rationale":"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).","mnemonic_candidate":"","mnemonic_fallback":"","mnemonic_basis":"","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v10","input_chars":68211,"truncated":false,"text_source":"pdf","created_at":"2026-10-09T07:38:31Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:cbeb72dab45a6fe6d2941439b13e6dac6816abe9f3dc30fa6b9ba1da034e00f0","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":["sejm/10/print/3231"],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf","members":[],"container_sha256":"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7","sha256":"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7","role":"bill","text":"","pages":83,"page_start":1,"page_end":83,"text_start":0,"text_end":252394,"text_sha256":"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9","losses":[]}],"observed_parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf","members":[],"container_sha256":"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7","sha256":"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7","role":"bill","text":"","pages":83,"page_start":1,"page_end":83,"text_start":0,"text_end":252394,"text_sha256":"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"sejm/10/print/3231","provenance":"source_relation","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf","text_sha256":"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf","text_sha256":"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9","block_id":"part:0","start":0,"end":898,"quote":"Druk nr 3231\n Warszawa, 8 października 2026 r.\nSEJM\nRZECZYPOSPOLITEJ POLSKIEJ\nX kadencja\n\nPrezes Rady Ministrów\nRM-0610-170-26\n\n Pan\n Włodzimierz Czarzasty\n Marszałek Sejmu\n Rzeczypospolitej Polskiej\n\nSzanowny Panie Marszałku,\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam\nSejmowi Rzeczypospolitej Polskiej projekt ustawy\n\n - o zmianie ustawy - Prawo o szkolnictwie\nwyższym i nauce oraz niektórych innych ustaw.\n\nProjekt ma charakter deregulacyjny.\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac parlamentarnych\nzostał upoważniony Minister Nauki i Szkolnictwa Wyższego.\n\n Z poważaniem\n Donald Tusk\n /podpisano kwalifikowanym podpisem elektronicznym/\n\n                Tłoczono z polecenia  Marszałka Sejmu Rzeczypospolitej Polskiej\n\n\fProjekt\nU S T AWA\nz dnia\no zmianie ustawy – Prawo o szkolnictwie wyższym i nauce oraz niektórych innych\nustaw1)\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf","text_sha256":"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9","block_id":"part:0","start":14153,"end":14175,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":252394,"page_start":1,"page_end":83,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":252394,"page_start":null,"page_end":null,"losses":[]}],"normative_sha25