INSERT INTO "bills" VALUES(10,'RPW/35455/2026','Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci','2026-10-21T00:00:00+00:00',NULL,NULL,'linked','["text:cudzoziemcy", "text:obywatele_ukrainy"]','{"term":10,"number":"RPW/35455/2026","title":"Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci","description":"automatycznego odnawiania prawa do świadczenia 800+ na kolejne okresy świadczeniowe, bez konieczności corocznego składania wniosków przez rodziców i opiekunów. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-21","document_date":"2026-10-21","change_date":"2026-10-21T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,'{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила пособия 800+: ZUS сам будет продлевать право на выплату на следующий год без ежегодной заявки, если ситуация семьи не изменилась. Расширяется круг получателей за счёт лиц, которым суд передал текущую опеку над ребёнком.","key_changes":["ZUS автоматически продляет право на 800+ на следующий период при наличии права на 31 мая","Новые получатели: лица с текущей опекой над ребёнком по решению польского суда","При изменении ситуации (в т.ч. выезд за границу) сохраняется обязанность сообщать в ZUS","Данные заявлений через банки и e‑системы можно хранить до 10 лет для рекламаций","Уточняются правила при одновременных заявках двух опекунов и при смерти опекуна"],"affected_groups":["иностранные родители с правом на świadczenie wychowawcze (800+)","иностранные опекуны детей по решению польского суда","иностранцы, являющиеся опекунами детей, указанных властями страны происхождения"],"practical_impact":"Иностранным семьям, уже получающим 800+, не придётся каждый год подавать новый электронный заявлений – ZUS сам продлит право, если нет изменений. Нужно внимательно сообщать ZUS о переезде за границу, смене состава семьи или опекуна, иначе могут возникнуть переплаты или отказ.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования, за исключением art. 1 pkt 4 lit. a, pkt 5, pkt 9 lit. a и pkt 10–13 и art. 3, которые вступают в силу 1 февраля 2027 г.","confidence":0.94,"rationale":"Проект меняет правила назначения и продления семейного пособия 800+, которое доступно не только гражданам Польши, поэтому это социально важное изменение для иностранцев с детьми.","mnemonic_candidate":"Автопродление 800 плюс","mnemonic_fallback":"Автопродление пособия 800+","mnemonic_basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":42107,"truncated":false,"text_source":"pdf","created_at":"2026-10-21T18:29:51Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35455-2026/$file/10-RPW-35455-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:22527ae36364ed66a6d55811671abc768d7227a14a181b8cdb67ec956852a927","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35455-2026/$file/10-RPW-35455-2026.pdf","members":[],"container_sha256":"0d783f9c2ae9a82ab1244bd0fcd82b49a235c9f4ab6c55bb07518045e10dc201","sha256":"0d783f9c2ae9a82ab1244bd0fcd82b49a235c9f4ab6c55bb07518045e10dc201","role":"bill","text":"","pages":62,"page_start":1,"page_end":62,"text_start":0,"text_end":110930,"text_sha256":"6af140db547368b6707230a94bbacfad1ad81815218d3de5f7a30af34236c021","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","prove