ieczności corocznego składania wniosków przez rodziców i opiekunów. Nowe przepisy realizują działania deregulacyjne rządu","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-21","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null,"senders_number":"RM-0610-171-26"}','3267',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,NULL,NULL,NULL,'full','relevant_analysis','{"mnemonic":{"name":"Автопродление 800 плюс","language":"ru","basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.","selected_at":"2026-10-21T18:29:51Z","origin":"analysis","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,NULL);
