INSERT INTO "bills" VALUES(10,'RPW/35344/2026','Komisyjny projekt ustawy o zmianie ustawy o referendum ogólnokrajowym','2026-10-21T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/35344/2026","title":"Komisyjny projekt ustawy o zmianie ustawy o referendum ogólnokrajowym","description":"dostosowania terminologii stosowanej w zmienianej ustawie do terminologii występującej w polskim systemie prawnym, zastępując termin: \"zakład pomocy społecznej\" prawidłowym terminem \"dom pomocy społecznej\" oraz termin \"szpital\" prawidłowym terminem \"zakład leczniczy\". Utrzymywanie stanu niespójności terminologicznej w systemie prawnym skutkuje brakiem możliwości uczestnictwa w referendum ogólnokrajowym osób przebywających w hospicjach.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-21","document_date":"2026-10-21","change_date":"2026-10-21T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"committee"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-10-21T18:07:14+00:00','2026-10-23T06:05:56+00:00','{"term":10,"number":"RPW/35344/2026","title":"Komisyjny projekt ustawy o zmianie ustawy o referendum ogólnokrajowym","description":"dostosowania terminologii stosowanej w zmienianej ustawie do terminologii występującej w polskim systemie prawnym, zastępując termin: \"zakład pomocy społecznej\" prawidłowym terminem \"dom pomocy społecznej\" oraz termin \"szpital\" prawidłowym terminem \"zakład leczniczy\". Utrzymywanie stanu niespójności terminologicznej w systemie prawnym skutkuje brakiem możliwości uczestnictwa w referendum ogólnokrajowym osób przebywających w hospicjach.","applicant":"committee","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-21","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-10-22","consultation_end":"2026