INSERT INTO "bills" VALUES(10,'RPW/35640/2026','Poselski projekt ustawy o zmianie ustawy o Instytucie Pamięci Narodowej - Komisji Ścigania Zbrodni przeciwko Narodowi Polskiemu oraz niektórych innych ustaw','2026-10-22T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:migracja", "text:straz_graniczna", "text:deportacja", "text:obywatele_innych_panstw", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/35640/2026","title":"Poselski projekt ustawy o zmianie ustawy o Instytucie Pamięci Narodowej - Komisji Ścigania Zbrodni przeciwko Narodowi Polskiemu oraz niektórych innych ustaw","description":"kompleksowego uregulowania ochrony pamięci ofiar zbrodni popełnionych przez członków i współpracowników Organizacji Ukraińskich Nacjonalistów frakcji Bandery (OUN-B), Ukraińskiej Powstańczej Armii (UPA) oraz innych ukraińskich organizacji i formacji kolaborujących z Trzecią Rzeszą Niemiecką - w szczególności zbrodni ludobójstwa dokonanej na ludności polskiej na Wołyniu i w sąsiednich regionach II Rzeczypospolitej Polskiej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-22","document_date":"2026-10-22","change_date":"2026-10-22T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,'{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит уголовную ответственность за публичную пропаганду идеологии и символики ОУН‑Б и УПА, отрицание и прославление их преступлений. Для иностранцев такие действия станут отдельным основанием для решения о выдворении и многолетнем запрете въезда в Польшу.","key_changes":["Прямая криминализация идеологии и символики ОУН-Б и УПА в Kodeks karny","Кара за отрицание, похвалу и героизацию волынских преступлений в ustawa o IPN","Новые основания выдворения иностранца после приговора за такие преступления","Возможен занос иностранца в реестр нежелательных и запрет въезда до 5 лет","Запрет тратить польские госcредства (в т.ч. за рубежом) на прославление ОУН-Б/УПА"],"affected_groups":["иностранцы, публично продвигающие идеологию или символику ОУН-Б/УПА","иностранцы, отрицающие или прославляющие волынское преступление и другие описанные злодеяния","иностранные НКО и проекты, получающие польские госcредства"],"practical_impact":"Иностранец, публично прославляющий ОУН-Б/УПА или отрицающий описанные в законе преступления, может получить уголовный приговор, после чего воевода вынесет решение о выезде с запретом въезда на 3–5 лет. Даже без приговора такие действия могут привести к занесению в реестр нежелательных и запрету въезда до 5 лет, а проекты не получат польское госфинансирование.","effective_date":"Через 30 дней после опубликования, кроме норм о названиях и памятниках, которые вступают в силу через 3 месяца после опубликования.","confidence":0.93,"rationale":"Проект прямо меняет ustawę o cudzoziemcach, вводя новые основания для решения о возвращении и запрете въезда иностранцев за пропаганду идеологии ОУН-Б/УПА и отрицание или прославление связанных с ними преступлений.","mnemonic_candidate":"Депортация за УПА","mnemonic_fallback":"Выдворение за УПА","mnemonic_basis":"Проект добавляет в ustawę o cudzoziemcach отдельное основание для решения о возвращении и запрете въезда за преступления, связанные с идеологией или символикой ОУН-Б/УПА и отрицанием их зločинów.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":48328,"truncated":true,"text_source":"pdf","created_at":"2026-10-23T18:21:00Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:ee1a33cdce683dffb0cc9c49bd99ff6619e9c2a702c9a98db0f4ef525622cfe9","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf","members":[],"container_sha256":"9a8d3709ce89cdf307d21392082f7bc25342ca86d1f22e641e9586aa8d5b66a6","sha256":"9a8d3709ce89cdf307d21392082f7bc25342ca86d1f22e641e9586aa8d5b66a6","role":"bill","text":"","pages":24,"page_start":1,"page_end":24,"text_start":0,"text_end":48328,"text_sha256":"568ace2a76b0b32ce9455786b2c186e0cd8265507ddf72260d319613b983fef7","losses":["text page coverage differs from the PDF page count"]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf","text_sha256":"568ace2a76b0b32ce9455786b2c186e0cd8265507ddf72260d319613b983fef7","block_id":"part:0","start":0,"end":181,"quote":"1\n\nProjekt\nUSTAWA\nz dnia …………………… 2026 r.\no zmianie ustawy o Instytucie Pamięci Narodowej – Komisji Ścigania Zbrodni przeciwko\nNarodowi Polskiemu oraz niektórych innych ustaw\nArt. 1"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":48328,"page_start":1,"page_end":24,"losses":["text page coverage differs from the PDF page count"]},{"part_index":0,"stage":"analysis","start":0,"end":48328,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"b113474d7b94bc20bf3b81e7ac2f238f635fc41154e574967a3b871ca87e119e"},"law_sha256":"law-v2:2ba1e1aa4180b97f67e338b498bb3be748fb0090e996fa97194c6ce4ab3de8a2","source_checked_at":"2026-10-23T18:21:00Z"}',0,NULL,'2026-10-22T18:02:39+00:00','2026-10-24T11:20:58+00:00','{"term":10,"number":"RPW/35640/2026","title":"Poselski projekt ustawy o zmianie ustawy o Instytucie Pamięci Narodowej - Komisji Ścigania Zbrodni przeciwko Narodowi Polskiemu oraz niektórych innych ustaw","description":"kompleksowego uregulowania ochrony pamięci ofiar zbrodni popełnionych przez członków i współpracowników Organizacji Ukraińskich Nacjonalistów frakcji Bandery (OUN-B), Ukraińskiej Powstańczej Armii (UPA) oraz innych ukraińskich organizacji i formacji kolaborujących z Trzecią Rzeszą Niemiecką - w szczególności zbrodni ludobójstwa dokonanej na ludności polskiej na Wołyniu i w sąsiednich regionach II Rzeczypospolitej Polskiej","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-22","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-10-23","consultation_end":"2026-11-22","consultation_results":false,"withdrawn_date":null,"senders_number":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Депортация за УПА","language":"ru","basis":"Проект добавляет в ustawę o cudzoziemcach отдельное основание для решения о возвращении и запрете въезда за преступления, связанные с идеологией или символикой ОУН-Б/УПА и отрицанием их зločинów.","selected_at":"2026-10-23T18:21:00Z","origin":"analysis","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,NULL);
