INSERT INTO "bills" VALUES(10,'3268','Poselski projekt ustawy o zmianie ustawy - Kodeks karny','2026-10-06T22:00:00+00:00',NULL,0,'skipped_text_prefilter','["text:uznawanie_kwalifikacji"]','{"term":10,"number":"3268","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks karny","description":"projekt dotyczy rozszerzenia i doprecyzowania zakresu odpowiedzialności karnej za nadużycia związane z wykorzystaniem technik cyfrowych, w szczególności sztucznej inteligencji do produkcji treści o charakterze pornograficznym, a także używanych w celu pokrzywdzenia indywidualnych osób prezentowanych w sytuacjach intymnych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-07","document_date":"2026-10-07","change_date":"2026-10-06T22:00:00Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-07","print_number":"3268","sub_committee":false,"children":[]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-07","print_number":"3268","sub_committee":false,"children":[]}]','93a61980fb01f5af967d3302ff2bb5c9d6f0e8e5a489ed6a2823d1ae9d02cd8d',NULL,0,'text prefilter: under the threshold of 2 distinct patterns (uznawanie_kwalifikacji×1)','2026-10-23T17:57:08+00:00','2026-10-23T17:57:08+00:00','{"term":10,"number":"RPW/33663/2026","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks karny","description":"rozszerzenia i doprecyzowania zakresu odpowiedzialności karnej za nadużycia związane z wykorzystaniem technik cyfrowych, w szczególności sztucznej inteligencji do produkcji treści o charakterze pornograficznym, a także używanych w celu pokrzywdzenia indywidualnych osób prezentowanych w sytuacjach intymnych","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-07","print_number":"3268","eu_related":false,"public_consultation":true,"consultation_s