INSERT INTO "bills" VALUES(10,'3266','Rządowy projekt ustawy o sprawiedliwym dostępie do danych i ich wykorzystywaniu','2026-10-23T07:56:46+00:00',NULL,0,'analyzed','["text:prawnicy_zagraniczni"]','{"term":10,"number":"3266","title":"Rządowy projekt ustawy o sprawiedliwym dostępie do danych i ich wykorzystywaniu","description":"projekt dotyczy wprowadzenia przepisów, które zapewnią stosowanie unijnych zasad dostępu do danych i ich wykorzystywania. Chodzi m.in. o dane w urządzeniach podłączonych do internetu. Prezes Urzędu Komunikacji Elektronicznej będzie odpowiadał za nadzór nad przestrzeganiem tych zasad, rozpatrywanie skarg i certyfikowanie podmiotów rozstrzygających spory. Obowiązki informacyjne wobec Komisji Europejskiej będzie realizował Minister Cyfryzacji","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-19","document_date":"2026-10-19","change_date":"2026-10-23T07:56:46Z","passed":false,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-175-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-175-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-19","print_number":"3266","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"CNT","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-19","print_number":"3266","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-22","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-22","committee_code":"CNT","sub_committee":false,"committee_name":"Komisja Cyfryzacji, 