INSERT INTO "bills" VALUES(10,'3267','Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci','2026-10-23T08:00:19+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatele_ukrainy"]','{"term":10,"number":"3267","title":"Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci","description":"projekt dotyczy automatycznego odnawiania prawa do świadczenia 800+ na kolejne okresy świadczeniowe, bez konieczności corocznego składania wniosków przez rodziców i opiekunów. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-21","document_date":"2026-10-21","change_date":"2026-10-23T08:00:19Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-171-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-171-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-21","print_number":"3267","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-23","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"DER","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"PSR","sub_committee":false,"children":[]}]}]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-21","print_number":"3267","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-23","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}]','6f6e3ae86f5d407e67eaf58af72d3f309ba2be2fd7f7647cf55136c5de6d5171','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект меняет правила пособия 800+: ZUS сам будет продлевать право на выплату на следующий год без ежегодной заявки, если ситуация семьи не изменилась. Расширяется круг получателей за счёт лиц, которым суд передал текущую опеку над ребёнком.","key_changes":["ZUS автоматически продляет право на 800+ на следующий период при наличии права на 31 мая","Новые получатели: лица с текущей опекой над ребёнком по решению польского суда","При изменении ситуации (в т.ч. выезд за границу) сохраняется обязанность сообщать в ZUS","Данные заявлений через банки и e‑системы можно хранить до 10 лет для рекламаций","Уточняются правила при одновременных заявках двух опекунов и при смерти опекуна"],"affected_groups":["иностранные родители с правом на świadczenie wychowawcze (800+)","иностранные опекуны детей по решению польского суда","иностранцы, являющиеся опекунами детей, указанных властями страны происхождения"],"practical_impact":"Иностранным семьям, уже получающим 800+, не придётся каждый год подавать новый электронный заявлений – ZUS сам продлит право, если нет изменений. Нужно внимательно сообщать ZUS о переезде за границу, смене состава семьи или опекуна, иначе могут возникнуть переплаты или отказ.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования, за исключением art. 1 pkt 4 lit. a, pkt 5, pkt 9 lit. a и pkt 10–13 и art. 3, которые вступают в силу 1 февраля 2027 г.","confidence":0.94,"rationale":"Проект меняет правила назначения и продления семейного пособия 800+, которое доступно не только гражданам Польши, поэтому это социально важное изменение для иностранцев с детьми.","mnemonic_candidate":"Автопродление 800 плюс","mnemonic_fallback":"Автопродление пособия 800+","mnemonic_basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":42107,"truncated":false,"text_source":"pdf","created_at":"2026-10-21T18:29:51Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:b7ffd62485a003e71abc7e0e14af829f3984c046ea7842afd99c0ee6848e388b","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":["sejm/10/print/3267"],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf","members":[],"container_sha256":"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7","sha256":"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7","role":"bill","text":"","pages":62,"page_start":1,"page_end":62,"text_start":0,"text_end":110974,"text_sha256":"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1","losses":[]}],"observed_parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf","members":[],"container_sha256":"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7","sha256":"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7","role":"bill","text":"","pages":62,"page_start":1,"page_end":62,"text_start":0,"text_end":110974,"text_sha256":"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"sejm/10/print/3267","provenance":"source_relation","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf","text_sha256":"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf","text_sha256":"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1","block_id":"part:0","start":0,"end":896,"quote":"Druk nr 3267\n Warszawa, 21 października 2026 r.\nSEJM\nRZECZYPOSPOLITEJ POLSKIEJ\nX kadencja\n\nPrezes Rady Ministrów\nRM-0610-171-26\n\n Pan\n Włodzimierz Czarzasty\n Marszałek Sejmu\n Rzeczypospolitej Polskiej\n\nSzanowny Panie Marszałku,\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam\nSejmowi Rzeczypospolitej Polskiej projekt ustawy\n - o zmianie ustawy o pomocy państwa\nw wychowywaniu dzieci.\nProjekt ma charakter deregulacyjny oraz realizuje priorytet polityki Rady\nMinistrów.\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac parlamentarnych\nzostał upoważniony Minister Rodziny, Pracy i Polityki Społecznej.\n\n Z poważaniem\n Donald Tusk\n /podpisano kwalifikowanym podpisem elektronicznym/\n\n                Tłoczono z polecenia  Marszałka Sejmu Rzeczypospolitej Polskiej\n\n\fProjekt\nU S T A W A\nz dnia\no zmianie ustawy o pomocy państwa w wychowywaniu dzieci\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":110974,"page_start":1,"page_end":62,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":110974,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"9cf5073592f18aec715743c63b65fc105ceff9234d544d31de33b89df3ea49c8"},"law_sha256":"law-v2:d83673b42b2f9050ba6a6fd9c844cfb417f84b6296f185c3820ff266c9006c2b","source_checked_at":"2026-10-23T18:03:17Z"}',0,NULL,'2026-10-23T17:57:12+00:00','2026-10-28T19:18:36+00:00','{"term":10,"number":"RPW/35455/2026","title":"Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci","description":"automatycznego odnawiania prawa do świadczenia 800+ na kolejne okresy świadczeniowe, bez konieczności corocznego składania wniosków przez rodziców i opiekunów. Nowe przepisy realizują działania deregulacyjne rządu","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-21","print_number":"3267","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null,"senders_number":"RM-0610-171-26"}','RCL/12409404',NULL,NULL,NULL,NULL,NULL,NULL,'UDER106',NULL,'[]',NULL,NULL,'{"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-10-21","print_number":"3267","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-10-23","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"DER","sub_committee":false,"committee_name":"Komisja do Spraw Deregulacji","children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-10-23","committee_code":"PSR","sub_committee":false,"committee_name":"Komisja Polityki Społecznej i Rodziny","children":[]}]}],"passed":false,"document":{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf","kind":"print","extra_urls":[],"alternatives":[],"compare_versions":false,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":[],"official_link_conflict":false},"analysis_sha256":"text-v2:b7ffd62485a003e71abc7e0e14af829f3984c046ea7842afd99c0ee6848e388b","analysis_revision":1,"seen_supplements":[]}',2,NULL,NULL,NULL,'full','telegram_thread','{"mnemonic":{"name":"Автообновление 800+","language":"ru","basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze (800+) без повторной заявки для лиц, уже получающих выплату.","selected_at":"2026-10-14T16:08:45Z","origin":"analysis","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":{"name":"Автопродление 800 плюс","language":"ru","basis":"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.","selected_at":"2026-10-21T18:29:51Z","origin":"analysis","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"priority":null,"priority_history":[],"announced_version":1}',NULL,NULL,NULL,NULL,'[]');
