INSERT INTO "bills" VALUES(10,'RCL/12416153','Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz niektórych innych ustaw','2026-10-27T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:straz_graniczna"]','{"term":10,"number":"RCL/12416153","title":"Projekt ustawy o zmianie ustawy – Kodeks postępowania karnego oraz niektórych innych ustaw","description":"KARNE POSTĘPOWANIE; sprawiedliwość","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-27","document_date":"2026-10-27","change_date":"2026-10-27T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12416153","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","date":"2026-10-27","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","date":"2026-10-27","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","date":"2026-10-27","sub_committee":false,"children":[]}]','ae67ea29166643d581c56b261233f25c8ee2f44970a3f954653dd6fbdb52e8e0','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Вводится новый мер пресечения – электронный арест с браслетом вместо СИЗО. В законе о cudzoziemcach такой арест приравнивается к тюрьме/СИЗО при решениях по разрешениям на проживание и обмену информацией между органами.","key_changes":["Появляется новый мер пресечения: электронный арест с браслетом вместо СИЗО.","Во всех нормах о cudzoziemcach электронный арест приравнен к тюрьме и СИЗО.","При электронном аресте органы сообщают об этом в делах по легализации пребывания.","Электронный арест учитывается как негативный фактор при ряде решений по проживанию.","За явно незаконный электронный арест можно требовать компенсацию как за СИЗО."],"affected_groups":["иностранцы, в отношении которых ведётся уголовное производство в Польше","иностранцы, подающие заявки на разные виды разрешений на пребывание","иностранцы, находящиеся в тюрьме, СИЗО или под электронным арестом"],"practical_impact":"Для иностранцев, подозреваемых в преступлении, может применяться домашний арест с браслетом вместо СИЗО, но для миграционных органов он считается тем же лишением свободы. Такой статус может повлиять на получение или продление разрешения на проживание и фиксируется в обмене данными между ведомствами.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня его официального опубликования.","confidence":0.93,"rationale":"Проект прямо меняет ustawę o cudzoziemcach, приравнивая новый электронный арест к тюрьме/СИЗО при решениях по статусу пребывания, что напрямую затрагивает легализацию пребывания иностранцев.","mnemonic_candidate":"Браслет и вид на жительство","mnemonic_fallback":"Электронный арест и ВНЖ","mnemonic_basis":"В законе о cudzoziemcach электронный арест добавлен рядом с тюрьмой и СИЗО как основание и информация для решений по делам иностранцев.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":265334,"truncated":false,"text_source":"documents","created_at":"2026-10-27T19:14:06Z","computation_id":"result-v1:1cc652dfa4d7e78687b70c378641ff4c03ef5a092324c0adb67bd38f6e454600","request_sha256":"9b039854d3f69de8f6060c5c005880a9fec342118e00b97cd48d3a4787ee563e","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","source_kind":"rcl","revision":1,"text_sha256":"text-v2:ff2d354564f8f56cb7ffffb34bd5f734e6a4a1a9708056134777fa67b95021a9","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"selected","belonging":[],"role":[],"version":["rcl/12416153/stage/13234331","Projekt ustawy UD256.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","members":[],"container_sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":89591,"text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804263.docx","members":[],"container_sha256":"d5e6709a2fc2fe96408e650d8b03790de7e1032de7396a1c46391bcd9317b3f9","sha256":"d5e6709a2fc2fe96408e650d8b03790de7e1032de7396a1c46391bcd9317b3f9","role":"justification","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":128215,"text_sha256":"1be816a45ee4eed036c13a2f9187bd27af417291ac102e88354e4333609a75c2","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804264.docx","members":[],"container_sha256":"5e2d8f15709bae8fe21d896ab72af9fa366e9b460c1ab679fc7eed95be36ddef","sha256":"5e2d8f15709bae8fe21d896ab72af9fa366e9b460c1ab679fc7eed95be36ddef","role":"osr","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":143569,"text_sha256":"a69b62b10f690a2900f6af69663341ad6d3d81100350c883f391051bdaea2a40","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","members":[],"container_sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":89591,"text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12416153/stage/13234331","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":3363,"quote":"Projekt z 26 października 2026 r.\nustawa\nz dnia …\no zmianie ustawy – Kodeks postępowania karnego oraz niektórych innych ustaw [przypis 1: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 14 czerwca 1960 r. − Kodeks postępowania administracyjnego, ustawę z dnia 17 listopada 1964 r. − Kodeks postępowania cywilnego, ustawę z dnia 20 maja 1971 r. – Kodeks wykroczeń, ustawę z dnia 26 czerwca 1974 r. − Kodeks pracy, ustawę z dnia 26 stycznia 1982 r. − Karta Nauczyciela, ustawę z dnia 26 maja 1982 r. – Prawo o adwokaturze, ustawę z dnia 6 lipca 1982 r. o radcach prawnych, ustawę z dnia 16 września 1982 r. o pracownikach urzędów państwowych, ustawę z dnia 8 marca 1990 r. o samorządzie gminnym, ustawę z dnia 6 kwietnia 1990 r. o Policji, ustawę z dnia 12 października 1990 r. o Straży Granicznej, ustawę z dnia 24 sierpnia 1991 r. o Państwowej Straży Pożarnej, ustawę z dnia 23 grudnia 1994 r. o Najwyższej Izbie Kontroli, ustawę z dnia 6 czerwca 1997 r. – Kodeks karny, ustawę z dnia 6 czerwca 1997 r. − Kodeks karny wykonawczy, ustawę z dnia 29 sierpnia 1997 r. – Ordynacja podatkowa, ustawę z dnia 10 września 1999 r. − Kodeks karny skarbowy, ustawę z dnia 23 września 1999 r. o zasadach pobytu wojsk obcych na terytorium Rzeczypospolitej Polskiej, zasadach ich przemieszczania się przez to terytorium oraz zasadach udzielania pomocy wojskom sojuszniczym i organizacjom międzynarodowym, ustawę z dnia 30 czerwca 2000 r. – Prawo własności przemysłowej, ustawę z dnia 27 lipca 2001 r. o kuratorach sądowych, ustawę z dnia 24 sierpnia 2001 r. – Kodeks postępowania w sprawach o wykroczenia, ustawę z dnia 24 maja 2002 r. o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawę z dnia 30 sierpnia 2002 r. − Prawo o postępowaniu przed sądami administracyjnymi, ustawę z dnia 17 czerwca 2004 r. o skardze na naruszenie prawa strony do rozpoznania sprawy w postępowaniu przygotowawczym prowadzonym lub nadzorowanym przez prokuratora i postępowaniu sądowym bez nieuzasadnionej zwłoki, ustawę z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, ustawę z dnia 9 czerwca 2006 r. o służbie funkcjonariuszy Służby Kontrwywiadu Wojskowego oraz Służby Wywiadu Wojskowego, ustawę z dnia 9 czerwca 2006 r. o Centralnym Biurze Antykorupcyjnym, ustawę z dnia 13 kwietnia 2007 r. o Państwowej Inspekcji Pracy, ustawę z dnia 21 listopada 2008 r. o pracownikach samorządowych, ustawę z dnia 21 listopada 2008 r. o służbie cywilnej, ustawę z dnia 27 sierpnia 2009 r. o finansach publicznych, ustawę z dnia 9 kwietnia 2010 r. o Służbie Więziennej, ustawę z dnia 30 kwietnia 2010 r. o instytutach badawczych, ustawę z dnia 30 kwietnia 2010 r. o Polskiej Akademii Nauk, ustawę z dnia 25 czerwca 2010 r. o sporcie, ustawę z dnia 24 maja 2013 r. o środkach przymusu bezpośredniego i broni palnej, ustawę z dnia 12 grudnia 2013 r. o cudzoziemcach, ustawę z dnia 16 listopada 2016 r. o Krajowej Administracji Skarbowej, ustawę z dnia 15 grudnia 2016 r. o Prokuratorii Generalnej Rzeczypospolitej Polskiej, ustawę z dnia 8 grudnia 2017 r. o Służbie Ochrony Państwa, ustawę z dnia 26 stycznia 2018 r. o Straży Marszałkowskiej, ustawę z dnia 20 lipca 2018 r. – Prawo o szkolnictwie wyższym i nauce, ustawę z dnia 18 listopada 2020 r. o doręczeniach elektronicznych oraz ustawę z dnia 11 marca 2022 r. o obronie Ojczyzny.] )\nArt. 1"},{"kind":"draft_date","value":"2026-10-26","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234