INSERT INTO "bills" VALUES(10,'3278','Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o systemie oświaty oraz niektórych innych ustaw oraz ustawę o rynku pracy i służbach zatrudnienia','2026-10-29T14:07:32+00:00',NULL,0,'skipped_text_prefilter','["text:obywatele_ukrainy"]','{"term":10,"number":"3278","title":"Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o systemie oświaty oraz niektórych innych ustaw oraz ustawę o rynku pracy i służbach zatrudnienia","description":"projekt dotyczy zwiększenia limitów środków na przygotowanie i przeprowadzenie egzaminu ósmoklasisty i egzaminu maturalnego, a także egzaminów zawodowych oraz eksternistycznych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-28","document_date":"2026-10-28","change_date":"2026-10-29T14:07:32Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-189-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-189-26","prints_considered_jointly":[],"applicant":"government"}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (obywatele_ukrainy×2)','2026-10-29T19:00:06+00:00','2026-10-29T19:00:06+00:00','{"term":10,"number":"RPW/36433/2026","title":"Rządowy projekt ustawy zmieniającej ustawę o zmianie ustawy o systemie oświaty oraz niektórych innych ustaw oraz ustawę o rynku pracy i służbach zatrudnienia","description":"zwiększenia limitów środków na przygotowanie i przeprowadzenie egzaminu ósmoklasisty i egzaminu maturalnego, a także egzaminów zawodowych oraz eksternistycznych","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-28","print_number":"3278","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null,"senders_number":"RM-0610-189-26"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NUL