INSERT INTO "bills" VALUES(10,'RPW/36403/2026','Poselski projekt ustawy o zmianie ustawy o pomocy społecznej','2026-10-28T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:ochrona_miedzynarodowa", "text:status_uchodzcy", "text:uznawanie_kwalifikacji"]','{"term":10,"number":"RPW/36403/2026","title":"Poselski projekt ustawy o zmianie ustawy o pomocy społecznej","description":"wprowadzenia corocznej weryfikacji kryteriów dochodowych uprawniających do świadczeń z pomocy społecznej, począwszy od 2028 r., ze skutkiem w zakresie wysokości kryteriów od dnia 1 stycznia 2029 r.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-10-28","document_date":"2026-10-28","change_date":"2026-10-28T00:00:00Z","eu_related":false,"prints_considered_jointly":[],"applicant":"deputies"}',NULL,NULL,'{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Доходные пороги для социальной помощи пересматриваются ежегодно вместо одного раза в три года. Это также касается размеров помощи на содержание и изучение польского для беженцев, получателей дополнительной защиты и обладателей прямо указанного временного ВНЖ.","key_changes":["Доходные пороги социальной помощи пересматриваются ежегодно на основе исследования необходимых расходов.","Минимум и максимум помощи на содержание и изучение польского меняются на 50% суммы прироста двух доходных порогов.","Для расчёта берётся прирост порогов для одиноко проживающего человека и на одного члена семьи.","В те же сроки по той же формуле меняются максимум постоянного пособия и база помощи на самостоятельную жизнь и учёбу.","Первый пересмотр — в 2028 году; пересмотренные пороги и суммы применяются с 1 января следующего года, впервые — 2029 года."],"affected_groups":["Иностранцы, имеющие право на социальную помощь, зависящую от дохода","Иностранцы, получившие в Польше статус беженца","Иностранцы, получившие в Польше дополнительную защиту","Иностранцы с временным ВНЖ по ст. 159 ч. 1 п. 1 подп. c или d ustawa o cudzoziemcach (закона об иностранцах)"],"practical_impact":"Для имеющих право на помощь иностранцев доходные пороги и связанные с ними суммы пересматриваются каждый год. Для перечисленных получателей интеграционной помощи ежегодно пересчитываются её минимум и максимум; фиксированного процента ежегодного повышения законопроект не устанавливает.","effective_date":"Закон вступает в силу 1 января 2028 года.","confidence":0.99,"rationale":"Оценка 3 и социальная категория обусловлены изменением периодичности пересмотра доходных порогов и размеров выплат, прямо предусмотренных для перечисленных групп иностранцев.","mnemonic_candidate":"Ежегодный пересчёт интеграционной помощи","mnemonic_fallback":"Ежегодный пересмотр интеграционных выплат","mnemonic_basis":"Минимальные и максимальные выплаты на содержание и изучение польского для перечисленных иностранцев меняются в сроки ежегодного пересмотра доходных порогов.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-6.1-sol","prompt_version":"2026-10-v13","input_chars":51065,"truncated":false,"text_source":"pdf","created_at":"2026-10-29T19:12:03Z","computation_id":"result-v1:45ce3e693670caf73d3b4cc5a1d3aa30f0c712feaae7355394d0019d2453e90d","request_sha256":"7197fa9f053f0fd1a3d0e42e51235ea96f5b05a147102543de262b9626b7e6ed","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:ec5f5cd9ba7f09699205920e7723ad7a085f20d30da370bf757ce6197fc22bd5","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf","members":[],"container_sha256":"0465f82b7ac8c54dc0fa30bb433c31a38b489b64e6c68e139217f5409f7fe675","sha256":"0465f82b7ac8c54dc0fa30bb433c31a38b489b64e6c68e139217f5409f7fe675","role":"bill","text":"","pages":21,"page_start":1,"page_end":21,"text_start":0,"text_end":51065,"text_sha256":"4e65ecca9eadf5304fda125ba3f5aa4fc9ccf16436e2aaec8136731231c94c1b","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf","text_sha256":"4e65ecca9eadf5304fda125ba3f5aa4fc9ccf16436e2aaec8136731231c94c1b","block_id":"part:0","start":0,"end":85,"quote":"projekt\nUSTAWA\nz dnia ……………………….. 2027 r.\no zmianie ustawy o pomocy społecznej\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf","text_sha256":"4e65ecca9eadf5304fda125ba3f5aa4fc9ccf16436e2aaec8136731231c94c1b","block_id":"part:0","start":4184,"end":4206,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":51065,"page_start":1,"page_end":21,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":51065,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"b455255ecdafc49d32ba6176010e69657ffbc15ba95dc155eb4aab867d41e3af"},"law_sha256":"law-v2:af6a1bcdc36ed01168b930bb09045acbd23c7e96ed6318c3a3e3bd7ad8a9b415","source_checked_at":"2026-10-29T19:12:03Z"}',0,NULL,'2026-10-29T19:00:14+00:00','2026-10-29T19:00:14+00:00','{"term":10,"number":"RPW/36403/2026","title":"Poselski projekt ustawy o zmianie ustawy o pomocy społecznej","description":"wprowadzenia corocznej weryfikacji kryteriów dochodowych uprawniających do świadczeń z pomocy społecznej, począwszy od 2028 r., ze skutkiem w zakresie wysokości kryteriów od dnia 1 stycznia 2029 r.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-10-28","print_number":null,"eu_related":false,"public_consultation":true,"consultation_start":"2026-10-29","consultation_end":"2026-11-28","consultation_results":false,"withdrawn_date":null,"senders_number":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,'{"mnemonic":{"name":"Ежегодный пересчёт интеграционной помощи","language":"ru","basis":"Минимальные и максимальные выплаты на содержание и изучение польского для перечисленных иностранцев меняются в сроки ежегодного пересмотра доходных порогов.","selected_at":"2026-10-29T19:12:03Z","origin":"analysis","version":1,"provisional":false,"command_update_id":null,"actor_id":null,"author_signature":null},"previous":[],"proposed":null,"priority":null,"priority_history":[],"announced_version":0}',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12408601','Projekt ustawy o zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych innych ustaw','2026-10-29T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:migracja", "text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"RCL/12408601","title":"Projekt ustawy o zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych innych ustaw","description":"RODZINNE I OPIEKUŃCZE PRAWO; rodzina","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-26","document_date":"2026-03-26","change_date":"2026-10-29T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12408601","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','b4b6a1d4196e2182309dc514172d5b60ab6b074136e8252708772fb13296c2ca','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Меняются правила усыновления и приёмной опеки, в том числе для иностранцев. Предусмотрены переводчики, использование заключений из страны происхождения и проверки иностранных опекунов. Правила приёмной опеки охватывают также несовершеннолетних иностранцев в Польше вне перечисленных законом категорий.","key_changes":["Проверяемые иностранцы представляют сведения о несудимости и отсутствии запретов из реестра страны гражданства; проверки — не реже 24 месяцев.","Министр может выделить центр усыновления для иностранцев; другие центры сохраняют компетенцию и могут использовать заключения из страны происхождения.","При недостаточном польском допускается переводчик, в том числе на обучении; при усыновлении ребёнка из-за рубежа расходы несут кандидаты.","При усыновлении с выездом в страну Гаагской конвенции: согласие на отчёты ежегодно первые 3 года после вступления решения в силу, затем раз в 3 года до 18 лет.","Иностранному представителю зарубежного посредника по усыновлению нужен документ о знании польского; аккредитация посредника — максимум на 2 года."],"affected_groups":["Несовершеннолетние иностранцы, находящиеся в Польше, включая не перечисленных в статье 5, части 1, пунктах 2–6","Иностранцы — кандидаты в усыновители, приёмные родители и руководители семейных детских домов; для приёмных родителей требуется законное пребывание","Иностранцы в поддерживающих семьях, семьях временной подмены опекунов и семьях ухода за взрослыми; сотрудники, исполнители услуг, волонтёры и наставники воспитанников","Совместно проживающие с кандидатами в усыновители, приёмными семьями, руководителями семейных детских домов и семьями ухода; с поддерживающими и подменяющими семьями — при контакте с детьми","Представители зарубежных посредников и кандидаты в усыновители, проживающие за пределами Польши"],"practical_impact":"При усыновлении ребёнка супруга исключаются общий запрет судимости и проверка совместно проживающих. При ввозе усыновляемого ребёнка расходы на перевод в исключительных случаях, особенно при родстве, свойстве или объединении братьев и сестёр, может принять центр либо центральный орган. Для действующих зарубежных посредников: сведения о ранее отсутствовавшем представителе — за 3 месяца, подтверждение соответствия представителей требованиям — за 6 месяцев со вступления закона в силу.","effective_date":"«Закон вступает в силу 1 октября 2026 года, за исключением: 1) статьи 1, пункта 17, и статьи 25 — с 1 января 2027 года; 2) статьи 1, пункта 101, статьи 2, пункта 1, статьи 3, пунктов 3 и 4, статей 8, 10 и 11, а также статьи 12, пункта 2, статей 16, 20–22 и 24 — с 1 января 2028 года; 3) статьи 1, пункта 150, подпункта d, пункта 152, подпункта d, пункта 155, подпункта c, пункта 157, подпункта a, второго и шестого абзацев перечня, а также пункта 158, подпунктов a, f и g, в части использования информационной системы — со дня, определённого в объявлении, предусмотренном статьёй 72».","confidence":0.93,"rationale":"Оценка 3 и социальная категория обусловлены прямыми изменениями правил усыновления, приёмной опеки и проверки иностранцев, а не легализации их пребывания.","mnemonic_candidate":"Переводчик при усыновлении","mnemonic_fallback":"Перевод в процедуре усыновления","mnemonic_basis":"Добавляемая статья 169a допускает переводчика при недостаточном владении польским и регулирует расходы при усыновлении ребёнка с переездом в Польшу.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-6.1-sol","prompt_version":"2026-10-v13","input_chars":608481,"truncated":false,"text_source":"documents","created_at":"2026-10-29T19:12:03Z","computation_id":"result-v1:7abf53b9cf9baa9408a529918c05ad0692155a5eed622d8b4820582346da4f4d","request_sha256":"1fe039ec8ff4e37ff47e5282564600ea8cd4ed4bbdebe0df2f61e311b0364adf","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","source_kind":"rcl","revision":1,"text_sha256":"text-v2:193ed7229af7dcaf3d276ba2c825d6d03bb37cffe232b5613e8656a3b3a8aac1","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"selected","belonging":[],"role":[],"version":["rcl/12408601/stage/13194357","Projekt 20.03.2026."],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","members":[],"container_sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","role":"bill","text":"","pages":165,"page_start":1,"page_end":165,"text_start":0,"text_end":345959,"text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","losses":[]},{"url":"https://l