INSERT INTO "computation_results" VALUES('result-v1:072ab7e466c32fa05951bd10df3703bbdeb52cbf7892fa81b71c49f282914e77','openai','batch_6ae0caae37248190ad0743ebd8949af9','d97305165bf209dce93950b861b919206b516101299c87930707c7fde1754647',10,'WPL/UD491','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae0caae37248190ad0743ebd8949af9","custom_id":"d97305165bf209dce93950b861b919206b516101299c87930707c7fde1754647","purpose":"analysis","term":10,"number":"WPL/UD491","generation":1,"collected_at":"2026-10-27T16:29:23Z","input_binding":{"term":10,"number":"WPL/UD491","reuse_key":"40332aee9eb5117623ed323c797c999f78684278c5578ed0821ccb6cff90618a"},"request_sha256":"a1082c3fe7b938dd93b92ed42c420c90afcd9bcacd2deaa0169e34a1d5541590","validation":"validated","record":{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Планируются жёсткие изменения правил получения и восстановления польского гражданства. Для иностранцев вырастут требования к сроку проживания, знанию языка, доходам, жилью и проверкам безопасности, появится обязательный экзамен по Польше. Упрощённое восстановление гражданства будет доступно только до конца 2030 года.","key_changes":["Увеличение минимального срока легального проживания перед признанием гражданином","Обязательная клятва верности и экзамен по знанию Польши для заявителей","Требование центра жизненных интересов и налоговой резиденции в Польше","Минимальный доход, самодостаточность и обязательный титул к жилью","Закрытие упрощённого восстановления гражданства после 31.12.2030 и лёгкая отмена решений"],"affected_groups":["иностранцы, подающие на признание гражданином РП","лица, восстанавливающие польское гражданство","иностранцы польского происхождения и обладатели Карты Поляка","иностранцы с постоянным или долгосрочным пребыванием в Польше"],"practical_impact":"Получение гражданства станет сложнее: дольше ждать нужного стажа, сдавать экзамен, подтверждать язык на уровне B2, доходы и жильё. Упрощённое восстановление гражданства станет возможным лишь до 2030 года, а ранее выданные решения легче отменят при выявлении нарушений.","effective_date":null,"confidence":0.72,"rationale":"Проект прямо ужесточает материальные и процедурные условия получения и восстановления гражданства польского иностранцами, что является zmianą zasad legalizacji pobytu najwyższej wagi.","mnemonic_candidate":"Тест на гражданство","mnemonic_fallback":"Ужесточение гражданства","mnemonic_basis":"Проект вводит обязательный экзамен по знанию Польши и повышает уровень языка до B2 как ключевые условия получения гражданства.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":0,"truncated":false,"text_source":"metadata_only","created_at":"2026-10-27T16:29:23Z","computation_id":"result-v1:072ab7e466c32fa05951bd10df3703bbdeb52cbf7892fa81b71c49f282914e77","request_sha256":"a1082c3fe7b938dd93b92ed42c420c90afcd9bcacd2deaa0169e34a1d5541590","input_tokens":3379,"output_tokens":951,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":null,"source_kind":"metadata","revision":1,"text_sha256":null,"selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":"2026-10-27T16:29:23Z"},"model":"gpt-5.1-2025-11-13","usage":{"input":0,"output":0,"cache_read":0,"cache_creation":0,"batch_input":3379,"batch_output":951,"batch_cache_read":0,"batch_cache_creation":0},"error":null,"context_exceeded":false}');
INSERT INTO "computation_results" VALUES('result-v1:184f3d2e1a51b254cce761e69ab3ab3aa0a118601f3c0ea9569d23c374e85297','openai','batch_6ae0d26d2088819099f3c459cea4b69c','cf3da3533749a7fa22ea43fa45253f6c61421a5a35877ba8882b51e8688c8cf8',10,'3157','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae0d26d2088819099f3c459cea4b69c","custom_id":"cf3da3533749a7fa22ea43fa45253f6c61421a5a35877ba8882b51e8688c8cf8","purpose":"reanalysis","term":10,"number":"3157","generation":4,"collected_at":"2026-10-27T17:30:26Z","input_binding":{"term":10,"number":"3157","reuse_key":"98545f8a16da86ef940d1accfd4d75ecd823be7d7daeab8e6b2b0f7731a0c9ac"},"request_sha256":"c5813beb590fdb03b3a24f26d6f2fe41064c7c93e1b735b45e7b118abf5efe05","validation":"validated","record":{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Закон усиливает контроль NFZ над больницами и ограничивает время работы и максимальные ставки оплаты для врачей и медперсонала, работающих по контрактам NFZ. Вводится прямое право пациента на равное отношение и запрет дискриминации, в т.ч. по гражданству и национальности, а также реестр врачей, лишённых права работать за счёт NFZ.","key_changes":["В закон о правах пациента вводится право на равное обращение и запрет дискриминации, в т.ч. по гражданству","Медучреждения обязаны активно предотвращать дискриминацию пациентов по перечисленным признакам","Создаётся публичный реестр врачей с запретом на работу по контрактам NFZ и правила информирования пациентов","Ужесточается контроль NFZ и Agencja HTA: доступ к меддокументации, новые обязанности по передаче данных","Вводятся лимиты общего рабочего времени и максимального дохода медиков по контрактам NFZ, с обязанностью деклараций"],"affected_groups":["иностранцы‑пациенты, пользующиеся NFZ","иностранные врачи и другой медперсонал, работающие в Польше","медучреждения и частные практики с контрактами NFZ"],"practical_impact":"Иностранец‑пациент получает прямое право на недискриминацию из‑за гражданства и может жаловаться в Rzecznik Praw Pacjenta (омбудсмен по правам пациента). Иностранные медики должны вписаться в лимиты часов и оплаты по NFZ и правдиво декларировать занятость, иначе возможны штрафы и расторжение договоров.","effective_date":"Через месяц после опубликования, кроме ст. 1 п. 19, п. 25 (в части ст. 132ad) и п. 28 (в части ст. 193 ч. 1 п. 15–16 и распространения ч. 2 на эти пункты), ст. 2, ст. 3 п. 2–5 и ст. 4, которые вступают в силу через 6 месяцев после опубликования.","confidence":0.95,"rationale":"Закон прямо вводит право пациента на недискриминацию по гражданству и др. признакам и существенно меняет правила работы медиков в системе NFZ, что затрагивает как иностранных пациентов, так и иностранных врачей в социальной сфере.","mnemonic_candidate":"Антидискриминация пациентов","mnemonic_fallback":"Равное лечение пациентов","mnemonic_basis":"В ustawa o prawach pacjenta i Rzeczniku Praw Pacjenta добавлен art. 8a с правом на равное обращение и прямым запретом дискриминации, в т.ч. по obywatelstwo и narodowość.","mnemonic_language":"ru","changes_since_previous":["Подробно введён механизм запрета NFZ для врачей (zakaz udzielania świadczeń) с публичным реестром и обменом данными с ZUS.","Пациент получил право на информацию о таком запрете у лечащего врача и введены крупные штрафы для учреждений за его сокрытие.","Расширены обязанности клиник ежедневно проверять реестр запретов и хранить доказательства такой проверки.","Конкретизированы лимиты совокупного рабочего времени и максимального дохода медиков по контрактам NFZ, с жёсткими последствиями за превышение.","Добавлены новые составы правонарушений и штрафы до 30 000 zł за работу под запретом и нарушение новых лимитов и обязанностей.","Установлен 6‑месячный переходный период на приведение действующих договоров и правил оплаты труда медиков в соответствие новым требованиям."]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":75147,"truncated":false,"text_source":"pdf","created_at":"2026-10-27T17:30:26Z","computation_id":"result-v1:184f3d2e1a51b254cce761e69ab3ab3aa0a118601f3c0ea9569d23c374e85297","request_sha256":"c5813beb590fdb03b3a24f26d6f2fe41064c7c93e1b735b45e7b118abf5efe05","input_tokens":27386,"output_tokens":2811,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3157/attachment/3157_u3.pdf","source_kind":"text_after3","revision":3,"text_sha256":"text-v2:ccedb75e9b7500f0f20bc218b59ee3b1b8bb2dfbd5dffea0e5b6bd19998d74e4","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/processes/3157/attachment/3157_u3.pdf","members":[],"container_sha256":"2f5f6ffbaf8d771a53c1e5c1cd485eb396c5952653c54a57c6b468beb15681a4","sha256":"2f5f6ffbaf8d771a53c1e5c1cd485eb396c5952653c54a57c6b468beb15681a4","role":"bill","text":"","pages":36,"page_start":1,"page_end":36,"text_start":0,"text_end":75147,"text_sha256":"3e4a0ea990a2cfba91d534077a98ae64f1500afd31ccf734e6b17e3a87278786","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3157/attachment/3157_u3.pdf","text_sha256":"3e4a0ea990a2cfba91d534077a98ae64f1500afd31ccf734e6b17e3a87278786","block_id":"part:0","start":0,"end":233,"quote":"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\n\nUSTAWA\nz dnia 22 października 2026 r.\no zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków\npublicznych oraz niektórych innych ustaw1)\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/3157/attachment/3157_u3.pdf","text_sha256":"3e4a0ea990a2cfba91d534077a98ae64f1500afd31ccf734e6b17e3a87278786","block_id":"part:0","start":74776,"end":74798,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":75147,"page_start":1,"page_end":36,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":75147,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"495a82481f2b9e4d2589f1fd54dd87d37f907009d98010a1b3552ff0f0805c48"},"law_sha256":"law-v2:b5493dd172eb18c7a5a41a3e6cc42192e098cc84bdb4c29c2bdf164c7a6daf0f","source_checked_at":"2026-10-27T17:30:26Z"},"model":"gpt-5.1-2025-11-13","usage":{"input":0,"output":0,"cache_read":0,"cache_creation":0,"batch_input":27386,"batch_output":2811,"batch_cache_read":0,"batch_cache_creation":0},"error":null,"context_exceeded":false}');
INSERT INTO "computation_results" VALUES('result-v1:918484969efdcf4dda2372d88b94162ccbca666a97d2cabf0be0f38f7585ab3f','openai','batch_6ae0f2f167ac81909998461d26252119','387caa6949d2b76a9d7341d9e5a4d4f67c5c354daa0c3ad613a1cfe89b83c75d',10,'WPL/UD492','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae0f2f167ac81909998461d26252119","custom_id":"387caa6949d2b76a9d7341d9e5a4d4f67c5c354daa0c3ad613a1cfe89b83c75d","purpose":"analysis","term":10,"number":"WPL/UD492","generation":0,"collected_at":"2026-10-27T19:14:06Z","input_binding":{"term":10,"number":"WPL/UD492","reuse_key":"1608142c29e8524b99282ea490607a7aa7392549fd725811537f3553b66fe1ec"},"request_sha256":"d67f038f04c3f9c485b6c5d32d7e66ea34adf20fa051c13ca97118e200a4dea9","validation":"validated","record":{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект вводит минимальный возраст 15 лет для доступа к интернет‑соцсетям и общие правила проверки возраста. Планируется также усилить цифровое воспитание и обучение безопасности в сети в школах.","key_changes":["Минимальный возраст доступа к соцсетям будет установлен на 15 лет","Провайдеры соцсетей должны будут проверять возраст пользователей","Будут указаны допустимые способы онлайн‑верификации возраста","В школьные программы включат больше тем цифровой и сетевой безопасности","Министр образования проведёт информкампании о безопасном интернете"],"affected_groups":["иностранные дети и подростки, живущие в Польше","родители иностранных детей школьного возраста","иностранные пользователи соцсетей, на которых распространяется польское право","иностранные учителя и кадры в польских школах"],"practical_impact":"Подростки младше 15 лет, независимо от гражданства, могут столкнуться с блокировкой или ограничением аккаунтов в соцсетях. Школы усилят обучение цифровой безопасности, а родителям придётся учитывать новые возрастные ограничения и возможные проверки возраста детей онлайн.","effective_date":null,"confidence":0.55,"rationale":"Projekt wprowadza ogólny limit wieku i edukację cyfrową dla wszystkich małoletnich w Polsce, co istotnie wpływa także na dzieci cudzoziemców w sferze życia społecznego i szkolnego.","mnemonic_candidate":"Сетевой возрастной барьер","mnemonic_fallback":"Минимальный возраст соцсетей","mnemonic_basis":"Проект прямо заявляет о ustanowieniu minimalnego wieku dostępu do internetowych serwisów społecznościowych na poziomie 15 lat.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":0,"truncated":false,"text_source":"metadata_only","created_at":"2026-10-27T19:14:06Z","computation_id":"result-v1:918484969efdcf4dda2372d88b94162ccbca666a97d2cabf0be0f38f7585ab3f","request_sha256":"d67f038f04c3f9c485b6c5d32d7e66ea34adf20fa051c13ca97118e200a4dea9","input_tokens":2042,"output_tokens":928,"cache_read_input_tokens":1280,"cache_creation_input_tokens":0,"source_url":null,"source_kind":"metadata","revision":1,"text_sha256":null,"selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[],"observed_parts":[],"rejected":[],"facts":[],"limitations":[],"links":[],"coverage":[],"normative_sha256":""},"law_sha256":null,"source_checked_at":"2026-10-27T19:14:06Z"},"model":"gpt-5.1-2025-11-13","usage":{"input":0,"output":0,"cache_read":0,"cache_creation":0,"batch_input":2042,"batch_output":928,"batch_cache_read":1280,"batch_cache_creation":0},"error":null,"context_exceeded":false}');
INSERT INTO "computation_results" VALUES('result-v1:a86f266384e5076b0d5d36ee67af54d5d21a2d09579244b9200dd9d811d3afc9','openai','batch_6ae0f2f167ac81909998461d26252119','058b16acdaf7ba0f80f296c068215ee05b618db0ffa58ac5b9b3207273658e1b',10,'2995','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae0f2f167ac81909998461d26252119","custom_id":"058b16acdaf7ba0f80f296c068215ee05b618db0ffa58ac5b9b3207273658e1b","purpose":"analysis","term":10,"number":"2995","generation":0,"collected_at":"2026-10-27T19:14:06Z","input_binding":{"term":10,"number":"2995","reuse_key":"785f060989a9fc2f920d5e3e8fa7541ca38ff953c0077775d0e4ba66be855cc6"},"request_sha256":"eb7f731acb125e5ae05ececb010b03f43447a2e91edd0b9826c208084e8db2cf","validation":"validated","record":{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект ужесточает правила регистрации яхт и малых судов в реестре REJA24, особенно если они не считаются «польской собственностью». Возможны запреты на регистрацию судов, принадлежащих гражданам отдельных стран вне ЕС/ЕЭЗ.","key_changes":["Обязательный предварительный осмотр судов, не являющихся польской собственностью, перед регистрацией/сменой владельца","Оплату за предварительный осмотр устанавливает уполномоченная организация, но не выше среднего годового заработка","Правительство сможет вводить запрет на регистрацию судов, принадлежащих гражданам указанных третьих стран вне ЕС/ЕЭЗ","Во всех заявках собираются данные о гражданстве, паспорте и адресе для вручения в Польше владельца/арматора","Невыполнение новых обязанностей ведет к приостановке, а затем утрате польской регистрации и флага судна"],"affected_groups":["Иностранные владельцы яхт и малых судов в реестре REJA24","Иностранные арматоры, использующие польский флаг для яхт до 24 м","Граждане третьих стран вне ЕС/ЕЭЗ, которых могут затронуть будущие запреты"],"practical_impact":"Иностранным владельцам потребуется проходить платный технический предосмотр судна и подавать больше данных о себе, в т.ч. адрес для вручения в Польше. Невыполнение требований или попадание под правительственный запрет может привести к отказу в регистрации, приостановке или утрате польского флага.","effective_date":"Закон вступает в силу по истечении 12 месяцев со дня опубликования, за исключением указанных положений, которые вступают в силу по истечении 14 дней со дня опубликования.","confidence":0.94,"rationale":"Акт не меняет иммиграционные или трудовые правила, но вводит специальные требования и возможные запреты для судов, принадлежащих иностранцам из третьих стран, поэтому это косвенное, но целевое регулирование иностранцев (score 2, категория indirect).","mnemonic_candidate":"Иностранные яхты фильтр","mnemonic_fallback":"Предосмотр иностранных яхт","mnemonic_basis":"Проект вводит обязательный предварительный осмотр для судов, не являющихся польской собственностью, и позволяет правительству запрещать регистрацию судов, принадлежащих гражданам выбранных третьих стран.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":49161,"truncated":false,"text_source":"pdf","created_at":"2026-10-27T19:14:06Z","computation_id":"result-v1:a86f266384e5076b0d5d36ee67af54d5d21a2d09579244b9200dd9d811d3afc9","request_sha256":"eb7f731acb125e5ae05ececb010b03f43447a2e91edd0b9826c208084e8db2cf","input_tokens":17956,"output_tokens":1671,"cache_read_input_tokens":1280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3220/3220.pdf","source_kind":"committee_report","revision":1,"text_sha256":"text-v2:89390ade5829cfcd834a32b71e3e7a8f6379aab2b767cf16b25d3a6d9833b1d4","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3220/3220.pdf","members":[],"container_sha256":"e7cc9390ca6cdfd69f0a0fccc6c6c035019195dd550d22adb03f2912a60fba0d","sha256":"e7cc9390ca6cdfd69f0a0fccc6c6c035019195dd550d22adb03f2912a60fba0d","role":"bill","text":"","pages":24,"page_start":1,"page_end":24,"text_start":0,"text_end":49161,"text_sha256":"a82f55ab2df72eb51c415f0672848b47d535688397e649c4419250fab586708c","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3220/3220.pdf","text_sha256":"a82f55ab2df72eb51c415f0672848b47d535688397e649c4419250fab586708c","block_id":"part:0","start":0,"end":1253,"quote":"Druk nr 3220\nSEJM\nRZECZYPOSPOLITEJ POLSKIEJ\n\n X kadencja\n\nS P R A W O Z D A N I E\nKOMISJI  GOSPODARKI  MORSKIEJ  I  ŻEGLUGI  ŚRÓDLĄDOWEJ\n\no rządowym projekcie ustawy o zmianie ustawy\no rejestracji jachtów i innych jednostek\npływających o długości do 24 m oraz ustawy\no bezpieczeństwie morskim (druk nr 2995)\n\nMarszałek Sejmu, zgodnie z art. 37 ust.1 i art. 40 ust.1 regulaminu Sejmu\nskierował w dniu 11 sierpnia  2026 r. powyższy projekt ustawy do Komisji Gospodarki\nMorskiej i Żeglugi Śródlądowej do pierwszego czytania.\n\n          Komisja Gospodarki Morskiej i Żeglugi Śródlądowej  po przeprowadzeniu pierwszego\nczytania oraz rozpatrzeniu tego projektu ustawy  na posiedzeni ach w dni ach: 3 września\noraz 22 października 2026 r.\nwnosi :\n  W y s o k i  S e j m uchwalić raczy załączony projekt ustawy.\n\nWarszawa, dnia 22 października 2026 r.\n\nSprawozdawca\n\n(-) Piotr Głowski\n\nPrzewodniczący Komisji\n\n(-) Kacper Płażyński\n\n Tłoczono z polecenia Marszałka Sejmu Rzeczypospolitej Polskiej\n \fLiczba stron :  23     Data :   2026-10-27      Nazwa pliku :   V6_2027-1.NK   1\nX kadencja/druk nr 2995\nProjekt\nU S T AWA\nz dnia\no zmianie ustawy o rejestracji jachtów i innych jednostek pływających o długości\ndo 24 m oraz ustawy o bezpieczeństwie morskim\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":49161,"page_start":1,"page_end":24,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":49161,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"37d179ea952454958c6880c16159273e97f8ce859250fbc56b19bc4926450660"},"law_sha256":"law-v2:df95be3f434e69586b00655598163c90fe9075b948b401fa971486f108c28f41","source_checked_at":"2026-10-27T19:14:06Z"},"model":"gpt-5.1-2025-11-13","usage":{"input":0,"output":0,"cache_read":0,"cache_creation":0,"batch_input":17956,"batch_output":1671,"batch_cache_read":1280,"batch_cache_creation":0},"error":null,"context_exceeded":false}');
INSERT INTO "computation_results" VALUES('result-v1:1cc652dfa4d7e78687b70c378641ff4c03ef5a092324c0adb67bd38f6e454600','openai','batch_6ae0f2f167ac81909998461d26252119','8f3f5a3cdb385466347513ee7f1671f55994d51ea871824f94b3ae69c59447bd',10,'RCL/12416153','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae0f2f167ac81909998461d26252119","custom_id":"8f3f5a3cdb385466347513ee7f1671f55994d51ea871824f94b3ae69c59447bd","purpose":"analysis","term":10,"number":"RCL/12416153","generation":0,"collected_at":"2026-10-27T19:14:06Z","input_binding":{"term":10,"number":"RCL/12416153","reuse_key":"7c459b70bf8c263e185963cfcb617bca83dd3959132068a11ff11edde7324a50"},"request_sha256":"9b039854d3f69de8f6060c5c005880a9fec342118e00b97cd48d3a4787ee563e","validation":"validated","record":{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Вводится новый мер пресечения – электронный арест с браслетом вместо СИЗО. В законе о cudzoziemcach такой арест приравнивается к тюрьме/СИЗО при решениях по разрешениям на проживание и обмену информацией между органами.","key_changes":["Появляется новый мер пресечения: электронный арест с браслетом вместо СИЗО.","Во всех нормах о cudzoziemcach электронный арест приравнен к тюрьме и СИЗО.","При электронном аресте органы сообщают об этом в делах по легализации пребывания.","Электронный арест учитывается как негативный фактор при ряде решений по проживанию.","За явно незаконный электронный арест можно требовать компенсацию как за СИЗО."],"affected_groups":["иностранцы, в отношении которых ведётся уголовное производство в Польше","иностранцы, подающие заявки на разные виды разрешений на пребывание","иностранцы, находящиеся в тюрьме, СИЗО или под электронным арестом"],"practical_impact":"Для иностранцев, подозреваемых в преступлении, может применяться домашний арест с браслетом вместо СИЗО, но для миграционных органов он считается тем же лишением свободы. Такой статус может повлиять на получение или продление разрешения на проживание и фиксируется в обмене данными между ведомствами.","effective_date":"Закон вступает в силу по истечении 6 месяцев со дня его официального опубликования.","confidence":0.93,"rationale":"Проект прямо меняет ustawę o cudzoziemcach, приравнивая новый электронный арест к тюрьме/СИЗО при решениях по статусу пребывания, что напрямую затрагивает легализацию пребывания иностранцев.","mnemonic_candidate":"Браслет и вид на жительство","mnemonic_fallback":"Электронный арест и ВНЖ","mnemonic_basis":"В законе о cudzoziemcach электронный арест добавлен рядом с тюрьмой и СИЗО как основание и информация для решений по делам иностранцев.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","input_chars":265334,"truncated":false,"text_source":"documents","created_at":"2026-10-27T19:14:06Z","computation_id":"result-v1:1cc652dfa4d7e78687b70c378641ff4c03ef5a092324c0adb67bd38f6e454600","request_sha256":"9b039854d3f69de8f6060c5c005880a9fec342118e00b97cd48d3a4787ee563e","input_tokens":92328,"output_tokens":1503,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","source_kind":"rcl","revision":1,"text_sha256":"text-v2:ff2d354564f8f56cb7ffffb34bd5f734e6a4a1a9708056134777fa67b95021a9","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"selected","belonging":[],"role":[],"version":["rcl/12416153/stage/13234331","Projekt ustawy UD256.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","members":[],"container_sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":89591,"text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804263.docx","members":[],"container_sha256":"d5e6709a2fc2fe96408e650d8b03790de7e1032de7396a1c46391bcd9317b3f9","sha256":"d5e6709a2fc2fe96408e650d8b03790de7e1032de7396a1c46391bcd9317b3f9","role":"justification","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":128215,"text_sha256":"1be816a45ee4eed036c13a2f9187bd27af417291ac102e88354e4333609a75c2","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804264.docx","members":[],"container_sha256":"5e2d8f15709bae8fe21d896ab72af9fa366e9b460c1ab679fc7eed95be36ddef","sha256":"5e2d8f15709bae8fe21d896ab72af9fa366e9b460c1ab679fc7eed95be36ddef","role":"osr","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":143569,"text_sha256":"a69b62b10f690a2900f6af69663341ad6d3d81100350c883f391051bdaea2a40","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","members":[],"container_sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":89591,"text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12416153/stage/13234331","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":3363,"quote":"Projekt z 26 października 2026 r.\nustawa\nz dnia …\no zmianie ustawy – Kodeks postępowania karnego oraz niektórych innych ustaw [przypis 1: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 14 czerwca 1960 r. − Kodeks postępowania administracyjnego, ustawę z dnia 17 listopada 1964 r. − Kodeks postępowania cywilnego, ustawę z dnia 20 maja 1971 r. – Kodeks wykroczeń, ustawę z dnia 26 czerwca 1974 r. − Kodeks pracy, ustawę z dnia 26 stycznia 1982 r. − Karta Nauczyciela, ustawę z dnia 26 maja 1982 r. – Prawo o adwokaturze, ustawę z dnia 6 lipca 1982 r. o radcach prawnych, ustawę z dnia 16 września 1982 r. o pracownikach urzędów państwowych, ustawę z dnia 8 marca 1990 r. o samorządzie gminnym, ustawę z dnia 6 kwietnia 1990 r. o Policji, ustawę z dnia 12 października 1990 r. o Straży Granicznej, ustawę z dnia 24 sierpnia 1991 r. o Państwowej Straży Pożarnej, ustawę z dnia 23 grudnia 1994 r. o Najwyższej Izbie Kontroli, ustawę z dnia 6 czerwca 1997 r. – Kodeks karny, ustawę z dnia 6 czerwca 1997 r. − Kodeks karny wykonawczy, ustawę z dnia 29 sierpnia 1997 r. – Ordynacja podatkowa, ustawę z dnia 10 września 1999 r. − Kodeks karny skarbowy, ustawę z dnia 23 września 1999 r. o zasadach pobytu wojsk obcych na terytorium Rzeczypospolitej Polskiej, zasadach ich przemieszczania się przez to terytorium oraz zasadach udzielania pomocy wojskom sojuszniczym i organizacjom międzynarodowym, ustawę z dnia 30 czerwca 2000 r. – Prawo własności przemysłowej, ustawę z dnia 27 lipca 2001 r. o kuratorach sądowych, ustawę z dnia 24 sierpnia 2001 r. – Kodeks postępowania w sprawach o wykroczenia, ustawę z dnia 24 maja 2002 r. o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawę z dnia 30 sierpnia 2002 r. − Prawo o postępowaniu przed sądami administracyjnymi, ustawę z dnia 17 czerwca 2004 r. o skardze na naruszenie prawa strony do rozpoznania sprawy w postępowaniu przygotowawczym prowadzonym lub nadzorowanym przez prokuratora i postępowaniu sądowym bez nieuzasadnionej zwłoki, ustawę z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, ustawę z dnia 9 czerwca 2006 r. o służbie funkcjonariuszy Służby Kontrwywiadu Wojskowego oraz Służby Wywiadu Wojskowego, ustawę z dnia 9 czerwca 2006 r. o Centralnym Biurze Antykorupcyjnym, ustawę z dnia 13 kwietnia 2007 r. o Państwowej Inspekcji Pracy, ustawę z dnia 21 listopada 2008 r. o pracownikach samorządowych, ustawę z dnia 21 listopada 2008 r. o służbie cywilnej, ustawę z dnia 27 sierpnia 2009 r. o finansach publicznych, ustawę z dnia 9 kwietnia 2010 r. o Służbie Więziennej, ustawę z dnia 30 kwietnia 2010 r. o instytutach badawczych, ustawę z dnia 30 kwietnia 2010 r. o Polskiej Akademii Nauk, ustawę z dnia 25 czerwca 2010 r. o sporcie, ustawę z dnia 24 maja 2013 r. o środkach przymusu bezpośredniego i broni palnej, ustawę z dnia 12 grudnia 2013 r. o cudzoziemcach, ustawę z dnia 16 listopada 2016 r. o Krajowej Administracji Skarbowej, ustawę z dnia 15 grudnia 2016 r. o Prokuratorii Generalnej Rzeczypospolitej Polskiej, ustawę z dnia 8 grudnia 2017 r. o Służbie Ochrony Państwa, ustawę z dnia 26 stycznia 2018 r. o Straży Marszałkowskiej, ustawę z dnia 20 lipca 2018 r. – Prawo o szkolnictwie wyższym i nauce, ustawę z dnia 18 listopada 2020 r. o doręczeniach elektronicznych oraz ustawę z dnia 11 marca 2022 r. o obronie Ojczyzny.] )\nArt. 1"},{"kind":"draft_date","value":"2026-10-26","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":30,"quote":"Projekt z 26 października 2026"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":89341,"end":89363,"quote":"Ustawa wchodzi w życie"}],"limitations":["support_applicability_unknown"],"links":[{"kind":"supporting","source_part":1,"target_part":0,"status":"unknown","evidence":[]},{"kind":"supporting","source_part":2,"target_part":0,"status":"unknown","evidence":[]}],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":89591,"page_start":null,"page_end":null,"losses":[]},{"part_index":1,"stage":"extraction","start":0,"end":128215,"page_start":null,"page_end":null,"losses":[]},{"part_index":2,"stage":"extraction","start":0,"end":143569,"page_start":null,"page_end":null,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":89591,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"00746e7a2fae78bbb5a60fd550fc7876a5eae8515999220ebc4ffffa3abe616c"},"law_sha256":"law-v2:0d680f74ae1306e2727286354b4e7785143018d907e5137e937623f7067a1ca6","source_checked_at":"2026-10-27T19:14:06Z"},"model":"gpt-5.1-2025-11-13","usage":{"input":0,"output":0,"cache_read":0,"cache_creation":0,"batch_input":92328,"batch_output":1503,"batch_cache_read":0,"batch_cache_creation":0},"error":null,"context_exceeded":false}');
INSERT INTO "computation_results" VALUES('result-v1:ac61beabf382607e4fb057cd3b70531f02a44fc1083a25df16b114834ab6c2b8','openai','batch_6ae245f072e08190a36457785b64b260','d67b149f6c853d4d0399b6a1acff3ca1a83be5ad9d974f1b3dce9b61c09b4dc4',10,'3146','{"schema_version":2,"provider":"openai","batch_id":"batch_6ae245f072e08190a36457785b64b260","custom_id":"d67b149f6c853d4d0399b6a1acff3ca1a83be5ad9d974f1b3dce9b61c09b4dc4","purpose":"amendments","term":10,"number":"3146","generation":null,"collected_at":"2026-10-28T19:12:04Z","input_binding":{"term":10,"number":"3146","reuse_key":"d67b149f6c853d4d0399b6a1acff3ca1a83be5ad9d974f1b3dce9b61c09b4dc4"},"request_sha256":"b024647583eebcc3ae4b5991249fe836094c7aa78accff4be8210ba2cea8a363","validation":"validated","record":{"amendments":{"summary":"Поправки Сената в основном усиливают контроль за выдачей полномочий на применение силы, оружия и боеприпасов в операциях с участием Frontex и персонала других государств ЕС и уточняют ряд формулировок. Объём и характер операций по возвращению иностранцев не расширяются, меняются лишь процедуры согласования и терминология.","changes":["Полномочия персонала Frontex/ЕС на применение силы и оружия выдаются Komendant Główny SG только с согласия министра внутренних дел.","В нормах о Frontex-операциях прямо упомянуто применение не только оружия, но и боеприпасов.","Уточнено, что льготы при командировках касаются службы за границей на период свыше 30 дней.","В законе о Straży Granicznej введено единое обозначение «Agencja Frontex».","Скорректированы формулировки о финансировании операций и удалены лишние слова в новых статьях."],"affects_foreigners":true,"confidence":0.83,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3275/3275-uchwa%C5%82a.docx","source_kind":"senate_amendments","created_at":"2026-10-28T19:12:04Z","computation_id":"result-v1:ac61beabf382607e4fb057cd3b70531f02a44fc1083a25df16b114834ab6c2b8","request_sha256":"b024647583eebcc3ae4b5991249fe836094c7aa78accff4be8210ba2cea8a363","input_tokens":2729,"output_tokens":2557,"cache_read_input_tokens":0,"cache_creation_input_tokens":0},"model":"gpt-5.1-2025-11-13","usage":{"input":0,"output":0,"cache_read":0,"cache_creation":0,"batch_input":2729,"batch_output":2557,"batch_cache_read":0,"batch_cache_creation":0},"error":null,"context_exceeded":false}');
INSERT INTO "computation_results" VALUES('result-v1:7abf53b9cf9baa9408a529918c05ad0692155a5eed622d8b4820582346da4f4d','openai','batch_6ae3994c0c9c8190a7f09698b0ce03a9','1ae8d2162abc51088fb55ce377e554cc5c663979b5c445ae919036c6a027d2a1',10,'RCL/12408601','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae3994c0c9c8190a7f09698b0ce03a9","custom_id":"1ae8d2162abc51088fb55ce377e554cc5c663979b5c445ae919036c6a027d2a1","purpose":"analysis","term":10,"number":"RCL/12408601","generation":0,"collected_at":"2026-10-29T19:12:03Z","input_binding":{"term":10,"number":"RCL/12408601","reuse_key":"23205207dea7fa3a4b0f18fa1c78c9d1906b15cbddc53421e359f8479a6b88f7"},"request_sha256":"1fe039ec8ff4e37ff47e5282564600ea8cd4ed4bbdebe0df2f61e311b0364adf","validation":"validated","record":{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Меняются правила усыновления и приёмной опеки, в том числе для иностранцев. Предусмотрены переводчики, использование заключений из страны происхождения и проверки иностранных опекунов. Правила приёмной опеки охватывают также несовершеннолетних иностранцев в Польше вне перечисленных законом категорий.","key_changes":["Проверяемые иностранцы представляют сведения о несудимости и отсутствии запретов из реестра страны гражданства; проверки — не реже 24 месяцев.","Министр может выделить центр усыновления для иностранцев; другие центры сохраняют компетенцию и могут использовать заключения из страны происхождения.","При недостаточном польском допускается переводчик, в том числе на обучении; при усыновлении ребёнка из-за рубежа расходы несут кандидаты.","При усыновлении с выездом в страну Гаагской конвенции: согласие на отчёты ежегодно первые 3 года после вступления решения в силу, затем раз в 3 года до 18 лет.","Иностранному представителю зарубежного посредника по усыновлению нужен документ о знании польского; аккредитация посредника — максимум на 2 года."],"affected_groups":["Несовершеннолетние иностранцы, находящиеся в Польше, включая не перечисленных в статье 5, части 1, пунктах 2–6","Иностранцы — кандидаты в усыновители, приёмные родители и руководители семейных детских домов; для приёмных родителей требуется законное пребывание","Иностранцы в поддерживающих семьях, семьях временной подмены опекунов и семьях ухода за взрослыми; сотрудники, исполнители услуг, волонтёры и наставники воспитанников","Совместно проживающие с кандидатами в усыновители, приёмными семьями, руководителями семейных детских домов и семьями ухода; с поддерживающими и подменяющими семьями — при контакте с детьми","Представители зарубежных посредников и кандидаты в усыновители, проживающие за пределами Польши"],"practical_impact":"При усыновлении ребёнка супруга исключаются общий запрет судимости и проверка совместно проживающих. При ввозе усыновляемого ребёнка расходы на перевод в исключительных случаях, особенно при родстве, свойстве или объединении братьев и сестёр, может принять центр либо центральный орган. Для действующих зарубежных посредников: сведения о ранее отсутствовавшем представителе — за 3 месяца, подтверждение соответствия представителей требованиям — за 6 месяцев со вступления закона в силу.","effective_date":"«Закон вступает в силу 1 октября 2026 года, за исключением: 1) статьи 1, пункта 17, и статьи 25 — с 1 января 2027 года; 2) статьи 1, пункта 101, статьи 2, пункта 1, статьи 3, пунктов 3 и 4, статей 8, 10 и 11, а также статьи 12, пункта 2, статей 16, 20–22 и 24 — с 1 января 2028 года; 3) статьи 1, пункта 150, подпункта d, пункта 152, подпункта d, пункта 155, подпункта c, пункта 157, подпункта a, второго и шестого абзацев перечня, а также пункта 158, подпунктов a, f и g, в части использования информационной системы — со дня, определённого в объявлении, предусмотренном статьёй 72».","confidence":0.93,"rationale":"Оценка 3 и социальная категория обусловлены прямыми изменениями правил усыновления, приёмной опеки и проверки иностранцев, а не легализации их пребывания.","mnemonic_candidate":"Переводчик при усыновлении","mnemonic_fallback":"Перевод в процедуре усыновления","mnemonic_basis":"Добавляемая статья 169a допускает переводчика при недостаточном владении польским и регулирует расходы при усыновлении ребёнка с переездом в Польшу.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-6.1-sol","prompt_version":"2026-10-v13","input_chars":608481,"truncated":false,"text_source":"documents","created_at":"2026-10-29T19:12:03Z","computation_id":"result-v1:7abf53b9cf9baa9408a529918c05ad0692155a5eed622d8b4820582346da4f4d","request_sha256":"1fe039ec8ff4e37ff47e5282564600ea8cd4ed4bbdebe0df2f61e311b0364adf","input_tokens":199743,"output_tokens":1405,"cache_read_input_tokens":0,"cache_creation_input_tokens":2131,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","source_kind":"rcl","revision":1,"text_sha256":"text-v2:193ed7229af7dcaf3d276ba2c825d6d03bb37cffe232b5613e8656a3b3a8aac1","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"selected","belonging":[],"role":[],"version":["rcl/12408601/stage/13194357","Projekt 20.03.2026."],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","members":[],"container_sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","role":"bill","text":"","pages":165,"page_start":1,"page_end":165,"text_start":0,"text_end":345959,"text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769079.pdf","members":[],"container_sha256":"1df0a054620d8dc2bdfeb38bf61b41734b91bc2d4c1bb10d664274a550e88af9","sha256":"1df0a054620d8dc2bdfeb38bf61b41734b91bc2d4c1bb10d664274a550e88af9","role":"justification","text":"","pages":73,"page_start":1,"page_end":73,"text_start":0,"text_end":185158,"text_sha256":"024ef7a3efd75d5c64a39559503a84ce9183008c6f93142369719d2b2fba0c4b","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769080.pdf","members":[],"container_sha256":"8849709070e4264a5ed1373b2d0fbe3fa39d4b42341c5fd998f699ccc7fb032c","sha256":"8849709070e4264a5ed1373b2d0fbe3fa39d4b42341c5fd998f699ccc7fb032c","role":"osr","text":"","pages":29,"page_start":1,"page_end":29,"text_start":0,"text_end":131304,"text_sha256":"7cfd3b14744a034f650c41ff6ea6480bd4186e42ed406fab76b3db0bdb4951fe","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","members":[],"container_sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","role":"bill","text":"","pages":165,"page_start":1,"page_end":165,"text_start":0,"text_end":345959,"text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12408601/stage/13194357","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","block_id":"part:0","start":0,"end":156,"quote":"Projekt z dnia 20 marca 2026 r.\nU S T A W A\nz dnia\no zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych\ninnych ustaw 1)\nArt. 1"},{"kind":"draft_date","value":"2026-03-20","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs/