INSERT INTO "computation_results" VALUES('result-v1:45ce3e693670caf73d3b4cc5a1d3aa30f0c712feaae7355394d0019d2453e90d','openai','batch_6ae3994c0c9c8190a7f09698b0ce03a9','32d0a7924bd4ea3ba533f03cc8a88e28a0f017987a09d14bb6138aac31105495',10,'RPW/36403/2026','{"schema_version":1,"provider":"openai","batch_id":"batch_6ae3994c0c9c8190a7f09698b0ce03a9","custom_id":"32d0a7924bd4ea3ba533f03cc8a88e28a0f017987a09d14bb6138aac31105495","purpose":"analysis","term":10,"number":"RPW/36403/2026","generation":0,"collected_at":"2026-10-29T19:12:03Z","input_binding":{"term":10,"number":"RPW/36403/2026","reuse_key":"463166ea9c4b4b6dd7918e36dfcaca429b5142f677b51272b803548d1b986656"},"request_sha256":"7197fa9f053f0fd1a3d0e42e51235ea96f5b05a147102543de262b9626b7e6ed","validation":"validated","record":{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Доходные пороги для социальной помощи пересматриваются ежегодно вместо одного раза в три года. Это также касается размеров помощи на содержание и изучение польского для беженцев, получателей дополнительной защиты и обладателей прямо указанного временного ВНЖ.","key_changes":["Доходные пороги социальной помощи пересматриваются ежегодно на основе исследования необходимых расходов.","Минимум и максимум помощи на содержание и изучение польского меняются на 50% суммы прироста двух доходных порогов.","Для расчёта берётся прирост порогов для одиноко проживающего человека и на одного члена семьи.","В те же сроки по той же формуле меняются максимум постоянного пособия и база помощи на самостоятельную жизнь и учёбу.","Первый пересмотр — в 2028 году; пересмотренные пороги и суммы применяются с 1 января следующего года, впервые — 2029 года."],"affected_groups":["Иностранцы, имеющие право на социальную помощь, зависящую от дохода","Иностранцы, получившие в Польше статус беженца","Иностранцы, получившие в Польше дополнительную защиту","Иностранцы с временным ВНЖ по ст. 159 ч. 1 п. 1 подп. c или d ustawa o cudzoziemcach (закона об иностранцах)"],"practical_impact":"Для имеющих право на помощь иностранцев доходные пороги и связанные с ними суммы пересматриваются каждый год. Для перечисленных получателей интеграционной помощи ежегодно пересчитываются её минимум и максимум; фиксированного процента ежегодного повышения законопроект не устанавливает.","effective_date":"Закон вступает в силу 1 января 2028 года.","confidence":0.99,"rationale":"Оценка 3 и социальная категория обусловлены изменением периодичности пересмотра доходных порогов и размеров выплат, прямо предусмотренных для перечисленных групп иностранцев.","mnemonic_candidate":"Ежегодный пересчёт интеграционной помощи","mnemonic_fallback":"Ежегодный пересмотр интеграционных выплат","mnemonic_basis":"Минимальные и максимальные выплаты на содержание и изучение польского для перечисленных иностранцев меняются в сроки ежегодного пересмотра доходных порогов.","mnemonic_language":"ru","changes_since_previous":[]},"model":"gpt-6.1-sol","prompt_version":"2026-10-v13","input_chars":51065,"truncated":false,"text_source":"pdf","created_at":"2026-10-29T19:12:03Z","computation_id":"result-v1:45ce3e693670caf73d3b4cc5a1d3aa30f0c712feaae7355394d0019d2453e90d","request_sha256":"7197fa9f053f0fd1a3d0e42e51235ea96f5b05a147102543de262b9626b7e6ed","input_tokens":16211,"output_tokens":1105,"cache_read_input_tokens":2131,"cache_creation_input_tokens":0,"source_url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf","source_kind":"print","revision":1,"text_sha256":"text-v2:ec5f5cd9ba7f09699205920e7723ad7a085f20d30da370bf757ce6197fc22bd5","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf","members":[],"container_sha256":"0465f82b7ac8c54dc0fa30bb433c31a38b489b64e6c68e139217f5409f7fe675","sha256":"0465f82b7ac8c54dc0fa30