INSERT INTO "content_snapshots" VALUES('content-snapshot-v1:58e42bd4cc2c6b93a13ccc7472357143f381213ca7aa23b1189435d3be2c308f','bill','{"summary":{"term":10,"number":"3146","title":"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","description":"projekt dotyczy zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-23","document_date":"2026-09-23","change_date":"2026-10-28T11:16:32Z","closure_date":"2026-10-22","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":"RM-0610-143-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26","prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null},"status":"analyzed","prefilter_hits":["text:cudzoziemcy","text:migracja","text:straz_graniczna","text:granica_panstwowa","text:schengen","text:pracownicy_delegowani"],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-23","print_number":"3146","sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingRe