INSERT INTO "content_versions" VALUES('content-v1:fe5a2b3074b4f63c69fbb033f64042f9bf623b2e8c5c4f67227249716c062eb0',231,NULL,'content-snapshot-v1:58e42bd4cc2c6b93a13ccc7472357143f381213ca7aa23b1189435d3be2c308f','content-snapshot-v1:931aed83f17e379e63adf82ac7157b43883576b9d2d66533b8d824c2349eb19b','content-snapshot-v1:5f736a5e2edfc58fdb2972cd626531ccbbb4e3651b69d9b52ffa66110d85c555','{"schema_version":1,"root_publication_id":231,"previous_version_id":null,"reason":"original","language":"ru","bill_snapshot_id":"content-snapshot-v1:58e42bd4cc2c6b93a13ccc7472357143f381213ca7aa23b1189435d3be2c308f","change_snapshot_id":"content-snapshot-v1:931aed83f17e379e63adf82ac7157b43883576b9d2d66533b8d824c2349eb19b","plan_snapshot_id":"content-snapshot-v1:5f736a5e2edfc58fdb2972cd626531ccbbb4e3651b69d9b52ffa66110d85c555","rendered_text":"<b>Депортации Frontex · druk nr 3146</b>\n📮 <b>Направлен в комиссию</b>\n<i>Принят Сеймом 22 окт 2026</i>\n\n🧭 <b>Новые стадии</b>\n• 27 окт 2026: Сенат внёс поправки (druk nr 3275)\n• 28 окт 2026: 📮 Направлен в комиссию: Komisja Administracji i Spraw Wewnętrznych (ASW)\n\n🆕 <b>Что меняют поправки Сената</b>\nПоправки Сената в основном усиливают контроль за выдачей полномочий на применение силы, оружия и боеприпасов в операциях с участием Frontex и персонала других государств ЕС и уточняют ряд формулировок. Объём и характер операций по возвращению иностранцев не расширяются, меняются лишь процедуры согласования и терминология.\n• Полномочия персонала Frontex/ЕС на применение силы и оружия выдаются Komendant Główny SG только с согласия министра внутренних дел.\n• В нормах о Frontex-операциях прямо упомянуто применение не только оружия, но и боеприпасов.\n• Уточнено, что льготы при командировках касаются службы за границей на период свыше 30 дней.\n• В законе о Straży Granicznej введено единое обозначение «Agencja Frontex».\n• Скорректированы формулировки о финансировании операций и удалены лишние слова в новых статьях.\n\n⏭ <b>Что дальше:</b> Сейм рассматривает поправки Сената · обычно на ближайшем заседании Сейма\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=ASW\">Komisja Administracji i Spraw Wewnętrznych (ASW)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=ASW\">форма письма</a>)\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3146\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3146\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3275/3275-uchwa%C5%82a.docx\">Текст поправок (DOCX)</a>\n\n#комиссия #сенат #поправки #важность5 #легализация #kadencja10druk3146 #UC126","formatter_version":"telegram-format-v1","source_observation_ids":[],"computation_ids":["result-v1:ac61beabf382607e4fb057cd3b70531f02a44fc1083a25df16b114834ab6c2b8"],"application_ids":[],"status_change_id":189,"recorded_at":"2026-10-28T19:18:25Z"}');
