INSERT INTO "document_selections" VALUES('selection-v1:4bc84d28e7c359f774f69e51f56c36a051cf8b30a42f47f1271dbbb94416f150','bill_text','document-selection-v1','unverified','{"schema_version":1,"selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3220/3220.pdf","members":[],"container_sha256":"e7cc9390ca6cdfd69f0a0fccc6c6c035019195dd550d22adb03f2912a60fba0d","sha256":"e7cc9390ca6cdfd69f0a0fccc6c6c035019195dd550d22adb03f2912a60fba0d","role":"bill","text":"","pages":24,"page_start":1,"page_end":24,"text_start":0,"text_end":49161,"text_sha256":"a82f55ab2df72eb51c415f0672848b47d535688397e649c4419250fab586708c","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3220/3220.pdf","text_sha256":"a82f55ab2df72eb51c415f0672848b47d535688397e649c4419250fab586708c","block_id":"part:0","start":0,"end":1253,"quote":"Druk nr 3220\nSEJM\nRZECZYPOSPOLITEJ POLSKIEJ\n\n X kadencja\n\nS P R A W O Z D A N I E\nKOMISJI  GOSPODARKI  MORSKIEJ  I  ŻEGLUGI  ŚRÓDLĄDOWEJ\n\no rządowym projekcie ustawy o zmianie ustawy\no rejestracji jachtów i innych jednostek\npływających o długości do 24 m oraz ustawy\no bezpieczeństwie morskim (druk nr 2995)\n\nMarszałek Sejmu, zgodnie z art. 37 ust.1 i art. 40 ust.1 regulaminu Sejmu\nskierował w dniu 11 sierpnia  2026 r. powyższy projekt ustawy do Komisji Gospodarki\nMorskiej i Żeglugi Śródlądowej do pierwszego czytania.\n\n          Komisja Gospodarki Morskiej i Żeglugi Śródlądowej  po przeprowadzeniu pierwszego\nczytania oraz rozpatrzeniu tego projektu ustawy  na posiedzeni ach w dni ach: 3 września\noraz 22 października 2026 r.\nwnosi :\n  W y s o k i  S e j m uchwalić raczy załączony projekt ustawy.\n\nWarszawa, dnia 22 października 2026 r.\n\nSprawozdawca\n\n(-) Piotr Głowski\n\nPrzewodniczący Komisji\n\n(-) Kacper Płażyński\n\n Tłoczono z polecenia Marszałka Sejmu Rzeczypospolitej Polskiej\n \fLiczba stron :  23     Data :   2026-10-27      Nazwa pliku :   V6_2027-1.NK   1\nX kadencja/druk nr 2995\nProjekt\nU S T AWA\nz dnia\no zmianie ustawy o rejestracji jachtów i innych jednostek pływających o długości\ndo 24 m oraz ustawy o bezpieczeństwie morskim\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":49161,"page_start":1,"page_end":24,"losses":[]}],"normative_sha256":"37d179ea952454958c6880c16159273e97f8ce859250fbc56b19bc4926450660"}}');
INSERT INTO "document_selections" VALUES('selection-v1:6cb513dfc7f8ba5751234d43150072d818cb69a3002b7b4aa5119f30a3a8d783','bill_text','document-selection-v1','selected','{"schema_version":1,"selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"selected","belonging":[],"role":[],"version":["rcl/12416153/stage/13234331","Projekt ustawy UD256.docx"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","members":[],"container_sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":89591,"text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804263.docx","members":[],"container_sha256":"d5e6709a2fc2fe96408e650d8b03790de7e1032de7396a1c46391bcd9317b3f9","sha256":"d5e6709a2fc2fe96408e650d8b03790de7e1032de7396a1c46391bcd9317b3f9","role":"justification","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":128215,"text_sha256":"1be816a45ee4eed036c13a2f9187bd27af417291ac102e88354e4333609a75c2","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804264.docx","members":[],"container_sha256":"5e2d8f15709bae8fe21d896ab72af9fa366e9b460c1ab679fc7eed95be36ddef","sha256":"5e2d8f15709bae8fe21d896ab72af9fa366e9b460c1ab679fc7eed95be36ddef","role":"osr","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":143569,"text_sha256":"a69b62b10f690a2900f6af69663341ad6d3d81100350c883f391051bdaea2a40","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","members":[],"container_sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","sha256":"f8646a662fee0ecde861fe523b1b7c013b11bd35745287039e2bf54a88a2e11c","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":89591,"text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12416153/stage/13234331","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":3363,"quote":"Projekt z 26 października 2026 r.\nustawa\nz dnia …\no zmianie ustawy – Kodeks postępowania karnego oraz niektórych innych ustaw [przypis 1: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 14 czerwca 1960 r. − Kodeks postępowania administracyjnego, ustawę z dnia 17 listopada 1964 r. − Kodeks postępowania cywilnego, ustawę z dnia 20 maja 1971 r. – Kodeks wykroczeń, ustawę z dnia 26 czerwca 1974 r. − Kodeks pracy, ustawę z dnia 26 stycznia 1982 r. − Karta Nauczyciela, ustawę z dnia 26 maja 1982 r. – Prawo o adwokaturze, ustawę z dnia 6 lipca 1982 r. o radcach prawnych, ustawę z dnia 16 września 1982 r. o pracownikach urzędów państwowych, ustawę z dnia 8 marca 1990 r. o samorządzie gminnym, ustawę z dnia 6 kwietnia 1990 r. o Policji, ustawę z dnia 12 października 1990 r. o Straży Granicznej, ustawę z dnia 24 sierpnia 1991 r. o Państwowej Straży Pożarnej, ustawę z dnia 23 grudnia 1994 r. o Najwyższej Izbie Kontroli, ustawę z dnia 6 czerwca 1997 r. – Kodeks karny, ustawę z dnia 6 czerwca 1997 r. − Kodeks karny wykonawczy, ustawę z dnia 29 sierpnia 1997 r. – Ordynacja podatkowa, ustawę z dnia 10 września 1999 r. − Kodeks karny skarbowy, ustawę z dnia 23 września 1999 r. o zasadach pobytu wojsk obcych na terytorium Rzeczypospolitej Polskiej, zasadach ich przemieszczania się przez to terytorium oraz zasadach udzielania pomocy wojskom sojuszniczym i organizacjom międzynarodowym, ustawę z dnia 30 czerwca 2000 r. – Prawo własności przemysłowej, ustawę z dnia 27 lipca 2001 r. o kuratorach sądowych, ustawę z dnia 24 sierpnia 2001 r. – Kodeks postępowania w sprawach o wykroczenia, ustawę z dnia 24 maja 2002 r. o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawę z dnia 30 sierpnia 2002 r. − Prawo o postępowaniu przed sądami administracyjnymi, ustawę z dnia 17 czerwca 2004 r. o skardze na naruszenie prawa strony do rozpoznania sprawy w postępowaniu przygotowawczym prowadzonym lub nadzorowanym przez prokuratora i postępowaniu sądowym bez nieuzasadnionej zwłoki, ustawę z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, ustawę z dnia 9 czerwca 2006 r. o służbie funkcjonariuszy Służby Kontrwywiadu Wojskowego oraz Służby Wywiadu Wojskowego, ustawę z dnia 9 czerwca 2006 r. o Centralnym Biurze Antykorupcyjnym, ustawę z dnia 13 kwietnia 2007 r. o Państwowej Inspekcji Pracy, ustawę z dnia 21 listopada 2008 r. o pracownikach samorządowych, ustawę z dnia 21 listopada 2008 r. o służbie cywilnej, ustawę z dnia 27 sierpnia 2009 r. o finansach publicznych, ustawę z dnia 9 kwietnia 2010 r. o Służbie Więziennej, ustawę z dnia 30 kwietnia 2010 r. o instytutach badawczych, ustawę z dnia 30 kwietnia 2010 r. o Polskiej Akademii Nauk, ustawę z dnia 25 czerwca 2010 r. o sporcie, ustawę z dnia 24 maja 2013 r. o środkach przymusu bezpośredniego i broni palnej, ustawę z dnia 12 grudnia 2013 r. o cudzoziemcach, ustawę z dnia 16 listopada 2016 r. o Krajowej Administracji Skarbowej, ustawę z dnia 15 grudnia 2016 r. o Prokuratorii Generalnej Rzeczypospolitej Polskiej, ustawę z dnia 8 grudnia 2017 r. o Służbie Ochrony Państwa, ustawę z dnia 26 stycznia 2018 r. o Straży Marszałkowskiej, ustawę z dnia 20 lipca 2018 r. – Prawo o szkolnictwie wyższym i nauce, ustawę z dnia 18 listopada 2020 r. o doręczeniach elektronicznych oraz ustawę z dnia 11 marca 2022 r. o obronie Ojczyzny.] )\nArt. 1"},{"kind":"draft_date","value":"2026-10-26","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":0,"end":30,"quote":"Projekt z 26 października 2026"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx","text_sha256":"04ff400c35c8a4bc566545dec9cce0fb28113408fb59cfe152b3b75a09c0d665","block_id":"part:0","start":89341,"end":89363,"quote":"Ustawa wchodzi w życie"}],"limitations":["support_applicability_unknown"],"links":[{"kind":"supporting","source_part":1,"target_part":0,"status":"unknown","evidence":[]},{"kind":"supporting","source_part":2,"target_part":0,"status":"unknown","evidence":[]}],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":89591,"page_start":null,"page_end":null,"losses":[]},{"part_index":1,"stage":"extraction","start":0,"end":128215,"page_start":null,"page_end":null,"losses":[]},{"part_index":2,"stage":"extraction","start":0,"end":143569,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"00746e7a2fae78bbb5a60fd550fc7876a5eae8515999220ebc4ffffa3abe616c"}}');
