arlamentu Europejskiego i Rady z dnia 9 września 2015 r. ustanawiającą procedurę udzielania informacji w dziedzinie przepisów technicznych oraz zasad dotyczących usług społeczeństwa informacyjnego (ujednolicenie) (Dz. Urz. UE L 241 z 17.09.2015, str. 1). ] 1)\nArt. 1"},{"kind":"draft_date","value":"2026-10-15","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12399305/13139362/13139363/dokument804388.zip","text_sha256":"459b991cbcaaa1b4e7a4a2d1793f0167763af4b691982e8230aa966f573b2416","block_id":"part:0","start":0,"end":35,"quote":"Projekt z dnia 15 października 2026"}],"limitations":["annex_link_unknown","support_applicability_unknown","missing_evidence"],"links":[{"kind":"normative_annex","source_part":1,"target_part":0,"status":"unknown","evidence":[]},{"kind":"supporting","source_part":2,"target_part":0,"status":"unknown","evidence":[]},{"kind":"supporting","source_part":3,"target_part":0,"status":"unknown","evidence":[]}],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":24685,"page_start":null,"page_end":null,"losses":[]},{"part_index":1,"stage":"extraction","start":0,"end":34637,"page_start":null,"page_end":null,"losses":[]},{"part_index":2,"stage":"extraction","start":0,"end":31051,"page_start":null,"page_end":null,"losses":[]},{"part_index":3,"stage":"extraction","start":0,"end":49704,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"2e6c0ab0353569def3fd7b6d7c9de54874bbe8158cdb19c3307a4c5cf7b08301"}}');
