cf110869500e1857ab43eeaa64ea166eaa8d","sha256":"f2f326a5cb5e15671414ff9d7795cf110869500e1857ab43eeaa64ea166eaa8d","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":107718,"text_sha256":"f397c85a33192f71f57d63913b8fe1b2f418727adf2ffac6131bebc74f199f90","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12402550/13159514/13159515/dokument739326.docx","members":[],"container_sha256":"ba828f5fbcb7e6f95575a0fd1c7998528bb71976926b9457a391b39c74e1d566","sha256":"ba828f5fbcb7e6f95575a0fd1c7998528bb71976926b9457a391b39c74e1d566","role":"bill","text":"","pages":0,"page_start":null,"page_end":null,"text_start":0,"text_end":104254,"text_sha256":"e4c19baeaf9088f22464e745ae37d5e357f024140eae2e9635ffa69df9518a17","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12402550/stage/13159514","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402550/13159514/13159515/dokument779125.docx","text_sha256":"f397c85a33192f71f57d63913b8fe1b2f418727adf2ffac6131bebc74f199f90","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402550/13159514/13159515/dokument779125.docx","text_sha256":"f397c85a33192f71f57d63913b8fe1b2f418727adf2ffac6131bebc74f199f90","block_id":"part:0","start":0,"end":881,"quote":"Projekt z dnia 27 maja 2026 r.\nustawa\nz dnia ………………………………… 2026 r.\no zmianie ustawy o wspieraniu rozwoju usług i sieci telekomunikacyjnych oraz niektórych innych ustaw [przypis 2: )\tNiniejszą ustawą zmienia się ustawy: ustawę z dnia 21 marca 1985 r. o drogach publicznych, ustawę z dnia 17 maja 1989 r.  Prawo geodezyjne i kartograficzne, ustawę z dnia 28 września 1991 r. o lasach, ustawę z dnia 7 lipca 1994 r. – Prawo budowlane, ustawę z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym, ustawę z dnia 21 sierpnia 1997 r. o gospodarce nieruchomościami, ustawę z dnia 5 czerwca 1998 r. o samorządzie powiatowym, ustawę z dnia 23 stycznia 2009 r. o wojewodzie i administracji rządowej w województwie, ustawę z dnia 12 lipca 2024 r. – Prawo komunikacji elektronicznej oraz ustawę z dnia 12 lipca 2024 r. – Przepisy wprowadzające ustawę – Prawo komunikacji elektronicznej.] )\nArt. 1"},{"kind":"draft_date","value":"2026-05-27","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402550/13159514/13159515/dokument779125.docx","text_sha256":"f397c85a33192f71f57d63913b8fe1b2f418727adf2ffac6131bebc74f199f90","block_id":"part:0","start":0,"end":27,"quote":"Projekt z dnia 27 maja 2026"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12402550/13159514/13159515/dokument779125.docx","text_sha256":"f397c85a33192f71f57d63913b8fe1b2f418727adf2ffac6131bebc74f199f90","block_id":"part:0","start":106785,"end":106807,"quote":"Ustawa wchodzi w życie"}],"limitations":["support_applicability_unknown"],"links":[{"kind":"supporting","source_part":1,"target_part":0,"status":"unknown","evidence":[]},{"kind":"supporting","source_part":2,"target_part":0,"status":"unknown","evidence":[]}],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":107718,"page_start":null,"page_end":null,"losses":[]},{"part_index":1,"stage":"extraction","start":0,"end":324352,"page_start":null,"page_end":null,"losses":[]},{"part_index":2,"stage":"extraction","start":0,"end":161526,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"bc68730146e9f0ca0cabf28e50359c7eb45d627d3d50edbd903b0eb45c422aaa"}}');
