INSERT INTO "document_selections" VALUES('selection-v1:3288394401250f0665646eacbe5cc7433d713b3bdad669f089a70fbfa2116105','bill_text','document-selection-v1','unverified','{"schema_version":1,"selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"unverified","belonging":[],"role":[],"version":["sejm/10/print/3278"],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3278/3278.pdf","members":[],"container_sha256":"9095ef86c4b9de17a32566fbcd73ac405ff1ec8bc085c3b945b152d5b4394dab","sha256":"9095ef86c4b9de17a32566fbcd73ac405ff1ec8bc085c3b945b152d5b4394dab","role":"bill","text":"","pages":67,"page_start":1,"page_end":67,"text_start":0,"text_end":200755,"text_sha256":"2c74a729afdba0366b316ca8308c1278d264359ba90207d3462184e66422e007","losses":[]}],"observed_parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3278/3278.pdf","members":[],"container_sha256":"9095ef86c4b9de17a32566fbcd73ac405ff1ec8bc085c3b945b152d5b4394dab","sha256":"9095ef86c4b9de17a32566fbcd73ac405ff1ec8bc085c3b945b152d5b4394dab","role":"bill","text":"","pages":67,"page_start":1,"page_end":67,"text_start":0,"text_end":200755,"text_sha256":"2c74a729afdba0366b316ca8308c1278d264359ba90207d3462184e66422e007","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"sejm/10/print/3278","provenance":"source_relation","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3278/3278.pdf","text_sha256":"2c74a729afdba0366b316ca8308c1278d264359ba90207d3462184e66422e007","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3278/3278.pdf","text_sha256":"2c74a729afdba0366b316ca8308c1278d264359ba90207d3462184e66422e007","block_id":"part:0","start":0,"end":1105,"quote":"Druk nr 3278\n Warszawa, 28 października 2026 r.\nSEJM\nRZECZYPOSPOLITEJ POLSKIEJ\nX kadencja\n\nPrezes Rady Ministrów\nRM-0610-189-26\n\n Pan\n Włodzimierz Czarzasty\n Marszałek Sejmu\n Rzeczypospolitej Polskiej\n\nSzanowny Panie Marszałku,\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam\nSejmowi Rzeczypospolitej Polskiej projekt ustawy\n - zmieniającej ustawę o zmianie ustawy\no systemie oświaty oraz niektórych innych\nustaw oraz ustawę o rynku pracy i służbach\nzatrudnienia.\nJednocześnie, z uwagi na konieczność wejścia w życie zmian przed końcem\nbieżącego roku  budżetowego, przedstawiam wniosek o skrócenie postępowania\nz projektem ustawy.\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac\nparlamentarnych został upoważniony Minister Edukacji.\n\n Z poważaniem\n Donald Tusk\n /podpisano kwalifikowanym podpisem elektronicznym/\n\n                Tłoczono z polecenia  Marszałka Sejmu Rzeczypospolitej Polskiej\n\n\fProjekt\nU S T AWA\nz dnia\nzmieniająca ustawę o zmianie ustawy o systemie oświaty oraz niektórych innych ustaw\noraz ustawę o rynku pracy i służbach zatrudnienia\nArt. 1"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3278/3278.pdf","text_sha256":"2c74a729afdba0366b316ca8308c1278d264359ba90207d3462184e66422e007","block_id":"part:0","start":3844,"end":3866,"quote":"Ustawa wchodzi w życie"}],"limitations":["missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":200755,"page_start":1,"page_end":67,"losses":[]}],"normative_sha256":"e7acfea6f4673bb3e38a7326ab8fe5c4f774e7e10d2d8e8d6f7e93ad232b29f7"}}');
