INSERT INTO "document_work" VALUES('amendments/133',10,'2870','waiting','2026-10-21T18:05:02+00:00','{"key":"amendments/133","term":10,"number":"2870","change_id":133,"bill_json":"{\"summary\":{\"term\":10,\"number\":\"2870\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych\",\"description\":\"projekt dotyczy wprowadzenia stałych i jednolitych zasad przygotowania i zabezpieczania najważniejszych wydarzeń państwowych oraz międzynarodowych organizowanych w Polsce. Dzięki nowym przepisom służby będą mogły sprawniej planować działania i skuteczniej reagować na zagrożenia, w tym o charakterze terrorystycznym. Rozwiązania zastąpią przepisy przygotowywane dotychczas odrębnie dla poszczególnych wydarzeń\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-07-22\",\"document_date\":\"2026-07-22\",\"change_date\":\"2026-10-20T08:48:36Z\",\"closure_date\":\"2026-09-18\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-114-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-114-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:obywatelstwo\",\"text:straz_graniczna\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-07-22\",\"print_number\":\"2870\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-07-29\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":