INSERT INTO "document_work" VALUES('amendments/139',10,'2107','waiting','2026-10-22T18:11:13+00:00','{"key":"amendments/139","term":10,"number":"2107","change_id":139,"bill_json":"{\"summary\":{\"term\":10,\"number\":\"2107\",\"title\":\"Rządowy projekt ustawy o przywróceniu prawa do niezależnego i bezstronnego sądu ustanowionego na podstawie prawa przez uregulowanie skutków uchwał Krajowej Rady Sądownictwa podjętych w latach 2018-2025\",\"description\":\"projekt dotyczy przywrócenia prawa do niezależnego i bezstronnego sądu ustanowionego na podstawie prawa przez uregulowanie skutków uchwał w sprawach indywidualnych podjętych przez Krajową Radę Sądownictwa, działającą w okresie od 7 marca 2018 r. do 13 maja 2026 r. Skład Krajowej Rady Sądownictwa w ww. okresie został ukształtowany na podstawie ustawy z dnia 8 grudnia 2017 r. o zmianie ustawy o Krajowej Radzie Sądownictwa oraz niektórych innych ustaw\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-12-29\",\"document_date\":\"2025-12-29\",\"change_date\":\"2026-10-21T08:43:31Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-237-25\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-237-25\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obywatelstwo\",\"text:wizy\",\"text:legalizacja\",\"text:nieruchomosci_cudzoziemcy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2025-12-29\",\"print_number\":\"2107\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na p