fter3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-09-18\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf\",\"kind\":\"text_after3\",\"extra_urls\":[]},\"analysis_sha256\":\"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2\",\"analysis_revision\":3,\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Закон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с перечисленными видами легального пребывания в Польше получают это право наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.\",\"key_changes\":[\"Право на услугу: ПМЖ, резидент ЕС, беженцы и доп. защита, граждане ЕС/ЕЭЗ/Швейцарии и члены семей\",\"Включены разрешения по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust. 1, 186 ust. 1 pkt 3, научная виза, Brexit-соглашение\",\"Карта побыту с отметкой ''dostęp do rynku pracy'' даёт право, кроме студентов, сезонных и краткосрочных работников\",\"Объём: 20–240 часов в месяц (18–65 лет), 20–80 часов (13–18 лет); ставки 49–55 zł брутто в час\",\"Заявление подаётся электронно; иностранец прилагает документ, дающий право на пребывание в Польше\"],\"affected_groups\":[\"иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС\",\"беженцы и лица с дополнительной защитой\",\"граждане ЕС/ЕЭЗ/Швейцарии и члены их семей\",\"обладатели карты побыту с отметкой ''dostęp do rynku pracy''\",\"работники по внутрикорпоративному переводу и научные работники\",\"граждане Великобритании по Brexit-соглашению\"],\"practical_impact\":\"Иностранец с инвалидностью, проживающий в Польше и имеющий соответствующее решение об уровне потребности в поддержке, может бесплатно получить личного ассистента; заявление подаётся только электронно с приложением документа о праве на пребывание.\",\"effective_date\":\"Через 14 дней после опубликования, с исключениями: ст. 6 ust. 1 pkt 1 и часть ст. 8 — через 12 месяцев; ст. 6 ust. 1 pkt 2 и ст. 7 ust. 2–7 — через 14 месяцев; ст. 58–67 и ст. 99 — с первого дня месяца после 5 месяцев от опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон касается социальной поддержки и прямо перечисляет категории иностранцев, получающих право на услугу, но не затрагивает легализацию пребывания или работу.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[\"В перечень оснований добавлены разрешения по ст. 159 ust. 1 и ст. 186 ust. 1 pkt 3 ustawy o cudzoziemcach\",\"Добавлены переходные ограничения максимума часов: 200 часов в 2028 г. и 220 часов в 2029 г.\",\"Уточнены сроки рассмотрения заявлений: до 120 дней (до 31.12.2028), 90 дней, затем 60 дней\",\"Детализирован поэтапный запуск: 90 баллов — через 12/16 месяцев от публикации, 85 — через 17/21, 80 — с 01.09.2028/01.01.2029\",\"Для лиц 13–18 лет и проживающих в учреждениях круглосуточного ухода — заявления с 01.05.2029, право с 01.01.2030\"]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":154338,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-22T16:01:14Z\",\"input_tokens\":77754,\"output_tokens\":1429,\"cache_read_input_tokens\":2652,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":3,\"text_sha256\":\"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2\",\"law_sha256\":null,\"source_checked_at\":\"2026-09-22T16:01:14Z\"},\"editorial\":{\"mnemonic\":null,\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/36702/2025\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2025-11-04\",\"print_number\":\"1929\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2170.html\",\"title\":\"Ustawa o asystencji osobistej osób z niepełnosprawnościami\",\"print_number\":\"832\",\"received\":\"2026-09-22\",\"committees\":[{\"id\":233,\"name\":\"Komisja Rodziny, Polityki Senioralnej i Społecznej\",\"email\":\"krpss@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-08\",\"2026-10-13\"],\"committee_work_completed\":false},\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-14T16:11:24Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-14T16:11:18Z","assessed_at":"2026-10-14T16:11:24Z","novelty":"new_consequence","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"{\"id\":118,\"term\":10,\"number\":\"1929\",\"old_fingerprint\":\"a7850ab982d317aea4cc4d3e291b6a095b79ce72df7649668633e1006adbd6df\",\"new_fingerprint\":\"6d0c033862bef66f3141d297d7faa7040d4761d35b3b2ce9c23c871981a396ce\",\"new_stages\":[{\"stage_name\":\"Stanowisko Senatu\",\"stage_type\":\"SenatePosition\",\"date\":\"2026-10-13\",\"print_number\":\"3213\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":\"wniósł poprawki\",\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-14\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-14\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Polityki Społecznej i Rodziny\",\"children\":[]}],\"closure_detected\":false,\"decision_changed\":false,\"passed\":true,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":{\"amendments\":{\"summary\":\"Документ, переданный из Senat, лишь подтверждает принятие «uchwały w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami» (постановления Сената по закону об асистенции), но не содержит текста самих поправок. Поэтому по этому документу невозможно определить, какие именно изменения Сенат внес в проект и как они соотносятся с нынешним описанием закона.\",\"changes\":[\"В документе отсутствует текст сенатских поправок, их содержание по нему установить нельзя\"],\"affects_foreigners\":false,\"confidence\":0.1},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v11\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3213/3213.pdf\",\"source_kind\":\"senate_amendments\",\"created_at\":\"2026-10-14T16:08:45Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-14T16:11:18Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-14","still_meets":false,"reply_to":15,"edit_message_id":107,"revision_of":136,"amendment_key":"ed50d047b5d58a4142859baed582938f9841872a7737160a18221b1ebc7dd4f2","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}}}','2026-10-16T18:47:43+00:00','{"custom_id":"baa5e39a69291ab55541bfa51bd5f6dd7a5278fd70942090a21578c56495131b","model":"gpt-5.1-2025-11-13","prompt_version":null,"input_tokens":13123,"output_tokens":1595,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"error":null,"context_exceeded":false}','2026-10-16T18:50:54+00:00');
