INSERT INTO "llm_batch_items" VALUES('batch_6ad33720b37881909054230aea47852b','993f49406197cd188d5ddf891e641e645f3f6cfca3894bef21033046c956bb7c','reanalysis',10,'RCL/12408952','{"input_chars":228592,"overflow":false,"truncated":false,"text_source":"documents","source_kind":"rcl","source_url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","revision":2,"text_sha256":"text-v2:559c3fe3f4c4aae96220072d090e61bf3acb2495023ea00be621419d24f0aa74","selection":{"question":"bill_text","state":"selected","belonging":[],"role":[],"version":["rcl/12408952/stage/13196550","projekt UPK III.pdf"],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801248.pdf","members":[],"container_sha256":"bf3d56cf5e8cb011dd81f1bd54924e82390627aa98339e014dbc88df10dd798a","sha256":"bf3d56cf5e8cb011dd81f1bd54924e82390627aa98339e014dbc88df10dd798a","role":"bill","text":"","pages":33,"page_start":1,"page_end":33,"text_start":0,"text_end":66825,"text_sha256":"17433d201fc2d487374264c80933a1e02968958b01b96c8568241b09dd4ee587","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801250.pdf","members":[],"container_sha256":"9551e2be7029f345903da408cb754d3466b1a3f170bb6eee4052349192ce8133","sha256":"9551e2be7029f345903da408cb754d3466b1a3f170bb6eee4052349192ce8133","role":"justification","text":"","pages":39,"page_start":1,"page_end":39,"text_start":0,"text_end":95646,"text_sha256":"0e88403f5e9474f989a718cd8546a1f88b8db21863e1545f1f8b5389e9e658d6","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801249.pdf","members":[],"container_sha256":"3a638eda97ebeade5efe318e53126b0d105900eccedc0ed729e94427d5b0b7c1","sha256":"3a638eda97ebeade5efe318e53126b0d105900eccedc0ed729e94427d5b0b7c1","role":"osr","text":"","pages":20,"page_start":1,"page_end":20,"text_start":0,"text_end":86105,"text_sha256":"6d7d83fbc722967d1cb83cd9c002e7454cf21e89d958b