INSERT INTO "llm_batch_items" VALUES('batch_6ad90a7cf6fc81909ad25b557b5ddfad','4dfea829eb1df9afa1780ae345b3a587bb880013096dfe726770a8d001f9647c','reanalysis',10,'3160','{"input_chars":50033,"overflow":false,"truncated":false,"text_source":"pdf","source_kind":"committee_report","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3243/3243.pdf","revision":3,"text_sha256":"text-v2:52bb06ec7573eb34df226c6e2e060e4c399f389efe5495f0c9bbda3df2869845","selection":{"question":"bill_text","state":"unverified","belonging":[],"role":[],"version":[],"completeness":[],"parts":[{"url":"https://api.sejm.gov.pl/sejm/term10/prints/3243/3243.pdf","members":[],"container_sha256":"e796c4e395af53f69ba8fe74844172870f304d8950f89bb338c25155a49ef271","sha256":"e796c4e395af53f69ba8fe74844172870f304d8950f89bb338c25155a49ef271","role":"bill","text":"","pages":24,"page_start":1,"page_end":24,"text_start":0,"text_end":50033,"text_sha256":"9eb7f58dc22b0f049beb6fc6c5a81a078fc6561183e0bf8b7b39adf97067e1c8","losses":[]}],"observed_parts":[],"rejected":[],"facts":[{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3243/3243.pdf","text_sha256":"9eb7f58dc22b0f049beb6fc6c5a81a078fc6561183e0bf8b7b39adf97067e1c8","block_id":"part:0","start":0,"end":1017,"quote":"Druk nr 3243\n\nX  kadencja\n\nS P R A W O Z D A N I E\nKOMISJI GOSPODARKI I ROZWOJU\n\no rządowym projekcie ustawy  o zmianie ustawy\no wspieraniu nowych inwestycji oraz niektórych\ninnych ustaw (druk nr 3160)\n\nSejm na 66. posiedzeniu w dniu 8 października 2026 r., zgodnie z art. 39 ust . 2 regulaminu\nSejmu skierował powyższy projekt ustawy do Komisji Gospodarki i Rozwoju  w celu\nrozpatrzenia.\n\nKomisja Gospodarki i Rozwoju po roz patrzeniu powyższego projektu ustawy na\nposiedzeniu w dniu 21 października 2026 r.\n\nwnosi:\n\nW y s o k i  S e j m  uchwalić raczy załączony projekt ustawy.\n\nWarszawa, dnia 21 października 2026 r.\n\nSprawozdawca\n\n(-) Jerzy Meysztowicz\nPrzewodniczący Komisji\n\n(-) Rafał Komarewicz\n\n Tłoczono z polecenia Marszałka Sejmu Rzeczypospolitej Polskiej\n\nSEJM\nRZECZYPOSPOLITEJ POLSKIE J \fLiczba stron :  23     Data :   2026-10-21      Nazwa pliku :   V6_2037-1.NK   1\nX kadencja/druk nr 3160\nProjekt\nU S T AWA\nz dnia\no zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw1)\nArt. 1"}],"limitations":["annex_link_unknown","missing_evidence"],"links":[],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":50033,"page_start":1,"page_end":24,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":50033,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"b435fedf4e7aedd8ffa699c9d347c261d31d715cfc266dcbcb00790a0cb6ec09"},"law_sha256":"law-v2:368989bd7e27e754dc3a1eb79a0300fa2c27207ef2fa4602bf9a9f431692e15b","prompt_version":"2026-10-v12","generation":2,"memo_key":"b422e06c39d9fab7073f910b66ce11172192698d3b189343fa96fd7f073a4eec"}','2026-10-21T19:11:53+00:00','{"custom_id":"4dfea829eb1df9afa1780ae345b3a587bb880013096dfe726770a8d001f9647c","model":"gpt-5.1-2025-11-13","prompt_version":null,"input_tokens":19770,"output_tokens":2332,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"error":null,"context_exceeded":false}','2026-10-21T19:18:40+00:00');
