ull,\"proposal\":\"przyjąć poprawki\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-21\",\"print_number\":\"3255\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć poprawki\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_detected\":false,\"decision_changed\":false,\"passed\":true,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":{\"amendments\":{\"summary\":\"Документ комиссии не описывает содержание поправок Сената, а лишь рекомендует Сейму принять все 35 поправок к закону об личной ассистенции лиц с инвалидностью. Неясно, изменяют ли эти поправки объём прав или условия доступа к услуге для иностранцев.\\n\",\"changes\":[\"Комиссия Polityki Społecznej i Rodziny рекомендует принять все 35 поправок Сената к закону.\",\"Часть поправок предлагается голосовать совместно с другими (10 с 14; 13 с 15 и 28; 23 с 26; 24 с 29; 31 с 35).\",\"Текст спrawozdania не содержит описания содержания поправок и их материальных последствий.\"],\"affects_foreigners\":false,\"confidence\":0.23,\"source_evidence\":{\"subject\":\"Sprawozdanie Komisji Polityki Społecznej i Rodziny o uchwale Senatu w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"adopted_on\":\"2026-10-21\",\"decision\":\"amendments\",\"complete\":true,\"resolution_page\":null,\"amendment_pages\":[],\"amendment_quote\":\"Komisja Polityki Społecznej i Rodziny ... wnosi: Wysoki Sejm raczy poprawki Senatu zawarte w: pkt 1 – przyjąć ... pkt 35 – przyjąć.\"}},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf\",\"source_kind\":\"committee_amendments\",\"created_at\":\"2026-10-21T18:29:52Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-21T18:53:55Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-21","still_meets":false,"reply_to":15,"edit_message_id":123,"revision_of":172,"amendment_key":"cf4c167f67585e578404d1de7e40e3b70245872eab258a4b1f8d1622d2827c0b","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}},"amendment_source":null,"explanation":null}','2026-10-21T20:55:57+00:00','{"custom_id":"89d8022a6cb015f25d46af5f445bc1740ca862b722b86e1fe68933abd2fd80c7","model":"gpt-5.1-2025-11-13","prompt_version":null,"input_tokens":134,"output_tokens":709,"cache_read_input_tokens":1664,"cache_creation_input_tokens":0,"error":null,"context_exceeded":false}','2026-10-21T21:00:27+00:00');
