osition\":null,\"proposal\":\"przyjąć poprawki\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-21\",\"print_number\":\"3255\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć poprawki\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_detected\":false,\"decision_changed\":false,\"passed\":true,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":{\"amendments\":{\"summary\":\"Документ комиссии не описывает содержание поправок Сената, а лишь рекомендует Сейму принять все 35 поправок к закону об личной ассистенции лиц с инвалидностью. Неясно, изменяют ли эти поправки объём прав или условия доступа к услуге для иностранцев.\\n\",\"changes\":[\"Комиссия Polityki Społecznej i Rodziny рекомендует принять все 35 поправок Сената к закону.\",\"Часть поправок предлагается голосовать совместно с другими (10 с 14; 13 с 15 и 28; 23 с 26; 24 с 29; 31 с 35).\",\"Текст спrawozdania не содержит описания содержания поправок и их материальных последствий.\"],\"affects_foreigners\":false,\"confidence\":0.23,\"source_evidence\":{\"subject\":\"Sprawozdanie Komisji Polityki Społecznej i Rodziny o uchwale Senatu w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"adopted_on\":\"2026-10-21\",\"decision\":\"amendments\",\"complete\":true,\"resolution_page\":null,\"amendment_pages\":[],\"amendment_quote\":\"Komisja Polityki Społecznej i Rodziny ... wnosi: Wysoki Sejm raczy poprawki Senatu zawarte w: pkt 1 – przyjąć ... pkt 35 – przyjąć.\"}},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf\",\"source_kind\":\"committee_amendments\",\"created_at\":\"2026-10-21T18:29:52Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-21T18:53:55Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-21","still_meets":false,"reply_to":15,"edit_message_id":123,"revision_of":172,"amendment_key":"38015d8a4028a95a9fba86f3f9c5ede06448de9f72dc349893d0beecbc021145","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}},"amendment_source":null,"explanation":null}','2026-10-21T21:37:51+00:00','{"custom_id":"5605fbe17f440940a5ea95bd179f5d7e391493f63b67f41d03697e8a42da7c03","model":"gpt-5.1-2025-11-13","prompt_version":null,"input_tokens":14035,"output_tokens":3866,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"error":null,"context_exceeded":false}','2026-10-21T21:42:59+00:00');
