INSERT INTO "llm_batch_items" VALUES('batch_6ae3994c0c9c8190a7f09698b0ce03a9','1ae8d2162abc51088fb55ce377e554cc5c663979b5c445ae919036c6a027d2a1','analysis',10,'RCL/12408601','{"input_chars":608481,"overflow":false,"truncated":false,"text_source":"documents","source_kind":"rcl","source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","revision":1,"text_sha256":"text-v2:193ed7229af7dcaf3d276ba2c825d6d03bb37cffe232b5613e8656a3b3a8aac1","selection":{"question":"bill_text","policy_version":"document-selection-v1","state":"selected","belonging":[],"role":[],"version":["rcl/12408601/stage/13194357","Projekt 20.03.2026."],"completeness":[],"parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","members":[],"container_sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","role":"bill","text":"","pages":165,"page_start":1,"page_end":165,"text_start":0,"text_end":345959,"text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769079.pdf","members":[],"container_sha256":"1df0a054620d8dc2bdfeb38bf61b41734b91bc2d4c1bb10d664274a550e88af9","sha256":"1df0a054620d8dc2bdfeb38bf61b41734b91bc2d4c1bb10d664274a550e88af9","role":"justification","text":"","pages":73,"page_start":1,"page_end":73,"text_start":0,"text_end":185158,"text_sha256":"024ef7a3efd75d5c64a39559503a84ce9183008c6f93142369719d2b2fba0c4b","losses":[]},{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769080.pdf","members":[],"container_sha256":"8849709070e4264a5ed1373b2d0fbe3fa39d4b42341c5fd998f699ccc7fb032c","sha256":"8849709070e4264a5ed1373b2d0fbe3fa39d4b42341c5fd998f699ccc7fb032c","role":"osr","text":"","pages":29,"page_start":1,"page_end":29,"text_start":0,"text_end":131304,"text_sha256":"7cfd3b14744a034f650c41ff6ea6480bd4186e42ed406fab76b3db0bdb4951fe","losses":[]}],"observed_parts":[{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","members":[],"container_sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","sha256":"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085","role":"bill","text":"","pages":165,"page_start":1,"page_end":165,"text_start":0,"text_end":345959,"text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","losses":[]}],"rejected":[],"facts":[{"kind":"official_link","value":"rcl/12408601/stage/13194357","provenance":"source_relation","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","block_id":"part:0","start":0,"end":0,"quote":""},{"kind":"bill_structure","value":"bill","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","block_id":"part:0","start":0,"end":156,"quote":"Projekt z dnia 20 marca 2026 r.\nU S T A W A\nz dnia\no zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych\ninnych ustaw 1)\nArt. 1"},{"kind":"draft_date","value":"2026-03-20","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","block_id":"part:0","start":0,"end":28,"quote":"Projekt z dnia 20 marca 2026"},{"kind":"coverage","value":"body_through_commencement","provenance":"extracted_text","part_index":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","text_sha256":"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036","block_id":"part:0","start":345176,"end":345198,"quote":"Ustawa wchodzi w życie"}],"limitations":["support_applicability_unknown"],"links":[{"kind":"supporting","source_part":1,"target_part":0,"status":"unknown","evidence":[]},{"kind":"supporting","source_part":2,"target_part":0,"status":"unknown","evidence":[]}],"coverage":[{"part_index":0,"stage":"extraction","start":0,"end":345959,"page_start":1,"page_end":165,"losses":[]},{"part_index":1,"stage":"extraction","start":0,"end":185158,"page_start":1,"page_end":73,"losses":[]},{"part_index":2,"stage":"extraction","start":0,"end":131304,"page_start":1,"page_end":29,"losses":[]},{"part_index":0,"stage":"analysis","start":0,"end":345959,"page_start":null,"page_end":null,"losses":[]}],"normative_sha256":"d544a1ea7b8a8c03710531446ed81ce83c970c4449429b992903b9faf85dce6d"},"law_sha256":"law-v2:fac88797e71d1acaf8656fcb5732a3668ec074766e9534f07a95272fbbd3dd5c","prompt_version":"2026-10-v13","request_sha256":"1fe039ec8ff4e37ff47e5282564600ea8cd4ed4bbdebe0df2f61e311b0364adf","generation":0,"memo_key":"23205207dea7fa3a4b0f18fa1c78c9d1906b15cbddc53421e359f8479a6b88f7","located":{"summary":null,"stages":null,"document":{"url":"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf","kind":"rcl","extra_urls":["https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769079.pdf","https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769080.pdf"],"senate":null,"alternatives":[],"compare_versions":true,"normative_urls":[],"required_urls":[],"amendment_urls":[],"version_basis":["rcl/12408601/stage/13194357","Projekt 20.03.2026."],"official_link_conflict":false}},"text":"Projekt z dnia 20 marca 2026 r.\nU S T A W A\nz dnia\no zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych\ninnych ustaw 1)\nArt. 1. W ustawie z dnia 9 czerwca 2011 r. o wspieraniu rodziny i systemie pieczy\nzastępczej (Dz. U. z 2025 r. poz. 49 i 1301) wprowadza się następujące zmiany:\n1) w art. 2 ust. 3 otrzymuje brzmienie:\n„3. Jednostkami organizacyjnymi wspierania rodziny i systemu pieczy zastępczej są\njednostki organizacyjne jednostek samorządu terytorialnego wykonujące zadania w\nzakresie wspierania rodziny i systemu pieczy zastępczej, placówki wsparcia dziennego,\norganizatorzy rodzinnej pieczy zastępczej, placówki opiekuńczo-wychowawcze,\nregionalne placówki opiekuńczo-terapeutyczne, ośrodki adopcyjne oraz podmioty,\nktórym zlecono realizację zadań z zakresu wspierania rodziny i systemu pieczy\nzastępczej.”;\n1) Niniejsza ustawa zmienia następujące ustawy:\n ustawę z dnia 25 lutego 1964 r. – Kodeks rodzinny i opiekuńczy, ustawę z dnia 17 listopada 1964 – Kodeks\npostępowania cywilnego, ustawę z dnia 17 czerwca 1966 r. o postępowaniu egzekucyjnym w administracji,\nustawę z dnia 15 lutego 1992 r. o podatku dochodowym od osób fizycznych,  ustawę z dnia 30 listopada 1995\nr. o pomocy państwa w spłacie niektórych kredytów mieszkaniowych, udzielaniu premii gwarancyjnych oraz\nrefundacji bankom wypłaconych premii gwarancyjnych, ustawę z dnia 29 sierpnia 1997 r. – Prawo bankowe,\nustawę z dnia 27 sierpnia 1997 r. o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób\nniepełnosprawnych, ustawę z dnia 17 grudnia 1998 r.  o emeryturach i rentach z Funduszu Ubezpieczeń\nSpołecznych, ustawę z dnia 24 kwietnia 2003 r. o działalności pożytku publicznego i o wolontariacie, ustawę\nz dnia 28 listopada 2003 r. o świadczeniach rodzinnych, ustawę z dnia 12 marca 2004 o pomocy społecznej,\nustawę z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych,\nustawę z dnia 5 listopada 2009 r. o spółdzielczych kasach oszczędnościowo-kredytowych, ustawę  z dnia 9\nkwietnia 2010 r. o udostępnianiu informacji gospodarczych i wymianie danych gospodarczych, ustawę z dnia\n15 kwietnia 2011 r. o działalności leczniczej, ustawę z dnia 28 kwietnia 2011 r. o systemie informacji w\nochronie zdrowia, ustawę z dnia 15 lipca 2011 r. o zawodach pielęgniarki i położnej, ustawę z dnia 5 grudnia\n2014 r. o Karcie Dużej Rodziny, ustawę z dnia 11 lutego 2016 r. o pomocy państwa w wychowywaniu dzieci,\nustawę z dnia 26 stycznia 2018 r. o wykonywaniu niektórych czynności organu centralnego w sprawach\nrodzinnych z zakresu obrotu prawnego na podstawie prawa Unii Europejskiej i umów międzynarodowych,\nustawę z dnia 2 marca 2020 r. o szczególnych rozwiązaniach związanych z zapobieganiem, przeciwdziałaniem\ni zwalczaniem COVID-19, innych chorób zakaźnych oraz wywołanych nimi sytuacji kryzysowych, ustawę z\ndnia 24 maja 2000 r. o Krajowym Rejestrze Karnym, ustawę z dnia 15 maja 2024 r. o wspieraniu rodziców w\naktywności zawodowej oraz w wychowaniu dziecka – „Aktywny rodzic”, ustawę z dnia 20 marca 2025 r. o\nrynku pracy i służbach zatrudnienia.\f– 2 –\n2) w art. 3 ust. 2 otrzymuje brzmienie:\n„2. Obowiązek, o którym mowa w ust. 1, jednostki samorządu terytorialnego oraz\norgany administracji rządowej realizują w szczególności we współpracy z jednostkami\nsektora finansów publicznych, środowiskiem lokalnym, sądami i ich organami\npomocniczymi, Policją, przedszkolami, szkołami i podmiotami, o których mowa w art.\n2 pkt 3–8 ustawy z dnia 14 grudnia 2016 r. Prawo oświatowe (Dz. U. z 2025 r. poz. 1043,\n1160 i 1837), podmiotami leczniczymi, organizacjami pozarządowymi lub podmiotami, o\nktórych mowa w art. 3 ust. 3 ustawy z dnia 24 kwietnia 2003 r. o działalności pożytku\npublicznego i wolontariacie (Dz. U. z 2025 r. poz. 1338) działającymi na rzecz dziecka i\nrodziny.”;\n3) w art. 5 ust. 3 otrzymuje brzmienie:\n„3. Przepisy działu III stosuje się także do małoletniego cudzoziemca\nniewymienionego w ust. 1 pkt 2–6, przebywającego na terytorium Rzeczypospolitej\nPolskiej.”;\n4) art. 6 otrzymuje brzmienie:\n„Art. 6. 1. Ilekroć w ustawie jest mowa o :\n1) wójcie, należy przez to rozumieć także burmistrza oraz prezydenta miasta;\n2)pozarządowym organizatorze rodzinnej pieczy zastępczej, należy przez to rozumieć\norganizację pozarządową lub podmiot, o którym mowa w art. 3 ust. 3 ustawy z dnia\n24 kwietnia 2003 r. o działalności pożytku publicznego i wolontariacie albo ich\noddział, który, zgodnie z art. 76a, ustanowiono pozarządowym organizatorem\nrodzinnej pieczy zastępczej;\n3)zaświadczeniu, należy przez to rozumieć dokument urzędowy sporządzony przez\norgany władzy publicznej i inne organy państwowe w zakresie ich działania albo w\nzakresie zadań zleconych przez ustawę, jednostkom organizacyjnym wspierania\nrodziny i systemu pieczy zastępczej w zakresie umieszczenia dziecka w rodzinie\nzastępczej, rodzinnym domu dziecka, placówce opiekuńczo-wychowawczej albo\nregionalnej placówce opiekuńczo-terapeutycznej bądź przebywania dziecka w tych\nformach pieczy zastępczej, albo ośrodkowi adopcyjnemu o przysposobieniu\ndziecka, stanowiąc dowód tego, co zostało w nich urzędowo zaświadczone w\nrozumieniu art. 76 ustawy z dnia 14 czerwca 1960 r. Kodeks postępowania\nadministracyjnego (Dz.U. z 2025 r. poz. 1691). \f– 3 –\n5) po art. 6 dodaje się art. 6a w brzmieniu:\n„Art. 6a. Do wydawania zaświadczenia o:\n1) umieszczeniu lub przebywaniu dziecka w rodzinie zastępczej lub rodzinnym domu\ndziecka wydawanego przez osobę kierującą podmiotem, któremu powiat zlecił\nrealizację tego zadania na podstawie art. 190, albo pozarządowym organizatorem\nrodzinnej pieczy zastępczej;\n2) umieszczeniu dziecka w :\na) placówce opiekuńczo-wychowawczej wydawanego przez dyrektora tej\nplacówki,\nb) regionalnej placówce opiekuńczo-terapeutycznej wydawanego przez dyrektora\ntej placówki,\n3) przysposobieniu dziecka wydawanego przez ośrodek adopcyjny\n– mają zastosowanie przepisy dotyczące wydawania zaświadczeń art. 217-219\nustawy z dnia 14 czerwca 1960 r. - Kodeks postępowania administracyjnego.”;\n6) w art. 7 ust. 1 otrzymuje brzmienie:\n„1. Podmioty i osoby realizujące zadania w zakresie wspierania rodziny i systemu\npieczy zastępczej przetwarzają dane osobowe osób, do których stosuje się niniejszą\nustawę, członków ich rodzin, a także osób współpracujących lub działających w imieniu\ni na rzecz podmiotów, o których mowa w art. 3 ust. 2, realizujących działania na rzecz\ndziecka i rodziny w zakresie niezbędnym do realizacji zadań wynikających z niniejszej\nustawy w celu ochrony bezpieczeństwa i zapewnienia opieki dzieciom.”;\n7) w art. 7b :\na) ust. 1 otrzymuje brzmienie:\n„1. Rodziną wspierającą, rodziną opiekuńczą, kandydatem do pełnienia funkcji\nrodziny zastępczej niezawodowej i zawodowej, rodziną zastępczą niezawodową i\nzawodową, kandydatem do prowadzenia rodzinnego domu dziecka, osobą\nprowadzącą rodzinny dom dziecka, rodziną pomocową, kandydatem do\nprzysposobienia dziecka, osobą podejmującą się wspierania działań\nwychowawczych, o której mowa w art. 96, kierownikiem, dyrektorem, a także osobą\nzatrudnioną, osobą świadczącą usługi lub wolontariuszem, w jednostce\norganizacyjnej wspierania rodziny i systemie pieczy zastępczej, rodzinie zastępczej\nlub rodzinnym domu dziecka, opiekunem usamodzielnienia oraz przedstawicielem,\no którym mowa w art. 167a ust. 3, może być osoba:\f– 4 –\n1) która nie figuruje w bazie danych Rejestru Sprawców Przestępstw na Tle\nSeksualnym z dostępem ograniczonym lub w bazie danych Rejestru osób, w\nstosunku do których Państwowa Komisja do spraw przeciwdziałania\nwykorzystaniu seksualnemu małoletnich poniżej lat 15 wydała postanowienie\no wpisie w tym rejestrze;\n2) która nie była skazana prawomocnym wyrokiem za umyślne przestępstwo\nścigane z oskarżenia publicznego lub umyślne przestępstwo skarbowe;\n3) wobec której nie orzeczono zakazu prowadzenia działalności związanej\nz wychowywaniem, leczeniem, edukacją małoletnich lub opieką nad nimi lub\nzakazu przebywania w określonych środowiskach lub miejscach,\nkontaktowania się z określonymi osobami, zbliżania się do określonych osób\nlub opuszczania określonego miejsca pobytu bez zgody sądu;\n4) wobec której nie orzeczono prawomocnie środków wychowawczych, środka\nleczniczego lub środka poprawczego na podstawie ustawy z dnia 9 czerwca\n2022 r. o wspieraniu i resocjalizacji nieletnich (Dz. U. z 2024 r. poz. 978 i 1228\noraz z 2025 r. poz. 1872) w wyniku popełnienia przez nią przestępstwa lub\nprzestępstwa skarbowego.\",\nb) po ust. 1 dodaje się ust. 1a–1c w brzmieniu:\n„1a. Kandydatem do pełnienia funkcji rodziny zastępczej spokrewnionej albo\nrodziną zastępczą spokrewnioną, może być osoba:\n1) która nie figuruje w bazie danych Rejestru Sprawców Przestępstw na Tle\nSeksualnym z dostępem ograniczonym lub w bazie danych Rejestru osób, w\nstosunku do których Państwowa Komisja do spraw przeciwdziałania\nwykorzystaniu seksualnemu małoletnich poniżej lat 15 wydała postanowienie\no wpisie w tym rejestrze;\n2) która nie była skazana prawomocnym wyrokiem za umyślne przestępstwo:\na)określone w ustawie z dnia 6 czerwca 1997 r. – Kodeks karny (Dz. U.\nz 2025 r. poz. 383, 1818 i 1872) przeciwko:\n–życiu i zdrowiu,\n–wolności, z wyjątkiem przestępstwa określonego w art. 192 i 193,\n– wolności seksualnej i obyczajności,\n– rodzinie i opiece, \f– 5 –\n– czci i nietykalności cielesnej, z wyjątkiem przestępstwa określonego\nw art. 212–216,\nb) określone w rozdziale 7 ustawy z dnia 29 lipca 2005 r. o przeciwdziałaniu\nnarkomanii (Dz. U. z 2023 r. poz. 1939);\n3) wobec której nie orzeczono zakazu prowadzenia działalności związanej\nz wychowywaniem, leczeniem, edukacją małoletnich lub opieką nad nimi lub\nzakazu przebywania w określonych środowiskach lub miejscach,\nkontaktowania się z określonymi osobami, zbliżania się do określonych osób\nlub opuszczania określonego miejsca pobytu bez zgody sądu;\n4) wobec której nie orzeczono prawomocnie środków wychowawczych, środka\nleczniczego lub środka poprawczego na podstawie ustawy z dnia 9 czerwca\n2022 r. o wspieraniu i resocjalizacji nieletnich w wyniku popełnienia przez nią\nprzestępstwa lub przestępstwa skarbowego.\n1b. Przepis ust. 1a stosuje się odpowiednio do osób wspólnie zamieszkujących\nz:\n1) rodziną wspierającą, jeżeli osoby te mają kontakt z dziećmi objętymi\nwsparciem rodziny wspierającej;\n2) kandydatem do pełnienia funkcji rodziny zastępczej spokrewnionej,\nniezawodowej lub zawodowej;\n3) rodziną zastępczą spokrewnioną, niezawodową lub zawodową;\n4) kandydatem do prowadzenia rodzinnego domu dziecka;\n5) osobą prowadzącą rodzinny dom dziecka;\n6) rodziną opiekuńczą;\n7) rodziną pomocową, jeżeli osoby te mają kontakt z dziećmi objętymi opieką\nrodziny pomocowej;\n8) osobą prowadzącą placówkę opiekuńczo-wychowawczą typu rodzinnego;\n9) kandydatem do przysposobienia dziecka.\n1c. Przepisu ust. 1 pkt 2 i ust. 1b nie stosuje się w przypadku gdy\nprzysposobienie dotyczy przysposobienia dziecka współmałżonka.\";\nc) w ust. 2:\n– wprowadzenie do wyliczenia otrzymuje brzmienie:\n„2. Informację o figurowaniu albo niefigurowaniu w bazie danych Rejestru\nSprawców Przestępstw na Tle Seksualnym z dostępem ograniczonym lub w bazie \f– 6 –\ndanych Rejestru osób, w stosunku do których Państwowa Komisja do spraw\nprzeciwdziałania wykorzystaniu seksualnemu małoletnich poniżej lat 15 wydała\npostanowienie o wpisie w tym rejestrze oraz Krajowym Rejestrze Karnym w\nzwiązku ze skazaniem prawomocnym wyrokiem za umyślne przestępstwo ścigane z\noskarżenia publicznego lub umyślne przestępstwo skarbowe oraz informację o\norzeczeniu albo nieorzeczeniu  wobec osoby podlegającej sprawdzeniu zakazu\nprowadzenia działalności związanej z wychowywaniem, leczeniem, edukacją\nmałoletnich lub opieką nad nimi lub zakazu przebywania w określonych\nśrodowiskach lub miejscach, kontaktowania się z określonymi osobami, zbliżania się\ndo określonych osób lub opuszczania określonego miejsca pobytu bez zgody sądu, a\ntakże prawomocnego środka wychowawczego, środka leczniczego lub środka\npoprawczego w zakresie wynikającym, z ust. 1-1c, nie rzadziej niż co 24 miesiące,\nsprawdza i potwierdza, w odniesieniu do:”,\n– pkt 1 otrzymuje brzmienie:\n„1) rodziny wspierającej lub osób wspólnie zamieszkujących z rodziną\nwspierającą– odpowiednio wójt, upoważniony przez niego pracownik\nurzędu lub innej jednostki organizacyjnej gminy albo kierownik podmiotu,\nktóremu gmina zleciła realizację tego zadania na podstawie art. 190 – w\ncelu weryfikacji wymagań dotyczących rodziny wspierającej lub osób\nwspólnie zamieszkujących z rodziną wspierającą;”,\n– po pkt 1 dodaje się pkt 1a i 1b w brzmieniu:\n„1a) wolontariuszy w placówkach wsparcia dziennego – kierownik placówki\nwsparcia dziennego – w celu weryfikacji wymagań dotyczących\nwolontariuszy w placówkach wsparcia dziennego;\n1b) rodzinę opiekuńczą, osób wspólnie zamieszkujących z rodziną opiekuńczą\nlub wolontariuszy w rodzinach opiekuńczych – odpowiednio wójt,\nupoważniony przez niego pracownik urzędu lub innej jednostki\norganizacyjnej gminy albo kierownik podmiotu, któremu gmina zleciła\nrealizację tego zadania na podstawie art. 190 – w celu weryfikacji\nwymagań dotyczących rodziny opiekuńczej, osób wspólnie\nzamieszkujących z rodziną opiekuńczą lub wolontariuszy w rodzinach\nopiekuńczych;”,\f– 7 –\n– pkt 2 otrzymuje brzmienie:\n„2) kandydatów do pełnienia funkcji rodziny zastępczej lub prowadzenia\nrodzinnego domu dziecka, rodziny zastępcze, osób prowadzących rodzinne\ndomy dziecka, rodziny pomocowe, wolontariuszy w rodzinie zastępczej,\nrodzinnym domu dziecka lub rodzinie pomocowej oraz osób wspólnie\nzamieszkujących z:\na) kandydatem do pełnienia funkcji rodziny zastępczej lub prowadzenia\nrodzinnego domu dziecka,\nb)rodziną zastępczą,\nc)osobą prowadzącą rodzinny domy dziecka,\nd)rodziną pomocową,\n–  organizator rodzinnej pieczy zastępczej – w celu weryfikacji wymagań\ndotyczących kandydatów do pełnienia funkcji rodziny zastępczej lub\nprowadzenia rodzinnego domu dziecka, osób tworzących rodziny\nzastępcze, osób prowadzących rodzinne domy dziecka, osób tworzących\nrodziny pomocowe, osób wspólnie zamieszkujących z tymi kandydatami\nlub osobami i wolontariuszy w rodzinie zastępczej, rodzinnym domu\ndziecka lub rodzinie pomocowej;”,\n– pkt 6 otrzymuje brzmienie:\n„6) osób podejmujących się wspierania działań wychowawczych, o których\nmowa w art. 96, wolontariuszy w placówce opiekuńczo-wychowawczej lub\nregionalnej placówce opiekuńczo-terapeutycznej – dyrektor odpowiednio\nplacówki opiekuńczo-wychowawczej albo regionalnej placówki\nopiekuńczo-terapeutycznej – w celu weryfikacji wymagań dotyczących\nosób podejmujących się wspierania działań wychowawczych, o których\nmowa w art. 96, wolontariuszy w placówce opiekuńczo-wychowawczej lub\nregionalnej placówce opiekuńczo-terapeutycznej lub osób wspólnie\nzamieszkujących z osobami prowadzącymi placówkę opiekuńczo-\nwychowawczą typu rodzinnego;”,\n– po pkt 6 kropkę zastępuje się średnikiem i dodaje się pkt 7 i 8 w brzmieniu:\n„7) opiekunów usamodzielnienia, a także osób wspólnie zamieszkujących z\nosobami prowadzącymi placówkę opiekuńczo-wychowawczą typu\nrodzinnego – odpowiednio starosta, upoważniony przez niego pracownik \f– 8 –\nurzędu lub innej jednostki organizacyjnej starostwa albo kierownik\npodmiotu, któremu powiat zlecił realizację tego zadania na podstawie art.\n190 – w celu weryfikacji wymagań dotyczących opiekunów\nusamodzielnienia;\n8) przedstawicieli, o których mowa w art. 167a ust. 3 – organ centralny,\no którym mowa w art. 187 ust. 1 pkt 9 – w celu weryfikacji wymagań\ndotyczących przedstawicieli.”,\nd) po ust. 2 dodaje się ust. 3–5 w brzmieniu:\n„3. W przypadku pozyskania i potwierdzenia informacji o figurowaniu, osoby\npodlegającej sprawdzeniu w zakresie, o którym mowa w ust. 1–1c:\n1) w bazie danych Rejestru Sprawców Przestępstw na Tle Seksualnym z dostępem\nograniczonym lub w bazie danych Rejestru osób, w stosunku do których\nPaństwowa Komisja do spraw przeciwdziałania wykorzystaniu seksualnemu\nmałoletnich poniżej lat 15 wydała postanowienie o wpisie w tym rejestrze lub\n2) w Krajowym Rejestrze Karnym jako:\n a) osoby skazanej prawomocnym wyrokiem za umyślne przestępstwo ścigane\nz oskarżenia publicznego lub za umyślne przestępstwo skarbowe,\nb) osoby, wobec której orzeczono zakaz prowadzenia działalności związanej z\nwychowywaniem, leczeniem, edukacją małoletnich lub opieką nad nimi,\n c) osoby, wobec której orzeczono zakaz przebywania w określonych\nśrodowiskach lub miejscach, kontaktowania się z określonymi osobami,\nzbliżania się do określonych osób lub opuszczania określonego miejsca pobytu\nbez zgody sądu,\nd) osoby, wobec której orzeczono prawomocnie środek wychowawczy, środek\nleczniczy lub środek poprawczy na podstawie ustawy z dnia 9 czerwca 2022 r.\no wspieraniu i resocjalizacji nieletnich, w wyniku popełnienia przez nią\nprzestępstwa lub przestępstwa skarbowego\n– osobę tę natychmiast odsuwa się od czynności związanych z opieką lub\nwychowaniem odpowiednio osoby lub dziecka.\n4. W celu potwierdzenia spełniania warunków, o których mowa w ust. 1–1c,\nosoba osoby podlegającej sprawdzeniu posiadająca obywatelstwo innego państwa\nniż Rzeczpospolita Polska, przedkłada odpowiedniemu podmiotowi, o którym mowa\nw ust. 2, informację o:\f– 9 –\n1) niekaralności w zakresie w jakim podlega sprawdzeniu wynikającym z ust. 1–\n1b;\n2) nie orzeczeniu w stosunku do tej osoby zakazu prowadzenia działalności\nzwiązanej z wychowywaniem, leczeniem, edukacją małoletnich lub opieką nad\nnimi lub zakazu przebywania w określonych środowiskach lub miejscach,\nkontaktowania się z określonymi osobami, zbliżania się do określonych osób\nlub opuszczania określonego miejsca pobytu bez zgody sądu; albo\n3) niekaralności za odpowiadające tym przestępstwom czyny zabronione lub\nzakazy określone w przepisach prawa obcego, uzyskaną z właściwego rejestru\nkarnego państwa, którego obywatelem jest ta osoba.\n5. W zakresie nieuregulowanym niniejszą ustawą przepisy ustawy z dnia 16\nmaja 2016 r. o przeciwdziałaniu zagrożeniom przestępczości na tle seksualnym i\nochronie małoletnich, stosuje się odpowiednio.”;\n8) po art. 7b dodaje się art. 7c w brzmieniu:\n„Art. 7c. 1. Osobie prowadzącej rodzinny dom dziecka, rodzinie zastępczej\nzawodowej, rodzinie zastępczej niezawodowej, rodzinie pomocowej, kierownikowi i\nosobom pracującym z dziećmi w placówce wsparcia dziennego, dyrektorowi i osobom\npracującym z dziećmi w placówce opiekuńczo-wychowawczej, regionalnej placówce\nopiekuńczo-wychowawczej, asystentowi rodziny, a także koordynatorowi rodzinnej\npieczy zastępczej oraz pracownikowi organizatora rodzinnej pieczy zastępczej, podczas i\nw związku z wykonywaniem czynności w ramach swoich obowiązków, przysługuje\nochrona przewidziana dla funkcjonariuszy publicznych.\n2. Ochrona, o której mowa w ust. 1, przysługuje także w zakresie kontaktów z\nrodzinami z którymi prowadzona jest praca z rodziną lub udzielna jest im pomoc w opiece\ni wychowaniu dziecka, a także kontaktów z rodzinami dziecka umieszczonego w pieczy\nzastępczej.”;\n9) w art. 10 ust. 1 otrzymuje brzmienie:\n„1. Z zastrzeżeniem art. 11a, pracę z rodziną organizuje gmina lub podmiot, któremu\ngmina zleciła realizację tego zadania na podstawie art. 190.”;\n10) art. 11 otrzymuje brzmienie\n„Art. 11. 1. W przypadku gdy ośrodek pomocy społecznej albo centrum usług\nspołecznych poweźmie informację o rodzinie przeżywającej trudności w wypełnianiu\nfunkcji opiekuńczo-wychowawczych, pracownik socjalny ośrodka pomocy społecznej \f– 10 –\nalbo centrum usług społecznych przeprowadza w tej rodzinie wywiad środowiskowy, na\nzasadach określonych w ustawie z dnia 12 marca 2004 r. o pomocy społecznej (Dz.U. z\n2024 r. poz. 1283 i 1572).\n2. Po przeprowadzeniu wywiadu, o którym mowa w ust. 1, pracownik socjalny\nośrodka pomocy społecznej dokonuje analizy sytuacji rodziny.\n3. Jeżeli z analizy, o której mowa w ust. 2, wynika konieczność przydzielenia\nrodzinie asystenta rodziny, pracownik socjalny ośrodka pomocy społecznej albo centrum\nusług społecznych występuje do kierownika jednostki organizacyjnej lub podmiotu, o\nktórym mowa w art. 17 ust. 1 pkt 1, z wnioskiem o przydzielenie rodzinie asystenta\nrodziny.\n4. Po otrzymaniu wniosku, o którym mowa w ust. 3, kierownik jednostki\norganizacyjnej lub podmiotu, o którym mowa w art. 17 ust. 1 pkt 1, przydziela rodzinie\nasystenta rodziny.\n5. W przypadku gdy rodzicem wychowującym dziecko jest małoletni opuszczający\nmłodzieżowy ośrodek wychowawczy, młodzieżowy ośrodek socjoterapii, okręgowy\nośrodek wychowawczy, schronisko dla nieletnich lub zakład poprawczy, pracownik\nsocjalny ośrodka pomocy społecznej albo centrum usług społecznych, przeprowadza u\ntego rodzica wywiad, o którym mowa w ust. 1-3, a następnie kierownik jednostki\norganizacyjnej lub podmiotu, o których mowa w art. 17 ust. 1 pkt 1, przydziela temu\nrodzicowi asystenta rodziny, chyba że asystent rodziny został mu już przydzielony.\n6. W przypadku rodziny, z której dziecko zostało po raz pierwszy umieszczone\nw pieczy zastępczej kierownik jednostki organizacyjnej lub podmiotu, o którym mowa w\nart. 17 ust. 1 pkt 1, przydziela tej rodzinie asystenta rodziny, chyba że rodzinie tej asystent\nrodziny został już przydzielony.\n7. W przypadku rodziny dziecka umieszczonego w pieczy zastępczej, z której\nrodzeństwo tego dziecka zostało również umieszczone w pieczy zastępczej lub dziecko\nzostało po raz kolejny umieszczone w pieczy zastępczej, kierownik jednostki\norganizacyjnej lub podmiotu, o którym mowa w art. 17 ust. 1 pkt 1, może przydzielić tej\nrodzinie asystenta rodziny, chyba że tej rodzinie asystent rodziny został już przydzielony.\n8. W przypadku rodzica, który zgodnie z art. 109 § 2 ustawy z dnia 25 lutego 1964 r.\n– Kodeks rodzinny i opiekuńczy (Dz. U. z 2023 r. poz. 1606 i 2809 oraz z 2025 r. poz.\n897), został zobowiązany do pracy z asystentem rodziny kierownik jednostki\norganizacyjnej lub podmiotu, o których mowa w art. 17 ust. 1 pkt 1, przydziela temu \f– 11 –\nrodzicowi asystenta rodziny. Przepisu art. 8 ust. 3, w zakresie uzyskania zgody rodzica,\nnie stosuje się.\n9. W przypadku gdy rodzic, który zgodnie z art. 109 § 2 ustawy z dnia 25 lutego\n1964 r. – Kodeks rodzinny i opiekuńczy, został zobowiązany do pracy z asystentem\nrodziny, nie wywiązuje się z tego obowiązku poprzez brak lub odmowę współpracy,\nkierownik jednostki organizacyjnej lub podmiotu, o których mowa w art. 17 ust. 1 pkt 1,\nzawiadamia o tym fakcie sąd.\n10. Asystent rodziny może być przydzielony także na wniosek rodzica\nwychowującego dziecko.\n11. W przypadku wniosku, o którym mowa w ust. 10, kierownik jednostki\norganizacyjnej lub podmiotu, o których mowa w art. 17 ust. 1 pkt 1, przydziela temu\nrodzicowi asystenta rodziny lub prowadzi z rodziną pracę w formie, o której mowa w art.\n10 ust. 3.\n12. Przepisów ust. 1–11 nie stosuje się do rodzin zastępczych i rodzinnych domów\ndziecka, z zastrzeżeniem ust. 13.\n13. W uzasadnionych przypadkach kierownik jednostki organizacyjnej lub\npodmiotu, o których mowa w art. 17 ust. 1 pkt 1, może przydzielić asystenta rodziny\nrodzinie zastępczej spokrewnionej.”;\n11) po art. 11 dodaje się art. 11a w brzmieniu:\n„Art. 11a. 1. Rodzinie dziecka umieszczonego w pieczy zastępczej asystenta rodziny\nmoże przydzielić, po uzgodnieniu z gminą właściwą w zakresie prowadzenia pracy z\nrodziną, kierownik jednostki organizacyjnej powiatu organizującego pieczę zastępczą lub\nkierownik podmiotu, któremu powiat zlecił organizację rodzinnej pieczy zastępczej na\npodstawie art. 190.\n2. Asystent rodziny przydzielony na zasadach określonych w ust. 1, może prowadzić\npracę z rodziną przez okres, w którym dziecko jest umieszczone w pieczy zastępczej, nie\ndłużej niż przez okres 6 miesięcy od dnia uchylenia postanowienia o umieszczeniu\ndziecka w pieczy zastępczej.\n3. W okresie, w którym pracę z rodziną prowadzi asystent rodziny przydzielony na\nzasadach określonych w ust. 1, kierownik jednostki organizacyjnej lub podmiotu, o\nktórych mowa w art. 17 ust. 1 pkt 1, nie są obowiązani do przydzielenia tej rodzinie\nasystenta rodziny.\f– 12 –\n4. W przypadku uzasadnionej potrzeby wsparcia rodziny po upływie okresu, na\nktóry został przydzielony asystent rodziny na zasadach określonych w ust. 1, pracę z\nrodziną prowadzi asystent rodziny przydzielony przez kierownika jednostki\norganizacyjnej lub podmiotu, o których mowa w art. 17 ust. 1 pkt 1.”.\n5. W przypadku przydzielania asystenta rodziny na zasadach określonych w ust. 1\nprzepisów art. 11 nie stosuje się.”;\n12) w art. 12 w ust. 1:\na) w pkt 1 lit. a otrzymuje brzmienie:\n„a)wykształcenie wyższe na kierunku pedagogika, psychologia,\npsychoprofilaktyka, socjologia, nauki o rodzinie lub praca socjalna lub”,\nb) uchyla się pkt 4 i 5;\n13) w art. 13 ust. 1 otrzymuje brzmienie:\n„1. W przypadku wszczęcia przeciwko asystentowi rodziny postępowania karnego\no umyślne przestępstwo ścigane z oskarżenia publicznego albo umyślne przestępstwo\nskarbowe albo wszczęcia przeciwko asystentowi rodziny postępowania karnego o\norzeczenie wobec niego zakazu, o którym mowa w art. 7b ust. 1 pkt 3, zawiesza się go w\npełnieniu obowiązków do czasu prawomocnego zakończenia postępowania.”;\n14) art. 15 otrzymuje brzmienie:\n„Art. 15. 1. Do zadań asystenta rodziny należy podejmowanie działań wspierających\ni zaradczych w celu ochrony dobra dziecka i rodziny, w szczególności:\n1) opracowanie, realizacja i aktualizacja planu pracy z rodziną we współpracy z\nczłonkami rodziny i w konsultacji w szczególności odpowiednio z pracownikiem\nsocjalnym, o którym mowa w art. 11 ust. 1, kierownikiem placówki wsparcia\ndziennego, koordynatorem rodzinnej pieczy zastępczej, rodziną zastępczą lub\nprowadzącym rodzinny dom dziecka, wychowawcą kierującym procesem\nwychowawczym w placówce opiekuńczo-wychowawczej albo w regionalnej\nplacówce opiekuńczo-terapeutycznej, dyrektorem placówki opiekuńczo-\nwychowawczej, dyrektorem regionalnej placówki opiekuńczo-terapeutycznej lub\nz kuratorem;\n2) koordynacja planu pracy z rodziną z planem pomocy dziecku umieszczonemu\nw pieczy zastępczej;\n3) udzielanie pomocy rodzinom w poprawie ich sytuacji życiowej, w tym poradnictwo\nlub trening w zakresie prawidłowego prowadzenia gospodarstwa domowego;\f– 13 –\n4) pedagogizacja rodziców dotycząca prawidłowego wychowania i opieki nad dziećmi;\n5) koordynacja uzyskiwania przez rodzinę specjalistycznego poradnictwa, w tym\npedagogicznego, prawnego lub z zakresu ochrony zdrowia;\n6) wspieranie aktywności społecznej rodzin;\n7) motywowanie członków rodzin do podnoszenia kwalifikacji zawodowych;\n8) motywowanie do udziału w zajęciach grupowych dla rodziców, mających na celu\nkształtowanie prawidłowych wzorców rodzicielskich i umiejętności\npsychospołecznych;\n9) udzielanie wsparcia dzieciom, w szczególności poprzez prowadzenie działań\nwspomagających rozwój, reedukacyjnych i wychowawczo-motywujących;\n10)  udzielanie wsparcia dziecku przez towarzyszenie mu podczas posiedzenia albo\nrozprawy z jego udziałem, o których mowa w art. 76a § 1 ustawy z dnia 6 czerwca\n1997 r. – Kodeks postępowania karnego (Dz. U. z 2025 r. poz. 46, 304, 1178, 1420\ni 1872);\n11) realizacja zadań określonych w ustawie z dnia 4 listopada 2016 r. o wsparciu kobiet\nw ciąży i rodzin „Za życiem” (Dz. U. z 2024 r. poz. 1829);\n12) prowadzenie dokumentacji dotyczącej pracy z rodziną;\n13) dokonywanie odpowiednio we współpracy i w konsultacji z osobami, o których\nmowa w pkt 1, oceny końcowej realizacji planu pracy z rodziną;\n14) monitorowanie funkcjonowania rodziny po zakończeniu pracy z rodziną;\n15) sporządzanie, na wniosek sądu, opinii o rodzinie i jej członkach;\n16) przekazywanie sądowi planu pracy z rodziną, aktualizacji planu pracy z rodziną i\noceny końcowej realizacji planu pracy z rodziną – w przypadku gdy rodzinie został\nprzydzielony asystent rodziny przez sąd lub dziecko zostało umieszczone w pieczy\nzastępczej;\n17) współpraca odpowiednio z jednostkami samorządu terytorialnego oraz organami\nadministracji rządowej, środowiskiem lokalnym, sądami i ich organami\npomocniczymi, Policją, instytucjami oświatowymi, podmiotami leczniczymi, a\ntakże organizacjami pozarządowymi lub podmiotami, o których mowa w art. 3 ust.\n3 ustawy z dnia 24 kwietnia 2003 r. o działalności pożytku publicznego i\nwolontariacie, oraz innymi podmiotami i osobami działającymi na rzecz dziecka i\nrodziny, w szczególności pracownikiem socjalnym, o którym mowa w art. 11 ust. 1,\nkierownikiem placówki wsparcia dziennego, koordynatorem rodzinnej pieczy \f– 14 –\nzastępczej, rodziną zastępczą lub prowadzącym rodzinny dom dziecka,\nwychowawcą kierującym procesem opiekuńczo-wychowawczym w placówce\nopiekuńczo-wychowawczej albo w regionalnej placówce opiekuńczo-\nterapeutycznej, dyrektorem placówki opiekuńczo-wychowawczej, dyrektorem\nregionalnej placówki opiekuńczo-terapeutycznej;\n18)  współpraca z zespołem interdyscyplinarnym lub grupą diagnostyczno-pomocową,\no których mowa w art. 9a ustawy z dnia 29 lipca 2005 r. o przeciwdziałaniu\nprzemocy domowej (Dz. U. z 2024 r. poz. 1673), lub innymi podmiotami, których\npomoc przy wykonywaniu zadań uzna za niezbędną;\n19) koordynowanie pracy z rodziną i na jej rzecz poprzez zwoływanie i prowadzenie\nzespołów składających się ze specjalistów związanych z podmiotami pracującymi z\ndaną rodziną lub dzieckiem, zmierzające do określenia działań i ustalenia wspólnych\ncelów pracy i trybu monitorowania efektów pracy.\n2. Podmioty, o których mowa w ust. 1 pkt 1 i 17, udzielają asystentowi rodziny\nodpowiedniej pomocy w wykonywaniu czynności zawodowych.\n3. Plan pracy z rodziną, o którym mowa w ust. 1 pkt 1, obejmuje w szczególności:\n1)ocenę sytuacji rodziny i dziecka, w tym określenie:\na) zasobów rodzinnych i pozarodzinnych,\nb)  potrzeb dziecka i poziomu ich zaspokojenia przez rodziców,\nc)  potrzeb rodziny w obszarze socjalno-bytowym i poziomu ich zaspokojenia,\nd)  umiejętności opiekuńczych, wychowawczych i społecznych rodziców;\n2)określenie zakresu zmian prowadzących do osiągnięcia stabilizacji przez rodzinę, w\ntym zapobieżenia konieczności umieszczenia dziecka w pieczy zastępczej lub w\nprzypadku pobytu dziecka w pieczy zastępczej umożliwienia jego powrotu do\nrodziny;\n3)określenie działań, które powinny zostać podjęte przez rodzinę i podmioty pracujące\nz daną rodziną lub dzieckiem w celu przezwyciężenia trudności w wypełnianiu\nfunkcji opiekuńczo-wychowawczych wraz ze wskazaniem terminów ich realizacji\noraz przewidywanych efektów;\n4)analizę ryzyka planowanych i realizowanych działań przez rodzinę i podmioty\npracujące z daną rodziną lub dzieckiem oraz sposobów jego minimalizacji;\n5) aktualizacje planu pracy z rodziną .\f– 15 –\n4. Plan pracy z rodziną jest skoordynowany z planem pomocy dziecku\numieszczonemu w pieczy zastępczej.\n5. Aktualizacja planu pracy z rodziną jest dokonywana w przypadku każdej zmiany\nsytuacji rodziny mającej wpływ na informacje zawarte w planie pracy z rodziną, jednak\nnie rzadziej niż co pół roku, i jest przekazywana odpowiednio kierownikowi jednostki\norganizacyjnej gminy albo powiatu, która organizuje pracę z rodziną lub kierownikowi\npodmiotu, któremu gmina albo powiat zleciła organizację pracy z rodziną na podstawie\nart. 190, oraz w przypadku przydzielenia asystenta rodziny przez sąd lub umieszczenia\ndziecka w pieczy zastępczej odpowiednio do właściwego sądu, organizatora rodzinnej\npieczy zastępczej lub dyrektora placówki opiekuńczo-wychowawczej lub dyrektora\nregionalnej placówki opiekuńczo-terapeutycznej.\n6. Realizacja planu pracy z rodziną podlega ocenie końcowej, która zawiera\npodsumowanie efektów pracy z rodziną oraz jest przekazywana kierownikowi jednostki\norganizacyjnej lub podmiotu, o którym mowa w art. 17 ust. 1, oraz w przypadku\nprzydzielenia asystenta rodziny przez sąd lub umieszczenia dziecka w pieczy zastępczej\nodpowiednio do właściwego sądu, organizatora rodzinnej pieczy zastępczej lub dyrektora\nplacówki opiekuńczo-wychowawczej lub dyrektora regionalnej placówki opiekuńczo-\nterapeutycznej;\n7. Plan pracy z rodziną, jego aktualizacja oraz ocena końcowa realizacji planu pracy\nz są tworzone w co najmniej dwóch egzemplarzach, z których jeden otrzymuje rodzina\npotwierdzając jego otrzymanie.\n8. Liczba rodzin, z którymi jeden asystent rodziny może w tym samym czasie\nprowadzić pracę, jest uzależniona od stopnia trudności wykonywanych zadań, jednak nie\nmoże przekroczyć 15.”;\n15) po art. 15 dodaje się art. 15a w brzmieniu:\n„Art. 15a. Po otrzymaniu aktualizacji planu pracy z rodziną lub oceny końcowej\nrealizacji planu pracy z rodziną sąd niezwłocznie analizuje sytuację rodzinną dziecka pod\nkątem ewentualnej zmiany zarządzeń dotyczących dziecka.”;\n16) w art. 16:\na) uchyla się ust. 3,\nb) po ust. 3 dodaje się ust. 4–14 w brzmieniu:\n„4. Asystentowi rodziny zatrudnionemu w pełnym wymiarze czasu pracy,\nprzysługuje wypłacany co miesiąc dodatek do wynagrodzenia w wysokości 400 zł z \f– 16 –\ntytułu wykonywania czynności zawodowych poza miejscem pracy. W przypadku\nzatrudnienia asystenta rodziny w niepełnym wymiarze czasu pracy dodatek\nprzysługuje w wysokości proporcjonalnej do wymiaru czasu pracy. Przepisy art. 86\nust. 2–3 stosuje się odpowiednio.\n5. Dodatek, o którym mowa w ust. 4, nie jest uwzględniany przy obliczaniu\nwysokości wynagrodzenia pracownika zgodnie z art. 6 ust. 4 ustawy z dnia\n10 października 2002 r. o minimalnym wynagrodzeniu za pracę (Dz. U.\nz 2024 r. poz. 1773).\n6. Pracodawca zapewnia asystentowi rodziny samochód służący do realizacji\nprzez niego zadań służbowych.\n7. W przypadku braku możliwości zapewnienia asystentowi rodziny\nsamochodu służącego do realizacji przez niego zadań służbowych, kierownik\njednostki organizacyjnej lub podmiotu, o których mowa w art. 17 ust. 1, zwraca\nasystentowi rodziny wykorzystującemu do realizacji zadań służbowych pojazd\nprywatny, wydatki poniesione w zawiązku z użytkowaniem tego pojazdu na\nzasadach ustalania oraz wysokości należności przysługujących pracownikowi z\ntytułu podróży służbowej na obszarze kraju oraz zgodnie z warunkami ustalania oraz\nsposobu dokonywania zwrotu kosztów używania do celów służbowych pojazdów\nniebędących własnością pracodawcy.\n8. W przypadku braku możliwości zapewnienia asystentowi rodziny\nsamochodu służącego do realizacji przez niego zadań służbowych oraz w przypadku\ngdy asystent rodziny nie wykorzystuje pojazdu prywatnego do realizacji zadań\nsłużbowych, kierownik jednostki organizacyjnej lub podmiotu, o których mowa w\nart. 17 ust. 1, zapewnia asystentowi rodziny pokrycie kosztów przejazdów\nzwiązanych z realizacją przez tego asystenta rodziny zadań służbowych.\n9. Asystentowi rodziny, do którego obowiązków należy praca z rodziną w\nśrodowisku lokalnym rodziny, w tym miejscu jej zamieszkania, jeżeli przepracował\nco najmniej 3 lata, przysługuje raz na 2 lata dodatkowy urlop wypoczynkowy w\nwymiarze 10 dni.\n10. Asystentowi rodziny przysługuje pomoc psychologiczna w przypadku\nwystąpienia sytuacji bezpośrednio zagrażających jego życiu lub zdrowiu w związku\nz wykonywanymi zadaniami służbowymi.\f– 17 –\n11. Pomoc, o której mowa w ust. 10, zapewnia asystentowi rodziny\npracodawca.\n12. Asystentowi rodziny przysługuje zwrot kosztów szkoleń\nnieobowiązkowych z zakresu pracy z rodziną, realizowanych za zgodą pracodawcy,\nw kwocie nie mniejszej niż 50% kosztów szkolenia.\n13. Asystentowi rodziny, w związku z wykonywanymi zadaniami służbowymi\ni w zakresie tych zadań, przysługuje prawo pierwszeństwa w urzędach, instytucjach,\npodmiotach wykonujących działalność leczniczą i innych placówkach edukacyjnych\ni usługowych.\n14. Organy i instytucje administracji publicznej, podmioty wykonujące\ndziałalność leczniczą i organizacje pozarządowe są obowiązane do udzielania\nasystentowi rodziny pomocy w wykonywaniu jego zadań.”;\n17) w art. 17:\na) ust. 1 otrzymuje brzmienie:\n„1. Asystenta rodziny zatrudnia:\n1) kierownik jednostki organizacyjnej gminy, która organizuje pracę z rodziną lub\nkierownik podmiotu, któremu gmina zleciła organizację pracy z rodziną na\npodstawie art. 190 – w odniesieniu do asystenta rodziny przydzielanego\nrodzinie dziecka lub przydzielanego rodzinie zastępczej spokrewnionej,\n2) kierownik jednostki organizacyjnej powiatu organizującej pieczę zastępczą lub\nkierownik podmiotu, któremu powiat zlecił organizację rodzinnej pieczy\nzastępczej na podstawie art. 190 – w odniesieniu do asystenta rodziny\nprzydzielanego rodzinie dziecka umieszczonego w pieczy zastępczej.”,\nb) po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Zatrudnienie asystenta rodziny jest obligatoryjne w każdej gminie.”,\nc) ust. 2 otrzymuje brzmienie:\n„2. Praca asystenta rodziny jest wykonywana w ramach stosunku pracy w\nsystemie zadaniowego czasu pracy.”,\nd) ust 4 otrzymuje brzmienie:\n„4. Asystent rodziny nie może:\n1) prowadzić postępowań z zakresu świadczeń realizowanych przez gminę\nlub powiat;\f– 18 –\n2) być wyznaczany do bezpośredniego udziału w czynności związanej\nz przymusowym odebraniem osoby podlegającej władzy\nrodzicielskiej lub pozostającej pod opieką, o którym mowa w art. 5986\nustawy z dnia 17 listopada 1964 r. - Kodeks postępowania\ncywilnego.”;\n18) po art. 17 dodaje się art. 17a i 17b w brzmieniu:\n„Art. 17a. 1. Ustala się następujące stopnie awansu zawodowego dla asystentów\nrodziny:\n1) młodszy asystent rodziny;\n2) asystent rodziny;\n3) starszy asystent rodziny;\n4) specjalista asystent rodziny;\n5) starszy specjalista asystent rodziny;\n6) główny specjalista asystent rodziny.\n2. Wyższy stopień awansu zawodowego można nadać zgodnie z trybem określonym\nw ust. 13 albo 14, po spełnieniu warunku minimalnego stażu pracy w zawodzie asystenta\nrodziny, które ustala się dla:\n1) asystenta rodziny - jako posiadanie rocznego stażu pracy;\n2) starszego asystenta rodziny - jako posiadanie 2-letniego stażu pracy;\n3) specjalisty asystenta rodziny - jako posiadanie 3-letniego stażu pracy;\n4) starszego specjalisty asystenta rodziny - jako posiadanie 4-letniego stażu pracy;\n5) głównego specjalisty asystenta rodziny - jako posiadanie 6-letniego stażu pracy.\n3. Okres zatrudnienia na podstawie umowy o świadczenie usług, w charakterze\nasystenta rodziny, na podstawie ustawy z dnia 23 kwietnia 1964 r. - Kodeks cywilny,\nwlicza się do wymogów okresu zatrudnienia dotyczących stopni awansu zawodowego w\nzakresie zatrudniania asystentów rodziny.\n4. Praca asystenta rodziny podlega, raz na 2 lata, ocenie okresowej dokonywanej\nprzez bezpośredniego przełożonego, w zakresie wywiązywania się przez niego z\nobowiązków wynikających z czynności i zadań na zajmowanym stanowisku, w\nszczególności podejmowanych inicjatyw, innowacyjności, kreatywności, współpracy z\ninnymi podmiotami oraz skuteczności przeciwdziałania konieczności umieszczenia\ndziecka w pieczy zastępczej lub działań umożliwiających powrót dziecka do rodziny.\n5. Ocena okresowa jest sporządzana na piśmie i zawiera uzasadnienie.\f– 19 –\n6. Ocena okresowa może być pozytywna powyżej oczekiwań, pozytywna albo\nnegatywna.\n7. Asystent rodziny może wnieść na piśmie zastrzeżenia co do uzyskanej oceny\nokresowej, w terminie 14 dni od dnia otrzymania tej oceny, odpowiednio do kierownika\njednostki organizacyjnej, w której jest zatrudniony.\n8. W przypadku gdy bezpośrednim przełożonym asystenta rodziny jest kierownik\njednostki organizacyjnej, zastrzeżenia wnosi się do organu nadzorującego jednostkę , w\nktórej asystent rodziny jest zatrudniony.\n9. Kierownik jednostki albo organ, do którego asystent rodziny wniósł zastrzeżenia,\nanalizuje ich treść, a następnie informuje na piśmie asystenta rodziny o podtrzymaniu albo\nzakwestionowaniu oceny okresowej wraz z uzasadnieniem, w terminie 14 dni od dnia\notrzymania zastrzeżeń.\n10. W przypadku, o którym mowa w ust. 9, informacja o podtrzymaniu albo\nzakwestionowaniu oceny okresowej jest przekazywana także bezpośredniemu\nprzełożonemu asystenta rodziny.\n11. W przypadku podtrzymania przez kierownika jednostki albo przez organ, do\nktórego asystent rodziny wniósł zastrzeżenia, negatywnej oceny okresowej, nie podlega\nona zaskarżeniu.\n12. W przypadku zakwestionowania oceny okresowej przez kierownika jednostki\nalbo przez organ, do którego asystent rodziny wniósł zastrzeżenia, ocena okresowa pracy\ntego asystenta jest dokonywana ponownie.\n13 W sprawach naruszenia zasady równego traktowania w zatrudnieniu podczas\noceny okresowej stosuje się przepisy art. 183d ustawy z dnia 26 czerwca 1974 r. – Kodeks\npracy (Dz. U. z 2025 r. poz. 277, 807, 1423 i 1661 oraz z 2026 r. poz. 25).\n14. Asystentowi rodziny, który otrzymał dwie następujące po sobie oceny okresowe\npozytywne powyżej oczekiwań, spełniającemu warunki dotyczące stażu pracy, o których\nmowa w ust. 2 i 3, jest nadawany wyższy stopień awansu zawodowego.\n15. Asystentowi, który posiada odpowiedni staż pracy, o którym mowa w ust. 2 i 3,\noraz wyróżnia się wysokim zaangażowaniem, inicjatywą lub nowatorskim podejściem\nprzy wykonywaniu obowiązków służbowych z zakresu pracy z rodziną, może być nadany\nwyższy stopień awansu z pominięciem wymogu, o którym mowa w ust. 14.\n16. W przypadku awansu na wyższy stopień zawodowy asystentowi rodziny\nprzysługuje podwyższenie wynagrodzenia zasadniczego.\f– 20 –\n17. Szczegółowe kryteria i sposób dokonania oceny okresowej w zakresie, o którym\nmowa w ust. 4, ustala pracodawca, po konsultacji z zakładową organizacją związkową\nlub z reprezentacją pracowników. Art. 17b. 1. Dokumentem identyfikującym asystenta\nrodziny oraz potwierdzającym jego zatrudnienie oraz uprawnienia wynikające z\nprzepisów niniejszej ustawy jest legitymacja służbowa.\n2. Legitymację służbową wydaje odpowiednio wójt albo starosta właściwi\nmiejscowo dla jednostki, placówki albo podmiotu, o których mowa w art. 17 ust. 1.\n3. Wójt może upoważnić, w formie pisemnej, pracownika urzędu lub innej jednostki\norganizacyjnej gminy do wydawania legitymacji służbowych, o których mowa w ust. 2.\n4. Starosta może upoważnić, w formie pisemnej, pracownika urzędu lub innej\njednostki organizacyjnej powiatu do wydawania legitymacji służbowych.\n5. Asystent rodziny przed rozpoczęciem wykonywania czynności służbowych\nokazuje legitymację służbową.\n6. Legitymacja służbowa zawiera:\n1)imię (imiona) i nazwisko asystenta rodziny;\n2) wizerunek twarzy asystenta rodziny;\n3) numer legitymacji;\n4)datę wydania legitymacji;\n5) dane organu wydającego legitymację.\n7. Legitymację służbową wydaje się na czas zatrudnienia jako asystent rodziny, nie\ndłużej jednak niż na 3 lata.\n8. Unieważnia się niezwłocznie legitymację służbową  w przypadku:\n1)rozwiązania stosunku pracy z asystentem rodziny;\n2)błędu w numerze legitymacji;\n3) zmiany imienia lub nazwiska  asystenta rodziny.\n9. W przypadku gdy legitymacja służbowa zostanie zgubiona, skradziona lub w inny\nsposób utracona, na wniosek asystenta rodziny, który utracił dokument, odpowiednio\nwójt, albo starosta wydaje duplikat legitymacji.\n10. W przypadkach, o których mowa w ust. 8, dotychczas posiadana legitymacja\nsłużbowa podlega zwrotowi odpowiednio do wójta albo starosty, który wydał legitymację,\na następnie podlega unieważnieniu odpowiednio przez tego wójta albo starostę.\n11. W przypadku unieważnienia legitymacji asystenta rodziny z przyczyn\nokreślonych w ust. 8 asystentowi rodziny wydaje się nową legitymację służbową. \f– 21 –\n12. Minister właściwy do spraw rodziny określi, w drodze rozporządzenia, wzór\nlegitymacji służbowej asystenta rodziny i koordynatora rodzinnej pieczy zastępczej oraz\nsposób unieważnienia tych legitymacji, uwzględniając potrzebę identyfikacji osoby\nzatrudnionej na stanowisku asystenta rodziny albo koordynatora rodzinnej pieczy\nzastępczej, a także zapewnienia bezpieczeństwa przed fałszerstwami.”;\n19) art. 18 otrzymuje brzmienie:\n„Art. 18. 1. Placówka wsparcia dziennego obejmuje dziecko opieką i wychowaniem.\n2. Placówkę wsparcia dziennego prowadzi gmina lub podmiot, któremu gmina\nzleciła realizację tego zadania na podstawie art. 190.\n3. Placówkę wsparcia dziennego może prowadzić podmiot, który uzyskał\nzezwolenie wójta.\n4. Powiat może prowadzić lub zlecić, na podstawie art. 190, prowadzenie placówki\nwsparcia dziennego o zasięgu ponadgminnym. Placówka wsparcia dziennego o zasięgu\nponadgminnym może być prowadzona także przez podmiot, który uzyskał zezwolenie\nstarosty”;\n20) w art. 23 ust. 1 otrzymuje brzmienie:\n„1. Placówka wsparcia dziennego współpracuje, w szczególności odpowiednio z\nrodzicami, opiekunami prawnymi dziecka, asystentem rodziny, rodziną zastępczą lub\nprowadzącym rodzinny dom dziecka, a także organizacjami pozarządowymi lub\npodmiotami, o których mowa w art. 3 ust. 3 ustawy z dnia 24 kwietnia 2003 r. o\ndziałalności pożytku publicznego i wolontariacie, oraz innymi podmiotami lub osobami\ndziałającymi na rzecz dziecka i rodziny.”;\n21) w art. 25:\na) w ust. 2 uchyla się pkt 4 i 5,\nb) ust. 3 otrzymuje brzmienie:\n„3. W przypadku wszczęcia przeciwko kierownikowi placówki wsparcia\ndziennego postępowania karnego o umyślne przestępstwo ścigane z oskarżenia\npublicznego albo umyślne przestępstwo skarbowe albo wszczęcia postępowania\nkarnego o orzeczenie wobec niego zakazu, o którym mowa w art. 7b ust. 1 pkt 3,\nprzepisy art. 13 stosuje się odpowiednio.”;\f– 22 –\n22) w art. 26:\na) w ust. 1 w pkt 1 w lit. a tire pierwsze otrzymuje brzmienie:\n„– na kierunku pedagogika, pedagogika specjalna, psychologia,\npsychoprofilaktyka, socjologia, praca socjalna, nauki o rodzinie lub na innym\nkierunku, którego program obejmuje resocjalizację, pracę socjalną, pedagogikę\nopiekuńczo-wychowawczą lub”,\nb) w ust. 2 uchyla się pkt 3 i 4,\nc) ust. 3 otrzymuje brzmienie:\n„3. W przypadku wszczęcia przeciwko osobie, o której mowa w ust. 1,\npostępowania karnego o umyślne przestępstwo ścigane z oskarżenia publicznego\nalbo umyślne przestępstwo skarbowe albo wszczęcia postępowania karnego o\norzeczenie wobec niej zakazu, o którym mowa w art. 7b ust. 1 pkt 3, przepisy art. 13\nstosuje się odpowiednio.”;\n23)w art. 27 :\na) uchyla się ust. 1,\nb) ust. 2 otrzymuje brzmienie:\n„2. W przypadku wszczęcia przeciwko osobie zatrudnionej w placówce\nwsparcia dziennego, niebędącej kierownikiem lub osobą, o której mowa w art. 26\nust. 1,  postępowania karnego o umyślne przestępstwo ścigane z oskarżenia\npublicznego albo umyślne przestępstwo skarbowe albo wszczęcia postępowania\nkarnego o orzeczenie wobec niej zakazu, o którym mowa w art. 7b ust. 1 pkt 3,\nprzepisy art. 13 stosuje się odpowiednio.”;\n24) w art. 28a:\na) w ust. 1 zdanie drugie otrzymuje brzmienie:\n„W przypadku placówek, o których mowa w art. 18 ust. 3, oraz asystentów\nrodziny przydzielonych na zasadach, o których mowa w art. 11a ust. 1, kontrolę\nsprawuje zarząd powiatu.\",\nb) w ust. 2 zdanie pierwsze otrzymuje brzmienie:\n„2. Do sprawowania kontroli, o której mowa w ust. 1, wójt może upoważnić w\nformie pisemnej, pracownika urzędu lub innej jednostki organizacyjnej gminy.”,\nc) w ust. 3 zdanie pierwsze otrzymuje brzmienie:\f– 23 –\n„3. Do sprawowania kontroli, o której mowa w ust. 1, zarząd powiatu może\nupoważnić, w formie pisemnej, członka zarządu powiatu, pracownika urzędu lub\ninnej jednostki organizacyjnej powiatu.”;\n25) w art. 30:\na) uchyla się ust. 1,\nb) ust. 2 otrzymuje brzmienie:\n„2. Rodzinę wspierającą organizuje gmina właściwa ze względu na miejsce\nzamieszkania rodziny wspierającej lub podmiot, któremu gmina zleciła realizację\ntego zadania na podstawie art. 190.\"\nc) po ust. 2 dodaje się ust. 3-5 w brzmieniu:\n3. Rodzinę wspierającą ustanawia i zawiera z nią umowę kierownik jednostki\norganizacyjnej gminy lub kierownik podmiotu, o których mowa w ust. 1a, po\nprzeprowadzeniu rodzinnego wywiadu środowiskowego, o którym mowa w ustawie\nz dnia 12 marca 2004 r. o pomocy społecznej.\n4. Umowa, o której mowa w ust. 3, określa w szczególności:\n1) zakres działań rodziny wspierającej wykonywanych na rzecz rodziny\nwspieranej;\n2) zasady zwrotu kosztów związanych z udzielaniem pomocy, o której mowa\nw art. 29 ust. 2;\n3) czas, na jaki umowa została zawarta;\n4) warunki i sposób zmiany oraz rozwiązania umowy.\n5. W umowie, o której mowa w ust. 3, mogą zostać określone kwestie dotyczące\nwynagrodzenia dla rodziny wspierającej.”;\n26) w art. 31:\na) uchyla się ust. 1,\nb) ust. 2 otrzymuje brzmienie:\n„2. Kierownik jednostki organizacyjnej gminy, która organizuje rodzinę\nwspierającą, może upoważnić pracownika tej jednostki do ustanawiania rodziny\nwspierającej, zawierania i ustalania treści umowy z nią zawieranej oraz jej\nrozwiązywania.”;\n27) po art. 31 dodaje się art. 31a-31e w brzmieniu:\n„Art. 31a. 1. Osoba, która przebywała w rodzinie zastępczej niezawodowej lub\nzawodowej albo rodzinnym domu dziecka i ukończyła 25 rok życia oraz:\f– 24 –\n1) legitymuje się orzeczeniem o znacznym stopniu niepełnosprawności oraz\n2) jest niezdolna do samodzielnej egzystencji oraz\n3) proces usamodzielnienia, o którym mowa w art. 139c, nie doprowadził do\nmożliwości zamieszkania przez nią poza dotychczasową rodziną zastępczą lub\nrodzinnym domem dziecka\n–może przebywać w rodzinie opiekuńczej.\n2. Rodzinę opiekuńczą organizuje gmina lub podmiot, któremu gmina zleciła\nrealizację tego zadania na podstawie art. 190.\n3. Rodzinę opiekuńczą tworzą osoby pełniące uprzednio wobec osoby, o której\nmowa w ust. 1, funkcję rodziny zastępczej niezawodowej, zawodowej lub rodzinnego\ndom dziecka.\n4. Rodzina opiekuńcza zapewnia zaspokojenie potrzeb osób, o których mowa w ust.\n1, ze szczególnym uwzględnieniem ich potrzeb emocjonalnych, bytowych, zdrowotnych,\nedukacyjnych i kulturalno-rekreacyjnych oraz podejmuje działania na rzecz zwiększenia\npoziomu niezależności tych osób, w tym aktywnego uczestnictwa w życiu społecznym i\nzawodowym.\n5. Do osób pełniących funkcję rodziny opiekuńczej stosuje się odpowiednio przepisy\nart. 42 ust. 1 pkt 1-5 i 7-8, art. 50 oraz 66.\nArt. 31b. 1. Osoba, o której mowa w art. 31a ust. 1, albo występujący w jej imieniu\nprzedstawiciel ustawowy, zawiera trójstronną umowę o pełnienie funkcji rodziny\nopiekuńczej z osobą pełniącą wobec niej uprzednio funkcję rodziny zastępczej\nniezawodowej, rodziny zastępczej zawodowej lub rodzinnego dom dziecka, oraz z\nwójtem gminy, o której mowa w art. 59 ust. 1 ustawy z dnia 12 marca 2004 r. o pomocy\nspołecznej, lub podmiotem, któremu gmina zleciła organizowanie rodzin opiekuńczych\nna podstawie art. 190. O zawarciu, zmianie lub rozwiązaniu umowy gmina lub podmiot,\nktóremu gmina zleciła organizowanie rodzin opiekuńczych informuje właściwy powiat.\n2. Umowę, o której mowa w ust. 1, zawiera się na wniosek  osoby, o której mowa w\nart. 31a ust. 1, jej przedstawiciela ustawowego lub sądu, za zgodą osób pełniących funkcję\nrodziny zastępczej niezawodowej, rodziny zastępczej zawodowej lub prowadzącego\nrodzinny dom dziecka, w którym ta osoba przebywa.\n3. Umowa, o której mowa w ust. 2, określa w szczególności:\n1) strony umowy;\n2) cel i przedmiot umowy;\f– 25 –\n3) miejsce sprawowania opieki;\n4)wysokość wynagrodzenia;\n5) zasady finansowania wynagrodzenia, w tym w zakresie partycypacji i\nrozliczeń, o których mowa w art. 31c ust. 3–8;\n6) zasady partycypacji przez osobę, o której mowa w art. 31a ust. 1, w kosztach\nzwiązanych z prowadzeniem wspólnego gospodarstwa domowego;\n7)liczbę osób, o których mowa w art. 31a ust. 1, powierzonych opiece rodziny\nopiekuńczej;\n8) zakres niezbędnej pomocy w razie choroby osób tworzących rodzinę\nopiekuńczą lub wyzwań związanych z opieką nad osobami powierzonymi\nopiece rodziny opiekuńczej;\n9) uprawnienia i obowiązki w zakresie bieżącej kontroli;\n10) czas, na jaki umowa została zawarta;\n11) warunki i sposób zmiany umowy lub jej rozwiązania.\n4. Wójt może upoważnić pracownika urzędu lub innej jednostki organizacyjnej\ngminy do zawierania i rozwiązywania umowy, o której mowa w ust. 1.\n5. W zakresie nieuregulowanym ustawą do umowy, o której mowa w ust. 1, mają\nzastosowanie przepisy ustawy z dnia 23 kwietnia 1964 r. – Kodeks cywilny, dotyczące\numowy zlecenia.\nArt. 31c. 1. Rodzinie opiekuńczej przysługuje miesięczne wynagrodzenie w kwocie\nnie niższej niż 6160 zł. Przepisy art. 86 ust. 2–3 stosuje się odpowiednio.\n2. Ustalając wysokość wynagrodzenia, o którym mowa w ust. 1, bierze się pod\nuwagę w szczególności kwalifikacje, szkolenia i ocenę rodziny opiekuńczej oraz liczbę,\nstan zdrowia, rozwoju oraz niepełnosprawność osób przebywających pod jej opieką\n3. W przypadku łączenia funkcji rodziny opiekuńczej z pełnieniem funkcji rodziny\nzastępczej zawodowej lub prowadzeniem rodzinnego domu dziecka, w tym przez\nmałżonka osoby pełniącej funkcję rodziny opiekuńczej, rodzinie opiekuńczej przysługuje\nmiesięczne wynagrodzenie w wysokości nie niższej niż 50% kwoty, o której mowa w ust.\n1.\n4. Wynagrodzenie rodziny opiekuńczej finansowane jest:\n1) w wysokości nie niższej niż 35% – przez gminę,\f– 26 –\n2) w wysokości nie wyższej niż 65% kwoty minimalnego wynagrodzenia\nprzysługującego rodzinie opiekuńczej - przez osobę, o której mowa w art. 31a\nust. 2.\n5. Obowiązani do współfinansowania w części, o której mowa w ust. 4 pkt 2, w\nkolejności:\n1) osoba, o której mowa w art. 31a ust. 1,\n2) wstępni,\n3) gmina\n- przy czym osoby i gmina określone w pkt 2 i 3 nie mają obowiązku wnoszenia\nopłat, jeżeli osoba, o której mowa w art. 31a ust. 1, wnosi pełną odpłatność.\n6.  Współfinansowania w części o której mowa w ust. 4 pkt 2, mogą wnosić osoby\nniewymienione w ust. 5.\n7. Wysokość finansowania, o której mowa w ust. 4 pkt 2, nie może wynosić więcej\nniż 70% dochodu osoby, o której mowa w art. 31a ust. 1.\n8. Ustalając dochód osoby, o której mowa w art. 31a ust. 1, uwzględnia się dochody,\no których mowa w art. 8 ust. 3–13 ustawy z dnia 12 marca 2004 r. o pomocy społecznej,\nuzyskane w miesiącu poprzedzającym ustalenie wysokości finansowania, o którym mowa\nw ust. 4 pkt 2.\n9. W przypadku przebywania dwóch lub więcej osób, o których mowa w art. 31a\nust. 1, pod opieką rodziny opiekuńczej wysokość finansowania, o którym mowa w ust. 4\npkt 2, ponoszona jest proporcjonalnie przez te osoby.\n10. Wynagrodzenie dla rodziny opiekuńczej wypłacane jest miesięcznie przez\nodpowiednio gminę, która zawarła z rodziną opiekuńczą umowę, o której mowa w art.\n31b ust. 1, lub podmiot, któremu gmina zleciła organizowanie rodzin opiekuńczych na\npodstawie art. 190 i zawarł z rodziną opiekuńczą umowę, o której mowa w art. 31b ust.\n1.\n11. Część wynagrodzenia współfinansowanego przez osobę, o której mowa w art.\n31a ust. 1, w wysokości, o której mowa w ust. 4 pkt 2, wpłacana jest przez nią, na zasadach\nokreślonych w umowie, o której mowa w 31b ust. 1, na rachunek bankowy gminy, która\nzawarła z rodziną opiekuńczą umowę, o której mowa w art. 31b ust. 1,  lub podmiotu,\nktóremu gmina zleciła organizowanie rodzin opiekuńczych na podstawie art. 190 i zawarł\nz rodziną opiekuńczą umowę, o której mowa w art. 31b ust. 1.\f– 27 –\n12. Niezapłacone przez osobę, o której mowa w art. 31a ust. 1, należności z tytułu\nwspółfinansowania, o którym mowa w ust. 4 pkt 2, podlegają  egzekucji w trybie\nprzepisów o postępowaniu egzekucyjnym w administracji albo postępowaniu\negzekucyjnemu w sprawach cywilnych.\n13.  W przypadku gdy dochód osoby, o której mowa w art. 31a ust. 1, nie pozwala\nna pokrycie finansowania w części, o której mowa w ust. 4 pkt 2, brakującą kwotę\nwynagrodzenia rodziny opiekuńczej finansują wstępni, inne osoby lub gmina. Sposób,\nwysokość i tryb ustalania współfinansowania, o którym mowa w ust. 4 pkt 2, ustala gmina\nw drodze umowy z zstępnymi lub innymi osobami, biorąc pod uwagę wysokość\ndochodów i możliwości. Do zawarcia umowy i wysokości wnoszonych części\nwspółfinansowania stosuje się odpowiednio przepisu art. 61 ust. 2, 2b, 2d-3, art. 64 i 66\nustawy z dnia 12 marca 2004 r. o pomocy społecznej.\n14. Osoba, o której mowa w art. 31a ust. 1, lub jej przedstawiciel ustawowy, jest\nobowiązana niezwłocznie poinformować gminę, która organizuje rodzinę opiekuńczą, a\nw przypadku podpisania umowy, o której mowa w art. 31b ust. 1, przez podmiot, któremu\ngmina zleciła organizowanie rodziny opiekuńczej, także ten podmiot, o każdej zmianie w\njej sytuacji osobistej, dochodowej i majątkowej, która wiąże się z podstawą do ustalenia\nwysokości finansowania ponoszonej przez tę osobę.\n15. Gmina, która organizuje rodzinę opiekuńczą lub zleca organizowanie rodziny\nopiekuńczej, weryfikuje, co 3 lata, ustalone kwoty finansowania, o którym mowa w ust.\n4, dokonując ustalenia dochodu osoby, o której mowa w art. 31a ust. 1.\n16. W przypadku stwierdzenia przez gminę pokrywająca część wynagrodzenia\nrodziny opiekuńczej, zmiany dochodu osoby, o której mowa w art. 31a ust. 1, wpływającą\nna ustalone kwoty finansowania tego wynagrodzenia dokonuje się zmiany ustalenia\nwysokości finansowania.\nArt. 31d. 1. Rodzina opiekuńcza jest obowiązana do przedstawiania, co 2 lata,\nodpowiednio kierownikowi ośrodka pomocy społecznej, kierownikowi centrum usług\nspołecznych albo kierownikowi podmiotu, któremu gmina zleciła organizowanie rodziny\nopiekuńczej na podstawie art. 190, zaświadczenia lekarskiego o stanie zdrowia,\nwystawione przez lekarza podstawowej opieki zdrowotnej w rozumieniu art. 6 ustawy z\ndnia 27 października 2017 r. o podstawowej opiece zdrowotnej (Dz. U. z 2025 r. poz.\n515), oraz opinii o posiadaniu predyspozycji i motywacji do pełnienia funkcji rodziny\nopiekuńczej, wystawionej przez psychologa.\f– 28 –\n2. Ośrodek pomocy społecznej albo centrum usług społecznych gminy, która\nzawarła umowę trójstronną, o której mowa w art. 31b ust. 1, albo podmiot, któremu gmina\nzleciła organizowanie rodziny opiekuńczej na podstawie art. 190, ocenia:\n1)sytuację osoby, o której mowa w art. 31a ust. 1;\n2)rodzinę opiekuńczą.\n3. Oceny sytuacji osoby, o której mowa w art. 31a ust. 1, dokonuje się przede\nwszystkim w celu:\n1) ustalenia stanu psychofizycznego tej osoby;\n2) wskazania najbardziej efektywnych metod do pracy z tą osobą;\n3) oceny możliwości usamodzielnienia tej osoby albo zasadności dalszego jej\npobytu w rodzinie opiekuńczej.\n4. Oceny sytuacji osoby, o której mowa w art. 31a ust. 1, dokonuje się na posiedzeniu\nz udziałem w szczególności, odpowiednio:\n1) tej osoby lub jej przedstawiciela prawnego;\n2) asystenta tej osoby niepełnosprawnej;\n3) rodziny opiekuńczej;\n4) psychologa.\n5. Ocena sytuacji osoby, o której mowa w art. 31a ust. 1, jest przeprowadzana\nw miarę potrzeb, jednak nie rzadziej niż co 12 miesięcy od poprzedniej oceny.\n6. Ocena rodziny opiekuńczej jest dokonywana pod względem predyspozycji do\npełnienia powierzonej jej funkcji oraz jakości wykonywanej pracy.\n7. Pierwszej oceny rodziny opiekuńczej dokonuje się nie później niż przed upływem\nroku od podpisania umowy, o której mowa w art. 31b ust.1.\n8. Kolejne oceny są dokonywane nie rzadziej niż co 3 lata.\n9. Do ocen, o których mowa w ust. 7 i 8, rodzina opiekuńcza może złożyć, w terminie\n14 dni od dnia jej otrzymania, zastrzeżenia do wójta.\n10. Wójt rozpatruje zastrzeżenia w terminie 30 dni od dnia ich otrzymania.\n11. W przypadku, gdy wójt nie rozpatrzy zastrzeżeń w terminie, o którym mowa w\nust. 10, uznaje się, że zastrzeżenia te zostały uwzględnione przez wójta.\n12. W przypadku uwzględnienia zastrzeżeń przez wójta, ocenę rodziny opiekuńczej\nsporządza się ponownie. Do oceny sporządzonej po raz drugi rodzina opiekuńcza może\nzłożyć zastrzeżenia w trybie określonym w ust. 9–11.\f– 29 –\n13. W przypadku nieuwzględnienia przez wójta zastrzeżenia złożonego do\nponownej oceny uznaje się, że  ocena rodziny opiekuńczej jest negatywna. W takim\nprzypadku kolejna ocena jest dokonywana nie później niż w terminie 6 miesięcy od dnia\ndokonania poprzedniej oceny. Kolejna negatywna ocena stanowi podstawę do\nrozwiązania z tą rodziną umowy o pełnienie funkcji rodziny opiekuńczej przez wójta lub\npodmiot, któremu gmina zleciła organizowanie rodziny opiekuńczej na podstawie art.\n190. Przepis art. 31e ust. 3 stosuje się odpowiednio.\nArt. 31e. 1. Kontrolę nad rodzinami opiekuńczymi sprawuje wójt, gminy, która\norganizuje rodzinę opiekuńczą lub zleca organizowanie rodziny opiekuńczej na podstawie\nart. 190, z zachowaniem zasad określonych w art. 28a.\n2. W przypadku gdy rodzina opiekuńcza nie wypełnia swoich funkcji lub wypełnia\nje niewłaściwie naruszając dobra osobiste osoby, o której mowa w art. 31a ust. 1, wójt lub\npodmiot, który zawarł umowę z rodziną opiekuńczą może rozwiązać z tą rodziną umowę\no pełnienie funkcji rodziny opiekuńczej bez zachowania terminu wypowiedzenia.\n3. W przypadku rozwiązania umowy o pełnienie funkcji rodziny opiekuńczej,\ngmina, która organizuje rodzinę opiekuńczą lub zleca organizowanie rodziny opiekuńczej\nna podstawie art. 190, zapewnia osobie, o której mowa w art. 31a ust. 1, właściwą\nopiekę.”;\n28) w art. 32 po ust. 2 dodaje się ust. 3 w brzmieniu:\n„3. Powiat przy organizacji pieczy zastępczej może być wspierany przez organizacje\npozarządowe lub podmioty, o których mowa w art. 3 ust. 3 ustawy z dnia 24 kwietnia\n2003 r. o działalności pożytku publicznego i wolontariacie, w szczególności przez\npozarządowego organizatora rodzinnej pieczy zastępczej.”;\n29) po art. 33 dodaje się art. 33a w brzmieniu:\n„Art. 33a. W sytuacji rozdzielenia rodzeństwa umieszczonego w pieczy zastępczej\nstarosta, pozarządowy organizator rodzinnej pieczy zastępczej lub marszałek\nwojewództwa, są zobowiązani do:\n1) zapewnienia dzieciom możliwości utrzymania lub nawiązania więzi oraz\n2) podejmowania działań zmierzających do umieszczenia rodzeństwa razem w\npieczy zastępczej, biorąc pod uwagę ich potrzeby\n– chyba że byłoby to sprzeczne z ich dobrem.”;\f– 30 –\n30) w art. 35:\na) po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Starosta informuje gminę miejsca zamieszkania rodziców dziecka o\numieszczeniu dziecka w pieczy zastępczej, w celu podjęcia przez gminę pracy z\nrodziną dziecka.”,\nb) ust. 2 otrzymuje brzmienie:\n„2. W przypadku pilnej konieczności, na wniosek lub za zgodą rodziców\ndziecka, możliwe jest umieszczenie dziecka w rodzinnej pieczy zastępczej na\npodstawie umowy zawartej między rodziną zastępczą albo prowadzącym rodzinny\ndom dziecka, a starostą powiatu właściwego, o którym mowa w art. 35b ust. 1-3,\nchyba, że porozumienie, o którym mowa w art. 35b ust. 4, stanowi inaczej. O\nzawartej umowie starosta niezwłocznie zawiadamia sąd.”,\nc) ust. 3 otrzymuje brzmienie:\n„3. Umowa, o której mowa w ust. 2, określa czas na jaki została zawarta.\nDo umowy stosuje się odpowiednio przepisy art. 35b ust. 4, art. 54 ust. 7b oraz art.\n55a ust. 2 pkt 1-4 i 10, ust. 7, 9, 10 i 12.”.\n31) w art. 35a ust. 2-4 otrzymują brzmienie:\n„2. Jeżeli sąd lub inny organ państwa obcego wskazał kandydatów do pełnienia\nfunkcji rodziny zastępczej albo prowadzenia rodzinnego domu dziecka albo określoną\nplacówkę opiekuńczo-wychowawczą albo regionalną placówkę opiekuńczo--\nterapeutyczną, w których dziecko ma być umieszczone, sąd opiekuńczy może wydać\nzgodę na umieszczenie dziecka w pieczy zastępczej po uzyskaniu opinii odpowiednio\nstarosty powiatu, o którym mowa w art. 35b ust. 1-3 i 5, pozarządowego organizatora\nrodzinnej pieczy zastępczej albo marszałka.\n3. W przypadku gdy sąd lub inny organ państwa obcego nie wskazał kandydatów do\npełnienia funkcji rodziny zastępczej albo prowadzenia rodzinnego domu dziecka albo\nokreślonej placówki opiekuńczo-wychowawczej, albo regionalnej placówki opiekuńczo-\nterapeutycznej, sąd opiekuńczy może wydać zgodę na umieszczenie dziecka w pieczy\nzastępczej po uzyskaniu opinii starosty powiatu, o którym mowa w art. 35b ust. 1-3 i 5,\npozarządowego organizatora rodzinnej pieczy zastępczej albo marszałka.\n4. W przypadku, o którym mowa w ust. 3, starosta powiatu, o którym mowa w art.\n35b ust. 1-3 i 5, pozarządowy organizator rodzinnej pieczy zastępczej albo marszałek\nwskazuje odpowiednio kandydatów do pełnienia funkcji rodziny zastępczej albo \f– 31 –\nprowadzenia rodzinnego domu dziecka, placówkę opiekuńczo-wychowawczą albo\nregionalną placówkę opiekuńczo-terapeutyczną.”;\n32) po art. 35a dodaje się art. 35b w brzmieniu:\n„Art. 35b. 1. Powiatem właściwym w zakresie zapewnienia funkcjonowania rodziny\npomocowej, rodziny zastępczej lub prowadzenia rodzinnego domu dziecka, oraz\nzapewnienia funkcjonowania organizatora rodzinnej pieczy zastępczej, a także kontroli,\nfinansowania, w tym przyznawania świadczeń, dodatków lub wypłaty wynagrodzeń\nprzysługujących odpowiednio rodzinie pomocowej, rodzinie zastępczej lub\nprowadzącemu rodzinny dom dziecka, dla:\n1) rodziny zastępczej spokrewnionej jest powiat właściwy ze względu na miejsce\nzamieszkania rodziny zastępczej spokrewnionej;\n2) rodziny zastępczej niezawodowej jest powiat właściwy dla organizatora\nrodzinnej pieczy zastępczej, który wydał zaświadczenie kwalifikacyjne;\n3) rodziny zastępczej zawodowej jest powiat, który organizuje rodzinę zastępczą\nzawodową lub zleca organizację rodziny zastępczej zawodowej;\n4)  prowadzącego rodzinny dom dziecka jest powiat, który organizuje rodzinny\ndom dziecka lub zleca organizację rodzinnego domu dziecka;\n5) rodziny pomocowej jest powiat, który organizuje rodzinę pomocową\nzawodową lub zleca organizację rodziny pomocowej.\n2. W przypadku połączenia funkcji:\n1) rodziny zastępczej spokrewnionej z funkcją rodziny zastępczej niezawodowej\npowiatem właściwym jest powiat, właściwy dla organizatora, który wydał\nzaświadczenie kwalifikacyjne dla rodziny zastępczej niezawodowej;\n2) rodziny zastępczej spokrewnionej z funkcją rodziny zastępczej zawodowej\npowiatem właściwym jest powiat, który organizuje rodzinę zastępczą\nzawodową lub zleca organizację rodziny zastępczej zawodowej;\n3) rodziny zastępczej spokrewnionej z prowadzeniem rodzinnego domu dziecka,\npowiatem właściwym jest powiat, który organizuje rodzinny dom dziecka lub\nzleca organizację rodzinnego domu dziecka.\n3. W przypadku wygaśnięcia umowy o współpracy zawartej z niezawodową rodziną\nzastępczą w związku z uchyleniem albo wygaśnięciem decyzji, o której mowa w art. 76a\nust. 2, i nie podpisania przez tę rodzinę zastępczą umowy o współpracy z innym\npozarządowym organizatorem rodzinnej pieczy zastępczej powiatem właściwym w \f– 32 –\nzakresie zapewnienia funkcjonowania tej rodziny zastępczej jest powiat właściwy ze\nwzględu na jej miejsce zamieszkania.\n4. Starosta powiatu, o którym mowa w ust. 1-3, może zawrzeć ze starostą innego\npowiatu porozumienie, w którym powierzy zadania związane z funkcjonowaniem rodziny\npomocowej, rodziny zastępczej lub prowadzeniem rodzinnego domu dziecka, w tym w\nzakresie dotyczącym realizacji zadań przez organizatora rodzinnej pieczy zastępczej, a\ntakże kontroli, o której mowa w art. 38b ust. 1, finansowania, w tym przyznawania\nświadczeń, dodatków lub wypłaty wynagrodzeń przysługujących odpowiednio rodzinie\npomocowej, rodzinie zastępczej lub prowadzącemu rodzinny dom dziecka, powiatowi\nstarosty z którym zawarto porozumienie.\n5. Powiatem właściwym, w zakresie funkcjonowania placówki opiekuńczo-\nwychowawczej jest powiat, który prowadzi placówkę lub powiat, który zlecił realizację\ntego zadania na podstawie art. 190.\n6. Starosta powiatu, o którym mowa w ust. 5, może zawrzeć ze starostą powiatu  na\nterenie którego prowadzona jest placówka opiekuńczo-wychowawcza porozumienie, w\nktórym powierzy zadania związane z zapewnieniem funkcjonowania placówki\nopiekuńczo-wychowawczej.”;\n33) w art. 37:\na) ust. 3-8 otrzymują brzmienie:\n„3. W przypadku odpowiednio rozwiązania albo likwidacji dotychczasowej\nrodziny zastępczej, rodzinnego domu dziecka, placówki opiekuńczo-wychowawczej\nalbo regionalnej placówki opiekuńczo-terapeutycznej, w której przebywa osoba, o\nktórej mowa w ust. 2, osoba ta może przebywać w innej niż dotychczasowa rodzinie\nzastępczej, rodzinnym domu dziecka, placówce opiekuńczo-wychowawczej albo\nregionalnej placówce opiekuńczo-terapeutycznej za zgodą odpowiednio starosty,\npozarządowego organizatora rodzinnej pieczy zastępczej albo marszałka\nwojewództwa oraz odpowiednio rodziny zastępczej, prowadzącego rodzinny dom\ndziecka, dyrektora placówki opiekuńczo-wychowawczej albo dyrektora regionalnej\nplacówki opiekuńczo-terapeutycznej.\n4. W szczególnie uzasadnionych przypadkach osoba, która osiągnęła\npełnoletność przebywając w pieczy zastępczej, a po osiągnięciu pełnoletności\nopuściła dotychczasową rodzinę zastępczą, rodzinny dom dziecka, placówkę\nopiekuńczo-wychowawczą albo regionalną placówkę opiekuńczo-terapeutyczną, w \f– 33 –\ntym uzyskała wsparcie w mieszkaniu treningowym lub wspomaganym, o którym\nmowa w art. 53 ust. 1 ustawy z dnia 12 marca 2004 r. o pomocy społecznej, może\njeden raz powrócić, o ile spełnia wymagania określone w ust. 2, do dotychczasowej\nrodziny zastępczej, rodzinnego domu dziecka, placówki opiekuńczo-wychowawczej\nalbo regionalnej placówki opiekuńczo-terapeutycznej za zgodą odpowiednio\nstarosty, pozarządowego organizatora rodzinnej pieczy zastępczej albo marszałka\nwojewództwa oraz odpowiednio rodziny zastępczej, prowadzącego rodzinny dom\ndziecka, dyrektora placówki opiekuńczo-wychowawczej albo dyrektora regionalnej\nplacówki opiekuńczo-terapeutycznej.\n5. Osoba, której pobyt w rodzinnej pieczy zastępczej ustał w okresie 6 miesięcy\nprzed osiągnięciem przez tę osobę pełnoletności na skutek śmierci osób tworzących\nrodzinę zastępczą lub osoby prowadzącej rodzinny dom dziecka może, o ile spełnia\nwymagania określone w ust. 2, jeden raz powrócić do rodziny zastępczej, rodzinnego\ndomu dziecka, placówki opiekuńczo-wychowawczej albo regionalnej placówki\nopiekuńczo-terapeutycznej za zgodą odpowiednio starosty, pozarządowego\norganizatora rodzinnej pieczy zastępczej albo marszałka województwa oraz\nodpowiednio rodziny zastępczej, prowadzącego rodzinny dom dziecka, dyrektora\nplacówki opiekuńczo-wychowawczej albo dyrektora regionalnej placówki\nopiekuńczo-terapeutycznej.\n6. W przypadku odpowiednio rozwiązania albo likwidacji dotychczasowej\nrodziny zastępczej, rodzinnego domu dziecka, placówki opiekuńczo-wychowawczej\nalbo regionalnej placówki opiekuńczo-terapeutycznej osoba, o której mowa w ust. 4\nlub 5, o ile spełnia wymagania określone w ust. 2, może przebywać w innej niż\ndotychczasowa rodzinie zastępczej, rodzinnym domu dziecka, placówce\nopiekuńczo-wychowawczej albo regionalnej placówce opiekuńczo-terapeutycznej\nza zgodą odpowiednio starosty, pozarządowego organizatora rodzinnej pieczy\nzastępczej albo marszałka województwa oraz odpowiednio rodziny zastępczej,\nprowadzącego rodzinny dom dziecka, dyrektora placówki opiekuńczo-\nwychowawczej albo dyrektora regionalnej placówki opiekuńczo-terapeutycznej.\n7. Starosta, pozarządowy organizator rodzinnej pieczy zastępczej oraz\nmarszałek województwa, wydając zgodę, o której mowa w ust. 3-6, uwzględniają w\nszczególności liczbę wolnych miejsc w pieczy zastępczej oraz brak negatywnego\nwpływu pobytu osoby, która osiągnęła pełnoletność przebywając w pieczy \f– 34 –\nzastępczej, lub osoby, o której mowa w ust. 5 lub 6, na dzieci umieszczone lub\nprzebywającej w tej formie pieczy zastępczej.\n8. Informacja w przedmiocie zgody rodziny zastępczej, prowadzącego rodzinny\ndom dziecka, dyrektora placówki opiekuńczo-wychowawczej albo dyrektora\nregionalnej placówki opiekuńczo-terapeutycznej, o której mowa odpowiednio w ust.\n2-6, oraz informacja w przedmiocie zgody starosty, pozarządowego organizatora\nrodzinnej pieczy zastępczej albo marszałka województwa, o której mowa\nodpowiednio w ust. 3-6, jest wydawana w formie pisemnej. W przypadku braku\nzgody dyrektora placówki opiekuńczo-wychowawczej albo dyrektora regionalnej\nplacówki opiekuńczo-terapeutycznej oraz braku zgody starosty, pozarządowego\norganizatora rodzinnej pieczy zastępczej albo marszałka województwa, o której\nmowa odpowiednio w ust. 3-6, informacja zawiera pouczenie strony o\nprzysługującym prawie wniesienia do sądu administracyjnego skargi na zasadach i\nw trybie określonych dla aktów lub czynności, o których mowa w art. 3 § 2 pkt\n4 ustawy z dnia 30 sierpnia 2002 r. - Prawo o postępowaniu przed sądami\nadministracyjnymi (Dz.U. z 2024 r. poz. 935 i 1685).”,\nb) po ust. 8 dodaje się ust. 9 w brzmieniu:\n„9. Osoba, która osiągnęła pełnoletność przebywając w pieczy zastępczej i po\nosiągnięciu pełnoletności opuściła dotychczasową rodzinę zastępczą, rodzinny dom\ndziecka, placówkę opiekuńczo-wychowawczą albo regionalną placówkę\nopiekuńczo-terapeutyczną, może mieć przyznane wsparcie w mieszkaniu\ntreningowym lub wspomaganym, o którym mowa w art. 53 ust. 1 ustawy z dnia 12\nmarca 2004 r. o pomocy społecznej.”;\n34) w art. 38a\na) w ust. 1:\n- wprowadzenie do wyliczenia otrzymuje brzmienie:\n„1. Powiatowe centrum pomocy rodzinie oraz organizator rodzinnej pieczy\nzastępczej gromadzą i przekazują odpowiednio rodzinie zastępczej, prowadzącemu\nrodzinny dom dziecka, dyrektorowi placówki opiekuńczo-wychowawczej,\ndyrektorowi regionalnej placówki opiekuńczo-terapeutycznej, oraz zespołowi do\nspraw okresowej oceny sytuacji dziecka umieszczonego w instytucjonalnej pieczy\nzastępczej informacje oraz dokumentację dotyczące dziecka, w szczególności :”,\n- pkt 2 otrzymuje brzmienie:\f– 35 –\n„2) szczegółowe informacje o dziecku i jego sytuacji rodzinnej, uwzgledniające\nrównież przyczyny umieszczenia dziecka w pieczy, w tym informacje o\nrodzeństwie i rodzicach dziecka;”,\n- pkt 8 otrzymuje brzmienie:\n„8) plan pracy z rodziną, o którym mowa w art. 15 ust. 1 pkt 1 oraz odpowiednio\njego aktualizację i ocenę końcową, przekazane przez asystenta rodziny, a\nw przypadku, gdy rodzinie dziecka nie został przydzielony asystent rodziny\n- przekazaną przez gminę informację o sytuacji rodziny;”,\n- po pkt 8 dodaje się pkt 9-11 w brzmieniu:\n„9) informacje na temat dotychczasowych miejsc pobytu dziecka w\nplacówkach zapewniających całodobową opiekę;\n10) szczegółowy opis przebiegu pobytu dziecka w pieczy zastępczej,\nzawierający również daty umieszczania dziecka w pieczy zastępczej;\n11) informacje dotyczące wyznania i pochodzenia etnicznego dziecka.”,\nb) w ust. 2 wprowadzenie do wyliczenia otrzymuje brzmienie:\n„2. W przypadku małoletniego cudzoziemca poza informacjami i\ndokumentacją, o których mowa w ust. 1, powiatowe centrum pomocy rodzinie oraz\norganizator rodzinnej pieczy zastępczej ponadto gromadzą i przekazują odpowiednio\nrodzinie zastępczej, prowadzącemu rodzinny dom dziecka, dyrektorowi placówki\nopiekuńczo-wychowawczej, dyrektorowi regionalnej placówki opiekuńczo-\nterapeutycznej oraz zespołowi do spraw okresowej oceny sytuacji dziecka\numieszczonego w instytucjonalnej pieczy zastępczej dostępne informacje oraz\ndokumentację, a w szczególności:”,\nc) ust. 3 otrzymuje brzmienie:\n„3. W celu realizacji zadań, o których mowa w ust. 1 i 2 oraz art. 139a,\npowiatowe centrum pomocy rodzinie oraz organizator rodzinnej pieczy zastępczej\nmają prawo do uzyskania informacji oraz otrzymania lub wglądu do wszelkiej\ndostępnej dokumentacji, w tym prawnej i medycznej, dotyczących przyjętego\ndziecka jak również przetwarzania jego wizerunku.”;\f– 36 –\n35) w art. 38b:\na) ust. 1 otrzymuje brzmienie:\n„1. Z zastrzeżeniem ust. 11, kontrolę nad rodzinami zastępczymi,\nprowadzącymi rodzinne domy dziecka oraz placówkami opiekuńczo-\nwychowawczymi sprawuje zarząd powiatu właściwego, o którym mowa w art. 35b.”,\nb) po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Z zastrzeżeniem ust. 12, kontrolę nad organizatorami rodzinnej pieczy\nzastępczej sprawuje zarząd powiatu.”,\nc) w ust. 2 zdanie pierwsze otrzymuje brzmienie:\n„2. Zarząd powiatu może upoważnić, w formie pisemnej członka zarządu\npowiatu, pracownika urzędu lub innej jednostki organizacyjnej powiatu do\nsprawowania kontroli, o której mowa w ust. 1 i 1a.”,\nd) uchyla się ust. 3-5,\ne) ust. 6 otrzymuje brzmienie:\n„6. Zarząd województwa sprawuje kontrolę nad regionalnymi placówkami\nopiekuńczo-terapeutycznymi.”,\nf) w ust. 7 zdanie pierwsze otrzymuje brzmienie:\n„7. Zarząd województwa może upoważnić, w formie pisemnej, członka zarządu\nwojewództwa, pracownika urzędu marszałkowskiego lub innej jednostki\norganizacyjnej województwa do sprawowania kontroli, o której mowa w ust. 6.”,\ng) po ust. 10 dodaje się ust. 11 i 12 w brzmieniu:\n„11. W przypadku organizowania rodziny zastępczej niezawodowej, rodziny\nzastępczej zawodowej, rodzinnego domu dziecka, albo rodziny pomocowej przez\npozarządowego organizatora rodzinnej pieczy zastępczej, kontrolę nad tym\nrodzinami albo prowadzącym rodzinny dom dziecka, sprawuje pozarządowy\norganizator rodzinnej pieczy zastępczej. Przepisy ust. 8 i 10 stosuje się odpowiednio.\n12. Kontrolę nad pozarządowym organizatorem rodzinnej pieczy zastępczej\nsprawuje wojewoda właściwy ze względu na siedzibę odpowiednio organizacji\npozarządowej, podmiotu, o którym mowa w art. 3 ust. 3 ustawy z dnia 24 kwietnia\n2003 r. o działalności pożytku publicznego i wolontariacie albo ich oddziału, który\nustanowiono pozarządowym organizatorem rodzinnej pieczy zastępczej. Przepisy\nust. 8 i 10 stosuje się odpowiednio.”.\f– 37 –\n36) w art. 38c wprowadzenie do wyliczenia otrzymuje brzmienie:\n„W okresie stanu zagrożenia epidemicznego albo stanu epidemii rodzina zastępcza,\nprowadzący rodzinny dom dziecka, dyrektor placówki opiekuńczo-wychowawczej oraz\ndyrektor regionalnej placówki opiekuńczo-terapeutycznej są obowiązani do:”;\n37) w art. 38d:\na) w ust. 1 pkt 6 i 7 otrzymują brzmienie:\n„6) wykaz placówek opiekuńczo-wychowawczych oraz regionalnych placówek\nopiekuńczo-terapeutycznych;\n7) wykaz osób usamodzielnianych opuszczających po osiągnięciu pełnoletności,\nrodzinę zastępczą, rodzinny dom dziecka, placówkę opiekuńczo-\nwychowawczą lub regionalną placówkę opiekuńczo-terapeutyczną.”,\nb) w ust. 3:\n- w pkt 8 lit. a-b otrzymują brzmienie:\n„a) w przypadku umieszczenia dziecka, osoby, która osiągnęła pełnoletność\nprzebywając w pieczy zastępczej, o której mowa w art. 37 ust. 2-4 i 6, lub osoby\nopuszczającej rodzinną pieczę zastępczą jako niepełnoletnia, o której mowa w\nart. 37 ust. 5 i 6, w rodzinnej pieczy zastępczej - formy rodzinnej pieczy\nzastępczej, w której zostało umieszczone dziecko lub osoba, województwa,\npowiatu i adresu odpowiednio zamieszkania rodziny zastępczej lub\nprowadzenia rodzinnego domu dziecka, odpowiednio powiatu, o którym mowa\nw art. 35b ust. 1-3, chyba że porozumienie, o którym mowa w art. 35b ust. 4,\nstanowi inaczej  albo pozarządowego organizatora rodzinnej pieczy zastępczej\noraz imienia, nazwiska i numeru PESEL, a w razie gdy nie nadano numeru\nPESEL - numeru i serii dokumentu potwierdzającego tożsamość odpowiednio\nosoby tworzącej rodzinę zastępczą lub osoby prowadzącej rodzinny dom\ndziecka, b) w przypadku umieszczenia dziecka, osoby, która osiągnęła\npełnoletność przebywając w pieczy zastępczej, o której mowa w art. 37 ust. 2-\n4 i 6, lub osoby opuszczającej rodzinną pieczę zastępczą jako niepełnoletnia, o\nktórej mowa w art. 37 ust. 5 i 6, w instytucjonalnej pieczy zastępczej - formy i\ntypu instytucjonalnej pieczy zastępczej, w której zostało umieszczone dziecko\nlub osoba, województwa, powiatu, adresu, nazwy, numeru NIP i numeru\nREGON odpowiednio placówki opiekuńczo-wychowawczej lub regionalnej\nplacówki opiekuńczo-terapeutycznej oraz imienia, nazwiska i numeru PESEL, \f– 38 –\na w razie gdy nie nadano numeru PESEL - numeru i serii dokumentu\npotwierdzającego tożsamość osoby kierującej odpowiednio tą placówką, a w\nprzypadkach, o których mowa w art. 97 ust. 1a, 1b i 2a - również adresu, ze\nwskazaniem powiatu i województwa, numeru NIP i numeru REGON\nodpowiednio jednostki zapewniającej wspólną obsługę placówek opiekuńczo-\nwychowawczych, podmiotu, któremu zlecono realizację obsługi placówek\nopiekuńczo-wychowawczych lub podmiotu, któremu powiat zlecił\nprowadzenie placówek opiekuńczo-wychowawczych na podstawie art. 190,\noraz imienia, nazwiska i numeru PESEL, a w razie gdy nie nadano numeru\nPESEL - numeru i serii dokumentu potwierdzającego tożsamość dyrektora\nodpowiednio tej jednostki lub podmiotu,”,\n- po pkt 9 dodaje się pkt 9a-9c w brzmieniu:\n„9a) dotyczące niezrealizowania przez powiat w ciągu dwóch tygodni\nrozstrzygnięcia sądu o umieszczeniu dziecka w rodzinnej pieczy\nzastępczej;\n9b) dotyczące przebywania dziecka w instytucjonalnej formie pieczy zastępczej\nwbrew rozstrzygnięciu sądu o umieszczeniu dziecka w rodzinnej formie\npieczy zastępczej;\n9c) dotyczące przebywania w placówce opiekuńczo-wychowawczej typu\nsocjalizacyjnego, interwencyjnego lub specjalistyczno-terapeutycznego\ndzieca poniżej 10. roku życia;”,\n- po pkt 15 dodaje się pkt 15a w brzmieniu:\n„15a) dotyczące przebywania rodzeństwa w różnych rodzinach zastępczych,\nrodzinnych domach dziecka, placówkach opiekuńczo-wychowawczych lub\nregionalnych placówkach opiekuńczo-terapeutycznych;”,\nc) w ust. 6:\n- po pkt 16 dodaje się pkt 16a w brzmieniu:\n„16a) informację o pełnieniu przez rodzinę zastępczą funkcji rodziny\nopiekuńczej wraz ze wskazaniem liczby osób w stosunku do których ta\nfunkcja jest pełniona;”,\n- pkt 20 - 22 otrzymują brzmienie:\n„20) informację o dacie zawarcia umowy rodzicielstwa zastępczego;\f– 39 –\n21) wskazanie odpowiednio powiatu, o którym mowa odpowiednio w art. 35b\nust. 1-3, lub podmiotu, któremu powiat zlecił organizowanie rodziny\nzastępczej, albo pozarządowego organizatora rodzinnej pieczy zastępczej ;\n22) informację, czy zawarto porozumienie, o którym mowa w o którym mowa\nw art. 35b ust. 4;”,\nd) w ust. 7:\n- po pkt 16 dodaje się pkt 16a w brzmieniu:\n„16a. informację o pełnieniu przez osoby prowadzące rodzinny dom dziecka\nfunkcji rodziny opiekuńczej wraz ze wskazaniem liczby osób w stosunku\ndo których ta funkcja jest pełniona;”,\n- pkt 18- 20 otrzymuje brzmienie:\n„18) informację o dacie zawarcia umowy rodzicielstwa zastępczego;\n19) wskazanie odpowiednio powiatu, o którym mowa odpowiednio w art. 35b\nust. 1-3, lub podmiotu, któremu powiat zlecił organizowanie rodzinnego\ndomu dziecka albo pozarządowego organizatora rodzinnej pieczy\nzastępczej;\n20) informację, czy zawarto porozumienie, o którym mowa w art. 35b ust. 4;”,\ne) ust. 8 otrzymuje brzmienie:\n„8. Wykaz, o którym mowa w ust. 1 pkt 6, zawiera następujące dane:\n1) nazwę oraz typ placówki opiekuńczo-wychowawczej i nazwę regionalnej\nplacówki opiekuńczo-terapeutycznej;\n2) adres, ze wskazaniem powiatu i województwa, numer NIP, numer REGON,\nadres poczty elektronicznej oraz numer telefonu placówki opiekuńczo-\nwychowawczej i regionalnej placówki opiekuńczo-terapeutycznej, a w przypadkach,\no których mowa w art. 97 ust. 1a, 1b i 2a - również adres, ze wskazaniem powiatu i\nwojewództwa, numer NIP, numer REGON, adres poczty elektronicznej oraz numer\ntelefonu odpowiednio jednostki zapewniającej wspólną obsługę placówek\nopiekuńczo-wychowawczych, podmiotu, któremu zlecono realizację obsługi\nplacówek opiekuńczo-wychowawczych lub podmiotu, któremu powiat zlecił\nprowadzenie placówek opiekuńczo-wychowawczych na podstawie art. 190;\n3) imię, nazwisko i numer PESEL, a w razie gdy nie nadano numeru PESEL -\nnumer i serię dokumentu potwierdzającego tożsamość osoby kierującej odpowiednio\nplacówką opiekuńczo-wychowawczą lub regionalną placówką opiekuńczo-\f– 40 –\nterapeutyczną , a w przypadkach, o których mowa w art. 97 ust. 1a, 1b i 2a - również\ndyrektora odpowiednio jednostki zapewniającej wspólną obsługę placówek\nopiekuńczo-wychowawczych, podmiotu, któremu zlecono realizację obsługi\nplacówek opiekuńczo-wychowawczych lub podmiotu, któremu powiat zlecił\nprowadzenie placówek opiekuńczo-wychowawczych na podstawie art. 190;\n4) wynikającą z zezwolenia wydanego przez wojewodę liczbę miejsc w\nplacówce opiekuńczo-wychowawczej, w tym liczbę miejsc przewidzianych dla\nkażdego typu placówki - w przypadku placówki opiekuńczo-wychowawczej łączącej\nzadania na podstawie art. 101 ust. 3, i liczbę miejsc w regionalnej placówce\nopiekuńczo-terapeutycznej;\n5) liczbę dzieci, osób, które osiągnęły pełnoletność przebywając w pieczy\nzastępczej, o których mowa w art. 37 ust. 2-4 i 6, i osób opuszczających rodzinną\npieczę zastępczą jako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6,\numieszczonych lub przebywających w placówce opiekuńczo-wychowawczej, a w\nprzypadku placówki opiekuńczo-wychowawczej łączącej zadania na podstawie art.\n101 ust. 3 w poszczególnych typach placówek i w regionalnej placówce opiekuńczo-\nterapeutycznej;\n6) liczbę wolnych miejsc w placówce opiekuńczo-wychowawczej, a w\nprzypadku placówki opiekuńczo-wychowawczej łączącej zadania na podstawie art.\n101 ust. 3 - w poszczególnych typach placówek i w regionalnej placówce\nopiekuńczo-terapeutycznej;\n7) oznaczenie wojewody, który wydał zezwolenie na prowadzenie placówki\nopiekuńczo-wychowawczej lub regionalnej placówki opiekuńczo-terapeutycznej;\n8) informację, czy zawarto porozumienie, o którym mowa w 35b ust. 6;\n9) informację o likwidacji lub o cofnięciu zezwolenia na prowadzenie placówki\nopiekuńczo-wychowawczej i regionalnej placówki opiekuńczo-terapeutycznej.”,\nf) w ust. 9:\n- w pkt 7 w lit. a tire czwarte otrzymuje brzmienie:\n„- wskazania odpowiednio starosty powiatu, o którym mowa w art. 35b ust. 1-3,\nchyba że porozumienie, o którym mowa w art. 35b ust. 4, stanowi inaczej,\npodmiotu, któremu powiat zlecił organizowanie rodziny zastępczej lub\nrodzinnego domu dziecka albo pozarządowego organizatora rodzinnej\npieczy zastępczej,”,\f– 41 –\n- w pkt 8 i 9 otrzymują brzmienie:\n„8) formy udzielonej pomocy, o której mowa w art. 140 ust. 1 i 4;\n9) informację o zawieszeniu udzielania pomocy, o której mowa w art. 140 ust. 1\ni 4;”;\ng) w ust. 10:\n- w pkt 1:\n- - lit. a otrzymuje brzmienie:\n„a) starosta powiatu właściwego, o którym mowa w art. 35b ust. 1-3 albo 5,\nchyba że porozumienie, o którym mowa w art. 35b ust. 4 albo 6 stanowi\ninaczej,”,\n-- uchyla się lit. b i c;\n-- w pkt 1 po lit. d średnik zastępuje się przecinkiem i dodaje się lit. e w\nbrzmieniu:\n„e)właściwy pozarządowy organizator rodzinnej pieczy;”,\n- pkt 4 i 5 otrzymują brzmienie:\n„4) ust. 6 - do rejestru wprowadza, aktualizuje i usuwa odpowiednio starosta\npowiatu, o którym mowa odpowiednio w art. 35b ust. 1-3, chyba że\nporozumienie, o którym mowa w art. 35b ust. 4 stanowi inaczej albo\nwłaściwy pozarządowy organizator rodzinnej pieczy zastępczej;\n5) ust. 7 - do rejestru wprowadza, aktualizuje i usuwa starosta powiatu, o którym\nmowa odpowiednio w art. 35b ust. 1-3, chyba że porozumienie, o którym\nmowa w art. 35b ust. 4, stanowi inaczej albo właściwy pozarządowy\norganizator rodzinnej pieczy zastępczej;”,\n- w pkt 6 lit. a otrzymuje brzmienie:\n„a) starosta powiatu właściwego, o którym mowa art. 35b ust. 5, chyba\nże porozumienie, o którym mowa w art. 35b ust. 6 stanowi inaczej- w\nzakresie placówek opiekuńczo-wychowawczych,”;\n- pkt 7 otrzymuje brzmienie:\n„7) ust. 9 - do rejestru wprowadza, aktualizuje i usuwa odpowiednio starosta\npowiatu właściwego ze względu na miejsce pobytu osoby usamodzielnianej,\nstarosta powiatu właściwego do ponoszenia wydatków na finansowanie\npomocy na kontynuowanie nauki i usamodzielnienie osoby\nusamodzielnianej- w zakresie pomocy na pokrycie kosztów związanych z \f– 42 –\nwystąpieniem zdarzeń losowych lub innych zdarzeń mających wpływ\nprzebieg procesu usamodzielnienia, lub starosta powiatu właściwego ze\nwzględu na miejsce osiedlenia się osoby usamodzielnianej- w zakresie\npomocy na zagospodarowanie;”,\nh) ust. 11-13 otrzymują brzmienie:\n„11. Starosta może upoważnić pracownika urzędu lub innej jednostki\norganizacyjnej powiatu do wprowadzania, aktualizowania i usuwania z rejestru\ndanych, o których mowa w ust. 3, 6, 7, 8 w zakresie placówek opiekuńczo-\nwychowawczych oraz w ust. 9.\n12. Marszałek województwa może upoważnić pracownika urzędu lub innej\njednostki organizacyjnej województwa do wprowadzania, aktualizowania\ni usuwania z rejestru danych, o których mowa w ust. 3 i 8, w zakresie regionalnych\nplacówek opiekuńczo-terapeutycznych.\n13. Wojewoda może upoważnić pracownika urzędu lub innej jednostki\norganizacyjnej województwa do wprowadzania, aktualizowania i usuwania z rejestru\ndanych, o których mowa w ust. 8 pkt 4 i 7, oraz danych w zakresie wynikającym\nz zezwolenia na prowadzenie odpowiednio placówki opiekuńczo-wychowawczej\nlub regionalnej placówki opiekuńczo-terapeutycznej.”,\ni) ust. 16 otrzymuje brzmienie:\n„16. Osoby posiadające wstępną kwalifikację do pełnienia funkcji rodziny\nzastępczej lub prowadzenia rodzinnego domu dziecka, kandydaci zakwalifikowani\ndo pełnienia funkcji rodziny zastępczej lub prowadzenia rodzinnego domu dziecka,\nrodziny zastępcze, osoby prowadzące rodzinne domy dziecka oraz osoby\nusamodzielniane są obowiązani do informowania odpowiednio:\n1) organizatora rodzinnej pieczy zastępczej, który wstępnie zakwalifikował\nkandydata do pełnienia funkcji rodziny zastępczej lub prowadzenia rodzinnego\ndomu dziecka lub wydał zaświadczenie kwalifikacyjne, o którym mowa w art. 45\nust. 1 lub art. 45b ust. 1;\n2) odpowiednio starosty powiatu właściwego, o którym mowa w art. 35b ust.\n1-3, chyba że porozumienie, o którym mowa w art. 35b ust. 4, stanowi inaczej, albo\nwłaściwego pozarządowego organizatora rodzinnej pieczy zastępczej, o którym\nmowa w art. 76a ust. 3;\f– 43 –\n3) starosty powiatu właściwego do ponoszenia wydatków na finansowanie\npomocy na kontynuowanie nauki i usamodzielnienie osoby usamodzielnianej;\n4) starosty powiatu właściwego ze względu na miejsce pobytu osoby\nusamodzielnianej;\n5) starosty powiatu właściwego ze względu na miejsce osiedlenia się osoby\nusamodzielnianej\n- o każdej zmianie danych, o których mowa odpowiednio w ust. 4 pkt 1 i 3-11,\nust. 5 pkt 1 i 3-11, ust. 6 pkt 1, 3-11 i 16a, ust. 7 pkt 1, 3-11 i 16a oraz ust. 9 pkt 1, 3\ni 4.”;\n38) w art. 38e:\na) w ust. 1:\n- pkt 1 otrzymuje brzmienie:\n„1) staroście powiatu, pozarządowemu organizatorowi rodzinnej pieczy\nzastępczej, marszałkowi województwa, o których mowa w art. 38d ust. 10\npkt 1 - dane dotyczące dzieci umieszczonych w pieczy zastępczej, o\nktórych mowa w art. 38d ust. 3, w celu zapewnienia dzieciom pieczy\nzastępczej;”,\n- pkt 4 otrzymuje brzmienie:\n„4) staroście powiatu innego niż powiat, o którym mowa w pkt 1-3, oraz\npozarządowemu organizatorowi rodzinnej pieczy zastępczej, innemu niż\npozarządowy organizator rodzinnej pieczy zastępczej, o którym mowa w\npkt 1- dane, o których mowa w art. 38d ust. 3 pkt 8 lit. a i b - w zakresie\nodpowiednio powiatu właściwego, o którym mowa w art. 35b,\npozarządowego organizatora rodzinnej pieczy zastępczej lub województwa\nna terenie którego dziecko zostało umieszczone w regionalnej placówce\nopiekuńczo- terapeutycznej, oraz pkt 11 w zakresie numeru PESEL,\na w razie gdy nie nadano numeru PESEL - numeru i serii dokumentu\npotwierdzającego tożsamość rodziców dziecka, w celu zapewnienia\ndzieciom pieczy zastępczej oraz zapewnienia im prawa do zachowania\nstosunków rodzinnych;”,\n- po pkt 4 dodaje się pkt 4a w brzmieniu:\n„4a) pozarządowemu organizatorowi rodzinnej pieczy zastępczej, innemu niż\npozarządowy organizator rodzinnej pieczy zastępczej, o którym mowa w \f– 44 –\npkt 1- dane o których mowa w art. 38d ust. 3, w przypadku dzieci, o których\nmowa w art. 76a ust. 1, w celu tworzenia i zapewnienia funkcjonowania\nrodzin zastępczych, rodzinnych domów dziecka oraz w celu zapewnienia\ndzieciom rodzinnej pieczy zastępczej;”,\n- pkt 5 otrzymuje brzmienie:\n„5) marszałkowi województwa innego niż województwo, o którym mowa w pkt\n1 - dane, o których mowa w art. 38d ust. 3 pkt 8 lit. a i b - w zakresie\nodpowiednio powiatu właściwego, o którym mowa w art. 35b,\npozarządowego organizatora rodzinnej pieczy zastępczej lub województwa\nna terenie którego dziecko zostało umieszczone w regionalnej placówce\nopiekuńczo- terapeutycznej, oraz pkt 11 w zakresie numeru PESEL, a w\nrazie gdy nie nadano numeru PESEL - numeru i serii dokumentu\npotwierdzającego tożsamość rodziców dziecka, w celu zapewnienia\ndzieciom pieczy zastępczej oraz zapewnienia im prawa do zachowania\nstosunków rodzinnych;”,\n- pkt 6 otrzymuje brzmienie:\n„6) wojewodzie właściwemu ze względu na miejsce sprawowania pieczy\nzastępczej lub wojewodzie, o którym mowa w art. 38b ust. 12– dane, o\nktórych mowa w art. 38d ust. 3, w celu sprawowania kontroli nad realizacją\nzadań z zakresu wspierania rodziny i pieczy zastępczej wykonywanych\nprzez jednostki organizacyjne wspierania rodziny i systemu pieczy\nzastępczej oraz w celu zasięgania informacji o sposobie realizacji zadań w\ntym zakresie;”,\n- pkt 8 otrzymuje brzmienie:\n„8) gminie miejsca zamieszkania rodziców dziecka umieszczonego w pieczy\nzastępczej oraz podmiotowi prowadzącemu pracę z rodziną dziecka - dane,\no których mowa w art. 38d ust. 3 pkt 8 lit. a i b - w zakresie odpowiednio\npowiatu właściwego, o którym mowa w art. 35b, pozarządowego\norganizatora rodzinnej pieczy zastępczej lub województwa na terenie\nktórego dziecko zostało umieszczone w regionalnej placówce opiekuńczo-\nterapeutycznej, oraz pkt 11 w zakresie numeru PESEL, a w razie gdy nie\nnadano numeru PESEL - numeru i serii dokumentu potwierdzającego\ntożsamość rodziców dziecka, w celu prowadzenia pracy z rodziną \f– 45 –\nprzeżywającą trudności w wypełnianiu funkcji opiekuńczo-\nwychowawczych;”,\nb) w ust. 3:\n- uchyla się pkt 2,\n- pkt 3 otrzymuje brzmienie:\n„3) organizatorowi rodzinnej pieczy zastępczej innemu niż organizator rodzinnej\npieczy zastępczej, o którym mowa w pkt 1, oraz staroście powiatu innego\nniż powiat organizatora rodzinnej pieczy zastępczej, o którym mowa w pkt\n1- dane, o których mowa w art. 38d ust. 5 pkt 1 i 15-17, oraz, za zgodą\norganizatora rodzinnej pieczy zastępczej, o którym mowa w art. 38d ust. 10\npkt 3 - dane, o których mowa w art. 38d ust. 5 pkt 2-14, w celu zapewnienia\ntworzenia i funkcjonowania rodzin zastępczych, rodzinnych domów\ndziecka i rodzin pomocowych oraz w celu zapewnienia dzieciom rodzinnej\npieczy zastępczej;”,\nc) w ust. 4:\n- pkt 1 otrzymuje brzmienie:\n„1) staroście powiatu i pozarządowemu organizatorowi rodzinnej pieczy\nzastępczej, o których mowa w art. 38d ust. 10 pkt 4 - dane, o których mowa\nw art. 38d ust. 6, w celu zapewnienia tworzenia i funkcjonowania rodzin\nzastępczych, rodzinnych domów dziecka i rodzin pomocowych oraz w celu\nzapewnienia dzieciom rodzinnej pieczy zastępczej;”,\n- pkt 3 otrzymuje brzmienie:\n„3) staroście powiatu innego niż powiat, o którym mowa w pkt 1 lub 2 oraz\npozarządowemu organizatorowi rodzinnej pieczy zastępczej, innemu niż\npozarządowy organizator rodzinnej pieczy zastępczej, o którym mowa w\npkt 1- dane, o których mowa w art. 38d ust. 6 pkt 1, 13, 15-18 i 24, oraz, za\nzgodą odpowiednio starosty albo pozarządowego organizatora rodzinnej\npieczy zastępczej, o których mowa w art. 38d ust. 10 pkt 4 - dane, o których\nmowa w art. 38d ust. 6 pkt 2, 5, 12, 14 i 20-23, w celu zapewnienia\ndzieciom rodzinnej pieczy zastępczej;”,\n- pkt 5 otrzymuje brzmienie:\n„5) wojewodzie właściwemu ze względu na powiat, o którym mowa w pkt 1 lub\n2 lub wojewodzie, o którym mowa w art. 38b ust. 12- dane, o których mowa \f– 46 –\nw art. 38d ust. 6, w celu sprawowania kontroli nad realizacją zadań z\nzakresu pieczy zastępczej wykonywanych przez jednostki organizacyjne\nsystemu pieczy zastępczej oraz w celu zasięgania informacji o sposobie\nrealizacji zadań w tym zakresie;”,\nd) w ust. 5:\n- pkt 1 otrzymuje brzmienie:\n„1) staroście powiatu i pozarządowemu organizatorowi rodzinnej pieczy\nzastępczej, o których mowa w art. 38d ust. 10 pkt 5 - dane, o których mowa\nw art. 38d ust. 7, w celu zapewnienia tworzenia i funkcjonowania rodzin\nzastępczych, rodzinnych domów dziecka i rodzin pomocowych oraz w celu\nzapewnienia dzieciom rodzinnej pieczy zastępczej;”,\n- pkt 3 otrzymuje brzmienie:\n„3) staroście powiatu innego niż powiat, o którym mowa w pkt 1 lub 2 oraz\npozarządowemu organizatorowi rodzinnej pieczy zastępczej, innemu niż\npozarządowy organizator rodzinnej pieczy zastępczej, o którym mowa w\npkt 1- dane, o których mowa w art. 38d ust. 7 pkt 1, 13, 15, 16, 16a i 22, za\nzgodą odpowiednio starosty albo pozarządowego organizatora rodzinnej\npieczy zastępczej, o których mowa w art. 38d ust. 10 pkt 5 - dane, o których\nmowa w art. 38d ust. 7 pkt 2, 5, 12, 14 i 18-21, w celu zapewnienia\ndzieciom rodzinnej pieczy zastępczej;”,\n- pkt 5 otrzymuje brzmienie:\n„5) wojewodzie właściwemu ze względu na powiat, o którym mowa w pkt 1 lub\n2 lub wojewodzie, o którym mowa w art. 38b ust. 12- dane, o których mowa\nw art. 38d ust. 7, w celu sprawowania kontroli nad realizacją zadań z\nzakresu pieczy zastępczej wykonywanych przez jednostki organizacyjne\nsystemu pieczy zastępczej oraz w celu zasięgania informacji o sposobie\nrealizacji zadań w tym zakresie;”;\ne) w ust. 6:\n- pkt 2 otrzymuje brzmienie\n„2) staroście powiatu właściwego do finansowania pobytu dziecka w tej\nplacówce opiekuńczo-wychowawczej lub regionalnej placówce\nopiekuńczo-terapeutycznej - dane, o których mowa w art. 38d ust. 8, z\nwyłączeniem danych dotyczących numeru PESEL oraz numeru i serii \f– 47 –\ndokumentu potwierdzającego tożsamość, w celu zapewnienia finansowania\npobytu dziecka w instytucjonalnej pieczy zastępczej;”,\n- pkt 5 otrzymuje brzmienie:\n„5) wojewodzie właściwemu ze względu na powiat, o którym mowa w pkt 1 lub\n2 - dane, o których mowa w art. 38d ust. 8, z wyłączeniem danych\ndotyczących numeru PESEL oraz numeru i serii dokumentu\npotwierdzającego tożsamość, w celu wydawania i cofania zezwoleń na\nprowadzenie placówek opiekuńczo-wychowawczych i regionalnych\nplacówek opiekuńczo-terapeutycznych, sprawowania kontroli nad\nrealizacją zadań z zakresu pieczy zastępczej wykonywanych przez\njednostki organizacyjne systemu pieczy zastępczej oraz w celu zasięgania\ninformacji o sposobie realizacji zadań w tym zakresie;”,\nf) w ust. 7:\n- po pkt 2 dodaje się pkt 2a w brzmieniu:\n„2a) staroście powiatu właściwego do ponoszenia wydatków na finansowanie\npomocy na kontynuowanie nauki i usamodzielnienie osoby\nusamodzielnianej- - dane, o których mowa w art. 38d ust. 9, w celu\nzapewnienia pomocy osobom usamodzielnianym;”,\n- pkt 3 otrzymuje brzmienie:\n„3)  wojewodzie właściwemu ze względu na powiat, o którym mowa w pkt 1-2a\n- dane, o których mowa w art. 38d ust. 9, w celu sprawowania kontroli nad\nrealizacją zadań z zakresu usamodzielnień pełnoletnich wychowanków\noraz w celu zasięgania informacji o sposobie realizacji zadań w tym\nzakresie;”;\n39) w art. 38f ust. 16 otrzymuje brzmienie:\n„16. Podmioty wymienione w art. 38e ust. 6 pkt 1-6 przechowują dane, o których\nmowa w art. 38d ust. 8 pkt 3, przez okres kierowania przez osobę, o której mowa w art.\n38d ust. 8 pkt 3, odpowiednio placówką opiekuńczo-wychowawczą lub regionalną\nplacówką opiekuńczo-terapeutyczną. Dane, o których mowa w art. 38d ust. 8 pkt 3, usuwa\nsię niezwłocznie po upływie okresów przechowywania.”;\f– 48 –\n40) po art. 38f dodaje się ust. 38g w brzmieniu:\n„Art. 38g. Minister właściwy do spraw rodziny zapewnia system teleinformatyczny,\nza pomocą którego są wykonywane czynności związane z realizacją zadań dotyczących\nsystemu pieczy zastępczej.\";\n41) w art. 39 po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Dla rodzinnego domu dziecka może być również stosowana nazwa wielodzietna\nrodzina zastępcza. O stosowanej nazwie decyduje prowadzący rodzinny dom dziecka.”;\n42) w art. 40 po ust. 2 dodaje się ust. 3 i 4 w brzmieniu:\n„3. W przypadku doboru przez ośrodek adopcyjny kandydatów do przysposobienia\ndziecka przebywającego w rodzinie zastępczej lub rodzinnym domu dziecka, rodzina\nzastępcza lub prowadzący rodzinny dom dziecka współpracują z ośrodkiem adopcyjnym\noraz kandydatami do przysposobienia dziecka w zakresie przejścia dziecka pod opiekę\nodpowiednio kandydatów do przysposobienia dziecka lub przysposabiających.\n4. W przypadku zmiany formy pieczy zastępczej, powrotu dziecka do rodziny, lub\numieszczenia dziecka lub osoby, o której mowa w art. 37 ust. 2-6 w instytucjach, o\nktórych mowa w art. 87 ust. 2, rodzina zastępcza lub prowadzący rodzinny dom dziecka\nwspółpracują odpowiednio z koordynatorem rodzinnej pieczy zastępczej, organizatorem\nrodzinnej pieczy zastępczej, rodziną zastępczą, prowadzącym rodzinny dom dziecka,\ndyrektorem placówki opiekuńczo-wychowawczej, dyrektorem regionalnej placówki\nopiekuńczo-terapeutycznej, dyrektorami instytucji, o których mowa w art. 87 ust. 2,\nasystentem rodziny lub rodziną dziecka w zakresie przejścia dziecka lub osoby, o której\nmowa w art. 37 ust. 2-6 pod opiekę odpowiednio nowej rodziny zastępczej,\ninstytucjonalnej formy pieczy zastępczej, rodziny lub instytucji, o których mowa w art.\n87 ust. 2.”;\n43) w art. 41 po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Rodzina zastępcza lub rodzinny dom dziecka mogą być tworzone przez jednego\nz małżonków, jeżeli małżonkowie nie zamieszkują wspólnie.”;\n44) w art. 42:\na) w ust. 1 otrzymuje brzmienie:\n\"1. Pełnienie funkcji rodziny zastępczej oraz prowadzenie rodzinnego domu\ndziecka może być powierzone osobom, które:\n1) dają rękojmię należytego sprawowania pieczy zastępczej;\f– 49 –\n2) nie są i nie były pozbawione władzy rodzicielskiej, oraz władza rodzicielska\nnie jest im ograniczona ani zawieszona;\n3) wypełniają obowiązek alimentacyjny - w przypadku gdy taki obowiązek w\nstosunku do nich wynika z tytułu egzekucyjnego;\n4) nie są ograniczone w zdolności do czynności prawnych;\n5)  są zdolne do sprawowania właściwej opieki nad dzieckiem, co zostało\npotwierdzone:\na) zaświadczeniem lekarskim o stanie zdrowia wystawionym przez lekarza\npodstawowej opieki zdrowotnej, w rozumieniu przepisów ustawy z\ndnia 27 października 2017 r. o podstawowej opiece zdrowotnej, oraz\nb) opinią o posiadaniu predyspozycji i motywacji do pełnienia funkcji\nrodziny zastępczej lub prowadzenia rodzinnego domu dziecka\nwystawioną przez psychologa, który posiada co najmniej\nwykształcenie wyższe magisterskie na kierunku psychologia oraz 2-\nletnie doświadczenie w poradnictwie rodzinnym;\n6) posiadają ważne zaświadczenie kwalifikacyjne, o którym mowa w art. 45\nust. 1 lub art. 45b ust. 1;\n7) przebywają na terytorium Rzeczypospolitej Polskiej, z tym że w przypadku\ncudzoziemców ich pobyt jest legalny;\n8) zapewnią odpowiednie warunki bytowe i mieszkaniowe umożliwiające\ndziecku zaspokajanie jego indywidualnych potrzeb, w tym:\na) rozwoju emocjonalnego, fizycznego i społecznego,\nb) właściwej edukacji i rozwoju zainteresowań,\nc) wypoczynku i organizacji czasu wolnego\n- chyba że warunki mieszkaniowe zapewni organizator rodzinnej pieczy\nzastępczej;\n9) nie zamieszkują z rodzicami dziecka nad którym sprawują pieczę zastępczą,\nchyba że rodzice dziecka wymagają bezwzględnego wsparcia osób trzecich i nie\nzagraża to dobru dziecka.\",\nb) uchyla się ust. 2,\nc) ust. 5a otrzymuje brzmienie:\f– 50 –\n„5a. Przed wydaniem rozstrzygnięcia w sprawach, o których mowa w ust. 4 i\n5, sąd zasięga opinii odpowiednio właściwego starosty albo pozarządowego\norganizatora rodzinnej pieczy zastępczej.”;\nd) ust. 6a otrzymuje brzmienie:\n„6a. Do wydawania opinii, o której mowa w ust. 5a, starosta może upoważnić,\nw formie pisemnej, pracownika urzędu lub innej jednostki organizacyjnej powiatu.”,\ne) po ust. 7 dodaje się ust. 8 i 9 w brzmieniu:\n„8. W przypadku gdy rodzina zastępcza zawodowa, rodzina zastępcza\nniezawodowa lub prowadzący rodzinny dom dziecka przestanie spełniać warunki, o\nktórych mowa w art. 7b ust. 1 i 1b oraz art. 42 ust. 1 i 3, organizator rodzinnej pieczy\nzastępczej stwierdza nieaktualność wydanego zaświadczenia kwalifikacyjnego oraz\ninformuje właściwy sąd. Przepisy art. 45 ust. 3 stosuje się odpowiednio.\n9. W przypadku stwierdzenia nieaktualności wydanego zaświadczenia\nkwalifikacyjnego starosta lub pozarządowy organizator rodzinnej pieczy zastępczej\nwykreśla rodzinę zastępczą niezawodową lub zawodową albo rodzinny dom dziecka\nz rejestru, o którym mowa w art. 38d ust. 1 pkt 4 i 5.\ninformuje właściwy sąd.\n10. W przypadku gdy rodzina zastępcza spokrewniona przestanie spełniać\nwarunki, o których mowa w art. 7b ust. 1a i 1b oraz art. 42 ust. 1, organizator\nrodzinnej pieczy zastępczej stwierdza nieaktualność wydanego zaświadczenia\nkwalifikacyjnego oraz informuje właściwy sąd. Przepisy art. 45b ust. 2 stosuje się\nodpowiednio.\n11. W przypadku stwierdzenia nieaktualności wydanego zaświadczenia\nkwalifikacyjnego, o którym mowa w ust. 10, starosta wykreśla rodzinę zastępczą\nspokrewnioną niezwłocznie z rejestru, o którym mowa w art. 38d ust. 1 pkt 4.”;\n45) w art. 43:\na) ust. 1 otrzymuje brzmienie:\n„1. Organizator rodzinnej pieczy zastępczej, na wniosek kandydata do pełnienia funkcji\nrodziny zastępczej zawodowej, rodziny zastępczej niezawodowej lub prowadzenia\nrodzinnego domu dziecka, przeprowadza na podstawie oceny spełniania warunków,\no których mowa w art. 7b ust. 1 i 1b oraz art. 42 ust. 1 pkt 1-5 i 7-9, wstępną\nkwalifikację kandydata do pełnienia funkcji rodziny zastępczej zawodowej, rodziny \f– 51 –\nzastępczej niezawodowej lub prowadzenia rodzinnego domu dziecka. Pozytywna\nwstępna kwalifikacja jest ważna przez okres 2 lat od dnia jej przeprowadzenia.”;\nb) ust. 4 otrzymuje brzmienie:\n„4. Wstępna kwalifikacja, o której mowa w ust. 1, jest przeprowadzana przez\norganizatora rodzinnej pieczy zastępczej właściwego ze względu na miejsce\nzamieszkania kandydata do pełnienia funkcji rodziny zastępczej zawodowej, rodziny\nzastępczej niezawodowej lub prowadzenia rodzinnego domu dziecka albo przez\npozarządowego organizatora rodzinnej pieczy zastępczej.”,\nc) w ust. 5 wstęp do wyliczenia otrzymuje brzmienie:\n„5. Z zastrzeżeniem działań podejmowanych przez pozarządowego\norganizatora rodzinnej pieczy zastępczej, wstępna kwalifikacja, o której mowa w ust.\n1, może być przeprowadzana przez organizatora rodzinnej pieczy zastępczej innego\nniż organizator rodzinnej pieczy zastępczej właściwy ze względu na miejsce\nzamieszkania kandydata do pełnienia funkcji rodziny zastępczej zawodowej, rodziny\nzastępczej niezawodowej lub prowadzenia rodzinnego domu dziecka, jeżeli:”,\nd) ust. 7 i 8 otrzymują brzmienie:\n„7. Jeżeli kandydat do pełnienia funkcji rodziny zastępczej zawodowej, rodziny\nzastępczej niezawodowej lub prowadzenia rodzinnego domu dziecka nie posiada\nświadectwa ukończenia szkolenia, o którym mowa w art. 44 ust. 1 lub ust. 1a,\norganizator rodzinnej pieczy zastępczej, który pozytywnie wstępnie zakwalifikował\nkandydata do pełnienia funkcji rodziny zastępczej zawodowej, rodziny zastępczej\nniezawodowej lub prowadzenia rodzinnego domu dziecka, kieruje tego kandydata,\nna jego wniosek, na szkolenie.\n8. W przypadku o którym mowa w ust. 7, organizator rodzinnej pieczy\nzastępczej, który pozytywnie wstępnie zakwalifikował kandydata do pełnienia\nfunkcji rodziny zastępczej zawodowej, rodziny zastępczej niezawodowej lub\nprowadzenia rodzinnego domu dziecka, jest obowiązany do zapewnienia szkolenia,\no którym mowa w art. 44 ust. 1 lub ust. 1a, w terminie 3 miesięcy od dnia złożenia\nprzez kandydata wniosku.”;\n46) w art. 44:\na) ust. 1 otrzymuje brzmienie:\n„1. Kandydaci do pełnienia funkcji rodziny zastępczej zawodowej, rodziny\nzastępczej niezawodowej lub do prowadzenia rodzinnego domu dziecka są \f– 52 –\nobowiązani posiadać świadectwo ukończenia szkolenia organizowanego przez\norganizatora rodzinnej pieczy zastępczej lub przez inny podmiot.”,\nb) po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Kandydaci do pełnienia funkcji rodziny zastępczej niezawodowej\nnieposiadający świadectwa ukończenia szkolenia, o którym mowa w ust. 1, którzy\nposiadają świadectwo ukończenia szkolenia dla kandydatów do przysposobienia\ndziecka, o którym mowa w art. 172 ust. 1, oraz ważną pozytywną opinię\nkwalifikacyjną, o której mowa w art. 172a, są obowiązani posiadać świadectwo\nukończenia szkolenia uzupełniającego w zakresie pełnienia funkcji rodziny\nzastępczej niezawodowej organizowanego przez organizatora rodzinnej pieczy\nzastępczej lub przez inny podmiot.”,\nc) ust. 2 otrzymuje brzmienie:\n„2. Program szkoleń, o których mowa w ust. 1 i 1a, zatwierdza, na okres 5 lat,\nna wniosek podmiotu prowadzącego szkolenie, minister właściwy do spraw\nrodziny.”;\n47) w art. 45:\na) ust. 1 otrzymuje brzmienie:\n„1. Na wniosek kandydata do pełnienia funkcji rodziny zastępczej zawodowej,\nrodziny zastępczej niezawodowej lub prowadzenia rodzinnego domu dziecka,\nposiadającego świadectwo ukończenia szkolenia, o którym mowa odpowiednio\nw art. 44 ust. 1 lub 1a, organizator rodzinnej pieczy zastępczej, który pozytywnie\nwstępnie zakwalifikował kandydata do pełnienia funkcji rodziny zastępczej\nzawodowej, rodziny zastępczej niezawodowej lub prowadzenia rodzinnego domu\ndziecka, wydaje zaświadczenie kwalifikacyjne zawierające potwierdzenie\nukończenia tego szkolenia oraz spełniania warunków, o których mowa odpowiednio\nw art. 7b ust. 1 i 1b, art. 42 ust. 1 pkt 1-5, 7-9 oraz ust. 3.”;\nb) ust. 3 otrzymuje brzmienie:\n„3. W przypadku gdy kandydat do pełnienia funkcji rodziny zastępczej\nzawodowej, rodziny zastępczej niezawodowej lub prowadzenia rodzinnego domu\ndziecka przestanie spełniać warunki, o których mowa odpowiednio w art. 7b ust. 1 i\n1b, art. 42 ust. 1 pkt 1-5, 7-9 oraz ust. 3, organizator rodzinnej pieczy zastępczej,\nktóry pozytywnie wstępnie zakwalifikował kandydata do pełnienia funkcji rodziny\nzastępczej zawodowej, rodziny zastępczej niezawodowej lub prowadzenia \f– 53 –\nrodzinnego domu dziecka, stwierdza nieaktualność wydanego zaświadczenia\nkwalifikacyjnego i wykreśla kandydata niezwłocznie z rejestru, o którym mowa\nw art. 38d ust. 1 pkt 3, oraz zawiadamia go o tym pisemnie w postaci papierowej lub\nelektronicznej, podając jednocześnie uzasadnienie, z jednoczesnym pouczeniem\nstrony o przysługującym prawie wniesienia do sądu administracyjnego skargi na\nzasadach i w trybie określonych dla aktów lub czynności, o których mowa w art. 3 §\n2 pkt 4 ustawy z dnia 30 sierpnia 2002 r. - Prawo o postępowaniu przed sądami\nadministracyjnymi.”;\n48) art. 45a otrzymuje brzmienie:\n„Art. 45a. Kandydaci zakwalifikowani do pełnienia funkcji rodziny zastępczej\nzawodowej, rodziny zastępczej niezawodowej lub prowadzenia rodzinnego domu\ndziecka, rodziny zastępcze zawodowe, rodziny zastępcze niezawodowe, a także osoby\nprowadzące rodzinne domy dziecka, są obowiązani do przedstawiania, co 2 lata,\nodpowiednio organizatorowi rodzinnej pieczy zastępczej, który przeprowadził wstępną\nkwalifikację kandydata do pełnienia funkcji rodziny zastępczej lub prowadzenia\nrodzinnego domu dziecka, albo staroście powiatu właściwego, o którym mowa\nodpowiednio w art. 35b ust. 1-3, chyba że porozumienie, o którym mowa w art. 35b ust.\n4, stanowi inaczej:\n1) zaświadczenia lekarskiego o stanie zdrowia, wystawionego przez lekarza\npodstawowej opieki zdrowotnej w rozumieniu przepisów ustawy z dnia 27 października\n2017 r. o podstawowej opiece zdrowotnej;\n2) opinii o posiadaniu predyspozycji i motywacji do pełnienia funkcji rodziny\nzastępczej lub prowadzenia rodzinnego domu dziecka, wystawionej przez psychologa.”;\n49) po art. 45a dodaje się art. 45b w brzmieniu:\n„Art. 45b. 1. Kandydatowi do pełnienia funkcji rodziny zastępczej spokrewnionej,\norganizator rodzinnej pieczy zastępczej właściwy ze względu na miejsce zamieszkania\nkandydata, wydaje zaświadczenie kwalifikacyjne zawierające potwierdzenie spełniania\nwarunków, o których mowa w art. 7b ust. 1a i 1b oraz art. 42 ust. 1 pkt 1, 5,  7-9.\n2. W przypadku gdy kandydat do pełnienia funkcji rodziny zastępczej\nspokrewnionej przestanie spełniać warunki, o których mowa w art. 7b ust. 1a i 1b oraz\nart. 42 ust. 1 pkt 1-5, 7-9, organizator rodzinnej pieczy zastępczej, właściwy ze względu\nna miejsce zamieszkania rodziny zastępczej spokrewnionej, stwierdza nieaktualność\nwydanego zaświadczenia kwalifikacyjnego i wykreśla kandydata niezwłocznie z rejestru, \f– 54 –\no którym mowa w art. 38d ust. 1 pkt 3, oraz zawiadamia go o tym w formie pisemnej,\npodając uzasadnienie, oraz zawierając pouczeniem strony o przysługującym prawie\nwniesienia do sądu administracyjnego skargi na zasadach i w trybie określonych dla\naktów lub czynności, o których mowa w art. 3 § 2 pkt 4 ustawy z dnia 30 sierpnia 2002 r.\n- Prawo o postępowaniu przed sądami administracyjnymi.\n3. W przypadku odmowy wydania zaświadczenia kwalifikacyjnego, o którym mowa\nw ust. 1, organizator rodzinnej pieczy zastępczej, odmawia jego wydania w formie\npisemnej, z uzasadnieniem przyczyn odmowy lub wskazaniem obszarów wymagających\npoprawy, oraz zawierając pouczenie strony o przysługującym prawie wniesienia do sądu\nadministracyjnego skargi na zasadach i w trybie określonych dla aktów lub czynności, o\nktórych mowa w art. 3 § 2 pkt 4 ustawy z dnia 30 sierpnia 2002 r. - Prawo o postępowaniu\nprzed sądami administracyjnymi.\n4. W przypadku stwierdzenia nieaktualności wydanego zaświadczenia\nkwalifikacyjnego lub odmowy wydania zaświadczenia kwalifikacyjnego, o których mowa\nw ust. 2 i 3, organizator rodzinnej pieczy zastępczej informuje właściwy sąd.”;\n50) w art. 47:\na) w ust. 1 pkt 2 otrzymuje brzmienie:\n„2) przekazanie, nie później niż w dniu poprzedzającym dzień przyjęcia dziecka,\ndokumentacji, o której mowa w art. 38a ust. 1 pkt 3-11.”,\nb) ust. 2 otrzymuje brzmienie:\n„2. W przypadku umieszczenia w rodzinnej pieczy zastępczej dziecka\nwymagającego natychmiastowej pomocy lub umieszczenia dziecka w trybie art.\n12a ustawy z dnia 29 lipca 2005 r. o przeciwdziałaniu przemocy domowej\norganizator rodzinnej pieczy zastępczej przekazuje rodzinie zastępczej lub\nprowadzącemu rodzinny dom dziecka informacje, o których mowa w art. 38a ust. 1\npkt 1 i 2, oraz dokumentację, o której mowa w art. 38a ust. 1 pkt 3-11, niezwłocznie\npo przyjęciu dziecka.”,\nc) ust. 7 otrzymuje brzmienie:\n„7. W przypadku stwierdzenia braku możliwości powrotu dziecka do jego\nrodziny, organizator rodzinnej pieczy zastępczej składa do właściwego sądu wniosek\no pozbawienie władzy rodzicielskiej rodziców dziecka, chyba że władza ta już im\nnie przysługuje. Do wniosku organizator rodzinnej pieczy zastępczej dołącza w\nszczególności uzasadnienie, oraz odpowiednio opinię gminy lub podmiotu \f– 55 –\nprowadzącego pracę z rodziną, asystenta rodziny i opinię koordynatora rodzinnej\npieczy zastępczej.”,\nd) po ust. 7 dodaje się ust. 8 w brzmieniu:\n„8. W przypadku niestwierdzenia ustania przyczyny umieszczenia dziecka\nw rodzinie zastępczej lub rodzinnym domu dziecka, o której mowa w ust. 6 w\nterminie 12 miesięcy od dnia umieszczenia dziecka w pieczy zastępczej, organizator\nrodzinnej pieczy zastępczej składa do właściwego sądu wniosek, o którym mowa w\nust. 7, chyba że wniosek ten został już złożony.”;\n51) art. 48 otrzymuje brzmienie :\n„Art. 48. Minister właściwy do spraw rodziny określi, w drodze rozporządzenia,\nwzór zaświadczenia kwalifikacyjnego zawierającego potwierdzenie ukończenia\nszkolenia, spełniania warunków i posiadania predyspozycji do sprawowania pieczy\nzastępczej, mając na uwadze konieczność rzetelnej oceny predyspozycji kandydatów do\npełnienia funkcji:\n1) rodziny zastępczej spokrewnionej,\n2) rodziny zastępczej niezawodowej, zawodowej lub prowadzenia rodzinnego domu\ndziecka.”;\n52) art. 50 otrzymuje brzmienie:\n„1. W przypadku gdy wobec osoby pełniącej funkcję rodziny zastępczej\nniezawodowej, rodziny zastępczej zawodowej lub prowadzącego rodzinny dom dziecka\nwszczęto postępowanie karne o umyślne przestępstwo, o którym mowa w art. 7b ust. 1\npkt 2 lub o orzeczenie wobec niej zakazu, o którym mowa w art. 7b ust. 1 pkt 3 i 4, a także\njeżeli w stosunku do osoby wspólnie zamieszkującej wszczęto postępowanie karne o\numyślne przestępstwo, o którym mowa ust. 1a pkt 2 lub wszczęto postępowanie karne o\norzeczenie wobec niej zakazu, o którym mowa w art. 7b ust. 1a pkt 3 i 4, do czasu\nprawomocnego zakończenia postępowania starosta albo pozarządowy organizator\nrodzinnej pieczy zastępczej może odpowiednio:\n1) zapewnić dziecku pieczę w innej rodzinie zastępczej;\n2) wyznaczyć inną osobę, spełniającą warunki dla prowadzącego rodzinny dom\ndziecka, o których mowa w art. 7b ust. 1 i 1b oraz art. 42, i powierzyć jej prowadzenie\nrodzinnego domu dziecka, a gdy nie jest to możliwe, zapewnić dzieciom pieczę w rodzinie\nzastępczej lub innym rodzinnym domu dziecka.\f– 56 –\n2. Przepis ust. 1 stosuje się odpowiednio do rodziny zastępczej spokrewnionej, jeżeli\nwszczęto przeciwko niej  postępowanie karne o umyślne przestępstwo, o którym mowa\nw art. 7b ust. 1a pkt 2, a także wszczęto postępowanie karne o orzeczenie wobec niej\nzakazu, o którym mowa w art. 7b ust. 1a pkt 3 i 4, a także jeżeli w stosunku do osoby\nwspólnie zamieszkującej wszczęto postępowanie karne o umyślne przestępstwo, o którym\nmowa ust. 1a pkt 2, lub wszczęto postępowanie karne o orzeczenie wobec niej zakazu, o\nktórym mowa w art. 7b ust. 1a pkt 3 i 4.\n3. W przypadku gdy starosta albo pozarządowy organizator rodzinnej pieczy\nzastępczej zapewnił dziecku pieczę zastępczą w innej rodzinie zastępczej lub w\nrodzinnym domu dziecka albo powierzył innej osobie prowadzenie rodzinnego domu\ndziecka, przepisy art. 13 stosuje się odpowiednio.”;\n53) art. 52 otrzymuje brzmienie:\n„Art. 52. Minister właściwy do spraw rodziny określi, w drodze rozporządzenia,\nliczbę godzin szkoleń i zakres programowy szkoleń dla:\n1) kandydatów do pełnienia funkcji rodziny zastępczej zawodowej, rodziny\nzastępczej niezawodowej lub prowadzenia rodzinnego domu dziecka, w tym szkoleń\nuzupełniających;\n2) rodziny pomocowej;\n3) kandydatów na dyrektora placówki opiekuńczo-wychowawczej typu rodzinnego\n- biorąc pod uwagę możliwość umieszczenia w nich również dzieci o szczególnych\npotrzebach, w tym dzieci legitymujących się orzeczeniem o niepełnosprawności,\norzeczeniem o znacznym lub umiarkowanym stopniu niepełnosprawności, lub dzieci\nwobec których zastosowano środki wychowawcze na podstawie ustawy z dnia 9 czerwca\n2022 r. o wspieraniu i resocjalizacji nieletnich, a także biorąc pod uwagę specyfikę zadań\nopiekuńczo - wychowawczych dla poszczególnych form rodzinnej pieczy zastępczej oraz\nkonieczność zapewnienia odpowiedniego poziomu sprawowanej pieczy zastępczej.”;\n54) w art. 53:\na) ust. 1 otrzymuje brzmienie;\n„1. W rodzinie zastępczej zawodowej, w tym samym czasie, może przebywać\nłącznie nie więcej niż 4 dzieci, osób, które osiągnęły pełnoletność przebywając w\npieczy zastępczej, o których mowa w art. 37 ust. 2-4 i 6, oraz osób opuszczających\nrodzinną pieczę zastępczą jako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6.”,\f– 57 –\nb) po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. W rodzinie zastępczej niezawodowej, w tym samym czasie, może\nprzebywać łącznie nie więcej niż 3 dzieci, osób, które osiągnęły pełnoletność\nprzebywając w pieczy zastępczej, o których mowa w art. 37 ust. 2-4 i 6, oraz osób\nopuszczających rodzinną pieczę zastępczą jako niepełnoletnie, o których mowa\nw art. 37 ust. 5 i 6.”;\n55) po art. 53 dodaje się art. 53a i 53b w brzmieniu:\n„Art. 53a. 1. Z zastrzeżeniem ust. 3, rodzinę zastępczą niezawodową lub zawodową\norganizuje powiat lub podmiot, któremu powiat zlecił realizację tego zadania na\npodstawie art. 190.\n2. Rodzina zastępcza zawodowa lub niezawodowa może być organizowana na\nterenie powiatu innego niż powiat organizujący rodzinę zastępczą lub powiat, który zlecił\norganizację rodziny zastępczej niezawodowej lub zawodowej na podstawie art. 190.\n3. Rodzinę zastępczą niezawodową lub zawodową może organizować pozarządowy\norganizator rodzinnej pieczy zastępczej.\nArt. 53b. 1. W przypadku organizowania rodziny zastępczej niezawodowej, rodziny\nzastępczej zawodowej, rodzinnego domu dziecka, albo rodziny pomocowej przez\npozarządowego organizatora rodzinnej pieczy zastępczej, przepisy art. 88 ust. 2, 180 pkt\n2a, 4, 6, 7, 10-12, 14 stosuje się odpowiednio.\n2. W przypadku organizowania rodziny zastępczej niezawodowej, rodziny\nzastępczej zawodowej, rodzinnego domu dziecka, albo rodziny pomocowej przez\npozarządowego organizatora rodzinnej pieczy zastępczej  przepis art. 35b i art. 88 ust. 1 i\n3-6 nie stosuje się.\n3. Z kandydatami spełniającymi warunki do pełnienia funkcji rodziny zastępczej\nniezawodowej w zakresie szkoleń, o których mowa w art. 44 ust. 1, pozarządowy\norganizator rodzinnej pieczy zastępczej, który wydał kandydatowi zaświadczenie\nkwalifikacyjne, o którym mowa w art. 45 ust. 1, może zawrzeć umowę o współpracy.\n4. Do umowy, o której mowa w ust. 3, przepisy art. 55a ust. 2 pkt 1-7, 9-11, 13, 14,\nust. 5 pkt 1, 6, 8, 10-12, art. 71 ust. 2 stosuje się odpowiednio.\";\n56) w art. 54:\na) ust. 1 otrzymuje brzmienie:\n„1. Z rodziną zastępczą niezawodową spełniającą warunki do pełnienia funkcji\nrodziny zastępczej zawodowej w zakresie szkoleń, o których mowa odpowiednio w \f– 58 –\nart. 44 ust. 1, posiadającą opinię koordynatora rodzinnej pieczy zastępczej oraz co\nnajmniej 3-letnie doświadczenie jako rodzina zastępcza, prowadzący rodzinny dom\ndziecka lub pełniący funkcję dyrektora placówki opiekuńczo-wychowawczej typu\nrodzinnego, starosta lub podmiot, któremu powiat zlecił realizację tego zadania na\npodstawie art. 190, albo pozarządowy organizator rodzinnej pieczy zastępczej,\nzawiera na jej wniosek, umowę rodzicielstwa zastępczego, o której mowa w art. 55a\nust. 1, w zakresie pełnienia funkcji rodziny zastępczej zawodowej.”,\nb) po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Z rodziną zastępczą niezawodową spełniającą warunki do pełnienia funkcji\nrodziny zastępczej zawodowej w zakresie szkoleń, o których mowa odpowiednio w\nart. 44 ust. 1, posiadającą opinię koordynatora rodzinnej pieczy zastępczej,\nwychowującą co najmniej 4 dzieci, starosta lub podmiot, któremu powiat zlecił\nwykonywanie tego zadania na podstawie art. 190 albo pozarządowy organizator\nrodzinnej pieczy zastępczej, zawiera na wniosek tej rodziny, umowę rodzicielstwa\nzastępczego, o której mowa w art. 55a ust. 1, w zakresie pełnienia funkcji rodziny\nzastępczej zawodowej.”,\nc) ust. 2 otrzymuje brzmienie:\n„2. Z rodziną zastępczą niezawodową spełniającą warunki do pełnienia funkcji\nrodziny zastępczej zawodowej w zakresie szkoleń, o których mowa w art. 44 ust. 1,\nposiadającą pozytywną opinię koordynatora rodzinnej pieczy zastępczej, starosta lub\npodmiot, któremu powiat zlecił wykonywanie tego zadania na podstawie art. 190\nalbo pozarządowy organizator rodzinnej pieczy zastępczej, może zawrzeć, na jej\nwniosek, umowę rodzicielstwa zastępczego, o której mowa w art. 55a ust. 1, w\nzakresie pełnienia funkcji rodziny zastępczej zawodowej.”,\nd) uchyla się ust. 3-7a;\ne) ust. 7b otrzymuje brzmienie:\n„7b. W przypadku odmowy zawarcia przez starostę albo pozarządowego\norganizatora rodzinnej pieczy zastępczej, umowy, o której mowa w ust. 2, odmowa\nta wydawana jest w formie pisemnej, ze szczegółowym uzasadnieniem przyczyn\nodmowy.”,\nf) uchyla się ust. 8;\f– 59 –\n57) w art. 55:\na) ust. 1 i 1a otrzymują brzmienie:\n„1. Z kandydatami spełniającymi warunki do pełnienia funkcji rodziny\nzastępczej zawodowej lub prowadzenia rodzinnego domu dziecka w zakresie\nszkoleń, o których mowa w art. 44 ust. 1, na ich wniosek, starosta lub podmiot,\nktóremu powiat zlecił realizację tego zadania na podstawie art. 190, albo\npozarządowy organizator rodzinnej pieczy zastępczej, może zawrzeć umowę\nrodzicielstwa zastępczego, o której mowa w art. 55a ust. 1, w zakresie w zakresie\nodpowiednio pełnienia funkcji rodziny zastępczej zawodowej albo prowadzenia\nrodzinnego domu dziecka.\n1a. Kandydat spełniający warunki do pełnienia funkcji rodziny zastępczej\nzawodowej lub prowadzenia rodzinnego domu dziecka w zakresie szkoleń, o których\nmowa w art. 44 ust. 1, składa wniosek, o którym mowa w ust. 1, odpowiednio do:\n1) starosty powiatu, którego organizator rodzinnej pieczy zastępczej wydał mu\nzaświadczenie kwalifikacyjne, o którym mowa w art. 45 ust. 1, lub podmiotu,\nktóremu ten powiat zlecił realizację tego zadania na podstawie art. 190, albo\n2) pozarządowego organizatora rodzinnej pieczy zastępczej, który wydał mu\nzaświadczenie kwalifikacyjne, o którym mowa w art. 45 ust. 1,”,\nb) po ust. 1a dodajemy ust. 1aa i ust. 1ab w brzmieniu:\n„1aa. Pierwsza umowa rodzicielstwa zastępczego z kandydatem spełniającym\nwarunki do pełnienia funkcji rodziny zastępczej zawodowej lub prowadzenia\nrodzinnego domu dziecka może być zawarta na czas określony nie dłuższy niż 24\nmiesiące, z terminem wypowiedzenia umowy nie krótszym niż 2 tygodnie.\n1ab. Umowa rodzicielstwa zastępczego zawierana z rodziną zastępczą, która\npełniła funkcje na podstawie umowy na czas określony, zawierana jest na czas\nnieokreślony.”,\nc) ust. 1b otrzymuje brzmienie:\n„1b. W przypadku gdy:\n1) starosta powiatu, o którym mowa w ust. 1a, lub podmiot, któremu ten powiat\nzleci realizację tego zadania na podstawie art. 190 albo\n2) pozarządowy organizator rodzinnej pieczy zastępczej, o którym mowa w ust.\n1a,\f– 60 –\n- nie zawarł z kandydatem do pełnienia funkcji rodziny zastępczej zawodowej\nlub prowadzenia rodzinnego domu dziecka, w terminie miesiąca od dnia złożenia\nwniosku, o którym mowa w ust. 1, umowy rodzicielstwa zastępczego, kandydat\nspełniający warunki do pełnienia funkcji rodziny zastępczej zawodowej lub\nprowadzenia rodzinnego domu dziecka może złożyć wniosek w tym zakresie do\ninnego starosty lub podmiotu, któremu inny starosta zlecił realizację tego zadania na\npodstawie art. 190, albo do innego pozarządowego organizatora rodzinnej pieczy\nzastępczej.”;\n58) po art. 55 dodaje się art. 55a w brzmieniu:\n„Art. 55a. 1. Praca rodziny zastępczej zawodowej i prowadzącego rodzinny dom\ndziecka jest wykonywana na podstawie umowy rodzicielstwa zastępczego.\n2. Umowa rodzicielstwa zastępczego określa w szczególności:\n1) strony umowy;\n2) cel i przedmiot umowy;\n3) miejsce sprawowania pieczy zastępczej;\n4) sposób i zakres finansowania pieczy zastępczej ze wskazaniem wysokości\nśrodków przeznaczonych na poszczególne cele;\n5) liczbę dzieci powierzonych odpowiednio rodzinie zastępczej albo prowadzącemu\nrodzinny dom dziecka;\n6) maksymalną liczbę dzieci, które można umieścić w tej rodzinie zastępczej albo\ndanym rodzinnym domu dziecka;\n7) gotowość do sprawowania pieczy zastępczej nad małoletnim umieszczonym w\npieczy zastępczej na podstawie orzeczenia sądu lub innego organu państwa obcego za\nzgodą sądu polskiego, lub legitymującym się orzeczeniem o niepełnosprawności albo\norzeczeniem o umiarkowanym lub znacznym stopniu niepełnosprawności, lub\nmałoletnimi matką lub ojcem z dzieckiem;\n8) wysokość wynagrodzenia przysługującego rodzinie zastępczej albo\nprowadzącemu rodzinny dom dziecka oraz sposób wypłaty;\n9) tryb i sposób korzystania ze szkoleń i innych form podnoszenia kwalifikacji przez\nrodzinę zastępczą albo prowadzącego rodzinny dom dziecka;\n10) zakres niezbędnej pomocy w razie choroby rodziny zastępczej albo\nprowadzącego rodzinny dom dziecka, lub problemów z powierzonymi dziećmi;\f– 61 –\n11) warunki czasowego niesprawowania opieki nad dzieckiem, w szczególności\nzwiązanego z wypoczynkiem;\n12) zasady wypłaty środków finansowych, o których mowa w art. 83 ust. 3a lub art.\n84 pkt 1;\n13) uprawnienia i obowiązki w zakresie bieżącej kontroli wykonywania umowy;\n14) warunki i sposób zmiany oraz rozwiązania umowy.\n3. Umowa rodzicielstwa zastępczego zawierana z rodziną zastępczą zawodową\nokreśla dodatkowo gotowość do pełnienia funkcji pogotowia rodzinnego lub rodziny\nzastępczej zawodowej specjalistycznej sprawującej pieczę zastępczą nad dzieckiem\numieszczonym na podstawie ustawy z dnia 9 czerwca 2022 r. o wspieraniu i resocjalizacji\nnieletnich.\n4. Umowa rodzicielstwa zastępczego zawierana z prowadzącym rodzinny dom\ndziecka określa dodatkowo:\n1) zasady kalkulacji i przyznawania wysokość środków finansowych na pokrycie\nniezbędnych kosztów związanych z remontem lub ze zmianą lokalu w budynku\nwielorodzinnym lub domu jednorodzinnego, w którym ma być prowadzony rodzinny dom\ndziecka, o których mowa w art. 84 pkt 2;\n2) wysokość środków finansowych na pokrycie innych niezbędnych\ni nieprzewidzianych kosztów związanych z opieką i wychowaniem dziecka lub\nfunkcjonowaniem rodzinnego domu dziecka o których mowa w art. 84 pkt 3.\n5. Umowa rodzicielstwa zastępczego może dodatkowo określać:\n1) zasady przyznawania:\na) dofinansowania do wypoczynku poza miejscem zamieszkania dziecka,\nb) świadczeń albo środków finansowych na pokrycie niezbędnych kosztów\nzwiązanych z potrzebami przyjmowanego dziecka,\nc)świadczeń na pokrycie kosztów związanych z wystąpieniem zdarzeń losowych\nlub innych zdarzeń mających wpływ na jakość sprawowanej opieki,\nd) dofinansowania kosztów związanych z leasingiem lub kredytem na zakup\nsamochodu związanego z potrzebami rodziny zastępczej lub rodzinnego domu\ndziecka.\n2) zasady przyznawania rodzinie zastępczej zawodowej środków finansowych na\nutrzymanie lokalu mieszkalnego w budynku wielorodzinnym lub domu\njednorodzinnego, o których mowa w art. 83 ust. 2 lub świadczeń na pokrycie \f– 62 –\nkosztów związanych z przeprowadzeniem niezbędnego remontu lokalu\nmieszkalnego w budynku wielorodzinnym lub domu jednorodzinnego, , o których\nmowa w art. 83 ust. 4.\n6. Umowa rodzicielstwa zastępczego zawierana przez pozarządowego organizatora\nrodzinnej pieczy zastępczej, zawiera dodatkowo określenie wysokości świadczeń\nprzeznaczonych na pokrycie kosztów utrzymania dziecka oraz dodatków na pokrycie\nzwiększonych kosztów utrzymania dziecka legitymującego się orzeczeniem o\nniepełnosprawności lub orzeczeniem o znacznym lub umiarkowanym stopniu\nniepełnosprawności lub umieszczonego na podstawie ustawy z dnia 9 czerwca 2022 r. o\nwspieraniu i resocjalizacji nieletnich.\n7. Starosta powiatu może upoważnić pracownika urzędu lub innej jednostki\norganizacyjnej powiatu do zawierania i rozwiązywania umów rodzicielstwa zastępczego.\n8. Umowę rodzicielstwa zastępczego zawiera się na czas nieokreślony z terminem\nwypowiedzenia umowy nie krótszym niż 3 miesiące.\n9. Jeżeli umowę rodzicielstwa zastępczego zawierają małżonkowie, wynagrodzenie\nprzysługuje małżonkowi wskazanemu w umowie.\n10. Umowa rodzicielstwa zastępczego ulega rozwiązaniu, w przypadku gdy rodzina\nzastępcza zawodowa lub prowadzący rodzinny dom dziecka zmieni miejsce sprawowania\npieczy zastępczej, opuszczając terytorium Rzeczypospolitej Polskiej lub powiat miejsca\nzamieszkania, chyba że:\n1) starosta lub podmiot, któremu powiat zlecił wykonywanie tego zadania na\npodstawie art. 190 albo pozarządowy organizator rodzinnej pieczy zastępczej, który\npodpisał z rodziną zastępczą lub prowadzącym rodzinny dom dziecka umowę\nrodzicielstwa zastępczego, postanowi inaczej lub\n2) zmiana miejsca sprawowania pieczy zastępczej jest związana z wyjazdem\nwakacyjnym.\n11. W zakresie nieuregulowanym ustawą do umowy mają zastosowanie przepisy\nustawy z dnia 23 kwietnia 1964 r. - Kodeks cywilny dotyczące umowy zlecenia.”;\n59) art. 56 otrzymuje brzmienie:\n„Art. 56. Umowy, o których mowa w art. 54 ust. 1 i 2, zawierane przez starostę lub\npodmiot, któremu powiat zlecił wykonywanie tego zadania na podstawie art. 190, zawiera\nsię w ramach limitu rodzin zastępczych zawodowych na dany rok kalendarzowy, \f– 63 –\nokreślonego w 3-letnim powiatowym programie dotyczącym rozwoju pieczy\nzastępczej.”;\n60) w art. 57 ust. 1a - 4 otrzymują brzmienie:\n„1a. W przypadku gdy w rodzinie zastępczej przebywa więcej niż 3 dzieci, na\nwniosek rodziny zastępczej, zatrudnia się osobę do pomocy przy sprawowaniu opieki nad\ndziećmi i przy pracach gospodarskich. Przepisy art. 64 ust. 3-6 stosuje się.\n2. W uzasadnionych przypadkach, na wniosek rodziny zastępczej, odpowiednio\nstarosta lub podmiot, któremu powiat zlecił realizacje tego zadania na podstawie art. 190,\nalbo pozarządowy organizator rodzinnej pieczy zastępczej, może zatrudnić osobę do\npomocy przy sprawowaniu opieki nad dziećmi i przy pracach gospodarskich. Przepisy art.\n64 ust. 3-6 stosuje się odpowiednio.\n3. Osobą zatrudnioną do pomocy przy sprawowaniu opieki nad dziećmi i przy\npracach gospodarskich może być także małżonek niepobierający wynagrodzenia z\ntytułu umowy rodzicielstwa zastępczego.\n4. Starosta może upoważnić pracownika urzędu lub innej jednostki organizacyjnej\npowiatu do zawierania i rozwiązywania umów z osobami do pomocy przy sprawowaniu\nopieki nad dziećmi i przy pracach gospodarskich.”;\n61) w art. 58 w ust. 1 pkt 2 otrzymuje brzmienie:\n„2) doprowadzone przez Policję lub Straż Graniczną, w sytuacji braku możliwości\nzapewnienia mu opieki ze strony rodziców;”.\n62) w art. 60:\na) ust. 1 otrzymuje brzmienie:\n„1. Z zastrzeżeniem ust. 2a, rodzinny dom dziecka organizuje powiat lub\npodmiot, któremu powiat zlecił realizację tego zadania na podstawie art. 190.”,\nb) po ust. 2 dodaje się ust. 2a w brzmieniu:\n„2a. Rodzinny dom dziecka może organizować pozarządowy organizator\nrodzinnej pieczy zastępczej.”,\nc) uchyla się ust. 3-5;\n63) art. 61a otrzymuje brzmienie:\n„Art. 61a. 1. Z rodziną zastępczą zawodową, w której wychowuje się co najmniej 6\ndzieci, spełniającą warunki do prowadzenia rodzinnego domu dziecka w zakresie szkoleń,\no których mowa w art. 44 ust. 1, starosta lub podmiot, któremu powiat zlecił realizację\ntego zadania na podstawie art. 190, albo pozarządowy organizator rodzinnej pieczy \f– 64 –\nzastępczej, zawiera na jej wniosek, umowę rodzicielstwa zastępczego, o której mowa w\nart. 55a ust. 1, w zakresie prowadzenia rodzinnego domu dziecka.\n2. Z rodziną zastępczą niezawodową lub zawodową spełniającą warunki\ndo prowadzenia rodzinnego domu dziecka w zakresie szkoleń, o których mowa w art. 44\nust. 1, starosta lub podmiot, któremu powiat zlecił realizację tego zadania na podstawie\nart. 190 albo pozarządowy organizator rodzinnej pieczy zastępczej, może zawrzeć, na\nwniosek tej rodziny, umowę rodzicielstwa, o której mowa w art. 55a ust. 1, w zakresie\nprowadzenia rodzinnego domu dziecka.\n3. W przypadku odmowy zawarcia przez starostę albo pozarządowego organizatora\nrodzinnej pieczy zastępczej, umowy w sytuacji, o której mowa w ust. 2, odmowa ta\nwydawana jest w formie pisemnej, ze szczegółowym uzasadnieniem przyczyn odmowy.”;\n64) uchyla się art. 62;\n65) w art. 64:\na) ust. 1 i 2 otrzymują brzmienie:\n„1. Odpowiednio starosta organizujący rodzinny dom dziecka, podmiot,\nktóremu powiat zlecił realizacje tego zadania na podstawie art. 190, albo\npozarządowy organizator rodzinnej pieczy zastępczej, w uzasadnionych\nprzypadkach, na wniosek prowadzącego rodzinny dom dziecka może zatrudnić\nosobę do pomocy przy sprawowaniu opieki nad dziećmi i przy pracach\ngospodarskich.\n2. W rodzinnym domu dziecka, w którym przebywa więcej niż 4 dzieci,\nodpowiednio starosta organizujący rodzinny dom dziecka, podmiot, któremu powiat\nzlecił realizacje tego zadania na podstawie art. 190 albo pozarządowy organizator\nrodzinnej pieczy zastępczej, na wniosek prowadzącego rodzinny dom dziecka,\nzatrudnia osobę do pomocy przy sprawowaniu opieki nad dziećmi i przy pracach\ngospodarskich.”,\nb) w ust. 5 uchyla się pkt 3 i 4,\nc) ust. 5a i 5b otrzymują brzmienie:\n„5a. Osobą zatrudnioną do pomocy przy sprawowaniu opieki nad dziećmi i przy\npracach gospodarskich może być także małżonek niepobierający wynagrodzenia z\ntytułu umowy rodzicielstwa zastępczego.\f– 65 –\n5b. Starosta może upoważnić pracownika urzędu lub innej jednostki\norganizacyjnej powiatu do zawierania i rozwiązywania umów z osobami do pomocy\nprzy sprawowaniu opieki nad dziećmi i przy pracach gospodarskich.”;\n66) art. 66 otrzymuje brzmienie:\n„Art. 66. 1. Przy zapewnianiu pieczy i wychowania dzieciom umieszczonym w\nrodzinie zastępczej, rodzinnym domu dziecka lub rodzinie pomocowej oraz\nwykonywaniu innych czynności związanych z realizacją zadań rodziny zastępczej,\nrodzinnego domu dziecka lub rodziny pomocowej, rodzina zastępcza, prowadzący\nrodzinny dom dziecka oraz rodzina pomocowa mogą korzystać z pomocy\nwolontariuszy, organizowanej przez organizatora rodzinnej pieczy zastępczej.\nPrzepisy art. 64 ust. 5 stosuje się odpowiednio.\n2. O potrzebie skorzystania z pomocy, o której mowa w ust. 1, rodzina\nzastępcza, prowadzący rodzinny dom dziecka lub rodzina pomocowa informuje\nwłaściwego organizatora rodzinnej pieczy zastępczej.”;\n67) w art. 67:\na) ust. 2 otrzymuje brzmienie:\n„2. W przypadku połączenia funkcji rodziny zastępczej spokrewnionej z\nfunkcją rodziny zastępczej zawodowej w rodzinie tej nie może przebywać więcej\nniż 4 dzieci, osób, które osiągnęły pełnoletność przebywając w pieczy zastępczej, o\nktórych mowa w art. 37 ust. 2-4 i 6, oraz osób opuszczających rodzinną pieczę\nzastępczą jako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6. W razie\nkonieczności umieszczenia w takiej rodzinie rodzeństwa, za zgodą tej rodziny oraz\npo uzyskaniu pozytywnej opinii koordynatora rodzinnej pieczy zastępczej, jest\ndopuszczalne umieszczenie w tym samym czasie większej liczby dzieci.”,\nb) po ust. 2 dodaje się ust. 2a brzmieniu:\n„2a. W przypadku połączenia funkcji rodziny zastępczej spokrewnionej z\nfunkcją rodziny zastępczej niezawodowej w tej rodzinie nie może przebywać więcej\nniż 3 dzieci, osób, które osiągnęły pełnoletność przebywając w pieczy zastępczej, o\nktórych mowa w art. 37 ust. 2-4 i 6, oraz osób opuszczających rodzinną pieczę\nzastępczą jako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6. W razie\nkonieczności umieszczenia w takiej rodzinie rodzeństwa, za zgodą tej rodziny oraz\npo uzyskaniu pozytywnej opinii koordynatora rodzinnej pieczy zastępczej, jest\ndopuszczalne umieszczenie w tym samym czasie większej liczby dzieci.”,\f– 66 –\nc) po ust. 3 dodaje się ust. 4-7 w brzmieniu:\n„4. Pełnienie funkcji rodziny zastępczej, z wyjątkiem rodziny zastępczej\nzawodowej pełniącej funkcję pogotowia rodzinnego lub prowadzenie rodzinnego\ndomu dziecka może być łączone z pełnieniem funkcji rodziny opiekuńczej.\n5. W przypadku połączenia funkcji rodziny zastępczej niezawodowej z\npełnieniem funkcji rodziny opiekuńczej piecza zastępcza lub opieka może być\nsprawowana nad nie więcej niż 3 dzieci lub osób, które osiągnęły pełnoletność\nprzebywając w pieczy zastępczej, o których mowa w art. 37 ust. 2-4 i 6, osób\nopuszczających rodzinną pieczę zastępczą jako niepełnoletnie, o których mowa w\nart. 37 ust. 5 i 6, oraz osób przebywających w rodzinie opiekuńczej. W przypadku\nkonieczności objęcia opieką rodzeństwa, za zgodą tej rodziny oraz po uzyskaniu\npozytywnej opinii koordynatora rodzinnej pieczy zastępczej oraz odpowiednio wójta\nlub podmiotu o których mowa w art. 31b ust. 1, dopuszczalne jest przebywanie w\ntym samym czasie większej liczby odpowiednio dzieci lub osób, które osiągnęły\npełnoletność przebywając w pieczy zastępczej, o których mowa w art. 37 ust. 2-4 i\n6, osób opuszczających rodzinną pieczę zastępczą jako niepełnoletnie, o których\nmowa w art. 37 ust. 5 i 6, oraz osób przebywających w rodzinie opiekuńczej.\n6. W przypadku połączenia funkcji rodziny zastępczej zawodowej z pełnieniem\nfunkcji rodziny opiekuńczej piecza zastępcza lub opieka może być sprawowana nad\nnie więcej niż 4 dzieci lub osób, które osiągnęły pełnoletność przebywając w pieczy\nzastępczej, o których mowa w art. 37 ust. 2-4 i 6, osób opuszczających rodzinną\npieczę zastępczą jako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6, oraz osób\nprzebywających w rodzinie opiekuńczej. W przypadku konieczności objęcia opieką\nrodzeństwa, za zgodą tej rodziny oraz po uzyskaniu pozytywnej opinii koordynatora\nrodzinnej pieczy zastępczej oraz odpowiednio wójta lub podmiotu o których mowa\nw art. 31b ust. 1, dopuszczalne jest przebywanie w tym samym czasie większej liczby\nodpowiednio dzieci lub osób, które osiągnęły pełnoletność przebywając w pieczy\nzastępczej, o których mowa w art. 37 ust. 2-4 i 6, osób opuszczających rodzinną\npieczę zastępczą jako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6, oraz osób\nprzebywających w rodzinie opiekuńczej.\n7. W przypadku połączenia prowadzenia rodzinnego domu dziecka z\npełnieniem funkcji rodziny opiekuńczej, piecza zastępcza lub opieka może być\nsprawowana nad nie więcej niż 8 dzieci lub osób, które osiągnęły pełnoletność \f– 67 –\nprzebywając w pieczy zastępczej, o których mowa w art. 37 ust. 2-4 i 6, osób\nopuszczających rodzinną pieczę zastępczą jako niepełnoletnie, o których mowa w\nart. 37 ust. 5 i 6, oraz osób przebywających w rodzinie opiekuńczej. W przypadku\nkonieczności objęcia opieką rodzeństwa, za zgodą prowadzącego rodzinny dom\ndziecka oraz po uzyskaniu pozytywnej opinii koordynatora rodzinnej pieczy\nzastępczej oraz odpowiednio wójta, lub podmiotu o których mowa w art. 31b ust. 1,\ndopuszczalne jest przebywanie w tym samym czasie większej liczby odpowiednio\ndzieci lub osób, które osiągnęły pełnoletność przebywając w pieczy zastępczej, o\nktórych mowa w art. 37 ust. 2-4 i 6, osób opuszczających rodzinną pieczę zastępczą\njako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6, oraz osób przebywających\nw rodzinie opiekuńczej.”;\n68) w art. 69 po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Niewykorzystane w danym roku kalendarzowym dni czasowego\nniesprawowania opieki nad dzieckiem w związku z wypoczynkiem rodzina zastępcza\nzawodowa albo prowadzący rodzinny dom dziecka mają prawo wykorzystać najpóźniej\ndo dnia 30 września następnego roku kalendarzowego.”;\n69) art. 70 otrzymuje brzmienie\n„Art. 70. 1. Osoba, której przysługuje wynagrodzenie z tytułu pełnienia funkcji\nrodziny zastępczej zawodowej lub prowadzenia rodzinnego domu dziecka, może\nkontynuować lub podjąć dodatkowe zatrudnienie lub inną pracę zarobkową po uzyskaniu\nzgody odpowiednio właściwego starosty albo pozarządowego organizatora rodzinnej\npieczy zastępczej.\n2. Odpowiednio starosta, po zasięgnięciu opinii organizatora rodzinnej pieczy\nzastępczej albo pozarządowy organizator rodzinnej pieczy zastępczej, może odmówić\nudzielenia zgody, o której mowa w ust. 1, w przypadku gdy charakter i specyfika\nwykonywanej pracy będzie miała negatywny wpływ na sprawowanie pieczy zastępczej.\nOdmowa udzielenia zgody wymaga pisemnego uzasadnienia.\n3. Starosta może upoważnić pracownika urzędu lub innej jednostki organizacyjnej\npowiatu do udzielania zgody, o której mowa w ust. 1.”;\n70) art. 71 otrzymuje brzmienie:\n„Art. 71. 1. W przypadku gdy rodzina zastępcza lub prowadzący rodzinny dom\ndziecka nie wypełnia swoich funkcji lub wypełnia je niewłaściwie, odpowiednio starosta \f– 68 –\nlub podmiot, któremu powiat zlecił realizację tego zadania na podstawie art. 190, albo\npozarządowy organizator rodzinnej pieczy zastępczej, zawiadamia właściwy sąd.\n2. W przypadku gdy sąd zmieni orzeczenie o umieszczeniu dziecka w rodzinie\nzastępczej zawodowej lub rodzinnym domu dziecka z przyczyn, o których mowa w ust.\n1, starosta lub podmiot, któremu powiat zlecił realizację tego zadania na podstawie art.\n190, albo pozarządowy organizator rodzinnej pieczy zastępczej może rozwiązać z tą\nrodziną zastępczą lub z osobą prowadzącą rodzinny dom dziecka umowę rodzicielstwa\nzastępczego, bez zachowania terminu wypowiedzenia.\n3. Wraz z zawiadomieniem, o którym mowa w ust. 1, odpowiednio powiatowe\ncentrum pomocy rodzinie albo pozarządowy organizator rodzinnej pieczy zastępczej,\ninformuje sąd o rodzinach zastępczych i rodzinnych domach dziecka, w których można\numieścić dziecko, o osobach spełniających warunki do pełnienia funkcji rodziny\nzastępczej lub prowadzenia rodzinnego domu dziecka.\n4. Do czasu ponownego umieszczenia dziecka w pieczy zastępczej, starosta powiatu\nwłaściwego, o którym mowa w art. 35b ust. 1-3 chyba że porozumienie, o którym mowa\nw art. 35b ust. 4, stanowi inaczej albo pozarządowy organizator rodzinnej pieczy\nzastępczej ma obowiązek zapewnienia dziecku opieki i wychowania.”;\n71) art. 72 otrzymuje brzmienie:\n„Art. 72. W przypadku przeniesienia dziecka do innej rodziny zastępczej lub\nrodzinnego domu dziecka dotychczasowa rodzina zastępcza lub osoba prowadząca\nrodzinny dom dziecka, za pośrednictwem organizatora rodzinnej pieczy zastępczej,\nprzekazuje, nie później niż w dniu przeniesienia dziecka, osobie sprawującej pieczę\nzastępczą dokumentację, o której mowa w art. 38a ust. 1 pkt 3-11. Przepisy art. 47 ust. 2\ni 3 stosuje się odpowiednio.”;\n72) w art. 73 po ust 2 dodaje się ust. 3 i 4 w brzmieniu:\n„3. Z zastrzeżeniem ust. 4, rodzinę pomocową organizuje powiat lub podmiot,\nktóremu powiat zlecił realizację tego zadania na podstawie art. 190.\n4. Rodzinę pomocową może organizować pozarządowy organizator rodzinnej\npieczy zastępczej.”;\n73) w art. 74:\na) w ust. 1 po pkt 2 kropkę zastępuje się średnikiem i dodaje się pkt 3-6 w brzmieniu:\n„3) osoby spokrewnione lub spowinowacone z osobami pełniącymi funkcję rodziny\nzastępczej lub osobą prowadzącą rodzinny dom dziecka;\f– 69 –\n4) osoby zatrudnione w rodzinie zastępczej lub rodzinnym domu dziecka jako osoby\ndo pomocy przy sprawowaniu opieki nad dziećmi i przy pracach\ngospodarskich, o których mowa w art. 57 ust. 1 i art. 64 ust. 1 i 2;\n5) wolontariusze zapewniający pomoc przy sprawowaniu pieczy i wychowaniu\ndzieci umieszczonych w rodzinie zastępczej lub rodzinnym domu dziecka, o\nktórych mowa w art. 66 ust 1.”,\nb) po ust. 1 dodaje się ust. 1a i 1b w brzmieniu:\n„1a. Rodzinę pomocową może utworzyć jeden z małżonków osób, o których\nmowa w ust. 1 pkt 1 i 2, jeżeli małżonkowie nie zamieszkują razem.\n1b. Rodzina pomocowa może zostać utworzona przez osoby, o których mowa\nw ust. 1 pkt 2 i 3, jeżeli osoby te spełniają warunki, o których mowa w art. 7b ust. 1\ni 1b oraz art. 42 ust. 1 pkt 1 - 4 .”;\n74) w art. 75:\na) ust. 1 otrzymuje brzmienie:\n„1. Podstawą umieszczenia dziecka w rodzinie pomocowej jest umowa\nzawierana między starostą, podmiotem, któremu powiat zlecił realizację tego\nzadania na podstawie art. 190, albo pozarządowym organizatorem rodzinnej pieczy\nzastępczej, a rodziną pomocową.”,\nb) w ust. 2 pkt 8 otrzymuje brzmienie:\n„8) uprawnienia i obowiązki odpowiednio starosty, podmiotu, któremu powiat zlecił\nrealizację tego zadania na podstawie art. 190, albo pozarządowego organizatora\nrodzinnej pieczy zastępczej, w zakresie bieżącej kontroli wykonywania\numowy;”,\nc) ust. 3 i 3a otrzymują brzmienie:\n„3. O zawartej umowie odpowiednio starosta, podmiot, któremu powiat zlecił\nrealizację tego zadania na podstawie art. 190, albo pozarządowy organizator\nrodzinnej pieczy zastępczej, zawiadamia niezwłocznie sąd.\n3a. Starosta może upoważnić pracownika urzędu lub innej jednostki\norganizacyjnej powiatu do zawierania i rozwiązywania umów, o których mowa w\nust. 2, oraz do powiadamiania sądu o zawartej umowie.”;\f– 70 –\n75) w art. 76:\na) ust. 1 otrzymuje brzmienie:\n„1. Organizatorem rodzinnej pieczy zastępczej jest jednostka organizacyjna\npowiatu, podmiot, któremu powiat zlecił realizację tego zadania na podstawie art.\n190 albo pozarządowy organizator rodzinnej pieczy zastępczej.”,\nb) w ust. 4:\n- pkt 8 otrzymuje brzmienie:\n„8) współpraca ze środowiskiem lokalnym, w szczególności z powiatowym\ncentrum pomocy rodzinie, ośrodkiem pomocy społecznej, centrum usług\nspołecznych, sądami i ich organami pomocniczymi, instytucjami\noświatowymi, podmiotami leczniczymi, a także organizacjami\npozarządowymi lub podmiotami, o którym mowa w art. 3 ust. 3 ustawy z\ndnia 24 kwietnia 2003 r. o działalności pożytku publicznego i\nwolontariacie;”,\n- pkt 10 otrzymuje brzmienie:\n„10) zapewnianie pomocy prawnej osobom sprawującym rodzinną pieczę\nzastępczą, w szczególności:\na) w zakresie prawa rodzinnego, w tym w sprawach dotyczących kontaktów z\nrodzicami dzieci nad którymi sprawują pieczę zastępczą,\nb) w sytuacjach zagrażających bezpieczeństwu tych osób, ich dzieci oraz dzieci\nznajdujących się pod ich opieką,\nc) w sytuacjach naruszania ich dóbr osobistych lub majątkowych przez rodziców\ndzieci nad którymi sprawują pieczę zastępczą.”,\n- po pkt 10 dodaje się pkt 10a w brzmieniu:\n„10a) zapewnienie miejsca spotkań do kontaktów dzieci znajdujących się w\npieczy zastępczej z rodziną;”,\n- po pkt 11 dodaje się pkt 11a w brzmieniu:\n„11a) koordynowanie współpracy, w szczególności pomiędzy, rodziną\nzastępczą, prowadzącym rodzinny dom dziecka, dyrektorem placówki\nopiekuńczo-wychowawczej, dyrektorem regionalnej placówki opiekuńczo-\nterapeutycznej, dyrektorem instytucji, o których mowa w art. 87 ust. 2, lub\nrodzicem dziecka w zakresie przejścia dziecka lub osoby, o której mowa\nw art. 37 ust. 2-6, odpowiednio z rodzinnej pieczy zastępczej do \f– 71 –\ninstytucjonalnej pieczy zastępczej, powrotu dziecka z rodzinnej pieczy\nzastępczej do rodziny, zmiany rodziny zastępczej lub rodzinnego domu\ndziecka, w którym dziecko lub osoba, o której mowa w art. 37 ust. 2-6,\nprzebywa lub umieszczenia dziecka lub osoby, o której mowa w art. 37 ust.\n2-6, w instytucjach, o których mowa w art. 87 ust. 2.”,\n- pkt 15 otrzymuje brzmienie:\n„15)  przedstawienie corocznego sprawozdania z efektów pracy zarządowi i\nradzie powiatu, a w przypadku pozarządowego organizatora rodzinnej\npieczy zastępczej - wojewodzie i ministrowi właściwemu do spraw\nrodziny;”,\n- po pkt 16 dodaje się pkt 16a w brzmieniu:\n„16a) współpraca z ośrodkiem adopcyjnym w zakresie objęcia opieką dziecka\nprzez kandydatów do przysposobienia dziecka lub przez\nprzysposabiających;”;\n- po pkt 18 dodaje się pkt 19 i 20 w brzmieniu:\n„19) organizowanie rodzin zastępczych niezawodowych, rodzin zastępczych\nzawodowych, rodzinnych domów dziecka;\n20) wydawanie zaświadczeń potwierdzających przebywanie dziecka w rodzinie\nzastępczej lub rodzinnym domu dziecka umożliwiających skorzystanie z\nuprawnień wynikających z przepisów odrębnych.”;\n76) po art. 76 dodaje się art. 76a - 76c w brzmieniu:\n„Art. 76a. 1. W przypadku:\n1) gdy powiat w ciągu dwóch tygodni nie zrealizuje rozstrzygnięcia sądu w\nprzedmiocie umieszczenia dziecka w rodzinnej pieczy zastępczej;\n2) gdy dziecko przebywa w instytucjonalnej formie pieczy zastępczej wbrew\nrozstrzygnięciu sądu o umieszczeniu go w rodzinnej formie pieczy zastępczej;\n3) przebywania rodzeństwa w różnych rodzinach zastępczych, rodzinnych domach\ndziecka, placówkach opiekuńczo-wychowawczych lub regionalnych placówkach\nopiekuńczo-terapeutycznych, chyba że taka forma zapewnienia tym dzieciom pieczy\nzastępczej została zastosowana z uwagi na ich dobro;\n4) przebywania w placówce opiekuńczo-wychowawczej typu socjalizacyjnego,\ninterwencyjnego lub specjalistyczno-terapeutycznego dziecka poniżej 10. roku \f– 72 –\nżycia, z wyłączeniem sytuacji, gdy w tej placówce opiekuńczo-wychowawczej\numieszczona jest matka lub ojciec tego dziecka;\n5) dzieci umieszonych lub przebywających w domu pomocy społecznej\n- w celu zapewnienia dzieciom rodzinnej pieczy zastępczej, zadania, o których mowa w\nart. 76 ust. 4, realizuje pozarządowy organizator rodzinnej pieczy zastępczej.\n2. Pozarządowego organizatora rodzinnej pieczy zastępczej ustanawia minister\nwłaściwy do spraw rodziny, w drodze decyzji administracyjnej, po weryfikacji spełnienia\nwymogów, o których mowa w ust. 4, akceptacji planu rozwoju rodzinnej pieczy\nzastępczej oraz kalkulacji, o których mowa w ust. 5 pkt 3 i 4.\n3. Decyzja, o której mowa w ust. 2, określa w szczególności:\n1) czas na jaki został ustanowiony pozarządowy organizator rodzinnej pieczy\nzastępczej;\n2)miesięczną wysokość wydatków na realizację zadań pozarządowego organizatora\nrodzinnej pieczy zastępczej ustaloną na podstawie kosztów, o których mowa w ust.\n5 pkt 3 i 4.\n4. Pozarządowym organizatorem rodzinnej pieczy zastępczej może być organizacja\npozarządowa, posiadający osobowość prawną oddział organizacji pozarządowej,\npodmiot, o którym mowa w art. 3 ust. 3 ustawy z dnia 24 kwietnia 2003 r. o działalności\npożytku publicznego i wolontariacie, lub posiadający osobowość prawną oddział tego\npodmiotu, które łącznie spełniają następujące warunki:\n1)posiadają minimum pięcioletnie doświadczenie w zakresie wspierania dzieci i rodzin\nw sytuacjach kryzysowych, dzieci ze szczególnymi potrzebami lub rodzin\nzastępczych;\n2)posiadają doświadczenie w realizacji zadań publicznych na kwotę minimum 100 000\nzł;\n3)posiadają status organizacji pożytku publicznego;\n4)zapewniają zatrudnienie koordynatora rodzinnej pieczy zastępczej spełniającego\nkryteria, o których mowa w art. 78;\n5)zapewniają zespół specjalistów zatrudnionych lub współpracujących, w zakresie co\nnajmniej trzech spośród specjalizacji pracy z dziećmi:\na) ze Spektrum Płodowych Zaburzeń Alkoholowych,\nb) doświadczającymi traumy lub wykorzystania, w tym wykorzystania seksualnego,\nc) z doświadczeniem zaburzenia więzi,\f– 73 –\nd) z niepełnosprawnościami,\ne) wymagającymi zastosowania szczególnych środków wychowawczych,\nf) z doświadczeniem migracji,\ng) z doświadczeniem konfliktu zbrojnego;\n6)posiadają uprawnienie do prowadzenia szkoleń dla kandydatów do pełnienia funkcji\nrodziny zastępczej lub prowadzenia rodzinnego domu dziecka, o których mowa w\nart. 44 ust. 1 i 1a.\n5. Wniosek o ustanowienie pozarządowego organizatora rodzinnej pieczy zastępczej\norganizacja pozarządowa, podmiot, o którym mowa w art. 3 ust. 3 ustawy z dnia 24\nkwietnia 2003 r. o działalności pożytku publicznego i wolontariacie, albo ich oddział,\nskładają do ministra właściwego do spraw rodziny dołączając:\n1) dokumenty potwierdzające spełnianie wymogów, o których mowa w ust. 4;\n2) program rozwoju rodzinnej pieczy zastępczej;\n3)całkowitą kalkulację szacowanych kosztów związanych z funkcjonowaniem i\nwykonywaniem zadań pozarządowego organizatora pieczy zastępczej, wraz z\nuwzględnieniem szacowanych dla poszczególnych form rodzinnej pieczy zastępczej\nwysokości świadczeń lub środków finansowych odpowiednio na:\na) pokrycie kosztów utrzymania dziecka w rodzinie zastępczej lub w rodzinnym\ndomu dziecka,\nb) dodatki na pokrycie zwiększonych kosztów utrzymania dziecka legitymującego\nsię orzeczeniem o niepełnosprawności, albo orzeczeniem o znacznym lub\numiarkowanym stopniu niepełnosprawności lub umieszczonego na podstawie\nustawy z dnia 9 czerwca 2022 r. o wspieraniu i resocjalizacji nieletnich,\nc) dofinansowanie do wypoczynku poza miejscem zamieszkania dziecka,\nd) pokrycie niezbędnych kosztów związanych z potrzebami przyjmowanego\ndziecka,\ne) pokrycie kosztów związanych z wystąpieniem zdarzeń losowych lub innych\nzdarzeń mających wpływ na jakość sprawowanej opieki,\nf) dofinansowanie kosztów związanych z nabyciem, leasingiem lub wynajmem\npojazdu związanego z potrzebami rodziny zastępczej lub rodzinnego domu\ndziecka,\ng) utrzymanie lokalu mieszkalnego w budynku wielorodzinnym lub domu\njednorodzinnego oraz pokrycie niezbędnych kosztów związanych z remontem \f– 74 –\nlub ze zmianą lokalu w budynku wielorodzinnym lub domu jednorodzinnego,\nw którym jest prowadzony rodzinny dom dziecka lub swoje funkcje wypełnia\nrodzina zastępcza,\nh) pokrycie innych niezbędnych i nieprzewidzianych kosztów związanych z\nopieką i wychowaniem dziecka lub funkcjonowaniem rodzinnego domu\ndziecka,\ni) wynagrodzenia dla rodzin zastępczych zawodowych, prowadzących rodzinne\ndomy dziecka, rodzin pomocowych oraz osób do pomocy przy sprawowaniu\nopieki nad dziećmi i przy pracach gospodarczych;\n4) wskazanie wynikających z przedłożonej kalkulacji miesięcznych jednostkowych\nkosztów pobytu dzieci i osób, o których mowa w art. 37 ust 2-6, w poszczególnych\nformach rodzinnej pieczy zastępczej.\n6. Zmiana wysokości kosztów pobytu dziecka w poszczególnych formach pieczy\nzastępczej, o których mowa w ust. 5 pkt 4, związana z waloryzacją, o której mowa w art.\n86 ust. 2, nie wymaga zmiany decyzji, o której mowa w ust. 2.\n7. Liczba dzieci, o których mowa w ust. 1, w stosunku do których powiat jest\npowiatem obowiązanym do ponoszenia wydatków, o których mowa w art. 191 ust. 1 pkt\n1, dla których miejsce w pieczy zastępczej zapewnił pozarządowy organizator rodzinnej\npieczy zastępczej nie może przekroczyć 5% ogólnej liczby dzieci umieszczonych z tego\npowiatu w pieczy zastępczej.\nArt. 76b. 1. Minister właściwy do spraw rodziny udostępnia w Biuletynie Informacji\nPublicznej listę organizacji pozarządowych, podmiotów, o których mowa w art. 3 ust. 3\nustawy z dnia 24 kwietnia 2003 r. o działalności pożytku publicznego i wolontariacie,\nalbo ich oddziałów, które zostały ustanowione pozarządowym organizatorem rodzinnej\npieczy zastępczej, wraz ze wskazaniem wojewody właściwego do ich kontroli.\n2. Organizacja pozarządowa, podmiot, o którym mowa w art. 3 ust. 3 ustawy z dnia\n24 kwietnia 2003 r. o działalności pożytku publicznego i wolontariacie, albo ich oddział,\nktóre zostały ustanowione pozarządowym organizatorem rodzinnej pieczy zastępczej, są\nobowiązane do niezwłocznego informowania ministra właściwego do spraw rodziny o\nkażdej zmianie sytuacji, która może mieć wpływ na ustanowienie ich pozarządowym\norganizatorem rodzinnej pieczy zastępczej.\n3. Wojewoda właściwy do kontroli pozarządowego organizatora rodzinnej pieczy\nzastępczej, o którym mowa w art. 38b ust. 12, jest zobowiązany do niezwłocznego \f– 75 –\ninformowania ministra właściwego do spraw rodziny, w przypadku stwierdzenia\npoważnych nieprawidłowości w działalności organizacji pozarządowej, podmiotu, o\nktórym mowa w art. 3 ust. 3 ustawy z dnia 24 kwietnia 2003 r. o działalności pożytku\npublicznego i wolontariacie, albo ich oddziału, która została ustanowiona pozarządowym\norganizatorem rodzinnej pieczy zastępczej, w szczególności w przypadku\nnieprawidłowego wykonywania przez niego zadań.\n4. Minister właściwy do spraw rodziny, uchyla decyzję, o której mowa w art. 75a\nust. 2, w przypadku:\n1) stwierdzenia braku spełnienia przez pozarządowego organizatora rodzinnej pieczy\nzastępczej wymogów, o których mowa w art. 76a ust. 4, lub\n2) stwierdzenia poważnych nieprawidłowości w działalności pozarządowego\norganizatora rodzinnej pieczy zastępczej, w szczególności w przypadku\nnieprawidłowego wykonywania przez niego zadań.\nArt. 76c. 1. W przypadku uchylenia lub wygaśnięcia decyzji, o której mowa w art.\n76a ust. 2, umowy o współpracy, o których mowa w art. 53b ust. 3 zawarte z rodzinami\nzastępczymi niezawodowymi, umowy rodzicielstwa zastępczego zawarte z rodzinami\nzastępczymi zawodowymi albo prowadzącymi rodzinne domy dziecka oraz umowy, o\nktórych mowa art. 75 ust. 1, zawarte z rodzinami pomocowymi, przez pozarządowego\norganizatora rodzinnej pieczy zastępczej, któremu decyzję uchylono albo ona wygasła,\nwygasają z mocy prawa.\n2. W przypadku, o którym mowa w ust. 1, zadania pozarządowego organizatora\nrodzinnej pieczy zastępczej, któremu decyzję uchylono albo ona wygasła, przejmuje w\nstosunku do:\n1) rodziny zastępczej zawodowej albo rodzinnego domu dziecka -pozarządowy\norganizator rodzinnej pieczy zastępczej, który podpisał umowę rodzicielstwa zastępczego\nz tą rodziną albo rodzinnym domem dziecka;\n2) rodziny zastępczej niezawodowej - pozarządowy organizator rodzinnej pieczy\nzastępczej, który podpisał z tą rodziną umowę współpracy, o której mowa w art. 53b ust.\n3.\n3. W przypadku niepodpisania z rodziną zastępczą zawodową albo rodzinnym\ndomem dziecka umowy rodzicielstwa zastępczego, o której mowa w ust. 2 pkt 1, zadania\nrealizowane przez pozarządowego organizatora rodzinnej pieczy zastępczej, któremu\ndecyzje uchylono albo ona wygasła, przejmuje starosta lub podmiot, któremu powiat \f– 76 –\nzlecił realizację zadania organizacji rodzinnej pieczy zastępczej na podstawie art. 190,\nktóry podpisał  umowę rodzicielstwa zastępczego z rodziną zastępczą zawodową albo\nprowadzącym rodzinny dom dziecka.\n4. W przypadku niepodpisania z rodziną zastępczą niezawodową umowy o\nwspółpracy, o której mowa w ust. 2 pkt 2 oraz niepodpisania z rodziną zastępczą\nzawodową albo rodzinnym domem dziecka umowy rodzicielstwa zastępczego, o której\nmowa w ust. 2 pkt 1 lub ust. 3, zadania pozarządowego organizatora rodzinnej pieczy\nzastępczej, któremu decyzję uchylono albo ona wygasła, przejmuje powiat właściwy ze\nwzględu na miejsce zamieszkania rodziny zastępczej niezawodowej, rodziny zastępczej\nzawodowej, albo powiat właściwy ze względu na miejsce prowadzenia rodzinnego domu\ndziecka.\n5. W przypadku, o którym mowa w ust. 1 - 4, odpowiednio świadczenia i dodatki, o\nktórych mowa w art. 80 ust. 1 i art. 81 oraz wynagrodzenie przysługujące rodzinnie\nzastępczej zawodowej lub prowadzącemu rodzinnego domu dziecka od dnia\nnastępującym po dniu uchylenia albo wygaśnięcia decyzji, o której mowa w art. 76a ust.\n2. Przepisy art. 85 i 87 stosuje się odpowiednio.”;\n77) w art. 77:\na) w ust. 3 po pkt 4 dodaje się pkt 4a w brzmieniu:\n„4a) organizacja spotkań dzieci znajdujących się w pieczy zastępczej z rodziną - na\nwniosek rodziny zastępczej lub osób prowadzących rodzinny dom dziecka;”;\nb) po ust. 6 dodaje się ust. 7-17 w brzmieniu:\n„7. Koordynatorowi rodzinnej pieczy zastępczej zatrudnionemu w pełnym\nwymiarze czasu pracy, przysługuje wypłacany co miesiąc dodatek do wynagrodzenia\nw wysokości 400 zł z tytułu wykonywania czynności zawodowych poza miejscem\npracy. W przypadku zatrudnienia koordynatora rodzinnej pieczy zastępczej w\nniepełnym wymiarze czasu pracy dodatek przysługuje w wysokości proporcjonalnej\ndo wymiaru czasu pracy. Przepisy art. 86 ust. 2-3 stosuje się odpowiednio.\n8. Dodatek, o którym mowa w ust. 4, nie jest uwzględniany przy obliczaniu\nwysokości minimalnego wynagrodzenia pracownika zgodnie z art. 6 ust. 4 ustawy z\ndnia 10 października 2002 r. o minimalnym wynagrodzeniu za pracę.\n9. Kierownik jednostki organizacyjnej, w której jest zatrudniony koordynator\nrodzinnej pieczy zastępczej zapewnia koordynatorowi rodzinnej pieczy zastępczej\nsamochód służący do realizacji przez niego zadań służbowych. \f– 77 –\n10. W przypadku braku możliwości zapewnienia koordynatorowi rodzinnej\npieczy zastępczej samochodu służącego do realizacji przez niego zadań służbowych,\nkierownik jednostki organizacyjnej, w której jest zatrudniony koordynator rodzinnej\npieczy zastępczej, zwraca koordynatorowi rodzinnej pieczy zastępczej\nwykorzystującemu do realizacji zadań służbowych pojazd prywatny, wydatki\nponiesione w zawiązku z użytkowaniem tego samochodu na zasadach ustalania oraz\nwysokości należności przysługujących pracownikowi z tytułu podróży służbowej na\nobszarze kraju oraz zgodnie z warunkami ustalania oraz sposobu dokonywania\nzwrotu kosztów używania do celów służbowych pojazdów niebędących własnością\npracodawcy.\n11. W przypadku braku możliwości zapewnienia koordynatorowi rodzinnej\npieczy zastępczej samochodu służącego do realizacji przez niego zadań służbowych\noraz w przypadku gdy koordynator rodzinnej pieczy zastępczej nie wykorzystuje\npojazdu prywatnego do realizacji zadań służbowych, kierownik jednostki\norganizacyjnej, w której jest zatrudniony koordynator rodzinnej pieczy zastępczej,\nzapewnia koordynatorowi rodzinnej pieczy zastępczej pokrycie kosztów przejazdów\nzwiązanych z realizacją przez tego koordynatora rodzinnej pieczy zastępczej zadań\nsłużbowych.\n12. Koordynatorowi rodzinnej pieczy zastępczej, który realizuje zadania w\nśrodowisku miejsca sprawowania pieczy zastępczej przez rodzinę zastępczą  albo\nrodzinny domu dziecka, jeżeli przepracował co najmniej 3 lata, przysługuje raz na 2\nlata, dodatkowy urlop wypoczynkowy w wymiarze 10 dni.\n13. Koordynatorowi rodzinnej pieczy zastępczej przysługuje pomoc\npsychologiczna w przypadku wystąpienia sytuacji bezpośrednio zagrażających jego\nżyciu lub zdrowiu w związku z wykonywanymi zadaniami służbowymi.\n14. Pomoc, o której mowa w ust. 13, zapewnia kierownik jednostki\norganizacyjnej lub podmiotu, w której jest zatrudniony koordynator rodzinnej pieczy\nzastępczej.\n15. Koordynatorowi rodzinnej pieczy zastępczej przysługuje zwrot kosztów\nszkoleń nieobowiązkowych w zakresie pracy z rodziną realizowanych za zgodą\norganizator rodzinnej pieczy zastępczej, w kwocie nie mniejszej niż 50% kosztów\nszkolenia.\f– 78 –\n16. Koordynator rodzinnej pieczy zastępczej korzysta w związku z\nwykonywanymi zadaniami służbowymi i w zakresie tych zadań przysługuje  prawo\npierwszeństwa w urzędach, instytucjach, podmiotach wykonujących działalność\nleczniczą i innych placówkach edukacyjnych i usługowych.\n17. Organy i instytucje administracji publicznej, podmioty wykonujące\ndziałalność leczniczą i organizacje pozarządowe są obowiązane do udzielania\nkoordynatorowi rodzinnej pieczy zastępczej pomocy w wykonywaniu jego zadań.”;\n78) w art. 78 w ust 1:\na) w pkt 1 lit. a otrzymuje brzmienie:\n„a) wykształcenie wyższe na kierunku pedagogika, pedagogika specjalna,\npsychologia, psychoprofilaktyka, socjologia, praca socjalna, nauki o rodzinie\nlub”,\nb) uchyla się pkt 4 i 5;\n79) w art. 79 ust. 2 otrzymuje brzmienie:\n„2. Praca koordynatora rodzinnej pieczy zastępczej jest wykonywana w ramach\nstosunku pracy w systemie zadaniowego czasu pracy.”;\nc) ust. 5 otrzymuje brzmienie:\n„5. W przypadku niewypełnienia obowiązku, o którym mowa w art. 77 ust. 3\npkt 5, z koordynatorem rodzinnej pieczy zastępczej stosunek pracy może zostać\nrozwiązany bez zachowania okresu wypowiedzenia.”;\n80) po art. 79 dodaje się art. 79a i 79b w brzmieniu:\n„Art. 79a. 1. Ustala się następujące stopnie awansu zawodowego dla koordynatorów\nrodzinnej pieczy zastępczej:\n1) młodszy koordynator rodzinnej pieczy zastępczej;\n2) koordynator rodzinnej pieczy zastępczej;\n3) starszy koordynator rodzinnej pieczy zastępczej;\n4) specjalista koordynator rodzinnej pieczy zastępczej;\n5) starszy specjalista koordynator rodzinnej pieczy zastępczej;\n6) główny specjalista koordynator rodzinnej pieczy zastępczej.\n2. Wyższy stopień awansu zawodowego można nadać zgodnie z trybem określonym\nw ust. 13 albo 14, po spełnieniu warunku minimalnego stażu pracy w zawodzie\nkoordynatora pieczy zastępczej, które ustala się dla:\n1) koordynatora rodzinnej pieczy zastępczej - jako posiadanie rocznego stażu pracy;\f– 79 –\n2) starszego koordynatora rodzinnej pieczy zastępczej - jako posiadanie 2-letniego\nstażu pracy;\n3) specjalisty koordynatora rodzinnej pieczy zastępczej - jako posiadanie 3-letniego\nstażu pracy;\n4) starszego specjalisty koordynatora rodzinnej pieczy zastępczej - jako posiadanie\n4-letniego stażu pracy;\n5) głównego specjalisty koordynatora rodzinnej pieczy zastępczej - jako posiadanie\n6-letniego stażu pracy.\n3.Okres zatrudnienia na podstawie umowy o świadczenie usług, w charakterze\nkoordynatora rodzinnej pieczy zastępczej, na podstawie ustawy z dnia 23 kwietnia 1964 r.\n- Kodeks cywilny, wlicza się do wymogów okresu zatrudnienia dotyczących stopni\nawansu zawodowego w zakresie zatrudniania koordynatorów rodzinnej pieczy zastępczej.\n4. Praca koordynator rodzinnej pieczy zastępczej podlega, raz na 2 lata, ocenie\nokresowej dokonywanej przez bezpośredniego przełożonego, w zakresie wywiązywania\nsię przez niego z obowiązków wynikających z czynności i zadań na zajmowanym\nstanowisku, w szczególności skuteczności działań w zakresie udzielania pomocy\nrodzinom zastępczym i prowadzącym rodzinne domy dziecka.\n5. Ocena okresowa jest sporządzana na piśmie i zawiera uzasadnienie.\n6. Ocena okresowa może być pozytywna powyżej oczekiwań, pozytywna albo\nnegatywna.\n7. Koordynator rodzinnej pieczy zastępczej może wnieść na piśmie zastrzeżenia\nco do uzyskanej oceny okresowej, w terminie 14 dni od dnia otrzymania tej oceny do\nkierownika jednostki organizacyjnej, w której jest zatrudniony.\n8. W przypadku gdy bezpośrednim przełożonym koordynatora rodzinnej pieczy\nzastępczej jest kierownik jednostki organizacyjnej, zastrzeżenia wnosi się do organu\nnadzorującego jednostkę, w której koordynator rodzinnej pieczy zastępczej jest\nzatrudniony.\n9. Kierownik jednostki albo organ, do którego koordynator rodzinnej pieczy\nzastępczej wniósł zastrzeżenia, analizuje ich treść, a następnie informuje, na piśmie\nkoordynatora rodzinnej pieczy zastępczej o podtrzymaniu albo zakwestionowaniu\ndokonanej oceny okresowej wraz z uzasadnieniem, w terminie 14 dni od dnia otrzymania\nzastrzeżeń.\f– 80 –\n10. W przypadku, o którym mowa w ust. 9, informacja o podtrzymaniu albo\nzakwestionowaniu dokonanej oceny okresowej jest przekazywana także bezpośredniemu\nprzełożonemu koordynatora rodzinnej pieczy zastępczej.\n11. W przypadku podtrzymania negatywnej oceny okresowej przez kierownika\njednostki albo przez organ, do którego koordynator rodzinnej pieczy zastępczej wniósł\nzastrzeżenia, nie podlega ona zaskarżeniu.\n12. W przypadku zakwestionowania oceny okresowej przez kierownika jednostki\nalbo przez organ, do którego koordynator rodzinnej pieczy zastępczej wniósł zastrzeżenia,\nocena okresowa pracy tego koordynatora rodzinnej pieczy zastępczej jest dokonywana\nponownie.\n13. W sprawach naruszenia zasady równego traktowania w zatrudnieniu podczas\noceny okresowej stosuje się przepisy art. 183d ustawy z dnia 26 czerwca 1974 r. – Kodeks\npracy.\n14. Koordynatorowi rodzinnej pieczy zastępczej, który otrzymał dwie następujące\npo sobie oceny okresowe pozytywne powyżej oczekiwań, spełniającemu warunki\ndotyczące stażu pracy, o których mowa w ust. 2, jest nadawany wyższy stopień awansu\nzawodowego.\n15. Koordynatorowi rodzinnej pieczy zastępczej, który posiada wymóg stażu pracy,\no którym mowa w ust. 2, oraz wyróżnia się wysokim zaangażowaniem, inicjatywą lub\nnowatorskim podejściem przy wykonywaniu obowiązków służbowych związanych z\nopieką nad rodzinami zastępczymi oraz rodzinnymi domami dziecka, może być nadany\nwyższy stopień awansu z pominięciem wymogu, o którym mowa w ust. 13.\n16. W przypadku awansu na wyższy stopień zawodowy koordynatorowi rodzinnej\npieczy zastępczej przysługuje podwyższenie wynagrodzenia zasadniczego.\n17. Szczegółowe zasady i kryteria oceny okresowej w zakresie, o którym mowa\nw ust. 3, ustala kierownik podmiotu zatrudniającego koordynatora rodzinnej pieczy\nzastępczej, po konsultacji z zakładową organizacją związkową lub z reprezentacją\npracowników.\n18. Przy dokonywaniu okresowej oceny pracy koordynatora rodzinnej pieczy\nzastępczej bierze się pod uwagę opinie rodzin zastępczych oraz prowadzących rodzinne\ndomy dziecka, objętych opieką tego koordynatora rodzinnej pieczy zastępczej, na temat\nwspółpracy z tym koordynatorem rodzinnej pieczy zastępczej.\f– 81 –\nArt. 79b. 1. Dokumentem identyfikującym koordynatora rodzinnej pieczy zastępczej\noraz potwierdzającym jego zatrudnienie oraz uprawnienia wynikające z przepisów\nniniejszej ustawy jest legitymacja służbowa.\n2. Legitymację służbową wydaje pracodawca. Przepisy art. 17b ust. 4 -11 stosuje się\nodpowiednio.”;\n81) w art. 80 ust. 1 otrzymuje brzmienie:\n„1. Rodzinie zastępczej oraz prowadzącemu rodzinny dom dziecka, na każde\numieszczone dziecko, przysługuje świadczenie na pokrycie kosztów jego utrzymania,  w\nwysokości nie niższej niż kwota:\n1) 1325 zł miesięcznie - w przypadku dziecka umieszczonego w rodzinie zastępczej\nspokrewnionej;\n2) 1628,19 zł miesięcznie - w przypadku dziecka umieszczonego w rodzinie\nzastępczej zawodowej, rodzinie zastępczej niezawodowej lub rodzinnym domu\ndziecka.”;\n82) art. 81 otrzymuje brzmienie:\n„Art. 81. 1. Rodzinie zastępczej albo prowadzącemu rodzinny dom dziecka\nprzysługuje dodatek na każde umieszczone dziecko legitymujące się\norzeczeniem o niepełnosprawności, albo orzeczeniem o znacznym lub umiarkowanym\nstopniu niepełnosprawności, w wysokości nie niższej niż kwota 328,43 zł miesięcznie na\npokrycie zwiększonych kosztów utrzymania tego dziecka.\n2. Rodzinie zastępczej zawodowej przysługuje dodatek na każde dziecko\numieszczone na podstawie przepisów ustawy z dnia 9 czerwca 2022 r. o wspieraniu i\nresocjalizacji nieletnich, w wysokości nie niższej niż kwota 328,43 zł miesięcznie na\npokrycie zwiększonych kosztów utrzymania tego dziecka.”;\n83) w art. 83:\na) ust. 1 otrzymuje brzmienie:\n„1. Rodzinie zastępczej oraz prowadzącemu rodzinny dom dziecka starosta, a\nw przypadku organizowania rodziny zastępczej albo rodzinnego domu dziecka przez\npozarządowego organizatora rodzinnej pieczy zastępczej - pozarządowy organizator\nrodzinnej pieczy zastępczej, może przyznać:\n1) dofinansowanie do wypoczynku poza miejscem zamieszkania dziecka;\n2)świadczenie na pokrycie:\f– 82 –\na) niezbędnych kosztów związanych z potrzebami przyjmowanego dziecka\n– jednorazowo,\nb)  kosztów związanych z wystąpieniem zdarzeń losowych lub innych\nzdarzeń mających wpływ na jakość sprawowanej opieki - jednorazowo lub\nokresowo;\n3) zwrot kosztów amortyzacji środków trwałych, wykorzystywanych przez\nrodzinę zastępczą zawodową lub rodzinny dom dziecka, w zakresie, w jakim\nśrodki trwałe nie zostały sfinansowane ze środków publicznych, w tym\nokreślenie kategorii środków trwałych, których dotyczy zwrot kosztów\namortyzacji;\n4) dofinansowanie kosztów związanych z nabyciem, leasingiem lub wynajmem\npojazdu związanego z potrzebami rodziny zastępczej lub rodzinnego domu\ndziecka.”,\nb) ust. 3a i 4 otrzymują brzmienie:\n„3a. Środki finansowe, o których mowa w ust. 2, starosta, a w przypadku\norganizowania rodziny zastępczej albo rodzinnego domu dziecka przez\npozarządowego organizatora rodzinnej pieczy zastępczej - pozarządowy organizator\nrodzinnej pieczy zastępczej, jest zobowiązany przyznać rodzinie zastępczej\nzawodowej, w której umieszczono powyżej 3 dzieci, osób, które osiągnęły\npełnoletność przebywając w pieczy zastępczej, o których mowa w art. 37 ust. 2-4 i\n6, oraz osób opuszczających rodzinną pieczę zastępczą jako niepełnoletnie, o których\nmowa w art. 37 ust. 5 i 6.\n4. Rodzinie zastępczej zawodowej starosta, a w przypadku organizowania\nrodziny zastępczej albo rodzinnego domu dziecka przez pozarządowego\norganizatora rodzinnej pieczy zastępczej - pozarządowy organizator rodzinnej pieczy\nzastępczej, może raz do roku przyznać świadczenie na pokrycie kosztów związanych\nz przeprowadzeniem niezbędnego remontu lokalu mieszkalnego w budynku\nwielorodzinnym lub domu jednorodzinnego.”;\n84) w art. 84 pkt 2 i 3 otrzymują brzmienie:\n„2) pokrycie niezbędnych kosztów związanych z remontem lub ze zmianą lokalu\nw budynku wielorodzinnym lub domu jednorodzinnego, w którym jest prowadzony\nrodzinny dom dziecka - do wysokości środków określonych zgodnie z zasadami \f– 83 –\nkalkulacji zawartymi w umowie rodzicielstwa zastępczego, o której mowa w art. 55a\nust. 1;\n3) pokrycie innych niezbędnych i nieprzewidzianych kosztów związanych z opieką i\nwychowaniem dziecka lub funkcjonowaniem rodzinnego domu dziecka – do\nwysokości środków określonych w umowie rodzicielstwa zastępczego, o której\nmowa w art. 55a ust. 1.”;\n85) w art. 85:\na) ust. 1 otrzymuje brzmienie:\n„1. Miesięczne wynagrodzenie określone w umowie rodzicielstwa zastępczego,\no której mowa w art. 55a ust. 1, przysługuje:\n1) rodzinie zastępczej zawodowej - w kwocie nie niższej 6160 zł;\n2) rodzinie zastępczej zawodowej specjalistycznej - w kwocie nie niższej niż 7260\nzł;\n3) rodzinie zastępczej zawodowej pełniącej funkcję pogotowia rodzinnego – w\nkwocie nie niższej niż 7260 zł;\n4) prowadzącemu rodzinny dom dziecka - w kwocie nie niższej niż 7260 zł.”,\nb) uchyla się ust. 2,\nc) po ust. 2 dodaje się ust. 2a w brzmieniu:\n„2a. Rodzinie zastępczej zawodowej albo prowadzącemu rodzinny dom\ndziecka przysługuje miesięczny dodatek stażowy za wieloletnie pełnienie funkcji\nrodziny zastępczej albo prowadzenie rodzinnego domu dziecka w wysokości\nwynoszącej, po pięciu latach pełnienia funkcji rodziny zastępczej lub prowadzenia\nrodzinnego dom dziecka, 5% miesięcznego wynagrodzenia, określonego w umowie\nrodzicielstwa zastępczego, o której mowa w art. 55a ust. 1. Dodatek ten wzrasta o\n1% za każdy dalszy rok pełnienia funkcji rodziny zastępczej lub prowadzenia\nrodzinnego dom dziecka, aż do osiągnięcia 20% miesięcznego wynagrodzenia.”;\nd) ust. 3 otrzymuje brzmienie:\n„3. Ustalając wysokość wynagrodzenia określonego w umowie, o której mowa\nw art. 55a, bierze się pod uwagę w szczególności kwalifikacje, szkolenia i oceny\nrodziny zastępczej zawodowej oraz prowadzącego rodzinny dom dziecka, liczbę\ndzieci lub osób, o których mowa w art. 37 ust. 2-6, przebywających pod ich opieką,\na także stan zdrowia, rozwoju oraz niepełnosprawność dzieci lub osób, o których\nmowa w art. 37 ust. 2-6 przebywających pod ich opieką.”;\f– 84 –\ne) ust. 7 otrzymuje brzmienie:\n„7. Rodzina zastępcza niezawodowa oraz małżonkowie lub osoba, o których\nmowa w art. 74 ust. 1 pkt 2-6, za czas sprawowania funkcji rodziny pomocowej\notrzymują miesięczne wynagrodzenie w wysokości nie niższej niż 20% kwoty, o\nktórej mowa w ust. 1 pkt 1.”;\n86) w art. 86:\na) ust. 2 otrzymuje brzmienie:\n„2. Kwoty:\n1) o której mowa w art. 80 ust. 1 i art. 81;\n2) wysokości wynagrodzeń, określonych w umowach, o których mowa w art. 55a i\n75;\n3) zatwierdzonej kalkulacji, o której mowa w art. 76a ust. 5 pkt 4;\n4) minimalnego wynagrodzenia, o którym mowa w art. 85 ust. 1;\n5) pomocy na usamodzielnienie, o której mowa w art. 149 ust. 1\n- podlegają waloryzacji wskaźnikiem waloryzacji równym wskaźnikowi cen\ntowarów i usług konsumpcyjnych ogółem w roku poprzedzającym rok, w którym\nprzeprowadzana jest waloryzacja.”;\nb) po ust. 2 dodaje się ust. 2a i 2b w brzmieniu:\n„2a. W wyniku przeprowadzonej waloryzacji, kwoty, o których mowa w ust. 2,\nnie mogą ulec obniżeniu.\n2b. W przypadku przeprowadzenia waloryzacji, o której mowa w ust. 2 pkt 1\nprzepisów art. 10 § 1 oraz art. 61 § 4 ustawy z dnia 14 czerwca 1960 r. - Kodeks\npostępowania administracyjnego nie stosuje się.”;\n87) w art. 88:\na) ust. 1 otrzymuje brzmienie:\n„1. Świadczenia, dodatki, dofinansowanie do wypoczynku i dofinansowanie\nkosztów związanych z leasingiem lub kredytem na zakup samochodu, o których\nmowa w art. 80 ust. 1, art. 81, art. 83 i art. 84, są udzielane na wniosek odpowiednio\nrodziny zastępczej, rodziny pomocowej lub prowadzącego rodzinny dom dziecka.”;\nb) ust. 3 otrzymuje brzmienie:\n„3. Wniosek, o którym mowa w ust. 1:\n1) rodzina zastępcza niezawodowa składa w powiatowym centrum pomocy\nrodzinie w powiecie właściwym:\f– 85 –\na) dla organizatora, który wydał zaświadczenie kwalifikacyjne, z zastrzeżeniem art.\n35b ust. 4,\nb) ze względu na miejsce zamieszkania rodziny zastępczej niezawodowej- w\nprzypadku, o którym mowa w art. 35b ust. 3;\n2) rodzina zastępcza zawodowa składa w powiatowym centrum pomocy\nrodzinie w powiecie, który organizuje rodzinę zastępczą zawodową lub zleca\norganizację rodziny zastępczej zawodowej, z zastrzeżeniem art. 35b ust. 4;\n3) prowadzący rodzinny dom dziecka składa w powiatowym centrum pomocy\nrodzinie w powiecie, który organizuje rodzinny dom dziecka lub zleca organizację\nrodzinnego domu dziecka, z zastrzeżeniem art. 35b ust. 4;\n4) rodzina zastępcza spokrewniona składa w powiatowym centrum pomocy\nrodzinie właściwym ze względu na miejsce zamieszkania, z zastrzeżeniem 35b ust.\n2 lub 4;\n5) rodzina pomocowa składa w powiatowym centrum pomocy rodzinie w\npowiecie, który organizuje rodzinę pomocową, z zastrzeżeniem art. 35b ust. 4.”;\n88) po art. 90 dodaje się art. 90a-90c w brzmieniu:\n„Art. 90a. 1. Wójt gminy właściwej ze względu na miejsce zamieszkania dziecka\nprzed umieszczeniem go po raz pierwszy w pieczy zastępczej może, w drodze decyzji\nadministracyjnej, przyznać comiesięczne świadczenie pieniężne na zaspokojenie\ndodatkowych potrzeb dziecka umieszczonego w rodzinie zastępczej spokrewnionej,\nniezależnie od jej miejsca zamieszkania. Kwota dodatkowego świadczenia finansowana\njest ze środków własnych gminy.\n2. Świadczenie jest przyznawane na wniosek osoby pełniącej funkcję rodziny\nzastępczej spokrewnionej składany do wójta gminy, o której mowa w ust. 1 i\nprzeznaczone jest na zaspokojenie dodatkowych potrzeb nie pokrywanych przez\nświadczenie, o którym mowa w art. 80 ust.1 lub dodatek, o którym mowa w art. 81 ust. 1.\nArt. 90b. Decyzję zmienia się lub uchyla jeżeli osoba otrzymująca świadczenie, o\nktórym mowa w art. 90a ust. 1 marnotrawi je lub wydatkuje je niezgodnie z\nprzeznaczeniem.\nArt. 90c. 1. Do nienależnie pobranych świadczeń, o których mowa w art. 90a ust. 1\nstosuje się odpowiednio przepis art. 92.\n2. Organ, który wydał decyzję w sprawie nienależnie pobranych świadczeń, może\numorzyć kwotę nienależnie pobranych świadczeń łącznie z odsetkami w całości lub w \f– 86 –\nczęści, odroczyć termin płatności albo rozłożyć na raty, jeżeli zachodzą szczególnie\nuzasadnione okoliczności dotyczące sytuacji rodziny.\n3. W przypadku śmierci osoby, która pobrała nienależnie świadczenia, należności z\ntytułu nienależnie pobranych świadczeń wygasają.”;\n89) art. 91 otrzymuje brzmienie:\n„Art. 91. Rada powiatu może, w drodze uchwały, podnieść wysokość odpowiednio\nświadczeń pieniężnych lub wynagrodzeń, o których mowa w art. 80 ust. 1, art. 81, 83, 85\nust. 1 i 7 oraz art. 87 ust. 5.”;\n90) po art. 92 dodaje się art. 92a w brzmieniu:\n„Art. 92a. 1. W przypadku organizowania rodziny zastępczej niezawodowej, rodziny\nzastępczej zawodowej, rodzinnego domu dziecka, albo rodziny pomocowej przez\npozarządowego organizatora rodzinnej pieczy zastępczej, nienależnie pobrane\nświadczenia pieniężne podlegają zwrotowi, łącznie z odsetkami ustawowymi za\nopóźnienie, przez osobę, która je pobrała. Przepis art. 92 ust. 2 stosuje się odpowiednio.2.\nDo nienależnie pobranych świadczeń pieniężnych stosuje się odpowiednio przepisy o\nbezpodstawnym wzbogaceniu z art. 405-414 ustawy z dnia 23 kwietnia 1964 r. - Kodeks\ncywilny.”;\n91) w art. 93:\na) w ust. 1 uchyla się pkt 3,\nb) ust. 2a otrzymuje brzmienie:\n„2a. Placówka opiekuńczo-wychowawcza może być prowadzona na terenie\ninnego powiatu.”,\nc) ust. 3 otrzymuje brzmienie:\n„3. Samorząd województwa może prowadzić lub zlecić, na podstawie art. 190,\nprowadzenie regionalnej placówki opiekuńczo-terapeutycznej.”,\nd) w ust. 4:\n- pkt 4 otrzymuje brzmienie:\n„4) podejmuje działania w celu powrotu dziecka do rodziny lub, gdy to jest\nniemożliwe, przygotowuje do przysposobienia,”,\n- po pkt 4 dodaje się pkt 4a i 4b w brzmieniu:\n„4a) w przypadku doboru przez ośrodek adopcyjny kandydatów do\nprzysposobienia dziecka, współpracuje z ośrodkiem adopcyjnym oraz\nkandydatami do przysposobienia dziecka w zakresie przejścia dziecka pod \f– 87 –\nopiekę odpowiednio kandydatów do przysposobienia dziecka lub\nprzysposabiających,\n4b) koordynuje współpracę, w szczególności, pomiędzy organizatorem\nrodzinnej pieczy zastępczej, rodziną zastępczą, prowadzącym rodzinny dom\ndziecka, dyrektorem placówki opiekuńczo-wychowawczej, dyrektorem\nregionalnej placówki opiekuńczo-terapeutycznej, dyrektorem instytucji, o\nktórych mowa w art. 87 ust. 2 lub rodzicem dziecka w zakresie\na) umieszczenia dziecka lub osoby, o której mowa w art. 37 ust. 2-6 w rodzinnej\npieczy zastępczej,\nb) powrotu dziecka z instytucjonalnej pieczy zastępczej do rodziny,\nc) zmiany placówki opiekuńczo-wychowawczej albo regionalnej placówki\nopiekuńczo-terapeutycznej, w których przebywa dziecko lub osoba, o której\nmowa w art. 37 ust. 2-6 ,\nd) umieszczenia dziecka lub osoby, o której mowa w art. 37 ust. 2-6, w\ninstytucjach, o których mowa w art. 87 ust. 2.”,\n- po pkt 7 kropkę zastępuje się średnikiem i dodaje się pkt 8 i 9 w brzmieniu:\n„8) udziela wsparcia pełnoletnim wychowankom po opuszczeniu przez nich\nplacówki opiekuńczo-wychowawczej,\n9) wydaje zaświadczenia o przebywaniu dziecka w placówce opiekuńczo-\nwychowawczej umożliwiające skorzystanie z uprawnień wynikających z\nprzepisów odrębnych.”,\ne) po ust. 4 dodaje się ust. 5-7 w brzmieniu:\n„5. Placówka opiekuńczo-wychowawcza, może:\n1) prowadzić grupy usamodzielniające, o których mowa w art. 106a;\n2) prowadzić mieszkania treningowe lub wspomagane, o których mowa w art. 53\nustawie z dnia 2004 r. o pomocy społecznej dla pełnoletnich wychowanków\npieczy zastępczej po opuszczeniu przez nich placówki opiekuńczo-\nwychowawczej;\n3) prowadzić działania na rzecz lokalnej społeczności, w tym także wsparcia rodzin\nzastępczych.\n6. Mieszkania treningowe lub wspomagane nie mogą znajdować się na terenie\ntej samej lub bezpośrednio sąsiadującej nieruchomości, co placówka opiekuńczo-\nwychowawcza. Przepisy art. 106 ust. 2a stosuje się odpowiednio.\f– 88 –\n7. Mieszkania treningowe lub wspomagane prowadzone przez placówki\nopiekuńczo-wychowawcze prowadzone są zgodnie ze standardami i zasadami\nwynikającymi z przepisów ustawy z dnia 12 marca 2004 r. o pomocy społecznej”;\n92) po art. 94a dodaje się art. 94b w brzmieniu:\n„Art. 94b. Z dyrektorem placówki opiekuńczo - wychowawczej typu rodzinnego\nstarosta powiatu, który prowadzi tę placówkę lub zlecił jej prowadzenie na podstawie art.\n190, zawiera na wniosek tego dyrektora, w terminie 3 miesięcy od dnia złożenia wniosku,\numowę rodzicielstwa zastępczego o której mowa w art. 55a ust. 1. Przepisy art. 44 ust. 1\ni art. 55 ust. 1aa-1ab nie stosuje się.”;\n93) w art. 97 w ust. 3 uchyla się pkt 5 i 5a;\n94) w art. 98:\na) w ust. 1 w pkt 6 kropkę zastępuje się średnikiem i dodaje się pkt 7 w brzmieniu:\n„7) w przypadku pielęgniarki - prawo wykonywania zawodu pielęgniarki w\nrozumieniu ustawy z dnia 15 lipca 2011 r.  o zawodach pielęgniarki i położnej\n(Dz.U. z 2026 r. poz. 15).”,\nb) w ust. 3 uchyla się pkt 3 i 3a;\n95) w art. 100:\na) ust. 4a otrzymuje brzmienie:\n„4a. W przypadku stwierdzenia ustania przyczyny umieszczenia dziecka w placówce\nopiekuńczo - wychowawczej dyrektor placówki opiekuńczo - wychowawczej\ninformuje właściwy sąd o możliwości powrotu dziecka do jego rodziny,\ndołączając opinię gminy lub podmiotu prowadzącego pracę z rodziną.”;\nb) po ust. 4a dodaje się ust. 4b i 4c w brzmieniu:\n„4b. W przypadku stwierdzenia braku możliwości powrotu dziecka do jego rodziny,\ndyrektor placówki opiekuńczo - wychowawczej składa do właściwego sądu\nwniosek o pozbawienie władzy rodzicielskiej rodziców dziecka, chyba, że\nwładza ta już im nie przysługuje. Do wniosku dyrektor placówki opiekuńczo -\nwychowawczej dołącza w szczególności uzasadnienie i opinię gminy lub\npodmiotu prowadzącego pracę z rodziną.\n4c. W przypadku niestwierdzenia ustania przyczyny umieszczenia dziecka w\nplacówce opiekuńczo - wychowawczej, o której mowa w ust. 4a w terminie\n12 miesięcy od dnia umieszczenia dziecka w pieczy zastępczej, dyrektor \f– 89 –\nplacówki opiekuńczo - wychowawczej składa do właściwego sądu wniosek, o\nktórym mowa w ust. 4b, chyba że wniosek ten został już złożony.”;\n96) w art. 102 pkt 1 otrzymuje brzmienie:\n„1) wychowuje dzieci w różnym wieku, w tym dorastające i usamodzielniające się,\nktórych wyłącznymi opiekunami są małżonkowie lub osoba niepozostająca w\nzwiązku małżeńskim, zamieszkujący z dziećmi lub osobami, o których mowa w art.\n37 ust. 2-6, w tej placówce na stałe;”;\n97) po art. 106 dodaje się art. 106a w brzmieniu:\n„Art. 106a. 1. W ramach placówki opiekuńczo-wychowawczej typu\nsocjalizacyjnego, może być prowadzona grupa usamodzielniająca dla osób, o których\nmowa w art. 37 ust. 2-6.\n2. Z zastrzeżeniem ust. 3, grupa usamodzielniająca nie może znajdować się na\nterenie tej samej lub bezpośrednio sąsiadującej nieruchomości, co placówka opiekuńczo-\nwychowawcza, w ramach której jest prowadzona. Przepis art. 106 ust. 2a stosuje się\nodpowiednio.\n3. Na terenie tej samej nieruchomości nie mogą być prowadzone więcej niż dwie\ngrupy usamodzielniające.\n4. W jednej grupie usamodzielniającej nie może przebywać więcej niż 5 osób, o\nktórych mowa w ust. 1.\n5. Liczba osób przebywających w grupie usamodzielniającej nie wlicza się do limitu\nliczby dzieci i osób, które osiągnęły pełnoletność przebywając w pieczy zastępczej, o\nktórych mowa w art. 37 ust. 2-4 i 6, oraz osób opuszczających rodzinną pieczę zastępczą\njako niepełnoletnie, o których mowa w art. 37 ust. 5 i 6, wskazanego w art. 95 ust 3.”;\n98) w art. 108 ust. 1 otrzymuje brzmienie:\n„1. Na wniosek dyrektora placówki opiekuńczo-wychowawczej lub na wniosek\nwychowawcy, za zgodą dyrektora placówki opiekuńczo-wychowawczej, po zasięgnięciu\nopinii powiatowego centrum pomocy rodzinie powiatu właściwego do\nponoszenia  miesięcznych wydatków przeznaczonych na utrzymanie dziecka w placówce\nopiekuńczo-wychowawczej określonych na podstawie art. 196, starosta powiatu, który\nskierował dziecko do placówki opiekuńczo-wychowawczej, może przenieść dziecko do\ninnej placówki opiekuńczo-wychowawczej tego samego typu.”;\n99) uchyla się art. 111;\f– 90 –\n100) w art. 112 otrzymuje brzmienie:\n„Art. 112. Regionalne placówki opiekuńczo-terapeutyczne zapewniają\nspecjalistyczną opiekę medyczną i rehabilitację dzieciom umieszczonym w tych\nplacówkach.”;\n101) w art. 113 uchyla się ust. 2;\n102) w art. 121b:\na) ust. 1-3 otrzymują brzmienie:\n„1. Jeżeli jest to niezbędne do zapewnienia bezpieczeństwa dzieci lub osób\nzatrudnionych lub ochrony mienia, w placówce opiekuńczo-wychowawczej oraz\nregionalnej placówce opiekuńczo-terapeutycznej może zostać wprowadzony\nszczególny nadzór nad pomieszczeniami placówki albo ośrodka lub terenem wokół\nplacówki albo ośrodka w formie środków technicznych umożliwiających rejestrację\nobrazu (monitoring).\n2. Monitoring może zostać wprowadzony przez dyrektora:\n1) placówki opiekuńczo-wychowawczej - w uzgodnieniu odpowiednio z\nstarostą albo kierownikiem podmiotu, któremu powiat zlecił prowadzenie\nplacówki opiekuńczo-wychowawczej, o czym informują zarząd powiatu;\n2) regionalnej placówki opiekuńczo-terapeutycznej - w uzgodnieniu\nodpowiednio z marszałkiem województwa albo kierownikiem podmiotu,\nktóremu samorząd województwa zlecił prowadzenie regionalnej placówki\nopiekuńczo-terapeutycznej, o czym informują zarząd województwa.\n3. Monitoring nie stanowi środka nadzoru nad jakością wykonywania pracy\nprzez pracowników placówki opiekuńczo-wychowawczej oraz regionalnej placówki\nopiekuńczo-terapeutycznej.”;\nb) ust. 5 i 6 otrzymują brzmienie:\n„5. Nagrania obrazu zawierające dane osobowe dzieci, osób zatrudnionych i\ninnych osób, które w wyniku tych nagrań można zidentyfikować, placówka\nopiekuńczo-wychowawcza lub regionalna placówka opiekuńczo-terapeutyczna\nprzetwarzają wyłącznie w celu zapewnienia bezpieczeństwa dzieciom lub osobom\nzatrudnionym lub ochrony mienia w tych jednostkach i przechowują przez okres nie\ndłuższy niż 3 miesiące od dnia nagrania.\n6. W przypadku gdy dyrektor placówki opiekuńczo-wychowawczej albo\ndyrektor regionalnej placówki opiekuńczo-terapeutycznej powziął wiadomość, że \f– 91 –\nnagrania obrazu mogą stanowić dowód w postępowaniu prowadzonym na podstawie\nprzepisów prawa, termin określony w ust. 5 ulega przedłużeniu do czasu\nprawomocnego zakończenia postępowania. Nagrania te są przekazywane\nwłaściwemu organowi prowadzącemu postępowanie.”;\nc) ust. 8-11 otrzymują brzmienie:\n„8. Dyrektor placówki opiekuńczo-wychowawczej albo dyrektor regionalnej\nplacówki opiekuńczo-terapeutycznej informuje dzieci i osoby zatrudnione w\nplacówce o wprowadzeniu monitoringu, w sposób przyjęty w tej placówce, nie\npóźniej niż 14 dni przed uruchomieniem monitoringu.\n9. Dyrektor placówki opiekuńczo-wychowawczej albo dyrektor regionalnej\nplacówki opiekuńczo-terapeutycznej przed dopuszczeniem osoby do wykonywania\nobowiązków służbowych informuje ją na piśmie o prowadzeniu monitoringu.\n10. W przypadku wprowadzenia monitoringu dyrektor placówki opiekuńczo-\nwychowawczej albo dyrektor regionalnej placówki opiekuńczo-terapeutycznej\noznacza pomieszczenia i teren monitorowany w sposób widoczny i czytelny, za\npomocą odpowiednich znaków lub ogłoszeń dźwiękowych, nie później niż dzień\nprzed jego uruchomieniem.\n11. Dyrektor placówki opiekuńczo-wychowawczej albo dyrektor regionalnej\nplacówki opiekuńczo-terapeutycznej uzgadnia odpowiednio ze starostą albo z\nmarszałkiem województwa, albo odpowiednim podmiotem, o którym mowa w ust.\n2, środki techniczne i organizacyjne w celu ochrony przechowywanych nagrań\nobrazu oraz danych osobowych dzieci, osób zatrudnionych i innych osób, które w\nwyniku tych nagrań można zidentyfikować, uzyskanych w wyniku monitoringu, a\nnastępnie wprowadza te środki techniczne.”;\nd) po ust. 11 dodaje się ust. 12 w brzmieniu:\n„12. Dyrektor placówki opiekuńczo-wychowawczej albo dyrektor regionalnej\nplacówki opiekuńczo-terapeutycznej, niezwłocznie po przyjęciu dziecka do\nplacówki opiekuńczo-wychowawczej albo do regionalnej placówki opiekuńczo-\nterapeutycznej, informuje je, w sposób dostosowany do jego wieku i stopnia\ndojrzałości, o prowadzeniu monitoringu.”;\n103) art. 122 i 122a otrzymują brzmienie:\n„Art. 122. 1. Wojewoda sprawuje kontrolę nad działalnością placówek opiekuńczo-\nwychowawczych oraz regionalnych placówek opiekuńczo- terapeutycznych.\f– 92 –\n2. W przypadku, o którym mowa w art. 93 ust. 2a, kontrolę nad działalnością\nplacówek opiekuńczo-wychowawczej sprawuje wojewoda właściwy dla powiatu, o\nktórym mowa w art. 35b ust. 5, chyba że porozumienia, o którym mowa w art. 35b ust. 6\nstanowi inaczej.\nArt. 122a. Kontrola nad placówkami opiekuńczo-wychowawczymi i regionalnymi\nplacówkami opiekuńczo-terapeutycznymi obejmuje w szczególności:\n1) przestrzeganie standardów opieki i wychowania, o których mowa w przepisach\ndotyczących placówek opiekuńczo-wychowawczych i regionalnych placówek\nopiekuńczo-terapeutycznych;\n2) przestrzeganie standardów ochrony małoletnich, o których mowa w ustawie z dnia 13\nmaja 2016 r. o przeciwdziałaniu zagrożeniem przestępczości na tle seksualnym i\nochronie małoletnich;\n3) działania placówki na rzecz utrzymania przez dziecko kontaktów z rodziną;\n4) działania placówki na rzecz dobra dziecka, w tym zaspokajanie potrzeb dziecka i\nrespektowanie jego praw;\n5) przestrzeganie przepisów określających zasady działania placówki opiekuńczo-\nwychowawczej i regionalnej placówki opiekuńczo-terapeutycznej.”;\n104) art. 127 otrzymuje brzmienie:\n„Art. 127. Minister właściwy do spraw rodziny określi, w drodze rozporządzenia:\n1) tryb i sposób kierowania i przyjmowania dziecka do placówki opiekuńczo-\nwychowawczej, i regionalnej placówki opiekuńczo-terapeutycznej oraz ich\nopuszczania, z uwzględnieniem dzieci cudzoziemców,\n2) organizację placówek, o których mowa w pkt 1, w tym:\na) maksymalną liczbę dzieci pozostających pod opieką jednego wychowawcy\noraz innych osób pracujących z dziećmi, w zależności od organizacji pracy\ni potrzeb dzieci,\nb) warunki sprawowania opieki w godzinach nocnych,\nc) organizację pracy wychowawczej, w tym tryb przeprowadzania diagnozy\npsychofizycznej dziecka,\nd) prowadzoną dokumentację dotyczącą dziecka,\n3) standardy usług świadczonych w placówkach, o których mowa w pkt 1, w tym w\nramach grup usamodzielniających;\f– 93 –\n4) wzór wniosku o wydanie zezwolenia na prowadzenie placówki, o którym mowa w pkt\n1\n- uwzględniając zadania realizowane przez placówki opiekuńczo-wychowawcze\noraz regionalne placówki opiekuńczo-terapeutyczne, potrzebę zapewnienia\nprawidłowego funkcjonowania tych placówek oraz odpowiedniego poziomu\nświadczonych usług, a także kontaktów dziecka z jego rodziną.”;\n105) w art. 129 po pkt 7 kropkę zastępuje się średnikiem i dodaje się pkt 8 w brzmieniu:\n„8) opracowania zindywidualizowanej diagnozy sytuacji dziecka, o której mowa w art.\n139aa.”;\n106) w art. 130:\na) w ust 1:\n- pkt 5 otrzymuje brzmienie:\n„5) przedstawiciela ośrodka adopcyjnego w sytuacji, kiedy ocena sytuacji\ndziecka dotyczy dziecka, którego rodzice zostali pozbawieni władzy\nrodzicielskiej, wyrazili zgodę na adopcję bez wskazywania osoby\nprzysposabiającego lub nie żyją;”,\n- po pkt 7 kropkę zastępuje się średnikiem i dodaje się pkt 8-10 w brzmieniu:\n„8) opiekuna usamodzielnienia, jeżeli został ustanowiony;\n9) przedstawiciela ministra właściwego do spraw rodziny, w sytuacji, o której\nmowa w art. 164 ust. 11a pkt 2;\n10) przedstawiciela organu centralnego w sytuacji, o której mowa w art. 164 ust.\n19 pkt 2.”\nb) ust. 2 otrzymuje brzmienie:\n„2. Do udziału w posiedzeniu w sprawie sytuacji dziecka umieszczonego\nw rodzinnej pieczy zastępczej mogą być zapraszani w szczególności przedstawiciele\nodpowiednio, zgodnych z właściwością: sądu, powiatowego centrum pomocy\nrodzinie, ośrodka pomocy społecznej, centrum usług społecznych, Policji, ochrony\nzdrowia, instytucji oświatowych, a także inne podmioty i osoby działające na rzecz\ndziecka i rodziny, osoby bliskie dziecku, a także przedstawiciel ośrodka adopcyjnego\nw przypadkach innych niż wskazane w ust. 1 pkt 5.”;\f– 94 –\n107) w art. 131:\na) ust. 2 otrzymuje brzmienie:\n„2. Po dokonaniu oceny sytuacji dziecka organizator rodzinnej pieczy\nzastępczej formułuje ją na piśmie wraz z opinią dotyczącą zasadności dalszego\npobytu dziecka w pieczy zastępczej, a następnie przekazuje je do właściwego sądu.”;\nb) po ust. 2 dodaje się ust. 3 w brzmieniu:\n„3. W przypadku gdy dziecko dla którego dokonywana jest ocena sytuacji\nzostało zgłoszone do ośrodka adopcyjnego, ocena ta wraz z opinią dotyczącą\nzasadności dalszego pobytu dziecka w pieczy zastępczej przekazywana jest do\nwłaściwego ośrodka adopcyjnego.”;\n108) w art. 134:\na) ust. 2a- 2d otrzymują brzmienie:\n„2a. Do ocen, o których mowa w ust. 1 i 2, w terminie 14 dni od dnia otrzymania\noceny, rodzina zastępcza i prowadzący rodzinny dom dziecka mogą złożyć\nodpowiednio do starosty albo pozarządowego organizatora rodzinnej pieczy\nzastępczej, zastrzeżenia.\n2b. Starosta albo pozarządowy organizator rodzinnej pieczy zastępczej\nrozpatruje zastrzeżenia w terminie 30 dni od dnia ich otrzymania.\n2c. W przypadku, gdy starosta albo pozarządowy organizator rodzinnej pieczy\nzastępczej nie rozpatrzy zastrzeżeń, o których mowa w ust. 2a, w terminie, o którym\nmowa w ust. 2b, uznaje się, że zastrzeżenia te zostały przez starostę albo\npozarządowego organizatora rodzinnej pieczy zastępczej, uwzględnione.\n2d. W razie uwzględnienia przez starostę albo pozarządowego organizatora\nrodzinnej pieczy zastępczej, zastrzeżeń, ocenę rodziny zastępczej albo\nprowadzącego rodzinny dom dziecka sporządza się po raz drugi. Do oceny\nsporządzonej po raz drugi przysługują zastrzeżenia na zasadach określonych w ust.\n2a-2c.”\nb) ust. 4 otrzymuje brzmienie:\n„4. W przypadku rodzin zastępczych zawodowych oraz rodzinnych domów\ndziecka w celu ustalenia zasadności podpisania umowy rodzicielstwa zastępczego, o\nktórej mowa w 55 ust. 1aa, oceny dokonuje się także na trzy miesiące przed\nwygaśnięciem umowy o której mowa w 55 ust. 1aa.”;\f– 95 –\n109) art. 135 otrzymuje brzmienie:\n„Art. 135. W placówce opiekuńczo-wychowawczej typu socjalizacyjnego,\ninterwencyjnego i specjalistyczno-terapeutycznego albo regionalnej placówce\nopiekuńczo-terapeutycznej zespół do spraw okresowej oceny sytuacji dziecka, zwany\ndalej „zespołem”, ocenia sytuację umieszczonego dziecka.”;\n110) w art. 136 po pkt 7 kropkę zastępuje się średnikiem i dodaje się pkt 8 w brzmieniu:\n„8) opracowania zindywidualizowanej diagnozy sytuacji dziecka, o której mowa w art.\n139aa.”;\n111) w art. 137:\na) w ust 1:\n- po pkt 5a dodaje się pkt 5b-5e w brzmieniu:\n„5b) przedstawiciel ośrodka adopcyjnego w sytuacji, kiedy ocena sytuacji\ndziecka dotyczy dziecka, którego rodzice zostali pozbawieni władzy\nrodzicielskiej, wyrazili zgodę na adopcję bez wskazywania osoby\nprzysposabiającego lub nie żyją;\n5c) opiekun usamodzielnienia, jeżeli został ustanowiony;\n5d) przedstawiciel ministra właściwego do spraw rodziny, w sytuacji, o której\nmowa w art. 164 ust. 11a pkt 2;\n5e) przedstawiciel organu centralnego w sytuacji, o której mowa w art. 164 ust.\n19 pkt 2.”,\n- pkt 6 otrzymuje brzmienie:\n„6) inne osoby, w szczególności asystent rodziny prowadzący pracę z rodziną\ndziecka.”;\nb) ust. 2 otrzymuje brzmienie:\n„2. Do udziału w posiedzeniu zespołu mogą być zapraszani w szczególności\nprzedstawiciele odpowiednio, zgodnych z właściwością: sądu, powiatowego\ncentrum pomocy rodzinie, ośrodka pomocy społecznej, centrum usług społecznych,\nPolicji, ochrony zdrowia, instytucji oświatowych, a także inne podmioty i osoby\ndziałające na rzecz dziecka i rodziny, osoby bliskie dziecku, a także przedstawiciel\nośrodka adopcyjnego w przypadkach innych niż wskazane w ust. 1 pkt 5b.”;\f– 96 –\n112) w art. 138:\na) ust. 2 otrzymuje brzmienie:\n„2. Po dokonaniu okresowej oceny sytuacji dziecka zespół formułuje ją na\npiśmie wraz z opinią dotyczącą zasadności dalszego pobytu dziecka w placówce, a\nnastępnie przekazuje je do właściwego sądu.”,\nb) ust. 3 otrzymuje brzmienie:\n„3. W przypadku gdy dziecko dla którego dokonywana jest ocena sytuacji\nzostało zgłoszone do ośrodka adopcyjnego, ocena ta wraz z opinią dotyczącym\nzasadności dalszego pobytu dziecka w placówce przekazywana jest do właściwego\nośrodka adopcyjnego.”;\n113) w art. 139 po ust. 1 dodaje się ust. 1a w brzmieniu:\n„1a. Do udziału w ocenie sytuacji dziecka mogą być zapraszani w szczególności\nprzedstawiciele odpowiednio, zgodnych z właściwością: sądu, powiatowego centrum\npomocy rodzinie, ośrodka pomocy społecznej, centrum usług społecznych, Policji,\nochrony zdrowia, instytucji oświatowych, a także inne podmioty i osoby działające na\nrzecz dziecka i rodziny, osoby bliskie dziecku, a także przedstawiciel ośrodka\nadopcyjnego.”;\n114) w art. 139a w ust. 1 pkt 6 otrzymuje brzmienie:\n„6) przekazywanie właściwemu ośrodkowi adopcyjnemu informacji i dokumentacji, o\nktórych mowa w art. 38a oraz wizerunku dziecka.”;\n115) po art. 139a dodaje się art. 139aa w brzmieniu:\n„Art. 139aa. 1. Organizator rodzinnej pieczy zastępczej, zespół do spraw okresowej\noceny dziecka lub dyrektor placówki opiekuńczo-wychowawczej typu rodzinnego,\npodczas dokonywania okresowej oceny sytuacji dziecka bezpośrednio przed\nukończeniem przez dziecko 16. roku życia, opracowuje, we współpracy w szczególności\nz dzieckiem oraz ze specjalistami w zakresie szkolnictwa, rozwoju zawodowego, a także\nrynku pracy, zindywidualizowaną diagnozę sytuacji dziecka.\n2. Zindywidualizowana diagnoza sytuacji dziecka zawiera w szczególności opis jego\npotrzeb i oczekiwań, mocnych stron oraz obszarów wymagających wsparcia, a także\nsytuacji rodzinnej, psychospołecznej oraz predyspozycji zawodowych, sporządzony pod\nkątem rozpoczęcia procesu usamodzielnienia.\f– 97 –\n3. Zindywidualizowaną diagnozę sytuacji dziecka, organizator rodzinnej pieczy\nzastępczej przekazuje rodzinie zastępczej lub osobie prowadzącej rodzinny dom dziecka,\nw której dziecko przebywa.\n4. Zindywidualizowaną diagnozę sytuacji dziecka, organizator rodzinnej pieczy\nzastępczej, zespół do spraw okresowej oceny dziecka lub dyrektor placówki opiekuńczo-\nwychowawczej typu rodzinnego, przekazuje dziecku oraz opiekunowi usamodzielnienia-\npo jego wyznaczeniu.”;\n116) w dziale IV dodaje się art. 139c-139i w brzmieniu:\n„Art. 139c. 1. Osobą usamodzielnianą, jest osoba, która ukończyła 16. rok życia,\nprzebywająca w rodzinie zastępczej, rodzinnym domu dziecka, placówce opiekuńczo-\nwychowawczej lub regionalnej placówce opiekuńczo-terapeutycznej, w przypadku gdy\numieszczenie w pieczy zastępczej nastąpiło na podstawie orzeczenia sądu, która\nrozpoczyna proces usamodzielnienia.\n2. Celem procesu usamodzielnienia jest w szczególności przygotowanie osoby\nusamodzielnianej do podjęcia samodzielnego i dojrzałego życia w integracji ze\nśrodowiskiem lokalnym w sposób dostosowany do aspiracji, potrzeb i możliwości tej\nosoby.\n3. Proces usamodzielnienia trwa nie dłużej niż do ukończenia przez osobą\nusamodzielnianą 26 roku życia.\nArt. 139d. Wsparcie osób usamodzielnianych, w tym osób usamodzielnianych\nopuszczających, po osiągnięciu pełnoletności, rodzinę zastępczą, rodzinny dom dziecka,\nplacówkę opiekuńczo-wychowawczą lub regionalną placówkę opiekuńczo-terapeutyczną\norganizuje powiat lub podmiot, któremu powiat zlecił realizację tego zadania na\npodstawie art. 190.\nArt. 139e. 1. Osoba usamodzielniana w terminie do 3 miesięcy od ukończenia przez\nnią 16. roku życia informuje kierownika jednostki organizacyjnej powiatu właściwego ze\nwzględu na miejsce pobytu osoby usamodzielnianej lub kierownika podmiotu, któremu\npowiat zlecił organizację wsparcia osób usamodzielnianych na podstawie art. 190, o\nwyborze opiekuna usamodzielnia oraz przedstawia pisemną zgodę tej osoby.\n2. Kierownik jednostki organizacyjnej powiatu lub podmiotu, o których mowa w ust.\n1, po sprawdzeniu spełniania warunków, o których mowa w art. art. 7b ust. 1 oraz art.\n139f ust. 1, przez osobę wskazaną do pełnienia funkcji opiekuna usamodzielnienia,\nzatwierdza opiekuna usamodzielnienia.\f– 98 –\n3. Kierownik jednostki organizacyjnej powiatu lub podmiotu, o których mowa w ust.\n2, informuje osobę usamodzielnianą, oraz odpowiednio rodzinę zastępczą, rodzinny dom\ndziecka, dyrektora placówki opiekuńczo-wychowawczej lub regionalnej placówki\nopiekuńczo-terapeutycznej, w których osoba usamodzielniana przebywa, a także\norganizatora rodzinnej pieczy zastępczej i zespół do spraw okresowej oceny dziecka, o\nzatwierdzeniu opiekuna usamodzielnienia.\n4. W przypadku umieszczenia dziecka w pieczy zastępczej po ukończeniu przez nie\n16. roku życia, termin, o którym mowa w ust. 1 rozpoczyna się od dnia umieszczenia\ndziecka w pieczy zastępczej.\n5. W przypadku niewskazania w terminie, o którym mowa w ust. 1 i ust. 4, osoby,\nktóra podejmuje się pełnienia funkcji opiekuna usamodzielnienia lub nieuzyskania przez\ntę osobę zatwierdzenia kierownika jednostki organizacyjnej powiatu lub podmiotu o\nktórych mowa w ust. 2, opiekuna usamodzielnienia wyznacza kierownik tej jednostki lub\npodmiotu.\n6. Tryb określony w ust. 1-5 stosuje się odpowiednio w przypadku zmiany opiekuna\nusamodzielnienia.\nArt. 139f. 1. Opiekunem usamodzielnienia może być osoba, która poprzez swoje\npredyspozycje, doświadczenie lub wykształcenie daje rękojmię długofalowej realizacji\ndziałań przyczyniających się do uzyskania przez osobę usamodzielnianą samodzielności,\noraz która:\n1) nie jest i nie była pozbawiona władzy rodzicielskiej oraz władza rodzicielska nie jest\nani nie była jej zawieszona ani ograniczona;\n2) wypełnia obowiązek alimentacyjny - w przypadku gdy taki obowiązek w stosunku do\nnich wynika z tytułu egzekucyjnego.\n2. Powiat lub podmiot, któremu powiat zlecił organizację wsparcia osób\nusamodzielnianych na podstawie art. 190, jest zobowiązany do zatrudnienia opiekuna\nusamodzielnienia dla osoby usamodzielnianej, która przebywa w placówce opiekuńczo-\nwychowawczej lub regionalnej placówce opiekuńczo-terapeutycznej lub osoby\nusamodzielnianej, która opuściła placówkę opiekuńczo-wychowawczą lub regionalną\nplacówkę opiekuńczo-terapeutyczną.\n3. Powiat lub podmiot, któremu powiat zlecił organizację wsparcia osób\nusamodzielnianych na podstawie art. 190, może zatrudnić opiekuna usamodzielnienia dla\nosoby usamodzielnianej, która przebywa w rodzinie zastępczej lub rodzinnym domu \f– 99 –\ndziecka lub osoby usamodzielnianej, która opuściła rodzinę zastępczą lub rodzinny dom\ndziecka.\n4. Powiat lub podmiot, któremu powiat zlecił organizację wsparcia osób\nusamodzielnianych na podstawie art. 190, zatrudniający opiekuna usamodzielnienia\nzapewnia dostęp do wsparcia merytorycznego i edukacyjnego dla opiekuna\nusamodzielnienia, dostosowanego do lokalnych potrzeb i specyfiki pracy, w\nszczególności poprzez umożliwienie udziału w szkoleniach, konsultacjach\nspecjalistycznych lub grupach wsparcia oraz dostęp do informacji o formach wsparcia\ndostępnych dla młodzieży pomocnych w procesie usamodzielnienia.\n5. Praca opiekuna usamodzielnienia jest wykonywana w ramach stosunku pracy w\nsystemie zadaniowego czasu pracy albo umowy o świadczenie usług, do której, zgodnie\nz ustawą z dnia 23 kwietnia 1964 r. - Kodeks cywilny, stosuje się przepisy dotyczące\nzlecenia.\n6. Opiekun usamodzielnienia dla osoby usamodzielnianej przebywającej w\nplacówce opiekuńczo-wychowawczej lub regionalnej placówce opiekuńczo-\nterapeutycznej lub osoby usamodzielnianej, która opuściła placówkę opiekuńczo-\nwychowawczą lub regionalną placówkę opiekuńczo-terapeutyczną otrzymuje\nwynagrodzenie za pełnienie funkcji opiekuna usamodzielnienia w wysokości nie niższej\nniż 300 zł miesięcznie za każdą z osób usamodzielnianych przebywających w placówce\nopiekuńczo-wychowawczej lub regionalnej placówce opiekuńczo-terapeutycznej lub\nosób usamodzielnianych, które opuściły placówkę opiekuńczo-wychowawczą lub\nregionalną placówkę opiekuńczo-terapeutyczną, dla których pełni tę funkcję. Artykuł 86\nust. 2- 3 i art. 91 stosuje się odpowiednio.\n7. Osoba zatrudniona w placówce opiekuńczo-wychowawczej lub regionalnej\nplacówce opiekuńczo-terapeutycznych może być opiekunem usamodzielnienia dla nie\nwięcej niż 3 osób usamodzielnianych.”;\nArt. 139g. Do zadań opiekuna usamodzielnienia należy podejmowanie działań, które\nprzyczynią się do uzyskania samodzielności przez osobę usamodzielnianą,\nw szczególności poprzez wspieranie tej osoby oraz współpracę z podmiotami\npublicznymi i niepublicznymi, których działalność może wspierać proces\nusamodzielnienia.\nArt. 139h. 1. Osoba usamodzielniana wspólnie z opiekunem usamodzielnienia\nw terminie do 1. miesięca od dnia zatwierdzenia opiekuna usamodzielnienia, na \f– 100 –\npodstawie zindywidualizowanej diagnozy sytuacji dziecka, o której mowa w art. 139aa,\nopracowuje indywidualny program usamodzielnienia.\n2. Indywidualny program usamodzielnienia, określa w szczególności:\n1) zakres współdziałania osoby usamodzielnianej z opiekunem usamodzielnienia;\n2) sposób uzyskania przez osobę usamodzielnianą wykształcenia lub kwalifikacji\nzawodowych, pomocy w uzyskaniu odpowiednich warunków mieszkaniowych\noraz w podjęciu przez osobę usamodzielnianą zatrudnienia.\n3) miejsce, w którym wychowanek zamierza się osiedlić po opuszczeniu pieczy\nzastępczej, o ile jest ono już znane;\n4) terminy realizacji poszczególnych działań, w szczególności orientacyjne terminy\nubiegania się o świadczenia finansowe na realizację programu\nusamodzielnienia, w tym na kontynuowanie nauki, usamodzielnienie lub\nzagospodarowanie;\n5) sposób wydatkowania zgromadzonych przez osobę usamodzielnianą środków\nfinansowych, w szczególności środków ze świadczenia wychowawczego, o ile\nzostały zgromadzone.\n3. Indywidualny program usamodzielnienia jest zatwierdzany przez kierownika\njednostki organizacyjnej powiatu właściwego ze względu na miejsce pobytu osoby\nusamodzielniane lub kierownik podmiotu, któremu powiat zlecił organizację wsparcia\nosób usamodzielnianych na podstawie art. 190.\n4. Kierownik jednostki organizacyjnej powiatu lub podmiotu, o których mowa w ust.\n3, informuje powiat właściwy ze względu na planowane miejsce osiedlenia się osoby\nusamodzielnianej o zamiarze osiedlenia się tej osoby w miejscowości wskazanej w\nindywidualnym programie usamodzielnienia oraz przesyła mu kopię tego programu i\ninformacje o opiekunie usamodzielnienia.\n5. Aktualizacja indywidualnego programu usamodzielnienia jest dokonywana w\nprzypadku każdej zmiany sytuacji osoby usamodzielnianej mającej wpływ na informacje\nzawarte indywidualnym programie usamodzielnienia, jednak nie rzadziej niż co pół roku,\ni jest przekazywana kierownikowi jednostki organizacyjnej powiatu lub podmiotu, o\nktórych mowa w ust. 3.\n6. Zmiany indywidualnego programu usamodzielnienia wymagają zatwierdzenia\nprzez kierownika jednostki organizacyjnej powiatu lub podmiotu, o których mowa w ust.\n3.\f– 101 –\n7. Po zakończeniu realizacji indywidualnego programu usamodzielnienia osoba\nusamodzielniana wraz z opiekunem usamodzielnienia i kierownikiem jednostki\norganizacyjnej powiatu lub podmiotu, o których mowa w ust. 3, dokonują oceny\nkońcowej procesu usamodzielnienia.\n8. Po roku od dokonania oceny końcowej procesu usamodzielnienia kierownik\njednostki organizacyjnej powiatu lub podmiotu, który zatwierdził opiekuna\nusamodzielnienia we współpracy z osobą, która zakończyła proces usamodzielnienia\nprzeprowadza ocenę efektywności procesu usamodzielnienia, w tym efekty współpracy\nwychowanka z opiekunem usamodzielnienia, w szczególności poprzez analizę sytuacji\nosobistej i zawodowej osoby, która zakończyła proces usamodzielnienia.\nArt. 139i. Minister właściwy do spraw rodziny może określić oraz zamieścić w\nBiuletynie Informacji Publicznej wzór indywidualnego programu usamodzielnienia, o\nktórym mowa w art. 139h ust. 1 lub wzór oceny końcowej procesu usamodzielnienia, o\nktórej mowa w art. 139h ust. 8.”;\n117) w art. 140:\na) w ust. 1 wprowadzenie do wyliczenia otrzymuje brzmienie:\n„Osobie usamodzielnianej opuszczającej, po osiągnięciu pełnoletności, rodzinę\nzastępczą, rodzinny dom dziecka, placówkę opiekuńczo-wychowawczą lub\nregionalną placówkę opiekuńczo-terapeutyczną, w przypadku gdy umieszczenie w\npieczy zastępczej nastąpiło na podstawie orzeczenia sądu:”,\nb) ust. 2 i 3 otrzymują brzmienie:\n„2. Pomoc, o której mowa w ust. 1, przysługuje także osobie, której pobyt w\nrodzinnej pieczy zastępczej ustał na skutek śmierci osób tworzących rodzinę\nzastępczą lub osoby prowadzącej rodzinny dom dziecka, w okresie 6 miesięcy przed\nosiągnięciem przez osobę usamodzielnianą pełnoletności.\n3. W przypadku gdy osoba usamodzielniana:\n1) przebywa w domu pomocy społecznej albo placówce zapewniającej\ncałodobową opiekę osobom niepełnosprawnym lub przewlekle chorym,\n2) otrzymuje pomoc dla osób usamodzielnianych w rozumieniu przepisów o\npomocy społecznej\n- pomoc, o której mowa w ust. 1 i 4, nie przysługuje.”;\f– 102 –\nc) po ust. 3 dodaje się ust. 4 w brzmieniu:\n„4. Osobie usamodzielnianej opuszczającej, po osiągnięciu pełnoletności,\nrodzinę zastępczą, rodzinny dom dziecka, placówkę opiekuńczo-wychowawczą lub\nregionalną placówkę opiekuńczo-terapeutyczną starosta powiatu właściwego do\nponoszenia wydatków na finansowanie pomocy na kontynuowanie nauki i\nusamodzielnienie może przyznać pomoc na pokrycie kosztów związanych z\nwystąpieniem zdarzeń losowych lub innych zdarzeń mających wpływ przebieg\nprocesu usamodzielnienia - jednorazowo lub okresowo. Przepis ust. 2, art. 151 ust. 1\ni 3 oraz 152a stosuje się odpowiednio.”;\n118) w art. 143:\na) ust. 1 i 2 otrzymują brzmienie:\n„1. Pomoc, o której mowa w art. 140 ust. 1 i 4, jest przyznawana lub udzielana\nna wniosek osoby usamodzielnianej.\n2. Wniosek o przyznanie pomocy na kontynuowanie nauki i pomocy na\nusamodzielnienie osoba usamodzielniana składa w powiecie właściwym ze względu\nna miejsce pobytu osoby usamodzielnianej.”,\nb) po ust. 3 dodaje się ust. 3a w brzmieniu:\n„3a. Wniosek o przyznanie pomocy na pokrycie kosztów związanych z\nwystąpieniem zdarzeń losowych lub innych zdarzeń mających wpływ przebieg\nprocesu usamodzielnienia osoba usamodzielniana składa w powiecie właściwym do\nponoszenia wydatków na finansowanie pomocy na kontynuowanie nauki i\nusamodzielnienie za pośrednictwem kierownika powiatowego centrum pomocy\nrodzinie powiatu właściwego ze względu na miejsce pobytu osoby\nusamodzielnianej.”;\n119) w art. 145:\na) ust. 1 otrzymuje brzmienie:\n„1. Warunkiem przyznania pomocy na kontynuowanie nauki i na\nusamodzielnienie oraz pomocy na pokrycie kosztów związanych z wystąpieniem\nzdarzeń losowych lub innych zdarzeń mających wpływ przebieg procesu\nusamodzielnienia jest złożenie wniosku oraz posiadanie zatwierdzonego\nindywidualnego programu usamodzielnienia.”,\nb) ust. 2-7 uchyla się,\f– 103 –\nc) ust. 8 otrzymuje brzmienie:\n„8. W szczególnie uzasadnionych przypadkach pomoc na kontynuowanie nauki\ni na usamodzielnienie oraz pomoc na pokrycie kosztów związanych z wystąpieniem\nzdarzeń losowych lub innych zdarzeń mających wpływ przebieg procesu\nusamodzielnienia mogą być przyznane osobie usamodzielnianej, której\nindywidualny program usamodzielnienia został zatwierdzony później w terminie, o\nktórym mowa w art. 139h ust. 1.”;\n120) w art. 146 ust. 2 otrzymuje brzmienie:\n„2. Wysokość pomocy, o której mowa w ust. 1, wynosi nie mniej niż 1300\nzł miesięcznie.”;\n121) w art. 149 w ust. 1 pkt 1 i 2 otrzymuje brzmienie:\n„1) w przypadku osoby usamodzielnianej opuszczającej rodzinę zastępczą spokrewnioną\n- nie mniej niż 5364 zł, jeżeli przebywała w pieczy zastępczej przez okres co\nnajmniej 3 lat;\n2) w przypadku osoby usamodzielnianej opuszczającej rodzinę zastępczą niezawodową,\nrodzinę zastępczą zawodową, rodzinny dom dziecka, placówkę opiekuńczo-\nwychowawczą lub regionalną placówkę opiekuńczo-terapeutyczną:\na) nie mniej niż 10723 zł - jeżeli przebywała w pieczy zastępczej przez okres\npowyżej 3 lat,\nb) nie mniej niż 5364 zł - jeżeli przebywała w pieczy zastępczej przez okres od 2 do\n3 lat,\nc) nie mniej niż 2683 zł - jeżeli przebywała w pieczy zastępczej przez okres poniżej\n2 lat, nie krócej jednak niż przez okres roku.”;\n122) w art. 150 ust. 1 otrzymuje brzmienie:\n„1. Pomoc na zagospodarowanie jest wypłacana jednorazowo, nie później niż do\nukończenia przez osobę usamodzielnianą 26. roku życia, w wysokości nie niższej\nniż 2438 zł, a w przypadku osoby legitymującej się orzeczeniem o umiarkowanym albo\nznacznym stopniu niepełnosprawności w wysokości nie niższej niż 4875 zł.”;\n123) art. 153 otrzymuje brzmienie:\n„Art. 153. Do pomocy dla osób usamodzielnianych przepisy art. 86 ust. 2- 3 i art.\n92 stosuje się odpowiednio.”;\f– 104 –\n124) po art. 153 dodaje się art. 153a i 153b w brzmieniu:\n„Art. 153a. Rada powiatu może, w drodze uchwały, podnieść wysokość pomocy\nna kontynuowanie nauki, usamodzielnienie, zagospodarowanie, jak również określić\nkryteria uzyskania pomocy w wyższej wysokości.\nArt. 153b. Kierownik jednostki organizacyjnej powiatu może upoważnić\npracownika jednostki organizacyjnej powiatu do wykonywania czynności o których\nmowa w art. 139e i art. 139h.”;\n125) w art. 154:\na) ust. 4 otrzymuje brzmienie:\n„4. Minister właściwy do spraw rodziny prowadzi centralny rejestr ośrodków\nadopcyjnych z podziałem na województwa na terenie których działa dany ośrodek\nadopcyjny.\",\nb) po ust. 4 dodaje się ust. 5 w brzmieniu:\n„5. Marszałek lub upoważniony przez niego pracownik urzędu\nmarszałkowskiego lub innej jednostki organizacyjnej województwa, informuje na\npiśmie ministra właściwego do spraw rodziny, o powstawaniu, likwidacji lub\nzmianie danych teleadresowych ośrodka adopcyjnego.\";\n126) w art. 155 po ust. 2 dodaje się ust. 3 w brzmieniu:\n„3. W sytuacji, gdy ośrodek adopcyjny, organizator rodzinnej pieczy zastępczej,\ndyrektor placówki opiekuńczo-wychowawczej lub dyrektor regionalnej placówki\nopiekuńczo-terapeutycznej uzyska informacje o utrudnianiu podejmowania czynności\nzwiązanych z przysposobieniem dziecka przez osoby spokrewnione lub spowinowacone\ndziecka, informuje o tym sąd celem rozważenia zasadności zastosowania przez sąd zakazu\nkontaktów z dzieckiem.”;\n127) w art. 155a:\na) w ust. 2:\n- pkt 2 i 3 otrzymują brzmienie:\n„2) ośrodek adopcyjny w zakresie prowadzenia procedur adopcyjnych i\nprzetwarzanych danych osobowych, w tym zapewnienia ochrony danych\nosobowych w nim zawartych;\n3) marszałek województwa w zakresie nadawania i cofania uprawnień dostępu\ndo systemu ośrodkom adopcyjnym, zapewnienia ochrony danych \f– 105 –\nosobowych w nim zawartych oraz sprawowania kontroli nad jakością\nprowadzonych procedur przysposobienia.”;\n- po pkt 3 kropkę zastępuje się średnikiem i dodaje się pkt 4 w brzmieniu:\n„4) wojewoda w zakresie zapewnienia ochrony danych osobowych w nim\nzawartych oraz sprawowania kontroli nad jakością prowadzonych procedur\nprzysposobienia.”;\nb) ust. 4 otrzymuje brzmienie:\n„4. Podmiot, o którym mowa w ust. 2 pkt 2, dokonuje w systemie, o którym\nmowa w ust. 1, pseudonimizacji danych dziecka niezwłocznie po nieuzyskaniu albo\nutracie przez dziecko kwalifikacji do przysposobienia. Podmiot ten przechowuje\ndane, w tym dane poddane pseudonimizacji, przez okres roku od dnia ukończenia\nprzez daną osobę 18. roku życia. Dane usuwa się niezwłocznie po upływie okresów\nprzechowywania.”;\nc) po ust. 4 dodaje się ust. 4a w brzmieniu:\n„4a. Podmiot, o którym mowa w ust. 2 pkt 2 usuwa dane przysposobionego\noraz przysposabiających po upływie 50 lat od uprawomocnienia się postanowienia o\nprzysposobieniu.”;\nd) ust. 5 zdanie pierwsze otrzymuje brzmienie:\n„5. Podmiot, o którym mowa w ust. 2 pkt 2, dokonuje w systemie, o którym\nmowa w ust. 1, pseudonimizacji danych kandydata do przysposobienia dziecka po\nupływie 3 lat od:\n1) utraty ważności pozytywnej opinii kwalifikacyjnej wydanej\nkandydatowi do przysposobienia dziecka,\n2) wydania kandydatowi do przysposobienia dziecka negatywnej opinii\nkwalifikacyjnej;\n3) rezygnacji kandydata do przysposobienia dziecka z udziału w\nprocedurze adopcyjnej lub\n4) wydania kandydatowi negatywnej wstępnej oceny kandydata do\nprzysposobienia dziecka”;\n128) w art. 156:\na) w ust. 1:\n- pkt 1 otrzymuje brzmienie:\n„1) kwalifikacja dzieci zgłoszonych do przysposobienia;”,\f– 106 –\n- po pkt 1a dodaje się pkt 1b w brzmieniu:\n„1b) aktualizacja diagnozy psychologicznej i pedagogicznej dla dziecka\nzakwalifikowanego do przysposobienia;”,\n- pkt 5 otrzymuje brzmienie:\n„5) gromadzenie i aktualizowanie informacji o dzieciach, które mogą być\nprzysposobione, w tym gromadzenie aktualnych informacji o ich stanie\nzdrowia;”,\n- pkt 11a otrzymuje brzmienie:\n„11a) prowadzenie szkoleń dla kandydatów do pełnienia funkcji rodziny\nzastępczej lub prowadzenia rodzinnego domu dziecka, a także szkolenia\nuzupełniającego w zakresie pełnienia funkcji rodziny zastępczej\nniezawodowej oraz wydawanie świadectw ukończenia tych szkoleń;”,\n- pkt 9 otrzymuje brzmienie:\n\"9) zapewnienie pomocy psychologicznej oraz wsparcia pedagogicznego\nkandydatom do przysposobienie dziecka oraz osobom, które przysposobiły\ndziecko;\",\n- po pkt 13 kropkę zastępuje się średnikiem i dodaje się pkt 14-17 w brzmieniu:\n„14) koordynowanie współpracy, w szczególności, pomiędzy rodziną zastępczą,\nprowadzącym rodzinny dom dziecka, organizatorem rodzinnej pieczy\nzastępczej, koordynatorem rodzinnej pieczy zastępczej, dyrektorem\nplacówki opiekuńczo-wychowawczej lub dyrektorem regionalnej placówki\nopiekuńczo-terapeutycznej oraz kandydatami do przysposobienia dziecka w\nzakresie przejścia dziecka pod opiekę odpowiednio kandydatów do\nprzysposobienia dziecka lub przysposabiających;\n15) zapewnienie pomocy psychologicznej osobom przysposobionym\nposzukujących informacji na temat swojego pochodzenia oraz osobom\nprzysposabiającym;\n16) umożliwianie dorosłemu przysposobionemu, na jego wniosek, nawiązanie z\nkontaktu z rodziną pochodzenia, jeśli rodzina ta zwróciła się do ośrodka\nadopcyjnego z prośbą o nawiązanie kontaktu z przysposobionym;\n17) wydawanie zaświadczeń potwierdzających przysposobienie dziecka, z\nwyłączeniem sytuacji w której małżonek przysposobił dziecko drugiego \f– 107 –\nmałżonka, umożliwiających skorzystanie z uprawnień wynikających z\nprzepisów odrębnych.”,\nb) po ust. 1 dodaje się ust. 1a – 1d w brzmieniu:\n„1a. W przypadku wydania przez organ centralny, o którym mowa w art. 187\nust. 1 pkt 9 zgody, o której mowa w art. 17lit. c Konwencji z dnia 29 maja 1993 r. o\nochronie dzieci i współpracy w dziedzinie przysposobienia międzynarodowego\n(Dz.U. z 2000 r. poz. 448 oraz z 2002 r. poz. 17), ośrodek adopcyjny, o którym mowa\nw art. 168 ust. 2 lub organ centralny, mogą monitorować sytuację przysposobionego,\npoprzez w szczególności:\n1) uzyskiwanie informacji na temat sytuacji przysposobionego i\nprzysposabiającego;\n2) utrzymywanie kontaktu z przysposobionym i przysposabiającym\npoprzez przeprowadzanie rozmów z przysposobionym i\nprzysposabiającym oraz odbywanie wizyt w miejscu ich pobytu.\n1b. Organ centralny, o którym mowa w art. 187 ust. 1 pkt 9 lub ośrodek\nadopcyjny, o którym mowa w art. 168 ust. 2, może żądać od organizacji lub ośrodka\nadopcyjnego, o których mowa w art. 167a ust. 1, informacji na temat sytuacji\nprzysposobionego i przysposabiającego. Przepisy art. 167a ust. 7 i art. 167b stosuje\nsię odpowiednio.\n1c. Informacje na temat sytuacji przysposobionego i przysposabiającego, o\nktórych mowa w ust. 1b powinny być przekazywane nie rzadziej niż raz na rok przez\npierwsze trzy lata od dnia uprawomocnienia się postanowienia sądu o\nprzysposobieniu, a następnie nie rzadziej niż raz na trzy lata, aż do osiągnięcia przez\ndziecko pełnoletności.\n1d. Zadanie, o którym mowa w ust. 1a pkt 2 może być realizowane za\npośrednictwem polskich służb konsularnych lub innych osób upoważnionych przez\norgan centralny, o którym mowa w art. 187 ust. 1 pkt 9.”;\n129) w art. 158 w ust. 1 uchyla się pkt 5 i 6;\n130) w art. 159 w ust. 1 uchyla się pkt 5 i 6;\n131) w art. 161:\na) w ust. 1 w pkt 1:\n- lit. a otrzymuje brzmienie:\n„a) kandydatów do przysposobienia dziecka oraz przysposabiających;”,\f– 108 –\n- lit. c otrzymuje brzmienie:\n„c) dzieci zgłoszonych do przysposobienia, dzieci zakwalifikowanych do\nprzysposobienia, w tym dzieci zakwalifikowanych 