ype\":\"CommitteeWork\",\"date\":\"2026-09-15\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-09-15\",\"print_number\":\"2792-A\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć część poprawek\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"III czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-09-18\",\"print_number\":null,\"sitting_num\":65,\"decision\":\"uchwalono\",\"committee_code\":null,\"report_file\":null,\"text_after3\":\"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf\",\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-09-18\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":443,\"no\":0,\"abstain\":0,\"not_participating\":17,\"sitting\":65,\"voting_number\":68,\"date\":\"2026-09-18T08:48:50Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/65/68/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-09-18\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[]},\"analysis_sha256\":\"6615687cb6a75a98a4f4ea2cb58c159ed74d1e3416909b9f3c7666ffda80d6eb\",\"analysis_revision\":2,\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Законопроект вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с рядом видов легального пребывания в Польше смогут получать её наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.\",\"key_changes\":[\"Право на услугу у иностранцев: ПМЖ, резидент ЕС, беженцы, доп. защита, карта с ''dostęp do rynku pracy'', ЕС/ЕЭЗ\",\"Включены обладатели разрешений по ст. 127, 137a, 139a, 139o, 151, 151b, научной визы, граждане Великобритании по Brexit-соглашению\",\"Объём: 20–240 часов в месяц (18–65 лет) и 20–80 часов (13–18 лет), ставка 49–55 zł брутто в час\",\"Заявление подаётся только электронно; нужен документ, дающий право на пребывание в Польше\",\"Поэтапный запуск: сначала 90 баллов поддержки, затем 85, с 1 января 2029 — 80 баллов\"],\"affected_groups\":[\"иностранцы с инвалидностью, имеющие ПМЖ или разрешение резидента ЕС\",\"беженцы и лица с дополнительной защитой\",\"обладатели карты побыту с отметкой ''dostęp do rynku pracy''\",\"граждане ЕС/ЕЭЗ/Швейцарии и члены их семей\",\"иностранные научные работники и переведённые внутри компании сотрудники\",\"граждане Великобритании по Brexit-соглашению\"],\"practical_impact\":\"Иностранец с инвалидностью, постоянно проживающий в Польше и имеющий подходящий вид пребывания, сможет подать электронное заявление и бесплатно получать до 240 часов помощи ассистента в месяц; к заявлению нужно приложить документ, подтверждающий право на пребывание.\",\"effective_date\":\"Закон вступает в силу через 14 дней после опубликования, кроме отдельных статей: через 12 и 14 месяцев после опубликования, а также с первого дня месяца после 5 месяцев с даты опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон открывает иностранцам с определёнными видами пребывания доступ к новой социальной услуге, что относится к социальной сфере, а не к легализации пребывания.\",\"changes_since_previous\":[\"Расширен список иностранцев: добавлены ICT-разрешения (ст. 139a, 139o, 139n), научные работники (ст. 151, 151b, 156b), национальная виза для исследований\",\"Добавлены граждане Великобритании и члены их семей по соглашению о Brexit и лица по двусторонним договорам о соцобеспечении\",\"Введена вторая группа получателей — подростки 13–18 лет, для них 20–80 часов в месяц\",\"Прописан поэтапный запуск: 90 баллов, затем 85, с 1 января 2029 — 80 баллов; лимиты часов в 2028 г. — 200, в 2029 г. — 220\",\"Уточнён перенос неиспользованных часов: не более 50% месячного лимита и не более 100 часов на следующий месяц\",\"Добавлены сроки рассмотрения заявлений (120/90/60 дней) и административные штрафы для реализаторов от 2 000 до 200 000 zł\"]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":170371,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-14T10:56:26Z\",\"input_tokens\":86708,\"output_tokens\":1403,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf\",\"source_kind\":\"committee_report\",\"revision\":2,\"text_sha256\":\"6615687cb6a75a98a4f4ea2cb58c159ed74d1e3416909b9f3c7666ffda80d6eb\",\"source_checked_at\":null},\"analysis_attempts\":0,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/36702/2025\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2025-11-04\",\"print_number\":\"1929\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"],\"joint\":null,\"discontinued_at\":null,\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-09-18T09:56:11Z\"}","change_json":"{\"id\":11,\"term\":10,\"number\":\"1929\",\"old_fingerprint\":\"3466a93fd060049f6dd8dbcb680c797d454ab9c4d3dd964ef154bb97b21e82b1\",\"new_fingerprint\":\"7e8083bfe1a9ea21704e89671d78fdd3e3fc4b1964b2b690cf32f6561a1a3629\",\"new_stages\":[{\"stage_name\":\"II czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-09-02\",\"print_number\":null,\"sitting_num\":64,\"decision\":\"skierowano ponownie do komisji w celu przedstawienia sprawozdania\",\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"III czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-09-18\",\"print_number\":null,\"sitting_num\":65,\"decision\":\"uchwalono\",\"committee_code\":null,\"report_file\":null,\"text_after3\":\"https://api.sejm.gov.pl/sej