ji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-09-16\",\"print_number\":\"3111\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3111/3111.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"uchwalić ponownie\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Rozpatrywanie na forum Sejmu wniosku Prezydenta\",\"stage_type\":\"PresidentMotionConsideration\",\"date\":\"2026-09-17\",\"print_number\":null,\"sitting_num\":65,\"decision\":\"nie uchwalona ponownie\",\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-09-17\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":232,\"no\":200,\"abstain\":0,\"not_participating\":28,\"sitting\":65,\"voting_number\":11,\"date\":\"2026-09-17T15:24:41Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/65/11/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"nie uchwalona ponownie po wecie Prezydenta\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-09-17\",\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2111/attachment/2111_u3.pdf\",\"kind\":\"text_after3\",\"extra_urls\":[]},\"analysis_sha256\":\"6af9660d9f0772d8ebc8e22bd36b98bd91c63c76872d04134dca6143470bf8b1\",\"analysis_revision\":2,\"seen_supplements\":[\"2111-001\",\"2111-002\",\"2111-003\",\"2111-004\",\"2111-005\",\"2111-006\",\"2111-007\",\"2111-008\",\"2111-009\",\"2111-010\",\"2111-011\",\"2111-012\",\"2111-013\",\"2111-014\",\"2111-015\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект вводит в польское право «umowa o wspólnym pożyciu» (договор о совместной жизни) и статус ближайшего лица, внося правки примерно в 240 законов. В ustawa o cudzoziemcach и законе о въезде граждан ЕС партнёр по такому договору приравнивается к супругу при выдаче ВНЖ, ПМЖ, а также при отказе и проверке фиктивности союза.\",\"key_changes\":[\"Партнёр по umowa o wspólnym pożyciu приравнен к супругу в ustawa o cudzoziemcach (ВНЖ по семье, ПМЖ)\",\"ПМЖ для партнёра гражданина Польши после 3 лет союза и 2 лет ВНЖ; проверка фиктивности как у браков\",\"Члены семьи граждан ЕС: партнёр и его дети получают право пребывания и карту побыту; ПМЖ через 3 года\",\"Партнёр может быть застрахован в NFZ; льготы по налогу на наследство и дарение (I группа)\",\"Регистрация статуса в USC через нотариальный договор; справка о статусе — 38 zł; правки в Karta Dużej Rodziny, 800+, PIT\"],\"affected_groups\":[\"Иностранцы — партнёры граждан Польши\",\"Иностранцы — партнёры иностранцев с ПМЖ/долгосрочным резидентством\",\"Члены семьи граждан ЕС\",\"Иностранцы, пользующиеся NFZ, пособиями, налоговыми льготами\"],\"practical_impact\":\"Незарегистрированные пары смогут оформить нотариальный договор и получить статус ближайшего лица, что даёт основание для ВНЖ и ПМЖ по семейным обстоятельствам, доступ к медстраховке партнёра и налоговым льготам. Как и у браков, уряд будет проверять фиктивность союза и реальность связи.\",\"effective_date\":\"1 января 2027 года (статья о технической подготовке реестров — на следующий день после опубликования)\",\"confidence\":0.88,\"rationale\":\"Проект напрямую меняет ustawa o cudzoziemcach и закон о въезде граждан ЕС, добавляя новое основание для ВНЖ и ПМЖ, поэтому оценка 5 и категория legal_stay.\",\"changes_since_previous\":[\"Уточнена дата вступления в силу: 1 января 2027 года\",\"Указана дата самой ustawy o statusie osoby najbliższej — 29 мая 2026 года\",\"Добавлены переходные нормы: старые правила применяются к делам о возврате (zobowiązanie do powrotu) и решениям, начатым до вступления в силу\",\"Добавлено требование к MC обеспечить техническую готовность реестра стана цивильного (вступает сразу после публикации)\",\"Уточнено условие ПМЖ для партнёра гражданина Польши: 3 года союза и 2 года непрерывного пребывания по ВНЖ\",\"В тексте прямо указано: можно отказать в ВНЖ/карте побыту, если связь с партнёром не имеет реального и постоянного характера\"]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":664717,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-16T19:39:15Z\",\"input_tokens\":348525,\"output_tokens\":1084,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2111/attachment/2111_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":2,\"text_sha256\":\"6af9660d9f0772d8ebc8e22bd36b98bd91c63c76872d04134dca6143470bf8b1\",\"source_checked_at\":null},\"analysis_attempts\":0,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/43917/2025\",\"title\":\"Rządowy projekt ustawy - Przepisy wprowadzające ustawę o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu\",\"description\":\"nowelizacji wszystkich ustaw, których zmiana jest konieczna w związku z wprowadzeniem ustawy o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu, na mocy której strony umowy uzyskują status osoby najbliższej w związku, mającej zapewnić ochronę prawną związkom nieformalnym\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2025-12-30\",\"print_number\":\"2111\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/65/2026-09-15\",\"date\":\"2026-09-15\",\"end_date\":\"2026-09-18\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":65,\"room\":null,\"text\":\"Sprawozdanie Komisji Nadzwyczajnej o wniosku Prezydenta Rzeczypospolitej Polskiej o ponowne rozpatrzenie ustawy z dnia 29 maja 2026 r. – Przepisy wprowadzające ustawę o statusie osoby najbliższej w związku i umowie o wspólnym pożyciu (druki nr 2864 i )\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"seen_supplements\":[\"2111-001\",\"2111-002\",\"2111-003\",\"2111-004\",\"2111-005\",\"2111-006\",\"2111-007\",\"2111-008\",\"2111-009\",\"2111-010\",\"2111-011\",\"2111-012\",\"2111-013\",\"2111-014\",\"2111-015\"],\"joint\":null,\"discontinued_at\":null,\"first_seen_at\":\"2026-09-16T19:35:39Z\",\"last_checked_at\":\"2026-09-18T19:10:05Z\"}","change_json":"{\"id\":12,\"term\":10,\"number\":\"2111\",\"old_fingerprint\":\"9a2201fe9f3e9e84407a298f075d4720a79ba051ecb5213d439e57c7bc058ab4\",\"new_fingerprint\":\"87b2fddb8e704bc8035fc1ee518abf0c60eba5c8a8726a909bebd6f20c981ccd\",\"new_stages\":[{\"stage_name\":\"Rozpatrywanie na forum Sejmu wniosku Prezydenta\",\"stage_type\":\"PresidentMotionConsideration\",\"date\":\"2026-09-17\",\"print_number\":null,\"sitting_num\":65,\"decision\":\"nie uchwalona ponownie\",\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-09-17\",\"print_numb