INSERT INTO "publications" VALUES(58,10,'RCL/12404454','new_bill','sent','@lex_inform_pl',61,'[]',NULL,'2026-09-22T16:00:01+00:00','2026-09-22T16:00:01+00:00',NULL,0,NULL,'b75ebc7c8d307d65a8fa2109eb34c72c38f344747553616bc879ac0875b32f02','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12404454\",\"title\":\"Projekt ustawy o stażach\",\"description\":\"PRACA; praca\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-11-21\",\"document_date\":\"2025-11-21\",\"change_date\":\"2026-09-22T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12404454\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obywatele_ukrainy\",\"text:zatrudnianie_cudzoziemcow\",\"text:pracownicy_delegowani\",\"text:obywatele_innych_panstw\",\"text:uznawanie_kwalifikacji\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"33945cb65856ab293cd9a94579fdd5922b95e64e99d21d3eee08cf9c15039bec\",\"observed_closure_date\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"employment\",\"summary\":\"Проект вводит новый закон о стажировках (staże) вместо ustawa o praktykach absolwenckich (закон о выпускных практиках): стажировки становятся обязательно оплачиваемыми, с письменным договором и страхованием. Закон распространяется на граждан ЕС/ЕЭЗ и на иностранцев, перечисленных в ст. 3 ч. 1 ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom (закон о допустимости поручения работы иностранцам).\",\"key_changes\":[\"Отмена ustawa o praktykach absolwenckich; бесплатные выпускные практики больше невозможны\",\"Круг участников: поляки, граждане ЕС/ЕЭЗ и иностранцы из ст. 3 ч. 1 закона о поручении работы иностранцам\",\"Денежная выплата стажёру: не менее 35% среднего заработка и не выше среднего заработка\",\"Договор о стажировке — письменный, максимум 6 месяцев, срок предупреждения 7 или 14 дней\",\"Стажёр подлежит соцстрахованию как исполнитель zlecenie и медстрахованию NFZ через организатора\"],\"affected_groups\":[\"граждане ЕС/ЕЭЗ в Польше\",\"иностранцы со свободным доступом к рынку труда по ст. 3 ч. 1 закона о поручении работы иностранцам\",\"граждане Украины, охваченные специальным законом (в части ст. 26)\",\"молодёжь и выпускники, включая несовершеннолетних стажёров\"],\"practical_impact\":\"Иностранцы, имеющие доступ к польскому рынку труда, смогут проходить стажировку только по письменному договору и за оплату не ниже 35% среднего заработка, с социальным и медицинским страхованием; бесплатные практики исчезнут. Для иностранцев без такого доступа стажировки по этому закону недоступны.\",\"effective_date\":\"Закон вступает в силу по истечении 6 месяцев со дня опубликования.\",\"confidence\":0.8,\"rationale\":\"Закон прямо определяет круг иностранцев, которым разрешены стажировки, и регулирует условия их оплачиваемого труда, что относится к сфере занятости.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":96624,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-09-22T16:00:01Z\",\"input_tokens\":49715,\"output_tokens\":1125,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":2652,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12404454/13171166/13171167/dokument749803.pdf\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"96b2a36ffb972cede864176f0bd61797487a2189acea3e6a32c4a293080369d1\",\"source_checked_at\":\"2026-09-22T16:00:01Z\"},\"analysis_attempts\":0,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12404454,\"title\":\"Projekt ustawy o stażach\",\"applicant\":\"Minister Rodziny, Pracy i Polityki Społecznej\",\"wykaz_number\":\"UD307\",\"wykaz_url\":\"https://www.gov.pl/web/premier/wplip-rm\",\"created\":\"2025-11-21\",\"modified\":\"2026-09-22\",\"departments\":[\"praca\"],\"keywords\":[\"PRACA\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13171153,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"catalog_read\":false},{\"id\":13171154,\"number\":2,\"name\":\"Uzgodnienia\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-09-22\",\"folders\":[],\"catalog_read\":false},{\"id\":13171160,\"number\":3,\"name\":\"Konsultacje publiczne\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-04-24\",\"folders\":[{\"id\":13171161,\"name\":\"Projekt\",\"modified\":\"2026-04-21\",\"documents\":[{\"id\":