ull,\"voting\":{\"yes\":411,\"no\":23,\"abstain\":0,\"not_participating\":26,\"sitting\":65,\"voting_number\":86,\"date\":\"2026-09-18T09:15:44Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/65/86/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Stanowisko Senatu\",\"stage_type\":\"SenatePosition\",\"date\":\"2026-09-24\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":\"nie wniósł poprawek\",\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Ustawę przekazano Prezydentowi do podpisu\",\"stage_type\":\"ToPresident\",\"date\":\"2026-09-24\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-09-18\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"kind\":\"text_after3\",\"extra_urls\":[]},\"analysis_sha256\":\"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a\",\"analysis_revision\":2,\"seen_supplements\":[\"2846-001\",\"2846-002\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"legal_stay\",\"summary\":\"Специальный закон об организации Всемирного скаутского Джамбори в Гданьске в 2027 году. Для иностранцев главное: участники освобождаются от консульского сбора за национальную и шенгенскую визу, а их заявления рассматриваются без лишней задержки. Остальные нормы касаются медицины, санитарии, строительства и безопасности.\",\"key_changes\":[\"Освобождение от консульского сбора за национальную визу и визу Шенген для участников Джамбори\",\"Нужно приложить подтверждение регистрации участия или иной документ об участии\",\"Рассмотрение «без излишней задержки», если консула уведомили не позднее чем за 6 недель до начала\",\"Срок 6 недель не действует для глав государств, членов правительств, монархов и официальных делегаций\",\"Волонтёры не из ЕС должны представить справки о несудимости из стран гражданства и проживания за 10 лет\"],\"affected_groups\":[\"иностранные участники Всемирного скаутского Джамбори, нуждающиеся в визе\",\"иностранные волонтёры, работающие с несовершеннолетними участниками\",\"официальные иностранные делегации\"],\"practical_impact\":\"Иностранные участники Джамбори не платят консульский сбор за визу при наличии подтверждения регистрации и получают ускоренное рассмотрение при уведомлении консула за 6 недель. Волонтёры-иностранцы для работы с детьми обязаны собрать справки о несудимости из стран гражданства и проживания за последние 10 лет.\",\"effective_date\":\"Закон вступает в силу по истечении 14 дней со дня опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон содержит визовые льготы (сфера легализации въезда), но узкие и разовые — только для участников одного мероприятия, поэтому оценка средняя.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":27534,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-28T15:56:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":2,\"text_sha256\":\"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a\",\"source_checked_at\":\"2026-09-28T15:56:32Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/25576/2026\",\"title\":\"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.\",\"description\":\"uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-07-23\",\"print_number\":\"2846\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"2846-001\",\"2846-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"relevant_analysis\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-09-28T16:02:13Z\"}","change_json":"","print_json":"{\"term\":10,\"number\":\"2846\",\"title\":\"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.\",\"document_date\":\"2026-07-23\",\"delivery_date\":\"2026-07-27\",\"change_date\":\"2026-08-28T14:06:27Z\",\"attachments\":[{\"print_number\":\"2846\",\"name\":\"2846.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2846/2846.pdf\"},{\"print_number\":\"2846\",\"name\":\"2846-uzasadnienie.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2846/2846-uzasadnienie.docx\"},{\"print_number\":\"2846\",\"name\":\"2846-ustawa.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2846/2846-ustawa.docx\"}],\"additional_prints\":[{\"term\":10,\"number\":\"2846-001\",\"title\":\"Do druku nr 2846 - opinia GIP (nie zgłoszono uwag).\",\"document_date\":\"2026-08-04\",\"delivery_date\":\"2026-08-04\",\"change_date\":\"2026-08-04T11:09:04Z\",\"attachments\":[{\"print_number\":\"2846-001\",\"name\":\"2846-001.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2846-001/2846-001.pdf\"}],\"additional_prints\":[]},{\"term\":10,\"number\":\"2846-002\",\"title\":\"Do druku nr 2846 - opinia NRPiP\",\"document_date\":\"2026-08-26\",\"delivery_date\":\"2026-08-28\",\"change_date\":\"2026-08-28T09:58:12Z\",\"attachments\":[{\"print_number\":\"2846-002\",\"name\":\"2846-002.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/2846-002/2846-002.pdf\"}],\"additional_prints\":[]}]}","primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":null,"held_change_ids":[]}',NULL);
