committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"GOR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Gospodarki i Rozwoju\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"FPB\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Finansów Publicznych\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":null,\"analysis_revision\":1,\"seen_supplements\":[\"3003-001\",\"3003-002\",\"3003-003\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"legal_stay\",\"summary\":\"Проект вводит единый закон о санкциях (środki ograniczające) — общий порядок применения санкций ЕС и национальных санкций. Для иностранцев важно, что одним из национальных санкционных мер становится внесение в реестр нежелательных лиц, а закон о иностранцах дополняется новым основанием для запрета въезда и отказа в визе/виде на жительство. Затрагивает лишь лиц, попавших в санкционный список МВД.\",\"key_changes\":[\"Новая мера: внесение иностранца в wykaz cudzoziemców, których pobyt jest niepożądany\",\"Поправки в ustawa o cudzoziemcach: санкционный список — основание для отказа в визе и ВНЖ\",\"Szef Urzędu do Spraw Cudzoziemców — орган, решающий об исключениях из запрета на въезд\",\"Уголовная ответственность (3 мес.–5 лет) за содействие въезду или транзиту лица под санкциями\",\"Список санкционных лиц публикуется в BIP МВД; обжалование — только в административный суд\",\"Выплаты работникам санкционированного работодателя из FGŚP до 3 месяцев\"],\"affected_groups\":[\"Иностранцы, внесённые в национальный санкционный список\",\"Граждане ЕС и члены их семей, подпадающие под санкции\",\"Работники (в т.ч. иностранцы) компаний под санкциями\",\"Предприниматели и компании, ведущие торговлю с санкционными странами\"],\"practical_impact\":\"Для подавляющего большинства иностранцев ничего не меняется. Тому, кто попал в санкционный список, грозит запрет въезда, отказ в визе и виде на жительство, заморозка средств; работникам санкционированных фирм гарантируется выплата зарплаты из FGŚP до 3 месяцев.\",\"effective_date\":\"Через 30 дней после опубликования, кроме ст. 73, которая вступает в силу через 6 месяцев после опубликования.\",\"confidence\":0.85,\"rationale\":\"Проект напрямую изменяет ustawa o cudzoziemcach и вводит запрет въезда/пребывания как санкционную меру, но касается узкой группы лиц, поэтому 4, а не 5.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v3\",\"input_chars\":375697,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-09T17:59:19Z\",\"input_tokens\":185019,\"output_tokens\":1333,\"cache_read_input_tokens\":2118,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":null,\"law_sha256\":null,\"source_checked_at\":null},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/27024/2026\",\"title\":\"Rządowy projekt ustawy o środkach ograniczających\",\"description\":\"określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-08-06\",\"print_number\":\"3003\",\"eu_related\":true,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"committee\",\"ref\":\"ASW/138/2026-10-06+14:00+sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"date\":\"2026-10-06\",\"end_date\":null,\"start_time\":\"14:00:00\",\"committee_code\":\"ASW\",\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"sitting_number\":138,\"room\":\"sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"text\":\"Rozpatrzenie rządowego projektu ustawy o środkach ograniczających (druk nr 3003).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=13C7C6459FB55203C1258E82003B72DD\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"3003-001\",\"3003-002\",\"3003-003\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-09-30T23:06:42Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"committee\",\"ref\":\"ASW/138/2026-10-06+14:00+sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"date\":\"2026-10-06\",\"end_date\":null,\"start_time\":\"14:00:00\",\"committee_code\":\"ASW\",\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"sitting_number\":138,\"room\":\"sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"text\":\"Rozpatrzenie rządowego projektu ustawy o środkach ograniczających (druk nr 3003).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=13C7C6459FB55203C1258E82003B72DD\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}","moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":13,"held_change_ids":[]}',NULL);
