":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"GOR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Gospodarki i Rozwoju\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"FPB\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Finansów Publicznych\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":null,\"analysis_revision\":1,\"seen_supplements\":[\"3003-001\",\"3003-002\",\"3003-003\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"legal_stay\",\"summary\":\"Проект вводит единый закон о санкциях (środki ograniczające) — общий порядок применения санкций ЕС и национальных санкций. Для иностранцев важно, что одним из национальных санкционных мер становится внесение в реестр нежелательных лиц, а закон о иностранцах дополняется новым основанием для запрета въезда и отказа в визе/виде на жительство. Затрагивает лишь лиц, попавших в санкционный список МВД.\",\"key_changes\":[\"Новая мера: внесение иностранца в wykaz cudzoziemców, których pobyt jest niepożądany\",\"Поправки в ustawa o cudzoziemcach: санкционный список — основание для отказа в визе и ВНЖ\",\"Szef Urzędu do Spraw Cudzoziemców — орган, решающий об исключениях из запрета на въезд\",\"Уголовная ответственность (3 мес.–5 лет) за содействие въезду или транзиту лица под санкциями\",\"Список санкционных лиц публикуется в BIP МВД; обжалование — только в административный суд\",\"Выплаты работникам санкционированного работодателя из FGŚP до 3 месяцев\"],\"affected_groups\":[\"Иностранцы, внесённые в национальный санкционный список\",\"Граждане ЕС и члены их семей, подпадающие под санкции\",\"Работники (в т.ч. иностранцы) компаний под санкциями\",\"Предприниматели и компании, ведущие торговлю с санкционными странами\"],\"practical_impact\":\"Для подавляющего большинства иностранцев ничего не меняется. Тому, кто попал в санкционный список, грозит запрет въезда, отказ в визе и виде на жительство, заморозка средств; работникам санкционированных фирм гарантируется выплата зарплаты из FGŚP до 3 месяцев.\",\"effective_date\":\"Через 30 дней после опубликования, кроме ст. 73, которая вступает в силу через 6 месяцев после опубликования.\",\"confidence\":0.85,\"rationale\":\"Проект напрямую изменяет ustawa o cudzoziemcach и вводит запрет въезда/пребывания как санкционную меру, но касается узкой группы лиц, поэтому 4, а не 5.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v3\",\"input_chars\":375697,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-09T17:59:19Z\",\"input_tokens\":185019,\"output_tokens\":1333,\"cache_read_input_tokens\":2118,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":null,\"law_sha256\":null,\"source_checked_at\":null},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/27024/2026\",\"title\":\"Rządowy projekt ustawy o środkach ograniczających\",\"description\":\"określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-08-06\",\"print_number\":\"3003\",\"eu_related\":true,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"committee\",\"ref\":\"ASW/135/2026-10-06+14:00+sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"date\":\"2026-10-06\",\"end_date\":null,\"start_time\":\"14:00:00\",\"committee_code\":\"ASW\",\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"sitting_number\":135,\"room\":\"sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"text\":\"Rozpatrzenie rządowego projektu ustawy o środkach ograniczających (druk nr 3003).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=13C7C6459FB55203C1258E82003B72DD\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"3003-001\",\"3003-002\",\"3003-003\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-09-30T23:06:42Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"committee\",\"ref\":\"ASW/135/2026-10-06+14:00+sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"date\":\"2026-10-06\",\"end_date\":null,\"start_time\":\"14:00:00\",\"committee_code\":\"ASW\",\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"sitting_number\":135,\"room\":\"sala im. Konstytucji 3-go Maja (nr 118, bud. C)\",\"text\":\"Rozpatrzenie rządowego projektu ustawy o środkach ograniczających (druk nr 3003).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=13C7C6459FB55203C1258E82003B72DD\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}","moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":13,"held_change_ids":[]}',NULL);
INSERT INTO "publications" VALUES(77,10,'3157','new_bill','sent','@lex_inform_pl',75,'[]',NULL,'2026-10-01T19:41:40+00:00','2026-10-01T19:41:40+00:00',NULL,0,NULL,'70e04f5142e93959de202c826c15644ab181cf7001f761cc1cde199ae2004083','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3157\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-28\",\"document_date\":\"2026-09-28\",\"change_date\":\"2026-10-01T07:13:08Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-160-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-160-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:migracja\",\"text:obywatelstwo\",\"text:przekraczanie_granicy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-28\",\"print_number\":\"3157\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-30\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-30\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"stages_fingerprint\":\"a6eb8942658610b3f54612c55eeabde7ac670e9e8c22b5cb1549850d09579b31\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-28\",\"print_number\":\"3157\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-30\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-30\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект ужесточает правила найма и оплаты труда медперсонала по контрактам с NFZ и усиливает контроль NFZ. Вводится прямое право пациента на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.\",\"key_changes\":[\"Лимит общего рабочего времени медиков и потолки почасовой/месячной оплаты по контрактам с NFZ\",\"Запрет привязки зарплаты медиков к проценту от контракта NFZ, жёсткие условия договоров\",\"Сокращение схем через компании/спółki: заказы в основном напрямую физлицам‑медикам\",\"NFZ получает расширенный доступ к меддокументации и документам о занятости, вводятся штрафы\",\"В законе о правах пациента закреплён запрет дискриминации, в т.ч. по гражданству и национальности\"],\"affected_groups\":[\"иностранцы, пользующиеся медицинской помощью в Польше (NFZ и частной)\",\"иностранные врачи, медсёстры, физиотерапевты и др., работающие в Польше по контрактам с NFZ\",\"иностранные пациенты, жалующиеся РПП на неравное обращение\"],\"practical_impact\":\"Иностранные пациенты получают прямую законную защиту от худшего обращения или отказа в помощи из‑за гражданства/национальности, проще ссылаться на это в жалобе. Иностранным медикам придётся подстраивать графики и зарплатные условия под новые лимиты времени работы и оплаты у всех работодателей.\",\"effective_date\":\"Закон вступает в силу по истечении месяца со дня его опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект системно меняет условия работы медиков и вводит прямой запрет дискриминации пациентов по гражданству и национальности, что затрагивает как иностранных пациентов, так и иностранных медработников, поэтому значимость для иностранцев средняя в социальной сфере.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":182345,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-01T19:41:36Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06\",\"law_sha256\":\"91f20470de90c8ae40b69032937a961b66736ee658335374ed0715585d2d7093\",\"source_checked_at\":\"2026-10-01T19:41:36Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32531/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-28\",\"print_number\":\"3157\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-01T07:15:59Z\",\"last_checked_at\":\"2026-10-01T18:56:06Z\"}","change_json":"","print_json":"{\"term\":10,\"number\":\"3157\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw.\",\"document_date\":\"2026-09-28\",\"delivery_date\":\"2026-10-01\",\"change_date\":\"2026-10-01T10:52:03Z\",\"attachments\":[{\"print_number\":\"3157\",\"name\":\"3157-ustawa.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157-ustawa.docx\"},{\"print_number\":\"3157\",\"name\":\"3157-uzasadnienie.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157-uzasadnienie.docx\"},{\"print_number\":\"3157\",\"name\":\"3157.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\"}],\"additional_prints\":[]}","primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":null,"held_change_ids":[]}',NULL);
