INSERT INTO "publications" VALUES(79,10,'3157','agenda','sent','@lex_inform_pl',77,'[]',NULL,'2026-10-01T19:43:40+00:00','2026-10-01T19:43:40+00:00',NULL,0,'ZDR/170/2026-10-07+16:00+sala im. Olgi Krzyżanowskiej (nr 412, bud. U)',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3157\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-28\",\"document_date\":\"2026-09-28\",\"change_date\":\"2026-10-01T07:13:08Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-160-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-160-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:migracja\",\"text:obywatelstwo\",\"text:przekraczanie_granicy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-28\",\"print_number\":\"3157\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_n