,\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект ужесточает правила найма и оплаты труда медперсонала по контрактам с NFZ и усиливает контроль NFZ. Вводится прямое право пациента на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.\",\"key_changes\":[\"Лимит общего рабочего времени медиков и потолки почасовой/месячной оплаты по контрактам с NFZ\",\"Запрет привязки зарплаты медиков к проценту от контракта NFZ, жёсткие условия договоров\",\"Сокращение схем через компании/спółki: заказы в основном напрямую физлицам‑медикам\",\"NFZ получает расширенный доступ к меддокументации и документам о занятости, вводятся штрафы\",\"В законе о правах пациента закреплён запрет дискриминации, в т.ч. по гражданству и национальности\"],\"affected_groups\":[\"иностранцы, пользующиеся медицинской помощью в Польше (NFZ и частной)\",\"иностранные врачи, медсёстры, физиотерапевты и др., работающие в Польше по контрактам с NFZ\",\"иностранные пациенты, жалующиеся РПП на неравное обращение\"],\"practical_impact\":\"Иностранные пациенты получают прямую законную защиту от худшего обращения или отказа в помощи из‑за гражданства/национальности, проще ссылаться на это в жалобе. Иностранным медикам придётся подстраивать графики и зарплатные условия под новые лимиты времени работы и оплаты у всех работодателей.\",\"effective_date\":\"Закон вступает в силу по истечении месяца со дня его опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект системно меняет условия работы медиков и вводит прямой запрет дискриминации пациентов по гражданству и национальности, что затрагивает как иностранных пациентов, так и иностранных медработников, поэтому значимость для иностранцев средняя в социальной сфере.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":182345,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-01T19:41:36Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06\",\"law_sha256\":\"91f20470de90c8ae40b69032937a961b66736ee658335374ed0715585d2d7093\",\"source_checked_at\":\"2026-10-01T19:41:36Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32531/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-28\",\"print_number\":\"3157\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"committee\",\"ref\":\"ZDR/170/2026-10-07+16:00+sala im. Olgi Krzyżanowskiej (nr 412, bud. U)\",\"date\":\"2026-10-07\",\"end_date\":null,\"start_time\":\"16:00:00\",\"committee_code\":\"ZDR\",\"committee_name\":\"Komisja Zdrowia\",\"sitting_number\":170,\"room\":\"sala im. Olgi Krzyżanowskiej (nr 412, bud. U)\",\"text\":\"Pierwsze czytanie rządowego projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druk nr 3157) – uzasadnia Minister Zdrowia.\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=29908C1CEA6614F6C1258E83003BD1B0\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T07:15:59Z\",\"last_checked_at\":\"2026-10-01T18:56:06Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"committee\",\"ref\":\"ZDR/170/2026-10-07+16:00+sala im. Olgi Krzyżanowskiej (nr 412, bud. U)\",\"date\":\"2026-10-07\",\"end_date\":null,\"start_time\":\"16:00:00\",\"committee_code\":\"ZDR\",\"committee_name\":\"Komisja Zdrowia\",\"sitting_number\":170,\"room\":\"sala im. Olgi Krzyżanowskiej (nr 412, bud. U)\",\"text\":\"Pierwsze czytanie rządowego projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druk nr 3157) – uzasadnia Minister Zdrowia.\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=29908C1CEA6614F6C1258E83003BD1B0\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}","moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":75,"held_change_ids":[]}',NULL);
INSERT INTO "publications" VALUES(80,10,'3039','status_update','sent','@lex_inform_pl',78,'[]',52,'2026-10-01T20:28:27+00:00','2026-10-01T20:28:27+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3039\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o udzielaniu cudzoziemcom ochrony na terytorium Rzeczypospolitej Polskiej\",\"description\":\"projekt dotyczy rozszerzenia katalogu osób uprawnionych do nieodpłatnego pobytu w obiektach zbiorowego zakwaterowania, umożliwienia wojewodom finansowania transportu mieszkańców tych obiektów w sytuacji wymagającej relokacji lub zapewnienia świadczeń zdrowotnych, umożliwienie organizacjom pozarządowym prowadzenia tego typu obiektów z pominięciem otwartego konkursu ofert\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-08-03\",\"document_date\":\"2026-08-03\",\"change_date\":\"2026-09-04T09:09:10Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"cudzoziemcy\",\"ochrona_cudzoziemcow\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-08-03\",\"print_number\":\"3039\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ASW\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"children\":[]}]}],\"stages_fingerprint\":\"cb84442d86c41c7859428d34b37b92124473038d0b68849912688cd593427255\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-08-03\",\"print_number\":\"3039\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-03\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ASW\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3039/3039.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":null,\"analysis_revision\":1,\"seen_supplements\":[\"3039-001\",\"3039-002\",\"3039-003\",\"3039-004\",\"3039-005\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект вносит изменения в ustawa o udzielaniu cudzoziemcom ochrony na terytorium RP (закон о предоставлении иностранцам защиты в Польше) в части работы центров коллективного размещения и доступа к медицинской помощи для лиц под временной защитой. Расширяется список тех, кто может бесплатно проживать в таких центрах: несовершеннолетние под опекой проживающих, учащиеся до 26 лет, одинокие матери и получатели минимальной польской пенсии. Те же категории получают право на медицинские услуги, даже если они не живут в центре коллективного размещения — подтверждение через заявление под угрозой уголовной ответственности за ложные сведения. Воеводы смогут финансировать транспорт жильцов при релокации или для доступа к медпомощи, а также поручать управление центрами НГО и профсоюзам без открытого конкурса. Оценочная стоимость — около 223 млн зл. в год.\",\"key_changes\":[\"Право на бесплатное проживание в центрах коллективного размещения для несовершеннолетних под опекой проживающих там лиц\",\"Право проживания для лиц до 26 лет, которые жили в центре до 1 июля 2026 г. и продолжают учёбу в дневной школе или на стационаре в вузе\",\"Право проживания для одиноких матерей (без супруга или чей супруг вне территории Польши)\",\"Право проживания для лиц пенсионного возраста с польской пенсией не выше минимальной\",\"Право на медицинские услуги для этих категорий, даже если они не живут в центре, подтверждаемое заявлением под уголовной ответственностью\",\"Воеводы могут оплачивать транспорт жильцов и передавать управление центрами НГО/профсоюзам без открытого конкурса\"],\"affected_groups\":[\"лица под временной защитой (в основном граждане Украины)\",\"несовершеннолетние под опекой жильцов центров\",\"учащиеся и студенты до 26 лет\",\"одинокие матери с детьми\",\"получатели минимальной польской пенсии\"],\"practical_impact\":\"Перечисленные категории смогут бесплатно жить в центрах коллективного размещения и получать медицинскую помощь даже при проживании вне центра, подав заявление о соответствии условиям. Для подтверждения права потребуется письменное заявление под угрозой уголовной ответственности за ложные сведения.\",\"effective_date\":\"Закон вступает в силу через 14 дней после опубликования.\",\"confidence\":0.9,\"rationale\":\"Проект не меняет основания легализации пребывания, но напрямую расширяет социальные права (жильё, медпомощь) для лиц под временной защитой, что соответствует категории social и оценке 3.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v1\",\"input_chars\":20001,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-07T13:53:03Z\",\"input_tokens\":10317,\"output_tokens\":951,\"cache_read_input_tokens\":null,\"cache_creation_input_tokens\":null,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3039/3039.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":null,\"law_sha256\":null,\"source_checked_at\":null},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"3039-001\",\"3039-002\",\"3039-003\",\"3039-004\",\"3039-005\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-01T20:28:27Z\"}","change_json":"{\"id\":52,\"term\":10,\"number\":\"3039\",\"old_fingerprint\":\"cb84442d86c41c7859428d34b37b92124473038d0b68849912688cd593427255\",\"new_fingerprint\":\"895187d55c8ac7496856398c9089f7e4801aaec319494be24ba78a69aa435c5f\",\"new_stages\":[],\"closure_detected\":false,\"passed\":false,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":null,\"supplements\":[{\"number\":\"3039-005\",\"title\":\"Do druku nr 3039 - ocena skutków regulacji\",\"source_kind\":\"impact_assessment\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3039-005/3039-005.pdf\",\"digest\":{\"summary\":\"Документ описывает, что проект расширяет поддержку для бенефициаров временной защиты со статusem UKR (около 8,5 тыс. людей в оśrodkach zbiorowego zakwaterowania и 176 тыс. вне них) и может стоить сектору финансов общественных свыше 1,2 млрд зł в год. Эксперты указывают на риск завышения/неправильной оценки прав на льготы (в т.ч. медуслуги по одному лишь заявлению), спорные критерии «групп уязвимых» и возможное несоответствие нормам ЕС по zamówienia publiczne при передаче управления центрами без конкурса.\",\"points\":[\"Проект охватывает 8 544 жителей OZZ и 176 000 уязвимых лиц вне центров\",\"Месячный koszt по расчётам MRPiPS – 18,6 млн зł плюс 85,36 млн зł на медпомощь\",\"Годовой совокупный koszt может превысить 1,247 млрд зł, а не 223 млн зł\",\"Есть риск дискриминации: проект отдельно защищает только «матерей-одиночек», а не отцов\",\"Самодекларация для доступа к медуслугам и отсутствие документов могут вести к злоупотреблениям\",\"Передача OZZ НПО и профсоюзам без конкурса может противоречить dyrektywa 2014/24/UE\",\"Проект может восприниматься как дающий преференции бенефициарам ochrony czasowej над поляками\"],\"supports\":null,\"affects_foreigners\":true,\"confidence\":0.9},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"created_at\":\"2026-10-01T20:23:30Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}],\"detected_at\":\"2026-10-01T20:28:27Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":2,"held_change_ids":[]}',NULL);
INSERT INTO "publications" VALUES(82,10,'RCL/12402353','new_bill','sent','@lex_inform_pl',79,'[]',NULL,'2026-10-02T18:30:30+00:00','2026-10-02T18:30:30+00:00',NULL,0,NULL,'f488cd80b231a5797366e98c6f4dd9bb43427f8cf88e603ddb5dab5f300a6f57','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12402353\",\"title\":\"Projekt ustawy o rejestracji statków pod polską banderą\",\"description\":\"STATKI MORSKIE; gospodarka morska\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-09-22\",\"document_date\":\"2026-10-02\",\"change_date\":\"2026-10-02T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12402353\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:wizy\",\"text:straz_graniczna\",\"text:schengen\",\"text:obywatele_innych_panstw\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"083ec036fb68ff1442bd73fa9567257f2288d3a6988823c66e9060065719844b\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157968/13157969/dokument800294.zip\",\"kind\":\"rcl\",\"extra_urls\":[]},\"analysis_sha256\":\"f80b38830cd42ba5dcec1207547dea96d3a21b7ebd28b1a2dac0a251aea614cb\",\"analysis_revision\":2,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"employment\",\"summary\":\"Проект полностью перестраивает систему регистрации судов и реестра, вводит электронный реестр и сервис на английском. Важное для иностранцев: расширяются правила временного признания дипломов моряков из третьих стран и допуска их к работе на судах под польским флагом до 3 месяцев.\",\"key_changes\":[\"Моряки с документами из третьих стран могут получить признание диплома максимум на 3 месяца\",\"Признание документов стран не из списка ЕС/KE – только если в KE подан запрос о признании этой страны\",\"Моряки с поданным заявлением на признание диплома могут до 3 мес. работать на судах под польской флагом\",\"И то, и другое допускается лишь после проверки подлинности иностранного документа квалификации\",\"За выдачу подтверждения подачи заявления на признание взимается 30 PLN\"],\"affected_groups\":[\"иностранные моряки с дипломами/свидетельствами третьих стран\",\"иностранные члены экипажей, нанимающиеся на суда под польским флагом\",\"иностранные судовладельцы из państw UE/EFTA, регистрирующие суда в польском реестре\"],\"practical_impact\":\"Иностранец‑моряк с дипломом из третьей страны сможет быстрее выйти в рейс на судне под польским флагом: до 3 месяцев на основании временного признания или подтверждения подачи заявления. Нужно пройти проверку подлинности документа и оплатить 30 PLN за подтверждение.\",\"effective_date\":\"Изменения по признанию документов квалификационных (art. 6 pkt 1–3, 5–7, 10) вступают в силу через 14 дней со дня официального опубликования закона.\",\"confidence\":0.86,\"rationale\":\"Проект прямо изменяет правила признания иностранных морских дипломов и допуска иностранных моряков к работе на судах под польским флагом, что существенно для занятости (категория „employment”, важность 4).\",\"changes_since_previous\":[\"Уточнено, что для документов из стран, не признанных Еврокомиссией, временное признание возможно только после подачи Польшей официального wniosku do KE о признании этой страны (новый ust. 6 art. 67).\",\"Чётко разделены два механизма: краткосрочное признание зарубежного документа (до 3 мес.) и допуск к работе по одному лишь подтверждению подачи заявления (также до 3 мес., ust. 7–8).\",\"В тексте подробно прописано, что и временное признание, и подтверждение подачи заявления выдаются только после позитивной проверки подлинности иностранного документа квалификации.\",\"Сохранена, но теперь явно указана в załączniku фиксированная плата 30 PLN за подтверждение подачи wniosku о признании документа.\"]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":288205,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-02T14:56:37Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157968/13157969/dokument800294.zip\",\"source_kind\":\"rcl\",\"revision\":2,\"text_sha256\":\"f80b38830cd42ba5dcec1207547dea96d3a21b7ebd28b1a2dac0a251aea614cb\",\"law_sha256\":\"9905bda2732b2835f7398323ab30026ea480ae68a1f1ab65d544e9a5f1c1d2ab\",\"source_checked_at\":\"2026-10-02T14:56:37Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12402353,\"title\":\"Projekt ustawy o rejestracji statków pod polską banderą\",\"applicant\":\"Minister Infrastruktury\",\"wykaz_number\":\"UDER84\",\"wykaz_url\":\"https://www.gov.pl/web/premier/projekt-ustawy-o-rejestracji-statkow-pod-polska-bandera\",\"created\":\"2025-09-22\",\"modified\":\"2026-10-02\",\"departments\":[\"gospodarka morska\"],\"keywords\":[\"STATKI MORSKIE\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13157930,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"catalog_read\":false},{\"id\":13157931,\"number\":2,\"name\":\"Uzgodnienia\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-09-11\",\"folders\":[{\"id\":13157932,\"name\":\"Projekt\",\"modified\":\"2026-05-15\",\"documents\":[{\"id\":738389,\"name\":\"projekt-uzgodnienia.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument738389.pdf\",\"created\":\"2025-09-22\",\"author\":\"Minister Infrastruktury\"},{\"id\":738391,\"name\":\"uzasadnienie-uzgodnienia.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument738391.pdf\",\"created\":\"2025-09-22\",\"author\":\"Minister Infrastruktury\"},{\"id\":738393,\"name\":\"OSR-uzgodnienia.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument738393.pdf\",\"created\":\"2025-09-22\",\"author\":\"Minister Infrastruktury\"},{\"id\":776348,\"name\":\"projekt2 - uzgodnienia.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument776348.pdf\",\"created\":\"2026-05-15\",\"author\":\"Minister Infrastruktury\"},{\"id\":776349,\"name\":\"projekt2 - uzgodnienia.docx\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument776349.docx\",\"created\":\"2026-05-15\",\"author\":\"Minister Infrastruktury\"},{\"id\":776350,\"name\":\"uzasadnienie2 - uzgodnienia.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157931/13157932/dokument776350.pdf\",\"