INSERT INTO "publications" VALUES(85,10,'RCL/12408952','new_bill','sent','@lex_inform_pl',81,'[]',NULL,'2026-10-07T19:38:44+00:00','2026-10-07T19:38:44+00:00',NULL,0,NULL,'892db95c5803fa353b768bfde3093b1e3431468bc4039c9d8b2cf9872fb139bb','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12408952\",\"title\":\"Projekt ustawy o zmianie ustawy – Prawo konsularne oraz niektórych innych ustaw\",\"description\":\"KONSULARNE PRAWO; sprawy zagraniczne\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-04-07\",\"document_date\":\"2026-08-11\",\"change_date\":\"2026-10-07T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12408952\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obywatelstwo\",\"text:wizy\",\"text:legalizacja\",\"text:obywatele_innych_panstw\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"21c827d742656001809fa046e38d9443179510b069446deff34310c2ab3397ba\",\"observed_closure_date\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект меняет «Право консульское», закон о иностранцах и др. Появится электронная платформа ePUK для связи с консулом, шире привлекаются внешние визовые центры и собираются данные при записи на визу. Визы для докторантов и стипендиатов NAWA получат приоритет.\",\"key_changes\":[\"Запись на подачу на нацвизу и повторный приём заявлений можно поручать визовым центрам за плату\",\"При онлайн‑записи на визу консул/центр может временно обрабатывать биометрию и больше данных из паспорта\",\"Нацвизы для докторантов, исследователей и стипендиатов NAWA и Минкультуры рассматриваются в приоритете\",\"Создаётся реестр иностранцев‑стипендиатов и участников программ NAWA с доступом МИД и консулов\",\"Консулы подтверждают profil zaufany только гражданам Польши, ЕС и ЕАСТ, а не всем иностранцам\"],\"affected_groups\":[\"иностранцы, подающие на национальную визу в Польшу\",\"иностранные студенты и докторанты, исследователи\",\"иностранные стипендиаты и участники программ NAWA\",\"иностранцы, пользующиеся услугами визовых центров\",\"иностранные охранники официальных делегаций с оружием\"],\"practical_impact\":\"Для заявителей на визу станет шире использование внешних визовых центров с дополнительной сервисной оплатой и сбором более полного набора данных при онлайн‑записи. Докторанты, исследователи и стипендиаты NAWA/Минкульт смогут рассчитывать на более быстрый приём и рассмотрение заявлений.\",\"effective_date\":\"В целом закон вступает в силу через 14 дней после опубликования; нормы о квалификации консулов (art. 1 pkt 5–13) – через 3 месяца; przepisy art. 9 (реестр NAWA) – через 6 месяцев; положения о системе ePUK (art. 1 pkt 29, 36–37, 43 lit. b–c, 44, 47–48 и art. 11 ust. 2) – с даты, указанной в официальном сообщении министра иностранных дел.\",\"confidence\":0.86,\"rationale\":\"Проект прямо изменяет ustawę o cudzoziemcach в части визовых процедур и приоритета рассмотрения, а также вводит реестр иностранных стипендиатов NAWA, что затрагивает легализацию въезда и статус иностранцев.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":227202,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-07T19:38:39Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument791693.pdf\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"text-v2:2eb2bdff200ad583e341c313896b4652ff2957b20faea77bba18668220b8f90c\",\"law_sha256\":\"law-v2:dfb553aba9fca7357cf37e7ee22a6a74faf1cf4bdfe128d611b535ced4bb5fee\",\"source_checked_at\":\"2026-10-07T19:38:39Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12408952,\"title\":\"Projekt ustawy o zmianie ustawy – Prawo konsularne oraz niektórych innych ustaw\",\"applicant\":\"Minister Spraw Zagranicznych\",\"wykaz_number\":\"UPRO6\",\"wykaz_url\":\"https://www.gov.pl/web/premier/wplip-rm\",\"created\":\"2026-04-07\",\"modified\":\"2026-10-07\",\"departments\":[\"sprawy zagraniczne\"],\"keywords\":[\"KONSULARNE PRAWO\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13196537,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"catalog_read\":false},{\"id\":13196538,\"number\":2,\"name\":\"Uzgodnienia\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-10-07\",\"folders\":[],\"catalog_read\":false},{\"id\":13196544,\"number\":3,\"name\":\"Konsultacje publiczne\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"