Spraw Zagranicznych\"},{\"id\":801250,\"name\":\"UPK - uzasadnienie III (1).pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196551/dokument801250.pdf\",\"created\":\"2026-10-07\",\"author\":\"Minister Spraw Zagranicznych\"}]},{\"id\":13196552,\"name\":\"Pisma kierujące projekt do opiniowania\",\"modified\":\"2026-10-07\",\"documents\":[{\"id\":770213,\"name\":\"MSZ pismo przewodnie opiniownie.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196552/dokument770213.pdf\",\"created\":\"2026-04-07\",\"author\":\"Minister Spraw Zagranicznych\"},{\"id\":791695,\"name\":\"MSZ pismo przewodnie opiniowanie i konsultacje (1).pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196552/dokument791695.pdf\",\"created\":\"2026-08-11\",\"author\":\"Minister Spraw Zagranicznych\"},{\"id\":801251,\"name\":\"MSZ pismo przewodnie opiniowanie III.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196552/dokument801251.pdf\",\"created\":\"2026-10-07\",\"author\":\"Minister Spraw Zagranicznych\"}]},{\"id\":13196553,\"name\":\"Stanowiska zgłoszone w ramach opiniowania\",\"modified\":\"2026-10-07\",\"documents\":[{\"id\":773650,\"name\":\"Opiniowanie DPNT.401.138.2026_opinia_PUODO.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196553/dokument773650.pdf\",\"created\":\"2026-04-27\",\"author\":\"Minister Spraw Zagranicznych\"},{\"id\":773651,\"name\":\"Opiniowanie NAWA ustawa prawo konsularne.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196553/dokument773651.pdf\",\"created\":\"2026-04-27\",\"author\":\"Minister Spraw Zagranicznych\"},{\"id\":791697,\"name\":\"zestawienie_uwag_opiniowanie_05082026.pdf\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408952/13196550/13196553/dokument791697.pdf\",\"created\":\"2026-08-11\",\"author\":\"Minister Spraw Zagranicznych\"},{\"id\":801252,\"name\":\"op. PUODO II tura.pdf\",\"url\":\"https://legislacj