INSERT INTO "publications" VALUES(92,10,'3160','agenda','sent','@lex_inform_pl',83,'[]',NULL,'2026-10-08T17:30:02+00:00','2026-10-08T17:30:03+00:00',NULL,0,'sejm/67/2026-10-20',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3160\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-01\",\"document_date\":\"2026-10-01\",\"change_date\":\"2026-10-08T17:27:11Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-169-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:nieruchomosci_cudzoziemcy\",\"text:praca_sezonowa\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-01\",\"print_number\":\"3160\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-01\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-01\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"Sejm\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"stages_fingerprint\":\"f65da2688c30cb2e7ecf90ffbc933390e21561c0129c788e2374286c031fc9ec\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-01\",\"print_number\":\"3160\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-01\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-01\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"Sejm\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"text-v2:82e96f6568b7893f7cf0cf0474d26b5fb441d49c2642665ac71cdf6e3faed013\",\"analysis_revision\":2,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":2,\"category\":\"indirect\",\"summary\":\"Проект реформирует систему налоговых льгот для новых инвестиций (Polska Strefa Inwestycji) и одновременно отменяет ст. 3a в законе о покупке недвижимости иностранцами. Это немного меняет правила приобретения недвижимости для нерезидентов.\",\"key_changes\":[\"Отменяется ст. 3a закона от 24.03.1920 о приобретении недвижимости иностранцами.\"],\"affected_groups\":[\"иностранцы, покупающие недвижимость в Польше\",\"иностранные инвесторы, планирующие покупку земли или объектов в Польше\"],\"practical_impact\":\"Правила получения разрешений на покупку недвижимости иностранцами изменятся из‑за отмены ст. 3a: часть нынешних исключений или условий может исчезнуть или измениться. Перед сделкой нужно будет сверяться с обновлённой версией закона и, при необходимости, получать новое разрешение МВД.\",\"effective_date\":\"Для изменений в законе о приобретении недвижимости иностранцами (art. 2): с 31 декабря 2027 г.\",\"confidence\":0.74,\"rationale\":\"Проект прямо изменяет ustawę o nabywaniu nieruchomości przez cudzoziemców, влияя на условия покупки недвижимости иностранцами, но не затрагивает правила легализации пребывания, поэтому значение среднее и категория – косвенное воздействие.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":213997,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-05T21:29:37Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\",\"source_kind\":\"print\",\"revision\":2,\"text_sha256\":\"text-v2:82e96f6568b7893f7cf0cf0474d26b5fb441d49c2642665ac71cdf6e3faed013\",\"law_sha256\":\"law-v2:216077303ec00b1e1d64dfc9c53aa3df3621b86744306112a0020dafa93b77f2\",\"source_checked_at\":\"2026-10-05T21:29:37Z\"},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/33024/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"zmian w zasadach działania Polskiej Strefy Inwestycji (PSI)\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-10-01\",\"print_number\":\"3160\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji o rządowym projekcie ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw (druki nr 3160 i )\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T18:56:08Z\",\"last_checked_at\":\"2026-10-08T17:29:30Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji o rządowym projekcie