n\":0,\"not_participating\":26,\"sitting\":65,\"voting_number\":86,\"date\":\"2026-09-18T09:15:44Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/65/86/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Stanowisko Senatu\",\"stage_type\":\"SenatePosition\",\"date\":\"2026-09-24\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":\"nie wniósł poprawek\",\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Ustawę przekazano Prezydentowi do podpisu\",\"stage_type\":\"ToPresident\",\"date\":\"2026-09-24\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-09-18\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"kind\":\"text_after3\",\"extra_urls\":[]},\"analysis_sha256\":\"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a\",\"analysis_revision\":2,\"seen_supplements\":[\"2846-001\",\"2846-002\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"legal_stay\",\"summary\":\"Специальный закон об организации Всемирного скаутского Джамбори в Гданьске в 2027 году. Для иностранцев главное: участники освобождаются от консульского сбора за национальную и шенгенскую визу, а их заявления рассматриваются без лишней задержки. Остальные нормы касаются медицины, санитарии, строительства и безопасности.\",\"key_changes\":[\"Освобождение от консульского сбора за национальную визу и визу Шенген для участников Джамбори\",\"Нужно приложить подтверждение регистрации участия или иной документ об участии\",\"Рассмотрение «без излишней задержки», если консула уведомили не позднее чем за 6 недель до начала\",\"Срок 6 недель не действует для глав государств, членов правительств, монархов и официальных делегаций\",\"Волонтёры не из ЕС должны представить справки о несудимости из стран гражданства и проживания за 10 лет\"],\"affected_groups\":[\"иностранные участники Всемирного скаутского Джамбори, нуждающиеся в визе\",\"иностранные волонтёры, работающие с несовершеннолетними участниками\",\"официальные иностранные делегации\"],\"practical_impact\":\"Иностранные участники Джамбори не платят консульский сбор за визу при наличии подтверждения регистрации и получают ускоренное рассмотрение при уведомлении консула за 6 недель. Волонтёры-иностранцы для работы с детьми обязаны собрать справки о несудимости из стран гражданства и проживания за последние 10 лет.\",\"effective_date\":\"Закон вступает в силу по истечении 14 дней со дня опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон содержит визовые льготы (сфера легализации въезда), но узкие и разовые — только для участников одного мероприятия, поэтому оценка средняя.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":27534,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-28T15:56:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":2,\"text_sha256\":\"f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a\",\"law_sha256\":null,\"source_checked_at\":\"2026-09-28T15:56:32Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/25576/2026\",\"title\":\"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.\",\"description\":\"uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-07-23\",\"print_number\":\"2846\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"2846-001\",\"2846-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-08T17:30:54Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":"{\"key\":\"president\",\"committees\":[],\"date\":null,\"deadline\":\"2026-10-15\",\"deadline_exact\":true,\"since\":\"2026-09-24\"}","hearing_json":null,"today":"2026-10-08","still_meets":false,"reply_to":66,"held_change_ids":[],"with_act":false}',NULL);
INSERT INTO "publications" VALUES(96,10,'RPW/33929/2026','new_bill','sent','@lex_inform_pl',86,'[]',NULL,'2026-10-09T07:38:34+00:00','2026-10-09T07:38:35+00:00',NULL,0,NULL,'ce1480c57f72bc68b447a4134f62d05331adf106257dcdc3464504347053f062','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RPW/33929/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\",\"description\":\"zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-08\",\"document_date\":\"2026-10-08\",\"change_date\":\"2026-10-08T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\"],\"stages\":[],\"stages_fingerprint\":null,\"observed_closure_date\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.\",\"key_changes\":[\"Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией\",\"Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии\",\"Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS\",\"Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу\",\"Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты\"],\"affected_groups\":[\"иностранные докторанты польских школ докторантских\",\"иностранцы, завершившие обучение в школе докторантской и готовящие защиту\",\"вузы и научные учреждения, ведущие школы докторантские с иностранцами\"],\"practical_impact\":\"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.\",\"effective_date\":\"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":68211,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T07:38:31Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-33929-2026/$file/10-RPW-33929-2026.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:671110a797f75f62e946bcd580fb507f4f591a40dec42fc59e7874e69a5abde7\",\"law_sha256\":\"law-v2:8c9f289a9c507825256be59e5306e676356ecd300e9c57646c1ece5096ee9060\",\"source_checked_at\":\"2026-10-09T07:38:31Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/33929/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\",\"description\":\"zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-10-08\",\"print_number\":null,\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-09T07:28:41Z\",\"last_checked_at\":\"2026-10-09T07:28:41Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":null,"held_change_ids":[],"with_act":false}',NULL);
INSERT INTO "publications" VALUES(97,10,'2644','status_update','sent','@lex_inform_pl',87,'[]',73,'2026-10-09T14:42:47+00:00','2026-10-09T14:42:47+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"2644\",\"title\":\"Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny\",\"description\":\"projekt dotyczy włączenie artystów zawodowych do systemu zabezpieczenia społecznego; stworzenia możliwości aplikowania o przyznanie im uprawnienia do otrzymania dopłaty celem uzupełnienia finansowania ich składek na ubezpieczenia społeczne i zdrowotne do poziomu składek wynikających z minimalnego wynagrodzenia za pracę. Dopłata ma obejmować również składki na Fundusz Pracy oraz Fundusz Emerytur Pomostowych. Artyści osiągający tym samym najniższe dochody będą uprawnieni do wsparcia finansowego w opłaceniu składek w okresach, w których ich własne dochody nie będą pozwalać na pokrycie składek.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-06-03\",\"document_date\":\"2026-06-03\",\"change_date\":\"2026-10-09T12:09:24Z\",\"closure_date\":\"2026-10-08\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-79-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-79-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:uchodzcy\",\"text:wizy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:ochrona_miedzynarodowa\",\"text:status_uchodzcy\",\"text:obywatele_innych_panstw\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-06-03\",\"print_number\":\"2644\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"m