czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":66,\"decision\":\"uchwalono\",\"committee_code\":null,\"report_file\":null,\"text_after3\":\"https://api.sejm.gov.pl/sejm/term10/processes/2644/attachment/2644_u3.pdf\",\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-10-08\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[]},\"analysis_sha256\":\"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72\",\"analysis_revision\":1,\"seen_supplements\":[\"2644-001\",\"2644-002\",\"2644-003\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Законопроект вводит «статус артиста» (status artysty) и доплату государства к взносам ZUS и на медстрахование для людей творческих профессий с низкими доходами. Иностранцы с определёнными видами легального пребывания в Польше прямо включены в круг заявителей.\",\"key_changes\":[\"Статус артиста на 5 лет (после трёх раз — на 8) выдаёт dyrektor Instytucji, решение обжалуется министру\",\"Право подать заявление имеют граждане ЕС/ЕЭЗ/Швейцарии и члены семей с правом пребывания\",\"Иностранцы с pobyt stały, rezydent UE, рядом zezwoleń na pobyt czasowy (в т.ч. ст. 114, 127, 151, 139a), беженцы и лица с доп. защитой — тоже\",\"Исключены лица с разрешением на пребывание и работу до 9 месяцев (или до 6 мес. для научных случаев)\",\"Доплата назначается ZUS при среднем доходе за 3 года не выше 125% годового минимального заработка\"],\"affected_groups\":[\"граждане ЕС/ЕЭЗ/Швейцарии и члены их семей в Польше\",\"иностранцы с pobyt stały и rezydent długoterminowy UE\",\"обладатели отдельных zezwoleń na pobyt czasowy (работа, ICT, научные исследования)\",\"беженцы и лица с дополнительной защитой\",\"граждане Великобритании по Brexit-соглашению\"],\"practical_impact\":\"Иностранцы-творческие работники с подходящим основанием пребывания смогут получить статус артиста и войти в систему ZUS/NFZ, а при низких доходах — государственную доплату к взносам. Заявление на статус подаётся в Instytucję, на доплату — в ZUS электронно через profil informacyjny.\",\"effective_date\":\"Первый день месяца, следующего за истечением 9 месяцев со дня опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон касается социального страхования и взносов, прямо перечисляя категории иностранцев, имеющих право на статус артиста, — это социальная сфера, а не легализация пребывания.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":86933,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-18T19:07:51Z\",\"input_tokens\":44861,\"output_tokens\":851,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf\",\"source_kind\":\"committee_report\",\"revision\":1,\"text_sha256\":\"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72\",\"law_sha256\":null,\"source_checked_at\":\"2026-09-18T19:07:51Z\"},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/19231/2026\",\"title\":\"Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny\",\"description\":\"włączenie artystów zawodowych do systemu zabezpieczenia społecznego; stworzenia możliwości aplikowania o przyznanie im uprawnienia do otrzymania dopłaty celem uzupełnienia finansowania ich składek na ubezpieczenia społeczne i zdrowotne do poziomu składek wynikających z minimalnego wynagrodzenia za pracę. Dopłata ma obejmować również składki na Fundusz Pracy oraz Fundusz Emerytur Pomostowych. Artyści osiągający tym samym najniższe dochody będą uprawnieni do wsparcia finansowego w opłaceniu składek w okresach, w których ich własne dochody nie będą pozwalać na pokrycie składek.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-06-03\",\"print_number\":\"2644\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/66/2026-10-06\",\"date\":\"2026-10-06\",\"end_date\":\"2026-10-09\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":66,\"room\":null,\"text\":\"Sprawozdanie Komisji Kultury, Dziedzictwa Narodowego i Środków Przekazu o rządowym projekcie ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny (druki nr 2644 i ) - sprawozdawca poseł Krzysztof Mieszkowski.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"2644-001\",\"2644-002\",\"2644-003\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-18T19:03:49Z\",\"last_checked_at\":\"2026-10-09T14:42:47Z\"}","change_json":"{\"id\":73,\"term\":10,\"number\":\"2644\",\"old_fingerprint\":\"de7e4dc789b934d4fc633eb0cdbe888d28a499770e693777e2d8cd3c228096ec\",\"new_fingerprint\":\"bed985b8f1550ee27ff1b97e0426193f42bce4b9400edb781422b66f76876d00\",\"new_stages\":[{\"stage_name\":\"II czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":66,\"decision\":\"niezwłocznie przystąpiono do III czytania\",\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"III czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":66,\"decision\":\"uchwalono\",\"committee_code\":null,\"report_file\":null,\"text_after3\":\"https://api.sejm.gov.pl/sejm/term10/processes/2644/attachment/2644_u3.pdf\",\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_detected\":true,\"passed\":true,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":null,\"supplements\":[],\"detected_at\":\"2026-10-09T14:42:46Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":57,"held_change_ids":[],"with_act":false}',NULL);
INSERT INTO "publications" VALUES(99,10,'3146','new_bill','sent','@lex_inform_pl',88,'[]',NULL,'2026-10-10T12:46:37+00:00','2026-10-10T12:46:37+00:00',NULL,0,NULL,'b7b232933c216669099cd032cc67bc142872ad69c58a28388772cca98fb800bb','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3146\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-23\",\"document_date\":\"2026-09-23\",\"change_date\":\"2026-10-09T11:43:38Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":true,\"rcl_num\":\"RM-0610-143-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:migracja\",\"text:straz_graniczna\",\"text:granica_panstwowa\",\"text:schengen\",\"text:pracownicy_delegowani\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-23\",\"print_number\":\"3146\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after