eport_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-08\",\"print_number\":\"3196\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[]},\"analysis_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"analysis_revision\":3,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.\",\"key_changes\":[\"В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС\",\"Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы\",\"Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу\",\"В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex\",\"В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше\"],\"affected_groups\":[\"иностранцы с решениями о возврате/выдворении\",\"мигранты с неурегулированным статусом, подлежащие депортации\",\"лица, находящиеся в процедурах принудительного возвращения\"],\"practical_impact\":\"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.\",\"effective_date\":\"закон вступает в силу через 14 дней со дня его официального опубликования.\",\"confidence\":0.94,\"rationale\":\"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":25424,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T14:59:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"source_kind\":\"committee_report\",\"revision\":3,\"text_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"law_sha256\":\"law-v2:d8f3ef852ea1e280e0266d4fd204414510c5915f5b455b687f48e404e70b1825\",\"source_checked_at\":\"2026-10-09T14:59:32Z\"},\"analysis_attempts\":0,\"analysis_generation\":5,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32084/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3146\",\"eu_related\":true,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":\"RCL/12405005\",\"linked_wykaz_number\":\"UC126\",\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Administracji i Spraw Wewnętrznych o rządowym projekcie ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw (druki nr 3146 i ) - sprawozdawca poseł Artur Jarosław Łącki.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"relevant_analysis\",\"first_seen_at\":\"2026-09-28T15:32:12Z\",\"last_checked_at\":\"2026-10-10T12:46:19Z\"}","change_json":"","print_json":"{\"term\":10,\"number\":\"3146\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw.\",\"document_date\":\"2026-09-23\",\"delivery_date\":\"2026-09-28\",\"change_date\":\"2026-10-01T10:52:02Z\",\"attachments\":[{\"print_number\":\"3146\",\"name\":\"3146.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf\"},{\"print_number\":\"3146\",\"name\":\"3146-ustawa.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146-ustawa.docx\"},{\"print_number\":\"3146\",\"name\":\"3146-uzasadnienie.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146-uzasadnienie.docx\"}],\"additional_prints\":[]}","primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":null,"held_change_ids":[],"with_act":false}',NULL);
INSERT INTO "publications" VALUES(100,10,'RCL/12411950','new_bill','sent','@lex_inform_pl',89,'[]',NULL,'2026-10-10T12:46:37+00:00','2026-10-10T12:46:38+00:00',NULL,0,NULL,'40384f08a86cf74b666c823d65dd0b5358186872397b06e717fc6f42b6ed2ca0','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12411950\",\"title\":\"Projekt ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw\",\"description\":\"TRANSPORT DROGOWY; transport\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-06-30\",\"document_date\":\"2026-06-30\",\"change_date\":\"2026-10-08T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12411950\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"43a0b7c3b72431342d82aad01837745e53733404650a764b9a29cceae3b366c4\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument784828.pdf\",\"kind\":\"rcl\",\"extra_urls\":[]},\"analysis_sha256\":\"text-v2:373b3fe1580566c755268bed86e244514711999ed475d7dbc4ed7f1fd1f4f91e\",\"analysis_revision\":2,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект полностью меняет систему обучения и экзаменов на польские права, вводит цифровую карту курсанта, запись видео экзаменов и новые сроки действия результатов. Для шеринговых самокатов и велосипедов вводится парковка только в специально обозначенных местах под угрозой эвакуации и сборов.\",\"key_changes\":[\"Вводится цифровая карта курсанта с GPS‑записью маршрутов и часов вождения\",\"Видео‑ и аудиозапись практических экзаменов (внутренних и госэкзаменов) для всех категорий\",\"Убирается экзамен на плацу для категорий B и B1, меняются правила повторной сдачи\",\"Результат теории и части плаца (другие категории) действует 24 месяца, одно‑дневные повторы ограничены\",\"Шеринговые самокаты/велосипеды можно оставлять только в обозначенных зонах, иначе эвакуация и платёж\"],\"affected_groups\":[\"иностранцы, проходящие курс и экзамен на польские права (все категории, особенно B/B1)\",\"иностранные инструкторы и владельцы автошкол\",\"пользователи шеринговых самокатов и велосипедов, включая туристов\"],\"practical_impact\":\"Кандидату на польские права придётся учитывать цифровую фиксацию всех уроков и то, что теория и часть результатов практики «сгорают» через 24 месяца. Пользователи шеринговых самокатов и велосипедов должны парковать их только в отмеченных местах, иначе транспорт могут увезти на платную стоянку.\",\"effective_date\":\"Основное: с 1 января 2027 г. Исключения: часть норм о видеозаписи экзаменов и требования к инструкторам – с 1 июля 2027 г.; przepisy о Centrum Egzaminowania, mikromobilności i др. указанные в art. 10 pkt 2–3 – соответственно с 1 января 2028 г. и 1 января 2029 г.\",\"confidence\":0.9,\"rationale\":\"Проект затрагивает правила получения польских водительских прав и пользования шеринговой микромобильностью, что напрямую влияет на быт иностранцев, но не меняет zasady pobytu, поэтому категория «social» и важность 3.\",\"changes_since_previous\":[\"Ранее текста не было; теперь ясно, что вводится цифровая карта курсанта с GPS и двусторонним подтверждением занятий\",\"Появились точные правила видеозаписи внутренних и госэкзаменов и сроки хранения записей\",\"Уточнено, что для категорий B/B1 отменяется плац, меняются условия повторной сдачи и срок важности теории 24 месяца\",\"Появились нормы о Centrum Egzaminowania и сокращении базы тестовых вопросов до 1500\",\"Добавлены конкретные правила для шеринговых самокатов/велосипедов: обязательные места парковки, эвакуация и тарифы\",\"Wskazano dokładne daty wejścia w życie poszczególnych grup przepisów (2027–2029)\"]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":127449,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-09T14:59:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument784828.pdf\",\"source_kind\":\"rcl\",\"revision\":2,\"text_sha256\":\"text-v2:373b3fe1580566c755268bed86e244514711999ed475d7dbc4ed7f1fd1f4f91e\",\"law_sha256\":\"law-v2:ffc6d32a0cd0a25dd5729bb79e8443596a5eaded4b5ce2a13ac77ebe34f226e7\",\"source_checked_at\":\"2026-10-09T14:59:32Z\"},\"analysis_attempts\":0,\"analysis_generation\":3,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12411950,\"title\":\"Projekt ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw\",\"applicant\":\"Minister Infrastruktury\",\"wykaz_number\":\"UD402\",\"wykaz_url\":\"https://www.gov.pl/web/premier/wplip-rm\",\"created\":\"2026-06-30\",\"modified\":\"2026-10-08\",\"departments\":[\"transport\"],\"keywords\":[\"TRANSPORT DROGOWY\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13212201,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"catalog_read\":false},{\"id\":13212202,\"number\":2,\"name\":\"Uzgodnienia\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-10-05\",\"folders\":[{\"id\":13212203,\"name\":\"Projekt\",\"modified\":\"2026-10-05\",\"d