on\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-08\",\"print_number\":\"3196\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[]},\"analysis_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"analysis_revision\":3,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.\",\"key_changes\":[\"В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС\",\"Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы\",\"Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу\",\"В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex\",\"В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше\"],\"affected_groups\":[\"иностранцы с решениями о возврате/выдворении\",\"мигранты с неурегулированным статусом, подлежащие депортации\",\"лица, находящиеся в процедурах принудительного возвращения\"],\"practical_impact\":\"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.\",\"effective_date\":\"закон вступает в силу через 14 дней со дня его официального опубликования.\",\"confidence\":0.94,\"rationale\":\"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":25424,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T14:59:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"source_kind\":\"committee_report\",\"revision\":3,\"text_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"law_sha256\":\"law-v2:d8f3ef852ea1e280e0266d4fd204414510c5915f5b455b687f48e404e70b1825\",\"source_checked_at\":\"2026-10-09T14:59:32Z\"},\"analysis_attempts\":0,\"analysis_generation\":5,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32084/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3146\",\"eu_related\":true,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":\"RCL/12405005\",\"linked_wykaz_number\":\"UC126\",\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Administracji i Spraw Wewnętrznych o rządowym projekcie ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw (druki nr 3146 i ) - sprawozdawca poseł Artur Jarosław Łącki.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-28T15:32:12Z\",\"last_checked_at\":\"2026-10-10T12:46:19Z\"}","change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Administracji i Spraw Wewnętrznych o rządowym projekcie ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw (druki nr 3146 i ) - sprawozdawca poseł Artur Jarosław Łącki.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}","moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":88,"held_change_ids":[],"with_act":false}',NULL);
INSERT INTO "publications" VALUES(102,10,'2644','status_update','sent','@lex_inform_pl',91,'[]',87,'2026-10-11T13:10:48+00:00','2026-10-11T13:10:48+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"2644\",\"title\":\"Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny\",\"description\":\"projekt dotyczy włączenie artystów zawodowych do systemu zabezpieczenia społecznego; stworzenia możliwości aplikowania o przyznanie im uprawnienia do otrzymania dopłaty celem uzupełnienia finansowania ich składek na ubezpieczenia społeczne i zdrowotne do poziomu składek wynikających z minimalnego wynagrodzenia za pracę. Dopłata ma obejmować również składki na Fundusz Pracy oraz Fundusz Emerytur Pomostowych. Artyści osiągający tym samym najniższe dochody będą uprawnieni do wsparcia finansowego w opłaceniu składek w okresach, w których ich własne dochody nie będą pozwalać na pokrycie składek.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-06-03\",\"document_date\":\"2026-06-03\",\"change_date\":\"2026-10-09T12:09:24Z\",\"closure_date\":\"2026-10-08\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-79-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-79-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:uchodzcy\",\"text:wizy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:ochrona_miedzynarodowa\",\"text:status_uchodzcy\",\"text:obywatele_innych_panstw\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-06-03\",\"print_number\":\"2644\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"