ny projekt ustawy\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"II czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":66,\"decision\":\"niezwłocznie przystąpiono do III czytania\",\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"III czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":66,\"decision\":\"uchwalono\",\"committee_code\":null,\"report_file\":null,\"text_after3\":\"https://api.sejm.gov.pl/sejm/term10/processes/2644/attachment/2644_u3.pdf\",\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":232,\"no\":197,\"abstain\":4,\"not_participating\":27,\"sitting\":66,\"voting_number\":106,\"date\":\"2026-10-08T18:56:58Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/66/106/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-10-08\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[]},\"analysis_sha256\":\"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72\",\"analysis_revision\":1,\"seen_supplements\":[\"2644-001\",\"2644-002\",\"2644-003\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Законопроект вводит «статус артиста» (status artysty) и доплату государства к взносам ZUS и на медстрахование для людей творческих профессий с низкими доходами. Иностранцы с определёнными видами легального пребывания в Польше прямо включены в круг заявителей.\",\"key_changes\":[\"Статус артиста на 5 лет (после трёх раз — на 8) выдаёт dyrektor Instytucji, решение обжалуется министру\",\"Право подать заявление имеют граждане ЕС/ЕЭЗ/Швейцарии и члены семей с правом пребывания\",\"Иностранцы с pobyt stały, rezydent UE, рядом zezwoleń na pobyt czasowy (в т.ч. ст. 114, 127, 151, 139a), беженцы и лица с доп. защитой — тоже\",\"Исключены лица с разрешением на пребывание и работу до 9 месяцев (или до 6 мес. для научных случаев)\",\"Доплата назначается ZUS при среднем доходе за 3 года не выше 125% годового минимального заработка\"],\"affected_groups\":[\"граждане ЕС/ЕЭЗ/Швейцарии и члены их семей в Польше\",\"иностранцы с pobyt stały и rezydent długoterminowy UE\",\"обладатели отдельных zezwoleń na pobyt czasowy (работа, ICT, научные исследования)\",\"беженцы и лица с дополнительной защитой\",\"граждане Великобритании по Brexit-соглашению\"],\"practical_impact\":\"Иностранцы-творческие работники с подходящим основанием пребывания смогут получить статус артиста и войти в систему ZUS/NFZ, а при низких доходах — государственную доплату к взносам. Заявление на статус подаётся в Instytucję, на доплату — в ZUS электронно через profil informacyjny.\",\"effective_date\":\"Первый день месяца, следующего за истечением 9 месяцев со дня опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон касается социального страхования и взносов, прямо перечисляя категории иностранцев, имеющих право на статус артиста, — это социальная сфера, а не легализация пребывания.\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":86933,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-18T19:07:51Z\",\"input_tokens\":44861,\"output_tokens\":851,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3082/3082.pdf\",\"source_kind\":\"committee_report\",\"revision\":1,\"text_sha256\":\"ad1e8979d087cde24004e2a6bf74e16d4fd297120c3dececc46f370532e1ef72\",\"law_sha256\":null,\"source_checked_at\":\"2026-09-18T19:07:51Z\"},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/19231/2026\",\"title\":\"Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny\",\"description\":\"włączenie artystów zawodowych do systemu zabezpieczenia społecznego; stworzenia możliwości aplikowania o przyznanie im uprawnienia do otrzymania dopłaty celem uzupełnienia finansowania ich składek na ubezpieczenia społeczne i zdrowotne do poziomu składek wynikających z minimalnego wynagrodzenia za pracę. Dopłata ma obejmować również składki na Fundusz Pracy oraz Fundusz Emerytur Pomostowych. Artyści osiągający tym samym najniższe dochody będą uprawnieni do wsparcia finansowego w opłaceniu składek w okresach, w których ich własne dochody nie będą pozwalać na pokrycie składek.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-06-03\",\"print_number\":\"2644\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"2644-001\",\"2644-002\",\"2644-003\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-18T19:03:49Z\",\"last_checked_at\":\"2026-10-11T13:10:48Z\"}","change_json":"{\"id\":87,\"term\":10,\"number\":\"2644\",\"old_fingerprint\":\"366dce31ea5522265195a27667518705a804d7d75e074a6863d7791fd53d8fba\",\"new_fingerprint\":\"b9df05a5d552a5db8e9918f10e8b2d62bcfd29cadd6d3ae26c4bba6aa4fc7a36\",\"new_stages\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":232,\"no\":197,\"abstain\":4,\"not_participating\":27,\"sitting\":66,\"voting_number\":106,\"date\":\"2026-10-08T18:56:58Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/66/106/pdf\",\"clubs\":[{\"club\":\"KO\",\"yes\":154,\"no\":0,\"abstain\":0,\"absent\":2},{\"club\":\"PSL-TD\",\"yes\":30,\"no\":0,\"abstain\":0,\"absent\":2},{\"club\":\"Lewica\",\"yes\":20,\"no\":0,\"abstain\":0,\"absent\":1},{\"club\":\"Polska2050\",\"yes\":14,\"no\":0,\"abstain\":0,\"absent\":1},{\"club\":\"PiS\",\"yes\":5,\"no\":131,\"abstain\":1,\"absent\":10},{\"club\":\"Razem\",\"yes\":4,\"no\":0,\"abstain\":0,\"absent\":0},{\"club\":\"niez.\",\"yes\":3,\"no\":2,\"abstain\":1,\"absent\":1},{\"club\":\"Centrum\",\"yes\":2,\"no\":7,\"abstain\":1,\"absent\":5},{\"club\":\"RozwojPlus\",\"yes\":0,\"no\":35,\"abstain\":1,\"absent\":4},{\"club\":\"Konfederacja\",\"yes\":0,\"no\":15,\"abstain\":0,\"absent\":1},{\"club\":\"Demokracja\",\"yes\":0,\"no\":4,\"abstain\":0,\"absent\":0},{\"club\":\"Konfederacja_KP\",\"yes\":0,\"no\":3,\"abstain\":0,\"absent\":0}]},\"committee_name\":null,\"children\":[]}],\"closure_detected\":false,\