ull,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"10. Komisja Prawnicza\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"2f0021a0ac23e6eba08157bfab4b739df7054744c5308f732870b287ecc73405\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129955/13129956/dokument782506.zip\",\"kind\":\"rcl\",\"extra_urls\":[]},\"analysis_sha256\":\"524157fa25a212119ccdf0eaa03ac7361481e0897a566f90548b9b3a13c50ed6\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект полностью перестраивает правила рефундации лекарств и медизделий за счёт NFZ, вводит новые ИТ‑системы и упрощённые процедуры. Это может улучшить доступ к дорогим и редким лекарствам для всех застрахованных, в т.ч. иностранцев, и меняет данные, которые указываются в рецептах и заявках на возмещение.\",\"key_changes\":[\"Новые процедуры и ИТ‑системы для рефундации и мониторинга программ лековых (SOLR, SOID, System Monitorowania Programów Lekowych, SWDPL)\",\"Подробная регламентация импортa целевого и его рефундации, в т.ч. по заявлению пациента с PESEL или с паспортом, если PESEL нет\",\"Отдельный учёт пациентов с правами по координации ЕС: личный идентификационный номер и данные иностранной институции на рецептах\",\"Расширение и упорядочение рефундации редких («сиротских») лекарств, с новой многофакторной оценкой\",\"Уточнение данных в рецептах и отчётности аптек (коды болезней ICD‑10, номера документов, коды для координации ЕС и пр.)\"],\"affected_groups\":[\"Все застрахованные пациенты NFZ, включая иностранцев\",\"Иностранцы без номера PESEL, подающие заявки на индивидуальную рефундацию импортируемых лекарств/питания\",\"Пациенты, имеющие право на лечение по правилам координации ЕС (EHIC, S1 и др.)\",\"Аптеки и врачи, выписывающие рецепты иностранцам\"],\"practical_impact\":\"В повседневности у иностранцев с правом на NFZ изменится форма рецептов и заявлений: чаще потребуется указывать PESEL либо данные паспорта/личный номер по координации ЕС. Потенциально возрастает доступность дорогостоящих и редких лекарств за счёт упрощённых и быстрее проводимых процедур рефундации.\",\"effective_date\":\"Закон вступает в силу 1 января 2027 г., за исключением указанных статей, которые начнут действовать: через 14 дней, через 6 месяцев от дня оглашения, либо с 1 апреля 2027 г., 1 июля 2027 г. и 1 января 2028 г.\",\"confidence\":0.88,\"rationale\":\"Акт комплексно меняет правила рефундации и доступа к лекарствам в системе NFZ, что прямо затрагивает и иностранцев‑пациентов, но не меняет специальных иммиграционных режимов, поэтому это социальная сфера средней важности.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":495380,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-09-30T11:32:33Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129955/13129956/dokument782506.zip\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"524157fa25a212119ccdf0eaa03ac7361481e0897a566f90548b9b3a13c50ed6\",\"law_sha256\":\"ba40ef050ccbcbe4812e32bd7981f599b3c5ccf103eeb19131577128dc57c845\",\"source_checked_at\":\"2026-09-30T11:32:33Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12398102,\"title\":\"Projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów med