ull,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-09-30\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-09-30\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ZDR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Zdrowia\",\"children\":[]}]},{\"stage_name\":\"Praca w komisjach po I czytaniu\",\"stage_type\":\"CommitteeWork\",\"date\":\"2026-10-07\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-07\",\"print_number\":\"3193\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":9,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06\",\"analysis_revision\":1,\"seen_supplements\":[\"3157-001\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект ужесточает правила найма и оплаты труда медперсонала по контрактам с NFZ и усиливает контроль NFZ. Вводится прямое право пациента на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.\",\"key_changes\":[\"Лимит общего рабочего времени медиков и потолки почасовой/месячной оплаты по контрактам с NFZ\",\"Запрет привязки зарплаты медиков к проценту от контракта NFZ, жёсткие условия договоров\",\"Сокращение схем через компании/спółki: заказы в основном напрямую физлицам‑медикам\",\"NFZ получает расширенный доступ к меддокументации и документам о занятости, вводятся штрафы\",\"В законе о правах пациента закреплён запрет дискриминации, в т.ч. по гражданству и национальности\"],\"affected_groups\":[\"иностранцы, пользующиеся медицинской помощью в Польше (NFZ и частной)\",\"иностранные врачи, медсёстры, физиотерапевты и др., работающие в Польше по контрактам с NFZ\",\"иностранные пациенты, жалующиеся РПП на неравное обращение\"],\"practical_impact\":\"Иностранные пациенты получают прямую законную защиту от худшего обращения или отказа в помощи из‑за гражданства/национальности, проще ссылаться на это в жалобе. Иностранным медикам придётся подстраивать графики и зарплатные условия под новые лимиты времени работы и оплаты у всех работодателей.\",\"effective_date\":\"Закон вступает в силу по истечении месяца со дня его опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект системно меняет условия работы медиков и вводит прямой запрет дискриминации пациентов по гражданству и национальности, что затрагивает как иностранных пациентов, так и иностранных медработников, поэтому значимость для иностранцев средняя в социальной сфере.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":182345,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-01T19:41:36Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3157/3157.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"8d6a8231f42d443f4af4a01d2b550980d2a29fdcff6de7361a65f14a61ae8c06\",\"law_sha256\":\"91f20470de90c8ae40b69032937a961b66736ee658335374ed0715585d2d7093\",\"source_checked_at\":\"2026-10-01T19:41:36Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32531/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-28\",\"print_number\":\"3157\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":\"RCL/12412802\",\"linked_wykaz_number\":\"UD439\",\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Zdrowia o rządowym projekcie ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druki nr 3157 i ) - sprawozdawca poseł Marta Golbik.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"3157-001\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T07:15:59Z\",\"last_checked_at\":\"2026-10-12T21:51:47Z\"}","change_json":"{\"id\":99,\"term\":10,\"number\":\"3157\",\"old_fingerprint\":\"a6eb8942658610b3f54612c55eeabde7ac670e9e8c22b5cb1549850d09579b31\",\"new_fingerprint\":\"fbe85fcc295822486a910e0177c17f2b69b7ee4fcb3ec7f25967c80d925e0eb5\",\"new_stages\":[{\"stage_name\":\"Praca w komisjach po I czytaniu\",\"stage_type\":\"CommitteeWork\",\"date\":\"2026-10-07\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-07\",\"print_number\":\"3193\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":9,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-07\",\"print_number\":\"3193\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":9,\"voting\":null,\"committee_name\":null,\"children\"