INSERT INTO "publications" VALUES(119,10,'RCL/12403003','new_bill','sent','@lex_inform_pl',100,'[]',NULL,'2026-10-12T22:14:41+00:00','2026-10-12T22:14:42+00:00',NULL,0,NULL,'36b83de5947f0ae84e568a5bc542e375140efa3e9516c949777ca0a7d10b724e','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12403003\",\"title\":\"Projekt ustawy o zmianie ustawy o działalności leczniczej oraz niektórych innych ustaw\",\"description\":\"OCHRONA ZDROWIA; zdrowie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-10-09\",\"document_date\":\"2026-10-12\",\"change_date\":\"2026-10-12T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12403003\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obywatelstwo\",\"text:pobyt_kwalifikowany\",\"text:straz_graniczna\",\"text:granica_panstwowa\",\"text:ochrona_cudzoziemcow\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"5. Komitet Rady Ministrów do Spraw Cyfryzacji\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"2450c72f471340a4d7e7e8d2d61ca184b3d87acfe5516c9e08e068efb4135228\",\"observed_closure_date\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет оформление рождения, мертворождения и смерти: вводит электронные медкарты и автоматическую передачу данных в ЗАГС, статистику и санэпиднадзор. Касается всех, у кого рождение или смерть происходят в Польше, независимо от гражданства.\",\"key_changes\":[\"Вводятся e‑карта рождения, e‑карта смерти и e‑карта мертворождения.\",\"ЗАГС будет получать данные напрямую из медсистемы, без большинства бумажных справок.\",\"Появляется «urzędowy lekarz» для констатации смерти вне больницы.\",\"При рождении/смерти фиксируются гражданство, страна проживания и срок пребывания в Польше.\",\"Если у умершего нет PESEL, родственники по‑прежнему лично заявляют о смерти в ЗАГС.\"],\"affected_groups\":[\"Иностранцы, рождающие детей в Польше\",\"Семьи умерших иностранцев в Польше\",\"Иностранцы без номера PESEL, оформляющие смерть родственника\"],\"practical_impact\":\"Оформление рождения и смерти будет происходить через электронные медкарты, а ЗАГС сам получит почти все нужные данные. Иностранцам реже придётся относить медсправки в ЗАГС, но при отсутствии PESEL сохраняется обязанность личного заявления о смерти.\",\"effective_date\":\"Закон в целом вступает в силу 1 февраля 2027 г., за исключением указанных статей, которые начнут действовать на следующий день после опубликования, с 1 января 2028 г. или с 1 января 2030 г. (по перечню в ст. 20).\",\"confidence\":0.78,\"rationale\":\"Проект не меняет правил легализации пребывания, но существенно реформирует регистрацию рождений и смертей (ZUSC, PESEL, сбор данных о гражданстве и проживании), что затрагивает иностранцев в Польше по линии актов гражданского состояния, поэтому категория «social» и средняя важность.\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":208433,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-12T22:14:37Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12403003/13163123/13163124/dokument801853.zip\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"text-v2:c9d455c0bd3f56ed8c53887c30172d348e7765b91f9c286be14f94b9703e3498\",\"law_sha256\":\"law-v2:8d38a1abeb29e5fe8e3e9dc967ad5528bdffb820e4abb25830c26c3b136ef8f0\",\"source_checked_at\":\"2026-10-12T22:14:37Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12403003,\"title\":\"Projekt ustawy o zmianie ustawy o działalności leczniczej oraz niektórych innych ustaw\",\"applicant\":\"Minister Zdrowia\",\"wykaz_number\":\"UD234\",\"wykaz_url\":\"https://www.gov.pl/web/premier/wplip-rm\",\"created\":\"2025-10-09\",\"modified\":\"2026-10-12\",\"departments\":[\"zdrowie\"],\"keywords\":[\"OCHRONA ZDROWIA\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"rm_number\":null,\"sejm_url\":null,\"print_number\":null,\"stages\":[{\"id\":13163085,\"number\":1,\"name\":\"Zgłoszenia lobbingowe\",\"stat