y_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"fba5961c636c6d4f52b335214b2a9644b16730d9c6529f054ff6b767023dbe2e\",\"observed_closure_date\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12404454/13171166/13171167/dokument749803.pdf\",\"kind\":\"rcl\",\"extra_urls\":[]},\"analysis_sha256\":\"96b2a36ffb972cede864176f0bd61797487a2189acea3e6a32c4a293080369d1\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"employment\",\"summary\":\"Проект вводит новый закон о стажах вместо практик absolwenckich: все стажи на открытом рынке становятся платными и оформляются как umowa o pracę. Участвовать смогут поляки, граждане ЕС/ЕЭЗ, некоторые британцы и иностранцы с полным доступом к рынку труда по спецзакону.\",\"key_changes\":[\"Стаж = работа по umowa o pracę na czas określony, максимум 6 месяцев\",\"Минимальная оплата стажа: не ниже 65% минимальной зарплаты\",\"Круг участников: поляки, ЕС/ЕЭЗ, часть британцев, иностранцы из art. 3 ust. 1 i 5 pkt 1‑5 спецзакона\",\"Отмена ustawa o praktykach absolwenckich, бесплатные практики исчезают\",\"Стажёр получает соцстрахование как работник; данные о стажах передаются в ZUS и МРPiPS\"],\"affected_groups\":[\"Иностранцы с правом работы без zezwoleń по ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom\",\"Граждане ЕС/ЕЭЗ, Швейцарии и иных стран со свободой передвижения\",\"Некоторые граждане Великобритании и члены их семей по Umowa o wystąpieniu\",\"Иностранные выпускники и студенты, ищущие стаж на открытом рынке\",\"Организаторы стажей, нанимающие иностранных стажёров\"],\"practical_impact\":\"Иностранец с полным доступом к рынку труда сможет проходить только оплачиваемый стаж по umowa o pracę с взносами в ZUS и защитой по Kodeks pracy. Бесплатные «praktyki absolwenckie» исчезнут, но появятся чёткие минимальные ставки оплаты и стандарты стажа.\",\"effective_date\":\"Закон вступает в силу с 1 января 2027 года.\",\"confidence\":0.95,\"rationale\":\"Акт комплексно регулирует стажи как форму работы, прямо определяет круг допущенных иностранцев и условия их оплаты и страхования, что существенно для трудовых прав, но не меняет правил легализации пребывания.\",\"changes_since_previous\":[\"Минимальная оплата стажа изменена: было ≥35% средней зарплаты, стало ≥65% минимальной зарплаты без верхнего предела.\",\"Umowa o staż прямо признана umowa o pracę na czas określony с частичным применением Kodeks pracy, а не отдельным гражданско‑правовым договором.\",\"Расширен и уточнён круг иностранцев: добавлены отдельные категории граждан Великобритании и их семей и ссылка на art. 3 ust. 5 pkt 1‑5 спецзакона о работе иностранцев.\",\"Изменена модель соцстраха: взрослые стажёры страхуются как работники, а несовершеннолетние стажисты освобождены от обязательных пенсионных и рентных взносов.\",\"Подробно урегулирован «staż z małoletnim stażystą» с выплатой минимум 500 zł стажисту и дотацией 750 zł организатору за месяц.\",\"Закреплена дата вступления в силу (1.01.2027), добавлены численные лимиты на количество стажёров у одного организатора и новые составы нарушений с крупными штрафами.\"]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":115478,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-12T22:14:38Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12404454/13171191/13171192/dokument801844.zip\",\"source_kind\":\"rcl\",\"revision\":2,\"text_sha256\":\"text-v2:3cb0bf125f8d9ffba6558af943a27d6f02bb6f6b19f0ae555d738b02c8ec2244\",\"law_sha256\":\"law-v2:fde80988ad0ee8ddd1ca1ce8b82bdfbbe171fcfa38a854db236375da77d851b7\",\"source_checked_at\":\"2026-10-12T22:14:38Z\"},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12404454,\"title\"