name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-01\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-01\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"Sejm\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"I czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":66,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-08\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"GOR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Gospodarki i Rozwoju\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\",\"kind\":\"print\",\"extra_urls\":[]},\"analysis_sha256\":\"text-v2:82e96f6568b7893f7cf0cf0474d26b5fb441d49c2642665ac71cdf6e3faed013\",\"analysis_revision\":2,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":2,\"category\":\"indirect\",\"summary\":\"Проект реформирует систему налоговых льгот для новых инвестиций (Polska Strefa Inwestycji) и одновременно отменяет ст. 3a в законе о покупке недвижимости иностранцами. Это немного меняет правила приобретения недвижимости для нерезидентов.\",\"key_changes\":[\"Отменяется ст. 3a закона от 24.03.1920 о приобретении недвижимости иностранцами.\"],\"affected_groups\":[\"иностранцы, покупающие недвижимость в Польше\",\"иностранные инвесторы, планирующие покупку земли или объектов в Польше\"],\"practical_impact\":\"Правила получения разрешений на покупку недвижимости иностранцами изменятся из‑за отмены ст. 3a: часть нынешних исключений или условий может исчезнуть или измениться. Перед сделкой нужно будет сверяться с обновлённой версией закона и, при необходимости, получать новое разрешение МВД.\",\"effective_date\":\"Для изменений в законе о приобретении недвижимости иностранцами (art. 2): с 31 декабря 2027 г.\",\"confidence\":0.74,\"rationale\":\"Проект прямо изменяет ustawę o nabywaniu nieruchomości przez cudzoziemców, влияя на условия покупки недвижимости иностранцами, но не затрагивает правила легализации пребывания, поэтому значение среднее и категория – косвенное воздействие.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":213997,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-05T21:29:37Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\",\"source_kind\":\"print\",\"revision\":2,\"text_sha256\":\"text-v2:82e96f6568b7893f7cf0cf0474d26b5fb441d49c2642665ac71cdf6e3faed013\",\"law_sha256\":\"law-v2:216077303ec00b1e1d64dfc9c53aa3df3621b86744306112a0020dafa93b77f2\",\"source_checked_at\":\"2026-10-05T21:29:37Z\"},\"editorial\":{\"mnemonic\":null,\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/33024/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"zmian w zasadach działania Polskiej Strefy Inwestycji (PSI)\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-10-01\",\"print_number\":\"3160\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji o rządowym projekcie ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw (druki nr 3160 i )\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null},{\"kind\":\"committee\",\"ref\":\"GOR/162/2026-10-21+16:00+sala nr 312, bud. U\",\"date\":\"2026-10-21\",\"end_date\":null,\"start_time\":\"16:00:00\",\"committee_code\":\"GOR\",\"committee_name\":\"Komisja Gospodarki i Rozwoju\",\"sitting_number\":162,\"room\":\"sala nr 312, bud. U\",\"text\":\"Rozpatrzenie rządowego projektu ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw (druk nr 3160).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=74DA919C1E49CB35C1258E90003DC3B2\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T18:56:08Z\",\"last_checked_at\":\"2026-10-14T11:06:18Z\"}","attention":{"importance":"routine","urgency":"normal","reasons":["agenda"],"explanation":"The case appears on a sitting agenda.","affected_groups":[],"action":"wait","deadline":"2026-10-21","deadline_source":"agenda","deadline_precision":"day","detected_at":"2026-10-14T11:21:41Z","assessed_at":"2026-10-14T11:21:41Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"","disable_notification":false,"schedule":{"route":"daily_sittings","detected_at":"2026-10-14T11:21:41Z","not_before":"2026-10-14T16:00:00Z","deliver_by":"2026-10-15T11:21:41Z"},"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"committee\",\"ref\":\"GOR/162/2026-10-21+16:00+sala nr 312, bud. U\",\"date\":\"2026-10-21\",\"end_date\":null,\"start_time\":\"16:00:00\",\"committee_code\":\"GOR\",\"committee_name\":\"Komisja Gospodarki i Rozwoju\",\"sitting_number\":162,\"room\":\"sala nr 312, bud. U\",\"text\":\"Rozpatrzenie rządowego projektu ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw (druk nr 3160).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=74DA919C1E49CB35C1258E90003DC3B2\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}","moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":76,"edit_message_id":null,"held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[130,133],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"🗓 <b>Заседания</b>\n\n<b>Комиссии</b>\n\n<b>Проект вводит единый закон о санкциях (środki ograniczające) — общий порядок применения санкций ЕС и национальных санкций.</b>\n• <b><a href=\"https://t.me/lex_inform_pl/13\">druk nr 3003</a></b> — Komisja Administracji i Spraw Wewnętrznych (ASW) · 21 окт 2026, 09:30 (по времени Варшавы) · sala im. Konstytucji 3-go Maja (nr 118, bud. C) · <a href=\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=DD007749D7B495E4C1258E900038EC30\">Трансляция</a>\nЦель пункта не уточнена в структурированных данных; ниже формулировка источника.\n<i>Rozpatrzenie sprawozdania Podkomisji nadzwyczajnej o rządowym projekcie ustawy o środkach ograniczających (druk nr 3003) – przedstawia przewodnicząca Podkomisji poseł Zofia Czernow.</i>\nℹ️ Заседание объявлено условно: состоится, только если…\n\n<b>Проект реформирует систему налоговых льгот для новых инвестиций (Polska Strefa Inwestycji) и одновременно отменяет ст.</b>\n• <b><a href=\"https://t.me/lex_inform_pl/76\">druk nr 3160</a></b> — Komisja Gospodarki i Rozwoju (GOR) · 21 окт 2026, 16:00 (по времени Варшавы) · sala nr 312, bud. U · <a href=\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=74DA919C1E49CB35C1258E90003DC3B2\">Трансляция</a>\nЦель пункта не уточнена в структурированных данных; ниже формулировка источника.\n<i>Rozpatrzenie rządowego projektu ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw (druk nr 3160).</i>\n\n#заседаниекомиссии #kadencja10druk3003 #UC92 #kadencja10druk3160","with_act":false}','{"importance":"routine","urgency":"normal","reasons":["agenda"],"explanation":"The case appears on a sitting agenda.","affected_groups":[],"action":"wait","deadline":"2026-10-21","deadline_source":"agenda","deadline_precision":"day","detected_at":"2026-10-14T11:21:41Z","assessed_at":"2026-10-14T11:21:41Z","novelty":"unknown","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(134,10,'2667','act_application','sent','@lex_inform_pl',104,'[]',NULL,'2026-10-14T11:25:16+00:00','2026-10-14T11:25:17+00:00',NULL,0,'document-review:d0d364cfa98c85449ee97748692728ddca37d91c008eb0795fbb06ecf9017332',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"2667\",\"title\":\"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.\",\"description\":\"projekt dotyczy uregulowania między Polską a Albanią wzajemnych stosunków w dziedzinie zabezpieczenia społecznego, w tym wprowadzenia możliwości korzystania przy ustalaniu prawa do świadczeń długoterminowych (emerytur i rent) z zasady sumowania okresów ubezpieczenia oraz możliwości transferu świadczeń nabytych na podstawie ustawodawstwa Polski, w przypadku przeniesienia swojego miejsca zamieszkania na terytorium Albanii i odwrotnie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-06-09\",\"document_date\":\"2026-06-09\",\"change_date\":\"2026-08-27T09:19:19Z\",\"closure_date\":\"2026-07-17\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":true,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":\"DU/2026/1100\",\"display_address\":\"Dz.U. 2026 poz. 1100\",\"isap_url\":\"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001100\"},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:migracja\",\"text:uchodzcy\",\"text:obywatelstwo\",\"text:wizy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:straz_graniczna\",\"text:granica_panstwowa\",\"text:ochrona_miedzynarodowa\",\"text:schengen\",\"text:pracownicy_delegowani\",\"text:status_uchodzcy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-06-09\",\"print_number\":\"2667\",\"sitting_num\":null,\"decision\":null,\"c