dren\":[]}]},{\"stage_name\":\"Stanowisko Senatu\",\"stage_type\":\"SenatePosition\",\"date\":\"2026-07-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":\"nie wniósł poprawek\",\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Ustawę przekazano Prezydentowi do podpisu\",\"stage_type\":\"ToPresident\",\"date\":\"2026-07-27\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Prezydent podpisał ustawę\",\"stage_type\":\"PresidentSignature\",\"date\":\"2026-08-13\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"02d845bfdabced08724c6d2fe866d147adc35d34dc38bdd7ec2c95eeb002b907\",\"observed_closure_date\":\"2026-07-17\",\"consultation_review\":null,\"act_application_review\":{\"review\":{\"purpose\":\"act_application\",\"complete\":false,\"summary\":\"Ustawa „o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.” upoważnia Prezydenta Rzeczypospolitej Polskiej do ratyfikacji wskazanej umowy międzynarodowej o zabezpieczeniu społecznym między Polską i Albanią. Akt nie reguluje bezpośrednio świadczeń ani zasad zabezpieczenia społecznego – odsyła w tym zakresie do treści samej Umowy. Ustawa przewiduje wejście w życie po upływie 14 dni od dnia ogłoszenia w Dzienniku Ustaw.\",\"consultation_findings\":[],\"effective_rules\":[{\"locator\":\"Art. 1\",\"change\":\"Устанавливается, что Rzeczpospolita Polska wyraża ustawową zgodę na dokonanie przez Prezydenta Rzeczypospolitej Polskiej ratyfikacji „Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.”. Уполномочение имеет wyłącznie przedmiotowy charakter – dotyczy tylko wskazanej Umowy o zabezpieczeniu społecznym między Rzecząpospolitą Polską a Republiką Albanii.\",\"affected_groups\":[\"Prezydent Rzeczypospolitej Polskiej\",\"organy Rzeczypospolitej Polskiej właściwe do wykonywania czynności związanych z ratyfikacją umów międzynarodowych\"],\"conditions\":[\"Zgoda ustawowa obejmuje wyłącznie „Umowę między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisaną w Warszawie dnia 23 lutego 2026 r.”\"],\"exceptions\":[],\"old_applications\":\"Przed wejściem w życie ustawy brak było szczególnej ustawowej zgody na ratyfikację tej konkretnej Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym; ratyfikacja wymagała uprzedniego uchwalenia takiej ustawy upoważniającej.\",\"documents\":[\"DU/2026/1100\"],\"date_kind\":\"relative\",\"date\":\"2026-09-02\",\"days_after_promulgation\":14,\"trigger\":\"upływ 14 dni od dnia ogłoszenia ustawy w Dzienniku Ustaw\",\"evidence\":{\"document_id\":\"DU/2026/1100\",\"locator\":\"Art. 1\",\"quote\":\"Art. 1. Wyraża się zgodę na dokonanie przez Prezydenta Rzeczypospolitej Polskiej ratyfikacji Umowy między Rzeczą-\\npospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.\"},\"date_evidence\":{\"document_id\":\"DU/2026/1100\",\"locator\":\"Art. 2\",\"quote\":\"Art. 2. Ustawa wchodzi w życie po upływie 14 dni od dnia ogłoszenia.\"}},{\"locator\":\"Art. 2\",\"change\":\"Устанавливается порядок wejścia w życie ustawy: przewidziana jest vacatio legis, zgodnie z którą ustawa wchodzi w życie po upływie 14 dni od dnia jej ogłoszenia w Dzienniku Ustaw.\",\"affected_groups\":[\"adresaci ustawy, w tym Prezydent Rzeczypospolitej Polskiej oraz organy odpowiedzialne za ratyfikację i wykonywanie Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym\"],\"conditions\":[],\"exceptions\":[],\"old_applications\":\"Przed ogłoszeniem ustawy nie istniała regulacja określająca termin jej wejścia w życie; niniejszy przepis ustanawia 14‑dniowy okres vacatio legis liczony od dnia ogłoszenia.\",\"documents\":[\"DU/2026/1100\"],\"date_kind\":\"relative\",\"date\":\"2026-09-02\",\"days_after_promulgation\":14,\"trigger\":\"ogłoszenie ustawy w Dzienniku Ustaw i upływ 14 dni od tego dnia\",\"evidence\":{\"document_id\":\"DU/2026/1100\",\"locator\":\"Art. 2\",\"quote\":\"Art. 2. Ustawa wchodzi w życie po upływie 14 dni od dnia ogłoszenia.\"},\"date_evidence\":{\"document_id\":\"DU/2026/1100\",\"locator\":\"Art. 2\",\"quote\":\"Art. 2. Ustawa wchodzi w życie po upływie 14 dni od dnia ogłoszenia.\"}}],\"unresolved\":[\"Nie dostarczono tekstu „Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.”, dlatego nie można opisać szczegółowych praw i obowiązków ubezpieczonych, pracowników, pracodawców czy instytucji zabezpieczenia społecznego wynikających z samej Umowy.\",\"Ustawa określa wejście w życie wyłącznie poprzez formułę „po upływie 14 dni od dnia ogłoszenia” i nie wskazuje konkretnej kalendarzowej daty; ustalenie tej daty wymaga odrębnego sprawdzenia daty ogłoszenia w Dzienniku Ustaw i zastosowania zasad liczenia terminów.\"]},\"context\":{\"number\":\"2667\",\"title\":\"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.\",\"purpose\":\"act_application\",\"documents\":[{\"identity\":\"DU/2026/1100\",\"url\":\"https://api.sejm.gov.pl/eli/acts/DU/2026/1100/text.pdf\",\"role\":\"final_act\",\"text\":\"DZIENNIK USTAW\\nRZECZYPOSPOLITEJ POLSKIEJ\\nWarszawa, dnia 18 sierpnia 2026 r.\\nPoz. 1100\\n\\nUSTAWA\\nz dnia 17 lipca 2026 r.\\no ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym,\\npodpisanej w Warszawie dnia 23 lutego 2026 r.\\nArt. 1. Wyraża się zgodę na dokonanie przez Prezydenta Rzeczypospolitej Polskiej ratyfikacji Umowy między Rzeczą-\\npospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.\\nArt. 2. Ustawa wchodzi w życie po upływie 14 dni od dnia ogłoszenia.\\nPrezydent Rzeczypospolitej Polskiej: K. Nawrocki\",\"sha256\":\"3c3bf53885732323762e1a1739d6fb3cd88b605c35c77065c879a1407fc4cd4c\",\"normalized_sha256\":\"text-v2:cda4a5b9635b3a29d6e2c30728b7029ae202a667104025d6bc96302c6f029672\",\"complete\":true,\"file_sha256\":\"f4a126e558630edd7e9feb0ca26de1533d93ab4769050400a320797c1f5ad474\",\"author\":\"\"}],\"act_eli\":\"DU/2026/1100\",\"promulgation_date\":\"2026-08-18\",\"canonical_date\":\"2026-09-02\",\"comparison_sha256\":null},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"document-review-v1\",\"created_at\":\"2026-10-14T11:15:29Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"baseline_day\":\"2026-10-14\",\"source_key\":\"review-input:37a92d58f0fde55cc08e0ed82bf65a1e31f386f75fd02a5e32a472bf40d63ea2\",\"checked_at\":\"2026-10-14T11:25:16Z\",\"canonical_dates\":[\"2026-09-02\"]},\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-06-09\",\"print_number\":\"2667\",\"sitting_num\":null,\"decisi