t\",\"modified\":\"2026-04-20\",\"documents\":[{\"id\":772517,\"name\":\"PROJEKT - 13.04.2026.\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198662/13198663/dokument772517.doc\",\"created\":\"2026-04-20\",\"author\":\"Minister Rodziny, Pracy i Polityki Społecznej\"},{\"id\":772518,\"name\":\"UZASADNIENIE - 13.04.2026.\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198662/13198663/dokument772518.doc\",\"created\":\"2026-04-20\",\"author\":\"Minister Rodziny, Pracy i Polityki Społecznej\"},{\"id\":772519,\"name\":\"OSR - 13.04.2026.\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198662/13198663/dokument772519.doc\",\"created\":\"2026-04-20\",\"author\":\"Minister Rodziny, Pracy i Polityki Społecznej\"}]},{\"id\":13198664,\"name\":\"Pisma kierujące projekt do konsultacji publicznych\",\"modified\":\"2026-04-20\",\"documents\":[{\"id\":772520,\"name\":\"Informacja konsultacje społeczne.\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198662/13198664/dokument772520.docx\",\"created\":\"2026-04-20\",\"author\":\"Minister Rodziny, Pracy i Polityki Społecznej\"}]},{\"id\":13198665,\"name\":\"Stanowiska zgłoszone w ramach konsultacji publicznych\",\"modified\":\"2026-06-01\",\"documents\":[{\"id\":779072,\"name\":\"Stanowisko ING Banku Śląskiego S.A.\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198662/13198665/dokument779072.docx\",\"created\":\"2026-06-01\",\"author\":\"Minister Rodziny, Pracy i Polityki Społecznej\"}]},{\"id\":13198666,\"name\":\"Odniesienie się wnioskodawcy do uwag\",\"modified\":null,\"documents\":[]},{\"id\":13198667,\"name\":\"Odrębna konferencja z udziałem podmiotów publicznych\",\"modified\":null,\"documents\":[]}],\"catalog_read\":true},{\"id\":13198668,\"number\":4,\"name\":\"Opiniowanie\",\"state\":\"reached\",\"started\":null,\"ended\":null,\"modified\":\"2026-06-01\",\"folders\":[],\"catalog_read\":false},{\"id\":13198673,\"number\":5,\"name\":\"Komitet Rady Ministrów do Spr