INSERT INTO "publications" VALUES(138,10,'1929','agenda','sent','@lex_inform_pl',108,'[]',NULL,'2026-10-15T17:50:36+00:00','2026-10-16T16:56:30+00:00',NULL,0,'PSR/145/2026-10-21+14:00+sala konferencyjna im. Jacka Kuronia (bud. F)',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"1929\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"projekt dotyczy systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-11-04\",\"document_date\":\"2025-11-04\",\"change_date\":\"2026-10-14T12:37:01Z\",\"closure_date\":\"2026-09-18\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-188-25\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-188-25\",\"prints_considered_jointly\":[\"316\",\"1933\"],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:uchodzcy\",\"text:obywatelstwo\",\"text:wizy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:ochrona_miedzynarodowa\",\"text:status_uchodzcy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2025-11-04\",\"print_number\":\"1929\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":\"202