"extra_urls\":[]},\"analysis_sha256\":\"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2\",\"analysis_revision\":3,\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Закон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с перечисленными видами легального пребывания в Польше получают это право наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.\",\"key_changes\":[\"Право на услугу: ПМЖ, резидент ЕС, беженцы и доп. защита, граждане ЕС/ЕЭЗ/Швейцарии и члены семей\",\"Включены разрешения по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust. 1, 186 ust. 1 pkt 3, научная виза, Brexit-соглашение\",\"Карта побыту с отметкой ''dostęp do rynku pracy'' даёт право, кроме студентов, сезонных и краткосрочных работников\",\"Объём: 20–240 часов в месяц (18–65 лет), 20–80 часов (13–18 лет); ставки 49–55 zł брутто в час\",\"Заявление подаётся электронно; иностранец прилагает документ, дающий право на пребывание в Польше\"],\"affected_groups\":[\"иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС\",\"беженцы и лица с дополнительной защитой\",\"граждане ЕС/ЕЭЗ/Швейцарии и члены их семей\",\"обладатели карты побыту с отметкой ''dostęp do rynku pracy''\",\"работники по внутрикорпоративному переводу и научные работники\",\"граждане Великобритании по Brexit-соглашению\"],\"practical_impact\":\"Иностранец с инвалидностью, проживающий в Польше и имеющий соответствующее решение об уровне потребности в поддержке, может бесплатно получить личного ассистента; заявление подаётся только электронно с приложением документа о праве на пребывание.\",\"effective_date\":\"Через 14 дней после опубликования, с исключениями: ст. 6 ust. 1 pkt 1 и часть ст. 8 — через 12 месяцев; ст. 6 ust. 1 pkt 2 и ст. 7 ust. 2–7 — через 14 месяцев; ст. 58–67 и ст. 99 — с первого дня месяца после 5 месяцев от опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон касается социальной поддержки и прямо перечисляет категории иностранцев, получающих право на услугу, но не затрагивает легализацию пребывания или работу.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[\"В перечень оснований добавлены разрешения по ст. 159 ust. 1 и ст. 186 ust. 1 pkt 3 ustawy o cudzoziemcach\",\"Добавлены переходные ограничения максимума часов: 200 часов в 2028 г. и 220 часов в 2029 г.\",\"Уточнены сроки рассмотрения заявлений: до 120 дней (до 31.12.2028), 90 дней, затем 60 дней\",\"Детализирован поэтапный запуск: 90 баллов — через 12/16 месяцев от публикации, 85 — через 17/21, 80 — с 01.09.2028/01.01.2029\",\"Для лиц 13–18 лет и проживающих в учреждениях круглосуточного ухода — заявления с 01.05.2029, право с 01.01.2030\"]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":154338,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-22T16:01:14Z\",\"input_tokens\":77754,\"output_tokens\":1429,\"cache_read_input_tokens\":2652,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":3,\"text_sha256\":\"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2\",\"law_sha256\":null,\"source_checked_at\":\"2026-09-22T16:01:14Z\"},\"editorial\":{\"mnemonic\":null,\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/36702/2025\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2025-11-04\",\"print_number\":\"1929\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"committee\",\"ref\":\"PSR/145/2026-10-21+14:00+sala konferencyjna im. Jacka Kuronia (bud. F)\",\"date\":\"2026-10-21\",\"end_date\":null,\"start_time\":\"14:00:00\",\"committee_code\":\"PSR\",\"committee_name\":\"Komisja Polityki Społecznej i Rodziny\",\"sitting_number\":145,\"room\":\"sala konferencyjna im. Jacka Kuronia (bud. F)\",\"text\":\"Rozpatrzenie uchwały Senatu w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami (druk nr 3213).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=BC934DFB19FD9000C1258E91003EF399\",\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2170.html\",\"title\":\"Ustawa o asystencji osobistej osób z niepełnosprawnościami\",\"print_number\":\"832\",\"received\":\"2026-09-22\",\"committees\":[{\"id\":233,\"name\":\"Komisja Rodziny, Polityki Senioralnej i Społecznej\",\"email\":\"krpss@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-08\",\"2026-10-13\"],\"committee_work_completed\":false},\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"],\"joint\":null,\