:"2026-10-16T16:00:00Z","deliver_by":"2026-10-16T17:50:38Z"},"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":"{\"kind\":\"committee\",\"ref\":\"ZDR/173/2026-10-21+15:30+sala im. Olgi Krzyżanowskiej (nr 412, bud. U)\",\"date\":\"2026-10-21\",\"end_date\":null,\"start_time\":\"15:30:00\",\"committee_code\":\"ZDR\",\"committee_name\":\"Komisja Zdrowia\",\"sitting_number\":173,\"room\":\"sala im. Olgi Krzyżanowskiej (nr 412, bud. U)\",\"text\":\"Rozpatrzenie poprawek zgłoszonych w czasie drugiego czytania do projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druki nr 3141 i 3201).\",\"video_url\":\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=C961ED6560C561A9C1258E910039645E\",\"condition\":\"referral\",\"closed\":false,\"apply_email\":null,\"apply_by\":null}","moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":67,"edit_message_id":null,"held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[138,139,140],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"🗓 <b>Заседания</b>\n\n<b>Комиссии</b>\n\n<b><a href=\"https://t.me/lex_inform_pl/15\">druk nr 1929</a> · O asystencji osobistej osób z niepełnosprawnościami</b>\nKomisja Polityki Społecznej i Rodziny (PSR)\n🗓 21 окт 2026, 14:00 (по времени Варшавы)\nsala konferencyjna im. Jacka Kuronia (bud. F)\n<a href=\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=BC934DFB19FD9000C1258E91003EF399\">Трансляция</a>\n\nРассмотрение постановления Сената\n<i>Rozpatrzenie uchwały Senatu w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami (druk nr 3213).</i>\n\n<b><a href=\"https://t.me/lex_inform_pl/67\">druk nr 3141</a> · O świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw</b>\nKomisja Zdrowia (ZDR)\n🗓 21 окт 2026, 15:30 (по времени Варшавы)\nsala im. Olgi Krzyżanowskiej (nr 412, bud. U)\n<a href=\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=C961ED6560C561A9C1258E910039645E\">Трансляция</a>\n\nВ повестке:\n<i>Rozpatrzenie poprawek zgłoszonych w czasie drugiego czytania do projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druki nr 3141 i 3201).</i>\nℹ️ Заседание объявлено условно: состоится, только если Сейм направит проект в эту комиссию.\n\n<b><a href=\"https://t.me/lex_inform_pl/75\">druk nr 3157</a> · O świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw</b>\nKomisja Zdrowia (ZDR)\n🗓 21 окт 2026, 15:30 (по времени Варшавы)\nsala im. Olgi Krzyżanowskiej (nr 412, bud. U)\n<a href=\"https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=C961ED6560C561A9C1258E910039645E\">Трансляция</a>\n\nВ повестке:\n<i>Rozpatrzenie poprawek zgłoszonych w czasie drugiego czytania do projektu ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druki nr 3157 i 3193).</i>\nℹ️ Заседание объявлено условно: состоится, только если Сейм направит проект в эту комиссию.\n\n#заседаниекомиссии #kadencja10druk1929 #kadencja10druk3141 #UD428 #kadencja10druk3157 #UD439","with_act":false}','{"importance":"routine","urgency":"normal","reasons":["agenda"],"explanation":"The case appears on a sitting agenda.","affected_groups":[],"action":"wait","deadline":"2026-10-21","deadline_source":"agenda","deadline_precision":"day","detected_at":"2026-10-15T17:50:38Z","assessed_at":"2026-10-15T17:50:38Z","novelty":"unknown","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(140,10,'3157','agenda','sent','@lex_inform_pl',108,'[]',NULL,'2026-10-15T17:50:38+00:00','2026-10-16T16:56:30+00:00',NULL,0,'ZDR/173/2026-10-21+15:30+sala im. Olgi Krzyżanowskiej (nr 412, bud. U)',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3157\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-28\",\"document_date\":\"2026-09-28\",\"change_date\":\"2026-10-12T13:41:03Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-160-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-160-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:migracja\",\"text:obywatelstwo\",\"text:przekraczanie_granicy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-28\",\"print_number\":\"3157\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage