nd\":\"text_after3\",\"extra_urls\":[]},\"analysis_sha256\":\"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2\",\"analysis_revision\":3,\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Закон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета. Иностранцы с перечисленными видами легального пребывания в Польше получают это право наравне с гражданами. Услуга бесплатна, назначается решением wojewódzki zespół ds. orzekania o niepełnosprawności.\",\"key_changes\":[\"Право на услугу: ПМЖ, резидент ЕС, беженцы и доп. защита, граждане ЕС/ЕЭЗ/Швейцарии и члены семей\",\"Включены разрешения по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust. 1, 186 ust. 1 pkt 3, научная виза, Brexit-соглашение\",\"Карта побыту с отметкой ''dostęp do rynku pracy'' даёт право, кроме студентов, сезонных и краткосрочных работников\",\"Объём: 20–240 часов в месяц (18–65 лет), 20–80 часов (13–18 лет); ставки 49–55 zł брутто в час\",\"Заявление подаётся электронно; иностранец прилагает документ, дающий право на пребывание в Польше\"],\"affected_groups\":[\"иностранцы с инвалидностью, имеющие ПМЖ или статус резидента ЕС\",\"беженцы и лица с дополнительной защитой\",\"граждане ЕС/ЕЭЗ/Швейцарии и члены их семей\",\"обладатели карты побыту с отметкой ''dostęp do rynku pracy''\",\"работники по внутрикорпоративному переводу и научные работники\",\"граждане Великобритании по Brexit-соглашению\"],\"practical_impact\":\"Иностранец с инвалидностью, проживающий в Польше и имеющий соответствующее решение об уровне потребности в поддержке, может бесплатно получить личного ассистента; заявление подаётся только электронно с приложением документа о праве на пребывание.\",\"effective_date\":\"Через 14 дней после опубликования, с исключениями: ст. 6 ust. 1 pkt 1 и часть ст. 8 — через 12 месяцев; ст. 6 ust. 1 pkt 2 и ст. 7 ust. 2–7 — через 14 месяцев; ст. 58–67 и ст. 99 — с первого дня месяца после 5 месяцев от опубликования.\",\"confidence\":0.85,\"rationale\":\"Закон касается социальной поддержки и прямо перечисляет категории иностранцев, получающих право на услугу, но не затрагивает легализацию пребывания или работу.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[\"В перечень оснований добавлены разрешения по ст. 159 ust. 1 и ст. 186 ust. 1 pkt 3 ustawy o cudzoziemcach\",\"Добавлены переходные ограничения максимума часов: 200 часов в 2028 г. и 220 часов в 2029 г.\",\"Уточнены сроки рассмотрения заявлений: до 120 дней (до 31.12.2028), 90 дней, затем 60 дней\",\"Детализирован поэтапный запуск: 90 баллов — через 12/16 месяцев от публикации, 85 — через 17/21, 80 — с 01.09.2028/01.01.2029\",\"Для лиц 13–18 лет и проживающих в учреждениях круглосуточного ухода — заявления с 01.05.2029, право с 01.01.2030\"]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":154338,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-22T16:01:14Z\",\"input_tokens\":77754,\"output_tokens\":1429,\"cache_read_input_tokens\":2652,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/316/attachment/316_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":3,\"text_sha256\":\"ca08cb45cab92073c6425650560e9f2d84d0f354b7e9ed5ec8ec1b0136e2d2f2\",\"law_sha256\":null,\"source_checked_at\":\"2026-09-22T16:01:14Z\"},\"editorial\":{\"mnemonic\":null,\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/36702/2025\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2025-11-04\",\"print_number\":\"1929\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2170.html\",\"title\":\"Ustawa o asystencji osobistej osób z niepełnosprawnościami\",\"print_number\":\"832\",\"received\":\"2026-09-22\",\"committees\":[{\"id\":233,\"name\":\"Komisja Rodziny, Polityki Senioralnej i Społecznej\",\"email\":\"krpss@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-08\",\"2026-10-13\"],\"committee_work_completed\":false},\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-14T16:11:24Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-14T16:11:18Z","assessed_at":"2026-10-14T16:11:24Z","novelty":"new_consequence","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Важно</b>\n📮 <b>Направлен в комиссию — druk nr 1929</b>\nЗакон вводит системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью, финансируемую из госбюджета.\n<i>Принят Сеймом 18 сент 2026</i>\n\n🧭 <b>Новые стадии</b>\n• 13 окт 2026: Сенат внёс поправки (druk nr 3213)\n• 14 окт 2026: 📮 Направлен в комиссию: Komisja Polityki Społecznej i Rodziny (PSR)\n\n🆕 <b>Что меняют поправки Сената</b>\nПоправки Сената не меняют круг иностранных получателей услуги, но вводят реестр пользователей асистенции (с данными PESEL или документа), смягчают правила переноса часов, позволяют правительству индексировать ставки и вводят переходный период по квалификациям ассистентов до конца 2029 года.\nЧасть изменений уточняет процедуры (помощь ZUS и повятов при подаче и исправлении заявлений, правила замены ассистента, финансирование ИТ‑систем) и перераспределяет технические нормы между разделами закона.\n• Создаётся реестр получателей асистенции; при отсутствии PESEL вносятся данные документа, удостоверяющего личность\n• Невыбранные часы можно использовать до конца календарного года, но не более двойного месячного лимита\n• Rada Ministrów может повышать часовые ставки асистенции с учётом роста зарплат и минимальных ставок\n• ZUS и повят помогают не только подать, но и исправить/дополнить заявления и жалобы по асистенции\n• До 31.12.2029 ассистентом может быть и человек без полного стажа/квалификаций при выборе пользователем или обучении\n• Уточнены правила замены ассистента при его отсутствии и возможность авансовой выплаты за декабрь до 31 декабря\n\n⏭ <b>Что дальше:</b> Сейм рассматривает поправки Сената · обычно на ближайшем заседании Сейма\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=PSR\">Komisja Polityki Społecznej i Rodziny (PSR)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=PSR\">форма письма</a>)\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=1929\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=1929\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3213/3213-uchwa%C5%82a.docx\">Текст поправок (DOCX)</a>\n\n#комиссия #сенат #поправки #важность3 #соцсфера #kadencja10druk1929","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"{\"id\":118,\"term\":10,\"number\":\"1929\",\"old_fingerprint\":\"a7850ab982d317aea4cc4d3e291b6a095b79ce72df7649668633e1006adbd6df\",\"new_fingerprint\":\"6d0c033862bef66f3141d297d7faa7040d4761d35b3b2ce9c23c871981a396ce\",\"new_stages\":[{\"stage_name\":\"Stanowisko Senatu\",\"stage_type\":\"SenatePosition\",\"date\":\"2026-10-13\",\"print_number\":\"3213\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":\"wniósł poprawki\",\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-14\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-14\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Polityki Społecznej i Rodziny\",\"children\":[]}],\"closure_detected\":false,\"decision_changed\":false,\"passed\":true,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":{\"amendments\":{\"summary\":\"Поправки Сената не меняют круг иностранных получателей услуги, но вводят реестр пользователей асистенции (с данными PESEL или документа), смягчают правила переноса часов, позволяют правительству индексировать ставки и вводят переходный период по квалификациям ассистентов до конца 2029 года.\\nЧасть изменений уточняет процедуры (помощь ZUS и повятов при подаче и исправлении заявлений, правила замены ассистента, финансирование ИТ‑систем) и перераспределяет технические нормы между разделами закона.\",\"changes\":[\"Создаётся реестр получателей асистенции; при отсутствии PESEL вносятся данные документа, удостоверяющего личность\",\"Невыбранные часы можно использовать до конца календарного года, но не более двойного месячного лимита\",\"Rada Ministrów может повышать часовые ставки асистенции с учётом роста зарплат и минимальных ставок\",\"ZUS и повят помогают не только подать, но и исправить/дополнить заявления и жалобы по асистенции\",\"До 31.12.2029 ассистентом может быть и человек без полного стажа/квалификаций при выборе пользователем или обучении\",\"Уточнены правила замены ассистента при его отсутствии и возможность авансовой выплаты за декабрь до 31 декабря\"],\"affects_foreigners\":true,\"confidence\":0.9},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v11\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3213/3213-uchwa%C5%82a.docx\",\"source_kind\":\"senate_amendments\",\"created_at\":\"2026-10-16T18:47:43Z\",\"input_tokens\":13123,\"output_tokens\":1595,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-14T16:11:18Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-14","still_meets":false,"reply_to":15,"edit_message_id":107,"revision_of":136,"amendment_key":"ed50d047b5d58a4142859baed582938f9841872a7737160a18221b1ebc7dd4f2","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-14T16:11:18Z","assessed_at":"2026-10-14T16:11:24Z","novelty":"new_consequence","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(143,10,'RCL/12411950','status_update','sent','@lex_inform_pl',109,'[]',119,'2026-10-17T09:11:36+00:00','2026-10-17T09:11:37+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12411950\",\"title\":\"Projekt ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw\",\"description\":\"TRANSPORT DROGOWY; transport\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-06-30\",\"document_date\":\"2026-10-05\",\"change_date\":\"2026-10-08T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12411950\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"9f71c67e83a21461fcb70bd9527416cdf9204d40399513d07432cf39f029ce5e\",\"observed_closure_date\":null,\"consultation_review\":null,\"act_application_review\":null,\"review_work\":[{\"memo_key\":\"document-review:e557357ef0ae5b5354f31d9aafc470860368e8353eacaa9848a8db8f61657fb8\",\"purpose\":\"consultation_review\",\"context\":{\"number\":\"RCL/12411950\",\"title\":\"Projekt ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw\",\"purpose\":\"consultation_review\",\"documents\":[{\"identity\":\"rcl/801497\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212212/dokument801497.pdf\",\"role\":\"response\",\"text\":\"1\\n\\nTabela uwag zgłoszonych w ramach konsultacji publicznych projektu ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw\\n(UD 402)\\n\\n(według kolejności jednostek redakcyjnych projektu ustawy)\\n\\nlp Jednostka\\nredakcyjna\\nprojektu\\nPodmiot\\nzgłaszający\\nuwagę\\nTreść uwagi Sposób rozpatrzenia\\nuwagi/uzasadnienie\\n1 2 3 4 5\\n Art. 1 pkt 1 i\\npkt 3 projektu\\nustawy\\nPolska\\nWytwórnia\\nPapierów\\nWartościowych\\nS.A.\\nWątpliwości budzi proponowane przez projektodawcę rozwiązanie, aby wszelkie usługi\\nzwiązane ze szkoleniem kandydatów na kierowców były świadczone „w systemie\\nteleinformatycznym zapewnionym przez ministra właściwego do spraw informatyzacji,\\nzintegrowanym z systemem,\\no którym mowa w art. 16a”. Zaproponowane w projekcie ustawy rozwiązania związane z\\npostępującą cyfryzacją są rozwinięciem istniejących już rozwiązań w zakresie obsługi procesu\\nwnioskowania, szkolenia i egzaminowfizycznaania kandydatów na kierowców i kierowców,\\nktóre są obecnie realizowane za pomocą profilu kandydata na kierowcę (PKK), o którym\\nmowa w art. 2 pkt 3 ustawy, oraz profilu kierowcy zawodowego (PKZ), o którym mowa w art.\\n2 pkt 4 ustawy. PKK oraz PKZ są obsługiwane przy użyciu systemu teleinformatycznego, o\\nktórym mowa w art. 16a ustawy, tj. systemu teleinformatycznego zapewnianego przez\\nwytwórcę praw jazdy, kart kwalifikacji kierowcy i pozwoleń na kierowanie tramwajem.\\nIstniejące rozwiązania, funkcjonujące i sprawdzone od wielu lat, są kompletne i zapewniają\\npełną kontrolę nad uzyskiwaniem określonych rodzajów uprawnień, a także zapewniają\\nintegralność i poufność danych, w tym danych w postaci elektronicznej.\\n\\nZ uwagi na powyższe wprowadzenie rozwiązania opartego na „cyfrowej karcie kursanta” jest\\njedynie modyfikacją (rozwinięciem) istniejącego systemu teleinformatycznego,\\nMając na uwadze istotny\\nzakres zmian\\nwprowadzonych do\\nprojektu ustawy w wyniku\\nprzeprowadzonych\\nkonsultacji, nowe brzmienie\\nprojektowanej regulacji\\nzostało skierowane do\\nponownych konsultacji\\npublicznych. Stanowiska i\\nuwagi zgłoszone w ich toku\\nzostaną przeanalizowane, a\\nodniesienie się do nich\\nnastąpi w odrębnej tabeli\\nuwag zgłoszonych w\\nramach konsultacji\\npublicznych. \\f\\n\\nStrona 2 z 219\\n\\no którym mowa w art. 16a ustawy. Brak jest zatem uzasadnienia, w szczególności\\nekonomicznego, dla konieczności budowania odrębnego „systemu teleinformatycznego\\nzapewnianego przez ministra właściwego do spraw informatyzacji” do budowania\\nalternatywnego w stosunku do istniejącego rozwiązania.\\n\\nWymaga wskazania, że aktualnie czynności związane ze składaniem wniosku o wydanie\\nuprawnień są świadczone\\nw ramach usług elektronicznych w Portalu e-usług, który jest utrzymywany przez PWPW S.A.\\nPortal ten został zbudowany z wykorzystaniem środków z Krajowego Planu Odbudowy\\ni Zwiększania Odporności w zakresie wniosku projektowego „Uzyskanie uprawnień na Prawo\\nJazdy lub Kartę Kwalifikacji Kierowcy, możliwość sprawdzenia statusu sprawy wydania\\nPJ/KKK w urzędzie lub statusu obsługi PKK/PKZ”. PWPW S.A. została zobowiązana do\\nutrzymania trwałości tego projektu przez okres 5 lat od dnia jego uruchomienia (tj. od maja\\n2026 r.). Nie ma zatem przeszkód technicznych, aby „cyfrowa karta kierowcy” była dostępna\\nw tym rozwiązaniu. Cyfrowa karta kierowcy może zostać także udostępniona dla ośrodków\\nszkolenia kierowców poprzez istniejące API dla podmiotów dostarczających rozwiązania\\ndedykowane dla tych ośrodków.\\n\\nWobec powyższego należy wskazać, że przyjęcie rozwiązania, że „cyfrowa karta kursanta”\\nbędzie obsługiwana przez istniejący system teleinformatyczny, o którym mowa w art. 16a\\nustawy, zapobiegnie nieefektywnemu wydatkowaniu środków publicznych, skoro Portal e-\\nusług, zbudowany z wykorzystaniem środków Krajowego Planu Odbudowy i Zwiększania\\nOdporności, musi być utrzymywany przez PWPW S.A. przez blisko 5 lat.\\n\\nWymaga podkreślenia, że PWPW S.A. dysponuje projektem technicznym i gotową\\ndokumentację do wdrożenia rozwiązania związanego z „cyfrową kartą kursanta” co do\\nwiększości planowanych funkcjonalności (projekt oraz dokumentacja nie obejmują jedynie\\nobsługi zapisów z kamer z ośrodków szkolenia kierowców). Wobec powyższego PWPW S.A. \\f\\n\\nStrona 3 z 219\\n\\nbyłaby gotowa do wdrożenia tych rozwiązań nawet w terminie 6 miesięcy od dnia wejścia\\nw życie ustawy (zamiast projektowanych obecnie 2 lat od dnia wejścia w życie ustawy).\\nNiezależnie od powyższej uwagi ogólnej należy wskazać, że:\\n1) wprowadzenie „indywidualnego numeru kursanta” jest\\nw praktyce zdublowaniem istniejących funkcjonalności\\nw ramach profilu kandydata na kierowcę (PKK), o którym mowa w art. 2 pkt 3 ustawy,\\noraz profilu kierowcy zawodowego (PKZ), o którym mowa w art. 2 pkt 4 ustawy; z tego\\npowodu z projektu należy skreślić przepis formułujący definicję tego pojęcia;\\nwprowadzenie „indywidualnego numeru instruktora” jest zbędne, ponieważ już aktualnie\\ninstruktorom są nadawane numeru ewidencyjne przez starostów (art. 33 ust. 2 pkt 2\\nustawy), a numery te są gromadzone\\nw systemie teleinformatycznym, o którym mowa w art. 16a ustawy; przepis formułujący tę\\ndefinicję także należy skreślić.\\n\\nPropozycja przepisów:\\n1) projektowanej definicji cyfrowej karty kursanta proponuje się nadać brzmienie:\\n„5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących\\nosobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym,\\ninstruktora, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym\\nmowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu szkolenia w\\nzakresie nauki jazdy i części praktycznej egzaminu wewnętrznego, utworzony, udostępniany,\\naktualizowany i archiwizowany\\nw systemie teleinformatycznym, o którym mowa\\nw art. 16a ust. 1.”;\\n\\n2) z projektu należy wykreślić projektowane brzmienie art. 2 pkt 6 i 7 ustawy, co będzie\\nskutkowało rezygnacją z formułowania definicji „indywidualnego numeru kursanta” oraz\\n„indywidualnego numeru instruktora”; \\f\\n\\nStrona 4 z 219\\n\\n3) projekt ustawy należy uzupełnić o nowelizację art. 16a ustawy poprzez dodanie po ust. 1\\nust. 1a w brzmieniu:\\n„1a. System teleinformatyczny, o którym mowa\\nw ust. 1, umożliwia także założenie i prowadzenie cyfrowej karty kursanta.”;\\n\\n4) projektowany art. 23d ust. 1 ustawy powinien otrzymać brzmienie:\\n„1. Po zakończeniu zajęć w zakresie nauki jazdy lub części praktycznej egzaminu\\nwewnętrznego osoba ubiegająca się o uprawnienia do kierowania pojazdem silnikowym\\nmoże wprowadzić w cyfrowej karcie kursanta uwagi, o których mowa w art. 23c ust. 1 pkt 1\\nlit. k lub pkt 2 lit. k oraz potwierdzić albo odmówić potwierdzenia przebiegu szkolenia lub\\nczęści praktycznej egzaminu wewnętrznego poprzez wprowadzenie indywidualnego numeru\\nkursanta. Dane i informację są wprowadzane\\nz wykorzystaniem systemu teleinformatycznego,\\no którym mowa w art. 16a, oraz narzędzi teleinformatycznych wykorzystywanych przez\\nośrodki szkolenia kierowców zintegrowane\\nz systemem, o którym mowa w art. 16a.”;\\n\\n5) projektowany art. 23d ust. 3 ustawy powinien otrzymać brzmienie:\\n„3. Instruktor może sprostować dane i informacje,\\no których mowa w art. 23c ust. 1 pkt 1 lit. c–f, i oraz\\nj lub pkt 2 lit. c–f oraz h–j, zarejestrowane\\nw cyfrowej karcie kursanta, po uzyskaniu zgody osoby ubiegającej się o uprawnienia do\\nkierowania pojazdem silnikowym, potwierdzonej przez wprowadzenie indywidualnego\\nnumeru kursanta. Dane i informację są wprowadzane\\nz wykorzystaniem systemu teleinformatycznego,\\no którym mowa w art. 16a, oraz narzędzi teleinformatycznych wykorzystywanych przez\\nośrodki szkolenia kierowców zintegrowane\\nz systemem, o którym mowa w art. 16a.”.\\n \\f\\n\\nStrona 5 z 219\\n\\n6) projektowane brzmienie art. 27 ust. 4b ustawy powinno otrzymać brzmienie:\\n„4b. Wydanie zaświadczenia o ukończeniu szkolenia, o którym mowa w ust. 4, następuje\\nprzez wprowadzenie danych o jego wydaniu do profilu kandydata na kierowcę.”;\\n\\n7) z projektu należy wykreślić zmianę projektowaną w art. 1 pkt 5 lit. d projektu.\\n\\n Art. 1 pkt 1\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 1 budzi wątpliwość kwestia konieczności centralnego zapewnienia systemu\\nteleinformatycznego. Dotychczasowe doświadczenia w tych obszarach generują obawę o\\nryzyko niezrozumienia intencji autorów Projektu. Obecne możliwości techniczne na pewno\\npozwalają na zapewnienie odpowiedniego standardu cyfrowego dokumentowania procesu\\nszkolenia bez ryzyka nadmiernych regulacji – w szczególności na poziomie ustawowym.\\n\\n Art. 1 pkt 1\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\n18) Biorąc pod uwagę, że w proponowanych przepisach zakładamy, że indywidualny numer\\ninstruktora będzie generowany w aplikacji mObywatel oznacza to, że powstanie jedna baza\\ndanych zbierająca wszystkich instruktorów nauki jazdy z której będzie korzystał mObywatel.\\nZatem rozwiązany zostanie problem uniemożliwiający dotychczas przeniesienie legitymacji\\ninstruktorów nauki jazdy do aplikacji mObywatel. W naszej ocenie należy rozważyć\\nwprowadzenie zmian likwidujących papierową legitymacje instruktora nauki jazdy i\\npozostawienie jej wyłącznie jako dokumentu elektronicznego w aplikacji mObywatel. Takie\\ndziałanie rozwiąże szereg problemów z tym dokumentem (np. jego wielkość) i pozwoli\\njednocześnie na bieżące sprawdzanie czy dany instruktor posiada aktualne uprawnienia.\\nPrzy odpowiednim wykorzystaniu automatyki w cyfrowej karcie kursanta będzie można\\ncałkowicie zapobiec prowadzeniu szkoleń przez osoby nieposiadające uprawnień.\\n\\n Art. 1 pkt 1 i\\npkt 3 projektu\\nustawy\\nOgólnopolska\\nIzba\\nGospodarcza\\nOśrodków\\nSzkolenia\\nKierowców\\n(OIGOSK),\\nWnosimy o odstąpienie na tym etapie od obowiązkowego wprowadzania „cyfrowej karty\\nkursanta”, a w konsekwencji „indywidualnego numeru kursanta” oraz „indywidualnego\\nnumeru instruktora”. Uzasadnienie W ocenie skutków regulacji można znaleźć stwierdzenie,\\nże analiza funkcjonowania obecnego systemu wskazuje deficyt w postaci braku skutecznych\\nmechanizmów weryfikacji rzeczywistego przebiegu szkolenia praktycznego osób\\nubiegających się o uprawnienia do kierowania pojazdami. Nie wykazano jednak w jakim\\nprocencie szkoleń występują nieprawidłowości, założono domniemanie nieuczciwości\\nprzedsiębiorców. Projekt obejmuje wszystkich przedsiębiorców systemem stałego nadzoru, \\f\\n\\nStrona 6 z 219\\n\\nPolska\\nFederacja\\nStowarzyszeń\\nSzkół\\nKierowców\\n(LFEDERACJA),\\nPolska Izba\\nGospodarcza\\nOśrodków\\nSzkolenia\\nKierowców\\n(PIGOSK)\\n\\nmimo że zdecydowana większość prowadzi działalność zgodnie z prawem. Kontrola powinna\\nkoncentrować się na podmiotach naruszających przepisy, a nie obejmować wszystkich.\\nProjekt przewiduje rejestrowanie trasy każdej jazdy, czasu jej trwania i innych danych\\npozwalających odtworzyć historię przemieszczania się kursantów i instruktorów. Tak daleko\\nidąca ingerencja w prywatność nie została należycie uzasadniona. Projekt budzi poważne\\nwątpliwości w świetle art. 31 ust. 3, art. 47 oraz art. 51 ust. 2 Konstytucji RP. Nie wykazano,\\nże obowiązkowe gromadzenie danych o lokalizacji wszystkich kursantów i instruktorów jest\\nśrodkiem koniecznym oraz najmniej ingerującym w prawa obywateli. Możliwość odbycia\\nszkolenia zostaje uzależniona od posiadania smartfona, aplikacji mobilnej i dostępu do\\nInternetu, choć prawo nie nakłada na obywateli obowiązku posiadania takich urządzeń.\\nProjekt nie uwzględnia awarii telefonu, braku zasięgu GPS (zjawisko powszechne przy\\nlotniskach, obiektach wojskowych czy przy granicy z Rosją i Białorusią w obecnej napiętej\\nsytuacji w związku z wojną w Ukrainie), utraty Internetu ani sytuacji osób zagrożonych\\nwykluczeniem cyfrowym. Projekt przewiduje gromadzenie dużej ilości danych lokalizacyjnych\\nbez przedstawienia przekonującej analizy ryzyka ich wycieku lub nieuprawnionego\\nwykorzystania. Cyfryzacja procesu szkolenia kierowców jest kierunkiem pożądanym, jednak\\nnie może prowadzić do powszechnego monitorowania obywateli, uzależnienia szkolenia od\\nposiadania prywatnego urządzenia elektronicznego ani przerzucania ryzyka awarii systemów\\nna przedsiębiorców i kursantów. Projekt wymaga istotnych zmian, aby zachować zgodność z\\nzasadą proporcjonalności, ochroną prywatności oraz równego dostępu do szkolenia. W pełni\\npopieramy i utożsamiamy się z publikowanym postulatem prowadzenia „pilotażu” przed\\nwdrożeniem Cyfrowej karty kursanta do systemu prawnego RP, link\\nhttps://www.prawodrogowe.pl/informacje/news-tygodnia/jakub-grabowski-czy-cyfrowa-\\nkarta- kursanta-powinna-przejsc-pilot Najpierw sprawdźmy, potem wdrażajmy. Cyfrowa\\nkarta kursanta powinna przejść pilotaż w prawdziwym OSK. Propozycja ta zdecydowanie\\nzasługuje na rozwinięcie. Zanim cyfrowa karta kursanta, rejestrowanie tras jazd, dwustronne\\npotwierdzanie zajęć staną się obowiązkiem wszystkich ośrodków szkolenia kierowców,\\nnależy sprawdzić te rozwiązania w praktyce. Nie na papierze. Nie wyłącznie podczas\\nkonsultacji przy ministerialnym stole. W prawdziwej szkole jazdy, z prawdziwymi\\ninstruktorami, kursantami, samochodami, problemami z zasięgiem, rozładowanym\\ntelefonem i napiętym grafikiem jazd. Taki pilotaż pokaże, czy projektowany system\\nrzeczywiście zwiększy rzetelność szkolenia, czy też stworzy problemy, których dzisiaj jeszcze\\nnie jesteśmy w stanie przewidzieć. \\f\\n\\nStrona 7 z 219\\n\\n Art. 1 pkt 1 i\\npkt 3 projektu\\nustawy\\nZrzeszenie\\nMiędzynarodo-\\nwych\\nPrzewoźników\\nDrogowych\\nObawy budzą również projektowane rozwiązania dotyczące cyfrowej karty kursanta oraz\\nobowiązku rejestrowania obrazu i dźwięku z praktycznej części egzaminu wewnętrznego. Ich\\nwdrożenie będzie wymagało od ośrodków szkolenia kierowców zapewnienia odpowiedniego\\nzaplecza technicznego, obejmującego w szczególności urządzenia lokalizacyjne, urządzenia\\nsłużące do rejestracji obrazu i dźwięku, a także narzędzia umożliwiające instruktorowi i\\nkursantowi sprawne wprowadzanie oraz potwierdzanie danych w cyfrowej karcie kursanta.\\nWprowadzenie tych rozwiązań będzie wiązało się nie tylko z kosztami zakupu lub\\ndostosowania urządzeń, lecz także z wydatkami na ich utrzymanie, obsługę i serwisowanie.\\nW praktyce koszty te zostaną uwzględnione przez ośrodki szkolenia kierowców w cenach\\nkursów, a więc ostatecznie poniosą je osoby ubiegające się o uzyskanie uprawnień. Tym\\nsamym projektowane obowiązki doprowadzą do dalszego wzrostu kosztów szkolenia.\\nWzrost kosztów szkolenia może być szczególnie dotkliwy dla osób ubiegających się o\\nuzyskanie kategorii wymaganych do wykonywania zawodu kierowcy. Już obecnie średnia\\ncena kursu na prawo jazdy kategorii B w mieście wojewódzkim wynosi 4150 zł (w Warszawie\\n4740 zł). W przypadku kategorii zawodowych, po uwzględnieniu kosztów kursów na\\nodpowiednie kategorie\\nprawa jazdy, wymaganych szkoleń oraz uzyskania kwalifikacji zawodowej, łączny wydatek\\nmoże przekraczać 12 000 zł. Koszty te stanowią istotną barierę wejścia do zawodu, a ich\\ndalszy wzrost może ograniczać liczbę nowych kandydatów i pogłębiać trudności kadrowe\\nprzedsiębiorstw transportowych, zwłaszcza w warunkach utrzymującego się deficytu\\nkierowców zawodowych.\\n\\nArt. 1 pkt 1\\nprojektu\\nustawy w\\nzakresie art. 2\\npkt 5-7\\nustawy o\\nkierujących\\npojazdami\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n1. Ad art. 1 pkt 1 projektu wprowadzający zmiany w art. 2 pkt 5-7 UoKP\\nZaproponowane definicje „cyfrowej karty kursanta” „indywidualnego numeru kursanta” i\\n„indywidualnego numeru instruktora” budzą poważne wątpliwości zarówno z\\nmerytorycznego, jak i z formalnego punktu widzenia.\\nW naszej ocenie tego typu propozycje stanowią klasyczny przykład nadmiernej regulacji,\\ntworzącej tzw. nadmiarowe byty. Jeśli intencją projektodawcy jest zapisywanie danych i\\ninformacji o przebiegu szkolenia, to w ocenie TLP, wystarczający byłby ustanowiony w\\nodrębnej jednostce redakcyjnej, w rozdziale odnoszącym się do szkolenia, przepis\\nokreślający:\\n• obowiązkowe przetwarzanie odpowiednich danych dotyczących szkolenia, takich,\\njak np.: dane identyfikacyjne szkolonej osoby, dane identyfikacyjne oso b prowadzących \\f\\n\\nStrona 8 z 219\\n\\nszkolenie, dane identyfikujące ośrodek szkolenia kierowco w lub inną jednostkę prowadzącą\\nszkolenie, dane identyfikujące pojazd, którym prowadzone jest szkolenie, dane i informacje\\ndotyczące rozpoczęcia i zakończenia poszczególnych jednostek dydaktycznych, dane\\ngeolokalizacyjne pozwalające ustalić trasę pojazdu, którym prowadzone jest szkolenie, etc.,\\n• system teleinformatycznego, w którym przetwarzane będą wymagane dane,\\n• obowiązek wprowadzania wymaganych danych objętych przetwarzaniem w\\nsystemie przez instruktora i osobę szkoloną,\\n• obowiązek posiadania lub wyposażenia pojazdu w odpowiednie urządzenie\\ngeolokalizacyjne, z którego pobierane będą dane pozwalające ustalić trasę pojazdu,\\n• zasady postępowania w przypadku awarii systemu teleinformatycznego lub\\nurządzenia/systemu geolokalizacyjnego.\\n\\nSzczegółowe zasady wprowadzania danych i ich przetwarzania powinny być określone w\\nakcie wykonawczym, zważywszy na fakt, iż związane jest to z konkretnymi rozwiązaniami\\ntechnicznymi, kto re mogą ewaluować m.in. w związku z postępem technicznym. Trudno\\nbowiem w przypadku wprowadzenia zmian na dużym poziomie szczegółowości, za każdym\\nrazem zmieniać akt rangi ustawowej\\nOdnosząc się do danych identyfikacyjnych osób fizycznych (osób szkolonych i szkolących) w\\npolskim systemie prawnym nie ma potrzeby tworzenia nowych „bytów”, gdyż każdą osobę\\nidentyfikują takie dane jak imię, nazwisko, data urodzenia, numer PESEL lub numer\\ndokumentu tożsamości. Wydaje się, że z funkcjonalnego punktu widzenia, przepisy rangi\\nwykonawczej powinny wskazywać, iż do potwierdzania wprowadzanych danych używany\\njest odpowiedni indywidualnie przypisany klucz lub odpowiedni token (cyfrowy\\nidentyfikator), wygenerowany przez system na odpowiedni wniosek (kursanta? instruktora?\\nośrodka szkolenia kierowco w?). Nie ma potrzeby wprowadzania jego definicji na poziomie\\nustawy.\\nTworząc określone obowiązki nie można zapominać , iż system powinien zapewniać także\\nobsługę osób wykluczonych cyfrowo! W szczególności należy pamiętać, iż obywatel UE nie\\nma obowiązku posiadania i korzystania z takich urządzeń , jak smartfon, tablet, komputer,\\netc. Pomimo znacznej szczegółowości proponowanych w dalszych przepisach rozwiązań ,\\nkwestie te są niestety nierozpoznawalne.  \\f\\n\\nStrona 9 z 219\\n\\nUstanawiając przetwarzanie danych (które nie są danymi produkcyjnymi na użytek\\nproducenta dokumentów komunikacyjnych), należałoby przy tym określić :\\n• Podmioty odpowiedzialne, w tym organ prowadzący system, organ odpowiedzialny\\nmerytorycznie za proces, administratora danych osobowych, podmiot zapewniający obsługę\\ntechniczną, organ sprawujący nadzór, etc. Obecny system prowadzony przez PWPW S.A. -\\nw naszej ocenie - nie spełnia tych wymogów!\\n• Dostęp do systemu i udostępnianie danych, w tym kategorie użytkowników i zakres\\nich uprawnień, dostęp osoby do własnych danych, zasady dostępu publicznego, tryb\\nudostępniania danych jednostkowych i masowych, możliwość przekazywania danych przez\\nAPI, odpłatność albo nieodpłatność, zakaz dalszego wykorzystania niezgodnego z celem,\\nobowiązek rejestrowania zapytań , zmian i pobrań etc. Obecny system prowadzony przez\\nPWPW S.A. - w naszej ocenie - nie spełnia tych wymogów!\\n• Jakość danych i prawa osób, (podmiotów) których dane są przetwarzane, a w\\nszczególności: zasady aktualizacji danych, procedurę sprostowania danych nieprawidłowych,\\nuzupełnienie danych niekompletnych, oznaczenie danych spornych, możliwość wstrzymania\\nich wykorzystywania do czasu wyjaśnienia, powiadomienie odbiorców o korekcie, dostęp do\\nhistorii zmian, tryb złożenia skargi lub wniosku, organ właściwy do rozpoznania sporu.\\nObecny system prowadzony przez PWPW S.A. - w naszej ocenie - nie spełnia tych\\nwymogów!\\nWskazane wyżej kwestie, wykraczają zbyt daleko od zakresu podmiotowo-przedmiotowego\\nUoKP. Niemniej ich pominięcie byłoby – w naszej ocenie – niezgodne z obowiązującym w\\ntym zakresie systemem prawnym RP i UE. Dlatego też bardziej właściwym wydaje się\\nprzygotowanie odrębnego projektu ustawy, który tworzyłby lub sankcjonował odpowiedni\\nsystem teleinformatyczny, służący m.in. do zamawiania dokumentów.\\nPonadto, poważne wątpliwości TLP budzą takie fakty, jak:\\n• Doświadczenia związane z wdrażaniem wcześniejszych rozwiązań\\nteleinformatycznych w procesie uzyskiwania uprawnień do kierowania pojazdami i\\nkwalifikacji zawodowych kierowców („Profil Kandydata na Kierowcę” oraz „Profil Kierowcy\\nzawodowego”) wskazują, że uruchamianiu nowych systemów towarzyszyły problemy\\norganizacyjne i techniczne, które okresowo zakłócały szkolenie i egzaminowanie. Projekt nie\\nprzedstawia pełnej analizy łącznych kosztów wcześniejszych wdrożeń ani niezależnego\\naudytu ich efektów. Wydaje się, że wdrożenie ww. rozwiązań w żaden sposób nie przełożyło\\nsię na poprawę efektywności systemu uzyskiwania uprawnień do kierowania pojazdami, a \\f\\n\\nStrona 10 z 219\\n\\ntym samym poprawę bezpieczeństwa na polskich drogach. Uzasadnia to ostrożność przy\\nprojektowaniu kolejnego narzędzia - „cyfrowej karty kursanta” - oraz potrzebę wykazania\\njego proporcjonalności, efektywności i odporności na awarie. Należy także przejrzyście\\nopisać rolę dostawcy systemu teleinformatycznego w pracach nad rozwiązaniami prawnymi i\\ntechnicznymi.\\n• Brak wystarczającej analizy porównawczej. TLP nie zidentyfikowało w dostępnych\\nmateriałach rozwiązania europejskiego, kto re łączyłoby dokładny s lad GPS z obustronnym\\npotwierdzaniem każdej jazdy w zakresie odpowiadającym projektowanej „cyfrowej karcie\\nkursanta”. Co prawda we Francji funkcjonuje centralny cyfrowy dziennik szkolenia, a w\\nPortugalii obowiązkowo rejestruje się m.in. czas jazdy, pojazd, instruktora i przejechane\\nkilometry. Niemniej w żadnych z tych państw nie ma rozwiązań, które łączyłoby to z\\ndokładnym śladem GPS i obustronnym potwierdzaniem każdej jazdy. Zaproponowany profil\\nstanowi więc dużo bardziej rozbudowaną, mocno skomplikowaną i ingerującą w prywatność\\nkombinację rozwiązań francuskich i portugalskich. Nie trzeba przy tym dodawać, że koszty\\ninwestycyjne oraz koszty eksploatacyjne nowej funkcjonalności systemu będą\\nnieproporcjonalnie wyższe. Oznacza to, że proponuje się nam bardzo daleko idący i na\\ndodatek kosztowny eksperyment, którego deklarowane cele nie zostały potwierdzone przez\\nprzykłady dobrej praktyki, ani tez przez jakiekolwiek prace badawcze.\\n• Koszty społeczne „cyfrowej karty kursanta”. Przy założeniu, iż corocznie szkolonych\\njest 400 tysięcy osób, a każda z nich odbywa średnio 60 jednostek wymagających\\npotwierdzenia przez osobę szkoloną i instruktora, liczba dodatkowych czynności\\n(wprowadzania i potwierdzania zajęć) mogłaby sięgnąć nawet 48 milionów rocznie. TLP\\nszacuje wynikający z tego wzrost kosztów szkolenia na co najmniej 100 mln zł rocznie.\\nBudzi to bardzo poważne wątpliwości co do zasadności przedłożonych propozycji z punktu\\nwidzenia rachunku cost/benefits. Szczególnie, że zaproponowane rozwiązania wydają się\\nbyć bardzo podatne na fałszerstwa. Wystarczy bowiem, że cyfrowy identyfikator osoby\\nszkolonej zostanie wykorzystywany przez instruktora w porozumieniu z tą osobą.\\n• Znaczne zwiększenie regulacyjnego ryzyka po stronie instruktorów oraz\\nprzedsiębiorców prowadzących OSK. Przy 48 milionowej skali wprowadzania danych do\\nodpowiednich rekordów systemu, należy założyć skalę popełnianych błędów ludzkich, na\\nktórą dodatkowo mogą się nałożyć błędy zewnętrzne (np. wynikające z odnotowywanych na\\nterytorium Polski, czasowych zakłóceń systemów prowadzących wrogie działania o\\ncharakterze hybrydowym). Zazwyczaj przy projektowaniu systemów teleinformatycznych \\f\\n\\nStrona 11 z 219\\n\\nzakłada się występowanie do około 3% błędnie wprowadzanych danych. I nawet jeśli\\nprzyszłe rozwiązania techniczne ograniczą ich występowanie do 1%, to nadal ich liczba (480\\ntysięcy rocznie), skutkować będzie wszczynanymi postępowaniami administracyjnymi, które\\nmogą zakończyć się odebraniem uprawnień do prowadzenia szkolenia (w założeniu\\nzawartym w proponowanych przepisach nie ma możliwości skorygowania błędnie\\nwprowadzonych danych!), Ponadto, niezależnie od ryzyka po stronie prywatnych\\npodmiotów, należy zadać sobie pytanie, czy prowadzący nadzór nad szkoleniem starostowie\\nbędą przygotowani organizacyjnie i kadrowo do analizy takiej liczby danych i do\\npodejmowania odpowiednich postępowań administracyjnych. W naszej ocenie\\nzdecydowanie nie, co oznacza jednocześnie, że efektywność proponowanego rozwiązania\\nbędzie wynosiła zaledwie kilka procent.\\n• Brak ustalonych zasad odpłatności za obowiązkowe użytkowanie (korzystanie z)\\nsystemu. Podobnie jak w przypadku dotychczasowych, obligatoryjnych rozwiązań\\nteleinformatycznych („profil kandydata na kierowcę” i „profil kierowcy zawodowego”), nie\\nustalono zasad ponoszenia opłat za korzystanie z systemu dla OSK, starostw i innych\\npodmiotów, zobowiązanych do czynności związanych z przetwarzaniem danych w systemie.\\nPowoduje to kuriozalną i dwuznaczną pod względem prawnym sytuację, w której wyznacza\\nsię podmiot prowadzący system (dotychczas była to państwowa spółka prawa handlowego),\\na następnie pośrednio (poprzez przymus korzystania z systemu), zmusza się inne podmioty i\\norgany do zawierania odpłatnych umów z tym wyznaczonym podmiotem – na zasadzie:\\nMUSISZ KORZYSTAĆ, MUSISZ PŁACIĆ TYLE ILE CHCEMY!\\n\\nMając na uwadze podniesione wyżej (aczkolwiek nie wyczerpujące pełnego ich katalogu)\\nwątpliwości, zamiast procedowania nad zaproponowanymi w projekcie rozwiązaniami,\\nbardziej zasadne byłoby ustanowienie podstawy prawnej dla przeprowadzenia przez\\nministra właściwego ds. transportu pilotażu nowych rozwiązań teleinformatycznych.\\nDopiero po przeprowadzeniu takich działań, ich ewaluacji, można by było podjąć decyzje o\\nzasadności, zakresie i sposobie wdrożenia odpowiednika cyfrowego dziennika szkolenia,\\njakim de facto ma być „cyfrowa karta kursanta”.\\n\\nArt. 1 pkt 1 i\\npkt 3 projektu\\nustawy\\n\\nFundacja\\nzapobiegania\\n\\nPoważne wątpliwości budzi projekt wprowadzenia cyfrowej karty kursanta, czyli w praktyce -\\nelektronicznego nadzoru nad szkoleniem, a tym samym nad pracą instruktora. Rozumiejąc\\nintencje autorów projektu, pozostajemy w przekonaniu, że nadzór i likwidacja \\f\\n\\nStrona 12 z 219\\n\\nWypadkom\\nDrogowym\\newentualnych, choć rzeczywiście występujących, nadużyć w zakresie realizacji zadań z\\nzakresu szkolenia nie powinno odbywać się kosztem rzetelnej i uczciwie postępującej\\nwiększości instruktorów. Także postulat przeprowadzenia w tym względzie pilotażu wydaje\\nsię ze wszech miar słuszny. Wiele argumentów przemawia za tym, że wypełnianie\\nposzczególnych rubryk w aplikacji nie jest najtrafniejszą formą kontroli nad jakością\\nszkolenia. Za to jest formą postępującej biurokratyzacji i formalizacji oraz braku zaufania do\\nprzedsiębiorcy i jego pracowników. Propozycja ta porównywana jest do dość powszechnie\\nkrytykowanego sposobu egzaminowania narzucającego wypełnianie ściśle określonego\\nzestawu rubryk. Nasza opinia nie stoi w sprzeczności z pilną potrzebą wypracowania nowych\\nform nadzoru i kontroli nad OSK. Obecny jest bowiem uważany za zbyt formalny i w\\nniewielkim stopniu merytoryczny.\\n\\n Art. 1 pkt 1\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\n1) W założeniu projektu ustawy przyjęto, że w cyfrowej karcie kursanta rejestrowany będzie\\nwyłącznie przebieg części praktycznej szkolenia dla kandydata na kierowcę oraz część\\npraktyczna egzaminu wewnętrznego. W całym procesie nie uwzględniono konieczności\\nelektronicznej rejestracji części teoretycznej szkolenia, zajęć z pierwszej pomocy i części\\nteoretycznej egzaminu wewnętrznego. Rejestracji tej części zajęć nie wolno pomijać. Nie\\nmożna też założyć, że przeprowadzenie tych zajęć będzie potwierdzone jednorazowo za całe\\n30 godzin. Dotychczas zajęcia teoretyczne, tak jak zajęcia praktyczne były potwierdzane w\\nkarcie przeprowadzonych zajęć na takich samych zasadach jak zajęcia praktyczne czyli przez\\nkursanta i wykładowcę czy instruktora po każdych zajęciach. W ocenie Polskiego Związku\\nSzkoleniowego taka zasada powinna zostać zachowana. Proponujemy aby w cyfrowej karcie\\nkursanta rejestrować na takich samych zasadach jak dotychczas także informacje o szkoleniu\\nteoretycznym oraz o szkoleniu z pierwszej pomocy. Takie rozwiązanie ujednolici sposób\\nprowadzenia dokumentacji i jednoznacznie ułatwi jej kontrolę.\\nWarto zauważyć, że czy tak czy inaczej przeprowadzenie zajęć teoretycznych musi być w\\njakiś sposób rejestrowane i potwierdzane. Jeżeli nie wprowadzimy tego rozwiązania do\\ncyfrowej karty kursanta to potwierdzanie zajęć teoretycznych będzie się musiało odbywać\\ntak jak dotychczas w oparciu o papierowe dokumenty. Zatem w tym wypadku\\nwprowadzenie cyfrowej karty kursanta zamiast usprawnić prowadzenie dokumentacji\\nzwiązanej ze szkoleniem, stanie się dodatkowym elementem do papierowych dokumentów.\\nProponujemy przeredagowanie definicji zawartych w art. 1 pkt 1 w następujący sposób:\\n \\f\\n\\nStrona 13 z 219\\n\\na) zmianę definicji cyfrowej karty kursanta:\\n\\n„5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących\\nosobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym,\\ninstruktora, wykładowcę, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o\\nktórym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu szkolenia i\\negzaminu wewnętrznego, utworzony, udostępniany, aktualizowany i archiwizowany w\\nsystemie teleinformatycznym zapewnionym przez ministra właściwego do spraw\\ninformatyzacji, zintegrowanym z systemem, o którym mowa w art. 16a;”\\n\\nb) zmianę definicji indywidualnego numeru kursanta:\\n\\n„6) indywidualnym numerze kursanta – należy przez to rozumieć unikalny numer\\nidentyfikujący osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem\\nsilnikowym, umożliwiający tej osobie potwierdzanie w cyfrowej karcie kursanta danych i\\ninformacji dotyczących przebiegu szkolenia oraz egzaminu wewnętrznego;”\\n\\nc) zmianę definicji indywidualnego numeru  instruktora/wykładowcy:\\n\\n7) indywidualnym numerze instruktora lub wykładowcy – należy przez to rozumieć unikalny\\nnumer identyfikujący instruktora lub wykładowcę, umożliwiający wprowadzenie i\\npotwierdzenie w cyfrowej karcie kursanta danych i informacji dotyczących przebiegu\\nszkolenia i egzaminu wewnętrznego, generowany w aplikacji mObywatel.”;\\n\\nWprowadzenie obowiązku rejestracji w cyfrowej karcie kursanta zajęć teoretycznych i\\nszkolenia z pierwszej pomocy będzie wymagało przeredagowania pozostałych przepisów z\\ntym związanych w pozostałej części projektu ustawy.\\n Art. 1  pkt 1\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\n13. Z treści projektu ustawy nie wiadomo jak od strony technicznej będzie wdrożona\\ncyfrowa karta kursanta. Przepisy dotyczące rejestracji egzaminów mają zostać napisane na\\npostawie zmienianej ustawy (Art. 23h 3.). Dostosowanie się do nowych przepisów będzie dla\\nośrodków szkolenia oznaczało konieczność poniesienia dodatkowych koszów. Dzisiaj nie\\nmamy danych do oszacowania jakich. Liga Obrony Kraju (LOK) \\f\\n\\nStrona 14 z 219\\n\\nposiada wiele ośrodków i pojazdów szkoleniowych. Z tego powodu uważamy, że przyjęte\\nrozwiązania powinny być oparte na powszechnie dostępnych urządzeniach (smartfony z\\nodpowiednią aplikacją) co pozwoli uniknąć instalowania dedykowanych urządzeń\\nlokalizacyjnych. Pozwoli wdrożyć proponowane zmiany bez dużych nakładów finansowych.\\nIm wcześniej będziemy znać szczegóły tym łatwiej będzie nam zgromadzić odpowiednie\\nśrodki. Będziemy też mieli więcej czasu na dostosowanie się pod względem organizacyjnym i\\ntechnicznym. Przechowywanie w dużej ilości danych\\nosobowych w sposób zgodny z RODO będzie również dużym wyzwaniem dla wszystkich\\nośrodków szkoleniowych. Reasumując wnioskujemy aby ww. regulacja była możliwie\\nszybko opublikowana, a nie na kilka dni przed wejściem w życie przepisów nakazujących\\nrejestrację egzaminu.\\n Art. 1 pkt 1\\nprojektu\\nustawy\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\n\\nKonsekwentnie należy wprowadzić rejestrację wszystkich zajęć podlegających rejestracji w\\njednym miejscu, w tym przypadku w odpowiednio przygotowanej cyfrowej karcie kursanta.\\n\\nProponowana zmiana:\\n„5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących\\nosobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym,\\ninstruktora, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym\\nmowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu szkolenia w\\nzakresie części teoretycznej, nauki udzielania pierwszej pomocy, nauki jazdy i części\\npraktycznej egzaminu wewnętrznego, utworzony, udostępniany, aktualizowany i\\narchiwizowany w systemie teleinformatycznym zapewnionym przez ministra właściwego do\\nspraw informatyzacji, zintegrowanym z systemem, o którym mowa w art. 16a;\\n\\nSystem cyfrowej karty kursanta należy oprzeć o funkcjonowanie odpowiedniej aplikacji,\\nktóra będzie również przesyłała dane o geolokalizacji. Osoba używająca aplikacji (instruktor)\\nbędzie  mógł zadecydować o jej wyłączeniu, po zakończeniu pracy. Aplikacja co do lokalizacji\\ni trasy powinna działać na podobnych zasadach jak np. aplikacja do obsługi systemu opłat\\ndrogowych e-toll.\\n\\nProwadzenie harmonogramu kursu nie jest potrzebne i stanowi tylko i wyłącznie\\nniepotrzebny dokument, w oparciu o który kontrolujacy nic nie są w stanie zweryfikować.\\nZajęcia teoretyczne do tej pory odnotowywane są w Karcie Przeprowadzonych Zajęć lub \\f\\n\\nStrona 15 z 219\\n\\ndokumentacji cyfrowej - w przypadku prowadzenia kursu w formule e-learning. W nowym\\nwariancie, przy wprowadzeniu cyfrowej karty kursanta, transparentność zajęć będzie pełna i\\nprowadzenie dodatkowej dokumentacji stanowi tylko i wyłącznie pusty wymów obciążający\\nKierownika OSK.\\n\\n Art. 1 pkt 1 i\\npkt 3 projektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 1)\\nUproszczenie obsługi cyfrowej karty kursanta\\ni jedno zbiorcze podsumowanie dla instruktora i kursanta\\n1. Treść uwagi\\nProponuje się przyjęcie prostego, spójnego i neutralnego technologicznie modelu obsługi\\ncyfrowej karty kursanta. Po zakończeniu jazdy zarówno instruktor, jak i kursant powinni\\notrzymać jedno kompletne podsumowanie, odpowiednio do swoich ról. Instruktor uzupełnia\\ni zatwierdza zbiorczo dane zajęć, natomiast kursant w tym samym procesie zapoznaje się z\\ngotowym wpisem, może dodać komentarz, zgłosić niezgodność, potwierdzić dane albo\\nzaakceptować korektę.\\nPrzed rozpoczęciem jazdy nie powinno być obowiązku podawania ani potwierdzania pełnego\\nzestawu danych, takich jak ośrodek szkolenia kierowców, kursant, instruktor, pojazd czy\\nplanowany czas zajęć. Na tym etapie wystarczające powinno być techniczne uruchomienie\\nrejestracji przez instruktora albo system teleinformatyczny. Jeżeli jazda została wcześniej\\nzaplanowana w aplikacji, system może rozpocząć rejestrację automatycznie zgodnie z\\nharmonogramem, jednak wcześniejsze posiadanie wszystkich danych nie powinno być\\nwarunkiem rozpoczęcia zapisu. System może najpierw rejestrować przebieg sesji, w\\nszczególności czas i trasę, a dopiero po zakończeniu jazdy otrzymać i powiązać z nią\\npozostałe wymagane informacje. Instruktor powinien wtedy otrzymać jedno zbiorcze\\npodsumowanie, w którym jednorazowo wskazuje lub weryfikuje ośrodek, kursanta,\\ninstruktora, pojazd, czas zajęć, kilometry, uwagi oraz inne wymagane dane. Takie\\nrozwiązanie usuwa zbędne czynności wykonywane przed ruszeniem pojazdu, a jednocześnie\\npozwala zgromadzić po jeździe kompletną i uporządkowaną dokumentację.\\nAplikacja mObywatel ani aplikacja mobilna konkretnego ośrodka szkolenia kierowców nie\\npowinny być obowiązkowym warunkiem udziału w szkoleniu lub wykonywania praw\\nkursanta. Zgodnie z regulaminem aplikacji mObywatel korzystanie z niej jest dobrowolne, \\f\\n\\nStrona 16 z 219\\n\\ndlatego projekt nie powinien przekształcać jej instalacji w faktyczny obowiązek. MObywatel\\nmoże pozostać fakultatywnym sposobem uwierzytelnienia lub wygodnym przekierowaniem\\ndo cyfrowej karty kursanta. Podobnie aplikacja OSK może być oferowana jako udogodnienie,\\nale kursant powinien mieć równoważną możliwość zapoznania się z danymi, zgłoszenia uwag\\ni potwierdzenia wpisu przez interfejs internetowy, urządzenie udostępnione przez ośrodek\\nalbo inny dostępny kanał. Przepisy powinny pozostawić kursantowi możliwość wyboru\\nośrodka i sposobu obsługi, bez narzucania instalowania określonego oprogramowania na\\nprywatnym telefonie.\\n2. Wartość i korzyści proponowanego rozwiązania\\n• Więcej czasu na szkolenie praktyczne. Ograniczenie czynności wykonywanych przed\\nrozpoczęciem i po zakończeniu każdej jazdy pozwala instruktorowi skoncentrować się na\\nprzygotowaniu kursanta, omówieniu celów zajęć oraz przekazaniu wartościowej\\ninformacji zwrotnej.\\n• Sprawniejsza organizacja kolejnych jazd. Krótsza obsługa administracyjna pomiędzy\\nzajęciami ułatwia zachowanie punktualności, ogranicza opóźnienia i pozwala efektywniej\\nwykorzystywać pojazdy oraz czas pracy instruktorów.\\n• Jedno podsumowanie dla instruktora. Zamiast potwierdzać rozpoczęcie, wprowadzać\\nczęść danych przed jazdą, potwierdzać zakończenie i wykonywać kolejne czynności\\nosobno, instruktor otrzymuje po zajęciach jeden formularz obejmujący cały przebieg\\njazdy.\\n• Zbiorcze wprowadzenie danych po jeździe. Ośrodek, kursant, instruktor, pojazd i\\npozostałe informacje mogą zostać wskazane lub zweryfikowane dopiero w końcowym\\npodsumowaniu. Nie ma potrzeby uzależniania technicznego rozpoczęcia rejestracji od\\nwcześniejszego posiadania przez system kompletnego zestawu danych.\\n• Pełna i uporządkowana dokumentacja. System nadal może rejestrować czas rozpoczęcia i\\nzakończenia, trasę i inne parametry automatyczne, a instruktor po jeździe uzupełnia\\ndane opisowe. Uproszczenie dotyczy kolejności i sposobu obsługi, a nie zakresu\\ninformacji ani możliwości ich późniejszej analizy.\\n• Wyższa jakość podsumowania po obu stronach. Instruktor zatwierdza kompletny zapis po\\nzakończeniu pracy, gdy zna rzeczywisty przebieg zajęć, a kursant otrzymuje następnie\\njeden gotowy wpis, który może świadomie ocenić i skomentować. \\f\\n\\nStrona 17 z 219\\n\\n• Mniej punktów awarii i przestojów. Rezygnacja z obowiązkowego skanowania kodów oraz\\nwielokrotnego potwierdzania ogranicza ryzyko opóźnień spowodowanych problemem z\\ntelefonem, aplikacją, aparatem lub połączeniem internetowym.\\n• Dostępność bez obowiązkowej aplikacji. Kursant może korzystać z aplikacji OSK albo\\nmObywatela, jeżeli uzna je za wygodne, ale powinien mieć także równoważny sposób\\nobsługi bez instalowania aplikacji na prywatnym telefonie.\\n• Niższe koszty organizacyjne i integracyjne. Ograniczenie liczby obowiązkowych systemów\\noraz manualnych kroków upraszcza wdrożenie, utrzymanie i odpowiedzialność za\\nprawidłowe działanie usługi.\\n3. Proponowany przebieg obsługi jazdy\\nEtap Sposób realizacji\\nPrzed jazdą Instruktor lub system uruchamia techniczną rejestrację sesji. Jeżeli\\nistnieje wcześniej zaplanowany harmonogram, rejestracja może\\nrozpocząć się automatycznie zgodnie z planem. Nie jest wymagane\\nwcześniejsze wprowadzenie pełnych danych ośrodka, kursanta,\\ninstruktora i pojazdu, dodatkowe potwierdzenie kursanta ani\\nskanowanie kodu QR.\\nW trakcie jazdy System automatycznie gromadzi dane możliwe do pozyskania w\\ntrakcie zajęć, w szczególności czas i przebieg trasy. Zapis jest\\nutrzymywany jako sesja, do której po jeździe mogą zostać przypisane\\npozostałe wymagane informacje. \\f\\n\\nStrona 18 z 219\\n\\nZbiorcze\\npodsumowanie\\ninstruktora\\nPo zakończeniu jazdy instruktor otrzymuje jedno kompletne\\nzestawienie. W jednym miejscu wskazuje lub weryfikuje ośrodek,\\nkursanta, instruktora, pojazd, rzeczywisty czas zajęć, kilometry,\\nuwagi i inne wymagane dane, a następnie zatwierdza cały wpis. Nie\\nmusi wykonywać odrębnych potwierdzeń na początku i na końcu\\njazdy.\\nPodsumowanie dla\\nkursanta\\nPo zatwierdzeniu przez instruktora kursant otrzymuje pełne\\nzestawienie jazdy. Dostęp może być zapewniony w aplikacji,\\ninterfejsie internetowym, na urządzeniu udostępnionym przez OSK\\nalbo w innym równoważnym kanale, bez obowiązku instalowania\\naplikacji mObywatel lub aplikacji ośrodka.\\nJedna decyzja\\nkursanta\\nPo zapoznaniu się z całym podsumowaniem kursant potwierdza\\nwpis, zgłasza niezgodność, dodaje komentarz albo odmawia\\npotwierdzenia. Wszystkie czynności powinny być dostępne w tym\\nsamym kanale, w którym przedstawiono podsumowanie.\\nEwentualna korekta Jeżeli potrzebna jest zmiana danych, instruktor przedstawia\\nskorygowane podsumowanie, a kursant może zaakceptować korektę\\nw tym samym interfejsie lub równoważnym kanale, bez\\nprzechodzenia do obowiązkowej dodatkowej aplikacji.\\n4. Uzasadnienie\\nCelem cyfryzacji powinno być przede wszystkim uproszczenie procesu i ograniczenie\\nczynności, które nie zwiększają wartości gromadzonych danych. Techniczne rozpoczęcie\\nzapisu nie wymaga wcześniejszego przypisania całego zestawu informacji. System może\\nnajpierw zarejestrować czas i trasę sesji, a następnie po zakończeniu jazdy otrzymać od\\ninstruktora dane potrzebne do utworzenia kompletnego wpisu.\\nKażda dodatkowa czynność może wydawać się jednostkowo krótka, jednak jest powtarzana\\nprzy każdej jeździe przez wszystkich instruktorów i kursantów. W skali działalności ośrodka \\f\\n\\nStrona 19 z 219\\n\\ntworzy to znaczące obciążenie organizacyjne, wydłuża przerwy pomiędzy zajęciami i\\nogranicza czas, który można przeznaczyć na rzeczywiste szkolenie.\\nPostulat wynika również z obserwacji instruktorów korzystających już z systemu, który\\nwdraża rozwiązanie funkcjonalnie zbliżone do przewidzianego w projekcie, w tym\\npotwierdzanie rozpoczęcia i zakończenia jazdy. Z ich praktycznych doświadczeń wynika, że\\nodrębne czynności na początku i na końcu są postrzegane jako zbędne oraz nie wnoszą\\ndodatkowej wartości do późniejszej analizy danych. Bardziej użyteczne jest jedno końcowe\\npodsumowanie, w którym instruktor może od razu opisać rzeczywisty przebieg zajęć i\\nzatwierdzić kompletny wpis.\\nZbiorcza obsługa po zakończeniu jazdy jest również bardziej miarodajna. Dopiero wtedy\\ninstruktor zna faktyczny czas, wykorzystany pojazd, przebieg trasy, liczbę kilometrów i\\newentualne odstępstwa. Może więc wprowadzić wszystkie dane jednorazowo, zamiast\\npotwierdzać na początku informacje, które w toku zajęć mogą się zmienić. Następnie\\nkursant otrzymuje kompletny wpis i może ocenić go jako całość.\\nProponowane uproszczenie nie ogranicza uprawnień organów nadzoru. Dane nadal\\npozostają kompletne, możliwe do analizy i powiązane z konkretną jazdą. Zmienia się jedynie\\nmoment uzupełnienia danych opisowych i liczba manualnych kroków wymaganych od\\ninstruktora oraz kursanta.\\nRównie istotna jest neutralność technologiczna. Korzystanie z aplikacji mObywatel jest\\ndobrowolne, a posiadanie smartfona i instalowanie aplikacji konkretnego OSK nie powinno\\nstawać się faktycznym warunkiem skorzystania ze szkolenia. Ośrodki mogą oferować własne\\naplikacje jako wygodne narzędzie i konkurować jakością obsługi, ale przepisy powinny\\nwymagać zapewnienia również równoważnego kanału dla osób, które nie chcą lub nie mogą\\ninstalować aplikacji. Tak zaprojektowany proces łączy wysoką jakość dokumentacji z\\npraktyczną użytecznością systemu i pozostawia użytkownikom realny wybór.\\nPodstawa dotycząca dobrowolności: Regulamin korzystania z Aplikacji mObywatel 2.0\\nwskazuje, że posługiwanie się aplikacją przez użytkowników jest dobrowolne.\\n5. Postulat legislacyjny\\nProjektowane przepisy powinny zostać ukształtowane w taki sposób, aby:\\n• przed rozpoczęciem jazdy wymagane było wyłącznie techniczne uruchomienie rejestracji\\nprzez instruktora albo system, przy czym rejestracja mogła rozpoczynać się\\nautomatycznie zgodnie z wcześniej zaplanowanym harmonogramem; \\f\\n\\nStrona 20 z 219\\n\\n• rozpoczęcie rejestracji nie było uzależnione od wcześniejszego wprowadzenia pełnych\\ndanych ośrodka, kursanta, instruktora, pojazdu i zajęć ani od potwierdzenia kursanta lub\\nzeskanowania kodu QR;\\n• system mógł najpierw zarejestrować sesję, w szczególności jej czas i trasę, a pozostałe\\nwymagane dane mogły zostać wprowadzone i przypisane po zakończeniu jazdy;\\n• instruktor po zakończeniu jazdy otrzymywał jedno zbiorcze podsumowanie i w jednym\\nmiejscu wskazywał, uzupełniał, weryfikował oraz zatwierdzał wszystkie wymagane dane,\\nbez odrębnego potwierdzania rozpoczęcia i zakończenia;\\n• kursant po zatwierdzeniu wpisu przez instruktora otrzymywał jedno kompletne\\npodsumowanie i mógł je potwierdzić, zakwestionować, skomentować albo\\nzaakceptować korektę;\\n• wszystkie czynności kursanta były możliwe zarówno w aplikacji mobilnej, jak i przez\\nrównoważny kanał niewymagający instalowania aplikacji na prywatnym telefonie;\\n• aplikacja mObywatel oraz aplikacja OSK pozostawały rozwiązaniami fakultatywnymi i\\npomocniczymi, a ich posiadanie nie stanowiło warunku rozpoczęcia lub ukończenia\\nszkolenia;\\n• indywidualny numer kursanta pełnił wyłącznie funkcję identyfikatora technicznego, a kod\\nQR nie był obowiązkowym etapem obsługi każdej jazdy;\\n• uproszczenie procedury nie wpływało na zakres gromadzonych danych, ich kompletność\\nani możliwość późniejszej analizy przez uprawnione podmioty.\\n\\n Art. 1 pkt 2\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\n1. W Art. 1 zmiana 2) w art. 23\\nProponujemy wykreślić tą zmianę w całości.\\nObecne przepisy nie zabraniają instruktorowi prowadzić szkolenie na drogach innych jak\\npubliczne. Skoro aktualne przepisy nie zabraniają to dodanie ust. 2a jest zbędne.\\nEwentualnie ustęp powinien zawierać tylko regulację zobowiązującą instruktora do\\nstosowania zasad i przepisów ruchu drogowego obowiązujących na drogach publicznych\\njeśli prowadzi szkolenie na pozostałych rodzajach dróg.\\nUważamy, że część szkolenia praktycznego nadal powinna odbywać się na placu\\nmanewrowym. W proponowanej treści ust. 2a jest zapis, że „instruktor może, na podstawie \\f\\n\\nStrona 21 z 219\\n\\noceny umiejętności osoby szkolonej”. Jak instruktor może ocenić umiejętności osoby\\nszkolonej, nie mając do dyspozycji bezpiecznego placu manewrowego ? „Głębokie spojrzenie\\nw oczy” nie wystarczy, potrzebny jest plac manewrowy. Bezpieczny plac manewrowy jest\\npotrzebny instruktorom i wielu kursantom. Instruktorom bo mogą skupić się tylko na\\nkursancie i nie muszą przejmować się innymi uczestnikami ruchu drogowego. Niektórzy\\nkursanci mimo zapisania się na kurs po prostu\\nboją się prowadzić pojazd. Swój strach pokonują pod okiem instruktora tylko dlatego, że\\nszkolenie odbywa się na bezpiecznym placu manewrowym. Gdzie nie obawiają się,\\nże spowodują jakieś „nieszczęście”. Plac manewrowy na dalszym etapie szkolenia też jest\\npotrzebny. Zawsze będzie lepiej dla wszystkich uczestników ruchu drogowego, jak\\nkursant po raz pierwszy będzie trenować manewry (parkowania, ruszania pod górę) na placu\\nmanewrowym a dopiero później na publicznej drodze. Istnieje również zagrożenie, że nie\\nwszyscy instruktorzy będą odpowiedzialni i znajdą naprawdę bezpieczne miejsce do\\nprowadzenia szkolenia wstępnego. Wprowadzanie obowiązku rejestracji egzaminu\\nwewnętrznego świadczy, że nawet ustawodawca nie do końca wierzy w rzetelność\\nwszystkich instruktorów.\\n Art. 1 pkt 2\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n2) w art. 23:\\na) w ust. 2 pkt 2 lit. a otrzymuje brzmienie:\\n„a) na placu manewrowym – nie dotyczy uprawnień do kierowania pojazdami silnikowymi\\nkategorii B lub B1,”;\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nJesteśmy za utrzymaniem placu manewrowego w szkoleniu i egzaminowaniu w obecnej\\nformie.\\n\\n Art. 1 pkt 2\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nW art. 1 pkt 2 – należy powrócić do obowiązku posiadania przez OSK placów manewrowych.\\nI nie chodzi tu o obecne rozumienie placu z wyznaczonymi stanowiskami, pachołkami i\\ntyczami. Chodzi o przestrzeń, w której z zachowaniem spokoju i bezpieczeństwa będą\\nrealizowane pierwsze godziny szkoleń.\\n \\f\\n\\nStrona 22 z 219\\n\\nRuchu\\nDrogowego\\n Art. 1 pkt 2\\nprojektu\\nustawy\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n1. Ad. art. 1 pkt 2 projektu\\nZaproponowane zmiany art. 23 UoKP w zakresie ust. 2 pkt 2 lit. a, likwidującej zajęcia\\npraktyczne podczas szkolenia praktycznego w zakresie kategorii B1 i B, przeprowadzane na\\nplacu manewrowym, mogą budzić - w ocenie TLP - uzasadnione wątpliwości, związane z\\nkoniecznością zapewniania bezpieczeństwa osobie szkolonej, instruktorowi, jak i osobom\\npostronnym. Szczególnie na początku szkolenia, gdzie osoba szkolona powinna nabyć\\npodstawowe umiejętności w zakresie panowania nad pojazdem. Nie rozwiązuje tego\\nproblemu zaproponowany nowy przepis art. 23 ust. 2a UoKP, gdyż możliwość szkolenia poza\\ndrogą publiczną ma charakter fakultatywny. Ponadto, brzmienie powołanego nowego\\nprzepisu art. 23 ust. 2a może budzić poważne wątpliwości, gdyż  sugeruje możliwość\\nprowadzenia nawet 90% zająć poza drogą publiczną.\\nZgadzamy się, co do zasady, z oceną resortu infrastruktury, że plac manewrowy w\\ndotychczasowej formie (sztywno określone i wyznaczone za pomocą „patyków” stanowiska\\ndo manewrów) jest szkodliwym i zbędnym anachronizmem, który nie pozwala na\\nwykształcenie prawidłowych nawyków, niezbędnych do wykonywania manewrów w\\nrealnych sytuacjach, związanych z manewrowaniem na drodze publicznej lub w innych\\nmiejscach, gdzie na co dzień wykonywane są takie manewry. Ta krytyczna ocena placu\\nmanewrowego w dotychczasowej formie dotyczy także innych kategorii prawa jazdy takich,\\njak np. prawo jazdy kategorii C, C+E, D, i D+E.\\nNiemniej uważamy, że szkolenie praktyczne powinno zawierać obligatoryjne zajęcia\\nwstępne, przeprowadzane na dowolnym placu, który jest zabezpieczony przed dostępem\\nosób trzecich w trakcie przeprowadzanych zajęć . Może to być dowolne miejsce,\\nudostępnione przez uprawnionego zarządcę tego obiektu, takie jak np.: wydzielona część\\nparkingu przy dowolnym obiekcie biurowym, przemysłowym, sportowym, handlowym lub\\nlogistycznym, w dniach gdy obiekt ten nie jest użytkowany. O czasie trwania tych zajęć\\nwstępnych, powinien decydować wyłącznie instruktor ,uwzględniając stopień panowania\\nnad pojazdem.\\nOdnosząc się do miejsca i sposobu przeprowadzania zajęć praktycznych, regulowanych w\\nart. 23 UoKP, należałoby zapewnić możliwość używania symulatorów podczas zajęć z\\npercepcji ryzyka. Nawet prosty symulator (bez jakichkolwiek stopni swobody) pozwala na \\f\\n\\nStrona 23 z 219\\n\\npokazanie większości sytuacji potencjalnie wymagających zmiany w zachowaniu kierowcy i\\nwykształcenie odpowiednich nawyków w tym obszarze.\\nMając na uwadze wskazane wyżej zastrzeżenia i postulaty, proponujemy w art. 23 UoKP:\\n• nadanie ust. 2 pkt 2 brzmienia:\\n\\n„2) część praktyczną w zakresie kierowania pojazdem, zwaną dalej „nauką jazdy”,\\nprzeprowadzaną:\\n• w miejscu (placu) zabezpieczonym w trakcie przeprowadzania zajęć przed dostępem\\nosób postronnych,\\n• w ruchu miejskim,\\n• w ruchu poza obszarem zabudowanym;”\\n• zmianę proponowanego w projekcie brzmienia ust. 2a na następujące:\\n\\n2a. Zajęcia z zakresu rozpoznawania zagrożeń, prowadzone podczas części praktycznej\\nszkolenia, o której mowa w ust. 2 pkt 2, mogą być prowadzone w ośrodku szkolenia z\\nwykorzystaniem symulatora jazdy.\\n\\nArt. 1 pkt 2 lit.\\na projektu\\nustawy\\n\\nPolski Związek\\nSzkoleniowy\\nW art. 1 w pkt 2 w lit. a proponujemy zmianę nowego brzmienia przepisu art. 23 ust. 2 pkt 2\\nlit. a poprzez zamianę słów „silnikowymi kategorii B lub B1,” na słowa „kategorii B lub B1\\noraz kategorii AM - w przypadku przeprowadzania szkolenia zakresie prawa jazdy kategorii\\nAM przy użyciu czterokołowca lekkiego lub motoroweru trójkołowego;”\\nZarówno szkolenie jak i egzaminowanie w zakresie prawa jazdy kategorii AM może odbywać\\nsię na czterokołowcu lekkim albo motorowerze trójkołowym. Szkolenie takie jak i egzamin\\nodbywa się na zasadach określonych dla prawa jazdy kategorii B1. Dlatego też, jeżeli OSK\\nprowadzi szkolenia na prawo jazdy kategorii AM czterokołowca lekkiego lub motoroweru\\ntrójkołowego to to szkolenie także powinno być formalnie wyłączone spod wymagania\\nprzeprowadzania go na placu manewrowym. Usunięcie z definicji słowa „silnikowym” wiąże\\nsię z definicją motoroweru który nie jest pojazdem silnikowym.\\n\\n \\f\\n\\nStrona 24 z 219\\n\\n Art. 1 pkt 2 lit.\\nb projektu\\nustawy\\n\\nPolski Związek\\nSzkoleniowy\\n3) W art. 1 w pkt 2: w lit. b proponujemy zmianę polegającą na zmianie brzmienia nowego\\nust. 2a poprzez zamianę słów „pojazdem silnikowym kategorii B lub B1” na słowa „kategorii\\nB lub B1 oraz kategorii AM - w przypadku przeprowadzania szkolenia zakresie prawa jazdy\\nkategorii AM przy użyciu czterokołowca lekkiego lub motoroweru trójkołowego;”\\nUzasadnienie jak powyżej.\\n\\nPo lit b dodaje się lit c w brzmieniu:\\n\\nW art. 23 po ust. 3 dodaje się ust. 3a i 7a w brzmieniu:\\n„3a. Część praktyczna szkolenia, o której mowa w ust. 2 pkt 2, w wymiarze 10% zajęć, może\\nbyć prowadzona przy użyciu urządzenia technicznego do symulowania jazdy samochodem\\nosobowym, spełniającego wymagania określone w przepisach wydanych na podstawie ust.\\n7a, posiadającego ważny certyfikat wydany przez jednostkę akredytowaną w polskim\\nsystemie akredytacji, który potwierdza spełnienie tych wymagań przez to urządzenie.\\n7a. Minister właściwy do spraw transportu określi, w drodze rozporządzenia, wymagania\\ntechniczno-organizacyjne oraz zakres funkcjonalności realizowanej przez urządzenie, o\\nktórym mowa w ust. 3a, uwzględniając potrzebę zapewnienia wykorzystania podczas\\nszkolenia urządzeń spełniających jednolite wymagania.”;”\\n\\nUzasadnienie\\nUwzględniając rozwój technologii szkoleniowych i zapotrzebowanie rynku, podobnie jak w\\nprzypadku szkoleń dla kierowców zawodowych, proponujemy umożliwienie ośrodkom\\nszkolenia kierowców prowadzenie części szkolenia praktycznego przy użyciu odpowiednich\\nsymulatorów jazdy. Urządzenia te mogłyby być z powodzeniem stosowane w pierwszej fazie\\nszkolenia na placu manewrowym, w szczególności w zakresie obsługi urządzeń pojazdu,\\nzmiany biegów, trzymania się w pasie ruchu, umiejętności ruszania i bezpiecznego\\nzatrzymania. W drugiej fazie szkolenia symulatory mogłyby być wykorzystane do nauki jazdy\\npo autostradzie. W szczególności dotyczy to miejscowości, w których wyjazd na autostradę\\nczy drogę szybkiego ruchu jest utrudniony. Zanim osoba szkolona fizycznie wyjechałaby na\\nautostradę w bezpieczny sposób mogłaby się oswoić z zasadami wjazdu na autostradę,\\nwłączania się do ruchu, zmiany pasa ruchu, a także opuszczenia autostrady. Takie zajęcia na\\npewno przygotowałyby kursantów do lekcji w realnym ruchu dając instruktorom poczucie\\nbezpieczeństwa przy pierwszych lekcjach w fizycznym ruchu drogowym.  \\f\\n\\nStrona 25 z 219\\n\\nNależy pamiętać, że symulatory dają możliwość oprócz zwykłych sytuacji drogowych\\nsymulowania sytuacji nietypowych z którymi osoba szkolona może nigdy nie spotkać się\\npodczas szkolenia. Możliwość prowadzenia takiego szkolenia w znacznym stopniu przyczyni\\nsię do poprawy umiejętności przyszłych kierowców, a więc także do poprawy\\nbezpieczeństwa.\\nNależy pamiętać, że konieczność umożliwienia wszystkim osobom szkolonym bezpiecznego\\nzapoznania się z zasadami ruchu po autostradach jest jednoznacznie uzasadniona ostatnimi\\nwypadkami śmiertelnymi na tych drogach. Warto umożliwić wszystkim, nawet tym którzy do\\nautostrady nie mają jeszcze dostępu, bezpieczną naukę poruszania się tymi drogami z\\nuwzględnieniem wjazdów i zjazdów z nich.\\n Art. 1 pkt 2\\nprojektu\\nustawy w\\nzakresie art.\\n23 ust. 2 pkt 2\\nlit. a ustawy o\\nkierujących\\npojazdami\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPropozycja zmiany:\\na) na placu manewrowym – nie dotyczy uprawnień do kierowania pojazdami silnikowymi\\nkategorii B, B1 i AM (trójkołowca)\\nUzasadnienie:\\nProponowana zmiana jest konsekwencją wprowadzenia głównej zmiany w procesie\\nszkolenia i egzaminowania – likwidacja placu manewrowego. Skoro znosimy dla kat. B1 i B\\nplac manewrowy to dla kategorii AM, który odbywa się trójkołowcem taka zmiana wydaje\\nsię być zasadna.\\n Art. 1 pkt 2\\nprojektu\\nustawy w\\nzakresie art.\\n23 ust. 2a\\nustawy o\\nkierujących\\npojazdami\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nW przypadku szkolenia osoby ubiegającej się o uprawnienia do kierowania pojazdem\\nsilnikowym kategorii B, B1 i AM (trójkołowiec), instruktor może, na podstawie oceny\\numiejętności osoby szkolonej, podjąć decyzję o przeprowadzeniu części zajęć z nauki\\njazdy poza drogą publiczną, strefą zamieszkania i strefą ruchu, pod warunkiem zapewnienia\\nprzez instruktora stosowania zasad i przepisów ruchu drogowego\\nobowiązujących na drodze publicznej.\\n\\nProponowana zmiana jest konsekwencją wprowadzonej zmiany w punkcie powyżej.\\n\\nArt. 1 pkt 2\\nprojektu\\nustawy\\n\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\n\\nUwaga 7. Uregulowanie formy prowadzenia zajęć teoretycznych poprzez dopuszczenie\\nnauczania na odległość wyłącznie w czasie rzeczywistym i udostępnienie tej formy\\nwszystkim ośrodkom szkolenia kierowców (art. 1 pkt 2 projektu; art. 23 ust. 3 i art. 26 ust.\\n2 ustawy)\\nTreść uwagi: Przedmiotem nowelizacji jest ustawa o kierujących pojazdami, w związku z tym\\npostulujemy objęcie nią również art. 23 ust. 3 ustawy poprzez doprecyzowanie, że nauczanie \\f\\n\\nStrona 26 z 219\\n\\nna odległość w części teoretycznej szkolen ia jest dopuszczalne wyłącznie w formie zajęć\\nprowadzonych w czasie rzeczywistym przez wykładowcę lub instruktora, z możliwością\\nbieżącego zadawania pytań, co oznacza rezygnację z e-learningu opartego na odtwarzaniu\\ngotowych materiałów, oraz udostępnienie tak rozumianego nauczania na odległość wszystkim\\nośrodkom szkolenia kierowców poprzez uchylenie art. 26 ust. 2 ustawy.\\nProblem: Obowiązujący art. 23 ust. 3 ustawy dopuszcza przeprowadzenie wykładów w formie\\nnauczania na odległość z wykorzystaniem technik komputerowych i Internetu pod nadzorem\\nośrodka szkolenia kierowców, przy czym zgodnie z art. 26 ust. 2 ustawy szkolenie w tej formie\\nmoże prowadzić wyłącznie ośrodek posiadający poświadczenie potwierdzające spełnianie\\ndodatkowych wymagań, a przepisy nie rozróżniają zajęć prowadzonych na żywo przez\\nwykładowcę od e-learningu polegającego na samodzielnym odtwarzaniu gotowych\\nprezentacji, który nie daje gwarancji rzetelnego przeprowadzenia części teoretycznej i w\\npraktyce sprowadza się często do jak najszybszego przechodzenia przez kolejne slajdy.\\nPodzielamy pogląd części organizacji branżowych o potrzebie rezygnacji z tak rozumianego e-\\nlearningu, sprzeciwiamy się natomiast postulatom całkowitego zakazu wszelkich form\\nszkolenia na odległość, ponieważ zajęcia prowadzone w czasie rzeczywistym z\\nwykorzystaniem platform webinarowych, powszechnie stosowane przez uczelnie wyższe w\\nmodelu kształcenia mieszanego, pozwalają utworzyć wirtualną salę wykładową z\\nzachowaniem norm metodycznych, z bezpośrednim kontaktem z prowadzącym,\\nprezentacjami, filmami edukacyjnymi i bieżącą weryfikacją wiedzy, a zarazem eliminują\\nbarierę dojazdu, szczególnie istotną dla kursantów z mniejszych miejscowości. Przy zajęciach\\nprowadzonych w czasie rzeczywistym, rejestrowanych w cyfrowej karcie kursanta,\\nutrzymywanie bariery w postaci poświadczenia potwierdzającego spełnianie dodatkowych\\nwymagań traci uzasadnienie, dlatego wzorem rozwiązania obowiązującego w okresie\\npandemii możliwość prowadzenia zajęć na odległość powinna przysługiwać wszystkim\\nośrodkom szkolenia kierowców. Postulat ten pozostaje w pełnej synergii z projektowaną\\ncyfrową kartą kursanta oraz z uwagą 2 niniejszego stanowiska, ponieważ rejestracja w karcie\\ndaty, godzin i formy realizacji zajęć teoretycznych, wraz z funkcjami platform webinarowych\\ndokumentującymi czas logowania i obecność uczestników, czyni nadzór nad zajęciami\\nprowadzonymi na odległość w pełni realnym i weryfikowalnym.\\nPropozycja zmiany zapisu: Proponujemy, aby w art. 1 pkt 2 projektu dodać lit. c w brzmieniu:\\n„c) ust. 3 otrzymuje brzmienie: \\f\\n\\nStrona 27 z 219\\n\\n«3. Wykłady, o których mowa w ust. 2 pkt 1, mogą być przeprowadzone w formie\\nnauczania na odległość z wykorzystaniem technik komputerowych i Internetu, pod\\nnadzorem ośrodka szkolenia kierowców, jeżeli:\\n1) zajęcia są prowadzone w czasie rzeczywistym przez wykładowcę lub\\ninstruktora z wykorzystaniem platformy umożliwiającej transmisję obrazu i\\ndźwięku;\\n2) osoby szkolone mają możliwość zadawania pytań oraz komunikowania się z\\nprowadzącym zajęcia w czasie rzeczywistym;\\n3) nie obejmują one zajęć z zakresu udzielania pierwszej pomocy ofiarom\\nwypadków drogowych.»”\\noraz aby w art. 1 projektu dodać punkt uchylający art. 26 ust. 2 ustawy, tak aby prowadzenie\\nzajęć teoretycznych w formie nauczania na odległość w czasie rzeczywistym było dostępne dla\\nwszystkich ośrodków szkolenia kierowców, bez konieczności posiadania poświadczenia\\npotwierdzającego spełnianie dodatkowych wymagań.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy\\n\\nPolska\\nWytwórnia\\nPapierów\\nWartościowych\\nS.A.\\nw maju br. został przez PWPW S.A. udostępniony Portal e-usług (portal dostępny pod\\nadresem: https://info-kierowca.pl/). Portal ten przewiduje możliwość złożenia wniosku o\\nwydanie prawa jazdy oraz wniosku o wydanie karty kwalifikacji kierowcy przy użyciu\\nformularza utrwalonego w postaci elektronicznej. Jest to portal skierowany do osób\\nubiegających się o uzyskanie uprawnień do kierowania pojazdami, zatem do tej samej grupy\\nodbiorców, co kursanci.\\nJak wskazano powyżej portal ten został zbudowany\\nz wykorzystaniem środków z Krajowego Planu Odbudowy\\ni Zwiększania Odporności, a PWPW S.A. została zobowiązana do utrzymania trwałości tego\\nprojektu przez okres 5 lat od dnia jego uruchomienia.\\nZ uwagi na powyższe projektowane rozwiązania powinny zostać powiązane z ww. portalem,\\nco zapewni spójną\\ni jednolitą obsługę osób ubiegających się o uprawnienia do kierowania pojazdami od etapu\\nszkolenia do etapu wydania dokumentu potwierdzającego te uprawnienia.  \\f\\n\\nStrona 28 z 219\\n\\nDodatkowo proponuje się, aby w „cyfrowej karcie kursanta” ewidencjonowane były dane\\ndotyczące szkolenia teoretycznego na zasadach analogicznych jak przewidziano dla\\newidencjonowania przebiegu zajęć praktycznych\\nw zakresie nauki jazdy.\\n1) projektowany art. 23b ust. 3 ustawy powinien otrzymać brzmienie:\\n„3. Indywidualny numer kursanta może być odwzorowany za pomocą kodu QR w usłudze\\nelektronicznej udostępnionej przez wytwórcę praw jazdy, kart kwalifikacji kierowcy i\\npozwoleń na kierowanie tramwajem umożliwiającej złożenie wniosku o wydanie tych\\ndokumentów za pomocą środków komunikacji elektronicznej, na podstawie danych\\npodanych przez wnioskodawcę po uwierzytelnieniu.”;\\n\\n2) projektowany art. 23c ust. 2 ustawy powinien otrzymać brzmienie:\\n„2. Instruktor przeprowadzający zajęcia w zakresie nauki jazdy lub część praktyczną\\negzaminu wewnętrznego ma dostęp do danych i informacji zawartych w cyfrowej karcie\\nkursanta w zakresie zajęć lub części praktycznej egzaminu wewnętrznego, po\\nuwierzytelnieniu.”;\\n\\n3) projekt powinien zostać uzupełniony o przepis przyznający dostęp do danych zawartych\\nw cyfrowej karcie kursanta także wykładowcy.\\n Art. 1 pkt 3\\nprojektu\\nustawy\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n1. Ad. art. 1 pkt 3\\nProponowane w pkt 3 projektu zmiany UoKP polegają na wprowadzeniu do procesu\\nszkolenia „cyfrowej karty kursanta”. Ogólne krytyczne uwagi co do zasadności i sposobu\\nwdrożenia tego rozwiązania wskazane zostały w uwagach TLP do art. 1 pkt 1 projektu. I\\npodtrzymujemy wskazane tamże wnioski, których przyjęcie oznaczałoby odrzucenie\\nproponowanych w pkt 3 przepisów w lub ich bardzo poważną modyfikację.\\nOdnosząc się natomiast do szczegółowym propozycji zawartych w art. 1 pkt 3 przekazujemy\\nnastępujące uwagi:  \\f\\n\\nStrona 29 z 219\\n\\n• W art. 23c ust. 1 UoKP w zdaniu wprowadzającym do wyliczenia, użyto wyrazu\\n„rejestruje”. Bardziej właściwym byłoby użycie wyrazu „wprowadza”. Zwracamy uwagę, iż\\nrejestrowanie powinno następować do określonego systemu, podczas gdy cyfrowa karta\\nkursanta, zgodnie z definicją zaproponowaną w nowym art. 2 pkt 5 UoKP, stanowi zestaw\\ndanych, czyli zawartość lub zbiór informacji, które już są w systemie przetwarzane, a nie\\nstanowią system, jako odrębny byt.\\n• W odniesieniu do art. 23c ust. 1 pkt 1 i 2 UoKP, TLP podtrzymuje wyżej wyrażone w\\nuwagach do pkt 1, wątpliwości, czy tak szczegółowe dane i informacje, powinny stanowić\\nmaterię rangi ustawowej, czy też nie powinny zostać przeniesione do rozporządzenia, jako\\naktu wykonawczego względem UoKP. Wątpliwości te są tym bardziej uzasadnione, iż biorąc\\npod uwagę różnorodny zakres i charakter omawianych danych, każdorazowa ich późniejsza\\nzmiana będzie wymagała kolejnej nowelizacji UoKP, podczas gdy ewentualna zmiana\\nrozporządzenia będzie proceduralnie krótsza a osiągnięty cel i skutek będzie taki sam.\\n• W art. 23c ust. 1 pkt 1 i 2 UoKP występuje niezgodność z art. 2 pkt 5 UoKP. W\\n“cyfrowej karcie kursanta” wprowadza się trzy, odrębne zestawy danych: identyfikujących\\nosobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem, dotyczących\\nprzebiegu szkolenia w zakresie nauki jazdy oraz dotyczących przebiegu części praktycznej\\negzaminu wewnętrznego, podczas gdy rejestracja do cyfrowej karty obejmuje tylko dane\\ndotyczące przebiegu szkolenia i egzaminu wewnętrznego, dublując dane identyfikujące\\nosobę szkoloną.\\n• W art. 23c ust. 1 pkt 1 lit. e-f UoKP, należy doprecyzować , czy data i godzina\\nrozpoczęcia / zakończenia zajęć ma dotyczyć pierwszych i ostatnich zajęć całego szkolenia,\\nczy ma dotyczyć każdorazowo rozpoczynania i zakańczania konkretnych zajęć w ramach, np.\\njednego dnia szkolenia.\\n• W art. 23c ust. 3 i 4 UoKP, następuje nieuzasadnione rozszerzenie obowiązków\\ninstruktorów nauki jazdy o wprowadzanie i potwierdzanie danych oraz informacji w cyfrowej\\nkarcie kursanta. W ocenie TLP, pomijając fakt, iż informacje wpisuje się, a nie potwierdza,\\ncelem instruktora jest przygotowanie kursanta do bezpiecznego prowadzenia pojazdu oraz\\nzdania egzaminu państwowego, a nie czasochłonna biurokracja i weryfikacja elektronicznie\\nzgromadzonych danych i informacji.  \\f\\n\\nStrona 30 z 219\\n\\n• W art. 23c ust. 5 UoKP, okres lenie „aplikacja mobilna zintegrowana z cyfrową kartą\\nkursanta” jest ogólne i nie wskazuje podstawowych elementów, tj. jakie mają być\\nparametry/wymagania takiej aplikacji, w jaki sposób ma być integrowana z zestawem\\ndanych i informacji, który nie stanowi systemu oraz kto będzie odpowiedzialny za taką\\nintegrację.\\n• W art. 23c ust. 6 UoKP, TLP sprzeciwia się rozwiązaniu, zgodnie z którym dane\\nlokalizacyjne dotyczące godziny i daty zakończenia zajęć oraz trasy jazdy nie będą mogły być\\nzmieniane ani usuwane. Po pierwsze, nie wskazano, zakończenie których zajęć ma być\\nrejestrowane (całości szkolenia czy pojedynczych w ramach każdego dnia szkolenia, czy\\ninnych?), a po drugie, proponowane rozwiązanie jest nieadekwatne do stanów faktycznych\\nmogących mieć miejsce podczas nauki, np. błędna lokalizacja generowana przez system\\nteleinformatyczny, zakłócenia systemu przekazywania danych geolokalizacyjnych, oczywiste\\nomyłki pisarskie. W ocenie TLP, w projektowanym przepisie kropkę należałoby zastąpić\\nprzecinkiem i dodać wyrazy „chyba, że zaistnieją szczególne okoliczności, na które osoba\\nszkolona lub instruktor nie mieli wpływu”.\\n• W art. 23d UoKP, przepisy dotyczące szczegółowej procedury wprowadzania przez\\nkursanta uwag, potwierdzania lub odmowy potwierdzania przebiegu szkolenia i egzaminu\\nwewnętrznego, a także wprowadzania, potwierdzania i zatwierdzania zestawów danych na\\ncyfrowej karcie kursanta przez instruktora, stanowią materię rozporządzenia, jako aktu\\nwykonawczego do ustawy, a nie projektowanej UoKP. W art. 23j ust. 2 UoKP, po pierwsze,\\nzwracamy uwagę, iż „prawomocne zakończenie postępowania” jest okres leniem ogólnym,\\npotocznym, a tym samym niezdefiniowanym w przepisach prawnych, które odnosi się do\\nsytuacji w której w danej sprawie zapadło już orzeczenie, niepodlegające zaskarżeniu za\\npomocą zwyczajnych środków odwoławczych. Prawomocność należy odnosić raczej do form\\nrozstrzygnięć sądowych – wyroków /postanowień, podczas gdy decyzje administracyjne, nie\\nsą prawomocne tylko ostateczne. Po drugie, w projektowanym przepisie nie wskazano, do\\njakiego rodzaju postępowań należy odnosić „prawomocność ”, tj. administracyjnego,\\nkarnego, czy cywilnego.\\n• W art. 23j ust. 5 UoKP, użyte określenia „w celach komercyjnych, promocyjnych i\\nreklamowych” nie są zdefiniowane, a dotyczą jednego z elementów zakazu przetwarzania\\ndanych osobowych przez ośrodek szkolenia kierowców. W ocenie TLP, wszelkie przepisy \\f\\n\\nStrona 31 z 219\\n\\nprojektujące sankcje, w tym znamiona czynów niedozwolonych, powinny być konkretne, tj.\\ndokładne i jednoznaczne.\\n• W odniesieniu do art. 1 pkt 3 projektu, w zakresie art. 23i-j UoKP, art. 1 pkt 4\\nprojektu, w zakresie art. 24pkt 1 lit. e UoKP oraz art. 1 pkt 5 lit. a-d projektu, w zakresie\\nart. 27ust. 1 pkt 7 oraz art. 27 ust. 2 pkt 6, art. 27 ust. 4b, art. 27 ust. 6-7 UoKP, zwracamy\\nuwagę, iż projektowane rozwiązania wprowadzają bardzo szczegółowe, biurokratyczne i\\nczasochłonne w realizacji, dodatkowe obowiązki ośrodków szkoleń kierowców, o\\ncharakterze formalno-administracyjnym, kto re z prawdopodobieństwem graniczącym z\\npewnością będą stanowić nie ułatwienie a kolejną barierę administracyjną w działalności\\ntych ośrodków. W ocenie TLP, zdecydowana większość tych przepisów może stanowić\\nregulację rangi rozporządzenia, bądź zostać usunięta, ze względu na obowiązujące już,\\nszczegółowe przepisy polskie i unijne oraz wynikające z nich procedury, dotyczące\\nprzetwarzania danych osobowych.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 3  - w części dotyczącej proponowanego art. 23e – nie wydaje się potrzebnym\\nzapewnienie dostępu WORD do danych i informacji zarejestrowanych w cyfrowej karcie\\nkursanta. Natomiast popieramy propozycję regulacji wnoszącej obowiązkową rejestrację\\nprzebiegu części praktycznej egzaminu wewnętrznego. Szczegółowe określenie jej\\nwarunków, zasad i procedur związanych z przechowywaniem powinno nastąpić w\\nrozporządzeniu.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\nArt. 23j ust. 1\\n„Zapis przebiegu części praktycznej egzaminu wewnętrznego przechowuje się przez okres 90\\ndni od dnia przeprowadzenia tego egzaminu, z uwzględnieniem ust. 2.”\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nProponujemy wydłużenie okresu przechowywania zapisu przebiegu części praktycznej\\negzaminu wewnętrznego. W ocenie Krajowego Stowarzyszenia Egzaminatorów zapis ten\\npowinien być przechowywany do czasu uzyskania przez osobę szkoloną pozytywnego \\f\\n\\nStrona 32 z 219\\n\\nwyniku części praktycznej egzaminu państwowego, nie dłużej jednak, niż przez okres 12\\nmiesięcy od dnia uzyskania pozytywnego wyniku egzaminu wewnętrznego.\\nProponowany w projekcie okres 90 dni może okazać się niewystarczający. Należy mieć na\\nuwadze, że od momentu zakończenia szkolenia i uzyskania pozytywnego wyniku egzaminu\\nwewnętrznego do uzyskania pozytywnego wyniku egzaminu państwowego może upłynąć\\nokres przekraczający trzy miesiące. Wpływ na to mają zarówno czas oczekiwania na\\nwyznaczenie terminu egzaminu państwowego, jak również możliwość uzyskania przez\\nkandydata negatywnych wyników kolejnych egzaminów i związana z tym konieczność\\nponownego oczekiwania na następne terminy.\\nJednocześnie znaczna część kandydatów uzyskuje pozytywny wynik egzaminu państwowego\\njuż przy pierwszym podejściu. W takich przypadkach nie istnieje potrzeba dalszego\\nprzechowywania zapisu egzaminu wewnętrznego po uzyskaniu pozytywnego wyniku części\\npraktycznej egzaminu państwowego. Powiązanie okresu przechowywania nagrania z\\nmomentem uzyskania pozytywnego wyniku egzaminu państwowego pozwoliłoby zatem\\nuniknąć nieuzasadnionego gromadzenia znacznej liczby nagrań dotyczących osób, których\\nproces uzyskiwania uprawnień został już zakończony.\\nIstotnym argumentem przemawiającym za proponowanym rozwiązaniem jest również\\nmożliwość wykorzystania zapisu egzaminu wewnętrznego do oceny prawidłowości procesu\\nszkolenia. Szczególne znaczenie może mieć to w przypadkach, w których osoba szkolona,\\npomimo uzyskania pozytywnego wyniku egzaminu wewnętrznego, wielokrotnie uzyskuje\\nnegatywny wynik części praktycznej egzaminu państwowego.\\nMożliwość weryfikacji zapisu egzaminu wewnętrznego pozwoliłaby w takich sytuacjach na\\nocenę, czy osoba szkolona w chwili jego przeprowadzania rzeczywiście prezentowała poziom\\numiejętności pozwalający na samodzielne i bezpieczne uczestnictwo w ruchu drogowym oraz\\nczy pozytywny wynik egzaminu wewnętrznego znajdował uzasadnienie w faktycznie\\nzaprezentowanych umiejętnościach.\\nRozwiązanie takie stanowiłoby również mechanizm zwiększający odpowiedzialność osób\\nprzeprowadzających egzaminy wewnętrzne. Świadomość, że zapis egzaminu może podlegać\\npóźniejszej weryfikacji, w szczególności w przypadku powtarzających się negatywnych \\f\\n\\nStrona 33 z 219\\n\\nwyników egzaminów państwowych, powinna ograniczać przypadki przedwczesnego zaliczania\\negzaminu wewnętrznego osobom, które nie osiągnęły jeszcze poziomu umiejętności\\nniezbędnego do samodzielnego i bezpiecznego kierowania pojazdem.\\nW konsekwencji kandydat, który nie osiągnął wymaganego poziomu umiejętności, powinien\\nkontynuować szkolenie w zakresie niezbędnym do uzupełnienia stwierdzonych braków,\\nzamiast uzyskiwać pozytywny wynik egzaminu wewnętrznego i podejmować kolejne,\\nnieskuteczne próby zdania egzaminu państwowego.\\nW ocenie Krajowego Stowarzyszenia Egzaminatorów proponowane rozwiązanie może zatem\\nprzyczynić się zarówno do podniesienia jakości szkolenia kandydatów na kierowców , jak i\\nzwiększenia rzetelności egzaminów wewnętrznych oraz odpowiedzialności podmiotów\\nprowadzących szkolenie za poziom przygotowania osób kierowanych na egzamin\\npaństwowy. Jednocześnie ustanowienie maksymalnego, 12-miesięcznego okresu\\nprzechowywania zapisu zapobiegałoby konieczności jego bezterminowego przechowywania\\nw przypadku osób, które po ukończeniu szkolenia nie przystąpią do egzaminu państwowego\\nalbo przez dłuższy czas nie uzyskają wyniku pozytywnego.\\nProponowane brzmienie przepisu:\\n„1. Zapis przebiegu części praktycznej egzaminu wewnętrznego przechowuje się do dnia\\nuzyskania przez osobę szkoloną pozytywnego wyniku części praktycznej egzaminu\\npaństwowego, nie dłużej jednak niż przez okres 12 miesięcy od dnia uzyskania pozytywnego\\nwyniku egzaminu wewnętrznego, z uwzględnieniem ust. 2.”\\n Art. 1 pkt 1 i\\npkt 3 projektu\\nustawy\\nOgólnopolski\\nZwiązek\\nPracodawców\\nTransportu\\nDrogowego\\nProponowane nowe rozwiązania informatyczne na pewno bardzo kosztowne nie przekładają\\nsię jednak na jakość szkolenia. Systemy informatyczne, aplikacje dostępowe, wpisy do\\nkomputera, podpisy, akcepcje treści wpisów to strata co najmniej jednej trzeciej czasu\\nkażdej godziny szkolenia. Na pewno nie zyska na tym kursant, który trafił do OSK z zamiarem\\nnabycia umiejętności. Obecny system oparty na PKK jest wystarczający do nadzorowania\\nfaktycznego ewidencjonowania szkoleń oraz czasu szkolenia. Wydawanie kolejnych środków\\nfinansowych na nową informatyzację to nie jest dobre lokowanie środków. Zdecydowanie\\nlepiej tymi środkami bezpośrednio dofinansować kursy w OSK co pozwoli osobom mniej \\f\\n\\nStrona 34 z 219\\n\\nzasobnym ukończyć kurs a nie tylko szukać taniego OSK który w ramach niskich cen\\nsfabrykuje zaświadczenie czy wpis do systemu informatycznego o ukończeniu szkolenia.\\nJesteśmy społeczeństwem mało zasobnym finansowo poprawa BRD uzyskana poprzez\\nbudowę i rozwój infrastruktury drogowej powoli osiąga poziom stabilizacji nadszedł czas na\\ndofinasowanie infrastruktury szkoleniowej, dofinasowanie szkolenia i uzyskanie wyższej\\njakości nabywanych umiejętności i zachowań. W tym kierunku powinny iść zmiany w\\nszkoleniu i egzaminowaniu to jest kolejny krok w stronę większego BRD. Nowa Dyrektywa\\n2025/2205 wprowadza bardziej rygorystyczne, harmonizowane zasady wydawania,\\nprzedłużania i odnawiania praw jazdy w ramach szerszej strategii bezpieczeństwa\\ndrogowego UE.\\nUstawa, po której branża oczekuje przełamania impasu w systemie szkolenia i\\negzaminowania proponuje jednak inny kierunek: uproszczenie szkolenia, łatwy\\nprzewidywalny egzamin oraz szybkie uzyskanie prawa jazdy. Ponadto stawianie założeń, że\\ngłównym cel ustawy poprawa jakości szkolenia osiągnięty zostanie przez zastosowanie\\nnowych rozwiązań informatycznych w ramach Centralnej Ewidencji Kierowców oraz\\nzawartych w niej funkcjonalności obsługujących proces i ewidencję szkoleń i egzaminów\\nosób kandydatów na kierowców jest założeniem bardzo ryzykownym. Dwudziestoletnie\\ndoświadczenia budowy CEK wskazują, że nadal nie posiadamy systemu sprawnej ewidencji\\npraw jazdy.\\n\\nArt. 1 pkt 3\\nprojektu\\nustawy\\n\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\nUwaga 2. Objęcie cyfrową kartą kursanta całości szkolenia, w tym zajęć teoretycznych, zajęć\\nz zakresu udzielania pierwszej pomocy oraz egzaminu wewnętrznego w części teoretycznej\\n(art. 1 pkt 3 projektu; projektowane art. 23b ust. 1 i art. 23c ust. 1)\\nTreść uwagi: Postulujemy rozszerzenie zakresu cyfrowej karty kursanta na całość szkolenia –\\nrównież na zajęcia teoretyczne, zajęcia z zakresu udzielania pierwszej pomocy oraz egzamin\\nwewnętrzny w części teoretycznej, wraz z określeniem odrębnego katalogu danych\\nrejestrowanych dla tych form zajęć.\\nProblem: Projektowany art. 23b ust. 1 ogranicza zakres cyfrowej karty kursanta wyłącznie do\\nprzebiegu szkolenia w zakresie nauki jazdy oraz części praktycznej egzaminu wewnętrznego,\\nwskutek czego poza jakąkolwiek rejestracją w karcie pozostanie cała część teoretyczna\\nszkolenia, realizowana stacjonarnie albo w formie e-learningu, a także egzamin wewnętrzny\\nw części teoretycznej, podczas gdy karta ma pełnić funkcję kompletnej, wiarygodnej ewidencji \\f\\n\\nStrona 35 z 219\\n\\nprzebiegu szkolenia, stanowiącej podstawę nadzoru starosty oraz weryfikacji rzetelności\\nprocesu szkoleniowego. Rozszerzenie katalogu danych z art. 23c ust. 1 wymaga przy tym\\nodrębnej jednostki redakcyjnej z własnym katalogiem danych, z którego muszą zostać\\nlogicznie wyłączone trasa jazdy w postaci pliku danych lokalizacyjnych oraz liczba\\nprzejechanych kilometrów, ponieważ dane te z natury rzeczy mogą dotyczyć wyłącznie zajęć\\nrealizowanych pojazdem i ich mechaniczne odniesienie do zajęć teoretycznych czyniłoby\\nprzepis niewykonalnym.\\nPropozycja zmiany zapisu: W art. 1 pkt 3 projektu proponujemy, aby projektowany art. 23b\\nust. 1 otrzymał brzmienie:\\n„1. Przebieg szkolenia osoby ubiegającej się o uzyskanie uprawnienia do kierowania\\npojazdem silnikowym, obejmujący zajęcia teoretyczne, zajęcia z zakresu udzielania\\npierwszej pomocy, naukę jazdy oraz egzamin wewnętrzny w części teoretycznej i w\\nczęści praktycznej, rejestruje się w cyfrowej karcie kursanta.”\\noraz aby w projektowanym art. 23c w ust. 1 w pkt 2 w lit. l kropkę zastąpić średnikiem i dodać\\npkt 3 i 4 w brzmieniu:\\n„3) przebiegu zajęć teoretycznych oraz zajęć z zakresu udzielania pierwszej pomocy:\\na) imię i nazwisko oraz numer PESEL lub datę urodzenia osoby ubiegającej się o\\nuzyskanie uprawnienia do kierowania pojazdem silnikowym,\\nb) imię i nazwisko oraz numer uprawnień instruktora albo imię i nazwisko\\nwykładowcy prowadzącego zajęcia,\\nc) nazwę ośrodka szkolenia kierowców lub podmiotu prowadzącego szkolenie, o\\nktórym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, oraz numer w rejestrze\\nprzedsiębiorców prowadzących ośrodek szkolenia kierowców lub numer w\\newidencji podmiotów prowadzących szkolenie,\\nd) datę i godzinę rozpoczęcia zajęć oraz datę i godzinę zakończenia zajęć,\\ne) formę realizacji zajęć, ze wskazaniem, czy zajęcia były prowadzone w formie\\nstacjonarnej, czy w formie nauczania na odległość,\\nf) informację o potwierdzeniu albo odmowie potwierdzenia przebiegu zajęć przez\\nprowadzącego zajęcia lub osobę ubiegającą się o uzyskanie uprawnienia do\\nkierowania pojazdem silnikowym; \\f\\n\\nStrona 36 z 219\\n\\n4) przebiegu części teoretycznej egzaminu wewnętrznego:\\na) dane i informacje, o których mowa w pkt 3 lit. a i c,\\nb) imię i nazwisko oraz numer uprawnień instruktora albo imię i nazwisko\\nwykładowcy przeprowadzającego część teoretyczną egzaminu wewnętrznego,\\nc) datę przeprowadzenia oraz wynik części teoretycznej egzaminu wewnętrznego,\\nd) informację o potwierdzeniu albo odmowie potwierdzenia przebiegu części\\nteoretycznej egzaminu wewnętrznego przez przeprowadzającego ten egzamin lub\\nosobę ubiegającą się o uzyskanie uprawnienia do kierowania pojazdem silnikowym.”\\nwraz z odpowiednim dostosowaniem projektowanych art. 23c ust. 3 i 4 w zakresie danych\\nwprowadzanych i potwierdzanych przed rozpoczęciem i po zakończeniu zajęć.\\n\\nArt. 1 pkt 3\\nprojektu\\nustawy\\n\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\nUwaga 3. Wprowadzenie cyfrowego arkusza przebiegu części praktycznej egzaminu\\nwewnętrznego, prowadzonego w karcie kursanta obok rejestracji obrazu i dźwięku (art. 1\\npkt 3 projektu; projektowane art. 23c ust. 1 pkt 2 oraz art. 23h)\\nTreść uwagi: Postulujemy, aby przebieg części praktycznej egzaminu wewnętrznego był\\nrejestrowany nie tylko za pomocą urządzenia służącego do zapisu obrazu i dźwięku, lecz\\nrównież w postaci ustrukturyzowanego, cyfrowego arkusza przebiegu tego egzaminu,\\nstanowiącego część cyfrowej karty kursanta i obejmującego, w odniesieniu do każdego\\nzadania egzaminacyjnego, jego identyfikator, dane lokalizacyjne, znacznik czasu oraz wynik\\ndla poszczególnych kryteriów oceny. Rejestracja obrazu i dźwięku przewidziana w\\nprojektowanym art. 23h pozostaje bez zmian i funkcjonuje równolegle z arkuszem.\\nProblem: Projekt konsekwentnie cyfryzuje całą dokumentację przebiegu szkolenia w cyfrowej\\nkarcie kursanta, natomiast wynik części praktycznej egzaminu wewnętrznego rejestruje w\\nprojektowanym art. 23c ust. 1 pkt 2 lit. i wyłącznie jako wynik zbiorczy, a poza tym poprzestaje\\nna nagraniu obrazu i dźwięku, które stanowi dane nieustrukturyzowane, wysokowolumenowe\\ni niepoddające się automatycznej analizie. W konsekwencji dokumentacja przebiegu\\negzaminu wewnętrznego pozostaje w warstwie cyfrowej uboższa niż dokumentacja zwykłych\\njazd szkoleniowych, mimo że to właśnie egzamin wewnętrzny jest momentem weryfikacji\\ngotowości kursanta. Zapis ustrukturyzowany na poziomie pojedynczego zadania, prowadzony\\nobok nagrania, nie zwiększa istotnie kosztów, ponieważ wykorzystuje tę samą infrastrukturę \\f\\n\\nStrona 37 z 219\\n\\nkarty kursanta i to samo urządzenie lokalizacyjne, które projekt i tak wymaga na podstawie\\nart. 23f pkt 1, a jednocześnie czyni przebieg egzaminu wewnętrznego danymi\\nprzetwarzalnymi maszynowo, umożliwiającymi nadzór skalowalny, wykrywanie anomalii oraz\\nzasilanie statystyki bezpieczeństwa ruchu drogowego, podczas gdy nagranie obrazu i dźwięku\\nzachowuje swoją niezastąpioną funkcję dowodową w sytuacjach spornych.\\nPropozycja zmiany zapisu: W art. 1 pkt 3 projektu proponujemy, aby projektowany art. 23c\\nust. 1 pkt 2 lit. i otrzymała brzmienie:\\n„i) w odniesieniu do każdego zadania egzaminacyjnego – jego identyfikator, dane\\nlokalizacyjne w formacie, o którym mowa w lit. g, znacznik czasu oraz wynik dla\\nposzczególnych kryteriów oceny, a także zbiorczy wynik części praktycznej egzaminu\\nwewnętrznego,”\\noraz aby w projektowanym art. 23h dodać ust. 6 w brzmieniu:\\n„6. Niezależnie od rejestracji, o której mowa w ust. 1, przebieg części praktycznej\\negzaminu wewnętrznego rejestruje się w cyfrowym arkuszu przebiegu tego egzaminu,\\nstanowiącym część cyfrowej karty kursanta, obejmującym dane, o których mowa w art.\\n23c ust. 1 pkt 2 lit. i. Do rejestracji danych lokalizacyjnych oraz znaczników czasu stosuje\\nsię odpowiednio art. 23c ust. 5.”\\n\\nArt. 1 pkt 3\\nprojektu\\nustawy\\n\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\nUwaga 4. Wykorzystanie danych cyfrowej karty kursanta do analizy jakości szkolenia i\\ninformacji zwrotnej dla ośrodków szkolenia kierowców (art. 1 pkt 3 projektu; projektowany\\nart. 23g ust. 3)\\nTreść uwagi: Postulujemy rozszerzenie celu przetwarzania danych lokalizacyjnych\\nzarejestrowanych w cyfrowej karcie kursanta tak, aby obok weryfikacji przebiegu jazd mogły\\none być przetwarzane, w postaci zagregowanej i zanonimizowanej, do analizy jakości\\nszkolenia, informacji zwrotnej dla ośrodków szkolenia kierowców oraz statystyki\\nbezpieczeństwa ruchu drogowego.\\nProblem: Projektowany art. 23g ust. 3 dopuszcza przetwarzanie danych lokalizacyjnych\\nwyłącznie w celu weryfikacji przebiegu jazd, a więc redukuje cyfrową kartę kursanta do\\nnarzędzia czysto kontrolnego, podczas gdy zgromadzone w niej dane, przetwarzane\\nwspółczesnymi narzędziami analitycznymi, w tym algorytmami sztucznej inteligencji, \\f\\n\\nStrona 38 z 219\\n\\npozwalają wyznaczać obiektywne mierniki jakości procesu szkolenia, takie jak średnia liczba\\nkilometrów przejeżdżanych przez kursantów w ruchu drogowym w skali ośrodka, rozkład tych\\nwartości w skali kraju wraz ze wskazaniem wartości najwyższych i najniższych, struktura\\nobszarów, na których prowadzone są zajęcia, czy udział jazd realizowanych poza obszarem\\nzabudowanym, a następnie zwracać te informacje ośrodkom szkolenia kierowców i organom\\nnadzoru oraz zasilać statystykę bezpieczeństwa ruchu drogowego. Rozwiązanie takie\\nkoresponduje z zadaniem Centrum Egzaminowania określonym w projektowanym art. 57aa\\nust. 2 pkt 5 i sprawia, że znaczący koszt wdrożenia karty zwróci się w postaci realnej pętli\\ninformacji zwrotnej podnoszącej jakość szkolenia, a nie wyłącznie w postaci aparatu\\nsprawozdawczo-kontrolnego.\\nPropozycja zmiany zapisu: W art. 1 pkt 3 projektu proponujemy, aby projektowany art. 23g\\nust. 3 otrzymał brzmienie:\\n„3. Dane lokalizacyjne w formacie GPX lub równoważnym przetwarza się:\\n1) w celu weryfikacji przebiegu jazd w trakcie zajęć w zakresie nauki jazdy oraz części\\npraktycznej egzaminu wewnętrznego przez podmioty uprawnione do nadzoru oraz\\nkierownika ośrodka szkolenia kierowców albo innego podmiotu prowadzącego\\nszkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3;\\n2) w postaci zagregowanej i zanonimizowanej, w celu analizy jakości szkolenia\\nkandydatów na kierowców, przekazywania ośrodkom szkolenia kierowców oraz\\norganom nadzoru informacji zwrotnej o jakości szkolenia, a także prowadzenia\\nstatystyki bezpieczeństwa ruchu drogowego, w szczególności przez Centrum\\nEgzaminowania, o którym mowa w art. 57aa ust. 1.”\\nwraz z odpowiednim uzupełnieniem katalogu podmiotów, o których mowa w projektowanym\\nart. 23e ust. 1, o Centrum Egzaminowania w zakresie dostępu do danych w postaci\\nzagregowanej i zanonimizowanej, ponieważ bez tego uzupełnienia cel analityczny określony\\nw proponowanym pkt 2 pozostawałby bez podstawy dostępowej.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy\\n\\nPolski Związek\\nSzkoleniowy\\na) Proponujemy dostosowanie przepisów do rejestracji całości przebiegu zarówno szkolenia\\n(teoria, praktyka zajęcia z pierwszej pomocy) jak i egzaminu wewnętrznego zgodnie z opisem\\npowyżej.\\n \\f\\n\\nStrona 39 z 219\\n\\nb) W proponowanym art. 23b w ust. 2 wskazujemy, że organ właściwy w sprawach\\nwydawania dokumentów stwierdzających uprawnienia do kierowania pojazdami tworzy\\ncyfrową kartę kursanta i generuje indywidualny numer kursanta. W naszej ocenie brakuje tu\\nodesłania do tworzenia profilu kandydata na kierowcę który do tej pory był opisany w\\nrozporządzeniu w sprawie wydawania dokumentów stwierdzających uprawniania do\\nkierowania pojazdami. Aby zachować właściwą kolejność tworzonych przez starostę\\ndokumentów proponujemy następujące brzmienie tego przepisu:\\n„2. Organ właściwy w sprawach wydawania dokumentów stwierdzających uprawnienia do\\nkierowania pojazdem silnikowym, generując profil kandydata na kierowcę w systemie\\nteleinformatycznym tworzy cyfrową kartę kursanta i generuje indywidualny numer\\nkursanta.”\\nTakie rozwiązanie będzie zgodne z dotychczasowym rozwiązaniem informatycznym i wskaże\\nstaroście kolejność zadań. Przeniesienie zadania tworzenia profilu kandydata na kierowcę z\\nrozporządzenia do ustawy jest niezbędne do wskazania i utrzymania jednolitego trybu\\npostępowania w tych sprawach.\\n\\n c) W proponowanym art. 23c w ust. 1 pkt 1 lit i sugerujemy usunięcie możliwości\\nwskazywania liczby kilometrów poprzez ręczne wpisywanie wskazań licznika pojazdu. Takie\\nrozwiązanie niestety spowoduje, że tak czy inaczej będą wpisywane niewłaściwe informacje.\\nTylko automatyczna rejestracja za pomocą GPS rozwiązuje ten problem.\\n\\n d) Odnosząc się do zapisywania śladu GPS tylko w formacie pliku GPX należy wskazać, że jest\\nto zbyt mało. Na rynku istnieją programy, które służą do podmiany danych zapisanych w\\nplikach GPX. I to nie po ich utworzeniu, a w czasie rzeczywistym Jest to tzw. GPS spoofing.\\nRozwiązaniem jest np. zapis dwóch plików zarówno od kursanta jak i od instruktora, albo\\ndanych z BTS.\\n\\n e) W proponowanym art. 23c ust. 2 sugerujemy dodanie warunku aby instruktor miał dostęp\\ndo tych danych, ale dopiero po potwierdzeniu swojej tożsamości (np. po zalogowaniu się do\\naplikacji instruktora potwierdzając swoją tożsamość poprzez login.gov.). Samo\\nwprowadzenie indywidualnego numeru instruktora nie jest wystarczające, a tym bardziej\\nwyłącznie podanie imienia nazwiska i numeru instruktora. Mimo wszystko jest to dostęp do \\f\\n\\nStrona 40 z 219\\n\\ndanych osobowych kursanta. Imię, nazwisko i nr instruktora może wpisać każdy i znać każdy.\\nJest tu duże pole do popisu dla obchodzenia przepisów.\\n\\n f) W naszej ocenie możliwość podpisania (zatwierdzenia) zarówno rozpoczęcia szkolenia jak i\\njego zakończenia (przez kursanta i instruktora) powinna być możliwa dopiero po\\nzalogowaniu się i uwierzytelnieniu tożsamości kursanta w aplikacji (lub WEB). Zarówno\\nkursant jak i instruktor powinien móc zalogować się do aplikacji na 10 minut przed\\nrozpoczęciem zajęć i wylogować się na 10 minut po zakończeniu zaplanowanych zajęć. Takie\\nrozwiązanie pozwoli na uniknięcie sytuacji w której OSK wyposaży swoich kursantów w\\ntablety lub smartfony, do których kursanci zalogują się tylko (potwierdzą tożsamość) raz na\\npoczątku szkolenia, a instruktor będzie je mógł wozić ze sobą i potwierdzać kolejne zajęcia\\nza siebie i za kursanta przekazanym nr kursanta. Obowiązek zalogowania przed zajęciami i\\nwylogowania po zajęciach (tu może być automat wylogowujący po stwierdzeniu\\npotwierdzenia zakończenia danych zajęć)\\n\\n g) W proponowanym art. 23c ust. 3 i 4 sugerujemy usunięcie obowiązku wpisywania przez\\ninstruktora do cyfrowej karty kursanta danych dotyczących ośrodka szkolenia czy daty i\\ngodziny rozpoczęcia zajęć. Te dane powinny być już wpisane automatycznie przez system.\\nNajpierw kursant przychodzi do ośrodka szkolenia kierowców i zapisuje się na kurs, a więc\\ndana karta przydzielona jest już do właściwego ośrodka szkolenia. Numer instruktora także\\npowinien wpisywać się automatycznie. To ośrodek szkolenia kierowców wyznacza dla danej\\nosoby instruktora prowadzącego, zatem wiadomo jaki instruktor powinien prowadzić\\nszkolenie danej osoby.\\n\\nPozostawienie tego przepisu w takiej formie jak dziś może spowodować, że dowolny\\ninstruktor niezatrudniony w danym OSK będzie mógł w cyfrowej karcie kursanta wpisać\\ndowolny OSK i dowolnego instruktora. Kursant i tak tego nie sprawdzi i potwierdzi.\\nNarażamy się na powstanie kolejnej patologii.\\nPodobnie po zakończeniu zajęć. Zarówno godzina zakończenia, jak i liczba kilometrów\\nprzejechanych powinna być wpisywana automatycznie na podstawie danych GPS.\\n\\n h) W odniesieniu do art. 23c ust. 5 proponujemy rozważenie bieżącego przesyłania danych\\ndo cyfrowej karty kursanta wraz z danymi z BTS. W naszej ocenie możliwość późniejszego \\f\\n\\nStrona 41 z 219\\n\\nprzesłania wygenerowanego pliku daje możliwość podstawienia dowolnych danych już w\\nmomencie zakończenia zajęć. Wystarczy, że ktoś będzie miał wcześniej przygotowany plik i\\nstosowany przez niego program podstawi go w momencie zakończenia szkolenia.\\n\\n i) W odniesieniu do art. 23d ust. 1 proponujemy jednoznaczne wskazanie kto i na jakich\\nzasadach będzie miał dostęp do uwag kursanta co do przebiegu szkolenia. W naszej ocenie\\npowinno to być tak samo jak w przypadku przyczyny odmowy potwierdzenia zajęć, ale\\ndodatkowo ta informacja powinna dostępna zarówno w przypadku odmowy jak i w\\nprzypadku potwierdzenia. Uwagi kursanta mogą powstać także jak potwierdzi zajęcia. Do\\nuwag powinien też mieć wgląd organ nadzoru.\\n\\n j) W odniesieniu do art. 23d ust. 3 proponujemy dodanie konieczności akceptacji\\ndokonywanych zmian przez co najmniej kierownika OSK, ale najlepiej gdyby musiał zrobić to\\norgan nadzoru (starosta). Pozostawienie możliwości korekty bez odgórnego zatwierdzenia\\nwydaje się niezasadne. Tutaj także należy uwzględnić brak możliwości korekty OSK które\\nprowadziło szkolenie. (patrz lit. f)\\n\\n k) W odniesieniu do art. 23d ust. 6 proponujemy zamianę słowa „lub” na „jednak nie później\\nniż”. Pozostawienie tu słowa lub daje możliwość wprowadzenia tych danych np. po 3\\nmiesiącach jeżeli następne zajęcia odbędą się dopiero za 3 miesiące. Nasza propozycja\\nzawęża maksymalny termin wprowadzenia tych danych do 7 dni.\\n\\n l) W odniesieniu do art. 23e ust. 1 pkt 4 proponujemy likwidację dostępu WORD do danych\\numieszczonych w cyfrowej karcie kursanta. W naszej ocenie żadne dane z danych\\numieszczonych w tej karcie nie są WORD potrzebne. WORD potrzebuje wyłącznie danych\\numieszczonych w CEPIK dotyczących zaświadczenia o ukończonym szkoleniu. Możliwość\\ndostępu do pozostałych danych jest dostępem nadmiarowym niepotrzebnym do realizacji\\nzadań WORD.\\n\\n m) W odniesieniu do art. 23e ust. 2 w naszej ocenie trzeba się zdecydować, czy nadal\\nbędziemy mieli do czynienia z profilem kandydata na kierowcę, czy nie. W nowo\\nprzygotowanym przepisie art. 27 ust. 4b dodajemy informację że zaświadczenie o \\f\\n\\nStrona 42 z 219\\n\\nukończeniu szkolenia wystawia się za pomocą wpisania tej informacji do CEPIK. Dotychczas\\nto zaświadczenie wpisywało się poprzez uzupełnienie profilu kandydata na kierowcę (patrz §\\n16 rozporządzenia w sprawie szkolenia osób ubiegających się o uprawnienia do kierowania\\npojazdami). Zatem jeżeli zamierzamy pozostawić profil to warto byłoby przenieść zapis z\\nrozporządzenia do ustawy, lub wprowadzić przepis, że wprowadza się do CEPIK poprzez\\naktualizację profilu kandydata na kierowcę. Takie rozwiązanie rozwieje wątpliwości co do\\nsposobu postępowania i miejsca w systemie cyfrowej karty przeprowadzonych zajęć.\\n\\n Art. 1 pkt 1\\noraz pkt 3\\nprojektu\\nustawy w\\nzakresie  art. 2\\npkt 6 i art. 23b\\nust. 2 ustawy\\no kierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nProponuje się rezygnację z odrębnego „indywidualnego numeru kursanta” generowanego\\nprzez organ właściwy w sprawach wydawania dokumentów stwierdzających uprawnienia.\\nJako identyfikator kursanta powinien być wykorzystywany PESEL, a do czasu utrzymania PKK\\n- numer PKK. Jeżeli z przyczyn technicznych niezbędny jest dodatkowy token/logowanie do\\ncyfrowej karty kursanta, powinien być generowany automatycznie w systemie centralnym\\nlub w aplikacji mObywatel, bez udziału starosty i bez konieczności ponownej wizyty\\nobywatela w urzędzie.\\nUzasadnienie:\\nProjekt w obecnym brzmieniu może oznaczać, że kandydat najpierw uzyska PKK, a następnie\\nbędzie musiał ponownie wystąpić do organu o wygenerowanie indywidualnego numeru\\nkursanta. Takie rozwiązanie dubluje identyfikatory i tworzy dodatkową czynność\\nadministracyjno-techniczną po stronie starostw. Nie jest jasne, dlaczego funkcji\\nidentyfikacyjnej nie może pełnić istniejący numer PKK lub PESEL, skoro dane kursanta,\\nbadania lekarskie, badania psychologiczne i dalsze czynności mają być w praktyce powiązane\\nz jedną osobą.\\n Art. 1 pkt 3\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 3\\nWprowadzono obowiązek rejestracji szkolenia. Zmiana wyrównuje dla wszystkich szkół\\nwarunki prowadzenia szkolenia. Eliminuje szkoły które nierzetelnie prowadzą szkolenie.\\nZ naszego punktu widzenia jest to korzystna zmiana.\\n                               Art. 1 pkt 3 w\\nzakresie art.\\n23c ust. 5\\nustawy o\\nkierujących\\npojazdami\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 3) Art. 23c ust.5\\nJest zapis, że instruktor w przypadku problemów technicznych ma obowiązek\\ndokumentowania szkolenia „ w inny sposób”. W ust. 6 jest obowiązek uzupełnienia danych\\nw cyfrowej karcie kursanta jeszcze przed kolejną jazdą. Proponujemy doprecyzowanie co\\nkonkretnie ma dokumentować instruktor. \\f\\n\\nStrona 43 z 219\\n\\n W późniejszym czasie raczej na pewno nie będzie mógł uzupełnić danych lokalizacyjnych\\npojazdu w odstępie 5 sekund.\\n Art. 1 pkt 1\\noraz pkt 3\\nprojektu\\nustawy w\\nzakresie art. 2\\npkt 7 i art. 23c\\nust. 1 pkt 1 lit.\\nb oraz ust. 2\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nProponuje się rezygnację z odrębnego „indywidualnego numeru instruktora” albo\\njednoznaczne wskazanie, że jest nim numer instruktora w ewidencji instruktorów. W art. 23c\\nust. 1 pkt 1 lit. b i pkt 2 lit. b należy posługiwać się pojęciem „numer w ewidencji\\ninstruktorów”, a nie niejednoznacznym sformułowaniem „numer uprawnień instruktora”.\\nUzasadnienie:\\nNumer instruktora jest już nadawany i ujawniany w ewidencji instruktorów prowadzonej\\nprzez starostę. Wprowadzanie kolejnego numeru identyfikującego tę samą osobę zwiększa\\nryzyko niespójności danych, błędów przy kontroli oraz problemów przy integracji z\\nmLegitymacją instruktora lub innymi dokumentami cyfrowymi. Z perspektywy samorządów\\nracjonalne jest wykorzystanie istniejącego numeru ewidencyjnego, a nie mnożenie\\nidentyfikatorów.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23c ust. 1 pkt\\n1 lit. b ustawy\\no kierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nWe wskazany zapisie prawnym zgodnie z właściwą terminologią nie powinno być „numer\\nuprawnień instruktora” tylko „numer ewidencyjny instruktora”.\\n\\nUzasadnienie:\\nW projekcie użyto błędnej terminologii.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23c ust. 1 pkt\\n1 lit. i oraz pkt\\n2 lit. h ustawy\\no kierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy rozważyć zasadność zapisu mówiącym o wskazaniu liczby przejechanych kilometrów\\nwg wskazań licznika pojazdu.\\n\\nUzasadnienie:\\nJeśli ustawodawca stawia na transparentność to we wskazanym artykule nie powinno się już\\npolegać na wskazaniu licznika pojazdu, który z reguły odczytywany jest przez instruktora\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nUnia Metropolii\\nPolskich im.\\nNależy rozważyć zasadność zapisów stanowiących o wnoszeniu uwag przez osoby ubiegające\\nsię o uzyskanie uprawnienia do kierowania pojazdem silnikowym  dotyczące przebiegu zajęć\\noraz części praktycznej egzaminu wewnętrznego do cyfrowej karty kursanta. \\f\\n\\nStrona 44 z 219\\n\\nzakresie  art.\\n23c ust.1 pkt 1\\nlit. k i art. 23d\\nust. 1 oraz\\nart. 23f pkt 3\\nustawy o\\nkierujących\\npojazdami\\nPawła\\nAdamowicza\\n\\nUzasadnienie:\\nW treści uzasadnienia nie poruszono zasadności wnoszenia uwag przez osoby ubiegającą się\\no uprawnienia do kierowania pojazdem silnikowym dotyczących przebiegu zajęć.\\nWprowadzenie przedmiotowego zapisu dającemu w pewien sposób ingerować osobie\\nszkolonej w proces szkolenia, może skutkować powstaniem pewnego rodzaju nadużyć ze\\nstrony osoby szkolonej poprzez wywieranie presji na instruktora m.in. w przypadku, gdy ten\\nuzna, iż osoba szkolona nie jest jeszcze przygotowana do przystąpienia, do egzaminu\\npaństwowego, a tym samym  winna kontynuować szkolenie. Może to skutkować\\nnieuzasadnionymi skargami na instruktorów.\\n Art. 1 pkt 3\\nprojektu w\\nzakresie art.\\n23d ust. 5\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nW dodanym art. 23d ust. 5 należałoby doprecyzować następującą część zdania: „albo\\ndokumentuje ją w inny sposób wraz z danymi i informacjami”.\\nUzasadnienie:\\nDoprecyzowanie wskazanego zapisu pozwoli uniknąć nieporozumień w trakcie\\nsprawowanego nadzoru przez właściwego starostę nad ośrodkiem szkolenia kierowców\\n Art. 1 pkt 3\\nprojektu w\\nzakresie art.\\n23d ust. 5-7 i\\nart. 23f pkt 4\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\n Należy doprecyzować tryb postępowania w przypadku awarii systemu, braku\\nłączności, błędu aplikacji albo awarii urządzenia lokalizacyjnego. Przepis powinien\\nokreślać: kto dokumentuje awarię, w jakiej formie, czy możliwe jest prowadzenie\\nkolejnych zajęć przed uzupełnieniem danych, jak odróżnić awarię systemową od\\nnaruszenia po stronie OSK oraz kiedy OSK ma obowiązek zgłoszenia problemu\\nstaroście.\\n Należy zdefiniować stwierdzenie tzw.” przyczyn technicznych” i określić precyzyjną\\nprocedurę postępowania w przypadku ich wystąpienia aby uniknąć nadużyć w tym\\nzakresie ze strony podmiotów szkolących.\\n Należy rozważyć uzupełnienie stwierdzenia w proponowanym ustępie 7, np. w\\nsposób:  „następuje niezwłocznie, nie później niż następnego dnia …”\\nKonieczne wydaje się również zdefiniowanie sankcji za brak realizacji tego obowiązku.\\nUzasadnienie: \\f\\n\\nStrona 45 z 219\\n\\n Obecne przepisy wskazują terminy późniejszego wprowadzenia danych, ale nie\\ntworzą pełnej procedury awaryjnej. W praktyce może to prowadzić do masowego\\nkierowania do starostów zgłoszeń o problemach technicznych, także wtedy, gdy\\nproblem leży po stronie systemu centralnego lub aplikacji. Należy uniknąć sytuacji, w\\nktórej starosta staje się adresatem zgłoszeń technicznych bez narzędzi do ich\\nweryfikacji i usunięcia.\\n Obecna propozycja tej regulacji umożliwia w każdym przypadku zastosowanie przez\\npodmiot szkolący wytłumaczenia w postaci wystąpienia trudności o charakterze\\ntechnicznym, co w przypadku świadomych nadużyć i nieprawidłowości uniemożliwi\\norganom nadzorującym szkolenie ich stwierdzenie.\\n Określenie „niezwłocznie” pozostawia zbyt wiele pola do nadinterpretacji tego\\nterminu.\\n Brak ustawowej odpowiedzialności spowoduje, że regulacja będzie „martwą”.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23d ust. 6\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nWe wskazanym zapisie zasadnym byłoby zastąpienie jego drugiej części, tj. cyt,: „(…) lub\\nprzed rozpoczęciem kolejnych zajęć z osobą szkoloną.”, zapisem zawartym w ust. 7, w\\nktórym mówi się o wprowadzeniu danych, cyt. „(…) niezwłocznie po ustaniu przyczyny\\nuniemożliwiającej ich wprowadzenie.”\\nUzasadnienie:\\nWskazana propozycja zmiany nie ograniczałaby kursanta do wstrzymania procesu szkolenia,\\nw przypadku nie usunięcia usterki uniemożliwiającej potwierdzenie przez instruktora\\nprzebiegu szkolenia w zakresie nauki jazdy w cyfrowej karcie kursanta przed kolejnym\\nzajęciami praktycznymi.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23f ustawy o\\nkierujących\\npojazdami\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\n\\nWyposażanie pojazdów szkoleniowych w urządzenia mające wysyłać informacje o trasie w\\npostaci plików GPX to dodatkowe obciążenie przedsiębiorcy prowadzącego szkolenie.\\nUrządzenie takie będzie musiało nie tylko współpracować z zewnętrznym systemem, które\\nzasad działania (technicznych) nie znamy, ale również będzie musiało mieć stałą łączność z\\nsiecią Internet, co w wielu miejscach może być niemożliwe.\\n \\f\\n\\nStrona 46 z 219\\n\\nPojazdy nauki jazdy (w szczególności pojazdu osobowe) bardzo często wykorzystywane są\\nprzez właścicieli również do użytku prywatnego, zatem nieustanne wysyłanie informacji o\\nlokalizacji pojazdu lub przebytych trasach nie powinno mieć miejsca.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23e, art. 23g\\noraz art. 23j\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy jednoznacznie określić zakres dostępu do danych cyfrowej karty kursanta, danych\\nlokalizacyjnych i nagrań dla wszystkich podmiotów wykonujących realne czynności\\nnadzorcze, w tym starosty nadzorującego OSK, kuratora oświaty w odniesieniu do szkół,\\nwłaściwych podmiotów resortowych w odniesieniu do szkoleń szczególnych oraz Policji\\ndziałającej na podstawie porozumień ze starostą. Jednocześnie należy przesądzić, czy projekt\\nrozszerza zakres nadzoru starosty nad podmiotami, które dotychczas pozostawały poza jego\\nbezpośrednią właściwością.\\n\\nUzasadnienie:\\nZ projektu wynika znaczne wzmocnienie narzędzi nadzoru nad szkoleniem, ale nie jest jasne,\\nczy dostęp do danych odpowiada rzeczywistemu podziałowi kompetencji. Starosta\\nprowadzący ewidencję instruktorów ma być pozbawiony dostępu do danych lokalizacyjnych,\\na jednocześnie projekt nakłada na OSK obowiązki, których kontrola może wymagać analizy\\ntrasy, czasu i przebiegu jazd. W praktyce nadzór nad OSK jest często wykonywany przy\\nwspółpracy z Policją. Brak dostępu lub niepełny dostęp podmiotów kontrolujących może\\nuczynić nowe obowiązki nieweryfikowalnymi.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23e ust. 2\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy doprecyzować, w jaki sposób podmioty wymienione w art. 23e ust. 1 będą uzyskiwać\\ndostęp do danych cyfrowej karty kursanta, jeżeli PKK zostanie zastąpione albo ograniczone\\nw wyniku innych projektów cyfryzacyjnych. Przepis powinien odwoływać się do docelowego\\nidentyfikatora i systemu centralnego, a nie wyłącznie do profilu kandydata na kierowcę.\\n\\nUzasadnienie:\\nProjekt jednocześnie tworzy indywidualny numer kursanta i przewiduje dostęp do danych\\nprzy użyciu PKK. Powstaje pytanie, jaka jest funkcja nowego numeru, skoro dostęp organów\\nma następować przez PKK. Brak spójności może prowadzić do sytuacji, w której organy i OSK\\nbędą obsługiwały równolegle kilka identyfikatorów, co utrudni kontrolę, obsługę\\ncudzoziemców i migrację danych do systemu opartego na PESEL.\\n Art. 1 pkt 3\\nprojektu\\nUnia Metropolii\\nPolskich im. W zapisie zawartym w projekcie należy rozważyć czy po wyrazach, cyt. „w ciągu 7 dni”, nie\\nbyłoby zasadnym dodać  zapis o treści, cyt.” lub niezwłocznie po ustaniu przyczyn \\f\\n\\nStrona 47 z 219\\n\\nustawy w\\nzakresie art.\\n23f pkt 4\\nustawy o\\nkierujących\\npojazdami\\nPawła\\nAdamowicza\\nuniemożliwiających ich wprowadzenie. Jednocześnie należałoby doprecyzować formę\\ninformacji przekazywanej przez ośrodek szkolenia kierowców właściwemu staroście.\\nNależy rozważyć określenie precyzyjnego terminu zgłaszania staroście faktu braku\\nmożliwości wprowadzenia lub potwierdzenia danych i informacji dotyczących przebiegu\\nszkolenia lub części praktycznej egzaminu wewnętrznego w cyfrowej karcie kursanta,\\npoprzez zastosowanie stwierdzenia np. niezwłocznie, nie później niż następnego dnia …\\n\\nUzasadnienie:\\nProponowana zmiana (w pierwszym zdaniu) jest powiązana z treścią uwagi zawartej w pkt 8\\nniniejszej tabeli. Wskazanie jednoznacznej formy przekazania przedmiotowej informacji\\nbędzie miało na celu jasny sposób komunikacji między ośrodkiem szkolenia kierowców a\\nwłaściwym starostą.\\n\\nBrak precyzyjnego wskazania terminu zgłaszania staroście tego faktu pozostawia ośrodkom\\nszkolenia pełną dowolność w realizacji tego obowiązku, a co za tym idzie nieskuteczność\\nnadzoru w tym obszarze.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23g ust. 1\\nustawy o\\nkierujących\\npojazdami\\nPolska\\nWytwórnia\\nPapierów\\nWartościowych\\nS.A.\\nW konsekwencji przyjęcia uwagi zawartej w poz. 1, administratorem danych osobowych\\nzarejestrowanych\\nw cyfrowej karcie kursanta będzie organ właściwy do spraw wydawania dokumentów\\nstwierdzających uprawnienia do kierowania pojazdami, który wygenerował tę kartę.\\n\\nProjektowane brzmienie art. 23g ust. 1 ustawy powinno otrzymać brzmienie:\\n\\n„1. Administratorem danych osobowych zarejestrowanych w cyfrowej karcie kursanta\\nw zakresie wydanej karty jest organ właściwy do spraw wydawania dokumentów\\nstwierdzających uprawnienia do kierowania pojazdami, który wygenerował tę kartę.”.\\n\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie  art.\\n23g  ust. 3\\nLiga Obrony\\nKraju\\n4. W Art. 1 zmiana 3) Art. 23g ust.3\\nJest zapis, że „Dane lokalizacyjne w formacie GPX ... przetwarza się wyłącznie w celu\\nweryfikacji przebiegu jazd w trakcie zajęć”.\\nNiestety uprawnione organy wg obecnych i proponowanych przepisów w zasadzie mogą\\ntylko sprawdzać czy położenie pojazdu było rejestrowane i jaki był czas szkolenia. \\f\\n\\nStrona 48 z 219\\n\\nPrzepisy regulują tylko egzaminy i kilka godzin szkolenia poza obszarem zabudowanym. Dla\\npozostałych godzin szkolenia instruktor w praktyce ma pełną dowolność gdzie i ile\\njeździ. Organy uprawnione nie mają podstawy, normy aby zakwestionować np. ilość\\nprzejechanych kilometrów, czy trasę przejazdu. Rejestracja czasu szkolenia też może rodzić\\nspory. Liga Obrony Kraju od wielu lat korzysta z urządzeń lokalizujących pojazdy. Z naszego\\ndoświadczenia wiemy, że żaden pojazd nie jeździ 60 minut w trakcie jednej godziny\\nszkoleniowej. Od sprawdzenia pojazdu przed jazdą, zajęcia miejsca,\\ndopasowania fotela, lusterek do uruchomienia silnika i jazdy mija troszkę czasu. Po\\nzakończonej jeździe trzeba też wypełnić dokumenty. Realnie z godziny szkolenia pozostaje\\nnp. 50 min kiedy pojazd jeździ. Jeśli nie ma obowiązujących norm, to ww.\\nprzypadku złośliwy urzędnik będzie mógł stwierdzić uchybienie i w konsekwencji będzie\\nmógł zamknąć ośrodek. Ocena, weryfikacja prawidłowości szkolenia nie powinna opierać się\\ntylko na niemierzalnej ocenie, poglądach kontrolującego urzędnika, który nie zawsze ma\\npotrzebne kompetencje. Zbieranie danych lokalizacyjnych jeśli dalej praktycznie nie będą\\nmogły być wykorzystane narusza zasady RODO. Może być\\nzakwestionowane praktycznie przez każdego kursanta. Jeśli zastrzeżenia podzieli Prezes\\nUrzędu Ochrony Danych Osobowych to ośrodki szkolenia jako administratorzy danych\\nosobowych będą miały problem.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23h ust. 3\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy przeanalizować czy zapis wskazanego artykułu nie jest zbyt szeroki, gdyż w jego treści\\nwskazano, że urządzenie techniczne służące do zapisu obrazu i dźwięku przebiegu części\\npraktycznej egzaminu wewnętrznego winno odpowiadać warunkom określonym w\\nprzepisach wydanych na podstawie art. 66 ust. 1 pkt 1-5, 7 i 8. Tym samym należy rozważyć\\nczy wskazanego zapisu nie ograniczyć do art. 66 ust. 1 pkt 1, pkt 4 lit. a, lit. c i  lit. d oraz pkt\\n5.\\n\\nUzasadnienie:\\nPropozycja zmiany ma na celu uszczegółowienie projektu przedstawionego zapisu\\n Art. 1 pkt 3 i 4\\nprojektu\\nustawy w\\nzakresie art.\\n23f pkt 1, art.\\n23h oraz art.\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy doprecyzować, czy urządzenie lokalizacyjne oraz urządzenie do rejestracji obrazu i\\ndźwięku mają stanowić obowiązkowe wyposażenie każdego pojazdu wykorzystywanego do\\nnauki jazdy albo egzaminu wewnętrznego, czy wystarczy zapewnienie przez OSK\\nokreślonego sposobu rejestracji. W projekcie lub w delegacji do aktu wykonawczego należy\\nwskazać minimalne wymagania techniczne oraz sposób weryfikacji sprawności tych \\f\\n\\nStrona 49 z 219\\n\\n24 pkt 1 lit. e\\nustawy o\\nkierujących\\npojazdami\\nurządzeń, w tym rozważyć powiązanie z dodatkowym badaniem technicznym pojazdu nauki\\njazdy.\\n\\nUzasadnienie:\\nW obecnym brzmieniu projekt przewiduje obowiązki GPS i nagrywania egzaminu\\nwewnętrznego, ale nie przesądza, jak organy mają sprawdzać, czy pojazd „L” faktycznie jest\\nwyposażony w wymagane urządzenia i czy są one sprawne. Powstaje też wątpliwość, czy\\nkamery mają być zamontowane w każdym pojeździe szkoleniowym, czy tylko w pojeździe\\nużywanym do egzaminu wewnętrznego. Brak takich regulacji może powodować różną\\npraktykę kontrolną w powiatach oraz spory z OSK.\\n\\n Art. 1 pkt 3 w\\nzakresie art.\\n23f ustawy o\\nkierujących\\npojazdami\\nPolski Związek\\nSzkoleniowy\\n19) Proponujemy także wprowadzenie odrębnej delegacja ustawowa dla ustalenia zasad i\\nsposobu prowadzenia rejestracji GPS (zasady, dane gromadzone, wykorzystywane systemy\\nitp.) co znacznie ułatwi bieżące dostosowanie systemów.\\n\\n Art. 1 pkt 3 i 5\\nprojektu\\nustawy w\\nzakresie art.\\n23j oraz art.\\n27 ust. 1 pkt 7\\ni ust. 2 pkt 6\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy wydłużyć albo elastycznie ukształtować okres przechowywania nagrań z części\\npraktycznej egzaminu wewnętrznego. Co najmniej należy wprowadzić obowiązek\\nzabezpieczenia nagrania na żądanie organu nadzoru lub po zgłoszeniu zastrzeżeń przez\\nkursanta przed upływem 90 dni. Alternatywnie należy rozważyć przechowywanie nagrań\\nprzez okres umożliwiający wykorzystanie ich w ramach okresowej kontroli OSK.\\n\\nUzasadnienie:\\nProjekt przewiduje 90-dniowy okres przechowywania nagrania, podczas gdy kontrole OSK są\\nco do zasady prowadzone okresowo, a informacja o nieprawidłowościach może ujawnić się\\npo upływie tego terminu. Jeżeli nagranie ma być realnym narzędziem dowodowym dla\\norganu nadzoru, system musi zapewniać możliwość jego zabezpieczenia i wykorzystania\\ntakże wtedy, gdy sprawa nie zostanie wykryta natychmiast po egzaminie wewnętrznym.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy przeanalizować zasadność przechowywania zapisu przebiegu części praktycznej\\negzaminu wewnętrznego przez okres 90 dni. Należałoby zastąpić wskazany okres\\nsformułowaniem: od dnia przeprowadzenia kompleksowej kontroli ośrodka szkolenia\\nkierowców do dnia zakończenia kolejnej kontroli kompleksowej tego ośrodka. \\f\\n\\nStrona 50 z 219\\n\\n23j ust. 1\\nustawy o\\nkierujących\\npojazdami\\n\\nUzasadnienie:\\nPropozycja zmiany przedstawionego zapisu jest podyktowana tym, iż w wielu przypadkach\\nczynności kontrolne organu nadzoru przeprowadzane są nawet po 12 miesiącach, licząc od\\npoprzedniej kontroli.\\n Art. 1 pkt 3\\nprojektu\\nustawy w\\nzakresie art.\\n23j ust. 4\\nustawy o\\nkierujących\\npojazdami\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 3) Art. 23j ust.4\\nDotyczy udostępnienia nagrania z egzaminu. Regulacja w zasadzie powtarza prawo\\nwynikające z Art. 15 ust. 3 rozporządzenia RODO czyli ustęp w obecnej treści może być\\npominięty. Art. 15 ust. 4 rozporządzenia RODO pozwala  przekazać kopię ale tylko w sposób\\nnie naruszający praw innych osób. Przeciętny ośrodek nie ma możliwości usunięcia z\\nnagrania wizji i dźwięku tylko danych osób trzecich. Proponujemy zamiast\\nobecnej treści ustępu wpisać regulację, która ograniczy prawo kursanta do dalszego\\ndysponowania otrzymanym nagraniem. Kursant również nie powinien mieć prawa do\\nkorzystania z nagrania w celach reklamowych, promocyjnych, komercyjnych itd. Ogólnie w\\nsposób naruszający dobro osób trzecich.\\n Art. 1 pkt 4\\nprojektu\\nustawy\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n• Ad. art. 1 pkt 4 projektu\\nZaproponowana zmiany art. 24 pkt 1 lit. d UoKP ma charakter nadmiarowy (i jako taki\\nzbędny). Zakres dodatkowego wyposażenia pojazdu przeznaczonego do prowadzenia nauki\\njazdy reguluje, wydane na podstawie art. 66 ust. 5 ustawy z dnia 20 czerwca 1997 r. – Prawo\\no ruchu drogowym, rozporządzenie Ministra Infrastruktury w sprawie warunków\\ntechnicznych pojazdów oraz zakresu ich niezbędnego wyposażenia z dnia 31 grudnia 2002 r.,\\na konkretnie § 43 tego rozporządzenia. Dlatego tez to właśnie w tym akcie wykonawczym\\nnależałoby ewentualnie wprowadzić odpowiednie zmiany wprowadzające odpowiednie\\nurządzenie geolokalizacyjne, jako obowiązkowe wyposażenie pojazdu przeznaczonego do\\nszkolenia.\\nJednocześnie w przypadku pozostawienia koncepcji „cyfrowej karty kursanta” i\\nwprowadzenia odpowiednich zmian w ww. rozporządzeniu, należałoby – w opinii TLP –\\nzapewnić możliwość alternatywnego używania smartfona lub tabletu, jako urządzenia\\ngeolokalizacyjnego. Takie rozwiązanie stosowane jest w wielu polskich systemach\\nteleinformatycznych, gdzie potrzebne jest śledzenie trasy pojazdu. Przykładem może być\\nsystem SENT lub system e-toll, gdzie wykorzystywana jest bezpłatna aplikacja „e-toll”. Jeśli\\ndla celo w zabezpieczenia wpływów z akcyzy i podatku VAT, dopuszcza się taką alternatywę, \\f\\n\\nStrona 51 z 219\\n\\nto nie istnieje jakakolwiek, racjonalna przesłanka, która mogłaby uniemożliwić takie\\nrozwiązanie w znacznie mniej istotnym z punktu widzenia interesów państwa systemie.\\nOdnosząc się do przepisu art. 24 UoKP, stanowiącego o pojazdach używanych w trakcie zajęć\\npraktycznych, postulujemy wprowadzenie możliwości przeprowadzania części zajęć na\\npojazdach innych niż te, kto re wskazane są w pkt 1 lit. c. Jako przykład można tutaj wskazać\\nszkolenie w zakresie prawa jazdy kategorii C+E, gdzie zgodnie z postulatami branży\\ntransportowej, wprowadzono obligatoryjne szkolenie z wykorzystaniem ciągnika siodłowego\\ni naczepy. Podtrzymujemy pełne poparcie dla tego rozwiązania, niemniej chcielibyśmy\\nusunąć barierę dla fakultatywnego przeprowadzania części zajęć praktycznych na tzw.\\ntandemie (samochodzie ciężarowym z przyczepą). Np. w przypadku, gdy uczestnik kursu jest\\nszkolony na\\npotrzeby konkretnego przedsiębiorstwa. W wyniku takiego hybrydowego szkolenia, przyszły\\nkierowca uzyska nie tylko obligatoryjne kwalifikacje w kierowaniu dominującym w\\nprzewozach rzeczy zestawem (ciągnik + naczepa), ale także uzyska umiejętność kierowania\\nww. tzw. tandemem.\\nDlatego tez proponujemy w art. 24 UoKP dotychczasową treść oznaczyć jako ust. 1 i dodać\\nust. 2 w brzmieniu:\\n„2. Część zajęć praktycznych w ramach nauki jazdy może być prowadzona pojazdami\\nodpowiadającymi kategorii prawa jazdy w zakresie której prowadzone jest szkolenie, innymi\\nniż pojazdy wskazane w ust. 1 pkt 1 lit. c.”\\n Art. 1 pkt 4\\nprojektu\\nustawy\\n\\nPolski Związek\\nSzkoleniowy\\nW odniesieniu do art. 1 w pkt 4 w proponowanym przepisie zawarto obowiązek\\nwyposażenia pojazdów do nauki jazdy w urządzenie lokalizacyjne o którym mowa w art. 23f\\npkt 1. Z tym że w art. 23f pkt 1 jest także mowa o aplikacji mobilnej zintegrowanej z cyfrową\\nkartą kursanta. W naszej ocenie w proponowanym przepisie zabrakło wyłączenie\\nodnoszącego się do tej aplikacji. Proponujemy następujące rozwiązanie:\\n\\n„e) wyposażonym w urządzenie lokalizacyjne, o którym mowa w art. 23f pkt 1 – w zakresie\\nszkolenia osób ubiegających się o uzyskanie uprawnienia do kierowania pojazdem\\nsilnikowym\\n– nie dotyczy pojazdów w których podczas szkolenia wykorzystuje się aplikację mobilną\\nzintegrowaną z cyfrową kartą kursanta zapewniającą możliwości rejestrowania trasy jazdy;”; \\f\\n\\nStrona 52 z 219\\n\\n Art. 1 pkt 4\\nprojektu\\nustawy\\n\\nOIGOSK,\\nLFEDERACJA,\\nPIGOSK\\npkt.4 wykreślić\\n4) w art. 24 w pkt 1 w lit. d średnik zastępuje się przecinkiem i dodaje się lit. e w brzmieniu:\\n„e) wyposażonym w urządzenie lokalizacyjne, o którym mowa w art. 23f pkt 1 – w zakresie\\nszkolenia osób ubiegających się o uzyskanie uprawnienia do kierowania pojazdem\\nsilnikowym;”; Uzasadnienie Vide uzasadnienie do pkt.1 powyżej 3.\\n Art. 1 pkt 5\\nprojektu\\nustawy w\\nzakresie art.\\n27 ust. 1\\nustawy o\\nkierujących\\npojazdami\\n\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nW dodanym pkt 7 do art. 27 ust. 1 właściwym winno być: plik z nagraniem, o którym mowa\\nw art. 23h ust. 5, a nie jak zapisano w projekcie art. 23h ust. 4.\\nUzasadnienie:\\nZapis, o którym mowa wydaje się być oczywistą omyłką pisarską.\\n Art. 1 pkt 5 lit.\\na projektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\nW odniesieniu do art. 1 w pkt 5 w lit. a w proponowanym pkt 7 jest błędne odesłanie\\nzamiast art. 23h ust. 4 powinno być ust. 5.\\n\\n Art. 1 pkt 5\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 5) c) i 5) d)\\nPrzenosi dokumentację szkoleniową z wersji papierowej do wersji elektronicznej.\\nZgodnie z treścią proponowanego art. 23b. cały przebieg szkolenia i części praktycznej\\negzaminu wewnętrznego będzie rejestrowany elektronicznie. Czy w tej sytuacji zasadnym\\njest prowadzenie nawet w wersji elektronicznej np. Karty przeprowadzonych zajęć ?.\\nUważamy, że przy tak znaczącej zmianie w prowadzeniu dokumentacji szkoleniowej\\nkonieczne jest jak najszybsze opublikowanie nowej wersji obecnego\\nRozporządzenia Ministra Infrastruktury i Budownictwa w sprawie szkolenia osób\\nubiegających się o uprawnienia do kierowania pojazdami w którym określone zostaną\\ndokumenty ich wzory jakie będą obowiązywać po proponowanych zmianach.\\nBez aktualizacji tego rozporządzenia od 01.01.2027r. będziemy mieli chaos. Dokumenty\\nbędą dublować się wzajemnie np. cyfrowa karta kursanta i karta przeprowadzonych\\nzajęć. Rozporządzenie można wydać dopiero po uchwaleniu przez Sejm poprawionej ustawy.\\nCzyli na uchwalenie i opublikowanie nowego rozporządzenia nie będzie zbyt\\nwiele czasu jeśli zmiany miały by wejść od początku roku. \\f\\n\\nStrona 53 z 219\\n\\n Art. 1 pkt 6\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 6) Art. 28 po ust. 2 dodaje się ust. 2a.\\nZe względów wyżej wymienionych w pkt. 1 proponujemy wykreślić tą zmianę.\\nUważamy, że ośrodek szkolący tylko na kat. B i B1 też powinien dysponować placem\\nmanewrowym.\\n Art. 1 pkt 6\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nPracodawców\\nTransportu\\nDrogowego\\nPrzesłany projekt jest realizacją wcześniej zapowiadanych zmian w szkoleniu i\\negzaminowaniu kierowców oraz procesie uzyskiwania uprawnień do kierowania pojazdami.\\nAnaliza projektu wskazuje jednak, że jest on daleki od oczekiwań branży transportu\\ndrogowego, ponieważ proponowane zmiany tylko w niewielkim stopniu odnoszą się do\\njakości szkolenia oraz oczekiwanego efektu w postaci niezbędnej wiedzy i umiejętności\\nprzyszłych kierowców, którzy już jako kierujący maja bezpośredni wpływ na bezpieczeństwo\\nruchu drogowego.\\nNiektóre proponowane zmiany w naszej ocenie mogą pogarszać jakość szkolenia i tym\\nsamym tworzyć nowe ryzyka wynikające z uczestnictwa tych osób w ruchu drogowym.\\nZniesienie obowiązku posiadania placu manewrowego przez ośrodki szkolenia prowadzące\\nkursy na ktg prawa jazdy B i B1 przyczyni się do rozwoju ośrodków bez jakiejkolwiek\\ninfrastruktury, a osoba szkolona bez podstawowych umiejętności będzie uczestniczyć w\\nruchu drogowym. Znając rynek szkoleń oceniamy, że szkolenie wstępne pozwalające nabyć\\numiejętności panowania nad pojazdem oraz wykonywania podstawowych manewrów jazda\\npo prostej i po łuku do przodu lub cofając (manewry wymagane dyrektywą 2205/2025)\\nprzeniesie się na ulice o niskim natężeniu ruchu (gorzej w dużych miastach) oraz parkingi\\nprzy marketach skąd pojazdy z „L” są „wypychane” przez właścicieli terenów. To nie poprawi\\njakości szkolenia szczególności w początkowym okresie.\\n Art. 1 pkt 6\\nprojektu\\nustawy\\nFundacja\\nZapobiegania\\nWypadkom\\nDrogowym\\nW  kwestii usunięcia z programu szkolenia kandydatów na kierowców obowiązkowych zajęć\\nna placu manewrowym stoimy na stanowisku, że o ile słuszna i uzasadniona jest rezygnacja z\\nczęści egzaminu na prawo jazdy na placu manewrowym, o tyle „uwolnienie” i przeniesienie\\ntych elementów szkolenia do ruchu drogowego i przestrzeni publicznej przyniesie liczne\\nszkody, zagrożenia i konflikty. Wiele argumentów uzasadniających to stanowisko było w\\nostatnich tygodniach prezentowanych podczas spotkań przedstawicieli branży, w mediach,\\ntakże w realizowanej przez nas audycji „Dyskusja na Ratuszowej”. Postulujemy zatem\\npozostawienie placu manewrowego jako obowiązkowego elementu szkolenia w OSK.\\n \\f\\n\\nStrona 54 z 219\\n\\n Art. 1 pkt 6\\nprojektu\\nustawy\\nZwiązek\\nPracodawców\\n‘Transport i\\nLogistyka\\nPolska”\\n1. Ad. art. 1 pkt 6 projektu\\nArt. 1 pkt 6 projektu, wprowadza zmiany w art. 28 ust. 2a UoKP, kto re wyłączają wymóg\\nposiadania placu manewrowego dla ośrodka szkolenia kierowców prowadzącego szkolenie\\nw zakresie prawa jazdy kategorii B1 i B.\\nNawiązując do uwag zgłoszonych do przepisu art. 1 pkt 2 projektu, proponujemy\\nalternatywne rozwiązanie dotyczące wszystkich kategorii prawa jazdy, polegające na tym, z e\\nod przedsiębiorcy wymaga się posiadania tytułu prawnego zapewniającego możliwość\\nprzeprowadzania części zajęć praktycznych w zakresie panowania nad pojazdem w miejscu\\n(placu) zabezpieczonym, w trakcie przeprowadzania zajęć , przed dostępem oso b\\npostronnych.\\nDlatego też proponujemy w art. 28 UoKP:\\n• uchylenie przepisu ust. 2 pkt 1 lit. c,\\n• dodanie w ust. 2 pkt 1a w brzmieniu:\\n\\n„1a. Dysponuje możliwością prowadzenia w ramach nauki jazdy, zajęć praktycznych na\\nmiejscu (placu), zabezpieczonym przed dostępem osób trzecich, w trakcie przeprowadzania\\ntych zajęć.”.\\nKonsekwentnie proponujemy skreślenie propozycji nowego ust. 2a w art. 28 UoKP.\\n Art. 1 pkt 6\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\nW odniesieniu do art. 1 pkt 6 w naszej ocenie pomimo likwidacji na egzaminie państwowym\\nzadań realizowanych na placu manewrowym to w przypadku prowadzenia ośrodka szkolenia\\nkierowców plac ten powinien pozostać. Nie musza to być tak jak dotychczas zadania\\negzaminacyjne ale mimo wszystko powinien to być plac pozwalający na wykonanie\\npodstawowych manewrów takich jak nauka ruszania, podstawowa nauka ruszania,\\nhamowania, jazdy w przód i tył, obsługi pojazdu czy przygotowania do jazdy. Są to czynności\\nniezbędne do nauczenia w bezpiecznych warunkach a nie w ruchu drogowym. Zatem każdy\\nOSK powinien mieć taką przestrzeń przygotowaną dla kandydatów na kierowców\\nrozpoczynających swoją przygodę z prawem jazdy. W naszej ocenie taki optymalny plac to\\nokoło 10 m na 30 m czyli około 300 m2. Dzisiejszy podstawowy plac manewrowy dla OSK\\nprowadzących szkolenie w zakresie prawa jazdy kategorii B to co najmniej 550 m2. Zatem\\n300 m2 to obniżenie wymagań dla OSK, ale bez likwidacji bezpiecznej przestrzeni\\nszkoleniowej.\\nPlac manewrowy jest jedynym miejscem umożliwiającym bezpieczne wykonywanie przez\\nkursanta pierwszych samodzielnych czynności związanych z prowadzeniem pojazdu.  \\f\\n\\nStrona 55 z 219\\n\\nNa placu kursant nabywa podstawowe umiejętności obejmujące:\\n· ruszanie i zatrzymywanie pojazdu,\\n· płynne operowanie sprzęgłem i skrzynią biegów,\\n· utrzymanie właściwego toru jazdy,\\n· kontrolę pojazdu przy bardzo małych prędkościach,\\n· ocenę gabarytów pojazdu,\\n· jazdę z wykorzystaniem biegu wstecznego,\\n· wykonywanie podstawowych manewrów.\\nDopiero po opanowaniu tych czynności możliwe jest bezpieczne rozpoczęcie szkolenia w\\nruchu drogowym.\\nSamodzielna jazda kursanta może odbywać się wyłącznie na placu manewrowym.\\nSzczególną rolę plac manewrowy pełni w zakresie wykonywania przez kursanta\\nsamodzielnych manewrów.\\nWyłącznie na placu możliwe jest stworzenie warunków, w których instruktor może czasowo\\nopuścić pojazd, obserwować wykonywany manewr z zewnątrz oraz ocenić:\\n· sposób prowadzenia pojazdu,\\n· rzeczywisty tor jazdy,\\n· zachowanie odpowiednich odległości,\\n· prawidłowość obserwacji otoczenia,\\n· ocenę gabarytów pojazdu,\\n· samodzielność podejmowanych decyzji.\\nTakiej formy szkolenia nie można przenieść do ruchu drogowego.\\nInstruktor prowadzący szkolenie na drodze publicznej ma obowiązek sprawowania\\nbezpośredniego nadzoru nad przebiegiem jazdy i zapewnienia bezpieczeństwa uczestnikom\\nruchu. Opuszczenie pojazdu oraz pozostawienie kursanta wykonującego samodzielnie\\nmanewry na drodze publicznej byłoby niedopuszczalne zarówno z punktu widzenia\\nbezpieczeństwa, jak i odpowiedzialności instruktora.\\nOznacza to, że po likwidacji obowiązku zapewnienia placu manewrowego kursanci zostaliby\\ncałkowicie pozbawieni możliwości wykonywania samodzielnych ćwiczeń pod nadzorem\\ninstruktora prowadzonym z zewnętrznej obserwacji.\\nByłaby to istotna utrata jakości procesu szkolenia, której projekt nie identyfikuje ani nie\\nrekompensuje.\\n \\f\\n\\nStrona 56 z 219\\n\\nJeżeli jednak pozostaniemy przy braku wymagania placu manewrowego w przypadku OSK\\nprowadzących szkolenie w zakresie prawa jazdy B to w art. 31 ust. 1 należy rozważyć\\npodjęcie tych samych działań w stosunku do OSK spełniających dodatkowe wymagania.\\nJeżeli nie dal wszystkich OSK to opisany w pkt 7 plac powinien być wymagany przy OSK\\nspełniającym dodatkowe wymagania w zakresie prawa jazdy kategorii B. Jednak trzeba\\npamiętać, że trzeba określić wielkość placu.\\n\\n Art. 1 pkt 6\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n6) w art. 28 po ust. 2 dodaje się ust. 2a w brzmieniu:\\n\\n„2a. Wymogu posiadania placu manewrowego, o którym mowa w ust. 2 pkt 1 lit. c,\\nnie stosuje się do ośrodka szkolenia kierowców prowadzącego szkolenie w zakresie\\nuprawnień kategorii B lub B1.”;\\n\\nJesteśmy za utrzymaniem placu manewrowego w szkoleniu i egzaminowaniu w obecnej\\nformie.\\n\\nArt. 1 pkt 7\\nprojektu\\nustawy\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n1. Ad. art. 1 pkt 7 projektu\\nArt. 1 pkt 7 lit. a-c projektu wprowadza zmiany w art. 33 UoKP ustanawiające nowe\\nwymagania wobec instruktorów prowadzących szkolenie. Nie negując potrzeby zmian, TLP\\nnie znajduje merytorycznego uzasadnienia, opartego na przykładach dobrej praktyki z innych\\npaństw lub opartego na wynikach badań, do wprowadzania, po pierwsze wymogu co\\nnajmniej wykształcenia średniego lub średniego branżowego dla instruktorów i\\nwykładowców, a po drugie, dla podwyższenia wymaganego czasu posiadania prawa jazdy\\nodpowiedniej kategorii z 2 do 3 lat.\\nW ocenie TLP, miarą oceny kwalifikacji, w tym przygotowania zawodowego instruktorów i\\nwykładowco w, powinno być doświadczenie oraz prezentowane umiejętności a nie\\nformalny, niezwiązany z wykonywanymi zadaniami, poziom wykształcenia oraz okres\\nposiadania kategorii prawa jazdy. Okresu posiadania prawa jazdy nie powinno się\\nutożsamiać z okresem fizycznej jazdy pojazdem. W tym zakresie, w ocenie TLP, niezbędne są\\nkonkretne dane, wynikające z profesjonalnych analiz umiejętności i kwalifikacji osób,\\nwykładających na kursach oraz oso b przygotowujących kursantów do bezpiecznej jazdy po\\ndrogach.  \\f\\n\\nStrona 57 z 219\\n\\nJednocześnie, TLP wskazuje na potrzebę odpowiedniego uregulowania kompetencji\\ninstruktorów prowadzących szkolenia w zakresie wyższych kategorii prawa jazdy, zgodnie ze\\nwskazaną na wstępie propozycją nr 2.\\n Art. 1 pkt 7\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 7 – proponujemy warunek 5 lat posiadanego uprawnienia do kierowania wz.\\nuprawnień instruktora oraz wprowadzenie obowiązku rocznego stażu zakończonego oceną\\nwarunkującą przedłużenie ważności uprawnień na kolejne 3 lata. Po tych dwóch okresach\\ninstruktor mógłby ubiegać się o Certyfikat instruktora nauki jazdy ważny przez kolejne 5 lat.\\nSzczegółowe warunki realizacji powyższych wymagań należałoby określić w odpowiednim\\nrozporządzeniu.\\n\\n Art. 1 pkt 7\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n7) w art. 33:\\na) w ust. 1 po pkt 1 dodaje się pkt 1a w brzmieniu:\\n„1a) posiada co najmniej wykształcenie średnie lub średnie branżowe;”,\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nW związku z proponowanym przywróceniem wymogu posiadania co najmniej wykształcenia\\nśredniego lub średniego branżowego przez instruktora nauki jazdy, Krajowe Stowarzyszenie\\nEgzaminatorów proponuje równoczesną zmianę art. 58 ust. 1 pkt 1 ustawy , poprzez\\nprzywrócenie wymogu posiadania wykształcenia wyższego przez osobę ubiegającą się o\\nuprawnienia egzaminatora.\\nW naszej ocenie wymagania stawiane kandydatom na egzaminatorów powinny odpowiadać\\ncharakterowi, randze oraz zakresowi odpowiedzialności związanej z wykonywaniem tego\\nzawodu. Egzaminator nie zajmuje się wyłącznie oceną techniki kierowania pojazdem. Do jego\\nobowiązków należy dokonywanie obiektywnej oceny kwalifikacji osoby egzaminowanej,\\nprawidłowe stosowanie przepisów prawa, właściwa kwalifikacja zachowań osoby\\negzaminowanej, podejmowanie decyzji mających bezpośredni wpływ na wynik egzaminu, a\\ntakże jasne i merytoryczne uzasadnianie podejmowanych rozstrzygnięć. \\f\\n\\nStrona 58 z 219\\n\\nWykonywanie zawodu egzaminatora wymaga zatem nie tylko odpowiedniej wiedzy z zakresu\\nprzepisów ruchu drogowego i techniki kierowania pojazdem, lecz również rozwiniętych\\nkompetencji w zakresie logicznego formułowania wypowiedzi, argumentowania\\npodejmowanych decyzji, interpretacji i stosowania przepisów oraz komunikowania osobie\\negzaminowanej przyczyn uzyskania określonego wyniku egzaminu.\\nKompetencje te nabierają szczególnego znaczenia w przypadku składania przez osoby\\negzaminowane skarg dotyczących przebiegu egzaminu lub kwestionowania jego wyniku.\\nEgzaminator powinien być wówczas zdolny do precyzyjnego odtworzenia przebiegu\\nzdarzenia, właściwej oceny zachowania osoby egzaminowanej oraz przedstawienia spójnego\\ni merytorycznego uzasadnienia podjętej decyzji, znajdującego oparcie w obowiązujących\\nprzepisach.\\nZniesienie wymogu posiadania wykształcenia wyższego przez kandydatów na egzaminatorów\\nobniżyło formalny próg dostępu do zawodu, mimo że zakres odpowiedzialności egzaminatora\\noraz wymagania związane z prawidłowym wykonywaniem jego obowiązków nie uległy\\nodpowiedniemu zmniejszeniu. Doświadczenia praktyczne środowiska egzaminatorów\\nwskazują natomiast, że samo spełnienie pozostałych wymagań formalnych nie zawsze\\ngwarantuje odpowiedni poziom kompetencji niezbędnych do właściwego wykonywania tego\\nzawodu, w szczególności w zakresie komunikacji, argumentacji oraz prawidłowego\\nuzasadniania dokonywanych ocen.\\nNależy również zwrócić uwagę na potrzebę zachowania właściwych proporcji pomiędzy\\nwymaganiami stawianymi instruktorom, a wymaganiami dotyczącymi egzaminatorów. Skoro\\nprojektodawca dostrzega potrzebę podwyższenia wymagań dotyczących wykształcenia osób\\nodpowiedzialnych za przygotowanie kandydatów do kierowania pojazdami, tym bardziej\\nuzasadnione jest zapewnienie odpowiednio wysokich wymagań wobec osób, które następnie\\ndokonują niezależnej i końcowej oceny kwalifikacji tych kandydatów w ramach egzaminu\\npaństwowego.\\nPrzywrócenie wymogu posiadania wykształcenia wyższego stanowiłoby również element\\nwzmacniający profesjonalny charakter zawodu egzaminatora oraz sprzyjałoby utrzymaniu \\f\\n\\nStrona 59 z 219\\n\\nodpowiedniego poziomu merytorycznego osób wykonujących zadania o istotnym znaczeniu\\ndla bezpieczeństwa ruchu drogowego.\\nW ocenie Krajowego Stowarzyszenia Egzaminatorów podwyższenie wymagań dotyczących\\nwykształcenia kandydatów na egzaminatorów powinno stanowić jeden z elementów\\ndziałań zmierzających do podnoszenia jakości systemu egzaminowania, profesjonalizacji\\nzawodu egzaminatora oraz wzmacniania społecznego zaufania do egzaminów\\npaństwowych na prawo jazdy.\\nProponowane brzmienie art. 58 ust. 1 pkt 1:\\n„1) posiada wykształcenie wyższe; dotyczy kandydatów na egzaminatorów po dniu wejścia w\\nżycie ustawy ”.\\n Art. 1 pkt 11\\nprojektu\\nustawy w\\nzakresie art.\\n45 ust. 2 pkt\\n1a, 3a i 3b\\nustawy o\\nkierujących\\npojazdami Unia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy zdefiniować pojęcie „wielokrotnie” oraz wprowadzić proporcjonalny mechanizm\\nsankcyjny, rozróżniający naruszenia zawinione przez OSK od naruszeń wynikających z awarii\\nsystemu centralnego, aplikacji, braku łączności lub nieprawidłowości po stronie dostawcy\\nrozwiązań technicznych. Sankcje powinny być poprzedzone możliwością usunięcia uchybień,\\no ile nie doszło do rażącego naruszenia bezpieczeństwa lub fałszowania dokumentacji.\\nNależy rozważyć korektę brzmienia proponowanego punktu 1a tj. wielokrotne\\nniezrealizowanie obowiązków, o których mowa w art. 23f pkt 2-4 oraz uzupełnienie w\\nobowiązujących przepisach art. 45 ust. 2 pkt 1 lit. c w brzmieniu „pojazdami niespełniającymi\\nwymagań, o których mowa w art. 23c ust. 5, 23f, 24 lub nieposiadającymi aktualnego\\nokresowego badania technicznego”\\n\\nUzasadnienie:\\nProjekt przewiduje nowe przesłanki wykreślenia z rejestru/ewidencji związane z\\nniewykonywaniem obowiązków cyfrowych i ochroną danych, ale nie precyzuje progu\\nnaruszeń. Przy tak złożonym systemie teleinformatycznym część błędów może mieć\\ncharakter techniczny i niezależny od OSK. Brak gradacji sankcji może prowadzić do\\nnadmiernie represyjnej i niejednolitej praktyki organów nadzoru.\\n \\f\\n\\nStrona 60 z 219\\n\\nPropozycja o charakterze technicznym, uzupełniona o kwestię obowiązku szkolenia\\npojazdami bezpiecznymi i sprawnymi technicznie tj. posiadającymi aktualne okresowe\\nbadania techniczne (patrz. orzecznictwo)\\n Art. 1 pkt 11\\nlit. a-b\\nprojektu\\nustawy Związek\\nPracodawców\\n„Transport i\\nLogistyka Polska\\nAd. art. 1 pkt 11 lit. a-b projektu\\nOdnosząc się do proponowanych zmian w zakresie art. 45 ust. 2 pkt 1a, 3a i 3b UoKP,\\nzastrzeżenia TLP dotyczą braku precyzji w zakresie przesłanek do podejmowanych w trybie\\nnadzoru decyzji. Przepisy nie wskazują ile konkretnie przypadków obejmuje wielokrotne\\nnierealizowanie obowiązków, czy naruszanie warunków prowadzenia działalności przez\\nośrodek szkolenia kierowców. Jest to szczególnie istotne, gdyż wielokrotność ta jest\\nelementem, którego zaistnienie skutkuje skreśleniem z listy OSK przez starostę i brakiem\\nmożliwości dalszego szkolenia kierowców.\\n Art. 1 pkt 12\\nprojektu\\nustawy\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nW art. 46 ust. 1 pkt 4 lit c ustawy o kierujących pojazdami należy rozważyć uzupełnienie\\nbrzmienia tej regulacji poprzez zmianę np.: „ potwierdzenie nieprawdy w dokumentacji\\ndotyczącej szkolenia w tym cyfrowej karcie kursanta”.\\nNależy rozważyć wprowadzenie po literze c kolejną literę d w brzmieniu np. „wielokrotne\\nniezrealizowanie obowiązków o których mowa w art. 23d ust 6 lub 7 w wskazanych\\nterminach.\\nAlternatywnie przepis ten można uwzględnić w stosunku do przedsiębiorcy prowadzącego\\nOSK\\nUzasadnienie:\\nW obecnym kształcie projektu nie przewidziana została odpowiedzialność instruktora w\\nprzypadku niewypełniania obowiązków, dotyczących wprowadzania danych i informacji do\\ncyfrowej karty kursanta\\n Art. 1 pkt 13\\nprojektu\\nustawy Związek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPropozycja zmiany:\\ndot. art. 50 ust 2 pkt 9\\nw art. 50 w ust. 2 w pkt 8 kropkę zastępuje się średnikiem i dodaje się pkt 9 w brzmieniu:\\n„9) która powtórnie w tym samym dniu przystępuje do części praktycznej egzaminu\\npaństwowego, z którego uzyskała wynik negatywny.”;\\n - Proponuje się wykreślenie pkt 13  w proponowanym brzmieniu.\\n \\f\\n\\nStrona 61 z 219\\n\\nUzasadnienie:\\nJeżeli wojewódzki ośrodek ruchu drogowego (WORD) dysponuje wolnymi terminami\\negzaminów praktycznych albo zwolniły się miejsca wskutek rezygnacji osób, którym\\nwcześniej wyznaczono termin egzaminu na dany dzień, trudno znaleźć uzasadnienie dla\\nodmowy przystąpienia do ponownego egzaminu praktycznego tego samego dnia przez\\nosobę, która uzyskała wynik negatywny i wyraża taką wolę.\\n\\nSam fakt uzyskania negatywnego wyniku egzaminu nie stanowi jednoznacznej i obiektywnej\\nprzesłanki uzasadniającej zakaz ponownego przystąpienia do egzaminu w tym samym dniu.\\nJeżeli istnieją warunki organizacyjne umożliwiające przeprowadzenie takiego egzaminu, a\\nkandydat mógłby zostać zapisany na egzamin w dniu następnym, brak jest racjonalnych\\npodstaw do wykluczenia możliwości jego przeprowadzenia jeszcze tego samego dnia.\\n\\nNależy również zauważyć, że w sytuacji, gdy wolny termin egzaminu w danym dniu nie\\nzostanie wykorzystany, skierowanie takiej osoby na egzamin w innym terminie powoduje\\nzajęcie miejsca, z którego mogłaby skorzystać inna osoba oczekująca na egzamin. W\\nkonsekwencji dochodzi do sztucznego wydłużania czasu oczekiwania na egzamin praktyczny\\noraz mniej efektywnego wykorzystania dostępnych terminów egzaminacyjnych, mimo że\\nistniała możliwość przeprowadzenia egzaminu wcześniej.\\n\\nW związku z powyższym proponuje się pozostawienie tej kwestii do rozstrzygnięcia\\nwojewódzkiemu ośrodkowi ruchu drogowego, jako organizatorowi egzaminu, oraz\\nkandydatowi na kierowcę, który mógłby zdecydować o skorzystaniu lub rezygnacji z\\nmożliwości ponownego przystąpienia do egzaminu praktycznego tego samego dnia, o ile\\npozwalałyby na to warunki organizacyjne. Rozwiązanie takie przyczyniłoby się zarówno do\\nbardziej racjonalnego wykorzystania dostępnych terminów egzaminów, jak i do ograniczenia\\nsztucznego wydłużania kolejek osób oczekujących na wyznaczenie terminu egzaminu z\\npowodów proceduralnych.\\n Art. 1 pkt 13\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 13) w Art. 50.\\nOgraniczono możliwość powtórnego zdawania egzaminu w tym samym dniu. Taka zmiana\\nniewątpliwie ułatwi planowanie pracy w WORD, pozwoli lepiej wykorzystać czas na\\negzaminowanie, skróci kolejkę. Ale dla kursantów będzie tylko dodatkowym \\f\\n\\nStrona 62 z 219\\n\\nkłopotem. Zamiast dojechać do WORD jeden raz będą musieli to zrobić kilka razy. Zamiast\\njednego dnia urlopu z pracy będą musieli wykorzystać kilka dni. Kursant następnego dnia nie\\nbędzie lepiej jeździł jeśli przed kolejnym egzaminem nie wróci do\\nośrodka szkolenia na doszkolenie. Proponowana regulacja takiego obowiązku nie nakłada.\\n Art. 1 pkt 13\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\n11) W odniesieniu do art. 1 pkt 13 proponujemy następujące brzmienie przepisu art. 50 ust\\n2 pkt 9:\\n„9) która przystępowała w tym samym dniu do części praktycznej egzaminu państwowego w\\nzakresie danej kategorii prawa jazdy, z którego uzyskała wynik negatywny.”;\\nZaproponowane w projekcie brzmienie przepisu jest nielogiczne ponieważ z przepisu\\nwynika, że osoba przystępuje do egzaminu, a tak naprawdę nie powinna być na niego w\\nogóle zapisana. Zaproponowane brzmienie zakazuje zapisania na kolejny egzamin takiej\\nosoby w danym dniu, a nie egzaminowania już osoby zapisanej.\\n Art. 1 pkt 13\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 13 – proponujemy wprowadzenie okresu co najmniej 7 dni pomiędzy\\negzaminami. Ta regulacja powinna także dotyczyć egzaminów teoretycznych. Po trzech\\nkolejnych niepowodzeniach ww. okres powinien być przedłużony do miesiąca.\\n\\n Art. 1 pkt 13\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n13) w art. 50 w ust. 2 w pkt 8 kropkę zastępuje się średnikiem i dodaje się pkt 9 w\\nbrzmieniu:\\n\\n„9) która powtórnie w tym samym dniu przystępuje do części praktycznej egzaminu\\npaństwowego, z którego uzyskała wynik negatywny.”;\\n\\nNaszym zdaniem powinniśmy zostawić tą kwestie dyrekcji ośrodka egzaminowania. Są ośrodki\\ngdzie odległość osób przystępujących do egzaminu wynosi ponad 100 km, często osoby biorą\\ncały dzień urlopu lub wolnego. W okresach   gdzie nie ma dużo chętnych ( np. okres zimowy)\\nzapełnienie pełnego grafiku egzaminatorowi w danym dniu  jest bardzo trudne). Cześć\\nwyników negatywnych jest rezultatem stresu, a nie złego przygotowania. Wielokrotnie  zdarza\\nsię, iż klienci podchodzą  drugi raz  do egzaminu  w tym samym dniu uzyskujac wynik\\npozytywny.  Dlatego proponujemy aby zostawić tą kwestie dyrektorom tak jak do tej pory.\\nProponujemy zmianę zapisu na uniemożliwiający  zdawanie egzaminu więcej, niż  dwa razy w\\ntym samym dniu.   \\f\\n\\nStrona 63 z 219\\n\\nArt. 1 pkt 13\\nprojektu\\nustawy\\nZwiązek\\nPracodawców\\n\\\"Transport i\\nLogistyka\\nPolska\\\"\\n\\n1. Ad. art. 1 pkt 13 projektu\\nProponujemy modyfikację brzmienia art. 50 ust. 2 pkt 9 UoKP na następujące:\\n„9) która uzyskała w tym samym dniu negatywny wynik z części praktycznej egzaminu\\npaństwowego.”.\\nW ocenie TLP, jest to rozwiązanie wprowadzające jednoznacznie zasadę, iż w tym samym\\ndniu nie można przystępować do więcej niż jednego egzaminu i realizujące w pełni cel\\nprojektowanego przepisu.\\n Art. 1 pkt 14\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 14) d)\\nUsuwa z egzaminu w WORD zadania na placu manewrowym dla kat. B, B1.\\nNawet największa sprawność w realizacji zadań na placu manewrowym nie gwarantuje, że\\nkursant w rzeczywistym ruchu drogowym nie będzie popełniał błędów. Czas poświęcony na\\nopanowanie zadań na placu manewrowym automatycznie ogranicza czas jaki instruktor\\nmógłby poświęcić na szkolenie w rzeczywistych warunkach ruchu drogowego. Jeśli celem\\negzaminu w WORD jest sprawdzenie czy kursant potrafi\\nkierować w rzeczywistym ruchu drogowym to rezygnacja z wykonywania zadań w sztucznych\\nwarunkach na placu może być uzasadniona.\\n Art. 1 pkt 14\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n14)  w art. 51\\n\\nd) w ust. 3 w pkt 1:\\n– w lit. a skreśla się wyrazy „B1 i B”,\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nLikwidacja placu manewrowego w zakresie kat B prawa jazdy pociągnie za sobą wiele\\nnegatywnych konsekwencji. Cena egzaminu będzie musiała wzrosnąć ze względu na\\nzmniejszenie ilości egzaminów praktycznych. Likwidacja placu manewrowego przy\\njednoczesnym pozostawieniu obecnej tabeli zadań egzaminacyjnych spowoduje wydłużenie\\nczasu realizacji egzaminów praktycznych. Automatycznie musi wzrosnąć koszt działalności\\nWORD-ów, niebagatelnym kosztem będzie również zagospodarowanie pozostałej\\ninfrastruktury, część WORD-ów będzie nadal ponosić koszty dzierżawy, utrzymania\\nbezużytecznych terenów, podatków. Przykładowo w MORD Kraków OT Oświęcim  zlikwidują\\negzaminy na kategorie motocyklowe i po zakończeniu umowy najmu oddadzą \\f\\n\\nStrona 64 z 219\\n\\nwyremontowany ogromnym nakładem finansowym plac albo będą każdego roku przez pół\\nroku braku egzaminów na kategorie motocyklowe utrzymywać pusty plac. Wiele ośrodków\\negzaminowania w Polsce przygotowując się do kategorii C+E  na ciągniku siodłowym z naczepą\\nponiosło wielomilionowe koszty związane z modernizacja placu np. WORD Suwałki. Nie\\nzawsze warunki umożliwiają zagospodarowanie placu na cele inne, niż egzaminy na          kat.\\nB. Istotny będzie  również spadek dochodów z najmu placu dla ośrodków szkolenia\\nkierowców. Puki co proponowane zmiany i tak zmuszą WORD-y do kosztownego\\nutrzymywania placu manewrowego o wymiarach przewidzianych dla kat. B ze względu na\\nprowadzenie egzaminów na kat AM czterokołowcem lekkim lub pojazdem trójkołowym.\\nNależy jednoznacznie wskazać, iż efektem proponowanych zmian będzie zwiększenie nakładu\\npracy poszczególnych egzaminatorów. Na przykładzie dużych miast już teraz praktycznie\\nniemożliwa jest realizacja zaplanowanych 9 egzaminów w przypadku konieczności realizacji\\npełnego programu egzaminu tj. plac manewrowy + ruch drogowy. Likwidacja placu nie skróci\\nwyraźnie czasu egzaminów. Przy odpowiedniej organizacji placów manewrowych realizacja\\ndwóch proponowanych do usunięcia zadań trwała bardzo krótko.  Przypadki te wiążą się z\\nkoniecznością przeprowadzania egzaminów przez egzaminatorów nadzorujących lub\\nprzeprowadzeniem przez innych egzaminatorów 10 egzaminów w ciągu dnia pracy. Nie\\nwyobrażamy sobie sytuacji po wprowadzeniu proponowanych  zmian, gdy będzie absencja\\negzaminatora. Teraz, gdy osoba uzyska wynik negatywny na placu manewrowym jesteśmy w\\nstanie szybko przydzielić wolnego egzaminatora do osoby, która była zaplanowana na\\negzaminatora, który w tym dniu nie wstawił się do pracy. Po zmianach będzie to niemożliwe\\nkażdy egzaminator gdy wyjedzie od razu do ruchu wróci po 20 -30 minutach i nie będzie w\\nstanie wziąć kolejnej osoby. Muszą być rezerwowi egzaminatorzy. Chcąc zapewnić obecny\\npoziom obsługi klienta wskazane będzie istotne zmniejszenie ilości planowanych egzaminów\\npraktycznych. Mając na uwadze konieczność realizacji wszystkich zaplanowanych egzaminów\\ntj. niedoprowadzanie do sytuacji, w której klient przyjedzie do WORD-u i dowie się, że egzamin\\njest odwołany niezbędnym będzie ograniczenie ilości planowanych egzaminów praktycznych\\nna poszczególnych egzaminatorów. Konieczna jest również nowelizacja przepisów\\ndotyczących organizacji egzaminów, a mianowicie jednoznaczne doprecyzowanie, że\\nmaksymalny czas spóźnienia rozpoczęcia egzaminu dotyczy osób egzaminowanych, a nie\\negzaminatora;\\nZmniejszenie ilości planowanych egzaminów znacznie wydłuży terminy oczekiwania na\\negzaminy praktyczne. W tym momencie niektóre WORD-y mają ogromny problem z naborem \\f\\n\\nStrona 65 z 219\\n\\nnowych pracowników, ogłoszenia o prace pozostają bez odpowiedzi, starsi egzaminatorzy\\nprzechodzą na emerytury, a nie ma kim ich zastąpić. Już na ten moment czas oczekiwania na\\negzaminy w wielu WORD-ach jest zbyt długi.\\nProponujemy aby pozostawić plac manewrowy, ale chcąc zapewnić lepsze warunki dla osób\\negzaminowanych, należałoby znowelizować zasady przez np. dodanie korekty na pasie ruchu,\\ndowolność ustawienia  lusterka, próbne ruszenie, zapoznanie się z samochodem WORD, przed\\nrozpoczęciem drugiego zadania tj. jazdy pasem ruchu.\\n Art. 1 pkt 14\\nlit. d projektu\\nustawy\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\n\\nUwaga 1. Objęcie wyłączeniem zadań na placu manewrowym także egzaminu w zakresie\\nkategorii AM przeprowadzanego czterokołowcem lekkim lub motorowerem trójkołowym\\n(art. 1 pkt 14 lit. d projektu; art. 51 ust. 3 pkt 1 lit. a ustawy)\\nTreść uwagi: Popierając wyłączenie kategorii B i B1 z zakresu zadań realizowanych na placu\\nmanewrowym, postulujemy rozszerzenie tego wyłączenia również na egzamin państwowy w\\nzakresie kategorii AM przeprowadzany czterokołowcem lekkim lub motorowerem\\ntrójkołowym, przy jednoczesnym pozostawieniu bez zmian zadań na placu manewrowym dla\\negzaminu kategorii AM przeprowadzanego motorowerem dwukołowym oraz wymogów\\ninfrastrukturalnych ośrodków szkolenia kierowców w zakresie tej kategorii.\\nProblem: Projektowany art. 1 pkt 14 lit. d skreśla w art. 51 ust. 3 pkt 1 lit. a wyrazy „B1 i B”,\\npozostawiając w zakresie zadań na placu manewrowym kategorie AM, A1, A2 i A. Tymczasem\\nzgodnie z § 23 ust. 3 rozporządzenia Ministra Infrastruktury z dnia 24 listopada 2023 r. w\\nsprawie egzaminowania osób ubiegających się o uprawnienia do kierowania pojazdami (Dz.\\nU. poz. 2659) osoba egzaminowana w zakresie kategorii AM czterokołowcem lekkim lub\\nmotorowerem trójkołowym wykonuje na placu manewrowym zadania określone dla kategorii\\nB1 w sposób określony dla tej kategorii, wobec czego po usunięciu zadań placowych dla\\nkategorii B1 utrzymanie kategorii AM w art. 51 ust. 3 pkt 1 lit. a prowadzi do sytuacji, w której\\nzadania egzaminacyjne dla obu tych wariantów egzaminu odsyłają do zadań, które przestaną\\nistnieć. Czterokołowiec lekki jest przy tym pojazdem konstrukcyjnie i funkcjonalnie zbliżonym\\ndo samochodu osobowego, a zadania wykonywane na placu manewrowym zarówno tym\\npojazdem, jak i motorowerem trójkołowym, odpowiadają zadaniom przewidzianym\\ndotychczas dla kategorii B1, wobec czego wszystkie argumenty przemawiające za\\nprzeniesieniem oceny umiejętności do rzeczywistego ruchu drogowego, przywołane w\\nuzasadnieniu projektu w odniesieniu do kategorii B i B1, zachowują pełną aktualność także w\\nodniesieniu do tych wariantów egzaminu. Pozostawienie zadań na placu manewrowym \\f\\n\\nStrona 66 z 219\\n\\nwyłącznie dla tych statystycznie marginalnych wariantów spowoduje ponadto, że\\nwojewódzkie ośrodki ruchu drogowego będą zobowiązane w dalszym ciągu utrzymywać\\nstanowisko przystosowane do wykonywania tych zadań, mimo że infrastruktura ta przestanie\\nbyć wykorzystywana na potrzeby egzaminów kategorii B i B1, co pozostaje w sprzeczności z\\ndeklarowanym w Ocenie Skutków Regulacji celem efektywniejszego wykorzystania zasobów\\ntych ośrodków. Podkreślamy zarazem, że w zakresie szkolenia wymóg posiadania placu\\nmanewrowego przez ośrodki prowadzące szkolenie w kategorii AM powinien pozostać\\nniezmieniony, ponieważ plac pozostaje niezbędny do bezpiecznej nauki jazdy jednośladem.\\nPropozycja zmiany zapisu: Proponujemy, aby art. 1 pkt 14 lit. d tiret pierwsze projektu,\\ndotyczące art. 51 ust. 3 pkt 1 lit. a ustawy, otrzymało brzmienie:\\n„– lit. a otrzymuje brzmienie:\\n«a) sprawdzenie podstawowych umiejętności w zakresie panowania nad pojazdem\\nodpowiednim dla uprawnień prawa jazdy kategorii A1, A2 i A, a w zakresie kategorii\\nAM – wyłącznie w przypadku egzaminu przeprowadzanego motorowerem\\ndwukołowym,»”\\n\\nArt. 1 pkt 14\\nlit. c projektu\\nustawy\\n\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\n\\nUwaga 5. Przeniesienie maksymalnej liczby pytań egzaminacyjnych na poziom\\nrozporządzenia oraz wprowadzenie kryteriów psychometrycznych i kwartalnego\\nmonitoringu pytań (art. 1 pkt 14 lit. c projektu; art. 51 ust. 2c ustawy)\\nTreść uwagi: Postulujemy, aby maksymalnej liczby pytań egzaminacyjnych nie określać w\\nustawie, lecz przenieść ją, wraz z kryteriami psychometrycznymi dopuszczenia pytania do\\nstosowania oraz trybem kwartalnego monitoringu jakości pytań obejmującym automatyczne\\nzawieszanie pytań zdegradowanych, do rozporządzenia wydanego na podstawie delegacji\\nustawowej.\\nProblem: Projektowany art. 1 pkt 14 lit. c zastępuje w art. 51 ust. 2c liczbę „4000” liczbą\\n„1500”, wskutek czego przepis nadal określa w ustawie maksymalną liczbę pytań\\negzaminacyjnych. Nie kwestionujemy docelowego rozmiaru bazy, wskazujemy natomiast, że\\nnawet ujęta jako pułap maksymalny liczba pytań jest parametrem operacyjnym produktu\\ncyfrowego, którym baza pytań się staje, nie zaś rozwiązaniem ustrojowym wymagającym rangi\\nustawowej, a jej pozostawienie w ustawie oznacza, że każde podniesienie tego pułapu będzie \\f\\n\\nStrona 67 z 219\\n\\nwymagało nowelizacji ustawy. Ograniczenie to okaże się szczególnie dotkliwe w razie\\nprzewidywanego rozwoju egzaminu teoretycznego, w tym ewentualnego włączenia do niego\\nzadań badających percepcję zagrożeń, które mogą wymagać zwiększenia liczby pytań ponad\\nprzyjęty pułap. Jednocześnie projekt nie określa żadnych kryteriów jakościowych\\nwarunkujących dopuszczenie pytania do stosowania ani mechanizmu ciągłego monitorowania\\npytań aktywnych, przez co walidacja przewidziana w projektowanym art. 57aa ust. 2 pkt 4\\npozostaje deklaratywna, a wobec pełnej jawności bazy pytań przewidzianej w art. 51 ust. 2b,\\nktórą w pełni popieramy, kluczowego znaczenia nabiera systematyczne wycofywanie pytań\\nzdegradowanych – takich, które wskutek pamięciowego opanowania przez osoby\\negzaminowane utraciły wartość różnicującą.\\nPropozycja zmiany zapisu: Proponujemy, aby art. 1 pkt 14 lit. c projektu otrzymał brzmienie:\\n„c) ust. 2c otrzymuje brzmienie:\\n«2c. Maksymalną liczbę pytań egzaminacyjnych stosowanych na egzaminie\\npaństwowym określają przepisy wydane na podstawie ust. 2d.»”\\noraz aby po lit. c dodać lit. ca w brzmieniu:\\n„ca) po ust. 2c dodaje się ust. 2d w brzmieniu:\\n«2d. Minister właściwy do spraw transportu określi, w drodze rozporządzenia,\\nmaksymalną liczbę pytań egzaminacyjnych stosowanych na egzaminie\\npaństwowym, kryteria psychometryczne warunkujące dopuszczenie pytania\\negzaminacyjnego do stosowania oraz tryb okresowego, przeprowadzanego nie\\nrzadziej niż raz na kwartał, monitorowania jakości stosowanych pytań\\negzaminacyjnych, obejmującego automatyczne zawieszanie stosowania pytań,\\nktóre utraciły wartość różnicującą, mając na względzie konieczność zapewnienia\\nrzetelnej oceny kompetencji osób egzaminowanych oraz bieżącego\\ndostosowywania bazy pytań do zmian stanu prawnego, postępu technologicznego\\nw motoryzacji i danych o wypadkach drogowych.»”\\n\\n Art. 1 pkt 14\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nW art. 1 pkt 14  w podpunkcie 3 – proponujemy skreślić ust. 3c.\\n \\f\\n\\nStrona 68 z 219\\n\\nRuchu\\nDrogowego\\n\\nArt. 1 pkt 14\\nprojektu\\nustawy\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n1. Ad, art. 1 pkt 14 projektu\\n- Przepis art. 1 pkt 14 lit. c projektu zmienia przepis art. 51 ust. 2c, regulujący liczbę pytań\\negzaminacyjnych z 4000 na 1000. Nie odnosząc się do kwestii merytorycznej (zmniejszenia\\nliczby pytań), uważamy że takie kwestie nie powinny być regulowane w drodze ustawy. Tego\\ntypu przepisy wydają się być sprzeczne z zasadą minimalizmu legislacyjnego, zasadą\\nproporcjonalności (pomocniczości) oraz ze zdrowym rozsądkiem. Jeżeli kiedykolwiek trzeba\\nbędzie podjąć decyzję o zwiększeniu liczby pytań o nowe obszary (co wymagałoby dodania\\nna przykład kolejnych 10 pytań), to w tej sprawie będzie potrzebna decyzja Sejmu, Senatu i\\nPrezydenta RP. Czy naprawdę jest to poważne rozwiązanie? Dlatego proponujemy\\nuchylenie przepisu art. 51 ust. 2c UoKP.\\n- Przepis art. 1 pkt 14 lit. d projektu wyłącza obowiązek przeprowadzania części egzaminu\\npraktycznego w zakresie kategorii B1 i B na placu manewrowym. W odniesieniu do tego\\nrozwiązania swoje uwagi wskazaliśmy wyżej w pkt 5 postulatu TLP, dotyczącego zmian w\\negzaminie praktycznym na prawo jazdy kategorii C, C+E, D, D+E. Podtrzymujemy\\nsformułowane tamże propozycje odpowiednich zmian w art. 51 UoKP.\\n- Przepis art. 1 pkt 14 lit. e projektu wprowadza w art. 51 UoKP nowe przepisy ust. 3a-3c,\\nregulujące zasady uznawania wyników części egzaminu praktycznego przez okres 24\\nmiesięcy. Nie negując potrzeby podobnej regulacji pragniemy zwrócić uwagę, na fakt iż\\numiejętności praktyczne nabywane są w trzech etapach (klasyczny model przyswajania\\numiejętności motorycznych Fittsa i Posnera): fazy poznawczej/kognitywnej (kursant\\nświadomie myśli o każdym ruchu), fazy asocjacyjnej (ruchy kursanta zaczynają łączyć się w\\npłynniejsze sekwencje) i fazy autonomicznej (umiejętność przechodzi do głębokiej pamięci\\nproceduralnej - jest automatyczna. 20\\n\\nOsoba, która jedynie ukończyła standardowe szkolenie, zazwyczaj dociera zaledwie do\\npóźnej fazy poznawczej lub wczesnej asocjacyjnej. Ponieważ jej mózg wciąż musi traktować\\nprowadzenie pojazdu, jako ciąg świadomych instrukcji (wiedza deklaratywna), umiejętność\\nta nie zdążyła się utrwalić, jako odporny na upływ czasu nawyk ruchowy. To prowadzi do\\nszybkiej degradacji nieutrwalonej umiejętności. Zjawisko to w literaturze naukowej nosi\\nnazwę zaniku umiejętności (ang. skill decay), jeśli osoba po szkoleniu nie podejmuje praktyki.  \\f\\n\\nStrona 69 z 219\\n\\nI tak po kilku tygodniach następuje szybka utrata płynności motorycznej (tzw. \\\"drewniane\\nruchy\\\"), utrata zdolności do synchronizacji kilku czynności naraz (np. obserwacja lusterek i\\noperowanie pedałami), etc.\\nPo 3–6 miesiącach, ślady wczesnej pamięci proceduralnej ulegają znacznemu zatarciu.\\nPojawiają się rażące błędy (np. gaśnięcie silnika, problemy z oceną odległości, szarpanie).\\nPoziom stresu poznawczego przy próbie wykonania zadania jest zbliżony do tego z\\npoczątków kursu.\\nPowyżej roku (i dalej) następuje niemal całkowity regres do stanu początkowego w zakresie\\ntzw. pamięci mięśniowej. Osoba pamięta jedynie ułamki wiedzy teoretycznej (wie, do czego\\nsłuży kierownica i hamulec), ale w ujęciu neurologicznym powraca do punktu wyjścia.\\nSamodzielne, bezpieczne prowadzenie pojazdu bez jazd doszkalających staje się wówczas\\nniemożliwe.\\nDlatego też proponujemy weryfikację wskazanego okresu z uwzględnieniem współczesnych\\nbadań w tym obszarze.\\n Art. 1 pkt 14\\nlit. e projektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n14)  w art. 51\\n\\ne) po ust. 3 dodaje się ust. 3a–3c w brzmieniu:\\n\\n3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego\\nprzystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach\\nwydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu lub\\nzdrowiu uczestników ruchu drogowego – w takim przypadku\\nosoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w pełnym\\nzakresie.”,\\n\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nKrajowe Stowarzyszenie Egzaminatorów opowiada się za pozostawieniem obowiązku\\nwykonywania zadań na placu manewrowym przy każdym podejściu do części praktycznej\\negzaminu państwowego. Plac manewrowy stanowi bezpieczne i odizolowane od ruchu\\ndrogowego środowisko, w którym weryfikowane są podstawowe umiejętności techniczne\\nosoby egzaminowanej, w tym właściwe operowanie pojazdem oraz wyczucie jego gabarytów. \\f\\n\\nStrona 70 z 219\\n\\nMa to szczególne znaczenie w przypadku kategorii motocyklowych oraz kategorii dotyczących\\npojazdów ciężkich.\\nJednocześnie zdecydowanie negatywnie oceniamy rozwiązanie zaproponowane w ust. 3c,\\nzgodnie z którym osoba, która podczas kolejnego podejścia do egzaminu w ruchu drogowym\\nspowoduje bezpośrednie zagrożenie życia lub zdrowia uczestników ruchu drogowego, przy\\nnastępnym podejściu będzie zobowiązana do ponownego przystąpienia do części praktycznej\\negzaminu w pełnym zakresie.\\nNie znajdujemy merytorycznego uzasadnienia dla uzależnienia obowiązku ponownego\\nwykonywania zadań na placu manewrowym od zachowania osoby egzaminowanej w ruchu\\ndrogowym. Spowodowanie bezpośredniego zagrożenia w ruchu drogowym nie oznacza, że\\nosoba egzaminowana utraciła lub nie posiada umiejętności technicznych, które zostały\\nwcześniej pozytywnie zweryfikowane na placu manewrowym.\\nProponowany przepis może ponadto prowadzić do niepotrzebnych sporów pomiędzy osobą\\negzaminowaną, a egzaminatorem dotyczących kwalifikacji konkretnego zachowania jako\\nbezpośredniego zagrożenia życia lub zdrowia. Dla osoby egzaminowanej taka kwalifikacja\\nbędzie bowiem powodowała dodatkową konsekwencję w postaci konieczności powtarzania\\ncałego egzaminu, w tym ponownego wykonywania zadań na placu manewrowym. Problem\\nten może być szczególnie widoczny w przypadku kategorii motocyklowych oraz kategorii\\ndotyczących pojazdów ciężkich, gdzie część egzaminu przeprowadzana na placu\\nmanewrowym jest bardziej rozbudowana. Może to w konsekwencji powodować wzrost liczby\\nskarg i odwołań od przebiegu oraz wyniku egzaminu.\\nDodatkowym argumentem przeciw proponowanemu rozwiązaniu jest kwestia logistyki\\nprzeprowadzania egzaminów praktycznych zarówno, jeżeli chodzi o ich planowanie jaki i\\nfizyczną realizację. Przykładowo w zakresie kat. BE, CE, DE oraz T prawa jazdy kto będzie\\nodpowiadał za sprzęganie pojazdu silnikowego z przyczepą/naczepą w przypadku kandydata\\nna kierowcę podchodzącego do egzaminu tylko w części realizowanej w ruchu drogowym?\\nProponowana zmiana może wygenerować dodatkowe koszty zatrudnienia pracowników do\\nobsługi sprzęgania. Osoby egzaminowane mogą również kwestionować koszt tego\\n„skróconego” egzaminu. \\f\\n\\nStrona 71 z 219\\n\\nZ posiadanych przez Krajowe Stowarzyszenie Egzaminatorów informacji wynika ponadto, że\\nw przypadku kategorii motocyklowych oraz kategorii dotyczących pojazdów ciężkich liczba\\negzaminów zakończonych wynikiem negatywnym z powodu bezpośredniego zagrożenia życia\\nlub zdrowia uczestników ruchu drogowego jest niewielka. Tym samym projektowana\\nregulacja odnosi się do sytuacji występujących stosunkowo rzadko, jednocześnie\\nwprowadzając dodatkowe komplikacje w zakresie kwalifikowania wyniku egzaminu.\\nNależy również uwzględnić projektowaną zmianę art. 52 ust. 2, zgodnie z którą egzaminator\\nmoże przerwać egzamin, jeżeli zachowanie osoby egzaminowanej może zagrażać życiu lub\\nzdrowiu uczestników ruchu drogowego. Przy tak skonstruowanym przepisie egzamin może\\nzostać zakończony jeszcze przed wystąpieniem bezpośredniego zagrożenia, co dodatkowo\\nogranicza praktyczne zastosowanie projektowanego ust. 3c.\\nW naszej ocenie tworzenie dodatkowej regulacji odnoszącej się do nielicznych przypadków,\\nktóra jednocześnie może powodować spory interpretacyjne i zwiększać liczbę skarg na\\ndecyzje egzaminatorów, jest niecelowe.\\nW związku z powyższym Krajowe Stowarzyszenie Egzaminatorów proponuje usunięcie ust.\\n3c z projektu.\\n Art. 1 pkt 14\\nprojektu\\nustawy\\nZrzeszenie\\nMiędzynarodo-\\nwych\\nPrzewoźników\\nDrogowych w\\nPolsce\\nW pierwszej kolejności ZMPD pozytywnie ocenia zmianę przewidzianą w art. 1 pkt 14 lit. e\\nprojektu ustawy, polegającą na zachowaniu przez okres 24 miesięcy pozytywnego wyniku\\nczęści\\npraktycznej egzaminu państwowego uzyskanego na placu manewrowym. Brak konieczności\\nponownego wykonywania zadań, które zostały już zaliczone, może stanowić istotne\\nułatwienie dla osób ubiegających się o uzyskanie prawa jazdy kategorii C, C+E, D lub D+E, a\\ntym samym przyczynić się do usprawnienia procesu uzyskiwania uprawnień przez przyszłych\\nkierowców zawodowych. Przyjęty okres 24 miesięcy wydaje się przy tym racjonalnym\\nkompromisem pomiędzy interesem osoby egzaminowanej a potrzebą zachowania\\naktualności sprawdzonych wcześniej umiejętności.\\nWątpliwości budzi jednak propozycja pobierania opłaty w tej samej wysokości również w\\nprzypadku, gdy osoba egzaminowana, korzystając z zachowanego wyniku uzyskanego na\\nplacu manewrowym, przystępuje wyłącznie do części praktycznej egzaminu\\nprzeprowadzanej w ruchu drogowym. W ocenie Zrzeszenia wysokość opłaty powinna \\f\\n\\nStrona 72 z 219\\n\\npozostawać w odpowiedniej relacji do rzeczywistego zakresu egzaminu oraz kosztów jego\\nprzeprowadzenia. Skoro egzamin w takim przypadku nie obejmuje części realizowanej na\\nplacu manewrowym, zasadne jest ustalenie odrębnej, odpowiednio niższej opłaty. Nawet\\numiarkowane obniżenie kosztu\\nkolejnego podejścia (o 10 lub 20%) miałoby znaczenie dla kandydatów na kierowców\\nzawodowych, którzy na etapie uzyskiwania wymaganych uprawnień ponoszą bardzo wysokie\\nkoszty szkolenia i egzaminowania.\\nPozytywnie należy również ocenić ponowne wprowadzenie terminu ważności pozytywnego\\nwyniku części teoretycznej egzaminu państwowego. Jak wskazano w uzasadnieniu projektu,\\nbezterminowa ważność tego wyniku może prowadzić do sytuacji, w której osoba\\nprzystępująca do części praktycznej zdała egzamin teoretyczny wiele lat wcześniej. W takim\\nprzypadku wiedza kandydata mogła ulec częściowemu zatarciu, a ponadto – ze względu na\\nzachodzące w tym okresie zmiany przepisów – może nie odpowiadać aktualnemu stanowi\\nprawnemu.\\nWprowadzenie 24-miesięcznego okresu ważności wyniku części teoretycznej zasługuje\\nzatem na aprobatę, ponieważ zwiększa prawdopodobieństwo, że osoba przystępująca do\\negzaminu\\npraktycznego będzie dysponowała aktualną wiedzą z zakresu przepisów i bezpieczeństwa\\nruchu drogowego.\\n Art. 1 pkt 14\\nlit. e projektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\n\\nPropozycja zmiany:\\n3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie\\nkolejnego przystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony\\nw przepisach wydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża\\nbezpośrednio życiu lub zdrowiu uczestników ruchu drogowego – w takim przypadku\\nosoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w\\npełnym zakresie.” - Proponuje się wykreślenie pkt 14  w proponowanym brzmieniu.\\n\\nProponuje się rezygnację z projektowanego rozwiązania w tym zakresie.\\n\\nUzasadnienie:\\nZgodnie z art. 51 ust. 3 pkt 1 lit. b oraz odpowiednio art. 51 ust. 5 pkt 2 ustawy, część\\npraktyczna egzaminu państwowego obejmuje odrębnie sprawdzenie umiejętności \\f\\n\\nStrona 73 z 219\\n\\nmanewrowania pojazdem lub zespołem pojazdów (w przypadku egzaminu na prawo jazdy)\\nalbo sprawdzenie pozostałych umiejętności wymaganych podczas egzaminu (w przypadku\\npozwolenia).\\n\\nOznacza to, że wynik uzyskany podczas wykonywania zadań na placu manewrowym jest\\nniezależny od wyniku uzyskanego podczas realizacji zadań w ruchu drogowym. Nie istnieje\\nzatem merytoryczny związek pomiędzy nieprawidłowym wykonaniem zadań\\negzaminacyjnych w ruchu drogowym, w tym doprowadzeniem do zagrożenia\\nbezpieczeństwa ruchu drogowego, a prawidłowym wykonaniem manewrów na placu\\nmanewrowym.\\n\\nW konsekwencji projektowany przepis prowadziłby do konieczności ponownej weryfikacji\\numiejętności, które zostały już pozytywnie ocenione na wcześniejszym etapie egzaminu,\\nmimo że nie wystąpiły żadne okoliczności podważające prawidłowość tej oceny. Rozwiązanie\\ntakie pozostaje bez uzasadnienia merytorycznego i jest sprzeczne z konstrukcją części\\npraktycznej egzaminu państwowego, w której poszczególne etapy służą ocenie odrębnych\\ngrup umiejętności kandydata.\\n\\nProjektowane rozwiązanie rodzi również istotne wątpliwości formalnoprawne. Może\\nbowiem prowadzić do sytuacji, w której egzamin praktyczny przeprowadzony w ruchu\\ndrogowym, następnie prawomocnie unieważniony z uwagi na naruszenie przepisów mające\\nwpływ na jego wynik, wywoła wcześniej skutek prawny w postaci anulowania pozytywnego\\nwyniku części egzaminu przeprowadzonej na placu manewrowym.\\n\\nPrzykładowo, kandydat uzyskuje pozytywny wynik z części egzaminu realizowanej na placu\\nmanewrowym, natomiast otrzymuje wynik negatywny z części przeprowadzanej w ruchu\\ndrogowym. Przystępując do kolejnego egzaminu wyłącznie w ruchu drogowym doprowadza\\n– zgodnie z projektowanym przepisem – do sytuacji skutkującej utratą wcześniej uzyskanego\\npozytywnego wyniku z placu manewrowego. Następnie składa odwołanie od wyniku tego\\negzaminu, a właściwy organ lub sąd prawomocnie stwierdza, że egzamin został\\nprzeprowadzony z naruszeniem przepisów, które miało wpływ na jego wynik, i w\\nkonsekwencji unieważnia ten egzamin.\\n \\f\\n\\nStrona 74 z 219\\n\\nW efekcie egzamin, który w świetle prawomocnego rozstrzygnięcia został uznany za\\nprzeprowadzony niezgodnie z prawem i wyeliminowany z obrotu prawnego, wywołał\\nwcześniej skutki wobec innego, prawidłowo przeprowadzonego etapu egzaminu\\npaństwowego poprzez anulowanie pozytywnego wyniku uzyskanego na placu\\nmanewrowym. Powstaje zatem stan, w którym wadliwy egzamin oddziałuje na wynik\\nodrębnej części egzaminu przeprowadzonej zgodnie z przepisami, mimo że sam został\\nnastępnie prawomocnie uznany za nieważny. Takie rozwiązanie narusza zasadę pewności\\nprawa oraz prowadzi do powstania niespójnych skutków prawnych, których projekt nie\\nreguluje.\\n Art. 1 pkt 14\\nlit. e\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nZawodowy\\nPracowników\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nZaproponowana nowelizacja ustawy z  dnia 5 stycznia 2011 r. o  kierujących pojazdami\\n(Dz.U.2025.1226 t.j.) przedstawia propozycję zmian w przepisach regulujących kwestie\\nzachowania pozytywnej części egzaminu praktycznego w zakresie egzaminu\\nprzeprowadzanego na placu manewrowym oraz godzin, w jakich przeprowadzone są\\negzaminy państwowe.\\n1. Propozycja stanowi zmianę rozwiązania przedstawionego w projekcie ustawy o zmianie\\nustawy o kierujących pojazdami oraz niektórych innych ustaw, znajdującej się w wykazie prac\\nlegislacyjnych i programowych Rady Ministrów pod numerem UD402. W przedstawionym\\nprojekcie proponuje się ponad przedstawione w niniejszym projekcie dodanie ustępu 3c,\\nartykułu 51 zmienianej ustawy w brzmieniu:\\n„3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego\\nprzystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach\\nwydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu lub\\nzdrowiu uczestników ruchu drogowego – w takim przypadku osoba ta przystępuje ponownie\\ndo części praktycznej egzaminu państwowego w pełnym zakresie.”\\nZaproponowane brzmienie nie jest spójne z obecnym brzmieniem art. 52 ust. 2, który reguluje\\nprzesłankę przerwania egzaminu jako zachowanie, które „może zagrażać życiu lub zdrowiu\\negzaminatora lub innego uczestnika ruchu drogowego lub bezpośrednio wpływa na\\nbezpieczeństwo ruchu drogowego\\\". Przesłanka ta jest szersza i dwuczłonowa (obejmuje\\nzarówno zachowania mogące zagrażać, jak i wpływające na bezpieczeństwo), podczas gdy\\nproponowany art. 51 ust. 3c posługuje się przesłanką węższą, która wymaga zagrożenia\\nbezpośredniego życia i zdrowia uczestników ruchu.\\nPowstaje w ten sposób realna możliwość rozbieżności skutków prawnych tego samego\\nzdarzenia egzaminacyjnego. Egzamin może zostać przerwany na podstawie art. 52 ust. 2 (jako \\f\\n\\nStrona 75 z 219\\n\\nzachowanie mogące zagrażać bezpieczeństwu), a mimo to nie spełni przesłanki z art. 51 ust.\\n3c. Projektodawca nie wyjaśnia w uzasadnieniu relacji między tymi dwiema przesłankami, co\\nrodzi istotną wątpliwość interpretacyjną co do zakresu stosowania obu przepisów.\\nNiezależnie od wskazanej wyżej niespójności zaproponowanej zmiany z art. 52 ust. 2, należy\\nzwrócić uwagę na samą konstrukcję projektowanego przepisu. Art. 51 ust. 3a, 3b oraz 3c\\nwprowadzają wielostopniowy warunek zachowania ważności wyniku części egzaminu\\nprzeprowadzanej na placu manewrowym, uzależniony od oceny zachowania zdającego\\nw trakcie odrębnej, późniejszej części egzaminu w ruchu drogowym. Takie rozwiązanie jest\\ntrudne do jednoznacznej interpretacji dla egzaminatora, a tym bardziej dla osoby\\negzaminowanej, która powinna mieć możliwość zrozumienia zasad, na jakich jest oceniana\\nbez konieczności sięgania po wykładnię systemową kilku przepisów jednocześnie.\\n2. Zaproponowane rozwiązanie eliminuje problem przeprowadzanie egzaminów\\nw warunkach późnowieczornych, podczas których, z uwagi na niewielkie natężenie ruchu nie\\nmożna w sposób właściwy ocenić zachowania osoby egzaminowanej w odniesieniu do innych\\nuczestników ruchu. Dodatkowo przeprowadzanie egzaminów państwach poza nominalnym\\nruchem drogowym stoi w sprzeczności z normą prawną, zawartą w Dyrektywie, która stanowi\\n„Kandydaci muszą wykonać wszystkie poniższe czynności w normalnym ruchu ulicznym”.\\nWprowadzenie proponowanego ograniczenia przyczyni się do zwiększenia wiarygodności\\negzaminu jako narzędzia oceny rzeczywistych kompetencji kandydatów na kierowców oraz\\nzapewni większą spójność krajowych regulacji z przepisami prawa Unii Europejskiej.\\n\\n Art. 1 pkt 14\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\nW odniesieniu do art. 1 pkt 14:\\na) W lit c proponujemy pozostawienie dotychczasowej maksymalnej liczby pytań lub\\newentualnie usunięcie całego przepisu.\\nObniżenie liczby pytań w bazie pytań stosowanej na egzaminie państwowym na prawo jazdy\\ndo 1500 doprowadzi do sytuacji w której każdy średnio-inteligentny kandydat na kierowcę\\nbędzie w stanie nauczyć się wszystkich pytań na pamięć. Nie pomoże dynamiczna zmiana\\npytań, czy ich utajnienie, jeżeli np. w zakresie prawa jazdy kategorii B będzie tylko 400 pytań\\negzaminacyjnych. Warto zauważyć, że liczba 1500 dotyczy pytań egzaminacyjnych na\\nwszystkie kategorie prawa jazdy zarówno z części ogólnej jak i z części specjalistycznej,\\nwliczając także te na pozwolenie na kierowanie tramwajem czy te na prawo jazdy kategorii\\nAM. Zatem na poszczególne kategorie prawa jazdy będziemy mieli do nauczenia się \\f\\n\\nStrona 76 z 219\\n\\nwyłącznie po kilkaset pytań. Z punktu widzenia procesu kształcenia jest to zła sytuacja, bo\\nograniczony ze względów praktycznych do niezbędnego minimum zakres części teoretycznej\\negzaminu spowoduje ograniczenie, ze względów ekonomicznych prowadzenia wykładów na\\nkorzyść nauki poszczególnych pytań. Takie działanie przyczyni się do pogorszenia jakości\\nszkolenia a nie do jego poprawy.\\n\\nb) Odnosząc się do propozycji zawartej w literze e dotyczącej podziału części praktycznej\\negzaminu na część na placu manewrowym i na część w ruchu drogowym w naszej ocenie\\nrozwiązanie to jest właściwe, ale nie wymaga uregulowania ustawowego. Zasady organizacji\\ni przeprowadzania egzaminu państwowego na prawo jazdy zgodnie z delegacją ustawową\\nokreśloną w art. 66 ust. 1 pkt 4 ustawy o kierujących pojazdami opisane są w rozporządzenie\\nMinistra Infrastruktury w sprawie egzaminowania osób ubiegających się o uprawnienia do\\nkierowania pojazdami, szkolenia, egzaminowania i uzyskiwania uprawnień przez\\negzaminatorów oraz wzorów dokumentów stosowanych w tych sprawach. Tam są\\numieszczone zasady wystawiania oceny czy możliwości kontynuowania egzaminu. Dlatego\\nteż w naszej ocenie umieszczenie w ustawie przepisów art. 51 ust. 3a – 3c jest niezasadne.\\nWpisując je do ustawy należałoby do ustawy przenieść pozostałe zasady ocenienia co jest w\\nnaszej ocenie niepotrzebne. Zatem przepisy te, jak najbardziej potrzebne, należy umieścić w\\nnowym rozporządzeniu w sprawie egzaminowania. Takie rozporządzenie i tak będzie\\nmusiało być przygotowane ze względu na likwidację placu manewrowego w ramach\\negzaminu państwowego w zakresie prawa jazdy kategorii B.\\n\\nc) Ośrodek egzaminowania przesyła właściwemu organowi wydającemu prawo jazdy lub\\npozwolenie informację o pozytywnym albo negatywnym wyniku egzaminu przez aktualizację\\nprofilu kandydata na kierowcę w centralnej ewidencji kierowców.\\n\\nArt. 1 pkt 14\\nlit. f projektu\\nustawy\\n\\n NSZZ\\n„Solidarność” -\\n80 w WORD i\\nOSK\\n\\n W art. 51 ust 4a ustawy o kierujących dodać „Miasto, wskazane przez sejmik województwa\\nna wniosek marszałka województwa jako miejsce przeprowadzania egzaminów musi\\nposiadać infrastrukturę odpowiednią do realizacji zadań określonych w rozporządzeniu w\\nsprawie egzaminowania jako obowiązkowe. Spełnienie tych warunków kontroluje marszałek\\nwojewództwa. Protokół z wykonania kontroli wykonania obowiązkowych zadań dołącza do\\nwniosku.” Uzasadnieniem propozycji jest konieczność wyeliminowania sytuacji, o których \\f\\n\\nStrona 77 z 219\\n\\nwielokrotnie informowaliśmy, że miasta wskazywane przez sejmik województwa to miasta,\\nw których nie jest możliwe wykonanie zadań określonych jako obowiązkowe na egzaminie.\\nJeśli egzamin jest przeprowadzony w celu sprawdzania kwalifikacji osoby ubiegającej się o\\nuprawnienia konieczne jest aby poziom trudności egzaminu był jednakowy we wszystkich\\nośrodkach egzaminowania i aby zdający byli równo traktowani\\n\\n Art. 1 pkt 14\\nlit. f projektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\nf) ust. 4a otrzymuje brzmienie:\\n\\n„4a. Egzamin państwowy w zakresie prawa jazdy kategorii AM, A1, A2, A, B1, B, B+E lub T\\nmoże być także przeprowadzany w mieście niespełniającym warunków, o których mowa w\\nust. 4, wskazanym przez sejmik województwa na wniosek marszałka województwa.”;\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nKrajowe Stowarzyszenie Egzaminatorów negatywnie ocenia propozycję rozszerzenia\\nmożliwości przeprowadzania egzaminów państwowych w oddziałach terenowych o kategorie\\nB+E oraz T. W naszej ocenie rozwiązanie to może generować nieproporcjonalnie wysokie\\nkoszty organizacyjne i infrastrukturalne w stosunku do rzeczywistego zapotrzebowania na\\negzaminy w tych kategoriach.\\nPrzeprowadzanie egzaminów w zakresie kategorii B+E oraz T wymaga zapewnienia\\nodpowiedniej infrastruktury, w szczególności placu manewrowego o powierzchni i\\nparametrach umożliwiających prawidłowe wykonywanie wymaganych zadań\\negzaminacyjnych. W przypadku oddziałów terenowych, które korzystają z wynajmowanej\\ninfrastruktury, może to oznaczać konieczność wynajęcia dodatkowej powierzchni, jej\\nodpowiedniego przygotowania oraz ponoszenia stałych kosztów utrzymania, niezależnie od\\nfaktycznej liczby przeprowadzanych egzaminów.\\nProblem ten nabiera szczególnego znaczenia w kontekście projektowanych zmian\\ndotyczących egzaminów w zakresie kategorii B i B1, przewidujących odejście od wykonywania\\nczęści dotychczasowych zadań na placu manewrowym. Wprowadzenie tych zmian może\\nistotnie ograniczyć zapotrzebowanie na rozbudowaną infrastrukturę placów manewrowych\\nwykorzystywanych w oddziałach terenowych do egzaminów. Jednoczesne rozszerzenie\\ndziałalności tych oddziałów o kategorie B+E i T prowadziłoby natomiast do konieczności \\f\\n\\nStrona 78 z 219\\n\\ndalszego utrzymywania lub nawet rozbudowywania placów manewrowych przede wszystkim\\nna potrzeby tych dwóch kategorii.\\nW ocenie Krajowego Stowarzyszenia Egzaminatorów może prowadzić to do sytuacji\\nekonomicznie nieracjonalnej, w której znaczna powierzchnia infrastruktury egzaminacyjnej\\nbędzie utrzymywana na potrzeby relatywnie niewielkiej liczby egzaminów. Dotyczy to w\\nszczególności kategorii T, w przypadku której liczba przeprowadzanych egzaminów w wielu\\nośrodkach jest niewielka.\\nDodatkowym problemem pozostaje zapewnienie w oddziałach terenowych odpowiednich\\npojazdów egzaminacyjnych. W przypadku kategorii T konieczne byłoby zapewnienie ciągnika\\nrolniczego wraz z przyczepą w miejscu przeprowadzania egzaminów. Transport takiego\\nzespołu pojazdów pomiędzy główną siedzibą WORD, a oddziałem terenowym może być\\norganizacyjnie skomplikowany i generować dodatkowe koszty. Alternatywą byłoby\\nutrzymywanie odrębnego pojazdu w oddziale terenowym, co przy niewielkiej liczbie\\negzaminów w tej kategorii również może być ekonomicznie nieuzasadnione.\\nNależy ponadto zwrócić uwagę na nakłady inwestycyjne poniesione w ostatnich latach przez\\nwojewódzkie ośrodki ruchu drogowego w związku z dostosowaniem infrastruktury do nowych\\nwymagań dotyczących przeprowadzania egzaminów państwowych, w tym egzaminów\\nkategorii C+E przy wykorzystaniu ciągnika siodłowego i naczepy o czym pisaliśmy wcześniej.\\nDostosowanie placów manewrowych wymagało w części ośrodków przeprowadzenia\\nrozległych prac modernizacyjnych i poniesienia znaczących nakładów finansowych,\\nsięgających – według informacji posiadanych przez środowisko – nawet około 1–2 mln zł w\\nprzypadku pojedynczych inwestycji.\\nNależy przy  tej okazji wspomnieć  z dużym wyprzedzeniem, iż kwestią czasu będzie  jak\\npolitycy zauważą małe koszty tworzenia   i utrzymania oddziałów. Może wpłynąć to na\\nmasowe  tworzenie   oddziałów jak grzyby po deszcz co wpłynie   na  degradacje WORD-ów.\\n\\n Art. 1 pkt 14 i\\n16 oraz art. 8\\nprojektu\\nustawy w\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nNależy ponownie przeanalizować przepisy przejściowe dotyczące ważności pozytywnego\\nwyniku części teoretycznej egzaminu państwowego. Jeżeli celem jest zapewnienie\\naktualności wiedzy, warto rozważyć wprowadzenie długiego okresu dostosowawczego także\\ndla wyników uzyskanych przed wejściem w życie ustawy, np. 24 albo 36 miesięcy od dnia \\f\\n\\nStrona 79 z 219\\n\\nzakresie art.\\n51, art. 52 ust.\\n1 i przepisów\\nprzejściowych\\nwejścia w życie przepisów, albo szczegółowo uzasadnić utrzymanie ich bezterminowej\\nważności. Niezależnie od przyjętego wariantu system powinien automatycznie informować\\nkandydata i organy o utracie ważności wyniku.\\nUzasadnienie:\\nUzasadnienie trafnie wskazuje, że brak terminu ważności wyniku teoretycznego może\\nprowadzić do przystępowania do egzaminu praktycznego po wielu latach od zdania teorii.\\nJednocześnie projekt utrzymuje bezterminową ważność wyników dotychczasowych.\\nPowstaje więc niespójność między deklarowanym celem regulacji a rozwiązaniem\\nprzejściowym. Z perspektywy organów stosujących prawo konieczne jest także\\njednoznaczne, systemowe oznaczanie ważności wyniku, aby uniknąć sporów przy kierowaniu\\nna egzamin praktyczny\\n\\nArt. 1 pkt 19\\nprojektu\\nustawy\\n\\nNSZZ\\n„Solidarność” -\\n80 w WORD i\\nOSK\\n\\n W art. 54 dodać „Rejestracji obrazu dokonuje się za pomocą jednej kamery skierowanej do\\nprzodu pojazdu” skreślić „za pomocą urządzenia zainstalowanego w pojeździe\\ntowarzyszącym, a w miarę możliwości technicznych – także”. Uzasadnieniem tej propozycji\\njest wprowadzenie zapisu, który zestandaryzuje warunki nagrywania we wszystkich\\nośrodkach – nie ma potrzeby montowania kilku kamer – na licznik, na osobę zdającą, na tył,\\nbok pojazdu – z nagrania będzie można skutecznie prowadzić nadzór nad egzaminami, bo\\nMarszałek będzie mógł skontrolować czy egzamin odbył się zgodnie z obowiązującymi\\nprzepisami i czy ewentualne błędy popełnione przez egzaminatora miały wpływ na wynik\\negzaminu.\\n\\n Art. 1 pkt 19\\nlit. a projektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n19) w art. 54:\\na) ust. 1 otrzymuje brzmienie:\\n„1. Przebieg części praktycznej egzaminu państwowego dla każdej kategorii prawa jazdy\\nrejestruje się za pomocą urządzenia służącego do zapisu obrazu i dźwięku. W przypadku\\negzaminu państwowego przeprowadzanego pojazdem jednośladowym rejestracja odbywa\\nsię za pomocą urządzenia zainstalowanego w pojeździe towarzyszącym, a w miarę\\nmożliwości technicznych – także za pomocą urządzenia rejestrującego zainstalowanego na\\npojeździe egzaminacyjnym lub w wyposażeniu osoby egzaminowanej.”, \\f\\n\\nStrona 80 z 219\\n\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nKrajowe Stowarzyszenie Egzaminatorów zgłasza istotne zastrzeżenia dotyczące praktycznej\\nmożliwości realizacji obowiązku rejestracji obrazu i dźwięku podczas części praktycznej\\negzaminów państwowych w zakresie kategorii AM, A1, A2 i A na placu manewrowym.\\nStanowiska przeznaczone do wykonywania poszczególnych zadań egzaminacyjnych dla tych\\nkategorii są rozmieszczone w różnych częściach placu manewrowego. Jednocześnie na placu\\nmoże być prowadzonych kilka egzaminów, zarówno w zakresie kategorii motocyklowych, jak\\ni innych kategorii prawa jazdy. W tych warunkach zapewnienie ciągłej i czytelnej rejestracji\\nprzebiegu konkretnego egzaminu, wraz z zapisem dźwięku, za pomocą urządzenia\\nznajdującego się w pojeździe towarzyszącym może być w praktyce niemożliwe.\\nPojazd towarzyszący wykorzystywany podczas egzaminu w ruchu drogowym nie jest\\npojazdem przeznaczonym do przemieszczania się po placu manewrowym w ślad za osobą\\nwykonującą poszczególne zadania. Konieczność jego wielokrotnego przestawiania pomiędzy\\nstanowiskami egzaminacyjnymi byłaby nie tylko niepraktyczna, ale mogłaby również\\npowodować dodatkowe zagrożenie dla osób wykonujących w tym samym czasie zadania na\\nplacu manewrowym. Powstaje również problem organizacyjny dotyczący tego, kto miałby taki\\npojazd przemieszczać w czasie, gdy egzaminator prowadzi egzamin.\\nW naszej ocenie projektowany obowiązek w tym zakresie nie uwzględnia rzeczywistego\\nsposobu organizacji egzaminów motocyklowych na placach manewrowych WORD.\\nProponujemy zatem wyłączenie obowiązku rejestracji obrazu i dźwięku na placu\\nmanewrowym podczas egzaminów w zakresie kategorii AM, A1, A2 i A , pozostawiając\\nobowiązek rejestracji egzaminu w ruchu drogowym za pomocą urządzenia znajdującego się w\\npojeździe towarzyszącym.\\nZastrzeżenia dotyczą również objęcia obowiązkiem rejestracji egzaminów w zakresie kategorii\\nT. Pojazdy wykorzystywane do tych egzaminów nie zawsze stanowią własność wojewódzkiego\\nośrodka ruchu drogowego, a ich konstrukcja i wyposażenie mogą nie umożliwiać trwałego\\noraz zgodnego z wymaganiami technicznymi zamontowania urządzenia rejestrującego i \\f\\n\\nStrona 81 z 219\\n\\nzapewnienia mu odpowiedniego źródła zasilania. Z tego względu proponujemy rozważenie\\nwyłączenia kategorii T z obowiązku rejestracji przebiegu części praktycznej egzaminu.\\nOdrębnym i szczególnie istotnym problemem jest zapewnienie rejestracji w pojazdach,\\nktóre nie są własnością ośrodka egzaminowania.  W praktyce jedynym możliwym\\nrozwiązaniem będzie w wielu przypadkach zastosowanie przenośnego urządzenia\\nrejestrującego, montowanego przed rozpoczęciem egzaminu i zasilanego z instalacji\\nelektrycznej pojazdu, np. poprzez gniazdo 12 V.\\nNie można przy tym zagwarantować, że w każdym pojeździe podstawionym na egzamin\\ngniazdo takie będzie sprawne albo w ogóle dostępne. Powstaje zatem praktyczny problem,\\nczy w przypadku braku możliwości zasilenia urządzenia rejestrującego egzamin będzie mógł\\nzostać przeprowadzony, a jeżeli nie – kto będzie ponosił konsekwencje braku technicznej\\nmożliwości dokonania rejestracji.\\nProjektowana regulacja powinna jednoznacznie rozstrzygać takie sytuacje, ponieważ brak\\nmożliwości technicznych niezależny od egzaminatora i ośrodka egzaminowania nie powinien\\nprowadzić do odpowiedzialności egzaminatora ani automatycznie uniemożliwiać\\nprzeprowadzenia egzaminu.\\nNależy ponadto zwrócić uwagę na konieczność dostosowania przepisów wykonawczych do\\nprojektowanej zmiany. Zgodnie z § 7 ust. 1 pkt 3 rozporządzenia regulującego\\nprzeprowadzanie egzaminów:\\n„Urządzenie, o którym mowa w art. 54 ust. 1 ustawy: (...)\\n3) uniemożliwia ingerencję w zapis na informatycznym nośniku danych”.\\nW przypadku urządzeń rejestrujących zamontowanych na stałe w pojazdach egzaminacyjnych\\nspełnienie tego wymagania jest możliwe. Sytuacja wygląda jednak inaczej w przypadku\\nprzenośnych urządzeń wykorzystywanych w pojazdach podstawianych na egzamin.\\nPrzenośna kamera zasilana z gniazda pojazdu z natury rzeczy pozostaje urządzeniem, do\\nktórego użytkownik ma fizyczny dostęp. Możliwe jest odłączenie jej od źródła zasilania, a w \\f\\n\\nStrona 82 z 219\\n\\nzależności od konstrukcji urządzenia również użycie znajdujących się na nim przycisków\\nsterujących. Powstaje zatem zasadnicza wątpliwość, czy urządzenie tego rodzaju będzie\\nmogło zostać uznane za spełniające wymaganie określone w § 7 ust. 1 pkt 3 rozporządzenia.\\nNie można z jednej strony nakładać obowiązku rejestracji egzaminów w pojazdach, w których\\nze względów technicznych możliwe jest zastosowanie wyłącznie urządzeń przenośnych, a z\\ndrugiej utrzymywać wymagań technicznych skonstruowanych z myślą o urządzeniach\\nzamontowanych na stałe w pojazdach egzaminacyjnych.\\nW związku z powyższym Krajowe Stowarzyszenie Egzaminatorów proponuje:\\n1. wyłączenie obowiązku rejestracji obrazu i dźwięku na placu manewrowym podczas\\negzaminów w zakresie kategorii AM, A1, A2 i A;\\n2. wyłączenie kategorii T z obowiązku rejestracji albo wprowadzenie szczególnych zasad\\nrejestracji dla tej kategorii;\\n3. jednoznaczne uregulowanie sposobu postępowania w przypadku braku technicznej\\nmożliwości podłączenia lub zasilenia urządzenia rejestrującego w pojeździe\\npodstawionym na egzamin;\\n4. dostosowanie § 7 ust. 1 pkt 3 rozporządzenia do możliwości stosowania przenośnych\\nurządzeń rejestrujących, w szczególności poprzez zmianę lub usunięcie tego\\nwymagania w odniesieniu do urządzeń wykorzystywanych w pojazdach\\npodstawianych na egzamin.\\nWprowadzenie obowiązku rejestracji dla kolejnych kategorii prawa jazdy powinno zostać\\npoprzedzone określeniem takich wymagań technicznych, które będą możliwe do spełnienia w\\nrzeczywistych warunkach prowadzenia egzaminów państwowych.\\n Art. 1 pkt 19\\nlit. c projektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\nc) ust. 5 otrzymuje brzmienie:\\n\\n„5. Jeżeli egzamin jest przeprowadzany pojazdem:\\n\\n1) osoby niepełnosprawnej wymagającej przystosowania pojazdu do rodzaju\\nschorzenia,\\n2) bez pedału sprzęgła, jeżeli nie jest to pojazd będący w dyspozycji wojewódzkiego\\nośrodka ruchu drogowego \\f\\n\\nStrona 83 z 219\\n\\n– urządzenie, o którym mowa w ust. 1, zapewnia wojewódzki ośrodek ruchu\\ndrogowego.”;\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nKrajowe Stowarzyszenie Egzaminatorów uwzględniając rosnącą ilość egzaminów\\nprzeprowadzanych pojazdami bez pedału sprzęgła obawia się, iż proponowana zmiana\\nwygeneruje znaczący wzrost kosztów dla WORD-ów w postaci dodatkowych urządzeń oraz ich\\nobsługi. Na dzień dzisiejszy prawie wszystkie pojazdy nauki jazdy są wyposażone w kamery, a\\ndodatkowo wprowadza się obowiązek rejestracji egzaminów wewnętrznych. Brak możliwości\\nwykorzystania tego sprzętu na egzaminie, dublowanie kamer, wyłączanie tych należących do\\nośrodka szkolenia , a montowanie należących do ośrodka egzaminowania  nie znajduje\\nlogicznego uzasadnienia. W przypadku podstawienia pojazdu bez pedału sprzegła pojazd ten\\npowinien być wyposażony w kamerke przez Ośrodek szkolenia  tak jak kazdy inny  pojazd\\npodstawiany na egzamin kategorii  B.\\n\\n Art. 1 pkt 14\\nlit. e projektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nDyrektorów\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nUsunięcie ust. 3c z art. 51\\nUzasadnienie: Brak związku celu realizowania egzaminu na placu manewrowym z\\negzaminem praktycznym przeprowadzanym w ruchu drogowym.\\nStworzenie bezpośredniego zagrożenia dla zdrowia lub życia uczestników ruchu drogowego\\npodczas przeprowadzania części praktycznej egzaminu w ruchu drogowym nie ma związku\\nze sprawnością manewrowania pojazdem lub panowania nad nim podczas realizowania\\nzadań egzaminacyjnych na placu manewrowym Mając powyższe na względzie zasadnym jest\\npozostawienie jedynie ust. 3a i 3b w art. 51\\n Art. 1 pkt 14\\nlit. e projektu\\nustawy\\nOIGOSK,\\nLFEDERACJA,\\nPIGOSK\\nw lit. e wykreślić dodawany ust. 3c\\n„3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego\\nprzystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach\\nwydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu\\nlub zdrowiu uczestników ruchu drogowego – w takim przypadku osoba ta przystępuje\\nponownie do części praktycznej egzaminu państwowego w pełnym zakresie.”,\\n\\nUzasadnienie Naszym zdaniem propozycja aby przerwanie egzaminu praktycznego\\nprowadzonego w ruchu drogowym skutkowało koniecznością uzyskania ponownie \\f\\n\\nStrona 84 z 219\\n\\npozytywnego wyniku z części egzaminu realizowanego na placu manewrowym – nie ma\\nżadnego uzasadniania merytorycznego i ma charakter wyłącznie sankcyjny.\\n Art. 1 pkt 14\\nprojektu\\nustawy w\\nzakresie art.\\n51 ust. 3 pkt 1\\nustawy o\\nkierujących\\npojazdami\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPropozycja zmiany:\\nw lit. a skreśla się wyrazy „B1, B i AM (trójkołowiec)\\n\\nProponowana zmiana jest wynikiem zaproponowanej zmiany w samym procesie szkolenia.\\n\\nUzasadnienie:\\nBrak związku celu realizowania egzaminu na placu manewrowym z egzaminem praktycznym\\nprzeprowadzanym w ruchu drogowym.\\nStworzenie bezpośredniego zagrożenia dla zdrowia lub życia uczestników ruchu drogowego\\npodczas przeprowadzania części praktycznej egzaminu w ruchu drogowym nie ma związku\\nze sprawnością manewrowania pojazdem lub panowania nad nim podczas realizowania\\nzadań egzaminacyjnych na placu manewrowym\\nMając powyższe na względzie zasadnym jest pozostawienie jedynie ust. 3a i 3b w art. 51\\n Art. 1 pkt 14\\nlit. e projektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPropozycja zmiany:\\nUsunięcie ust. 3c z art. 51\\n\\nUzasadnienie:\\nBrak związku celu realizowania egzaminu na placu manewrowym z egzaminem praktycznym\\nprzeprowadzanym w ruchu drogowym.\\nStworzenie bezpośredniego zagrożenia dla zdrowia lub życia uczestników ruchu drogowego\\npodczas przeprowadzania części praktycznej egzaminu w ruchu drogowym nie ma związku\\nze sprawnością manewrowania pojazdem lub panowania nad nim podczas realizowania\\nzadań egzaminacyjnych na placu manewrowym\\nMając powyższe na względzie zasadnym jest pozostawienie jedynie ust. 3a i 3b w art. 51\\n Art. 1 pkt 15\\nprojektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPropozycja zmiany:\\npo art. 51 dodaje się art. 51a w brzmieniu:\\n– 12 –\\n„Art. 51a. 1. Zakazu, o którym mowa w art. 50 ust. 2 pkt 9, nie stosuje się, jeżeli\\negzamin nie doszedł do skutku z przyczyn niezależnych od osoby egzaminowanej.\\n2. W przypadku, o którym mowa w ust. 1, kandydatowi wyznacza się nowy termin\\negzaminu bez pobierania dodatkowej opłaty. Nowy termin może przypadać w tym samym \\f\\n\\nStrona 85 z 219\\n\\ndniu wyłącznie, gdy pozwalają na to warunki techniczne i organizacyjne wojewódzkiego\\nośrodka ruchu drogowego oraz kandydat wyrazi na to zgodę.”; - proponuje się wykreślić\\nzapis w zaproponowanym brzmieniu.\\n\\nUzasadnienie:\\nproponuje się wykreślić zapis w związku z uzasadnieniem i propozycją wykreślenia Art. 1 pkt\\n13\\n\\n Art. 1 pkt 15\\nprojektu\\nustawy\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n1. Ad. art. 1 pkt 15 projektu\\n- Przepis art. 1 pkt 16 lit. e projektu wprowadza zmiany w art. 52 UoKP, regulujące zasady\\nuznawania wyników egzaminu teoretycznego przez okres 24 miesięcy. Nie negując potrzeby\\ntakiej regulacji, chcemy zwrócić uwagę że zaproponowany okres wydaje się być zbyt długi.\\nNależy bowiem pamiętać, że mózg dorosłego człowieka zarządza pamięcią w sposób wysoce\\nekonomiczny. Informacje teoretyczne ze szkoleń trafiają najpierw do pamięci krótkotrwałej.\\nAby przeszły do pamięci długotrwałej, musi zajść proces konsolidacji. Jeśli mózg nie\\notrzymuje silnego sygnału, że dana wiedza jest krytyczna (czyli nie jest natychmiast używana\\ndo rozwiązywania bieżących problemów ani nie powtarza się cyklicznie), to traktuje ją jako\\nzbędny szum informacyjny i celowo ją usuwa, by nie przeciążać układu nerwowego.\\nPonieważ osoba ubiegająca się o uprawnienia, do momentu zdobycia tych uprawnień nie\\nbędzie posługiwała się zdobytą wiedzą teoretyczną w praktyce (uczestnicząc w ruchu\\ndrogowym jako kierowca), to w bardzo szybkim tempie dojdzie do jej wyparcia i utraty\\nodpowiednich kompetencji. Nie pogłębiając ze swej strony tego tematu, proponujemy\\nzapoznanie się z publikacjami i wynikami badań takimi jak: Hermann Ebbinghaus, \\\"Memory:\\nA Contribution to Experimental Psychology\\\" (1885), publikacje z obszaru Learning &\\nDevelopment (L&D), w tym m.in. publikowane statystyki przez organizacje takie, jak\\nAssociation for Talent Development (ATD), etc.\\n Art. 1 pkt 16\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 16 proponujemy skrócenie okresu do 12 miesięcy.\\n\\n    \\f\\n\\nStrona 86 z 219\\n\\nArt. 1 pkt 17 i\\n20 projektu\\nustawy\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n1. Ad. art. 1 pkt 17 i 20 projektu\\nPrzepisy art. 1 pkt 17 i 20 projektu wprowadzają zmiany w art. 53 ust. 4b oraz art. 56 ust. 2b-\\n2c UoKP. Nie negując tych rozwiązań, zwracamy jednocześnie uwagę, iż projekt ustawy nie\\nuwzględnia zmian, które ułatwiałyby prowadzenie szkolenia kierowców kategorii C i C+E\\nprzez szkoły branżowe, prowadzące kształcenie zawodowe/techniczne, pomimo że\\nodgrywają one istotną rolę w przygotowaniu przyszłych kierowców zawodowych. Z\\ninformacji posiadanych przez TLP wynika, iż obecnie szkoły te i technika nie mogą\\norganizować egzaminów na swoim terenie, nie mają ustawowego prawa do egzaminowania\\nna własnych pojazdach, nie korzystają z uproszczonych wymagań organizacyjnych, nie mają\\npreferencyjnego finansowania zakupu pojazdów do szkolenia, nie przewidziano dla nich\\nodrębnych rozwiązań ułatwiających uzyskanie prawa jazdy kategorii C oraz C+E. W ocenie\\nTLP, skoro projekt dopuszcza przeprowadzanie egzaminów państwowych na terenie\\njednostek wojskowych z wykorzystaniem należących do 21\\ntych jednostek pojazdów, to rozwiązaniem takim można byłoby objąć szkoły kształcące\\nprzyszłych kierowców zawodowych. Taka zmiana mogłaby zwiększyć dostępność szkolenia\\nna kategorię C oraz C+E, bez obniżania wymagań egzaminacyjnych.\\nDlatego też proponujemy:\\n• nadanie następującego brzmienia art. 53 ust. 4b UoKP:\\n\\n„4b. Egzamin państwowy w zakresie prawa jazdy kategorii C, C1, C+E oraz C1+E może być\\nprzeprowadzany również na terenie jednostki wojskowej lub szkoły prowadzącej kształcenie\\nw zawodzie związanym z transportem drogowym lub spedycją, w rozumieniu przepisów\\nustawy z dnia 14 grudnia 2016 r. – Prawo oświatowe (Dz. U. z 2025 r. poz. 1043, z późn. zm.),\\nz wykorzystaniem pojazdu pozostającego w dyspozycji odpowiednio tej jednostki lub szkoły,\\nspełniającego wymagania określone w przepisach wydanych na podstawie niniejszej\\nustawy.”,\\n• w art. 56 ust. 2b oraz ust. 2c UoKP, po wyrazach: „jednostce wojskowej”, dodaje się\\nwyrazy: „lub szkole prowadzącej kształcenie w zawodzie związanym z transportem\\ndrogowym lub spedycją, w rozumieniu ustawy dnia 14 grudnia 2016 r. – Prawo oświatowe\\n(Dz. U. z 2025 r. poz. 1043, z późn. zm.).”.\\n \\f\\n\\nStrona 87 z 219\\n\\n Art. 1 pkt 18\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\n13) W odniesieniu do art. 1 pkt 18 w odniesieniu do:\\na) art. 53b ust. 1 W naszej ocenie wskazujemy nie ten system teleinformatyczny który\\npowinien być wskazany. Jeżeli zachowujemy profil kandydata na kierowcę to można\\nzachować następujące brzmienie użyte zresztą w rozporządzeniu w sprawie egzaminowania:\\n\\n„Art. 53b. 1. Wojewódzki ośrodek ruchu drogowego aktualizuje profil kandydata na\\nkierowcę w centralnej ewidencji kierowców w zakresie pozytywnego wyniku części\\npraktycznej egzaminu państwowego uzyskanego na placu manewrowym, wraz z datą jego\\nuzyskania oraz wskazaniem kategorii prawa jazdy lub pozwolenia, której wynik dotyczy.”\\nTakie rozwiązanie pozostawia jako podstawowy dokument kandydata na kierowcę profil\\nkandydata na kierowcę.\\n\\nOdchodząc od szczegółów warto zauważyć, że także w tym przypadku w ustawie niema\\nżadnych odniesień do wpisywania czy przesyłania wyniku egzaminu i sposobu postępowania\\nz poszczególnymi wynikami poszczególnych części egzaminów. Jest to domena\\nrozporządzenia w sprawie egzaminowania tak jak opisywaliśmy w lit. c. Dlatego też należy\\nrozważyć przeniesienie do ustawy całości sposobu i zasad uzyskiwania wyników egzaminów,\\nalbo (co będzie prostsze) wykreślenie ww. przepisów z ustawy i przeniesienie ich, tak jak\\ndotychczas do rozporządzenia.\\n Art. 1 pkt 18\\nprojektu\\nustawy\\nOIGOSK,\\nLFEDERACJA,\\nPIGOSK\\nw art.53b ust.2 skreślić „2. Opłata za część praktyczną egzaminu państwowego\\nprzeprowadzaną na podstawie art.51 ust. 3a jest pobierana w tej samej wysokości jak opłata\\nza przeprowadzenie części praktycznej na podstawie art.51 ust. 3”.\\n\\nUzasadnienie Opłata powinna być pomniejszona z uwagi na mniejszy koszt ograniczonego\\nzakresu zadań egzaminacyjnych, a także dyspozycję przepisu art.56a ust.2. Analiza projektu\\nprowadzi do wniosku, że jego głównym celem jest zwiększenie kontroli nad procesem\\nszkolenia i egzaminowania. Świadczą o tym między innymi obowiązek stosowania systemów\\nGPS, rejestrowanie egzaminów wewnętrznych, rozszerzenie obowiązku stosowania kamer\\noraz tworzenie kolejnych mechanizmów nadzorczych. W naszej ocenie właściwszym\\nkierunkiem byłoby skoncentrowanie się na poprawie jakości szkolenia oraz bezpieczeństwa\\nruchu drogowego. Osiągnięcie tego celu wymaga przede wszystkim inwestowania w\\nedukację kandydatów na kierowców, systematyczne doskonalenie zawodowe instruktorów\\nnauki jazdy oraz egzaminatorów, a także tworzenie nowoczesnych i jednolitych programów \\f\\n\\nStrona 88 z 219\\n\\nszkolenia opartych na aktualnej wiedzy z zakresu bezpieczeństwa ruchu drogowego,\\npsychologii transportu oraz metodyki nauczania. Projekt zdaje się opierać na założeniu, że\\nzwiększenie nadzoru automatycznie przełoży się na poprawę jakości szkolenia. Tymczasem\\nnadmierna kontrola nie zastąpi dobrze przygotowanego instruktora, rzetelnego procesu\\ndydaktycznego ani wysokich standardów kształcenia. Jednocześnie proponowane\\nrozwiązania mogą być odbierane jako wyraz ograniczonego zaufania wobec środowiska\\ninstruktorów i egzaminatorów, mimo że zdecydowana większość z nich wykonuje swoje\\nobowiązki rzetelnie i zgodnie z obowiązującymi przepisami. Budowanie jakości systemu\\npowinno opierać się przede wszystkim na wzmacnianiu kompetencji jego uczestników, a nie\\nwyłącznie na rozbudowie mechanizmów kontrolnych. Dlatego warto rozważyć, aby większy\\nnacisk położyć na rozwój programów szkolenia kandydatów na kierowców, doskonalenie\\nzawodowe instruktorów i egzaminatorów oraz działania wspierające wysoką jakość procesu\\nkształcenia. To właśnie edukacja i profesjonalne przygotowanie uczestników systemu są\\nnajskuteczniejszym sposobem poprawy bezpieczeństwa na drogach. Najlepszymi\\nkontrolerami w systemie uzyskiwania uprawnień będą świadomi swoich praw i obowiązków\\nkursanci. Propozycje zmian nie uwzględnione w opiniowanym projekcie usta\\n\\nArt. 1 pkt 18\\nprojektu\\nustawy\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n• Ad. art. 1 pkt 18 projektu\\nRegulowanie szczegółowych czynności, związanych z wprowadzaniem danych przez\\nwojewódzkie ośrodki ruchu drogowego, na szczeblu ustawowym, wydaje się być sprzeczne z\\nzasadą minimalizmu legislacyjnego. Każdorazowa zmiana funkcjonalności systemu wymagać\\nbędzie w tym momencie decyzji Sejmu, Senatu i Prezydenta RP. Dlatego też uważamy, że\\nproponowane przepisy powinny znaleźć sią w odpowiednim akcie wykonawczym,\\nwydawanym przez ministra właściwego do spraw transportu\\n Art. 1 pkt 19\\nlit. c projektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nDyrektorów\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nUsunięcie treści:\\n„- urządzenie, o którym mowa w ust. 1 zapewnia wojewódzki ośrodek ruchu drogowego.”\\nUzasadnienie: Uwzględniając rosnącą ilość egzaminów przeprowadzanych pojazdami bez\\npedału sprzęgła proponowana zmiana wygeneruje znaczący wzrost kosztów dla WORD-ów\\nzwiązanych z nabyciem dodatkowych urządzeń oraz ich obsługi. Na dzień dzisiejszy prawie\\nwszystkie pojazdy nauki jazdy są wyposażone w kamery a dodatkowo wprowadza się\\nobowiązek rejestracji egzaminów wewnętrznych. Brak możliwości wykorzystania tego\\nsprzętu na egzaminie, dublowanie kamer, wyłączanie tych należących do OSK a montowanie\\nnależących do WORD nie znajduje logicznego uzasadnienia. \\f\\n\\nStrona 89 z 219\\n\\n Art. 1 pkt 19\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 19) c) ust. 5 otrzymuje brzmienie:\\nwyrazy „5. Jeżeli egzamin jest przeprowadzany pojazdem: ...”\\nproponujemy zastąpić wyrazami\\n„5. Przepisów ust. 1-2 nie stosuje się jeżeli egzamin jest przeprowadzany pojazdem: ...”\\n Art. 1 pkt 19\\nprojektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nProjektowane rozwiązanie wymaga ponownej oceny pod kątem jego efektywności oraz\\nproporcjonalności w stosunku do zakładanych celów.\\n\\nW przypadku egzaminów praktycznych przeprowadzanych w zakresie kategorii  innych niż\\nkat. B proponuje się rozważenie zastosowania indywidualnych kamer nasobnych (kamer\\nosobistych) używanych przez egzaminatorów zamiast wyposażania wszystkich pojazdów\\negzaminacyjnych w stacjonarne systemy rejestracji obrazu i dźwięku.\\n\\nRozwiązanie takie pozwoliłoby na istotne ograniczenie kosztów zakupu, montażu,\\nserwisowania oraz utrzymania systemów rejestracji w pojazdach wykorzystywanych do\\nprzeprowadzania egzaminów. Jednocześnie kamery nasobne umożliwiają rejestrację\\nprzebiegu egzaminu z perspektywy egzaminatora, co może stanowić równie wartościowy\\nmateriał dowodowy w postępowaniach wyjaśniających.\\n\\nZastosowanie tego rozwiązania zapewniłoby zaproponowaną w projekcie transparentność\\nprocesu egzaminowania oraz większą elastyczność organizacyjną, możliwość wykorzystania\\njednego urządzenia przez egzaminatora podczas egzaminów przeprowadzanych na różnych\\npojazdach oraz znacząco ograniczyłoby koszty wdrożenia i eksploatacji systemu rejestracji\\nbez uszczerbku dla realizacji celu projektowanej regulacji. Proponowane rozwiązanie\\nmogłoby uwzględniać również rejestrację egzaminu na pozwolenie.\\n\\nUzasadnienie:\\nObjęcie obowiązkiem rejestracji wszystkich egzaminów praktycznych bez egzaminu na\\npozwolenie będzie wiązało się z istotnym wzrostem kosztów związanych z zakupem,\\neksploatacją i serwisowaniem urządzeń rejestrujących, archiwizacją oraz zabezpieczeniem\\nznacznie większej liczby nagrań, a także obsługą organizacyjną i informatyczną całego\\nsystemu. Jednocześnie należy spodziewać się wzrostu liczby skarg na przebieg egzaminów,\\nco przełoży się na zwiększenie liczby postępowań wyjaśniających oraz kosztów ich\\nprowadzenia. \\f\\n\\nStrona 90 z 219\\n\\nJednocześnie brak jest podstaw do przyjęcia, że powszechna rejestracja egzaminów pozwoli\\nna jednoznaczne i obiektywne ustalenie stanu faktycznego w każdym przypadku. Materiał\\naudiowizualny, z uwagi na ograniczenia techniczne rejestracji, nie odzwierciedla w pełni pola\\nwidzenia egzaminatora i osoby egzaminowanej, nie pozwala na wierną ocenę odległości,\\nprędkości oraz wszystkich okoliczności mających znaczenie dla oceny przebiegu egzaminu, a\\ntakże nie obejmuje wszystkich zdarzeń i komunikatów występujących poza pojazdem. W\\nkonsekwencji nagrania, pomimo znacznych kosztów ich pozyskania i przechowywania, w\\nwielu przypadkach nie będą stanowiły wystarczającego materiału dowodowego do\\njednoznacznego rozstrzygnięcia zasadności wniesionej skargi.\\n\\nW związku z powyższym zasadność objęcia obowiązkiem rejestracji wszystkich egzaminów\\npraktycznych wymaga ponownej analizy pod kątem rzeczywistej skuteczności\\nprojektowanego rozwiązania oraz jego kosztów organizacyjnych i finansowych.\\n\\nObjęcie obowiązkiem rejestracji wszystkich egzaminów praktycznych, z wyłączeniem\\negzaminów na pozwolenie, może spowodować istotny wzrost liczby skarg dotyczących\\nprzebiegu i wyniku egzaminów. Dostępność materiału z rejestracji przebiegu egzaminu\\nbędzie sprzyjała częstszemu kwestionowaniu rozstrzygnięć egzaminatorów oraz zwiększeniu\\nliczby postępowań wyjaśniających prowadzonych przez marszałków województw.\\n\\nW konsekwencji realizacja projektowanego rozwiązania może wymagać zwiększenia\\nzasobów kadrowych urzędów marszałkowskich poprzez utworzenie dodatkowych etatów\\nprzeznaczonych do rozpatrywania skarg oraz analizy materiałów z rejestracji egzaminów.\\nOznacza to wzrost kosztów realizacji zadań zleconych z zakresu administracji rządowej, który\\npowinien zostać uwzględniony w Ocenie Skutków Regulacji oraz znaleźć odzwierciedlenie w\\nodpowiednim zwiększeniu wysokości dotacji celowej przekazywanej z budżetu państwa na\\nrealizację tych zadań.\\nProjektowane rozwiązanie nie będzie miało wpływu na poprawę bezpieczeństwa ruchu\\ndrogowego ani na podniesienie jakości procesu szkolenia i egzaminowania kandydatów na\\nkierowców. Rejestracja przebiegu egzaminu pełni wyłącznie funkcję dowodową.\\n \\f\\n\\nStrona 91 z 219\\n\\nJednocześnie doświadczenia związane z rozpatrywaniem skarg wskazują, że znaczna ich\\nczęść dotyczy okoliczności, których nie można jednoznacznie zweryfikować na podstawie\\nmateriału audiowizualnego sporządzonego zgodnie z obowiązującymi wymaganiami\\ntechnicznymi. Dotyczy to w szczególności subiektywnej oceny zachowania innych\\nuczestników ruchu, wzajemnej obserwacji, odległości, prędkości, warunków widoczności czy\\nkomunikacji odbywającej się poza polem rejestracji obrazu i dźwięku.\\nW konsekwencji rozszerzenie obowiązku rejestracji wszystkich egzaminów nie doprowadzi\\ndo wyeliminowania sporów dotyczących przebiegu egzaminu, natomiast wygeneruje istotne\\nkoszty organizacyjne i finansowe związane z rejestracją, przechowywaniem oraz analizą\\nmateriałów, których wartość dowodowa w wielu przypadkach pozostanie ograniczona.\\n\\n Art. 1 pkt 20\\nprojektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPrzepis ust. 2b nie wskazuje, kto i według jakich kryteriów ma ocenić, czy dana lokalizacja i\\npojazd zapewnia warunki do przeprowadzenia egzaminu państwowego porównywalne z\\nwarunkami występującymi na trasach egzaminacyjnych wykorzystywanych przez WORD.\\n\\nProjektowany przepis wymaga doprecyzowania warunków przeprowadzania egzaminu\\npaństwowego na terenie jednostki wojskowej lub innej infrastruktury pozostającej w jej\\ndyspozycji.\\n\\nNależy zwrócić uwagę, że nie każda jednostka wojskowa lub infrastruktura pozostająca w jej\\ndyspozycji dysponuje warunkami umożliwiającymi realizację wszystkich zadań\\negzaminacyjnych wymaganych przepisami prawa. W szczególności może nie posiadać\\ninfrastruktury odpowiadającej wymaganiom placu manewrowego lub warunków\\npozwalających na przeprowadzenie wszystkich elementów części praktycznej egzaminu.\\n\\nPonadto jednostki wojskowe często są zlokalizowane poza obszarami zabudowanymi lub w\\nznacznym oddaleniu od miejscowości, co może uniemożliwiać lub istotnie utrudniać\\nprzeprowadzenie części egzaminu wymagającej oceny umiejętności uczestnictwa w ruchu\\ndrogowym w typowych warunkach drogowych, obejmujących m.in. skrzyżowania, przejścia\\ndla pieszych, sygnalizację świetlną, strefy ograniczonej prędkości czy ruch o odpowiednim\\nnatężeniu. \\f\\n\\nStrona 92 z 219\\n\\nW związku z powyższym proponuje się uzależnienie możliwości przeprowadzania egzaminów\\nna terenie jednostki wojskowej od wcześniejszego potwierdzenia przez właściwy\\nwojewódzki ośrodek ruchu drogowego, że infrastruktura oraz lokalizacja wskazane przez\\njednostkę wojskową umożliwiają realizację pełnego zakresu egzaminu państwowego\\nzgodnie z wymaganiami określonymi w ustawie i przepisach wykonawczych.\\n\\nArt. 1 pkt 20\\nprojektu\\nustawy\\n\\nMałopolskie\\nStowarzyszenie\\nNauczycieli\\nKształcących\\nKierowców\\n\\nUwaga 6. Doprecyzowanie zasad przeprowadzania egzaminu państwowego na wniosek\\njednostki wojskowej (art. 1 pkt 20 projektu; projektowane art. 56 ust. 2b i 2c)\\nTreść uwagi: Popierając cel regulacji, którym jest usprawnienie procesu uzyskiwania\\nuprawnień do kierowania pojazdami przez żołnierzy, postulujemy doprecyzowanie\\nprojektowanego art. 56 ust. 2b poprzez jednoznaczne wskazanie podmiotu\\nprzeprowadzającego egzamin, warunków, jakie muszą spełniać sala egzaminacyjna i\\nstanowiska egzaminacyjne wraz z dostępem do systemu teleinformatycznego, oraz zasady, że\\nczęść praktyczna egzaminu w zakresie jazdy w ruchu drogowym odbywa się na drogach\\npublicznych.\\nProblem: Projektowany przepis został sformułowany w sposób zbyt ogólny, ponieważ nie\\nwskazuje, czy egzamin przeprowadzają egzaminatorzy zatrudnieni w wojewódzkim ośrodku\\nruchu drogowego, czy inne osoby posiadające uprawnienia egzaminatora, nie określa\\nwymagań dla sali egzaminacyjnej i stanowisk egzaminacyjnych niezbędnych do\\nprzeprowadzenia części teoretycznej, w tym dostępu do systemu teleinformatycznego z bazą\\npytań egzaminacyjnych oraz możliwości wprowadzenia wyniku egzaminu do systemu, a\\nsformułowanie o przeprowadzeniu egzaminu na terenie jednostki wojskowej lub innej\\ninfrastruktury pozostającej w jej dyspozycji może sugerować, że również jazda w ruchu\\ndrogowym miałaby odbywać się na terenie jednostki, którego infrastruktura drogowa, z uwagi\\nna ograniczoną sieć dróg wewnętrznych i znikome natężenie ruchu, nie pozwala na rzetelną i\\nporównywalną z egzaminami przeprowadzanymi w wojewódzkich ośrodkach ruchu\\ndrogowego ocenę zachowania kandydata w rzeczywistym ruchu drogowym, a konieczność\\ndojazdu do najbliższych dróg spełniających wymagania egzaminacyjne mogłaby wydłużać\\negzamin ponad przewidziany czas i zaburzać organizację czasu pracy egzaminatorów. Brak\\ntych regulacji może prowadzić do wątpliwości interpretacyjnych oraz podważać\\nporównywalność procesu egzaminowania w skali kraju. \\f\\n\\nStrona 93 z 219\\n\\nPropozycja zmiany zapisu: W art. 1 pkt 20 projektu proponujemy, aby projektowany art. 56\\nust. 2b otrzymał brzmienie:\\n„2b. Na wniosek jednostki wojskowej prowadzącej szkolenie żołnierzy na potrzeby Sił\\nZbrojnych Rzeczypospolitej Polskiej egzamin państwowy może być przeprowadzony\\nprzez wojewódzki ośrodek ruchu drogowego, przez zatrudnionych w nim\\negzaminatorów, na terenie tej jednostki wojskowej lub innej infrastruktury\\npozostającej w jej dyspozycji, z wykorzystaniem pojazdu wskazanego przez tę\\njednostkę, spełniającego wymagania, o których mowa w art. 24, przy czym część\\npraktyczną egzaminu w zakresie jazdy w ruchu drogowym przeprowadza się na drogach\\npublicznych.”\\noraz aby po projektowanym ust. 2c dodać ust. 2d w brzmieniu:\\n„2d. Przeprowadzenie egzaminu państwowego w sposób określony w ust. 2b wymaga\\nzapewnienia przez jednostkę wojskową sali egzaminacyjnej oraz stanowisk\\negzaminacyjnych spełniających warunki określone w przepisach wydanych na\\npodstawie art. 66 ust. 1, wraz z dostępem do systemu teleinformatycznego, o którym\\nmowa w art. 51 ust. 2a pkt 1, umożliwiającym przeprowadzenie części teoretycznej\\negzaminu państwowego oraz wprowadzenie wyniku egzaminu, a także zapewnienia\\negzaminatorom warunków pracy odpowiadających warunkom obowiązującym w\\nwojewódzkim ośrodku ruchu drogowego.”\\n\\n Art. 1 pkt 20\\nprojektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nZaproponowany przepis ust. 2c - Zapis pozostaje zbyt ogólny.\\n\\nNależałoby doprecyzować, jakie koszty ponosi jednostka wojskowa, w szczególności czy\\nobejmują one koszty dojazdu egzaminatora do miejsca przeprowadzenia egzaminu, udział w\\nkosztach jego wynagrodzenia lub inne koszty związane z organizacją i przeprowadzeniem\\negzaminu.\\n\\nPonadto zasadne byłoby określenie wymagań, jakie musi spełniać miejsce przeprowadzenia\\negzaminu, albo jednoznaczne wskazanie, czy jednostki wojskowe są zwolnione ze\\nstosowania warunków i trybu przeprowadzania egzaminów określonych dla osób cywilnych. \\f\\n\\nStrona 94 z 219\\n\\n Art. 1 pkt 20\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 20 proponujemy skreślić.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\n\\nPolska\\nWytwórnia\\nPapierów\\nWartościowych\\nS.A.\\nWyjaśnienia wymaga, z jakiego powodu projektodawca zamierza wprowadzić do ustawy\\nsystem teleinformatyczny dostarczany przez ministra właściwego do spraw informatyzacji\\nsłużący do opracowywania i weryfikowania pytań egzaminacyjnych na prawo jazdy (koszt\\nbudowy takiego systemu to - zgodnie z informacją zawartą w OSR - 7 050 000 zł).\\n\\nWymaga podkreślenia, że już obecnie system do weryfikacji pytań istnieje i jest nieodpłatnie\\nudostępniany przez PWPW S.A. System ten jest zgodny z przepisami ustawy i spełnia\\nwszystkie wymagania i oczekiwania Komisji do spraw weryfikacji i rekomendacji pytań\\negzaminacyjnych. Istnieje możliwość, aby do istniejącego już systemu do weryfikacji pytań\\nwprowadzić mechanizmy dynamicznego generowania pytań, zgodnego z przepisami\\ndyrektywy Parlamentu Europejskiego i Rady (UE) 2025/2205 z dnia 22 października 2025 r. w\\nsprawie praw jazdy, zmieniająca rozporządzenie Parlamentu Europejskiego i Rady (UE)\\n2018/1724\\ni dyrektywę Parlamentu Europejskiego i Rady (UE) 2022/2561 oraz uchylająca dyrektywę\\n2006/126/WE Parlamentu Europejskiego i Rady i rozporządzenie Komisji (UE) nr 383/2012.\\n\\nPWPW S.A. jest w stanie zapewnić system opisany\\nw projekcie ustawy poprzez modernizację istniejącego rozwiązania. Koszt takiej\\nmodernizacji będzie zdecydowanie niższy niż koszt budowy nowego systemu\\nteleinformatycznego przez ministra właściwego do spraw informatyzacji, który - według\\ninformacji zawartych w Ocenie Skutków Regulacji - wynosi 7 050 000 zł.\\n\\nProjektowane brzmienie art. 57ac ust. 1 ustawy powinno otrzymać brzmienie:\\n \\f\\n\\nStrona 95 z 219\\n\\n„1. Centrum Egzaminowania opracowuje lub weryfikuje pytania egzaminacyjne stosowane\\nna egzaminie państwowym, egzaminach teoretycznych, o których mowa w art. 33 ust. 1 pkt\\n7, art. 58 ust. 1 pkt 7 i art. 117 ust. 2 pkt 7, oraz testach kwalifikacyjnych, o których mowa w\\nart. 39b ust. 3 ustawy z dnia 6 września 2001 r.\\no transporcie drogowym, w systemie teleinformatycznym zapewnionym przez wytwórcę\\npraw jazdy, kart kwalifikacji kierowcy i pozwoleń na kierowanie tramwajem, z którym jest\\nzintegrowany system teleinformatyczny, o którym mowa w art. 51 ust. 2a pkt 1.”.\\n\\nArt. 1 pkt 22\\nprojektu\\nustawy\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka Polska\\n\\n1. Ad. art. 1 pkt 22 projektu,\\nNie negując idei powołania odpowiedniego podmiotu odpowiadającego za zakres spraw,\\nprzypisanych w projekcie do proponowanego „Centrum egzaminowania”, TLP krytycznie\\nocenia koncepcję utworzenia tego „podmiotu” w strukturze organizacyjnej Instytutu\\nTransportu Samochodowego (ITS). Projektowane rozwiązanie nie określa w sposób\\nprecyzyjny statusu prawnego Centrum Egzaminowania, jego miejsca w systemie podmiotów,\\nrealizujących powierzone zadania publiczne, ani relacji, pomiędzy Centrum, dyrektorem\\nInstytutu Transportu Samochodowego i ministrem właściwym do spraw transportu. Nasze\\nzastrzeżenia dotyczą 10 wskazanych poniżej obszarów.\\nPo pierwsze, Centrum Egzaminowania nie jest samodzielnym organem administracji\\npublicznej. Z uzasadnienia projektowanych zmian wynika, że ma ono funkcjonować w\\nstrukturze organizacyjnej Instytutu Transportu Samochodowego. Oznacza to, że nie będzie\\nani odrębną państwową osobą prawną, ani odrębnym organem administracji publicznej, nie\\nbędzie posiadało osobowości prawnej, ani jakiejkolwiek odrębności organizacyjnej i\\nfinansowej od ITS. Co więcej, nie będzie nawet funkcjonowało w ramach urzędu\\nobsługującego organ administracji publicznej, np. w strukturach ministerstwa, tylko będzie\\nstanowiło komórkę organizacyjną w strukturze ITS. W tym miejscu pragniemy zaznaczyć, iż\\nITS jest instytutem badawczym, działającym na podstawie m.in. ustawy z dnia 30 kwietnia\\n2010 r. o instytutach badawczych, co oznacza, że Centrum Egzaminowania, jako wewnętrzna\\njednostka ITS, będzie mogła funkcjonować wyłącznie w ramach osobowości prawnej\\nInstytutu, jego struktury organizacyjnej, planu działalności, planu finansowego oraz\\nkompetencji dyrektora ITS. Nie będzie natomiast traktowana, jako podmiot istniejący\\nniezależnie od ITS. Tymczasem projekt posługuje się nazwą „Centrum Egzaminowania” w \\f\\n\\nStrona 96 z 219\\n\\nsposób sugerujący istnienie odrębnej instytucji publicznej, której bezpośrednio przypisuje się\\nustawowe zadania i kompetencje. Powstaje w ten sposób konstrukcja hybrydowa: Centrum\\nnie jest organem ani osobą prawną, lecz jednocześnie projekt traktuje je jak samodzielnego\\nadresata ustawowych norm kompetencyjnych. Jest to rozwiązanie zdecydowanie wadliwe\\nustrojowo i legislacyjnie.\\nPo drugie, kompetencje powinny zostać powierzone ITS, a nie jego wewnętrznej komórce,\\ntj. jeżeli ustawodawca zamierza powierzyć zadania związane z opracowywaniem i\\nweryfikacją pytań egzaminacyjnych Instytutowi Transportu Samochodowego, to adresatem\\nnorm ustawowych w tym zakresie powinien być sam Instytut, reprezentowany przez jego\\ndyrektora, a nie nieposiadające podmiotowości prawnej Centrum Egzaminowania,\\nstanowiące komórkę w wewnętrznej strukturze organizacyjnej ITS. Jeżeli zatem projekt\\nmiałby zobowiązać ITS do wyodrębnienia w swojej strukturze komórki organizacyjnej\\nobsługującej zadania związane z bazą pytań egzaminacyjnych, to należy wyraźnie oddzielić\\npodmiot, któremu ustawa powierza zadanie publiczne, czyli ITS, organ osoby prawnej\\nodpowiedzialny za jego wykonanie, czyli dyrektora ITS oraz wewnętrzną komórkę\\norganizacyjną wykonującą czynności materialne i eksperckie, czyli Centrum Egzaminowania.\\nTymczasem, projektowane rozwiązania, nie przewidują takiego rozróżnienia, a w\\nkonsekwencji nie wiadomo, czy za działania Centrum odpowiada dyrektor ITS, kierownik\\nCentrum, minister właściwy do spraw transportu, czy też samo Centrum, które jednak nie\\nposiada zdolności prawnej ani zdolności do czynności prawnych. do ponoszenia\\nodpowiedzialności.\\nPo trzecie, nie jest określona relacja Centrum z ustawowymi organami ITS. Zgodnie z ww.\\nustawą o instytutach badawczych, organami instytutu są dyrektor oraz rada naukowa. To\\ndyrektor zarządza instytutem, reprezentuje go na zewnątrz i odpowiada za jego działalność.\\nW tym kontekście projekt nie wyjaśnia natomiast: kto powołuje i odwołuje kierownika\\nCentrum Egzaminowania, jakie wymagania musi spełniać kierownik Centrum, czy kierownik\\ndziała z upoważnienia dyrektora ITS, czy posiada własne ustawowe kompetencje, kto jako\\nosoba fizyczna zatwierdza pytania egzaminacyjne i ponosi odpowiedzialność za ich zgodność\\nz prawem, czy dyrektor ITS może ingerować w treść pytań, podstaw programowych oraz\\ninnych dokumentów opracowywanych przez Centrum, czy rada naukowa ITS posiada\\njakiekolwiek kompetencje w stosunku do działalności Centrum, jaki jest zakres nadzoru\\nministra nad poszczególnymi czynnościami Centrum, w jakim trybie można kwestionować\\nrozstrzygnięcia, działania lub zaniechania Centrum i jaką formę będą miały takie \\f\\n\\nStrona 97 z 219\\n\\nrozstrzygnięcia (postanowień, decyzji, zarządzeń, uchwał). W tym kontekście z treści\\nprojektowanego art. 57aa ust. 1 UoKP wynika jedynie wewnętrzne umiejscowienie Centrum,\\na nie to co najważniejsze, tj. status prawny i pozycja wobec innych podmiotów i organów\\nadministracji.\\nPo czwarte, proponowane rozwiązanie wprowadza ryzyko powierzenia kompetencji\\npublicznych podmiotowi niebędącemu organem, a opracowywanie i aktualizowanie pytań\\nwykorzystywanych podczas egzaminu państwowego na prawo jazdy czy dla przyszłych\\nkierowców zawodowych nie jest zwykłą działalnością naukową lub ekspercką. Pytania te\\nwspółkształtują treść państwowego egzaminu, od którego zależy możliwość uzyskania\\nuprawnienia do kierowania pojazdami albo wykonywania zawodu kierowcy. W tym\\nkontekście, jeszcze poważniejsze wątpliwości wywołuje przewidziane w art. 57aa ust. 2 pkt 7\\nUoKP, powierzenie Centrum opracowywania i publikowania „podstaw programowych”\\nszkoleń, które zgodnie z uzasadnieniem mają być dokumentami wiążącymi i określać cele\\nedukacyjne, obowiązkowe treści oraz minimalne efekty uczenia się. Jeżeli dokument\\nopracowywany przez Centrum ma kształtować treść obowiązków ośrodków szkolenia\\nkierowców, instruktorów, wykładowców, ośrodków doskonalenia techniki jazdy lub innych\\npodmiotów, to nie może być traktowany jedynie jako materiał ekspercki albo wewnętrzny\\ndokument ITS. Normy powszechnie obowiązujące, określające prawa i obowiązki\\nprzedsiębiorców lub innych podmiotów spoza administracji publicznej, powinny wynikać\\nprzede wszystkim z ustawy, a nie powinny być ustanawiane przez komórkę organizacyjną\\ninstytutu badawczego w drodze publikacji dokumentu na jego stronie internetowej (swoją\\ndrogą zwaną w projekcie „stroną podmiotową” – art. 57aaust. 2 pkt 4 UoKP, czy art. 57ae\\nUoKP). W tym zakresie, wątpliwości TLP budzi zgodność proponowanych rozwiązań z\\nkonstytucyjnym systemem źródeł prawa oraz zasadą legalizmu, zgodnie z którą organy\\nwładzy publicznej działają na podstawie i w granicach prawa. Centrum może przygotowywać\\nprojekty podstaw programowych, analizy i rekomendacje, natomiast dokument o\\ncharakterze wiążącym powinien zostać ustanowiony przez właściwy organ administracji\\npublicznej w formie przewidzianej prawem.\\nPo piąte, projekt nie wprowadza żadnych rozwiązań wobec Centrum, na wypadek\\nlikwidacji, przekształcenia albo reorganizacji ITS, co w ocenie TLP jest istotnym\\nmankamentem projektu, który całkowicie pomija skutki możliwych i legalnych zmian\\norganizacyjnych dotyczących Instytutu Transportu Samochodowego, dokonanych na\\npodstawie ww. ustawy o instytutach badawczych. Zgodnie z art. 7 tej ustawy ITS może \\f\\n\\nStrona 98 z 219\\n\\nzostać połączony z innym instytutem, podzielony, zreorganizowany, przekształcony w\\ninstytucję gospodarki budżetowej, zlikwidowany, jeżeli minister nadzorujący (właściwy do\\nspraw transportu) uzna takie działanie za uzasadnione merytorycznie, organizacyjnie lub\\nfinansowo. Oznacza to, że istnienie ITS w obecnym kształcie nie jest ustawowo\\nzagwarantowane. Oznacza to, że projekt wiąże funkcjonowanie kluczowego elementu\\npaństwowego systemu egzaminowania - Centrum Egzaminowania - z instytutem\\nbadawczym, nie przewidując: następstwa prawnego w zakresie zadań Centrum, przejęcia\\nbazy pytań egzaminacyjnych, przejęcia praw autorskich, dokumentacji i danych, kontynuacji\\nzatrudnienia ekspertów, przejęcia środków pochodzących z opłat egzaminacyjnych,\\nzapewnienia ciągłości działania systemu teleinformatycznego, wskazania podmiotu\\nodpowiedzialnego za aktualizowanie pytań w okresie reorganizacji albo likwidacji ITS! Co\\nwięcej, projekt nie zawiera mechanizmu, pozwalającego ministrowi właściwemu do spraw\\ntransportu, przenieść zadania Centrum do innego podmiotu ani przepisu, zgodnie z którym\\nzadania te z mocy prawa przechodziłyby na następcę prawnego ITS! W konsekwencji,\\nreorganizacja instytutu mogłaby zagrozić ciągłości państwowych egzaminów na prawo jazdy\\ni egzaminów dotyczących kwalifikacji zawodowych kierowców. W ocenie TLP, nie można\\nzaakceptować sytuacji, w której trwałość wykonywania zadań o podstawowym znaczeniu\\npublicznym zależy od dalszego istnienia ITS jako instytutu badawczego, bez ustanowienia\\nustawowych gwarancji sukcesji i ciągłości tworzonego podmiotu i powierzonych mu zadań!\\nPo szóste, projekt nie wskazuje charakteru i statusu zadań wykonywanych przez Centrum\\nEgzaminowania w ramach ITS. Przepisy ww. ustawy o instytutach badawczych umożliwiają\\nprowadzenie działalności innej niż naukowa, badawcza, rozwojowa, itd., jednakże pod\\nwarunkiem wyodrębnienia jej pod względem finansowym i rachunkowym. Ustawa\\ndopuszcza również nałożenie na instytut zadania z zakresu administracji rządowej. W tym\\nkontekście projekt powinien jednoznacznie rozstrzygnąć, czy zadania Centrum są zadaniami\\nz zakresu administracji rządowej, nałożonymi na ITS na podstawie przepisów szczególnych i\\npowinien określić nie tylko zasady ich finansowania, ale także nadzór i sprawozdawczość.\\nStatut ITS, mający zastosowanie w tym zakresie, nie może zastępować ustawowej regulacji\\nkompetencji podmiotu wykonującego odpowiednie zadania publiczne.\\nPo siódme, nie wskazano nadzoru nad Centrum Egzaminowania, tym samym\\nodpowiedzialność za bazę pytań może zostać rozmyta. Z treści uzasadnienia do projektu\\nwynika, iż przewiduje się zwiększenie niezależności procesu opracowywania pytań\\negzaminacyjnych, ale nie wyjaśnia się przy tym, od kogo Centrum ma być niezależne i w \\f\\n\\nStrona 99 z 219\\n\\njakim zakresie. Tymczasem, jeżeli Centrum ma być komórką wewnętrzną ITS, pozostaje\\norganizacyjnie podporządkowane dyrektorowi ITS, którego z kolei nadzoruje minister\\nwłaściwy do spraw transportu. W takiej sytuacji, projekt ustawy powinien jednoznacznie\\nokreślić: kto i czy minister ten zatwierdza bazę pytań lub podstawy programowe, czy może\\nnakazać zmianę pytania niezgodnego z prawem, czy może przeprowadzać kontrolę Centrum,\\nw tym zażądać dokumentów i wyjaśnień, jakie posiada narzędzia prawne sprzeciwiające się\\nrozstrzygnięciom Centrum, kto będzie odpowiadać za szkodę wynikającą z wadliwego\\npytania egzaminacyjnego, jaki będzie tryb usunięcia danego pytania z bazy, kto będzie\\nodpowiadał za bazę pytań i całokształt działalności Centrum – Minister Infrastruktury,\\nDyrektor ITS, kierownik Centrum, Rada Konsultacyjna, czy osoby wchodzące w skład\\nCentrum i w nim pracujące? 24\\nPo ósme, nie jest zdefiniowany status Rady Konsultacyjnej, działającej na podstawie\\nprojektowanego art. 57ad ust. 1-3 UoKP. Projektodawca wskazuje, iż ma być to organ\\nspołeczny o charakterze doradczo-opiniodawczym i ma składać się z ekspertów,\\nwskazywanych przez ministra właściwego do spraw transportu w drodze zarządzenia.\\nPomijając zgodność z prawem takiej konstrukcji składu Rady, nie jest wskazane wprost: kto\\npowołuje i odwołuje członków Rady, na jaką kadencję są powoływani, jakie są przesłanki ich\\nodwołania, czy członkowie składają oświadczenia dotyczące konfliktu interesów, czy opinie\\nRady są jawne, czy opinia Rady jest obowiązkowa przed wprowadzeniem pytania do bazy,\\nczy Centrum może odstąpić od opinii Rady, czy członkowie odpowiadają za zachowanie\\npoufności pytań egzaminacyjnych. W ocenie TLP, biorąc pod uwagę założenia\\nprojektowanych zmian, zgodnie z którymi Rada ma stanowić gwarancję jakości i\\nniezależności pytań egzaminacyjnych, zasady jej funkcjonowania powinny zostać określone\\nw ustawie, a nie pozostawione wewnętrznym regulacjom ITS.\\nPo dziewiąte, w ocenie TLP nie jest jasny sposób finansowana Centrum Egzaminacyjnego,\\nokreślony w art. 57c ust. 1 UoKP. Projekt zakłada finansowanie Centrum ze środków\\npochodzących z opłat za część teoretyczną egzaminu państwowego, uznając takie\\nrozwiązanie stabilnym źródłem finansowania, nie przedstawiając jednak dokładnego modelu\\nprzepływu środków, sposobu obliczania należności ITS, ani kontroli ich wydatkowania. Co\\nwięcej, projekt przewiduje wpisaną na sztywną kwotę 2 zł, co oznacza, iż jakakolwiek\\npotrzeba jej zmiany, zarówno podwyższenia, czy też zmniejszenia, będzie związana z\\nkoniecznością nowelizacji UoKP! Wydaje się, iż w tym zakresie, racjonalnym rozwiązaniem\\nbyłoby wprowadzenie procentowego odniesienia do wiarygodnych, adekwatnych do stanu \\f\\n\\nStrona 100 z 219\\n\\ngospodarki wskaźników, dotyczących wynagrodzeń w gospodarce, określanych przez Główny\\nUrząd Statystyczny. W tej sytuacji, projekt powinien dodatkowo wskazywać, czy: czy środki\\nfinansowe będą stanowiły przychód ITS, kto będzie pobierał i przekazywał część opłaty,\\nwedług jakiego algorytmu zostanie ustalona jej wysokość w przypadku kolejnych zmian, czy\\nwysokość finansowania będzie powiązana z rzeczywistymi kosztami Centrum, czy środki\\nbędą mogły być przeznaczane na inne zadania ITS, kto będzie kontrolował ich wykorzystanie,\\nco stanie się ze środkami w razie likwidacji lub przekształcenia ITS?\\nPo dziesiąte, projekt nie przewiduje procedury weryfikacji działań Centrum, w\\nszczególności zgłaszania i rozpatrywania zastrzeżeń dotyczących wadliwych pytań\\negzaminacyjnych, pytań niezgodnych z obowiązującym stanem prawnym, pytań\\nzawierających więcej niż jedną prawidłową odpowiedź, ewentualnych błędów w\\ntłumaczeniach, niezgodności materiałów audiowizualnych z rzeczywistym przebiegiem\\nsytuacji drogowej, rozbieżności pomiędzy pytaniem a przyjętą podstawą programową. W\\nocenie TLP, osoba egzaminowana powinna mieć możliwość zakwestionowania pytania, które\\nmogło mieć wpływ na wynik egzaminu. Projekt nie określa jednak, czy rozpatrzenie takiego\\nzastrzeżenia będzie czynnością Centrum, Dyrektora ITS, marszałka województwa, ministra\\nwłaściwego do spraw transportu, czy nawet sądu administracyjnego. W ocenie TLP, brak\\ntakiej procedury może podważać deklarowaną w uzasadnieniu transparentność systemu.\\nReasumując, TLP proponuje utworzenie samodzielnej osoby prawnej, której przypisane\\nzostaną odpowiednie kompetencje, albo przypisanie tych kompetencji bezpośrednio\\ninstytutowi badawczemu, wskazanemu przez ministra właściwego do spraw transportu.\\nOczywiście, przy jednoczesnym uregulowaniu wszystkich wymaganych kwestii tak, aby\\nusunąć wskazane wyżej zastrzeżenia.\\n1. W odniesieniu do pkt 14 powyżej, wyjaśnienia wymagają także następujące\\nkwestie:\\n\\n- art. 57aa ust. 2 pkt 2 oraz art. 57ab ust. 1 UoKP – co odróżnia podmioty zewnętrzne od\\nosób prywatnych, tj. czy chodzi tutaj o różnice w formie działalności, np. te pierwsze to\\npodmioty zorganizowane, np. spółki, a te drugie to osoby fizyczne, a także w oparciu o co, o\\njakie przesłanki będzie weryfikacja propozycji pytań egzaminacyjnych; 25\\n \\f\\n\\nStrona 101 z 219\\n\\n- art. 57aa ust. 2 pkt 7 UoKP – dlaczego użyto okres lenia „transport drogowy”, podczas gdy\\npowinno być „przewóz drogowy”, co wynika choćby ze struktury przepisów i z tytułów\\nrozdziało w ustawy z dnia 6 września 2001 r. o transporcie drogowym;\\n- art. 57ab ust. 3 UoKP, zakłada odesłanie do weryfikacji pytań, podczas gdy w przepisie, do\\nktórego następuje to odesłanie, jest mowa o aktualizacji pytań ;\\n- art. 57ab ust. 4 UoKP – dlaczego podmiotom przekazującym pytania nie przysługuje z tego\\ntytułu wynagrodzenie, wobec faktu, iż jest to przecież praca wykonana przez takie podmioty;\\n- art. 57ac ust. 1 i następne UoKP – dla określeń dotyczących zakresu odesłania do pytań\\negzaminacyjnych, należałoby sformułować stosowny skrót, celem uniknięcia powtarzania\\npełnego tekstu w kolejnych przepisach projektowanej ustawy.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nPracodawców\\nTransportu\\nDrogowego\\nBardzo dobrym krokiem jest propozycja powołania Centrum Egzaminowania w Instytucie\\nTransportu Samochodowego jednostce podległej Ministrowi. Tak koncepcja była już\\nomawiana kiedyś na forach branżowych i w ramach kierownictwa resortu. Szkoda jednak, że\\nobecnie autorzy projektujący rozwiązania prawne zatrzymują się tylko na delegowaniu do\\nITS zadań merytorycznych: podstawy programowe, cele szkoleniowe, pytania egzaminacyjne\\ni statystyki. Brakuje kolejnego kroku nowoczesne współfinansowane przez Państwo Centra\\nSzkoleniowe, centralnie zarządzana struktura egzaminacyjna podległa Centrum\\nEgzaminowania. Może pora zlikwidować polityczna podległość WORD i postawić na\\nmerytoryczną wartość szkolenia i oceny umiejętności kandydatów na kierowców. WORD\\npoczątkowo jako wojewódzkie miejsca/centra egzaminowania to pomysł z ubiegłego wieku\\nefekt wpływu na jakość szkolenia i poprawę BRD maja już dawno za sobą. Dobra\\ninfrastruktura oraz większość osób zatrudnionych tam osób o wysokich kompetencjach w\\nobecnych ramach prawnych działania i egzaminowania nie przekłada się na właściwa ocenę i\\nkwalifikację kandydatów do bezpiecznego uczestniczenia w ruchu drogowym\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 22 – popierając ideę stworzenia Centrum Egzaminowania proponujemy:\\n1)  zmianę nazwy na: Agencja ds. Standardów Kierowania Pojazdami,\\n2)  zmianę koncepcji jej funkcjonowania na standard analogicznych agencji rządowych,\\n3)  zmianę zasad finansowania ww. Ich źródłem powinien być np. 1,5 % od każdego\\negzaminu (teoretycznego i praktycznego ) dla kandydatów na kierowców, instruktorów,\\negzaminatorów, instruktorów techniki jazdy oraz testu kwalifikacyjnego). \\f\\n\\nStrona 102 z 219\\n\\n4) poszerzenie zadań ww. instytucji na m.in. określanie standardów przeprowadzania i\\norganizacji egzaminów, w tym systemu/ systemów teleinformatycznych.\\n\\nArt. 1 pkt 22\\nprojektu\\nustawy\\n\\nFundacja\\nZapobiegania\\nWypadkom\\nDrogowym\\n\\nEksperci naszej Fundacji zwracają uwagę na brak szczegółów i wytycznych dotyczących\\nfunkcjonowania i struktury planowanego Centrum Egzaminowania. Nie zostały określone\\nkompetencje osób, które będą weryfikowały, oceniały, redagowały pytania, nie jest znany\\njego skład ilościowy i zasady funkcjonowania. Jest to jeden z kluczowych elementów,\\nszczególnie w kontekście niedawnych perturbacji związanych z egzaminami teoretycznymi\\nna prawo jazdy.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy w\\nzakresie art.\\n57ab ustawy o\\nkierujących\\npojazdami\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nPkt 4 i 5 - Brak regulacji odpłatności może powodować, że baza pytań będzie zasilana\\nwyłącznie przez administrację, co ograniczy dostęp do wiedzy praktycznej osób\\nwykonujących zawód instruktora, egzaminatora czy kierowcy zawodowego\\nPowyższy zapis może zniechęcać podmioty zewnętrzne oraz osoby prywatne posiadające\\nwiedzę i doświadczenie w zakresie szkolenia, egzaminowania oraz kierowania pojazdami do\\naktywnego współtworzenia i rozwijania bazy pytań egzaminacyjnych poprzez przekazywanie\\nprofesjonalnie opracowanych pytań testowych.\\nW przypadku braku zainteresowania wykorzystaniem przedłożonego pytania przez Centrum\\npodmiot lub osoba, która je opracowała, nie będzie miała możliwości jego zastosowania w\\nramach oficjalnej bazy. Natomiast w sytuacji, gdy Centrum zdecyduje się na wykorzystanie\\nprzekazanego pytania, zasadne jest wprowadzenie mechanizmu zapewniającego autorowi\\nlub podmiotowi, który je opracował, odpowiednie wynagrodzenie za wykorzystanie\\nprzygotowanego materiału.\\nTakie rozwiązanie stanowiłoby zachętę do współpracy z ekspertami zewnętrznymi,\\npozwoliłoby na zwiększenie jakości i różnorodności bazy pytań oraz zapewniłoby\\nposzanowanie nakładu pracy osób tworzących wartościowe merytorycznie materiały\\negzaminacyjne.\\n Ponadto można rozważyć organizowanie konkursów z zakresu bezpieczeństwa ruchu\\ndrogowego (BRD), w ramach których osoby posiadające wiedzę i doświadczenie w obszarze\\nszkolenia, egzaminowania oraz praktycznego uczestnictwa w ruchu drogowym mogłyby \\f\\n\\nStrona 103 z 219\\n\\ntworzyć i zgłaszać wartościowe materiały, w tym profesjonalnie opracowane pytania\\negzaminacyjne.\\nTakie rozwiązanie pozwoliłoby nie tylko na pozyskanie wysokiej jakości materiałów do\\nwykorzystania w systemie egzaminowania, ale również stanowiłoby formę docenienia\\nzaangażowania osób uczestniczących w tworzeniu treści służących poprawie bezpieczeństwa\\nruchu drogowego. Jednocześnie konkursowy charakter pozyskiwania materiałów mógłby\\nzwiększyć zainteresowanie społeczne tematyką BRD oraz zachęcić większą liczbę ekspertów i\\npraktyków do współpracy przy rozwijaniu systemu egzaminacyjnego przy jednoczesnym\\nzachowaniu proponowanych rozwiązań dotyczących praw autorskich.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy w\\nzakresie art.\\n57ac ustawy o\\nkierujących\\npojazdami\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nProponuje się uzupełnienie składu rady o przedstawiciela organów nadzoru.\\nUzasadnienie:\\nUwzględnienie w składzie rady przedstawiciela organów nadzoru pozwoliłoby na\\nzapewnienie szerszej perspektywy w zakresie funkcjonowania systemu egzaminowania oraz\\nuwzględnienie doświadczeń wynikających z bieżącego nadzoru nad realizacją zadań\\nzwiązanych z przeprowadzaniem egzaminów państwowych.\\nOrgany nadzoru posiadają praktyczną wiedzę wynikającą z rozpatrywania skarg,\\nprowadzonych postępowań wyjaśniających, analizy nieprawidłowości oraz oceny stosowania\\nprzepisów przez podmioty realizujące zadania w obszarze szkolenia i egzaminowania.\\nWiedza ta może stanowić istotny wkład w proces opiniowania rozwiązań dotyczących\\norganizacji egzaminów, tworzenia pytań egzaminacyjnych oraz doskonalenia systemu\\nzapewniającego jednolitość i obiektywność przeprowadzanych egzaminów.\\nUdział przedstawiciela organów nadzoru pozwoliłby również na wcześniejsze\\nidentyfikowanie potencjalnych problemów interpretacyjnych i organizacyjnych związanych z\\nprojektowanymi rozwiązaniami oraz zapewniłby lepsze uwzględnienie praktycznych skutków\\nproponowanych regulacji.\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\nCo najmniej jeden z członków komisji powinien być rekomendowany przez działające na\\nrynku stowarzyszenia branżowe. Niestety obecnie, w zdecydowanej większości, członkowie\\nKomisji nie mają odpowiedniego doświadczenia w prowadzeniu szkolenia kandydatów na \\f\\n\\nStrona 104 z 219\\n\\nkierowców, co dalej przekłada się na często mylną ocenę umiejętności kandydata na\\ninstruktora, w szczególności w części praktycznej egzaminu.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 11. Kandydaci na kierowców i kierowcy\\nAktualna propozycja zawarta w UD402\\nProjektowany art. 57ae pkt 1 stanowi:\\n„1) w zakresie szkolenia kandydatów na kierowców i kierowców – cele edukacyjne szkolenia\\nw zakresie niezbędnej wiedzy i umiejętności dotyczących kompetencji niezbędnych do\\nbezpiecznej jazdy, opanowania pojazdu, świadomości czynników zwiększających ryzyko\\nwypadku oraz umiejętności obiektywnej oceny własnych kompetencji i postaw;”.\\nPrzepis nie wymienia bezpiecznego zachowania wobec osób z niepełnosprawnościami ani\\ninnych niechronionych uczestników ruchu.\\nPropozycja PZN\\nProjektowanemu art. 57ae pkt 1 proponuje się nadać następujące brzmienie:\\n„1) w zakresie szkolenia kandydatów na kierowców i kierowców – cele edukacyjne szkolenia\\nw zakresie niezbędnej wiedzy i umiejętności dotyczących kompetencji niezbędnych do\\nbezpiecznej jazdy, opanowania pojazdu, świadomości czynników zwiększających ryzyko\\nwypadku, umiejętności obiektywnej oceny własnych kompetencji i postaw oraz\\nbezpiecznego zachowania wobec niechronionych uczestników ruchu, w szczególności\\npieszych, rowerzystów, użytkowników hulajnóg elektrycznych, osób niewidomych i\\nsłabowidzących, osób korzystających z psa przewodnika oraz osób z ograniczoną\\nmobilnością;”.\\nUzasadnienie\\nOgólne odwołanie do bezpieczeństwa nie gwarantuje, że w podstawach programowych\\nznajdą się zagadnienia dotyczące osób z niepełnosprawnościami.\\nKandydat na kierowcę powinien wiedzieć między innymi, że:\\n osoba niewidoma nie może nawiązać kontaktu wzrokowego z kierowcą, \\f\\n\\nStrona 105 z 219\\n\\n gest wykonany z wnętrza samochodu (może Pan/Pani przechodzić) może być dla niej\\ncałkowicie niewidoczny,\\n zachowanie osoby korzystającej z białej laski lub psa przewodnika może być\\nodbierane jako nietypowe,\\n kierowca powinien uwzględniać możliwość trudności w lokalizowaniu przejścia,\\nrozpoznaniu zatrzymania pojazdu i ocenie sytuacji drogowej.\\nOdwołanie do wcześniejszego opracowania\\nW opracowaniu z 18 sierpnia 2025 r. wskazano potrzebę uwzględnienia zasad\\nbezpieczeństwa, pierwszeństwa i relacji pomiędzy ruchem pieszym, rowerowym i\\nsamochodowym w szkoleniu kandydatów na kierowców oraz egzaminatorów.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 12. Kandydaci na instruktorów nauki jazdy i instruktorzy\\nAktualna propozycja zawarta w UD402\\nProjektowany art. 57ae przewiduje opracowanie podstaw programowych dla kandydatów\\nna instruktorów i instruktorów, obejmujących niezbędną wiedzę, umiejętności dydaktyczne i\\nkompetencje zawodowe.\\nProjekt nie wskazuje jednak wprost obowiązku przygotowania instruktorów do nauczania\\nzasad zachowania wobec osób z niepełnosprawnościami.\\nPropozycja PZN\\nProjektowanemu art. 57ae pkt 2 proponuje się nadać następujące brzmienie:\\n„2) w zakresie szkolenia kandydatów na instruktorów nauki jazdy i instruktorów – cele\\nedukacyjne szkolenia w zakresie niezbędnej wiedzy, umiejętności dydaktycznych i\\nmetodycznych oraz kompetencji zawodowych koniecznych do prawidłowego przygotowania\\nkandydatów na kierowców do bezpiecznego uczestnictwa w ruchu drogowym, w tym\\nrozpoznawania zagrożeń dotyczących niechronionych uczestników ruchu oraz osób z\\nniepełnosprawnościami, kształtowania właściwych postaw i oceny postępów osoby\\nszkolonej;”. \\f\\n\\nStrona 106 z 219\\n\\nUzasadnienie\\nInstruktor powinien umieć nie tylko przytoczyć treść przepisu, ale także wyjaśnić jego\\npraktyczne zastosowanie w sytuacjach dotyczących osoby niewidomej, osoby korzystającej z\\npsa przewodnika albo osoby o ograniczonej mobilności. Jest to szczególnie istotne w\\nodniesieniu do przepisów dotyczących pierwszeństwa pieszych i rowerzystów, które nadal\\nbywają niejednolicie rozumiane i stosowane.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 13. Kandydaci na egzaminatorów i egzaminatorzy\\nAktualna propozycja zawarta w UD402\\nProjektowany art. 57ae obejmuje podstawy programowe dla kandydatów na\\negzaminatorów i egzaminatorów, ale nie wskazuje wprost oceny zachowania osoby\\negzaminowanej wobec osób z niepełnosprawnościami.\\nPropozycja PZN\\nProjektowanemu art. 57ae pkt 3 proponuje się nadać następujące brzmienie:\\n„3) w zakresie szkolenia kandydatów na egzaminatorów i egzaminatorów – cele edukacyjne\\nszkolenia w zakresie niezbędnej wiedzy, umiejętności i kompetencji koniecznych do\\nrzetelnego, obiektywnego i jednolitego przeprowadzania egzaminów państwowych, oceny\\nzachowania osoby egzaminowanej wobec niechronionych uczestników ruchu, w tym osób z\\nniepełnosprawnościami, rozpoznawania sytuacji niebezpiecznych oraz uzasadniania\\npodejmowanych decyzji egzaminacyjnych;”.\\nUzasadnienie\\nJednolitość egzaminowania powinna obejmować sposób oceny zachowania wobec osób\\nniewidomych, słabowidzących i osób z ograniczoną mobilnością. Brak wyraźnego wskazania\\ntego obszaru może powodować różną ocenę podobnych sytuacji przez poszczególnych\\negzaminatorów.\\n \\f\\n\\nStrona 107 z 219\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 14. Konsultowanie podstaw programowych\\nAktualna propozycja zawarta w UD402\\nProjekt powierza Centrum Egzaminowania opracowywanie i publikowanie podstaw\\nprogramowych, ale nie przewiduje obowiązku ich konsultowania z organizacjami osób z\\nniepełnosprawnościami.\\nPropozycja PZN\\nW projektowanym art. 57ae proponuje się dodać ustęp w brzmieniu:\\n„Przed opublikowaniem podstaw programowych w części dotyczącej bezpieczeństwa osób z\\nniepełnosprawnościami i innych niechronionych uczestników ruchu Centrum\\nEgzaminowania zasięga opinii reprezentatywnych organizacji osób z\\nniepełnosprawnościami.”\\nUzasadnienie\\nPraktyczna wiedza dotycząca poruszania się z białą laską, korzystania z psa przewodnika lub\\nprzemieszczania się na wózku nie może być w pełni zastąpiona wiedzą prawniczą, policyjną,\\nszkoleniową lub egzaminacyjną. Zasięgnięcie opinii nie ograniczy kompetencji Centrum, a\\npozwoli zapobiec błędom merytorycznym i uproszczeniom.\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 15. Rozszerzenie katalogu dziedzin eksperckich\\nAktualna propozycja zawarta w UD402\\nProjektowany art. 57ad ust. 3 przewiduje, że w skład Rady Konsultacyjnej wejdzie co\\nnajmniej 12 ekspertów posiadających wiedzę lub doświadczenie w zakresie:\\n1. bezpieczeństwa ruchu drogowego;\\n2. szkolenia i egzaminowania;\\n3. kontroli ruchu lub transportu drogowego;\\n4. ratownictwa, ochrony ludności lub bezpieczeństwa publicznego;\\n5. psychologii transportu, dydaktyki lub metodyki kształcenia;\\n6. medycyny ratunkowej lub ratownictwa medycznego. \\f\\n\\nStrona 108 z 219\\n\\nProjekt nie wymienia dostępności przestrzeni publicznej, projektowania uniwersalnego ani\\nbezpieczeństwa osób z niepełnosprawnościami.\\nPropozycja PZN\\nW projektowanym art. 57ad ust. 3 po pkt 6 proponuje się dodać pkt 7 w brzmieniu:\\n„7) dostępności przestrzeni publicznej, projektowaniu uniwersalnym lub bezpieczeństwa\\nosób z niepełnosprawnościami w ruchu drogowym.”.\\nUzasadnienie\\nSkoro bezpieczeństwo osób niewidomych i innych osób o szczególnych potrzebach stanowi\\njeden z powodów interwencji legislacyjnej, wiedza dotycząca tej grupy powinna być\\nreprezentowana w Radzie opiniującej pytania egzaminacyjne i podstawy programowe.\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 16. Zagwarantowanie udziału eksperta dostępności\\nAktualna propozycja zawarta w UD402\\nProjekt wymienia dziedziny, z których mogą wywodzić się członkowie Rady, ale nie wymaga\\nobecności przedstawiciela każdej z nich.\\nDodanie dostępności do katalogu nie zagwarantuje zatem samo w sobie powołania osoby\\nposiadającej odpowiednie doświadczenie.\\nPropozycja PZN\\nW projektowanym art. 57ad proponuje się dodać ustęp w brzmieniu:\\n„W skład Rady Konsultacyjnej wchodzi co najmniej jeden ekspert posiadający\\nudokumentowane doświadczenie w zakresie dostępności przestrzeni publicznej,\\nprojektowania uniwersalnego lub bezpieczeństwa osób z niepełnosprawnościami w ruchu\\ndrogowym.”\\nUzasadnienie\\nBez takiej gwarancji perspektywa osób z niepełnosprawnościami może pozostać\\nnieuwzględniona mimo formalnego rozszerzenia katalogu dziedzin.\\n \\f\\n\\nStrona 109 z 219\\n\\nArt. 1 pkt 22\\nprojektu\\nustawy w\\nzakresie art.\\n57ad ust. 3\\nustawy o\\nkierujących\\npojazdami\\n\\nOgólnopolskie\\nStowarzyszenie\\nInstruktorów\\nTechniki Jazdy\\n\\nZwracamy uwagę także na fakt, że kryteria określające kompetencje osób wchodzących w\\nskład przyszłej Rady Konsultacyjnej (art. 1 pkt 22 w zakresie art. 57ad ust. 3) są\\nnieprecyzyjne i bardzo ogólnikowe. W naszej ocenie niezbędne jest zobiektywizowanie tych\\nwymagań poprzez określenie mierzalnych kryteriów, uwzględniających w szczególności\\naktualną wiedzę oraz praktyczne doświadczenie kandydatów.\\nZasadnym wydaje się – np. w dziedzinie szkolenia i egzaminowania instruktorów techniki\\njazdy - wprowadzenie wymogu aktywnego wykonywania działalności szkoleniowej w\\nzakresie doskonalenia techniki jazdy w określonym okresie poprzedzającym powołanie do\\nRady, np. w ciągu ostatnich 10 lat. Doświadczenie to powinno obejmować rzeczywiste\\nprowadzenie zajęć praktycznych i teoretycznych, a nie jedynie historyczne wykonywanie\\nzawodu lub samo posiadanie uprawnień.\\nNie sposób bowiem uznać za wystarczające doświadczenie zawodowe polegające na\\nprowadzeniu zajęć z bezpiecznej jazdy kilkanaście lat temu, kiedy zarówno technologia\\nmotoryzacyjna, systemy bezpieczeństwa pojazdów, jak i metodyka szkolenia kierowców\\nznacząco odbiegały od obecnych standardów. Według proponowanego brzmienia przepisu\\nosoba, która nie prowadziła szkoleń od wielu lat, nadal mogłaby zostać członkiem Rady i\\nwspółtworzyć pytania egzaminacyjne oraz standardy obowiązujące instruktorów aktywnie\\nwykonujących zawód.\\nMając na uwadze odpowiedzialność Rady za kształtowanie poziomu merytorycznego\\negzaminów oraz standardów szkolenia, jej członkowie powinni legitymować się nie tylko\\ndoświadczeniem zawodowym, ale również aktualną praktyką szkoleniową, zapewniającą\\nznajomość współczesnych realiów, technologii pojazdów oraz obowiązujących metod\\ndydaktycznych.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 22)\\nWprowadzająca Centrum Egzaminowania, które jest wspierane przez Radę Konsultacyjną\\njest krokiem w dobrym kierunku. Szczegółowe regulacje dotyczące m.in. praw autorskich\\npozwolą uniknąć problemów jakie były w obecnym systemie. Pozwolą\\nwłaściwie każdemu wpływać na zawartość zestawu pytań egzaminacyjnych. Ograniczona\\nilość pytań ułatwi również nadzór nad ich aktualnością i poprawnością merytoryczną.\\n    \\f\\n\\nStrona 110 z 219\\n\\nArt. 1 pkt 22\\nprojektu\\nustawy\\n NSZZ\\n„Solidarność” -\\n80 w WORD i\\nOSK\\nW art. 57 ab skreślić ust. 4 Propozycja aby nieodpłatnie przekazywać propozycje pytań jest\\nkompletnie niezrozumiała. Jeśli pytania trafią do bazy pytań i z autorem zawarto umowę o\\nich wykorzystywaniu to umowa powinna przewidywać wynagrodzenie.\\n\\n Art. 1 pkt 22\\nprojektu\\nustawy\\nZrzeszenie\\nMiędzynarodo-\\nwych\\nPrzewoźników\\nDrogowych w\\nPolsce\\nzwracamy uwagę na prawdopodobną omyłkę pisarską w art. 1 pkt 22 projektu. W\\nprojektowanym art. 57aa ust. 2 pkt 6 wskazano na „Instytut Transportu\\nDrogowego” zamiast „Instytut Transportu Samochodowego\\n Art. 1 pkt 23\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 1 zmiana 23) w art. 57c ust.1 otrzymuje brzmienie:\\nZmiana wprowadza opłatę w wysokości 2 zł. Może lepiej jak ta opłata była by określona w\\nprocentach tak jak było w starej wersji ustępu 1. Taki sposób naliczania zabezpieczył\\nby ustawę przed konicznością aktualizowania tej kwoty z powodu inflacji.\\n Art. 1 pkt 23\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n23) w art. 57c ust. 1 otrzymuje brzmienie:\\n„1. Wojewódzkie ośrodki ruchu drogowego przekazują 2 zł z opłaty za\\nprzeprowadzenie części teoretycznej egzaminu państwowego na rachunek bankowy\\nInstytutu Transportu Samochodowego na cele utworzenia, działalności i rozwoju Centrum\\nEgzaminowania.”;\\nStanowisko Krajowego Stowarzyszenia Egzaminatorów:\\nNaszym zdaniem zaproponowana kwota przy obecnych cenach egzaminu teoretycznego jest\\nzbyt duża  na dzień dzisiejszy, ponieważ jest dwukrotnością obecnego zapisu 1,5% . Na dzień\\ndzisiejszy  egzamin teoretyczny w wiekszości ośrodków ruchu drogowego w Polsce nie\\nprzekracza  60 złotych, co daje kwotę około 90 groszy.\\n W związku z powyższym Krajowe Stowarzyszenie Egzaminatorów jest za zostawieniem\\nprzekazywania 1,5 % opłaty za przeprowadzenie cześci teoretycznej egzaminu państwowego.\\nJednocześnie  proponujemy, podwyższyć kwotę za egzamin kwalifikacji  zawodowej  oraz\\nprzekazanie  od niego też 1.5 %.\\n\\n Art. 1 pkt 27\\nprojektu\\nustawy\\nZwiązek\\nWojewództw\\nProponuje się doprecyzowanie sposobu podawania analizy do publicznej wiadomości.\\nProjektowany przepis wskazuje jedynie obowiązek publikacji analizy sporządzanej przez\\nmarszałka województwa, nie określając jednak formy ani miejsca jej udostępnienia. \\f\\n\\nStrona 111 z 219\\n\\nRzeczypospolitej\\nPolskiej\\nNależałoby jednoznacznie wskazać, czy analiza powinna być publikowana w Biuletynie\\nInformacji Publicznej urzędu marszałkowskiego, na stronie internetowej urzędu, stronie\\ninternetowej wojewódzkiego ośrodka ruchu drogowego, na tablicy ogłoszeń, czy w inny\\nokreślony sposób.\\nDoprecyzowanie sposobu realizacji obowiązku publikacji pozwoli na zapewnienie jednolitych\\nzasad we wszystkich województwach oraz wyeliminuje ryzyko odmiennej praktyki\\nstosowania przepisu przez poszczególnych marszałków województw.\\n Art. 1 pkt 27\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 27 proponujemy skreślić.\\n\\n Art. 1 pkt 28\\nprojektu\\nustawy\\nKrajowe\\nStowarzyszenie\\nDyrektorów\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW dodanym punkcie 3 do art. 112 ust. 1,  art. 49 ust.1 punkt 3 lit a odnosi się do osób,\\nktórym cofnięto uprawnienia do kierowania pojazdami, natomiast w art. 112 w ust. 1 mówi\\nsię o szkoleniu praktycznym dla osób posiadających uprawnienia do kierowania pojazdami.\\nUzasadnienie:\\nBrak spójności adresatów szkolenia praktycznego, o których mowa w art. 112 ust.1 – tj.\\nosoby posiadające uprawnienia do kierowania pojazdami z osobami, o których mowa w art.\\n49 ust. 1 pkt lit a - przywrócenie uprawnienia do kierowania motorowerem, pojazdami\\nsilnikowymi lub tramwajem cofniętego na okres przekraczający rok lub cofniętego w związku\\nz utratą kwalifikacji\\n Art. 1 pkt 28\\nprojektu\\nustawy\\nZwiązek\\nWojewództw\\nRzeczypospolitej\\nPolskiej\\nW dodanym punkcie 3 do art. 112 ust. 1,  art. 49 ust.1 punkt 3 lit a odnosi się do osób,\\nktórym cofnięto uprawnienia do kierowania pojazdami, natomiast w art. 112 w ust. 1 mówi\\nsię o szkoleniu praktycznym dla osób posiadających uprawnienia do kierowania pojazdami.\\n\\nBrak spójności adresatów szkolenia praktycznego, o których mowa w art. 112 ust.1 – tj.\\nosoby posiadające uprawnienia do kierowania pojazdami z osobami, o których mowa w art.\\n49 ust. 1 pkt lit a - przywrócenie uprawnienia do kierowania motorowerem, pojazdami\\nsilnikowymi lub tramwajem cofniętego na okres przekraczający rok lub cofniętego w związku\\nz utratą kwalifikacji\\n \\f\\n\\nStrona 112 z 219\\n\\n Art. 1 pkt 28\\nprojektu\\nustawy\\nOgólnopolskie\\nStowarzyszenie\\nInstruktorów\\nTechniki Jazdy\\nOgólnopolskie Stowarzyszenie Instruktorów Techniki Jazdy wnosi o skreślenie zmiany\\nzaproponowanej w art. 1 pkt 28 projektu ustawy o zmianie ustawy o kierujących pojazdami\\noraz niektórych innych ustaw (nr z wykazu UD 402) w brzmieniu:\\n\\n28) w art. 112 w ust. 1 w pkt 2 w lit. d kropkę zastępuje się średnikiem i dodaje się pkt 3 w\\nbrzmieniu:\\n„3) ośrodku szkolenia kierowców – w zakresie szkolenia mającego na celu doskonalenie\\numiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem lub\\nprzygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa w art. 49 ust. 1 pkt\\n2 i 3.”;\\n\\nUzasadnienie:\\nProponowany zapis umożliwia Ośrodkom Szkolenia Kierowców prowadzenie wszelkich\\nszkoleń osób posiadających już uprawnienia do kierowania. Nie tylko tych kierowców, którzy\\nnp. nie prowadzili pojazdu przez dłuższy czas i chcą są przypomnieć ogólne zasady i przepisy\\nruchu drogowego. Zmiana umożliwia Ośrodkom Szkolenia Kierowców prowadzenie także\\nwysoko specjalistycznych szkoleń i kursów z bezpiecznej jazdy, ecodrivigu, a nawet technik\\nwychodzenia z poślizgów. Po wejściu przepisu w życie Ośrodki Szkolenia Kierowców będą\\nmogły bowiem np. na kawałku dowolnego placu utworzyć sobie prowizoryczną matę\\npoślizgową i w świetle prawa w tych warunkach szkolić.\\nZwracamy uwagę na fakt, że w tej chwili omawiana działalność jest uregulowana poprzez\\nustawowe przypisanie jej Ośrodkom Doskonalenia Techniki Jazdy, które posiadają\\nprofesjonalną, opisaną we właściwym akcie prawnym infrastrukturę oraz wykwalifikowaną\\nkadrę. Szkolenia w ODTJ prowadzą instruktorzy techniki jazdy z państwowymi\\nuprawnieniami oraz z wiedzą i doświadczeniem w tym segmencie szkoleń.\\nInstruktorzy nauki jazdy zatrudnieni w OSK specjalizują się w przygotowaniu kursantów do\\nzdania egzaminu państwowego na prawo jazdy, a więc w zupełnie innym zakresie.\\nNależy podkreślić, że kompetencje nabywane podczas szkolenia (i weryfikowane poprzez\\negzaminy państwowe) kandydata na instruktora nauki jazdy i kandydata na instruktora\\ntechniki jazdy są zupełnie różne, właśnie ze względu na krańcowo odmienną wykonywaną\\npotem pracę.\\nNie negujemy potrzeby umożliwienia doszkalania się w Ośrodkach Szkolenia Kierowców\\nkierowców objętych kontrolnym sprawdzeniem kwalifikacji czy chcącym sobie przypomnieć \\f\\n\\nStrona 113 z 219\\n\\nzasady i przepisy ruchu drogowego lub podstawowe umiejętności kierowania pojazdem.\\nWymaga to jednak gruntownej zmiany i doprecyzowania przepisu, który w\\nzaproponowanym brzmieniu znacznie rozszerza uprawnienia Ośrodka Szkolenia Kierowców\\no elementy, do których ani kadrowo, ani infrastrukturalnie nie jest przygotowany.\\n Art. 1 pkt 28\\nprojektu\\nustawy\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nW art. 1 pkt 28 proponujemy zmianę zapisu nowego pkt 3 na: ,,ośrodku szkolenia kierowców\\nw zakresie pozwalającym na przygotowanie do kontrolnego sprawdzenia kwalifikacji, o\\nktórym mowa w art. 49 ust. 1 pkt 2 i 3 lub przywrócenia poziomu wiedzy i umiejętności\\numożliwiających bezpieczne kierowanie pojazdami, w szczególności w ruchu drogowym.\\n\\nArt. 1 pkt 28\\nprojektu\\nustawy\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n1. Ad art. 1 pkt 28 projektu\\nArt. 1 pkt 28 projektu proponuje zmiany art. 112 UoKP, umożliwiające szkolenie osób\\nposiadających uprawnienia do kierowania pojazdem także przez ośrodki szkolenia\\nkierowców, a nie tylko przez ośrodki doskonalenia techniki jazdy.\\nTLP, co do zasady, ocenia pozytywnie taką propozycję, gdyż postulat prowadzenia jazd\\ndoszkalających formułowany był od dawna przez różne środowiska. Możliwości prowadzenia\\ntakich jazd oczekiwały bowiem OSK, do których zgłaszały się np. osoby mające długą przerwę\\nw prowadzeniu pojazdów, pragnące odnowić umiejętności praktyczne w kierowaniu\\npojazdem, które z upływem czasu uległy zatarciu, etc. Z kolei przedsiębiorcy wykorzystujący\\nmniej popularne rodzaje pojazdów w danej kategorii prawa jazdy, wyrażali chęć zlecenia\\nzajęć dokształcających dla nowo zrekrutowanych pracowników nie posiadających\\ndoświadczenia w kierowaniu takich pojazdów.\\nNiemniej zaproponowany sposób wyjścia naprzeciw tym postulatom nie pozwala\\njednoznacznie rozróżnić planowanych kompetencji ośrodków szkolenia kierowców od\\ndotychczasowych kompetencji ośrodków doskonalenia techniki jazdy\\nDlatego też proponujemy doprecyzowanie brzmienia proponowanego art. 112 ust. 1 pkt 3\\nUoKP w następujący sposób:\\n„3) ośrodku szkolenia kierowców – w ruchu drogowym, w zakresie szkolenia mającego na\\ncelu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym\\nuprawnieniem lub przygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa\\nw art. 49 ust. 1 i pkt 2 i 3.”  \\f\\n\\nStrona 114 z 219\\n\\nProponowane wyżej rozwiązanie wykluczy możliwość prowadzenia zajęć przez OSK na\\nzamkniętych obiektach nie spełniających wymagań stawianych ODTJ-om w zakresie\\nbezpieczeństwa wykonywanego szkolenia.\\n\\nArt. 1 pkt 28\\nprojektu\\nustawy\\n\\nStanowisko\\nwspólne\\nTor Modlin sp. z\\no.o., Driveland\\nsp. z o.o.,\\nSobiesław\\nZasada Centrum\\nsp. z o.o. sp.j.,\\nAberos sp. z o.o.\\n\\nArt. 2 Projekt ustawy zakłada zmianę art. 112 ust. 1 Ustawy poprzez dodanie pkt. 3 w\\nnastępującym brzmieniu: „3) ośrodku szkolenia kierowców – w zakresie szkolenia mającego\\nna celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym\\nuprawnieniem lub przygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa\\nw art. 49 ust. 1 pkt 2 i 3”.\\n\\nW dotychczasowym brzmieniu art. 112 ust. 1 Ustawy przewiduje, że ośrodki doskonalenia\\ntechniki jazdy stopnia podstawowego prowadzą szkolenia w zakresie doskonalenia techniki\\njazdy kierowców posiadających prawo jazdy kategorii, A1, A2, A, B1, B lub B+E, zaś ośrodki\\ndoskonalenia techniki jazdy stopnia wyższego w zakresie doskonalenia techniki jazdy\\nkierowców posiadających prawo jazdy kategorii C1, C1+E, C, C+E, D1, D1+E, D lub D+E.\\n\\nW ramach postulowanej zmiany nie sposób dojść do wniosku, czym różni się szkolenie\\nmające na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym\\nposiadanym uprawnieniem od szkolenia w zakresie doskonalenia techniki jazdy. Ma to\\nszczególne znaczenie praktyczne, w szczególności, że projektodawca odrębnie wyróżnił\\nkategorię przygotowania do kontrolnego sprawdzenia kwalifikacji. O ile nie budzi żadnych\\nwątpliwości możliwość doszkalania się w Ośrodkach Szkolenia Kierowców kierowców\\nobjętych kontrolnym sprawdzeniem kwalifikacji, o tyle spore wątpliwości budzi, co\\nprojektodawca rozumie pod pojęciem „szkolenia mającego na celu doskonalenie\\numiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem” i jaka\\njest relacja tego pojęcia do pojęcia „szkolenia w zakresie doskonalenia techniki jazdy”.\\n\\nNależy wyraźnie podkreślić, że prowadzenie ośrodka doskonalenia techniki jazdy stanowi\\ndziałalność regulowaną. Ustawodawca w art. 114 Ustawy przewidział szereg warunków,\\nktóre spełnić musi przedsiębiorca, aby móc prowadzić ośrodek doskonalenia techniki jazdy.\\nNadto, w art. 117 Ustawy przewidziano szereg warunków, których spełnienie pozwala\\nuzyskać uprawnienia instruktora techniki jazdy. Wymagania przewidziane dla ośrodków\\nszkolenia kierowców (art. 28 Ustawy) oraz dla instruktorów (art. 33 Ustawy) są zgoła \\f\\n\\nStrona 115 z 219\\n\\nodmienne od tych określonych w zdaniu poprzedzającym, które przewidziane są dla\\nośrodków doskonalenia techniki jazdy oraz zatrudnionych tam instruktorów.\\n\\nZ powyższego jednoznacznie wynika, że ośrodki szkolenia kierowców oraz instruktorzy nie są\\nprzygotowani do prowadzenia wysoko specjalistycznych szkoleń i kursów z bezpiecznej\\njazdy, w szczególności obejmujących kontrolowaną utratę przyczepności, destabilizację toru\\njazdy pojazdu, hamowanie na nawierzchniach o zróżnicowanej przyczepności lub\\nopanowanie pojazdu w sytuacji poślizgu, ecodrivingu. Do prowadzenia tego rodzaju\\ndziałalności niezbędna jest określona infrastruktura oraz umiejętności, których ustawodawca\\nnie wymaga dotychczas od ośrodków szkolenia kierowców oraz instruktorów ani także nie\\nprzewiduje ich w ramach przedmiotowej nowelizacji. Mając zaś na względzie\\nniejednoznaczną relację między pojęciami „szkolenia mającego na celu doskonalenie\\numiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem” oraz\\n„szkolenia w zakresie doskonalenia techniki jazdy”, zachodzi realne ryzyko otwarcia\\nośrodkom szkolenia kierowców możliwości prowadzenia specjalistycznych szkoleń, których\\nprowadzenie dotychczas było reglamentowane i przewidziane wyłącznie dla podmiotów\\nwyspecjalizowanych i do tego przygotowanych.\\n\\nW tym zakresie wypada wskazać, że postulowana zmiana nie spełnia kryteriów określoności\\nprzepisów prawa, przewidzianych przez przepisy prawa powszechnie obowiązującego, a\\ndoprecyzowanych przez orzecznictwo sądowe. Nie sposób bowiem prima facie ani nawet po\\ngłębszej lekturze postulowanej zmiany, wywnioskować, jaka była intencja prawodawcy w\\nzakresie zwiększenia uprawnień ośrodków szkolenia kierowców. Tego rodzaju przepisy\\nprawa winny być na tyle szczegółowe i precyzyjne, aby nie było wątpliwości, jakie\\ndodatkowe uprawnienia zostały danemu podmiotowi przyznane, w szczególności w\\nporównaniu z innymi podmiotami, które dotychczas danymi uprawnieniami (lub\\nanalogicznymi) już dysponują. Wymaga to, w obecnym stanie projektowanej regulacji,\\ngruntownej zmiany i doprecyzowania przepisu, który w zaproponowanym brzmieniu\\nznacznie rozszerza uprawnienia ośrodków szkolenia kierowców o nieokreślone elementy.\\n\\nPowyższe rozwiązanie budzi również wątpliwości natury formalnej z uwagi na to, że\\nuzasadnienie Projektu ustawy w żadnym stopniu nie odnosi się do rozwiązania określonego\\nw art. 1 pkt 28 Projektu ustawy. Uzasadnienie odbiega więc od standardów przewidzianych \\f\\n\\nStrona 116 z 219\\n\\nwłaściwymi przepisami prawa dla uzasadnienia aktu normatywnego, jakim jest ustawa.\\nOcena Skutków Regulacji również abstrahuje od proponowanego w tym zakresie\\nrozwiązania. Gdyby więc rozwiązanie przyjęte zostało w obecnym kształcie, to nie sposób\\nbyłoby nawet odczytać intencję projektodawcy bowiem nie została ona w żadnym miejscu\\nwyrażona. Naraża to adresatów pierwotnych i wtórnych na dalej idące problemy związane\\nze stosowaniem prawa, w szczególności w zakresie potencjalnej odpowiedzialności\\npodmiotów prowadzących tego rodzaju szkolenia specjalistyczne.\\n\\nMając na względzie powyższe, wnosimy o usunięcie projektowanej zmiany, określonej w art.\\n1 pkt 28 Projektu ustawy albo o pozostawienie ośrodkom szkolenia kierowców wyłącznie\\nuprawnienia do kontrolnego sprawdzenia kwalifikacji, do czego ośrodki te są w sposób\\nwystarczający przygotowane. Pozwoli to na zachowanie spójności systemu prawa, a także\\nzabezpieczy interesy korzystających ze szkoleń specjalistycznych, w tym ich bezpieczeństwo,\\na więc również wpłynie na zabezpieczenie interesu ogólnego. Projektowany przepis wymaga\\nponownego przemyślenia i niezbędnego doprecyzowania.\\n\\n Art. 1 pkt 28\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\n14) W odniesieniu do art. 1 pkt 28 w naszej ocenie rozwiązanie to jest jak najbardziej\\noczekiwane przez środowisko. Jednak do właściwego działania niezbędna jest zmiana\\nprzepisów art. 55 ustawy – Prawo o ruchu drogowym tak aby osoba szkolona, a nie tylko\\nubiegająca się o uprawnienia do kierowania pojazdami miała możliwość kierowania\\npojazdem na którym znajduje się tablica „L”. Propozycje zapisów w tym zakresie\\nprzedstawimy w dalszej części pisma.\\n\\n Art. 1 projektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 2)\\nZwracam się do Państwa jako osoba zainteresowana kształtem nadchodzących zmian w\\nprzepisach dotyczących szkolenia i egzaminowania kierowców. Chciałabym przedstawić\\nswoje stanowisko oraz konstruktywne uwagi dotyczące projektowanych regulacji, które\\nbudzą moje wątpliwości w kontekście ich realnego wpływu na bezpieczeństwo ruchu\\ndrogowego oraz jakość kształcenia.\\nMoje zastrzeżenia dotyczą następujących kwestii:\\n Egzaminy wewnętrzne: Wprowadzenie obligatoryjnych egzaminów wewnętrznych\\nbudzi wątpliwości natury etycznej i finansowej. Istnieje ryzyko, że staną się one dla \\f\\n\\nStrona 117 z 219\\n\\nośrodków szkolenia kierowców jedynie dodatkowym źródłem zarobku, zamiast\\npełnić funkcję realnej weryfikacji wiedzy. Czy ośrodki szkolenia będą ponosić\\nodpowiedzialność finansową, jeśli kursant po pozytywnym zaliczeniu egzaminu\\nwewnętrznego nie zda egzaminu państwowego w WORD?\\n Termin ważności egzaminu teoretycznego: Uważam, że egzamin teoretyczny\\npowinien pozostać bezterminowy. Obecne przepisy nie przewidują obowiązku\\nponownego egzaminowania kierowców posiadających już uprawnienia przy każdej\\naktualizacji przepisów, dlatego nakładanie takiego obowiązku wyłącznie na\\nkandydatów jest niesprawiedliwe.\\n System szkolenia i liczba godzin: Zwiększenie liczby godzin szkolenia (np. z 30 do 50)\\npowinno iść w parze z jakością, a nie tylko ilością. Postuluję położenie większego\\nnacisku na naukę praktycznych umiejętności, takich jak tankowanie pojazdu czy\\njazda w warunkach dróg szybkiego ruchu. Rozważyłabym również umożliwienie\\ndoszkalania się pod okiem doświadczonych kierowców, co pozwoliłoby na nabycie\\ncennej praktyki.\\n Przygotowanie pojazdu do jazdy: Wymóg szczegółowego sprawdzania stanu\\ntechnicznego pojazdu (poziomu płynów eksploatacyjnych) na egzaminie uważam za\\nnieadekwatny do realiów użytkowania samochodów przez przeciętnych kierowców i\\nnie wpływający bezpośrednio na bezpieczeństwo podczas jazdy egzaminacyjnej.\\n Sankcje za niezdane egzaminy: Obowiązek odbycia dodatkowych godzin\\ndoszkalających po trzech niezdanych egzaminach, bez jednoczesnej gwarancji\\njakości szkolenia w ośrodku, przerzuca ciężar niepowodzenia wyłącznie na kursanta.\\nPodsumowując, uważam, że reforma powinna skupić się na realnym podniesieniu\\nstandardów szkolenia praktycznego, a nie na mnożeniu formalnych barier, które nie\\nrozwiązują problemu jakości nauczania.\\n Art. 2 projektu\\nustawy\\nZarząd Dróg\\nMiejskich\\nWarszawa\\n  Zarządca ruchu wyznaczy miejsca postoju pojazdów mikromobilności dzielonej\\nW ustawie z dnia 21 marca 1985 r. o drogach publicznych proponujemy dodanie nowego art.\\n12c, zgodnie z którym organ właściwy do zarządzania ruchem, wyznaczałby miejsca do\\npostoju hulajnóg elektrycznych, motorowerów, urządzeń transportu osobistego i rowerów.\\nDodatkowo (opcjonalnie) nowy art. 12c mógłby określać, że zarządca drogi może wymagać\\nuzyskania jego zgody na wykonywanie postoju w takich miejscach przez pojazdy\\nmikromobilności dzielonej. \\f\\n\\nStrona 118 z 219\\n\\nBrzmienie proponowanego artykułu:\\n„art. 12 c. 1. Organ właściwy do zarządzania ruchem na drogach wyznacza miejsca, na\\nktórych dopuszczony jest postój pojazdów mikromobilności dzielonej.\\n2. Postój pojazdów mikromobilności dzielonej na miejscach, o których mowa w ust. 1.\\nwymaga uzyskania przez podmiot realizujący usługę mikromobilności dzielonej zezwolenia\\nzarządcy drogi, wydanego na wyznaczony okres, w drodze decyzji administracyjnej.”\\n\\n Art. 2 projektu\\nustawy\\nLime\\nTechnology sp. z\\no.o.\\n● Art. 2 projektu ustawy – art. 20 pkt 21 ustawy o drogach publicznych:\\n\\nProjekt przyznaje zarządcy drogi kompetencję do wyznaczania miejsc przeznaczonych do\\npostoju pojazdów i urządzeń udostępnianych w ramach mikromobilności.\\n\\nProponowany art. 20 pkt 21 mógłby otrzymać następujące brzmienie:\\n„21) wyznaczanie i oznakowanie, na zasadach określonych w porozumieniu, o którym mowa\\nw art. 47 ust. 3a ustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym, miejsc\\nprzeznaczonych do postoju pojazdów lub urządzeń przeznaczonych do indywidualnego\\nprzemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg\\nelektrycznych lub urządzeń transportu osobistego udostępnianych w ramach\\nmikromobilności współdzielonej, w liczbie, o pojemności i rozmieszczeniu odpowiadających\\nlokalnemu zapotrzebowaniu, natężeniu ruchu, sposobowi zagospodarowania terenu”.\\nZmiana zachowałaby kompetencję zarządcy drogi do wyznaczania miejsc parkingowych,\\nnakładając jednocześnie obowiązek zapewnienia ich w liczbie, pojemności i rozmieszczeniu\\numożliwiających rzeczywiste przestrzeganie zasad obowiązkowego parkowania.\\n Art. 2 projektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 3)\\nczłonek\\nWielkopolskiego\\nStowarzyszenia\\nNiewidomych\\n\\njako osoba niewidoma i członek Wielkopolskiego Stowarzyszenia Niewidomych, wyrażam\\nzdecydowane poparcie dla wprowadzenia obowiązku pozostawiania pojazdów\\nmikromobilności dzielonej wyłącznie w miejscach wyznaczonych przez zarządcę drogi.\\nNieprawidłowo pozostawione hulajnogi i rowery stanowią dla osób niewidomych i\\nsłabowidzących nieprzewidywalne, trudne do wykrycia przeszkody. Mogą powodować\\npotknięcia, upadki, konieczność wejścia na jezdnię oraz ograniczać możliwość\\nsamodzielnego i bezpiecznego poruszania się. \\f\\n\\nStrona 119 z 219\\n\\nProjekt trafnie rozpoznaje ten problem w uzasadnieniu i ocenie skutków regulacji.\\nProponuję jednak uzupełnienie tekstu ustawy o następujące rozwiązania:\\n1. Uzupełnienie projektowanego art. 20 pkt 21 ustawy o drogach publicznych o\\nobowiązek wyznaczania miejsc postoju z uwzględnieniem zasad projektowania\\nuniwersalnego, potrzeb osób ze szczególnymi potrzebami oraz konieczności\\nzachowania ciągłej i wolnej od przeszkód drogi dla pieszych.\\nProponowane brzmienie:\\n„21) wyznaczanie, z uwzględnieniem zasad projektowania uniwersalnego, potrzeb osób ze\\nszczególnymi potrzebami oraz konieczności zachowania ciągłej i wolnej od przeszkód drogi\\ndla pieszych, miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych do\\nindywidualnego przemieszczania się na krótkich dystansach (…)”.\\n2. Dodanie obowiązku stosowania przez operatorów rozwiązań technicznych\\nuniemożliwiających zakończenie korzystania z pojazdu poza wyznaczonym miejscem.\\nProponowane brzmienie:\\n„Podmiot świadczący usługę mikromobilności dzielonej jest obowiązany zapewnić\\nrozwiązania techniczne uniemożliwiające zakończenie korzystania z pojazdu lub urządzenia\\npoza miejscem wyznaczonym przez zarządcę drogi”.\\n1. Określenie minimalnych wymagań dotyczących lokalizacji i oznakowania miejsc\\npostojowych. Miejsca te nie powinny znajdować się na ścieżkach prowadzących i\\npolach uwagi, przy przejściach dla pieszych, przystankach, wejściach do budynków\\nani w sposób ograniczający wymaganą wolną szerokość drogi dla pieszych.\\n2. Zobowiązanie operatorów do zapewnienia dostępnego cyfrowo i telefonicznie\\nsposobu zgłaszania źle pozostawionych pojazdów oraz do ich niezwłocznego\\nusuwania.\\n Art. 2 projektu\\nustawy\\nPolski Związek\\nNiewidomych 1. Zapewnienie dostępności miejsc wyznaczanych przez zarządcę drogi\\nAktualna propozycja zawarta w UD402 \\f\\n\\nStrona 120 z 219\\n\\nArt. 2 projektu przewiduje dodanie w art. 20 ustawy o drogach publicznych pkt 21 w\\nbrzmieniu:\\n„21) wyznaczanie miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych\\ndo indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów,\\nhulajnóg elektrycznych lub urządzeń transportu osobistego udostępnianych w ramach\\nmikromobilności dzielonej, w rozumieniu art. 2 pkt 47d ustawy z dnia 20 czerwca 1997 roku\\n– Prawo o ruchu drogowym.”.\\nProjekt przyznaje zarządcy drogi kompetencję do wyznaczania miejsc postojowych, ale nie\\nwskazuje zasad, według których kompetencja ta ma być wykonywana.\\nPropozycja PZN\\nW art. 2 projektu UD402 projektowanemu art. 20 pkt 21 ustawy o drogach publicznych\\nproponuje się nadać następujące brzmienie:\\n„21) wyznaczanie miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych\\ndo indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów,\\nhulajnóg elektrycznych lub urządzeń transportu osobistego udostępnianych w ramach\\nmikromobilności dzielonej, w rozumieniu art. 2 pkt 47d ustawy z dnia 20 czerwca 1997 r. –\\nPrawo o ruchu drogowym, w sposób zapewniający bezpieczeństwo i dostępność ruchu\\npieszych, w tym ciągłość trasy wolnej od przeszkód.”.\\nUzasadnienie\\nProjekt ma służyć poprawie dostępności przestrzeni publicznej. Cel ten powinien wynikać z\\nsamego przepisu, a nie wyłącznie z uzasadnienia i OSR.\\nBez proponowanego uzupełnienia miejsce może zostać formalnie wyznaczone na trasie\\nwykorzystywanej przez pieszych, przy elewacji stanowiącej naturalną linię prowadzącą albo\\nw sąsiedztwie oznaczeń fakturowych.\\nOdwołanie do wcześniejszego opracowania\\nProblem został wskazany w opracowaniu z 18 sierpnia 2025 r., w rozdziale II pkt 1\\ndotyczącym zasad parkowania hulajnóg. Postulowano tam ochronę ciągu pieszego, \\f\\n\\nStrona 121 z 219\\n\\nnaturalnych linii prowadzących oraz przestrzeni potrzebnej osobom niewidomym i\\nsłabowidzącym.\\n\\n Art. 2 projektu\\nustawy\\nPolski Związek\\nNiewidomych 4. Jednolite warunki lokalizowania i oznaczania miejsc postojowych\\nAktualna propozycja zawarta w UD402\\nProjekt nie zawiera przepisów określających:\\n sposób lokalizowania miejsc postojowych,\\n wymaganą szerokość dostępnego przejścia,\\n ochronę oznaczeń fakturowych,\\n relację strefy do naturalnych linii prowadzących,\\n sposób oznaczenia granic miejsca,\\n zasady sytuowania miejsc przy przejściach, przystankach i wejściach do budynków,\\n sposób zabezpieczenia przed przewracaniem się urządzeń.\\nProjekt posługuje się jedynie pojęciem miejsca „wyznaczonego przez zarządcę drogi”.\\nPropozycja PZN\\nW art. 2 projektu UD402 proponuje się dodać zmianę ustanawiającą w ustawie o drogach\\npublicznych upoważnienie ustawowe w następującym brzmieniu:\\n„Minister właściwy do spraw transportu określi, w drodze rozporządzenia, szczegółowe\\nwarunki lokalizowania, wyznaczania i oznaczania miejsc, o których mowa w art. 20 pkt 21,\\nmając na uwadze konieczność zapewnienia bezpieczeństwa i dostępności ruchu pieszych,\\nzachowania ciągłości trasy wolnej od przeszkód, ochrony oznaczeń fakturowych i\\nnaturalnych linii prowadzących, bezpieczeństwa dojść do przejść dla pieszych, przystanków i\\nwejść do budynków oraz zapobiegania przewracaniu się pojazdów i ich wystawaniu poza\\ngranice miejsca postoju.”.\\nUzasadnienie \\f\\n\\nStrona 122 z 219\\n\\nBez jednolitych zasad zarządcy dróg mogą stosować rozwiązania całkowicie odmienne, w\\ntym miejsca wyznaczane wyłącznie za pomocą namalowanych linii, bez ochrony dostępnej\\nczęści chodnika i zabezpieczenia przed wystawaniem urządzeń.\\nSzczegółowe wymagania mają charakter techniczny i powinny zostać określone w\\nrozporządzeniu. Delegacja ustawowa powinna jednak precyzyjnie wskazywać cel i zakres\\nregulacji.\\nOdwołanie do wcześniejszego opracowania\\nNasze opracowanie z 18 sierpnia 2025 r. zawierało postulaty dotyczące szerokości\\ndostępnego ciągu pieszego, lokalizowania stref poza podstawową trasą ruchu osób\\nniewidomych oraz czytelnego wyznaczania ich granic.\\n\\n Art. 2  Polski Związek\\nNiewidomych Projekt nakłada obowiązek prawidłowego postoju na użytkownika, ale nie określa\\nobowiązków przedsiębiorcy organizującego usługę.\\nTymczasem operator:\\n decyduje o sposobie działania aplikacji,\\n posiada dane o lokalizacji urządzeń,\\n określa warunki zakończenia najmu,\\n ustala i stosuje własne sankcje regulaminowe,\\n organizuje relokację floty,\\n osiąga przychody z udostępniania urządzeń.\\nOSR wskazuje, że operatorzy będą musieli dostosować floty i aplikacje, a skuteczność\\nregulacji zależy od technicznego powiązania zakończenia najmu z miejscem wyznaczonym.\\nNie znajduje to jednak odzwierciedlenia w proponowanych przepisach.\\n\\n Art. 2 Polski Związek\\nNiewidomych 9. Przekazywanie danych zarządcy drogi\\nAktualna propozycja zawarta w UD402 \\f\\n\\nStrona 123 z 219\\n\\nProjekt nie zobowiązuje operatorów do przekazywania zarządcom dróg informacji\\npozwalających ocenić skuteczność systemu parkowania.\\nNie określa także organu odpowiedzialnego za sprawdzanie, czy prywatne sankcje\\nregulaminowe są rzeczywiście stosowane.\\nPropozycja PZN\\nW art. 2 projektu UD402 proponuje się dodać w ustawie o drogach publicznych po\\nprojektowanym pkt 21 kolejny punkt w brzmieniu:\\n„22) kontrolowanie wykonywania przez operatorów mikromobilności dzielonej obowiązków\\ndotyczących postoju, zgłaszania i usuwania pojazdów oraz pozyskiwanie od operatorów\\nzagregowanych danych niezbędnych do oceny skuteczności wykonywania tych\\nobowiązków.”.\\nPonadto proponuje się dodać w Prawie o ruchu drogowym przepis:\\n„Operator mikromobilności dzielonej przekazuje zarządcy drogi, na jego żądanie,\\nzagregowane dane dotyczące liczby zgłoszeń nieprawidłowego postoju, liczby\\nprzeprowadzonych relokacji, czasu reakcji na zgłoszenia, przypadków zakończenia\\nkorzystania poza miejscem wyznaczonym oraz przypadków nieprawidłowego ustawienia\\npojazdu.”\\nUzasadnienie\\nBez danych zarządca drogi nie będzie mógł ocenić, czy operator skutecznie egzekwuje\\nzasady wobec użytkowników i czy stosowane przez niego środki mają charakter rzeczywisty,\\nczy wyłącznie deklarowany.\\nDane powinny być zagregowane i nie powinny umożliwiać identyfikacji poszczególnych\\nużytkowników.\\n\\nZwiązek\\nPracodawców\\n\\n1. Ad. art. 2 i 3 projektu  \\f\\n\\nStrona 124 z 219\\n\\nArt. 2 i 3\\nprojektu\\nustawy\\n„Transport i\\nLogistyka\\nPolska”\\nOceniając z formalnego punktu widzenia zaproponowane w art. 2 i 3 projektu rozwiązania,\\nwątpliwości budzi wprowadzanie w art. 2 ustawy Prawo o ruchu drogowym (PoRD) definicji\\nusługi wykonywanej w ramach komercyjnej działalności przedsiębiorców! Wykracza to poza\\nzakres przedmiotowo-podmiotowy tego aktu prawnego i powinno być zrealizowane w\\nramach innych aktów prawnych określających rodzaje usług związanych z transportem i\\nzasady ich wykonywania. Prawo o ruchu drogowym jest bowiem aktem prawnym\\nregulującym zasady ruchu drogowego, uprawnienia organów związane z tym ruchem etc.\\nOdnosząc się z kolei do merytorycznego aspektu proponowanych rozwiązań, należy wskazać,\\nże podjęta próba uregulowania niektórych kwestii dotyczących mikromobilności, powinna\\nbyć oceniana z perspektywy spójności systemu transportowego. Mikromobilność\\nwspółdzielona stanowi dziś uzupełniający element systemu transportu miejskiego.\\nObsługuje podróże, dla których komunikacja zbiorowa jest zbyt rzadka, a korzystanie z\\nsamochodu osobowego nie jest konieczne, w tym dojazdy do przystanków i węzłów\\nprzesiadkowych. Rola ta jest szczególnie istotna w dzielnicach, położonych na obrzeżach\\nmiast, gdzie transport „pierwszej i ostatniej mili\\\" ułatwia mieszkańcom dotarcie do pracy czy\\nszkoły, a pośrednio odciąża zarówno linie transportu zbiorowego, jak i układ drogowy.\\nRegulacje dotyczące zasad postoju tych pojazdów, powinny być zatem projektowane tak,\\naby nie ograniczać faktycznej dostępności tej formy przemieszczania się.\\nW tym kontekście zwracamy uwagę, że realizacja celów projektu zależy, co zostało\\ndostrzeżone w jego uzasadnieniu, od odpowiedniego zaprojektowania przez zarządców dróg\\nsieci miejsc postoju, w tym ich rozmieszczenia w lokalizacjach faktycznie dostępnych i\\ndogodnych dla użytkowników. Praktyka ośrodków, w których sieć punktów postoju okazała\\nsię zbyt rzadka, wskazuje, że jej niedostateczna dostępność skutkuje pozostawianiem\\npojazdów poza strefami, i w efekcie podważa cele, którym regulacja ma służyć. Jeżeli\\nobowiązek miałby zostać utrzymany, to zasadne byłoby, aby ustawa lub akty wykonawcze\\nokreślały standardy rozmieszczenia miejsc postoju gwarantujące ich realną dostępność dla\\nużytkowników.\\nPragniemy również podkreślić, że potrzeby transportowe poszczególnych obszarów są\\ngłęboko zróżnicowane. Zjawisko, którego dotyczy regulacja, koncentruje się w największych\\nośrodkach miejskich, co potwierdza sama ocena skutków regulacji, przewidująca, że nową\\nkompetencję będzie aktywnie wykonywać jedynie niewielka część zarządców dróg, objętych\\nprzepisem. Potrzeby przewozowe zdecydowanej większości gmin kształtują się odmiennie\\nniż w metropoliach i rozwiązania ustawowe powinny tę odmienność respektować. Jeszcze \\f\\n\\nStrona 125 z 219\\n\\ninna jest specyfika gmin o charakterze turystycznym, gdzie popyt na mikromobilność\\npojawia się skokowo, wraz z sezonowym szczytem przyjazdów, gdy lokalna komunikacja\\nzbiorowa pracuje na granicy przepustowości. W tych warunkach usługi współdzielone\\nprzejmują część ruchu, pełniąc funkcję sezonowego bufora.\\nZwracamy ponadto uwagę, że operatorzy prowadzą działalność w znacznej mierze na\\npodstawie porozumień z jednostkami samorządu terytorialnego, w ramach których\\nuzgadniane są zasady postoju pojazdów, obszary wyłączone z użytkowania oraz ograniczenia\\nprędkości - z uwzględnieniem charakteru poszczególnych obszarów, natężenia ruchu i\\nlokalnych potrzeb przewozowych. Model ten sprawdza się, ponieważ pozwala różnicować\\nreguły tam, gdzie różnicują się realne potoki ruchu, zamiast stosować jednolite rozwiązanie\\nna obszarze całej gminy. Powszechny obowiązek ustawowy nakładałby się na te rozwiązania\\ni mógłby naruszyć ustalenia wypracowane lokalnie, a w okresie dostosowawczym, którego\\ndługość przewidziana w projekcie budzi nasze wątpliwości, prowadzić do zakłóceń w\\ndostępności usług.\\nMając na uwadze powyższe, proponujemy zastąpienie projektowanego art. 47 ust. 3a PoRD\\nprzepisem zobowiązującym operatora mikromobilności współdzielonej do uregulowania\\nzasad postoju pojazdów w porozumieniu zawieranym z właściwą jednostką samorządu\\nterytorialnego. Określenie w ustawie minimalnego zakresu takiego porozumienia\\nzapewniłoby jednolitość ram prawnych, a jednocześnie pozwoliło dopasować rozwiązania do\\nrealnych potrzeb przewozowych poszczególnych obszarów.\\n\\nArt. 3 pkt 2\\nprojektu\\nustawy\\n\\nLime\\nTechnology sp. z\\no.o.\\n\\n● Art. 3 pkt 2 projektu ustawy - art. 47 ust. 3a-3c ustawy - Prawo o ruchu drogowym:\\nObecne brzmienie projektu nakłada na użytkownika obowiązek zakończenia postoju\\nwyłącznie w miejscu wyznaczonym przez zarządcę drogi, nie uzależniając stosowania tego\\nobowiązku od wcześniejszego utworzenia odpowiedniej sieci miejsc parkingowych ani od\\nuzgodnienia zasad funkcjonowania strefy z operatorami.\\nZamiast projektowanego art. 47 ust. 3a proponuje się wprowadzenie następujących\\nprzepisów:\\n\\n„3a. Zarządca drogi, przed wprowadzeniem obowiązku, o którym mowa w ust. 3b, zawiera z\\npodmiotami świadczącymi na danym obszarze usługę mikromobilności współdzielonej\\nporozumienie określające w szczególności obszar obowiązywania obowiązku parkowania, \\f\\n\\nStrona 126 z 219\\n\\nlokalizację, liczbę, pojemność i sposób oznakowania miejsc parkingowych; termin\\nrozpoczęcia obowiązywania nowych zasad; zakres obowiązków zarządcy drogi i podmiotów\\nświadczących usługę mikromobilności współdzielonej; zasady monitorowania\\nfunkcjonowania strefy oraz wprowadzania zmian wynikających z lokalnych potrzeb.\\n\\n3aa. Porozumienie, o którym mowa w ust. 3a, powinno przewidywać możliwość\\nprzystąpienia do niego na równych i niedyskryminujących zasadach przez podmiot\\nzamierzający rozpocząć świadczenie usługi mikromobilności współdzielonej na obszarze\\nobjętym tym porozumieniem. Podmiot ten jest obowiązany przystąpić do porozumienia przed\\nrozpoczęciem świadczenia usługi na tym obszarze\\n\\n3b. Na obszarze i od dnia określonego w porozumieniu, o którym mowa w ust. 3a, po\\nwyznaczeniu i oznakowaniu właściwych miejsc parkingowych, osoba pozostawiająca pojazd\\nlub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach,\\nw szczególności rower, hulajnogę elektryczną lub urządzenie transportu osobistego\\nudostępnione w ramach mikromobilności współdzielonej, jest zobowiązana pozostawić ten\\npojazd lub urządzenie wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę drogi.\\n\\n3c. Do czasu zawarcia porozumienia, o którym mowa w ust. 3a, oraz wyznaczenia i\\noznakowania właściwych miejsc parkingowych, a także poza obszarem objętym takim\\nporozumieniem, do parkowania pojazdów i urządzeń udostępnianych w ramach\\nmikromobilności współdzielonej nie stosuje się ust. 3a do 3b.”.\\n\\nW takim modelu obowiązek parkowania nadal wynikałby bezpośrednio z ustawy.\\nPorozumienie określałoby natomiast jego terytorialny i operacyjny zakres oraz moment\\nrozpoczęcia stosowania. Mogłoby ono obejmować całą gminę albo jedynie określone strefy,\\nw których obowiązkowe parkowanie jest uzasadnione lokalnymi warunkami.\\nJeżeli zarządca drogi nie zawrze porozumienia lub nie wyznaczy i nie oznakuje odpowiednich\\nmiejsc parkingowych, nadal obowiązywałyby ogólne zasady parkowania.\\n\\nArt. 3 pkt 3\\nprojektu\\nustawy\\n\\nOgólnopolski\\nZwiązek\\nWojewódzkich\\n\\nW art. 3 po pkt. 3 proponujemy dodać pkt 4 w brzmieniu:\\n1)  w art. 119 ust. 3 uchyla się pkt 4.\\n2)  art. 119 ust. 4 otrzymuje brzmienie: \\f\\n\\nStrona 127 z 219\\n\\nOśrodków\\nRuchu\\nDrogowego\\n„4. Ośrodek ponosi wydatki na działania na rzecz poprawy bezpieczeństwa ruchu drogowego\\nna obszarze województwa, w szczególności na popularyzację zasad ruchu drogowego oraz\\npodnoszenie kultury jazdy kierowców”.\\n3)   po ust. 4 dodaje się ust. 4a w brzmieniu:\\n„4a. Wydatki, o których mowa w ust. 4, mogą być finansowane ze środków zgromadzonych\\nna funduszu zapasowym ośrodka. Przeznaczenie środków funduszu zapasowego następuje z\\nzachowaniem zdolności ośrodka do terminowego wykonywania jego zobowiązań.”\\n\\nUzasadnienie do pkt. 13\\n\\nProjektowana zmiana ma na celu zwiększenie efektywności wykorzystania środków\\nfinansowych zgromadzonych przez wojewódzkie ośrodki ruchu drogowego oraz\\nwzmocnienie realizacji ustawowych zadań związanych z poprawą bezpieczeństwa ruchu\\ndrogowego. Obecne przepisy, które określają szczegółowe warunki gospodarki finansowej\\nwojewódzkich ośrodków ruchu drogowego są zawarte w Rozporządzeniu Ministra\\nInfrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki\\nfinansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków\\newidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376).\\nRozporządzenie to zastąpiło poprzednio obowiązujący akt, tj. Rozporządzenie Ministra\\nInfrastruktury z dnia 2 października 2002 r. w sprawie szczegółowych warunków gospodarki\\nfinansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków\\newidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. Nr 176, poz.\\n1443) i wprowadziło zmianę w zakresie przeznaczenia funduszu zapasowego. Zgodnie z\\ntreścią § 5 poprzednio obowiązującego Rozporządzenia, fundusz zapasowy był przeznaczony\\ndo dyspozycji ośrodka na finansowanie działalności, o której mowa w art. 117 ust. 1 i 2\\nustawy - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251), a zatem również na\\npotrzeby szeroko rozumianej działalności oświatowej dot. bezpieczeństwa w ruchu\\ndrogowym oraz realizacji innych, doniosłych zadań z zakresu tego bezpieczeństwa. Obecnie\\nnatomiast, zgodnie z aktualnym Rozporządzeniem, fundusz zapasowy może być\\nprzeznaczony jedynie na pokrycie strat netto ośrodka. W praktyce oznacza to, że środki\\nzgromadzone w funduszu zapasowym pozostają niewykorzystane do czasu wystąpienia\\nujemnego wyniku finansowego, niezależnie od istniejących potrzeb w zakresie realizacji\\ndziałań służących poprawie bezpieczeństwa ruchu drogowego. Jednocześnie działania na \\f\\n\\nStrona 128 z 219\\n\\nrzecz poprawy bezpieczeństwa ruchu drogowego stanowią jedno z podstawowych zadań\\nwojewódzkich ośrodków ruchu drogowego, wynikających bezpośrednio z ustawy. Nie mają\\none charakteru działalności dodatkowej ani fakultatywnej, lecz pozostają integralnym\\nelementem misji publicznej realizowanej przez te podmioty.\\nBrak jest dostatecznego uzasadnienia dla utrzymywania stanu, w którym środki\\nzgromadzone przez ośrodek pozostają zarezerwowane wyłącznie na pokrycie potencjalnych\\nprzyszłych strat, podczas gdy mogą zostać wykorzystane do realizacji ustawowych zadań\\nsłużących ograniczaniu liczby wypadków drogowych, zwiększaniu świadomości uczestników\\nruchu drogowego oraz podnoszeniu poziomu bezpieczeństwa na drogach. Proponowane\\nrozwiązanie wychodzi z założenia, że środki funduszu zapasowego powinny służyć nie tylko\\nochronie stabilności finansowej ośrodka, lecz również wspierać realizację celów publicznych,\\ndla których wojewódzkie ośrodki ruchu drogowego zostały utworzone. Umożliwienie\\nfinansowania działań na rzecz bezpieczeństwa ruchu drogowego ze środków funduszu\\nzapasowego pozwoli na bardziej racjonalne i efektywne gospodarowanie zgromadzonym\\nmajątkiem, przy jednoczesnym zachowaniu bezpieczeństwa finansowego jednostek.\\nPowrót do finansowania wydatków, w części przeznaczonej na poprawę bezpieczeństwa\\nruchu drogowego z funduszu zapasowego, bez wątpienia umożliwiłby zwiększenie\\nskuteczności i efektywności pomocy m.in. placówkom edukacyjno-oświatowym\\nprzygotowującym dzieci i młodzież do świadomego i bezpiecznego udziału w ruchu\\ndrogowym na terenie naszego kraju, a ponadto znacząco odciążyłby fundusz z bieżącej\\ndziałalności ośrodków.\\nProjektowana regulacja nie zmienia charakteru funduszu zapasowego jako instrumentu\\nwzmacniającego stabilność finansową ośrodka, lecz rozszerza katalog dopuszczalnych\\nsposobów jego wykorzystania o finansowanie działań pozostających w bezpośrednim\\nzwiązku z ustawowymi zadaniami wojewódzkich ośrodków ruchu drogowego. Rozwiązanie\\nto zapewni możliwość przeznaczania wypracowanych przez ośrodki nadwyżek finansowych\\nna cele służące interesowi publicznemu, bez konieczności oczekiwania na wystąpienie\\nokoliczności uzasadniających pokrywanie strat.\\nNależy jeszcze raz podkreślić, że finansowanie działań na rzecz poprawy bezpieczeństwa\\nruchu drogowego ze środków funduszu zapasowego nie stanowi przeznaczenia tych\\nśrodków na cele niezwiązane z działalnością ośrodka. Przeciwnie, środki te byłyby\\nwykorzystywane na realizację zadań ustawowo przypisanych wojewódzkim ośrodkom ruchu\\ndrogowego. Proponowana zmiana prowadzi zatem do silniejszego powiązania sposobu \\f\\n\\nStrona 129 z 219\\n\\nwykorzystania wypracowanych nadwyżek finansowych z podstawowymi celami działalności\\nośrodków,\\na tym samym wzmacnia funkcjonalny związek pomiędzy gospodarką finansową ośrodka,\\na realizacją powierzonych mu zadań publicznych.\\n\\nDo ew. wykorzystania:\\n\\nProponowane brzmienie przepisu Rozporządzenia Ministra Infrastruktury z dnia 3 lipca 2023\\nr. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu\\ndrogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z\\ndziałalnością ośrodka (Dz. U. poz. 1376):\\nKonsekwencją wprowadzenia powyższej zmiany do Ustawy - Prawo o ruchu drogowym (t.j.\\nDz. U. z 2024 r. poz. 1251) jest dostosowanie obecnego brzmienia Rozporządzenia Ministra\\nInfrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki\\nfinansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków\\newidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376).\\nRozporządzenie jako akt wykonawczy do ustawy nie może pozostawać z nią w sprzeczności,\\nstąd konieczna jest modyfikacja treści § 5 Rozporządzenia. Wynika to z konstytucyjnej\\nzasady zgodności rozporządzeń z ustawą. Wobec powyższego koniecznym jest także\\ndokonanie zmiany § 5 ust. 2 ww. Rozporządzenia o proponowanej treści:\\n\\n§ 5 ust. 2 otrzymuje brzmienie:\\n„Fundusz zapasowy jest przeznaczony na:\\n1. pokrycie strat netto ośrodka;\\n2. finansowanie wydatków na działania na rzecz poprawy bezpieczeństwa ruchu drogowego,\\no których mowa w art. 119 ust. 4 ustawy.”\\n\\nArt. 3 projektu\\nustawy\\n\\nZwiązek\\nPowiatów\\nPolskich\\n\\nJako organizacja reprezentująca środowisko przedsiębiorców przywiązujemy szczególną\\nwagę do jakości stanowionego prawa, w tym do zasady proporcjonalności oraz\\nadekwatności instrumentów regulacyjnych do skali zjawiska, którego dotyczą. W naszej\\nocenie projektowany, powszechny obowiązek zakończenia postoju pojazdów \\f\\n\\nStrona 130 z 219\\n\\nmikromobilności dzielonej wyłącznie w miejscach wyznaczonych przez zarządcę drogi budzi\\nw tym kontekście istotne wątpliwości.\\nZ oceny skutków regulacji wynika, że kompetencję wyznaczania miejsc postoju będzie\\naktywnie wykonywać jedynie ok. 100–150 zarządców dróg spośród blisko 2 800 potencjalnie\\nobjętych przepisem. Oznacza to, że instrument o charakterze powszechnym projektowany\\njest w odpowiedzi na zjawisko występujące lokalnie, skoncentrowane w największych\\nośrodkach miejskich. Dobre praktyki legislacyjne nakazują w takiej sytuacji rozważenie\\nrozwiązań o węższym, precyzyjnie określonym zakresie podmiotowym, na przykład\\nograniczonym do gmin o określonej liczbie mieszkańców, zamiast obejmowania\\nobowiązkiem ogółu jednostek, w tym takich, w których zjawisko nie występuje, a zasoby\\nadministracyjne są ograniczone.\\nUsankcjonowanie praktyki współpracy operatorów z samorządami\\nZwracamy również uwagę, że regulacja nakładałaby się na rozwiązania funkcjonujące już w\\npraktyce. Operatorzy usług współdzielonych prowadzą działalność w znacznej mierze na\\npodstawie porozumień z jednostkami samorządu terytorialnego, których treść jest\\nkażdorazowo dostosowywana do lokalnych potrzeb i które określają m.in. zasady postoju\\nudostępnianych pojazdów, obszary wyłączone z użytkowania oraz ograniczenia prędkości w\\nmiejscach intensywnego ruchu pieszego. Wprowadzenie powszechnego obowiązku\\nustawowego oznaczałoby konieczność ponownego wykonania pracy, która w znacznej\\nmierze została już wykonana, i mogłoby naruszyć rozwiązania wypracowane lokalnie. Z\\nperspektywy przedsiębiorców rodzi to również ryzyko niestabilności otoczenia prawnego dla\\npodmiotów, które poniosły nakłady na dostosowanie działalności do ustaleń z samorządami,\\nw tym w odpłatne tytuły prawne do gruntów wykorzystywanych jako strefy parkowania.\\nSkutki finansowe i operacyjne proponowanych zmian\\nOdrębnym zagadnieniem są koszty dostosowawcze i wykonalność regulacji w przewidzianym\\nokresie przejściowym. Uzasadnienie projektu samo przyznaje, że skala niezbędnych prac po\\nstronie zarządców dróg jest znaczna, a w największych miastach liczba wymaganych\\nlokalizacji może sięgać kilku tysięcy. Równolegle, dostosowania wymagać będą systemy i\\numowy operatorów. W tych warunkach zasadne byłoby wydłużenie okresu przejściowego\\nlub powiązanie momentu rozpoczęcia stosowania obowiązku z rzeczywistym utworzeniem\\nsieci miejsc postoju w danej gminie.\\nSugerowany kierunek zmian  \\f\\n\\nStrona 131 z 219\\n\\nMając na uwadze powyższe, postulujemy rozważenie zastąpienia powszechnego obowiązku\\nokreślonego w projektowanym art. 47 ust. 3a ustawy – Prawo o ruchu drogowym\\nrozwiązaniem alternatywnym, polegającym na wprowadzeniu ustawowego obowiązku\\nzawarcia przez operatora mikromobilności współdzielonej porozumienia z właściwą\\njednostką samorządu terytorialnego, określającego zasady postoju udostępnianych\\npojazdów. Jednolitość ram prawnych można osiągnąć poprzez określenie minimalnej,\\nobowiązkowej treści takich porozumień. Rozwiązanie to realizowałoby cele projektu przy\\nistotnie niższych kosztach regulacyjnych i bez naruszania mechanizmów współpracy\\nfunkcjonujących już w praktyce.\\n\\n Art. 3 projektu\\nustawy\\nAmerykańska\\nIzba Handlowa\\nw Polsce\\nAmCham popiera działania służące poprawie bezpieczeństwa pieszych, zachowaniu\\ndostępności chodników oraz uporządkowaniu sposobu pozostawiania pojazdów.\\nObowiązkowe miejsca postojowe mogą być skutecznym rozwiązaniem, pod warunkiem że ich\\nwprowadzenie będzie poprzedzone stworzeniem infrastruktury odpowiadającej rzeczywistym\\npotrzebom mieszkańców i charakterystyce poszczególnych części miasta.\\nSystemy mikromobilności współdzielonej od lat działają w wielu miastach Stanów\\nZjednoczonych. Amerykańskie doświadczenia i badania dotyczące funkcjonowania takich\\nusług wskazują, że jednym z najważniejszych czynników decydujących o prawidłowym\\nparkowaniu oraz wygodzie użytkowników jest odpowiednie zagęszczenie miejsc postojowych.\\nZa efektywną uznaje się sieć umożliwiającą znalezienie parkingu mniej więcej co 200–250\\nmetrów. Jeżeli odległości są większe, użytkownicy częściej rezygnują z prawidłowego\\nzakończenia przejazdu, a sama usługa traci swoją podstawową zaletę tj. możliwość sprawnego\\ndotarcia blisko miejsca docelowego.\\nSzczególne znaczenie ma to w centrach miast, gdzie występują duże natężenie ruchu,\\nograniczona przestrzeń oraz częste konflikty między różnymi sposobami jej wykorzystania. To\\nwłaśnie tam obowiązkowe parkowanie może najlepiej porządkować przestrzeń publiczną, o\\nile parkingi są widoczne, łatwo dostępne i rozmieszczone zgodnie z rzeczywistymi kierunkami\\nprzemieszczania się użytkowników. Zbyt rzadka sieć miejsc może natomiast powodować\\nkumulowanie się pojazdów, utrudniać kończenie przejazdów i prowadzić do pozostawiania\\nsprzętu poza wyznaczonymi punktami. \\f\\n\\nStrona 132 z 219\\n\\nJednocześnie jednolite objęcie obowiązkowym parkowaniem całego obszaru miasta może nie\\nodpowiadać jego zróżnicowanym potrzebom. W dzielnicach oddalonych od centrum hulajnogi\\ni rowery współdzielone często pełnią funkcję dojazdu do przystanków, stacji kolejowych,\\nszkół, uczelni i miejsc pracy. Na terenach o bardziej rozproszonej zabudowie stworzenie\\nrównie gęstej sieci fizycznie oznakowanych parkingów może być trudne i kosztowne.\\nOgraniczenie możliwości zakończenia przejazdu wyłącznie do nielicznych punktów mogłoby w\\npraktyce pozbawić mieszkańców dostępu do usługi oraz osłabić jej rolę jako uzupełnienia\\ntransportu publicznego.\\nDlatego za szczególnie ważne uznajemy zachowanie podejścia elastycznego i strefowego.\\nBardziej rygorystyczne zasady mogą być stosowane w centrach, przy węzłach\\nkomunikacyjnych i w miejscach wskazanych przez miasta jako problematyczne. Poza takimi\\nobszarami powinny być możliwe rozwiązania dostosowane do lokalnych warunków,\\nuwzględniające dotychczasowe zasady parkowania, rzeczywisty popyt oraz dostępność\\nprzestrzeni.\\nKluczowa pozostaje również współpraca zarządców dróg z operatorami. Firmy świadczące\\nusługi mikromobilności dysponują danymi o trasach przejazdów, miejscach ich rozpoczynania\\ni kończenia oraz obszarach o największym zapotrzebowaniu. Informacje te pozwalają\\nwłaściwie zaplanować liczbę, lokalizację i pojemność parkingów. Operatorzy mogą także\\nwspierać przestrzeganie zasad za pomocą geolokalizacji, komunikatów w aplikacji, blokowania\\nmożliwości zakończenia przejazdu w niewłaściwym miejscu oraz weryfikacji zdjęć\\nzaparkowanych pojazdów.\\nAmCham zwraca również uwagę na potrzebę proporcjonalności obowiązków, opłat i sankcji.\\nPowinny one skutecznie przeciwdziałać naruszeniom, ale jednocześnie uwzględniać specyfikę\\nlekkich pojazdów współdzielonych oraz rzeczywiste koszty ich usuwania i przechowywania.\\nNadmierne obciążenia mogą przełożyć się na wzrost cen dla użytkowników lub wycofywanie\\nusługi z mniej rentownych dzielnic i mniejszych miast.\\nW ocenie AmCham dalsze prace nad projektem powinny zmierzać w kierunku modelu, który: \\f\\n\\nStrona 133 z 219\\n\\n● zapewni odpowiednio gęstą i funkcjonalną sieć parkingów, zwłaszcza w centrach\\nmiast;\\n● pozostawi samorządom możliwość dostosowania zasad do lokalnych potrzeb;\\n● ochroni dostępność mikromobilności na obrzeżach i terenach słabiej obsługiwanych\\nprzez transport publiczny;\\n● oprze organizację systemu na współpracy i wymianie danych między miastami a\\noperatorami.\\n\\n Art. 3 projektu\\nustawy\\nKonfederacja\\nLewiatan\\n Uwagi w zakresie: art. 47 ust. 3a ustawy – Prawo o ruchu drogowym, wprowadzającym\\npowszechny obowiązek zakończenia postoju pojazdów mikromobilności dzielonej wyłącznie\\nw miejscach wyznaczonych przez zarządcę drogi, oraz na powiązanych zmianach w art. 130a\\ntej ustawy.\\nKonfederacja Lewiatan z uznaniem odnosi się do działań ustawodawcy zmierzających do\\nzwiększenia przejrzystości i bezpieczeństwa regulacyjnego rynku. Dotychczasowe zmiany\\nprzepisów w istotnym stopniu uporządkowały obowiązujące ramy prawne, a jednocześnie\\nstworzyły uczestnikom rynku możliwość wypracowania dobrych praktyk w zakresie ich\\nstosowania. Doświadczenia zebrane w okresie obowiązywania tych regulacji pozwalają dziś\\nzidentyfikować rozwiązania, które sprawdziły się w praktyce, jak również obszary\\nwymagające doprecyzowania. W ocenie Konfederacji Lewiatan obecna nowelizacja stanowi\\ndobrą okazję do wzmocnienia wypracowanych dobrych praktyk, zwiększenia pewności\\nprawa oraz wyeliminowania wątpliwości interpretacyjnych, przy jednoczesnym zachowaniu\\ncelów, które przyświecały wcześniejszym zmianom legislacyjnym wobec czego chcielibyśmy\\nzasygnalizować na wstępie elementy, które - w naszej ocenie - budzą pewne wątpliwości.\\nZwracamy uwagę na potrzebę oceny proponowanych co do relacji proponowanych\\nrozwiązań do konstytucyjnych zasad pomocniczości i decentralizacji władzy publicznej.\\nOrganizacja transportu lokalnego, zagospodarowanie przestrzeni publicznej oraz organizacja\\nruchu drogowego należą do zadań własnych gmin (art. 7 ust. 1 pkt 1, 2 i 4 ustawy o\\nsamorządzie gminnym). Zgodnie z preambułą oraz art. 15 ust. 1 Konstytucji RP ustrój\\nterytorialny Rzeczypospolitej opiera się na decentralizacji, a art. 165 ust. 2 Konstytucji RP\\ngwarantuje ochronę samodzielności jednostek samorządu terytorialnego. Kierunek ten\\npotwierdza Europejska Karta Samorządu Lokalnego, której art. 4 ust. 3 przewiduje, że \\f\\n\\nStrona 134 z 219\\n\\nwykonywanie zadań publicznych powinno zasadniczo należeć do organów najbliższych\\nobywatelom. Narzucenie w ustawie jednego, jednolitego modelu parkowania pojazdów\\nmikromobilności, bez pozostawienia gminom realnej swobody wyboru innych skutecznych\\nrozwiązań, stanowi w naszej ocenie ingerencję w sferę wymagającą uwzględnienia lokalnych\\nuwarunkowań i może pozostawać w sprzeczności z powołanymi zasadami.\\nIngerencja ta jest tym trudniejsza do uzasadnienia, że samorządy wypracowały już we\\nwspółpracy z operatorami skuteczne instrumenty zarządzania mikromobilnością. Działalność\\noperatorów prowadzona jest w znacznej mierze na podstawie porozumień z poszczególnymi\\njednostkami samorządu terytorialnego, których treść jest każdorazowo dostosowana do\\nlokalnych potrzeb: wyznaczane są strefy obowiązkowego parkowania tam, gdzie jest to\\nrzeczywiście uzasadnione, strefy ograniczonej prędkości w obszarach intensywnego ruchu\\npieszego oraz obszary całkowicie wyłączone z użytkowania. Ograniczenia te są egzekwowane\\nnie za pomocą znaków czy kontroli na miejscu, lecz zdalnie, przy pomocy narzędzi\\ntechnologicznych operatora, które uniemożliwiają np. zakończenie przejazdu poza\\nwyznaczoną strefą. Wprowadzenie powszechnego obowiązku ustawowego dublowałoby\\nzatem działania już podjęte przez administrację samorządową i mogłoby podważyć ustalenia\\nfunkcjonujące lokalnie.\\nPodkreślamy również, że sytuacja poszczególnych jednostek samorządu terytorialnego jest\\ngłęboko zróżnicowana i jednolite rozwiązanie ustawowe nie jest w stanie tego zróżnicowania\\nuwzględnić. Skalę tego zróżnicowania obrazują dane przywołane w ocenie skutków regulacji:\\nspośród blisko 2 800 zarządców dróg objętych projektowanym przepisem realne\\nwykonywanie nowej kompetencji przewiduje się jedynie w przypadku około stu\\npięćdziesięciu z nich. Dla pozostałych jednostek obowiązek miałby zatem charakter w istocie\\npusty, albo generowałby obciążenia nieadekwatne do skali zjawiska na ich terenie. Odrębną\\nkategorię stanowią gminy turystyczne, w których zapotrzebowanie na usługę zależy od\\nsezonowego napływu turystów, a lokalne linie transportu zbiorowego są dodatkowo\\nobciążone w miesiącach letnich. Jednocześnie projektowanie, dostosowanie i utrzymywanie\\nstref postoju generuje koszty i potrzeby kadrowe, na które wiele mniejszych jednostek\\nsamorządu terytorialnego nie może sobie pozwolić. Nakładanie na wszystkie gminy\\nobowiązku zaprojektowanego z myślą o realiach dużych ośrodków miejskich oznaczałoby\\nprzeniesienie na samorządy ciężarów nieproporcjonalnych do skali problemu na ich terenie.\\nMając na uwadze powyższe, postulujemy, aby w miejsce powszechnego obowiązku z\\nprojektowanego art. 47 ust. 3a ustawy – Prawo o ruchu drogowym ustawodawca zobowiązał \\f\\n\\nStrona 135 z 219\\n\\noperatorów mikromobilności współdzielonej do zawarcia z właściwą jednostką samorządu\\nterytorialnego porozumienia określającego zasady postoju udostępnianych pojazdów,\\npozostawiając gminom wypracowanie szczegółów stosownie do lokalnych uwarunkowań.\\nWskazywaną w ocenie skutków regulacji potrzebę jednolitości ram prawnych zaspokoiłoby\\nustawowe określenie obligatoryjnych elementów takiego porozumienia.\\n\\nArt. 3 projektu\\nustawy\\n\\nPolskie\\nStowarzyszenia\\nNowej\\nMobilności\\n\\n Działalność operatorów prowadzona jest obecnie w znacznej mierze na podstawie\\nporozumień zawieranych z poszczególnymi jednostkami samorządu terytorialnego, których\\ntreść jest każdorazowo dostosowana do lokalnych potrzeb i specyfiki danej przestrzeni\\nmiejskiej. W ramach tych porozumień samorządy wskazują strefy, w których pojazd\\nsamoczynnie ogranicza prędkość, np. do 15 km/h, wyznaczane tam, gdzie ruch pieszy jest\\nszczególnie intensywny, strefy wyłączone z użytkowania, obejmujące zwykle parki i tereny\\nzielone, a także obszary obowiązkowego parkowania w miejscach, w których jest to\\nrzeczywiście uzasadnione, czego przykładem jest obszar Starego Miasta w Warszawie.\\nWszystkie te ograniczenia są egzekwowane zdalnie, w czasie rzeczywistym, za pomocą\\nsystemów geofencingu, tj. elektronicznego wyznaczania granic obszarów w aplikacji\\nmobilnej operatora. Model ten pozwala precyzyjnie różnicować zasady korzystania z\\nmikromobilności w zależności od charakteru poszczególnych obszarów, natężenia ruchu i\\npotrzeb mieszkańców. Powszechny obowiązek ustawowy oznaczałby dla samorządów i\\noperatorów konieczność powtórnego przeprowadzenia procesu, który w wielu miastach\\nzostał już zakończony i przynosi oczekiwane efekty.\\nZ doświadczeń operacyjnych wynika, że o powodzeniu każdego modelu opartego na\\nwyznaczonych miejscach postoju decydują dwa czynniki: gęstość sieci oraz jej czytelne\\noznakowanie. Doświadczenia miast, w których punkty postoju rozmieszczone są zbyt rzadko,\\npokazują, że niedostępność stref prowadzi do frustracji użytkowników i nieprawidłowego\\nparkowania. Równie istotna jest identyfikacja wizualna – praktyka wskazuje, że oznakowanie\\npunktów postoju bywa nieadekwatne do potrzeb użytkowników, m.in. ze względu na słabą\\nwidoczność. Przykładem dobrze zaprojektowanego systemu stref jest Poznań, gdzie miejsca\\nparkowania są wyraźnie wyodrębnione wizualnie i wyposażone w znaki pionowe, a przez to\\nłatwe do zidentyfikowania zarówno przez mieszkańców, jak i turystów. Jeżeli obowiązek\\nmiałby zostać utrzymany, zasadne byłoby, aby ustawa lub akty wykonawcze określały\\nmierzalne wymogi dotyczące gęstości i dostępności sieci miejsc postoju – w przeciwnym \\f\\n\\nStrona 136 z 219\\n\\nrazie nowy obowiązek może okazać się w praktyce niewykonalny dla użytkowników i\\nprowadzić do faktycznego ograniczenia dostępności tej formy transportu.\\nOdrębnego rozważenia wymaga długość przewidzianego w projekcie okresu przejściowego.\\nUzasadnienie projektu przyznaje, że w większych miastach liczba wymaganych lokalizacji\\nmoże sięgać kilkuset, a nawet kilku tysięcy, a ich wyznaczenie wymaga analiz potrzeb,\\noznakowania oraz uzgodnień konserwatorskich w obszarach zabytkowych. Równolegle\\noperatorzy będą musieli przebudować systemy informatyczne, w tym mechanizmy\\ngeofencingu i blokady zakończenia przejazdu poza strefą, oraz aneksować umowy z\\nsamorządami. Istotne jest przy tym, że w obecnym modelu nierzadką sytuacją jest\\nzawieranie umów, na podstawie których udostępniane są przestrzenie pod strefy\\nparkowania. Wprowadzenie prawnego obowiązku wyznaczania takich miejsc mogłoby\\nzakwestionować ten model, na którym oparte są obowiązujące umowy. Postuluje się w\\nzwiązku z tym wydłużenie okresu przejściowego albo uzależnienie stosowania obowiązku od\\nfaktycznego utworzenia sieci miejsc postoju na terenie danej gminy.\\nWarto jednocześnie zwrócić uwagę, że usługi współdzielonej mikromobilności funkcjonują\\ndziś w ograniczonej liczbie ośrodków, przede wszystkim w największych miastach, i tam też\\nkoncentruje się zjawisko, na które odpowiada projekt, co znajduje potwierdzenie w ocenie\\nskutków regulacji. Obejmowanie powszechnym obowiązkiem także gmin, w których usługa\\nnie jest i w przewidywalnej przyszłości nie będzie świadczona, nie przybliża realizacji celów\\nregulacji. Zakres podmiotowy obowiązku powinien uwzględniać tę koncentrację oraz\\nzróżnicowanie sytuacji poszczególnych jednostek samorządu terytorialnego, w tym gmin\\nturystycznych, w których zapotrzebowanie na usługę ma charakter sezonowy.\\n\\nW związku z powyższym wnosi się o rozważenie zastąpienia powszechnego obowiązku\\nokreślonego w projektowanym art. 47 ust. 3a ustawy – Prawo o ruchu drogowym\\nrozwiązaniem alternatywnym, polegającym na wprowadzeniu ustawowego obowiązku\\nzawarcia przez operatora mikromobilności współdzielonej porozumienia z właściwą\\njednostką samorządu terytorialnego, określającego zasady postoju udostępnianych\\npojazdów. Jednolitość ram prawnych, wskazywaną w ocenie skutków regulacji jako zaletę\\nprojektu, można osiągnąć poprzez określenie minimalnej, obowiązkowej treści takich\\nporozumień. Rozwiązanie to nadałoby ramę ustawową modelowi współpracy, który nasi\\nczłonkowie z powodzeniem stosują w praktyce. \\f\\n\\nStrona 137 z 219\\n\\n Art. 3 projektu\\nustawy\\nemTransit\\nsp. z o.o.\\nSpołka co do zasady popiera cel Projektu, jakim jest uporządkowanie zasad postoju\\npojazdow mikromobilności dzielonej w przestrzeni publicznej, jednocześnie jednak zwraca\\nuwagę, że część projektowanych rozwiązań - w obecnym brzmieniu - może wywołać skutki\\nodwrotne do zamierzonych i w praktyce utrudnić świadczenie usług mikromobilności\\ndzielonej w części gmin.\\n\\nSpołka pozytywnie ocenia wprowadzenie do ustawy - Prawo o ruchu drogowym definicji\\nmikromobilności dzielonej (projektowany art. 2 pkt 47d) oraz przyznanie zarządcom drog\\nwyraźnej kompetencji do wyznaczania miejsc postoju pojazdow mikromobilności dzielonej\\n(projektowany art 20 pkt 21 ustawy o drogach publicznych). Rozwiązania te odpowiadają\\nwypracowanej już praktyce wspołpracy Operatorow z miastami i zasługują na poparcie co do\\nkierunku.\\nZasadnicze zastrzeżenia Społki budzi natomiast konstrukcja obowiązku postoju wyłącznie w\\nmiejscach wyznaczonych (projektowany art. 47 ust. 3a) w powiązaniu z sankcją usunięcia\\npojazdu z drogi (projektowany art. 130a ust. 1 pkt 8 oraz ust. 6a lit. i). Uwagi w tym zakresie\\nprzedstawiamy poniżej.\\n Art. 3 pkt 2\\nprojektu\\nustawy\\nemTransit\\nsp. z o.o.\\nIII. Uwaga zasadnicza: projektowany art. 130a ust 1 pkt 8 w związku z art 47 ust 3a ustawy -\\nPrawo o ruchu drogowym\\n1. Istota problemu - obowiązek bez gwarancji infrastruktury. Projektowany art. 47 ust. 3a\\nnakłada na użytkownika bezwzględny obowiązek zakończenia postoju „wyłącznie w\\nmiejscu wyznaczonym do tego celu przez zarządcę drogi”, a projektowany art. 130a ust. 1\\npkt 8 przewiduje usunięcie pojazdu pozostawionego poza takim miejscem. Projekt nie\\nnakłada jednak na zarządcę drogi żadnego obowiązku wyznaczenia takich miejsc, nie określa\\nich minimalnej gęstości ani trybu ich uzgadniania z Operatorami - wyznaczanie\\nmiejsc pozostaje wyłącznie uprawnieniem zarządcy drogi (projektowany art. 20 pkt 21\\nustawy o drogach publicznych).\\nPrzepis nie precyzuje jednak, jak należy interpretować sytuację, w ktorej na danym obszarze\\nzarządca drogi nie wyznaczył jeszcze żadnych miejsc postojowych albo wyznaczył je w\\nliczbie lub lokalizacjach nieodpowiadających rzeczywistym potrzebom użytkownikow. Bez\\ntakiego doprecyzowania nie można wykluczyć interpretacji, zgodnie z ktorą każdorazowe\\nzakończenie przejazdu na takim obszarze stanowiłoby naruszenie art. 47 ust. 3a i podstawę\\nusunięcia pojazdu na koszt Operatora (200 zł za usunięcie oraz 50 zł za każdą dobę \\f\\n\\nStrona 138 z 219\\n\\nprzechowywania). W takim ujęciu o możliwości faktycznego prowadzenia działalności\\ngospodarczej na danym obszarze decydowałaby nie ustawa, lecz tempo działania zarządcy\\ndrogi w zakresie wyznaczania miejsc postojowych, co w skrajnym przypadku mogłoby\\nprowadzić do wyłączenia usług mikromobiiności dzielonej w części kraju.\\nNiezależnie od tego, ktorą interpretację ostatecznie przyjęto by w praktyce stosowania\\nprzepisu, sama ta niejednoznaczność rodzi po stronie Operatorow istotną niepewność co do\\nwarunkow prowadzenia działalności w poszczegolnych gminach, a w konsekwencji utrudnia\\npodejmowanie decyzji inwestycyjnych i operacyjnych. Z tego względu Społka postuluje\\njednoznaczne doprecyzowanie przepisu w kierunku wskazanym w pkt. 3 poniżej, co pozwoli\\nuniknąć niepewności, utrudniające prowadzenie działalności gospodarczej w tym zakresie.\\n2. Nieproporcjonalność sankcji i pominięcie możliwości technicznych Operatorow. Usunięcie\\npojazdu przez podmiot wyznaczony przez starostę jest środkiem najdalej idącym i\\nnajbardziej kosztownym, podczas gdy Operatorzy - w odrożnieniu od właścicieli pojazdow\\nindywidualnych, dysponują narzędziami pozwalającymi usunąć nieprawidłowość\\nniezwłocznie i bez angażowania środkow publicznych: dzięki wbudowanemu w każdym\\npojeżdzie systemowi GPS, Operatorzy mają podgląd co do lokalizacji jej floty, a lokalne\\nzespoły serwisowe, ktorych zadaniem jest m.in, relokacja pojazdow, działają w trybie\\nciągłym. Projekt nie przewiduje jednak żadnego trybu uprzedniego wezwania Operatora do\\nrelokacji pojazdu. W rezultacie środek publicznoprawny staje się środkiem pierwszego\\nwyboru, generującym koszty po stronie Operatorow i obciążenia organizacyjne po stronie\\npowiatow, mimo że ten sam skutek (usunięcie pojazdu z miejsca niedozwolonego)\\nOperatorzy mogą osiągnąć szybciej i bez kosztow publicznych.\\n3. Propozycja Społki - ustawowy mechanizm porozumień z zarządcami drog oraz gwarancja\\nodpowiedniej gęstości miejsc postojowych. Społka proponuje oparcie projektowanego\\nmechanizmu na sprawdzonym modelu funkcjonującym obecnie m.in. w Warszawie,\\nPoznaniu, Krakowie i Gdańsku, tj. na umowach (porozumieniach) zawieranych pomiędzy\\nzarządcą drogi (miastem) a Operatorami. Proponujemy, aby:\\n- obowiązek zakończenia postoju wyłącznie w miejscu wyznaczonym (art. 47 ust. 3a) oraz\\npowiązana z nim sankcja usunięcia pojazdu (art. 130a ust. 1 pkt 8) znajdowały\\nzastosowanie wyłącznie na obszarze, dla ktorego zarządca drogi zawarł z Operatorem\\nporozumienie określające lokalizację i gęstość miejsc przeznaczonych do postoju\\npojazdow mikromobiiności dzielonej; \\f\\n\\nStrona 139 z 219\\n\\n- zarządca drogi był obowiązany, na wniosek Operatora świadczącego usługi\\nmikromobiiności dzielonej na danym obszarze, przystąpić do uzgodnień i zawrzeć takie\\nporozumienie w ustawowo określonym terminie, na podstawie wspolnych ustaleń stron;\\n- porozumienie gwarantowało odpowiednią gęstość sieci miejsc postojowych, ustaloną na\\npodstawie danych o rzeczywistym wykorzystaniu istniejących miejsc, ktore to dane\\nSpołka jest gotowa udostępnić zarządcą drog na etapie uzgodnień, nie mniejszą jednak niż\\niiczba i rozmieszczenie miejsc (spotow) funkcjonujących na danym obszarze w dniu wejścia\\nw życie ustawy, z możliwością jej dalszego zwiększania w miarę\\nzwiększających się potrzeb mieszkańcow;\\n- w braku porozumienia (w tym w braku uzgodnienia gęstości i lokalizacji miejsc\\npostojowych) na danym obszarze stosowane były zasady ogolne postoju pojazdow,\\nobowiązujące obecnie - analogicznie jak ma to miejsce dzisiaj w gminach, ktore nie\\nzdecydowały się na wspołpracę umowną z Operatorami;\\n- usunięcie pojazdu na podstawie art. 130a ust. 1 pkt 8 było dopuszczalne dopiero po\\nbezskutecznym upływie terminu wyznaczonego Operatorowi na relokacię pojazdu;\\nproponowany przez Społkę termin nie krotszy niż 3 godziny od zawiadomienia\\noperatora, dokonanego rownież środkami komunikacji elektronicznej, odpowiada\\nobserwowanemu w praktyce Społki czasowi reakcji lokalnych zespołow operacyjnych w\\nmiastach objętych obecnie umowną wspołpracą i może zostać potwierdzony danymi\\noperacyjnymi, ktore Społka jest gotowa przedstawić Ministerstwu. Powyższego terminu nie\\nstosuje się, jeżeli pojazd pozostawiono w sposob powodujący bezpośrednie\\nzagrożenie bezpieczeństwa ruchu drogowego.\\n4. Proponowane kierunkowe brzmienie przepisu. Tytułem propozycji legislacyjnej, Społka\\nproponuje nadanie projektowanemu art. 47 ust. 3a następującego brzmienia, opartego na\\nmechanizmie porozumienia zawieranego między zarządcą drogi a Operatorem (dalej jako\\n“Wariant I”)\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności\\ndzielonej, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez\\nzarządcę drogi, jeżeli miejsca takie zostały\\nwyznaczone na podstawie porozumienia zawartego pomiędzy zarządcą drogi a podmiotem\\nświadczącym usługę mikromobilności dzielonej, określającego co najmniej lokalizacje oraz\\ngęstość tych miejsc. Zarządca drogi zawiera porozumienie \\f\\n\\nStrona 140 z 219\\n\\nna wniosek podmiotu świadczącego usługę mikromobilności dzielonej, w terminie [3]\\nmiesięcy od dnia złożenia wniosku, zapewniając gęstość miejsc nie mniejszą niż istniejąca na\\ndanym obszarze w dniu wejścia w życie ustawy. W braku porozumienia\\ndo postoju pojazdów i urządzeń, o których mowa w zdaniu pierwszym, stosuje się przepisy\\nust. 1-3.”\\nSpołka dostrzega, że przyjęcie mechanizmu opartego na porozumieniu (Wariant I) wymaga\\nw praktyce wspołdziałania zarządcy drogi. Na wypadek, gdyby Ministerstwo uznało taki\\nmechanizm za zbyt daleko idący, Społka przedstawia dodatkowo propozycję alternatywną\\n(dalej jako „Wariant ił”), niewymagającą zawarcia porozumienia, a jedynie\\nsamodzielnego określenia przez zarządcę drogi obszaru objętego obowiązkiem oraz\\nwyznaczenia i podania do wiadomości operatorom lokalizacji i liczby miejsc postojowych na\\ntym obszarze:\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności\\ndzielonej,, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez\\nzarządcę drogi, pod warunkiem ze: T) zarządca\\ndrogi określił obszar, na którym obowiązek, o którym mowa w zdaniu pierwszym, ma\\nzastosowanie; 2) miejsca przeznaczone do postoju na tym obszarze zostały wyznaczone oraz\\npodane do wiadomości podmiotom świadczącym usługi mikromobilności dzielonej na tym\\nobszarze, ze wskazaniem co najmniej lokalizacji oraz liczby tych miejsc. W przypadku\\nniespełnienia warunków, o których mowa w zdaniu pierwszym, do postoju pojazdów i\\nurządzeń, o których mowa w zdaniu pierwszym, stosuje się przepisy ust. f-3.”\\nOdpowiedniej korekty wymagałby wowczas projektowany art 130a ust. 1 pkt 8 (odesłanie do\\nnaruszenia obowiązku wynikającego z porozumienia - w przypadku Wariantu I, albo z\\nwarunkow określenia obszaru i wyznaczenia miejsc - w przypadku Wariantu ii, a także\\nwarunek uprzedniego wezwania Operatora do reiokacji), a także projektowany art. 20 pkt 21\\nustawy o drogach publicznych (uzupełnienie o obowiązek uzgadniania lokalizacji i gęstości\\nmiejsc z Operatorami - w przypadku wariantu i, albo o obowiązek określenia obszaru oraz\\nwyznaczenia i podania do wiadomości Operatorom lokalizacji i liczby miejsc postojowych –\\nw przypadku Wariantu II). Społka deklaruje gotowość przedstawienia kompletnych\\npropozycji\\nredakcyjnych wszystkich powiązanych jednostek redakcyjnych. \\f\\n\\nStrona 141 z 219\\n\\n Art. 3 pkt 2\\nprojektu\\nustawy\\nTIER Mobility\\nPoland sp. z o.o.\\nII. Ocena ogolna Projektu\\nSpołka pozytywnie ocenia wprowadzenie do ustawy - Prawo o ruchu drogowym definicji\\nmikromobilności dzielonej (projektowany art. 2 pkt 47d) oraz przyznanie zarządcom drog\\nwyraźnej kompetencji do wyznaczania miejsc postoju pojazdow mikromobilności dzielonej\\n(projektowany art. 20 pkt 21 ustawy o drogach publicznych). Rozwiązania te odpowiadają\\nwypracowanej już praktyce wspołpracy Operatorow z miastami i zasługują na poparcie co do\\nkierunku.\\nZasadnicze zastrzeżenia Społki budzi natomiast konstrukcja obowiązku postoju wyłącznie w\\nmiejscach wyznaczonych (projektowany art. 47 ust. 3a) w powiązaniu z sankcją usunięcia\\npojazdu z drogi (projektowany art. 130a ust. 1 pkt 8 oraz ust. 6a lit. i). Uwagi w tym zakresie\\nprzedstawiamy w pkt III poniżej.\\nIII. Uwaga zasadnicza: projektowany art. 130a ust 1 pkt 8 w związku z art. 47 ust. 3a ustawy -\\nPrawo o ruchu u rugowym\\n1. Istota problemu - obowiązek bez gwarancji infrastruktury. Projektowany art. 47 ust. 3a\\nnakłada na użytkownika bezwzględny obowiązek zakończenia postoju „wyłącznie w\\nmiejscu wyznaczonym do tego celu przez zarządcę drogi”, a projektowany art. 130a ust. 1\\npkt 8 przewiduje usunięcie pojazdu pozostawionego poza takim miejscem. Projekt nie\\nnakłada jednak na zarządcę drogi żadnego obowiązku wyznaczenia takich miejsc, nie określa\\nich minimalnej gęstości ani trybu ich uzgadniania z Operatorami - wyznaczanie\\nmiejsc pozostaje wyłącznie uprawnieniem zarządcy drogi (projektowany art. 20 pkt 21\\nustawy o drogach publicznych).\\nPrzepis nie precyzuje jednak, jak należy interpretować sytuację, w ktorej na danym obszarze\\nzarządca drogi nie wyznaczył jeszcze żadnych miejsc postojowych albo wyznaczył je w liczbie\\nlub lokalizacjach nieodpowiadających rzeczywistym potrzebom użytkownikow. Bez takiego\\ndoprecyzowania nie można wykluczyć interpretacji, zgodnie z ktorą każdorazowe\\nzakończenie przejazdu na takim obszarze stanowiłoby naruszenie art. 47 ust. 3a i podstawę\\nusunięcia pojazdu na koszt Operatora (200 zł za usunięcie oraz 50 zł za każdą dobę\\nprzechowywania). W takim ujęciu o możliwości faktycznego prowadzenia działalności\\ngospodarczej na danym obszarze decydowałaby nie ustawa, lecz tempo działania zarządcy\\ndrogi w zakresie wyznaczania miejsc postojowych, co w skrajnym przypadku mogłoby\\nprowadzić do wyłączenia usług mikrornobiiności dzielonej w części kraju.\\nNiezależnie od tego, ktorą Interpretację ostatecznie przyjęto by w praktyce stosowania\\nprzepisu, sama ta niejednoznaczność rodzi po stronie Operatorow istotną niepewność co do \\f\\n\\nStrona 142 z 219\\n\\nwarunkow prowadzenia działalności w poszczegolnych gminach, a w konsekwencji utrudnia\\npodejmowanie decyzji inwestycyjnych i operacyjnych. Z tego względu Społka postuluje\\njednoznaczne doprecyzowanie przepisu w kierunku wskazanym w pkt. 3 poniżej, co pozwoli\\nuniknąć niepewności, utrudniające prowadzenie działalności gospodarczej w tym zakresie.\\n2. Nieproporcjonalność sankcji i pominięcie możliwości technicznych Operatorów.\\nUsunięcie pojazdu przez podmiot wyznaczony przez starostę jest środkiem najdalej idącym i\\nnajbardziej kosztownym, podczas gdy Operatorzy - w odrożnieniu od właścicieli pojazdow\\nindywidualnych, dysponują narzędziami pozwalającymi usunąć nieprawidłowość\\nniezwłocznie i bez angażowania środkow publicznych: dzięki wbudowanemu w każdym\\npojeździe systemowi GPS, Operatorzy mają podgląd co do lokalizacji jej floty, a lokalne\\nzespoły serwisowe, ktorych zadaniem jest m.in. relokacja pojazdow, działają w trybie\\nciągłym. Projekt nie przewiduje jednak żadnego trybu uprzedniego wezwania Operatora do\\nrelokacji pojazdu. W rezultacie środek publicznoprawny staje się środkiem pierwszego\\nwyboru, generującym koszty po stronie Operatorow i obciążenia organizacyjne po stronie\\npowiatow, mimo że ten sam skutek (usunięcie pojazdu z miejsca niedozwolonego)\\nOperatorzy mogą osiągnąć szybciej i bez kosztow publicznych.\\n3. Propozycja Spółki - ustawowy mechanizm porozumień z zarządcami dróg oraz gwarancja\\nodpowiedniej gęstości miejsc postojowych. Społka proponuje oparcie projektowanego\\nmechanizmu na sprawdzonym modelu funkcjonującym obecnie m.in. w Warszawie,\\nPoznaniu, Krakowie i Gdańsku, tj. na umowach (porozumieniach) zawieranych pomiędzy\\nzarządcą drogi (miastem) a Operatorami. Proponujemy, aby:\\n- obowiązek zakończenia postoju wyłącznie w miejscu wyznaczonym (art. 47 ust. 3a)\\noraz powiązana z nim sankcja usunięcia pojazdu (art. 130a ust. 1 pkt 8) znajdowały\\nzastosowanie wyłącznie na obszarze, dla którego zarządca drogi zawarł z Operatorem\\nporozumienie określające lokalizację i gęstość miejsc przeznaczonych do postoju pojazdow\\nmikrornobiiności dzielonej;\\n- zarządca drogi był obowiązany, na wniosek Operatora świadczącego usługi\\nmikrornobiiności dzielonej na danym obszarze, przystąpić do uzgodnień i zawrzeć takie\\nporozumienie w ustawowo określonym terminie, na podstawie wspolnych ustaleń stron;\\n- porozumienie gwarantowało odpowiednią gęstość sieci miejsc postojowych, ustaloną\\nna podstawie danych o rzeczywistym wykorzystaniu istniejących miejsc. Ktore to dane\\nSpołka jest gotowa udostępnić zarządcą drog na etapie uzgodnień, nie mniejszą jednak niż\\nliczba i rozmieszczenie miejsc (spotow) funkcjonujących na danym obszarze w dniu wejścia \\f\\n\\nStrona 143 z 219\\n\\nw życie ustawy, z możliwością jej dalszego zwiększania w miarę zwiększających się potrzeb\\nmieszkańcow;\\n- w braku porozumienia (w tym w braku uzgodnienia gęstości i lokalizacji miejsc\\npostojowych) na danym obszarze stosowane były zasady ogolne postoju pojazdow,\\nobowiązujące obecnie - analogicznie jak ma to miejsce dzisiaj w gminach, ktore nie\\nzdecydowały się na wspołpracę umowną z Operatorami;\\n- usunięcie pojazdu na podstawie art. l30a ust. 1 pkt 8 było dopuszczalne dopiero po\\nbezskutecznym upływie terminu wyznaczonego Operatorowi na relokację\\npojazdu;proponowany przez Społkę termin nie krotszy niż 3 godziny od zawiadomienia\\noperatora, dokonanego rownież środkami komunikacji elektronicznej, odpowiada\\nobserwowanemu w praktyce Społki czasowi reakcji lokalnych zespołow operacyjnych\\nw miastach objętych obecnie umowną wspołpracą i może zostać potwierdzony danymi\\noperacyjnymi, ktore Społka jest gotowa przedstawić Ministerstwu. Powyższego terminu\\nnie stosuje się. jeżeli pojazd pozostawiono w sposob powodujący bezpośrednie zagrożenie\\nbezpieczeństwa ruchu drogowego.\\n4. Proponowane kierunkowe brzmienie przepisu. Tytułem propozycji legislacyjnej, Społka\\nproponuje nadanie projektowanemu art. 47 ust. 3a następującego brzmienia, opartego na\\nmechanizmie porozumienia zawieranego między zarządcą drogi a Operatorem (dalej jako\\n“Wariant I”)\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności\\ndzielonej, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez\\nzarządcę drogi, jeżeli miejsca takie zostały\\nwyznaczone na podstawie porozumienia zawartego pomiędzy zarządcą drogi a podmiotem\\nświadczącym usługę mikromobilności dzielonej, określającego co\\nnajmniej lokalizacje oraz gęstość tych miejsc. Zarządca drogi zawiera porozumienie na\\nwniosek podmiotu świadczącego usługę mikromobilności dzielonej, w terminie [3] miesięcy\\nod dnia złożenia wniosku, zapewniając gęstość miejsc nie mniejszą niż istniejąca na danym\\nobszarze w dniu wejścia wżycie ustawy W braku porozumienia do postoju pojazdów i\\nurządzeń, o których mowa w zdaniu pierwszym, stosuje się\\nprzepisy ust. 1-3.”\\nSpołka dostrzega, że przyjęcie mechanizmu opartego na porozumieniu (Wariant I) wymaga\\nw praktyce wspołdziałania zarządcy drogi. Na wypadek, gdyby Ministerstwo uznało taki \\f\\n\\nStrona 144 z 219\\n\\nmechanizm za zbyt daleko idący, Społka przedstawia dodatkowo propozycję alternatywną\\n(dalej jako „Wariant !!”), niewymagającą zawarcia porozumienia, a jedynie\\nsamodzielnego określenia przez zarządcę drogi obszaru objętego obowiązkiem oraz\\nwyznaczenia i podania do wiadomości operatorom lokalizacji i liczby miejsc postojowych\\nna tym obszarze:\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności\\ndzielonej, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez\\nzarządcę drogi, pod warunkiem ze: 1) zarządca\\ndrogi określił obszar na którym obowiązek, o którym mowa w zdaniu pierwszym, ma\\nzastosowanie; 2) miejsca przeznaczone do postoju na tym obszarze zostały wyznaczone oraz\\npodane do wiadomości podmiotom świadczącym usługi mikromobilności dzielonej na tym\\nobszarze, ze wskazaniem co najmniej lokalizacji\\noraz liczby tych miejsc. W przypadku niespełnienia warunków, o których mowa w zdaniu\\npierwszym, do postoju pojazdów i urządzeń, ó których mowa w zdaniu pierwszym, stosuje się\\nprzepisy ust. 1-3. ”\\nOdpowiedniej korekty wymagałby wowczas projektowany art. 130a ust. 1 pkt 8 (odesłanie\\ndo naruszenia obowiązku wynikającego z porozumienia - w przypadku Wariantu I, albo z\\nwarunkow określenia obszaru i wyznaczenia miejsc - w przypadku wariantu li, a także\\nwarunek uprzedniego wezwania Operatora do reiokacji), a także projektowany art. 20 pkt 21\\nustawy o drogach publicznych (uzupełnienie o obowiązek uzgadniania lokalizacji i gęstości\\nmiejsc z Operatorami - w przypadku Wariantu I, albo o obowiązek określenia obszaru oraz\\nwyznaczenia i podania do wiadomości Operatorom lokalizacji i liczby miejsc postojowych –\\nw przypadku Wariantu II).\\n\\n Art. 3 i art. 10\\nprojektu\\nustawy\\nFundacja\\nBlind&Proud\\nE-hulajnogi w polskich miastach\\nHulajnogi elektryczne na wynajem są już dostępne w około 200 miastach w całej Polsce. W\\nkażdym mieście mogą działać na innych zasadach, bez umów z samorządem. Choć to władze\\nsamorządów są rozliczane za utrzymanie porządku i bezpieczeństwo na drogach i\\nchodnikach, nie mają istotnego wpływu na działalność operatorów hulajnóg elektrycznych i\\nnegatywne skutki dla lokalnych społeczności. \\f\\n\\nStrona 145 z 219\\n\\nPorozrzucane hulajnogi to powszechny problem\\nUżytkownicy hulajnóg elektrycznych porzucają je w niewłaściwych miejscach, bo mogą to\\nrobić, bezkarnie. Operatorzy nie mają skutecznych narzędzi do weryfikacji prawidłowego\\nparkowania. Trudno również oczekiwać, że samorząd będzie delegował armię policjantów i\\nstrażników miejskich do porządkowania chodników z porzuconych hulajnóg elektrycznych.\\nPorzucone e-hulajnogi stanowią poważne zagrożenie dla wszystkich użytkowników dróg i\\nchodników, w tym rowerzystów i pieszych, w szczególności seniorów, małych dzieci i osób\\nz niepełnosprawnościami. Zderzenia rowerzystów z leżącymi hulajnogami elektrycznymi,\\nupadki seniorów, osób niewidomych i małych dzieci to wysokie ryzyko urazów. Ponadto\\nurządzenia blokujące chodnik wymuszają poruszanie się pieszych po ulicy, co stwarza\\nzagrożenie potrąceniem przez samochód. Obywatele oczekują, że odpowiednie organy\\nzapanują nad tym bałaganem. Część z miast wprowadza stopniowo ograniczenia\\nw parkowaniu hulajnóg elektrycznych, w uzgodnieniu z operatorami. Ograniczenia dotyczą\\njednak z reguły wyłącznie centrów miast, przez co hulajnogi elektryczne dalej są porzucane,\\nchoć nie w samym centrum. Inne miasta zwiększają liczbę miejsc do parkowania e-hulajnóg.\\nJednak jak wskazuje raport mikromobilności w Warszawie, samo istnienie miejsc do\\nparkowania to zbyt mało. W okresie objętym badaniem tylko 6% podróży zakończyło się\\nparkowaniem w wyznaczonym miejscu.\\nPrzyczyna problemu\\nŹródło problemu stanowią niejasne przepisy art. 47 ust. 3 ustawy Prawo o ruchu drogowym,\\nprzyjęte w 2021 roku. Przepisy dopuszczają by hulajnogę elektryczną zostawić w miejscu\\nprzeznaczonym a jak nie ma takiego miejsca, to na chodniku. Tak ogólny zapis spowodował\\nobecny chaos w parkowaniu hulajnóg elektrycznych na wynajem, na którym korzystają\\noperatorzy e-hulajnóg z uwagi na możliwość oferowania swoich pojazdów na wynajem na\\nniemal każdym rogu chodnika.\\nProjektowana zmiana prawna (UD 402)\\nPrzygotowany przez Ministerstwo Infrastruktury projekt ustawy (UD 402), wprowadza\\nszereg korzystnych zmian porządkujących parkowanie e-hulajnóg na wynajem:\\n definicję mikromobilności dzielonej;\\n kompetencję zarządcy dróg, czyli głównie prezydentów miast, burmistrzów i wójtów\\ndo wyznaczania miejsca do parkowania wynajmowanych e-hulajnóg, rowerów i\\nurządzeń transportu osobistego; \\f\\n\\nStrona 146 z 219\\n\\n wymóg parkowania hulajnogi elektrycznej, roweru lub urządzenia transportu\\nosobistego na wynajem tylko w miejscach wyznaczonych;\\n możliwość usuwania nieprawidłowo zaparkowanych pojazdów na wynajem na koszt\\nwłaściciela ( 200 zł za usunięcie i 50 zł za każdy dzień przechowywania),\\n projektowane przepisy mają wejść w życie od 1 stycznia 2028 roku.\\nKorzyści z uregulowania parkowania e-hulajnóg na wynajem\\nProponowana zmiana pozwoli uporządkować parkowanie hulajnóg elektrycznych\\nudostępnianych przez operatorów, bez negatywnych skutków dla właścicieli prywatnych\\npojazdów. Parkowanie e-hulajnóg na wynajem wyłącznie w miejscach wyznaczonych\\npozwoli odzyskać lokalnym władzom możliwość zarządzania bezpieczeństwem na drogach i\\nchodnikach. Samorząd zdecyduje o miejscach i liczbie miejsc wyznaczonych na własnym\\nterenie. To pozwoli na wyrównany dialog między operatorami, chcącymi oferować swoje\\nusługi mieszkańcom a samorządem, który odpowiada za bezpieczeństwo i porządek w\\nprzestrzeni publicznej.\\nProjektowane przepisy spowodują, że hulajnogi elektryczne na wynajem nie będą mogły być\\nporzucane poza miejscami wyznaczonymi. Ustawa zapewnia również możliwość usuwania\\nnieprawidłowo zaparkowanych e-hulajnóg udostępnianych przez operatorów.\\nRaz jeszcze pragniemy wyrazić nasze poparcie dla wprowadzenia obowiązku parkowania\\nhulajnóg elektrycznych na wynajem wyłącznie w miejscach wyznaczonych. To konieczny\\nkrok, by wzmocnić bezpieczeństwa wszystkich uczestników ruchu drogowego, w tym\\npieszych ze szczególnymi potrzebami.\\nKonieczność pilnego procedowania\\nArt. 10 pkt 2 projektu ustawy UD402 przewiduje, że obowiązek parkowania hulajnóg\\nelektrycznych na wynajem wejdzie w życie 1 stycznia 2028 roku. Postulujemy maksymalne\\nmożliwe skrócenie tego okresu i, o ile będzie to możliwe, wejście w życie zmian od 1 lipca\\n2027 roku. Oznacza to konieczność pilnego procedowania projektu. Mamy jednak nadzieję,\\nże postulat ten zostanie przez Pana Ministra uwzględniony z uwagi na fakt, że proponowane\\nprzepisy regulują kwestie istotne dla bezpieczeństwa uczestników ruchu drogowego.\\n\\n Art. 3 projektu\\nustawy\\nZarząd Dróg\\nMiejskich\\nWarszawa\\n1. Regulacja postoju\\nW zakresie przepisów zawartych w ustawach oraz propozycji zmian zawartych w projekcie nr\\nUD402 proponujemy następujące rozwiązania: \\f\\n\\nStrona 147 z 219\\n\\n Definicja mikromobilności dzielonej:\\nWprowadzenie w ustawie z dnia 20 czerwca 1997 r., Prawo o ruchu drogowym – zgodnie z\\npropozycją resortu - jako art. 2 pkt. 47d), definicji mikromobilności dzielonej. Proponujemy\\naby miała ona następującą treść:\\n„47d) mikromobilność dzielona - usługa polegająca na udostępnianiu pojazdów i innych\\nurządzeń przeznaczonych do indywidualnego przemieszczania się, w szczególności rowerów,\\nmotorowerów, hulajnóg elektrycznych oraz urządzeń transportu osobistego, a także\\npojazdów kategorii L1e i jej podkategorii, w rozumieniu rozporządzenia 168/2013 w sprawie\\nhomologacji i nadzoru rynku pojazdów, na krótki okres, w sposób odpłatny lub nieodpłatny,\\numożliwiający rozpoczęcie i zakończenie podróży pojazdem w miejscach zarówno\\nwskazanych przez udostępniającego, jak też wybranych przez użytkownika, w celu\\nwykorzystania tych pojazdów przez wielu użytkowników;”\\n\\n Dookreślenie miejsca przeznaczonego dla postoju hulajnogi (i roweru)\\nW naszej opinii wskazane byłoby dookreślenie dopuszczenia opisanego a art. 47 ust. 3 -  a\\nwięc dopuszczenia dot. rowerów, hulajnóg elektrycznych itp. do postoju na chodniku –\\npoprzez wskazanie podstawowych rodzajów miejsc określonych jako „przeznaczone”. Byłyby\\nto miejsca wyznaczone znakami lub też tzw. stojaki rowerowe, czyli elementy małej\\narchitektury służące do parkowania rowerów. BARDZO WAŻNE – te zapis nie powinien\\nnakładać obowiązku oznakowania znakami pionowymi ani sporządzania projektów\\norganizacji ruchu dla stojaków rowerowych.\\nBrzmienie art. 47 ust. 3 mogłoby być wtedy następujące:\\n„3. Dopuszcza się postój roweru, hulajnogi elektrycznej lub urządzenia transportu\\nosobistego przy elemencie małej architektury, przeznaczonym do tego celu, lub w miejscu\\nwyznaczonym, a w razie braku takiego miejsca – jak najbliżej zewnętrznej krawędzi drogi dla\\npieszych najbardziej oddalonej od jezdni oraz równolegle do tej krawędzi, przy zachowaniu\\nwarunków określonych w ust. 1 pkt. 2.„\\n\\n Zakaz postoju dla pojazdów mikromobilności dzielonej poza miejscami\\nprzeznaczonymi\\nW ustawie prawo o ruchu drogowym proponujemy dodanie w art. 49 ust. 2, nowego pkt 6),\\nustanawiającego zakaz postoju dla pojazdów mikromobilności dzielonej poza miejscami \\f\\n\\nStrona 148 z 219\\n\\nprzeznaczonymi. W przepisie tym mowa zarówno o miejscach wyznaczonych zgodnie z\\ntrybem opisanym w wyżej proponowanym art. 12c ustawy o drogach publicznych, jak też o\\ntzw. stojakach rowerowych, określanych jako „inne elementy małej architektury,\\nprzeznaczone do postoju rowerów”.\\nBrzmienie proponowanego w art. 49 ust. 2. nowego punktu:\\n[Zabrania się postoju:] „6) pojazdu udostępnionego w ramach mikromobilności dzielonej w\\nmiejscach nie będących:\\n- miejscami wyznaczonymi przez organ właściwy do zarządzania ruchem, o których mowa w\\nart. 12c ustawy z dnia 21 marca 1985 r. o drogach publicznych,\\n- miejscami umieszczenia elementów małej architektury, przeznaczonych do postoju\\nrowerów.”\\n\\n Możliwość usunięcia pojazdu pozostawionego niezgodnie z przepisami\\nZgodnie z założeniami resortu potrzebne będzie wprowadzenie zmian w art. 130a ustawy\\nprawo o ruchu drogowym, polegających na uzupełnieniu ust. 1 poprzez wskazanie, że w\\nrazie naruszenia zakazu postoju, pojazd mikromobilności dzielonej podlega usunięciu na\\nkoszt właściciela, oraz uzupełnieniu ust. 4 poprzez przyznanie straży gminnej (miejskiej)\\nkompetencji do wydawania dyspozycji usunięcia takiego pojazdu. Jeśli do postoju pojazdu\\nmikromobilności dzielonej niezbędna byłaby zgoda zarządcy drogi, jej brak również powinien\\nbyć podstawą do usunięcia takiego pojazdu.\\nProponowane zmiany (zgodnie z porządkiem wg projektu UD402):\\nW art. 130a:\\na) w ust. 1 w pkt 7) kropkę zastępuje się średnikiem i dodaje się pkt 8) o brzmieniu:\\n„8) pozostawienia, z naruszeniem art. 49 ust. 2 pkt. 6), pojazdu udostępnionego w ramach\\nmikromobilności dzielonej poza przeznaczonym miejscem.”;\\nb) w ust. 6a lit. h kropkę zastępuje się średnikiem i dodaje się lit. i o brzmieniu:\\n„i) pojazd lub urządzenie udostępnione w ramach mikromobilności dzielonej, za usunięcie -\\n200 zł, za każdą rozpoczętą dobę przechowywania - 50 zł.”\\nc) w ust. 4. w pkt. 2) słowa „ust. 1 pkt 1, 4 i 5;” zastępuje się słowami „ust. 1 pkt. 1, 4, 5 i 8;”\\n\\n Art. 3 projektu Lime\\nTechnology sp. z\\no.o.\\n● Art. 3 pkt 1 projektu ustawy – art. 2 pkt 47d ustawy – Prawo o ruchu drogowym:\\n \\f\\n\\nStrona 149 z 219\\n\\nProjekt wprowadza do ustawy – Prawo o ruchu drogowym definicję „mikromobilności\\ndzielonej”. Lime proponuje zastąpienie tego określenia pojęciem „mikromobilność\\nwspółdzielona”. Termin „mikromobilność współdzielona” jest powszechnie stosowany w\\nterminologii branżowej, materiałach prasowych i publikacjach dotyczących sektora. Trafniej\\noddaje również charakter usługi polegającej na udostępnianiu tych samych pojazdów lub\\nurządzeń wielu użytkownikom.\\n\\nProjektowany art. 2 pkt 47d ustawy – Prawo o ruchu drogowym mógłby otrzymać\\nnastępujące brzmienie:\\n„47d) mikromobilność współdzielona – usługę polegającą na udostępnianiu użytkownikom,\\nodpłatnie lub nieodpłatnie, pojazdów lub urządzeń przeznaczonych do indywidualnego\\nprzemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg\\nelektrycznych lub urządzeń transportu osobistego, z wykorzystaniem aplikacji mobilnej lub\\ninnego systemu teleinformatycznego\\numożliwiającego korzystanie z tych pojazdów lub urządzeń przez wielu użytkowników;”.\\n\\nKonsekwentnie określenie „mikromobilność dzielona” powinno zostać zastąpione\\nokreśleniem „mikromobilność współdzielona” również w art. 2 projektu ustawy oraz w\\npozostałych przepisach dodawanych lub zmienianych w art. 3 projektu.\\n Art. 3 pkt 1\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 6. Definicja operatora mikromobilności dzielonej\\nAktualna propozycja zawarta w UD402\\nArt. 3 pkt 1 projektu przewiduje dodanie w art. 2 Prawa o ruchu drogowym pkt 47d:\\n„47d) mikromobilność dzielona – usługę polegającą na udostępnianiu użytkownikom, w\\nsposób odpłatny lub nieodpłatny, pojazdów lub urządzeń przeznaczonych do\\nindywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów,\\nhulajnóg elektrycznych lub urządzeń transportu osobistego, z wykorzystaniem aplikacji\\nmobilnej lub innego systemu teleinformatycznego umożliwiającego korzystanie z tych\\npojazdów lub urządzeń przez wielu użytkowników;”.\\nProjekt definiuje usługę, ale nie definiuje operatora odpowiedzialnego za jej organizację.\\nPropozycja PZN \\f\\n\\nStrona 150 z 219\\n\\nW art. 3 pkt 1 projektu, po projektowanym art. 2 pkt 47d, proponuje się dodać pkt 47e w\\nbrzmieniu:\\n„47e) operator mikromobilności dzielonej – przedsiębiorcę lub inny podmiot organizujący\\nalbo prowadzący usługę mikromobilności dzielonej;”.\\nUzasadnienie\\nDefinicja jest konieczna, aby ustawa mogła nakładać jednoznaczne obowiązki na podmiot\\nzarządzający aplikacją i flotą, a nie jedynie na osobę korzystającą z urządzenia.\\n\\n Art. 3 pkt 2\\nprojektu\\nustawy\\nPolski Związek\\nNiewidomych 2. Prawidłowy sposób ustawienia urządzenia w miejscu wyznaczonym\\nAktualna propozycja zawarta w UD402\\nArt. 3 pkt 2 projektu przewiduje dodanie w art. 47 Prawa o ruchu drogowym ust. 3a w\\nbrzmieniu:\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, w szczególności rower, hulajnogę elektryczną\\nlub urządzenie transportu osobistego udostępnione w ramach mikromobilności dzielonej\\njest obowiązana zakończyć postój wyłącznie w miejscu wyznaczonym do tego celu przez\\nzarządcę drogi.”.\\nPrzepis określa miejsce zakończenia postoju, ale nie reguluje sposobu ustawienia\\nurządzenia.\\nPropozycja PZN\\nW art. 3 pkt 2 projektu UD402 projektowanemu art. 47 ust. 3a ustawy – Prawo o ruchu\\ndrogowym proponuje się nadać następujące brzmienie:\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, w szczególności rower, hulajnogę elektryczną\\nlub urządzenie transportu osobistego udostępnione w ramach mikromobilności dzielonej,\\njest obowiązana zakończyć postój wyłącznie w miejscu wyznaczonym do tego celu przez \\f\\n\\nStrona 151 z 219\\n\\nzarządcę drogi oraz ustawić pojazd lub urządzenie stabilnie, w całości w granicach tego\\nmiejsca i w sposób zapewniający ciągłość trasy wolnej od przeszkód”.\\nUzasadnienie\\nW aktualnym brzmieniu za prawidłowo zaparkowane może zostać uznane urządzenie,\\nktórego tylko część znajduje się w strefie. Hulajnoga może także leżeć w granicach miejsca,\\nale wystawać kierownicą lub kołem na ciąg pieszy.\\nObowiązek powinien obejmować zarówno lokalizację postoju, jak i sposób ustawienia\\nurządzenia.\\nOdwołanie do wcześniejszego opracowania\\nW opracowaniu z 2025 r. wskazano, że pojazdy nie mogą ograniczać swobodnego i\\nbezpiecznego poruszania się pieszych ani pozostawać w sposób powodujący powstanie\\nprzeszkody na chodniku.\\n\\n Art. 3 pkt 3 lit.\\na projektu\\nustawy\\nPolski Związek\\nNiewidomych 3. Dostosowanie podstawy usunięcia pojazdu do zmienionego art. 47 ust. 3a\\nAktualna propozycja zawarta w UD402\\nArt. 3 pkt 3 lit. a projektu przewiduje dodanie w art. 130a ust. 1 pkt 8:\\n„8) pozostawienia, z naruszeniem art. 47 ust. 3a, pojazdu lub urządzenia przeznaczonego do\\nindywidualnego przemieszczania się na krótkich dystansach, w szczególności roweru,\\nhulajnogi elektrycznej lub urządzenia transportu osobistego udostępnionego w ramach\\nmikromobilności dzielonej, poza miejscem wyznaczonym do tego celu przez zarządcę\\ndrogi.”.\\nPodstawa usunięcia obejmuje wyłącznie pozostawienie urządzenia poza miejscem\\nwyznaczonym.\\nPropozycja PZN\\nW art. 3 pkt 3 lit. a projektu projektowanemu art. 130a ust. 1 pkt 8 proponuje się nadać\\nnastępujące brzmienie: \\f\\n\\nStrona 152 z 219\\n\\n„8) pozostawienia, z naruszeniem art. 47 ust. 3a, pojazdu lub urządzenia przeznaczonego do\\nindywidualnego przemieszczania się na krótkich dystansach, w szczególności roweru,\\nhulajnogi elektrycznej lub urządzenia transportu osobistego udostępnionego w ramach\\nmikromobilności dzielonej, poza miejscem wyznaczonym do tego celu przez zarządcę drogi  i\\nzapewniającego ciągłośc trasy wolnej od przeszkód wraz z opaską szerokości 0,3m.”.\\nUzasadnienie\\nJeżeli art. 47 ust. 3a zostanie uzupełniony o sposób ustawienia urządzenia, analogicznie\\nnależy rozszerzyć podstawę jego usunięcia. W przeciwnym razie możliwe będzie usunięcie\\nurządzenia znajdującego się poza strefą, ale nie urządzenia znajdującego się częściowo w\\nstrefie i jednocześnie blokującego chodnik. Należy zwrócić uwagę na linie prowadzące (tzw.\\nnaturalne linie kierunkowe” i sposób poruszania się osób niewidomych.\\n\\n Art. 3 projektu\\nustawy\\nPolski Związek\\nNiewidomych 7. Techniczne ograniczenie możliwości zakończenia korzystania poza miejscem\\nwyznaczonym\\nAktualna propozycja zawarta w UD402\\nProjekt nakłada obowiązek parkowania w miejscu wyznaczonym na użytkownika.\\nNie przewiduje natomiast ustawowego obowiązku operatora dotyczącego:\\n stosowania geofencingu lub innego mechanizmu lokalizacyjnego,\\n weryfikowania sposobu ustawienia urządzenia,\\n wskazywania użytkownikowi najbliższych miejsc postojowych,\\n dokumentowania przypadków nieprawidłowego postoju.\\nPropozycja PZN\\nW art. 3 projektu proponuje się dodać zmianę polegającą na dodaniu w ustawie – Prawo o\\nruchu drogowym art. 47a w brzmieniu:\\n„Art. 47a. \\f\\n\\nStrona 153 z 219\\n\\n1. Operator mikromobilności dzielonej zapewnia rozwiązania techniczne służące\\nskutecznemu ograniczeniu możliwości zakończenia korzystania z pojazdu lub\\nurządzenia poza miejscem wyznaczonym przez zarządcę drogi.\\n2. Operator zapewnia weryfikację prawidłowego ustawienia pojazdu lub urządzenia\\nprzy zakończeniu korzystania z niego.\\n3. Operator zapewnia użytkownikowi informację o lokalizacji najbliższych miejsc\\nwyznaczonych do postoju.\\n4. Minister właściwy do spraw transportu określi, w drodze rozporządzenia,\\nszczegółowy sposób realizacji obowiązków, o których mowa w ust. 1–3,\\nuwzględniając dokładność systemów lokalizacyjnych, konieczność skutecznej\\nweryfikacji postoju oraz ochronę danych osobowych.”.\\nUzasadnienie\\nKary lub dodatkowe opłaty nakładane na podstawie prywatnych regulaminów operatorów\\nnie zapewniają skutecznego egzekwowania obowiązków.\\nNie istnieje publiczna kontrola pozwalająca ustalić:\\n czy sankcje są rzeczywiście nakładane,\\n jak często operator odstępuje od ich stosowania,\\n jak wiele przypadków nieprawidłowego postoju pozostaje bez reakcji,\\n czy system technicznie zapobiega zakończeniu najmu poza strefą.\\nProponowany przepis nie narzuca jednej technologii, lecz wymaga osiągnięcia określonego\\nrezultatu.\\n\\n Art. 3 projektu\\nustawy\\nPolski Związek\\nNiewidomych 8. Dostępny system zgłaszania urządzeń stanowiących przeszkodę\\nAktualna propozycja zawarta w UD402\\nProjekt przewiduje możliwość usunięcia urządzenia pozostawionego poza miejscem\\nwyznaczonym oraz opłatę 200 zł za usunięcie i 50 zł za każdą dobę przechowywania. \\f\\n\\nStrona 154 z 219\\n\\nNie przewiduje jednak obowiązku operatora dotyczącego przyjmowania zgłoszeń,\\ndostępności kanału zgłoszeniowego ani czasu reakcji.\\nPropozycja PZN\\nPo proponowanym art. 47a proponuje się dodać art. 47b w brzmieniu:\\n„Art. 47b.\\n1. Operator mikromobilności dzielonej zapewnia bezpłatny i dostępny dla osób ze\\nszczególnymi potrzebami system zgłaszania pojazdów lub urządzeń pozostawionych\\nnieprawidłowo albo w sposób powodujący zagrożenie lub utrudnienie dla ruchu.\\n2. Dokonanie zgłoszenia nie może być uzależnione od posiadania konta użytkownika\\nani zainstalowania aplikacji operatora.\\n3. Operator zapewnia co najmniej możliwość dokonania zgłoszenia telefonicznego oraz\\nza pomocą dostępnego cyfrowo formularza.\\n4. Operator niezwłocznie usuwa albo prawidłowo ustawia pojazd lub urządzenie\\npowodujące bezpośrednie zagrożenie lub istotne utrudnienie dla ruchu pieszych.\\n5. Minister właściwy do spraw transportu określi, w drodze rozporządzenia,\\nmaksymalny termin reakcji operatora w pozostałych przypadkach oraz minimalne\\nwymagania dostępności systemu zgłoszeń.”.\\nUzasadnienie\\nOsoba niewidoma może nie być w stanie odczytać numeru urządzenia ani kodu QR. Nie\\npowinna być również zmuszana do instalowania aplikacji każdego operatora tylko po to, aby\\nzgłosić przeszkodę.\\nAdministracyjne usunięcie pojazdu nie zastępuje szybkiej reakcji operatora, który zna\\nlokalizację urządzenia i dysponuje możliwością jego relokacji.\\n Art. 3 projektu\\nustawy\\nPolski Związek\\nNiewidomych 10. Sankcje wobec operatora\\nAktualna propozycja zawarta w UD402 \\f\\n\\nStrona 155 z 219\\n\\nProjekt określa opłatę za administracyjne usunięcie pojedynczego urządzenia, ale nie\\nprzewiduje sankcji za systemowe niewykonywanie obowiązków przez operatora.\\nNie obejmuje więc sytuacji, w której operator:\\n nie zapewnia skutecznej weryfikacji parkowania,\\n nie reaguje na zgłoszenia,\\n nie usuwa urządzeń,\\n nie przekazuje wymaganych danych,\\n prowadzi usługę mimo powtarzających się naruszeń.\\nPropozycja PZN\\nPZN proponuje wprowadzenie administracyjnej kary pieniężnej za niewykonywanie\\nobowiązków określonych w proponowanych art. 47a i 47b oraz obowiązków informacyjnych\\nwobec zarządcy drogi.\\nPrzepis powinien stanowić:\\n„Operator mikromobilności dzielonej, który nie wykonuje obowiązków dotyczących\\nweryfikacji postoju, reagowania na zgłoszenia, usuwania pojazdów lub przekazywania\\nwymaganych danych, podlega administracyjnej karze pieniężnej.”\\nPrzy ustalaniu wysokości kary organ powinien uwzględniać:\\n1. liczbę urządzeń objętych naruszeniem;\\n2. czas trwania i powtarzalność naruszenia;\\n3. stopień zagrożenia dla ruchu pieszych;\\n4. wielkość floty operatora;\\n5. działania podjęte w celu usunięcia naruszenia.\\nUzasadnienie\\nOpłata 200 zł za usunięcie pojedynczego urządzenia może być traktowana przez dużego\\noperatora jako zwykły koszt prowadzenia działalności. Nie oddziałuje ona na systemowe \\f\\n\\nStrona 156 z 219\\n\\nnieprawidłowości, takie jak nieskuteczny geofencing, brak obsługi zgłoszeń albo\\npowtarzające się niewykonywanie obowiązku relokacji.\\nPZN nie proponuje na tym etapie konkretnych widełek kwotowych. Powinny one zostać\\nustalone po analizie proporcjonalności i struktury rynku.\\nArt. 1 pkt 22\\n Art. 3 projektu\\nustawy\\nZrzeszenie\\nStudentów\\nNiepełnospraw-\\nnych\\nUniwersytetu\\nKazimierza\\nWielkiego w\\nBydgoszczy\\npragnę wyrazić poparcie dla projektowanych przez Ministerstwo Infrastruktury, nowych\\nprzepisów (projekt UD 402), skutkujących wymogiem parkowania hulajnóg elektrycznych na\\nwynajem wyłącznie w miejscach wyznaczonych. To konieczny krok, by wzmocnić\\nbezpieczeństwo wszystkich uczestników ruchu drogowego, w tym dzieci, seniorów, osób z\\nniepełnosprawnościami i rowerzystów.\\nJako Zrzeszenie Studentów Niepełnosprawnych Uniwersytetu Kazimierza Wielkiego w\\nBydgoszczy pragniemy poinformować, że w pełni podzielamy stanowisko i obawy dotyczące\\nproblemów z dostępnością oraz bezpieczeństwem w przestrzeniach miejskich.\\n\\nChcielibyśmy przekazać, że jako organizacja reprezentująca interesy osób ze szczególnymi\\npotrzebami podjęliśmy już w tej sprawie formalne kroki. W dniu 21 lipca 2026 r.\\nskierowaliśmy na ręce Pana Rafała Bruskiego, Prezydenta Miasta Bydgoszczy, dwa oficjalne\\npisma:\\na) Wniosek o lepsze zabezpieczenie terenów remontowanych oraz usprawnienie\\ninformowania o zmianach w organizacji ruchu i komunikacji miejskiej. Zwracamy w nim\\nuwagę na drastyczne utrudnienia w samodzielnym i bezpiecznym poruszaniu się, z jakimi\\nborykają się m.in. nasze niewidome koleżanki i koledzy. Apelujemy o zapewnienie\\nbezpiecznych, alternatywnych ciągów pieszych oraz lepsze informowanie o zmianach w\\nkursowaniu komunikacji miejskiej.\\nb)Wniosek o ulepszenie organizacji ruchu i zasad korzystania z hulajnóg elektrycznych na\\nterenie miasta.\\nWskazujemy w nim na realne zagrożenie zdrowia i życia, jakie stanowią nieprawidłowo\\nporzucone na chodnikach hulajnogi, przywołując m.in. niedawny wypadek jednej z naszych\\nstudentek na ul. Krasińskiego. Domagamy się wyznaczenia obowiązkowych stref parkowania\\nhulajnóg oraz stref ograniczonej prędkości (zwłaszcza w okolicach szkół i ośrodków dla osób\\nz niepełnosprawnościami).\\n \\f\\n\\nStrona 157 z 219\\n\\nWierzymy, że wspólny i głośny apel naszych środowisk skłoni władze do podjęcia szybkich\\ndziałań i wdrożenia rozwiązań, które sprawią, że miasta będą miejscem bezpiecznym i\\nprzyjaznym dla wszystkich, niezależnie od stopnia ich sprawności.\\n\\n Art. 3 i 4\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 3 i Art. 4\\nZmiany dotyczące unormowania postoju wynajmowanych hulajnóg i innych pojazdów są\\nkorzystne i w interesie społecznym w szczególności osób z niepełnosprawnościami,\\nktóre do tej pory są często poszkodowane z powodu nieodpowiedzialności osób\\nwynajmujących te pojazdy.\\n Art. 3 pkt 2\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 3 zmiana 2) dodaje się ust. 3a w brzmieniu:\\nZamiast obecnej wersji proponujemy nową treść ust. 3a)\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach w ramach mikromobilności dzielonej, w\\nszczególności rower, hulajnogę elektryczną lub urządzenie transportu osobistego jest\\nobowiązana zakończyć jazdę wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę\\ndrogi.”\\nZgodnie z uzasadnieniem zmian w ustawie zakaz miał dotyczyć tylko pojazdów\\nwynajmowanych. Nie miał dotyczyć prywatnych pojazdów. Obecna treść ust. 3a zakazuje\\npozostawiania wszystkich pojazdów poza wyznaczonymi miejscami także\\nprywatnych. Użytkownik pozostawiający pojazd raczej kończy jazdę a nie postój\\n Art. 3 projektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 4)\\n\\nJestem niewidoma. Korzystam z komputera z czytnikiem ekranu. Na stronie Rządowego\\nCentrum Legislacji znalazłam informacje o konsultacjach projektu ustawy o zmianie ustawy o\\nkierujących pojazdami, ale bez użycia myszy nie dotarłam do linku, pod którym można\\npobrać całą treść.\\nWażne jest uporządkowanie kwesƟi parkowania hulajnóg i skuteczne wymierzanie kar za ich\\nporzucanie w miejscach niedozwolonych. Tam, gdzie to możliwe, osoby niewidome\\nporuszają się stroną oddaloną od jezdni, np. wzdłuż trawnika, budynku. Hulajnogi nie\\npowinny być parkowane w takich miejscach ani przy przejściach dla pieszych, ponieważ\\nosobie niewidomej będzie jeszcze trudniej znaleźć przejście.\\nPonadto, miejscowości, w których ﬁrmy mają hulajnogi elektryczne, powinny na tym\\nzarabiać. Skoro trzeba płacić za rozstawienie straganu z truskawkami, na jakiej podstawie\\noperatorzy hulajnóg korzystają z miejskiej przestrzeni za darmo i na tym zarabiają? \\f\\n\\nStrona 158 z 219\\n\\nMieszkam w Jastrzębiu-Zdroju w woj. śląskim. Parę lat temu w nocy w mieście pojawiło się\\nkilkadziesiąt hulajnóg. Na dwie wpadłam w drodze na przystanek. W urzędzie miasta\\ndowiedziałam się, że nie było żadnych uzgodnień. Mimo że ta nocna akcja była nielegalna,\\nmiasto nie miało narzędzi, by obciążyć operatora opłatą.\\nUstawa powinna też obligować policję i straż miejską do wystawiania mandatów za\\npozostawienie hulajnogi w niedozwolonym miejscu. Obecnie w wielu miastach służby tego\\nnie robią. Gdy potknęłam się o hulajnogę, wysiadając z autobusu, inna pasażerka zrobiła jej\\nzdjęcie. Mimo że był na nim widoczny kod QR, straż miejska, której wysłałam zdjęcie, nic nie\\nzrobiła. Powiedziano mi, że podjęłaby działania, gdybym zadzwoniła w momencie zdarzenia.\\nInnym razem zadzwoniłam, straż przyjechała i tylko przestawiła hulajnogę w bezpieczne\\nmiejsce.\\nKażda hulajnoga elektryczna, zarówno komercyjna, jak i prywatna, powinna być łatwa do\\nzidentyﬁkowania, np. numer rejestracyjny, zakodowanie danych właściciela w czipie\\ndostępnym dla policji i straży miejskiej.\\n\\n Art. 3 projektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 5)\\n\\nw związku z wejściem w życie nowych przepisów dotyczących korzystania z hulajnóg\\nelektrycznych przez osoby poniżej 13. roku życia, zwracamy się z apelem o ich ponowną\\nanalizę oraz dostosowanie do rzeczywistych warunków korzystania z tego środka transportu.\\nDoceniamy fakt, że obowiązujące przepisy dopuściły możliwość poruszania się hulajnogą\\nelektryczną przez dzieci poniżej 13. roku życia pod bezpośrednią opieką osoby dorosłej. Jest\\nto rozwiązanie bardziej racjonalne od całkowitego zakazu i uwzględnia rolę rodziców w\\nzapewnianiu bezpieczeństwa najmłodszym uczestnikom ruchu.\\nJednocześnie obowiązujące ograniczenie, zgodnie z którym dziecko może korzystać z\\nhulajnogi elektrycznej wyłącznie w strefie zamieszkania, nie znajduje uzasadnienia w\\npraktyce i nie odpowiada rzeczywistemu charakterowi rodzinnego korzystania z hulajnóg.\\nAnaliza komunikatów Policji oraz doniesień medialnych dotyczących wykroczeń i zdarzeń z\\nudziałem hulajnóg elektrycznych wskazuje, że przypadki naruszania przepisów dotyczą\\nprzede wszystkim młodzieży powyżej 13. roku życia oraz osób dorosłych. To właśnie\\nprzedstawiciele tych grup najczęściej pojawiają się w policyjnych komunikatach dotyczących\\nniebezpiecznych zachowań.\\nNie widać natomiast, aby istotnym problemem były dzieci poniżej 13. roku życia poruszające\\nsię pod opieką rodziców.\\nW praktyce to osoba dorosła wybiera trasę przejazdu, kontroluje sposób jazdy oraz \\f\\n\\nStrona 159 z 219\\n\\nodpowiada za bezpieczeństwo dziecka. Trudno więc uznać, że przejazd rodzica z dzieckiem\\ndrogą dla rowerów stwarza większe zagrożenie niż taki sam przejazd odbywający się kilkaset\\nmetrów dalej w strefie zamieszkania.\\nCo więcej, większość bezpiecznej infrastruktury przeznaczonej dla rowerzystów i\\nużytkowników hulajnóg znajduje się poza strefami zamieszkania. Są to drogi dla rowerów,\\nciągi pieszo-rowerowe oraz tereny rekreacyjne, które zostały zaprojektowane właśnie z\\nmyślą o bezpiecznym poruszaniu się użytkowników rowerów oraz mikromobilności.\\nWspólne przejażdżki rodziców i dzieci to nie tylko forma aktywności fizycznej. To również\\nbudowanie trwałych więzi rodzinnych, tak potrzebnych we współczesnym świecie, a także\\npraktyczna nauka zasad ruchu drogowego. Dzieci uczą się odpowiedzialnych zachowań\\nprzede wszystkim poprzez obserwację swoich rodziców i wspólne uczestnictwo w ruchu\\ndrogowym.\\nDlatego zwracamy się z prośbą o zmianę obowiązujących przepisów poprzez umożliwienie\\ndzieciom poniżej 13. roku życia korzystania z hulajnóg elektrycznych pod bezpośrednią\\nopieką osoby dorosłej wszędzie tam, gdzie przepisy dopuszczają ruch hulajnóg\\nelektrycznych, a nie wyłącznie w strefie zamieszkania.\\nUważamy, że takie rozwiązanie będzie lepiej odpowiadało rzeczywistym potrzebom rodzin,\\njednocześnie nie obniżając poziomu bezpieczeństwa. Pozwoli również skoncentrować\\ndziałania legislacyjne na grupach użytkowników, które – zgodnie z obserwacjami Policji –\\nnajczęściej dopuszczają się naruszeń przepisów ruchu drogowego.\\n\\n Art. 3 projektu\\nustawy\\nPowiatowa\\nSpołeczna Rada\\nds. Osób\\nNiepełnosprawn\\nych w Kielcach\\nw związku z trwającymi konsultacjami publicznymi projektu ustawy dotyczącego\\nuregulowania zasad funkcjonowania mikromobilności współdzielonej, Powiatowa Społeczna\\nRada ds. Osób Niepełnosprawnych w Kielcach wyraża zdecydowane poparcie dla\\nproponowanych rozwiązań dotyczących obowiązku parkowania hulajnóg elektrycznych oraz\\ninnych urządzeń transportu osobistego na wynajem wyłącznie w miejscach wyznaczonych, a\\ntakże dla możliwości usuwania pojazdów pozostawionych niezgodnie z przepisami na koszt\\noperatora.\\n\\nOd wielu lat problem nieprawidłowo zaparkowanych hulajnóg jest przedmiotem zgłoszeń\\nkierowanych do Rady przez mieszkańców oraz organizacje reprezentujące osoby z\\nniepełnosprawnościami. Pozostawiane na chodnikach hulajnogi stanowią istotną barierę w\\nsamodzielnym i bezpiecznym poruszaniu się po przestrzeni publicznej. \\f\\n\\nStrona 160 z 219\\n\\nNajczęstsze problemy zgłaszane przez osoby z niepełnosprawnościami to:\\n\\n- blokowanie chodników i ciągów pieszych,\\nutrudnienia dla osób niewidomych i słabowidzących korzystających z białej laski lub psa\\nprzewodnika, dla których nieprawidłowo pozostawiona hulajnoga może stanowić poważne\\nzagrożenie,\\n- ograniczenie możliwości bezpiecznego poruszania się osób korzystających z wózków,\\nbalkoników i kul,\\n- blokowanie dojść do przejść dla pieszych, przystanków komunikacji publicznej, pochylni\\noraz wind,\\n- pogorszenie dostępności przestrzeni publicznej dla wszystkich mieszkańców.\\n\\nPowiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach od początku angażuje\\nsię w działania na rzecz poprawy bezpieczeństwa i dostępności przestrzeni miejskiej. Rada\\nuczestniczyła w przygotowaniu spotu edukacyjnego dotyczącego prawidłowego parkowania\\nhulajnóg, stworzonego wspólnie z uczniami kieleckiego liceum im. Norwida i emitowanego w\\npojazdach komunikacji miejskiej. Wybór młodzieży jako współtwórców kampanii nie był\\nprzypadkowy – to właśnie ona najczęściej korzysta z hulajnóg elektrycznych, dlatego\\nuznaliśmy, że działania edukacyjne prowadzone z udziałem młodych ludzi mogą\\nnajskuteczniej kształtować właściwe postawy użytkowników.\\n\\nDoceniamy znaczenie edukacji i uważamy, że powinna być ona nadal rozwijana.\\nDotychczasowe doświadczenia pokazują jednak, że same kampanie informacyjne nie\\nrozwiązują problemu. Konieczne jest wprowadzenie skutecznych rozwiązań systemowych.\\n\\nPowiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach popiera tworzenie\\nwyznaczonych stref parkowania hulajnóg, które uporządkują przestrzeń publiczną i ułatwią\\nkorzystanie z niej wszystkim użytkownikom. Jednocześnie za niezbędne uznajemy\\nwyposażenie samorządów w skuteczne narzędzia egzekwowania przepisów, w tym\\nmożliwość usuwania hulajnóg pozostawionych niezgodnie z przepisami na koszt operatora.\\nTo operatorzy, jako podmioty prowadzące działalność gospodarczą i czerpiące z niej korzyści,\\npowinni ponosić odpowiedzialność za sposób funkcjonowania swoich usług oraz za \\f\\n\\nStrona 161 z 219\\n\\nzapewnienie, że nie będą one ograniczać prawa innych osób do bezpiecznego korzystania z\\nprzestrzeni publicznej.\\n\\nPowiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach wyraża pełne poparcie\\ndla proponowanych zmian i apeluje o ich przyjęcie. Jesteśmy przekonani, że nowe przepisy\\nbędą ważnym krokiem w kierunku poprawy bezpieczeństwa, zwiększenia dostępności\\nprzestrzeni publicznej oraz lepszej ochrony praw osób z niepełnosprawnościami.\\n\\n Art. 3 pkt 3\\nprojektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 3 zmiana 3) w art. 130a:\\nZ analogicznego powodu jak wyżej proponujemy nową treść pkt. 8.\\n„8) pozostawienia, z naruszeniem art.7 ust. 3a, pojazdu lub urządzenia przeznaczonego do\\nindywidualnego przemieszczania się na krótkich dystansach w ramach mikromobilności\\ndzielonej, poza miejscem wyznaczonym do tego celu przez zarządcę\\ndrogi.”\\n Art. 8 projektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\nW art. 8 proponujemy wykreślić zdanie drugie. Jest to tzw. masło maślane w kontekście\\nzdania 1.\\n\\n Art. 8 projektu\\nustawy\\nLiga Obrony\\nKraju\\nW Art. 8:\\nProjekt zachowuje bezterminowo pozytywny wynik egzaminu z części teoretycznej dla osób\\nktóre zdały egzamin przed zmianą przepisów.\\nZ tych samych powodów dla których wprowadzono ograniczenie 24 miesięcy proponujemy\\nw tym artykule wpisać ograniczenie, że pozytywny wynik egzaminu z części teoretycznej\\nzachowuje ważność ale tylko przez 24 miesiące od wejścia w życie\\nproponowanych zmian. Prawa nabyte nie powinny być naruszane ale z ważnych powodów\\njest to dopuszczalne. Precedens mamy nawet w przypadku bezterminowych\\npraw jazdy, które jednak będą musiały być wymieniane. Osób które ewentualnie ucierpią na\\ntakiej zmianie raczej nie będzie zbyt wiele w naszej ocenie.\\n Art. 8 projektu\\nustawy\\nZrzeszenie\\nMiędzynarodo-\\nwych\\nPrzewoźników\\nDrogowych w\\nPolsce\\nZastrzeżenia budzi jednak art. 8 projektu, przewidujący bezterminowe zachowanie ważności\\npozytywnych wyników egzaminu teoretycznego uzyskanych przed wejściem ustawy w życie.\\nProjektodawca uzasadnia to potrzebą ochrony uzasadnionych oczekiwań osób, które\\nprzystępowały do egzaminu w przekonaniu o bezterminowej ważności jego wyniku. Bardziej\\nwyważonym rozwiązaniem byłoby przyjęcie, że wyniki te zachowają ważność przez 24\\nmiesiące od dnia wejścia nowych przepisów w życie. Taki okres przejściowy zapewniłby \\f\\n\\nStrona 162 z 219\\n\\nzainteresowanym realną możliwość zakończenia procesu uzyskiwania uprawnień, a\\njednocześnie pozwoliłby zachować spójność regulacji z przyjętym przez projektodawcę\\nzałożeniem, zgodnie z którym wiedza kandydata powinna pozostawać aktualna.\\n Przepisy\\nprzejściowe\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\nw przepisach przejściowych dodać, że wymóg 3 lat prawa jazdy nie dotyczy osób, które\\nprzed wejściem w życie przepisów rozpoczęły kurs na instruktora nauki jazdy.\\n\\n Przepisy\\nprzejściowe\\nPolski Związek\\nNiewidomych 5. Przegląd istniejących miejsc postojowych\\nAktualna propozycja zawarta w UD402\\nProjekt przewiduje wejście w życie przepisów dotyczących mikromobilności dzielonej 1\\nstycznia 2028 r., ale nie nakłada obowiązku przeglądu miejsc postojowych wyznaczonych\\nprzed tą datą.\\nPropozycja PZN\\nW przepisach przejściowych projektu proponuje się dodać przepis:\\n„Zarządcy dróg, na których przed dniem wejścia w życie art. 2 i art. 3 pkt 1–3 niniejszej\\nustawy wyznaczono miejsca postoju pojazdów lub urządzeń udostępnianych w ramach\\nmikromobilności dzielonej, dokonają, do dnia 31 grudnia 2027 r., przeglądu tych miejsc pod\\nwzględem bezpieczeństwa i dostępności ruchu pieszych oraz dostosują je do wymagań\\nwynikających z ustawy i przepisów wykonawczych.”.\\nUzasadnienie\\nBez przepisu przejściowego istniejące miejsca mogą być nadal wykorzystywane mimo ich\\nnieprawidłowej lokalizacji. Okres poprzedzający wejście ustawy w życie powinien zostać\\nwykorzystany nie tylko na dostosowanie aplikacji operatorów, ale także na dostosowanie\\ninfrastruktury.\\n\\n \\f\\n\\nStrona 163 z 219\\n\\nArt. 10\\nprojektu\\nustawy\\n\\nFundacja Vis\\nMaior Pies\\nPrzewodnik\\n\\nPoparcie zmiany prawnej\\nRaz jeszcze pragniemy wyrazić nasze poparcie dla wprowadzenia obowiązku parkowania\\nhulajnóg elektrycznych na wynajem wyłącznie w miejscach wyznaczonych. To konieczny\\nkrok, by wzmocnić bezpieczeństwo wszystkich uczestników ruchu drogowego, w tym\\npieszych ze szczególnymi potrzebami.\\nKonieczność pilnego procedowania\\nArt. 10 pkt 2 projektu ustawy UD402 przewiduje, że obowiązek parkowania hulajnóg\\nelektrycznych na wynajem wejdzie w życie 1 stycznia 2028 roku. Postulujemy maksymalne\\nmożliwe skrócenie tego okresu i, o ile będzie to możliwe, wejście w życie zmian od 1 lipca\\n2027 roku. Oznacza to konieczność pilnego procedowania projektu. Mamy jednak nadzieję,\\nże postulat ten zostanie przez Pana Ministra uwzględniony z uwagi na fakt, że proponowane\\nprzepisy regulują kwestie istotne dla bezpieczeństwa uczestników ruchu drogowego.\\n Art. 10\\nprojektu\\nustawy\\nPolski Związek\\nSzkoleniowy\\n17) W art. 10 w pkt 1 i pkt 3 wymieniony jest art. 1 pkt 11. Obydwa punkty mają zasadniczo\\ninną datę wejścia w życie. Trzeba podjąć jednoznaczną decyzję w jakim terminie wchodzi w\\nżycie przepis art. 1 pkt 11.\\n\\n Art. 10\\nprojektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 6)\\n\\nchciałbym przekazać swoje uwagi do projektu o numerze UD402.\\n\\nPo pierwsze, mam wątpliwości czy termin wejścia w życie ustawy (w projekcie 1 stycznia\\n2027 r.) jest realnym terminem. Konsultacje projektu zakończą się pod koniec lipca,\\nnastępnie projekt musi zostać jeszcze przyjęty przez stały komitet RM, komisje prawniczą, a\\ntakże przez Radę Ministrów. Następnie przynajmniej 6 tygodni w obu izbach Parlamentu, 21\\ndni na podpis Prezydenta RP i kilka dni na publikację w Dzienniku Ustaw RP.\\nProszę rozważyć czy ten termin jest rzeczywiście realny. Ja bym jednak proponował jego\\nzmianę na 1 lutego, bądź 1 marca.\\n\\nNastępnie, uważam, że termin wejścia w życie rejestracji egzaminów państwowych każdej\\nkategorii należy przesunąć na 1 lipca 2027 r., i tym samym ujednolicić z wejściem w życie\\nrejestracji egzaminów wewnętrznych. Zamówienie urządzeń do rejestracji zajmuje pewien \\f\\n\\nStrona 164 z 219\\n\\nczas, a następnie trzeba te urządzenia zamontować oraz skonfigurować.\\n\\nZ wyrazami szacunku,\\nAdrian Piotrkowski\\n\\n Art. 10\\nprojektu\\nustawy\\nOsoba fizyczna\\n(zgłoszenie nr 7)\\nProjektowany przepis wprowadzający sztywny, półroczny termin na ukończenie kursu oraz\\nrozpoczęcie procedury egzaminacyjnej przez kandydatów na instruktorów jest rozwiązaniem\\ncałkowicie oderwanym od realiów rynkowych oraz administracyjnych. W praktyce przepis\\nten drastycznie ograniczy obywatelom możliwość uzyskania uprawnień zawodowych, co\\nrodzi poważne wątpliwości natury konstytucyjnej. Wprowadzenie tak krótkiego ramu\\nczasowego jest wadliwe z dwóch kluczowych powodów: Paraliż proceduralny a\\nodpowiedzialność kandydata: Proces szkolenia wymaga czasu, jednak największym\\nproblemem jest sama procedura egzaminacyjna. Terminy egzaminów państwowych są\\nwyznaczane przez Wojewódzkie Ośrodki Ruchu Drogowego (WORD) z dużym opóźnieniem.\\nKandydat nie ma żadnego wpływu na opieszałość aparatu urzędniczego. Narzucenie limitu\\nsześciu miesięcy oznacza, że obywatel poniesie finansowe i czasowe konsekwencje\\nniewydolności systemu organizowanego przez państwo. Naruszenie Konstytucji RP:\\nRozwiązanie to stoi w sprzeczności z zasadą państwa prawa (art. 2 Konstytucji RP), a w\\nszczególności z wywodzoną z niej zasadą zaufania obywatela do państwa i stanowionego\\nprzez nie prawa oraz zasadą proporcjonalności. Prawo nie może wymagać od obywatela\\nrzeczy niemożliwych ani karać go (poprzez przepadnięcie kursu) za opóźnienia leżące po\\nstronie organów egzaminacyjnych. Ponadto regulacja ta w sposób nieuzasadniony ogranicza\\nwolność wyboru i wykonywania zawodu (art. 65 ust. 1 Konstytucji RP). Wniosek: Termin ten\\nnależy wydłużyć (co najmniej do 12 miesięcy) lub całkowicie wyłączyć z niego czas\\noczekiwania na wyznaczenie terminów egzaminów przez WORD. W obecnym kształcie\\nprzepis ten jest rażąco niesprawiedliwy i podatny na zaskarżenie do Trybunału\\nKonstytucyjnego.\\n\\nUwagi\\ndodatkowe\\n\\nZwiązek\\nPracodawców\\n„Transport i\\n\\n Zaproponowane zmiany odnoszą się przede wszystkim do narzędzi, procedur i\\ninstrumentów formalnego nadzoru, pozostawiając na uboczu dużo ważniejsze kwestie takie\\njak:  \\f\\n\\nStrona 165 z 219\\n\\nLogistyka\\nPolska”\\n• podniesienie kompetencji oso b prowadzących szkolenie oraz oso b sprawdzających\\nkwalifikacje;\\n• zmiana zasad i sposobu prowadzenia szkolenia oso b ubiegających się o\\nuprawnienia do kierowania, w celu ich dostosowania do wspo łczesnych standardo w,\\nobowiązujących w krajach o znacznie wyz szym poziomie bezpieczen stwa ruchu drogowego\\nniz Polska oraz dostosowania do rozwoju technicznego w zakresie motoryzacji,\\ninfrastruktury drogowej, etc.;\\n• gruntowna zmiana zasad i sposobu przeprowadzania egzaminu państwowego tak,\\naby przestał on byc swoistą „sztuką dla sztuki”, a stał się faktycznym sprawdzianem wiedzy i\\numiejętnos ci, potrzebnych do bezpiecznego uczestnictwa w ruchu drogowym\\n(proponowana likwidacja placu manewrowego jest krokiem w dobrym kierunku, ale niestety\\nto tylko jeden z wielu elemento w wymagających korekty);\\n• potrzeby polskiej gospodarki narodowej, kto ra w duz ej mierze zawdzięcza swo j\\nrozwo j branz y transportu drogowego (jedynej polskiej branz y, kto ra jest liderem /pierwsze\\nmiejsce/ na jednolitym unijnym rynku), a kto ra napotkała mocną barierę rozwoju, związaną\\nz brakiem wykwalifikowanych kierowco w.\\n\\nZ zaskoczeniem i niepokojem przyjęliśmy, że znaczna część propozycji nie została - w ocenie\\nTLP - uzasadniona pogłębionymi badaniami, analizą dobrych praktyk, ani opracowaniami\\nnaukowymi. Projekt nie wyjaśnia również w dostatecznym stopniu, w jaki sposób dobierano\\nekspertów, uczestniczących w pracach zespołu działającego przy resorcie infrastruktury,\\nktóry opracował założenia przedstawionego do konsultacji projektu. 2\\n\\nPoważne wątpliwości budzi także brak przedstawienia pełnej analizy kosztów wdrożenia\\nproponowanych rozwiązań. Dla przykładu, TLP szacuje, że obsługa „cyfrowej karty kursanta”\\nmoże generować po stronie branży szkoleniowej, a pośrednio jej klientów, koszty sięgające\\nco najmniej 100 mln zł rocznie. W dokumentacji projektu nie przedstawiono odrębnych\\nanaliz kosztów i korzyści, dotyczących poszczególnych propozycji.\\nNa dodatek, część zaproponowanych rozwiązań wydaje się nam całkowicie sprzeczna z\\ndeklarowanymi przez Prezesa Rady Ministrów działaniami na rzecz deregulacji (przykładem\\nmoże być wspomniana wyżej „cyfrowa karta kursanta” i nałożone zarówno na instruktorów,\\njak i osoby szkolone, liczne obowiązki związane z jej obsługą – gdzie wszelkie formalne \\f\\n\\nStrona 166 z 219\\n\\npomyłki skutkować będą podwyższonym ryzykiem utraty uprawnień zawodowych lub\\nlikwidacji prowadzonej działalności gospodarczej). Zamiast ułatwiać dostęp do kursów prawa\\njazdy, wprowadzają one skomplikowane procedury, stanowiące nieuzasadnione bariery\\nadministracyjne dla podmiotów szkoleniowych i kursantów, a także dla organów\\nadministracji, zaangażowanych w system szkolenia kierowców.\\nNiemniej liczymy, że resort infrastruktury uwzględni uwagi i propozycje przedkładane w\\ntrakcie konsultacji społecznych, co pozwoliłoby usunąć przedłożone wyżej zastrzeżenia.\\nSzczególnie, że z kalendarza wyborczego wynika, że ewentualne późniejsze działania\\nlegislacyjne, mające na celu wyjście naprzeciw uwagom i propozycjom składanym pod\\nadresem zmian w szeroko rozumianym systemie uzyskiwania uprawnień do kierowania\\npojazdami, skazane mogą być na niepowodzenie. Może to wywołać negatywny odbiór\\nspołeczny, szczególnie wśród środowisk, związanych zawodowo z transportem i ruchem\\ndrogowym.\\nDlatego też, przed przejściem do szczegółowej analizy i uwag związanych z propozycjami\\nzawartymi w projekcie, chciałbym w imieniu TLP, wskazać pakiet konkretnych propozycji,\\nktórych wdrożenia oczekiwalibyśmy przy okazji tej inicjatywy legislacyjnej. Propozycje te w\\ndużej części związane są z wynikami badania przeprowadzonego przez TLP w sierpniu 2023\\nroku „Ocena rynku szkoleń zawodowych kierowców”. Raport z badania został przekazany do\\nwiadomości resortu infrastruktury w tym samym roku. Raport pokazał bardzo krytyczną\\nocenę systemu uzyskiwania uprawnień (szkolenia i egzaminowania) w zakresie wyższych\\nkategorii praw jazdy (kategoria C1 C1+E, C, C+E, D1, D1+E, D, D+E).\\nDla przykładu, kilka wybranych liczb z ww. raportu. 46% respondentów badania określiło\\nstopień umiejętności i wiedzy osób, uzyskujących uprawnienia do kierowania ciężkimi\\nsamochodami do przewozu rzeczy lub autobusami, jako żaden lub niedostateczny. Co\\ncharakterystyczne, aż 61% respondentów określiło umiejętności w zakresie korzystania z\\npełnej funkcjonalności współczesnych pojazdów, jako żadne lub niedostateczne. To tylko\\nwybrane wyniki tego badania, niemniej dobitnie pokazują patologie obecnego systemu.\\nCzęść z zamieszonych niżej propozycji, ma na celu także usunięcie barier jakie napotykamy w\\ntrakcie procesu rekrutacji kierowców, szczególnie w zakresie procedur związanych z\\nwydawaniem wymaganych od kierowców dokumentów. \\f\\n\\nStrona 167 z 219\\n\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\nPropozycje TLP do projektu ustawy\\n1) Modyfikacja przepisów określających warunki uzyskania polskiego krajowego prawa\\njazdy.\\nPolski przewoźnik (pracodawca) rekrutując pracownika z zagranicy na czas określony (np. na\\njeden rok) nie może przed upływem 6 miesięcy, uzyskać dla tego pracownika odpowiednich\\npolskich uprawnień do kierowania pojazdami (pracownik nie może przystąpić do szkolenia,\\ndo dodatkowego egzaminu, ani uzyskać wymiany zagranicznych uprawnień na polskie\\nkrajowe uprawnienia). Ponieważ zezwolenie na pracę dotyczy zatrudnienia na konkretnym\\nstanowisku pracy (np. kierowca wykonujący przewozy międzynarodowe), przez 6 miesięcy\\nsprowadzony pracownik nie może legalnie uzyskać środków utrzymania, a tym samym,\\nkoszty jego pobytu obciążają pracodawcę. I to pomimo, że po uzyskaniu zezwolenia na pobyt\\ni pracę, pracownik jest związany z terytorium Polski przez okres dłuższy niż 6 miesięczny\\nokres karencyjny określony w unijnych przepisach. Stąd, nasz postulat wprowadzenia\\nodpowiedniego przepisu uznającego, iż warunek pobytu w Polsce przez co najmniej 6\\nmiesięcy jest spełniony, o ile osoby ubiegające się o polskie uprawnienia, mają odpowiednie\\nzezwolenie na pobyt i pracę przez okres dłuższy niż 6 miesięcy.\\nDlatego też proponujemy w art.11 ustawy z dnia 5 stycznia 2011 r. o kierujących\\npojazdami (UoKP) po ust. 1 dodanie ust. 1c w brzmieniu:\\n„1c. Warunek o którym mowa w ust. 1, uważa się za spełniony przez cudzoziemca, który\\notrzymał odpowiednie zezwolenie na pobyt i pracę na terytorium Rzeczypospolitej Polskiej na\\nokres dłuższy niż 6 miesięcy.”.\\nJedną z zasad obowiązujących przy wymianie zagranicznego prawa jazdy jest uwzględnianie\\nterminów ważności przypisanym poszczególnym kategoriom prawa jazdy. W praktyce\\noznacza to, że jeżeli zagraniczne prawo jazdy nie zawiera tych terminów, to starostowie\\nodmawiają ich wymiany. W naszej ocenie jest to luka prawna, stwarzająca kolejną formalną\\nbarierę w przypadku rekrutacji pracowników z innych państw.\\nDlatego też proponujemy w art. 14 UoKP dodanie ust. 2g w brzmieniu:\\n„2g. Jeżeli ważne krajowe prawo jazdy wydane w państwie innym niż państwo członkowskie\\nUnii Europejskiej, Konfederacja Szwajcarska lub państwo członkowskie Europejskiego\\nPorozumienia o Wolnym Handlu (EFTA) — strona umowy o Europejskim Obszarze\\nGospodarczym — nie określa terminów ważności poszczególnych kategorii, to terminy\\nważności wydawanego polskiego krajowego prawa jazdy, ustala się zgodnie z art. 13 ust. 1 i\\n2.”.  \\f\\n\\nStrona 168 z 219\\n\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n2) Podniesienie kompetencji instruktorów i egzaminatorów w zakresie wyższych kategorii\\nprawa jazdy\\nNie rozstrzygając w tym miejscu o kompleksowych, docelowych rozwiązaniach, dotyczących\\nkompetencji osób szkolących i sprawdzających kwalifikacje w zakresie wszystkich kategorii\\nprawa jazdy, TLP stoi na stanowisko, że za zbyt niski stopień przygotowania osób\\nuzyskujących uprawnienia do kierowania pojazdami w zakresie wyższych kategorii prawa\\njazdy (C, C+E, D, D+E) odpowiada brak dostatecznych kompetencji po stronie instruktorów i\\negzaminatorów, w zakresie realnej praktyki w kierowaniu nowoczesnym pojazdem i w\\nwykonywaniu zadań, jakie powinni wykonywać zawodowi kierowcy. Są to rażące braki,\\nzważywszy, iż instruktorzy są także uprawnieni do prowadzenia szkolenia w zakresie\\nkwalifikacji wstępnej i szkoleń okresowych, o których mowa w ustawie z dnia 6 września\\n2001 roku o transporcie drogowym (UoTD).\\nAby podnieść poziom przygotowania tych osób, proponujemy, aby instruktorzy i\\negzaminatorzy w zakresie wyższych kategorii prawa jazdy, spełniali odpowiednie wymagania\\nstawiane kierowcom wykonującym przewóz drogowy, wynikające z art. 39a UoTD, oraz\\nposiadali udokumentowane doświadczenie w kierowaniu i użytkowaniu nowoczesnych\\npojazdów, wykorzystywanych w przewozach drogowych - przykładowo co najmniej\\nsześciomiesięczne doświadczenie na stanowisku kierowcy albo odpowiadający mu staż\\npraktyczny.\\nDlatego też w proponujemy:\\n- w art. 33 UoKP po ust. 1a dodanie ust. 1b w brzmieniu:\\n„1b. Dodatkowym wymogiem wobec instruktorów prowadzących szkolenie w zakresie prawa\\njazdy kategorii C, C+E, D lub D+E jest:\\n1) spełnienie warunków, o których mowa w art. 39a ustawy z dnia 6 września 2001 r. o\\ntransporcie drogowym,\\n2) wykazanie się co najmniej 6 miesięcznym:\\na) zatrudnieniem na stanowisku kierowcy wykonującego przewóz drogowy, w wymiarze co\\nnajmniej połowy pełnego czasu pracy, lub  \\f\\n\\nStrona 169 z 219\\n\\nb) stażem w przedsiębiorstwie wykonującym przewóz drogowy, na stanowisku kierowcy,\\ndyspozytora lub spedytora.”\\n\\n- w art. 58 UoKP po ust. 1 dodanie ust. 1a w brzmieniu:\\n„1a. Dodatkowym wymogiem wobec egzaminatorów dokonujących sprawdzenia kwalifikacji\\nw zakresie prawa jazdy kategorii C, C+E, D lub D+E jest:\\n1) spełnienie warunków, o których mowa w art. 39a ustawy z dnia 6 września 2001 r. o\\ntransporcie drogowym,\\n2) wykazanie się co najmniej 6 miesięcznym:\\na) zatrudnieniem na stanowisku kierowcy wykonującego przewóz drogowy, w wymiarze co\\nnajmniej połowy pełnego czasu pracy,\\nb) stażem w przedsiębiorstwie wykonującym przewóz drogowy, na stanowisku kierowcy,\\ndyspozytora lub spedytora.” nauki jazdy osób ubiegających się o prawo jazdy kategorii innej\\nniż kategoria C, C+E, D lub D+E,\\n\\n- w art. 39a ust. 3 pkt 7 UoTD wprowadzenie następujących zmian:\\n1) lit. a otrzymuje brzmienie:\\n2) uchyla się lit. b,\\n3) lit. c otrzymuje brzmienie:\\nprzeprowadzania państwowego egzaminu dla osób ubiegających się o prawo jazdy kategorii\\ninnej niż kategoria C, C+E, D lub D+E;”\\n\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n3) Skrócenie okresu oczekiwania na uzyskanie wymaganych dokumentów uprawniających\\ndo kierowania i wykonywania zawodu kierowcy\\nObecnie uzyskanie dokumentów wymaganych do kierowania pojazdem i wykonywania\\nzawodu kierowcy, wymaga udziału kilku organów i podmiotów oraz, co do zasady, kolejnego\\nprzechodzenia poszczególnych procedur. Prawo jazdy wydaje właściwy organ administracji,\\nkarta kierowcy do tachografu jest wydawana przez PWPW S.A., natomiast świadectwo\\nkierowcy - przez Głównego Inspektora Transportu Drogowego. Mimo odrębności tych\\nprocedur, część danych źródłowych się powtarza. Na dodatek, dane te są w dyspozycji tego\\nsamego podmiotu (PWPW S.A.). Stąd - w naszej ocenie - procesy uzyskania tych\\ndokumentów, można prowadzić równoległe, bez naruszenia prawa UE.\\nDlatego też proponujemy, aby świadectwo kierowcy było wydawane:  \\f\\n\\nStrona 170 z 219\\n\\n• bez konieczności przedkładania prawa jazdy z kodem 95 (lub karty kierowcy) lub\\nalternatywnie,\\n• na podstawie przedłożonych wymaganych orzeczeń (lekarskiego i psychologicznego)\\ni świadectwa kwalifikacji zawodowej.\\n\\nW tym drugim wariancie, należałoby dodatkowo wskazać, że jeżeli kierowca ma już ważne,\\nwydane w innym państwie członkowskim UE, prawo jazdy lub kartę kwalifikacji z kodem 95,\\nto może je przedłożyć, zamiast świadectwa kwalifikacji zawodowej.\\nW przypadku wniosku o wydanie karty kierowcy do tachografu cyfrowego proponujemy, aby\\nzamiast prawa jazdy, w przypadku gdy kierowca złożył wniosek o jego wydanie, wniosek\\nmógł 5\\n\\nzawierać numer Profilu Zawodowego Kierowcy, który posiada PWPW S.A.. W tej sytuacji\\nPWPW S.A. mogłaby w tym samym dniu, wysłać kierowcy zarówno kartę do TC, jak i\\npersonalizowane prawo jazdy.\\nDlatego też proponujemy m.in.:\\n- w art. 32b ust. 5 UoTD nadać pkt 2 brzmienie:\\n„2) zaświadczenie o zatrudnieniu kierowcy;”\\n(ta wersja propozycji TLP wynika z faktu, że zgodnie z art. 39f oraz zgodnie z przepisami\\ndyrektywy Parlamentu Europejskiego i Rady (UE) 2022/2561 spełnienie wymagań, o których\\nmowa w art. 39a ust. 1 pkt 5 i 6 UoTD dokumentowane jest kodem 95 w prawie jazdy lub w\\nkarcie kwalifikacji kierowcy, bez których kierowca nie może wykonywać przewozów\\ndrogowych. Stąd nie ma potrzeby dublowania tych wymagań w świadectwie kierowcy)\\nAlternatywnie\\n- w art. 32b UoTD proponujemy:\\n1) w ust. 5 pkt 2 otrzymuje brzmienie:\\n„2) zaświadczenie o zatrudnieniu kierowcy oraz kopie:\\n• wymaganych orzeczeń:\\n\\n- lekarskiego o braku przeciwwskazań zdrowotnych do wykonywania pracy na stanowisku\\nkierowcy,\\n- psychologicznego o braku przeciwwskazań psychologicznych do wykonywania pracy na\\nstanowisku kierowcy;  \\f\\n\\nStrona 171 z 219\\n\\n• wymaganego świadectwa kwalifikacji zawodowej;”;\\n\\n2) po ust. 4 dodaje się ust. 4a w brzmieniu:\\n„4a. Wymóg, o którym mowa w ust. 5 pkt 2 lit. c uznaje się za spełniony, jeżeli do wniosku\\ndołączona zostanie kopia ważnego krajowego prawa jazdy wydanego w innym państwie\\nczłonkowskim z kodem 95 w zakresie odpowiedniej kategorii.”\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n4) Wprowadzenie przyśpieszonej ścieżki uzyskiwania prawa pobytu i pracy dla\\nzrekrutowanych lub już obecnie pracujących na rzecz polskiego przewoźnika kierowców\\nspoza UE\\nNajwiększym problemem, barierą i wyzwaniem jest strukturalny brak kierowców na polskim\\nrynku pracy. Już w 2017 roku prognozy zawarte w raporcie PWC/TLP „Rynek pracy\\nkierowców w Polsce” przewidywały, iż w latach 2025 i następnych zabraknie nam około 320\\ntysięcy pracowników wykonujących przewozy drogowe. Tej katastrofie udało się częściowo\\nzapobiec, sukcesywnie zatrudniając kierowców spoza UE. I tak, w 2023 roku pracowało w\\npolskich firmach około 165 tysięcy zagranicznych kierowców, co pozwoliło częściowo\\nzrekompensować przewidywania z 2017 roku. Obecnie, na skutek zaostrzenia polityki\\nmigracyjnej, w porównaniu z rokiem 2023 utraciliśmy około 20 tysięcy pracowników z\\nzagranicy. TLP szacuje, że w 2026 roku brakuje nam około 120 tysięcy pracowników w tym\\nzawodzie. I jest to problem, wynikający nie tyle z niskich zarobków (przeciętne\\nwynagrodzenie w międzynarodowym transporcie drogowym wynosi od 8 do 10 tysięcy\\nzłotych netto), co problem strukturalny, charakterystyczny dla każdego kontynentu. Na\\ndodatek, w coraz większym tempie tracimy dotychczas zatrudnionych kierowców spoza UE,\\nktórzy oczekują na przedłużenie prawa pobytu i pracy nawet do 18 miesięcy. Ich sytuacja\\nróżni się zasadniczo od innych grup zawodowych, gdyż pracując w usługach\\ntransgranicznych, nie mogą się wykazać odpowiednimi dokumentami pozwalającymi\\nprzekraczać granice wewnętrzne strefy Schengen (te dostaną bowiem po upływie nawet 1,5\\nroku od dnia, w którym złożono wniosek o odpowiednie zezwolenie). Pozostałe grupy\\npracowników spoza UE, wykonujące zawody nie wymagające przekraczania granic, mogą\\nlegalnie kontynuować pracę na podstawie potwierdzenia złożenia wniosku o przedłużenie\\nprawa pobytu i pracy.\\nDlatego też, nie ingerując w wynikające z polityki migracyjnej Rządu zasady przyznawania\\nprawa pobytu i pracy, ta najliczniejsza grupa zawodowa, wymaga pierwszeństwa („fast\\ntrack”) w rozpatrywaniu wniosków w tych sprawach. Jest to zgodne z interesem polskiego \\f\\n\\nStrona 172 z 219\\n\\nrynku pracy, aby w pierwszej kolejności pracę otrzymywały osoby, niestanowiące\\nkonkurencji dla polskich bezrobotnych.\\nStąd też wnioskujemy o przyjęcie przepisów (lex specialis), pozwalających na skorzystanie\\ndla tej grupy zawodowej, z tzw. szybkiej ścieżki, przewidzianej w ustawie z dnia 20 marca\\n2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium\\nRzeczypospolitej Polskiej oraz w ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach.\\nDlatego też proponujemy - w rozdziale 7a UoTD, dodanie art. 39o w brzmieniu:\\n„Art. 39o. 1. Minister właściwy do spraw transportu w porozumieniu z ministrem właściwym\\ndo spraw gospodarki może określić, w drodze rozporządzenia, wykaz stanowisk pracy\\nkierowców, w którym występują strukturalne niedobory kadrowe.\\n2. Wykaz określający grupy zawodów, w których występują niedobory kadrowe, tworzony\\njest na podstawie badań, analiz i ocen dotyczących potrzeb rynku pracy kierowców, a także\\nw oparciu o znaczenie dla gospodarki narodowej oraz krajowego bilansu płatniczego\\nposzczególnych rodzajów przewozów drogowych.\\n3. Przedsiębiorcom ubiegającym się o wydanie zezwolenia na pracę cudzoziemca na pracę na\\nstanowisku określonym w wykazie, o którym mowa w ust. 1, przysługuje pierwszeństwo w\\nrozpatrywaniu wniosków, na zasadach określonych w art. 27 pkt 1 ustawy z dnia 20 marca\\n2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium\\nRzeczypospolitej Polskiej.\\n4. Kierowcom spoza Unii Europejskiej, ubiegającym się o zatrudnienie lub zatrudnionym u\\nprzedsiębiorcy posiadającego zezwolenie na wykonywanie zawodu przewoźnika drogowego\\nlub licencję wspólnotową, na stanowisku określonym w wykazie, o którym mowa w ust. 1,\\nprzysługuje pierwszeństwo w rozpatrywaniu wniosków o wydanie wizy, wniosków o udzielenie\\nzezwolenia na pobyt czasowy oraz wniosków o udzielenie zezwolenia na pobyt czasowy i\\npracę, na zasadach określonych odpowiednio w art. 77 ust. 9a, w art. 112a ust. 3b oraz w art.\\n117b ustawy z dnia 12 grudnia 2013 r. o cudzoziemcach.”.\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n5) Zmiany w egzaminie praktycznym na prawo jazdy kategorii C, C+E, D, D+E (likwidacja\\nplacu manewrowego, wyprowadzenie jazdy w ruchu kategorii C, C+E z miast na prawach\\npowiatu)\\nObecnie, część praktyczna egzaminu państwowego w zakresie prawa jazdy kategorii C, C+E,\\nD, D+E przeprowadzana jest na placu manewrowym wojewódzkiego ośrodku ruchu\\ndrogowego oraz na drogach publicznych, położonych w mieście na prawach powiatu.\\nZarówno warunki placu manewrowego, jak i ruchu miejskiego, nie odpowiadają \\f\\n\\nStrona 173 z 219\\n\\nrzeczywistym warunkom, w jakich pracują zawodowi kierowcy w transporcie drogowym w\\nprzewozie rzeczy lub osób. Wykonywanie manewrów ciężkimi pojazdami w oparciu o\\nstanowiska wyznaczone tyczkami powoduje, że znaczna część szkolenia przygotowującego\\n(niestety) głównie do egzaminu państwowego, przeprowadzana jest w warunkach, w\\nktórych przyszły kierowca nigdy nie będzie wykonywał jakichkolwiek manewrów. Tym\\nsamym, umiejętność wykonywania podstawowych manewrów jest nabywana przez\\nkierowców już po uzyskaniu uprawnienia do kierowania pojazdem dla którego wymagane są\\nwyższe kategorie prawa jazdy. Potwierdzają to powoływane wyżej wyniki badań TLP „Ocena\\nrynku szkoleń zawodowych kierowców”, gdzie 41,5% 7\\n\\nsprawdzenie podstawowych umiejętności w zakresie panowania nad pojazdem\\nodpowiednim dla uprawnień prawa jazdy kategorii AM, A1, A2, A,\\nsprawdzenie umiejętności manewrowania pojazdem lub zespołem pojazdów odpowiednim\\ndla uprawnień prawa jazdy kategorii B+E, C1, C1+E, D1, D1+E, i T;\\n\\nankietowanych wskazało, na brak umiejętności „młodych” kierowców w zakresie\\nwykonywania podstawowych manewrów pojazdami używanymi w ich\\nprzedsiębiorstwach.\\nIdentyczne zastrzeżenia dotyczą obecnych warunków, w których przeprowadzane jest\\nsprawdzenie kwalifikacji w ruchu drogowym. Ich konsekwencją jest przeniesieniu głównego\\nnacisku podczas szkolenia przyszłych kierowców na ruch miejski, co nie odpowiada\\nrzeczywistym warunkom, w jakich ci kierowcy będą wykonywali codzienne zadania w\\nprzewozach drogowych. To ostatnie zastrzeżenie dotyczy przede wszystkim szkolenia i\\negzaminowania pojazdami, dla których wymagane jest prawo jazdy kategorii C i C+E. W\\nzakresie szkolenia na kategorię D sytuacja kształtuje się bowiem w odmienny sposób, gdyż\\nznaczna część pracy kierowców związana jest z ruchem miejskim (komunikacja miejska,\\nprzystanki komunikacji regionalnej i ponad regionalnej, etc.)\\nMając na uwadze powyższą ocenę sytuacji, TLP wnioskuje o wyprowadzenie egzaminu\\npraktycznego z placów manewrowych w zakresie kategorii C, C+E, D, D+E oraz\\nprzeprowadzanie sprawdzenia kwalifikacji na drogach publicznych, położonych poza\\nmiastem na prawach powiatu, w zakresie kategorii C i C+E.  \\f\\n\\nStrona 174 z 219\\n\\nDodatkowo uważamy, że praktyczna część egzaminu państwowego w zakresie prawa jazdy\\nkategorii B, B+E, C1, C1+E, C, C+E, D1, D1E, D, D+E powinna zawierać, jako obowiązkowy\\nelement, jazdę po autostradzie, drodze ekspresowej lub drodze dwujezdniowej o dwóch\\npasach ruchu dla tego samego kierunku, na których dopuszcza się prędkość co najmniej\\n90/km/h, a także jazdę poza obszarem zabudowanym na drodze innej, niż wskazane\\nwcześniej drogi.\\nDlatego też proponujemy w art. 51 UoKP:\\n- w ust. 3 pkt 1 otrzymuje brzmienie:\\n„1) na placu manewrowym wojewódzkiego ośrodka ruchu drogowego – w zakresie\\nobejmującym:\\n2) w ruchu drogowym na drogach publicznych – w zakresie obejmującym sprawdzenie\\npozostałych umiejętności wymaganych podczas części praktycznej egzaminu dla uprawnień\\ndowolnej kategorii prawa jazdy.”.\\n- po ust. 3 dodaje się ust. 3a w brzmieniu:\\n„3a. Obowiązkowym elementem części praktycznej egzaminu państwowego , o której mowa\\nw ust. 3 pkt 2, dla uprawnień prawa jazdy kategorii B, B+E, C1, C1+E, C, C+E, D1, D1+E,, D,\\nD+E, jest jazda:\\n1) autostradą, drogą ekspresową lub drogą dwujezdniową z co najmniej dwoma pasami\\nruchu dla każdego kierunku, na których dopuszcza się prędkość co najmniej 90/km/h;\\n2) drodze jednojezdniowej położonej poza obszarem zabudowanym.”.\\n\\n- ust. 4b otrzymuje brzmienie:\\n„4b. Egzamin państwowy w zakresie prawa jazdy kategorii C, C+E, T, w części, o której mowa\\nw ust. 3, jest przeprowadzany poza granicami administracyjnymi miasta, o którym mowa w\\nust. 4.”.\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n6) Zmodyfikowanie dotychczasowych celów egzaminu państwowego osób ubiegających\\nsię o uprawnienie do kierowania pojazdem\\nNajważniejszym elementem systemu uzyskiwania uprawnień do kierowania pojazdami jest\\netap sprawdzania kompetencji i kwalifikacji uzyskiwanych w poprzedzającym ten etap\\nprocesie szkolenia. Aby mógł on prawidłowo spełniać swoje funkcje, należy prawidłowo\\nzdefiniować jego cele, Obecne cele egzaminu państwowego zdefiniowane zostały ponad 20\\nlat temu w pierwszej wersji ustawy o kierujących pojazdami i były zgodne z ówczesnym \\f\\n\\nStrona 175 z 219\\n\\nstanem wiedzy i przykładami najlepszej praktyki w innych państwach europejskich. Te cele\\nzostały bez żadnych zmian przeniesione do obecnie obowiązującej ustawy, którą uchwalono\\nprawie 15 lat temu. Od tego czasu w europejskich systemach uzyskiwania uprawnień\\ndokonał się znaczny postęp dotyczący przede wszystkim założeń w zakresie wiedzy i\\numiejętności sprawdzanych podczas egzaminu osób ubiegających się o prawo jazdy. Dzisiaj\\njest najwyższy czas, aby uwzględnić ten postęp w polskich przepisach regulujących zakres\\nsprawdzania kwalifikacji przyszłych kierowców.\\nPonadto należy wziąć pod uwagę kierunek zmian w unijnych przepisach regulujących ten\\nobszar. Nowa dyrektywa (UE) 2025/2205 wymaga uwzględnienia m.in. percepcji zagrożeń i\\npodejmowania decyzji, zmęczenia i stanu psychicznego, dekoncentracji urządzeniami\\nelektronicznymi, mikromobilności i innych niechronionych uczestników ruchu drogowego,\\nmartwych pól, pierwszej pomocy i resuscytacji krążeniowo-oddechowej, pojazdów\\nalternatywnie zasilanych oraz zalet, ograniczeń i ryzyka ADAS i automatyzacji. W egzaminie\\npraktycznym dyrektywa nakazuje zwracać uwagę na jazdę defensywną i społeczną.\\nMając powyższe na uwadze TLP proponuje zmianę brzmienia art. 51 ust. 1 UoKP na\\nnastępujące:\\n„1. Egzamin państwowy jest przeprowadzany w celu sprawdzenia wiedzy, umiejętności,\\nzachowań oraz zdolności do samooceny osoby egzaminowanej, niezbędnych do\\nsamodzielnego, odpowiedzialnego, defensywnego, bezpiecznego i środowiskowo\\nefektywnego kierowania pojazdem, w szczególności w zakresie rozpoznawania i\\nprzewidywania zagrożeń, podejmowania decyzji, ochrony niechronionych uczestników ruchu,\\noceny własnej sprawności psychofizycznej, zarządzania uwagą, właściwego korzystania z\\nsystemów wspomagania i automatyzacji oraz działania w sytuacji awarii lub wypadku.”\\nW ślad za zmianą celów egzaminu państwowego warto pokusić się o korektę form, w jakich\\nten egzamin się odbywa. I tu TLP proponuje następujące brzmienie przepisu art. 51 ust. 2\\nUoKP:\\n„2. Egzamin państwowy składa się z:\\n1) części teoretycznej, przeprowadzanej w formie testów sprawdzającej wiedzę, percepcję\\nzagrożeń, ocenę ryzyka i podejmowanie decyzji;\\n2) części praktycznej, sprawdzającej umiejętności oraz zachowania osoby egzaminowanej\\npodczas przygotowania pojazdu i kierowania nim w ruchu drogowym,”.\\n \\f\\n\\nStrona 176 z 219\\n\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n7) Wprowadzenie możliwości wdrażania indywidualnych/pilotażowych programów\\nszkolenia\\nObecny, sztywny program szkolenia kierowców, a także bardzo rygorystyczne określenie\\nwarunków i zasad prowadzenia zajęć, uniemożliwiają jakikolwiek postęp w tym obszarze.\\nKażda próba przeprowadzania zajęć według innych zasad lub w innych warunkach (często\\nnawet lepszych z punktu widzenia efektywności procesu szkolenia), traktowana jest jako\\nnaruszenie przepisów o szkoleniu, co może się skończyć odebraniem uprawnień osobom\\nprowadzącym szkolenie lub likwidacją ośrodka szkolenia.\\nDlatego też, w ocenie TLP, w przepisach projektu ustawy należałoby wprowadzić\\nmożliwość wdrażania indywidualnych/pilotażowych programów szkolenia, realizowanych\\nna zasadach i warunkach stanowiących odstępstwo od wymagań określonych w\\nprzepisach wykonawczych.\\nAby zachować kontrolę nad wdrażaniem tego typu programów (i zagwarantować realizację\\nokreślonych w ustawie celów szkolenia), takie programy mogłyby być wdrażane za zgodą\\nprojektowanego „centrum egzaminowania”, po złożeniu odpowiedniego wniosku przez\\nzainteresowany ośrodek szkolenia kierowców. Oczywiście po uprzedniej korekcji założeń\\nfunkcjonowania tego centrum tak, aby usunąć wszystkie, wskazane dalej w opinii TLP,\\nproblemy o charakterze prawnym.\\nDoświadczenia z takich indywidualnych/pilotażowych programów mogłyby stanowić\\ndoskonały materiał do wykorzystania w przyszłych zmianach polskiego systemu szkolenia.\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n8) Wprowadzenie jednolitych, powszechnie stosowanych standardów nauczania i\\nsprawdzania kwalifikacji kierowców\\nPodczas sprawdzania kwalifikacji osób ubiegających się o uprawnienia do kierowania,\\noceniane jako prawidłowe zachowanie kierującego pojazdem, w zakresie przygotowania\\npojazdu do ruchu, techniki kierowania pojazdem, czy też odpowiedniego zachowania (np.\\nsposób obserwacji i reakcji na zmienne warunki ruchu), wynika z wewnętrznych ustaleń w\\ndanym wojewódzkim ośrodku ruchu drogowego, województwie czy też w regionie. Ta\\nuwaga dotyczy oczywiście kwestii nie uregulowanych prawnie.\\nProwadzi to do sytuacji w której używane są niejednolite w skali całego kraju, niejasne\\nkryteria oceny. Przenosi się to na sposób szkolenia kierowców, gdzie naucza się pod kątem\\nwymagań i kryteriów oceny stosowanych w danym WORD-zie, gdzie będzie składać egzamin\\nzainteresowana osoba. Opinia publiczna mówi wprost o szkole krakowskiej, warszawskiej\\netc.  \\f\\n\\nStrona 177 z 219\\n\\nWymaga to - w ocenie TLP – odpowiedniej reakcji. Konieczne jest ustanowienie jednolitych\\nstandardów w zakresie przygotowania pojazdu do ruchu, techniki jazdy i zachowania w\\nruchu drogowym, nauczanych podczas szkolenia i sprawdzanych podczas egzaminu\\npaństwowego. Na zasadach podobnych, jak te obowiązujące w wielu europejskich\\npaństwach. Przykładem może być Wielka Brytania, gdzie podobne standardy ustala Driver\\nand Vehicle Standards Agency (DVSA). Oficjalnym standardem jest National Standard for\\nDriving Cars and Light Vans (Category B), a odpowiadającym mu aktualnym podręcznikiem\\nbranżowym — The Official DVSA Guide to Driving – the Essential Skills. W przypadku techniki\\njazdy punktem odniesienia jest natomiast Roadcraft: The Police Driver’s Handbook.\\nProponujemy, aby nadać podobne kompetencje (tworzenia obowiązujących standardów)\\nproponowanemu w projekcie Centrum Egzaminowania . Krytycznie oceniamy natomiast\\nznajdujące się w tekście opiniowanego projektu rozwiązanie przypisujące szereg zadań w\\nzakresie ustalania celów szkolenia i egzaminowania. Cele powinny określać normy prawne!\\nNatomiast Centrum powinno się zajmować określaniem szczegółowych sposobów ich\\nosiągania (wytyczne, standardy, podręczniki etc.).\\n\\nUwaga\\ndodatkowa\\n\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n\\n9) Ułatwienia dla cudzoziemców podczas egzaminu państwowego i testu kwalifikacyjnego\\nCoraz więcej cudzoziemców spoza Unii Europejskiej przebywających na terytorium\\nRzeczypospolitej Polskiej podejmuje pracę na rzecz polskiej gospodarki. Znaczna część z tych\\nosób, do wykonywania zadań służbowych związanych z pracą zawodową, potrzebuje\\nuprawnień do kierowania pojazdem. Wśród licznych problemów i barier wskazywanych\\nprzez te osoby oraz przez ich pracodawców, znajduje sią bariera językowa, jaką napotykają\\npodczas egzaminów państwowych sprawdzających kwalifikacje osób ubiegających się o\\nuprawnienia do kierowania pojazdami silnikowymi lub kończącego kwalifikację wstępną\\ntestu kwalifikacyjnego. W innych państwach członkowskich UE rozwiązano ten problem\\ntłumacząc pytania egzaminacyjne nawet na kilkanaście języków, związanych z narodowością\\nosób uzyskujących prawo czasowego lub stałego pobytu na terytorium tych państw.\\nTLP rekomenduje przyjęcie tych dobrych praktyk, poprzez wskazanie dodatkowego zadania\\ndla powoływanego „Centrum Egzaminowania” – opracowywania obcojęzycznych wersji\\npytań, stosowanych podczas egzaminu państwowego oraz podczas testu kwalifikacyjnego\\nkierowców kończących kwalifikację wstępną. Proponowane przez TLP rozwiązanie będzie\\nznacznie mniej kosztowne społecznie, niż zapewnianie udziału w egzaminach tłumaczy\\nprzysięgłych. Przy wyborze języków, na które będą kolejno tłumaczone pytania, należy \\f\\n\\nStrona 178 z 219\\n\\nkierować się m.in. statystykami Głównego Inspektoratu Transportu Drogowego w zakresie\\nwydawanych świadectw kierowców. W tych statystykach ujęta jest bowiem narodowość\\nzagranicznych kierowców zatrudnionych w transporcie drogowym.\\n Uwaga\\ndodatkowa\\nZwiązek\\nPracodawców\\n„Transport i\\nLogistyka\\nPolska”\\n10) Zablokowanie możliwości wydania decyzji o cofnięciu prawa jazdy ze względów\\nformalnych, leżących po stronie instruktora lub ośrodka szkolenia kierowców\\nW obecnym stanie prawnym zdarzają się sytuacje, gdy w postępowaniu administracyjnym\\nodbierane jest (często po wielu latach) prawo jazdy, w przypadku gdy doszło do uchybień\\nprzepisów ustawy o kierujących pojazdami po stronie ośrodka szkolenia kierowców lub po\\nstronie instruktora prowadzącego szkolenie (bez winy lub bez udziału posiadacza prawa\\njazdy). Prawo jazdy jest odbierane, pomimo że kierowca zdał egzamin państwowy na prawo\\njazdy i następnie bezpiecznie (bezwypadkowo) i zgodnie z prawem (bez popełniania\\nnaruszeń), korzystał z tego uprawnienia. Często dotyczy to osób, które podjęły po uzyskania\\nprawa jazdy pracę zawodową, jako kierowcy, która to praca stanowi jedyne źródło\\nutrzymania dla nich i dla ich rodzin. Takie decyzje (o odebraniu prawa jazdy) są formalnie\\nzgodne z prawem, ale w oczywisty sposób krzywdzą osobę zainteresowaną (są\\nniesprawiedliwe, gdyż ta osoba nie miała wpływu na naruszenie OSK) i są bezsensowne z\\npunktu widzenia celu polskich przepisów o szkoleniu i egzaminowaniu, jakim jest\\nbezpieczeństwo ruchu drogowego (jeżdżą zgodnie z prawem i na dodatek bezwypadkowo).\\nDlatego też proponujemy w art. 72 UoKP po ust. 1 dodanie ust. 1a–1e w brzmieniu:\\n„1a. Egzaminu państwowego przeprowadzonego z wynikiem pozytywnym nie unieważnia się\\nz przyczyn określonych w ust. 1 pkt 1 lub 3, jeżeli łącznie są spełnione następujące warunki:\\n1) przyczyna unieważnienia wynika wyłącznie z naruszenia przepisów dotyczących uprawnień\\npodmiotu prowadzącego szkolenie, uprawnień instruktora lub wykładowcy albo organizacji,\\nzakresu, sposobu przeprowadzenia lub dokumentowania szkolenia;\\n2) naruszenia dopuścił się podmiot prowadzący szkolenie, osoba zarządzająca tym\\npodmiotem, instruktor, wykładowca albo inna osoba działająca w ich imieniu;\\n3) osoba egzaminowana nie spowodowała naruszenia, nie uczestniczyła w nim umyślnie oraz\\nnie wiedziała i przy zachowaniu należytej staranności nie mogła wiedzieć o jego wystąpieniu;  \\f\\n\\nStrona 179 z 219\\n\\n4) przebieg egzaminu państwowego był zgodny z przepisami regulującymi sposób jego\\nprzeprowadzania, a ujawnione nieprawidłowości nie miały wpływu na jego wynik.\\n\\n1b. Nie domniemywa się wiedzy ani umyślnego udziału osoby egzaminowanej w naruszeniu,\\no którym mowa w ust. 1a. Okoliczności wyłączające zastosowanie ust. 1a wykazuje organ\\nprowadzący postępowanie. 11\\n\\n1c. Niezależnie od ust. 1a, egzaminu państwowego przeprowadzonego z wynikiem\\npozytywnym nie można unieważnić z przyczyn określonych w ust. 1 pkt 1 lub 3 po upływie\\ndwóch lat od dnia jego przeprowadzenia, chyba że osoba egzaminowana umyślnie\\ndoprowadziła do powstania przyczyny unieważnienia albo popełniła przestępstwo lub\\numyślnie uczestniczyła w przestępstwie pozostającym w związku z dopuszczeniem jej do\\negzaminu lub uzyskaniem jego wyniku.\\n1d. W przypadkach określonych w ust. 1a lub 1c egzamin państwowy zachowuje ważność, a\\nuchybienie dotyczące szkolenia lub jego dokumentowania nie może stanowić podstawy\\nodmowy wydania prawa jazdy ani wznowienia postępowania, uchylenia, zmiany,\\nstwierdzenia nieważności lub wygaśnięcia decyzji o wydaniu prawa jazdy.”.\\nPonadto proponujemy dodatkowy przepis przejściowy w brzmieniu:\\n„Art. x. 1. Do postępowań administracyjnych i sądowoadministracyjnych w sprawie\\nunieważnienia egzaminu państwowego albo dotyczących decyzji o wydaniu prawa jazdy,\\nwszczętych i niezakończonych przed dniem wejścia w życie niniejszej ustawy, stosuje się art.\\n72 ust. 1a–1e ustawy zmienianej w art. 1 w brzmieniu nadanym niniejszą ustawą.\\n2. Postępowanie zakończone przed dniem wejścia w życie niniejszej ustawy ostateczną\\ndecyzją o unieważnieniu egzaminu państwowego albo o uchyleniu, zmianie, stwierdzeniu\\nnieważności lub wygaśnięcia decyzji o wydaniu prawa jazdy w okolicznościach określonych w\\nart. 72 ust. 1a lub 1c ustawy zmienianej w art. 1, wznawia się na żądanie strony.\\n3. Żądanie, o którym mowa w ust. 2, wnosi się w terminie 12 miesięcy od dnia wejścia w\\nżycie niniejszej ustawy. Do wznowienia stosuje się odpowiednio art. 145–152 ustawy z dnia\\n14 czerwca 1960 r. - Kodeks postępowania administracyjnego, z wyłączeniem terminów\\nokreślonych w art. 146 tego Kodeksu.”.  \\f\\n\\nStrona 180 z 219\\n\\n Uwaga\\ndodatkowa do\\nart. 11 ust. 1a\\nustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\n1a. Osoba ubiegająca się o wydanie prawa jazdy najpóźniej w dniu osobistego odbioru prawa\\njazdy we właściwym organie wydającym prawo jazdy, planowanego przekazania prawa jazdy\\nza pośrednictwem operatora pocztowego lub w dniu przystąpienia do egzaminu\\npaństwowego, o którym mowa w art. 49 ust. 1 pkt 1 w zakresie kategorii AM, A1, A2, A, B1,\\nB, B+E lub T:\\n1) spełnia wymagania, o których mowa w ust. 1 pkt 5,\\n2) uprzedzona o odpowiedzialności karnej za zeznanie nieprawdy lub zatajenie prawdy\\nskłada oświadczenie pod rygorem odpowiedzialności karnej za składanie fałszywych\\noświadczeń, że posiada miejsce zamieszkania, o którym mowa w ust. 1 pkt 5.\\n1b. Składający oświadczenie, o którym mowa w ust. 1a pkt 2, jest obowiązany do zawarcia w\\nnim klauzuli następującej treści: \\\"Świadomy odpowiedzialności karnej za złożenie fałszywego\\noświadczenia, wynikającej z art. 233 § 6 Kodeksu karnego, oświadczam, że posiadam na\\nterytorium Rzeczypospolitej Polskiej miejsce zamieszkania, o którym mowa w art. 11 ust. 1\\npkt 5 ustawy z dnia 5 stycznia 2011 r. o kierujących pojazdami.\\\" Klauzula ta zastępuje\\npouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń.\\\",\\n\\nUzasadnienie:\\nZ uzasadnienia  projektu do  ustawy o zmianie ustawy Prawo o ruchu drogowym oraz\\nniektórych innych ustaw  – jednoznacznie wynikało, że zmiana przepisu w zakresie\\nobowiązku składania oświadczenia miała dotyczyć wymiany zagranicznych praw jazdy.\\nProponowane rozwiązanie miało na celu  usprawnienie procedury wydawania polskiego\\nprawa jazdy na podstawie prawa jazdy zagranicznego. Projektowana zmiana dopuszczała\\nzłożenie wniosku o wydanie prawa jazdy przed spełnieniem wymogu rezydencji.\\n\\n Biorąc pod uwagę, że wprowadzone zmiany odnoszą się do wszystkich osób nie  tylko\\nubiegających się  o wymianę zagranicznego prawa jazdy , ale  również o wydanie prawa\\njazdy kategorii AM,A1,A2, A, B1,B,B+E lub T, zachodzi potrzeba doprecyzowania\\nzmienionego przepisu.\\n\\nNasuwają się wątpliwości:\\n W jaki sposób odebrać oświadczenie pod odpowiedzialnością karną o posiadaniu\\nmiejsca zamieszkania o którym mowa w ust. 1 pkt 5 w przypadku planowanego\\nprzekazania prawa jazdy wnioskodawcy za pośrednictwem operatora pocztowego , \\f\\n\\nStrona 181 z 219\\n\\njeżeli osoba ubiegająca się o wydanie prawa jazdy nie złoży takiego oświadczenia w\\ndniu przystąpienia do egzaminu? Brak podstawy prawnej do odmowy\\nprzeprowadzenia egzaminu. Brak podstawy prawnej do wydania decyzji o nadaniu\\nuprawnienia do kierowania pojazdami.\\n Czy ww. oświadczenie będzie składane w dniu egzaminu przed osobą\\nprzeprowadzającą egzamin?\\n W jaki sposób oświadczenie złożone przed egzaminatorem zostanie przekazane do\\norganu wydającego uprawnienia do kierowania pojazdami?\\n Czy oświadczenie złożone przed egzaminatorem, w przypadku jego przekazania do\\norganu ewidencyjnego będzie zwalniało organ z ponownego odebrania od Strony ww.\\noświadczenia w przypadku odbioru osobistego prawa jazdy lub przekazania\\ndokumentu za pośrednictwem operatora pocztowego?\\n Czy WORD może odmówić przeprowadzenia egzaminu osoby, która nie złoży\\noświadczenia o miejscu zamieszkania w trybie art. 233 k.k.\\n Czy można ujednolicić zapis dotyczący składanych oświadczeń w trybie art. 233 k.k.\\ndo jednej klauzuli w brzmieniu „Świadomy odpowiedzialności karnej za złożenie\\nfałszywego oświadczenia, wynikającej z art. 233 § 6 Kodeksu karnego” zamiast\\n„uprzedzona o odpowiedzialności karnej za zeznanie nieprawdy lub zatajenie prawdy\\nskłada oświadczenie pod rygorem odpowiedzialności karnej za składanie fałszywych\\noświadczeń”\\n Różnica pomiędzy dotychczasowym sformułowaniem, że „miejsce zamieszkania\\nznajduje się na terytorium”, a nowym brzmieniem „ posiada miejsce zamieszkania”\\nZmiana wzoru wniosku o wydanie prawa jazdy\\n\\n Uwaga\\ndodatkowa do\\nart. 13 ust. 1\\npkt 8 ustawy o\\nkierujących\\npojazdami\\nUnia Metropolii\\nPolskich im.\\nPawła\\nAdamowicza\\nStarosta z urzędu unieważnia wpis kodu 95 w prawie jazdy po uzyskaniu informacji o\\ncofnięciu świadectwa kwalifikacji zawodowej, na podstawie którego ten wpis został\\ndokonany, oraz:\\n1) informuje posiadacza prawa jazdy o unieważnieniu wpisu, w szczególności o dacie\\nunieważnienia wpisu kodu i obowiązku wymiany prawa jazdy w terminie 60 dni od dnia\\nunieważnienia wpisu;\\n2) przekazuje zaktualizowane dane prawa jazdy do centralnej ewidencji kierowców.\\n\\nUzasadnienie: \\f\\n\\nStrona 182 z 219\\n\\nJak możliwe jest unieważnienie samego wpisu kodu 95 w prawie jazdy bez unieważnienia\\ncałego dokumentu?\\n\\nCo w sytuacji, gdy osoba, której unieważniono wpis kodu 95 nie odbierze o tym informacji, a\\nwykonuje przewóz drogowy?\\n Uwagi\\ndodatkowe\\nKrajowe\\nStowarzyszenie\\nDyrektorów\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nZagadnienia wymagające pilnego podjęcia prac\\n i wprowadzenia zmian przy okazji procedowanego projektu:\\n\\n1. Art. 51 ust. 3 pkt 2- skreślenie zapisu o drogach publicznych;\\n\\n2. Art. 55 ust. 3. Dodanie zapisu dotyczącego przerwania egzaminu praktycznego w\\nprzypadku nieprawidłowego prowadzenia przez kandydata na egzaminatora -na dzień\\ndzisiejszy kandydat na egzaminatora w ramach praktyk ma „przeprowadzić” a nigdzie\\nnie ma zapisu o prawidłowym przeprowadzeniu egzaminów;\\n\\n3. Art. 56a – wprowadzenie corocznej waloryzacji wysokości opłat za prowadzenie\\negzaminów państwowych o wskaźnik inflacji ogłaszany przez GUS. Dodatkowo\\nnależałoby rozważyć waloryzacje opłat za inne szkolenia prowadzone przez WORDy\\noraz powrót do stawek jednolitych na terenie całej Polski;\\n\\n4.  Art. 56c – wprowadzenie podpunktu dotyczącego corocznej waloryzacji wynagrodzeń\\negzaminatorów przeprowadzających egzaminy państwowe o wskaźnik inflacji\\nogłaszany przez GUS;\\n\\n5. Art. 58 ust. 1 pkt 1 – przywrócenie zapisu dotyczącego wykształcenia wyższego i\\ndodatkowo rozważenie podniesienia wymagania z pkt 2 np. na 5 lat posiadania prawa\\njazdy. Powrót wykształcenia wyższego podniósłby kompetencje egzaminatorów;\\n\\n6. Art. 58 ust. 1 pkt 8 – doprecyzowanie przepisów dotyczących rękojmi należytego\\nwykonywania swoich obowiązków. Na dzień dzisiejszy przepis jest martwy a\\negzaminatorzy chronieni przez Związki Zawodowe czują się bezkarni; \\f\\n\\nStrona 183 z 219\\n\\n7. Art. 59 wprowadzenie pkt 5) o treści: B jest uprawniony do egzaminowania w zakresie\\nprawa jazdy kat AM w przypadku egzaminu realizowanego czterokołowcem lekkim –\\negzamin AM czterokołowcem lekkim w praktyce, poza czasem, wygląda jak egzamin w\\nzakresie kategorii B1 oraz B a na dzień dzisiejszy WORD-y są zobowiązane do\\nzapewnienia egzaminatora z uprawnieniami do kategorii A;\\n\\n8. Art. 61 ust. 3 pkt 3 – modyfikacja zapisu zmniejszająca wymaganie dotyczące\\nuczestnictwa w charakterze obserwatora egzaminów teoretycznych do 10 z\\nrównoczesnym podniesieniu do 30 w przypadku egzaminów praktycznych. Dodanie\\nzapisu dotyczącego prawidłowego przeprowadzenia 10 egzaminów - na dzień dzisiejszy\\negzaminatorem może zostać osoba, która w ramach praktyk nie przeprowadziła\\nprawidłowo ani jednego egzaminu;\\n\\n9. Art. 62 ust. 1 – dodanie legitymacji egzaminatora do mObywatela;\\n\\n10. Art. 64 – określenie zasad wynagradzania komisji weryfikacyjnej;\\n\\n11. § 27. ust. 2 określenie możliwości oceny egzaminu na kat AM realizowanego\\nczterokołowcem lekkim na tych samych zasadach co motorowerem jednośladowym w\\nprzypadku gdy ilość miejsca uniemożliwia egzaminatorowi odpowiednie warunki\\nprzebywania w pojeździe.\\nNa rynku czterokołowców lekkich przybywa pojazdów zarówno trój jak i\\nczterokołowych, spełniających warunki homologacji L6e, w których miejsce dla\\npasażera znajduje się za kierowcą. Obecny formalny zapis rozporządzenia wskazuje na\\nkonieczność przeprowadzenia takiego egzaminu przez egzaminatora będącego\\nw pojeździe. W takim przypadku egzaminator nie jest w stanie zapewnić\\nbezpieczeństwa gdyż nie ma dostępu do mechanizmów sterowania pojazdem jak\\ni siedząc z tyłu nie posiada dostatecznej widoczności. W dniu 18 kwietnia 2025 r.\\nDepartament Transportu Drogowego Ministerstwa Infrastruktury pismem znak:\\nDTD-5-1.4411.229.2025 w odpowiedzi na zapytanie jednego z producentów tego typu \\f\\n\\nStrona 184 z 219\\n\\npojazdów wyraził opinię w przedmiotowej sytuacji. Zdaniem MI egzaminator w takich\\nsytuacjach ma prawo odmówić jazdy w pojeździe egzaminacyjnym, lecz jest to\\nocena/opinia a nie zapis w rozporządzeniu.\\n\\n12.  Wprowadzenie obowiązkowych zajęć w ośrodku doskonalenia techniki jazdy w\\nramach szkolenia podstawowego lub powrót do planowanego a ostatecznie\\nwykreślonego szkolenia miedzy 4 a 8 – kształtowanie właściwych postaw przyszłego\\nkierującego pod kątem właściwego przygotowania pojazdu do jazdy, warunków\\ndecydujących o zachowaniu pojazdu w warunkach specjalnych (nawierzchnia o różnej\\nprzyczepności).\\n\\n Uwagi\\ndodatkowe\\nOIGOSK,\\nLFEDERACJA,\\nPIGOSK\\nII. W Ustawie z 5 stycznia 2011 o kierujących pojazdami, proponujemy:\\n\\n1. w art. 6 ust. 2 otrzymuje brzmienie:\\n„2. Zespołem pojazdów, o którym mowa w ust. 1 pkt 6 lit. c, którego dopuszczalna masa\\ncałkowita przekracza 3,5 t, może kierować osoba, która odbyła wymagane szkolenie i zdała\\nczęść praktyczną egzaminu państwowego, potwierdzoną wpisem do prawa jazdy”\\n\\nUzasadnienie Art.10 ust.1 lit. d Dyrektywy Parlamentu Europejskiego i Rady (UE) 2025/2205\\nDziennik Urzędowy Unii Europejskiej ser. L Przewiduje trzy warianty do wyboru Państwom\\nczłonkowskim: 1) Tylko szkolenie, 2) Tylko egzamin praktyczny, 3) Szkolenie + egzamin\\npraktyczny Zdawalność dotychczas prowadzonych egzaminów państwowych bez obowiązku\\nodbycia szkolenia jest żenująco niska i wynosi ok. 20%. Wielokrotne zdawanie egzaminu\\npaństwowego generuje dla obywateli znaczące wydatki (aktualnie ok. 250 PLN/egzamin)\\noraz koszty społeczne ( np. konieczność podróży do WORD, absencja w pracy itp.)\\n\\n2. w art. 23 ust.2 pkt.2 dodaje się lit. d w brzmieniu: „d) na drodze ekspresowej lub\\nautostradzie – dotyczy prawa jazdy kat. B, C, CE, D;”\\n\\nUzasadnienie Należy wprowadzić obowiązek szkolenia na drogach ekspresowych lub\\nautostradach w zakresie kat. B, C, CE, D prawa jazdy. Nie może dłużej trwać sytuacja, gdzie\\nwiele osób uzyskujących uprawnienia po raz pierwszy w życiu wyjeżdża na taką drogę po\\nzdaniu egzaminu bez wcześniejszego praktycznego przygotowania. Wiele osób popełnia \\f\\n\\nStrona 185 z 219\\n\\nbłędy niewłaściwego korzystania z pasu rozbiegowego, niewłaściwego zjazdu, wyprzedzania,\\nutrzymywania odstępu, ewentualnego zawracani (korzystania z węzłów), te umiejętności\\nchociaż nie egzekwowane na egzaminie państwowym powinny być jak najszybciej\\nwprowadzone do programu szkolenia. Rozporządzeniem należy wprowadzać okresy\\nprzejściowe czy wyłączenia z obowiązku szkolenia na takiej drodze jeżeli odległość osk od\\nnajbliższej drogi ekspresowej lub autostrady jest większa niż np. 50 km. Jednak przy\\ndopuszczeniu możliwości realizacji z jednym kursantem jednorazowo 4 godz. zajęć szkolenie\\nna drogach szybkiego ruchu można z powodzeniem realizować na terenie całego kraju.\\n\\n 3. w art. 24 pkt.1 lit. b otrzymuje brzmienie: „b) oznakowanym kwadratową tablicą barwy\\nniebieskiej z białą literą „L” – nie dotyczy motocykla dwukołowego i motoroweru\\ndwukołowego. Dopuszcza się oznakowanie samochodu osobowego kwadratową nalepką\\nbarwy niebieskiej z białą literą „L”,”\\n\\nUzasadnienie W przypadku szkolenia / egzaminowania na prawo jazdy kategorii AM, A1, A2 i\\nA zasadnym jest odstąpienie od obowiązku oznaczania pojazdu jednośladowego tablicą z\\nliterą „L” na rzecz obowiązkowej kamizelki odblaskowej z wyraźnie umieszczoną literą „L”, w\\nktórą ubrana jest osoba szkolona/ egzaminowana.. • Poprawa bezpieczeństwa ruchu\\ndrogowego – litera „L” umieszczona na kamizelce odblaskowej jest widoczna z przodu, z tyłu\\noraz z boków motocyklisty, dzięki czemu pozostali uczestnicy ruchu wcześniej rozpoznają, że\\nmają do czynienia z osobą uczącą się jazdy. • Lepsza widoczność – kamizelka odblaskowa\\nzwiększa widoczność motocyklisty zarówno w dzień, jak i po zmroku, co ma większy wpływ\\nna bezpieczeństwo niż niewielka tablica zamocowana z tyłu motocykla. • Brak możliwości\\nbezpiecznego montażu – wiele motocykli, szczególnie nowoczesnych, nie posiada\\nkonstrukcyjnych możliwości trwałego i bezpiecznego zamocowania tablicy „L”. Stosowane\\nuchwyty mogą ulec uszkodzeniu lub odpaść podczas jazdy. • Ochrona motocykla – montaż\\ndodatkowych uchwytów często wymaga ingerencji w elementy konstrukcyjne, co może\\nprowadzić do uszkodzeń pojazdu i utraty jego walorów użytkowych. • Mniejsze ryzyko\\nzagrożenia – wystające elementy mocujące tablicę mogą stanowić dodatkowe zagrożenie\\npodczas wywrotki lub kolizji. • Łatwość kontroli – kamizelka z literą „L” jest łatwa do\\nzweryfikowania przez organy kontrolne, a jednocześnie nie wymaga dodatkowego\\nwyposażenia motocykla. • Praktyka europejska – w wielu państwach europejskich \\f\\n\\nStrona 186 z 219\\n\\nstosowane są rozwiązania polegające na oznaczaniu osoby szkolonej specjalną kamizelką lub\\nodzieżą z odpowiednim oznaczeniem, bez konieczności montowania tablic na motocyklu\\n\\n4. w art.36 dodaje się ust.3 w brzmieniu: „3. Legitymacja instruktora może być udostępniana\\nw postaci dokumentu mobilnego, o którym mowa w art. 2 pkt 7 ustawy z dnia 26 maja 2023\\nr. o aplikacji mObywatel.”\\n\\nUzasadnienie Pozytywne rozpatrzenie propozycji wyeliminowałoby uciążliwe perturbacje\\ndotykające również liczne rzesze osób szkolonych ( np. wykluczenie obecności instruktora na\\negzaminie państwowym) w razie zagubienia, zniszczenia czy zapomnienia zabrania fizycznej\\npostaci legitymacji instruktora Ponadto pożądane upowszechnienie się postaci mobilnej w/w\\ndokumentów – perspektywicznie umożliwiłoby wydawanie ich postaci fizycznej wyłącznie na\\nwniosek osoby. W takich okolicznościach znacząco zostałyby zmniejszone wydatki organów\\newidencyjnych administracji publicznej zobowiązanych do nieodpłatnego wydawania\\nomawianych dokumentów w okolicznościach np. zmiany wzorców, zmian granic\\nadministracyjnych, zmian nazw itp.\\n\\n 5. w art. 45 ust. 4 uchyla się 4. Decyzja, o której mowa w ust. 1, podlega\\nnatychmiastowemu wykonaniu /zakaz wykonywania działalności OSK/\\n\\nUzasadnienie Naszym zdaniem nie znajdujemy uzasadnienia faktycznego i merytorycznego\\ndla zastosowania tak drastycznej sankcji. Ponadto rygor natychmiastowej wykonalności\\ndecyzji o zakazie prowadzenia działalności gospodarczej w zakresie OSK przede wszystkim\\njest bardzo dolegliwy dla osób szkolonych, które w takich okolicznościach są zmuszone do\\nnagłego poszukiwania innych OSK\\n\\n6. w art. 53 ust. 4a otrzymuje brzmienie: „4a. Praktyczna część egzaminu państwowego na\\nwniosek osoby egzaminowanej, jest prowadzona wskazanym pojazdem ośrodka szkolenia\\nkierowców, który prowadził szkolenie tej osoby.”\\n\\nUzasadnienie Naszym zdaniem nie ma przeszkód faktycznych i merytorycznych aby\\npraktyczna część egzaminu państwowego w zakresie każdej kategorii prawa jazdy - na\\nwniosek osoby egzaminowanej mogła być prowadzona wskazanym pojazdem ośrodka \\f\\n\\nStrona 187 z 219\\n\\nszkolenia kierowców, który prowadził szkolenie tej osoby. Niniejsza propozycja uzasadniona\\njest również statystykami, które obiektywnie, bo empirycznie dowodzą wyższej zdawalności\\negzaminów prowadzonych pojazdami OSK oraz wyraźnej tendencji rosnącej % udziału tych\\negzaminów w liczbie egzaminów danej kategorii prawa jazdy, vide przywołane zobrazowania\\ngraficzne.\\n\\n7. w art. 53 ust. 5 otrzymuje brzmienie: „5. Wojewódzkie ośrodki ruchu drogowego,\\nprzeprowadzając postępowanie o udzielenie zamówienia publicznego, którego przedmiotem\\nsą pojazdy do przeprowadzania praktycznej części egzaminu na prawo jazdy przygotowując\\ndokumenty zamówienia i powołując komisję przetargową, włączają do prac przedstawicieli\\nregionalnych organizacji zrzeszających ośrodki szkolenia kierowców, na ich wniosek, a w\\nrazie braku takich organizacji – przedstawicieli ogólnopolskich organizacji zrzeszających\\nośrodki szkolenia kierowców, wyrażających wolę wzięcia udziału w postępowaniu. Umowa w\\nsprawie zamówienia publicznego na pojazdy jest zawierana przez wojewódzkie ośrodki\\nruchu drogowego na okres nie krótszy niż 4 lata.”\\n\\nUzasadnienie W środowisku dyrektorów WORD-ów spotykamy się ze stanowiskiem, które\\nskutkuje akceptacją wniosku o włączenie przedstawicieli organizacji zrzeszających ośrodki\\nszkolenia kierowców do postępowania o udzielenie zamówienia publicznego, którego\\nprzedmiotem są pojazdy do przeprowadzania praktycznej części egzaminu na prawo jazdy\\nwyłącznie alternatywnie tj. włącza się tych przedstawicieli tylko na etapie przygotowywania\\ndokumentów zamówienia albo tylko na etapie prac komisji przetargowej. Wielu dyrektorów\\ndopuszcza przedstawicieli organizacji zrzeszających osk do wszystkich etapów postępowania\\no udzielenie zamówienia publicznego, którego przedmiotem są pojazdy do przeprowadzania\\npraktycznej części egzaminu na prawo jazdy. Naszym zdaniem przedstawiciele organizacji\\nzrzeszających ośrodki szkolenia kierowców powinni uczestniczyć w każdym etapie\\npostępowania o udzielenie zamówienia publicznego, którego przedmiotem są pojazdy do\\nprzeprowadzania praktycznej części egzaminu na prawo jazdy.\\n\\n8. w art. 56a ust. 2 otrzymuje brzmienie: „2. W uchwale, o której mowa w ust.1, uwzględnia\\nsię koszty rzeczowe i osobowe związane z przeprowadzaniem egzaminów państwowych, w\\ntym pojazdem innego dysponenta, niż określony w art.53 ust.1.”\\n \\f\\n\\nStrona 188 z 219\\n\\nUzasadnienie WORD-y nie posiadając pojazdów do prowadzenia egzaminów lub\\nprowadzonych pojazdem innego dysponenta w trybie przepisów art.53 ust.4 i ust.4a ustawy\\no kierujących pojazdami tj. prowadzenia egzaminu państwowego na prawo jazdy: 1)\\npojazdem bez pedału (dźwigni) sprzęgła, jeżeli nie jest to pojazd będący w dyspozycji\\nwojewódzkiego ośrodka ruchu drogowego [ art.54 ust.5 pkt.2 w związku z art.53 ust.4 pkt.1\\nuokp], 2) pojazdami, którymi prowadzi się egzamin w zakresie uprawnień prawa jazdy\\nkategorii B1, C1, C1+E, C, C+E, D1, D1+E, D lub D+E [art.53 ust.4 pkt.2 uokp], 3) pojazdami\\nośrodka szkolenia kierowców, który prowadził szkolenie tej osoby w zakresie prawa jazdy\\nkategorii AM, A1, A2, A, B, kod B96 i B+E [art.53 ust.4a uokp]. nie ponoszą kosztów\\neksploatacyjnych i wszystkich innych kosztów związanych z nabyciem i posiadaniem\\npojazdu (amortyzacja, ubezpieczenia, obsługi codzienne, mycie, sprzątanie, tankowanie,\\ngarażowanie lub parking strzeżony, okresowe badania i obsługi techniczne itp.) - niemałych\\nszczególnie w obecnym czasie wysokich cen materiałów i usług. Niestety uchwały sejmików\\nwojewódzkich nie uwzględniają w/w obiektywnych okoliczności dlatego konieczna jest\\nodpowiednia regulacja ustawowa, o która niniejszym wnosimy.\\n Uwagi\\ndodatkowe\\nOIGOSK,\\nLFEDERACJA,\\nPIGOSK\\nIII. W ustawie z 20 czerwca 1997 Prawo o ruchu drogowym, proponujemy:\\n\\n1. w art. 55 a) ust.1 otrzymuje brzmienie: „1. Pojazd do nauki jazdy lub przeprowadzania\\negzaminu państwowego oznacza się tablicą kwadratową barwy niebieskiej z białą literą „L”,\\numieszczoną na pojeździe – nie dotyczy motocykla dwukołowego i motoroweru\\ndwukołowego. W warunkach niedostatecznej widoczności tablica umieszczona na pojeździe\\npowinna być oświetlona. Podczas prowadzenia nauki jazdy lub egzaminu państwowego\\nmotocyklem dwukołowym lub motorowerem dwukołowym osoba kierująca takim pojazdem\\npowinna być ubrana w kamizelkę z umieszczoną na niej tablicą kwadratową barwy\\nniebieskiej z białą literą „L” wykonanych z materiału odblaskowego”\\n\\nUzasadnienie: • Poprawa bezpieczeństwa ruchu drogowego – litera „L” umieszczona na\\nkamizelce odblaskowej jest widoczna z przodu, z tyłu oraz z boków motocyklisty, dzięki\\nczemu pozostali uczestnicy ruchu wcześniej rozpoznają, że mają do czynienia z osobą uczącą\\nsię jazdy. • Lepsza widoczność – kamizelka odblaskowa zwiększa widoczność motocyklisty\\nzarówno w dzień, jak i po zmroku, co ma większy wpływ na bezpieczeństwo niż niewielka\\ntablica zamocowana z tyłu motocykla. • Brak możliwości bezpiecznego montażu – wiele\\nmotocykli, szczególnie nowoczesnych, nie posiada konstrukcyjnych możliwości trwałego i \\f\\n\\nStrona 189 z 219\\n\\nbezpiecznego zamocowania tablicy „L”. Stosowane uchwyty mogą ulec uszkodzeniu lub\\nodpaść podczas jazdy. • Ochrona motocykla – montaż dodatkowych uchwytów często\\nwymaga ingerencji w elementy konstrukcyjne, co może prowadzić do uszkodzeń pojazdu i\\nutraty jego walorów użytkowych. • Mniejsze ryzyko zagrożenia – wystające elementy\\nmocujące tablicę mogą stanowić dodatkowe zagrożenie podczas wywrotki lub kolizji. •\\nŁatwość kontroli – kamizelka z literą „L” jest łatwa do zweryfikowania przez organy\\nkontrolne, a jednocześnie nie wymaga dodatkowego wyposażenia motocykla. • Praktyka\\neuropejska – w wielu państwach europejskich stosowane są rozwiązania polegające na\\noznaczaniu osoby szkolonej specjalną kamizelką lub odzieżą z odpowiednim oznaczeniem,\\nbez konieczności montowania tablic na motocyklu.\\n\\n b) Dodaje się ust. 1a w brzmieniu: „1a. Pojazd wykorzystywany do nauki jazdy lub\\nprzeprowadzania egzaminu państwowego prawa jazdy kat. B może być oznaczony w sposób\\nopisany w ust. 1 lub zamiennie kwadratową nalepką barwy niebieskiej z białą literą „L” na\\nprzedniej i tylnej szybie pojazdu w sposób nie ograniczający widoczności osobie szkolonej i\\ninstruktorowi.\\n\\nUzasadnienie Podczas szkolenia na drogach ekspresowych i autostradach a także na drogach\\npoza obszarem zabudowanym stosowanie tablicy „L” o wymiarach 30 x30 cm na dachu\\npojazdu generuje niebezpieczeństwo dla innych uczestników ruchu, gdyż napór powietrza\\nna tak dużą powierzchnię niekiedy zrywa z dachu pojazdu tablice „L” powodując zagrożenie\\npowstaniem poważnego wypadku drogowego. W wielu państwach samochody nauki jazdy\\nsą oznaczone poprzez nalepki z różnymi symbolami i jest to z powodzeniem stosowane bez\\nuszczerbku dla bezpieczeństwa. Z racji przyzwyczajenia do symbolu niebieskiej „L” dla\\npojazdów nauki jazdy- taki symbol o wymiarach np. 10 x 10 cm należałoby zachować –\\nszczegółowe warunki należy określić w Rozporządzeniu w sprawie rejestracji i oznaczania\\npojazdów, wymagań dla tablic rejestracyjnych oraz wzorów innych dokumentów związanych\\nz rejestracją pojazdów\\n Uwaga\\ndodatkowa\\nPolski Związek\\nMotorowy\\nProponowane brzmienie przepisu Ustawy z dnia 20 czerwca 1997 r. - Prawo o ruchu\\ndrogowym (t.j. Dz. U. z 2024 r. poz. 1251 z późn. zm.):\\n\\nArt. 119 Ustawy - Prawo o ruchu drogowym\\n \\f\\n\\nStrona 190 z 219\\n\\nW art. 119 ust. 3 uchyla się pkt 4.\\n\\nArt. 119 ust. 4 otrzymuje brzmienie:\\n\\n„4. Ośrodek ponosi wydatki na działania na rzecz poprawy bezpieczeństwa ruchu drogowego\\nna obszarze województwa, w szczególności na popularyzację zasad ruchu drogowego oraz\\npodnoszenie kultury jazdy kierowców”.\\n\\nPo ust. 4 dodaje się ust. 4a w brzmieniu:\\n\\n„4a. Wydatki, o których mowa w ust. 4, mogą być finansowane ze środków zgromadzonych\\nna funduszu zapasowym ośrodka.”\\n\\nUzasadnienie:\\n\\nProjektowana zmiana ma na celu zwiększenie efektywności wykorzystania środków\\nfinansowych zgromadzonych przez wojewódzkie ośrodki ruchu drogowego oraz wzmocnienie\\nrealizacji ustawowych zadań związanych z poprawą bezpieczeństwa ruchu drogowego w tym\\ndziałań związanych z turniejami Bezpieczeństwa Ruchu Drogowego na szczeblu szkolnym,\\npowiatowym, wojewódzkim jak i krajowym. Działania na rzecz poprawy bezpieczeństwa ruchu\\ndrogowego stanowią jedno z podstawowych zadań wojewódzkich ośrodków ruchu\\ndrogowego, wynikających bezpośrednio z ustawy. Nie mają one charakteru działalności\\ndodatkowej ani fakultatywnej, lecz pozostają integralnym elementem misji publicznej\\nrealizowanej przez te podmioty.\\nObecne przepisy, które określają szczegółowe warunki gospodarki finansowej wojewódzkich\\nośrodków ruchu drogowego są zawarte w Rozporządzeniu Ministra Infrastruktury z dnia 3\\nlipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego\\nośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów\\nzwiązanych z działalnością ośrodka (Dz. U. poz. 1376). Rozporządzenie to zastąpiło poprzednio\\nobowiązujący akt, tj. Rozporządzenie Ministra Infrastruktury z dnia 2 października 2002 r. w\\nsprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu\\ndrogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z\\ndziałalnością ośrodka (Dz. U. Nr 176, poz. 1443) i wprowadziło zmianę w zakresie \\f\\n\\nStrona 191 z 219\\n\\nprzeznaczenia funduszu zapasowego. Zgodnie z treścią § 5 poprzednio obowiązującego\\nRozporządzenia, fundusz zapasowy był przeznaczony do dyspozycji ośrodka na finansowanie\\ndziałalności, o której mowa w art. 117 ust. 1 i 2 ustawy - Prawo o ruchu drogowym (t.j. Dz. U.\\nz 2024 r. poz. 1251), a zatem również na potrzeby szeroko rozumianej działalności oświatowej\\ndot. bezpieczeństwa w ruchu drogowym oraz realizacji innych, doniosłych zadań z zakresu\\ntego bezpieczeństwa. Obecnie natomiast, zgodnie z aktualnym Rozporządzeniem, fundusz\\nzapasowy może być przeznaczony jedynie na pokrycie strat netto ośrodka.  W praktyce\\noznacza to, że środki zgromadzone w funduszu zapasowym pozostają\\nniewykorzystane do czasu wystąpienia ujemnego wyniku finansowego, niezależnie od\\nistniejących potrzeb w zakresie realizacji działań służących poprawie bezpieczeństwa ruchu\\ndrogowego.\\nBrak jest dostatecznego uzasadnienia dla utrzymywania stanu, w którym środki zgromadzone\\nprzez ośrodek pozostają zarezerwowane wyłącznie na pokrycie potencjalnych przyszłych\\nstrat, podczas gdy mogą zostać wykorzystane do realizacji ustawowych zadań służących\\nograniczaniu liczby wypadków drogowych, zwiększaniu świadomości uczestników ruchu\\ndrogowego oraz podnoszeniu poziomu bezpieczeństwa na drogach. Proponowane\\nrozwiązanie wychodzi z założenia, że środki funduszu zapasowego powinny służyć nie tylko\\nochronie stabilności finansowej ośrodka, lecz również wspierać realizację celów publicznych,\\ndla których wojewódzkie ośrodki ruchu drogowego zostały utworzone. Umożliwienie\\nfinansowania działań na rzecz bezpieczeństwa ruchu drogowego ze środków funduszu\\nzapasowego pozwoli na bardziej racjonalne i efektywne gospodarowanie zgromadzonym\\nmajątkiem, przy jednoczesnym zachowaniu bezpieczeństwa finansowego jednostek.\\nPowrót do finansowania wydatków, w części przeznaczonej na poprawę bezpieczeństwa\\nruchu drogowego z funduszu zapasowego, bez wątpienia umożliwiłby zwiększenie\\nskuteczności i efektywności pomocy m.in. placówkom edukacyjno-oświatowym\\nprzygotowującym dzieci i młodzież do świadomego i bezpiecznego udziału w ruchu drogowym\\nna terenie naszego kraju w tym na organizację turniejów bezpieczeństwa ruchu drogowego,\\nktórego między innymi organizatorem jest Polski Związek Motorowy , a ponadto znacząco\\nodciążyłby fundusz z bieżącej działalności ośrodków.\\nNależy jeszcze raz podkreślić, że finansowanie działań na rzecz poprawy bezpieczeństwa ruchu\\ndrogowego ze środków funduszu zapasowego nie stanowi przeznaczenia tych środków na cele\\nniezwiązane z działalnością ośrodka. Przeciwnie, środki te byłyby wykorzystywane na\\nrealizację zadań ustawowo przypisanych wojewódzkim ośrodkom ruchu drogowego. \\f\\n\\nStrona 192 z 219\\n\\nProponowana zmiana prowadzi zatem do silniejszego powiązania sposobu wykorzystania\\nwypracowanych nadwyżek finansowych z podstawowymi celami działalności ośrodków, a tym\\nsamym wzmacnia funkcjonalny związek pomiędzy gospodarką finansową ośrodka, a realizacją\\npowierzonych mu zadań publicznych.\\n\\n Uwaga\\ndodatkowa\\nPolski Związek\\nSzkoleniowy\\nProponujemy wprowadzenie do art. 31 ustawy o kierujących pojazdami następującej\\npoprawki:\\nW art. 31 po ust. 1 dodaje się ust. 1a w brzmieniu:\\n„1a. Przedsiębiorca może nie spełniać wymagań, o których mowa w ust. 1 pkt 3 lit. b, w\\nzakresie prawa jazdy kategorii C, jeśli posiada zespół pojazdów spełniający wymagania dla\\npojazdu szkoleniowego w zakresie prawa jazdy kategorii C+E, składający się ciągnika\\nsiodłowego z naczepą, w którym ciągnik siodłowy jest nie starszy niż 7 lat.”.”\\n\\nOd początku 2026 r. do prowadzenia szkolenia i egzaminowania osób w zakresie prawa jazdy\\nkategorii C+E są wymagane ciągniki siodłowe z naczepą. Oznacza to jednocześnie, że do\\nszkolenia w zakresie prawa jazdy kategorii C będzie potrzebny inny pojazd niż do szkolenia w\\nzakresie prawa jazdy kategorii C+E. Wiele podmiotów prowadzących szkolenia w zakresie\\nprawa jazdy kategorii C i C+E kupiło nowe lub prawie nowe zespoły pojazdów składające się\\nz ciągnika siodłowego z naczepą. Jest to na tyle duże obciążenie finansowe, że w przypadku\\nciężarówki na prawo jazdy kategorii C niektórych podmiotów może nie być stać na zakup\\nkolejnego, młodszego niż 7 lat pojazdu. Dlatego też proponujemy aby pojazd kategorii C+E\\njakim jest ciągnik siodłowy z naczepą, pozwalał także na spełnianie dodatkowych warunków\\nw zakresie pojazdów, dla podmiotu posiadającego lub występującego o poświadczenie\\nspełniania dodatkowych wymagań.\\n\\n Uwaga\\ndodatkowa\\nPolski Związek\\nSzkoleniowy\\n10) Proponujemy wprowadzenie do art. 35 ustawy o kierujących pojazdami następującej\\npoprawki:\\n\\nW art. 35 po ust. 3 dodaje się ust. 3a w brzmieniu:\\n„3a. Zajęcia, o których mowa w ust. 3 pkt. 1, mogą być realizowane przy wykorzystaniu\\nmetod on-line polegających na transmisji w czasie rzeczywistym dźwięku i obrazu między\\nosobą prowadzącą takie zajęcia, a jej uczestnikami.”  \\f\\n\\nStrona 193 z 219\\n\\nProponujemy doprecyzowanie przepisów dotyczących prowadzenia szkolenia instruktorów\\nnauki jazdy. Zgodnie z przepisami ustawy o kierujących pojazdami szkolenia dla instruktorów\\nnauki jazdy mogą prowadzić:\\n1) ośrodek szkolenia kierowców posiadający poświadczenie potwierdzające spełnianie\\ndodatkowych wymagań - odpowiednio do zakresu posiadanego poświadczenia;\\n2) jednostka wojskowa - w zakresie szkolenia instruktorów na potrzeby Sił Zbrojnych\\nRzeczypospolitej Polskiej;\\n3) jednostka organizacyjna służb podległych ministrowi właściwemu do spraw\\nwewnętrznych - w zakresie szkolenia osób na potrzeby tych służb;\\n4) podmiot wykonujący przewozy tramwajem - w zakresie szkolenia instruktorów osób\\nubiegających się o uprawnienie do kierowania tramwajem;\\n5) wojewódzki ośrodek ruchu drogowego spełniający wymagania, o których mowa w art. 31\\nust. 1 pkt 3-5.\\n\\nJednym z przywilejów dla przedsiębiorcy prowadzącego, wymieniony w pkt. 1, ośrodek\\nszkolenia kierowców posiadający poświadczenie potwierdzające spełnianie dodatkowych\\nwymagań jest, zgodnie z art. 26 ust. 2 ustawy, szkolenie osób w formie nauczania na\\nodległość z wykorzystaniem technik komputerowych i Internetu, o którym mowa w art. 23\\nust. 3 ustawy. Jest to przywilej stosowany w przypadku szkolenia kandydatów na kierowców.\\nPodmioty te są od lat przygotowane i odpowiednio wyposażone, aby takie zajęcia w zgodny\\nz prawem sposób prowadzić. W ostatnim czasie niektóre organy nadzoru poddały w\\nwątpliwość możliwość prowadzenia przez te podmioty zajęć teoretycznych dla instruktorów\\nnauki jazdy metodą on-line polegającą na transmisji w czasie rzeczywistym dźwięku i obrazu\\nmiędzy osobą prowadzącą takie zajęcia, a jej uczestnikami. Oczywiście nie jest to metoda\\nzabroniona, ale mając na względzie czystość stanowionego prawa i dążąc do jego jednolitego\\nstosowania proponujemy jednoznaczne wskazanie, że taki ośrodek ma prawo prowadzić\\nczęść teoretyczną szkolenia dla instruktorów nauki jazdy przy pomocy metod on-line\\npolegających na transmisji w czasie rzeczywistym dźwięku i obrazu między osobą\\nprowadzącą takie zajęcia, a jej uczestnikami. Warto zauważyć, że w odróżnieniu od metod e-\\nlearningowych prowadzenie wykładów on-line na żywo nie obniża jakości szkolenia i daje\\nmożliwość pełnej interakcji pomiędzy osobami szkolonymi, a wykładowcą gwarantując\\nodpowiednio wysoką jakość szkolenia i zaangażowanie osób szkolonych.  \\f\\n\\nStrona 194 z 219\\n\\nWprowadzenie tej regulacji otwiera możliwości udziału w kursach dla kandydatów na\\ninstruktorów i instruktorów osobom, które ze względu na rodzaj i system wykonywanej\\npracy były wykluczone z możliwości zdobycia uprawnień instruktora nauki jazdy, w\\nprzeciwieństwie do osób ubiegających się o uprawnienia do kierowania.\\nJednocześnie nie generuje to dodatkowych zobowiązań i obciążeń zarówno po stronie\\nspołecznej (koszt szkolenia dla zainteresowanej osoby nie zwiększa się względem\\nstandardowego szkolenia stacjonarnego, po stronie przedsiębiorcy korzysta się z już\\nwypracowanych technik i sprawdzonego, bezpiecznego oprogramowania, po stronie\\nnadzoru możliwość weryfikacji przeprowadzenia zajęć nie tylko na podstawie ewidencji w\\ndokumentacji, ale również wglądu w zarejestrowane zajęcia, oraz weryfikacji merytoryki i\\nzgodności z programem nauczania – analogicznie jak w przypadku szkolenia dla osób\\nubiegających się o uprawnienia do kierowania) jak i nie stanowi obciążenia dla budżetu.\\n Uwaga\\ndodatkowa\\nPolski Związek\\nSzkoleniowy\\n15) W odniesieniu do art. 3:\\na) pkt 1 otrzymuje brzmienie:\\n\\n1) w art. 2\\na) w pkt 37 po wyrazach „Służbę Więzienną” skreśla się średnik i dodaje się wyrazy „oraz\\npojazdy przeznaczone wyłącznie do nauki jazdy i egzaminowania;”\\nb) po pkt 47c dodaje się pkt 47d w brzmieniu:\\n\\n„47d) mikromobilność dzielona – usługę polegającą na udostępnianiu użytkownikom, w\\nsposób odpłatny lub nieodpłatny, pojazdów lub urządzeń przeznaczonych do\\nindywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów,\\nhulajnóg elektrycznych lub urządzeń transportu osobistego, z wykorzystaniem aplikacji\\nmobilnej lub innego systemu teleinformatycznego umożliwiającego korzystanie z tych\\npojazdów lub urządzeń przez wielu użytkowników;”;\\n\\nUzasadnienie\\nZgodnie z przepisami art. 8 ustawy z dnia 12 stycznia 1991 r. o podatkach i opłatach\\nlokalnych (Dz.U. z 2023 r. poz. 70) Opodatkowaniu podatkiem od środków transportowych\\npodlegają:\\n1) samochody ciężarowe o dopuszczalnej masie całkowitej powyżej 3,5 tony i poniżej 12 ton;\\n2) samochody ciężarowe o dopuszczalnej masie całkowitej równej lub wyższej niż 12 ton;  \\f\\n\\nStrona 195 z 219\\n\\n3) ciągniki siodłowe i balastowe przystosowane do używania łącznie z naczepą lub przyczepą\\no dopuszczalnej masie całkowitej zespołu pojazdów od 3,5 tony i poniżej 12 ton;\\n4) ciągniki siodłowe i balastowe przystosowane do używania łącznie z naczepą lub przyczepą\\no dopuszczalnej masie całkowitej zespołu pojazdów równej lub wyższej niż 12 ton;\\n5) przyczepy i naczepy, które łącznie z pojazdem silnikowym posiadają dopuszczalną masę\\ncałkowitą od 7 ton i poniżej 12 ton, z wyjątkiem związanych wyłącznie z działalnością\\nrolniczą prowadzoną przez podatnika podatku rolnego;\\n6) przyczepy i naczepy, które łącznie z pojazdem silnikowym posiadają dopuszczalną masę\\ncałkowitą równą lub wyższą niż 12 ton, z wyjątkiem związanych wyłącznie z działalnością\\nrolniczą prowadzoną przez podatnika podatku rolnego;\\n7) autobusy.\\n\\nPodatek ten został nałożony na wszystkich posiadaczy ww. środków transportu w założeniu,\\nże pojazdy te wykorzystywane są w mniejszym lub większym stopniu do wykonywania\\nodpłatnego transportu drogowego osób lub rzeczy.\\n\\nWiadomym jest, że wykonywanie takiego transportu, a w szczególności regularny przejazd\\nobciążonymi pojazdami drogami lokalnymi przyczynia się do ich szybszego zużycia i ich\\nprzyspieszonej degradacji. Dlatego też słusznym rozwiązaniem jest podatkowa partycypacja\\nposiadaczy takich pojazdów w budżecie lokalnych samorządów tak aby można było na\\nbieżąco naprawiać i rozwijać lokalna infrastrukturę drogową.\\nJednak ustawodawca zauważył, że w przypadku niektórych pojazdów, w szczególności tych\\nnieużywanych do wykonywania transportu drogowego osób lub rzeczy, podatek ten nie\\npowinien być pobierany. Stanowi o tym art. 12 przedmiotowej ustawy który wskazuje, że:\\n„Art. 12 1. Zwalnia się od podatku od środków transportowych:\\n1) pod warunkiem wzajemności - środki transportowe będące w posiadaniu\\nprzedstawicielstw dyplomatycznych, urzędów konsularnych i innych misji zagranicznych,\\nkorzystających z przywilejów i immunitetów na podstawie ustaw, umów lub zwyczajów\\nmiędzynarodowych, oraz członków ich personelu, jak również innych osób zrównanych z\\nnimi, jeżeli nie są obywatelami polskimi i nie mają miejsca pobytu stałego na terytorium\\nRzeczypospolitej Polskiej;\\n2) środki transportowe stanowiące zapasy mobilizacyjne, pojazdy specjalne oraz pojazdy\\nużywane do celów specjalnych w rozumieniu przepisów o ruchu drogowym;  \\f\\n\\nStrona 196 z 219\\n\\n3) pojazdy zabytkowe, w rozumieniu przepisów o ruchu drogowym.\\n4) W szczególności należy tu wskazać na zwolnienie od podatku od środków transportowych\\npojazdów specjalnych oraz pojazdy używane do celów specjalnych. Zgodnie z przepisami\\nustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym są to pojazdy samochodowe\\nlub przyczepy przeznaczone do wykonywania specjalnej funkcji, która powoduje konieczność\\ndostosowania nadwozia lub posiadania specjalnego wyposażenia. W pojeździe tym mogą\\nbyć przewożone osoby i rzeczy związane z wykonywaniem tej funkcji.\\n\\nCzyli są to pojazdy stricte przeznaczone do konkretnych celów, ale nie wykonujące przewozu\\ndrogowego osób lub rzeczy.\\nNiestety według dotychczasowego orzecznictwa pojazdy do nauki jazdy i egzaminowania nie\\nwchodzą w tą definicję.\\n\\nW ww. przepisach mamy też wymieniony „pojazd używany do celów specjalnych”. Są to\\npojazdy używane w szczególny sposób przystosowane do przewozu osób lub ładunków przez\\nsłużby (wojsko, policję itp.). W naszej ocenie do tej kategorii pojazdów powinny dołączyć\\npojazdy przeznaczone do nauki jazdy i egzaminowania ponieważ są to też pojazdy używane\\ndo celów specjalnych (innych niż transport drogowy) – czyli do nauki jazdy i egzaminowania.\\nPojazdy te nie występują w znacznej ilości i pomimo posiadania dopuszczalnej masy\\ncałkowitej powyżej 12 t. ich ładowność nie jest wykorzystywana, a więc nie obciążają dróg w\\ntakim stopniu jak pojazdy wykorzystywane do zarobkowego transportu drogowego.\\nPojazdy te nigdy nie wykonują transportu drogowego osób lub rzeczy i zwykle poruszają się\\npo drogach w ogóle nie obciążone.\\nWarto podkreślić, że zadania wykonywane przez te pojazdy są zadaniami pośrednio na rzecz\\nlokalnej społeczności. Są to też działania związane z edukacją obywateli i ich rozwojem\\nzawodowym, a także poprawą bezpieczeństwa ruchu drogowego. Wiemy, że w przypadkach\\nkiedy pojazdami tymi nie jest wykonywana działalność transportowa, to płacony od lat\\npodatek od środków transportu stanowi znaczący koszt w rocznym utrzymaniu takiego\\npojazdu.\\nPrzyczynia się to do konieczności podnoszenia ceny za kurs na prawo jazdy, a więc ogranicza\\ndostępność zawodu kierowcy. Od kilku lat największe organizacje zrzeszające pracodawców\\ntransportu drogowego alarmują o braku kierowców na rynku Polskim, co jest spowodowane\\nmiędzy innymi wysokim kosztem uzyskania uprawnień kierowcy w Polsce. Mając na \\f\\n\\nStrona 197 z 219\\n\\nwzględzie obecną sytuację ekonomiczną wiele osób odstępuje od pomysłu uzyskania\\nuprawnień kierowcy zawodowego ze względu na koszty. Z drugiej strony przedsiębiorcy\\nprowadzący ośrodki szkolenia kierowców, zmuszeni do ponoszenia kosztów stałych\\nutrzymania sprzętu (w tym niezależnego od dochodu podatku od środków transportu),\\npodnoszą ceny za kursy, albo rezygnują z prowadzenia tej części swojej działalności.\\nUmożliwienie tym podmiotom zachowania lub rozwinięcia swojej działalności i jednoczesne\\nobniżenie kosztów uzyskania uprawnień do kierowania pojazdami ciężarowymi powinno być\\npriorytetem dla organów Państwa.\\nWarto także zauważyć, że Polska jest liderem transportu drogowego w Unii Europejskiej.\\nMamy zarejestrowanych ponad milion pojazdów ciężarowych i autobusów, za które\\nsamorządy słusznie pobierają podatek od środków transportu.\\nDo szkolenia i egzaminowania wykorzystywanych jest około 1500 pojazdów w całej Polsce.\\nJest to średnio 4 pojazdy szkoleniowe powyżej 12 t na powiat. Daje to niewielki dochód\\nPowiatowi, ale znacznie obciąża budżet małych przedsiębiorców niejednokrotnie\\nprzyczyniając się do likwidacji ostatnich w danym powiecie Ośrodków Szkolenia Kierowców\\nszkolących kierowców zawodowych. Zamyka to także szansę na uzyskanie dobrze płatnego i\\npotrzebnego polskiej gospodarce zawodu kierowcy. Dodatkowo należy wskazać, że byłaby to\\nbardzo niewielka liczba pojazdów zwolnionych od podatku w skali prawie 4 milionów\\nzarejestrowanych samochodów ciężarowych w skali całej Polski.\\nNależy przypomnieć, że od 1 stycznia 2026 r. weszły wreszcie w życie przepisy nakładające\\nobowiązek przeprowadzania egzaminów państwowych na prawo jazdy kategorii C+E przy\\nużyciu wyłącznie samochodów ciężarowych z naczepą czyli ciągników siodłowych. W\\nostatnim roku w wszystkie Wojewódzkie Ośrodki Ruchu Drogowego i w zasadzie wszystkie\\nośrodki szkolenia szkolące w zakresie prawa jazdy C+E musiały zainwestować niemałe\\npieniądze w zakup zestawów do prowadzenia szkolenia i egzaminowania według nowych\\nzasad. Warto zatem, jak w przypadku dofinansowania wymiany tachografów cyfrowych,\\nulżyć odrobinę tym podmiotom choćby przez zwolnienie ich z podatku od środków\\ntransportu, mając na względzie, że tego transportu tymi pojazdami i tak nie wykonują.\\nZatem przyczyniając się do promocji zawodu kierowcy, a tym samym polskiego transportu\\ndrogowego wnosimy o przyjęcie proponowanego rozwiązania będącego jednoznacznym\\nwsparciem dla Polskich przedsiębiorców szkoleniowych. Należy wskazać, że do tej pory\\nlikwidacja barier uniemożliwiających, albo utrudniających prowadzenie działalności\\ngospodarczej była jednym z działań priorytetowych podejmowanych przez władzę \\f\\n\\nStrona 198 z 219\\n\\nustawodawczą i wielokrotnie przyczyniała się do rozwoju poszczególnych branż. Mamy\\nnadzieję, że proponowane przez nas rozwiązanie w podobny sposób wpłynie na rozwój\\nbranży szkolenia kierowców oraz branży transportowej.\\n\\n Uwaga\\ndodatkowa\\nPolski Związek\\nSzkoleniowy\\nPo pkt 2 dodaje się pkt 2a w brzmieniu:\\n\\n„2a) w art. 55 ust. 1 i 2 otrzymują brzmienie:\\n„1. Pojazd do nauki jazdy lub przeprowadzania egzaminu państwowego oznacza się tablicą\\nkwadratową barwy niebieskiej z białą literą \\\"L\\\", umieszczoną na pojeździe. W warunkach\\nniedostatecznej widoczności tablica umieszczona na pojeździe, z wyłączeniem tablicy na\\nmotocyklu, powinna być oświetlona. Tablica, którą oznaczony jest motocykl, powinna być\\nwykonana z materiału odblaskowego i może być zastąpiona kamizelką odblaskową na której\\nznajduje się odwzorowanie tej tablicy, noszoną przez osobę szkoloną.”\\n2. Podczas kierowania pojazdem do nauki jazdy przez osobę inną niż osoba szkolona lub\\negzaminowana tablica, o której mowa w ust. 1, powinna być zasłonięta lub złożona.””\\n\\nUzasadnienie\\nW związku z wprowadzeniem możliwości szkolenia przez ośrodek szkolenia kierowców osób\\nposiadających uprawnienia do kierowania pojazdami (tzw. powtórna nauka jazdy dla\\nposiadających prawo jazdy) ze względów bezpieczeństwa całego procesu należy umożliwić\\ntym osobom jazdę w samochodzie do nauki jazdy oznaczonym tablicą „L”. Osoby, które\\nwiele lat nie kierowały pojazdem mogą stanowić na drodze podobne zagrożenie jak\\nkandydaci na kierowców, a więc powinien istnieć obowiązek informowania pozostałych\\nuczestników ruchu o możliwym zagrożeniu. Obecne brzmienie art. 55 jednoznacznie\\nwyklucza z kierowania pojazdem oznaczonym tą literą wszystkie osoby posiadające\\nuprawnienia do kierowania pojazdami. Proponowana zmiana rozwiązuje ten problem dając\\nzielone światło do ponownego szkolenia osób posiadających uprawnienia do kierowania\\npojazdami z zachowaniem odpowiednich zasad bezpieczeństwa.\\nProponujemy także częściową likwidację obowiązku posiadania tablicy „L” przez motocykl w\\nzamian za obowiązek umieszczenia tego znaku na kamizelce, którą w czasie szkolenia będzie\\nmiała na sobie osoba szkolona. Należy zwrócić uwagę, że celem tablicy „L” na pojeździe jest\\ninformowanie o zagrożeniu w postaci osoby dopiero uczącej się jeździć na takim pojeździe.\\nDotychczas umieszczanie takiej tablicy na motocyklu odbywało się poprzez przykręcenie jej \\f\\n\\nStrona 199 z 219\\n\\nna tylnym błotniku, co jest kłopotliwe, a jednocześnie nie realizuje celu informacyjnego\\nponieważ zwykle tablica znajduje się bardzo nisko i nie jest dobrze widoczna. Najwyższym\\npunktem motocykla jest osoba szkolona i umieszczenie informacji w formie tablicy „L” na\\nkursancie rozwiązuje problem widoczności.\\nWarto też zauważyć, że blaszana tablica wystająca poza motocykl może stanowić realne\\nzagrożenie dla przewracającego się kursanta.\\n Uwaga\\ndodatkowa\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\nObecnie obowiązek montowania tablic L z tyłu na motocyklach prowadzi do licznych\\nproblemów. Nowoczesne motocykle często pozbawione są z tyłu elementów do których\\nmożliwy jest bezpieczny montaż tablicy L. Tablica często montowana jest nisko, co znacząco\\nogranicza jej widoczność w ruchu drogowym. Należy zwrócić uwagę, że dla innych pojazdów\\nminimalną wysokość ustawodawca określił na 60 cm czyli miał na uwadze fakt widoczności.\\nAby poprawić widoczność osoby szkolonej na motocyklu i jednocześnie zminimalizować\\nproblemy techniczne dot. montażu tablic z tyłu motocykla sugeruję usunięcie obowiązku\\nmontowania tablic L na motocyklach, w zamian nakładając obowiązek stosowania kamizelki\\ndla osoby szkolonej z umieszczonymi na niej oznaczeniami L z przodu i z tyłu. Takie\\nrozwiązanie z pewnością poprawi widoczność takiej osoby i przez to bezpieczeństwo w\\nruchu drogowym.\\n\\n Uwagi\\ndodatkowe\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\nWarto zwrócić uwagę i uzupełnić przepisy w zakresie dotyczącym następujących kwestii:\\n1. rozbudowanie systemu PKK o funkcję wysyłającą automatycznie informację, do wszystkich\\npodmiotów zainteresownych (OSK,które ma pobrany PKK, WORD itp.) informacji o\\nwprowadzeniu do systemu danych o zakazie prowadzenia pojazdów orzeczonym wobec\\ndanej osoby.\\n2. przeniesienie ciężaru odpowiedzialności za wprowadzenie informacji o zakazach\\nprowadzenia pojazdów na starostę z jednoczesnym dopilnowaniem obowiązku\\npoinformowania OSK, które prowadzi szkolenie takiej osoby.\\n3. w przypadku szkolenia przez OSK osób przygotowujących się do kontrolnego sprawdzenia\\nkwalifikacji (co popieram) należy utworzyć PKK który będzie mógł pobrać OSK celem\\nprawidłowego zarejestrowania prowadzonego szkolenia\\n\\n Uwagi\\ndodatkowe\\nWielkopolskie\\nStowarzyszenie\\nProwadzenie harmonogramu kursu nie jest potrzebne i stanowi tylko i wyłącznie\\nniepotrzebny dokument, w oparciu o który kontrolujacy nic nie są w stanie zweryfikować.\\nZajęcia teoretyczne do tej pory odnotowywane są w Karcie Przeprowadzonych Zajęć lub \\f\\n\\nStrona 200 z 219\\n\\nOSK i\\nInstruktorów\\ndokumentacji cyfrowej - w przypadku prowadzenia kursu w formule e-learning. W nowym\\nwariancie, przy wprowadzeniu cyfrowej karty kursanta, transparentność zajęć będzie pełna i\\nprowadzenie dodatkowej dokumentacji stanowi tylko i wyłącznie pusty wymów obciążający\\nKierownika OSK.\\n\\nRaportowanie jest niepotrzebnym obciążeniem Kierownika OSK. Już obecnie starosta\\nsprawujący nadzór nad szkoleniem ma pełen wgląd do systemu PKK i może w sposób\\ndowolny weryfikować dane statystyczne co do ilości osób szkolonych w poszczególnych OSK\\n(vide chociażby ostatnio wprowadzony system info-kierowca.pl). Zatem obowiązki\\nstatystyczne które stanowią tylko i wyłącznie powielenie już informacji widniejących w\\nsystemie do którego ma dostęp starosta są zbędne i co najważniejsze nie mają żadnego\\nwpływu na poprawę jakości szkolenia lub poprawę bezpieczeństwa ruchu drogowego\\n\\n Uwaga\\ndodatkowa\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\nZgłaszanie osoby, która ma rozpocząć szkolenie jest dublowaniem informacji, które starosta\\nmoże sprawdzić korzystając z dostępnego systemu do obsługi PKK. Przed rozpoczęciem\\nszkolenia kierownik OSK pobiera PKK i w tej sposób starosta ma informację że dana osoba\\nbędzie odbywała szkolenie. W obecnych realiach (gdzie większość szkoleń prowadzona jest\\nw takiej formule, że kursanci przygotowują się samodzielnie do egz. teoretycznego i dopiero\\npo uzyskaniu wyniku pozytywnego przystępują do kursu) realizowanie obowiązku\\nwynikającego z art. 27  ust. 1 pkt 1) sprowadza się do wysyłania \\\"pustego\\\" zgłoszenia do\\nstarostwa.\\n\\n Uwaga\\ndodatkowa\\nWielkopolskie\\nStowarzyszenie\\nOSK i\\nInstruktorów\\nNależy doprecyzować (co znajduje umocowanie w interpretacjach MI wydawanych w\\nodpowiedzi na zapytania), że w OSK P wystarczające jest posiadanie co najmniej jednego\\npojazdu dla każdej kategorii spełniającego kryterium maksymalnego wieku. W tym zakresie\\nróżne podmioty sprawujące nadzór stosują różną interpretację prowadzące do\\nniejednolitych zasad na terenie kraju. Dodatkowo dla autobusów należy podnieść wiek do co\\nnajmniej 15 lat. Autobusy są pojazdami bardzo drogimi, a ich okres eksploatacji przewiduje\\nsię na znacznie więcej jak 12 lat. Wcześniej (przy tworzeniu obecnego brzmienia przepisów)\\nz pewnością kryterium 12 lat wynikało m.in. z faktu, aby pojazdy były \\\"nowoczesne\\\" i\\nwyposażone w systemy bezpieczeństwa. Obecnie wszystkie autobusy, nawet 15 letnie, są w\\ntakie systemy wyposażone stąd podniesienie wieku pozwoli przedsiębiorcom na \\f\\n\\nStrona 201 z 219\\n\\namortyzowanie zakupionego sprzętu dłużej, z lepszym bilansem ekonomicznym i\\njednocześnie nie będzie to miało negatywnego wpływu na jakość szkolenia i sprzętu.\\n\\nUwaga\\ndodatkowa\\n\\nFundacja\\nZapobiegania\\nWypadkom\\nDrogowym\\n\\nWszyscy nasi konsultanci zwracali uwagę na istotny brak projektów rozporządzeń, które nie\\ntylko zwyczajowo powinny towarzyszyć projektowi zmian w ustawie zmieniającej… Dopiero\\nkomplet dokumentów pozwala ocenić i docenić ich trafność.\\n\\n Uwagi\\ndodatkowe\\nZarząd Dróg\\nMiejskich\\nWarszawa\\n 2. Oznakowanie\\nW ślad za zmianami, do których wprowadzenia dąży resort infrastruktury, niezbędne będzie\\nwprowadzenie nowych znaków drogowych dotyczących bezpośrednio hulajnóg\\nelektrycznych.\\nWśród znaków pionowych uzupełnienia wymaga przede wszystkim zakres znaków B-9 do B-\\n12 o zakaz ruchu odnoszący się do hulajnóg elektrycznych. Wydaje się właściwe, aby był to\\nznak o symbolu B9a. Zapewne powinien obejmować również urządzenia transportu\\nosobistego.\\nPrzydatne było również wprowadzenie znaku poziomego, do oznaczenia miejsc postojowych\\ndla hulajnóg elektrycznych w trybie określonym w proponowanym art. 12c ustawy o drogach\\npublicznych. Ważne, aby nie zaśmiecić przestrzeni tysiącami znaków, proponujemy by nie\\nwprowadzać w tym celu znaku pionowego do oznaczania miejsc postojowych.\\n\\nUzasadnienie\\nRozwiązanie, które proponujemy, pozwoli prywatnym właścicielom hulajnóg elektrycznych i\\npodobnych pojazdów korzystać z obecnych rozwiązań prawnych (a więc m.in. wykonywać\\npostój na chodnikach czy w innych miejscach niewyznaczonych, zgodnie z obowiązującymi\\nprzepisami), natomiast jednoznacznie zobowiąże użytkowników pojazdów wynajmowanych\\ndo pozostawiania pojazdu po zakończeniu użytkowania, wyłącznie w miejscu\\nprzeznaczonym.\\n\\n Proponujemy odmienne zdefiniowanie mikromobilności dzielonej. W naszej ocenie\\nistotny nie jest dystans pokonywany pojazdami współdzielonymi, lecz okres, na jaki\\nsą one udostępniane. Podróż współdzielonym pojazdem może trwać nawet dwie \\f\\n\\nStrona 202 z 219\\n\\ngodziny i obejmować odcinek o długości kilkudziesięciu kilometrów, natomiast o\\nwspółdzielonym charakterze usługi świadczy przede wszystkim krótki czas\\nudostępnienia – z reguły znacznie krótszy niż doba, najczęściej nieprzekraczający\\njednej godziny.\\n\\n Wnioskujemy również o rezygnację ze wskazywania w definicji systemów\\nteleinformatycznych jako sposobu udostępniania pojazdów. Wynajem hulajnóg\\nelektrycznych lub urządzeń transportu osobistego prowadzony przez wypożyczalnie\\nhotelowe czy inne komercyjne wypożyczalnie, niewykorzystujące aplikacji\\nmobilnych, również powinien podlegać projektowanym regulacjom. Ponadto nie\\nsposób przewidzieć kierunków rozwoju tego rodzaju usług, dlatego definicja\\npowinna mieć możliwie otwarty charakter. Jednocześnie proponujemy rozszerzenie\\nkatalogu pojazdów - motorowery, rowery elektryczne i inne rowery wspomagane,\\nzwłaszcza w wersjach elektrycznych, mogą w najbliższych latach odgrywać coraz\\nwiększą rolę na rynku mikromobilności dzielonej.\\n\\n Proponujemy dodanie art. 12c do ustawy o drogach publicznych zamiast\\nproponowanych przez resort zmian w art. 20 tej ustawy, ponieważ wyznaczanie\\nmiejsc postojowych może być elementem organizacji ruchu - właściwe byłoby zatem\\nodesłanie w ustawie do organu właściwego do zarządzania ruchem. W ten sposób\\nstojaki rowerowe, które umieszczane są bez wpływu na organizację ruchu, byłyby w\\nkompetencji zarządcy drogi, a miejsca wymagające zmian w organizacji ruchu\\nwyznaczane byłyby przez zarządcę ruchu i byłyby bezpośrednio określone w nowych\\nartykule.\\n\\n Pod rozwagę poddajemy również możliwość wprowadzenia wymogu udzielenia\\nzgody przez zarządcę drogi na korzystanie z miejsc postojowych przez pojazdy\\nmikromobilności dzielonej. Zainteresowane samorządy mogłyby zyskać w ten\\nsposób narzędzie kontroli liczby hulajnóg znajdujących się w użytkowaniu oraz\\ndodatkowy sposób identyfikacji pojazdu współdzielonego. Dane te pozwalałyby\\nlepiej planować politykę transportową miasta, zwłaszcza jeśli liczba rodzajów\\npojazdów mikromobilności dzielonej będzie rosła. Rozwiązanie to należy jednak\\ntraktować wyłącznie jako fakultatywne. \\f\\n\\nStrona 203 z 219\\n\\n W naszej ocenie nie należy również wprowadzać do porządku prawnego miejsc\\nprzeznaczonych wyłącznie dla pojazdów mikromobilności dzielonej. Miejsca dla\\nhulajnóg i podobnych pojazdów powinny być ogólnodostępne. Trudne do\\nuzasadnienia i egzekwowania byłoby wyznaczenie miejsc przeznaczonych wyłącznie\\ndla pojazdów współdzielonych, z których nie mogliby korzystać właściciele pojazdów\\nprywatnych. Rodziłoby to niepotrzebne konflikty i podważało zasadność takich\\nregulacji.\\n\\n Proponujemy również wprowadzenie zakazu postoju pojazdów współdzielonych w\\nart. 49 Prawa o ruchu drogowym, zamiast dodawania nowego ust. 3a w art. 47. Art.\\n47 reguluje bowiem dopuszczalne przypadki postoju na chodniku, natomiast celem\\nprojektowanego rozwiązania jest kompleksowe uregulowanie zasad postoju\\npojazdów mikromobilności dzielonej i jednoznaczne wskazanie, że jedynym\\ndopuszczalnym miejscem ich postoju są miejsca wyznaczone. Dodanie nowego ust.\\n3a do art. 47 mogłoby prowadzić do wątpliwości interpretacyjnych, czy obowiązek\\nten dotyczy wyłącznie chodników, czy całej drogi.\\nAlternatywą jest wprowadzenie art. 47b., który dopuszczałby postój pojazdów\\nmikromobilności dzielonej tylko w przeznaczonych miejscach: określonych w\\ndodanym art. 12c. ustawy o drogach publicznych i przy stojakach rowerowych.\\n\\n Istotne jest także jednoznaczne przyznanie straży gminnej (miejskiej) kompetencji\\ndo wydawania dyspozycji usunięcia pojazdu na podstawie art. 130a Prawa o ruchu\\ndrogowym. W ślad za propozycjami zawartymi w projekcie nr UD402 zasadne jest\\nwyraźne określenie tych kompetencji w ustawie.\\n\\n Uwagi\\ndodatkowe\\nOsoba fizyczna\\n(zgłoszenie nr 9)\\nNiniejszym zgłaszam postulat włączenia do projektu szeregu zmian przedstawionych w\\nniniejszym piśmie, które mają na celu:\\n1. Wprowadzić ułatwienia w przechodzeniu z zawodu egzaminatora i instruktora\\ntechniki jazdy do zawodu instruktora nauki jazdy czy właściciela własnej szkoły jazdy,\\njako że dwa pierwsze zawody cechuje bardzo wysoki poziom przygotowania.  \\f\\n\\nStrona 204 z 219\\n\\n2. Zlikwidować rosnący problem niedoboru instruktorów kategorii ciężkich w Polsce.\\nPoprzez otwarcie drogi do zawodu instruktora kat. C, D i C+E osobom posiadającym\\nprzez ponad 5 lat stosowne uprawnienia i kwalifikację zawodową. W tym celu\\nzniesienie dla kandydatów na instruktorów kategorii ciężkich z doświadczeniem w\\npracy kierowcy zawodowego, nadmiernych wymogów formalnych w zakresie\\ndokumentacji oraz czysto arbitralnych wymogów pracy w wybranych sektorach\\ntransportu, eliminujących osoby posiadające realne kompetencje spoza tych\\nsektorów.\\n3. Usunąć pozbawiony podstaw merytorycznych, wymóg czysto pasywnego posiadania\\nprzez co najmniej 3 lata uprawnień egzaminacyjnych na kategorię B, jako warunek\\nuzyskania uprawnień egzaminacyjnych na inne kategorie.\\nZmiana 1:\\nW art. 28 w ust. 2 pkt 2 otrzymuje brzmienie:\\n„2) zatrudnia w ośrodku szkolenia kierowców co najmniej jednego instruktora, który posiada\\nuprawnienia do prowadzenia szkoleń w zakresie uzyskiwania uprawnienia do kierowania\\npojazdami silnikowymi kategorii prawa jazdy określonej we wniosku, o którym mowa w ust.\\n4, oraz udokumentowaną, łączną 3-letnią praktykę w zakresie tej kategorii, obejmującą\\nokresy wykonywania jednej lub więcej następujących czynności:\\n a) instruktora nauki jazdy w ośrodku szkolenia kierowców,\\nb) egzaminatora w wojewódzkim ośrodku ruchu drogowego, lub\\n c) instruktora techniki jazdy w ośrodku doskonalenia techniki jazdy\\n– albo sam jest instruktorem spełniającym te wymagania;”\\nZmiana 2:\\nW art. 33 w ust. 1 pkt 6 otrzymuje brzmienie:\\n„6) ukończyła z wynikiem pozytywnym kurs dla kandydatów na instruktorów i posiada\\nzaświadczenie o jego ukończeniu – dotyczy instruktorów osób ubiegających się o uzyskanie\\nuprawnienia do kierowania pojazdami silnikowymi, przy czym wymóg ten nie dotyczy osób, \\f\\n\\nStrona 205 z 219\\n\\nktóre w dniu złożenia z wynikiem pozytywnym egzaminu, o którym mowa w pkt 7, posiadały\\nuprawnienia egzaminacyjne lub uprawnienia instruktora techniki jazdy w zakresie prawa\\njazdy kategorii odpowiedniej dla zakresu prowadzonego szkolenia;”\\nZmiana 3:\\nW art. 33 ust. 1a otrzymuje brzmienie:\\n „1a. Wymóg, o którym mowa w ust. 1 pkt 2 lit. c, uznaje się za spełniony, jeżeli kandydat na\\ninstruktora posiada przez łączny okres przekraczający 5 lat ważne uprawnienia do\\nkierowania pojazdami oraz kwalifikację zawodową:\\n1. odpowiednie dla prawa jazdy kategorii C+E – w przypadku kandydata na instruktora\\nw zakresie prawa jazdy kategorii C, C+E lub D,\\n2. odpowiednie dla prawa jazdy kategorii C albo D – w przypadku kandydata na\\ninstruktora w zakresie którejkolwiek z tych kategorii\\n a ponadto przez okres co najmniej roku posiada uprawnienia do kierowania\\npojazdami odpowiednie do zakresu prowadzonych zajęć oraz odpowiadającą im\\nkwalifikację zawodową.”\\n\\nZmiana 4:\\nW art. 33 dodaje się ust. 1b w brzmieniu:\\n\\n„1b. Wymóg, o którym mowa w ust. 1 pkt 2 lit. c, uważa się za spełniony w przypadku\\nkandydata na instruktora, który posiada ważne prawo jazdy kategorii odpowiedniej do\\nzakresu prowadzonych zajęć, a ponadto udokumentuje łączny okres wykonywania\\nczynności egzaminatora w wojewódzkim ośrodku ruchu drogowego, instruktora\\ntechniki jazdy w ośrodku doskonalenia techniki jazdy lub łączny okres wykonywania\\nobu tych czynności, wynoszący co najmniej:\\n \\f\\n\\nStrona 206 z 219\\n\\n1. 1 rok w zakresie kategorii prawa jazdy odpowiedniej do zakresu prowadzonych\\nzajęć, albo\\n2. 3 lata w zakresie prawa jazdy kategorii B, do okresu tego wlicza się również okres\\nwykonywania czynności instruktora nauki jazdy kategorii B w ośrodku szkolenia\\nkierowców.”\\nZmiana 5:\\nW art. 58 w ust. 1 pkt 3 otrzymuje brzmienie:\\n„3) posiada uprawnienia egzaminatora w zakresie prawa jazdy kategorii B, w przypadku\\nosoby ubiegającej się o uprawnienia do egzaminowania na pozostałe kategorie prawa\\njazdy;”\\nUzasadnienie zmiany 1:\\nOśrodki Szkolenia Kierowców mają obowiązek zatrudniania co najmniej jednego instruktora\\nz 3-letnim doświadczeniem w szkoleniu kierowców. Zmiana pozwala, alternatywnie,\\nzatrudnić instruktora który posiada 3-letnie doświadczenie w pracy egzaminatora w WORD\\nlub instruktora techniki jazdy w ODTJ.\\nPonadto doświadczony egzaminator lub doświadczony instruktor doskonalenia techniki\\njazdy otrzymują możliwość by ich uprzednie doświadczenie w egzaminowaniu lub\\ndoskonaleniu techniki jazdy pozwoliło na spełnienie wymogu o którym mowa w przepisie,do\\nzałożenia i prowadzenia ich własnej szkoły jazdy.\\nPrzepis pozwala na sumowanie okresów wykonywania czynności instruktora nauki jazdy z\\nokresami wykonywania czynności egzaminatora i instruktora doskonalenia techniki jazdy.\\nUżyte w przepisie wyrażenia, pozwalają na zaliczenie doświadczenia uzyskanego również w\\nramach samozatrudnienia.\\nJakkolwiek w przypadku kierowców zawodowych, wymóg udokumentowania doświadczenia\\njest nadmiernym wymogiem – kierowca rzadko z góry planuje że zostanie instruktorem i nie\\nzbiera dokumentów -  tak od osób zawodowo związanych z branżą szkolenia kierowców, jak\\nnajbardziej można wymagać zbierania takiej dokumentacji.\\nUzasadnienie zmiany 2: \\f\\n\\nStrona 207 z 219\\n\\nProponowana zmiana zwalnia osoby posiadające uprawnienia egzaminacyjne lub\\nuprawnienia instruktora techniki jazdy z odbycia kursu instruktora nauki jazdy. Osoby te\\nposiadają przeważnie znacznie szersze kwalifikacje i wiedzę niż te przekazywane na kursie\\ninstruktora nauki jazdy. Można więc je bezpiecznie zwolnić  z konieczności ponoszenia\\nkosztów finansowych i czasowych związanych z, w praktyce zduplikowanym kursem i\\ndopuścić je bezpośrednio do egzaminu na instruktora nauki jazdy.\\nUzasadnienie zmiany 3:\\nProponowana zmiana ma na celu zapobieżenie rosnącemu w Polsce niedoborowi\\ninstruktorów kategorii zaawansowanych przy jednoczesnym zapewnieniu jakości szkolenia.\\nCoraz częściej czas zrobienia kursu na kategorie zaawansowaną przekracza dzisiaj 3\\nmiesiące, przyczyną tego jest niedobór nowych instruktorów oraz przechodzenie obecnych\\ninstruktorów na emeryturę.\\nDojście do zawodu, wymaga albo 3 lat doświadczenia w zakresie szkolenia na kat. B, co w\\nżaden sposób nie przekłada się na umiejętności nauczania dla kategorii ciężkich. Albo w\\nprzypadku kierowcy zawodowego spełnienia bardzo zbiurokratyzowanych wymogów\\nudokumentowania doświadczenia w przewozach międzynarodowych lub komunikacji\\npublicznej. Prowadzi to do pominięcia całego grona kompetentnych osób, które albo nie są\\nw stanie zebrać odpowiedniej dokumentacji albo posiadają doświadczenie w innych niż te\\nczysto arbitralnie wybrane segmenty transportu.\\nToteż proponuje się, aby ułatwiony dostęp do zawodu instruktora nauki jazdy na kategorie\\nciężkie, miały osoby które posiadają swoje uprawnienia kierowcy zawodowego przez ponad\\n5 lat, co automatycznie oznacza że uprawnienia te musiały przedłużyć. Osoba, która\\nprzedłuża swoje uprawnienia i kwalifikację zawodową na następne 5 lat i inwestuje to\\nśrodki, w absolutnej większości będzie osobą z realnym doświadczeniem w transporcie\\nciężkim, gotową wiązać dalej z nim swoją karierę.\\nZastosowany filtr, jest najbardziej realistycznym i racjonalnym rozwiązaniem w celu\\nzapewnienia jakości szkolenia, innym niż po prostu znaczne zaostrzenie kryteriów\\negzaminowania kandydatów na instruktora kategorii ciężkich.\\nSzczególną zaletą proponowanego rozwiązania jest to, że zwalnia ono absolutną większość\\nkandydatów ze zbierania dokumentacji, gdyż ewidencję instruktorów prowadzi wydział\\nkomunikacji starostwa, ten sam który wydaje prawa jazdy.  \\f\\n\\nStrona 208 z 219\\n\\nZ uwagi na podobieństwo gabarytów między pojazdami kategorii C i D, wprowadzono\\nułatwiony dostęp dla doświadczonego kierowcy kategorii ciężarowej lub autobusowej, w\\nuzyskaniu uprawnień instruktora na tą drugą kategorię. Wystarczy, aby obok posiadania\\nswoich głównych uprawnień i kwalifikacji przez ponad 5 lat, posiadał te drugie uprawnienia i\\nkwalifikacje przez okres co najmniej 1 roku.\\nZ kolei doświadczenie nabyte jako kierowca kategorii C+E, otwiera dostęp do zawodu\\ninstruktora w sposób najbardziej szeroki, z uwagi na najbardziej szeroki zakres umiejętności\\ntych kandydatów. Dla doświadczonego kierowcy kategorii C+E, kierowanie pojazdem na\\nkategorię C jest wręcz trywialne. Stąd tak samo jak dla kierowcy kategorii C, uzasadnione\\njest ułatwienie dojścia do zawodu instruktora kategorii D. Z uwagi na przepis art. 33 ust. 3a\\npkt. 2-5,  instruktor posiadający uprawnienia do szkolenia jednocześnie na kat. C, C+E i D,\\nbędzie z urzędu uprawniony do szkolenia na kategorie B+E ,C1,C,C1+E, C+E,D,D1,D1+E, D+E i\\nT.\\nNowelizacja nie przewiduje dodatkowych ułatwień dla kierowców kat. D+E, innych niż\\nwynikających z posiadania przez ponad 5 lat uprawnień i kwalifikacji zawodowej dla samej\\nkategorii D. Szkolenie na kategorię D+E jest w Polsce marginesem, a w przedsiębiorstwach\\nzajmujących się przewozem osób, do kierowania zespołami pojazdów na kat. D zatrudnia się\\nkierowców posiadających jednocześnie kategorię D i C+E, którym na podstawie art. 6 , ust. 1\\npkt. 16 niniejszej ustawy z urzędu wpisano kategorię D+E.  Należy zanotować na marginesie,\\nże obecny przepis art. 33, ust. 1a, pkt. 2 odnoszący się do szkolenia na kategorię D+E jest\\nprawem całkowicie martwym, zwłaszcza przy zawartych w tym przepisie wymogach.\\nZa całkowicie oderwane od dzisiejszej rzeczywistości i dyskryminujące, uznane zostały\\nwymogi pracy w konkretnych sektorach – przewozie międzynarodowym czy komunikacji\\nmiejskiej. Zawężenie doświadczenia do tych sektorów jest czysto arbitralne i zupełnie\\nbezzasadnie eliminuje osoby posiadające realne kompetencje.\\nZmiana celowo używa pojęcia “okresu łącznego”, w celu objęcia nią również osób, które z\\npowodów np. zdrowotnych miały przerwę w odnawianiu swoich uprawnień i kwalifikacji,\\njednak łącznie posiadały je przez 5 lat, jednocześnie posiadają te uprawnienia i kwalifikację\\nobecnie.\\nUzasadnienie zmiany 4: \\f\\n\\nStrona 209 z 219\\n\\nNiniejsza zmiana uznaje 3-letnie doświadczenie w pracy egzaminatora w WORD i instruktora\\ntechniki jazdy w ODTJ dla kategorii B za równorzędne z doświadczeniem w szkoleniu\\nkandydatów na kierowców jako instruktor nauki jazdy, w kontekście uzyskania uprawnień\\ninstruktora kategorii B+E, C1, C1+E, C, C+E, D1, D1+E, D lub D+E. Ponadto egzaminatorzy i\\ninstruktorzy techniki jazdy, którzy posiadają co najmniej 1 roczne doświadczenie w pracy\\njako egzaminator w WORD lub instruktor techniki jazdy w ODTJ na jedną z w/w kategorii\\nmogą zostać instruktorem tej kategorii bez spełniania wymogu 3 letniego doświadczenia w\\nszkoleniu, doskonaleniu techniki jazdy lub egzaminowaniu na kategorię B. Osoba ta posiada\\nkwalifikacje znacznie większą, niż osoba wykonująca czynności tylko dla kategorii B.\\nZachowano jednak wymóg posiada prawa jazdy danej kategorii.\\nPrzepis pozwala na łączenie ze sobą okresów wykonywania czynności egzaminatora,\\ninstruktora techniki jazdy i instruktora nauki jazdy oraz na uznanie doświadczenia\\nuzyskanego w ramach samozatrudnienia.\\nUzasadnienie zmiany 5:\\nPrzepis warunkujący uzyskanie uprawnień egzaminatora dla kategorii innych niż kat. B od\\nposiadania uprawnień egzaminatora kategorii B przez 3 lata jest pozbawiony uzasadnienia i\\nstanowi nadmierną regulację sztucznie ograniczającą dostęp do zawodu. Samo pasywne\\nposiadanie uprawnień przez 3 lata nie daje żadnych przewag w kwestii jakości przyszłej\\npracy kandydata na egzaminatora. Po 3 latach, o uprawnienia dodatkowe może ubiegać się\\nosoba, która nie przeprowadziła ani jednego egzaminu, a tylko i wyłącznie brała udział w\\ncorocznych szkoleniach doskonalących.\\n Zdawalność egzaminów dla kandydatów na egzaminatorów jest bardzo niska, a proces\\nweryfikacji wiedzy kandydatów na egzaminatorów stoi na bardzo wysokim poziomie. Toteż\\nobecny przepis stanowi całkowicie zbędną barierę dojścia do i tak trudno dostępnego\\nzawodu.\\nWobec powyższego zaproponowano zmianę, by do uzyskania uprawnień egzaminatora\\ninnych kategorii niż kat. B, wymagany był, oprócz pozostałych wymogów zawartych w art. 58\\nUstawy, sam fakt posiadania uprawnień do egzaminowania na kategorię B, bez względu na\\nczas ich posiadania. Niewątpliwie kategoria B stanowi istotną bazę na której można\\nbudować kolejne uprawnienia. Nie ma jednak najmniejszego uzasadnienia dla \\f\\n\\nStrona 210 z 219\\n\\nwarunkowania rozbudowy tych uprawnień od samego tylko upływu czasu i wzięcia udziału w\\ntrzech corocznych szkoleniach doskonalących, przedłożenia zaświadczenia lekarskiego itd.\\n Uwagi\\ndodatkowe\\nOgólnopolski\\nZwiązek\\nZawodowy\\nPracowników\\nWojewódzkich\\nOśrodków\\nRuchu\\nDrogowego\\nWnioskujemy także o zmianę zapisu Art. 63 ust. 1 pkt. 6  oraz dodanie Art. 63a) tak, by można\\nbyło również korzystać z mLegitymacji umieszczonej w aplikacji mObywatel.\\nArt.  63.\\n1.  Egzaminator jest obowiązany:\\n6) posiadać w czasie przeprowadzania egzaminów legitymację egzaminatora lub\\nmLegitymację oraz okazywać ją na żądanie uprawnionego podmiotu.\\nArt.  63a. [mLegitymacja egzaminatora]\\n\\n1. Egzaminatorowi wydaje się legitymację służbową w postaci dokumentu mobilnego, o\\nktórym mowa w art. 2 pkt 7 ustawy z dnia 26 maja 2023 r. o aplikacji mObywatel (Dz. U. z\\n2024 r. poz. 1275 i 1717 oraz z 2025 r. poz. 1019), jako \\\"mLegitymację\\\", po uwierzytelnieniu\\nprzy użyciu certyfikatu podstawowego, o którym mowa w art. 2 pkt 2 ustawy z dnia 26 maja\\n2023 r. o aplikacji mObywatel.\\n 2.  mLegitymację wydaje się w terminie 14 dni od dnia nawiązania stosunku pracy w\\nWojewódzkim Ośrodku Ruchu Drogowego.\\n3.  mLegitymacja zawiera:\\n1) imię (imiona) i nazwisko egzaminatora;\\n2) wizerunek twarzy egzaminatora;\\n3) numer ewidencyjny egzaminatora;\\n4) kategorie prawa jazdy, na które egzaminator posiada uprawnienia egzaminacyjne;\\n5) nazwę i adres siedziby WORD, w którym egzaminator jest zatrudniony;\\n6) numer mLegitymacji;\\n7) datę wydania mLegitymacji.\\n4. Numer mLegitymacji jest tożsamy z numerem legitymacji egzaminatora\\n5. mLegitymacja potwierdza zatrudnienie na stanowisku egzaminatora.\\n6. mLegitymację wydaje się egzaminatorowi na czas zgodny z terminem ważności wydanej\\nlegitymacji egzaminatora.\\n7. mLegitymację unieważnia się w przypadku:\\n1) rozwiązania albo wygaśnięcia stosunku pracy egzaminatora;\\n2) zmiany Wojewódzkiego Ośrodka Ruchu Drogowego, w którym egzaminator jest\\nzatrudniony; \\f\\n\\nStrona 211 z 219\\n\\n3) błędu w numerze lub danych w mLegitymacji;\\n4) zmiany zakresu uprawnień egzaminacyjnych;\\n5) utraty uprawnień egzaminacyjnych.\\n8. W przypadku unieważnienia mLegitymacji z przyczyn określonych w ust. 7 pkt 2-4\\negzaminatorowi wydaje się nową mLegitymację.\\n\\n Uwagi\\ndodatkowe\\nOsoba fizyczna\\n(zgłoszenie nr 8)\\nPrzedmiot uwagi: Przyspieszenie wejścia w życie przepisów znoszących obowiązek egzaminu\\npaństwowego przy usuwaniu ograniczenia kodu 78 (skrzynia automatyczna). Wnoszę o jak\\nnajszybsze wdrożenie przepisów znoszących konieczność zdawania egzaminu państwowego\\nw WORD w celu usunięcia kodu 78 z prawa jazdy i zastąpienie go kursem w Ośrodku\\nSzkolenia Kierowców (OSK). Pozostawienie obecnych restrykcji do końca unijnego okresu\\ndostosowawczego (2029 r.) niesie za sobą negatywne skutki społeczne, gospodarcze i\\nekologiczne. Natychmiastowe wejście w życie tych zmian jest uzasadnione następującymi\\nargumentami: 1. Blokada rozwoju elektromobilności i transformacji ekologicznej. Polska,\\njako kraj członkowski UE, dąży do redukcji emisji gazów cieplarnianych i popularyzacji aut\\nnisko- i zeroemisyjnych. Samochody elektryczne oraz zdecydowana większość nowoczesnych\\nhybryd konstrukcyjnie nie posiadają manualnej skrzyni biegów. Obecne przepisy zniechęcają\\nmłodych kierowców do nauki jazdy na nowoczesnych pojazdach (automatach), ponieważ\\notrzymanie kodu 78 drastycznie ogranicza ich mobilność w przyszłości. Przyspieszenie zmian\\nnatychmiast odblokuje ten proces i zachęci obywateli do przesiadki na pojazdy ekologiczne.\\n2. Sztuczne obciążenie i paraliż systemu egzaminacyjnego (WORD). Wojewódzkie Ośrodki\\nRuchu Drogowego od lat zmagają się z problemem długich kolejek i brakiem rąk do pracy\\nwśród egzaminatorów. Zmuszanie kierowców, którzy potrafią już bezpiecznie poruszać się w\\nruchu miejskim, do ponownego zdawania pełnego egzaminu państwowego tylko w celu\\nzweryfikowania umiejętności zmiany biegów, jest marnotrawstwem zasobów publicznych.\\nPrzeniesienie tego uprawnienia do OSK w formie kilkugodzinnego szkolenia natychmiast\\nodciąży WORD-y i skróci czas oczekiwania na egzaminy dla osób ubiegających się o swoje\\npierwsze prawo jazdy. 3. Straty finansowe polskich przedsiębiorców i szkół jazdy (OSK).\\nKrajowy rynek szkoleniowy jest gotowy na zmiany, jednak obecne przepisy blokują\\ninwestycje w nowoczesną flotę pojazdów. Szkoły jazdy obawiają się zakupu aut\\nelektrycznych i hybrydowych, ponieważ kursy na automatach cieszą się mniejszym\\nzainteresowaniem wyłącznie przez uciążliwą procedurę usuwania kodu 78. Przyspieszenie\\nnowelizacji da impuls gospodarczy dla sektora OSK i pozwoli na modernizację infrastruktury \\f\\n\\nStrona 212 z 219\\n\\nszkoleniowej w Polsce. 4. Dostosowanie prawa do realiów rynkowych i wykluczenie\\nkomunikacyjne. Manualne skrzynie biegów stają się technologią schodzącą z rynku – w\\nnowych samochodach osobowych stanowią one zdecydowaną mniejszość. Utrzymywanie\\nrestrykcyjnych przepisów uderza w osoby, które z przyczyn losowych (np. konieczność\\nnagłego podjęcia pracy wymagającej jazdy autem służbowym z manualną skrzynią) zostają\\nodcięte od możliwości szybkiej zmiany uprawnień. System oparty na krótkim przeszkoleniu\\nw OSK pozwala elastycznie i szybko reagować na potrzeby rynku pracy, redukując ryzyko\\nwykluczenia zawodowego.\\n\\nUwagi\\ndodatkowe\\n\\nUnia\\nWielkopolan\\n\\n Proponowane brzmienie przepisu Ustawy z dnia 20 czerwca 1997 r. - Prawo o ruchu\\ndrogowym (t.j. Dz. U. z 2024 r. poz. 1251 z późn. zm.):\\nArt. 119 Ustawy - Prawo o ruchu drogowym\\nW art. 119 ust. 3 uchyla się pkt 4.\\nArt. 119 ust. 4 otrzymuje brzmienie:\\n„4. Ośrodek ponosi wydatki na działania na rzecz poprawy bezpieczeństwa ruchu drogowego\\nna obszarze województwa, w szczególności na popularyzację zasad ruchu drogowego oraz\\npodnoszenie kultury jazdy kierowców”.\\nPo ust. 4 dodaje się ust. 4a w brzmieniu:\\n„4a. Wydatki, o których mowa w ust. 4, mogą być finansowane ze środków zgromadzonych\\nna funduszu zapasowym ośrodka.”\\nUzasadnienie:\\nProjektowana zmiana ma na celu zwiększenie efektywności wykorzystania środków\\nfinansowych zgromadzonych przez wojewódzkie ośrodki ruchu drogowego oraz\\nwzmocnienie realizacji ustawowych zadań związanych z poprawą bezpieczeństwa ruchu\\ndrogowego.\\nObecne przepisy, które określają szczegółowe warunki gospodarki finansowej wojewódzkich\\nośrodków ruchu drogowego są zawarte w Rozporządzeniu Ministra Infrastruktury z dnia 3\\nlipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego\\nośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów\\nzwiązanych z działalnością ośrodka (Dz. U. poz. 1376). Rozporządzenie to zastąpiło\\npoprzednio obowiązujący akt, tj. Rozporządzenie Ministra Infrastruktury z dnia 2\\npaździernika 2002 r. w sprawie szczegółowych warunków gospodarki finansowej \\f\\n\\nStrona 213 z 219\\n\\nwojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji\\nprzychodów i kosztów związanych z działalnością ośrodka (Dz. U. Nr 176, poz. 1443) i\\nwprowadziło zmianę w zakresie przeznaczenia funduszu zapasowego.\\n\\nZgodnie z treścią § 5 poprzednio obowiązującego Rozporządzenia, fundusz zapasowy był\\nprzeznaczony do dyspozycji ośrodka na finansowanie działalności, o której mowa w art. 117\\nust. 1 i 2 ustawy - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251), a zatem również\\nna potrzeby szeroko rozumianej działalności oświatowej dot. bezpieczeństwa w ruchu\\ndrogowym oraz realizacji innych, doniosłych zadań z zakresu tego bezpieczeństwa. Obecnie\\nnatomiast, zgodnie z aktualnym Rozporządzeniem, fundusz zapasowy może być\\nprzeznaczony jedynie na pokrycie strat netto ośrodka. W praktyce oznacza to, że środki\\nzgromadzone w funduszu zapasowym pozostają niewykorzystane do czasu wystąpienia\\nujemnego wyniku finansowego, niezależnie od istniejących potrzeb w zakresie realizacji\\ndziałań służących poprawie bezpieczeństwa ruchu drogowego. Jednocześnie działania na\\nrzecz poprawy bezpieczeństwa ruchu drogowego stanowią jedno z podstawowych zadań\\nwojewódzkich ośrodków ruchu drogowego, wynikających bezpośrednio z ustawy. Nie mają\\none charakteru działalności dodatkowej ani fakultatywnej, lecz pozostają integralnym\\nelementem misji publicznej realizowanej przez te podmioty.\\nBrak jest dostatecznego uzasadnienia dla utrzymywania stanu, w którym środki\\nzgromadzone przez ośrodek pozostają zarezerwowane wyłącznie na pokrycie potencjalnych\\nprzyszłych strat, podczas gdy mogą zostać wykorzystane do realizacji ustawowych zadań\\nsłużących ograniczaniu liczby wypadków drogowych, zwiększaniu świadomości uczestników\\nruchu drogowego oraz podnoszeniu poziomu bezpieczeństwa na drogach. Proponowane\\nrozwiązanie wychodzi z założenia, że środki funduszu zapasowego powinny służyć nie tylko\\nochronie stabilności finansowej ośrodka, lecz również wspierać realizację celów publicznych,\\ndla których wojewódzkie ośrodki ruchu drogowego zostały utworzone. Umożliwienie\\nfinansowania działań na rzecz bezpieczeństwa ruchu drogowego ze środków funduszu\\nzapasowego pozwoli na bardziej racjonalne i efektywne gospodarowanie zgromadzonym\\nmajątkiem, przy jednoczesnym zachowaniu bezpieczeństwa finansowego jednostek.\\nPowrót do finansowania wydatków, w części przeznaczonej na poprawę bezpieczeństwa\\nruchu drogowego z funduszu zapasowego, bez wątpienia umożliwiłby zwiększenie\\nskuteczności i efektywności pomocy m.in. placówkom edukacyjno-oświatowym\\nprzygotowującym dzieci i młodzież do świadomego i bezpiecznego udziału w ruchu \\f\\n\\nStrona 214 z 219\\n\\ndrogowym na terenie naszego kraju, a ponadto znacząco odciążyłby fundusz z bieżącej\\ndziałalności ośrodków.\\n\\nProjektowana regulacja nie zmienia charakteru funduszu zapasowego jako instrumentu\\nwzmacniającego stabilność finansową ośrodka, lecz rozszerza katalog dopuszczalnych\\nsposobów jego wykorzystania o finansowanie działań pozostających w bezpośrednim\\nzwiązku z ustawowymi zadaniami wojewódzkich ośrodków ruchu drogowego. Rozwiązanie\\nto zapewni możliwość przeznaczania wypracowanych przez ośrodki nadwyżek finansowych\\nna cele służące interesowi publicznemu, bez konieczności oczekiwania na wystąpienie\\nokoliczności uzasadniających pokrywanie strat.\\nNależy jeszcze raz podkreślić, że finansowanie działań na rzecz poprawy bezpieczeństwa\\nruchu drogowego ze środków funduszu zapasowego nie stanowi przeznaczenia tych\\nśrodków na cele niezwiązane z działalnością ośrodka. Przeciwnie, środki te byłyby\\nwykorzystywane na realizację zadań ustawowo przypisanych wojewódzkim ośrodkom ruchu\\ndrogowego. Proponowana zmiana prowadzi zatem do silniejszego powiązania sposobu\\nwykorzystania wypracowanych nadwyżek finansowych z podstawowymi celami działalności\\nośrodków, a tym samym wzmacnia funkcjonalny związek pomiędzy gospodarką finansową\\nośrodka, a realizacją powierzonych mu zadań publicznych.\\n\\nUwagi\\ndodatkowe\\n\\nKrajowe\\nStowarzyszenie\\nEgzaminatorów\\n\\nZAGADNIENIA\\nKRAJOWEGO STOWARZYSZENIA EGZAMINATORÓW\\nwymagające pilnego podjęcia prac oraz wprowadzenia zmian przy okazji procedowanego\\nprojektu:\\n\\n1. Art. 24 – dodanie do pojazdów wykorzystywanych do szkolenia i egzaminowania osób\\nniepełnosprawnych oraz czterokołowców lekkich wykorzystywanych w ramach kat. AM prawa\\njazdy wymogu przystosowania do nauki jazdy. Na dzień dzisiejszy w przypadku pojazdu\\nbędącego własnością osoby niepełnosprawnej, dopuszcza się pojazdy bez dodatkowych\\nlusterek, bez dodatkowego pedału hamulca, a jedyne wymaganie to oznakowanie tablicą „L”.\\nStanowi to zagrożenia zarówno dla instruktora jak i egzaminatora;\\n\\n2. Art. 55 ust. 3. Dodanie zapisu dotyczącego przerwania egzaminu praktycznego w przypadku\\nnieprawidłowego prowadzenia przez kandydata na egzaminatora - na dzień dzisiejszy \\f\\n\\nStrona 215 z 219\\n\\nkandydat na egzaminatora w ramach praktyk ma „przeprowadzić”, a nigdzie nie ma zapisu o\\nprawidłowym przeprowadzeniu egzaminów;\\n\\n3. Art. 56 ust. 7 – skreślenie ustępu 7 – WORD-y ponoszą dodatkowe koszty zapewnienia\\nosobom egzaminowanym tłumacza języka migowego. Dodatkowo brak spójności z przepisami\\ndotyczącymi tłumaczy języków obcych, których zapewniają osoby egzaminowane;\\n4. Art. 56a – wprowadzenie corocznej waloryzacji wysokości opłat za prowadzenie egzaminów\\npaństwowych o wskaźnik inflacji ogłaszany przez GUS. Dodatkowo należałoby rozważyć\\nwaloryzacje opłat za inne szkolenia prowadzone przez WORD-y oraz powrót do stawek\\njednolitych na terenie całej Polski;\\nNależało by również podnieść obecne kwoty określone w tym artykule, aby były adekwatne\\ndo dzisiejszych czasów tj. cytuje:\\nArt. 56.1  pkt 2\\n2) 250 zł w zakresie uprawnień prawa jazdy kategorii B+E, C1+E, C, C+E, D, D+E lub D1+E.\\n Przelicznik powinien być np. uzależniony od kwoty za egzamin na kategorie B tzn.\\n9 egzaminów na kategorie B po np. 230 złotych daje nam kwotę 2070 złotych.\\nPowyższą kwote 2070 dzielimy na 5 egzaminów w zakresie  kategorii  C+E co daje nam 414\\nzłoty.\\nKwote 2070 złotych możemy podzielic na 6 egzaminów w zakresie prawa jazdy kategorii\\nA,A2,A1,C, B+E i T co daje nam kwote bazową 345 złotych.\\nProponujemy podwyższenie ceny za egzamin na kwalifikacje lub zrównanie jej z ceną\\negzaminu teoretycznego.\\n5.  Art. 56c – wprowadzenie podpunktu dotyczącego corocznej waloryzacji wynagrodzeń\\negzaminatorów przeprowadzających egzaminy państwowe o wskaźnik inflacji ogłaszany przez\\nGUS;\\n6. Art. 58 ust. 1 pkt 1 – przywrócenie zapisu dotyczącego wykształcenia wyższego (o czym\\npisaliśmy przy art. 33 dotyczącym wykształcenia instruktora) i dodatkowo rozważenie\\npodniesienia wymagania z pkt 2 np. na 5 lat posiadania prawa jazdy. Powrót wykształcenia\\nwyższego podniósłby kompetencje egzaminatorów;\\n7. Art. 58 ust. 1 pkt 8 – doprecyzowanie przepisów dotyczących rękojmi należytego\\nwykonywania swoich obowiązków.\\n8. Art. 59 wprowadzenie pkt 5) o treści: B jest uprawniony do egzaminowania w zakresie\\nprawa jazdy kat AM w przypadku egzaminu realizowanego czterokołowcem lekkim – egzamin \\f\\n\\nStrona 216 z 219\\n\\nAM czterokołowcem lekkim w pr aktyce, poza czasem, wygląda jak egzamin w zakresie\\nkategorii B1 oraz B, a na dzień dzisiejszy WORD-y są zobowiązane do zapewnienia\\negzaminatora z uprawnieniami do kategorii A;\\n9. Art. 61 ust. 3 pkt 3 – modyfikacja zapisu zmniejszająca wymaganie dotyczące uczestnictwa\\nw charakterze obserwatora egzaminów teoretycznych do 10 z równoczesnym podniesieniu\\ndo 30 w przypadku egzaminów praktycznych ( dotyczy uprawnien  kategorii B). Dodanie zapisu\\ndotyczącego prawidłowego przeprowadzenia 10 egzaminów - na dzień dzisiejszy\\negzaminatorem może zostać osoba, która w ramach praktyk nie przeprowadziła prawidłowo\\nani jednego egzaminu;\\n10. Art. 62 ust 1 – dodanie legitymacji egzaminatora do m-Obywatela;\\n11. Art. 64 – określenie zasad wynagradzania komisji weryfikacyjnej;\\n12. Art. 68 ust. 3 – dodanie zapisu o wymogu każdorazowego przesłania wyjaśnień\\negzaminatora, który prowadził zaskarżony egzamin;\\n13. Dopuszczenie do egzaminów teoretycznych możliwości uczestnictwa tłumacza\\nprzysięgłego języka obcego. Od wejścia ustawy o kierujących zabronione jest uczestnictwo\\ntłumacza co w istotny sposób utrudnia obcokrajowcom zdanie egzaminu teoretycznego.\\nTłumacz jest na egzaminie praktycznym, a na teorii już nie. Przepisy dopuszczają egzamin\\nteoretyczny tylko dla jednej osoby, ale tylko w przypadku dyslektyków, gdzie drugi\\negzaminator czyta pytania i odpowiedzi. W analogiczny sposób powinno się dopuszczać\\negzaminy z tłumaczem przysięgłym języka obcego. W przypadku egzaminu dla dyslektyków\\npowinno dopuścić sie wydłużenie czasu na przeczytanie pytania.  Wówczas można pominąć\\ndrugiego egzaminatora.\\n14. Umożliwienie przeprowadzania części praktycznej egzaminu praktycznego na kat A,B poza\\ngranicami miasta w którym zlokalizowany jest WORD. Obecne ograniczenie utrudnia\\nprzeprowadzanie egzaminów praktycznych ze względu na ograniczenia infrastruktury\\nszczególnie w oddziałach terenowych umiejscowionych w mniejszych miejscowościach.\\n15. Zmiana zapisów dotyczących zadań wykonywanych na egzaminie praktycznym w ruchu\\ndrogowym – w obecnym systemie prawnym egzamin sprowadza się do jeżdżenia tymi samymi\\ntrasami nie w celu sprawdzenia umiejętności kandydatów na kierowców, a celem wykonania\\nzadań egzaminacyjnych. Zmiana zapisu umożliwi egzaminatorom znacznie lepszy dobór tras\\negzaminacyjnych oraz ograniczy protesty mieszkańców związane z ilością przejazdów\\npojazdów egzaminacyjnych, co za tym idzie również szkoleniowych, tymi samymi ulicami; \\f\\n\\nStrona 217 z 219\\n\\n16.  Zmiana programu szkolenia kandydatów na egzaminatorów oraz egzaminatorów\\npodnoszących uprawnienia; obecny program nie przygotowuje do pracy w zawodzie\\negzaminatora. Nacisk kładzie się na zagadnienia zupełnie nieprzydatne w pracy egzaminatora,\\na brakuje solidnej części praktycznej\\n17. Wprowadzenie obowiązkowych zajęć w ośrodku doskonalenia techniki jazdy w ramach\\nszkolenia podstawowego lub powrót do planowanego z zagrożeń (tak jak jest to w Szwecji), a\\nostatecznie wykreślonego szkolenia miedzy 4 a 8 miesiacem – kształtowanie właściwych\\npostaw przyszłego kierującego pod kątem właściwego przygotowania pojazdu do jazdy,\\nwarunków decydujących o zachowaniu pojazdu w warunkach specjalnych (nawierzchnia o\\nróżnej przyczepności)\\n\\n OSR Polska\\nWytwórnia\\nPapierów\\nWartościowych\\nS.A.\\nOcena Skutków Regulacji powinna zostać uzupełniona\\no wskazanie:\\n1) źródła finansowania i wysokości środków finansowych, jakie PWPW S.A. będzie musiała\\nponieść w związku\\nz koniecznością dokonania:\\na) w przypadku nieuwzględnienia uwagi z poz. 1 - integracji systemu\\nteleinformatycznego, o którym mowa w art. 16a ust. 1 ustawy, z nowym systemem\\nteleinformatycznym, który ma zostać zbudowany\\ni utrzymywany przez ministra właściwego do spraw informatyzacji; przepisy projektu\\nprzewidują bowiem obowiązek takiej integracji (np. projektowane brzmienie art. 2\\npkt 5 ustawy), nie przewidując jednak żadnych środków finansowych na pokrycie\\nkosztów tej czynności,\\nb) modyfikacji systemu teleinformatycznego, o którym mowa w art. 16a ust. 1 ustawy,\\nw związku\\n z rozszerzeniem jego funkcjonalności (np. projektowane brzmienie art. 53b ust. 1\\nustawy);\\n2) źródła finansowania i wysokości środków finansowych przeznaczonych na zakup i\\nutrzymanie:\\na) urządzeń lokalizujących rejestrujących trasę jazdy, \\f\\n\\nStrona 218 z 219\\n\\nb) urządzeń do rejestracji obrazu i dźwięku z części praktycznej egzaminu\\nwewnętrznego,\\nserwerów niezbędnych do przechowywania danych z urządzeń wskazanych w lit. a i b.\\n\\nUzupełnienie Oceny Skutków Regulacji o wskazane informacje.\\n OSR Polski Związek\\nNiewidomych Uzupełnienie Oceny Skutków Regulacji\\n17. Wskazanie osób o szczególnych potrzebach jako grupy oddziaływania\\nAktualna propozycja zawarta w UD402\\nW tabeli podmiotów, na które oddziałuje projekt, wymieniono między innymi kandydatów\\nna kierowców, instruktorów, egzaminatorów, zarządców dróg, operatorów oraz\\nużytkowników mikromobilności.\\nNie wskazano natomiast osób niewidomych, słabowidzących ani innych pieszych o\\nszczególnych potrzebach jako odrębnej grupy oddziaływania.\\nPropozycja PZN\\nPZN proponuje uzupełnić tabelę OSR o następującą grupę:\\nGrupa:\\nosoby niewidome i słabowidzące, osoby z ograniczoną mobilnością, osoby starsze oraz inni\\npiesi o szczególnych potrzebach.\\nOddziaływanie:\\npotencjalna poprawa bezpieczeństwa i dostępności przestrzeni pieszej, uzależniona od\\nprawidłowego wyznaczenia miejsc postojowych, skutecznej kontroli operatorów i szybkiego\\nusuwania przeszkód; ryzyko negatywnego oddziaływania w przypadku lokalizowania stref na\\ntrasach wolnych od przeszkód, oznaczeniach fakturowych lub naturalnych liniach\\nprowadzących.\\nUzasadnienie \\f\\n\\nStrona 219 z 219\\n\\nOsoby te są bezpośrednimi beneficjentami regulacji. Mogą jednak ponieść również\\nnegatywne skutki, jeżeli miejsca postojowe zostaną wyznaczone w sposób niewłaściwy.\\n18. Uzupełnienie OSR o koszty skutecznego wykonywania obowiązków\\nAktualna propozycja zawarta w UD402\\nOSR wskazuje ogólnie, że operatorzy mogą ponosić koszty dostosowania flot i aplikacji, a\\nzarządcy dróg koszty związane z wyznaczeniem miejsc.\\nNie obejmuje natomiast kosztów pełnego systemu egzekwowania nowych zasad.\\nPropozycja PZN\\nOSR należy uzupełnić o analizę kosztów:\\n1. dostosowania systemów lokalizacyjnych operatorów;\\n2. weryfikacji sposobu parkowania;\\n3. obsługi dostępnego systemu zgłoszeń;\\n4. relokacji pojazdów;\\n5. przekazywania danych zarządcom dróg;\\n6. kontroli wykonywania obowiązków przez operatorów;\\n7. dostosowania istniejących miejsc postojowych do wymagań dostępności;\\n8. przeprowadzenia przeglądu istniejących stref.\\nUzasadnienie\\nBez określenia rzeczywistych obowiązków i kosztów ich wykonywania nie można rzetelnie\\nocenić wykonalności projektowanej regulacji.\",\"sha256\":\"fb960cb5057d1cfd065f7493aa860fee01ca6bd83991eef4f24c0f2e587b9137\",\"normalized_sha256\":\"text-v2:b89248955e9a6ef543f83a90c8b4b1a7740e401b523d965445b5e036769c848b\",\"complete\":true,\"file_sha256\":\"2a972b48b82bf74fdf4e2c68ebca1e9bed898080c816b5201ca867afce4dbddd\",\"author\":\"Minister Infrastruktury\"},{\"identity\":\"rcl/801498\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212212/dokument801498.docx\",\"role\":\"response\",\"text\":\"\\t\\nTabela uwag zgłoszonych w ramach konsultacji publicznych projektu ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw \\n(UD 402)\\n\\n(według kolejności jednostek redakcyjnych projektu ustawy)\\n\\nlp\\tJednostka redakcyjna projektu \\tPodmiot zgłaszający uwagę\\tTreść uwagi\\tSposób rozpatrzenia uwagi/uzasadnienie\\n1\\t2\\t3\\t4\\t5\\n\\tArt. 1 pkt 1 i pkt 3 projektu ustawy \\tPolska Wytwórnia Papierów Wartościowych S.A.\\t\\tWątpliwości budzi proponowane przez projektodawcę rozwiązanie, aby wszelkie usługi związane ze szkoleniem kandydatów na kierowców były świadczone „w systemie teleinformatycznym zapewnionym przez ministra właściwego do spraw informatyzacji, zintegrowanym z systemem, \\no którym mowa w art. 16a”. Zaproponowane w projekcie ustawy rozwiązania związane z postępującą cyfryzacją są rozwinięciem istniejących już rozwiązań w zakresie obsługi procesu wnioskowania, szkolenia i egzaminowfizycznaania kandydatów na kierowców i kierowców, które są obecnie realizowane za pomocą profilu kandydata na kierowcę (PKK), o którym mowa w art. 2 pkt 3 ustawy, oraz profilu kierowcy zawodowego (PKZ), o którym mowa w art. 2 pkt 4 ustawy. PKK oraz PKZ są obsługiwane przy użyciu systemu teleinformatycznego, o którym mowa w art. 16a ustawy, tj. systemu teleinformatycznego zapewnianego przez wytwórcę praw jazdy, kart kwalifikacji kierowcy i pozwoleń na kierowanie tramwajem. Istniejące rozwiązania, funkcjonujące i sprawdzone od wielu lat, są kompletne i zapewniają pełną kontrolę nad uzyskiwaniem określonych rodzajów uprawnień, a także zapewniają integralność i poufność danych, w tym danych w postaci elektronicznej.  \\t\\nZ uwagi na powyższe wprowadzenie rozwiązania opartego na „cyfrowej karcie kursanta” jest jedynie modyfikacją (rozwinięciem) istniejącego systemu teleinformatycznego, \\fo którym mowa w art. 16a ustawy. Brak jest zatem uzasadnienia, w szczególności ekonomicznego, dla konieczności budowania odrębnego „systemu teleinformatycznego zapewnianego przez ministra właściwego do spraw informatyzacji” do budowania alternatywnego w stosunku do istniejącego rozwiązania.  \\t \\tWymaga wskazania, że aktualnie czynności związane ze składaniem wniosku o wydanie uprawnień są świadczone \\nw ramach usług elektronicznych w Portalu e-usług, który jest utrzymywany przez PWPW S.A. Portal ten został zbudowany z wykorzystaniem środków z Krajowego Planu Odbudowy \\ni Zwiększania Odporności w zakresie wniosku projektowego „Uzyskanie uprawnień na Prawo Jazdy lub Kartę Kwalifikacji Kierowcy, możliwość sprawdzenia statusu sprawy wydania PJ/KKK w urzędzie lub statusu obsługi PKK/PKZ”. PWPW S.A. została zobowiązana do utrzymania trwałości tego projektu przez okres 5 lat od dnia jego uruchomienia (tj. od maja 2026 r.). Nie ma zatem przeszkód technicznych, aby „cyfrowa karta kierowcy” była dostępna w tym rozwiązaniu. Cyfrowa karta kierowcy może zostać także udostępniona dla ośrodków szkolenia kierowców poprzez istniejące API dla podmiotów dostarczających rozwiązania dedykowane dla tych ośrodków. \\t \\tWobec powyższego należy wskazać, że przyjęcie rozwiązania, że „cyfrowa karta kursanta” będzie obsługiwana przez istniejący system teleinformatyczny, o którym mowa w art. 16a ustawy, zapobiegnie nieefektywnemu wydatkowaniu środków publicznych, skoro Portal e-usług, zbudowany z wykorzystaniem środków Krajowego Planu Odbudowy i Zwiększania Odporności, musi być utrzymywany przez PWPW S.A. przez blisko 5 lat. \\t \\tWymaga podkreślenia, że PWPW S.A. dysponuje projektem technicznym i gotową dokumentację do wdrożenia rozwiązania związanego z „cyfrową kartą kursanta” co do większości planowanych funkcjonalności (projekt oraz dokumentacja nie obejmują jedynie obsługi zapisów z kamer z ośrodków szkolenia kierowców). Wobec powyższego PWPW S.A. \\fbyłaby gotowa do wdrożenia tych rozwiązań nawet w terminie 6 miesięcy od dnia wejścia w życie ustawy (zamiast projektowanych obecnie 2 lat od dnia wejścia w życie ustawy). \\tNiezależnie od powyższej uwagi ogólnej należy wskazać, że: \\twprowadzenie „indywidualnego numeru kursanta” jest \\nw praktyce zdublowaniem istniejących funkcjonalności \\nw ramach profilu kandydata na kierowcę (PKK), o którym mowa w art. 2 pkt 3 ustawy, oraz profilu kierowcy zawodowego (PKZ), o którym mowa w art. 2 pkt 4 ustawy; z tego powodu z projektu należy skreślić przepis formułujący definicję tego pojęcia; \\twprowadzenie „indywidualnego numeru instruktora” jest zbędne, ponieważ już aktualnie instruktorom są nadawane numeru ewidencyjne przez starostów (art. 33 ust. 2 pkt 2 ustawy), a numery te są gromadzone \\nw systemie teleinformatycznym, o którym mowa w art. 16a ustawy; przepis formułujący tę definicję także należy skreślić. \\t \\tPropozycja przepisów: projektowanej definicji cyfrowej karty kursanta proponuje się nadać brzmienie: „5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym, instruktora, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu szkolenia w zakresie nauki jazdy i części praktycznej egzaminu wewnętrznego, utworzony, udostępniany, aktualizowany i archiwizowany \\nw systemie teleinformatycznym, o którym mowa \\nw art. 16a ust. 1.”;  z projektu należy wykreślić projektowane brzmienie art. 2 pkt 6 i 7 ustawy, co będzie skutkowało rezygnacją z formułowania definicji „indywidualnego numeru kursanta” oraz „indywidualnego numeru instruktora”;  projekt ustawy należy uzupełnić o nowelizację art. 16a ustawy poprzez dodanie po ust. 1 ust. 1a w brzmieniu: „1a. System teleinformatyczny, o którym mowa \\nw ust. 1, umożliwia także założenie i prowadzenie cyfrowej karty kursanta.”;  projektowany art. 23d ust. 1 ustawy powinien otrzymać brzmienie: „1. Po zakończeniu zajęć w zakresie nauki jazdy lub części praktycznej egzaminu wewnętrznego osoba ubiegająca się o uprawnienia do kierowania pojazdem silnikowym może wprowadzić w cyfrowej karcie kursanta uwagi, o których mowa w art. 23c ust. 1 pkt 1 lit. k lub pkt 2 lit. k oraz potwierdzić albo odmówić potwierdzenia przebiegu szkolenia lub części praktycznej egzaminu wewnętrznego poprzez wprowadzenie indywidualnego numeru kursanta. Dane i informację są wprowadzane \\nz wykorzystaniem systemu teleinformatycznego, o którym mowa w art. 16a, oraz narzędzi teleinformatycznych wykorzystywanych przez ośrodki szkolenia kierowców zintegrowane \\nz systemem, o którym mowa w art. 16a.”;  projektowany art. 23d ust. 3 ustawy powinien otrzymać brzmienie: „3. Instruktor może sprostować dane i informacje,  o których mowa w art. 23c ust. 1 pkt 1 lit. c–f, i oraz  j lub pkt 2 lit. c–f oraz h–j, zarejestrowane  w cyfrowej karcie kursanta, po uzyskaniu zgody osoby ubiegającej się o uprawnienia do kierowania pojazdem silnikowym, potwierdzonej przez wprowadzenie indywidualnego numeru kursanta. Dane i informację są wprowadzane  z wykorzystaniem systemu teleinformatycznego,  o którym mowa w art. 16a, oraz narzędzi teleinformatycznych wykorzystywanych przez ośrodki szkolenia kierowców zintegrowane \\nz systemem, o którym mowa w art. 16a.”.  \\fprojektowane brzmienie art. 27 ust. 4b ustawy powinno otrzymać brzmienie: „4b. Wydanie zaświadczenia o ukończeniu szkolenia, o którym mowa w ust. 4, następuje przez wprowadzenie danych o jego wydaniu do profilu kandydata na kierowcę.”;  \\t7) z projektu należy wykreślić zmianę projektowaną w art. 1 pkt 5 lit. d projektu. \\t\\fMając na uwadze istotny zakres zmian wprowadzonych do projektu ustawy w wyniku przeprowadzonych konsultacji, nowe brzmienie projektowanej regulacji zostało skierowane do ponownych konsultacji publicznych. Stanowiska i uwagi zgłoszone w ich toku zostaną przeanalizowane, a odniesienie się do nich nastąpi w odrębnej tabeli uwag zgłoszonych w ramach konsultacji publicznych.\\n\\tArt. 1 pkt 1 projektu ustawy  \\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 1 budzi wątpliwość kwestia konieczności centralnego zapewnienia systemu teleinformatycznego. Dotychczasowe doświadczenia w tych obszarach generują obawę o ryzyko niezrozumienia intencji autorów Projektu. Obecne możliwości techniczne na pewno pozwalają na zapewnienie odpowiedniego standardu cyfrowego dokumentowania procesu szkolenia bez ryzyka nadmiernych regulacji – w szczególności na poziomie ustawowym. \\t\\n\\tArt. 1 pkt 1 projektu ustawy  \\tPolski Związek Szkoleniowy\\t18) Biorąc pod uwagę, że w proponowanych przepisach zakładamy, że indywidualny numer instruktora będzie generowany w aplikacji mObywatel oznacza to, że powstanie jedna baza danych zbierająca wszystkich instruktorów nauki jazdy z której będzie korzystał mObywatel. Zatem rozwiązany zostanie problem uniemożliwiający dotychczas przeniesienie legitymacji instruktorów nauki jazdy do aplikacji mObywatel. W naszej ocenie należy rozważyć wprowadzenie zmian likwidujących papierową legitymacje instruktora nauki jazdy i pozostawienie jej wyłącznie jako dokumentu elektronicznego w aplikacji mObywatel. Takie działanie rozwiąże szereg problemów z tym dokumentem (np. jego wielkość) i pozwoli jednocześnie na bieżące sprawdzanie czy dany instruktor posiada aktualne uprawnienia. Przy odpowiednim wykorzystaniu automatyki w cyfrowej karcie kursanta będzie można całkowicie zapobiec prowadzeniu szkoleń przez osoby nieposiadające uprawnień.  \\t\\n\\tArt. 1 pkt 1 i pkt 3 projektu ustawy  \\tOgólnopolska Izba Gospodarcza Ośrodków Szkolenia Kierowców (OIGOSK), \\fPolska Federacja Stowarzyszeń Szkół Kierowców (LFEDERACJA), Polska Izba Gospodarcza Ośrodków Szkolenia Kierowców (PIGOSK) \\t\\fWnosimy o odstąpienie na tym etapie od obowiązkowego wprowadzania „cyfrowej karty kursanta”, a w konsekwencji „indywidualnego numeru kursanta” oraz „indywidualnego numeru instruktora”. Uzasadnienie W ocenie skutków regulacji można znaleźć stwierdzenie, że analiza funkcjonowania obecnego systemu wskazuje deficyt w postaci braku skutecznych mechanizmów weryfikacji rzeczywistego przebiegu szkolenia praktycznego osób ubiegających się o uprawnienia do kierowania pojazdami. Nie wykazano jednak w jakim procencie szkoleń występują nieprawidłowości, założono domniemanie nieuczciwości przedsiębiorców. Projekt obejmuje wszystkich przedsiębiorców systemem stałego nadzoru, \\fmimo że zdecydowana większość prowadzi działalność zgodnie z prawem. Kontrola powinna koncentrować się na podmiotach naruszających przepisy, a nie obejmować wszystkich. Projekt przewiduje rejestrowanie trasy każdej jazdy, czasu jej trwania i innych danych pozwalających odtworzyć historię przemieszczania się kursantów i instruktorów. Tak daleko idąca ingerencja w prywatność nie została należycie uzasadniona. Projekt budzi poważne wątpliwości w świetle art. 31 ust. 3, art. 47 oraz art. 51 ust. 2 Konstytucji RP. Nie wykazano, że obowiązkowe gromadzenie danych o lokalizacji wszystkich kursantów i instruktorów jest środkiem koniecznym oraz najmniej ingerującym w prawa obywateli. Możliwość odbycia szkolenia zostaje uzależniona od posiadania smartfona, aplikacji mobilnej i dostępu do Internetu, choć prawo nie nakłada na obywateli obowiązku posiadania takich urządzeń. Projekt nie uwzględnia awarii telefonu, braku zasięgu GPS (zjawisko powszechne przy lotniskach, obiektach wojskowych czy przy granicy z Rosją i Białorusią w obecnej napiętej sytuacji w związku z wojną w Ukrainie), utraty Internetu ani sytuacji osób zagrożonych wykluczeniem cyfrowym. Projekt przewiduje gromadzenie dużej ilości danych lokalizacyjnych bez przedstawienia przekonującej analizy ryzyka ich wycieku lub nieuprawnionego wykorzystania. Cyfryzacja procesu szkolenia kierowców jest kierunkiem pożądanym, jednak nie może prowadzić do powszechnego monitorowania obywateli, uzależnienia szkolenia od posiadania prywatnego urządzenia elektronicznego ani przerzucania ryzyka awarii systemów na przedsiębiorców i kursantów. Projekt wymaga istotnych zmian, aby zachować zgodność z zasadą proporcjonalności, ochroną prywatności oraz równego dostępu do szkolenia. W pełni popieramy i utożsamiamy się z publikowanym postulatem prowadzenia „pilotażu” przed wdrożeniem Cyfrowej karty kursanta do systemu prawnego RP, link https://www.prawodrogowe.pl/informacje/news-tygodnia/jakub-grabowski-czy-cyfrowa-karta- kursanta-powinna-przejsc-pilot Najpierw sprawdźmy, potem wdrażajmy. Cyfrowa karta kursanta powinna przejść pilotaż w prawdziwym OSK. Propozycja ta zdecydowanie zasługuje na rozwinięcie. Zanim cyfrowa karta kursanta, rejestrowanie tras jazd, dwustronne potwierdzanie zajęć staną się obowiązkiem wszystkich ośrodków szkolenia kierowców, należy sprawdzić te rozwiązania w praktyce. Nie na papierze. Nie wyłącznie podczas konsultacji przy ministerialnym stole. W prawdziwej szkole jazdy, z prawdziwymi instruktorami, kursantami, samochodami, problemami z zasięgiem, rozładowanym telefonem i napiętym grafikiem jazd. Taki pilotaż pokaże, czy projektowany system rzeczywiście zwiększy rzetelność szkolenia, czy też stworzy problemy, których dzisiaj jeszcze nie jesteśmy w stanie przewidzieć.\\t\\n\\tArt. 1 pkt 1 i pkt 3 projektu ustawy\\tZrzeszenie Międzynarodo-wych Przewoźników Drogowych\\tObawy budzą również projektowane rozwiązania dotyczące cyfrowej karty kursanta oraz obowiązku rejestrowania obrazu i dźwięku z praktycznej części egzaminu wewnętrznego. Ich wdrożenie będzie wymagało od ośrodków szkolenia kierowców zapewnienia odpowiedniego zaplecza technicznego, obejmującego w szczególności urządzenia lokalizacyjne, urządzenia służące do rejestracji obrazu i dźwięku, a także narzędzia umożliwiające instruktorowi i kursantowi sprawne wprowadzanie oraz potwierdzanie danych w cyfrowej karcie kursanta. Wprowadzenie tych rozwiązań będzie wiązało się nie tylko z kosztami zakupu lub dostosowania urządzeń, lecz także z wydatkami na ich utrzymanie, obsługę i serwisowanie. W praktyce koszty te zostaną uwzględnione przez ośrodki szkolenia kierowców w cenach kursów, a więc ostatecznie poniosą je osoby ubiegające się o uzyskanie uprawnień. Tym samym projektowane obowiązki doprowadzą do dalszego wzrostu kosztów szkolenia. Wzrost kosztów szkolenia może być szczególnie dotkliwy dla osób ubiegających się o uzyskanie kategorii wymaganych do wykonywania zawodu kierowcy. Już obecnie średnia cena kursu na prawo jazdy kategorii B w mieście wojewódzkim wynosi 4150 zł (w Warszawie 4740 zł). W przypadku kategorii zawodowych, po uwzględnieniu kosztów kursów na odpowiednie kategorie prawa jazdy, wymaganych szkoleń oraz uzyskania kwalifikacji zawodowej, łączny wydatek może przekraczać 12 000 zł. Koszty te stanowią istotną barierę wejścia do zawodu, a ich dalszy wzrost może ograniczać liczbę nowych kandydatów i pogłębiać trudności kadrowe przedsiębiorstw transportowych, zwłaszcza w warunkach utrzymującego się deficytu kierowców zawodowych.\\t\\n\\t Art. 1 pkt 1 projektu ustawy w zakresie art. 2 pkt 5-7 ustawy o kierujących pojazdami\\t Związek Pracodawców  „Transport i Logistyka Polska”\\t Ad art. 1 pkt 1 projektu wprowadzający zmiany w art. 2 pkt 5-7 UoKP  Zaproponowane definicje „cyfrowej karty kursanta” „indywidualnego numeru kursanta” i „indywidualnego numeru instruktora” budzą poważne wątpliwości zarówno z merytorycznego, jak i z formalnego punktu widzenia.  W naszej ocenie tego typu propozycje stanowią klasyczny przykład nadmiernej regulacji, tworzącej tzw. nadmiarowe byty. Jeśli intencją projektodawcy jest zapisywanie danych i informacji o przebiegu szkolenia, to w ocenie TLP, wystarczający byłby ustanowiony w odrębnej jednostce redakcyjnej, w rozdziale odnoszącym się do szkolenia, przepis określający:  obowiązkowe przetwarzanie odpowiednich danych dotyczących szkolenia, takich, jak np.: dane identyfikacyjne szkolonej osoby, dane identyfikacyjne oso b prowadzących \\fszkolenie, dane identyfikujące ośrodek szkolenia kierowco w lub inną jednostkę prowadzącą szkolenie, dane identyfikujące pojazd, którym prowadzone jest szkolenie, dane i informacje dotyczące rozpoczęcia i zakończenia poszczególnych jednostek dydaktycznych, dane geolokalizacyjne pozwalające ustalić trasę pojazdu, którym prowadzone jest szkolenie, etc.,  system teleinformatycznego, w którym przetwarzane będą wymagane dane,  obowiązek wprowadzania wymaganych danych objętych przetwarzaniem w systemie przez instruktora i osobę szkoloną,  obowiązek posiadania lub wyposażenia pojazdu w odpowiednie urządzenie geolokalizacyjne, z którego pobierane będą dane pozwalające ustalić trasę pojazdu,  zasady postępowania w przypadku awarii systemu teleinformatycznego lub urządzenia/systemu geolokalizacyjnego.   Szczegółowe zasady wprowadzania danych i ich przetwarzania powinny być określone w akcie wykonawczym, zważywszy na fakt, iż związane jest to z konkretnymi rozwiązaniami technicznymi, kto re mogą ewaluować m.in. w związku z postępem technicznym. Trudno bowiem w przypadku wprowadzenia zmian na dużym poziomie szczegółowości, za każdym razem zmieniać akt rangi ustawowej  Odnosząc się do danych identyfikacyjnych osób fizycznych (osób szkolonych i szkolących) w polskim systemie prawnym nie ma potrzeby tworzenia nowych „bytów”, gdyż każdą osobę identyfikują takie dane jak imię, nazwisko, data urodzenia, numer PESEL lub numer dokumentu tożsamości. Wydaje się, że z funkcjonalnego punktu widzenia, przepisy rangi wykonawczej powinny wskazywać, iż do potwierdzania wprowadzanych danych używany jest odpowiedni indywidualnie przypisany klucz lub odpowiedni token (cyfrowy identyfikator), wygenerowany przez system na odpowiedni wniosek (kursanta? instruktora? ośrodka szkolenia kierowco w?). Nie ma potrzeby wprowadzania jego definicji na poziomie ustawy.  Tworząc określone obowiązki nie można zapominać , iż system powinien zapewniać także obsługę osób wykluczonych cyfrowo! W szczególności należy pamiętać, iż obywatel UE nie ma obowiązku posiadania i korzystania z takich urządzeń , jak smartfon, tablet, komputer, etc. Pomimo znacznej szczegółowości proponowanych w dalszych przepisach rozwiązań , kwestie te są niestety nierozpoznawalne.  \\fUstanawiając przetwarzanie danych (które nie są danymi produkcyjnymi na użytek producenta dokumentów komunikacyjnych), należałoby przy tym określić :  Podmioty odpowiedzialne, w tym organ prowadzący system, organ odpowiedzialny merytorycznie za proces, administratora danych osobowych, podmiot zapewniający obsługę techniczną, organ sprawujący nadzór, etc. Obecny system prowadzony przez PWPW S.A. - w naszej ocenie - nie spełnia tych wymogów!  Dostęp do systemu i udostępnianie danych, w tym kategorie użytkowników i zakres ich uprawnień, dostęp osoby do własnych danych, zasady dostępu publicznego, tryb udostępniania danych jednostkowych i masowych, możliwość przekazywania danych przez API, odpłatność albo nieodpłatność, zakaz dalszego wykorzystania niezgodnego z celem, obowiązek rejestrowania zapytań , zmian i pobrań etc. Obecny system prowadzony przez PWPW S.A. - w naszej ocenie - nie spełnia tych wymogów!  Jakość danych i prawa osób, (podmiotów) których dane są przetwarzane, a w szczególności: zasady aktualizacji danych, procedurę sprostowania danych nieprawidłowych, uzupełnienie danych niekompletnych, oznaczenie danych spornych, możliwość wstrzymania ich wykorzystywania do czasu wyjaśnienia, powiadomienie odbiorców o korekcie, dostęp do historii zmian, tryb złożenia skargi lub wniosku, organ właściwy do rozpoznania sporu. Obecny system prowadzony przez PWPW S.A. - w naszej ocenie - nie spełnia tych wymogów!  Wskazane wyżej kwestie, wykraczają zbyt daleko od zakresu podmiotowo-przedmiotowego UoKP. Niemniej ich pominięcie byłoby – w naszej ocenie – niezgodne z obowiązującym w tym zakresie systemem prawnym RP i UE. Dlatego też bardziej właściwym wydaje się przygotowanie odrębnego projektu ustawy, który tworzyłby lub sankcjonował odpowiedni system teleinformatyczny, służący m.in. do zamawiania dokumentów.  Ponadto, poważne wątpliwości TLP budzą takie fakty, jak:  Doświadczenia związane z wdrażaniem wcześniejszych rozwiązań teleinformatycznych w procesie uzyskiwania uprawnień do kierowania pojazdami i kwalifikacji zawodowych kierowców („Profil Kandydata na Kierowcę” oraz „Profil Kierowcy zawodowego”) wskazują, że uruchamianiu nowych systemów towarzyszyły problemy organizacyjne i techniczne, które okresowo zakłócały szkolenie i egzaminowanie. Projekt nie przedstawia pełnej analizy łącznych kosztów wcześniejszych wdrożeń ani niezależnego audytu ich efektów. Wydaje się, że wdrożenie ww. rozwiązań w żaden sposób nie przełożyło się na poprawę efektywności systemu uzyskiwania uprawnień do kierowania pojazdami, a \\ftym samym poprawę bezpieczeństwa na polskich drogach. Uzasadnia to ostrożność przy projektowaniu kolejnego narzędzia - „cyfrowej karty kursanta” - oraz potrzebę wykazania jego proporcjonalności, efektywności i odporności na awarie. Należy także przejrzyście opisać rolę dostawcy systemu teleinformatycznego w pracach nad rozwiązaniami prawnymi i technicznymi.  Brak wystarczającej analizy porównawczej. TLP nie zidentyfikowało w dostępnych materiałach rozwiązania europejskiego, kto re łączyłoby dokładny s lad GPS z obustronnym potwierdzaniem każdej jazdy w zakresie odpowiadającym projektowanej „cyfrowej karcie kursanta”. Co prawda we Francji funkcjonuje centralny cyfrowy dziennik szkolenia, a w Portugalii obowiązkowo rejestruje się m.in. czas jazdy, pojazd, instruktora i przejechane kilometry. Niemniej w żadnych z tych państw nie ma rozwiązań, które łączyłoby to z dokładnym śladem GPS i obustronnym potwierdzaniem każdej jazdy. Zaproponowany profil stanowi więc dużo bardziej rozbudowaną, mocno skomplikowaną i ingerującą w prywatność kombinację rozwiązań francuskich i portugalskich. Nie trzeba przy tym dodawać, że koszty inwestycyjne oraz koszty eksploatacyjne nowej funkcjonalności systemu będą nieproporcjonalnie wyższe. Oznacza to, że proponuje się nam bardzo daleko idący i na dodatek kosztowny eksperyment, którego deklarowane cele nie zostały potwierdzone przez przykłady dobrej praktyki, ani tez przez jakiekolwiek prace badawcze.  Koszty społeczne „cyfrowej karty kursanta”. Przy założeniu, iż corocznie szkolonych jest 400 tysięcy osób, a każda z nich odbywa średnio 60 jednostek wymagających potwierdzenia przez osobę szkoloną i instruktora, liczba dodatkowych czynności (wprowadzania i potwierdzania zajęć) mogłaby sięgnąć nawet 48 milionów rocznie. TLP szacuje wynikający z tego wzrost kosztów szkolenia na co najmniej 100 mln zł rocznie. Budzi to bardzo poważne wątpliwości co do zasadności przedłożonych propozycji z punktu widzenia rachunku cost/benefits. Szczególnie, że zaproponowane rozwiązania wydają się być bardzo podatne na fałszerstwa. Wystarczy bowiem, że cyfrowy identyfikator osoby szkolonej zostanie wykorzystywany przez instruktora w porozumieniu z tą osobą.  Znaczne zwiększenie regulacyjnego ryzyka po stronie instruktorów oraz przedsiębiorców prowadzących OSK. Przy 48 milionowej skali wprowadzania danych do odpowiednich rekordów systemu, należy założyć skalę popełnianych błędów ludzkich, na którą dodatkowo mogą się nałożyć błędy zewnętrzne (np. wynikające z odnotowywanych na terytorium Polski, czasowych zakłóceń systemów prowadzących wrogie działania o charakterze hybrydowym). Zazwyczaj przy projektowaniu systemów teleinformatycznych \\fzakłada się występowanie do około 3% błędnie wprowadzanych danych. I nawet jeśli przyszłe rozwiązania techniczne ograniczą ich występowanie do 1%, to nadal ich liczba (480 tysięcy rocznie), skutkować będzie wszczynanymi postępowaniami administracyjnymi, które mogą zakończyć się odebraniem uprawnień do prowadzenia szkolenia (w założeniu zawartym w proponowanych przepisach nie ma możliwości skorygowania błędnie wprowadzonych danych!), Ponadto, niezależnie od ryzyka po stronie prywatnych podmiotów, należy zadać sobie pytanie, czy prowadzący nadzór nad szkoleniem starostowie będą przygotowani organizacyjnie i kadrowo do analizy takiej liczby danych i do podejmowania odpowiednich postępowań administracyjnych. W naszej ocenie zdecydowanie nie, co oznacza jednocześnie, że efektywność proponowanego rozwiązania będzie wynosiła zaledwie kilka procent.  Brak ustalonych zasad odpłatności za obowiązkowe użytkowanie (korzystanie z) systemu. Podobnie jak w przypadku dotychczasowych, obligatoryjnych rozwiązań teleinformatycznych („profil kandydata na kierowcę” i „profil kierowcy zawodowego”), nie ustalono zasad ponoszenia opłat za korzystanie z systemu dla OSK, starostw i innych podmiotów, zobowiązanych do czynności związanych z przetwarzaniem danych w systemie. Powoduje to kuriozalną i dwuznaczną pod względem prawnym sytuację, w której wyznacza się podmiot prowadzący system (dotychczas była to państwowa spółka prawa handlowego), a następnie pośrednio (poprzez przymus korzystania z systemu), zmusza się inne podmioty i organy do zawierania odpłatnych umów z tym wyznaczonym podmiotem – na zasadzie: MUSISZ KORZYSTAĆ, MUSISZ PŁACIĆ TYLE ILE CHCEMY!   Mając na uwadze podniesione wyżej (aczkolwiek nie wyczerpujące pełnego ich katalogu) wątpliwości, zamiast procedowania nad zaproponowanymi w projekcie rozwiązaniami, bardziej zasadne byłoby ustanowienie podstawy prawnej dla przeprowadzenia przez ministra właściwego ds. transportu pilotażu nowych rozwiązań teleinformatycznych. Dopiero po przeprowadzeniu takich działań, ich ewaluacji, można by było podjąć decyzje o zasadności, zakresie i sposobie wdrożenia odpowiednika cyfrowego dziennika szkolenia, jakim de facto ma być „cyfrowa karta kursanta”.\\t\\n\\t Art. 1 pkt 1 i pkt 3 projektu ustawy\\t Fundacja zapobiegania \\fWypadkom Drogowym\\t Poważne wątpliwości budzi projekt wprowadzenia cyfrowej karty kursanta, czyli w praktyce - elektronicznego nadzoru nad szkoleniem, a tym samym nad pracą instruktora. Rozumiejąc intencje autorów projektu, pozostajemy w przekonaniu, że nadzór i likwidacja \\fewentualnych, choć rzeczywiście występujących, nadużyć w zakresie realizacji zadań z zakresu szkolenia nie powinno odbywać się kosztem rzetelnej i uczciwie postępującej większości instruktorów. Także postulat przeprowadzenia w tym względzie pilotażu wydaje się ze wszech miar słuszny. Wiele argumentów przemawia za tym, że wypełnianie poszczególnych rubryk w aplikacji nie jest najtrafniejszą formą kontroli nad jakością szkolenia. Za to jest formą postępującej biurokratyzacji i formalizacji oraz braku zaufania do przedsiębiorcy i jego pracowników. Propozycja ta porównywana jest do dość powszechnie krytykowanego sposobu egzaminowania narzucającego wypełnianie ściśle określonego zestawu rubryk. Nasza opinia nie stoi w sprzeczności z pilną potrzebą wypracowania nowych form nadzoru i kontroli nad OSK. Obecny jest bowiem uważany za zbyt formalny i w niewielkim stopniu merytoryczny.  \\t\\n\\tArt. 1 pkt 1 projektu ustawy  \\tPolski Związek Szkoleniowy\\t1) W założeniu projektu ustawy przyjęto, że w cyfrowej karcie kursanta rejestrowany będzie wyłącznie przebieg części praktycznej szkolenia dla kandydata na kierowcę oraz część praktyczna egzaminu wewnętrznego. W całym procesie nie uwzględniono konieczności elektronicznej rejestracji części teoretycznej szkolenia, zajęć z pierwszej pomocy i części teoretycznej egzaminu wewnętrznego. Rejestracji tej części zajęć nie wolno pomijać. Nie można też założyć, że przeprowadzenie tych zajęć będzie potwierdzone jednorazowo za całe 30 godzin. Dotychczas zajęcia teoretyczne, tak jak zajęcia praktyczne były potwierdzane w karcie przeprowadzonych zajęć na takich samych zasadach jak zajęcia praktyczne czyli przez kursanta i wykładowcę czy instruktora po każdych zajęciach. W ocenie Polskiego Związku Szkoleniowego taka zasada powinna zostać zachowana. Proponujemy aby w cyfrowej karcie kursanta rejestrować na takich samych zasadach jak dotychczas także informacje o szkoleniu teoretycznym oraz o szkoleniu z pierwszej pomocy. Takie rozwiązanie ujednolici sposób prowadzenia dokumentacji i jednoznacznie ułatwi jej kontrolę.  Warto zauważyć, że czy tak czy inaczej przeprowadzenie zajęć teoretycznych musi być w jakiś sposób rejestrowane i potwierdzane. Jeżeli nie wprowadzimy tego rozwiązania do cyfrowej karty kursanta to potwierdzanie zajęć teoretycznych będzie się musiało odbywać tak jak dotychczas w oparciu o papierowe dokumenty. Zatem w tym wypadku wprowadzenie cyfrowej karty kursanta zamiast usprawnić prowadzenie dokumentacji związanej ze szkoleniem, stanie się dodatkowym elementem do papierowych dokumentów. Proponujemy przeredagowanie definicji zawartych w art. 1 pkt 1 w następujący sposób:   \\fa) zmianę definicji cyfrowej karty kursanta:   „5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym, instruktora, wykładowcę, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu szkolenia i egzaminu wewnętrznego, utworzony, udostępniany, aktualizowany i archiwizowany w systemie teleinformatycznym zapewnionym przez ministra właściwego do spraw informatyzacji, zintegrowanym z systemem, o którym mowa w art. 16a;”   b) zmianę definicji indywidualnego numeru kursanta:   „6) indywidualnym numerze kursanta – należy przez to rozumieć unikalny numer identyfikujący osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym, umożliwiający tej osobie potwierdzanie w cyfrowej karcie kursanta danych i informacji dotyczących przebiegu szkolenia oraz egzaminu wewnętrznego;”   c) zmianę definicji indywidualnego numeru  instruktora/wykładowcy:   7) indywidualnym numerze instruktora lub wykładowcy – należy przez to rozumieć unikalny numer identyfikujący instruktora lub wykładowcę, umożliwiający wprowadzenie i potwierdzenie w cyfrowej karcie kursanta danych i informacji dotyczących przebiegu szkolenia i egzaminu wewnętrznego, generowany w aplikacji mObywatel.”;   Wprowadzenie obowiązku rejestracji w cyfrowej karcie kursanta zajęć teoretycznych i szkolenia z pierwszej pomocy będzie wymagało przeredagowania pozostałych przepisów z tym związanych w pozostałej części projektu ustawy.\\t\\n\\tArt. 1  pkt 1 projektu ustawy\\tLiga Obrony Kraju\\t13. Z treści projektu ustawy nie wiadomo jak od strony technicznej będzie wdrożona cyfrowa karta kursanta. Przepisy dotyczące rejestracji egzaminów mają zostać napisane na postawie zmienianej ustawy (Art. 23h 3.). Dostosowanie się do nowych przepisów będzie dla ośrodków szkolenia oznaczało konieczność poniesienia dodatkowych koszów. Dzisiaj nie mamy danych do oszacowania jakich. Liga Obrony Kraju (LOK) \\fposiada wiele ośrodków i pojazdów szkoleniowych. Z tego powodu uważamy, że przyjęte rozwiązania powinny być oparte na powszechnie dostępnych urządzeniach (smartfony z odpowiednią aplikacją) co pozwoli uniknąć instalowania dedykowanych urządzeń lokalizacyjnych. Pozwoli wdrożyć proponowane zmiany bez dużych nakładów finansowych. Im wcześniej będziemy znać szczegóły tym łatwiej będzie nam zgromadzić odpowiednie środki. Będziemy też mieli więcej czasu na dostosowanie się pod względem organizacyjnym i technicznym. Przechowywanie w dużej ilości danych osobowych w sposób zgodny z RODO będzie również dużym wyzwaniem dla wszystkich ośrodków szkoleniowych. Reasumując wnioskujemy aby ww. regulacja była możliwie szybko opublikowana, a nie na kilka dni przed wejściem w życie przepisów nakazujących rejestrację egzaminu.\\t\\n\\tArt. 1 pkt 1 projektu ustawy\\tWielkopolskie Stowarzyszenie OSK i Instruktorów \\tKonsekwentnie należy wprowadzić rejestrację wszystkich zajęć podlegających rejestracji w jednym miejscu, w tym przypadku w odpowiednio przygotowanej cyfrowej karcie kursanta.  Proponowana zmiana: „5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym, instruktora, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu szkolenia w zakresie części teoretycznej, nauki udzielania pierwszej pomocy, nauki jazdy i części praktycznej egzaminu wewnętrznego, utworzony, udostępniany, aktualizowany i archiwizowany w systemie teleinformatycznym zapewnionym przez ministra właściwego do spraw informatyzacji, zintegrowanym z systemem, o którym mowa w art. 16a;  System cyfrowej karty kursanta należy oprzeć o funkcjonowanie odpowiedniej aplikacji, która będzie również przesyłała dane o geolokalizacji. Osoba używająca aplikacji (instruktor) będzie  mógł zadecydować o jej wyłączeniu, po zakończeniu pracy. Aplikacja co do lokalizacji i trasy powinna działać na podobnych zasadach jak np. aplikacja do obsługi systemu opłat drogowych e-toll.\\n Prowadzenie harmonogramu kursu nie jest potrzebne i stanowi tylko i wyłącznie niepotrzebny dokument, w oparciu o który kontrolujacy nic nie są w stanie zweryfikować. Zajęcia teoretyczne do tej pory odnotowywane są w Karcie Przeprowadzonych Zajęć lub \\fdokumentacji cyfrowej - w przypadku prowadzenia kursu w formule e-learning. W nowym wariancie, przy wprowadzeniu cyfrowej karty kursanta, transparentność zajęć będzie pełna i prowadzenie dodatkowej dokumentacji stanowi tylko i wyłącznie pusty wymów obciążający Kierownika OSK.\\n\\t\\n\\tArt. 1 pkt 1 i pkt 3 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 1)\\tUproszczenie obsługi cyfrowej karty kursanta\\ni jedno zbiorcze podsumowanie dla instruktora i kursanta 1. Treść uwagi Proponuje się przyjęcie prostego, spójnego i neutralnego technologicznie modelu obsługi cyfrowej karty kursanta. Po zakończeniu jazdy zarówno instruktor, jak i kursant powinni otrzymać jedno kompletne podsumowanie, odpowiednio do swoich ról. Instruktor uzupełnia i zatwierdza zbiorczo dane zajęć, natomiast kursant w tym samym procesie zapoznaje się z gotowym wpisem, może dodać komentarz, zgłosić niezgodność, potwierdzić dane albo zaakceptować korektę. Przed rozpoczęciem jazdy nie powinno być obowiązku podawania ani potwierdzania pełnego zestawu danych, takich jak ośrodek szkolenia kierowców, kursant, instruktor, pojazd czy planowany czas zajęć. Na tym etapie wystarczające powinno być techniczne uruchomienie rejestracji przez instruktora albo system teleinformatyczny. Jeżeli jazda została wcześniej zaplanowana w aplikacji, system może rozpocząć rejestrację automatycznie zgodnie z harmonogramem, jednak wcześniejsze posiadanie wszystkich danych nie powinno być warunkiem rozpoczęcia zapisu. System może najpierw rejestrować przebieg sesji, w szczególności czas i trasę, a dopiero po zakończeniu jazdy otrzymać i powiązać z nią pozostałe wymagane informacje. Instruktor powinien wtedy otrzymać jedno zbiorcze podsumowanie, w którym jednorazowo wskazuje lub weryfikuje ośrodek, kursanta, instruktora, pojazd, czas zajęć, kilometry, uwagi oraz inne wymagane dane. Takie rozwiązanie usuwa zbędne czynności wykonywane przed ruszeniem pojazdu, a jednocześnie pozwala zgromadzić po jeździe kompletną i uporządkowaną dokumentację. Aplikacja mObywatel ani aplikacja mobilna konkretnego ośrodka szkolenia kierowców nie powinny być obowiązkowym warunkiem udziału w szkoleniu lub wykonywania praw kursanta. Zgodnie z regulaminem aplikacji mObywatel korzystanie z niej jest dobrowolne, \\fdlatego projekt nie powinien przekształcać jej instalacji w faktyczny obowiązek. MObywatel może pozostać fakultatywnym sposobem uwierzytelnienia lub wygodnym przekierowaniem do cyfrowej karty kursanta. Podobnie aplikacja OSK może być oferowana jako udogodnienie, ale kursant powinien mieć równoważną możliwość zapoznania się z danymi, zgłoszenia uwag i potwierdzenia wpisu przez interfejs internetowy, urządzenie udostępnione przez ośrodek albo inny dostępny kanał. Przepisy powinny pozostawić kursantowi możliwość wyboru ośrodka i sposobu obsługi, bez narzucania instalowania określonego oprogramowania na prywatnym telefonie.  2. Wartość i korzyści proponowanego rozwiązania • Więcej czasu na szkolenie praktyczne. Ograniczenie czynności wykonywanych przed rozpoczęciem i po zakończeniu każdej jazdy pozwala instruktorowi skoncentrować się na przygotowaniu kursanta, omówieniu celów zajęć oraz przekazaniu wartościowej informacji zwrotnej. • Sprawniejsza organizacja kolejnych jazd. Krótsza obsługa administracyjna pomiędzy zajęciami ułatwia zachowanie punktualności, ogranicza opóźnienia i pozwala efektywniej wykorzystywać pojazdy oraz czas pracy instruktorów. • Jedno podsumowanie dla instruktora. Zamiast potwierdzać rozpoczęcie, wprowadzać część danych przed jazdą, potwierdzać zakończenie i wykonywać kolejne czynności osobno, instruktor otrzymuje po zajęciach jeden formularz obejmujący cały przebieg jazdy. • Zbiorcze wprowadzenie danych po jeździe. Ośrodek, kursant, instruktor, pojazd i pozostałe informacje mogą zostać wskazane lub zweryfikowane dopiero w końcowym podsumowaniu. Nie ma potrzeby uzależniania technicznego rozpoczęcia rejestracji od wcześniejszego posiadania przez system kompletnego zestawu danych. • Pełna i uporządkowana dokumentacja. System nadal może rejestrować czas rozpoczęcia i zakończenia, trasę i inne parametry automatyczne, a instruktor po jeździe uzupełnia dane opisowe. Uproszczenie dotyczy kolejności i sposobu obsługi, a nie zakresu informacji ani możliwości ich późniejszej analizy. • Wyższa jakość podsumowania po obu stronach. Instruktor zatwierdza kompletny zapis po zakończeniu pracy, gdy zna rzeczywisty przebieg zajęć, a kursant otrzymuje następnie jeden gotowy wpis, który może świadomie ocenić i skomentować. \\f• Mniej punktów awarii i przestojów. Rezygnacja z obowiązkowego skanowania kodów oraz wielokrotnego potwierdzania ogranicza ryzyko opóźnień spowodowanych problemem z telefonem, aplikacją, aparatem lub połączeniem internetowym. • Dostępność bez obowiązkowej aplikacji. Kursant może korzystać z aplikacji OSK albo mObywatela, jeżeli uzna je za wygodne, ale powinien mieć także równoważny sposób obsługi bez instalowania aplikacji na prywatnym telefonie. • Niższe koszty organizacyjne i integracyjne. Ograniczenie liczby obowiązkowych systemów oraz manualnych kroków upraszcza wdrożenie, utrzymanie i odpowiedzialność za prawidłowe działanie usługi. 3. Proponowany przebieg obsługi jazdy Etap\\tSposób realizacji Przed jazdą\\tInstruktor lub system uruchamia techniczną rejestrację sesji. Jeżeli istnieje wcześniej zaplanowany harmonogram, rejestracja może rozpocząć się automatycznie zgodnie z planem. Nie jest wymagane wcześniejsze wprowadzenie pełnych danych ośrodka, kursanta, instruktora i pojazdu, dodatkowe potwierdzenie kursanta ani skanowanie kodu QR. W trakcie jazdy\\tSystem automatycznie gromadzi dane możliwe do pozyskania w trakcie zajęć, w szczególności czas i przebieg trasy. Zapis jest utrzymywany jako sesja, do której po jeździe mogą zostać przypisane pozostałe wymagane informacje. \\fZbiorcze podsumowanie instruktora\\tPo zakończeniu jazdy instruktor otrzymuje jedno kompletne zestawienie. W jednym miejscu wskazuje lub weryfikuje ośrodek, kursanta, instruktora, pojazd, rzeczywisty czas zajęć, kilometry, uwagi i inne wymagane dane, a następnie zatwierdza cały wpis. Nie musi wykonywać odrębnych potwierdzeń na początku i na końcu jazdy. Podsumowanie dla kursanta\\tPo zatwierdzeniu przez instruktora kursant otrzymuje pełne zestawienie jazdy. Dostęp może być zapewniony w aplikacji, interfejsie internetowym, na urządzeniu udostępnionym przez OSK albo w innym równoważnym kanale, bez obowiązku instalowania aplikacji mObywatel lub aplikacji ośrodka. Jedna decyzja kursanta\\tPo zapoznaniu się z całym podsumowaniem kursant potwierdza wpis, zgłasza niezgodność, dodaje komentarz albo odmawia potwierdzenia. Wszystkie czynności powinny być dostępne w tym samym kanale, w którym przedstawiono podsumowanie. Ewentualna korekta\\tJeżeli potrzebna jest zmiana danych, instruktor przedstawia skorygowane podsumowanie, a kursant może zaakceptować korektę w tym samym interfejsie lub równoważnym kanale, bez przechodzenia do obowiązkowej dodatkowej aplikacji. 4. Uzasadnienie Celem cyfryzacji powinno być przede wszystkim uproszczenie procesu i ograniczenie czynności, które nie zwiększają wartości gromadzonych danych. Techniczne rozpoczęcie zapisu nie wymaga wcześniejszego przypisania całego zestawu informacji. System może najpierw zarejestrować czas i trasę sesji, a następnie po zakończeniu jazdy otrzymać od instruktora dane potrzebne do utworzenia kompletnego wpisu. Każda dodatkowa czynność może wydawać się jednostkowo krótka, jednak jest powtarzana przy każdej jeździe przez wszystkich instruktorów i kursantów. W skali działalności ośrodka \\ftworzy to znaczące obciążenie organizacyjne, wydłuża przerwy pomiędzy zajęciami i ogranicza czas, który można przeznaczyć na rzeczywiste szkolenie. Postulat wynika również z obserwacji instruktorów korzystających już z systemu, który wdraża rozwiązanie funkcjonalnie zbliżone do przewidzianego w projekcie, w tym potwierdzanie rozpoczęcia i zakończenia jazdy. Z ich praktycznych doświadczeń wynika, że odrębne czynności na początku i na końcu są postrzegane jako zbędne oraz nie wnoszą dodatkowej wartości do późniejszej analizy danych. Bardziej użyteczne jest jedno końcowe podsumowanie, w którym instruktor może od razu opisać rzeczywisty przebieg zajęć i zatwierdzić kompletny wpis. Zbiorcza obsługa po zakończeniu jazdy jest również bardziej miarodajna. Dopiero wtedy instruktor zna faktyczny czas, wykorzystany pojazd, przebieg trasy, liczbę kilometrów i ewentualne odstępstwa. Może więc wprowadzić wszystkie dane jednorazowo, zamiast potwierdzać na początku informacje, które w toku zajęć mogą się zmienić. Następnie kursant otrzymuje kompletny wpis i może ocenić go jako całość. Proponowane uproszczenie nie ogranicza uprawnień organów nadzoru. Dane nadal pozostają kompletne, możliwe do analizy i powiązane z konkretną jazdą. Zmienia się jedynie moment uzupełnienia danych opisowych i liczba manualnych kroków wymaganych od instruktora oraz kursanta. Równie istotna jest neutralność technologiczna. Korzystanie z aplikacji mObywatel jest dobrowolne, a posiadanie smartfona i instalowanie aplikacji konkretnego OSK nie powinno stawać się faktycznym warunkiem skorzystania ze szkolenia. Ośrodki mogą oferować własne aplikacje jako wygodne narzędzie i konkurować jakością obsługi, ale przepisy powinny wymagać zapewnienia również równoważnego kanału dla osób, które nie chcą lub nie mogą instalować aplikacji. Tak zaprojektowany proces łączy wysoką jakość dokumentacji z praktyczną użytecznością systemu i pozostawia użytkownikom realny wybór. Podstawa dotycząca dobrowolności: Regulamin korzystania z Aplikacji mObywatel 2.0 wskazuje, że posługiwanie się aplikacją przez użytkowników jest dobrowolne. 5. Postulat legislacyjny Projektowane przepisy powinny zostać ukształtowane w taki sposób, aby: • przed rozpoczęciem jazdy wymagane było wyłącznie techniczne uruchomienie rejestracji przez instruktora albo system, przy czym rejestracja mogła rozpoczynać się automatycznie zgodnie z wcześniej zaplanowanym harmonogramem; \\f• rozpoczęcie rejestracji nie było uzależnione od wcześniejszego wprowadzenia pełnych danych ośrodka, kursanta, instruktora, pojazdu i zajęć ani od potwierdzenia kursanta lub zeskanowania kodu QR; • system mógł najpierw zarejestrować sesję, w szczególności jej czas i trasę, a pozostałe wymagane dane mogły zostać wprowadzone i przypisane po zakończeniu jazdy; • instruktor po zakończeniu jazdy otrzymywał jedno zbiorcze podsumowanie i w jednym miejscu wskazywał, uzupełniał, weryfikował oraz zatwierdzał wszystkie wymagane dane, bez odrębnego potwierdzania rozpoczęcia i zakończenia; • kursant po zatwierdzeniu wpisu przez instruktora otrzymywał jedno kompletne podsumowanie i mógł je potwierdzić, zakwestionować, skomentować albo zaakceptować korektę; • wszystkie czynności kursanta były możliwe zarówno w aplikacji mobilnej, jak i przez równoważny kanał niewymagający instalowania aplikacji na prywatnym telefonie; • aplikacja mObywatel oraz aplikacja OSK pozostawały rozwiązaniami fakultatywnymi i pomocniczymi, a ich posiadanie nie stanowiło warunku rozpoczęcia lub ukończenia szkolenia; • indywidualny numer kursanta pełnił wyłącznie funkcję identyfikatora technicznego, a kod QR nie był obowiązkowym etapem obsługi każdej jazdy; • uproszczenie procedury nie wpływało na zakres gromadzonych danych, ich kompletność ani możliwość późniejszej analizy przez uprawnione podmioty. \\t\\n\\tArt. 1 pkt 2 projektu ustawy\\tLiga Obrony Kraju\\t1. W Art. 1 zmiana 2) w art. 23 Proponujemy wykreślić tą zmianę w całości. Obecne przepisy nie zabraniają instruktorowi prowadzić szkolenie na drogach innych jak publiczne. Skoro aktualne przepisy nie zabraniają to dodanie ust. 2a jest zbędne. Ewentualnie ustęp powinien zawierać tylko regulację zobowiązującą instruktora do stosowania zasad i przepisów ruchu drogowego obowiązujących na drogach publicznych jeśli prowadzi szkolenie na pozostałych rodzajach dróg. Uważamy, że część szkolenia praktycznego nadal powinna odbywać się na placu manewrowym. W proponowanej treści ust. 2a jest zapis, że „instruktor może, na podstawie \\foceny umiejętności osoby szkolonej”. Jak instruktor może ocenić umiejętności osoby szkolonej, nie mając do dyspozycji bezpiecznego placu manewrowego ? „Głębokie spojrzenie w oczy” nie wystarczy, potrzebny jest plac manewrowy. Bezpieczny plac manewrowy jest potrzebny instruktorom i wielu kursantom. Instruktorom bo mogą skupić się tylko na kursancie i nie muszą przejmować się innymi uczestnikami ruchu drogowego. Niektórzy kursanci mimo zapisania się na kurs po prostu boją się prowadzić pojazd. Swój strach pokonują pod okiem instruktora tylko dlatego, że szkolenie odbywa się na bezpiecznym placu manewrowym. Gdzie nie obawiają się, że spowodują jakieś „nieszczęście”. Plac manewrowy na dalszym etapie szkolenia też jest potrzebny. Zawsze będzie lepiej dla wszystkich uczestników ruchu drogowego, jak kursant po raz pierwszy będzie trenować manewry (parkowania, ruszania pod górę) na placu manewrowym a dopiero później na publicznej drodze. Istnieje również zagrożenie, że nie wszyscy instruktorzy będą odpowiedzialni i znajdą naprawdę bezpieczne miejsce do prowadzenia szkolenia wstępnego. Wprowadzanie obowiązku rejestracji egzaminu wewnętrznego świadczy, że nawet ustawodawca nie do końca wierzy w rzetelność wszystkich instruktorów.\\t\\n\\tArt. 1 pkt 2 projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t2) w art. 23: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\ta) w ust. 2 pkt 2 lit. a otrzymuje brzmienie: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„a) na placu manewrowym – nie dotyczy uprawnień do kierowania pojazdami silnikowymi kategorii B lub B1,”; \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tJesteśmy za utrzymaniem placu manewrowego w szkoleniu i egzaminowaniu w obecnej formie.  \\t\\n\\tArt. 1 pkt 2 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków \\fRuchu Drogowego\\t\\fW art. 1 pkt 2 – należy powrócić do obowiązku posiadania przez OSK placów manewrowych. I nie chodzi tu o obecne rozumienie placu z wyznaczonymi stanowiskami, pachołkami i tyczami. Chodzi o przestrzeń, w której z zachowaniem spokoju i bezpieczeństwa będą realizowane pierwsze godziny szkoleń.  \\t\\n\\tArt. 1 pkt 2 projektu ustawy\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\tAd. art. 1 pkt 2 projektu  Zaproponowane zmiany art. 23 UoKP w zakresie ust. 2 pkt 2 lit. a, likwidującej zajęcia praktyczne podczas szkolenia praktycznego w zakresie kategorii B1 i B, przeprowadzane na placu manewrowym, mogą budzić - w ocenie TLP - uzasadnione wątpliwości, związane z koniecznością zapewniania bezpieczeństwa osobie szkolonej, instruktorowi, jak i osobom postronnym. Szczególnie na początku szkolenia, gdzie osoba szkolona powinna nabyć podstawowe umiejętności w zakresie panowania nad pojazdem. Nie rozwiązuje tego problemu zaproponowany nowy przepis art. 23 ust. 2a UoKP, gdyż możliwość szkolenia poza drogą publiczną ma charakter fakultatywny. Ponadto, brzmienie powołanego nowego przepisu art. 23 ust. 2a może budzić poważne wątpliwości, gdyż  sugeruje możliwość prowadzenia nawet 90% zająć poza drogą publiczną.  Zgadzamy się, co do zasady, z oceną resortu infrastruktury, że plac manewrowy w dotychczasowej formie (sztywno określone i wyznaczone za pomocą „patyków” stanowiska do manewrów) jest szkodliwym i zbędnym anachronizmem, który nie pozwala na wykształcenie prawidłowych nawyków, niezbędnych do wykonywania manewrów w realnych sytuacjach, związanych z manewrowaniem na drodze publicznej lub w innych miejscach, gdzie na co dzień wykonywane są takie manewry. Ta krytyczna ocena placu manewrowego w dotychczasowej formie dotyczy także innych kategorii prawa jazdy takich, jak np. prawo jazdy kategorii C, C+E, D, i D+E.  Niemniej uważamy, że szkolenie praktyczne powinno zawierać obligatoryjne zajęcia wstępne, przeprowadzane na dowolnym placu, który jest zabezpieczony przed dostępem osób trzecich w trakcie przeprowadzanych zajęć . Może to być dowolne miejsce, udostępnione przez uprawnionego zarządcę tego obiektu, takie jak np.: wydzielona część parkingu przy dowolnym obiekcie biurowym, przemysłowym, sportowym, handlowym lub logistycznym, w dniach gdy obiekt ten nie jest użytkowany. O czasie trwania tych zajęć wstępnych, powinien decydować wyłącznie instruktor ,uwzględniając stopień panowania nad pojazdem.  Odnosząc się do miejsca i sposobu przeprowadzania zajęć praktycznych, regulowanych w art. 23 UoKP, należałoby zapewnić możliwość używania symulatorów podczas zajęć z percepcji ryzyka. Nawet prosty symulator (bez jakichkolwiek stopni swobody) pozwala na \\fpokazanie większości sytuacji potencjalnie wymagających zmiany w zachowaniu kierowcy i wykształcenie odpowiednich nawyków w tym obszarze.  Mając na uwadze wskazane wyżej zastrzeżenia i postulaty, proponujemy w art. 23 UoKP:  nadanie ust. 2 pkt 2 brzmienia:   „2) część praktyczną w zakresie kierowania pojazdem, zwaną dalej „nauką jazdy”, przeprowadzaną:  w miejscu (placu) zabezpieczonym w trakcie przeprowadzania zajęć przed dostępem osób postronnych,  w ruchu miejskim,  w ruchu poza obszarem zabudowanym;”  zmianę proponowanego w projekcie brzmienia ust. 2a na następujące:   2a. Zajęcia z zakresu rozpoznawania zagrożeń, prowadzone podczas części praktycznej szkolenia, o której mowa w ust. 2 pkt 2, mogą być prowadzone w ośrodku szkolenia z wykorzystaniem symulatora jazdy. \\t\\n\\t Art. 1 pkt 2 lit. a projektu ustawy  \\t Polski Związek Szkoleniowy\\tW art. 1 w pkt 2 w lit. a proponujemy zmianę nowego brzmienia przepisu art. 23 ust. 2 pkt 2 lit. a poprzez zamianę słów „silnikowymi kategorii B lub B1,” na słowa „kategorii B lub B1 oraz kategorii AM - w przypadku przeprowadzania szkolenia zakresie prawa jazdy kategorii AM przy użyciu czterokołowca lekkiego lub motoroweru trójkołowego;”  Zarówno szkolenie jak i egzaminowanie w zakresie prawa jazdy kategorii AM może odbywać się na czterokołowcu lekkim albo motorowerze trójkołowym. Szkolenie takie jak i egzamin odbywa się na zasadach określonych dla prawa jazdy kategorii B1. Dlatego też, jeżeli OSK prowadzi szkolenia na prawo jazdy kategorii AM czterokołowca lekkiego lub motoroweru trójkołowego to to szkolenie także powinno być formalnie wyłączone spod wymagania przeprowadzania go na placu manewrowym. Usunięcie z definicji słowa „silnikowym” wiąże się z definicją motoroweru który nie jest pojazdem silnikowym.   \\t\\n\\tArt. 1 pkt 2 lit. b projektu ustawy  \\tPolski Związek Szkoleniowy\\t3) W art. 1 w pkt 2: w lit. b proponujemy zmianę polegającą na zmianie brzmienia nowego ust. 2a poprzez zamianę słów „pojazdem silnikowym kategorii B lub B1” na słowa „kategorii B lub B1 oraz kategorii AM - w przypadku przeprowadzania szkolenia zakresie prawa jazdy kategorii AM przy użyciu czterokołowca lekkiego lub motoroweru trójkołowego;”  Uzasadnienie jak powyżej.   Po lit b dodaje się lit c w brzmieniu:   W art. 23 po ust. 3 dodaje się ust. 3a i 7a w brzmieniu:  „3a. Część praktyczna szkolenia, o której mowa w ust. 2 pkt 2, w wymiarze 10% zajęć, może być prowadzona przy użyciu urządzenia technicznego do symulowania jazdy samochodem osobowym, spełniającego wymagania określone w przepisach wydanych na podstawie ust. 7a, posiadającego ważny certyfikat wydany przez jednostkę akredytowaną w polskim systemie akredytacji, który potwierdza spełnienie tych wymagań przez to urządzenie.  7a. Minister właściwy do spraw transportu określi, w drodze rozporządzenia, wymagania techniczno-organizacyjne oraz zakres funkcjonalności realizowanej przez urządzenie, o którym mowa w ust. 3a, uwzględniając potrzebę zapewnienia wykorzystania podczas szkolenia urządzeń spełniających jednolite wymagania.”;”   Uzasadnienie  Uwzględniając rozwój technologii szkoleniowych i zapotrzebowanie rynku, podobnie jak w przypadku szkoleń dla kierowców zawodowych, proponujemy umożliwienie ośrodkom szkolenia kierowców prowadzenie części szkolenia praktycznego przy użyciu odpowiednich symulatorów jazdy. Urządzenia te mogłyby być z powodzeniem stosowane w pierwszej fazie szkolenia na placu manewrowym, w szczególności w zakresie obsługi urządzeń pojazdu, zmiany biegów, trzymania się w pasie ruchu, umiejętności ruszania i bezpiecznego zatrzymania. W drugiej fazie szkolenia symulatory mogłyby być wykorzystane do nauki jazdy po autostradzie. W szczególności dotyczy to miejscowości, w których wyjazd na autostradę czy drogę szybkiego ruchu jest utrudniony. Zanim osoba szkolona fizycznie wyjechałaby na autostradę w bezpieczny sposób mogłaby się oswoić z zasadami wjazdu na autostradę, włączania się do ruchu, zmiany pasa ruchu, a także opuszczenia autostrady. Takie zajęcia na pewno przygotowałyby kursantów do lekcji w realnym ruchu dając instruktorom poczucie bezpieczeństwa przy pierwszych lekcjach w fizycznym ruchu drogowym.  \\fNależy pamiętać, że symulatory dają możliwość oprócz zwykłych sytuacji drogowych symulowania sytuacji nietypowych z którymi osoba szkolona może nigdy nie spotkać się podczas szkolenia. Możliwość prowadzenia takiego szkolenia w znacznym stopniu przyczyni się do poprawy umiejętności przyszłych kierowców, a więc także do poprawy bezpieczeństwa.  Należy pamiętać, że konieczność umożliwienia wszystkim osobom szkolonym bezpiecznego zapoznania się z zasadami ruchu po autostradach jest jednoznacznie uzasadniona ostatnimi wypadkami śmiertelnymi na tych drogach. Warto umożliwić wszystkim, nawet tym którzy do autostrady nie mają jeszcze dostępu, bezpieczną naukę poruszania się tymi drogami z uwzględnieniem wjazdów i zjazdów z nich.\\t\\n\\tArt. 1 pkt 2 projektu ustawy w zakresie art. 23 ust. 2 pkt 2 lit. a ustawy o kierujących pojazdami\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPropozycja zmiany: a) na placu manewrowym – nie dotyczy uprawnień do kierowania pojazdami silnikowymi kategorii B, B1 i AM (trójkołowca) Uzasadnienie: Proponowana zmiana jest konsekwencją wprowadzenia głównej zmiany w procesie szkolenia i egzaminowania – likwidacja placu manewrowego. Skoro znosimy dla kat. B1 i B plac manewrowy to dla kategorii AM, który odbywa się trójkołowcem taka zmiana wydaje się być zasadna.\\t\\n\\tArt. 1 pkt 2 projektu ustawy w zakresie art. 23 ust. 2a ustawy o kierujących pojazdami\\tZwiązek Województw Rzeczypospolitej Polskiej\\tW przypadku szkolenia osoby ubiegającej się o uprawnienia do kierowania pojazdem silnikowym kategorii B, B1 i AM (trójkołowiec), instruktor może, na podstawie oceny umiejętności osoby szkolonej, podjąć decyzję o przeprowadzeniu części zajęć z nauki jazdy poza drogą publiczną, strefą zamieszkania i strefą ruchu, pod warunkiem zapewnienia przez instruktora stosowania zasad i przepisów ruchu drogowego obowiązujących na drodze publicznej.  Proponowana zmiana jest konsekwencją wprowadzonej zmiany w punkcie powyżej.\\t\\n\\t Art. 1 pkt 2 projektu ustawy\\t Małopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców \\tUwaga 7. Uregulowanie formy prowadzenia zajęć teoretycznych poprzez dopuszczenie nauczania na odległość wyłącznie w czasie rzeczywistym i udostępnienie tej formy wszystkim ośrodkom szkolenia kierowców (art. 1 pkt 2 projektu; art. 23 ust. 3 i art. 26 ust. 2 ustawy) Treść uwagi: Przedmiotem nowelizacji jest ustawa o kierujących pojazdami, w związku z tym postulujemy objęcie nią również art. 23 ust. 3 ustawy poprzez doprecyzowanie, że nauczanie \\fna odległość w części teoretycznej szkolenia jest dopuszczalne wyłącznie w formie zajęć prowadzonych w czasie rzeczywistym przez wykładowcę lub instruktora, z możliwością bieżącego zadawania pytań, co oznacza rezygnację z e-learningu opartego na odtwarzaniu gotowych materiałów, oraz udostępnienie tak rozumianego nauczania na odległość wszystkim ośrodkom szkolenia kierowców poprzez uchylenie art. 26 ust. 2 ustawy. Problem: Obowiązujący art. 23 ust. 3 ustawy dopuszcza przeprowadzenie wykładów w formie nauczania na odległość z wykorzystaniem technik komputerowych i Internetu pod nadzorem ośrodka szkolenia kierowców, przy czym zgodnie z art. 26 ust. 2 ustawy szkolenie w tej formie może prowadzić wyłącznie ośrodek posiadający poświadczenie potwierdzające spełnianie dodatkowych wymagań, a przepisy nie rozróżniają zajęć prowadzonych na żywo przez wykładowcę od e-learningu polegającego na samodzielnym odtwarzaniu gotowych prezentacji, który nie daje gwarancji rzetelnego przeprowadzenia części teoretycznej i w praktyce sprowadza się często do jak najszybszego przechodzenia przez kolejne slajdy. Podzielamy pogląd części organizacji branżowych o potrzebie rezygnacji z tak rozumianego e-learningu, sprzeciwiamy się natomiast postulatom całkowitego zakazu wszelkich form szkolenia na odległość, ponieważ zajęcia prowadzone w czasie rzeczywistym z wykorzystaniem platform webinarowych, powszechnie stosowane przez uczelnie wyższe w modelu kształcenia mieszanego, pozwalają utworzyć wirtualną salę wykładową z zachowaniem norm metodycznych, z bezpośrednim kontaktem z prowadzącym, prezentacjami, filmami edukacyjnymi i bieżącą weryfikacją wiedzy, a zarazem eliminują barierę dojazdu, szczególnie istotną dla kursantów z mniejszych miejscowości. Przy zajęciach prowadzonych w czasie rzeczywistym, rejestrowanych w cyfrowej karcie kursanta, utrzymywanie bariery w postaci poświadczenia potwierdzającego spełnianie dodatkowych wymagań traci uzasadnienie, dlatego wzorem rozwiązania obowiązującego w okresie pandemii możliwość prowadzenia zajęć na odległość powinna przysługiwać wszystkim ośrodkom szkolenia kierowców. Postulat ten pozostaje w pełnej synergii z projektowaną cyfrową kartą kursanta oraz z uwagą 2 niniejszego stanowiska, ponieważ rejestracja w karcie daty, godzin i formy realizacji zajęć teoretycznych, wraz z funkcjami platform webinarowych dokumentującymi czas logowania i obecność uczestników, czyni nadzór nad zajęciami prowadzonymi na odległość w pełni realnym i weryfikowalnym. Propozycja zmiany zapisu: Proponujemy, aby w art. 1 pkt 2 projektu dodać lit. c w brzmieniu: „c) ust. 3 otrzymuje brzmienie: \\f«3. Wykłady, o których mowa w ust. 2 pkt 1, mogą być przeprowadzone w formie nauczania na odległość z wykorzystaniem technik komputerowych i Internetu, pod nadzorem ośrodka szkolenia kierowców, jeżeli: 1) zajęcia są prowadzone w czasie rzeczywistym przez wykładowcę lub instruktora z wykorzystaniem platformy umożliwiającej transmisję obrazu i dźwięku; 2) osoby szkolone mają możliwość zadawania pytań oraz komunikowania się z prowadzącym zajęcia w czasie rzeczywistym; 3) nie obejmują one zajęć z zakresu udzielania pierwszej pomocy ofiarom wypadków drogowych.»” oraz aby w art. 1 projektu dodać punkt uchylający art. 26 ust. 2 ustawy, tak aby prowadzenie zajęć teoretycznych w formie nauczania na odległość w czasie rzeczywistym było dostępne dla wszystkich ośrodków szkolenia kierowców, bez konieczności posiadania poświadczenia potwierdzającego spełnianie dodatkowych wymagań. \\t\\n\\tArt. 1 pkt 3 projektu ustawy \\tPolska Wytwórnia Papierów Wartościowych S.A.\\tw maju br. został przez PWPW S.A. udostępniony Portal e-usług (portal dostępny pod adresem: https://info-kierowca.pl/). Portal ten przewiduje możliwość złożenia wniosku o wydanie prawa jazdy oraz wniosku o wydanie karty kwalifikacji kierowcy przy użyciu formularza utrwalonego w postaci elektronicznej. Jest to portal skierowany do osób ubiegających się o uzyskanie uprawnień do kierowania pojazdami, zatem do tej samej grupy odbiorców, co kursanci.  Jak wskazano powyżej portal ten został zbudowany \\nz wykorzystaniem środków z Krajowego Planu Odbudowy \\ni Zwiększania Odporności, a PWPW S.A. została zobowiązana do utrzymania trwałości tego projektu przez okres 5 lat od dnia jego uruchomienia.  Z uwagi na powyższe projektowane rozwiązania powinny zostać powiązane z ww. portalem, co zapewni spójną \\ni jednolitą obsługę osób ubiegających się o uprawnienia do kierowania pojazdami od etapu szkolenia do etapu wydania dokumentu potwierdzającego te uprawnienia.  \\fDodatkowo proponuje się, aby w „cyfrowej karcie kursanta” ewidencjonowane były dane dotyczące szkolenia teoretycznego na zasadach analogicznych jak przewidziano dla ewidencjonowania przebiegu zajęć praktycznych \\nw zakresie nauki jazdy. projektowany art. 23b ust. 3 ustawy powinien otrzymać brzmienie: „3. Indywidualny numer kursanta może być odwzorowany za pomocą kodu QR w usłudze elektronicznej udostępnionej przez wytwórcę praw jazdy, kart kwalifikacji kierowcy i pozwoleń na kierowanie tramwajem umożliwiającej złożenie wniosku o wydanie tych dokumentów za pomocą środków komunikacji elektronicznej, na podstawie danych podanych przez wnioskodawcę po uwierzytelnieniu.”;  projektowany art. 23c ust. 2 ustawy powinien otrzymać brzmienie: „2. Instruktor przeprowadzający zajęcia w zakresie nauki jazdy lub część praktyczną egzaminu wewnętrznego ma dostęp do danych i informacji zawartych w cyfrowej karcie kursanta w zakresie zajęć lub części praktycznej egzaminu wewnętrznego, po uwierzytelnieniu.”;  projekt powinien zostać uzupełniony o przepis przyznający dostęp do danych zawartych \\nw cyfrowej karcie kursanta także wykładowcy.\\t\\n\\tArt. 1 pkt 3 projektu ustawy \\tZwiązek Pracodawców „Transport i Logistyka Polska”\\tAd. art. 1 pkt 3  Proponowane w pkt 3 projektu zmiany UoKP polegają na wprowadzeniu do procesu szkolenia „cyfrowej karty kursanta”. Ogólne krytyczne uwagi co do zasadności i sposobu wdrożenia tego rozwiązania wskazane zostały w uwagach TLP do art. 1 pkt 1 projektu. I podtrzymujemy wskazane tamże wnioski, których przyjęcie oznaczałoby odrzucenie proponowanych w pkt 3 przepisów w lub ich bardzo poważną modyfikację.  Odnosząc się natomiast do szczegółowym propozycji zawartych w art. 1 pkt 3 przekazujemy następujące uwagi:  \\fW art. 23c ust. 1 UoKP w zdaniu wprowadzającym do wyliczenia, użyto wyrazu „rejestruje”. Bardziej właściwym byłoby użycie wyrazu „wprowadza”. Zwracamy uwagę, iż rejestrowanie powinno następować do określonego systemu, podczas gdy cyfrowa karta kursanta, zgodnie z definicją zaproponowaną w nowym art. 2 pkt 5 UoKP, stanowi zestaw danych, czyli zawartość lub zbiór informacji, które już są w systemie przetwarzane, a nie stanowią system, jako odrębny byt.  W odniesieniu do art. 23c ust. 1 pkt 1 i 2 UoKP, TLP podtrzymuje wyżej wyrażone w uwagach do pkt 1, wątpliwości, czy tak szczegółowe dane i informacje, powinny stanowić materię rangi ustawowej, czy też nie powinny zostać przeniesione do rozporządzenia, jako aktu wykonawczego względem UoKP. Wątpliwości te są tym bardziej uzasadnione, iż biorąc pod uwagę różnorodny zakres i charakter omawianych danych, każdorazowa ich późniejsza zmiana będzie wymagała kolejnej nowelizacji UoKP, podczas gdy ewentualna zmiana rozporządzenia będzie proceduralnie krótsza a osiągnięty cel i skutek będzie taki sam.  W art. 23c ust. 1 pkt 1 i 2 UoKP występuje niezgodność z art. 2 pkt 5 UoKP. W “cyfrowej karcie kursanta” wprowadza się trzy, odrębne zestawy danych: identyfikujących osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem, dotyczących przebiegu szkolenia w zakresie nauki jazdy oraz dotyczących przebiegu części praktycznej egzaminu wewnętrznego, podczas gdy rejestracja do cyfrowej karty obejmuje tylko dane dotyczące przebiegu szkolenia i egzaminu wewnętrznego, dublując dane identyfikujące osobę szkoloną.  W art. 23c ust. 1 pkt 1 lit. e-f UoKP, należy doprecyzować , czy data i godzina rozpoczęcia / zakończenia zajęć ma dotyczyć pierwszych i ostatnich zajęć całego szkolenia, czy ma dotyczyć każdorazowo rozpoczynania i zakańczania konkretnych zajęć w ramach, np. jednego dnia szkolenia.  W art. 23c ust. 3 i 4 UoKP, następuje nieuzasadnione rozszerzenie obowiązków instruktorów nauki jazdy o wprowadzanie i potwierdzanie danych oraz informacji w cyfrowej karcie kursanta. W ocenie TLP, pomijając fakt, iż informacje wpisuje się, a nie potwierdza, celem instruktora jest przygotowanie kursanta do bezpiecznego prowadzenia pojazdu oraz zdania egzaminu państwowego, a nie czasochłonna biurokracja i weryfikacja elektronicznie zgromadzonych danych i informacji.  \\fW art. 23c ust. 5 UoKP, okres lenie „aplikacja mobilna zintegrowana z cyfrową kartą kursanta” jest ogólne i nie wskazuje podstawowych elementów, tj. jakie mają być parametry/wymagania takiej aplikacji, w jaki sposób ma być integrowana z zestawem danych i informacji, który nie stanowi systemu oraz kto będzie odpowiedzialny za taką integrację.  W art. 23c ust. 6 UoKP, TLP sprzeciwia się rozwiązaniu, zgodnie z którym dane lokalizacyjne dotyczące godziny i daty zakończenia zajęć oraz trasy jazdy nie będą mogły być zmieniane ani usuwane. Po pierwsze, nie wskazano, zakończenie których zajęć ma być rejestrowane (całości szkolenia czy pojedynczych w ramach każdego dnia szkolenia, czy innych?), a po drugie, proponowane rozwiązanie jest nieadekwatne do stanów faktycznych mogących mieć miejsce podczas nauki, np. błędna lokalizacja generowana przez system teleinformatyczny, zakłócenia systemu przekazywania danych geolokalizacyjnych, oczywiste omyłki pisarskie. W ocenie TLP, w projektowanym przepisie kropkę należałoby zastąpić przecinkiem i dodać wyrazy „chyba, że zaistnieją szczególne okoliczności, na które osoba szkolona lub instruktor nie mieli wpływu”.  W art. 23d UoKP, przepisy dotyczące szczegółowej procedury wprowadzania przez kursanta uwag, potwierdzania lub odmowy potwierdzania przebiegu szkolenia i egzaminu wewnętrznego, a także wprowadzania, potwierdzania i zatwierdzania zestawów danych na cyfrowej karcie kursanta przez instruktora, stanowią materię rozporządzenia, jako aktu wykonawczego do ustawy, a nie projektowanej UoKP. W art. 23j ust. 2 UoKP, po pierwsze, zwracamy uwagę, iż „prawomocne zakończenie postępowania” jest okres leniem ogólnym, potocznym, a tym samym niezdefiniowanym w przepisach prawnych, które odnosi się do sytuacji w której w danej sprawie zapadło już orzeczenie, niepodlegające zaskarżeniu za pomocą zwyczajnych środków odwoławczych. Prawomocność należy odnosić raczej do form rozstrzygnięć sądowych – wyroków /postanowień, podczas gdy decyzje administracyjne, nie są prawomocne tylko ostateczne. Po drugie, w projektowanym przepisie nie wskazano, do jakiego rodzaju postępowań należy odnosić „prawomocność ”, tj. administracyjnego, karnego, czy cywilnego.  W art. 23j ust. 5 UoKP, użyte określenia „w celach komercyjnych, promocyjnych i reklamowych” nie są zdefiniowane, a dotyczą jednego z elementów zakazu przetwarzania danych osobowych przez ośrodek szkolenia kierowców. W ocenie TLP, wszelkie przepisy \\fprojektujące sankcje, w tym znamiona czynów niedozwolonych, powinny być konkretne, tj. dokładne i jednoznaczne.  W odniesieniu do art. 1 pkt 3 projektu, w zakresie art. 23i-j UoKP, art. 1 pkt 4 projektu, w zakresie art. 24pkt 1 lit. e UoKP oraz art. 1 pkt 5 lit. a-d projektu, w zakresie art. 27ust. 1 pkt 7 oraz art. 27 ust. 2 pkt 6, art. 27 ust. 4b, art. 27 ust. 6-7 UoKP, zwracamy uwagę, iż projektowane rozwiązania wprowadzają bardzo szczegółowe, biurokratyczne i czasochłonne w realizacji, dodatkowe obowiązki ośrodków szkoleń kierowców, o charakterze formalno-administracyjnym, kto re z prawdopodobieństwem graniczącym z pewnością będą stanowić nie ułatwienie a kolejną barierę administracyjną w działalności tych ośrodków. W ocenie TLP, zdecydowana większość tych przepisów może stanowić regulację rangi rozporządzenia, bądź zostać usunięta, ze względu na obowiązujące już, szczegółowe przepisy polskie i unijne oraz wynikające z nich procedury, dotyczące przetwarzania danych osobowych.  \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\n\\tArt. 1 pkt 3 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 3  - w części dotyczącej proponowanego art. 23e – nie wydaje się potrzebnym zapewnienie dostępu WORD do danych i informacji zarejestrowanych w cyfrowej karcie kursanta. Natomiast popieramy propozycję regulacji wnoszącej obowiązkową rejestrację przebiegu części praktycznej egzaminu wewnętrznego. Szczegółowe określenie jej warunków, zasad i procedur związanych z przechowywaniem powinno nastąpić w rozporządzeniu. \\t\\n\\tArt. 1 pkt 3 projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tArt. 23j ust. 1 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„Zapis przebiegu części praktycznej egzaminu wewnętrznego przechowuje się przez okres 90 dni od dnia przeprowadzenia tego egzaminu, z uwzględnieniem ust. 2.” \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProponujemy wydłużenie okresu przechowywania zapisu przebiegu części praktycznej egzaminu wewnętrznego. W ocenie Krajowego Stowarzyszenia Egzaminatorów zapis ten powinien być przechowywany do czasu uzyskania przez osobę szkoloną pozytywnego \\fwyniku części praktycznej egzaminu państwowego, nie dłużej jednak, niż przez okres 12 miesięcy od dnia uzyskania pozytywnego wyniku egzaminu wewnętrznego. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProponowany w projekcie okres 90 dni może okazać się niewystarczający. Należy mieć na uwadze, że od momentu zakończenia szkolenia i uzyskania pozytywnego wyniku egzaminu wewnętrznego do uzyskania pozytywnego wyniku egzaminu państwowego może upłynąć okres przekraczający trzy miesiące. Wpływ na to mają zarówno czas oczekiwania na wyznaczenie terminu egzaminu państwowego, jak również możliwość uzyskania przez kandydata negatywnych wyników kolejnych egzaminów i związana z tym konieczność ponownego oczekiwania na następne terminy. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tJednocześnie znaczna część kandydatów uzyskuje pozytywny wynik egzaminu państwowego już przy pierwszym podejściu. W takich przypadkach nie istnieje potrzeba dalszego przechowywania zapisu egzaminu wewnętrznego po uzyskaniu pozytywnego wyniku części praktycznej egzaminu państwowego. Powiązanie okresu przechowywania nagrania z momentem uzyskania pozytywnego wyniku egzaminu państwowego pozwoliłoby zatem uniknąć nieuzasadnionego gromadzenia znacznej liczby nagrań dotyczących osób, których proces uzyskiwania uprawnień został już zakończony. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tIstotnym argumentem przemawiającym za proponowanym rozwiązaniem jest również możliwość wykorzystania zapisu egzaminu wewnętrznego do oceny prawidłowości procesu szkolenia. Szczególne znaczenie może mieć to w przypadkach, w których osoba szkolona, pomimo uzyskania pozytywnego wyniku egzaminu wewnętrznego, wielokrotnie uzyskuje negatywny wynik części praktycznej egzaminu państwowego. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tMożliwość weryfikacji zapisu egzaminu wewnętrznego pozwoliłaby w takich sytuacjach na ocenę, czy osoba szkolona w chwili jego przeprowadzania rzeczywiście prezentowała poziom umiejętności pozwalający na samodzielne i bezpieczne uczestnictwo w ruchu drogowym oraz czy pozytywny wynik egzaminu wewnętrznego znajdował uzasadnienie w faktycznie zaprezentowanych umiejętnościach. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tRozwiązanie takie stanowiłoby również mechanizm zwiększający odpowiedzialność osób przeprowadzających egzaminy wewnętrzne. Świadomość, że zapis egzaminu może podlegać późniejszej weryfikacji, w szczególności w przypadku powtarzających się negatywnych \\fwyników egzaminów państwowych, powinna ograniczać przypadki przedwczesnego zaliczania egzaminu wewnętrznego osobom, które nie osiągnęły jeszcze poziomu umiejętności niezbędnego do samodzielnego i bezpiecznego kierowania pojazdem. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW konsekwencji kandydat, który nie osiągnął wymaganego poziomu umiejętności, powinien kontynuować szkolenie w zakresie niezbędnym do uzupełnienia stwierdzonych braków, zamiast uzyskiwać pozytywny wynik egzaminu wewnętrznego i podejmować kolejne, nieskuteczne próby zdania egzaminu państwowego. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW ocenie Krajowego Stowarzyszenia Egzaminatorów proponowane rozwiązanie może zatem przyczynić się zarówno do podniesienia jakości szkolenia kandydatów na kierowców, jak i zwiększenia rzetelności egzaminów wewnętrznych oraz odpowiedzialności podmiotów prowadzących szkolenie za poziom przygotowania osób kierowanych na egzamin państwowy. Jednocześnie ustanowienie maksymalnego, 12-miesięcznego okresu przechowywania zapisu zapobiegałoby konieczności jego bezterminowego przechowywania w przypadku osób, które po ukończeniu szkolenia nie przystąpią do egzaminu państwowego albo przez dłuższy czas nie uzyskają wyniku pozytywnego. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProponowane brzmienie przepisu: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„1. Zapis przebiegu części praktycznej egzaminu wewnętrznego przechowuje się do dnia uzyskania przez osobę szkoloną pozytywnego wyniku części praktycznej egzaminu państwowego, nie dłużej jednak niż przez okres 12 miesięcy od dnia uzyskania pozytywnego wyniku egzaminu wewnętrznego, z uwzględnieniem ust. 2.”\\t\\n\\tArt. 1 pkt 1 i pkt 3 projektu ustawy\\tOgólnopolski Związek Pracodawców Transportu Drogowego\\tProponowane nowe rozwiązania informatyczne na pewno bardzo kosztowne nie przekładają się jednak na jakość szkolenia. Systemy informatyczne, aplikacje dostępowe, wpisy do komputera, podpisy, akcepcje treści wpisów to strata co najmniej jednej trzeciej czasu każdej godziny szkolenia. Na pewno nie zyska na tym kursant, który trafił do OSK z zamiarem nabycia umiejętności. Obecny system oparty na PKK jest wystarczający do nadzorowania faktycznego ewidencjonowania szkoleń oraz czasu szkolenia. Wydawanie kolejnych środków finansowych na nową informatyzację to nie jest dobre lokowanie środków. Zdecydowanie lepiej tymi środkami bezpośrednio dofinansować kursy w OSK co pozwoli osobom mniej \\fzasobnym ukończyć kurs a nie tylko szukać taniego OSK który w ramach niskich cen sfabrykuje zaświadczenie czy wpis do systemu informatycznego o ukończeniu szkolenia. Jesteśmy społeczeństwem mało zasobnym finansowo poprawa BRD uzyskana poprzez budowę i rozwój infrastruktury drogowej powoli osiąga poziom stabilizacji nadszedł czas na dofinasowanie infrastruktury szkoleniowej, dofinasowanie szkolenia i uzyskanie wyższej jakości nabywanych umiejętności i zachowań. W tym kierunku powinny iść zmiany w szkoleniu i egzaminowaniu to jest kolejny krok w stronę większego BRD. Nowa Dyrektywa 2025/2205 wprowadza bardziej rygorystyczne, harmonizowane zasady wydawania, przedłużania i odnawiania praw jazdy w ramach szerszej strategii bezpieczeństwa drogowego UE. Ustawa, po której branża oczekuje przełamania impasu w systemie szkolenia i egzaminowania proponuje jednak inny kierunek: uproszczenie szkolenia, łatwy przewidywalny egzamin oraz szybkie uzyskanie prawa jazdy. Ponadto stawianie założeń, że głównym cel ustawy poprawa jakości szkolenia osiągnięty zostanie przez zastosowanie nowych rozwiązań informatycznych w ramach Centralnej Ewidencji Kierowców oraz zawartych w niej funkcjonalności obsługujących proces i ewidencję szkoleń i egzaminów osób kandydatów na kierowców jest założeniem bardzo ryzykownym. Dwudziestoletnie doświadczenia budowy CEK wskazują, że nadal nie posiadamy systemu sprawnej ewidencji praw jazdy.\\t\\n\\t Art. 1 pkt 3 projektu ustawy\\t Małopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców\\tUwaga 2. Objęcie cyfrową kartą kursanta całości szkolenia, w tym zajęć teoretycznych, zajęć z zakresu udzielania pierwszej pomocy oraz egzaminu wewnętrznego w części teoretycznej (art. 1 pkt 3 projektu; projektowane art. 23b ust. 1 i art. 23c ust. 1) Treść uwagi: Postulujemy rozszerzenie zakresu cyfrowej karty kursanta na całość szkolenia – również na zajęcia teoretyczne, zajęcia z zakresu udzielania pierwszej pomocy oraz egzamin wewnętrzny w części teoretycznej, wraz z określeniem odrębnego katalogu danych rejestrowanych dla tych form zajęć. Problem: Projektowany art. 23b ust. 1 ogranicza zakres cyfrowej karty kursanta wyłącznie do przebiegu szkolenia w zakresie nauki jazdy oraz części praktycznej egzaminu wewnętrznego, wskutek czego poza jakąkolwiek rejestracją w karcie pozostanie cała część teoretyczna szkolenia, realizowana stacjonarnie albo w formie e-learningu, a także egzamin wewnętrzny w części teoretycznej, podczas gdy karta ma pełnić funkcję kompletnej, wiarygodnej ewidencji \\fprzebiegu szkolenia, stanowiącej podstawę nadzoru starosty oraz weryfikacji rzetelności procesu szkoleniowego. Rozszerzenie katalogu danych z art. 23c ust. 1 wymaga przy tym odrębnej jednostki redakcyjnej z własnym katalogiem danych, z którego muszą zostać logicznie wyłączone trasa jazdy w postaci pliku danych lokalizacyjnych oraz liczba przejechanych kilometrów, ponieważ dane te z natury rzeczy mogą dotyczyć wyłącznie zajęć realizowanych pojazdem i ich mechaniczne odniesienie do zajęć teoretycznych czyniłoby przepis niewykonalnym. Propozycja zmiany zapisu: W art. 1 pkt 3 projektu proponujemy, aby projektowany art. 23b ust. 1 otrzymał brzmienie: „1. Przebieg szkolenia osoby ubiegającej się o uzyskanie uprawnienia do kierowania pojazdem silnikowym, obejmujący zajęcia teoretyczne, zajęcia z zakresu udzielania pierwszej pomocy, naukę jazdy oraz egzamin wewnętrzny w części teoretycznej i w części praktycznej, rejestruje się w cyfrowej karcie kursanta.” oraz aby w projektowanym art. 23c w ust. 1 w pkt 2 w lit. l kropkę zastąpić średnikiem i dodać pkt 3 i 4 w brzmieniu: „3) przebiegu zajęć teoretycznych oraz zajęć z zakresu udzielania pierwszej pomocy: a) imię i nazwisko oraz numer PESEL lub datę urodzenia osoby ubiegającej się o uzyskanie uprawnienia do kierowania pojazdem silnikowym, b) imię i nazwisko oraz numer uprawnień instruktora albo imię i nazwisko wykładowcy prowadzącego zajęcia, c) nazwę ośrodka szkolenia kierowców lub podmiotu prowadzącego szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, oraz numer w rejestrze przedsiębiorców prowadzących ośrodek szkolenia kierowców lub numer w ewidencji podmiotów prowadzących szkolenie, d) datę i godzinę rozpoczęcia zajęć oraz datę i godzinę zakończenia zajęć, e) formę realizacji zajęć, ze wskazaniem, czy zajęcia były prowadzone w formie stacjonarnej, czy w formie nauczania na odległość, f) informację o potwierdzeniu albo odmowie potwierdzenia przebiegu zajęć przez prowadzącego zajęcia lub osobę ubiegającą się o uzyskanie uprawnienia do kierowania pojazdem silnikowym; \\f4) przebiegu części teoretycznej egzaminu wewnętrznego: a) dane i informacje, o których mowa w pkt 3 lit. a i c, b) imię i nazwisko oraz numer uprawnień instruktora albo imię i nazwisko wykładowcy przeprowadzającego część teoretyczną egzaminu wewnętrznego, c) datę przeprowadzenia oraz wynik części teoretycznej egzaminu wewnętrznego, d) informację o potwierdzeniu albo odmowie potwierdzenia przebiegu części teoretycznej egzaminu wewnętrznego przez przeprowadzającego ten egzamin lub osobę ubiegającą się o uzyskanie uprawnienia do kierowania pojazdem silnikowym.” wraz z odpowiednim dostosowaniem projektowanych art. 23c ust. 3 i 4 w zakresie danych wprowadzanych i potwierdzanych przed rozpoczęciem i po zakończeniu zajęć. \\t\\n\\t Art. 1 pkt 3 projektu ustawy\\t Małopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców\\tUwaga 3. Wprowadzenie cyfrowego arkusza przebiegu części praktycznej egzaminu wewnętrznego, prowadzonego w karcie kursanta obok rejestracji obrazu i dźwięku (art. 1 pkt 3 projektu; projektowane art. 23c ust. 1 pkt 2 oraz art. 23h) Treść uwagi: Postulujemy, aby przebieg części praktycznej egzaminu wewnętrznego był rejestrowany nie tylko za pomocą urządzenia służącego do zapisu obrazu i dźwięku, lecz również w postaci ustrukturyzowanego, cyfrowego arkusza przebiegu tego egzaminu, stanowiącego część cyfrowej karty kursanta i obejmującego, w odniesieniu do każdego zadania egzaminacyjnego, jego identyfikator, dane lokalizacyjne, znacznik czasu oraz wynik dla poszczególnych kryteriów oceny. Rejestracja obrazu i dźwięku przewidziana w projektowanym art. 23h pozostaje bez zmian i funkcjonuje równolegle z arkuszem. Problem: Projekt konsekwentnie cyfryzuje całą dokumentację przebiegu szkolenia w cyfrowej karcie kursanta, natomiast wynik części praktycznej egzaminu wewnętrznego rejestruje w projektowanym art. 23c ust. 1 pkt 2 lit. i wyłącznie jako wynik zbiorczy, a poza tym poprzestaje na nagraniu obrazu i dźwięku, które stanowi dane nieustrukturyzowane, wysokowolumenowe i niepoddające się automatycznej analizie. W konsekwencji dokumentacja przebiegu egzaminu wewnętrznego pozostaje w warstwie cyfrowej uboższa niż dokumentacja zwykłych jazd szkoleniowych, mimo że to właśnie egzamin wewnętrzny jest momentem weryfikacji gotowości kursanta. Zapis ustrukturyzowany na poziomie pojedynczego zadania, prowadzony obok nagrania, nie zwiększa istotnie kosztów, ponieważ wykorzystuje tę samą infrastrukturę \\fkarty kursanta i to samo urządzenie lokalizacyjne, które projekt i tak wymaga na podstawie art. 23f pkt 1, a jednocześnie czyni przebieg egzaminu wewnętrznego danymi przetwarzalnymi maszynowo, umożliwiającymi nadzór skalowalny, wykrywanie anomalii oraz zasilanie statystyki bezpieczeństwa ruchu drogowego, podczas gdy nagranie obrazu i dźwięku zachowuje swoją niezastąpioną funkcję dowodową w sytuacjach spornych. Propozycja zmiany zapisu: W art. 1 pkt 3 projektu proponujemy, aby projektowany art. 23c ust. 1 pkt 2 lit. i otrzymała brzmienie: „i) w odniesieniu do każdego zadania egzaminacyjnego – jego identyfikator, dane lokalizacyjne w formacie, o którym mowa w lit. g, znacznik czasu oraz wynik dla poszczególnych kryteriów oceny, a także zbiorczy wynik części praktycznej egzaminu wewnętrznego,” oraz aby w projektowanym art. 23h dodać ust. 6 w brzmieniu: „6. Niezależnie od rejestracji, o której mowa w ust. 1, przebieg części praktycznej egzaminu wewnętrznego rejestruje się w cyfrowym arkuszu przebiegu tego egzaminu, stanowiącym część cyfrowej karty kursanta, obejmującym dane, o których mowa w art. 23c ust. 1 pkt 2 lit. i. Do rejestracji danych lokalizacyjnych oraz znaczników czasu stosuje się odpowiednio art. 23c ust. 5.” \\t\\n\\t Art. 1 pkt 3 projektu ustawy\\t Małopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców\\tUwaga 4. Wykorzystanie danych cyfrowej karty kursanta do analizy jakości szkolenia i informacji zwrotnej dla ośrodków szkolenia kierowców (art. 1 pkt 3 projektu; projektowany art. 23g ust. 3) Treść uwagi: Postulujemy rozszerzenie celu przetwarzania danych lokalizacyjnych zarejestrowanych w cyfrowej karcie kursanta tak, aby obok weryfikacji przebiegu jazd mogły one być przetwarzane, w postaci zagregowanej i zanonimizowanej, do analizy jakości szkolenia, informacji zwrotnej dla ośrodków szkolenia kierowców oraz statystyki bezpieczeństwa ruchu drogowego. Problem: Projektowany art. 23g ust. 3 dopuszcza przetwarzanie danych lokalizacyjnych wyłącznie w celu weryfikacji przebiegu jazd, a więc redukuje cyfrową kartę kursanta do narzędzia czysto kontrolnego, podczas gdy zgromadzone w niej dane, przetwarzane współczesnymi narzędziami analitycznymi, w tym algorytmami sztucznej inteligencji, \\fpozwalają wyznaczać obiektywne mierniki jakości procesu szkolenia, takie jak średnia liczba kilometrów przejeżdżanych przez kursantów w ruchu drogowym w skali ośrodka, rozkład tych wartości w skali kraju wraz ze wskazaniem wartości najwyższych i najniższych, struktura obszarów, na których prowadzone są zajęcia, czy udział jazd realizowanych poza obszarem zabudowanym, a następnie zwracać te informacje ośrodkom szkolenia kierowców i organom nadzoru oraz zasilać statystykę bezpieczeństwa ruchu drogowego. Rozwiązanie takie koresponduje z zadaniem Centrum Egzaminowania określonym w projektowanym art. 57aa ust. 2 pkt 5 i sprawia, że znaczący koszt wdrożenia karty zwróci się w postaci realnej pętli informacji zwrotnej podnoszącej jakość szkolenia, a nie wyłącznie w postaci aparatu sprawozdawczo-kontrolnego. Propozycja zmiany zapisu: W art. 1 pkt 3 projektu proponujemy, aby projektowany art. 23g ust. 3 otrzymał brzmienie: „3. Dane lokalizacyjne w formacie GPX lub równoważnym przetwarza się: 1) w celu weryfikacji przebiegu jazd w trakcie zajęć w zakresie nauki jazdy oraz części praktycznej egzaminu wewnętrznego przez podmioty uprawnione do nadzoru oraz kierownika ośrodka szkolenia kierowców albo innego podmiotu prowadzącego szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3; 2) w postaci zagregowanej i zanonimizowanej, w celu analizy jakości szkolenia kandydatów na kierowców, przekazywania ośrodkom szkolenia kierowców oraz organom nadzoru informacji zwrotnej o jakości szkolenia, a także prowadzenia statystyki bezpieczeństwa ruchu drogowego, w szczególności przez Centrum Egzaminowania, o którym mowa w art. 57aa ust. 1.” wraz z odpowiednim uzupełnieniem katalogu podmiotów, o których mowa w projektowanym art. 23e ust. 1, o Centrum Egzaminowania w zakresie dostępu do danych w postaci zagregowanej i zanonimizowanej, ponieważ bez tego uzupełnienia cel analityczny określony w proponowanym pkt 2 pozostawałby bez podstawy dostępowej. \\t\\n\\tArt. 1 pkt 3 projektu ustawy  \\tPolski Związek Szkoleniowy\\ta) Proponujemy dostosowanie przepisów do rejestracji całości przebiegu zarówno szkolenia (teoria, praktyka zajęcia z pierwszej pomocy) jak i egzaminu wewnętrznego zgodnie z opisem powyżej.   \\fb) W proponowanym art. 23b w ust. 2 wskazujemy, że organ właściwy w sprawach wydawania dokumentów stwierdzających uprawnienia do kierowania pojazdami tworzy cyfrową kartę kursanta i generuje indywidualny numer kursanta. W naszej ocenie brakuje tu odesłania do tworzenia profilu kandydata na kierowcę który do tej pory był opisany w rozporządzeniu w sprawie wydawania dokumentów stwierdzających uprawniania do kierowania pojazdami. Aby zachować właściwą kolejność tworzonych przez starostę dokumentów proponujemy następujące brzmienie tego przepisu:  „2. Organ właściwy w sprawach wydawania dokumentów stwierdzających uprawnienia do kierowania pojazdem silnikowym, generując profil kandydata na kierowcę w systemie teleinformatycznym tworzy cyfrową kartę kursanta i generuje indywidualny numer kursanta.”  Takie rozwiązanie będzie zgodne z dotychczasowym rozwiązaniem informatycznym i wskaże staroście kolejność zadań. Przeniesienie zadania tworzenia profilu kandydata na kierowcę z rozporządzenia do ustawy jest niezbędne do wskazania i utrzymania jednolitego trybu postępowania w tych sprawach.   c) W proponowanym art. 23c w ust. 1 pkt 1 lit i sugerujemy usunięcie możliwości wskazywania liczby kilometrów poprzez ręczne wpisywanie wskazań licznika pojazdu. Takie rozwiązanie niestety spowoduje, że tak czy inaczej będą wpisywane niewłaściwe informacje. Tylko automatyczna rejestracja za pomocą GPS rozwiązuje ten problem.   d) Odnosząc się do zapisywania śladu GPS tylko w formacie pliku GPX należy wskazać, że jest to zbyt mało. Na rynku istnieją programy, które służą do podmiany danych zapisanych w plikach GPX. I to nie po ich utworzeniu, a w czasie rzeczywistym Jest to tzw. GPS spoofing. Rozwiązaniem jest np. zapis dwóch plików zarówno od kursanta jak i od instruktora, albo danych z BTS.   e) W proponowanym art. 23c ust. 2 sugerujemy dodanie warunku aby instruktor miał dostęp do tych danych, ale dopiero po potwierdzeniu swojej tożsamości (np. po zalogowaniu się do aplikacji instruktora potwierdzając swoją tożsamość poprzez login.gov.). Samo wprowadzenie indywidualnego numeru instruktora nie jest wystarczające, a tym bardziej wyłącznie podanie imienia nazwiska i numeru instruktora. Mimo wszystko jest to dostęp do \\fdanych osobowych kursanta. Imię, nazwisko i nr instruktora może wpisać każdy i znać każdy. Jest tu duże pole do popisu dla obchodzenia przepisów.   f) W naszej ocenie możliwość podpisania (zatwierdzenia) zarówno rozpoczęcia szkolenia jak i jego zakończenia (przez kursanta i instruktora) powinna być możliwa dopiero po zalogowaniu się i uwierzytelnieniu tożsamości kursanta w aplikacji (lub WEB). Zarówno kursant jak i instruktor powinien móc zalogować się do aplikacji na 10 minut przed rozpoczęciem zajęć i wylogować się na 10 minut po zakończeniu zaplanowanych zajęć. Takie rozwiązanie pozwoli na uniknięcie sytuacji w której OSK wyposaży swoich kursantów w tablety lub smartfony, do których kursanci zalogują się tylko (potwierdzą tożsamość) raz na początku szkolenia, a instruktor będzie je mógł wozić ze sobą i potwierdzać kolejne zajęcia za siebie i za kursanta przekazanym nr kursanta. Obowiązek zalogowania przed zajęciami i wylogowania po zajęciach (tu może być automat wylogowujący po stwierdzeniu potwierdzenia zakończenia danych zajęć)   g) W proponowanym art. 23c ust. 3 i 4 sugerujemy usunięcie obowiązku wpisywania przez instruktora do cyfrowej karty kursanta danych dotyczących ośrodka szkolenia czy daty i godziny rozpoczęcia zajęć. Te dane powinny być już wpisane automatycznie przez system. Najpierw kursant przychodzi do ośrodka szkolenia kierowców i zapisuje się na kurs, a więc dana karta przydzielona jest już do właściwego ośrodka szkolenia. Numer instruktora także powinien wpisywać się automatycznie. To ośrodek szkolenia kierowców wyznacza dla danej osoby instruktora prowadzącego, zatem wiadomo jaki instruktor powinien prowadzić szkolenie danej osoby.   Pozostawienie tego przepisu w takiej formie jak dziś może spowodować, że dowolny instruktor niezatrudniony w danym OSK będzie mógł w cyfrowej karcie kursanta wpisać  dowolny OSK i dowolnego instruktora. Kursant i tak tego nie sprawdzi i potwierdzi. Narażamy się na powstanie kolejnej patologii.  Podobnie po zakończeniu zajęć. Zarówno godzina zakończenia, jak i liczba kilometrów przejechanych powinna być wpisywana automatycznie na podstawie danych GPS.   h) W odniesieniu do art. 23c ust. 5 proponujemy rozważenie bieżącego przesyłania danych do cyfrowej karty kursanta wraz z danymi z BTS. W naszej ocenie możliwość późniejszego \\fprzesłania wygenerowanego pliku daje możliwość podstawienia dowolnych danych już w momencie zakończenia zajęć. Wystarczy, że ktoś będzie miał wcześniej przygotowany plik i stosowany przez niego program podstawi go w momencie zakończenia szkolenia.   i) W odniesieniu do art. 23d ust. 1 proponujemy jednoznaczne wskazanie kto i na jakich zasadach będzie miał dostęp do uwag kursanta co do przebiegu szkolenia. W naszej ocenie powinno to być tak samo jak w przypadku przyczyny odmowy potwierdzenia zajęć, ale dodatkowo ta informacja powinna dostępna zarówno w przypadku odmowy jak i w przypadku potwierdzenia. Uwagi kursanta mogą powstać także jak potwierdzi zajęcia. Do uwag powinien też mieć wgląd organ nadzoru.   j) W odniesieniu do art. 23d ust. 3 proponujemy dodanie konieczności akceptacji dokonywanych zmian przez co najmniej kierownika OSK, ale najlepiej gdyby musiał zrobić to organ nadzoru (starosta). Pozostawienie możliwości korekty bez odgórnego zatwierdzenia wydaje się niezasadne. Tutaj także należy uwzględnić brak możliwości korekty OSK które prowadziło szkolenie. (patrz lit. f)   k) W odniesieniu do art. 23d ust. 6 proponujemy zamianę słowa „lub” na „jednak nie później niż”. Pozostawienie tu słowa lub daje możliwość wprowadzenia tych danych np. po 3 miesiącach jeżeli następne zajęcia odbędą się dopiero za 3 miesiące. Nasza propozycja zawęża maksymalny termin wprowadzenia tych danych do 7 dni.   l) W odniesieniu do art. 23e ust. 1 pkt 4 proponujemy likwidację dostępu WORD do danych umieszczonych w cyfrowej karcie kursanta. W naszej ocenie żadne dane z danych umieszczonych w tej karcie nie są WORD potrzebne. WORD potrzebuje wyłącznie danych umieszczonych w CEPIK dotyczących zaświadczenia o ukończonym szkoleniu. Możliwość dostępu do pozostałych danych jest dostępem nadmiarowym niepotrzebnym do realizacji zadań WORD.   m) W odniesieniu do art. 23e ust. 2 w naszej ocenie trzeba się zdecydować, czy nadal będziemy mieli do czynienia z profilem kandydata na kierowcę, czy nie. W nowo przygotowanym przepisie art. 27 ust. 4b dodajemy informację że zaświadczenie o \\fukończeniu szkolenia wystawia się za pomocą wpisania tej informacji do CEPIK. Dotychczas to zaświadczenie wpisywało się poprzez uzupełnienie profilu kandydata na kierowcę (patrz § 16 rozporządzenia w sprawie szkolenia osób ubiegających się o uprawnienia do kierowania pojazdami). Zatem jeżeli zamierzamy pozostawić profil to warto byłoby przenieść zapis z rozporządzenia do ustawy, lub wprowadzić przepis, że wprowadza się do CEPIK poprzez aktualizację profilu kandydata na kierowcę. Takie rozwiązanie rozwieje wątpliwości co do sposobu postępowania i miejsca w systemie cyfrowej karty przeprowadzonych zajęć.  \\t\\n\\tArt. 1 pkt 1 oraz pkt 3 projektu ustawy w zakresie  art. 2 pkt 6 i art. 23b ust. 2 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tProponuje się rezygnację z odrębnego „indywidualnego numeru kursanta” generowanego przez organ właściwy w sprawach wydawania dokumentów stwierdzających uprawnienia. Jako identyfikator kursanta powinien być wykorzystywany PESEL, a do czasu utrzymania PKK - numer PKK. Jeżeli z przyczyn technicznych niezbędny jest dodatkowy token/logowanie do cyfrowej karty kursanta, powinien być generowany automatycznie w systemie centralnym lub w aplikacji mObywatel, bez udziału starosty i bez konieczności ponownej wizyty obywatela w urzędzie. Uzasadnienie: Projekt w obecnym brzmieniu może oznaczać, że kandydat najpierw uzyska PKK, a następnie będzie musiał ponownie wystąpić do organu o wygenerowanie indywidualnego numeru kursanta. Takie rozwiązanie dubluje identyfikatory i tworzy dodatkową czynność administracyjno-techniczną po stronie starostw. Nie jest jasne, dlaczego funkcji identyfikacyjnej nie może pełnić istniejący numer PKK lub PESEL, skoro dane kursanta, badania lekarskie, badania psychologiczne i dalsze czynności mają być w praktyce powiązane z jedną osobą.\\t\\n\\tArt. 1 pkt 3 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 3 Wprowadzono obowiązek rejestracji szkolenia. Zmiana wyrównuje dla wszystkich szkół warunki prowadzenia szkolenia. Eliminuje szkoły które nierzetelnie prowadzą szkolenie. Z naszego punktu widzenia jest to korzystna zmiana.\\t\\n                               \\tArt. 1 pkt 3 w zakresie art. 23c ust. 5 ustawy o kierujących pojazdami \\t\\fLiga Obrony Kraju\\tW Art. 1 zmiana 3) Art. 23c ust.5 Jest zapis, że instruktor w przypadku problemów technicznych ma obowiązek dokumentowania szkolenia „ w inny sposób”. W ust. 6 jest obowiązek uzupełnienia danych w cyfrowej karcie kursanta jeszcze przed kolejną jazdą. Proponujemy doprecyzowanie co konkretnie ma dokumentować instruktor. \\fW późniejszym czasie raczej na pewno nie będzie mógł uzupełnić danych lokalizacyjnych pojazdu w odstępie 5 sekund.\\t\\n\\tArt. 1 pkt 1 oraz pkt 3 projektu ustawy w zakresie art. 2 pkt 7 i art. 23c ust. 1 pkt 1 lit. b oraz ust. 2 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tProponuje się rezygnację z odrębnego „indywidualnego numeru instruktora” albo jednoznaczne wskazanie, że jest nim numer instruktora w ewidencji instruktorów. W art. 23c ust. 1 pkt 1 lit. b i pkt 2 lit. b należy posługiwać się pojęciem „numer w ewidencji instruktorów”, a nie niejednoznacznym sformułowaniem „numer uprawnień instruktora”. Uzasadnienie: Numer instruktora jest już nadawany i ujawniany w ewidencji instruktorów prowadzonej przez starostę. Wprowadzanie kolejnego numeru identyfikującego tę samą osobę zwiększa ryzyko niespójności danych, błędów przy kontroli oraz problemów przy integracji z mLegitymacją instruktora lub innymi dokumentami cyfrowymi. Z perspektywy samorządów racjonalne jest wykorzystanie istniejącego numeru ewidencyjnego, a nie mnożenie identyfikatorów.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23c ust. 1 pkt 1 lit. b ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tWe wskazany zapisie prawnym zgodnie z właściwą terminologią nie powinno być „numer uprawnień instruktora” tylko „numer ewidencyjny instruktora”.  Uzasadnienie:  W projekcie użyto błędnej terminologii.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23c ust. 1 pkt 1 lit. i oraz pkt 2 lit. h ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy rozważyć zasadność zapisu mówiącym o wskazaniu liczby przejechanych kilometrów wg wskazań licznika pojazdu.  Uzasadnienie: Jeśli ustawodawca stawia na transparentność to we wskazanym artykule nie powinno się już polegać na wskazaniu licznika pojazdu, który z reguły odczytywany jest przez instruktora\\t\\n\\tArt. 1 pkt 3 projektu ustawy w \\fzakresie  art. 23c ust.1 pkt 1 lit. k i art. 23d ust. 1 oraz  art. 23f pkt 3 ustawy o kierujących pojazdami\\t\\fUnia Metropolii Polskich im. \\fPawła Adamowicza\\t\\fNależy rozważyć zasadność zapisów stanowiących o wnoszeniu uwag przez osoby ubiegające się o uzyskanie uprawnienia do kierowania pojazdem silnikowym  dotyczące przebiegu zajęć  oraz części praktycznej egzaminu wewnętrznego do cyfrowej karty kursanta.  Uzasadnienie: W treści uzasadnienia nie poruszono zasadności wnoszenia uwag przez osoby ubiegającą się o uprawnienia do kierowania pojazdem silnikowym dotyczących przebiegu zajęć. Wprowadzenie przedmiotowego zapisu dającemu w pewien sposób ingerować osobie szkolonej w proces szkolenia, może skutkować powstaniem pewnego rodzaju nadużyć ze strony osoby szkolonej poprzez wywieranie presji na instruktora m.in. w przypadku, gdy ten uzna, iż osoba szkolona nie jest jeszcze przygotowana do przystąpienia, do egzaminu państwowego, a tym samym  winna kontynuować szkolenie. Może to skutkować nieuzasadnionymi skargami na instruktorów.   \\t\\n\\tArt. 1 pkt 3 projektu w zakresie art. 23d ust. 5 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tW dodanym art. 23d ust. 5 należałoby doprecyzować następującą część zdania: „albo dokumentuje ją w inny sposób wraz z danymi i informacjami”. Uzasadnienie:  Doprecyzowanie wskazanego zapisu pozwoli uniknąć nieporozumień w trakcie sprawowanego nadzoru przez właściwego starostę nad ośrodkiem szkolenia kierowców\\t\\n\\tArt. 1 pkt 3 projektu w zakresie art. 23d ust. 5-7 i art. 23f pkt 4 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy doprecyzować tryb postępowania w przypadku awarii systemu, braku łączności, błędu aplikacji albo awarii urządzenia lokalizacyjnego. Przepis powinien określać: kto dokumentuje awarię, w jakiej formie, czy możliwe jest prowadzenie kolejnych zajęć przed uzupełnieniem danych, jak odróżnić awarię systemową od naruszenia po stronie OSK oraz kiedy OSK ma obowiązek zgłoszenia problemu staroście. Należy zdefiniować stwierdzenie tzw.” przyczyn technicznych” i określić precyzyjną procedurę postępowania w przypadku ich wystąpienia aby uniknąć nadużyć w tym zakresie ze strony podmiotów szkolących. Należy rozważyć uzupełnienie stwierdzenia w proponowanym ustępie 7, np. w sposób:  „następuje niezwłocznie, nie później niż następnego dnia …”  Konieczne wydaje się również zdefiniowanie sankcji za brak realizacji tego obowiązku. Uzasadnienie: \\fObecne przepisy wskazują terminy późniejszego wprowadzenia danych, ale nie tworzą pełnej procedury awaryjnej. W praktyce może to prowadzić do masowego kierowania do starostów zgłoszeń o problemach technicznych, także wtedy, gdy problem leży po stronie systemu centralnego lub aplikacji. Należy uniknąć sytuacji, w której starosta staje się adresatem zgłoszeń technicznych bez narzędzi do ich weryfikacji i usunięcia. Obecna propozycja tej regulacji umożliwia w każdym przypadku zastosowanie przez podmiot szkolący wytłumaczenia w postaci wystąpienia trudności o charakterze technicznym, co w przypadku świadomych nadużyć i nieprawidłowości uniemożliwi organom nadzorującym szkolenie ich stwierdzenie.   Określenie „niezwłocznie” pozostawia zbyt wiele pola do nadinterpretacji tego terminu. Brak ustawowej odpowiedzialności spowoduje, że regulacja będzie „martwą”.  \\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23d ust. 6 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tWe wskazanym zapisie zasadnym byłoby zastąpienie jego drugiej części, tj. cyt,: „(…) lub przed rozpoczęciem kolejnych zajęć z osobą szkoloną.”, zapisem zawartym w ust. 7, w którym mówi się o wprowadzeniu danych, cyt. „(…) niezwłocznie po ustaniu przyczyny uniemożliwiającej ich wprowadzenie.”    Uzasadnienie: Wskazana propozycja zmiany nie ograniczałaby kursanta do wstrzymania procesu szkolenia, w przypadku nie usunięcia usterki uniemożliwiającej potwierdzenie przez instruktora przebiegu szkolenia w zakresie nauki jazdy w cyfrowej karcie kursanta przed kolejnym zajęciami praktycznymi.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23f ustawy o kierujących pojazdami\\tWielkopolskie Stowarzyszenie OSK i Instruktorów \\tWyposażanie pojazdów szkoleniowych w urządzenia mające wysyłać informacje o trasie w postaci plików GPX to dodatkowe obciążenie przedsiębiorcy prowadzącego szkolenie. Urządzenie takie będzie musiało nie tylko współpracować z zewnętrznym systemem, które zasad działania (technicznych) nie znamy, ale również będzie musiało mieć stałą łączność z siecią Internet, co w wielu miejscach może być niemożliwe.  \\fPojazdy nauki jazdy (w szczególności pojazdu osobowe) bardzo często wykorzystywane są przez właścicieli również do użytku prywatnego, zatem nieustanne wysyłanie informacji o lokalizacji pojazdu lub przebytych trasach nie powinno mieć miejsca. \\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23e, art. 23g oraz art. 23j ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy jednoznacznie określić zakres dostępu do danych cyfrowej karty kursanta, danych lokalizacyjnych i nagrań dla wszystkich podmiotów wykonujących realne czynności nadzorcze, w tym starosty nadzorującego OSK, kuratora oświaty w odniesieniu do szkół, właściwych podmiotów resortowych w odniesieniu do szkoleń szczególnych oraz Policji działającej na podstawie porozumień ze starostą. Jednocześnie należy przesądzić, czy projekt rozszerza zakres nadzoru starosty nad podmiotami, które dotychczas pozostawały poza jego bezpośrednią właściwością.  Uzasadnienie: Z projektu wynika znaczne wzmocnienie narzędzi nadzoru nad szkoleniem, ale nie jest jasne, czy dostęp do danych odpowiada rzeczywistemu podziałowi kompetencji. Starosta prowadzący ewidencję instruktorów ma być pozbawiony dostępu do danych lokalizacyjnych, a jednocześnie projekt nakłada na OSK obowiązki, których kontrola może wymagać analizy trasy, czasu i przebiegu jazd. W praktyce nadzór nad OSK jest często wykonywany przy współpracy z Policją. Brak dostępu lub niepełny dostęp podmiotów kontrolujących może uczynić nowe obowiązki nieweryfikowalnymi.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23e ust. 2 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy doprecyzować, w jaki sposób podmioty wymienione w art. 23e ust. 1 będą uzyskiwać dostęp do danych cyfrowej karty kursanta, jeżeli PKK zostanie zastąpione albo ograniczone w wyniku innych projektów cyfryzacyjnych. Przepis powinien odwoływać się do docelowego identyfikatora i systemu centralnego, a nie wyłącznie do profilu kandydata na kierowcę.  Uzasadnienie: Projekt jednocześnie tworzy indywidualny numer kursanta i przewiduje dostęp do danych przy użyciu PKK. Powstaje pytanie, jaka jest funkcja nowego numeru, skoro dostęp organów ma następować przez PKK. Brak spójności może prowadzić do sytuacji, w której organy i OSK będą obsługiwały równolegle kilka identyfikatorów, co utrudni kontrolę, obsługę cudzoziemców i migrację danych do systemu opartego na PESEL.\\t\\n\\tArt. 1 pkt 3 projektu \\fustawy w zakresie art. 23f pkt 4 ustawy o kierujących pojazdami\\t\\fUnia Metropolii Polskich im. \\fPawła Adamowicza\\t\\fW zapisie zawartym w projekcie należy rozważyć czy po wyrazach, cyt. „w ciągu 7 dni”, nie byłoby zasadnym dodać  zapis o treści, cyt.” lub niezwłocznie po ustaniu przyczyn \\funiemożliwiających ich wprowadzenie. Jednocześnie należałoby doprecyzować formę informacji przekazywanej przez ośrodek szkolenia kierowców właściwemu staroście. Należy rozważyć określenie precyzyjnego terminu zgłaszania staroście faktu braku możliwości wprowadzenia lub potwierdzenia danych i informacji dotyczących przebiegu szkolenia lub części praktycznej egzaminu wewnętrznego w cyfrowej karcie kursanta, poprzez zastosowanie stwierdzenia np. niezwłocznie, nie później niż następnego dnia …  Uzasadnienie: Proponowana zmiana (w pierwszym zdaniu) jest powiązana z treścią uwagi zawartej w pkt 8 niniejszej tabeli. Wskazanie jednoznacznej formy przekazania przedmiotowej informacji będzie miało na celu jasny sposób komunikacji między ośrodkiem szkolenia kierowców a właściwym starostą.  Brak precyzyjnego wskazania terminu zgłaszania staroście tego faktu pozostawia ośrodkom szkolenia pełną dowolność w realizacji tego obowiązku, a co za tym idzie nieskuteczność nadzoru w tym obszarze.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23g ust. 1 ustawy o kierujących pojazdami\\tPolska Wytwórnia Papierów Wartościowych S.A.\\tW konsekwencji przyjęcia uwagi zawartej w poz. 1, administratorem danych osobowych zarejestrowanych \\nw cyfrowej karcie kursanta będzie organ właściwy do spraw wydawania dokumentów stwierdzających uprawnienia do kierowania pojazdami, który wygenerował tę kartę.  Projektowane brzmienie art. 23g ust. 1 ustawy powinno otrzymać brzmienie:  „1. Administratorem danych osobowych zarejestrowanych w cyfrowej karcie kursanta \\nw zakresie wydanej karty jest organ właściwy do spraw wydawania dokumentów stwierdzających uprawnienia do kierowania pojazdami, który wygenerował tę kartę.”. \\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie  art. 23g  ust. 3\\tLiga Obrony Kraju\\t4. W Art. 1 zmiana 3) Art. 23g ust.3 Jest zapis, że „Dane lokalizacyjne w formacie GPX ... przetwarza się wyłącznie w celu weryfikacji przebiegu jazd w trakcie zajęć”. Niestety uprawnione organy wg obecnych i proponowanych przepisów w zasadzie mogą tylko sprawdzać czy położenie pojazdu było rejestrowane i jaki był czas szkolenia. \\fPrzepisy regulują tylko egzaminy i kilka godzin szkolenia poza obszarem zabudowanym. Dla pozostałych godzin szkolenia instruktor w praktyce ma pełną dowolność gdzie i ile jeździ. Organy uprawnione nie mają podstawy, normy aby zakwestionować np. ilość przejechanych kilometrów, czy trasę przejazdu. Rejestracja czasu szkolenia też może rodzić spory. Liga Obrony Kraju od wielu lat korzysta z urządzeń lokalizujących pojazdy. Z naszego doświadczenia wiemy, że żaden pojazd nie jeździ 60 minut w trakcie jednej godziny szkoleniowej. Od sprawdzenia pojazdu przed jazdą, zajęcia miejsca, dopasowania fotela, lusterek do uruchomienia silnika i jazdy mija troszkę czasu. Po zakończonej jeździe trzeba też wypełnić dokumenty. Realnie z godziny szkolenia pozostaje np. 50 min kiedy pojazd jeździ. Jeśli nie ma obowiązujących norm, to ww. przypadku złośliwy urzędnik będzie mógł stwierdzić uchybienie i w konsekwencji będzie mógł zamknąć ośrodek. Ocena, weryfikacja prawidłowości szkolenia nie powinna opierać się tylko na niemierzalnej ocenie, poglądach kontrolującego urzędnika, który nie zawsze ma potrzebne kompetencje. Zbieranie danych lokalizacyjnych jeśli dalej praktycznie nie będą mogły być wykorzystane narusza zasady RODO. Może być zakwestionowane praktycznie przez każdego kursanta. Jeśli zastrzeżenia podzieli Prezes Urzędu Ochrony Danych Osobowych to ośrodki szkolenia jako administratorzy danych osobowych będą miały problem.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23h ust. 3 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy przeanalizować czy zapis wskazanego artykułu nie jest zbyt szeroki, gdyż w jego treści wskazano, że urządzenie techniczne służące do zapisu obrazu i dźwięku przebiegu części praktycznej egzaminu wewnętrznego winno odpowiadać warunkom określonym w przepisach wydanych na podstawie art. 66 ust. 1 pkt 1-5, 7 i 8. Tym samym należy rozważyć czy wskazanego zapisu nie ograniczyć do art. 66 ust. 1 pkt 1, pkt 4 lit. a, lit. c i  lit. d oraz pkt 5.    Uzasadnienie: Propozycja zmiany ma na celu uszczegółowienie projektu przedstawionego zapisu\\t\\n\\tArt. 1 pkt 3 i 4 projektu ustawy w zakresie art. 23f pkt 1, art. 23h oraz art. \\f24 pkt 1 lit. e ustawy o kierujących pojazdami\\t\\fUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy doprecyzować, czy urządzenie lokalizacyjne oraz urządzenie do rejestracji obrazu i dźwięku mają stanowić obowiązkowe wyposażenie każdego pojazdu wykorzystywanego do nauki jazdy albo egzaminu wewnętrznego, czy wystarczy zapewnienie przez OSK określonego sposobu rejestracji. W projekcie lub w delegacji do aktu wykonawczego należy wskazać minimalne wymagania techniczne oraz sposób weryfikacji sprawności tych \\furządzeń, w tym rozważyć powiązanie z dodatkowym badaniem technicznym pojazdu nauki jazdy.  Uzasadnienie: W obecnym brzmieniu projekt przewiduje obowiązki GPS i nagrywania egzaminu wewnętrznego, ale nie przesądza, jak organy mają sprawdzać, czy pojazd „L” faktycznie jest wyposażony w wymagane urządzenia i czy są one sprawne. Powstaje też wątpliwość, czy kamery mają być zamontowane w każdym pojeździe szkoleniowym, czy tylko w pojeździe używanym do egzaminu wewnętrznego. Brak takich regulacji może powodować różną praktykę kontrolną w powiatach oraz spory z OSK.  \\t\\n\\tArt. 1 pkt 3 w zakresie art. 23f ustawy o kierujących pojazdami\\tPolski Związek Szkoleniowy\\t19) Proponujemy także wprowadzenie odrębnej delegacja ustawowa dla ustalenia zasad i sposobu prowadzenia rejestracji GPS (zasady, dane gromadzone, wykorzystywane systemy itp.) co znacznie ułatwi bieżące dostosowanie systemów.  \\t\\n\\tArt. 1 pkt 3 i 5 projektu ustawy w zakresie art. 23j oraz art. 27 ust. 1 pkt 7 i ust. 2 pkt 6 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy wydłużyć albo elastycznie ukształtować okres przechowywania nagrań z części praktycznej egzaminu wewnętrznego. Co najmniej należy wprowadzić obowiązek zabezpieczenia nagrania na żądanie organu nadzoru lub po zgłoszeniu zastrzeżeń przez kursanta przed upływem 90 dni. Alternatywnie należy rozważyć przechowywanie nagrań przez okres umożliwiający wykorzystanie ich w ramach okresowej kontroli OSK.  Uzasadnienie: Projekt przewiduje 90-dniowy okres przechowywania nagrania, podczas gdy kontrole OSK są co do zasady prowadzone okresowo, a informacja o nieprawidłowościach może ujawnić się po upływie tego terminu. Jeżeli nagranie ma być realnym narzędziem dowodowym dla organu nadzoru, system musi zapewniać możliwość jego zabezpieczenia i wykorzystania także wtedy, gdy sprawa nie zostanie wykryta natychmiast po egzaminie wewnętrznym.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. \\f23j ust. 1 ustawy o kierujących pojazdami\\t\\fUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy przeanalizować zasadność przechowywania zapisu przebiegu części praktycznej egzaminu wewnętrznego przez okres 90 dni. Należałoby zastąpić wskazany okres sformułowaniem: od dnia przeprowadzenia kompleksowej kontroli ośrodka szkolenia kierowców do dnia zakończenia kolejnej kontroli kompleksowej tego ośrodka.  Uzasadnienie: Propozycja zmiany przedstawionego zapisu jest podyktowana tym, iż w wielu przypadkach czynności kontrolne organu nadzoru przeprowadzane są nawet po 12 miesiącach, licząc od poprzedniej kontroli.\\t\\n\\tArt. 1 pkt 3 projektu ustawy w zakresie art. 23j ust. 4 ustawy o kierujących pojazdami\\tLiga Obrony Kraju\\tW Art. 1 zmiana 3) Art. 23j ust.4 Dotyczy udostępnienia nagrania z egzaminu. Regulacja w zasadzie powtarza prawo wynikające z Art. 15 ust. 3 rozporządzenia RODO czyli ustęp w obecnej treści może być pominięty. Art. 15 ust. 4 rozporządzenia RODO pozwala  przekazać kopię ale tylko w sposób nie naruszający praw innych osób. Przeciętny ośrodek nie ma możliwości usunięcia z nagrania wizji i dźwięku tylko danych osób trzecich. Proponujemy zamiast obecnej treści ustępu wpisać regulację, która ograniczy prawo kursanta do dalszego dysponowania otrzymanym nagraniem. Kursant również nie powinien mieć prawa do korzystania z nagrania w celach reklamowych, promocyjnych, komercyjnych itd. Ogólnie w sposób naruszający dobro osób trzecich.\\t\\n\\tArt. 1 pkt 4 projektu ustawy  \\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t Ad. art. 1 pkt 4 projektu  Zaproponowana zmiany art. 24 pkt 1 lit. d UoKP ma charakter nadmiarowy (i jako taki zbędny). Zakres dodatkowego wyposażenia pojazdu przeznaczonego do prowadzenia nauki jazdy reguluje, wydane na podstawie art. 66 ust. 5 ustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym, rozporządzenie Ministra Infrastruktury w sprawie warunków technicznych pojazdów oraz zakresu ich niezbędnego wyposażenia z dnia 31 grudnia 2002 r., a konkretnie § 43 tego rozporządzenia. Dlatego tez to właśnie w tym akcie wykonawczym należałoby ewentualnie wprowadzić odpowiednie zmiany wprowadzające odpowiednie urządzenie geolokalizacyjne, jako obowiązkowe wyposażenie pojazdu przeznaczonego do szkolenia.  Jednocześnie w przypadku pozostawienia koncepcji „cyfrowej karty kursanta” i wprowadzenia odpowiednich zmian w ww. rozporządzeniu, należałoby – w opinii TLP – zapewnić możliwość alternatywnego używania smartfona lub tabletu, jako urządzenia geolokalizacyjnego. Takie rozwiązanie stosowane jest w wielu polskich systemach teleinformatycznych, gdzie potrzebne jest śledzenie trasy pojazdu. Przykładem może być system SENT lub system e-toll, gdzie wykorzystywana jest bezpłatna aplikacja „e-toll”. Jeśli dla celo w zabezpieczenia wpływów z akcyzy i podatku VAT, dopuszcza się taką alternatywę, \\fto nie istnieje jakakolwiek, racjonalna przesłanka, która mogłaby uniemożliwić takie rozwiązanie w znacznie mniej istotnym z punktu widzenia interesów państwa systemie.  Odnosząc się do przepisu art. 24 UoKP, stanowiącego o pojazdach używanych w trakcie zajęć praktycznych, postulujemy wprowadzenie możliwości przeprowadzania części zajęć na pojazdach innych niż te, kto re wskazane są w pkt 1 lit. c. Jako przykład można tutaj wskazać szkolenie w zakresie prawa jazdy kategorii C+E, gdzie zgodnie z postulatami branży transportowej, wprowadzono obligatoryjne szkolenie z wykorzystaniem ciągnika siodłowego i naczepy. Podtrzymujemy pełne poparcie dla tego rozwiązania, niemniej chcielibyśmy usunąć barierę dla fakultatywnego przeprowadzania części zajęć praktycznych na tzw. tandemie (samochodzie ciężarowym z przyczepą). Np. w przypadku, gdy uczestnik kursu jest szkolony na  potrzeby konkretnego przedsiębiorstwa. W wyniku takiego hybrydowego szkolenia, przyszły kierowca uzyska nie tylko obligatoryjne kwalifikacje w kierowaniu dominującym w przewozach rzeczy zestawem (ciągnik + naczepa), ale także uzyska umiejętność kierowania ww. tzw. tandemem.  Dlatego tez proponujemy w art. 24 UoKP dotychczasową treść oznaczyć jako ust. 1 i dodać ust. 2 w brzmieniu:  „2. Część zajęć praktycznych w ramach nauki jazdy może być prowadzona pojazdami odpowiadającymi kategorii prawa jazdy w zakresie której prowadzone jest szkolenie, innymi niż pojazdy wskazane w ust. 1 pkt 1 lit. c.”\\t\\n\\tArt. 1 pkt 4 projektu ustawy  \\tPolski Związek Szkoleniowy\\tW odniesieniu do art. 1 w pkt 4 w proponowanym przepisie zawarto obowiązek wyposażenia pojazdów do nauki jazdy w urządzenie lokalizacyjne o którym mowa w art. 23f pkt 1. Z tym że w art. 23f pkt 1 jest także mowa o aplikacji mobilnej zintegrowanej z cyfrową kartą kursanta. W naszej ocenie w proponowanym przepisie zabrakło wyłączenie odnoszącego się do tej aplikacji. Proponujemy następujące rozwiązanie:   „e) wyposażonym w urządzenie lokalizacyjne, o którym mowa w art. 23f pkt 1 – w zakresie szkolenia osób ubiegających się o uzyskanie uprawnienia do kierowania pojazdem silnikowym  – nie dotyczy pojazdów w których podczas szkolenia wykorzystuje się aplikację mobilną zintegrowaną z cyfrową kartą kursanta zapewniającą możliwości rejestrowania trasy jazdy;”;\\t\\n\\tArt. 1 pkt 4 projektu ustawy  \\tOIGOSK, LFEDERACJA, PIGOSK\\tpkt.4 wykreślić  4) w art. 24 w pkt 1 w lit. d średnik zastępuje się przecinkiem i dodaje się lit. e w brzmieniu: „e) wyposażonym w urządzenie lokalizacyjne, o którym mowa w art. 23f pkt 1 – w zakresie szkolenia osób ubiegających się o uzyskanie uprawnienia do kierowania pojazdem silnikowym;”; Uzasadnienie Vide uzasadnienie do pkt.1 powyżej 3.\\t\\n\\tArt. 1 pkt 5 projektu ustawy w zakresie art. 27 ust. 1 ustawy o kierujących pojazdami \\tUnia Metropolii Polskich im. Pawła Adamowicza\\tW dodanym pkt 7 do art. 27 ust. 1 właściwym winno być: plik z nagraniem, o którym mowa w art. 23h ust. 5, a nie jak zapisano w projekcie art. 23h ust. 4.   Uzasadnienie:  Zapis, o którym mowa wydaje się być oczywistą omyłką pisarską.\\t\\n\\tArt. 1 pkt 5 lit. a projektu ustawy\\tPolski Związek Szkoleniowy\\tW odniesieniu do art. 1 w pkt 5 w lit. a w proponowanym pkt 7 jest błędne odesłanie zamiast art. 23h ust. 4 powinno być ust. 5.  \\t\\n\\tArt. 1 pkt 5 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 5) c) i 5) d) Przenosi dokumentację szkoleniową z wersji papierowej do wersji elektronicznej. Zgodnie z treścią proponowanego art. 23b. cały przebieg szkolenia i części praktycznej egzaminu wewnętrznego będzie rejestrowany elektronicznie. Czy w tej sytuacji zasadnym jest prowadzenie nawet w wersji elektronicznej np. Karty przeprowadzonych zajęć ?. Uważamy, że przy tak znaczącej zmianie w prowadzeniu dokumentacji szkoleniowej konieczne jest jak najszybsze opublikowanie nowej wersji obecnego Rozporządzenia Ministra Infrastruktury i Budownictwa w sprawie szkolenia osób ubiegających się o uprawnienia do kierowania pojazdami w którym określone zostaną dokumenty ich wzory jakie będą obowiązywać po proponowanych zmianach. Bez aktualizacji tego rozporządzenia od 01.01.2027r. będziemy mieli chaos. Dokumenty będą dublować się wzajemnie np. cyfrowa karta kursanta i karta przeprowadzonych zajęć. Rozporządzenie można wydać dopiero po uchwaleniu przez Sejm poprawionej ustawy. Czyli na uchwalenie i opublikowanie nowego rozporządzenia nie będzie zbyt wiele czasu jeśli zmiany miały by wejść od początku roku.\\t\\n\\tArt. 1 pkt 6 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 6) Art. 28 po ust. 2 dodaje się ust. 2a. Ze względów wyżej wymienionych w pkt. 1 proponujemy wykreślić tą zmianę. Uważamy, że ośrodek szkolący tylko na kat. B i B1 też powinien dysponować placem manewrowym.\\t\\n\\tArt. 1 pkt 6 projektu ustawy\\tOgólnopolski Związek Pracodawców Transportu Drogowego\\tPrzesłany projekt jest realizacją wcześniej zapowiadanych zmian w szkoleniu i egzaminowaniu kierowców oraz procesie uzyskiwania uprawnień do kierowania pojazdami. Analiza projektu wskazuje jednak, że jest on daleki od oczekiwań branży transportu drogowego, ponieważ proponowane zmiany tylko w niewielkim stopniu odnoszą się do jakości szkolenia oraz oczekiwanego efektu w postaci niezbędnej wiedzy i umiejętności przyszłych kierowców, którzy już jako kierujący maja bezpośredni wpływ na bezpieczeństwo ruchu drogowego. Niektóre proponowane zmiany w naszej ocenie mogą pogarszać jakość szkolenia i tym samym tworzyć nowe ryzyka wynikające z uczestnictwa tych osób w ruchu drogowym. Zniesienie obowiązku posiadania placu manewrowego przez ośrodki szkolenia prowadzące kursy na ktg prawa jazdy B i B1 przyczyni się do rozwoju ośrodków bez jakiejkolwiek infrastruktury, a osoba szkolona bez podstawowych umiejętności będzie uczestniczyć w ruchu drogowym. Znając rynek szkoleń oceniamy, że szkolenie wstępne pozwalające nabyć umiejętności panowania nad pojazdem oraz wykonywania podstawowych manewrów jazda po prostej i po łuku do przodu lub cofając (manewry wymagane dyrektywą 2205/2025) przeniesie się na ulice o niskim natężeniu ruchu (gorzej w dużych miastach) oraz parkingi przy marketach skąd pojazdy z „L” są „wypychane” przez właścicieli terenów. To nie poprawi jakości szkolenia szczególności w początkowym okresie.\\t\\n\\tArt. 1 pkt 6 projektu ustawy\\tFundacja Zapobiegania Wypadkom Drogowym\\tW  kwestii usunięcia z programu szkolenia kandydatów na kierowców obowiązkowych zajęć na placu manewrowym stoimy na stanowisku, że o ile słuszna i uzasadniona jest rezygnacja z części egzaminu na prawo jazdy na placu manewrowym, o tyle „uwolnienie” i przeniesienie tych elementów szkolenia do ruchu drogowego i przestrzeni publicznej przyniesie liczne szkody, zagrożenia i konflikty. Wiele argumentów uzasadniających to stanowisko było w ostatnich tygodniach prezentowanych podczas spotkań przedstawicieli branży, w mediach, także w realizowanej przez nas audycji „Dyskusja na Ratuszowej”. Postulujemy zatem pozostawienie placu manewrowego jako obowiązkowego elementu szkolenia w OSK.  \\t\\n\\tArt. 1 pkt 6 projektu ustawy\\tZwiązek Pracodawców ‘Transport i Logistyka Polska”\\tAd. art. 1 pkt 6 projektu  Art. 1 pkt 6 projektu, wprowadza zmiany w art. 28 ust. 2a UoKP, kto re wyłączają wymóg posiadania placu manewrowego dla ośrodka szkolenia kierowców prowadzącego szkolenie w zakresie prawa jazdy kategorii B1 i B.  Nawiązując do uwag zgłoszonych do przepisu art. 1 pkt 2 projektu, proponujemy alternatywne rozwiązanie dotyczące wszystkich kategorii prawa jazdy, polegające na tym, z e od przedsiębiorcy wymaga się posiadania tytułu prawnego zapewniającego możliwość przeprowadzania części zajęć praktycznych w zakresie panowania nad pojazdem w miejscu (placu) zabezpieczonym, w trakcie przeprowadzania zajęć , przed dostępem oso b postronnych.  Dlatego też proponujemy w art. 28 UoKP:  uchylenie przepisu ust. 2 pkt 1 lit. c,  dodanie w ust. 2 pkt 1a w brzmieniu:   „1a. Dysponuje możliwością prowadzenia w ramach nauki jazdy, zajęć praktycznych na miejscu (placu), zabezpieczonym przed dostępem osób trzecich, w trakcie przeprowadzania tych zajęć.”.  Konsekwentnie proponujemy skreślenie propozycji nowego ust. 2a w art. 28 UoKP.\\t\\n\\tArt. 1 pkt 6 projektu ustawy\\tPolski Związek Szkoleniowy\\tW odniesieniu do art. 1 pkt 6 w naszej ocenie pomimo likwidacji na egzaminie państwowym zadań realizowanych na placu manewrowym to w przypadku prowadzenia ośrodka szkolenia kierowców plac ten powinien pozostać. Nie musza to być tak jak dotychczas zadania egzaminacyjne ale mimo wszystko powinien to być plac pozwalający na wykonanie podstawowych manewrów takich jak nauka ruszania, podstawowa nauka ruszania, hamowania, jazdy w przód i tył, obsługi pojazdu czy przygotowania do jazdy. Są to czynności niezbędne do nauczenia w bezpiecznych warunkach a nie w ruchu drogowym. Zatem każdy OSK powinien mieć taką przestrzeń przygotowaną dla kandydatów na kierowców rozpoczynających swoją przygodę z prawem jazdy. W naszej ocenie taki optymalny plac to około 10 m na 30 m czyli około 300 m2. Dzisiejszy podstawowy plac manewrowy dla OSK prowadzących szkolenie w zakresie prawa jazdy kategorii B to co najmniej 550 m2. Zatem 300 m2 to obniżenie wymagań dla OSK, ale bez likwidacji bezpiecznej przestrzeni szkoleniowej.  Plac manewrowy jest jedynym miejscem umożliwiającym bezpieczne wykonywanie przez kursanta pierwszych samodzielnych czynności związanych z prowadzeniem pojazdu.  \\fNa placu kursant nabywa podstawowe umiejętności obejmujące:  · ruszanie i zatrzymywanie pojazdu,  · płynne operowanie sprzęgłem i skrzynią biegów,  · utrzymanie właściwego toru jazdy,  · kontrolę pojazdu przy bardzo małych prędkościach,  · ocenę gabarytów pojazdu,  · jazdę z wykorzystaniem biegu wstecznego,  · wykonywanie podstawowych manewrów.  Dopiero po opanowaniu tych czynności możliwe jest bezpieczne rozpoczęcie szkolenia w ruchu drogowym.  Samodzielna jazda kursanta może odbywać się wyłącznie na placu manewrowym. Szczególną rolę plac manewrowy pełni w zakresie wykonywania przez kursanta samodzielnych manewrów.  Wyłącznie na placu możliwe jest stworzenie warunków, w których instruktor może czasowo opuścić pojazd, obserwować wykonywany manewr z zewnątrz oraz ocenić:  · sposób prowadzenia pojazdu,  · rzeczywisty tor jazdy,  · zachowanie odpowiednich odległości,  · prawidłowość obserwacji otoczenia,  · ocenę gabarytów pojazdu,  · samodzielność podejmowanych decyzji.  Takiej formy szkolenia nie można przenieść do ruchu drogowego.  Instruktor prowadzący szkolenie na drodze publicznej ma obowiązek sprawowania bezpośredniego nadzoru nad przebiegiem jazdy i zapewnienia bezpieczeństwa uczestnikom ruchu. Opuszczenie pojazdu oraz pozostawienie kursanta wykonującego samodzielnie manewry na drodze publicznej byłoby niedopuszczalne zarówno z punktu widzenia bezpieczeństwa, jak i odpowiedzialności instruktora.  Oznacza to, że po likwidacji obowiązku zapewnienia placu manewrowego kursanci zostaliby całkowicie pozbawieni możliwości wykonywania samodzielnych ćwiczeń pod nadzorem instruktora prowadzonym z zewnętrznej obserwacji.  Byłaby to istotna utrata jakości procesu szkolenia, której projekt nie identyfikuje ani nie rekompensuje.  \\fJeżeli jednak pozostaniemy przy braku wymagania placu manewrowego w przypadku OSK prowadzących szkolenie w zakresie prawa jazdy B to w art. 31 ust. 1 należy rozważyć podjęcie tych samych działań w stosunku do OSK spełniających dodatkowe wymagania. Jeżeli nie dal wszystkich OSK to opisany w pkt 7 plac powinien być wymagany przy OSK spełniającym dodatkowe wymagania w zakresie prawa jazdy kategorii B. Jednak trzeba pamiętać, że trzeba określić wielkość placu.  \\t\\n\\tArt. 1 pkt 6 projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t6) w art. 28 po ust. 2 dodaje się ust. 2a w brzmieniu:  „2a. Wymogu posiadania placu manewrowego, o którym mowa w ust. 2 pkt 1 lit. c, nie stosuje się do ośrodka szkolenia kierowców prowadzącego szkolenie w zakresie uprawnień kategorii B lub B1.”;  Jesteśmy za utrzymaniem placu manewrowego w szkoleniu i egzaminowaniu w obecnej formie. \\t\\n\\t Art. 1 pkt 7 projektu ustawy\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t Ad. art. 1 pkt 7 projektu  Art. 1 pkt 7 lit. a-c projektu wprowadza zmiany w art. 33 UoKP ustanawiające nowe wymagania wobec instruktorów prowadzących szkolenie. Nie negując potrzeby zmian, TLP nie znajduje merytorycznego uzasadnienia, opartego na przykładach dobrej praktyki z innych państw lub opartego na wynikach badań, do wprowadzania, po pierwsze wymogu co najmniej wykształcenia średniego lub średniego branżowego dla instruktorów i wykładowców, a po drugie, dla podwyższenia wymaganego czasu posiadania prawa jazdy odpowiedniej kategorii z 2 do 3 lat.  W ocenie TLP, miarą oceny kwalifikacji, w tym przygotowania zawodowego instruktorów i wykładowco w, powinno być doświadczenie oraz prezentowane umiejętności a nie formalny, niezwiązany z wykonywanymi zadaniami, poziom wykształcenia oraz okres posiadania kategorii prawa jazdy. Okresu posiadania prawa jazdy nie powinno się utożsamiać z okresem fizycznej jazdy pojazdem. W tym zakresie, w ocenie TLP, niezbędne są konkretne dane, wynikające z profesjonalnych analiz umiejętności i kwalifikacji osób, wykładających na kursach oraz oso b przygotowujących kursantów do bezpiecznej jazdy po drogach.  \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\fJednocześnie, TLP wskazuje na potrzebę odpowiedniego uregulowania kompetencji instruktorów prowadzących szkolenia w zakresie wyższych kategorii prawa jazdy, zgodnie ze wskazaną na wstępie propozycją nr 2.\\t\\n\\tArt. 1 pkt 7 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 7 – proponujemy warunek 5 lat posiadanego uprawnienia do kierowania wz. uprawnień instruktora oraz wprowadzenie obowiązku rocznego stażu zakończonego oceną warunkującą przedłużenie ważności uprawnień na kolejne 3 lata. Po tych dwóch okresach instruktor mógłby ubiegać się o Certyfikat instruktora nauki jazdy ważny przez kolejne 5 lat. Szczegółowe warunki realizacji powyższych wymagań należałoby określić w odpowiednim rozporządzeniu.   \\t\\n\\tArt. 1 pkt 7 projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t7) w art. 33: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\ta) w ust. 1 po pkt 1 dodaje się pkt 1a w brzmieniu: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„1a) posiada co najmniej wykształcenie średnie lub średnie branżowe;”, \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW związku z proponowanym przywróceniem wymogu posiadania co najmniej wykształcenia średniego lub średniego branżowego przez instruktora nauki jazdy, Krajowe Stowarzyszenie Egzaminatorów proponuje równoczesną zmianę art. 58 ust. 1 pkt 1 ustawy, poprzez przywrócenie wymogu posiadania wykształcenia wyższego przez osobę ubiegającą się o uprawnienia egzaminatora. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW naszej ocenie wymagania stawiane kandydatom na egzaminatorów powinny odpowiadać charakterowi, randze oraz zakresowi odpowiedzialności związanej z wykonywaniem tego zawodu. Egzaminator nie zajmuje się wyłącznie oceną techniki kierowania pojazdem. Do jego obowiązków należy dokonywanie obiektywnej oceny kwalifikacji osoby egzaminowanej, prawidłowe stosowanie przepisów prawa, właściwa kwalifikacja zachowań osoby egzaminowanej, podejmowanie decyzji mających bezpośredni wpływ na wynik egzaminu, a także jasne i merytoryczne uzasadnianie podejmowanych rozstrzygnięć. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\fWykonywanie zawodu egzaminatora wymaga zatem nie tylko odpowiedniej wiedzy z zakresu przepisów ruchu drogowego i techniki kierowania pojazdem, lecz również rozwiniętych kompetencji w zakresie logicznego formułowania wypowiedzi, argumentowania podejmowanych decyzji, interpretacji i stosowania przepisów oraz komunikowania osobie egzaminowanej przyczyn uzyskania określonego wyniku egzaminu. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tKompetencje te nabierają szczególnego znaczenia w przypadku składania przez osoby egzaminowane skarg dotyczących przebiegu egzaminu lub kwestionowania jego wyniku. Egzaminator powinien być wówczas zdolny do precyzyjnego odtworzenia przebiegu zdarzenia, właściwej oceny zachowania osoby egzaminowanej oraz przedstawienia spójnego i merytorycznego uzasadnienia podjętej decyzji, znajdującego oparcie w obowiązujących przepisach. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tZniesienie wymogu posiadania wykształcenia wyższego przez kandydatów na egzaminatorów obniżyło formalny próg dostępu do zawodu, mimo że zakres odpowiedzialności egzaminatora oraz wymagania związane z prawidłowym wykonywaniem jego obowiązków nie uległy odpowiedniemu zmniejszeniu. Doświadczenia praktyczne środowiska egzaminatorów wskazują natomiast, że samo spełnienie pozostałych wymagań formalnych nie zawsze gwarantuje odpowiedni poziom kompetencji niezbędnych do właściwego wykonywania tego zawodu, w szczególności w zakresie komunikacji, argumentacji oraz prawidłowego uzasadniania dokonywanych ocen. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNależy również zwrócić uwagę na potrzebę zachowania właściwych proporcji pomiędzy wymaganiami stawianymi instruktorom, a wymaganiami dotyczącymi egzaminatorów. Skoro projektodawca dostrzega potrzebę podwyższenia wymagań dotyczących wykształcenia osób odpowiedzialnych za przygotowanie kandydatów do kierowania pojazdami, tym bardziej uzasadnione jest zapewnienie odpowiednio wysokich wymagań wobec osób, które następnie dokonują niezależnej i końcowej oceny kwalifikacji tych kandydatów w ramach egzaminu państwowego. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tPrzywrócenie wymogu posiadania wykształcenia wyższego stanowiłoby również element wzmacniający profesjonalny charakter zawodu egzaminatora oraz sprzyjałoby utrzymaniu \\fodpowiedniego poziomu merytorycznego osób wykonujących zadania o istotnym znaczeniu dla bezpieczeństwa ruchu drogowego. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW ocenie Krajowego Stowarzyszenia Egzaminatorów podwyższenie wymagań dotyczących wykształcenia kandydatów na egzaminatorów powinno stanowić jeden z elementów działań zmierzających do podnoszenia jakości systemu egzaminowania, profesjonalizacji zawodu egzaminatora oraz wzmacniania społecznego zaufania do egzaminów państwowych na prawo jazdy. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProponowane brzmienie art. 58 ust. 1 pkt 1: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„1) posiada wykształcenie wyższe; dotyczy kandydatów na egzaminatorów po dniu wejścia w życie ustawy ”.\\t\\n\\tArt. 1 pkt 11 projektu ustawy w zakresie art. 45 ust. 2 pkt 1a, 3a i 3b ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy zdefiniować pojęcie „wielokrotnie” oraz wprowadzić proporcjonalny mechanizm sankcyjny, rozróżniający naruszenia zawinione przez OSK od naruszeń wynikających z awarii systemu centralnego, aplikacji, braku łączności lub nieprawidłowości po stronie dostawcy rozwiązań technicznych. Sankcje powinny być poprzedzone możliwością usunięcia uchybień, o ile nie doszło do rażącego naruszenia bezpieczeństwa lub fałszowania dokumentacji. Należy rozważyć korektę brzmienia proponowanego punktu 1a tj. wielokrotne niezrealizowanie obowiązków, o których mowa w art. 23f pkt 2-4 oraz uzupełnienie w obowiązujących przepisach art. 45 ust. 2 pkt 1 lit. c w brzmieniu „pojazdami niespełniającymi wymagań, o których mowa w art. 23c ust. 5, 23f, 24 lub nieposiadającymi aktualnego okresowego badania technicznego”  Uzasadnienie: Projekt przewiduje nowe przesłanki wykreślenia z rejestru/ewidencji związane z niewykonywaniem obowiązków cyfrowych i ochroną danych, ale nie precyzuje progu naruszeń. Przy tak złożonym systemie teleinformatycznym część błędów może mieć charakter techniczny i niezależny od OSK. Brak gradacji sankcji może prowadzić do nadmiernie represyjnej i niejednolitej praktyki organów nadzoru.  \\fPropozycja o charakterze technicznym, uzupełniona o kwestię obowiązku szkolenia pojazdami bezpiecznymi i sprawnymi technicznie tj. posiadającymi aktualne okresowe badania techniczne (patrz. orzecznictwo)\\t\\n\\tArt. 1 pkt 11 lit. a-b projektu ustawy\\tZwiązek Pracodawców „Transport i Logistyka Polska\\tAd. art. 1 pkt 11 lit. a-b projektu  Odnosząc się do proponowanych zmian w zakresie art. 45 ust. 2 pkt 1a, 3a i 3b UoKP, zastrzeżenia TLP dotyczą braku precyzji w zakresie przesłanek do podejmowanych w trybie nadzoru decyzji. Przepisy nie wskazują ile konkretnie przypadków obejmuje wielokrotne nierealizowanie obowiązków, czy naruszanie warunków prowadzenia działalności przez ośrodek szkolenia kierowców. Jest to szczególnie istotne, gdyż wielokrotność ta jest elementem, którego zaistnienie skutkuje skreśleniem z listy OSK przez starostę i brakiem możliwości dalszego szkolenia kierowców.\\t\\n\\tArt. 1 pkt 12 projektu ustawy\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tW art. 46 ust. 1 pkt 4 lit c ustawy o kierujących pojazdami należy rozważyć uzupełnienie brzmienia tej regulacji poprzez zmianę np.: „ potwierdzenie nieprawdy w dokumentacji dotyczącej szkolenia w tym cyfrowej karcie kursanta”. Należy rozważyć wprowadzenie po literze c kolejną literę d w brzmieniu np. „wielokrotne niezrealizowanie obowiązków o których mowa w art. 23d ust 6 lub 7 w wskazanych terminach. Alternatywnie przepis ten można uwzględnić w stosunku do przedsiębiorcy prowadzącego OSK Uzasadnienie: W obecnym kształcie projektu nie przewidziana została odpowiedzialność instruktora w przypadku niewypełniania obowiązków, dotyczących wprowadzania danych i informacji do cyfrowej karty kursanta\\t\\n\\tArt. 1 pkt 13  projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPropozycja zmiany: dot. art. 50 ust 2 pkt 9 w art. 50 w ust. 2 w pkt 8 kropkę zastępuje się średnikiem i dodaje się pkt 9 w brzmieniu: „9) która powtórnie w tym samym dniu przystępuje do części praktycznej egzaminu państwowego, z którego uzyskała wynik negatywny.”;  - Proponuje się wykreślenie pkt 13  w proponowanym brzmieniu.  \\fUzasadnienie:  Jeżeli wojewódzki ośrodek ruchu drogowego (WORD) dysponuje wolnymi terminami egzaminów praktycznych albo zwolniły się miejsca wskutek rezygnacji osób, którym wcześniej wyznaczono termin egzaminu na dany dzień, trudno znaleźć uzasadnienie dla odmowy przystąpienia do ponownego egzaminu praktycznego tego samego dnia przez osobę, która uzyskała wynik negatywny i wyraża taką wolę.  Sam fakt uzyskania negatywnego wyniku egzaminu nie stanowi jednoznacznej i obiektywnej przesłanki uzasadniającej zakaz ponownego przystąpienia do egzaminu w tym samym dniu. Jeżeli istnieją warunki organizacyjne umożliwiające przeprowadzenie takiego egzaminu, a kandydat mógłby zostać zapisany na egzamin w dniu następnym, brak jest racjonalnych podstaw do wykluczenia możliwości jego przeprowadzenia jeszcze tego samego dnia.  Należy również zauważyć, że w sytuacji, gdy wolny termin egzaminu w danym dniu nie zostanie wykorzystany, skierowanie takiej osoby na egzamin w innym terminie powoduje zajęcie miejsca, z którego mogłaby skorzystać inna osoba oczekująca na egzamin. W konsekwencji dochodzi do sztucznego wydłużania czasu oczekiwania na egzamin praktyczny oraz mniej efektywnego wykorzystania dostępnych terminów egzaminacyjnych, mimo że istniała możliwość przeprowadzenia egzaminu wcześniej.  W związku z powyższym proponuje się pozostawienie tej kwestii do rozstrzygnięcia wojewódzkiemu ośrodkowi ruchu drogowego, jako organizatorowi egzaminu, oraz kandydatowi na kierowcę, który mógłby zdecydować o skorzystaniu lub rezygnacji z możliwości ponownego przystąpienia do egzaminu praktycznego tego samego dnia, o ile pozwalałyby na to warunki organizacyjne. Rozwiązanie takie przyczyniłoby się zarówno do bardziej racjonalnego wykorzystania dostępnych terminów egzaminów, jak i do ograniczenia sztucznego wydłużania kolejek osób oczekujących na wyznaczenie terminu egzaminu z powodów proceduralnych.\\t\\n\\tArt. 1 pkt 13  projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 13) w Art. 50. Ograniczono możliwość powtórnego zdawania egzaminu w tym samym dniu. Taka zmiana niewątpliwie ułatwi planowanie pracy w WORD, pozwoli lepiej wykorzystać czas na egzaminowanie, skróci kolejkę. Ale dla kursantów będzie tylko dodatkowym \\fkłopotem. Zamiast dojechać do WORD jeden raz będą musieli to zrobić kilka razy. Zamiast jednego dnia urlopu z pracy będą musieli wykorzystać kilka dni. Kursant następnego dnia nie będzie lepiej jeździł jeśli przed kolejnym egzaminem nie wróci do ośrodka szkolenia na doszkolenie. Proponowana regulacja takiego obowiązku nie nakłada.\\t\\n\\tArt. 1 pkt 13 projektu ustawy\\tPolski Związek Szkoleniowy\\t11) W odniesieniu do art. 1 pkt 13 proponujemy następujące brzmienie przepisu art. 50 ust 2 pkt 9:  „9) która przystępowała w tym samym dniu do części praktycznej egzaminu państwowego w zakresie danej kategorii prawa jazdy, z którego uzyskała wynik negatywny.”;  Zaproponowane w projekcie brzmienie przepisu jest nielogiczne ponieważ z przepisu wynika, że osoba przystępuje do egzaminu, a tak naprawdę nie powinna być na niego w ogóle zapisana. Zaproponowane brzmienie zakazuje zapisania na kolejny egzamin takiej osoby w danym dniu, a nie egzaminowania już osoby zapisanej.\\t\\n\\tArt. 1 pkt 13  projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 13 – proponujemy wprowadzenie okresu co najmniej 7 dni pomiędzy egzaminami. Ta regulacja powinna także dotyczyć egzaminów teoretycznych. Po trzech kolejnych niepowodzeniach ww. okres powinien być przedłużony do miesiąca. \\t\\n\\tArt. 1 pkt 13  projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t13) w art. 50 w ust. 2 w pkt 8 kropkę zastępuje się średnikiem i dodaje się pkt 9 w brzmieniu:  „9) która powtórnie w tym samym dniu przystępuje do części praktycznej egzaminu państwowego, z którego uzyskała wynik negatywny.”; \\t\\t Naszym zdaniem powinniśmy zostawić tą kwestie dyrekcji ośrodka egzaminowania. Są ośrodki gdzie odległość osób przystępujących do egzaminu wynosi ponad 100 km, często osoby biorą cały dzień urlopu lub wolnego. W okresach   gdzie nie ma dużo chętnych ( np. okres zimowy) zapełnienie pełnego grafiku egzaminatorowi w danym dniu  jest bardzo trudne). Cześć wyników negatywnych jest rezultatem stresu, a nie złego przygotowania. Wielokrotnie  zdarza się, iż klienci podchodzą  drugi raz  do egzaminu  w tym samym dniu uzyskujac wynik pozytywny.  Dlatego proponujemy aby zostawić tą kwestie dyrektorom tak jak do tej pory.  Proponujemy zmianę zapisu na uniemożliwiający  zdawanie egzaminu więcej, niż  dwa razy w tym samym dniu.   \\t\\n\\t Art. 1 pkt 13  projektu ustawy\\tZwiązek Pracodawców \\\"Transport i Logistyka Polska\\\"\\t Ad. art. 1 pkt 13 projektu  Proponujemy modyfikację brzmienia art. 50 ust. 2 pkt 9 UoKP na następujące:  „9) która uzyskała w tym samym dniu negatywny wynik z części praktycznej egzaminu państwowego.”.  W ocenie TLP, jest to rozwiązanie wprowadzające jednoznacznie zasadę, iż w tym samym dniu nie można przystępować do więcej niż jednego egzaminu i realizujące w pełni cel projektowanego przepisu.\\t\\n\\tArt. 1 pkt 14 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 14) d) Usuwa z egzaminu w WORD zadania na placu manewrowym dla kat. B, B1. Nawet największa sprawność w realizacji zadań na placu manewrowym nie gwarantuje, że kursant w rzeczywistym ruchu drogowym nie będzie popełniał błędów. Czas poświęcony na opanowanie zadań na placu manewrowym automatycznie ogranicza czas jaki instruktor mógłby poświęcić na szkolenie w rzeczywistych warunkach ruchu drogowego. Jeśli celem egzaminu w WORD jest sprawdzenie czy kursant potrafi kierować w rzeczywistym ruchu drogowym to rezygnacja z wykonywania zadań w sztucznych warunkach na placu może być uzasadniona.\\t\\n\\tArt. 1 pkt 14 projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t14)  w art. 51    d) w ust. 3 w pkt 1: – w lit. a skreśla się wyrazy „B1 i B”, \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: Likwidacja placu manewrowego w zakresie kat B prawa jazdy pociągnie za sobą wiele negatywnych konsekwencji. Cena egzaminu będzie musiała wzrosnąć ze względu na zmniejszenie ilości egzaminów praktycznych. Likwidacja placu manewrowego przy jednoczesnym pozostawieniu obecnej tabeli zadań egzaminacyjnych spowoduje wydłużenie czasu realizacji egzaminów praktycznych. Automatycznie musi wzrosnąć koszt działalności WORD-ów, niebagatelnym kosztem będzie również zagospodarowanie pozostałej infrastruktury, część WORD-ów będzie nadal ponosić koszty dzierżawy, utrzymania bezużytecznych terenów, podatków. Przykładowo w MORD Kraków OT Oświęcim  zlikwidują egzaminy na kategorie motocyklowe i po zakończeniu umowy najmu oddadzą \\fwyremontowany ogromnym nakładem finansowym plac albo będą każdego roku przez pół roku braku egzaminów na kategorie motocyklowe utrzymywać pusty plac. Wiele ośrodków egzaminowania w Polsce przygotowując się do kategorii C+E  na ciągniku siodłowym z naczepą poniosło wielomilionowe koszty związane z modernizacja placu np. WORD Suwałki. Nie zawsze warunki umożliwiają zagospodarowanie placu na cele inne, niż egzaminy na          kat. B. Istotny będzie  również spadek dochodów z najmu placu dla ośrodków szkolenia kierowców. Puki co proponowane zmiany i tak zmuszą WORD-y do kosztownego utrzymywania placu manewrowego o wymiarach przewidzianych dla kat. B ze względu na prowadzenie egzaminów na kat AM czterokołowcem lekkim lub pojazdem trójkołowym. Należy jednoznacznie wskazać, iż efektem proponowanych zmian będzie zwiększenie nakładu pracy poszczególnych egzaminatorów. Na przykładzie dużych miast już teraz praktycznie niemożliwa jest realizacja zaplanowanych 9 egzaminów w przypadku konieczności realizacji pełnego programu egzaminu tj. plac manewrowy + ruch drogowy. Likwidacja placu nie skróci wyraźnie czasu egzaminów. Przy odpowiedniej organizacji placów manewrowych realizacja dwóch proponowanych do usunięcia zadań trwała bardzo krótko.  Przypadki te wiążą się z koniecznością przeprowadzania egzaminów przez egzaminatorów nadzorujących lub przeprowadzeniem przez innych egzaminatorów 10 egzaminów w ciągu dnia pracy. Nie wyobrażamy sobie sytuacji po wprowadzeniu proponowanych  zmian, gdy będzie absencja egzaminatora. Teraz, gdy osoba uzyska wynik negatywny na placu manewrowym jesteśmy w stanie szybko przydzielić wolnego egzaminatora do osoby, która była zaplanowana na egzaminatora, który w tym dniu nie wstawił się do pracy. Po zmianach będzie to niemożliwe każdy egzaminator gdy wyjedzie od razu do ruchu wróci po 20 -30 minutach i nie będzie w stanie wziąć kolejnej osoby. Muszą być rezerwowi egzaminatorzy. Chcąc zapewnić obecny poziom obsługi klienta wskazane będzie istotne zmniejszenie ilości planowanych egzaminów praktycznych. Mając na uwadze konieczność realizacji wszystkich zaplanowanych egzaminów tj. niedoprowadzanie do sytuacji, w której klient przyjedzie do WORD-u i dowie się, że egzamin jest odwołany niezbędnym będzie ograniczenie ilości planowanych egzaminów praktycznych na poszczególnych egzaminatorów. Konieczna jest również nowelizacja przepisów dotyczących organizacji egzaminów, a mianowicie jednoznaczne doprecyzowanie, że maksymalny czas spóźnienia rozpoczęcia egzaminu dotyczy osób egzaminowanych, a nie egzaminatora; Zmniejszenie ilości planowanych egzaminów znacznie wydłuży terminy oczekiwania na egzaminy praktyczne. W tym momencie niektóre WORD-y mają ogromny problem z naborem \\fnowych pracowników, ogłoszenia o prace pozostają bez odpowiedzi, starsi egzaminatorzy przechodzą na emerytury, a nie ma kim ich zastąpić. Już na ten moment czas oczekiwania na egzaminy w wielu WORD-ach jest zbyt długi.  Proponujemy aby pozostawić plac manewrowy, ale chcąc zapewnić lepsze warunki dla osób egzaminowanych, należałoby znowelizować zasady przez np. dodanie korekty na pasie ruchu, dowolność ustawienia  lusterka, próbne ruszenie, zapoznanie się z samochodem WORD, przed rozpoczęciem drugiego zadania tj. jazdy pasem ruchu.\\t\\n\\tArt. 1 pkt 14 lit. d projektu ustawy\\tMałopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców \\tUwaga 1. Objęcie wyłączeniem zadań na placu manewrowym także egzaminu w zakresie kategorii AM przeprowadzanego czterokołowcem lekkim lub motorowerem trójkołowym (art. 1 pkt 14 lit. d projektu; art. 51 ust. 3 pkt 1 lit. a ustawy) Treść uwagi: Popierając wyłączenie kategorii B i B1 z zakresu zadań realizowanych na placu manewrowym, postulujemy rozszerzenie tego wyłączenia również na egzamin państwowy w zakresie kategorii AM przeprowadzany czterokołowcem lekkim lub motorowerem trójkołowym, przy jednoczesnym pozostawieniu bez zmian zadań na placu manewrowym dla egzaminu kategorii AM przeprowadzanego motorowerem dwukołowym oraz wymogów infrastrukturalnych ośrodków szkolenia kierowców w zakresie tej kategorii. Problem: Projektowany art. 1 pkt 14 lit. d skreśla w art. 51 ust. 3 pkt 1 lit. a wyrazy „B1 i B”, pozostawiając w zakresie zadań na placu manewrowym kategorie AM, A1, A2 i A. Tymczasem zgodnie z § 23 ust. 3 rozporządzenia Ministra Infrastruktury z dnia 24 listopada 2023 r. w sprawie egzaminowania osób ubiegających się o uprawnienia do kierowania pojazdami (Dz. U. poz. 2659) osoba egzaminowana w zakresie kategorii AM czterokołowcem lekkim lub motorowerem trójkołowym wykonuje na placu manewrowym zadania określone dla kategorii B1 w sposób określony dla tej kategorii, wobec czego po usunięciu zadań placowych dla kategorii B1 utrzymanie kategorii AM w art. 51 ust. 3 pkt 1 lit. a prowadzi do sytuacji, w której zadania egzaminacyjne dla obu tych wariantów egzaminu odsyłają do zadań, które przestaną istnieć. Czterokołowiec lekki jest przy tym pojazdem konstrukcyjnie i funkcjonalnie zbliżonym do samochodu osobowego, a zadania wykonywane na placu manewrowym zarówno tym pojazdem, jak i motorowerem trójkołowym, odpowiadają zadaniom przewidzianym dotychczas dla kategorii B1, wobec czego wszystkie argumenty przemawiające za przeniesieniem oceny umiejętności do rzeczywistego ruchu drogowego, przywołane w uzasadnieniu projektu w odniesieniu do kategorii B i B1, zachowują pełną aktualność także w odniesieniu do tych wariantów egzaminu. Pozostawienie zadań na placu manewrowym \\fwyłącznie dla tych statystycznie marginalnych wariantów spowoduje ponadto, że wojewódzkie ośrodki ruchu drogowego będą zobowiązane w dalszym ciągu utrzymywać stanowisko przystosowane do wykonywania tych zadań, mimo że infrastruktura ta przestanie być wykorzystywana na potrzeby egzaminów kategorii B i B1, co pozostaje w sprzeczności z deklarowanym w Ocenie Skutków Regulacji celem efektywniejszego wykorzystania zasobów tych ośrodków. Podkreślamy zarazem, że w zakresie szkolenia wymóg posiadania placu manewrowego przez ośrodki prowadzące szkolenie w kategorii AM powinien pozostać niezmieniony, ponieważ plac pozostaje niezbędny do bezpiecznej nauki jazdy jednośladem. Propozycja zmiany zapisu: Proponujemy, aby art. 1 pkt 14 lit. d tiret pierwsze projektu, dotyczące art. 51 ust. 3 pkt 1 lit. a ustawy, otrzymało brzmienie: „– lit. a otrzymuje brzmienie: «a) sprawdzenie podstawowych umiejętności w zakresie panowania nad pojazdem odpowiednim dla uprawnień prawa jazdy kategorii A1, A2 i A, a w zakresie kategorii AM – wyłącznie w przypadku egzaminu przeprowadzanego motorowerem dwukołowym,»” \\t\\n\\t Art. 1 pkt 14 lit. c projektu ustawy\\t Małopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców \\tUwaga 5. Przeniesienie maksymalnej liczby pytań egzaminacyjnych na poziom rozporządzenia oraz wprowadzenie kryteriów psychometrycznych i kwartalnego monitoringu pytań (art. 1 pkt 14 lit. c projektu; art. 51 ust. 2c ustawy) Treść uwagi: Postulujemy, aby maksymalnej liczby pytań egzaminacyjnych nie określać w ustawie, lecz przenieść ją, wraz z kryteriami psychometrycznymi dopuszczenia pytania do stosowania oraz trybem kwartalnego monitoringu jakości pytań obejmującym automatyczne zawieszanie pytań zdegradowanych, do rozporządzenia wydanego na podstawie delegacji ustawowej. Problem: Projektowany art. 1 pkt 14 lit. c zastępuje w art. 51 ust. 2c liczbę „4000” liczbą „1500”, wskutek czego przepis nadal określa w ustawie maksymalną liczbę pytań egzaminacyjnych. Nie kwestionujemy docelowego rozmiaru bazy, wskazujemy natomiast, że nawet ujęta jako pułap maksymalny liczba pytań jest parametrem operacyjnym produktu cyfrowego, którym baza pytań się staje, nie zaś rozwiązaniem ustrojowym wymagającym rangi ustawowej, a jej pozostawienie w ustawie oznacza, że każde podniesienie tego pułapu będzie \\fwymagało nowelizacji ustawy. Ograniczenie to okaże się szczególnie dotkliwe w razie przewidywanego rozwoju egzaminu teoretycznego, w tym ewentualnego włączenia do niego zadań badających percepcję zagrożeń, które mogą wymagać zwiększenia liczby pytań ponad przyjęty pułap. Jednocześnie projekt nie określa żadnych kryteriów jakościowych warunkujących dopuszczenie pytania do stosowania ani mechanizmu ciągłego monitorowania pytań aktywnych, przez co walidacja przewidziana w projektowanym art. 57aa ust. 2 pkt 4 pozostaje deklaratywna, a wobec pełnej jawności bazy pytań przewidzianej w art. 51 ust. 2b, którą w pełni popieramy, kluczowego znaczenia nabiera systematyczne wycofywanie pytań zdegradowanych – takich, które wskutek pamięciowego opanowania przez osoby egzaminowane utraciły wartość różnicującą. Propozycja zmiany zapisu: Proponujemy, aby art. 1 pkt 14 lit. c projektu otrzymał brzmienie: „c) ust. 2c otrzymuje brzmienie: «2c. Maksymalną liczbę pytań egzaminacyjnych stosowanych na egzaminie państwowym określają przepisy wydane na podstawie ust. 2d.»” oraz aby po lit. c dodać lit. ca w brzmieniu: „ca) po ust. 2c dodaje się ust. 2d w brzmieniu: «2d. Minister właściwy do spraw transportu określi, w drodze rozporządzenia, maksymalną liczbę pytań egzaminacyjnych stosowanych na egzaminie państwowym, kryteria psychometryczne warunkujące dopuszczenie pytania egzaminacyjnego do stosowania oraz tryb okresowego, przeprowadzanego nie rzadziej niż raz na kwartał, monitorowania jakości stosowanych pytań egzaminacyjnych, obejmującego automatyczne zawieszanie stosowania pytań, które utraciły wartość różnicującą, mając na względzie konieczność zapewnienia rzetelnej oceny kompetencji osób egzaminowanych oraz bieżącego dostosowywania bazy pytań do zmian stanu prawnego, postępu technologicznego w motoryzacji i danych o wypadkach drogowych.»” \\t\\n\\tArt. 1 pkt 14 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków \\fRuchu Drogowego\\t\\fW art. 1 pkt 14  w podpunkcie 3 – proponujemy skreślić ust. 3c. \\t\\n\\t Art. 1 pkt 14 projektu ustawy\\t Związek Pracodawców „Transport i Logistyka Polska”\\t Ad, art. 1 pkt 14 projektu  - Przepis art. 1 pkt 14 lit. c projektu zmienia przepis art. 51 ust. 2c, regulujący liczbę pytań egzaminacyjnych z 4000 na 1000. Nie odnosząc się do kwestii merytorycznej (zmniejszenia liczby pytań), uważamy że takie kwestie nie powinny być regulowane w drodze ustawy. Tego typu przepisy wydają się być sprzeczne z zasadą minimalizmu legislacyjnego, zasadą proporcjonalności (pomocniczości) oraz ze zdrowym rozsądkiem. Jeżeli kiedykolwiek trzeba będzie podjąć decyzję o zwiększeniu liczby pytań o nowe obszary (co wymagałoby dodania na przykład kolejnych 10 pytań), to w tej sprawie będzie potrzebna decyzja Sejmu, Senatu i Prezydenta RP. Czy naprawdę jest to poważne rozwiązanie? Dlatego proponujemy uchylenie przepisu art. 51 ust. 2c UoKP.  - Przepis art. 1 pkt 14 lit. d projektu wyłącza obowiązek przeprowadzania części egzaminu praktycznego w zakresie kategorii B1 i B na placu manewrowym. W odniesieniu do tego rozwiązania swoje uwagi wskazaliśmy wyżej w pkt 5 postulatu TLP, dotyczącego zmian w egzaminie praktycznym na prawo jazdy kategorii C, C+E, D, D+E. Podtrzymujemy sformułowane tamże propozycje odpowiednich zmian w art. 51 UoKP.  - Przepis art. 1 pkt 14 lit. e projektu wprowadza w art. 51 UoKP nowe przepisy ust. 3a-3c, regulujące zasady uznawania wyników części egzaminu praktycznego przez okres 24 miesięcy. Nie negując potrzeby podobnej regulacji pragniemy zwrócić uwagę, na fakt iż umiejętności praktyczne nabywane są w trzech etapach (klasyczny model przyswajania umiejętności motorycznych Fittsa i Posnera): fazy poznawczej/kognitywnej (kursant świadomie myśli o każdym ruchu), fazy asocjacyjnej (ruchy kursanta zaczynają łączyć się w płynniejsze sekwencje) i fazy autonomicznej (umiejętność przechodzi do głębokiej pamięci proceduralnej - jest automatyczna. 20   Osoba, która jedynie ukończyła standardowe szkolenie, zazwyczaj dociera zaledwie do późnej fazy poznawczej lub wczesnej asocjacyjnej. Ponieważ jej mózg wciąż musi traktować prowadzenie pojazdu, jako ciąg świadomych instrukcji (wiedza deklaratywna), umiejętność ta nie zdążyła się utrwalić, jako odporny na upływ czasu nawyk ruchowy. To prowadzi do szybkiej degradacji nieutrwalonej umiejętności. Zjawisko to w literaturze naukowej nosi nazwę zaniku umiejętności (ang. skill decay), jeśli osoba po szkoleniu nie podejmuje praktyki.  \\fI tak po kilku tygodniach następuje szybka utrata płynności motorycznej (tzw. \\\"drewniane ruchy\\\"), utrata zdolności do synchronizacji kilku czynności naraz (np. obserwacja lusterek i operowanie pedałami), etc.  Po 3–6 miesiącach, ślady wczesnej pamięci proceduralnej ulegają znacznemu zatarciu. Pojawiają się rażące błędy (np. gaśnięcie silnika, problemy z oceną odległości, szarpanie). Poziom stresu poznawczego przy próbie wykonania zadania jest zbliżony do tego z początków kursu.  Powyżej roku (i dalej) następuje niemal całkowity regres do stanu początkowego w zakresie tzw. pamięci mięśniowej. Osoba pamięta jedynie ułamki wiedzy teoretycznej (wie, do czego służy kierownica i hamulec), ale w ujęciu neurologicznym powraca do punktu wyjścia. Samodzielne, bezpieczne prowadzenie pojazdu bez jazd doszkalających staje się wówczas niemożliwe.  Dlatego też proponujemy weryfikację wskazanego okresu z uwzględnieniem współczesnych badań w tym obszarze.\\t\\n\\tArt. 1 pkt 14 lit. e projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t14)  w art. 51    e) po ust. 3 dodaje się ust. 3a–3c w brzmieniu:  3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego przystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach wydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu lub zdrowiu uczestników ruchu drogowego – w takim przypadku osoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w pełnym zakresie.”,  \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tKrajowe Stowarzyszenie Egzaminatorów opowiada się za pozostawieniem obowiązku wykonywania zadań na placu manewrowym przy każdym podejściu do części praktycznej egzaminu państwowego. Plac manewrowy stanowi bezpieczne i odizolowane od ruchu drogowego środowisko, w którym weryfikowane są podstawowe umiejętności techniczne osoby egzaminowanej, w tym właściwe operowanie pojazdem oraz wyczucie jego gabarytów. \\fMa to szczególne znaczenie w przypadku kategorii motocyklowych oraz kategorii dotyczących pojazdów ciężkich. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tJednocześnie zdecydowanie negatywnie oceniamy rozwiązanie zaproponowane w ust. 3c, zgodnie z którym osoba, która podczas kolejnego podejścia do egzaminu w ruchu drogowym spowoduje bezpośrednie zagrożenie życia lub zdrowia uczestników ruchu drogowego, przy następnym podejściu będzie zobowiązana do ponownego przystąpienia do części praktycznej egzaminu w pełnym zakresie. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNie znajdujemy merytorycznego uzasadnienia dla uzależnienia obowiązku ponownego wykonywania zadań na placu manewrowym od zachowania osoby egzaminowanej w ruchu drogowym. Spowodowanie bezpośredniego zagrożenia w ruchu drogowym nie oznacza, że osoba egzaminowana utraciła lub nie posiada umiejętności technicznych, które zostały wcześniej pozytywnie zweryfikowane na placu manewrowym. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProponowany przepis może ponadto prowadzić do niepotrzebnych sporów pomiędzy osobą egzaminowaną, a egzaminatorem dotyczących kwalifikacji konkretnego zachowania jako bezpośredniego zagrożenia życia lub zdrowia. Dla osoby egzaminowanej taka kwalifikacja będzie bowiem powodowała dodatkową konsekwencję w postaci konieczności powtarzania całego egzaminu, w tym ponownego wykonywania zadań na placu manewrowym. Problem ten może być szczególnie widoczny w przypadku kategorii motocyklowych oraz kategorii dotyczących pojazdów ciężkich, gdzie część egzaminu przeprowadzana na placu manewrowym jest bardziej rozbudowana. Może to w konsekwencji powodować wzrost liczby skarg i odwołań od przebiegu oraz wyniku egzaminu. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDodatkowym argumentem przeciw proponowanemu rozwiązaniu jest kwestia logistyki przeprowadzania egzaminów praktycznych zarówno, jeżeli chodzi o ich planowanie jaki i fizyczną realizację. Przykładowo w zakresie kat. BE, CE, DE oraz T prawa jazdy kto będzie odpowiadał za sprzęganie pojazdu silnikowego z przyczepą/naczepą w przypadku kandydata na kierowcę podchodzącego do egzaminu tylko w części realizowanej w ruchu drogowym? Proponowana zmiana może wygenerować dodatkowe koszty zatrudnienia pracowników do obsługi sprzęgania. Osoby egzaminowane mogą również kwestionować koszt tego „skróconego” egzaminu. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\fZ posiadanych przez Krajowe Stowarzyszenie Egzaminatorów informacji wynika ponadto, że w przypadku kategorii motocyklowych oraz kategorii dotyczących pojazdów ciężkich liczba egzaminów zakończonych wynikiem negatywnym z powodu bezpośredniego zagrożenia życia lub zdrowia uczestników ruchu drogowego jest niewielka. Tym samym projektowana regulacja odnosi się do sytuacji występujących stosunkowo rzadko, jednocześnie wprowadzając dodatkowe komplikacje w zakresie kwalifikowania wyniku egzaminu. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNależy również uwzględnić projektowaną zmianę art. 52 ust. 2, zgodnie z którą egzaminator może przerwać egzamin, jeżeli zachowanie osoby egzaminowanej może zagrażać życiu lub zdrowiu uczestników ruchu drogowego. Przy tak skonstruowanym przepisie egzamin może zostać zakończony jeszcze przed wystąpieniem bezpośredniego zagrożenia, co dodatkowo ogranicza praktyczne zastosowanie projektowanego ust. 3c. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW naszej ocenie tworzenie dodatkowej regulacji odnoszącej się do nielicznych przypadków, która jednocześnie może powodować spory interpretacyjne i zwiększać liczbę skarg na decyzje egzaminatorów, jest niecelowe. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW związku z powyższym Krajowe Stowarzyszenie Egzaminatorów proponuje usunięcie ust. 3c z projektu.\\t\\n\\tArt. 1 pkt 14 projektu ustawy\\tZrzeszenie Międzynarodo-wych Przewoźników Drogowych w Polsce \\tW pierwszej kolejności ZMPD pozytywnie ocenia zmianę przewidzianą w art. 1 pkt 14 lit. e projektu ustawy, polegającą na zachowaniu przez okres 24 miesięcy pozytywnego wyniku części praktycznej egzaminu państwowego uzyskanego na placu manewrowym. Brak konieczności ponownego wykonywania zadań, które zostały już zaliczone, może stanowić istotne ułatwienie dla osób ubiegających się o uzyskanie prawa jazdy kategorii C, C+E, D lub D+E, a tym samym przyczynić się do usprawnienia procesu uzyskiwania uprawnień przez przyszłych kierowców zawodowych. Przyjęty okres 24 miesięcy wydaje się przy tym racjonalnym kompromisem pomiędzy interesem osoby egzaminowanej a potrzebą zachowania aktualności sprawdzonych wcześniej umiejętności. Wątpliwości budzi jednak propozycja pobierania opłaty w tej samej wysokości również w przypadku, gdy osoba egzaminowana, korzystając z zachowanego wyniku uzyskanego na placu manewrowym, przystępuje wyłącznie do części praktycznej egzaminu przeprowadzanej w ruchu drogowym. W ocenie Zrzeszenia wysokość opłaty powinna \\fpozostawać w odpowiedniej relacji do rzeczywistego zakresu egzaminu oraz kosztów jego przeprowadzenia. Skoro egzamin w takim przypadku nie obejmuje części realizowanej na placu manewrowym, zasadne jest ustalenie odrębnej, odpowiednio niższej opłaty. Nawet umiarkowane obniżenie kosztu kolejnego podejścia (o 10 lub 20%) miałoby znaczenie dla kandydatów na kierowców zawodowych, którzy na etapie uzyskiwania wymaganych uprawnień ponoszą bardzo wysokie koszty szkolenia i egzaminowania. Pozytywnie należy również ocenić ponowne wprowadzenie terminu ważności pozytywnego wyniku części teoretycznej egzaminu państwowego. Jak wskazano w uzasadnieniu projektu, bezterminowa ważność tego wyniku może prowadzić do sytuacji, w której osoba przystępująca do części praktycznej zdała egzamin teoretyczny wiele lat wcześniej. W takim przypadku wiedza kandydata mogła ulec częściowemu zatarciu, a ponadto – ze względu na zachodzące w tym okresie zmiany przepisów – może nie odpowiadać aktualnemu stanowi prawnemu. Wprowadzenie 24-miesięcznego okresu ważności wyniku części teoretycznej zasługuje zatem na aprobatę, ponieważ zwiększa prawdopodobieństwo, że osoba przystępująca do egzaminu praktycznego będzie dysponowała aktualną wiedzą z zakresu przepisów i bezpieczeństwa ruchu drogowego.\\t\\n\\tArt. 1 pkt 14 lit. e projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\t Propozycja zmiany: 3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego przystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach wydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu lub zdrowiu uczestników ruchu drogowego – w takim przypadku osoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w pełnym zakresie.” - Proponuje się wykreślenie pkt 14  w proponowanym brzmieniu.  Proponuje się rezygnację z projektowanego rozwiązania w tym zakresie.  Uzasadnienie: Zgodnie z art. 51 ust. 3 pkt 1 lit. b oraz odpowiednio art. 51 ust. 5 pkt 2 ustawy, część praktyczna egzaminu państwowego obejmuje odrębnie sprawdzenie umiejętności \\fmanewrowania pojazdem lub zespołem pojazdów (w przypadku egzaminu na prawo jazdy) albo sprawdzenie pozostałych umiejętności wymaganych podczas egzaminu (w przypadku pozwolenia).  Oznacza to, że wynik uzyskany podczas wykonywania zadań na placu manewrowym jest niezależny od wyniku uzyskanego podczas realizacji zadań w ruchu drogowym. Nie istnieje zatem merytoryczny związek pomiędzy nieprawidłowym wykonaniem zadań egzaminacyjnych w ruchu drogowym, w tym doprowadzeniem do zagrożenia bezpieczeństwa ruchu drogowego, a prawidłowym wykonaniem manewrów na placu manewrowym.  W konsekwencji projektowany przepis prowadziłby do konieczności ponownej weryfikacji umiejętności, które zostały już pozytywnie ocenione na wcześniejszym etapie egzaminu, mimo że nie wystąpiły żadne okoliczności podważające prawidłowość tej oceny. Rozwiązanie takie pozostaje bez uzasadnienia merytorycznego i jest sprzeczne z konstrukcją części praktycznej egzaminu państwowego, w której poszczególne etapy służą ocenie odrębnych grup umiejętności kandydata.  Projektowane rozwiązanie rodzi również istotne wątpliwości formalnoprawne. Może bowiem prowadzić do sytuacji, w której egzamin praktyczny przeprowadzony w ruchu drogowym, następnie prawomocnie unieważniony z uwagi na naruszenie przepisów mające wpływ na jego wynik, wywoła wcześniej skutek prawny w postaci anulowania pozytywnego wyniku części egzaminu przeprowadzonej na placu manewrowym.  Przykładowo, kandydat uzyskuje pozytywny wynik z części egzaminu realizowanej na placu manewrowym, natomiast otrzymuje wynik negatywny z części przeprowadzanej w ruchu drogowym. Przystępując do kolejnego egzaminu wyłącznie w ruchu drogowym doprowadza – zgodnie z projektowanym przepisem – do sytuacji skutkującej utratą wcześniej uzyskanego pozytywnego wyniku z placu manewrowego. Następnie składa odwołanie od wyniku tego egzaminu, a właściwy organ lub sąd prawomocnie stwierdza, że egzamin został przeprowadzony z naruszeniem przepisów, które miało wpływ na jego wynik, i w konsekwencji unieważnia ten egzamin.  \\fW efekcie egzamin, który w świetle prawomocnego rozstrzygnięcia został uznany za przeprowadzony niezgodnie z prawem i wyeliminowany z obrotu prawnego, wywołał wcześniej skutki wobec innego, prawidłowo przeprowadzonego etapu egzaminu państwowego poprzez anulowanie pozytywnego wyniku uzyskanego na placu manewrowym. Powstaje zatem stan, w którym wadliwy egzamin oddziałuje na wynik odrębnej części egzaminu przeprowadzonej zgodnie z przepisami, mimo że sam został następnie prawomocnie uznany za nieważny. Takie rozwiązanie narusza zasadę pewności prawa oraz prowadzi do powstania niespójnych skutków prawnych, których projekt nie reguluje.\\t\\n\\tArt. 1 pkt 14  lit. e projektu ustawy\\tOgólnopolski Związek Zawodowy Pracowników Wojewódzkich Ośrodków Ruchu Drogowego\\tZaproponowana nowelizacja ustawy z dnia 5 stycznia 2011 r. o kierujących pojazdami (Dz.U.2025.1226 t.j.) przedstawia propozycję zmian w przepisach regulujących kwestie zachowania pozytywnej części egzaminu praktycznego w zakresie egzaminu przeprowadzanego na placu manewrowym oraz godzin, w jakich przeprowadzone są egzaminy państwowe. 1. Propozycja stanowi zmianę rozwiązania przedstawionego w projekcie ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw, znajdującej się w wykazie prac legislacyjnych i programowych Rady Ministrów pod numerem UD402. W przedstawionym projekcie proponuje się ponad przedstawione w niniejszym projekcie dodanie ustępu 3c, artykułu 51 zmienianej ustawy w brzmieniu: „3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego przystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach wydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu lub zdrowiu uczestników ruchu drogowego – w takim przypadku osoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w pełnym zakresie.” Zaproponowane brzmienie nie jest spójne z obecnym brzmieniem art. 52 ust. 2, który reguluje przesłankę przerwania egzaminu jako zachowanie, które „może zagrażać życiu lub zdrowiu egzaminatora lub innego uczestnika ruchu drogowego lub bezpośrednio wpływa na bezpieczeństwo ruchu drogowego\\\". Przesłanka ta jest szersza i dwuczłonowa (obejmuje zarówno zachowania mogące zagrażać, jak i wpływające na bezpieczeństwo), podczas gdy proponowany art. 51 ust. 3c posługuje się przesłanką węższą, która wymaga zagrożenia bezpośredniego życia i zdrowia uczestników ruchu. Powstaje w ten sposób realna możliwość rozbieżności skutków prawnych tego samego zdarzenia egzaminacyjnego. Egzamin może zostać przerwany na podstawie art. 52 ust. 2 (jako \\fzachowanie mogące zagrażać bezpieczeństwu), a mimo to nie spełni przesłanki z art. 51 ust. 3c. Projektodawca nie wyjaśnia w uzasadnieniu relacji między tymi dwiema przesłankami, co rodzi istotną wątpliwość interpretacyjną co do zakresu stosowania obu przepisów. Niezależnie od wskazanej wyżej niespójności zaproponowanej zmiany z art. 52 ust. 2, należy zwrócić uwagę na samą konstrukcję projektowanego przepisu. Art. 51 ust. 3a, 3b oraz 3c wprowadzają wielostopniowy warunek zachowania ważności wyniku części egzaminu przeprowadzanej na placu manewrowym, uzależniony od oceny zachowania zdającego w trakcie odrębnej, późniejszej części egzaminu w ruchu drogowym. Takie rozwiązanie jest trudne do jednoznacznej interpretacji dla egzaminatora, a tym bardziej dla osoby egzaminowanej, która powinna mieć możliwość zrozumienia zasad, na jakich jest oceniana bez konieczności sięgania po wykładnię systemową kilku przepisów jednocześnie. 2. Zaproponowane rozwiązanie eliminuje problem przeprowadzanie egzaminów w warunkach późnowieczornych, podczas których, z uwagi na niewielkie natężenie ruchu nie można w sposób właściwy ocenić zachowania osoby egzaminowanej w odniesieniu do innych uczestników ruchu. Dodatkowo przeprowadzanie egzaminów państwach poza nominalnym ruchem drogowym stoi w sprzeczności z normą prawną, zawartą w Dyrektywie, która stanowi „Kandydaci muszą wykonać wszystkie poniższe czynności w normalnym ruchu ulicznym”. Wprowadzenie proponowanego ograniczenia przyczyni się do zwiększenia wiarygodności egzaminu jako narzędzia oceny rzeczywistych kompetencji kandydatów na kierowców oraz zapewni większą spójność krajowych regulacji z przepisami prawa Unii Europejskiej.  \\t\\n\\tArt. 1 pkt 14 projektu ustawy\\tPolski Związek Szkoleniowy\\tW odniesieniu do art. 1 pkt 14:  a) W lit c proponujemy pozostawienie dotychczasowej maksymalnej liczby pytań lub ewentualnie usunięcie całego przepisu.  Obniżenie liczby pytań w bazie pytań stosowanej na egzaminie państwowym na prawo jazdy do 1500 doprowadzi do sytuacji w której każdy średnio-inteligentny kandydat na kierowcę będzie w stanie nauczyć się wszystkich pytań na pamięć. Nie pomoże dynamiczna zmiana pytań, czy ich utajnienie, jeżeli np. w zakresie prawa jazdy kategorii B będzie tylko 400 pytań egzaminacyjnych. Warto zauważyć, że liczba 1500 dotyczy pytań egzaminacyjnych na wszystkie kategorie prawa jazdy zarówno z części ogólnej jak i z części specjalistycznej, wliczając także te na pozwolenie na kierowanie tramwajem czy te na prawo jazdy kategorii AM. Zatem na poszczególne kategorie prawa jazdy będziemy mieli do nauczenia się \\fwyłącznie po kilkaset pytań. Z punktu widzenia procesu kształcenia jest to zła sytuacja, bo ograniczony ze względów praktycznych do niezbędnego minimum zakres części teoretycznej egzaminu spowoduje ograniczenie, ze względów ekonomicznych prowadzenia wykładów na korzyść nauki poszczególnych pytań. Takie działanie przyczyni się do pogorszenia jakości szkolenia a nie do jego poprawy.   b) Odnosząc się do propozycji zawartej w literze e dotyczącej podziału części praktycznej egzaminu na część na placu manewrowym i na część w ruchu drogowym w naszej ocenie rozwiązanie to jest właściwe, ale nie wymaga uregulowania ustawowego. Zasady organizacji i przeprowadzania egzaminu państwowego na prawo jazdy zgodnie z delegacją ustawową określoną w art. 66 ust. 1 pkt 4 ustawy o kierujących pojazdami opisane są w rozporządzenie Ministra Infrastruktury w sprawie egzaminowania osób ubiegających się o uprawnienia do kierowania pojazdami, szkolenia, egzaminowania i uzyskiwania uprawnień przez egzaminatorów oraz wzorów dokumentów stosowanych w tych sprawach. Tam są umieszczone zasady wystawiania oceny czy możliwości kontynuowania egzaminu. Dlatego też w naszej ocenie umieszczenie w ustawie przepisów art. 51 ust. 3a – 3c jest niezasadne. Wpisując je do ustawy należałoby do ustawy przenieść pozostałe zasady ocenienia co jest w naszej ocenie niepotrzebne. Zatem przepisy te, jak najbardziej potrzebne, należy umieścić w nowym rozporządzeniu w sprawie egzaminowania. Takie rozporządzenie i tak będzie musiało być przygotowane ze względu na likwidację placu manewrowego w ramach egzaminu państwowego w zakresie prawa jazdy kategorii B.   c) Ośrodek egzaminowania przesyła właściwemu organowi wydającemu prawo jazdy lub pozwolenie informację o pozytywnym albo negatywnym wyniku egzaminu przez aktualizację profilu kandydata na kierowcę w centralnej ewidencji kierowców.  \\t\\n\\t Art. 1 pkt 14 lit. f projektu ustawy\\t  NSZZ „Solidarność” - 80 w WORD i OSK\\t  W art. 51 ust 4a ustawy o kierujących dodać „Miasto, wskazane przez sejmik województwa na wniosek marszałka województwa jako miejsce przeprowadzania egzaminów musi posiadać infrastrukturę odpowiednią do realizacji zadań określonych w rozporządzeniu w sprawie egzaminowania jako obowiązkowe. Spełnienie tych warunków kontroluje marszałek województwa. Protokół z wykonania kontroli wykonania obowiązkowych zadań dołącza do wniosku.” Uzasadnieniem propozycji jest konieczność wyeliminowania sytuacji, o których \\fwielokrotnie informowaliśmy, że miasta wskazywane przez sejmik województwa to miasta, w których nie jest możliwe wykonanie zadań określonych jako obowiązkowe na egzaminie. Jeśli egzamin jest przeprowadzony w celu sprawdzania kwalifikacji osoby ubiegającej się o uprawnienia konieczne jest aby poziom trudności egzaminu był jednakowy we wszystkich ośrodkach egzaminowania i aby zdający byli równo traktowani  \\t\\n\\tArt. 1 pkt 14 lit. f projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\tf) ust. 4a otrzymuje brzmienie:  \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„4a. Egzamin państwowy w zakresie prawa jazdy kategorii AM, A1, A2, A, B1, B, B+E lub T może być także przeprowadzany w mieście niespełniającym warunków, o których mowa w ust. 4, wskazanym przez sejmik województwa na wniosek marszałka województwa.”; \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tKrajowe Stowarzyszenie Egzaminatorów negatywnie ocenia propozycję rozszerzenia możliwości przeprowadzania egzaminów państwowych w oddziałach terenowych o kategorie B+E oraz T. W naszej ocenie rozwiązanie to może generować nieproporcjonalnie wysokie koszty organizacyjne i infrastrukturalne w stosunku do rzeczywistego zapotrzebowania na egzaminy w tych kategoriach. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tPrzeprowadzanie egzaminów w zakresie kategorii B+E oraz T wymaga zapewnienia odpowiedniej infrastruktury, w szczególności placu manewrowego o powierzchni i parametrach umożliwiających prawidłowe wykonywanie wymaganych zadań egzaminacyjnych. W przypadku oddziałów terenowych, które korzystają z wynajmowanej infrastruktury, może to oznaczać konieczność wynajęcia dodatkowej powierzchni, jej odpowiedniego przygotowania oraz ponoszenia stałych kosztów utrzymania, niezależnie od faktycznej liczby przeprowadzanych egzaminów. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProblem ten nabiera szczególnego znaczenia w kontekście projektowanych zmian dotyczących egzaminów w zakresie kategorii B i B1, przewidujących odejście od wykonywania części dotychczasowych zadań na placu manewrowym. Wprowadzenie tych zmian może istotnie ograniczyć zapotrzebowanie na rozbudowaną infrastrukturę placów manewrowych wykorzystywanych w oddziałach terenowych do egzaminów. Jednoczesne rozszerzenie działalności tych oddziałów o kategorie B+E i T prowadziłoby natomiast do konieczności \\fdalszego utrzymywania lub nawet rozbudowywania placów manewrowych przede wszystkim na potrzeby tych dwóch kategorii. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW ocenie Krajowego Stowarzyszenia Egzaminatorów może prowadzić to do sytuacji ekonomicznie nieracjonalnej, w której znaczna powierzchnia infrastruktury egzaminacyjnej będzie utrzymywana na potrzeby relatywnie niewielkiej liczby egzaminów. Dotyczy to w szczególności kategorii T, w przypadku której liczba przeprowadzanych egzaminów w wielu ośrodkach jest niewielka. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tDodatkowym problemem pozostaje zapewnienie w oddziałach terenowych odpowiednich pojazdów egzaminacyjnych. W przypadku kategorii T konieczne byłoby zapewnienie ciągnika rolniczego wraz z przyczepą w miejscu przeprowadzania egzaminów. Transport takiego zespołu pojazdów pomiędzy główną siedzibą WORD, a oddziałem terenowym może być organizacyjnie skomplikowany i generować dodatkowe koszty. Alternatywą byłoby utrzymywanie odrębnego pojazdu w oddziale terenowym, co przy niewielkiej liczbie egzaminów w tej kategorii również może być ekonomicznie nieuzasadnione. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNależy ponadto zwrócić uwagę na nakłady inwestycyjne poniesione w ostatnich latach przez wojewódzkie ośrodki ruchu drogowego w związku z dostosowaniem infrastruktury do nowych wymagań dotyczących przeprowadzania egzaminów państwowych, w tym egzaminów kategorii C+E przy wykorzystaniu ciągnika siodłowego i naczepy o czym pisaliśmy wcześniej. Dostosowanie placów manewrowych wymagało w części ośrodków przeprowadzenia rozległych prac modernizacyjnych i poniesienia znaczących nakładów finansowych, sięgających – według informacji posiadanych przez środowisko – nawet około 1–2 mln zł w przypadku pojedynczych inwestycji. Należy przy  tej okazji wspomnieć  z dużym wyprzedzeniem, iż kwestią czasu będzie  jak politycy zauważą małe koszty tworzenia   i utrzymania oddziałów. Może wpłynąć to na masowe  tworzenie   oddziałów jak grzyby po deszcz co wpłynie   na  degradacje WORD-ów. \\t\\n\\tArt. 1 pkt 14 i 16 oraz art. 8 projektu ustawy w \\fzakresie art. 51, art. 52 ust. 1 i przepisów przejściowych\\t\\fUnia Metropolii Polskich im. Pawła Adamowicza\\tNależy ponownie przeanalizować przepisy przejściowe dotyczące ważności pozytywnego wyniku części teoretycznej egzaminu państwowego. Jeżeli celem jest zapewnienie aktualności wiedzy, warto rozważyć wprowadzenie długiego okresu dostosowawczego także dla wyników uzyskanych przed wejściem w życie ustawy, np. 24 albo 36 miesięcy od dnia \\fwejścia w życie przepisów, albo szczegółowo uzasadnić utrzymanie ich bezterminowej ważności. Niezależnie od przyjętego wariantu system powinien automatycznie informować kandydata i organy o utracie ważności wyniku. Uzasadnienie: Uzasadnienie trafnie wskazuje, że brak terminu ważności wyniku teoretycznego może prowadzić do przystępowania do egzaminu praktycznego po wielu latach od zdania teorii. Jednocześnie projekt utrzymuje bezterminową ważność wyników dotychczasowych. Powstaje więc niespójność między deklarowanym celem regulacji a rozwiązaniem przejściowym. Z perspektywy organów stosujących prawo konieczne jest także jednoznaczne, systemowe oznaczanie ważności wyniku, aby uniknąć sporów przy kierowaniu na egzamin praktyczny\\t\\n\\t Art. 1 pkt 19 projektu ustawy\\t NSZZ „Solidarność” - 80 w WORD i OSK\\t  W art. 54 dodać „Rejestracji obrazu dokonuje się za pomocą jednej kamery skierowanej do przodu pojazdu” skreślić „za pomocą urządzenia zainstalowanego w pojeździe towarzyszącym, a w miarę możliwości technicznych – także”. Uzasadnieniem tej propozycji jest wprowadzenie zapisu, który zestandaryzuje warunki nagrywania we wszystkich ośrodkach – nie ma potrzeby montowania kilku kamer – na licznik, na osobę zdającą, na tył, bok pojazdu – z nagrania będzie można skutecznie prowadzić nadzór nad egzaminami, bo Marszałek będzie mógł skontrolować czy egzamin odbył się zgodnie z obowiązującymi przepisami i czy ewentualne błędy popełnione przez egzaminatora miały wpływ na wynik egzaminu.  \\t\\n\\tArt. 1 pkt 19 lit. a projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t19) w art. 54: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\ta) ust. 1 otrzymuje brzmienie: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„1. Przebieg części praktycznej egzaminu państwowego dla każdej kategorii prawa jazdy rejestruje się za pomocą urządzenia służącego do zapisu obrazu i dźwięku. W przypadku egzaminu państwowego przeprowadzanego pojazdem jednośladowym rejestracja odbywa się za pomocą urządzenia zainstalowanego w pojeździe towarzyszącym, a w miarę możliwości technicznych – także za pomocą urządzenia rejestrującego zainstalowanego na pojeździe egzaminacyjnym lub w wyposażeniu osoby egzaminowanej.”, \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\fStanowisko Krajowego Stowarzyszenia Egzaminatorów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tKrajowe Stowarzyszenie Egzaminatorów zgłasza istotne zastrzeżenia dotyczące praktycznej możliwości realizacji obowiązku rejestracji obrazu i dźwięku podczas części praktycznej egzaminów państwowych w zakresie kategorii AM, A1, A2 i A na placu manewrowym. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowiska przeznaczone do wykonywania poszczególnych zadań egzaminacyjnych dla tych kategorii są rozmieszczone w różnych częściach placu manewrowego. Jednocześnie na placu może być prowadzonych kilka egzaminów, zarówno w zakresie kategorii motocyklowych, jak i innych kategorii prawa jazdy. W tych warunkach zapewnienie ciągłej i czytelnej rejestracji przebiegu konkretnego egzaminu, wraz z zapisem dźwięku, za pomocą urządzenia znajdującego się w pojeździe towarzyszącym może być w praktyce niemożliwe. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tPojazd towarzyszący wykorzystywany podczas egzaminu w ruchu drogowym nie jest pojazdem przeznaczonym do przemieszczania się po placu manewrowym w ślad za osobą wykonującą poszczególne zadania. Konieczność jego wielokrotnego przestawiania pomiędzy stanowiskami egzaminacyjnymi byłaby nie tylko niepraktyczna, ale mogłaby również powodować dodatkowe zagrożenie dla osób wykonujących w tym samym czasie zadania na placu manewrowym. Powstaje również problem organizacyjny dotyczący tego, kto miałby taki pojazd przemieszczać w czasie, gdy egzaminator prowadzi egzamin. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW naszej ocenie projektowany obowiązek w tym zakresie nie uwzględnia rzeczywistego sposobu organizacji egzaminów motocyklowych na placach manewrowych WORD. Proponujemy zatem wyłączenie obowiązku rejestracji obrazu i dźwięku na placu manewrowym podczas egzaminów w zakresie kategorii AM, A1, A2 i A, pozostawiając obowiązek rejestracji egzaminu w ruchu drogowym za pomocą urządzenia znajdującego się w pojeździe towarzyszącym. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tZastrzeżenia dotyczą również objęcia obowiązkiem rejestracji egzaminów w zakresie kategorii T. Pojazdy wykorzystywane do tych egzaminów nie zawsze stanowią własność wojewódzkiego ośrodka ruchu drogowego, a ich konstrukcja i wyposażenie mogą nie umożliwiać trwałego oraz zgodnego z wymaganiami technicznymi zamontowania urządzenia rejestrującego i \\fzapewnienia mu odpowiedniego źródła zasilania. Z tego względu proponujemy rozważenie wyłączenia kategorii T z obowiązku rejestracji przebiegu części praktycznej egzaminu. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tOdrębnym i szczególnie istotnym problemem jest zapewnienie rejestracji w pojazdach, które nie są własnością ośrodka egzaminowania. W praktyce jedynym możliwym rozwiązaniem będzie w wielu przypadkach zastosowanie przenośnego urządzenia rejestrującego, montowanego przed rozpoczęciem egzaminu i zasilanego z instalacji elektrycznej pojazdu, np. poprzez gniazdo 12 V. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNie można przy tym zagwarantować, że w każdym pojeździe podstawionym na egzamin gniazdo takie będzie sprawne albo w ogóle dostępne. Powstaje zatem praktyczny problem, czy w przypadku braku możliwości zasilenia urządzenia rejestrującego egzamin będzie mógł zostać przeprowadzony, a jeżeli nie – kto będzie ponosił konsekwencje braku technicznej możliwości dokonania rejestracji. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tProjektowana regulacja powinna jednoznacznie rozstrzygać takie sytuacje, ponieważ brak możliwości technicznych niezależny od egzaminatora i ośrodka egzaminowania nie powinien prowadzić do odpowiedzialności egzaminatora ani automatycznie uniemożliwiać przeprowadzenia egzaminu. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNależy ponadto zwrócić uwagę na konieczność dostosowania przepisów wykonawczych do projektowanej zmiany. Zgodnie z § 7 ust. 1 pkt 3 rozporządzenia regulującego przeprowadzanie egzaminów: \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t„Urządzenie, o którym mowa w art. 54 ust. 1 ustawy: (...)  \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t3) uniemożliwia ingerencję w zapis na informatycznym nośniku danych”. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW przypadku urządzeń rejestrujących zamontowanych na stałe w pojazdach egzaminacyjnych spełnienie tego wymagania jest możliwe. Sytuacja wygląda jednak inaczej w przypadku przenośnych urządzeń wykorzystywanych w pojazdach podstawianych na egzamin. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tPrzenośna kamera zasilana z gniazda pojazdu z natury rzeczy pozostaje urządzeniem, do którego użytkownik ma fizyczny dostęp. Możliwe jest odłączenie jej od źródła zasilania, a w \\fzależności od konstrukcji urządzenia również użycie znajdujących się na nim przycisków sterujących. Powstaje zatem zasadnicza wątpliwość, czy urządzenie tego rodzaju będzie mogło zostać uznane za spełniające wymaganie określone w § 7 ust. 1 pkt 3 rozporządzenia. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tNie można z jednej strony nakładać obowiązku rejestracji egzaminów w pojazdach, w których ze względów technicznych możliwe jest zastosowanie wyłącznie urządzeń przenośnych, a z drugiej utrzymywać wymagań technicznych skonstruowanych z myślą o urządzeniach zamontowanych na stałe w pojazdach egzaminacyjnych. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tW związku z powyższym Krajowe Stowarzyszenie Egzaminatorów proponuje: wyłączenie obowiązku rejestracji obrazu i dźwięku na placu manewrowym podczas egzaminów w zakresie kategorii AM, A1, A2 i A; wyłączenie kategorii T z obowiązku rejestracji albo wprowadzenie szczególnych zasad rejestracji dla tej kategorii; jednoznaczne uregulowanie sposobu postępowania w przypadku braku technicznej możliwości podłączenia lub zasilenia urządzenia rejestrującego w pojeździe podstawionym na egzamin; dostosowanie § 7 ust. 1 pkt 3 rozporządzenia do możliwości stosowania przenośnych urządzeń rejestrujących, w szczególności poprzez zmianę lub usunięcie tego wymagania w odniesieniu do urządzeń wykorzystywanych w pojazdach podstawianych na egzamin. \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tWprowadzenie obowiązku rejestracji dla kolejnych kategorii prawa jazdy powinno zostać poprzedzone określeniem takich wymagań technicznych, które będą możliwe do spełnienia w rzeczywistych warunkach prowadzenia egzaminów państwowych.\\t\\n\\tArt. 1 pkt 19 lit. c projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\tc) ust. 5 otrzymuje brzmienie:  „5. Jeżeli egzamin jest przeprowadzany pojazdem:  1) osoby niepełnosprawnej wymagającej przystosowania pojazdu do rodzaju schorzenia, 2) bez pedału sprzęgła, jeżeli nie jest to pojazd będący w dyspozycji wojewódzkiego ośrodka ruchu drogowego \\f– urządzenie, o którym mowa w ust. 1, zapewnia wojewódzki ośrodek ruchu drogowego.”; \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: Krajowe Stowarzyszenie Egzaminatorów uwzględniając rosnącą ilość egzaminów przeprowadzanych pojazdami bez pedału sprzęgła obawia się, iż proponowana zmiana wygeneruje znaczący wzrost kosztów dla WORD-ów w postaci dodatkowych urządzeń oraz ich obsługi. Na dzień dzisiejszy prawie wszystkie pojazdy nauki jazdy są wyposażone w kamery, a dodatkowo wprowadza się obowiązek rejestracji egzaminów wewnętrznych. Brak możliwości wykorzystania tego sprzętu na egzaminie, dublowanie kamer, wyłączanie tych należących do ośrodka szkolenia , a montowanie należących do ośrodka egzaminowania  nie znajduje logicznego uzasadnienia. W przypadku podstawienia pojazdu bez pedału sprzegła pojazd ten powinien być wyposażony w kamerke przez Ośrodek szkolenia  tak jak kazdy inny  pojazd podstawiany na egzamin kategorii  B.  \\t\\n\\tArt. 1 pkt 14 lit. e projektu ustawy\\tKrajowe Stowarzyszenie Dyrektorów Wojewódzkich Ośrodków Ruchu Drogowego\\tUsunięcie ust. 3c z art. 51 Uzasadnienie: Brak związku celu realizowania egzaminu na placu manewrowym z egzaminem praktycznym przeprowadzanym w ruchu drogowym.  Stworzenie bezpośredniego zagrożenia dla zdrowia lub życia uczestników ruchu drogowego podczas przeprowadzania części praktycznej egzaminu w ruchu drogowym nie ma związku ze sprawnością manewrowania pojazdem lub panowania nad nim podczas realizowania zadań egzaminacyjnych na placu manewrowym Mając powyższe na względzie zasadnym jest pozostawienie jedynie ust. 3a i 3b w art. 51\\t\\n\\tArt. 1 pkt 14 lit. e projektu ustawy\\tOIGOSK, LFEDERACJA, PIGOSK\\tw lit. e wykreślić dodawany ust. 3c  „3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie kolejnego przystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony w przepisach wydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża bezpośrednio życiu lub zdrowiu uczestników ruchu drogowego – w takim przypadku osoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w pełnym zakresie.”,   Uzasadnienie Naszym zdaniem propozycja aby przerwanie egzaminu praktycznego prowadzonego w ruchu drogowym skutkowało koniecznością uzyskania ponownie \\fpozytywnego wyniku z części egzaminu realizowanego na placu manewrowym – nie ma żadnego uzasadniania merytorycznego i ma charakter wyłącznie sankcyjny.\\t\\n\\tArt. 1 pkt 14 projektu ustawy w zakresie art. 51 ust. 3 pkt 1 ustawy o kierujących pojazdami\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPropozycja zmiany: w lit. a skreśla się wyrazy „B1, B i AM (trójkołowiec)  Proponowana zmiana jest wynikiem zaproponowanej zmiany w samym procesie szkolenia.  Uzasadnienie: Brak związku celu realizowania egzaminu na placu manewrowym z egzaminem praktycznym przeprowadzanym w ruchu drogowym.  Stworzenie bezpośredniego zagrożenia dla zdrowia lub życia uczestników ruchu drogowego podczas przeprowadzania części praktycznej egzaminu w ruchu drogowym nie ma związku ze sprawnością manewrowania pojazdem lub panowania nad nim podczas realizowania zadań egzaminacyjnych na placu manewrowym Mając powyższe na względzie zasadnym jest pozostawienie jedynie ust. 3a i 3b w art. 51\\t\\n\\tArt. 1 pkt 14 lit. e projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPropozycja zmiany: Usunięcie ust. 3c z art. 51  Uzasadnienie: Brak związku celu realizowania egzaminu na placu manewrowym z egzaminem praktycznym przeprowadzanym w ruchu drogowym.  Stworzenie bezpośredniego zagrożenia dla zdrowia lub życia uczestników ruchu drogowego podczas przeprowadzania części praktycznej egzaminu w ruchu drogowym nie ma związku ze sprawnością manewrowania pojazdem lub panowania nad nim podczas realizowania zadań egzaminacyjnych na placu manewrowym Mając powyższe na względzie zasadnym jest pozostawienie jedynie ust. 3a i 3b w art. 51\\t\\n\\tArt. 1 pkt 15 projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPropozycja zmiany: po art. 51 dodaje się art. 51a w brzmieniu: – 12 – „Art. 51a. 1. Zakazu, o którym mowa w art. 50 ust. 2 pkt 9, nie stosuje się, jeżeli egzamin nie doszedł do skutku z przyczyn niezależnych od osoby egzaminowanej. 2. W przypadku, o którym mowa w ust. 1, kandydatowi wyznacza się nowy termin egzaminu bez pobierania dodatkowej opłaty. Nowy termin może przypadać w tym samym \\fdniu wyłącznie, gdy pozwalają na to warunki techniczne i organizacyjne wojewódzkiego ośrodka ruchu drogowego oraz kandydat wyrazi na to zgodę.”; - proponuje się wykreślić zapis w zaproponowanym brzmieniu.   Uzasadnienie: proponuje się wykreślić zapis w związku z uzasadnieniem i propozycją wykreślenia Art. 1 pkt 13  \\t\\n\\tArt. 1 pkt 15 projektu ustawy\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\tAd. art. 1 pkt 15 projektu  - Przepis art. 1 pkt 16 lit. e projektu wprowadza zmiany w art. 52 UoKP, regulujące zasady uznawania wyników egzaminu teoretycznego przez okres 24 miesięcy. Nie negując potrzeby takiej regulacji, chcemy zwrócić uwagę że zaproponowany okres wydaje się być zbyt długi.  Należy bowiem pamiętać, że mózg dorosłego człowieka zarządza pamięcią w sposób wysoce ekonomiczny. Informacje teoretyczne ze szkoleń trafiają najpierw do pamięci krótkotrwałej. Aby przeszły do pamięci długotrwałej, musi zajść proces konsolidacji. Jeśli mózg nie otrzymuje silnego sygnału, że dana wiedza jest krytyczna (czyli nie jest natychmiast używana do rozwiązywania bieżących problemów ani nie powtarza się cyklicznie), to traktuje ją jako zbędny szum informacyjny i celowo ją usuwa, by nie przeciążać układu nerwowego. Ponieważ osoba ubiegająca się o uprawnienia, do momentu zdobycia tych uprawnień nie będzie posługiwała się zdobytą wiedzą teoretyczną w praktyce (uczestnicząc w ruchu drogowym jako kierowca), to w bardzo szybkim tempie dojdzie do jej wyparcia i utraty odpowiednich kompetencji. Nie pogłębiając ze swej strony tego tematu, proponujemy zapoznanie się z publikacjami i wynikami badań takimi jak: Hermann Ebbinghaus, \\\"Memory: A Contribution to Experimental Psychology\\\" (1885), publikacje z obszaru Learning & Development (L&D), w tym m.in. publikowane statystyki przez organizacje takie, jak Association for Talent Development (ATD), etc.\\t\\n\\tArt. 1 pkt 16 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 16 proponujemy skrócenie okresu do 12 miesięcy. \\t\\n\\t \\fArt. 1 pkt 17 i 20 projektu ustawy\\t \\fZwiązek Pracodawców „Transport i Logistyka Polska”\\t \\fAd. art. 1 pkt 17 i 20 projektu  Przepisy art. 1 pkt 17 i 20 projektu wprowadzają zmiany w art. 53 ust. 4b oraz art. 56 ust. 2b-2c UoKP. Nie negując tych rozwiązań, zwracamy jednocześnie uwagę, iż projekt ustawy nie uwzględnia zmian, które ułatwiałyby prowadzenie szkolenia kierowców kategorii C i C+E przez szkoły branżowe, prowadzące kształcenie zawodowe/techniczne, pomimo że odgrywają one istotną rolę w przygotowaniu przyszłych kierowców zawodowych. Z informacji posiadanych przez TLP wynika, iż obecnie szkoły te i technika nie mogą organizować egzaminów na swoim terenie, nie mają ustawowego prawa do egzaminowania na własnych pojazdach, nie korzystają z uproszczonych wymagań organizacyjnych, nie mają preferencyjnego finansowania zakupu pojazdów do szkolenia, nie przewidziano dla nich odrębnych rozwiązań ułatwiających uzyskanie prawa jazdy kategorii C oraz C+E. W ocenie TLP, skoro projekt dopuszcza przeprowadzanie egzaminów państwowych na terenie jednostek wojskowych z wykorzystaniem należących do 21  tych jednostek pojazdów, to rozwiązaniem takim można byłoby objąć szkoły kształcące przyszłych kierowców zawodowych. Taka zmiana mogłaby zwiększyć dostępność szkolenia na kategorię C oraz C+E, bez obniżania wymagań egzaminacyjnych.  Dlatego też proponujemy:  nadanie następującego brzmienia art. 53 ust. 4b UoKP:   „4b. Egzamin państwowy w zakresie prawa jazdy kategorii C, C1, C+E oraz C1+E może być przeprowadzany również na terenie jednostki wojskowej lub szkoły prowadzącej kształcenie w zawodzie związanym z transportem drogowym lub spedycją, w rozumieniu przepisów ustawy z dnia 14 grudnia 2016 r. – Prawo oświatowe (Dz. U. z 2025 r. poz. 1043, z późn. zm.), z wykorzystaniem pojazdu pozostającego w dyspozycji odpowiednio tej jednostki lub szkoły, spełniającego wymagania określone w przepisach wydanych na podstawie niniejszej ustawy.”,  w art. 56 ust. 2b oraz ust. 2c UoKP, po wyrazach: „jednostce wojskowej”, dodaje się wyrazy: „lub szkole prowadzącej kształcenie w zawodzie związanym z transportem drogowym lub spedycją, w rozumieniu ustawy dnia 14 grudnia 2016 r. – Prawo oświatowe (Dz. U. z 2025 r. poz. 1043, z późn. zm.).”.  \\t\\n\\tArt. 1 pkt 18 projektu ustawy\\tPolski Związek Szkoleniowy\\t13) W odniesieniu do art. 1 pkt 18 w odniesieniu do: a) art. 53b ust. 1 W naszej ocenie wskazujemy nie ten system teleinformatyczny który powinien być wskazany. Jeżeli zachowujemy profil kandydata na kierowcę to można zachować następujące brzmienie użyte zresztą w rozporządzeniu w sprawie egzaminowania:   „Art. 53b. 1. Wojewódzki ośrodek ruchu drogowego aktualizuje profil kandydata na kierowcę w centralnej ewidencji kierowców w zakresie pozytywnego wyniku części praktycznej egzaminu państwowego uzyskanego na placu manewrowym, wraz z datą jego uzyskania oraz wskazaniem kategorii prawa jazdy lub pozwolenia, której wynik dotyczy.”  Takie rozwiązanie pozostawia jako podstawowy dokument kandydata na kierowcę profil kandydata na kierowcę.   Odchodząc od szczegółów warto zauważyć, że także w tym przypadku w ustawie niema żadnych odniesień do wpisywania czy przesyłania wyniku egzaminu i sposobu postępowania z poszczególnymi wynikami poszczególnych części egzaminów. Jest to domena rozporządzenia w sprawie egzaminowania tak jak opisywaliśmy w lit. c. Dlatego też należy rozważyć przeniesienie do ustawy całości sposobu i zasad uzyskiwania wyników egzaminów, albo (co będzie prostsze) wykreślenie ww. przepisów z ustawy i przeniesienie ich, tak jak dotychczas do rozporządzenia.\\t\\n\\tArt. 1 pkt 18 projektu ustawy\\tOIGOSK, LFEDERACJA, PIGOSK\\tw art.53b ust.2 skreślić „2. Opłata za część praktyczną egzaminu państwowego przeprowadzaną na podstawie art.51 ust. 3a jest pobierana w tej samej wysokości jak opłata za przeprowadzenie części praktycznej na podstawie art.51 ust. 3”.   Uzasadnienie Opłata powinna być pomniejszona z uwagi na mniejszy koszt ograniczonego zakresu zadań egzaminacyjnych, a także dyspozycję przepisu art.56a ust.2. Analiza projektu prowadzi do wniosku, że jego głównym celem jest zwiększenie kontroli nad procesem szkolenia i egzaminowania. Świadczą o tym między innymi obowiązek stosowania systemów GPS, rejestrowanie egzaminów wewnętrznych, rozszerzenie obowiązku stosowania kamer oraz tworzenie kolejnych mechanizmów nadzorczych. W naszej ocenie właściwszym kierunkiem byłoby skoncentrowanie się na poprawie jakości szkolenia oraz bezpieczeństwa ruchu drogowego. Osiągnięcie tego celu wymaga przede wszystkim inwestowania w edukację kandydatów na kierowców, systematyczne doskonalenie zawodowe instruktorów nauki jazdy oraz egzaminatorów, a także tworzenie nowoczesnych i jednolitych programów \\fszkolenia opartych na aktualnej wiedzy z zakresu bezpieczeństwa ruchu drogowego, psychologii transportu oraz metodyki nauczania. Projekt zdaje się opierać na założeniu, że zwiększenie nadzoru automatycznie przełoży się na poprawę jakości szkolenia. Tymczasem nadmierna kontrola nie zastąpi dobrze przygotowanego instruktora, rzetelnego procesu dydaktycznego ani wysokich standardów kształcenia. Jednocześnie proponowane rozwiązania mogą być odbierane jako wyraz ograniczonego zaufania wobec środowiska instruktorów i egzaminatorów, mimo że zdecydowana większość z nich wykonuje swoje obowiązki rzetelnie i zgodnie z obowiązującymi przepisami. Budowanie jakości systemu powinno opierać się przede wszystkim na wzmacnianiu kompetencji jego uczestników, a nie wyłącznie na rozbudowie mechanizmów kontrolnych. Dlatego warto rozważyć, aby większy nacisk położyć na rozwój programów szkolenia kandydatów na kierowców, doskonalenie zawodowe instruktorów i egzaminatorów oraz działania wspierające wysoką jakość procesu kształcenia. To właśnie edukacja i profesjonalne przygotowanie uczestników systemu są najskuteczniejszym sposobem poprawy bezpieczeństwa na drogach. Najlepszymi kontrolerami w systemie uzyskiwania uprawnień będą świadomi swoich praw i obowiązków kursanci. Propozycje zmian nie uwzględnione w opiniowanym projekcie usta\\t\\n\\t Art. 1 pkt 18 projektu ustawy \\t Związek Pracodawców „Transport i Logistyka Polska”\\t Ad. art. 1 pkt 18 projektu  Regulowanie szczegółowych czynności, związanych z wprowadzaniem danych przez wojewódzkie ośrodki ruchu drogowego, na szczeblu ustawowym, wydaje się być sprzeczne z zasadą minimalizmu legislacyjnego. Każdorazowa zmiana funkcjonalności systemu wymagać będzie w tym momencie decyzji Sejmu, Senatu i Prezydenta RP. Dlatego też uważamy, że proponowane przepisy powinny znaleźć sią w odpowiednim akcie wykonawczym, wydawanym przez ministra właściwego do spraw transportu\\t\\n\\tArt. 1 pkt 19 lit. c projektu ustawy\\tKrajowe Stowarzyszenie Dyrektorów Wojewódzkich Ośrodków Ruchu Drogowego\\tUsunięcie treści: „- urządzenie, o którym mowa w ust. 1 zapewnia wojewódzki ośrodek ruchu drogowego.” Uzasadnienie: Uwzględniając rosnącą ilość egzaminów przeprowadzanych pojazdami bez pedału sprzęgła proponowana zmiana wygeneruje znaczący wzrost kosztów dla WORD-ów związanych z nabyciem dodatkowych urządzeń oraz ich obsługi. Na dzień dzisiejszy prawie wszystkie pojazdy nauki jazdy są wyposażone w kamery a dodatkowo wprowadza się obowiązek rejestracji egzaminów wewnętrznych. Brak możliwości wykorzystania tego sprzętu na egzaminie, dublowanie kamer, wyłączanie tych należących do OSK a montowanie należących do WORD nie znajduje logicznego uzasadnienia.\\t\\n\\tArt. 1 pkt 19 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 19) c) ust. 5 otrzymuje brzmienie: wyrazy „5. Jeżeli egzamin jest przeprowadzany pojazdem: ...” proponujemy zastąpić wyrazami „5. Przepisów ust. 1-2 nie stosuje się jeżeli egzamin jest przeprowadzany pojazdem: ...”\\t\\n\\tArt. 1 pkt 19 projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\tProjektowane rozwiązanie wymaga ponownej oceny pod kątem jego efektywności oraz proporcjonalności w stosunku do zakładanych celów.  W przypadku egzaminów praktycznych przeprowadzanych w zakresie kategorii  innych niż kat. B proponuje się rozważenie zastosowania indywidualnych kamer nasobnych (kamer osobistych) używanych przez egzaminatorów zamiast wyposażania wszystkich pojazdów egzaminacyjnych w stacjonarne systemy rejestracji obrazu i dźwięku.  Rozwiązanie takie pozwoliłoby na istotne ograniczenie kosztów zakupu, montażu, serwisowania oraz utrzymania systemów rejestracji w pojazdach wykorzystywanych do przeprowadzania egzaminów. Jednocześnie kamery nasobne umożliwiają rejestrację przebiegu egzaminu z perspektywy egzaminatora, co może stanowić równie wartościowy materiał dowodowy w postępowaniach wyjaśniających.  Zastosowanie tego rozwiązania zapewniłoby zaproponowaną w projekcie transparentność procesu egzaminowania oraz większą elastyczność organizacyjną, możliwość wykorzystania jednego urządzenia przez egzaminatora podczas egzaminów przeprowadzanych na różnych pojazdach oraz znacząco ograniczyłoby koszty wdrożenia i eksploatacji systemu rejestracji bez uszczerbku dla realizacji celu projektowanej regulacji. Proponowane rozwiązanie mogłoby uwzględniać również rejestrację egzaminu na pozwolenie.  Uzasadnienie: Objęcie obowiązkiem rejestracji wszystkich egzaminów praktycznych bez egzaminu na pozwolenie będzie wiązało się z istotnym wzrostem kosztów związanych z zakupem, eksploatacją i serwisowaniem urządzeń rejestrujących, archiwizacją oraz zabezpieczeniem znacznie większej liczby nagrań, a także obsługą organizacyjną i informatyczną całego systemu. Jednocześnie należy spodziewać się wzrostu liczby skarg na przebieg egzaminów, co przełoży się na zwiększenie liczby postępowań wyjaśniających oraz kosztów ich prowadzenia.  Jednocześnie brak jest podstaw do przyjęcia, że powszechna rejestracja egzaminów pozwoli na jednoznaczne i obiektywne ustalenie stanu faktycznego w każdym przypadku. Materiał audiowizualny, z uwagi na ograniczenia techniczne rejestracji, nie odzwierciedla w pełni pola widzenia egzaminatora i osoby egzaminowanej, nie pozwala na wierną ocenę odległości, prędkości oraz wszystkich okoliczności mających znaczenie dla oceny przebiegu egzaminu, a także nie obejmuje wszystkich zdarzeń i komunikatów występujących poza pojazdem. W konsekwencji nagrania, pomimo znacznych kosztów ich pozyskania i przechowywania, w wielu przypadkach nie będą stanowiły wystarczającego materiału dowodowego do jednoznacznego rozstrzygnięcia zasadności wniesionej skargi.  W związku z powyższym zasadność objęcia obowiązkiem rejestracji wszystkich egzaminów praktycznych wymaga ponownej analizy pod kątem rzeczywistej skuteczności projektowanego rozwiązania oraz jego kosztów organizacyjnych i finansowych.  Objęcie obowiązkiem rejestracji wszystkich egzaminów praktycznych, z wyłączeniem egzaminów na pozwolenie, może spowodować istotny wzrost liczby skarg dotyczących przebiegu i wyniku egzaminów. Dostępność materiału z rejestracji przebiegu egzaminu będzie sprzyjała częstszemu kwestionowaniu rozstrzygnięć egzaminatorów oraz zwiększeniu liczby postępowań wyjaśniających prowadzonych przez marszałków województw.  W konsekwencji realizacja projektowanego rozwiązania może wymagać zwiększenia zasobów kadrowych urzędów marszałkowskich poprzez utworzenie dodatkowych etatów przeznaczonych do rozpatrywania skarg oraz analizy materiałów z rejestracji egzaminów. Oznacza to wzrost kosztów realizacji zadań zleconych z zakresu administracji rządowej, który powinien zostać uwzględniony w Ocenie Skutków Regulacji oraz znaleźć odzwierciedlenie w odpowiednim zwiększeniu wysokości dotacji celowej przekazywanej z budżetu państwa na realizację tych zadań. Projektowane rozwiązanie nie będzie miało wpływu na poprawę bezpieczeństwa ruchu drogowego ani na podniesienie jakości procesu szkolenia i egzaminowania kandydatów na kierowców. Rejestracja przebiegu egzaminu pełni wyłącznie funkcję dowodową.  \\fJednocześnie doświadczenia związane z rozpatrywaniem skarg wskazują, że znaczna ich część dotyczy okoliczności, których nie można jednoznacznie zweryfikować na podstawie materiału audiowizualnego sporządzonego zgodnie z obowiązującymi wymaganiami technicznymi. Dotyczy to w szczególności subiektywnej oceny zachowania innych uczestników ruchu, wzajemnej obserwacji, odległości, prędkości, warunków widoczności czy komunikacji odbywającej się poza polem rejestracji obrazu i dźwięku. W konsekwencji rozszerzenie obowiązku rejestracji wszystkich egzaminów nie doprowadzi do wyeliminowania sporów dotyczących przebiegu egzaminu, natomiast wygeneruje istotne koszty organizacyjne i finansowe związane z rejestracją, przechowywaniem oraz analizą materiałów, których wartość dowodowa w wielu przypadkach pozostanie ograniczona.  \\t\\n\\tArt. 1 pkt 20 projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPrzepis ust. 2b nie wskazuje, kto i według jakich kryteriów ma ocenić, czy dana lokalizacja i pojazd zapewnia warunki do przeprowadzenia egzaminu państwowego porównywalne z warunkami występującymi na trasach egzaminacyjnych wykorzystywanych przez WORD.   Projektowany przepis wymaga doprecyzowania warunków przeprowadzania egzaminu państwowego na terenie jednostki wojskowej lub innej infrastruktury pozostającej w jej dyspozycji.  Należy zwrócić uwagę, że nie każda jednostka wojskowa lub infrastruktura pozostająca w jej dyspozycji dysponuje warunkami umożliwiającymi realizację wszystkich zadań egzaminacyjnych wymaganych przepisami prawa. W szczególności może nie posiadać infrastruktury odpowiadającej wymaganiom placu manewrowego lub warunków pozwalających na przeprowadzenie wszystkich elementów części praktycznej egzaminu.  Ponadto jednostki wojskowe często są zlokalizowane poza obszarami zabudowanymi lub w znacznym oddaleniu od miejscowości, co może uniemożliwiać lub istotnie utrudniać przeprowadzenie części egzaminu wymagającej oceny umiejętności uczestnictwa w ruchu drogowym w typowych warunkach drogowych, obejmujących m.in. skrzyżowania, przejścia dla pieszych, sygnalizację świetlną, strefy ograniczonej prędkości czy ruch o odpowiednim natężeniu.  W związku z powyższym proponuje się uzależnienie możliwości przeprowadzania egzaminów na terenie jednostki wojskowej od wcześniejszego potwierdzenia przez właściwy wojewódzki ośrodek ruchu drogowego, że infrastruktura oraz lokalizacja wskazane przez jednostkę wojskową umożliwiają realizację pełnego zakresu egzaminu państwowego zgodnie z wymaganiami określonymi w ustawie i przepisach wykonawczych.\\t\\n\\t Art. 1 pkt 20 projektu ustawy\\t Małopolskie Stowarzyszenie Nauczycieli Kształcących Kierowców \\tUwaga 6. Doprecyzowanie zasad przeprowadzania egzaminu państwowego na wniosek jednostki wojskowej (art. 1 pkt 20 projektu; projektowane art. 56 ust. 2b i 2c) Treść uwagi: Popierając cel regulacji, którym jest usprawnienie procesu uzyskiwania uprawnień do kierowania pojazdami przez żołnierzy, postulujemy doprecyzowanie projektowanego art. 56 ust. 2b poprzez jednoznaczne wskazanie podmiotu przeprowadzającego egzamin, warunków, jakie muszą spełniać sala egzaminacyjna i stanowiska egzaminacyjne wraz z dostępem do systemu teleinformatycznego, oraz zasady, że część praktyczna egzaminu w zakresie jazdy w ruchu drogowym odbywa się na drogach publicznych. Problem: Projektowany przepis został sformułowany w sposób zbyt ogólny, ponieważ nie wskazuje, czy egzamin przeprowadzają egzaminatorzy zatrudnieni w wojewódzkim ośrodku ruchu drogowego, czy inne osoby posiadające uprawnienia egzaminatora, nie określa wymagań dla sali egzaminacyjnej i stanowisk egzaminacyjnych niezbędnych do przeprowadzenia części teoretycznej, w tym dostępu do systemu teleinformatycznego z bazą pytań egzaminacyjnych oraz możliwości wprowadzenia wyniku egzaminu do systemu, a sformułowanie o przeprowadzeniu egzaminu na terenie jednostki wojskowej lub innej infrastruktury pozostającej w jej dyspozycji może sugerować, że również jazda w ruchu drogowym miałaby odbywać się na terenie jednostki, którego infrastruktura drogowa, z uwagi na ograniczoną sieć dróg wewnętrznych i znikome natężenie ruchu, nie pozwala na rzetelną i porównywalną z egzaminami przeprowadzanymi w wojewódzkich ośrodkach ruchu drogowego ocenę zachowania kandydata w rzeczywistym ruchu drogowym, a konieczność dojazdu do najbliższych dróg spełniających wymagania egzaminacyjne mogłaby wydłużać egzamin ponad przewidziany czas i zaburzać organizację czasu pracy egzaminatorów. Brak tych regulacji może prowadzić do wątpliwości interpretacyjnych oraz podważać porównywalność procesu egzaminowania w skali kraju. \\fPropozycja zmiany zapisu: W art. 1 pkt 20 projektu proponujemy, aby projektowany art. 56 ust. 2b otrzymał brzmienie: „2b. Na wniosek jednostki wojskowej prowadzącej szkolenie żołnierzy na potrzeby Sił Zbrojnych Rzeczypospolitej Polskiej egzamin państwowy może być przeprowadzony przez wojewódzki ośrodek ruchu drogowego, przez zatrudnionych w nim egzaminatorów, na terenie tej jednostki wojskowej lub innej infrastruktury pozostającej w jej dyspozycji, z wykorzystaniem pojazdu wskazanego przez tę jednostkę, spełniającego wymagania, o których mowa w art. 24, przy czym część praktyczną egzaminu w zakresie jazdy w ruchu drogowym przeprowadza się na drogach publicznych.” oraz aby po projektowanym ust. 2c dodać ust. 2d w brzmieniu: „2d. Przeprowadzenie egzaminu państwowego w sposób określony w ust. 2b wymaga zapewnienia przez jednostkę wojskową sali egzaminacyjnej oraz stanowisk egzaminacyjnych spełniających warunki określone w przepisach wydanych na podstawie art. 66 ust. 1, wraz z dostępem do systemu teleinformatycznego, o którym mowa w art. 51 ust. 2a pkt 1, umożliwiającym przeprowadzenie części teoretycznej egzaminu państwowego oraz wprowadzenie wyniku egzaminu, a także zapewnienia egzaminatorom warunków pracy odpowiadających warunkom obowiązującym w wojewódzkim ośrodku ruchu drogowego.” \\t\\n\\tArt. 1 pkt 20 projektu ustawy \\tZwiązek Województw Rzeczypospolitej Polskiej\\tZaproponowany przepis ust. 2c - Zapis pozostaje zbyt ogólny.  Należałoby doprecyzować, jakie koszty ponosi jednostka wojskowa, w szczególności czy obejmują one koszty dojazdu egzaminatora do miejsca przeprowadzenia egzaminu, udział w kosztach jego wynagrodzenia lub inne koszty związane z organizacją i przeprowadzeniem egzaminu.  Ponadto zasadne byłoby określenie wymagań, jakie musi spełniać miejsce przeprowadzenia egzaminu, albo jednoznaczne wskazanie, czy jednostki wojskowe są zwolnione ze stosowania warunków i trybu przeprowadzania egzaminów określonych dla osób cywilnych.\\t\\n\\tArt. 1 pkt 20 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 20 proponujemy skreślić. \\t\\n\\tArt. 1 pkt 22 projektu ustawy  \\tPolska Wytwórnia Papierów Wartościowych S.A.\\tWyjaśnienia wymaga, z jakiego powodu projektodawca zamierza wprowadzić do ustawy system teleinformatyczny dostarczany przez ministra właściwego do spraw informatyzacji służący do opracowywania i weryfikowania pytań egzaminacyjnych na prawo jazdy (koszt budowy takiego systemu to - zgodnie z informacją zawartą w OSR - 7 050 000 zł).  Wymaga podkreślenia, że już obecnie system do weryfikacji pytań istnieje i jest nieodpłatnie udostępniany przez PWPW S.A. System ten jest zgodny z przepisami ustawy i spełnia wszystkie wymagania i oczekiwania Komisji do spraw weryfikacji i rekomendacji pytań egzaminacyjnych. Istnieje możliwość, aby do istniejącego już systemu do weryfikacji pytań wprowadzić mechanizmy dynamicznego generowania pytań, zgodnego z przepisami dyrektywy Parlamentu Europejskiego i Rady (UE) 2025/2205 z dnia 22 października 2025 r. w sprawie praw jazdy, zmieniająca rozporządzenie Parlamentu Europejskiego i Rady (UE) 2018/1724 \\ni dyrektywę Parlamentu Europejskiego i Rady (UE) 2022/2561 oraz uchylająca dyrektywę 2006/126/WE Parlamentu Europejskiego i Rady i rozporządzenie Komisji (UE) nr 383/2012.   PWPW S.A. jest w stanie zapewnić system opisany \\nw projekcie ustawy poprzez modernizację istniejącego rozwiązania. Koszt takiej modernizacji będzie zdecydowanie niższy niż koszt budowy nowego systemu teleinformatycznego przez ministra właściwego do spraw informatyzacji, który - według informacji zawartych w Ocenie Skutków Regulacji - wynosi 7 050 000 zł.  Projektowane brzmienie art. 57ac ust. 1 ustawy powinno otrzymać brzmienie:  \\f„1. Centrum Egzaminowania opracowuje lub weryfikuje pytania egzaminacyjne stosowane na egzaminie państwowym, egzaminach teoretycznych, o których mowa w art. 33 ust. 1 pkt 7, art. 58 ust. 1 pkt 7 i art. 117 ust. 2 pkt 7, oraz testach kwalifikacyjnych, o których mowa w art. 39b ust. 3 ustawy z dnia 6 września 2001 r. \\no transporcie drogowym, w systemie teleinformatycznym zapewnionym przez wytwórcę praw jazdy, kart kwalifikacji kierowcy i pozwoleń na kierowanie tramwajem, z którym jest zintegrowany system teleinformatyczny, o którym mowa w art. 51 ust. 2a pkt 1.”. \\t\\n\\t Art. 1 pkt 22 projektu ustawy\\t Związek Pracodawców „Transport i Logistyka Polska\\t Ad. art. 1 pkt 22 projektu,  Nie negując idei powołania odpowiedniego podmiotu odpowiadającego za zakres spraw, przypisanych w projekcie do proponowanego „Centrum egzaminowania”, TLP krytycznie ocenia koncepcję utworzenia tego „podmiotu” w strukturze organizacyjnej Instytutu Transportu Samochodowego (ITS). Projektowane rozwiązanie nie określa w sposób precyzyjny statusu prawnego Centrum Egzaminowania, jego miejsca w systemie podmiotów, realizujących powierzone zadania publiczne, ani relacji, pomiędzy Centrum, dyrektorem Instytutu Transportu Samochodowego i ministrem właściwym do spraw transportu. Nasze zastrzeżenia dotyczą 10 wskazanych poniżej obszarów.  Po pierwsze, Centrum Egzaminowania nie jest samodzielnym organem administracji publicznej. Z uzasadnienia projektowanych zmian wynika, że ma ono funkcjonować w strukturze organizacyjnej Instytutu Transportu Samochodowego. Oznacza to, że nie będzie ani odrębną państwową osobą prawną, ani odrębnym organem administracji publicznej, nie będzie posiadało osobowości prawnej, ani jakiejkolwiek odrębności organizacyjnej i finansowej od ITS. Co więcej, nie będzie nawet funkcjonowało w ramach urzędu obsługującego organ administracji publicznej, np. w strukturach ministerstwa, tylko będzie stanowiło komórkę organizacyjną w strukturze ITS. W tym miejscu pragniemy zaznaczyć, iż ITS jest instytutem badawczym, działającym na podstawie m.in. ustawy z dnia 30 kwietnia 2010 r. o instytutach badawczych, co oznacza, że Centrum Egzaminowania, jako wewnętrzna jednostka ITS, będzie mogła funkcjonować wyłącznie w ramach osobowości prawnej Instytutu, jego struktury organizacyjnej, planu działalności, planu finansowego oraz kompetencji dyrektora ITS. Nie będzie natomiast traktowana, jako podmiot istniejący niezależnie od ITS. Tymczasem projekt posługuje się nazwą „Centrum Egzaminowania” w \\fsposób sugerujący istnienie odrębnej instytucji publicznej, której bezpośrednio przypisuje się ustawowe zadania i kompetencje. Powstaje w ten sposób konstrukcja hybrydowa: Centrum nie jest organem ani osobą prawną, lecz jednocześnie projekt traktuje je jak samodzielnego adresata ustawowych norm kompetencyjnych. Jest to rozwiązanie zdecydowanie wadliwe ustrojowo i legislacyjnie.  Po drugie, kompetencje powinny zostać powierzone ITS, a nie jego wewnętrznej komórce, tj. jeżeli ustawodawca zamierza powierzyć zadania związane z opracowywaniem i weryfikacją pytań egzaminacyjnych Instytutowi Transportu Samochodowego, to adresatem norm ustawowych w tym zakresie powinien być sam Instytut, reprezentowany przez jego dyrektora, a nie nieposiadające podmiotowości prawnej Centrum Egzaminowania, stanowiące komórkę w wewnętrznej strukturze organizacyjnej ITS. Jeżeli zatem projekt miałby zobowiązać ITS do wyodrębnienia w swojej strukturze komórki organizacyjnej obsługującej zadania związane z bazą pytań egzaminacyjnych, to należy wyraźnie oddzielić podmiot, któremu ustawa powierza zadanie publiczne, czyli ITS, organ osoby prawnej odpowiedzialny za jego wykonanie, czyli dyrektora ITS oraz wewnętrzną komórkę organizacyjną wykonującą czynności materialne i eksperckie, czyli Centrum Egzaminowania. Tymczasem, projektowane rozwiązania, nie przewidują takiego rozróżnienia, a w konsekwencji nie wiadomo, czy za działania Centrum odpowiada dyrektor ITS, kierownik Centrum, minister właściwy do spraw transportu, czy też samo Centrum, które jednak nie posiada zdolności prawnej ani zdolności do czynności prawnych. do ponoszenia odpowiedzialności.  Po trzecie, nie jest określona relacja Centrum z ustawowymi organami ITS. Zgodnie z ww. ustawą o instytutach badawczych, organami instytutu są dyrektor oraz rada naukowa. To dyrektor zarządza instytutem, reprezentuje go na zewnątrz i odpowiada za jego działalność. W tym kontekście projekt nie wyjaśnia natomiast: kto powołuje i odwołuje kierownika Centrum Egzaminowania, jakie wymagania musi spełniać kierownik Centrum, czy kierownik działa z upoważnienia dyrektora ITS, czy posiada własne ustawowe kompetencje, kto jako osoba fizyczna zatwierdza pytania egzaminacyjne i ponosi odpowiedzialność za ich zgodność z prawem, czy dyrektor ITS może ingerować w treść pytań, podstaw programowych oraz innych dokumentów opracowywanych przez Centrum, czy rada naukowa ITS posiada jakiekolwiek kompetencje w stosunku do działalności Centrum, jaki jest zakres nadzoru ministra nad poszczególnymi czynnościami Centrum, w jakim trybie można kwestionować rozstrzygnięcia, działania lub zaniechania Centrum i jaką formę będą miały takie \\frozstrzygnięcia (postanowień, decyzji, zarządzeń, uchwał). W tym kontekście z treści projektowanego art. 57aa ust. 1 UoKP wynika jedynie wewnętrzne umiejscowienie Centrum, a nie to co najważniejsze, tj. status prawny i pozycja wobec innych podmiotów i organów administracji.  Po czwarte, proponowane rozwiązanie wprowadza ryzyko powierzenia kompetencji publicznych podmiotowi niebędącemu organem, a opracowywanie i aktualizowanie pytań wykorzystywanych podczas egzaminu państwowego na prawo jazdy czy dla przyszłych kierowców zawodowych nie jest zwykłą działalnością naukową lub ekspercką. Pytania te współkształtują treść państwowego egzaminu, od którego zależy możliwość uzyskania uprawnienia do kierowania pojazdami albo wykonywania zawodu kierowcy. W tym kontekście, jeszcze poważniejsze wątpliwości wywołuje przewidziane w art. 57aa ust. 2 pkt 7 UoKP, powierzenie Centrum opracowywania i publikowania „podstaw programowych” szkoleń, które zgodnie z uzasadnieniem mają być dokumentami wiążącymi i określać cele edukacyjne, obowiązkowe treści oraz minimalne efekty uczenia się. Jeżeli dokument opracowywany przez Centrum ma kształtować treść obowiązków ośrodków szkolenia kierowców, instruktorów, wykładowców, ośrodków doskonalenia techniki jazdy lub innych podmiotów, to nie może być traktowany jedynie jako materiał ekspercki albo wewnętrzny dokument ITS. Normy powszechnie obowiązujące, określające prawa i obowiązki przedsiębiorców lub innych podmiotów spoza administracji publicznej, powinny wynikać przede wszystkim z ustawy, a nie powinny być ustanawiane przez komórkę organizacyjną instytutu badawczego w drodze publikacji dokumentu na jego stronie internetowej (swoją drogą zwaną w projekcie „stroną podmiotową” – art. 57aaust. 2 pkt 4 UoKP, czy art. 57ae UoKP). W tym zakresie, wątpliwości TLP budzi zgodność proponowanych rozwiązań z konstytucyjnym systemem źródeł prawa oraz zasadą legalizmu, zgodnie z którą organy władzy publicznej działają na podstawie i w granicach prawa. Centrum może przygotowywać projekty podstaw programowych, analizy i rekomendacje, natomiast dokument o charakterze wiążącym powinien zostać ustanowiony przez właściwy organ administracji publicznej w formie przewidzianej prawem.  Po piąte, projekt nie wprowadza żadnych rozwiązań wobec Centrum, na wypadek likwidacji, przekształcenia albo reorganizacji ITS, co w ocenie TLP jest istotnym mankamentem projektu, który całkowicie pomija skutki możliwych i legalnych zmian organizacyjnych dotyczących Instytutu Transportu Samochodowego, dokonanych na podstawie ww. ustawy o instytutach badawczych. Zgodnie z art. 7 tej ustawy ITS może \\fzostać połączony z innym instytutem, podzielony, zreorganizowany, przekształcony w instytucję gospodarki budżetowej, zlikwidowany, jeżeli minister nadzorujący (właściwy do spraw transportu) uzna takie działanie za uzasadnione merytorycznie, organizacyjnie lub finansowo. Oznacza to, że istnienie ITS w obecnym kształcie nie jest ustawowo zagwarantowane. Oznacza to, że projekt wiąże funkcjonowanie kluczowego elementu państwowego systemu egzaminowania - Centrum Egzaminowania - z instytutem badawczym, nie przewidując: następstwa prawnego w zakresie zadań Centrum, przejęcia bazy pytań egzaminacyjnych, przejęcia praw autorskich, dokumentacji i danych, kontynuacji zatrudnienia ekspertów, przejęcia środków pochodzących z opłat egzaminacyjnych, zapewnienia ciągłości działania systemu teleinformatycznego, wskazania podmiotu odpowiedzialnego za aktualizowanie pytań w okresie reorganizacji albo likwidacji ITS! Co więcej, projekt nie zawiera mechanizmu, pozwalającego ministrowi właściwemu do spraw transportu, przenieść zadania Centrum do innego podmiotu ani przepisu, zgodnie z którym zadania te z mocy prawa przechodziłyby na następcę prawnego ITS! W konsekwencji, reorganizacja instytutu mogłaby zagrozić ciągłości państwowych egzaminów na prawo jazdy i egzaminów dotyczących kwalifikacji zawodowych kierowców. W ocenie TLP, nie można zaakceptować sytuacji, w której trwałość wykonywania zadań o podstawowym znaczeniu publicznym zależy od dalszego istnienia ITS jako instytutu badawczego, bez ustanowienia ustawowych gwarancji sukcesji i ciągłości tworzonego podmiotu i powierzonych mu zadań!  Po szóste, projekt nie wskazuje charakteru i statusu zadań wykonywanych przez Centrum Egzaminowania w ramach ITS. Przepisy ww. ustawy o instytutach badawczych umożliwiają prowadzenie działalności innej niż naukowa, badawcza, rozwojowa, itd., jednakże pod warunkiem wyodrębnienia jej pod względem finansowym i rachunkowym. Ustawa dopuszcza również nałożenie na instytut zadania z zakresu administracji rządowej. W tym kontekście projekt powinien jednoznacznie rozstrzygnąć, czy zadania Centrum są zadaniami z zakresu administracji rządowej, nałożonymi na ITS na podstawie przepisów szczególnych i powinien określić nie tylko zasady ich finansowania, ale także nadzór i sprawozdawczość. Statut ITS, mający zastosowanie w tym zakresie, nie może zastępować ustawowej regulacji kompetencji podmiotu wykonującego odpowiednie zadania publiczne.  Po siódme, nie wskazano nadzoru nad Centrum Egzaminowania, tym samym odpowiedzialność za bazę pytań może zostać rozmyta. Z treści uzasadnienia do projektu wynika, iż przewiduje się zwiększenie niezależności procesu opracowywania pytań egzaminacyjnych, ale nie wyjaśnia się przy tym, od kogo Centrum ma być niezależne i w \\fjakim zakresie. Tymczasem, jeżeli Centrum ma być komórką wewnętrzną ITS, pozostaje organizacyjnie podporządkowane dyrektorowi ITS, którego z kolei nadzoruje minister właściwy do spraw transportu. W takiej sytuacji, projekt ustawy powinien jednoznacznie określić: kto i czy minister ten zatwierdza bazę pytań lub podstawy programowe, czy może nakazać zmianę pytania niezgodnego z prawem, czy może przeprowadzać kontrolę Centrum, w tym zażądać dokumentów i wyjaśnień, jakie posiada narzędzia prawne sprzeciwiające się rozstrzygnięciom Centrum, kto będzie odpowiadać za szkodę wynikającą z wadliwego pytania egzaminacyjnego, jaki będzie tryb usunięcia danego pytania z bazy, kto będzie odpowiadał za bazę pytań i całokształt działalności Centrum – Minister Infrastruktury, Dyrektor ITS, kierownik Centrum, Rada Konsultacyjna, czy osoby wchodzące w skład Centrum i w nim pracujące? 24  Po ósme, nie jest zdefiniowany status Rady Konsultacyjnej, działającej na podstawie projektowanego art. 57ad ust. 1-3 UoKP. Projektodawca wskazuje, iż ma być to organ społeczny o charakterze doradczo-opiniodawczym i ma składać się z ekspertów, wskazywanych przez ministra właściwego do spraw transportu w drodze zarządzenia. Pomijając zgodność z prawem takiej konstrukcji składu Rady, nie jest wskazane wprost: kto powołuje i odwołuje członków Rady, na jaką kadencję są powoływani, jakie są przesłanki ich odwołania, czy członkowie składają oświadczenia dotyczące konfliktu interesów, czy opinie Rady są jawne, czy opinia Rady jest obowiązkowa przed wprowadzeniem pytania do bazy, czy Centrum może odstąpić od opinii Rady, czy członkowie odpowiadają za zachowanie poufności pytań egzaminacyjnych. W ocenie TLP, biorąc pod uwagę założenia projektowanych zmian, zgodnie z którymi Rada ma stanowić gwarancję jakości i niezależności pytań egzaminacyjnych, zasady jej funkcjonowania powinny zostać określone w ustawie, a nie pozostawione wewnętrznym regulacjom ITS.  Po dziewiąte, w ocenie TLP nie jest jasny sposób finansowana Centrum Egzaminacyjnego, określony w art. 57c ust. 1 UoKP. Projekt zakłada finansowanie Centrum ze środków pochodzących z opłat za część teoretyczną egzaminu państwowego, uznając takie rozwiązanie stabilnym źródłem finansowania, nie przedstawiając jednak dokładnego modelu przepływu środków, sposobu obliczania należności ITS, ani kontroli ich wydatkowania. Co więcej, projekt przewiduje wpisaną na sztywną kwotę 2 zł, co oznacza, iż jakakolwiek potrzeba jej zmiany, zarówno podwyższenia, czy też zmniejszenia, będzie związana z koniecznością nowelizacji UoKP! Wydaje się, iż w tym zakresie, racjonalnym rozwiązaniem byłoby wprowadzenie procentowego odniesienia do wiarygodnych, adekwatnych do stanu \\fgospodarki wskaźników, dotyczących wynagrodzeń w gospodarce, określanych przez Główny Urząd Statystyczny. W tej sytuacji, projekt powinien dodatkowo wskazywać, czy: czy środki finansowe będą stanowiły przychód ITS, kto będzie pobierał i przekazywał część opłaty, według jakiego algorytmu zostanie ustalona jej wysokość w przypadku kolejnych zmian, czy wysokość finansowania będzie powiązana z rzeczywistymi kosztami Centrum, czy środki będą mogły być przeznaczane na inne zadania ITS, kto będzie kontrolował ich wykorzystanie, co stanie się ze środkami w razie likwidacji lub przekształcenia ITS?  Po dziesiąte, projekt nie przewiduje procedury weryfikacji działań Centrum, w szczególności zgłaszania i rozpatrywania zastrzeżeń dotyczących wadliwych pytań egzaminacyjnych, pytań niezgodnych z obowiązującym stanem prawnym, pytań zawierających więcej niż jedną prawidłową odpowiedź, ewentualnych błędów w tłumaczeniach, niezgodności materiałów audiowizualnych z rzeczywistym przebiegiem sytuacji drogowej, rozbieżności pomiędzy pytaniem a przyjętą podstawą programową. W ocenie TLP, osoba egzaminowana powinna mieć możliwość zakwestionowania pytania, które mogło mieć wpływ na wynik egzaminu. Projekt nie określa jednak, czy rozpatrzenie takiego zastrzeżenia będzie czynnością Centrum, Dyrektora ITS, marszałka województwa, ministra właściwego do spraw transportu, czy nawet sądu administracyjnego. W ocenie TLP, brak takiej procedury może podważać deklarowaną w uzasadnieniu transparentność systemu.  Reasumując, TLP proponuje utworzenie samodzielnej osoby prawnej, której przypisane zostaną odpowiednie kompetencje, albo przypisanie tych kompetencji bezpośrednio instytutowi badawczemu, wskazanemu przez ministra właściwego do spraw transportu. Oczywiście, przy jednoczesnym uregulowaniu wszystkich wymaganych kwestii tak, aby usunąć wskazane wyżej zastrzeżenia.  W odniesieniu do pkt 14 powyżej, wyjaśnienia wymagają także następujące kwestie:   - art. 57aa ust. 2 pkt 2 oraz art. 57ab ust. 1 UoKP – co odróżnia podmioty zewnętrzne od osób prywatnych, tj. czy chodzi tutaj o różnice w formie działalności, np. te pierwsze to podmioty zorganizowane, np. spółki, a te drugie to osoby fizyczne, a także w oparciu o co, o jakie przesłanki będzie weryfikacja propozycji pytań egzaminacyjnych; 25   \\f- art. 57aa ust. 2 pkt 7 UoKP – dlaczego użyto okres lenia „transport drogowy”, podczas gdy powinno być „przewóz drogowy”, co wynika choćby ze struktury przepisów i z tytułów rozdziało w ustawy z dnia 6 września 2001 r. o transporcie drogowym;  - art. 57ab ust. 3 UoKP, zakłada odesłanie do weryfikacji pytań, podczas gdy w przepisie, do którego następuje to odesłanie, jest mowa o aktualizacji pytań ;  - art. 57ab ust. 4 UoKP – dlaczego podmiotom przekazującym pytania nie przysługuje z tego tytułu wynagrodzenie, wobec faktu, iż jest to przecież praca wykonana przez takie podmioty;  - art. 57ac ust. 1 i następne UoKP – dla określeń dotyczących zakresu odesłania do pytań egzaminacyjnych, należałoby sformułować stosowny skrót, celem uniknięcia powtarzania pełnego tekstu w kolejnych przepisach projektowanej ustawy.   \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tOgólnopolski Związek Pracodawców Transportu Drogowego\\tBardzo dobrym krokiem jest propozycja powołania Centrum Egzaminowania w Instytucie Transportu Samochodowego jednostce podległej Ministrowi. Tak koncepcja była już omawiana kiedyś na forach branżowych i w ramach kierownictwa resortu. Szkoda jednak, że obecnie autorzy projektujący rozwiązania prawne zatrzymują się tylko na delegowaniu do ITS zadań merytorycznych: podstawy programowe, cele szkoleniowe, pytania egzaminacyjne i statystyki. Brakuje kolejnego kroku nowoczesne współfinansowane przez Państwo Centra Szkoleniowe, centralnie zarządzana struktura egzaminacyjna podległa Centrum Egzaminowania. Może pora zlikwidować polityczna podległość WORD i postawić na merytoryczną wartość szkolenia i oceny umiejętności kandydatów na kierowców. WORD początkowo jako wojewódzkie miejsca/centra egzaminowania to pomysł z ubiegłego wieku efekt wpływu na jakość szkolenia i poprawę BRD maja już dawno za sobą. Dobra infrastruktura oraz większość osób zatrudnionych tam osób o wysokich kompetencjach w obecnych ramach prawnych działania i egzaminowania nie przekłada się na właściwa ocenę i kwalifikację kandydatów do bezpiecznego uczestniczenia w ruchu drogowym\\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 22 – popierając ideę stworzenia Centrum Egzaminowania proponujemy: 1)  zmianę nazwy na: Agencja ds. Standardów Kierowania Pojazdami, 2)  zmianę koncepcji jej funkcjonowania na standard analogicznych agencji rządowych, 3)  zmianę zasad finansowania ww. Ich źródłem powinien być np. 1,5 % od każdego egzaminu (teoretycznego i praktycznego ) dla kandydatów na kierowców, instruktorów,  egzaminatorów, instruktorów techniki jazdy oraz testu kwalifikacyjnego). \\f4) poszerzenie zadań ww. instytucji na m.in. określanie standardów przeprowadzania i organizacji egzaminów, w tym systemu/ systemów teleinformatycznych. \\t\\n\\t Art. 1 pkt 22 projektu ustawy\\t Fundacja Zapobiegania Wypadkom Drogowym\\t Eksperci naszej Fundacji zwracają uwagę na brak szczegółów i wytycznych dotyczących funkcjonowania i struktury planowanego Centrum Egzaminowania. Nie zostały określone kompetencje osób, które będą weryfikowały, oceniały, redagowały pytania, nie jest znany jego skład ilościowy i zasady funkcjonowania. Jest to jeden z kluczowych elementów, szczególnie w kontekście niedawnych perturbacji związanych z egzaminami teoretycznymi na prawo jazdy.  \\t\\n\\tArt. 1 pkt 22 projektu ustawy w zakresie art. 57ab ustawy o kierujących pojazdami\\tZwiązek Województw Rzeczypospolitej Polskiej\\tPkt 4 i 5 - Brak regulacji odpłatności może powodować, że baza pytań będzie zasilana wyłącznie przez administrację, co ograniczy dostęp do wiedzy praktycznej osób wykonujących zawód instruktora, egzaminatora czy kierowcy zawodowego Powyższy zapis może zniechęcać podmioty zewnętrzne oraz osoby prywatne posiadające wiedzę i doświadczenie w zakresie szkolenia, egzaminowania oraz kierowania pojazdami do aktywnego współtworzenia i rozwijania bazy pytań egzaminacyjnych poprzez przekazywanie profesjonalnie opracowanych pytań testowych. W przypadku braku zainteresowania wykorzystaniem przedłożonego pytania przez Centrum podmiot lub osoba, która je opracowała, nie będzie miała możliwości jego zastosowania w ramach oficjalnej bazy. Natomiast w sytuacji, gdy Centrum zdecyduje się na wykorzystanie przekazanego pytania, zasadne jest wprowadzenie mechanizmu zapewniającego autorowi lub podmiotowi, który je opracował, odpowiednie wynagrodzenie za wykorzystanie przygotowanego materiału. Takie rozwiązanie stanowiłoby zachętę do współpracy z ekspertami zewnętrznymi, pozwoliłoby na zwiększenie jakości i różnorodności bazy pytań oraz zapewniłoby poszanowanie nakładu pracy osób tworzących wartościowe merytorycznie materiały egzaminacyjne.  Ponadto można rozważyć organizowanie konkursów z zakresu bezpieczeństwa ruchu drogowego (BRD), w ramach których osoby posiadające wiedzę i doświadczenie w obszarze szkolenia, egzaminowania oraz praktycznego uczestnictwa w ruchu drogowym mogłyby \\ftworzyć i zgłaszać wartościowe materiały, w tym profesjonalnie opracowane pytania egzaminacyjne. Takie rozwiązanie pozwoliłoby nie tylko na pozyskanie wysokiej jakości materiałów do wykorzystania w systemie egzaminowania, ale również stanowiłoby formę docenienia zaangażowania osób uczestniczących w tworzeniu treści służących poprawie bezpieczeństwa ruchu drogowego. Jednocześnie konkursowy charakter pozyskiwania materiałów mógłby zwiększyć zainteresowanie społeczne tematyką BRD oraz zachęcić większą liczbę ekspertów i praktyków do współpracy przy rozwijaniu systemu egzaminacyjnego przy jednoczesnym zachowaniu proponowanych rozwiązań dotyczących praw autorskich. \\t\\n\\tArt. 1 pkt 22 projektu ustawy w zakresie art. 57ac ustawy o kierujących pojazdami\\tZwiązek Województw Rzeczypospolitej Polskiej\\tProponuje się uzupełnienie składu rady o przedstawiciela organów nadzoru. Uzasadnienie: Uwzględnienie w składzie rady przedstawiciela organów nadzoru pozwoliłoby na zapewnienie szerszej perspektywy w zakresie funkcjonowania systemu egzaminowania oraz uwzględnienie doświadczeń wynikających z bieżącego nadzoru nad realizacją zadań związanych z przeprowadzaniem egzaminów państwowych. Organy nadzoru posiadają praktyczną wiedzę wynikającą z rozpatrywania skarg, prowadzonych postępowań wyjaśniających, analizy nieprawidłowości oraz oceny stosowania przepisów przez podmioty realizujące zadania w obszarze szkolenia i egzaminowania. Wiedza ta może stanowić istotny wkład w proces opiniowania rozwiązań dotyczących organizacji egzaminów, tworzenia pytań egzaminacyjnych oraz doskonalenia systemu zapewniającego jednolitość i obiektywność przeprowadzanych egzaminów. Udział przedstawiciela organów nadzoru pozwoliłby również na wcześniejsze identyfikowanie potencjalnych problemów interpretacyjnych i organizacyjnych związanych z projektowanymi rozwiązaniami oraz zapewniłby lepsze uwzględnienie praktycznych skutków proponowanych regulacji.\\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tWielkopolskie Stowarzyszenie OSK i Instruktorów\\tCo najmniej jeden z członków komisji powinien być rekomendowany przez działające na rynku stowarzyszenia branżowe. Niestety obecnie, w zdecydowanej większości, członkowie Komisji nie mają odpowiedniego doświadczenia w prowadzeniu szkolenia kandydatów na \\fkierowców, co dalej przekłada się na często mylną ocenę umiejętności kandydata na instruktora, w szczególności w części praktycznej egzaminu. \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tPolski Związek Niewidomych\\t11. Kandydaci na kierowców i kierowcy Aktualna propozycja zawarta w UD402 Projektowany art. 57ae pkt 1 stanowi: „1) w zakresie szkolenia kandydatów na kierowców i kierowców – cele edukacyjne szkolenia w zakresie niezbędnej wiedzy i umiejętności dotyczących kompetencji niezbędnych do bezpiecznej jazdy, opanowania pojazdu, świadomości czynników zwiększających ryzyko wypadku oraz umiejętności obiektywnej oceny własnych kompetencji i postaw;”. Przepis nie wymienia bezpiecznego zachowania wobec osób z niepełnosprawnościami ani innych niechronionych uczestników ruchu. Propozycja PZN Projektowanemu art. 57ae pkt 1 proponuje się nadać następujące brzmienie: „1) w zakresie szkolenia kandydatów na kierowców i kierowców – cele edukacyjne szkolenia w zakresie niezbędnej wiedzy i umiejętności dotyczących kompetencji niezbędnych do bezpiecznej jazdy, opanowania pojazdu, świadomości czynników zwiększających ryzyko wypadku, umiejętności obiektywnej oceny własnych kompetencji i postaw oraz bezpiecznego zachowania wobec niechronionych uczestników ruchu, w szczególności pieszych, rowerzystów, użytkowników hulajnóg elektrycznych, osób niewidomych i słabowidzących, osób korzystających z psa przewodnika oraz osób z ograniczoną mobilnością;”. Uzasadnienie Ogólne odwołanie do bezpieczeństwa nie gwarantuje, że w podstawach programowych znajdą się zagadnienia dotyczące osób z niepełnosprawnościami. Kandydat na kierowcę powinien wiedzieć między innymi, że: osoba niewidoma nie może nawiązać kontaktu wzrokowego z kierowcą, \\fgest wykonany z wnętrza samochodu (może Pan/Pani przechodzić) może być dla niej całkowicie niewidoczny, zachowanie osoby korzystającej z białej laski lub psa przewodnika może być odbierane jako nietypowe, kierowca powinien uwzględniać możliwość trudności w lokalizowaniu przejścia, rozpoznaniu zatrzymania pojazdu i ocenie sytuacji drogowej. Odwołanie do wcześniejszego opracowania W opracowaniu z 18 sierpnia 2025 r. wskazano potrzebę uwzględnienia zasad bezpieczeństwa, pierwszeństwa i relacji pomiędzy ruchem pieszym, rowerowym i samochodowym w szkoleniu kandydatów na kierowców oraz egzaminatorów. \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tPolski Związek Niewidomych\\t12. Kandydaci na instruktorów nauki jazdy i instruktorzy Aktualna propozycja zawarta w UD402 Projektowany art. 57ae przewiduje opracowanie podstaw programowych dla kandydatów na instruktorów i instruktorów, obejmujących niezbędną wiedzę, umiejętności dydaktyczne i kompetencje zawodowe. Projekt nie wskazuje jednak wprost obowiązku przygotowania instruktorów do nauczania zasad zachowania wobec osób z niepełnosprawnościami. Propozycja PZN Projektowanemu art. 57ae pkt 2 proponuje się nadać następujące brzmienie: „2) w zakresie szkolenia kandydatów na instruktorów nauki jazdy i instruktorów – cele edukacyjne szkolenia w zakresie niezbędnej wiedzy, umiejętności dydaktycznych i metodycznych oraz kompetencji zawodowych koniecznych do prawidłowego przygotowania kandydatów na kierowców do bezpiecznego uczestnictwa w ruchu drogowym, w tym rozpoznawania zagrożeń dotyczących niechronionych uczestników ruchu oraz osób z niepełnosprawnościami, kształtowania właściwych postaw i oceny postępów osoby szkolonej;”. \\fUzasadnienie Instruktor powinien umieć nie tylko przytoczyć treść przepisu, ale także wyjaśnić jego praktyczne zastosowanie w sytuacjach dotyczących osoby niewidomej, osoby korzystającej z psa przewodnika albo osoby o ograniczonej mobilności. Jest to szczególnie istotne w odniesieniu do przepisów dotyczących pierwszeństwa pieszych i rowerzystów, które nadal bywają niejednolicie rozumiane i stosowane. \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tPolski Związek Niewidomych\\t13. Kandydaci na egzaminatorów i egzaminatorzy Aktualna propozycja zawarta w UD402 Projektowany art. 57ae obejmuje podstawy programowe dla kandydatów na egzaminatorów i egzaminatorów, ale nie wskazuje wprost oceny zachowania osoby egzaminowanej wobec osób z niepełnosprawnościami. Propozycja PZN Projektowanemu art. 57ae pkt 3 proponuje się nadać następujące brzmienie: „3) w zakresie szkolenia kandydatów na egzaminatorów i egzaminatorów – cele edukacyjne szkolenia w zakresie niezbędnej wiedzy, umiejętności i kompetencji koniecznych do rzetelnego, obiektywnego i jednolitego przeprowadzania egzaminów państwowych, oceny zachowania osoby egzaminowanej wobec niechronionych uczestników ruchu, w tym osób z niepełnosprawnościami, rozpoznawania sytuacji niebezpiecznych oraz uzasadniania podejmowanych decyzji egzaminacyjnych;”. Uzasadnienie Jednolitość egzaminowania powinna obejmować sposób oceny zachowania wobec osób niewidomych, słabowidzących i osób z ograniczoną mobilnością. Brak wyraźnego wskazania tego obszaru może powodować różną ocenę podobnych sytuacji przez poszczególnych egzaminatorów. \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tPolski Związek Niewidomych\\t14. Konsultowanie podstaw programowych Aktualna propozycja zawarta w UD402 Projekt powierza Centrum Egzaminowania opracowywanie i publikowanie podstaw programowych, ale nie przewiduje obowiązku ich konsultowania z organizacjami osób z niepełnosprawnościami. Propozycja PZN W projektowanym art. 57ae proponuje się dodać ustęp w brzmieniu: „Przed opublikowaniem podstaw programowych w części dotyczącej bezpieczeństwa osób z niepełnosprawnościami i innych niechronionych uczestników ruchu Centrum Egzaminowania zasięga opinii reprezentatywnych organizacji osób z niepełnosprawnościami.” Uzasadnienie Praktyczna wiedza dotycząca poruszania się z białą laską, korzystania z psa przewodnika lub przemieszczania się na wózku nie może być w pełni zastąpiona wiedzą prawniczą, policyjną, szkoleniową lub egzaminacyjną. Zasięgnięcie opinii nie ograniczy kompetencji Centrum, a pozwoli zapobiec błędom merytorycznym i uproszczeniom.\\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tPolski Związek Niewidomych\\t15. Rozszerzenie katalogu dziedzin eksperckich Aktualna propozycja zawarta w UD402 Projektowany art. 57ad ust. 3 przewiduje, że w skład Rady Konsultacyjnej wejdzie co najmniej 12 ekspertów posiadających wiedzę lub doświadczenie w zakresie: bezpieczeństwa ruchu drogowego; szkolenia i egzaminowania; kontroli ruchu lub transportu drogowego; ratownictwa, ochrony ludności lub bezpieczeństwa publicznego; psychologii transportu, dydaktyki lub metodyki kształcenia; medycyny ratunkowej lub ratownictwa medycznego. \\fProjekt nie wymienia dostępności przestrzeni publicznej, projektowania uniwersalnego ani bezpieczeństwa osób z niepełnosprawnościami. Propozycja PZN W projektowanym art. 57ad ust. 3 po pkt 6 proponuje się dodać pkt 7 w brzmieniu: „7) dostępności przestrzeni publicznej, projektowaniu uniwersalnym lub bezpieczeństwa osób z niepełnosprawnościami w ruchu drogowym.”. Uzasadnienie Skoro bezpieczeństwo osób niewidomych i innych osób o szczególnych potrzebach stanowi jeden z powodów interwencji legislacyjnej, wiedza dotycząca tej grupy powinna być reprezentowana w Radzie opiniującej pytania egzaminacyjne i podstawy programowe.\\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tPolski Związek Niewidomych\\t16. Zagwarantowanie udziału eksperta dostępności Aktualna propozycja zawarta w UD402 Projekt wymienia dziedziny, z których mogą wywodzić się członkowie Rady, ale nie wymaga obecności przedstawiciela każdej z nich. Dodanie dostępności do katalogu nie zagwarantuje zatem samo w sobie powołania osoby posiadającej odpowiednie doświadczenie. Propozycja PZN W projektowanym art. 57ad proponuje się dodać ustęp w brzmieniu: „W skład Rady Konsultacyjnej wchodzi co najmniej jeden ekspert posiadający udokumentowane doświadczenie w zakresie dostępności przestrzeni publicznej, projektowania uniwersalnego lub bezpieczeństwa osób z niepełnosprawnościami w ruchu drogowym.” Uzasadnienie Bez takiej gwarancji perspektywa osób z niepełnosprawnościami może pozostać nieuwzględniona mimo formalnego rozszerzenia katalogu dziedzin. \\t\\n\\t Art. 1 pkt 22 projektu ustawy w zakresie art. 57ad ust. 3 ustawy o kierujących pojazdami\\t Ogólnopolskie Stowarzyszenie Instruktorów Techniki Jazdy\\t Zwracamy uwagę także na fakt, że kryteria określające kompetencje osób wchodzących w skład przyszłej Rady Konsultacyjnej (art. 1 pkt 22 w zakresie art. 57ad ust. 3) są nieprecyzyjne i bardzo ogólnikowe. W naszej ocenie niezbędne jest zobiektywizowanie tych wymagań poprzez określenie mierzalnych kryteriów, uwzględniających w szczególności aktualną wiedzę oraz praktyczne doświadczenie kandydatów. Zasadnym wydaje się – np. w dziedzinie szkolenia i egzaminowania instruktorów techniki jazdy - wprowadzenie wymogu aktywnego wykonywania działalności szkoleniowej w zakresie doskonalenia techniki jazdy w określonym okresie poprzedzającym powołanie do Rady, np. w ciągu ostatnich 10 lat. Doświadczenie to powinno obejmować rzeczywiste prowadzenie zajęć praktycznych i teoretycznych, a nie jedynie historyczne wykonywanie zawodu lub samo posiadanie uprawnień.  Nie sposób bowiem uznać za wystarczające doświadczenie zawodowe polegające na prowadzeniu zajęć z bezpiecznej jazdy kilkanaście lat temu, kiedy zarówno technologia motoryzacyjna, systemy bezpieczeństwa pojazdów, jak i metodyka szkolenia kierowców znacząco odbiegały od obecnych standardów. Według proponowanego brzmienia przepisu osoba, która nie prowadziła szkoleń od wielu lat, nadal mogłaby zostać członkiem Rady i współtworzyć pytania egzaminacyjne oraz standardy obowiązujące instruktorów aktywnie wykonujących zawód. Mając na uwadze odpowiedzialność Rady za kształtowanie poziomu merytorycznego egzaminów oraz standardów szkolenia, jej członkowie powinni legitymować się nie tylko doświadczeniem zawodowym, ale również aktualną praktyką szkoleniową, zapewniającą znajomość współczesnych realiów, technologii pojazdów oraz obowiązujących metod dydaktycznych. \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 22) Wprowadzająca Centrum Egzaminowania, które jest wspierane przez Radę Konsultacyjną jest krokiem w dobrym kierunku. Szczegółowe regulacje dotyczące m.in. praw autorskich pozwolą uniknąć problemów jakie były w obecnym systemie. Pozwolą właściwie każdemu wpływać na zawartość zestawu pytań egzaminacyjnych. Ograniczona ilość pytań ułatwi również nadzór nad ich aktualnością i poprawnością merytoryczną.\\t\\n\\t \\fArt. 1 pkt 22 projektu ustawy\\t \\f NSZZ „Solidarność” - 80 w WORD i OSK\\t \\fW art. 57 ab skreślić ust. 4 Propozycja aby nieodpłatnie przekazywać propozycje pytań jest kompletnie niezrozumiała. Jeśli pytania trafią do bazy pytań i z autorem zawarto umowę o ich wykorzystywaniu to umowa powinna przewidywać wynagrodzenie.  \\t\\n\\tArt. 1 pkt 22 projektu ustawy\\tZrzeszenie Międzynarodo-wych Przewoźników Drogowych w Polsce\\tzwracamy uwagę na prawdopodobną omyłkę pisarską w art. 1 pkt 22 projektu. W projektowanym art. 57aa ust. 2 pkt 6 wskazano na „Instytut Transportu Drogowego” zamiast „Instytut Transportu Samochodowego\\t\\n\\tArt. 1 pkt 23 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 1 zmiana 23) w art. 57c ust.1 otrzymuje brzmienie: Zmiana wprowadza opłatę w wysokości 2 zł. Może lepiej jak ta opłata była by określona w procentach tak jak było w starej wersji ustępu 1. Taki sposób naliczania zabezpieczył by ustawę przed konicznością aktualizowania tej kwoty z powodu inflacji.\\t\\n\\tArt. 1 pkt 23 projektu ustawy\\tKrajowe Stowarzyszenie Egzaminatorów\\t23) w art. 57c ust. 1 otrzymuje brzmienie: „1. Wojewódzkie ośrodki ruchu drogowego przekazują 2 zł z opłaty za przeprowadzenie części teoretycznej egzaminu państwowego na rachunek bankowy Instytutu Transportu Samochodowego na cele utworzenia, działalności i rozwoju Centrum Egzaminowania.”; \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\tStanowisko Krajowego Stowarzyszenia Egzaminatorów: Naszym zdaniem zaproponowana kwota przy obecnych cenach egzaminu teoretycznego jest  zbyt duża  na dzień dzisiejszy, ponieważ jest dwukrotnością obecnego zapisu 1,5% . Na dzień dzisiejszy  egzamin teoretyczny w wiekszości ośrodków ruchu drogowego w Polsce nie przekracza  60 złotych, co daje kwotę około 90 groszy.   W związku z powyższym Krajowe Stowarzyszenie Egzaminatorów jest za zostawieniem przekazywania 1,5 % opłaty za przeprowadzenie cześci teoretycznej egzaminu państwowego. Jednocześnie  proponujemy, podwyższyć kwotę za egzamin kwalifikacji  zawodowej  oraz przekazanie  od niego też 1.5 %.  \\t\\n\\tArt. 1 pkt 27 projektu ustawy\\tZwiązek Województw \\fRzeczypospolitej Polskiej\\t\\fProponuje się doprecyzowanie sposobu podawania analizy do publicznej wiadomości. Projektowany przepis wskazuje jedynie obowiązek publikacji analizy sporządzanej przez marszałka województwa, nie określając jednak formy ani miejsca jej udostępnienia. \\fNależałoby jednoznacznie wskazać, czy analiza powinna być publikowana w Biuletynie Informacji Publicznej urzędu marszałkowskiego, na stronie internetowej urzędu, stronie internetowej wojewódzkiego ośrodka ruchu drogowego, na tablicy ogłoszeń, czy w inny określony sposób. Doprecyzowanie sposobu realizacji obowiązku publikacji pozwoli na zapewnienie jednolitych zasad we wszystkich województwach oraz wyeliminuje ryzyko odmiennej praktyki stosowania przepisu przez poszczególnych marszałków województw.\\t\\n\\tArt. 1 pkt 27 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 27 proponujemy skreślić. \\t\\n\\tArt. 1 pkt 28 projektu ustawy\\tKrajowe Stowarzyszenie Dyrektorów Wojewódzkich Ośrodków Ruchu Drogowego\\tW dodanym punkcie 3 do art. 112 ust. 1,  art. 49 ust.1 punkt 3 lit a odnosi się do osób, którym cofnięto uprawnienia do kierowania pojazdami, natomiast w art. 112 w ust. 1 mówi się o szkoleniu praktycznym dla osób posiadających uprawnienia do kierowania pojazdami. Uzasadnienie: Brak spójności adresatów szkolenia praktycznego, o których mowa w art. 112 ust.1 – tj. osoby posiadające uprawnienia do kierowania pojazdami z osobami, o których mowa w art. 49 ust. 1 pkt lit a - przywrócenie uprawnienia do kierowania motorowerem, pojazdami silnikowymi lub tramwajem cofniętego na okres przekraczający rok lub cofniętego w związku z utratą kwalifikacji\\t\\n\\tArt. 1 pkt 28 projektu ustawy\\tZwiązek Województw Rzeczypospolitej Polskiej\\tW dodanym punkcie 3 do art. 112 ust. 1,  art. 49 ust.1 punkt 3 lit a odnosi się do osób, którym cofnięto uprawnienia do kierowania pojazdami, natomiast w art. 112 w ust. 1 mówi się o szkoleniu praktycznym dla osób posiadających uprawnienia do kierowania pojazdami.  Brak spójności adresatów szkolenia praktycznego, o których mowa w art. 112 ust.1 – tj. osoby posiadające uprawnienia do kierowania pojazdami z osobami, o których mowa w art. 49 ust. 1 pkt lit a - przywrócenie uprawnienia do kierowania motorowerem, pojazdami silnikowymi lub tramwajem cofniętego na okres przekraczający rok lub cofniętego w związku z utratą kwalifikacji \\t\\n\\tArt. 1 pkt 28 projektu ustawy\\tOgólnopolskie Stowarzyszenie Instruktorów Techniki Jazdy\\tOgólnopolskie Stowarzyszenie Instruktorów Techniki Jazdy wnosi o skreślenie zmiany zaproponowanej w art. 1 pkt 28 projektu ustawy o zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw (nr z wykazu UD 402) w brzmieniu:  28) w art. 112 w ust. 1 w pkt 2 w lit. d kropkę zastępuje się średnikiem i dodaje się pkt 3 w brzmieniu: „3) ośrodku szkolenia kierowców – w zakresie szkolenia mającego na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem lub przygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa w art. 49 ust. 1 pkt 2 i 3.”;  Uzasadnienie: Proponowany zapis umożliwia Ośrodkom Szkolenia Kierowców prowadzenie wszelkich szkoleń osób posiadających już uprawnienia do kierowania. Nie tylko tych kierowców, którzy np. nie prowadzili pojazdu przez dłuższy czas i chcą są przypomnieć ogólne zasady i przepisy ruchu drogowego. Zmiana umożliwia Ośrodkom Szkolenia Kierowców prowadzenie także wysoko specjalistycznych szkoleń i kursów z bezpiecznej jazdy, ecodrivigu, a nawet technik wychodzenia z poślizgów. Po wejściu przepisu w życie Ośrodki Szkolenia Kierowców będą mogły bowiem np. na kawałku dowolnego placu utworzyć sobie prowizoryczną matę poślizgową i w świetle prawa w tych warunkach szkolić.  Zwracamy uwagę na fakt, że w tej chwili omawiana działalność jest uregulowana poprzez ustawowe przypisanie jej Ośrodkom Doskonalenia Techniki Jazdy, które posiadają profesjonalną, opisaną we właściwym akcie prawnym infrastrukturę oraz wykwalifikowaną kadrę. Szkolenia w ODTJ prowadzą instruktorzy techniki jazdy z państwowymi uprawnieniami oraz z wiedzą i doświadczeniem w tym segmencie szkoleń.  Instruktorzy nauki jazdy zatrudnieni w OSK specjalizują się w przygotowaniu kursantów do zdania egzaminu państwowego na prawo jazdy, a więc w zupełnie innym zakresie. Należy podkreślić, że kompetencje nabywane podczas szkolenia (i weryfikowane poprzez egzaminy państwowe) kandydata na instruktora nauki jazdy i kandydata na instruktora techniki jazdy są zupełnie różne, właśnie ze względu na krańcowo odmienną wykonywaną potem pracę.  Nie negujemy potrzeby umożliwienia doszkalania się w Ośrodkach Szkolenia Kierowców kierowców objętych kontrolnym sprawdzeniem kwalifikacji czy chcącym sobie przypomnieć \\fzasady i przepisy ruchu drogowego lub podstawowe umiejętności kierowania pojazdem. Wymaga to jednak gruntownej zmiany i doprecyzowania przepisu, który w zaproponowanym brzmieniu znacznie rozszerza uprawnienia Ośrodka Szkolenia Kierowców o elementy, do których ani kadrowo, ani infrastrukturalnie nie jest przygotowany. \\t\\n\\tArt. 1 pkt 28 projektu ustawy\\tOgólnopolski Związek Wojewódzkich Ośrodków Ruchu Drogowego\\tW art. 1 pkt 28 proponujemy zmianę zapisu nowego pkt 3 na: ,,ośrodku szkolenia kierowców w zakresie pozwalającym na przygotowanie do kontrolnego sprawdzenia kwalifikacji, o którym mowa w art. 49 ust. 1 pkt 2 i 3 lub przywrócenia poziomu wiedzy i umiejętności umożliwiających bezpieczne kierowanie pojazdami, w szczególności w ruchu drogowym. \\t\\n\\t Art. 1 pkt 28 projektu ustawy\\t Związek Pracodawców „Transport i Logistyka Polska”\\t Ad art. 1 pkt 28 projektu  Art. 1 pkt 28 projektu proponuje zmiany art. 112 UoKP, umożliwiające szkolenie osób posiadających uprawnienia do kierowania pojazdem także przez ośrodki szkolenia kierowców, a nie tylko przez ośrodki doskonalenia techniki jazdy.  TLP, co do zasady, ocenia pozytywnie taką propozycję, gdyż postulat prowadzenia jazd doszkalających formułowany był od dawna przez różne środowiska. Możliwości prowadzenia takich jazd oczekiwały bowiem OSK, do których zgłaszały się np. osoby mające długą przerwę w prowadzeniu pojazdów, pragnące odnowić umiejętności praktyczne w kierowaniu pojazdem, które z upływem czasu uległy zatarciu, etc. Z kolei przedsiębiorcy wykorzystujący mniej popularne rodzaje pojazdów w danej kategorii prawa jazdy, wyrażali chęć zlecenia zajęć dokształcających dla nowo zrekrutowanych pracowników nie posiadających doświadczenia w kierowaniu takich pojazdów.  Niemniej zaproponowany sposób wyjścia naprzeciw tym postulatom nie pozwala jednoznacznie rozróżnić planowanych kompetencji ośrodków szkolenia kierowców od dotychczasowych kompetencji ośrodków doskonalenia techniki jazdy  Dlatego też proponujemy doprecyzowanie brzmienia proponowanego art. 112 ust. 1 pkt 3 UoKP w następujący sposób:  „3) ośrodku szkolenia kierowców – w ruchu drogowym, w zakresie szkolenia mającego na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem lub przygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa w art. 49 ust. 1 i pkt 2 i 3.”  \\fProponowane wyżej rozwiązanie wykluczy możliwość prowadzenia zajęć przez OSK na zamkniętych obiektach nie spełniających wymagań stawianych ODTJ-om w zakresie bezpieczeństwa wykonywanego szkolenia.\\t\\n\\t Art. 1 pkt 28 projektu ustawy\\t Stanowisko wspólne Tor Modlin sp. z o.o., Driveland sp. z o.o., Sobiesław Zasada Centrum sp. z o.o. sp.j., Aberos sp. z o.o. \\t Art. 2 Projekt ustawy zakłada zmianę art. 112 ust. 1 Ustawy poprzez dodanie pkt. 3 w następującym brzmieniu: „3) ośrodku szkolenia kierowców – w zakresie szkolenia mającego na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem lub przygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa w art. 49 ust. 1 pkt 2 i 3”.   W dotychczasowym brzmieniu art. 112 ust. 1 Ustawy przewiduje, że ośrodki doskonalenia techniki jazdy stopnia podstawowego prowadzą szkolenia w zakresie doskonalenia techniki jazdy kierowców posiadających prawo jazdy kategorii, A1, A2, A, B1, B lub B+E, zaś ośrodki doskonalenia techniki jazdy stopnia wyższego w zakresie doskonalenia techniki jazdy kierowców posiadających prawo jazdy kategorii C1, C1+E, C, C+E, D1, D1+E, D lub D+E.   W ramach postulowanej zmiany nie sposób dojść do wniosku, czym różni się szkolenie mające na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem od szkolenia w zakresie doskonalenia techniki jazdy. Ma to szczególne znaczenie praktyczne, w szczególności, że projektodawca odrębnie wyróżnił kategorię przygotowania do kontrolnego sprawdzenia kwalifikacji. O ile nie budzi żadnych wątpliwości możliwość doszkalania się w Ośrodkach Szkolenia Kierowców kierowców objętych kontrolnym sprawdzeniem kwalifikacji, o tyle spore wątpliwości budzi, co projektodawca rozumie pod pojęciem „szkolenia mającego na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem” i jaka jest relacja tego pojęcia do pojęcia „szkolenia w zakresie doskonalenia techniki jazdy”.  Należy wyraźnie podkreślić, że prowadzenie ośrodka doskonalenia techniki jazdy stanowi działalność regulowaną. Ustawodawca w art. 114 Ustawy przewidział szereg warunków, które spełnić musi przedsiębiorca, aby móc prowadzić ośrodek doskonalenia techniki jazdy. Nadto, w art. 117 Ustawy przewidziano szereg warunków, których spełnienie pozwala uzyskać uprawnienia instruktora techniki jazdy. Wymagania przewidziane dla ośrodków szkolenia kierowców (art. 28 Ustawy) oraz dla instruktorów (art. 33 Ustawy) są zgoła \\fodmienne od tych określonych w zdaniu poprzedzającym, które przewidziane są dla ośrodków doskonalenia techniki jazdy oraz zatrudnionych tam instruktorów.   Z powyższego jednoznacznie wynika, że ośrodki szkolenia kierowców oraz instruktorzy nie są przygotowani do prowadzenia wysoko specjalistycznych szkoleń i kursów z bezpiecznej jazdy, w szczególności obejmujących kontrolowaną utratę przyczepności, destabilizację toru jazdy pojazdu, hamowanie na nawierzchniach o zróżnicowanej przyczepności lub opanowanie pojazdu w sytuacji poślizgu, ecodrivingu. Do prowadzenia tego rodzaju działalności niezbędna jest określona infrastruktura oraz umiejętności, których ustawodawca nie wymaga dotychczas od ośrodków szkolenia kierowców oraz instruktorów ani także nie przewiduje ich w ramach przedmiotowej nowelizacji. Mając zaś na względzie niejednoznaczną relację między pojęciami „szkolenia mającego na celu doskonalenie umiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem” oraz „szkolenia w zakresie doskonalenia techniki jazdy”, zachodzi realne ryzyko otwarcia ośrodkom szkolenia kierowców możliwości prowadzenia specjalistycznych szkoleń, których prowadzenie dotychczas było reglamentowane i przewidziane wyłącznie dla podmiotów wyspecjalizowanych i do tego przygotowanych.   W tym zakresie wypada wskazać, że postulowana zmiana nie spełnia kryteriów określoności przepisów prawa, przewidzianych przez przepisy prawa powszechnie obowiązującego, a doprecyzowanych przez orzecznictwo sądowe. Nie sposób bowiem prima facie ani nawet po głębszej lekturze postulowanej zmiany, wywnioskować, jaka była intencja prawodawcy w zakresie zwiększenia uprawnień ośrodków szkolenia kierowców. Tego rodzaju przepisy prawa winny być na tyle szczegółowe i precyzyjne, aby nie było wątpliwości, jakie dodatkowe uprawnienia zostały danemu podmiotowi przyznane, w szczególności w porównaniu z innymi podmiotami, które dotychczas danymi uprawnieniami (lub analogicznymi) już dysponują. Wymaga to, w obecnym stanie projektowanej regulacji, gruntownej zmiany i doprecyzowania przepisu, który w zaproponowanym brzmieniu znacznie rozszerza uprawnienia ośrodków szkolenia kierowców o nieokreślone elementy.   Powyższe rozwiązanie budzi również wątpliwości natury formalnej z uwagi na to, że uzasadnienie Projektu ustawy w żadnym stopniu nie odnosi się do rozwiązania określonego w art. 1 pkt 28 Projektu ustawy. Uzasadnienie odbiega więc od standardów przewidzianych \\fwłaściwymi przepisami prawa dla uzasadnienia aktu normatywnego, jakim jest ustawa. Ocena Skutków Regulacji również abstrahuje od proponowanego w tym zakresie rozwiązania. Gdyby więc rozwiązanie przyjęte zostało w obecnym kształcie, to nie sposób byłoby nawet odczytać intencję projektodawcy bowiem nie została ona w żadnym miejscu wyrażona. Naraża to adresatów pierwotnych i wtórnych na dalej idące problemy związane ze stosowaniem prawa, w szczególności w zakresie potencjalnej odpowiedzialności podmiotów prowadzących tego rodzaju szkolenia specjalistyczne.   Mając na względzie powyższe, wnosimy o usunięcie projektowanej zmiany, określonej w art. 1 pkt 28 Projektu ustawy albo o pozostawienie ośrodkom szkolenia kierowców wyłącznie uprawnienia do kontrolnego sprawdzenia kwalifikacji, do czego ośrodki te są w sposób wystarczający przygotowane. Pozwoli to na zachowanie spójności systemu prawa, a także zabezpieczy interesy korzystających ze szkoleń specjalistycznych, w tym ich bezpieczeństwo, a więc również wpłynie na zabezpieczenie interesu ogólnego. Projektowany przepis wymaga ponownego przemyślenia i niezbędnego doprecyzowania.  \\t\\n\\tArt. 1 pkt 28 projektu ustawy\\tPolski Związek Szkoleniowy\\t14) W odniesieniu do art. 1 pkt 28 w naszej ocenie rozwiązanie to jest jak najbardziej oczekiwane przez środowisko. Jednak do właściwego działania niezbędna jest zmiana przepisów art. 55 ustawy – Prawo o ruchu drogowym tak aby osoba szkolona, a nie tylko ubiegająca się o uprawnienia do kierowania pojazdami miała możliwość kierowania pojazdem na którym znajduje się tablica „L”. Propozycje zapisów w tym zakresie przedstawimy w dalszej części pisma.  \\t\\n\\tArt. 1 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 2)\\tZwracam się do Państwa jako osoba zainteresowana kształtem nadchodzących zmian w przepisach dotyczących szkolenia i egzaminowania kierowców. Chciałabym przedstawić swoje stanowisko oraz konstruktywne uwagi dotyczące projektowanych regulacji, które budzą moje wątpliwości w kontekście ich realnego wpływu na bezpieczeństwo ruchu drogowego oraz jakość kształcenia. ​Moje zastrzeżenia dotyczą następujących kwestii: ​Egzaminy wewnętrzne: Wprowadzenie obligatoryjnych egzaminów wewnętrznych budzi wątpliwości natury etycznej i finansowej. Istnieje ryzyko, że staną się one dla \\fośrodków szkolenia kierowców jedynie dodatkowym źródłem zarobku, zamiast pełnić funkcję realnej weryfikacji wiedzy. Czy ośrodki szkolenia będą ponosić odpowiedzialność finansową, jeśli kursant po pozytywnym zaliczeniu egzaminu wewnętrznego nie zda egzaminu państwowego w WORD? ​Termin ważności egzaminu teoretycznego: Uważam, że egzamin teoretyczny powinien pozostać bezterminowy. Obecne przepisy nie przewidują obowiązku ponownego egzaminowania kierowców posiadających już uprawnienia przy każdej aktualizacji przepisów, dlatego nakładanie takiego obowiązku wyłącznie na kandydatów jest niesprawiedliwe. ​System szkolenia i liczba godzin: Zwiększenie liczby godzin szkolenia (np. z 30 do 50) powinno iść w parze z jakością, a nie tylko ilością. Postuluję położenie większego nacisku na naukę praktycznych umiejętności, takich jak tankowanie pojazdu czy jazda w warunkach dróg szybkiego ruchu. Rozważyłabym również umożliwienie doszkalania się pod okiem doświadczonych kierowców, co pozwoliłoby na nabycie cennej praktyki. ​Przygotowanie pojazdu do jazdy: Wymóg szczegółowego sprawdzania stanu technicznego pojazdu (poziomu płynów eksploatacyjnych) na egzaminie uważam za nieadekwatny do realiów użytkowania samochodów przez przeciętnych kierowców i nie wpływający bezpośrednio na bezpieczeństwo podczas jazdy egzaminacyjnej. ​Sankcje za niezdane egzaminy: Obowiązek odbycia dodatkowych godzin doszkalających po trzech niezdanych egzaminach, bez jednoczesnej gwarancji jakości szkolenia w ośrodku, przerzuca ciężar niepowodzenia wyłącznie na kursanta. ​Podsumowując, uważam, że reforma powinna skupić się na realnym podniesieniu standardów szkolenia praktycznego, a nie na mnożeniu formalnych barier, które nie rozwiązują problemu jakości nauczania.\\t\\n\\tArt. 2 projektu ustawy\\tZarząd Dróg Miejskich Warszawa\\t Zarządca ruchu wyznaczy miejsca postoju pojazdów mikromobilności dzielonej W ustawie z dnia 21 marca 1985 r. o drogach publicznych proponujemy dodanie nowego art. 12c, zgodnie z którym organ właściwy do zarządzania ruchem, wyznaczałby miejsca do postoju hulajnóg elektrycznych, motorowerów, urządzeń transportu osobistego i rowerów. Dodatkowo (opcjonalnie) nowy art. 12c mógłby określać, że zarządca drogi może wymagać uzyskania jego zgody na wykonywanie postoju w takich miejscach przez pojazdy mikromobilności dzielonej. \\fBrzmienie proponowanego artykułu: „art. 12 c. 1. Organ właściwy do zarządzania ruchem na drogach wyznacza miejsca, na których dopuszczony jest postój pojazdów mikromobilności dzielonej. 2. Postój pojazdów mikromobilności dzielonej na miejscach, o których mowa w ust. 1. wymaga uzyskania przez podmiot realizujący usługę mikromobilności dzielonej zezwolenia zarządcy drogi, wydanego na wyznaczony okres, w drodze decyzji administracyjnej.” \\t\\n\\tArt. 2 projektu ustawy\\tLime Technology sp. z o.o.\\t● Art. 2 projektu ustawy – art. 20 pkt 21 ustawy o drogach publicznych:   Projekt przyznaje zarządcy drogi kompetencję do wyznaczania miejsc przeznaczonych do postoju pojazdów i urządzeń udostępnianych w ramach mikromobilności.   Proponowany art. 20 pkt 21 mógłby otrzymać następujące brzmienie:  „21) wyznaczanie i oznakowanie, na zasadach określonych w porozumieniu, o którym mowa w art. 47 ust. 3a ustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym, miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego udostępnianych w ramach mikromobilności współdzielonej, w liczbie, o pojemności i rozmieszczeniu odpowiadających lokalnemu zapotrzebowaniu, natężeniu ruchu, sposobowi zagospodarowania terenu”.  Zmiana zachowałaby kompetencję zarządcy drogi do wyznaczania miejsc parkingowych, nakładając jednocześnie obowiązek zapewnienia ich w liczbie, pojemności i rozmieszczeniu umożliwiających rzeczywiste przestrzeganie zasad obowiązkowego parkowania.\\t\\n\\tArt. 2 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 3)\\nczłonek Wielkopolskiego Stowarzyszenia Niewidomych \\tjako osoba niewidoma i członek Wielkopolskiego Stowarzyszenia Niewidomych, wyrażam zdecydowane poparcie dla wprowadzenia obowiązku pozostawiania pojazdów mikromobilności dzielonej wyłącznie w miejscach wyznaczonych przez zarządcę drogi. Nieprawidłowo pozostawione hulajnogi i rowery stanowią dla osób niewidomych i słabowidzących nieprzewidywalne, trudne do wykrycia przeszkody. Mogą powodować potknięcia, upadki, konieczność wejścia na jezdnię oraz ograniczać możliwość samodzielnego i bezpiecznego poruszania się. \\fProjekt trafnie rozpoznaje ten problem w uzasadnieniu i ocenie skutków regulacji. Proponuję jednak uzupełnienie tekstu ustawy o następujące rozwiązania: Uzupełnienie projektowanego art. 20 pkt 21 ustawy o drogach publicznych o obowiązek wyznaczania miejsc postoju z uwzględnieniem zasad projektowania uniwersalnego, potrzeb osób ze szczególnymi potrzebami oraz konieczności zachowania ciągłej i wolnej od przeszkód drogi dla pieszych. Proponowane brzmienie:\\n„21) wyznaczanie, z uwzględnieniem zasad projektowania uniwersalnego, potrzeb osób ze szczególnymi potrzebami oraz konieczności zachowania ciągłej i wolnej od przeszkód drogi dla pieszych, miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach (…)”. 2. Dodanie obowiązku stosowania przez operatorów rozwiązań technicznych uniemożliwiających zakończenie korzystania z pojazdu poza wyznaczonym miejscem. Proponowane brzmienie:\\n„Podmiot świadczący usługę mikromobilności dzielonej jest obowiązany zapewnić rozwiązania techniczne uniemożliwiające zakończenie korzystania z pojazdu lub urządzenia poza miejscem wyznaczonym przez zarządcę drogi”. Określenie minimalnych wymagań dotyczących lokalizacji i oznakowania miejsc postojowych. Miejsca te nie powinny znajdować się na ścieżkach prowadzących i polach uwagi, przy przejściach dla pieszych, przystankach, wejściach do budynków ani w sposób ograniczający wymaganą wolną szerokość drogi dla pieszych. Zobowiązanie operatorów do zapewnienia dostępnego cyfrowo i telefonicznie sposobu zgłaszania źle pozostawionych pojazdów oraz do ich niezwłocznego usuwania.\\t\\n\\tArt. 2 projektu ustawy\\tPolski Związek Niewidomych\\t1. Zapewnienie dostępności miejsc wyznaczanych przez zarządcę drogi Aktualna propozycja zawarta w UD402 \\fArt. 2 projektu przewiduje dodanie w art. 20 ustawy o drogach publicznych pkt 21 w brzmieniu: „21) wyznaczanie miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego udostępnianych w ramach mikromobilności dzielonej, w rozumieniu art. 2 pkt 47d ustawy z dnia 20 czerwca 1997 roku – Prawo o ruchu drogowym.”. Projekt przyznaje zarządcy drogi kompetencję do wyznaczania miejsc postojowych, ale nie wskazuje zasad, według których kompetencja ta ma być wykonywana. Propozycja PZN W art. 2 projektu UD402 projektowanemu art. 20 pkt 21 ustawy o drogach publicznych proponuje się nadać następujące brzmienie: „21) wyznaczanie miejsc przeznaczonych do postoju pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego udostępnianych w ramach mikromobilności dzielonej, w rozumieniu art. 2 pkt 47d ustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym, w sposób zapewniający bezpieczeństwo i dostępność ruchu pieszych, w tym ciągłość trasy wolnej od przeszkód.”. Uzasadnienie Projekt ma służyć poprawie dostępności przestrzeni publicznej. Cel ten powinien wynikać z samego przepisu, a nie wyłącznie z uzasadnienia i OSR. Bez proponowanego uzupełnienia miejsce może zostać formalnie wyznaczone na trasie wykorzystywanej przez pieszych, przy elewacji stanowiącej naturalną linię prowadzącą albo w sąsiedztwie oznaczeń fakturowych. Odwołanie do wcześniejszego opracowania Problem został wskazany w opracowaniu z 18 sierpnia 2025 r., w rozdziale II pkt 1 dotyczącym zasad parkowania hulajnóg. Postulowano tam ochronę ciągu pieszego, \\fnaturalnych linii prowadzących oraz przestrzeni potrzebnej osobom niewidomym i słabowidzącym. \\t\\n\\tArt. 2 projektu ustawy\\tPolski Związek Niewidomych\\t4. Jednolite warunki lokalizowania i oznaczania miejsc postojowych Aktualna propozycja zawarta w UD402 Projekt nie zawiera przepisów określających: sposób lokalizowania miejsc postojowych, wymaganą szerokość dostępnego przejścia, ochronę oznaczeń fakturowych, relację strefy do naturalnych linii prowadzących, sposób oznaczenia granic miejsca, zasady sytuowania miejsc przy przejściach, przystankach i wejściach do budynków, sposób zabezpieczenia przed przewracaniem się urządzeń. Projekt posługuje się jedynie pojęciem miejsca „wyznaczonego przez zarządcę drogi”. Propozycja PZN W art. 2 projektu UD402 proponuje się dodać zmianę ustanawiającą w ustawie o drogach publicznych upoważnienie ustawowe w następującym brzmieniu: „Minister właściwy do spraw transportu określi, w drodze rozporządzenia, szczegółowe warunki lokalizowania, wyznaczania i oznaczania miejsc, o których mowa w art. 20 pkt 21, mając na uwadze konieczność zapewnienia bezpieczeństwa i dostępności ruchu pieszych, zachowania ciągłości trasy wolnej od przeszkód, ochrony oznaczeń fakturowych i naturalnych linii prowadzących, bezpieczeństwa dojść do przejść dla pieszych, przystanków i wejść do budynków oraz zapobiegania przewracaniu się pojazdów i ich wystawaniu poza granice miejsca postoju.”. Uzasadnienie \\fBez jednolitych zasad zarządcy dróg mogą stosować rozwiązania całkowicie odmienne, w tym miejsca wyznaczane wyłącznie za pomocą namalowanych linii, bez ochrony dostępnej części chodnika i zabezpieczenia przed wystawaniem urządzeń. Szczegółowe wymagania mają charakter techniczny i powinny zostać określone w rozporządzeniu. Delegacja ustawowa powinna jednak precyzyjnie wskazywać cel i zakres regulacji. Odwołanie do wcześniejszego opracowania Nasze opracowanie z 18 sierpnia 2025 r. zawierało postulaty dotyczące szerokości dostępnego ciągu pieszego, lokalizowania stref poza podstawową trasą ruchu osób niewidomych oraz czytelnego wyznaczania ich granic. \\t\\n\\tArt. 2 \\tPolski Związek Niewidomych\\tProjekt nakłada obowiązek prawidłowego postoju na użytkownika, ale nie określa obowiązków przedsiębiorcy organizującego usługę. Tymczasem operator: decyduje o sposobie działania aplikacji, posiada dane o lokalizacji urządzeń, określa warunki zakończenia najmu, ustala i stosuje własne sankcje regulaminowe, organizuje relokację floty, osiąga przychody z udostępniania urządzeń. OSR wskazuje, że operatorzy będą musieli dostosować floty i aplikacje, a skuteczność regulacji zależy od technicznego powiązania zakończenia najmu z miejscem wyznaczonym. Nie znajduje to jednak odzwierciedlenia w proponowanych przepisach.  \\t\\n\\tArt. 2\\tPolski Związek Niewidomych\\t9. Przekazywanie danych zarządcy drogi Aktualna propozycja zawarta w UD402 \\fProjekt nie zobowiązuje operatorów do przekazywania zarządcom dróg informacji pozwalających ocenić skuteczność systemu parkowania. Nie określa także organu odpowiedzialnego za sprawdzanie, czy prywatne sankcje regulaminowe są rzeczywiście stosowane. Propozycja PZN W art. 2 projektu UD402 proponuje się dodać w ustawie o drogach publicznych po projektowanym pkt 21 kolejny punkt w brzmieniu: „22) kontrolowanie wykonywania przez operatorów mikromobilności dzielonej obowiązków dotyczących postoju, zgłaszania i usuwania pojazdów oraz pozyskiwanie od operatorów zagregowanych danych niezbędnych do oceny skuteczności wykonywania tych obowiązków.”. Ponadto proponuje się dodać w Prawie o ruchu drogowym przepis: „Operator mikromobilności dzielonej przekazuje zarządcy drogi, na jego żądanie, zagregowane dane dotyczące liczby zgłoszeń nieprawidłowego postoju, liczby przeprowadzonych relokacji, czasu reakcji na zgłoszenia, przypadków zakończenia korzystania poza miejscem wyznaczonym oraz przypadków nieprawidłowego ustawienia pojazdu.” Uzasadnienie Bez danych zarządca drogi nie będzie mógł ocenić, czy operator skutecznie egzekwuje zasady wobec użytkowników i czy stosowane przez niego środki mają charakter rzeczywisty, czy wyłącznie deklarowany. Dane powinny być zagregowane i nie powinny umożliwiać identyfikacji poszczególnych użytkowników.  \\t\\n\\t \\fArt. 2 i 3 projektu ustawy\\t Związek Pracodawców \\f„Transport i Logistyka Polska”\\t Ad. art. 2 i 3 projektu  \\fOceniając z formalnego punktu widzenia zaproponowane w art. 2 i 3 projektu rozwiązania, wątpliwości budzi wprowadzanie w art. 2 ustawy Prawo o ruchu drogowym (PoRD) definicji usługi wykonywanej w ramach komercyjnej działalności przedsiębiorców! Wykracza to poza zakres przedmiotowo-podmiotowy tego aktu prawnego i powinno być zrealizowane w ramach innych aktów prawnych określających rodzaje usług związanych z transportem i zasady ich wykonywania. Prawo o ruchu drogowym jest bowiem aktem prawnym regulującym zasady ruchu drogowego, uprawnienia organów związane z tym ruchem etc.  Odnosząc się z kolei do merytorycznego aspektu proponowanych rozwiązań, należy wskazać, że podjęta próba uregulowania niektórych kwestii dotyczących mikromobilności, powinna być oceniana z perspektywy spójności systemu transportowego. Mikromobilność współdzielona stanowi dziś uzupełniający element systemu transportu miejskiego. Obsługuje podróże, dla których komunikacja zbiorowa jest zbyt rzadka, a korzystanie z samochodu osobowego nie jest konieczne, w tym dojazdy do przystanków i węzłów przesiadkowych. Rola ta jest szczególnie istotna w dzielnicach, położonych na obrzeżach miast, gdzie transport „pierwszej i ostatniej mili\\\" ułatwia mieszkańcom dotarcie do pracy czy szkoły, a pośrednio odciąża zarówno linie transportu zbiorowego, jak i układ drogowy. Regulacje dotyczące zasad postoju tych pojazdów, powinny być zatem projektowane tak, aby nie ograniczać faktycznej dostępności tej formy przemieszczania się.  W tym kontekście zwracamy uwagę, że realizacja celów projektu zależy, co zostało dostrzeżone w jego uzasadnieniu, od odpowiedniego zaprojektowania przez zarządców dróg sieci miejsc postoju, w tym ich rozmieszczenia w lokalizacjach faktycznie dostępnych i dogodnych dla użytkowników. Praktyka ośrodków, w których sieć punktów postoju okazała się zbyt rzadka, wskazuje, że jej niedostateczna dostępność skutkuje pozostawianiem pojazdów poza strefami, i w efekcie podważa cele, którym regulacja ma służyć. Jeżeli obowiązek miałby zostać utrzymany, to zasadne byłoby, aby ustawa lub akty wykonawcze określały standardy rozmieszczenia miejsc postoju gwarantujące ich realną dostępność dla użytkowników.  Pragniemy również podkreślić, że potrzeby transportowe poszczególnych obszarów są głęboko zróżnicowane. Zjawisko, którego dotyczy regulacja, koncentruje się w największych ośrodkach miejskich, co potwierdza sama ocena skutków regulacji, przewidująca, że nową kompetencję będzie aktywnie wykonywać jedynie niewielka część zarządców dróg, objętych przepisem. Potrzeby przewozowe zdecydowanej większości gmin kształtują się odmiennie niż w metropoliach i rozwiązania ustawowe powinny tę odmienność respektować. Jeszcze \\finna jest specyfika gmin o charakterze turystycznym, gdzie popyt na mikromobilność pojawia się skokowo, wraz z sezonowym szczytem przyjazdów, gdy lokalna komunikacja zbiorowa pracuje na granicy przepustowości. W tych warunkach usługi współdzielone przejmują część ruchu, pełniąc funkcję sezonowego bufora.  Zwracamy ponadto uwagę, że operatorzy prowadzą działalność w znacznej mierze na podstawie porozumień z jednostkami samorządu terytorialnego, w ramach których uzgadniane są zasady postoju pojazdów, obszary wyłączone z użytkowania oraz ograniczenia prędkości - z uwzględnieniem charakteru poszczególnych obszarów, natężenia ruchu i lokalnych potrzeb przewozowych. Model ten sprawdza się, ponieważ pozwala różnicować reguły tam, gdzie różnicują się realne potoki ruchu, zamiast stosować jednolite rozwiązanie na obszarze całej gminy. Powszechny obowiązek ustawowy nakładałby się na te rozwiązania i mógłby naruszyć ustalenia wypracowane lokalnie, a w okresie dostosowawczym, którego długość przewidziana w projekcie budzi nasze wątpliwości, prowadzić do zakłóceń w dostępności usług.  \\tMając na uwadze powyższe, proponujemy zastąpienie projektowanego art. 47 ust. 3a PoRD przepisem zobowiązującym operatora mikromobilności współdzielonej do uregulowania zasad postoju pojazdów w porozumieniu zawieranym z właściwą jednostką samorządu terytorialnego. Określenie w ustawie minimalnego zakresu takiego porozumienia zapewniłoby jednolitość ram prawnych, a jednocześnie pozwoliło dopasować rozwiązania do realnych potrzeb przewozowych poszczególnych obszarów.\\t\\n\\t Art. 3 pkt 2 projektu ustawy\\t Lime Technology sp. z o.o.\\t ● Art. 3 pkt 2 projektu ustawy - art. 47 ust. 3a-3c ustawy - Prawo o ruchu drogowym:  Obecne brzmienie projektu nakłada na użytkownika obowiązek zakończenia postoju wyłącznie w miejscu wyznaczonym przez zarządcę drogi, nie uzależniając stosowania tego obowiązku od wcześniejszego utworzenia odpowiedniej sieci miejsc parkingowych ani od uzgodnienia zasad funkcjonowania strefy z operatorami.  Zamiast projektowanego art. 47 ust. 3a proponuje się wprowadzenie następujących przepisów:   „3a. Zarządca drogi, przed wprowadzeniem obowiązku, o którym mowa w ust. 3b, zawiera z podmiotami świadczącymi na danym obszarze usługę mikromobilności współdzielonej porozumienie określające w szczególności obszar obowiązywania obowiązku parkowania, \\flokalizację, liczbę, pojemność i sposób oznakowania miejsc parkingowych; termin rozpoczęcia obowiązywania nowych zasad; zakres obowiązków zarządcy drogi i podmiotów świadczących usługę mikromobilności współdzielonej; zasady monitorowania funkcjonowania strefy oraz wprowadzania zmian wynikających z lokalnych potrzeb.   3aa. Porozumienie, o którym mowa w ust. 3a, powinno przewidywać możliwość przystąpienia do niego na równych i niedyskryminujących zasadach przez podmiot zamierzający rozpocząć świadczenie usługi mikromobilności współdzielonej na obszarze objętym tym porozumieniem. Podmiot ten jest obowiązany przystąpić do porozumienia przed rozpoczęciem świadczenia usługi na tym obszarze   3b. Na obszarze i od dnia określonego w porozumieniu, o którym mowa w ust. 3a, po wyznaczeniu i oznakowaniu właściwych miejsc parkingowych, osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rower, hulajnogę elektryczną lub urządzenie transportu osobistego udostępnione w ramach mikromobilności współdzielonej, jest zobowiązana pozostawić ten pojazd lub urządzenie wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę drogi.   3c. Do czasu zawarcia porozumienia, o którym mowa w ust. 3a, oraz wyznaczenia i oznakowania właściwych miejsc parkingowych, a także poza obszarem objętym takim porozumieniem, do parkowania pojazdów i urządzeń udostępnianych w ramach mikromobilności współdzielonej nie stosuje się ust. 3a do 3b.”.   W takim modelu obowiązek parkowania nadal wynikałby bezpośrednio z ustawy. Porozumienie określałoby natomiast jego terytorialny i operacyjny zakres oraz moment rozpoczęcia stosowania. Mogłoby ono obejmować całą gminę albo jedynie określone strefy, w których obowiązkowe parkowanie jest uzasadnione lokalnymi warunkami.  Jeżeli zarządca drogi nie zawrze porozumienia lub nie wyznaczy i nie oznakuje odpowiednich miejsc parkingowych, nadal obowiązywałyby ogólne zasady parkowania.\\t\\n\\t Art. 3 pkt 3 projektu ustawy\\t Ogólnopolski Związek Wojewódzkich \\fOśrodków Ruchu Drogowego\\t W art. 3 po pkt. 3 proponujemy dodać pkt 4 w brzmieniu: 1)  w art. 119 ust. 3 uchyla się pkt 4. 2)  art. 119 ust. 4 otrzymuje brzmienie: \\f„4. Ośrodek ponosi wydatki na działania na rzecz poprawy bezpieczeństwa ruchu drogowego na obszarze województwa, w szczególności na popularyzację zasad ruchu drogowego oraz podnoszenie kultury jazdy kierowców”. 3)   po ust. 4 dodaje się ust. 4a w brzmieniu: „4a. Wydatki, o których mowa w ust. 4, mogą być finansowane ze środków zgromadzonych na funduszu zapasowym ośrodka. Przeznaczenie środków funduszu zapasowego następuje z zachowaniem zdolności ośrodka do terminowego wykonywania jego zobowiązań.”  Uzasadnienie do pkt. 13  Projektowana zmiana ma na celu zwiększenie efektywności wykorzystania środków finansowych zgromadzonych przez wojewódzkie ośrodki ruchu drogowego oraz wzmocnienie realizacji ustawowych zadań związanych z poprawą bezpieczeństwa ruchu drogowego. Obecne przepisy, które określają szczegółowe warunki gospodarki finansowej wojewódzkich ośrodków ruchu drogowego są zawarte w Rozporządzeniu Ministra Infrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376). Rozporządzenie to zastąpiło poprzednio obowiązujący akt, tj. Rozporządzenie Ministra Infrastruktury z dnia 2 października 2002 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. Nr 176, poz. 1443) i wprowadziło zmianę w zakresie przeznaczenia funduszu zapasowego. Zgodnie z treścią § 5 poprzednio obowiązującego Rozporządzenia, fundusz zapasowy był przeznaczony do dyspozycji ośrodka na finansowanie działalności, o której mowa w art. 117 ust. 1 i 2 ustawy - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251), a zatem również na potrzeby szeroko rozumianej działalności oświatowej dot. bezpieczeństwa w ruchu drogowym oraz realizacji innych, doniosłych zadań z zakresu tego bezpieczeństwa. Obecnie natomiast, zgodnie z aktualnym Rozporządzeniem, fundusz zapasowy może być przeznaczony jedynie na pokrycie strat netto ośrodka. W praktyce oznacza to, że środki zgromadzone w funduszu zapasowym pozostają niewykorzystane do czasu wystąpienia ujemnego wyniku finansowego, niezależnie od istniejących potrzeb w zakresie realizacji działań służących poprawie bezpieczeństwa ruchu drogowego. Jednocześnie działania na \\frzecz poprawy bezpieczeństwa ruchu drogowego stanowią jedno z podstawowych zadań wojewódzkich ośrodków ruchu drogowego, wynikających bezpośrednio z ustawy. Nie mają one charakteru działalności dodatkowej ani fakultatywnej, lecz pozostają integralnym elementem misji publicznej realizowanej przez te podmioty. Brak jest dostatecznego uzasadnienia dla utrzymywania stanu, w którym środki zgromadzone przez ośrodek pozostają zarezerwowane wyłącznie na pokrycie potencjalnych przyszłych strat, podczas gdy mogą zostać wykorzystane do realizacji ustawowych zadań służących ograniczaniu liczby wypadków drogowych, zwiększaniu świadomości uczestników ruchu drogowego oraz podnoszeniu poziomu bezpieczeństwa na drogach. Proponowane rozwiązanie wychodzi z założenia, że środki funduszu zapasowego powinny służyć nie tylko ochronie stabilności finansowej ośrodka, lecz również wspierać realizację celów publicznych, dla których wojewódzkie ośrodki ruchu drogowego zostały utworzone. Umożliwienie finansowania działań na rzecz bezpieczeństwa ruchu drogowego ze środków funduszu zapasowego pozwoli na bardziej racjonalne i efektywne gospodarowanie zgromadzonym majątkiem, przy jednoczesnym zachowaniu bezpieczeństwa finansowego jednostek. Powrót do finansowania wydatków, w części przeznaczonej na poprawę bezpieczeństwa ruchu drogowego z funduszu zapasowego, bez wątpienia umożliwiłby zwiększenie skuteczności i efektywności pomocy m.in. placówkom edukacyjno-oświatowym przygotowującym dzieci i młodzież do świadomego i bezpiecznego udziału w ruchu drogowym na terenie naszego kraju, a ponadto znacząco odciążyłby fundusz z bieżącej działalności ośrodków.  Projektowana regulacja nie zmienia charakteru funduszu zapasowego jako instrumentu wzmacniającego stabilność finansową ośrodka, lecz rozszerza katalog dopuszczalnych sposobów jego wykorzystania o finansowanie działań pozostających w bezpośrednim związku z ustawowymi zadaniami wojewódzkich ośrodków ruchu drogowego. Rozwiązanie \\nto zapewni możliwość przeznaczania wypracowanych przez ośrodki nadwyżek finansowych na cele służące interesowi publicznemu, bez konieczności oczekiwania na wystąpienie okoliczności uzasadniających pokrywanie strat. Należy jeszcze raz podkreślić, że finansowanie działań na rzecz poprawy bezpieczeństwa ruchu drogowego ze środków funduszu zapasowego nie stanowi przeznaczenia tych środków na cele niezwiązane z działalnością ośrodka. Przeciwnie, środki te byłyby wykorzystywane na realizację zadań ustawowo przypisanych wojewódzkim ośrodkom ruchu drogowego. Proponowana zmiana prowadzi zatem do silniejszego powiązania sposobu \\fwykorzystania wypracowanych nadwyżek finansowych z podstawowymi celami działalności ośrodków, \\na tym samym wzmacnia funkcjonalny związek pomiędzy gospodarką finansową ośrodka, \\na realizacją powierzonych mu zadań publicznych.  Do ew. wykorzystania:  Proponowane brzmienie przepisu Rozporządzenia Ministra Infrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376): Konsekwencją wprowadzenia powyższej zmiany do Ustawy - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251) jest dostosowanie obecnego brzmienia Rozporządzenia Ministra Infrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376). Rozporządzenie jako akt wykonawczy do ustawy nie może pozostawać z nią w sprzeczności, stąd konieczna jest modyfikacja treści § 5 Rozporządzenia. Wynika to z konstytucyjnej zasady zgodności rozporządzeń z ustawą. Wobec powyższego koniecznym jest także dokonanie zmiany § 5 ust. 2 ww. Rozporządzenia o proponowanej treści:   § 5 ust. 2 otrzymuje brzmienie: „Fundusz zapasowy jest przeznaczony na: 1. pokrycie strat netto ośrodka;  2. finansowanie wydatków na działania na rzecz poprawy bezpieczeństwa ruchu drogowego, o których mowa w art. 119 ust. 4 ustawy.” \\t\\n\\t Art. 3 projektu ustawy\\t Związek Powiatów Polskich\\t Jako organizacja reprezentująca środowisko przedsiębiorców przywiązujemy szczególną wagę do jakości stanowionego prawa, w tym do zasady proporcjonalności oraz adekwatności instrumentów regulacyjnych do skali zjawiska, którego dotyczą. W naszej ocenie projektowany, powszechny obowiązek zakończenia postoju pojazdów \\fmikromobilności dzielonej wyłącznie w miejscach wyznaczonych przez zarządcę drogi budzi w tym kontekście istotne wątpliwości. Z oceny skutków regulacji wynika, że kompetencję wyznaczania miejsc postoju będzie aktywnie wykonywać jedynie ok. 100–150 zarządców dróg spośród blisko 2 800 potencjalnie objętych przepisem. Oznacza to, że instrument o charakterze powszechnym projektowany jest w odpowiedzi na zjawisko występujące lokalnie, skoncentrowane w największych ośrodkach miejskich. Dobre praktyki legislacyjne nakazują w takiej sytuacji rozważenie rozwiązań o węższym, precyzyjnie określonym zakresie podmiotowym, na przykład ograniczonym do gmin o określonej liczbie mieszkańców, zamiast obejmowania obowiązkiem ogółu jednostek, w tym takich, w których zjawisko nie występuje, a zasoby administracyjne są ograniczone. Usankcjonowanie praktyki współpracy operatorów z samorządami  Zwracamy również uwagę, że regulacja nakładałaby się na rozwiązania funkcjonujące już w praktyce. Operatorzy usług współdzielonych prowadzą działalność w znacznej mierze na podstawie porozumień z jednostkami samorządu terytorialnego, których treść jest każdorazowo dostosowywana do lokalnych potrzeb i które określają m.in. zasady postoju udostępnianych pojazdów, obszary wyłączone z użytkowania oraz ograniczenia prędkości w miejscach intensywnego ruchu pieszego. Wprowadzenie powszechnego obowiązku ustawowego oznaczałoby konieczność ponownego wykonania pracy, która w znacznej mierze została już wykonana, i mogłoby naruszyć rozwiązania wypracowane lokalnie. Z perspektywy przedsiębiorców rodzi to również ryzyko niestabilności otoczenia prawnego dla podmiotów, które poniosły nakłady na dostosowanie działalności do ustaleń z samorządami, w tym w odpłatne tytuły prawne do gruntów wykorzystywanych jako strefy parkowania. Skutki finansowe i operacyjne proponowanych zmian Odrębnym zagadnieniem są koszty dostosowawcze i wykonalność regulacji w przewidzianym okresie przejściowym. Uzasadnienie projektu samo przyznaje, że skala niezbędnych prac po stronie zarządców dróg jest znaczna, a w największych miastach liczba wymaganych lokalizacji może sięgać kilku tysięcy. Równolegle, dostosowania wymagać będą systemy i umowy operatorów. W tych warunkach zasadne byłoby wydłużenie okresu przejściowego lub powiązanie momentu rozpoczęcia stosowania obowiązku z rzeczywistym utworzeniem sieci miejsc postoju w danej gminie. Sugerowany kierunek zmian  \\fMając na uwadze powyższe, postulujemy rozważenie zastąpienia powszechnego obowiązku określonego w projektowanym art. 47 ust. 3a ustawy – Prawo o ruchu drogowym rozwiązaniem alternatywnym, polegającym na wprowadzeniu ustawowego obowiązku zawarcia przez operatora mikromobilności współdzielonej porozumienia z właściwą jednostką samorządu terytorialnego, określającego zasady postoju udostępnianych pojazdów. Jednolitość ram prawnych można osiągnąć poprzez określenie minimalnej, obowiązkowej treści takich porozumień. Rozwiązanie to realizowałoby cele projektu przy istotnie niższych kosztach regulacyjnych i bez naruszania mechanizmów współpracy funkcjonujących już w praktyce. \\t\\n\\tArt. 3 projektu ustawy\\tAmerykańska Izba Handlowa w Polsce\\tAmCham popiera działania służące poprawie bezpieczeństwa pieszych, zachowaniu dostępności chodników oraz uporządkowaniu sposobu pozostawiania pojazdów. Obowiązkowe miejsca postojowe mogą być skutecznym rozwiązaniem, pod warunkiem że ich wprowadzenie będzie poprzedzone stworzeniem infrastruktury odpowiadającej rzeczywistym potrzebom mieszkańców i charakterystyce poszczególnych części miasta. Systemy mikromobilności współdzielonej od lat działają w wielu miastach Stanów Zjednoczonych. Amerykańskie doświadczenia i badania dotyczące funkcjonowania takich usług wskazują, że jednym z najważniejszych czynników decydujących o prawidłowym parkowaniu oraz wygodzie użytkowników jest odpowiednie zagęszczenie miejsc postojowych. Za efektywną uznaje się sieć umożliwiającą znalezienie parkingu mniej więcej co 200–250 metrów. Jeżeli odległości są większe, użytkownicy częściej rezygnują z prawidłowego zakończenia przejazdu, a sama usługa traci swoją podstawową zaletę tj. możliwość sprawnego dotarcia blisko miejsca docelowego. Szczególne znaczenie ma to w centrach miast, gdzie występują duże natężenie ruchu, ograniczona przestrzeń oraz częste konflikty między różnymi sposobami jej wykorzystania. To właśnie tam obowiązkowe parkowanie może najlepiej porządkować przestrzeń publiczną, o ile parkingi są widoczne, łatwo dostępne i rozmieszczone zgodnie z rzeczywistymi kierunkami przemieszczania się użytkowników. Zbyt rzadka sieć miejsc może natomiast powodować kumulowanie się pojazdów, utrudniać kończenie przejazdów i prowadzić do pozostawiania sprzętu poza wyznaczonymi punktami. \\fJednocześnie jednolite objęcie obowiązkowym parkowaniem całego obszaru miasta może nie odpowiadać jego zróżnicowanym potrzebom. W dzielnicach oddalonych od centrum hulajnogi i rowery współdzielone często pełnią funkcję dojazdu do przystanków, stacji kolejowych, szkół, uczelni i miejsc pracy. Na terenach o bardziej rozproszonej zabudowie stworzenie równie gęstej sieci fizycznie oznakowanych parkingów może być trudne i kosztowne. Ograniczenie możliwości zakończenia przejazdu wyłącznie do nielicznych punktów mogłoby w praktyce pozbawić mieszkańców dostępu do usługi oraz osłabić jej rolę jako uzupełnienia transportu publicznego. Dlatego za szczególnie ważne uznajemy zachowanie podejścia elastycznego i strefowego. Bardziej rygorystyczne zasady mogą być stosowane w centrach, przy węzłach komunikacyjnych i w miejscach wskazanych przez miasta jako problematyczne. Poza takimi obszarami powinny być możliwe rozwiązania dostosowane do lokalnych warunków, uwzględniające dotychczasowe zasady parkowania, rzeczywisty popyt oraz dostępność przestrzeni. Kluczowa pozostaje również współpraca zarządców dróg z operatorami. Firmy świadczące usługi mikromobilności dysponują danymi o trasach przejazdów, miejscach ich rozpoczynania i kończenia oraz obszarach o największym zapotrzebowaniu. Informacje te pozwalają właściwie zaplanować liczbę, lokalizację i pojemność parkingów. Operatorzy mogą także wspierać przestrzeganie zasad za pomocą geolokalizacji, komunikatów w aplikacji, blokowania możliwości zakończenia przejazdu w niewłaściwym miejscu oraz weryfikacji zdjęć zaparkowanych pojazdów. AmCham zwraca również uwagę na potrzebę proporcjonalności obowiązków, opłat i sankcji. Powinny one skutecznie przeciwdziałać naruszeniom, ale jednocześnie uwzględniać specyfikę lekkich pojazdów współdzielonych oraz rzeczywiste koszty ich usuwania i przechowywania. Nadmierne obciążenia mogą przełożyć się na wzrost cen dla użytkowników lub wycofywanie usługi z mniej rentownych dzielnic i mniejszych miast. W ocenie AmCham dalsze prace nad projektem powinny zmierzać w kierunku modelu, który: \\fzapewni odpowiednio gęstą i funkcjonalną sieć parkingów, zwłaszcza w centrach miast; pozostawi samorządom możliwość dostosowania zasad do lokalnych potrzeb; ochroni dostępność mikromobilności na obrzeżach i terenach słabiej obsługiwanych przez transport publiczny; oprze organizację systemu na współpracy i wymianie danych między miastami a operatorami. \\t\\n\\tArt. 3 projektu ustawy\\tKonfederacja Lewiatan\\t Uwagi w zakresie: art. 47 ust. 3a ustawy – Prawo o ruchu drogowym, wprowadzającym powszechny obowiązek zakończenia postoju pojazdów mikromobilności dzielonej wyłącznie w miejscach wyznaczonych przez zarządcę drogi, oraz na powiązanych zmianach w art. 130a tej ustawy.  Konfederacja Lewiatan z uznaniem odnosi się do działań ustawodawcy zmierzających do zwiększenia przejrzystości i bezpieczeństwa regulacyjnego rynku. Dotychczasowe zmiany przepisów w istotnym stopniu uporządkowały obowiązujące ramy prawne, a jednocześnie stworzyły uczestnikom rynku możliwość wypracowania dobrych praktyk w zakresie ich stosowania. Doświadczenia zebrane w okresie obowiązywania tych regulacji pozwalają dziś zidentyfikować rozwiązania, które sprawdziły się w praktyce, jak również obszary wymagające doprecyzowania. W ocenie Konfederacji Lewiatan obecna nowelizacja stanowi dobrą okazję do wzmocnienia wypracowanych dobrych praktyk, zwiększenia pewności prawa oraz wyeliminowania wątpliwości interpretacyjnych, przy jednoczesnym zachowaniu celów, które przyświecały wcześniejszym zmianom legislacyjnym wobec czego chcielibyśmy zasygnalizować na wstępie elementy, które - w naszej ocenie - budzą pewne wątpliwości.  Zwracamy uwagę na potrzebę oceny proponowanych co do relacji proponowanych rozwiązań do konstytucyjnych zasad pomocniczości i decentralizacji władzy publicznej. Organizacja transportu lokalnego, zagospodarowanie przestrzeni publicznej oraz organizacja ruchu drogowego należą do zadań własnych gmin (art. 7 ust. 1 pkt 1, 2 i 4 ustawy o samorządzie gminnym). Zgodnie z preambułą oraz art. 15 ust. 1 Konstytucji RP ustrój terytorialny Rzeczypospolitej opiera się na decentralizacji, a art. 165 ust. 2 Konstytucji RP gwarantuje ochronę samodzielności jednostek samorządu terytorialnego. Kierunek ten potwierdza Europejska Karta Samorządu Lokalnego, której art. 4 ust. 3 przewiduje, że \\fwykonywanie zadań publicznych powinno zasadniczo należeć do organów najbliższych obywatelom. Narzucenie w ustawie jednego, jednolitego modelu parkowania pojazdów mikromobilności, bez pozostawienia gminom realnej swobody wyboru innych skutecznych rozwiązań, stanowi w naszej ocenie ingerencję w sferę wymagającą uwzględnienia lokalnych uwarunkowań i może pozostawać w sprzeczności z powołanymi zasadami.  Ingerencja ta jest tym trudniejsza do uzasadnienia, że samorządy wypracowały już we współpracy z operatorami skuteczne instrumenty zarządzania mikromobilnością. Działalność operatorów prowadzona jest w znacznej mierze na podstawie porozumień z poszczególnymi jednostkami samorządu terytorialnego, których treść jest każdorazowo dostosowana do lokalnych potrzeb: wyznaczane są strefy obowiązkowego parkowania tam, gdzie jest to rzeczywiście uzasadnione, strefy ograniczonej prędkości w obszarach intensywnego ruchu pieszego oraz obszary całkowicie wyłączone z użytkowania. Ograniczenia te są egzekwowane nie za pomocą znaków czy kontroli na miejscu, lecz zdalnie, przy pomocy narzędzi technologicznych operatora, które uniemożliwiają np. zakończenie przejazdu poza wyznaczoną strefą. Wprowadzenie powszechnego obowiązku ustawowego dublowałoby zatem działania już podjęte przez administrację samorządową i mogłoby podważyć ustalenia funkcjonujące lokalnie.  Podkreślamy również, że sytuacja poszczególnych jednostek samorządu terytorialnego jest głęboko zróżnicowana i jednolite rozwiązanie ustawowe nie jest w stanie tego zróżnicowania uwzględnić. Skalę tego zróżnicowania obrazują dane przywołane w ocenie skutków regulacji: spośród blisko 2 800 zarządców dróg objętych projektowanym przepisem realne wykonywanie nowej kompetencji przewiduje się jedynie w przypadku około stu pięćdziesięciu z nich. Dla pozostałych jednostek obowiązek miałby zatem charakter w istocie pusty, albo generowałby obciążenia nieadekwatne do skali zjawiska na ich terenie. Odrębną kategorię stanowią gminy turystyczne, w których zapotrzebowanie na usługę zależy od sezonowego napływu turystów, a lokalne linie transportu zbiorowego są dodatkowo obciążone w miesiącach letnich. Jednocześnie projektowanie, dostosowanie i utrzymywanie stref postoju generuje koszty i potrzeby kadrowe, na które wiele mniejszych jednostek samorządu terytorialnego nie może sobie pozwolić. Nakładanie na wszystkie gminy obowiązku zaprojektowanego z myślą o realiach dużych ośrodków miejskich oznaczałoby przeniesienie na samorządy ciężarów nieproporcjonalnych do skali problemu na ich terenie. Mając na uwadze powyższe, postulujemy, aby w miejsce powszechnego obowiązku z projektowanego art. 47 ust. 3a ustawy – Prawo o ruchu drogowym ustawodawca zobowiązał \\foperatorów mikromobilności współdzielonej do zawarcia z właściwą jednostką samorządu terytorialnego porozumienia określającego zasady postoju udostępnianych pojazdów, pozostawiając gminom wypracowanie szczegółów stosownie do lokalnych uwarunkowań. Wskazywaną w ocenie skutków regulacji potrzebę jednolitości ram prawnych zaspokoiłoby ustawowe określenie obligatoryjnych elementów takiego porozumienia.\\t\\n\\t Art. 3 projektu ustawy\\t Polskie Stowarzyszenia Nowej Mobilności\\t  Działalność operatorów prowadzona jest obecnie w znacznej mierze na podstawie porozumień zawieranych z poszczególnymi jednostkami samorządu terytorialnego, których treść jest każdorazowo dostosowana do lokalnych potrzeb i specyfiki danej przestrzeni miejskiej. W ramach tych porozumień samorządy wskazują strefy, w których pojazd samoczynnie ogranicza prędkość, np. do 15 km/h, wyznaczane tam, gdzie ruch pieszy jest szczególnie intensywny, strefy wyłączone z użytkowania, obejmujące zwykle parki i tereny zielone, a także obszary obowiązkowego parkowania w miejscach, w których jest to rzeczywiście uzasadnione, czego przykładem jest obszar Starego Miasta w Warszawie. Wszystkie te ograniczenia są egzekwowane zdalnie, w czasie rzeczywistym, za pomocą systemów geofencingu, tj. elektronicznego wyznaczania granic obszarów w aplikacji mobilnej operatora. Model ten pozwala precyzyjnie różnicować zasady korzystania z mikromobilności w zależności od charakteru poszczególnych obszarów, natężenia ruchu i potrzeb mieszkańców. Powszechny obowiązek ustawowy oznaczałby dla samorządów i operatorów konieczność powtórnego przeprowadzenia procesu, który w wielu miastach został już zakończony i przynosi oczekiwane efekty.  Z doświadczeń operacyjnych wynika, że o powodzeniu każdego modelu opartego na wyznaczonych miejscach postoju decydują dwa czynniki: gęstość sieci oraz jej czytelne oznakowanie. Doświadczenia miast, w których punkty postoju rozmieszczone są zbyt rzadko, pokazują, że niedostępność stref prowadzi do frustracji użytkowników i nieprawidłowego parkowania. Równie istotna jest identyfikacja wizualna – praktyka wskazuje, że oznakowanie punktów postoju bywa nieadekwatne do potrzeb użytkowników, m.in. ze względu na słabą widoczność. Przykładem dobrze zaprojektowanego systemu stref jest Poznań, gdzie miejsca parkowania są wyraźnie wyodrębnione wizualnie i wyposażone w znaki pionowe, a przez to łatwe do zidentyfikowania zarówno przez mieszkańców, jak i turystów. Jeżeli obowiązek miałby zostać utrzymany, zasadne byłoby, aby ustawa lub akty wykonawcze określały mierzalne wymogi dotyczące gęstości i dostępności sieci miejsc postoju – w przeciwnym \\frazie nowy obowiązek może okazać się w praktyce niewykonalny dla użytkowników i prowadzić do faktycznego ograniczenia dostępności tej formy transportu.  Odrębnego rozważenia wymaga długość przewidzianego w projekcie okresu przejściowego. Uzasadnienie projektu przyznaje, że w większych miastach liczba wymaganych lokalizacji może sięgać kilkuset, a nawet kilku tysięcy, a ich wyznaczenie wymaga analiz potrzeb, oznakowania oraz uzgodnień konserwatorskich w obszarach zabytkowych. Równolegle operatorzy będą musieli przebudować systemy informatyczne, w tym mechanizmy geofencingu i blokady zakończenia przejazdu poza strefą, oraz aneksować umowy z samorządami. Istotne jest przy tym, że w obecnym modelu nierzadką sytuacją jest zawieranie umów, na podstawie których udostępniane są przestrzenie pod strefy parkowania. Wprowadzenie prawnego obowiązku wyznaczania takich miejsc mogłoby zakwestionować ten model, na którym oparte są obowiązujące umowy. Postuluje się w związku z tym wydłużenie okresu przejściowego albo uzależnienie stosowania obowiązku od faktycznego utworzenia sieci miejsc postoju na terenie danej gminy.  Warto jednocześnie zwrócić uwagę, że usługi współdzielonej mikromobilności funkcjonują dziś w ograniczonej liczbie ośrodków, przede wszystkim w największych miastach, i tam też koncentruje się zjawisko, na które odpowiada projekt, co znajduje potwierdzenie w ocenie skutków regulacji. Obejmowanie powszechnym obowiązkiem także gmin, w których usługa nie jest i w przewidywalnej przyszłości nie będzie świadczona, nie przybliża realizacji celów regulacji. Zakres podmiotowy obowiązku powinien uwzględniać tę koncentrację oraz zróżnicowanie sytuacji poszczególnych jednostek samorządu terytorialnego, w tym gmin turystycznych, w których zapotrzebowanie na usługę ma charakter sezonowy.   W związku z powyższym wnosi się o rozważenie zastąpienia powszechnego obowiązku określonego w projektowanym art. 47 ust. 3a ustawy – Prawo o ruchu drogowym rozwiązaniem alternatywnym, polegającym na wprowadzeniu ustawowego obowiązku zawarcia przez operatora mikromobilności współdzielonej porozumienia z właściwą jednostką samorządu terytorialnego, określającego zasady postoju udostępnianych pojazdów. Jednolitość ram prawnych, wskazywaną w ocenie skutków regulacji jako zaletę projektu, można osiągnąć poprzez określenie minimalnej, obowiązkowej treści takich porozumień. Rozwiązanie to nadałoby ramę ustawową modelowi współpracy, który nasi członkowie z powodzeniem stosują w praktyce.\\t\\n\\tArt. 3 projektu ustawy\\temTransit  sp. z o.o.\\tSpołka co do zasady popiera cel Projektu, jakim jest uporządkowanie zasad postoju pojazdow mikromobilności dzielonej w przestrzeni publicznej, jednocześnie jednak zwraca uwagę, że część projektowanych rozwiązań - w obecnym brzmieniu - może wywołać skutki odwrotne do zamierzonych i w praktyce utrudnić świadczenie usług mikromobilności dzielonej w części gmin.  Społka pozytywnie ocenia wprowadzenie do ustawy - Prawo o ruchu drogowym definicji mikromobilności dzielonej (projektowany art. 2 pkt 47d) oraz przyznanie zarządcom drog wyraźnej kompetencji do wyznaczania miejsc postoju pojazdow mikromobilności dzielonej (projektowany art 20 pkt 21 ustawy o drogach publicznych). Rozwiązania te odpowiadają wypracowanej już praktyce wspołpracy Operatorow z miastami i zasługują na poparcie co do kierunku. Zasadnicze zastrzeżenia Społki budzi natomiast konstrukcja obowiązku postoju wyłącznie w miejscach wyznaczonych (projektowany art. 47 ust. 3a) w powiązaniu z sankcją usunięcia pojazdu z drogi (projektowany art. 130a ust. 1 pkt 8 oraz ust. 6a lit. i). Uwagi w tym zakresie przedstawiamy poniżej.\\t\\n\\tArt. 3 pkt 2 projektu ustawy\\temTransit  sp. z o.o.\\tIII. Uwaga zasadnicza: projektowany art. 130a ust 1 pkt 8 w związku z art 47 ust 3a ustawy - Prawo o ruchu drogowym 1. Istota problemu - obowiązek bez gwarancji infrastruktury. Projektowany art. 47 ust. 3a nakłada na użytkownika bezwzględny obowiązek zakończenia postoju „wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę drogi”, a projektowany art. 130a ust. 1 pkt 8 przewiduje usunięcie pojazdu pozostawionego poza takim miejscem. Projekt nie nakłada jednak na zarządcę drogi żadnego obowiązku wyznaczenia takich miejsc, nie określa ich minimalnej gęstości ani trybu ich uzgadniania z Operatorami - wyznaczanie miejsc pozostaje wyłącznie uprawnieniem zarządcy drogi (projektowany art. 20 pkt 21 ustawy o drogach publicznych). Przepis nie precyzuje jednak, jak należy interpretować sytuację, w ktorej na danym obszarze zarządca drogi nie wyznaczył jeszcze żadnych miejsc postojowych albo wyznaczył je w liczbie lub lokalizacjach nieodpowiadających rzeczywistym potrzebom użytkownikow. Bez takiego doprecyzowania nie można wykluczyć interpretacji, zgodnie z ktorą każdorazowe zakończenie przejazdu na takim obszarze stanowiłoby naruszenie art. 47 ust. 3a i podstawę usunięcia pojazdu na koszt Operatora (200 zł za usunięcie oraz 50 zł za każdą dobę \\fprzechowywania). W takim ujęciu o możliwości faktycznego prowadzenia działalności gospodarczej na danym obszarze decydowałaby nie ustawa, lecz tempo działania zarządcy drogi w zakresie wyznaczania miejsc postojowych, co w skrajnym przypadku mogłoby prowadzić do wyłączenia usług mikromobiiności dzielonej w części kraju. Niezależnie od tego, ktorą interpretację ostatecznie przyjęto by w praktyce stosowania przepisu, sama ta niejednoznaczność rodzi po stronie Operatorow istotną niepewność co do warunkow prowadzenia działalności w poszczegolnych gminach, a w konsekwencji utrudnia podejmowanie decyzji inwestycyjnych i operacyjnych. Z tego względu Społka postuluje jednoznaczne doprecyzowanie przepisu w kierunku wskazanym w pkt. 3 poniżej, co pozwoli uniknąć niepewności, utrudniające prowadzenie działalności gospodarczej w tym zakresie. 2. Nieproporcjonalność sankcji i pominięcie możliwości technicznych Operatorow. Usunięcie pojazdu przez podmiot wyznaczony przez starostę jest środkiem najdalej idącym i najbardziej kosztownym, podczas gdy Operatorzy - w odrożnieniu od właścicieli pojazdow indywidualnych, dysponują narzędziami pozwalającymi usunąć nieprawidłowość niezwłocznie i bez angażowania środkow publicznych: dzięki wbudowanemu w każdym pojeżdzie systemowi GPS, Operatorzy mają podgląd co do lokalizacji jej floty, a lokalne zespoły serwisowe, ktorych zadaniem jest m.in, relokacja pojazdow, działają w trybie ciągłym. Projekt nie przewiduje jednak żadnego trybu uprzedniego wezwania Operatora do relokacji pojazdu. W rezultacie środek publicznoprawny staje się środkiem pierwszego wyboru, generującym koszty po stronie Operatorow i obciążenia organizacyjne po stronie powiatow, mimo że ten sam skutek (usunięcie pojazdu z miejsca niedozwolonego) Operatorzy mogą osiągnąć szybciej i bez kosztow publicznych. 3. Propozycja Społki - ustawowy mechanizm porozumień z zarządcami drog oraz gwarancja odpowiedniej gęstości miejsc postojowych. Społka proponuje oparcie projektowanego mechanizmu na sprawdzonym modelu funkcjonującym obecnie m.in. w Warszawie, Poznaniu, Krakowie i Gdańsku, tj. na umowach (porozumieniach) zawieranych pomiędzy zarządcą drogi (miastem) a Operatorami. Proponujemy, aby: - obowiązek zakończenia postoju wyłącznie w miejscu wyznaczonym (art. 47 ust. 3a) oraz powiązana z nim sankcja usunięcia pojazdu (art. 130a ust. 1 pkt 8) znajdowały zastosowanie wyłącznie na obszarze, dla ktorego zarządca drogi zawarł z Operatorem porozumienie określające lokalizację i gęstość miejsc przeznaczonych do postoju pojazdow mikromobiiności dzielonej; \\f- zarządca drogi był obowiązany, na wniosek Operatora świadczącego usługi mikromobiiności dzielonej na danym obszarze, przystąpić do uzgodnień i zawrzeć takie porozumienie w ustawowo określonym terminie, na podstawie wspolnych ustaleń stron; - porozumienie gwarantowało odpowiednią gęstość sieci miejsc postojowych, ustaloną na podstawie danych o rzeczywistym wykorzystaniu istniejących miejsc, ktore to dane Społka jest gotowa udostępnić zarządcą drog na etapie uzgodnień, nie mniejszą jednak niż iiczba i rozmieszczenie miejsc (spotow) funkcjonujących na danym obszarze w dniu wejścia w życie ustawy, z możliwością jej dalszego zwiększania w miarę zwiększających się potrzeb mieszkańcow; - w braku porozumienia (w tym w braku uzgodnienia gęstości i lokalizacji miejsc postojowych) na danym obszarze stosowane były zasady ogolne postoju pojazdow, obowiązujące obecnie - analogicznie jak ma to miejsce dzisiaj w gminach, ktore nie zdecydowały się na wspołpracę umowną z Operatorami; - usunięcie pojazdu na podstawie art. 130a ust. 1 pkt 8 było dopuszczalne dopiero po bezskutecznym upływie terminu wyznaczonego Operatorowi na relokacię pojazdu; proponowany przez Społkę termin nie krotszy niż 3 godziny od zawiadomienia operatora, dokonanego rownież środkami komunikacji elektronicznej, odpowiada obserwowanemu w praktyce Społki czasowi reakcji lokalnych zespołow operacyjnych w miastach objętych obecnie umowną wspołpracą i może zostać potwierdzony danymi operacyjnymi, ktore Społka jest gotowa przedstawić Ministerstwu. Powyższego terminu nie stosuje się, jeżeli pojazd pozostawiono w sposob powodujący bezpośrednie zagrożenie bezpieczeństwa ruchu drogowego. 4. Proponowane kierunkowe brzmienie przepisu. Tytułem propozycji legislacyjnej, Społka proponuje nadanie projektowanemu art. 47 ust. 3a następującego brzmienia, opartego na mechanizmie porozumienia zawieranego między zarządcą drogi a Operatorem (dalej jako “Wariant I”) „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności dzielonej, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez zarządcę drogi, jeżeli miejsca takie zostały wyznaczone na podstawie porozumienia zawartego pomiędzy zarządcą drogi a podmiotem świadczącym usługę mikromobilności dzielonej, określającego co najmniej lokalizacje oraz gęstość tych miejsc. Zarządca drogi zawiera porozumienie \\fna wniosek podmiotu świadczącego usługę mikromobilności dzielonej, w terminie [3] miesięcy od dnia złożenia wniosku, zapewniając gęstość miejsc nie mniejszą niż istniejąca na danym obszarze w dniu wejścia w życie ustawy. W braku porozumienia do postoju pojazdów i urządzeń, o których mowa w zdaniu pierwszym, stosuje się przepisy ust. 1-3.” Społka dostrzega, że przyjęcie mechanizmu opartego na porozumieniu (Wariant I) wymaga w praktyce wspołdziałania zarządcy drogi. Na wypadek, gdyby Ministerstwo uznało taki mechanizm za zbyt daleko idący, Społka przedstawia dodatkowo propozycję alternatywną (dalej jako „Wariant ił”), niewymagającą zawarcia porozumienia, a jedynie samodzielnego określenia przez zarządcę drogi obszaru objętego obowiązkiem oraz wyznaczenia i podania do wiadomości operatorom lokalizacji i liczby miejsc postojowych na tym obszarze: „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności dzielonej,, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez zarządcę drogi, pod warunkiem ze: T) zarządca drogi określił obszar, na którym obowiązek, o którym mowa w zdaniu pierwszym, ma zastosowanie; 2) miejsca przeznaczone do postoju na tym obszarze zostały wyznaczone oraz podane do wiadomości podmiotom świadczącym usługi mikromobilności dzielonej na tym obszarze, ze wskazaniem co najmniej lokalizacji oraz liczby tych miejsc. W przypadku niespełnienia warunków, o których mowa w zdaniu pierwszym, do postoju pojazdów i urządzeń, o których mowa w zdaniu pierwszym, stosuje się przepisy ust. f-3.” Odpowiedniej korekty wymagałby wowczas projektowany art 130a ust. 1 pkt 8 (odesłanie do naruszenia obowiązku wynikającego z porozumienia - w przypadku Wariantu I, albo z warunkow określenia obszaru i wyznaczenia miejsc - w przypadku Wariantu ii, a także warunek uprzedniego wezwania Operatora do reiokacji), a także projektowany art. 20 pkt 21 ustawy o drogach publicznych (uzupełnienie o obowiązek uzgadniania lokalizacji i gęstości miejsc z Operatorami - w przypadku wariantu i, albo o obowiązek określenia obszaru oraz wyznaczenia i podania do wiadomości Operatorom lokalizacji i liczby miejsc postojowych – w przypadku Wariantu II). Społka deklaruje gotowość przedstawienia kompletnych propozycji redakcyjnych wszystkich powiązanych jednostek redakcyjnych.\\t\\n\\tArt. 3 pkt 2 projektu ustawy\\tTIER Mobility Poland sp. z o.o.\\tII. Ocena ogolna Projektu Społka pozytywnie ocenia wprowadzenie do ustawy - Prawo o ruchu drogowym definicji mikromobilności dzielonej (projektowany art. 2 pkt 47d) oraz przyznanie zarządcom drog wyraźnej kompetencji do wyznaczania miejsc postoju pojazdow mikromobilności dzielonej (projektowany art. 20 pkt 21 ustawy o drogach publicznych). Rozwiązania te odpowiadają wypracowanej już praktyce wspołpracy Operatorow z miastami i zasługują na poparcie co do kierunku. Zasadnicze zastrzeżenia Społki budzi natomiast konstrukcja obowiązku postoju wyłącznie w miejscach wyznaczonych (projektowany art. 47 ust. 3a) w powiązaniu z sankcją usunięcia pojazdu z drogi (projektowany art. 130a ust. 1 pkt 8 oraz ust. 6a lit. i). Uwagi w tym zakresie przedstawiamy w pkt III poniżej. III. Uwaga zasadnicza: projektowany art. 130a ust 1 pkt 8 w związku z art. 47 ust. 3a ustawy - Prawo o ruchu u rugowym 1. Istota problemu - obowiązek bez gwarancji infrastruktury. Projektowany art. 47 ust. 3a nakłada na użytkownika bezwzględny obowiązek zakończenia postoju „wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę drogi”, a projektowany art. 130a ust. 1 pkt 8 przewiduje usunięcie pojazdu pozostawionego poza takim miejscem. Projekt nie nakłada jednak na zarządcę drogi żadnego obowiązku wyznaczenia takich miejsc, nie określa ich minimalnej gęstości ani trybu ich uzgadniania z Operatorami - wyznaczanie miejsc pozostaje wyłącznie uprawnieniem zarządcy drogi (projektowany art. 20 pkt 21 ustawy o drogach publicznych). Przepis nie precyzuje jednak, jak należy interpretować sytuację, w ktorej na danym obszarze zarządca drogi nie wyznaczył jeszcze żadnych miejsc postojowych albo wyznaczył je w liczbie lub lokalizacjach nieodpowiadających rzeczywistym potrzebom użytkownikow. Bez takiego doprecyzowania nie można wykluczyć interpretacji, zgodnie z ktorą każdorazowe zakończenie przejazdu na takim obszarze stanowiłoby naruszenie art. 47 ust. 3a i podstawę usunięcia pojazdu na koszt Operatora (200 zł za usunięcie oraz 50 zł za każdą dobę przechowywania). W takim ujęciu o możliwości faktycznego prowadzenia działalności gospodarczej na danym obszarze decydowałaby nie ustawa, lecz tempo działania zarządcy drogi w zakresie wyznaczania miejsc postojowych, co w skrajnym przypadku mogłoby prowadzić do wyłączenia usług mikrornobiiności dzielonej w części kraju. Niezależnie od tego, ktorą Interpretację ostatecznie przyjęto by w praktyce stosowania przepisu, sama ta niejednoznaczność rodzi po stronie Operatorow istotną niepewność co do \\fwarunkow prowadzenia działalności w poszczegolnych gminach, a w konsekwencji utrudnia podejmowanie decyzji inwestycyjnych i operacyjnych. Z tego względu Społka postuluje jednoznaczne doprecyzowanie przepisu w kierunku wskazanym w pkt. 3 poniżej, co pozwoli uniknąć niepewności, utrudniające prowadzenie działalności gospodarczej w tym zakresie. 2. Nieproporcjonalność sankcji i pominięcie możliwości technicznych Operatorów. Usunięcie pojazdu przez podmiot wyznaczony przez starostę jest środkiem najdalej idącym i najbardziej kosztownym, podczas gdy Operatorzy - w odrożnieniu od właścicieli pojazdow indywidualnych, dysponują narzędziami pozwalającymi usunąć nieprawidłowość niezwłocznie i bez angażowania środkow publicznych: dzięki wbudowanemu w każdym pojeździe systemowi GPS, Operatorzy mają podgląd co do lokalizacji jej floty, a lokalne zespoły serwisowe, ktorych zadaniem jest m.in. relokacja pojazdow, działają w trybie ciągłym. Projekt nie przewiduje jednak żadnego trybu uprzedniego wezwania Operatora do relokacji pojazdu. W rezultacie środek publicznoprawny staje się środkiem pierwszego wyboru, generującym koszty po stronie Operatorow i obciążenia organizacyjne po stronie powiatow, mimo że ten sam skutek (usunięcie pojazdu z miejsca niedozwolonego) Operatorzy mogą osiągnąć szybciej i bez kosztow publicznych. 3. Propozycja Spółki - ustawowy mechanizm porozumień z zarządcami dróg oraz gwarancja odpowiedniej gęstości miejsc postojowych. Społka proponuje oparcie projektowanego mechanizmu na sprawdzonym modelu funkcjonującym obecnie m.in. w Warszawie, Poznaniu, Krakowie i Gdańsku, tj. na umowach (porozumieniach) zawieranych pomiędzy zarządcą drogi (miastem) a Operatorami. Proponujemy, aby: - obowiązek zakończenia postoju wyłącznie w miejscu wyznaczonym (art. 47 ust. 3a) oraz powiązana z nim sankcja usunięcia pojazdu (art. 130a ust. 1 pkt 8) znajdowały zastosowanie wyłącznie na obszarze, dla którego zarządca drogi zawarł z Operatorem porozumienie określające lokalizację i gęstość miejsc przeznaczonych do postoju pojazdow mikrornobiiności dzielonej; - zarządca drogi był obowiązany, na wniosek Operatora świadczącego usługi mikrornobiiności dzielonej na danym obszarze, przystąpić do uzgodnień i zawrzeć takie porozumienie w ustawowo określonym terminie, na podstawie wspolnych ustaleń stron; - porozumienie gwarantowało odpowiednią gęstość sieci miejsc postojowych, ustaloną na podstawie danych o rzeczywistym wykorzystaniu istniejących miejsc. Ktore to dane Społka jest gotowa udostępnić zarządcą drog na etapie uzgodnień, nie mniejszą jednak niż liczba i rozmieszczenie miejsc (spotow) funkcjonujących na danym obszarze w dniu wejścia \\fw życie ustawy, z możliwością jej dalszego zwiększania w miarę zwiększających się potrzeb mieszkańcow; - w braku porozumienia (w tym w braku uzgodnienia gęstości i lokalizacji miejsc postojowych) na danym obszarze stosowane były zasady ogolne postoju pojazdow, obowiązujące obecnie - analogicznie jak ma to miejsce dzisiaj w gminach, ktore nie zdecydowały się na wspołpracę umowną z Operatorami; - usunięcie pojazdu na podstawie art. l30a ust. 1 pkt 8 było dopuszczalne dopiero po bezskutecznym upływie terminu wyznaczonego Operatorowi na relokację pojazdu;proponowany przez Społkę termin nie krotszy niż 3 godziny od zawiadomienia operatora, dokonanego rownież środkami komunikacji elektronicznej, odpowiada obserwowanemu w praktyce Społki czasowi reakcji lokalnych zespołow operacyjnych w miastach objętych obecnie umowną wspołpracą i może zostać potwierdzony danymi operacyjnymi, ktore Społka jest gotowa przedstawić Ministerstwu. Powyższego terminu nie stosuje się. jeżeli pojazd pozostawiono w sposob powodujący bezpośrednie zagrożenie bezpieczeństwa ruchu drogowego. 4. Proponowane kierunkowe brzmienie przepisu. Tytułem propozycji legislacyjnej, Społka proponuje nadanie projektowanemu art. 47 ust. 3a następującego brzmienia, opartego na mechanizmie porozumienia zawieranego między zarządcą drogi a Operatorem (dalej jako “Wariant I”) „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności dzielonej, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez zarządcę drogi, jeżeli miejsca takie zostały wyznaczone na podstawie porozumienia zawartego pomiędzy zarządcą drogi a podmiotem świadczącym usługę mikromobilności dzielonej, określającego co najmniej lokalizacje oraz gęstość tych miejsc. Zarządca drogi zawiera porozumienie na wniosek podmiotu świadczącego usługę mikromobilności dzielonej, w terminie [3] miesięcy od dnia złożenia wniosku, zapewniając gęstość miejsc nie mniejszą niż istniejąca na danym obszarze w dniu wejścia wżycie ustawy W braku porozumienia do postoju pojazdów i urządzeń, o których mowa w zdaniu pierwszym, stosuje się przepisy ust. 1-3.” Społka dostrzega, że przyjęcie mechanizmu opartego na porozumieniu (Wariant I) wymaga w praktyce wspołdziałania zarządcy drogi. Na wypadek, gdyby Ministerstwo uznało taki \\fmechanizm za zbyt daleko idący, Społka przedstawia dodatkowo propozycję alternatywną (dalej jako „Wariant !!”), niewymagającą zawarcia porozumienia, a jedynie samodzielnego określenia przez zarządcę drogi obszaru objętego obowiązkiem oraz wyznaczenia i podania do wiadomości operatorom lokalizacji i liczby miejsc postojowych na tym obszarze: „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, udostępnione w ramach mikromobilności dzielonej, jest obowiązana zakończyć postój w miejscu wyznaczonym do tego celu przez zarządcę drogi, pod warunkiem ze: 1) zarządca drogi określił obszar na którym obowiązek, o którym mowa w zdaniu pierwszym, ma zastosowanie; 2) miejsca przeznaczone do postoju na tym obszarze zostały wyznaczone oraz podane do wiadomości podmiotom świadczącym usługi mikromobilności dzielonej na tym obszarze, ze wskazaniem co najmniej lokalizacji oraz liczby tych miejsc. W przypadku niespełnienia warunków, o których mowa w zdaniu pierwszym, do postoju pojazdów i urządzeń, ó których mowa w zdaniu pierwszym, stosuje się przepisy ust. 1-3. ” Odpowiedniej korekty wymagałby wowczas projektowany art. 130a ust. 1 pkt 8 (odesłanie do naruszenia obowiązku wynikającego z porozumienia - w przypadku Wariantu I, albo z warunkow określenia obszaru i wyznaczenia miejsc - w przypadku wariantu li, a także warunek uprzedniego wezwania Operatora do reiokacji), a także projektowany art. 20 pkt 21 ustawy o drogach publicznych (uzupełnienie o obowiązek uzgadniania lokalizacji i gęstości miejsc z Operatorami - w przypadku Wariantu I, albo o obowiązek określenia obszaru oraz wyznaczenia i podania do wiadomości Operatorom lokalizacji i liczby miejsc postojowych – w przypadku Wariantu II).  \\t\\n\\tArt. 3 i art. 10 projektu ustawy\\tFundacja Blind&Proud\\tE-hulajnogi w polskich miastach Hulajnogi elektryczne na wynajem są już dostępne w około 200 miastach w całej Polsce. W każdym mieście mogą działać na innych zasadach, bez umów z samorządem. Choć to władze samorządów są rozliczane za utrzymanie porządku i bezpieczeństwo na drogach i chodnikach, nie mają istotnego wpływu na działalność operatorów hulajnóg elektrycznych i negatywne skutki dla lokalnych społeczności. \\fPorozrzucane hulajnogi to powszechny problem Użytkownicy hulajnóg elektrycznych porzucają je w niewłaściwych miejscach, bo mogą to robić, bezkarnie. Operatorzy nie mają skutecznych narzędzi do weryfikacji prawidłowego parkowania. Trudno również oczekiwać, że samorząd będzie delegował armię policjantów i strażników miejskich do porządkowania chodników z porzuconych hulajnóg elektrycznych. Porzucone e-hulajnogi stanowią poważne zagrożenie dla wszystkich użytkowników dróg i chodników, w tym rowerzystów i pieszych, w szczególności seniorów, małych dzieci i osób z niepełnosprawnościami. Zderzenia rowerzystów z leżącymi hulajnogami elektrycznymi, upadki seniorów, osób niewidomych i małych dzieci to wysokie ryzyko urazów. Ponadto urządzenia blokujące chodnik wymuszają poruszanie się pieszych po ulicy, co stwarza zagrożenie potrąceniem przez samochód. Obywatele oczekują, że odpowiednie organy zapanują nad tym bałaganem. Część z miast wprowadza stopniowo ograniczenia w parkowaniu hulajnóg elektrycznych, w uzgodnieniu z operatorami. Ograniczenia dotyczą jednak z reguły wyłącznie centrów miast, przez co hulajnogi elektryczne dalej są porzucane, choć nie w samym centrum. Inne miasta zwiększają liczbę miejsc do parkowania e-hulajnóg. Jednak jak wskazuje raport mikromobilności w Warszawie, samo istnienie miejsc do parkowania to zbyt mało. W okresie objętym badaniem tylko 6% podróży zakończyło się parkowaniem w wyznaczonym miejscu. Przyczyna problemu Źródło problemu stanowią niejasne przepisy art. 47 ust. 3 ustawy Prawo o ruchu drogowym, przyjęte w 2021 roku. Przepisy dopuszczają by hulajnogę elektryczną zostawić w miejscu przeznaczonym a jak nie ma takiego miejsca, to na chodniku. Tak ogólny zapis spowodował obecny chaos w parkowaniu hulajnóg elektrycznych na wynajem, na którym korzystają operatorzy e-hulajnóg z uwagi na możliwość oferowania swoich pojazdów na wynajem na niemal każdym rogu chodnika. Projektowana zmiana prawna (UD 402) Przygotowany przez Ministerstwo Infrastruktury projekt ustawy (UD 402), wprowadza szereg korzystnych zmian porządkujących parkowanie e-hulajnóg na wynajem:   definicję mikromobilności dzielonej; kompetencję zarządcy dróg, czyli głównie prezydentów miast, burmistrzów i wójtów do wyznaczania miejsca do parkowania wynajmowanych e-hulajnóg, rowerów i urządzeń transportu osobistego; \\fwymóg parkowania hulajnogi elektrycznej, roweru lub urządzenia transportu osobistego na wynajem tylko w miejscach wyznaczonych; możliwość usuwania nieprawidłowo zaparkowanych pojazdów na wynajem na koszt właściciela ( 200 zł za usunięcie i 50 zł za każdy dzień przechowywania), projektowane przepisy mają wejść w życie od 1 stycznia 2028 roku.  Korzyści z uregulowania parkowania e-hulajnóg na wynajem Proponowana zmiana pozwoli uporządkować parkowanie hulajnóg elektrycznych udostępnianych przez operatorów, bez negatywnych skutków dla właścicieli prywatnych pojazdów. Parkowanie e-hulajnóg na wynajem wyłącznie w miejscach wyznaczonych pozwoli odzyskać lokalnym władzom możliwość zarządzania bezpieczeństwem na drogach i chodnikach. Samorząd zdecyduje o miejscach i liczbie miejsc wyznaczonych na własnym terenie. To pozwoli na wyrównany dialog między operatorami, chcącymi oferować swoje usługi mieszkańcom a samorządem, który odpowiada za bezpieczeństwo i porządek w przestrzeni publicznej. Projektowane przepisy spowodują, że hulajnogi elektryczne na wynajem nie będą mogły być porzucane poza miejscami wyznaczonymi. Ustawa zapewnia również możliwość usuwania nieprawidłowo zaparkowanych e-hulajnóg udostępnianych przez operatorów. Raz jeszcze pragniemy wyrazić nasze poparcie dla wprowadzenia obowiązku parkowania hulajnóg elektrycznych na wynajem wyłącznie w miejscach wyznaczonych. To konieczny krok, by wzmocnić bezpieczeństwa wszystkich uczestników ruchu drogowego, w tym pieszych ze szczególnymi potrzebami. Konieczność pilnego procedowania Art. 10 pkt 2 projektu ustawy UD402 przewiduje, że obowiązek parkowania hulajnóg elektrycznych na wynajem wejdzie w życie 1 stycznia 2028 roku. Postulujemy maksymalne możliwe skrócenie tego okresu i, o ile będzie to możliwe, wejście w życie zmian od 1 lipca 2027 roku. Oznacza to konieczność pilnego procedowania projektu. Mamy jednak nadzieję, że postulat ten zostanie przez Pana Ministra uwzględniony z uwagi na fakt, że proponowane przepisy regulują kwestie istotne dla bezpieczeństwa uczestników ruchu drogowego. \\t\\n\\tArt. 3 projektu ustawy \\tZarząd Dróg Miejskich Warszawa\\t1. Regulacja postoju W zakresie przepisów zawartych w ustawach oraz propozycji zmian zawartych w projekcie nr UD402 proponujemy następujące rozwiązania: \\f  Definicja mikromobilności dzielonej: Wprowadzenie w ustawie z dnia 20 czerwca 1997 r., Prawo o ruchu drogowym – zgodnie z propozycją resortu - jako art. 2 pkt. 47d), definicji mikromobilności dzielonej. Proponujemy aby miała ona następującą treść: „47d) mikromobilność dzielona - usługa polegająca na udostępnianiu pojazdów i innych urządzeń przeznaczonych do indywidualnego przemieszczania się, w szczególności rowerów, motorowerów, hulajnóg elektrycznych oraz urządzeń transportu osobistego, a także pojazdów kategorii L1e i jej podkategorii, w rozumieniu rozporządzenia 168/2013 w sprawie homologacji i nadzoru rynku pojazdów, na krótki okres, w sposób odpłatny lub nieodpłatny, umożliwiający rozpoczęcie i zakończenie podróży pojazdem w miejscach zarówno wskazanych przez udostępniającego, jak też wybranych przez użytkownika, w celu wykorzystania tych pojazdów przez wielu użytkowników;”  Dookreślenie miejsca przeznaczonego dla postoju hulajnogi (i roweru) W naszej opinii wskazane byłoby dookreślenie dopuszczenia opisanego a art. 47 ust. 3 -  a więc dopuszczenia dot. rowerów, hulajnóg elektrycznych itp. do postoju na chodniku – poprzez wskazanie podstawowych rodzajów miejsc określonych jako „przeznaczone”. Byłyby to miejsca wyznaczone znakami lub też tzw. stojaki rowerowe, czyli elementy małej architektury służące do parkowania rowerów. BARDZO WAŻNE – te zapis nie powinien nakładać obowiązku oznakowania znakami pionowymi ani sporządzania projektów organizacji ruchu dla stojaków rowerowych.  Brzmienie art. 47 ust. 3 mogłoby być wtedy następujące: „3. Dopuszcza się postój roweru, hulajnogi elektrycznej lub urządzenia transportu osobistego przy elemencie małej architektury, przeznaczonym do tego celu, lub w miejscu wyznaczonym, a w razie braku takiego miejsca – jak najbliżej zewnętrznej krawędzi drogi dla pieszych najbardziej oddalonej od jezdni oraz równolegle do tej krawędzi, przy zachowaniu warunków określonych w ust. 1 pkt. 2.„  Zakaz postoju dla pojazdów mikromobilności dzielonej poza miejscami przeznaczonymi W ustawie prawo o ruchu drogowym proponujemy dodanie w art. 49 ust. 2, nowego pkt 6), ustanawiającego zakaz postoju dla pojazdów mikromobilności dzielonej poza miejscami \\fprzeznaczonymi. W przepisie tym mowa zarówno o miejscach wyznaczonych zgodnie z trybem opisanym w wyżej proponowanym art. 12c ustawy o drogach publicznych, jak też o tzw. stojakach rowerowych, określanych jako „inne elementy małej architektury, przeznaczone do postoju rowerów”. Brzmienie proponowanego w art. 49 ust. 2. nowego punktu: [Zabrania się postoju:] „6) pojazdu udostępnionego w ramach mikromobilności dzielonej w miejscach nie będących: - miejscami wyznaczonymi przez organ właściwy do zarządzania ruchem, o których mowa w art. 12c ustawy z dnia 21 marca 1985 r. o drogach publicznych, - miejscami umieszczenia elementów małej architektury, przeznaczonych do postoju rowerów.”   Możliwość usunięcia pojazdu pozostawionego niezgodnie z przepisami Zgodnie z założeniami resortu potrzebne będzie wprowadzenie zmian w art. 130a ustawy prawo o ruchu drogowym, polegających na uzupełnieniu ust. 1 poprzez wskazanie, że w razie naruszenia zakazu postoju, pojazd mikromobilności dzielonej podlega usunięciu na koszt właściciela, oraz uzupełnieniu ust. 4 poprzez przyznanie straży gminnej (miejskiej) kompetencji do wydawania dyspozycji usunięcia takiego pojazdu. Jeśli do postoju pojazdu mikromobilności dzielonej niezbędna byłaby zgoda zarządcy drogi, jej brak również powinien być podstawą do usunięcia takiego pojazdu. Proponowane zmiany (zgodnie z porządkiem wg projektu UD402): W art. 130a: a) w ust. 1 w pkt 7) kropkę zastępuje się średnikiem i dodaje się pkt 8) o brzmieniu: „8) pozostawienia, z naruszeniem art. 49 ust. 2 pkt. 6), pojazdu udostępnionego w ramach mikromobilności dzielonej poza przeznaczonym miejscem.”; b) w ust. 6a lit. h kropkę zastępuje się średnikiem i dodaje się lit. i o brzmieniu: „i) pojazd lub urządzenie udostępnione w ramach mikromobilności dzielonej, za usunięcie - 200 zł, za każdą rozpoczętą dobę przechowywania - 50 zł.” c) w ust. 4. w pkt. 2) słowa „ust. 1 pkt 1, 4 i 5;” zastępuje się słowami „ust. 1 pkt. 1, 4, 5 i 8;” \\t\\n\\tArt. 3 projektu\\tLime Technology sp. z o.o.\\t● Art. 3 pkt 1 projektu ustawy – art. 2 pkt 47d ustawy – Prawo o ruchu drogowym:   \\fProjekt wprowadza do ustawy – Prawo o ruchu drogowym definicję „mikromobilności dzielonej”. Lime proponuje zastąpienie tego określenia pojęciem „mikromobilność współdzielona”. Termin „mikromobilność współdzielona” jest powszechnie stosowany w terminologii branżowej, materiałach prasowych i publikacjach dotyczących sektora. Trafniej oddaje również charakter usługi polegającej na udostępnianiu tych samych pojazdów lub urządzeń wielu użytkownikom.   Projektowany art. 2 pkt 47d ustawy – Prawo o ruchu drogowym mógłby otrzymać następujące brzmienie:  „47d) mikromobilność współdzielona – usługę polegającą na udostępnianiu użytkownikom, odpłatnie lub nieodpłatnie, pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego, z wykorzystaniem aplikacji mobilnej lub innego systemu teleinformatycznego  umożliwiającego korzystanie z tych pojazdów lub urządzeń przez wielu użytkowników;”.   Konsekwentnie określenie „mikromobilność dzielona” powinno zostać zastąpione określeniem „mikromobilność współdzielona” również w art. 2 projektu ustawy oraz w pozostałych przepisach dodawanych lub zmienianych w art. 3 projektu.\\t\\n\\tArt. 3 pkt 1 projektu ustawy\\tPolski Związek Niewidomych\\t6. Definicja operatora mikromobilności dzielonej Aktualna propozycja zawarta w UD402 Art. 3 pkt 1 projektu przewiduje dodanie w art. 2 Prawa o ruchu drogowym pkt 47d: „47d) mikromobilność dzielona – usługę polegającą na udostępnianiu użytkownikom, w sposób odpłatny lub nieodpłatny, pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego, z wykorzystaniem aplikacji mobilnej lub innego systemu teleinformatycznego umożliwiającego korzystanie z tych pojazdów lub urządzeń przez wielu użytkowników;”. Projekt definiuje usługę, ale nie definiuje operatora odpowiedzialnego za jej organizację. Propozycja PZN \\fW art. 3 pkt 1 projektu, po projektowanym art. 2 pkt 47d, proponuje się dodać pkt 47e w brzmieniu: „47e) operator mikromobilności dzielonej – przedsiębiorcę lub inny podmiot organizujący albo prowadzący usługę mikromobilności dzielonej;”. Uzasadnienie Definicja jest konieczna, aby ustawa mogła nakładać jednoznaczne obowiązki na podmiot zarządzający aplikacją i flotą, a nie jedynie na osobę korzystającą z urządzenia. \\t\\n\\tArt. 3 pkt 2 projektu ustawy\\tPolski Związek Niewidomych\\t2. Prawidłowy sposób ustawienia urządzenia w miejscu wyznaczonym Aktualna propozycja zawarta w UD402 Art. 3 pkt 2 projektu przewiduje dodanie w art. 47 Prawa o ruchu drogowym ust. 3a w brzmieniu: „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rower, hulajnogę elektryczną lub urządzenie transportu osobistego udostępnione w ramach mikromobilności dzielonej jest obowiązana zakończyć postój wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę drogi.”. Przepis określa miejsce zakończenia postoju, ale nie reguluje sposobu ustawienia urządzenia. Propozycja PZN W art. 3 pkt 2 projektu UD402 projektowanemu art. 47 ust. 3a ustawy – Prawo o ruchu drogowym proponuje się nadać następujące brzmienie: „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rower, hulajnogę elektryczną lub urządzenie transportu osobistego udostępnione w ramach mikromobilności dzielonej, jest obowiązana zakończyć postój wyłącznie w miejscu wyznaczonym do tego celu przez \\fzarządcę drogi oraz ustawić pojazd lub urządzenie stabilnie, w całości w granicach tego miejsca i w sposób zapewniający ciągłość trasy wolnej od przeszkód”.  Uzasadnienie W aktualnym brzmieniu za prawidłowo zaparkowane może zostać uznane urządzenie, którego tylko część znajduje się w strefie. Hulajnoga może także leżeć w granicach miejsca, ale wystawać kierownicą lub kołem na ciąg pieszy. Obowiązek powinien obejmować zarówno lokalizację postoju, jak i sposób ustawienia urządzenia. Odwołanie do wcześniejszego opracowania W opracowaniu z 2025 r. wskazano, że pojazdy nie mogą ograniczać swobodnego i bezpiecznego poruszania się pieszych ani pozostawać w sposób powodujący powstanie przeszkody na chodniku. \\t\\n\\tArt. 3 pkt 3 lit. a projektu ustawy\\tPolski Związek Niewidomych\\t3. Dostosowanie podstawy usunięcia pojazdu do zmienionego art. 47 ust. 3a Aktualna propozycja zawarta w UD402 Art. 3 pkt 3 lit. a projektu przewiduje dodanie w art. 130a ust. 1 pkt 8: „8) pozostawienia, z naruszeniem art. 47 ust. 3a, pojazdu lub urządzenia przeznaczonego do indywidualnego przemieszczania się na krótkich dystansach, w szczególności roweru, hulajnogi elektrycznej lub urządzenia transportu osobistego udostępnionego w ramach mikromobilności dzielonej, poza miejscem wyznaczonym do tego celu przez zarządcę drogi.”. Podstawa usunięcia obejmuje wyłącznie pozostawienie urządzenia poza miejscem wyznaczonym. Propozycja PZN W art. 3 pkt 3 lit. a projektu projektowanemu art. 130a ust. 1 pkt 8 proponuje się nadać następujące brzmienie: \\f„8) pozostawienia, z naruszeniem art. 47 ust. 3a, pojazdu lub urządzenia przeznaczonego do indywidualnego przemieszczania się na krótkich dystansach, w szczególności roweru, hulajnogi elektrycznej lub urządzenia transportu osobistego udostępnionego w ramach mikromobilności dzielonej, poza miejscem wyznaczonym do tego celu przez zarządcę drogi  i zapewniającego ciągłośc trasy wolnej od przeszkód wraz z opaską szerokości 0,3m.”. Uzasadnienie Jeżeli art. 47 ust. 3a zostanie uzupełniony o sposób ustawienia urządzenia, analogicznie należy rozszerzyć podstawę jego usunięcia. W przeciwnym razie możliwe będzie usunięcie urządzenia znajdującego się poza strefą, ale nie urządzenia znajdującego się częściowo w strefie i jednocześnie blokującego chodnik. Należy zwrócić uwagę na linie prowadzące (tzw. naturalne linie kierunkowe” i sposób poruszania się osób niewidomych.  \\t\\n\\tArt. 3 projektu ustawy\\tPolski Związek Niewidomych\\t7. Techniczne ograniczenie możliwości zakończenia korzystania poza miejscem wyznaczonym Aktualna propozycja zawarta w UD402 Projekt nakłada obowiązek parkowania w miejscu wyznaczonym na użytkownika. Nie przewiduje natomiast ustawowego obowiązku operatora dotyczącego: stosowania geofencingu lub innego mechanizmu lokalizacyjnego, weryfikowania sposobu ustawienia urządzenia, wskazywania użytkownikowi najbliższych miejsc postojowych, dokumentowania przypadków nieprawidłowego postoju. Propozycja PZN W art. 3 projektu proponuje się dodać zmianę polegającą na dodaniu w ustawie – Prawo o ruchu drogowym art. 47a w brzmieniu: „Art. 47a. \\fOperator mikromobilności dzielonej zapewnia rozwiązania techniczne służące skutecznemu ograniczeniu możliwości zakończenia korzystania z pojazdu lub urządzenia poza miejscem wyznaczonym przez zarządcę drogi. Operator zapewnia weryfikację prawidłowego ustawienia pojazdu lub urządzenia przy zakończeniu korzystania z niego. Operator zapewnia użytkownikowi informację o lokalizacji najbliższych miejsc wyznaczonych do postoju. Minister właściwy do spraw transportu określi, w drodze rozporządzenia, szczegółowy sposób realizacji obowiązków, o których mowa w ust. 1–3, uwzględniając dokładność systemów lokalizacyjnych, konieczność skutecznej weryfikacji postoju oraz ochronę danych osobowych.”. Uzasadnienie Kary lub dodatkowe opłaty nakładane na podstawie prywatnych regulaminów operatorów nie zapewniają skutecznego egzekwowania obowiązków. Nie istnieje publiczna kontrola pozwalająca ustalić: czy sankcje są rzeczywiście nakładane, jak często operator odstępuje od ich stosowania, jak wiele przypadków nieprawidłowego postoju pozostaje bez reakcji, czy system technicznie zapobiega zakończeniu najmu poza strefą. Proponowany przepis nie narzuca jednej technologii, lecz wymaga osiągnięcia określonego rezultatu. \\t\\n\\tArt. 3 projektu ustawy\\tPolski Związek Niewidomych\\t8. Dostępny system zgłaszania urządzeń stanowiących przeszkodę Aktualna propozycja zawarta w UD402 Projekt przewiduje możliwość usunięcia urządzenia pozostawionego poza miejscem wyznaczonym oraz opłatę 200 zł za usunięcie i 50 zł za każdą dobę przechowywania. \\fNie przewiduje jednak obowiązku operatora dotyczącego przyjmowania zgłoszeń, dostępności kanału zgłoszeniowego ani czasu reakcji. Propozycja PZN Po proponowanym art. 47a proponuje się dodać art. 47b w brzmieniu: „Art. 47b. Operator mikromobilności dzielonej zapewnia bezpłatny i dostępny dla osób ze szczególnymi potrzebami system zgłaszania pojazdów lub urządzeń pozostawionych nieprawidłowo albo w sposób powodujący zagrożenie lub utrudnienie dla ruchu. Dokonanie zgłoszenia nie może być uzależnione od posiadania konta użytkownika ani zainstalowania aplikacji operatora. Operator zapewnia co najmniej możliwość dokonania zgłoszenia telefonicznego oraz za pomocą dostępnego cyfrowo formularza. Operator niezwłocznie usuwa albo prawidłowo ustawia pojazd lub urządzenie powodujące bezpośrednie zagrożenie lub istotne utrudnienie dla ruchu pieszych. Minister właściwy do spraw transportu określi, w drodze rozporządzenia, maksymalny termin reakcji operatora w pozostałych przypadkach oraz minimalne wymagania dostępności systemu zgłoszeń.”. Uzasadnienie Osoba niewidoma może nie być w stanie odczytać numeru urządzenia ani kodu QR. Nie powinna być również zmuszana do instalowania aplikacji każdego operatora tylko po to, aby zgłosić przeszkodę. Administracyjne usunięcie pojazdu nie zastępuje szybkiej reakcji operatora, który zna lokalizację urządzenia i dysponuje możliwością jego relokacji.\\t\\n\\tArt. 3 projektu ustawy\\tPolski Związek Niewidomych\\t10. Sankcje wobec operatora Aktualna propozycja zawarta w UD402 \\fProjekt określa opłatę za administracyjne usunięcie pojedynczego urządzenia, ale nie przewiduje sankcji za systemowe niewykonywanie obowiązków przez operatora. Nie obejmuje więc sytuacji, w której operator: nie zapewnia skutecznej weryfikacji parkowania, nie reaguje na zgłoszenia, nie usuwa urządzeń, nie przekazuje wymaganych danych, prowadzi usługę mimo powtarzających się naruszeń. Propozycja PZN PZN proponuje wprowadzenie administracyjnej kary pieniężnej za niewykonywanie obowiązków określonych w proponowanych art. 47a i 47b oraz obowiązków informacyjnych wobec zarządcy drogi. Przepis powinien stanowić: „Operator mikromobilności dzielonej, który nie wykonuje obowiązków dotyczących weryfikacji postoju, reagowania na zgłoszenia, usuwania pojazdów lub przekazywania wymaganych danych, podlega administracyjnej karze pieniężnej.” Przy ustalaniu wysokości kary organ powinien uwzględniać: liczbę urządzeń objętych naruszeniem; czas trwania i powtarzalność naruszenia; stopień zagrożenia dla ruchu pieszych; wielkość floty operatora; działania podjęte w celu usunięcia naruszenia. Uzasadnienie Opłata 200 zł za usunięcie pojedynczego urządzenia może być traktowana przez dużego operatora jako zwykły koszt prowadzenia działalności. Nie oddziałuje ona na systemowe \\fnieprawidłowości, takie jak nieskuteczny geofencing, brak obsługi zgłoszeń albo powtarzające się niewykonywanie obowiązku relokacji. PZN nie proponuje na tym etapie konkretnych widełek kwotowych. Powinny one zostać ustalone po analizie proporcjonalności i struktury rynku. Art. 1 pkt 22\\t\\n\\tArt. 3 projektu ustawy\\tZrzeszenie Studentów Niepełnospraw-nych Uniwersytetu Kazimierza Wielkiego w Bydgoszczy\\tpragnę wyrazić poparcie dla projektowanych przez Ministerstwo Infrastruktury, nowych przepisów (projekt UD 402), skutkujących wymogiem parkowania hulajnóg elektrycznych na wynajem wyłącznie w miejscach wyznaczonych. To konieczny krok, by wzmocnić bezpieczeństwo wszystkich uczestników ruchu drogowego, w tym dzieci, seniorów, osób z niepełnosprawnościami i rowerzystów. Jako Zrzeszenie Studentów Niepełnosprawnych Uniwersytetu Kazimierza Wielkiego w Bydgoszczy pragniemy poinformować, że w pełni podzielamy stanowisko i obawy dotyczące problemów z dostępnością oraz bezpieczeństwem w przestrzeniach miejskich.\\n\\nChcielibyśmy przekazać, że jako organizacja reprezentująca interesy osób ze szczególnymi potrzebami podjęliśmy już w tej sprawie formalne kroki. W dniu 21 lipca 2026 r. skierowaliśmy na ręce Pana Rafała Bruskiego, Prezydenta Miasta Bydgoszczy, dwa oficjalne pisma:\\na) Wniosek o lepsze zabezpieczenie terenów remontowanych oraz usprawnienie informowania o zmianach w organizacji ruchu i komunikacji miejskiej. Zwracamy w nim uwagę na drastyczne utrudnienia w samodzielnym i bezpiecznym poruszaniu się, z jakimi borykają się m.in. nasze niewidome koleżanki i koledzy. Apelujemy o zapewnienie bezpiecznych, alternatywnych ciągów pieszych oraz lepsze informowanie o zmianach w kursowaniu komunikacji miejskiej.\\nb)Wniosek o ulepszenie organizacji ruchu i zasad korzystania z hulajnóg elektrycznych na terenie miasta.\\nWskazujemy w nim na realne zagrożenie zdrowia i życia, jakie stanowią nieprawidłowo porzucone na chodnikach hulajnogi, przywołując m.in. niedawny wypadek jednej z naszych studentek na ul. Krasińskiego. Domagamy się wyznaczenia obowiązkowych stref parkowania hulajnóg oraz stref ograniczonej prędkości (zwłaszcza w okolicach szkół i ośrodków dla osób z niepełnosprawnościami).\\n\\fWierzymy, że wspólny i głośny apel naszych środowisk skłoni władze do podjęcia szybkich działań i wdrożenia rozwiązań, które sprawią, że miasta będą miejscem bezpiecznym i przyjaznym dla wszystkich, niezależnie od stopnia ich sprawności. \\t\\n\\tArt. 3 i 4 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 3 i Art. 4 Zmiany dotyczące unormowania postoju wynajmowanych hulajnóg i innych pojazdów są korzystne i w interesie społecznym w szczególności osób z niepełnosprawnościami, które do tej pory są często poszkodowane z powodu nieodpowiedzialności osób wynajmujących te pojazdy.\\t\\n\\tArt. 3 pkt 2 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 3 zmiana 2) dodaje się ust. 3a w brzmieniu: Zamiast obecnej wersji proponujemy nową treść ust. 3a) „3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich dystansach w ramach mikromobilności dzielonej, w szczególności rower, hulajnogę elektryczną lub urządzenie transportu osobistego jest obowiązana zakończyć jazdę wyłącznie w miejscu wyznaczonym do tego celu przez zarządcę drogi.” Zgodnie z uzasadnieniem zmian w ustawie zakaz miał dotyczyć tylko pojazdów wynajmowanych. Nie miał dotyczyć prywatnych pojazdów. Obecna treść ust. 3a zakazuje pozostawiania wszystkich pojazdów poza wyznaczonymi miejscami także prywatnych. Użytkownik pozostawiający pojazd raczej kończy jazdę a nie postój\\t\\n\\tArt. 3 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 4) \\tJestem niewidoma. Korzystam z komputera z czytnikiem ekranu. Na stronie Rządowego Centrum Legislacji znalazłam informacje o konsultacjach projektu ustawy o zmianie ustawy o kierujących pojazdami, ale bez użycia myszy nie dotarłam do linku, pod którym można pobrać całą treść. Ważne jest uporządkowanie kwestii parkowania hulajnóg i skuteczne wymierzanie kar za ich porzucanie w miejscach niedozwolonych. Tam, gdzie to możliwe, osoby niewidome poruszają się stroną oddaloną od jezdni, np. wzdłuż trawnika, budynku. Hulajnogi nie powinny być parkowane w takich miejscach ani przy przejściach dla pieszych, ponieważ osobie niewidomej będzie jeszcze trudniej znaleźć przejście. Ponadto, miejscowości, w których firmy mają hulajnogi elektryczne, powinny na tym zarabiać. Skoro trzeba płacić za rozstawienie straganu z truskawkami, na jakiej podstawie operatorzy hulajnóg korzystają z miejskiej przestrzeni za darmo i na tym zarabiają? \\fMieszkam w Jastrzębiu-Zdroju w woj. śląskim. Parę lat temu w nocy w mieście pojawiło się kilkadziesiąt hulajnóg. Na dwie wpadłam w drodze na przystanek. W urzędzie miasta dowiedziałam się, że nie było żadnych uzgodnień. Mimo że ta nocna akcja była nielegalna, miasto nie miało narzędzi, by obciążyć operatora opłatą. Ustawa powinna też obligować policję i straż miejską do wystawiania mandatów za pozostawienie hulajnogi w niedozwolonym miejscu. Obecnie w wielu miastach służby tego nie robią. Gdy potknęłam się o hulajnogę, wysiadając z autobusu, inna pasażerka zrobiła jej zdjęcie. Mimo że był na nim widoczny kod QR, straż miejska, której wysłałam zdjęcie, nic nie zrobiła. Powiedziano mi, że podjęłaby działania, gdybym zadzwoniła w momencie zdarzenia. Innym razem zadzwoniłam, straż przyjechała i tylko przestawiła hulajnogę w bezpieczne miejsce. Każda hulajnoga elektryczna, zarówno komercyjna, jak i prywatna, powinna być łatwa do zidentyfikowania, np. numer rejestracyjny, zakodowanie danych właściciela w czipie dostępnym dla policji i straży miejskiej. \\t\\n\\tArt. 3 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 5) \\tw związku z wejściem w życie nowych przepisów dotyczących korzystania z hulajnóg elektrycznych przez osoby poniżej 13. roku życia, zwracamy się z apelem o ich ponowną analizę oraz dostosowanie do rzeczywistych warunków korzystania z tego środka transportu.\\nDoceniamy fakt, że obowiązujące przepisy dopuściły możliwość poruszania się hulajnogą elektryczną przez dzieci poniżej 13. roku życia pod bezpośrednią opieką osoby dorosłej. Jest to rozwiązanie bardziej racjonalne od całkowitego zakazu i uwzględnia rolę rodziców w zapewnianiu bezpieczeństwa najmłodszym uczestnikom ruchu.\\nJednocześnie obowiązujące ograniczenie, zgodnie z którym dziecko może korzystać z hulajnogi elektrycznej wyłącznie w strefie zamieszkania, nie znajduje uzasadnienia w praktyce i nie odpowiada rzeczywistemu charakterowi rodzinnego korzystania z hulajnóg.\\nAnaliza komunikatów Policji oraz doniesień medialnych dotyczących wykroczeń i zdarzeń z udziałem hulajnóg elektrycznych wskazuje, że przypadki naruszania przepisów dotyczą przede wszystkim młodzieży powyżej 13. roku życia oraz osób dorosłych. To właśnie przedstawiciele tych grup najczęściej pojawiają się w policyjnych komunikatach dotyczących niebezpiecznych zachowań.\\nNie widać natomiast, aby istotnym problemem były dzieci poniżej 13. roku życia poruszające się pod opieką rodziców.\\nW praktyce to osoba dorosła wybiera trasę przejazdu, kontroluje sposób jazdy oraz \\fodpowiada za bezpieczeństwo dziecka. Trudno więc uznać, że przejazd rodzica z dzieckiem drogą dla rowerów stwarza większe zagrożenie niż taki sam przejazd odbywający się kilkaset metrów dalej w strefie zamieszkania.\\nCo więcej, większość bezpiecznej infrastruktury przeznaczonej dla rowerzystów i użytkowników hulajnóg znajduje się poza strefami zamieszkania. Są to drogi dla rowerów, ciągi pieszo-rowerowe oraz tereny rekreacyjne, które zostały zaprojektowane właśnie z myślą o bezpiecznym poruszaniu się użytkowników rowerów oraz mikromobilności.\\nWspólne przejażdżki rodziców i dzieci to nie tylko forma aktywności fizycznej. To również budowanie trwałych więzi rodzinnych, tak potrzebnych we współczesnym świecie, a także praktyczna nauka zasad ruchu drogowego. Dzieci uczą się odpowiedzialnych zachowań przede wszystkim poprzez obserwację swoich rodziców i wspólne uczestnictwo w ruchu drogowym.\\nDlatego zwracamy się z prośbą o zmianę obowiązujących przepisów poprzez umożliwienie dzieciom poniżej 13. roku życia korzystania z hulajnóg elektrycznych pod bezpośrednią opieką osoby dorosłej wszędzie tam, gdzie przepisy dopuszczają ruch hulajnóg elektrycznych, a nie wyłącznie w strefie zamieszkania.\\nUważamy, że takie rozwiązanie będzie lepiej odpowiadało rzeczywistym potrzebom rodzin, jednocześnie nie obniżając poziomu bezpieczeństwa. Pozwoli również skoncentrować działania legislacyjne na grupach użytkowników, które – zgodnie z obserwacjami Policji – najczęściej dopuszczają się naruszeń przepisów ruchu drogowego.\\n\\t\\n\\tArt. 3 projektu ustawy\\tPowiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach\\tw związku z trwającymi konsultacjami publicznymi projektu ustawy dotyczącego uregulowania zasad funkcjonowania mikromobilności współdzielonej, Powiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach wyraża zdecydowane poparcie dla proponowanych rozwiązań dotyczących obowiązku parkowania hulajnóg elektrycznych oraz innych urządzeń transportu osobistego na wynajem wyłącznie w miejscach wyznaczonych, a także dla możliwości usuwania pojazdów pozostawionych niezgodnie z przepisami na koszt operatora.  Od wielu lat problem nieprawidłowo zaparkowanych hulajnóg jest przedmiotem zgłoszeń kierowanych do Rady przez mieszkańców oraz organizacje reprezentujące osoby z niepełnosprawnościami. Pozostawiane na chodnikach hulajnogi stanowią istotną barierę w samodzielnym i bezpiecznym poruszaniu się po przestrzeni publicznej.  Najczęstsze problemy zgłaszane przez osoby z niepełnosprawnościami to:  - blokowanie chodników i ciągów pieszych, utrudnienia dla osób niewidomych i słabowidzących korzystających z białej laski lub psa przewodnika, dla których nieprawidłowo pozostawiona hulajnoga może stanowić poważne zagrożenie, - ograniczenie możliwości bezpiecznego poruszania się osób korzystających z wózków, balkoników i kul, - blokowanie dojść do przejść dla pieszych, przystanków komunikacji publicznej, pochylni oraz wind, - pogorszenie dostępności przestrzeni publicznej dla wszystkich mieszkańców.  Powiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach od początku angażuje się w działania na rzecz poprawy bezpieczeństwa i dostępności przestrzeni miejskiej. Rada uczestniczyła w przygotowaniu spotu edukacyjnego dotyczącego prawidłowego parkowania hulajnóg, stworzonego wspólnie z uczniami kieleckiego liceum im. Norwida i emitowanego w pojazdach komunikacji miejskiej. Wybór młodzieży jako współtwórców kampanii nie był przypadkowy – to właśnie ona najczęściej korzysta z hulajnóg elektrycznych, dlatego uznaliśmy, że działania edukacyjne prowadzone z udziałem młodych ludzi mogą najskuteczniej kształtować właściwe postawy użytkowników.  Doceniamy znaczenie edukacji i uważamy, że powinna być ona nadal rozwijana. Dotychczasowe doświadczenia pokazują jednak, że same kampanie informacyjne nie rozwiązują problemu. Konieczne jest wprowadzenie skutecznych rozwiązań systemowych.  Powiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach popiera tworzenie wyznaczonych stref parkowania hulajnóg, które uporządkują przestrzeń publiczną i ułatwią korzystanie z niej wszystkim użytkownikom. Jednocześnie za niezbędne uznajemy wyposażenie samorządów w skuteczne narzędzia egzekwowania przepisów, w tym możliwość usuwania hulajnóg pozostawionych niezgodnie z przepisami na koszt operatora. To operatorzy, jako podmioty prowadzące działalność gospodarczą i czerpiące z niej korzyści, powinni ponosić odpowiedzialność za sposób funkcjonowania swoich usług oraz za \\fzapewnienie, że nie będą one ograniczać prawa innych osób do bezpiecznego korzystania z przestrzeni publicznej.  Powiatowa Społeczna Rada ds. Osób Niepełnosprawnych w Kielcach wyraża pełne poparcie dla proponowanych zmian i apeluje o ich przyjęcie. Jesteśmy przekonani, że nowe przepisy będą ważnym krokiem w kierunku poprawy bezpieczeństwa, zwiększenia dostępności przestrzeni publicznej oraz lepszej ochrony praw osób z niepełnosprawnościami. \\t\\n\\tArt. 3 pkt 3 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 3 zmiana 3) w art. 130a: Z analogicznego powodu jak wyżej proponujemy nową treść pkt. 8.  „8) pozostawienia, z naruszeniem art.7 ust. 3a, pojazdu lub urządzenia przeznaczonego do indywidualnego przemieszczania się na krótkich dystansach w ramach mikromobilności dzielonej, poza miejscem wyznaczonym do tego celu przez zarządcę drogi.”\\t\\n\\tArt. 8 projektu ustawy\\tPolski Związek Szkoleniowy\\tW art. 8 proponujemy wykreślić zdanie drugie. Jest to tzw. masło maślane w kontekście zdania 1.  \\t\\n\\tArt. 8 projektu ustawy\\tLiga Obrony Kraju\\tW Art. 8: Projekt zachowuje bezterminowo pozytywny wynik egzaminu z części teoretycznej dla osób które zdały egzamin przed zmianą przepisów. Z tych samych powodów dla których wprowadzono ograniczenie 24 miesięcy proponujemy w tym artykule wpisać ograniczenie, że pozytywny wynik egzaminu z części teoretycznej zachowuje ważność ale tylko przez 24 miesiące od wejścia w życie proponowanych zmian. Prawa nabyte nie powinny być naruszane ale z ważnych powodów jest to dopuszczalne. Precedens mamy nawet w przypadku bezterminowych praw jazdy, które jednak będą musiały być wymieniane. Osób które ewentualnie ucierpią na takiej zmianie raczej nie będzie zbyt wiele w naszej ocenie.\\t\\n\\tArt. 8 projektu ustawy\\tZrzeszenie Międzynarodo-wych Przewoźników Drogowych w Polsce\\tZastrzeżenia budzi jednak art. 8 projektu, przewidujący bezterminowe zachowanie ważności pozytywnych wyników egzaminu teoretycznego uzyskanych przed wejściem ustawy w życie. Projektodawca uzasadnia to potrzebą ochrony uzasadnionych oczekiwań osób, które przystępowały do egzaminu w przekonaniu o bezterminowej ważności jego wyniku. Bardziej wyważonym rozwiązaniem byłoby przyjęcie, że wyniki te zachowają ważność przez 24 miesiące od dnia wejścia nowych przepisów w życie. Taki okres przejściowy zapewniłby \\fzainteresowanym realną możliwość zakończenia procesu uzyskiwania uprawnień, a jednocześnie pozwoliłby zachować spójność regulacji z przyjętym przez projektodawcę założeniem, zgodnie z którym wiedza kandydata powinna pozostawać aktualna.\\t\\n\\tPrzepisy przejściowe \\tWielkopolskie Stowarzyszenie OSK i Instruktorów\\tw przepisach przejściowych dodać, że wymóg 3 lat prawa jazdy nie dotyczy osób, które przed wejściem w życie przepisów rozpoczęły kurs na instruktora nauki jazdy. \\t\\n\\tPrzepisy przejściowe\\tPolski Związek Niewidomych\\t5. Przegląd istniejących miejsc postojowych Aktualna propozycja zawarta w UD402 Projekt przewiduje wejście w życie przepisów dotyczących mikromobilności dzielonej 1 stycznia 2028 r., ale nie nakłada obowiązku przeglądu miejsc postojowych wyznaczonych przed tą datą. Propozycja PZN W przepisach przejściowych projektu proponuje się dodać przepis: „Zarządcy dróg, na których przed dniem wejścia w życie art. 2 i art. 3 pkt 1–3 niniejszej ustawy wyznaczono miejsca postoju pojazdów lub urządzeń udostępnianych w ramach mikromobilności dzielonej, dokonają, do dnia 31 grudnia 2027 r., przeglądu tych miejsc pod względem bezpieczeństwa i dostępności ruchu pieszych oraz dostosują je do wymagań wynikających z ustawy i przepisów wykonawczych.”. Uzasadnienie Bez przepisu przejściowego istniejące miejsca mogą być nadal wykorzystywane mimo ich nieprawidłowej lokalizacji. Okres poprzedzający wejście ustawy w życie powinien zostać wykorzystany nie tylko na dostosowanie aplikacji operatorów, ale także na dostosowanie infrastruktury.  \\t\\n\\t Art. 10 projektu ustawy\\t Fundacja Vis Maior Pies Przewodnik\\t Poparcie zmiany prawnej Raz jeszcze pragniemy wyrazić nasze poparcie dla wprowadzenia obowiązku parkowania hulajnóg elektrycznych na wynajem wyłącznie w miejscach wyznaczonych. To konieczny krok, by wzmocnić bezpieczeństwo wszystkich uczestników ruchu drogowego, w tym pieszych ze szczególnymi potrzebami. Konieczność pilnego procedowania Art. 10 pkt 2 projektu ustawy UD402 przewiduje, że obowiązek parkowania hulajnóg elektrycznych na wynajem wejdzie w życie 1 stycznia 2028 roku. Postulujemy maksymalne możliwe skrócenie tego okresu i, o ile będzie to możliwe, wejście w życie zmian od 1 lipca 2027 roku. Oznacza to konieczność pilnego procedowania projektu. Mamy jednak nadzieję, że postulat ten zostanie przez Pana Ministra uwzględniony z uwagi na fakt, że proponowane przepisy regulują kwestie istotne dla bezpieczeństwa uczestników ruchu drogowego.\\t\\n\\tArt. 10 projektu ustawy\\tPolski Związek Szkoleniowy\\t17) W art. 10 w pkt 1 i pkt 3 wymieniony jest art. 1 pkt 11. Obydwa punkty mają zasadniczo inną datę wejścia w życie. Trzeba podjąć jednoznaczną decyzję w jakim terminie wchodzi w życie przepis art. 1 pkt 11.  \\t\\n\\tArt. 10 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 6) \\tchciałbym przekazać swoje uwagi do projektu o numerze UD402.\\n\\nPo pierwsze, mam wątpliwości czy termin wejścia w życie ustawy (w projekcie 1 stycznia 2027 r.) jest realnym terminem. Konsultacje projektu zakończą się pod koniec lipca, następnie projekt musi zostać jeszcze przyjęty przez stały komitet RM, komisje prawniczą, a także przez Radę Ministrów. Następnie przynajmniej 6 tygodni w obu izbach Parlamentu, 21 dni na podpis Prezydenta RP i kilka dni na publikację w Dzienniku Ustaw RP.\\nProszę rozważyć czy ten termin jest rzeczywiście realny. Ja bym jednak proponował jego zmianę na 1 lutego, bądź 1 marca.\\n\\nNastępnie, uważam, że termin wejścia w życie rejestracji egzaminów państwowych każdej kategorii należy przesunąć na 1 lipca 2027 r., i tym samym ujednolicić z wejściem w życie rejestracji egzaminów wewnętrznych. Zamówienie urządzeń do rejestracji zajmuje pewien \\fczas, a następnie trzeba te urządzenia zamontować oraz skonfigurować.\\n\\nZ wyrazami szacunku,\\nAdrian Piotrkowski \\t\\n\\tArt. 10 projektu ustawy\\tOsoba fizyczna (zgłoszenie nr 7)\\tProjektowany przepis wprowadzający sztywny, półroczny termin na ukończenie kursu oraz rozpoczęcie procedury egzaminacyjnej przez kandydatów na instruktorów jest rozwiązaniem całkowicie oderwanym od realiów rynkowych oraz administracyjnych. W praktyce przepis ten drastycznie ograniczy obywatelom możliwość uzyskania uprawnień zawodowych, co rodzi poważne wątpliwości natury konstytucyjnej. ​Wprowadzenie tak krótkiego ramu czasowego jest wadliwe z dwóch kluczowych powodów: ​Paraliż proceduralny a odpowiedzialność kandydata: Proces szkolenia wymaga czasu, jednak największym problemem jest sama procedura egzaminacyjna. Terminy egzaminów państwowych są wyznaczane przez Wojewódzkie Ośrodki Ruchu Drogowego (WORD) z dużym opóźnieniem. Kandydat nie ma żadnego wpływu na opieszałość aparatu urzędniczego. Narzucenie limitu sześciu miesięcy oznacza, że obywatel poniesie finansowe i czasowe konsekwencje niewydolności systemu organizowanego przez państwo. ​Naruszenie Konstytucji RP: Rozwiązanie to stoi w sprzeczności z zasadą państwa prawa (art. 2 Konstytucji RP), a w szczególności z wywodzoną z niej zasadą zaufania obywatela do państwa i stanowionego przez nie prawa oraz zasadą proporcjonalności. Prawo nie może wymagać od obywatela rzeczy niemożliwych ani karać go (poprzez przepadnięcie kursu) za opóźnienia leżące po stronie organów egzaminacyjnych. Ponadto regulacja ta w sposób nieuzasadniony ogranicza wolność wyboru i wykonywania zawodu (art. 65 ust. 1 Konstytucji RP). ​Wniosek: Termin ten należy wydłużyć (co najmniej do 12 miesięcy) lub całkowicie wyłączyć z niego czas oczekiwania na wyznaczenie terminów egzaminów przez WORD. W obecnym kształcie przepis ten jest rażąco niesprawiedliwy i podatny na zaskarżenie do Trybunału Konstytucyjnego.\\n\\t\\n\\t Uwagi dodatkowe \\t Związek Pracodawców „Transport i \\fLogistyka Polska”\\t  Zaproponowane zmiany odnoszą się przede wszystkim do narzędzi, procedur i instrumentów formalnego nadzoru, pozostawiając na uboczu dużo ważniejsze kwestie takie jak:  \\fpodniesienie kompetencji oso b prowadzących szkolenie oraz oso b sprawdzających kwalifikacje;  zmiana zasad i sposobu prowadzenia szkolenia oso b ubiegających się o uprawnienia do kierowania, w celu ich dostosowania do wspo łczesnych standardo w, obowiązujących w krajach o znacznie wyz szym poziomie bezpieczen stwa ruchu drogowego niz Polska oraz dostosowania do rozwoju technicznego w zakresie motoryzacji, infrastruktury drogowej, etc.;  gruntowna zmiana zasad i sposobu przeprowadzania egzaminu państwowego tak, aby przestał on byc swoistą „sztuką dla sztuki”, a stał się faktycznym sprawdzianem wiedzy i umiejętnos ci, potrzebnych do bezpiecznego uczestnictwa w ruchu drogowym (proponowana likwidacja placu manewrowego jest krokiem w dobrym kierunku, ale niestety to tylko jeden z wielu elemento w wymagających korekty);  potrzeby polskiej gospodarki narodowej, kto ra w duz ej mierze zawdzięcza swo j rozwo j branz y transportu drogowego (jedynej polskiej branz y, kto ra jest liderem /pierwsze miejsce/ na jednolitym unijnym rynku), a kto ra napotkała mocną barierę rozwoju, związaną z brakiem wykwalifikowanych kierowco w.   Z zaskoczeniem i niepokojem przyjęliśmy, że znaczna część propozycji nie została - w ocenie TLP - uzasadniona pogłębionymi badaniami, analizą dobrych praktyk, ani opracowaniami naukowymi. Projekt nie wyjaśnia również w dostatecznym stopniu, w jaki sposób dobierano ekspertów, uczestniczących w pracach zespołu działającego przy resorcie infrastruktury, który opracował założenia przedstawionego do konsultacji projektu. 2   Poważne wątpliwości budzi także brak przedstawienia pełnej analizy kosztów wdrożenia proponowanych rozwiązań. Dla przykładu, TLP szacuje, że obsługa „cyfrowej karty kursanta” może generować po stronie branży szkoleniowej, a pośrednio jej klientów, koszty sięgające co najmniej 100 mln zł rocznie. W dokumentacji projektu nie przedstawiono odrębnych analiz kosztów i korzyści, dotyczących poszczególnych propozycji.  Na dodatek, część zaproponowanych rozwiązań wydaje się nam całkowicie sprzeczna z deklarowanymi przez Prezesa Rady Ministrów działaniami na rzecz deregulacji (przykładem może być wspomniana wyżej „cyfrowa karta kursanta” i nałożone zarówno na instruktorów, jak i osoby szkolone, liczne obowiązki związane z jej obsługą – gdzie wszelkie formalne \\fpomyłki skutkować będą podwyższonym ryzykiem utraty uprawnień zawodowych lub likwidacji prowadzonej działalności gospodarczej). Zamiast ułatwiać dostęp do kursów prawa jazdy, wprowadzają one skomplikowane procedury, stanowiące nieuzasadnione bariery administracyjne dla podmiotów szkoleniowych i kursantów, a także dla organów administracji, zaangażowanych w system szkolenia kierowców.  Niemniej liczymy, że resort infrastruktury uwzględni uwagi i propozycje przedkładane w trakcie konsultacji społecznych, co pozwoliłoby usunąć przedłożone wyżej zastrzeżenia. Szczególnie, że z kalendarza wyborczego wynika, że ewentualne późniejsze działania legislacyjne, mające na celu wyjście naprzeciw uwagom i propozycjom składanym pod adresem zmian w szeroko rozumianym systemie uzyskiwania uprawnień do kierowania pojazdami, skazane mogą być na niepowodzenie. Może to wywołać negatywny odbiór społeczny, szczególnie wśród środowisk, związanych zawodowo z transportem i ruchem drogowym.  Dlatego też, przed przejściem do szczegółowej analizy i uwag związanych z propozycjami zawartymi w projekcie, chciałbym w imieniu TLP, wskazać pakiet konkretnych propozycji, których wdrożenia oczekiwalibyśmy przy okazji tej inicjatywy legislacyjnej. Propozycje te w dużej części związane są z wynikami badania przeprowadzonego przez TLP w sierpniu 2023 roku „Ocena rynku szkoleń zawodowych kierowców”. Raport z badania został przekazany do wiadomości resortu infrastruktury w tym samym roku. Raport pokazał bardzo krytyczną ocenę systemu uzyskiwania uprawnień (szkolenia i egzaminowania) w zakresie wyższych kategorii praw jazdy (kategoria C1 C1+E, C, C+E, D1, D1+E, D, D+E).  Dla przykładu, kilka wybranych liczb z ww. raportu. 46% respondentów badania określiło stopień umiejętności i wiedzy osób, uzyskujących uprawnienia do kierowania ciężkimi samochodami do przewozu rzeczy lub autobusami, jako żaden lub niedostateczny. Co charakterystyczne, aż 61% respondentów określiło umiejętności w zakresie korzystania z pełnej funkcjonalności współczesnych pojazdów, jako żadne lub niedostateczne. To tylko wybrane wyniki tego badania, niemniej dobitnie pokazują patologie obecnego systemu.  Część z zamieszonych niżej propozycji, ma na celu także usunięcie barier jakie napotykamy w trakcie procesu rekrutacji kierowców, szczególnie w zakresie procedur związanych z wydawaniem wymaganych od kierowców dokumentów.\\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\tPropozycje TLP do projektu ustawy 1) Modyfikacja przepisów określających warunki uzyskania polskiego krajowego prawa jazdy.  Polski przewoźnik (pracodawca) rekrutując pracownika z zagranicy na czas określony (np. na jeden rok) nie może przed upływem 6 miesięcy, uzyskać dla tego pracownika odpowiednich polskich uprawnień do kierowania pojazdami (pracownik nie może przystąpić do szkolenia, do dodatkowego egzaminu, ani uzyskać wymiany zagranicznych uprawnień na polskie krajowe uprawnienia). Ponieważ zezwolenie na pracę dotyczy zatrudnienia na konkretnym stanowisku pracy (np. kierowca wykonujący przewozy międzynarodowe), przez 6 miesięcy sprowadzony pracownik nie może legalnie uzyskać środków utrzymania, a tym samym, koszty jego pobytu obciążają pracodawcę. I to pomimo, że po uzyskaniu zezwolenia na pobyt i pracę, pracownik jest związany z terytorium Polski przez okres dłuższy niż 6 miesięczny okres karencyjny określony w unijnych przepisach. Stąd, nasz postulat wprowadzenia odpowiedniego przepisu uznającego, iż warunek pobytu w Polsce przez co najmniej 6 miesięcy jest spełniony, o ile osoby ubiegające się o polskie uprawnienia, mają odpowiednie zezwolenie na pobyt i pracę przez okres dłuższy niż 6 miesięcy.  Dlatego też proponujemy w art.11 ustawy z dnia 5 stycznia 2011 r. o kierujących pojazdami (UoKP) po ust. 1 dodanie ust. 1c w brzmieniu:  „1c. Warunek o którym mowa w ust. 1, uważa się za spełniony przez cudzoziemca, który otrzymał odpowiednie zezwolenie na pobyt i pracę na terytorium Rzeczypospolitej Polskiej na okres dłuższy niż 6 miesięcy.”.  Jedną z zasad obowiązujących przy wymianie zagranicznego prawa jazdy jest uwzględnianie terminów ważności przypisanym poszczególnym kategoriom prawa jazdy. W praktyce oznacza to, że jeżeli zagraniczne prawo jazdy nie zawiera tych terminów, to starostowie odmawiają ich wymiany. W naszej ocenie jest to luka prawna, stwarzająca kolejną formalną barierę w przypadku rekrutacji pracowników z innych państw.  Dlatego też proponujemy w art. 14 UoKP dodanie ust. 2g w brzmieniu:  „2g. Jeżeli ważne krajowe prawo jazdy wydane w państwie innym niż państwo członkowskie Unii Europejskiej, Konfederacja Szwajcarska lub państwo członkowskie Europejskiego Porozumienia o Wolnym Handlu (EFTA) — strona umowy o Europejskim Obszarze Gospodarczym — nie określa terminów ważności poszczególnych kategorii, to terminy ważności wydawanego polskiego krajowego prawa jazdy, ustala się zgodnie z art. 13 ust. 1 i 2.”.  \\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t2) Podniesienie kompetencji instruktorów i egzaminatorów w zakresie wyższych kategorii prawa jazdy  Nie rozstrzygając w tym miejscu o kompleksowych, docelowych rozwiązaniach, dotyczących kompetencji osób szkolących i sprawdzających kwalifikacje w zakresie wszystkich kategorii prawa jazdy, TLP stoi na stanowisko, że za zbyt niski stopień przygotowania osób uzyskujących uprawnienia do kierowania pojazdami w zakresie wyższych kategorii prawa jazdy (C, C+E, D, D+E) odpowiada brak dostatecznych kompetencji po stronie instruktorów i egzaminatorów, w zakresie realnej praktyki w kierowaniu nowoczesnym pojazdem i w wykonywaniu zadań, jakie powinni wykonywać zawodowi kierowcy. Są to rażące braki, zważywszy, iż instruktorzy są także uprawnieni do prowadzenia szkolenia w zakresie kwalifikacji wstępnej i szkoleń okresowych, o których mowa w ustawie z dnia 6 września 2001 roku o transporcie drogowym (UoTD).  Aby podnieść poziom przygotowania tych osób, proponujemy, aby instruktorzy i egzaminatorzy w zakresie wyższych kategorii prawa jazdy, spełniali odpowiednie wymagania stawiane kierowcom wykonującym przewóz drogowy, wynikające z art. 39a UoTD, oraz posiadali udokumentowane doświadczenie w kierowaniu i użytkowaniu nowoczesnych pojazdów, wykorzystywanych w przewozach drogowych - przykładowo co najmniej sześciomiesięczne doświadczenie na stanowisku kierowcy albo odpowiadający mu staż praktyczny.  Dlatego też w proponujemy:  - w art. 33 UoKP po ust. 1a dodanie ust. 1b w brzmieniu:  „1b. Dodatkowym wymogiem wobec instruktorów prowadzących szkolenie w zakresie prawa jazdy kategorii C, C+E, D lub D+E jest:  1) spełnienie warunków, o których mowa w art. 39a ustawy z dnia 6 września 2001 r. o transporcie drogowym,  2) wykazanie się co najmniej 6 miesięcznym:  a) zatrudnieniem na stanowisku kierowcy wykonującego przewóz drogowy, w wymiarze co najmniej połowy pełnego czasu pracy, lub  \\fb) stażem w przedsiębiorstwie wykonującym przewóz drogowy, na stanowisku kierowcy, dyspozytora lub spedytora.”   - w art. 58 UoKP po ust. 1 dodanie ust. 1a w brzmieniu:  „1a. Dodatkowym wymogiem wobec egzaminatorów dokonujących sprawdzenia kwalifikacji w zakresie prawa jazdy kategorii C, C+E, D lub D+E jest:  1) spełnienie warunków, o których mowa w art. 39a ustawy z dnia 6 września 2001 r. o transporcie drogowym,  2) wykazanie się co najmniej 6 miesięcznym:  a) zatrudnieniem na stanowisku kierowcy wykonującego przewóz drogowy, w wymiarze co najmniej połowy pełnego czasu pracy,  b) stażem w przedsiębiorstwie wykonującym przewóz drogowy, na stanowisku kierowcy, dyspozytora lub spedytora.” nauki jazdy osób ubiegających się o prawo jazdy kategorii innej niż kategoria C, C+E, D lub D+E,   - w art. 39a ust. 3 pkt 7 UoTD wprowadzenie następujących zmian:  1) lit. a otrzymuje brzmienie:  2) uchyla się lit. b,  3) lit. c otrzymuje brzmienie:  przeprowadzania państwowego egzaminu dla osób ubiegających się o prawo jazdy kategorii innej niż kategoria C, C+E, D lub D+E;”  \\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t3) Skrócenie okresu oczekiwania na uzyskanie wymaganych dokumentów uprawniających do kierowania i wykonywania zawodu kierowcy  Obecnie uzyskanie dokumentów wymaganych do kierowania pojazdem i wykonywania zawodu kierowcy, wymaga udziału kilku organów i podmiotów oraz, co do zasady, kolejnego przechodzenia poszczególnych procedur. Prawo jazdy wydaje właściwy organ administracji, karta kierowcy do tachografu jest wydawana przez PWPW S.A., natomiast świadectwo kierowcy - przez Głównego Inspektora Transportu Drogowego. Mimo odrębności tych procedur, część danych źródłowych się powtarza. Na dodatek, dane te są w dyspozycji tego samego podmiotu (PWPW S.A.). Stąd - w naszej ocenie - procesy uzyskania tych dokumentów, można prowadzić równoległe, bez naruszenia prawa UE.  Dlatego też proponujemy, aby świadectwo kierowcy było wydawane:  \\fbez konieczności przedkładania prawa jazdy z kodem 95 (lub karty kierowcy) lub alternatywnie,  na podstawie przedłożonych wymaganych orzeczeń (lekarskiego i psychologicznego) i świadectwa kwalifikacji zawodowej.   W tym drugim wariancie, należałoby dodatkowo wskazać, że jeżeli kierowca ma już ważne, wydane w innym państwie członkowskim UE, prawo jazdy lub kartę kwalifikacji z kodem 95, to może je przedłożyć, zamiast świadectwa kwalifikacji zawodowej.  W przypadku wniosku o wydanie karty kierowcy do tachografu cyfrowego proponujemy, aby zamiast prawa jazdy, w przypadku gdy kierowca złożył wniosek o jego wydanie, wniosek mógł 5   zawierać numer Profilu Zawodowego Kierowcy, który posiada PWPW S.A.. W tej sytuacji PWPW S.A. mogłaby w tym samym dniu, wysłać kierowcy zarówno kartę do TC, jak i personalizowane prawo jazdy.  Dlatego też proponujemy m.in.:  - w art. 32b ust. 5 UoTD nadać pkt 2 brzmienie:  „2) zaświadczenie o zatrudnieniu kierowcy;”  (ta wersja propozycji TLP wynika z faktu, że zgodnie z art. 39f oraz zgodnie z przepisami dyrektywy Parlamentu Europejskiego i Rady (UE) 2022/2561 spełnienie wymagań, o których mowa w art. 39a ust. 1 pkt 5 i 6 UoTD dokumentowane jest kodem 95 w prawie jazdy lub w karcie kwalifikacji kierowcy, bez których kierowca nie może wykonywać przewozów drogowych. Stąd nie ma potrzeby dublowania tych wymagań w świadectwie kierowcy)  Alternatywnie  - w art. 32b UoTD proponujemy:  1) w ust. 5 pkt 2 otrzymuje brzmienie:  „2) zaświadczenie o zatrudnieniu kierowcy oraz kopie:  wymaganych orzeczeń:   - lekarskiego o braku przeciwwskazań zdrowotnych do wykonywania pracy na stanowisku kierowcy,  - psychologicznego o braku przeciwwskazań psychologicznych do wykonywania pracy na stanowisku kierowcy;  \\fwymaganego świadectwa kwalifikacji zawodowej;”;   2) po ust. 4 dodaje się ust. 4a w brzmieniu:  „4a. Wymóg, o którym mowa w ust. 5 pkt 2 lit. c uznaje się za spełniony, jeżeli do wniosku dołączona zostanie kopia ważnego krajowego prawa jazdy wydanego w innym państwie członkowskim z kodem 95 w zakresie odpowiedniej kategorii.”\\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t4) Wprowadzenie przyśpieszonej ścieżki uzyskiwania prawa pobytu i pracy dla zrekrutowanych lub już obecnie pracujących na rzecz polskiego przewoźnika kierowców spoza UE  Największym problemem, barierą i wyzwaniem jest strukturalny brak kierowców na polskim rynku pracy. Już w 2017 roku prognozy zawarte w raporcie PWC/TLP „Rynek pracy kierowców w Polsce” przewidywały, iż w latach 2025 i następnych zabraknie nam około 320 tysięcy pracowników wykonujących przewozy drogowe. Tej katastrofie udało się częściowo zapobiec, sukcesywnie zatrudniając kierowców spoza UE. I tak, w 2023 roku pracowało w polskich firmach około 165 tysięcy zagranicznych kierowców, co pozwoliło częściowo zrekompensować przewidywania z 2017 roku. Obecnie, na skutek zaostrzenia polityki migracyjnej, w porównaniu z rokiem 2023 utraciliśmy około 20 tysięcy pracowników z zagranicy. TLP szacuje, że w 2026 roku brakuje nam około 120 tysięcy pracowników w tym zawodzie. I jest to problem, wynikający nie tyle z niskich zarobków (przeciętne wynagrodzenie w międzynarodowym transporcie drogowym wynosi od 8 do 10 tysięcy złotych netto), co problem strukturalny, charakterystyczny dla każdego kontynentu. Na dodatek, w coraz większym tempie tracimy dotychczas zatrudnionych kierowców spoza UE, którzy oczekują na przedłużenie prawa pobytu i pracy nawet do 18 miesięcy. Ich sytuacja różni się zasadniczo od innych grup zawodowych, gdyż pracując w usługach transgranicznych, nie mogą się wykazać odpowiednimi dokumentami pozwalającymi przekraczać granice wewnętrzne strefy Schengen (te dostaną bowiem po upływie nawet 1,5 roku od dnia, w którym złożono wniosek o odpowiednie zezwolenie). Pozostałe grupy pracowników spoza UE, wykonujące zawody nie wymagające przekraczania granic, mogą legalnie kontynuować pracę na podstawie potwierdzenia złożenia wniosku o przedłużenie prawa pobytu i pracy.  Dlatego też, nie ingerując w wynikające z polityki migracyjnej Rządu zasady przyznawania prawa pobytu i pracy, ta najliczniejsza grupa zawodowa, wymaga pierwszeństwa („fast track”) w rozpatrywaniu wniosków w tych sprawach. Jest to zgodne z interesem polskiego \\frynku pracy, aby w pierwszej kolejności pracę otrzymywały osoby, niestanowiące konkurencji dla polskich bezrobotnych.  Stąd też wnioskujemy o przyjęcie przepisów (lex specialis), pozwalających na skorzystanie dla tej grupy zawodowej, z tzw. szybkiej ścieżki, przewidzianej w ustawie z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej oraz w ustawie z dnia 12 grudnia 2013 r. o cudzoziemcach.  Dlatego też proponujemy - w rozdziale 7a UoTD, dodanie art. 39o w brzmieniu:  „Art. 39o. 1. Minister właściwy do spraw transportu w porozumieniu z ministrem właściwym do spraw gospodarki może określić, w drodze rozporządzenia, wykaz stanowisk pracy kierowców, w którym występują strukturalne niedobory kadrowe.  2. Wykaz określający grupy zawodów, w których występują niedobory kadrowe, tworzony jest na podstawie badań, analiz i ocen dotyczących potrzeb rynku pracy kierowców, a także w oparciu o znaczenie dla gospodarki narodowej oraz krajowego bilansu płatniczego poszczególnych rodzajów przewozów drogowych.  3. Przedsiębiorcom ubiegającym się o wydanie zezwolenia na pracę cudzoziemca na pracę na stanowisku określonym w wykazie, o którym mowa w ust. 1, przysługuje pierwszeństwo w rozpatrywaniu wniosków, na zasadach określonych w art. 27 pkt 1 ustawy z dnia 20 marca 2025 r. o warunkach dopuszczalności powierzania pracy cudzoziemcom na terytorium Rzeczypospolitej Polskiej.  4. Kierowcom spoza Unii Europejskiej, ubiegającym się o zatrudnienie lub zatrudnionym u przedsiębiorcy posiadającego zezwolenie na wykonywanie zawodu przewoźnika drogowego lub licencję wspólnotową, na stanowisku określonym w wykazie, o którym mowa w ust. 1, przysługuje pierwszeństwo w rozpatrywaniu wniosków o wydanie wizy, wniosków o udzielenie zezwolenia na pobyt czasowy oraz wniosków o udzielenie zezwolenia na pobyt czasowy i pracę, na zasadach określonych odpowiednio w art. 77 ust. 9a, w art. 112a ust. 3b oraz w art. 117b ustawy z dnia 12 grudnia 2013 r. o cudzoziemcach.”.\\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t5) Zmiany w egzaminie praktycznym na prawo jazdy kategorii C, C+E, D, D+E (likwidacja placu manewrowego, wyprowadzenie jazdy w ruchu kategorii C, C+E z miast na prawach powiatu)  Obecnie, część praktyczna egzaminu państwowego w zakresie prawa jazdy kategorii C, C+E, D, D+E przeprowadzana jest na placu manewrowym wojewódzkiego ośrodku ruchu drogowego oraz na drogach publicznych, położonych w mieście na prawach powiatu. Zarówno warunki placu manewrowego, jak i ruchu miejskiego, nie odpowiadają \\frzeczywistym warunkom, w jakich pracują zawodowi kierowcy w transporcie drogowym w przewozie rzeczy lub osób. Wykonywanie manewrów ciężkimi pojazdami w oparciu o stanowiska wyznaczone tyczkami powoduje, że znaczna część szkolenia przygotowującego (niestety) głównie do egzaminu państwowego, przeprowadzana jest w warunkach, w których przyszły kierowca nigdy nie będzie wykonywał jakichkolwiek manewrów. Tym samym, umiejętność wykonywania podstawowych manewrów jest nabywana przez kierowców już po uzyskaniu uprawnienia do kierowania pojazdem dla którego wymagane są wyższe kategorie prawa jazdy. Potwierdzają to powoływane wyżej wyniki badań TLP „Ocena rynku szkoleń zawodowych kierowców”, gdzie 41,5% 7    sprawdzenie podstawowych umiejętności w zakresie panowania nad pojazdem odpowiednim dla uprawnień prawa jazdy kategorii AM, A1, A2, A,  sprawdzenie umiejętności manewrowania pojazdem lub zespołem pojazdów odpowiednim dla uprawnień prawa jazdy kategorii B+E, C1, C1+E, D1, D1+E, i T;    ankietowanych wskazało, na brak umiejętności „młodych” kierowców w zakresie wykonywania podstawowych manewrów pojazdami używanymi w ich przedsiębiorstwach.  Identyczne zastrzeżenia dotyczą obecnych warunków, w których przeprowadzane jest sprawdzenie kwalifikacji w ruchu drogowym. Ich konsekwencją jest przeniesieniu głównego nacisku podczas szkolenia przyszłych kierowców na ruch miejski, co nie odpowiada rzeczywistym warunkom, w jakich ci kierowcy będą wykonywali codzienne zadania w przewozach drogowych. To ostatnie zastrzeżenie dotyczy przede wszystkim szkolenia i egzaminowania pojazdami, dla których wymagane jest prawo jazdy kategorii C i C+E. W zakresie szkolenia na kategorię D sytuacja kształtuje się bowiem w odmienny sposób, gdyż znaczna część pracy kierowców związana jest z ruchem miejskim (komunikacja miejska, przystanki komunikacji regionalnej i ponad regionalnej, etc.)  Mając na uwadze powyższą ocenę sytuacji, TLP wnioskuje o wyprowadzenie egzaminu praktycznego z placów manewrowych w zakresie kategorii C, C+E, D, D+E oraz przeprowadzanie sprawdzenia kwalifikacji na drogach publicznych, położonych poza miastem na prawach powiatu, w zakresie kategorii C i C+E.  \\fDodatkowo uważamy, że praktyczna część egzaminu państwowego w zakresie prawa jazdy kategorii B, B+E, C1, C1+E, C, C+E, D1, D1E, D, D+E powinna zawierać, jako obowiązkowy element, jazdę po autostradzie, drodze ekspresowej lub drodze dwujezdniowej o dwóch pasach ruchu dla tego samego kierunku, na których dopuszcza się prędkość co najmniej 90/km/h, a także jazdę poza obszarem zabudowanym na drodze innej, niż wskazane wcześniej drogi.  Dlatego też proponujemy w art. 51 UoKP:  - w ust. 3 pkt 1 otrzymuje brzmienie:  „1) na placu manewrowym wojewódzkiego ośrodka ruchu drogowego – w zakresie obejmującym:  2) w ruchu drogowym na drogach publicznych – w zakresie obejmującym sprawdzenie pozostałych umiejętności wymaganych podczas części praktycznej egzaminu dla uprawnień dowolnej kategorii prawa jazdy.”.  - po ust. 3 dodaje się ust. 3a w brzmieniu:  „3a. Obowiązkowym elementem części praktycznej egzaminu państwowego , o której mowa w ust. 3 pkt 2, dla uprawnień prawa jazdy kategorii B, B+E, C1, C1+E, C, C+E, D1, D1+E,, D, D+E, jest jazda:  1) autostradą, drogą ekspresową lub drogą dwujezdniową z co najmniej dwoma pasami ruchu dla każdego kierunku, na których dopuszcza się prędkość co najmniej 90/km/h;  2) drodze jednojezdniowej położonej poza obszarem zabudowanym.”.   - ust. 4b otrzymuje brzmienie:  „4b. Egzamin państwowy w zakresie prawa jazdy kategorii C, C+E, T, w części, o której mowa w ust. 3, jest przeprowadzany poza granicami administracyjnymi miasta, o którym mowa w ust. 4.”.\\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t6) Zmodyfikowanie dotychczasowych celów egzaminu państwowego osób ubiegających się o uprawnienie do kierowania pojazdem  Najważniejszym elementem systemu uzyskiwania uprawnień do kierowania pojazdami jest etap sprawdzania kompetencji i kwalifikacji uzyskiwanych w poprzedzającym ten etap procesie szkolenia. Aby mógł on prawidłowo spełniać swoje funkcje, należy prawidłowo zdefiniować jego cele, Obecne cele egzaminu państwowego zdefiniowane zostały ponad 20 lat temu w pierwszej wersji ustawy o kierujących pojazdami i były zgodne z ówczesnym \\fstanem wiedzy i przykładami najlepszej praktyki w innych państwach europejskich. Te cele zostały bez żadnych zmian przeniesione do obecnie obowiązującej ustawy, którą uchwalono prawie 15 lat temu. Od tego czasu w europejskich systemach uzyskiwania uprawnień dokonał się znaczny postęp dotyczący przede wszystkim założeń w zakresie wiedzy i umiejętności sprawdzanych podczas egzaminu osób ubiegających się o prawo jazdy. Dzisiaj jest najwyższy czas, aby uwzględnić ten postęp w polskich przepisach regulujących zakres sprawdzania kwalifikacji przyszłych kierowców.  Ponadto należy wziąć pod uwagę kierunek zmian w unijnych przepisach regulujących ten obszar. Nowa dyrektywa (UE) 2025/2205 wymaga uwzględnienia m.in. percepcji zagrożeń i podejmowania decyzji, zmęczenia i stanu psychicznego, dekoncentracji urządzeniami elektronicznymi, mikromobilności i innych niechronionych uczestników ruchu drogowego, martwych pól, pierwszej pomocy i resuscytacji krążeniowo-oddechowej, pojazdów alternatywnie zasilanych oraz zalet, ograniczeń i ryzyka ADAS i automatyzacji. W egzaminie praktycznym dyrektywa nakazuje zwracać uwagę na jazdę defensywną i społeczną.  Mając powyższe na uwadze TLP proponuje zmianę brzmienia art. 51 ust. 1 UoKP na następujące:  „1. Egzamin państwowy jest przeprowadzany w celu sprawdzenia wiedzy, umiejętności, zachowań oraz zdolności do samooceny osoby egzaminowanej, niezbędnych do samodzielnego, odpowiedzialnego, defensywnego, bezpiecznego i środowiskowo efektywnego kierowania pojazdem, w szczególności w zakresie rozpoznawania i przewidywania zagrożeń, podejmowania decyzji, ochrony niechronionych uczestników ruchu, oceny własnej sprawności psychofizycznej, zarządzania uwagą, właściwego korzystania z systemów wspomagania i automatyzacji oraz działania w sytuacji awarii lub wypadku.”  W ślad za zmianą celów egzaminu państwowego warto pokusić się o korektę form, w jakich ten egzamin się odbywa. I tu TLP proponuje następujące brzmienie przepisu art. 51 ust. 2 UoKP:  „2. Egzamin państwowy składa się z:  1) części teoretycznej, przeprowadzanej w formie testów sprawdzającej wiedzę, percepcję zagrożeń, ocenę ryzyka i podejmowanie decyzji;  2) części praktycznej, sprawdzającej umiejętności oraz zachowania osoby egzaminowanej podczas przygotowania pojazdu i kierowania nim w ruchu drogowym,”.  \\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t7) Wprowadzenie możliwości wdrażania indywidualnych/pilotażowych programów szkolenia  Obecny, sztywny program szkolenia kierowców, a także bardzo rygorystyczne określenie warunków i zasad prowadzenia zajęć, uniemożliwiają jakikolwiek postęp w tym obszarze. Każda próba przeprowadzania zajęć według innych zasad lub w innych warunkach (często nawet lepszych z punktu widzenia efektywności procesu szkolenia), traktowana jest jako naruszenie przepisów o szkoleniu, co może się skończyć odebraniem uprawnień osobom prowadzącym szkolenie lub likwidacją ośrodka szkolenia.  Dlatego też, w ocenie TLP, w przepisach projektu ustawy należałoby wprowadzić możliwość wdrażania indywidualnych/pilotażowych programów szkolenia, realizowanych na zasadach i warunkach stanowiących odstępstwo od wymagań określonych w przepisach wykonawczych.  Aby zachować kontrolę nad wdrażaniem tego typu programów (i zagwarantować realizację określonych w ustawie celów szkolenia), takie programy mogłyby być wdrażane za zgodą projektowanego „centrum egzaminowania”, po złożeniu odpowiedniego wniosku przez zainteresowany ośrodek szkolenia kierowców. Oczywiście po uprzedniej korekcji założeń funkcjonowania tego centrum tak, aby usunąć wszystkie, wskazane dalej w opinii TLP, problemy o charakterze prawnym.  Doświadczenia z takich indywidualnych/pilotażowych programów mogłyby stanowić doskonały materiał do wykorzystania w przyszłych zmianach polskiego systemu szkolenia.\\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t8) Wprowadzenie jednolitych, powszechnie stosowanych standardów nauczania i sprawdzania kwalifikacji kierowców  Podczas sprawdzania kwalifikacji osób ubiegających się o uprawnienia do kierowania, oceniane jako prawidłowe zachowanie kierującego pojazdem, w zakresie przygotowania pojazdu do ruchu, techniki kierowania pojazdem, czy też odpowiedniego zachowania (np. sposób obserwacji i reakcji na zmienne warunki ruchu), wynika z wewnętrznych ustaleń w danym wojewódzkim ośrodku ruchu drogowego, województwie czy też w regionie. Ta uwaga dotyczy oczywiście kwestii nie uregulowanych prawnie.  Prowadzi to do sytuacji w której używane są niejednolite w skali całego kraju, niejasne kryteria oceny. Przenosi się to na sposób szkolenia kierowców, gdzie naucza się pod kątem wymagań i kryteriów oceny stosowanych w danym WORD-zie, gdzie będzie składać egzamin zainteresowana osoba. Opinia publiczna mówi wprost o szkole krakowskiej, warszawskiej etc.  \\fWymaga to - w ocenie TLP – odpowiedniej reakcji. Konieczne jest ustanowienie jednolitych standardów w zakresie przygotowania pojazdu do ruchu, techniki jazdy i zachowania w ruchu drogowym, nauczanych podczas szkolenia i sprawdzanych podczas egzaminu państwowego. Na zasadach podobnych, jak te obowiązujące w wielu europejskich państwach. Przykładem może być Wielka Brytania, gdzie podobne standardy ustala Driver and Vehicle Standards Agency (DVSA). Oficjalnym standardem jest National Standard for Driving Cars and Light Vans (Category B), a odpowiadającym mu aktualnym podręcznikiem branżowym — The Official DVSA Guide to Driving – the Essential Skills. W przypadku techniki jazdy punktem odniesienia jest natomiast Roadcraft: The Police Driver’s Handbook.  Proponujemy, aby nadać podobne kompetencje (tworzenia obowiązujących standardów) proponowanemu w projekcie Centrum Egzaminowania. Krytycznie oceniamy natomiast znajdujące się w tekście opiniowanego projektu rozwiązanie przypisujące szereg zadań w zakresie ustalania celów szkolenia i egzaminowania. Cele powinny określać normy prawne! Natomiast Centrum powinno się zajmować określaniem szczegółowych sposobów ich osiągania (wytyczne, standardy, podręczniki etc.).\\t\\n\\t Uwaga dodatkowa\\t Związek Pracodawców „Transport i Logistyka Polska”\\t 9) Ułatwienia dla cudzoziemców podczas egzaminu państwowego i testu kwalifikacyjnego  Coraz więcej cudzoziemców spoza Unii Europejskiej przebywających na terytorium Rzeczypospolitej Polskiej podejmuje pracę na rzecz polskiej gospodarki. Znaczna część z tych osób, do wykonywania zadań służbowych związanych z pracą zawodową, potrzebuje uprawnień do kierowania pojazdem. Wśród licznych problemów i barier wskazywanych przez te osoby oraz przez ich pracodawców, znajduje sią bariera językowa, jaką napotykają podczas egzaminów państwowych sprawdzających kwalifikacje osób ubiegających się o uprawnienia do kierowania pojazdami silnikowymi lub kończącego kwalifikację wstępną testu kwalifikacyjnego. W innych państwach członkowskich UE rozwiązano ten problem tłumacząc pytania egzaminacyjne nawet na kilkanaście języków, związanych z narodowością osób uzyskujących prawo czasowego lub stałego pobytu na terytorium tych państw.  TLP rekomenduje przyjęcie tych dobrych praktyk, poprzez wskazanie dodatkowego zadania dla powoływanego „Centrum Egzaminowania” – opracowywania obcojęzycznych wersji pytań, stosowanych podczas egzaminu państwowego oraz podczas testu kwalifikacyjnego kierowców kończących kwalifikację wstępną. Proponowane przez TLP rozwiązanie będzie znacznie mniej kosztowne społecznie, niż zapewnianie udziału w egzaminach tłumaczy przysięgłych. Przy wyborze języków, na które będą kolejno tłumaczone pytania, należy \\fkierować się m.in. statystykami Głównego Inspektoratu Transportu Drogowego w zakresie wydawanych świadectw kierowców. W tych statystykach ujęta jest bowiem narodowość zagranicznych kierowców zatrudnionych w transporcie drogowym.\\t\\n\\tUwaga dodatkowa\\tZwiązek Pracodawców „Transport i Logistyka Polska”\\t10) Zablokowanie możliwości wydania decyzji o cofnięciu prawa jazdy ze względów formalnych, leżących po stronie instruktora lub ośrodka szkolenia kierowców  W obecnym stanie prawnym zdarzają się sytuacje, gdy w postępowaniu administracyjnym odbierane jest (często po wielu latach) prawo jazdy, w przypadku gdy doszło do uchybień przepisów ustawy o kierujących pojazdami po stronie ośrodka szkolenia kierowców lub po stronie instruktora prowadzącego szkolenie (bez winy lub bez udziału posiadacza prawa jazdy). Prawo jazdy jest odbierane, pomimo że kierowca zdał egzamin państwowy na prawo jazdy i następnie bezpiecznie (bezwypadkowo) i zgodnie z prawem (bez popełniania naruszeń), korzystał z tego uprawnienia. Często dotyczy to osób, które podjęły po uzyskania prawa jazdy pracę zawodową, jako kierowcy, która to praca stanowi jedyne źródło utrzymania dla nich i dla ich rodzin. Takie decyzje (o odebraniu prawa jazdy) są formalnie zgodne z prawem, ale w oczywisty sposób krzywdzą osobę zainteresowaną (są niesprawiedliwe, gdyż ta osoba nie miała wpływu na naruszenie OSK) i są bezsensowne z punktu widzenia celu polskich przepisów o szkoleniu i egzaminowaniu, jakim jest bezpieczeństwo ruchu drogowego (jeżdżą zgodnie z prawem i na dodatek bezwypadkowo).  Dlatego też proponujemy w art. 72 UoKP po ust. 1 dodanie ust. 1a–1e w brzmieniu:  „1a. Egzaminu państwowego przeprowadzonego z wynikiem pozytywnym nie unieważnia się z przyczyn określonych w ust. 1 pkt 1 lub 3, jeżeli łącznie są spełnione następujące warunki:  1) przyczyna unieważnienia wynika wyłącznie z naruszenia przepisów dotyczących uprawnień podmiotu prowadzącego szkolenie, uprawnień instruktora lub wykładowcy albo organizacji, zakresu, sposobu przeprowadzenia lub dokumentowania szkolenia;  2) naruszenia dopuścił się podmiot prowadzący szkolenie, osoba zarządzająca tym podmiotem, instruktor, wykładowca albo inna osoba działająca w ich imieniu;  3) osoba egzaminowana nie spowodowała naruszenia, nie uczestniczyła w nim umyślnie oraz nie wiedziała i przy zachowaniu należytej staranności nie mogła wiedzieć o jego wystąpieniu;  \\f4) przebieg egzaminu państwowego był zgodny z przepisami regulującymi sposób jego przeprowadzania, a ujawnione nieprawidłowości nie miały wpływu na jego wynik.   1b. Nie domniemywa się wiedzy ani umyślnego udziału osoby egzaminowanej w naruszeniu, o którym mowa w ust. 1a. Okoliczności wyłączające zastosowanie ust. 1a wykazuje organ prowadzący postępowanie. 11   1c. Niezależnie od ust. 1a, egzaminu państwowego przeprowadzonego z wynikiem pozytywnym nie można unieważnić z przyczyn określonych w ust. 1 pkt 1 lub 3 po upływie dwóch lat od dnia jego przeprowadzenia, chyba że osoba egzaminowana umyślnie doprowadziła do powstania przyczyny unieważnienia albo popełniła przestępstwo lub umyślnie uczestniczyła w przestępstwie pozostającym w związku z dopuszczeniem jej do egzaminu lub uzyskaniem jego wyniku.  1d. W przypadkach określonych w ust. 1a lub 1c egzamin państwowy zachowuje ważność, a uchybienie dotyczące szkolenia lub jego dokumentowania nie może stanowić podstawy odmowy wydania prawa jazdy ani wznowienia postępowania, uchylenia, zmiany, stwierdzenia nieważności lub wygaśnięcia decyzji o wydaniu prawa jazdy.”.  Ponadto proponujemy dodatkowy przepis przejściowy w brzmieniu:  „Art. x. 1. Do postępowań administracyjnych i sądowoadministracyjnych w sprawie unieważnienia egzaminu państwowego albo dotyczących decyzji o wydaniu prawa jazdy, wszczętych i niezakończonych przed dniem wejścia w życie niniejszej ustawy, stosuje się art. 72 ust. 1a–1e ustawy zmienianej w art. 1 w brzmieniu nadanym niniejszą ustawą.  2. Postępowanie zakończone przed dniem wejścia w życie niniejszej ustawy ostateczną decyzją o unieważnieniu egzaminu państwowego albo o uchyleniu, zmianie, stwierdzeniu nieważności lub wygaśnięcia decyzji o wydaniu prawa jazdy w okolicznościach określonych w art. 72 ust. 1a lub 1c ustawy zmienianej w art. 1, wznawia się na żądanie strony.  3. Żądanie, o którym mowa w ust. 2, wnosi się w terminie 12 miesięcy od dnia wejścia w życie niniejszej ustawy. Do wznowienia stosuje się odpowiednio art. 145–152 ustawy z dnia 14 czerwca 1960 r. - Kodeks postępowania administracyjnego, z wyłączeniem terminów określonych w art. 146 tego Kodeksu.”. \\t\\n\\tUwaga dodatkowa do art. 11 ust. 1a ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\t1a. Osoba ubiegająca się o wydanie prawa jazdy najpóźniej w dniu osobistego odbioru prawa jazdy we właściwym organie wydającym prawo jazdy, planowanego przekazania prawa jazdy za pośrednictwem operatora pocztowego lub w dniu przystąpienia do egzaminu państwowego, o którym mowa w art. 49 ust. 1 pkt 1 w zakresie kategorii AM, A1, A2, A, B1, B, B+E lub T:  1) spełnia wymagania, o których mowa w ust. 1 pkt 5, 2) uprzedzona o odpowiedzialności karnej za zeznanie nieprawdy lub zatajenie prawdy składa oświadczenie pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń, że posiada miejsce zamieszkania, o którym mowa w ust. 1 pkt 5. 1b. Składający oświadczenie, o którym mowa w ust. 1a pkt 2, jest obowiązany do zawarcia w nim klauzuli następującej treści: \\\"Świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia, wynikającej z art. 233 § 6 Kodeksu karnego, oświadczam, że posiadam na terytorium Rzeczypospolitej Polskiej miejsce zamieszkania, o którym mowa w art. 11 ust. 1 pkt 5 ustawy z dnia 5 stycznia 2011 r. o kierujących pojazdami.\\\" Klauzula ta zastępuje pouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń.\\\",  Uzasadnienie: Z uzasadnienia  projektu do  ustawy o zmianie ustawy Prawo o ruchu drogowym oraz niektórych innych ustaw  – jednoznacznie wynikało, że zmiana przepisu w zakresie obowiązku składania oświadczenia miała dotyczyć wymiany zagranicznych praw jazdy. Proponowane rozwiązanie miało na celu  usprawnienie procedury wydawania polskiego prawa jazdy na podstawie prawa jazdy zagranicznego. Projektowana zmiana dopuszczała złożenie wniosku o wydanie prawa jazdy przed spełnieniem wymogu rezydencji.     Biorąc pod uwagę, że wprowadzone zmiany odnoszą się do wszystkich osób nie  tylko ubiegających się  o wymianę zagranicznego prawa jazdy , ale  również o wydanie prawa jazdy kategorii AM,A1,A2, A, B1,B,B+E lub T, zachodzi potrzeba doprecyzowania zmienionego przepisu.   Nasuwają się wątpliwości: W jaki sposób odebrać oświadczenie pod odpowiedzialnością karną o posiadaniu miejsca zamieszkania o którym mowa w ust. 1 pkt 5 w przypadku planowanego przekazania prawa jazdy wnioskodawcy za pośrednictwem operatora pocztowego , \\fjeżeli osoba ubiegająca się o wydanie prawa jazdy nie złoży takiego oświadczenia w dniu przystąpienia do egzaminu? Brak podstawy prawnej do odmowy przeprowadzenia egzaminu. Brak podstawy prawnej do wydania decyzji o nadaniu uprawnienia do kierowania pojazdami.   Czy ww. oświadczenie będzie składane w dniu egzaminu przed osobą przeprowadzającą egzamin? W jaki sposób oświadczenie złożone przed egzaminatorem zostanie przekazane do organu wydającego uprawnienia do kierowania pojazdami? Czy oświadczenie złożone przed egzaminatorem, w przypadku jego przekazania do organu ewidencyjnego będzie zwalniało organ z ponownego odebrania od Strony ww. oświadczenia w przypadku odbioru osobistego prawa jazdy lub przekazania dokumentu za pośrednictwem operatora pocztowego?  Czy WORD może odmówić przeprowadzenia egzaminu osoby, która nie złoży  oświadczenia o miejscu zamieszkania w trybie art. 233 k.k.  Czy można ujednolicić zapis dotyczący składanych oświadczeń w trybie art. 233 k.k. do jednej klauzuli w brzmieniu „Świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia, wynikającej z art. 233 § 6 Kodeksu karnego” zamiast „uprzedzona o odpowiedzialności karnej za zeznanie nieprawdy lub zatajenie prawdy składa oświadczenie pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń” Różnica pomiędzy dotychczasowym sformułowaniem, że „miejsce zamieszkania znajduje się na terytorium”, a nowym brzmieniem „ posiada miejsce zamieszkania” Zmiana wzoru wniosku o wydanie prawa jazdy \\t\\n\\tUwaga dodatkowa do art. 13 ust. 1 pkt 8 ustawy o kierujących pojazdami\\tUnia Metropolii Polskich im. Pawła Adamowicza\\tStarosta z urzędu unieważnia wpis kodu 95 w prawie jazdy po uzyskaniu informacji o cofnięciu świadectwa kwalifikacji zawodowej, na podstawie którego ten wpis został dokonany, oraz: 1) informuje posiadacza prawa jazdy o unieważnieniu wpisu, w szczególności o dacie unieważnienia wpisu kodu i obowiązku wymiany prawa jazdy w terminie 60 dni od dnia unieważnienia wpisu; 2) przekazuje zaktualizowane dane prawa jazdy do centralnej ewidencji kierowców.  Uzasadnienie: \\fJak możliwe jest unieważnienie samego wpisu kodu 95 w prawie jazdy bez unieważnienia całego dokumentu?  Co w sytuacji, gdy osoba, której unieważniono wpis kodu 95 nie odbierze o tym informacji, a wykonuje przewóz drogowy?\\t\\n\\tUwagi dodatkowe \\tKrajowe Stowarzyszenie Dyrektorów Wojewódzkich Ośrodków Ruchu Drogowego\\tZagadnienia wymagające pilnego podjęcia prac  i wprowadzenia zmian przy okazji procedowanego projektu:   Art. 51 ust. 3 pkt 2- skreślenie zapisu o drogach publicznych;  Art. 55 ust. 3. Dodanie zapisu dotyczącego przerwania egzaminu praktycznego w przypadku nieprawidłowego prowadzenia przez kandydata na egzaminatora -na dzień dzisiejszy kandydat na egzaminatora w ramach praktyk ma „przeprowadzić” a nigdzie nie ma zapisu o prawidłowym przeprowadzeniu egzaminów;  Art. 56a – wprowadzenie corocznej waloryzacji wysokości opłat za prowadzenie egzaminów państwowych o wskaźnik inflacji ogłaszany przez GUS. Dodatkowo należałoby rozważyć waloryzacje opłat za inne szkolenia prowadzone przez WORDy oraz powrót do stawek jednolitych na terenie całej Polski;   Art. 56c – wprowadzenie podpunktu dotyczącego corocznej waloryzacji wynagrodzeń egzaminatorów przeprowadzających egzaminy państwowe o wskaźnik inflacji ogłaszany przez GUS;  Art. 58 ust. 1 pkt 1 – przywrócenie zapisu dotyczącego wykształcenia wyższego i dodatkowo rozważenie podniesienia wymagania z pkt 2 np. na 5 lat posiadania prawa jazdy. Powrót wykształcenia wyższego podniósłby kompetencje egzaminatorów;  Art. 58 ust. 1 pkt 8 – doprecyzowanie przepisów dotyczących rękojmi należytego wykonywania swoich obowiązków. Na dzień dzisiejszy przepis jest martwy a egzaminatorzy chronieni przez Związki Zawodowe czują się bezkarni;  Art. 59 wprowadzenie pkt 5) o treści: B jest uprawniony do egzaminowania w zakresie prawa jazdy kat AM w przypadku egzaminu realizowanego czterokołowcem lekkim – egzamin AM czterokołowcem lekkim w praktyce, poza czasem, wygląda jak egzamin w zakresie kategorii B1 oraz B a na dzień dzisiejszy WORD-y są zobowiązane do zapewnienia egzaminatora z uprawnieniami do kategorii A;   Art. 61 ust. 3 pkt 3 – modyfikacja zapisu zmniejszająca wymaganie dotyczące uczestnictwa w charakterze obserwatora egzaminów teoretycznych do 10 z równoczesnym podniesieniu do 30 w przypadku egzaminów praktycznych. Dodanie zapisu dotyczącego prawidłowego przeprowadzenia 10 egzaminów - na dzień dzisiejszy egzaminatorem może zostać osoba, która w ramach praktyk nie przeprowadziła prawidłowo ani jednego egzaminu;  Art. 62 ust. 1 – dodanie legitymacji egzaminatora do mObywatela;  Art. 64 – określenie zasad wynagradzania komisji weryfikacyjnej;  § 27. ust. 2 określenie możliwości oceny egzaminu na kat AM realizowanego czterokołowcem lekkim na tych samych zasadach co motorowerem jednośladowym w przypadku gdy ilość miejsca uniemożliwia egzaminatorowi odpowiednie warunki przebywania w pojeździe. \\nNa rynku czterokołowców lekkich przybywa pojazdów zarówno trój jak i czterokołowych, spełniających warunki homologacji L6e, w których miejsce dla pasażera znajduje się za kierowcą. Obecny formalny zapis rozporządzenia wskazuje na konieczność przeprowadzenia takiego egzaminu przez egzaminatora będącego \\nw pojeździe. W takim przypadku egzaminator nie jest w stanie zapewnić bezpieczeństwa gdyż nie ma dostępu do mechanizmów sterowania pojazdem jak \\ni siedząc z tyłu nie posiada dostatecznej widoczności. W dniu 18 kwietnia 2025 r. Departament Transportu Drogowego Ministerstwa Infrastruktury pismem znak:\\nDTD-5-1.4411.229.2025 w odpowiedzi na zapytanie jednego z producentów tego typu \\fpojazdów wyraził opinię w przedmiotowej sytuacji. Zdaniem MI egzaminator w takich sytuacjach ma prawo odmówić jazdy w pojeździe egzaminacyjnym, lecz jest to ocena/opinia a nie zapis w rozporządzeniu.    Wprowadzenie obowiązkowych zajęć w ośrodku doskonalenia techniki jazdy w ramach szkolenia podstawowego lub powrót do planowanego a ostatecznie wykreślonego szkolenia miedzy 4 a 8 – kształtowanie właściwych postaw przyszłego kierującego pod kątem właściwego przygotowania pojazdu do jazdy, warunków decydujących o zachowaniu pojazdu w warunkach specjalnych (nawierzchnia o różnej przyczepności). \\t\\n\\tUwagi dodatkowe\\tOIGOSK, LFEDERACJA, PIGOSK\\tII. W Ustawie z 5 stycznia 2011 o kierujących pojazdami, proponujemy:   1. w art. 6 ust. 2 otrzymuje brzmienie:  „2. Zespołem pojazdów, o którym mowa w ust. 1 pkt 6 lit. c, którego dopuszczalna masa całkowita przekracza 3,5 t, może kierować osoba, która odbyła wymagane szkolenie i zdała część praktyczną egzaminu państwowego, potwierdzoną wpisem do prawa jazdy”   Uzasadnienie Art.10 ust.1 lit. d Dyrektywy Parlamentu Europejskiego i Rady (UE) 2025/2205 Dziennik Urzędowy Unii Europejskiej ser. L Przewiduje trzy warianty do wyboru Państwom członkowskim: 1) Tylko szkolenie, 2) Tylko egzamin praktyczny, 3) Szkolenie + egzamin praktyczny Zdawalność dotychczas prowadzonych egzaminów państwowych bez obowiązku odbycia szkolenia jest żenująco niska i wynosi ok. 20%. Wielokrotne zdawanie egzaminu państwowego generuje dla obywateli znaczące wydatki (aktualnie ok. 250 PLN/egzamin) oraz koszty społeczne ( np. konieczność podróży do WORD, absencja w pracy itp.)   2. w art. 23 ust.2 pkt.2 dodaje się lit. d w brzmieniu: „d) na drodze ekspresowej lub autostradzie – dotyczy prawa jazdy kat. B, C, CE, D;”   Uzasadnienie Należy wprowadzić obowiązek szkolenia na drogach ekspresowych lub autostradach w zakresie kat. B, C, CE, D prawa jazdy. Nie może dłużej trwać sytuacja, gdzie wiele osób uzyskujących uprawnienia po raz pierwszy w życiu wyjeżdża na taką drogę po zdaniu egzaminu bez wcześniejszego praktycznego przygotowania. Wiele osób popełnia \\fbłędy niewłaściwego korzystania z pasu rozbiegowego, niewłaściwego zjazdu, wyprzedzania, utrzymywania odstępu, ewentualnego zawracani (korzystania z węzłów), te umiejętności chociaż nie egzekwowane na egzaminie państwowym powinny być jak najszybciej wprowadzone do programu szkolenia. Rozporządzeniem należy wprowadzać okresy przejściowe czy wyłączenia z obowiązku szkolenia na takiej drodze jeżeli odległość osk od najbliższej drogi ekspresowej lub autostrady jest większa niż np. 50 km. Jednak przy dopuszczeniu możliwości realizacji z jednym kursantem jednorazowo 4 godz. zajęć szkolenie na drogach szybkiego ruchu można z powodzeniem realizować na terenie całego kraju.   3. w art. 24 pkt.1 lit. b otrzymuje brzmienie: „b) oznakowanym kwadratową tablicą barwy niebieskiej z białą literą „L” – nie dotyczy motocykla dwukołowego i motoroweru dwukołowego. Dopuszcza się oznakowanie samochodu osobowego kwadratową nalepką barwy niebieskiej z białą literą „L”,”   Uzasadnienie W przypadku szkolenia / egzaminowania na prawo jazdy kategorii AM, A1, A2 i A zasadnym jest odstąpienie od obowiązku oznaczania pojazdu jednośladowego tablicą z literą „L” na rzecz obowiązkowej kamizelki odblaskowej z wyraźnie umieszczoną literą „L”, w którą ubrana jest osoba szkolona/ egzaminowana.. • Poprawa bezpieczeństwa ruchu drogowego – litera „L” umieszczona na kamizelce odblaskowej jest widoczna z przodu, z tyłu oraz z boków motocyklisty, dzięki czemu pozostali uczestnicy ruchu wcześniej rozpoznają, że mają do czynienia z osobą uczącą się jazdy. • Lepsza widoczność – kamizelka odblaskowa zwiększa widoczność motocyklisty zarówno w dzień, jak i po zmroku, co ma większy wpływ na bezpieczeństwo niż niewielka tablica zamocowana z tyłu motocykla. • Brak możliwości bezpiecznego montażu – wiele motocykli, szczególnie nowoczesnych, nie posiada konstrukcyjnych możliwości trwałego i bezpiecznego zamocowania tablicy „L”. Stosowane uchwyty mogą ulec uszkodzeniu lub odpaść podczas jazdy. • Ochrona motocykla – montaż dodatkowych uchwytów często wymaga ingerencji w elementy konstrukcyjne, co może prowadzić do uszkodzeń pojazdu i utraty jego walorów użytkowych. • Mniejsze ryzyko zagrożenia – wystające elementy mocujące tablicę mogą stanowić dodatkowe zagrożenie podczas wywrotki lub kolizji. • Łatwość kontroli – kamizelka z literą „L” jest łatwa do zweryfikowania przez organy kontrolne, a jednocześnie nie wymaga dodatkowego wyposażenia motocykla. • Praktyka europejska – w wielu państwach europejskich \\fstosowane są rozwiązania polegające na oznaczaniu osoby szkolonej specjalną kamizelką lub odzieżą z odpowiednim oznaczeniem, bez konieczności montowania tablic na motocyklu   4. w art.36 dodaje się ust.3 w brzmieniu: „3. Legitymacja instruktora może być udostępniana w postaci dokumentu mobilnego, o którym mowa w art. 2 pkt 7 ustawy z dnia 26 maja 2023 r. o aplikacji mObywatel.”   Uzasadnienie Pozytywne rozpatrzenie propozycji wyeliminowałoby uciążliwe perturbacje dotykające również liczne rzesze osób szkolonych ( np. wykluczenie obecności instruktora na egzaminie państwowym) w razie zagubienia, zniszczenia czy zapomnienia zabrania fizycznej postaci legitymacji instruktora Ponadto pożądane upowszechnienie się postaci mobilnej w/w dokumentów – perspektywicznie umożliwiłoby wydawanie ich postaci fizycznej wyłącznie na wniosek osoby. W takich okolicznościach znacząco zostałyby zmniejszone wydatki organów ewidencyjnych administracji publicznej zobowiązanych do nieodpłatnego wydawania omawianych dokumentów w okolicznościach np. zmiany wzorców, zmian granic administracyjnych, zmian nazw itp.   5. w art. 45 ust. 4 uchyla się 4. Decyzja, o której mowa w ust. 1, podlega natychmiastowemu wykonaniu /zakaz wykonywania działalności OSK/   Uzasadnienie Naszym zdaniem nie znajdujemy uzasadnienia faktycznego i merytorycznego dla zastosowania tak drastycznej sankcji. Ponadto rygor natychmiastowej wykonalności decyzji o zakazie prowadzenia działalności gospodarczej w zakresie OSK przede wszystkim jest bardzo dolegliwy dla osób szkolonych, które w takich okolicznościach są zmuszone do nagłego poszukiwania innych OSK   6. w art. 53 ust. 4a otrzymuje brzmienie: „4a. Praktyczna część egzaminu państwowego na wniosek osoby egzaminowanej, jest prowadzona wskazanym pojazdem ośrodka szkolenia kierowców, który prowadził szkolenie tej osoby.”  Uzasadnienie Naszym zdaniem nie ma przeszkód faktycznych i merytorycznych aby praktyczna część egzaminu państwowego w zakresie każdej kategorii prawa jazdy - na wniosek osoby egzaminowanej mogła być prowadzona wskazanym pojazdem ośrodka \\fszkolenia kierowców, który prowadził szkolenie tej osoby. Niniejsza propozycja uzasadniona jest również statystykami, które obiektywnie, bo empirycznie dowodzą wyższej zdawalności egzaminów prowadzonych pojazdami OSK oraz wyraźnej tendencji rosnącej % udziału tych egzaminów w liczbie egzaminów danej kategorii prawa jazdy, vide przywołane zobrazowania graficzne.   7. w art. 53 ust. 5 otrzymuje brzmienie: „5. Wojewódzkie ośrodki ruchu drogowego, przeprowadzając postępowanie o udzielenie zamówienia publicznego, którego przedmiotem są pojazdy do przeprowadzania praktycznej części egzaminu na prawo jazdy przygotowując dokumenty zamówienia i powołując komisję przetargową, włączają do prac przedstawicieli regionalnych organizacji zrzeszających ośrodki szkolenia kierowców, na ich wniosek, a w razie braku takich organizacji – przedstawicieli ogólnopolskich organizacji zrzeszających ośrodki szkolenia kierowców, wyrażających wolę wzięcia udziału w postępowaniu. Umowa w sprawie zamówienia publicznego na pojazdy jest zawierana przez wojewódzkie ośrodki ruchu drogowego na okres nie krótszy niż 4 lata.”   Uzasadnienie W środowisku dyrektorów WORD-ów spotykamy się ze stanowiskiem, które skutkuje akceptacją wniosku o włączenie przedstawicieli organizacji zrzeszających ośrodki szkolenia kierowców do postępowania o udzielenie zamówienia publicznego, którego przedmiotem są pojazdy do przeprowadzania praktycznej części egzaminu na prawo jazdy wyłącznie alternatywnie tj. włącza się tych przedstawicieli tylko na etapie przygotowywania dokumentów zamówienia albo tylko na etapie prac komisji przetargowej. Wielu dyrektorów dopuszcza przedstawicieli organizacji zrzeszających osk do wszystkich etapów postępowania o udzielenie zamówienia publicznego, którego przedmiotem są pojazdy do przeprowadzania praktycznej części egzaminu na prawo jazdy. Naszym zdaniem przedstawiciele organizacji zrzeszających ośrodki szkolenia kierowców powinni uczestniczyć w każdym etapie postępowania o udzielenie zamówienia publicznego, którego przedmiotem są pojazdy do przeprowadzania praktycznej części egzaminu na prawo jazdy.   8. w art. 56a ust. 2 otrzymuje brzmienie: „2. W uchwale, o której mowa w ust.1, uwzględnia się koszty rzeczowe i osobowe związane z przeprowadzaniem egzaminów państwowych, w tym pojazdem innego dysponenta, niż określony w art.53 ust.1.”   \\fUzasadnienie WORD-y nie posiadając pojazdów do prowadzenia egzaminów lub prowadzonych pojazdem innego dysponenta w trybie przepisów art.53 ust.4 i ust.4a ustawy o kierujących pojazdami tj. prowadzenia egzaminu państwowego na prawo jazdy: 1) pojazdem bez pedału (dźwigni) sprzęgła, jeżeli nie jest to pojazd będący w dyspozycji wojewódzkiego ośrodka ruchu drogowego [ art.54 ust.5 pkt.2 w związku z art.53 ust.4 pkt.1 uokp], 2) pojazdami, którymi prowadzi się egzamin w zakresie uprawnień prawa jazdy kategorii B1, C1, C1+E, C, C+E, D1, D1+E, D lub D+E [art.53 ust.4 pkt.2 uokp], 3) pojazdami ośrodka szkolenia kierowców, który prowadził szkolenie tej osoby w zakresie prawa jazdy kategorii AM, A1, A2, A, B, kod B96 i B+E [art.53 ust.4a uokp]. nie ponoszą kosztów eksploatacyjnych i wszystkich innych kosztów związanych z nabyciem i posiadaniem pojazdu (amortyzacja, ubezpieczenia, obsługi codzienne, mycie, sprzątanie, tankowanie, garażowanie lub parking strzeżony, okresowe badania i obsługi techniczne itp.) - niemałych szczególnie w obecnym czasie wysokich cen materiałów i usług. Niestety uchwały sejmików wojewódzkich nie uwzględniają w/w obiektywnych okoliczności dlatego konieczna jest odpowiednia regulacja ustawowa, o która niniejszym wnosimy. \\t\\n\\tUwagi dodatkowe\\tOIGOSK, LFEDERACJA, PIGOSK\\tIII. W ustawie z 20 czerwca 1997 Prawo o ruchu drogowym, proponujemy:   1. w art. 55 a) ust.1 otrzymuje brzmienie: „1. Pojazd do nauki jazdy lub przeprowadzania egzaminu państwowego oznacza się tablicą kwadratową barwy niebieskiej z białą literą „L”, umieszczoną na pojeździe – nie dotyczy motocykla dwukołowego i motoroweru dwukołowego. W warunkach niedostatecznej widoczności tablica umieszczona na pojeździe powinna być oświetlona. Podczas prowadzenia nauki jazdy lub egzaminu państwowego motocyklem dwukołowym lub motorowerem dwukołowym osoba kierująca takim pojazdem powinna być ubrana w kamizelkę z umieszczoną na niej tablicą kwadratową barwy niebieskiej z białą literą „L” wykonanych z materiału odblaskowego”   Uzasadnienie: • Poprawa bezpieczeństwa ruchu drogowego – litera „L” umieszczona na kamizelce odblaskowej jest widoczna z przodu, z tyłu oraz z boków motocyklisty, dzięki czemu pozostali uczestnicy ruchu wcześniej rozpoznają, że mają do czynienia z osobą uczącą się jazdy. • Lepsza widoczność – kamizelka odblaskowa zwiększa widoczność motocyklisty zarówno w dzień, jak i po zmroku, co ma większy wpływ na bezpieczeństwo niż niewielka tablica zamocowana z tyłu motocykla. • Brak możliwości bezpiecznego montażu – wiele motocykli, szczególnie nowoczesnych, nie posiada konstrukcyjnych możliwości trwałego i \\fbezpiecznego zamocowania tablicy „L”. Stosowane uchwyty mogą ulec uszkodzeniu lub odpaść podczas jazdy. • Ochrona motocykla – montaż dodatkowych uchwytów często wymaga ingerencji w elementy konstrukcyjne, co może prowadzić do uszkodzeń pojazdu i utraty jego walorów użytkowych. • Mniejsze ryzyko zagrożenia – wystające elementy mocujące tablicę mogą stanowić dodatkowe zagrożenie podczas wywrotki lub kolizji. • Łatwość kontroli – kamizelka z literą „L” jest łatwa do zweryfikowania przez organy kontrolne, a jednocześnie nie wymaga dodatkowego wyposażenia motocykla. • Praktyka europejska – w wielu państwach europejskich stosowane są rozwiązania polegające na oznaczaniu osoby szkolonej specjalną kamizelką lub odzieżą z odpowiednim oznaczeniem, bez konieczności montowania tablic na motocyklu.   b) Dodaje się ust. 1a w brzmieniu: „1a. Pojazd wykorzystywany do nauki jazdy lub przeprowadzania egzaminu państwowego prawa jazdy kat. B może być oznaczony w sposób opisany w ust. 1 lub zamiennie kwadratową nalepką barwy niebieskiej z białą literą „L” na przedniej i tylnej szybie pojazdu w sposób nie ograniczający widoczności osobie szkolonej i instruktorowi.   Uzasadnienie Podczas szkolenia na drogach ekspresowych i autostradach a także na drogach poza obszarem zabudowanym stosowanie tablicy „L” o wymiarach 30 x30 cm na dachu pojazdu generuje niebezpieczeństwo dla innych uczestników ruchu, gdyż napór powietrza na tak dużą powierzchnię niekiedy zrywa z dachu pojazdu tablice „L” powodując zagrożenie powstaniem poważnego wypadku drogowego. W wielu państwach samochody nauki jazdy są oznaczone poprzez nalepki z różnymi symbolami i jest to z powodzeniem stosowane bez uszczerbku dla bezpieczeństwa. Z racji przyzwyczajenia do symbolu niebieskiej „L” dla pojazdów nauki jazdy- taki symbol o wymiarach np. 10 x 10 cm należałoby zachować – szczegółowe warunki należy określić w Rozporządzeniu w sprawie rejestracji i oznaczania pojazdów, wymagań dla tablic rejestracyjnych oraz wzorów innych dokumentów związanych z rejestracją pojazdów\\t\\n\\tUwaga dodatkowa\\tPolski Związek Motorowy\\tProponowane brzmienie przepisu Ustawy z dnia 20 czerwca 1997 r. - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251 z późn. zm.):  Art. 119 Ustawy - Prawo o ruchu drogowym  \\fW art. 119 ust. 3 uchyla się pkt 4.  Art. 119 ust. 4 otrzymuje brzmienie:  „4. Ośrodek ponosi wydatki na działania na rzecz poprawy bezpieczeństwa ruchu drogowego na obszarze województwa, w szczególności na popularyzację zasad ruchu drogowego oraz podnoszenie kultury jazdy kierowców”.  Po ust. 4 dodaje się ust. 4a w brzmieniu:  „4a. Wydatki, o których mowa w ust. 4, mogą być finansowane ze środków zgromadzonych na funduszu zapasowym ośrodka.”  Uzasadnienie:  Projektowana zmiana ma na celu zwiększenie efektywności wykorzystania środków finansowych zgromadzonych przez wojewódzkie ośrodki ruchu drogowego oraz wzmocnienie realizacji ustawowych zadań związanych z poprawą bezpieczeństwa ruchu drogowego w tym działań związanych z turniejami Bezpieczeństwa Ruchu Drogowego na szczeblu szkolnym, powiatowym, wojewódzkim jak i krajowym. Działania na rzecz poprawy bezpieczeństwa ruchu drogowego stanowią jedno z podstawowych zadań wojewódzkich ośrodków ruchu drogowego, wynikających bezpośrednio z ustawy. Nie mają one charakteru działalności dodatkowej ani fakultatywnej, lecz pozostają integralnym elementem misji publicznej realizowanej przez te podmioty. Obecne przepisy, które określają szczegółowe warunki gospodarki finansowej wojewódzkich ośrodków ruchu drogowego są zawarte w Rozporządzeniu Ministra Infrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376). Rozporządzenie to zastąpiło poprzednio obowiązujący akt, tj. Rozporządzenie Ministra Infrastruktury z dnia 2 października 2002 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. Nr 176, poz. 1443) i wprowadziło zmianę w zakresie \\fprzeznaczenia funduszu zapasowego. Zgodnie z treścią § 5 poprzednio obowiązującego Rozporządzenia, fundusz zapasowy był przeznaczony do dyspozycji ośrodka na finansowanie działalności, o której mowa w art. 117 ust. 1 i 2 ustawy - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251), a zatem również na potrzeby szeroko rozumianej działalności oświatowej dot. bezpieczeństwa w ruchu drogowym oraz realizacji innych, doniosłych zadań z zakresu tego bezpieczeństwa. Obecnie natomiast, zgodnie z aktualnym Rozporządzeniem, fundusz zapasowy może być przeznaczony jedynie na pokrycie strat netto ośrodka. W praktyce oznacza to, że środki zgromadzone w funduszu zapasowym pozostają  niewykorzystane do czasu wystąpienia ujemnego wyniku finansowego, niezależnie od istniejących potrzeb w zakresie realizacji działań służących poprawie bezpieczeństwa ruchu drogowego.  Brak jest dostatecznego uzasadnienia dla utrzymywania stanu, w którym środki zgromadzone przez ośrodek pozostają zarezerwowane wyłącznie na pokrycie potencjalnych przyszłych strat, podczas gdy mogą zostać wykorzystane do realizacji ustawowych zadań służących ograniczaniu liczby wypadków drogowych, zwiększaniu świadomości uczestników ruchu drogowego oraz podnoszeniu poziomu bezpieczeństwa na drogach. Proponowane rozwiązanie wychodzi z założenia, że środki funduszu zapasowego powinny służyć nie tylko ochronie stabilności finansowej ośrodka, lecz również wspierać realizację celów publicznych, dla których wojewódzkie ośrodki ruchu drogowego zostały utworzone. Umożliwienie finansowania działań na rzecz bezpieczeństwa ruchu drogowego ze środków funduszu zapasowego pozwoli na bardziej racjonalne i efektywne gospodarowanie zgromadzonym majątkiem, przy jednoczesnym zachowaniu bezpieczeństwa finansowego jednostek. Powrót do finansowania wydatków, w części przeznaczonej na poprawę bezpieczeństwa ruchu drogowego z funduszu zapasowego, bez wątpienia umożliwiłby zwiększenie skuteczności i efektywności pomocy m.in. placówkom edukacyjno-oświatowym przygotowującym dzieci i młodzież do świadomego i bezpiecznego udziału w ruchu drogowym na terenie naszego kraju w tym na organizację turniejów bezpieczeństwa ruchu drogowego, którego między innymi organizatorem jest Polski Związek Motorowy , a ponadto znacząco odciążyłby fundusz z bieżącej działalności ośrodków.  Należy jeszcze raz podkreślić, że finansowanie działań na rzecz poprawy bezpieczeństwa ruchu drogowego ze środków funduszu zapasowego nie stanowi przeznaczenia tych środków na cele niezwiązane z działalnością ośrodka. Przeciwnie, środki te byłyby wykorzystywane na realizację zadań ustawowo przypisanych wojewódzkim ośrodkom ruchu drogowego. \\fProponowana zmiana prowadzi zatem do silniejszego powiązania sposobu wykorzystania wypracowanych nadwyżek finansowych z podstawowymi celami działalności ośrodków, a tym samym wzmacnia funkcjonalny związek pomiędzy gospodarką finansową ośrodka, a realizacją powierzonych mu zadań publicznych. \\t\\n\\tUwaga dodatkowa\\tPolski Związek Szkoleniowy\\tProponujemy wprowadzenie do art. 31 ustawy o kierujących pojazdami następującej poprawki:  W art. 31 po ust. 1 dodaje się ust. 1a w brzmieniu:  „1a. Przedsiębiorca może nie spełniać wymagań, o których mowa w ust. 1 pkt 3 lit. b, w zakresie prawa jazdy kategorii C, jeśli posiada zespół pojazdów spełniający wymagania dla pojazdu szkoleniowego w zakresie prawa jazdy kategorii C+E, składający się ciągnika siodłowego z naczepą, w którym ciągnik siodłowy jest nie starszy niż 7 lat.”.”   Od początku 2026 r. do prowadzenia szkolenia i egzaminowania osób w zakresie prawa jazdy kategorii C+E są wymagane ciągniki siodłowe z naczepą. Oznacza to jednocześnie, że do szkolenia w zakresie prawa jazdy kategorii C będzie potrzebny inny pojazd niż do szkolenia w zakresie prawa jazdy kategorii C+E. Wiele podmiotów prowadzących szkolenia w zakresie prawa jazdy kategorii C i C+E kupiło nowe lub prawie nowe zespoły pojazdów składające się z ciągnika siodłowego z naczepą. Jest to na tyle duże obciążenie finansowe, że w przypadku ciężarówki na prawo jazdy kategorii C niektórych podmiotów może nie być stać na zakup kolejnego, młodszego niż 7 lat pojazdu. Dlatego też proponujemy aby pojazd kategorii C+E jakim jest ciągnik siodłowy z naczepą, pozwalał także na spełnianie dodatkowych warunków w zakresie pojazdów, dla podmiotu posiadającego lub występującego o poświadczenie spełniania dodatkowych wymagań.  \\t\\n\\tUwaga dodatkowa\\tPolski Związek Szkoleniowy\\t10) Proponujemy wprowadzenie do art. 35 ustawy o kierujących pojazdami następującej poprawki:   W art. 35 po ust. 3 dodaje się ust. 3a w brzmieniu:  „3a. Zajęcia, o których mowa w ust. 3 pkt. 1, mogą być realizowane przy wykorzystaniu metod on-line polegających na transmisji w czasie rzeczywistym dźwięku i obrazu między osobą prowadzącą takie zajęcia, a jej uczestnikami.”  \\fProponujemy doprecyzowanie przepisów dotyczących prowadzenia szkolenia instruktorów nauki jazdy. Zgodnie z przepisami ustawy o kierujących pojazdami szkolenia dla instruktorów nauki jazdy mogą prowadzić:  1) ośrodek szkolenia kierowców posiadający poświadczenie potwierdzające spełnianie dodatkowych wymagań - odpowiednio do zakresu posiadanego poświadczenia;  2) jednostka wojskowa - w zakresie szkolenia instruktorów na potrzeby Sił Zbrojnych Rzeczypospolitej Polskiej;  3) jednostka organizacyjna służb podległych ministrowi właściwemu do spraw wewnętrznych - w zakresie szkolenia osób na potrzeby tych służb;  4) podmiot wykonujący przewozy tramwajem - w zakresie szkolenia instruktorów osób ubiegających się o uprawnienie do kierowania tramwajem;  5) wojewódzki ośrodek ruchu drogowego spełniający wymagania, o których mowa w art. 31 ust. 1 pkt 3-5.   Jednym z przywilejów dla przedsiębiorcy prowadzącego, wymieniony w pkt. 1, ośrodek szkolenia kierowców posiadający poświadczenie potwierdzające spełnianie dodatkowych wymagań jest, zgodnie z art. 26 ust. 2 ustawy, szkolenie osób w formie nauczania na odległość z wykorzystaniem technik komputerowych i Internetu, o którym mowa w art. 23 ust. 3 ustawy. Jest to przywilej stosowany w przypadku szkolenia kandydatów na kierowców. Podmioty te są od lat przygotowane i odpowiednio wyposażone, aby takie zajęcia w zgodny z prawem sposób prowadzić. W ostatnim czasie niektóre organy nadzoru poddały w wątpliwość możliwość prowadzenia przez te podmioty zajęć teoretycznych dla instruktorów nauki jazdy metodą on-line polegającą na transmisji w czasie rzeczywistym dźwięku i obrazu między osobą prowadzącą takie zajęcia, a jej uczestnikami. Oczywiście nie jest to metoda zabroniona, ale mając na względzie czystość stanowionego prawa i dążąc do jego jednolitego stosowania proponujemy jednoznaczne wskazanie, że taki ośrodek ma prawo prowadzić część teoretyczną szkolenia dla instruktorów nauki jazdy przy pomocy metod on-line polegających na transmisji w czasie rzeczywistym dźwięku i obrazu między osobą prowadzącą takie zajęcia, a jej uczestnikami. Warto zauważyć, że w odróżnieniu od metod e-learningowych prowadzenie wykładów on-line na żywo nie obniża jakości szkolenia i daje możliwość pełnej interakcji pomiędzy osobami szkolonymi, a wykładowcą gwarantując odpowiednio wysoką jakość szkolenia i zaangażowanie osób szkolonych.  \\fWprowadzenie tej regulacji otwiera możliwości udziału w kursach dla kandydatów na instruktorów i instruktorów osobom, które ze względu na rodzaj i system wykonywanej pracy były wykluczone z możliwości zdobycia uprawnień instruktora nauki jazdy, w przeciwieństwie do osób ubiegających się o uprawnienia do kierowania.  Jednocześnie nie generuje to dodatkowych zobowiązań i obciążeń zarówno po stronie społecznej (koszt szkolenia dla zainteresowanej osoby nie zwiększa się względem standardowego szkolenia stacjonarnego, po stronie przedsiębiorcy korzysta się z już wypracowanych technik i sprawdzonego, bezpiecznego oprogramowania, po stronie nadzoru możliwość weryfikacji przeprowadzenia zajęć nie tylko na podstawie ewidencji w dokumentacji, ale również wglądu w zarejestrowane zajęcia, oraz weryfikacji merytoryki i zgodności z programem nauczania – analogicznie jak w przypadku szkolenia dla osób ubiegających się o uprawnienia do kierowania) jak i nie stanowi obciążenia dla budżetu.\\t\\n\\tUwaga dodatkowa\\tPolski Związek Szkoleniowy\\t15) W odniesieniu do art. 3:  a) pkt 1 otrzymuje brzmienie:   1) w art. 2  a) w pkt 37 po wyrazach „Służbę Więzienną” skreśla się średnik i dodaje się wyrazy „oraz pojazdy przeznaczone wyłącznie do nauki jazdy i egzaminowania;”  b) po pkt 47c dodaje się pkt 47d w brzmieniu:   „47d) mikromobilność dzielona – usługę polegającą na udostępnianiu użytkownikom, w sposób odpłatny lub nieodpłatny, pojazdów lub urządzeń przeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w szczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego, z wykorzystaniem aplikacji mobilnej lub innego systemu teleinformatycznego umożliwiającego korzystanie z tych pojazdów lub urządzeń przez wielu użytkowników;”;   Uzasadnienie  Zgodnie z przepisami art. 8 ustawy z dnia 12 stycznia 1991 r. o podatkach i opłatach lokalnych (Dz.U. z 2023 r. poz. 70) Opodatkowaniu podatkiem od środków transportowych podlegają:  1) samochody ciężarowe o dopuszczalnej masie całkowitej powyżej 3,5 tony i poniżej 12 ton;  2) samochody ciężarowe o dopuszczalnej masie całkowitej równej lub wyższej niż 12 ton;  \\f3) ciągniki siodłowe i balastowe przystosowane do używania łącznie z naczepą lub przyczepą o dopuszczalnej masie całkowitej zespołu pojazdów od 3,5 tony i poniżej 12 ton;  4) ciągniki siodłowe i balastowe przystosowane do używania łącznie z naczepą lub przyczepą o dopuszczalnej masie całkowitej zespołu pojazdów równej lub wyższej niż 12 ton;  5) przyczepy i naczepy, które łącznie z pojazdem silnikowym posiadają dopuszczalną masę całkowitą od 7 ton i poniżej 12 ton, z wyjątkiem związanych wyłącznie z działalnością rolniczą prowadzoną przez podatnika podatku rolnego;  6) przyczepy i naczepy, które łącznie z pojazdem silnikowym posiadają dopuszczalną masę całkowitą równą lub wyższą niż 12 ton, z wyjątkiem związanych wyłącznie z działalnością rolniczą prowadzoną przez podatnika podatku rolnego;  7) autobusy.   Podatek ten został nałożony na wszystkich posiadaczy ww. środków transportu w założeniu, że pojazdy te wykorzystywane są w mniejszym lub większym stopniu do wykonywania odpłatnego transportu drogowego osób lub rzeczy.   Wiadomym jest, że wykonywanie takiego transportu, a w szczególności regularny przejazd obciążonymi pojazdami drogami lokalnymi przyczynia się do ich szybszego zużycia i ich przyspieszonej degradacji. Dlatego też słusznym rozwiązaniem jest podatkowa partycypacja posiadaczy takich pojazdów w budżecie lokalnych samorządów tak aby można było na bieżąco naprawiać i rozwijać lokalna infrastrukturę drogową.  Jednak ustawodawca zauważył, że w przypadku niektórych pojazdów, w szczególności tych nieużywanych do wykonywania transportu drogowego osób lub rzeczy, podatek ten nie powinien być pobierany. Stanowi o tym art. 12 przedmiotowej ustawy który wskazuje, że:  „Art. 12 1. Zwalnia się od podatku od środków transportowych:  1) pod warunkiem wzajemności - środki transportowe będące w posiadaniu przedstawicielstw dyplomatycznych, urzędów konsularnych i innych misji zagranicznych, korzystających z przywilejów i immunitetów na podstawie ustaw, umów lub zwyczajów międzynarodowych, oraz członków ich personelu, jak również innych osób zrównanych z nimi, jeżeli nie są obywatelami polskimi i nie mają miejsca pobytu stałego na terytorium Rzeczypospolitej Polskiej;  2) środki transportowe stanowiące zapasy mobilizacyjne, pojazdy specjalne oraz pojazdy używane do celów specjalnych w rozumieniu przepisów o ruchu drogowym;  \\f3) pojazdy zabytkowe, w rozumieniu przepisów o ruchu drogowym.  4) W szczególności należy tu wskazać na zwolnienie od podatku od środków transportowych pojazdów specjalnych oraz pojazdy używane do celów specjalnych. Zgodnie z przepisami ustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym są to pojazdy samochodowe lub przyczepy przeznaczone do wykonywania specjalnej funkcji, która powoduje konieczność dostosowania nadwozia lub posiadania specjalnego wyposażenia. W pojeździe tym mogą być przewożone osoby i rzeczy związane z wykonywaniem tej funkcji.   Czyli są to pojazdy stricte przeznaczone do konkretnych celów, ale nie wykonujące przewozu drogowego osób lub rzeczy.  Niestety według dotychczasowego orzecznictwa pojazdy do nauki jazdy i egzaminowania nie wchodzą w tą definicję.   W ww. przepisach mamy też wymieniony „pojazd używany do celów specjalnych”. Są to pojazdy używane w szczególny sposób przystosowane do przewozu osób lub ładunków przez służby (wojsko, policję itp.). W naszej ocenie do tej kategorii pojazdów powinny dołączyć pojazdy przeznaczone do nauki jazdy i egzaminowania ponieważ są to też pojazdy używane do celów specjalnych (innych niż transport drogowy) – czyli do nauki jazdy i egzaminowania.  Pojazdy te nie występują w znacznej ilości i pomimo posiadania dopuszczalnej masy całkowitej powyżej 12 t. ich ładowność nie jest wykorzystywana, a więc nie obciążają dróg w takim stopniu jak pojazdy wykorzystywane do zarobkowego transportu drogowego.  Pojazdy te nigdy nie wykonują transportu drogowego osób lub rzeczy i zwykle poruszają się po drogach w ogóle nie obciążone.  Warto podkreślić, że zadania wykonywane przez te pojazdy są zadaniami pośrednio na rzecz lokalnej społeczności. Są to też działania związane z edukacją obywateli i ich rozwojem zawodowym, a także poprawą bezpieczeństwa ruchu drogowego. Wiemy, że w przypadkach kiedy pojazdami tymi nie jest wykonywana działalność transportowa, to płacony od lat podatek od środków transportu stanowi znaczący koszt w rocznym utrzymaniu takiego pojazdu.  Przyczynia się to do konieczności podnoszenia ceny za kurs na prawo jazdy, a więc ogranicza dostępność zawodu kierowcy. Od kilku lat największe organizacje zrzeszające pracodawców transportu drogowego alarmują o braku kierowców na rynku Polskim, co jest spowodowane między innymi wysokim kosztem uzyskania uprawnień kierowcy w Polsce. Mając na \\fwzględzie obecną sytuację ekonomiczną wiele osób odstępuje od pomysłu uzyskania uprawnień kierowcy zawodowego ze względu na koszty. Z drugiej strony przedsiębiorcy prowadzący ośrodki szkolenia kierowców, zmuszeni do ponoszenia kosztów stałych utrzymania sprzętu (w tym niezależnego od dochodu podatku od środków transportu), podnoszą ceny za kursy, albo rezygnują z prowadzenia tej części swojej działalności. Umożliwienie tym podmiotom zachowania lub rozwinięcia swojej działalności i jednoczesne obniżenie kosztów uzyskania uprawnień do kierowania pojazdami ciężarowymi powinno być priorytetem dla organów Państwa.  Warto także zauważyć, że Polska jest liderem transportu drogowego w Unii Europejskiej. Mamy zarejestrowanych ponad milion pojazdów ciężarowych i autobusów, za które samorządy słusznie pobierają podatek od środków transportu.  Do szkolenia i egzaminowania wykorzystywanych jest około 1500 pojazdów w całej Polsce. Jest to średnio 4 pojazdy szkoleniowe powyżej 12 t na powiat. Daje to niewielki dochód Powiatowi, ale znacznie obciąża budżet małych przedsiębiorców niejednokrotnie przyczyniając się do likwidacji ostatnich w danym powiecie Ośrodków Szkolenia Kierowców szkolących kierowców zawodowych. Zamyka to także szansę na uzyskanie dobrze płatnego i potrzebnego polskiej gospodarce zawodu kierowcy. Dodatkowo należy wskazać, że byłaby to bardzo niewielka liczba pojazdów zwolnionych od podatku w skali prawie 4 milionów zarejestrowanych samochodów ciężarowych w skali całej Polski.  Należy przypomnieć, że od 1 stycznia 2026 r. weszły wreszcie w życie przepisy nakładające obowiązek przeprowadzania egzaminów państwowych na prawo jazdy kategorii C+E przy użyciu wyłącznie samochodów ciężarowych z naczepą czyli ciągników siodłowych. W ostatnim roku w wszystkie Wojewódzkie Ośrodki Ruchu Drogowego i w zasadzie wszystkie ośrodki szkolenia szkolące w zakresie prawa jazdy C+E musiały zainwestować niemałe pieniądze w zakup zestawów do prowadzenia szkolenia i egzaminowania według nowych zasad. Warto zatem, jak w przypadku dofinansowania wymiany tachografów cyfrowych, ulżyć odrobinę tym podmiotom choćby przez zwolnienie ich z podatku od środków transportu, mając na względzie, że tego transportu tymi pojazdami i tak nie wykonują.  Zatem przyczyniając się do promocji zawodu kierowcy, a tym samym polskiego transportu drogowego wnosimy o przyjęcie proponowanego rozwiązania będącego jednoznacznym wsparciem dla Polskich przedsiębiorców szkoleniowych. Należy wskazać, że do tej pory likwidacja barier uniemożliwiających, albo utrudniających prowadzenie działalności gospodarczej była jednym z działań priorytetowych podejmowanych przez władzę \\fustawodawczą i wielokrotnie przyczyniała się do rozwoju poszczególnych branż. Mamy nadzieję, że proponowane przez nas rozwiązanie w podobny sposób wpłynie na rozwój branży szkolenia kierowców oraz branży transportowej.  \\t\\n\\tUwaga dodatkowa \\tPolski Związek Szkoleniowy\\tPo pkt 2 dodaje się pkt 2a w brzmieniu:   „2a) w art. 55 ust. 1 i 2 otrzymują brzmienie:  „1. Pojazd do nauki jazdy lub przeprowadzania egzaminu państwowego oznacza się tablicą kwadratową barwy niebieskiej z białą literą \\\"L\\\", umieszczoną na pojeździe. W warunkach niedostatecznej widoczności tablica umieszczona na pojeździe, z wyłączeniem tablicy na motocyklu, powinna być oświetlona. Tablica, którą oznaczony jest motocykl, powinna być wykonana z materiału odblaskowego i może być zastąpiona kamizelką odblaskową na której znajduje się odwzorowanie tej tablicy, noszoną przez osobę szkoloną.”  2. Podczas kierowania pojazdem do nauki jazdy przez osobę inną niż osoba szkolona lub egzaminowana tablica, o której mowa w ust. 1, powinna być zasłonięta lub złożona.””   Uzasadnienie  W związku z wprowadzeniem możliwości szkolenia przez ośrodek szkolenia kierowców osób posiadających uprawnienia do kierowania pojazdami (tzw. powtórna nauka jazdy dla posiadających prawo jazdy) ze względów bezpieczeństwa całego procesu należy umożliwić tym osobom jazdę w samochodzie do nauki jazdy oznaczonym tablicą „L”. Osoby, które wiele lat nie kierowały pojazdem mogą stanowić na drodze podobne zagrożenie jak kandydaci na kierowców, a więc powinien istnieć obowiązek informowania pozostałych uczestników ruchu o możliwym zagrożeniu. Obecne brzmienie art. 55 jednoznacznie wyklucza z kierowania pojazdem oznaczonym tą literą wszystkie osoby posiadające uprawnienia do kierowania pojazdami. Proponowana zmiana rozwiązuje ten problem dając zielone światło do ponownego szkolenia osób posiadających uprawnienia do kierowania pojazdami z zachowaniem odpowiednich zasad bezpieczeństwa.  Proponujemy także częściową likwidację obowiązku posiadania tablicy „L” przez motocykl w zamian za obowiązek umieszczenia tego znaku na kamizelce, którą w czasie szkolenia będzie miała na sobie osoba szkolona. Należy zwrócić uwagę, że celem tablicy „L” na pojeździe jest informowanie o zagrożeniu w postaci osoby dopiero uczącej się jeździć na takim pojeździe. Dotychczas umieszczanie takiej tablicy na motocyklu odbywało się poprzez przykręcenie jej \\fna tylnym błotniku, co jest kłopotliwe, a jednocześnie nie realizuje celu informacyjnego ponieważ zwykle tablica znajduje się bardzo nisko i nie jest dobrze widoczna. Najwyższym punktem motocykla jest osoba szkolona i umieszczenie informacji w formie tablicy „L” na kursancie rozwiązuje problem widoczności.  Warto też zauważyć, że blaszana tablica wystająca poza motocykl może stanowić realne zagrożenie dla przewracającego się kursanta.\\t\\n\\tUwaga dodatkowa\\tWielkopolskie Stowarzyszenie OSK i Instruktorów\\tObecnie obowiązek montowania tablic L z tyłu na motocyklach prowadzi do licznych problemów. Nowoczesne motocykle często pozbawione są z tyłu elementów do których możliwy jest bezpieczny montaż tablicy L. Tablica często montowana jest nisko, co znacząco ogranicza jej widoczność w ruchu drogowym. Należy zwrócić uwagę, że dla innych pojazdów minimalną wysokość ustawodawca określił na 60 cm czyli miał na uwadze fakt widoczności. Aby poprawić widoczność osoby szkolonej na motocyklu i jednocześnie zminimalizować problemy techniczne dot. montażu tablic z tyłu motocykla sugeruję usunięcie obowiązku montowania tablic L na motocyklach, w zamian nakładając obowiązek stosowania kamizelki dla osoby szkolonej z umieszczonymi na niej oznaczeniami L z przodu i z tyłu. Takie rozwiązanie z pewnością poprawi widoczność takiej osoby i przez to bezpieczeństwo w ruchu drogowym. \\t\\n\\tUwagi dodatkowe\\tWielkopolskie Stowarzyszenie OSK i Instruktorów\\tWarto zwrócić uwagę i uzupełnić przepisy w zakresie dotyczącym następujących kwestii:\\n1. rozbudowanie systemu PKK o funkcję wysyłającą automatycznie informację, do wszystkich podmiotów zainteresownych (OSK,które ma pobrany PKK, WORD itp.) informacji o wprowadzeniu do systemu danych o zakazie prowadzenia pojazdów orzeczonym wobec danej osoby.\\n2. przeniesienie ciężaru odpowiedzialności za wprowadzenie informacji o zakazach prowadzenia pojazdów na starostę z jednoczesnym dopilnowaniem obowiązku poinformowania OSK, które prowadzi szkolenie takiej osoby.\\n3. w przypadku szkolenia przez OSK osób przygotowujących się do kontrolnego sprawdzenia kwalifikacji (co popieram) należy utworzyć PKK który będzie mógł pobrać OSK celem prawidłowego zarejestrowania prowadzonego szkolenia \\t\\n\\tUwagi dodatkowe\\tWielkopolskie Stowarzyszenie \\fOSK i Instruktorów\\t\\fProwadzenie harmonogramu kursu nie jest potrzebne i stanowi tylko i wyłącznie niepotrzebny dokument, w oparciu o który kontrolujacy nic nie są w stanie zweryfikować. Zajęcia teoretyczne do tej pory odnotowywane są w Karcie Przeprowadzonych Zajęć lub \\fdokumentacji cyfrowej - w przypadku prowadzenia kursu w formule e-learning. W nowym wariancie, przy wprowadzeniu cyfrowej karty kursanta, transparentność zajęć będzie pełna i prowadzenie dodatkowej dokumentacji stanowi tylko i wyłącznie pusty wymów obciążający Kierownika OSK.  Raportowanie jest niepotrzebnym obciążeniem Kierownika OSK. Już obecnie starosta sprawujący nadzór nad szkoleniem ma pełen wgląd do systemu PKK i może w sposób dowolny weryfikować dane statystyczne co do ilości osób szkolonych w poszczególnych OSK (vide chociażby ostatnio wprowadzony system info-kierowca.pl). Zatem obowiązki statystyczne które stanowią tylko i wyłącznie powielenie już informacji widniejących w systemie do którego ma dostęp starosta są zbędne i co najważniejsze nie mają żadnego wpływu na poprawę jakości szkolenia lub poprawę bezpieczeństwa ruchu drogowego \\t\\n\\tUwaga dodatkowa\\tWielkopolskie Stowarzyszenie OSK i Instruktorów\\tZgłaszanie osoby, która ma rozpocząć szkolenie jest dublowaniem informacji, które starosta może sprawdzić korzystając z dostępnego systemu do obsługi PKK. Przed rozpoczęciem szkolenia kierownik OSK pobiera PKK i w tej sposób starosta ma informację że dana osoba będzie odbywała szkolenie. W obecnych realiach (gdzie większość szkoleń prowadzona jest w takiej formule, że kursanci przygotowują się samodzielnie do egz. teoretycznego i dopiero po uzyskaniu wyniku pozytywnego przystępują do kursu) realizowanie obowiązku wynikającego z art. 27  ust. 1 pkt 1) sprowadza się do wysyłania \\\"pustego\\\" zgłoszenia do starostwa. \\t\\n\\tUwaga dodatkowa\\tWielkopolskie Stowarzyszenie OSK i Instruktorów\\tNależy doprecyzować (co znajduje umocowanie w interpretacjach MI wydawanych w odpowiedzi na zapytania), że w OSK P wystarczające jest posiadanie co najmniej jednego pojazdu dla każdej kategorii spełniającego kryterium maksymalnego wieku. W tym zakresie różne podmioty sprawujące nadzór stosują różną interpretację prowadzące do niejednolitych zasad na terenie kraju. Dodatkowo dla autobusów należy podnieść wiek do co najmniej 15 lat. Autobusy są pojazdami bardzo drogimi, a ich okres eksploatacji przewiduje się na znacznie więcej jak 12 lat. Wcześniej (przy tworzeniu obecnego brzmienia przepisów) z pewnością kryterium 12 lat wynikało m.in. z faktu, aby pojazdy były \\\"nowoczesne\\\" i wyposażone w systemy bezpieczeństwa. Obecnie wszystkie autobusy, nawet 15 letnie, są w takie systemy wyposażone stąd podniesienie wieku pozwoli przedsiębiorcom na \\famortyzowanie zakupionego sprzętu dłużej, z lepszym bilansem ekonomicznym i jednocześnie nie będzie to miało negatywnego wpływu na jakość szkolenia i sprzętu. \\t\\n\\t Uwaga dodatkowa\\t Fundacja Zapobiegania Wypadkom Drogowym\\t Wszyscy nasi konsultanci zwracali uwagę na istotny brak projektów rozporządzeń, które nie tylko zwyczajowo powinny towarzyszyć projektowi zmian w ustawie zmieniającej… Dopiero komplet dokumentów pozwala ocenić i docenić ich trafność.  \\t\\n\\tUwagi dodatkowe\\tZarząd Dróg Miejskich Warszawa\\t 2. Oznakowanie W ślad za zmianami, do których wprowadzenia dąży resort infrastruktury, niezbędne będzie wprowadzenie nowych znaków drogowych dotyczących bezpośrednio hulajnóg elektrycznych. Wśród znaków pionowych uzupełnienia wymaga przede wszystkim zakres znaków B-9 do B-12 o zakaz ruchu odnoszący się do hulajnóg elektrycznych. Wydaje się właściwe, aby był to znak o symbolu B9a. Zapewne powinien obejmować również urządzenia transportu osobistego. Przydatne było również wprowadzenie znaku poziomego, do oznaczenia miejsc postojowych dla hulajnóg elektrycznych w trybie określonym w proponowanym art. 12c ustawy o drogach publicznych. Ważne, aby nie zaśmiecić przestrzeni tysiącami znaków, proponujemy by nie wprowadzać w tym celu znaku pionowego do oznaczania miejsc postojowych.      Uzasadnienie Rozwiązanie, które proponujemy, pozwoli prywatnym właścicielom hulajnóg elektrycznych i podobnych pojazdów korzystać z obecnych rozwiązań prawnych (a więc m.in. wykonywać postój na chodnikach czy w innych miejscach niewyznaczonych, zgodnie z obowiązującymi przepisami), natomiast jednoznacznie zobowiąże użytkowników pojazdów wynajmowanych do pozostawiania pojazdu po zakończeniu użytkowania, wyłącznie w miejscu przeznaczonym.   Proponujemy odmienne zdefiniowanie mikromobilności dzielonej. W naszej ocenie istotny nie jest dystans pokonywany pojazdami współdzielonymi, lecz okres, na jaki są one udostępniane. Podróż współdzielonym pojazdem może trwać nawet dwie \\fgodziny i obejmować odcinek o długości kilkudziesięciu kilometrów, natomiast o współdzielonym charakterze usługi świadczy przede wszystkim krótki czas udostępnienia – z reguły znacznie krótszy niż doba, najczęściej nieprzekraczający jednej godziny.   Wnioskujemy również o rezygnację ze wskazywania w definicji systemów teleinformatycznych jako sposobu udostępniania pojazdów. Wynajem hulajnóg elektrycznych lub urządzeń transportu osobistego prowadzony przez wypożyczalnie hotelowe czy inne komercyjne wypożyczalnie, niewykorzystujące aplikacji mobilnych, również powinien podlegać projektowanym regulacjom. Ponadto nie sposób przewidzieć kierunków rozwoju tego rodzaju usług, dlatego definicja powinna mieć możliwie otwarty charakter. Jednocześnie proponujemy rozszerzenie katalogu pojazdów - motorowery, rowery elektryczne i inne rowery wspomagane, zwłaszcza w wersjach elektrycznych, mogą w najbliższych latach odgrywać coraz większą rolę na rynku mikromobilności dzielonej.   Proponujemy dodanie art. 12c do ustawy o drogach publicznych zamiast proponowanych przez resort zmian w art. 20 tej ustawy, ponieważ wyznaczanie miejsc postojowych może być elementem organizacji ruchu - właściwe byłoby zatem odesłanie w ustawie do organu właściwego do zarządzania ruchem. W ten sposób stojaki rowerowe, które umieszczane są bez wpływu na organizację ruchu, byłyby w kompetencji zarządcy drogi, a miejsca wymagające zmian w organizacji ruchu wyznaczane byłyby przez zarządcę ruchu i byłyby bezpośrednio określone w nowych artykule.   Pod rozwagę poddajemy również możliwość wprowadzenia wymogu udzielenia zgody przez zarządcę drogi na korzystanie z miejsc postojowych przez pojazdy mikromobilności dzielonej. Zainteresowane samorządy mogłyby zyskać w ten sposób narzędzie kontroli liczby hulajnóg znajdujących się w użytkowaniu oraz dodatkowy sposób identyfikacji pojazdu współdzielonego. Dane te pozwalałyby lepiej planować politykę transportową miasta, zwłaszcza jeśli liczba rodzajów pojazdów mikromobilności dzielonej będzie rosła. Rozwiązanie to należy jednak traktować wyłącznie jako fakultatywne. \\f  W naszej ocenie nie należy również wprowadzać do porządku prawnego miejsc przeznaczonych wyłącznie dla pojazdów mikromobilności dzielonej. Miejsca dla hulajnóg i podobnych pojazdów powinny być ogólnodostępne. Trudne do uzasadnienia i egzekwowania byłoby wyznaczenie miejsc przeznaczonych wyłącznie dla pojazdów współdzielonych, z których nie mogliby korzystać właściciele pojazdów prywatnych. Rodziłoby to niepotrzebne konflikty i podważało zasadność takich regulacji.   Proponujemy również wprowadzenie zakazu postoju pojazdów współdzielonych w art. 49 Prawa o ruchu drogowym, zamiast dodawania nowego ust. 3a w art. 47. Art. 47 reguluje bowiem dopuszczalne przypadki postoju na chodniku, natomiast celem projektowanego rozwiązania jest kompleksowe uregulowanie zasad postoju pojazdów mikromobilności dzielonej i jednoznaczne wskazanie, że jedynym dopuszczalnym miejscem ich postoju są miejsca wyznaczone. Dodanie nowego ust. 3a do art. 47 mogłoby prowadzić do wątpliwości interpretacyjnych, czy obowiązek ten dotyczy wyłącznie chodników, czy całej drogi.\\nAlternatywą jest wprowadzenie art. 47b., który dopuszczałby postój pojazdów mikromobilności dzielonej tylko w przeznaczonych miejscach: określonych w dodanym art. 12c. ustawy o drogach publicznych i przy stojakach rowerowych.   Istotne jest także jednoznaczne przyznanie straży gminnej (miejskiej) kompetencji do wydawania dyspozycji usunięcia pojazdu na podstawie art. 130a Prawa o ruchu drogowym. W ślad za propozycjami zawartymi w projekcie nr UD402 zasadne jest wyraźne określenie tych kompetencji w ustawie. \\t\\n\\tUwagi dodatkowe\\tOsoba fizyczna  (zgłoszenie nr 9)\\tNiniejszym zgłaszam postulat włączenia do projektu szeregu zmian przedstawionych w niniejszym piśmie, które mają na celu: Wprowadzić ułatwienia w przechodzeniu z zawodu egzaminatora i instruktora techniki jazdy do zawodu instruktora nauki jazdy czy właściciela własnej szkoły jazdy, jako że dwa pierwsze zawody cechuje bardzo wysoki poziom przygotowania.  \\fZlikwidować rosnący problem niedoboru instruktorów kategorii ciężkich w Polsce. Poprzez otwarcie drogi do zawodu instruktora kat. C, D i C+E osobom posiadającym przez ponad 5 lat stosowne uprawnienia i kwalifikację zawodową. W tym celu zniesienie dla kandydatów na instruktorów kategorii ciężkich z doświadczeniem w pracy kierowcy zawodowego, nadmiernych wymogów formalnych w zakresie dokumentacji oraz czysto arbitralnych wymogów pracy w wybranych sektorach transportu, eliminujących osoby posiadające realne kompetencje spoza tych sektorów. Usunąć pozbawiony podstaw merytorycznych, wymóg czysto pasywnego posiadania przez co najmniej 3 lata uprawnień egzaminacyjnych na kategorię B, jako warunek uzyskania uprawnień egzaminacyjnych na inne kategorie. Zmiana 1:  W art. 28 w ust. 2 pkt 2 otrzymuje brzmienie:  „2) zatrudnia w ośrodku szkolenia kierowców co najmniej jednego instruktora, który posiada uprawnienia do prowadzenia szkoleń w zakresie uzyskiwania uprawnienia do kierowania pojazdami silnikowymi kategorii prawa jazdy określonej we wniosku, o którym mowa w ust. 4, oraz udokumentowaną, łączną 3-letnią praktykę w zakresie tej kategorii, obejmującą okresy wykonywania jednej lub więcej następujących czynności:  a) instruktora nauki jazdy w ośrodku szkolenia kierowców,  b) egzaminatora w wojewódzkim ośrodku ruchu drogowego, lub  c) instruktora techniki jazdy w ośrodku doskonalenia techniki jazdy  – albo sam jest instruktorem spełniającym te wymagania;” Zmiana 2:  W art. 33 w ust. 1 pkt 6 otrzymuje brzmienie:  „6) ukończyła z wynikiem pozytywnym kurs dla kandydatów na instruktorów i posiada zaświadczenie o jego ukończeniu – dotyczy instruktorów osób ubiegających się o uzyskanie uprawnienia do kierowania pojazdami silnikowymi, przy czym wymóg ten nie dotyczy osób, \\fktóre w dniu złożenia z wynikiem pozytywnym egzaminu, o którym mowa w pkt 7, posiadały uprawnienia egzaminacyjne lub uprawnienia instruktora techniki jazdy w zakresie prawa jazdy kategorii odpowiedniej dla zakresu prowadzonego szkolenia;” Zmiana 3:  W art. 33 ust. 1a otrzymuje brzmienie:  „1a. Wymóg, o którym mowa w ust. 1 pkt 2 lit. c, uznaje się za spełniony, jeżeli kandydat na instruktora posiada przez łączny okres przekraczający 5 lat ważne uprawnienia do kierowania pojazdami oraz kwalifikację zawodową:  odpowiednie dla prawa jazdy kategorii C+E – w przypadku kandydata na instruktora w zakresie prawa jazdy kategorii C, C+E lub D,  odpowiednie dla prawa jazdy kategorii C albo D – w przypadku kandydata na instruktora w zakresie którejkolwiek z tych kategorii   a ponadto przez okres co najmniej roku posiada uprawnienia do kierowania pojazdami odpowiednie do zakresu prowadzonych zajęć oraz odpowiadającą im kwalifikację zawodową.”      Zmiana 4:  W art. 33 dodaje się ust. 1b w brzmieniu:   „1b. Wymóg, o którym mowa w ust. 1 pkt 2 lit. c, uważa się za spełniony w przypadku kandydata na instruktora, który posiada ważne prawo jazdy kategorii odpowiedniej do zakresu prowadzonych zajęć, a ponadto udokumentuje łączny okres wykonywania czynności egzaminatora w wojewódzkim ośrodku ruchu drogowego, instruktora techniki jazdy w ośrodku doskonalenia techniki jazdy lub łączny okres wykonywania obu tych czynności, wynoszący co najmniej:  \\f1 rok w zakresie kategorii prawa jazdy odpowiedniej do zakresu prowadzonych zajęć, albo 3 lata w zakresie prawa jazdy kategorii B, do okresu tego wlicza się również okres wykonywania czynności instruktora nauki jazdy kategorii B w ośrodku szkolenia kierowców.” Zmiana 5:  W art. 58 w ust. 1 pkt 3 otrzymuje brzmienie:  „3) posiada uprawnienia egzaminatora w zakresie prawa jazdy kategorii B, w przypadku osoby ubiegającej się o uprawnienia do egzaminowania na pozostałe kategorie prawa jazdy;” Uzasadnienie zmiany 1: Ośrodki Szkolenia Kierowców mają obowiązek zatrudniania co najmniej jednego instruktora z 3-letnim doświadczeniem w szkoleniu kierowców. Zmiana pozwala, alternatywnie, zatrudnić instruktora który posiada 3-letnie doświadczenie w pracy egzaminatora w WORD lub instruktora techniki jazdy w ODTJ. Ponadto doświadczony egzaminator lub doświadczony instruktor doskonalenia techniki jazdy otrzymują możliwość by ich uprzednie doświadczenie w egzaminowaniu lub doskonaleniu techniki jazdy pozwoliło na spełnienie wymogu o którym mowa w przepisie,do założenia i prowadzenia ich własnej szkoły jazdy.  Przepis pozwala na sumowanie okresów wykonywania czynności instruktora nauki jazdy z okresami wykonywania czynności egzaminatora i instruktora doskonalenia techniki jazdy.  Użyte w przepisie wyrażenia, pozwalają na zaliczenie doświadczenia uzyskanego również w ramach samozatrudnienia. Jakkolwiek w przypadku kierowców zawodowych, wymóg udokumentowania doświadczenia jest nadmiernym wymogiem – kierowca rzadko z góry planuje że zostanie instruktorem i nie zbiera dokumentów -  tak od osób zawodowo związanych z branżą szkolenia kierowców, jak najbardziej można wymagać zbierania takiej dokumentacji.   Uzasadnienie zmiany 2: \\fProponowana zmiana zwalnia osoby posiadające uprawnienia egzaminacyjne lub uprawnienia instruktora techniki jazdy z odbycia kursu instruktora nauki jazdy. Osoby te posiadają przeważnie znacznie szersze kwalifikacje i wiedzę niż te przekazywane na kursie instruktora nauki jazdy. Można więc je bezpiecznie zwolnić  z konieczności ponoszenia kosztów finansowych i czasowych związanych z, w praktyce zduplikowanym kursem i dopuścić je bezpośrednio do egzaminu na instruktora nauki jazdy. Uzasadnienie zmiany 3: Proponowana zmiana ma na celu zapobieżenie rosnącemu w Polsce niedoborowi instruktorów kategorii zaawansowanych przy jednoczesnym zapewnieniu jakości szkolenia. Coraz częściej czas zrobienia kursu na kategorie zaawansowaną przekracza dzisiaj 3 miesiące, przyczyną tego jest niedobór nowych instruktorów oraz przechodzenie obecnych instruktorów na emeryturę.  Dojście do zawodu, wymaga albo 3 lat doświadczenia w zakresie szkolenia na kat. B, co w żaden sposób nie przekłada się na umiejętności nauczania dla kategorii ciężkich. Albo w przypadku kierowcy zawodowego spełnienia bardzo zbiurokratyzowanych wymogów udokumentowania doświadczenia w przewozach międzynarodowych lub komunikacji publicznej. Prowadzi to do pominięcia całego grona kompetentnych osób, które albo nie są w stanie zebrać odpowiedniej dokumentacji albo posiadają doświadczenie w innych niż te czysto arbitralnie wybrane segmenty transportu. Toteż proponuje się, aby ułatwiony dostęp do zawodu instruktora nauki jazdy na kategorie ciężkie, miały osoby które posiadają swoje uprawnienia kierowcy zawodowego przez ponad 5 lat, co automatycznie oznacza że uprawnienia te musiały przedłużyć. Osoba, która przedłuża swoje uprawnienia i kwalifikację zawodową na następne 5 lat i inwestuje to środki, w absolutnej większości będzie osobą z realnym doświadczeniem w transporcie ciężkim, gotową wiązać dalej z nim swoją karierę.   Zastosowany filtr, jest najbardziej realistycznym i racjonalnym rozwiązaniem w celu zapewnienia jakości szkolenia, innym niż po prostu znaczne zaostrzenie kryteriów egzaminowania kandydatów na instruktora kategorii ciężkich.  Szczególną zaletą proponowanego rozwiązania jest to, że zwalnia ono absolutną większość kandydatów ze zbierania dokumentacji, gdyż ewidencję instruktorów prowadzi wydział komunikacji starostwa, ten sam który wydaje prawa jazdy.  \\fZ uwagi na podobieństwo gabarytów między pojazdami kategorii C i D, wprowadzono ułatwiony dostęp dla doświadczonego kierowcy kategorii ciężarowej lub autobusowej, w uzyskaniu uprawnień instruktora na tą drugą kategorię. Wystarczy, aby obok posiadania swoich głównych uprawnień i kwalifikacji przez ponad 5 lat, posiadał te drugie uprawnienia i kwalifikacje przez okres co najmniej 1 roku.  Z kolei doświadczenie nabyte jako kierowca kategorii C+E, otwiera dostęp do zawodu instruktora w sposób najbardziej szeroki, z uwagi na najbardziej szeroki zakres umiejętności tych kandydatów. Dla doświadczonego kierowcy kategorii C+E, kierowanie pojazdem na kategorię C jest wręcz trywialne. Stąd tak samo jak dla kierowcy kategorii C, uzasadnione jest ułatwienie dojścia do zawodu instruktora kategorii D. Z uwagi na przepis art. 33 ust. 3a pkt. 2-5,  instruktor posiadający uprawnienia do szkolenia jednocześnie na kat. C, C+E i D, będzie z urzędu uprawniony do szkolenia na kategorie B+E ,C1,C,C1+E, C+E,D,D1,D1+E, D+E i T. Nowelizacja nie przewiduje dodatkowych ułatwień dla kierowców kat. D+E, innych niż wynikających z posiadania przez ponad 5 lat uprawnień i kwalifikacji zawodowej dla samej kategorii D. Szkolenie na kategorię D+E jest w Polsce marginesem, a w przedsiębiorstwach zajmujących się przewozem osób, do kierowania zespołami pojazdów na kat. D zatrudnia się kierowców posiadających jednocześnie kategorię D i C+E, którym na podstawie art. 6 , ust. 1 pkt. 16 niniejszej ustawy z urzędu wpisano kategorię D+E.  Należy zanotować na marginesie, że obecny przepis art. 33, ust. 1a, pkt. 2 odnoszący się do szkolenia na kategorię D+E jest prawem całkowicie martwym, zwłaszcza przy zawartych w tym przepisie wymogach. Za całkowicie oderwane od dzisiejszej rzeczywistości i dyskryminujące, uznane zostały wymogi pracy w konkretnych sektorach – przewozie międzynarodowym czy komunikacji miejskiej. Zawężenie doświadczenia do tych sektorów jest czysto arbitralne i zupełnie bezzasadnie eliminuje osoby posiadające realne kompetencje. Zmiana celowo używa pojęcia “okresu łącznego”, w celu objęcia nią również osób, które z powodów np. zdrowotnych miały przerwę w odnawianiu swoich uprawnień i kwalifikacji, jednak łącznie posiadały je przez 5 lat, jednocześnie posiadają te uprawnienia i kwalifikację obecnie.  Uzasadnienie zmiany 4: \\fNiniejsza zmiana uznaje 3-letnie doświadczenie w pracy egzaminatora w WORD i instruktora techniki jazdy w ODTJ dla kategorii B za równorzędne z doświadczeniem w szkoleniu kandydatów na kierowców jako instruktor nauki jazdy, w kontekście uzyskania uprawnień instruktora kategorii B+E, C1, C1+E, C, C+E, D1, D1+E, D lub D+E. Ponadto egzaminatorzy i instruktorzy techniki jazdy, którzy posiadają co najmniej 1 roczne doświadczenie w pracy jako egzaminator w WORD lub instruktor techniki jazdy w ODTJ na jedną z w/w kategorii mogą zostać instruktorem tej kategorii bez spełniania wymogu 3 letniego doświadczenia w szkoleniu, doskonaleniu techniki jazdy lub egzaminowaniu na kategorię B. Osoba ta posiada kwalifikacje znacznie większą, niż osoba wykonująca czynności tylko dla kategorii B.  Zachowano jednak wymóg posiada prawa jazdy danej kategorii.   Przepis pozwala na łączenie ze sobą okresów wykonywania czynności egzaminatora, instruktora techniki jazdy i instruktora nauki jazdy oraz na uznanie doświadczenia uzyskanego w ramach samozatrudnienia. Uzasadnienie zmiany 5: Przepis warunkujący uzyskanie uprawnień egzaminatora dla kategorii innych niż kat. B od posiadania uprawnień egzaminatora kategorii B przez 3 lata jest pozbawiony uzasadnienia i stanowi nadmierną regulację sztucznie ograniczającą dostęp do zawodu. Samo pasywne posiadanie uprawnień przez 3 lata nie daje żadnych przewag w kwestii jakości przyszłej pracy kandydata na egzaminatora. Po 3 latach, o uprawnienia dodatkowe może ubiegać się osoba, która nie przeprowadziła ani jednego egzaminu, a tylko i wyłącznie brała udział w corocznych szkoleniach doskonalących.  Zdawalność egzaminów dla kandydatów na egzaminatorów jest bardzo niska, a proces weryfikacji wiedzy kandydatów na egzaminatorów stoi na bardzo wysokim poziomie. Toteż obecny przepis stanowi całkowicie zbędną barierę dojścia do i tak trudno dostępnego zawodu.  Wobec powyższego zaproponowano zmianę, by do uzyskania uprawnień egzaminatora innych kategorii niż kat. B, wymagany był, oprócz pozostałych wymogów zawartych w art. 58 Ustawy, sam fakt posiadania uprawnień do egzaminowania na kategorię B, bez względu na czas ich posiadania. Niewątpliwie kategoria B stanowi istotną bazę na której można budować kolejne uprawnienia. Nie ma jednak najmniejszego uzasadnienia dla \\fwarunkowania rozbudowy tych uprawnień od samego tylko upływu czasu i wzięcia udziału w trzech corocznych szkoleniach doskonalących, przedłożenia zaświadczenia lekarskiego itd.\\t\\n\\tUwagi dodatkowe\\tOgólnopolski Związek Zawodowy Pracowników Wojewódzkich Ośrodków Ruchu Drogowego\\tWnioskujemy także o zmianę zapisu Art. 63 ust. 1 pkt. 6  oraz dodanie Art. 63a) tak, by można było również korzystać z mLegitymacji umieszczonej w aplikacji mObywatel. Art.  63. 1.  Egzaminator jest obowiązany: 6) posiadać w czasie przeprowadzania egzaminów legitymację egzaminatora lub mLegitymację oraz okazywać ją na żądanie uprawnionego podmiotu. Art.  63a. [mLegitymacja egzaminatora]  1. Egzaminatorowi wydaje się legitymację służbową w postaci dokumentu mobilnego, o którym mowa w art. 2 pkt 7 ustawy z dnia 26 maja 2023 r. o aplikacji mObywatel (Dz. U. z 2024 r. poz. 1275 i 1717 oraz z 2025 r. poz. 1019), jako \\\"mLegitymację\\\", po uwierzytelnieniu przy użyciu certyfikatu podstawowego, o którym mowa w art. 2 pkt 2 ustawy z dnia 26 maja 2023 r. o aplikacji mObywatel.  2.  mLegitymację wydaje się w terminie 14 dni od dnia nawiązania stosunku pracy w Wojewódzkim Ośrodku Ruchu Drogowego. 3.  mLegitymacja zawiera: 1) imię (imiona) i nazwisko egzaminatora; 2) wizerunek twarzy egzaminatora; 3) numer ewidencyjny egzaminatora; 4) kategorie prawa jazdy, na które egzaminator posiada uprawnienia egzaminacyjne; 5) nazwę i adres siedziby WORD, w którym egzaminator jest zatrudniony; 6) numer mLegitymacji; 7) datę wydania mLegitymacji. 4. Numer mLegitymacji jest tożsamy z numerem legitymacji egzaminatora 5. mLegitymacja potwierdza zatrudnienie na stanowisku egzaminatora. 6. mLegitymację wydaje się egzaminatorowi na czas zgodny z terminem ważności wydanej legitymacji egzaminatora. 7. mLegitymację unieważnia się w przypadku: 1) rozwiązania albo wygaśnięcia stosunku pracy egzaminatora; 2) zmiany Wojewódzkiego Ośrodka Ruchu Drogowego, w którym egzaminator jest zatrudniony; \\f3) błędu w numerze lub danych w mLegitymacji; 4) zmiany zakresu uprawnień egzaminacyjnych; 5) utraty uprawnień egzaminacyjnych. 8. W przypadku unieważnienia mLegitymacji z przyczyn określonych w ust. 7 pkt 2-4 egzaminatorowi wydaje się nową mLegitymację. \\t\\n\\tUwagi dodatkowe\\tOsoba fizyczna (zgłoszenie nr 8)\\tPrzedmiot uwagi: Przyspieszenie wejścia w życie przepisów znoszących obowiązek egzaminu państwowego przy usuwaniu ograniczenia kodu 78 (skrzynia automatyczna). Wnoszę o jak najszybsze wdrożenie przepisów znoszących konieczność zdawania egzaminu państwowego w WORD w celu usunięcia kodu 78 z prawa jazdy i zastąpienie go kursem w Ośrodku Szkolenia Kierowców (OSK). Pozostawienie obecnych restrykcji do końca unijnego okresu dostosowawczego (2029 r.) niesie za sobą negatywne skutki społeczne, gospodarcze i ekologiczne. Natychmiastowe wejście w życie tych zmian jest uzasadnione następującymi argumentami: 1. Blokada rozwoju elektromobilności i transformacji ekologicznej. Polska, jako kraj członkowski UE, dąży do redukcji emisji gazów cieplarnianych i popularyzacji aut nisko- i zeroemisyjnych. Samochody elektryczne oraz zdecydowana większość nowoczesnych hybryd konstrukcyjnie nie posiadają manualnej skrzyni biegów. Obecne przepisy zniechęcają młodych kierowców do nauki jazdy na nowoczesnych pojazdach (automatach), ponieważ otrzymanie kodu 78 drastycznie ogranicza ich mobilność w przyszłości. Przyspieszenie zmian natychmiast odblokuje ten proces i zachęci obywateli do przesiadki na pojazdy ekologiczne. 2. Sztuczne obciążenie i paraliż systemu egzaminacyjnego (WORD). Wojewódzkie Ośrodki Ruchu Drogowego od lat zmagają się z problemem długich kolejek i brakiem rąk do pracy wśród egzaminatorów. Zmuszanie kierowców, którzy potrafią już bezpiecznie poruszać się w ruchu miejskim, do ponownego zdawania pełnego egzaminu państwowego tylko w celu zweryfikowania umiejętności zmiany biegów, jest marnotrawstwem zasobów publicznych. Przeniesienie tego uprawnienia do OSK w formie kilkugodzinnego szkolenia natychmiast odciąży WORD-y i skróci czas oczekiwania na egzaminy dla osób ubiegających się o swoje pierwsze prawo jazdy. 3. Straty finansowe polskich przedsiębiorców i szkół jazdy (OSK). Krajowy rynek szkoleniowy jest gotowy na zmiany, jednak obecne przepisy blokują inwestycje w nowoczesną flotę pojazdów. Szkoły jazdy obawiają się zakupu aut elektrycznych i hybrydowych, ponieważ kursy na automatach cieszą się mniejszym zainteresowaniem wyłącznie przez uciążliwą procedurę usuwania kodu 78. Przyspieszenie nowelizacji da impuls gospodarczy dla sektora OSK i pozwoli na modernizację infrastruktury \\fszkoleniowej w Polsce. 4. Dostosowanie prawa do realiów rynkowych i wykluczenie komunikacyjne. Manualne skrzynie biegów stają się technologią schodzącą z rynku – w nowych samochodach osobowych stanowią one zdecydowaną mniejszość. Utrzymywanie restrykcyjnych przepisów uderza w osoby, które z przyczyn losowych (np. konieczność nagłego podjęcia pracy wymagającej jazdy autem służbowym z manualną skrzynią) zostają odcięte od możliwości szybkiej zmiany uprawnień. System oparty na krótkim przeszkoleniu w OSK pozwala elastycznie i szybko reagować na potrzeby rynku pracy, redukując ryzyko wykluczenia zawodowego.  \\t\\n\\t Uwagi dodatkowe\\t Unia Wielkopolan\\t  Proponowane brzmienie przepisu Ustawy z dnia 20 czerwca 1997 r. - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251 z późn. zm.):  Art. 119 Ustawy - Prawo o ruchu drogowym  W art. 119 ust. 3 uchyla się pkt 4.  Art. 119 ust. 4 otrzymuje brzmienie:  „4. Ośrodek ponosi wydatki na działania na rzecz poprawy bezpieczeństwa ruchu drogowego na obszarze województwa, w szczególności na popularyzację zasad ruchu drogowego oraz podnoszenie kultury jazdy kierowców”.  Po ust. 4 dodaje się ust. 4a w brzmieniu:  „4a. Wydatki, o których mowa w ust. 4, mogą być finansowane ze środków zgromadzonych na funduszu zapasowym ośrodka.”  Uzasadnienie:  Projektowana zmiana ma na celu zwiększenie efektywności wykorzystania środków finansowych zgromadzonych przez wojewódzkie ośrodki ruchu drogowego oraz wzmocnienie realizacji ustawowych zadań związanych z poprawą bezpieczeństwa ruchu drogowego.  Obecne przepisy, które określają szczegółowe warunki gospodarki finansowej wojewódzkich ośrodków ruchu drogowego są zawarte w Rozporządzeniu Ministra Infrastruktury z dnia 3 lipca 2023 r. w sprawie szczegółowych warunków gospodarki finansowej wojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. poz. 1376). Rozporządzenie to zastąpiło poprzednio obowiązujący akt, tj. Rozporządzenie Ministra Infrastruktury z dnia 2 października 2002 r. w sprawie szczegółowych warunków gospodarki finansowej \\fwojewódzkiego ośrodka ruchu drogowego oraz szczegółowych warunków ewidencji przychodów i kosztów związanych z działalnością ośrodka (Dz. U. Nr 176, poz. 1443) i wprowadziło zmianę w zakresie przeznaczenia funduszu zapasowego.   Zgodnie z treścią § 5 poprzednio obowiązującego Rozporządzenia, fundusz zapasowy był przeznaczony do dyspozycji ośrodka na finansowanie działalności, o której mowa w art. 117 ust. 1 i 2 ustawy - Prawo o ruchu drogowym (t.j. Dz. U. z 2024 r. poz. 1251), a zatem również na potrzeby szeroko rozumianej działalności oświatowej dot. bezpieczeństwa w ruchu drogowym oraz realizacji innych, doniosłych zadań z zakresu tego bezpieczeństwa. Obecnie natomiast, zgodnie z aktualnym Rozporządzeniem, fundusz zapasowy może być przeznaczony jedynie na pokrycie strat netto ośrodka. W praktyce oznacza to, że środki zgromadzone w funduszu zapasowym pozostają niewykorzystane do czasu wystąpienia ujemnego wyniku finansowego, niezależnie od istniejących potrzeb w zakresie realizacji działań służących poprawie bezpieczeństwa ruchu drogowego. Jednocześnie działania na rzecz poprawy bezpieczeństwa ruchu drogowego stanowią jedno z podstawowych zadań wojewódzkich ośrodków ruchu drogowego, wynikających bezpośrednio z ustawy. Nie mają one charakteru działalności dodatkowej ani fakultatywnej, lecz pozostają integralnym elementem misji publicznej realizowanej przez te podmioty.  Brak jest dostatecznego uzasadnienia dla utrzymywania stanu, w którym środki zgromadzone przez ośrodek pozostają zarezerwowane wyłącznie na pokrycie potencjalnych przyszłych strat, podczas gdy mogą zostać wykorzystane do realizacji ustawowych zadań służących ograniczaniu liczby wypadków drogowych, zwiększaniu świadomości uczestników ruchu drogowego oraz podnoszeniu poziomu bezpieczeństwa na drogach. Proponowane rozwiązanie wychodzi z założenia, że środki funduszu zapasowego powinny służyć nie tylko ochronie stabilności finansowej ośrodka, lecz również wspierać realizację celów publicznych, dla których wojewódzkie ośrodki ruchu drogowego zostały utworzone. Umożliwienie finansowania działań na rzecz bezpieczeństwa ruchu drogowego ze środków funduszu zapasowego pozwoli na bardziej racjonalne i efektywne gospodarowanie zgromadzonym majątkiem, przy jednoczesnym zachowaniu bezpieczeństwa finansowego jednostek.  Powrót do finansowania wydatków, w części przeznaczonej na poprawę bezpieczeństwa ruchu drogowego z funduszu zapasowego, bez wątpienia umożliwiłby zwiększenie skuteczności i efektywności pomocy m.in. placówkom edukacyjno-oświatowym przygotowującym dzieci i młodzież do świadomego i bezpiecznego udziału w ruchu \\fdrogowym na terenie naszego kraju, a ponadto znacząco odciążyłby fundusz z bieżącej działalności ośrodków.   Projektowana regulacja nie zmienia charakteru funduszu zapasowego jako instrumentu wzmacniającego stabilność finansową ośrodka, lecz rozszerza katalog dopuszczalnych sposobów jego wykorzystania o finansowanie działań pozostających w bezpośrednim związku z ustawowymi zadaniami wojewódzkich ośrodków ruchu drogowego. Rozwiązanie to zapewni możliwość przeznaczania wypracowanych przez ośrodki nadwyżek finansowych na cele służące interesowi publicznemu, bez konieczności oczekiwania na wystąpienie okoliczności uzasadniających pokrywanie strat.  Należy jeszcze raz podkreślić, że finansowanie działań na rzecz poprawy bezpieczeństwa ruchu drogowego ze środków funduszu zapasowego nie stanowi przeznaczenia tych środków na cele niezwiązane z działalnością ośrodka. Przeciwnie, środki te byłyby wykorzystywane na realizację zadań ustawowo przypisanych wojewódzkim ośrodkom ruchu drogowego. Proponowana zmiana prowadzi zatem do silniejszego powiązania sposobu wykorzystania wypracowanych nadwyżek finansowych z podstawowymi celami działalności ośrodków, a tym samym wzmacnia funkcjonalny związek pomiędzy gospodarką finansową ośrodka, a realizacją powierzonych mu zadań publicznych.\\t\\n\\t Uwagi dodatkowe\\t Krajowe Stowarzyszenie Egzaminatorów\\t ZAGADNIENIA KRAJOWEGO STOWARZYSZENIA EGZAMINATORÓW wymagające pilnego podjęcia prac oraz wprowadzenia zmian przy okazji procedowanego projektu:  1. Art. 24 – dodanie do pojazdów wykorzystywanych do szkolenia i egzaminowania osób niepełnosprawnych oraz czterokołowców lekkich wykorzystywanych w ramach kat. AM prawa jazdy wymogu przystosowania do nauki jazdy. Na dzień dzisiejszy w przypadku pojazdu będącego własnością osoby niepełnosprawnej, dopuszcza się pojazdy bez dodatkowych lusterek, bez dodatkowego pedału hamulca, a jedyne wymaganie to oznakowanie tablicą „L”. Stanowi to zagrożenia zarówno dla instruktora jak i egzaminatora;   2. Art. 55 ust. 3. Dodanie zapisu dotyczącego przerwania egzaminu praktycznego w przypadku nieprawidłowego prowadzenia przez kandydata na egzaminatora - na dzień dzisiejszy \\fkandydat na egzaminatora w ramach praktyk ma „przeprowadzić”, a nigdzie nie ma zapisu o prawidłowym przeprowadzeniu egzaminów;  3. Art. 56 ust. 7 – skreślenie ustępu 7 – WORD-y ponoszą dodatkowe koszty zapewnienia osobom egzaminowanym tłumacza języka migowego. Dodatkowo brak spójności z przepisami dotyczącymi tłumaczy języków obcych, których zapewniają osoby egzaminowane; 4. Art. 56a – wprowadzenie corocznej waloryzacji wysokości opłat za prowadzenie egzaminów państwowych o wskaźnik inflacji ogłaszany przez GUS. Dodatkowo należałoby rozważyć waloryzacje opłat za inne szkolenia prowadzone przez WORD-y oraz powrót do stawek jednolitych na terenie całej Polski; Należało by również podnieść obecne kwoty określone w tym artykule, aby były adekwatne do dzisiejszych czasów tj. cytuje: Art. 56.1  pkt 2 2) 250 zł w zakresie uprawnień prawa jazdy kategorii B+E, C1+E, C, C+E, D, D+E lub D1+E.  Przelicznik powinien być np. uzależniony od kwoty za egzamin na kategorie B tzn. 9 egzaminów na kategorie B po np. 230 złotych daje nam kwotę 2070 złotych. Powyższą kwote 2070 dzielimy na 5 egzaminów w zakresie  kategorii  C+E co daje nam 414 złoty.  Kwote 2070 złotych możemy podzielic na 6 egzaminów w zakresie prawa jazdy kategorii A,A2,A1,C, B+E i T co daje nam kwote bazową 345 złotych.  Proponujemy podwyższenie ceny za egzamin na kwalifikacje lub zrównanie jej z ceną egzaminu teoretycznego.  5.  Art. 56c – wprowadzenie podpunktu dotyczącego corocznej waloryzacji wynagrodzeń egzaminatorów przeprowadzających egzaminy państwowe o wskaźnik inflacji ogłaszany przez GUS; 6. Art. 58 ust. 1 pkt 1 – przywrócenie zapisu dotyczącego wykształcenia wyższego (o czym pisaliśmy przy art. 33 dotyczącym wykształcenia instruktora) i dodatkowo rozważenie podniesienia wymagania z pkt 2 np. na 5 lat posiadania prawa jazdy. Powrót wykształcenia wyższego podniósłby kompetencje egzaminatorów; 7. Art. 58 ust. 1 pkt 8 – doprecyzowanie przepisów dotyczących rękojmi należytego wykonywania swoich obowiązków. 8. Art. 59 wprowadzenie pkt 5) o treści: B jest uprawniony do egzaminowania w zakresie prawa jazdy kat AM w przypadku egzaminu realizowanego czterokołowcem lekkim – egzamin \\fAM czterokołowcem lekkim w praktyce, poza czasem, wygląda jak egzamin w zakresie kategorii B1 oraz B, a na dzień dzisiejszy WORD-y są zobowiązane do zapewnienia egzaminatora z uprawnieniami do kategorii A;  9. Art. 61 ust. 3 pkt 3 – modyfikacja zapisu zmniejszająca wymaganie dotyczące uczestnictwa w charakterze obserwatora egzaminów teoretycznych do 10 z równoczesnym podniesieniu do 30 w przypadku egzaminów praktycznych ( dotyczy uprawnien  kategorii B). Dodanie zapisu dotyczącego prawidłowego przeprowadzenia 10 egzaminów - na dzień dzisiejszy egzaminatorem może zostać osoba, która w ramach praktyk nie przeprowadziła prawidłowo ani jednego egzaminu; 10. Art. 62 ust 1 – dodanie legitymacji egzaminatora do m-Obywatela; 11. Art. 64 – określenie zasad wynagradzania komisji weryfikacyjnej; 12. Art. 68 ust. 3 – dodanie zapisu o wymogu każdorazowego przesłania wyjaśnień egzaminatora, który prowadził zaskarżony egzamin; 13. Dopuszczenie do egzaminów teoretycznych możliwości uczestnictwa tłumacza przysięgłego języka obcego. Od wejścia ustawy o kierujących zabronione jest uczestnictwo tłumacza co w istotny sposób utrudnia obcokrajowcom zdanie egzaminu teoretycznego. Tłumacz jest na egzaminie praktycznym, a na teorii już nie. Przepisy dopuszczają egzamin teoretyczny tylko dla jednej osoby, ale tylko w przypadku dyslektyków, gdzie drugi egzaminator czyta pytania i odpowiedzi. W analogiczny sposób powinno się dopuszczać egzaminy z tłumaczem przysięgłym języka obcego. W przypadku egzaminu dla dyslektyków powinno dopuścić sie wydłużenie czasu na przeczytanie pytania.  Wówczas można pominąć drugiego egzaminatora.  14. Umożliwienie przeprowadzania części praktycznej egzaminu praktycznego na kat A,B poza granicami miasta w którym zlokalizowany jest WORD. Obecne ograniczenie utrudnia przeprowadzanie egzaminów praktycznych ze względu na ograniczenia infrastruktury szczególnie w oddziałach terenowych umiejscowionych w mniejszych miejscowościach. 15. Zmiana zapisów dotyczących zadań wykonywanych na egzaminie praktycznym w ruchu drogowym – w obecnym systemie prawnym egzamin sprowadza się do jeżdżenia tymi samymi trasami nie w celu sprawdzenia umiejętności kandydatów na kierowców, a celem wykonania zadań egzaminacyjnych. Zmiana zapisu umożliwi egzaminatorom znacznie lepszy dobór tras egzaminacyjnych oraz ograniczy protesty mieszkańców związane z ilością przejazdów pojazdów egzaminacyjnych, co za tym idzie również szkoleniowych, tymi samymi ulicami; \\f16.  Zmiana programu szkolenia kandydatów na egzaminatorów oraz egzaminatorów podnoszących uprawnienia; obecny program nie przygotowuje do pracy w zawodzie egzaminatora. Nacisk kładzie się na zagadnienia zupełnie nieprzydatne w pracy egzaminatora, a brakuje solidnej części praktycznej  17. Wprowadzenie obowiązkowych zajęć w ośrodku doskonalenia techniki jazdy w ramach szkolenia podstawowego lub powrót do planowanego z zagrożeń (tak jak jest to w Szwecji), a ostatecznie wykreślonego szkolenia miedzy 4 a 8 miesiacem – kształtowanie właściwych postaw przyszłego kierującego pod kątem właściwego przygotowania pojazdu do jazdy, warunków decydujących o zachowaniu pojazdu w warunkach specjalnych (nawierzchnia o różnej przyczepności) \\t\\n\\tOSR\\tPolska Wytwórnia Papierów Wartościowych S.A.\\tOcena Skutków Regulacji powinna zostać uzupełniona \\no wskazanie: źródła finansowania i wysokości środków finansowych, jakie PWPW S.A. będzie musiała ponieść w związku \\nz koniecznością dokonania: w przypadku nieuwzględnienia uwagi z poz. 1 - integracji systemu teleinformatycznego, o którym mowa w art. 16a ust. 1 ustawy, z nowym systemem teleinformatycznym, który ma zostać zbudowany \\ni utrzymywany przez ministra właściwego do spraw informatyzacji; przepisy projektu przewidują bowiem obowiązek takiej integracji (np. projektowane brzmienie art. 2 pkt 5 ustawy), nie przewidując jednak żadnych środków finansowych na pokrycie kosztów tej czynności, modyfikacji systemu teleinformatycznego, o którym mowa w art. 16a ust. 1 ustawy, w związku\\n z rozszerzeniem jego funkcjonalności (np. projektowane brzmienie art. 53b ust. 1 ustawy); źródła finansowania i wysokości środków finansowych przeznaczonych na zakup i utrzymanie: urządzeń lokalizujących rejestrujących trasę jazdy, \\furządzeń do rejestracji obrazu i dźwięku z części praktycznej egzaminu wewnętrznego, serwerów niezbędnych do przechowywania danych z urządzeń wskazanych w lit. a i b.  Uzupełnienie Oceny Skutków Regulacji o wskazane informacje.\\t\\n\\tOSR\\tPolski Związek Niewidomych\\tUzupełnienie Oceny Skutków Regulacji 17. Wskazanie osób o szczególnych potrzebach jako grupy oddziaływania Aktualna propozycja zawarta w UD402 W tabeli podmiotów, na które oddziałuje projekt, wymieniono między innymi kandydatów na kierowców, instruktorów, egzaminatorów, zarządców dróg, operatorów oraz użytkowników mikromobilności. Nie wskazano natomiast osób niewidomych, słabowidzących ani innych pieszych o szczególnych potrzebach jako odrębnej grupy oddziaływania. Propozycja PZN PZN proponuje uzupełnić tabelę OSR o następującą grupę: Grupa: osoby niewidome i słabowidzące, osoby z ograniczoną mobilnością, osoby starsze oraz inni piesi o szczególnych potrzebach. Oddziaływanie: potencjalna poprawa bezpieczeństwa i dostępności przestrzeni pieszej, uzależniona od prawidłowego wyznaczenia miejsc postojowych, skutecznej kontroli operatorów i szybkiego usuwania przeszkód; ryzyko negatywnego oddziaływania w przypadku lokalizowania stref na trasach wolnych od przeszkód, oznaczeniach fakturowych lub naturalnych liniach prowadzących. Uzasadnienie \\fOsoby te są bezpośrednimi beneficjentami regulacji. Mogą jednak ponieść również negatywne skutki, jeżeli miejsca postojowe zostaną wyznaczone w sposób niewłaściwy. 18. Uzupełnienie OSR o koszty skutecznego wykonywania obowiązków Aktualna propozycja zawarta w UD402 OSR wskazuje ogólnie, że operatorzy mogą ponosić koszty dostosowania flot i aplikacji, a zarządcy dróg koszty związane z wyznaczeniem miejsc. Nie obejmuje natomiast kosztów pełnego systemu egzekwowania nowych zasad. Propozycja PZN OSR należy uzupełnić o analizę kosztów: dostosowania systemów lokalizacyjnych operatorów; weryfikacji sposobu parkowania; obsługi dostępnego systemu zgłoszeń; relokacji pojazdów; przekazywania danych zarządcom dróg; kontroli wykonywania obowiązków przez operatorów; dostosowania istniejących miejsc postojowych do wymagań dostępności; przeprowadzenia przeglądu istniejących stref. Uzasadnienie Bez określenia rzeczywistych obowiązków i kosztów ich wykonywania nie można rzetelnie ocenić wykonalności projektowanej regulacji.\\t\\n\",\"sha256\":\"d472923a97fe7653d78786da8d0b0d30447caaee86de3b15eec9175f607e24c0\",\"normalized_sha256\":\"text-v2:4fa7db0aa733d0b03176a6a7214ca3a56e660b9ab94a1d5145fdf5088eb44336\",\"complete\":true,\"file_sha256\":\"51238128e4929758db2b01b3c578d707ca85b0797a630c01351add260e628dbd\",\"author\":\"Minister Infrastruktury\"},{\"identity\":\"rcl/784828\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument784828.pdf\",\"role\":\"project_text\",\"text\":\"Projekt z dnia 27.06.2026 r.\\nU S T A W A\\nz dnia ………………….. 2026 r.\\no zmianie ustawy o kierujących pojazdami oraz niektórych innych ustaw1)\\nArt. 1.W ustawie z dnia 5 stycznia 2011 r. o kierujących pojazdami (Dz. U. z 2025 r. poz.\\n1226, 1676 i 1872 oraz 2026 r. poz. 180 i 187) wprowadza się następujące zmiany:\\n1) w art. 2 w pkt 4 kropkę zastępuje się średnikiem i dodaje się pkt 5–7 w brzmieniu:\\n„5) cyfrowej karcie kursanta – należy przez to rozumieć zestaw danych identyfikujących\\nosobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem silnikowym,\\ninstruktora, ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o\\nktórym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, a także dane dotyczące przebiegu\\nszkolenia w zakresie nauki jazdy i części praktycznej egzaminu wewnętrznego,\\nutworzony, udostępniany, aktualizowany i archiwizowany w systemie\\nteleinformatycznym zapewnionym przez ministra właściwego do spraw\\ninformatyzacji, zintegrowanym z systemem, o którym mowa w art. 16a;\\n6) indywidualnym numerze kursanta – należy przez to rozumieć unikalny numer\\nidentyfikujący osobę ubiegającą się o uzyskanie uprawnień do kierowania pojazdem\\nsilnikowym, umożliwiający tej osobie potwierdzanie w cyfrowej karcie kursanta\\ndanych i informacji dotyczących przebiegu szkolenia w zakresie nauki jazdy oraz\\nczęści praktycznej egzaminu wewnętrznego;\\n7) indywidualnym numerze instruktora – należy przez to rozumieć unikalny numer\\nidentyfikujący instruktora, umożliwiający wprowadzenie i potwierdzenie w\\ncyfrowej karcie kursanta danych i informacji dotyczących przebiegu szkolenia w\\nzakresie nauki jazdy oraz części praktycznej egzaminu wewnętrznego, generowany\\nw aplikacji mObywatel.”;\\n2) w art. 23:\\na) w ust. 2 w pkt 2 lit. a otrzymuje brzmienie:\\n„a) na placu manewrowym – nie dotyczy uprawnień do kierowania pojazdami\\nsilnikowymi kategorii B lub B1,”;\\n1) Niniejszą ustawą zmienia się ustawy: ustawę z dnia 21 marca 1985 r. o drogach publicznych, ustawę z dnia 20\\nczerwca 1997 r. – Prawo o ruchu drogowym oraz ustawę z dnia 6 września 2001 r. o transporcie drogowym.\\f– 2 –\\nb) po ust. 2 dodaje się ust. 2a w brzmieniu:\\n„2a. W przypadku szkolenia osoby ubiegającej się o uprawnienia do kierowania\\npojazdem silnikowym kategorii B lub B1, instruktor może, na podstawie oceny\\numiejętności osoby szkolonej, podjąć decyzję o przeprowadzeniu części zajęć z nauki\\njazdy poza drogą publiczną, strefą zamieszkania i strefą ruchu, pod warunkiem\\nzapewnienia przez instruktora stosowania zasad i przepisów ruchu drogowego\\nobowiązujących na drodze publicznej.”;\\n3) po art. 23a dodaje się art. 23b–art. 23j w brzmieniu:\\n„Art. 23b. 1. Przebieg szkolenia w zakresie nauki jazdy oraz części praktycznej\\negzaminu wewnętrznego osoby ubiegającej się o uzyskanie uprawnienia do kierowania\\npojazdem silnikowym rejestruje się w cyfrowej karcie kursanta.\\n2. Organ właściwy w sprawach wydawania dokumentów stwierdzających\\nposiadanie uprawnienia do kierowania pojazdem silnikowym, wraz z utworzeniem\\ncyfrowej karty kursanta, generuje indywidualny numer kursanta.\\n3. Indywidualny numer kursanta może być odwzorowany za pomocą kodu QR w\\naplikacji mObywatel.\\n4. Osoba ubiegająca się o uzyskanie uprawnienia do kierowania pojazdem\\nsilnikowym posiada jedną aktywną cyfrową kartę kursanta dla danej kategorii prawa\\njazdy oraz jeden aktywny indywidualny numer kursanta przez cały okres szkolenia.\\nArt. 23c. 1. W cyfrowej karcie kursanta rejestruje się następujące dane i informacje\\ndotyczące:\\n1) przebiegu szkolenia w zakresie nauki jazdy:\\na) imię i nazwisko oraz numer PESEL lub datę urodzenia osoby ubiegającej się o\\nuzyskanie uprawnienia do kierowania pojazdem silnikowym,\\nb) imię i nazwisko oraz numer uprawnień instruktora przeprowadzającego zajęcia,\\nc) nazwę ośrodka szkolenia kierowców lub podmiotu prowadzącego szkolenie, o\\nktórym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, oraz numer w rejestrze\\nprzedsiębiorców prowadzących ośrodek szkolenia kierowców lub numer w\\newidencji podmiotów prowadzących szkolenie, o których mowa w art. 26 ust.\\n1 pkt 1a lub ust. 3,\\nd) numer rejestracyjny pojazdu, o którym mowa w art. 24,\\ne) datę i godzinę rozpoczęcia zajęć,\\nf) datę i godzinę zakończenia zajęć,\\f– 3 –\\ng) liczbę godzin przeprowadzonych zajęć,\\nh) trasę jazdy w postaci pliku danych lokalizacyjnych w formacie GPX lub\\nrównoważnym,\\ni) liczbę przejechanych kilometrów ustaloną na postawie danych lokalizacyjnych,\\no których mowa w lit. h, albo wskazań licznika pojazdu,\\nj) uwagi instruktora dotyczące przebiegu zajęć,\\nk) uwagi osoby ubiegającej się o uzyskanie uprawnienia do kierowania pojazdem\\nsilnikowym dotyczące przebiegu zajęć,\\nl) informację o potwierdzeniu albo odmowie potwierdzenia przebiegu szkolenia\\nprzez instruktora lub osobę ubiegającą się o uzyskanie uprawnienia do\\nkierowania pojazdem silnikowym;\\n2) przebiegu części praktycznej egzaminu wewnętrznego:\\na) imię i nazwisko oraz numer PESEL lub datę urodzenia osoby ubiegającej się o\\nuzyskanie uprawnienia do kierowania pojazdem silnikowym,\\nb) imię i nazwisko oraz numer uprawnień instruktora przeprowadzającego część\\npraktyczną egzaminu wewnętrznego,\\nc) nazwę ośrodka szkolenia kierowców lub podmiotu prowadzącego szkolenie, o\\nktórym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, oraz numer w rejestrze\\nprzedsiębiorców prowadzących ośrodek szkolenia kierowców lub numer w\\newidencji podmiotów prowadzących szkolenie, o których mowa w art. 26 ust.\\n1 pkt 1a lub ust. 3,\\nd) numer rejestracyjny pojazdu, o którym mowa w art. 24,\\ne) datę i godzinę rozpoczęcia części praktycznej egzaminu wewnętrznego,\\nf) datę i godzinę zakończenia części praktycznej egzaminu wewnętrznego,\\ng) trasę jazdy w postaci pliku danych lokalizacyjnych w formacie GPX lub\\nrównoważnym,\\nh) liczbę przejechanych kilometrów ustaloną na postawie danych lokalizacyjnych,\\no których mowa w lit. g, albo wskazań licznika pojazdu,\\ni) wynik części praktycznej egzaminu wewnętrznego,\\nj) uwagi instruktora dotyczące przebiegu i wyniku części praktycznej egzaminu\\nwewnętrznego,\\f– 4 –\\nk) uwagi osoby ubiegającej się o uzyskanie uprawnienia do kierowania pojazdem\\nsilnikowym dotyczące przebiegu i wyniku części praktycznej egzaminu\\nwewnętrznego,\\nl) informację o potwierdzeniu albo odmowie potwierdzenia przebiegu części\\npraktycznej egzaminu wewnętrznego przez instruktora lub osobę ubiegającą się\\no uzyskanie uprawnienia do kierowania pojazdem silnikowym.\\n2. Instruktor przeprowadzający zajęcia w zakresie nauki jazdy lub część praktyczną\\negzaminu wewnętrznego ma dostęp do danych i informacji zawartych w cyfrowej karcie\\nkursanta w zakresie zajęć lub części praktycznej egzaminu wewnętrznego, po\\nwprowadzeniu swojego imienia i nazwiska oraz numeru w ewidencji instruktorów albo\\nindywidualnego numeru instruktora.\\n3. Przed rozpoczęciem zajęć w zakresie nauki jazdy lub części praktycznej egzaminu\\nwewnętrznego instruktor wprowadza i potwierdza dane i informacje, o których mowa w\\nust. 1 pkt 1 lit. c–e lub pkt 2 lit. c–e.\\n4. Po zakończeniu zajęć w zakresie nauki jazdy lub części praktycznej egzaminu\\nwewnętrznego instruktor wprowadza i potwierdza dane i informacje, o których mowa w\\nust. 1 pkt 1 lit. f, i oraz j lub pkt 2 lit. f oraz h–j.\\n5. Rejestracja danych lokalizacyjnych, o których mowa w ust. 1 pkt 1 lit. h i pkt 2\\nlit. g, odbywa się automatycznie za pomocą urządzenia lokalizacyjnego zainstalowanego\\nw pojeździe, o którym mowa w art. 24, albo za pośrednictwem aplikacji mobilnej\\nzintegrowanej z cyfrową kartą kursanta i obejmuje zapis punktów lokalizacyjnych z\\nczęstotliwością nie mniejszą niż jeden punkt na 5 sekund oraz zapis znacznika czasu dla\\nkażdego punktu. Dane lokalizacyjne są przesyłane do cyfrowej karty kursanta\\nniezwłocznie po zakończeniu jazdy albo części praktycznej egzaminu wewnętrznego.\\n6. Dane lokalizacyjne, o których mowa w ust. 1 pkt 1 lit. f i pkt 2 lit. g, rejestrowane\\nw cyfrowej karcie kursanta nie mogą być zmieniane ani usuwane.\\nArt. 23d. 1. Po zakończeniu zajęć w zakresie nauki jazdy lub części praktycznej\\negzaminu wewnętrznego osoba ubiegająca się o uprawnienia do kierowania pojazdem\\nsilnikowym może wprowadzić w cyfrowej karcie kursanta uwagi, o których mowa w art.\\n23c ust. 1 pkt 1 lit. k lub pkt 2 lit. k oraz potwierdzić albo odmówić potwierdzenia\\nprzebiegu szkolenia lub części praktycznej egzaminu wewnętrznego poprzez\\nwprowadzenie indywidualnego numeru kursanta albo kodu QR, o którym mowa w art.\\n23b ust. 3.\\f– 5 –\\n2. W przypadku odmowy potwierdzenia danych i informacji dotyczących\\nprzebiegu szkolenia lub części praktycznej egzaminu wewnętrznego informacja o tej\\nodmowie jest przekazywana kierownikowi ośrodka szkolenia kierowców albo podmiotu\\nprowadzącego szkolenia, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, zatrudniającego\\ninstruktora.\\n3. Instruktor może sprostować dane i informacje, o których mowa w art. 23c ust. 1\\npkt 1 lit. c–f, i oraz j lub pkt 2 lit. c–f oraz h–j, zarejestrowane w cyfrowej karcie kursanta,\\npo uzyskaniu zgody osoby ubiegającej się o uprawnienia do kierowania pojazdem\\nsilnikowym, potwierdzonej przez wprowadzenie indywidualnego numeru kursanta albo\\nkodu QR, o którym mowa w art. 23b ust. 3.\\n4. Potwierdzenie przez instruktora oraz osobę ubiegającą się o uprawnienia do\\nkierowania pojazdem silnikowym danych i informacji dotyczących przebiegu szkolenia\\nw zakresie nauki jazdy lub części praktycznej egzaminu wewnętrznego stanowi warunek\\nzatwierdzenia w cyfrowej karcie kursanta wpisu dotyczącego przeprowadzonych zajęć\\nlub części praktycznej egzaminu wewnętrznego.\\n5. Jeżeli z przyczyn technicznych nie jest możliwe wprowadzenie przez instruktora\\ndanych i informacji dotyczących przebiegu szkolenia lub części praktycznej egzaminu\\nwewnętrznego lub ich potwierdzenie przez instruktora lub przez osobę ubiegającą się o\\nuprawnienia do kierowania pojazdem silnikowym w sposób, o którym mowa w ust. 4,\\ninstruktor odnotowuje tę przyczynę w cyfrowej karcie kursanta, jeżeli jest to możliwe,\\nalbo dokumentuje ją w inny sposób wraz z danymi i informacjami, w celu ich\\npóźniejszego wprowadzenia do cyfrowej karty kursanta lub późniejszego potwierdzenia\\nniezwłocznie po ustaniu tej przyczyny. Przepis ust. 4 stosuje się odpowiednio.\\n6. Wprowadzenie danych i informacji dotyczących przebiegu szkolenia w zakresie\\nnauki jazdy w sposób, o którym mowa w ust. 5, następuje najpóźniej w ciągu 7 dni lub\\nprzed rozpoczęciem kolejnych zajęć z osobą szkoloną.\\n7. Wprowadzenie danych i informacji dotyczących przebiegu części praktycznej\\negzaminu wewnętrznego w sposób, o którym mowa w ust. 5, następuje niezwłocznie po\\nustaniu przyczyny uniemożliwiającej ich wprowadzenie.\\nArt. 23e. 1. Dostęp do danych i informacji zarejestrowanych w cyfrowej karcie\\nkursanta mają:\\n1) ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym mowa\\nw art. 26 ust. 1 pkt 1a lub ust. 3;\\f– 6 –\\n2) starosta prowadzący rejestr ośrodków szkolenia kierowców albo ewidencję\\npodmiotów prowadzących szkolenie – w zakresie ośrodka albo podmiotu\\nprowadzącego szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, dla\\nktórego prowadzi odpowiednio rejestr albo ewidencję;\\n3) starosta prowadzący ewidencję instruktorów, właściwy miejscowo ze względu na\\nadres zamieszkania instruktora – z wyłączeniem danych lokalizacyjnych, o których\\nmowa w art. 23c ust. 1 pkt 1 lit. h i pkt 2 lit. g;\\n4) wojewódzki ośrodek ruchu drogowego, w którym odbywa się egzamin państwowy\\nosoby ubiegającej się o uprawnienia do kierowania pojazdem silnikowym – z\\nwyłączeniem danych lokalizacyjnych, o których mowa w art. 23c ust. 1 pkt 1 lit. h i\\npkt 2 lit. g.\\n2. Podmioty, o których mowa w ust. 1, uzyskują dostęp do danych i informacji przy\\nużyciu profilu kandydata na kierowcę.\\nArt. 23f. Ośrodek szkolenia kierowców albo podmiot prowadzący szkolenie, o\\nktórym mowa w art. 26 ust. 1 pkt 1a lub ust. 3, jest obowiązany do:\\n1) wyposażenia pojazdu, o którym mowa w art. 24, w urządzenie lokalizacyjne zdolne\\ndo rejestrowania i przesyłania pliku danych lokalizacyjnych w formacie GPX lub\\nrównoważnym do cyfrowej karty kursanta lub do zapewnienia możliwości\\nrejestrowania trasy jazdy w aplikacji mobilnej zintegrowanej z cyfrową kartą\\nkursanta;\\n2) umożliwienia instruktorowi wprowadzania i potwierdzania danych i informacji\\ndotyczących przebiegu szkolenia lub części praktycznej egzaminu wewnętrznego;\\n3) umożliwienia osobie ubiegającej się o uprawnienia do kierowania pojazdem\\nsilnikowym wprowadzania uwag, o których mowa w art. 23c ust. 1 pkt 1 lit. k i pkt\\n2 lit. k, oraz potwierdzania danych i informacji dotyczących przebiegu szkolenia lub\\nczęści praktycznej egzaminu wewnętrznego;\\n4) zgłaszania staroście braku możliwości wprowadzenia lub potwierdzenia danych i\\ninformacji dotyczących przebiegu szkolenia lub części praktycznej egzaminu\\nwewnętrznego w cyfrowej karcie kursanta, jeżeli wprowadzenie lub potwierdzenie\\ntych danych i informacji nie nastąpiło w ciągu 7 dni od zakończenia zajęć lub części\\npraktycznej egzaminu wewnętrznego.\\nArt. 23g. 1. Administratorem danych osobowych zarejestrowanych w cyfrowej\\nkarcie kursanta jest minister właściwy do spraw informatyzacji.\\f– 7 –\\n2. Dane osobowe instruktora oraz osoby ubiegającej się o uprawnienia do kierowania\\npojazdem silnikowym, zawarte w cyfrowej karcie kursanta, przechowuje się przez okres\\n24 miesięcy od dnia uzyskania przez tę osobę pozytywnego wyniku egzaminu\\npaństwowego, a jeżeli osoba ta nie uzyskała pozytywnego wyniku egzaminu\\npaństwowego – od dnia ostatniej czynności zarejestrowanej w cyfrowej karcie kursanta.\\n3. Dane lokalizacyjne w formacie GPX lub równoważnym przetwarza się wyłącznie\\nw celu weryfikacji przebiegu jazd w trakcie zajęć w zakresie nauki jazdy oraz części\\npraktycznej egzaminu wewnętrznego przez podmioty uprawnione do nadzoru oraz\\nkierownika ośrodka szkolenia kierowców albo innego podmiotu prowadzącego szkolenie,\\no którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3.\\nArt. 23h. 1. Przebieg części praktycznej egzaminu wewnętrznego rejestruje się za\\npomocą urządzenia technicznego służącego do zapisu obrazu i dźwięku.\\n2. Urządzenie, o którym mowa w ust. 1, zapewnia ośrodek szkolenia kierowców albo\\npodmiot prowadzący szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a lub ust. 3.\\n3. Urządzenie, o którym mowa w ust. 1, powinno odpowiadać warunkom\\nokreślonym w przepisach wydanych na podstawie art. 66 ust. 1 pkt 1–5, 7 i 8 oraz\\npozwalać na rejestrację przebiegu części praktycznej egzaminu wewnętrznego i\\nprzekazanie zapisu z wykorzystaniem ogólnodostępnych informatycznych nośników\\ndanych.\\n4. Rejestracja, o której mowa w ust. 1, stanowi warunek zakończenia części\\npraktycznej egzaminu wewnętrznego. W przypadku awarii urządzenia, o którym mowa w\\nust. 1, część praktyczna egzaminu wewnętrznego zostaje przerwana i wyznaczona w\\nnowym terminie na koszt ośrodka szkolenia kierowców albo jest kontynuowana pojazdem\\nwyposażonym w sprawne urządzenie.\\n5. Plik z nagraniem przebiegu części praktycznej egzaminu wewnętrznego zapisuje\\nsię w powszechnie stosowanym formacie zapisu i odczytu danych, możliwym do\\nodtworzenia bez specjalistycznego oprogramowania i sprzętu.\\nArt. 23i. Administratorem danych osobowych przetwarzanych w związku z\\nrejestrowaniem przebiegu egzaminu wewnętrznego jest właściwy ośrodek szkolenia\\nkierowców albo podmiot prowadzący szkolenie, o którym mowa w art. 26 ust. 1 pkt 1a\\nlub ust. 3.\\f– 8 –\\nArt. 23j. 1. Zapis przebiegu części praktycznej egzaminu wewnętrznego\\nprzechowuje się przez okres 90 dni od dnia przeprowadzenia tego egzaminu, z\\nuwzględnieniem ust. 2.\\n2. W przypadku wniesienia skargi do Prezesa Urzędu Ochrony Danych Osobowych,\\nwszczęcia postępowania dyscyplinarnego, administracyjnego lub sądowego dotyczącego\\nprzebiegu części praktycznej egzaminu wewnętrznego albo uzasadnionego podejrzenia\\npopełnienia wykroczenia lub przestępstwa podczas części praktycznej egzaminu\\nwewnętrznego zapis przechowuje się do czasu prawomocnego zakończenia\\npostępowania.\\n3. Po upływie okresu, o którym mowa w ust. 1 albo ust. 2, zapis przebiegu części\\npraktycznej egzaminu wewnętrznego podlega trwałemu usunięciu.\\n4. Zapis przebiegu części praktycznej egzaminu wewnętrznego udostępnia się\\nosobie ubiegającej się o uprawnienia do kierowania pojazdem silnikowym – na jej\\nwniosek złożony przed upływem okresu przechowywania zapisu przebiegu części\\npraktycznej egzaminu wewnętrznego, a w przypadku osoby niepełnoletniej – także na\\nwniosek jej rodzica lub przedstawiciela ustawowego.\\n5. Ośrodek szkolenia kierowców lub podmiot prowadzący szkolenie, o którym\\nmowa w art. 26 ust. 1 pkt 1a lub ust. 3, nie może wykorzystywać zapisu przebiegu części\\npraktycznej egzaminu wewnętrznego w celach komercyjnych, promocyjnych,\\nreklamowych ani w innych celach niezwiązanych bezpośrednio z realizacją obowiązku\\nrejestrowania przebiegu części praktycznej egzaminu wewnętrznego, bez zgody osoby\\nubiegającej się o uprawnienia do kierowania pojazdem silnikowym, a w przypadku osoby\\nniepełnoletniej – bez zgody jej rodzica lub przedstawiciela ustawowego.”;\\n4) w art. 24 w pkt 1 w lit. d średnik zastępuje się przecinkiem i dodaje się lit. e w brzmieniu:\\n„e) wyposażonym w urządzenie lokalizacyjne, o którym mowa w art. 23f pkt 1 – w\\nzakresie szkolenia osób ubiegających się o uzyskanie uprawnienia do kierowania\\npojazdem silnikowym;”;\\n5) w art. 27:\\na) w ust. 1 w pkt 6 kropkę zastępuje się średnikiem i dodaje się pkt 7 w brzmieniu:\\n„7) przekazywać staroście, o którym mowa w pkt 1, niezwłocznie, lecz nie później\\nniż w terminie 3 dni roboczych od otrzymania żądania, plik z nagraniem, o\\nktórym mowa w art. 23h ust. 4.”,\\nb) w ust. 2 w pkt 5 kropkę zastępuje się średnikiem i dodaje się pkt 6 w brzmieniu:\\f– 9 –\\n„6) przekazywać staroście, o którym mowa w pkt 1, w terminie 3 dni roboczych od\\notrzymania żądania pliku z nagraniem, o którym mowa w art. 23h ust. 5.”,\\nc) po ust. 4a dodaje się ust. 4b w brzmieniu:\\n„4b. Wydanie zaświadczenia o ukończeniu szkolenia, o którym mowa w ust.\\n4, następuje przez wprowadzenie danych o jego wydaniu do centralnej ewidencji\\nkierowców.”,\\nd) ust. 6 i 7 otrzymują brzmienie:\\n„6. Informacje i dane, o których mowa w ust. 1 pkt 1–2a i 7 oraz ust. 2 pkt 1–\\n3 i 6, przekazuje się staroście przez ich wprowadzenie do centralnej ewidencji\\nkierowców.\\n7.Dokumentacja, o której mowa w ust. 1 pkt 2 i 2a oraz w ust. 2 pkt 2, jest\\nprowadzona w formie elektronicznej.”;\\n6) w art. 28 po ust. 2 dodaje się ust. 2a w brzmieniu:\\n„2a. Wymogu posiadania placu manewrowego, o którym mowa w ust. 2 pkt 1 lit. c,\\nnie stosuje się do ośrodka szkolenia kierowców prowadzącego szkolenie w zakresie\\nuprawnień kategorii B lub B1.”;\\n7) w art. 33:\\na) w ust. 1 po pkt 1 dodaje się pkt 1a w brzmieniu:\\n„1a) posiada co najmniej wykształcenie średnie lub średnie branżowe;”,\\nb) w ust. 1 w pkt 2 lit. a, b i d oraz w pkt 3 wyrazy „2 lat” zastępuje się wyrazami „3\\nlat”,\\nc) w ust. 2 w pkt 1 i w pkt 3 w lit. a wyrazy „pkt 2–8” zastępuje się wyrazami „1a–8”;\\n8) w art. 37 ust. 1a otrzymuje brzmienie:\\n„1a. Obowiązek, o którym mowa w ust. 1 pkt 2 i 3, nie dotyczy osoby, która po raz\\npierwszy uzyskała uprawnienia instruktora w tym samym roku, w którym byłaby\\nobowiązana uczestniczyć w warsztatach doskonalenia zawodowego, oraz osoby, o której\\nmowa w art. 46 ust. 7, w tym samym roku, w którym dokonano ponownego wpisu do\\newidencji.”;\\n9) w art. 38:\\na) w ust. 1 pkt 1 otrzymuje brzmienie:\\n„1) spełnia wymagania, o których mowa w art. 33 ust. 1 pkt 1a, 7 i 8, oraz posiada\\nzaświadczenie o ukończeniu z wynikiem pozytywnym kursu dla kandydatów\\nna instruktorów lub wykładowców;”,\\f– 10 –\\nb) w ust. 2 w pkt 1 i w pkt 4 w lit. a wyrazy „pkt 6–8” zastępuje się wyrazami „pkt 1a,\\n6–8”,\\nc) ust. 6 otrzymuje brzmienie:\\n„6. Obowiązek, o którym mowa w ust. 5 pkt 2 i 3, nie dotyczy osoby, która\\nuzyskała po raz pierwszy uprawnienia wykładowcy w tym samym roku, w którym\\nbyłaby obowiązana uczestniczyć w warsztatach doskonalenia zawodowego, oraz\\nosoby, o której mowa w art. 46 ust. 7, w tym samym roku, w którym dokonano\\nponownego wpisu do ewidencji.”;\\n10) w art. 39 w ust. 7 zdanie pierwsze otrzymuje brzmienie:\\n„Na egzaminie, o którym mowa w art. 33 ust. 1 pkt 7, stosuje się pytania egzaminacyjne\\nopracowane lub zweryfikowane przez Centrum Egzaminowania, o którym mowa w art.\\n57aa ust. 1.”.\\n11) w art. 45 w ust 2:\\na) po pkt 1 dodaje się pkt 1a w brzmieniu:\\n„1a) wielokrotnie nie realizuje obowiązków, o których mowa w art. 23f pkt 1–4;”;\\nb) po pkt 3 dodaje się pkt 3a i 3b w brzmieniu:\\n„3a) wielokrotne niespełnienie obowiązku, o którym mowa w art. 27 ust. 1 pkt 7;\\n3b) wielokrotne naruszenie warunków ochrony zapisanych danych dotyczących\\nprzebiegu części praktycznej egzaminu wewnętrznego, o których mowa w art.\\n23j;”;\\n12) w art. 46:\\na) w ust. 1 w pkt 2 wyrazy „pkt 2–8” zastępuje się wyrazami „pkt 1a–8”,\\nb) w ust. 2 w pkt 2 wyrazy „pkt 6–8” zastępuje się wyrazami „pkt 1a, 6–8”;\\n13) w art. 50 w ust. 2 w pkt 8 kropkę zastępuje się średnikiem i dodaje się pkt 9 w brzmieniu:\\n„9) która powtórnie w tym samym dniu przystępuje do części praktycznej egzaminu\\npaństwowego, z którego uzyskała wynik negatywny.”;\\n14) w art. 51:\\na) w ust. 2a pkt 2 otrzymuje brzmienie:\\n„2) przy użyciu pytań egzaminacyjnych opracowanych lub zweryfikowanych przez\\nCentrum Egzaminowania.”,\\nb) ust. 2b otrzymuje brzmienie:\\n„2b. Pytania egzaminacyjne, o których mowa w ust. 2a pkt 2, oraz scenariusze,\\nwizualizacje i opisy wchodzące w skład tych pytań, stanowią informację publiczną \\f– 11 –\\nw rozumieniu przepisów ustawy z dnia 6 września 2001 r. o dostępie do informacji\\npublicznej.”,\\nc) w ust. 2c wyraz „4000” zastępuje się wyrazem „1500”,\\nd) w ust. 3 w pkt 1:\\n– w lit. a skreśla się wyrazy „B1 i B”,\\n– w lit. b średnik zastępuje się przecinkiem i dodaje się lit. c w brzmieniu:\\n„c) sprawdzenie umiejętności przygotowania do jazdy, sprawdzenie stanu\\ntechnicznego podstawowych elementów pojazdu bezpośrednio\\nodpowiedzialnych za bezpieczeństwo jazdy – w przypadku uprawnień\\nprawa jazdy kategorii B1 i B;”,\\ne) po ust. 3 dodaje się ust. 3a–3c w brzmieniu:\\n„3a. Osoba egzaminowana, która uzyskała pozytywny wynik części\\npraktycznej egzaminu państwowego w zakresie, o którym mowa w ust. 3 pkt 1 albo\\nust. 5 pkt 1, a uzyskała wynik negatywny w zakresie, o którym mowa w ust. 3 pkt 2\\nalbo ust. 5 pkt 2, zachowuje pozytywny wynik uzyskany na placu manewrowym i\\nprzy kolejnym przystąpieniu do części praktycznej egzaminu państwowego w\\nzakresie tej samej kategorii prawa jazdy lub pozwolenia przystępuje wyłącznie do\\nczęści przeprowadzanej w ruchu drogowym.\\n3b. Przepisu ust. 3a nie stosuje się, jeżeli od dnia uzyskania pozytywnego\\nwyniku, o którym mowa w ust. 3 pkt 1 albo ust. 5 pkt 1, minęło więcej niż 24\\nmiesiące.\\n3c. Przepisu ust. 3a nie stosuje się, jeżeli osoba egzaminowana w trakcie\\nkolejnego przystąpienia do egzaminu, o którym mowa w ust. 3a, w sposób określony\\nw przepisach wydanych na podstawie art. 66 ust. 1 pkt 5, kierując pojazdem zagraża\\nbezpośrednio życiu lub zdrowiu uczestników ruchu drogowego – w takim przypadku\\nosoba ta przystępuje ponownie do części praktycznej egzaminu państwowego w\\npełnym zakresie.”,\\nf) ust. 4a otrzymuje brzmienie:\\n„4a. Egzamin państwowy w zakresie prawa jazdy kategorii AM, A1, A2, A,\\nB1, B, B+E lub T może być także przeprowadzany w mieście niespełniającym\\nwarunków, o których mowa w ust. 4, wskazanym przez sejmik województwa na\\nwniosek marszałka województwa.”;\\n15) po art. 51 dodaje się art. 51a w brzmieniu:\\f– 12 –\\n„Art. 51a. 1. Zakazu, o którym mowa w art. 50 ust. 2 pkt 9, nie stosuje się, jeżeli\\negzamin nie doszedł do skutku z przyczyn niezależnych od osoby egzaminowanej.\\n2. W przypadku, o którym mowa w ust. 1, kandydatowi wyznacza się nowy termin\\negzaminu bez pobierania dodatkowej opłaty. Nowy termin może przypadać w tym samym\\ndniu wyłącznie, gdy pozwalają na to warunki techniczne i organizacyjne wojewódzkiego\\nośrodka ruchu drogowego oraz kandydat wyrazi na to zgodę.”;\\n16) w art. 52 w ust. 1 dodaje się zdanie drugie w brzmieniu:\\n „Pozytywny wynik z części teoretycznej jest ważny przez 24 miesiące od dnia jego\\nuzyskania.”;\\n17) w art. 53 po ust. 4a dodaje się ust. 4b w brzmieniu:\\n„4b. Praktyczna część egzaminu państwowego, o którym mowa w art. 56 ust. 2b,\\nmoże być prowadzona pojazdem udostępnionym przez jednostkę wojskową prowadzącą\\nszkolenie żołnierzy na potrzeby Sił Zbrojnych Rzeczypospolitej Polskiej.”;\\n18) po art. 53a dodaje się art. 53b i art. 53c w brzmieniu:\\n„Art. 53b. 1. Wojewódzki ośrodek ruchu drogowego odnotowuje w systemie\\nteleinformatycznym umożliwiającym realizację zadań organów właściwych do\\nwydawania dokumentów stwierdzających uprawnienia do kierowania pojazdami, o\\nktórym mowa w art. 16a ust. 1, pozytywny wynik części praktycznej egzaminu\\npaństwowego uzyskany na placu manewrowym, wraz z datą jego uzyskania oraz\\nwskazaniem kategorii prawa jazdy lub pozwolenia, której wynik dotyczy.\\n2. Opłata za część praktyczną egzaminu państwowego przeprowadzaną na\\npodstawie art. 51 ust. 3a jest pobierana w tej samej wysokości jak opłata za\\nprzeprowadzenie części praktycznej na podstawie art. 51 ust. 3.\\nArt. 53c. W przypadku przeprowadzania części praktycznej egzaminu państwowego\\nna podstawie art. 51 ust. 3a, egzaminator nie ocenia ponownie zadań wykonywanych na\\nplacu manewrowym, a wynik egzaminu ustala wyłącznie na podstawie zadań\\nwykonanych w ruchu drogowym.”;\\n19) w art. 54:\\na) ust. 1 otrzymuje brzmienie:\\n„1. Przebieg części praktycznej egzaminu państwowego dla każdej kategorii prawa\\njazdy rejestruje się za pomocą urządzenia służącego do zapisu obrazu i dźwięku. W\\nprzypadku egzaminu państwowego przeprowadzanego pojazdem jednośladowym\\nrejestracja odbywa się za pomocą urządzenia zainstalowanego w pojeździe \\f– 13 –\\ntowarzyszącym, a w miarę możliwości technicznych – także za pomocą urządzenia\\nrejestrującego zainstalowanego na pojeździe egzaminacyjnym lub w wyposażeniu osoby\\negzaminowanej.”,\\nb)  uchyla się ust. 3,\\nc) ust. 5 otrzymuje brzmienie:\\n„5. Jeżeli egzamin jest przeprowadzany pojazdem:\\n1) osoby niepełnosprawnej wymagającej przystosowania pojazdu do rodzaju\\nschorzenia,\\n2) bez pedału sprzęgła, jeżeli nie jest to pojazd będący w dyspozycji wojewódzkiego\\nośrodka ruchu drogowego\\n– urządzenie, o którym mowa w ust. 1, zapewnia wojewódzki ośrodek ruchu\\ndrogowego.”;\\n20) w art. 56 po ust. 2a dodaje się ust. 2b i 2c w brzmieniu:\\n„2b. Na wniosek jednostki wojskowej prowadzącej szkolenie żołnierzy na potrzeby\\nSił Zbrojnych Rzeczypospolitej Polskiej, egzamin państwowy może być przeprowadzony\\nna terenie tej jednostki wojskowej lub innej infrastruktury pozostającej w jej dyspozycji,\\nz wykorzystaniem pojazdu wskazanego przez tę jednostkę, spełniającego wymagania, o\\nktórych mowa w art. 24.\\n2c. Koszty przeprowadzenia egzaminu państwowego w sposób określony w ust. 2b,\\nw tym koszty związane z wykorzystaniem pojazdu oraz organizacją miejsca\\nprzeprowadzenia egzaminu, ponosi jednostka wojskowa występująca z wnioskiem.”\\n21) uchyla się art. 57a;\\n22) po art. 57a dodaje się art. 57aa–art. 57ae w brzmieniu:\\n„Art. 57aa. 1. Tworzy się Centrum Egzaminowania, działające w ramach struktury\\norganizacyjnej Instytutu Transportu Samochodowego.\\n2. Do zadań Centrum Egzaminowania należy w szczególności:\\n1) opracowywanie lub zlecanie opracowania pytań egzaminacyjnych oraz scenariuszy,\\nwizualizacji i opisów wchodzących w skład tych pytań egzaminacyjnych\\nstosowanych na egzaminie państwowym, egzaminach teoretycznych, o których\\nmowa w art. 33 ust. 1 pkt 7, art. 58 ust. 1 pkt 7 i art. 117 ust. 2 pkt 7, lub testach\\nkwalifikacyjnych, o których mowa w art. 39b ust. 3 ustawy z dnia 6 września 2001\\nr. o transporcie drogowym;\\f– 14 –\\n2) weryfikowanie propozycji pytań egzaminacyjnych, o których mowa w pkt 1, oraz\\nscenariuszy, wizualizacji i opisów wchodzących w skład tych pytań\\negzaminacyjnych, przekazanych przez podmioty zewnętrzne oraz  osoby prywatne\\nlub zleconych do opracowania przez Centrum Egzaminowania;\\n3) aktualizowanie i zapewnienie zgodności pytań egzaminacyjnych, o których mowa w\\npkt 1, z obowiązującymi przepisami prawa i zasadami ruchu drogowego, postępem\\ntechnologicznym w motoryzacji oraz aktualnym stanem wiedzy technicznej i wiedzy\\nmedycznej w zakresie udzielania pierwszej pomocy;\\n4) walidacja pytań egzaminacyjnych, o których mowa w pkt 1, na podstawie analizy\\nwyników egzaminów, danych o wypadkach drogowych i rekomendacji Rady\\nKonsultacyjnej;\\n5) gromadzenie, przetwarzanie i publikowanie danych statystycznych dotyczących\\nwyników egzaminów państwowych z podziałem na instruktorów prowadzących\\nszkolenie, ośrodki szkolenia kierowców i ośrodki szkolenia, ośrodki doskonalenia\\ntechniki jazdy i wojewódzkie ośrodki ruchu drogowego, ze wskazaniem wartości\\nśredniej oraz najmniejszej i największej;\\n6) publikowanie na stronie podmiotowej Instytutu Transportu Drogowego aktualnego\\nkatalogu pytań egzaminacyjnych stosowanych na egzaminie państwowym na prawo\\njazdy;\\n7) opracowywanie i publikowanie podstaw programowych szkolenia kandydatów na\\nkierowców i kierowców, kandydatów na instruktorów i instruktorów, kandydatów\\nna egzaminatorów i egzaminatorów, kandydatów na instruktorów techniki jazdy i\\ninstruktorów techniki jazdy oraz kandydatów na kierowców wykonujących transport\\ndrogowy;\\n8) wydawanie rozstrzygnięcia w zakresie prawidłowości pytania egzaminacyjnego\\nbędącego podstawą skargi na część teoretyczną egzaminu państwowego, egzaminy\\nteoretyczne, o których mowa w art. 33 ust. 1 pkt 7, art. 58 ust. 1 pkt 7 i art. 117 ust.\\n2 pkt 7, lub testy kwalifikacyjne, o których mowa w art. 39b ust. 3 ustawy z dnia 6\\nwrześnia 2001 r. o transporcie drogowym.\\n3. Rozstrzygnięcia, o których mowa w ust. 2 pkt 8, są wydawane na wniosek\\nmarszałka województwa właściwego do rozpatrzenia skargi, o której mowa w art. 68 ust.\\n1, w terminie 7 dni od dnia złożenia wniosku.\\f– 15 –\\nArt. 57ab. 1. Propozycje pytań egzaminacyjnych, o których mowa w art. 57aa ust. 2\\npkt 1, oraz scenariuszy, wizualizacji i opisów wchodzących w skład tych pytań, mogą być\\nprzekazywane Centrum Egzaminowania przez podmioty zewnętrzne oraz osoby\\nprywatne.\\n2. Centrum Egzaminowania informuje podmioty zewnętrzne oraz osoby prywatne o\\npozytywnej lub negatywnej weryfikacji propozycji pytań egzaminacyjnych, o których\\nmowa w art. 57aa ust. 2 pkt 1, oraz scenariuszy, wizualizacji i opisów wchodzących w\\nskład tych pytań, w terminie 30 dni do dnia dokonania weryfikacji.\\n3. W ramach weryfikacji, o której mowa w art. 57aa ust. 2 pkt 3, Centrum\\nEgzaminowania może ingerować w treść propozycji pytań egzaminacyjnych, o których\\nmowa w art. 57aa ust. 2 pkt 1, oraz scenariuszy, wizualizacji i opisów wchodzących w\\nskład tych pytań, lub wykorzystywać tylko ich część.\\n4. Podmiotom zewnętrznym oraz osobom prywatnym, które przekazały Centrum\\nEgzaminowania propozycje pytań egzaminacyjnych, o których mowa w art. 57aa ust. 2\\npkt 1, oraz scenariuszy, wizualizacji i opisów wchodzących w skład tych pytań, nie\\nprzysługuje wynagrodzenie za przekazanie tych propozycji, ani za ich przetwarzanie, w\\ntym wykorzystanie pozytywnie zweryfikowanych propozycji pytań egzaminacyjnych lub\\nich części, na egzaminie państwowym,  egzaminach teoretycznych, o których mowa w\\nart. 33 ust. 1 pkt 7, art. 58 ust. 1 pkt 7 i art. 117 ust. 2 pkt 7, lub  testach kwalifikacyjnych,\\no których mowa w art. 39b ust. 3 ustawy z dnia 6 września 2001 r. o transporcie\\ndrogowym.\\n5. Z chwilą przekazania Centrum Egzaminowania propozycji pytań\\negzaminacyjnych, o których mowa w art. 57aa ust. 2 pkt 1, oraz scenariuszy, wizualizacji\\ni opisów wchodzących w skład tych pytań, podmiot zewnętrzny lub osoba prywatna, która\\nje przekazała, przenosi na Skarb Państwa, reprezentowany przez Instytut Transportu\\nSamochodowego, autorskie prawa majątkowe do tych propozycji, bez ograniczeń\\nczasowych i terytorialnych, z prawem ich wykorzystywania na wszystkich polach\\neksploatacji.\\nArt. 57ac. 1. Centrum Egzaminowania opracowuje lub weryfikuje pytania\\negzaminacyjne stosowane na egzaminie państwowym, egzaminach teoretycznych, o\\nktórych mowa w art. 33 ust. 1 pkt 7, art. 58 ust. 1 pkt 7 i art. 117 ust. 2 pkt 7, oraz  testach\\nkwalifikacyjnych, o których mowa w art. 39b ust. 3 ustawy z dnia 6 września 2001 r. o\\ntransporcie drogowym, w systemie teleinformatycznym zapewnionym przez ministra \\f– 16 –\\nwłaściwego do spraw informatyzacji, z którym jest zintegrowany system\\nteleinformatyczny, o którym mowa w art. 51 ust. 2a pkt 1.\\n2. Utworzenie i utrzymanie systemu teleinformatycznego, o którym mowa w ust. 1,\\njest finansowane z Funduszu – Centralna Ewidencja Pojazdów i Kierowców, o którym\\nmowa w art. 80d ustawy z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym.\\nArt. 57ad. 1. Przy Centrum Egzaminowania działa Rada Konsultacyjna, będąca\\norganem opiniodawczo-doradczym Centrum Egzaminowania.\\n2. Centrum Egzaminacyjne może, w celu realizacji poszczególnych zadań, zasięgać\\nopinii Rady Konsultacyjnej, której skład wyznacza minister właściwy do spraw\\ntransportu, w drodze zarządzenia.\\n3. W skład Rady Konsultacyjnej, o której mowa w ust. 1, wchodzi co najmniej 12\\nekspertów posiadających wiedzę, dorobek naukowy lub udokumentowane doświadczenie\\nzawodowe w zakresie co najmniej jednej z następujących dziedzin:\\n1) bezpieczeństwo ruchu drogowego;\\n2) szkolenie i egzaminowanie kandydatów na kierowców i kierowców, kandydatów na\\ninstruktorów i instruktorów, kandydatów na egzaminatorów i egzaminatorów,\\nkandydatów na instruktorów techniki jazdy i instruktorów techniki jazdy lub\\nkandydatów na kierowców wykonujących transport drogowy i kierowców\\nwykonujących transport drogowy;\\n3) kontrola ruchu drogowego lub kontrola transportu drogowego;\\n4) prowadzenie działań ratowniczych, ochrona ludności lub zapewnienie\\nbezpieczeństwa publicznego;\\n5) psychologia transportu, dydaktyka lub metodyka kształcenia;\\n6) medycyna ratunkowa lub ratownictwo medyczne.\\nArt. 57ae. Centrum Egzaminowania opracowuje i publikuje na stronie podmiotowej\\nInstytutu Transportu Samochodowego podstawy programowe szkolenia kandydatów na\\nkierowców i kierowców, kandydatów na instruktorów i instruktorów, kandydatów na\\negzaminatorów i egzaminatorów, kandydatów na instruktorów techniki jazdy i\\ninstruktorów techniki jazdy oraz kandydatów na kierowców wykonujących transport\\ndrogowy, określające w szczególności:\\n1) w zakresie szkolenia kandydatów na kierowców i kierowców – cele edukacyjne\\nszkolenia w zakresie niezbędnej wiedzy i umiejętności dotyczących kompetencji\\nniezbędnych do bezpiecznej jazdy, opanowania pojazdu, świadomości czynników \\f– 17 –\\nzwiększających ryzyko wypadku oraz umiejętności obiektywnej oceny własnych\\nkompetencji i postaw;\\n2) w zakresie szkolenia kandydatów na instruktorów nauki jazdy i instruktorów – cele\\nedukacyjne szkolenia w zakresie niezbędnej wiedzy, umiejętności dydaktycznych i\\nmetodycznych oraz kompetencji zawodowych koniecznych do prawidłowego\\nprzygotowania kandydatów na kierowców do bezpiecznego uczestnictwa w ruchu\\ndrogowym, kształtowania właściwych postaw, rozpoznawania zagrożeń oraz oceny\\npostępów osoby szkolonej;\\n3) w zakresie szkolenia kandydatów na egzaminatorów i egzaminatorów – cele\\nedukacyjne szkolenia w zakresie niezbędnej wiedzy, umiejętności i kompetencji\\nkoniecznych do rzetelnego, obiektywnego i jednolitego przeprowadzania\\negzaminów państwowych, oceny zachowania osoby egzaminowanej w ruchu\\ndrogowym, rozpoznawania sytuacji niebezpiecznych oraz uzasadniania\\npodejmowanych decyzji egzaminacyjnych;\\n4) w zakresie szkolenia kandydatów na instruktorów techniki jazdy i instruktorów\\ntechniki jazdy – cele edukacyjne szkolenia w zakresie niezbędnej wiedzy,\\numiejętności praktycznych i kompetencji dydaktycznych koniecznych do\\nprowadzenia zajęć doskonalących technikę jazdy, w szczególności dotyczących\\npanowania nad pojazdem, przewidywania i unikania zagrożeń, reagowania w\\nsytuacjach awaryjnych oraz kształtowania świadomości ograniczeń kierowcy i\\npojazdu;\\n5) w zakresie szkolenia kandydatów na kierowców wykonujących transport drogowy –\\ncele edukacyjne szkolenia w zakresie niezbędnej wiedzy, umiejętności i kompetencji\\nzawodowych koniecznych do bezpiecznego, odpowiedzialnego i zgodnego z\\nprzepisami wykonywania przewozu drogowego, z uwzględnieniem zasad\\nbezpieczeństwa ruchu drogowego, czasu pracy kierowców, czasu prowadzenia\\npojazdów, obowiązkowych przerw i okresów odpoczynku oraz stosowania\\ntachografów, obsługi pojazdu, przewozu osób lub rzeczy oraz świadomości ryzyk\\nzwiązanych z wykonywaniem zawodu kierowcy;\\n6) zalecane metody dydaktyczne i formy prowadzenia zajęć;\\n7) wymagania dotyczące warunków przeprowadzania szkolenia.”;\\n23) w art. 57c ust. 1 otrzymuje brzmienie:\\f– 18 –\\n„1. Wojewódzkie ośrodki ruchu drogowego przekazują 2 zł z opłaty za\\nprzeprowadzenie części teoretycznej egzaminu państwowego na rachunek bankowy\\nInstytutu Transportu Samochodowego na cele utworzenia, działalności i rozwoju Centrum\\nEgzaminowania.”;\\n24) uchyla się art. 57d;\\n25) w art. 63 ust. 1a otrzymuje brzmienie:\\n„1a. Obowiązek, o którym mowa w ust. 1 pkt 2 i 3, nie dotyczy osoby, która\\nuzyskała po raz pierwszy uprawnienia egzaminatora w tym samym roku, w którym byłaby\\nobowiązana uczestniczyć w warsztatach doskonalenia zawodowego, oraz osoby, o której\\nmowa w art. 71 ust. 6, w tym samym roku, w którym dokonano ponownego wpisu do\\newidencji.”;\\n26) w art. 64 w ust. 7a w pkt 1 zdanie pierwsze otrzymuje brzmienie:\\n „przy użyciu pytań egzaminacyjnych z katalogu pytań egzaminacyjnych opracowanych\\nlub zweryfikowanych przez Centrum Egzaminowania, o którym mowa w art. 57aa ust.\\n1;”;\\n27) w art. 69 ust. 2 otrzymuje brzmienie:\\n„2. Analizę, o której mowa w art. 67 ust. 1 pkt 8 lit. a, sporządza marszałek\\nwojewództwa na podstawie danych uzyskanych z wojewódzkiego ośrodka ruchu\\ndrogowego oraz podaje ją do publicznej wiadomości.”;\\n28) w art. 112 w ust. 1 w pkt 2 w lit. d kropkę zastępuje się średnikiem i dodaje się pkt 3 w\\nbrzmieniu:\\n„3) ośrodku szkolenia kierowców – w zakresie szkolenia mającego na celu doskonalenie\\numiejętności kierowania pojazdem w zakresie objętym posiadanym uprawnieniem\\nlub przygotowania do kontrolnego sprawdzenia kwalifikacji, o którym mowa w art.\\n49 ust. 1 pkt 2 i 3.”;\\n29)  w art. 119 w ust. 5a zdanie pierwsze otrzymuje brzmienie:\\n„Na egzaminie, o którym mowa w art. 117 ust. 2 pkt 7, stosuje się pytania egzaminacyjne\\npochodzące z katalogu pytań opracowanych lub zweryfikowanych przez Centrum\\nEgzaminowania, o którym mowa w art. 57aa ust. 1.”.\\nArt. 2. W ustawie z dnia 21 marca 1985 r. o drogach publicznych (Dz. U. z 2025 r. poz.\\n889 oraz z 2026 r. poz. 815) w art. 20 w pkt 20 kropkę zastępuje się średnikiem i dodaje się pkt\\n21 w brzmieniu:\\f– 19 –\\n„21) wyznaczanie miejsc przeznaczonych do postoju pojazdów lub urządzeń\\nprzeznaczonych do indywidualnego przemieszczania się na krótkich dystansach, w\\nszczególności rowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego\\nudostępnianych w ramach mikromobilności dzielonej, w rozumieniu art. 2 pkt 47d ustawy z\\ndnia 20 czerwca 1997 roku – Prawo o ruchu drogowym.”.\\nArt. 3. W ustawie z dnia 20 czerwca 1997 r. – Prawo o ruchu drogowym (Dz. U. z 2024\\nr. poz. 1251, z późn. zm.2)) wprowadza się następujące zmiany:\\n1) w art. 2 po pkt 47c dodaje się pkt 47d w brzmieniu:\\n„47d) mikromobilność dzielona – usługę polegającą na udostępnianiu użytkownikom, w\\nsposób odpłatny lub nieodpłatny, pojazdów lub urządzeń przeznaczonych do\\nindywidualnego przemieszczania się na krótkich dystansach, w szczególności\\nrowerów, hulajnóg elektrycznych lub urządzeń transportu osobistego, z\\nwykorzystaniem aplikacji mobilnej lub innego systemu teleinformatycznego\\numożliwiającego korzystanie z tych pojazdów lub urządzeń przez wielu\\nużytkowników;”;\\n2) w art. 47 po ust. 3 dodaje się ust. 3a w brzmieniu:\\n„3a. Osoba pozostawiająca pojazd lub urządzenie przeznaczone do indywidualnego\\nprzemieszczania się na krótkich dystansach, w szczególności rower, hulajnogę\\nelektryczną lub urządzenie transportu osobistego udostępnione w ramach\\nmikromobilności dzielonej jest obowiązana zakończyć postój wyłącznie w miejscu\\nwyznaczonym do tego celu przez zarządcę drogi.”;\\n3) w art. 130a:\\n a) w ust. 1 w pkt 7 kropkę zastępuje się średnikiem i dodaje się pkt 8 w brzmieniu:\\n„8) pozostawienia, z naruszeniem art. 47 ust. 3a, pojazdu lub urządzenia przeznaczonego\\ndo indywidualnego przemieszczania się na krótkich dystansach, w szczególności\\nroweru, hulajnogi elektrycznej lub urządzenia transportu osobistego udostępnionego\\nw ramach mikromobilności dzielonej, poza miejscem wyznaczonym do tego celu\\nprzez zarządcę drogi.”;\\nb) w ust. 6a w lit. h kropkę zastępuje się średnikiem i dodaje się lit. i w brzmieniu:\\n2) Zmiany tekstu jednolitego wymienionej ustawy zostały ogłoszone w Dz. U. z 2025 r. poz. 820, 1006, 1676,\\n1734, 1843 i 1872 oraz z 2026 r. poz. 180.\\f– 20 –\\n„i) urządzenie przeznaczone do indywidualnego przemieszczania się na krótkich\\ndystansach, udostępnione w ramach mikromobilności dzielonej - za usunięcie - 200\\nzł; za każdą dobę przechowywania - 50 zł.”.\\nArt. 4. W ustawie z dnia 6 września 2001 r. o transporcie drogowym (Dz. U. z 2025 poz.\\n1490, 1676, 1795 i 1843) w art. 39b1 w ust. 6 wyrazy „zatwierdzonych przez ministra\\nwłaściwego do spraw transportu” zastępuje się wyrazami „opracowanych lub\\nzweryfikowanych przez Centrum Egzaminowania, o którym mowa w art. 57aa ust. 1 ustawy z\\ndnia 5 stycznia 2011 r. o kierujących pojazdami”.\\nArt. 5. Osobę wpisaną w dniu wejścia w życie ustawy do ewidencji, o których mowa w\\nart. 33 ust. 2 i art. 38 ust. 2 ustawy zmienianej w art. 1, uznaje się za spełniającą wymagania w\\nzakresie dotychczas posiadanych uprawnień.\\nArt. 6. Do spraw wszczętych i niezakończonych przed dniem wejścia w życie niniejszej\\nustawy, związanych z wpisem do ewidencji, o których mowa w art. 33 ust. 2 i art. 38 ust. 2\\nustawy zmienianej w art. 1, stosuje się przepisy dotychczasowe.\\nArt. 7. Do spraw wszczętych i niezakończonych przed dniem wejścia w życie niniejszej\\nustawy, związanych z wpisem do rejestru przedsiębiorców prowadzących ośrodek szkolenia\\nkierowców, o którym mowa w art. 28 ust. 1 ustawy zmienianej w art. 1, lub ewidencji\\npodmiotów prowadzących szkolenie, o których mowa w art. 29 ust. 1–2a tej ustawy, stosuje\\nsię przepisy ustawy zmienianej w art. 1 w brzmieniu nadanym niniejszą ustawą.\\nArt. 8. Pozytywny wynik części teoretycznej egzaminu państwowego uzyskany przed\\ndniem wejścia w życie niniejszej ustawy zachowuje ważność bezterminowo, na zasadach\\ndotychczasowych. Przepis art. 52 ust. 1 zdanie drugie ustawy zmienianej w art. 1, w brzmieniu\\nnadanym niniejszą ustawą, stosuje się wyłącznie do pozytywnych wyników części teoretycznej\\negzaminu państwowego uzyskanych od dnia wejścia w życie niniejszej ustawy.\\nArt. 9. Pytania egzaminacyjne stosowane na egzaminie państwowym,   egzaminach, o\\nktórych mowa w art. 33 ust. 1 pkt 7, art. 58 ust. 1 pkt 7 i art. 117 ust. 2 pkt 7 ustawy zmienianej\\nw art. 1, lub  testach kwalifikacyjnych, o których mowa w art. 39b ust. 3 ustawy zmienianej w\\nart. 4 , zatwierdzone przez ministra właściwego do spraw transportu na podstawie art. 57a ust.\\n3 ustawy zmienianej w art. 1, w brzmieniu dotychczasowym, stosuje się do dnia opracowania\\nlub zweryfikowania pytań egzaminacyjnych przez Centrum Egzaminowania, o którym mowa \\f– 21 –\\nw art. 57aa ust. 1 ustawy zmienianej w art. 1, jednak nie dłużej niż przez okres 24 miesięcy od\\ndnia wejścia w życie niniejszej ustawy.\\nArt. 10. Ustawa wchodzi w życie z dniem 1 stycznia 2027 r., z wyjątkiem:\\n1) art. 1 pkt 3 w zakresie art. 23h–23j ustawy z dnia 5 stycznia 2011 r. o kierujących\\npojazdami, pkt 7–9 i 11, które wchodzą w życie z dniem 1 lipca 2027 r.;\\n2) art. 1 pkt 10, 14 lit. a–c, 21, 22, 24, 26, 29, art. 2–4 oraz art. 9, które wchodzą w życie z\\ndniem 1 stycznia 2028 r.;\\n3) art. 1 pkt 1, 3 w zakresie art. 23b–23g ustawy z dnia 5 stycznia 2011 r o kierujących\\npojazdami, pkt 4, 5, 11 i 12, które wchodzą w życie z dniem 1 stycznia 2029 r.\\nZa zgodność pod względem prawnym,\\nlegislacyjnym i redakcyjnym\\nTomasz Behrendt\\nZastępca Dyrektora Departamentu Prawnego\\nw Ministerstwie Infrastruktury\",\"sha256\":\"c825feb6c5a5177f52d697f37e0580526ddf2fbdcb9e50b532a70eb3112298ad\",\"normalized_sha256\":\"text-v2:bacae7321d49781a7bbe57d8bb4eb15271e9a1fb71d2b1ec3b723146e6c86dc2\",\"complete\":true,\"file_sha256\":\"397d5858bff88dd438fbd22ef85cfaa0e822dfb427a7a8a586381bde0cf68cef\",\"author\":\"\"}],\"act_eli\":null,\"promulgation_date\":null,\"canonical_date\":null,\"comparison_sha256\":null},\"input_bill_json\":\"\",\"since\":\"2026-10-14T10:22:31Z\",\"baseline_day\":\"2026-10-14\",\"checked_at\":null,\"limitation\":\"\",\"source_key\":\"review-input:ea7a8cd7b9d5f747a8a919a86053ab881561e9f835ba67f3caecd8157b55caaa\",\"act_eli\":null}],\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument784828.pdf\",\"kind\":\"rcl\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:373b3fe1580566c755268bed86e244514711999ed475d7dbc4ed7f1fd1f4f91e\",\"analysis_revision\":2,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект серьёзно меняет обучение и экзамены на польские права, вводит пилот цифровой карты курсанта и обязательную видеозапись практики. Уточняются правила обмена иностранных прав без срока действия и упрощается подтверждение кода 95 для водителей-профессионалов.\",\"key_changes\":[\"Новый порядок для обмена иностранных прав без срока действия на польские с обычными сроками\",\"Пилот «cyfrowa karta kursanta» с записью часов вождения и GPS‑маршрутов в e‑системе\",\"Обязательная видеозапись практики: внутренний экзамен (видео), госэкзамен (видео+аудио)\",\"Теория действует 12 мес., результат плаца (другие категории) хранится 24 мес. и повторно не сдаётся\",\"Шеринг‑самокаты/велосипеды можно оставлять только в спецзонах; вне зоны — эвакуация и платёж\"],\"affected_groups\":[\"иностранцы, проходящие курсы в польских автошколах\",\"владельцы национальных прав из стран вне ЕС/EFTA/Швейцарии, обменивающие их на польские\",\"иностранные водители‑профессионалы, получающие świadectwo kierowcy в Польше\",\"иностранные родители и дети, получающие kartę rowerową\",\"иностранцы, пользующиеся шеринг‑самокатами и велосипедами в Польше\"],\"practical_impact\":\"Иностранцам, обменивающим права третьих стран без указанного срока, польское право будет выдаваться на стандартный ограниченный срок. Обучение и экзамены на права будут фиксироваться в видео и цифровых записях, теория будет действовать только 12 месяцев, а шеринг‑самокаты придётся оставлять в отмеченных парковках, иначе грозит эвакуация и сборы.\",\"effective_date\":\"Закон вступает в силу 1 января 2027 г., кроме: части норм (цифровая карта курсанта, видеозапись внутренних экзаменов, повышенные требования к инструкторам и переходные правила) – с 1 июля 2027 г.; положений о Центрум ds. Szkolenia i Egzaminowania и новых правилах микромобильности и транспорта drogowego – с 1 января 2028 г.; детальных норм о пилотном проекте cyfrowa karta kursanta – с 1 января 2029 г.\",\"confidence\":0.84,\"rationale\":\"Акт комплексно меняет систему обучения и экзаменов на права, обмен иностранных прав и доступ к профессии водителя, что затрагивает многих иностранцев как участников дорожного движения, поэтому категория «social» и значимость 3.\",\"mnemonic_candidate\":\"Цифровой курсант\",\"mnemonic_fallback\":\"Реформа обучения водителей\",\"mnemonic_basis\":\"Проект вводит пилот цифровой карты курсанта и обязательную видеозапись практических экзаменов.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[\"Цифровая карта курсанта теперь запускается как добровольный пилот, а не сразу как единая обязательная система.\",\"Срок действия теоретического экзамена установлен на 12 месяцев, а не на 24, как описывалось ранее.\",\"Добавлены специальные правила для обмена иностранных прав без указанного срока действия на польские.\",\"Введена аболиция для добросовестных водителей при выявлении подлога документов автошколой и предел 2 лет на аннулирование экзамена.\",\"Точно прописаны размеры сборов за эвакуацию и хранение шеринг‑самокатов/велосипедов (200 zł + 50 zł/сутки).\",\"Существенно расширены и детализированы правила детского велодвижения и karty rowerowej (возраст, опека, стандарты экзамена).\"]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"input_chars\":182566,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-17T09:07:43Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument800663.pdf\",\"source_kind\":\"rcl\",\"revision\":3,\"text_sha256\":\"text-v2:e269ba14f2def14a7f75e5e59ac1b780a3dbfa9b61528de4ab8ff2718d14a151\",\"selection\":{\"question\":\"bill_text\",\"state\":\"selected\",\"belonging\":[],\"role\":[],\"version\":[\"rcl/12411950/stage/13212208\",\"25.09.2026 UD 402_projekt ustawy-3.pdf\"],\"completeness\":[],\"parts\":[{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument800663.pdf\",\"members\":[],\"container_sha256\":\"c4a337e9c3afdff072cc9f078d2f3707d79db86a268d7010bb5f0db72eb567dc\",\"sha256\":\"c4a337e9c3afdff072cc9f078d2f3707d79db86a268d7010bb5f0db72eb567dc\",\"role\":\"bill\",\"text\":\"\",\"pages\":30,\"page_start\":1,\"page_end\":30,\"text_start\":0,\"text_end\":62827,\"text_sha256\":\"9f860804ffbcbd2e6edc49c12d10f755a7e389a5fc0fa22fe4eeab70fbe23aa7\",\"losses\":[]},{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411950/13212208/13212209/dokument800664.pdf\",\"members\":[],\"container_sha256\":\"cf6b318701bc62c615cd6d6ef68424a45ebe7097972aa4ec11d820c9f4a82bc1\",\"sha256\":\"cf6b318701bc62c615cd6d6ef68424a45ebe7097972aa4ec11d820c9f4a82bc1\",\"role\":\"justification\",\"text\":\"\",\"pages\":32,\"page_start\":1,\"page_end\":32,\"text_start\":0,\"text_end\":76298,\"text_sha256\":\"d5cd3fef51aef1aba400cec5748b942aa9405694ecc9f55a77dc9bd19f405cf6\",\"losses\":[]},{\"url\":\"https:/