://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-09-18\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":411,\"no\":23,\"abstain\":0,\"not_participating\":26,\"sitting\":65,\"voting_number\":86,\"date\":\"2026-09-18T09:15:44Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/65/86/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Stanowisko Senatu\",\"stage_type\":\"SenatePosition\",\"date\":\"2026-09-24\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":\"nie wniósł poprawek\",\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Ustawę przekazano Prezydentowi do podpisu\",\"stage_type\":\"ToPresident\",\"date\":\"2026-09-24\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Prezydent podpisał ustawę\",\"stage_type\":\"PresidentSignature\",\"date\":\"2026-10-09\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-09-18\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"kind\":\"text_after3\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a\",\"analysis_revision\":3,\"seen_supplements\":[\"2846-001\",\"2846-002\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Специальный закон для проведения Всемирного скаутского Джамбори в Гданьске в 2027 г. Участники освобождаются от консульского сбора за польскую и шенгенскую визу, а их заявления обещают рассматривать без лишних задержек. Для волонтёров вводятся детальные проверки несудимости.\",\"key_changes\":[\"Участники Джамбори не платят консульский сбор за визу на въезд в Польшу\",\"К заявлению на визу нужно приложить подтверждение регистрации участия\",\"При подаче списка за 6 недель визы рассматривают без лишней задержки\",\"Волонтёры‑иностранцы должны предоставить справки о несудимости за 10 лет\",\"Организатор проверяет волонтёров в КРК и реестрах по преступлениям против детей\"],\"affected_groups\":[\"иностранные участники и гости Джамбори 2027\",\"иностранные волонтёры на Джамбори\",\"члены иностранных официальных делегаций, едущие на Джамбори\"],\"practical_impact\":\"Иностранные участники экономят на визовом сборе и могут рассчитывать на более быстрое рассмотрение заявлений при своевременной подаче. Волонтёрам понадобятся официальные справки о несудимости из стран гражданства и проживания за последние 10 лет.\",\"effective_date\":\"Закон вступает в силу через 14 дней со дня опубликования.\",\"confidence\":0.96,\"rationale\":\"Закон прямо вводит льготы по визам для участников Джамбори и специальные требования проверки волонтёров‑иностранцев, что относится к сфере виз и легализации пребывания.\",\"mnemonic_candidate\":\"Бесплатные визы Джамбори\",\"mnemonic_fallback\":\"Закон о визах Джамбори\",\"mnemonic_basis\":\"Статья 20 освобождает участников Джамбори от консульского сбора за национальную и шенгенскую визы при наличии подтверждения участия.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[\"Уточнены категории волонтёров: отдельно описаны граждане ЕС и не‑ЕС и набор проверок для них.\",\"Для волонтёров‑граждан ЕС добавлена обязанность приносить справки о несудимости из стран проживания вне ЕС за последние 10 лет.\",\"Закреплено, что организатор запрашивает через КРК данные о судимости волонтёров‑граждан ЕС в их стране гражданства.\",\"Расширён период, к которому привязаны специальные меры закона: теперь с 14 июля по 16 августа 2027 года.\"]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"input_chars\":27534,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-19T06:47:45Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":3,\"text_sha256\":\"text-v2:f4a3bf591d2ceebcf73b360901f38bb0fc2bf7f016acb504a4c15caecd85808a\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"members\":[],\"container_sha256\":\"f88cad4bec78dab024c2dfc612fd95dc58bc9a160d82e2ae7cbd1b123fced776\",\"sha256\":\"f88cad4bec78dab024c2dfc612fd95dc58bc9a160d82e2ae7cbd1b123fced776\",\"role\":\"bill\",\"text\":\"\",\"pages\":13,\"page_start\":1,\"page_end\":13,\"text_start\":0,\"text_end\":27534,\"text_sha256\":\"cd1d300fca04381f23bbdd95dfcde2691b3205c2b8426049d3b3a916aaddf1a5\",\"losses\":[]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"text_sha256\":\"cd1d300fca04381f23bbdd95dfcde2691b3205c2b8426049d3b3a916aaddf1a5\",\"block_id\":\"part:0\",\"start\":0,\"end\":238,\"quote\":\"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\\n\\nUSTAWA\\nz dnia 18 września 2026 r.\\no szczególnych rozwiązaniach związanych z organizacją XXVI Światowego\\nJamboree Skautowego w Rzeczypospolitej Polskiej w 2027 r.\\nArt. 1\"},{\"kind\":\"coverage\",\"value\":\"body_through_commencement\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/2846/attachment/2846_u3.pdf\",\"text_sha256\":\"cd1d300fca04381f23bbdd95dfcde2691b3205c2b8426049d3b3a916aaddf1a5\",\"block_id\":\"part:0\",\"start\":27426,\"end\":27448,\"quote\":\"Ustawa wchodzi w życie\"}],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":27534,\"page_start\":1,\"page_end\":13,\"losses\":[]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":27534,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"483dadd76045041e7386267f20834fb7625c1ff5c723da87a149bd3ef02365f1\"},\"law_sha256\":\"law-v2:7a613a479dd0ec93f8e71e3e2a43ab84c179dba165ae9c962ecec27aea6fcecc\",\"source_checked_at\":\"2026-10-19T06:47:45Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Бесплатные визы Джамбори\",\"language\":\"ru\",\"basis\":\"Статья 20 освобождает участников Джамбори от консульского сбора за национальную и шенгенскую визы при наличии подтверждения участия.\",\"selected_at\":\"2026-10-19T06:47:45Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/25576/2026\",\"title\":\"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.\",\"description\":\"uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-07-23\",\"print_number\":\"2846\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":{\"eli\":\"DU/2026/1343\",\"display_address\":\"Dz.U. 2026 poz. 1343\",\"title\":\"Ustawa z dnia 18 września 2026 r. o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Rzeczypospolitej Polskiej w 2027 r.\",\"act_date\":\"2026-09-18\",\"promulgation_date\":\"2026-10-16\",\"entry_into_force\":\"2026-10-31\",\"in_force\":\"IN_FORCE\",\"status\":\"obowiązujący\",\"text_pdf_url\":\"https://api.sejm.gov.pl/eli/acts/DU/2026/1343/text.pdf\",\"isap_url\":\"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001343\",\"fetched_at\":\"2026-10-19T19:28:19.413562Z\"},\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"2846-001\",\"2846-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-19T19:28:19Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["act_evidence"],"explanation":"Publication or entry into force is confirmed.","affected_groups":[],"action":"prepare","deadline":"2026-10-31","deadline_source":"DU/2026/1343","deadline_precision":"day","detected_at":"2026-10-19T19:28:19Z","assessed_at":"2026-10-19T19:28:19Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Бесплатные визы Джамбори · druk nr 2846</b>\n📖 <b>Опубликован в Dziennik Ustaw</b>\n\nO szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Rzeczypospolitej Polskiej w 2027 r.\n\n📰 <b>Публикация:</b> Dz.U. 2026 poz. 1343 (опубликован 16 окт 2026)\n📅 <b>Вступает в силу:</b> 31 окт 2026\nℹ️ <i>Это общая дата из ELI. Применение отдельных норм и переходные условия ещё не разобраны.</i>\n\nРазбор неполный; неустановленные условия требуют проверки в официальных документах.\n\n👉 <b>Что можно сделать сейчас:</b> пока ничего — закон принят, остаётся подготовиться к вступлению в силу\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=2846\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=2846\">Ход процесса в Сейме</a> | <a href=\"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001343\">ISAP</a> | <a href=\"https://api.sejm.gov.pl/eli/acts/DU/2026/1343/text.pdf\">Текст закона (PDF)</a>\n\n#закон #важность5 #легализация #kadencja10druk2846","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],