INSERT INTO "publications" VALUES(157,10,'3231','status_update','sent','@lex_inform_pl',115,'[]',128,'2026-10-20T18:03:44+00:00','2026-10-20T18:03:45+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3231\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-08\",\"document_date\":\"2026-10-08\",\"change_date\":\"2026-10-20T09:04:06Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-170-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-170-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-08\",\"print_number\":\"3231\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"DER\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja do Spraw Deregulacji\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ENM\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Edukacji i Nauki\",\"children\":[]}]}],\"stages_fingerprint\":\"ce84531a49b298be4c7ea39e83097baaf00de88b348952a502180b6584011449\",\"observed_closure_date\":null,\"consultation_review\":null,\"act_application_review\":null,\"review_work\":[],\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.\",\"key_changes\":[\"Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией\",\"Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии\",\"Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS\",\"Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу\",\"Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты\"],\"affected_groups\":[\"иностранные докторанты польских школ докторантских\",\"иностранцы, завершившие обучение в школе докторантской и готовящие защиту\",\"вузы и научные учреждения, ведущие школы докторантские с иностранцами\"],\"practical_impact\":\"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.\",\"effective_date\":\"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":68211,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T07:38:31Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:cbeb72dab45a6fe6d2941439b13e6dac6816abe9f3dc30fa6b9ba1da034e00f0\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[\"sejm/10/print/3231\"],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"members\":[],\"container_sha256\":\"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7\",\"sha256\":\"519b94f07a9b243cc4fbb