ing_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-08\",\"print_number\":\"3196\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"analysis_revision\":3,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.\",\"key_changes\":[\"В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС\",\"Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы\",\"Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу\",\"В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex\",\"В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше\"],\"affected_groups\":[\"иностранцы с решениями о возврате/выдворении\",\"мигранты с неурегулированным статусом, подлежащие депортации\",\"лица, находящиеся в процедурах принудительного возвращения\"],\"practical_impact\":\"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.\",\"effective_date\":\"закон вступает в силу через 14 дней со дня его официального опубликования.\",\"confidence\":0.94,\"rationale\":\"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":25424,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T14:59:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"source_kind\":\"committee_report\",\"revision\":3,\"text_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":\"law-v2:d8f3ef852ea1e280e0266d4fd204414510c5915f5b455b687f4