ll,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"10. Komisja Prawnicza\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"12. Rada Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198704/13198705/dokument802150.zip\",\"kind\":\"rcl\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:57833ee7f7e58bce903afef37933eddd113258f57ca4536092fdb1b27ff1d7b6\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила пособия на ребёнка 800+. ZUS будет сам продлевать право на выплату тем, кто уже его получает, а круг получателей расширят на некоторых опекунов по решению суда.\",\"key_changes\":[\"ZUS автоматически продлевает право на 800+ тем, у кого оно есть на 31 мая.\",\"Добавлены получатели: лица с «bieżąca piecza» по решению польского суда.\",\"Уточнены категории временного опекуна и опекуна, назначенного властями страны происхождения.\",\"Банки и системы e‑ZUS могут хранить заявки и вложения до 10 лет для рекламаций.\",\"Уточнено финансирование вещевой формы 800+ для опекуна ребёнка, указанного страной происхождения.\"],\"affected_groups\":[\"иностранцы с детьми, уже получающие пособие 800+\",\"иностранцы, впервые оформляющие 800+ на ребёнка в Польше\",\"иностранные опекуны детей по решению польского суда (bieżąca piecza)\",\"опекуны детей, указанных властями страны происхождения ребёнка\"],\"practical_impact\":\"Иностранным семьям, которые уже получают 800+ на 31 мая, обычно не придётся подавать ежегодные заявки: ZUS сам продлит выплату. При первом оформлении и при изменении ситуации (особенно выезд семьи за границу) по‑прежнему нужно подавать заявление и уведомлять ZUS; новые категории опекунов смогут получать 800+ напрямую.\",\"effective_date\":\"Закон вступает в силу через 14 дней после опубликования, за исключением ст. 1 п. 4 лит. a, п. 5, п. 9 лит. a и п. 10–13 и ст. 3, которые вступают в силу 1 февраля 2027 г.\",\"confidence\":0.93,\"rationale\":\"Проект меняет порядок назначения и продления пособия 800+, которым могут пользоваться иностранцы с детьми в Польше, поэтому это важное изменение в социальной сфере.\",\"mnemonic_candidate\":\"Автообновление 800+\",\"mnemonic_fallback\":\"Автопродление пособия 800+\",\"mnemonic_basis\":\"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze (800+) без повторной заявки для лиц, уже получающих выплату.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v11\",\"input_chars\":41339,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-14T16:08:45Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12409404/13198704/13198705/dokument802150.zip\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"text-v2:57833ee7f7e58bce903afef37933eddd113258f57ca4536092fdb1b27ff1d7b6\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":\"law-v2:d83673b42b2f9050ba6a6fd9c844cfb417f84b6296f185c3820ff266c9006c2b\",\"source_checked_at\":\"2026-10-14T16:08:45Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Автообновление 800+\",\"language\":\"ru\",\"basis\":\"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze (800+) без повторной заявки для лиц, уже получающих выплату.\",\"selected_at\":\"2026-10-14T16:08:45Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,