ll,\"decision\":null,\"committee_code\":\"FPB\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Finansów Publicznych\",\"children\":[]}]},{\"stage_name\":\"Praca w komisjach po I czytaniu\",\"stage_type\":\"CommitteeWork\",\"date\":\"2026-10-19\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie podkomisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-19\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/processes/3003/attachment/spr_3003.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":true,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-21\",\"print_number\":\"3251\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3251/3251.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":5,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\",\"kind\":\"print\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":null,\"analysis_revision\":1,\"seen_supplements\":[\"3003-001\",\"3003-002\",\"3003-003\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"legal_stay\",\"summary\":\"Проект вводит единый закон о санкциях (środki ograniczające) — общий порядок применения санкций ЕС и национальных санкций. Для иностранцев важно, что одним из национальных санкционных мер становится внесение в реестр нежелательных лиц, а закон о иностранцах дополняется новым основанием для запрета въезда и отказа в визе/виде на жительство. Затрагивает лишь лиц, попавших в санкционный список МВД.\",\"key_changes\":[\"Новая мера: внесение иностранца в wykaz cudzoziemców, których pobyt jest niepożądany\",\"Поправки в ustawa o cudzoziemcach: санкционный список — основание для отказа в визе и ВНЖ\",\"Szef Urzędu do Spraw Cudzoziemców — орган, решающий об исключениях из запрета на въезд\",\"Уголовная ответственность (3 мес.–5 лет) за содействие въезду или транзиту лица под санкциями\",\"Список санкционных лиц публикуется в BIP МВД; обжалование — только в административный суд\",\"Выплаты работникам санкционированного работодателя из FGŚP до 3 месяцев\"],\"affected_groups\":[\"Иностранцы, внесённые в национальный санкционный список\",\"Граждане ЕС и члены их семей, подпадающие под санкции\",\"Работники (в т.ч. иностранцы) компаний под санкциями\",\"Предприниматели и компании, ведущие торговлю с санкционными странами\"],\"practical_impact\":\"Для подавляющего большинства иностранцев ничего не меняется. Тому, кто попал в санкционный список, грозит запрет въезда, отказ в визе и виде на жительство, заморозка средств; работникам санкционированных фирм гарантируется выплата зарплаты из FGŚP до 3 месяцев.\",\"effective_date\":\"Через 30 дней после опубликования, кроме ст. 73, которая вступает в силу через 6 месяцев после опубликования.\",\"confidence\":0.85,\"rationale\":\"Проект напрямую изменяет ustawa o cudzoziemcach и вводит запрет въезда/пребывания как санкционную меру, но касается узкой группы лиц, поэтому 4, а не 5.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v3\",\"input_chars\":375697,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-09T17:59:19Z\",\"input_tokens\":185019,\"output_tokens\":1333,\"cache_read_input_tokens\":2118,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":null,\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":null,\"source_checked_at\":null},\"editorial\":{\"mnemonic\":{\"name\":\"Санкционный въездной барьер\",\"language\":\"ru\",\"basis\":\"Иностранец, внесённый в санкционный список МВД, автоматически попадает в wykaz cudzoziemców, których pobyt jest niepożądany, что влечёт запрет въезда и негативные визово‑миграционные решения.\",\"selected_at\":\"2026-10-21T18:29:53Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/27024/2026\",\"title\":\"Rządowy projekt ustawy o środkach ograniczających\",\"description\":\"określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.\",\"appli