ocx\",\"created\":\"2026-10-09\",\"author\":\"Prezes Rządowego Centrum Legislacji\"}],\"catalog_read\":true},{\"id\":13146414,\"number\":11,\"name\":\"Potwierdzenie projektu przez Stały Komitet Rady Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13146429,\"number\":12,\"name\":\"Rada Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13146447,\"number\":13,\"name\":\"Notyfikacja\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13146450,\"number\":14,\"name\":\"Skierowanie projektu ustawy do Sejmu\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false}],\"consultation\":{\"letter_url\":\"https://legislacja.rcl.gov.pl/docs//2/12400563/13146303/13146309/dokument730187.docx\",\"letter_date\":null,\"days\":21,\"deadline\":\"2025-08-21\",\"email\":\"dep.prawny@mswia.gov.pl\",\"positions\":2,\"response_published\":false,\"letters_read\":[\"https://legislacja.rcl.gov.pl/docs//2/12400563/13146303/13146309/dokument730187.docx\"]},\"consultation_attempts\":0},\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-09T14:42:18Z\",\"last_checked_at\":\"2026-10-21T18:52:21Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":["Граждане безвизовых стран, въезжающие в Польшу/Шенген","Иностранцы, находящиеся в Польше по безвизу и подающие на ВНЖ, ПМЖ, резидента ЕС","Иностранцы с польскими визами и картами pobytu","Иностранцы, работающие в Польше по разрешениям на работу, сезонной работе и по заявлениям о powierzeniu pracy","Лица с запретом въезда в Польшу/Шенген, данные которых вносятся в реестры"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-21T18:52:21Z","assessed_at":"2026-10-21T18:52:21Z","novelty":"new_consequence","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Пропуск ETIAS · UC104</b>\n🆕 <b>Новая версия текста</b>\n\nКого касается: Граждане безвизовых стран, въезжающие в Польшу/Шенген; Иностранцы, находящиеся в Польше по безвизу и подающие на ВНЖ, ПМЖ, резидента ЕС; Иностранцы с польскими визами и картами pobytu; Иностранцы, работающие в Польше по разрешениям на работу, сезонной работе и по заявлениям о powierzeniu pracy; Лица с запретом въезда в Польшу/Шенген, данные которых вносятся в реестры\n<b>Изменения между версиями проекта</b>\n• Размер пошлины за повторное рассмотрение дела по ETIAS больше не фиксирован в 200 zł: в проекте предусмотрено, что её точное значение установят в регламенте МВД в диапазоне от 100 zł до 6,54% средней зарплаты.\n\n📝 <b>Суть проекта</b>\nПроект вводит в Польше систему ETIAS: гражданам безвизовых стран понадобится электронное разрешение на поездку, иначе могут отказать во въезде и в легализации пребывания. Создаётся единый Krajowy Rejestr Cudzoziemców с главным идентификатором для всех ведомств.\n\n⏭ <b>Что дальше:</b> завершение юридической проверки и подтверждение текста в Stały Komitet Rady Ministrów, затем рассмотрение Советом министров\n👉 <b>Что можно сделать сейчас:</b> новое окно участия не подтверждено; следим за итогами юридической проверки\n\n🔗 <a href=\"https://legislacja.rcl.gov.pl/projekt/12400563\">Проект на RCL</a> | <a href=\"https://legislacja.rcl.gov.pl/docs//2/12400563/13146411/dokument801710.docx\">Текст проекта (DOCX)</a>\n\n#важность5 #легализация #UC104","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"{\"id\":144,\"term\":10,\"number\":\"RCL/12400563\",\"old_fingerprint\":\"2774d093c90ce43756ceb3a86e5a5487bd3bf4e0efb8a7086cd7edd8616e8a84\",\"new_fingerprint\":\"d3f1c26a89cb00bee2f832ee6597b42331fad7585c6c7145e336e6859f0590e6\",\"new_stages\":[],\"closure_detected\":false,\"decision_changed\":false,\"passed\":null,\"content_changed\":true,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":null,\"supplements\":[],\"detected_at\":\"2026-10-21T18:52:21Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-21","still_meets":false,"reply_to":12,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":["Граждане безвизовых стран, въезжающие в Польшу/Шенген","Иностранцы, находящиеся в Польше по безвизу и подающие на ВНЖ, ПМЖ, резидента ЕС","Иностранцы с польскими визами и картами pobytu","Иностранцы, работающие в Польше по разрешениям на работу, сезонной работе и по заявлениям о powierzeniu pracy","Лица с запретом въезда в Польшу/Шенген, данные которых вносятся в реестры"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-21T18:52:21Z","assessed_at":"2026-10-21T18:52:21Z","novelty":"new_consequence","rule_version":"attention-v1"}');
