ersions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:5dd8519f8dbf37d9ed90080a6224c539a78b2c705c073ae7ee01f6488f9a839b\",\"analysis_revision\":2,\"seen_supplements\":[\"3157-001\",\"3157-002\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект усиливает контроль NFZ над медучреждениями и условия найма/оплаты медиков. В закон о правах пациента вводится прямое право на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.\",\"key_changes\":[\"В закон о правах пациента вводится право на равное обращение\",\"Прямой запрет дискриминации по гражданству, национальности и др.\",\"Обязанность медорганизаций активно предотвращать дискриминацию\",\"Расширяется доступ NFZ к меддокументации и контролю учреждений\",\"Жёстко регулируются время работы и максимум оплат для медиков NFZ\"],\"affected_groups\":[\"иностранцы, пользующиеся услугами NFZ\",\"иностранные работники и студенты с правом на медобслуживание в Польше\",\"пациенты‑иностранцы в государственных и контрактных клиниках\"],\"practical_impact\":\"Иностранец, имеющий право на лечение в Польше, получает чёткую юридическую базу требовать одинакового доступа к услугам и условиям приёма вне зависимости от гражданства. Жалобы на отказ или худшие условия из‑за паспорта можно опирать на прямую норму закона о правах пациента.\",\"effective_date\":\"Устawa wchodzi w życie po upływie miesiąca od dnia ogłoszenia (через месяц со дня официального опубликования).\",\"confidence\":0.94,\"rationale\":\"Проект прямо вводит в закон о правах пациента запрет дискриминации, включая по гражданству, что существенно влияет на социальные права иностранцев в системе здравоохранения (категория „social”, важность 3).\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":81176,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-12T22:14:38Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"source_kind\":\"committee_report\",\"revision\":2,\"text_sha256\":\"text-v2:5dd8519f8dbf37d9ed90080a6224c539a78b2c705c073ae7ee01f6488f9a839b\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"members\":[],\"container_sha256\":\"12e4ff3820a9110255d2aadf03e3a86dfa264fb58b56dcb0c9d081d5387d81a6\",\"sha256\":\"12e4ff3820a9110255d2aadf03e3a86dfa264fb58b56dcb0c9d081d5387d81a6\",\"role\":\"unknown\",\"text\":\"\",\"pages\":38,\"page_start\":1,\"page_end\":38,\"text_start\":0,\"text_end\":81176,\"text_sha256\":\"465e2f79824fe17ab7ddbf1adfcc84a414086766951c1f7d9fb9b4c04d8a920a\",\"losses\":[]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":81176,\"page_start\":1,\"page_end\":38,\"losses\":[]}],\"normative_sha256\":\"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945\"},\"law_sha256\":\"law-v2:1ea862ae2d11a96f555c0ce8737e38455e925538f24d9d6e71ee8a04d682afda\",\"source_checked_at\":\"2026-10-21T18:11:10Z\"},\"editorial\":{\"mnemonic\":null,\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":4,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32531/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-28\",\"print_number\":\"3157\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null},\"linked_number\":\"RCL/12412802\",\"linked_wykaz_number\":\"UD439\",\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Zdrowia o rządowym projekcie ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw (druki nr 3157 i ) - sprawozdawca poseł Marta Golbik.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[\"3157-001\",\"3157-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T07:15:59Z\",\"last_checked_at\":\"2026-10-21T18:54:01Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-21T18:53:59Z","assessed_at":"2026-10-21T18:54:01Z","novelty":"new_consequence","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"📋 <b>Отчёт комиссии — druk nr 3157</b>\nПроект усиливает контроль NFZ над медучреждениями и условия найма/оплаты медиков.\n\n🧭 <b>Новые стадии</b>\n• 21 окт 2026: отчёт комиссии (sprawozdanie) (druk nr 3193-A): предлагает принять часть поправок\n\n🆕 <b>Что меняют поправки (по отчёту комиссии)</b>\nКомиссия предлагает принять лишь часть поправок: они уточняют новые ограничения по занятости и оплате труда медработников, а также действие переходных норм. Более радикальные изменения (повышение гарантированного финансирования, иная формула расчёта лимитов вознаграждений, расширение их на услуги вне договоров с NFZ) комиссия рекомендует отклонить.\n• Время дежурства вне медучреждения и на дому не войдёт в общий лимит занятости медиков.\n• Стационар и приём в больничной поликлинике должны вести медики с нагрузкой не менее 0,5 ставки.\n• Из этого требования выведены дежурства, работа вне обычных часов и услуги гериатров, патоморфологов, психиатров.\n• Процедура второй работы: при кадровом дефиците работодатель сперва предлагает поднять ставку, затем решает о согласии/увольнении.\n• Льготные лимиты оплаты в трансплантологии уточнены: касаются операций по изъятию и пересадке органов.\n• Нормы распространены и на служебные/иные отношения; часть переходных правил ст. 4 изменена или исключена, конфликтующие коллективные нормы действуют лишь в несопротиворечащей части.\n\n⏭ <b>Что дальше:</b> III чтение и голосование в Сейме · часто на одном заседании со II чтением\n👉 <b>Что можно сделать сейчас:</b> пока ничего — после голосования в Сейме мнение можно направить в комиссию Сената\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3157\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3157\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf\">PDF 3193-A</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf\">Текст поправок (PDF)</a>\n\n#комиссия #поправки #важность3 #соцсфера #kadencja10druk3157 #UD439","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"{\"id\":146,\"term\":10,\"number\":\"3157\",\"old_fingerprint\":\"c6456e71574f1baa6c44feb3ce6d94909fb5c99a3fd97f92d33b1c448c7d2e9f\",\"new_fingerprint\":\"626842c5aff30a6dcaf32a39a75af4ab2c5ecd6f3b34a048afcd1fd7038f5142\",\"new_stages\":[{\"stage_name\":\"Praca w komisjach po II czytaniu\",\"stage_type\":\"CommitteeWork\",\"date\":\"2026-10-21\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-21\",\"print_number\":\"3193-A\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć część poprawek\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-21\",\"print_number\":\"3193-A\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć część poprawek\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_detected\":false,\"decision_changed\":false,\"passed\":false,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":{\"amendments\":{\"summary\":\"Комиссия предлагает принять лишь часть поправок: они уточняют новые ограничения по занятости и оплате труда медработников, а также действие переходных норм. Более радикальные изменения (повышение гарантированного финансирования, иная формула расчёта лимитов вознаграждений, расширение их на услуги вне договоров с NFZ) комиссия рекомендует отклонить.\",\"changes\":[\"Время дежурства вне медучреждения и на дому не войдёт в общий лимит занятости медиков.\",\"Стационар и приём в больничной поликлинике должны вести медики с нагрузкой не менее 0,5 ставки.\",\"Из этого требования выведены дежурства, работа вне обычных часов и услуги гериатров, патоморфологов, психиатров.\",\"Процедура второй работы: при кадровом дефиците работодатель сперва предлагает поднять ставку, затем решает о согласии/увольнении.\",\"Льготные лимиты оплаты в трансплантологии уточнены: касаются операций по изъятию и пересадке органов.\",\"Нормы распространены и на служебные/иные отношения; часть переходных правил ст. 4 изменена или исключена, конфликтующие коллективные нормы действуют лишь в несопротиворечащей части.\"],\"affects_foreigners\":false,\"confidence\":0.73,\"source_evidence\":null},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf\",\"source_kind\":\"committee_amendments\",\"created_at\":\"2026-10-21T18:29:54Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-21T18:53:59Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-21","still_meets":false,"reply_to":75,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-21T18:53:59Z","assessed_at":"2026-10-21T18:54:01Z","novelty":"new_consequence","rule_version":"attention-v1"}');
