ort\",\"date\":\"2026-10-08\",\"print_number\":\"3196\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"załączony projekt ustawy\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"II czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":67,\"decision\":\"skierowano ponownie do komisji w celu przedstawienia sprawozdania\",\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ASW\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Administracji i Spraw Wewnętrznych\",\"children\":[]}]},{\"stage_name\":\"Praca w komisjach po II czytaniu\",\"stage_type\":\"CommitteeWork\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-22\",\"print_number\":\"3196-A\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć część poprawek\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"analysis_revision\":3,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.\",\"key_changes\":[\"В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС\",\"Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы\",\"Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу\",\"В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex\",\"В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше\"],\"affected_groups\":[\"иностранцы с решениями о возврате/выдворении\",\"мигранты с неурегулированным статусом, подлежащие депортации\",\"лица, находящиеся в процедурах принудительного возвращения\"],\"practical_impact\":\"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.\",\"effective_date\":\"закон вступает в силу через 14 дней со дня его официального опубликования.\",\"confidence\":0.94,\"rationale\":\"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":25424,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T14:59:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"source_kind\":\"committee_report\",\"revision\":3,\"text_sha256\":\"text-v2:39685f0bf7c1205c727174065e959018e2f6648b8263660d07aa0bd242bcde61\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"members\":[],\"container_sha256\":\"c964ab29f180c16c1bc97dfdb8990627d11dbfca60456c5a2fcbc3af16625bda\",\"sha256\":\"c964ab29f180c16c1bc97dfdb8990627d11dbfca60456c5a2fcbc3af16625bda\",\"role\":\"bill\",\"text\":\"\",\"pages\":13,\"page_start\":1,\"page_end\":13,\"text_start\":0,\"text_end\":25424,\"text_sha256\":\"5d3d22ac9bc06a57037d19bfe1679cd57b1aa492213684737ffb342f8a463c2a\",\"losses\":[\"text page coverage differs from the PDF page count\"]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196/3196.pdf\",\"text_sha256\":\"5d3d22ac9bc06a57037d19bfe1679cd57b1aa492213684737ffb342f8a463c2a\",\"block_id\":\"part:0\",\"start\":0,\"end\":201,\"quote\":\"Liczba stron :  12     Data :   2026-10-09      Nazwa pliku :   V7_4-9.NK   1\\nX kadencja/druk nr 3146\\nProjekt\\nU S T AWA\\nz dnia\\no zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw1)\\nArt. 1\"}],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":25424,\"page_start\":1,\"page_end\":13,\"losses\":[\"text page coverage differs from the PDF page count\"]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":25424,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"6b5bbe10f25ea633a96fc33239f2e29e933dde49f71d37cd2ed54453af4be5e9\"},\"law_sha256\":\"law-v2:d8f3ef852ea1e280e0266d4fd204414510c5915f5b455b687f48e404e70b1825\",\"source_checked_at\":\"2026-10-22T18:05:41Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Депортации Frontex\",\"language\":\"ru\",\"basis\":\"Проект вводит в закон об иностранцах операции и интервенции по принудительному возвращению с участием Frontex и регулирует их проведение в Польше.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":7,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32084/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3146\",\"eu_related\":true,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null,\"senders_number\":null},\"linked_number\":\"RCL/12405005\",\"linked_wykaz_number\":\"UC126\",\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Administracji i Spraw Wewnętrznych o rządowym projekcie ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw (druki nr 3146 i ) - sprawozdawca poseł Artur Jarosław Łącki.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-28T15:32:12Z\",\"last_checked_at\":\"2026-10-22T18:17:41Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-22T18:17:39Z","assessed_at":"2026-10-22T18:17:41Z","novelty":"new_consequence","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Депортации Frontex · druk nr 3146</b>\n📋 <b>Отчёт комиссии</b>\n\n🧭 <b>Новые стадии</b>\n• 22 окт 2026: отчёт комиссии (sprawozdanie) (druk nr 3196-A): предлагает принять часть поправок\n\n🆕 <b>Что меняют поправки (по отчёту комиссии)</b>\nПоправки дорабатывают регулирование спецтранспорта Agencji Frontex и исключают один блок изменений (art.9); комиссия рекомендует принять только поправки KO (9–10 и 12), а все поправки KP PiS (1–8 и 11) об удалении частей проекта – отклонить.\nВ результате ключевые положения о сотрудничестве со Strażą Graniczną и об участии Frontex остаются в правительственной редакции, лишь технически уточняется режим для транспортных средств агентства.\n• В art.66 добавляется прямое упоминание Agencji Frontex в перечне субъектов, для чьего спецтранспорта задаются техтребования\n• Вводится новый ust.7a art.66: министр внутренних дел с минтрансом будет в регламенте определять техусловия спецтранспорта Agencji Frontex\n• Расширяется отсылка в art.66 ust.8 так, чтобы она охватывала также новый ust.7a о транспорте Agencji Frontex\n• Изменения в art.4 перегруппированы: правка art.66 выделена в отдельный pkt 3a вместо прежнего включения в pkt 3\n• Полностью исключается art.9 проекта (один из блоков изменений в другом законе)\n• Поправки KP PiS об удалении отдельных подпунктов и целых статей (1–8,11) отклонены, правительственный текст там не меняется\n\n⏭ <b>Что дальше:</b> III чтение и голосование в Сейме · часто на одном заседании со II чтением\n👉 <b>Что можно сделать сейчас:</b> пока ничего — после голосования в Сейме мнение можно направить в комиссию Сената\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3146\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3146\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf\">Текст поправок (PDF)</a>\n\n#комиссия #поправки #важность5 #легализация #kadencja10druk3146 #UC126","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"{\"id\":153,\"term\":10,\"number\":\"3146\",\"old_fingerprint\":\"3a03726dc6b5d56c938376e625fae40a7107ff0699abc27c0b5c3e7b9d6ffb77\",\"new_fingerprint\":\"415d07e1427dedbf2837ba4f1e8fff4cd8d03db3f21063af620975b331f503ec\",\"new_stages\":[{\"stage_name\":\"Praca w komisjach po II czytaniu\",\"stage_type\":\"CommitteeWork\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-22\",\"print_number\":\"3196-A\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć część poprawek\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Sprawozdanie komisji\",\"stage_type\":\"CommitteeReport\",\"date\":\"2026-10-22\",\"print_number\":\"3196-A\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf\",\"text_after3\":null,\"position\":null,\"proposal\":\"przyjąć część poprawek\",\"sub_committee\":false,\"minority_motions\":0,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_detected\":false,\"decision_changed\":false,\"passed\":false,\"content_changed\":false,\"withdrawn\":false,\"discontinued\":false,\"consultation_opened\":false,\"amendments\":{\"amendments\":{\"summary\":\"Поправки дорабатывают регулирование спецтранспорта Agencji Frontex и исключают один блок изменений (art.9); комиссия рекомендует принять только поправки KO (9–10 и 12), а все поправки KP PiS (1–8 и 11) об удалении частей проекта – отклонить.\\nВ результате ключевые положения о сотрудничестве со Strażą Graniczną и об участии Frontex остаются в правительственной редакции, лишь технически уточняется режим для транспортных средств агентства.\",\"changes\":[\"В art.66 добавляется прямое упоминание Agencji Frontex в перечне субъектов, для чьего спецтранспорта задаются техтребования\",\"Вводится новый ust.7a art.66: министр внутренних дел с минтрансом будет в регламенте определять техусловия спецтранспорта Agencji Frontex\",\"Расширяется отсылка в art.66 ust.8 так, чтобы она охватывала также новый ust.7a о транспорте Agencji Frontex\",\"Изменения в art.4 перегруппированы: правка art.66 выделена в отдельный pkt 3a вместо прежнего включения в pkt 3\",\"Полностью исключается art.9 проекта (один из блоков изменений в другом законе)\",\"Поправки KP PiS об удалении отдельных подпунктов и целых статей (1–8,11) отклонены, правительственный текст там не меняется\"],\"affects_foreigners\":false,\"confidence\":0.62,\"source_evidence\":null},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf\",\"source_kind\":\"committee_amendments\",\"created_at\":\"2026-10-22T18:13:48Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-22T18:17:39Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-22","still_meets":false,"reply_to":88,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"abso