рекомендует Сейму все эти поправки отклонить.\",\"changes\":[\"Добавляется цель поддержки: помощь предпринимателям в доступе к энергии, особенно из возобновляемых источников.\",\"Из одной нормы убираются ссылки на spółka komandytowa и spółka komandytowo‑akcyjna.\",\"Предлагается вычеркнуть два пункта изменений в основной статье, изменяющей базовый закон.\",\"Предлагается полностью удалить из проекта статьи 16 и 23.\",\"Снижение занятости: не более 20% от среднего за 12 мес. до заявки, с исключением на случаи ошибки.\",\"Переходные нормы: для незавершённых и части старых дел о поддержке инвестиций уточняется, какие старые правила применять.\"],\"affects_foreigners\":false,\"confidence\":0.63,\"source_evidence\":null},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3243-A/3243-A.pdf\",\"source_kind\":\"committee_amendments\",\"created_at\":\"2026-10-22T18:13:48Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0},\"supplements\":[],\"detected_at\":\"2026-10-22T18:17:41Z\"}","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-22","still_meets":false,"reply_to":76,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["substantive_content"],"explanation":"Substantive text or supporting documents changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-22T18:17:41Z","assessed_at":"2026-10-22T18:17:45Z","novelty":"new_consequence","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(185,10,'3231','agenda','sent','@lex_inform_pl',129,'[]',NULL,'2026-10-23T06:07:49+00:00','2026-10-23T17:59:46+00:00',NULL,0,'sejm/68/2026-11-05',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3231\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-08\",\"document_date\":\"2026-10-08\",\"change_date\":\"2026-10-20T09:04:06Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-170-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-170-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-08\",\"print_number\":\"3231\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":n