stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"DER\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja do Spraw Deregulacji\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ENM\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Edukacji i Nauki\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"kind\":\"print\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:cbeb72dab45a6fe6d2941439b13e6dac6816abe9f3dc30fa6b9ba1da034e00f0\",\"analysis_revision\":1,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.\",\"key_changes\":[\"Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией\",\"Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии\",\"Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS\",\"Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу\",\"Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты\"],\"affected_groups\":[\"иностранные докторанты польских школ докторантских\",\"иностранцы, завершившие обучение в школе докторантской и готовящие защиту\",\"вузы и научные учреждения, ведущие школы докторантские с иностранцами\"],\"practical_impact\":\"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.\",\"effective_date\":\"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":68211,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T07:38:31Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:cbeb72dab45a6fe6d2941439b13e6dac6816abe9f3dc30fa6b9ba1da034e00f0\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[\"sejm/10/print/3231\"],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"members\":[],\"container_sha256\":\"519b94f07a9b243cc4fbb