INSERT INTO "publications" VALUES(186,10,'3205','consultation_results','sent','@lex_inform_pl',139,'[]',NULL,'2026-10-23T17:57:13+00:00','2026-10-25T11:54:28+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3205\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych\",\"description\":\"projekt dotyczy wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-18\",\"document_date\":\"2026-09-18\",\"change_date\":\"2026-10-23T08:02:23Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:migracja\",\"text:obywatelstwo\",\"text:obywatele_ukrainy\",\"text:uznawanie_kwalifikacji\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-18\",\"print_number\":\"3205\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"949e8d4b8f2d586799c203d57b8cd4685b610e742e63c82307218ff4b1415182\",\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":[],\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-18\",\"print_number\":\"3205\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3205/3205.pdf\",\"kind\":\"print\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:4abee9811eff6947d721e858763a885f13f24a4695205ca3d47af330d8ae24cf\",\"analysis_revision\":1,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект ужесточает условия доплаты пенсии до минимальной из ZUS: помимо возраста и стажа потребуется накопить на пенсионном счёте взносы не ниже 25-кратного минимального вознаграждения (в 2026 г. — около 120 150 zł). Формально касается всех, но по обоснованию нацелен на иностранцев с коротким стажем работы в Польше.\",\"key_changes\":[\"Новое условие в art. 87 ust. 1 ustawy o emeryturach i rentach z FUS для доплаты до минимальной пенсии\",\"Требуется валоризованная сумма взносов на счёте не ниже 25-кратного минимального вознаграждения (~120 150 zł в 2026 г.)\",\"Условия возраста (65/60 лет) и стажа (25/20 лет) сохраняются\",\"Новые правила применяются и к делам, начатым, но не завершённым до вступления в силу\",\"Цель обоснования — ограничить доплаты лицам с минимальным стажем работы в Польше\"],\"affected_groups\":[\"Иностранцы, работавшие в Польше и получающие пенсию из ZUS\",\"Граждане Украины и других стран с договорами о социальном обеспечении с Польшей\",\"Лица с коротким периодом уплаты взносов в Польше\",\"Граждане Польши с низкими накоплениями в ZUS\"],\"practical_impact\":\"Если сумма взносов на счёте в ZUS ниже указанного порога, доплата до минимальной пенсии не будет назначена, даже при достаточном общем стаже с учётом периодов работы за границей. Это касается и заявлений, поданных до вступления закона в силу, но ещё не рассмотренных.\",\"effective_date\":\"Через 14 дней со дня опубликования\",\"confidence\":0.9,\"rationale\":\"Проект напрямую влияет на социальные выплаты (пенсии) иностранцам, работавшим в Польше, но не затрагивает легализацию пребывания или работу.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":38308,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-18T19:08:16Z\",\"input_tokens\":20036,\"output_tokens\":700,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3205/3205.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:4abee9811eff6947d721e858763a885f13f24a4695205ca3d47af330d8ae24cf\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":\"law-v2:3198311dc715b17383e0ca232f3b80f6c1e87c1a624af2f0653b2347f289e9f9\",\"source_checked_at\":\"2026-10-09T07:44:09Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Барьер доплаты ZUS\",\"language\":\"ru\",\"basis\":\"Проект вводит высокий порог накопленных взносов для получения доплаты пенсии до минимальной из ZUS, что особенно затронет иностранцев с коротким стажем работы в Польше.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":3,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/31544/2026\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych\",\"description\":\"wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej\",\"applicant\":\"deputies\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-18\",\"print_number\":\"3205\",\"eu_related\":false,\"public_consultation\":true,\"consultation_start\":\"2026-09-21\",\"consultation_end\":\"2026-10-21\",\"consultation_results\":true,\"withdrawn_date\":null,\"senders_number\":null},\"linked_number\":\"RPW/31544/2026\",\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-08T17:29:48Z\",\"last_checked_at\":\"2026-10-23T17:54:29Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["participation_result"],"explanation":"Consultation results became available.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-23T17:57:13Z","assessed_at":"2026-10-23T17:57:13Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"","disable_notification":false,"schedule":null,"destination":"digest_only","destination_reason":"documents_without_confirmed_consequence","proposed_destination":"digest_only","digest_eligible_at":"2026-10-23T17:57:13Z","digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":null,"still_meets":false,"reply_to":58,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["participation_result"],"explanation":"Consultation results became available.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-23T17:57:13Z","assessed_at":"2026-10-23T17:57:13Z","novelty":"unknown","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(187,10,'RCL/12411650','consultation_results','sent','@lex_inform_pl',139,'[]',NULL,'2026-10-23T18:00:32+00:00','2026-10-25T11:54:28+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12411650\",\"title\":\"projekt ustawy o zmianie ustawy o pracy na morzu oraz niektórych innych ustaw\",\"description\":\"BEZPIECZEŃSTWO I HIGIENA PRACY; PRACA; MORSKIE PRAWO; gospodarka morska\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-06-23\",\"document_date\":\"2026-06-23\",\"change_date\":\"2026-10-23T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12411650\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:repatriacja\",\"text:straz_graniczna\",\"text:schengen\",\"text:obywatele_innych_panstw\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"1de035118b31f677b3db311cd7b5525a6bea20344f8d38a8629d8ee8a02db025\",\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":null,\"observed_process\":{\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12411650/13210764/13210765/dokument783211.pdf\",\"kind\":\"rcl\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"48c4fa6122b06be1ee3d21ff6a70ca34f66153682d68f3fc8fbea0d4db0c1919\",\"analysis_revision\":1,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"employment\",\"summary\":\"Проект меняет ustawa o pracy na morzu (закон о труде на море). Для моряков-иностранцев на судах под польским флагом минимальная зарплата будет привязана к стране их постоянного проживания, а обязательное соцстрахование в Польше на них в общем случае распространяться не будет. Также закрепляется право схода на берег без прохождения погранперехода.\",\"key_changes\":[\"Базовая зарплата моряка-нерезидента — не ниже минималки страны его постоянного проживания\",\"Моряки не из ЕС/ЕЭЗ без места жительства в ЕС не подлежат обязательному соцстрахованию в Польше\",\"Исключение: при постоянных перевозках/услугах в польских портах и водах ZUS обязателен\",\"Право схода на берег с удостоверением моряка (МОТ №108/185, FAL) без явки на пограничный переход\",\"Заявления и документы (книжка моряка, репатриация, жалобы) можно подавать на польском или английском\"],\"affected_groups\":[\"моряки-иностранцы на судах под польским флагом\",\"моряки из стран вне ЕС/ЕЭЗ\",\"экипажи судов, заходящих в польские порты\",\"судовладельцы (armatorzy)\"],\"practical_impact\":\"Для моряка-иностранца меняется порядок расчёта минимальной зарплаты и обязанность страхования в ZUS, а сход на берег в польском порту и возвращение на судно возможны по удостоверению моряка без отдельной визы и явки на погранпереход; отказ Straż Graniczna должен быть обоснован, по требованию — письменно.\",\"effective_date\":\"Закон вступает в силу по истечении 30 дней со дня опубликования.\",\"confidence\":0.83,\"rationale\":\"Проект напрямую регулирует трудовые и страховые права моряков-иностранцев и их право схода на берег, но не касается легализации пребывания.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":77736,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-09-15T01:42:25Z\",\"input_tokens\":38746,\"output_tokens\":925,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12411650/13210764/13210765/dokument783211.pdf\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"48c4fa6122b06be1ee3d21ff6a70ca34f66153682d68f3fc8fbea0d4db0c1919\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":null,\"source_checked_at\":null},\"editorial\":{\"mnemonic\":{\"name\":\"Иностранная минималка морякам\",\"language\":\"ru\",\"basis\":\"Проект привязывает минимальную зарплату моряков-нерезидентов к минималке в стране их постоянного проживания и меняет для них правила соцстрахования в Польше.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":0,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12411650,\"title\":\"projekt ustawy o zmianie ustawy o pracy na morzu oraz niektórych innych ustaw\",\"applicant\":\"Minister Infrastruktury\",\"wykaz_number\":\"UPRO10\",\"wykaz_url\":\"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-pracy-na-morzu-oraz-niektorych-innych-ustaw2\",\"created\":\"2026-06-23\",\"modified\":\"2026-10-23\",\"departments\":[\"gospodarka morska\"],\"keywords\":[\"BEZPIECZEŃSTWO I HIGIENA PRACY\",\"PRACA\",\"MORSKIE PRAWO\"],\"status\":\"otwarty\",\"eu_note\":null,\"term_label\":\"X\",\"