ting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":251,\"no\":144,\"abstain\":41,\"not_participating\":24,\"sitting\":67,\"voting_number\":177,\"date\":\"2026-10-22T17:04:08Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/67/177/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-10-22\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf\",\"kind\":\"text_after3\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:9a627081d5ebee24320cd3df17b863358eac053a2ca96a3a63930842c85ef393\",\"analysis_revision\":3,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект подстраивает законы о Straży Granicznej, границе и об иностранцах под регламент ЕС 2019/1896 о Frontex. Для иностранцев это создаёт чёткую базу для операций и интервенций по принудительному возвращению (депортации) при участии Frontex в Польше.\",\"key_changes\":[\"В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС\",\"Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы\",\"Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу\",\"В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex\",\"В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше\"],\"affected_groups\":[\"иностранцы с решениями о возврате/выдворении\",\"мигранты с неурегулированным статусом, подлежащие депортации\",\"лица, находящиеся в процедурах принудительного возвращения\"],\"practical_impact\":\"При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.\",\"effective_date\":\"закон вступает в силу через 14 дней со дня его официального опубликования.\",\"confidence\":0.94,\"rationale\":\"Проект прямо добавляет в ustawa o cudzoziemcach (закон об иностранцах) режим операций и интервенций по возвращению при участии Frontex, что непосредственно касается депортаций и статуса пребывания иностранцев, поэтому категория legal_stay и важность 5.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":25424,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T14:59:32Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf\",\"source_kind\":\"text_after3\",\"revision\":3,\"text_sha256\":\"text-v2:9a627081d5ebee24320cd3df17b863358eac053a2ca96a3a63930842c85ef393\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf\",\"members\":[],\"container_sha256\":\"a81d8c71ca12c5ffe4113001b6173e2cf5c787bf5d22d935190e55393148f319\",\"sha256\":\"a81d8c71ca12c5ffe4113001b6173e2cf5c787bf5d22d935190e55393148f319\",\"role\":\"bill\",\"text\":\"\",\"pages\":12,\"page_start\":1,\"page_end\":12,\"text_start\":0,\"text_end\":24189,\"text_sha256\":\"deff59c098299926633e0a6f4eea504df9c4cf8ad3620483a9e5fac248ea98a8\",\"losses\":[]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf\",\"text_sha256\":\"deff59c098299926633e0a6f4eea504df9c4cf8ad3620483a9e5fac248ea98a8\",\"block_id\":\"part:0\",\"start\":0,\"end\":182,\"quote\":\"Tekst ustawy przekazany do Senatu zgodnie z art. 52 regulaminu Sejmu\\n\\nUSTAWA\\nz dnia 22 października 2026 r.\\no zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw1)\\nArt. 1\"},{\"kind\":\"coverage\",\"value\":\"body_through_commencement\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/processes/3146/attachment/3146_u3.pdf\",\"text_sha256\":\"deff59c098299926633e0a6f4eea504df9c4cf8ad3620483a9e5fac248ea98a8\",\"block_id\":\"part:0\",\"start\":24081,\"end\":24103,\"quote\":\"Ustawa wchodzi w życie\"}],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":24189,\"page_start\":1,\"page_end\":12,\"losses\":[]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":24189,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"db0e9eaa408b6b7a6cb51841ed2db0e9ba684baa506c7a17b8941737decdfde4\"},\"law_sha256\":\"law-v2:8c1948260dc16145adcb198b519959321eb2fc6655c8812a6acf16669f797f51\",\"source_checked_at\":\"2026-10-23T18:01:35Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Депортации Frontex\",\"language\":\"ru\",\"basis\":\"Проект вводит в закон об иностранцах операции и интервенции по принудительному возвращению с участием Frontex и регулирует их проведение в Польше.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":8,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32084/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-23\",\"print_number\":\"3146\",\"eu_related\":true,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null,\"senders_number\":null},\"linked_number\":\"RCL/12405005\",\"linked_wykaz_number\":\"UC126\",\"act\":null,\"authors\":null,\"agenda\":[{\"kind\":\"sejm\",\"ref\":\"sejm/67/2026-10-20\",\"date\":\"2026-10-20\",\"end_date\":\"2026-10-23\",\"start_time\":null,\"committee_code\":null,\"committee_name\":null,\"sitting_number\":67,\"room\":null,\"text\":\"Sprawozdanie Komisji Administracji i Spraw Wewnętrznych o rządowym projekcie ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw (druki nr 3146 i ) - sprawozdawca poseł Artur Jarosław Łącki.\",\"video_url\":null,\"condition\":null,\"closed\":false,\"apply_email\":null,\"apply_by\":null}],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-28T15:32:12Z\",\"last_checked_at\":\"2026-10-23T18:01:44Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["confirmed_decision"],"explanation":"Decision or process closure evidence changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-23T18:01:08Z","assessed_at":"2026-10-23T18:01:44Z","novelty":"new_decision","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Депортации Frontex · druk nr 3146</b>\n✅ <b>Сейм принял закон</b>\n<i>Принят Сеймом 22 окт 2026</i>\n\n🧭 <b>Новые стадии</b>\n• 22 окт 2026: III чтение на заседании Сейма — закон принят\n• 22 окт 2026: 🗳 <b>Голосование:</b> 251 за, 144 против, 41 воздержались · не голосовали: 24 · <a href=\"https://api.sejm.gov.pl/sejm/term10/votings/67/177/pdf\">протокол голосования (PDF)</a>\n  За: KO 148, PSL-TD 30, Lewica 20, Konfederacja 16, … · Против: PiS 140, Demokracja 2, PSL-TD 1, niez. 1 · Воздержались: RozwojPlus 38, Konfederacja_KP 2, Demokracja 1\n• процесс в Сейме завершён\n\n⏭ <b>Что дальше:</b> рассмотрение в Сенате (до 30 дней) · решение до 21 нояб 2026\n👉 <b>Что можно сделать сейчас:</b> Данные о комиссии и маршруте подачи пока не подтверждены; проверьте страницу Сената.\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3146\">Страница проекта в Сейме</a> | <a href=\"https:/