7,\"voting_number\":149,\"date\":\"2026-10-22T16:45:08Z\",\"pdf_url\":\"https://api.sejm.gov.pl/sejm/term10/votings/67/149/pdf\",\"clubs\":[]},\"committee_name\":null,\"children\":[]}]},{\"stage_name\":\"Uchwalono\",\"stage_type\":\"End\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":\"2026-10-22\",\"passed\":true,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"kind\":\"committee_report\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:5dd8519f8dbf37d9ed90080a6224c539a78b2c705c073ae7ee01f6488f9a839b\",\"analysis_revision\":2,\"seen_supplements\":[\"3157-001\",\"3157-002\",\"3157-003\"]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект усиливает контроль NFZ над медучреждениями и условия найма/оплаты медиков. В закон о правах пациента вводится прямое право на равное обращение и запрет дискриминации, в том числе по гражданству и национальности.\",\"key_changes\":[\"В закон о правах пациента вводится право на равное обращение\",\"Прямой запрет дискриминации по гражданству, национальности и др.\",\"Обязанность медорганизаций активно предотвращать дискриминацию\",\"Расширяется доступ NFZ к меддокументации и контролю учреждений\",\"Жёстко регулируются время работы и максимум оплат для медиков NFZ\"],\"affected_groups\":[\"иностранцы, пользующиеся услугами NFZ\",\"иностранные работники и студенты с правом на медобслуживание в Польше\",\"пациенты‑иностранцы в государственных и контрактных клиниках\"],\"practical_impact\":\"Иностранец, имеющий право на лечение в Польше, получает чёткую юридическую базу требовать одинакового доступа к услугам и условиям приёма вне зависимости от гражданства. Жалобы на отказ или худшие условия из‑за паспорта можно опирать на прямую норму закона о правах пациента.\",\"effective_date\":\"Устawa wchodzi w życie po upływie miesiąca od dnia ogłoszenia (через месяц со дня официального опубликования).\",\"confidence\":0.94,\"rationale\":\"Проект прямо вводит в закон о правах пациента запрет дискриминации, включая по гражданству, что существенно влияет на социальные права иностранцев в системе здравоохранения (категория „social”, важность 3).\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":81176,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-12T22:14:38Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"source_kind\":\"committee_report\",\"revision\":2,\"text_sha256\":\"text-v2:5dd8519f8dbf37d9ed90080a6224c539a78b2c705c073ae7ee01f6488f9a839b\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3193/3193.pdf\",\"members\":[],\"container_sha256\":\"12e4ff3820a9110255d2aadf03e3a86dfa264fb58b56dcb0c9d081d5387d81a6\",\"sha256\":\"12e4ff3820a9110255d2aadf03e3a86dfa264fb58b56dcb0c9d081d5387d81a6\",\"role\":\"unknown\",\"text\":\"\",\"pages\":38,\"page_start\":1,\"page_end\":38,\"text_start\":0,\"text_end\":81176,\"text_sha256\":\"465e2f79824fe17ab7ddbf1adfcc84a414086766951c1f7d9fb9b4c04d8a920a\",\"losses\":[]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":81176,\"page_start\":1,\"page_end\":38,\"losses\":[]}],\"normative_sha256\":\"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945\"},\"law_sha256\":\"law-v2:1ea862ae2d11a96f555c0ce8737e38455e925538f24d9d6e71ee8a04d682afda\",\"source_checked_at\":\"2026-10-21T18:11:10Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Антидискриминация в медицине\",\"language\":\"ru\",\"basis\":\"Проект вводит в закон о правах пациента прямой запрет дискриминации, в том числе по гражданству и национальности, и обязанность медорганизаций ей противодействовать.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":4,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/32531/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-28\",\"print_number\":\"3157\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\