INSERT INTO "publications" VALUES(198,10,'3160','status_update','sent','@lex_inform_pl',135,'[]',160,'2026-10-23T18:02:24+00:00','2026-10-23T18:02:25+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3160\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-01\",\"document_date\":\"2026-10-01\",\"change_date\":\"2026-10-23T08:03:34Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-169-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"batch_pending\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:nieruchomosci_cudzoziemcy\",\"text:praca_sezonowa\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-01\",\"print_number\":\"3160\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":