е до 21 нояб 2026\n👉 <b>Что можно сделать сейчас:</b> Данные о комиссии и маршруте подачи пока не подтверждены; проверьте страницу Сената.\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3160\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3160\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf\">Текст после III чтения</a>\n\n#принят #голосование #важность2 #косвенно #kadencja10druk3160","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"{\"id\":160,\"term\":10,\"number\":\"3160\",\"old_fingerprint\":\"727c1fbcb0d823bbcef7a16fec281600b666f29a19da67ef89aa91191940894b\",\"new_fingerprint\":\"3fbf894380c9173f0296c76659815f1265adcf501c8c9a0b22e9fabcac352f04\",\"new_stages\":[{\"stage_name\":\"III czytanie na posiedzeniu Sejmu\",\"stage_type\":\"SejmReading\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":67,\"decision\":\"uchwalono\",\"committee_code\":null,\"report_file\":null,\"text_after3\":\"https://api.sejm.gov.pl/sejm/term10/processes/3160/attachment/3160_u3.pdf\",\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Głosowanie\",\"stage_type\":\"Voting\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":{\"yes\":231,\"no\":6,\"abstain\":200,\"not_participating\":23,\"sitting\":67,\"voting_number\":124,\"date\":\"2026-10-22T16:29:14Z\",\"pdf_url\":\"https://ap