INSERT INTO "publications" VALUES(200,10,'3205','status_update','sent','@lex_inform_pl',138,'[]',161,'2026-10-23T18:02:25+00:00','2026-10-24T18:21:26+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3205\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych\",\"description\":\"projekt dotyczy wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-18\",\"document_date\":\"2026-09-18\",\"change_date\":\"2026-10-23T08:02:23Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:migracja\",\"text:obywatelstwo\",\"text:obywatele_ukrainy\",\"text:uznawanie_kwalifikacji\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-18\",\"print_number\":\"3205\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Polityki Społecznej i Rodziny\",\"children\":[]}]}],\"stages_fingerprint\":\"473f0724b67a7f1a15aa97fbfa3bd6ecbce8229809c82f4e3b132eeeb218242b\",\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":[],\"observed_process\":{\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-18\",\"print_number\":\"3205\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-22\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Polityki Społecznej i Rodziny\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3205/3205.pdf\",\"kind\":\"print\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:4abee9811eff6947d721e858763a885f13f24a4695205ca3d47af330d8ae24cf\",\"analysis_revision\":1,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект ужесточает условия доплаты пенсии до минимальной из ZUS: помимо возраста и стажа потребуется накопить на пенсионном счёте взносы не ниже 25-кратного минимального вознаграждения (в 2026 г. — около 120 150 zł). Формально касается всех, но по обоснованию нацелен на иностранцев с коротким стажем работы в Польше.\",\"key_changes\":[\"Новое условие в art. 87 ust. 1 ustawy o emeryturach i rentach z FUS для доплаты до минимальной пенсии\",\"Требуется валоризованная сумма взносов на счёте не ниже 25-кратного минимального вознаграждения (~120 150 zł в 2026 г.)\",\"Условия возраста (65/60 лет) и стажа (25/20 лет) сохраняются\",\"Новые правила применяются и к делам, начатым, но не завершённым до вступления в силу\",\"Цель обоснования — ограничить доплаты лицам с минимальным стажем работы в Польше\"],\"affected_groups\":[\"Иностранцы, работавшие в Польше и получающие пенсию из ZUS\",\"Граждане Украины и других стран с договорами о социальном обеспечении с Польшей\",\"Лица с коротким периодом уплаты взносов в Польше\",\"Граждане Польши с низкими накоплениями в ZUS\"],\"practical_impact\":\"Если сумма взносов на счёте в ZUS ниже указанного порога, доплата до минимальной пенсии не будет назначена, даже при достаточном общем стаже с учётом периодов работы за границей. Это касается и заявлений, поданных до вступления закона в силу, но ещё не рассмотренных.\",\"effective_date\":\"Через 14 дней со дня опубликования\",\"confidence\":0.9,\"rationale\":\"Проект напрямую влияет на социальные выплаты (пенсии) иностранцам, работавшим в Польше, но не затрагивает легализацию пребывания или работу.\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"claude-opus-5\",\"prompt_version\":\"2026-09-v7\",\"input_chars\":38308,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-09-18T19:08:16Z\",\"input_tokens\":20036,\"output_tokens\":700,\"cache_read_input_tokens\":2496,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3205/3205.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:4abee9811eff6947d721e858763a885f13f24a4695205ca3d47af330d8ae24cf\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":\"law-v2:3198311dc715b17383e0ca232f3b80f6c1e87c1a624af2f0653b2347f289e9f9\",\"source_checked_at\":\"2026-10-09T07:44:09Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Барьер доплаты ZUS\",\"language\":\"ru\",\"basis\":\"Проект вводит высокий порог накопленных взносов для получения доплаты пенсии до минимальной из ZUS, что особенно затронет иностранцев с коротким стажем работы в Польше.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":3,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/31544/2026\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o emeryturach i rentach z Funduszu Ubezpieczeń Społecznych\",\"description\":\"wprowadzenia dodatkowego warunku podwyższenia emerytury do wysokości emerytury minimalnej polegającego na wykazaniu zwaloryzowanej wysokości składek na ubezpieczenie emerytalne ewidencjonowanej na koncie ubezpieczonego w wysokości nie niższej niż równowartość dwudziestopięciokrotności kwoty minimalnego wynagrodzenia pracowników, w celu uszczelnienia systemu emerytalnego oraz ograniczenia ryzyka nadużyć i zjawiska tzw. turystyki emerytalnej\",\"applicant\":\"deputies\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-09-18\",\"print_number\":\"3205\",\"eu_related\":false,\"public_consultation\":true,\"consultation_start\":\"2026-09-21\",\"consultation_end\":\"2026-10-21\",\"consultation_results\":true,\"withdrawn_date\":null,\"senders_number\":null},\"linked_number\":\"RPW/31544/2026\",\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-08T17:29:48Z\",\"last_checked_at\":\"2026-10-23T18:02:25Z\"}","attention":{"importance":"routine","urgency":"normal","reasons":["routine_process"],"explanation":"Only routine process facts changed.","affected_groups":[],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-23T18:02:25Z","assessed_at":"2026-10-23T18:02:25Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Барьер доплаты ZUS · druk nr 3205</b>\n📮 <b>Направлен в комиссию</b>\n\n🧭 <b>Новые стадии</b>\n• 22 окт 2026: направлен на I чтение\n• 22 окт 2026: 📮 Направлен в комиссию: Komisja Polityki Społecznej i Rodziny (PSR)\n\n⏭ <b>Что дальше:</b> I чтение в комиссии — Komisja Polityki