INSERT INTO "publications" VALUES(201,10,'RPW/35640/2026','new_bill','sent','@lex_inform_pl',136,'[]',NULL,'2026-10-23T18:21:36+00:00','2026-10-23T18:21:37+00:00',NULL,0,NULL,'dddec2fc142b5818a95f5b304e9b452537092943acf73b5ea5d6360b00eae546','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RPW/35640/2026\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o Instytucie Pamięci Narodowej - Komisji Ścigania Zbrodni przeciwko Narodowi Polskiemu oraz niektórych innych ustaw\",\"description\":\"kompleksowego uregulowania ochrony pamięci ofiar zbrodni popełnionych przez członków i współpracowników Organizacji Ukraińskich Nacjonalistów frakcji Bandery (OUN-B), Ukraińskiej Powstańczej Armii (UPA) oraz innych ukraińskich organizacji i formacji kolaborujących z Trzecią Rzeszą Niemiecką - w szczególności zbrodni ludobójstwa dokonanej na ludności polskiej na Wołyniu i w sąsiednich regionach II Rzeczypospolitej Polskiej\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-22\",\"document_date\":\"2026-10-22\",\"change_date\":\"2026-10-22T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":\"deputies\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:migracja\",\"text:straz_graniczna\",\"text:deportacja\",\"text:obywatele_innych_panstw\",\"text:uznawanie_kwalifikacji\"],\"stages\":[],\"stages_fingerprint\":null,\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":5,\"category\":\"legal_stay\",\"summary\":\"Проект вводит уголовную ответственность за публичную пропаганду идеологии и символики ОУН‑Б и УПА, отрицание и прославление их преступлений. Для иностранцев такие действия станут отдельным основанием для решения о выдворении и многолетнем запрете въезда в Польшу.\",\"key_changes\":[\"Прямая криминализация идеологии и символики ОУН-Б и УПА в Kodeks karny\",\"Кара за отрицание, похвалу и героизацию волынских преступлений в ustawa o IPN\",\"Новые основания выдворения иностранца после приговора за такие преступления\",\"Возможен занос иностранца в реестр нежелательных и запрет въезда до 5 лет\",\"Запрет тратить польские госcредства (в т.ч. за рубежом) на прославление ОУН-Б/УПА\"],\"affected_groups\":[\"иностранцы, публично продвигающие идеологию или символику ОУН-Б/УПА\",\"иностранцы, отрицающие или прославляющие волынское преступление и другие описанные злодеяния\",\"иностранные НКО и проекты, получающие польские госcредства\"],\"practical_impact\":\"Иностранец, публично прославляющий ОУН-Б/УПА или отрицающий описанные в законе преступления, может получить уголовный приговор, после чего воевода вынесет решение о выезде с запретом въезда на 3–5 лет. Даже без приговора такие действия могут привести к занесению в реестр нежелательных и запрету въезда до 5 лет, а проекты не получат польское госфинансирование.\",\"effective_date\":\"Через 30 дней после опубликования, кроме норм о названиях и памятниках, которые вступают в силу через 3 месяца после опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект прямо меняет ustawę o cudzoziemcach, вводя новые основания для решения о возвращении и запрете въезда иностранцев за пропаганду идеологии ОУН-Б/УПА и отрицание или прославление связанных с ними преступлений.\",\"mnemonic_candidate\":\"Депортация за УПА\",\"mnemonic_fallback\":\"Выдворение за УПА\",\"mnemonic_basis\":\"Проект добавляет в ustawę o cudzoziemcach отдельное основание для решения о возвращении и запрете въезда за преступления, связанные с идеологией или символикой ОУН-Б/УПА и отрицанием их зločинów.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"input_chars\":48328,\"truncated\":true,\"text_source\":\"pdf\",\"created_at\":\"2026-10-23T18:21:00Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:ee1a33cdce683dffb0cc9c49bd99ff6619e9c2a702c9a98db0f4ef525622cfe9\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf\",\"members\":[],\"container_sha256\":\"9a8d3709ce89cdf307d21392082f7bc25342ca86d1f22e641e9586aa8d5b66a6\",\"sha256\":\"9a8d3709ce89cdf307d21392082f7bc25342ca86d1f22e641e9586aa8d5b66a6\",\"role\":\"bill\",\"text\":\"\",\"pages\":24,\"page_start\":1,\"page_end\":24,\"text_start\":0,\"text_end\":48328,\"text_sha256\":\"568ace2a76b0b32ce9455786b2c186e0cd8265507ddf72260d319613b983fef7\",\"losses\":[\"text page coverage differs from the PDF page count\"]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf\",\"text_sha256\":\"568ace2a76b0b32ce9455786b2c186e0cd8265507ddf72260d319613b983fef7\",\"block_id\":\"part:0\",\"start\":0,\"end\":181,\"quote\":\"1\\n\\nProjekt\\nUSTAWA\\nz dnia …………………… 2026 r.\\no zmianie ustawy o Instytucie Pamięci Narodowej – Komisji Ścigania Zbrodni przeciwko\\nNarodowi Polskiemu oraz niektórych innych ustaw\\nArt. 1\"}],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":48328,\"page_start\":1,\"page_end\":24,\"losses\":[\"text page coverage differs from the PDF page count\"]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":48328,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"b113474d7b94bc20bf3b81e7ac2f238f635fc41154e574967a3b871ca87e119e\"},\"law_sha256\":\"law-v2:2ba1e1aa4180b97f67e338b498bb3be748fb0090e996fa97194c6ce4ab3de8a2\",\"source_checked_at\":\"2026-10-23T18:21:00Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Депортация за УПА\",\"language\":\"ru\",\"basis\":\"Проект добавляет в ustawę o cudzoziemcach отдельное основание для решения о возвращении и запрете въезда за преступления, связанные с идеологией или символикой ОУН-Б/УПА и отрицанием их зločинów.\",\"selected_at\":\"2026-10-23T18:21:00Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/35640/2026\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o Instytucie Pamięci Narodowej - Komisji Ścigania Zbrodni przeciwko Narodowi Polskiemu oraz niektórych innych ustaw\",\"description\":\"kompleksowego uregulowania ochrony pamięci ofiar zbrodni popełnionych przez członków i współpracowników Organizacji Ukraińskich Nacjonalistów frakcji Bandery (OUN-B), Ukraińskiej Powstańczej Armii (UPA) oraz innych ukraińskich organizacji i formacji kolaborujących z Trzecią Rzeszą Niemiecką - w szczególności zbrodni ludobójstwa dokonanej na ludności polskiej na Wołyniu i w sąsiednich regionach II Rzeczypospolitej Polskiej\",\"applicant\":\"deputies\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-10-22\",\"print_number\":null,\"eu_related\":false,\"public_consultation\":true,\"consultation_start\":\"2026-10-23\",\"consultation_end\":\"2026-11-22\",\"consultation_results\":false,\"withdrawn_date\":null,\"senders_number\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-22T18:02:39Z\",\"last_checked_at\":\"2026-10-23T17:54:30Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранцы, публично продвигающие идеологию или символику ОУН-Б/УПА","иностранцы, отрицающие или прославляющие волынское преступление и другие описанные злодеяния","иностранные НКО и проекты, получающие польские госcредства"],"action":"submit_opinion","deadline":"2026-11-22","deadline_source":"https://opiniowanie.sejm.gov.pl/RPW-35640-2026","deadline_precision":"day","detected_at":"2026-10-23T18:21:36Z","assessed_at":"2026-10-23T18:21:36Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Депортация за УПА · RPW/35640/2026 (номер druku ещё не присвоен)</b>\n📜 <b>Новый законопроект</b>\n\nO Instytucie Pamięci Narodowej - Komisji Ścigania Zbrodni przeciwko Narodowi Polskiemu oraz niektórych innych ustaw\n\n👥 <b>Кого касается:</b> иностранцы, публично продвигающие идеологию или символику ОУН-Б/УПА; иностранцы, отрицающие или прославляющие волынское преступление и другие описанные злодеяния; иностранные НКО и проекты, получающие польские госcредства\n\n💡 <b>Что это значит на практике:</b> Иностранец, публично прославляющий ОУН-Б/УПА или отрицающий описанные в законе преступления, может получить уголовный приговор, после чего воевода вынесет решение о выезде с запретом въезда на 3–5 лет. Даже без приговора такие действия могут привести к занесению в реестр нежелательных и запрету въезда до 5 лет, а проекты не получат польское госфинансирование.\n\n🗣 <b>Общественные консультации:</b> 23 окт - 22 нояб 2026 · <a href=\"https://opiniowanie.sejm.gov.pl/RPW-35640-2026\">анкета на сайте Сейма</a>\n\n👉 <b>Что можно сделать сейчас:</b> заполнить анкету <a href=\"https://opiniowanie.sejm.gov.pl/RPW-35640-2026\">на сайте Сейма</a> до 22 нояб 2026\n\n🔑 <b>Ключевые изменения</b>\n• Прямая криминализация идеологии и символики ОУН-Б и УПА в Kodeks karny\n• Кара за отрицание, похвалу и героизацию волынских преступлений в ustawa o IPN\n• Новые основания выдворения иностранца после приговора за такие преступления\n• Возможен занос иностранца в реестр нежелательных и запрет въезда до 5 лет\n• Запрет тратить польские госcредства (в т.ч. за рубежом) на прославление ОУН-Б/УПА\n\n📅 <b>Вступление в силу:</b> Через 30 дней после опубликования, кроме норм о названиях и памятниках, которые вступают в силу через 3 месяца после опубликования.\n\n🗺 <b>Путь:</b> Сейм ● → комиссии → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> консультации до 22 нояб 2026, затем присвоение номера druku и I чтение\n\n🏛 <b>Стадия:</b> проект поступил в Сейм, ожидает присвоения номера druku\n✍️ <b>Инициатор:</b> депутатский\n📄 <b>Поступил в Сейм:</b> 22 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\nℹ️ <i>Анализ основан на неполном тексте документа.</i>\n\n🔴 <b>Важность:</b> ●●●●● 5/5\n🏷 <b>Категория:</b> легализация пребывания\n\n🔗 <a href=\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-35640-2026/$file/10-RPW-35640-2026.pdf\">PDF проекта (сайт Сейма)</a>\n\n#RPW_35640_2026 #важность5 #легализация #консультации","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-23","still_meets":false,"reply_to":null,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранцы, публично продвигающие идеологию или символику ОУН-Б/УПА","иностранцы, отрицающие или прославляющие волынское преступление и другие описанные злодеяния","иностранные НКО и проекты, получающие польские госcредства"],"action":"submit_opinion","deadline":"2026-11-22","deadline_source":"https://opiniowanie.sejm.gov.pl/RPW-35640-2026","deadline_precision":"day","detected_at":"2026-10-23T18:21:36Z","assessed_at":"2026-10-23T18:21:36Z","novelty":"unknown","rule_version":"attention-v1"}');
