e\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja do Spraw Deregulacji\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-23\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"PSR\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Polityki Społecznej i Rodziny\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\",\"kind\":\"print\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:b7ffd62485a003e71abc7e0e14af829f3984c046ea7842afd99c0ee6848e388b\",\"analysis_revision\":1,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила пособия 800+: ZUS сам будет продлевать право на выплату на следующий год без ежегодной заявки, если ситуация семьи не изменилась. Расширяется круг получателей за счёт лиц, которым суд передал текущую опеку над ребёнком.\",\"key_changes\":[\"ZUS автоматически продляет право на 800+ на следующий период при наличии права на 31 мая\",\"Новые получатели: лица с текущей опекой над ребёнком по решению польского суда\",\"При изменении ситуации (в т.ч. выезд за границу) сохраняется обязанность сообщать в ZUS\",\"Данные заявлений через банки и e‑системы можно хранить до 10 лет для рекламаций\",\"Уточняются правила при одновременных заявках двух опекунов и при смерти опекуна\"],\"affected_groups\":[\"иностранные родители с правом на świadczenie wychowawcze (800+)\",\"иностранные опекуны детей по решению польского суда\",\"иностранцы, являющиеся опекунами детей, указанных властями страны происхождения\"],\"practical_impact\":\"Иностранным семьям, уже получающим 800+, не придётся каждый год подавать новый электронный заявлений – ZUS сам продлит право, если нет изменений. Нужно внимательно сообщать ZUS о переезде за границу, смене состава семьи или опекуна, иначе могут возникнуть переплаты или отказ.\",\"effective_date\":\"Закон вступает в силу по истечении 14 дней со дня опубликования, за исключением art. 1 pkt 4 lit. a, pkt 5, pkt 9 lit. a и pkt 10–13 и art. 3, которые вступают в силу 1 февраля 2027 г.\",\"confidence\":0.94,\"rationale\":\"Проект меняет правила назначения и продления семейного пособия 800+, которое доступно не только гражданам Польши, поэтому это социально важное изменение для иностранцев с детьми.\",\"mnemonic_candidate\":\"Автопродление 800 плюс\",\"mnemonic_fallback\":\"Автопродление пособия 800+\",\"mnemonic_basis\":\"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"input_chars\":42107,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-21T18:29:51Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:b7ffd62485a003e71abc7e0e14af829f3984c046ea7842afd99c0ee6848e388b\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[\"sejm/10/print/3267\"],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\",\"members\":[],\"container_sha256\":\"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7\",\"sha256\":\"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7\",\"role\":\"bill\",\"text\":\"\",\"pages\":62,\"page_start\":1,\"page_end\":62,\"text_start\":0,\"text_end\":110974,\"text_sha256\":\"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1\",\"losses\":[]}],\"observed_parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\",\"members\":[],\"container_sha256\":\"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7\",\"sha256\":\"6b47916bde589fbc304faacd84a6746d8d2de56527f27c7b982f3dbdda2651d7\",\"role\":\"bill\",\"text\":\"\",\"pages\":62,\"page_start\":1,\"page_end\":62,\"text_start\":0,\"text_end\":110974,\"text_sha256\":\"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1\",\"losses\":[]}],\"rejected\":[],\"facts\":[{\"kind\":\"official_link\",\"value\":\"sejm/10/print/3267\",\"provenance\":\"source_relation\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\",\"text_sha256\":\"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1\",\"block_id\":\"part:0\",\"start\":0,\"end\":0,\"quote\":\"\"},{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\",\"text_sha256\":\"532fb0f6655625f0b2ae87fa5340ce3e81636ec78ee6eb670014bb1d920873c1\",\"block_id\":\"part:0\",\"start\":0,\"end\":896,\"quote\":\"Druk nr 3267\\n Warszawa, 21 października 2026 r.\\nSEJM\\nRZECZYPOSPOLITEJ POLSKIEJ\\nX kadencja\\n\\nPrezes Rady Ministrów\\nRM-0610-171-26\\n\\n Pan\\n Włodzimierz Czarzasty\\n Marszałek Sejmu\\n Rzeczypospolitej Polskiej\\n\\nSzanowny Panie Marszałku,\\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam\\nSejmowi Rzeczypospolitej Polskiej projekt ustawy\\n - o zmianie ustawy o pomocy państwa\\nw wychowywaniu dzieci.\\nProjekt ma charakter deregulacyjny oraz realizuje priorytet polityki Rady\\nMinistrów.\\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac parlamentarnych\\nzostał upoważniony Minister Rodziny, Pracy i Polityki Społecznej.\\n\\n Z poważaniem\\n Donald Tusk\\n /podpisano kwalifikowanym podpisem elektronicznym/\\n\\n                Tłoczono z polecenia  Marszałka Sejmu Rzeczypospolitej Polskiej\\n\\n\\fProjekt\\nU S T A W A\\nz dnia\\no zmianie ustawy o pomocy państwa w wychowywaniu dzieci\\nArt. 1\"}],\"limitations\":[\"annex_link_unknown\",\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":110974,\"page_start\":1,\"page_end\":62,\"losses\":[]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":110974,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"9cf5073592f18aec715743c63b65fc105ceff9234d544d31de33b89df3ea49c8\"},\"law_sha256\":\"law-v2:d83673b42b2f9050ba6a6fd9c844cfb417f84b6296f185c3820ff266c9006c2b\",\"source_checked_at\":\"2026-10-23T18:03:17Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Автопродление 800 плюс\",\"language\":\"ru\",\"basis\":\"Проект вводит автоматическое ежегодное продление права на świadczenie wychowawcze 800+ без повторной заявки, если у семьи уже было право на выплату.\",\"selected_at\":\"2026-10-21T18:29:51Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/35455/2026\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci\",\"description\":\"automatycznego odnawiania prawa do świadczenia 800+ na kolejne okresy świadczeniowe, bez konieczności corocznego składania wniosków przez rodziców i opiekunów. Nowe przepisy realizują działania deregulacyjne rządu\",\"applicant\":\"government\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-10-21\",\"print_number\":\"3267\",\"eu_related\":false,\"public_consultation\":false,\"consultation_start\":null,\"consultation_end\":null,\"consultation_results\":false,\"withdrawn_date\":null,\"senders_number\":\"RM-0610-171-26\"},\"linked_number\":\"RPW/35455/2026\",\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"relevant_analysis\",\"first_seen_at\":\"2026-10-23T17:57:12Z\",\"last_checked_at\":\"2026-10-23T18:03:17Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранные родители с правом на świadczenie wychowawcze (800+)","иностранные опекуны детей по решению польского суда","иностранцы, являющиеся опекунами детей, указанных властями страны происхождения"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-23T18:21:38Z","assessed_at":"2026-10-23T18:21:38Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Автопродление 800 плюс · druk nr 3267</b>\n📜 <b>Новый законопроект</b>\n\nO pomocy państwa w wychowywaniu dzieci\n\n👥 <b>Кого касается:</b> иностранные родители с правом на świadczenie wychowawcze (800+); иностранные опекуны детей по решению польского суда; иностранцы, являющиеся опекунами детей, указанных властями страны происхождения\n\n💡 <b>Что это значит на практике:</b> Иностранным семьям, уже получающим 800+, не придётся каждый год подавать новый электронный заявлений – ZUS сам продлит право, если нет изменений. Нужно внимательно сообщать ZUS о переезде за границу, смене состава семьи или опекуна, иначе могут возникнуть переплаты или отказ.\n\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=DER\">Komisja do Spraw Deregulacji (DER)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=DER\">форма письма</a>), <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=PSR\">Komisja Polityki Społecznej i Rodziny (PSR)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=PSR\">форма письма</a>)\n\n🔑 <b>Ключевые изменения</b>\n• ZUS автоматически продляет право на 800+ на следующий период при наличии права на 31 мая\n• Новые получатели: лица с текущей опекой над ребёнком по решению польского суда\n• При изменении ситуации (в т.ч. выезд за границу) сохраняется обязанность сообщать в ZUS\n• Данные заявлений через банки и e‑системы можно хранить до 10 лет для рекламаций\n• Уточняются правила при одновременных заявках двух опекунов и при смерти опекуна\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу по истечении 14 дней со дня опубликования, за исключением art. 1 pkt 4 lit. a, pkt 5, pkt 9 lit. a и pkt 10–13 и art. 3, которые вступают в силу 1 февраля 2027 г.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ● → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> I чтение в комиссии — Komisja do Spraw Deregulacji (DER), Komisja Polityki Społecznej i Rodziny (PSR) · обычно 2–6 недель после поступления\n\n🏛 <b>Стадия:</b> направлен на I чтение (23 окт 2026) · направлен в комиссию Komisja Polityki Społecznej i Rodziny (PSR)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 21 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟡 <b>Важность:</b> ●●●○○ 3/5\n🏷 <b>Категория:</b> соцсфера\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3267\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3267\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-171-26\">Проект на RCL</a>\n\n#kadencja10druk3267 #RPW_35455_2026 #важность3 #соцсфера #kadencja10","disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":"{\"term\":10,\"number\":\"3267\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o pomocy państwa w wychowywaniu dzieci.\",\"document_date\":\"2026-10-21\",\"delivery_date\":\"2026-10-23\",\"change_date\":\"2026-10-23T12:17:23Z\",\"attachments\":[{\"print_number\":\"3267\",\"name\":\"3267.pdf\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267.pdf\"},{\"print_number\":\"3267\",\"name\":\"3267-ustawa.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267-ustawa.docx\"},{\"print_number\":\"3267\",\"name\":\"3267-uzasadnienie.docx\",\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3267/3267-uzasadnienie.docx\"}],\"additional_prints\":[],\"process_prints\":[\"3267\"]}","primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-23","still_meets":false,"reply_to":null,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранные родители с правом на świadczenie wychowawcze (800+)","иностранные опекуны детей по решению польского суда","иностранцы, являющиеся опекунами детей, указанных властями страны происхождения"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-23T18:21:38Z","assessed_at":"2026-10-23T18:21:38Z","novelty":"unknown","rule_version":"attention-v1"}');
