INSERT INTO "publications" VALUES(205,10,'1039','message_part','sent','@lex_inform_pl',33,'[]',NULL,'2026-10-26T06:26:50+00:00','2026-10-26T06:26:55+00:00',NULL,0,'card/27/72e20aee2e035b3541da4541ff710aa6659b0c5ddcd79ef7222f7db282192bf1-27/1','72e20aee2e035b3541da4541ff710aa6659b0c5ddcd79ef7222f7db282192bf1','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"1039\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa\",\"description\":\"projekt dotyczy usunięcia przepisów pozwalających na uprzywilejowane traktowanie obywateli Ukrainy względem obywateli Rzeczypospolitej Polskiej w zakresie dostępu do określonych świadczeń socjalnych oraz w zakresie możliwości zatrudnienia ich odpowiednio w jednostkach naukowych oraz innych jednostkach organizacyjnych PAN, instytucie badawczym oraz Centrum Łukasiewicz lub instytucie działającym w ramach Sieci Badawczej Łukasiewicz bez przeprowadzania konkursu\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-01-23\",\"document_date\":\"2025-01-23\",\"change_date\":\"2025-03-05T10:13:09Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"obywatele_ukrainy\"],\"stages_fingerprint\":\"aa1546e0382267490ef77ef55e4c4b65c52426f9dd0f98b2e533f5dfc18122df\",\"observed_closure_date\":null,\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Отмена льгот украинцам\",\"language\":\"ru\",\"basis\":\"Проект отменяет спецнормы о льготном доступе граждан Украины к соцвыплатам, медпомощи NFZ и трудоустройству, приравнивая их к другим иностранцам.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":{\"representative\":\"Przemysław Wipler\",\"representative_club\":\"Konfederacja\",\"clubs\":[[\"Konfederacja\",15],[\"Konfederacja_KP\",2]],\"signatories\":17,\"unresolved\":0},\"senate\":null,\"seen_supplements\":[\"1039-001\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-11T14:43:40Z\",\"last_checked_at\":\"2026-10-26T06:26:44Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Отмена льгот украинцам · druk nr 1039</b>\n📜 <b>Новый законопроект</b>\n\nO pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa\n\n👥 <b>Кого касается:</b> граждане Украины, пребывающие в Польше на основании спецзакона; украинцы, получающие социальные выплаты и медицинскую помощь по спецзакону; украинские учёные, трудоустраивающиеся в научные учреждения\n\n💡 <b>Что это значит на практике:</b> Украинцы со статусом по спецзакону утратили бы льготный доступ к части соцвыплат и медпомощи и могли бы получать их только на общих основаниях, например при наличии карты побыту, статуса беженца или страховки NFZ. Для работы в институтах PAN и Łukasiewicz потребовался бы обычный конкурс.\n\n🗣 <b>Общественные консультации:</b> завершились 23 фев 2025 · <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KONSULTOWANY_PROJEKT&amp;NrProjektu=RPW/2793/2025\">страница консультаций на сайте Сейма</a>\n\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=PSR\">Komisja Polityki Społecznej i Rodziny (PSR)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=PSR\">форма письма</a>)\n\n🔑 <b>Ключевые изменения</b>\n• Отмена ряда статей спецзакона (в т.ч. ст. 26, 26a, 27b, 27c, 29, 32, 33, 37) о льготном доступе к соцвыплатам\n• По обоснованию, отменяется автоматический доступ к медпомощи NFZ для легально пребывающих украинцев\n• Отмена ст. 47–49: приём украинцев на работу в институты PAN и Łukasiewicz без конкурса, по заявлению\n• Повят будет финансировать только пребывание в приёмной семье лиц из ст. 27a (новая редакция ст. 27d)\n• Замена в тексте закона «w Ukrainie» на «na Ukrainie» (языковая правка)\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу по истечении 30 дней со дня опубликования.\n\n🗺 <b>Путь:</b> Сейм ✓ → комиссии ● → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> I чтение в комиссии — Komisja Polityki Społecznej i Rodziny (PSR) · без движения уже 20 мес.\n\n🏛 <b>Стадия:</b> направлен на I чтение (5 марта 2025) · направлен в комиссию Komisja Polityki Społecznej i Rodziny (PSR)\n✍️ <b>Инициатор:</b> депутатский (подписали: Konfederacja 15, Konfederacja_KP 2 · представитель: Przemysław Wipler, Konfederacja)\n📄 <b>Дата druku:</b> 23 янв 2025\n\n🟠 <b>Важность:</b> ●●●●○ 4/5\n🏷 <b>Категория:</b> соцсфера\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=1039\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=1039\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/1039/1039.pdf\">PDF</a>\n\n#kadencja10druk1039 #важность4 #соцсфера #Украина #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":27,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-26","still_meets":false,"reply_to":33,"edit_message_id":33,"revision_of":27,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(206,10,'1040','message_part','sent','@lex_inform_pl',34,'[]',NULL,'2026-10-26T06:26:59+00:00','2026-10-26T06:27:02+00:00',NULL,0,'card/28/5c4485a9821f425c2f7b101968d66130a068d647eae3f759f94e862cc585f31a-28/1','5c4485a9821f425c2f7b101968d66130a068d647eae3f759f94e862cc585f31a','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"1040\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa\",\"description\":\"projekt dotyczy propozycji wprowadzenia dwóch dodatkowych warunków, od których uzależnione jest otrzymanie świadczenia wychowawczego przez obywateli Ukrainy na podstawie ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium: 1) warunek zatrudnienia lub prowadzenia działalności gospodarczej na terytorium Rzeczypospolitej Polskiej,2) warunek realizowania zobowiązania podatkowego wobec Skarbu Państwa, chyba, że zaległości z uiszczeniem podatków wynikają z uzyskania przewidzianych prawem zwolnienia, odroczenia, rozłożenia na raty zaległych płatności lub wstrzymania w całości wykonania decyzji właściwego organu. Projekt wprowadza również przepisy, które zakładają wstrzymanie wypłaty świadczenia w przypadku podjęcia przez właściwe organy informacji o pozostawaniu bez pracy, jak również nie odprowadzaniu podatku i  przywrócenia świadczenia w przypadku ponownego spełnienia tych warunków.\\n\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-01-20\",\"document_date\":\"2025-01-20\",\"change_date\":\"2025-03-05T10:15:17Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"obywatele_ukrainy\"],\"stages_fingerprint\":\"7c566ff411a50170979cb17fbde9e6a3a7a97e46e712fb36a796e3ed98160182\",\"observed_closure_date\":null,\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"800+ за занятость\",\"language\":\"ru\",\"basis\":\"Проект делает выплату 800+ для граждан Украины зависимой от работы/бизнеса в Польше и уплаты налогов, с приостановкой при невыполнении условий.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":{\"representative\":\"Zbigniew Bogucki\",\"representative_club\":\"PiS\",\"clubs\":[[\"PiS\",24],[\"RozwojPlus\",3]],\"signatories\":27,\"unresolved\":0},\"senate\":null,\"seen_supplements\":[\"1040-001\",\"1040-002\",\"1040-003\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-11T14:44:07Z\",\"last_checked_at\":\"2026-10-26T06:26:44Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>800+ за занятость · druk nr 1040</b>\n📜 <b>Новый законопроект</b>\n\nO pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa\n\n👥 <b>Кого касается:</b> Граждане Украины с легальным пребыванием на основании art. 2 ust. 1 спецзакона; Украинские родители, получающие или подающие заявление на 800+\n\n💡 <b>Что это значит на практике:</b> Чтобы получать 800+ на ребёнка, гражданину Украины нужно будет работать или вести бизнес в Польше и не иметь налоговых задолженностей; иначе ZUS приостановит выплату. Новые условия впервые применяются к заявлениям, подаваемым с 1 февраля по 30 апреля 2025 г.\n\n🗣 <b>Общественные консультации:</b> завершились 20 фев 2025 · <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KONSULTOWANY_PROJEKT&amp;NrProjektu=RPW/1978/2025\">страница консультаций на сайте Сейма</a>\n\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=PSR\">Komisja Polityki Społecznej i Rodziny (PSR)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=PSR\">форма письма</a>)\n\n🔑 <b>Ключевые изменения</b>\n• Новое условие для 800+: трудоустройство или ведение działalności gospodarczej в Польше\n• Новое условие: исполнение налоговых обязательств перед государством\n• Исключение: законные освобождения, отсрочки, рассрочка или приостановление решения органа\n• Приостановление выплаты при выявлении отсутствия работы или неуплаты налогов\n• Возобновление выплаты с месяца, когда условия снова выполнены\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу по истечении 14 дней со дня опубликования; новые условия впервые применяются к заявлениям, подаваемым с 1 февраля 2025 г. по 30 апреля 2025 г.\n\n🗺 <b>Путь:</b> Сейм ✓ → комиссии ● → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> I чтение в комиссии — Komisja Polityki Społecznej i Rodziny (PSR) · без движения уже 20 мес.\n\n🏛 <b>Стадия:</b> направлен на I чтение (5 марта 2025) · направлен в комиссию Komisja Polityki Społecznej i Rodziny (PSR)\n✍️ <b>Инициатор:</b> депутатский (подписали: PiS 24, RozwojPlus 3 · представитель: Zbigniew Bogucki, PiS)\n📄 <b>Дата druku:</b> 20 янв 2025\n\n🟠 <b>Важность:</b> ●●●●○ 4/5\n🏷 <b>Категория:</b> работа и трудоустройство\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=1040\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=1040\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/1040/1040.pdf\">PDF</a>\n\n#kadencja10druk1040 #важность4 #работа #Украина #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":28,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-26","still_meets":false,"reply_to":34,"edit_message_id":34,"revision_of":28,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(207,10,'RCL/12398102','status_update','queued','@lex_inform_pl',NULL,'[]',174,'2026-10-26T19:27:01+00:00',NULL,NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12398102\",\"title\":\"Projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw\",\"description\":\"OCHRONA ZDROWIA; zdrowie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-05-22\",\"document_date\":\"2026-10-26\",\"change_date\":\"2026-10-26T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12398102\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"batch_pending\",\"prefilter_hits\":[\"text:migracja\",\"text:obywatele_ukrainy\",\"text:karta_polaka\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"10. Komisja Prawnicza\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"12. Rada Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"622104eca7eb63a0ed2f772e63e567c9c67f5a46ff2d256fb4e7e5443b39032a\",\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[{\"memo_key\":\"document-review:36d82383c0d28ed7d761a103b0bc15dee26b926b5f33b895b2c43d7dbc452b7d\",\"purpose\":\"consultation_review\",\"context\":{\"number\":\"RCL/12398102\",\"title\":\"Projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw\",\"purpose\":\"consultation_review\",\"documents\":[{\"identity\":\"rcl/780621\",\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129924/13129928/dokument780621.docx\",\"role\":\"response\",\"text\":\"Raport z konsultacji publicznych oraz opiniowania projektu  ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (UD187)\\n\\n\\nZgodnie z art. 5 ustawy z dnia 7 lipca 2005 r. o działalności lobbingowej w procesie stanowienia prawa (Dz. U. z 2025 r. poz. 677, z późn. zm.), z chwilą skierowania ww. projektu ustawy do konsultacji publicznych i opiniowania oraz zgodnie z § 52 ust. 1 uchwały nr 190 Rady Ministrów z dnia 29 października 2013 r. Regulamin pracy Rady Ministrów (M.P. z 2026 r. poz. 404) przedmiotowy projekt został zamieszczony w Biuletynie Informacji Publicznej na stronie Rządowego Centrum Legislacji w serwisie Rządowy Proces Legislacyjny.\\nW trybie art. 7 ustawy z dnia 7 lipca 2005 r. o działalności lobbingowej w procesie stanowienia prawa jeden podmiot zgłosił zainteresowania pracami nad projektem ustawy: Kancelaria Radcy Prawnego Tomasz Dauerman. Uwagi zawarte w zgłoszeniu są ujęte w poniższej tabeli. \\nProjekt został przekazany do konsultacji publicznych i opiniowania (z terminem 30 dni na zgłaszanie uwag) do podmiotów wyszczególnionych w pkt 5 OSR.\\nJednocześnie projekt ustawy został poddany konsultacjom w trybie przepisów ustawy z dnia 23 maja 1991 r. o związkach zawodowych (Dz. U. z 2026 r. poz. 549) oraz ustawy z dnia 23 maja 1991 r. o organizacjach pracodawców (Dz. U. z 2025 r. poz. 423) z podmiotami wyszczególnionymi w pkt 5 OSR.\\n\\n\\n\\n Lp.\\t Podmiot zgłaszający uwagę  \\t Przepis, którego dotyczy uwaga\\t Treść uwagi\\t Uzasadnienie uwag\\t Stanowisko MZ\\n\\tStowarzyszenie Wilson Polska\\tOgólne\\tZwracamy się z uprzejmą prośbą w imieniu Chorych na chorobę Wilsona w Polsce (jest nas około 2000) o wskazanie lub stworzenie rozwiązań, które poprawią dostępność finansową i proceduralną wszystkich leków zarejestrowanych w UE do leczenia choroby Wilsona\\tDzień dobry, (1) Choroba Wilsona jest chorobą genetyczną polegającą na odkładaniu się w orgniźmie człowieka miedzi wyniszczając kolejno narządy wewnętrzne: wątrobę, układ nerwowy, nerki, itd... Niezdiagnozowana lub zdiagnozowana zbyt późno kończy się śmiercią ale wczesne jej wykrycie daje możliwość normalnego życia. Dzięki \\fodpowiednio dobranej terapii istnieją też szanse na odwrócenie zmian i przywrócenie normalnego funkcjonowania. Szacuje się, że w Polsce na tę rzadką chorobę cierpi około 2000 osób Zgodnie z wytycznymi europejskimi (https://www.journal-of-hepatology.eu/article/S0168-8278(24)02706-5/fulltext), w których powstaniu brali udział polscy eksperci, chorzy na chorobę Wilsona wymagają leczenia jednym z wymienionych poniżej produktów leczniczych. Konieczne jest zapewnienie dostępu do wszystkich leków, ponieważ z powodu nieskuteczności leczenia lub nietolerancji nierzadko konieczna jest zmiana leku. Zaprzestanie leczenia z przyczyn finansowych (tak się dzieje w przypadku Zincteralu) lub z powodu złej tolerancji leku przez pacjentów powoduje dramatyczne pogorszenie stanu zdrowia pacjentów, często nieodwracalne. Choroba Wilsona poddaje się leczeniu, które wprawdzie trwa całe życie ale jest relatywnie niedrogie, bardzo skuteczne i pozwala pacjentom normalnie żyć i pracować. Obecnie w Polsce są dostępne trzy leki do leczenia choroby Wilsona: ‒ Zincteral (siarczan cynku), nie ma statusu leku sierocego w Unii Europejskiej (UE), zarejestrowany w procedurze narodowej we wskazaniu choroba Wilsona, najczęściej stosowany, zalecana dawka dobowa 150mg, koszt miesięczny leczenia 100zł; lek jest pełnopłatny nierefundowany, podmiot odpowiedzialny Teva Pharmaceuticals Polska \\f(2) ‒ Cuprenil (D-penicylamina), nie ma statusu leku sierocego w UE, zarejestrowany w procedurze narodowej, we wskazaniu choroba Wilsona , RZS, zatrucie ołowiem, cystynuria, zalecana dawka dobowa 750-1000mg, koszt miesięczny leczenia 350zł, refundowany dla chorych na chorobę Wilsona opłata ryczałtowa 3,20 zł, podmiot odpowiedzialny Teva Pharmaceuticals Polska ‒ Cuprior (tetrachlorowodorek trientyny), nie ma statusu leku sierocego w UE, zarejestrowany w procedurze centralnej UE, dostępny w programie lekowym NFZ B.123, zalecana dawka -450-975mg, koszt miesięczny leczenia 46800zł. Podmiot odpowiedzialny Orphalan, w czerwcu 2024 zamknął przedstawicielstwo w Polsce i planuje wycofać się z rynku do czerwca 2026. Czwarty lek nie ma pozwolenia na dopuszczenie do obrotu w Polsce, ale jest dostępny w niektórych krajach UE i jest sprowadzany dla polskich pacjentów na indywidualne zamówienia: ‒ Wilzin (octan cynku), zarejestrowany w procedurze centralnej UE we wskazaniu choroba Wilsona, utracił status leku sierocego w UE (po upływie 20 lat obecności na rynku liczonych od 2001) dawka dobowa 75-150mg, koszt miesięczny leczenia 450-800zł. Podmiot odpowiedzialny Recordati Rare Diseases Piąty lek Cufence (dichlorowodorek trientyny) zarejestrowany w procedurze centralnej UE, we wskazaniu choroba Wilsona, nie ma statusu leku sierocego w UE, może być stosowany wymiennie z tetrachlorodowodorkiem trientyny \\f(Cuprior), jest bardzo rzadko lub wcale stosowany w Polsce ze względu na koszt leczenia, zalecana dawka dobowa 750–1600mg , koszt miesięczny leczenia 21000-43000zł, podmiot odpowiedzialny Univar Solutions BV. Obecnie o losie dwóch najbardziej popularnych leków dla chorych na chorobę Wilsona decyduje jeden podmiot odpowiedzialny Teva Pharmaceutiacals Polska, trzeci lek jest dostępny w imporcie a czwarty w programie lekowym NFZ (aktywnie leczonych w tym programie jest 3 pacjentów). W projekcie ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw z dnia 22.05.2025 nie odnaleźliśmy specyficznych rozwiązań poprawiających dostępność leków dla chorych na chorobę Wilsona- prosimy o ich wskazanie. W projekcie ułatwione wnioskowanie o refundację dla leków sierocych uzależnione jest od woli podmiotu odpowiedzialnego. Refundacja importu docelowego nie jest automatyczna w chorobach sierocych, zaś sam proces pozyskania leku dla indywidualnego pacjenta jest nadal skomplikowany. Ponadto żaden lek dla chorych na chorobę Wilsona nie ma statusu leku sierocego a producenci nie planują ubiegania się o ich umieszczenie ze względu na niewielką liczbę pacjentów oraz wysokie koszty opracowania dokumentacji. Dla nich nasze leki są nierentowne. Kilka lat temu zdarzyła się już taka sytuacja, że firma wstrzymała \\fprodukcję leków dla nas. Lekarze ponieśli koszty opracowania nowego wniosku o refundację. Boimy się powtórzenia podobnej sytuacji, boimy się, że zostaniemy bez leków. Oczywiście jesteśmy wdzięczni za podjęcie próby upraszczenia poszczególnych procedur (import docelowy, szybka scieżka itd.) jednak wydaje się nam, że proponowane w ustawie rozwiązania nie będą nas pacjentów chorych na chorobę Wilsona dotyczyć. Potrzebujemy prostych rozwiązań systemowych nie wymagających cyklicznego występowania i zabiegania o leki. Dla nas niesie to ogromne ryzyka i stres związany z utratą ciągłąści leczenia, co w naszym przypadku może doprowadzić do pogorszenia stanu zdrowia a nawet śmierci. Chorzy na chorobę Wilsona są skazani na przyjmowanie leków do końca życia, dlatego najlepszym sposobem będzie prosta procedura, np. wydawanie leku w aptece na podstawie recepty lub podczas wizyty w ośrodku koordynyjącym.\\t\\fUwaga niezasadna Tryb wnioskowy stanowiący elementarną zasadę obowiązującego systemu refundacyjnego pozostaje niezmienny, bowiem złożenie wniosku o objęcie refundacją pozostanie autonomiczną decyzją podmiotu odpowiedzialnego. Jednak w projekcie zaproponowano nowe brzmienie art. 30a \\fustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych (Dz. U. z 2026 r. poz. 253\\n«numer_dziennika_ustawy_ref»), dalej ,,ustawa o refundacji,, które nadaje ministrowi właściwemu do spraw zdrowia możliwość wezwania podmiotu odpowiedzialnego do złożenia wniosku refundacyjnego, kierując się w szczególności niezaspokojoną potrzebą zdrowotną oraz racjonalizacją wydatków płatnika. Podmiot odpowiedzialny przedkładając wniosek zgodny z wezwaniem ministra właściwego do spraw zdrowia upoważniony będzie do skorzystania z preferencyjnych warunków procedowania takiego wniosku w tym szybszej ścieżki dla leków w terapii skojarzonej. Preferencje uzależnione zostały od obowiązujących okresów ochronnych danego produktu leczniczego. Dodatkowo projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce \\fzdrowotnej. Stanowi to również wypełnienie postulatów, które znalazły się w pierwotnej wersji ramowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 7551a Ustawa z dnia 17 listopada 1964 r. Kodeks postępowania cywilnego \\tArt. 7551a § 1. W sprawach własności intelektualnej każdy kto spodziewa się złożenia wniosku o udzielenie zabezpieczenia (wnioskodawca), może złożyć do sądu pismo zawierające jego stanowisko w sprawie (list ochronny).  § 2. Wnioskodawca może złożyć list ochronny do jednego lub kilku sądów. Art. 734 stosuje się odpowiednio.  § 3. List ochronny powinien wskazywać osobę lub osoby, które mogą wystąpić z wnioskiem o udzielenie zabezpieczenia, przedmiot spodziewanego wniosku o \\fudzielenie zabezpieczenia oraz zawierać uprawdopodobnienie okoliczności przedstawionych w liście ochronnym. Jeżeli oznaczenie osoby lub wszystkich osób, które mogą wystąpić z wnioskiem o udzielenie zabezpieczenia, jest niemożliwe lub nadmiernie utrudnione, list ochronny zawiera informację o braku oznaczenia takiej osoby lub osób oraz wyjaśnienie przyczyn braku ich oznaczenia.  § 4. List ochronny obowiązuje przez okres 6 miesięcy od dnia jego złożenia.  § 5. Na wniosek wnioskodawcy złożony przed upływem okresu, o którym mowa w mowa w § 4, okres obowiązywania listu ochronnego ulega przedłużeniu o kolejne 6 miesięcy.  § 6. Po upływie okresu obowiązywania list ochronny zwraca się wnioskodawcy.  § 7. W razie złożenia wniosku o udzielenie zabezpieczenia w okresie obowiązywania listu ochronnego, po stwierdzeniu przez sąd, że wnioskodawca złożył uprzednio list ochronny dotyczący przedmiotu wniosku, list ten niezwłocznie dołącza się do akt sprawy, a jego odpis doręcza się uprawnionemu.  § 8. W razie złożenia listu ochronnego po złożeniu wniosku o udzielenie zabezpieczenia, a przed jego rozpoznaniem, przepis § 7 stosuje się odpowiednio.  \\t\\fZaproponowane zmiany mają na celu uregulowanie instytucji listów ochronnych, która pomaga zapobiegać nadużywaniu instytucji zabezpieczenia roszczeń. Znane są z praktyki sądowej przypadki uzyskiwania zabezpieczeń w sprawach z zakresu własności intelektualnej na podstawie jednostronnych, zmanipulowanych lub opartych na przemilczeniu istotnych okoliczności wniosków. Konsekwencje takich sytuacji są szczególnie dotkliwe, gdy w oparciu o nierzetelnie lub jednostronnie przedstawiony stan \\ffaktyczny dochodzi do udzielenia zabezpieczenia polegającego na zakazie prowadzenia obrotu towarem na czas postępowania. W takich przypadkach uprawniony osiąga skutek w postaci opóźnienia lub zniweczenia konkurencji już przez samo uzyskanie zabezpieczenia, bez względu na ostateczny wynik sprawy. Cierpią przez to pacjenci pozbawieni dostępu do terapii, a także płatnik publiczny, któremu odbiera się oszczędność. Dla przeciwdziałania opisanemu zjawisku proponuje się uregulowanie instytucji listu ochronnego. Instytucja ta znana jest w innych europejskich systemach prawnych, m. in. Niemczech, Holandii, Belgii, Szwajcarii i Hiszpanii. Instytucja ta jest również przewidziana w projekcie Regulaminu Jednolitego Sądu Patentowego. Również w Polsce, pomimo braku ustawowej regulacji, pisma ochronne występują już w praktyce, przy czym podejście sędziów jest zróżnicowane – od akceptacji takich listów poprzez włączanie ich do akt sprawy po ich zwrot.   Istotą listu ochronnego jest przedstawienie przez potencjalnego obowiązanego okoliczności dotyczących spodziewanego wniosku o zabezpieczenie roszczeń, aby umożliwić sądowi uwzględnienie stanowiska drugiej strony sporu, bez konieczności aktywnego włączania obowiązanego do postępowania zabezpieczającego. Złożenie listu ochronnego zmniejsza ryzyko wydania nieuzasadnionego i powodującego szkody zabezpieczenia, a jednocześnie gwarantuje utrzymanie \\fzasady szybkości w postępowaniu zabezpieczającym.   W ślad za przeważającymi rozwiązaniami europejskimi postuluje się wprowadzenie ograniczonego czasu obowiązywania listu ochronnego (6 miesięcy, z możliwością jednokrotnego przedłużenia o kolejne 6 miesięcy).    Wprowadzenie nowelizacji nie wpłynie na pogorszenie pozycji prawnej powodów (uprawnionych). Złożenie listu ochronnego nie będzie w żaden sposób opóźniać rozpoznania wniosku o zabezpieczenie. Jednocześnie projekt przewiduje udostępnienie uprawnionemu odpisu listu ochronnego przed rozpoznaniem wniosku, tak aby zachować zasadę równości stron i kontradyktoryjności postępowania. \\t\\fPoza zakresem nowelizacji. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 69a ustawa z dnia 28 lipca 2005 r. o kosztach sądowych w sprawach cywilnych\\tArt. 69a  1. Od listu ochronnego pobiera się opłatę stałą w kwocie 1000 zł.  2. Połowę opłaty pobiera się od wniosku o przedłużenie obowiązywania listu ochronnego.\\tDodatkowe obowiązki przewodniczącego wydziału i sędziego referenta, związane z uwzględnieniem faktu złożenia listu ochronnego i prowadzenia wykazu listów ochronnych, zostaną zrekompensowane przez opłatę, z którą będzie wiązać się złożenie (1000 zł) i przedłużenie obowiązywania (500 zł) listu ochronnego.  \\tPoza zakresem nowelizacji \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 752a Ustawa z dnia 30 czerwca 2000 r. Prawo własności przemysłowej \\tWERSJA A  Art. 752a.  § 1. Do postępowań wszczętych na podstawie wniosku, o którym mowa w art. 752, nie stosuje się art. 98 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego.  § 2. Prezes Urzędu Patentowego może z urzędu w drodze postanowienia zawiesić postępowanie wszczęte na podstawie wniosku, o którym mowa w art. 752, na czas \\fnie dłuższy niż 90 dni. Łączny czas zawieszenia danego postępowania nie może być dłuższy niż 180 dni.                                       WERSJA B  Art. 752a.  § 1. Do postępowań wszczętych na podstawie wniosku, o którym mowa w art. 752, nie stosuje się art. 98 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego.  § 2. Prezes Urzędu Patentowego może z urzędu w drodze postanowienia zawiesić postępowanie wszczęte na podstawie wniosku, o którym mowa w art. 752, na okres nie dłuższy niż 90 dni.  § 3. Prezes Urzędu Patentowego może zawiesić postępowanie na okres do 90 dni, jeżeli wystąpi o to zgłaszający, jest to uzasadnione ważnym interesem strony oraz nie zagraża to interesowi społecznemu. Art. 101-103 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego stosuje się odpowiednio. § 4. Łączny czas zawieszenia danego postępowania na podstawie § 2 i § 3 nie może być dłuższy niż 180 dni.\\t\\fWERSJA A Dodanie proponowanego przepisu art. 752a ma na celu ograniczenie podstaw do zawieszenia postępowań o udzielenie dodatkowego prawa ochronnego (DPO).  Art. 98 ustawy z dnia 14 czerwca 1960 r. Kodeks postępowania administracyjnego (t.j. Dz. U. z 2021 r. poz. 735 z późn. zm.) daje uprawnienie do zawieszenia postępowania administracyjnego do 3 lat \\fprzez stronę postępowania, na której żądanie postępowanie zostało wszczęte. Dotychczasowa praktyka stosowania tego przepisu w postępowaniach przez Urzędem Patentowym RP dotycząca udzielenia DPO wskazuje, że zawieszanie postępowań może prowadzić do znacznego wydłużenia czasu rozpatrywania wniosków. Celem inicjatywy legislacyjnej jest zapobieganie przewlekłości postępowania, w którym czas rozpatrywania wniosku bywa nawet dłuższy niż okres ochrony udzielonej przez DPO (do 5 lat).  W przypadku postępowań o udzielenie DPO czas rozpatrywania wniosku powinien być krótki, ponieważ w przeciwieństwie do postępowania patentowego, przy rozpatrywaniu wniosku o udzielenie DPO nie dochodzi do merytorycznej oceny tego wniosku, a działanie Urzędu ogranicza się wyłącznie do zbadania jego terminowości, kompletności i prawidłowości. Do nieuzasadnionego przedłużania postępowań o udzielenie DPO dochodzi w wielu przypadkach na skutek nadużywania instytucji zawieszenia postępowania jako sposobu swoistej walki konkurencyjnej. Decyzja o udzieleniu DPO wpływa nie tylko na sferę prawną uprawnionego z patentu, ale również na możliwość skorzystania przez innych producentów z wyjątku wcześniejszej produkcji generycznej. Przedłużające się postępowania w sprawie udzielenia DPO mogą utrudniać skorzystanie przez inne podmioty z uprawnień wynikających z art. 5 ust. 2 lit. b i c Rozporządzenia Parlamentu \\fEuropejskiego i Rady (WE) nr 469/2009 z dnia 6 maja 2009 r. dotyczącego dodatkowego świadectwa ochronnego dla produktów leczniczych. Przepisy Rozporządzenia 469/2009 przewidują odstępstwo od skutków wydania świadectwa w odniesieniu do niektórych działań dotyczących wytwarzania produktów leczniczych, które w przeciwnym razie wymagałyby zgody posiadacza świadectwa. Skorzystanie z wyjątku wcześniejszej produkcji generycznej umożliwia producentom wytwarzanie produktów leczniczych na terytorium Unii Europejskiej celem ich wywozu na rynki państw trzecich i podejmowanie innych działań niezbędnych do takiego wytwarzania lub do samego wywozu produktów. Producenci uzyskują również możliwość wytwarzania i magazynowania produktów leczniczych w państwie członkowskim w okresie 6 miesięcy przed datą wygaśnięcia DPO w celu wejścia na rynek państwa członkowskiego już od pierwszego dnia po wygaśnięciu DPO. Warunkiem skorzystania z powyższego wyjątku jest powiadomienie zarówno uprawnionego, jak i Urzędu o zamiarze skorzystania z ww. uprawnienia. Wydłużony czas rozpatrywania wniosku o udzielenie DPO powoduje, że podmiot zainteresowany skorzystaniem z uprawnień przewidzianych w ww. przepisach Rozporządzenia pozostaje w niepewności prawnej co do terminu, w jakim powinien to uczynić. To z kolei uniemożliwia takiemu podmiotowi zaplanowanie i podjęcie działań \\fpowiązanych w wytwarzaniem przed rozpoczęciem właściwej czynności wytwarzania.  Zważywszy na kreacyjny charakter decyzji Urzędu o udzieleniu dodatkowego prawa ochronnego, należy podjąć środki celem zapewnienia realizacji zasady szybkości postępowania, co pozwoli na zachowanie równowagi pomiędzy interesami wszystkich podmiotów zainteresowanych uprawnieniami wynikającymi z udzielenia DPO.  Przewiduje się, że Prezes Urzędu Patentowego będzie miał uprawnienie aby z urzędu zawiesić takie postępowanie, jednak na czas nie dłuższy niż 90 dni. Zawieszenie postępowania nastąpi w drodze postanowienia. Łączny czas zawieszenia danego postępowania o udzielenie DPO nie będzie mógł być dłuższy niż 180 dni.  WERSJA B  Dodanie proponowanego przepisu w art. 752a PWP ma na celu ograniczenie podstaw do zawieszenia postępowań o udzielenie dodatkowego prawa ochronnego (DPO).  Art. 98 ustawy z dnia 14 czerwca 1960 r. Kodeks postępowania administracyjnego (t.j. Dz. U. z 2021 r. poz. 735 z późn. zm.) daje uprawnienie do zawieszenia postępowania administracyjnego do 3 lat przez stronę postępowania, na której żądanie postępowanie zostało wszczęte. Dotychczasowa praktyka stosowania tego przepisu w postępowaniach przez Urzędem Patentowym RP dotycząca udzielenia DPO wskazuje, że zawieszanie \\fpostępowań może prowadzić do znacznego wydłużenia czasu rozpatrywania wniosków. Celem inicjatywy legislacyjnej jest zapobieganie przewlekłości postępowania, w którym czas rozpatrywania wniosku bywa nawet dłuższy niż okres ochrony udzielonej przez DPO (do 5 lat).  W przypadku postępowań o udzielenie DPO czas rozpatrywania wniosku powinien być krótki, ponieważ w przeciwieństwie do postępowania patentowego, przy rozpatrywaniu wniosku o udzielenie DPO nie dochodzi do merytorycznej oceny tego wniosku, a działanie Urzędu ogranicza się wyłącznie do zbadania jego terminowości, kompletności i prawidłowości.  Do nieuzasadnionego przedłużania postępowań o udzielenie DPO dochodzi w wielu przypadkach na skutek nadużywania instytucji zawieszenia postępowania jako sposobu swoistej walki konkurencyjnej. Decyzja o udzieleniu DPO wpływa nie tylko na sferę prawną uprawnionego z patentu, ale również przez innych producentów, którzy chcą skorzystać z wyjątku wcześniejszej produkcji generycznej.  Przedłużające się postępowania w sprawie udzielenia DPO mogą utrudniać skorzystanie przez inne podmioty z uprawnień wynikających z art. 5 ust. 2 lit. b i c Rozporządzenia Parlamentu Europejskiego i Rady (WE) nr 469/2009 z dnia 6 maja 2009 r. dotyczącego dodatkowego świadectwa ochronnego dla produktów leczniczych. Przepisy Rozporządzenia 469/2009 przewidują odstępstwo od skutków wydania \\fświadectwa w odniesieniu do niektórych działań dotyczących wytwarzania produktów leczniczych, które w przeciwnym razie wymagałyby zgody posiadacza świadectwa. Skorzystanie z wyjątku wcześniejszej produkcji generycznej umożliwia producentom wytwarzanie produktów leczniczych na terytorium Unii Europejskiej celem ich wywozu na rynki państw trzecich i podejmowanie innych działań niezbędnych do takiego wytwarzania lub do samego wywozu produktów. Producenci uzyskują również możliwość wytwarzania i magazynowania produktów leczniczych w państwie członkowskim w okresie 6 miesięcy przed datą wygaśnięcia DPO w celu wejścia na rynek państwa członkowskiego już od pierwszego dnia po wygaśnięciu DPO. Warunkiem skorzystania z powyższego wyjątku jest powiadomienie zarówno uprawnionego, jak i Urzędu o zamiarze skorzystania z ww. uprawnienia. Wydłużony czas rozpatrywania wniosku o udzielenie DPO powoduje, że podmiot zainteresowany skorzystaniem z uprawnień przewidzianych w ww. przepisach Rozporządzenia pozostaje w niepewności prawnej co do terminu, w jakim powinien to uczynić. To z kolei uniemożliwia takiemu podmiotowi zaplanowanie i podjęcie działań powiązanych z wytwarzaniem przed rozpoczęciem właściwej czynności wytwarzania.  Zważywszy na kreacyjny charakter decyzji Urzędu o udzieleniu dodatkowego prawa ochronnego należy \\fpodjąć środki celem zapewnienia realizacji zasady szybkości postępowania, co pozwoli na zachowanie równowagi pomiędzy interesami wszystkich podmiotów zainteresowanych uprawnieniami wynikającymi z udzielenia DPO.  Przewiduje się, że Prezes Urzędu Patentowego będzie miał uprawnienie aby z urzędu zawiesić takie postępowanie, jednak na czas nie dłuższy niż 90 dni. Zawieszenie postępowania nastąpi w drodze postanowienia.  W przypadkach, gdy będzie to uzasadnione ważnym interesem strony oraz nie będzie to zagrażało interesowi społecznemu zgłaszający będzie mógł wystąpić do Prezesa Urzędu Patentowego o zawieszenie postępowania. Łączny czas zawieszenia danego postępowania o udzielenie DPO z urzędu i na wniosek zgłaszającego, nie będzie mógł być dłuższy niż 180 dni. \\t\\fPoza zakresem nowelizacji\\n\\tNaczelna Izba Aptekarska\\tArt. 19 ust. 5c ustawy o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi\\tPo art. 6 dodaje się art. 6a w brzmieniu: „Art. 6a. W ustawie z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (Dz. U. z 2023 r. poz. 1284 i 1938) w art. 19 ust. 5c otrzymuje brzmienie: „5c. W przypadku przeprowadzenia szczepienia na podstawie recepty farmaceutycznej, o której mowa w art. 96 ust. 41 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne, osoba poddana szczepieniu ponosi koszty przeprowadzenia szczepienia, w tym koszt szczepionki, a także koszty badania kwalifikacyjnego wykonanego przez farmaceutę, w całości albo w części, która \\fnie jest finansowana ze środków publicznych.”.”. \\t\\fPropozycja zmiany art. 19 ust. 5c ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, polega na nadaniu mu nowego brzmienia: „5c. W przypadku przeprowadzenia szczepienia na podstawie recepty farmaceutycznej, o której mowa w art. 96 ust. 41 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, osoba poddana szczepieniu ponosi koszty przeprowadzenia szczepienia, w tym koszt szczepionki, a także koszty badania \\fkwalifikacyjnego wykonanego przez farmaceutę, w całości albo w części, która nie jest finansowana ze środków publicznych”. Propozycja opiera się na kilku istotnych przesłankach. Obecne brzmienie przepisu odnosi się wyłącznie do kosztu wydania Międzynarodowej Książeczki Szczepień (art. 19 ust. 7), co nie oddaje rzeczywistej struktury kosztów związanych z przeprowadzeniem szczepienia w aptece. Sama procedura szczepienia obejmuje nie tylko podanie szczepionki, ale także konieczne badanie kwalifikacyjne przeprowadzane przez farmaceutę oraz wartość samej szczepionki, jeżeli nie jest ona finansowana ze środków publicznych. Pozostawienie przepisu w obecnym kształcie stwarza ryzyko niejasności co do tego, kto ponosi faktyczne koszty. Stan ten prowadzi do nieporozumień między pacjentami, farmaceutami oraz Narodowym Funduszem Zdrowia. Uwzględnienie w przepisie kosztów niepokrywanych ze środków publicznych jest zgodne z zasadą przejrzystości finansowej oraz prawidłowego rozliczania świadczeń zdrowotnych. Jeśli szczepienie nie jest finansowane w całości przez NFZ, pacjent powinien mieć świadomość, że ponosi koszt szczepionki oraz \\fkwalifikacji. Obecnie fakt ten nie wynika jasno z ustawy.  Zmiana ta odpowiada na rozwój kompetencji farmaceutów, którzy - zgodnie z ustawą Prawo farmaceutyczne - uzyskali możliwość wystawiania recept farmaceutycznych oraz wykonywania szczepień, w tym kwalifikacji do szczepienia. Badanie kwalifikacyjne jest niezbędnym elementem procedury szczepienia, warunkującym bezpieczeństwo pacjenta, dlatego jego koszt powinien być wprost przewidziany w ustawie. Wprowadzenie jasnej normy, że pacjent ponosi koszt szczepienia w zakresie niepokrywanym ze środków publicznych, zabezpiecza zarówno apteki wykonujące szczepienia, jak i samych pacjentów przed niejasnościami dotyczącymi rozliczeń. Proponowana zmiana porządkuje przepisy w zakresie odpłatności za szczepienia realizowane w aptekach, zwiększa przejrzystość rozliczeń, uwzględnia rzeczywiste elementy kosztowe (szczepionka, badanie kwalifikacyjne, wykonanie szczepienia) oraz dostosowuje ustawę do aktualnego stanu prawnego i praktyki wykonywania szczepień przez farmaceutów w ramach recept farmaceutycznych.\\t\\fPoza zakresem nowelizacji  \\n\\tOsoba fizyczna \\tUstawa o zwodzie farmaceuty\\tPo art. 7 dodaje się art. 7a w brzmieniu: W ustawie z dnia 10 grudnia 2020 r. o zawodzie farmaceuty (Dz. U. z 2021 poz. 97 \\fz późn. zm.) wprowadza się następujące zmiany: 1) w art. 3 pkt 7 otrzymuje brzmienie: „7) usługa farmacji klinicznej - działania na rzecz racjonalnej i optymalnej farmakoterapii realizowane przez farmaceutę w podmiocie wykonującym działalność leczniczą; \\\"                                                          \\f2) w art. 4. ust. 4. uchyla się punkt 6                                                   3) po art. 4. dodaje się art. 4a w brzmieniu: „4a Farmaceuta ma prawo wglądu do dokumentacji medycznej pacjenta w zakresie niezbędnym do sprawowania opieki farmaceutycznej, o której mowa w art. 4 ust. 2 i udzielania usług farmaceutycznych, o których mowa w art. 4 ust. 3\\\"         4) w art. 4 ust. po punkcie 5 dodaje się ust. 2a w brzmieniu: „2a Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, szczegółowe zasady wystawiania recept w ramach kontynuacji zlecenia lekarskiego.\\\" \\t\\fUZASADNIENIE Obecne brzmienie jest następujące: art. 3 pkt 7 usługa farmacji klinicznej – działania na rzecz zwiększenia skuteczności, bezpieczeństwa i \\fzasadności, w tym ekonomicznej, użycia produktów leczniczych oraz wsparcie lekarza prowadzącego leczenie w zakresie farmakoterapii, realizowane przez farmaceutę w podmiocie wykonującym działalność leczniczą na rzecz pacjenta, członków rodziny pacjenta lub personelu medycznego; Zasadne jest wprowadzenie krótkiej, jasnej i precyzyjnej definicji. Aktualna definicja usługi farmacji klinicznej jest niewłaściwa pod względem poprawności redakcyjnej ponieważ zawiera błędne, niewłaściwe i niepotrzebne określenia: „działania na rzecz zwiększenia skuteczności, bezpieczeństwa i zasadności, w tym ekonomicznej, użycia produktów leczniczych\\\" -  błędne określenie ponieważ skuteczność każdego leku została określona na etapie badań klinicznych. Skuteczność leku może być zwiększona na przykład poprzez wprowadzenie nowej postaci (formy) leku lub poprzez wprowadzenie nowej drogi podania. Mogą tego dokonać tylko i wyłącznie producenci leków. „w tym ekonomicznej\\\" - niewłaściwe oraz zbyt szerokie określenie, ponieważ w przypadku leków poprawne nazewnictwo to farmakoekonomika. „wsparcie lekarza prowadzącego leczenie\\\" -  błędne określenie ponieważ zakłada się a priori, że lekarz prowadzący leczenie potrzebuje wsparcia. „członków rodziny pacjenta\\\" – niepotrzebne określenie, ponieważ jest zbyt szerokie: członkowie rodziny pacjenta to krewni w linii prostej tzn. zstępni (dzieci, wnuki, prawnuki) oraz wstępni (rodzice, dziadkowie, pradziadkowie) oraz \\fpowinowaci w linii prostej oraz powinowaci w linii bocznej. Powyższe określenie jest sprzeczne z zasadami RODO, dodatkowo każdy pacjent ma prawo nie wyrazić zgody na przekazywanie jakichkolwiek informacji zawartych w jego dokumentacji medycznej, w tym również informacji na temat farmakoterapii. Ponadto warto wskazać, że należy korzystać z istniejących systemów na zasadzie benchmarkingu. Najczęściej cytowaną definicją farmacji klinicznej jest ta, która została sformułowana przez specjalistów z Amerykańskiego Kolegium Farmacji Klinicznej (ang. American College of Clinical Pharmacy, ACCP), zgodnie z którą „farmacja kliniczna stanowi obszar farmacji zajmujący się nauką i praktyką racjonalnego stosowania leków”. Członkowie Europejskiego Stowarzyszenia Farmacji Klinicznej (ang. European Society of Clinical Pharmacy, ESCP) określili „farmację kliniczną jako czynności i usługi farmaceuty klinicznego mające na celu rozwój i promocję racjonalnego oraz właściwego stosowania produktów leczniczych”.   UZASADNIENIE Obecne brzmienie jest następujące: art. 4. ust. 4. „Zadania zawodowe farmaceuty obejmują: 5) sprawowanie nadzoru nad gospodarką produktami leczniczymi oraz wyrobami medycznymi w podmiocie wykonującym działalność leczniczą; 6) zarządzanie produktami leczniczymi i wyrobami medycznymi w oddziale szpitalnym”. Treść zawarta w punkcie 5) \\fjest zasadna i wystarczająca ponieważ dotyczy sprawowania nadzoru nad gospodarką produktami leczniczymi oraz wyrobami medycznymi w szpitalu. Co do zasady ordynator oddziału zarządza i odpowiada za to jak funkcjonuje cały oddział. Farmaceuta szpitalny nie może zarządzać żadnymi materiałami znajdującymi się w oddziale szpitalnym, ponieważ są to kompetencje ordynatora. Dlatego zarządzanie produktami leczniczymi i wyrobami medycznymi w oddziale szpitalnym przez farmaceutę jest niedopuszczalne. Z tych samych powodów błędem byłoby umieszczenie w ustawie o zawodzie lekarza zapisu, że „zadania zawodowe lekarza obejmują: zarządzanie produktami leczniczymi i wyrobami medycznymi w aptece szpitalnej\\\". Należy podkreślić, że zarządzanie łączy się bezpośrednio z ponoszeniem odpowiedzialności. Ponadto należy wskazać, że Najwyższa Izba Kontroli (NIK) opublikowała raport: „Funkcjonowanie aptek szpitalnych i działów farmacji szpitalnej”. W trakcie kontroli NIK stwierdziła nieprawidłowości w apteczkach oddziałowych. W raporcie znajdują się zarzuty pod adresem farmaceutów szpitalnych, które są kuriozalne, ponieważ wynikają z faktu, że nie ma regulacji prawnych w zakresie odpowiedzialności za obrót lekami w apteczkach oddziałowych.    UZASADNIENIE \\fUstawa z dnia 17 sierpnia 2023 r. o niektórych zawodach medycznych nadała prawo wglądu do dokumentacji medycznej pacjenta piętnastu zawodom medycznym. Jednym z tych zawodów jest technik farmaceutyczny. Fakt, że technik farmaceutyczny posiada uprawnienie, którego nie posiada farmaceuta jest dużą nieprawidłowością.     UZASADNIENIE W 2024 roku w Polsce wystawiono około 521 milionów recept. Widomo, że około 25 procent wizyt stanowią tzw. wizyty receptowe w celu wystawienia kolejnych recept na te same leki w ramach kontynuacji terapii chorób przewlekłych. Docelowo farmaceuci mogliby rocznie wystawiać około 130 milionów recept w ramach kontynuacji zlecenia lekarskiego, co niewątpliwie spowodowałoby skrócenie kolejek do lekarzy w POZ i w AOS.\\t\\fPoza zakresem nowelizacji.  \\n\\tNaczelna Izba Aptekarska\\tUstawy o zwodzie farmaceuty\\tPo art. 6a dodaje się art.  6b w brzmieniu: „Art. 6b. W ustawie z dnia 10 grudnia 2020 r. o zawodzie farmaceuty (Dz. U. z 2024 r. poz. 676)  w art. 4 w ust. 1 w pkt 4 na końcu kropkę zastępuje się średnikiem i dodaje się pkt 5 w brzmieniu: „5) przeprowadzaniu szczepień ochronnych oraz wystawianiu recept na produkty immunologiczne niezbędne do przeprowadzenia zalecanych szczepień ochronnych,\\nw rozumieniu przepisów ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (Dz. U. z 2023 r. poz. 1284, z późn. zm.), a także udzielaniu innych świadczeń zdrowotnych w przypadkach określonych w przepisach odrębnych regulujących zasady ich wykonywania.”;  po art. 28 dodaje się art. 28a w brzmieniu: „Art. 28a. 1. Farmaceuta ma prawo wglądu do dokumentacji medycznej pacjenta oraz do uzyskania od podmiotu udzielającego świadczeń zdrowotnych pełnej informacji w rozumieniu przepisów ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2022 r. poz. 1876, 2280 i 2705 oraz z 2023 r. poz. 605) o stanie zdrowia pacjenta, rozpoznaniu, proponowanych metodach diagnostycznych, leczniczych, rehabilitacyjnych, zapobiegawczych i dających się przewidzieć następstwach podejmowanych działań, w zakresie \\fniezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę. 2. Farmaceuta ma prawo dostępu do danych dotyczących pacjenta przetwarzanych w Internetowym Koncie Pacjenta, o którym mowa w art. 2 pkt 19 ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia (Dz.U. z 2023 r. poz. 2465, z późn. zm.), w zakresie niezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę.”. po art. 31 dodaje się art. 31a w brzmieniu: „Art. 31a.  1.\\tFarmaceuta ma prawo do samodzielnego wystawienia recepty na produkt immunologiczny niezbędny do przeprowadzenia zalecanego szczepienia ochronnego\\nw rozumieniu art. 19 ust. 1 ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi.  2.\\tUprawnienie, o którym mowa w ust. 1, obejmuje również wystawianie recept osobom, o których mowa w art. 43, 43a i art. 44-46 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, na zasadach określonych w tej ustawie oraz w ustawie z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych (Dz. U. z 2022 r. poz. 463, 583 i 974), zwanej dalej „ustawą o refundacji”; 3.\\tFarmaceuta wystawia receptę na zasadach określonych w art. 95b, art. 96a i \\fart. 96b ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne. 4.\\tW przypadku wystawiania recept na produkt immunologiczny określony w wykazach, o którym mowa w art. 37 ustawy o refundacji, farmaceuta jest obowiązany do odnotowania na recepcie odpłatności, jeżeli produkt występuje w tych wykazach w co najmniej dwóch odpłatnościach, o których mowa w art. 6 ust. 2 ustawy o refundacji. 5.\\tOkreślenie odpłatności na recepcie w postaci elektronicznej może nastąpić przy wykorzystaniu narzędzia informatycznego, o którym mowa w art. 9b ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia (Dz. U. z 2022 r. poz. 1555). 6.\\tFarmaceuta oraz świadczeniodawca lub apteka nie ponoszą odpowiedzialności za skutki błędnego działania narzędzia informatycznego, o którym mowa w art. 9b ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia, polegającego na nieprawidłowym określeniu odpłatności w związku z rozbieżnością danych zawartych w narzędziu a przepisami prawa, w szczególności z wykazami, o których mowa w art. 37 ust. 1 ustawy o refundacji.”.\\t\\fProjektowana zmiana w art. 4 ust. 1 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty polega na dodaniu nowej kategorii czynności objętych pojęciem „wykonywania zawodu farmaceuty”. Obok sprawowania opieki farmaceutycznej, udzielania usług farmaceutycznych, wykonywania zadań zawodowych, wykonywaniu czynności, o których mowa w art. 4 ust. 5, wykonywanie zawodu farmaceuty polegać będzie na przeprowadzaniu szczepień ochronnych oraz wystawianiu recept na produkty immunologiczne niezbędne do przeprowadzenia zalecanych szczepień ochronnych, w rozumieniu przepisów ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (Dz. U. z 2023 r. poz. 1284, z późn. zm.), a także udzielaniu innych świadczeń zdrowotnych w przypadkach określonych w przepisach odrębnych regulujących zasady ich wykonywania. Dodanie nowego przepisu art. 28a gwarantować będzie farmaceutom prawo wglądu do dokumentacji medycznej pacjenta oraz prawo do uzyskania od podmiotu udzielającego świadczeń zdrowotnych pełnej informacji w rozumieniu przepisów ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta, o stanie zdrowia pacjenta, rozpoznaniu, proponowanych metodach \\fdiagnostycznych, leczniczych, rehabilitacyjnych, zapobiegawczych i dających się przewidzieć następstwach podejmowanych działań, w zakresie niezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę. Ponadto, projekt w dodawanym art. 28a ust. 2 przewiduje prawo dostępu farmaceuty do danych dotyczących pacjenta przetwarzanych w Internetowym Koncie Pacjenta, o którym mowa w art. 2 pkt 19 ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia (Dz.U. z 2023 r. poz. 2465, z późn. zm.), w zakresie niezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę. Obie zmiany uzasadnione są tymi sami okolicznościami, które przemawiają za zapewnieniem farmaceucie dostępu do danych osobowych lub jednostkowych danych medycznych usługobiorców, przetwarzanych w systemie teleinformatycznym usługodawcy lub w SIM. Projektowane dodanie art. 31a oznacza przyznanie farmaceucie prawa do samodzielnego wystawienia recepty na produkt immunologiczny niezbędny do przeprowadzenia zalecanego szczepienia ochronnego w rozumieniu art. 19 ust. 1 ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi. Uprawnienie to obejmować będzie \\frównież wystawianie recept osobomF i art. 44-46 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, na zasadach określonych w tej ustawie oraz w ustawie z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych. Farmaceuta zobowiązany będzie do wystawiania recept na zasadach określonych w art. 95b, art. 96a i art. 96b ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne. W przypadku wystawiania recept na produkt immunologiczny określony w wykazach, o którym mowa w art. 37 ustawy o refundacji, farmaceuta obowiązany będzie do odnotowania na recepcie odpłatności, jeżeli produkt występuje w tych wykazach w co najmniej dwóch odpłatnościach, o których mowa w art. 6 ust. 2 ustawy o refundacji. Określenie odpłatności na recepcie w postaci elektronicznej może nastąpić przy wykorzystaniu narzędzia informatycznego, o którym mowa w art. 9b ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia. Zmiana ta uzupełnia zmianę z art. 96 ust. 41 Pr. farm. która przewiduje, że recepta farmaceutyczna może być wystawiona na produkt immunologiczny niezbędny do przeprowadzania w aptece zalecanego szczepienia ochronnego w \\frozumieniu art. 19 ust. 1 ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi. Recepta farmaceutyczna stanowi podstawę zastosowania produktu leczniczego wyłącznie w aptece ogólnodostępnej, w której farmaceuta wystawił tę receptę. Regulacja ta dotyczy wyłącznie farmaceutów, którzy wykonują zawód w aptece. Należy podkreślić, że zgodnie z art. 19 ust. 5a pkt 2 i ust. 5b pkt 1 ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, uprawnienie farmaceuty do przeprowadzenia badaniem kwalifikacyjnym w celu wykluczenia przeciwwskazań do wykonania tego szczepienia oraz wykonania zalecanego szczepienia ochronnego oraz szczepienia przeciw COVID-19 nie jest ograniczone wyłącznie do szczepień w aptekach.  Zgodnie z art.  36 ust. 1 ustawy o zawodzie farmaceuty, zawód farmaceuty wykonuje się: \\t1)\\tw ramach stosunku pracy w rozumieniu ustawy z dnia 26 czerwca 1974 r. - Kodeks pracy; \\t2)\\tna podstawie umowy cywilnoprawnej zgodnie z ustawą z dnia 23 kwietnia 1964 r. - Kodeks cywilny; \\t3)\\tw ramach wolontariatu zgodnie z ustawą z dnia 24 kwietnia 2003 \\fr. o działalności pożytku publicznego i o wolontariacie; \\t4)\\tw formie jednoosobowej działalności gospodarczej zgodnie z ustawą z dnia 6 marca 2018 r. - Prawo przedsiębiorców (Dz. U. z 2024 r. poz. 236); \\t5)\\tjako wspólnik spółki jawnej lub wspólnik (partner) spółki partnerskiej, której przedmiotem działalności jest prowadzenie apteki zgodnie z ustawą z dnia 15 września 2000 r. - Kodeks spółek handlowych; \\t6)\\tw ramach stosunku służbowego zgodnie z ustawą z dnia 11 marca 2022 r. o obronie Ojczyzny lub ustawą z dnia 9 kwietnia 2010 r. o Służbie Więziennej. Projekt ustawy umożliwiający farmaceutom wystawianie recept na produkty immunologiczne znacząco przyczyni się do poprawy dostępności i efektywności szczepień ochronnych, co jest kluczowe dla zdrowia publicznego i prewencji chorób zakaźnych. Zgodnie z art. 19 ust. 1 ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi, szczepienia ochronne są kluczowym elementem strategii zapobiegania chorobom zakaźnym. Umożliwienie farmaceutom wystawiania recept na produkty immunologiczne jest logicznym krokiem w realizacji tego celu, pozwalając na bardziej elastyczne i \\fdostępne systemy szczepień. Farmaceuci mają bardzo szeroki dostęp do pacjentów i mogą skutecznie zwiększyć dostępność szczepień, zwłaszcza w regionach z ograniczoną liczbą lekarzy. Umożliwienie farmaceutom wystawiania recept na produkty immunologiczne przyspiesza proces szczepień. Ułatwienie farmaceutom wystawiania recept na szczepionki redukuje liczbę wizyt pacjentów u lekarzy tylko po to, aby otrzymać receptę, co z kolei skraca czas oczekiwania na szczepienie. Przekazanie farmaceutom uprawnień do wystawiania recept na produkty immunologiczne odciąża lekarzy, którzy mogą skupić się na bardziej skomplikowanych przypadkach medycznych. To efektywniejsze wykorzystanie zasobów medycznych. Farmaceuci są wysoko wykwalifikowanymi specjalistami w dziedzinie farmakologii i szczepień. Ich zaangażowanie w proces szczepień zwiększa zaufanie pacjentów do programów szczepień i ogólnie poprawia ich stan zdrowia. Zwiększenie liczby szczepień przez farmaceutów przyczyni się do wyższego poziomu immunizacji w społeczeństwie, co z kolei zmniejsza ryzyko wybuchu epidemii i odciąża system opieki zdrowotnej. Równocześnie, projekt przewiduje normę, zgodnie z którą farmaceuta oraz świadczeniodawca lub apteka nie ponoszą odpowiedzialności za skutki \\fbłędnego działania narzędzia informatycznego, o którym mowa w art. 9b ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia, polegającego na nieprawidłowym określeniu odpłatności w związku z rozbieżnością danych zawartych w narzędziu a przepisami prawa, w szczególności z wykazami, o których mowa w art. 37 ust. 1 ustawy o refundacji.\\t\\fPoza zakresem nowelizacji                      \\n\\tPrzedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tdodanie do projektu art. 2 pkt 22 zmieniającego art. 133a ust. Prawo Farmaceutyczne\\t Art. 133a. 1. Kto nie powiadamia Prezesa Urzędu o tymczasowym lub stałym wstrzymaniu obrotu produktem leczniczym, w terminie określonym o którym mowa w art. 24 ust. 3 pkt 4 albo art. 36g ust. 1 pkt 15, podlega karze pieniężnej w wysokości do 500 000 zł.  \\tZgodnie z przyjętym kierunkiem zmian o charakterze deregulacyjnym, poprzez analogię do wszystkich pozostałych przepisów sankcyjnych (art. 127b, 127ba, 127c, 127ca, 127cb, 127cc, 127cd, 127da, 129b, 129bb, 129c, 129d, 129e i 132d), proponuje się wprowadzenie miarkowania kar za niepowiadomienie o tymczasowym lub stałym wstrzymaniu obrotu produktem leczniczym oraz usunięcie przesłanki czasowej (brak zgodności z zapisami dyrektywy), zwłaszcza, że nie ma możliwości dokładnego przewidzenia momentu wystąpienia braku produktu na rynku, na co mają często wpływ czynniki zewnętrzne, niezależne od podmiotu odpowiedzialnego, takie jak: brak dostępności odpowiedników, nagły wzrost zapotrzebowania, sytuacje kryzysowe itp. Zgodnie z art. 23a DYREKTYWY 2001/83/WE PARLAMENTU EUROPEJSKIEGO I RADY, „posiadający pozwolenie na dopuszczenie do obrotu również powiadamia właściwe władze o przypadku tymczasowego albo stałego wstrzymania wprowadzania produktu do obrotu Państwa Członkowskiego. \\fTakiego powiadomienia, z zastrzeżeniem wyjątkowych okoliczności, posiadający pozwolenie dokonuje w terminie nie dłuższym niż 2 miesiące od dnia zaprzestania wprowadzania produktu do obrotu.”. Obecna wysokość kary – 500 000 PLN, bez możliwości jej miarkowania jest nieproporcjonalna do wielu niezależnych od podmiotu odpowiedzialnego sytuacji, które zawsze powinny być oceniane indywidualnie.\\t\\fUwaga niezasadna  Propozycja w zaproponowanym brzmieniu nie może liczyć na uwzględnienie. Wysokość kary jest adekwatna do skali naruszenia prawa. Ponadto Wnoszący nie wskazał żadnych okoliczności, w oparciu, o które miałoby następować miarkowanie wysokości kary pieniężnej.\\n\\tAffordable Medicines Europe\\t„punkt 7 wniosku” dot art. 24 ust. 2 pkt 1 ust ref?\\tWymaganie: Tłumaczenia przysięgłe na język polski dokumentów potwierdzających informacje o produkcie leczniczym, obowiązujących w momencie składania wniosku, we wszystkich krajach UE i EFTA. Dokumenty te powinny zawierać szczegóły dotyczące poziomu refundacji, warunków oraz wszelkich ograniczeń. Powinny także określać, czy istnieją umowy dotyczące podziału ryzyka lub potwierdzić, że takie ograniczenia nie istnieją.\\tUważamy, że punkt 7 wniosku o refundację nie jest zgodny z polską ustawą o refundacji, ponieważ art. 30 zwalnia już importerów równoległych z obowiązku przekazywania informacji wymaganych w art. 24 ust. 2 pkt 1. W związku z tym oczekujemy zmiany wniosku o refundację dla podmiotów prowadzących handel równoległy, która wykluczy punkt 7.\\tUwaga niezasadna Art. 24 ust 2 pkt 1 ustawy o refundacji jest wyłączony w stosunku do importerów równoległych na podstawie art. 30 ust. 1 ustawy o refundacji już obecnie. Natomiast projekt rozszerza przedmiotowe wyłączenie dodatkowo o art. 24 ust. 2 pkt 1a ustawy o refundacji.\\n\\tAffordable Medicines Europe\\t„punkt 9 wniosku” dot. art. 25 pkt 3, art. 25 pkt 3, art. 25b ust. 1 ust. ref\\tDowód dostępności na rynku w momencie składania wniosku\\tWnioskujemy o wprowadzenie zwolnienia z punktu 9 ram refundacyjnych dla podmiotów zajmujących się handlem równoległym. Biorąc pod uwagę fakt, że podmioty zajmujące się handlem równoległym nie są posiadaczami pozwolenia na dopuszczenie do obrotu ani oryginalnymi producentami leków, nie jesteśmy w stanie przedstawić tradycyjnego dowodu dostępności na rynku w momencie składania wniosku.\\tUwaga niezasadna  W nowelizacji zaproponowano zmianę w zakresie przedstawienia dowodu dostępności, która po konsultacjach publicznych uległa dalszym liberalizującym zmianom, obecnie brzmi następująco: „dowód dostępności w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11, a w przypadku produktu leczniczego terapii zaawansowanej – zobowiązanie do zapewnienia gotowości technologicznej do jego wytworzenia na dzień składania wniosku”. \\fCo więcej, dowód dostępności nie jest pozwoleniem na dopuszczenie do obrotu, a np. fakturą zakupu.\\f.\\tAffordable Medicines Europe\\t„punkt 11 i12 wniosku” art. 25 pkt 14 lit. d,  art. 25a pkt 14 lit. d, art. 26 pkt. 1 lit. g, art. 26 pkt. 2 lit. g, art. 28 pkt. 7 lit. c,\\tSzczegóły dotyczące badań naukowych przeprowadzonych przez wnioskodawcę oraz inwestycji w opiekę zdrowotną w Polsce i innych krajach UE lub EFTA.\\tPonieważ art. 30 wyłącza importerów równoległych z obowiązku przekazywania informacji na podstawie art. 25 pkt 14, zwracamy się z wnioskiem o usunięcie punktów 11 i 12 z wniosku refundacyjnego, które zwolniłyby podmioty prowadzące handel równoległy z wymogu podawania szczegółowych informacji na temat naszych badań naukowych i inwestycji w opiekę zdrowotną w Polsce i innych krajach UE lub EFTA. W związku z powyższym, ponownie zwracamy się z uprzejmą prośbą o rewizję ram refundacyjnych, tak aby były one faktycznie dostosowane do wymogów i zwolnień zakotwiczonych w ustawie refundacyjnej.\\tUwaga niezasadna Kompleksowa analiza przepisów przedstawionych przez wnoszącego uwagę, nie uzasadnia w ocenie MZ konieczności wprowadzania tych zmian. „Punkt 11 i 12” wniosku, o którym mowa w art. 24 ust. 1 ustawy o refundacji, stanowi jego integralną część i dotyczy wszystkich Wnioskodawców. Ich brak skutkowałby niepełnym obrazem sytuacji i utrudniał podjęcie decyzji o objęciu refundacją. Wymagania, o których mowa w art. 24 ust. 2 pkt 1 i 1a, art. 25 pkt 12 i 13 oraz 14 lit. d, art. 26 pkt 1 lit. g oraz pkt 2 lit. g, art. 28 pkt 7 lit. c ustawy o refundacji, nie dotyczą wniosku składanego przez wnioskodawcę będącego importerem równoległym, dlatego w obowiązującym formularzu wniosku wystarczy w polach 11 i 12 wskazać „nie dotyczy”. Jest to obecnie funkcjonująca praktyka w przypadku wyłączeń wynikających z art. 30 ustawy o refundacji.\\n\\tAffordable Medicines Europe\\tOgólna\\tTraktowanie produktów z importu równoległego jako leków generycznych jest szczególnie szkodliwe dla potencjału handlu równoległego w Polsce. Aby leki z importu równoległego kwalifikowały się do refundacji przez Narodowy Fundusz Zdrowia (NFZ), ich cena musi być o 25% niższa od ceny referencyjnej leku oryginalnego w Polsce. Jeśli różnica w cenie jest niższa niż próg 25%, import równoległy nie może być refundowany, nawet jeśli jest \\fchemicznie identyczny z produktem oryginalnym. Mimo, że produkty z importu równoległego są odpowiednikami produktów referencyjnych, które są oferowane przez producenta po wyższej cenie, są one traktowane jako leki generyczne. Skutkuje to nieuzasadnionymi ekonomicznie decyzjami, gdy płatnik publiczny rezygnuje z oszczędności poniżej 25% ceny referencyjnych produktów leczniczych, a droższe terapie są dostarczane przez producentów farmaceutycznych w Polsce zamiast tych tańszych dostarczanych przez importerów równoległych. Co więcej, traktowanie leków w obrocie równoległym jako leków generycznych i narzucanie obowiązkowego 25% rabatu jest wysoce nietypowe w Europie. Większość krajów nie wymaga stałej zniżki, ale po prostu oczekuje, że ceny leków z importu równoległego będą niższe od cen produktów referencyjnych. Tylko dwa  kraje w Europie wymagają określonego rabatu. Aby uzyskać refundację, Francja wymaga, aby leki z importu równoległego były o 5% tańsze niż leki referencyjne, podczas gdy Włochy wymagają 7% zniżki na wysoce innowacyjne i szpitalne leki. Dlatego zasada 25% w Polsce jest nie tylko wyjątkowo wysoka, ale także rażąco nieproporcjonalna w porównaniu z innymi krajami. Chcielibyśmy jeszcze raz zaznaczyć, że produkty z importu równoległego i dystrybucji równoległej są prawnie powiązane z konkretnym produktem referencyjnym. W związku z tym, dla wszystkich celów, w tym refundacji, produkt referencyjny jest punktem wyjścia \\fdla sposobu, w jaki produkt z importu równoległego powinien być rozpatrywany. Skuteczny dostęp produktów z importu równoległego do rynku jest nieodłącznie związany z produktem referencyjnym - czyli produktem, dla którego ma on bezpośrednio konkurować. Komisja Europejska wielokrotnie podkreślała, że nie ma różnicy między lekami importowanymi bezpośrednio lub produkowanymi w państwie członkowskim a lekami importowanymi równolegle2. Niedawno Komisja opublikowała zaktualizowany „Przewodnik dotyczący art. 34-36 Traktatu o funkcjonowaniu Unii Europejskiej (TFUE)”, który ma na celu wzmocnienie spójnego stosowania zasady swobodnego przepływu towarów na rynku wewnętrznym, pomagając usunąć wszelkie pozostałe przeszkody i zapobiegając powstawaniu nowych3. Sekcja 4.11 Przewodnika wyraźnie stwierdza, że „określenie produktów podlegających zwrotowi i tych, które są wykluczone, nie może wiązać się z dyskryminacją w odniesieniu do pochodzenia produktów i musi być przeprowadzane na podstawie obiektywnych i weryfikowalnych kryteriów”. Zgodnie z rozumowaniem Komisji, nie ma podstaw prawnych do traktowania leku z importu równoległego inaczej niż produktu referencyjnego objętego krajowym pozwoleniem na import/notyfikacją EMA - również w odniesieniu do refundacji. W tym zakresie polskie przepisy są sprzeczne z art. 34 TFUE i nie ma uzasadnienia, które tłumaczyłoby, że obecne przepisy są konieczne i proporcjonalne zgodnie z art. \\f36 TFUE. równoległy / notyfikacji EEMA zgodnie z prawodawstwem UE.\\t\\fImport równoległy powinien być zatem traktowany nie jako nowy produkt generyczny, ale raczej jako produkt referencyjny w krajowym pozwoleniu na import równoległy / notyfikacji EEMA zgodnie z prawodawstwem UE \\tUwaga niezasadna Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia \\fpełnego katalogu wymogów ustawowych przewidzianych dla refundacji. Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu.\\n\\tJKK ds. gastroenterologii\\togólne\\tChciałbym przekazać uwagi z punktu widzenia lekarzy uczestniczących w leczeniu chorych na nieswoiste choroby zapalne jelit (wrzodziejące zapalenie jelita grubego i choroba Lesniowskiego-Crohna) w ramach programów lekowych B55 i B32.  Główne problemy w prowadzeniu leczenia tej grupy chorych to:  a) leczenie to odbywa się praktycznie tylko w wielkomiejskich ośrodkach (czyli z dala od miejsca zamieszkania dużej części pacjentów)  b) zaledwie kilka ośrodków leczy bardzo duże grupy chorych i stały się one przez to kompletnie niewydolne (brak personelu, duże obciążenie istniejącego personelu – grożące utrata jakości). Jednocześnie NFZ kontraktuje nowych świadczeniodawców niechętnie i z opóźnieniem.  c) wycena świadczeń jest nieopłacalna dla świadczeniodawców, dlatego dyrektorzy szpitali bardzo niechętnie akceptują potrzebę uruchamiania możliwości tego leczenia (nieadekwatna wycena świadczeń, limitowanie świadczeń, brak/opóźnione płatności za nadwykonania) d) duże obciążenie administracyjne dla personelu polegające na konieczności prowadzenia SMPT – co polega na DUBLOWANIU istniejącej już dokumentacji medycznej ( uwaga – nie da się skopiować automatycznie tylko trzeba dane „wklepywać” ręcznie, trudno uwierzyć ale tak jest) e) jednocześnie brak dostępu do danych z SMPT tak aby móc ocenić skuteczność poszczególnych terapii – nawet konsultant krajowy ma utrudniony dostęp do indywidualnych danych bo \\fwedług NFZ istnieje „groźba” (kuriozalna, moim zdaniem) – identyfikacji pacjenta (cytat z pisma od NFZ, naprawdę – dysponuje kopią) przez osobę, które chciałaby przeanalizować wyniki leczenia na dużej grupie chorych a dane zagregowane, które może wydać NFZ nie mają żadnej wartości Cześć z powyższych problemów rzeczywiście mogłoby rozwiązać wprowadzenie czwartej kategorii dostępności. I tutaj popieram pomysł, który jednak w szczegółach powinien uwzględniać następujące elementy (a nie wiem czy uwzględnia, szczególnie ich rozwiązanie):  kolejki do poradni gastroenterologicznych (AOS) są bardzo długie - sięgają 1,5 roku, nie wiem czy przy istniejącym obciążeniu codzienną pracą – poradnie będą w stanie podjąć nowe obowiązki. Życie pokaże, ale wątpię aby się to udało – obym się pomylił.  Poradnie funkcjonują głównie przy szpitalach ( a wiec personel przygotowany do leczenia biologicznego znajdujący się w szpitalach mógłby teoretycznie zająć się tymi pacjentami w AOS), ale wtedy zakładając mniejszą wycenę w AOS – może to być bariera dla uzyskania zgody dyrekcji szpitali.  W Poradniach (AOS) poza-szpitalnych może być kłopot z pozyskaniem lekarzy gastroenterologów doświadczonych w leczeniu zaawansowanym  Bardzo potrzebna (dla rozładowania przeciążenia aktualnych zespołów leczących obie choroby) byłaby możliwość przekazania do AOS pacjenta w stabilnej remisji od np. pół roku, którego leczenie podtrzymujące mógłby prowadzić lekarz w AOS, współpracujący z oddziałem \\fgastroenterologicznym prowadzącym leczenie. Potrzebne jest jednak wytworzenie kanałów komunikacji./ szkoleń/ spotkań typu MDT – takich jak w onkologii. Taki zamysł ma projekt tzw opieki koordynowanej w chorobach zapalnych jelita, który jednak jeszcze nie wszedł w życie.  Dodatkowo, i to jest bardzo ważne, jeśli pacjent ma mieć KONTYUNOWANĄ terapię w AOS, która doprowadziła do remisji – to konieczne jest aby te same leki były dostępne zarówno w programach lekowych jak i w AOS. Mogłyby to być leki z grupy „generycznych-biopodobnych” i wtedy powinny być dostępne w trybach. Inaczej pacjent przechodząc do AOS będzie musiał zmienić lek – co grozi zaostrzeniem.  Pacjenci z tymi dwiema chorobami (szczególnie z chorobą Leśniowskiego- Crohna) mogą wymagać pilnej interwencji szpitalnej w oddziale gastroenterologicznym. Konieczne więc są ustrukturyzowane kanały  komunikacji i wspólnej opieki (znowu program opieki koordynowanej). W Szwecji – pacjenci leczeni w ramach opieki ambulatoryjnej – raz do roku maja dostęp do lekarzy z wyższego poziomu referencyjności . Może u nas tez by to mogło być wprowadzone. Pacjenci czuliby się bezpieczni i nie mieliby poczucia odrzucenia przez ośrodki specjalistyczne.   \\t\\f-\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej \\n\\tZwiązek Pracodawców Polska Dystrybucja Farmaceutyczna\\tDodanie do Projektu w art. 1 ust. 1 litery g) zmieniającej \\fdefinicję „ceny zbytu netto”.\\t\\fProponowane jest wprowadzenie zasady, że cenę zbytu netto stosuje nie tylko wnioskodawca, ale także przedsiębiorca \\fprowadzący obrót hurtowy z grupy kapitałowej wnioskodawcy: „art. 2 6) cena zbytu netto - cenę sprzedaży leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego przez wnioskodawcę lub przedsiębiorcę prowadzącego obrót hurtowy w rozumieniu ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne będącego członkiem grupy kapitałowej, w rozumieniu przepisów o ochronie konkurencji i konsumentów, do której należy wnioskodawca, podmiotom uprawnionym, nieuwzględniającą należnego podatku od towarów i usług”\\t\\fCelem proponowanej zmiany jest rozszerzenie stosowania ceny zbytu netto na hurtownię farmaceutyczną \\fnależącą do tej samej grupy kapitałowej co wnioskodawca. Obecnie obowiązujące przepisy przewidują, że cena zbytu netto może być stosowana wyłącznie przez wnioskodawcę. W obowiązującym stanie prawnym, tzw. hurtownia producencka nabywa produkt leczniczy po cenie urzędowej i może, zgodnie z ustawą, skonsumować część marży hurtowej przed sprzedażą produktów do hurtowni niezwiązanych z producentem. W rezultacie: a)hurtownie spoza grupy kapitałowej producenta często nie mają dostępu do produktów w cenie urzędowej netto, b)hurtownicy, którzy faktycznie realizują transport i logistykę dla produktów, dysponują uszczuploną marżą hurtową poniżej ustawowych 6% bowiem część z tej marży zatrzymują hurtownie z grupy kapitałowej producentów, c) istnieją wątpliwości interpretacyjne czy hurtownia farmaceutyczna wewnątrz grupy kapitałowej producenta powinna stosować urzędową cenę zbytu, czy też cenę hurtową. Standardowo tzw. hurtownie producenckie stosują cenę hurtową (urzędowa cena zbytu jest zwykle stosowana przy pierwszej transakcji w Polsce – a zatem gdy hurtownia producencka nabywa lek od podmiotu ze swojej grupy kapitałowej), więc by wykazać jakikolwiek uzasadniony zysk, zatrzymują część z marży hurtowej, d) z tego powodu część marży hurtowej zostaje „wchłonięta” przez tzw. hurtownię producencką, mimo że hurtownia z grupy kapitałowej podmiotu \\fodpowiedzialnego zazwyczaj nie ponosi realnych kosztów fizycznej dystrybucji leków do aptek i szpitali. Członkowie PLDF przygotowali zestawienie danych dotyczących zatrzymywanej części marży hurtowej przez hurtownie z grupy kapitałowej producentów dla produktów refundowanych za 2022 r. (a więc przed podwyżką marży hurtowej do 6%) oraz za 2024 r. (a więc po podwyżce wynikającej z DNUR). Tylko wśród wybranych członków PLDF wartość marży zatrzymanej na poziomie hurtowni producenckich wyniosła odpowiednio 2022 r.: 14 621 096 zł 2024 r.: 26 991 155 zł Powyższe dane wskazują jednoznacznie, że hurtownie należące do grup kapitałowych producentów leków zatrzymują istotną część marży hurtowej. Co istotne z naszych danych wynika, że sytuacja ta w chwili obecnej dotyczy nawet 90 podmiotów producenckich. Co więcej, zestawienie danych za rok 2022 oraz 2024 pokazuje, że sam wzrost procentowy wartości marży hurtowej na poziomie ustawowym nie jest wystarczający, bowiem proporcjonalnie większą część marży zatrzymują u siebie hurtownie z grupy kapitałowej producenta. Wewnętrzne analizy PLDF pokazują, że szczególnie hurtownie z grup kapitałowych zagranicznych producentów przejmują część marży hurtowej dla siebie, gdy tymczasem hurtownie należące do polskich producentów najczęściej pozostawiają \\fcałą marżę hurtową faktycznym dystrybutorom. W konsekwencji, obecne regulacje nie realizują w pełni celu ustawodawcy, jakim jest urentownienie dystrybucji leków refundowanych przez hurtownie farmaceutyczne. Proponowana zmiana wprowadza możliwość stosowania ceny zbytu netto na etapie sprzedaży z hurtowni producenckiej, co pozwoli: a) zapewnić całą marżę hurtową dla dystrybutorów, którzy faktycznie realizują fizyczną dystrybucję, co pozytywnie wpłynie na jakość i stabilność dostaw, b) usprawnić strukturę finansową i podatkową grup kapitałowych podmiotów odpowiedzialnych bez wpływu na końcową cenę dla pacjenta lub płatnika publicznego, c) zwiększyć transparentność kosztową i funkcjonalną całego łańcucha dostaw leków refundowanych. Rozwiązanie to nie zmienia mechanizmu ustalania ceny urzędowej, ani nie wpływa na wysokość dopłaty ze środków publicznych, a jedynie optymalizuje przepływ handlowy i księgowy i zapewnia lepszą realizację zamierzeń ustawodawcy (właściwe przypisanie marży hurtowej).\\t\\fUwaga niezasadne Rozwiązanie wiąże się z nadmiernym komplikowaniem systemu obrotu produktami refundowanymi i koniecznością każdorazowej weryfikacji, \\fczy dana hurtownia należy do tej samej grupy kapitałowej co wnioskodawca.\\n\\tPolskie Towarzystwo Farmakoekonomiczne\\tArt. 39 ust. 1b UR  \\tKwestie związane z refundacją ex-post w przypadku dostępu do technologii lekowych (Art. 39 ust. 1b UR ) wymagają ponownego rozważenia, aby nie ograniczać praw pacjentów w stanach nagłych.  \\tProponujemy wykreślenie tego zapisu. Z uwagi na to, że postępowania o refundację dla indywidualnych pacjentów są długie, następuje wydłużenie czasu w jakim zapada decyzja o objęciu leku finansowaniem z środków publicznych. W przypadku wprowadzenia zakazu refundacji ex post \\fbyłoby to jednoznaczne z opóźnieniem możliwości otrzymania leku przez pacjenta, co biorąc pod uwagę specyfikę tych chorób, może przesądzać o życiu pacjenta.  • Sądy wielokrotnie potwierdzały, że pacjent, który podjął natychmiastowe działania ratujące zdrowie i życie, nie powinien tracić prawa do refundacji. Przepis ten stoi w sprzeczności z art. 68 Konstytucji RP gwarantującym prawo do ochrony zdrowia. \\t\\fUwaga niezasadna Przyjęcie rozwiązania polegającego na możliwości uzyskiwania refundacji po odbiorze leku z apteki rodzi problem szczególności w przypadku, gdy decyzja na refundacje jest odmowna. Ponadto taki zapis byłby problematyczny do realizacji ze względu na dokument \\frealizacji recepty oraz ze względu na realizacje zapotrzebowania i naliczanie marż. Ponadto przywołać należy art. 15 ust. 2 pkt 17 i 18 ustawy o świadczeniach, który wskazuje, iż w przypadku leków i środków spożywczych specjalnego przeznaczenia żywieniowego sprowadzanych w ramach importu docelowego świadczenie gwarantowane przysługuje świadczeniobiorcy pod warunkiem wydania decyzji przez Ministra Zdrowia. Podsumowując proponowany przepis stanowi odzwierciedlenie istniejących rozwiązań prawnych przyjętych w ustawie o świadczeniach i ma na celu doprecyzowanie wątpliwości interpretacyjnych związanych z regulacją materii świadczeń gwarantowanych w różnych ustawach.  Jednocześnie podkreślić należy, że art. 68 Konstytucji nie wymaga, aby wszystkie świadczenia opieki zdrowotnej, jakie są udzielane przez publiczną służbę zdrowia, były nieodpłatne. Ustawodawca powinien jednak – i jest to jego podstawowy obowiązek, płynący z art. 68 – jednoznacznie ustalić, które rodzaje świadczeń są dostępne bez konieczności ponoszenia dodatkowych kosztów (tzw. koszyk świadczeń gwarantowanych), a które mają charakter ponadstandardowy  i wymagają sfinansowania (czy dofinansowania) przez obywatela (por. wyrok Trybunału Konstytucyjnego K 14/03). Wskazany przepis daje zatem ustawodawcy – w zależności od aktualnego stanu finansów publicznych – możliwość wprowadzenia podziału świadczeń opieki zdrowotnej na takie, \\fktóre będą nieodpłatne, częściowo odpłatne oraz w pełni odpłatne. Ważne jednak, aby podział ten był określony na poziomie ustawowym, z poszanowaniem zasad poprawnej legislacji (por. wyrok Trybunału Konstytucyjnego K 14/03).” (wyrok Naczelnego Sądu Administracyjnego z dnia 23 stycznia 2018 r., sygn. akt: II GSK 1315/17). \\n\\tNaczelna Izba Aptekarska\\tArt. 2 pkt 13c, art. 6 ust. 9a-9c, aert. 45a pkt 8 lit. n1 ustawy refundacyjnej - opłata dyspensyjna\\tProponuje się wprowadzić instytucję opłaty dyspensyjnej.  W związku z tym proponuje się wprowadzić następujące zmiany: W art. 1 dotyczącym zmiany w ustawie z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych (Dz. U. z 2024 r. poz. 930 oraz z 2025 r. poz. 129) wprowadza się następujące zmiany: - w pkt 1 dot. art. 2 dodaje się lit. c1 w brzmieniu: „c1) po pkt 13 dodaje się pkt 13a w brzmieniu: „13a) opłata dyspensyjna - opłatę należną podmiotowi prowadzącemu aptekę w związku z wykonaniem czynności wymaganych przy wydaniu leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medyczny, dla którego wydana została decyzja administracyjna o objęciu refundacją w zakresie nadanej kategorii dostępności \\frefundacyjnej, o której mowa w art. 6 ust. 1 pkt 1;”; - w pkt 2 dot. art. 6 dodaje się lit. d1 w brzmieniu: „d1) po ust. 9 dodaje się ust. 9a-9c w brzmieniu: „9a. Za wydanie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medyczny, dla którego wydana została decyzja administracyjna o objęciu refundacją w zakresie nadanej kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1, aptece przysługuje opłata dyspensyjna.  9b. Opłata dyspensyjna finansowa jest przez Fundusz. 9c. Kwota opłaty dyspensyjnej wynosi: 0,25 kwoty odpłatności ryczałtowej, o której mowa w ust. 7 - w przypadku leku wytwarzanego w Polsce; 0,20 kwoty odpłatności ryczałtowej, o której mowa w ust. 7 – w przypadku pozostałych leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych. 9d. Opłata dyspensyjna dotyczy jednostkowego opakowania leku, środka spożywczego specjalnego przeznaczenia żywieniowego oraz jednostkowego wyrobu medycznego.”.  - w pkt 48 lit. e tiret czwarte dotyczącym zmiany art. 45a pkt 8 dodaje lit. n1 w brzmieniu: „n1) kwotę opłaty dyspensyjnej.”. \\t\\fProponowane wprowadzenie opłaty dyspensyjnej za każde wydanie leku refundowanego stanowi odpowiedź na wieloletnie postulaty środowiska aptekarskiego, a także systemową potrzebę stabilizacji rynku farmaceutycznego w Polsce. Celem zmiany jest wzmocnienie ekonomiczne aptek ogólnodostępnych, których rentowność - szczególnie w segmencie leków refundowanych - ulega systematycznemu pogorszeniu. Dotychczasowy model finansowania aptek, oparty na urzędowej marży naliczanej od limitu refundacyjnego, nie był istotnie modyfikowany od ponad dekady i stał się nieadekwatny wobec realnych kosztów prowadzenia działalności oraz presji na obniżanie cen leków. Z danych rynkowych wynika, że realna wartość tej marży, która powinna pokrywać koszty funkcjonowania apteki (personel, logistyka, utrzymanie lokalu, obowiązki sprawozdawcze), systematycznie maleje. W tym czasie znacząco wzrosły m.in. koszty zatrudnienia farmaceutów i techników farmaceutycznych, co w szczególności uderza w apteki indywidualne oraz placówki działające w mniejszych \\fmiejscowościach i na terenach wiejskich. Pogarszająca się sytuacja finansowa przyczynia się do likwidacji placówek.  W tym kontekście opłata dyspensyjna pełni funkcję systemowego instrumentu rekompensującego aptekom coraz niższe przychody z leków refundowanych. W przeciwieństwie do marży procentowej, opłata dyspensyjna jest stałym, niezależnym od ceny leku wynagrodzeniem za czynność wydania leku – a więc za świadczenie zdrowotne, które farmaceuta wykonuje. Takie rozwiązanie funkcjonuje od lat w wielu państwach UE, gdzie stała opłata za wydanie leku stanowi ważny filar finansowania aptek i zapewnia im stabilność operacyjną.  Wprowadzenie opłaty dyspensyjnej pozwoli także na zwiększenie dostępności leków refundowanych w skali kraju. Obecnie apteki niechętnie utrzymują w magazynach tanie preparaty refundowane, ponieważ generują one niewielki lub wręcz ujemny dochód. W rezultacie pacjenci są zmuszeni do wielokrotnych wizyt lub poszukiwania leków w odległych lokalizacjach. Stałe wynagrodzenie za każdą dyspensację zlikwiduje tę barierę ekonomiczną i przyczyni się do zapewnienia pełniejszego asortymentu dostępnych od ręki leków, co poprawi ciągłość farmakoterapii i jakość leczenia. Nowy mechanizm może również wspierać realizację strategicznych celów zdrowotnych państwa, takich jak zwiększenie udziału krajowej produkcji leków. Projekt ustawy przewiduje możliwość zróżnicowania wysokości \\fopłaty dyspensyjnej m.in. w zależności od miejsca wytworzenia leku. Wyższa stawka dla leków produkowanych w Polsce może stanowić zachętę dla aptek do utrzymywania tych produktów w asortymencie, co z kolei wspiera krajowy przemysł farmaceutyczny i zwiększa bezpieczeństwo lekowe państwa. Opłata dyspensyjna stanowi również element niezbędny dla rozwoju nowych świadczeń farmaceutycznych. Stabilna sytuacja finansowa aptek pozwoli na szersze wdrażanie takich usług jak przeglądy lekowe, szczepienia w aptekach, czy edukacja pacjenta. Wzmocnienie ekonomiczne podstawowej działalności apteki (wydawanie leków refundowanych) jest warunkiem koniecznym dla rozwoju tych świadczeń, które są obecnie finansowane w wielu krajach UE i stanowią ważne uzupełnienie systemu ochrony zdrowia. Wprowadzenie opłaty dyspensyjnej nie obciąży pacjentów – będzie finansowane ze środków publicznych w ramach budżetu refundacyjnego, a jednocześnie przyniesie konkretne korzyści społeczne: poprawi dostęp do leków, ograniczy zjawisko „białych plam” aptecznych, zwiększy adherencję pacjentów do leczenia oraz wzmocni rolę apteki jako lokalnego punktu pierwszego kontaktu w systemie ochrony zdrowia. Jednocześnie mechanizm ten może mieć również pozytywny wpływ na racjonalizację wydatków refundacyjnych – apteki, nieuzależnione od ceny leku, będą skłonne częściej wydawać tańsze odpowiedniki, co przyniesie oszczędności dla NFZ. \\fPodsumowując, wprowadzenie opłaty dyspensyjnej to rozwiązanie długo oczekiwane, uzasadnione ekonomicznie, społecznie i systemowo. Poprawia stabilność funkcjonowania aptek, zwiększa dostępność leków refundowanych dla pacjentów, wspiera lokalną produkcję farmaceutyczną i stanowi istotny krok w kierunku modernizacji oraz europeizacji polskiego systemu refundacji leków.\\t\\fPoza zakresem regulacji\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 2 pkt 11a, 18, 20b i 20c ustawy refundacyjnej\\tArt. 2 Użyte w ustawie określenia oznaczają: (…) 11a) lek wytwarzany na terytorium Rzeczypospolitej Polskiej – lek, w odniesieniu do którego jakiekolwiek każde działanie podejmowane przez przedsiębiorcę niebędącego osobą zagraniczną w rozumieniu art. 3 pkt 5 ustawy z dnia 6 marca 2018 r. o zasadach uczestnictwa przedsiębiorców zagranicznych i innych osób zagranicznych w obrocie gospodarczym na terytorium Rzeczypospolitej Polskiej (Dz. U. z 2022 r. poz. 470) i prowadzące do jego wytworzenia powstania, w tym zakup i przyjmowanie w miejscu wytwarzania przez wytwórcę materiałów używanych do produkcji, pakowanie oraz produkcja, odbywa się w całości na terytorium Rzeczypospolitej Polskiej, z wyłączeniem zakupu leku, jego pakowania lub przepakowywania leku, magazynowania i dystrybucji, a także czynności kontrolnych związanych z tymi działaniami, w tym zwalnianiem do obrotu;  11ab) lek przeznaczony do wytwarzania na terytorium Rzeczpospolitej Polskiej – lek, w \\fodniesieniu do którego wnioskodawca zobowiązał się zapewnić, że działania wymienione w pkt 11a lub pkt 20b rozpoczną się na terytorium Rzeczpospolitej Polskiej po dniu wejścia w życie decyzji, jednak nie później niż w terminie  lata od dnia wydania decyzji o objęciu refundacją,        20b) substancja czynna wytwarzana na terytorium Rzeczypospolitej Polskiej - substancję czynną, w odniesieniu do której każde jakiekolwiek działanie podejmowane przez przedsiębiorcę niebędącego osobą zagraniczną w rozumieniu art. 3 pkt 5 ustawy z dnia 6 marca 2018 r. o zasadach uczestnictwa przedsiębiorców zagranicznych i innych osób zagranicznych w obrocie gospodarczym na terytorium Rzeczypospolitej Polskiej i prowadzące do jej wytworzenia powstania, w tym zakup i przyjmowanie w miejscu wytwarzania przez wytwórcę materiałów używanych do jej produkcji oraz produkcja, odbywa się w całości na terytorium Rzeczypospolitej Polskiej, z wyłączeniem dopuszczenia do kolejnych etapów wytwarzania substancji czynnej, w tym jej pakowania, przepakowywania, ponownego etykietowania, magazynowania oraz dystrybucji, a także czynności kontrolnych związanych z tymi działaniami;  \\f20c) substancja czynna wytwarzana na terytorium Unii Europejskiej - substancję czynną, w odniesieniu do której każde działanie podejmowane przez przedsiębiorcę i prowadzące do jej wytworzenia, w tym zakup i przyjmowanie w miejscu wytwarzania przez wytwórcę materiałów używanych do jej produkcji oraz produkcja, odbywa się w całości na terytorium Unii Europejskiej, z wyłączeniem dopuszczenia do kolejnych etapów wytwarzania substancji czynnej, w tym jej pakowania, przepakowywania, ponownego etykietowania, magazynowania oraz dystrybucji, a także czynności kontrolnych związanych z tymi działaniami;  \\t   Co do pkt 11a i 20b: Postulujemy rozszerzenie definicji leku wytwarzanego w Polsce oraz substancji czynnej wytwarzanej w Polsce – aby objąć także inne stany faktyczne, w których produkt w toku procesu wytwarzania jest fizycznie 312 obecny na terytorium Rzeczpospolitej Polskiej. Z punktu widzenia bezpieczeństwa lekowego celem przepisu powinno być doprowadzenie do sytuacji, w której produkt w trakcie wytwarzania jest fizycznie obecny na terytorium Polski. Definicja bardziej otwarta jest też korzystna z punktu widzenia rozwoju gospodarki, gdyż powoduje zachętę dla przedsiębiorców do przenoszenia wytwarzania produktów leczniczych, nawet częściowego, do Polski.  Preferencje refundacyjne dla leków gotowych sprowadzanych do Polski byłyby odpowiednio niższe niż w przypadku leków, których większa część procesu wytwórczego jest zlokalizowana \\fna terytorium naszego kraju (zob. uwagi do art. 6 ust. 2a).       PZPPF postuluje rozszerzenie preferencji refundacyjnych na leki, co do których wnioskodawca zobowiąże się do przeniesienia wytwarzania do Polski w okresie maksymalnie 3 lat. Będzie to skuteczne narzędzie zachęcające do alokowania produkcji farmaceutycznej w naszym kraju, zwiększając poziom bezpieczeństwa lekowego oraz sprzyjając rozwojowi gospodarczemu. Pakiet propozycji obejmuje: - wprowadzenie definicji „leku przeznaczonego do wytwarzania na terytorium Rzeczpospolitej Polskiej” (art. 2 pkt 11ab); - rozciągnięcie na taki lek możliwości skorzystania z preferencji refundacyjnych (art. 13a ust. 1); - wprowadzenie zobowiązania do rozpoczęcia wytwarzania w Polsce (art. 13a ust. 3a); - wprowadzenie odpowiedzialności za niedopełnienie ww. zobowiązania (art. 13a ust. 6, art. 33 ust. 1 pkt 6a).  Uzasadnienie jak do pkt 11a powyżej.                  Proponujemy dodanie definicji „substancja czynna wytwarzana na terytorium Unii Europejskiej” oraz utworzenie nowego wykazu G3, obejmującego produkty lecznicze wytwarzane na terytorium Rzeczypospolitej Polskiej z substancji czynnych produkowanych w państwach członkowskich Unii Europejskiej. Produkty te objęte byłyby szczególnym mechanizmem preferencyjnym, na wzór obowiązujących już wykazów G1 i G2. Według danych Ministerstwa Zdrowia i Narodowego Funduszu Zdrowia, wykaz G2 – obejmujący produkty lecznicze wytwarzane w Polsce – obecnie pokrywa jedynie ok. 0,65% potrzeb pacjentów (1 terapia na 154 osoby), gdzie wykaz G1 odpowiada za ok. 30% potrzeb pacjentów. Taka dysproporcja potwierdza, że dalsze istotne zwiększenie wolumenu leków z wykazu G2 w krótkim horyzoncie czasowym jest nierealne z uwagi na ograniczenia technologiczne i infrastrukturalne krajowego przemysłu farmaceutycznego. Wprowadzenie nowej kategorii pośredniej – wykazu G3 – stanowi \\fproporcjonalny i możliwy do realizacji krok w kierunku uniezależniania polskiego rynku leków od dostaw substancji czynnych z Azji, przy jednoczesnym wzmocnieniu europejskiego łańcucha dostaw. Mechanizm ten będzie stanowić silny impuls inwestycyjny dla przedsiębiorstw operujących na terytorium UE, zachęcając do nabywania API oraz przenoszenia ich produkcji z Azji do Europy, co jest zgodne z kierunkiem wyznaczanym przez politykę strategicznej autonomii Unii Europejskiej. W świetle niedawnych zakłóceń w globalnym łańcuchu dostaw w trakcie pandemii COVID-19 – których skutki odczuły wszystkie państwa członkowskie – konieczne jest tworzenie realnych zachęt do dywersyfikacji źródeł pozyskiwania substancji czynnych. Włączenie do preferencyjnego mechanizmu refundacyjnego produktów leczniczych, których zarówno wytwarzanie końcowe, jak i pochodzenie API związane są z terytorium UE, przyczyni się do zwiększenia odporności systemu ochrony zdrowia na przyszłe kryzysy i zaburzenia rynkowe. Wskazany mechanizm G3, jako rozwiązanie pośrednie między obecnymi wykazami G1 i G2, wpisuje się w strategię budowania długoterminowej samowystarczalności lekowej Polski w ramach wspólnotowego rynku Unii Europejskiej. \\t\\fUwaga niezasadna  Zdaniem Ministra Zdrowia, aby przedmiotowa regulacja odnosiła właściwy skutek, musi ograniczać się jedynie do leków w całości wytworzonych w Polsce. Dodatkowo projekt po konsultacjach publicznych będzie rozszerzony o dodatkowe preferencje dla produktów wytworzonych w kraju.\\n\\tNutricia Polska Sp. z o.o.\\tArt.2 pkt 13 lit. b ustawy refundacyjnej\\tUżyte w ustawie określenia oznaczają: (…) 13) odpowiednik - w przypadku: (…) b) środka spożywczego specjalnego przeznaczenia żywieniowego - środek spożywczy specjalnego przeznaczenia żywieniowego mający ten sam albo zbliżony skład ilościowy i jakościowy – z wyłączeniem składników wpływających na smak, to samo zastosowanie lub oraz ten sam sposób przygotowania,\\tW przypadku środka spożywczego specjalnego przeznaczenia żywieniowego należy zastosować punkt wyjścia taki jak w przypadku odpowiedników leków i wyrobów medycznych, tj. tożsamość. Wobec tego zasadnym jest wykreślenie podobieństwa („albo zbliżony”) i zastosowanie wyłącznie kryterium tożsamości.  Jednocześnie, aby uniknąć wątpliwości, należałoby wprost wyłączyć z kwestii tożsamości kwestie smakowe (podobnie jak w definicji prezentacji).  Zaproponowane rozwiązanie wynika z faktu, że obecna, szeroka definicja odpowiednictwa dla tej kategorii produktów jest nie do utrzymania i negatywnie wpływa na dostępność do poszczególnych produktów.  Produkty z kategorii środków spożywczych specjalnego przeznaczenia żywieniowego zawierają po kilkadziesiąt składników różnego znaczenia i pochodzących z różnych źródeł. Nawet produkty o podobnym przeznaczeniu różnią się od siebie nie tylko liczbą składników, ale także ich proporcjami. W przypadku postępowania dietetycznego w różnych jednostkach chorobowych nawet niewielkie różnice jakościowe i ilościowe w składzie występujące między produktami mogą uniemożliwiać ich zamianę.  Taka sytuacja dotyczy m.in. podobnych produktów aminokwasowych \\fstosowanych w ciężkiej alergii na białko mleka krowiego, co szczegółowo wyjaśnia Stanowisko eksperckie w sprawie stosowania mieszanek elementarnych w ciężkiej alergii przygotowane przez Dr Rebeccę Stratton.  W przywołanym dokumencie czytamy m.in., że niemowlęta i dzieci z ciężką postacią alergii na białka mleka krowiego (ABMK), które są leczone znoszącą objawy mieszanką aminokwasową, nie powinny mieć zmienianego preparatu bez wskazań medycznych. Wprawdzie wszystkie preparaty do postępowania w ciężkiej alergii objęte refundacją są podobne, a mechanizm ich działania tożsamy, niemniej jednak składają się z kilkudziesięciu składników w różnych proporcjach, których pełna tolerancja przez pacjenta jest kluczem do długotrwałego sukcesu terapeutycznego. Dlatego produkty „tylko podobne” w ciężkiej alergii nie są rutynowo stosowane wymiennie.  Różnice między preparatami wynikają m.in. ze składu i procesów technologicznych. Mieszanki aminokwasowe mogą różnić się pochodzeniem i jakością aminokwasów. Różne źródła surowców (np. syntetyczne vs roślinne) mogą wpływać na stopień tolerancji produktu przez pacjenta.   Produkty różnią się źródłem węglowodanów (np. maltodekstyna vs syrop glukozowy). Maltodekstryna to polisacharyd zbudowany z glukozy, który wymaga enzymatycznej hydrolizy w \\fprzewodzie pokarmowym przed wchłonięciem do krwiobiegu. Jej trawienie przebiega inaczej niż w przypadku syropu glukozowego, wchłanianego w jelicie cienkim, bez konieczności wcześniejszej hydrolizy.   Preparaty zawierają różne poziomy składników odżywczych. Różnice w wartości odżywczej (np. poziom makroskładników czy składników mineralnych) zmieniają osmolarność produktu, co może znacząco wpływać na tolerancję pacjenta. Różnica osmolarności może powodować ryzyko wystąpienia m.in. problemów żołądkowo-jelitowych, takich jak biegunka czy wymioty.   Preparaty zawierają różne proporcje składników. Poszczególne mieszanki zawierają różne oleje roślinne w zmiennych proporcjach, co może mieć wpływ na tolerancję i akceptację produktu przez dzieci z ciężką postacią alergii na białka mleka krowiego. Preparaty mogą też zawierać różne ilości średniołańcuchowych triglicerydów (tłuszcze MCT), które są łatwiejsze do metabolizowania niż długołańcuchowe kwasy tłuszczowe. Obecność tłuszczów MCT poprawia trawienie i wchłanianie tłuszczów, szczególnie u dzieci z alergią, z zaburzeniami wchłaniania lub problemami żołądkowo-jelitowymi. Różna ilość i pochodzenie tłuszczów MCT w poszczególnych preparatach wpływa na tolerancję mieszanki.  \\fTłuszcz jest nośnikiem smaku, więc różnice profili tłuszczowych w preparatach wpływają na ich smak i teksturę, co jest istotne w kontekście dzieci z ciężką ABMK, które często cierpią na neofobię czy zaburzenia karmienia. Każde dziecko może inaczej reagować na konkretne proporcje tłuszczów a akceptacja smaku jest kluczowa w doborze preparatu.  Produkty różnią się źródłami wielonienasyconych kwasów tłuszczowych DHA i ARA (np. olej rybi czy olej z mikroalg Schizochytrium sp.). Dzieci z ciężką ABMK mogą reagować na nowe źródła DHA i ARA, których nie było w dotychczasowej mieszance.  Istotne są także różnice w obecności składników dodawanych dobrowolnie. Preparaty podobne różnicuje obecność składników dodatkowych, dobrowolnie wprowadzanych przez producenta, takich jak skrobia, która wpływa na właściwości preparatu, m.in. poprzez jego zagęszczenie i zmianę tekstury. Różnice w składzie, wynikające z obecności lub braku skrobi (np. skrobi modyfikowanej tapiokowej czy kukurydzianej), mogą mieć istotne znaczenie, zwłaszcza w kontekście tolerancji preparatu przez dziecko z ciężką postacią ABMK.  Każdy producent stosuje inne metody produkcji. Jeśli formuła nie jest dobrze przebadana pod kątem hipoalergenności, możliwe jest występowanie w różnych preparatach śladowych ilości peptydów \\fpochodzenia surowcowego (np. z olejów roślinnych), które szczególnie u dzieci z alergią wielopokarmową mogą wywoływać reakcje alergiczne. Różnice w technologii produkcji mogą również wpływać na smak, zapach i konsystencję mieszanki, co może powodować brak akceptacji innej formuły przez dziecko.  Wprowadzenie innej mieszanki może wiązać się z nieprzewidywalnymi reakcjami, a proces ponownej adaptacji może być długotrwały, trwać nawet około miesiąca i być niekorzystny dla zdrowia dziecka i komfortu całej rodziny, lub zakończyć się niepowodzeniem.  W rezultacie przyjęcie zaproponowanej definicji odpowiednika dla kategorii środków spożywczych specjalnego przeznaczenia żywieniowego, skutkowałoby zapewnieniem realnej i bezpiecznej dla pacjentów zasady zamiennictwa tego rodzaju produktów.\\t\\fUwaga niezasadna Ze względów technologicznych większość produktów leczniczych zawiera w składzie oprócz substancji czynnych również substancje pomocnicze. W przypadku środków spożywczych specjalnego przeznaczenia żywieniowego (śsspż) należałoby je ogólnie określić „składnikami podstawowymi” oraz „składnikami dodatkowymi”. Posiadanie zbliżonego składu, zastosowania lub sposobu przygotowania śsspż jest wystarczającym, aby wskazać czy może zostać uznany za odpowiednik innego śsspż, co wnioskodawca starający się o wejście do refundacji udowadnia w składanym pod rygorem odpowiedzialności karnej wniosku refundacyjnym. Założenie powyższej definicji jest podstawą zachowania konkurencyjności oraz dostępu do produktów o coraz większym znaczeniu refundacyjnym.  Należy przy tym zauważyć, iż w przypadku implementacji proponowanej zmiany należałoby dostosować wiele innych przepisów, w tym m. in. wymagać składania pełnych wniosków refundacyjnych, wraz z analizami HTA,  po każdej zmianie składu środka spożywczego objętego refundacją, jeżeli faktycznie każda zmiana składu preparatu ma tak ogromny wpływ na leczenie – zdaniem Ministra Zdrowia niewielkie różnice w składzie produktu nie wpływają na jego wartość kliniczną, dlatego też nieraz godzi się na przedłużanie refundacji środków spożywczych specjalnego przeznaczenia \\fżywieniowego pomimo zmian w ich składzie jakościowym i ilościowym.  Minister Zdrowia kategorycznie odmawia określania odpowiednikami jedynie środków spożywczych mający ten sam skład jakościowy i ilościowy, to samo zastosowanie oraz ten sam sposób przygotowania.\\n\\tPolskie Towarzystwo Farmakoekonomiczne \\tRozdział IX ustawy o refundacji\\tProponujemy zagwarantowanie odpowiednich okresów przejściowych. W rozdziale 9 UR proponujemy, aby do postępowań wszczętych i niezakończonych przed dniem wejścia w życie nowelizacji ustawy stosować przepisy nowe a nie dotychczasowe.  \\tNowe przepisy wprowadzają wiele korzystnych rozwiązań, takich jak nowa definicja ceny efektywnej czy możliwość zastosowania kroczącej obniżki, które powinny mieć zastosowanie również do toczących się postępowań. Zapewni to równe traktowanie wszystkich wnioskodawców i przyspieszy dostęp pacjentów do terapii. \\tUwaga niezasadna Z uwagi na bardzo duży zakres zmian, które wprowadza projekt zasadne jest utrzymanie oczywistego i najbezpieczniejszego rozwiązania w zakresie przepisów przejściowych i utrzymanie zapisów, zgodnie z którymi do postępowań wszczętych i niezakończonych przed dniem wejścia w życie nowelizacji ustawy stosować należy przepisy dotychczasowe. Rozpatrywanie postępowań wszczętych i niezakończonych według nowych zapisów ustawowych przedłuży postępowania oraz może zwiększyć ryzyko błędów. Niezasadne jest \\fwybieranie przepisów, które dla stron są korzystniejsze z oddalaniem w czasie tych mniej nieopłacalnych. W projekcie zaproponowano, by odstąpić jedynie od art. 11 ustawy o refundacji w zakresie terminu ochrony patentowej oraz od art. 18 ustawy o refundacji w zakresie braku możliwości zmiany wniosku po uchwale Komisji Ekonomicznej.\\n\\tPolskie Towarzystwo Reumatologiczne\\tArt. 2 pkt 18 ustawy - zmiana\\tW związku z wprowadzeniem przez projektodawcę tzw. „czwartej kategorii dostępności refundacyjnej” wnioskujemy o zmianę definicji programu lekowego.  Proponujemy następujące brzmienie art. 2 pkt 18 ustawy:  „18) program lekowy – program zdrowotny w rozumieniu art. 5 pkt 30 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych obejmujący technologię lekową, w której substancja czynna w danym wskazaniu oraz dla danej populacji nie jest składową kosztową innych świadczeń gwarantowanych, lub środek spożywczy specjalnego przeznaczenia żywieniowego, który nie jest składową kosztową innych świadczeń gwarantowanych w rozumieniu art. 5 pkt 35 tej ustawy, za wyjątkiem świadczeń gwarantowanych, o których mowa w art. 15 ust. 2 pkt 14 i 15 a tejże ustawy.”  \\tPropozycja umożliwiająca refundację danej substancji czynnej jednocześnie w dwóch kategoriach dostępności – programie lekowym i czwartej kategorii dostępności refundacyjnej. Takie rozwiązanie będzie bezpieczniejsze dla pacjentów, tzn. umożliwi płynne przechodzenie pacjentów z programu lekowego do nowej kategorii w AOS bez potencjalnego narażania chorych na brak ciągłości leczenia.  Refundacja danej substancji czynnej tylko w czwartej kategorii będzie skutkowała potrzebą przejęcia leczenia pacjentów z programu lekowego przez AOS z dnia na dzień. Jeśli pacjent nie znajdzie takiego AOS, który będzie chciał kontynuować leczenie chory utraci możliwość dalszej terapii, bo leku jednocześnie nie będzie już w programie lekowym. W przypadku reumatologii i np. adalimumabu, który mógłby z uwagi na koszt rocznej terapii przejść do nowej kategorii, jest to liczba ponad 9 tys. pacjentów.  \\fMożliwość kontynuowania leczenia w programie lekowym substancją czynną, która jednocześnie znalazłaby się w czwartej kategorii, pozwoliłoby pacjentowi i ośrodkowi prowadzącemu leczenie na znalezienie AOS, w którym chory będzie mógł i będzie chciał kontynuować terapię.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej \\n\\tKonfederacja Lewiatan\\tDotyczy Art. 2 pkt 11a, 20b Ustawy – zmiana dotychczasowej treści\\tArt. 2  Użyte w ustawie określenia oznaczają:  (…)  11a) lek wytwarzany na terytorium Rzeczypospolitej Polskiej – lek, w odniesieniu do którego jakiekolwiek każde działanie podejmowane przez przedsiębiorcę niebędącego osobą zagraniczną w rozumieniu art. 3 pkt 5 ustawy z dnia 6 marca 2018 r. o zasadach uczestnictwa przedsiębiorców zagranicznych i innych osób zagranicznych w obrocie gospodarczym na terytorium Rzeczypospolitej Polskiej (Dz. U. z 2022 r. poz. 470) i prowadzące do jego wytworzenia powstania, w tym zakup i przyjmowanie w miejscu wytwarzania przez wytwórcę materiałów używanych do produkcji, pakowanie oraz produkcja, odbywa się w całości na terytorium Rzeczypospolitej Polskiej, z wyłączeniem zakupu leku, jego pakowania lub przepakowywania leku, magazynowania i dystrybucji, a także czynności kontrolnych związanych z tymi działaniami, w tym zwalnianiem do obrotu;  20b) substancja czynna wytwarzana na terytorium Rzeczypospolitej Polskiej - substancję czynną, w odniesieniu do której każde jakiekolwiek działanie podejmowane przez przedsiębiorcę niebędącego osobą zagraniczną w rozumieniu art. 3 pkt 5 \\fustawy z dnia 6 marca 2018 r. o zasadach uczestnictwa przedsiębiorców zagranicznych i innych osób zagranicznych w obrocie gospodarczym na terytorium Rzeczypospolitej Polskiej i prowadzące do jej wytworzenia powstania, w tym zakup i przyjmowanie w miejscu wytwarzania przez wytwórcę materiałów używanych do jej produkcji oraz produkcja, odbywa się w całości na terytorium Rzeczypospolitej Polskiej, z wyłączeniem dopuszczenia do kolejnych etapów wytwarzania substancji czynnej, w tym jej pakowania, przepakowywania, ponownego etykietowania, magazynowania oraz dystrybucji, a także czynności kontrolnych związanych z tymi działaniami;\\t\\fPostulujemy rozszerzenie definicji leku wytwarzanego w Polsce oraz substancji czynnej wytwarzanej w Polsce – aby objąć także inne stany faktyczne, w których produkt w toku procesu wytwarzania jest fizycznie obecny na terytorium Rzeczpospolitej Polskiej. Z punktu widzenia bezpieczeństwa lekowego celem przepisu powinno być doprowadzenie do sytuacji, w której produkt w trakcie wytwarzania jest fizycznie obecny na terytorium Polski. Definicja bardziej otwarta jest też korzystna z punktu widzenia rozwoju gospodarki, gdyż powoduje zachętę dla przedsiębiorców do przenoszenia wytwarzania produktów leczniczych, nawet częściowego, do Polski. Preferencje refundacyjne dla leków gotowych sprowadzanych do Polski byłyby odpowiednio niższe niż w przypadku leków, których większa część procesu wytwórczego jest zlokalizowana na terytorium naszego kraju (zob. uwagi do art. 6 ust. 2a).\\tUwaga niezasadna  Zdaniem Ministra Zdrowia, aby przedmiotowa regulacja odnosiła właściwy skutek, musi ograniczać się jedynie do leków w całości wytworzonych w Polsce. Dodatkowo projekt po konsultacjach publicznych będzie rozszerzony o dodatkowe preferencje dla produktów wytworzonych w kraju.\\n\\tNutricia Polska Sp. z o.o.\\tart. 2 dodanie pkt 21 ustawy refundacyjnej\\tUżyte w ustawie określenia oznaczają: (…) 21) środek spożywczy specjalnego przeznaczenia żywieniowego –  środek spożywczy, o którym mowa w art. 24 ust. 2 pkt 1 i 4 ustawy z dnia 25 sierpnia 2006 r. o bezpieczeństwie żywności i żywienia (Dz. U. z 2023 r. poz. 1448)  preparat do początkowego żywienia niemowląt oraz preparat do dalszego żywienia niemowląt, o których mowa w art. 2. ust. 2 pkt c oraz d Rozporządzania Parlamentu Europejskiego i Rady (UE) nr 609/2013 z dnia 12 czerwca 2013 r. w sprawie żywności przeznaczonej dla niemowląt i małych dzieci oraz żywności specjalnego przeznaczenia medycznego i środków spożywczych zastępujących całodzienną dietę, do kontroli masy ciała oraz uchylające dyrektywę Rady 92/52/EWG, dyrektywy Komisji 96/8/WE, 1999/21/WE, 2006/125/WE i 2006/141/WE, dyrektywę Parlamentu Europejskiego i Rady 2009/39/WE oraz rozporządzenia Komisji \\f(WE) nr 41/2009 i (WE) nr 953/2009  przeznaczony do dietetycznego odżywiania pacjentów pod nadzorem lekarza, którego stosowania nie można uniknąć przez modyfikację normalnej diety lub podawanie innych środków spożywczych specjalnego przeznaczenia żywieniowego; oraz żywność specjalnego przeznaczenia medycznego, o której mowa w art. 2. ust. 2 pkt g tego rozporządzenia;\\t\\fWobec uchylenia za pomocą  Rozporządzenia Parlamentu Europejskiego i Rady (UE) nr 609/2013 z dnia 12 czerwca 2013 r. Dyrektywy Parlamentu Europejskiego i Rady 2009/39/WE z dnia 6 maja 2009 r. w sprawie środków spożywczych specjalnego przeznaczenia żywieniowego należy wskazać, że obecnie w prawie UE nie funkcjonuje pojęcie „środka spożywczego specjalnego przeznaczenia żywieniowego”. Tym samym zasadnym jest oparcie definicji legalnej środka spożywczego specjalnego przeznaczenia żywieniowego (którego nie proponujemy usuwać z ustawy refundacyjnej z uwagi na jego ugruntowanie w systemie) o pojęcia, których definicje legalne są uregulowane w aktualnie obowiązującym prawie (ustawa o bezpieczeństwie \\fżywności i żywienia jest w tym zakresie nieaktualna).  Jednocześnie należy wskazać, że aktualna definicja środka spożywczego specjalnego przeznaczenia żywieniowego nie odbiega w istotnym stopniu od definicji żywności specjalnego przeznaczenia medycznego (np. element nadzoru lekarza czy braku osiągnięcia celu jedynie przez zmianę normalnej diety). Tym samym niniejsza propozycja zmiany pozytywnie wpłynie na jednolitość i spójność siatki pojęciowej w obowiązujących aktach prawnych.   W proponowanej zmianie do definicji włączono pojęcia preparatów do początkowego żywienia niemowląt oraz preparatów do dalszego żywienia niemowląt – które aktualnie znajdują się w definicji poprzez referencję do art. 24 ust. 2 pkt 1 ustawy o bezpieczeństwie żywności i żywienia. Niniejsza propozycja jest podyktowana również odwołaniem do wyżej wspomnianego Rozporządzenia unijnego, które definiuje te pojęcia.   Proponowana zmiana jest zgodna z pierwotną wolą ustawodawcy i nie wpływa w istotny sposób na poszerzenie lub zawężenie zakresu pojęciowego środków spożywczych specjalnego przeznaczenia żywieniowego. Jednocześnie proponowana zmiana pozytywnie wpływa na spójność siatki pojęciowej w obowiązującym prawie, co przyczynia się do efektywności jego stosowania\\t\\fUwaga niezasadna Ustawa o refundacji definiuje „środek spożywczy specjalnego przeznaczenia żywieniowego” zgodnie z definicją wynikającą z ustawy generalnej dla tej grupy produktów tj. ustawy z dnia 25 sierpnia 2006 r. o bezpieczeństwie żywności i żywienia (Dz. U. z 2023 r. poz. 1448). \\n\\t\\tArt. 2 pkt 25aa ustawy refundacyjnej\\t25aa) terapia skojarzona - farmakoterapię prowadzoną za pomocą co najmniej dwóch technologii lekowych, które łączą się w jeden schemat stosowany w leczeniu danej choroby;\\tCelem wprowadzenia regulacji dotyczących finansowania terapii skojarzonych, koniecznym jest ich zdefiniowanie.\\tUwaga niezasadna Pojęcie terapii skojarzonej jest wskazane w art. 30a ust. 6 ustawy o refundacji i w opinii Ministra Zdrowia takie zdefiniowanie jest wystarczające.\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\tart. 2 pkt 30 ustawy refundacyjnej\\t 30) produktem leczniczym z importu równoległego – jest każdy produkt leczniczy sprowadzony do Rzeczpospolitej Polskiej w drodze importu równoległego w rozumieniu art. 2 ust. 7b ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne\\tZ uwagi na odmienności związane z obrotem produktami z importu równoległego oraz z uwagi na rozbudowanie przepisów dotyczących tej grupy produktów należy wprowadzić odrębną definicję w celu zapewnienia przejrzystości nowych zapisów.\\tUwaga niezasadna Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji. Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu.\\n\\tKonfederacja Lewiatan\\tDotyczy Art. 3 ust. 1 i 4 Ustawy – zmiana dotychczasowej treści \\tArt. 3 ust 1. Całkowity budżet na refundację wynosi nie więcej niż 17% sumy środków publicznych przeznaczonych na finansowanie świadczeń gwarantowanych w planie finansowym Funduszu zatwierdzonym w trybie, o którym mowa w art. 121 ust. 4 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej \\ffinansowanych ze środków publicznych, zwanej dalej \\\"ustawą o świadczeniach\\\", albo ustalonym w trybie, o którym mowa w art. 121 ust. 5 tej ustawy, z uwzględnieniem jego późniejszych zmian, o których mowa w art. 124 ustawy o świadczeniach, oraz środków pochodzących z instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5, a także zwrotów, o których mowa w art. 34 ust. 1-1b, podwyższony o koszty poniesione przez wnioskodawców na podstawie art. 11 ust. 3b i 3c. Art. 3 ust. 4. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, podział kwoty środków finansowych, o której mowa w ust. 2, uwzględniając realizację refundacji, a także liczbę i rodzaj złożonych wniosków, o których mowa w art. 24 ust. 1.\\t\\fProjekt przewiduje w art. 11 ust. 3b i 3c obowiązek zawierania RSS, w których wnioskodawcy w określonych tam okolicznościach mają zobowiązywać się do finansowania określonych kosztów terapii. Wskazujemy, że wydatki wnioskodawców na podstawie RSS powinny podwyższać całkowity budżet na refundację. Wydatki te stanowią bowiem obligatoryjny (nie dobrowolny) \\fwkład wnioskodawców w finansowanie świadczeń gwarantowanych.  Przepis o brzmieniu powyższym funkcjonował od początku obowiązywania Ustawy refundacyjnej. Jego uchylenie na podstawie nowelizacji z 17 sierpnia 2023 r. było uzasadniane potrzebą wprowadzenie większej elastyczności w wydatkowaniu środków pochodzących ze wzrostu Całkowitego Budżetu na Refundację (CBR). Rzeczywistym skutkiem zmiany jest jednak dowolność w wydatkowaniu tych dodatkowych środków.  Należy podkreślić, że usunięciu przepisu art. 3 ust. 4 z Ustawy refundacyjnej sprzeciwił się Senat RP w poprawkach do nowelizacji. Biuro Legislacyjne Senatu w „Opinii do ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (druk nr 1056)” z dnia 24 lipca 2023 r. wskazało na tę zmianę jako przykład naruszenia art. 2 Konstytucji RP, ze względu na brak wskazania kryteriów, jakimi należy kierować się przy decyzji o dystrybucji dodatkowych środków. Poprawka Senatu została odrzucona przez ówczesną większość sejmową. Postulujemy przywrócenie dotychczasowego, dobrze funkcjonującego przepisu, który gwarantował bardziej transparentną procedurę dystrybucji dodatkowych środków w CBR.\\t\\fUwaga niezasadna Minister Zdrowia całkowicie zmienił regulacje, o których mowa w art. 11 ust. 3b i 3c ustawy o refundacji.   W ocenie Ministra Zdrowia konieczność określania CBR w drodze rozporządzenia jest zbędną biurokratyczna procedurą. Te same efekty bez żadnego uszczerbku dla \\fsystemu zostaną osiągnięte poprzez określenie tego podziału w planie finansowym funduszu.\\n\\tPolski Związek Pracodawców \\fPrzemysłu Farmaceutycznego\\t\\fArt. 3 ust. 1 ustawy\\t1. Całkowity budżet na refundację wynosi nie więcej niż 17% sumy środków \\fpublicznych przeznaczonych na finansowanie świadczeń gwarantowanych w planie finansowym Funduszu zatwierdzonym w trybie, o którym mowa w art. 121 ust. 4 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, zwanej dalej \\\"ustawą o świadczeniach\\\", albo ustalonym w trybie, o którym mowa w art. 121 ust. 5 tej ustawy, z uwzględnieniem jego późniejszych zmian, o których mowa w art. 124 ustawy o świadczeniach, oraz środków pochodzących z instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5, a także zwrotów, o których mowa w art. 34 ust. 1-1b, podwyższony o koszty poniesione przez wnioskodawców na podstawie art. 11 ust. 3b i 3c. \\t\\fProjekt przewiduje w art. 11 ust. 3b i 3c obowiązek zawierania RSS, w których \\fwnioskodawcy w określonych tam okolicznościach mają zobowiązywać się do finansowania określonych kosztów terapii. Niezależnie od dalszych uwag PZPPF do tych przepisów, na wypadek gdyby miały się one ostać w zaproponowanym kształcie, wskazujemy, że wydatki wnioskodawców na podstawie RSS powinny podwyższać całkowity budżet na refundację. Wydatki te stanowią bowiem obligatoryjny (nie dobrowolny) wkład wnioskodawców w finansowanie świadczeń gwarantowanych.\\t\\fUwaga niezasadna \\fMinister Zdrowia całkowicie zmienił regulacje, o których mowa w art. 11 ust. 3b i 3c ustawy refundacyjnej\\n\\tAmerykańska Izba Handlowa w Polsce/ Pracodawcy RP\\tArt. 3 ust. 1a ustawy refundacyjnej \\tW art. 3 proponujemy dodanie ust. 1a w brzmieniu: 2. Środki finansowe pochodzące z:  1) kwot zwrotu, o których mowa w art. 4 ust. 10,  2) instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5,  3) kar pieniężnych, o których mowa w art. 34,  4) kar finansowych wynikających z art. 50–52a –– powiększają odpowiednio koszty poszczególnych pozycji wchodzących w skład całkowitego budżetu na refundację w \\froku następującym po roku, w którym zaksięgowany zostanie ich wpływ.\\t\\fProponujemy wprowadzenie regulacji, która znalazła się w pierwotnej wersji projektu ustawy z dnia 17 sierpnia 2023 r. o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (Dz. U. z 2023 r., poz. 1938), zwanej \\\"dużą nowelizacją ustawy refundacyjnej\\\" (\\\"DNUR\\\") i zakładała, że środki pochodzące z tzw. „payback”, instrumentów dzielenia ryzyka oraz kar powiększać będą całkowity budżet na refundację. Temat ten był przedmiotem dyskusji od wielu lat. W ocenie KF AmCham środki uzyskane, między innymi, z instrumentów dzielenia ryzyka powinny wracać do systemu refundacyjnego. Rozwiązanie takie zwiększa \\fprzejrzystość i efektywność finansowania, powinno pozwolić na lepsze planowanie budżetu refundacyjnego i zwiększenie dostępności do refundowanych terapii.  Uzasadnienie Pracodawcy RP Proponujemy wprowadzenie regulacji, która znalazła się w pierwotnej wersji projektu ustawy z dnia 17 sierpnia 2023 r. o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (Dz. U. z 2023 r., poz. 1938), zwanej \\\"dużą nowelizacją ustawy refundacyjnej\\\" (\\\"DNUR\\\") i zakładała, że środki pochodzące z tzw. „pay-back”, instrumentów dzielenia ryzyka oraz kar powiększać będą całkowity budżet na refundację. Temat ten był przedmiotem dyskusji od wielu lat. W ocenie Pracodawców RP środki uzyskane, między innymi, z instrumentów dzielenia ryzyka powinny wracać do systemu refundacyjnego. Rozwiązanie takie zwiększa przejrzystość i efektywność finansowania, powinno pozwolić na lepsze planowanie budżetu refundacyjnego i zwiększenie dostępności do refundowanych terapii. W tym miejscu warto nadmienić, że zgodnie z wypowiedziami kierownictwa MZ, aktualnie wpływy z instrumentów dzielenia ryzyka to istotna kwota - ok. 1,7 mld złotych rocznie. \\t\\fUwaga niezasadna W ocenie Ministra Zdrowia nie ma konieczność dodania przedmiotowego ustępu w sytuacji, w której środki finansowe pochodzące z instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5, a także zwrotów, o których mowa w art. 34 ust. 1-1b są już wskazane w ust. 1 przedmiotowego przepisu. \\n\\tPolski Związek Pracodawców \\fPrzemysłu Farmaceutycznego\\t\\fArt. 3 ust. 4 ust ref\\t4. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, podział \\fkwoty środków finansowych, o której mowa w ust. 2, uwzględniając realizację refundacji, a także liczbę i rodzaj złożonych wniosków, o których mowa w art. 24 ust. 1.\\t\\fPrzepis o brzmieniu powyższym funkcjonował od początku \\fobowiązywania Ustawy refundacyjnej. Jego uchylenie na podstawie nowelizacji z 17 sierpnia 2023 r. było uzasadniane potrzebą wprowadzenie większej elastyczności w wydatkowaniu środków pochodzących ze wzrostu Całkowitego Budżetu na Refundację (CBR). Rzeczywistym skutkiem zmiany jest jednak dowolność w wydatkowaniu tych dodatkowych środków.   Należy podkreślić, że usunięciu przepisu art. 3 ust. 4 z Ustawy refundacyjnej sprzeciwił się Senat RP w poprawkach do nowelizacji. Biuro Legislacyjne Senatu w „Opinii do ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (druk nr 1056)” z dnia 24 lipca 2023 r. wskazało na tę zmianę jako przykład naruszenia art. 2 Konstytucji RP, ze względu na brak wskazania kryteriów, jakimi należy kierować się przy decyzji o dystrybucji dodatkowych środków. Poprawka Senatu została odrzucona przez ówczesną większość sejmową.  Postulujemy przywrócenie dotychczasowego, dobrze funkcjonującego przepisu, który gwarantował bardziej transparentną procedurę dystrybucji dodatkowych środków w CBR. \\t\\fUwaga niezasadna \\fW ocenie Ministra Zdrowia konieczność określania CBR w drodze rozporządzenia jest zbędną biurokratyczna procedurą. Te same efekty bez żadnego uszczerbku dla systemu zostaną osiągnięte poprzez określenie tego podziału w planie finansowym funduszu.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 4a (nowy)\\tArt. 4a.  Przepis art. 4 nie dotyczy Wnioskodawcy uznanego za Partnera Bezpieczeństwa Lekowego.\\tDodanie art. 4a (wyłączenie paybacku) jest jednym z elementów proponowanego mechanizmu Partnera Bezpieczeństwa Lekowego. Mechanizm wspierania produkcji w Polsce za pomocą \\finstrumentów prawa refundacyjnego, oprócz wspierania refundacji konkretnych produktów, powinien odnosić się także do samego wnioskodawcy.  Proponuje się więc dodatkowo mechanizm (w nowo dodanym art. 12a i 12b – zob. dalej), który zagwarantuje firmom wytwarzającym co najmniej 25% swoich leków refundowanych lub co najmniej 100 mln jednostek leków rocznie na terenie Polski – stabilizację ekonomiczną i możliwość rozwoju. Takie rozwiązanie realizuje potrzeby Ministerstwa Zdrowia – zapewnienie ciągłości dostaw leków, a jednocześnie resortów gospodarczych, skutkując zwiększeniem inwestycji oraz działalności badawczo-rozwojowej w Polsce. Oddziałuje też pozytywnie na bilans handlowy kraju, rynek pracy oraz zwiększa wpływy budżetowe z podatków i innych danin.   Podniesie to konkurencyjność naszego kraju w zakresie lokowania inwestycji związanych z produkcją farmaceutyczną, o co dziś zabiega wiele krajów UE.\\t\\fUwaga niezasadna Minister Zdrowia wprowadził dodatkowy mechanizm rozszerzający preferencje, o których mowa w art. 6 ust. 2a oraz art. 13a ustawy o refundacji. \\fZdaniem Ministra Zdrowia regulacje dotyczące preferencji dla leków powinny odnosić się jedynie do leków w całości wytworzonych w Polsce. \\n\\tIzba Gospodarcza \\\"FARMACJA POLSKA\\\"\\tArt. 5 ustawy refundacyjnej\\tDlatego w naszej ocenie konieczne jest dodanie do projektu nowelizacji zmian w art. 5 poprzez wskazanie, że w sytuacji, gdy lek zawiera więcej niż jedną substancję czynną, za podstawę obliczeń, o których mowa w art. 4, 6, 7, 9 i art. 13–15 ustawy, przyjmuje się PDD uwzględniające każdą z substancji czynnych zawartych w tym leku. To rozwiązanie pozwoli na to, by w procesie negocjacji uzgodnić stosowną cenę dla różnych dawek tego samego SPC.  \\fPonadto wskazujemy na zasadność utworzenia odrębnych grup limitowych dla monoterapii oraz dla leków złożonych - osobno dla połączeń dwulekowych, trójlekowych, a nawet czterolekowych.\\t\\fZmiany zaproponowane w art. 30 ust. 5 ustawy, wprowadzające ułatwienia w postępowaniu refundacyjnym dotyczącym leku złożonego, dostępnego w aptece na receptę, oceniamy bardzo pozytywnie, jako redukujące czas i koszty wnioskodawcy. Stosowanie leków złożonych to rozwiązanie, które ma pozytywny wpływ na zwiększenie skuteczności leczenia poprzez poprawę przestrzegania zaleceń lekarskich (adherencja). \\fZwracamy jednak uwagę, że brak zmian w zakresie Art. 5 ustawy, dotyczącego wyliczania ceny za DDD takich leków, utrudni objęcie refundacją kolejnych produktów tego typu.  Błędnym podejściem jest określenie limitów finansowania dla takich preparatów w oparciu o koszt DDD tylko jednej substancji czynnej zawartej w produkcie. Przykładem, gdzie takie rozwiązanie jest i dalej będzie ogromną barierą wejścia do refundacji, jest połączenie substancji czynnych w niskich dawkach, np. w SPC trójskładnikowym, dla którego połączenie trzech niskich dawek cechuje się wyższą skutecznością niż lek jednoskładnikowy, w dawce wysokiej.  \\t\\fUwaga niezasadna Zasada 1+1=1 ma zastosowanie od 2012 r. i Minister Zdrowia nie widzi konieczności zmiany.  Dla produktów wieloskładnikowych projekt zakłada już wprowadzenie pewnych ułatwień np. zniesienie obowiązku dołączania pełnych analiz HTA, w przypadku leków, których składniki są już objęte refundacją w lekach jednoskładnikowych.  \\fOdnosząc się do uwagi dotyczącej tworzenia grup limitowych należy wskazać, że grupowanie leków w duże grupy limitowe zwiększa konkurencyjność cenową. W przypadku niekorzystnych efektów w każdym momencie Minister Zdrowia może dokonać wyodrębnienia osobnej grupy (art. 15 ust. 3). Jako przykład należy tu wskazać grupę 22.0 Heparyny drobnocząsteczkowe i leki o działaniu heparyn drobnocząsteczkowych, w której pozostawiono Heparyny drobnocząsteczkowe i wyodrębniono grupę 22.1 Leki przeciwzakrzepowe – bezpośrednie inhibitory trombiny i czynnika Xa.\\n\\tKonfederacja Lewiatan\\t art. 7 ust. 2 Ustawy  \\tArt. 7 ust. 2  Przedsiębiorcy prowadzący obrót hurtowy w rozumieniu art. 72 ust. 3 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne są obowiązani stosować cenę zbytu netto wraz z marżą, o której mowa w ust. 1, oraz właściwą stawkę podatku od towarów i usług niezależnie od miejsca dostawy leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego będącego przedmiotem tego obrotu.\\tObowiązek stosowania sztywnej marży w wysokości 6% przy sprzedaży produktów refundowanych niezależnie od miejsca dostawy – w tym również w ramach wewnątrzwspólnotowego obrotu – budzi wątpliwości co do efektywności tego środka w kontekście celu, w jakim został wprowadzony, tj. poprawy dostępności produktów leczniczych dla pacjentów w Polsce.  Przepis nie rozróżnia sytuacji, w których produkt rzeczywiście jest zagrożony brakiem dostępności na rynku krajowym, od sytuacji, gdy takie ryzyko nie występuje. W efekcie mechanizm sztywnej marży stosowany do całej grupy produktów refundowanych – jak wskazuje analiza Obwieszczeń Ministra Zdrowia w sprawie wykazu produktów \\fleczniczych, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych zagrożonych brakiem dostępności na terytorium Rzeczypospolitej Polskiej (potocznie zwana listą anty wywozową)– nie przyczynił się do poprawy dostępności leków w Polsce.  Dodatkowo, stosowanie sztywnych cen w obrocie wewnątrzwspólnotowym prowadzi do zmniejszenia wpływów budżetowych (w szczególności z tytułu CIT, PIT i VAT), bez proporcjonalnej korzyści dla systemu ochrony zdrowia.  Dane potwierdzające nieskuteczność mechanizmu sztywnej marży :  Analiza Obwieszczeń Ministra Zdrowia (potocznie - lista anty wywozowa) po 1 roku i 6 miesiącach obowiązywania znowelizowanej ustawy refundacyjnej:  Obwieszczenie z 11.10.2023 r. (ostatnia lista przed obowiązywaniem zapisów z ustawy): 288 produktów na ilości w różnej wielkości opakowań, na wykazie bez podziału na wielkości opakowań 222 produkty  Obwieszczenie z 08.05.2025 r. (najnowsze obwieszczenie): 379 produktów na ilości w różnej wielkości opakowań , na wykazie bez podziału na wielkości opakowań 276 produkty   Zmiany:  \\f20 pozycji usuniętych (poprawa dostępności),  111 pozycji nowo dodanych (pogorszenie dostępności),  Wzrost liczby produktów 24,3%, co przeczy skuteczności regulacji obowiązującej od listopada 2023 r.  Brak efektów w dostępności:  207 spośród 222 produktów z 2023 r. nadal znajduje się na wykazie w 2025 r. (ponad 93% bez poprawy),  Ministerstwo Zdrowia posiada ZSMPOL - analityczne narzędzie do skutecznej oceny który umożliwia:  identyfikację transakcji krajowych i zagranicznych (m.in. poprzez numery NIP z prefiksem kraju),  śledzenie wolumenów i wartości sprzedaży,  ocenę realnego wpływu obrotu wewnątrzwspólnotowego na dostępność poszczególnych produktów.   Praktyki regulacyjne w Unii Europejskiej  W wielu krajach UE funkcjonują listy produktów zagrożonych, których obrót wewnątrzwspólnotowy wymaga zgody regulatora.  Żadne inne państwo członkowskie nie stosuje cen urzędowych do obrotu wewnątrzwspólnotowego – Polska jest w tym zakresie wyjątkiem.   Wprowadzenie sztywnej marży nie przyniosło oczekiwanej poprawy \\fdostępności leków – przeciwnie, liczba pozycji na wykazie wzrosła. Polska jako jedyny kraj UE stosuje sztywną regulację cenową na rynek zewnętrzny – brak analogicznych praktyk w pozostałych krajach wspólnoty. Pełniejsze wykorzystanie danych ZSMOPL przez Regulatora umożliwiłoby skuteczniejszą, opartą na dowodach politykę lekową. Stosowanie sztywnych marż w przypadku sprzedaży wewnątrzwspólnotowej powoduje, iż leki z Polski stały się znacznie tańsze przyczyniając się do wzrostu ich atrakcyjności dla kontrahentów zagranicznych. W efekcie dochodzi do zwiększenia skali sprzedaży wewnątrzwspólnotowej, co stoi w sprzeczności z zamierzonym celem regulacji, jakim była poprawa dostępności leków na rynku krajowym.\\t\\fUwaga niezasadna Zdaniem organu obowiązek stosowania sztywnej marży w wysokości 6% przy sprzedaży produktów refundowanych niezależnie od miejsca dostawy jest jednym z narzędzi zapobiegania nadmiernego wywożenia refundowanych leków z terenu Rzeczypospolitej Polskiej, z którego nie należy rezygnować, ani zmieniać jego kształtu. Należy zauważyć, że sztywne ceny i marże są wprowadzone jedynie dla produktów objętych refundacją. Resztą produktów można handlować bez tego ograniczenia. Natomiast dowolność stosowania marży dla refundowanych produktów wywożonych poza granice powodowała, że taka sprzedaż była bardziej opłacalna niż sprzedaż dla polskich świadczeniobiorców.  Usuwanie produktów z wykazu, o którym mowa w art. 37 ust. 1 ustawy o refundacji \\fnie ma związku z dostępnością refundowanych produktów znajdujących się na tym wykazie. \\n\\tPracodawcy RP\\tArt. 7 ust. 2 i art. 8 ust. 2\\tW odniesieniu do  art. 7 ust. 2 proponujemy następującą zmianę: „2. Przedsiębiorcy prowadzący obrót hurtowy w rozumieniu art. 72 ust. 3 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne są obowiązani stosować cenę zbytu netto wraz z marżą, o której mowa w ust. 1, oraz właściwą stawkę podatku od towarów i usług niezależnie od miejsca państwa dostawy leku, środka spożywczego specjalnego przeznaczenia \\fżywieniowego lub wyrobu medycznego będącego przedmiotem tego obrotu. art. 8 proponujemy oznaczenie dotychczasowej treści jako ust. 1 i dodanie ust. 2 w brzmieniu:  „2. Przepisy ust. 1 oraz art. 9 ust. 1–2a nie stosują się do transakcji na terytorium Rzeczypospolitej Polskiej, które w całości są przeprowadzane poza systemem refundacji.”\\t\\fPrzepis art. 7 ust. 2 został zmieniony nowelizacją z 2023 r. i wydaje się, że jego celem była walka z wywozem leków z Polski (wynika to zarówno z brzmienia uzasadnienia do projektu DNUR („Proponowana zmiana w art. 7 ust. 2 ustawy refundacyjnej ma na celu doprecyzowanie i usunięcie wątpliwości, że marże urzędowe obowiązują również w odniesieniu do transakcji dotyczących sprzedaży leków poza granice Rzeczpospolitej Polskiej”), jak i faktu, że przepis posługuje się pojęciem „miejsca”, a nie – jak w innych przepisach ustawy \\frefundacyjnej – pojęciem „podmiotu” (świadczeniodawca, przedsiębiorca prowadzący obrót hurtowy). Niestety, obecnie, przepis ten budzi wątpliwości i jest przez niektórych interpretowany rozszerzająco jako obowiązek stosowania cen i marż urzędowych w przypadku sprzedaży leków poza systemem refundacji (np. na potrzeby badań klinicznych czy sprzedaży na rynku prywatnym).  Celem wykluczenia takich wątpliwości zasadnym jest potwierdzenie, że przepis ten dotyczy sprzedaży niezależnie od państwa dostawy (a więc wskazanie na obowiązek stosowania ceny i marż urzędowych w przypadku sprzedaży leków poza granice Polski i to niezależnie od celu). Innym przepisem powiązanym z tym samym problemem jest art. 8 ustawy refundacyjnej. Ten przepis również budzi wątpliwości i jest przez niektórych interpretowany rozszerzająco jako obowiązek stosowania cen i marż urzędowych w przypadku sprzedaży leków poza systemem refundacji w Polsce (np. na potrzeby badań klinicznych czy sprzedaży na rynku prywatnym). Takie podejście, w przypadku transakcji przeprowadzanych w Polsce nie ma uzasadnienia (skoro lek miałby być sprzedany np. celem dostarczenia do \\fpacjentów w badaniu klinicznym lub na rynku prywatnym), poniżej argumenty: Jedynym z celów ustawy refundacyjnej (wskazanym w jej uzasadnieniu) jest zapewnienie, aby Narodowy Fundusz Zdrowia czy inny płatnik publiczny nie płacił zbyt dużo za leki (a więc aby mógł kontrolować koszty tych produktów). Nie ma więc uzasadnienia, aby wskazane regulacje cenowe obejmowałby także leki w ramach sprzedaży komercyjnej – ponieważ nie są one finansowane/współfinansowane przez płatnika publicznego; Urzędowe ceny zbytu (od 1 listopada 2023 r. ceny zbytu netto) są określone bezpośrednio w decyzjach refundacyjnych, które precyzują wskazanie terapeutyczne oraz model dystrybucji w ramach refundacji (jest to wskazane w punkcie: kategoria dostępności refundacyjnej). Wobec tego, ceny powinny mieć zastosowanie tylko w tym zakresie (co jest istotnym argumentem np. przy sprzedaży leków na potrzeby badań klinicznych oraz sprzedawanie leków z refundacji aptecznej do podmiotów leczniczych); \\fUstawa refundacyjna wprost odnosi się do sytuacji, w której świadczeniodawcy nabywają produkty do stosowania w ramach świadczeń gwarantowanych (w tym programów lekowych i chemioterapii). W konsekwencji w ramach sprzedaży komercyjnej, gdzie np. podmiot leczniczy nie jest świadczeniodawcą (nie ma umowy z NFZ) i/albo nie udziela świadczenia gwarantowanego, nie powinny być stosowane te przepisy.  Dlatego wobec potrzeby wyeliminowania tych wątpliwości i potwierdzenia dotychczasowej praktyki Ministerstwa Zdrowia, zasadnym jest wprost wskazanie, że ceny i marże urzędowe oraz ceny maksymalne nie obowiązują w transakcjach przeprowadzanych w Polsce, jeżeli produkty od początku (to jest od wprowadzenia leku do Polski) do końca znajdują się poza systemem refundacji (tj. na żadnym etapie łańcucha dystrybucyjnego nie były dystrybuowane celem sfinansowania leku ze środków publicznych). Proponowane zmiany klarują sytuację prawną, nie narzucając żadnych \\fdodatkowych obowiązków na uczestników rynku. Dodatkowo jest z tym powiązana zmiana dot. art. 7 ust. 2, z której wprost wynika, że w przypadku sprzedaży poza Polskę hurtownia farmaceutyczna będzie musiała stosować urzędowe ceny i marże (co jest zasadnym instrumentem na przeciwdziałanie wywozowi leków z Polski).\\t\\fUwaga niezasadna Zdaniem organu obowiązek stosowania sztywnej marży w wysokości 6% przy sprzedaży produktów refundowanych niezależnie od miejsca dostawy jest jednym z narzędzi zapobiegania nadmiernego wywożenia refundowanych leków z terenu Rzeczypospolitej Polskiej, z którego nie należy rezygnować, ani zmieniać jego kształtu. Nie powinno się robić też wskazanych przez zgłaszającego uwagę wyjątków. Co tylko powoduje większe komplikacje w systemie refundacyjnym i może tworzyć nowe luki prawne.  \\f Należy zauważyć, że sztywne ceny i marże są wprowadzone jedynie dla produktów objętych refundacją. Resztą produktów można handlować bez tego ograniczenia. Natomiast dowolność stosowania marży dla refundowanych produktów wywożonych poza granice powodowała, że taka sprzedaż była bardziej opłacalna niż sprzedaż dla polskich świadczeniobiorców. \\n\\tPolskie Towarzystwo Farmakoekonomiczne\\tArt. 1 ust. pkt 2 tiret 1 odnoszący się do art. 6 ust. 1 pkt. 2a\\tDoprecyzowanie zapisów dotyczących tzw. czwartej kategorii dostępności AOS (Art. 6 ust.1 pkt 2a UR)  \\tMożliwość przesunięcia leków z programu lekowego do AOS a także składania wniosków refundacyjnych bezpośrednio do kategorii dostępności AOS zasługuje na uznanie, warto jednak rozszerzyć ten zakres również   na leki stosowane w opiece psychiatrycznej i leczeniu uzależnień art. 15 ust. 2 pkt 4, czyli zmienić aktualny przepis w proponowanym 2a) z „o których mowa w art. 15 ust. 2 pkt 2 i 3” na odpowiednio “o których mowa w art. 15 ust. 2 pkt 2-4.” Warto dodatkowo rozważyć, czy nie powinien to być dodawany ust. 1 pkt 3a a nie 2a gdyż bardziej pasuje logiką do pkt 3 a nie 2. • W proponowanym dodawanym ust. 2b na końcu należałoby również umożliwić wskazanie specjalizacji lekarskiej odpowiednio również do kategorii dodawanej w ust. 2a czyli koniec tego ustępu brzmiałby „w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1, 2 i 2a.”  \\f• Jednakże propozycje funkcjonowania takiej ścieżki w zakresie zasad dystrybucji, zasad stosowania cen, czy odpowiedzialności za prowadzenie terapii nie są w naszym mniemaniu wyczerpująco opisane w ustawie. Dlatego postulujemy dalsze prace nad uzupełnieniem tych elementów.  \\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolskie Towarzystwo Reumatologiczne \\tdodanie w art. 6 ust. 1a\\tW art. 6 po ustępie 1 dodaje się ust. 1a w brzmieniu: „1a. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia kryteria dla leków stosowanych w chorobach innych niż onkologiczne, dla których może zostać wydana decyzja administracyjna o objęciu refundacją w zakresie nadanej kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 2a.” \\tPropozycja dodania nowego ust 1a do art. 6.  Możliwość refundacji leków w nowej czwartej kategorii dostępności powinna podlegać jasnym kryteriom. Kryterium tzw. „generyzacji” czyli w przypadku leków biologicznych rejestracji leków biopodobnych, a w przypadku leków syntetycznych celowanych rejestracji leków generycznych, nie powinno być jedynym kryterium.  W przypadku reumatologii, jeden lek biologiczny biopodobny z uwagi na remonopolizację rynku jest istotnie droższy niż wiele innych leków biologicznych referencyjnych oraz syntetycznych celowanych. Brak przepisu wskazującego na konieczność określenia kryteriów może budzić w przyszłości podejrzenie braku transparentności w procesie podejmowania konkretnych decyzji refundacyjnych.\\tUwaga niezasadna Dla katalogu chemioterapii nie istnieje obowiązek prawy ustalenia kryteriów przez MZ. Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej  \\n\\tOsoba fizyczna  \\tArt. 6 ust. 10 (dodanie pkt. 3)\\t„3) Minister zdrowia ustala corocznie, nie później niż do dnia 30 września danego roku, wykaz limitów finansowania, o \\fktórych mowa w ust. 10 pkt 1) i 2). Limity te obowiązują od dnia 1 stycznia następnego roku.” \\t\\fWprowadzenie corocznego mechanizmu aktualizowania limitów finansowania ma na celu zapewnienie równowagi \\fekonomicznej pomiędzy uczestnikami rynku ochrony zdrowia, podmiotami uczestniczącymi w obrocie produktami, o których mowa w art. 6, ust. 10 a instytucjami finansującymi i regulującymi ten rynek. Regularne dostosowywanie tych limitów do aktualnych realiów rynkowych pozwoli uniknąć sytuacji podobnej do tej, jaka miała miejsce w przypadku rozporządzenia określającego wysokość taksy laborum, które pozostawało niezmienione przez 19 lat – od 2005 roku, aż do jego aktualizacji w 2024 roku.    ROZPORZĄDZENIE MINISTRA ZDROWIA z dnia 17 grudnia 2004 r. w sprawie wykazu leków, które mogą być traktowane jako surowce farmaceutyczne, wysokości opłaty ryczałtowej za leki podstawowe i recepturowe, ilości leku recepturowego, którego dotyczy opłata ryczałtowa, oraz sposobu obliczania kosztu sporządzania leku recepturowego ROZPORZĄDZENIE MINISTRA ZDROWIA z dnia 14 lutego 2024 r. zmieniające rozporządzenie w sprawie leków, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych.   Brak aktualizacji przez tak długi okres doprowadził do ogromnej rozbieżności między rzeczywistymi kosztami sporządzania leków recepturowych a ich urzędową wyceną. Coroczna aktualizacja limitów zapewni stabilność rynku, sprawiedliwość i adekwatność systemu finansowania przy jednoczesnym \\fzachowaniu kontroli nad tą kategorią produktów.  Ponadto, ustalenie terminu corocznej aktualizacji limitów do 30 września, które będą obowiązywały od 1 stycznia następnego roku, zapewni wszystkim uczestnikom rynku wystarczający czas na przygotowanie się do zmian. Trzymiesięczne vacatio legis sprawi, że nowe limity nie będą wprowadzane z dnia na dzień, co zminimalizuje ryzyko dezorganizacji i nieprzewidzianych skutków. \\t\\fUwaga niezasadna Proponowany zapis nakłada obowiązek corocznego aktualizowania wykazów, \\fbez względu na istnienie rzeczywistej potrzeby dokonania takiej aktualizacji. Proces legislacyjny jest procesem czasochłonnym i angażującym znaczne zasoby osobowe, tym samym proponowany zapis stanowiłby zbytnie obciążenie w stosunku do celu jakiemu miałby służyć. Wykazy powinny być aktualizowane w przypadku stwierdzenia takiej potrzeby.  \\n\\tOsoby fizyczne – pismo zbiorowe\\tart. 1 pkt 2 lit. c odnoszący się do art. 6 ust. 5 ustawy\\tWyrażamy również głębokie zaniepokojenie i stanowczy sprzeciw wobec propozycji zmiany art. 6 ust. 5 ustawy o refundacji, który w obecnej formie brzmi: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego jest mniejsza od najmniejszej dawki leku gotowego w formie stałej stosowanej doustnie.”  Projekt zakłada usunięcie z przepisu sformułowania „w formie stałej stosowanej doustnie”. Ta pozornie techniczna korekta jest w rzeczywistości drastycznym ograniczeniem możliwości terapeutycznych, a jej skutki będą dotkliwe zarówno dla pacjentów, jak i dla całego systemu. \\fObowiązujący przepis, co potwierdza m.in. pismo Ministerstwa Zdrowia (PLO.461.82.2015.MW) z 2015 roku, ma charakter precyzyjnie ukierunkowanego zabezpieczenia. Jego celem jest zapobieganie nadużyciom polegającym na obchodzeniu braku refundacji doustnych leków gotowych poprzez ich proste rozproszenie i przepisanie jako refundowanego leku recepturowego. Warunek, aby dawka leku recepturowego była mniejsza niż dawka użytego leku gotowego, słusznie dotyczy tylko refundowanych leków w stałej formie doustnej. Proponowana zmiana, poprzez wykreślenie kluczowego ograniczenia, rozszerza ten warunek na wszystkie postaci leku, co jest działaniem nieproporcjonalnym i szkodliwym.\\t\\fKonsekwencje tego zapisu będą następujące: Eliminacja kluczowych terapii i technik farmaceutycznych. Zmiana uniemożliwi refundację powszechnie stosowanych i często niezastąpionych procedur recepturowych. Nowy przepis ignoruje fakt, że indywidualizacja terapii polega nie tylko na zmianie dawki, ale również na modyfikacji postaci leku, w tym podłoża. Konsekwentnie, zablokowane zostaną takie praktyki jak: Modyfikacja podłoża: W wielu przypadkach, zwłaszcza w dermatologii, pacjent wymaga zastosowania substancji czynnej w tym samym stężeniu co w leku gotowym, ale w innym podłożu (np. z \\fpowodu alergii na składniki pomocnicze, potrzeby zastosowania podłoża o innych właściwościach fizykochemicznych). Proponowana zmiana, skupiając się wyłącznie na dawce (stężeniu), uniemożliwi refundację takiej terapii. Sporządzanie zindywidualizowanych dawek pediatrycznych: Uniemożliwiona zostanie refundacja leków dla dzieci, których przygotowanie wymaga modyfikacji stężenia leku gotowego (np. syropu), a docelowa dawka nie jest niższa niż w preparacie wyjściowym. Pozbawienie pacjentów dostępu do leczenia o wyższym stężeniu. Jednym z fundamentalnych założeń receptury jest możliwość przygotowania leku o stężeniu substancji czynnej wyższym niż dostępne w obrocie preparaty gotowe. Jest to standardem postępowania klinicznego w wielu dziedzinach, m.in. w dermatologii, gdzie terapia często wymaga \\fstopniowego zwiększania mocy preparatu. Projektowany przepis, uzależniając refundację od dawki mniejszej niż w leku gotowym, całkowicie zamyka tę ścieżkę terapeutyczną w ramach ubezpieczenia. Pacjenci, dla których lekarz ordynuje lek recepturowy o stężeniu wyższym niż najmocniejszy lek gotowy, zostaną pozbawieni możliwości refundacji, co zmusi ich do ponoszenia pełnej odpłatności za leczenie lub skazuje na terapię o suboptymalnej, niższej skuteczności. W naszej ocenie jest to zapis szkodliwy, który pod pozorem uszczelniania systemu ogranicza dostęp do skutecznego leczenia. \\t\\fUwaga częściowo uwzględniona Projektodawca wprowadził stosowną modyfikację mającą na celu pogodzenie rozwoju praktyki farmaceutycznej oraz potrzeb pacjentów z zapewnieniem stabilności i bezpieczeństwa finansowego systemu refundacyjnego.  Zaproponowano nowe brzmienie ust. 5: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego jest mniejsza od najmniejszej dawki leku gotowego w formie stałej stosowanej doustnie. Przepis nie ma zastosowania w przypadku sporządzania leków recepturowych o innej drodze podania niż użyty lek gotowy lub dostępności preparatów gotowych w zaordynowanej dawce lub stężeniu.”\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 7 ust. 2 oraz art. 8 ust. 2 ustawy refundacyjnej\\tArt. 7 ust. 2. Przedsiębiorcy prowadzący obrót hurtowy w rozumieniu art. 72 ust. 3 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne są obowiązani stosować cenę zbytu netto wraz z marżą, o której mowa w ust. 1, oraz właściwą stawkę podatku od towarów i usług niezależnie od miejsca państwa dostawy leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego będącego przedmiotem tego obrotu. Art. 8 ust. 2. Przepisy ust. 1 oraz art. 9 ust. 1 – 2a nie stosują się do transakcji na terytorium Rzeczypospolitej Polskiej, które \\fw całości są przeprowadzane poza systemem refundacji.\\t\\fPrzepis art. 7 ust. 2 został zmieniony nowelizacją z 2023 r. Wydaje się, że jego celem była walka z wywozem leków z Polski (na co wskazuje treść uzasadnienia: „Proponowana zmiana w art. 7 ust. 2 ustawy refundacyjnej ma na celu doprecyzowanie i usunięcie wątpliwości, że marże urzędowe obowiązują również w odniesieniu do transakcji dotyczących sprzedaży leków poza granice Rzeczpospolitej Polskiej.”).  Niestety pomimo tak wyraźnego kontekstu, obecnie, przepis ten budzi niekiedy wątpliwości i jest przez niektórych (niesłusznie) interpretowany \\frozszerzająco jako obowiązek stosowania cen i marż urzędowych w przypadku sprzedaży leków poza systemem refundacji (np. na potrzeby badań klinicznych czy sprzedaży na rynku prywatnym).  Celem wykluczenia takich wątpliwości  zasadnym jest potwierdzenie, że przepis ten dotyczy sprzedaży niezależnie od państwa dostawy (a więc wskazanie na obowiązek stosowania ceny i marż urzędowych w przypadku sprzedaży leków poza granice Polski i to niezależnie od celu). Innym przepisem powiązanym z tym samym problemem jest art. 8 ustawy refundacyjnej (i pośrednio art. 9 w kontekście cen maksymalnych). Ten przepis również niekiedy budzi wątpliwości i jest przez niektórych (niesłusznie) interpretowany rozszerzająco jako obowiązek stosowania cen i marż urzędowych w przypadku sprzedaży leków poza systemem refundacji w Polsce (np. na potrzeby badań klinicznych czy sprzedaży na rynku prywatnym). Takie podejście, w przypadku transakcji przeprowadzanych w Polsce nie ma uzasadnienia (skoro lek miałby być sprzedany np. celem dostarczenia do pacjentów w badaniu klinicznym). Dlatego wobec potrzeby wyeliminowania tych wątpliwości i potwierdzenia dotychczasowej praktyki Ministerstwa Zdrowia, zasadnym jest wprost wskazanie, że ceny i marże urzędowe oraz ceny maksymalne nie obowiązują w transakcjach \\fprzeprowadzanych w Polsce, jeżeli produkty od początku (to jest od wprowadzenia leku do Polski) do końca znajdują się poza systemem refundacji (tj. na żadnym etapie łańcucha dystrybucyjnego nie były dystrybuowane celem sfinansowania leku ze środków publicznych). Dodatkowo jest z tym powiązana zmiana dot. art. 7 ust. 2, z której wprost wynika, że w przypadku sprzedaży poza Polskę hurtownia farmaceutyczna będzie musiała stosować urzędowe ceny i marże (co jest zasadnym instrumentem na przeciwdziałanie wywozowi leków z Polski).\\t\\fUwaga niezasadna  Zdaniem organu obowiązek stosowania sztywnej marży w wysokości 6% przy sprzedaży produktów refundowanych niezależnie od miejsca dostawy jest jednym z narzędzi zapobiegania nadmiernego wywożenia refundowanych leków z terenu Rzeczypospolitej Polskiej, z którego nie należy rezygnować, ani zmieniać jego kształtu. Nie powinno się robić też wskazanych przez zgłaszającego uwagę wyjątków. Co tylko powoduje większe komplikacje w systemie refundacyjnym i może tworzyć nowe luki prawne.  \\f Należy zauważyć, że sztywne ceny i marże są wprowadzone jedynie dla produktów objętych refundacją. Resztą produktów można handlować bez tego ograniczenia. Natomiast dowolność stosowania marży dla refundowanych produktów wywożonych poza granice powodowała, że taka sprzedaż była bardziej opłacalna niż sprzedaż dla polskich świadczeniobiorców. Dodatkowo należy wskazać, że Ministerstwo Zdrowia od czasu nowelizacji z dnia 17 sierpnia 2023 r.  zawsze wskazywało, że przepisy o cenach i marży na leki refundowane powinny być stosowana także w przypadku sprzedaży leków do badań klinicznych.\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tart. 7 ust. 7a ustawy refundacyjnej\\t7a. Dla produktów leczniczych z importu równoległego objętych refundacją ustala się marżę hurtową w wysokości 10%. Marża detaliczna wynosi 100% wartości urzędowej marży detalicznej ustalonej w ust. 4 dla danego przedziału ceny hurtowej.\\tW celu zachęcenia dystrybutorów do sięgania po produkty pochodzące z importu równoległego, a podlegające refundacji należy stworzyć preferencyjne warunki marżowe dla takich produktów (analogiczne jak w przypadku produktów pochodzących z tzw. importu interwencyjnego). W przeciwnym wypadku sprzedaż refundowanych produktów leczniczych z importu równoległego będzie opłacalna dla wszystkich uczestników rynku poza dystrybutorami, którzy związani sztywną marżą będą preferować droższe produkty (na których uzyskają większy zysk).  Od Kancelaria Radcy Prawnego Tomasz Dauerman: Proponujemy uproszczenie systemu ustalania i naliczana marż urzędowych poprzez wskazanie tej samej wysokości marży zarówno w przypadku produktów wprowadzanych w trybie art. 39 ust. 1 \\fPrawa farmaceutycznego, jak i w trybie art. 4a Prawa farmaceutycznego, ze względu na systemowe podobieństwa obu trybów. Powyższe uprości i przyspieszy proces nakładania marż dla podmiotów zobowiązanych. W przeciwnym wypadku sprzedaż refundowanych produktów leczniczych z importu równoległego będzie opłacalna dla wszystkich uczestników rynku poza hurtownikami, którzy związani sztywną marżą będą preferować droższe produkty (na których uzyskają większy zysk).\\t\\fUwaga niezasadna Wprowadzenie nowego art. 7 ust. 7a do ustawy o refundacji jest niezasadne. Wprowadzenie jednolitej, sztywnej marży na produkty importu równoległego, niezależnie od specyfiki i zmienności rynku, może prowadzić do naruszenia zasady równości podmiotów na rynku farmaceutycznym, w tym przede wszystkim nierównego traktowania podmiotów importujących równolegle w porównaniu do producentów krajowych, co w efekcie może wpłynąć na konkurencyjność i dostępność leków. Brak uwzględnienia specyfiki produktów importowanych równolegle w kontekście różnic w procesie dystrybucji i dodatkowych kosztów związanych z tym typem importu może prowadzić do zniekształcenia konkurencji i negatywnych konsekwencji rynkowych. W związku z tym, propozycja ta wydaje się nieuzasadniona z punktu widzenia \\fefektywności rynku oraz zasad konkurencji.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 9 ust. 2 ustawy refundacyjnej\\t2. Świadczeniodawca jest obowiązany nabywać leki, oraz środki spożywcze specjalnego przeznaczenia żywieniowego oraz wyroby medyczne, dla których ustalono kategorie dostępności refundacyjnej, o których mowa w art. 6 ust. 1 pkt 2 i 3, po cenie nie wyższej niż urzędowa cena zbytu leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego: 1) leku stanowiącego podstawę limitu, w przypadku leku zawierającego tę samą substancję czynną co lek wyznaczający podstawę limitu, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, jednak nie wyższą niż urzędowa cena zbytu danego leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, albo 2) leku będącego najtańszym odpowiednikiem nabywanego leku, w przypadku gdy podstawę limitu w danej grupie limitowej wyznacza lek z inną substancją czynną, a koszt DDD każdego z \\fodpowiedników jest większy niż koszt DDD leku wyznaczającego podstawę limitu, jednak nie wyższą niż urzędowa cena zbytu danego leku, albo 3) leku będącego najdroższym odpowiednikiem nabywanego leku, którego cena zbytu netto za DDD nie przekracza ceny zbytu netto za DDD leku wyznaczającego podstawę limitu, w przypadku gdy podstawę limitu w danej grupie limitowej wyznacza lek z inną substancją czynną, a koszt DDD przynajmniej jednego odpowiednika jest nie większy niż koszt DDD leku wyznaczającego podstawę limitu, jednak nie wyższą niż urzędowa cena zbytu danego leku, albo 4) danego leku, w przypadku leku nieposiadającego odpowiednika, gdy podstawę limitu w danej grupie limitowej wyznacza lek z inną substancją czynną, albo 5) środka spożywczego specjalnego przeznaczenia żywieniowego stanowiącego podstawę limitu w przypadku środka spożywczego specjalnego przeznaczenia żywieniowego, jednak nie wyższą niż urzędowa cena zbytu danego środka spożywczego specjalnego przeznaczenia żywieniowego - uwzględniając liczbę DDD leku albo, jednostek środka spożywczego specjalnego przeznaczenia żywieniowego w opakowaniu albo liczbę jednostkowych wyrobów medycznych, albo liczbę jednostek wyrobu medycznego, powiększoną o marżę nie wyższą niż urzędowa marża hurtowa, a w przypadku nabywania od podmiotu innego niż \\fprzedsiębiorca prowadzący obrót hurtowy w rozumieniu art. 72 ust. 3 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne - po cenie nie wyższej niż urzędowa cena zbytu.\\t\\fPrzedkładana poprawka jest konieczna w celu wyklarowania sytuacji dla świadczeniodawców i podmiotów prowadzących obrót lekami.  Nowelizacja z 2023 r. zmodyfikowała dotychczasowe brzmienie art. 9 ust. 2, który reguluje po jakiej cenie maksymalnej świadczeniodawcy mogą nabyć leki czy środki spożywcze specjalnego przeznaczenia żywieniowego celem ich zastosowania w programach lekowych lub chemioterapii (co ma istotne znaczenie w perspektywie rozliczeń z Narodowym Funduszem Zdrowia). Niestety przy okazji uchwalenia poprawki doszło do: a) braku wykreślenia z treści przepisu wyrobów medycznych (nie podlegają one refundacji w ramach programów lekowych oraz chemioterapii; wcześniej były w przepisie, gdyż obejmował on swoim zakresem także kategorię \\frefundacyjną z art. 6 ust. 1 pkt 1 tzn. tzw. „refundację apteczną”), oraz b) braku uwzględnienia sytuacji, w której lek z substancją czynna A, który nie ma odpowiednika może znajdować się w grupie limitowej z lekami z substancją czynna B i to jeden z takich leków wyznacza podstawę limitu. Proponowana poprawka naprawia te dwa niedopatrzenia, ułatwiając przy tym sytuację prawną dla świadczeniodawców. Warto uwzględnić przy tych zmianach także analogiczne zmiany jak do art. 13 ust. 6 pkt 2 UR.\\t\\fUwaga uwzględniona w części  Z projektu wykreślono z art. 9 ust. 2 ustawy o refundacji wyrazów „wyrobów medycznych”. \\n\\tOsoba fizyczna \\tart. 1 ust. 4 projektu odnoszący się do art. 7 – usunięcie ust. 1a lub wdrożenie alternatywnego brzmienia w zaproponowanej formie\\t„4) w art. 7: a) w ust. 1 we wprowadzeniu do wyliczenia wyrazy „50 groszy” zastępuje się wyrazami „80 groszy”, b) po ust. 1 dodaje się ust. 1a w brzmieniu: 1a. Ustala się urzędową marżę hurtową w wysokości 6% ceny: 1) surowców farmaceutycznych; 2) utensyliów recepturowych, o których mowa w art. 6 ust. 10 pkt 2; 3) leków gotowych, które mogą być traktowane jako surowce farmaceutyczne podczas sporządzania leku recepturowego.” Propozycja alternatywnego brzmienia: „1a. Ustala się urzędową marżę hurtową w wysokości 6% ceny, ale nie niższą niż 80 groszy: 1) surowców farmaceutycznych; 2) utensyliów recepturowych, o których mowa w art. 6 ust. 10 pkt 2; 3) leków gotowych, które mogą być traktowane jako surowce farmaceutyczne podczas sporządzania leku recepturowego.” \\tDodanie ust. 1a w proponowanym brzmieniu jest niezasadne, ponieważ wymienione w tym ustępie surowce farmaceutyczne, utensylia recepturowe i leki gotowe, które mogą być traktowane jako surowce farmaceutyczne, są objęte limitami finansowania na podstawie art. 6 ust. 8a (surowce) i ust. 10 (utensylia i leki gotowe). Proponowany mechanizm finansowania tych produktów jest odmienny od zasad stosowanych wobec leków gotowych, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, o których mowa w ust. 1, i które podlegają odrębnym regułom refundacyjnym. Dublowanie regulacji dla produktów już objętych limitami finansowania jest rozwiązaniem zbędnym i systemowo szkodliwym. Prowadzi do niepotrzebnej komplikacji przepisów, utrudnia ich jednolite stosowanie i zwiększa ryzyko dezorganizacji w realizacji świadczeń refundowanych. Dla zachowania spójności planowanych zmian, przejrzystości przepisów właściwe jest pozostawienie tylko jednego mechanizmu kontroli kosztów refundacji dla surowców farmaceutycznych, utensyliów recepturowych i leków gotowych, które mogą być traktowane jako surowce farmaceutyczne, tj. limitów finansowania \\fustalanych przez Ministra Zdrowia lub ogłaszanych przez Prezesa NFZ. Alternatywne brzmienie przepisu: „Uzasadnienie oraz proponowane rozwiązanie są spójne z treścią dokumentu \\\"Ocena Skutków Regulacji\\\" (OSR) dla art. 7 ust. 1 ustawy refundacyjnej.” \\t\\fUwaga niezasadna Wprowadzenie minimalnej wysokości marży hurtowej w proponowanej wysokości w przypadku niektórych utensyliów może znacząco wpłynąć na ich cenę. Tym samym zasadne jest pozostawienie zapisu w dotychczasowym brzmieniu tj. ustalającym wysokość marży hurtowej wyłącznie jako % ceny.\\n\\tOsoba fizyczna    \\tart. 1 pkt 4 lit. d odnoszący się do art. 7 ust. 8\\tKolejnym rozwiązaniem, które budzi nasz stanowczy sprzeciw, jest propozycja zmiany zasad naliczania marży detalicznej na lek recepturowy. Projekt zakłada zmianę art. 7 ust. 8 ustawy o refundacji, w efekcie której maksymalna wysokość marży detalicznej będzie mogła wynosić nie więcej niż koszt wykonania leku przygotowywanego w warunkach innych niż aseptyczne. \\toznacza to, że nawet jeśli farmaceuta sporządzi lek jałowy (np. krople do oczu), co jest czynnością znacznie bardziej pracochłonną, kosztowną i wymagającą zachowania najwyższych standardów jakościowych, jego marża zostanie ograniczona do poziomu przewidzianego dla leków niejałowych. Jest to rozwiązanie głęboko niesprawiedliwe i nieracjonalne ekonomicznie, które bezpośrednio uderza w rentowność wykonywania najbardziej zaawansowanych leków recepturowych. Co więcej, limitowanie wysokości marży, przy jednoczesnym jej uzależnieniu od kosztu sporządzenia leku, będzie wprost zniechęcać do stosowania nowoczesnych, często droższych surowców i opakowań, ponieważ apteka nie uzyska z tego tytułu odpowiedniej rekompensaty. Dodatkowo, projekt całkowicie pomija specyfikę ekonomiczną prowadzenia receptury. Farmaceuci często zmuszeni są do zakupu surowców w opakowaniach znacznie większych niż wymagane do jednorazowego \\fsporządzenia leku. Przy braku pewności co do ciągłości preskrypcji, surowce te nierzadko ulegają przeterminowaniu, generując straty dla apteki. Marża na lek recepturowy jest kluczowym elementem, który pozwala amortyzować to ryzyko. Jej obniżenie i sztywne ograniczenie podważy ten mechanizm. W połączeniu z drastycznym wzrostem obciążeń biurokratycznych, zmiana ta tworzy spójny, lecz negatywny obraz, w którym od farmaceutów oczekuje się więcej pracy za mniejsze wynagrodzenie. Istnieje realne ryzyko, że taka polityka doprowadzi do dalszego ograniczania lub całkowitej rezygnacji z wykonywania receptury przez apteki, co ostatecznie odbije się na pacjentach.\\t\\fUwaga zasadna Proponowana zmiana została usunięta z projektu.\\n\\tOsoba fizyczna \\tArt. 1 ust. 2 lit f odnoszący się do art. 6 ustawy refundacyjnej\\tProponuje się, aby ust. 12 otrzymał następujące brzmienie:   „12. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, receptariusz leków recepturowych finansowanych ze środków publicznych, stosowanych w danych dziedzinach medycyny, mając na względzie potrzebę zapewnienia odpowiedniej jakości i skuteczności leku recepturowego oraz wspomagania i ujednolicania preskrypcji leków recepturowych. Receptariusz ten podlega corocznej aktualizacji.”\\tWprowadzenie zasady corocznej aktualizacji receptariusza ma na celu zapewnienie jego bieżącej przydatności, zgodności z aktualnym stanem wiedzy medycznej i farmaceutycznej, oraz z dostępnością surowców farmaceutycznych. Doświadczenia z lat ubiegłych – jak w przypadku wspomnianej już powyżej taksy laborum, która pozostawała bez zmian przez 19 lat – pokazują, że brak regularnych aktualizacji dokumentów tego typu prowadzi do systemowych dysfunkcji, ekonomiczną opłacalność a w konsekwencji ograniczających dostępność świadczeń zdrowotnych dla pacjenta.   Coroczna aktualizacja receptariusza pozwoli na utrzymanie jego spójności z praktyką kliniczną i farmaceutyczną oraz \\fzgodności z ewoluującymi standardami terapeutycznymi.\\t\\fUwaga niezasadna Proponowany zapis nakłada obowiązek corocznego aktualizowania wykazów, bez względu na istnienie rzeczywistej potrzeby dokonania takiej aktualizacji. Proces legislacyjny jest procesem czasochłonnym i angażującym znaczne zasoby osobowe, tym samym proponowany zapis stanowiłby zbytnie obciążenie w stosunku do celu jakiemu miałby służyć. Wykazy powinny być aktualizowane w przypadku stwierdzenia takiej potrzeby.  \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 6 ust. 2a ust. ref.\\tWERSJA A  2a.  Kwota odpłatności przez pacjenta, o której mowa w ust. 2, ulega obniżeniu o: 1) o 20% - w przypadku gdy lek jest sprowadzany na terytorium Rzeczypospolitej Polskiej jako produkt luzem, zaś na terytorium Rzeczpospolitej Polskiej odbywają się dalsze czynności jego wytwarzania,  2) 10 do niższej z wartości: o 70 % lub do poziomu odpłatności za leki o najniższej odpłatności w grupie limitowej w odpowiadającej dawce i wielkości opakowania - w przypadku gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej, z wyłączeniem leku, o którym mowa w pkt 1, albo gdy do jego wytworzenia wykorzystano substancję czynną wytwoarzoaną na terytorium Rzeczypospolitej Polskiej, 3) do niższej z wartości: o 80 % lub do poziomu odpłatności za leki o najniższej odpłatności w grupie limitowej w odpowiadającej dawce i wielkości opakowania - w przypadku gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej z wykorzystaniem substancji czynnej wytwarzanej na terytorium Unii Europejskiej,\\t 4) 15 do niższej z wartości: o 90% lub do poziomu odpłatności za leki o najniższej odpłatności w grupie limitowej w odpowiadającej dawce i wielkości opakowania - w przypadku gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej z \\fwykorzystaniem substancji czynnej wytwarzanej na terytorium Rzeczypospolitej Polskiej - przy czym koszt tej obniżki jest finansowany ze środków Funduszu.  WERSJA B   2a.  Kwota odpłatności przez pacjenta, o której mowa w ust. 2, ulega obniżeniu o: 1) 20% - w przypadku gdy lek jest sprowadzany na terytorium Rzeczypospolitej Polskiej jako produkt luzem, zaś na terytorium Rzeczpospolitej Polskiej odbywają się dalsze czynności jego wytwarzania,  2) 10 70% - w przypadku gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej, z wyłączeniem leku, o którym mowa w pkt 1, albo gdy do jego wytworzenia wykorzystano substancję czynną wytwoarzoaną na terytorium Rzeczypospolitej Polskiej, 3) 80% - w przypadku gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej z wykorzystaniem substancji czynnej wytwarzanej na terytorium Unii Europejskiej,\\t 4) 15 90% - w przypadku gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej z wykorzystaniem substancji czynnej wytwarzanej na terytorium Rzeczypospolitej Polskiej - przy czym koszt tej obniżki jest finansowany ze środków Funduszu.\\t\\fZgodnie z założeniami ustawodawcy przy nowelizacji z roku 2023 (Załącznik nr 1 do ówczesnego OSR) wartość dopłat do cen leków wytwarzanych w Polsce planowano na poziomie od ok. 100 mln zł (w wariancie wyliczeń A) do ok. 360 mln zł rocznie (w wariancie wyliczeń B). Tymczasem rzeczywista skala dopłat, jak wskazują analitycy PEX, wynosi ok. 25 mln zł rocznie (dane za rok 2024). Postulujemy zmianę poziomu dopłat tak, aby dostosować ich poziom do założeń oraz stworzyć rzeczywistą, a nie tylko symboliczną, zachętę do kupowania leków wytwarzanych w Polsce. Będzie to realny krok ku wzmocnieniu bezpieczeństwa lekowego, poprzez stworzenie dodatkowych zachęt do lokowania produkcji farmaceutyków w Polsce, zwłaszcza poprzez powiązanie kwoty odpłatności przez pacjenta z poziomem najniższej odpłatności leków w danej grupie limitowej. Proponujemy również zachętę dla pacjentów, choć na niższym poziomie, także do nabywania leków sprowadzanych do Polski jako produkty luzem – i takie bowiem działanie jest korzystniejsze dla bezpieczeństwa lekowego niż tylko sprowadzanie (lub nie) do Polski leków gotowych, w całości wytworzonych zagranicą.  W zakresie nowej kwoty obniżenia odpłatności dla pacjenta (80%) dla leków wytwarzanych na terytorium RP z wykorzystaniem substancji czynnej \\fwytwarzanej na terytorium EU – zob. uzasadnienie do zmiany art. 2 pkt 20c.   \\t\\fUwaga częściowo zasadna  W projekcie dokonano zmian w zakresie zwiększenia dopłat do leków, gdy lek jest lekiem wytwarzanym na terytorium Rzeczypospolitej Polskiej z wykorzystaniem substancji czynnej wytwarzanej na terytorium Rzeczypospolitej Polskiej. Po konsultacja publicznych zmieniono projekt przewidując podwyższenie dopłat ponoszonych przez płatnika do leków znajdujących się na wykazie G2 (Leki wytwarzane na terytorium Rzeczypospolitej Polskiej z wykorzystaniem substancji czynnej wytwarzanej na terytorium Rzeczypospolitej Polskiej, jako najbardziej pożądanej kategorii.  .\\n\\tPolski Związek Pracodawców \\fPrzemysłu Farmaceutycznego\\t\\fArt. 6 ust. 2c ust. ref.\\t2c. Minister właściwy do spraw zdrowia umieszcza lek, o którym mowa w ust. 2a, w obwieszczeniu, o którym mowa w art. 37 \\fust. 2a, z urzędu na podstawie oświadczenia wnioskodawcy złożonego pod rygorem odpowiedzialności za składanie fałszywych oświadczeń. \\t\\fProponowany przepis zmierza do odbiurokratyzowania procesu tworzenia wykazu polskich leków.  \\fZe względu na brak odpowiednich przepisów przejściowych w nowelizacji z dnia 17 sierpnia 2023 r., stworzenie pierwszego wykazu polskich leków wymagało według ówczesnej interpretacji Departamentu Polityki Lekowej i Farmacji MZ pełnego przeprocedowania nowych wniosków refundacyjnych, połączonego ze skróceniem dotychczasowych decyzji. Proces ten był czasochłonny, niepotrzebny i doprowadził do pominięcia w pierwszym wykazie niektórych leków wytwarzanych w Polsce z powodu opóźnień proceduralnych. Proponowane rozwiązanie eliminuje ten problem, a przy tym w sposób prawidłowy rozdziela kwestie preferencji dla wnioskodawców (udzielanych w postępowaniu zainicjowanym wnioskiem refundacyjnym) od kwestii obniżki odpłatności dla pacjentów (należnej zgodnie z treścią ustawy w przypadku wszystkich leków wytwarzanych w Polsce lub z polskiego API). \\t\\fUwaga niezasadna Uwaga wykracza poza zakres nowelizacji. \\fW opinii Organu propozycja umieszczania na wykazie, o którym mowa w art. 37 ust. 2a ustawy o refundacji, w oparciu o oświadczenie wnioskodawcy jest bezpodstawna i niezasadne, wydatkowanie publicznych pieniędzy nie może odbywać się bez przeprowadzenia postępowania administracyjnego.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 6 ust. 8 ust. ref.\\t8. Lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny, dla którego wydana została decyzja administracyjna o objęciu refundacją w zakresie nadanej kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 2, 2a i 3, jest wydawany świadczeniobiorcy bezpłatnie.\\tW obecnym brzmieniu  Projektu nie określono poziomu odpłatności dla leków z nowej kategorii dostępności. Mając na uwadze konstrukcję prawną nawiązującą do kategorii dostępności chemioterapii, jak również traktowanie w pozostałej części Projektu nowej kategorii dostępności z art. 6 ust. 1 pkt 2a na równi z kategoriami określonymi w art. 6 ust. 1 pkt 2 i 3, należy ujednolicić poziom odpłatności za leki z tej kategorii \\fz sytuacją leków podawanych w chemioterapii i programach lekowych. \\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 11 ust. 2 ustawy refundacyjnej\\t10) zakres ograniczeń w zakresie preskrypcji, o których mowa w art. 6 ust. 2b, jeżeli został ustalony.\\tZobacz uzasadnienie do artykułu art. 1 pkt 2 lit b projektu odnoszące się do art. 6 ust. 2b ustawy refundacyjnej\\tUwaga niezasadna W zakresie programu lekowym takie ograniczenia już są w treści programu lekowego.\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\tart. 11 dodanie ust. 3 pkt 4\\t3. Decyzję administracyjną o objęciu refundacją, o której mowa w ust. 1, wydaje się na okres: 4) do 3 lat – dla produktów leczniczych z importu równoległego\\tZapis dodany w celu uniknięcia wątpliwości co do okresu, na który wydawane są decyzje dla tej grupy produktów.\\tUwaga niezasadna Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji.   Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu. \\n\\tZwiązek Pracodawców  \\fInnowacyjnych Firm Farmaceutycznych INFARMA\\t\\fArt. 11 ust. 5b ustawy refundacyjnej\\t5b. W przypadku gdy decyzja administracyjna o objęciu refundacją, o której mowa w ust. 1, zawiera instrument dzielenia ryzyka, o którym mowa w ust. 2 \\fpkt 7, na wniosek wnioskodawcy uwzględnia się w nim określenie populacji lub grupy limitowej, której dotyczy zobowiązanie wnioskodawcy określone w instrumencie dzielenia ryzyka.\\t\\fNowelizacją ustawy refundacyjnej z 2023 r. zmieniono istotnie zasady ustalania jednych z istotnych czynników \\fbranych pod uwagę przy ustalaniu warunków refundacji. Po pierwsze, z decyzji, które są wydawane od 1 listopada 2023 r. wyłączono informację o grupie limitowej oraz opis programu lekowego (który był dotychczas załącznikiem do decyzji refundacyjnych). W stosunku do decyzji sprzed 1 listopada 2023 r. wprowadzono bardzo „elastyczny” mechanizm zmian grup limitowych z urzędu przez Ministra Zdrowia(Zob. obecnie obowiązujący art. 15 ust. 3 – 3b u.r.) oraz możliwość zmiany opisów programów lekowych bez żadnych przesłanek i praktycznie w jakimkolwiek czasie(Zob. obecnie obowiązujący art. 16a ust. 4 i 5 u.r.). Dodatkowo komunikatem(https://www.gov.pl/web/zdrowie/komunikat-ministra-zdrowia-w-sprawie-dotychczas-wydanych-decyzji-o-objeciu-refundacja-zawierajacych-zalacznik-w-postaci-opisu-programu-lekowego-w-zwiazku-ze-zmianami-prawa-jakie-zajda-z-dniem-1-listopada-2023-r) (!) usunięto z wydanych już decyzji (co stanowi istotne naruszenie od zasady trwałości decyzji administracyjnej) załączniki w postaci opisów programów lekowych – co teraz jest legalizowane w ramach nowelizacji. Te zmiany (które należy ocenić negatywnie) powodują, że wnioskodawcy tracą pewność co do założeń jakie poczynili w przeszłości, lub jakie mają poczynić w świetle trwających i przyszłych postępowań refundacyjnych. Warto podkreślić, że zarówno opis populacji dla danego programu lekowego \\f(np. kryteria włączenia i wyłączenia pacjenta z uczestnictwie w programie) czy grupa limitowa są niezwykle ważne dla ustalania obowiązków refundacyjnych wnioskodawców, w szczególności wynikających z instrumentów dzielenia ryzyka (stanowiących element decyzji refundacyjnej). Tymczasem instrument dzielenia ryzyka to de facto umowa administracyjna zawierana pomiędzy dwoma stronami (MZ oraz adresatem decyzji refundacyjnej). Nie może więc być tak, że jedna ze stron takiej umowy (w tym wypadku MZ) ma arbitralną możliwość całkowitej zmiany warunków w takcie trwania umowy, zaś druga strona nie ma na to żadnego wpływu, przy czym równocześnie odpowiada za zobowiązania wynikające z tejże umowy (adresat decyzji). Dla adresatów decyzji refundacyjnych wydanych przed 1 listopada 2023 r. wskazane zmiany oznaczają „zmianę reguł gry w jej trakcie”. Ustalali oni z Ministrem Zdrowia konkretne instrumenty dzielenia ryzyka dostosowane do konkretnej populacji (która była „ugruntowana” w ich decyzji refundacyjnej) czy grupy limitowej.  W tej sytuacji zmiana populacji poprzez jej rozszerzenie np. w przypadku instrumentu dzielenia ryzyka polegającego na określeniu pewnego „CAP-u” (limitu), po przekroczeniu którego „aktywują się” obowiązki wnioskodawcy, może oznaczać zwiększenie obciążeń wnioskodawców, których nie mogli przewidzieć. \\fTaka nieprzewidywalność jest wprost sprzeczna z zasadami wynikającymi z Dyrektywy Przejrzystości(Dyrektywa Rady z dnia 21 grudnia 1988 r. dotycząca przejrzystości środków regulujących ustalanie cen na produkty lecznicze przeznaczone do użytku przez człowieka oraz włączenia ich w zakres krajowego systemu ubezpieczeń zdrowotnych.). Było to zresztą przedmiotem skargi INFARMA do Komisji Europejskiej. Wobec powyższego, postulujemy wycofanie się ze zmian wprowadzonych nowelizacją z 2023 r. oraz zmian proponowanych w tej nowelizacji, które dotyczą zmian grup limitowych, a także „wyjęcia” z decyzji refundacyjnych opisów wskazań w przypadku chemioterapii oraz czwartej kategorii dostępności.  Alternatywnie proponujemy pozostawienie tych rozwiązań, jednak pod warunkiem wprowadzenia zaproponowanego rozwiązania i dodania art. 11 ust. 5b. Takie rozwiązanie pozwoli Ministerstwu Zdrowia na kształtowanie populacji i wskazań, jednocześnie dając pewność i stabilność dla wnioskodawców, co będzie – wraz z uwzględnieniem zaproponowanych zmian do art. 16a –  prowadziło do zgodności ustawy refundacyjnej w tym zakresie z Dyrektywą Przejrzystości oraz będzie odpowiadać charakterowi RSS. W przypadku takiego rozwiązania strony RSS (MZ i wnioskodawca) będą mogły dokonać stosownych zmian w treści tego instrumentu na wniosek, w trybie art. 155 KPA.  \\t\\fUwaga niezasadna Organ nie widzi możliwości wprowadzenia zaproponowanego przepisu, ponieważ zarówno program, jak \\fi grupa limitowa nie są elementem decyzji administracyjnej, więc nie mogą być objęte porozumieniem RSS- instrumentem dzielenia ryzyka, ponieważ mogą ulec zmianie w trakcie obowiązywania decyzji refundacyjnej. Zaproponowany mechanizm każdorazowo ponownie wymagałby zmiany załącznika w postaci RSS w trybie art. 155 ustawy z dnia 14 czerwca 1960 r. Kodeks postępowania administracyjnego (Dz. U. z 2025 r. poz. 1691\\n«numer_dziennika_ustawy_kpa»), dalej ,,kpa”, co byłoby sprzeczne z założeniami dokonanych zmian w nowelizacji z 1 listopada 2023 r.\\n\\tKonfederacja Lewiatan / Polski Związek Pracodawców Przemysłu Farmaceutycznego\\t art. 11 ust. 4 i art. 11 a - propozycja nowego przepisu \\tArt. 11  4. Podwyższenie albo obniżenie urzędowej ceny zbytu następuje w drodze zmiany decyzji administracyjnej o objęciu refundacją, o której mowa w ust. 1, a w przypadku, o którym mowa w art. 11a, w drodze obwieszczenia, o którym mowa w art. 37 ust. 1.  Art. 11a  1. Jeżeli średnioroczny wskaźnik cen towarów i usług konsumpcyjnych ogółem w poprzednim roku, ogłaszany przez Prezesa Głównego Urzędu Statystycznego, przekracza wartość 105, minister właściwy do spraw zdrowia podwyższa urzędowe ceny zbytu leków, których urzędowa cena zbytu w dniu 1 stycznia roku bieżącego nie przekracza 75 zł, w najbliższym obwieszczeniu, o którym mowa w art. 37 ust. 1, o wartość wskazaną w ust. 2 i 3 poniżej, oraz podwyższa ceny detaliczne odpowiednio, zaokrąglając je w górę do pełnych groszy.  2. Urzędową cenę zbytu nieprzekraczającą 50 zł podwyższa się o wartość średniorocznego wskaźnika cen towarów i usług konsumpcyjnych ogółem w poprzednim roku, ogłaszanego przez Prezesa Głównego Urzędu Statystycznego, pomniejszoną o 3 punkty procentowe.  3. Urzędową cenę zbytu przekraczającą 50 zł, a nieprzekraczającą 75 zł, podwyższa się o wartość średniorocznego wskaźnika cen towarów i usług konsumpcyjnych ogółem w poprzednim roku, ogłaszanego przez Prezesa Głównego Urzędu Statystycznego, pomniejszoną o 5 punktów procentowych.  \\f4. Przepisów ust. 1-3 nie stosuje się do leków, środków spożywczych specjalnego przeznaczenia żywieniowego, wyrobów medycznych, które są jedynymi produktami refundowanymi w danym wskazaniu lub które są zawarte w wykazie, o którym mowa w art. 37 ust. 1, nieprzerwanie krócej niż 6 miesięcy.\\t\\fProponuje się wprowadzenie mechanizmu automatycznej indeksacji cen produktów refundowanych. Od 2012 roku ustalone przez Ministra Zdrowia ceny leków refundowanych mają charakter sztywny (apteka) lub maksymalny (lecznictwo szpitalne) i obowiązują przez cały okres ważności decyzji refundacyjnych. Regulacje prawne nie przewidują mechanizmu waloryzacji cen produktów refundowanych, co nie pozwala chronić wnioskodawców przed nieuzasadnioną i nieprzewidywalną erozją cenową (na przykładzie: inflacja konsumencka w Polsce w 2022 roku wyniosła 14,4 % w ujęciu rocznym, w roku 2023 wyniosła 11,4% - deprecjacja pieniądza nie znalazła odbicia w cenach leków refundowanych). Automatyczna indeksacja cen została zaproponowana w dodanym art. 11a. Wprowadzany przepis przewiduje, że jeżeli średnioroczny wskaźnik cen towarów i usług konsumpcyjnych ogółem w poprzednim roku, ogłaszany przez Prezesa Głównego Urzędu Statystycznego, przekracza 105 %, minister właściwy do spraw zdrowia podwyższa urzędowe ceny zbytu leków, w najbliższym obwieszczeniu o wartość tego wskaźnika, pomniejszoną w przypadku leków, których urzędowa cena zbytu nie przekracza 50 zł, o 3 \\fpunkty procentowe, a w przypadku ceny nieprzekraczającej 75 zł o 5 punktów procentowych. Automatyczna indeksacja cen następuje na podstawie obwieszczenia ministra właściwego do spraw zdrowia. Podobne rozwiązania znaleźć można w innych aktach rangi ustawowej. Przykładowo, art. 40 ust. 8 ustawy z dnia 29 grudnia 1992 r. o radiofonii i telewizji przewiduje możliwość waloryzacji opłat za udzielenie koncesji w każdym roku o średnioroczny wskaźnik cen towarów i usług konsumpcyjnych ogółem w poprzednim roku kalendarzowym, ogłaszany przez Prezesa Głównego Urzędu Statystycznego. Projektowany mechanizm nie będzie dotyczył leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, które objęte są ochroną patentową (w tym dodatkowym świadectwem ochronnym), wyłącznością danych lub wyłącznością rynkową bądź dla których decyzja administracyjna o objęciu refundacją obowiązuje nieprzerwanie krócej niż 6 miesięcy.\\t\\fUwaga niezasadna Zaproponowany przepis spowodowałby, iż ceny leków kształtowałyby się poza kontrolą Ministra Zdrowia. Przykładowo zgodnie z obwieszczeniem Ministra Zdrowia z dnia 17 czerwca 2025 r. w sprawie wykazu refundowanych leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych na 1 lipca 2025 r. do urzędowej ceny zbytu netto w wysokości 75 zł refundowanych jest 3851 produktów. Wg dostępnych danych za grudzień 2024 r. łącznie w miesiącu sprzedało się 36 500 368,87 opak. tych produktów. Wobec powyższego należy podkreślić, iż produkty o niskiej wartości nominalnej są refundowane w dużych ilościach. Automatyczny wzrost cen powodowałby znaczący wzrost wydatków płatnika publicznego. Należy podkreślić, iż nie każdy Wnioskodawcy przy wzroście inflacji konsumenckiej boryka się z problemami finansowanymi w przedsiębiorstwie. Powyższe zależy od wielu czynników m.in faktycznym wzrostem poszczególnych kosztów i rodzajem oraz długością zawartych umów. W przypadku braku rentowności produktu i braku możliwości utrzymywania go na liście leków refundowanych, Wnioskodawca ma możliwość renegocjacji ceny poprzez złożenie wniosku o podwyższenie ceny zbytu netto leku z art. 24 ust. 1 pkt 2 ustawy o refundacji w trakcie obowiązywania aktualnej decyzji refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego/  Zakłady Farmaceutyczne POLPHARMA S.A.\\tDodaje się art. 12a i 12b w ust. ref.\\tArt. 12a.  1. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego leku, który stanowi pierwszy lub kolejny odpowiednik leku refundowanego w danym wskazaniu lub znajdującego się na wykazie, o którym mowa w art. 37 ust. 1, oraz do wniosku, o którym mowa w art. 24 ust. 1 pkt 3, złożonego przez Partnera Bezpieczeństwa \\fLekowego nie stosuje się przepisów art. 12, art. 19 oraz art. 36.  2. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego leku, który nie posiada zarejestrowanego odpowiednika nie stosuje się ust. 1.  3. Za Partnera Bezpieczeństwa Lekowego uznaje się wnioskodawcę, będącego osobą prawną i jej podmioty powiązane zgodnie z definicją zawartą w ustawie o rachunkowości z dnia 29 września 1994 r., który spełnia przynajmniej jeden z następujących warunków:  a) co najmniej 25% wolumenu, wyrażonego w dobowej dawce leku ustalonej przez Światową Organizację Zdrowia (DDD) lub w innej jednostce stosowanej przez Ministra Zdrowia przy projektowaniu list refundacyjnych i limitów, jego leków objętych refundacją w roku poprzedzającym złożenie wniosku, o którym mowa w ust. 1, w kategorii dostępności, o której mowa w art. 6 ust. 1 pkt 1-3, jest wytwarzanych na terytorium Rzeczypospolitej Polskiej,   b) co najmniej 100 mln wolumenu wyrażonego w standardowej jednostce, uspójnionej dla różnych form jego leków jest wytwarzanych na terytorium Rzeczypospolitej Polskiej,  - w roku poprzedzającym złożenie wniosku, o którym mowa w ust. 1.  4. W celu wykazania przesłanek, o których mowa w ust. 3 powyżej, wnioskodawca składa informację na piśmie o działalności inwestycyjnej w zakresie związanym z ochroną zdrowia, w obszarze produkcji leków, stanowiącą wzmacnianie bezpieczeństwa lekowego Polski. Wzór \\finformacji zostanie określony w rozporządzeniu, o który mowa w ust. 7.   5. Przepis ust. 3 nie dotyczy wnioskodawcy, który jest wyłącznie importerem równoległym w rozumieniu ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne bądź którego zakres wytwarzania obejmuje wyłącznie czynności pakowania lub przepakowywania.  6. Pod pojęciem wytwarzania leku na terytorium Rzeczypospolitej Polskiej, o którym mowa w ust. 3, rozumie się wytwarzanie, o którym mowa w ustawie z dnia 6 września 2001 r. - Prawo farmaceutyczne.  7. Minister właściwy do spraw gospodarki w porozumieniu z ministrem właściwym do spraw zdrowia określi w drodze rozporządzenia wzór informacji o działalności inwestycyjnej w zakresie związanym z ochroną zdrowia, w obszarze produkcji leków, stanowiącą wzmacnianie bezpieczeństwa lekowego Polski.  8. Partner Bezpieczeństwa Lekowego nie podlega rozszerzonej odpowiedzialności producenta, o której mowa w art. 9 ust. 1 Dyrektywy Parlamentu Europejskiego i Rady (UE) 2024/3019 z dnia 27 listopada 2024 r. dotycząca ścieków komunalnych (wersja przekształcona) oraz w ustawie wykonującej tę dyrektywę.  Art. 12b. 1. W przypadku rozpoznania wniosków, o których mowa w art. 24 ust. 1 pkt 1 złożonych przez Partnera Bezpieczeństwa Lekowego dla leku, który stanowi pierwszy lub kolejny odpowiednik leku refundowanego w danym wskazaniu, urzędowa cena zbytu ustalona w decyzji, o której mowa w art. 11 ust. 1, odpowiada \\furzędowej cenie zbytu, o której mowa w art. 13 ust. 6, chyba, że Wnioskodawca zaproponował we wniosku cenę zbytu netto pozwalającą na ustalenie urzędowej ceny zbytu na niższym poziomie.   2. Urzędowa cena zbytu leku, który w dniu złożenia wniosku o którym mowa w art. 24 ust. 1 pkt 1, był zawarty w wykazie, o którym mowa w art. 37 ust. 1, w danym wskazaniu, dla którego wnioskodawcą jest Partner Bezpieczeństwa Lekowego, ustalona w decyzji, o której mowa w art. 11 ust. 1, odpowiada urzędowej cenie zbytu leku obowiązującej w dniu złożenia tego wniosku, chyba, że Wnioskodawca zaproponował we wniosku cenę zbytu netto pozwalającą na ustalenie urzędowej ceny zbytu na niższym poziomie.     3. Decyzja, o której mowa w ust. 1 i 2 wydawana jest na okres 5 lat.  4. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dotyczący leku dla którego dotychczas nie obowiązywała decyzja administracyjna o objęciu refundacją, złożony przez Partnera Bezpieczeństwa Lekowego, rozpatrywany jest w pierwszej kolejności. Wobec takiego wniosku nie ma zastosowania art. 31 ust. 1.  5. Produkt leczniczy Wnioskodawcy uznanego za Partnera Bezpieczeństwa Lekowego, dla którego żaden odpowiednik nie jest refundowany w danym wskazaniu, ma pierwszeństwo w obejmowaniu refundacją w danym wskazaniu.  6. Rozpatrując wniosek, o którym mowa w art. 24 ust. 1 pkt 1, złożony przez Partnera Bezpieczeństwa Lekowego dla leku, dla którego żaden odpowiednik nie jest refundowany w danym wskazaniu, minister właściwy do spraw zdrowia, Prezes Agencji \\foraz Komisja Ekonomiczna uwzględniają wysokość progu kosztu uzyskania dodatkowego roku życia skorygowanego o jakość, o którym mowa w art. 12 pkt 13, art. 19 ust. 2 pkt 7, art. 35 ust. 5 pkt 4, art. 35 ust. 6 pkt 3 lit. e., podwyższoną o 50 % w porównaniu do wartości określonej w art. 12 pkt 13.\\t\\fZob. uzasadnienie do postulatu zmiany art. 4a  Dodanie art. 12a i 12b stanowi jeden z elementów proponowanego mechanizmu Partnera Bezpieczeństwa Lekowego. Mechanizm wspierania produkcji w Polsce za pomocą instrumentów prawa refundacyjnego powinien odnosić się do wnioskodawcy, a \\fnie tylko jego poszczególnych produktów, jak ma to miejsce w obecnym porządku prawnym.                                                 W zakresie ust. 8 – projekt rozporządzenia unijnego Critical Medicines Act uzasadnia zwolnienie z obowiązków wynikających z dyrektywy UWWTD, mając na uwadze, że nakładane przez nią wymagania stanowią istotne obciążenie administracyjne i operacyjne, mogące negatywnie wpływać na potencjał produkcyjny w zakresie wytwarzania leków o kluczowym znaczeniu dla zdrowia publicznego.                                               Od Pol W związku z dużym zaangażowaniem Pana Ministra w kwestie zwiększenia produkcji leków w Polsce, pragniemy złożyć uzasadnienie do propozycji dodania art. 12a i 12b, zawartej w stanowisku PZPPF w konsultacjach publicznych dot. projektu ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (strona 13 załączonego stanowiska) , które w naszej opinii będą silną zachętą do produkcji leków w Polsce. 1. Proponujemy oznaczanie producentów-wnioskodawców według dwóch kategorii: • Wnioskodawca produkujący leki w Polsce -nazwany przez nas roboczo Partnerem Bezpieczeństwa Lekowego • Wnioskodawca -importer Partner Bezpieczeństwa Lekowego to firma, która: • produkuje w Polsce co najmniej 25% liczby leków podlegającej refundacji lub \\f• 100 mln opakowań produktów leczniczych. 2. Proponujemy aby ceny leków refundowanych Partnerów Bezpieczeństwa Lekowego były traktowane w procesie refundacyjnym podobnie jak leki produkowane w Polsce, a nie traktowane na równi z lekami importerów. Oznacza to, że ceny wszystkich leków refundowanych Partnerów Bezpieczeństwa lekowego będą mogły być ustalone na poziomie maksymalnych cen ustawowych.  Uzasadnienie na przykładzie Polpharmy:  Zwiększanie produkcji w Polsce - zyski ze sprzedaży wszystkich leków Polpharmy (produkowanych w Polsce, kupowanych w ramach licencji, a nawet importowanych) są przeznaczone na inwestycje w opracowanie nowych leków, niezbędną infrastrukturę do ich produkcji, ale także na rozwój nowych klas leków, np. leków biologicznych, biologicznych oryginalnych oraz leków RNA. Nakłady inwestycyjne Grupy Kapitałowej Polpharma w Polsce na badania i rozwój produktów leczniczych w latach 2021-2024 wyniosły 917 mln zł.  Zwiększanie dochodów podatkowych Polski w tym składek zdrowotnych - dzięki działalności Polpharmy w 2024 r. do budżetu państwa trafiło około 1,3 mld zł, tymczasem \\frefundacja za nasze leki w tym okresie wyniosła ok. 890 mln zł .  Leki sprowadzane w ramach licencji docelowo będą produkowane w Polsce. Większość umów licencyjnych zawiera możliwość kupowania od licencjodawcy gotowych leków, a po określonym czasie transferu technologii i produkcji w naszych zakładach.  Transparentność i przewidywalność ustalania cen może być też zachętą dla zagranicznych firm, które przeniosą część swojej produkcji do Polski. W tej chwili nie widzą żadnych zachęt. Stabilność i przewidywalność cen sprzyjają inwestycjom, podczas gdy ich nieprzewidywalność i niestabilność ogranicza chęć podejmowania działań inwestycyjnych.  Nawet w przypadku, zaniżonej oferty cenowej Ministra Zdrowia, w porównaniu do ustawowej, firma woli przyjąć taką propozycję ze względu na zwolnione do obrotu leki w magazynach, niż stracić możliwość ich sprzedaży. W takim przypadku poszukuje się tańszego dostawcy lub skraca decyzję refundacyjną.   Podsumowanie:  Ustalanie cen dla wybranych producentów na maksymalnym poziomie ustawowym zachęci do produkowania leków w Polsce,  \\fZyski ze sprzedaży leków produkowanych w Polsce lub polskich producentów zasilają budżet państwa w tym składki zdrowotnej,  Polityka cenowa Ministerstwa Zdrowia prowadzona z uwzględnieniem zwiększania produkcji leków w Polsce zwiększy bezpieczeństwo lekowe Polaków, brak takiej perspektywy, obniży w krótkiej perspektywie wydatki NFZ na refundację leków ale w odległej, zmniejszy produkcję w Polsce i uzależnienie od importu leków. \\t\\fUwaga niezasadna Uwaga poza zakresem nowelizacji Niezasadne jest uznawanie produkcji leków czy substancji czynnych które są produkowane poza granicami Polski, jako aspektu poprawiającego bezpieczeństwo lekowe Polski.  Zachęty przewidziane w ustawie refundacyjnej obejmują podmioty \\fwytwarzające lek na terytorium Rzeczypospolitej Polskiej albo wytwarzające lek z wykorzystaniem substancji czynnej wytworzonej na terytorium Rzeczypospolitej Polskiej w Polsce.\\n\\tPracodawcy RP\\tArt. 12 pkt 15 ustawy refundacyjnej\\tW art. 12 proponujemy dodanie pkt 15 w brzmieniu: „15) opinię lub stanowisko organizacji pacjentów, o której mowa w art. 55a ust. 1 ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2024 r. poz. 581), jeżeli zostało przedstawione”  W konsekwencji powyższej zmiany proponujemy rezygnację z wprowadzania przepisu art. 19 ust. 1d. \\tZe względu na liczne wątpliwości odnośnie udziału przedstawiciela organizacji pacjentów w negocjacjach proponujemy wprowadzenie opinii lub stanowiska takiej organizacji do katalogu elementów branych pod uwagę przez MZ na etapie wydawania decyzji.\\tUwaga niezasadna Ministerstwo Zdrowia nie podziela prezentowanego stanowiska. Rekomendacja Prezesa Agencji, o której mowa w art. 35 ust.6 ustawy o refundacji wydawana na podstawie analizy weryfikacyjnej przygotowanej przez AOTMiT stanowi kryterium decyzji o objęciu refundacją. AOTMiT ocenia analizy HTA dotyczące objęcia refundacją danego leku, w tym analizę kliniczną przedstawiającą efekty kliniczne wynikające ze stosowania danego leku, zasięgając przy tym opinii konsultantów medycznych i ekspertów klinicznych. Minister Zdrowia otrzymując sygnały od pacjentów czy organizacji społecznych, bierze je pod uwagę w toku podejmowanych działań. Natomiast pacjent nie finansuje bezpośrednio terapii ani nie może ocenić merytorycznie efektów klinicznych terapii.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13 ust. 1 ust. ref\\t1. Minister właściwy do spraw zdrowia ustala cenę zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, dla którego żaden odpowiednik nie jest refundowany w danym wskazaniu, przy uwzględnieniu następujących kryteriów: 1)\\t stanowiska Komisji Ekonomicznej, o której mowa w art. 17, 2)\\t rekomendacji Prezesa Agencji, o której mowa w art. 35 ust. 6, w szczególności wyników analizy stosunku kosztów do uzyskanych efektów zdrowotnych, 3)\\t konkurencyjności cenowej - biorąc pod uwagę równoważenie interesów świadczeniobiorców i przedsiębiorców zajmujących się wytwarzaniem lub obrotem lekami, środkami spożywczymi specjalnego przeznaczenia żywieniowego, wyrobami medycznymi, możliwości płatnicze podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, objęcie leku w ramach Krajowej Listy Leków Krytycznych lub w unijnym wykazie produktów leczniczych o krytycznym znaczeniu oraz działalność naukowo-badawczą i inwestycyjną wnioskodawcy w zakresie związanym z ochroną zdrowia na terytorium Rzeczypospolitej Polskiej oraz w innych państwach członkowskich Unii Europejskiej lub państwach członkowskich Europejskiego Porozumienia o Wolnym Handlu (EFTA). \\tWprowadzenie przesłanki objęcia leku unijną listą leków krytycznych (Union List of Critical Medicines), publikowaną przez Europejską Agencję Leków (EMA) lub Krajową Listą Leków Krytycznych, ma na celu wzmocnienie bezpieczeństwa zdrowotnego Rzeczypospolitej Polskiej oraz zapewnienie ciągłości dostaw produktów leczniczych o strategicznym znaczeniu. Listy te identyfikują substancje czynne, których dostępność jest kluczowa z punktu widzenia ochrony zdrowia publicznego w Polsce i Unii Europejskiej. Uwzględnienie tego kryterium w procesie ustalania cen leków ma umożliwić elastyczniejsze podejście do warunków refundacyjnych dla produktów, których niedobory mogłyby prowadzić do istotnych zagrożeń terapeutycznych. Rozwiązanie to jest spójne z celem Unii Europejskiej, wyrażonym m.in. w projekcie rozporządzenia Critical Medicines Act, zmierzającym do zwiększenia odporności łańcucha dostaw produktów leczniczych, a także wspiera rozwój lokalnej produkcji oraz inwestycji w badania i rozwój w obszarach kluczowych dla bezpieczeństwa zdrowotnego.             \\t\\fPoza zakresem nowelizacji \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13 ust. 5 ust. ref.\\t5. Minister właściwy do spraw zdrowia ustala cenę zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, dla którego co najmniej jeden odpowiednik jest refundowany w danym wskazaniu, przy uwzględnieniu kryteriów, o których mowa w ust. 1, biorąc pod uwagę równoważenie interesów świadczeniobiorców i przedsiębiorców zajmujących się wytwarzaniem lub obrotem lekami, środkami spożywczymi specjalnego przeznaczenia żywieniowego oraz wyrobami medycznymi, możliwości płatnicze podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych objęcie leku w ramach Krajowej Listy Leków Krytycznych lub w unijnym wykazie produktów leczniczych o krytycznym znaczeniu oraz działalność naukowo-badawczą i inwestycyjną wnioskodawcy w zakresie związanym z ochroną zdrowia na terytorium Rzeczypospolitej Polskiej oraz w innych państwach członkowskich Unii Europejskiej lub państwach członkowskich Europejskiego Porozumienia o Wolnym Handlu (EFTA). \\tObniżka ceny dotychczasowego monopolisty jest rozwiązaniem zasadnym i zgodnym z interesem pacjentów. Powinna jednak następować równolegle z objęciem refundacją pierwszego odpowiednika, a zatem wtedy kiedy pojawia się realna konkurencja rynkowa. W przeciwnym wypadku zamiast rozszerzenia dostępu pacjentów do leku (poprzez równoległe udostępnienie leku objętego dotąd wyłącznością oraz jego odpowiednika), może dojść do całkowitego pozbawienia pacjentów takiego dostępu. Wymuszenie obniżki ceny urzędowej przed faktycznym pojawieniem się konkurencyjnego leku może bowiem spowodować co najmniej przejściowe wycofanie się producenta jedynego leku refundowanego z refundacji. Postulowane rozwiązanie zapewnia większą przewidywalność dla wszystkich uczestników rynku oraz brak nieuzasadnionych merytorycznie obniżek cen leków referencyjnych w przypadku gdy na rynek faktycznie nie wchodzi konkurencja. Eliminuje także zagrożenie przerwania ciągłości dostępu do leków refundowanych dla pacjentów – w przeszłości było wiele przykładów, gdy mechanizm stosowania tego przepisu prowadził do wycofania na kilka miesięcy produktów bez odpowiedników z refundacji. W razie uwzględnienia propozycji zmiany do art. 13 ust. 2, należy dostosować brzmienie art. 11 ust. 3a w taki sposób, by \\fobniżka cenowa dotychczasowego monopolisty i pierwszego odpowiednika następowała równocześnie. \\t\\f Poza zakresem nowelizacji\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tart. 15 ust. ref. dodanie ust. 4b\\t4b. Przy ustalaniu podstawy limitu w danej grupie limitowej nie uwzględnia się leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych dopuszczonych do obrotu na podstawie Art. 4a ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. \\tWprowadzenie przesłanki objęcia leku na unijnym wykazie produktów leczniczych o krytycznym znaczeniu (Union List of Critical Medicines), publikowaną przez Europejską Agencję Leków (EMA) lub Krajową Listą Leków Krytycznych, ma na celu wzmocnienie bezpieczeństwa zdrowotnego Rzeczypospolitej Polskiej oraz zapewnienie ciągłości dostaw produktów leczniczych o strategicznym znaczeniu. Listy te identyfikują substancje czynne, których dostępność jest kluczowa z punktu widzenia ochrony zdrowia publicznego w Polsce i Unii Europejskiej. Uwzględnienie tego kryterium w procesie ustalania cen leków ma umożliwić elastyczniejsze podejście do warunków refundacyjnych dla produktów, których niedobory mogłyby prowadzić do istotnych zagrożeń terapeutycznych. Rozwiązanie to jest spójne z celem Unii Europejskiej, wyrażonym m.in. w projekcie rozporządzenia Critical Medicines Act, zmierzającym do zwiększenia odporności łańcucha dostaw produktów leczniczych, a także wspiera rozwój lokalnej produkcji oraz inwestycji w badania i rozwój w obszarach kluczowych dla bezpieczeństwa zdrowotnego.  OD Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman:  \\fWyłączenie produktów leczniczych pochodzących z importu równoległego z grup limitowych jest niezbędne, żeby nie miały one wpływu na poziom refundacji pozostałych produktów leczniczych. Równocześnie to wyłączenie będzie gwarantowało, że różnica w cenie leku z importu równoległego będzie dawała każdorazowo oszczędności zarówno po stronie pacjenta, jak i NFZu. W nowelizacji jest procedowany już nowy ust. 4a. Dla uniknięcia konfuzji, proponujemy umieszczenie naszej propozycji jako ust. 4b.\\t\\fUwaga niezasadna Projektowana zmiana art. 15 ust. 7 ustawy o refundacji, polegająca na wyłączeniu stosowania zasady ustalania podstawy limitu według DDD pierwszego odpowiednika w przypadku produktów leczniczych wprowadzanych do obrotu w ramach importu równoległego na podstawie art. 4a ustawy – Prawo farmaceutyczne prowadziłaby do stworzenia odrębnego, korzystniejszego trybu ustalania podstawy limitu wyłącznie dla tej kategorii produktów. Proponowane wyłączenie mogłoby prowadzić do luki prawnej w procedurze refundacyjnej poprzez zgłaszanie produktów w imporcie równoległym jedynie w celu uniknięcia zastosowania przepisu art. 15 ust. 7 ustawy o refundacji.  Ponadto nieuprawnione jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia \\fpełnego katalogu wymogów ustawowych przewidzianych dla refundacji.  Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu. \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tart. 15 zmiana ust. 7\\t7. W przypadku wydania decyzji o objęciu refundacją pierwszego odpowiednika refundowanego w danym wskazaniu podstawą limitu w grupie limitowej jest cena hurtowa za DDD tego odpowiednika. Przepisu zdania pierwszego nie stosuje się, jeżeli pierwszym odpowiednikiem jest produkt leczniczy dopuszczony do obrotu na podstawie Art. 4a ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. W przypadku objęcia refundacją kolejnych odpowiedników podstawa limitu nie może być wyższa niż cena hurtowa za DDD pierwszego odpowiednika. \\tZmiana ustępu 7 polega na uproszczeniu procedury refundacyjnej. W przypadku importu równoległego bowiem refundacja odpowiednika nie ma znaczenia, bo leki z importu nie stanowią kolejnego odpowiednika leku, ale ten sam produkt leczniczy pod inną rejestracją.  OD Kancelaria Radcy Prawnego Tomasz Dauerman: Zmiana ustępu 7 polega na uproszczeniu procedury refundacyjnej. W przypadku importu równoległego refundacja odpowiednika nie ma bowiem znaczenia, gdyż leki z importu nie stanowią kolejnego odpowiednika leku, ale ten sam produkt leczniczy pod inną rejestracją. \\tUwaga niezasadna Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji.   Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, \\fformy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 13 ust. 2e ustawy refundacyjnej\\t2e. W przypadku zastosowania mechanizmów, o których mowa w ust. 2 – 2b, wyliczenia cen dla leku dokonuje się proporcjonalnie do prezentacji leku, dla której została wydana pierwsza decyzja administracyjna o objęciu refundacją, przy uwzględnieniu jednostki miary substancji czynnej lub DDD lub PDD.\\tCelem zapewnienia odpowiednich przeliczeń koniecznym jest wskazanie w ustawie punktu odniesienia. Dotyczy to sytuacji kiedy do refundacji weszła prezentacja X, a po okresie wskazanym w art. 13 ust. 2 w systemie refundacji pozostaje jedynie prezentacja Y, która ma inną zawartość opakowania (100 mg vs 200 mg). Racjonalnym byłoby przejęcie, że takim punktem odniesienia (do obliczania propozycji) jest jednostka miary substancji czynnej, którą w większości przypadków leków będzie miligram lub DDD lub PDD (w przypadku jeżeli w przeszłości mieliśmy do czynienia z cenami typu flat price)\\tUwaga niezasadna Uwaga jest nieprecyzyjna, jednak wydaje się, że w opisanej sytuacji musi dojść do sytuacji, że jednocześnie na wykazie będzie prezentacja X i Y i obie będą miały wyznaczone rozliczenie w oparciu o tę samą miarę DDD/PDD/mg. Obniżka w art. 13 ust. 2 – 2b ustawy o refundacji dotyczy ceny zbytu netto bądź ceny efektywnej i dotyczy jednakowo obu prezentacji. W przypadku, gdy na wykazie pozostanie wyłącznie prezentacja Y i wywoła to niekorzystny efekt przy obejmowaniu odpowiedników to Minister Zdrowia ma możliwość zareagowania poprzez wyznaczenie odpowiedniej jednostki miary.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 13 ust. 2f ustawy refundacyjnej\\t2f. Jeżeli pierwsza decyzja administracyjna o objęciu refundacją była wydana dla kilku prezentacji leku jednocześnie to jako punkt odniesienia traktowana jest najwyższa cena zbytu netto lub cena efektywna w przeliczeniu na jednostkę miary substancji czynnej lub PDD.\\tWobec możliwości, że lek wszedł lub wejdzie do systemu refundacji w różnych prezentacjach, koniecznym jest uregulowanie takiej sytuacji poprzez ustalenie punktu odniesienia dla obliczeń.\\tUwaga niezasadna Referencja jest w każdym przypadku do wcześniejszej decyzji dla danego leku. Jeśli wnioskodawca ustalił inne koszty za DDD/PDD/mg dla różnych prezentacji to po ustawowej obniżce (jednakowej i zgodnie z przepisem) dla każdej prezentacji ten koszt będzie odpowiedni. Skoro Wnioskodawca już na wstępie ustalił nieliniowe ceny dla różnych prezentacji, to musi liczyć się z tym, że nastąpi jednakowa obniżka w stosunku do pierwotnie zaproponowanych cen. Referencja do najwyższej ceny za DDD/PDD/mg w niektórych przypadkach mogłaby być traktowana jako podwyżka. Natomiast warunek ustawowy będzie zawsze zachowany, gdyby referencja była do najniższego kosztu na DDD/PDD/mg.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 13 ust. 2g ustawy refundacyjnej\\t2g. W przypadku zastosowania mechanizmu, o którym mowa w ust. 2a lub ust. 2b nie znajduje zastosowania ust. 2.\\tCelem uniknięcia zbędnych wątpliwości, należy doprecyzować, że decyzję w zastosowanie jednego z dwóch alternatywnych mechanizmów (ust. 2a i ust 2b), wyłącza możliwość dodatkowego zastosowania mechanizmu z ust. 2.\\tUwaga niezasadna Art. 13 ust 2a i 2b ustawy o refundacji są traktowane jako wyjątki od ust. 2 i Minister Zdrowia nie znajduje uzasadnienia dodawania proponowanego w ust. 2g zapisu.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 13 ust. 2h ustawy refundacyjnej\\t2h. Decyzję o wyborze mechanizmu obniżki ceny, o których mowa w ust. 2 – 2b, podejmuje wnioskodawca.\\tCelem uniknięcia zbędnych wątpliwości, należy doprecyzować, że decyzję w zakresie wyboru odpowiedniego mechanizmu obniżającego cenę podejmuje wnioskodawca.\\tUwaga niezasadna We wskazanym przepisie art. 13 ustawy o refundacji nie ma konieczności doprecyzowania, iż o wyborze mechanizmu obniżki ceny, o którym mowa w ust. 2-2b, decyduje Wnioskodawca, z uwagi na fakt, iż w obecnym kształcie przepisów o sposobie obniżki ceny, co do zasady decyduje Wnioskodawca, składając swoją propozycję przy wniosku o refundację leku oraz przedstawiając ofertę na negocjacjach z Komisją Ekonomiczną. Nie wyklucza to jednocześnie możliwości zaproponowania innego mechanizmu przez Komisję Ekonomiczną czy Ministra Zdrowia. Wprowadzenie przepisu doprecyzowującego, że decyzję o wyborze mechanizmu obniżającego cenę podejmuje Wnioskodawca, spowoduje jednocześnie błędną interpretację, iż ani Komisja Ekonomiczna ani Minister Zdrowia nie mają możliwości/elastyczności w formułowaniu swoich propozycji podczas negocjacji z Wnioskodawcą.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 13 ust. 2i ustawy refundacyjnej\\t2i. Jeżeli między wydaniem pierwszej decyzji administracyjnej o objęciu refundacją prezentacji leku, niezależnie od postaci farmaceutycznej, a wygaśnięciem okresu wyłączności rynkowej, o którym mowa w art. 15 ust. 2 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, \\fdoszło do wydania decyzji, o której mowa w art. 24 ust. 1 pkt 2, do zastosowania mechanizmów obniżki ceny, o których mowa w ust. 2 – 2b punktem odniesienia jest najwyższa cena zbytu netto obowiązująca w wyżej wymienionym okresie.\\t\\fMając na uwadze fakt, że to Minister Zdrowia wydaje decyzje, w których podwyższa cenę zbytu netto (a więc akceptuje argumentacje i analizy wnioskodawcy) zasadnym jest aby te \\fceny były brane pod uwagę w kontekście obowiązkowej obniżki ceny. \\t\\fUwaga niezasadna Zapis stoi w sprzeczności z innymi regulacjami zaproponowanymi w projekcie m.in. regulacji, w której określono mechanizm tzw. obniżki kroczącej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13a ust. 1\\t1. Wnioskodawca, składając wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla leku wytwarzanego na terytorium Rzeczypospolitej Polskiej, albo leku wytworzonego z wykorzystaniem substancji czynnej wytworzonej na terytorium Rzeczypospolitej Polskiej lub leku przeznaczonego do wytwarzania na terytorium Rzeczpospolitej Polskiej, może wnioskować o przyznanie maksymalnie jednej z preferencji administracyjnych i jednej z preferencji ekonomicznych, o których mowa w ust. 2, a w przypadku wytwarzania lub przeznaczenia do wytwarzania leku na terytorium Rzeczypospolitej Polskiej z wykorzystaniem substancji czynnej wytworzonej na terytorium Rzeczypospolitej Polskiej - po dwie takie preferencje.\\tTransfer wytwarzania do Polski – zob. uzasadnienie do art. 2 pkt 11ab.\\tUwaga częściowo zasadna Po konsultacjach publicznych Minister Zdrowia wprowadza następujące zmiany: -wydanie decyzji z przywilejami, o których mowa w art. 13a ustawy o refundacji w przypadku zobowiązania się przez Wnioskodawcę do transferu całej technologii (produkcji substancji czynnej oraz całej produkcji leku) do Polski w ciągu 3 lat od daty wejścia w życie decyzji; - brak zasady kolejności wpływu dla procedowania wniosku dla polskiego leku  - pierwszeństwo wejścia na wykaz dla polskich pierwszych odpowiedników leków (po spełnieniu określonych warunków).\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 14 ust. 1 pkt 1 ustawy refundacyjnej\\t1. Minister właściwy do spraw zdrowia, wydając decyzję o objęciu refundacją, dokonuje kwalifikacji do następujących odpłatności na dzień wydania decyzji: 1) bezpłatnie - leku, wyrobu medycznego mającego udowodnioną skuteczność w leczeniu nowotworu złośliwego, zaburzenia psychotycznego, upośledzenia umysłowego lub zaburzenia rozwojowego albo choroby zakaźnej o szczególnym zagrożeniu epidemicznym dla populacji, albo leku, środka spożywczego specjalnego \\fprzeznaczenia żywieniowego stosowanego w ramach programu lekowego albo produktu immunologicznego, o którym mowa w art. 2 pkt 30 lit. a ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne, dla których Minister Zdrowia wydał ostateczną decyzję administracyjną o objęciu refundacją lub decyzję administracyjną o ustaleniu ceny zbytu netto;\\t\\fProponowana zmiana pozostaje w zgodności z interesem ekonomicznym świadczeniobiorców ze względu na zniesienie odpłatności za stosowanie produktów immunologicznych służących do wywoływania czynnej odporności. Zniesienie odpłatności dla tych produktów przyczyni się w konsekwencji istotnie do zwiększenia poziomu zaszczepienia (zwiększenia liczby osób objętych ochroną) przeciwko chorobom zakaźnym w populacjach docelowych, \\fzdefiniowanych decyzją Ministra Zdrowia o objęciu refundacją lub ustaleniu urzędowej ceny zbytu tych produktów. Zwiększenie zakresu profilaktyki pierwotnej przy zastosowaniu szczepień ochronnych, wpłynie również na zmniejszenie wydatków płatnika publicznego ponoszonych na leczenie chorób zakaźnych i ich powikłań oraz kosztów społecznych wynikających z chorobowości, absencji w pracy i przedwczesnej umieralności z powodu chorób zakaźnych.  Tym samym, produkty immunologiczne, o których mowa w art. 2 pkt 30 lit. a ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne powinny być wydawane świadczeniobiorcom nieodpłatnie ze względu na zapewnienie równego dostępu do ochrony przed chorobami zakaźnymi wszystkim świadczeniobiorcom, u których zastosowanie profilaktyki jest wskazane w oparciu o dowody naukowe i potwierdzone wydaną przez Ministra Zdrowia decyzją refundacyjną.  Podejście egalitarne do szczepień ochronnych umożliwi realizację działań chroniących obecnie zdrowie społeczeństwa i przyszłych pokoleń poprzez dążenie do uzyskania odporności zbiorowiskowej przeciwko patogenom odpowiedzialnym za rozprzestrzenianie się chorób zakaźnych i ich konsekwencji zdrowotnych, społecznych i ekonomicznych.   \\t\\fUwaga niezasadna Refundacja produktów, o których mowa w art. 2 pkt 30 lit. a ustawy Prawo farmaceutyczne, tj. leków służących do realizacji szczepień ochronnych, w trybie i na zasadach ustawy o refundacji, jest narzędziem umożliwiającym zabezpieczenie bieżących potrzeb zdrowotnych pacjentów, niemniej nie może zastąpić realizacji programów profilaktycznych dotyczących szczepień ochronnych w różnych obszarach zdrowotnych w zależności od \\fpojawiających się potrzeb epidemiologicznych.  Finansowanie szczepień ze środków publicznych odbywa się co do zasady w ramach Programu Szczepień Ochronnych (PSO). To program dedykowany zapewnieniu dostępności szczepień oraz odpowiedniego poziomu „wyszczepialności” pacjentów, gwarantujący tym samym zapobieganie i zwalczanie chorób zakaźnych w sposób systemowy, obejmując perspektywę społeczną. Szczepionki obejmowane refundacją na podstawie decyzji administracyjnej Ministra Zdrowia, o której mowa w ustawie o refundacji mają przede wszystkim służyć rozszerzeniu wachlarza opcji terapeutycznych dostępnych dla pacjentów w indywidualnych przypadkach i na zasadzie dobrowolności, przy jednoczesnym uwzględnieniu korzyści jakie płyną z działań profilaktycznych. Poziom odpłatności określony obecnie w ustawie dla tej kategorii produktów, skutecznie realizuje ten cel zapewniając faktyczną i ekonomiczną dostępność pacjentów do szczepień ochronnych.  \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\tart. 15 zmiana ust. 1\\t1. Minister właściwy do spraw zdrowia ustala grupy leków, środków spożywczych specjalnego przeznaczenia żywieniowego, wyrobów medycznych, w ramach których wyznacza się podstawę limitu. Grup limitowych nie tworzy się w odniesieniu do leków, środków spożywczych specjalnego przeznaczenia żywieniowego, wyrobów medycznych, o których mowa w art. 6 ust. 1 pkt 4. Produkty lecznicze z importu równoległego, dla których wydano decyzję refundacyjną w trybie art. 39a nie są uwzględniane w grupach limitowych.\\tWyłączenie produktów leczniczych refundowanych w nowym, uproszczonym trybie z grup limitowych jest niezbędne, żeby zmiana nie wpłynęła na poziom refundacji pozostałych produktów leczniczych. Równocześnie to wyłączenie będzie gwarantowało ( w połączeniu z proponowanym zapisem art. 39a ust. 6), że różnica w cenie leku z importu równoległego będzie dawała każdorazowo oszczędności zarówno po stronie pacjenta, jak i NFZu.\\tUwaga niezasadna Wyłączenie produktów leczniczych z importu równoległego, objętych refundacją na podstawie art. 39a ustawy o refundacyji z systemu grup limitowych pozostaje w sprzeczności z istotą konstrukcji limitów finansowania, której celem zgodnie z art. 15 ustawy refundacyjnej jest wprowadzenie mechanizmów konkurencji cenowej (por. M. Pieklak [w:] P. Pieklak (red.), Ustawa o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych. Komentarz, wyd. 1, 2014, art. 15) pomiędzy produktami o podobnej skuteczności terapeutycznej i stosowanymi w analogicznych wskazaniach, niezależnie od rejestracyjnej formy dopuszczenia do obrotu. W konsekwencji, utrzymanie obecnej regulacji pozostaje w pełni uzasadnione z punktu konstrukcji grup limitacyjnych oraz spójności systemu refundacyjnego.\\n\\tNutricia Polska Sp. z o.o.\\tart. 15 ust. 2 ustawy refundacyjnej\\t2. Do grupy limitowej kwalifikuje się: 1) lek posiadający tę samą nazwę międzynarodową albo inne nazwy międzynarodowe, ale podobne działanie terapeutyczne i zbliżony mechanizm działania; 2) środek spożywczy specjalnego przeznaczenia żywieniowego mający ten sam skład jakościowy i ilościowy – z wyłączeniem składników wpływających na smak oraz to samo zastosowanie; \\f3) wyrób medyczny, przy zastosowaniu następujących kryteriów: a) tych samych lub zbliżonych wskazań lub przeznaczeń, w których są refundowane, b) podobnej skuteczności.\\t\\fZ uwagi na argumenty dotyczące zamiennictwa przedstawione w uzasadnieniu zmian do definicji odpowiednika koniecznym jest także wprowadzenie zasady, że grupa limitowa dla środków spożywczych specjalnego przeznaczenia żywieniowego może opierać się tylko o produkty o tożsamym (z wyłączeniem kwestii smakowych) składzie oraz mających to samo zastosowanie (wskazanie).   Takie rozwiązanie nie oznacza jednak ograniczenia grup limitowych tylko do „identycznych” odpowiedników. Pozwoli \\fto także zaliczyć do jednej grupy limitowej produktu w istocie takie same, ale różniące się sposobem przygotowania (formą) – np. produkty w proszku, które potem miesza się z wodą oraz produktu gotowe (których składniki zostały zmieszane na etapie produkcji). Dzięki takiemu rozwiązaniu otrzymamy uzupełnienie zaproponowanego wyżej mechanizmu realnego i bezpiecznego dla pacjentów zamiennictwa.\\t\\fUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 2 pkt 13 lit. b ustawy o refundacji. \\n\\tNutricia Polska Sp. z o.o.\\tart. 15 ust. 5 ustawy refundacyjnej\\t5. Podstawę limitu w przypadku: 1) środka spożywczego specjalnego przeznaczenia żywieniowego - stanowi cena hurtowa za jednostkę tego środka, dla którego najwyższya spośród najniższych kosztów 30-dniowego stosowania według cen zbytu netto za jednostkę dopełnia 25% obrotu ilościowego zrealizowanego w tej grupie limitowej w miesiącu poprzedzającym o 3 miesiące ogłoszenie obwieszczenia, o którym mowa w art. 37 ust. 1;\\tZasadnym jest zastosowanie do środka spożywczego specjalnego przeznaczenia żywieniowego rozwiązań analogicznych, jak w przypadku leków czy wyrobów medycznych.  Jednocześnie tak jak zostanie wskazane poniżej, taka zmiana jest konieczna celem odejścia od korzystania z DDD (czy PDD) w odniesieniu do tej kategorii produktów.\\tUwaga niezasadna Minister Zdrowia nie ma na celu odejścia od DDD/PDD w przypadku śsspż. Z uwagi na różnorodność śsspż, ich wartość kliniczna nie może być wyznaczana prostym przeliczeniem jednostki masy lub objętości. Niepodważalna jest konieczność wyznaczenia dawki dobowej preparatu. Przykładowo największa wartość preparatów stosowanych w fenyloketonurii (PKU) to zawartość białka w dawce produktu, a nie całkowita jego masa/objętość. Ocena farmakoekonomiczna, w tym porównanie kosztu żywienia czy suplementacji różnymi środkami spożywczymi stosowanymi w tym samym stanie klinicznym oraz wyznaczenie środka spożywczego którego stosowanie faktycznie dopełnia 25% obrotu ilościowego, biorąc pod uwagę jego zużycie, nie jest możliwa bez wyliczenia kosztu ich stosowania w określonym przedziale czasowym. Minister Zdrowia stoi na stanowisku, iż usunięcie przesłanki czasu stosowania w przypadku śsspż spowoduje zakłamanie rzeczywistej wartości produktów \\f(białko/kcal) – zwiększy się wartość produktów nieskondensowanych, a zmniejszy produktów skondensowanych.\\n\\tNutricia Polska Sp. z o.o.\\tart. 15 ust. 7 ustawy refundacyjnej\\t7. W przypadku wydania decyzji o objęciu refundacją pierwszego odpowiednika refundowanego w danym wskazaniu podstawą limitu w grupie limitowej jest cena hurtowa za DDD tego odpowiednika – w odniesieniu do leków albo za jednostkę – w odniesieniu do wyrobów medycznych oraz środków spożywczych specjalnego przeznaczenia żywieniowego. W przypadku objęcia refundacją kolejnych odpowiedników podstawa limitu nie może być wyższa niż cena hurtowa za DDD pierwszego odpowiednika – w odniesieniu do leków, albo za jednostkę pierwszego odpowiednika – w odniesieniu do wyrobów medycznych oraz środków spożywczych specjalnego przeznaczenia żywieniowego.\\tZmiana jest konsekwencją zmian do art. 15 ust. 5 oraz ust. 15.\\tUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 15 ust. 5 oraz ust. 15 ustawy o refundacji. \\n\\tNutricia Polska Sp. z o.o.\\tart. 15 ust. 7a ustawy refundacyjnej\\t7a. W przypadku gdy w danej grupie limitowej więcej niż jeden lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny jest pierwszym odpowiednikiem, do obliczeń, o których mowa w ust. 7, wykorzystuje się cenę hurtową produktu odpowiednio o najniższej cenie zbytu netto za DDD lub o najniższym koszcie 30-dniowego stosowania według cen zbytu netto, lub o najniższej cenie zbytu netto za jednostkę.\\tZmiana jest konsekwencją zmian do art. 15 ust. 5 oraz ust. 15.\\tUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 15 ust. 5 oraz ust. 15 ustawy o refundacji. \\n\\tNutricia Polska Sp. z o.o.\\tart. 15 ust. 13 ustawy refundacyjnej\\t13. Przepisy ust. 11-12 stosuje się odpowiednio w przypadku: 1) leków, dla których DDD nie zostało określone, \\f2) środków spożywczych specjalnego przeznaczenia żywieniowego - o których mowa w art. 6 ust. 1 pkt 2 i 3, z zastrzeżeniem, że w odniesieniu do środków spożywczych specjalnego przeznaczenia żywieniowego zastosowanie zamiast DDD mają jednostki.\\t\\fZmiana jest powiązana z dodaniem ust. 15 do art. 15.\\tUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 15 ust. 5 oraz ust. 15 ustawy o refundacji. \\n\\tNutricia Polska Sp. z o.o.\\tart. 15 ust. 15 ustawy refundacyjnej\\t15. Jednostką dla środka spożywczego specjalnego przeznaczenia żywieniowego jest 100 g proszku albo 100 ml płynu zawartego w jednostkowym opakowaniu.\\t\\tMiara DDD jest z powodzeniem stosowana w produktach leczniczych, ponieważ jest uniwersalna i obiektywna, ponieważ ustalana zewnętrznie – wartość DDD dla leku ustala i publikuje w domenie publicznej WHO.  \\t \\tDla środków spożywczych specjalnego przeznaczenia żywieniowego WHO nigdy nie ustalała DDD, ponieważ w leczeniu żywieniowym nie ma to merytorycznego uzasadnienia. Dawkowanie środków spożywczych specjalnego przeznaczenia żywieniowego zależy od wieku, wagi i stanu klinicznego pacjenta, więc liczba DDD w opakowaniu dla różnych pacjentów będzie różna. Tak jest np. w przypadku produktów dla niemowląt i dzieci stosowanych w alergii, gdzie z powodu braku zewnętrznie ustalonego DDD, jego wartość ustalana jest arbitralnie raz na podstawie wartości kalorycznej gotowego produktu (produkty aminokwasowe), a kiedy indziej tylko na podstawie liczby karmień (produkty zhydrolizowane) i ilości proszku potrzebnego do przygotowania porcji zgodnie z informacjami na etykiecie.   \\t \\t\\fRozszerzenie zasad wyliczania podstawy limitu w grupie z zastosowaniem miary DDD (czy w innych sytuacjach na PDD) z leków m.in. na środki spożywcze specjalnego przeznaczenia żywieniowego spowodowało, że wartość DDD (lub PDD) ma często większe znaczenie w wyliczaniu limitów finansowania i dopłat pacjentów niż sama cena produktu. Tak jest m.in. w przypadku produktów w grupie 217.8, w ramach której refundowanych jest 5 produktów dwóch producentów dla pacjentów w różnym wieku w opakowaniach 400 g. W tym przypadku liczbę DDD w opakowaniu ustalano na podstawie uśrednionej liczby karmień, co powoduje, że 2 produkty dla niemowląt do 6 miesiąca życia są zawsze najdroższe dla pacjentów (liczba DDD w puszce jest niska, bo produkty są jedynym źródłem pożywienia), mimo niższej ceny niż produkt wyznaczający podstawę limitu, ale przeznaczony dla pacjentów od 6 miesiąca do 18 roku życia (gdzie arbitralnie ustalono, że liczymy DDD zakładając że pacjenci od szóstego miesiąca życia do pełnoletności potrzebują 2 karmień dziennie produktem, więc liczba DDD w opakowaniu jest znacząco wyższa niż w przypadku produktu dla niemowląt od urodzenia do 6 miesiąca życia. Nutricia wielokrotnie zwracała uwagę podczas negocjacji cenowych w latach 2016-2018, że warto byłoby rozważyć rozdzielenie grupy limitowej 217.8 na dwie grupy: grupę produktów 1 i grupę produktów 2, bo wówczas dopłaty do produktów dla najmłodszych pacjentów \\fbyłyby niższe – zobacz tabelka nr 1 pod propozycjami zmian. \\t \\tGdyby przyjąć zaproponowane przez Nutricia rozwiązanie dotyczące art. 15 ust. 2 Ustawy, które zakłada, że w jednej grupie limitowej znajdują się praktycznie produkty, które w uzasadnionej sytuacji mogą być zamienione, jednostką stanowiącą podstawę do wyliczeń wysokości limitu finansowania dla wszystkich produktów w grupie (nawet tak heterogennej jak grupa 217.8) mogłaby być jednostka produktu rozumianego jako 100 gram proszku albo 100 mililitrów płynu zawartego w jednostkowym opakowaniu dopełniającym 25 % obrotu. W tym modelu dopłatę pacjenta determinuje jedynie wysokość ceny i produkt dopełniający 25% obrotu w grupie, a nie przyjęte arbitralnie założenie, że w opakowaniu X jest 3 DDD, a Y 5. Gdyby produkty o tym samym składzie miały różne wielkości opakowania, zastosowalibyśmy poniższe wyliczenia stosując je w odpowiednich proporcjach. Wysokość dopłaty NFZ do produktów dla niemowląt od urodzenia do 6 miesiąca życia rośnie, ale za to dopłaty dla pacjentów do wszystkich produktów stają się podobne.  \\t \\tTaką teoretyczną sytuację ilustruje tabela nr 2 na str. 25, która odzwierciedla teoretyczną sytuację, kiedy w grupie limitowej 217.8 zastosujemy zaproponowany przez Nutricia rozwiązanie nowego sposobu określania podstawy limitu i liczenia wysokości \\fdopłat świadczeniobiorców bez stosowania arbitralnie określanego DDD. Dla porównania tabela nr 1 na str. 25 przedstawia aktualny sposób wyliczania podstawy limitu w grupie 217.8 i jego konsekwencje w postaci zróżnicowanych dopłat dla świadczeniobiorców. \\t \\tDopełnieniem uzasadnienia merytorycznego dla zasadności proponowanej zmiany są doświadczenia wynikające z charakteru portfolio produktów Nutricia stosowanych u pacjentów z fenyloketonurią. \\t \\tW przypadku produktów stosowanych przez pacjentów z fenyloketonurią, istnieje praktyka umieszczania w jednej grupie limitowej tylko preparatów o tożsamym składzie jakościowym i ilościowym w różnych wariantach smakowych. Podkreślaliśmy, że takie rozwiązanie zapewnia pacjentom z fenyloketonurią pełny dostęp do kilkudziesięciu produktów, które są stosowane w różnych konfiguracjach w zależności od stanu klinicznego pacjenta, jego wieku, indywidualnych potrzeb, a także specyficznej tolerancji. Praktyka stosowania tych preparatów polega na tym, że pacjenci preparaty łączą, zmieniają, modyfikują, co powoduje, że nie sposób określić wiarygodnego DDD / PDD dla każdego z nich. Za każdym razem, kiedy odbywają się negocjacje cenowe nowych produktów dla pacjentów z fenyloketonurią, powtarzamy te same dyskusje z Komisją Ekonomiczną o tym, że nie można \\fokreślić DDD / PDD dla nowego produktu, bo w zasadzie musiałoby być ono inne dla każdego pojedynczego pacjenta. Bo pacjenci różnią się nie tylko wiekiem, wagą i stanem klinicznym, ale przede wszystkim nie stosują pojedynczych preparatów tylko kombinacje różnych produktów.  \\t \\tZ przyczyn formalnych Ministerstwo Zdrowia ustaliło dla tych produktów wartości DDD, a właściwie PDD (na wniosek Nutricia dane te zostały Nam udostępnione – załącznik 3 do pisma przewodniego), ale w żadnej mierze nie odzwierciedlają one realiów stosowania przez pacjentów. Nie powinny być zatem brane pod uwagę np. w procesie liczenia kosztów stosowania danego produktu w przeliczeniu na pacjenta, z czym często spotykaliśmy się podczas negocjacji cenowych.  \\t \\tO tym, że proponowane podejście jest zasadne, świadczy fakt, że potencjalnie negatywne skutki stosowania DDD / PDD dla tej kategorii produktów stosowanych w fenyloketonurii są już teraz w praktyce minimalizowane przez umieszczanie w jednej grupie limitowej tylko tożsamych produktów w różnych wariantach smakowych. Dzięki temu dopłaty pacjentów pozostają na poziomie stawki ryczałtowej, co stanowi o pełnej dostępności preparatów dla pacjentów. O ile łatwiej – zamiast rozwiązywania tego problemu w opisany sposób - byłoby przyjęcie rozwiązania zaproponowanego w kolumnie po lewej stronie. \\t \\t\\f \\t\\t\\fUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 15 ust. 5 ustawy o refundacji.  Minister Zdrowia podkreśla, iż wartość kliniczna śsspż nie jest determinowana jedynie jego masą lub objętością.  Proponowane założenia w tym zakresie nie wspierają prowadzenia analiz farmakoekonomicznych wśród śsspż oraz mogą prowadzić do problemów z wyznaczaniem właściwych odpłatności dla tej grupy produktów. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tart. 16b ust. 7a-7d ustawy refundacyjnej\\t7a. W posiedzeniach Zespołu Koordynacyjnego może uczestniczyć świadczeniobiorca i jego lekarz prowadzący w zakresie, w jakim posiedzenie dotyczy świadczeniobiorcy. 7b. Rozstrzygnięcia, o których mowa w ust. 2 pkt 1 i pkt 3, są wydawane w formie decyzji administracyjnych i doręczane świadczeniobiorcy. 7c. Od decyzji, o których mowa w ust. 7b, świadczeniobiorcy przysługuje odwołanie do ministra właściwego do spraw zdrowia. Rozpatrując odwołanie, minister właściwy do spraw zdrowia zasięga opinii konsultanta krajowego z dziedziny medycyny odpowiedniej dla danego programu lekowego. 7d. Zespół Koordynacyjny podejmuje decyzje w sposób niezależny, w oparciu o dokumentację medyczną świadczeniobiorcy oraz po uzyskaniu opinii lekarza prowadzącego. Zespół Koordynacyjny może przeprowadzić lub zlecić przeprowadzenie badania świadczeniobiorcy, jeśli jest to potrzebne do wydania decyzji, o których mowa w ust. 7b.\\tObecne rozwiązania dotyczące Zespołów Koordynacyjnych nie przewidują podmiotowego traktowania pacjenta, w tym zagwarantowania jego praw.  W rezultacie art. 16b ustawy refundacyjnej powinien przewidywać: udział pacjenta w procesie podejmowania decyzji o jego prawie do leczenia oraz udział jego lekarza prowadzącego; wskazanie, że (i) decyzje o kwalifikacji oraz (ii) decyzje o wyłączeniu świadczeniobiorców z programów mają formę decyzji administracyjnych podlegających kontroli sądowej (w celu zabezpieczenia praw pacjentów), \\twskazanie podstaw do wydania tych decyzji.\\tUwaga niezasadna Propozycje zgłaszającego uwagę są nieracjonalne, zwłaszcza w kontekście oczekiwania wydawania przez Zespół Koordynacyjny decyzji administracyjnych. Tak ukształtowane zasady jedynie utrudniłyby dostęp do leczenia zamiast go uprościć powodując dodatkowe bariery administracyjne trudne do zrealizowania. Ustawodawca wprowadzając możliwość udziału w posiedzeniu ww. zespołu - bez prawa głosu przedstawiciela organizacji pacjentów wspierających pacjentów z daną chorobą uznał za zasadne z uwagi na unikalne doświadczenie pacjentów w zakresie doświadczenia choroby (patient experience) i funkcjonowania systemu, które pozwalają dostrzec aspekty nie widziane i często pomijane przez profesjonalistów medycznych, a dotyczące zwłaszcza organizacyjnej, praktycznej strony programów. Pacjenci mają swojego przedstawiciela w Radzie Przejrzystości- przedstawiciele Rzecznika jak i organizacji pacjentów bez prawa głosu. Każda osoba ma prawo zgłosić uwagę do opublikowanej Analizy weryfikacyjnej Agencji po wypełnieniu deklaracji konfliktu interesów. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 18a ust. 2 ustawy refundacyjnej\\t2. Minister właściwy do spraw zdrowia może, po podjęciu przez Komisję uchwały, o której mowa w art. 18 ust. 3, przeprowadzić dodatkowe negocjacje z wnioskodawcą w szczególności w zakresie, o którym mowa w art. 18 ust. 1 pkt 1, 3 i 4, \\fbiorąc pod uwagę kryteria, o których mowa w art. 19 ust. 2, jeżeli uzna to za konieczne ze względu na niezaspokojone potrzeby świadczeniobiorców oraz możliwości płatnicze podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych.\\t\\fMinisterstwo Zdrowia zaproponowało bardzo dobrą zmianę polegającą na usunięciu ust. 1 z art. 18a.  Warto jednak jeszcze doprecyzować mechanizm negocjacji na linii \\fwnioskodawca – Minister Zdrowia (które odbywają się po negocjacjach z Komisją Ekonomiczną). Zaproponowana poprawka ma na celu rozszerzenie katalogu sytuacji, w których MZ może przeprowadzić dodatkowe negocjacje z wnioskodawcą oraz doprecyzowanie, że w toku takich dodatkowych negocjacji MZ może dyskutować z wnioskodawcę nie tylko – choć w szczególności – cenę zbytu netto, wskazania refundacyjne oraz RSS-y, a także nowy element negocjacji z Komisją Ekonomiczną tj. wielkość dostaw. Obecnie obowiązujące brzmienie art. 18a ust. 2 jest zbyt restrykcyjne.  Prowadzi ono bowiem do bezcelowego zablokowania możliwości negocjacyjnych MZ \\n(w zakresie innym niż cena zbytu netto, wskazania refundacyjne oraz RSS-y), co jak wskazano powyżej jest z zasady niekorzystne z punktu widzenia dostępu polskich pacjentów do refundowanej terapii, a co więcej, jest także niespójne z proponowanym w obecnej nowelizacji rozszerzeniem zakresu przedmiotu negocjacji z Komisją Ekonomiczną.  Taka restrykcyjna blokada jest także sprzeczna z podstawowymi zasadami i celami procedury refundacyjnej, przede wszystkim dlatego, że w sposób nieuzasadniony osłabia rolę MZ, a więc organu odpowiedzialnego za wydanie decyzji refundacyjnych.\\t\\fUwaga częściowo zasadna  Przedmiotowa zmiana umożliwi Ministrowi Zdrowia prowadzenie negocjacji również z uwzględnieniem nowych przesłanek wskazanych w art. 18 ust. 1 ustawy o refundacji, tj. \\fzobowiązania do zapewnienia ciągłości dostaw, o którym mowa w art. 12 pkt 14, zapewniającego zaspokojenie potrzeb populacji. Zasadnym jest to, by katalog przesłanek ustawowych był zamknięty.\\n\\tZwiązek Pracodawców  \\fInnowacyjnych Firm Farmaceutycznych INFARMA\\t\\fArt. 24 ust. 6e ustawy \\frefundacyjnej\\t\\fSkreśla się ust. 6e \\f6e. Decyzje, postanowienia oraz inne pisma wydane w toku postępowania w sprawie refundacji leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego prowadzonego za pomocą SOLR uznaje się za doręczone z chwilą ich podpisania i umieszczenia w skrzynce odbiorcy. \\t\\fNowelizacja z 2023 r. wprowadziła rozwiązanie, które stanowi zaprzeczenie zasad funkcjonujących w postępowaniu \\fadministracyjnym, gdzie doręczenie liczy się od chwili odebrania korespondencji lub po upływie terminu 14 dni od przekazania pisma odbiorcy. Co istotne, takie zasady znajdują zastosowanie także w przypadku ustawy z dnia 18 listopada 2020 r. o doręczeniach elektronicznych (zob. np. art. 41 i 42 tej ustawy). Zgodnie z art. 24 ust. 6e „Decyzje, postanowienia oraz inne pisma wydane w toku postępowania w sprawie refundacji leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego prowadzonego za pomocą SOLR uznaje się za doręczone z chwilą ich podpisania i umieszczenia w skrzynce odbiorcy.”. Takie rozwiązanie może generować wiele problemów. Dotyczy to przede wszystkim sytuacji, w których wyznaczono krótki termin na odpowiedź. Jeżeli pismo zostanie umieszczone w SOLR np. w piątek wieczorem, to praktycznie nikt nie zapozna się z nim do poniedziałku, a w związku z nowym brzmieniem przepisów wyznaczony termin już będzie płynął i wnioskodawca będzie miał realnie 2 dni mniej na reakcję. Innym problemem jest sytuacja, w której adresat pisma może przebywać na urlopie lub (krótkim) zwolnieniu lekarskim, a inne osoby nie będą podłączone w SOLR do danego postępowania. Wówczas termin może upłynąć faktycznie bez wiedzy wnioskodawcy. \\tWobec powyższego zasadnym jest usunięcie tego rozwiązania i stosowanie \\fzasad doręczenia wynikających z Kodeksu postępowania administracyjnego (tak jak miało to miejsce do 1 listopada 2023 r.).\\t\\fUwaga niezasadna Wprowadzony od 1 listopada 2023 r. nowelizacją ustawy o refundacji art. 24 \\fust. 6e ustawy o refundacji miał na celu usprawnienie procesu refundacyjnego. W świetle dużej ilości wniosków refundacyjnych (w 2024 r. ich liczba wyniosła 4588) oraz jeszcze większej liczby pism składanych w postępowaniach refundacyjnych duże znaczenie ma czas oczekiwania na odbiór pisma przez Wnioskodawcę. Często brak odbioru takiego pisma uniemożliwiał dalsze działanie Organu. Z dotychczasowej praktyki, po wprowadzeniu przedmiotowego procesu nie zidentyfikowano, poza pojedynczymi przypadkami uwag od strony Wnioskodawców w tym zakresie. Przepis funkcjonuje w porządku prawnym już ponad 1,5 roku i od tego czasu Wnioskodawcy wiedząc o jego stosowaniu szybciej zapoznają się z przekazanymi w SOLR pismami. Powyższa zmiana skraca proces refundacyjny.\\n\\tNutricia Polska Sp. z o.o.\\tart. 24 ust. 7 ustawy refundacyjnej\\t7. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia: (…) 2) minimalne wymagania, jakie muszą spełniać analizy, o których mowa w art. 25 pkt 14 lit. c oraz lit. ca i art. 25a pkt 14 oraz art. 26 pkt 2 lit. h, ha oraz i, biorąc pod uwagę potrzebę zapewnienia niezbędnej wiarygodności i precyzji tych analiz, koniecznej do podjęcia na ich podstawie adekwatnych decyzji o objęciu refundacją.\\t\\tZmiana w tym zakresie jest konsekwencją zmian dotyczących analiz HTA dla środków spożywczych specjalnego przeznaczenia żywieniowego (zmiany dotyczące wniosków – do art. 25 oraz art. 26 ustawy).\\tUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 25 pkt. 14 ustawy o refundacji. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 25 pkt 7a ustawy refundacyjnej\\t7a) zakres ograniczeń w zakresie preskrypcji, o których mowa w art. 6 ust. 2b, jeżeli wnioskodawca o to wnioskuje;\\t\\tZobacz uzasadnienie do artykułu Art. 6 ust. 2b UR.\\tUwaga niezasadna Jedynie do decyzji Ministra Zdrowia pozostaje wskazanie jakichkolwiek ograniczeń w obwieszczeniu, o którym mowa w art. 37 ust. 1 ustawy o refundacji. Jednocześnie Wnioskodawca może zawrzeć we wniosku refundacyjnym taką propozycję, która zostanie przez Organ rozpatrzona. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 25 pkt 8a ustawy refundacyjnej\\t8a) wskazanie obowiązującej stawki podatku od towarów i usług w rozumieniu ustawy z dnia 11 marca 2004 r. o podatku od towarów i usług (Dz.U. z 2024 r. poz. 361) dla wnioskowanego leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego;\\tCena podana w decyzji refundacyjnej (oraz we wniosku refundacyjnym) to cena zbytu netto. Wobec powyższego, realizując podnoszone przez Rząd postulaty deregulacyjne, postulujemy o wykreślenie obowiązku podania tej informacji we wniosku refundacyjnej.  W tym kontekście istotnym pozostaje, że jest to kwestia prawa, a nie faktu, więc organ administracji publicznej jakim jest Minister Zdrowia powinien sam ustalić stawkę podatku VAT. \\t\\fWarto również wskazać, że takiego obowiązku nie ma w przypadku analogicznych wniosków tj. wniosków z art. 25a i 25b ustawy refundacyjnej.\\t\\fUwaga niezasadna Ustawodawca nie przewiduje zmian w przedmiotowym zakresie. Wskazanie stawki VAT na etapie wniosku i dokumentacji umożliwia właściwe ustalenie ostatecznej ceny. Brak tej informacji prowadziłoby do niejasności i ryzyka nieprawidłowości rozliczeń między płatnikiem publicznym a podmiotami odpowiedzialnymi. Usuniecie tego obowiązku mogłoby prowadzić do sytuacji, w której środki publiczne byłyby wydatkowane w sposób mniej kontrolowany a także utrudniałyby nadzór nad zgodnością stosowanych cen \\fz obowiązującymi przepisami prawa podatkowego. Ponadto, stawka VAT wynika bezpośrednio z przepisów o podatku od towarów i usług oraz rozporządzeń wykonawczych, a organ prowadzący postępowanie nie ma kompetencji do jej samodzielnego określania czy kształtowania.  Obowiązek podania stawki VAT pełni funkcję informacyjną i porządkującą w postępowaniu refundacyjnym. Usunięcie tego obowiązku mogłoby prowadzić do sytuacji, w której konieczne byłby każdorazowe odwoływanie się do zewnętrznych regulacji podatkowych na etapie weryfikacji dokumentów, co utrudniałoby sprawne prowadzenie postępowania i mogłoby powodować rozbieżności interpretacyjne.\\n\\tNutricia Polska Sp. z o.o.\\tart. 25 pkt 14 ustawy refundacyjnej\\t14) uzasadnienie wniosku zawierające: a) dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który ma co najmniej jeden odpowiednik refundowany w danym wskazaniu - analizę wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, b) (uchylona) c) dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu: - analizę kliniczną, sporządzoną na podstawie przeglądu systematycznego w porównaniu z innymi możliwymi do zastosowania w danym stanie klinicznym \\fprocedurami medycznymi we wnioskowanym wskazaniu, w tym, o ile występują, finansowanymi ze środków publicznych, - analizę ekonomiczną z perspektywy podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych oraz świadczeniobiorcy, - analizę wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, - (uchylone), ca) dla środka spożywczego specjalnego przeznaczenia żywieniowego, który nie ma odpowiednika refundowanego w danym wskazaniu: - analizę problemu decyzyjnego, zawierającą przegląd dostępnych dowodów na skuteczność i bezpieczeństwo, - analizę wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, d) informacje dotyczące działalności naukowo-badawczej i inwestycyjnej wnioskodawcy w zakresie związanym z ochroną zdrowia na terytorium Rzeczypospolitej Polskiej oraz w innych państwach członkowskich Unii Europejskiej lub państwach członkowskich Europejskiego Porozumienia o Wolnym Handlu (EFTA);\\t\\t\\fŚrodek spożywczy specjalnego przeznaczenia żywieniowego istotnie różni się od leków oraz wyrobów medycznych. Wobec tego niezasadnym jest utrzymywanie dla tej kategorii produktów refundowanych takiego samego, bardzo rygorystycznego poziomu analiz HTA.  \\t \\tPropozycja uproszczenia analiz dołączanych obligatoryjnie do wniosków dla nowych produktów w nowych wskazaniach z kategorii środków spożywczych specjalnego przeznaczenia żywieniowego wynika już z charakterystyki samej kategorii – producenci środków spożywczych specjalnego przeznaczenia żywieniowego nie prowadzili i prawdopodobnie nie będą prowadzić wysokiej jakości, typowych dla \\fproduktów leczniczych randomizowanych badań klinicznych dla swoich produktów, ponieważ w Unii Europejskiej praktycznie tylko we Francji i w Polsce wymagane jest od producentów żywności medycznej przygotowywanie analiz HTA w procesie refundacyjnym. W Polsce wymogi formalne dla nowych produktów z kategorii FSMP są takie same jak dla innowacyjnych leków, natomiast kategorie są nieporównywalne pod względem bezpieczeństwa stosowania. \\t \\tW tym zakresie zasadnym wydaje się więc uproszczenie części klinicznej, poprzez ograniczenie się do przeglądu dostępnych dowodów na skuteczność wnioskowanej terapii, w ramach analizy problemu decyzyjnego. Konsekwentnie w przypadku FSMP koniecznym byłaby rezygnacja z przygotowania i przedłożenia we wniosku refundacyjnym analizy ekonomicznej. Kwestie finansowane omawiałaby analiza wpływu na budżet.  \\t \\tTakie rozwiązanie pozwoli dostosować poziom analiz do danych dostępnych środków spożywczych specjalnego przeznaczenia żywieniowego, a jednocześnie nadal pozwoli Agencji przeprowadzać analizy celem ustalenia zasadności ekonomicznej i klinicznej refundacji danego produktu.\\t\\fUwaga niezasadna Mając na uwadze racjonalne gospodarowanie środkami pochodzącymi ze składek obywateli Minister Zdrowia każdorazowo waży zasadność objęcia refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego kierując się zasadami medycyny opartej na dowodach naukowych (EMB) oraz oceny technologii medycznych (HTA). Minister Zdrowia, przed wprowadzeniem do ogólnodostępnej refundacji systemowej kolejnych produktów musi mieć pewność, iż ich finansowanie jest uzasadnione naukowo i klinicznie. Z uwagi na powyższe od Wnioskodawców wymaga się pełnej analizy klinicznej i ekonomicznej, z przedstawieniem danych potwierdzających niezaprzeczalny, \\fpozytywny wpływ na życie pacjenta oraz danych o koszcie stosowania preparatu, określonych zgodnie z wymaganiem HTA.  Biorąc pod uwagę powyższe, mając przy tym również na względzie równe traktowanie przedsiębiorców starających się o objęcie refundacją leków i wyrobów medycznych Minister Zdrowia uznaje uwagę za niezasadną. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 25c ust. 3 ustawy refundacyjnej\\t3. Jeżeli po złożeniu wniosku kontynuacyjnego, o którym mowa w ust. 1, następuje wygaśnięcie dotychczasowej decyzji dotyczącej refundacji leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, minister właściwy do spraw zdrowia może umorzyć umarza postępowanie wszczęte na podstawie tego wniosku, o ile taka sytuacja wynika z opóźnień spowodowanych z winy wnioskodawcy.\\tUstawą z dnia 17 sierpnia 2023 r. o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw wprowadzono do Ustawy refundacyjnej nową przesłankę obligatoryjnego umorzenia postępowania refundacyjnego. Jest to jednak rozwiązanie nieproporcjonalne oraz mogące godzić bezpośrednio w interesy polskich pacjentów, co szczegółowo omówiono poniżej.  Wprowadzenie takiego maksymalnego terminu postępowania stoi w istocie w sprzeczności z naczelnym celem postępowania refundacyjnego. Nie jest nim bowiem jak najszybsze zakończenie postępowania, ale zapewnienie pacjentom potrzebnej terapii. Sztuczne przyśpieszanie momentu zakończenia postępowania nie znajduje żadnego uzasadnienia w ratio legis Ustawy refundacyjnej. Dodatkowo warto wskazać, że takie obligatoryjne umorzenie postępowania może nastąpić z powodu czynników zupełnie niezależnych od wnioskodawcy (w tym także działań samego organu), który chce dalej kontynuować postępowanie. Mając powyższe na uwadze, w niniejszej poprawce zaproponowano odstąpienie od obligatoryjności umarzania postępowania refundacyjnego i pozostawienie Ministrowi Zdrowia („MZ”) możliwości skorzystania z tej instytucji.  \\fObowiązująca od 1 listopada 2023 r. przesłanka umorzenia powoduje de facto wypaczenie tej instytucji postępowania administracyjnego. Zgodnie z art. 105 k.p.a. postępowanie może być umorzone, gdy z jakiejkolwiek przyczyny stało się ono bezprzedmiotowe w całości albo w części lub gdy wystąpi o to strona na wniosek, której toczy się to postępowanie. Nowelizacją wprowadzono natomiast rozwiązania, które kończą trwające postępowanie refundacyjne wcale nie dlatego, że stało się ono w istocie bezprzedmiotowe (z uwagi na wygaśnięcie dotychczasowej decyzji). W przypadku procedury refundacyjnej nie ma natomiast żadnych przesłanek, które pozwalałyby uznać, że postępowanie prowadzone w terminie przekraczającym ważność poprzedniej decyzji refundacyjnej staje się bezprzedmiotowe (szczególnie, że te elementy nie stanowią kryteriów refundacyjnych z art. 12 u.r.). Wręcz przeciwnie, jego kontynuowanie jest o tyle zasadne, że może pozwolić wydać nową decyzję refundacyjną.  \\tZresztą skutkiem takiego umorzenia będzie przecież konieczność przedłożenia nowego wniosku o objęcie refundacją, co w praktyce oznacza długi (niepotrzebny) okres braku dostępności do leku dla polskich pacjentów.\\t\\fUwaga niezasadna Zdaniem Ministra Zdrowia zapis użyty w ustawie jest wystarczający. Przepis jest przejrzysty i Minister Zdrowia nie widzi podstaw do jego rozszerzenia. Tak zaproponowana zmiana spowodowałaby dodatkowe bariery administracyjne, paraliżując harmonogram cyklicznej pracy nad kolejnym obwieszczeniami refundacyjnymi. Obecnie przyjęte regulacje wyznaczają dyscyplinę dla wszystkich uczestników procesów refundacyjnych, tak aby system refundacyjny mógł właściwie funkcjonować. Ustawa pozostawia możliwość złożenia nowego wniosku o objęcie refundacją, co stanowi drogę dla Wnioskodawcy w przypadku niedopilnowania obowiązującej wszystkich wskazanej wyżej dyscypliny, pozostawiając w perspektywie możliwość dostępu do refundowanej terapii dla pacjentów. \\n\\tNutricia Polska Sp. z o.o./ Związek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tdodanie art. 25f do ustawy refundacyjnej\\tMinister właściwy do spraw zdrowia może, w trybie art. 155 ustawy z dnia 14 czerwca 1960 r. - Kodeks postępowania administracyjnego, zmienić decyzję o objęciu refundacją środka spożywczego specjalnego przeznaczenia żywieniowego w zakresie jego nazwy lub jego danych \\fidentyfikacyjnych, w przypadku, jeżeli taka zmiana jest spowodowana względami technicznymi.\\t\\t\\fW przypadku środków spożywczych specjalnego przeznaczenia żywieniowego często dochodzi do drobnych zmian technicznych (które nie przechodzą żadnych procedur rejestracyjnych) – co istotnie odróżnia tę kategorię dostępności od leków – przez \\fco koniecznym jest zmiana numeru GTIN. Inną sytuacją (często niezależną od polskiego wnioskodawcy refundacyjnego) jest zmiana nazwy produktu, która wynika z globalnego lub europejskiego rebranding’u.  \\t \\tTakie sytuacje w obecnym stanie prawnym prowadziłyby do konieczności uchylenia obowiązującej decyzji refundacyjnej i wydania nowej (jako że zgodnie z aktualną praktyką i podejściem Ministerstwa Zdrowia) decyzja refundacyjna jest „przypisana” do konkretnego GTINu. \\t \\tW duchu podnoszonych w ostatnim czasie postulatów deregulacyjnych, które mają na celu usprawnienie i ułatwienie pracy przedsiębiorców, prosimy więc o przyjęcie rozwiązania, które spowoduje, że nie będzie konieczne przechodzenie przez nowe postępowanie refundacyjne, a jedynie „podmianę” w obowiązującej decyzji refundacyjnej GTINu lub nazwy (w istocie tego samego produktu). \\t \\tCo istotne, takie rozwiązanie jest bezpieczne z perspektywy systemowej. Stanowi ono uprawnienie, a nie obowiązek Ministra Zdrowia i w przypadku, kiedy Minister Zdrowia uznałby, że zmiany źródło zmian nie ma charakteru technicznego, mógłby zaproponować wnioskodawcy złożenie nowego wniosku refundacyjnego połączonego z tzw. „skróceniem” technicznym. \\tDodatkowo zaproponowany mechanizm stanowić będzie odciążenie \\fDepartamentu Polityki Lekowej i Farmacji, którego pracownicy nie będą musieli przeprowadzać całego postępowania refundacyjnego, a jedynie krótsze postępowanie z art. 155 KPA. \\tUzasadnienie NFARMA: W przypadku leków (ale także innych produktów) występują zmiany dotyczące numeru GTIN.  Takie zmiany wynikają np. z niezależnych od wnioskodawcy zmian miejsca wytwarzania leku, czy zmiany podmiotu odpowiedzialnego (na podmiot z innego kraju).  \\tWobec tego, analogicznie do ułatwienia w zakresie zmiany adresata decyzji refundacyjnej, zasadnym jest wprowadzenie mechanizmy, który pozwoli na sprawne i niewymagające wszczynania postępowania refundacyjnego działanie, którego celem byłoby jedynie zastąpienie numeru GTIN (w niektórych sytuacjach możemy sobie wyobrazić także związaną z tym zmianę nazwy), przy pozostawieniu niezmienionych pozostałych elementów decyzji administracyjnej (co wynika z braku istotnych zmian dot. produktu oraz wskazań refundacyjnych).\\t\\fUwaga niezasadna Praktyka Ministra Zdrowia w zakresie wymagalności złożenia wniosku o objęcie refundacją nowego GTIN produktu podyktowana jest szczególnym znaczeniem identyfikacyjnym tegoż \\fnumeru i nie jest rozważana zmiana podejścia w tym zakresie.  Zmiany określane terminem „technicznych” są aktualnie przeprowadzanie postępowaniem z art. 155 kpa – na zasadach i zgodnie z przepisami prawa. \\n\\tNutricia Polska Sp. z o.o.\\tdodanie art. 26 lit. h ustawy refundacyjnej\\tWniosek, o którym mowa w art. 24 ust. 1 pkt 2, zawiera, jeżeli dany lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny: (…) 2) nie ma odpowiednika refundowanego w danym wskazaniu: (…)  h) analizę kliniczną i ekonomiczną, jeżeli w uzasadnieniu wniosku są podane argumenty związane z efektem \\fzdrowotnym, dodatkowym efektem zdrowotnym lub kosztami ich uzyskania – w przypadku leku albo wyrobu medycznego, ha) analizę problemu decyzyjnego, zawierającą przegląd dostępnych dowodów na skuteczność i bezpieczeństwo, jeżeli w uzasadnieniu wniosku są podane argumenty związane z efektem zdrowotnym, dodatkowym efektem zdrowotnym lub kosztami ich uzyskania – w przypadku środka spożywczego specjalnego przeznaczenia żywieniowego,\\t\\t\\tUwaga niezasadna Mając na uwadze racjonalne gospodarowanie środkami pochodzącymi ze składek obywateli MZ każdorazowo waży zasadność objęcia refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego kierując się zasadami medycyny opartej na dowodach naukowych (EMB) oraz \\foceny technologii medycznych (HTA). Minister Zdrowia, przed wprowadzeniem do ogólnodostępnej refundacji systemowej kolejnych produktów musi mieć pewność, iż ich finansowanie jest uzasadnione naukowo i klinicznie. Z uwagi na powyższe od Wnioskodawców wymaga się pełnej analizy klinicznej i ekonomicznej, z przedstawieniem danych potwierdzających niezaprzeczalny, pozytywny wpływ na życie pacjenta oraz danych o koszcie stosowania preparatu, określonych zgodnie z wymaganiem HTA.  \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\tzmiana art. 30 ust. 1\\t1. Wymagania, o których mowa w art. 24 ust. 2 pkt 1 i 1a, art. 25 pkt 3, 4, 7, 12 i 13, art. 26 pkt 1 lit. g oraz pkt 2 lit. g, art. 28 pkt 7 lit. c, nie dotyczą wniosków, o których mowa w art. 24 ust. 1, składanych przez wnioskodawcę będącego importerem równoległym.\\tDalsze wyłączenia mają na celu ułatwienie procedury administracyjnej dla importerów równoległych oraz zdjęcie z nich obowiązków, których adresatami nie powinni być z uwagi na specyfikę możliwości pozyskiwania produktów leczniczych poprzez import równoległy (obowiązek zapewnienia ciągłości dostaw oraz obowiązek zapewnienia rocznej wielkości dostaw).\\tUwaga niezasadna  Uwaga częściowo przewidziana w samym projekcie w zakresie wymagań, o których mowa w art. art. 24 ust. 2 pkt 1 i 1a ustawy o refundacji. Niewskazane jest jednak rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji. Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów \\fniezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu.\\n\\tLobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tzmiana art. 30 ust. 1\\t1. Wymagania, o których mowa w art. 24 ust. 2 pkt 1 i 1a, art. 25 pkt 3, 7, 12 i 13 oraz 14 lit. c i lit. d, art. 26 pkt 1 lit. g oraz pkt 2 lit. g, art. 28 pkt 7 lit. c, nie dotyczą wniosku, o którym mowa w art. 24 ust. 1, składanego przez wnioskodawcę będącego importerem równoległym.\\tProponowane wyłączenia mają na celu ułatwienie procedury administracyjnej dla importerów równoległych oraz zdjęcie z nich obowiązków, których adresatami nie powinni oni być z uwagi na specyfikę możliwości pozyskiwania produktów leczniczych poprzez import równoległy.\\tUwaga niezasadna Częściowo przewidziana w samym projekcie w zakresie wymagań, o których mowa w art. art. 24 ust. 2 pkt 1 i 1a ustawy o refundacji. Niewskazane jest jednak rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji. Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu.\\n\\tNutricia Polska Sp. z o.o.\\tdodanie art. 30 ust. 4 ustawy refundacyjnej\\t4. Nie podlega opłacie, o której mowa w art. 32, wniosek, o którym w art. 24 ust. 1 pkt 5, dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego zawartego w wykazie, o którym mowa w art. 37 ust. 1, w danym wskazaniu, złożony w celu wydania decyzji o objęciu refundacją i ustaleniu ceny zbytu \\fnetto dla tego samego leku w tym samym albo szerszym wskazaniu.\\t\\t\\fPropozycja ułatwień dotyczących tzw. skrócenia technicznego nie powinna dotyczyć tylko leków, ale powinna obejmować także pozostałe kategorie produktowe tj. środki spożywcze specjalnego przeznaczenia żywieniowego oraz wyroby medyczne.\\tUwaga zasadna \\n\\tOgólnopolska Izba Gospodarcza Wyrobów Medycznych POLMED\\tDodanie art. 30 ust. 7-10 ustawy refundacyjnej\\tdodaje się ust. 7-10 w brzmieniu 7. Do wniosku, o którym w art. 24 ust. 1 pkt 1 złożonego dla wyrobu medycznego różniącego się od tego samego wyrobu medycznego, który na dzień złożenia wniosku zawarty jest już w wykazie, o którym mowa w art. 37 ust. 1, wyłącznie numerem GTIN zgodnym z systemem GS1 lub innym kodem jednoznacznie identyfikującym wyrób medyczny, stosuje się ust. 8 i 9, jeżeli wniosek złożony jest w celu wydania decyzji o objęciu refundacją i ustaleniu ceny zbytu netto w tym samym wskazaniu i wnioskodawca złoży ministrowi właściwemu do spraw zdrowia oświadczenie o stosowaniu trybu z art. 30 ust. 7-9 niniejszej ustawy. 8. Jeżeli cena zbytu netto oraz cena efektywna wyrobu medycznego proponowane we wniosku, o którym mowa w ust. 7, nie są wyższe niż cena zbytu netto oraz cena efektywna dla tego samego wyrobu różniącego się wyłącznie numerem GTIN zgodnym z systemem GS1 lub innym kodem jednoznacznie identyfikującym wyrób medyczny, obowiązujące na dzień złożenia wniosku, w decyzji administracyjnej o objęciu refundacją dla wyrobu, o którym mowa w ust. 7, minister właściwy do spraw zdrowia wskazuje cenę zbytu netto zgodną z propozycją wnioskodawcy. \\f9. Decyzję administracyjną o objęciu refundacją, o której mowa w ust. 8, minister właściwy do spraw zdrowia wydaje na okres nie dłuższy niż okres obowiązywania decyzji o objęciu refundacją dla tego samego wyrobu, ujętego w wykazie, o którym mowa w art. 37 ust. 1, różniącego się wyłącznie numerem GTIN zgodnym z systemem GS1 lub innym kodem jednoznacznie identyfikującym wyrób medyczny. 10. Dla celów ust. 7-9 za ten sam wyrób medyczny uznaje się wyrób medyczny tego samego wnioskodawcy mający takie samo przewidziane zastosowanie oraz właściwości, także jeżeli posiada on inny numer GTIN zgodny z systemem GS1 lub inny kod jednoznacznie identyfikujący wyrób medyczny niż wyrób znajdujący się na dzień złożenia wniosku w wykazie, o którym mowa w art. 37 ust. 1, pod warunkiem, że stanowi on ten sam wyrób medyczny w rozumieniu rozporządzenia 2017/745 lub ten sam wyrób medyczny do diagnostyki in vitro w rozumieniu rozporządzenia 2017/746. 11. Wprowadzone do obrotu jednostkowe opakowania wyrobu medycznego, dla którego wydano decyzję o objęciu refundacją w trybie ust. 7-9, zalicza się na poczet zobowiązania, o którym mowa w art. 11 ust. 2 pkt 9, określonego w decyzji administracyjnej o objęciu refundacją wyrobu ujętego w wykazie, o którym mowa \\fw art. 37 ust. 1, różniącego się wyłącznie numerem GTIN zgodnym z systemem GS1 lub innym kodem jednoznacznie identyfikującym wyrób medyczny.\\t\\t\\fW celu zabezpieczenia dostępności dla pacjentów wyrobów medycznych na wypadek uaktualnienia przez producenta kodu GTIN/EAN na opakowaniu wyrobu (przy jednoczesnym braku jakichkolwiek innych zmian oraz zachowaniu tożsamości między wyrobami medycznymi oznaczonymi różnymi kodami) uzasadnione jest wprowadzenie szczególnego trybu, pozwalającego na objęcie refundacją kolejnego numeru GTIN tego samego wyrobu, przy zachowaniu na liście refundacyjnej wyrobu opatrzonego dotychczasowym kodem GTIN. \\tIstotne jest jednak uniknięcie sytuacji, w której w wykazie występowałby ten sam wyrób medyczny (oznaczony wprawdzie różnym kodem GTIN, ale będący dokładnie tym samym wyrobem medycznym w rozumieniu rozporządzenia 2017/745), tego samego wnioskodawcy, ale posiadający różne ceny zbytu netto. Prowadzić mogłoby to bowiem to dyskryminacji części pacjentów. \\tProponowana procedura, oparta o mechanizm przedstawiony przez Ministerstwo Zdrowia w nowym art. 30aa, pozwalałaby na objęcie refundacją kolejnego kodu GTIN tego samego wyrobu medycznego – z zachowaniem dotychczasowej ceny zbytu netto. Decyzja dla wyrobów opatrzonych nowym kodem GTIN wydawana byłaby wyłącznie na okres obowiązywania decyzji refundacyjnej dla dotychczasowego kodu GTIN.  \\t\\fRównocześnie zasadne jest utrzymanie na liście refundacyjnej także wyrobów oznaczonych dotychczasowym kodem GTIN, aby nie dopuścić do utraty finansowania dla tych egzemplarzy wyrobów, które zostaną wprowadzone do obrotu jeszcze przed zmianą kodu i wciąż znajdować się będą na rynku. Brak uwzględnienia poprzedniego kodu uderzyłby w apteki ogólnodostępne i hurtownie farmaceutyczne posiadające zapas takich wyrobów, a przede wszystkim w pacjentów, którzy mogliby utracić dostęp do refundowanych wyrobów w okresie pomiędzy zmianą decyzji a dostawą egzemplarzy z nowymi kodami do aptek ogólnodostępnych.\\t\\fUwaga niezasadna Zmieniany jest art. 30 ust. 4 ustawy o refundacji umożliwi skrócenia techniczne dla wyrobów medycznych.  Uzasadnieniem dla przedłożonej propozycji dodania w art. 30 ustawy o refundacji ust. od 7 do 10 jest mechanizm zaprojektowany przez Ministra Zdrowia w art. 30aa ustawy o refundacji. Wyjaśnić zatem należy, że Minister Zdrowia proponuje wprowadzenie możliwości, by dla leku ujętego w obwieszczeniu, o którym mowa w art. 37 ust. 1 i w obwieszczeniu, o którym mowa w art. 37av ust. 14 ustawy – Prawo farmaceutyczne, ten sam wnioskodawca mógł złożyć wniosek o objęciu refundacją, dla tego samego leku w obcojęzycznym opakowaniu w przypadku uzyskania zgody, o której mowa w art. 4c ww. ustawy o refundacji. Powyższe podyktowane jest zaobserwowanymi na przestrzeni lat problemami w zakresie dostępności leków i polega na zapewnieniu ścieżki szybkiej refundacji leku w sytuacjach jego braku, gdy jedyną możliwością zapewnienia dostępności jest refundacja w innym niż polskojęzyczne opakowaniu lub z dołączoną do nich ulotką w języku obcym. Co więcej nie dotyczy to każdego refundowanego leku a jedynie tego ujętego w obwieszczeniu, o którym mowa w art. 37av ust. 14 ustawy – Prawo farmaceutyczne. Powyższa procedura zwiększy bezpieczeństwo i dostępność leków i zapobiegnie przerywaniu terapii z uwagi na czasowy brak leków w polskich \\fopakowaniach. Analogicznych braków nie zaobserwowano w zakresie wyrobów medycznych. Dodatkowo należy zauważyć, że w przypadku zmiany kodów GTIN wyrobów medycznych Minister Zdrowia każdorazowo przychyla się do próśb Wnioskodawców w sytuacji złożonych wniosków o objęcie refundacją i ustalenie ceny zbytu netto takiego wyrobu medycznego z nowym kodem identyfikującym wraz z wnioskiem o skrócenie okresu obowiązywania decyzji z dotychczasowym kodem GTIN i przeprowadza postępowania jednoczasowo zgodnie z terminem wskazanym we wnioskach.  Powyższe podejście Organu potwierdza przedstawiana przez reprezentowaną Organizację kwestia wdrażania przepisów unijnych - w tym m.in. rozporządzenia Parlamentu Europejskiego i Rady (UE) 2017/745 z dnia 5 kwietnia 2017 r. w sprawie wyrobów medycznych, która - zgodnie z przekazywaną przez Państwa informacją, wymagała przeprowadzenia procesu re-certyfikacji i uzyskania nowych certyfikatów na poszczególne wyroby medyczne, co skutkowało nie tylko dostosowaniem wyrobów do nowych wymogów, ale również nadaniem im nowych kodów GTIN,\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tzmiana art. 30b ust. 4 ustawy refundacyjnej\\t4. Minister właściwy do spraw zdrowia oraz osoby zatrudnione w urzędzie obsługującym tego ministra są zwolnieni z obowiązku przestrzegania tajemnicy refundacyjnej, jeżeli ujawnienie informacji objętych tą tajemnicą jest niezbędne do: 1) wykonywania zadań związanych z refundacją leków, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych przez Fundusz, Agencję lub świadczeniodawcę; 2) realizacji postanowień umów międzynarodowych, bilateralnych lub porozumień w zakresie wymiany informacji dotyczących refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych; 3) wykonania obowiązków informacyjnych wobec Komisji Europejskiej.\\tInformacje objęte tajemnicą refundacyjną, w tym m.in. treść RSS nie powinna być przekazywana do innych krajów.  Dzięki tajemnicy refundacyjnej wnioskodawcy mogą oferować polskiemu rządowi atrakcyjne warunki finansowe. Jak wskazało samo Ministerstwo Zdrowia w uzasadnieniu do nowelizacji z 2023 r.:  „Poufność tych wiadomości powinna być więc chroniona szczególnie, bowiem ma ona duże znaczenie dla podmiotu je oferującego z uwagi na zachowanie konkurencyjności na rynku farmaceutycznym.  Ujawnienie tych informacji podmiotom lub osobom nieuprawnionym, może stwarzać poważne ryzyko odejścia podmiotów odpowiedzialnych od oferowania takich instrumentów, co biorąc pod uwagę globalizację rynku spowoduje składanie ofert cenowych na leki w cenach wyższych niż obecnie.  W konsekwencji narazi to płatnika publicznego jakim jest Fundusz na ponoszenie wyższych kosztów refundacji leków, co z kolei przy ograniczonym budżecie, spowoduje zmniejszenie liczby refundowanych technologii lekowych i niemożność osiągnięcia celu jakim jest \\fzapewnianie szerokiej gamy dostępnych nowoczesnych opcji terapeutycznych dla pacjentów.” \\tW tym kontekście zasadnym jest więc rezygnacja z przepisu pozwalającego na przekazanie informacji zagranicznym podmiotom.\\t\\fUwaga niezasadna Twierdzenie wskazujące, iż omawiany przepis może prowadzić do nieuprawnionego przekazywania informacji objętych tajemnicą refundacyjną jest nieuzasadnione, gdyż proponowana regulacja zawiera ściśle określone przesłanki ujawnienia tych informacji – wyłącznie w zakresie niezbędnym do (i) wykonania zadań refundacyjnych przez wskazane podmioty publiczne systemu ochrony zdrowia, (ii) realizacji zobowiązań międzynarodowych o charakterze publicznoprawnym lub (iii) wykonania obowiązków informacyjnych wobec Komisji Europejskiej. Jak należy zauważyć przepis ten nie tworzy możliwości przekazywania informacji handlowych podmiotom konkurencyjnym ani nie przewiduje ujawniania danych wrażliwych innym zagranicznym przedsiębiorcom, lecz zapewnia zgodność z obowiązującymi Polskę międzynarodowymi zobowiązaniami prawnymi.  Polska jako członek Unii Europejskiej oraz sygnatariusz licznych umów międzynarodowych uczestniczy w formalnych mechanizmach wymiany informacji dotyczących polityki lekowej i systemów refundacyjnych z innymi \\fkrajami. W szczególności, na podstawie przepisów prawa UE.  \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych               \\\\Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman \\tzmiana art. 31 ust. 2 dodanie ust. 13\\t2. W pierwszej kolejności, rozpatrywane są wnioski, o których mowa w art. 24 ust. 1 pkt 3 oraz wnioski o objęcie refundacją produktów leczniczych z importu równoległego. 13. Wniosek, o którym mowa w art. 24 ust. 1 albo wniosek o ponowne rozpatrzenie sprawy dotyczący tego wniosku, jeżeli dotyczy on produktu leczniczego z importu równoległego, rozpatruje się w terminie 30 dni, z tym że w przypadku konieczności uzupełnienia danych niezbędnych do rozpatrzenia wniosku, bieg tego terminu ulega zawieszeniu do dnia otrzymania uzupełnienia danych albo do dnia upływu terminu uzupełnienia wniosku.  \\t \\t\\tZ uwagi na wyłączenia wskazane w art. 30 oraz art. 36 wnioski o objęcie produktów leczniczych z importu równoległego są uproszczone w stosunku do innych wniosków, co uzasadnia skrócenie terminów na ich rozpatrzenie.\\tUwaga niezasadna Zmiana w art. 31 ust. 2 ustawy o refundacji, która wprowadza pierwszeństwo rozpatrywania wniosków dotyczących produktów leczniczych z importu równoległego, jest niezasadna. Propozycja ta narusza zasadę równych szans podmiotów ubiegających się o refundację, wprowadzając preferencje dla importu równoległego kosztem innych produktów leczniczych, które mogą mieć równie istotne znaczenie dla zapewnienia dostępności terapii dla pacjentów. Tego typu zmiana może prowadzić do zniekształcenia procesu oceny wniosków refundacyjnych, faworyzując jedną grupę produktów, co w dłuższym okresie może skutkować nierównym dostępem do różnych leków. Ponadto, brak szczegółowego uzasadnienia dla preferencyjnego traktowania importu równoległego może wprowadzać wątpliwości co do zasadności tej regulacji w kontekście ogólnych zasad refundacyjnych, w tym efektywności wydatkowania publicznych środków na refundację. Ustalenie pierwszeństwa dla tego typu wniosków \\fmoże również ograniczać elastyczność systemu refundacyjnego, który powinien priorytetowo traktować te produkty lecznicze, które w sposób najbardziej efektywny zaspokajają potrzeby pacjentów, a nie te, które wynikają z określonych interesów rynkowych. W związku z powyższym, zmiana ta wydaje się nieuzasadniona, zarówno w kontekście zasady równości podmiotów na rynku farmaceutycznym, jak i w odniesieniu do celów efektywnego i sprawiedliwego systemu refundacyjnego.  Dodanie art. 31 ust. 13 do ustawy refundacyjnej, który wprowadza 30-dniowy termin rozpatrywania wniosków dotyczących produktów leczniczych z importu równoległego, z możliwością zawieszenia biegu terminu w przypadku konieczności uzupełnienia danych, jest również niezasadne. Równość i obiektywizm w procesie decyzyjnym są kluczowe dla utrzymania transparentności i uczciwości systemu refundacyjnego, a wprowadzenie preferencyjnego terminu tylko dla produktów z importu równoległego może być postrzegane jako faworyzowanie jednej grupy podmiotów. Wprowadzenie krótkiego, 30-dniowego terminu na rozpatrzenie takich wniosków, z możliwością jego zawieszenia w przypadku uzupełnienia danych, może stanowić nieproporcjonalne obciążenie \\fadministracyjne, zwłaszcza w przypadkach, gdy konieczność uzupełnienia dokumentacji wynika z zawiłości i specyfiki procesów związanych z importem równoległym. Zbyt restrykcyjny termin może prowadzić do powierzchownej analizy wniosków, co może z kolei wpłynąć negatywnie na jakość i rzetelność decyzji administracyjnych. W związku z powyższym, proponowana zmiana nie znajduje uzasadnienia. \\n\\t\\tart. 31 zmiana ust. 2 \\t2. W pierwszej kolejności, rozpatrywane są wnioski, o których mowa w art. 24 ust. 1 pkt 3 oraz wnioski składane przez wnioskodawców będących importerami równoległymi. \\tZmiana ma na celu ustanowienie szybszej ścieżki refundacji dla leków z importu równoległego, dotyczą one bowiem leków, które już są objęte refundacją. Dzięki temu importerzy równolegli będą mieli możliwość wspierania rynku w przypadku braków leków, również w sektorze leków refundowanych.   Od Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman: Zmiana ma na celu ustanowienie szybszej ścieżki refundacji dla leków z importu równoległego, dotyczą one bowiem leków, które już są objęte refundacją. Dzięki temu importerzy równolegli będą mieli możliwość wspierania rynku w przypadku braków leków, również w sektorze leków refundowanych     \\tUwaga niezasadna  j.w.\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\\\ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tart. 31 zmiana ust. 4\\t4. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1 i 1a, albo wniosek o ponowne rozpatrzenie sprawy dotyczący tego wniosku, rozpatruje się w terminie 180 dni, a w przypadku wniosku złożonego przez wnioskodawcę będącego importerem równoległym termin ten wynosi 30 dni, z tym że w przypadku konieczności uzupełnienia danych niezbędnych do rozpatrzenia wniosku, bieg tego terminu ulega zawieszeniu do dnia otrzymania uzupełnienia danych albo do dnia upływu terminu uzupełnienia wniosku. \\tZmiana ma na celu ustanowienie szybszej ścieżki refundacji dla leków z importu równoległego, dotyczą one bowiem leków, które już są objęte refundacją. Dzięki temu importerzy równolegli będą mieli możliwość wspierania rynku w przypadku braków leków, również w sektorze leków refundowanych.  Od Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman Uzasadnienie do Art. 31 amiana ust. 2\\tUwaga niezasadna  Zmiana art. 31 ust. 4 ustawy o refundacji, która przewiduje skrócenie terminu rozpatrywania wniosków składanych przez importerów równoległych do 30 dni, jest niezasadna. Skrócenie terminu rozpatrywania wniosków tylko dla importerów równoległych wprowadza nierówne traktowanie wnioskodawców, co może prowadzić do nieuzasadnionego uprzywilejowania jednej kategorii podmiotów na rynku farmaceutycznym, kosztem innych wnioskodawców. Przyspieszenie procedury rozpatrywania wniosków wyłącznie dla importerów równoległych może skutkować obniżeniem jakości i staranności analizy wniosków. Skrócenie czasu na ocenę wniosku do 30 dni może być niewystarczające do przeprowadzenia pełnej i dokładnej oceny formalnej i merytorycznej, co w dłuższym okresie może wpłynąć na obniżenie skuteczności i rzetelności. Wprowadzenie szybszej ścieżki tylko dla jednej grupy wnioskodawców może również prowadzić do nierównego dostępu do refundacji leków, co może negatywnie wpływać na konkurencję na rynku farmaceutycznym oraz na dostępność leków dla pacjentów. W kontekście ogólnych zasad sprawiedliwości administracyjnej oraz efektywności systemu refundacyjnego, \\fwprowadzenie preferencyjnego terminu tylko dla importerów równoległych jest nieuzasadnione, gdyż może prowadzić do nierówności rynkowych, zniekształcenia procesu refundacji i wprowadzenia niepotrzebnych komplikacji w administracyjnym procesie podejmowania decyzji. \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tart. 31 zmiana ust. 7\\t7. Wniosek, o którym mowa w art. 24 ust. 1 pkt 3, albo wniosek o ponowne rozpatrzenie sprawy dotyczący tego wniosku oraz wnioski składane przez wnioskodawców będących importerami równoległymi rozpatruje się w terminie 30 dni, z tym że w przypadku konieczności uzupełnienia danych niezbędnych do rozpatrzenia wniosku, bieg tego terminu ulega zawieszeniu do dnia otrzymania uzupełnienia danych albo do dnia upływu terminu uzupełnienia wniosku.\\tZmiana ma na celu ustanowienie szybszej ścieżki refundacji dla leków z importu równoległego, dotyczą one bowiem leków, które już są objęte refundacją. Dzięki temu importerzy równolegli będą mieli możliwość wspierania rynku w przypadku braków leków, również w sektorze leków refundowanych.  Od Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman Uzasadnienie do Art. 31 amiana ust. 2\\tUwaga niezasadna Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji.   Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu.\\n\\tStowarzyszenie Importerów \\fRównoległych Produktów Leczniczych\\t\\fzmiana art. 32 dodanie \\fust. 1a, zmiana ust. 2\\t\\f1a. Za złożenie oświadczenia, o którym mowa w art. 39a ust. 1 pobiera się opłatę \\fwnoszoną na rachunek urzędu obsługującego ministra właściwego do spraw zdrowia. Opłata ta stanowi dochód budżetu państwa i nie może być ona wyższa niż 1500 zł. 2. Opłaty, o których mowa w ust. 1, stanowią dochód budżetu państwa i każda z nich nie może być wyższa niż 15 000 zł. W przypadku, gdy opłata uiszczana jest od wniosku dotyczącego produktu leczniczego z importu równoległego to nie może być ona wyższa niż 3000 zł.\\t\\fZ uwagi na uproszczony charakter wniosków / oświadczeń dotyczących \\fproduktów leczniczych z importu równoległego uzasadnione jest obniżenie opłat (rozpatrywanie tych wniosków / oświadczeń jest mniej czasochłonne).\\t\\fUwaga niezasadna \\fProponowane zróżnicowanie opłaty za złożenie wniosku refundacyjnego przez wnioskodawcę będącego importerem równoległym pozostaje w sprzeczności zarówno z konstrukcją systemu refundacyjnego, jak i z zasadą równego traktowania podmiotów ubiegających się o objęcie refundacją.  \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tArt. 32 dodanie ust. 2b\\t2b. Opłata za złożenie wniosku, o którym mowa w art. 24 ust. 1 pkt 1, przez wnioskodawcę będącego importerem równoległym, nie może być wyższa niż 3000 zł.\\tDalsze uproszczenie i przyspieszenie procedury dotyczące importu równoległego uwzględniające nakład pracy związanej z wykonaniem danej czynności i poziom kosztów.  Od Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman:  Dalsze uproszczenie i przyspieszenie procedury dotyczące importu równoległego uwzględniajace nakład pracy związanej z wykonaniem danej czynności i poziom kosztów   \\tUwaga niezasadna Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji.  Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu ich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 33 ust. 1 pkt d ustawy refundacyjnej\\t4) gdy zobowiązanie, o którym mowa w art. 34 ust. 2 11 ust. 2 pkt 9, nie zostanie dotrzymane w zakresie dotyczącym zapewnienia ciągłości dostaw i nastąpi niezaspokojenie potrzeb świadczeniobiorców;\\tNależy uspójnić brzmienie pkt 4 i 5 z art. 33 ust. 1. \\tUwaga niezasadna Minister Zdrowia nie uważa za zasadne ograniczenie odpowiedzialności za niedostarczenie zadeklarowanych dostawa i ich ciągłości do kolejnej przesłanki jaką ma być niezaspokojenie potrzeb świadczeniobiorców podczas gdy nałożenie kar w projektowanej ustawie dotyczy jedynie przypadków, gdy produkt umieszczony jest na liście antywywozowej.   \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 33a ustawy refundacyjnej\\tSkreśla się art. 33a Art. 33a Minister właściwy do spraw zdrowia z urzędu zmienia decyzję administracyjną o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, w przypadku gdy na podstawie przepisów innych ustaw ulegną zmianie elementy objęte tą decyzją.\\tPoprawka ma na celu usunięcie z polskiego porządku prawnego art. 33a Ustawy refundacyjnej, który stanowi istotne naruszenie zasad przewidywalności i pewności prawa.  Przepis ten przewiduje, że MZ z urzędu zmienia decyzję administracyjną o objęciu refundacją, w przypadku, gdy na podstawie przepisów innych ustaw zmianie ulegną elementy objęte tą decyzją.  Tym samym z treści przedmiotowego przepisu wynika faktycznie pełna swoboda MZ, który na podstawie innej niż Ustawa refundacyjna ustawy będzie mógł dowolnie zmienić ostateczne i funkcjonujące w obrocie decyzje refundacyjne, i to bez żadnego wpływu wnioskodawców na ten proces. Takie rozwiązanie może być groźne nie tylko z perspektywy wnioskodawców, którzy są adresatami decyzji refundacyjnych, ale i z perspektywy pacjentów będących beneficjentami takiej decyzji.  \\fWarto również podkreślić, że w uzasadnieniu nowelizacji z 2023 r., którą wprowadzono art. 33a do polskiego porządku prawnego wskazano, że przepis ten jest zasadny z uwagi na potrzebę uwzględnienia zmian stawek podatku, które miałyby mieć wpływ na wysokość urzędowej ceny zbytu (str. 29 i 30 uzasadnienia). Uzasadnienie było jednak w tym zakresie sprzeczne z pozostałymi propozycjami zawartymi w Nowelizacji. Otóż w jej w ramach przewidziano systemową zmianę, która sprowadza się do „odseparowania” decyzji refundacyjnej od problemu stawek podatkowych. Zgodnie bowiem z obecnie obowiązującymi przepisami, w decyzji refundacyjnej jest wskazywana cena zbytu netto (a nie jak miało to miejsce przed wejściem w życie DNUR urzędowa cena zbytu – uwzględniająca podatek VAT). Wobec powyższego nie widać żadnego społecznie uzasadnionego ratio legis przemawiającego za utrzymaniem w Ustawie refundacyjnej art. 33a. Wobec powyższych argumentów za zasadne należy uznać przyjęcie niniejszej poprawki.\\t\\fUwaga niezasadna  Możliwość zmiany decyzji administracyjnej o objęciu refundacją z urzędu przez ministra właściwego do spraw zdrowia jest konieczne z uwagi na zmieniające się przepisy prawa powszechnie obowiązującego. Elementem decyzji o objęciu refundacją i ustaleniu ceny zbytu netto jest nie tylko cena, ale również inne elementy mogące ulegać zmianom.  Jednym z najważniejszych elementów będących jednocześnie przykładem jest  treść wskazań refundacyjnych. Zawierają one kody klasyfikacji chorób, (obecnie ICD-10), które mogą się zmieniać w zależności od ciągle aktualizowanych wytycznych medycznych. Zmiana decyzji refundacyjnej będzie wówczas konieczna z uwagi na potrzebę dostosowania jej zakresu do faktycznie realizowanych schematów leczenia (np. zastąpienie obowiązującej obecnie klasyfikacji ICD-10 na ICD-11).  Dodatkowo zmiany decyzji refundacyjnych są niejednokrotnie konieczne z uwagi na zmieniające się \\fprzepisy proceduralne w ramach postępowania administracyjnego. Dokonywanie zamian z urzędu, bez konieczności uzyskiwania zgód wnioskodawców, umożliwia sprawne i skuteczne dopasowanie decyzji refundacyjnych do zmieniających się przepisów a także upraszcza proces technicznych zmian, które i tak wymagają wdrożenia.  Wymóg uzyskania zgody na zmianę decyzji w zakresie przepisów regulujących procedury administracyjne lub wynikające z aktualizacji medycznych wytycznych stanowi wyłącznie barierę i element obciążający działania administracyjne po stronie organu.\\n\\tNutricia Polska Sp. z o.o.\\tdodanie art. 35 ust. 1 ustawy refundacyjnej\\t1. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu, wraz z analizami, o których mowa w art. 25 pkt 14 lit. c albo lit. ca, oraz wniosek, o którym mowa w art. 24 ust. 1 pkt 1a, dla leku, który nie ma odpowiednika refundowanego w danym wskazaniu wraz z analizami, o których mowa w art. 25a pkt \\f14, a także wniosek, o którym mowa w art. 24 ust. 1 pkt 2, dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu, jeżeli w uzasadnieniu wniosku są podane argumenty związane z efektem zdrowotnym, dodatkowym efektem zdrowotnym lub kosztami ich uzyskania wraz z analizami, o których mowa w art. 26 pkt 2 lit. h oraz i, minister właściwy do spraw zdrowia niezwłocznie przekazuje Prezesowi Agencji za pomocą SOLR, w celu przygotowania: 1) analizy weryfikacyjnej Agencji; 2) stanowiska Rady Przejrzystości; 3) rekomendacji Prezesa Agencji.\\t\\fZmiana w tym zakresie jest konsekwencją zmian dotyczących analiz HTA dla środka spożywczego specjalnego przeznaczenia żywieniowego (zmiany dotyczące wniosków – do art. 25 oraz art. 26 ustawy).\\tUwaga niezasadna Konsekwencja odrzucenia zmian proponowanych do art. 25 pkt. 14 ustawy o refundacji.  Dodatkowo Minister Zdrowia wskazuje za niepodważalną konieczność przygotowania: 1) analizy weryfikacyjnej Agencji; 2) stanowiska Rady Przejrzystości; 3) rekomendacji Prezesa Agencji \\fw przypadku wniosku o którym mowa w art. 24 ust. 1 pkt 2 dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu, jeżeli w uzasadnieniu wniosku są podane argumenty związane z efektem zdrowotnym, dodatkowym efektem zdrowotnym lub kosztami ich uzyskania wraz z analizami, o których mowa w art. 26 pkt 2 lit. h oraz i, który to punkt został pominięty przy proponowaniu niniejszej zmiany (w propozycji zmian jest „art. 26 pkt 2 lit. h oraz i”  powinno być „art. 26 pkt 2 lit. h, ha oraz i”).\\n\\tNutricia Polska Sp. z o.o.\\tdodanie art. 35 ust. 4 ustawy refundacyjnej\\t\\t4. Prezes Agencji niezwłocznie przekazuje analizę weryfikacyjną Agencji w sprawie oceny leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego Radzie Przejrzystości oraz wnioskodawcy, a następnie publikuje ją w Biuletynie Informacji Publicznej Agencji wraz z analizami wnioskodawcy, o których mowa w art. 25 pkt 14 lit. c, art. 25 pkt 14 lit. ca, art. 25a pkt 14 oraz art. 26 pkt 2 lit. h oraz i. Do tych analiz można zgłaszać uwagi w terminie 7 dni od dnia opublikowania\\tZmiana w tym zakresie jest konsekwencją zmian dotyczących analiz HTA dla środka spożywczego specjalnego przeznaczenia żywieniowego (zmiany dotyczące wniosków – do art. 25 oraz art. 26 ustawy).\\tUwaga niezasadna (uzasadnienie: pkt. 93 raportu).\\n\\tNutricia Polska Sp. z o.o.\\tdodanie art. 35 ust. 5 ustawy refundacyjnej\\t5. Analiza weryfikacyjna Agencji zawiera w szczególności: \\t1) ocenę analiz, o których mowa w art. 25 pkt 14 lit. c albo art. 25 pkt 14 lit. c albo art. 25a pkt 14 albo art. 26 pkt 2 lit. h oraz i;\\tZmiana w tym zakresie jest konsekwencją zmian dotyczących analiz HTA dla środka spożywczego specjalnego przeznaczenia żywieniowego (zmiany dotyczące wniosków – do art. 25 oraz art. 26 ustawy).\\tUwaga niezasadna (uzasadnienie: pkt. 93 raportu).\\n\\tPrzedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tdodanie do art. 37 ust 2d ust. ref\\tTworząc wykazy, o których mowa w ust. 2a, 2aa i 2b, minister właściwy do spraw zdrowia, w odniesieniu do kryterium, o którym mowa w art. 43a ust. 1 pkt 1 oraz pkt 2 albo art. 43b ust. 1 ustawy o świadczeniach, uwzględnia w danej grupie limitowej leki, o których mowa w art. 2 pkt 11a lub wytworzone z substancji czynnej o której mowa w art. 2 pkt 21a. W przypadku niezaspokojenia potrzeb świadczeniobiorców minister właściwy do spraw zdrowia może, w następnej kolejności uwzględnić pozostałe leki z daną substancją czynną.\\tMając przede wszystkim na względzie fundamentalny cel jakim jest bezpieczeństwo lekowe Polski, przyświecający zarówno twórcom poprzedniej nowelizacji, jak i będący priorytetem dla urzędującej administracji, powracamy do propozycji przedstawionej w projekcie ustawy o zmianie ustawy o refundacji (DNUR) z 12 sierpnia 2022 r. Dla osiągniecia ww. celu kluczowe jest stworzenie takich zachęt, które w sposób realny przyczynią się do zwiększenia udziału produktów wytwarzanych na terytorium RP i/lub z substancji czynnej wytwarzanej na terytorium RP w rynku leków refundowanych. Rozwiązaniem, które niewątpliwie wpłynęłoby na zwiększenie partycypacji ww. leków jest ich pierwszeństwo przy tworzeniu wykazów 18-, 65+ oraz C+. Jest to tym bardziej uzasadnione, że przedsiębiorcy je wytwarzający zwiększają wpływy do polskiego budżetu, zatrudniając pracowników i odprowadzając podatki w kraju. Obecny kształt list umożliwia bezpłatne wydawanie pacjentom wszystkich odpowiedników z daną substancją czynną, w tym leków oryginalnych, co dodatkowo obciąża budżet płatnika\\tUwaga niezasadna Zwiększenie bezpieczeństwa lekowego Rzeczypospolitej Polskiej zostało wprowadzone do ustawy o refundacji w postaci mechanizmów zapewniających wnioskodawcom preferencje zwiększające stabilności decyzji administracyjnych oraz zwiększenie popytu dla leków produkowanych na terytorium RP. Mają one na celu przede wszystkim premiowanie i wzmacnianie działania przedsiębiorców w zakresie wytwarzania leków na terytorium RP. Listy 65+, ciąża + oraz 18- to z kolei mechanizmy stanowiące odpowiedź na zwiększone potrzeby lekowe w określonych grupach pacjentów. Zgodnie z tym założeniem, w przypadku leków umieszczonych w ww. wykazach, nie ma mechanizmu współpłacenia pacjenta – cały ciężar dopłat ponosi płatnik. Wprowadzenie proponowanego rozwiązania doprowadziłoby do pewnego rodzaju automatyzacji, która skutkowałaby przeniesieniem na płatnika obowiązku pokrycia kosztów preferencji tzw. „polskich leków”, a w konsekwencji wpłynęłaby na znaczne zwiększenie wydatków płatnika. Należy podkreślić, że leki posiadające preferencje przyznane w oparciu o przepisy art. 13a są niejednokrotnie produktami najdroższymi w ramach konkretnej grupy limitowej. Na kształtowanie ceny tych leków, w odróżnieniu od pozostałych leków obejmowanych refundacją, mają wpływ również przyznawane preferencje ekonomiczne. \\fMając na uwadze obecną strukturę kształtowania się cen „polskich leków” vs pozostałych należy stwierdzić, że wprowadzenie takich zmian jest nie do udźwignięcia w ramach aktualnego systemu refundacyjnego.  Zgodnie z analizą wielkości obrotu w 2024 roku prawie 52% wszystkich refundowanych opakowań w aptece zostało wydanych z uprawnieniem 65+ (lista S), a 3,3% wszystkich refundowanych opakowań w aptece w ramach uprawnienia 18- (Lista DZ). \\n\\tPracodawcy RP\\tart. 44 ust. 2c ustawy refundacyjnej\\tOsoba wydająca leki, środki spożywcze specjalnego przeznaczenia żywieniowego oraz wyroby medyczne objęte refundacją może wydać lek w opakowaniu zawierającym różną - o maksymalnie 10 %, liczbę dawek niż określona na recepcie, co dotyczy także leku przepisanego na recepcie.\\tJednoznaczne wskazanie, że zasada 10% dotyczy także produktów przepisanych na recepcie. Zasadność zmiany wynika z umiejscowienia przedmiotowego ustępu w przepisie dot. informowania o zamiennikach oraz ich wydawaniu pacjentom, co stwarza problemy interpretacyjne.\\tPoza zakresem nowelizacji\\n\\tPracodawcy RP\\tart. 88 ust. 4 Pf\\tKierownik apteki wyznacza, na czas swojej nieobecności, farmaceutę, o którym mowa w ust. 1, do jego zastępowania, w trybie określonym w art. 95 ust. 4 pkt 5. Jeśli nieobecność kierownika apteki nie przekracza 30 dni, wówczas farmaceuta wyznaczony do jego zastępowania nie musi spełniać obowiązku określonego w ust. 2 pkt 1.\\tJednoznaczne doprecyzowanie, że w przypadku nieobecności kierownika apteki nieprzekraczającej 30 dni, zastępca nie musi spełniać wymogu dot. stażu pracy, o którym mowa w art. 88 ust. 2 pkt 1. Propozycja ma istotne znaczenie z uwagi na problemy kadrowe aptek, zwłaszcza w zakresie osób spełniających wymogi właściwe dla kierownika apteki (m.in. pięcioletni staż pracy w aptece). Braki te znacząco utrudniają funkcjonowanie aptek z uwagi na konieczność poszukiwania zastępstwa dla kierownika apteki w przypadku jego urlopu czy też choroby i w skrajnych przypadkach powodują konieczność zamknięcia apteki. Problem szczególnie uderza w apteki położone w mniejszych \\fmiejscowościach i na wsi, gdzie poszukiwanie zastępstw jest szczególnie utrudnione. Należy podkreślić, że problemy aptek przekładają się na problemy pacjentów, którzy mają utrudniony, lub wręcz uniemożliwiony dostęp do leków. Zagrożeni są szczególnie pacjenci w mniejszych miejscowościach, którzy w razie zamknięcia jedynej apteki są zmuszeni pokonać odległość kilkanaście km, celem nabycia niezbędnych leków. Przedstawione rozwiązanie pozwoli zredukować problem, poprzez umożliwienie pełnienia zastępstwa przez innego farmaceutę, który nie posiada 5-letniego stażu, w przypadku gdy nieobecność kierownika apteki nie przekracza 30 dni. Zminimalizuje to ryzyko braku dostępów do leków, a jednocześnie nie będzie wiązało się z ryzykiem dezorganizacji pracy apteki.\\t\\fPoza zakresem nowelizacji\\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tArt. 91 ust. 1 pkt 1 PF\\tUprawnienia technika farmaceutycznego  Art. 91 ust. 1 pkt 1 PF odwołuje się do „substancji bardzo silnie działających określonych w Urzędowym Wykazie Produktów Leczniczych dopuszczonych do obrotu na terytorium RP”, podczas gdy Urzędowy Wykaz Produktów Leczniczych („Wykaz”) nie tylko nie określa produktów leczniczych zaklasyfikowanych do produktów zawierających substancje bardzo silnie działające, ale także nie zawiera jakiegokolwiek wykazu substancji uznanych za bardzo silnie działające. Wykaz substancji bardzo silnie działających jest natomiast publikowany w Farmakopei Polskiej (Wykaz A).  Brzmienie przywołanego przepisu, mającego istotne znaczenie praktyczne dla \\fdziałalności aptek, pomimo wielokrotnie sygnalizowanych problemów interpretacyjnych, nie zostało jednak do tej pory znowelizowane. Podejmując jednak działania zmierzające do doprowadzenia zgodności art. 91 ust. 1 pkt 1 PF z rzeczywistą praktyką należy mieć na uwadze również specyfikę punktów aptecznych. W wykazie substancji czynnych wchodzących w skład produktów leczniczych, które mogą być dopuszczone do obrotu w placówkach obrotu w punktach aptecznych, znajdują się substancje z Wykazu A, podczas gdy w większości przypadków podstawowym personelem fachowym zatrudnionym w punktach aptecznych są technicy farmaceutyczni.  W związku z powyższym konieczne jest wprowadzenie takich zmian w treści przepisu art. 91 ust. 1 PF, które zarówno dostosują jego treść do obowiązujących realiów, jak i zapewnią pacjentom nieprzerwany i bezpieczny dostęp do produktów leczniczych.\\t\\tPoza zakresem nowelizacji\\n\\tPracodawcy RP\\tart. 91 ust. 1 pkt 1 PF\\tTechnik farmaceutyczny, posiadający dwuletnią praktykę w aptece w pełnym wymiarze czasu pracy, może wykonywać w aptece czynności fachowe polegające na sporządzaniu, wytwarzaniu, wydawaniu produktów leczniczych i wyrobów medycznych, z wyjątkiem produktów leczniczych mających w swoim składzie: 1) substancje bardzo silnie działające określone w Urzędowym Wykazie Produktów Leczniczych dopuszczonych do obrotu na terytorium Rzeczypospolitej Polskiej, chyba że występują one w produktach leczniczych dopuszczonych do obrotu w punktach aptecznych.\\tRozszerzenie kompetencji techników w zakresie leków z wykazu A, które są dopuszczalne do sprzedaży w punktach aptecznych. Należy wskazać, że działalność punktu aptecznego nie wymaga obecności farmaceuty. Tym samym, aby poszerzenie asortymentu dopuszczalnego do sprzedaży w punkcie aptecznym miało realne przełożenie na dostępność produktów dla pacjentów, konieczne jest także stosowne poszerzenie kompetencji techników farmaceutycznych w zakresie wydawania produktów leczniczych.\\tPoza zakresem nowelizacji\\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tArt. 97 ust. 7a PF\\tW związku z powyższym, dla uniknięcia wątpliwości interpretacyjnych w tym zakresie, proponujemy następujące brzmienie przepisu:  7a. W przypadku realizacji recepty elektronicznej:  1) po upływie 30 dni od daty jej wystawienia albo naniesionej na recepcie daty realizacji \\\"od dnia\\\", recepta jest realizowana z wyłączeniem dni stosowania, które już upłynęły, licząc je od daty wystawienia recepty albo naniesionej na recepcie daty realizacji \\\"od dnia\\\",  2) pacjent od dnia realizacji recepty może otrzymać maksymalnie ilość produktu leczniczego, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego niezbędną pacjentowi do 120-dniowego okresu stosowania wyliczonego na podstawie określonego na recepcie sposobu dawkowania  - przy czym w przypadku produktu leczniczego, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, wydawanego w opakowaniach, których wielkość uniemożliwia wydanie go w ilości niezbędnej do stosowania przez wyliczony okres, dopuszcza się wydanie go w ilości przekraczającej tę ilość, jednak nie więcej niż o jedno najmniejsze opakowanie dostępne w obrocie na terytorium Rzeczypospolitej Polskiej, a w przypadku produktu leczniczego, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego podlegającego refundacji – jedno najmniejsze opakowanie występujące w wykazie określonym w art. 37 ust. 1 ustawy z dnia 12 maja 2011 r. o \\frefundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych.\\t\\frealizacja recepty Przepis art. 96a ust. 7a PF dopuszcza możliwość – w przypadku produktu wydawanego w opakowaniach, których wielkość uniemożliwia wydanie go w ilości niezbędnej do stosowania przez wyliczony okres – wydanie go w ilości przekraczającej tę ilość, jednak nie więcej niż o jedno najmniejsze opakowanie. W tym kontekście wskazać jednak należy, że nie wszystkie zarejestrowane wielkości opakowań są refundowane (w tym najmniejsze) oraz że nie każdy lek występuje w różnych wielkościach opakowań.\\tPoza zakresem nowelizacji\\n\\tPracodawcy RP\\tArt. 97 ust. 7a PF\\tW przypadku realizacji recepty elektronicznej: 1) po upływie 30 dni od daty jej wystawienia albo naniesionej na recepcie daty realizacji \\\"od dnia\\\", recepta jest realizowana z wyłączeniem dni stosowania, które już upłynęły, licząc je od daty wystawienia recepty albo naniesionej na recepcie daty realizacji \\\"od dnia\\\", 2) pacjent od dnia realizacji recepty może otrzymać maksymalnie ilość produktu leczniczego, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego niezbędną pacjentowi do 120-dniowego okresu stosowania wyliczonego na podstawie określonego na recepcie sposobu dawkowania - przy czym w przypadku produktu leczniczego, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, wydawanego w opakowaniach, których wielkość uniemożliwia wydanie go w ilości niezbędnej do stosowania przez wyliczony okres, dopuszcza się wydanie go w ilości przekraczającej tę ilość, jednak nie więcej niż o jedno najmniejsze opakowanie określone w wykazie, o którym mowa w art. 37 ust. 1 ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, a w przypadku produktów leczniczych, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych niepodlegających refundacji – jedno \\fnajmniejsze opakowanie dostępne w obrocie na terytorium Rzeczypospolitej Polskiej.\\t\\fZmiana zasad przekraczania ilości przysługującej pacjentowi w przypadku realizacji recepty elektronicznej.\\tPoza zakresem nowelizacji\\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tPropozycje zmian legislacyjnych umożlwiających stworzenie aptek specjalizujących się w sporządzaniu leków recepturowych część 1\\tUstawa z dnia 6 września 2001 r. – Prawo farmaceutyczne  W art. 86 po ust. 2a dodaje się 2a1 w brzmieniu:  Usługi farmaceutyczne, o których mowa w art. 4 ust. 3 pkt 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty, obejmujące sporządzanie leków recepturowych i aptecznych, mogą być świadczone samodzielnie przez aptekę albo przez powierzenie sporządzenia leku recepturowego lub aptecznego innej aptece na podstawie umowy. Umowa określa w szczególności zasady przekazywania danych niezbędnych do sporządzenia leków oraz danych, które w związku z realizacją recept są sprawozdawane do Narodowego Funduszu Zdrowia, jak również zasady transportu leków. Apteka, w której leki będą sporządzane i apteka, w której leki będą wydawane pacjentom, odpowiadają za jakość wydawanych pacjentom leków i są zobowiązane do zapewniania warunków transportu gwarantujących zachowanie jakości leków recepturowych przemieszczanych pomiędzy nimi.  W art. 86a po ust. 1a dodaje się 1b w brzmieniu:  1b. Apteka ogólnodostępna może zbyć lek recepturowy lub apteczny do innej apteki na podstawie art. 86 ust. 2a1.  W art. 103 ust. 2 pkt 4a otrzymuje brzmienie:  2. Wojewódzki inspektor farmaceutyczny może cofnąć zezwolenie, jeżeli: (…)  4a) apteka przekazuje, z wyłączeniem:  \\fa) Inspekcji Farmaceutycznej,  b) Narodowego Funduszu Zdrowia,  c) SIM,  d) apteki, której zlecono sporządzenie leku recepturowego lub aptecznego na warunkach przewidzianych w art. 86 ust. 2a1,  - dane umożliwiające identyfikację indywidualnego pacjenta, lekarza lub świadczeniodawcy;  Po art. 129e dodaje się art. 129f w brzmieniu:  1. Karze pieniężnej w wysokości do 5 000 zł podlega podmiot prowadzący aptekę, który wbrew obowiązkowi określonemu w art. 4 ust. 3 pkt 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty nie sporządza w ramach apteki leków recepturowych oraz aptecznych bądź nie posiada umowy z inną apteką, o której mowa w art. 86 ust. 2a1.  2. Karę pieniężną, o której mowa w ust. 1, nakłada właściwy miejscowo wojewódzki inspektor farmaceutyczny w drodze decyzji. Wojewódzki inspektor farmaceutyczny jest wierzycielem w rozumieniu przepisów o postępowaniu egzekucyjnym w administracji. \\t\\tPoza zakresem nowelizacji\\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tPropozycje zmian legislacyjnych umożlwiających stworzenie aptek specjalizujących się w sporządzaniu leków \\frecepturowych część 2\\t\\fRozporządzenie z dnia 30 września 2002 r. w sprawie szczegółowych wymogów, jakim powinien odpowiadać lokal apteki  W § 7 dotychczasową treść oznacza się jako ust. 1 i dodaje się ust. 2 w brzmieniu:  1. Apteka musi być wyposażona:  1) w urządzenia umożliwiające sporządzanie leków w postaciach farmaceutycznych wykonywanych w aptekach;  2) w urządzenia umożliwiające prawidłowe przechowywanie produktów leczniczych i \\fwyrobów medycznych w sposób zabezpieczający je przed zakurzeniem i zabrudzeniem.  2. Wymóg wskazany w pkt 1 nie dotyczy aptek, które powierzyły sporządzanie leków recepturowych i aptecznych innej aptece na podstawie umowy.  W § 8 po ust. 1 dodaje się ust. 1a w brzmieniu:  1a. Wymogi, o których mowa w ust. 1 pkt 7, 8, 11, 12 nie dotyczą aptek, które powierzyły sporządzanie leków recepturowych i aptecznych innej aptece na podstawie umowy.  Rozporządzenie z dnia 26 września 2002 r. w sprawie wykazu pomieszczeń wchodzących w skład powierzchni podstawowej i pomocniczej apteki  § 1 otrzymuje brzmienie:  § 1 W skład powierzchni podstawowej lokalu apteki ogólnodostępnej wchodzą następujące pomieszczenia:  1) izba ekspedycyjna;  2) izba recepturowa, która może być wyposażona w śluzę - jeżeli apteka sporządza leki recepturowe lub apteczne;  3) izba do sporządzania produktów homeopatycznych - jeżeli apteka sporządza produkty homeopatyczne;  4) zmywalnia - jeżeli apteka sporządza leki recepturowe lub apteczne;  5) magazyn lub magazyny produktów leczniczych;  6) magazyn lub magazyny do przechowywania asortymentu wymienionego w art. 72 ust. 5 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne, jeżeli jest on prowadzony przez aptekę;  \\f7) pomieszczenie administracyjno-szkoleniowe;  8) komora przyjęć, usytuowana w pobliżu wejścia do apteki przeznaczonego dla dostaw towaru i dla personelu;  9) archiwum.  Rozporządzenie dnia 27 października 2022 r. w sprawie podstawowych warunków prowadzenia apteki  W § 6 w ust. 4 po pkt 3 kropkę zastępuje się średnikiem i dodaję się pkt 4 w brzmieniu:  \\t 4) na rzecz innej apteki zgodnie z art. 86a ust. 2a1 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne.  W § 9 po ust. 2 dodaje się 2a w brzmieniu:  2a. Apteka zlecająca sporządzenie leku recepturowego zobowiązana jest prowadzić ewidencję zleconych do wykonania leków, która zawiera:  a) adres apteki sporządzającej lek recepturowy;  b) datę i czas przyjęcia recepty;  c) datę wydania leku recepturowego;  d) numer kontrolny recepty.  W § 9 po ust. 4 dodaje się 4a w brzmieniu:  4a. Apteka zlecająca sporządzenie leku aptecznego zobowiązana jest prowadzić ewidencję wskazaną w ust. 4 wraz ze wskazanie apteki sporządzającej lek apteczny. \\t\\tPoza zakresem nowelizacji\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\togólne\\t2. Obwieszczenie, o którym mowa w ust. 1, zawiera: 1) dane identyfikujące lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny; 2) kategorię dostępności refundacyjnej; 3) poziom odpłatności; 3a) cenę zbytu netto; \\f3b) cenę hurtową brutto; 4) urzędową cenę zbytu; 5) (uchylony) 6) wysokość limitu finansowania dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, o którym mowa w art. 6 ust. 1 pkt 1 albo informacyjną wysokość limitu finansowania dla leków, środków spożywczych specjalnego przeznaczenia żywieniowego, o których mowa w art. 6 ust. 1 pkt 2 i 3 dostosowaną do wielkości opakowania jednostkowego; 7) wysokość dopłaty świadczeniobiorcy; 8) grupę limitową; 9) termin wejścia w życie decyzji, o której mowa w art. 11 oraz okres jej obowiązywania; 10) dla produktów leczniczych z importu równoległego – odniesienie do produktu leczniczego, o którym mowa w art. 39a ust. 1 pkt 1. 6. Obwieszczenia, o których mowa w ust. 1 i 4, są ogłaszane raz na 2 miesiące w dzienniku urzędowym ministra właściwego do spraw zdrowia co najmniej na 14 dni przed dniem, na który ustala się wykazy, o których mowa w ust. 1 i 4.\\t\\fUmieszczenie w obwieszczeniu informacji o produkcie leczniczym, do którego „referuje” w swoim wniosku importer równoległy ułatwi lekarzom oraz farmaceutom zidentyfikowanie tych samych produktów leczniczych objętych refundacją. \\fZwiększenie częstotliwości ogłaszania obwieszczeń uzasadnione jest wprowadzeniem „szybkiej ścieżki” dla produktów leczniczych z importu równoległego (art. 39a).\\t\\fUwaga niezasadna   Obecny system publikacji obwieszczeń został zaprojektowany z uwzględnieniem równowagi pomiędzy zapewnieniem pełnej informacji dla środowiska medycznego a koniecznością zachowania \\fprzejrzystości i stabilności informacji zawartych w obwieszczeniach. Umieszczanie dodatkowych szczegółowych danych dotyczących produktów leczniczych „referowanych” przez importerów równoległych mogłoby w praktyce prowadzić do nadmiernego skomplikowania obwieszczeń, co utrudniłoby ich czytelność i efektywne wykorzystanie przez lekarzy oraz farmaceutów. Aktualny sposób prezentacji informacji zapewnia już wystarczający poziom identyfikacji produktów refundowanych, przy jednoczesnym zachowaniu przejrzystości dokumentu. Ponadto, należy podkreślić, że wprowadzenie „szybkiej ścieżki” dla produktów leczniczych z importu równoległego nie wymaga automatycznego zwiększenia częstotliwości publikacji obwieszczeń. System refundacji został tak skonstruowany, aby zapewnić elastyczność i sprawność procesów decyzyjnych bez konieczności zmiany częstotliwości publikacji obwieszczeń. Zwiększenie liczby obwieszczeń mogłoby przyczynić się do rozproszenia informacji oraz potencjalnego obciążenia zarówno środowiska medycznego, jak i organów administracji odpowiedzialnych za przygotowanie i publikację tych dokumentów. \\fNależy także zaznaczyć, że obecne przepisy przewidują adekwatne mechanizmy komunikacji oraz udostępniania informacji o produktach refundowanych, które umożliwiają lekarzom i farmaceutom szybki dostęp do aktualnych danych, w tym w szczególności systemy elektroniczne oraz bazy danych prowadzone przez instytucje odpowiedzialne za refundację. Wobec powyższego postulaty dotyczące dodatkowych informacji w obwieszczeniach oraz zwiększenia częstotliwości ich ogłaszania nie są uzasadnione. \\n\\tStowarzyszenie APETYT na życie\\togólne\\tZakres refundacji środków spożywczych specjalnego przeznaczenia żywieniowego (FSMP) 1. Proponujemy, by refundacją mogły być objęte środki spożywcze specjalnego przeznaczenia żywieniowego (FSMP), przeznaczone dla pacjentów z potwierdzonym niedożywieniem lub znaczącym ryzykiem jego wystąpienia, wynikającym z przebiegu choroby podstawowej, u których zachodzi fizjologiczna lub kliniczna niemożność pokrycia zapotrzebowania energetyczno-białkowego standardową dietą doustną. 2. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, grupy terapeutyczne i wskazania kliniczne, w których zachodzi największe ryzyko niedożywienia, w szczególności:    - nowotwory górnego odcinka przewodu pokarmowego oraz głowy i szyi, \\f   - choroby zapalne jelit i zespoły złego wchłaniania (m.in. choroba Leśniowskiego-Crohna, zespół krótkiego jelita), celiaklia, SIBO    - choroby neurologiczne z dysfagią (np. udar mózgu, stwardnienie rozsiane, SLA),    - zaawansowane choroby wątroby, nerek, serca i płuc,    - stany po zabiegach chirurgicznych dużego ryzyka, w szczególności onkologicznych,    - geriatryczna wielochorobowość z zespołem kruchości,    - choroby metaboliczne i neurologiczne wieku dziecięcego (np. mukowiscydoza) 3. Lista wskazań, o której mowa w ust. 2, powinna uwzględniać aktualne wytyczne Europejskiego Towarzystwa Żywienia Klinicznego i Metabolizmu (ESPEN), a także stanowiska krajowych towarzystw naukowych: Polskiego Towarzystwa Żywienia Pozajelitowego, Dojelitowego i Metabolizmu (POLSPEN) Polskiego Towarzystwa Żywienia Klinicznego (PTŻK), Polskiego Towarzystwa Gastroenterologii, Polskiego Towarzystwa Onkologicznego, Polskiego Towarzystwa Geriatrycznego oraz innych towarzystw właściwych dla danego obszaru terapeutycznego. \\t\\tUwaga niezasadna Zgodnie z zapisami ustawy refundacji może podlegać środek spożywczy, o którym mowa w art. 24 ust. 2 pkt 1 i 4 ustawy z dnia 25 sierpnia 2006 r. o bezpieczeństwie żywności i żywienia (Dz.U. z 2023 r. poz. 1448) przeznaczony do dietetycznego odżywiania pacjentów pod nadzorem lekarza, którego stosowania nie można uniknąć przez modyfikację normalnej diety lub podawanie innych środków spożywczych specjalnego przeznaczenia żywieniowego, pod warunkiem uzyskania pozytywnej decyzji Ministra Zdrowia w zakresie objęcia refundacją wydanej po przejściu pełnego procesu refundacyjnego (wniosek wraz z analizami HTA). Wnioskodawca wnioskując o refundację ma prawo określić wskazanie kliniczne w którym produkt powinien być refundowany.\\n\\tStowarzyszenie APETYT na życie\\togólne\\tOcena stanu odżywienia jako kryterium refundacji Refundacja FSMP może następować po uprzednim przeprowadzeniu oceny stanu odżywienia pacjenta z wykorzystaniem walidowanych narzędzi, np.: - Nutrition Risk Screening 2002 (NRS-2002),  - SGA \\f   \\t- Kryteria GLIM (Global Leadership Initiative on Malnutrition). Ciąg dalszy na kolejnej stronie\\t\\tUwaga niezasadna Minister Zdrowia rozważając możliwość systemowego finansowania terapii zobligowany jest do przeanalizowania wszystkich kryteriów decyzji o objęciu refundacją wskazanych w art. 12 ustawy o refundacji. Jednym z nich jest kryterium 4) skuteczności klinicznej i praktycznej, w którym zawierałby się stan odżywienia \\fjako jeden z możliwych punktów oceny klinicznej. Ocena stanu odżywienia jako kryterium refundacji w rozumieniu zawężenia wskazania refundacyjnego produktu leży w gestii wnioskodawcy i sformułowania wskazania do objęcia refundacją w ramach wniosku refundacyjnego. \\n\\tStowarzyszenie APETYT na życie\\togólne\\tUproszczona procedura włączania FSMP do wykazu refundacyjnego 1. W odniesieniu do FSMP o uznanej skuteczności klinicznej Minister może, w drodze obwieszczenia, wprowadzić uproszczony wykaz refundacyjny, niezależny od indywidualnych wniosków producentów. 2. Proponujemy by do wykazu mogły być włączone FSMP, które spełniają łącznie następujące warunki:    - Skuteczność potwierdzona w co najmniej dwóch prospektywnych, randomizowanych publikacjach naukowych opartych o badania kliniczne     - Rekomendacja do stosowania w aktualnych wytycznych towarzystw naukowych zajmujących się żywieniem klinicznym.    - Poparcie konsultanta krajowego odpowiedzialnego za dany obszar terapeutyczny lub zespołu ekspertów wyznaczonego przez ministra. 3. Obwieszczenie Ministra Zdrowia, o którym mowa w ust. 1, jest aktualizowane co najmniej raz na kwartał.\\t\\tUwaga niezasadna Przyjęcie proponowanego rozwiązania leży poza zakresem przedmiotowej regulacji – częściowe żywienie FSMP doustnymi w przytoczonym zakresie należałoby procedować raczej w ramach dedykowanego świadczenia gwarantowanego, analogicznie jak Żywienie dojelitowe warunkach domowych: Żywienie dojelitowe lub Żywienie pozajelitowe w warunkach domowych: Całkowite żywienie pozajelitowe określone w rozporządzeniu Ministra Zdrowia z dnia 6 listopada 2013 r. w sprawie świadczeń gwarantowanych z zakresu ambulatoryjnej opieki specjalistycznej (Dz. U. z 2016 r. poz. 357, z późn. zm.) – mając na uwadze optymalne wykorzystanie zalecanych środków spożywczych oraz ocenę ich skuteczności klinicznej i praktycznej. \\n\\tStowarzyszenie APETYT na życie\\togólne\\tWyroby medyczne do żywienia pozajelitowego w warunkach domowych 1. Do wykazu wyrobów medycznych wydawanych na zlecenie dodaje się: \\f   - przenośne pompy infuzyjne przeznaczone do podaży mieszanin do żywienia pozajelitowego,    - zestawy do ich obsługi, w tym linie infuzyjne I plecaki na mieszaniny I pompy. 2. Refundacja przysługuje pacjentom dorosłym i dzieciom objętym procedurą leczenia żywieniowego pozajelitowego w warunkach domowych, zgodnie z wymogami określonymi przez Narodowy Fundusz Zdrowia. 3. Zlecenie na akcesoria, o których mowa w ust. 1, może być wystawione przez lekarza prowadzącego opiekę nad pacjentem w ramach kontroli okresowej, odbywającej się nie rzadziej niż co 3 miesiące, zgodnie z obowiązującymi standardami NFZ. 4. Minister właściwy do spraw zdrowia określi w drodze rozporządzenia:    - kategorie i ilości wyrobów medycznych przysługujących pacjentom w zależności od rodzaju terapii i wieku,    - miesięczne limity finansowania refundowanego sprzętu.\\t\\tUwaga niezasadna W ramach załącznika nr 5 do rozporządzenia Ministra Zdrowia z dnia 6 listopada 2013 r. w sprawie świadczeń \\fgwarantowanych z zakresu ambulatoryjnej opieki specjalistycznej (Dz. U. z 2016 r. poz. 357, z późn. zm.) wymienione jest świadczenie gwarantowanie „Żywienie pozajelitowe w warunkach domowych: Całkowite żywienie pozajelitowe”. Rozporządzenie kompleksowo precyzuje zasady realizacji tego świadczenia, w tym wymagania formalne, personel, wyposażenie w sprzęt i aparaturę medyczną (pompy infuzyjne do żywienia pozajelitowego), zapewnianie badań diagnostycznych oraz pozostałych wymagań, jak np. przygotowanie pacjenta lub opiekunów do leczenia w warunkach domowych, zapewnienie ciągłego kontaktu telefonicznego z pacjentem lub opiekunami, program badań kontrolnych i dostarczanie preparatów, sprzętu i niezbędnych środków opatrunkowych do domu pacjenta. Należy podkreślić, że z przepisów ww. aktu prawnego nie wynika jaki rodzaj pompy infuzyjnej do żywienia pozajelitowego jest dostarczany pacjentowi w ramach świadczenia - czy może to być model stacjonarny lub przenośny. Przepisy nie wskazują także minimalnego standardu jakościowego np.: parametrów technicznych urządzenia. Jednocześnie obecnie funkcjonujący system zaopatrzenia pacjentów w pompy infuzyjne do żywienia pozajelitowego w ramach ww. świadczeń nie ustala limitu \\ffinansowania dla tej grupy wyrobów medycznych, a pacjent otrzymuje je w ramach świadczenia całkowicie bezpłatnie. Oznacza to, że podmioty lecznicze mające podpisane umowy na realizację świadczenia dokonują zakupu urządzeń w ramach zamówienia publicznego, a następnie zakwalifikowani pacjenci są zaopatrywani w zakupione w przetargu wyroby.  W związku z powyższym należy uznać, że obecnie funkcjonują rozwiązania zapewniające kompleksową opiekę nad pacjentami wymagającymi żywienia pozajelitowego. Ponadto, wprowadzenie na zasadzie odstępstwa od powyższych zasad finansowania elementu świadczenia żywienia pozajelitowego, tj. refundacji przenośnych pomp infuzyjnych do żywienia pozajelitowego (wraz z akcesoriami) w ramach wykazu wyrobów medycznych wydawanych na zlecenie może skutkować podwójnym finansowaniem świadczeń tzn. pacjent jeden wyrób otrzyma w ramach ambulatoryjnej opieki specjalistycznej drugi zaś na zlecenie.\\n\\tStowarzyszenie „UroConti”\\togólne\\tW związku z powyższym sugerujemy rozważenie wprowadzenie minimalnych kryteriów kwalifikacyjnych dla organizacji pacjentów, takich jak: •\\tOkreślony czas działalności (np. minimum 2 lata). •\\tMinimalna liczba zrzeszonych członków lub udokumentowane działania na rzecz pacjentów. •\\tDeklaracja transparentności finansowania organizacji pacjenckiej ze strony firm farmaceutycznych (np. poprzez \\fujawnienie wielkości uzyskanego finansowania za ostatnie 3 lata).\\t\\fZaproponowane zmiany dotyczące udziału organizacji pacjentów  Zgodnie z projektem nowelizacji ustawy refundacyjnej, organizacje pacjentów mają zyskać możliwość udziału w dwóch kluczowych obszarach:  Negocjacje cenowe z Komisją Ekonomiczną: Przedstawiciele organizacji pacjentów mogą uczestniczyć w negocjacjach \\fprowadzonych przez firmy farmaceutyczne z Komisją Ekonomiczną, ale tylko za zgodą firmy i w roli obserwatorów, bez prawa głosu czy podejmowania decyzji. Ich obecność ma obejmować cały proces negocjacyjny, w tym aspekty finansowe, co jest krokiem w stronę większej transparentności. Firmy mają jednak prawo decydować, czy zaprosić przedstawiciela pacjentów, co ogranicza uniwersalność tego rozwiązania.  Zespoły koordynujące programy lekowe: Organizacje pacjentów będą mogły uczestniczyć w pracach zespołów koordynujących programy lekowe, co ma zwiększyć ich wpływ na kształtowanie polityki lekowej i dostępności terapii.  Projekt zakłada także ograniczenie zakresu tzw. tajemnicy refundacyjnej, co ma umożliwić większą przejrzystość negocjacji, w tym dostęp do informacji finansowych. Jednak firmy farmaceutyczne nadal będą mogły ograniczać ujawnianie pewnych danych, szczególnie dotyczących instrumentów dzielenia ryzyka, co może budzić obawy o pełną transparentność.  Ocena zaproponowanych rozwiązań  Zalety:  Większa partycypacja pacjentów: Umożliwienie organizacjom \\fpacjentów udziału w negocjacjach \\ni zespołach koordynujących to krok w stronę większego zaangażowania pacjentów w proces decyzyjny. Może to zwiększyć uwzględnianie perspektywy pacjentów, szczególnie w kwestiach dostępności terapii \\ni ich finansowania.  Transparentność: Propozycja pełnego udziału w negocjacjach, w tym w częściach finansowych, oraz ograniczenie zakresu tajemnicy refundacyjnej to odpowiedź na wieloletnie postulaty środowisk pacjenckich o większą jawność procesów refundacyjnych. Może to przyczynić się do lepszej kontroli społecznej nad wydatkami publicznymi.  Wady i wyzwania:  Ograniczone prawa przedstawicieli pacjentów: Rola obserwatora bez prawa głosu może sprawić, że udział pacjentów będzie symboliczny, a ich wpływ na decyzje pozostanie minimalny.  Zależność od zgody firm: Uwarunkowanie udziału pacjentów zgodą firmy farmaceutycznej stwarza ryzyko, że tylko wybrane organizacje, potencjalnie sprzyjające interesom firm, będą zapraszane. Może to prowadzić do nierówności w reprezentacji środowisk pacjenckich.  \\fTajemnica refundacyjna: Choć projekt zakłada ograniczenie zakresu tajemnicy, firmy nadal mogą zastrzegać kluczowe dane, co może ograniczyć rzeczywistą transparentność. Dodatkowo, przedstawiciele pacjentów będą zobowiązani do zachowania poufności, co może komplikować ich rolę \\nw informowaniu społeczności pacjentów o szczegółach negocjacji.  Dodatkowo brak regulacji dotyczących kryteriów wyboru organizacji pacjentów może prowadzić do sytuacji, \\nw której małe fundacje, założone przez 1-3 osoby, będą chciały reprezentować całe środowisko. Może to podważyć wiarygodność i skuteczność reprezentacji pacjentów.  W związku z powyższym sugerujemy rozważenie wprowadzenie minimalnych kryteriów kwalifikacyjnych dla organizacji pacjentów, takich jak: Określony czas działalności (np. minimum 2 lata). Minimalna liczba zrzeszonych członków lub udokumentowane działania na rzecz pacjentów. Deklaracja transparentności finansowania organizacji pacjenckiej ze strony firm farmaceutycznych (np. poprzez ujawnienie wielkości uzyskanego finansowania za ostatnie 3 lata).  \\fTaki mechanizm pozwoliłby zachować różnorodność reprezentacji, jednocześnie ograniczając ryzyko dominacji przez małe (osobowo), mniej reprezentatywne podmioty. Dodatkowo, Ministerstwo Zdrowia mogłoby stworzyć rejestr kwalifikowanych organizacji reprezentujących pacjentów, wraz z obszarami ich statutowych aktywności terapeutycznych, co ułatwiłoby firmom i Komisji Ekonomicznej wybór optymalnych przedstawicieli.  Zaproponowane zmiany w ustawie refundacyjnej, umożliwiające udział organizacji pacjentów w negocjacjach i zespołach koordynujących, są krokiem w dobrym kierunku. Warto podkreślić, że o takie zmiany Stowarzyszenie „UroConti” wnioskowało wielokrotnie w swojej korespondencji z Ministerstwem Zdrowia, wskazując na potrzebę większej transparentności i rzeczywistej partycypacji pacjentów w procesie refundacyjnym. Skuteczność tych rozwiązań zależy jednak od szczegółów wdrożenia.   Kluczowe wyzwania to ograniczona rola pacjentów jako obserwatorów, zależność od zgody firm oraz potencjalny brak reprezentatywności niektórych organizacji. Te ograniczenia mogą sprawić, że zmiany te będą miały charakter pozorny, tworząc wrażenie większej partycypacji pacjentów, podczas gdy w rzeczywistości ich wpływ na decyzje pozostanie marginalny. Bez zapewnienia realnych mechanizmów wpływu, takich jak prawo do zabierania \\fgłosu czy jasne kryteria wyboru reprezentatywnych organizacji, istnieje ryzyko, że udział pacjentów stanie się jedynie formalnym elementem procesu, nie przekładając się na rzeczywiste uwzględnienie ich potrzeb i perspektywy.\\t\\fPoza zakresem nowelizacji\\n\\tKoalicja „Na pomoc niesamodzielnym”\\togólne\\tUwagi ogólne – znaczenie reprezentacji pacjentów, w tym opiekunów osób niesamodzielnych \\nw procesie refundacyjnym. \\tUczestnictwo w zespołach eksperckich tworzących programy lekowe oraz w charakterze obserwatora podczas negocjacji cenowych leków między Komisją Ekonomiczną MZ a firmą farmaceutyczną. To istotny krok w stronę zwiększenia przejrzystości, społecznego nadzoru oraz partycypacji interesariuszy, których głos przez lata był marginalizowany, zwłaszcza w przypadku środowisk osób niesamodzielnych i ich opiekunów.\\tPoza zakresem nowelizacji\\n\\tKoalicja „Na pomoc niesamodzielnym”\\togólne\\tZalecamy stworzenie rejestru organizacji społecznych uczestniczących w procesach refundacyjnych, prowadzonego np. przez Rzecznika Praw Pacjenta, z uwzględnieniem: •\\ttypu organizacji (pacjencka / propacjencka ekspercko-rzecznicza / propacjencka dedykowana jednemu schorzeniu), •\\ttransparentności działania (sprawozdania, źródła finansowania, historia aktywności, okres działania), •\\tspełnienia kryteriów stopnia rzeczywistej reprezentatywności.  Taki system ograniczyłby zjawisko tzw. „organizacji teczkowych” powoływanych ad hoc przez wąskie grupy interesu, które próbują legitymizować się, jako głos całego środowiska.\\t2.\\tRekomendacja podziału organizacji społecznych – propozycja uporządkowania sceny reprezentacyjnej. Z perspektywy Koalicji zasadnym i koniecznym jest wprowadzenie instytucjonalnego rozróżnienia pomiędzy dwoma typami podmiotów społecznych:  •\\tOrganizacje pacjenckie – skupiające bezpośrednich beneficjentów systemu ochrony zdrowia (pacjentów i/lub ich opiekunów), posiadające strukturę członkowską, przejrzystość finansową  i demokratyczne mechanizmy reprezentacji. Przykład: UroConti, Fundacja SMA. •\\tOrganizacje propacjenckie (ekspercko-rzecznicze) – think tanki, platformy współpracy, koalicje wielosektorowe działające na rzecz grup szczególnych (np. osoby niesamodzielne, \\fopiekunowie nieformalni, seniorzy, osoby z chorobami rzadkimi). Przykład Koalicja. •\\tInne organizacje propacjenckie (fundacje założone przez pojedynczych pacjentów  lub ich opiekunów).\\t\\fPoza zakresem nowelizacji\\n\\tKoalicja „Na pomoc niesamodzielnym”\\togólne\\tProponujemy:  •\\tZapewnienie równych szans udziału organizacji poprzez wprowadzenie procedury nominacji prowadzonej przez MZ lub RPP (np. rotacyjny udział przedstawicieli z zatwierdzonej listy NGO). •\\tOkreślenie kryteriów merytorycznych (np. doświadczenie w analizie HTA, udział w dialogu klinicznym) dla reprezentantów organizacji propacjenckich – w przypadku Koalicji oznaczałoby  to uwzględnienie wiedzy o specyfice leczenia pacjentów niesamodzielnych (np. żywienie dojelitowe, produkty specjalnego przeznaczenia żywieniowego, farmakoterapia paliatywna). •\\tUporządkowanie kwestii tajemnicy refundacyjnej – rekomendujemy wprowadzenie jednolitego wzorca oświadczenia o poufności (NDA) oraz systemu rejestrowania udziału obserwatorów.\\tUdział w negocjacjach cenowych – szanse i ryzyka  Zaproponowana możliwość obecności organizacji pacjenckich i propacjenckich, jako obserwatorów  w procesach negocjacyjnych z Komisją Ekonomiczną to dobry kierunek, ale wymaga dalszego rozwinięcia.\\tUwaga niezasadna Zgodnie z obowiązującymi przepisami ustawy o refundacji, postępowania o objęcie refundacją i ustalenie ceny zbytu netto dla leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, mają charakter wnioskowy. Podmioty odpowiedzialne lub ich przedstawiciele składają wnioski do ministra właściwego do spraw zdrowia, które są procedowane w oparciu o przepisy kodeksu postępowania administracyjnego. Oznacza to, że proces ustalenia praw i obowiązków wnioskodawcy odbywa się pomiędzy Stronami postępowania administracyjnego. Przepisy ustawy o refundacji przewidują wiele etapów procesu refundacyjnego, uwzględniających opinię ciał doradczych lub pozostałych interesantów, w tym również organizacji pacjenckich. Wszelkie uwagi, postulaty i wnioski organizacje pacjenckie mogą zgłaszać bezpośrednio do Ministra Zdrowia, mogą również przekazywać swoje stanowiska w ramach postępowań prowadzonych przez AOMTiT, np. poprzez zgłaszanie uwag do Analiz Weryfikacyjnych publikowanych przez Agencję. Informacje o procedowanych przez \\fAOMTiT wnioskach są publicznie dostępne w BIP Agencji.  Daje to przedmiotowym organizacjom możliwość wzięcia udziału we wskazywania faktycznych potrzeb pacjentów, których reprezentują, a także w kształtowaniu sposobu i zakresu leczenia objętego refundacją.   Niemniej analizując proponowaną zmianę należy stwierdzić, że nie jest jasne w jakim charakterze organizacje pacjenckie miałyby uczestniczyć w negocjacjach cenowych dla konkretnych leków. Udział w ustalaniu ceny leku wiąże się niejednokrotnie z nieograniczonym dostępem do akt postepowania, co stanowi zagrożenie dla tajemnicy refundacyjnej, m.in. w zakresie informacji technologicznych posiadających wartość gospodarczą, zawieranych instrumentów dzielenia ryzyka oraz innych informacji mających znaczenie dla strategii marketingowej wnioskodawcy. Skutkiem byłaby niechęć przedsiębiorców do wnioskowania o refundację leków w Polsce.  Dodatkowo należy wskazać, że z doświadczenia Ministra Zdrowia jako gospodarza postępowań refundacyjnych, wynika, że przedstawiciele organizacji pacjenckich lub klinicystów, wielokrotnie pełnią jednocześnie rolę pełnomocników wnioskodawców. Ma to w ocenie organu olbrzymi wpływ na poziom obiektywizmu działania takich organizacji. Nie bez wpływu pozostaje również fakt, że dana organizacja pacjencka reprezentuje interesy jednej grupy pacjentów i to jej postulaty uznaje za kluczowe, co znacznie utrudni a nawet uniemożliwi realizację \\fustawowego zadania Ministra Zdrowia  oraz Komisji Ekonomicznej jakim jest równoważenie interesów świadczeniobiorców, przedsiębiorców zajmujących się wytwarzaniem leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych a także możliwościami płatnika publicznego.\\n\\tKoalicja „Na pomoc niesamodzielnym”\\togólne\\tRekomendujemy:  •\\tWprowadzenie możliwości przedkładania opinii społecznych do wstępnych opinii refundacyjnych MZ przez organizacje spełniające określone warunki (np. działalność min. 3 lata, co najmniej  3 kampanie rzecznicze, 2 raporty eksperckie). •\\tStworzenie społecznego panelu doradczego przy AOTMiT lub MZ, w którym reprezentanci Koalicji mogliby zabierać głos w sprawach dotyczących dostępności terapii dla grup szczególnie zależnych od opiekunów.\\tEkspercką rolę organizacji propacjenckich w programach lekowych i opiniach MZ.  Koalicja posiada wieloletnie doświadczenie w ocenie jakości opieki nad osobami niezdolnymi  do samodzielnej egzystencji, przewlekle chorymi czy z niepełnosprawnościami i może realnie wesprzeć tworzenie programów lekowych dla takich grup jak:  •\\tPacjenci z otępieniem, zespołami neurologicznymi, niepełnosprawnością sprzężoną, •\\tOsoby starsze z wielochorobowością, •\\tPacjenci leżący, w opiece paliatywnej i długoterminowej.\\tUwaga niezasadna Minister Zdrowia tworzy opisy programów lekowych po zasięgnięciu opinii konsultanta krajowego lub wojewódzkiego z odpowiedniej dziedziny medycyny, Prezesa AOTMiT, a w uzasadnionych przypadkach medycznego towarzystwa naukowego z danej dziedziny medycyny. Nic nie stoi na przeszkodzie by organizacja propacjencka wnioskowała do towarzystw lub konsultantów o zmianę schematów lub treści programów lekowych. Nic nie stoi również na przeszkodzie by takie postulaty były zgłaszane do Ministra Zdrowia. Jeśli postulaty są słuszne i odpowiadają potrzebom pacjentów są uwzględniane w zmianach programów lekowych.  Nie jest natomiast pożądane by miało to miejsce w ramach procesu administracyjnego w którym organizacje pacjenckie nie są stroną. Organ działając w ramach obowiązujących przepisów zobowiązany jest starannie równoważąc interesy wszystkich grup pacjenckich partycypujących w refundacji, zważając przy tym na ograniczone środki finansowe przeznaczone na refundację. W konsekwencji, niemożliwym jest \\ffinansowanie wszystkich technologii medycznych ubiegających się o refundację, a decyzje są podejmowane z zachowaniem powtarzalności, przejrzystości, w oparciu o dowody naukowe.  Mając powyższe na uwadze, podkreślić należy, że wszelkie działania dotyczące ustalania i zmian w programach lekowych są nakierowane na ochronę zdrowia i życia pacjentów, a Minister Zdrowia działa zawsze mając na względzie interes społeczny i słuszny interes pacjentów. Niemniej, żeby zachować obiektywizm oraz standaryzację postępowań, procedura nie przewiduje udziału organizacji pacjenckich w opiniowaniu opisów programów lekowych w żadnym schorzeniu.\\n\\tKoalicja „Na pomoc niesamodzielnym”\\togólne\\tKoalicja postuluje rozszerzenie definicji pacjenta w ustawie refundacyjnej o „osoby pozostające pod opieką formalną lub nieformalną” – tak, by także głos opiekunów osób niesamodzielnych miał legitymację w systemie.\\tProjekt nowelizacji w obecnym kształcie zbyt silnie koncentruje się na relacji: firma–ministerstwo, marginalizując znaczenie głosu środowiska pacjentów i ich opiekunów.\\tUwaga niezasadna Ustawa o refundacji nie definiuje pojęcia „pacjent” lub jego opiekun. Wykaz leków refundowanych zawiera opcje terapeutyczne dla wszystkich grup pacjentów, nie wykluczając osób pozostających pod opieką prawną osób trzecich, w tym dzieci.  System obejmowania refundacją został oparty na wnioskach składanych przez podmioty odpowiedzialne, ale wydaje się to konieczne z uwagi na fakt, że żaden z pozostałych interesantów systemu refundacji nie ma możliwości prowadzenia obrotu oraz zapewnienia dostępności leków.\\n\\tKoalicja „Na pomoc niesamodzielnym”\\togólne\\tWłączenie organizacji społecznych do dialogu refundacyjnego nie może być symboliczne – konieczne są konkretne mechanizmy udziału, jawne zasady selekcji \\freprezentantów i uregulowanie ich statusu prawnego (nie tylko „obserwatorów”).\\t\\fProjekt nowelizacji w obecnym kształcie zbyt silnie koncentruje się na relacji: firma–ministerstwo, marginalizując znaczenie głosu środowiska pacjentów i ich opiekunów.\\tUwaga niezasadna j.w. w uwagach 111-1115  Uczestnicy procesu refundacyjnego posiadają określone zasoby, możliwości \\flub kwalifikacje do realizowania poszczególnych etapów. Każda decyzja podejmowana jest w oparciu o ściśle określone w ustawie kryteria, przy uwzględnieniu istniejących potrzeb pacjentów, wytycznych klinicznych oraz posiadanych możliwości finansowych płatnika. Organizacje pacjenckie w tym również opiekunowie chorych, mają możliwość wypowiedzenia się i przedstawienia swojego stanowiska w odniesieniu do zakresu i sposobu leczenia w ramach tworzenia programów lekowych, zastosowania leków poza wskazaniami czy potrzeby objęcia refundacją kolejnych, nowych technologii lekowych. Trudno zatem zgodzić się z uwagą, że głos pacjentów jest marginalizowany a organizacje pacjenckie są wyłącznie obserwatorem.  Dodatkowo warto podkreślić, że Rzecznik Praw Pacjentów nie zgłosił uwag dotyczących możliwego wykluczenia udziału pacjentów w procesie tworzenia wykazów leków refundowanych\\n\\tNaczelna Rada Lekarska\\togólne\\tNa koniec Prezydium Naczelnej Rady Lekarskiej wskazuje, że projektowana ustawa – rozwiązuje pewne niedoskonałości rynku prawa farmaceutycznego i ustawy refundacyjnej, jednakże dla środowiska lekarskiego istotne jest, że w obecnym projekcie ustawy nie został zrealizowany postulat dotyczący zdjęcia z lekarzy odpowiedzialności za oznaczenie poziomu odpłatności leku na recepcie i wprowadzenia automatyzmu refundacyjnego.  \\t\\tUwaga zasadna  W projekcie wprowadzono przepisy dotyczące tzw. automatycznej refundacji \\n\\tBusiness Centre Club/Pracodawcy RP\\tOgólne\\tDodanie możliwości zwrotu przez aptekę leku sprowadzonego w trybie importu docelowego\\tObecnie nie ma możliwości by apteka mogła zwrócić lek sprowadzany w trybie importu docelowego w sytuacji, gdy pacjent np. zrezygnuje z zakupu takiego leku. Bardzo często są to leki bardzo drogie, na sprowadzenie których trzeba czekać nawet kilka miesięcy. Ewentualny brak odbioru leku przez pacjenta powoduje olbrzymie obciążenie finansowe dla podmiotu prowadzącego aptekę i nierzadko konieczność utylizacji takiego leku. Możliwość ponownego wprowadzenia takiego leku do obrotu w sytuacji której pacjent nie odebrał tego leku jest nie tylko dużym odciążeniem dla podmiotów aptecznych ale może powodować także szybszy dostęp do leków dla pacjentów, którzy akurat takiego leku potrzebują.\\tUwaga niezasadna Potwierdzone przez Ministra zapotrzebowanie umożliwia sprowadzenie produktu z zagranicy dla konkretnego, zindywidualizowanego pacjenta i jako takie nie może być przedmiotem obrotu.  Jednocześnie podkreślić należy, iż procedura sprowadzenia leków w ramach importu docelowego jest ekstraordynaryjnym przypadkiem i jako taki nie może być kształtowany na tożsamych zasadach ogólnych jak leki dopuszczone do obrotu.\\n\\tPorozumienie Pracodawców Ochrony Zdrowia\\tOgólne\\tDziałając w imieniu lekarzy i świadczeniodawców zrzeszonych w Porozumieniu Pracodawców Ochrony Zdrowia, przekazuję uwagi PPOZ do projektu ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (UD 187, dalej: „Projekt\\\") Jak wskazuje się w uzasadnieniu Projektu, jego głównym celem jest „usprawnienie funkcjonowania systemu refundacyjnego\\\". Choć Projekt zawiera regulacje upraszczające procedurę\\nobjęcia leków refundacją, to w ocenie PPOZ jedynymi beneficjentami Projektu będą koncerny farmaceutyczne. Z perspektywy pacjentów i personelu medycznego Projekt nie tylko nie\\fusprawnia bowiem systemu refundacyjnego, ale dodatkowo go komplikuje, tworząc zeń swoistą pułapkę dla osób ordynujących leki i świadczeniobiorców. Przejawami dalszego komplikowania systemu refundacyjnego są:  wprowadzenie nowej kategorii refundacyjnej w postaci leku stosowanego w chorobach innych niż onkologiczne w ramach udzielania świadczeń z zakresu AOS i leczenia szpitalnego, we wskazaniu określonym stanem klinicznym (nowy art. 6 ust. 1 pkt 2a); opis refundowanych wskazań stanowić będzie załącznik do obwieszczenia refundacyjnego (nowy art. 37 ust. 3a);  wprowadzenie dla leków aptecznych i leków podawanych w programach lekowych możliwości określenia w obwieszczeniu refundacyjnym specjalizacji lekarskiej wymaganej do: (a) naniesienia poziomu odpłatności, (b) określenia okresu terapii oraz (c) liczby opakowań (nowy art. 6 ust. 2b); można przy tym wątpić, czy ograniczenie kompetencji lekarskich w drodze obwieszczenia Ministra Zdrowia jest zgodne z Konstytucją RP, skoro ta nie wymienia w art. 87 obwieszczeń jako źródeł powszechnie obowiązującego prawa;  wprowadzenie receptariusza leków recepturowych finansowanych ze środków publicznych, określającego składy leków recepturowych refundowanych w danej dziedzinie medycyny (nowy art. 6 ust. 12); PPOZ sprzeciwia się tej regulacji, ograniczy ona bowiem prawa pacjentów do refundowanych leków recepturowych \\fdostosowanych do ich indywidualnych potrzeb; niezależnie od innych wątpliwości związanych z tą regulacją, powiązanie refundacji z użyciem leku w danej „dziedzinie medycyny\\\" rodzić też będzie wątpliwość co do możliwości refundacji leku o tym samym składzie, który miałby zostać użyty w innej dziedzinie medycyny; wprowadzenie regulacji, zgodnie z którą każdy wniosek o objęcie leku refundacją będzie musiał zawierać w zakresie wskazań, w których lek ma być refundowany, określenie kodów ICD-10 (a w przyszłości ICD-11), których taka refundacja ma dotyczyć - a co ma docelowo prowadzić do powiązania refundacji z postawieniem konkretnego rozpoznania; PPOZ wskazuje, że w wielu przypadkach postawienie takiego rozpoznania nie jest możliwe, objawy pacjentów są bowiem niecharakterystyczne; z kolei konieczność weryfikacji kodów ICD-10 przypisanych do refundacji konkretnego leku jeszcze bardziej skomplikuje proces ich ordynacji. PPOZ od lat stoi na stanowisku, że polski system refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego i wyrobów medycznych powinien ulec radykalnemu uproszczeniu. W szczególności, system ten nie powinien rodzić u pacjentów, lekarzy i pozostałego personelu medycznego wątpliwości co do przysługujących im uprawnień. Opiniowany Projekt nie\\ntylko jednak nie stanowi kroku w tym kierunku - ale system refundacji istotnie komplikuje. \\fPowyższe powoduje, że PPOZ ocenia całość projektu jednoznacznie negatywnie.\\t\\tUwaga niezasadna Zgłoszona uwaga ogólna wydaje się wskazywać na brak zrozumienia dla całości regulacji systemu refundacyjnego. Zaprojektowane zmiany stanowią wspólna korzyść, dla wszystkich uczestników systemu refundacyjnego:  -          projekt zawiera zmiany w kierunku bardziej elastycznego, przejrzystego i przyjaznego systemu refundacyjnego, który lepiej odpowiada na potrzeby wszystkich uczestników systemu refundacyjnego. -          projektowane zmiany, przyspieszą proces refundacji – mniej biurokracji, prostsze procedury, odciążenie świadczeniodawców i administracji.   -          projekt usuwa wątpliwości interpretacyjne co do obecnych przepisów \\f-          projekt jest odpowiedzią na wnioski kierowane do Ministra Zdrowia od przedsiębiorców obecnych na rynku farmaceutycznym, świadczeniobiorców i innych grup społecznych, na których funkcjonowanie wpływają przepisy ustawy refundacyjnej. Projekt zawiera wiele propozycji deregulacyjnych. Zmiany, które bezpośrednio dotyczą firm farmaceutycznych będą miały bezpośredni wpływ na szybszy dostęp pacjentów do nowych terapii. \\n\\tFederacja Przedsiębiorców Polskich\\tOgólne\\tOdpowiadając na pismo z 21 maja 2025 r. (znak: PLR.0210.2.2024.ŁK.24), przekazujące do konsultacji publicznych projekt ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw (UD187), chciałbym serdecznie podziękować za zaproponowanie w projekcie szeregu postulowanych przez Federację Przedsiębiorców Polskich zmian dotyczących:  prowadzenia postępowań o objęcie refundacją leków takich jak m.in. usunięcie „warunkowych” Rekomendacji Prezesa AOTMiT, zmiany sposobu ustalania deklaracji dostaw, czy możliwość złożenia kolejnej oferty cenowej po zakończeniu negocjacji z Komisją Ekonomiczną;  usunięcia wymogu wprowadzania leku do 10 hurtowni farmaceutycznych.  Niemniej, dalej w miejscu pozostają postulaty Federacji dotyczące:  usunięcia wprowadzonej przez tzw. DNUR osobistej odpowiedzialności karnej osób podpisujących wnioski refundacyjne - zastąpienie odpowiedzialności karnej odpowiedzialnością administracyjną podmiotów odpowiedzialnych wpisywałoby się w mojej ocenie w \\fprezentowaną przez Pana Ministra koncepcję deregulacji;  umożliwienie wpływu wnioskodawcy na treść programu lekowego, w przypadku, gdy Minister Zdrowia proponuje zmiany wpływające na cenę efektywną leku w trakcie trwania decyzji administracyjnej;  wzmacniania rentowności hurtowni farmaceutycznych i aptek. \\t                                       \\t\\fUwaga częściowo zasadna  Odnosząc się do propozycji należy wskazać, iż rentowność aptek jest zwiększona chociażby przez lepszą wycenę leków recepturowych. Do tego nowelizacja z 1 listopada 2023 r. wprowadziła możliwość zwrotu leków wycofanych z refundacji jak również zmieniony algorytm wyliczania ceny detalicznej.  W zakresie rentowności hurtowni należy wskazać, iż wzrasta minimalna marża hurtowa z 50 gr na 80 gr. W ostatniej niedawnej zmianie była zmiana % z 5% na 6%. W zakresie zmiany programów lekowych Wnioskodawca ma możliwość złożenia z odpowiednim uzasadnieniem wniosku z art. 155 kpa w zakresie zmiany instrumentu dzielenia ryzyka. Taka praktyka ma miejsce od momentu wejścia ww. nowelizacji.  Jednak ma ona zasadność, gdy mowa o wzroście populacji, nie można uwzględniać tu sytuacji, gdzie MAH będzie chciał zwiększać cenę ze względu na wejście alternatywnej terapii, która będzie konkurować z nową terapią.  Uwaga niezasadna w zakresie usunięcia odpowiedzialności karnej  \\fUsunięcie odpowiedzialności karnej spowoduje, że składane oświadczenie będzie o osłabionej sankcji. Rodzaj odpowiedzialności administracyjnej jest mniej efektywny i wiarygodny względem odpowiedzialności karnej. Jego zastosowanie spowoduje obniżenie rangi odpowiedzialności za przedkładane informacje. Organ wprowadzając art. 24 ust. 6aa dążył do zapewnienia rzetelności i prawdziwości przedkładanych informacji i danych zawartych we wniosku. Przepis dotyczący składania oświadczenia pod rygorem odpowiedzialności karnej funkcjonuje również w innych przepisach np. w Prawie energetycznym (art. 11 zn ust. 3 pkt 2)\\n\\tFundacja StwardnienieRozsiane.Info\\tOgólne w zakresie czwartej kategorii\\tw naszej ocenie konieczne jest:  stworzenie sieci ośrodków o zróżnicowanym poziomie referencyjności;  zapewnienie możliwości płynnego przejścia z czwartej kategorii do programu lekowego, gdy wymaga tego sytuacja medyczna;  uelastycznienie zasad wydawania leków w aptekach ogólnodostępnych.   Uwzględnienie tych postulatów pozwoli na skuteczne połączenie celu, jakim jest zwiększenie dostępności terapii, z utrzymaniem wysokiego standardu leczenia.\\t1. Wdrożenie czwartej kategorii powinno bazować na doświadczeniu placówek już prowadzących leczenie danym produktem leczniczym Na etapie początkowego wdrażania czwartej kategorii dostępności – zanim powstanie sieć ośrodków referencyjnych – wskazane byłoby, aby leczenie prowadziły przede wszystkim te placówki, które mają już doświadczenie w stosowaniu danego produktu leczniczego w ramach istniejących modeli finansowania. Np. w obszarze stwardnienia rozsianego funkcjonuje obecnie ponad 130 ośrodków, które realizują takie terapie. Oparcie się na tych placówkach pozwoliłoby zachować wysoką jakość opieki i umożliwiłoby stopniowe poszerzanie dostępu do leczenia.  \\f2. Konieczność zapewnienia możliwości płynnego przejścia między czwartą kategorią a programem lekowym  Wnosimy o zagwarantowanie pacjentom możliwości przejścia z leczenia realizowanego w ramach czwartej kategorii dostępności do programu lekowego w przypadkach uzasadnionych klinicznie – przede wszystkim w sytuacji braku skuteczności terapii czy wystąpienia działań niepożądanych.  W takich przypadkach pacjent powinien mieć możliwość włączenia do programu lekowego bez konieczności ponownego spełniania pełnych kryteriów kwalifikacyjnych. Decyzja powinna opierać się na ocenie lekarza prowadzącego i/lub lekarza z ośrodka referencyjnego, a nie na warunkach przewidzianych wyłącznie dla osób rozpoczynających leczenie po raz pierwszy.  Brak takiego rozwiązania mógłby prowadzić do przerwania lub opóźnienia leczenia, co wiązałoby się z ryzykiem pogorszenia stanu zdrowia pacjenta.  3. Dostępność tej samej cząsteczki w obu mechanizmach refundacyjnych  W ustawie należy zagwarantować, że dana substancja czynna może być refundowana zarówno w ramach programu lekowego, jak i w czwartej kategorii. Takie rozwiązanie daje elastyczność organizacyjną, pozwala lepiej dostosować ścieżkę leczenia do aktualnej sytuacji pacjenta, a także umożliwia płynne przekazywanie opieki między placówkami różnego typu.  Przykładowo, rozpoczęcie terapii w ośrodku wysokospecjalistycznym może \\fbyć zasadne w początkowej fazie leczenia, natomiast kontynuacja w AOS, w sytuacji stabilizacji klinicznej, może być korzystna z punktu widzenia organizacyjnego i logistycznego, pod warunkiem zachowania dostępności tej samej terapii.  4. Wydawanie leków w aptece ogólnodostępnej – potrzeba elastyczności i decyzji indywidualnej  Rozwiązanie zakładające wydawanie leków stosowanych w ramach czwartej kategorii w aptekach ogólnodostępnych należy ocenić co do zasady pozytywnie. Może ono zwiększyć dostępność leczenia i uprościć jego organizację. Konieczne jest jednak uwzględnienie sytuacji, w których sztywne zasady wydawania leków, np. wyłącznie na okres jednego miesiąca, stanowiłyby utrudnienie dla pacjentów. W praktyce osoby z chorobami przewlekłymi nie zawsze są w stanie regularnie odbierać lek w comiesięcznych odstępach – ze względu na ograniczoną mobilność, stan zdrowia, obowiązki zawodowe lub wyjazdy. Dlatego ważne jest, aby lekarz prowadzący miał możliwość decydowania o sposobie i terminie realizacji recepty, zgodnie z indywidualną sytuacją pacjenta. Należy również unikać sytuacji, w której odbiór leku byłby możliwy jedynie w ściśle ograniczonym przedziale czasowym (np. tylko pomiędzy 1. a 10. dniem miesiąca), jak również sytuacji, w której odbiór leków byłby możliwy tylko przez pacjenta (brak możliwości odbioru leku przez inną, upoważnioną osobę).  \\fSztywne ograniczenia w tym zakresie mogą prowadzić do przerw w stosowaniu leków, co w przypadku terapii w chorobach przewlekłych ma bezpośredni wpływ na ich skuteczność. Uelastycznienie zasad wydawania leków w aptece (tam, gdzie jest to uzasadnione) zwiększy bezpieczeństwo i stabilność leczenia.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tOgólne Model Flex Care w ambulatoriach\\tZmiany w tym zakresie wymagają zmian w zarządzeniu Prezesa NFZ ws. programów lekowych, w zakresie określenia zasad zakupu leków dla danego ośrodka referencyjnego oraz wyodrębnienia nowego świadczenia w trybie ambulatoryjnym, wymagań dla ambulatoriów, które miałyby to świadczenie realizować oraz procesu zawarcia stosownych umów z ambulatoriami. Koniecznym byłoby również dookreślenie jakie leki miałyby wejść w taki model dystrybucji oraz jak wyglądałaby procedura ich włączenia w tej model, przy uwzględnieniu tu aktywnej roli wnioskodawcy refundacyjnego.  W kontekście finansowania wydaje się, że niezbędne byłoby także dostosowanie zasad rozliczania ryczałtów za diagnostykę i monitorowanie leczenia w ramach programów lekowych (w przypadku umożliwienia prowadzenia monitorowania leczenia również przez ambulatoria).   Z perspektywy ustawowej zasadnym byłoby wprowadzenie takich modyfikacji, aby SMPT był źródłem informacji dla lekarza m.in. w kontekście ambulatoriów. Jednocześnie koniecznym byłoby opracowanie systemu informatycznego (w \\framach Platformy P1) do e-zleceń oraz komunikacji na linii ośrodek referencyjny – ambulatoria, ewentualnie hurtownie.\\t\\f1)\\tRelacja z NFZ Relację z NFZ miałby zarówno szpital, jak i ambulatorium w ramach umowy na realizację programu lekowego (co jest uzasadnione m.in. tym, że zarządzenie Prezesa NFZ w zakresie programów lekowych już teraz zawiera świadczenia udzielane w ramach ambulatorium oraz że jest to związane z realizacją właśnie tego świadczenia gwarantowanego). Zasadnym byłoby, aby ambulatoriami w tym zakresie były przede wszystkim ambulatoria przy szpitalach powiatowych. Takie rozwiązanie nie tylko zapewnia najwyższy poziom zabezpieczenia pacjentów oraz dobre skomunikowanie, ale także gwarantuje wysokie standardy dystrybucyjne (dzięki istniejących w nich aptekach szpitalnych albo działach farmacji szpitalnej) oraz powoduje wykorzystanie potencjału tych placówek . W ramach umowy każdy ze świadczeniodawców miałby wskazany odpowiedni zakres świadczeń (określony w ramach zarządzenia Prezesa NFZ oraz w umowie z NFZ). Oba podmioty raportowałyby do NFZ przez SMPT/SMPL. Proponowany zakres świadczeń: \\f1.\\tOśrodek referencyjny (szpital) – kwalifikacja pacjenta do programu lekowego, jego początkowe leczenie i diagnostyka oraz diagnostyka i leczenie w przypadku „nawrotu” objawów (np. na skutek pogorszenia zdrowia), ewentualnie ocena bilansowa (raz w roku).  2.\\tAmbulatorium – zakres opieki w ambulatorium może obejmować: ●\\twydanie i ewentualne podanie leku pacjentowi, w ramach kontynuowania opieki (dotyczyłoby to leków, które mogą być wydane w warunkach pozaszpitalnych oraz pacjentów, wobec których lekarz prowadzący ze szpitala uzna, że nie jest to obarczone ryzykiem wystąpienia działań niepożądanych po podaniu, nieprawidłowego prowadzenia terapii czy brakiem współpracy pacjenta z lekarzem prowadzącym), ●\\t(opcjonalnie) wykonanie badań diagnostycznych zgodnych z zasadami monitorowania pacjenta w ramach opisu programu lekowego czy ocena bilansowa.  Niezwykle ważne w tym zakresie byłoby odpowiednie (proporcjonalne do zakresu świadczeń) określenie wymagań dla świadczeniodawców dla świadczeń typu wydanie leku w ramach kontynuacji leczenia. Bez tej zmiany (złagodzenia tych wymagań względem szpitali) wiele ambulatoriów może mieć trudności ze spełnieniem obecnych wymagań określonych w zarządzeniu Prezesa NFZ. Ośrodek referencyjny wystawiałby e-zlecenia (do ustalenia nazwa, inna propozycja to e-skierowanie) na wydanie leku do określonego ambulatorium wskazanego przez lekarza prowadzącego \\fi uwzględniającego wybór pacjenta (z opcją zmiany e-zlecenia przez ośrodek referencyjny). W tym zakresie lekarze prowadzący pacjenta w ośrodku referencyjnym powinni mieć listę zakontraktowanych ambulatoriów w systemie informatycznym (np. w ramach SMPL ). E-zlecenie byłoby widoczne dla NFZ oraz dla ambulatoriów.  NFZ rozliczałby świadczenia zdrowotne z ośrodkiem referencyjnym oraz ambulatorium, oraz świadczenia lekowe (rzeczowe) tylko ze szpitalem (po podaniu leku w szpitalu oraz w ambulatorium).\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tOgólne Model Flex Care w ambulatoriach\\tZmiany w tym zakresie wymagają zmian w Prawie farmaceutycznym w zakresie działów dystrybucji, które zaproponowano w projekcie nowelizacji, jednak z rozszerzeniem tego katalogu nie tylko na leki z nowej kategorii dostępności refundacyjnej, ale także na leki z programów lekowych.  Jednocześnie, w Prawie farmaceutycznym (np. w rozdziale poświęconym aptekom, w tym aptekom szpitalnym) należałoby dodać rozwiązanie wskazujące, że hurtownia farmaceutyczna może dostarczyć sprzedaż produkt leczniczy z kategorii dostępności określonej w art. 6 ust. 1 pkt 2 i 2a ustawy refundacyjnej do podmiotu leczniczego (jego apteki szpitalnej lub działu farmacji szpitalnej) realizującego świadczenia, o których mowa w art. 15 ust. 2 pkt 15 i 15a ustawy o świadczeniach, a dostarczyć ww. lek do innego podmiotu leczniczego (jego apteki szpitalnej, działu farmacji szpitalnej lub działu dystrybucji), który ma wydać i \\fewentualnie podać lek w ramach ww. świadczeń.  W ramach zarządzenia Prezesa NFZ należałoby wskazać na obowiązki zarówno ośrodka referencyjnego oraz ambulatorium dotyczące informowania o wydaniu / podaniu leku pacjentowi.\\t\\f2)\\tDystrybucja leku Relację umowną z hurtownią farmaceutyczną nadal miałby jedynie ośrodek referencyjny (szpital). To on nabywałby leki w trybie wynikającym z Prawa zamówień publicznych. W konsekwencji to szpital byłby ich właścicielem (faktura byłaby wydawana na szpital) i podmiotem rozliczającym nabycie leków z NFZ. Podmiot leczniczy prowadzący ambulatorium w tym modelu byłby jedynie faktycznym posiadaczem leku (co nie jest czymś niespotkanym w łańcuchu dystrybucji, gdyż w dystrybucji hurtowej funkcjonują modele Logistic Service Providera, który jako hurtownia farmaceutyczna przechowuje leki należące formalnie do innej hurtowni). W zależności od założeń, do dystrybucji w ramach Flex Care mogłyby zostać włączone podmioty lecznicze posiadające aptekę szpitalną lub dział farmacji szpitalnej (czyli przede wszystkim ambulatoria przy szpitalach), \\falternatywnie także ambulatoria posiadające dział dystrybucji leków, który został zaproponowany w projekcie nowelizacji w odniesieniu do tzw. czwartej kategorii dostępności. Ten model zakłada, że ambulatorium odpowiednio wcześnie zgłasza ośrodkowi referencyjnemu, który prowadzi danego pacjenta w ramach programu lekowego o potrzebie wydania i ewentualnie podania leku. W związku z tym szpital składa do hurtowni zamówienie nabycia leku na określoną ilość opakowań i wskazuje, że lek ma być dostarczony nie do apteki szpitalnej szpitala, lecz do podmiotu leczniczego prowadzącego ambulatorium (co wymaga zmian w Prawie farmaceutycznym). Omawiany model nie sprawia trudności z perspektywy realizacji różnych obowiązków dotyczących leków. Obowiązki w zakresie serializacji (weryfikacji autentyczności leków) byłyby realizowane przez a) aptekę szpitalną lub dział farmacji szpitalnej ambulatorium albo b) przez hurtownie farmaceutyczną w przypadku ambulatorium z działem dystrybucji (zgodnie z propozycją z nowelizacji). W zakresie raportowania do ZSMOPL raportowanie dokonywałoby się zarazem przez:  a)\\taptekę szpitalną lub dział farmacji szpitalnej szpitala – w zakresie raportowania transakcji nabycia leku, oraz b)\\tprzez aptekę szpitalną, dział farmacji aptecznej lub dział dystrybucji leków – w \\fzakresie raportowania transakcji przyjęcia leku na stan.  Taki model w pełni odpowiada logice systemu dystrybucji wynikającej z Prawa farmaceutycznego.  Z uwagi na fakt, że ambulatorium byłoby jedynie posiadaczem leku, a nie jego właścicielem, w tym modelu nie występują problemy dotyczące rozszerzenia katalogu podmiotów znających cenę efektywną leku, a więc w konsekwencji także treść RSS. Jest to również o tyle korzystne, że nie wymaga od ambulatoriów ponoszenia kosztów organizacyjnych, i w konsekwencji finansowych, dotyczących obsługi postępowań przetargowych. Jest to również korzystne dla budżetu płatnika, gdyż efekt skali w szpitalu zapewnia większe oszczędności niż małe przetargi realizowane przez poszczególne ambulatoria. Wreszcie jest to korzystne dla hurtowni farmaceutycznych, w tym tzw. producenckich, które w sferze organizacyjnej i przetargowej mają do obsłużenia mniej przetargów. Jednocześnie pojawiają się nowe obowiązki dla ośrodków referencyjnych wynikających ze współpracy z ambulatoriami.  Podsumowując, takie rozwiązanie gwarantuje stosowanie zasad dotyczących cen i marż z ustawy refundacyjnej (art. 9), zapewnia konkurencyjność (z uwagi na stosowanie przetargów), bezpieczeństwo wnioskodawców z zakresie informacji o cenach efektywnych (znajomość treści RSS przez taki zakres podmiotów jak \\faktualnie), relatywną prostotę procesu (dostawy bezpośrednie do wielu podmiotów, ale relacje umowne tylko z niektórymi), poszanowanie zasad dystrybucji i raportowania wynikających z Prawa farmaceutycznego.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tOgólne Model Flex Care w ambulatoriach\\tBrak konieczności zmian ustawowych. Zmiany dostosowujące nowy model byłoby konieczne na poziomie zarządzeń Prezesa NFZ, w tym np. wprowadzenie braku limitów do wysokości kontraktu na realizację programu lekowego.\\tFinansowanie Jak wskazano w pkt 1), każdy ze świadczeniodawców otrzymałby finansowanie za realizowane przez siebie świadczenia na podstawie umów zawartych z NFZ. Jednocześnie tylko ośrodek referencyjny otrzymywałby z NFZ finansowanie kosztu leków pacjentów „własnych” oraz obsługiwanych w ambulatoriach (działających na zasadzie e-zlecenia). W ramach programów nadal obowiązywałyby istniejące grupy limitowe, a zakup leków jedynie pokrywałby ośrodek referencyjny zgodnie z ceną z przetargu.  W tym zakresie do rozważenia jest wyjście w zakresie takiego modelu realizacji programów lekowych z dotychczasowych limitów kontraktowania, i wprowadzenie modelu niepowiązanego żadnym limitem (tak jak w przypadku pediatrycznych programów lekowych).  Wprowadzenie tego modelu pozwala na realizacje programów w ramach obecnych zasad ich finansowania i może być „bezkosztowe” dla NFZ z punktu widzenia kosztów na jednego pacjenta.  W celu wprowadzenia tych rozwiązań wymagana jednak będzie modyfikacja ryczałtów diagnostycznych oraz wprowadzenie możliwości wdrożenia nowych zasad komunikacji pomiędzy \\fośrodkami (w tym telekonsultacji czy telewizyt). Kwoty wynikające z konieczności zapłaty za świadczenia udzielane przez ambulatoria, mogłyby być pokrywane z oszczędności jakie będą wynikać z ograniczenia m.in. liczby hospitalizacji.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tOgólne Model Flex Care w ambulatoriach\\tW tym zakresie należałoby wprowadzić mechanizmy (w ramach zarządzenia Prezesa NFZ lub bezpośrednio w umowie na realizację świadczenia) informowania pacjenta przez ośrodek referencyjny, jakie ambulatoria znajdują się w okolicy miejsca zamieszkania pacjenta.\\t4)\\tPerspektywa pacjenta: Pacjent, zgodnie z art. 6 ust. 8 ustaw refundacyjnej otrzymuje lek bezpłatnie. Jednocześnie pacjent miałby dostęp do ambulatoriów, które mają podpisane stosowne umowny z NFZ, które znajdowałyby się bliżej pacjenta niż ośrodek referencyjny (szpital).\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tModel Flex Care w aptekach ogólnodostępnych\\tZ perspektywy ustawy o świadczeniach, apteka powinna zostać zdefiniowana jako możliwy świadczeniodawca (art. 5 pkt 41).  Zmiany w tym zakresie wymagają zmian w zarządzeniu Prezesa NFZ ws. programów lekowych, w zakresie wyodrębnienia nowego świadczenia w zakresie wydania leku z apteki.  Koniecznym byłoby ustalenie kryteriów (w zarządzeniu Prezesa NFZ) na podstawie, których miałyby być wybrane odpowiednie apteki. Zakładamy, że punktem odniesienia powinien być powiat. Ma to również istotne znaczenie nie tylko z perspektywy relacji z NFZ, ale także dystrybucji. Oczywiście wiele będzie zależało od rodzaju programu lekowego, w szczególności od jego populacji (zwłaszcza jeżeli wynosi więcej niż 2-3 tys. osób).\\t1)\\tRelacja z NFZ Relację z NFZ miałby zarówno szpital, jak i apteka ogólnodostępna (w ramach odrębnej umowy na realizację programu lekowego albo w ramach odrębnego świadczenia np. świadczenia opieki farmaceutycznej).  W ramach umowy każdy ze świadczeniodawców miałby wskazany odpowiedni zakres świadczeń. Oba podmioty raportowałyby do NFZ przez SMPT/SMPL. NFZ rozliczałby świadczenia lekowe (rzeczowe) tylko ze szpitalem (po podaniu leku w szpitalu oraz po wydaniu leku w aptece). Proponowany zakres świadczeń: 1.\\tOśrodek referencyjny (szpital) – pełne prowadzenie pacjenta w programie lekowy, w tym diagnostyka i terapia.  2.\\tApteka – wydanie leku pacjentowi, w ramach 1 miesięcznych limitów, na podstawie specjalnych recept (ewentualnie e-zleceń) wydawanych przez lekarza prowadzącego ze szpitala (dotyczyłoby to leków, które mogą być \\fwydane w warunkach pozaszpitalnych oraz pacjentów, wobec których lekarz prowadzący ze szpitala uzna, że nie jest to obarczone ryzykiem wystąpienia działań niepożądanych po podaniu, nieprawidłowego prowadzenia terapii czy brakiem współpracy pacjenta z lekarzem prowadzącym, jednocześnie uznając że pacjent lub jego opiekun jest dobrze wyszkolony i wyedukowany z podawania leku). Oznacza to, że w proponowanym modelu apteka nie dostawałaby wynagrodzenia w postaci marży od ceny produktu, ale wynagrodzenie za ww. świadczenie. W przypadku przyjęcia, że wydawanie leków miałoby mieć miejsce w świadczeniu gwarantowanym innym niż świadczenia w programie lekowym, koniecznym byłoby wprowadzenie odpowiednich odrębnych zasad finansowania leków (w tym grup limitowych) dla obrotu aptecznego co wiązało by się z wprowadzeniem rozwiązań zbliżonych do nowej kategorii dostępności jaką są leki specjalistyczne.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tModel Flex Care w aptekach ogólnodostępnych\\tZmiany w tym zakresie wymagają zmian w Prawie farmaceutycznym (np. w rozdziale poświęconym aptekom, w tym aptekom szpitalnym) poprzez dodanie rozwiązania wskazującego, że hurtownia farmaceutyczna może dostarczy sprzedaż produkt leczniczy z kategorii dostępności określonej w art. 6 ust. 1 pkt 2 i 2a ustawy refundacyjnej do podmiotu leczniczego (jego apteki szpitalnej lub działu farmacji szpitalnej) realizującego świadczenia, o których mowa w art. 15 ust. 2 pkt 15 i 15a ustawy o świadczeniach, a dostarczyć ww. \\flek do apteki ogólnodostępnej, która ma wydać lek w ramach ww. świadczeń.  Inne zmiany dotyczące Prawa farmaceutycznego (lub zapowiadanej ustawy o receptach) miałby na celu wdrożenie nowego typu recepty (alternatywnie e-zlecenia), który w ww. zakresie pozwalałby na realizację recept w aptekach. Jeżeli zgodnie z założeniami Ministerstwa Zdrowia dla jednego pacjenta mogłaby w tym samym czasie istnieć tylko jedna recepta to należałoby zabezpieczyć sytuację (ustawowo lub na poziomie umowy z ośrodkiem referencyjnym), która zagwarantowałaby, że recepta wystawiona przez lekarza, który już nie pracuje na pewno zostanie cofnięta.   Z perspektywy zakresu działań apteki zasadnym byłoby także dodanie odpowiedniej czynności do zakresu działań aptek (art. 87 ust. 2 Prawa farmaceutycznego), w postaci wydania leku w ramach programu lekowego.  W ramach zarządzenia Prezesa NFZ należałoby wskazać na obowiązki apteki dotyczące informowania szpitala o wydaniu leku pacjentowi oraz zasad otrzymywania leków nabytych uprzednio przez szpital.\\t\\f2)\\tDystrybucja leku Relację umowną z hurtownią farmaceutyczną nadal miałby jedynie szpital, a apteka działałby na podstawie specjalnej e-recepty (albo e-zlecenia). To ośrodek referencyjny nabywałby leki w trybie wynikającym z Prawa zamówień publicznych. W konsekwencji to szpital byłby ich właścicielem (faktura byłaby wydawana na szpital) i podmiotem rozliczającym nabycie leków z NFZ. Apteka ogólnodostępna w tym modelu byłaby jedynie faktycznym posiadaczem leku (co nie jest czymś niespotkanym w \\fłańcuchu dystrybucji, gdyż w dystrybucji hurtowej funkcjonują modele Logistic Service Providera, który jako hurtownia farmaceutyczna przechowuje leki należące formalnie do innej hurtowni). Tak jak wskazano powyżej, apteka nie otrzymywałaby marży od ceny produktu (bo nie jest jej właścicielem), ale wynagrodzenie za świadczenie. Ten model zakłada, że apteka ogólnodostępna odpowiednio wcześnie zgłasza szpitalowi, który prowadzi danego pacjenta w ramach programu lekowego o potrzebie wydania leku (po wcześniejszym zgłoszeniu się pacjenta do apteki ze wskazaniem na kiedy potrzebuje lek).  W związku z tym szpital składa do hurtowni zamówienie nabycia leku na określoną ilość opakowań i wskazuje, że lek ma być dostarczony nie do apteki szpitalnej szpitala, lecz do apteki ogólnodostępnej  (co wymaga niewielkich zmian w Prawie farmaceutycznym).  Taki model nie sprawia trudności z perspektywy realizacji różnych obowiązków dotyczących leków. Obowiązki w zakresie serializacji (weryfikacji autentyczności leków) byłby realizowane przez aptekę ogólnodostępną. W zakresie raportowania do ZSMOPL raportowanie dokonywałoby się zarazem przez a) aptekę szpitalną lub dział farmacji szpitalnej szpitala – w zakresie raportowania transakcji nabycia leku oraz b) przez aptekę ogólnodostępną – w zakresie raportowania transakcji przyjęcia leku na \\fstan. Taki model w pełni odpowiada logice systemu dystrybucji wynikającej z Prawa farmaceutycznego.  Z uwagi na fakt, że apteka ogólnodostępna byłaby jedynie posiadaczem leku, a nie jego właścicielem, w tym modelu nie występują problemy dotyczące rozszerzenia katalogu podmiotów znających cenę efektywną leku, a więc w konsekwencji także treść RSS. Jest to również o tyle korzystne, że nie wymaga od aptek ogólnodostępnych ponoszenia kosztów organizacyjnych, i w konsekwencji finansowych, dotyczących obsługi postępowań przetargowych. Jest to również korzystne dla aptek, bo – inaczej niż w modelu marżowym – nie ponoszą ryzyka związanego z nabyciem drogiego leku. Jest to również korzystne dla budżetu płatnika, gdyż efekt skali w szpitalu zapewnia większe oszczędności niż małe przetargi realizowane przez poszczególne apteki ogólnodostępne. Wreszcie jest to korzystne dla hurtowni farmaceutycznych, w tym tzw. producenckich, które w sferze organizacyjnej i przetargowej mają do obsłużenia tylko przetargi szpitalne, choć nadal kluczowa jest kwestia dotycząca dostaw leków do aptek.  Podsumowując, takie rozwiązanie gwarantuje stosowanie zasad dotyczących cen i marż z ustawy refundacyjnej (art. 9), zapewnia konkurencyjność (z uwagi na stosowanie przetargów), bezpieczeństwo wnioskodawców z zakresie informacji o cenach efektywnych (znajomość treści RSS przez taki zakres podmiotów jak \\faktualnie), relatywną prostotę procesu (dostawy bezpośrednie do wielu podmiotów, ale relacje umowne tylko z niektórymi), poszanowanie zasad dystrybucji i raportowania wynikających z Prawa farmaceutycznego. Jednocześnie pragniemy wskazać, że to rozwiązanie ma również pewne minusy (obiektywnie oraz w porównaniu z modelem ambulatorium). Jest to przede wszystkim istotne obciążenie hurtowni farmaceutycznych, które będą musiały dostarczać leki nie do kilku szpitali, ale także do wielu aptek (których ilość byłaby zapewne większa niż ambulatoriów) na terenie całego kraju. Oznacza to też konieczność reorganizacji pracy wielu hurtowni oraz zwiększenie obowiązków związanych z transportem.  Nadal do ustalenia byłaby też kwestia odpowiedzialności (przejęcia ryzyka) za utratę / zniszczenie leku (choć akurat ta kwestia ma zastosowanie także do modelu ambulatorium). W tym zakresie możemy kierunkowo wskazać, że odpowiedzialność za błędne wydanie leku spoczywałaby na aptece (której właściwie jedynym obowiązkiem w ramach realizacji świadczenia jest właśnie prawidłowe wydanie leku). Apteka w tym zakresie odpowiadałaby na zasadach funkcjonujących już w systemie (zwrot wynagrodzenia plus kara umowna).\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tModel Flex Care w aptekach ogólnodostępnych\\tBrak konieczności zmian ustawowych. Zmiany dostosowujące nowy model byłoby konieczne na poziomie zarządzeń Prezesa NFZ.\\tFinansowanie Jak wskazano w pkt 1), każdy ze świadczeniodawców otrzymałby finansowanie za realizowane przez siebie świadczenia. Wprowadzenie tego modelu pozwala na realizacje programów \\fw ramach obecnych zasad ich finansowania i może być „bezkosztowe” dla NFZ z punktu widzenia kosztów na jednego pacjenta. W celu wprowadzenia tych rozwiązań wymagania jednak będzie modyfikacja ryczałtów diagnostycznych oraz wprowadzenie możliwości wdrożenia nowych zasad komunikacji pomiędzy aptekami ogólnodostępnymi (w tym telekonsultacji) a ośrodkami. Kwoty wynikające z konieczności zapłaty za świadczenia udzielane przez ambulatoria, mogłyby być pokrywane z oszczędności jakie będą wynikać z ograniczenia min liczby hospitalizacji.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tModel Flex Care w aptekach ogólnodostępnych\\tW tym zakresie należałoby wprowadzić mechanizmy (w ramach zarządzenia Prezesa NFZ lub bezpośrednio w umowie na realizację świadczenia) informowania pacjenta przez ośrodek referencyjny, jakie apteki ogólnodostępne, które mają zawartą umowę z NFZ znajdują się w okolicy miejsca zamieszkania pacjenta.\\t4)\\tPerspektywa pacjenta: Pacjent, zgodnie z art. 6 ust. 8 ustaw refundacyjnej otrzymuje lek bezpłatnie. Jednocześnie pacjent miałby wydawane leki w aptekach ogólnodostępnych, które mają podpisane stosowne umowny z NFZ, które znajdowałyby się bliżej pacjenta niż szpital. Z perspektywy pacjenta model apteczny może wiązać się z większymi obawami / ryzykami niż model ambulatoryjny w zakresie braku kontaktu z lekarzem, czy pielęgniarką oraz konieczne jest określenie zasad refundacji kosztu leków w przypadku sytuacji np. utraty leku.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tNaczelna Izba Aptekarska\\t4 kategoria refundacyjna cz. 1\\tZMIANY DOTYCZĄCE NOWEJ KATEGORII DOSTĘPNOŚCI, pn.: „lek stosowany w chorobach innych niż onkologiczne w ramach udzielania świadczeń, o których mowa w art. 15 ust. 2 pkt 2 i 3 ustawy o świadczeniach, we wskazaniu określonym stanem klinicznym”  \\fProponuje się nową definicję wprowadzanej tzw. czwartej kategorii dostępności.  - w art. 1 pkt 2 lit. a tiret pierwsze (dot. art. 6 ust. 1 pkt 2a) proponuje się tiret pierwsze nadać brzmienie:  „- po pkt 2 dodaje się pkt 2a w brzmieniu: „2a) \\tlek stosowany w chorobach innych niż onkologiczne w ramach udzielania świadczeń,o których mowa w art. 15 ust. 2 pkt 2 i 3 ustawy o świadczeniach, lub w ramach sprawowania opieki farmaceutycznej, o której mowa w art. 4 ust. 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty - we wskazaniu określonym stanem klinicznym (lek w ramach ambulatoryjnej opieki specjalistycznej lub opieki farmaceutycznej),”;   W konsekwencji, proponuje się zmianę w art. 3 i art. 15 ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych.  - w art. 3 pkt 1 dotyczącym art. 5 ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, dodaje się lit. a1 w brzmieniu: „a1) w pkt 41 w lit. e średnik zastępuje się przecinkiem i dodaje się lit. f w brzmieniu: „f) podmiot prowadzący aptekę ogólnodostępną, w której przeprowadzane są szczepienia ochronne, realizowane są programy polityki zdrowotnej, zdrowotne lub pilotażowe lub udzielane są inne świadczenia opieki zdrowotnej, które mogą \\fbyć udzielane w aptece, określone w przepisach wydanych na podstawie art. 86 ust. 8h ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne;”.        - w art. 3 pkt 2 otrzymuje brzmienie: „2) w art. 15: a)\\tw ust. 2 po pkt 15 dodaje się pkt 15a w brzmieniu: „15a) \\tleków stosowanych w chorobach innych niż onkologiczne w ramach udzielania świadczeń w zakresie, o których mowa w pkt 2 i 3, lub sprawowania opieki farmaceutycznej, o której mowa w art. 4 ust. 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty, we wskazaniu określonym stanem klinicznym, określonych w przepisach ustawy o refundacji;”,  b)\\tpo ust. 2a dodaje się ust. 2b w brzmieniu: „2b. \\tŚwiadczenia zdrowotne dotyczące leków stosowanych w chorobach innych niż onkologiczne, o których mowa w ust. 2 pkt 15a, mogą być udzielane także,\\nw całości lub w określonym zakresie, przez farmaceutów w aptece .”    W konsekwencji, konieczne są zmiany w ustawie o zawodzie farmaceuty; proponuje się dodanie nowego przepisu do opiniowanego projektu, jako kolejnego artykułu.  \\f- \\tdodaje się art. X dotyczący ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty (Dz. U. z 2024 r. poz. 676) w brzmieniu:  „Art. X. W ustawie z dnia 10 grudnia 2020 r. o zawodzie farmaceuty (Dz. U. z 2024 r. poz. 676) wprowadza się następujące zmiany: w art. 4: w ust. 1 w pkt 4 na końcu kropkę zastępuje się średnikiem i dodaje się pkt 5 w brzmieniu: „5) przeprowadzaniu szczepień ochronnych oraz wystawianiu recept na produkty immunologiczne niezbędne do przeprowadzenia zalecanych szczepień ochronnych,\\nw rozumieniu przepisów ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (Dz. U. z 2023 r. poz. 1284, z późn. zm.), a także udzielaniu innych świadczeń zdrowotnych w przypadkach określonych w przepisach odrębnych regulujących zasady ich wykonywania.”, w ust. 2 w pkt 5 na końcu kropkę zastępuje się średnikiem i dodaje się pkt 6 w brzmieniu: „6) udzielaniu świadczeń zdrowotnych dotyczących leków stosowanych w chorobach innych niż onkologiczne, dla których ustalona została kategoria refundacyjna, o której mowa w art. 6 ust. 1 pkt 2a ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych.”;  po art. 28 dodaje się art. 28a w brzmieniu: „Art. 28a. 1. Farmaceuta ma prawo wglądu do dokumentacji medycznej pacjenta oraz do uzyskania od podmiotu udzielającego świadczeń zdrowotnych pełnej informacji w rozumieniu przepisów ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2022 r. poz. 1876, 2280 i 2705 oraz z 2023 r. poz. 605) o stanie zdrowia pacjenta, rozpoznaniu, proponowanych metodach diagnostycznych, leczniczych, rehabilitacyjnych, zapobiegawczych i dających się przewidzieć następstwach podejmowanych działań, w zakresie niezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę. 2. Farmaceuta ma prawo dostępu do danych dotyczących pacjenta przetwarzanych w Internetowym Koncie Pacjenta, o którym mowa w art. 2 pkt 19 ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia (Dz.U. z 2023 r. poz. 2465, z późn. zm.), w zakresie niezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę.”.   Konieczne jest unormowanie statusu prawnego apteki ogólnodostępnej jako miejsca udzielania świadczeń zdrowotnych.  W art. 2 dotyczącym zmiany ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne (Dz. U. z 2021 r. poz. 974 i 981) proponuje się następujące zmiany:  - w art. 2 proponuje się dodać po pkt 15 pkt 15a oraz po pkt 20 pkt 20a w brzmieniu:  „15a) w art. 86: ust. 8a otrzymuje brzmienie: „8a. W aptekach ogólnodostępnych spełniających wymagania do prowadzenia opieki farmaceutycznej, określone w przepisach wydanych na podstawie art. 97 ust. 5 i art. 98 ust. 5, poza świadczeniami zdrowotnymi w ramach sprawowania opieki farmaceutycznej, o której mowa w art. 4 ust. 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty, mogą być: przeprowadzane szczepienia ochronne zgodnie z przepisami ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi; realizowane programy polityki zdrowotnej, programy zdrowotne oraz programy pilotażowe, w rozumieniu przepisów ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych; udzielane inne świadczenia opieki zdrowotnej w rozumieniu art. 5 pkt 34 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych (Dz. U. z 2024 r. poz. 146), określone w wykazie, o którym mowa w ust. 8h pkt 1.”, po ust. 8a dodaje się ust. 8b-8h w brzmieniu: \\f„8b. Udzielanie w aptece ogólnodostępnej świadczeń zdrowotnych w ramach sprawowania opieki farmaceutycznej oraz świadczeń zdrowotnych, o których mowa w ust. 8a i ust. 8h, nie stanowi działalności leczniczej w rozumieniu art. 3 ust. 1 i 2 ustawy z dnia 15 kwietnia 2011 r. o działalności leczniczej.   8c. Podmiot prowadzący aptekę udzielający w aptece ogólnodostępnej świadczeń opieki zdrowotnej: określa profil medyczny i zakres świadczeń opieki zdrowotnych wykonywanych w aptece, stosując kody stanowiące części IX i X systemu resortowych kodów identyfikacyjnych, określone w przepisach wydanych na podstawie art. 105 ust. 5 ustawy z dnia 15 kwietnia 2011 r. o działalności leczniczej; przekazuje do właściwego miejscowo wojewódzkiego inspektora farmaceutycznego informację o rozpoczęciu albo zakończeniu udzielania świadczeń opieki zdrowotnej, zawierającą określenie profilu medycznego i zakresu świadczeń opieki zdrowotnej wykonywanych w aptece, niezwłocznie po rozpoczęciu, zmianie zakresu lub zakończeniu udzielania tych świadczeń. 8d. Podmiot prowadzący aptekę udzielający w aptece ogólnodostępnej świadczeń opieki zdrowotnej zobowiązany \\fjest zawrzeć umowę ubezpieczenia odpowiedzialności cywilnej obejmującej szkody będące następstwem udzielania świadczeń zdrowotnych albo niezgodnego z prawem zaniechania udzielania świadczeń zdrowotnych. 8e. Przepis ust. 8d nie narusza przepisów art. 120 ustawy z dnia 26 czerwca 1974 r. - Kodeks pracy. 8f. Obowiązek ubezpieczenia, o którym mowa w ust. 8d, powstaje najpóźniej w dniu poprzedzającym dzień rozpoczęcia udzielania świadczeń opieki zdrowotnej w aptece. 8g. Minister właściwy do spraw instytucji finansowych w porozumieniu\\nz ministrem właściwym do spraw zdrowia, po zasięgnięciu opinii Naczelnej Rady Aptekarskiej, określi, w drodze rozporządzenia, szczegółowy zakres ubezpieczenia obowiązkowego, o którym mowa w ust. 8d, oraz minimalną sumę gwarancyjną, biorąc pod uwagę zakresy świadczeń opieki zdrowotnej udzielanych w aptece. 8h. Minister właściwy do spraw zdrowia może określić, w drodze rozporządzenia: wykaz świadczeń opieki zdrowotnych innych niż świadczenia zdrowotne\\nw ramach sprawowania opieki farmaceutycznej oraz świadczenia zdrowotne, o których mowa w ust. 8a pkt 1 i 2, które mogą być udzielane w aptece ogólnodostępnej; warunki realizacji danego świadczenia opieki zdrowotnej, w tym dotyczące personelu medycznego i \\fwyposażenia w sprzęt i aparaturę medyczną, mając na uwadze konieczność zapewnienia wysokiej jakości świadczeń opieki zdrowotnej oraz właściwego zabezpieczenia tych świadczeń.”;  - „20a) w art. 107 ust. 2 po pkt 5 dodaje się pkt 5a w brzmieniu: „5a) określenie profilu medycznego i zakresu świadczeń opieki zdrowotnych wykonywanych w aptece, z zastosowaniem kodów stanowiących części IX i X systemu resortowych kodów identyfikacyjnych, określonych w przepisach wydanych na podstawie art. 105 ust. 5 ustawy z dnia 15 kwietnia 2011 r. o działalności leczniczej;”. \\t\\fUzasadnienie Ad 1. Naczelna Izba Aptekarska proponuje, aby w definicji nowej kategorii dostępności refundacyjnej, tzw. „czwartej kategorii”, uwzględnić również możliwość stosowania leków\\nw ramach opieki farmaceutycznej. Proponuję się nową nazwę tej kategorii dostępności: „lek w ramach \\fambulatoryjnej opieki specjalistycznej lub opieki farmaceutycznej”. Propozycja ta ma pełne uzasadnienie zarówno w świetle argumentacji przedstawionej przez Ministra Zdrowia, jak i z punktu widzenia struktury oraz funkcjonowania systemu ochrony zdrowia. Rozszerzenie to pozwala bowiem na realizację wszystkich celów, jakie postawiono przed nową kategorią dostępności, a w wielu przypadkach umożliwia ich sprawniejszą, bezpieczniejszą i bardziej dostępną realizację niż w przypadku ograniczenia wyłącznie do podmiotów leczniczych realizujących świadczenia z zakresu ambulatoryjnej opieki specjalistycznej (AOS). Zgodnie z art. 4 ust. 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty, opieka farmaceutyczna jest świadczeniem zdrowotnym w rozumieniu art. 5 pkt 40 ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych. Stanowi ona dokumentowany proces, prowadzony przez farmaceutę w ścisłej współpracy z lekarzem prowadzącym leczenie, a w razie potrzeby także z innymi przedstawicielami zawodów medycznych. W ramach opieki farmaceutycznej farmaceuta m.in. prowadzi konsultacje farmaceutyczne, wykonuje przeglądy lekowe, ocenia farmakoterapię, opracowuje indywidualne plany opieki, wykonuje proste badania diagnostyczne oraz może wystawiać recepty w ramach kontynuacji zlecenia lekarskiego. Zakres tych działań \\fzostał określony w art. 4 ust. 2 pkt 1–5 cytowanej ustawy. W świetle tych przepisów farmaceuci są wykwalifikowanymi i uprawnionymi profesjonalistami medycznymi, których wiedza i kompetencje - skoncentrowane w całości na farmakoterapii - czynią ich naturalnymi i koniecznymi uczestnikami systemu refundacji leków wymagających stałego nadzoru i monitorowania farmakoterapii. Proponowane przez NIA rozwiązanie wpisuje się bezpośrednio w konstrukcję merytoryczną tzw. „czwartej kategorii”, która z założenia ma pełnić funkcję pośrednią między programem lekowym a refundacją apteczną i ma służyć lekom stosowanym w leczeniu chorób innych niż onkologiczne, wymagającym szczególnego nadzoru lekarza lub farmaceuty, ale niekoniecznie hospitalizacji ani kosztownych reżimów terapeutycznych. Ministerstwo Zdrowia wskazało w uzasadnieniu projektowanego rozwiązania 10 kluczowych celów utworzenia nowej kategorii dostępności refundacyjnej. Wszystkie one mogą być w pełni, a w wielu przypadkach nawet skuteczniej, zrealizowane przy udziale farmaceutów w ramach opieki farmaceutycznej. Po pierwsze, propozycja NRA umożliwia zwiększenie dostępności terapeutycznej pacjentów do nowoczesnych technologii, ponieważ apteki ogólnodostępne działają na terenie całego kraju, niemalże w każdej gminie. Mogą prowadzić kontynuację leczenia także w miejscach bez dostępu do poradni specjalistycznych.  \\fPo drugie, zmniejszenie reżimu prowadzenia terapii jest możliwe dzięki narzędziom opieki farmaceutycznej, takim jak przeglądy lekowe, dokumentacja efektów leczenia\\ni wykonywanie badań podstawowych. Farmaceuci w ramach swoich ustawowych obowiązków wykonują świadczenia polegające na monitorowaniu działań niepożądanych, identyfikacji interakcji lekowych, przeciwwskazań, braku skuteczności oraz problemów wynikających\\nz politerapii. Oznacza to, że pełnią oni rolę bezpośrednio realizującą cel prowadzenia nadzorowanej farmakoterapii, jakiemu służyć ma nowa kategoria. Jednocześnie, dzięki liczbie ok. 11 200 aptek w Polsce, możliwe jest radykalne zwiększenie puli świadczeniodawców, co wpisuje się w trzeci i czwarty cel wskazany przez Ministerstwo Zdrowia - zmniejszenie barier administracyjnych i kolejek do świadczeń. Dalsze cele, takie jak zmniejszenie wydatków płatnika, zwiększenie znaczenia leków generycznych i biopodobnych czy zapewnienie kontroli nad produktami wrażliwymi, również znajdują bezpośrednie uzasadnienie w kompetencjach farmaceutów. To właśnie oni najczęściej identyfikują problemy w dostępie do leków, nadzorują ich obrót i reagują na zjawiska takie jak nieuzasadnione wywozy. Opieka farmaceutyczna, dzięki swojej strukturze, eliminuje zagrożenia wynikające z niekontrolowanego obrotu lekami\\fi receptomatów, ponieważ każdy przypadek jest dokumentowany i nadzorowany we współpracy z lekarzem. Warto także podkreślić, że w obecnym systemie prawnym wielu lekarzy realizujących świadczenia w ramach AOS nie ma bezpośredniego doświadczenia w zakresie stosowania nowoczesnych leków nieonkologicznych. AOS to bowiem bardzo szeroka kategoria, w której znajdują się również poradnie, które nie zajmują się zaawansowaną farmakoterapią. Tymczasem farmaceuci jako grupa zawodowa, zajmują się wyłącznie lekami i ich stosowaniem, a więc ich udział w realizacji tej kategorii gwarantuje nie tylko dostępność, ale również jakość i bezpieczeństwo terapii. Ujęcie opieki farmaceutycznej w definicji czwartej kategorii oznacza także stworzenie elastycznego modelu świadczenia, w którym pacjent może być leczony w sposób zdecentralizowany, w ramach współpracy pomiędzy podmiotem wykonującym działalność leczniczą a apteką ogólnodostępną. Farmaceuta, jako członek zespołu terapeutycznego, pełni w takim modelu rolę realizatora świadczenia zdrowotnego, współdziałając z lekarzem, ale również aktywnie monitorując leczenie w sposób dokumentowany, z wykorzystaniem posiadanych narzędzi systemowych (jak system P1, aplikacje apteczne, e-recepty). Podsumowując, propozycja Naczelnej Izby Aptekarskiej, aby opieka farmaceutyczna została objęta zakresem nowej kategorii dostępności refundacyjnej, wypełnia wszystkie cele \\fwskazane przez Ministra Zdrowia i daje gwarancję ich skuteczniejszej realizacji dzięki: wysokim kompetencjom farmaceutów; bliskości punktów świadczenia (apteki praktycznie w każdej gminie); mniejszym kosztom organizacyjnym; skuteczniejszemu nadzorowi nad terapią; eliminacji nadużyć i patologii. Brak uwzględnienia farmaceutów w systemie tej kategorii byłby nie tylko sprzeczny\\nz celem nowelizacji, ale również oznaczałby niewykorzystanie dostępnych i ustawowo uprawnionych zasobów systemu ochrony zdrowia. Dlatego konieczne jest, aby w art. 6 ust. 1 pkt 2a ustawy refundacyjnej, obok świadczeń AOS, wprost wskazać także możliwość stosowania leków w ramach opieki farmaceutycznej, zgodnie z art. 4 ust. 2 ustawy o zawodzie farmaceuty. Propozycja NRA, zgodnie z którą leki objęte nową kategorią dostępności refundacyjnej mogłyby być stosowane zarówno w ramach świadczeń udzielanych w rodzaju ambulatoryjnej opieki specjalistycznej, jak i w ramach opieki farmaceutycznej, znajduje uzasadnienie nie tylko w potrzebach systemu ochrony zdrowia, ale również w istniejących regulacjach oraz konstrukcjach prawnych możliwych do zastosowania per analogiam.  W szczególności możliwe jest oparcie tej kategorii o model organizacyjno-prawny \\ftożsamy lub zbliżony do modelu programów lekowych, określonego w zarządzeniu nr 9/2025/DGL Prezesa Narodowego Funduszu Zdrowia. Programy lekowe są realizowane jako świadczenia gwarantowane w rodzaju leczenie szpitalne. Ich struktura opiera się na formalnym zawarciu umowy pomiędzy Narodowym Funduszem Zdrowia a świadczeniodawcą, spełniającym określone warunki lokalizacyjne, kadrowe i organizacyjne. Świadczenie zdrowotne jest ściśle określone: zawiera kryteria kwalifikacji i wyłączenia, sposób dawkowania leku, monitorowanie wyników terapii oraz wymogi raportowe. Każdy etap realizacji świadczenia jest kontrolowany, a dokumentacja wprowadzana do systemu P1 i elektronicznego systemu monitorowania programów lekowych. Konstrukcja ta może zostać zastosowana - mutatis mutandis - również do realizacji świadczeń w ramach nowej kategorii dostępności refundacyjnej obejmującej opiekę farmaceutyczną. Z uwagi na zbieżność celów, zakresu i metodyki działania, świadczenie opieki farmaceutycznej może zostać ukształtowane analogicznie do programu lekowego, przy czym realizacja świadczenia mogłaby odbywać się w modelu zintegrowanym, np. w formie świadczenia nowego rodzaju: „terapia z monitorowaniem farmaceutycznym”. Proponuje się, aby świadczenie to mogło być realizowane na podstawie umowy zawartej z Narodowym Funduszem Zdrowia, przy zachowaniu określonych wymagań, w tym kryteriów klinicznych, \\fdokumentowania procesu oraz raportowania wyników leczenia. Świadczenie to mogłoby być realizowane przez nową formę organizacyjną – konsorcjum podmiotu leczniczego i apteki ogólnodostępnej, działające na podstawie wspólnego porozumienia lub umowy cywilnoprawnej. Podmiot leczniczy odpowiadałby za aspekt diagnostyczno-kliniczny oraz nadzór medyczny nad leczeniem, natomiast apteka realizowałaby świadczenie opieki farmaceutycznej - w tym kwalifikację farmakoterapeutyczną, przegląd lekowy, wykonanie badań podstawowych (np. pomiar ciśnienia, glikemii), prowadzenie dokumentacji i monitorowanie skuteczności leczenia. Takie rozwiązanie łączy kompetencje obu zawodów medycznych i umożliwia realizację terapii refundowanej\\nw sposób zdecentralizowany, a zarazem kontrolowany i bezpieczny.  Propozycja ta spełnia wszystkie cele wskazane przez Ministra Zdrowia jako uzasadnienie utworzenia nowej kategorii dostępności refundacyjnej.  Model realizacji świadczenia przez konsorcjum podmiotu leczniczego i apteki ogólnodostępnej zapewnia również możliwość szybkiej organizacji leczenia w lokalnych warunkach, w tym w powiatach, w których brakuje poradni specjalistycznych. Taka konstrukcja pozwala na prowadzenie terapii blisko miejsca zamieszkania pacjenta, przy zachowaniu wszystkich wymogów jakościowych, nadzoru merytorycznego i ciągłości dokumentacji medycznej. W połączeniu z odpowiednio ustalonymi \\fkryteriami klinicznymi oraz mechanizmem finansowania (np. w oparciu o ryczałt za farmakoterapię i badania podstawowe) możliwe jest stworzenie nowej, zintegrowanej formy świadczenia zdrowotnego w systemie publicznym. W rezultacie propozycja NIA nie tylko wpisuje się w cel systemowy „odwracania piramidy świadczeń”, lecz również rozwija koncepcję kontroli farmakoterapii poza szpitalem,\\numożliwiając pełną, nadzorowaną i efektywną kosztowo realizację refundowanych terapii w warunkach pozaszpitalnych. Włączenie opieki farmaceutycznej do katalogu świadczeń objętych nową kategorią dostępności powinno zatem zostać rozważone jako jedno z podstawowych i systemowo uzasadnionych rozwiązań, pozwalających połączyć nowoczesną terapię z dostępnością, jakością i bezpieczeństwem leczenia w warunkach bliskich pacjentowi. Ad 1.1. Wprowadzenie zmienionej definicji nowej kategorii dostępności refundacyjnej w art. 6 ust. 1 pkt 2a ustawy o refundacji, obejmującej „leki stosowane w chorobach innych niż onkologiczne w ramach ambulatoryjnej opieki specjalistycznej lub opieki farmaceutycznej”, uzasadnia zmianę brzmienia art. 15 ust. 2 pkt 15a ustawy o świadczeniach oraz dodanie nowego ust. 2b. Celem tych zmian jest zapewnienie systemowej spójności i pełnej funkcjonalności nowej kategorii dostępności refundacyjnej, pośredniej \\fmiędzy programem lekowym a dostępnością apteczną. Zmiana art. 15 ust. 2 pkt 15a u.o.św. porządkuje katalog świadczeń,\\nw ramach, których możliwe jest stosowanie tego typu leków, umożliwiając ich jednoznaczne przyporządkowanie w przepisach wykonawczych, systemach sprawozdawczości i rozliczenia z NFZ. Z kolei art. 15 ust. 2b u.o.św. precyzuje, że świadczenia dotyczące tej grupy leków mogą być udzielane także przez farmaceutów w aptekach ogólnodostępnych - w całości lub w określonym zakresie - w ramach opieki farmaceutycznej, zgodnie z art. 4 ust. 2 ustawy o zawodzie farmaceuty.  Ad 1.2. Proponowana zmiana art. 4 ust. 2 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty polegająca na dodaniu pkt 6 ma na celu dostosowanie zakresu uprawnień farmaceuty do nowej kategorii dostępności refundacyjnej, określonej w art. 6 ust. 1 pkt 2a ustawy refundacyjnej. Wprowadzenie tej kategorii, obejmującej leki stosowane w chorobach innych niż onkologiczne, dostępne w ramach ambulatoryjnej opieki specjalistycznej lub opieki farmaceutycznej, wymaga jednoznacznego wskazania, że farmaceuta może udzielać świadczeń zdrowotnych związanych ze stosowaniem tych leków. Zmiana ta zapewnia podstawę prawną dla pełnej realizacji nowej kategorii świadczeń w aptece ogólnodostępnej w ramach opieki farmaceutycznej.  \\fAd 1.3. Projektowana zmiana w art. 4 ust. 1 ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty polega na dodaniu nowej kategorii czynności objętych pojęciem „wykonywania zawodu farmaceuty”. Obok sprawowania opieki farmaceutycznej, udzielania usług farmaceutycznych, wykonywania zadań zawodowych, wykonywaniu czynności, o których mowa w art. 4 ust. 5, wykonywanie zawodu farmaceuty polegać będzie na przeprowadzaniu szczepień ochronnych oraz wystawianiu recept na produkty immunologiczne niezbędne do przeprowadzenia zalecanych szczepień ochronnych, w rozumieniu przepisów ustawy z dnia 5 grudnia 2008 r. o zapobieganiu oraz zwalczaniu zakażeń i chorób zakaźnych u ludzi (Dz. U. z 2023 r. poz. 1284, z późn. zm.), a także udzielaniu innych świadczeń zdrowotnych w przypadkach określonych w przepisach odrębnych regulujących zasady ich wykonywania. Dodanie nowego przepisu art. 28a gwarantować będzie farmaceutom prawo wglądu do dokumentacji medycznej pacjenta oraz prawo do uzyskania od podmiotu udzielającego świadczeń zdrowotnych pełnej informacji w rozumieniu przepisów ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta, o stanie zdrowia pacjenta, rozpoznaniu, proponowanych metodach diagnostycznych, leczniczych, rehabilitacyjnych, zapobiegawczych i dających się przewidzieć następstwach podejmowanych działań, w zakresie \\fniezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę. Ponadto, projekt w dodawanym art. 28a ust. 2 przewiduje prawo farmaceuty dostępu do danych dotyczących pacjenta przetwarzanych w Internetowym Koncie Pacjenta, o którym mowa w art. 2 pkt 19 ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia (Dz.U. z 2023 r. poz. 2465, z późn. zm.), w zakresie niezbędnym do udzielania świadczeń zdrowotnych przez farmaceutę. Obie zmiany uzasadnione są tymi sami okolicznościami, które przemawiają za zapewnieniem farmaceucie dostępu do danych osobowych lub jednostkowych danych medycznych usługobiorców, przetwarzanych w systemie teleinformatycznym usługodawcy lub w SIM.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej             \\f                                                                         \\f                                                                                \\f                                                                                \\f                                        .\\n\\tNaczelna Izba Aptekarska\\t4 kategoria refundacyjna cz. 2\\tW konsekwencji, konieczne są kolejne zmiany:  W art. 2 pkt 17 (dot. art. 87b ustaw - Prawo farmaceutyczne) proponuje się nadać nowe, poniższe brzmienie. Uchylenie zmiany z art. 2 pkt 14 lit. a (dotyczącą art. 78 ust. 1 pkt 3a lit. i Pr. farm.). Nadanie nowego brzmienia art. 2 pkt 16 (dot. art. 87 Pr. farm.). Dodanie w art. 2 zmiany pkt 20a (dotyczącej art. 106 ust. 3 pkt 2 Pr. farm.) \\fDodanie w art. 3 zmiany pkt 7a (dotyczącej art. 132a ust. 1 (konsorcjum)).  1.4.1. W art. 2 pkt 17 proponuje się nadać poniższe brzmienie.  „17) po art. 87a dodaje się art. 87b w brzmieniu: „Art. 87b. 1. Podmiot leczniczy wykonujący działalność leczniczą w rodzaju ambulatoryjne świadczenia zdrowotne, w ramach których udzielane są świadczenia, gwarantowane o których mowa w art. 15 ust. 2 pkt 15a ustawy z dnia 27 sierpnia 2004 r.\\no świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, obowiązany jest do utworzenia apteki szpitalnej albo działu farmacji szpitalnej, przeznaczonych do zaopatrywania się w produkty lecznicze, dla których ustalona została kategoria refundacyjna, o której mowa w art. 6 ust. 1 pkt 2a ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, z zastrzeżeniem ust. 2.  2. Obowiązek utworzenia apteki szpitalnej albo działu farmacji szpitalnej nie dotyczy podmiotu leczniczego, o którym mowa w ust. 1, jeżeli świadczenia gwarantowane, o których mowa w art. 15 ust. 2 pkt 15a ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, udzielane są wspólnie z apteką ogólnodostępną, która zapatruje ten podmiot lub pacjentów w produkty \\flecznicze, dla których ustalona została kategoria refundacyjna, o której mowa w art. 6 ust. 1 pkt 2a ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych.”;  1.4.2. Proponuje się uchylić zmianę z art. 2 pkt 14 lit. a (dotyczącą art. 78 ust. 1 pkt 3a lit. i Pr. farm.). \\t\\fUzasadnienie ad 1.4.1. oraz 1.4.2. Propozycja NRA dotycząca art. 87b Pr. farm. stanowi logiczną konsekwencję wprowadzenia nowej kategorii refundacyjnej leków stosowanych w chorobach innych niż onkologiczne, definiowanej jako „lek w ramach ambulatoryjnej opieki specjalistycznej lub opieki farmaceutycznej”. W przeciwieństwie do propozycji Ministerstwa Zdrowia, zakładającej obligatoryjne tworzenie w każdym podmiocie leczniczym działu dystrybucji leków, propozycja NIA umożliwia realizację świadczenia w elastycznej formule - przez aptekę szpitalną, dział farmacji szpitalnej lub we współpracy z apteką ogólnodostępną.  \\fTaka konstrukcja odzwierciedla nowy model świadczenia lekowego, w którym kluczową rolę pełni współpraca między podmiotem leczniczym a farmaceutą, zgodnie z art. 4 ust. 2 pkt 6 ustawy o zawodzie farmaceuty. Dzięki temu rozwiązaniu pacjent może uzyskać dostęp do refundowanego leku poza szpitalem, przy jednoczesnym zachowaniu kontroli nad terapią\\ni bezpieczeństwem farmakoterapii.  Model zaproponowany przez NIA eliminuje konieczność tworzenia nowych jednostek administracyjnych w podmiotach leczniczych, zmniejsza koszty, zwiększa dostępność świadczeń i umożliwia udział aptek ogólnodostępnych w realizacji świadczeń gwarantowanych, stanowiąc spójną implementację założeń nowelizacji ustawy refundacyjnej.                               \\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej                     \\n\\tNaczelna Izba Aptekarska\\t4 kategoria refundacyjna cz. 3\\t1.4.3. Nadanie nowego brzmienia art. 2 pkt 16 (dot. art. 87 Pr. farm.). - w art. 2 pkt 16 otrzymuje brzmienie: „16) w art. 87: ust. 2a i 2b otrzymują brzmienie: „2a. Aptekę szpitalną tworzy się w: zakładzie leczniczym, w którym podmiot leczniczy wykonuje działalność leczniczą w rodzaju stacjonarne i całodobowe świadczenia zdrowotne szpitalne i inne niż szpitalne; jednostce organizacyjnej publicznej służby krwi, o której mowa w art. 4 ust. 3 pkt 2 ustawy z dnia 22 sierpnia 1997 r. o publicznej służbie krwi; zakładzie leczniczym, w którym podmiot leczniczy wykonuje działalność leczniczą w rodzaju ambulatoryjne świadczenia zdrowotne, w ramach których udzielane są świadczenia gwarantowane o których mowa w art. 15 ust. 2 pkt 15a ustawy z dnia 27 sierpnia 2004 r. o świadczeniach \\fopieki zdrowotnej finansowanych ze środków publicznych. 2b. Za zgodą wojewódzkiego inspektora farmaceutycznego właściwego ze względu na położenie zakładu leczniczego apteki szpitalnej nie tworzy się: w zakładzie leczniczym, w którym podmiot leczniczy wykonuje działalność leczniczą w rodzaju całodobowe świadczenia zdrowotne inne niż szpitalne wyłącznie w zakresie świadczeń, o których mowa w art. 15 ust. 2 pkt 4-6 lub 11 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych (Dz. U. z 2024 r. poz. 146, z późn. zm.) - jeżeli udzielanie tych świadczeń nie wymaga stosowania produktów leczniczych wymagających nadzoru farmaceuty; w zakładzie leczniczym, w którym podmiot leczniczy wykonuje działalność leczniczą w rodzaju ambulatoryjne świadczenia zdrowotne, w ramach których udzielane są świadczenia gwarantowane o których mowa w art. 15 ust. 2 pkt 15a ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych - jeżeli świadczenia te udzielane są wspólnie z apteką ogólnodostępną, która zapatruje ten podmiot lub pacjentów w produkty lecznicze, dla których ustalona została kategoria refundacyjna, o której mowa w art. 6 ust. 1 pkt 2a ustawy z dnia 12 \\fmaja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych.”,  ust. 4 otrzymuje brzmienie: „4. Apteka szpitalna jest przeznaczona do: 1) zaopatrywania zakładu leczniczego lub jednostki organizacyjnej publicznej służby krwi, w których została utworzona, oraz pacjentów wskazanych w art. 106 ust. 3 pkt 2 i 3; 2) zapewnienia świadczenia usług farmaceutycznych, o których mowa w art. 86 ust. 2, na potrzeby podmiotu leczniczego lub jednostki organizacyjnej publicznej służby krwi, o której mowa w art. 4 ust. 3 pkt 2 ustawy z dnia 22 sierpnia 1997 r. o publicznej służbie krwi, w których została utworzona.”, w ust. 4c w pkt 4 kropkę zastępuje się średnikiem i dodaje się pkt 5 w brzmieniu „5) zakładzie leczniczym, w którym podmiot leczniczy wykonuje działalność leczniczą w rodzaju ambulatoryjne świadczenia zdrowotne, w ramach, których udzielane są świadczenia gwarantowane o których mowa w art. 15 ust. 2 pkt 15a ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych.”, w ust. 4d w pkt 2 kropkę zastępuje się średnikiem i dodaje się pkt 3 w brzmieniu: „3) zapatrywania pacjentów w produkty lecznicze, dla których ustalona została kategoria refundacyjna, o której mowa w art. 6 ust. 1 pkt 2a ustawy z dnia 12 maja 2011 r. o refundacji leków, środków \\fspożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych.”;\\t\\fUzasadnienie ad 1.4.3. Proponowana zmiana art. 87 ustawy – Prawo farmaceutyczne ma na celu zapewnienie spójności systemowej i organizacyjnej z projektowaną nową kategorią refundacyjną leków określoną w art. 6 ust. 1 pkt 2a ustawy o refundacji. Nowa kategoria przewiduje refundację leków stosowanych w chorobach innych niż onkologiczne w ramach ambulatoryjnych świadczeń zdrowotnych oraz w ramach opieki farmaceutycznej (wg propozycji NIA), co wymaga dostosowania struktury organizacyjnej podmiotów realizujących te świadczenia do obowiązujących przepisów Prawa farmaceutycznego. Z tego względu art. 87 ust. 2a zostaje uzupełniony o możliwość i obowiązek tworzenia apteki szpitalnej także w zakładach leczniczych realizujących świadczenia w ramach nowej kategorii refundacyjnej. Zmiana ta odpowiada potrzebie zapewnienia pacjentom odpowiedniego dostępu do leków refundowanych w warunkach ambulatoryjnych, przy jednoczesnym zapewnieniu nadzoru farmaceutycznego \\fi jakości farmakoterapii. Umożliwia to również elastyczność organizacyjną – świadczenia mogą być realizowane samodzielnie przez podmiot leczniczy (wówczas tworzy on aptekę szpitalną), jak i we współpracy z apteką ogólnodostępną, jeśli taka forma jest organizacyjnie i logistycznie uzasadniona. Zmiana ust. 4 porządkuje funkcje apteki szpitalnej, doprecyzowując, że służy ona także pacjentom objętym świadczeniami gwarantowanymi na podstawie art. 15 ust. 2 pkt 15a ustawy o świadczeniach.  Jednocześnie zmiana w ust. 4c i dodanie pkt 5 doprecyzowuje katalog podmiotów, w których dopuszcza się utworzenie zamiast apteki szpitalnej lub apteki zakładowej działu farmacji szpitalnej, a więc w zakładach realizujących świadczenia ambulatoryjne w zakresie nowej kategorii refundacyjnej. Zmiana ust. 4d pkt 2 i dodanie pkt 3 wprost wskazuje, że do zadań działu farmacji szpitalnej może należeć również zapatrywanie pacjentów w produkty lecznicze z nowej kategorii dostępności. NIA nie może zgodzić się na zmianą art. 87 ust. 4 ustawy - Prawo farmaceutyczne, polegającą na wykreśleniu wyrazu „zakładu” w odniesieniu do przeznaczenia apteki szpitalnej. Obecne brzmienie przepisu, zgodnie z którym apteka szpitalna jest przeznaczona do zaopatrywania zakładu leczniczego podmiotu leczniczego, znajduje pełne uzasadnienie w strukturze organizacyjnej i funkcjonalnej podmiotów leczniczych oraz w \\fdotychczasowej, stabilnej wykładni przepisów. Proponowana nowelizacja w rzeczywistości znosi powiązanie apteki szpitalnej z konkretnym zakładem leczniczym, co może prowadzić do niekontrolowanego rozszerzenia zakresu działalności apteki szpitalnej na wszystkie zakłady lecznicze podmiotu leczniczego, niezależnie od ich lokalizacji, profilu działania czy skali potrzeb. Taki kierunek zmian stoi w sprzeczności z zasadą racjonalnej gospodarki produktami leczniczymi, ponieważ wbrew intencjom projektodawcy centralizacja nie zawsze przekłada się na efektywność, a wręcz może utrudnić dostępność leków na poziomie poszczególnych zakładów. Dotychczasowy model, zakładający funkcjonowanie apteki szpitalnej przy konkretnym zakładzie leczniczym, pozwala na precyzyjne przypisanie odpowiedzialności farmaceuty za zaopatrzenie konkretnego zakładu. Wymusza także dostosowanie zakresu działania apteki do faktycznych potrzeb leczniczych danego zakładu leczniczego, co przekłada się na lepszą kontrolę merytoryczną, organizacyjną i prawną. Co istotne, zmiana proponowana w art. 2 pkt 16 projektu może mieć również niezamierzone konsekwencje w kontekście obowiązków raportowych (do ZSMOPL, ESVL), ponieważ utrudni jednoznaczne przypisanie źródła i celu wykorzystania produktów leczniczych w ramach struktury podmiotu leczniczego. W związku z powyższym należy opowiedzieć się za utrzymaniem \\fdotychczasowego brzmienia art. 87 ust. 4 Prawa farmaceutycznego, które zapewnia przejrzystość organizacyjną, odpowiedzialność zawodową farmaceutów oraz bezpieczną gospodarkę lekami w strukturach podmiotów leczniczych. \\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej                        \\n\\tNaczelna Izba Aptekarska\\t4 kategoria refundacyjna cz. 4\\tDodanie w art. 2 pkt 20a (dotyczącej art. 106 ust. 3 pkt 2 Pr. farm.)  - w art. 2 po pkt 20 dodaje się pkt 20a w brzmieniu:  „20a) w art. 106 ust. 3 po pkt 2 dodaje się pkt 2a w brzmieniu: „2a) pacjentów w produkty lecznicze, dla których ustalona została kategoria refundacyjna, o której mowa w art. 6 ust. 1 pkt 2a ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych.”;\\tProponowana zmiana art. 106 ust. 3 ustawy – Prawo farmaceutyczne ma na celu dostosowanie zakresu uprawnień aptek szpitalnych do nowej kategorii refundacyjnej leków określonej w art. 6 ust. 1 pkt 2a ustawy o refundacji. Uzupełnienie katalogu pacjentów, którym apteka szpitalna może wydawać leki, o osoby objęte leczeniem w ramach tej nowej kategorii (czyli „leków stosowanych w chorobach innych niż onkologiczne w ramach AOS lub opieki farmaceutycznej”), zapewnia pełną zgodność z nową strukturą dostępności refundacyjnej i umożliwia praktyczną realizację świadczeń w nowym modelu.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej  \\n\\tNaczelna Izba Aptekarska\\t4 kategoria refundacyjna cz. 5\\tDodanie w art. 3 pkt 7a (dotyczącej art. 132a (konsorcjum)) w brzmieniu: „7a) w art. 132a ust. 1 otrzymuje brzmienie: „1. Świadczeniodawcy mogą wspólnie ubiegać się o zawarcie i wykonywanie umowy o udzielanie świadczeń opieki zdrowotnej, której przedmiotem jest udzielanie świadczeń opieki zdrowotnej w nie mniej niż dwóch zakresach, o których mowa w art. 15 ust. 2 pkt 2-8, 10-13, 15 i 16, a także w przypadku zakresu, o którym mowa w art. 15 ust. 2 pkt 15a, niezależnie od liczby zakresów objętych umową.”.  \\tProponowana zmiana art. 132a ust. 1 ustawy o świadczeniach opieki zdrowotnej ma na celu dostosowanie przepisów do wprowadzenia nowej kategorii refundacyjnej leków określonej w art. 15 ust. 2 pkt 15a, czyli świadczeń obejmujących stosowanie leków w chorobach innych niż onkologiczne, realizowanych także w ramach opieki farmaceutycznej. Nowe brzmienie przepisu umożliwia wspólne ubieganie się o zawarcie umowy przez podmioty lecznicze i apteki ogólnodostępne, nawet jeżeli świadczenia objęte umową dotyczą wyłącznie tego jednego zakresu. \\fUzasadnieniem takiego rozwiązania jest konieczność wdrożenia nowego modelu współpracy między świadczeniodawcami, w którym integralną rolę odgrywają farmaceuci jako realizatorzy świadczeń w ramach opieki farmaceutycznej. Włączenie pkt 15a do katalogu wyjątków pozwala na skuteczne tworzenie konsorcjów podmiotów leczniczych i aptek, które razem zapewniają pełną ścieżkę farmakoterapii – od ordynacji przez monitorowanie po dystrybucję leku – bez konieczności rozszerzania umowy na inne zakresy.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria  Art. 2 pkt 18 ustawy refundacyjnej\\tArt. 2 Użyte w ustawie określenia oznaczają: (…) 18) program lekowy - program zdrowotny w rozumieniu art. 5 pkt 30 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych obejmujący technologię lekową, w której substancja czynna w danym wskazaniu oraz dla danej populacji nie jest składową kosztową innych świadczeń gwarantowanych z wyjątkiem leków objętych kategorią dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a, lub środek spożywczy specjalnego przeznaczenia żywieniowego, który nie jest składową kosztową innych świadczeń gwarantowanych w rozumieniu art. 5 pkt 35 tej ustawy; \\tKonieczne dla zapewnienia możliwości współistnienia programu lekowego i refundacji w ramach nowej kategorii. Istotne dla zapewnienia ciągłości terapii dla pacjentów objętych programami lekowymi w ramach dotychczasowej ścieżki.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 6 ust. 2b ustawy \\frefundacyjnej\\t\\f2b. Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust. 1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz \\fokreślenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1, 2 i 2a, a także dopuszczenie do wydawania pacjentom w aptekach ogólnodostępnych leku w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 2a. \\t\\fRealizacja założeń modelu 2.0. W ramach realizacji modelu dystrybucji 2.0 konieczne jest ustawowe umocowanie uprawnienia Ministra Zdrowia do decydowania, które z leków objętych \\fnową kategorią dostępności będą mogły być dystrybuowane do pacjentów przez apteki ogólnodostępne (niezależnie od dystrybucji przez podmioty lecznicze).\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 7 ust. 4a ustawy refundacyjnej\\t4a. Dla leków objętych kategorią dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a, dopuszczonych do wydawania pacjentom w aptekach ogólnodostępnych na podstawie art. 6 ust. 2b, urzędowa marża detaliczna nie może być wyższa niż … zł. \\tAby uniknąć nadmiernego wzrostu wydatków publicznych w związku z dopuszczeniem leków z nowej kategorii dostępności refundacyjnej do szerszej dystrybucji w aptekach ogólnodostępnych, należy wprowadzić górny limit marży detalicznej dla tych leków, analogicznie do limitu marży hurtowej (art. 7 ust. 1 UR). Poziom limitu pozostawiamy do oceny Projektodawcy.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 9 ust. 2b ustawy refundacyjnej\\t2b. W przypadku leków o kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a, dopuszczonych do wydawania pacjentom w aptekach ogólnodostępnych na podstawie art. 6 ust. 2b, apteka ogólnodostępna nabywa je po cenie sztywnej odpowiadającej cenie wyliczonej na podstawie art. 9 ust. 2.  \\tAby uniknąć nadmiernego wzrostu wydatków publicznych w związku z dopuszczeniem leków z nowej kategorii dostępności refundacyjnej do szerszej dystrybucji w aptekach ogólnodostępnych, leki te powinny być nabywane po cenie odpowiadającej maksymalnej cenie, po jakiej leki te nabywają świadczeniodawcy. Wartość referencyjna będzie znana z obwieszczenia, gdzie jest zamieszczana informacyjnie (zob. art. 37 ust. 2 pkt 6).\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 15 ust. 12a ustawy refundacyjnej\\t12a. W przypadku leków, o których mowa w art. 6 ust. 1 pkt 2a, dopuszczonych do wydawania pacjentom w aptekach ogólnodostępnych na podstawie art. 6 ust. 2b, limit finansowania aptekom ogólnodostępnym obejmuje także marżę detaliczną. \\t\\fZe względu na możliwość dopuszczenia leku z nowej kategorii dostępności do nieodpłatnego wydawania pacjentom w aptece ogólnodostępnej, konieczne jest zapewnienie, iż finansowanie ze środków publicznych obejmie również marżę apteki. \\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 37 ust. 2 pkt 10a, 11 ustawy refundacyjnej\\t2. Obwieszczenie, o którym mowa w ust. 1, zawiera: 1) dane identyfikujące lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny; 2) kategorię dostępności refundacyjnej; 3) poziom odpłatności; 3a) cenę zbytu netto; 3b) cenę hurtową brutto; 4) urzędową cenę zbytu; 5) (uchylony) 5a) cenę detaliczną; 6) wysokość limitu finansowania dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, o którym mowa w art. 6 ust. 1 pkt 1 albo informacyjną wysokość limitu finansowania dla leków, środków spożywczych specjalnego przeznaczenia żywieniowego, o których mowa w art. 6 ust. 1 pkt 2-3 dostosowaną do wielkości opakowania jednostkowego; 7) wysokość dopłaty świadczeniobiorcy; 8) grupę limitową; 9) termin wejścia w życie decyzji, o której mowa w art. 11 oraz okres jej obowiązywania 10) wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa w art. 6 ust. 2, określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, jeżeli dotyczy; 10a) informację o dopuszczeniu leku, o którym mowa w art. 6 ust. 1 pkt 2a, do wydawania pacjentom w aptekach ogólnodostępnych oraz wysokość limitu \\ffinansowania aptekom, dostosowaną do wielkości opakowania jednostkowego, jeżeli dotyczy; 11) liczbę DDD lub PDD w opakowaniu leku, przyjętą do obliczeń na potrzeby stosowania ustawy. \\t                          W związku z możliwością dopuszczenia leków z nowej kategorii do bezpłatnego wydawania pacjentom w aptekach ogólnodostępnych i szczególnym określeniem limitu finansowania tych leków, konieczne jest informowanie aptek o wysokości tego limitu.   Dla niektórych produktów trudne jest ustalenie DDD/PDD w opakowaniu leku przyjętego przez MZ do obliczeń cen, \\fpodstaw limitu i marż. Ma to też znaczenie dla leków złożonych. \\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej                                       \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 87b ust. 1 PF\\t1. Podmiot leczniczy wykonujący działalność leczniczą w rodzaju ambulatoryjne świadczenia zdrowotne, w ramach których udzielane są świadczenia, gwarantowane o których mowa w art. 15 ust. 2 pkt 15a ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, jest obowiązany do może utworzeniayć działu dystrybucji leków. \\tMając na uwadze, że podstawową formą dotyczącą leków z nowej kategorii dostępności powinno być zaopatrzenie przez apteki ogólnodostępne, dystrybucja do pacjentów przez podmioty lecznicze miałaby charakter uzupełniający i byłaby prowadzona w tych podmiotach, które się na to zdecydują.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 96 ust. 1a PF\\t1a.\\tProdukty lecznicze o kategorii dostępności, o której mowa w art. 23a ust. 1 pkt 5, dopuszczone do wydawania pacjentom w aptekach ogólnodostępnych na podstawie art. 6 ust. 2b ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, są wydawane z apteki ogólnodostępnej na podstawie recepty. \\tRealizacja założeń modelu 2.0. Ze względu na możliwość dopuszczenia leków z nowej kategorii dostępności do dystrybucji w aptekach ogólnodostępnych, konieczne jest stworzenie wyraźnej podstawy do wydania takiego leku pacjentowi.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 96a ust. 7aaa i 7aab PF\\t7aaa. W przypadku produktu leczniczego dopuszczonego do wydawania pacjentom w aptekach ogólnodostępnych na podstawie art. 6 ust. 2b ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, pacjent od dnia realizacji recepty może otrzymać maksymalnie ilość produktu leczniczego niezbędną pacjentowi do 30-dniowego okresu stosowania wyliczonego \\fna podstawie określonego na recepcie sposobu dawkowania.   7aab. W przypadku gdy na recepcie, o której mowa w ust. 7aaa, przepisano ilość większą niż do 30-dniowego stosowania, kolejną ilość produktu leczniczego niezbędną do następnego 30-dniowego okresu stosowania pacjent może otrzymać po upływie 3/4 okresu, na który zrealizował receptę. \\t\\fRealizacja założeń modelu 2.0. Ograniczenie wydawanej pacjentowi jednorazowo ilości leku objętego nową kategorią dostępności ma na celu racjonalizację wydatków płatnika publicznego i zapewnienie nadzoru lekarza nad farmakoterapią.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej       \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\t4 kategoria   Art. 15 ust. 2 pkt 14 ustawy o świadczeniach \\t2. Świadczeniobiorcy przysługują świadczenia gwarantowane z zakresu: 1) podstawowej opieki zdrowotnej; 2) ambulatoryjnej opieki specjalistycznej; 3) leczenia szpitalnego; 4) opieki psychiatrycznej i leczenia uzależnień; 5) rehabilitacji leczniczej; 6) świadczeń pielęgnacyjnych i opiekuńczych w ramach opieki długoterminowej; 7) leczenia stomatologicznego; 8) lecznictwa uzdrowiskowego; 9) zaopatrzenia w wyroby medyczne, na zlecenie osoby uprawnionej, oraz ich naprawy, o których mowa w ustawie o refundacji; 10) ratownictwa medycznego; 11) opieki paliatywnej i hospicyjnej; 12) świadczeń wysokospecjalistycznych; 13) programów zdrowotnych; 14) leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych dostępnych w aptece na receptę, z wyłączeniem leków, o których mowa w pkt 15a; 15) programów lekowych określonych w przepisach ustawy o refundacji; \\f15a) leków stosowanych w chorobach innych niż onkologiczne w ramach udzielania świadczeń w zakresie, o którym mowa w pkt 2 i 3, we wskazaniu określonym stanem klinicznym, określonych w przepisach ustawy o refundacji; 16) leków stosowanych w chemioterapii określonych w przepisach ustawy o refundacji; 17) leków nieposiadających pozwolenia na dopuszczenie do obrotu na terytorium Rzeczypospolitej Polskiej, sprowadzanych z zagranicy na warunkach i w trybie określonym w art. 4 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne, pod warunkiem że w stosunku do tych leków wydano decyzję o objęciu refundacją na podstawie ustawy o refundacji; 17a) ratunkowego dostępu do technologii lekowych; 18) środków spożywczych specjalnego przeznaczenia żywieniowego, sprowadzonych z zagranicy na warunkach i w trybie określonym w art. 29a ustawy z dnia 25 sierpnia 2006 r. o bezpieczeństwie żywności i żywienia (Dz. U. z 2023 r. poz. 1448), pod warunkiem, że w stosunku do tych środków wydano decyzję o objęciu refundacją na podstawie ustawy o refundacji; 19) stwierdzenia w związku z wydaniem zaświadczenia, o którym mowa w art. 133 § 2b ustawy z dnia 6 czerwca 1997 r. - Kodeks postępowania karnego (Dz. U. z 2024 r. poz. 37), że stan zdrowia osoby, która udzieliła pełnomocnictwa pocztowego do odbioru przesyłek pocztowych w placówce pocztowej w rozumieniu ustawy z dnia 23 listopada 2012 r. - Prawo pocztowe (Dz. U. z 2023 r. \\fpoz. 1640), uniemożliwia lub w znacznym stopniu utrudnia osobiste odebranie pisma w placówce pocztowej. \\t                  Co do pkt 14 – W związku z planowanym dopuszczeniem możliwości dystrybucji leków z nowej kategorii refundacyjnej także w aptekach ogólnodostępnych, należy wyraźnie rozróżnić świadczenie gwarantowane z pkt 14 (realizowane ze swej istoty w aptece) od nowego świadczenia z pkt 15a (którego rzeczowa część może, ale nie zawsze musi, być realizowana w takiej aptece).  Co do pkt 15a – Dostosowanie do proponowanego brzmienia  art. 6 ust. 1 pkt 2a UR. Jak wskazano  w stanowisku PZPPF z dnia 20.06.2025 r., w uwadze do art. 6 ust. 1 pkt 2a UR, nie należy ograniczać z góry możliwości refundacji leków w ramach nowej kategorii dostępności w całym zakresie zarejestrowanych wskazań i przeznaczeń. Taką możliwość stosuje się w odniesieniu do leków o kategorii dostępności w aptece na receptę, jak i chemioterapii. Nie ma powodu, by z góry wykluczać ją w przypadku leków z nowej kategorii dostępności. Ostateczne o zakresie refundowanych wskazać decydować będzie i tak Minister Zdrowia \\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 1 lit. b dotyczący art. 2 pkt 4a ustawy refundacyjnej\\t4a) cena efektywna – cenę hurtową leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego wynikającą z decyzji o objęciu refundacją przeliczeniu na jedno opakowanie lub na  jednego  pacjenta  ponoszoną  przez  podmiot  zobowiązany do finansowania  świadczeń  zdrowotnych  ze środków  publicznych, z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 i 4.\\tZmiana zaproponowana przez Ministerstwo Zdrowia i rozwinięta w uzasadnieniu idzie w bardzo dobrym kierunku.  Jak wskazano w uzasadnieniu do projektu: „Tym samym, do wyliczeń ceny efektywnej wykorzystywane powinny być wyłącznie te instrumenty dzielenia ryzyka, które w sposób bezpośredni oraz możliwy do jednoznacznego wyliczenia wpływają na koszt jednego opakowania leku lub koszt leczenia jednego pacjenta (tzw. mechanizm pay-back lub pre-paid; maksymalna cena hurtowa brutto, po której świadczeniodawca nabywa produkt celem realizacji świadczenia gwarantowanego).” INFARMA w pełni popiera to podejście. Pragniemy jednak doprecyzować takie rozwiązanie poprzez wskazanie wprost, że dotyczy to instrumentów dzielenia ryzyka wskazanych w pkt 2 i 4 (tzw. „CHB” oraz tzw. „payback”). W praktyce tylko w stosunku do tych mechanizmów jest znany wpływ na cenę zbytu netto zarówno w chwili złożenia wniosku, jak i w chwili wydania decyzji – co odpowiada podstawowym zasadom postępowania administracyjnego – zgodnie z którym decyzje administracyjne, powinny być wydane po dokładnym wyjaśnieniu stanu faktycznego, obowiązującego w chwili wydania decyzji administracyjnej (co \\fwynika z zasady praworządności oraz zasady prawdy obiektywnej wskazanych w art. 6 i 7 Kodeksu postępowania administracyjnego). Takiej pewności nie może być w przypadku tzw. CAPu czy RSS opartych o efekty kliniczne. Np. w przypadku CAPu rzetelne i dokładne określenie czy doszło do jego przekroczenia, a jeżeli tak to w jakiej skali (co wpływa bezpośrednio na wysokość zwrotu, a więc pośrednio na cenę zbytu netto), jest możliwe dopiero po podjęciu przez Radę Narodowego Funduszu Zdrowia uchwały w sprawie przyjęcia sprawozdania z wykonania planu finansowego Narodowego Funduszu Zdrowia za dany rok kalendarzowy (co oznacza, że w przypadku ostatniego roku obowiązywania decyzji refundacyjnej odbędzie się to dopiero w kolejnym roku kalendarzowym). Także wskazany w uzasadnieniu pre-paid może być problematyczny, bo np. nie wiadomo na jaką ilość pacjentów (a więc także ilość opakowań produktu) się rozłoży. Podsumowując, celem zapewnienia pewności zarówno dla wnioskodawców, jak i Ministerstwa Zdrowia zasadnym jest aby wprost wskazać, że cena efektywna uwzględnia jedynie wskazane wyżej dwa mechanizmy RSS. Jednocześnie proponujemy zmianę punktu odniesienia z perspektywy płatnika, na perspektywę wnioskodawcy.  Tylko w ten sposób unikniemy problemów dot. ewentualnego wliczania \\fw cenę efektywną innych „ulg” dla płatnika oraz ewentualnego wpływu listy „S” / „Dz” / „ciąża” na cenę efektywną. Cena efektywna jest też istotna z punktu widzenia zobowiązania wnioskodawcy w ramach negocjacji kontynuacyjnych oraz obniżki ceny zw. z wygaśnięciem wyłączności rynkowej - a zatem powinna być związana z elementami, na które wnioskodawca ma wpływ, nie zaś z takimi, które są w całości poza jego wpływem - i są bardzo zmienne w czasie, co dodatkowo utrudnia ustalenie ich (np. limit finansowania).\\t\\fUwaga częściowo zasadna  Przepis zmieniony zgodnie z w następujący sposób: „cena efektywna – cena leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego odpowiadająca wysokości kosztu ponoszonego przez podmiot zobowiązany do finansowania świadczeń ze środków publicznych z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 lub 4”\\n\\tAmerykańska Izba Handlowa w Polsce/ Pracodawcy RP\\tArt. 1 pkt 1 lit. b dotyczący art. 2 pkt 4a ustawy refundacyjnej\\tW art. 2 pkt 4a proponujemy nadać następujące brzmienie: „4a) cena efektywna – cenę hurtową leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w przeliczeniu na jedno opakowanie lub na jednego pacjenta ponoszoną przez podmiot zobowiązany do finansowania świadczeń zdrowotnych ze środków publicznych, z uwzględniającą eniem instrumentyów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 lub 4;” \\tW nawiązaniu do dyskusji podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca proponujemy, aby w definicji ceny efektywnej wprost wskazać jednoznacznie policzalne instrumenty dzielenia ryzyka określone w art. 11 ust. 5, tj. maksymalną cenę hurtową brutto oraz tzw. „payback” do Narodowego Funduszu Zdrowia („NFZ”) za każde zrefundowane opakowanie leku. W ocenie KF AmCham konieczne jest zdefiniowanie „ceny efektywnej” z perspektywy wnioskodawcy, a nie płatnika publicznego i wyraźne określenie wprost tych instrumentów dzielenia ryzyka, które są brane pod uwagę do jej wyliczenia. Tylko w ten sposób możliwe będzie uniknięcie problemów z wyliczeniem ceny efektywnej w ramach postepowań refundacyjnych. Pojęcie ceny efektywnej jest bardzo istotne z punktu widzenia negocjacji cenowych przy kontynuacji refundacji oraz tzw. obowiązkowej obniżce ceny leku. Dlatego też powinna \\fona być powiązana z tymi elementami, na które wnioskodawca ma całkowity wpływ i są one w pełni przewidywalne w czasie. Dodatkowo, KF AmCham proponuje, aby punktem wyjścia do kalkulacji ceny efektywnej była „cena hurtowa”. Uzasadnienie Pracodawcy RP W nawiązaniu do dyskusji podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca proponujemy, aby w definicji ceny efektywnej wskazać jednoznacznie policzalne instrumenty dzielenia ryzyka określone w art. 11 ust. 5, tj. maksymalną cenę hurtową brutto oraz pay-back do Narodowego Funduszu Zdrowia („NFZ”). Proponowane doprecyzowanie realizuje cel wskazany w uzasadnieniu do projektu ustawy, zapewniając możliwość bezpośredniego oraz jednoznacznego wyliczenia wpływu instrumentów dzielenia ryzyka na koszt opakowania leku.  Jedynie w przypadku mechanizmów zawartych w art. 11 ust. 5 pkt 2 i 4 tj. ustalenia ceny hurtowej brutto, po której świadczeniodawca nabywa produkt oraz tzw. pay-back, możliwe jest wyliczenie wpływu na cenę zbytu netto w trakcie każdego etapu postępowania administracyjnego.  Rzeczywisty wpływ na cenę zbytu netto wynikający z pozostałych mechanizmów podziału ryzyka takich jak tzw. CAP, pre-paid, czy RSS oparty o efekty kliniczne, w horyzoncie trwania decyzji \\frefundacyjnej, możliwy jest do wyliczenia z opóźnieniem uniemożliwiającym uwzględnienie go podczas postępowania o kontynuację refundacji. Dopiero po podjęciu przez Radę NFZ uchwały w sprawie przyjęcia sprawozdania z wykonania planu finansowego NFZ za rok kalendarzowy obejmujący ostatni rok obowiązywania danej decyzji refundacyjnej, dostępne są informacje niezbędne do przeprowadzenia wyliczeń. Tym samym, z uwagi na brak danych o liczbie zrefundowanych opakowań czy liczby pacjentów korzystających ze świadczenia w horyzoncie trwania decyzji, w terminie obejmującym okres postępowania refundacyjnego, nie jest możliwe jednoznaczne wyliczenie wpływu mechanizmu pre-paid, który wymieniony został w uzasadnieniu do projektu ustawy.\\t\\fUwaga częściowo zasadna  Przepis zmieniony zgodnie z w następujący sposób: „cena efektywna – cena leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego odpowiadająca wysokości kosztu ponoszonego przez podmiot zobowiązany do finansowania świadczeń ze środków publicznych z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 lub 4”\\n\\tFederacja Przedsiębiorców Polskich\\tArt.1 pkt 1 lit. b projektu odnoszący się do art. 2 pkt 4a ustawy refundacyjnej\\tWnioskujemy o zmianę zapisów dotyczących definicji ceny efektywnej.  Proponujemy następujące brzmienie art. 2 pkt 4a ustawy:  „4a) cena efektywna – cenę leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego odpowiadającą wysokości kosztu ponoszonego przez podmiot zobowiązany do finansowania świadczeń ze środków publicznych na refundację tego leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, w ramach świadczeń \\fgwarantowanych, o których mowa w art. 15 ust. 2 pkt 14-18 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych, w przeliczeniu na jedno opakowanie, z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 i 4;”\\t\\fProponowana w projekcie definicja ceny efektywnej (w szczególności w przeliczeniu na jednego pacjenta) z uwzględnieniem instrumentów dzielenia ryzyka, odbiega w sposób znaczący od definicji samej ceny i jest de facto definicją kosztu, jaki ponosi płatnik publiczny w związku z  finansowaniem świadczeń zdrowotnych ze środków publicznych, o których mowa w art. 15 ust. 2 pkt 14-18 ustawy z dnia 27 sierpnia 2004 r. o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych.   \\fProjektowana definicja nie precyzuje także instrumentów podziału ryzyka, które w sposób bezpośredni, \\njak i możliwy do jednoznacznego wyliczenia, wpływają na koszt jednego opakowania leku lub koszt leczenia jednego pacjenta, na które wskazuje projektodawca w uzasadnieniu.  Mając na uwadze intencję ustawodawcy proponujemy definicję ceny efektywnej, która nie tylko jednoznacznie wskazuje na jej bezpośrednie powiązanie z kosztem ponoszonym przez podmiot zobowiązany do finansowania świadczeń zdrowotnych ze środków publicznych na refundację leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, ale także na wybrane instrumenty dzielenia ryzyka, które w sposób bezpośredni i jednoznaczny do wyliczenia wpływają na koszt jednego opakowania.   Ponadto, ze względu na fakt, iż zaproponowana przez nas definicja odnosi się już wyłącznie do jednego opakowania, a nie do kosztu terapii jednego pacjenta, pozwoli to na jednolite podejście do wszystkich wnioskodawców w prowadzonych postępowaniach. \\t\\fUwaga częściowo zasadna Przepis zmieniony zgodnie z w następujący sposób: „cena efektywna – cena leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego odpowiadająca wysokości kosztu ponoszonego przez podmiot zobowiązany do finansowania świadczeń ze środków publicznych z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 lub 4”\\n\\tIzba Gospodarcza \\\"FARMACJA POLSKA\\\"\\tArt. 1 pkt 1 lit. b dotyczący art. 2 pkt 4a ustawy \\frefundacyjnej\\t\\fpostulujemy zmianę definicji ceny efektywnej w taki sposób, aby cena efektywna uwzględniała wyłącznie instrumenty dzielenia ryzyka, obniżające cenę refundowanego produktu jednolicie \\fna każdym opakowaniu. Tylko bowiem w takim przypadku cena efektywna będzie możliwa do ustalenia w sposób jednoznaczny.\\t\\fKatalog dopuszczalnych instrumentów dzielenia ryzyka z art. 11 ust. 5 ustawy jest bardzo szeroki i uwzględnia bardzo różne rodzaje umów pomiędzy \\fwnioskodawcą a płatnikiem; a przy tym nie jest to katalog zamknięty – możliwe jest ustalenie innego jeszcze rodzaju instrumentu dzielenia ryzyka niż te wskazane w ustawie. Część ze stosowanych w RSS rozwiązań może, ale nie musi, obniżać cenę refundowanego produktu. Przykładowo, w przypadku ustalenia capu na wydatki płatnika na refundowany produkt, powyżej którego zastosowanie będzie miał payback lub obowiązek bezpłatnych dostaw, w zależności od tego, czy w danym roku cap zostanie przekroczony, cena produktu ulegnie tego roku obniżeniu, lub nie.  W związku z treścią art. 13 ust. 6aa ustawy, zgodnie z którym przy odnowieniu refundacji cena efektywna nie może być w kolejnej decyzji o refundacji wyższa niż dotychczasowa, brak pewności co do wysokości ceny efektywnej (bo jej wysokość zależy w powyższym przykładzie od przekroczenia capu i też od liczby opakowań dostarczonych przez wnioskodawcę po jego przekroczeniu) uniemożliwia ustalenie warunków RSS w kolejnej decyzji. Z drugiej strony, przyjęcie interpretacji, zgodnie z którą zakaz pogorszenia dla płatnika ceny efektywnej oznaczałby konieczność powtórzenia tych warunków z poprzedniej decyzji, czyli ustalenia tej samej wysokości capu i obowiązków wnioskodawcy po jego przekroczeniu, uniemożliwiłby stronom dostosowanie warunków instrumentu dzielenia ryzyka do zmieniającego się zapotrzebowania na produkt, na przykład na skutek rekrutowania kolejnych pacjentów do \\fprogramu lekowego, poszerzenia wskazań lub z drugiej strony, włączenia odpowiednika do refundacji.  Dlatego naszym zdaniem definicja ceny efektywnej powinna uwzględniać wyłącznie te instrumenty dzielenia ryzyka, które pozwalają na precyzyjne ustalenie wysokości tej ceny, niezależnie od wielkości sprzedaży czy wydatków płatnika na refundowany produkt.  Będą to zatem porozumienia, obniżające urzędową cenę zbytu w sposób stały, na każdym opakowaniu, takie, jak payback od każdego opakowania refundowanego produktu lub maksymalna cena hurtowa brutto, po której wnioskodawca ma dostarczać lek do świadczeniodawców.\\t\\fUwaga zasadna Nowa propozycja w projekcie: 4a) cena efektywna – cena leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego \\fodpowiadająca wysokości kosztu ponoszonego przez podmiot zobowiązany do finansowania świadczeń ze środków publicznych z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 lub 4;”\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 1 lit. c dotyczący art. 2 pkt 11b ustawy refundacyjnej\\t11b) lek sierocy – produkt leczniczy zarejestrowany w leczeniu choroby rzadkiej lub ultrarzadkiej zgodnie z przepisami prawa Unii Europejskiej.\\tWprowadzenie do przepisów ustawy o refundacji definicji \\\"leku sierocego\\\" mogłoby niepotrzebnie ograniczyć katalog produktów leczniczych, które mogłyby skorzystać z nowej procedury refundacyjnej stworzonej dla tej wyjątkowej grupy. Status leku sierocego uzyskują bowiem substancje czynne, które zostały zarejestrowane w danej jednostce chorobowej jako pierwsze albo wykazały wyższość nad już zarejestrowanym produktem. Natomiast część leków zaprojektowanych do leczenia chorób rzadkich / ultrarzadkich jest rejestrowana w oparciu o badania jednoramienne, co uniemożliwia uzyskanie statusu leku sierocego w przypadku, gdy jest to kolejna cząsteczka zarejestrowana w tej chorobie.\\tUwaga niezasadna Projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Konieczność ustanowienia definicji leku sierocego wynika z faktu, że omawiana WAD dotyczy wyłącznie leków o statusie leku sierocego, które są stosowane w chorobach rzadkich. Zaproponowana (art. 1 pkt 1 lit. b projektu) definicja leku sierocego jest zgodna z rozporządzeniem nr 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. \\fUE). Niniejsza zmiana wiąże się z zaproponowanym dodaniem definicji wielokryterialnej analizy decyzyjnej (art. 1 pkt 1 lit. e projektu w zakresie pkt. 26b). Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce zdrowotnej. Stanowi to również wypełnienie postulatów, które znalazły się w pierwotnej wersji ramowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich\\n\\tAmerykańska Izba Handlowa w Polsce\\\\ Pracodawcy RP\\tArt. 1 pkt 1 lit. c dotyczący art. 2 pkt 11b ustawy refundacyjnej\\tpkt 11b proponujemy nadać następujące brzmienie: 11b) lek sierocy – sierocy produkt leczniczy w rozumieniu art. 2 lit. b rozporządzenia (WE) 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. UE Polskie wydanie specjalne, rozdz. 15, t. 5, str. 21, z późn. zm.); „11b) lek stosowany w chorobie rzadkiej – lek stosowany w leczeniu choroby, która dotyka nie więcej niż 5 na 10 000 osób;” \\tW nawiązaniu do rozmowy podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca prosimy o rozważenie zastąpienia definicji leku sierocego definicją leku stosowanego w chorobie rzadkiej oraz pozostałych przepisów odnoszących się do tej definicji. Zgodnie z przepisem art. 3 rozporządzenia (WE) 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych status leku sierocego w EMA otrzymuje jedynie taki produkt leczniczy, dla którego można wykazać, że nie istnieje zadowalająca metoda diagnozowania, zapobiegania lub leczenia danego stanu chorobowego, oficjalnie dopuszczona na terytorium Unii Europejskiej, lub też, jeśli taka metoda istnieje, to produkt leczniczy przyniesie znaczące korzyści pacjentom cierpiącym na ten stan chorobowy. Kolejny lek stosowany w tej samej chorobie nie otrzyma już tego statusu. Możliwym jest więc scenariusz, w którym \\fto drugi, a nie pierwszy zarejestrowany produkt leczniczy, jedyny posiadający status leku sierocego, będzie się ubiegać o refundację w Polsce jako pierwszy. Wówczas przyjmując zaproponowane brzmienie przepisów nie będzie możliwe zastosowanie dla niego analizy wielokryterialnej.  Możliwym jest również, że z różnych względów lek sierocy już nie będzie refundowany w Polsce, kiedy złożony zostanie wniosek dotyczący innego leku w danej chorobie rzadkiej. Z tego względu, zasadnym byłoby umożliwienia skorzystania z nowych regulacji nie tylko lekom sierocym, ale szerszej grupie leków – stosowanych w leczeniu chorób rzadkich. W Planie dla Chorób Rzadkich na lata 2021-2023 leki przeznaczone do terapii chorób rzadkich zostały zdefiniowane jako leki przeznaczone do leczenia chorób występujących z częstością niższą niż 5 na 10 000 osób w populacji, stąd zaproponowana przez KF AmCham definicja jest analogiczna. Uzasadnienie Pracodawcy RP Prosimy o rozważenie zastąpienia definicji leku sierocego definicją leku stosowanego w chorobie rzadkiej oraz pozostałych przepisów odnoszących się do tej definicji. Nie zawsze lek sierocy stosowany w danej chorobie rzadkiej będzie pierwszym, dla którego złożony zostanie wniosek o objęcie refundacją. Możliwym jest również, że z różnych względów lek sierocy już nie będzie refundowany w Polsce, kiedy złożony zostanie wniosek dotyczący innego leku w danej chorobie rzadkiej. Z tego \\fwzględu, zasadnym byłoby umożliwienie skorzystania z nowych regulacji nie tylko lekom sierocym, ale szerszej grupie leków, tj. lekom stosowanym w leczeniu chorób rzadkich.\\t\\fUwaga niezasadna  Projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Konieczność ustanowienia definicji leku sierocego wynika z faktu, że omawiana WAD dotyczy wyłącznie leków o statusie leku sierocego, które są stosowane w chorobach rzadkich. Zaproponowana (art. 1 pkt 1 lit. b projektu) definicja leku sierocego jest zgodna z rozporządzeniem nr 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. UE). Niniejsza zmiana wiąże się z \\fzaproponowanym dodaniem definicji wielokryterialnej analizy decyzyjnej (art. 1 pkt 1 lit. e projektu w zakresie pkt. 26b). Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce zdrowotnej. Stanowi to również wypełnienie postulatów, które znalazły się w pierwotnej wersji ramowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich.\\n\\tIzba Gospodarcza \\\"FARMACJA POLSKA\\\"\\tArt. 1 pkt 1 lit. c dotyczący art. 2 pkt 11b ustawy refundacyjnej\\tDlatego proponujemy zmianę tej definicji i odniesienie się w przepisach ustawy do leku stosowanego w chorobie rzadkiej, nie do leku sierocego w rozumieniu przepisów rozporządzenia 141/2000.\\tW naszej ocenie, powiązanie statusu leku sierocego i dotyczących takiego leku szczególnych regulacji w ustawie (np. możliwości składania wniosku z analizą wielokryterialną), ze statusem leku sierocego, uzyskanym w trybie rozporządzenia (WE) 141/2000 Parlamentu Europejskiego i Rady, stanowi zbyt daleko idące ograniczenie, które dodatkowo utrudni w praktyce procedowanie wniosków refundacyjnych dla takich leków. Wskazujemy, że ochrona prawna leku jako produktu sierocego w przepisach rozporządzenia unijnego jest czasowa, a do tego ogranicza się do wybranych wskazań takiego leku. Co więcej, zasady jej przyznawania mają teraz ulec zmianie, na skutek nowelizacji przepisów europejskiego prawa farmaceutycznego, znanej jako pakiet farmaceutyczny.  Autorzy pierwszego „Planu dla Chorób Rzadkich” celowo założyli, że „poprawa dostępu obejmuje zarówno leki innowacyjne (zarejestrowane i na etapie rozwoju/ badań klinicznych przed dopuszczeniem do obrotu), bez względu na status leku sierocego, jak i leki od dawna dostępne, w tym stosowane poza zarejestrowanymi wskazaniami.  Status leku sierocego i związana z nim ochrona rynkowa/handlowa w zamyśle ustawodawstwa unijnego miały \\fstymulować zainteresowanie przemysłu farmaceutycznego inwestowaniem w badania i produkcję leków do terapii chorób rzadkich. Status ten nadawany jest tylko na wniosek podmiotu zainteresowanego. Status leku sierocego jest jedynie kategorią ekonomiczną, nie epidemiologiczno-kliniczną, a fakt jego utraty nie zmienia właściwości terapeutycznych leku. Tymczasem na przykład możliwość złożenia wniosku o refundację z MCDA mogłaby pomóc w uzyskaniu refundacji dla różnych leków stosowanych w chorobach rzadkich, nie tylko tych, które aktualnie posiadają status leku sierocego.\\t\\fUwaga niezasadna Projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Konieczność ustanowienia definicji leku sierocego wynika z faktu, że omawiana WAD dotyczy wyłącznie leków o statusie leku sierocego, które są stosowane w chorobach rzadkich. Zaproponowana (art. 1 pkt 1 lit. b projektu) definicja leku sierocego jest zgodna z rozporządzeniem nr 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. UE). Niniejsza zmiana wiąże się z zaproponowanym dodaniem definicji wielokryterialnej analizy decyzyjnej (art. 1 pkt 1 lit. e projektu w zakresie pkt. 26b). Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce zdrowotnej. Stanowi to również wypełnienie postulatów, które \\fznalazły się w pierwotnej wersji ramowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 1 lit. c dotyczący art. 2 pkt 11b ustawy refundacyjnej\\t11b) lek sierocy – produkt leczniczy zarejestrowany w leczeniu choroby rzadkiej lub ultrarzadkiej zgodnie z przepisami prawa europejskiego.\\tPosłużenie się pojęciem \\\"leku sierocego\\\" ogranicza katalog produktów, które mogłyby skorzystać z MCDA. Status leku sierocego uzyskują bowiem substancje czynne, które zostały zarejestrowane w danej jednostce chorobowej jako pierwsze albo wykazały wyższość nad już zarejestrowanym produktem. Część leków zaprojektowanych do leczenia chorób rzadkich/ ultrarzadkich jest rejestrowana w oparciu o badania jednoramienne, co uniemożliwia uzyskanie statusu leku sierocego w przypadku, gdy jest to kolejna cząsteczka zarejestrowana w tej chorobie.  Proponowana zmiana niesie za sobą konieczność zmiany innych przepisów w tym np. art. 2 pkt 26b ustawy \\tUwaga niezasadna Projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Konieczność ustanowienia definicji leku sierocego wynika z faktu, że omawiana WAD dotyczy wyłącznie leków o statusie leku sierocego, które są stosowane w chorobach rzadkich. Zaproponowana (art. 1 pkt 1 lit. b projektu) definicja leku sierocego jest zgodna z rozporządzeniem nr 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. UE). Niniejsza zmiana wiąże się z \\fzaproponowanym dodaniem definicji wielokryterialnej analizy decyzyjnej (art. 1 pkt 1 lit. e projektu w zakresie pkt. 26b). Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce zdrowotnej. Stanowi to również wypełnienie postulatów, które znalazły się w pierwotnej wersji ramowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich.\\n\\tRada Chorób Rzadkich\\tArt. 1 pkt 1 lit. c dotyczący art. 2 pkt 11b ustawy refundacyjnej\\tDlatego zwracam się z wnioskiem o modyfikację zapisów ustawy i dopuszczenie analizy wielokryterialnej do leków „stosowanych w chorobach rzadkich”, a nie wyłącznie leków posiadających status „leku sierocego”.\\tW imieniu Rady Chorób Rzadkich pragnę zgłosić uwagę do opublikowanego Projektu ustawy o zmianie ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych oraz niektórych innych ustaw. Jako środowisko z zadowoleniem przyjęliśmy opublikowany projekt, który wychodzi naprzeciw wielu postulatom zgłaszanym przez środowiska eksperckie i pacjenckie. Nadal zaledwie ok. 3% chorób rzadkich, to choroby w których istnieją dedykowane terapie. Także dostęp do terapii o działaniu objawowym w zróżnicowanej grupie chorób rzadkich jest utrudniony. Jednym z rozwiązań postulowanych w odniesieniu do chorób rzadkich w postępowaniach refundacyjnych było ułatwienie dostępu do leków obejmujące wszystkie leki zarejestrowane na choroby rzadkie, a nie tylko „leki sieroce”. \\fTermin leki sieroce dotyczy leków do stosowania w terapii chorób rzadkich, które w ramach procedury dopuszczenia do obrotu na terenie Unii Europejskiej, na wniosek podmiotu odpowiedzialnego, podlegają ochronie handlowej przez nadanie im na okres 10 lat statusu leku sierocego. Po upływie tego okresu tracą status leku sierocego i w konsekwencji ochronę rynkową. Pozostają jednak nadal lekami przeznaczonymi do terapii chorób rzadkich. Status leku sierocego i związana z nim ochrona rynkowa/handlowa w zamyśle ustawodawstwa unijnego miały stymulować zainteresowanie przemysłu farmaceutycznego inwestowaniem w badania i produkcję leków do terapii chorób rzadkich. Status leku sierocego jest jedynie kategorią ekonomiczną, nie epidemiologiczno-kliniczną, a fakt jego utraty nie zmienia właściwości terapeutycznych leku. Według cokwartalnego raportu ORPHANET, w Unii Europejskiej na początku 2020 r. było 105 leków zarejestrowanych do stosowania w terapii chorób rzadkich ze statusem leku sierocego oraz 236 bez takiego statusu, spośród których odpowiednio 21 i 102 refundowano w Rzeczypospolitej Polskiej 20). Łącznie zarejestrowano 341 leków do stosowania w terapii chorób rzadkich, z których w Rzeczypospolitej Polskiej refundowano 123. Poprawa dostępu do leków w chorobach rzadkich powinna uwzględniać zarówno leki innowacyjne (zarejestrowane i na etapie rozwoju/ badań klinicznych przed \\fdopuszczeniem do obrotu), bez względu na status leku sierocego, jak i leki od dawna dostępne, w tym stosowane poza zarejestrowanymi wskazaniami. Projekt ustawy w zakresie dotyczącym chorób rzadkich używa tylko pojęcia „lek sierocy”, zgodnie z brzmieniem art. 3 Rozporządzenia 141/2000 Rady UE, a nie „lek zarejestrowany do stosowania w terapii chorób rzadkich”, jak stosowano w pierwszym „Planie dla Chorób Rzadkich” (m.in. s. 37). Jest to daleko idące zawężenie, mogące mieć negatywny wpływ na dostęp do terapii w chorobach rzadkich.\\t\\fUwaga niezasadna Projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Konieczność ustanowienia definicji leku sierocego wynika z faktu, że omawiana WAD dotyczy wyłącznie leków o statusie leku sierocego, które są stosowane w chorobach rzadkich. Zaproponowana (art. 1 pkt 1 lit. b projektu) definicja leku sierocego jest zgodna z rozporządzeniem nr 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. UE). Niniejsza zmiana wiąże się z zaproponowanym dodaniem definicji wielokryterialnej analizy decyzyjnej (art. \\f1 pkt 1 lit. e projektu w zakresie pkt. 26b). Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce zdrowotnej. Stanowi to również wypełnienie postulatów, które znalazły się w pierwotnej wersji ramowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich.\\n\\tWiseMed – agencja marketingu medycznego\\tArt. 1 pkt 1 lit. c dotyczący art. 2 pkt 11b  Oraz art. 2pkt 13a ustawy refundacyjnej \\tMając na celu zapobiegnięcie wystąpieniu jakichkolwiek wątpliwości interpretacyjnych, proponujemy, aby: 1. Art. 1 pkt 1 lit e projektowanej ustawy przyjął brzmienie: „17aa) prezentacja wyrobu medycznego – wyrób medyczny tego samego wnioskodawcy mający takie samo przewidziane zastosowanie oraz właściwości i przeznaczony do używania w takich samych warunkach przez tego samego rodzaju użytkownika, w przypadku którego pomija się wielkość opakowania i kształt;”,  albo inne zbliżone, które uwzględni przedstawione dalej uwagi. 2. Aktualizację definicji odpowiednika wyrobu medycznego (art. 2 pkt 13 lit c) ustawy refundacyjnej) tak, aby przepis ten przyjął kształt: „c) wyrobu medycznego – \\fwyrób medyczny mający takie samo przewidziane zastosowanie oraz właściwości i jest przeznaczony do używania w takich samych warunkach przez tego samego rodzaju użytkownika;”,  albo inne zbliżone, które uwzględni przedstawione dalej uwagi.\\t\\fChociaż wyróżnienie osobnej definicji prezentacji dla wyrobów medycznych wydaje się uzasadnione, proponowane przez Projektodawcę brzmienie art. 2 pkt 17aa nadal pozostawia pewne uzasadnione wątpliwości: 1. Pojęcie dawki użyte w taki sposób jak w pkt 17a jest właściwe dla produktów leczniczych. W odniesieniu do wyrobów mogłoby ono odnosić się wyłącznie do wyrobów medycznych, które zawierają jako integralną część substancję, która w przypadku użycia osobno mogłaby być uważana za produkt leczniczy, przy czym określałoby ono wyłącznie dawkę tej substancji i nie dotyczyłoby pozostałych elementów wyrobu medycznego. Z tego powodu zasadne wydaje się wykreślenie dawki z przedmiotowej definicji. 2. Zgodnie z art. 2 pkt 12 MDR, „przewidziane zastosowanie” oznacza użycie, do którego wyrób jest \\fprzeznaczony zgodnie z danymi podanymi przez producenta na etykiecie, w instrukcji używania lub w materiałach lub oświadczeniach promocyjnych lub sprzedażowych oraz określonymi przez producenta w ocenie klinicznej. Definicja ta nie odnosi się do tego, kto oraz w jakich warunkach stosuje wyrób medyczny. Istnieje możliwość, że dwa różne wyroby medyczne tego samego wnioskodawcy mogą być przeznaczone do tego samego użycia, ale przez innego rodzaju użytkowników (np. urządzenia do pomiaru parametrów fizjologicznych mogą być przeznaczone do samodzielnego użycia przez laika albo przez profesjonalistę medycznego) i w różnych warunkach używania (np. w szpitalu, pokoju zabiegowym albo w dowolnym miejscu, w tym w domu pacjenta). Chociaż Projektodawca włączył do definiensa także pojęcie właściwości wyrobu medycznego, wydaje się, że proponowane przez niego brzmienie przepisu nadal może pozostawiać pewne wątpliwości interpretacyjne, gdyż pojęcie to jest nieostre i w niektórych przypadkach może wymagać dodatkowej analizy mającej na celu rozróżnienie między takimi samymi a różnymi właściwościami wyrobu. Na przykład w sytuacji, w której kolory, wzór i symbole wyrobu mogą mieć wartość inną niż estetyczną. Z tego względu uzasadnionym wydaje się uwzględnienie w definicji prezentacji wyrobu medycznego również odwołania do warunków używania oraz przewidzianego użytkownika wyrobu. Podobne wątpliwości budzić może \\fustanowiona na potrzeby ustawy refundacyjnej definicja odpowiednika wyrobu medycznego dla ustawy refundacyjnej. Z tego względu analogiczna zmiana wydaje się być uzasadniona w odniesieniu do art. 1 pkt 13 lit c ustawy refundacyjnej.\\t\\fUwaga niezasadna W przypadku wyrobów medycznych objętych refundacją jako „dawkę” rozumiana jest np. powierzchnia opatrunku, co jest użyteczne w ustalaniu sprawiedliwych warunków cenowych. Jest to również ważny element pod kątem danych identyfikujących produkt.     W odniesieniu do punktu drugiego przedmiotowej uwagi należy zauważyć, że wyroby medyczne objęte refundacją co do zasady mogą być stosowane samodzielnie przez pacjenta w warunkach domowych.  Ustawa o refundacji umożliwia objęcie refundacją wyrobu medycznego w ramach kategorii dostępności „w aptece na receptę” oraz ustalenie ceny zbytu netto w przypadku innych świadczeń gwarantowanych. \\n\\tNaczelna Izba Aptekarska\\tArt. 1 pkt 1 lit. f dotyczący art. 2 pkt 26a ustawy refundacyjnej\\tnależy rozważyć, czy pojęcie „utensylia recepturowe” powinno - ze względów merytorycznych – obejmować opakowanie bezpośrednie leku recepturowego.\\tProponowana w art. 2 pkt 26a definicja „utensyliów recepturowych”, która łączy w jednej kategorii naczynia i przyrządy apteczne oraz opakowanie bezpośrednie leku recepturowego, jest niezgodna z wiedzą farmaceutyczną i wprowadza błąd pojęciowy. Zgodnie z ugruntowaną praktyką farmaceutyczną oraz Farmakopeą Polską, utensylia recepturowe to narzędzia, sprzęty i naczynia służące do sporządzania leku recepturowego, takie jak moździerze, kolby miarowe, wagi, mieszadła czy bagietki. Są to przedmioty wielokrotnego użytku wykorzystywane w procesie przygotowania leku, zgodnie z zasadami dobrej praktyki aptecznej oraz wymaganiami technologicznymi opisanymi m.in. w rozdziałach Receptura i Przygotowanie leków recepturowych Farmakopei. Natomiast opakowanie bezpośrednie to zgodnie z Farmakopeą, odrębna kategoria – są to pojemniki (np. butelki, słoiki, tuby), w które lek jest niezwłocznie po przygotowaniu dozowany i przechowywany, i które mają bezpośredni kontakt z produktem leczniczym. Opakowanie takie musi spełniać określone wymagania jakościowe, m.in. chemiczną obojętność i szczelność, ale nie uczestniczy w samym procesie sporządzania leku. \\fW świetle powyższego, łączenie utensyliów i opakowań bezpośrednich w jednej definicji jest niezgodne z zasadami farmacji praktycznej i naukowej.\\t\\fUwaga niezasadna Na potrzeby zapisów ustawy o refundacji nie ma konieczności rozgraniczania opakowań bezpośrednich leków recepturowych jako osobnej kategorii od utensyliów recepturowych.\\n\\tAmerykańska Izba Handlowa w Polsce/ Pracodawcy RP\\tArt. 1 pkt 1 lit. f dotyczący art. 2 pkt 26b ustawy refundacyjnej\\tpkt 26b proponujemy nadać następujące brzmienie: „26b) wielokryterialna analiza decyzyjna – analizę wieloczynnikową, która uwzględnia kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny, stanowiącą element analizy ekonomicznej dotyczącej leku sierocego stosowanego w chorobie rzadkiej, o której mowa w art. 25 pkt 14 lit. c tiret drugie, art. 25a pkt 14 lit. b, art. 26 pkt 2 lit. h;”\\t\\tW nawiązaniu do rozmowy podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca prosimy o rozważenie zastąpienia definicji leku sierocego definicją leku stosowanego w chorobie rzadkiej oraz pozostałych przepisów odnoszących się do tej definicji. Zgodnie z przepisem art. 3 rozporządzenia (WE) 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych status leku sierocego w EMA otrzymuje jedynie taki produkt leczniczy, dla którego można wykazać, że nie istnieje zadowalająca metoda diagnozowania, zapobiegania lub leczenia danego stanu chorobowego, oficjalnie dopuszczona na terytorium Unii Europejskiej, lub też, jeśli taka metoda istnieje, to produkt leczniczy przyniesie znaczące korzyści pacjentom cierpiącym na ten stan chorobowy. Kolejny lek stosowany w tej samej chorobie nie otrzyma już tego statusu. Możliwym jest więc scenariusz, w którym to drugi, a nie pierwszy zarejestrowany produkt leczniczy, jedyny posiadający status leku sierocego, będzie się ubiegać o refundację w Polsce jako pierwszy. Wówczas przyjmując zaproponowane brzmienie przepisów nie będzie możliwe zastosowanie dla niego analizy wielokryterialnej.  Możliwym jest również, że z różnych względów lek sierocy już nie będzie refundowany w Polsce, kiedy złożony zostanie wniosek dotyczący innego leku w danej chorobie \\frzadkiej. Z tego względu, zasadnym byłoby umożliwienia skorzystania z nowych regulacji nie tylko lekom sierocym, ale szerszej grupie leków – stosowanych w leczeniu chorób rzadkich. W Planie dla Chorób Rzadkich na lata 2021-2023 leki przeznaczone do terapii chorób rzadkich zostały zdefiniowane jako leki przeznaczone do leczenia chorób występujących z częstością niższą niż 5 na 10 000 osób w populacji, stąd zaproponowana przez KF AmCham definicja jest analogiczna. \\t \\tUzasadnienie Pracodawcy RP \\tProsimy o rozważenie zastąpienia definicji leku sierocego definicją leku stosowanego w chorobie rzadkiej oraz pozostałych przepisów odnoszących się do tej definicji. Nie zawsze lek sierocy stosowany w danej chorobie rzadkiej będzie pierwszym, dla którego złożony zostanie wniosek o objęcie refundacją. Możliwym jest również, że z różnych względów lek sierocy już nie będzie refundowany w Polsce, kiedy złożony zostanie wniosek dotyczący innego leku w danej chorobie rzadkiej. Z tego względu, zasadnym byłoby umożliwienie skorzystania z nowych regulacji nie tylko lekom sierocym, ale szerszej grupie leków, tj. lekom stosowanym w leczeniu chorób rzadkich.\\t\\fUwaga niezasadna Projekt ustawy wprowadza wielokryterialną analizę decyzyjną (WAD)– analiza wieloczynnikowa, która uwzględnia w sposób systematyczny kryteria kosztowe oraz pozakosztowe wspomagające proces decyzyjny. Zgodnie z założeniami WAD w Polsce dedykowana będzie ocenie leków sierocych i stanowić będzie dodatkowy element analizy ekonomicznej. Konieczność ustanowienia definicji leku sierocego wynika z faktu, że omawiana WAD dotyczy wyłącznie leków o statusie leku sierocego, które są stosowane w chorobach rzadkich. Zaproponowana (art. 1 pkt 1 lit. b projektu) definicja leku sierocego jest zgodna z rozporządzeniem nr 141/2000 Parlamentu Europejskiego i Rady z dnia 16 grudnia 1999 r. w sprawie sierocych produktów leczniczych (Dz. Urz. UE L 18 z 22.01.2000, str. 1; Dz. Urz. UE). Niniejsza zmiana wiąże się z zaproponowanym dodaniem definicji wielokryterialnej analizy decyzyjnej (art. 1 pkt 1 lit. e projektu w zakresie pkt. 26b). Zapis został dodany w celu uwzględnienia WAD, jako jednego z elementów dossier refundacyjnego. Wprowadzenie WAD do oceny leków refundowanych wynika z potrzeby zapewnienia bardziej kompleksowego, przejrzystego i sprawiedliwego procesu podejmowania decyzji w polityce zdrowotnej. Stanowi to również wypełnienie postulatów, które znalazły się w pierwotnej wersji \\framowego dokumentu Ministerstwa Zdrowia – Planu dla Chorób Rzadkich.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego/Polpharma\\tArt. 4a ustawy refundacyjnej\\tArt. 4a.  Przepis art. 4 nie dotyczy Wnioskodawcy uznanego za Partnera Bezpieczeństwa Lekowego.\\tDodanie art. 4a (wyłączenie paybacku) jest jednym z elementów proponowanego mechanizmu Partnera Bezpieczeństwa Lekowego. Mechanizm wspierania produkcji w Polsce za pomocą instrumentów prawa refundacyjnego, oprócz wspierania refundacji \\fkonkretnych produktów, powinien odnosić się także do samego wnioskodawcy.  Proponuje się więc dodatkowo mechanizm (w nowo dodanym art. 12a i 12b – zob. dalej), który zagwarantuje firmom wytwarzającym co najmniej 25% swoich leków refundowanych lub co najmniej 100 mln jednostek leków rocznie na terenie Polski – stabilizację ekonomiczną i możliwość rozwoju. Takie rozwiązanie realizuje potrzeby Ministerstwa Zdrowia – zapewnienie ciągłości dostaw leków, a jednocześnie resortów gospodarczych, skutkując zwiększeniem inwestycji oraz działalności badawczo-rozwojowej w Polsce. Oddziałuje też pozytywnie na bilans handlowy kraju, rynek pracy oraz zwiększa wpływy budżetowe z podatków i innych danin.   Podniesie to konkurencyjność naszego kraju w zakresie lokowania inwestycji związanych z produkcją farmaceutyczną, o co dziś zabiega wiele krajów UE. \\t\\t\\t\\fPoza zakresem nowelizacji \\tProponowane zmiany w projekcie zakładają coraz dalej idące preferencje dla polskich producentów leków w kraju. \\t \\t\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 2 lit. a tiret pierwsze dotyczący art. 6 ust.1 pkt 2a ustawy refundacyjnej\\tWobec powyższego postulujemy, aby zmiana w tym zakresie stała się przedmiotem odrębnych konsultacji, celem wypracowania sprawnego modelu dystrybucji, jednocześnie nie zatrzymując procedowania przedmiotowej nowelizacji.\\tIdea tzw. czwartej kategorii dostępności jest słuszna.  Mając jednak na uwadze zarówno propozycje zawarte w opublikowanej wersji projektu, jak i propozycje Ministra Zdrowia przedstawione na spotkaniu konsultacyjnym 2 czerwca 2025 r. dotyczące modelu dystrybucyjnego dla tej kategorii dostępności oraz dla programów lekowych - polegający na włączeniu do dystrybucji także aptek ogólnodostępnych, pragniemy wskazać, \\fże takie zmiany wymagają bardzo pogłębionej analizy. Przedstawione tam zagadnienia dotyczą wielu kwestii, w tym zasad dystrybucji, zasad stosowania cen, odpowiedzialności za prowadzenie terapii. zabezpieczenia zasad uczciwej konkurencji (a więc zagadnień, które nie dotyczą tylko ustawy refundacyjnej).  Takie kwestie powinny być przedyskutowane kompleksowo przez wszystkich interesariuszy, w tym pacjentów, lekarzy, przedstawicieli szpitali oraz AOSów, wnioskodawców, hurtownie farmaceutyczne, apteki, farmaceutów, płatnika publicznego, GIF oraz MZ. Wobec powyższego postulujemy, aby zmiana w tym zakresie stała się przedmiotem odrębnych konsultacji, celem wypracowania sprawnego modelu dystrybucji, jednocześnie nie zatrzymując procedowania przedmiotowej nowelizacji. Jednocześnie już w tym momencie pragniemy odnieść się kierunkowo do problemów, które zostały nakreślone przez Ministerstwo Zdrowia na spotkaniu konsultacyjnym 2 czerwca 2025 r. INFARMA stoi na stanowisku, że: •\\tmodel marży aptecznej polegający na podziale marży między MAH (Zwracamy uwagę, że MAH, w bardzo wielu przypadkach, w ogóle nie uczestniczy w fizycznym czy nawet finansowym przepływie produktu. W \\ftakim przypadku nie można mówić o marży MAHa. Czym innym jest marża tzw. hurtowni producenckiej, która prowadzi obrót, ale taka hurtownia (o ile czasem może być nawet wnioskodawcą refundacyjnym, to bardzo rzadko nie jest MAHem). a hurtownią generuje wiele problemów i nie powinien zostać wdrożony (m.in. z uwagi na problem ustalenia ile taka marża ma wynosić czy po jakiej cenie – od której liczona byłaby marża – powinno kupować się lek); •\\tprzedmiotem dystrybucji aptecznej w przypadku programów lekowych i czwartej kategorii dostępności powinny być wszystkie leki (nie tylko leki generyczne); •\\tkwestie cen powinny być uregulowane w taki sposób, aby poszanować tajemnicę przedsiębiorstwa wnioskodawców dotyczącą RSS i ceny efektywnej. Uzasadnia to tym bardziej postulat INFARMA, aby dyskusja w tym zakresie była otwarta i kontynuowana na dalszym etapie prac rządowych nad nowelizacją.\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 2 lit. a tiret pierwsze dotyczący art. 6 ust.1 pkt 2a ustawy refundacyjnej\\tpostulujemy, aby przy kwalifikowaniu produktów do nowej kategorii dostępności uwzględniać w tej kategorii całe grupy produktów o podobnym działaniu i stosowanych w tym samym wskazaniu, które były dotychczas refundowane w tym samym programie lekowym.\\tArt. 6 ust. 2a – nowa kategoria dostępności refundacyjnej  Co do zasady, popieramy wprowadzenie nowej kategorii dostępności refundacyjnej, która wpisuje się w promowaną od dawna przez Izbę Gospodarczą „FARMACJA POLSKA” ideę odwrócenia piramidy świadczeń i przez to zwiększenia dostępności refundowanych terapii dla pacjentów. \\fChcielibyśmy jednak zwrócić uwagę na ryzyko stworzenia nierównych warunków konkurencji na rynku dla producentów, które naszym zdaniem może wynikać z przyjęcia kryterium kwalifikacji do nowej kategorii dostępności leków, bazującego na wysokim poziomie generyzacji danej terapii – a na takie kryterium wskazuje uzasadnienie projektu nowelizacji ustawy o refundacji. W sytuacji, gdy substancja o wysokim poziomie generyzacji, refundowana obecnie w ramach programu lekowego razem z innymi produktami, stosowanymi w tym samym wskazaniu terapeutycznym (ICD-10) i mającymi podobny mechanizm działania, zostanie jako jedyna wyjęta do nowej kategorii dostępności, leki z tą substancją czynną w naturalny sposób będą znacznie szerzej stosowane przez pacjentów niż pozostałe, konkurencyjne preparaty.  Może to prowadzić do stworzenia konkurencyjnym wnioskodawcom nierównych warunków konkurencji na rynku,\\t\\fUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tNaczelna Izba Aptekarska  \\tArt. 1 pkt 2 lit. a tiret pierwsze dotyczący art. 6 ust.1 pkt 2a ustawy \\frefundacyjnej\\t\\f„- po pkt 2 dodaje się pkt 2a w brzmieniu: „2a) \\tlek stosowany w chorobach innych niż onkologiczne w ramach udzielania świadczeń, o których mowa w art. 15 ust. 2 pkt 2 i 3 ustawy o świadczeniach, lub w ramach sprawowania opieki farmaceutycznej, o której mowa w art. 4 ust. 2 ustawy z dnia 10 \\fgrudnia 2020 r. o zawodzie farmaceuty - we wskazaniu określonym stanem klinicznym (lek w ramach ambulatoryjnej opieki specjalistycznej lub opieki farmaceutycznej),”;  W konsekwencji, proponuje się zmianę w art. 3 i art. 15 ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych.\\t\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolskie Towarzystwo Farmakoekonomiczne\\tArt. 1 pkt 1 lit. b tiret pierwsze dotyczący art. 2 ust.1 pkt 4a ustawy refundacyjnej\\t Doprecyzowanie definicji ceny efektywnej (Art. 2 pkt 4a UR) poprzez jednoznaczne wskazanie, które instrumenty dzielenia ryzyka są uwzględniane w jej kalkulacji.  \\t Doceniamy zmianę w definicji ceny efektywnej zaproponowanej przez Ministerstwo Zdrowia i rozwiniętej w uzasadnieniu „Tym samym, do wyliczeń ceny efektywnej wykorzystywane powinny być wyłącznie te instrumenty dzielenia ryzyka, które w sposób bezpośredni oraz możliwy do jednoznacznego wyliczenia wpływają na koszt jednego opakowania leku lub koszt leczenia jednego pacjenta”.  • W pełni popieramy to podejście, ale warto byłoby doprecyzować je w samych zapisach ustawy a nie jedynie w uzasadnieniu do ustawy, poprzez wskazanie wprost, że dotyczy to instrumentów dzielenia ryzyka wskazanych w pkt 2 i 4 (tzw. „CHB” oraz tzw. „payback”). Wiele instrumentów dzielenia ryzyka może być związana z efektem klinicznym lub zmieniać się w zależności  od wielkości sprzedaż, dlatego trudno byłoby ustalić jak efektywnie wyliczać ceny w takich przypadkach.  \\tUwaga zasadna Nowa propozycja w projekcie: 4a) cena efektywna – cena leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego odpowiadająca wysokości kosztu ponoszonego przez podmiot zobowiązany do finansowania świadczeń ze środków publicznych z uwzględnieniem instrumentów dzielenia ryzyka, o których mowa w art. 11 ust. 5 pkt 2 lub 4;”\\n\\tPolskie Towarzystwo Reumatologiczne \\tart.1 pkt 2 lit. a tiret drugie projektu \\fodnoszący się do art. 6 ust. 1 pkt 4 ustawy refundacyjnej\\t\\fWnioskujemy o zmianę art. 6 ust. 1 pkt 4 w związku z błędem redakcyjnym.   \\fProponowany zapis nie uwzględnia pkt 2a – tzw. „czwartej kategorii dostępności refundacyjnej”.  Proponujemy zatem powrót do poprzedniego brzmienia art. 6 ust. 1 pkt 4 ustawy:  „4) lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny stosowany w ramach udzielania świadczeń gwarantowanych, innych niż wymienione w pkt 1 – 3.”\\t\\fBłąd redakcyjny.\\tUwaga bezprzedmiotowa  \\fProjektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tart.1 pkt 2 lit. a tiret drugie projektu odnoszący się do art. 6 ust. 1 pkt 4 ustawy refundacyjnej\\t1. Ustala się kategorię dostępności refundacyjnej: 1) lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny dostępny w aptece na receptę: a) w całym zakresie zarejestrowanych wskazań i przeznaczeń, b) we wskazaniu określonym stanem klinicznym; 2) lek, środek spożywczy specjalnego przeznaczenia żywieniowego stosowany w ramach programu lekowego; 2a) lek stosowany w chorobach innych niż onkologiczne w ramach udzielania świadczeń, o których mowa w art. 15 ust. 2 pkt 2 i 3 ustawy o świadczeniach,:  a) w całym zakresie zarejestrowanych wskazań i przeznaczeń, b) we wskazaniu określonym stanem klinicznym; 3) lek stosowany w ramach chemioterapii: a) w całym zakresie zarejestrowanych wskazań i przeznaczeń, b) we wskazaniu określonym stanem klinicznym; \\f4) lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny stosowany w ramach udzielania świadczeń gwarantowanych, innych niż wymienione w pkt 1, 2, 2a i 3. \\t\\fLeki z nowej kategorii dostępności (art. 6 ust. 1 pkt 2a) powinny być traktowane podobnie jak leki z pozostałych kategorii dostępności (apteka, chemioterapia, programy lekowe) – tzn. tak jak inne leki refundowane, powinny być wyłączone z możliwości objęcia ich równocześnie kategorią dostępności z art. 6 ust. 1 pkt 4. Proponujemy też, aby nie ograniczać z góry możliwości refundacji leków w ramach nowej kategorii dostępności w całym zakresie zarejestrowanych wskazań i przeznaczeń. Taką możliwość stosuje się w odniesieniu do leków o kategorii dostępności w aptece na receptę, jak i chemioterapii. Nie ma powodu, by z góry wykluczać ją w przypadku leków z nowej kategorii dostępności. Ostateczne o zakresie refundowanych wskazać decydować będzie i tak Minister Zdrowia.\\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej                \\n\\tFederacja Przedsiębiorców Polskich\\tArt.1 pkt 2 lit. a tiret drugie projektu odnoszący się do art. 6 ust. 1 pkt 4 ustawy)\\tWnioskujemy o zmianę art. 6 ust. 1 pkt 4 w związku z błędem redakcyjnym.   Proponowany zapis nie uwzględnia pkt 2a – tzw. „czwartej kategorii dostępności refundacyjnej”.  Proponujemy zatem powrót do poprzedniego brzmienia art. 6 ust. 1 pkt 4 ustawy:  „4) lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny stosowany w ramach udzielania świadczeń gwarantowanych, innych niż wymienione w pkt 1 – 3.”\\tProponowana zmiana uwzględnia tzw. „czwartą kategorię dostępności refundacyjnej”. \\tUwaga bezprzedmiotowa  Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolskie Towarzystwo Leczenia Ran\\tArt.1 pkt 2 lit. b projektu odnoszący się do projektowanego art. 6 ust. 2b ustawy\\t„2b. Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1,wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2 dla leku lub środka spożywczego specjalnego przeznaczenia żywieniowego.”\\tZarząd Polskiego Towarzystwa Leczenia Ran wnosi o wykreślenie z projektu ustawy zapisu o możliwości wskazywania specjalizacji lekarza uprawnionego do określania poziomu refundacji oraz okresu terapii, w odniesieniu do wyrobów medycznych.  W leczeniu ran niezwykle ważne miejsce zajmuje stosowanie na ranę nowoczesnych materiałów o statusie opatrunku specjalistycznego. W Polsce nie istnieje wyodrębniona grupa specjalistów zajmujących się leczeniem ran, chorzy z raną zatem trafiają do różnych placówek i lekarzy bądź pielęgniarek o różnych specjalnościach. \\fBiorąc pod uwagę, że ranę trudno gojącą się posiada około miliona Polaków(!), Polskie Towarzystwo Leczenia Ran dokłada od lat wszelkich starań, aby szkolić i poszerzać wciąż nieproporcjonalnie wąską grupę lekarzy i pielęgniarek chcących nieść pomoc tym chorym, w warunkach braku zorganizowanego przez Państwo systemu opieki nad pacjentem z raną.  W tym kontekście koncepcja administracyjnego ograniczenia uprawnień wystawiania recept refundowanych na wyroby medyczne pozostaje w sprzeczności z wysiłkami naszego Towarzystwa i dobrem pacjentów, a ewentualne migracje chorych od „uprawnionego” do „nieuprawnionego” lekarza stanowiłyby istotne obciążenie dla systemu opieki zdrowotnej.\\t\\fUwaga częściowo zasadna Z projektu usunięto zapis o wskazywaniu specjalizacji lekarza uprawnionego do określania poziomu refundacji. \\n\\tPolskie Towarzystwo Reumatologiczne \\tArt.1 pkt 2 lit. b projektu odnoszący się do projektowanego art. 6 ust. 2b ustawy\\tWnioskujemy o zmianę dodanego w art. 6 ustawy refundacyjnej ust. 2b.  Proponujemy następujące brzmienie zapisu art. 6 ust. 2b:  „2b. Minister właściwy do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, dla refundowanego leku w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1.”.\\tWskazanie specjalizacji lekarskiej wymaganej do preskrypcji danego leku z uwagi na jego zastosowanie kliniczne jest dobrym rozwiązaniem, które może otworzyć drogę do refundacji leków biologicznych i syntetycznych celowanych w aptekach ogólnodostępnych.   Wnioskowana zmiana ma na celu usunięcie wskazywania liczby opakowań leku i czasu leczenia. Taki zapis jest niekorzystny dla pacjentów stosujących leki obecnie refundowane w programach lekowych – biologiczne i syntetyczne \\fcelowane. Konieczność odbierania przez pacjenta leku co miesiąc z apteki może utrudniać aktywność życiową i zawodową części chorych. W przypadku braku możliwości odbioru leku w ustalonym przez regulatora czasie, ciągłość leczenia zostanie zaburzona, a efekty leczenia mogą być gorsze. Leki dawkowane są w różnych interwałach – codziennie, co tydzień, co 2 tygodnie, co 4 tygodnie, co miesiąc, co 8 tygodni, co 12 tygodni, a dane opakowanie leku wystarcza także na leczenie przez różny czas. Ustalenie uniwersalnego okienka czasowego na odbiór kolejnej partii leku może być trudne.   Rozwiązanie ograniczające możliwość wydania leku na jeden miesiąc nie funkcjonuje w innych przypadkach, np. u pacjentów z cukrzycą stosujących kosztowne w refundacji leki biologiczne, jak insuliny czy analogi GLP-1, co może rodzić pytanie o nierówne traktowanie różnych grup pacjentów.\\t\\fUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich \\fpacjentów, z uwzględnieniem personalizacji terapii. \\n\\tOkręgowa Izba Aptekarska w Krakowie\\tArt. 1 pkt 2 lit. b projektu \\tWykreślenie proponowanej zmiany z nowelizacji\\tProponowana zmiana to nieuzasadnione ograniczenie prawa osób uprawnionych do wypisywania recept do ich wystawiania. Wprowadzane ograniczenie może powodować problemy z dostępem do leków dla pacjentów. Dodatkowo może powodować, że pacjent uprawniony do otrzymania leku refundowanego, nie otrzyma go z właściwą odpłatnością.  Kolejny aspekt, który należy podkreślić, to możliwe przeniesienie \\fodpowiedzialności za weryfikację uprawnień do wystawienia recepty na apteki. Spowoduje to dodatkową pracę biurokratyczną w aptece oraz dodatkowo zmusi farmaceutę do podważania kompetencji lekarza do wystawienia recepty refundowanej dla danego pacjenta. Jest to sytuacja niezdrowa i niepożądana. Całość zmiany może mieć negatywne skutki społeczne na wielu płaszczyznach.\\t\\fUwaga uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. \\fW związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tPolska Izba Przemysłu Farmaceutycznego i Wyrobów Medycznych  POLFARMED\\tart. 1 pkt 2 lit. b odnoszący się do art. 6 ust. 2b \\tMinister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2, w odniesieniu do leku, który wcześniej był refundowany w kategorii dostępności, o której mowa w ust. 1 pkt 2.\\tZgodnie z uzasadnieniem wprowadzenia tego przepisu, istnieje potrzeba ograniczenia swobody preskrypcyjnej, w przypadku leku, który wcześniej był dostępny w programie lekowym, a został umieszczony na liście aptecznej. Nie ma natomiast żadnego uzasadnienia, aby podobne ograniczenia dotyczyły pozostałych leków z listy aptecznej. Proponujemy rezygnację z tego przepisu lub jego ograniczenie jedynie do leków, które wcześniej były dostępne w programach lekowych.\\tUwaga częściowo uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tOgólnopolska Izba Gospodarcza Wyrobów Medycznych POLMED\\tArt. 1 pkt 2 lit. b odnoszący się do art. 6 ust. 2b\\tpo ust. 2a dodaje się ust. 2b w brzmieniu:  „2b. Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz \\fokreślenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2 dla leku lub środka spożywczego specjalnego przeznaczenia żywieniowego.”,\\t\\fProponowana zmiana nie powinna mieć zastosowania do wyrobów medycznych. Wyroby medyczne znajdujące się na liście refundacyjnej (opatrunki, paski do glukometrów i igły do penów) charakteryzują się tym, że mają bardzo szerokie wskazania i w praktyce stosowane są w szerokim spektrum jednostek chorobowych. Z uwagi na powyższe, wskazywanie lekarzy z \\fkonkretną specjalizacją właściwą ze względu na wskazania wyrobu medycznego, którzy byliby uprawnieni do naniesienia poziomu odpłatności, określania liczby opakowań lub okresu terapii w naszej ocenie nie ma powinna mieć zastosowania przy wyrobach medycznych, gdyż należałoby wskazać bardzo szeroki zakres specjalizacji, co z kolei mija się z celem wprowadzania ww. zmiany.\\t\\fUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia \\fżywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 2 lit. b projektu odnoszący się do art. 6 ust. 2b ustawy refundacyjnej\\tSkreślić 2b. Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2. alternatywnie 2b. Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2 i 2a. alternatywnie \\f2b. Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust. 1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 –  i 2a, o ile takie ograniczenia wynikają z decyzji o objęciu refundacją. [połączone ze zmianami do art. 11 ust. 2, art. 18 oraz art. 25 UR]\\t\\fNaszym zdaniem nie ma powodu do ograniczenia uprawnień preskrypcji lekarskiej.  Takie działanie idzie w odwrotnym kierunku niż ostatnie działania rządu i ustawodawcy dotyczące leków „65+” oraz „18-”, gdzie na skutek nowelizacji, która weszła w życie 14 lutego 2025 r., wszyscy lekarze są uprawnieni do uwzględniania na recepcie tych dodatkowych uprawnień. Warto podkreślić, że obecnie leki refundowane mogą przepisywać wszyscy lekarze. W kontekście odwróconej piramidy świadczeń niezasadne jest więc wprowadzanie przepisów, które będą prowadzić do zwiększenia liczby wizyt w AOS kosztem POZ. Co więcej, jeżeli pacjent rozpoczął terapię refundowaną powinien mieć zapewnioną możliwość jej kontynuacji w ramach refundacji. Istnieje ryzyko, że pacjent będzie miał przerwę w dostępie do refundowanego leczenia ze względu na brak możliwości dostania się na wizytę do specjalisty wskazanego w Obwieszczeniu i tym samym będzie \\fzmuszony do zakupienia leku bez refundacji na podstawie np. recepty wydanej przez lekarza POZ lub przerwie terapię ze względu na zbyt wysoki koszt leku. Alternatywnie prosimy o rozważenie takiej zmiany, aby ograniczenie dotyczące preskrypcji miało zastosowanie tylko do leków z programów lekowych oraz nowej kategorii dostępności refundacyjnej. Skoro w tych dwóch przypadkach jest rozważane (jak wskazano na spotkaniu konsultacyjnym z dnia 2 czerwca 2025 r.) „przeniesienie” terapii ze szpitala czy AOS do domu (co miałoby być powiązane z wystawianiem specjalnego recepty) to takie ograniczenie byłoby uzasadnione, z uwagi na specyfikę takiego modelu udzielania świadczeń. Nie ma jednak żadnego uzasadnienia, aby ograniczać preskrypcję leków o kategorii dostępności wskazanej w art. 6 ust. 1 pkt 1 (tj. tzw. „leków aptecznych”). Wprowadzenie tych przepisów do refundacji aptecznej będzie stanowiło istotne ograniczenie w dostępie pacjentów do refundowanej terapii. Wprowadzenie proponowanych zapisów w zakresie wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności spowoduje wydłużenie kolejek do lekarzy danej specjalizacji tylko po to, aby uzyskać pierwszą lub kolejną receptę na stosowaną terapię.  Dodatkowo w przypadku leków aptecznych, nie występują przesłanki na \\fewentualne uzasadnienie ograniczenia specjalizacji, jak w przypadku programów lekowych czy nowej kategorii dostępności (choćby z uwagi na brak kryteriów włączenia, a także tańsze i mniej specjalistyczne leki). Ważnym w tym kontekście jest także wprowadzane niniejszą nowelizacją rozwiązanie, że wszyscy lekarze otrzymają dostęp do historii farmakoterapii pacjenta (jak to jest obecnie w lekach „65+” oraz „18-”). Wobec tego, że lekarz będzie wiedział czy, a jeżeli tak to ile leków otrzymał ostatnio pacjent, to nie ma potrzeby ograniczania uprawnienia preskrypcyjnego tylko do niektórych lekarzy. Jeszcze inną alternatywą, którą dajemy pod rozwagę jest pozostawienie takiego rozwiązania, jednak z zastrzeżeniem że stanowiłoby to element wniosku i decyzji refundacyjnej, a więc byłoby negocjowalne z wnioskodawcą. Dzięki temu wnioskodawca wiedziałby czy może się spodziewać takich zmian, co jest istotne, gdyż szacunki dotyczące ilości przepisywanych (stosowanych) leków mają również wpływ na zobowiązania cenowe oraz RSSowe firm.\\t\\fUwaga częściowo uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tNaczelna Rada Lekarska\\tArt. 1 pkt 2 lit. b projektu odnoszący się do art. 6 ust. 2b ustawy refundacyjnej\\tW zakresie projektowanych zmian w ustawie o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych zastrzeżenia budzi proponowana zmiana w art. 6 ust. 2b. Ten nowy przepis przewiduje, że Minister do spraw zdrowia będzie mógł określić w wykazie leków refundowanych wskazanie specjalizacji lekarskiej \\fwymaganej do naniesienia określonego poziomu odpłatności. Z przepisu tego wynika, że Minister Zdrowia będzie mógł wskazać w wykazie leków refundowanych specjalizacje lekarskie, których posiadanie będzie warunkowało wystawienie recepty z określonym poziomem odpłatności leku.\\t\\fOdnosząc się do tej propozycji samorząd lekarski stoi na stanowisku, że nie należy różnicować uprawnień poszczególnych grup lekarzy do przepisania określonego leku czy ustalania określonego poziomu odpłatności. Należy przypomnieć, że Prezydium Naczelnej Rady Lekarskiej w stanowisku nr 53/24/P-IX z dnia 12 lipca 2024 r. było przeciwne różnicowaniu \\fuprawnień lekarzy do wystawiania recepty na darmowe leki dla pacjentów w wieku powyżej 65. roku życia oraz dla pacjentów w wieku poniżej 18. roku życia – który wynikał z ówczesnego brzmienia art. 43a ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych. Ograniczenia preskrypcyjne oznaczające, że nie każdy lekarz może przepisać uprawnionemu pacjentowi receptę z określonym poziomem odpłatności, zwykle skutkują tym, że pacjent dla uzyskania leku z należną mu odpłatnością musi korzystać z porady lekarskiej dwóch lekarzy.  Samorząd lekarski stoi na stanowisku, że uprawnienie do zaopatrzenia w leki z odpowiednią refundacją przysługuje pacjentowi. Dostęp do refundowanych leków to prawo pacjenta, a nie przywilej lekarza. Wobec tego każdy lekarz powinien być upoważniony, aby wystawić pacjentowi receptę na ten lek z odpłatnością taką, jaka należy się pacjentowi. Nie ma uzasadnienia kierowanie pacjenta na kolejną wizytę do lekarza, tylko po to, aby ten drugi lekarz wystawił receptę.   Samorząd lekarski z zadowoleniem przyjął niedawną nowelizację art. 43a ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych (ustawa z dnia 5 grudnia 2024 r. o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw – Dz.U. z 2025 r. poz. 129), w której ustanowiono zasadę, że wszyscy lekarze, niezależnie od miejsca pracy i wykonywania zawodu w ramach umowy \\fz NFZ, mają uprawnienie preskrypcyjne w zakresie darmowych leków dla pacjentów powyżej 65. roku życia i poniżej 18. roku życia. Niezrozumiałe jest, dlaczego od zasady tej ustawodawca zamierza obecnie odstąpić.  \\t\\fUwaga częściowo uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka \\fspożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii. \\n\\tBusiness Centre Club/ Związek Aptek Franczyzowyc/ Pracodawcy RP\\tArt. 1 pkt2 lit. b projektu odnoszący się do art. 6 ust 2b ustawy refundacyjnej\\tWykreślenie proponowanych zmian\\tJest to zbędne ograniczenie możliwości wystawianie recepty przez osoby uprawnione. Może to powodować utrudniony dostęp do leków i leczenia. Dodatkowo rodzi to ryzyko przerzucenia obowiązku kontroli wystawionych recept na osoby realizujące takie recepty. Propozycja ta rodzi kolejne ryzyko pojawienia się zbędnej bariery biurokratycznej, która może mieć negatywne skutki społeczne.  Uzasadnienie Związek Aptek Franczyzowych W sytuacji pogłębiającego się problemu z dostępem do osób uprawnionych do wystawiania recept, oraz w obliczu dynamicznie starzejącego się społeczeństwa propozycja to wydaje się taką, która spowoduje powstanie kolejnych trudnych barier w dostępie pacjentów do systemu ochrony zdrowia.  Oczywistym jest fakt, że ograniczenia względem wystawiania recept spowodują utrudniony dostęp do recept. W ocenie ZAF każda zmiana prawa powinna ułatwiać życie społeczeństwu, a nie je utrudniać.\\tUwaga częściowo uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii. .\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 1 lit. b dotyczący art. 6 ust. 2b ustawy \\frefundacyjnej\\t\\fproponujemy zastosowanie tej regulacji wyłącznie do programów lekowych, ponieważ w refundacji aptecznej będzie stanowiło to istotne ograniczenie \\fdostępności pacjentów do refundowanych terapii.  \\t\\fZwracamy uwagę, że ograniczenia w zakresie określania poziomów odpłatności przepisywanego leku w związku ze specjalizacją lekarską będzie \\fprowadziło do zmniejszenia dostępności produktów refundowanych. Wynika to z niewystarczającego dostępu do leczenia specjalistycznego i długiego okresu oczekiwania na konsultację u lekarza - specjalisty.  W naszej ocenie proponowane przez Ministerstwo Zdrowia rozwiązanie może prowadzić do dalszego wydłużenia kolejek do specjalistów\\t\\fUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania \\fspecjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tOrganizacja Pracodawców Przemysłu Medycznego TECHNOMED\\tArt. 1 pkt 1 lit. b dotyczący art. 6 ust. 2b ustawy refundacyjnej\\tWnioskujemy o wyłączenie z przepisu wyrobów medycznych.\\tPrzyznanie Ministrowi Zdrowia uprawnień do określania specjalizacji lekarskich oraz parametrów ordynacji wyrobów medycznych jest rozwiązaniem nieproporcjonalnym, gdyż wyroby takie jak opatrunki specjalistyczne mają szerokie zastosowanie i określenie z góry wskazań może prowadzić do ograniczenia dostępności świadczeń zdrowotnych, zwiększenia kosztów systemowych oraz obniżenia jakości opieki nad pacjentem. W przypadku wyrobów decydującym o ordynacji powinien być lekarz.\\tUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tArt. 1 pkt 1 lit. b dotyczący art. 6 ust. 2b ustawy refundacyjnej\\tNie negując zasadności wprowadzenia proponowanego rozwiązani widzimy potencjalne trudności dotyczące jego późniejszego funkcjonowania. Z perspektywy Związku szczególnie istotne jest ryzyko przeniesienia na apteki obowiązku weryfikacji, czy dany produkt \\frefundowany został przepisany przez lekarza uprawnionego do określonej preskrypcji z uwagi na posiadaną przez niego specjalizację. W naszej ocenie kwestia ta wymaga jednoznacznego doprecyzowania, a ewentualne mechanizmy kontrolne powinny zostać zabezpieczone w sposób systemowy, bez ryzyka przenoszenia odpowiedzialności na apteki.\\t\\tUwaga częściowo uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. \\fZaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tPrzedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tArt. 1 pkt 2 lit. b dotyczący art. 6 ust. 2b ustawy refundacyjnej\\tPropozycja rezygnacji z tego przepisu lub jego doprecyzowanie w zaproponowanym brzmieniu: Minister do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, oraz określenie liczby opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2, w odniesieniu do leku, który wcześniej był refundowany w kategorii dostępności, o której mowa w ust. 1 pkt 2.\\tZgodnie z uzasadnieniem wprowadzenia tego przepisu, istnieje potrzeba ograniczenia swobody preskrypcyjnej, w przypadku leku, który wcześniej był dostępny w programie lekowym, a został umieszczony na liście aptecznej. Nie ma natomiast żadnego uzasadnienia, aby podobne ograniczenia dotyczyły pozostałych leków z listy aptecznej.\\tUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tWiseMed – agencja marketingu medycznego\\tArt. 1 pkt 2 lit. b dotyczący art. 6 ust. 2b ustawy refundacyjnej\\tProponujemy rezygnację z wprowadzania przedmiotowego upoważnienia dla Ministra Zdrowia (art. 1 pkt 2 lit b projektu) oraz zaplanowanie prac legislacyjnych mających na celu rozwiązanie zidentyfikowanych przez Projektodawcę problemów w sposób właściwy dla nich, a więc stawiających na pierwszym miejscu \\ftroskę o zdrowie i życie pacjentów, a nie wyłącznie aspekt ekonomiczny terapii.   Prosimy o rozpoczęcie prac nad przepisami, które umożliwią zabezpieczenie pacjentów przed zjawiskiem przepisywania tych samych leków, nieuzasadnioną klinicznie preskrypcją leków z tych samych grup terapeutycznych oraz preskrypcją bez faktycznego wskazania. W szczególności postulujemy: • Stworzenie mechanizmów faktycznego dostępu dla wszystkich grup profesjonalistów medycznych upoważnionych do wystawiania recept do dokumentacji medycznej w zakresie historii dotychczasowej farmakoterapii, • Systemowe umożliwienie sprawnej wzajemnej komunikacji między różnymi profesjonalistami wystawiającymi recepty praktykującymi w różnych placówkach oraz między farmaceutami realizującymi bądź kontrolującymi prawidłowość realizacji recept z tymi specjalistami, • Ewaluację i aktualizację przepisów ustawy z dnia 10 grudnia 2020 r. o zawodzie farmaceuty (Dz. U. 2021 poz. 97; dalej: u.z.f.) oraz innych ustaw w zakresie, w jakim dotyczą one przedmiotu u.z.f. Tak, aby rzeczywiście spełniony został jeden z kluczowych celów ustawodawcy uzasadniający przyjęcie tej ustawy, czyli zapewnienie faktycznego, powszechnego dostępu pacjentów do wysokiej jakości świadczeń zdrowotnych udzielanych w ramach opieki farmaceutycznej i usług farmaceutycznych służących zapewnieniu skuteczności i bezpieczeństwa farmakoterapii,   \\fNie generując ryzyka wzmożenia tendencji do przenoszenia ciężaru opieki zdrowotnej z podstawowej opieki zdrowotnej na opiekę specjalistyczną.\\t\\fW uzasadnieniu Projektodawca zaważył, że w katalogu aptecznym nie istnieją żadne bezpieczniki, które zabezpieczałyby płatnika publicznego przed nieuprawnioną preskrypcją dublująca się wielokrotnie u kilku specjalistów, braku zdefiniowanego horyzontu leczenia pacjenta oraz osoby prowadzącej daną terapię pacjenta. \\fStanowiłoby to również zabezpieczenie z korzystania przez pacjentów z mechanizmów autopreskrypcji, jak również przeciwdziałałoby wywozowi leków wysokokosztowych za granicę. Należy zauważyć, że zjawiska nieuprawnionej preskrypcji, przepisywania tych samych leków przez różnych specjalistów równocześnie, czy występowania mechanizmów samodzielnego i nieuzasadnionego klinicznie wpływu pacjentów na preskrypcję, są zagrożeniem przede wszystkim dla zdrowia i życia pacjentów, których dotyczą. Co więcej, istnieje wiele czynników sprawiających, że problemy te dotyczą przede wszystkim tańszych terapii, a w mniejszym stopniu towarzyszą stosowaniu najdroższych spośród refundowanych w ramach katalogu aptecznego. W przypadku terapii wysokokosztowych: • Istnieje mniejsze ryzyko nieświadomego przyjmowania przez pacjenta tych samych substancji leczniczych pod tą samą nazwą ze względu na brak albo mniejszą liczbę dostępnych odpowiedników, gdyż największe koszty generują nowe, innowacyjne terapie. • Obawy o odpowiedzialność finansową wynikającą z bezpodstawnego wystawienia recepty refundowanej skłaniają lekarzy do większej ostrożności przy okazji preskrypcji najdroższych leków • Wiele spośród droższych i innowacyjnych leków wymaga ściślejszego monitorowania efektów leczenia i z założenia podejmują się go \\fspecjaliści kompetentni w tym zakresie. Racjonalizacja wydatków płatnika publicznego jest w oczywisty sposób uzasadniona interesem publicznym, gdyż środki finansowe, którymi on dysponuje, są przeznaczone na realizację zadań władzy publicznej, ustanowionych poprzez art. 38 i art. 68 Konstytucji. Nie można jednak zapominać, iż gospodarowanie finansami narodowego funduszu zdrowia powinno mieć charakter służebny względem konstytucyjnych praw do ochrony zdrowia i życia jednostki – pacjenta. Z tego względu rozważając wprowadzenie ograniczeń służących zmniejszeniu wydatków płatnika publicznego, należy w pierwszej kolejności ocenić je przez pryzmat wpływu na zdrowie i życie pacjentów, których mogą one dotyczyć.  Proponowana w art. 1 pkt 2 lit. b projektu zmiana, chociaż prawdopodobnie wpłynęłaby pozytywnie na budżet płatnika finansowego, mogłaby odbić się negatywnie na dostępie pacjentów nie tylko do farmakoterapii, ale także do konsultacji specjalistycznych. Drastyczne ograniczenie katalogu specjalistów uprawnionych do nanoszenia poziomu odpłatności wybranych leków, najprawdopodobniej poskutkuje zwiększeniem liczby porad udzielanych przez tych specjalistów, a więc wydłużeniem czasu oczekiwania na konsultację. W pewnym stopniu wiąże się to również z przerzuceniem ciężaru finansowania tych terapii z płatnika publicznego na pacjentów, gdyż osoby, które mają takie możliwości finansowe nadal będą mogły wykupić leki dostępne \\fw aptece, jednak wyłącznie na „pełnopłatną” receptę.  Co najistotniejsze, projektowana zmiana nie rozwiązuje przytoczonych powyżej problemów nieuzasadnionej preskrypcji, duplikacji terapeutycznej, czy tzw. autopreskrypcji, ale jedynie chroni przed niektórymi, bezpośrednimi ich konsekwencjami płatnika publicznego. Wynika to z faktu, iż obejmie ona wyłącznie pacjentów korzystających z wybranych przez Ministra Zdrowia, wysokokosztowych terapii, a ponadto nawet oni nie będą chronieni w pełni, gdyż nadal będą narażeni na wystąpienie tych zjawisk, ale na skutek realizowania recept pełnopłatnych. Ponadto stoi ona w sprzeczności z podkreślaną zgodnie przez całe środowisko specjalistów opieki zdrowotnej koniecznością przesuwania ciężaru świadczeń z opieki szpitalnej na ambulatoryjną i z ambulatoryjnej na poziom POZ.  Opisane wyżej problemy z niewłaściwą preskrypcją nie wynikają z nieprawidłowych zasad refundacji produktów leczniczych, ale są wypadkową wielu czynników, na które składają się: • Brak faktycznego dostępu osób upoważnionych do wystawiania i realizacji recept do pełnej dokumentacji medycznej w zakresie istotnym z punktu widzenia preskrypcji, w szczególności pełnej historii farmakoterapii (dane dostępne przez Internetowe Konto Pacjenta w praktyce okazują się być niewystarczające). • Brak faktycznych formalnych i organizacyjnych mechanizmów \\fwzajemnej, dwustronnej komunikacji między osobami wystawiającymi recepty oraz między wystawiającymi a realizującymi je. Profesjonalista medyczny chcący skontaktować się ze specjalistą, który wystawił receptę, zmuszony jest podejmować próby, bardzo często czasochłonne i nieskuteczne, kontaktu poprzez ogólnodostępne infolinie czy rejestracje dla pacjentów. W praktyce ogromna część odpowiedzialności za przekazanie między specjalistami informacji o wdrożonym leczeniu systemowo przerzucona jest na pacjenta, który w najlepszym wypadku otrzymuję kartkę, którą winien osobiście przekazać dalej. Szczególnie rażący jest również brak możliwości przekazania preskryptorowi informacji o ewentualnej nieprawidłowości przez farmaceutę realizującego receptę, bądź kontrolującemu prawidłowość jej realizacji. Już w obecnym systemie realizacja recept i dostęp do systemu aptecznego pozwala na wykrycie sporej części nieprawidłowych preskrypcji. Niestety brakuje nie tylko możliwości skutecznego i sprawnego przekazania informacji w tym zakresie odpowiedniemu specjaliście, ale także mechanizmu obligującego tego specjalistę do przyjęcia i uwzględnienia tej informacji. • Nieskuteczność przepisów u.z.f. Stan faktyczny nie odpowiada intencjom ustawodawcy, którego celem było zapewnienie pacjentom dostępu do usług farmaceutycznych oraz świadczeń zdrowotnych realizowanych w ramach \\fopieki farmaceutycznej, aby zapewnić bezpieczeństwo i skuteczność farmakoterapii.  Rozwiązanie trzech głównych, wypunktowanych powyżej doprowadziłoby do rozwiązania faktycznych przyczyn zidentyfikowanych przez Projektodawcę problemów bez ryzyka obarczenia pacjentów negatywnymi konsekwencjami.   Na koniec warto podkreślić, że osoby uprawnione do wystawiania recept podlegają odpowiedzialności zawodowej, administracyjnej, cywilnej oraz karnej za nadużycia, których dopuszczają się w zakresie preskrypcji. W świetle tego faktu tym bardziej bezzasadne wydaje się rozwiązywanie problemu „nieuprawnionej preskrypcji” poprzez zmianę zasad refundacji produktów leczniczych, zamiast ewaluacji i udoskonalenia narzędzi prawnych i organizacyjnych\\t\\fUwaga częściowo uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Minister Zdrowia rozważy podjęcie prac nad innymi rozwiązaniami legislacyjnymi \\fmającymi na celu zabezpieczenie pacjentów przed kumulowaniem preskrypcji leków o podobnym działaniu terapeutycznym.\\n\\tFederacja Przedsiębiorców Polskich\\tArt.1 pkt 2 lit. b projektu odnoszący się do art. 6 ust. 2b ustawy refundacyjnej\\tWnioskujemy o zmianę dodanego w art. 6 ustawy refundacyjnej ust. 2b.  Proponujemy następujące brzmienie zapisu art. 6 ust. 2b:  „2b. Minister właściwy do spraw zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa ust. 2, dla refundowanego leku w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1, pod warunkiem, że specjalizacja ta została wskazana w Charakterystyce Produktu Leczniczego dla \\ftego leku, o ile takie ograniczenia wynikają z decyzji o objęciu refundacją”. \\t\\fZgodnie z brzmieniem projektowanej zmiany ustawodawca w przypadku refundowanych terapii aptecznych oraz tych, finansowanych w programach lekowych, proponuje możliwość wskazania lekarza specjalisty uprawnionego do preskrypcji z uwagi na posiadaną przez niego konkretną specjalizację, właściwą ze względu na wskazanie danego leku. Dodatkowo przepis ten wprowadza obostrzenie w postaci liczby opakowań leku lub okresu terapii.  \\fZgodnie z intencją ustawodawcy dodanie ust. 2b w art. 6 ustawy refundacyjnej ma pozwolić na pozytywne rozpatrywanie wniosków na terapie wysokokosztowe w ramach refundacji aptecznej oraz na kontynuację leczenia rozpoczętego w programie lekowym w warunkach ambulatoryjnych z jednoczesnym zabezpieczeniem interesów płatnika publicznego.  Projektowana zmiana wychodzi naprzeciw oczekiwaniom zarówno pacjentów, jak i środowiska lekarskiego, dając nadzieję na szerszy dostęp do terapii innowacyjnych.  Z drugiej strony zapisy dotyczące ilości opakowań lub okresu terapii nie są naszym zdaniem konieczne, ponieważ ilość leku możliwa do zapisania na recepcie jest już obecnie uwarunkowana zapisami ustawy Prawo farmaceutyczne i dyskusyjnym byłoby ograniczanie tej ilości poprzez obwieszczenie refundacyjne.  Ponadto, naszym zdaniem zapis ten powinien dotyczyć wyłącznie leków, środków spożywczych specjalnego przeznaczenia żywieniowego dostępnych w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1. Specjalizacje lekarskie, które mogą realizować \\fokreślone programy lekowe są wskazane dla każdego programu lekowego indywidualnie w wymaganiach dla świadczeniodawców chcących realizować dany program (załącznik nr 3 do zarządzenia Prezesa NFZ w sprawie określenia warunków zawierania i realizacji umów w rodzaju leczenie szpitalne w zakresie programy lekowe).  Proponowana przez nas zmiana brzmienia ust. 2b jest zgodna z intencją ustawodawcy, zabezpiecza interes płatnika publicznego, a jednocześnie nie powiela zapisów ustawy Prawo farmaceutyczne oraz zarządzenia Prezesa NFZ w sprawie określenia warunków zawierania i realizacji umów w rodzaju leczenie szpitalne w zakresie programy lekowe.   Proponujemy również, aby ograniczenia związane z preskrypcją leków stały się elementem decyzji refundacyjnej – co w zależności od przyjętego sposobu wprowadzenia tych ograniczeń może wiązać np. z koniecznością zmiany elementów decyzji refundacyjnej.\\t\\fUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu \\fzapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii. \\n\\tPOLSKA FEDERACJA PRODUCENTÓW ŻYWNOŚCI ZWIĄZEK PRACODAWCÓW\\tArt.1 pkt 2 lit. b projektu odnoszący się do art. 6 ust. 2b ustawy refundacyjnej\\tProjektowane zmiany zakładają wprowadzenie zasady, zgodnie z którą Minister Zdrowia może określić w wykazie, o którym mowa w art. 37 ust.1, wskazanie specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności, o której mowa w art. 6 ust. 2, oraz określenie liczby opakowań leku, środka spożywczego \\fspecjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okres terapii, w ramach kategorii dostępności refundacyjnej, o której mowa w ust. 1 pkt 1 i 2. PFPŻ ZP jest zdania, że w świetle utrudnionego dostępu pacjentów do lekarzy określonej specjalizacji, nie jest zasadnym umożliwianie ograniczenia osób uprawnionych do określania poziomu odpłatności, do wybranych specjalistów. PFPŻ ZP postuluje wykreślenie projektowanej zmiany.\\t\\tUwaga uwzględniona Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności.\\n\\tPracodawcy RP\\tArt. 1 pkt 2 lit. b oraz art. 1 pkt 41 lit. a tiret drugie dotyczący art. 6 ust. 2b oraz art. 36 ust. 2 pkt 10 ustawy refundacyjnej\\tProponujemy, aby projektowane przepisy art. 6 ust. 2b oraz art. 37 ust. 2 pkt 10 zostały zmodyfikowane w ten sposób, żeby odnosiły się wyłącznie do leków stosowanych w ramach projektowanego rozwiązania dla leczenia długoterminowego w programach lekowych i tzw. „czwartej” kategorii dostępności refundacyjnej (art. 6 ust. 1 pkt 2a). \\tW naszej ocenie wprowadzenie ograniczenia preskrypcji dla leków aptecznych będzie prowadziło do ograniczenia ich dostępności dla pacjentów, podczas gdy ich kluczową wartością jest właśnie szeroka dostępność. Nieuzasadnione wydaje się zatem wprowadzenie przepisów umożliwiających Ministrowi Zdrowia („MZ”) dowolne ustalanie ograniczeń dla leków aptecznych (brak konsultacji, możliwość zmiany ograniczeń w dowolnym czasie). Może to bowiem prowadzić do sytuacji, w której pacjent będzie opóźniał rozpoczęcie terapii lub będzie musiał przerwać leczenie ze względu na brak dostępności wizyty u lekarza danej specjalizacji i tym samym brak recepty na dany lek. Ponadto, ograniczenie to może zostać negatywnie odebrane przez środowisko lekarskie. \\fZasadne wydaje się, aby przepisy te odnosiły się do leków stosowanych w ramach programów lekowych i tzw. „czwartej” ktegorii dostępności refundacyjnej (AOS). Zgodnie z intencją wskazaną przez Ministerstwo Zdrowia i „przeniesieniem” terapii ze szpitala do AOS, konieczność wystawienia odpowiedniej recepty na realizację leku mogłaby zostać zrealizowana przez lekarza określonej specjalizacji.\\t\\fUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami do wskazanego artykułu podjął decyzję o wykreśleniu zapisu dotyczącego możliwości wskazania specjalizacji lekarskiej wymaganej do naniesienia poziomu odpłatności. Zaprojektowany zapis zakłada możliwość określenia opakowań leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub okresu terapii, na jaki zostanie produkt wydawany, nie obligatoryjny obowiązek. W związku z powyższym zakłada się, iż nie będzie on dotyczył wszystkich leków refundowanych. Zapis ma na celu zapewnienie dostępności dla wszystkich pacjentów, z uwzględnieniem personalizacji terapii.\\n\\tOkręgowa Izba Aptekarska w Krakowie\\tArt. 1 pkt 2 lit. c projektu \\tNależy umożliwić wydawanie za odpłatnością ryczałtową leków recepturowych sporządzonych z wykorzystaniem leków gotowych nie tylko w dawce niższej niż najniższa refundowana, ale także w każdej innej niż dostępna dawka refundowana.  c) ust. 5 otrzymuje brzmienie: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego jest inna niż dostępna dawka refundowanego leku gotowego.”,  \\tObecne przepisy odbierają prawo refundacji pacjentom, którzy potrzebują leku recepturowego, a dawka leku gotowego niezbędnego do wykonania tej receptury jest inna niż dawka refundowana, ale jednocześnie jest wyższa niż najniższa refundowana dawka.\\tUwaga częściowo uwzględniona Projektodawca wprowadził stosowną modyfikację mającą na celu pogodzenie rozwoju praktyki farmaceutycznej oraz potrzeb pacjentów z zapewnieniem stabilności i bezpieczeństwa finansowego systemu refundacyjnego.  Zaproponowano nowe brzmienie ust. 5.  „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego jest mniejsza od najmniejszej dawki leku gotowego w formie stałej stosowanej doustnie. Przepis nie ma zastosowania w przypadku sporządzania leków recepturowych o innej drodze podania niż użyty lek gotowy lub dostępności preparatów gotowych w zaordynowanej dawce lub stężeniu..\\n\\tOsoba fizyczna  \\tart. 1 pkt 2 lit. c projektu odnoszący \\fsię do art. 6 ust. 5 ustawy o refundacji \\t\\fzmiana jest niezasadna i zbędna. Warto przypomnieć, że taksa laborum – kluczowy element wyceny kosztu sporządzania \\fleków recepturowych – pozostawała bez jakiejkolwiek aktualizacji przez 20 lat!!!!!\\t\\f- ograniczenie marży do wartości „nie wyższej niż koszt wykonania leku recepturowego w warunkach innych niż \\faseptyczne” (31,81 zł) należy uznać za działanie nadmiarowe. De facto oznacza to ponowne zaniżenie limitów finansowania i niweczy długo wyczekiwaną reformę, która dopiero co została wdrożona. Takie ograniczenie może doprowadzić do spadku opłacalności wykonywania leków recepturowych w aptekach ogólnodostępnych, a tym samym do ograniczenia dostępności tej formy terapii dla pacjentów. - proponowana zmiana jest nie tylko niepotrzebna, ale również sprzeczna z celem, jaki przyświecał aktualizacji taksy laborum, czyli przywróceniem ekonomicznej równowagi w wycenie pracy farmaceuty.\\nW związku z tym postuluję pozostawienie obecnie obowiązujących zasad bez wprowadzania dodatkowych ograniczeń.\\t\\fUwaga zasadna  Proponowana zmiana została usunięta z projektu.\\n \\tBusiness Centre Club/Pracodawcy RP\\tart. 1 pkt 2 lit. c projektu odnoszący się do art. 6 ust. 5 ustawy o refundacji\\tc) ust. 5 otrzymuje brzmienie: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka i/lub, stężenie i/lub  postać leku recepturowego jest inna niż dawka i/lub stężenie i/lub postać mniejsza od najmniejszej dawki refundowanego leku gotowego.”, \\tObecna propozycja nie określa o jaką najmniejszą dawkę leku refundowanego chodzi – rodzi to wątpliwości czy wykonując np. maść ma brać pod uwagę inne postacie leku z tą samą substancją? Nie jest określone jaki związek ma najmniejsza dostępna dawka czy stężenie leku np. w kroplach do dawki np. wykonywanych proszków. Dodatkowo receptura charakteryzuje się tym, że przygotowuje się pacjentowi lek, którego nie ma w obrocie – dotyczy to zarówno dawki jak i postaci leku. Dlatego też uzasadnionym jest, że refundacji powinien podlegać lek recepturowy, którego dawka, stężenie lub postać są różne od tych które występują w postaci leków gotowych. Ograniczenie \\fmożliwości refundowania leku recepturowego przygotowywanych z leków gotowych nie może być możliwe tylko gdy wykonywany lek ma mniejszą dawkę niż lek gotowy, ponieważ powoduje to, że w niektórych sytuacjach mimo możliwości wykonania leku o innej dawce pacjent będzie zmuszony do samodzielnego dzielenia leku co rodzi ryzyko błędu w leczeniu. \\t\\fUwaga częściowo uwzględniona. Projektodawca wprowadził stosowną modyfikację mającą na celu pogodzenie rozwoju praktyki farmaceutycznej oraz potrzeb pacjentów z zapewnieniem stabilności i bezpieczeństwa finansowego systemu refundacyjnego.  Zaproponowano nowe brzmienie ust. 5.  „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego \\fjest mniejsza od najmniejszej dawki leku gotowego w formie stałej stosowanej doustnie. Przepis nie ma zastosowania w przypadku sporządzania leków recepturowych o innej drodze podania niż użyty lek gotowy lub dostępności preparatów gotowych w zaordynowanej dawce lub stężeniu.\\n\\tWiseMed – agencja marketingu medycznego\\tart. 1 pkt 2 lit. c projektu odnoszący się do art. 6 ust. 5 ustawy o refundacji\\tProponujemy: 1. Doprecyzowanie brzmienia art. 6 ust. 5 wprowadzanego przez art. 1 pkt. 2 lit. c Projektu w sposób zapewniający, że porównanie dawki składnika leku recepturowego dotyczy wyłącznie analogicznej postaci farmaceutycznej, a samo kryterium odnosi się zarówno do dawki lub stężenia. 2. Umożliwienie nadawania odpłatności ryczałtowej w przypadku recept na leki recepturowe, zawierające w składzie leki gotowe również w wyższej niż najmniejsza dawka leku gotowego w tej samej postaci   Proponowane brzmienie przepisu: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka jest inna niż dawka refundowanego leku gotowego w tej samej postaci, a w przypadku leków w formie innej niż stała – stężenie substancji leczniczej w refundowanym leku gotowych w tej samej postaci.”   \\fProponujemy także zmianę brzmienia punktu 5a tak, aby przyjął on treść: „5a Przepisu ust. 5 nie stosuje się do leków recepturowych: a) przygotowanych z surowców farmaceutycznych, które uzyskały pozwolenie na dopuszczenie do obrotu na podstawie art. 33a ust. 1 ustawy z dnia 29 lipca 2005 r. o przeciwdziałaniu narkomanii (Dz. U. z 2023 r. poz. 1939). b) przygotowanych z leków gotowych w dawce lub stężeniu równych wielokrotności dawki lub stężenia leku gotowego w postaci doustnej.   Jeśli Projektodawca nie zdecyduje się na uwzględnienie propozycji umożliwienia nadawania odpłatności ryczałtowej w przypadku recept na leki recepturowe, zawierające w składzie leki gotowe również w wyższej niż najmniejsza dawka leku gotowego w odpowiedniej postaci,, proponujemy, aby przepis przyjął brzmienie: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka lub stężenie leku recepturowego jest mniejsza od najmniejszej dawki, a w przypadku leków w formie innej niż stała – stężenia substancji leczniczej w refundowanym leku gotowym w tej samej postaci.”\\t\\fUsunięcie z przepisu ograniczenia do formy stałej stosowanej doustnie niewątpliwie rozwiązuje problem dotychczasowej interpretacji w odniesieniu do leków ad usum externum. Rodzi jednak kolejne problemy, ponieważ proponowany zapis otwiera kolejne ścieżki interpretacji przepisów. W szczególności należy założyć sytuację, gdy niewielkie stężenia substancji czynnej występują w chociażby refundowanych preparatach do oczu lub nosa, przez co likwiduje praktycznie możliwość objęcia refundacją leku recepturowego, w którym z uwagi na postać dawka będzie znacząco większa. Wnosimy więc, aby w przepisie uwzględniono określenie „tej samej postaci farmaceutycznej”   Dodatkowo – w przypadku maści określenie „dawki” jest nieprecyzyjne. Zarówno praktyka, jak i określone prawnie zasady refundacji dopuszczają sformułowanie dawkowania postaci do użytku zewnętrznego wyłącznie w formie częstotliwości. Nie sposób więc dla takiego leku obliczyć dawkę i porównać ją do leku gotowego, co utrudni pracę zarówno preskryptora, jak \\fi osoby wykonującej lek recepturowy. Najrozsądniejszym rozwiązaniem wydaje się być wprowadzenie określenia „stężenie”, które odpowiednio oddaje naturę produktów leczniczych w postaci maści czy kropli do oczu.   Aby uniknąć wątpliwości interpretacyjnych oraz zapewnić przewidywalność refundacji, proponujemy zmianę, która uwzględni zarówno dawkę lub stężenie, jak i postać farmaceutyczną, do której odnosi się porównanie.   Ponadto należy zauważyć, że obowiązujące przepisy wyłączają możliwość nadania odpłatności ryczałtowej lekom recepturowym, których nie da się zastąpić lekiem gotowym, a ich dawka jest większa niż najniższa refundowana dawka leku gotowego. Chodzi tutaj o sytuacje, w których dawka leku recepturowego nie stanowi wielokrotności żadnej z refundowanych dawek leku gotowego, ani nie może być osiągnięta przez np. podział tabletki.\\t\\fUwaga częściowo uwzględniona. Projektodawca wprowadził stosowną modyfikację mającą na celu pogodzenie rozwoju praktyki farmaceutycznej oraz potrzeb pacjentów z zapewnieniem stabilności i bezpieczeństwa finansowego systemu refundacyjnego.  Zaproponowano nowe brzmienie ust. 5.  „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego jest mniejsza od najmniejszej dawki leku gotowego w formie stałej stosowanej doustnie. Przepis nie ma zastosowania w przypadku sporządzania leków recepturowych o innej drodze podania niż użyty lek gotowy lub dostępności preparatów gotowych w zaordynowanej dawce lub stężeniu.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1. Pkt 2) lit. c)\\tust. 5 otrzymuje brzmienie: „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana \\fdecyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka lub stężenie lub postać leku recepturowego jest inna niż dawka lub stężenie lub postać mniejsza od najmniejszej dawki refundowanego leku gotowego.”, \\t\\fObecna propozycja nie określa o jaką najmniejszą dawkę leku refundowanego chodzi – rodzi to wątpliwości czy wykonując np. maść należy brać pod \\fuwagę inne postacie leku z tą samą substancją. Nie jest też określone jaki związek ma najmniejsza dostępna dawka czy stężenie leku np. w kroplach do dawki wykonywanych proszków. Dodatkowo, receptura charakteryzuje się tym, że przygotowuje się pacjentowi lek, którego nie ma w obrocie – dotyczy to zarówno dawki jak i postaci leku. Dlatego też uzasadnionym jest, że refundacji powinien podlegać lek recepturowy, którego dawka, stężenie lub postać są różne od tych które występują w postaci leków gotowych. Ograniczenie możliwości refundowania leku recepturowego przygotowywanych z leków gotowych nie może być możliwe tylko gdy wykonywany lek ma mniejszą dawkę niż lek gotowy, ponieważ powoduje to, że w niektórych sytuacjach mimo możliwości wykonania leku o innej dawce pacjent będzie zmuszony do samodzielnego dzielenia leku co rodzi ryzyko błędu w leczeniu\\t\\fUwaga częściowo uwzględniona. Projektodawca wprowadził stosowną modyfikację mającą na celu pogodzenie rozwoju praktyki farmaceutycznej oraz \\fpotrzeb pacjentów z zapewnieniem stabilności i bezpieczeństwa finansowego systemu refundacyjnego.  Zaproponowano nowe brzmienie ust. 5.  „5. Leki recepturowe przygotowane z surowców farmaceutycznych lub z leków gotowych, dla których została wydana decyzja administracyjna o objęciu refundacją, są wydawane świadczeniobiorcy za odpłatnością ryczałtową, pod warunkiem, że przepisana dawka leku recepturowego jest mniejsza od najmniejszej dawki leku gotowego w formie stałej stosowanej doustnie. Przepis nie ma zastosowania w przypadku sporządzania leków recepturowych o innej drodze podania niż użyty lek gotowy lub dostępności preparatów gotowych w zaordynowanej dawce lub stężeniu.\\n\\tOkręgowa Izba Aptekarska w Krakowie\\tArt. 1 pkt 2 lit. d projektu  odnoszący się do art. 6 ust. 8a ustawy refundacyjnej \\tWprowadzenie rozwiązania zabezpieczającego interes pacjentów, w przypadku nagłego wzrostu kosztów produkcji substancji recepturowych i wzrostu kosztów wykonania leku recpturowego. Np. oparcie kosztu na współczynniku uwzględniającym poziom inflacji\\tReceptura apteczna bardzo ucierpiała po wprowadzeniu limitów. Mimo, że podniesienie z 15 do 25 percentyla jest propozycją pozytywną , proponowana jest za późno. Zakładając, że ustawa refundacyjna nie będzie nieustannie nowelizowana, należy wprowadzić mechanizm zabezpieczający pacjentów przed zbyt wysoką opłatą za lek recepturowy w przypadku np. nagłego wzrostu ceny surowca farmaceutycznego.\\tUwaga częściowo uwzględniona  Zaproponowano zmianę w art. 6 ust. 8c mającą na celu wprowadzenie mechanizmu ograniczającego nadmierne obniżenie limitu finansowania. Tym samym zaproponowano następujące brzmienie ust. 8c: „8c. Jeżeli limit finansowania danego surowca farmaceutycznego, wyznaczony zgodnie z ust. 8a, byłby:  1) niższy o więcej niż 5% od limitu finansowania obowiązującego w roku poprzednim – limit finansowania tego surowca ustala się w wysokości limitu \\ffinansowania obowiązującego w roku poprzednim; 2) wyższy niż wartość odpowiadająca 30 percentylowi rozkładu cen danego surowca farmaceutycznego z roku poprzedzającego rok ubiegły – limit finansowania tego surowca ustala się w wysokości tej wartości. \\n\\tBusiness Centre Club/ Pracodawcy RP \\tArt. 1. pkt 2 lit. d projektu odnoszący się do art. 6 ust. 8a ustawy refundacyjnej\\tZniesienie mechanizmu prowadzącego do obniżenia limitów finansowania surowców farmaceutycznych i przywrócenie pierwszej po wejściu w życie DNUR listy limitów. Ustalenie limitów finansowania na stałym poziomie, który mógłby być rewaloryzowany zgodnie np. z poziomem inflacji.\\tCieszy fakt, że MZ doszło w końcu do tego, że należałoby ujednolicić mechanizm wyznaczania nowych limitów zarówno dla leków gotowych jak i surowców recepturowych – do 25 percentyla. Szkoda, że podczas procedowania DNUR nie uwzględniono tego pomysłu zgłaszanego m.in. przez Pracodawców RP czy ZAF i od wejścia w życie DNUR obowiązywał wysoce szkodliwy współczynnik określający limit dla surowców farmaceutycznych na podstawie 15 percentyla. Limity na surowce recepturowe niestety spadły do bardzo niskiego poziomu co rodzi obawę nie tylko już o opłacalność wykonania leku recepturowego w aptece, ale i o samą dostępność do surowców recepturowych – niedługo bowiem produkcja takich substancji może być całkowicie nieopłacalna, a ewentualna sprzedaż powyżej limitu będzie skutkować większą dopłatą przez pacjenta. Rynek zaakceptował i przystosował się do pierwszej listy limitów, wyznaczonej po wejściu w życie DNUR. Każda kolejna lista to dalsze spadki limitów finansowania i niezależnie czy mechanizm oparty jest obecnie na 15% czy na 25% to nie zmienia to faktu, że pierwsze obniżki były zbyt gwałtowne \\fco doprowadziło do znacznego pogorszenia dostępności do leków robionych w aptekach. Powrót do pierwszej listy limitowej wyznaczonej po wejściu w życie DNUR i rezygnacja z mechanizmów promujących spadek limitów zapewni stabilność funkcjonowania receptury w aptekach, które jeszcze tę recepturę wykonują. Dodatkowo, jako że leki recepturowe są specyficzną grupą preparatów, na których koszt wytworzenia bardzo duży wpływ mają szybko zmieniające się warunki rynkowe, dlatego też zasadnym byłoby, żeby zamiast mechanizmu promującego zmniejszanie wartości limitów dla surowców recepturowych zaproponować mechanizm, który zabezpieczałby ewentualny wzrost cen zakupu surowców recepturowych i dostosował limit do tej wartości. Można byłoby oprzeć taki koszt o np. wartość inflacji. Taki mechanizm, odwrotny od obecnie funkcjonującego zabezpieczyłby interes pacjentów i zapobiegałby nadmiernemu wzrostowi odpłatności przez pacjenta w sytuacji, gdyby np. koszty wytworzenia surowca recepturowego i wytworzenia leku recepturowego nagle wzrastały.  Uzasadnienie Pracodawcy RP Ujednolicenie mechanizmu wyznaczania nowych limitów zarówno dla leków gotowych jak i surowców recepturowych  do 25 percentyla było już zgłaszane m.in. przez Pracodawców RP czy ZAF podczas procedowania DNUR. Nie zostało to jednak wtedy uwzględnione i od wejścia w życie DNUR obowiązywał szkodliwy \\fwspółczynnik określający limit dla surowców farmaceutycznych na podstawie 15 percentyla. Limity na surowce recepturowe spadły do bardzo niskiego poziomu co rodzi obawę nie tylko już o opłacalność wykonania leku recepturowego w aptece, ale i o samą dostępność do surowców recepturowych – niedługo bowiem produkcja takich substancji może być całkowicie nieopłacalna, a ewentualna sprzedaż powyżej limitu będzie skutkować większą dopłatą przez pacjenta. Rynek zaakceptował i przystosował się do pierwszej listy limitów, wyznaczonej po wejściu w życie DNUR. Każda kolejna lista to dalsze spadki limitów finansowania i niezależnie czy mechanizm oparty jest obecnie na 15% czy na 25% to nie zmienia to faktu, że pierwsze obniżki były zbyt gwałtowne co doprowadziło do znacznego pogorszenia dostępności leków robionych w aptekach. Powrót do pierwszej listy limitowej wyznaczonej po wejściu w życie DNUR i rezygnacja z mechanizmów promujących spadek limitów zapewni stabilność funkcjonowania receptury w aptekach, które jeszcze tę recepturę wykonują. Biorąc pod uwagę, że leki recepturowe są specyficzną grupą preparatów, na których koszt wytworzenia bardzo duży wpływ mają szybko zmieniające się warunki rynkowe, zasadnym byłoby, żeby zamiast mechanizmu promującego zmniejszanie wartości limitów dla surowców recepturowych zaproponować mechanizm, który zabezpieczałby ewentualny wzrost cen zakupu \\fsurowców recepturowych i dostosował limit do tej wartości. Można byłoby oprzeć taki koszt o np. wartość inflacji. Taki mechanizm, odwrotny od obecnie funkcjonującego zabezpieczyłby interes pacjentów i zapobiegałby nadmiernemu wzrostowi odpłatności przez pacjenta w sytuacji, gdyby np. koszty wytworzenia surowca recepturowego i wytworzenia leku recepturowego nagle wzrastały. \\t\\fUwaga częściowo uwzględniona.  Zaproponowano zmianę w art. 6 ust. 8c mającą na celu wprowadzenie mechanizmu ograniczającego nadmierne obniżenie limitu finansowania. Tym samym zaproponowano następujące brzmienie ust. 8c: „8c. Jeżeli limit finansowania danego surowca farmaceutycznego, wyznaczony zgodnie z ust. 8a, byłby:  1) niższy o więcej niż 5% od limitu finansowania obowiązującego w roku poprzednim – limit finansowania tego surowca ustala się w wysokości limitu finansowania obowiązującego w roku poprzednim; 2) wyższy niż wartość odpowiadająca 30 percentylowi rozkładu cen danego surowca farmaceutycznego z roku poprzedzającego rok ubiegły – limit finansowania tego surowca ustala się w wysokości tej wartości. \\n\\tZwiązek Aptek Franczyzowych\\tArt. 1. pkt 2 lit. d projektu odnoszący się do art. 6 ust. 8a ustawy refundacyjnej\\tPrzywrócenie pierwszej po wejściu w życie DNUR listy limitów dla substancji recepturowych oraz ponowne jej przeliczanie według nowego modelu – w oparciu o 25 percentyl rozchodu. \\tZAF już podczas procedowania DNUR zwracał uwagę na brak konsekwencji ustawodawcy w określeniu modelu wyznaczania limitów finansowania i wnioskował o zmianę w ówczesnym projekcie – by limity dla substancji farmaceutycznych liczyć na podstawie 25 percentyla a nie na podstawie 15 percentyla. Niestety uwaga ta nie została uwzględniona. Dzisiaj widzimy, że nadmierne obniżenie progu ustalania nowych limitów skutkuje znacznym spadkiem wartości tych limitów, przez co niejednokrotnie to pacjenci są zmuszenie do ponoszenia większych wydatków za wykonanie leku robionego. Powoduje to, że i opłacalność wykonywania leków recepturowych się jeszcze bardziej zmniejszyła, ponieważ zmniejszeniu uległa podstawa liczenia marży. Zastosowanie od samego początku, tak jak wnioskował ZAF, mechanizmu wyznaczania nowych limitów w oparciu o 25 percentyl zabezpieczy rynek apteczny oraz dostawców przez nadmiernymi spadkami limitów, a to pozytywnie przełoży się na dostępność finansową dla pacjentów. Na koniec, mimo, że nie jest to związane z projektem warto zwrócić \\fuwagę na to, że spadki wartości limitów w ostatnim czasie wydają się być nienaturalne i być może warto przeanalizować proces wyznaczania nowych wartości limitów jeszcze raz? Patrząc bowiem jak trudno było dotychczas „zmieścić” się w limitach finansowania niemożliwym wydaje się tak duży spadek wartości limitów finansowania – niezależnie od tego czy sposób ich wyznaczania byłby oparty na 15 czy 25 percentylu. \\t\\fUwaga częściowo uwzględniona.  Zaproponowano zmianę w art. 6 ust. 8c mającą na celu wprowadzenie mechanizmu ograniczającego nadmierne obniżenie limitu finansowania. Tym samym zaproponowano następujące brzmienie ust. 8c: „8c. Jeżeli limit finansowania danego surowca farmaceutycznego, wyznaczony zgodnie z ust. 8a, byłby:  1) niższy o więcej niż 5% od limitu finansowania obowiązującego w roku poprzednim – limit finansowania tego surowca ustala się w wysokości limitu finansowania obowiązującego w roku poprzednim; 2) wyższy niż wartość odpowiadająca 30 percentylowi rozkładu cen danego surowca farmaceutycznego z roku poprzedzającego rok ubiegły – limit finansowania tego surowca ustala się w wysokości tej wartości. \\n\\tIzba Gospodarcza FARMACJA POLSKA\\tArt. 1. pkt 2 lit. d projektu odnoszący się do art. 6 ust. 8a ustawy refundacyjnej\\tZasadne jest zastopowanie ciągłego obniżania cen i wprowadzenie mechanizmu kontroli cen poprzez: Wprowadzenie zapisu i przeliczenie limitu według: 25 percentyla rozkładu cen danego surowca farmaceutycznego w roku poprzedzającym rok ustalenia limitu finansowania na surowce farmaceutyczne lub: Wprowadzenie w przepisach przejściowych Projektu Ustawy Zmieniającej zasady, że limit obowiązujący od 1 lipca 2026 będzie przeliczony na nowo z uwzględnieniem, że pierwszy, drugi i trzeci limit zostanie przeliczony na 25, a nie 15 percentylu rozkładu cen i na tej podstawie zostanie wyliczony limit obowiązujący od 1 lipca 2026. oraz  Wprowadzenia mechanizmu powiększania limitów o współczynnik inflacji, który częściowo pokrywałby zwiększanie \\fkosztów wytwarzania i dystrybucji, a kontrola państwa nad finansowaniem będzie zachowana. \\t\\fZmiana z „15 percentyla” na „25 percentyla” rozkładu cen danego surowca farmaceutycznego  Zmiana zawarta w art. 1 pkt 2) lit. d) o treści „d) w ust. 8a wyrazy „15 percentyla” zastępuje się wyrazami „25 percentyla”,” wydaje się, że niewiele zmienia, jednak w dłuższej perspektywie może spowodować braki dostępności niektórych surowców.   Po wprowadzeniu pierwszych limitów producenci i hurtownicy dostosowali ceny surowców do limitów, głównie poprzez ich obniżenie. W związku z tym, ceny hurtowe w pierwszym roku obowiązywania limitów wyrównały się i nie był zauważalny rozkład cen.  Jednocześnie, w związku z załamaniem rynku w roku 2024 r., ceny surowców farmaceutycznych były, przez niektóre podmioty, jednorazowo obniżane, na skutek np. wyprzedaży danego towaru przez producentów i hurtownie z uwagi na krótką datę ważności czy schodzenie ze stanów magazynowych. Takie jednorazowe obniżki, z uwagi na zastosowanie 15 percentyla bardzo \\fzaburzyły wyliczanie następnych limitów. Dnia 26 maja 2025 r. na stronie NFZ zostały opublikowane limity pod linkiem:   https://www.nfz.gov.pl/bip/komunikaty/projekt-wykazu-limitow-finansowania-za-jednostke-surowca-farmaceutycznego-sluzacego-do-sporzadzenia-leku-recepturowego,9.html    Nowe limity odnoszą się do pierwszego roku obowiązywania limitów i uwzględniają wyprzedaże z początku roku 2024. Ponieważ limity   te są obliczone od obniżonych cen i dodatkowo limit był wyliczany od 15 percentyla, to limit obecny dla większości surowców jest niższy niż limity poprzednio obowiązujące (zarówno pierwszy jaki i drugi limit).   To prowadzi do totalnej zapaści rynku. \\t\\fUwaga częściowo uwzględniona.  Zaproponowano zmianę w art. 6 ust. 8c mającą na celu wprowadzenie mechanizmu ograniczającego nadmierne obniżenie limitu finansowania. Tym samym zaproponowano następujące brzmienie ust. 8c: „8c. Jeżeli limit finansowania danego surowca farmaceutycznego, wyznaczony zgodnie z ust. 8a, byłby:  1) niższy o więcej niż 5% od limitu finansowania obowiązującego w roku poprzednim – limit finansowania tego surowca ustala się w wysokości limitu finansowania obowiązującego w roku poprzednim; 2) wyższy niż wartość odpowiadająca 30 percentylowi rozkładu cen danego surowca farmaceutycznego z roku poprzedzającego rok ubiegły – limit finansowania tego surowca ustala się w wysokości tej wartości. \\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1. pkt 2 lit. d projektu odnoszący się do art. 6 ust. 8a ustawy refundacyjnej\\tProponujemy zniesienie mechanizmu prowadzącego do obniżenia limitów finansowania surowców farmaceutycznych i przywrócenie pierwszej po wejściu w życie DNUR listy limitów. Ustalenie limitów finansowania na stałym poziomie, który mógłby być rewaloryzowany zgodnie np. z poziomem inflacji\\tPowrót do pierwszej listy limitowej wyznaczonej po wejściu w życie DNUR i rezygnacja z mechanizmów promujących spadek limitów zapewni stabilność funkcjonowania receptury w aptekach, które jeszcze tę recepturę wykonują. Dodatkowo, jako że leki recepturowe są specyficzną grupą preparatów, na których koszt wytworzenia bardzo duży wpływ mają szybko zmieniające się warunki rynkowe, dlatego też zasadnym byłoby, żeby zamiast mechanizmu promującego zmniejszanie wartości limitów dla surowców recepturowych zaproponować mechanizm, który zabezpieczałby ewentualny wzrost cen zakupu surowców recepturowych i \\fdostosował limit do tej wartości. Można byłoby oprzeć taki koszt o np. wartość inflacji. Taki mechanizm, odwrotny od obecnie funkcjonującego, zabezpieczyłby interes pacjentów i zapobiegałby nadmiernemu wzrostowi odpłatności przez pacjenta w sytuacji, gdyby np. koszty wytworzenia surowca recepturowego i wytworzenia leku recepturowego nagle wzrastały.\\t\\fUwaga częściowo uwzględniona  Zaproponowano zmianę w art. 6 ust. 8c mającą na celu wprowadzenie mechanizmu ograniczającego nadmierne obniżenie limitu finansowania. Tym samym zaproponowano następujące brzmienie ust. 8c: „8c. Jeżeli limit finansowania danego surowca farmaceutycznego, wyznaczony zgodnie z ust. 8a, byłby:  1) niższy o więcej niż 5% od limitu finansowania obowiązującego w roku poprzednim – limit finansowania tego surowca ustala się w wysokości limitu \\ffinansowania obowiązującego w roku poprzednim; 2) wyższy niż wartość odpowiadająca 30 percentylowi rozkładu cen danego surowca farmaceutycznego z roku poprzedzającego rok ubiegły – limit finansowania tego surowca ustala się w wysokości tej wartości. \\n\\tOkręgowa Izba Aptekarska w Krakowie\\tArt. 1 pkt 2 lit. e projektu \\tDodanie wymogu aktualizowania wykazu leków gotowych, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych nie rzadziej niż raz na dwa lata. e) ust. 10 otrzymuje brzmienie: „10. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia: 1) wykaz leków, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych oraz limity ich finansowania, ilość leku recepturowego, którego dotyczy odpłatność ryczałtowa, a także sposób obliczania kosztu sporządzania leku recepturowego, biorąc pod uwagę dostępność do leków, bezpieczeństwo ich stosowania oraz postać farmaceutyczną; dodanie punktu 1a): 1a) Minister właściwy do spraw zdrowia aktualizuje wykaz leków, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych nie rzadziej niż raz na dwa lata.\\tTak jak wprowadzane na rynek są nowe leki gotowe, tak w recepturze aptecznej pojawiają się nowe zastosowania leków gotowych. Niekiedy są jedynym rozwiązaniem dla potrzebujących pacjentów. Jako przykład można podać proszki z viagrą (obecnie sildenafil występuje już jako substancja recepturowa), krople oczne z insuliną, czy też starsze receptury np. z Nitrocardem. Stąd zasadnym wydaje sie aktualizacja listy leków gotowych, które mogą być traktowane jako surowce recepturowe tak, aby odpowiadała ona również bieżącym potrzebom pacjentów.\\tPoza zakresem nowelizacji  \\n\\tUrząd Rejestracji Produktów Leczniczych Wyrobów Medycznych i \\fProduktów Biobójczych\\t\\fArt. 1 pkt 2 lit. e projektu odnoszący się do art. 6 ust. 10 ustawy \\frefundacyjnej\\t\\fW odniesieniu do zapisów powyższej ustawy dotyczących zagadnień związanych z lekiem recepturowym oraz jednocześnie procedowanymi w Urzędzie (z udziałem GIF, DPL MZ i Naczelnej Izby Aptekarskiej) zmianami do monografii narodowej \\fFarmakopei Polskiej „Leki sporządzane w aptece” – w związku z planowaną w Suplemencie 2025 FP XIII zmianą statusu tej monografii z informacyjnego na obowiązujący, w kontekście planowanego do wydania na podstawie art. 6 ust. 10 ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych (art. 1 ust. 2 lit. e projektu) rozporządzenia Ministra Zdrowia uprzejmie informujemy, że celowe wydaje się objęcie przepisami refundacyjnymi miarek dołączanych do postaci leku sporządzanych w aptece, wymagających dozowania podczas stosowania (najczęściej są to płynne formy pediatryczne). W opinii ekspertów, wydawanie miarek przy takich lekach jest niezbędne i warunkuje prawidłowość terapii. Miary domowe (łyżeczki) są niedokładne, ponieważ aktualnie ich kształty i pojemność projektowane są w sposób dowolny. Badania praktyczne pojemności, np. łyżeczek wykazały drastyczne różnice (od 2,5-5 ml), i w tej sytuacji zalecana dawka, wyrażana na recepcie zapisem „łyżeczka”, nie może być prawidłowo osiągnięta, a lek będzie podawany niedokładnie oraz niepowtarzalnie.\\t\\tUwaga niezasadna Wskazane w uwadze kwestie będą brane pod uwagę podczas procedowania aktów wykonawczych do ustawy.\\n\\tPrzedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tArt. 1 pkt 2 lit. e projektu odnoszący się do art. 6 ust. 10 pkt 1 ustawy refundacyjnej\\to zmianę Art. 6 ust. 10 pkt 1 (art. 1 pkt 2 lit. e) poprzez usunięcie słów „oraz limity ich finansowania”:  Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia:  1) wykaz leków, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych oraz limity ich finansowania, ilość leku recepturowego, którego dotyczy \\fodpłatność ryczałtowa, a także sposób obliczania kosztu sporządzania leku recepturowego, biorąc pod uwagę dostępność do leków, bezpieczeństwo ich stosowania oraz postać farmaceutyczną.\\t\\fW przekazanej do konsultacji publicznych nowelizacji znalazły się również propozycje sprzeczne z przyjętym przez Ministra Zdrowia kierunkiem zmian o charakterze deregulacyjnym. Dotyczą one w szczególności kurczącego się z roku na rok rynku leków recepturowych, który, z uwagi na znikomą rentowność, może, w konsekwencji wprowadzenia \\fplanowanych zmian zostać całkowicie wyeliminowany. Już obecnie pacjent ponosi dodatkowe, nierzadko wysokie koszty leku przygotowywanego w aptece, zwłaszcza jeśli cena surowca, z którego został wykonany przekracza ustalony limit finasowania. Dobrą wiadomością dla pacjentów jest zawarta w przedmiotowym projekcie propozycja podniesienia progu limitu do 25 percentyla, co de facto zrównuje go z progiem ustalonym dla leków gotowych. Rozumiejąc potrzebę uszczelnia finansowania tego obszaru, sprzeciwiamy się ustaleniu limitów cenowych na leki gotowe, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych, co jest kolejnym rozwiązaniem uderzającym bezpośrednio w budżet pacjenta. Ta regulacja spowoduje dalsze zwiększenie dopłat pacjentów do leków recepturowych, a obowiązująca odpłatność ryczałtowa stanie się całkowicie pozorna. Produkty lecznicze należące do aktualnego wykazu to zwykle leki OTC, na które nie obowiązuje cena urzędowa, ale znajdują się wśród nich również leki wydawane na receptę, w tym refundowane które mają już ustalony limit finasowania. Warto również zaznaczyć, że w przeciwieństwie do surowców farmaceutycznych, apteka kupując lek gotowy z hurtowni, nie nabywa go z konkretnym przeznaczeniem – do receptury, a to ona ostatecznie kształtuje poziom ceny detalicznej. Pomysł wprowadzenia limitów na \\fprodukty lecznicze, które zgodnie z rozporządzeniem Ministra Zdrowia mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych przeczy jednocześnie samej idei tworzenia przedmiotowego wykazu tj. wyszczególnienia leków gotowych, których użycie nie generuje dodatkowych opłat po stronie pacjenta. Ponadto, proponowany przepis nie precyzuje w jaki sposób taki limit miałby zostać ustalony.\\t\\fUwaga niezasadna   W wyniku wprowadzenia w 2023 r. limitów finansowania na surowce farmaceutyczne na rynku leków recepturowych pojawiło się nowe zjawisko polegające na zawyżaniu cen opakowań bezpośrednich tych leków oraz leków gotowych traktowanych jako surowce farmaceutyczne przy \\fsporządzaniu leków recepturowych. W sygnalizowanych przez Narodowy Fundusz Zdrowia procederach dochodziło przykładowo do sporządzania w recepturze leków z użyciem produktu Linomag w cenie za gram produktu kilkukrotnie przekraczającej wartość produktu sprzedawanego w kanale OTC. Ponadto, należy zauważyć, że apteki zakupując produkty spoza listy refundacyjnej mają możliwość ustalenia marży detalicznej według własnego uznania dla każdej dostawy produktu. Co więcej, w systemie aptecznym technicznie możliwe jest wskazanie podczas wyceny leku recepturowego, która dostawa (i cena) ma zostać użyta do wyceny leku recepturowego. Możliwa jest więc w jednej aptece sprzedaż jednego produktu w kanale OTC z ceną inną niż produktu użytego w recepturze. Doświadczenia ostatnich lat wskazują, że przepisy w zakresie receptury bywają wykorzystywane w sposób prowadzący do zwiększonego i nieuzasadnionego obciążenia budżetu płatnika publicznego, dlatego też projektodawca, w trosce o stabilność i bezpieczeństwo finansowe systemu refundacyjnego, nie widzi możliwości usunięcia z projektu przedmiotowego zapisu. Kwestie sposobu wyznaczania limitów finansowania uregulowane będą w stosownym rozporządzeniu, jak wskazano w art. 6 ust. 10 pkt. 1 ustawy o refundacji.\\n\\tPolska Izba Przemysłu Farmaceutycznego i Wyrobów Medycznych  POLFARMED\\tart. 1 pkt 2 lit. e odnoszący się do art. 6 ust. 10 pkt 1 ustawy refundacyjnej\\tMinister właściwy do spraw zdrowia określi, w drodze rozporządzenia: 1) wykaz leków, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych oraz limity ich finansowania, ilość leku recepturowego, którego dotyczy odpłatność ryczałtowa, a także sposób obliczania kosztu sporządzania leku recepturowego, biorąc pod uwagę dostępność do leków, bezpieczeństwo ich stosowania oraz postać farmaceutyczną.\\tPostulujemy o usunięcie propozycji wprowadzenia limitów na leki gotowe, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych. Taka regulacja spowoduje znaczące dopłaty pacjentów do leków recepturowych, ponieważ leki gotowe należące do ww. wykazu w znacznej większości nie są objęte refundacją, więc ich ceny nie są regulowane. Są to zwykle tanie leki (krople witaminowe, syropy ziołowe), dostępne bez recepty (OTC). Są również wśród nich leki refundowane, które mają już ustalony limit. Ponadto, w odróżnieniu do surowców farmaceutycznych przepis nie precyzuje w jaki sposób limit miałby zostać ustalony. W naszej ocenie, aby uszczelnić system, wystarczy wprowadzić sztywną marżę hurtową na te produkty.\\tUwaga niezasadna  W wyniku wprowadzenia w 2023 r. limitów finansowania na surowce farmaceutyczne na rynku leków recepturowych pojawiło się nowe zjawisko polegające na zawyżaniu cen opakowań bezpośrednich tych leków oraz leków gotowych traktowanych jako surowce farmaceutyczne przy sporządzaniu leków recepturowych. W sygnalizowanych przez Narodowy Fundusz Zdrowia procederach dochodziło przykładowo do sporządzania w recepturze leków z użyciem produktu Linomag w cenie za gram produktu kilkukrotnie przekraczającej wartość produktu sprzedawanego w kanale OTC. Ponadto, należy zauważyć, że apteki zakupując produkty spoza listy refundacyjnej mają możliwość ustalenia marży detalicznej według własnego uznania dla każdej dostawy produktu. Co więcej, w systemie aptecznym technicznie możliwe jest wskazanie podczas wyceny leku recepturowego, \\fktóra dostawa (i cena) ma zostać użyta do wyceny leku recepturowego. Możliwa jest więc w jednej aptece sprzedaż jednego produktu w kanale OTC z ceną inną niż produktu użytego w recepturze. Doświadczenia ostatnich lat wskazują, że przepisy w zakresie receptury bywają wykorzystywane w sposób prowadzący do zwiększonego i nieuzasadnionego obciążenia budżetu płatnika publicznego, dlatego też projektodawca, w trosce o stabilność i bezpieczeństwo finansowe systemu refundacyjnego, nie widzi możliwości usunięcia z projektu przedmiotowego zapisu. Kwestie sposobu wyznaczania limitów finansowania uregulowane będą w stosownym rozporządzeniu, jak wskazano w art. 6 ust. 10 pkt. 1 ustawy o refundacji.\\n\\tKonfederacja Lewiatan\\tArt. 1 pkt 2 lit. f odnoszący się do art. 6 ust. 11 i 12 ust. ref.\\tZ jednej strony należy pozytywnie ocenić inicjatywę utworzenia receptariusza jako wyznaczenia pewnego standardu w obszarze wykonywania leków recepturowych. Z drugiej strony jednak przyjęcie sztywnych składów preparatów recepturowych jako warunku ich refundacji prowadzi w praktyce do ograniczenia elastyczności i indywidualizacji terapii, która stanowi istotę receptury aptecznej.  Wprowadzenie ścisłego katalogu składów leków recepturowych podlegających refundacji może skutkować istotnym ograniczeniem dostępności tej formy terapii. Tymczasem największą zaletą tych leków jest możliwość dostosowania składu leku do indywidualnych potrzeb pacjenta, takich jak nietolerancje, alergie, wiek czy specyfika przebiegu choroby. Proponowane rozwiązanie godzi w ideę \\freceptury jako narzędzia wspierającego spersonalizowaną farmakoterapię i grozi stopniowym jej marginalizowaniem w praktyce klinicznej.\\t\\fZamiast ustandaryzowanej listy składów, właściwszym kierunkiem byłoby opracowanie zaleceń lub wzorcowych receptur, które mogłyby pełnić funkcję referencyjną, nie zaś normatywną. Jednocześnie należy zagwarantować preskryptorom i farmaceutom odpowiednią swobodę w zakresie doboru składu leku recepturowego, przy zachowaniu wysokich standardów jakości i bezpieczeństwa\\tUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku finansowania określonych preparatów \\fwymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono przypadki preskrypcji leków recepturowych niezgodnie z aktualna wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji i stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną.\\n\\tOkręgowa Izba Aptekarska w Krakowie\\tArt. 1 pkt 2 lit. f projektu odnoszący się do art. 6 ust. 11 i 12 ustawy refundacyjnej \\tWykreślenie proponowanej zmiany z nowelizacji\\tLeki recepturowe to często receptury ustalane przez lekarza dla konkretnego pacjenta. Lekarz ma możliwość modyfikacji składu, biorąc np. pod uwagę alergie pacjenta. Jako przykład podajmy globulki dopochwowe z antybiotykiem, których skład lekarz może ustalać w oparciu o aktualną wiedzę medyczną ale również wyniki badań pacjentki (antybiorgram, mykogram) oraz występujące alergie na leki. Natomiast receptariusz z zasady zawęża możliwości lekarza, do dobrania terapii konkretnie do potrzeb danego pacjenta. Jest więc to działania na niekorzyść pacjenta i obniżające jakość usług zdrowotnych do niego skierowanych ze strony państwa.  Do leczenia pacjenta gotowymi recepturami lekarz ma leki gotowe. Receptariusz sprowadza recepturę apteczną do poziomu leku gotowego.   Dodatkowo leki recepturowe niekiedy wyprzedzają kompozycje leków \\fgotowych dając lekarzowi szersze możliwości terapeutyczne. Istnieje realne zagrożenie, że wprowadzony receptariusz byłby martwą listą, nie aktualizowaną systematycznie, stworzoną przez zbyt wąskie grono ekspertów, co nie dawałoby gwarancji jakości zawartych w nim receptur. A co w konsekwencji znowu ograniczałoby dostęp pacjenta do leku.  Na koniec należy zauważyć, że niemożliwym jest uwzględnienie w receptariuszu wszystkich receptur leków robionych, które mogą być stosowane.\\t\\fUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku finansowania określonych preparatów wymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono \\fprzypadki preskrypcji leków recepturowych niezgodnie z aktualna wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji i stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną.\\n\\tUrząd Rejestracji Produktów Leczniczych Wyrobów Medycznych i Produktów Biobójczych\\tArt. 1 pkt 2 lit. f projektu odnoszący się do art. 6 ust. 12 ustawy refundacyjnej\\tJednocześnie, w odniesieniu do upoważnienia zawartego w art. 6 ust. 12 ustawy z dnia 12 maja 2011 r. o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych (art. 1 ust. 2 lit. f projektu) do określenia receptariusza leków recepturowych finansowanych ze środków publicznych, uprzejmie informujemy, że Farmakopea Polska w dziale ponad 100 monografii narodowych (tzn. nieposiadających odpowiedników w Farmakopei Europejskiej) zawiera monografie dla preparatów, które mogą być sporządzane w aptece (ok. 60 preparatów galenowych, jak maści, preparaty płynne, 16 monografii dla mieszanek ziołowych). Monografie takie zwierają skład danego preparatu, sposób sporządzenia i wymagania jakościowe (badanie tożsamości, czystości, zawartości).\\t\\tUwaga niezasadna Receptariusz będzie określał wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny, a nie możliwych do sporządzenia w aptece. \\n\\tBusiness Centre Club/ Związek Aptek \\fFranczyzowych/ Pracodawcy RP \\t\\fArt. 1 pkt 2 lit. f projektu odnoszący \\fsię do art. 6 ust. 11 i 12 ustawy refundacyjnej\\t\\fWykreślenie proponowanych zmian\\tZ jednej strony należy bardzo pozytywnie ocenić inicjatywę utworzenia receptariusza jako wyznaczenia \\fpewnego standardu w obszarze wykonywania leków recepturowych. Z drugiej strony uzależnienie tego czy taki lek będzie refundowany od tego czy występuje on w receptariuszu stanowi nadmierne ograniczenie oraz stoi w sprzeczności z naturą leku recepturowego. Lek recepturowy bowiem jest odpowiedzią na bardzo specyficzne potrzeby pacjentów, gdzie osoba wystawiająca receptę decyduje o takiej a nie innej formie leczenia – może to być inna dawka leku niż leku gotowego, może to być inna postać, ale i inny skład. Jednocześnie taki lek jest indywidualnie dostosowany do potrzeb pacjenta i bardzo trudno określić katalog takich leków, które mogłyby być przepisane pacjentowi. A jeżeli pacjent będzie wymagał leczenia lekiem robionym spoza katalogu? Wobec powyższego wydaje się zasadnym by receptariusz funkcjonował jako dobra praktyka mająca na celu uświadamianie czym jest receptura i jakie leki mogą być przepisane na receptach. Rola receptariusza powinna być jednak edukacyjna i promocyjna w obszarze receptury, nie może ona być jednak ograniczająca do zamkniętego katalogu leków robionych, które pacjent może otrzymać w aptece.  Uzasadnienie Związek Aptek Franczyzowych  Utworzenie receptariusza jako dobrej praktyki jest to inicjatywa słuszna i może przyczynić się do propagowania receptury oraz spowodować większą \\fpewność preskrypcji takich leków oraz ich wykonywania – w tym ich wyceny w aptece. Jednak patrząc na rolę leku robionego i jego przyjętą przez lata definicję nie sposób się zgodzić by receptariusz był dokumentem, od którego zależy to czy dany lek robiony będzie mógł podlegać refundacji – od tego jest lista gotowych leków refundowanych. Leki robione służą do indywidualizacji terapii – pozwalają one osobie wystawiającej receptę na taki dobór składników i/lub dawek, które są najbardziej dopasowane do potrzeb danego pacjenta. Nie może być więc sytuacji, gdy np. lekarz na bazie swojej wiedzy i doświadczenia oraz znajomości potrzeb zdrowotnych pacjenta wypisuje lek robiony, którego nie ma w receptariuszu, a pacjent jest zmuszony ponieść całkowity koszt takiego leku.\\t\\fUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze \\fśrodków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku finansowania określonych preparatów wymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono przypadki preskrypcji leków recepturowych niezgodnie z aktualna wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji i stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną.\\n\\tWiseMed – agencja marketingu medycznego\\tArt. 1 pkt 2 lit. f projektu odnoszący się do art. 6 ust. 11 i 12 ustawy refundacyjnej\\t\\tProponujemy rezygnację z wprowadzenia zmian projektowanych w art. 1 pkt 2 lit. f\\tProjektodawca zakłada wprowadzenie przepisów umożliwiających opracowanie przez Ministra Zdrowia receptariusza leków recepturowych stosowanych w danych dziedzinach medycyny. Choć intencją jest zapewnienie jakości i ujednolicenie preskrypcji, zaproponowane rozwiązanie budzi poważne wątpliwości i może prowadzić do realnych ograniczeń terapeutycznych. Po pierwsze, wiązanie dostępności refundacji z konkretną „dziedziną medycyny” może oznaczać, że surowce zostaną przypisane do kompetencji tylko wybranych specjalistów, co z kolei ograniczy możliwości preskrypcji w podstawowej opiece zdrowotnej, pediatrii czy dermatologii. Uderzy to szczególnie w praktykę recepturową w \\fmniejszych miejscowościach, gdzie dostęp do lekarzy specjalistów bywa ograniczony. Po drugie, wprowadzenie takiego receptariusza w postaci rozporządzenia spowoduje dodatkowe obciążenie legislacyjne – każda zmiana w zakresie dostępności surowców farmaceutycznych (np. pojawienie się nowych substancji) czy rejestracji nowych leków gotowych wpływających na zasadność receptury (np. nowe, niższe stężenie lub dawka leku refundowanego) będzie wymagała nowelizacji aktu wykonawczego. To ryzyko opóźnień, chaosu prawnego i spadku elastyczności systemu. Receptura apteczna z definicji powinna być obszarem elastycznym, szybko reagującym na potrzeby kliniczne. Sztywne przypisanie konkretnych receptur do dziedzin medycyny i zamknięcie katalogu refundacyjnego może prowadzić do znacznego ograniczenia indywidualizacji terapii i pogorszenia dostępności leczenia, szczególnie w populacjach specjalnych – dzieci, pacjentów z rzadkimi chorobami czy nietolerancjami. Z powyższych względów postulujemy z projektu art. 1 pkt 2 lit. f jako nadmiernie restrykcyjnego, nietransparentnego i potencjalnie szkodliwego dla praktyki recepturowej w Polsce.\\t\\fUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku \\ffinansowania określonych preparatów wymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono przypadki preskrypcji leków recepturowych niezgodnie z aktualna wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji i stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną.   \\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 2 lit. f projektu odnoszący się do art. 6 ust. 11 i 12 ustawy refundacyjnej\\t\\tWykreślenie proponowanych zmian\\tZ jednej strony należy bardzo pozytywnie ocenić inicjatywę utworzenia receptariusza jako wyznaczenia pewnego standardu w obszarze wykonywania leków recepturowych. Z drugiej strony uzależnienie tego czy taki lek będzie refundowany od tego czy występuje on w receptariuszu stanowi \\fnadmierne ograniczenie oraz stoi w sprzeczności z naturą leku recepturowego. Lek recepturowy bowiem jest odpowiedzią na bardzo specyficzne potrzeby pacjentów, gdzie osoba wystawiająca receptę decyduje o takiej a nie innej formie leczenia – może to być inna dawka leku niż leku gotowego, może to być inna postać, ale i inny skład. Jednocześnie taki lek jest indywidualnie dostosowany do potrzeb pacjenta i bardzo trudno określić katalog takich leków, które mogłyby być przepisane pacjentowi. A jeżeli pacjent będzie wymagał leczenia lekiem robionym spoza katalogu? Wobec powyższego wydaje się zasadnym by receptariusz funkcjonował jako dobra praktyka mająca na celu uświadamianie czym jest receptura i jakie leki mogą być przepisane na receptach. Rola receptariusza powinna być jednak edukacyjna i uświadamiająca w obszarze receptury, nie może ona być jednak ograniczająca do zamkniętego katalogu leków robionych, które pacjent może otrzymać w aptece\\t\\fUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. \\fPodobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego.\\n\\tOsoby fizyczne - pismo zbiorowe\\tArt. 1 pkt 2 lit. f projektu odnoszący się do art. 6 ust. 12 ustawy refundacyjnej\\tZ największym niepokojem przyjmujemy propozycję zawartą w art. 1 pkt 2 lit. f projektu, która zakłada dodanie do art. 6 ustawy o refundacji ust. 12 w brzmieniu: „12. Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, receptariusz leków recepturowych finansowanych ze środków publicznych, stosowanych w danych dziedzinach medycyny, mając na względzie potrzebę zapewnienia odpowiedniej jakości i \\fskuteczności leku recepturowego oraz wspomagania i ujednolicania preskrypcji leków recepturowych.”. Z uzasadnienia Projektu wynika, że wprowadzenie receptariusza jest odpowiedzią Ministerstwa na postulaty organizacji zrzeszających lekarzy, dotyczące problemów z kwestionowaniem przez Narodowy Fundusz Zdrowia (NFZ) recept na leki recepturowe, co skutkowało nakładaniem dotkliwych kar finansowych na medyków. W pełni rozumiemy potrzebę ochrony lekarzy przed niejasnymi kryteriami kontroli i zapewnienia im bezpieczeństwa prawnego. Jednakże, proponowane rozwiązanie – obligatoryjny, zamknięty katalog receptur warunkujący refundację – jest w naszej ocenie próbą rozwiązania realnego problemu za pomocą narzędzia, które stworzy znacznie więcej nowych problemów, uderzając przede wszystkim w pacjentów i ich prawo do spersonalizowanej terapii. Rozumiemy i popieramy ideę standaryzacji oraz podnoszenia bezpieczeństwa i jakości leków sporządzanych w aptece. Stworzenie dobrze opracowanego receptariusza, jako zbioru wystandaryzowanych i sprawdzonych monografii, będzie stanowić cenne narzędzie edukacyjne i wsparcie dla lekarzy oraz farmaceutów. \\t\\fNasz fundamentalny sprzeciw budzi uzależnienie refundacji leku recepturowego od jego obecności w tymże wykazie. Wprowadzenie obligatoryjnego receptariusza jako kryterium finansowania stoi w sprzeczności z samą istotą leku recepturowego, którą jest terapia spersonalizowana i dostosowana do indywidualnych potrzeb pacjenta, jego wieku, stanu fizjologicznego czy specyfiki schorzenia. \\fW naszej ocenie proponowane rozwiązanie niesie ze sobą następujące zagrożenia: Ograniczenie dostępu pacjentów do spersonalizowanej farmakoterapii. Sztywny, zamknięty katalog refundowanych receptur uniemożliwi lekarzowi ordynację leku o indywidualnie dobranej dawce, unikalnym składzie czy specyficznej postaci, jeśli taka formuła nie znajdzie się w urzędowym wykazie. W praktyce oznacza to pozbawienie wielu pacjentów (m.in. w pediatrii, geriatrii czy dermatologii) jedynej skutecznej formy leczenia. Osłabienie roli receptury jako elementu bezpieczeństwa lekowego państwa. Receptura apteczna jest kluczowym narzędziem pozwalającym na zabezpieczenie ciągłości farmakoterapii w sytuacjach kryzysowych, takich jak niedobory lub całkowity brak leków gotowych na rynku. Ograniczenie jej stosowania osłabi zdolność systemu ochrony zdrowia do reagowania na takie sytuacje. Ograniczenie autonomii zawodowej lekarza. Narzucenie zamkniętego wykazu leków \\frecepturowych decydującego o refundacji ograniczy lekarzom możliwość elastycznego doboru składników, dawek i postaci, co jest kluczowe w indywidualizacji terapii. Zahamowanie rozwoju i innowacyjności w recepturze aptecznej. Uzależnienie refundacji od obecności składników w receptariuszu, aktualizowanym – jak można zakładać – relatywnie rzadko, drastycznie utrudni wprowadzanie do praktyki nowych, innowacyjnych surowców farmaceutycznych. Okres niezbędny na wprowadzenie nowego surowca do terapii refundowanej wydłuży się o czas potrzebny na jego rejestrację (zgodnie z Raportem ministerialnego zespołu ds. preskrypcji i realizacji recept z 2024, wydanie pozwolenia na dopuszczenie do obrotu surowca farmaceutycznego może trwać nawet do 24 miesięcy), a następnie o dodatkowy czas oczekiwania na aktualizację ministerialnego rozporządzenia wprowadzającego receptury do receptariusza. Pogłębienie problemów biurokratycznych i niechęci do wykonywania leków recepturowych. Ewentualny podział na leki recepturowe \\frefundowane i nierefundowane stworzy pole do licznych problemów interpretacyjnych dla lekarzy, farmaceutów oraz organów kontrolujących (NFZ ,WIF), generując niepotrzebne spory i obciążenia administracyjne. , proponujemy rozważenie następujących rozwiązań alternatywnych dla zapisu z art. 6 ust. 12: Stworzenie receptariusza o charakterze rekomendacyjnym. Receptariusz mógłby funkcjonować jako zbiór zalecanych, wystandaryzowanych i sprawdzonych receptur, których przepisanie i wykonanie byłoby ułatwione proceduralnie i nie podlegałoby kwestionowaniu przez NFZ. Stanowiłoby to cenną pomoc i gwarancję dla lekarzy i farmaceutów, ale nie wykluczałoby możliwości refundacji leków sporządzanych poza receptariuszem, jeśli ich zastosowanie jest medycznie uzasadnione. Rozwiązanie rzeczywistego problemu, czyli doprecyzowanie zasad ordynacji i kontroli refundacyjnej leków recepturowych. Zamiast tworzyć sztywny katalog, należy wypracować jasne i transparentne kryteria oceny prawidłowości preskrypcji przez NFZ. Takie \\fdziałanie, podjęte w dialogu ze środowiskiem lekarskim i farmaceutycznym, realnie zabezpieczyłoby lekarzy przed ryzykiem finansowym, nie ograniczając jednocześnie dostępu pacjentów do leczenia.\\t\\fUwaga niezasadna. Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków \\fpublicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku finansowania określonych preparatów wymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono przypadki preskrypcji leków recepturowych niezgodnie z aktualna wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji i stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną. \\n\\tIzba Gospodarcza FARMACJA POLSKA\\tArt. 1. pkt 2 lit. f odnoszący się do art. 6 ust. 12 ustawy o refundacji\\tWnioski  1)\\tWprowadzenie receptariuszy leków recepturowych może zatrzymać rozwój gałęzi leków recepturowych, ograniczenie dostępności nowoczesnych i innowacyjnych substancji, może być fatalne w skutkach. 2)\\tWprowadzanie nowych receptur, które nie zdążyły znaleźć się w receptariuszu będzie skutkowało brakiem refundacji, tzn. ograniczamy prawa pacjenta w dostępnie do nowych możliwości terapeutycznych. 3)\\tLek recepturowy często wypełnia lukę w dostępności preparatu w postaci leku gotowego (małe zapotrzebowanie, brak możliwości technologicznych w przygotowaniu leku gotowego). 4)\\tWybór leku recepturowego przez lekarza jest nierzadko jedyną alternatywą w leczeniu wielu chorób, czy u pacjentów z alergiami lub brakiem tolerancji na składniki. 5)\\tDawanie gotowców lekarzom w postaci zatwierdzonych składów w receptariuszu ograniczy możliwości terapeutyczne pacjentów, jak również ograniczy możliwości lekarza w stosowaniu spersonalizowanego leczenia. 6)\\tRządowe zapowiedzi deregulacji prawa nijak się mają do propozycji wprowadzania dodatkowych regulacji, w \\fdodatku powiązanych z prowadzeniem działań merytorycznych w leczeniu. Jedne receptury będą refundowane, inne nie.  \\t\\fWprowadzenie delegacji ustawowej umożliwiającej Ministrowi Zdrowia wprowadzenie receptariusza   Uwaga dotyczy zmiany zaproponowanej przez Ministerstwo Zdrowia zawartej w art. 1 pkt 2)                     lit. f) Projektu Ustawy Zmieniającej poprzez dodanie w art. 6 ustępu 12 Ustawy Refundacyjnej o treści:  „12.Minister właściwy do spraw zdrowia określi, w drodze rozporządzenia, receptariusz leków recepturowych finansowanych ze środków publicznych, stosowanych w danych dziedzinach medycyny, mając na względzie potrzebę zapewnienia odpowiedniej jakości i skuteczności leku recepturowego oraz wspomagania i ujednolicania preskrypcji leków recepturowych.” Jednym z fundamentów rozwoju produkcji leków recepturowych jest możliwość dostosowania dawki substancji czynnej do potrzeb, wieku i stanu chorobowego pacjenta.  Umożliwiają to  m.in.  innowacyjne i nowoczesne surowce oraz terapie. Nowe substancje wspomagają proces personalizacji terapii zwalczających \\fzwłaszcza rzadkie choroby, uśmierzających ból czy leczących jego przyczynę. Należy zauważyć, że receptura apteczna jest najbardziej rozwinięta w krajach takich jak USA, Szwajcaria, Włochy. Nie jest to przypadek, a odzew na wzrost potrzeby indywidualizacji terapii. Niestety, przez  wprowadzenie receptariusza leków recepturowych, zgodnie z którym refundowane będą wyłącznie leki o podanym składzie, może dojść do wielkiego ograniczenia dostępności nowoczesnych terapii i  upadnie jeden z największych atutów leku recepturowego – możliwość dostosowania dawki substancji czynnej do potrzeb, wieku i stanu chorobowego pacjenta. Nawet powołanie specjalnej  komisji złożonej z najwybitniejszych przedstawicieli  środowiska lekarskiego i medycznego nie jest w stanie sporządzić idealnego  receptariusza w leczeniu chorób rzadkich i współistniejących.  Uważamy, że to do lekarza prowadzącego powinno należeć ostatnie słowo,  jakie procedury  i leki zastosować przy danej terapii, a lekarzowi  temu  należy dostarczyć  jak najwięcej narzędzi w procesie leczenia, a nie wiązać ręce sztywnymi procedurami oraz receptariuszami.  Leczenie Chorób Rzadkich   Choroby dotykające niewielkiej części pacjentów często nie mają dedykowanych leków gotowych na \\frynku. W takich wypadkach, leki recepturowe stają się nieocenionym wsparciem dla pacjenta. Dzięki możliwości dostosowania terapii do indywidualnych potrzeb, ryzyko wystąpienia działań niepożądanych zmniejsza się do minimum. Jest to pomocne zwłaszcza w walce z chorobami współistniejącymi, gdy niedokładne dobranie substancji,  na skutek konieczności korzystania z receptariusza,  może pogłębić inne schorzenie. Powstanie receptariusza refundowanych leków recepturowych przeczy idei leku recepturowego jako leku, który uwzględnia indywidualne potrzeby pacjenta. Np. jeśli będziemy mieć refundowaną recepturę na proszki dzielone z laktozą, a pacjent ma nietolerancję laktozy i musi dostać proszki z glukozą lub z glukonianem wapnia, których nie ma w receptariuszu, bo są rzadko wykonywane, to będzie miał je pełnopłatne? Co w przypadku receptury pediatrycznej? Gdzie lek komponuje się nie tylko wg wieku, ale wagi dziecka, z uwzględnieniem alergii i rozmaitych nietolerancji. Czy wszystkie warianty leku będą uwzględnione w receptariuszu?  Leczenie bólu Ból jest jednym z najczęściej występujących objawów chorób. Tradycyjne leki często nie są wystarczające w łagodzeniu silnego bólu, a pacjent często uodparniają się na \\fich działanie. Dlatego właśnie leki recepturowe zrobione z nowoczesnych surowców farmaceutycznych są niezbędne w zapewnieniu choremu ulgi.  Nakładanie ram  receptariuszem może to uniemożliwiać i nie pozwolić np. na uwzględnianie chorób współistniejących. Wykluczy to możliwość zastosowania zindywidualizowanej, jedynie skutecznej terapii.   Leczenie chorób dermatologicznych Choroby dermatologiczne mogą być bardzo uciążliwe dla pacjentów, wpływając na ich komfort życia i samocenę. Ich przewlekłość i nieoczywiste podłoże powoduje, że gotowe leki często zawodzą lub w ekstremalnych przypadkach tworzą nowe problemy. Większa personalizacja i unowocześnienie mogą okazać się przyszłością dla walki z chorobami skóry.  Wprowadzenie receptariusza   spowoduje spadek jakości życia chorego i skuteczności leczenia.\\t\\fUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku finansowania określonych preparatów wymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono przypadki preskrypcji leków recepturowych niezgodnie z aktualną wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji \\fi stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną. \\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tArt. 1. pkt 2 lit. f projektu odnoszący się do art. 6 ust. 12 ustawy o refundacji\\tArt. 1 pkt 2 lit. f Projektu – receptariusz zawierający składy leków recepturowych finansowanych ze środków publicznych  Związek co do zasady pozytywnie ocenia działania zmierzające do wyznaczenia standardów w obszarze wykonywania leków recepturowych. Jednocześnie jednak przyjęcie zamkniętego katalogu składów leków recepturowych podlegających refundacji może skutkować istotnym ograniczeniem dostępu \\fpacjentów do zindywidualizowanych terapii, a wręcz wydaje się stać w sprzeczności z ideą receptury. Leki recepturowe są tworzone z myślą o konkretnym pacjencie, z uwzględnieniem jego unikalnych potrzeb terapeutycznych, i niejednokrotnie stanowią jedyną, dostępną formę leczenia dla niektórych z nich. W ocenie Związku receptariusz powinien więc pełnić funkcję referencyjną, a nie normatywną, nie ograniczając tym samym katalogu leków robionych dostępnych w aptece.\\t\\tUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać \\foczekiwania finansowania ze środków publicznych każdego leku recepturowego. Biorąc pod uwagę, iż receptariusz przygotowany zostanie z udziałem klinicystów przez co zagwarantowana zostanie zgodność z aktualną wiedza medyczną obawy dotyczące braku finansowania określonych preparatów wymaganych w danych dziedzinach medycyny należy uznać za nieuzasadnione. Co więcej z posiadanych przez Ministra Zdrowia informacji wynika, iż w ostatnim czasie stwierdzono przypadki preskrypcji leków recepturowych niezgodnie z aktualna wiedzą medyczną co skutkowało zakwestionowaniem refundacji tych preparatów ze środków publicznych. Wprowadzenie receptariusza pozwoli uniknąć w przyszłości podobnych sytuacji i stanowiło będzie gwarancję leczenia pacjenta zgodnie z aktualną wiedzą medyczną.\\n\\tNaczelna Izba Aptekarska\\tArt. 1. pkt 2 lit. f projektu odnoszący się do art. 6 ust. 12 ustawy o refundacji\\tnależy rozważyć zasadność i zakres zmiany w art. 1 pkt 2 lit. f, polegającej na dodaniu w art. 6 ust. 12 ustawy o refundacji leków, zawierającego upoważnienia Ministra Zdrowia do określenia w drodze rozporządzenia receptariusza leków recepturowych.\\tProponowany przepis budzi istotne wątpliwości merytoryczne i systemowe. Jego wprowadzenie może stanowić nadmierną ingerencję w samą istotę zawodów farmaceuty i lekarza, które opierają się m.in. na indywidualnym podejściu do pacjenta oraz elastyczności w zakresie doboru składu i postaci leku recepturowego, zgodnie z potrzebami klinicznymi konkretnego pacjenta. Zgodnie z definicją, lek recepturowy jest wytwarzany na podstawie jednostkowego zlecenia lekarskiego i dopasowany do indywidualnych wskazań. Ustanowienie sztywnego \\fwykazu, nawet o charakterze pomocniczym, może w praktyce prowadzić do sytuacji, w której preparaty spoza receptariusza nie będą kwalifikowane do refundacji. To z kolei niesie ryzyko ograniczenia dostępności leczenia, zwłaszcza w przypadkach niestandardowych, rzadkich lub wymagających terapii spersonalizowanej. Należy także zauważyć, że skład leków recepturowych ulega ciągłym zmianom, wynikającym z postępu wiedzy, dostępności surowców farmaceutycznych, rozwoju technologii wytwarzania i zmieniających się rekomendacji klinicznych. Stworzenie pełnego, aktualnego i zarazem wystarczająco elastycznego receptariusza w formie rozporządzenia wydaje się bardzo trudne. Niezbędna byłaby bowiem jego częsta nowelizacja, a opóźnienia w tym zakresie mogłyby wprost prowadzić do stosowania przestarzałych lub nieadekwatnych rozwiązań terapeutycznych.\\t\\fUwaga niezasadna Receptariusz określać będzie wykaz leków recepturowych finansowanych ze środków publicznych w danych dziedzinach medycyny. Wprowadzenie receptariusza ma na celu racjonalizację wydatków płatnika publicznego na finansowanie leków recepturowych. Podobnie jak nie wszystkie leki gotowe są finansowane ze środków publicznych, tak również za niezasadne należy uznać oczekiwania finansowania ze środków publicznych każdego leku recepturowego.\\n\\tZwiązek Pracodawców Polska Dystrybucja Farmaceutyczna\\tart. 1 pkt 4 lit. a projektu odnoszący się do art. 7 ust 1 ustawy refundacyjnej\\tProponowane jest wprowadzenie mechanizmu automatycznej waloryzacji wysokości minimalnej marży hurtowej. Tym samym art. 1 ust. 4 lit. a) Projektu uzyskałby następujące brzmienie: „Ustala się urzędową marżę hurtową w wysokości 6% ceny zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, nie niższą niż 0,018% minimalnego wynagrodzenia za pracę określonego na podstawie przepisów o \\fminimalnym wynagrodzeniu za pracę i nie wyższą niż: 1) 150 zł - w przypadku, o którym mowa w art. 6 ust. 1 pkt 1; 2) 2000 zł - w przypadkach, o których mowa w art. 6 ust. 1 pkt 2 i 3.”  Alternatywnie, proponujemy rozważenie wprowadzenia mechanizmu automatycznej waloryzacji wysokości minimalnej marży hurtowej wynoszącej 80 gr o 3% w skali roku. W tym rozwiązaniu art. 1 ust. 4 lit. a) Projektu pozostaje bez zmian, ale dodaje się do art. 1 ust. 4 nową lit. b) dodającą do art. 7 Ustawy refundacyjnej nowy ust. 1b, 1c oraz 1d:  Art. 7: „1b. Minimalna wysokość marży hurtowej, o której mowa w ust. 1 podlega corocznej waloryzacji. Waloryzacja dokonywana jest na dzień 1 stycznia. 1c. Wskaźnik waloryzacji wynosi 3% wartości minimalnej marży hurtowej za rok poprzedzający. 1d. Kwotę marży zaokrągla się do pełnego grosza w górę.\\t\\fKoszty prowadzenia działalności w hurtowym obrocie produktami leczniczymi nieustannie rosną – obejmują w szczególności wynagrodzenia, energię, transport, utrzymanie infrastruktury oraz zapewnienie zgodności z rygorystycznymi wymogami bezpieczeństwa i jakości. Nieustanny wzrost kosztów działalności hurtowni farmaceutycznych opiera się m.in. na: \\f• wzroście płac – zgodnie z danymi ZUS w latach 2014-2025 płaca minimalna wzrosła o 177% (prawie trzykrotny wzrost), zaś przeciętnie wynagrodzenie o ponad 116% (ponad dwukrotny wzrost); • wzroście kosztów transportu – zgodnie z danymi PKN Orlen hurtowa cena oleju napędowego na koniec 2024 r. była o niemal 42% wyższa niż cena w 2014 r.; • wzroście kosztów funkcjonowania magazynów – zgodnie z danymi URE średnia roczna cena energii wzrosła pomiędzy 2014 a 2024 r. o 217% (ponad trzykrotny wzrost), (szczegółowe zestawienie danych o kosztach stanowi załącznik nr 1 ).  Tymczasem, obecna konstrukcja ustawy refundacyjnej w zakresie kwotowego określenia minimalnej marży hurtowej \\fnie przewiduje dostosowywania tej marży do rosnących kosztów. Zmiana kwotowej wartości marży minimalnej każdorazowo będzie wymagała ustawowej nowelizacji co oznacza, że takie rozwiązanie jest nadmiernie sztywne, nieefektywne i nieprzystosowane do dynamicznego otoczenia gospodarczego. Brak elastycznego mechanizmu dostosowawczego w zakresie minimalnej marży hurtowej prowadzi do systematycznego pogarszania się rentowności działalności hurtowni farmaceutycznych, co może zagrażać stabilności łańcucha dostaw leków refundowanych. Zasadne jest zatem wprowadzenie mechanizmu automatycznej waloryzacji minimalnej urzędowej marży hurtowej, opartej na wskaźniku wzrostu minimalnego wynagrodzenia za pracę. Minimalne wynagrodzenie odzwierciedla realne zmiany kosztów pracy i stanowi jasny, obiektywny oraz społecznie akceptowany punkt odniesienia dla automatycznej aktualizacji marży. Ministerstwo Zdrowia zaproponowało w Projekcie podniesienie minimalnej marży hurtowej do poziomu 80 gr. co jest krokiem w kierunku urentownienia dystrybucji produktów refundowanych. Przestawiona przez związek PLDF propozycja zastąpienia stałej kwoty wskaźnikiem 0,018% minimalnego wynagrodzenia za pracę (według stawki na 2025 r. minimalna marża hurtowa wyniosłaby 83 gr) jest krokiem dalej mającym zapewnić dostosowywanie wysokości marży minimalnej do \\fzmieniających się kosztów ponoszonych przez hurtownie farmaceutyczne, realizujące obrót produktami refundowanymi. Alternatywnie rozważyć można mechanizm automatycznej, corocznej waloryzacji minimalnej marży hurtowej.  Wprowadzenie takiego rozwiązania przyniesie liczne korzyści: a) zapewni większą przewidywalność i stabilność finansową podmiotów hurtowych, b) zlikwiduje potrzebę czasochłonnych nowelizacji ustawowych, c) zwiększy odporność systemu dystrybucji leków refundowanych na zmiany ekonomiczne.  Do powyższej argumentacji należy również dodać, że od roku 2014 tylko raz wprowadzono zmianę w wysokości urzędowej marży hurtowej – w 2023 r. podwyższono wysokość urzędowej marży hurtowej o 1 punkt procentowy, z poziomu 5% do poziomu 6% (wzrost o 20%) oraz wprowadzono minimalną marżę hurtową na poziomie 50 gr. Przez te lata hurtownie doznały gigantycznego wzrostu kosztów działalności operacyjnej, co negatywnie przełożyło się na rentowność. Wartość marży hurtowej na lekach refundowanych rosła wolniej, ze względu na efektywne prowadzenie negocjacji przez Ministerstwo Zdrowia. Ceny produktów refundowanych w Polsce są jednymi z najniższych w Europie. Marża hurtowa liczona od wynegocjowanych cen produktów jest zatem także \\fodpowiednio niższa. W konsekwencji nawet podniesienie wysokości marży hurtowej o 1 pp. w 2023 r. nie pozwoliło na zrównoważenie wzrostu kosztów prowadzenia działalności hurtowej. Z tego powodu tak istotne jest aby w ustawie pojawiły się mechanizmy waloryzacyjne umożliwiające poprawę rentowności tak krytycznej dla państwa i społeczeństwa dystrybucji leków refundowanych.\\t\\fUwaga niezasadna Wprowadzenie automatyczne waloryzacji jest rozwiązaniem, które z każdym rokiem będzie powodowało większe koszty dystrybucji produktów refundowanych zwiększając koszt samej refundacji. Należy też zauważyć, że refundacja nie jest jedyną gałęzią, na której opierają swoją dzialność hurtownie farmaceutyczne, które obracają również lekami pełnopłatnymi \\fw tym OTC, nierefundowanymi wyrobami medycznymi. \\n\\tIzba Gospodarcza \\\"FARMACJA POLSKA\\\"\\tArt. 1 pkt 4 lit. a projektu odnoszący się do art. 7 ust. 1 ustawy refundacyjnej\\tzasadne jest wprowadzenie mechanizmu corocznej waloryzacji minimalnej marży hurtowej w stałej wysokości 3%.\\t6)\\tArt. 7 ust. 1 – minimalna marża hurtowa Proponowane w projekcie ustawy jednorazowe podniesienie marży do poziomu 80 groszy to krok w dobrym kierunku, jednak nie zabezpiecza ono długofalowej rentowności działalności dystrybucyjnej, szczególnie dla tanich produktów. W warunkach rosnących kosztów operacyjnych i presji inflacyjnej, utrzymywanie stałej minimalnej marży hurtowej staje się rozwiązaniem niewystarczającym dla zapewnienia stabilności finansowej hurtowni farmaceutycznych.  Z uwagi na skuteczne procesy negocjacyjne Ministerstwa Zdrowia ceny produktów refundowanych w Polsce należą do jednych z najniższych. Hurtownie farmaceutyczne dystrybuują tanie produkty refundowane stosując ustawową marżę hurtową, która jest proporcjonalna do niskiej ceny. Dla najtańszych produktów marża hurtowa nie pokrywa kosztów dystrybucji, stąd \\fkonieczność zmian w zakresie wysokości ustawowej marży minimalnej. Z powyższych powodów wskazujemy, że zasadne jest wprowadzenie mechanizmu corocznej waloryzacji minimalnej marży hurtowej w stałej wysokości 3%.  Taki mechanizm pozwoli na systematyczne dostosowywanie marży do rosnących kosztów prowadzenia działalności, bez konieczności każdorazowej nowelizacji ustawy. Wzrost o 3% rocznie to rozwiązanie umiarkowane, przewidywalne i łatwe do wdrożenia, które jednocześnie zapewnia realne wsparcie pokrywania rosnących kosztów dla hurtowni funkcjonujących w systemie refundacyjnym.\\t\\fUwaga niezasadna Wprowadzenie automatycznej waloryzacji jest rozwiązaniem, które z każdym rokiem będzie powodowało większe koszty dystrybucji produktów refundowanych zwiększając koszt samej refundacji. Należy też zauważyć, że refundacja nie jest jedyną gałęzią, na której opierają swoją dzielność hurtownie farmaceutyczne, które obracają również lekami pełnopłatnymi w tym OTC, nierefundowanymi wyrobami medycznymi.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 4 lit. a projektu odnoszący się do art. 7 ust. 1 ustawy refundacyjnej\\tWnioskujemy o następujące brzmienie art. 1 ust. 4 lit. a) Projektu:  „Ustala się urzędową marżę hurtową w wysokości 6% ceny zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, nie niższą niż 0,018% minimalnego wynagrodzenia za pracę określonego na podstawie przepisów o minimalnym wynagrodzeniu za pracę i nie wyższą niż: 1) 150 zł - w przypadku, o którym mowa w art. 6 ust. 1 pkt 1; 2) 2000 zł - w przypadkach, o których mowa w art. 6 ust. 1 pkt 2 i 3.” \\tUzasadnienie proponowanej waloryzacji minimalnej marży hurtowej  Podwyższenie minimalnej marży hurtowej odpowiada pilnej potrzebie zwiększenia pokrycia kosztów dystrybucji najtańszych leków refundowanych. Wnioskujemy, aby oprócz jednorazowego podniesienia marży do poziomu 80 groszy, wprowadzić mechanizm jej corocznej waloryzacji. Pozwoli to zapobiec dalszemu spadkowi rentowności dystrybucji w kolejnych latach.  W projekcie nowelizacji ustawy refundacyjnej zaproponowano podniesienie minimalnej marży hurtowej do 80 groszy. Celem tej zmiany jest poprawa dostępności leków refundowanych poprzez zapewnienie \\fopłacalności ich dystrybucji dla hurtowni farmaceutycznych.  Obecna sztywna wysokość marży minimalnej nie nadąża za rosnącymi kosztami prowadzenia działalności, takimi jak wynagrodzenia (wzrost płacy minimalnej), energia, transport, magazynowanie czy spełnianie wymogów bezpieczeństwa i jakości. W rezultacie rentowność hurtowni systematycznie się pogarsza, co może zagrażać stabilności łańcucha dostaw leków refundowanych.  Dodatkowo, obecna konstrukcja ustawy wymaga każdorazowej nowelizacji w celu zmiany wysokości marży minimalnej, co czyni system nieelastycznym i nieprzystosowanym do dynamicznych warunków gospodarczych. Dlatego proponujemy wprowadzenie mechanizmu automatycznej waloryzacji minimalnej marży hurtowej, powiązanego ze wzrostem minimalnego wynagrodzenia za pracę. Taki wskaźnik jest przejrzysty, obiektywny i społecznie akceptowalny, a jednocześnie dobrze odzwierciedla zmiany kosztów pracy – jednego z kluczowych składników kosztów działalności hurtowni.  Wprowadzenie tego rozwiązania przyniesie szereg korzyści: zapewni większą stabilność finansową hurtowniom w kolejnych latach, wyeliminuje konieczność częstych nowelizacji ustawy aby \\fdostosować marżę minimalną do wzrostu kosztów, zwiększy odporność systemu dystrybucji leków refundowanych na zmiany ekonomiczne.\\t\\fUwaga niezasadna Wprowadzenie automatycznej waloryzacji jest rozwiązaniem, które z każdym rokiem będzie powodowało większe koszty dystrybucji produktów refundowanych zwiększając koszt samej refundacji. Należy też zauważyć, że refundacja nie jest jedyną gałęzią, na której opierają swoją dzielność hurtownie farmaceutyczne, które obracają również lekami pełnopłatnymi w tym OTC, nierefundowanymi wyrobami medycznymi.\\n\\tZwiązku Pracodawców Hurtowni Farmaceutycznych\\tart. 7 ust. 3 ustawy refundacyjnej\\tArtykuł 7 ustęp 3 otrzymuje brzmienie:  Marża, o której mowa w ust. 1, może być dzielona pomiędzy przedsiębiorców prowadzących obrót hurtowy, z zastrzeżeniem, że marża ta nie może być pobierana przez: Wnioskodawców prowadzących obrót hurtowy,  Przedsiębiorców prowadzących obrót hurtowy należących do tej samej co Wnioskodawca grupy kapitałowej w rozumieniu ustawy z dnia 16 lutego 2007 r. o ochronie konkurencji i konsumentów,  Przedsiębiorców prowadzących obrót hurtowy na podstawie umowy o wyłącznej dystrybucji produktów objętych refundacją.  Podmioty wymienione w punktach 1), 2) i 3) powyżej mają prawo pobierać marżę hurtową wyłącznie w przypadku bezpośredniego zaopatrzenia podmiotów uprawnionych do obrotu detalicznego. \\t1.\\tWielu producentów leków prowadzi własne hurtownie farmaceutyczne, które zaopatrują inne hurtownie zatrzymując część marży hurtowej. Zmniejsza to znacząco możliwość wykorzystania pełnej marży hurtowej w wysokości 6 % przez hurtownie, które dostarczają te leki do wszystkich aptek w kraju. 2.\\tMarża hurtowa powinna gwarantować pokrycie kosztów przyjmowania, magazynowania i dystrybucji każdego opakowania produktu refundowanego aby zapewnić przedsiębiorcy prowadzącemu hurtownię farmaceutyczną środki niezbędne do prowadzenia działalności i spełniania wymagań jakościowych. Koszty „obsługi produktu” są w dużym stopniu proporcjonalne do ceny produktu, co uzasadnia marżę w ujęciu procentowym. Proporcjonalny wzrost kosztów „obsługi produktu” przy wzroście jego ceny wynika głównie z proporcjonalnego do ceny wzrostu kosztu finansowania zakupu i utrzymywania zapasów (oprocentowanie kredytów) oraz kredytowania sprzedanych już produktów, a także wzrostu obciążeń wynikających z \\fnieuniknionych uszkodzeń produktów podczas dystrybucji. Przy najtańszych produktach marża procentowa nie pokrywa kosztów, dlatego należy określić minimalną kwotową wartość marży pokrywającą przynajmniej znaczną część kosztu dystrybucji hurtowej danego produktu. Szacowane straty marży hurtowej w skali roku mieszczą się w przedziale 60 - 70 mln PLN co stanowi 0,5% całkowitej marży hurtowej\\t\\fUwaga niezasadna  Rozwiązanie wiąże się z nadmiernym komplikowaniem systemu obrotu produktami refundowanymi i koniecznością każdorazowej weryfikacji, czy dana hurtownia należy do tej samej grupy kapitałowej co wnioskodawca albo czy hurtownia ma podpisaną umowę o wyłącznej dystrybucji produktów objętych refundacją.  .\\n\\tZwiązek Pracodawców Polska Dystrybucja Farmaceutyczna\\tart. 1 pkt 4 lit. b projektu odnoszący się do art. 7 ust 1a ustawy refundacyjnej\\tRezygnacja z dodania do art. 7 ustępu 1a w Ustawie o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych, a w konsekwencji nieobjęcie surowców, utensyliów oraz leków gotowych, traktowanych jako surowce farmaceutyczne urzędową marżą hurtową.\\tCelem ustawodawcy jest zwiększenie przejrzystości i poprawności rozliczania refundacji produktów takich jak surowce farmaceutyczne, utensylia i leki gotowe, które mogą być traktowane jako surowce poprzez objęcie ich bardziej szczegółowymi mechanizmami nadzoru. Zmiany miały zapobiegać celowemu zawyżaniu cen składników stosowanych w recepturze co (przy braku limitów finansowania) skutkowało zawyżonymi dopłatami za leki recepturowe przez płatnika publicznego.  Należy wskazać, że zamierzony przez ustawodawcę cel regulacyjny – czyli ograniczenie nieprawidłowości i nadużyć refundacyjnych – zostanie osiągnięty poprzez samo wprowadzenie limitu finansowania na ww. kategorie produktów, bez potrzeby nakładania na hurtownie farmaceutyczne sztywnej marży.  Wprowadzenie limitu finansowania pozwala precyzyjnie określić maksymalny poziom refundacji dla \\fdanego produktu lub grupy produktów, co: a) wyznacza jasną granicę odpowiedzialności płatnika publicznego, b) skłania hurtownie farmaceutyczne do konkurowania ceną uwzględniając limity finansowania c) motywuje podmioty realizujące recepty do efektywnego zarządzania kosztami zakupu i dystrybucji, d) oraz czyni bezcelowym zawyżanie kosztów jednostkowych produktów.  Należy podkreślić, że wprowadzenie limitów finansowania (przy braku sztywnej marży hurtowej) na surowce farmaceutyczne w 2023 już pozwoliło osiągnąć powyższe cele, co jest dobitnym dowodem braku konieczności określania sztywnej marży hurtowej na składniki receptury.  Z kolei narzucenie sztywnej marży hurtowej w odniesieniu do surowców i utensyliów jest rozwiązaniem nadmiarowym, nieadekwatnym i nieproporcjonalnym z kilku powodów: a) charakter tych produktów różni się zasadniczo od leków gotowych – często są kupowane w różnych wolumenach i z różnych źródeł, a ich marże są kształtowane przez specyfikę zamówień i logistyki. b) sztywna marża może zaburzyć dostępność tych produktów, szczególnie tam, gdzie ich dystrybucja jest kosztowna, a rynek ograniczony. Ponadto jednym z założeń legislacyjnych projektu ustawy jest poprawa rentowności obrotu produktami \\frefundowanymi przez hurtownie farmaceutyczne. Proponowana zmiana taką zapowiedź gwarancji rentowności procesu dystrybucji w istocie poddaje w wątpliwość.  Zamiast tego, zastosowanie limitu finansowania pozwala zachować mechanizmy kontroli i transparentności w rozliczeniach refundacyjnych, bez nadmiernego ingerowania w mechanizmy rynkowe hurtowego obrotu tymi kategoriami produktów.  Projekt w obecnym kształcie może wykreować szereg problemów praktycznych:  Po pierwsze, utensylia do receptury są nabywane także od dostawców innych niż hurtownie farmaceutyczne (obrót utensyliami nie jest ściśle regulowany przez Prawo farmaceutyczne). Proponowana regulacja doprowadzi zatem do sytuacji, w której te same produkty będą mogły być sprzedawane z dowolną marżą poza kanałem dystrybucji hurtowni oraz z marżą sztywną w kanale hurtowym.  Po drugie, projekt nie określa sztywnych cen zbytu dla surowców farmaceutycznych, przez co producent będzie mógł stosować różne ceny zbytu dla różnych hurtowni. Marża hurtowa w praktyce może się zatem istotnie różnić w zależności od dystrybutora.  Po trzecie, apteki ogólnodostępne na etapie zamawiania produktów zazwyczaj \\fnie wiedzą czy dany lek zostanie sprzedany jako gotowy, czy też zostanie wykorzystany do sporządzenia leku recepturowego. Fakt ten spowoduje niejasność, do której sprzedaży należy zastosować marżę sztywną. Wreszcie, obawa o nadmierną wysokość marży hurtowej w przypadku braku jej „usztywnienia” na poziomie ustawowym nie jest uzasadniona. Apteki będą bowiem nabywać produkty od najtańszych dostawców, uruchomiony zostanie zatem mechanizm konkurencji cenowej pomiędzy hurtownikami. Na koniec, należy zauważyć, że Projekt nie jest konsekwentny – zakładając nawet wprowadzenie sztywnej marży hurtowej na utensylia, surowce i leki gotowe wykorzystywane w recepturze, Projekt nie przewiduje mechanizmu marży minimalnej. Tymczasem marża minimalna byłaby szczególnie uzasadniona w odniesieniu do utensylii, mających często bardzo niskie ceny.\\t\\fUwaga niezasadna Wprowadzenie urzędowej marży hurtowej stanowi dodatkowy mechanizm zabezpieczający wydatki płatnika publicznego na refundację leków recepturowych.\\n\\tIzba Gospodarcza „FARMACJA POLSKA” \\tart. 1 pkt 4 lit. b projektu odnoszący się do art. 7 ust 1a ustawy refundacyjnej\\tZamiast wprowadzać sztywną marżę hurtową, która może zakłócić funkcjonowanie rynku i ograniczyć dostępność składników recepturowych, należy pozostać przy mechanizmie limitów finansowania. Jest to rozwiązanie bardziej elastyczne, proporcjonalne i zgodne z zasadami konkurencji, a jednocześnie skutecznie realizujące cel racjonalizacji kosztów refundacji.\\tArt. 7 ust. 1a – urzędowa marża hurtowa dla surowców farmaceutycznych, utensyliów recepturowych oraz leków gotowych, które mogą być traktowane jako surowce farmaceutyczne Jak wskazują członkowie Izby Gospodarczej „FARMACJA POLSKA”, propozycja objęcia sztywną marżą hurtową surowców farmaceutycznych, utensyliów oraz gotowych produktów wykorzystywanych w recepturze budzi poważne wątpliwości zarówno z punktu widzenia skuteczności regulacyjnej, jak i funkcjonowania rynku.  \\fWprowadzenie takiego rozwiązania może przynieść więcej szkód niż korzyści, a jego cel – ograniczenie nadużyć refundacyjnych – można osiągnąć w sposób bardziej proporcjonalny \\ni rynkowo neutralny wprowadzając limity finansowania. Projekt ustawy przewiduje już wprowadzenie limitów finansowania dla składników recepturowych. To narzędzie skutecznie ogranicza możliwość zawyżania cen, ponieważ apteki, chcąc zmieścić się w limicie, będą wybierać najtańsze dostępne surowce. W tym kontekście dodatkowe ograniczenie w postaci sztywnej marży hurtowej jest zbędne i może prowadzić do niepożądanych efektów ubocznych. W odróżnieniu od leków gotowych objętych refundacją, surowce farmaceutyczne nie mają ustawowo ustalonych cen zbytu. Producenci mogą oferować różne ceny różnym hurtowniom, co oznacza, że hurtownia nie ma wpływu na końcową cenę dla apteki. Wprowadzenie sztywnej marży w takim systemie prowadzi do sytuacji, w której hurtownie nie mogą elastycznie reagować na warunki zakupu, co zaburza mechanizmy konkurencji. Warto zauważyć, że dla produktów refundowanych funkcjonuje system marż minimalnych, który zabezpiecza rentowność dystrybucji. W przypadku \\fskładników recepturowych proponuje się natomiast sztywną marżę bez możliwości dostosowania jej do warunków rynkowych, co tworzy nierównowagę i niespójność w systemie refundacyjnym. Sztywna marża uniemożliwia hurtowniom konkurowanie ceną, nawet jeśli uzyskają lepsze warunki handlowe od producentów. W efekcie apteki będą preferować hurtownie z najniższą ceną zakupu, a pozostałe – mimo że mogłyby zaoferować niższą cenę końcową dzięki niższej marży – zostaną wypchnięte z rynku. To prowadzi do koncentracji rynku i ograniczenia dostępu do surowców w niektórych regionach.\\t\\fUwaga niezasadna  Wprowadzenie urzędowej marży hurtowej stanowi dodatkowy mechanizm zabezpieczający wydatki płatnika publicznego na refundację leków recepturowych.\\n\\tIzba Gospodarcza FARMACJA POLSKA\\tArt. 1. pkt 4 lit. b projektu odnoszący się do art. 7 ust. 1a ustawy o refundacji\\tProponowane alternatywne podejście legislacyjne Wprowadzenie mechanizmu minimalnej kwoty marży (np. nie mniej niż 5–6 zł za jednostkową dostawę), by zapewnić pokrycie kosztów podstawowych operacji hurtowych. •\\tRozważenie związania marży z kosztem logistyki lub poziomem cenowym (np. przedziały marży zależnie od wartości surowca). •\\tWprowadzenie szczegółowej analizy ekonomicznej skutków regulacji przed jej przyjęciem. Podsumowanie Proponowane brzmienie art. 7 ust. 1a ustawy refundacyjnej w zakresie wprowadzenia urzędowej marży hurtowej w wysokości 6% dla surowców farmaceutycznych budzi uzasadnione \\fwątpliwości zarówno z perspektywy pacjentów, jak i stabilności systemu dystrybucji.\\t\\fWprowadzenie marży hurtowej dla leków recepturowych  Uwaga dotyczy zmiany zawartej w art. 1 pkt 4) lit. b) Projektu Ustawy Zmieniającej poprzez dodanie w art. 7 ustępu 1a Ustawy Refundacyjnej o treści: „1a. Ustala się urzędową marżę hurtową w wysokości 6% ceny: 1) surowców farmaceutycznych; 2) utensyliów recepturowych, o których mowa w art. 6 ust. 10 pkt 2; 3) leków gotowych, które mogą być traktowane jako surowce farmaceutyczne podczas sporządzania leku recepturowego.”  \\fZastrzeżenia prawne co do wadliwości tak sformułowanego przepisu   Zaproponowany ustęp 1a.  w art. 7 w przeciwieństwie do  ust 1  tego artykułu został nieprawidłowo sformułowany. Dlaczego?  W  obecnie obowiązującym art. 7 ust 1.  dotyczącym sposób wyliczania marży hurtowej  dla  leków  gotowych, w stosunku do których została wydana decyzja refundacyjna,  wygląda następująco: Wysokość marży hurtowej została określona na poziomie 6% urzędowej ceny zbytu określonej dla danego produktu w decyzji refundacyjnej.  Cena zbytu wynikająca z decyzji jest jawna i wszystkie podmioty hurtowe działające w łańcuchu dostaw znają cenę zbytu. Marża hurtowa  dla leków gotowych ( o której  mowa  w art. 7 ust. 1 obecnej Ustawy Refundacyjnej) ma co do zasady charakter sztywny, nieuzależniony od decyzji biznesowych poszczególnych przedsiębiorców. Ustawodawca regulując kwestie związane z marżą hurtową daje możliwość dzielenia marży pomiędzy poszczególnych przedsiębiorców oraz  ustala maksymalny charakter urzędowej marży hurtowej w przypadku realizacji dostaw produktów objętych refundacją do świadczeniodawców, w celu realizacji świadczeń gwarantowanych. Jeszcze raz podkreślamy, że obecny art. 7 ust 1 ustawy refundacyjnej jest jednoznaczny i prosty do realizowania bo każdy podmiotów hurtowych znajdujących się \\fw łańcuchu dostaw zna urzędowe ceny zbytu i wie  jaką może naliczyć marże mieszcząc się w pułapie 6 %.  W przypadku surowców  farmaceutycznych nie ma urzędowej ceny zbytu określonej dla danego produktu w decyzji refundacyjnej. Jest tylko limit finansowania za jednostkę surowca farmaceutycznego służącego do sporządzenia leku recepturowego. Każdy surowiec może mieć inną cenę po której podmiot odpowiedzialny sprzedaje  dany surowiec. Co więcej, cena surowca może i bardzo często przekracza cenę limitu finasowania.  W związku z tym  pojawiają się następujące wątpliwości, które bez ich usunięcia spowodują, że przepis ten będzie sformułowany wadliwie: 1.\\tNie wiadomo co ustawodawca  rozumie przez pojęcie „ceny”.  W Ustawie  refundacyjnej znajdują się  następujące pojęcia  ceny  i ich definicje:  •\\tcena detaliczna - cena zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego powiększona o urzędową marżę hurtową i urzędową marżę detaliczną oraz należny podatek od towarów i usług; •\\tcena hurtowa - cena zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu \\fmedycznego powiększona o urzędową marżę hurtową; •\\tcena hurtowa brutto - cena hurtowa powiększona o należny podatek od towarów i usług; •\\tcena zbytu netto - cena sprzedaży leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego przez wnioskodawcę podmiotom uprawnionym, nieuwzględniająca należnego podatku od towarów i usług. Żadne z tych pojęć dotyczących „ceny”  nie zostało powołane w dodawanych  ustępie 1a. Podkreślić należy, że  stosowanie jedynie słowa „ceny” bez wskazania o jaką cenę chodzi  doprowadzi do bardzo dużej niejednoznaczności interpretacyjnej.  2.\\t Ustawodawca nie określił, jak ma być w praktyce rozwiązywany problem dzielenia marży.               O ile w przypadku leków gotowych cena  zbytu jest określona w decyzji refundacyjnej i podmioty w łańcuchu dostaw wiedzą, ile mogą naliczyć marży, aby nie przekroczyć pułapu 6 %, to w przypadku surowców farmaceutycznych, nie wiedzą, z uwagi na tajemnicę handlową,  w jakiej  cenie  został zakupiony dany surowiec i ile zostało marży do pułapu 6 %.   3.\\tJak będzie wyglądał sposób rozliczania  marży hurtowej w przypadku, gdy podmiot odpowiedzialny prowadzi \\fjednocześnie hurtownię farmaceutyczną. Dodatkowo zdarzają  się podmioty odpowiedzialne, które  nie są wytwórcami. Wtedy taki podmiot odpowiedzialny nabywa od wytwórcy surowiec farmaceutyczny i sprzedaje dalszym hurtowniom farmaceutyczny, działając jako hurtownia farmaceutyczna. Czy w takim przypadku też obowiązuje marża 6 %? Jeśli tak, to ustawa wprowadza nierówne traktowanie podmiotów odpowiedzialnych, gdyż podmioty, które nie są wytwórcami i będą zmuszone do stosowania 6 % marzy hurtowej, nie będą mogły np. odzyskiwać koszów badań i rejestracji.   B. Negatywne skutki dla pacjentów  1. Potencjalne skutki dla pacjentów: a) Ograniczenie dostępności leków recepturowych Surowce farmaceutyczne stanowią podstawę do wykonywania leków recepturowych, które często są jedyną możliwością leczenia dla pacjentów z chorobami rzadkimi, nietypowymi alergiami, a także niemowląt i dzieci. Sztywna marża 6% w praktyce oznacza, że przy tanich surowcach (np. 20–30 zł) hurtownia uzyska zaledwie 1,20–1,80 zł za ich dystrybucję, co nie pokrywa nawet kosztów logistyki i \\fmoże doprowadzić do ograniczenia dostępności surowców dla pacjentów. b) Pogorszenie dostępu do spersonalizowanego leczenia Wprowadzenie sztywnej marży ograniczy dystrybucję niszowych surowców, co doprowadzi do pogłębienia problemu niedoborów i konieczności stosowania mniej skutecznych terapii substytucyjnych. c) Potencjalny wzrost kosztów dla pacjentów Braki surowców mogą doprowadzić do wzrostu kosztów leczenia, gdyż leki gotowe (alternatywy) są często znacznie droższe od leków wykonywanych w aptekach. C. Negatywny wpływ na rynek farmaceutyczny a) Brak rentowności hurtowej dystrybucji surowców Stała marża 6% nie odzwierciedla realiów ekonomicznych funkcjonowania hurtowni, w szczególności przy dystrybucji towarów wymagających specjalnych warunków przechowywania. Taki poziom rentowności czyni obrót surowcami nieopłacalnym. Należy pamiętać, że wytworzenie leku recepturowego w aptece często wymaga  stosowania wielu \\fsurowców o charakterze  niszowym. To powoduje, że hurtownie, otrzymując marże poniżej kosztów logistycznych, mogą zrezygnować z oferowania takich  surowców niszowych.   b) Ryzyko wycofania się mniejszych hurtowni Małe i średnie hurtownie, które obsługują lokalne apteki i często specjalizują się w dostawach surowców recepturowych, mogą nie być w stanie utrzymać działalności przy tak ograniczonym poziomie marży. To prowadzi do dalszej centralizacji i oligopolizacji rynku. c) Spadek konkurencyjności i innowacyjności Wprowadzenie jednolitej marży hamuje konkurencję pomiędzy podmiotami hurtowymi i zniechęca do inwestycji w rozwój usług, jakości obsługi czy infrastruktury logistycznej. \\t\\fUwaga niezasadna Wprowadzenie urzędowej marży hurtowej stanowi dodatkowy mechanizm zabezpieczający wydatki płatnika publicznego na refundację leków recepturowych.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1. pkt 4 lit. b projektu odnoszący się do art. 7 ust. 1a ustawy o refundacji\\tWnioskujemy o wykreślenie z projektu ustawy dodania do art. 7 ustępu 1a\\tUzasadnienie propozycji wykreślenia zapisu o sztywnej marży hurtowej na surowce farmaceutyczne, utensylia i produkty gotowe stosowane w recepturze  Wprowadzenie sztywnej marży hurtowej na surowce farmaceutyczne, utensylia oraz produkty gotowe wykorzystywane w recepturze nie jest zasadne z kilku \\fpowodów – zarówno merytorycznych, jak i praktycznych. Wystarczające zabezpieczenie celu ustawy.\\nProjekt ustawy już obecnie przewiduje określenie limitów finansowania dla surowców, utensyliów i leków gotowych stosowanych w recepturze. To rozwiązanie skutecznie realizuje główny cel regulacji, jakim jest eliminacja zawyżania cen składników recepturowych w celu uzyskania wyższej refundacji. Apteki, działając w ramach limitów, będą naturalnie dążyć do zakupu najtańszych dostępnych składników, co zapewni racjonalizację kosztów bez potrzeby dodatkowej ingerencji w postaci sztywnej marży hurtowej. Brak regulacji cen zbytu dla surowców farmaceutycznych.\\nW przeciwieństwie do innych produktów refundowanych, ustawa nie przewiduje sztywnych cen zbytu dla surowców farmaceutycznych. Producenci mogą ustalać różne ceny dla różnych hurtowni, co oznacza, że hurtownie nie mają wpływu na końcową cenę produktu oferowanego aptece. Wprowadzenie sztywnej marży w takim otoczeniu prowadzi do zaburzenia mechanizmów rynkowych. \\fOgraniczenie konkurencji i ryzyko eliminacji hurtowni z rynku.\\nSztywna marża uniemożliwia hurtowniom konkurowanie ceną, nawet jeśli uzyskają korzystniejsze warunki zakupu od producenta. W efekcie apteki będą wybierać wyłącznie te hurtownie, które otrzymały najniższą cenę zbytu od producenta, eliminując z rynku pozostałe podmioty. Taki mechanizm jest sprzeczny z zasadami konkurencji i może prowadzić do monopolizacji rynku receptury. Brak możliwości dostosowania marży przez hurtownie do kosztów.\\nStała marża nie uwzględnia zróżnicowanych kosztów logistycznych i operacyjnych ponoszonych przez hurtownie. W praktyce może to oznaczać, że dystrybucja niektórych surowców stanie się nieopłacalna, tym bardziej, że regulacja nie przewiduje hurtowej marży minimalnej jak dla innych produktów refundowanych, co wpłynie negatywnie na ich dostępność w aptekach.\\t\\fUwaga niezasadna Wprowadzenie urzędowej marży hurtowej stanowi dodatkowy mechanizm zabezpieczający wydatki płatnika publicznego na refundację leków recepturowych.\\n\\tOkręgowa Izba Aptekarska w Krakowie\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej \\tWykreślenie proponowanej zmiany z nowelizacji Zachowanie poprzedniego brzmienia:   Art 7 ust 8: Dla leków, o których mowa w art. 6 ust. 5, ustala się marżę detaliczną w wysokości 25 % liczoną od kosztu jego sporządzenia, \\fwynoszącą nie więcej niż koszt wykonania leku recepturowego przygotowywanego w warunkach aseptycznych, określony w przepisach wydanych na podstawie art. 6 ust. 10.  oraz   Wprowadzenie na poziomie ustawy przepisu, zgodnie z którym opłata za sporządzenie leku recepturowego będzie waloryzowana na podstawie stałej proporcji względem minimalnego wynagrodzenia, zgodnie ze stanem na dzień ostatniej aktualizacji wysokości tej opłaty. \\t\\fJuż poprzednia nowelizacja znacząco zmniejszyła rentowność wykonywania leków recepturowych w aptekach. Nie widzimy uzasadnienia kolejnego zmniejszenia jej rentowności. Chyba, że celem ustawodawcy jest zupełna likwidacja receptury aptecznej. Należy \\fjednak mieć na względzie, że jest to działanie na niekorzyść pacjentów.   Rosnące ograniczenia w zakresie receptury aptecznej skutkować będą postępującym zmniejszeniem liczby recept wystawianych na leki recepturowe, które nie będzie wynikać z klinicznej ekspertyzy preskryptorów, ale z trudności formalnych, ograniczeń prawnych oraz obawy o trudności z dostępem do leku recepturowego w aptece oraz przede wszystkim wysokie koszty, jakie ponosić będą pacjenci wykupujący leki recepturowe. Im mniej będzie realizowanych tego typu recept, tym wyższe koszty w przeliczeniu na jeden sporządzony lek ponosić będą apteki. Wynikające m. in. z utrudnionej optymalizacji stanu magazynowego, czy częstszej konieczności utylizacji przeterminowanych surowców recepturowych. Propozycja kolejnej obniżki marży aptecznej za leki recepturowe w warunkach stale rosnących kosztów to sytuacja, w której apteki nie tylko nie otrzymują wsparcia w zapewnieniu lokalnym społecznościom dostępu do produktów leczniczych zgodnie z ich potrzebami, ale musiały by mierzyć się z kolejnym utrudnieniem w tym zakresie.  W tym miejscu warto zauważyć, że chociaż wysokość ryczałtu za lek recepturowy jest na bieżąco waloryzowana, Minister Zdrowia nie przewidział mechanizmu aktualizacji opłaty za sporządzenie leku recepturowego.\\t\\fUwaga zasadna  Proponowana zmiana została usunięta z projektu.  W zakresie proponowanego wprowadzenie przepisu, zgodnie z którym opłata za sporządzenie leku recepturowego będzie waloryzowana na podstawie stałej proporcji względem \\fminimalnego wynagrodzenia, uwaga nie została uwzględniona. W trakcie procedowania rozporządzenie Ministra Zdrowia zmieniającego rozporządzenie w sprawie leków, które mogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych z dnia 14 lutego 2024 r. Minister Zdrowia zaproponował rozwiązanie polegające na uzależnieniu wysokości taksy laborum od wysokości minimalnego wynagrodzenia, jednakże nie zostało ono zaakceptowane przez Ministra Finansów.\\n\\tKonfederacja Lewiatan\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej\\tKonfederacja Lewiatan negatywnie ocenia propozycję ograniczenia maksymalnej wysokości marży detalicznej dla leków recepturowych do poziomu nieprzekraczającego kosztu wykonania leku recepturowego przygotowywanego w warunkach innych niż aseptyczne, określonego zgodnie z art. 6 ust. 10 pkt 1 ustawy refundacyjnej. Takie rozwiązanie w praktyce znacząco ogranicza opłacalność wykonywania leków recepturowych w aptekach ogólnodostępnych, co może skutkować dalszym spadkiem ich dostępności dla pacjentów. W związku z tym proponujemy powrót do limitu marży na poziomie wartości taxa laborum dla leku wykonywanego w warunkach aseptycznych.  Jednocześnie należałoby uzależnić wartość taxa laborum od wysokości minimalnego wynagrodzenia za pracę:  1% minimalnego wynagrodzenia za pracę za wykonanie leku niejałowego,  2% minimalnego wynagrodzenia za pracę za wykonanie leku jałowego.  \\tTakie rozwiązanie pozwoliłoby na zachowanie ekonomicznej równowagi, a jednocześnie wspierałoby rozwój receptury aptecznej jako ważnego elementu spersonalizowanej farmakoterapii\\tUwaga zasadna Proponowana zmiana została usunięta z projektu. \\n\\tBusiness Centre Club/Pracodawcy RP\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej\\tWykreślenie proponowanych zmian i powrót do limitu marży na poziomie wartości taxa laborum dla leku wykonywanego w warunkach aseptycznych.  \\fEwentualnie wysoce uzasadnionym wydaje się rezygnacja z określenia marży na leki refundowane i pozostawienie tylko warunku, który określa wysokość marży na poziomie 25%.\\t\\fRosnące dynamicznie koszty pracy, ale i ogólne koszty prowadzenia działalności aptecznej prowadzą do znaczącego, ciągłego pogorszenia opłacalności wykonywania receptury. Jednocześnie przystosowanie lokalu apteki do \\fprowadzenia izby recepturowej jest wysoce kosztochłonne, dodatkowo by wykonywać leki robione należy zapewnić odpowiednią ilość wysoko wykwalifikowanego personelu oraz zapewnić odpowiednie szkolenia.  Jednocześnie należy zwrócić uwagę, że obszar receptury jest obecnie wysoce przeregulowany z licznymi „bezpiecznikami”, które zapewniają, że wydatki NFZ na leki robione, powinny utrzymywać się na niskim poziomie. Mamy: - wyznaczone limity surowców recepturowych, które ograniczają możliwości fiannsowania ze strony NFZ - mechanizm (obecnie) wyznaczania nowych limitów oparty na 15 percentylu co spowodowało w ostatnim czasie znaczne spadki wartości limitów – nawet brak tego mechanizmu i pozostawienie limitów na jednorazowo wyznaczonym poziomie dalej mocno zabezpiecza wysokość wydatków NFZ - mechanizm zabezpieczający przed wzrostem wartości limitów oparty na 30 percentylu - zaproponowane w projekcie wyznaczenie limitów także dla utensyliów - zaproponowany w projekcie receptariusz, który ograniczy ilość i \\frodzaj wykonywanych leków recepturowych - obecnie obowiązuje nieuzasadniony (przy ustanowionych obecnie powyższych ograniczeniach) limit marży na poziomie wartości taxa laborum dla leku wykonywanego w warunkach aseptycznych, który już dzisiaj ogranicza opłacalność wykonywania receptutry - dwukrotne zmniejszenie tego limitu pogorszy dostęp do leków robionych\\t\\fUwaga zasadna Proponowana zmiana została usunięta z projektu.\\n\\tZwiązek Aptek Franczyzowych\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej\\tCałkowita rezygnacja z określenia limitu marży jako nadmiarowego obciążenia, które negatywnie przekłada się na dostępność do leków robionych.\\tObszar finansowania receptury jest już nadmiernie regulowany. Jest kilka czynników, które zabezpieczają płatnika publicznego przed nadmiernymi wydatkami. A należą do nich: limity finansowania na substancje recepturowe oraz (w przyszłości) na utensylia, mechanizm promujący spadek tych limitów (niezależnie czy oparty na 25 czy 15 percentylu) oraz mechanizm zabezpieczający przed ewentualnym wzrostem wartości limitów finansowania. Jednocześnie należy zauważyć, że koszty pracy w aptekach rosną, a prowadzenie receptury jest bardzo kosztochłonne, dlatego uzasadnionym wydaje się, by limit marży nie obowiązywał – co przełoży się na większą dostępność do leków robionych.\\tUwaga niezasadna Wprowadzenie urzędowej marży hurtowej stanowi dodatkowy mechanizm zabezpieczający wydatki płatnika publicznego na refundację leków recepturowych\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 \\fust. 8 ustawy refundacyjnej\\t\\fPowiązanie taxa laborum z płacą minimalną\\tNa koszty wykonania leku recepturowego składa się wiele elementów, które należy uwzględnić by \\fuzyskać adekwatną stawkę taxa laborum, tj. czas niezbędny do sporządzenia leku, koszt zużytych materiałów, koszty eksploatacyjne, a także samej pracy związanej z jego wykonaniem, dlatego proponujemy powiązanie taxa laborum z płacą minimalną. Dla faktycznego pokrycia kosztów wykonania leku recepturowego konieczne jest przyjęcie następujących wartości procentowych: 1,8% od stawki minimalnego wynagrodzenia za pracę – za wykonanie leku niejałowego; 3,6% – za wykonanie leku jałowego\\t\\fUwaga niezasadna W trakcie procedowania rozporządzenie Ministra Zdrowia zmieniającego rozporządzenie w sprawie leków, które \\fmogą być traktowane jako surowce farmaceutyczne przy sporządzaniu leków recepturowych z dnia 14 lutego 2024 r. Minister Zdrowia zaproponował rozwiązanie polegające na uzależnieniu wysokości taksy laborum od wysokości minimalnego wynagrodzenia, jednakże nie zostało ono zaakceptowane przez Ministra Finansów.\\n\\tZwiązek Pracodawców Aptecznych PharmaNET\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej\\tZwiązek negatywnie ocenia proponowaną zmianę w zakresie maksymalnej wysokości marży detalicznej dla leków recepturowych. Koszty prowadzenia i utrzymania receptury pozostają wysokie, co może prowadzić do sytuacji, w której wykonywanie niektórych leków recepturowych może stać się po prostu nieopłacalne. Mając zatem na uwadze potrzeby pacjentów należy w tym zakresie utrzymać dotychczasowe rozwiązanie.\\tJednocześnie, mając na uwadze, że na koszty wykonania leku recepturowego składa się wiele elementów, które należy uwzględnić by uzyskać adekwatną stawkę taxa laborum, tj. czas niezbędny do sporządzenia leku, koszt zużytych materiałów, koszty eksploatacyjne, a także samej pracy związanej z jego wykonaniem, proponujemy powiązanie taxa laborum z płacą minimalną. Niezależnie od powyższego postulujemy również umożliwienie prowadzenia receptury wybranym aptekom, na zlecenie tych placówek, które nie mogą sporządzić leków samodzielnie. Apteki zlecające, które nie brały czynnego udziału w przygotowywaniu leku, jedynie pośredniczyłyby w przekazaniu recepty (na podstawie umów obowiązkowo \\fzawieranych z inną apteką, która takie leki sporządza), a następnie wydawałyby go pacjentowi. W ten sposób sprzedaż leków odbywałaby się przez aptekę sporządzającą lek na rzecz indywidualnego pacjenta wskazanego na recepcie, a rozliczenia między aptekami podlegały ogólnym regulacjom dotyczącym obrotu gospodarczego między przedsiębiorcami. W praktyce wyglądałoby to następująco: 1) pacjent zgłasza się do wybranej przez siebie apteki z receptą na lek recepturowy; 2) apteka ta przekazuje receptę wraz ze zleceniem sporządzenia leku recepturowego do apteki specjalizującej się w sporządzaniu leków recepturowych; 3) wyspecjalizowana apteka, na podstawie otrzymanego zlecenia oraz przekazanej recepty, sporządza lek recepturowy oraz dokonuje otaksowania recepty; 4) sporządzony lek zostaje przekazany do apteki zlecającej wraz z dokumentem sprzedaży dla pacjenta; 5) apteka zlecająca wydaje pacjentowi lek oraz dokument sprzedaży. Współpraca między takimi placówkami aptecznymi nie narusza obecnie obowiązującej treści przepisów art. 86a \\fustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne („PF”), czy § 6 ust. 4 pkt 1 rozporządzenia Ministra Zdrowia z dnia 27 października 2022 r. w sprawie podstawowych warunków prowadzenia apteki. Także dane pacjenta i świadczeniodawcy nie są przekazywane do podmiotu trzeciego, a wykorzystywane wyłącznie na potrzeby świadczenie usługi farmaceutycznej i rozliczenia z NFZ (art. 103 ust. 2 pkt 4a PF). Usługowe sporządzenie leków recepturowych przez wyspecjalizowane w tym zakresie apteki ogólnodostępne jest rozwiązaniem często spotykanym w Europie i nie stoi w żaden sposób w sprzeczności z interesem pacjenta, czy też nie wpływa ujemnie na realizację podstawowych obowiązków apteki. Wręcz przeciwnie, sporządzenie leków recepturowych przez wyspecjalizowaną aptekę, która posiada na stanie szeroki asortyment surowców farmaceutycznych, przyspieszy zaopatrzenie pacjenta w lek oraz zagwarantuje jego najwyższą jakość. Mając na uwadze powyższe, w ocenie Związku, zawieranie pomiędzy aptekami ogólnodostępnymi umów o sporządzanie leków recepturowych na podstawie dostarczanych przez pacjentów recept jest możliwe już w obowiązującym stanie prawnym, jednak należy rozważyć \\fwprowadzenie stosownych zmian legislacyjnych dostosowujących obecne ramy prawne do realiów panujących na rynku aptecznym (Załącznik nr 1). Umożliwi to zwolnienie tych aptek, które jedynie pośredniczyłyby w przekazaniu recepty do odpowiedniej placówki, z części wymogów lokalowych ściśle związanych ze sporządzaniem leków recepturowych, tj. obowiązku posiadania izby recepturowej i zmywalni. Ponadto, w celu zagwarantowania, że każda apteka niesporządzająca leków recepturowych zawrze stosowne umowy z wyspecjalizowanymi aptekami, można rozważyć wprowadzenie odpowiednich sankcji administracyjnych.\\t\\fUwaga zasadna  Proponowana zmiana została usunięta z projektu.\\n\\tNaczelna Izba Aptekarska\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej\\t\\tW art. 1 pkt 4 lit. d projektu, dotyczącym art. 7 ust. 8 ustawy proponuje się nadać brzmienie: \\t„d) ust. 8 otrzymuje brzmienie: \\t„8. Dla leków, o których mowa w art. 6 ust. 5, ustala się marżę detaliczną w wysokości 25% liczoną od kosztu jego sporządzenia, wynoszącą nie więcej niż koszt wykonania leku recepturowego przygotowywanego w warunkach aseptycznych, określonego na podstawie art. 6 ust. 10 pkt 1.”;\\tPropozycja zmiany art. 7 ust. 8 ustawy refundacyjnej polega na pozostawieniu dotychczasowego brzmienia przepisu, w którym maksymalna wysokość marży detalicznej dla leków recepturowych odnosi się do kosztu wykonania leku przygotowywanego w warunkach aseptycznych. W ocenie NIA proponowana przez Ministra Zdrowia zmiana, polegająca na odniesieniu limitu marży do niższej kwoty, odpowiadającej kosztowi wykonania leku w warunkach innych niż aseptyczne, może mieć negatywne skutki dla dostępności leków recepturowych oraz stabilności ekonomicznej aptek wykonujących tego rodzaju leki. \\fW szczególności należy zwrócić uwagę, że wartość tzw. taxa laborum, czyli urzędowo określonego kosztu wykonania leku recepturowego, ma charakter ryczałtowy i nie podlega corocznej waloryzacji. Tymczasem koszty funkcjonowania aptek, w tym pracy farmaceutów, zakupu energii, surowców i odczynników, rosną w tempie przewyższającym tempo aktualizacji stawek urzędowych. Dla przykładu, obowiązująca obecnie stawka taxa laborum dla leków wykonywanych w warunkach nieaseptycznych wynosi 31,81 zł, czyli kwotę bardzo zbliżoną do aktualnej minimalnej stawki godzinowej za pracę, co oznacza, że marża apteczna z tytułu wykonania leku recepturowego w wielu przypadkach nie pokrywa nawet kosztów wynagrodzenia za pracę farmaceuty, nie wspominając o kosztach materiałowych czy organizacyjnych. Dodatkowo, należy zauważyć, że leki recepturowe, o których mowa w art. 6 ust. 5 ustawy refundacyjnej, niejednokrotnie wymagają znacznego nakładu pracy, szczególnej ostrożności oraz kwalifikacji, nawet jeśli formalnie sporządzane są w warunkach nieaseptycznych. Obniżenie pułapu marży do poziomu odpowiadającego taksie za warunki nieaseptyczne może więc prowadzić do sytuacji, w której sporządzanie tych leków stanie się dla aptek ekonomicznie nieopłacalne. W \\fkonsekwencji istnieje realne ryzyko, że część aptek zaprzestanie świadczenia tej formy usług. Wpłynie to bezpośrednio na pogorszenie dostępności terapii indywidualnie dostosowanych do pacjentów, zwłaszcza dzieci, osób starszych czy pacjentów wymagających leczenia skojarzonego. Z punktu widzenia funkcjonowania systemu ochrony zdrowia, utrzymanie marży odniesionej do wyższej wartości kosztu wykonania leku w warunkach aseptycznych gwarantuje nie tylko pokrycie rzeczywistych kosztów apteki, ale także zapewnia stabilność i przewidywalność warunków świadczenia usług przez apteki wykonujące leki recepturowe. Apteki te stanowią istotny element systemu opieki farmaceutycznej, a ich działalność nie powinna być uzależniona od ryzykownych i nieadekwatnych ograniczeń finansowych. Z tych względów postuluje się, aby art. 7 ust. 8 zachował dotychczasowe brzmienie, a więc aby marża detaliczna w wysokości 25% liczona od kosztu sporządzenia leku była ograniczona do poziomu kosztu wykonania leku recepturowego przygotowywanego w warunkach aseptycznych, określonego na podstawie art. 6 ust. 10 pkt 1 ustawy. Rozwiązanie to jest racjonalne, zgodne z zasadą proporcjonalności, zabezpiecza interes pacjentów i wspiera stabilność \\fekonomiczną aptek realizujących zadania publiczne w zakresie przygotowywania leków na indywidualne potrzeby chorych.\\t\\fUwaga zasadna Proponowana zmiana została usunięta z projektu.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 4 lit. d projektu odnoszący się do art. 7 ust. 8 ustawy refundacyjnej\\tWykreślenie proponowanych zmian i powrót do limitu marży na poziomie wartości taxa laborum dla leku wykonywanego w warunkach aseptycznych.  \\tEwentualnie wysoce uzasadnionym wydaje się rezygnacja z określenia marży na leki refundowane i pozostawienie tylko warunku, który określa wysokość marży na poziomie 25%.\\tRosnące dynamicznie koszty pracy, ale i ogólne koszty prowadzenia działalności aptecznej prowadzą do znaczącego, ciągłego pogorszenia opłacalności wykonywania receptury. Jednocześnie przystosowanie lokalu apteki do prowadzenia izby recepturowej jest wysoce kosztochłonne, dodatkowo by wykonywać leki robione należy zapewnić odpowiednią ilość wysoko wykwalifikowanego personelu oraz zapewnić odpowiednie szkolenia.  Jednocześnie należy zwrócić uwagę, że obszar receptury jest obecnie wysoce przeregulowany z licznymi „bezpiecznikami”, które zapewniają, że wydatki NFZ na leki robione, powinny utrzymywać się na niskim poziomie. Mamy: - wyznaczone limity surowców recepturowych, które ograniczają możliwości finansowania ze strony NFZ - mechanizm (obecnie) wyznaczania nowych limitów oparty na 15 percentylu, co spowodowało w ostatnim czasie znaczne spadki wartości limitów – nawet brak tego mechanizmu i pozostawienie limitów na jednorazowo wyznaczonym \\fpoziomie dalej mocno zabezpiecza wysokość wydatków NFZ - mechanizm zabezpieczający przed wzrostem wartości limitów oparty na 30 percentylu - zaproponowane w projekcie wyznaczenie limitów także dla utensyliów - zaproponowany w projekcie receptariusz, który ograniczy ilość i rodzaj wykonywanych leków recepturowych - obecnie obowiązuje nieuzasadniony (przy ustanowionych obecnie powyższych ograniczeniach) limit marży na poziomie wartości taxa laborum dla leku wykonywanego w warunkach aseptycznych, który już dzisiaj ogranicza opłacalność wykonywania receptutry - dwukrotne zmniejszenie tego limitu pogorszy dostęp do leków robionych\\t\\fUwaga zasadna  Proponowana zmiana została usunięta z projektu.  \\n\\tOrganizacja Pracodawców Przemysłu Medycznego TECHNOMED\\tArt. 1 pkt 5 projektu odnoszący się do art. 9 ustawy refundacyjnej\\tWnioskujemy o rozszerzenie zapisów art. 9 o inne podmioty prowadzące sprzedaż hurtową do świadczeniodawców jako uprawnionych do korzystania z marży hurtowej w przypadku wyrobów medycznych.\\tW przypadku wyrobów medycznych sprzedaż do świadczeniodawców może być prowadzona zarówno przez producenta, dystrybutora oraz hurtownię nie mającą statusu hurtowni farmaceutycznej. Nie ma obowiązku sprzedaży hurtowej przez kanał farmaceutyczny, który często nie zajmuje się wyrobami medycznymi ze względu na ich odmienną specyfikę i często również \\fgabarty. Brak obowiązku prowadzenia takiej sprzedaży przez hurt farmaceutyczny został również potwierdzony wyrokiem Wojewódzkiego Sądu Administracyjnego w Warszawie z dnia 27 listopada 2020 r.VI SA/Wa 1729/20. Dlatego też proponujemy następujący zapis art. 9: „ Świadczeniodawca w celu realizacji świadczeń gwarantowanych jest obowiązany nabywać leki, środki spożywcze specjalnego przeznaczenia żywieniowego, wyroby medyczne po cenie nie wyższej niż cena zbytu netto powiększona o marżę nie wyższą niż urzędowa marża hurtowa i należny podatek od towarów i usług, a w przypadku nabywania leków i środków specjalnego przeznaczenia żywieniowego od podmiotu innego niż przedsiębiorca prowadzący obrót hurtowy w rozumieniu ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne – po cenieW przypadku wyrobów medycznych sprzedaż do świadczeniodawców może być prowadzona zarówno  przez producenta, dystrybutora oraz hurtownię nie mającą statusu hurtowni farmaceutycznej. Nie ma obowiązku sprzedaży hurtowej przez kanał farmaceutyczny, który często nie zajmuje się wyrobami medycznymi ze względu na ich odmienną specyfikę i często również gabarty. Brak obowiązku prowadzenia takiej sprzedaży przez hurt \\ffarmaceutyczny został również potwierdzony wyrokiem Wojewódzkiego Sądu Administracyjnego w Warszawie z dnia 27 listopada 2020 r.VI SA/Wa 1729/20. Dlatego też proponujemy następujący zapis art. 9 : „ Świadczeniodawca w celu realizacji świadczeń gwarantowanych jest obowiązany nabywać leki, środki spożywcze specjalnego przeznaczenia żywieniowego, wyroby medyczne po cenie nie wyższej niż cena zbytu netto powiększona o marżę nie wyższą niż urzędowa marża hurtowa i należny podatek od towarów i usług, a w przypadku nabywania leków i środków specjalnego przeznaczenia żywieniowego od podmiotu innego niż przedsiębiorca prowadzący obrót hurtowy w rozumieniu ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne – po cenie nie wyższej niż urzędowa cena zbytu.”\\t\\fUwaga niezasadna  Zarówno apteki szpitalne, jak i działy farmacji szpitalnej zaopatrują szczególną grupę pacjentów tj. pacjentów hospitalizowanych. Pacjenci ci powinni być objęci szczególna opieką mieć zagwarantowane, że produkty, w tym wyroby medyczne, które otrzymują w ramach refundacji spełniają najwyższe standardy. Zakup wyrobów medycznych od hurtowni farmaceutycznych daje gwarancję, że obrót wyrobami medycznymi, podobnie jak produktami \\fleczniczymi, na każdym etapie odbywa się z zachowaniem zasad Dobrej Praktyki Dystrybucyjnej, a także jest w pełni monitorowany. Z praktycznego punktu widzenia jakości i bezpieczeństwa kluczowe jest egzekwowanie, aby dostawca wyrobów medycznych przestrzegał regulacji MDR w zakresie realizacji dostaw z zachowaniem zasad DPD i zgodnie z warunkami określonymi przez producenta, tj. na przykład zapewniał odpowiednie warunki sanitarne i temperaturowe w przestrzeni ładunkowej pojazdu, którym wykonywane są dostawy. Warunki takie gwarantuje dostawa poprzez hurtownię farmaceutyczną.\\n\\tAmerykańska Izba Handlowa w Polsce/ Pracodawcy RP\\tArt. 11 ust. 2 pkt 8\\tW art. 11ust. 2 pkt 8 proponujemy nadać brzmienie: \\\"8) określenie grupy limitowej;\\\"\\tZmiana powiązana ze zmianami zaproponowanymi przez KF AmCham w zakresie przepisów art. 15 ust. 2-3b. Szczegółowe uzasadnienie w tym zakresie zostało przedstawione w wierszach 10 i 11 poniżej. Uzasadnienie Pracodawcy RP Zmiana powiązana ze zmianami zaproponowanymi w zakresie przepisów art. 15 ust. 2-3b. Szczegółowe \\fuzasadnienie w tym zakresie zostało przedstawione poniżej.\\t\\fUwaga niezasadna W opinii resortu nie ma potrzeby doprecyzowania zapisu.  Zgodnie z projektem zmiany ustawy o refundacji Minister Zdrowia ustala grupy leków, w ramach których wyznacza się podstawę limitu. Skutek prawny zmian w grupach limitowych publikowany jest w obwieszczeniu Ministra Zdrowia w sprawie wykazu refundowanych leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz \\fwyrobów medycznych, opublikowanym po dacie wydania decyzji. Propozycja spowoduje ponowną konieczność przeprowadzania postępowań administracyjnych w zakresie zmiany grupy limitowej w przypadku, gdy w opinii Ministra Zdrowia lub wniosku Strony taka będzie zasadna. Na powrót wydłużałoby to postępowania refundacyjne.\\n\\tPOLSKA FEDERACJA PRODUCENTÓW ŻYWNOŚCI ZWIĄZEK PRACODAWCÓW\\tArt. 1 pkt 6 litera b odnoszący się do art. 10 ust 3 pkt 5\\tProjektowany przepis proponuje wprost wykluczenie możliwości objęcia refundacją produktów leczniczych o kategorii dostępności OTC. Do tej pory, produkty lecznicze tej kategorii nie były wprost wyłączone spod możliwości obejmowania ich refundacją, choć w praktyce rzeczywiście nie były refundowane. Aktualnie obowiązujący stan prawny umożliwia objęcie refundacją produktów o kategorii OTC, co wydaje się być podejściem bardziej elastycznym. To Minister Zdrowia mógł ostatecznie zdecydować, czy objęcie refundacją takiego produktu było zasadne, czy nie. W przypadku jednoznacznego wyłączeni możliwości refundowania leków OTC, na skutej dodania omawianej regulacji, Minister Zdrowia nie będzie już miał takiej możliwości. PFPŻ ZP jest zdania, że biorąc pod uwagę nieprzewidywalność potrzeb pacjentów i sytuacji zdrowotnej, rozsądniejszym jest utrzymanie aktualnie obowiązującego stanu prawnego. \\fW związku z tym PFPŻ ZP postuluje wykreślenie projektowanej zmiany.\\t\\tUwaga niezasadna W opinii Ministra Zdrowia niezasadne jest obejmowanie refundacją leków OTC. Jednym z powodów negatywnej opinii jest brak kontroli lekarskiej nad zasadnością stosowania, leki te dostępne są bez diagnozy, samodzielnie stosowane przez pacjenta, używane objawowo. Refundacja leków OTC oznaczałaby finansowanie tych leków bez weryfikacji medycznej zasadności. Leki te służą leczeniu drobnych i przemijających dolegliwości, które nie ratują życia ani nie dotyczą ciężkich schorzeń przewlekłych. System refundacyjny ma przede wszystkim zapewniać dostęp do terapii kosztowych, chronić przed barierą finansową w ciężkich, przewlekłych chorobach. Refundacja leków OTC stanowi również ryzyko nadmiernej ich konsumpcji. \\n\\tWiseMed – agencja marketingu medycznego\\tArt. 1 pkt 6 litera b oraz art. 1 pkt 34 projektu odnoszące się do art. 10 ust 3 pkt 4 i 5 oraz art. 33 ustawy refundacyjnej .\\tProponujemy rezygnację z wprowadzenia zmian projektowanych w art. 1 pkt 6 lit. b oraz art.1 pkt 34\\tWprowadzenie przedmiotowych zmian wiązałoby się z ryzykiem ograniczenia prawa pacjentów do dostępu do refundowanych terapii lekowych wynikającego wyłącznie z kategorii dostępności leku. Przypisanie leku do kategorii OTC nie jest zależne od jego skuteczności ani efektywności kosztowej, dlatego zaliczenie leku do kategorii OTC nie powinno wyłączać możliwości jego refundacji. Fakt, że do tej pory nie korzystano z możliwości refundacji leków bez recepty nie stanowi powodu, aby zakładać, że taka decyzja nie będzie uzasadniona w przyszłości.. Zawarta w uzasadnieniu opinia Projektodawcy, według którego cena leków OTC powinna być co do zasady niższa niż cena leków Rp, jest raczej argumentem przemawiającym na korzyść refundacji leków OTC. Gdyż niższy koszt terapii oznacza niższe koszty refundacji. Ponadto opinia ta wydaje się kontrowersyjna, ponieważ istnieje szereg mechanizmów ograniczających ceny refundowanych leków na receptę. Przeciętna cena w grupie leków na receptę jest oczywiście wyższa niż przeciętna cena w kategorii OTC. Nie wynika to jednak z faktu, że przyznanie kategorii OTC skutkuje obniżeniem ceny (taki mechanizm nie występuje), ale z \\ftego, że najdroższe i najbardziej innowacyjne terapie dotychczas kwalifikowane były do innych kategorii dostępności ze względu na ich profil bezpieczeństwa. Zgodnie z art. 23 ust. 3 ustawy z dnia 6 września 2001 r. Prawo farmaceutyczne (Dz. U. 2025 poz. 750; dalej: ustawy prawo farmaceutyczne), kryteria zaliczenia produktu leczniczego do poszczególnych kategorii dostępności określa w drodze rozporządzenia Minister Zdrowia, uwzględniając w szczególności charakter poszczególnych kategorii dostępności oraz bezpieczeństwo stosowania produktu leczniczego. Zgodnie z § 5. tego rozporządzenia, do kategorii dostępności „produkty lecznicze wydawane bez przepisu lekarza – OTC” zalicza się produkty lecznicze niespełniające warunków kwalifikacji do pozostałych kategorii. Oznacza to, że decyzja o kategorii dostępności nie zależy wyłącznie od biznesowych decyzji podmiotu odpowiedzialnego, ale jest podyktowana aspektem klinicznym ze szczególnym uwzględnieniem bezpieczeństwa stosowania leku. Z kolei decyzję o refundacji Minister właściwy do spraw zdrowia, podejmuje zgodnie z treścią art. 12 ustawy refundacyjnej, mając na uwadze uzyskanie jak największych efektów zdrowotnych w ramach dostępnych środków publicznych. Cały system refundacji \\fproduktów leczniczych ma na celu realizację zadań władzy publicznej, które określone zostały w art. 38 i art. 68 Konstytucji. Umożliwienie Ministrowi Zdrowia cofnięcia decyzji refundacyjnej w przypadku leku, który uzyskał kategorię dostępności OTC bądź dla którego pojawił się dostępny bez recepty odpowiednik (zgodnie z art. 1 pkt 34 projektu), de facto oznacza możliwość wycofania z refundacji produktu leczniczego z uwagi na fakt, iż potwierdzono dla niego bardzo wysoki poziom bezpieczeństwa stosowania. Mając na uwadze powyższe wydaje się, że wykluczenie z refundacji produktów leczniczych z kategorii dostępności OTC oraz tych, które posiadają wydawany bez recepty odpowiednik nie jest uzasadnione interesem publicznym.\\t\\fUwaga niezasadna. Organ nie widzi możliwości przywrócenia refundacji leków OTC. Należy wskazać, iż leki wydawane bez recepty powinny być tańsze, a przez to o wiele łatwiejsze do nabycia niż leki na receptę, więc ich refundacja nie przyniosłaby dużej ulgi pacjentom, a jednocześnie mogłaby mieć znaczny wpływ finansowy na budżet płatnika publicznego. Środki publiczne na refundację leków są ograniczone. Wobec powyższego płatnik koncentruje refundację na lekach droższych, stosowanych w chorobach przewlekłych i ciężkich np. w cukrzycy, chorobach sercowo - naczyniowych czy nowotworach, gdzie wydatek na poszczególny lek jest znaczący, a pacjent bez refundacji mógłby nie być w stanie się leczyć. W dużej mierze leki OTC dotyczą samoleczenia i profilaktyki, można stosować jeprzy dolegliwościach lekkich i przejściowych. Gdyby leki OTC były refundowane, mogłoby to prowadzić do większego ich zużycia, poprzez zakupy na zapas. Biorąc pod uwagę, że budżet na refundację leków jest ograniczony, w przypadku dużego nakładu finansowego na refundację leków OTC,  zagrożony może być dostęp do leków refundowanych na receptę, a jednocześnie ograniczona może zostać refundacja nowych innowacyjnych leków dla pacjentów.   Pomimo powyższej argumentacji umożliwiono refundację leków w kategorii OTC od 1.11.2023 r. jednak z uwagi, że od prawie dwóch lat żaden \\fpodmiot odpowiedzialny nie skorzystał z tego prawa, a tym samym nie złożył wniosku o objęcie refundacją i ustalenie ceny zbytu netto, z powodu braku zainteresowania i istnienia przepisu tylko w teorii, uznano, iż jednak leki OTC nie powinny być refundowane. Treścią konstytucyjnego prawa do ochrony życia i ochrony zdrowia Konstytucji jest - z jednej strony - przyznana każdemu możliwość korzystania z systemu ochrony zdrowia, funkcjonalnie ukierunkowanego na zwalczanie i zapobieganie chorobom, urazom i niepełnosprawności, a więc prawo do uzyskania pewnych, choć nieokreślonych konkretnie na poziomie konstytucyjnym, świadczeń ze strony państwa oraz - z drugiej strony - skierowany do państwa (władz publicznych) nakaz podejmowania działań, które są konieczne dla należytej ochrony i realizacji tego prawa. Powyższe należy rozumieć jako konieczność zabezpieczenia w budżecie państwa odpowiednich środków finansowych, umożliwiających funkcjonowanie publicznego systemu opieki zdrowotnej, a także stworzenia gwarancji prawnych - w tym instytucjonalnych i proceduralnych – właściwego wykorzystywania tych środków. Na ministrze właściwym do spraw zdrowia ciąży przede wszystkim obowiązek stworzenia ram prawnych i instytucjonalnych oraz procedur, które będą w sposób efektywny służyć wszystkim obywatelom, znajdującym się w sytuacji wymagającej skorzystania z opieki zdrowotnej. Gwarancją równości \\fw dostępie do świadczeń są w szczególności właśnie procedury, uregulowane przepisami prawa – w tym ustawą o refundacji, ustanawiające jednakowe dla wszystkich - i niezależne od sytuacji materialnej danej osoby - zasady ubiegania się o udzielenie świadczenia danego rodzaju. Z uwagi na ograniczone możliwości finansowe płatnika publicznego nie jest możliwym, aby wszystkie świadczenia, były refundowane lub nieodpłatne.\\n\\tIzba Gospodarcza „FARMACJA POLSKA” \\tArt. 1 pkt 7 lit. b dotyczący art. 11 ust. 3a ustawy refundacyjnej\\tChcielibyśmy jednak zaproponować Państwu przeniesienie momentu, w którym powinna się zrealizować obniżka ceny, z wygaśnięcia wyłączności rynkowej na moment objęcia refundacją pierwszego odpowiednika (leku biopodobnego) danego leku referencyjnego. Niezależnie od powyższego, wskazujemy na potrzebę zaadresowania w projekcie nowelizacji sytuacji leków, dla których po wejściu DNUR w życie wydano decyzje skrócone do momentu upływu okresu ochrony patentowej\\tJako Izba Gospodarcza „FARMACJA POLSKA” w pełni popieramy postulat odejścia od pomysłu obniżania ceny leku przy wygaśnięciu wyłączności rynkowej lub ochrony patentowej, zależnie od tego, co nastąpi jako pierwsze i przyjęcia jednego, pewnego terminu, w którym obniżka powinna być zrealizowana.  Faktycznie uwzględnienie momentu wygaśnięcia ochrony patentowej w mechanizmie obowiązkowej obniżki spowodowało niepotrzebny chaos, wynikający z faktu, że wiele produktów jest chronionych przez szereg patentów i \\fSPC (dodatkowych praw ochronnych), w związku z czym ustalenie jednego, precyzyjnego momentu wygaśnięcia ochrony patentowej może być trudne.  Chcielibyśmy jednak zaproponować Państwu przeniesienie momentu, w którym powinna się zrealizować obniżka ceny, z wygaśnięcia wyłączności rynkowej na moment objęcia refundacją pierwszego odpowiednika (leku biopodobnego) danego leku referencyjnego.  Rozwiązanie to spełniałoby bowiem funkcję zabezpieczenia pacjentów przed wysokimi dopłatami do cen leków (w refundacji aptecznej), a jednocześnie zmuszało wnioskodawców dla leków referencyjnych do zrewidowania swoich cen w sytuacji, w której na rynek wchodzi konkurencja; a jednocześnie chroniłoby pacjentów przed utratą (na skutek niemożności obniżenia ceny) jedynego refundowanego produktu o danym składzie i wskazaniu w sytuacji, w której pomimo wygaśnięcia wyłączności rynkowej nie są wprowadzane do obrotu odpowiedniki.  Ryzyko, że do takiej sytuacji dojdzie, jest wysokie, zwłaszcza, że w świetle zaproponowanego w projekcie nowelizacji art. 11 ust. 3a ustawy obniżka miałaby być zrealizowana po upływie najwcześniejszego okresu wyłączności rynkowej, a więc na przykład przed \\fupływem dodatkowego, rocznego okresu wyłączności rynkowej, udzielonego dla produktu na skutek zarejestrowania w okresie wyłączności danych nowego wskazania. Jako, że wiele produktów referencyjnych ma ten dodatkowy, roczny okres wyłączności rynkowej, wiele z nich będzie podlegać obowiązkowi obniżki ceny na rok przed wejściem do refundacji pierwszych odpowiedników. W takiej sytuacji brak zgody wnioskodawcy na obniżenie ceny będzie skutkował utratą leczenia przez pacjentów na rok.  Niezależnie od powyższego, wskazujemy na potrzebę zaadresowania w projekcie nowelizacji sytuacji leków, dla których po wejściu DNUR w życie wydano decyzje skrócone do momentu upływu okresu ochrony patentowej (lub takie decyzje będą wydane do dnia wejścia w życie kolejnej nowelizacji). Od chwili, gdy zacznie obowiązywać zmieniona treść art. 11 ust. 3a ustawy, upływ ochrony patentowej przestanie być przesłanką warunkującą obowiązkowe obniżenie ceny refundowanego produktu, w związku z czym skrócenie tych decyzji przestanie być zasadne. Naszym zdaniem należałoby wydłużyć okres ich obowiązywania do okresu, na jaki powinny być wydane w nowym stanie prawnym (bez ich skracania do końca okresu ochrony patentowej), dlatego \\fpostulujemy wprowadzenie do ustawy odpowiedniego przepisu przejściowego. \\t\\fUwaga niezasadna. Decyzje wydawane są w na podstawie obowiązujących na dzień ich wydania przepisów i są wiążące i ostateczne.  Zauważalny jest również problem skoordynowania w jednym czasie dwóch postępowań (obniżenia ceny dla leku referencyjnego) i procedowania jednocześnie wniosku o objęcie leku generycznego. Problem istniałby również po stronie proceduralnej, tj. w jaki sposób i czy podmiot mający wydaną i obowiązującą w danym czasie decyzję złoży wniosek w momencie powzięcia informacji o pojawieniu się wniosku dla leku generycznego, czy uda się oba procesy skoordynować oraz sytuacja \\fwymuszałaby skrócenie obowiązującej decyzji dla leku oryginalnego.    Zapis zaproponowany przez Ministra Zdrowia ma na celu właśnie redukcję ceny leku jeszcze w momencie przed wejściem do refundacji leku generycznego, co wtórnie skutkuje niższą ceną generyku (zmienia się referencja w cenie progowej). Proponowana zmiana powodowałby, że pierwsze odpowiedniki wchodziłyby do systemu z wyższymi cenami. Co więcej, niejednokrotnie w momencie generyzacji produkt referencyjny i tak wycofuje decyzje albo pozostaje bierny w postępowaniach przetargowych. Tak więc obniżka już po generyzacji nie przynosi żadnych oszczędności dla płatnika, a wręcz przeciwnie. Ponadto intencją Organu dla przedmiotowego przepisu jest obniżenie ceny leku wyłącznie po wygaśnięciu wyłączności rynkowej, która upływa jako pierwsza w danym wskazaniu. Zdarza się tak, że dany lek ma różne okresy wyłączności rynkowej na dwa różne wskazania. Stąd w tym przypadku wymóg obniżenia ceny o 25 pkt % dotyczy okresu wyłączności rynkowej, który upłynie jako pierwszy dla danego leku.  Od lat obowiązuje taka kolejność ustawowych obniżek i każdy profesjonalny podmiot odpowiedzialny kształtuje swoją długofalową politykę i strategie cenową z uwzględnieniem właśnie tych ustawowych zapisów.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 7 lit. b dotyczący art. 11 ust. 3a ustawy refundacyjnej\\tINFARMA niezmiennie stoi na stanowisku, że rozwiązanie – które jest ewenementem na skalę Europy – powinno zostać uchylone, i w tym zakresie powinny obowiązywać inne rozwiązania.  Niemniej jednak doceniamy pozytywny kierunek zmian.  Podtrzymując wskazany wyżej postulat usunięcia tego rozwiązania z ustawy refundacyjnej, ewentualnie zmiany punktu odniesienia do systemu refundacji pierwszego odpowiednika, jednocześnie w kolejnych punktach dotyczących omawianego rozwiązania proponujemy zmiany, które – w przypadku braku zgody na propozycje INFARMA rezygnacji z tego rozwiązania ustawowego lub zmiany punktu odniesienia – pozwoliłyby wyeliminować pewne praktyczne problemy rozwiązania zaproponowanego w nowelizacji przez Ministerstwo Zdrowia.\\t\\tUwaga niezasadna Zaproponowana zmiana podyktowana jest niejednoznacznością przepisów dotyczących konieczności obniżenia o 25 punktów procentowych ceny zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, w przypadku wygaśnięcia „ochrony wynikającej z patentu”, która miała jednocześnie wskazywać maksymalny okres na jaki mogłaby zostać wydana decyzja refundacyjna. Konieczność obniżenia ceny w sytuacji wygaśnięcia „ochrony wynikającej z patentu” została wprowadzona nowelizacją ustawy refundacyjnej, która weszła w życie z dniem 1 listopada 2023 r. Praktyka pracy organu nad wnioskami refundacyjnymi pokazała, że tzw. „gąszcze patentowe” uniemożliwiają jednoznaczne określenie momentu, po którym należy wypełnić taki obowiązek. Jednak w zaproponowanym brzmieniu Organ nie tylko proponuje usunięcie nieprecyzyjnego zapisu i powrót do brzmienia pierwotnego istniejącego od kilkunastu lat, lecz również wyjście naprzeciw postulatom Wnioskodawców, którzy podkreślają niejednokrotnie brak możliwości obniżania cen w związku z różnymi terminami wyłączności rynkowej w zależności od wskazania. Propozycja zakłada konieczność obniżenia warunków finansowych jednorazowo wraz końcem terminu wygaśnięcia okresu wyłączności rynkowej, który nastąpi jako pierwszy. Dodatkowo wypełnienie ustawowego \\fobowiązku obniżenia ceny z tytułu zakończenia wyłączności rynkowej danego produktu – redukcja ceny zbytu netto, redukcja ceny efektywnej, rozwiązanie hybrydowe polegające na redukcji ceny zbytu netto i ceny efektywnej łącznie o 25 punktów procentowych, albo dodanie instrumentu dzielenia ryzyka niezawartego w dotychczasowej decyzji refundacyjnej – okres, w którym ma nastąpić redukcja o 25% liczony jest od pierwszego dnia obowiązywania pierwszej decyzji refundacyjnej, a warunki finansowe wówczas obowiązujące stanowią tzw. punkt wyjściowy wyliczeń.\\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 pkt 7 lit. b dotyczący art. 11 ust. 3a ustawy refundacyjnej\\tW art. 11 ust. 3a proponujemy nadać następujące brzmienie: 3a. Okres obowiązywania decyzji administracyjnej o objęciu refundacją, o której mowa w ust. 1, nie może przekraczać najwcześniejszego terminu wygaśnięcia okresu wyłączności rynkowej, o którym mowa w art. 15 ust. 2 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne, niezależnie od wskazania. Zdanie pierwsze stosuje się jednorazowo w stosunku do danego leku\\tKF AmCham poddaje pod rozwagę uwzględnienie kontekstu leków sierocych/stosowanych w leczeniu chorób rzadkich w ramach zmian zaproponowanych w zmodyfikowanym przepisie art. 11 ust. 3a UoR. Przepis w jego obecnym brzmieniu (doprecyzowanie, że obowiązkowa obniżka musi nastąpić w związku z wygaśnięciem najwcześniejszego okresu wyłączności rynkowej „niezależnie od wskazania”) może spowodować, że wnioskodawcy nie będą decydować się na wprowadzenie do polskiego systemu refundacji dodatkowych wskazań dla leków sierocych/stosowanych w chorobach rzadkich, pomimo faktu ich zarejestrowania.  Zaproponowane rozwiązanie byłoby najbardziej skutecznym i prostym w tym kontekście. Alternatywnie, możliwe byłoby stworzenie przepisu szczególnego dla leków \\fsierocych/stosowanych w leczeniu chorób rzadkich.\\t\\fUwaga niezasadna Propozycja zakłada konieczność obniżenia warunków finansowych jednorazowo (redukcja o 25% liczona jest od pierwszego dnia obowiązywania pierwszej decyzji refundacyjnej, a warunki finansowe wówczas obowiązujące stanowią tzw. punkt wyjściowy wyliczeń) wraz z końcem terminu wygaśnięcia okresu wyłączności rynkowej, który nastąpi jako pierwszy. Powyższe zakłada jednorazowe obniżenie warunków finansowych niezależnie od wskazania w stosunku do danego leku.\\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\tArt. 1 pkt 7 lit. c projektu w zakresie dodawanego ust. 3b \\tWykreślenie przepisu\\tJest to przerzucanie ciężaru na podmiot, należy lepiej zorganizować proces kontraktowania świadczeń. Ustawa nie precyzuje, co stanie się w przypadkach, kiedy proces kontraktowania przekroczy zakładany okres 3 miesięcy, bowiem nie narzuca jednocześnie na Narodowy Fundusz Zdrowia obowiązku zakończenia procesu kontraktowania w czasie 3 miesięcy od objęcia refundacją nowej terapii. Dla terapii stosowanych jeden raz w życiu pacjenta albo przez określony czas (np. kilka tygodni lub cykli leczenia) przepis będzie uniemożliwiał ubieganie się o refundację w Polsce, z powodu nadmiernie rygorystycznych zobowiązań finansowych dla wnioskodawcy, co ograniczy dostęp chorych do terapii\\tUwaga niezasadna Projekt został zmieniony w zakresie ,,pomostowego dostępu” do terapii (uzasadnienie w pkt. 225). \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 7 lit. c dotyczący art. 11 ust. 3b ustawy refundacyjnej\\t3b. Decyzja administracyjna o objęciu refundacją leku albo środka spożywczego specjalnego przeznaczenia żywieniowego, który nie ma odpowiednika refundowanego w danym wskazaniu w kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, dla którego tworzy się nowy program lekowy zawiera, w ramach instrumentu dzielenia ryzyka, o którym mowa w ust. 5, zobowiązanie wnioskodawcy do odpłatnego dostarczenia do świadczeniodawcy i sfinansowania , na zasadach określonych w instrumencie dzielenia ryzyka, leku albo środka spożywczego specjalnego przeznaczenia żywieniowego od pierwszego dnia obowiązywania decyzji, do dnia zawarcia przez Fundusz umowy o udzielanie \\fświadczeń opieki zdrowotnej w zakresie danego programu lekowego, jednak nie dłużej niż przez 3 miesiące.\\t\\fINFARMA od wielu lat wskazywała na problem realnej dostępności świadczeniobiorców do programu lekowego w czasie od razu po jego wejściu w życie.  W tym kontekście doceniamy, że Ministerstwo Zdrowia podjęło ten temat. Jednocześnie INFARMA nie uważa, że przerzucenie ciężaru organizacyjnego i finansowego na wnioskodawców to najbardziej optymalne rozwiązanie. W tym zakresie cały czas postulujemy rozwiązania systemowe na poziomie NFZ oraz szpitali. Niemniej jednak pragniemy konstruktywnie podejść do zaproponowanego rozwiązania i \\fwykreślić obowiązek finansowania tych produktów. Przepisy powinny jasno wskazywać, z resztą zgodnie z intencją Ministerstwa Zdrowia przekazywaną na spotkaniach z branżą, że takie działanie ma mieć charakter nadzwyczajny, ale komercyjny. Skoro to rozwiązanie będzie funkcjonować na bazie instrumentu dzielenia ryzyka to zasady finansowania powinny być ustalane indywidualnie i wpisane do RSS. Takie podejście jest także spójne ze stanowiskiem MZ zaprezentowanym na spotkaniu dnia 2 czerwca 2025 r., gdzie wskazano, że 1) MZ nie wymaga od wnioskodawców przekazywania leków za darmowo, 2) MZ chce dać swobodę w określeniu modelu finansowania w ramach RSS. \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. Zgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia \\fżywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego. \\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 pkt 7 lit. c dotyczący art. 11 ust. 3b ustawy refundacyjnej\\tW art. 11 ust. 3b proponujemy nadać następujące brzmienie: 3b. Decyzja administracyjna o objęciu refundacją leku albo środka spożywczego specjalnego przeznaczenia żywieniowego, który nie ma odpowiednika refundowanego w danym wskazaniu w kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, dla którego tworzy się nowy program lekowy zawiera, w ramach instrumentu dzielenia ryzyka, o którym mowa w ust. 5, zobowiązanie wnioskodawcy do dostarczenia do świadczeniodawcy, o którym mowa w art. 16c, i sfinansowania leku albo środka spożywczego specjalnego przeznaczenia żywieniowego od pierwszego dnia obowiązywania decyzji, do \\fdnia zawarcia przez Fundusz umowy o udzielanie świadczeń opieki zdrowotnej w zakresie danego programu lekowego, jednak nie dłużej niż przez 3 miesiące.\\t\\fW związku z informacją przekazaną podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca br., że celem regulacji zawartej w przepisie art. 11 ust. 3b nie było pokrycie kosztu dostarczenia leku do świadczeniodawców w okresie pierwszych trzech miesięcy obowiązywania decyzji o objęciu refundacją, KF AmCham proponuje modyfikację przedmiotowego przepisu.  Proponowana zmiana ma na celu zwiększenie elastyczności i efektywności w procesie refundacji nowych leków i środków spożywczych specjalnego przeznaczenia żywieniowego, co jest kluczowe dla szybszego wdrażania \\finnowacyjnych terapii w systemie opieki zdrowotnej i zapewnienie realnego dostępu do leczenia dla pacjentów jak najszybciej po dacie refundacji. Zmiana ta wprowadza istotne usprawnienia w procesie, zachowując równocześnie kontrolę nad odpowiedzialnością stron. Usunięcie słowa „sfinansowania” i przeniesienie kwestii sposobu dostarczenia leku i mechanizmu jego finansowania przez NFZ w okresie przejściowym do indywidualnie negocjowanego instrumentu dzielenia ryzyka daje obu stronom – zarówno producentom, jak i Ministerstwu Zdrowia – większą elastyczność w ustalaniu warunków realizacji tego celu. Zamiast narzucać obowiązek finansowy, co mogłoby w niektórych przypadkach stanowić barierę bądź nawet uniemożliwiać wprowadzenie danej terapii do refundacji, zmiana ta umożliwia dopasowanie warunków do rzeczywistych potrzeb oraz aktualnych możliwości stron. W ocenie KF AmCham zaproponowana zmiana będzie zgodna z założeniami MZ co do celu tego przepisu.\\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. Zgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia \\fżywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 7 lit. c odnoszący się do art. 11 ust. 3b\\t3b. Decyzja administracyjna o objęciu refundacją leku albo środka spożywczego specjalnego przeznaczenia żywieniowego, który nie ma odpowiednika refundowanego w danym wskazaniu w kategorii dostępności refundacyjnej, o \\fktórej mowa w art. 6 ust. 1 pkt 2, dla którego tworzy się nowy program lekowy zawiera, w ramach instrumentu dzielenia ryzyka, o którym mowa w ust. 5, zobowiązanie wnioskodawcy do dostarczenia do świadczeniodawcy i sfinansowania leku albo środka spożywczego specjalnego przeznaczenia żywieniowego od pierwszego dnia obowiązywania decyzji, do dnia zawarcia przez Fundusz umowy o udzielanie świadczeń opieki zdrowotnej w zakresie danego programu lekowego, jednak nie dłużej niż przez 3 miesiące.\\t\\fPodmiotem zobowiązanym do finansowania ze środków publicznych świadczeń gwarantowanych jest Narodowy Fundusz Zdrowia. Konieczne zatem jest wykreślenie słowa “sfinansowanie” z projektowanego przepisu i dodanie (w UR i/lub UoŚ) \\fprzepisów jednoznacznie zobowiązujących NFZ do refundacji leku dostarczonego do świadczeniodawcy od pierwszego dnia obowiązywania decyzji.  Rozwiązaniem konstruktywnie wychodzącym naprzeciw problemowi braku faktycznej dostępności dla pacjentów do świadczenia gwarantowanego od 1. dnia po wejściu w życie decyzji MZ może być “kredytowanie” NFZ przez Wnioskodawców w okresie dopełniania przez stronę publiczną niezbędnych działań formalno-biurokratycznych, a nie przerzucenie na nich zadań płatnika publicznego – jednak jest to materia do uregulowania w treści instrumentów dzielenia ryzyka. Uważamy że analogicznym rozwiązaniem należałoby objąć wszystkie nowe technologie lekowe (również takie dla których nie tworzy się nowego programu lekowego), ponieważ w tej sytuacji aktualnie również faktyczna dostępność dla pacjentów nie jest zapewniona od 1. dnia po wejściu w życie decyzji MZ. Podsumowując, przy założeniu, że koszty refundacji ponosi płatnik publiczny, a nie wnioskodawca, konieczne jest rozszerzenie mechanizmu na wszystkie nowe technologie lekowe. Tylko w ten sposób możliwe będzie zapewnienie równego, realnego dostępu do świadczeń gwarantowanych od momentu wejścia decyzji w życie\\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. \\fZgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia żywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 7 lit. c projektu odnoszący \\fsię do art. 11 ust. 3b ustawy refundacyjnej\\t\\fWnosimy o uchylenie ust. 3b w art. 11 ustawy refundacyjnej.\\tWniosek o uchylenie art. 11 ust. 3b ustawy refundacyjnej (art. 1 pkt 7 lit c projektu) argumentujemy przerzuceniem \\fcałej odpowiedzialności za niekorzystne dla pacjentów leczonych w ramach programów lekowych rozwiązania systemowe na wnioskodawców.  Proponowana zmiana z jednej strony ma na celu zobligowanie wnioskodawcy do zawarcia instrumentu dzielenia ryzyka dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzony jest nowy program lekowy, w którym zobowiązany będzie do dostarczenia i sfinansowania leku albo środka spożywczego specjalnego przeznaczenia żywieniowego do świadczeniodawcy od pierwszego dnia obowiązywania decyzji, do dnia zawarcia przez NFZ umowy o udzielanie świadczeń opieki zdrowotnej w zakresie danego programu lekowego, jednak nie dłużej niż przez 3 miesiące, a z drugiej strony nie nakłada na NFZ obowiązku zawarcia umów ze świadczeniodawcami w przedmiotowym okresie.  Wydłużony okres oczekiwania pacjentów na kwalifikację do nowych programów lekowych wynika nie tylko z samego procesu zawierania umów ze świadczeniodawcami, poprzedzonego wydaniem zarządzenia Prezesa NFZ, który w zależności od trybu – rokowania \\flub konkurs ofert – powinien trwać nie dłużej niż 4 do 5 tygodni, ale przede wszystkim z praktyką ogłaszania przez OW NFZ postępowań konkursowych z kilkutygodniowym lub nawet kilkumiesięcznym opóźnieniem ze względu na brak zabezpieczonych na ten cel środków w planie finansowym.    Brak określenia w ustawie o świadczeniach obowiązku zawarcia umów przez NFZ z realizatorami nowych programów lekowych w ciągu 3 miesięcy od pierwszego dnia obowiązywania obwieszczenia powoduje, że po tym terminie, w przypadku nie zawarcia przedmiotowych umów, pacjent zgodnie z ustawą traci możliwość kontynuacji leczenia.  Obligowanie wnioskodawcy do dostarczenia leku albo środka spożywczego specjalnego przeznaczenia żywieniowego do świadczeniodawcy oraz do jego sfinansowania przez okres 3 miesięcy od pierwszego dnia obowiązywania decyzji dla nowotworzonego programu lekowego bez jednoczesnego nałożenia na NFZ obowiązku zawarcia umów ze świadczeniodawcami w przedmiotowym okresie budzi poważne wątpliwości co do odpowiedzialności poszczególnych interesariuszy systemu za zabezpieczenie kontynuacji terapii dla chorych po tym okresie, stwarzając tym \\fsamym dodatkowe potencjalne ryzyko finansowe po stronie wnioskodawcy. \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego \\frozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. Zgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia żywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego.\\n\\tPracodawcy RP\\tArt. 1 pkt 7 lit. c oraz art. 1 pkt 15 projektu dotyczący art. 11 ust. 3b oraz art. 16c ustawy refundacyjnej\\tProponujemy usunięcie przepisów art. 11 ust. 3b i art. 16c i rozważenie wprowadzenia systemowego rozwiązania, które mogłoby obejmować, np.: stworzenia świadczenia gwarantowanego, obejmującego pełną procedurę kwalifikacji, diagnostyki, podania leku i wszelkich związanych z tym dodatkowych elementów w ramach programu lekowego w okresie od wejścia w życie decyzji o objęciu refundację do zakontraktowania danego programu lekowego przez NFZ, do którego np. „dosumowywany” byłby koszt konkretnego leku; wprowadzenia uproszczonej procedury kontraktowania programów lekowych obejmującej, między innymi, rokowania pomiędzy OW NFZ a świadczeniodawcami oraz umożliwienie szpitalom szybkiego nabycia leków.\\tPomimo niewątpliwie słusznej i w pełni popieranej koncepcji zapewnienia leczenia w programach lekowych od pierwszego dnia obowiązywania decyzji Pracodawcy RP stoją na stanowisku, że zaproponowany mechanizm może być w praktyce trudny do realizacji. Przekazane podczas spotkania w dniu 2 czerwca założenie, że miałyby to być 1-2 ośrodki w kraju miałoby szansę powodzenia w małych populacjach pacjentów zgromadzonych wokół tych ośrodków. Ponadto proces dostarczania i późniejszego rozliczania przekazanych leków może okazać się trudny do realizacji z punktu widzenia podatkowego oraz łańcuchów dystrybucji, w których funkcjonują podmioty spoza grup kapitałowych wnioskodawców. Z tego względu apelujemy o rozważenie wprowadzenia bardziej systemowego rozwiązania, np. spośród zaproponowanych przez nas w kolumnie po lewej stronie.\\tUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. Zgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia żywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 7 lit. c odnoszący się do art. 11 ust. 3c\\tWARIANT A  3c. Decyzja administracyjna o objęciu refundacją leku stosowanego w onkologii albo chorobie rzadkiej zawiera, w ramach instrumentu dzielenia ryzyka, o którym mowa w ust. 5, zobowiązanie \\fwnioskodawcy do sfinansowania niewykorzystanej części opakowania, które to wynika z indywidualnego dawkowania na kilogram masy ciała lub powierzchnię ciała świadczeniobiorcy.       WARIANT B 3c. Decyzja administracyjna o objęciu refundacją leku stosowanego w onkologii albo chorobie rzadkiej zawiera, w ramach instrumentu dzielenia ryzyka, o którym mowa w ust. 5, zobowiązanie wnioskodawcy do sfinansowania połowy kosztu niewykorzystanej części opakowania, które to wynika z indywidulanego dawkowania na kilogram jednostkę masy ciała lub powietrzchnię ciała świadczeniobiorcy. Pozostałą część kosztu ponosi świadczeniodawca.    \\t\\fWARIANT A Postulujemy usunięcie projektowanego przepisu. Nie do zaakceptowania jest zmuszanie wnioskodawców do zawierania RSS. \\fZawieranie RSS jest uprawnieniem wnioskodawców, a nie ich obowiązkiem. Nie do zaakceptowania jest również ustawowe przerzucanie kosztów tzw. wastage na wnioskodawców, którzy nie mają żadnego wpływu na organizację świadczeń w podmiotach leczniczych. Zaproponowany mechanizm nie sprzyja efektywnemu gospodarowaniu refundowanymi lekami, demotywując podmioty lecznicze. Przerzucenie kosztów wastage na wnioskodawców nie przyniesie też płatnikowi publicznemu faktycznych oszczędności, ponieważ koszt ten zostanie de facto przeniesiony na płatnika w odpowiednio zwiększonej cenie jednostkowej leku. Zaproponowany mechanizm może zostać ujęty dobrowolnie jako element RSS przez tych wnioskodawców, którzy są gotowi uczestniczyć lub współuczestniczyć w kosztach wastage.   WARIANT B Na wypadek gdyby Projektodawca, pomimo zgłaszanych wątpliwości, zdecydował się utrzymać przedstawioną koncepcję, wskazujemy następujące szczegółowe uwagi. Nie ma żadnego racjonalnego uzasadnienia aby ew. nowy mechanizm dotyczył leku stosowanego w onkologii albo chorobie rzadkiej a nie dotyczył (przykładowo) leku stosowanego w ginekologii czy dermatologii - jeśli wejdzie w życie powinien konsekwentnie objąć wszystkie leki dawkowane na kilogram masy ciała lub powierzchnię ciała. \\fMechanizm powinien również czynić współodpowiedzialnym za koszt – samego świadczeniodawcę, bowiem to wyłącznie od jego personelu zależy skala tych kosztów. Przepis nie powinien przerzucać całego kosztu na innego podmiotu (w tym wnioskodawcę), gdyż w ten sposób nie motywuje się świadczeniodawców do efektywnego wykorzystywania leków finansowanych ze środków publicznych. Nowy mechanizm powinien dotyczyć wyłącznie nowych technologii lekowych obejmowanych po raz pierwszy refundacją po wejściu w życie nowelizacji (zob. postulat dot. dodania odpowiedniego przepisu przejściowego – zob. poniżej art. 9a nowelizacji). W przeciwnym wypadku istnieje bardzo wysokie ryzyko niewystępowania Wnioskodawców o kontynuację refundacji po upływie okresu aktualnych decyzji refundacyjnych. Przykładowo, jeśli poziom wastage wynosi 25% to efektywna cena zbytu spada o 29% (wliczając marżę hurtową i VAT) co w wielu przypadkach spowoduje utratę rentowności i brak możliwości kontynuacji dostarczania leku w dotychczasowej cenie zbytu. \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania. W dodawanym ust. 3d przewidziano, że w przypadku ustalenia rozliczenia na opakowania lub fiolki, \\fzamiast rozliczenia według rzeczywistej ilości podanej świadczeniobiorcy, decyzja administracyjna o objęciu refundacją leku, refundowanego w ramach programu lekowego, musi zawierać w ramach instrumentu dzielenia ryzyka, zobowiązanie wnioskodawcy do zwrotu części uzyskanej refundacji podmiotowi zobowiązanemu do finansowania świadczeń ze środków publicznych powyżej ustalonego limitu finansowania tego leku w każdym roku obowiązywania decyzji o objęciu refundacją. Zgodnie zaś z ust. 3e limit ten, nie może być wyższy niż koszty leku we wnioskowanym wskazaniu przedstawione w analizie wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, o której mowa w art. 25 pkt 14 lit. c. W przypadku rozliczania danej według rzeczywistej ilości podanej pacjentowi w przypadku leków stosowanych w onkologii albo chorobie rzadkiej ewentualne straty technologiczne byłyby pokrywane przez NFZ ze środków finansowych pochodzących z subfunduszu terapeutyczno-innowacyjnego.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 7 lit. c projektu w zakresie dodawanego ust. 3c ustawy refundacyjnej)\\tWnioskujemy o uchylenie proponowanej w dodawanym w art. 11 ust. 3c (art. 1 pkt 7 lit c projektu) zmiany wprowadzającej obowiązek zawarcia instrumentu dzielenia ryzyka w ramach decyzji administracyjnej o objęciu refundacją i ustaleniu ceny zbytu netto, zobowiązującego wnioskodawcę do finansowania niewykorzystanej części \\fopakowania, które to wynika z indywidulanego dawkowania na kilogram masy ciała lub powietrznię ciała świadczeniobiorcy.   \\t\\fZgodnie z projektowaną zmianą art. 11 ust. 3c ustawy refundacyjnej całe ryzyko związane z procesem powstawania strat, które są generowane przez szpitale w wyniku sporządzenia indywidualnych dawek dla pacjentów, na skutek przyjętego w zarządzeniu Prezesa NFZ w sprawie określenia warunków \\fzawierania i realizacji umów w rodzaju leczenie szpitalne w zakresie programy lekowe sposobu rozliczania leków w programach lekowych, miałby wziąć na siebie wnioskodawca.   Warto w tym miejscu przypomnieć, iż przed wejściem w życie ustawy refundacyjnej koszty tego typu strat w ograniczonym zakresie i w zależności od leczonej populacji (dorośli lub dzieci) pokrywał płatnik publiczny.  Jednocześnie pozytywnie oceniamy propozycję ustawodawcy dotyczącą zmian w art. 7 ustawy o Funduszu Medycznym (art. 6 pkt 1 projektu). \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania. W dodawanym ust. 3d przewidziano, że w przypadku ustalenia rozliczenia na opakowania lub fiolki, zamiast rozliczenia według rzeczywistej ilości podanej świadczeniobiorcy, decyzja administracyjna o objęciu refundacją \\fleku, refundowanego w ramach programu lekowego, musi zawierać w ramach instrumentu dzielenia ryzyka, zobowiązanie wnioskodawcy do zwrotu części uzyskanej refundacji podmiotowi zobowiązanemu do finansowania świadczeń ze środków publicznych powyżej ustalonego limitu finansowania tego leku w każdym roku obowiązywania decyzji o objęciu refundacją. Zgodnie zaś z ust. 3e limit ten, nie może być wyższy niż koszty leku we wnioskowanym wskazaniu przedstawione w analizie wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, o której mowa w art. 25 pkt 14 lit. c. W przypadku rozliczania danej według rzeczywistej ilości podanej pacjentowi w przypadku leków stosowanych w onkologii albo chorobie rzadkiej ewentualne straty technologiczne byłyby pokrywane przez NFZ ze środków finansowych pochodzących z subfunduszu terapeutyczno-innowacyjnego.\\n\\tRada Organizacji Pacjentów przy Rzeczniku Praw Pacjenta\\tArt. 1 pkt 7 lit. c projektu w zakresie dodawanego ust. 3c ustawy refundacyjnej\\tArt. 11 4. Podwyższenie albo obniżenie urzędowej ceny zbytu następuje w drodze zmiany decyzji administracyjnej o objęciu refundacją, o której mowa w ust. 1, a w przypadku, o którym mowa w art. 11a, w drodze obwieszczenia, o którym mowa w art. 37 ust. 1.  Art. 11a  1. Jeżeli średnioroczny wskaźnik cen towarów i usług konsumpcyjnych ogółem  w poprzednim roku, ogłaszany przez Prezesa Głównego Urzędu Statystycznego, \\fprzekracza wartość 105, minister właściwy do spraw zdrowia podwyższa urzędowe ceny zbytu leków, których urzędowa cena zbytu w dniu 1 stycznia roku bieżącego nie przekracza 75 zł, w najbliższym obwieszczeniu, o którym mowa w art. 37 ust. 1, o wartość wskazaną w ust. 2 i 3 poniżej, oraz podwyższa ceny detaliczne odpowiednio, zaokrąglając je w górę do pełnych groszy.  2. Urzędową cenę zbytu nieprzekraczającą 50 zł podwyższa się o wartość średniorocznego wskaźnika cen towarów i usług konsumpcyjnych ogółem w poprzednim roku, ogłaszanego przez Prezesa Głównego Urzędu Statystycznego, pomniejszoną o 3 punkty procentowe.  3. Urzędową cenę zbytu przekraczającą 50 zł, a nieprzekraczającą 75 zł, podwyższa się o wartość średniorocznego wskaźnika cen towarów i usług konsumpcyjnych ogółem w poprzednim roku, ogłaszanego przez Prezesa Głównego Urzędu Statystycznego, pomniejszoną o 5 punktów procentowych. 4. Przepisów ust. 1-3 nie stosuje się do leków, środków spożywczych specjalnego przeznaczenia żywieniowego, wyrobów medycznych, które są jedynymi produktami refundowanymi w danym wskazaniu lub które są zawarte w wykazie, o którym mowa w art. 37 ust. 1, nieprzerwanie krócej niż 6 miesięcy. \\t\\tUwaga niezasadna  W opinii Ministerstwa Zdrowia nie jest możliwe, aby pacjenci oczekiwali systematycznego wzrostu cen produktów refundowanych.  \\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\tArt. 1 pkt 7 lit. c projektu w zakresie dodawanego ust. 3c \\tWykreślenie przepisu\\tPrzeniesienie ryzyka pokrywania kosztów strat technologicznych (ang. wastage) przez szpitale dla terapii stosowanych w dawkowaniu na kg masy ciała. lub powierzchnię ciała nie musi odbywać się drogą zmian ustawy o refundacji. W zarządzeniu Prezesa NFZ \\fwystarczy doprecyzować rodzaj jednostki rozliczeniowej dla danego leku z „mg” na „opakowanie”, tak, aby NFZ pokrywał szpitalom koszt zakupu całego opakowania a nie jedynie zużytej substancji czynnej. W obecnym kształcie przepis przerzuca całość ryzyka na Wnioskodawcę.\\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania. W dodawanym ust. 3d przewidziano, że w przypadku ustalenia rozliczenia na opakowania lub fiolki, zamiast rozliczenia według rzeczywistej \\filości podanej świadczeniobiorcy, decyzja administracyjna o objęciu refundacją leku, refundowanego w ramach programu lekowego, musi zawierać w ramach instrumentu dzielenia ryzyka, zobowiązanie wnioskodawcy do zwrotu części uzyskanej refundacji podmiotowi zobowiązanemu do finansowania świadczeń ze środków publicznych powyżej ustalonego limitu finansowania tego leku w każdym roku obowiązywania decyzji o objęciu refundacją. Zgodnie zaś z ust. 3e limit ten, nie może być wyższy niż koszty leku we wnioskowanym wskazaniu przedstawione w analizie wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, o której mowa w art. 25 pkt 14 lit. c. W przypadku rozliczania danej według rzeczywistej ilości podanej pacjentowi w przypadku leków stosowanych w onkologii albo chorobie rzadkiej ewentualne straty technologiczne byłyby pokrywane przez NFZ ze środków finansowych pochodzących z subfunduszu terapeutyczno-innowacyjnego.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 7 lit. c dotyczący art. 11 ust. 3c ustawy refundacyjnej\\tSkreślenie 3c. Decyzja administracyjna o objęciu refundacją leku stosowanego w onkologii albo chorobie rzadkiej zawiera, w ramach instrumentu dzielenia ryzyka, o którym mowa w ust. 5, zobowiązanie wnioskodawcy do sfinansowania niewykorzystanej części opakowania, które to wynika z indywidulanego dawkowania na kilogram masy ciała lub powietrznię ciała świadczeniobiorcy. \\fJednocześnie proponuje się w art. 11 ust. 5 po pkt 4a dodanie pkt 4b w brzmieniu: 4b) ustalenia zasad finansowania przez wnioskodawcę całości lub części niewykorzystanej zawartości opakowania leku, która to wynika z indywidualnego dawkowania na kilogram masy ciała lub powierzchnię ciała świadczeniobiorcy; oraz dodanie ust. 5c w brzmieniu: 5c. W przypadku gdy decyzja administracyjna o objęciu refundacją, o której mowa w ust. 1, zawiera instrument dzielenia ryzyka, o którym mowa w ust. 5 pkt 4b: 1) Prezes Funduszu określi, w drodze zarządzenia, obowiązek kohortowania świadczeniobiorców przez świadczeniodawców oraz zasady monitorowania i egzekwowania tego obowiązku; 2) minister właściwy do spraw zdrowia udostępnia wnioskodawcy, na jego wniosek, dane dotyczące niewykorzystywanej zawartości opakowania leku.\\t\\fZdaniem INFARMA zasadnym jest, aby kwestia RSS w zakresie tzw. „drug wastage” pozostała – tak jak jest dotychczas w ramach fakultatywnego instrumentu dzielenia ryzyka.  Takie rozwiązanie zabezpiecza wszystkie strony tj. wnioskodawcę, MZ,  NFZ oraz świadczeniodawców.  W przypadku: \\fa) wnioskodawcy –  pozwala na ustalenie jaki poziom „drug wastage” będzie chciał sfinansować (część, wszystko) oraz w jaki sposób. Obecne brzmienie przepisu jest niezwykle groźne, gdyż przerzuca na wnioskodawców (z uwagi na obligatoryjność oraz sformułowanie „zobowiązanie wnioskodawcy do sfinansowania niewykorzystanej części opakowania”) finansowanie całości „drug wastage”, bez jednoczesnego wymagania od świadczeniodawców kohortowania pacjentów połączonego z systemem weryfikacji realizacji takiego obowiązku przez szpitale. Jednocześnie takie rozwiązanie jest prawdziwym instrumentem dzielenia ryzyka, gdyż pozwala realnie podzielić się ryzykiem między wnioskodawcę a świadczeniodawcę (co zarazem stanowi element motywowania szpitali do kohortowania pacjentów); b) MZ – nadal ma możliwość zobowiązania wnioskodawcy do przyjęcia takiego RSS w toku negocjacji czy całego postępowania refundacyjnego. Nie będzie miał tu automatyzmu, ale ma instrumenty wynikające z Ustawy refundacyjnej i KPA do wywarcia presji na wnioskodawcy; c) NFZ – płatnik publiczny nadal nie ponosi kosztów za „drug wastage”; d) świadczeniodawcy – odpowiednie podejście szpitala do kohortowania pacjentów pozwoli na optymalizację kosztów, minimalizując przy tym ryzyko strat leku. \\fNiezależnie od tego zasadnym jest, aby w przypadku takiego RSS istniał obowiązek (połączony z monitorowaniem i egzekucją) świadczeniobiorców do kohortowania pacjentów oraz obowiązek udostępnienia stosownych danych dot. drug wastage do wnioskodawcy.\\t\\fUwaga częściowo zasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania. W dodawanym ust. 3d przewidziano, że w przypadku ustalenia rozliczenia na opakowania lub fiolki, zamiast rozliczenia według rzeczywistej ilości podanej świadczeniobiorcy, decyzja administracyjna o objęciu refundacją leku, refundowanego w ramach programu lekowego, musi zawierać w ramach instrumentu dzielenia ryzyka, \\fzobowiązanie wnioskodawcy do zwrotu części uzyskanej refundacji podmiotowi zobowiązanemu do finansowania świadczeń ze środków publicznych powyżej ustalonego limitu finansowania tego leku w każdym roku obowiązywania decyzji o objęciu refundacją. Zgodnie zaś z ust. 3e limit ten, nie może być wyższy niż koszty leku we wnioskowanym wskazaniu przedstawione w analizie wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, o której mowa w art. 25 pkt 14 lit. c. W przypadku rozliczania danej według rzeczywistej ilości podanej pacjentowi w przypadku leków stosowanych w onkologii albo chorobie rzadkiej ewentualne straty technologiczne byłyby pokrywane przez NFZ ze środków finansowych pochodzących z subfunduszu terapeutyczno-innowacyjnego. Minister Zdrowia uznaje jednak za zasadne dodanie zapisów zobowiązujących Prezesa Narodowego Funduszu Zdrowia do monitorowania i egzekwowania obowiązku kohortowania pacjentów przez świadczeniodawców oraz przekazywania danych o niewykorzystanych zawartości opakowań leku na wniosek podmiotu odpowiedzialnego.  \\n\\tIzba Gospodarcza „FARMACJA POLSKA” \\tArt. 1 pkt 7 lit. c dotyczący art. 11 ust. 3b ustawy refundacyjnej\\tDlatego proponujemy zmianę brzmienia art. 11 ust. 3b ustawy, w sposób, który da stronom większą swobodę ustalenia warunków pokrycia kosztu leczenia pacjentów w okresie przejściowym, na przykład poprzez wskazanie w treści przepisu, że wnioskodawca będzie zobowiązany do dostarczania leku lub śsspż w okresie przejściowym na warunkach ustalonych w instrumencie dzielenia ryzyka, w celu zapewnienia pacjentom dostępu do leczenia w okresie do zawarcia przez NFZ umowy o udzielanie świadczeń opieki zdrowotnej w zakresie nowego programu lekowego, jednak nie dłużej niż przez 3 miesiące. Taka redakcja przepisu pozwoli zarówno na ustalenie zasad współfinansowania leku w tym okresie przez wnioskodawcę, jak i ustalenia innych obowiązków wnioskodawcy, mających na celu ułatwienie pacjentom szybszego dostępu do leczenia.\\tArt. 11 ust. 3b – nowy instrument dzielenia ryzyka dla leku lub środka spożywczego specjalnego przeznaczenia żywieniowego (śsspż) niemającego odpowiednika refundowanego w danym wskazaniu w programie lekowym, dla którego tworzy się nowy program W pełni rozumiemy potrzebę zapewnienia pacjentom szybszego dostępu do produktów refundowanych, dla których tworzony jest nowy program lekowy. Niemniej, zaproponowane w projekcie rozwiązanie, w postaci obowiązkowego instrumentu dzielenia ryzyka, zawierającego zobowiązanie wnioskodawcy do dostarczenia do świadczeniodawcy i sfinansowania leku albo śsspż od pierwszego dnia obowiązywania decyzji, do dnia zawarcia przez Fundusz umowy o udzielanie świadczeń opieki zdrowotnej w zakresie danego programu lekowego, jednak nie dłużej niż przez 3 miesiące, naszym zdaniem nie jest właściwe. Po pierwsze, w naszej ocenie obowiązkowy RSS nie rozwiązuje zasadniczego problemu, jakim jest zbyt wolne procedowanie przez NFZ kontraktowania programu lekowego. Jak \\frozumiemy z wypowiedzi przedstawicieli Ministerstwa Zdrowia, zakładają Państwo, że wskazany w przepisie trzymiesięczny okres, przez który wnioskodawca ma dostarczyć i sfinansować do świadczeniodawcy refundowany produkt, zmobilizuje NFZ do zamknięcia procesu kontraktowania programu lekowego w tym właśnie okresie. Jednakże nie ma żadnej gwarancji, że taki będzie skutek zawarcia przez wnioskodawcę żądanego instrumentu dzielenia ryzyka.  Po drugie, wskazana w przepisie obowiązkowa treść instrumentu dzielenia ryzyka oznacza, że w okresie 3 miesięcy wnioskodawca będzie musiał sfinansować dostawy leku czy śsspż: „wnioskodawca ma dostarczyć i sfinansować” refundowany produkt. Wprawdzie z wyjaśnień przedstawionych podczas niedawnego spotkania w Ministerstwie Zdrowia wynika, że obowiązek sfinansowania produktu mógłby być zrealizowany na przykład poprzez dłuższe terminy płatności za produkt tak, żeby szpital mógł opłacić zakup dopiero po zakontraktowaniu programu lekowego. Jednakże redakcja przepisu w projekcie nowelizacji ustawy o refundacji wskazuje na obowiązek „sfinansowania” produktu przez wnioskodawcę, a więc pokrycia jego \\fkosztu, a nie wyłącznie zaproponowania preferencyjnych zasad jego zakupu.  Tymczasem nałożenie na wnioskodawców bezwzględnego obowiązku sfinansowania produktu refundowanego na 3 miesiące w wielu przypadkach będzie nadmiernym obciążeniem dla wnioskodawców, trudnym do spełnienia. Będzie tak chociażby w przypadku leków, których schemat podania zakłada podanie raz w roku lub raz na pół roku – w tym przypadku wnioskodawca musiałby pokryć, odpowiednio, koszt 12-miesięcznej lub 6-miesięcznej terapii lekiem. Poza tym, projektowany art. 11 ust. 3b ustawy nie wskazuje, że wnioskodawca ma pokryć koszt dostaw produktu refundowanego wyłącznie do świadczeniodawców, wyznaczonych do zapewnienia pacjentom dostępu do leczenia w okresie przejściowym, zgodnie z art. 16c. A nawet, gdyby obowiązek dostaw był ograniczony tylko do tych świadczeniodawców, to podział kosztu leczenia pacjentów w nowym programie lekowym w okresie przejściowym, przed zakontraktowaniem programu, byłby nieproporcjonalny – w większości przypadków wnioskodawca ponosiłby nadmiernie wysokie koszty z tego tytułu.  Dlatego proponujemy zmianę brzmienia art. 11 ust. 3b ustawy, w sposób, który da stronom większą swobodę ustalenia \\fwarunków pokrycia kosztu leczenia pacjentów w okresie przejściowym, na przykład poprzez wskazanie w treści przepisu, że wnioskodawca będzie zobowiązany do dostarczania leku lub śsspż w okresie przejściowym na warunkach ustalonych w instrumencie dzielenia ryzyka, w celu zapewnienia   NFZ umowy o udzielanie świadczeń opieki zdrowotnej w zakresie nowego programu lekowego, jednak nie dłużej niż przez 3 miesiące. Taka redakcja przepisu pozwoli zarówno na ustalenie zasad współfinansowania leku w tym okresie przez wnioskodawcę, jak i ustalenia innych obowiązków wnioskodawcy, mających na celu ułatwienie pacjentom szybszego dostępu do leczenia. Jednocześnie zwracamy uwagę na fakt, że niezależnie od treści zawieranego w takiej sytuacji instrumentu dzielenia ryzyka do rozwiązania pozostanie zasadnicza kwestia w tym przypadku, czyli nieefektywny i zbyt długo trwający proces kontraktowania świadczenia przez NFZ. Przepisy ustawy o refundacji powinny przy tym jasno wskazywać, że po upływie pierwszych trzech miesięcy obowiązywania decyzji o refundacji produktu w nowym programie lekowym finansowanie produktu powinno przejść na NFZ.\\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. Zgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia żywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego.\\n\\tIzba Gospodarcza „FARMACJA POLSKA” \\tArt. 1 pkt 7 lit. c dotyczący art. 11 ust. 3c ustawy refundacyjnej\\tproponujemy wprowadzenie do ustawy nowego rodzaju instrumentu dzielenia ryzyka, dotyczącego pokrywania kosztów strat w lekach dawkowanych indywidualnie, ale jako rozwiązania opcjonalnego, nieobligatoryjnego; a przy tym dotyczącego współfinansowania, a nie finansowania wyłącznie przez wnioskodawcę, kosztu strat. W tej sytuacji wnioskodawcy będą mieli możliwość negocjowania z Komisją Ekonomiczną dokładnego zakresu obowiązków dotyczących minimalizowania kosztów świadczeniodawców, wynikających ze strat na skutek nieefektywnego podawania leków dawkowanych indywidualnie; a świadczeniodawcy nadal mieliby motywację do dbania do racjonalne gospodarowanie lekami. Jednocześnie świadczeniodawcy powinni być zobowiązani do kohortowania pacjentów stosujących leki dawkowane indywidualnie, na przykład w umowach z NFZ.  \\tArt. 11 ust. 3c - nowy instrument dzielenia ryzyka dla leku stosowanego w onkologii lub chorobie rzadkiej Dostrzegamy wagę problemu, jakim są straty generowane po stronie szpitali na skutek nieefektywnego wykorzystania leków refundowanych, które są dawkowane indywidualnie, w przeliczeniu na kg masy ciała lub powierzchnię ciała pacjenta. Jednak uważamy, że zaproponowane w projekcie nowelizacji ustawy o refundacji rozwiązanie, w postaci obowiązkowego instrumentu dzielenia ryzyka dla tak dawkowanych leków, stosowanych w onkologii lub chorobach rzadkich, nie jest właściwe i będzie prowadzić do większego ryzyka nieefektywnego wykorzystywania tych leków, z tym, że na koszt wnioskodawców. Z naszych obserwacji wynika, że obecnie świadczeniodawcy podejmują starania w celu zapobieżenia stratom na lekach dawkowanych indywidualnie, poprzez kolejkowanie pacjentów czy wprowadzanie systemów zarządzania podaniami leków tak, aby jak najefektywniej je wykorzystywać. W sytuacji, w której byliby całkowicie zwolnieni z obowiązku ponoszenia kosztów niewykorzystanej części opakowania leku, ryzyko nieuważnego gospodarowania lekami i marnowania części opakowań radykalnie wzrośnie, ponieważ świadczeniodawcy nie będą \\fzainteresowani podejmowaniem starań o jak najefektywniejsze wykorzystywanie leków. A to z kolei oznacza ryzyko rosnących kosztów po stronie wykonawców. Z drugiej strony, koszty te nie są odpowiednio skalkulowane w warunkach cenowych obowiązujących dla już refundowanych leków. Nowy obowiązek zawarcia instrumentu dzielenia ryzyka może bowiem dotknąć (przy okazji odnowienia decyzji o refundacji) leku od dawna refundowanego, na przykład takiego, który ma już zawarty instrument dzielenia ryzyka o innej treści, ustalający maksymalną cenę hurtową brutto za opakowanie produktu lub payback. Jeżeli wnioskodawca miałby ponosić koszt strat na skutek niewykorzystania części opakowań leku, to powinien mieć ten koszt skalkulowany w cenie efektywnej leku, której nie zmieni na swoją korzyść nawet przy odnowieniu decyzji o refundacji (z uwagi na treść art. 13 ust. 6aa ustawy). Problemem jest także brak dostępu wnioskodawców do informacji na temat wielkości strat i kosztów wynikających z nieefektywnego gospodarowania lekami dawkowanymi indywidualnie, co nie pozwala na oszacowanie kosztów wnioskodawców, wynikających z instrumentu dzielenia ryzyka, którego \\fzawarcie narzuca projekt nowelizacji ustawy o refundacji. \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania. W dodawanym ust. 3d przewidziano, że w przypadku ustalenia rozliczenia na opakowania lub fiolki, zamiast rozliczenia według rzeczywistej ilości podanej świadczeniobiorcy, decyzja administracyjna o objęciu refundacją leku, refundowanego w ramach programu lekowego, musi zawierać w ramach instrumentu dzielenia ryzyka, zobowiązanie wnioskodawcy do zwrotu części uzyskanej refundacji podmiotowi zobowiązanemu do finansowania świadczeń ze środków publicznych powyżej ustalonego limitu finansowania tego leku w każdym roku obowiązywania decyzji o objęciu refundacją. Zgodnie zaś z ust. 3e limit ten, nie może być wyższy niż koszty leku we wnioskowanym wskazaniu przedstawione w analizie wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, o której mowa w art. 25 pkt 14 lit. c. W przypadku rozliczania danej według rzeczywistej ilości podanej pacjentowi w przypadku leków stosowanych w onkologii albo chorobie rzadkiej ewentualne straty technologiczne byłyby pokrywane przez NFZ ze środków finansowych pochodzących z subfunduszu terapeutyczno-innowacyjnego.\\n\\tPracodawcy RP\\tArt. 1 pkt 7 lit. c dotyczący art. 11 ust. 3c ustawy refundacyjnej\\tProponujemy usunięcie przepisu art. 11 ust. 3c. \\tZe względu na brak możliwości (w tym procedury) weryfikacji danych oraz współpracy pomiędzy wnioskodawcą a NFZ w zakresie ustalenia faktycznego zużycia leków przez świadczeniodawców, w ocenie Pracodawców RP należy usunąć tę regulację z Projektu. Wprowadziłaby ona nadmierną nieprzewidywalność, która w połączeniu z brakiem regulacji obligujących świadczeniodawców do jak najbardziej racjonalnego i efektywnego podawania leków stosowanych na kilogram masy ciała lub powierzchnię ciała pacjenta, doprowadziłaby do jeszcze większych strat tych produktów. To przełożyłoby się na pogorszenie rzeczywistych warunków refundacji ustalonych w instrumencie dzielenia ryzyka, bez jakiegokolwiek wpływu na to po stronie wnioskodawców. W kontekście zaproponowanej przez Pracodawców RP zmiany należy mieć także na względzie istotne ryzyko rezygnacji ze składania wniosków o kontynuację refundacji przez wnioskodawców, których decyzje nie przewidują żadnych zasad rozliczania strat. W przypadku leków, dla których uśrednione straty są znaczące, konieczność poniesienia kosztu \\fnieuwzględnionego w ramach negocjacji wcześniejszych warunków refundacji może oznaczać konieczność zaprzestania refundacji w Polsce. \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania. W dodawanym ust. 3d przewidziano, że w przypadku ustalenia rozliczenia na opakowania lub fiolki, zamiast rozliczenia według rzeczywistej ilości podanej świadczeniobiorcy, decyzja administracyjna o objęciu refundacją leku, refundowanego w ramach programu lekowego, musi zawierać w ramach instrumentu dzielenia ryzyka, zobowiązanie wnioskodawcy do zwrotu części uzyskanej refundacji podmiotowi zobowiązanemu do finansowania świadczeń ze środków publicznych powyżej ustalonego limitu finansowania tego leku w każdym roku obowiązywania decyzji o objęciu refundacją. Zgodnie zaś z ust. 3e limit ten, nie może być wyższy niż koszty leku we wnioskowanym wskazaniu przedstawione w analizie wpływu na budżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, o której mowa w art. 25 pkt 14 lit. c. W przypadku rozliczania danej według rzeczywistej ilości podanej pacjentowi w przypadku leków stosowanych w onkologii albo chorobie rzadkiej ewentualne straty technologiczne byłyby pokrywane przez NFZ ze środków finansowych pochodzących z subfunduszu terapeutyczno-innowacyjnego.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 8 odnoszący się do Art. 12 pkt 14 i 15(dodany)\\tArt. 12 Minister właściwy do spraw zdrowia, mając na uwadze uzyskanie jak największych efektów zdrowotnych w ramach dostępnych środków publicznych, wydaje decyzję administracyjną o objęciu refundacją, przy uwzględnieniu następujących kryteriów: (…) 14) zobowiązania do zapewnienia ciągłości dostaw wraz z określeniem rocznej wielkości dostaw podanej w ujęciu miesięcznym, jeżeli dotyczy zabezpieczającym potrzeby zdrowotne świadczeniobiorców;  15) ujęcia leku na krajowej liście leków krytycznych lub unijnym wykazie produktów leczniczych o krytycznym znaczeniu. \\t       Fragment w pkt 14 o zabezpieczeniu potrzeb zdrowotnych świadczeniobiorców jest zbędny, ponieważ to Minister Zdrowia i Komisja Ekonomiczna decydują, w ramach negocjacji i decyzji, jaki poziom dostaw jest potrzebny w ujęciu całościowym oraz wystarczający w przypadku każdego indywidualnego dostawcy, kierując się kryteriami podanymi w nowo dodanym przepisie art. 19 ust. 2 pkt 8 Projektu. Pojedynczy dostawca nie odpowiada za zabezpieczenie całokształtu potrzeb zdrowotnych świadczeniobiorców.  Proponujemy też dodanie kryterium referującego do unijnej oraz polskiej listy leków krytycznych. Koresponduje to z projektem Aktu o lekach krytycznych (Critical Medicines Act) w art. 19 ust. 1 przewidziano obowiązek ustanowienia przez każde państwo członkowskie programu wspierania bezpieczeństwa dostaw leków krytycznych, w tym dotyczących ich refundacji. \\tUwaga niezasadna Zaproponowana treść ujęta w projekcie, odzwierciedla konieczność podania przez wnioskodawcę deklarowanych dostaw w ujęciu miesięcznym, uwzględniającym okres obowiązywania decyzji,  Pozostała cześć poza regulacją projektu  \\n\\tPolski Związek Pracodawców \\fPrzemysłu Farmaceutycznego/Polpharma\\t\\fArt. 12a i 12b ustawy \\frefundacyjnej\\t\\fArt. 12a.  \\f1. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego leku, który stanowi pierwszy lub kolejny odpowiednik leku refundowanego w danym wskazaniu lub znajdującego się na wykazie, o którym mowa w art. 37 ust. 1, oraz do wniosku, o którym mowa w art. 24 ust. 1 pkt 3, złożonego przez Partnera Bezpieczeństwa Lekowego nie stosuje się przepisów art. 12, art. 19 oraz art. 36.  2. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego leku, który nie posiada zarejestrowanego odpowiednika nie stosuje się ust. 1.  3. Za Partnera Bezpieczeństwa Lekowego uznaje się wnioskodawcę, będącego osobą prawną i jej podmioty powiązane zgodnie z definicją zawartą w ustawie o rachunkowości z dnia 29 września 1994 r., który spełnia przynajmniej jeden z następujących warunków:  a) co najmniej 25% wolumenu, wyrażonego w dobowej dawce leku ustalonej przez Światową Organizację Zdrowia (DDD) lub w innej jednostce stosowanej przez Ministra Zdrowia przy projektowaniu list refundacyjnych i limitów, jego leków objętych refundacją w roku poprzedzającym złożenie wniosku, o którym mowa w ust. 1, w kategorii dostępności, o której mowa w art. 6 ust. 1 pkt 1-3, jest wytwarzanych na terytorium Rzeczypospolitej Polskiej,   b) co najmniej 100 mln wolumenu wyrażonego w standardowej jednostce, uspójnionej dla różnych form jego leków jest wytwarzanych na terytorium Rzeczypospolitej Polskiej,  - w roku poprzedzającym złożenie wniosku, o którym mowa w ust. 1.  \\f4. W celu wykazania przesłanek, o których mowa w ust. 3 powyżej, wnioskodawca składa informację na piśmie o działalności inwestycyjnej w zakresie związanym z ochroną zdrowia, w obszarze produkcji leków, stanowiącą wzmacnianie bezpieczeństwa lekowego Polski. Wzór informacji zostanie określony w rozporządzeniu, o który mowa w ust. 7.   5. Przepis ust. 3 nie dotyczy wnioskodawcy, który jest wyłącznie importerem równoległym w rozumieniu ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne bądź którego zakres wytwarzania obejmuje wyłącznie czynności pakowania lub przepakowywania.  6. Pod pojęciem wytwarzania leku na terytorium Rzeczypospolitej Polskiej, o którym mowa w ust. 3, rozumie się wytwarzanie, o którym mowa w ustawie z dnia 6 września 2001 r. - Prawo farmaceutyczne.  7. Minister właściwy do spraw gospodarki w porozumieniu z ministrem właściwym do spraw zdrowia określi w drodze rozporządzenia wzór informacji o działalności inwestycyjnej w zakresie związanym z ochroną zdrowia, w obszarze produkcji leków, stanowiącą wzmacnianie bezpieczeństwa lekowego Polski.  8. Partner Bezpieczeństwa Lekowego nie podlega rozszerzonej odpowiedzialności producenta, o której mowa w art. 9 ust. 1 Dyrektywy Parlamentu Europejskiego i Rady (UE) 2024/3019 z dnia 27 listopada 2024 r. dotycząca ścieków komunalnych (wersja przekształcona) oraz w ustawie wykonującej tę dyrektywę.  \\fArt. 12b. 1. W przypadku rozpoznania wniosków, o których mowa w art. 24 ust. 1 pkt 1 złożonych przez Partnera Bezpieczeństwa Lekowego dla leku, który stanowi pierwszy lub kolejny odpowiednik leku refundowanego w danym wskazaniu, urzędowa cena zbytu ustalona w decyzji, o której mowa w art. 11 ust. 1, odpowiada urzędowej cenie zbytu, o której mowa w art. 13 ust. 6, chyba, że Wnioskodawca zaproponował we wniosku cenę zbytu netto pozwalającą na ustalenie urzędowej ceny zbytu na niższym poziomie.   2. Urzędowa cena zbytu leku, który w dniu złożenia wniosku o którym mowa w art. 24 ust. 1 pkt 1, był zawarty w wykazie, o którym mowa w art. 37 ust. 1, w danym wskazaniu, dla którego wnioskodawcą jest Partner Bezpieczeństwa Lekowego, ustalona w decyzji, o której mowa w art. 11 ust. 1, odpowiada urzędowej cenie zbytu leku obowiązującej w dniu złożenia tego wniosku, chyba, że Wnioskodawca zaproponował we wniosku cenę zbytu netto pozwalającą na ustalenie urzędowej ceny zbytu na niższym poziomie.     3. Decyzja, o której mowa w ust. 1 i 2 wydawana jest na okres 5 lat.  4. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dotyczący leku dla którego dotychczas nie obowiązywała decyzja administracyjna o objęciu refundacją, złożony przez Partnera Bezpieczeństwa Lekowego, rozpatrywany jest w pierwszej kolejności. Wobec takiego wniosku nie ma zastosowania art. 31 ust. 1.  5. Produkt leczniczy Wnioskodawcy uznanego za Partnera Bezpieczeństwa Lekowego, dla którego żaden odpowiednik nie jest refundowany w danym wskazaniu, \\fma pierwszeństwo w obejmowaniu refundacją w danym wskazaniu.  6. Rozpatrując wniosek, o którym mowa w art. 24 ust. 1 pkt 1, złożony przez Partnera Bezpieczeństwa Lekowego dla leku, dla którego żaden odpowiednik nie jest refundowany w danym wskazaniu, minister właściwy do spraw zdrowia, Prezes Agencji oraz Komisja Ekonomiczna uwzględniają wysokość progu kosztu uzyskania dodatkowego roku życia skorygowanego o jakość, o którym mowa w art. 12 pkt 13, art. 19 ust. 2 pkt 7, art. 35 ust. 5 pkt 4, art. 35 ust. 6 pkt 3 lit. e., podwyższoną o 50 % w porównaniu do wartości określonej w art. 12 pkt 13. \\t\\fZob. uzasadnienie do postulatu zmiany art. 4a  \\fDodanie art. 12a i 12b stanowi jeden z elementów proponowanego mechanizmu Partnera Bezpieczeństwa Lekowego. Mechanizm wspierania produkcji w Polsce za pomocą instrumentów prawa refundacyjnego powinien odnosić się do wnioskodawcy, a nie tylko jego poszczególnych produktów, jak ma to miejsce w obecnym porządku prawnym.                                                 W zakresie ust. 8 – projekt rozporządzenia unijnego Critical Medicines Act uzasadnia zwolnienie z obowiązków wynikających z dyrektywy UWWTD, mając na uwadze, że nakładane przez nią wymagania stanowią istotne obciążenie administracyjne i operacyjne, mogące negatywnie wpływać na potencjał produkcyjny w zakresie wytwarzania leków o kluczowym znaczeniu dla zdrowia publicznego.\\t\\fUwaga niezasadna \\fZachęty przewidziane w ustawie refundacyjnej obejmują podmioty wytwarzające lek na terytorium Rzeczypospolitej Polskiej albo wytwarzające lek z wykorzystaniem substancji czynnej wytworzonej na terytorium Rzeczypospolitej Polskiej w Polsce. Dodatkowo dalej projekt rozszerza preferencje dla polskich producentów.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 9 lit. a dotyczący art. 13 ust. 2-2b ustawy refundacyjnej\\t2. W pierwszej decyzji administracyjnej o objęciu refundacją leku, obowiązującej po upływie okresu, o którym mowa w art. 11 ust. 3a, cena zbytu netto nie może być określona na poziomie wyższym niż 75% ceny zbytu netto ustalonej w pierwszym dniu obowiązywania pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, niezależnie od postaci farmaceutycznej. 2a. W przypadku gdy w pierwszej decyzji administracyjnej o objęciu refundacją leku, był zawarty instrument dzielenia ryzyka obniżający cenę efektywną, mechanizm, o którym mowa w ust. 2, stosuje się w odniesieniu do: 1) instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 5, obniżającego cenę efektywną na poziomie nie wyższym niż 75% ceny efektywnej określonej w pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, \\fniezależnie od postaci farmaceutycznej, albo 2) ceny zbytu netto oraz ceny efektywnej określonej w taki sposób, aby suma obniżek tych cen wynosiła łącznie co najmniej 25 punktów procentowych względem tych cen określonych w pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, niezależnie od postaci farmaceutycznej. 2b. W przypadku gdy w pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, niezależnie od postaci farmaceutycznej nie był zawarty instrument dzielenia ryzyka, mechanizm, o którym mowa w ust. 2, może być również zrealizowany w instrumencie dzielenia ryzyka przez obniżenie ceny efektywnej do poziomu 75% ceny efektywnej ustalonej w pierwszej decyzji administracyjnej.\\t\\fPodtrzymując postulaty zmian wskazane w uzasadnieniu do art. 11 ust. 3a UR, uważamy jednocześnie, że wprowadzenie tzw. kroczącej obniżki jest pozytywną zmianą. W tym zakresie kluczowym pozostaje modyfikacja definicji ceny efektywnej, tj. ograniczenie jej do ceny uwzględniającej tzw. „CHB” i „payback” (zgodnie z propozycją zmiany art. 2 pkt pkt 4a UR). Dzięki takiemu rozwiązaniu zarówno wnioskodawca, jak i Ministerstwo Zdrowia nie będą miały problemów z obliczeniem obniżek na żadnym etapie postępowania refundacyjnego. Jednocześnie koniecznym jest wprowadzenie drobnej modyfikacji, która wydaje się być spójna z założeniami Ministra Zdrowia. Chodzi o doprecyzowanie, że pierwsza decyzja \\frefundacyjna dotyczy prezentacji danego leku.  Dzięki temu pierwsza cena refundacyjna rzeczywiście będzie punktem odniesienia dla całej „grupy” leków jednego wnioskodawcy, a nie konkretnego „GTINu”. Unikniemy dzięki temu sytuacji, w której prezentacja X ze 100 tabletkami weszła do refundacji z ceną 100 zł, przy odnowieniu jej cena spadła o 20 zł (20%) i równolegle do niej do prezentacji weszła prezentacja Y z 200 tabletkami (w cenie 160 zł – cena propozycjonalna do prezentacji X). Dzięki temu – jeżeli w toku trwania wyłączności rynkowej nie było już więcej obniżek cen, nie dojdzie do sytuacji, w której cena prezentacji X będzie musiała zostać obniżona o 5% (zgodnie z mechanizmem kroczącej obniżki), cena prezentacji Y o 25% - pomimo, że te ceny cały czas referowały do siebie. Zasady liczenia propozycji i punktów odniesienia w tym zakresie zostały zaproponowane w ust. 2f i ust. 2g.\\t\\fUwaga niezasadna Na wstępie należy wskazać, iż proponowana zmiana, polegająca na odniesieniu mechanizmu obniżki do „prezentacji” leku oraz wskazaniu, że następuje ona „niezależnie od postaci farmaceutycznej”, jest niezgodna z ratio legis projektowanej nowelizacji. Intencją ustawodawcy nie było każdorazowe odnoszenie mechanizmu obniżki do pierwszej prezentacji leku, dla której wydano decyzję pozytywną w przedmiocie objęcia refundacją, ani przenoszenie w sposób dorozumiany skutku wcześniejszej obniżki na kolejne prezentacje wprowadzane do systemu refundacyjnego w odrębnych postępowaniach. Zadaniem podmiotu odpowiedzialnego jest kształtowanie własnej polityki cenowej i optymalne zarządzanie portfolio, w tym podejmowanie decyzji o momencie oraz zakresie składanych wniosków \\frefundacyjnych. Wprowadzanie nowych prezentacji leku innowacyjnego stanowi element planowanej strategii rynkowej i powinno uwzględniać obowiązujące mechanizmy regulacyjne, a powszechne normy prawne nie mogą służyć kompensowaniu decyzji biznesowych uczestników rynku. Co istotne, proponowana zmiana mogłaby też prowadzić do zaburzenia zasady równego traktowania wnioskodawców poprzez zróżnicowanie sytuacji podmiotów odpowiedzialnych w zależności od struktury portfela prezentacji danego leku. Należy ponadto zauważyć, iż jednym z okresów, o których mowa w art. 11 ust. 3a jest okres ochrony wynikającej z patentu. Patenty cechują się szerokim i zróżnicowanym charakterem, wielowarstwową konstrukcją oraz rozbudowaną strukturą ochrony o niejednolitych granicach; mogą one obejmować m.in. wskazania terapeutyczne, postać farmaceutyczną czy metody wytwarzania. Doświadczenia międzynarodowe wskazują, że ochrona patentowa w sektorze farmaceutycznym stanowi zagadnienie złożone i problematyczne, generujące liczne spory natury prawnej i merytorycznej. W związku z powyższym, referowanie mechanizmu obniżki do jednej prezentacji leku, zamiast zapewniać przejrzystość regulacyjną, może komplikować wykładnię przepisów, rodzić poważne wątpliwości interpretacyjne oraz zwiększać potencjalne ryzyko nadużyć. \\fWarto jednocześnie podkreślić, iż dotychczas, objęcie refundacją leku nawet na krótki okres przed upływem terminów wskazanych w art. 11 ust. 3a nie zwalniało z obowiązku dokonania ustawowej obniżki o 25%.Wprowadzając mechanizm tzw. obniżki kroczącej, ustawodawca w istotnym zakresie uwzględnił postulaty uczestników rynku. Proponowana obecnie modyfikacja ma charakter dalej idący i nie znajduje uzasadnienia, a jej przyjęcie naruszałoby wypracowany kompromis pomiędzy oczekiwaniami rynku, a możliwościami płatnika publicznego. Niezależnie od powyższego należy wskazać, że proponowana modyfikacja przepisu nie zapewnia realizacji deklarowanej przez podmiot intencji. Samo wprowadzenie do art. 1 pkt 9 lit. a pojęcia „prezentacji” nie przesądza wprost, że każda kolejna prezentacja, w odniesieniu do mechanizmu obniżki, miałaby referować do pierwszej prezentacji leku objętej refundacją. Natomiast w odniesieniu do zaproponowanego sformułowania „niezależnie od postaci farmaceutycznej” należy podkreślić, że jego wprowadzenie stałoby w sprzeczności z ustawową definicją leku, określoną w ustawie – Prawo farmaceutyczne, zgodnie z którą postać farmaceutyczna stanowi integralny element definiujący lek.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 9 lit. a dotyczący art. 13 ust. 2 ustawy \\frefundacyjnej\\t\\f2. W pierwszej decyzji administracyjnej o objęciu refundacją leku, obowiązującej po objęciu refundacją pierwszego odpowiednika w danym wskazaniu upływie okresu, o którym mowa w art. 11 ust. 3a, cena zbytu netto nie może być określona na \\fpoziomie wyższym niż 75% najwyższej ceny zbytu netto ustalonej w pierwszym dniu obowiązywania pierwszej decyzji administracyjnej o objęciu refundacją tego leku  przed objęciem refundacją pierwszego odpowiednika w danym wskazaniu. \\t\\fObniżka ceny dotychczasowego monopolisty jest rozwiązaniem zasadnym i zgodnym z interesem pacjentów. Powinna jednak następować równolegle z objęciem refundacją pierwszego odpowiednika, a zatem \\fwtedy kiedy pojawia się realna konkurencja rynkowa. W przeciwnym wypadku zamiast rozszerzenia dostępu pacjentów do leku (poprzez równoległe udostępnienie leku objętego dotąd wyłącznością oraz jego odpowiednika), może dojść do całkowitego pozbawienia pacjentów takiego dostępu. Wymuszenie obniżki ceny urzędowej przed faktycznym pojawieniem się konkurencyjnego leku może bowiem spowodować co najmniej przejściowe wycofanie się producenta jedynego leku refundowanego z refundacji. Postulowane rozwiązanie zapewnia większą przewidywalność dla wszystkich uczestników rynku oraz brak nieuzasadnionych merytorycznie obniżek cen leków referencyjnych w przypadku gdy na rynek faktycznie nie wchodzi konkurencja. Eliminuje także zagrożenie przerwania ciągłości dostępu do leków refundowanych dla pacjentów – w przeszłości było wiele przykładów, gdy mechanizm stosowania tego przepisu prowadził do wycofania na kilka miesięcy produktów bez odpowiedników z refundacji. W razie uwzględnienia propozycji zmiany do art. 13 ust. 2, należy dostosować brzmienie art. 11 ust. 3a w taki sposób, by obniżka cenowa dotychczasowego monopolisty i pierwszego odpowiednika następowała równocześnie. \\t\\fUwaga niezasadna W ramach bieżącej nowelizacji ustawodawca musiał ustalić, w związku z projektowanym progresywnym charakterem mechanizmu obniżki, jasno określony punkt w czasie, od którego \\fbędzie prowadzone sumowanie dokonywanych obniżek. Wprowadzenie jako punktu odniesienia warunków z pierwszej decyzji o objęciu refundacją miało za zadanie wyeliminowanie między innymi nieuczciwych praktyk podejmowanych przez niektórych wnioskodawców mających na celu uzyskanie decyzji o podwyższeniu ceny zbytu netto przed upływem okresu wyłączności tak aby w stosunku do podwyższonej ceny móc zastosować warunek ustawowej obniżki o 25%. Efektem takiego działania był brak oczekiwanego korzystnego wpływu na wydatki płatnika publicznego związany z upływem okresu wyłączności, co stanowiło sprzeczność z celem jaki przyświecał ustawodawcy przy tworzeniu tego przepisu (uzyskanie oszczędności). Aby zapewnić szerszy zakres realizacji w praktyce wymogu ustawowego w zakresie obniżki o 25% ustawodawca zaproponował w ramach poprzedniej nowelizacji ustawy o refundacji wypełnienie obowiązku – w zakresie ceny zbytu netto, ceny efektywnej lub w mechanizmie mieszanym, tak aby wnioskodawca mógł spełnić obowiązek ustawowy z uwzględnieniem strategii marketingowej korporacji i referencyjności zewnętrznej produktu, dostępnego na innych rynkach. Przyjęcie optyki proponowanej przez wnoszących uwagi, tj. przyjęcie jako punktu odniesienia najwyższej ceny z okresu przed upływem wyłączności, ponownie doprowadziło by do sytuacji, która była przyczyną do zmiany ustawy w rozważanym zakresie, a zatem \\fniezgodności z podstawowym założeniem jakie przyświecało sformułowania przepisu o konieczności dokonania obniżki o 25% (oszczędność dla płatnika). Dodatkowo należy zauważyć, iż ustawodawca zaproponował w ramach niniejszej zmiany przepisów tzw. kroczący mechanizm obniżki pozwalający według potrzeb i aktualnych możliwości wnioskodawcy rozłożyć obniżkę również w czasie trwania okresu wyłączności nie tylko jednorazowo - w związku z jego upływem. W opinii ustawodawcy zaproponowane rozwiązania w wystarczającym stopniu chroni interesy Wnioskodawcy przy jednoczesnym zagwarantowaniu, iż projektowany przepis nadal spełnia cel jaki przyświecał jego ustanowieniu.\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tArt. 1 ust. 9 lit a odnoszący się do art. 13 zmiana ust. 2\\t2. W pierwszej decyzji administracyjnej o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego wydanej po upływie okresu, o którym mowa w art. 11 ust. 3a, cena zbytu netto nie może być określona na poziomie wyższym niż 75 % ceny zbytu netto określonej w ostatniej decyzji administracyjnej o objęciu refundacją tego leku, środka lub wyrobu wydanej przed upływem tego okresu, albo nie może być określona na poziomie wyższym niż 95 % urzędowej ceny zbytu tego samego leku dopuszczonego do obrotu w procedurze innej niż import równoległy - w przypadku leku dopuszczonego do obrotu na podstawie na \\fpodstawie art. 4a ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. \\t\\t\\fZmiana ma na celu rozdzielenie w procedurze refundacyjnej produktów leczniczych, które stanowią odpowiedniki (i które, zgodnie z założeniami ustawy powinny kształtować ceny w danej grupie limitowej) od produktów z importu równoległego, które nie stanowią kolejnego odpowiednika, ale są tym samym lekiem. Zmiana zapewni realną możliwość sprowadzenia produktów z krajów UE oraz EOG do Polski.   Od Kancelaria Radcy Prawnego Tomasz Dauerman: \\fZmiana ma na celu rozdzielenie w procedurze refundacyjnej produktów leczniczych, które stanowią odpowiedniki (i które, zgodnie z założeniami ustawy powinny kształtować ceny w danej grupie limitowej) od produktów z importu równoległego, które nie stanowią kolejnego odpowiednika, ale są tym samym lekiem. Zmiana zapewni realną możliwość sprowadzenia produktów z krajów UE oraz EOG do Polski.\\t\\fUwaga niezasadna  Niewskazane jest rozszerzanie regulacji właściwych dla rejestracji leków w trybie importu równoległego na zasady funkcjonowania systemu refundacyjnego, gdyż prowadzi to do nieuzasadnionego zróżnicowania sytuacji prawnej produktów równoważnych terapeutycznie. W zaproponowanym brzmieniu skutkuje to dyskryminacją produktów leczniczych generycznych, które są zobligowane do spełnienia pełnego katalogu wymogów ustawowych przewidzianych dla refundacji.   Należy podkreślić, że mechanizmy przewidziane w ustawie o refundacji służą kształtowaniu jak najkorzystniejszych cen refundowanych produktów leczniczych oraz zapewnieniu \\fich dostępności dla świadczeniobiorców, przy zachowaniu zasady równego traktowania wszystkich podmiotów niezależnie od ich statusu prawnego, formy prowadzenia działalności czy trybu dopuszczenia produktu do obrotu. \\n\\tIzba Gospodarcza „FARMACJA POLSKA”\\tArt. 1 ust. 9 lit a odnoszący się do art. 13 zmiana ust. 2\\tPo pierwsze, punktem odniesienia do ustalenia właściwej ceny produktu po obowiązkowej obniżce powinna być najwyższa jego dotychczasowa cena, a nie cena z pierwszej decyzji o refundacji. W przypadku bowiem, gdy po wydaniu pierwszej decyzji o refundacji cena produktu ulegała podwyższeniu, wymagana obniżka ceny powinna być realizowana od ceny podwyższonej, nie wyjściowej. W przeciwnym razie obniżka będzie w rzeczywistości przekraczać wymagane 25%. Po drugie, prosimy o wykreślenie z projektu art. 13 ust. 2d ustawy, w świetle którego wprowadzone przez DNUR mechanizmy elastycznego realizowania obniżki (również w cenie efektywnej lub częściowo efektywnej i częściowo nominalnej) mają być wyłączone w odniesieniu do leków refundowanych aptecznie.\\tArt. 13 ust. 2 – 2b oraz 2d – krocząca obniżka ceny leku po wygaśnięciu wyłączności rynkowej, wyłączenie możliwości obniżenia ceny efektywnej dla leku refundowanego aptecznie  W pierwszym rzędzie chcielibyśmy podkreślić, że bardzo doceniamy kolejną zmianę w treści art. 13 ustawy o refundacji, która ma jeszcze bardziej (w ślad po zmianach wprowadzonych przez DNUR) ułatwić wnioskodawcom stosowanie się do wymogu obniżenia ceny refundowanego leku po wygaśnięciu wyłączności rynkowej.  Jako Izba Gospodarcza „FARMACJA POLSKA” od wielu lat informujemy Państwa o tym, że obowiązek obniżania cen leku refundowanego przy wygaśnięciu wyłączności rynkowej jest niezwykle trudny dla wnioskodawców, a nawet może być przyczyną wycofania \\fleku \\nz refundacji.  Dlatego zaproponowane przez Państwa rozwiązanie, sprowadzające się do możliwości zaliczenia na poczet obowiązkowej obniżki już dokonanych w toku refundacji produktu obniżek, jest bardzo korzystne dla wnioskodawców i z pewnością ułatwi firmom stosowanie się do wymogu obniżenia ceny. Co więcej, jesteśmy zdania, że jest to zmiana korzystna również dla płatnika, ponieważ zachęci wnioskodawców do obniżania ceny jeszcze przed wygaśnięciem wyłączności rynkowej, podczas, gdy obecnie wielu wnioskodawców woli utrzymywać wysokie ceny swoich produktów, po to, by mieć potem z czego zejść.  Niemniej, dostrzegamy potrzebę wprowadzenia jeszcze drobnych modyfikacji do zaproponowanych przez Państwa zmian w artykule 13.  Po pierwsze, punktem odniesienia do ustalenia właściwej ceny produktu po obowiązkowej obniżce powinna być najwyższa jego dotychczasowa cena, a nie cena z pierwszej decyzji o refundacji. W przypadku bowiem, gdy po wydaniu pierwszej decyzji o refundacji cena produktu ulegała podwyższeniu, wymagana obniżka ceny powinna być realizowana od ceny podwyższonej, nie wyjściowej. W przeciwnym razie obniżka \\fbędzie w rzeczywistości przekraczać wymagane 25%. Po drugie, prosimy o wykreślenie z projektu art. 13 ust. 2d ustawy, w świetle którego wprowadzone przez DNUR mechanizmy elastycznego realizowania obniżki (również w cenie efektywnej lub częściowo efektywnej i częściowo nominalnej) mają być wyłączone w odniesieniu do leków refundowanych aptecznie.  Nie znajdujemy zasadnych argumentów, które by przemawiały za takim rozwiązaniem, poza tym, że impakt obniżek może być większy zwłaszcza w przypadku leków umieszczonych na wykazie „S”. Niemniej, należy zwrócić uwagę na fakt, że od 1 listopada 2023 roku (data wejścia DNUR w życie) były już wydawane decyzje o refundacji leków w aptekach, w których ustalano warunki cenowe z uwzględnieniem dopuszczalności obniżenia w przyszłości ceny efektywnej, co pozwalało wnioskodawcom na zaakceptowanie niższych cen zbytu netto. Teraz tacy wnioskodawcy znajdą się w gorszej sytuacji niż ci, których leki są refundowane w innych kategoriach dostępności refundacyjnej. \\t\\fUwaga niezasadna Wprowadzenie zapisu, który wyklucza możliwość zastosowania mechanizmu hybrydowego lub obniżenia wyłącznie ceny efektywnej w instrumencie podziału ryzyka w stosunku do leków dostępnych w aptece na receptę związane jest z faktem trudności jednoznacznego zdefiniowania ceny efektywnej leku w tym kanale dostępności refundacyjnej aby uzyskiwany efekt był jednakowy, powtarzalny dla wszystkich leków dostępnych w tym kanale oraz był zgodny z założeniami jakie przyświecały ustawodawcy w związku z  tworzeniem tego przepisu. Na cenę efektywną leku refundowanego na podstawie recepty w aptece mają bowiem wpływ nie tylko warunki ustalone dla niego ale i dla leku stanowiącego podstawę limitu w grupie, które mogą być zmienne w czasie. Aktualne brzmienie przepisu prowadziło do różnych jego interpretacji po stronie wnioskodawców, którzy szacowali koszt efektywny nie z perspektywy płatnika a swojej wskazując na wymagany procent \\fpomniejszenia zysku przedsiębiorcy (CZN pomniejszona o 25%), który jednak nie był tożsamy z perspektywy płatnika (koszt refundacji pomniejszony o 25%).   Doświadczenia Organu z tym zakresie wiązały się z obserwacją działań skutkujących marginalizacją konsekwencji związanych z obniżką poprzez zastosowanie rozwiązań, które nie realizowały podstawowego celu przyświecającego przepisowi, czyli wygenerowania oszczędności dla płatnika publicznego wynikających z faktycznego obniżenia kosztu efektywnego refundacji produktu lub sytuacje, w których faktyczna skala takiej obniżki była znikoma. I tak za przykład można przyjąć sytuację, w której wnioskodawca wyraża chęć realizacji obowiązku ustawowego poprzez pogłębienie ustalonej w poprzedniej decyzji kwoty zwrotu od opakowaniu produktu. Przy niskiej faktycznej wartości obowiązującego zwrotu np. 3 zł oraz wysokiej cenie zbytu netto pogłębienie pay-back o 0,75 zł, które w opinii wnioskodawcy literalnie spełnia warunek ustawowy, nie przekłada się na korzyści z tej obniżki po stronie płatnika publicznego. Koszt efektywny w opinii wnioskodawcy zmniejsza się o 25% jednak wpływ takiej obniżki na faktyczny koszt płatnika (rozumiany przez Organ jako koszt refundacji ponoszony przez płatnika z uwzględnieniem zwrotu) jest znikomy przy utrzymaniu niezmienionej ceny zbytu netto i braku wpływu na wartość podstawy limitu w grupie. Sytuacja, w której obniżka dotyczy leku będącego podstawą limitu jest \\frealizowana z zupełnie innym skutkiem dla jego wnioskodawcy i płatnika publicznego oraz wnioskodawcy, dla leku który nie stanowi podstawy limitu w tej grupie limitowej. Analiza różnych przykładów w odniesieniu do leków refundowanych w tej kategorii dostępności doprowadziła Organ do wniosku, iż jedynie referowanie do ceny zbytu netto daje warunki sprawiedliwe i powtarzalne oraz umożliwia zachowanie pierwotnego celu rozważanego przepisu.\\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 ust. 9 lit a i b odnoszący się do art. 13 \\fzmiana ust. 2-2c\\t\\fW art. 13 ust. 2-2c proponujemy nadanie następującego brzmienia: \\f„2. W pierwszej decyzji administracyjnej o objęciu refundacją leku, obowiązującej po upływie okresu, o którym mowa w art. 11 ust. 3a, cena zbytu netto nie może być określona na poziomie wyższym niż 75% ceny zbytu netto ustalonej w pierwszym dniu obowiązywania pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, niezależnie od postaci farmaceutycznej. 2a. W przypadku gdy w pierwszej decyzji administracyjnej o objęciu refundacją leku, był zawarty instrument dzielenia ryzyka obniżający pozwalający na wyliczenie cenyę efektywneją zgodnie z art. 2 pkt 4a, mechanizm, o którym mowa w ust. 2, stosuje się w odniesieniu do: 1) instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 5, obniżającego cenyę efektywneją w taki sposób, że nie może być ona określona na poziomie nie wyższym niż 75 % ceny efektywnej określonej w pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, niezależnie od postaci farmaceutycznej albo  2) ceny zbytu netto oraz ceny efektywnej określonej w taki sposób, aby suma obniżek tych cen wynosiła łącznie co najmniej 25 punktów procentowych względem tych cen określonych w pierwszej decyzji administracyjnej o objęciu refundacją \\fprezentacji tego leku, niezależnie od postaci farmaceutycznej. 2b. W przypadku gdy w pierwszej decyzji administracyjnej o objęciu refundacją prezentacji tego leku, niezależnie od postaci farmaceutycznej, nie był zawarty instrument dzielenia ryzyka, mechanizm, o którym mowa w ust. 2, może być również zrealizowany poprzez zawarcie w instrumentucie dzielenia ryzyka przez obniżającegoenie pozwalającego na wyliczenie ceny efektywnej, która nie może być określona na do poziomieu wyższym niż 75 % ceny zbytu netto efektywnej ustalonej w pierwszej decyzji administracyjnej o objęciu refundacją tego leku.\\t\\fZmiany zaproponowane do art. 13 ust. 2-2c mają na celu doprecyzowanie brzmienia przepisów w związku z \\fwprowadzeniem definicji ceny efektywnej, jak również uregulowanie, że obniżka powinna być dokonywana względem poszczególnych prezentacji leku i niezależnie od postaci farmaceutycznej. Ma to na celu zaadresowanie sytuacji, w których w toku refundacyjnego życia produktu zmieniła się formulacja danej prezentacji (np. dokonano zmiany kapsułek na tabletki).  Jednocześnie w pkt. 10 niniejszej tabeli przedstawiona została propozycja uzupełniająca zmiany zaproponowane w art. 13 ust. 2-2c, która reguluje kwestię proporcjonalnego wyliczenia cen dla poszczególnych prezentacji leku względem ceny obowiązującej w pierwszej decyzji.   \\t\\fUwaga niezasadna Proponowana w ramach nowelizacja zmiana zapisu stanowi znaczące złagodzenie obecnie obowiązujących \\fzobowiązań uwzględnionych w art. 13 ustawy o refundacji, bowiem wielokrotnie w toku renegocjacji terapii innowacyjnych dochodzi do redukcji warunków cenowych na poziomie negocjacji z Komisją Ekonomiczną lub Ministrem Zdrowia. Obecnie obniżenie ceny we wcześniejszych postępowaniach pozostaje bez znaczenia dla tzw. ustawowej obniżki -25% z powodu upływu wyłączności rynkowej lub (obecnie) ochrony wynikającej z patentu. Zważywszy na prawie każdorazowe zmiany dotychczasowych warunków finansowania podczas procesów kontynuacyjnych, proponowane w nowelizacji zapisu tzw. kroczącej obniżki będą ostatecznie stanowiły istotne ułatwienie spełnienia ustawowego warunku -25% w stosunku do terapii innowacyjnych, tj. on-patent.  Proponowana w ramach niniejszej uwagi zmiana prowadziłaby do zmiany referencji, zmiany punktu odniesienia służącego do skalkulowania kroczącej obniżki na pierwszą decyzję refundacyjną prezentacji tego leku, niezależnie od postaci farmaceutycznej. Taka propozycja wynika prawdopodobnie z faktu, że zdarzają się sytuację w których nowa prezentacja leku innowacyjnego zawierająca odmienną dawkę, ilość leku, nr GTIN zostaje włączona na wykaz na przykład po kilku latach refundowania innej prezentacji tego leku, dla którego miały już miejsce procesy negocjacyjne. Niemniej jednak, dziś, regulacja określona art. 13 nie przewiduje takiego rozwiązania, wskazując jako punkt odniesienia warunki z ostatniej decyzji \\frefundacyjnej dla każdej prezentacji z osoba. Ponadto, uniezależnienie od postaci farmaceutycznej tym bardziej nie może zostać uznane za zasadne, bowiem zgodnie z zapisami ustawy o refundacji, leki różniące się istotnie postacią farmaceutyczną nie mogą być traktowane jednakowo, a co za tym idzie, są traktowane jak odrębne/indywidualne terapie co w przypadku wnioskowania w danym wskazaniu sprowadza się do przedstawiania analiz HTA oraz przejścia oceny AOTMiT dla tego samego leku, w tym samym wskazaniu zarówno dla postaci doustnych tabletek i doustnego roztworu. W związku z tym, na poziomie obowiązku wynikającego z art. 13 ustawy o refundacji, nie jest możliwe jednakowe traktowanie leków różniących się postacią farmaceutyczną czy drogą podania – co również uzależnione jest od postaci farmaceutycznej. Co więcej, w systemie refundacyjnym mają miejsce sytuacje, w których ten sam produkt w różnych prezentacjach różni się zakresem wskazań refundacyjnych – dla przykładu zgodnie z Obwieszczenie Ministra Zdrowia z dnia 18 grudnia 2024 r. w sprawie wykazu refundowanych leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych na 1 stycznia 2025 r. produkt Signifor w prezentacjach 20/30/40/60mg refundowany był w zależności od prezentacji w programie B.99 albo B.118 albo B.99 i B.118. Mając na względzie powyższe brak jest uzasadnienia do proponowanej zmiany.\\n\\tPracodawcy RP\\tArt. 1 ust. 9 lit a i b odnoszący się do art. 13 zmiana ust. 2-2d\\tW odniesieniu do regulacji dotyczących tzw. obowiązkowej obniżki ceny po wygaśnięciu okresu wyłączności rynkowej proponujemy:  Rezygnację z tej regulacji  albo, alternatywnie: Wprowadzenie konieczności obowiązkowego obniżenia ceny w momencie pojawienia się pierwszego odpowiednika. Jednocześnie postulujemy, aby każde rozwiązanie w zakresie dokonywania obniżki ceny leku przewidywało jednakowe traktowanie leków, niezależnie od kategorii dostępności refundacyjnej. Zasadne jest również doprecyzowanie przepisów tak, aby uwzględniały leki, dla których MZ wydał pozytywną decyzję o podwyższeniu ceny zbytu netto. W przypadku tych produktów, w terminie obowiązkowej obniżki ceny, punktem referencyjnym powinny być warunki ustalone w decyzji podwyżkowej, nie w pierwszej decyzji o objęciu refundacją.\\tPomimo znanego Pracodawcom RP stanowiska MZ w tej kwestii mimo wszystko ponawiamy apel o likwidację przepisu wymagającego dokonanie obniżki ceny po wygaśnięciu okresu wyłączności rynkowej. Uważamy, że kwestia obniżki ceny powinna być powiązana z pojawieniem się konkurencji generycznej. Obecny mechanizm w dalszym ciągu: zniechęca do wprowadzania innowacyjnych terapii na polski rynek, osłabia konkurencyjność Polski względem innych krajów UE, jak również nie uwzględnia realiów rynkowych i kosztów produkcji leków. Powiązanie obniżki ceny leku oryginalnego z pojawieniem się leku generycznego lub biopodobnego jest zasadne z perspektywy pacjenta – w ten sposób ograniczane jest ryzyko czasowej bądź trwałej niedostępności leku w refundacji ze względu na międzynarodową referencyjność cenową. Warto przy tym podkreślić, że Polska jest jedynym krajem, w którym obowiązek obniżenia ceny leku oryginalnego zachodzi w terminie utraty wyłączności rynkowej. Warto podkreślić w tym kontekście, że propozycja zawarta w Projekcie nie tylko usuwa odniesienie do „ochrony wynikającej z patentu” ale dodatkowo referuje do „najwcześniejszego terminu wygaśnięcia okresu wyłączności \\frynkowej (…) niezależnie od wskazania”, w konsekwencji czyniąc ten przepis bardziej restrykcyjnym od obowiązującego do dnia wejścia w życie DNUR. Decyzje refundacyjne w zakresie cen powinny być zindywidualizowane, a nie oparte na sztywnych regułach. Nieuzasadnione wydaje się proponowane przez MZ usunięcie możliwości realizowania ustawowej obniżki ceny leków aptecznych w odniesieniu do ceny efektywnej (w pełni lub w rozwiązaniu łączącym obniżkę ceny zbytu netto z obniżką ceny efektywnej). Pozostawienie w UoR możliwości elastycznego podejścia MZ do każdego z produktów w trakcie negocjacji cenowych będzie korzystne dla wszystkich stron: Pacjenci unikną sytuacji, w której lek tymczasowo lub trwale utraci refundację – konieczność obniżenia ceny zbytu netto do poziomu nie wyższego niż 75% referencyjnej ceny zbytu netto jest często niemożliwa do zrealizowania przez podmiot odpowiedzialny biorąc pod uwagę międzynarodową referencyjność cenową i wspomniany powyżej fakt, że obniżenie ceny zachodzi w \\fPolsce znacznie wcześniej niż na innych rynkach. MZ poprzez negocjacje cenowe ma realny wpływ na osiągnięcie warunków cenowych korzystnych zarówno dla pacjenta (wynikających z obniżenia CZN) lub dla płatnika (wynikających z obniżenia CZN dla leków bezpłatnych oraz obniżenia ceny efektywnej – środki te wracają do budżetu NFZ). Podmiotu odpowiedzialnego – w przypadku, gdy międzynarodowa referencyjność cenowa uniemożliwia obniżenie CZN do poziomu wskazanego w UoR, możliwość zastosowania obniżenia ceny efektywnej lub rozwiązania hybrydowego daje możliwość znalezienia rozwiązania, które przyniesie oszczędności dla systemu ochrony zdrowia bez negatywnego wpływu na dostępność do terapii dla pacjenta. Należy również zauważyć, że obowiązkowa obniżka ceny zbytu netto nie zawsze będzie związana z obniżeniem kosztu NFZ – np. w przypadku leków, które nie są dostępne dla pacjentów na liście „S”, „Dz” lub „ciąża”, a ich cena zbytu \\fnetto po obniżce będzie wyższa niż cena podstawy limitu w grupie (pomimo obniżenia ceny zbytu netto, wysokość limitu finansowania nie ulegnie obniżeniu). Wymóg obniżenia ceny zbytu netto może prowadzić również do sytuacji, w której lek po obniżeniu ceny będzie wyznaczał podstawę limitu w grupie. O ile koszt z perspektywy NFZ ulegnie obniżeniu, to jednak koszt z perspektywy pacjenta stosującego pozostałe leki w grupie może istotnie wzrosnąć.  Aby uniknąć przytoczonych powyżej przykładów o negatywnym działaniu dla pacjenta lub płatnika warto pozostawić w UoR przepisy umożliwiające MZ elastyczne podejście do każdego leku. Należy również podkreślić, że proponowane przez MZ usunięcie przepisów wprowadzonych w ramach DNUR wyłącznie w odniesieniu do leków aptecznych i uzasadnienie takiego rozwiązania brakiem obniżenia kosztu dla płatnika jest nieuzasadnione. W przypadku leków stosowanych w programach lekowych pozostaje możliwość obniżenia wyłącznie ceny zbytu netto, która często nie ma żadnego wpływu na koszt ponoszony przez NFZ (np. lek z ceną zbytu netto w wysokości 1000 zł i maksymalną ceną hurtową brutto na poziomie 700 zł może obniżyć cenę zbytu netto do poziomu 750 zł i tym \\fsamym spełnić warunek ustawowy bez jakiegokolwiek wpływu na wydatki NFZ. Tym samym nierówne traktowanie leków, nie uwzględniające specyfiki kategorii dostępności i mechanizmów wpływających na koszt płatnika i pacjenta jest bezproduktywne i niepożądane. Zmiana tych przepisów będzie prowadziła do występowania sytuacji niekorzystnych z perspektywy pacjentów, które to zostały zaadresowane przez wprowadzenie tych przepisów w ramach DNUR. W przypadku leków, dla których w okresie refundacji nastąpiło podwyższenie ceny zbytu zasadne jest referowanie w terminie obowiązkowej obniżki ceny do warunków ustalonych w tej decyzji. W przeciwnym razie, biorąc pod uwagę proponowane przez MZ zmiany w przepisach (brak możliwości obniżenia ceny efektywnej czy zastosowania rozwiązania hybrydowego dla leków aptecznych), wnioskodawca będzie zmuszony obniżyć CZN o więcej niż 25%, co stoi w sprzeczności z wydaniem przez Ministra Zdrowia pozytywnej decyzji o podwyższeniu CZN i uznaniu argumentów wskazanych przez Wnioskodawcę w kontekście zasadności wprowadzenia tej podwyżki.\\t\\fUwaga niezasadna Jak sam autor przedmiotowej uwagi wskazał, znane jest mu stanowisko MZ w tej kwestii. W sprzeczności pozostaje również liczba nowych, obejmowanych refundacją terapii z stwierdzeniem co do zniechęcania producentów leków do wprowadzania innowacyjnych terapii na polski rynek przez wzgląd na dzisiejszy mechanizm zawarty w art. 13. Warto zaznaczyć, że regulacją zawartą w art. 13 referującą do wyłączności rynkowej lub (jak to ma miejsce obecnie) ochrony wynikającej z patentu, stanowi jedyny mechanizm dający gwarancje potencjalnej redukcji ceny efektywnej dla płatnika publicznego w okresie wyłącznego funkcjonowania na rynku leku referencyjnego. W Polsce nie obowiązują ustawowe mechanizmy redukujące cenę leków innowacyjnych, określające maksymalne wydatki na leki innowacyjne, obligatoryjne rabaty w momencie wejścia do refundacji leku innowacyjnego, zwroty części refundacji po przekroczeniu określonych progów w stosunku do danego leku lub całego portfolio danego podmiotu odpowiedzialnego. Tego typu, obligatoryjne zobowiązania na poziomie ustawowym nie funkcjonują w stosunku do innowacyjnych terapii, które co do zasady są kosztowne z perspektywy płatnika. Co więcej, dzisiejsze regulacje nie obligują również podmiotu do obniżenia warunków cenowych w momencie generyzacji produktu. Tym samym, mając na względzie, że w innych krajach obowiązują zróżnicowane mechanizmy redukujące ceny leków \\finnowacyjnych, nie ma możliwości aby w polskim systemie refundacyjnym wykluczyć jedyny taki mechanizm. Co więcej, ostatnia nowelizacja rozszerzyła wachlarz mechanizmów za pomocą których możliwe jest wywiązania się z przedmiotowego zobowiązania.   Odnosząc się do kwestii wyłączenia z rozwiązania hybrydowego produktów finansowanych w ramach kategorii aptecznej, wprowadzenie jest odpowiedzią ustawodawcy na nieprawidłowo funkcjonujący mechanizm, który został zaimplementowany w ramach ostatniej nowelizacji, a ponad dwuletnia praktyka wykazała jego dysfunkcjonalność. W konsekwencji w ramach nowelizacji ustawy o refundacji proponuje się przywrócenie poprzedniej regulacji w przypadku leków aptecznych, tzn. nie jest to nowy mechanizm, bowiem obowiązywał od początku funkcjonowania ustawy o refundacji do listopada 2023 r. Przedmiotowa kwestia została dokładnie wyjaśniona w uzasadnieniu: „(…)w przypadku produktów wydawanych w aptece na receptę cena zbytu netto w sposób bezpośredni koreluje z ceną efektywną, rozumianą jako ostateczny koszt refundacji dla płatnika. Jednocześnie, możliwa jest redukcja ceny efektywnej produkty wydawanego w aptece na przykład przez zastosowanie tzw. payback’ów – czyli ustalonej kwoty zwrotu do NFZ, za każde zrefundowane opakowanie. Współistnienie w decyzji refundacyjnej produktu aptecznego \\finstrumentu dzielenia ryzyka w postaci payback’u powoduje, że przy obecnej konstrukcji przepisu spełnienie ustawowych wymagań jest możliwe za pomocą obniżki ceny zbytu netto przykładowo o kilkanaście procent oraz odpowiednie zmniejszenie – pogorszenie instrumentu dzielenia ryzyka - dotychczasowego zwrotu do NFZ. Sumarycznie obniżka ceny zbytu netto i ceny efektywnej z perspektywy płatnika wyniesie 25 punktów procentowych, przy nieznacznej redukcji kosztów refundacji”. Wprowadzając obowiązującą dziś regulację umożliwiającą hybrydowe rozwiązanie również w stosunku do leków aptecznych, intencją ustawodawcy nie było zminimalizowanie potencjalnych oszczędności dla płatnika publicznego, a rzeczywistość i mające miejsce od dwóch lat sytuacje, wskazują właśnie takie konsekwencje w przypadku realizacji ustawowej obniżki w sposób hybrydowy w aptece.  Ponadto, trudno zgodzić się z twierdzeniem „(…) W przypadku leków stosowanych w programach lekowych pozostaje możliwość obniżenia wyłącznie ceny zbytu netto, która często nie ma żadnego wpływu na koszt ponoszony przez NFZ (np. lek z ceną zbytu netto w wysokości 1000 zł i maksymalną ceną hurtową brutto na poziomie 700 zł może obniżyć cenę zbytu netto do poziomu 750 zł i tym samym spełnić warunek ustawowy bez jakiegokolwiek wpływu na wydatki NFZ.”, bowiem w przypadku gdy w ostatniej decyzji obowiązywał instrument dzielenia ryzyka, regulacja \\fokreślona w art. 13 ust. 2 aktualnej ustawy o refundacji nie obowiązuje, bowiem w tych przypadkach zobowiązanie ustawowej redukcji ceny reguluje art. 13 ust. 2a, który nie przewiduje wyłącznej redukcji ceny zbytu netto o 25%.\\n\\tNovo Nordisk Pharma Sp. z o.o.\\tArt. 1 pkt 9 lit. b projektu w zakresie dodawanego art. 13 ust. 2d\\t\\tSkreślenie proponowanego brzmienia art. 13 ust. 2d i zastąpienie go następującym: \\tJeśli w okresie od wydania pierwszej decyzji administracyjnej o objęciu refundacją do zaistnienia okoliczności, o których mowa w art. 11 ust. 3a, dla leku wydana została co najmniej jedna decyzja, o której mowa w art. 24 ust. 1 pkt 2, punktem odniesienia do zastosowania obniżki, o której mowa w art. 13 ust. 2-2b jest najwyższa cena zbytu netto obowiązująca w tym okresie.\\tUzasadnienie dot. skreślenia proponowanego brzmienia art. 13 ust. 2d W dodanym do art. 13 ust. 2d zawarte zostało wyłączenie z możliwości zastosowania ustawowej obniżki ceny w terminie utraty wyłączności rynkowej z wykorzystaniem instrumentów dzielenia ryzyka w odniesieniu do leków dostępnych w aptece na receptę. Zgodnie z przedstawionym przez Ministerstwo Zdrowia (MZ) uzasadnieniem, jest to przede wszystkim związane z „dysfunkcjonalnym” mechanizmem hybrydowym. Proponowane przez MZ rozwiązanie trudności zidentyfikowanych w jednostkowych procesach refundacyjnych prowadzonych w okresie od obowiązywania przepisów DNUR wydaje się nieadekwatne. Ograniczenie możliwości zrealizowania ustawowej obniżki ceny w terminie wygaśnięcia wyłączności rynkowej dla leków aptecznych z wykorzystaniem różnych mechanizmów cenowych może prowadzić do czasowego lub trwałego ograniczenia dostępności leku dla pacjenta, przy braku dostępności alternatywnej terapii. Może mieć również negatywny wpływ na koszt terapii dla pacjentów stosujących inne leki. \\fNieuzasadnione wydaje się zatem podejście MZ, w którym dyskryminowane są leki apteczne. Trudności wynikające ze stosowania rozwiązania hybrydowego w równym stopniu odnoszą się bowiem do leków aptecznych, jak i szpitalnych, aczkolwiek ich specyfika jest zależna od kategorii dostępności refundacyjnej. Warto przy tym zauważyć, że zastosowanie rozwiązania hybrydowego dla leków szpitalnych również nie zawsze będzie prowadziło do oczekiwanych przez MZ oszczędności. Przykładowo, obniżenie CZN o 24% i obniżenie maksymalnej CHB o 1% spełni wymogi ustawowe, ale realnie przyniesie jedynie ok. 1% oszczędności dla systemu ochrony zdrowia (np. początkowa CZN = 100 zł i max CHB = 87 zł, po obniżce CZN = 76 zł, max CHB = 86 zł). Mimo to Organ nie zdecydował się na wycofanie takiego rozwiązania z dostępnych mechanizmów, pozostawiając możliwość indywidualnego i elastycznego podejścia do każdego leku. Jest to podejście zasadne i powinno w równym stopniu mieć możliwość zastosowania do leków aptecznych. Zastosowanie podobnych obniżek do leków aptecznych, tj. 24% redukcji CZN oraz 1% obniżenia kosztu NFZ przyniesie \\foszczędności większe niż analogiczny mechanizm dla leków szpitalnych. Jak podkreśliło MZ w uzasadnieniu do SZNUR, obniżka CZN w przypadku leków wydawanych w aptece przekłada się na wysokość ceny detalicznej i wysokość dopłaty pacjenta. Tym samym finalnym beneficjentem obniżki hybrydowej w odniesieniu do leków aptecznych jest zarówno pacjent, jak i płatnik publiczny. Nie bez znaczenia pozostaje to, że uzgodnienie finalnych warunków cenowych jest przedmiotem negocjacji, a każda propozycja podmiotu odpowiedzialnego musi finalnie zostać zaakceptowana przez Ministra Zdrowia. Trudno zatem wyobrazić sobie sytuację, w której Minister wyraża zgodę na warunki niekorzystne dla systemu ochrony zdrowia. Należy również zwrócić uwagę, że wprowadzenie sztywnej zasady dotyczącej możliwości obniżki wyłącznie CZN dla leków aptecznych może prowadzić nie tylko do czasowego lub stałego wycofania produktu z refundacji, ale może mieć również negatywny wpływ na warunki cenowe innych produktów znajdujących się w tej samej grupie limitowej. Przepisy ustawy refundacyjnej definiują mechanizmy kształtujące wysokość limitu finansowania leków i tym samym \\f(w przypadku leków aptecznych) również wysokości dopłaty pacjenta. Mając powyższe na uwadze, obniżenie CZN jednego leku może mieć istotny wpływ na wysokość limitu finansowania i kosztu dla pacjenta również w odniesieniu do innych leków refundowanych w ramach tej samej grupy limitowej. Proponowana przez MZ zmiana przepisów może zatem prowadzić do częstszego występowania sytuacji podobnych jak miało to miejsce na początku 2023 r. w grupie 14.3, Hormony trzustki - długodziałające analogi insulin: W związku z utratą wyłączności rynkowej jednego z produktów refundowanych w grupie limitowej 14.3 w styczniu 2023 r., cena zbytu netto tego leku obniżona została zgodnie z wymogami ustawowymi o 25%. W konsekwencji wysokość dopłaty pacjenta do tego leku oraz koszt NFZ uległ obniżeniu. W kolejnym Obwieszczeniu MZ (obowiązującym od 1 marca 2023 r.) lek ten uzyskał status leku wyznaczającego podstawę limitu w grupie. W konsekwencji wysokość dopłaty pacjenta do tego leku uległa nieznacznemu obniżeniu, ale jednocześnie istotnie wzrosła wysokość dopłaty pacjenta do wszystkich pozostałych produktów \\frefundowanych w tej grupie limitowej.  W efekcie zdecydowana większość pacjentów (ok. 80% wg danych NFZ za marzec 2023 r.) stosujących insuliny długodziałające odczuła znaczny wzrost kosztu terapii, który wyniósł od 13% do 30% za opakowanie.  Wydaje się zatem, że na kwestię obniżki ceny w terminie utraty wyłączności rynkowej należy patrzeć szerzej, tj. z perspektywy budżetu na refundację czy też budżetu NFZ ogółem.  Możliwość stosowania instrumentów dzielenia ryzyka prowadzi do znacznych oszczędności NFZ. Zgodnie z informacjami przedstawionymi w rocznym sprawozdaniu z wykonania planu finansowego NFZ za 2024 r., przychody z tytułu kwot zwrotu części uzyskanej refundacji z tytułu instrumentów dzielenia ryzyka (art. 11 ust. 5 pkt. 4 ustawy o refundacji) wyniosły 1,7 mld zł. Są to środki, które wracają do budżetu NFZ i mogą zostać wykorzystane na zapewnienie dostępu do świadczeń dla pacjentów.  Obowiązujące przepisy (wprowadzone w DNUR) dawały MZ możliwość elastycznego i indywidualnego podejścia do każdego leku tak, aby finalnie znaleźć rozwiązanie korzystne dla każdej ze \\fstron, tj. pacjenta, płatnika i podmiotu odpowiedzialnego. Obowiązujące przepisy ograniczyły ryzyko konieczności wycofania leku z refundacji ze względu na międzynarodową referencyjność cenową. Jak MZ zauważyło w uzasadnieniu do SZNUR – Polska jest jedynym krajem, w którym obowiązują przepisy obligujące podmiot odpowiedzialny do obniżki ceny w terminie wygaśnięcia wyłączności rynkowej. W pozostałych krajach obniżka ta jest uzależniona od dostępności leku generycznego bądź np. uzyskania przez niego odpowiedniego udziału w rynku, zabezpieczającego potrzeby pacjenta. Słuszne wydaje się zatem skreślenie proponowanej przez MZ treści art. 13 ust. 2d i pozostawienie w ustawie refundacyjnej przepisów umożliwiających elastyczne i indywidualne podejście do każdego leku, co w efekcie pozwoli na wypracowanie w ramach negocjacji cenowych warunków przynoszących oszczędności dla systemu ochrony zdrowia bez negatywnego wpływu na dostępność i koszty terapii dla pacjentów w szerszej perspektywie. Uzasadnienie dot. propozycji nowego brzmienia art. 13 ust. 2d (odniesienie do \\fleków, dla których wydana została decyzja o podwyższeniu CZN) Proponowane przez MZ przepisy dotyczące odniesienia się w art. 13 ust. 2-2b do warunków obowiązujących w pierwszej decyzji o objęciu refundacją nie uwzględniają sytuacji leków, dla których w okresie od objęcia refundacją do utraty wyłączności rynkowej wydana została pozytywna decyzja o podwyższeniu CZN. Należy zauważyć, że jeśli wystąpiły warunki wskazujące na zasadność podwyższenia ceny zbytu netto danego leku, a przedstawione przez podmiot odpowiedzialny uzasadnienie zostało pozytywnie rozpatrzone przez Ministra Zdrowia, zasadne jest odwołanie się w przepisach dotyczących obowiązkowej obniżki ceny do CZN obowiązującej w decyzji podwyżkowej. W przeciwnym przypadku podmiot odpowiedzialny będzie zmuszony do obniżenia CZN o więcej niż 25%, a jak słusznie zauważyło MZ w uzasadnieniu do SZNUR – „polski system refundacyjny charakteryzuje niespotykany nigdzie w Europie ustawowy mechanizm, obligujący do redukcji ceny produktów wciąż chronionych patentem”.  Tym samym jeśli w okresie przed utratą wyłączności rynkowej zaistniały okoliczności wskazujące na konieczność podwyższenia CZN trudno oczekiwać, że \\fpodmiot odpowiedzialny będzie miał możliwość obniżenia CZN o ponad 25% (z uwagi na konieczność referowania do CZN z pierwszej decyzji o objęciu refundacją). W szczególności, CZN ma istotne znaczenie w przypadku międzynarodowej referencyjności cenowej i konieczność obniżenia CZN przy braku możliwości zaoferowania tej obniżki w ramach instrumentu dzielenia ryzyka będzie prowadziło do czasowej lub trwałej niedostępności niektórych leków aptecznych dla pacjentów. Jednocześnie trudno się zgodzić ze stanowiskiem MZ przedstawionym w uzasadnieniu do SZNUR (w odniesieniu do zmian w art. 13 ust. 2-2b), w którym MZ wskazuje, że „Niniejsza zmiana niesie ze sobą korzyści dla wszystkich stron partycypujących w systemie refundacyjnym, firmy farmaceutyczne będą wykazywały większą skłonność do redukcji ceny w trakcie renegocjacji cen leków z trwającym okresem wyłączności rynkowej wiedząc, iż każdorazowa poprawa warunków finansowych dla płatnika będzie uwzględniania w ramach ustawowego wymogu obniżki ceny o 25%”. Powyższe zmiany nie dotyczą leków, dla których wydana została pozytywna decyzja o podwyższeniu CZN, w przypadku których żadne korzyści wynikające z obniżki warunków \\fcenowych (przed lub po podwyższeniu ceny) nie będą miały zastosowania.  Słuszne wydaje się zatem dodanie do ustawy refundacyjnej przepisów odnoszących się do sytuacji leków, dla których Minister Zdrowia wydał pozytywną decyzję o podwyższeniu CZN.  Podsumowanie Zwracamy się z uprzejmą prośbą o pozytywne rozpatrzenie zgłoszonej uwagi do przepisów z art. 13 ust. 2d i wprowadzenie zmian zgodnych z przedstawioną powyżej propozycją. Dodanie przepisów odnoszących się do produktów, dla których wydana została przez Ministra Zdrowia pozytywna decyzja o podwyższeniu CZN, i referowania w tym przypadku do CZN z decyzji podwyżkowej zamiast z pierwszej decyzji o objęciu refundacją, pozwoli na równe traktowanie leków w kontekście wymogu obniżenia ceny o 25%. W przeciwnym przypadku leki z podwyższeniem CZN będą zobligowane do znacznie większej redukcji ceny niż inne produkty lecznicze. Usunięcie proponowanego przez MZ ograniczenia możliwości zastosowania obowiązkowej obniżki ceny w terminie utraty wyłączności rynkowej w ramach instrumentów dzielenia ryzyka dla leków \\faptecznych będzie prowadziło do czasowej lub trwałej niedostępności terapii dla pacjentów – a więc sytuacji, która została zaadresowana w ramach DNUR poprzez wprowadzenie modyfikacji w przepisach art. 13. Usunięcie tych przepisów jest kontrproduktywne. Słuszne wydaje się zatem pozostawienie w ustawie refundacyjnej przepisów umożliwiających wypracowanie w ramach negocjacji cenowych pomiędzy MZ a podmiotem odpowiedzialnym warunków cenowych, które przyniosą korzyści wszyskim uczestnikom systemu ochrony zdrowia i zapewnią optymalne oszczędności bez ryzyka w przerwie w dostępności do terapii dla pacjentów bądź istotnego wzrostu kosztów pacjenta do innych leków w grupie limitowej, w której znajduje się lek, do którego zastosowane zostaną przepisy dotyczące obniżki ceny o 25%.\\t\\fUwaga niezasadna W ramach bieżącej nowelizacji ustawodawca musiał ustalić, w związku z projektowanym progresywnym charakterem mechanizmu obniżki, jasno określony punkt w czasie, od którego będzie prowadzone sumowanie dokonywanych obniżek. Wprowadzenie jako punktu odniesienia warunków z pierwszej decyzji o objęciu refundacją miało za zadanie wyeliminowanie między innymi nieuczciwych praktyk podejmowanych przez niektórych wnioskodawców mających na celu uzyskanie decyzji o podwyższeniu ceny zbytu netto przed upływem okresu wyłączności tak aby w stosunku do podwyższonej ceny móc zastosować warunek ustawowej obniżki o 25%. Efektem takiego działania był brak oczekiwanego korzystnego wpływu na wydatki płatnika publicznego związany z upływem okresu wyłączności, co stanowiło sprzeczność z celem jaki przyświecał ustawodawcy przy tworzeniu tego przepisu (uzyskanie oszczędności). Aby zapewnić szerszy zakres realizacji w praktyce wymogu ustawowego w zakresie obniżki o 25% ustawodawca zaproponował w ramach poprzedniej nowelizacji ustawy o refundacji wypełnienie obowiązku – w zakresie ceny zbytu netto, ceny efektywnej lub w mechanizmie mieszanym, tak aby wnioskodawca mógł spełnić obowiązek ustawowy z uwzględnieniem strategii marketingowej korporacji i referencyjności zewnętrznej produktu, dostępnego na innych rynkach. Przyjęcie optyki proponowanej \\fprzez wnoszących uwagi, tj. przyjęcie jako punktu odniesienia najwyższej ceny z okresu przed upływem wyłączności, ponownie doprowadziłoby do sytuacji, która była przyczyną do zmiany ustawy w rozważanym zakresie, a zatem niezgodności z podstawowym założeniem jakie przyświecało sformułowania przepisu o konieczności dokonania obniżki o 25% (oszczędność dla płatnika). Dodatkowo należy zauważyć, iż ustawodawca zaproponował w ramach niniejszej zmiany przepisów tzw. kroczący mechanizm obniżki pozwalający według potrzeb i aktualnych możliwości wnioskodawcy rozłożyć obniżkę również w czasie trwania okresu wyłączności nie tylko jednorazowo - w związku z jego upływem. W opinii ustawodawcy zaproponowane rozwiązania w wystarczającym stopniu chroni interesy Wnioskodawcy przy jednoczesnym zagwarantowaniu, iż projektowany przepis nadal spełnia cel jaki przyświecał jego ustanowieniu.  \\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\tArt. 1 pkt 9 lit. b projektu w zakresie dodawanego ust. 3d  \\t2c. Obowiązek, o którym mowa w ust. 2, 2a lub 2b, stosuje się jednorazowo do wszystkich obowiązujących decyzji administracyjnych o objęciu refundacją leku w przypadku wygaśnięcia okresu wyłączności rynkowej, o którym mowa w art. 15 ust. 2 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, który nastąpi jako pierwszy niezależnie od wskazania.  \\t\\f2d. Mechanizmu, o którym mowa w ust. 2a i 2b nie stosuje się do leku, dla którego w decyzji administracyjnej o objęciu go refundacją określono kategorię dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 1.\\t\\fZa niezasadne należy uznać podejście, które dyskryminuje leki z refundacji aptecznej i wyłącza możliwość zastosowania innych mechanizmów niż mechanizm z ust. 2.  Leki w refundacji aptecznej także mają zawarte instrumenty podziału ryzyka, które obniżają dla płatnika efektywny koszt refundacji, stąd ograniczanie przepisu tak, aby nie dotyczył on leków z \\frefundacji aptecznej jest nierównym traktowaniem podmiotów. To nierówne traktowanie podmiotów wyraża się przede wszystkim w nierównym traktowaniu zagranicznych producentów leków w stosunku do producentów krajowych. Wynika to z faktu, iż obligatoryjne obniżenie ceny o co najmniej 25% odnosi się do leków, w stosunku do których wygasł okres wyłączności rynkowej. A takie leki innowacyjne produkowane są przede wszystkim przez producentów zagranicznych.  Ta dyskryminacja producentów zagranicznych w stosunku do polskich producentów będzie dodatkowo pogłębiona przez fakt pozbawienia producentów zagranicznych możliwości zastosowania przy obniżce cen leków aptecznych innych mechanizmów, niż mechanizm z ust. 2.  Będą więc oni nie tylko gorzej traktowani w stosunku do producentów polskich, ale także w stosunku do leków aptecznych zostanie im zabrany wybór, w jaki najwłaściwszy sposób zastosować tę obniżkę. Z powyższych względów, komentowane rozwiązanie rodzi ryzyko naruszenia przepisów Traktatu o Funkcjonowaniu Unii Europejskiej (TFUE). W szczególności chodzi o art. 28 TFUE, który statuuje prawo swobodnego \\fprzepływu towarów pochodzących z państw członkowskich Unii Europejskiej albo towarów pochodzących z państw trzecich, które znajdują się w swobodnym obrocie w państwach członkowskich Unii Europejskiej. Ten przepis stanowi jedną z podstawowych zasad funkcjonowania Wspólnego Rynku Unii Europejskiej. Choć komentowany projekt przepisu nie zawiera wprost ograniczenia ww. zasady, to jednak może być uznany za pośrednie organicznie w tym zakresie, na skutek przyjęcia rozwiązania dyskryminującego zagranicznych producentów leków, w tym producentów pochodzących z Unii Europejskiej, w stosunku do producentów polskich.\\t\\fUwaga niezasadna Wprowadzenie niniejszej regulacji nie stanowi dyskryminacji jakiejkolwiek grupy producentów, natomiast jest odpowiedzią ustawodawcy na nieprawidłowo funkcjonujący mechanizm, który został zaimplementowany w ramach ostatniej nowelizacji, a ponad dwuletnia praktyka wykazała jego dysfunkcjonalność. W konsekwencji w ramach nowelizacji ustawy o refundacji proponuje się przywrócenie poprzedniej regulacji w \\fprzypadku leków aptecznych, tzn. nie jest to nowy mechanizm, bowiem obowiązywał od początku funkcjonowania ustawy o refundacji do listopada 2023 r. Przedmiotowa kwestia została dokładnie wyjaśniona w uzasadnieniu: „(…)w przypadku produktów wydawanych w aptece na receptę cena zbytu netto w sposób bezpośredni koreluje z ceną efektywną, rozumianą jako ostateczny koszt refundacji dla płatnika. Jednocześnie, możliwa jest redukcja ceny efektywnej produkty wydawanego w aptece na przykład przez zastosowanie tzw. payback’ów – czyli ustalonej kwoty zwrotu do NFZ, za każde zrefundowane opakowanie. Współistnienie w decyzji refundacyjnej produktu aptecznego instrumentu dzielenia ryzyka w postaci payback’u powoduje, że przy obecnej konstrukcji przepisu spełnienie ustawowych wymagań jest możliwe za pomocą obniżki ceny zbytu netto przykładowo o kilkanaście procent oraz odpowiednie zmniejszenie – pogorszenie instrumentu dzielenia ryzyka - dotychczasowego zwrotu do NFZ. Sumarycznie obniżka ceny zbytu netto i ceny efektywnej z perspektywy płatnika wyniesie 25 punktów procentowych, przy nieznacznej redukcji kosztów refundacji”. Wprowadzając obowiązującą dziś regulację umożliwiającą hybrydowe rozwiązanie również w stosunku do leków aptecznych, intencją ustawodawcy nie było zminimalizowanie potencjalnych oszczędności dla płatnika publicznego, a rzeczywistość i mające miejsce od dwóch lat sytuacje, wskazują właśnie takie \\fkonsekwencje w przypadku realizacji ustawowej obniżki w sposób hybrydowy w aptece.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 9 lit. a projektu dotyczący art. 13 ust. 2c i 2d ustawy refundacyjnej\\t2c. Obowiązek, o którym mowa w ust. 2, 2a lub 2b, stosuje się jednorazowo do wszystkich obowiązujących decyzji administracyjnych o objęciu refundacją leku w przypadku wygaśnięcia okresu wyłączności rynkowej, o którym mowa w art. 15 ust. 2 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, który nastąpi jako pierwszy niezależnie od wskazania. 2d. Mechanizmu, o którym mowa w ust. 2a i 2b nie stosuje się do leku, dla którego w decyzji administracyjnej o objęciu go refundacją określono kategorię dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 1.\\tZa niezasadne należy uznać podejście, które dyskryminuje leki z refundacji aptecznej i wyłącza możliwość zastosowania innych mechanizmów niż mechanizm z ust. 2.  Należy wskazać, że każdy z tych mechanizmów skutkuje obniżką ceny. Różni się tylko tym, że czasem w większym stopniu beneficjentem jest pacjent, a czasem Narodowy Fundusz Zdrowia.  Efektywnie jednak w każdym przypadku zyskuje system ochrony zdrowia.  Warto przypomnieć, że finalne warunki są wynikiem negocjacji, więc MZ ma realny wpływ na to jakie oszczędności system osiągnie. \\fNie bez znaczenia jest również, że ze względu na zasady wyznaczania cen i limitu finansowania, obniżka ceny zbytu netto o 25% może nie przełożyć się w żaden sposób na oszczędności NFZ (np. lek, który nie jest na liście S/DZ/ciąża i ma cenę wyższą niż lek wyznaczający podstawę limitu). Pozostawienie możliwości skorzystania z rozwiązania w zakresie ceny efektywnej lub tzw. „hybrydy” umożliwia Ministrowi odpowiednie kształtowanie warunków cenowych, w tym uniknięcie np. sytuacji zmiany produktu wyznaczającego podstawę limitu w grupie i związanego z tym wzrostu dopłat pacjentów do pozostałych leków w grupie przy niewielkim spadku kosztów z perspektywy NFZ.  Wobec powyższego proponuje się uchylenie ust. 2d i pozostawienie wnioskodawcom swobody w zakresie wyboru instrumentu dzielenia ryzyka. Jednocześnie, celem uniknięcia zbędnych wątpliwości proponuje się, że decyzja o wyborze mechanizmu należy do wnioskodawcy (zob. poprawka dotycząca art. 13 ust. 2h).\\t\\fUwaga niezasadna Wprowadzenie zapisu, który wyklucza możliwość zastosowania mechanizmu hybrydowego lub obniżenia wyłącznie ceny efektywnej w instrumencie podziału ryzyka w stosunku do leków dostępnych w aptece na receptę związane jest z faktem trudności jednoznacznego zdefiniowania ceny efektywnej leku w tym kanale dostępności refundacyjnej aby uzyskiwany efekt był jednakowy, powtarzalny dla wszystkich leków dostępnych w tym kanale oraz był zgodny z założeniami jakie przyświecały ustawodawcy w związku z  tworzeniem tego przepisu. Na cenę efektywną leku refundowanego na podstawie recepty w aptece mają bowiem wpływ nie tylko warunki ustalone dla niego ale i dla leku stanowiącego podstawę limitu w grupie, \\fktóre mogą być zmienne w czasie. Aktualne brzmienie przepisu prowadziło do różnych jego interpretacji po stronie wnioskodawców, którzy szacowali koszt efektywny nie z perspektywy płatnika a swojej wskazując na wymagany procent pomniejszenia zysku przedsiębiorcy (CZN pomniejszona o 25%), który jednak nie był tożsamy z perspektywy płatnika (koszt refundacji pomniejszony o 25%).   Doświadczenia Organu z tym zakresie wiązały się z obserwacją działań skutkujących marginalizacją konsekwencji związanych z obniżką poprzez zastosowanie rozwiązań, które nie realizowały podstawowego celu przyświecającego przepisowi, czyli wygenerowania oszczędności dla płatnika publicznego wynikających z faktycznego obniżenia kosztu efektywnego refundacji produktu lub sytuacje, w których faktyczna skala takiej obniżki była znikoma. I tak za przykład można przyjąć sytuację, w której wnioskodawca wyraża chęć realizacji obowiązku ustawowego poprzez pogłębienie ustalonej w poprzedniej decyzji kwoty zwrotu od opakowaniu produktu. Przy niskiej faktycznej wartości obowiązującego zwrotu np. 3 zł oraz wysokiej cenie zbytu netto pogłębienie pay-back o 0,75 zł, które w opinii wnioskodawcy literalnie spełnia warunek ustawowy, nie przekłada się na korzyści z tej obniżki po stronie płatnika publicznego. Koszt efektywny w opinii wnioskodawcy zmniejsza się o 25% jednak wpływ takiej obniżki na faktyczny koszt płatnika (rozumiany przez Organ jako koszt refundacji ponoszony przez \\fpłatnika z uwzględnieniem zwrotu) jest znikomy przy utrzymaniu niezmienionej ceny zbytu netto i braku wpływu na wartość podstawy limitu w grupie. Sytuacja, w której obniżka dotyczy leku będącego podstawą limitu jest realizowana z zupełnie innym skutkiem dla jego wnioskodawcy i płatnika publicznego oraz wnioskodawcy, dla leku który nie stanowi podstawy limitu w tej grupie limitowej. Analiza różnych przykładów w odniesieniu do leków refundowanych w tej kategorii dostępności doprowadziła Organ do wniosku, iż jedynie referowanie do ceny zbytu netto daje warunki sprawiedliwe i powtarzalne oraz umożliwia zachowanie pierwotnego celu rozważanego przepisu.\\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 pkt 9 lit. b projektu w zakresie dodawanego ust. 2d\\tW art. 13 proponujemy uchylenie ust. 2d.\\tWprowadzenie w ramach DNUR szerszego katalogu mechanizmów realizacji tzw. obowiązkowej obniżki ceny miało na celu uelastycznienie rozwiązania zawartego w UoR przed 1 listopada 2023 r., ponieważ brak odpowiednio szerokiego katalogu rozwiązań może niepotrzebnie zagrażać dostępności do wybranych terapii. Mechanizm obniżki hybrydowej ma jednakowe konsekwencje dla budżetu płatnika publicznego w przypadku leków aptecznych, jak i leków stosowanych w programach lekowych. Z tego względu nie można zgodzić się z uzasadnieniem do tej zmiany zawartym w Projekcie.  Ponadto, obniżka wyłącznie ceny zbytu netto w przypadku leku aptecznego ma \\ffaktyczne znaczenie w kontekście niższej ceny detalicznej i dopłaty pacjenta do tego konkretnego leku, natomiast może negatywnie wpływać wysokość dopłat do innych leków w danej grupie limitowej.  Należy podkreślić, że to Minister Zdrowia decyduje ostatecznie o wyborze sposobu realizacji obowiązkowej obniżki. Dlatego też pozostawienie pełnego katalogu dla wszystkich kategorii dostępności refundacyjnej, jest gwarantem równości praw wszystkich podmiotów i jest najbezpieczniejszym i najrozsądniejszym rozwiązaniem zarówno dla pacjenta, płatnika publicznego, jak i poszczególnych wnioskodawców.\\t\\fUwaga niezasadna Wprowadzenie zapisu, który wyklucza możliwość zastosowania mechanizmu hybrydowego lub obniżenia wyłącznie ceny efektywnej w instrumencie podziału ryzyka w stosunku do leków dostępnych w aptece na receptę związane jest z faktem trudności jednoznacznego zdefiniowania ceny efektywnej leku w tym kanale dostępności refundacyjnej aby uzyskiwany efekt był jednakowy, powtarzalny dla wszystkich leków dostępnych w tym kanale oraz był zgodny z założeniami jakie przyświecały ustawodawcy w związku z  tworzeniem tego przepisu. Na cenę efektywną leku refundowanego na podstawie recepty w aptece mają bowiem wpływ nie tylko warunki ustalone dla niego, ale i dla leku stanowiącego podstawę limitu w grupie, które mogą być zmienne w czasie. Aktualne brzmienie przepisu prowadziło \\fdo różnych jego interpretacji po stronie wnioskodawców, którzy szacowali koszt efektywny nie z perspektywy płatnika a swojej wskazując na wymagany procent pomniejszenia zysku przedsiębiorcy (CZN pomniejszona o 25%), który jednak nie był tożsamy z perspektywy płatnika (koszt refundacji pomniejszony o 25%).   Doświadczenia Organu z tym zakresie wiązały się z obserwacją działań skutkujących marginalizacją konsekwencji związanych z obniżką poprzez zastosowanie rozwiązań, które nie realizowały podstawowego celu przyświecającego przepisowi, czyli wygenerowania oszczędności dla płatnika publicznego wynikających z faktycznego obniżenia kosztu efektywnego refundacji produktu lub sytuacje, w których faktyczna skala takiej obniżki była znikoma. I tak za przykład można przyjąć sytuację, w której wnioskodawca wyraża chęć realizacji obowiązku ustawowego poprzez pogłębienie ustalonej w poprzedniej decyzji kwoty zwrotu od opakowaniu produktu. Przy niskiej faktycznej wartości obowiązującego zwrotu np. 3 zł oraz wysokiej cenie zbytu netto pogłębienie pay-back o 0,75 zł, które w opinii wnioskodawcy literalnie spełnia warunek ustawowy, nie przekłada się na korzyści z tej obniżki po stronie płatnika publicznego. Koszt efektywny w opinii wnioskodawcy zmniejsza się o 25% jednak wpływ takiej obniżki na faktyczny koszt płatnika (rozumiany przez Organ jako koszt refundacji ponoszony przez płatnika z uwzględnieniem zwrotu) jest znikomy przy utrzymaniu niezmienionej \\fceny zbytu netto i braku wpływu na wartość podstawy limitu w grupie. Sytuacja, w której obniżka dotyczy leku będącego podstawą limitu jest realizowana z zupełnie innym skutkiem dla jego wnioskodawcy i płatnika publicznego oraz wnioskodawcy, dla leku który nie stanowi podstawy limitu w tej grupie limitowej. Analiza różnych przykładów w odniesieniu do leków refundowanych w tej kategorii dostępności doprowadziła Organ do wniosku, iż jedynie referowanie do ceny zbytu netto daje warunki sprawiedliwe i powtarzalne oraz umożliwia zachowanie pierwotnego celu rozważanego przepisu.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 9 lit b projektu odnoszący się do art. 13 ust. 2c i 2d ustawy refundacyjnej\\tSkreśla się projektowany art. 13 ust. 2d.\\tZa niewłaściwe należy uznać podejście, które dyskryminuje leki z refundacji aptecznej i wyłącza możliwość zastosowania innych mechanizmów niż mechanizm z ust. 2.  Dodatkowo, pozostawienie możliwości skorzystania z rozwiązania projektowanego w art. 13 ust 2a i 2b również dla leków aptecznych umożliwi Ministrowi właściwemu do spraw zdrowia odpowiednie kształtowanie warunków cenowych, w tym uniknięcie np. sytuacji zmiany produktu wyznaczającego podstawę limitu w grupie i związanego z tym wzrostu dopłat pacjentów do pozostałych leków w grupie przy niewielkim spadku kosztów z perspektywy NFZ.\\tUwaga niezasadna Wprowadzenie zapisu, który wyklucza możliwość zastosowania mechanizmu hybrydowego lub obniżenia wyłącznie ceny efektywnej w instrumencie podziału ryzyka w stosunku do leków dostępnych w aptece na receptę związane jest z faktem trudności jednoznacznego zdefiniowania ceny efektywnej leku w tym kanale dostępności refundacyjnej aby uzyskiwany efekt był jednakowy, powtarzalny dla wszystkich leków dostępnych w tym kanale oraz był zgodny z założeniami jakie przyświecały ustawodawcy w związku z  tworzeniem tego przepisu. Na cenę efektywną leku refundowanego na podstawie recepty w aptece mają bowiem wpływ nie tylko warunki ustalone dla niego ale i dla leku stanowiącego podstawę limitu w grupie, które mogą być zmienne w czasie. Aktualne brzmienie przepisu prowadziło do różnych jego interpretacji po stronie wnioskodawców, którzy szacowali koszt \\fefektywny nie z perspektywy płatnika a swojej wskazując na wymagany procent pomniejszenia zysku przedsiębiorcy (CZN pomniejszona o 25%), który jednak nie był tożsamy z perspektywy płatnika (koszt refundacji pomniejszony o 25%).   Doświadczenia Organu z tym zakresie wiązały się z obserwacją działań skutkujących marginalizacją konsekwencji związanych z obniżką poprzez zastosowanie rozwiązań, które nie realizowały podstawowego celu przyświecającego przepisowi, czyli wygenerowania oszczędności dla płatnika publicznego wynikających z faktycznego obniżenia kosztu efektywnego refundacji produktu lub sytuacje, w których faktyczna skala takiej obniżki była znikoma. I tak za przykład można przyjąć sytuację, w której wnioskodawca wyraża chęć realizacji obowiązku ustawowego poprzez pogłębienie ustalonej w poprzedniej decyzji kwoty zwrotu od opakowaniu produktu. Przy niskiej faktycznej wartości obowiązującego zwrotu np. 3 zł oraz wysokiej cenie zbytu netto pogłębienie pay-back o 0,75 zł, które w opinii wnioskodawcy literalnie spełnia warunek ustawowy, nie przekłada się na korzyści z tej obniżki po stronie płatnika publicznego. Koszt efektywny w opinii wnioskodawcy zmniejsza się o 25% jednak wpływ takiej obniżki na faktyczny koszt płatnika (rozumiany przez Organ jako koszt refundacji ponoszony przez płatnika z uwzględnieniem zwrotu) jest znikomy przy utrzymaniu niezmienionej ceny zbytu netto i braku wpływu na wartość podstawy limitu w grupie. \\fSytuacja, w której obniżka dotyczy leku będącego podstawą limitu jest realizowana z zupełnie innym skutkiem dla jego wnioskodawcy i płatnika publicznego oraz wnioskodawcy, dla leku który nie stanowi podstawy limitu w tej grupie limitowej. Analiza różnych przykładów w odniesieniu do leków refundowanych w tej kategorii dostępności doprowadziła Organ do wniosku, iż jedynie referowanie do ceny zbytu netto daje warunki sprawiedliwe i powtarzalne oraz umożliwia zachowanie pierwotnego celu rozważanego przepisu.\\n\\tFederacja Przedsiębiorców Polskich\\tart. 13 ust. 2e ustawy refundacyjnej\\tW art. 13 dodaje się ust. 2e w następującym brzmieniu:   „W przypadku zastosowania mechanizmów, o których mowa w ust. 2 – 2b, wyliczenia cen dokonuje się proporcjonalnie, z uwzględnieniem formulacji zapewniającej ekwiwalentność terapeutyczną”.\\tPropozycja adresuje sytuację, gdy w toku refundacji leku zmianie ulegnie formulacja leku (np. kapsułki na tabletki itp.).\\tUwaga niezasadna Kapsułki i tabletki traktuje się jako tę samą postać farmaceutyczną. Ewentualne kwestie biodostępności mogą zostać poruszone indywidualnie przez Wnioskodawcę w toku procesu refundacyjnego. Propozycje dotyczące warunków implementacji produktu do obwieszczenia w celu zapewnienia ekwiwalentności terapeutycznej na dostosowanych warunkach cenowych mogą być przedmiotem wyjaśnień Wnioskodawcy i ostatecznie podlegać decyzji Ministra Zdrowia.\\n\\tAmerykańska Izba Handlowa w Polsce \\tArt. 13 ust. 2e-2g (nowe)\\tW art. 13 proponujemy dodanie ust. 2e-2g w następującym brzmieniu:  „2e. W przypadku zastosowania mechanizmów, o których mowa w ust. 2 – 2b, wyliczenia cen dla leku dokonuje się proporcjonalnie do prezentacji leku, dla której została wydana pierwsza decyzja administracyjna o objęciu refundacją, przy \\fuwzględnieniu jednostki miary substancji czynnej lub DDD lub PDD. 2f. Jeżeli pierwsza decyzja administracyjna o objęciu refundacją była wydana dla kilku prezentacji leku jednocześnie to jako punkt odniesienia traktowana jest najwyższa cena zbytu netto lub cena efektywna w przeliczeniu na jednostkę miary substancji czynnej lub PDD. 2g. W przypadku zastosowania mechanizmu, o którym mowa w ust. 2a lub ust. 2b nie znajduje zastosowania ust. 2.”.\\t\\fProponowane dodanie ust. 2e-2g w art. 13 ma na celu uregulowanie, że wyliczenie obniżonej ceny powinno być dokonywane proporcjonalnie do tej prezentacji leku, dla której została wydana pierwsza decyzja administracyjna o objęciu refundacją, jednakże przy uwzględnieniu jednostki miary substancji czynnej lub DDD lub PDD.  \\fPonadto, w przypadku gdy jednocześnie wydane zostało kilka pierwszych decyzji o objęciu refundacją dla kilku prezentacji, wówczas punktem odniesienia powinna być jest najwyższa cena zbytu netto lub cena efektywna w przeliczeniu na jednostkę miary substancji czynnej lub PDD.\\t\\fUwaga niezasadna Decyzje refundacyjne są wydawane dla konkretnego leku w danym wskazaniu i w analogiczny sposób oczekuje się jednorazowego obniżenia ceny leku w każdym dostępnym w refundacji wskazaniu po upływie okresu, o którym mowa w art. 11 ust. 3a. Punkt czasowy obniżki dla wszystkich dostępnych wskazań określono w art. 13 ust. 2c. Nie przewiduje się dodatkowych referencji cenowych wewnątrz omawianego zapisu.  Art. 13 ust 2a i 2b są traktowane jako wyjątki od ust. 2, nie ma potrzeby dodawania proponowanego w ust. 2g zapisu.\\n\\tOgólnopolska Izba Gospodarcza Wyrobów Medycznych POLMED\\tArt. 1 pkt 9 lit. c Odnoszący się do art. 13 ust. 6 ustawy refundacyjnej\\tAby zapewnić jednolity mechanizm wyznaczenia ceny progowej kolejnej prezentacji także dla wyrobów medycznych, proponujemy doprecyzowanie art. 1 pkt 9 lit. c : c) w ust. 6: - po pkt 1 dodaje się pkt 1a w brzmieniu  „1a) cena zbytu netto odpowiednika, o którym mowa w pkt 2, w przypadku pierwszego odpowiednika w danym wskazaniu, jeżeli w przeszłości cena zbytu netto leku będącego przedmiotem wniosku w danym wskazaniu lub wyrobu medycznego w danym wskazaniu albo odpowiednika takiego leku lub wyrobu medycznego została ustalona na podstawie pkt 1. Dla wyrobu medycznego cenę zbytu netto określa się z uwzględnieniem \\fceny za jednostkę wyrobu medycznego;”, - w pkt 2: - lit. b otrzymuje brzmienie: b) najdroższego odpowiednika, którego cena zbytu netto za DDD nie przekracza ceny zbytu netto za DDD leku wyznaczającego podstawę limitu, o ile podstawę limitu w danej grupie limitowej wyznacza lek niebędący odpowiednikiem leku, który jest przedmiotem wniosku, a koszt DDD przynajmniej jednego odpowiednika jest nie większy niż koszt DDD leku wyznaczającego podstawę limitu, albo”, - po lit. b dodaje się lit. c w brzmieniu: „c) najtańszego odpowiednika, o ile podstawę limitu w danej grupie limitowej wyznacza lek lub wyrób medyczny niebędący odpowiednikiem leku lub wyrobu medycznego, który jest przedmiotem wniosku, a koszt DDD każdego z odpowiedników jest większy niż koszt DDD leku wyznaczającego podstawę limitu lub koszt jednostki każdego z odpowiedników wyrobu medycznego jest większy niż koszt jednostki wyrobu medycznego wyznaczającego podstawę limitu”, \\f- w części wspólnej kropkę zastępuje się średnikiem i dodaje się pkt 3 w brzmieniu: „3)cena zbytu netto za DDD najtańszej prezentacji, w przypadku gdy przedmiotem wniosku jest kolejna prezentacja refundowanego leku w danym wskazaniu lub cena zbytu netto za jednostkę najtańszej prezentacji wyrobu medycznego w przypadku gdy przedmiotem wniosku jest kolejna prezentacja wyrobu medycznego refundowanego w danym wskazaniu.”, \\t\\t\\fProponowane w projekcie zmiany w art. 13 ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych umożliwiają przy ustalaniu ceny zbytu netto wnioskowanej dla kolejnej prezentacji referowanie do  ceny zbytu netto najtańszej prezentacji obecnej na liście, zamiast do ceny zbytu netto innego odpowiednika. Równocześnie, w zakresie wprowadzonych zmian należy uwzględnić wprowadzenie odrębnej definicji „prezentacji wyrobu medycznego”. Dlatego zaproponowany mechanizm powinien zostać rozszerzony na wyroby medyczne poprzez referowanie także do prezentacji wyrobu medycznego. Zmiana ma charakter techniczny. Po wprowadzeniu odrębnej definicji „prezentacji wyrobu medycznego” \\fmożliwość i zakres zastosowania art. 13 ust. 6 do wyrobów medycznych na podstawie art. 13 ust. 7 budzić może pewne wątpliwości interpretacyjne. Art. 13 ust. 7 pozwala bowiem na odpowiednie stosowanie przepisów o „lekach” do wyrobów medycznych, jednak nie zawiera analogicznego rozszerzenia stosowania przepisów o „prezentacji” na „prezentację wyrobu medycznego”. W celu usunięcia wszelkich wątpliwości proponowane jest precyzyjne odwołanie się do „prezentacji wyrobu medycznego” bezpośrednio w treści art. 13 ust. 6.  Jednocześnie, w celu potwierdzenia istniejącej praktyki, zasadne jest wskazanie, że dla określenie ceny zbytu netto wyrobu medycznego właściwym punktem odniesienia powinien być koszt jednostki a nie koszt DDD.\\t\\fUwaga niezasadna Zgodnie z art. 13 ust. 7 - przepis ust. 6 stosuje się odpowiednio do środka spożywczego specjalnego przeznaczenia żywieniowego i wyrobu medycznego – oznacza to przyjęcie interpretacji zapisów w art. 6 dla wyrobów medycznych zgodnie z przyjętymi dla wyrobów medycznych rozwiązaniami zaimplementowanymi w ustawie refundacyjnej, w tym mając na względzie utworzenie odrębnej definicji „prezentacji wyrobu medycznego”.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 ust. 9 lit c odnoszący się do Art. 13 ust. 6 pkt 2 + ust. 3\\t6. Cena zbytu netto, o której mowa w ust. 5, z uwzględnieniem liczby DDD w opakowaniu jednostkowym, nie może być wyższa niż: 1) 75 % ceny zbytu netto prezentacji o najniższym koszcie za DDD, liczonym według ceny zbytu netto jedynego odpowiednika refundowanego w danym wskazaniu; 1a) cena zbytu netto odpowiednika, o którym mowa w pkt 2, w przypadku pierwszego odpowiednika w danym wskazaniu, jeżeli w przeszłości cena zbytu netto leku będącego przedmiotem wniosku w danym wskazaniu albo jego odpowiednika została ustalona na podstawie pkt 1; 2) cena zbytu netto: a) odpowiednika wyznaczającego podstawę limitu albo \\fb) najdroższego odpowiednika o najwyższej spośród najniższych cen zbytu netto za DDD leku, który dopełnia 25% obrotu ilościowego, liczonego według DDD, spośród leków będących odpowiednikami wnioskowanego leku, zrealizowanego w tej grupie limitowej w miesiącu poprzedzającym o 3 miesiące ogłoszenie obwieszczenia, o którym mowa w art. 37, którego cena zbytu netto za DDD nie przekracza ceny zbytu netto za DDD leku wyznaczającego podstawę limitu, o ile podstawę limitu w danej grupie limitowej wyznacza lek niebędący odpowiednikiem leku, który jest przedmiotem wniosku, a koszt DDD przynajmniej jednego odpowiednika jest nie większy niż koszt DDD leku wyznaczającego podstawę limitu, albo c) najtańszego odpowiednika, o ile podstawę limitu w danej grupie limitowej wyznacza lek niebędący odpowiednikiem leku, który jest przedmiotem wniosku, a koszt DDD każdego z odpowiedników jest większy niż koszt DDD leku wyznaczającego podstawę limitu - w przypadku kolejnego odpowiednika refundowanego w danym wskazaniu; 3) cena zbytu netto za DDD najtańszej prezentacji, w przypadku gdy przedmiotem wniosku jest kolejna prezentacja refundowanego leku w danym wskazaniu, zaś jeśli lek jest już refundowany w innej prezentacji w tej samej dawce – cena zbytu netto za DDD najtańszej prezentacji w danej dawce, o ile jest wyższa niż określona na podstawie pkt 2 . \\t            W zakresie pkt 2 – W grupach limitowych zawierających wiele substancji czynnych często wejście nowego leku (o substancji czynnej innej niż lek stanowiący podstawę limitu) jest zablokowane z powodu refundacji najtańszego leku o bardzo małych udziałach rynkowych (np. z importu równoległego).                    W zakresie pkt 3 – Celem postulatu jest doprecyzowanie, że w przypadku wniosku o refundację kolejnej prezentacji leku już refundowanego w danym wskazaniu, ceną odniesienia powinna być cena zbytu netto za DDD najtańszej prezentacji w tej samej dawce. Dotychczas w praktyce, nawet jeśli wnioskodawca składał wniosek o kolejną prezentację własnego leku, analizowano go w odniesieniu do najtańszej prezentacji dostępnej na wykazie — niezależnie od producenta i niezależnie od dawki. Popieramy kierunek nowelizacji, która eliminuje tę niespójność, umożliwiając wnioskodawcy referowanie do prezentacji swoich produktów. Natomiast odnoszenie się do najtańszej prezentacji per DDD  może skutkować nierealistycznym poziomem oczekiwanej ceny dla nowej prezentacji w przypadku niższych dawek, nawet jeśli \\fpochodzi z tego samego portfolio produktów refundowanych danego wnioskodawcy. W efekcie mogłoby to zniechęcać do wprowadzania opakowań o większej liczbie tabletek, co stoi w sprzeczności z założeniami projektu, który w wielu miejscach odwołuje się do poprawy adherence i ograniczenia liczby wizyt pacjenta w aptece. Dodatkowo, większe opakowania przy tej samej cenie jednostkowej przynoszą systemowi korzyści wynikające z degresywności marży aptecznej. Przykładowo, w przypadku wprowadzenia 3-krotnie większego opakowania w cenie 3-krotnie wyższej, obciążenie systemu refundacyjnego i tak ulega redukcji. Postulat wspiera racjonalizację polityki lekowej, zwiększa dostępność korzystnych dla pacjentów i systemu opakowań oraz eliminuje nieuzasadnione bariery administracyjne. \\t\\fUwaga niezasadna Zapis w zaproponowanej formie właśnie zabezpiecza te sytuacje o których mowa w uwadze, tzn., gdy podstawą limitu jest inna substancja czynna niż wnioskowana, a najtańszy lek z wnioskowaną substancją czynną jest znacznie poniżej podstawy. Zaproponowany zapis wymagałby wyznaczania sztucznej podstawy limitu, jednakże skoro ustalono grupę wielocząsteczkową to m.in. dlatego, aby korzystać z jednego, wspólnego limitu.\\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\tArt. 1 ust. 9 lit c odnoszący się do art. 13  zmiana ust. 6\\t6. Cena zbytu netto, o której mowa w ust. 5, z uwzględnieniem liczby DDD w opakowaniu jednostkowym, nie może być wyższa niż:  1) 75 % ceny zbytu netto prezentacji o najniższym koszcie za DDD, liczonym według ceny zbytu netto jedynego odpowiednika refundowanego w danym wskazaniu;  1a) 95 % ceny zbytu netto tego samego leku dopuszczonego do obrotu w procedurze innej niż import równoległy - w przypadku leku dopuszczonego do obrotu na \\fpodstawie Art. 4a ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. 2) cena zbytu netto:  a) odpowiednika wyznaczającego podstawę limitu, albo  b) najtańszego odpowiednika, o ile podstawę limitu w danej grupie limitowej wyznacza lek niebędący odpowiednikiem leku, który jest przedmiotem wniosku  – w przypadku kolejnego odpowiednika refundowanego w danym wskazaniu, przy czym dla leku dopuszczonego do obrotu na podstawie art. 4a ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne – wskazana cena zbytu netto, o której mowa w ust. 5, z uwzględnieniem liczby DDD w opakowaniu jednostkowym odnosi się do ceny zbytu netto tego samego leku dopuszczonego do obrotu w procedurze innej niż import równoległy. \\t\\fZmiana ma na celu rozdzielenie w procedurze refundacyjnej produktów leczniczych, które stanowią odpowiedniki (i które, zgodnie z założeniami ustawy powinny kształtować ceny w danej grupie limitowej) od produktów z importu równoległego, które nie stanowią kolejnego odpowiednika, ale są tym samym lekiem. Zmiana zapewni realną możliwość sprowadzenia produktów z krajów UE oraz EOG do Polski. \\fUzasadnienie j.w. Zmiana do art. 13 ust. 2 - oraz zmiana do art. 13 ust. 6, muszą być wprowadzone razem.     Uzasadnienie od Kancelaria Radcy Prawnego Tomasz Dauerman: Uzasadnienie jw. Zmiana do art. 13 ust. 2 - oraz zmiana do art. 13 ust. 6, muszą być wprowadzone razem. \\t\\fUwaga niezasadna  Organ nie znajduje podstaw do wprowadzania wyjątków od zasad określonych w ustawie o refundacji leków. Niedopuszczalne jest stosowanie przez analogię przepisów odnoszących się do rejestracji produktów leczniczych pochodzących z importu równoległego do zasad refundacji leków.  Należy podkreślić, że mechanizmy przewidziane w ustawie refundacyjnej zostały zaprojektowane w celu zapewnienia możliwie najniższych cen leków objętych refundacją oraz ich dostępności, i nie różnicują sytuacji \\fpodmiotów ze względu na status czy sposób rejestracji produktu leczniczego.\\n\\tIzba Gospodarcza „FARMACJA POLSKA”\\tArt. 1 ust. 9 lit c odnoszący się do art. 13 ust. 6 pkt 3 ustawy refundacyjnej\\tproponujemy, aby przy ustalaniu ceny zbytu netto dla nowej prezentacji referować do najtańszej prezentacji danego leku o takiej samej dawce jak w prezentacji objętej nowym wnioskiem.\\tArt. 13 ust. 6 pkt 3 – cena zbytu netto przy wniosku dla kolejnej prezentacji leku refundowanego W pełni popieramy propozycję wprowadzenia nowego punktu odniesienia przy ustalaniu ceny zbytu netto dla kolejnej prezentacji leku już refundowanego, w postaci ceny zbytu netto za DDD już refundowanej prezentacji danego leku. Z uwagi jednak na występującą zwłaszcza w przypadku leków od dawna refundowanych nieliniowość wyceny za ich DDD \\fproponujemy, aby przy ustalaniu ceny zbytu netto dla nowej prezentacji referować do najtańszej prezentacji danego leku o takiej samej dawce jak w prezentacji objętej nowym wnioskiem.  W przeciwnym razie istnieje ryzyko, że wnioskodawcy nie będą występować z wnioskami o refundację niektórych dawek, na przykład mniejszych, co z kolei może przekładać się na zwiększone ryzyko strat na lekach dawkowanych indywidualnie (na kilogram masy ciała pacjenta lub powierzchnię ciała pacjenta).\\t\\fUwaga niezasadna Ustawa o refundacyji w żadnym z przypadków porównywania leków, oceny prawidłowej ścieżki refundacyjnej czy określenia cenowych warunków progowych, nie referuje do uzależnienia tych porównań od tej samej dawki leków porównywanych. Ponadto, sama definicja prezentacji wprost wskazuje na pomijanie aspektu wielkości dawki, tj. wg definicji ustawowej prezentacja to lek, środek spożywczy specjalnego przeznaczenia żywieniowego lub wyrób medyczny tego samego wnioskodawcy i \\fposiadający tę samą nazwę, w przypadku którego pomijane są: dawka, wielkość opakowania, smak i kolor. Wartość DDD stanowi najlepszy punkt odniesienia w przypadku danego produktu, szczególnie dla porównań między różnymi prezentacjami, bowiem ostatecznie stanowi wspólny mianownik dla tego typu porównań, niezależnie od obowiązujących warunków cenowych. Co więcej, takie postępowanie jest konsekwentne również w stosunku do pozostałych zapisów ustawy, które w większości referują właśnie do kosztu/wartości DDD. Kwestia nieliniowych cen leków co do zasady jest uzależniona od strategii cenowej danego podmiotu odpowiedzialnego, który w przypadku renegocjacji lub na mocy odpowiedniego wniosku, może w odpowiedni sposób obniżyć ceny produktów z wyższym DDD i w ten sposób ujednolicić koszt DDD\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 ust. 10 lit a odnoszący się do Art. 13a ust. 2\\t2. Preferencje, o których mowa w ust. 1, dotyczą: 1) w zakresie preferencji administracyjnych: a) (skreślony) b) wydania pierwszej decyzji administracyjnej o objęciu refundacją na okres 3 lat, a każdej kolejnej decyzji administracyjnej o objęciu refundacją na okres 5 lat, pod warunkiem że proponowana cena zbytu netto nie przekroczy 150% kosztu DDD wyliczonego na podstawie ceny zbytu netto leku stanowiącej podstawę limitu w grupie limitowej albo 150% kosztu DDD najtańszego odpowiednika, jeżeli lek nie stanowi odpowiednika leku stanowiącego \\fpodstawę limitu w grupie limitowej, w której znajduje się lek, chyba że lek nie był dotychczas wytwarzany w Rzeczypospolitej Polskiej - wówczas pierwsza decyzja o objęciu refundacją jest wydawana na okres 5 lat, c) zwolnienia z negocjacji cenowych z Komisją Ekonomiczną, o której mowa w art. 17, leku o kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 1-3, a w przypadku leku posiadającego co najmniej jeden refundowany odpowiednik oraz leku, który na dzień składania wniosku znajduje się w wykazie, o którym mowa w art. 37 ust. 1 – ustalenia ceny zbytu netto zgodnie z wnioskiem o ile spełnia wymogi wskazane w art. 13 ust. 6 i 6a;                      \\fd) rozpatrzenia wniosku w terminie nie dłuższym niż 90 dni - dla leków o kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 1, oraz nie dłuższym niż 120 dni - dla leków refundowanych dla leków o kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2–3;  2) w zakresie preferencji ekonomicznych: a) obniżenia opłaty za złożenie wniosku lub jego uzupełnienie, o których mowa w art. 32 ust. 1, do poziomu 50 %, b) obniżenia do 50 % opłaty, o którychej mowa w art. 16aa ust. 5 oraz 35 ust. 3, c) ustalenia ceny zbytu netto w wysokości 75 % ceny zbytu netto jedynego odpowiednika refundowanego w danym wskazaniu - w przypadku, o którym mowa w art. 13 ust. 6 pkt 1, d) zwolnienia z obowiązku zapłaty kwoty przekroczenia w przypadku przekroczenia całkowitego budżetu na refundację, o którym mowa w art. 4 – w takim przypadku koszt ten ponosi Fundusz. \\t   W zakresie pkt 1 lit. b – Skorzystanie z preferencji w postaci dłuższej decyzji jest uzależnione od dostosowania ceny leku do ceny najtańszego odpowiednika. Jest to przejaw zastosowania tzw. korytarza cenowego, szkodliwej instytucji, która otwiera drogę do eliminacji krajowej produkcji leków przez dumpingową konkurencję z krajów spoza Unii Europejskiej. Propozycja legislacyjna zmierza do usunięcia elementu korytarzy cenowych, który jest szczególnie krzywdzący, gdyż \\fma zastosowanie wyłącznie dla firm wytwarzających leki w Polsce.       W zakresie pkt 1 lit. c – Na wstępie wskazujemy, że ustawa nie rozróżnia negocjacji na cenowe i inne. Przechodząc do istoty propozycji, zaproponowana punktowa deregulacja, zgodna z deklaracją Premiera RP, oznacza mniej obciążeń administracyjnych dla urzędników, a jednocześnie wspiera realizację zapowiedzi rządu dotyczących preferowania krajowej produkcji.  Objęcie refundacją leku generycznego (odpowiednika) powoduje automatyczne obniżenie ceny dotychczasowego monopolisty. Im więcej dostawców danej cząsteczki, tym lepiej dla pacjenta i NFZ – ze względu na cenę, ale również większe bezpieczeństwo dostaw. Generyki generują około 500 mln oszczędności NFZ rocznie. Leki produkowane w Polsce mogą obecnie korzystać z preferencji polegającej na zwolnieniu z negocjacji cenowych z Komisją Ekonomiczną. W praktyce jednak proces ten często przenosi się na poziom decyzji Ministra Zdrowia, co w przypadku leków generycznych – których maksymalna cena i tak jest sztywno określona (art. 13 ustawy refundacyjnej) – staje się mechanizmem pozbawionym uzasadnienia. W ich przypadku kluczowe powinno być możliwie szybkie i sprawne \\fobjęcie refundacją, z uwagi na potencjalne oszczędności dla systemu ochrony zdrowia oraz zwiększenie bezpieczeństwa dostaw. Premier RP w kwietniu 2025 r. jasno zadeklarował konieczność wspierania krajowej produkcji i polskich firm – dlatego też leki wytwarzane w Polsce, po spełnieniu kryteriów dotyczących obniżki ceny, powinny być niezwłocznie refundowane, bez poddawania ich presji porównywalnej do produktów pochodzących spoza kraju. Deregulacja w tym obszarze odciąża Komisję Ekonomiczną od konieczności prowadzenia negocjacji dotyczących określonej grupy leków, wspierając jednocześnie cel ich preferowania oraz zwiększania dostępności krajowych produktów na rynku leków refundowanych.  Jakie będą korzyści?  - Możliwość uzyskania ceny zgodnie z własnym wnioskiem przez polskiego producenta leków; - Uproszczenie procedur decyzyjnych, zwłaszcza, że zmiana dotyczy leków, które są już obecne w wykazie refundacyjnym lub mają swoje refundowane odpowiedniki; - Szybszy dostęp do refundowanych leków dla polskiego pacjenta.   Co do pkt 1 lit. d – korekta podwójnego użycia określenia „dla leków”.           Co do pkt 2 lit. b – Preferencja powinna obejmować wszystkie opłaty zw. z rozpatrzeniem wniosku, a więc także opłatę za wydanie opinii wstępnej.\\t\\fUwaga niezasadna Zgłaszający uwagę dąży do umożliwienia wydawania decyzji o objęciu refundacją i ustalania ceny zbytu netto na niczym nieograniczonym poziomie cenowym i w dodatku dłuższy okres czasowy. Co odbić się może na możliwościach płatnika do finansowania nowych terapii ratujących życie. Dodatkowo należy zauważyć, że oprócz cen oficjalnych Komisja Ekonomiczna negocjuje również ceny efektywne.        \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 ust. 10 lit b odnoszący się do Art. 13a ust. 2a\\t2a. Wnioskodawca dla leku, który nie ma odpowiednika refundowanego w danym wskazaniu, nie może wybrać preferencji administracyjnej, o której mowa w ust. 2 pkt 1 lit. c. Nie dotyczy to wniosku, o którym mowa w art. 25c ust. 1, oraz leku, o którym mowa w art. 13 ust. 6 pkt 1a i ust. 6a. \\tWyłączenie tej preferencji (zwolnienie z negocjacji) powinno dotyczyć tylko pierwszych wniosków o objęcie refundacją. Preferencja ta powinna być natomiast dostępna w przypadku wniosków kontynuacyjnych, a także w sytuacjach gdy brak odpowiednika wynika z wycofania się odpowiednika (lub odpowiedników) z listy refundacyjnej – w takiej sytuacji cena leku jest już ograniczona ceną progową. \\tUwaga niezasadna Zdaniem organu jest to niepotrzebne komplikowanie zasad rządzących systemem przyznawania preferencji. Zaproponowane przepisy nie wyłączają stosowania art. 13 ustawy o refundacji, jak również nie odbierają Ministrowi Zdrowia możliwości negocjacji na Jego poziomie. \\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 13 ust. 6ab (nowy)\\tW art. 13 proponujemy dodanie nowego ust. 6ab w brzmieniu: „6ab. Cena efektywna, o której mowa w ust. 6aa, nie obejmuje instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 3b.” \\tPrzedmiotowa propozycja została przedstawiona na wypadek pozostawienia definicji „ceny efektywnej” w brzmieniu zaproponowanym w Projekcie. Celem tego rozwiązania jest zapewnienie, że obowiązkowy instrument dzielenia ryzyka uregulowany w przepisie art. 11 ust. 3b nie będzie wliczany w kalkulację ceny efektywnej, w przypadku, gdyby mógł on wpływać na rzeczywistą wysokość tej ceny. W ocenie KF AmCham wnioskodawcy nie powinni ponosić negatywnych konsekwencji zapewnienia dostępu do leczenia w nowych programach lekowych na czas 3 miesięcy \\fprocesu kontraktowania w formule zaproponowanej w Projekcie.\\t\\fUwaga niezasadna Przepis dotyczący tzw. pomostowego dostępu został zmieniony.\\n\\tIzba Gospodarcza „FARMACJA POLSKA”\\tArt. 1 ust. 10 odnoszący się do art. 13a ustawy refundacyjnej\\tPrzyznanie polskim producentom leków preferencji z tytułu wytwarzania leków z substancji czynnych z Europy również służyłoby uniezależnieniu polskich firm od wytwórców API z Azj\\tArt. 13a – preferencje dla leków wytwarzanych z substancji czynnych wytwarzanych w Polsce Z informacji przekazanych nam przez naszych członków wynika, że leki wytwarzane w Polsce z substancji czynnej wytwarzanej w Polsce aktualnie zabezpieczają jedynie ok. 0,6% zapotrzebowania polskich pacjentów na terapie lekami refundowanymi dostępnymi w aptece. Tym samym przepisy art. 13a ustawy o refundacji w zakresie, w jakim odnoszą się do leków wytwarzanych w Polsce z substancji czynnych wytwarzanych w Polsce, mają niewielki udział w zabezpieczeniu dostępności refundowanych leków dla pacjentów w Polsce. Tymczasem cele zapewnienia polskim pacjentom bezpieczeństwa lekowego w równym stopniu realizowałyby mechanizmy, zachęcające do wytwarzania w Polsce leków z substancji czynnych wytwarzanych na terenie Unii Europejskiej/EFTA. Przyznanie polskim producentom leków preferencji z tytułu wytwarzania leków z substancji czynnych z Europy również służyłoby uniezależnieniu polskich firm od wytwórców API z Azji; podczas, gdy, jak pokazała pandemia Covid-19, największym zagrożeniem dla polskiego \\fbezpieczeństwa lekowego jest właśnie wysoki stopień uzależnienia producentów od dostawców API z dalekiego wschodu. W dodatku mechanizm wspierania produkcji lekowej w Polsce wytwarzanej z API z UE lepiej wpisywałoby się w założenia wspólnego rynku europejskiego.\\t\\fUwaga niezasadna Zgodnie z dotychczasowym brzmieniem ustawy, preferencje przysługują wnioskodawcom składającym wniosek o objecie refundacją leku wytwarzanego na terytorium Rzeczypospolitej Polskiej albo leku wytworzonego z wykorzystaniem substancji czynnej wytworzonej na terytorium Rzeczypospolitej Polskiej. Zamysłem przedmiotowego rozwiązania było zachęcanie producentów do otwierania i rozwijania produkcji leków i substancji czynnych w Polsce.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13a ust. 3a\\t3a. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego leku przeznaczonego do wytwarzania na terytorium Rzeczpospolitej Polskiej wnioskodawca dołącza zobowiązanie do spełnienia tego warunku nie później niż w terminie 3 lat od dnia wejścia w życie decyzji. \\tTransfer wytwarzania do Polski – zob. uzasadnienie do art. 2 pkt 11ab.\\tUwaga zasadna\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13a ust. 4\\t4. Minister właściwy do spraw zdrowia w terminie 30 dni od dnia otrzymania wniosku, o którym mowa w ust. 1, wydaje postanowienie, o którym mowa w art. 123 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego (Dz. U. z 2023 r. poz. 775 i 803), określające przyznane wnioskodawcy preferencje zgodnie z jego wnioskiem, biorąc pod uwagę działania prowadzące do powstania leku wytwarzanego na terytorium Rzeczypospolitej Polskiej. \\tW aktualnym brzmieniu art. 13a ust. 4 pozostawia wątpliwości interpretacyjne co do tego, czy Minister Zdrowia jest związany wnioskiem strony w zakresie wyboru preferencji refundacyjnych, czy też ma możliwość ich nieprzyznania, bądź przyznania innych, w sytuacji gdy wnioskodawca spełnia wymóg wytwarzania w Polsce. Dla przecięcia tych wątpliwości postuluje się wyraźne wskazanie, że organ jest związany wyborem preferencji przez stronę.\\tUwaga niezasadna Organ decyduje o przyznaniu preferencji po uprzedniej analizie dokumentacji, o czy mowa w art. 13 ust. 3 ust. ref. Ponadto należy wskazać, iż art. 13 ust. 4 ust ref. wprost wskazuje, iż  „Minister właściwy do spraw zdrowia w terminie 30 dni od dnia otrzymania wniosku, o którym mowa w ust. 1, wydaje postanowienie, o którym mowa w art. 123 ustawy z dnia 14 czerwca 1960 r. - Kodeks postępowania administracyjnego (Dz.U. z 2024 r. poz. 572), określające przyznane wnioskodawcy preferencje, biorąc pod uwagę działania prowadzące do powstania leku wytwarzanego na terytorium Rzeczypospolitej Polskiej.”. Przepis wprost odwołuje się do wnioskowanych preferencji, więc \\fpowielanie regulacji należy uznać za pozbawione uzasadnienia.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13a ust. 5 \\t5. Jeżeli w okresie obowiązywania decyzji o objęciu refundacją wydanej na podstawie wniosku, o którym mowa w ust. 1, wnioskodawca poinformuje o zaprzestaniu spełniania warunków, o których mowa w ust. 1, minister właściwy do spraw zdrowia uchyla postanowienie, o którym mowa w ust. 4 oraz zmienia decyzję o objęciu refundacją w przypadku gdy przyznano preferencję, o której mowa w art. 13 ust. 2 pkt 1 lit. b.  \\tW obecnym brzmieniu ustawa przewiduje tylko jeden sposób postępowania w przypadku gdy wnioskodawca korzystający z preferencji przestanie produkować leki w Polsce – mianowicie uchylenie decyzji refundacyjnej przez Ministra Zdrowia (art. 33 ust. 1 pkt 6). Tymczasem zaprzestanie wytwarzania w Polsce może mieć różne przyczyny, w tym także może być procesem zaplanowanym. W tej sytuacji nie jest właściwe, aby odbierać produktowi refundację – zamiast tego produkt powinien przestać korzystać z preferencji, natomiast pozostać w systemie refundacyjnej na zasadach ogólnych. Taki mechanizm przewiduje proponowana zmiana. Jeżeli wnioskodawca dokona odpowiedniej zmiany decyzji w związku z zaprzestaniem wytwarzania leku w Polsce, uchylenie decyzji nie będzie konieczne. Znalazło to odzwierciedlenie także w odpowiedniej propozycji nowelizacji art. 33 ust. 1 pkt 6 (zob. dalej).\\tUwaga niezasadna Zgłaszający nie dostrzega konieczności w takiej sytuacji regulacji również kosztów, które ponosi płatnik publiczny w związku z dopłatami odpowiednio 10 i 15% za leki dla pacjenta. Jednocześnie kwestia wskazana przez zgłaszającego uwagę może zostać rozwiązania przez złożenie wniosku o skrócenie okresu obowiązywania decyzji refundacyjnej i ewentualnie złożenia nowego wniosku już bez preferencji. . \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13a ust. 6  \\t6. W przypadku gdy wnioskodawca nie wypełnił zobowiązania, o którym mowa w art. 13a ust. 3a, minister właściwy do spraw zdrowia w decyzji administracyjnej zobowiązuje wnioskodawcę do zwrotu uzyskanych korzyści w terminie 14 dni od dnia, kiedy decyzja ta stała się ostateczna. \\tTransfer wytwarzania do Polski – zob. uzasadnienie do art. 2 pkt 11ab.\\tUwaga zasadna Nowa regulacja w zakresie preferencji dla polskich producentów leków.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 13a ust. 7\\t7. Lek wytwarzany w Polsce, umieszczony na wykazie, o którym mowa w art. 37 ust. 1, i objęty w ramach Krajowej Listy Leków   lub unijnym wykazie produktów \\fleczniczych o krytycznym znaczeniu, nie podlega rozszerzonej odpowiedzialności producenta, o której mowa w art. 9 ust. 1 Dyrektywy Parlamentu Europejskiego i Rady (UE) 2024/3019 z dnia 27 listopada 2024 r. dotycząca ścieków komunalnych (wersja przekształcona) oraz w ustawie wykonującej tę dyrektywę. \\t\\fProjekt rozporządzenia unijnego Critical Medicines Act uzasadnia zwolnienie z obowiązków wynikających z dyrektywy \\fUWWTD, mając na uwadze, że nakładane przez nią wymagania stanowią istotne obciążenie administracyjne i operacyjne, mogące negatywnie wpływać na potencjał produkcyjny w zakresie wytwarzania leków o kluczowym znaczeniu dla zdrowia publicznego.\\t\\fPoza zakresem nowelizacji\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 14 ust. 1\\t1.\\tMinister właściwy do spraw zdrowia, wydając decyzję o objęciu refundacją, dokonuje kwalifikacji do następujących odpłatności na dzień wydania decyzji: 1)\\t bezpłatnie - leku, wyrobu medycznego mającego udowodnioną skuteczność w leczeniu nowotworu złośliwego, zaburzenia psychotycznego, upośledzenia umysłowego lub zaburzenia rozwojowego albo choroby zakaźnej o szczególnym zagrożeniu epidemicznym dla populacji, albo leku, środka spożywczego specjalnego przeznaczenia żywieniowego stosowanego w ramach programu lekowego lub dla którego ustalono kategorię dostępności, o której mowa w art. 6 ust. 1 pkt 2a; 2)\\t ryczałtowej - leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego: a)\\t wymagającego, zgodnie z aktualną wiedzą medyczną, stosowania dłużej niż 30 dni oraz którego miesięczny koszt stosowania dla świadczeniobiorcy przy odpłatności 30 % limitu finansowania przekraczałby 5 % minimalnego wynagrodzenia za pracę, ogłaszanego w obwieszczeniu Prezesa Rady Ministrów wydanym na podstawie art. 2 ust. 4 ustawy z dnia 10 października 2002 r. o minimalnym wynagrodzeniu za pracę, albo \\fb)\\t zakwalifikowanego na podstawie art. 72 lub jego odpowiednika, albo c)\\t wymagającego, zgodnie z aktualną wiedzą medyczną, stosowania nie dłużej niż 30 dni oraz którego koszt stosowania dla świadczeniobiorcy przy odpłatności 50 % limitu finansowania przekraczałby 30 % minimalnego wynagrodzenia za pracę, ogłaszanego w obwieszczeniu Prezesa Rady Ministrów wydanym na podstawie art. 2 ust. 4 ustawy z dnia 10 października 2002 r. o minimalnym wynagrodzeniu za pracę; 3) 50 % - leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który wymaga, zgodnie z aktualną wiedzą medyczną, stosowania nie dłużej niż 30 dni; 4) 30 % - leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie został zakwalifikowany do poziomów odpłatności określonych w pkt 1-3.\\t\\fProjekt, wprowadzając nową kategorię dostępności, zawiera lukę – nie określa bowiem poziomu odpłatności pacjenta, w tych przypadkach gdy lek będzie wydawany pacjentowi do domowego stosowania. Kierując się analogią do programów lekowych, zasadne jest wprowadzenie zasady nieodpłatnego zaopatrzenia pacjenta w leki w ramach nowej kategorii dostępności. \\tUwaga bezprzedmiotowa   Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 15 ust. 2\\tWARIANT A Art. 15 2. Do grupy limitowej kwalifikuje się: 1) lek posiadający tę samą nazwę międzynarodową albo inne nazwy międzynarodowe, ale podobne działanie terapeutyczne i zbliżony mechanizm działania;  2) środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny, przy zastosowaniu następujących kryteriów: a) tych samych lub zbliżonych wskazań lub przeznaczeń, w których są refundowane, b) podobnej skuteczności.   \\fWARIANT B Art. 15 2. Do grupy limitowej kwalifikuje się: 1) lek posiadający tę samą nazwę międzynarodową albo inne nazwy międzynarodowe, ale podobne działanie terapeutyczne i zbliżony mechanizm działania, zaś w przypadku leków, o których mowa w art. 5, lek, który zawiera tę samą kombinację substancji czynnych;  2) środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny, przy zastosowaniu następujących kryteriów: a) tych samych lub zbliżonych wskazań lub przeznaczeń, w których są refundowane, b) podobnej skuteczności. \\t\\fWARIANT A Mechanizm kształtowania zbyt szerokich grup limitowych jest główną przyczyną aktualnego stanu faktycznego, gdzie pomimo że ceny zbytu w Polsce należą do najniższych w Europie, poziom współpłacenia pacjenta jest paradoksalnie najwyższy.  W sytuacji gdy do grupy limitowej są włączone leki inne niż odpowiedniki, pacjent mający wskazania medyczne do zastosowania terapii innej niż substancja stanowiąca podstawę limitu, dopłaci pełną różnicę pomiędzy limitem a ceną swojego leku i to nawet w sytuacji, gdy wybierze w aptece najtańszy odpowiednik leku przepisanego przez \\flekarza. W tej sytuacji faktyczny poziom współpłacenia pacjenta  będzie zawsze wyższy niż wynikający z formalnej kategorii odpłatności (ryczałt, 30% lub 50% ceny).  Postulujemy ograniczenie grup limitowych do leków zawierających tę samą substancję czynną, co w konsekwencji uniemożliwi manipulację grupami limitowymi w trakcie trwania decyzji refundacyjnych.  WARIANT B Na wypadek gdyby ograniczenie grup limitowych do leków z tą samą substancją czynną było niemożliwe, postulujemy co najmniej ustawowe zagwarantowanie, że grupy limitowe będą tworzone dla leków złożonych o tej samej kombinacji substancji czynnych.  Grupowanie leków jednoskładnikowych z lekami złożonymi stoi w sprzeczności z aktualnym stanem wiedzy medycznej oraz zasadami racjonalnej polityki refundacyjnej. Przyjęcie, że lek złożony zawierający substancje A i B wykazuje „podobne działanie terapeutyczne” jak lek jednoskładnikowy zawierający jedynie substancję A, prowadziłoby do uzasadnionych wątpliwości co do celowości refundowania leku B, który samodzielnie nie wykazuje działania terapeutycznego.\\t\\fUwaga niezasadna Odp. do wariantu A Zaproponowany zapis powoduje, że różne sole tego samego kwasu posiadające ten sam aktywny metabolit nie mogłyby zostać zakwalifikowane do jednej grupy limitowej. Jako przykład należy wskazać Perindopril, który w lekach występuje jako tozylan perindoprilu, perindopril z argininą oraz sól peryndoprylu z tert-butyloaminą. Nazwy międzynarodowe są różne, ale leki zostały zakwalifikowane do tej samej grupy limitowej ze względu na podobne działanie terapeutyczne i zbliżony mechanizm działania.   Odp. do wariantu B Grupowanie leków w duże grupy limitowe zwiększa konkurencyjność cenową. W przypadku niekorzystnych efektów w każdym momencie Minister Zdrowia może dokonać wyodrębnienia osobnej grupy (art. 15 ust. 3). Jako przykład należy tu wskazać grupę 22.0 Heparyny drobnocząsteczkowe i leki o działaniu heparyn drobnocząsteczkowych, w której pozostawiono Heparyny drobnocząsteczkowe i wyodrębniono grupę 22.1 Leki przeciwzakrzepowe – bezpośrednie inhibitory trombiny i czynnika Xa.\\n\\tAmerykańska Izba Handlowa w Polsce/Pracodawcy RP\\tArt. 15 ust. 2 ustawy \\frefundacyjnej\\t\\fW art. 15 ust. 2 proponujemy nadanie następującego brzmienia: \\f\\\"2. Do grupy limitowej kwalifikuje się lek posiadający tę samą nazwę międzynarodową albo inne nazwy międzynarodowe, ale podobne działanie terapeutyczne i zbliżony mechanizm działania oraz środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny, przy zastosowaniu następujących kryteriów: 1) tych samych wskazań lub przeznaczeń, w których są refundowane; 2) podobnej skuteczności.\\\"\\t\\fObowiązujące od dnia 1 listopada 2023 r. zasady tworzenia grup limitowych pozwalają kwalifikować do jednej grupy \\fleki posiadające inne nazwy międzynarodowe, ale podobne działanie terapeutyczne i zbliżony mechanizm działania. W uwagach do tego przepisu, zgłoszonych podczas konsultacji publicznych, między innymi, przez Polskie Towarzystwo Farmakoekonomiczne wskazano, że: \\\"(…) w polskim systemie ochrony zdrowia znanym na świecie z bardzo naukowego podejścia do oceny technologii medycznych, wyrażonym w praktyce silną rolą Agencji Oceny Technologii Medycznych i Taryfikacji, która opiera się na mocnych kryteriach naukowych, nie powinny istnieć pojęcia „zbliżone” czy „podobne” zwłaszcza, jeśli występują w jednym zdaniu i żadne z tych pojęć nie jest ilościowo zdefiniowane. PTFe rekomenduje niestosowanie tego rodzaju nieprecyzyjnych sformułowań w opisie procesu, który jest w Polsce mocno skwantyfikowany\\\". W konsekwencji, podobnie jak uczyniło to PTFe, KF AmCham postuluje o przywrócenie poprzedniego brzmienia przepisu ust. 2, który jest obecnie nieprecyzyjny i pozostając w mocy może potencjalnie ograniczyć dostęp do niektórych leków w przyszłości.  O ile przepis ten w jego obecnym brzmieniu ułatwia Ministrowi Zdrowia administrowanie grupami limitowymi, to jednak cały czas może prowadzić do destabilizacji systemu refundacji \\fzarówno z punktu widzenia wnioskodawców, jak również pacjentów. To bowiem od kształtu grupy limitowej zależy wysokość dopłaty do cen leków w refundacji aptecznej.  Istotnie, proponowane przywrócenie art. 13 ust. 2 w brzmieniu sprzed dnia 1 listopada 2023 r. oznacza powrót do jednego z kryteriów w postaci \\\"podobnej skuteczności\\\", niemniej jednak wiodącym pozostawać będzie kryterium \\\" tych samych wskazań lub przeznaczeń, w których są refundowane\\\", wobec czego podobieństwo w zakresie skuteczności nie powinno prowadzić do powstawania większych wątpliwości. Tym bardziej, że przepis w tym brzmieniu obowiązywał prawie dwanaście lat. Uzasadnienie Pracodawcy RP Obowiązujące od dnia 1 listopada 2023 r. zasady tworzenia grup limitowych pozwalają kwalifikować do jednej grupy leki posiadające inne nazwy międzynarodowe, ale podobne działanie terapeutyczne i zbliżony mechanizm działania. W uwagach do tego przepisu, zgłoszonych podczas konsultacji publicznych, między innymi, przez Polskie Towarzystwo Farmakoekonomiczne wskazano, że: \\\"(…) w polskim systemie ochrony zdrowia znanym na świecie z bardzo naukowego podejścia do oceny technologii medycznych, wyrażonym w praktyce \\fsilną rolą Agencji Oceny Technologii Medycznych i Taryfikacji, która opiera się na mocnych kryteriach naukowych, nie powinny istnieć pojęcia „zbliżone” czy „podobne” zwłaszcza, jeśli występują w jednym zdaniu i żadne z tych pojęć nie jest ilościowo zdefiniowane. PTFe rekomenduje niestosowanie tego rodzaju nieprecyzyjnych sformułowań w opisie procesu, który jest w Polsce mocno skwantyfikowany\\\". W konsekwencji, postulujemy o przywrócenie poprzedniego brzmienia przepisu ust. 2, który jest obecnie nieprecyzyjny i pozostając w mocy może potencjalnie ograniczyć dostęp do niektórych leków w przyszłości.  O ile przepis ten w jego obecnym brzmieniu ułatwia Ministrowi Zdrowia administrowanie grupami limitowymi, to jednak cały czas może prowadzić do destabilizacji systemu refundacji zarówno z punktu widzenia wnioskodawców, jak również pacjentów. To bowiem od kształtu grupy limitowej zależy wysokość dopłaty do cen leków w refundacji aptecznej.  Istotnie, proponowane przywrócenie art. 13 ust. 2 w brzmieniu sprzed dnia 1 listopada 2023 r. oznacza powrót do jednego z kryteriów w postaci \\\"podobnej skuteczności\\\", niemniej jednak wiodącym pozostawać będzie kryterium \\\" tych samych wskazań lub przeznaczeń, w \\fktórych są refundowane\\\", wobec czego podobieństwo w zakresie skuteczności nie powinno prowadzić do powstawania większych wątpliwości. Tym bardziej, że przepis w tym brzmieniu obowiązywał prawie dwanaście lat. Przepis art. 15 ust. 3-3b w brzmieniu nadanym przez DNUR umożliwia Ministrowi Zdrowia jednostronną zmianę kwalifikacji produktu refundowanego do danej grupy limitowej w dowolnym momencie obowiązywania decyzji o objęciu refundacją. Jak wielokrotnie podkreślała strona społeczna podczas konsultacji publicznych projektu DNUR, przepis ten wprowadził odejście od fundamentalnej zasady prawa administracyjnego jaką jest trwałość decyzji administracyjnej (a w konsekwencji przewidywalności refundacyjnej dla pacjentów i wnioskodawców), naruszając tym samym Dyrektywę Przejrzystości. W związku z powyższym, Pracodawcy RP postulują o zmianę przepisu ust. 3 poprzez powrócenie do jego brzmienia sprzed dnia 1 listopada 2023 r. oraz usunięcie ust. 3a i 3b, które en bloc wprowadzają nieprzewidywalność i godzą w zasadę trwałości decyzji administracyjnych. Istnienie w ustawie przepisu pozwalającego na zmianę decyzji refundacyjnej w trakcie jej trwania na podstawie uznaniowych \\fkryteriów powoduje obawy wnioskodawców odnośnie warunków refundacyjnych w okresie obowiązywania decyzji, na które godził się podczas negocjacji.  Podsumowując, zaproponowane zmiany w odniesieniu do poszczególnych przepisów zawartych w art. 15 ustawy wynikają z konieczności szerokiego spojrzenia na potencjalne konsekwencje istnienia takiej regulacji. Art. 15 ust. 2-3b w jego obecnym brzmieniu prowadzi bowiem do sytuacji, w której rozszerzono kryteria kwalifikacji do grup limitowych, ograniczono możliwość ubiegania się przez wnioskodawcę o zmianę przyporządkowania do grupy limitowej oraz umożliwiono MZ dokonywanie zmiany grup limitowych z urzędu, co może negatywnie wpływać na stabilność systemu refundacji.\\t\\fUwaga niezasadna Należy zauważyć, iż zgodnie z art. 15 ust. 1 i 2 to Minister Zdrowia tworzy grupy limitowe i przypisuje do nich produkty \\flecznicze. Jednocześnie przynależność do grupy limitowej nie jest elementem wniosku refundacyjnego, a następuje dopiero przy wydawaniu decyzji o objęciu refundacją i nie wymaga zgody wnioskodawcy (choć oczywiście może być elementem odwołania od decyzji). Wydaje się więc logiczne, aby łączenie, rozdzielanie lub zmiana nazwy grupy limitowej również leżały po stronie organu. Należy również wskazać, iż zaproponowany przepis jedynie rozszerza uprawnienia zapisane już w art. 16 ustawy.\\n\\tAmerykańska Izba Handlowa w Polsce/Pracodawcy RP\\tArt. 15 ust. 3-3b ustawy refundacyjnej oraz Art. 1 pkt 11 lit. a projektu dotyczący art. 15 ust. 3c ustawy refundacyjnej\\tW art. 15 proponujemy: ust. 3 nadanie następującego brzmienia: \\\"3. Po zasięgnięciu opinii Rady Przejrzystości, opierającej się w szczególności na porównaniu wielkości kosztów uzyskania podobnego efektu zdrowotnego lub dodatkowego efektu zdrowotnego, dopuszcza się tworzenie: 1) odrębnej grupy limitowej, w przypadku gdy droga podania leku lub jego postać \\ffarmaceutyczna w istotny sposób ma wpływ na efekt zdrowotny lub dodatkowy efekt zdrowotny; 2) wspólnej grupy limitowej, w przypadku gdy podobny efekt zdrowotny lub podobny dodatkowy efekt zdrowotny uzyskiwany jest pomimo odmiennych mechanizmów działania leków; 3) odrębnej grupy limitowej dla środków spożywczych specjalnego przeznaczenia żywieniowego, jeżeli zawartość składników odżywczych w istotny sposób wpływa na efekt zdrowotny lub dodatkowy efekt zdrowotny.\\\" uchylenie ust. 3a; uchylenie ust. 3b; uchylenie ust. 3c;\\t\\fPrzepis art. 15 ust. 3-3b w brzmieniu nadanym przez DNUR umożliwia Ministrowi Zdrowia jednostronną zmianę kwalifikacji produktu refundowanego do danej grupy limitowej w dowolnym momencie obowiązywania decyzji o objęciu refundacją. Jak wielokrotnie podkreślała strona społeczna podczas konsultacji publicznych projektu DNUR, przepis ten wprowadził odejście od fundamentalnej zasady prawa administracyjnego jaką jest trwałość decyzji administracyjnej (a w \\fkonsekwencji przewidywalności refundacyjnej dla pacjentów i wnioskodawców), naruszając tym samym Dyrektywę Przejrzystości. W związku z powyższym, KF AmCham postuluje o zmianę przepisu ust. 3 poprzez powrócenie do jego brzmienia sprzed dnia 1 listopada 2023 r. oraz usuniecie ust. 3a i 3b, które en bloc wprowadzają nieprzewidywalność i godzą w zasadę trwałości decyzji administracyjnych. Istnienie w ustawie przepisu pozwalającego na zmianę decyzji refundacyjnej w trakcie jej trwania na podstawie uznaniowych kryteriów powoduje obawy wnioskodawców odnośnie warunków refundacyjnych w okresie obowiązywania decyzji, na które godził się podczas negocjacji.  Podsumowując, zmiany zaproponowane przez KF AmCham w odniesieniu do poszczególnych przepisów zawartych w art. 15 ustawy wynikają z konieczności szerokiego spojrzenia na potencjalne konsekwencje istnienia takiej regulacji. Art. 15 ust. 2-3b w jego obecnym brzmieniu prowadzi bowiem do sytuacji, w której rozszerzono kryteria kwalifikacji do grup limitowych, ograniczono możliwość ubiegania się przez wnioskodawcę o zmianę przyporządkowania do grupy limitowej oraz umożliwiono MZ dokonywanie zmiany grup limitowych z urzędu, co \\fmoże negatywnie wpływać na stabilność systemu refundacji.\\t\\fUwaga niezasadna W procesie refundacyjnym to Minister Zdrowia jest odpowiedzialny za równoważenie interesów pacjentów i przedsiębiorców biorąc pod uwagę możliwości finansowe płatnika publicznego. Dotychczasowa praktyka przed DNUR pokazała, że w tym zakresie brak przepisów utrudniał a czasami wręcz uniemożliwiał racjonalizację polityki refundacyjnej. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 15 ust. 3-3b ustawy refundacyjnej\\tArt. 15 3. Po zasięgnięciu opinii Prezesa Agencji, której podstawą jest porównanie wielkości kosztów uzyskiwania podobnego efektu zdrowotnego lub dodatkowego efektu zdrowotnego w danym stanie klinicznym, dopuszcza się w trakcie obowiązywania decyzji refundacyjnej tworzenie odrębnych lub wspólnych grup limitowych oraz dokonanie zmiany w grupach limitowych, która następuje przez zmianę z urzędu decyzji administracyjnej o objęciu refundacją. 3a. Decyzja, o której mowa w ust. 3, podlega natychmiastowemu wykonaniu. 3b. Skutek prawny zmian w grupach limitowych następuje w obwieszczeniu, o którym mowa w art. 37 ust. 1, opublikowanym po dacie wydania decyzji, o której mowa w ust. 3. \\tWprowadzone nowelizacją z dnia 17 sierpnia 2023 r. przepisy art. 15 ust. 3-3b umożliwiają łączenie, tworzenie odrębnych lub wspólnych grup oraz zmian w grupach limitowych z urzędu przez Ministra Zdrowia w trakcie obowiązywania decyzji refundacyjnej. Przepis daje Ministrowi Zdrowia bardzo szerokie, dyskrecjonalne uprawienia do zmiany ostatecznej decyzji administracyjnej bez zgody jej adresata. Zmiany takie wpłyną nie tylko na samą grupę limitową, ale również na produkt, który stanowił podstawę limitu.  Postulujemy powrót do modelu, w którym określenie grupy limitowej jest elementem rozstrzygnięcia indywidualnej sytuacji prawnej wnioskodawcy w decyzji administracyjnej, a tym samym korzysta z waloru trwałości i nie podlega zmianom bez zgody wnioskodawcy. \\tUwaga niezasadna W procesie refundacyjnym to Minister Zdrowia jest odpowiedzialny za równoważenie interesów pacjentów i przedsiębiorców biorąc pod uwagę możliwości finansowe płatnika publicznego. Dotychczasowa praktyka przed DNUR pokazała, że w tym zakresie brak przepisów utrudniał a czasami wręcz uniemożliwiał racjonalizację polityki refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 15 ust. 3c, 3d (nowy) \\tWARIANT A  3c. Minister dokonuje w wykazie, o którym mowa w art. 37 ust. 1, zmiany grupy limitowej w trakcie obowiązywania decyzji refundacyjnej przez tworzenie odrębnych lub wspólnych grup limitowych oraz dokonanie zmiany w grupach limitowych dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, dla którego w decyzji administracyjnej o objęciu refundacją nie określono grupy limitowej. Przed dokonaniem zmiany, minister właściwy do spraw zdrowia może zasięgnąć opinii \\fPrezesa Agencji, której podstawą będzie porównanie wielkości kosztów uzyskiwania podobnego efektu zdrowotnego lub dodatkowego efektu zdrowotnego w danym stanie klinicznym.  WARIANT B  3c. Minister dokonuje w wykazie, o którym mowa w art. 37 ust. 1, zmiany grupy limitowej w trakcie obowiązywania decyzji refundacyjnej przez tworzenie odrębnych lub wspólnych grup limitowych oraz dokonanie zmiany w grupach limitowych dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, dla którego w decyzji administracyjnej o objęciu refundacją nie określono grupy limitowej. Przed dokonaniem zmiany, minister właściwy do spraw zdrowia może zasięganąć opinii Prezesa Agencji, której podstawą będzie porównanie wielkości kosztów uzyskiwania podobnego efektu zdrowotnego lub dodatkowego efektu zdrowotnego w danym stanie klinicznym, o czym informuje wnioskodawców, których lek, środek spożywczy specjalnego przeznaczenia lub wyrób medyczny, ma znaleźć się w nowej grupie limitowej lub które należą do grup limitowych mających podlegać zmianie, o czym informuje wnioskodawców, których lek, środek spożywczy specjalnego przeznaczenia lub wyrób medyczny, ma znaleźć się w nowej grupie limitowej lub które należą do grup limitowych mających podlegać zmianie. 3d. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 5, złożonego przez wnioskodawcę, którego leku dotyczy zmiana grupy limitowej, w terminie 7 dni od \\fdnia doręczenia decyzji o zmianie decyzji, o której mowa w ust. 3, lub od dnia ogłoszenia obwieszczenia, o którym mowa w art. 37 ust. 1, w którym dokonano zmiany grupy limitowej w sposób wskazany w ust. 3c, stosuje się art. 30 ust. 4 i 5. Art. 11 ust. 11 pkt 1 oraz art. 31 ust. 1 nie stosuje się. \\t\\fWARIANT A Zob. uzasadnienie do postulatu uchylenia art. 15 ust. 3-3b.              WARIANT B Na wypadek gdyby mimo przedstawionych zastrzeżeń utrzymano usunięcie oznaczenia grupy limitowej w decyzji i objęciu refundacją oraz możliwość zmiany grup limitowych z urzędu w trakcie trwania decyzji, konieczne jest co najmniej wprowadzenie minimalnych gwarancji prawnych dla wnioskodawców, opisanych poniżej.  Zmiana grupy limitowej w trakcie obowiązywania decyzji refundacyjnej stanowi poważne odstępstwo od zasady trwałości decyzji administracyjnych. W takiej sytuacji konsultacje z AOTMiT powinny być obowiązkowe – w przeciwnym razie cały proces może nosić znamiona dowolności. Z punktu widzenia prawnych i ekonomicznych skutków zmiana grupy limitowej jest z punktu widzenia wnioskodawców i pacjentów równoznaczna z utworzeniem nowej grupy limitowej. Obligatoryjna opinia Prezesa Agencji jest w tym przypadku równie uzasadniona. Konieczne jest również uprzednie poinformowanie wnioskodawców o planowanych zmianach, aby nie byli nimi zaskakiwani. Ponadto, jeśli można zmienić grupę limitową, a tym samym warunki finansowania leku, w trakcie obowiązywania decyzji, bez zgody wnioskodawcy, należy przynajmniej zagwarantować wnioskodawcy możliwość wyjścia z refundacji. W tym celu proponujemy wprowadzenie \\fmożliwości złożenia wniosku o skrócenie decyzji, który nie podlega odmowie, negocjacjom ani opłacie oraz jest rozpatrywany poza kolejnością.   \\t\\fUwaga niezasadna W procesie refundacyjnym to Minister Zdrowia jest odpowiedzialny za równoważenie interesów pacjentów i przedsiębiorców biorąc pod uwagę możliwości finansowe płatnika publicznego. Dotychczasowa praktyka przed DNUR pokazała, że w tym zakresie brak przepisów utrudniał a czasami wręcz uniemożliwiał racjonalizację polityki refundacyjnej. Art. 15 ust. 3c to uzupełnienie aktualnego art. 15. Biorąc pod uwagę, fakt, iż w obrocie prawnym znajdują się decyzje \\fwydane przed 1 listopada 2023 r. jak i po tej dacie minister właściwy do spraw zdrowia uznał, iż istnieje potrzeba jednoznacznego i zrozumiałego dla wszystkich stron postepowania unormowania tej kwestii.  Wariant B  Obligatoryjne pozyskiwanie opinii Prezesa Agencji przy modyfikacji grup limitowych zmniejsza elastyczność decyzyjną Ministra Zdrowia. Często potrzeba modyfikacji grupy pojawia się na końcowym etapie procesu refundacyjnego, gdzie nie jest już możliwe pozyskanie opinii. Modyfikacje grup limitowych to często techniczne przesunięcia leków nie zawsze jest więc konieczność wymuszania pozyskiwania opinii Prezesa Agencji.   W decyzji refundacyjnej określa się cenę zbytu netto i jest to cena, którą podmiot odpowiedzialny otrzyma za swój lek w trakcie obowiązywania decyzji refundacyjnej. Zmiana podstawy limitu wpływa na marżę apteczną oraz na rozkład odpłatności pomiędzy pacjentem i płatnikiem publicznym. Nieuzasadnione jest umożliwienie szczególnego trybu skracania decyzji refundacyjnej, jeżeli nie dotyczy to CZN ustalonej w decyzji refundacyjnej.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 11 lit. a projektu dotyczący art. 15 ust. 3c ustawy refundacyjnej\\tSkreślić  3c. Minister dokonuje w wykazie, o którym mowa w art. 37 ust. 1, zmiany grupy limitowej w trakcie obowiązywania decyzji refundacyjnej przez tworzenie odrębnych lub wspólnych grup limitowych oraz dokonanie zmiany w grupach limitowych dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, dla którego w decyzji administracyjnej o objęciu refundacją nie określono grupy limitowej. Przed dokonaniem zmiany, minister właściwy do spraw zdrowia może zasięgnąć opinii Prezesa Agencji, której podstawą  będzie porównanie wielkości kosztów uzyskiwania podobnego efektu zdrowotnego lub dodatkowego efektu zdrowotnego w danym stanie klinicznym Alternatywnie wprowadzić zaproponowaną zmianę do art. 11 ust. 5b wraz z dodaniem zmian do obecnego brzmienia: 3c. Minister dokonuje w wykazie, o którym mowa w art. 37 ust. 1, zmiany grupy limitowej w trakcie obowiązywania decyzji refundacyjnej przez tworzenie odrębnych lub wspólnych grup limitowych oraz dokonanie zmiany w grupach limitowych \\fdla leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, dla którego w decyzji administracyjnej o objęciu refundacją nie określono grupy limitowej. Przed dokonaniem zmiany, minister właściwy do spraw zdrowia może zasięgnąć zasięga opinii Prezesa Agencji, której podstawą  będzie porównanie wielkości kosztów uzyskiwania podobnego efektu zdrowotnego lub dodatkowego efektu zdrowotnego w danym stanie klinicznym\\t\\fZobacz uzasadnienie do art. 11 ust. 5b ustawy refundacyjnej. Warto także wskazać, że ograniczenie w nowelizacji z 2023 r. kryteriów medycznych grupowania leków w grupy limitowe i utrzymanie takiego rozwiązania w obecnej nowelizacji powoduje, że w ręce MZ przechodzi decyzja w zasadzie terapeutyczna jakie leki Państwo uznaje za zamienne i w związku z tym ustala limit refundacji na jednym z nim zakładając, że zaspokoi on potrzeby medyczne pacjentów. Grupowanie leków ma przecież w istocie charakter uznania ich za medyczne zamienniki, a więc powinno być oparte o wskazane w ustawie kryteria medyczne, a nie tylko finansowe. Dodatkowo w kontekście alternatywnego rozwiązania przepis art. 15 ust. 3c powinien zawierać co najmniej obowiązek konsultacji każdej zmiany grupy limitowej z Prezesem Agencji. Taka zmiana pozwoli Ministrowi na kształtowanie grup limitowych przy jednoczesnym zachowaniu kontroli nad dowolnością i częstością takich zmian (informacje o zleceniach publikowane są \\fw BIP AOTMiT, tym samym wnioskodawcy mogą wcześniej otrzymać informację o planowanych zmianach).\\t\\fUwaga niezasadna Art. 15 ust. 3c to uzupełnienie aktualnego art. 15. Biorąc pod uwagę, fakt, iż w obrocie prawnym znajdują się decyzje wydane przed 1 listopada 2023 r. jak i po tej dacie minister właściwy do spraw zdrowia uznał, iż istnieje potrzeba jednoznacznego i zrozumiałego dla wszystkich stron postepowania unormowania tej kwestii.  Obligatoryjne pozyskiwanie opinii Prezesa Agencji przy modyfikacji grup limitowych zmniejsza elastyczność decyzyjną Ministra Zdrowia. Często potrzeba modyfikacji grupy pojawia się na końcowym etapie procesu refundacyjnego, gdzie nie jest już możliwe pozyskanie opinii. Modyfikacje grup limitowych to często techniczne przesunięcia leków nie zawsze jest więc konieczność wymuszania pozyskiwania opinii Prezesa Agencji.  \\n\\tPOLSKA FEDERACJA PRODUCENTÓW ŻYWNOŚCI ZWIĄZEK PRACODAWCÓW\\tArt. 1 pkt 11 lit. a projektu dotyczący art. 15 ust. 3c ustawy refundacyjnej\\tZaproponowane zmiany rozszerzają uprawnienia MZ w zakresie tworzenia, jak i zmiany grup limitowych. W konsekwencji będzie się to przekładało na szerokie uprawnienia MZ oraz ograniczone uprawnienia wnioskodawców w zakresie wyznaczania produktu stanowiącego podstawę limitu. Skutkować to będzie brakiem możliwości przewidzenia przez wnioskodawców dalszych scenariuszy w zakresie grup limitowych, do których mogą należeć produkty wnioskodawcy. W związku z tym PFPŻ ZP postuluje wykreślenie projektowanej zmiany.\\t\\tUwaga niezasadna Art. 15 ust. 3c ustawy o refundacji to uzupełnienie aktualnego art. 15. Biorąc pod uwagę, fakt, iż w obrocie prawnym znajdują się decyzje wydane przed 1 listopada 2023 r. jak i po tej dacie minister właściwy do spraw zdrowia uznał, iż istnieje potrzeba jednoznacznego i zrozumiałego dla wszystkich stron postepowania unormowania tej kwestii.\\n\\tIzba Gospodarcza „FARMACJA POLSKA”\\tArt. 1 pkt 11 lit. a projektu dotyczący art. 15 ust. 3c ustawy refundacyjnej\\tNowy przepis w art. 15 ust. 3c powinien co najmniej zawierać obowiązek konsultacji każdej zmiany grupy limitowej z AOTMiT\\tArt. 15 ust. 3c – zmiany w grupach limitowych W przepisie tym proponuje się zwiększenie swobody Ministerstwa Zdrowia w kształtowaniu grup limitowych, co ma istotny wpływ na wysokość dopłat pacjentów do leku i koszt NFZ. Tymczasem obecnie nie ma w przepisach ustawy o refundacji żadnych mechanizmów zabezpieczających wnioskodawcę przed dowolnym i \\fczęstym zmienianiem grup limitowych dla leku. Brak przewidywalności i stabilności jest kluczowym czynnikiem przy planowaniu strategii refundacyjnej i składaniu propozycji cenowych dla płatnika. Nowy przepis w art. 15 ust. 3c powinien co najmniej zawierać obowiązek konsultacji każdej zmiany grupy limitowej z AOTMiT. Taka zmiana pozwoli Ministrowi na kształtowanie grup limitowych przy jednoczesnym zachowaniu kontroli nad dowolnością i częstością takich zmian (informacje o zleceniach publikowane są w BIP AOTMiT, tym samym wnioskodawcy mogą wcześniej otrzymać informację o planowanych zmianach).\\t\\fUwaga niezasadna Art. 15 ust. 3c to uzupełnienie aktualnego art. 15. Biorąc pod uwagę, fakt, iż w obrocie prawnym znajdują się decyzje wydane przed 1 listopada 2023 r. jak i po tej dacie minister właściwy do spraw zdrowia uznał, iż istnieje potrzeba jednoznacznego i zrozumiałego dla wszystkich stron postepowania unormowania tej kwestii.  \\fObligatoryjne pozyskiwanie opinii Prezesa Agencji przy modyfikacji grup limitowych zmniejsza elastyczność decyzyjną Ministra Zdrowia. Często potrzeba modyfikacji grupy pojawia się na końcowym etapie procesu refundacyjnego, gdzie nie jest już możliwe pozyskanie opinii. Modyfikacje grup limitowych to często techniczne przesunięcia leków nie zawsze jest więc konieczność wymuszania pozyskiwania opinii Prezesa Agencji.  \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 15 ust. 4\\t4. Podstawę limitu w danej grupie limitowej dla leków, o których mowa w art. 6 ust. 1 pkt 1, stanowi cena hurtowa za DDD leku o najwyższej spośród najniższych cen zbytu netto za DDD, który dopełnia 25 % obrotu ilościowego liczonego według DDD, zrealizowanego w tej grupie limitowej w miesiącu kwartale kalendarzowym bezpośrednio poprzedzającym o 3 miesiące kwartał, w którym nastąpiło ogłoszenie obwieszczenia, o którym mowa w art. 37 ust. 1. \\tSkorzystanie z danych opisujących udziały w rynku w dłuższym horyzoncie czasowym spowoduje, że poziomy limitów/odpłatności/refundacji będą charakteryzować się mniejszymi fluktuacjami i większą stabilnością w porównaniu do sytuacji obecnej – co jak się wydaje będzie z korzyścią dla systemu i wszystkich jego interesariuszy.\\tUwaga niezasadna Do obliczeń używa się danych najbardziej odzwierciedlających aktualną sprzedaż. Przy wprowadzaniu leku na rynek, gdy brak jest jeszcze constans to dane za ostatni dostępny miesiąc należy uznać za najbardziej odwzorowujące rynek.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 15 ust. 4a\\t4a. W przypadku gdy dla wszystkich żadnych leków w danej grupie limitowej nie są ma dostępnyche danyche dotyczącyche obrotu ilościowego, o których mowa w ust. 4, podstawę limitu w danej grupie limitowej dla leków, o których mowa w art. 6 ust. 1 pkt 1, stanowi cena hurtowa za DDD leku o \\fnajniższej cenie zbytu netto za DDD, który według zobowiązania, o którym mowa w art. 11 ust. 2 pkt 9, dopełnia 25 % szacowanego zapotrzebowania na te leki deklarowanego w tej grupie limitowej na pierwszy miesiąc obowiązywania obwieszczenia, o którym mowa w art. 37 ust. 1, w którym po raz pierwszy wskazano wysokość limitu finansowania w danej grupie limitowej, liczonego według DDD leku. \\t\\fPZPPF proponuje zmianę brzmienia projektowanego art. 15 ust. 4a. Brzmienie zaproponowane przez Projektodawcę prowadzi do nieuzasadnionego niczym zaniżenia podstawy limitu w pierwszym okresie \\frefundacji leków w danej grupie limitowej.  Rozwiązaniem jest zastosowanie ogólnej reguły wyznaczania podstawy limitu z ust. 4, jednak nie w oparciu o wolumen obrotu realnego (gdyż tych danych na początku brak), a w oparciu o wolumen deklarowany przez wnioskodawców i zaakceptowany przez MZ w ramach decyzji o objęciu refundacją.\\t\\fUwaga niezasadna Propozycja jest uzupełnieniem obecnej luki prawnej w tej materii i została już zastosowana. Przy wyznaczeniu jako podstawy limitu leku o najniższym koszcie za DDD cena detaliczna leków będzie niższa niż w \\fprzypadku, gdy podstawę limitu będzie wyznaczał lek o najwyższym koszcie za DDD, co przekłada się na niższe koszty refundacji dla płatnika oraz pacjentów realizujących recepty pełnopłatnie. Istotnym jest fakt, że przyjęcie jako podstawy limitu produktu o najniższym koszcie za DDD jest wyłącznie sytuacją przejściową, bowiem wraz z publikacją kolejnych obwieszczeń podstawę limitu wyznaczy najniższa spośród najwyższych cen zbytu netto dopełniająca 25% obrotu ilościowego zgodnie z obowiązującym art. 15 ust. 4 ustawy refundacyjnej.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 15 ust. 11\\t11. Podstawę limitu w danej grupie limitowej leków, o których mowa w art. 6 ust. 1 pkt 2 - 3, stanowi najwyższa cena hurtowa leku, którego cena zbytu netto za DDD nie przekracza średniej ważonej obrotem ilościowym według DDD leku ceny zbytu netto za DDD leków w tej grupie limitowej w roku poprzedzającym rok ustalenia podstawy, przy czym ust. 7 stosuje się odpowiednio.\\tW przypadku leków stosowanych w ramach programów lekowych i chemioterapii wyznaczenie podstawy limitu przez odwołanie się do średniej ceny, bez uwzględnienia wolumenu sprzedaży poszczególnych produktów, może doprowadzić do nieakceptowalnych skutków w postaci nieprzewidywalnego obniżenia lub podwyższenia limitu finansowania ze względu na nietypowo niską lub wysoką cenę leku o marginalnej sprzedaży. Aby uniknąć takich skutków w przypadku leków z listy aptecznej, ustawodawca przewidział w art. 15 ust. 4 mechanizm odwołujący się do leku dopełniającego 25 % obrotu w grupie limitowej. Podobne założenie, odwołujące się do wolumenu obrotu, powinno towarzyszyć wyznaczaniu podstawy limitu dla leków z listy chemioterapii i programów lekowych. W związku z tym postulujemy odwołanie się w przepisie do średniej ważonej (uwzględniającej wielkość obrotu). \\fPostulat jest istotny także ze względu na wprowadzenie nowej kategorii dostępności (art. 6 ust. 1 pkt 2a). \\t\\fUwaga niezasadna Obowiązujący od 1 listopada 2023 r. przepis jest bardzo uproszczony w stosunku do poprzedniego, gdzie używane były deklaracje dostaw dla każdego z leków. Taki sposób obliczeń jest również bardziej przejrzysty, ponieważ nie zawiera żadnych ukrytych danych. Trywialność zapisu polega na tym, że płatnik publiczny płaci za lek tyle ile wynosiła jego średnia (oficjalna) cena w poprzednim roku. Przy dodawaniu nowych leków, obniżkach, podwyżkach brane jest pod uwagę, że ustalona cena zostanie wliczona do średniej w kolejnym roku – obecne negocjacje są prowadzone ze świadomością tego zapisu zarówno po stronie podmiotu odpowiedzialnego który przystępuje do postępowania jak i Komisji Ekonomicznej. Konsekwencje tego są długofalowe, więc nierozsądnym byłoby wprowadzanie nowej zmiany w tym momencie. Dodatkowo zobowiązano Komisję Ekonomiczną do prowadzenia negocjacji również w zakresie zobowiązania do \\fzapewnienia ciągłości dostaw, tak aby leki które mają niską cenę miały wystarczająco dostosowane deklaracje dostaw. Nie zauważono negatywnych skutków opisywanych w uzasadnieniu uwagi.  \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 12 projektu dotyczący art. 16a ustawy refundacyjnej\\tArt. 16a. 1. W przypadku gdy wniosek, o którym mowa w art. 16aa 24 ust. 1 pkt 1, dotyczy kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, minister właściwy do spraw zdrowia ustala opisy programów lekowych po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, a w uzasadnionych przypadkach również medycznego towarzystwa naukowego z danej dziedziny medycyny. Opis programu lekowego podlega konsultacji z Prezesem Agencji w zakresie zgodności z Charakterystyką Produktu Leczniczego oraz wytycznymi klinicznymi odnoszącymi się do technologii medycznej stosowanej w danym programie lekowym. 2. Minister właściwy do spraw zdrowia przedstawia opis programu lekowego do zaopiniowania wnioskodawcy po przeprowadzonej konsultacji z Prezesem Agencji. Wnioskodawca jest obowiązany przedstawić stanowisko w terminie nie dłuższym niż 7 dni od dnia otrzymania opisu programu lekowego. Stanowisko wnioskodawcy nie jest wiążące dla ministra właściwego do spraw zdrowia. 3. Minister właściwy do spraw zdrowia przedstawia ustalony opis programu lekowego wnioskodawcy w wstępnej opinii, o której mowa w art. 16aa ust. 1 \\fprzed przekazaniem Prezesowi Agencji wniosku i analiz zgodnie z art. 35 ust. 1 . 4. W przypadku chorób rzadkich oraz ultrarzadkich, opis programu lekowego może przewidywać powołanie przez Prezesa Funduszu zespołu koordynacyjnego dla danego programu lekowego. 5. Zmiany opisu programu lekowego dokonuje minister właściwy do spraw zdrowia w wykazie, o którym mowa w art. 37 ust. 1, w przypadku jeżeli jest to uzasadnione względami medycznymi lub organizacyjnym. 6. W przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do spraw zdrowia może przeprowadzić przeprowadza konsultacje z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji, a w uzasadnionych przypadkach również medycznym towarzystwem naukowym z danej dziedziny medycyny. 7. W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia ustala opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1. Minister właściwy do spraw zdrowia przedstawia opis programu lekowego do zaopiniowania wnioskodawcy, którego lek jest refundowanych w ramach danego \\fprogramu lekowego. Wnioskodawca jest obowiązany przedstawić stanowisko w terminie nie dłuższym niż 7 dni od dnia otrzymania opisu programu lekowego. Stanowisko wnioskodawcy nie jest wiążące dla ministra właściwego do spraw zdrowia. 8. Dla opisu refundowanych wskazań, w przypadku kategorii, o której mowa w art. 6 ust. 1 pkt 2a i 3, przepisy ust. 1–7 stosuje się odpowiednio. \\t\\fINFARMA podtrzymuje zarzuty przedstawione w ramach procesu legislacyjnego nowelizacji z 2023 r., a także zarzuty przedstawione w skardze do Komisji Europejskiej.  Mając jednak na uwadze postulat przedstawiony jako propozycja art. 11 ust. 5b (który powodowałby, że „wyjęcie” z decyzji refundacyjnych zarówno opisu programu lekowego, jak i opisu wskazań dla innych kategorii dostępności byłoby akceptowalne w świetle Dyrektywy Przejrzystości), INFARMA proponuje rozwiązania mające na celu poprawę istniejących mechanizmów. Z uwagi na propozycje zmian do art. 16aa (prekonsultacje), proponuje się zmianę „umiejscowienia” ustalania opisu programu lekowego. Tym momentem nie powinny być niewiążące prekonsultacje, a właściwe postępowanie refundacyjne – okres po złożeniu wniosku , aż do chwili skierowania wniosku i analiz do Agencji. To właśnie ten etap jest kluczowy z perspektywy oceny programu lekowego (do tego czasu powinien być on zasadniczo ustalony). Takie rozwiązanie uwzględnia także np. zmiany zapisów w ChPL czy wytycznych, które mogą zajść po wydaniu decyzji dla wniosku \\fprekonsultacyjnego, a przed złożeniem wniosku o objęcie refundacją. Te propozycje odzwierciedlają zmiany do ust. 1 i 3 . Jednocześnie w ramach ust. 4 proponuje się aby zespoły koordynacyjne funkcjonowały jedynie w ramach chorób rzadkich i ultrarzadkich. Zespoły koordynacyjne – jako szczególnego rodzaju konsylium lekarskie wydaje się znajdować uzasadnienie wyłącznie w stosunku do leków stosowanych we wskazaniach w leczeniu chorób rzadkich i ultrarzadkich. W lekach stosowanych powszechnie lekarze specjaliści mają wystarczającą wiedzę, aby decydować o zasadności kwalifikacji pacjentów lub ich wyłączenia z leczenia. Medyczne warunki stosowania danego leku w ramach programu powinny być merytoryczną podstawą do kwalifikacji pacjentów co do zasady przez lekarza prowadzącego. W ust. 5 proponuje się wprowadzenie zmiany, która odpowiada wytycznym z Dyrektywy Przejrzystości. W związku z tym należy doprecyzować w jakich przypadkach MZ będzie uprawniony do zmiany programu lekowego. W ust. 6 proponuje się wprowadzenie obowiązku prowadzenia konsultacji przy zmianie opisu programu lekowego, tak jak przy jego tworzeniu. Dzięki temu będzie pewność, że te zmiany znajdują akceptację środowiska medycznego. Jednocześnie w ust. 7 proponuje się usunięcie dotychczasowej treści (zmiany wynikające z zaproponowania \\fniewiążącego charakteru prekonsultacji) i włączenie (na zasadach analogicznych jak przy tworzeniu opisu programu lekowego) wnioskodawcy do procesu modyfikacji opisu programu lekowego. Nie proponujemy zmian do ust. 8, co wynika z założenia, że wprowadzona zostałaby propozycja dodania art. 11 ust. 5b oraz przyjęcia propozycji zmian do poprzednich ustępów art. 16a. \\t\\fUwaga częściowo niezasadna Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy refundacyjnej, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku refundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra właściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do treści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez strony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści następowała dopiero po wpłynięciu do \\fministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem trwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego świadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister Zdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem wydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu prowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym \\fwskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów kpa do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 ustawy o refundacji otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1.\\n\\tPolskie Towarztstwo Farmakoekonomiczne\\tArt. 1 pkt 12 projektu dotyczący art. 16a ustawy refundacyjnej\\t Przepisy dotyczące modyfikacji opisów programów lekowych powinny zostać uzupełnione o jasne kryteria dokonywania zmian oraz obowiązek konsultacji z ekspertami medycznymi i wnioskodawcami (Art. 16a UR).  \\t Proponujemy doprecyzowanie w art. 16a ust. 5, że zmiany w opisach programów lekowych mogą być dokonywane tylko jeśli jest to uzasadnione względami medycznymi lub organizacyjnymi. Takie rozwiązanie zwiększa przewidywalność systemu i chroni interesy pacjentów oraz wnioskodawców  • Proponujemy także wprowadzenie zmiany, która doprecyzowałaby w jakich przypadkach MZ będzie uprawniony do \\fzmiany programu lekowego: „minister właściwy do spraw zdrowia” zamiast „może przeprowadzić” wprowadzić zapis „ przeprowadza konsultacje z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji, a w uzasadnionych przypadkach również medycznym towarzystwem naukowym z danej dziedziny medycyny„  • Propozycja zmiany art. 16a ust. 6, wprowadzająca obowiązek (zamiast możliwości) przeprowadzenia konsultacji z konsultantem krajowym, wojewódzkim oraz Prezesem Agencji przy modyfikacji programu lekowego, jest w pełni uzasadniona. Zapewnia ona, że zmiany będą oparte na aktualnej wiedzy medycznej i znajdą akceptację środowiska medycznego, co jest kluczowe dla skuteczności programów lekowych. Najlepiej więc aby ust. 6 był sformułowany w taki sposób, że ust. 1 i 2 do zmian w opisach programu lekowego stosuje się odpowiednio.     \\t\\fUwaga niezasadna Nowelizacja ustawy o refundacji z 2023 r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez potrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. Powyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do \\fpotrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju opcji terapeutycznych i metod diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew stanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. Wszelki zmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców.  Wprowadzenie obowiązku (zamiast możliwości) przeprowadzenia konsultacji z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji w zakresie zmiany treści programu lekowego jest środkiem nadmiarowym, ponieważ nie każda zmiana musi być zmianą merytoryczną wymagająca angażowania wskazanych ekspertów.   \\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 12 projektu dotyczący art. 16a ust. 2, 5, 6 i 9 ustawy \\frefundacyjnej\\t\\fWnioskujemy o zmianę zapisów dotyczących możliwości dokonywania zmian w zapisach programów lekowych przez Ministra Zdrowia.  \\fProponujemy następujące brzmienie przepisu:  W art. 16a ust. 2 przyjmuje następujące brzmienie:  „2. Minister właściwy do spraw zdrowia przedstawia opis programu lekowego do zaopiniowania wnioskodawcy po przeprowadzonej konsultacji z Prezesem Agencji. Wnioskodawca jest obwiązany przedstawić stanowisko w terminie nie dłuższym niż 7 dni od dnia otrzymania opisu programu lekowego. Stanowisko wnioskodawcy nie jest wiążące dla ministra właściwego do spraw zdrowia, z zastrzeżeniem ust. 9.”  W art. 16a ust. 5 i 6 przyjmuje następujące brzmienie:  „5. Zmiany opisu programu lekowego dokonuje minister właściwy do spraw zdrowia w wykazie, o którym mowa w art. 37 ust. 1., w drodze decyzji administracyjnej.  6. W przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do spraw zdrowia przeprowadza konsultacje z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz może przeprowadzić konsultacje z Prezesem Agencji, a w uzasadnionych przypadkach również z \\fmedycznym towarzystwem naukowym z danej dziedziny medycyny.”  W art. 16a dodaje się ust. 9. w następującym brzmieniu:  „9. W przypadku, gdy zmiana, o której mowa w ust. 5, ma charakter istotny, w szczególności prowadzi do zmiany kryteriów włączenia i wyłączenia z programu lekowego w sposób, który wpływa na uzgodniony koszt terapii dla wnioskodawcy wynikający z decyzji refundacyjnej, w tym z instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 5, jej wprowadzenie wymaga zgody wnioskodawcy.”\\t\\fNowelizacja ustawy refundacyjnej wprowadziła właściwie nieograniczoną możliwość zmian programów lekowych z urzędu przez Ministra Zdrowia.   \\fZa właściwe uważamy przekazanie większej kontroli nad zapisami programów lekowych w ręce Ministra, co w naszej opinii usprawniło proces ich zmiany, zwłaszcza w zakresie, w jakim zmiany te związane były z dostosowaniem brzmienia do aktualnego stanu wiedzy medycznej.   Niemniej w zakresie, w jakim zmiany dotyczą warunków finansowych, które zostały uzgodnione przez Ministra Zdrowia oraz wnioskodawcę (w tym w szczególności prowadzą do zmiany kryteriów włączenia i wyłączenia z programu lekowego w sposób, który wpływa na uzgodniony koszt terapii dla wnioskodawcy wynikający z decyzji refundacyjnej, w tym z instrumentu dzielenia ryzyka) niezbędna jest naszym zdaniem zgoda, a nie tylko stanowisko wnioskodawcy.   Ponadto, naszym zdaniem zmiany w programach lekowych powinny być każdorazowo uzgadniane co najmniej z konsultantem krajowym lub wojewódzkim z odpowiedniej dziedziny medycyny.   Obecnie projektowane przepisy w dalszym ciągu pogłębiają znaczną nierównowagę stron uczestniczących w postępowaniu refundacyjnym oraz w dalszym ciągu umożliwiają jednostronną \\fzmianę warunków obowiązywania decyzji refundacyjnych.\\t\\fUwaga niezasadna Nowelizacja ustawy o refundacji z 2023 r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez \\fpotrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. Powyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do potrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju opcji terapeutycznych i metod diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew stanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. Wszelki zmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców.  Wprowadzenie obowiązku (zamiast możliwości) przeprowadzenia konsultacji z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji w zakresie zmiany treści programu lekowego jest środkiem nadmiarowym, ponieważ nie każda zmiana musi być zmianą merytoryczną wymagająca angażowania wskazanych ekspertów.   \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 12 projektu dotyczący art. 16a ust. 5, 6, 7a (nowy)\\t5. Zmiany opisu programu lekowego dokonuje minister właściwy do spraw zdrowia w wykazie, o którym mowa w art. 37 ust. 1. Przepisy ust. 1 i 2 stosuje się odpowiednio. 6. W przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do spraw zdrowia może przeprowadzić konsultacje z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji, a w uzasadnionych przypadkach również medycznym towarzystwem naukowym z danej dziedziny medycyny. 7a. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 5, wnioskodawcy, który wyraził negatywne stanowisko na temat zmiany, o której mowa w ust. 5, złożonego w terminie 7 dni od dnia ogłoszenia obwieszczenia, o którym mowa w art. 37 ust. 1, w którym \\fdokonano zmiany opisu programu lekowego, stosuje się art. 30 ust. 4 i 5. Art. 11 ust. 11 pkt 1 oraz art. 31 ust. 1 nie stosuje się. \\t\\fNowelizacja z dnia 17 sierpnia 2023 r. wprowadziła możliwość zmiany opisu programu lekowego bez zgody wnioskodawcy. Oznacza to możliwość jednostronnej zmiany warunków refundacji, pomimo tego że zostały one ustalone w prawomocnej decyzji administracyjnej. Budzi to poważne wątpliwości konstytucyjne, ponieważ oznacza przymus dostarczania leków na warunkach innych niż uzgodnione z wnioskodawcą. Postulujemy powrót do dotychczasowych zasad obowiązujących w latach 2012-2023. Zmiana opisu programu lekowego bez zgody wnioskodawcy wywołuje wobec niego te same skutki prawne, co pierwotne ustalenie opisu programu lekowego – w związku z tym powinna podlegać tej samej procedurze. Brakuje \\fuzasadnionych powodów, by umożliwiać dokonywanie takich zmian bez odpowiedniego trybu i gwarancji proceduralnych. Wnioskodawca powinien mieć również możliwość wyjścia z refundacji w razie zmiany opisu programu lekowego wbrew jego woli. \\t\\fUwaga niezasadna Nowelizacja ustawy o refundacji z 2023 r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez potrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. Powyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do potrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju  opcji terapeutycznych i metod  diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew \\fstanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. Wszelki zmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców.  Wprowadzenie obowiązku (zamiast możliwości) przeprowadzenia konsultacji z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji w zakresie zmiany treści programu lekowego jest środkiem nadmiarowym, ponieważ nie każda zmiana musi być zmianą merytoryczną wymagająca angażowania wskazanych ekspertów.  Wnioskodawca posiada możliwość wyjścia z refundacji w razie zmiany opisu programu lekowego poprzez złożenie wniosku o skrócenie okresu obowiązywania decyzji administracyjnej. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 12 projektu dotyczący art. Art. 16a ust. 7 i art. 16aa ust. 2, 3, 3a (nowy)\\tArt. 16a 7. W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia odmawia wydania decyzji o objęciu refundacją ustala opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1.  \\fArt. 16aa 2. W przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, wnioskodawca przedstawia projekt opisu programu lekowego, a w przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a i 3, projekt opisu refundowanych wskazań. W przypadku gdy minister właściwy do spraw zdrowia uzna za niewłaściwą kategorię dostępności refundacyjnej wskazaną we wniosku, o którym mowa w ust. 1, wzywa wnioskodawcę do odpowiedniej zmiany lub uzupełnienia wniosku, o projekty, o których mowa w zdaniu 1, w terminie nie dłuższym niż 30 dni pod rygorem wydania opinii negatywnej. Brak uzupełnienia wniosku powoduje pozostawienie go bez rozpoznania. 3. Do wydania wstępnej opinii nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego. Opinię, o której mowa w ust. 1 i 2, minister właściwy do spraw zdrowia wydaje w drodze postanowienia, na które służy zażalenie. 3a. Termin na rozpoznanie wniosku, o którym mowa w ust. 1 pkt 1, ulega skróceniu o czas trwania postępowania w sprawie wydania wstępnej opinii. \\t\\fCo do art. 16a – W ocenie Związku, skutkiem złożenia wniosku z opisem programu lekowego, którego opis różni się od wstępnej opinii ministra właściwego do spraw zdrowia dotyczącej kategorii dostępności refundacyjnej, nie może być wydanie decyzji o treści zgodnej z opinią wstępną, skoro wnioskodawca wyraźnie inaczej sformułował żądanie. Naruszałoby to zgodnie z którą to wnioskodawca jest gospodarzem swojego żądania. W sytuacji, gdy treść wniosku nie spełnia wymogów prawa materialnego), \\fwłaściwym działaniem jest wydanie decyzji negatywnej, a nie zignorowanie woli wnioskodawcy.     Co do art. 16aa – Rygorem w przypadku braku uzupełnienia wniosku powinna być opinia negatywna, a nie brak rozpoznania wniosku (uchylenie się od merytorycznej oceny). Tym bardziej, że zgodnie z nowoprojektowanym art. 16ab złożenie wniosku o objęcie refundacją niezgodnie z opinią powoduje brak rozpoznania – czyli również brak możliwości merytorycznej kontroli rozstrzygnięcia. Wniosek o wydanie wstępnej opinii powinien podlegać KPA, ponieważ de facto stanowi element procedury refundacyjnej. Opinia powinna być wydawana w drodze postanowienia, na które służy zażalenie. Powinien być określony ustawowo, odpowiednio krótki termin na wydanie opinii (faktycznie wydłuża on ustawowy termin na rozpoznanie wniosku). Z tego też powodu czas na wydanie opinii powinien być odliczony od terminu na rozpatrzenie wniosku o objęcie refundacją.   \\t\\fUwaga częściowo zasadna W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 \\fczerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1. \\n\\tKonsultant Krajowy w dziedzinie reumatologii \\tArt. 1 pkt 12 projektu dotyczący art. 16a ustawy refundacyjne\\fj – dodanie ust. 4\\t\\f„Opis programu lekowego może przewidywać włączenie pacjentów leczonych wcześniej lekami stosowanymi w ramach udzielania świadczeń gwarantowanych, wymieniony w art. 6 ust.1 pkt 4.” \\t\\fPonieważ w chwili obecnej  pacjenci leczeni w ramach „reumatologicznych” programów lekowych  są leczeni sekwencyjnie lekami z kategorią refundacyjną określoną w art. 6 ust. 1 pkt 2 ustawy refundacyjnej, to aby mogli być \\fnadal leczeni sekwencyjnie, po zastosowaniu leku z nowej kategorii refundacyjnej to proponuję dodanie zapisu pozwalającego  na powrót takiego pacjenta do programu lekowego bez konieczności  spełniania kryteriów włączenia do programu lekowego\\t\\fUwaga bezprzedmiotowa Projektodawca odstąpił od wprowadzenia tzw. 4 kategorii refundacyjnej \\n\\tOgólnopolska Federacja Onkologiczna\\tart. 1 pkt 12 projektu odnoszący się do art. 16a. ust.1\\tW przypadku gdy wniosek, o którym mowa w art. 16aa ust. 1, dotyczy kategorii dostępności refundacyjnej(…)mini ster właściwy do spraw zdrowia ustala opisy programów lekowych po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, a w uzasadnionych przypadkach również medycznego towarzystwa naukowego z danej dziedziny medycyny Propozycja nowego zapisu: W przypadku gdy wniosek, o którym mowa w art. 16aa ust. 1, dotyczy kategorii dostępności refundacyjnej(…)mini ster właściwy do spraw zdrowia ustala opisy programów lekowych po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, a w uzasadnionych przypadkach również medycznego towarzystwa naukowego z danej dziedziny medycyny.\\tMinister powinien obligatoryjnie zasięgać opinii medycznych towarzystw naukowych, jako zespołów specjalistów, ekspertów/praktyk ów klinicznych, mających doświadczenie bieżącej pracy terapeutycznej z określoną grupą pacjentów. W przypadku gdy wniosek, o którym mowa w art. 16aa ust. 1, dotyczy kategorii dostępności refundacyjnej(…)minister właściwy do spraw zdrowia ustala opisy programów lekowych po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny oraz medycznego towarzystwa naukowego z danej dziedziny medycyny.\\tUwaga niezasadna W opinii Ministra Zdrowia wystarczające jest ustalanie treści programów leków po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, jak również po konsultacji z Prezesem Agencji. Należy uznać za słuszne pozostawienie do oceny Ministra Zdrowia czy zachodzi konieczność uzyskania opinii medycznego towarzystwa naukowego z danej dziedziny medycyny. \\n\\tOgólnopolska Federacja Onkologiczna\\tart. 1 pkt 12 odnoszący się do art. 16 a, ust 4.\\t Skreślić art.16 a, ust.4.  Opis programu lekowego może przewidywać powołanie przez Prezesa \\fFunduszu zespołu koordynacyjnego dla danego programu lekowego\\t\\fPowoływanie zespołów koordynacyjnych może mieć  uzasadnienie jedynie w przypadku chorób rzadkich. W ch.rz. tylko lekarz/e prowadzący posiada/ją kompetencje w \\fzakresie podejmowania decyzji terapeutycznych. Zapis o Zespołach Koordynacyjnych nie wskazuje ścieżki odwoławczej pacjenta w przypadku negatywnej decyzji ani odpowiedzialności potencjalnego zespołu  za efekt terapeutyczny.\\t\\fUwaga niezasadna Opis programu lekowego może przewidywać powołanie przez Prezesa  Funduszu zespołu koordynacyjnego dla danego programu lekowego. Zespół koordynacyjny może być uwzględniony \\falbo wycofany z programu lekowego zgodnie z wolą Ministra Zdrowia. \\n\\tOgólnopolska Federacja Onkologiczna\\tart. 1 pkt 12 projektu odnoszący się do art. 16a ust. 5 ustawy\\tZmiany opisu programu lekowego dokonuje minister właściwy do spraw zdrowia w wykazie, o którym mowa w art. 37 ust. 1 Nowy przepis powinien zawierać szczegółowo określone zasady i kryteria dokonywania zmian opisów programów lekowych. Powinny być one dokonywane w szczególnych przypadkach (wymagających ścisłego precyzowania).\\tMinister właściwy ds. zdrowia nie powinien mieć arbitralnego wpływu na zmiany opisu programu lekowego. Potencjalny wpływ na brak stabilności decyzji refundacyjnych. \\tUwaga niezasadna Jak pokazała wcześniejsza praktyka, brak możliwości jednostronnej zmiany programu lekowego przez Ministra Zdrowia powodowało, że Wnioskodawcy blokowali niejednokrotnie wejście nowych terapii do refundacji. Nowelizacja ustawy o refundacji z 2023 r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez potrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. Powyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do potrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju opcji terapeutycznych i metod  diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew stanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. \\fWszelki zmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców.   \\n\\tOgólnopolska Federacja Onkologiczna\\tart. 1 pkt 12 projektu odnoszący się do art. 16a ust. 6 ustawy\\tW przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do spraw zdrowia może przeprowadzić konsultacje z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji, a w uzasadnionych przypadkach również medycznym towarzystwem naukowym z danej dziedziny medycyny\\tMinister powinien obligatoryjnie zasięgać opinii medycznych towarzystw naukowych, jako zespołów specjalistów, ekspertów/praktyk ów klinicznych, mających doświadczenie bieżącej pracy terapeutycznej z określoną grupą pacjentów. W przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do spraw zdrowia powinien przeprowadzić konsultacje z konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny, medycznym towarzystwem naukowym z danej dziedziny medycyny oraz Prezesem Agencji.\\tUwaga niezasadna Zbyt wielki kręg podmiotów z którymi MZ ma konsultować treść programu lekowego powoduje wydłużenie czasu procedowania wniosków refundacyjnych Jest kilka możliwości wypowiadania się na temat procedowanych wniosków: -Rada przejrzystości -Po publikacji analizy weryfikacyjnej -Projekt Zdrowia wprowadza też 4 możliwość w czasie negocjacji. W opinii Ministra Zdrowia wystarczające jest ustalanie treści programów leków po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, jak również po konsultacji z Prezesem Agencji. Należy uznać za słuszne pozostawienie do oceny Ministra Zdrowia czy zachodzi konieczność uzyskania opinii medycznego towarzystwa naukowego z danej dziedziny medycyny. \\n\\tPolskie Towarzystwo Reumatologiczne \\tart. 1 pkt 12 projektu odnoszący się do art. 16a ust. 6 ustawy\\tWnioskujemy o zmianę zapisów dotyczących możliwości dokonywania zmian w zapisach programów lekowych przez Ministra Zdrowia.  W art. 16a ust. 6 przyjmuje następujące brzmienie:  „6. W przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do \\fspraw zdrowia przeprowadza konsultacje z konsultantem krajowym, a w przypadku jego braku z konsultantem wojewódzkim z odpowiedniej dziedziny medycyny, oraz medycznym towarzystwem naukowym z danej dziedziny medycyny. W uzasadnionych przypadkach minister właściwy do spraw zdrowia może przeprowadzić konsultacje z Prezesem Agencji.” \\t\\fW przypadku dokonywania zmiany, o której mowa w ust. 5, minister właściwy do spraw zdrowia przeprowadza konsultacje z medycznym towarzystwem naukowym z danej dziedziny medycyny, konsultantem krajowym lub konsultantem wojewódzkim z odpowiedniej dziedziny medycyny oraz Prezesem Agencji.je zmian w programie lekowym, którego obowiązująca treść \\fzawsze powinna być wynikiem wspólnej pracy ekspertów dedykowanego medycznego towarzystwa naukowego i konsultanta krajowego z danej dziedziny medycyny, powinny być także obligatoryjnie konsultowane z medycznym towarzystwem naukowym, a nie tylko konsultantem krajowym.  Konsultacja zmiany opisu programu lekowego tylko z konsultantem wojewódzkim z pominięciem konsultanta krajowego, na co pozwala obecne brzmienie przepisu, nie powinna mieć miejsca. Każda zmiana programu może mieć duży wpływ na życie i zdrowie pacjentów, dlatego powinna być przedmiotem szerokich konsultacji ekspertów z danej dziedziny medycyny, którzy z uwagi na mandat wyborczy reprezentują całe środowisko.\\t\\fUwaga niezasadna Zbyt wielki kręg podmiotów z którymi MZ ma konsultować treść programu lekowego powoduje wydłużenie czasu procedowania wniosków refundacyjnych Jest kilka możliwości wypowiadania się na temat procedowanych wniosków: -Rada przejrzystości -Po publikacji analizy weryfikacyjnej -Projekt Zdrowia wprowadza też 4 możliwość w czasie negocjacji. \\fW opinii Ministra Zdrowia wystarczające jest ustalanie treści programów leków po zasięgnięciu opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, jak również po konsultacji z Prezesem Agencji. Należy uznać za słuszne pozostawienie do oceny Ministra Zdrowia czy zachodzi konieczność uzyskania opinii medycznego towarzystwa naukowego z danej dziedziny medycyny.\\n\\tAlivia - Fundacja Onkologiczna\\tart. 1 pkt 12 projektu odnoszący się do art. 16a ust. 1 i 6 ustawy refundacyjnej\\tWnioskujemy o uwzględnienie przedstawicieli organizacji pacjentów w procesie opiniowania nowych oraz zmian istniejących programów lekowych.\\tZwiększenia udziału przedstawicieli organizacji pacjentów w procesie opiniowania programów lekowych – zarówno na etapie tworzenia nowych, jak i przy wprowadzaniu zmian do programów już istniejących. Obecna propozycja w tym zakresie jest niewystarczająca i nie zapewnia faktycznego wpływu pacjentów na kształt świadczeń, z których korzystają.\\tUwaga niezasadna Zbyt wielki kręg podmiotów z którymi Minister Zdrowia ma konsultować treść programu lekowego powoduje wydłużenie czasu procedowania wniosków refundacyjnych Jest kilka możliwości wypowiadania się na temat procedowanych wniosków: -Rada przejrzystości -Po publikacji analizy weryfikacyjnej -Projekt obwieszczenia Minister Zdrowia wprowadza też 4 możliwość w czasie negocjacji. Ministerstwo Zdrowia apeluje o większą aktywność na obecny etapach umożliwiającą zgłaszanie uwag.\\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 pkt 12 projektu dotyczący art. 16a ust. 6 ustawy refundacyjnej\\tW art. 16a proponujemy dodanie ust. 6 w brzmieniu: \\\"6. W celu zagwarantowania pewności obrotu prawnego, w tym przede wszystkim zgodności instrumentów dzielenia ryzyka ze stanem faktycznym i prawnym stanowiącym podstawę dla ich ustalenia, minister właściwy do spraw zdrowia każdorazowo zawiadomi wnioskodawcę o zakresie i terminie wprowadzenia zmiany opisu programu lekowego, nie później jednak niż 90 dni przed wejściem w życie tej zmiany. W celu dostosowania zawartego instrumentu dzielenia ryzyka do zmiany opisu programu lekowego wnioskodawca składa wniosek, o którym mowa w art. 155 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego.\\\"\\tUprawnienie MZ do dokonywania jednostronnie zmian w opisach programów lekowych w dalszym ciągu budzi obawy wnioskodawców odnośnie możliwości powstania rozdźwięku pomiędzy takim zmienionym opisem a ustaleniami odzwierciedlonymi w instrumencie dzielenia ryzyka. Z tego względu KF AmCham proponuje dodanie nowego ust. 6, którego celem jest zagwarantowanie pewności obrotu prawnego i wprowadzenie procedury informowania wnioskodawców o planowanych zmianach, w połączeniu z umożliwieniem im złożenia wniosku i zmianę instrumentu dzielenia ryzyka na podstawie przepisu art. 155 KPA. \\tUwaga niezasadna Nowelizacja ustawy o refundacji z 2023 r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez potrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. Powyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do potrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju opcji terapeutycznych i metod diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew stanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. Wszelki zmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców. \\n\\tPracodawcy RP\\tArt. 1 pkt 12 projektu dotyczący art. 16a ust. 6-8 ustawy refundacyjnej\\tW art. 16a: proponujemy dodanie nowego ust. 6-8 w brzmieniu: \\\"6. W celu zagwarantowania pewności obrotu prawnego, w tym przede wszystkim zgodności instrumentów dzielenia ryzyka ze stanem faktycznym i prawnym stanowiącym podstawę dla ich ustalenia, w przypadku planowanej zmiany opisu programu lekowego minister właściwy do \\fspraw zdrowia każdorazowo zawiadomi wnioskodawcę o zakresie i terminie wprowadzenia zmiany opisu programu lekowego.  7. W celu dostosowania zawartego instrumentu dzielenia ryzyka do zmiany opisu programu lekowego wnioskodawca może złożyć wniosek, o którym mowa w art. 155 ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego. 8. Minister właściwy do spraw zdrowia rozpatruje wniosek, o którym mowa w ust. 7 w terminie 30 dni.\\\"\\t\\fUprawnienie MZ do dokonywania jednostronnie zmian w opisach programów lekowych w dalszym ciągu budzi obawy wnioskodawców odnośnie możliwości powstania rozdźwięku pomiędzy takim zmienionym opisem a ustaleniami odzwierciedlonymi w instrumencie dzielenia ryzyka. Z tego względu Pracodawcy RP proponują \\fdodanie nowych ust. 6-8, którego celem jest zagwarantowanie pewności obrotu prawnego i wprowadzenie procedury informowania wnioskodawców o planowanych zmianach, w połączeniu z umożliwieniem im złożenia wniosku i zmianę instrumentu dzielenia ryzyka na podstawie przepisu art. 155 KPA. \\t\\fUwaga niezasadna Nowelizacja ustawy o refundacji z 2023 r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez potrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. \\fPowyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do potrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju opcji terapeutycznych i metod diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew stanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. Wszelki zmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców. \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 13 dotyczący art. 16aa ustawy refundacyjnej\\tArt. 16aa. 1. Wnioskodawca przed złożeniem wniosku, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu, zwraca się za pomocą Systemu Obsługi List Refundacyjnych, o którym mowa w art. 30a ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia, zwanego dalej „SOLR”, do ministra właściwego do spraw zdrowia o wydanie wstępnej opinii dotyczącej kategorii dostępności refundacyjnej, wskazując we wniosku propozycję kategorii dostępności refundacyjnej. 1a. Złożenie wniosku, o którym mowa w ust. 1, może mieć miejsce po wydaniu przez Komitet ds. Produktów Leczniczych Stosowanych u Ludzi, o którym mowa w \\frozporządzeniu (WE) nr 726/2004 Parlamentu Europejskiego i Rady z dnia 31 marca 2004 r. ustanawiające unijne procedury wydawania pozwoleń dla produktów leczniczych stosowanych u ludzi i nadzoru nad nimi oraz ustanawiające Europejską Agencję Leków działający przy Europejskiej Agencji Leków, opinii w postępowaniu w sprawie wydania pozwolenia na dopuszczenie do obrotu. 2. W przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, wnioskodawca przedstawia projekt opisu programu lekowego, a w przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a i 3, projekt opisu refundowanych wskazań. W przypadku gdy minister właściwy do spraw zdrowia uzna za niewłaściwą kategorię dostępności refundacyjnej wskazaną we wniosku, o którym mowa w ust. 1, wzywa wnioskodawcę do uzupełnienia wniosku, o projekty, o których mowa w zdaniu 1, w terminie 30 dni. Brak uzupełnienia wniosku powoduje pozostawienie go bez rozpoznania. 2a. W ramach procedury wydania wstępnej opinii minister właściwy do spraw zdrowia oraz wnioskodawca mogą omawiać także zakres analizy weryfikacyjnej Agencji. 3. Do wydania wstępnej opinii nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego. 3a. Minister właściwy do spraw zdrowia oprócz wydania wstępnej opinii sporządza także protokół z przebiegu procedury jej \\fwydania, w tym spotkań z wnioskodawcą, oraz przekazuje go wnioskodawcy. 4. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu złożony w kategorii dostępności refundacyjnej innej niż wskazana przez ministra właściwego do spraw zdrowia we wstępnej opinii albo bez jej wydania, pozostawia się bez rozpoznania. Procedura wydania wstępnej opinii trwa nie dłużej niż 45 dni. W przypadku leku w terapii skojarzonej procedura wydania wstępnej opinii trwa nie dłużej niż 90 dni. 5. Złożenie wniosku o wydanie wstępnej opinii podlega opłacie w wysokości 3000 zł. 6. W przypadku złożenia wniosku o objęcie refundacją i ustalenie ceny zbytu netto zgodnie z wstępną opinią ministra właściwego do spraw zdrowia, opłata o której mowa w ust. 5, zostaje zaliczona na poczet opłaty za wniesienie wniosku, o której mowa w art. 32. 7. Jeżeli wstępna opinia miałaby dotyczyć leku stosowanego w ramach terapii skojarzonej, minister właściwy do spraw zdrowia zaprasza do procedury wydania wstępnej opinii także wnioskodawcę dla innego leku stosowanego w ramach takiej terapii skojarzonej. 8. W ramach procedury wydania opinii, minister właściwy do spraw zdrowia może włączyć do udziału przedstawicieli Funduszu oraz Agencji.\\t\\fINFARMA wspiera rozwiązanie w postaci prekonsultacji.  Zgadzamy się, że takie rozwiązanie możne znacząco przyspieszyć właściwe postępowanie refundacyjne poprzez omówienie niektórych rozwiązań wcześniej (co dodatkowo podkreślamy propozycją, aby takie konsultacje mogłyby się rozpocząć już po wydaniu opinii przez CHMP). Nie możemy jednak zgodzić się na wiążący charakter takich wstępnych opinii (połączony z brakiem możliwości odwołania się od nich z uwagi na wyłączenie przepisów KPA). Ideą prekonsultacji powinna być możliwość prowadzenia dyskusji pomiędzy wnioskodawcą a Ministerstwem Zdrowia, natomiast nie powinny one narzucać jedynego \\fmożliwego rozwiązania. Rola wnioskodawcy nie powinna się ograniczać wyłącznie do złożenia propozycji i późniejszego uzupełnienia wniosku zgodnie z oczekiwaniami MZ. Proces prekonsultacji powinien obejmować aktywną dyskusję pomiędzy wnioskodawcą a MZ, z  ewentualnym udziałem ekspertów klinicznych, towarzystw naukowych itp. z danej dziedziny. Zaproponowane przez MZ rozwiązanie byłoby wprost sprzeczne z Dyrektywą Przejrzystości, która w art. 6 ust. 2 bezpośrednio wskazuje, że „2. Każda decyzja odmawiająca włączenia [a taką w istocie byłaby negatywna wstępna opinia – przyp. autora] produktu leczniczego w wykazie produktów objętych krajowym systemem ubezpieczeń zdrowotnych musi zawierać uzasadnienie oparte na obiektywnych kryteriach, które mogą być sprawdzone, a w razie konieczności obejmować opinie lub zalecenia ekspertów, które stanowiły podstawę ich przyjęcia. Ponadto wnioskodawca zostanie powiadomiony o przysługujących mu środkach odwoławczych na mocy obowiązujących przepisów prawnych oraz o terminach, w jakich można je zastosować.”. W rezultacie brak możliwości odwołania się od tej decyzji byłby jednoznacznym naruszeniem Dyrektywy Przejrzystości (skoro prekonsultacje obejmują dwa z elementów istotnych dla refundacji tj. kategorię dostępności oraz wskazania, to w istocie byłyby integralną częścią \\fpostępowania refundacyjnego w rozumieniu art. 6 ww. dyrektywy). Wobec tego proponujemy, żeby prekonsultacje miały charakter właściwy dla ich istoty – jaką jest dyskusja, przygotowanie się do właściwego postępowania i w rezultacie miały niewiążący charakter.  Jednocześnie – pod warunkiem wprowadzenia braku wiążącego charakteru wstępnej opinii - INFARMA zgadza się na pozostawienie obligatoryjnego charakteru takich prekonsultacji oraz wyłączenia stosowania przepisów KPA (co jest zasadne, skoro nie mają one wiążącego charakteru, nie wywołują skutków prawych dla wnioskodawcy – nie ma potrzeby odwoływania się od nich). Proponuje się także rozszerzenie zakresu prekonsultacji także do zakresu analizy weryfikacyjnej Agencji (np. kwestii dot. PICO – które jest podstawą do przygotowania analiz HTA, wobec czego jest kluczowe dla całego procesu) oraz doprecyzowania czasu trwania takich prekonsultacji. Z uwagi na fakt, że prekonsultacje obejmowałyby także spotkania z Ministrem Zdrowia, zasadnym byłoby aby oprócz samej opinii Minister przygotował i przekazał wnioskodawcy także protokół z procedury, w tym spotkań z wnioskodawcą. Ważnym jest również, aby określić w jakim terminie miałyby się odbyć prekonsultacje (szczególnie, że – zgodnie z propozycją INFARMA – nie wchodzi w \\ften zakres już ustalanie opisu programu lekowego oraz opisów wskazań). Jednocześnie proponuje się, aby w ramach tych prekonsultacji – w przypadku terapii skojarzonych – można było doprosić wnioskodawcę dla innego leku wchodzącego w ten schemat leczenia. Dzięki temu już na tym etapie można byłoby ustalić czy są szanse na złożenie wniosku przez inny lek w ramach terapii skojarzonej, co ma istotny wpływ z perspektywy planowania wniosku refundacyjnego oraz ponoszonych w związku z tym kosztów organizacyjnych i finansowych. Zaproponowane rozwiązanie pozostaje także zgodne z przepisami prawa konkurencji. O ile przepisy te i tak znajdą zastosowanie do prowadzonych rozmów, to 1) nie obejmują one kwestii sensytywnych z tej perspektywy tj. odpłatności, ceny zbytu netto czy RSSów (zob. ust. 1 i 2a) oraz 2) wprowadza się protokół z prekonsultacji, który będzie wykazywał (np. w przypadku kontroli Prezesa UOKiK) zakres rozmowy (ust. 3a).  Warto również, aby Minister Zdrowia mógł zaprosić w ramach prekonsultacji także przedstawicieli NFZ czy Agencji do dyskusji z wnioskodawcą (co może być istotne np. w kwestii omawiania PICO).\\t\\fUwaga częściowo niezasadna   Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy refundacyjnej, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku refundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra właściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do \\ftreści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez strony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści następowała dopiero po wpłynięciu do ministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem trwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego świadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister Zdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem \\fwydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu prowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1.  Dodatkowo należy podkreślić, że art. 16a ust. 1 wskazuje procedurę ustalania opisów programów lekowych, wskazuje konieczność zasięgnięcia opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, konsultacji z Prezesem Agencji, przedstawienia projektu programu lekowego Wnioskodawcy jak również uzyskanie jego stanowiska. \\n\\tPOLSKA FEDERACJA PRODUCENTÓW ŻYWNOŚCI ZWIĄZEK PRACODAWCÓW\\tArt. 1 pkt 12 i 13 dotyczące się art. 16a i 16aa ustawy refundacyjnej\\tProjektowane przepisy nakładają na wnioskodawców, których produkty nie posiadają refundowanego odpowiednika w danym wskazaniu obowiązek wystąpienia za pośrednictwem SOLR do Ministra Zdrowia z wnioskiem o wydanie wstępnej \\fopinii dotyczącej kategorii dostępności refundacyjnej, wskazując we wniosku propozycję kategorii dostępności refundacyjnej. Złożenie wniosku podlegać ma opłacie w kwocie 3000 zł. Wniosek refundacyjny w odniesieniu do produktu, który nie ma odpowiednika refundowanego w danym wskazaniu złożony w kategorii dostępności refundacyjnej innej niż wskazana przez Ministra Zdrowia we wstępnej opinii albo bez jej wydania, pozostawia się bez rozpoznania. W aktualnym stanie prawnym wnioskodawcy nie są zobowiązani do tego, aby występować do MZ z wnioskiem o określenie kategorii dostępności, w której miałaby nastąpić refundacja produktu. Mogę więc sami zaproponować kategorię dostępności, w ramach której produkt może zostać objęty refundacją, zaś sama propozycja kategorii dostępności może być dyskutowany w trakcie negocjacji z Komisją Ekonomiczną. Po wprowadzeniu projektowanej regulacji, wystąpienie z takim wnioskiem stanie się obligatoryjne. PFPŻ ZP sprzeciwia się wprowadzeniu takiej regulacji i postuluje jej wykreślenie z Projektu.\\t\\tUwaga niezasadna Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy \\frefundacyjnej, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku refundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra właściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do treści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez strony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści następowała dopiero po wpłynięciu do ministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem \\ftrwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego świadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister Zdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem wydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu prowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 \\fczerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1. \\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 pkt 13 dotyczący art. 16aa ustawy refundacyjnej\\tArt. 16aa proponujemy nadanie następującego brzmienia: 1. Wnioskodawca przed złożeniem wniosku, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego lub produktu leczniczego, dla którego została wydana pozytywna opinia, o której mowa w art. 5 ust. 2 Rozporządzenia (WE) nr 726/2004 z dnia 31 marca 2004 r. ustanawiającego unijne procedury wydawania pozwoleń dla produktów leczniczych stosowanych u ludzi i nadzoru nad nimi oraz ustanawiające Europejską Agencję Leków, który nie ma odpowiednika refundowanego w danym wskazaniu, może zwrócićaca się za pomocą Systemu Obsługi List Refundacyjnych, o którym mowa w art. 30a ustawy z dnia 28 kwietnia 2011 r. o \\fsystemie informacji w ochronie zdrowia, zwanego dalej „SOLR”, do ministra właściwego do spraw zdrowia o wydanie wstępnej opinii dotyczącej kategorii dostępności refundacyjnej, wskazując we wniosku propozycję kategorii dostępności refundacyjnej.  2. W przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, wnioskodawca przedstawia projekt opisu programu lekowego, a w przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a i 3, projekt opisu refundowanych wskazań. W przypadku gdy minister właściwy do spraw zdrowia uzna za niewłaściwą kategorię dostępności refundacyjnej wskazaną we wniosku, o którym mowa w ust. 1, wzywa wnioskodawcę do uzupełnienia wniosku, o projekty, o których mowa w zdaniu 1, w terminie 30 dni. Brak uzupełnienia wniosku powoduje pozostawienie go bez rozpoznania.  3. Do wydania wstępnej opinii nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego.  4. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu złożony w kategorii dostępności \\frefundacyjnej innej niż wskazana przez ministra właściwego do spraw zdrowia we wstępnej opinii albo bez jej wydania, pozostawia się bez rozpoznania.  5. Złożenie wniosku o wydanie wstępnej opinii podlega opłacie w wysokości 3000 zł.  6. W przypadku złożenia wniosku o objęcie refundacją i ustalenie ceny zbytu netto zgodnie z wstępną opinią ministra właściwego do spraw zdrowia, opłata o której mowa w ust. 5, zostaje zaliczona na poczet opłaty za wniesienie wniosku, o której mowa w art. 32. 7. Minister Zdrowia przekazuje Agencji opinię, o której mowa w ust. 1. 8. Minister właściwy do spraw zdrowia wydaje opinię, o której mowa w ust. 1 w terminie 60 dni.  9. W przypadku niewydania opinii, o której mowa w ust. 1 w terminie wskazanym w ust. 7 wnioskodawca może złożyć wniosek o którym mowa w art. 24 ust. 1 pkt 1 dla kategorii dostępności wskazanej we wniosku, o którym mowa w ust. 1.\\t\\fWprowadzenie instytucji wydawania wstępnej opinii dotyczącej kategorii dostępności refundacyjnej wydaje się koncepcyjnie słusznym rozwiązaniem, jednakże w ocenie KF AmCham wymaga wprowadzenia kilku istotnych modyfikacji. Po pierwsze, w ocenie KF AmCham nie ma potrzeby, aby rozwiązanie to było obowiązkowe.  Po drugie, nie widzimy uzasadnienia dla wykluczenia z katalogu leków objętych prekonsultacjami leków aptecznych – tak samo jak kategoria dostępności aptecznej może okazać się właściwa dla wniosku złożonego dla leku dostępnego w programie lekowym lub tzw. czwartej kategorii dostępności, tak sytuacja może \\fokazać się odwrotna. Istotnym jest więc zachowanie tutaj pełnej elastyczności. Ponadto, wydaje się, że rzeczywistą wartością wstępnej opinii byłaby możliwość uzyskania jej na odpowiednio wczesnym etapie, nawet jeszcze przed rejestracją produktu– stąd propozycja rozszerzenia katalogu na leki, które uzyskały pozytywną opinię CHMP i oczekują na wydanie pozwolenia na dopuszczenie do obrotu.  Ostatnią propozycją jest wprowadzenie maksymalnego terminu 60 dni na wydanie opinii. Wyłączenie stosowania przepisów KPA będą miały także ten skutek, że brak będzie ustawowych terminów na załatwienie sprawy. Stąd też propozycja dodania terminu. Powyższe zmiany mają na celu umożliwienie uzgodnienia z Ministerstwem Zdrowia docelowej populacji i prawidłowej kategorii dostępności refundacyjnej jeszcze przed zarejestrowaniem leku, tak aby możliwe było jak najszybsze rozpoczęcie przygotowywania analiz HTA (których opracowanie jest jednym z najbardziej czasochłonnych etapów przygotowawczych do złożenia wniosku refundacyjnego). Jest to kluczowe dla jak najszybszego złożenia wniosku refundacyjnego już po jego rejestracji. Bez umożliwienia odbycia prekonsultacji przed rejestracją leku, określenia ich maksymalnego czasu trwania oraz zapewnienia wiążącego charakteru \\fpoczynionych ustaleń może paradoksalnie dojść do odroczenia momentu złożenia wniosku refundacyjnego.\\t\\fUwaga niezasadna  Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy refundacyjnej, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku refundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra właściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do treści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez \\fstrony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści następowała dopiero po wpłynięciu do ministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem trwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego świadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister Zdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem wydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu \\fprowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1.  Dodatkowo należy podkreślić, że art. 16a ust. 1 wskazuje procedurę ustalania \\fopisów programów lekowych, wskazuje konieczność zasięgnięcia opinii konsultanta krajowego lub konsultanta wojewódzkiego z odpowiedniej dziedziny medycyny, konsultacji z Prezesem Agencji, przedstawienia projektu programu lekowego Wnioskodawcy jak również uzyskanie jego stanowiska.\\n\\tPracodawcy RP\\tArt. 1 pkt 13 dotyczący art. 16aa ustawy refundacyjnej\\tW odniesieniu do art. 16aa proponujemy następujące zmiany: rezygnację z obowiązkowości tego rozwiązania albo wiążącego charakteru opinii wstępnej dotyczącej kategorii dostępności (art. 16aa ust. 4) rozszerzenie katalogu produktów objętych obowiązkiem uzyskania wstępnej opinii dotyczącej kategorii dostępności refundacyjnej o produkty lecznicze, które uzyskały pozytywną opinię Komitetu ds. Produktów Leczniczych Stosowanych u Ludzi; wprowadzenie możliwości konsultacji zakresu PICO; wprowadzenie możliwości uczestniczenia w procesie przedstawicieli AOTMiT i NFZ; wprowadzenie terminu 60 dni na wydanie opinii. \\tWprowadzenie instytucji wydawania wstępnej opinii dotyczącej kategorii dostępności refundacyjnej wydaje się koncepcyjnie słusznym rozwiązaniem, jednakże w ocenie Pracodawców RP wymaga wprowadzenia kilku istotnych modyfikacji. W ocenie Pracodawców RP rozwiązanie to nie powinno być obowiązkowe albo, alternatywnie, opinia nie powinna mieć wiążącego charakteru.  W naszej ocenie prekonsultacje powinny służyć dyskusji i zasięgnięciu opinii, nie zaś wskazaniu jedynego właściwego rozwiązania. Ponadto, w art. 16aa ust. 1 MZ wskazuje, że wniosek złożony w SOLR będzie dotyczył „wydania wstępnej opinii dotyczącej kategorii dostępności”, co również wskazuje na niewiążący charakter tego procesu i stoi w sprzeczności z przepisami proponowanymi w art. 16aa ust. 4. W przypadku wiążącego charakteru prekonsultacji, określona przez MZ treść programu lekowego czy opis refundowanych wskazań w AOS i \\fchemioterapii, które wnioskodawca będzie obowiązany zawrzeć we wniosku o objęcie refundacją, będzie bezpośrednio mieć przełożenie na analizy HTA, które wnioskodawca jest obowiązany przedstawić. Tym samym, brak możliwości realnego wpływu podmiotu odpowiedzialnego na docelowe wskazanie (art. 16a ust. 3, 7 i 8) może prowadzić do sytuacji, w której wnioskodawca może nie dysponować danymi klinicznymi we wskazaniu określonym przez MZ. Tymczasem to na nim spoczywa obowiązek przedstawienia analiz zgodnych z minimalnymi wymaganiami dla populacji określonej we wniosku o objęcie refundacją.  Wydaje się także, że rzeczywistą wartością wstępnej opinii byłaby możliwość uzyskania jej na odpowiednio wczesnym etapie – stąd propozycja rozszerzenia katalogu na leki, które uzyskały pozytywną opinię CHMP i oczekują na wydanie pozwolenia na dopuszczenie do obrotu. Pracodawcy RP pragną zwrócić uwagę, że procedowany równolegle projekt nowelizacji UoR wprowadza regulacje dotyczące unijnej oceny klinicznej. W konsekwencji, należy przeanalizować jak wyglądać będzie relacja proponowanych w Projekcie rozwiązań, a zwłaszcza instytucja prekonsultacji, z procesem wspólnej oceny klinicznej. \\fPrzykładowo, w sytuacji, gdy w trakcie prekonsultacji omawiane będzie wskazanie refundacyjne warto, aby proces uwzględniał ustalenia dotyczące PICO i aby mógł uczestniczyć w nich przedstawiciel AOTMiT. Ustalenia z prekonsultacji nie powinny stać w sprzeczności z późniejszym podejściem AOTMiT do oceny wniosku i konieczności zmiany analiz HTA. Zasadne wydaje się również uwzględnienie w procesie prekonsultacji przedstawiciela NFZ (np. w zakresie ustaleń dotyczących treści programu lekowego). Ostatnią propozycją jest wprowadzenie maksymalnego terminu 60 dni na wydanie opinii. Wyłączenie stosowania przepisów KPA będą miały także ten skutek, że brak będzie ustawowych terminów na załatwienie sprawy. Stąd też propozycja dodania terminu.\\t\\fUwaga niezasadna W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1. Należy wskazać, że zgodnie z zaprojektowanym przepisem opis programu lekowego podlega konsultacji z \\fPrezesem Agencji w zakresie zgodności z Charakterystyką Produktu Leczniczego oraz wytycznymi klinicznymi odnoszącymi się do technologii medycznej stosowanej w danym programie lekowym. Minister właściwy do spraw zdrowia przedstawia opis programu lekowego do zaopiniowania wnioskodawcy po przeprowadzonej konsultacji z Prezesem Agencji. Etap prekonsultacji ma być obligatoryjny, aby przyspieszyć procedowanie wniosków refundacyjnych. Przepis nie ma na celu przeniesienie HTA na etap prekonsultacji, a wyeliminowanie problemów administracyjnych i ukierunkowanie wnioskodawców, aby nie składali wniosków w zawężonych wskazaniach.\\n\\tIzba Gospodarcza „FARMACJA POLSKA”\\tArt. 1 pkt 13 projektu w zakresie dodawanego art. 16aa\\tproponujemy wykreślenie z projektu art. 16aa ust. 4 ustawy o refundacji. Nawet bez przymusu zastosowania się do opinii Ministra Zdrowia wydanej w prekonsultacjach wnioskodawcy będą co do zasady wnioskować o refundację zgodnie z opinią, wiedząc, że taki wniosek będzie mieć największe szanse powodzenia. Jednakże muszą mieć także możliwość skutecznego złożenia wniosku w innej kategorii dostępności refundacyjnej niż wskazana w opinii Ministra Zdrowia, po to, by móc w \\fpostępowaniu refundacyjnym zakwestionować przyjęte w opinii rozstrzygnięcie co do właściwej kategorii dostępności, które nie będzie mogło być zaskarżone w ramach prekonsultacji, z uwagi na brak zastosowania przepisów KPA do prekonsultacji.\\t\\fArt. 16aa – procedura prekonsultacji Ideę prekonsultacji przed złożeniem wniosku o refundację dla leku, śsspż lub wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu, co do zasady uznajemy za słuszną. Możliwość wcześniejszego skonsultowania z Ministerstwem Zdrowia prawidłowości dokonanego przez wnioskodawcę wyboru kategorii dostępności refundacyjnej z pewnością \\fzmniejszy ryzyko błędów przy składaniu wniosków i tym samym kosztów  i opóźnień związanych z koniecznością ponownego przygotowywania dokumentacji do wniosku. Jednakże sposób uregulowania prekonsultacji przed złożeniem wniosku o refundację  w projekcie nowelizacji Ustawy o refundacji budzi nasze poważne wątpliwości. Przede wszystkim, jeżeli wynik prekonsultacji miałby być dla wnioskodawcy wiążący, to musi on podlegać zaskarżeniu w trybie przepisów kodeksu postępowania administracyjnego; jeżeli zaś stosowanie przepisów KPA do prekonsultacji ma być wyłączone, wówczas opinia Ministra Zdrowia w sprawie właściwej kategorii dostępności nie może być dla strony wiążąca.  Projekt nowelizacji w obecnej wersji w ar. 16aa ust. 3 ustawy stanowi, że do wydania wstępnej opinii nie stosuje się przepisów kodeksu postępowania administracyjnego; zaś w art. 16aa ust. 4 ustawy zastrzega, że wniosek o refundację złożony w kategorii dostępności innej niż wskazana w opinii Ministra Zdrowia lub bez jej wydania będzie pozostawiony bez rozpoznania. Tym samym istotne dla wnioskodawcy rozstrzygnięcie, dotyczące kategorii dostępności refundacyjnej, staje się niezaskarżalne, co stanowi istotne naruszenie praw wnioskodawcy jako strony postępowania refundacyjnego, a jednocześnie przeczy zasadom \\ftransparentnego procesu refundacyjnego.\\t\\fUwaga niezasadna Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy refundacyjnej, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku refundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra \\fwłaściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do treści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez strony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści następowała dopiero po wpłynięciu do ministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem trwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego świadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister \\fZdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem wydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu prowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. \\f2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1.  \\n\\tPolskie Towarzystwo Farmakoekonomiczne\\tArt. 1 pkt 13 projektu odnoszący się do dadawanego art. 16aa\\tPrzepisy dotyczące prekonsultacji refundacyjnych (Art. 16aa UR) powinny zostać zmodyfikowane, aby umożliwić najbardziej efektywny dialog między wnioskodawcami a Ministerstwem Zdrowia w celu wypracowania optymalnej decyzji refundacyjnej.  \\tPTFE wspiera rozwiązanie w postaci prekonsultacji i zgadza się, że takie rozwiązanie możne znacząco przyspieszyć właściwe postępowanie refundacyjne poprzez omówienie niektórych rozwiązań wcześniej. Niemniej jednak wiążący charakter takich wstępnych opinii (połączony z brakiem możliwości odwołania się od nich z uwagi na wyłączenie przepisów KPA) może nie spełniać idei „early advice”. Założeniem prekonsultacji powinna być możliwość prowadzenia dyskusji pomiędzy wnioskodawcą a Ministerstwem Zdrowia, aby wypracować optymalną propozycję dla obu stron. Ustalenie, już na tak wczesnym etapie, sztywnych i niezmienialnych warunków refundacji tj. opisu programu lekowego lub opisu refundowanych wskazań, pod groźbą ich nierozpatrywania jeśli będą inne we wniosku refundacyjnym niż te ustalone w prekonsultacjach nie zapewniają konstruktywnego dialogu. Takie rozwiązanie nie uwzględnia chociażby zmiany zapisów w ChPL czy wytycznych, \\fktóre mogą zajść po wydaniu decyzji dla wniosku prekonsultacyjnego, a przed złożeniem wniosku o objęcie refundacją. Ustalenie sztywnego opisu programu lekowego, czy wskazań refundacyjnych, kiedy te mogą się jeszcze zmienić po prekonsultacjach może okazać się nieefektywne.  Proces prekonsultacji powinien obejmować aktywną dyskusję pomiędzy wnioskodawcą a MZ z ewentualnym udziałem ekspertów klinicznych i towarzystw naukowych z danej dziedziny. • Co więcej, przepisy dotyczące „wiążących ustaleń” budzą wątpliwości co do możliwości wdrożenia JCA (Joint Clinical Assessment) w Polsce. Jakiekolwiek odstępstwo pomiędzy prekonsultacjami a JCA albo zablokuje proces albo go znacznie opóźni. Prekonsultacje powinny mieć charakter dialogu i przygotowania do właściwego postępowania, a nie jednostronnego narzucania sztywnych rozwiązań. • Dlatego proponujemy, aby prekonsultacje miały charakter właściwy dla konsultacji, to jest aby stanowiły przygotowanie się do właściwego postępowania i nie miały charakteru wiążącego pod groźbą nierozpatrywania takich wniosków. \\f• Co więcej, nie określono żadnych ram czasowych dla tego procesu. Decyzja Ministerstwa Zdrowia, podejmowana przed rozpoczęciem sformalizowanej procedury i przed oceną AOTMiT, będzie etapem, w którym decyzja będzie wiążąca i nie będzie możliwości odwołania się od niej.\\t\\fUwaga niezasadna Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy o  refundacyji, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku refundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra właściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do treści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez strony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści \\fnastępowała dopiero po wpłynięciu do ministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem trwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego świadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister Zdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem wydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu prowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma \\fodpowiednika refundowanego w danym wskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma brzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1. \\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 13 projektu odnoszący się do dodawanego art. 16aa\\tWnioskujemy o zmianę zapisów art. 16aa ustawy refundacyjnej.   Mając na uwadze nierówne traktowanie stron w procesie wydawania wstępnej opinii proponujemy następujące brzmienie zapisów art. 16aa:  Art. 16aa otrzymuje brzmienie:  „1. Wnioskodawca przed złożeniem wniosku, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu, zwraca się za pomocą Systemu Obsługi List Refundacyjnych, o którym mowa w art. 30a ustawy z dnia 28 kwietnia 2011 r. o systemie informacji w ochronie zdrowia, zwanego dalej „SOLR”, do ministra właściwego do spraw zdrowia o wydanie wstępnej opinii dotyczącej kategorii dostępności refundacyjnej, wskazując we wniosku propozycję kategorii dostępności refundacyjnej. 2. Minister właściwy do spraw zdrowia wydaje wstępną opinie w terminie 30 dni od dnia złożenia wniosku. Brak wydania opinii uznaje się za akceptację wniosku. 3. W przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2, wnioskodawca przedstawia projekt opisu programu lekowego, a w przypadku kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a i 3, projekt opisu refundowanych wskazań. W przypadku gdy minister właściwy do spraw zdrowia uzna za niewłaściwą kategorię dostępności refundacyjnej wskazaną we wniosku, o którym mowa w ust. 1, wzywa wnioskodawcę do uzupełnienia wniosku, o projekty, o których mowa w zdaniu 1, w \\fterminie 30 dni. Brak uzupełnienia wniosku powoduje pozostawienie go bez rozpoznania. 4. Wstępna opinia dotyczącą kategorii dostępności refundacyjnej wydawana przez ministra właściwego do spraw zdrowia jest ważna przez 1 rok licząc od dnia jej sporządzenia. 5. Do wydania wstępnej opinii nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r.  – Kodeks postepowania administracyjnego. 6. Od wydanej przez ministra właściwego do spraw zdrowia wstępnej opinii dotyczącej kategorii dostępności refundacyjnej wnioskodawcy przysługuje wniosek o ponowne rozpatrzenie sprawy w terminie 14 dni od dnia umieszczenia przedmiotowej opinii w SOLR. 7. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu złożony w kategorii dostępności refundacyjnej innej niż wskazana przez ministra właściwego do spraw zdrowia we wstępnej opinii albo bez jej wydania, pozostawia się bez rozpoznania. 8. Złożenie wniosku o wydanie wstępnej opinii podlega opłacie w wysokości 3000 zł. 9. W przypadku złożenia wniosku o objęcie refundacją i ustalenie ceny zbytu netto zgodnie z wstępną opinią ministra \\fwłaściwego do spraw zdrowia, opłata o której mowa w ust. 5, zostaje zaliczona na poczet opłaty za wniesienie wniosku, o której mowa w art. 32.”\\t\\fArt. 16 aa dotyczy wydania przez ministra właściwego do spraw zdrowia wstępnej opinii dotyczącej kategorii dostępności refundacyjnej.  Opinia ta jest bezterminowa, wnioskodawca nie może się od niej odwołać. Minister właściwy do spraw zdrowia, ze względu na wyłączenie \\fprzepisów KPA, nie jest również zobowiązany do rozpatrywania wniosku w określonym terminie (co może rodzić sytuacje pozostawienia wniosków bez odpowiedzi w tzw. „zamrażarce”, co paraliżowałoby dalszy proces refundacyjny).   Art. 16aa w zaproponowanym przez nas brzmieniu pozwala na odwołanie się od wstępnej opinii dotyczącej kategorii dostępności refundacyjnej wydanej przez ministra właściwego do spraw zdrowia oraz ustala jej terminowość, co ma zasadnicze znaczenie zarówno z punktu widzenia wnioskodawcy, jak i przedstawicieli ministerstwa zdrowia, dla których wstępna opinia była wiążąca bezterminowo. \\t\\fUwaga częściowo zasadna Powodem zaprojektowania przepisów dotyczących prekonsultacji były postępowania refundacyjne w których występowała nieadekwatność analiz, o których mowa w art. 25 pkt 14 ustawy refundacyjnej, w związku z faktem ustalania treści programu lekowego przez Ministra Zdrowia dopiero po złożeniu wniosku o objęcie leku \\frefundacją. Wprowadzona zmiana polega na obowiązku nałożonym na wnioskodawcę w zakresie zwrócenia się o wydanie opinii wstępnej przez ministra właściwego do spraw zdrowia przed złożeniem właściwego wniosku o objęcie refundacją i ustalenie ceny zbytu netto. Ustawa refundacyjna w brzmieniu sprzed dnia 1 listopada 2023 r. zawierała regulację umożliwiającą wnioskodawcy zasięgnięcie opinii wstępnej organu co do treści proponowanego programu lekowego, tj. art. 31 ust. 12, jednak nie był on powszechnie wykorzystywany przez strony postępowania i dotyczył on tylko jednej kategorii dostępności refundacyjnej. W związku z powyższym weryfikacja przez organ zasadności wnioskowanej przez stronę kategorii dostępności refundacyjnej, zakresu wskazania, a w przypadku kategorii dostępności - program lekowy, jego treści następowała dopiero po wpłynięciu do ministra właściwego do spraw zdrowia wniosku o objęcie refundacją i ustalenie ceny. W trakcie trwania takiego postępowania zdarzało się, iż minister właściwy do spraw zdrowia z uzasadnionej przyczyny, w tym z uwagi na dostępność do świadczeń czy dbałość o dyscyplinę finansów publicznych, odmawiał dalszego procedowania postepowania w zakresie wnioskowanym przez stronę lub doprowadzenie do ustalenia rozwiązań kompromisowych było związane z  istotnym wydłużeniem trwania postępowania administracyjnego, co odbywało się ze szkodą zarówno dla świadczeniobiorców oczekujących na udostępnienie danego \\fświadczenia gwarantowanego jak i przedsiębiorców oraz rzutowało na kwestie dotrzymania ustawowych terminów procedowania. Jeżeli Minister Zdrowia uznaje, że jest zainteresowany inną treścią programu lekowego, to przedłożone wraz z wnioskiem refundacyjnym analizy stają się nieaktualne. Konieczność uzupełniania lub aktualizowania przedmiotowych analiz wiąże się ze zwiększeniem wydatków wnioskodawcy ponoszonych na ich przygotowanie, jak również wpływa na przedłużanie czasu prowadzenia postępowań refundacyjnych. Proponowana zmiana obejmująca dodanie art. 16aa wprowadza obligatoryjne wstępne konsultacje przed złożeniem wniosku o objęcie refundacją, leku, środka spożywczego specjalnego przeznaczenia żywieniowego albo wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu. W ramach konsultacji opiniowaniu ministra właściwego do spraw zdrowia będzie podlegać kategoria dostępności refundacyjnej oraz zakres wnioskowanego świadczenia rozumiany w przypadku kategorii dostępności w programie lekowym jako jego treść. Analizując uwagi zgłaszane w ramach konsultacji i opiniowania Minister Zdrowia uznał zasadność uwag dotyczących prekonsultacji i wprowadza zmiany w projekcie polegające stosowaniu przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego do wydawania opinii wstępnej, roczny termin ważności takiej opinii. Dodatkowo art. 16a ust. 7 otrzyma \\fbrzmienie: W przypadku złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 2 pkt 2, z opisem programu lekowego innym niż przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1, minister właściwy do spraw zdrowia może ustalić opis programu lekowego przedstawiony w opinii wstępnej, o której mowa w art. 16aa ust. 1. \\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\tArt. 1 pkt 13 projektu w zakresie dodawanego art. 16aa ust. 3\\tWykreślić ust. 3, 3. Do wydania wstępnej opinii nie stosuje się przepisów ustawy z dnia 14 czerwca 1960 r. – Kodeks postępowania administracyjnego. \\tPrekonsultacje niepotrzebnie wydłużają proces refundacyjny. Ewentualnie rekomendujemy wprowadzenie niewiążącego charakteru prekonsultacji.  Nie możemy zgodzić się na wiążący charakter takich wstępnych opinii połączony z brakiem możliwości odwołania się od nich z uwagi na wyłączenie przepisów kodeksu postępowania administracyjnego. Zaproponowane przez Ministerstwo Zdrowia rozwiązanie byłoby wprost sprzeczne z art. 6 ust. 2 Dyrektywy Rady 89/105/EWG z dnia 21 grudnia 1988 r. dotyczącej przejrzystości środków regulujących ustalanie cen na produkty lecznicze przeznaczone do użytku przez człowieka oraz włączenia ich w zakres krajowego systemu ubezpieczeń zdrowotnych.\\tUwaga zasadna \\n\\tAmerykańska Izba Handlowa w Polsce/Pracodawcy RP\\tArt. 16ab ustawy refundacyjnej \\tProponujemy rezygnację z wprowadzania art. 16ab.\\t\\tKF AmCham/Pracodawcy RP proponuje/ą zniesienie blokady jednoczesnej refundacji leku w różnych wskazaniach w programie lekowym i w aptece.  W pierwszej kolejności, pragniemy zwrócić uwagę, że wprowadzenie takiej regulacji byłoby sprzeczne z obecnie obowiązującą definicją programu lekowego (art. 2 pkt. 18 UoR), która wprost odnosi się do danego wskazaniu oraz danej populacji, dopuszczając tym samym możliwość refundowania tego samego leku w różnych wskazaniach w różnych kategoriach dostępności. Takie rozwiązanie wydaje się przeczyć nie tylko idei uelastycznienia leczenia pomiędzy różnymi kategoriami dostępności refundacyjnej (np. w kontekście projektu zmian w leczeniu długoterminowym, o którym MZ wspomniało podczas spotkania w dniu 2 czerwca), ale również prekonsultacji, podczas których MZ oraz wnioskodawca mają docelowo porozumiewać się w kwestii wyboru właściwej kategorii dostępności. Rozwiązanie takie wpisuje się też w koncepcję tzw. odwróconej piramidy świadczeń, a także w uzasadnienie do samego Projektu, zgodnie z którym: „Jednocześnie jest to wyjście naprzeciw wytypowania terapii, które mogłyby być kontynuowane w ramach długotrwałego leczenia, jeżeli pierwsza ordynacja leku \\frozpoczęła się w programie lekowym lub chemioterapii. W katalogu aptecznym nie istnieją żadne bezpieczniki, które zabezpieczałyby płatnika publicznego przed nieuprawnioną preskrypcją dublująca się wielokrotnie u kilku specjalistów, braku zdefiniowanego horyzontu leczenia pacjenta oraz osoby prowadzącej daną terapię pacjenta. (…)”.\\t\\fUwaga zasadna \\n\\tPolskie Towarzystwo Reumatologiczne \\tart. 1 pkt 13 projektu odnoszący się do art. 16ab ustawy projektu\\tWnioskujemy o usunięcie art. 16 ab ustawy w związku ze zmianą zaproponowaną w pkt 1. (pkt. 1- uwaga PTR - W związku z wprowadzeniem przez projektodawcę tzw. „czwartej kategorii dostępności refundacyjnej” wnioskujemy o zmianę definicji programu lekowego.) \\tKontynuacja zmiany zaproponowanej w pkt 1.\\tUwaga zasadna \\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 13 projektu (art. 16ab ustawy)\\tWnosimy o uchylenie art. 16ab ustawy\\tWprowadzenie zaproponowanych zapisów byłoby sprzeczne z obecnie obowiązującą definicją programu lekowego (art. 2 pkt. 18), która wskazuje że jest to kategoria obejmująca lek we wskazaniu oraz dla danej populacji, dopuszczając tym samym możliwość refundowania tego samego leku w różnych wskazaniach w różnych kategoriach dostępności.  Takie rozwiązanie przeczy idei elastycznego przesuwania leków między różnymi kategoriami dostępności refundacyjnej i jest niespójne z ideą \\fprekonsultacji, w których MZ oraz wnioskodawca mają ustalać kategorię dostępności.  Biorąc pod uwagę także tendencję deregulacyjną, zasadnym jest skreślenie tej blokady, szczególnie mając na uwadze, że MZ i tak będzie miał prawo nie wydać decyzji refundacyjnej w danej kategorii jeżeli nie zgadza się z takim podejściem.\\t\\fUwaga zasadna \\n\\tRada Organizacji Pacjentów przy Rzeczniku Praw Pacjenta\\tart. 1 pkt 13 projektu w zakresie ust. 4 i 5\\t\\tROP zgłosił następujące uwagi:  \\t1) Opis programu ma podlegać opiniowaniu przez Prezesa AOTMiT. Jednocześnie, wnioskodawca będzie miał obowiązek zaopiniować opis programu lekowego w terminie nie dłuższym niż 7 dni od dnia otrzymania opisu tego programu od Ministerstwa (Ministerstwo przekazywać będzie wnioskodawcy opis po wydaniu opinii przez Prezesa AOTMiT) – stanowisko wnioskodawcy nie będzie wiążące. Ministerstwo dodatkowo może dokonać zmian w programie bez konsultacji.  \\t2) Poza tym możliwa jest zmiana programu lekowego w każdym momencie - jak w związku z powyższym zostaną zabezpieczeni uczestniczący w programie lekowym pacjenci?\\t\\tUwaga niezasadna Nowelizacja ustawy o refundacji z 2023  r. wyłączyła treść programu lekowego jako załącznik do decyzji i umożliwiła ministrowi właściwemu do spraw zdrowia zmiany treści programu bez potrzeby uzyskiwania zgód wnioskodawców, wprowadziła możliwość zmiany treści programów lekowych bez przeprowadzania postępowania administracyjnego. Powyższe umożliwiło szybkie zmiany treści programów i dostosowanie ich do potrzeb zarówno świadczeniobiorców, jak i wynikających z postępu i rozwoju  opcji terapeutycznych i metod diagnostycznych. Na przestrzeni ponad dwuletniej już praktyki Minister Zdrowia nie dokonał żadnej zmiany programu lekowego bez zgody któregokolwiek ze Stron, czy wbrew stanowisku Strony. Brak obligatoryjnej konsultacji Ministra Zdrowia w zakresie zmiany programu lekowego ze stroną decyzji administracyjnej nie zakazuje Organowi nieformalnych konsultacji. Wszelki \\fzmiany odbywają się w poszanowaniu stanowiska i opinii Wnioskodawców. \\n\\tAlivia - Fundacja Onkologiczna\\tart. 1 pkt 14 projektu odnoszący się do art. 16b ust. 1 ustawy refundacyjnej\\t\\tWyrażamy zastrzeżenia wobec przeniesienia decyzji klinicznych tylko i wyłącznie na organy administracyjne (Zespoły Koordynacyjne), które nie pozostają w kontakcie z pacjentem i nie ponoszą odpowiedzialności za skutki terapii.\\t\\tUwaga niezasadna Minister Zdrowia nie podziela stanowiska zgłaszających uwagę. Konsylium Lekarskie jest zespołem koordynującym, który ma za zadanie zorganizować i nadzorować proces leczenia, w tym kwalifikację do leczenia, wybór metod leczenia oraz monitorowanie postępów terapii. Kieruje się stanem zdrowia pacjenta i treścią programu lekowego. Nie jest organem administracyjnym. Opis programu lekowego może przewidywać powołanie przez Prezesa Funduszu zespołu koordynacyjnego dla danego programu lekowego.\\n\\tAlivia – Fundacja Onkologiczna\\tart. 1 pkt 14 projektu odnoszący się do art. 16b ustawy refundacyjnej\\t\\tWprowadzenia zapisów rozszerzających kompetencje Zespołów Koordynacyjnych. W proponowanym kształcie zespoły te, będące organami administracyjnymi, otrzymują uprawnienia o charakterze klinicznym, choć nie mają bezpośredniego kontaktu z pacjentem ani nie ponoszą odpowiedzialności za skutki podejmowanych decyzji. Brak gwarancji przejrzystości działania tych zespołów, mechanizmów odwoławczych dla pacjentów oraz jasnej odpowiedzialności za rozstrzygnięcia budzi poważne obawy o poszanowanie praw chorego i bezpieczeństwo terapii.\\t\\tUwaga niezasadna Minister Zdrowia nie podziela stanowiska zgłaszających uwagę. Konsylium Lekarskie jest zespołem koordynującym, który ma za zadanie zorganizować i nadzorować proces leczenia, w tym kwalifikację do leczenia, wybór metod leczenia oraz monitorowanie postępów terapii. Kieruje się stanem zdrowia pacjenta i treścią programu lekowego. Nie jest organem administracyjnym. Opis programu lekowego może przewidywać powołanie przez Prezesa Funduszu zespołu koordynacyjnego dla danego programu lekowego.\\n\\tPolskie Towarzystwo Reumatologiczne \\tArt. 1 pkt 14 projektu odnoszący \\fsię do art. 16b ust. 7 pkt 3 ustawy\\t\\fWnioskujemy o zmianę art. 16b ust. 7 pkt 3 ustawy ze względu na konieczność wyłączenia przedstawiciela organizacji \\fpacjentów z posiedzeń zespołu koordynacyjnego, których przedmiotem jest analiza wniosków o zakwalifikowanie pacjenta do leczenia.  Proponujemy następujące brzmienie art. 16b ust. 7 pkt 3 ustawy:  \\t„3) przedstawiciel organizacji pacjentów wspierających pacjentów z chorobą leczoną w ramach danego programu lekowego, z wyjątkiem posiedzeń, których przedmiotem jest analiza wniosków o zakwalifikowanie pacjenta do leczenia.”\\t\\fZgodnie z aktualną praktyką i regulaminem ZK ds. Leczenia Chorób Reumatycznych przedstawiciel \\fpacjentów bierze udział w posiedzeniu ZK na zaproszenie przewodniczącego, ale tylko w części dot. spraw ogólnych związanych z realizacją programu. Nie bierze jednak udziału w części dot. rozpatrywania wniosków i kwalifikacji pacjentów, w której dochodzi do omawiania wrażliwych danych medycznych. Lekarz zobowiązany jest do dochowania tajemnicy lekarskiej, co nie dot. innych osób nie będących lekarzami. W związku z tym obecność przedstawicieli organizacji pacjentów w takiej części posiedzenia ZK wymaga ponownej analizy.  \\tPodobnie w przypadku obecności w trakcie posiedzenia przedstawicieli NFZ i MZ, zgodnie z pkt 1 i 2.\\t\\fUwaga niezasadna Prezes NFZ określa w zarządzeniu regulamin zespołu koordynacyjnego, w \\ftym organizację, sposób i tryb działania oraz zakres uczestnictwa poszczególnych uczestników posiedzeń w pracach zespołu. \\n\\tRada Organizacji Pacjentów przy Rzeczniku Praw Pacjenta\\tart. 1 pkt 14 i 15 projektu w zakresie art. 16b ust. 2 i art. 16c ust. 1\\t\\tRPO zgłosił następujące wątpliwości:  \\tPrzejęcie decyzji terapeutycznych z rąk lekarzy prowadzących, znających sytuację pacjenta, przez gremium „bezosobowe” z punktu widzenia chorego, które nie bada chorego i nie odpowiada za jego terapię; \\tpacjent nie ma możliwości odwołania się od decyzji Zespołu; \\tbrak uregulowania odpowiedzialności członków Zespołu Koordynacyjnego za podejmowane decyzje, szczególnie ze to lekarz pacjenta ponosi \\fkonsekwencje w ramach odpowiedzialności zawodowej za leczenia pacjenta, a nie Zespół. \\t\\t\\fROP ponadto wskazuje, iż o Zespołach Koordynacyjnych wypowiadał się Trybunał Konstytucyjny, który przedstawił Sejmowi postanowienie sygnalizacyjne w sprawie luk prawnych dotyczących statusu Zespołu Koordynacyjnego ds. Chorób Ultrarzadkich. Chodzi o postanowienie TK z 17.10.2018 r., S 6/18, OTK-A 2018, nr 63, dostępne pod adresem: \\thttps://ipo.trybunal.gov.pl/ipo/Sprawa?cid=2&dokument=17324&sprawa=20952 \\tNależy tu wskazać Zadania Zespołu Koordynacyjnego: \\t\\fkwalifikacja świadczeniobiorców do programu lekowego; \\tocena skuteczności terapii w trakcie trwania programu lekowego; \\trozstrzyganie o wyłączeniu świadczeniobiorców z programu lekowego; \\tskładanie rocznych raportów do Prezesa NFZ z realizacji danego programu lekowego; \\tskładanie do Ministerstwa Zdrowia propozycji zmian, kontynuacji lub zaprzestania finansowania programu lekowego na podstawie danych przekazywanych przez świadczeniodawców realizujących dany program lekowy do Funduszu i zespołu koordynacyjnego, w szczególności dotyczących oceny skuteczności terapii. \\t W posiedzeniu zespołu koordynacyjnego mogą brać udział, bez prawa głosu: 1) przedstawiciel Prezesa Funduszu; 2) przedstawiciel ministra właściwego do spraw zdrowia; 3) przedstawiciel organizacji pacjentów wspierających pacjentów z chorobą leczoną w ramach \\fdanego programu lekowego - zatem jaka jest rola przedstawiciela organizacji?\\t\\fUwaga niezasadna Konsylium Lekarskie jest zespołem koordynującym, który ma za zadanie ma za zadanie zorganizować i nadzorować proces leczenia, w tym kwalifikację do leczenia, wybór metod leczenia oraz monitorowanie postępów terapii. Kieruje się stanem zdrowia pacjenta i treścią programu lekowego. Nie jest organem administracyjnym. Jeżeli chodzi o uwagę odnośnie do roli przedstawiciela to wprowadzenie możliwości udziału w posiedzeniu ww. zespołu przedstawiciela organizacji pacjentów wspierających pacjentów z daną chorobą jest zasadne z uwagi na unikalne doświadczenie pacjentów w zakresie doświadczenia choroby (patient experience) i funkcjonowania systemu, \\fktóre pozwalają dostrzec aspekty nie widziane i często pomijane przez profesjonalistów medycznych, a dotyczące zwłaszcza organizacyjnej, praktycznej strony programów . Termin „bez prawa głosu” odnosi się do braku możliwości uczestnictwa w głosowaniach zespołu koordynacyjnego, nie zaś do braku ogólnej możliwości mówienia i wypowiadania się\\n\\tFederacja Pacjentów Polskich, Krajowe Forum ORPHAN\\tart. 1 pkt 14 lit. b projektu w zakresie art. 16b ust. 7 pkt 3 ustawy refundacyjnej\\t7.\\tW posiedzeniu zespołu koordynacyjnego mogą brać udział, bez prawa głosu: 1)\\tprzedstawiciel Prezesa Funduszu; 2)\\tprzedstawiciel ministra właściwego do spraw zdrowia; \\t3)\\tprzedstawiciel organizacji pacjentów wspierających pacjentów z chorobą leczoną w ramach danego programu lekowego oraz przedstawiciel pacjentów z organizacji parasolowej\\t\\t\\tUwaga niezasadna Zaproponowana przez Ministra Zdrowia regulacja w tym zakresie wydaje się kompleksowa. Żądanie udziału organizacji parasolowej w toku procesu decyzyjnego prowadzonego przez Organ jako przejawu kontroli społecznej jest  niezasadne. Wprowadzenie możliwości udziału w posiedzeniu zespołu koordynacyjnego - bez prawa głosu - przedstawiciela organizacji pacjentów wspierających pacjentów z daną chorobą jest zasadne z uwagi na unikalne doświadczenie pacjentów w zakresie doświadczenia choroby (patient experience) i funkcjonowania systemu, które pozwalają dostrzec aspekty nie widziane i często pomijane przez profesjonalistów medycznych, a dotyczące zwłaszcza organizacyjnej, praktycznej strony programów Należy wskazać, że podmioty o charakterze fundacji/stowarzyszenia również działają przez swoich przedstawicieli. Minister Zdrowia otrzymując sygnały od pacjentów czy organizacji społecznych, bierze je pod uwagę w toku podejmowanych działań.\\n\\tFederacja Przedsiębiorców Polskich\\tart. 1 pkt 14 lit. b projektu w zakresie art. 16b ust. 7 pkt 3 ustawy refundacyjnej)\\tWnioskujemy o zmianę art. 16b ust. 7 pkt 3 ustawy ze względu na konieczność wyłączenia przedstawiciela organizacji pacjentów z posiedzeń zespołu koordynacyjnego, których przedmiotem  jest  analiza  wniosków o zakwalifikowanie pacjenta do leczenia.  Proponujemy następujące brzmienie art. 16b ust. 7 pkt 3 ustawy:  „3) przedstawiciel organizacji pacjentów wspierających pacjentów z chorobą leczoną w ramach danego programu lekowego, z wyjątkiem  posiedzeń, których  przedmiotem  jest  analiza  wniosków o zakwalifikowanie pacjenta do leczenia.”\\t\\t\\fWnioskowana zmiana umożliwia zachowanie tajemnicy lekarskiej w związku z kwalifikacją pacjentów do leczenia. \\tUwaga częściowo zasadna W projekcie nastąpiła zmiana zgodnie, z którą obecność przedstawicieli stowarzyszeń pacjentów nie może mieć miejsca podczas omawiania wniosków pacjentów. Pozostawienie przepisów w zaproponowanym pierwotnie kształcie może powodować naruszenie zasad \\fochrony danych wrażliwych, w tym powodować niepotrzebne ‘napięcia’ w sytuacjach spornych związanych np. z podejmowaniem decyzji o włączeniu leczenia, zakończeniu, kontynuacji bądź wyłączeniu z terapii\\n\\tAmerykańska Izba Handlowa w Polsce\\tart. 1 pkt 15 projektu w zakresie art. 16c ustawy refundacyjnej\\tW odniesieniu do koncepcji umożliwienia rozpoczęcia leczenia w nowych programach lekowych od pierwszego dnia obowiązywania decyzji o objęciu refundacją, przedstawionej w art. 16c, proponujemy rozważenie wprowadzenia bardziej systemowego rozwiązania. Przykładowo, rozwiązanie taki mogłoby obejmować: wprowadzenie uproszczonej procedury kontraktowania programów lekowych obejmującej, między innymi, rokowania pomiędzy OW NFZ a świadczeniodawcami, wcześniejsze przygotowanie Centrali NFZ do procesu kontraktowania poprzez np. odpowiednio wczesne przygotowanie wymagań dla ośrodków, czy ryczałtów diagnostycznych oraz \\fumożliwienie szpitalom szybkiego nabycia leków; w przypadku rozwiązania zaproponowanego w Projekcie - zapewnienie dostępności do leczenia w ramach nowego programu lekowego w skali całego kraju (przykładowo liczba ośrodków, w których zostanie udostępniona refundowana terapia podczas 3 miesięczego okresu kontraktowania, powinna być dostosowywana do chorobowości danej jednostki chorobowej w uzgodnieniu z właściwym Konsultantem Krajowym i Konsultantami Wojewódzkimi); \\tw przypadku rozwiązania zaproponowanego w Projekcie -zapewnienie gwarancji finalnego zakontraktowania programu lekowego przez świadczeniodawców wskazanych do realizacji terapii przez 3 miesięczny okres przejściowy, tak aby uniknąć sytuacji, w której pacjenci po okresie pierwszych trzech miesięcy byliby zmuszeni do zmiany ośrodka.\\t\\t\\fPomimo niewątpliwie słusznej i w pełni popieranej koncepcji zapewnienia leczenia w programach lekowych od pierwszego dnia obowiązywania decyzji KF AmCham pragnie zwrócić uwagę na potencjalne trudności w realizacji zaproponowanego mechanizmu w praktyce, tak aby faktycznie przyczynił się do zaspokojenia potrzeb pacjentów. Przekazane podczas spotkania w dniu 2 czerwca założenie, że miałyby to być 1-2 ośrodki miałoby szansę powodzenia w małych populacjach pacjentów zgromadzonych wokół tych ośrodków. Niestety, w przypadku większych populacji, dla chorób populacyjnych, lub dla których pacjenci są rozproszeni w Polsce, wymagane byłoby zapewnienie dostępu do leczenia przynajmniej w ramach jednego ośrodka w każdym województwie. Niezmiernie istotnym jest też zapewnienie takich regulacji, które dadzą gwarancję, że okres 3 miesięcy będzie wystarczający do \\fprzeprowadzenia postępowań konkursowych oraz podpisania umów na realizację programu lekowego we wszystkich województwach w Polsce, tak aby nie dopuścić do sytuacji, że pacjenci nie mieliby dostępu do refundowanego leczenia. \\tZ tego względu apelujemy o rozważenie wprowadzenia bardziej systemowego rozwiązania umożliwiającego realizację w praktyce założonego celu przedmiotowej regulacji, tj. zapewnienia dostępu do leków refundowanych w ramach nowo utworzonych programów lekowych od 1 dnia obowiązywania decyzji refundacyjnej.\\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. Zgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia żywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej \\fod pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego.  \\n\\tFederacja Przedsiębiorców Polskich\\tart. 1 pkt 15 projektu w zakresie art. 16c ustawy refundacyjnej\\tWnosimy o uchylenie art. 16c ustawy w związku z wnioskiem o uchylenie art. 11 ust. 3b ustawy (art. 1 pkt 7 lit. c projektu).\\t\\tPropozycja dodania art. 16c ustawy wynika wprost z faktu konieczności wprowadzenia regulacji dotyczącej zawarcia przez NFZ umowy ze świadczeniodawcami, którzy zapewnią pacjentom dostęp do leczenia w okresie 3 \\fmiesięcy od pierwszego dnia obowiązywania decyzji administracyjnej o objęciu refundacją leku albo środka spożywczego specjalnego przeznaczenia żywieniowego w kategorii dostępności refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2. \\t\\fUwaga niezasadna Projektodawca postawił zmienić całkowicie kształt zaproponowanego rozwiązania, ostatecznie przyjęte rozwiązanie ma również na celu przyśpieszenie udzielania świadczeń w ramach nowych programów lekowych. \\fZgodnie z zaprojektowanym regulacjami decyzja o objęciu refundacją leku, który nie ma odpowiednika refundowanego w danym wskazaniu, dla którego tworzy się nowy program lekowy, może zostać umieszczony na wykazie, o którym mowa w art. 37 ust. 1, poprzedzającym wykaz, którego pierwszy dzień obowiązywania pokrywa się z terminem wejścia w życie decyzji administracyjnej o objęciu refundacją tego leku albo środka spożywczego specjalnego przeznaczenia żywieniowego. Regulacja ta ma umożliwić szybsze kontraktowanie nowych programów lekowych. Dodatkowo będzie ustawowe zobowiązanie Prezes NFZ do podpisania umów ze świadczeniodawcami umożliwiających rozpoczęcie udzielania świadczeń, na podstawie umów o udzielanie świadczeń opieki zdrowotnej od pierwszego dnia obowiązywania decyzji refundacyjnej dla leku, stosowanego w ramach nowego programu lekowego. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tart. 1 pkt 17 lit. a projektu odnoszący się do  Art. 18 ust. 1 pkt 5\\t1. Do zadań Komisji należy prowadzenie negocjacji z wnioskodawcą w zakresie: … 5) zobowiązania do zapewnienia ciągłości dostaw, o którym mowa w art. 12 pkt 14, zapewniającego zaspokojenie potrzeb populacji.\\tFragment o zabezpieczeniu potrzeb zdrowotnych świadczeniobiorców jest zbędny, ponieważ to Minister Zdrowia i Komisja Ekonomiczna decydują, w ramach negocjacji i decyzji, jaki poziom dostaw jest potrzebny w ujęciu całościowym oraz wystarczający w przypadku każdego indywidualnego dostawcy, kierując się kryteriami podanymi w nowo dodanym przepisie art. 19 ust. 2 pkt 8 Projektu. Pojedynczy dostawca nie odpowiada za zabezpieczenie całokształtu potrzeb zdrowotnych świadczeniobiorców. \\t\\t\\fUwaga niezasadna Komisja Ekonomiczna dysponuje wszelkimi narzędziami pomocnymi do oceny deklarowanych dostaw w porównaniu z szacowanym zapotrzebowaniem na daną technologię, co pozwoli określić czy proponowane wartości są w stanie zaspokoić potrzeby zdrowotne pacjentów. Uzupełnienie zadań Komisji Ekonomicznej ma na celu przeniesienie ciężaru negocjacyjnego w zakresie zobowiązania do zapewnienia ciągłości dostaw przedkładanego do wniosków o objęcie refundacją na \\fKomisję Ekonomiczną. Negocjacja z członkami Komisji Ekonomicznej stanowią odpowiedni moment w każdym postępowaniu dotyczącym objęcia refundacją na ustalenie odpowiedniego poziomu dostaw w stosunku do danej technologii lekowej. Dodatkowo, wieloetapowa formuła prowadzenia negocjacji daj możliwość dodatkowego spotkania w przypadku zaistnienia wątpliwości.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tart. 1 pkt 17 lit. c projektu odnoszący się do art. 18 ust. 1 ustawy refundacyjnej\\t5) zobowiązania do zapewnienia ciągłości dostaw, o którym mowa w art. 12 pkt 14, zapewniającego zaspokojenie potrzeb populacji.; \\t6) zakresu ograniczeń w zakresie preskrypcji, o których mowa w art. 6 ust. 2b.\\t\\tZobacz uzasadnienie do artykułu art. 1 pkt 2 lit b projektu odnoszące się do art. 6 ust. 2b ustawy refundacyjnej.\\tUwaga niezasadna Minister Zdrowia w związku z licznymi uwagami podjął decyzję wykreśleniu z projektu zapisów o możliwości określenia w wykazie leków refundowanych specjalizacji lekarskiej uprawnionej do ustalenia zasadności i poziomu refundacji danego leku, środka spożywczego specjalnego przeznaczenia żywieniowego i wyrobu medycznego.  \\n\\tPracodawcy RP\\tart. 1 pkt 18 projektu odnoszący się do art. 18a ustawy refundacyjnej\\tProponujemy uchylenie art. 18a w całości. \\t\\tW nawiązaniu do informacji przekazanej podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca, jak również bazując na przepisie art. 18a ust 2, który pozostanie po uchyleniu ust. 1 rozumiemy, że wnioskodawca będzie mógł zmodyfikować wniosek na każdym etapie postępowania. Z tego względu wydaje się, że pozostawienie jedynie przepisu art. 18a ust. 2 wydaje się zbędne.\\tUwaga niezasadna W związku z powyższą uwagą i po prze analizowaniu proponowanego stanu prawnego projektodawca postanowił zamiast usunięcia ust. 1 zmodyfikować jego brzmienie na następujące: „Po podjęciu przez Komisję uchwały, o której mowa w art. 18 ust. 3, wnioskodawca nie może zmienić treści wniosku, o którym mowa w art. 24 ust. 1, w zakresie ceny zbytu netto i instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 2 pkt 7.” \\n\\tPolski Związek Pracodawców \\fPrzemysłu Farmaceutycznego\\t\\fArt. 18a\\tMinister właściwy do spraw zdrowia może, po podjęciu przez Komisję uchwały, o której mowa w art. 18 ust. 3 lub na wniosek \\fwnioskodawcy, przeprowadzaić dodatkowe negocjacje z wnioskodawcą w zakresie, o którym mowa w art. 18 ust. 1 pkt 1, 3, i 4 i 5, biorąc pod uwagę kryteria, o których mowa w art. 19 ust. 2, jeżeli uzna to za konieczne ze względu na niezaspokojone potrzeby świadczeniobiorców oraz możliwości płatnicze podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych. \\t\\t\\fDodatkowe negocjacje powinny odbywać się  także na wniosek wnioskodawcy, a ich zakres w każdym \\fwypadku powinien w razie potrzeby obejmować również wielkość dostaw (dopisanie pkt 5). Ponadto prosimy o usunięcie z uzasadnienia Projektu fragmentu, który nie koresponduje z treścią ust. 2: „strony mogą modyfikować wniosek w zakresie ceny zbytu netto i instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 2 pkt 7 ustawy refundacyjnej. Może to nastąpić jedynie po przeprowadzeniu dodatkowej tury negocjacji, o której mowa, w art. 18a ust. 2 ustawy refundacyjnej. Wszelkie oferty składane poza tymi negocjacjami nie będą wywierały skutku prawnego, a co za tym idzie organ nie będzie brał ich pod uwagę przy rozstrzyganiu danej sprawy” \\t\\t\\fUwaga częściowo zasadna W związku z powyższą uwagą i po prze analizowaniu proponowanego stanu \\fprawnego projektodawca postanowi zamiast usunięcia ust. 1 zmodyfikować jego brzmienie wraz z ust. 2, na następujące: a)\\tw ust. 1 otrzymuje brzmienie: „1. Po podjęciu przez Komisję uchwały, o której mowa w art. 18 ust. 3, wnioskodawca nie może zmienić treści wniosku, o którym mowa w art. 24 ust. 1, w zakresie ceny zbytu netto i instrumentu dzielenia ryzyka, o którym mowa w art. 11 ust. 2 pkt 7.”, b)\\t\\tw ust. 2 skreśla się wyrazy „pkt 1, 3 i 4”.  \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tart. 1 pkt 19 lit. b projektu odnoszący się do art. 19 ust. 1c \\t\\t1c. Wnioskodawca podczas negocjacji jest reprezentowany przez nie więcej niż 4 osoby.  Reprezentantem wnioskodawcy nie może być konsultant krajowy lub konsultant wojewódzki.\\tNowelizacja z dnia 17 sierpnia 2023 r. ograniczyła liczbę reprezentantów wnioskodawcy w negocjacjach z Komisją Ekonomiczną do 3 osób. Projekt zwiększa tę liczbę do 4 osób. Tymczasem w niektórych przypadkach zachodzi rzeczywista potrzeba zaangażowania większej  ilości osób po stronie wnioskodawcy, w szczególności gdy przedmiotem negocjacji są skomplikowane zagadnienia medyczne lub farmakoekonomiczne wymagające specjalistycznej wiedzy.  Należy również zwrócić uwagę na nierówność traktowania przez ustawodawcę obu stron negocjacji. Zgodnie bowiem z art. 19 ust. 1b przewodniczący Komisji może dopuścić do negocjacji więcej niż 3 osoby, ale tylko po stronie Komisji. \\fPostulujemy rezygnację z odgórnego ograniczenia liczby reprezentantów wnioskodawcy w negocjacjach i przywrócenie w ten sposób zasady, że o składzie i liczebności swojego zespołu negocjacyjnego decyduje wnioskodawca. \\t\\t\\fUwaga niezasadna Wnioskodawca może powołać do swojego składu reprezentanta organizacji pacjentów reprezentującą organizację pacjentów, o której mowa w art. 55a ust. 1 ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2024 r. poz. 581), wówczas będzie mógł być reprezentowany nawet przez 5-osobowy skład (art. 1 pkt 19 lit. c projektu). W opinii Ministra Zdrowia liczba 4 reprezentantów Wnioskodawcy jest wystarczająca nawet w przypadku, gdy przedmiotem negocjacji są skomplikowane zagadnienia medyczne lub farmakoekonomiczne wymagające specjalistycznej wiedzy. \\n\\tRada Organizacji Pacjentów przy Rzeczniku Praw Pacjenta\\tart. 1 pkt 19 lit. c projektu\\t\\tNależy dookreślić udział organizacji np. poprzez akt wykonawczy.\\t\\tPozytywnym jest możliwość zaproszenia po stronnie świadczeniodawcy przedstawiciela organizacji pacjentów z wykazu prowadzonego przez Rzecznika Praw Pacjenta. Jednak wątpliwości organizacji dotyczą braku konfliktu interesów. Czy i w jaki sposób przedstawiciel organizacji będzie określała swój brak konfliktu – a także czy będzie zapraszany również na negocjacje ceny leku. \\t\\tUwaga niezasadna Z uwagi na fakt, że stroną postępowania jest Organ oraz firma farmaceutyczna, na wniosek której toczą się postępowania refundacyjne to właśnie Wnioskodawcy Minister Zdrowia pozostawił decyzję w zakresie powołania do udziału w spotkaniach negocjacyjnych osobę reprezentującą organizację pacjentów. Zważywszy, że negocjacje cenowe dotyczą materii stanowiącą tajemnicę przedsiębiorcy, to po stronie wnioskodawcy będzie leżało podjęcie decyzji, czy zamierza skorzystać z takiego rozwiązania.  Wnioskodawca jest podmiotem chronionym przez art. 11 ustawy z dnia 16 kwietnia 1993 r. o zwalczaniu nieuczciwej konkurencji (Dz. U. z 2022 r. poz. 1233), a także to wnioskodawca dobrze wie co objęte jest tajemnica refundacyjna, a zatem to jemu pozostawia się wybór dodatkowej 5 osoby w jego składzie negocjacyjnym. Odwrotna sytuacja, a więc pozostawienie tego w gestii ministra właściwego do spraw zdrowia powodowałaby wydłużenie postępowania refundacyjnego, ponieważ każdorazowo po wpłynięciu wniosku o objęcie refundacją należałoby się zwrócić do organizacji pacjentów, które najpierw trzeba byłoby wytypować, a następnie czekać na wskazanie osoby oraz na zgodę \\fpodmiot odpowiedzialnego, jak również poinformowaniu o braku konfliktu interesu.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 19 lit. a odnoszący się do art. 19 ust. 1\\t\\tRozpatrując wnioski, o których mowa w art. 24 ust. 1 pkt 1-2 i, 4 i 5, Komisja prowadzi negocjacje w składzie trzyosobowym, zwanym dalej \\\"zespołem negocjacyjnym\\\".\\tPostulujemy, aby wnioski o skrócenie okresu obowiązywania decyzji refundacyjnej nie podlegały procedurze negocjacyjnej. Obecny wymóg negocjacji generuje nieuzasadnione wydłużenie czasu postępowania oraz niepotrzebne obciążenie Komisji Ekonomicznej i wnioskodawców, co wiąże się również z nieefektywnym wykorzystaniem środków publicznych przeznaczonych na wynagrodzenia członków Komisji. Należy zaznaczyć, że decyzja o pozostaniu w systemie refundacji należy zawsze do wnioskodawcy, a Minister Zdrowia zawsze ma prawo wydać decyzję negatywną w przedmiocie skrócenia okresu obowiązywania refundacji, bez konieczności angażowania członków Komisji Ekonomicznej.  \\t\\tUwaga niezasadna  Zgodnie z art. 18 ust. 2 pkt. 2 jednym z obowiązków Komisji Ekonomicznej jest prowadzenie działań mających na celu racjonalizację wydatków związanych z refundacją oraz przedstawianie ministrowi właściwemu do spraw zdrowia propozycji w tym zakresie. Skrócenie decyzji może znacząco wpłynąć na budżet płatnika, zmniejszyć sytuację w grupie limitowej pozbawiając pacjentów dostępu do konkretnych leków. Komisja Ekonomiczna analizuje koszty terapii, dostępne alternatywy, ewentualne braki dostępności odpowiedników leków. Komisja Ekonomiczna może ocenić, czy skrócenie refundacji wpłynie negatywnie na dostępność leczenia lub konkurencję rynkową.\\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\tArt. 1 pkt 19 lit. c projektu odnoszący się do art. 19 ust. 1d ustawy refundacyjnej \\t\\tWykreślenie przepisu oraz zdefiniowanie roli pacjenta na wcześniejszych etapach.\\t\\tRekomendujemy zdefiniowanie roli pacjenta we wcześniejszych etapach, na przykład poprzez ustawowe wprowadzenie obowiązku pytania o opinię organizacji pacjenckiej przez Agencję Oceny Technologii Medycznych i Taryfikacji, tak, aby ta opinia była publicznie dostępna w analizie weryfikacyjnej AOTMiT) Ze względu na charakter obrad Komisji zasadny wydaje się udział przedstawiciela organizacji pacjentów we wcześniejszych etapach, na przykład na posiedzeniu Rady \\fPrzejrzystości lub też na etapie konsultowania programu lekowego, a nie dopiero na spotkaniach negocjacyjnych Komisji. Jeśli przepis miałby pozostać, należy go doprecyzować w zakresie  zasad udziału osób reprezentujących organizacje pacjentów oraz etapów w jakich mogliby brać udział. \\tNie jest jasne, dlaczego rola organizacji pacjentów nie została ustawowo doprecyzowana we wcześniejszych etapach postępowania refundacyjnego (np. poprzez ustawowe narzucenie obowiązku pytania o opinię organizacji pacjenckiej przez AOTMiT, tak, aby ta opinia była publicznie dostępna w analizie weryfikacyjnej AOTMiT). Nie wiemy również jaka była intencja ustawodawcy, który przewidział rolę organizacji pacjenckiej dopiero na etapie negocjacji finansowych z Komisją Ekonomiczną, które co do zasady są tajne a opinia organizacji pacjenckiej przekazana na takich negocjacjach nie będzie nigdzie dostępna (nie będzie jawna). W dodatku udział organizacji pacjenckiej w negocjacjach finansowych może naruszać tajemnicę przedsiębiorstwa określoną w art. 11 ust. 2 ustawy o zwalczaniu nieuczciwej konkurencji.  \\tWydaje się że możliwość udziału pacjentów byłaby szczególnie cenna, jeśli chodzi o zrozumienie problemów \\fzdrowotnych, z którymi zmagają się sami pacjenci.\\t\\fUwaga niezasadna Zbyt wielki kręg podmiotów z którymi Minister Zdrowia ma konsultować treść programu lekowego powoduje wydłużenie czasu procedowania wniosków refundacyjnych. Jest kilka możliwości wypowiadania się na temat procedowanych wniosków: -Rada przejrzystości -Po publikacji analizy weryfikacyjnej -Projekt obwieszczenia Ministerstwo Zdrowia apeluje o większą aktywność na obecny etapach umożliwiającą zgłaszanie uwag.  \\fMZ wprowadza też 4 możliwość w czasie negocjacji.  W sytuacji, w której Wnioskodawca postanowi powołać do swojego składu reprezentanta organizacji pacjentów reprezentującą organizację pacjentów, o której mowa w art. 55a ust. 1 ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2024 r. poz. 581), może powołać do udziału w spotkaniach negocjacyjnych dodatkową osobę ponad limit określony w ust. 1c, reprezentującą organizację pacjentów, o której mowa w art. 55a ust. 1 ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2024 r. poz. 581).Takie rozwiązanie ma wpłynąć na przejrzystość postępowań o objęcie refundacją i ustalenie ceny zbytu netto. Zważywszy, że negocjacje cenowe dotyczą materii stanowiącą tajemnicę przedsiębiorcy, to po stronie wnioskodawcy będzie leżało podjęcie decyzji, czy zamierza skorzystać z takiego rozwiązania.  Wnioskodawca jest podmiotem chronionym przez art. 11 ustawy z dnia 16 kwietnia 1993 r. o zwalczaniu nieuczciwej konkurencji (Dz. U. z 2022 r. poz. 1233), a także to wnioskodawca dobrze wie co objęte jest tajemnica refundacyjna, a zatem to jemu pozostawia się wybór dołączenia dodatkowej osoby w jego składzie negocjacyjnym. Odwrotna sytuacja, a więc pozostawienie tego w gestii ministra właściwego do spraw zdrowia powodowałaby wydłużenie postępowania refundacyjnego, ponieważ każdorazowo po wpłynięciu wniosku o \\fobjęcie refundacją należałoby się zwrócić do organizacji pacjentów, które najpierw trzeba byłoby wytypować, a następnie czekać na wskazanie osoby oraz na zgodę podmiot odpowiedzialnego, jak również poinformowaniu o braku konfliktu interesu. Dodatkowo mogłoby to powodować częstsze odwołania od decyzji administracyjnych o odmowie objęcia refundacją i ustalenia ceny zbytu netto.\\n\\tFederacja Pacjentów Polskich, Krajowe Forum ORPHAN\\tArt. 1 pkt 19 lit. c projektu odnoszący się do art. 19 ust. 1d ustawy refundacyjnej\\t\\t1d. Przewodniczący Komisji może powołać do udziału w spotkaniach negocjacyjnych dodatkową osobę ponad limit określony w ust. 1c, reprezentującą organizację pacjentów, o której mowa w art. 55a ust. 1 ustawy z dnia 6 listopada 2008 r. o prawach pacjenta i Rzeczniku Praw Pacjenta (Dz. U. z 2024 r. poz. 581).\\t\\t\\tUwaga niezasadna Po stronie Wnioskodawcy jest zabezpieczenie jego tajemnicy przedsiębiorcy. Dopóki nie zostanie unormowana prawnie kwestia funkcjonowania, finansowania przejrzystości działania fundacji, organizacji stowarzyszeń pacjenckich w osobnym akcie prawnym Minister Zdrowia  nie wyrazi zgody na wyznaczanie ze swojej strony przedstawiciela organizacji pacjenckich ze swojej strony do udziału w negocjacjach cenowych dla leków firm farmaceutycznych, które niejednokrotnie publikują w przestrzeni publicznej informacje w zakresie wspomagania finansowego takich podmiotów. MZ nie jest organem kompetentnym w zakresie rozstrzygania konfliktów interesów w zakresie działalności określonej fundacji z firmą farmaceutyczną. \\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 19 lit. c projektu odnoszący się do art. 19 ust. 1d \\fustawy refundacyjnej\\t\\fWnosimy o uchylenie art. 19 ust. 1d ustawy, który umożliwia wnioskodawcy powołanie do udziału w spotkaniach negocjacyjnych z Komisją Ekonomiczną reprezentanta organizacji pacjentów.    \\t\\t\\t\\fNaszym zdaniem, ze względu na fakt, iż negocjacje cenowe dotyczą materii stanowiącej tajemnicę przedsiębiorcy, przedstawiciel organizacji pacjentów nie powinien uczestniczyć w tej części \\fnegocjacji. W przeszłości zdarzało się, iż niektórzy wnioskodawcy zapraszali na posiedzenie zarówno ekspertów klinicznych, jak i przedstawicieli organizacji pacjenckich, ale tylko na część wstępną posiedzenia, podczas której przedstawiane były zazwyczaj dowody na efektywność kliniczną leku.\\t\\fUwaga niezasadna W gestii Wnioskodawcy jest zabezpieczenie jego tajemnicy przedsiębiorcy w czasie prowadzenia negocjacji. To do decyzji Wnioskodawcy \\fkażdorazowo będzie należało powołanie bądź nie do swojego składu negocjacyjnego przedstawiciela organizacji pacjentów.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 19 lit. d odnoszący się do art. 19 ust. 2\\t2. Negocjacje prowadzi się biorąc pod uwagę następujące kryteria: (…) - uwzględniając potrzebę równoważenia interesów świadczeniobiorców i przedsiębiorców zajmujących się wytwarzaniem lub obrotem lekami, środkami spożywczymi specjalnego przeznaczenia żywieniowego, wyrobami medycznymi, możliwości płatnicze podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, objęcia leku w ramach Krajowej Listy Leków Krytycznych oraz unijnym wykazie produktów leczniczych o krytycznym znaczeniu oraz działalność naukowo-badawczą i inwestycyjną wnioskodawcy w zakresie związanym z ochroną zdrowia na terytorium Rzeczypospolitej Polskiej oraz w innych państwach członkowskich Unii Europejskiej lub państwach członkowskich Europejskiego Porozumienia o Wolnym Handlu (EFTA). \\t\\tUwzględnienie podczas negocjacji Krajowej Listy Leków Krytycznych oraz unijnej listy leków krytycznych publikowanej przez Europejską Agencję Leków stanowi jedno z rozwiązań zabezpieczenia dostaw produktów o szczególnym znaczeniu dla bezpieczeństwa lekowego, co jest zgodne z celami strategicznymi UE oraz Polski. Również w projekcie Aktu o lekach krytycznych (Critical Medicines Act) w art. 19 ust. 1 przewidziano obowiązek ustanowienia przez każde państwo członkowskie programu wspierania bezpieczeństwa dostaw leków krytycznych, w tym dotyczących ich refundacji.\\tUwaga niezasadna Informacja o umieszczeniu danego leku na Krajowej Liście Leków Krytycznych czy liście leków krytycznych EMA, może być sygnalizowane przez Wnioskodawcę w postaci pisemnej i przedkładane w ramach dokumentacji składanej z wnioskiem. Powyższe nie wymaga podjęcia kroków legislacyjnych.\\n\\tOrganizacja Pracodawców Przemysłu Medycznego TECHNOMED\\tArt. 1 pkt 20 projektu odnoszący się do art. 20 ust. 7 ustawy \\frefundacyjnej\\t\\t\\fWnioskujemy aby kandydat do Komisji Ekonomicznej wykazał się również wiedzą z zakresu wyrobów medycznych\\tSegment wyrobów medycznych podczas negocjacji często spotyka się z brakiem informacji po stronie Komisji. Dlatego też proponujemy następujące brzmienie: \\fKandydat na członka Komisji składa ministrowi właściwemu do spraw zdrowia życiorys, wraz z dokumentami potwierdzającymi ukończenie kursu lub studiów w zakresie oceny technologii medycznych, wyrobów medycznych i medycyny opartej na dowodach naukowych lub ustalania cen leków oraz doświadczenie i dorobek zawodowy odpowiednie dla realizacji zadań w Komisji.”\\t\\fUwaga niezasadna Należy wskazać, że od wielu lat członkiem Komisji Ekonomicznej jest Zastępca Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych. Nawet jeżeli nie \\fbierze udziału w negocjacjach cenowych dla wyrobów medycznych, to jest obecny na posiedzeniach Komisji Ekonomicznej, podczas których zapadają uchwały. Jednocześnie projekt zakłada zmiany w zakresie art. 20 ustawy o refundacji, poprzez dodanie ust. 7, który nakłada na kandydata na członka Komisji obowiązek składa Ministrowi Zdrowia życiorys, wraz z dokumentami potwierdzającymi ukończenie kursu lub studiów w zakresie oceny technologii medycznych, medycyny opartej na dowodach naukowych lub ustalania cen leków oraz doświadczenie i dorobek zawodowy odpowiednie dla realizacji zadań w Komisji.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 21 projektu dotyczący art. 24 ust. 1a ustawy refundacyjnej\\t\\t1a. W przypadku wniosku, o którym mowa w art. 24 ust. 1 pkt 2, złożonego w okresie pierwszych 12 miesięcy obowiązywania pierwszej decyzji administracyjnej o objęciu refundacją wydanej obowiązującej po zaistnieniu okoliczności, o której mowa w art. 11 ust. 3a wygaśnięciu okresu wyłączności rynkowej, o którym mowa w art. 15 ust. 2 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, wniosek taki nie wywołuje skutku prawnego i pozostawia się go bez rozpoznania.\\tMinisterstwo Zdrowia zaproponowało bardzo dobrą poprawkę mającą na celu umożliwienie składania wniosków o podwyższenie ceny przed wystąpieniem sytuacji opisanej w art. 11 ust. 3a (tj. wygaśnięciem okresu wyłączności rynkowej). Jednak w związku z tym, że w art. 11 ust. 3a wskazuje się, że takie skrócenie decyzji (i w konsekwencji obniżenie ceny) następuje raz jednorazowo dla danego leku to celem uspójnienia treści przepisów, w niniejszym artykule należy referować do okoliczności z art. 11 ust. 3a. \\tPozostawienie obowiązującego brzmienia mogłoby rodzić wątpliwości czy przepis ma zastosowanie raz czy każdorazowo w przypadku wygasania poszczególnych wyłączności rynkowych \\f(co może mieć miejsce np. w przypadku leków sierocych).\\t\\fUwaga zasadna \\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa/ Związek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 24 ust. 6aa i 6ab ustawy refundacyjnej \\t\\tWykreślenie przepisów\\t\\tKonieczne jest usunięcie tego przepisu, ponieważ w chwili składania wniosku refundacyjnego wnioskodawca bazuje na dynamicznie zmieniających się danych, każdorazowo dochowując należytej staranności. \\tOsoby podpisujące wnioski refundacyjne działają zgodnie ze swoją najlepszą wiedzą, jednak nie zawsze mając możliwość zweryfikowania pozyskanych danych w oparciu o zewnętrzne źródła. \\t \\tUzasadnienie INFARMA: \\tKonieczne jest usunięcie tego przepisu ponieważ w chwili składania wniosku refundacyjnego wnioskodawca bazuje na dynamicznie zmieniających się danych dostarczanych często przez osoby trzecie. Osoby podpisujące wnioski refundacyjne działają zgodnie ze swoją najlepszą wiedzą, jednak nie zawsze mając możliwość zewnętrznego zweryfikowania pozyskanych danych.  \\tNie ma 100% pewności co do aktualności danych w szczególności, gdy w danym kraju przedstawicielem podmiotu jest inna spółka, na którą wnioskodawca nie może prawnie oddziaływać.  Mając to na uwadze niezasadne jest funkcjonowanie odpowiedzialności karnej – taka sankcja jest niepropozycjonalna do zakresu przekazywanych informacji.\\tUwaga niezasadna  Organ nie widzi możliwości usunięcia przepisu art. 24 ust. 6aa i 6ab ustawy o  refundacyji, nakładającego na wnioskodawcy obowiązek złożenia oświadczenia o odpowiedzialności karnej za składanie fałszywych oświadczeń z art. 233 § 6 ustawy z dnia 6 czerwca 1997 r. - Kodeks karny. Oświadczenie to zapewnia dochowanie rzetelności i wiarygodności postępowań administracyjnych oraz chroni interesu publicznego i finansów państwa. Usunięcie obowiązku złożenia oświadczenia przełożyłoby się na osłabienie mechanizmów zabezpieczających uczciwość postępowań i mogłoby prowadzić do niechlujnego składania dokumentów, co skutkowałoby wydłużeniem czasu postępowań oraz mogłoby zwiększyć obciążenia finansowe i inwestycyjnych ze strony państwa.   Brak proponowanego przepisu powodował swobodne  podchodzenie przez wnioskodawców  do obowiązków podawania danych we wnioskach a czasami wręcz podawania nieprawdziwych danych\\n\\tPolski Związek Pracodawców \\fPrzemysłu Farmaceutycznego\\t\\fArt. 24 ust. 6aa-6ab\\t6aa. Składający wniosek oświadcza pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń z art. 233 \\f§ 6 ustawy z dnia 6 czerwca 1997 r. - Kodeks karny, że dane zawarte we wniosku oraz informacje i dokumenty, o których mowa w ust. 2, są zgodne z prawdą. Składający deklarację jest obowiązany dołączyć do wniosku klauzulę o następującej treści: \\\"Jestem świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia.\\\". Klauzula ta zastępuje pouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń. \\t6ab. Oświadczenie, o którym mowa w ust. 6aa, nie dotyczy dokumentów, o których mowa w art. 25 pkt 14 lit. a oraz c, art. 25a pkt 14 lit. a-c, art. 25b pkt 14, art. 26 pkt 1 lit. h, pkt 2 lit. h oraz i, art. 28 pkt 7 lit. a i art. 29 pkt 5.\\t\\fNowelizacja z dnia 17 sierpnia 2023 r. wprowadziła rygor odpowiedzialności karnej za składanie fałszywych \\foświadczeń za dane podane we wniosku o refundację.  Wprowadzone rozwiązanie nie ma precedensu w polskim systemie prawnym. Przepisy innych ustaw, które przewidują odpowiedzialność karną za podanie określonych informacji, są powiązane z sytuacjami, w których osoba podlegająca takiej odpowiedzialności rzeczywiście ma i powinna mieć osobistą wiedzę na temat okoliczności, które poświadcza. Tymczasem wniosek refundacyjny zawiera szereg załączników obejmujących ogromną ilość danych rynkowych, medycznych i prawnych, także dotyczących innych rynków niż rynek polski. Nie jest możliwe, aby jedna osoba – podpisująca wniosek – posiadała komplet wiedzy fachowej i faktograficznej, która jest potrzebna, aby ręczyć za wszystkie dane pod rygorem odpowiedzialności karnej, ze względu na ich naukowy i wyspecjalizowany charakter.  Należy podkreślić, że osoba podpisująca wniosek, jak również inne zaangażowane w jego tworzenie osoby po stronie wnioskodawcy, i tak ponoszą odpowiedzialność prawną, w tym karną, za ewentualne świadome posłużenie się nieprawdziwymi danymi na podstawie art. 272 i 273 Kodeksu karnego.  Mając na uwadze powyższe, postulujemy usunięcie ww. przepisu. \\t\\fUwaga niezasadna  j.w.  Ustawa o refundacji i postępowania refundacyjne nie są jedynym przykładem, gdzie występuje nakładanie na Strony taki obowiązek. Przykładem może być art. 16 ust. 18b czy art. 62be ustawy energetycznej (Dz.U. z 2024 r. poz. 266, z późn. zm.).\\n\\tAmerykańska Izba Handlowa w Polsce/Pracodawcy RP\\tArt. 24 ust. 6aa ustawy refundacyjnej\\t\\tW art. 24 proponujemy uchylenie ust. 6aa.\\tWprowadzenie do ustawy przepisu przewidującego odpowiedzialność karną dla osób podpisujących wnioski \\frefundacyjne za prawdziwość danych i informacji w nich zawartych jest niewspółmiernie dolegliwe w stosunku do faktycznej możliwości weryfikacji otrzymywanych przez te osoby danych i informacji.  Biorąc pod uwagę wiedzę MZ odnośnie do tego, że każdy wniosek o objęcie refundacją stanowi kompilację danych i informacji zbieranych od osób pełniących różne funkcje, bardzo często zlokalizowanych w różnych krajach, dość niezrozumiałym było obarczenie osoby składającej wniosek odpowiedzialnością karną za ich prawdziwość. Osoby, które podpisują w Polsce wniosek zawierający szereg informacji, np. odnośnie refundacji danego produktu w innych krajach, nie mają żadnej możliwości weryfikacji tych danych. Muszą one uwierzyć innym osobom z danej organizacji, że dane te są rzetelne. Należy także pamiętać, że spółki z danej grupy kapitałowej są odrębnymi bytami prawnymi w poszczególnych krajach, które niezależnie od informacji wymaganych w Polsce, są indywidualnie zobowiązane do ochrony tajemnicy przedsiębiorstwa zgodnie z przepisami prawa lokalnego. W szczególności dotyczy to poufnych ustaleń poczynionych z odpowiednimi organami w tych krajach w zakresie cen \\fefektywnych oraz instrumentów dzielenia ryzyka. MZ mając dostęp do systemu EURIPID jest w stanie zweryfikować ceny obowiązujące w krajach UE/EFTA tak naprawdę bez konieczności ich podawania przez wnioskodawców. Powszechnie wiadomo też, że rozbieżności pomiędzy danymi we wniosku oraz danymi w EURIPID pojawiały się często i zawsze znajdowały logiczne uzasadnienie, wynikające ze specyfiki funkcjonowania danego rynku czy zakresu danych prezentowanych przez EURIPID.  Należy podkreślić, że przedawnienie przestępstwa stypizowanego w art. 24 ust. 6aa może wynieść nawet 25 lat, co w połączeniu z zagrożeniem wysoką karą pozbawienia wolności od samego początku i niezmiennie powoduje duże obawy przed podpisywaniem wniosków. Dzieje się tak nie dlatego, że dane są lub mogą być błędne, ale ze względu na trudne do przewidzenia konsekwencje zwykłej rozbieżności danych i sposobu prowadzenia negocjacji przez niektóre zespoły negocjacyjne Komisji Ekonomicznej.\\t\\fUwaga niezasadna  j.w.\\n\\tPolskie Towarzystwo Farmakoekonomiczne \\t art. 24 ust. 6aa i 6ab ustawy \\t Kwestie związane z odpowiedzialnością karną za oświadczenia o dostępności produktu wymagają rewizji.  \\t\\t W art. 24 ust. 6aa i 6ab UR proponujemy zastąpienie odpowiedzialności karnej innymi formami zabezpieczenia dostaw, które byłyby bardziej proporcjonalne i pragmatyczne.   \\f• Odpowiedzialność karna za oświadczenia dotyczące przyszłej dostępności leku jest nieproporcjonalna i nieefektywna. Bardziej skutecznym rozwiązaniem jest uzależnienie wydania decyzji refundacyjnej od faktycznego dostarczenia dowodu dostępności leku. Taka sankcja (opóźnienie wejścia do refundacji) jest wystarczająco motywująca dla wnioskodawców, a jednocześnie nie naraża pracowników na nieuzasadnioną odpowiedzialność karną (w Art. 25 pkt 3 UR).  \\t\\fUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony \\fnajpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 24 ust. 6e\\t\\t6e. Decyzje, postanowienia oraz inne pisma wydane w toku postępowania w sprawie refundacji leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego prowadzonego za pomocą SOLR uznaje się za doręczone z chwilą ich podpisania i umieszczenia w skrzynce odbiorcy.\\tNowelizacja z dnia 17 sierpnia 2023 r. wprowadziła zasadę doręczenia pism w SOLR z chwilą ich zamieszczenia w systemie. Jest to zasada niemająca odpowiednika w innych postępowaniach. Samo zamieszczenie pisma w systemie informatycznym nie jest równoznaczne z jego odbiorem przez adresata.  Wprowadzony przepis może prowadzić do pozbawienia strony prawa udziału w postępowaniu, a w konsekwencji prowadzić do wznawiania postępowań administracyjnych. Proponujemy powrót do dotychczasowych rozwiązań.\\tUwaga niezasadna Fikcja doręczenia jest uregulowana również w kodeksie postępowania administracyjnego i znajduje zastosowanie do wszelkich pism procesowych i materialnoprawnych organów administracji publicznej, od których doręczenia uzależnione jest przebieg postępowań, czy zmiana terminów procesowych.  Postępowania refundacyjne są obarczone terminami, praca w zespole jest dynamiczna i musi działać sprawnie. Adresat (Wnioskodawca) otrzymuje powiadomienia o wpływie pism oraz jest w powinności dbania o odbiór korespondencji w systemie. Brak reakcji (fizycznego kliknięcia odebrania pisma) nie może blokować dalszych prac podczas prowadzenia postępowania administracyjnego. Obowiązek do stałego monitorowania systemu jest traktowany jak standard należytej \\fstaranności. Przywracając poprzedni stan prawny Wnioskodawca otrzymuje narzędzie opóźniania procesu refundacyjnego, które w razie potrzeby może wykorzystać na swoją korzyść.\\n\\tAffordable Medicines Europe\\tArt. 1 pkt 22 lit. a projektu dotyczący art. 25 pkt 3  ustawy refundacyjnej\\t\\tProponujemy, aby art. 30 zawierał wyłączenia dla podmiotów prowadzących handel równoległy w celu wypełnienia obowiązków wynikających z art. 25 pkt 3, art. 25 pkt \\t4 i art. 25 pkt 8 oraz art. 25 pkt 14. \\tW szczególności chcielibyśmy zwrócić uwagę na art. 25 ust. 4 i wymóg, który wprowadza. Obowiązek zapewnienia ciągłości dostaw, czyli innymi słowy publiczny obowiązek dostaw (PSO) z rozszerzoną odpowiedzialnością za wskazanie rocznej ilości dostaw na miesiąc jest również wysoce problematyczny. Uważamy za ważne wyjaśnienie, że mechanizm działania handlu równoległego opiera się na nadwyżkach magazynowych na rynkach państw członkowskich UE, a nie na faktycznej produkcji leków. \\tSpełnienie obowiązku PSO jest podstawową odpowiedzialnością oryginalnych producentów, por. Dyrektywa Lekowa 2001/83/WE art. 81. Ponieważ oryginalni producenci mają pełny dostęp i kontrolę nad produkcją leków, ich przestrzeganie PSO i zapewnienie wystarczającej podaży leków na rynek jest kluczowe dla zapobiegania zakłóceniom na rynku. Biorąc pod uwagę, zgodnie z \\fprawem unijnym, że równolegli importerzy nie powinni być zobowiązani do spełnienia PSO ani rozszerzonej odpowiedzialności za wskazanie rocznej ilości dostaw na miesiąc, oczekujemy przeglądu ram refundacyjnych pomijających takie wymagania. W związku z tym mamy nadzieję na rewizję art. 25 (4) z późniejszym wyłączeniem podmiotów handlujących równolegle.\\t\\fW związku z tym wzywamy do rewizji art. 25 ust. 4 i wyłączenia z niego handlarzy równoległych.\\tUwaga niezasadna Wymóg przedłożenia wraz z wnioskiem refundacyjnym dowodu dostępności danego produktu leczniczego w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w chwili składania wniosku lub oświadczenie wnioskodawcy o zapewnieniu dostępności od dnia wejścia w życie decyzji administracyjnej o objęciu refundacją stanowi kluczowy mechanizm gwarancyjny w systemie refundacyjnym, służący ochronie interesu pacjentów.  Postulat wyłączenia importerów równoległych spod obowiązywania wskazanych przepisów jest nieuzasadniony prowadziłby bowiem do sytuacji, w której produkt zostaje objęty refundacją i umieszczony w obwieszczeniu Ministra Zdrowia jako dostępny dla pacjenta, pomimo braku rzeczywistej dostępności w aptekach. Uchylenie tego obowiązku skutkowałoby wprowadzaniem w błąd pacjentów oraz świadczeniodawców co do możliwości nabycia refundowanego leku, co pozostawałoby w sprzeczności z intencją ustawodawcy, aby decyzja refundacyjna przekładała się na faktyczną dostępność terapeutyczną produktu od momentu wejścia jej w życie.  \\fRefundacja leków stanowi instrument polityki zdrowotnej państwa, którego celem jest nie tylko obniżenie kosztów ponoszonych przez pacjenta poprzez częściowe finansowanie ceny produktu leczniczego, lecz także zapewnienie jego faktycznej dostępności na rynku. Realizacja tego celu wymaga, aby podmiot odpowiedzialny nie posiadał pełnej swobody w zakresie wielkości i regularności dostaw, co pozwala na uniknięcie sytuacji, w której nie zostanie dostarczona ilość niezbędna dla zabezpieczenia potrzeb wszystkich pacjentów. Udział w systemie refundacji ma charakter swoistego kontraktu zawieranego pomiędzy podmiotem odpowiedzialnym a Ministrem Zdrowia – w zamian za dostęp do rynku refundowanego na określonych zasadach podmiot odpowiedzialny zobowiązany jest do realizacji określonych obowiązków, w tym w szczególności do zapewnienia nieprzerwanej dostępności produktu w aptekach w skali odpowiadającej potrzebom pacjentów. Weryfikacja całkowitego zapotrzebowania dokonywana jest przy tym na podstawie udziału produktu w grupie limitowej, a nie w oparciu o indywidualne wnioski. Z tego względu zasadne jest wprowadzenie obowiązku zapewnienia ciągłości dostaw wraz ze wskazaniem rocznej wielkości dostaw w ujęciu miesięcznym, przy czym \\fobowiązek ten dotyczy również importerów równoległych Jednocześnie należy podkreślić, że wnioskodawcy korzystający z procedury importu równoległego nie będą objęci obowiązkiem wynikającym z art. 34 ustawy refundacyjnej. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 25 pkt 3\\tArt. 25 Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, zawiera: (…) 3) dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, złożony do akt sprawy do dnia zakończenia postępowania, w chwili składania wniosku lub oświadczenie wnioskodawcy o zapewnieniu dostępności od dnia wejścia w życie decyzji administracyjnej o objęciu refundacją, złożone pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń przewidzianej w art. 233 § 6 ustawy z dnia 6 czerwca 1997 r. – Kodeks karny, że dane zawarte w oświadczeniu są zgodne z prawdą. Do oświadczenia wnioskodawca jest obowiązany dołączyć klauzulę o następującej treści: „Jestem świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia.”. Klauzula ta zastępuje pouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń. W przypadku produktu leczniczego terapii zaawansowanej – zobowiązanie do zapewnienia gotowości technologicznej do jego wytworzenia na dzień składania wniosku; \\t\\t\\fPZPPF popiera propozycję wprowadzenia oświadczenia o zapewnieniu dostępności produktu od dnia wejścia w życie decyzji refundacyjnej, jako alternatywy wobec przedstawienia dowodu dostępności. Jest to niezwykle ważny krok w celu urzeczywistnienia zasady dostępu pacjentów do refundowanych terapii od pierwszego dnia po wygaśnięciu ochrony patentowej. Dopiero to rozwiązanie pozwala też w pełni wykorzystać uprawnienia, jakie producentom generycznym przyznała zmiana prawa unijnego w zakresie wprowadzenia tzw. wyjątku wytwórczego od Dodatkowego Prawa Ochronnego.  Jednocześnie wskazujemy, że rygor odpowiedzialności karnej nie jest potrzebny w tym przepisie, ponieważ stanowi superfluum względem art. 24 ust. 6aa. Zgodnie z tym ostatnim przepisem osoba składająca wniosek ponosi taką odpowiedzialność za prawdziwość wszystkich danych zawartych we wniosku, poza wyraźnie wyłączonymi, do których ww. oświadczenie nie należy. Należy więc uznać, że art. 24 ust. 6aa stanowi wyczerpującą gwarancję prawdziwości oświadczenia. \\fDruga uwaga dotyczy dowodu dostępności. PZPPF popiera utrzymanie tego wymogu jako alternatywnego względem oświadczenia. Jednocześnie, mając na uwadze wcześniejsze zapowiedzi MZ, jak również realizację zasady możliwie wczesnej dostępności produktów po wygaśnięciu ochrony patentowej, apelujemy o przesunięcie momentu przedstawienia dowodu dostępności na koniec postępowania (nie na początku). Dzięki temu wymóg ten nie będzie blokował złożenia wniosku (w sytuacji gdy ochrona patentowa dobiega końca, ale formalnie jeszcze uniemożliwia obrót lekiem generycznym). Pozwoli to na przyspieszenie objęcia leku generycznego refundacją co najmniej o 1 lub 2 kwartały.\\t\\fUwaga częściowo uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji, otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary. \\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\\\ Związek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 22 lit. b projektu odnoszący się do art. 25 pkt 3 ustawy refundacyjnej \\t\\t3) dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w chwili składania wniosku lub oświadczenie zobowiązanie wnioskodawcy do zapewnienia dostępności od dnia wejścia w życie decyzji administracyjnej o objęciu refundacją, które musi być uzupełnione o dowód dostępności w okresie pomiędzy podjęciem przez Komisję uchwały a wydaniem decyzji o objęciu refundacją. złożone pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń przewidzianej w art. 233 § 6 ustawy z dnia 6 czerwca 1997 r. – Kodeks karny, że dane zawarte w oświadczeniu są zgodne z prawdą. Do oświadczenia wnioskodawca jest \\fobowiązany dołączyć klauzulę o następującej treści: „Jestem świadomy odpowiedzialności karnej za złożenie fałszywego oświadczenia.”. Klauzula ta zastępuje pouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń. W przypadku produktu leczniczego terapii zaawansowanej – zobowiązanie do zapewnienia gotowości technologicznej do jego wytworzenia na dzień składania wniosku;\\t\\fNiezasadne jest przewidywanie odpowiedzialności karnej wobec przedstawiciela wnioskodawcy (konkretnej osoby fizycznej) za złożenie oświadczenia o zapewnieniu dostępności leku.  Dostępność leku zależy od szeregu czynników wpływających na globalny łańcuch dostaw, które nie są możliwe do przewidzenia w momencie składania deklaracji.  Jednocześnie prawa pacjentów i organu są zabezpieczone przez konieczność przedstawienia dowodu dostępności na etapie rozstrzygnięcia Ministra – jak w zaproponowanym opisie. Jest to optymalny czas na przedstawienie dowodu, który gwarantuje dostępność, a \\fjednocześnie nie wymusza przedwczesnego sprowadzenia często całej partii leku, który niekiedy w momencie zakończenia procesu refundacyjnego (szczególnie przy jego przedłużeniu) musiał zostać zutylizowany ze względu na upływający termin przydatności.  Osoba, która podpisywałaby taki dokument w istocie nie miałaby wpływu na dostępność leku, a miałaby ponosić odpowiedzialność karną. Notabene przestępstwem jest tylko czyn zawiniony. Innymi słowy wina zachodzi wówczas, gdy możemy sprawcy postawić zarzut z popełnienia danego czynu zabronionego.  Zaproponowana kara jest rażąco niewspółmierna w stosunku do ewentualnego przewinienia  – jeżeli z przyczyn nieleżących po stronie  wnioskodawcy czy osoby podpisującej oświadczenie/zobowiązanie, w  momencie podjęcia pozytywnej decyzji  refundacyjnej przez Ministra Zdrowia  nadal nie będzie możliwości zapewnienia dostępności do leku, wystarczy przesunąć  wydanie decyzji na kolejny okres, tym samym umożliwiając wydanie decyzji w terminie późniejszym, a nie obciążać wnioskodawcę odpowiedzialnością karną. Warto wskazać, że dostępność leku zależy od szeregu czynników wpływających na globalny łańcuch dostaw, które nie są możliwe do przewidzenia w momencie składania oświadczenia. Uzasadnienie INFARMA: \\fKierunek zmian proponowany przez Ministerstwo Zdrowia jest bardzo dobry.  Kwestią do zmiany jest jedynie forma i rygor takiego zobowiązania.  Zdaniem INFARMA niezasadne jest nakładanie na przedstawiciela wnioskodawcy (konkretną osobę fizyczną) odpowiedzialności karnej za oświadczenie o przyszłości. Osoba, która podpisywałaby taki dokument w istocie nie miała by jak wpływać (a w konsekwencji odpowiadać karnie) na dostępność leku za 9 lub 12 miesięcy od dnia podpisania oświadczenia.  Takie rozwiązanie nie tylko nakłada niepotrzebne ryzyko odpowiedzialności karnej na konkretnego pracownika wnioskodawcy, ale także w istocie nie realizuje celu tego przepisu jakim jest zapewnienie leków pacjentom od pierwszego dnia obowiązywania decyzji.  Dlatego odpowiedzialność należy pośrednio przerzucić na wnioskodawcę – w zakresie jakim miałby obowiązek (jako organizacja, a nie konkretna osoba) przedstawić dowód dostępności leku w obrocie (np. fakturę). Taki dokument powinien być przedstawiony (załączony w ramach SOLR) przez wnioskodawcę w okresie po wydaniu uchwały KE a przed wydaniem decyzji (czyli na końcowym etapie postępowania refundacyjnego). Brak podesłania takiego dokumentu powodowałby opóźnienie wydania decyzji do czasu przedstawienia dowodu (a więc w praktyce np. wejście do refundacji w ramach kolejnego obwieszczenia refundacyjnego).  Wydaje się, że to jest najbardziej efektywna sankcja dla wnioskodawcy, \\fktóra jednocześnie realnie zabezpieczenia interesy pacjentów, oraz pozostaje neutralna dla pracowników wnioskodawcy.\\t\\fUwaga uwzględniona    Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 22 lit. a projektu dotyczący art. 25 pkt 3  ustawy refundacyjnej\\t\\tproponujemy powrót do pierwotnie rozważanego przez Ministerstwo Zdrowia rozwiązania, w postaci przesunięcia momentu składania dowodu dostępności produktu w obrocie na etap postępowania tuż przed wydaniem decyzji o refundacji.\\tArt. 25 pkt 3, art. 25a pkt 3 i art. 25b pkt 3 - dowód dostępności w obrocie W naszej ocenie zaproponowane w projekcie nowelizacji Ustawy o refundacji rozwiązanie, mające na celu umożliwienie procedowania wniosku o refundację bez dowodu dostępności produktu w obrocie, może być trudne do stosowania w praktyce, jako, że wymagałoby poświadczenia przez osobę podpisującą wniosek (pod rygorem odpowiedzialności karnej) zdarzenia przyszłego, od tej osoby niezależnego. Rozwiązanie to (w postaci oświadczenia o zapewnieniu dostępności od dnia wejścia decyzji o refundacji w życie) przenosi bowiem odpowiedzialność za zapewnienie dostępności produktu w obrocie z wnioskodawcy – zwykle spółki (podmiotu odpowiedzialnego lub jego przedstawiciela) na osobę fizyczną. Dlatego proponujemy powrót do pierwotnie rozważanego przez Ministerstwo Zdrowia rozwiązania, w postaci przesunięcia momentu składania dowodu dostępności produktu w obrocie na etap postępowania tuż przed wydaniem decyzji o refundacji. Wówczas wnioskodawcy będą mieli już możliwość przedstawienia dowodu rzeczywistej dostępności produktu w obrocie, a nie \\fwyłącznie oświadczenia, które nie spełnia swojej roli (bo nie daje gwarancji, że produkt w przyszłości, tj. na czas wejścia decyzji o refundacji w życie, faktycznie będzie dostępny). Przepisy powinny być zatem zmienione w ten sposób, żeby nałożyć na wnioskodawców obowiązek dostarczenia dowodu dostępności produktu w obrocie do dnia wydania decyzji o refundacji, pod rygorem wydania decyzji odmownej.  \\t\\fUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary. \\n\\tAmerykańska Izba Handlowa w Polsce/ Pracodawcy RP\\tArt. 1 pkt 22 lit. a, 23, 24 projektu dotyczący art. 25 pkt 3, art. 25a pkt 3, art. 25b pkt 3 ustawy refundacyjnej\\tUwaga łączna polegająca na zmianie pkt. 3 we wszystkich trzech artykułach w następujący sposób: \\t„3) dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w chwili składania wniosku lub oświadczenie wnioskodawcy o zapewnieniu dostępności od dnia wejścia w życie decyzji administracyjnej o objęciu refundacją, potwierdzone dowodem dostępności w obrocie najpóźniej na dzień wydania decyzji, o której mowa w art. 11. złożone pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń przewidzianej w art. 233 § 6 ustawy z dnia 6 czerwca 1997 r. – Kodeks karny, że dane zawarte w oświadczeniu są zgodne z prawdą. Do oświadczenia wnioskodawca jest obowiązany dołączyć klauzulę o następującej treści: „Jestem świadomy odpowiedzialności karnej za złożenie \\ffałszywego oświadczenia.”. Klauzula ta zastępuje pouczenie organu o odpowiedzialności karnej za składanie fałszywych oświadczeń. Brak informacji w Zintegrowanym Systemie Monitorowania Obrotu Produktami Leczniczymi o dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub przedstawienia przez wnioskodawcę dowodu dostępności w obrocie wstrzymuje wydanie decyzji. W przypadku produktu leczniczego terapii zaawansowanej - zobowiązanie do zapewnienia gotowości technologicznej do jego wytworzenia na dzień składania wniosku;\\t\\fW nawiązaniu do dyskusji podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca proponujemy modyfikację wymogu przedstawienia dowodu dostępności w taki sposób, aby zrezygnować z oświadczenia obarczonego odpowiedzialnością karną. Zgodnie z przedstawioną koncepcją, najbardziej rozsądnym momentem na udokumentowanie dostępności produktu leczniczego na terytorium Polski jest przedział pomiędzy pozytywnym rozstrzygnięciem MZ a wydaniem decyzji, którego to udokumentowanie będzie warunkiem wydania decyzji o refundacji. W oparciu o takie założenia została przygotowana propozycja KF AmCham.  Uzasadnienie Pracodawcy RP \\fW nawiązaniu do dyskusji podczas spotkania w Ministerstwie Zdrowia w dniu 2 czerwca proponujemy modyfikację wymogu przedstawienia dowodu dostępności w taki sposób, aby zrezygnować z oświadczenia obarczonego odpowiedzialnością karną. Zgodnie z przedstawioną koncepcją, najbardziej rozsądnym momentem jest przedział pomiędzy pozytywnym rozstrzygnięciem MZ a wydaniem decyzji. \\t\\fUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 22 lit. a projektu dotyczący art. 25 pkt 4 ustawy refundacyjnej\\t\\tProponujemy zatem wprowadzenie do ustawy przepisu przejściowego, który pozwoliłby na przykład na szybką zmianę zobowiązania dotyczącego wielkości dostaw lub wskazującego, że zobowiązania wyliczone w oparciu o błędny algorytm nie będą egzekwowane.\\tArt. 25 pkt 4 – usunięcie algorytmu dostaw Popieramy w całości propozycję usunięcia z przepisów Ustawy o refundacji wadliwego algorytmu dostaw, który, jak pokazała praktyka, prowadził do błędnych wyliczeń dostaw, jakie powinien realizować wnioskodawca. Jednakże zwracamy uwagę na to, że w obrocie jest obecnie wiele decyzji refundacyjnych \\nz zobowiązaniem dotyczącym dostaw ustalonym w oparciu o ten błędny algorytm. Proponujemy zatem wprowadzenie do ustawy przepisu przejściowego, który pozwoliłby na przykład na szybką zmianę zobowiązania \\fdotyczącego wielkości dostaw lub wskazującego, że zobowiązania wyliczone w oparciu o błędny algorytm nie będą egzekwowane.  \\t\\t\\fUwaga niezasadna  Wnioskodawcy mają możliwość skorzystania z wniosków o zmianę decyzji ostatecznej, poprzez zmianę deklaracji dostaw, w trybie art. 155 Kpa. Minister Zdrowia rozpatruje takie wnioski od 2024 r.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 22 lit. b projektu odnoszący się do art. 25 pkt 6 lit.a  ustawy refundacyjnej\\t6) wnioskowane warunki objęcia refundacją, w szczególności: a) wskazania, w których lek, środek spożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny ma być refundowany, wraz z podaniem kodów Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO), (…) \\tPostulujemy usunięcie przepisu dotyczącego obowiązku wskazywania kodów Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych (ICD) sporządzonej przez WHO. Obecny przepis jest fragmentaryczny i niepowiązany normatywnie z systemem refundacji, co prowadzi do braku jasności co do jego celu i skutków stosowania. Taki stan prawny może generować niezamierzone, niepożądane różnice w warunkach refundacji poszczególnych produktów, co z kolei w praktyce może prowadzić do nierównego traktowania pacjentów i wnioskodawców. W naszej ocenie propozycja ta jest przedwczesna i niespójna z ogólną konstrukcją systemu refundacyjnego, dlatego postulujemy jej wykreślenie.\\tUwaga niezasadna  Projekt wprowadza rozwiązania ustawowe mające na celu zautomatyzowanie określania poziomu odpłatności na recepcie. Wprowadzenie tego rozwiązania wymaga, oprócz szeregu zmian systemowych, również zmian legislacyjnych. Jako najistotniejsze wśród proponowanych zmian wskazać należy ustanowienie narzędzia informatycznego, z którego fakultatywnie będzie mogła korzystać osoba wystawiająca receptę, a które będzie wskazywało właściwy – w danych okolicznościach – poziom odpłatności refundacyjnej. Narzędzie to będzie z jednej strony działało bazując na określonych ustawieniach wprowadzanych doń w cyklicznych interwałach czasowych w oparciu o obowiązujące w danym czasie wykazy refundacyjne, z drugiej strony w oparciu o aktywnie wprowadzane do niego, przez wystawiającego receptę, informacje o danej jednostce chorobowej scharakteryzowanej kodem Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych, w związku, z którym preskrypcja następuje. Powyższe uzasadnia wprowadzenie wymogu formalnego wniosku refundacyjnego w postaci wskazania, w których lek, środek \\fspożywczy specjalnego przeznaczenia żywieniowego, wyrób medyczny ma być refundowany, wraz z podaniem kodów Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO).\\n\\tOgólnopolska Izba Gospodarcza Wyrobów Medycznych POLMED\\tArt. 1 pkt 22 lit. b projektu odnoszący się do art. 25 pkt 6 ustawy refundacyjnej\\tw pkt 6: -lit. a otrzymuje brzmienie: „a) wskazania, w których lek, wyrób medyczny lub środek spożywczy specjalnego przeznaczenia żywieniowego ma być refundowany, a w przypadku leków i środków spożywczych specjalnego przeznaczenia żywieniowego wraz z podaniem kodów Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO), W przypadku wyrobu medycznego brak podania konkretnego kodu lub kodów skutkować będzie przypisaniem do wyrobu medycznego w danym wskazaniu wszystkich istniejących kodów Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO).”, - w lit. g w tiret czwarte średnik zastępuje się przecinkiem i dodaje się lit. h w brzmieniu: „h) projekt opisu refundowanych wskazań dla leków w kategorii refundacyjnej, o \\fktórej mowa w art. 6 ust. 1 pkt 2a i 3, jeżeli dotyczy, zawierający: nazwę substancji czynnej, zakres wskazań do stosowania wraz z obowiązującym kodem Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO), szczegółowe warunki do zastosowania;”,\\t\\fStworzenie kompletnego katalogu kodów Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO) przypisanych do wyrobów medycznych stosowanych we wskazaniach takich jak np. przewlekłe owrzodzenie, w inny sposób, niż przypisanie do wyrobu medycznego wszystkich istniejących kodów ICD, jest zadaniem praktycznie niemożliwym. Kazuistyczne zawężanie kodów w praktyce zawsze będzie skutkowało pominięciem jednostki chorobowej rodzącej ryzyko powstania rany wymagającej zaopatrzenia, nawet przy zachowaniu najwyższej staranności przy mapowaniu kodów. Dodatkowo zawężenie kodów może być interpretowane jako nieuprawnione zawężenie w stosunku do instrukcji użytkowania. Z powyższych względów właściwym rozwiązaniem jest stworzenie mechanizmu pozwalającego na automatyczne przypisanie wyrobom opatrunkowym wszystkich kodów ICD, co pozwoli na uniknięcie ryzyka pozbawienia pacjentów dostępu do przysługujących im świadczeń. W przypadku pozostałych wyrobów, w przypadku których możliwe jest wskazanie konkretnych kodów ICD, \\fstosować się będzie zasady właściwe jak dla produktów leczniczych. \\tEwentualnym alternatywnym rozwiązaniem mogłoby być wdrożenie w SOLR funkcjonalności pozwalającej wnioskodawcy na wybór  zdefiniowanego w SOLR „pakietu” kodów przypisanych przez system do określonego wskazania, tak aby uniknąć konieczności ręcznego wpisywania kilku tysięcy kodów do każdego wniosku – co generowałoby bardzo duży nakład pracy zarówno po stronie wnioskodawcy, jak też organu.  \\t\\fUwaga częściowo zasadna Organ uznaje za zasadne dopisanie, że przepis dotyczy również wyrobów medycznych i środków spożywczych specjalnego przeznaczenia żywieniowego. Jednak Organ nie widzi możliwości wprowadzenia do przepisów ustawy dalszej części zgłoszonej uwagi. Refundacją objętych jest wiele wyrobów medycznych w różnych wskazaniach refundacyjnych, np. igły do penów, paski do pomiaru glukozy we krwi, a zgłoszona uwaga odnosi się wyłącznie do wskazania \\\"przewlekłe owrzodzenia\\\". Jako rozwiązanie bardziej adekwatne, jak również zapewniające spójność w zakresie proponowanych przez różnych wnioskodawców kodów ICD-10 (dla wszystkich rodzajów produktów refundowanych), Organ uznaje stworzenie możliwości przypisywania wnioskowanym produktom predefiniowanych wcześniej w systemie SOLR kodów ICD-10.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 22 lit. b projektu dotyczący art. 25 pkt 6 lit. h ustawy refundacyjnej\\tSkreślić h) projekt opisu refundowanych wskazań dla leków w kategorii refundacyjnej, o której mowa w art. 6 ust. 1 pkt 2a i 3, jeżeli dotyczy, zawierający: – nazwę substancji czynnej, – zakres wskazań do stosowania wraz z obowiązującym kodem Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych sporządzonej przez Światową Organizację Zdrowia (WHO), – szczegółowe warunki do zastosowania; Alternatywnie wprowadzić zaproponowaną zmianę do art. 11 ust. 5b.\\tZobacz uzasadnienie do art. 11 ust. 5b ustawy refundacyjnej.\\tUwaga niezasadna Organ nie widzi możliwości wprowadzenia zaproponowanego przepisu art. 11 ust. 5b ustawy o refundacji, ponieważ zarówno program, jak i grupa limitowa nie są elementem decyzji administracyjnej, więc nie mogą być objęte porozumieniem RSS ponieważ mogą ulec zmianie w trakcie obowiązywania decyzji refundacyjnej. Jeżeli w opinii Wnioskodawcy istnieje konieczność zmiany treści programu lekowego lub grupy limitowej istnieje możliwość złożenia wniosku o skrócenie obowiązywania decyzji (art. 24 ust. 1 pkt 5) lub złożenie wniosku o zmianę z art. 155 kpa. Minister Zdrowia odstąpił od regulacji dotyczącej tzw. 4 kategorii dostępności.  Jednocześnie obowiązek przedstawiania wskazań do stosowania wraz z \\fobowiązującym kodem Międzynarodowej Statystycznej Klasyfikacji Chorób i Problemów Zdrowotnych powiązany jest z kompleksowy zmianami dotyczącymi przygotowania usprawnienia dla osób wystawiających recepty w zakresie automatyzmu określania odpłatności pacjenta za produkt leczniczy.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 23 projektu dotyczący art. 25a pkt 3 ustawy refundacyjnej\\t3) dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w chwili składania wniosku lub oświadczenie zobowiązanie wnioskodawcy o zapewnieniu dostępności od dnia wejścia w życie decyzji administracyjnej o objęciu refundacją, które musi być uzupełnione o dowód dostępności w okresie pomiędzy podjęciem przez Komisję uchwały a wydaniem decyzji o objęciu refundacją. złożone pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń przewidzianej w art. 233 § 6 ustawy z dnia 6 czerwca 1997 r. – Kodeks karny, że dane zawarte w oświadczeniu są zgodne z prawdą. Do oświadczenia wnioskodawca jest obowiązany dołączyć klauzulę o następującej treści: „Jestem świadomy odpowiedzialności karnej za złożenie fałszywego  oświadczenia.”.  Klauzula  ta  zastępuje  pouczenie  organu o odpowiedzialności karnej za składanie fałszywych oświadczeń. W przypadku produktu leczniczego terapii zaawansowanej – zobowiązanie do zapewnienia gotowości technologicznej do jego wytworzenia na dzień składania wniosku;\\tZobacz uzasadnienie do art. 25a pkt 3 UR.\\tUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 23 projektu dotyczący art. 25a pkt 3 ustawy refundacyjnej\\tproponujemy powrót do pierwotnie rozważanego przez Ministerstwo Zdrowia rozwiązania, w postaci przesunięcia momentu składania dowodu dostępności produktu w obrocie na etap postępowania tuż przed wydaniem decyzji o refundacji.\\tArt. 25 pkt 3, art. 25a pkt 3 i art. 25b pkt 3 - dowód dostępności w obrocie W naszej ocenie zaproponowane w projekcie nowelizacji Ustawy o refundacji rozwiązanie, mające na celu umożliwienie procedowania wniosku o refundację bez dowodu dostępności produktu w obrocie, może być trudne do stosowania w praktyce, jako, że wymagałoby poświadczenia przez osobę podpisującą wniosek (pod rygorem odpowiedzialności karnej) zdarzenia przyszłego, od tej osoby niezależnego. Rozwiązanie to (w postaci oświadczenia o zapewnieniu dostępności od dnia wejścia decyzji o refundacji w życie) przenosi bowiem odpowiedzialność za zapewnienie dostępności produktu w obrocie z wnioskodawcy – zwykle spółki (podmiotu odpowiedzialnego lub jego przedstawiciela) na osobę fizyczną. Dlatego proponujemy powrót do pierwotnie rozważanego przez Ministerstwo Zdrowia rozwiązania, w postaci przesunięcia momentu składania dowodu dostępności produktu w obrocie na etap postępowania tuż przed wydaniem decyzji o refundacji. Wówczas wnioskodawcy będą mieli już możliwość przedstawienia dowodu rzeczywistej dostępności produktu w obrocie, a nie wyłącznie oświadczenia, które nie spełnia swojej roli (bo nie daje gwarancji, że produkt w przyszłości, tj. na czas wejścia decyzji o refundacji w życie, \\ffaktycznie będzie dostępny). Przepisy powinny być zatem zmienione w ten sposób, żeby nałożyć na wnioskodawców obowiązek dostarczenia dowodu dostępności produktu w obrocie do dnia wydania decyzji o refundacji, pod rygorem wydania decyzji odmownej.  \\t\\fUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 24 projektu dotyczący art. 25b pkt 3 ustawy refundacyjnej\\t3) dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w chwili składania wniosku lub oświadczenie zobowiązanie wnioskodawcy o zapewnieniu dostępności od dnia wejścia w życie decyzji administracyjnej o objęciu refundacją, które musi być uzupełnione o dowód dostępności w okresie pomiędzy podjęciem przez Komisję uchwały a wydaniem decyzji o objęciu refundacją. złożone pod rygorem odpowiedzialności karnej za składanie fałszywych oświadczeń przewidzianej w art. 233 § 6 ustawy z dnia 6 czerwca 1997 r. – Kodeks karny, że dane zawarte w oświadczeniu są zgodne z prawdą. Do oświadczenia wnioskodawca jest obowiązany dołączyć klauzulę o następującej treści: „Jestem świadomy odpowiedzialności karnej za złożenie fałszywego  oświadczenia.”.  Klauzula  ta  zastępuje  pouczenie  organu o odpowiedzialności karnej za składanie fałszywych oświadczeń. W przypadku produktu leczniczego terapii zaawansowanej – zobowiązanie do zapewnienia gotowości technologicznej do \\fjego wytworzenia na dzień składania wniosku;\\t\\fZobacz uzasadnienie do art. 25a pkt 3 UR.\\tUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 24 projektu dotyczący art. 25b pkt 3 ustawy refundacyjnej\\tproponujemy powrót do pierwotnie rozważanego przez Ministerstwo Zdrowia rozwiązania, w postaci przesunięcia momentu składania dowodu dostępności produktu w obrocie na etap postępowania tuż przed wydaniem decyzji o refundacji.\\tArt. 25 pkt 3, art. 25a pkt 3 i art. 25b pkt 3 - dowód dostępności w obrocie W naszej ocenie zaproponowane w projekcie nowelizacji Ustawy o refundacji rozwiązanie, mające na celu umożliwienie procedowania wniosku o refundację bez dowodu dostępności produktu w obrocie, może być trudne do stosowania w praktyce, jako, że wymagałoby poświadczenia przez osobę podpisującą wniosek (pod rygorem odpowiedzialności karnej) zdarzenia przyszłego, od tej osoby niezależnego. Rozwiązanie to (w postaci oświadczenia o zapewnieniu dostępności od dnia wejścia decyzji o refundacji w życie) przenosi bowiem odpowiedzialność za zapewnienie dostępności produktu w obrocie z wnioskodawcy – zwykle spółki (podmiotu odpowiedzialnego lub jego przedstawiciela) na osobę fizyczną. Dlatego proponujemy powrót do pierwotnie rozważanego przez Ministerstwo Zdrowia rozwiązania, w postaci przesunięcia momentu składania dowodu dostępności produktu w obrocie na etap postępowania tuż przed wydaniem decyzji o refundacji. Wówczas wnioskodawcy będą mieli już możliwość przedstawienia dowodu rzeczywistej dostępności produktu w obrocie, a nie wyłącznie oświadczenia, które nie \\fspełnia swojej roli (bo nie daje gwarancji, że produkt w przyszłości, tj. na czas wejścia decyzji o refundacji w życie, faktycznie będzie dostępny). Przepisy powinny być zatem zmienione w ten sposób, żeby nałożyć na wnioskodawców obowiązek dostarczenia dowodu dostępności produktu w obrocie do dnia wydania decyzji o refundacji, pod rygorem wydania decyzji odmownej.  \\t\\fUwaga uwzględniona Dowód dostępności, czyli art. 25 pkt 3 ustawy o refundacji otrzyma brzmienie: ,,dowód dostępności w obrocie leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego w obrocie złożony najpóźniej na dzień wydania decyzji, o której mowa w art. 11”. Minister Zdrowia odstępuje od oświadczenia pod groźbą kary.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 25c ust. 3\\t3. Jeżeli po złożeniu wniosku kontynuacyjnego, o którym mowa w ust. 1, następuje wygaśnięcie dotychczasowej decyzji dotyczącej refundacji leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, minister właściwy do spraw zdrowia umarza postępowanie wszczęte na podstawie tego wniosku.\\tNowelizacja z dnia 17 sierpnia 2023 r. dodała przepis, zgodnie z którym w przypadku gdy po złożeniu wniosku kontynuacyjnego dojdzie do wygaśnięcia dotychczasowej decyzji dotyczącej refundacji, Minister Zdrowia umorzy postępowanie.  Decyzja wydana w wyniku wniosku kontynuacyjnego jest nową decyzją administracyjną. W związku z tym wygaśnięcie poprzedniej decyzji nie jest przyczyną bezprzedmiotowości postępowania zainicjowanego wnioskiem kontynuacyjnym i nie powinno to prowadzić do umorzenia postępowania. Przepis ten może prowadzić również do nieakceptowalnej sytuacji, w których to opóźnienie w rozpoznaniu wniosku kontynuacyjnego przez Ministra Zdrowia spowoduje, że nie zostanie on rozpoznany przed upływem terminu obowiązywania dotychczasowej decyzji refundacyjnej. Zastosowanie ww. przepisu w takiej sytuacji uniemożliwi wnioskodawcy uzyskanie kolejnej decyzji refundacyjnej, bez jego winy i ze szkodą dla pacjentów \\fleczących się lekiem objętym ww. wnioskami. Mając na uwadze powyższe, postulujemy usunięcie ww. przepisu. \\t\\fUwaga niezasadna Art. 25c ust. 3 ustawy o refundacji ma na celu doprecyzowanie rozpatrywania wniosków kontynuacyjnych. Przedmiotowy wniosek (kontynuacyjny) dotyczy produktu leczniczego znajdującego się w  wykazie i dotyczy ustanowienia granicznego terminu jego rozpoznania oraz konsekwencji wygaśnięcia  dotychczasowej decyzji refundacyjnej. Przepis ten wpisuje się również wyraźnie w całokształt regulacji jasno określających status „wniosku kontynuacyjnego”.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 25 projektu dotyczący art. Art. 25e ust. 2 pkt 2 ustawy refundacyjnej\\t2. Decyzja o przeniesieniu, o której mowa w ust. 1, jest wydawana na rzecz podmiotu, który: 1) wyraża zgodę na przyjęcie wszystkich praw i obowiązków z niej wynikających; 2) jest podmiotem odpowiedzialnym lub przedstawicielem podmiotu odpowiedzialnego dla leku, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia prawomocną decyzję Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych lub Komisji Europejskiej o zmianie podmiotu odpowiedzialnego, dotyczącą tego leku lub odpis powiadomienia odpowiedniego organu o ustanowieniu, zmianie lub odwołaniu przedstawiciela podmiotu odpowiedzialnego; 3) jest podmiotem uprawnionym dla środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków w zakresie tego środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, albo powiadomienie Głównego Inspektora Sanitarnego dla środka spożywczego specjalnego przeznaczenia żywieniowego albo Prezesa Urzędu Rejestracji Produktów \\fLeczniczych, Wyrobów Medycznych i Produktów Biobójczych dla wyrobu medycznego o zmianie podmiotu uprawnionego.\\t\\fZgodnie z obecnym brzmieniem art. 25e niemożliwe jest przeniesienie praw i obowiązków wynikających z decyzji refundacyjnej na inny podmiot, który nie jest aktualnym podmiotem odpowiedzialnym (MAH), lecz np. jego przedstawicielem. W takim przypadku zmiana wnioskodawcy powinna być możliwa bez zmiany samego MAH-a, pod warunkiem, że nowy wnioskodawca spełnia wymogi ustawowe oraz przedstawi stosowną dokumentację – w tym odpis powiadomienia odpowiedniego organu o ustanowieniu, zmianie lub odwołaniu przedstawiciela podmiotu odpowiedzialnego.  Związek pragnie podkreślić, że powyższa propozycja stanowi doprecyzowanie postulatu, który został podnoszony również w stanowisku z roku 2021 w stosunku do tzw. dużej nowelizacji ustawy refundacyjnej. Proponowana zmiana ma istotne znaczenie praktyczne, ponieważ umożliwia wskazanie nowego wnioskodawcy bez konieczności przechodzenia przez procedurę zmiany podmiotu odpowiedzialnego w myśl ustawy wskutek np. reorganizacji wewnętrznej.  \\tUwaga częściowo zasadna Zmiana przedstawiciela podmiotu odpowiedzialnego została uwzględniona w następujący sposób: „lub umowę zawartą pomiędzy podmiotem odpowiedzialnym a przedstawicielem podmiotu odpowiedzialnego, w rozumieniu przepisów ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne”\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 25 projektu dotyczący art. 25d ustawy refundacyjnej\\tz perspektywy wnioskodawców kluczowe jest, aby procedura horizon scanning nie blokowała w  o refundację, na przykład w przypadku zmiany okoliczności mających wpływ na decyzję biznesową wnioskodawcy o procedowaniu wniosku.\\tArt. 25d – horizon scanning Rozumiemy powody, dla których Ministerstwo Zdrowia chce zbierać informacje o planowanych złożeniach wniosków o refundację, jednakże projektowany przepis ustawy, obligujący wnioskodawców do informowania Ministra Zdrowia o planowanych na kolejny rok kalendarzowy wnioskach refundacyjnych, między 1 listopada a 31 grudnia, powinien jednoznacznie wskazywać, że wniosek o refundację złożony bez uprzedniego poinformowania Ministra Zdrowia będzie procedowany, a także, że na wnioskodawcę nie będą nakładane żadne sankcje z tytułu niezłożenia wniosku o refundację, którego złożenie było wcześniej zapowiadane.  Pomimo, iż wnioskodawcy co do zasady planują wcześniej złożenie wniosków o refundację, zmiana planów czy przesunięcie terminu złożenia wniosku są zawsze możliwe; zwłaszcza, jeżeli pierwotnie złożenie wniosku było planowane pod koniec roku kalendarzowego lub na jego początku. Złożenie wniosku może być zarówno przyspieszone (na przykład w sytuacji, gdy wnioskodawca poweźmie informację o złożeniu już wniosku dla \\fkonkurencyjnego produktu), albo opóźnione, na przykład na skutek opóźnień w produkcji i przesunięcia terminu wypuszczenia na rynek pierwszej serii produktu w polskich opakowaniach.  Dlatego z perspektywy wnioskodawców kluczowe jest, aby procedura horizon scanning nie blokowała w żaden sposób swobody złożenia lub niezłożenia wniosku o refundację, na przykład w przypadku zmiany okoliczności mających wpływ na decyzję biznesową wnioskodawcy o procedowaniu wniosku.\\t\\fUwaga niezasadna Projektowany zapis ma na celu umożliwienie ministrowi właściwemu do spraw zdrowia podejmowania długofalowych działań, zmierzających do wzmacniania racjonalnych aspektów procesów decyzyjnych w perspektywie ograniczonych środków przewidzianych na refundację. Projekt nie przewiduje sankcji za niewykonanie przedstawionych planów w zakresie złożenia wniosków refundacyjnych ani za ich zmianę.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 25 projektu dotyczący art. 25d ustawy refundacyjnej\\tWnioskujemy o doprecyzowanie art. 25d ust. 1 ustawy zgodnie z intencją ustawodawcy.  Proponujemy następujące brzmienie zapisu:   „Art. 25d. 1. Wnioskodawca planujący złożyć wniosek, o którym mowa w art. 24 ust. 1, dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu w następnym roku kalendarzowym ma obowiązek poinformować ministra właściwego do spraw zdrowia w terminie od dnia 1 listopada do dnia 31 grudnia roku kalendarzowego poprzedzającego złożenie wniosku, o swoim planie określając przedmiot wniosku, wskazanie do stosowania oraz szacowany wpływ na \\fbudżet podmiotu zobowiązanego do finansowania świadczeń ze środków publicznych, w związku z koniecznością zabezpieczenia w planie finansowym Narodowego Funduszu Zdrowia, o którym mowa w art. 118 ustawy o świadczeniach, środków na ten cel.” \\t\\fZgodnie z uzasadnieniem do ustawy dodanie art. 25d w ustawie refundacyjnej, ma na celu umożliwienie ministrowi właściwemu do spraw zdrowia podejmowania długofalowych działań, zmierzających do wzmacniania racjonalnych aspektów procesów decyzyjnych w perspektywie ograniczonych środków przewidzianych na refundację.  Mając na uwadze powyższe, proponujemy doprecyzowanie przedmiotowego przepisu w celu jednoznacznego wskazania, iż obowiązek informacji o planowaniu złożenia wniosku wynika bezpośrednio z konieczności zabezpieczenia w planie finansowym Narodowego Funduszu Zdrowia środków na ten cel. \\tUwaga niezasadna Projektowany zapis ma na celu umożliwienie ministrowi właściwemu do spraw zdrowia podejmowania długofalowych działań, zmierzających do wzmacniania racjonalnych aspektów procesów decyzyjnych w perspektywie ograniczonych środków przewidzianych na refundację. Projekt nie przewiduje sankcji za niewykonanie przedstawionych planów w zakresie złożenia wniosków refundacyjnych ani za ich zmianę. Jeżeli informacja pozyskiwania przez Ministra Zdrowia ma pozostać nieobligatoryjna, wówczas Ministerstwo nie ma żadnej pewności, że taki wniosek zostanie złożony, oraz jak będzie wpływ na budżet, który może się zmienić kilkukrotnie. To etap prekonsultacji będzie wiarygodnym źródłem uzyskania informacji. \\n\\tPOLSKA FEDERACJA PRODUCENTÓW ŻYWNOŚCI ZWIĄZEK PRACODAWCÓW\\tArt. 1 pkt 25 projektu dotyczący art. 25d ustawy refundacyjnej\\tProponowana zmiana zakłada zobowiązanie wnioskodawców, którzy planują złożyć wniosek refundacyjny dla produktu, który nie ma odpowiednika refundowanego w danym wskazaniu w następnym roku kalendarzowym, do poinformowania Ministra Zdrowia w terminie od dnia 1 listopada do dnia 31 grudnia roku kalendarzowego poprzedzającego złożenie wniosku, o swoim planie określając przedmiot wniosku oraz wskazanie do stosowania. W ocenie PFPŻ ZP jest to nadmiernie sformalizowany wymóg, uniemożliwiający podmiotom składanie wniosków w trakcie roku kalendarzowego, w wyniku braku złożenia stosownej informacji do MZ. PFPŻ ZP postuluje wykreślenie proponowanej zmiany z Projektu.\\t\\tUwaga niezasadna Projektowany zapis ma na celu umożliwienie ministrowi właściwemu do spraw zdrowia podejmowania długofalowych działań, zmierzających do wzmacniania racjonalnych aspektów procesów decyzyjnych w perspektywie ograniczonych środków przewidzianych na refundację. Projekt nie przewiduje sankcji za niewykonanie przedstawionych planów w zakresie złożenia wniosków refundacyjnych, ani za ich zmianę.\\n\\tOgólnopolska Izba Gospodarcza Wyrobów Medycznych POLMED\\tArt. 1 pkt 25 projektu odnoszący się do art. 25d i 25e ustawy refundacyjnej\\t„Art. 25d. 1. Wnioskodawca planujący złożyć wniosek, o którym mowa w art. 24 ust. 1, dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego, który nie ma odpowiednika refundowanego w danym wskazaniu w następnym roku kalendarzowym ma obowiązek poinformować ministra właściwego do \\fspraw zdrowia w terminie od dnia 1 listopada do dnia 31 grudnia roku kalendarzowego poprzedzającego złożenie wniosku, o swoim planie określając przedmiot wniosku oraz wskazanie do stosowania. 2. Informację, o której mowa w ust. 1, wnioskodawca składa w postaci elektronicznej przez odpowiedni formularz za pomocą SOLR.  Art. 25e. 1. Minister właściwy do spraw zdrowia może, za zgodą podmiotu, na rzecz którego została wydana decyzja o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, przenieść prawa i obowiązki wynikające z tej decyzji na inny podmiot na jego wniosek. Przeniesienie następuje w drodze decyzji administracyjnej. 2. Decyzja o przeniesieniu, o której mowa w ust. 1, jest wydawana na rzecz podmiotu, który: 1) wyraża zgodę na przyjęcie wszystkich praw i obowiązków z niej wynikających;  2) jest podmiotem odpowiedzialnym lub przedstawicielem podmiotu odpowiedzialnego dla leku, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do \\fspraw zdrowia prawomocną decyzję Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych lub Komisji Europejskiej o zmianie podmiotu odpowiedzialnego, dotyczącą tego leku; 3) jest podmiotem uprawnionym dla środka spożywczego specjalnego przeznaczenia żywieniowego lub podmiotem gospodarczym w rozumieniu art. art. 2 pkt 35 Rozporządzenia 2017/745 lub art. 2 pkt 28 rozporządzenia 2017/746 dla wyrobu medycznego, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków w zakresie tego środka spożywczego specjalnego przeznaczenia żywieniowego lub umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków wynikających z decyzji refundacyjnej w zakresie wyrobu medycznego albo inny dokument uzasadniający przeniesienie na niego praw i obowiązków wynikających z decyzji o objęciu wyrobu medycznego refundacją, albo powiadomienie Głównego Inspektora Sanitarnego dla środka spożywczego specjalnego przeznaczenia żywieniowego albo Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych dla wyrobu medycznego o zmianie podmiotu uprawnionego. \\f3. Decyzja o przeniesieniu następuje na wniosek podmiotu, który ubiega się o to przeniesienie, wyłącznie na okres, na który została wydana decyzja o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego. 4. W przypadku gdy wniosek, o którym mowa ust. 1, dotyczy leku objętego refundacją w zakresie wskazań do stosowania lub dawkowania, lub sposobu podawania odmiennych niż określone w Charakterystyce Produktu Leczniczego, o której mowa w art. 10 ust. 2 pkt 11 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, decyzja, o której mowa w ust. 1, przenosi również prawa i obowiązki wynikające z decyzji o objęciu refundacją wydane na podstawie art. 40 dla tego leku.”; \\t\\fNa skutek dodania art. 25e do ustawy o refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego oraz wyrobów medycznych w projekcie, przewidziano korzystną dla przedsiębiorców, jak i pacjentów, ścieżkę umożliwiającą przeniesienie decyzji refundacyjnej na inny podmiot (bez konieczności przechodzenia całej procedury od nowa).  \\fAby jednak ścieżka ta była korzystna, należy dopasować nomenklaturę i zakres wymagań do potrzeb każdej z kategorii produktów, których decyzja refundacyjna może dotyczyć. Należy bowiem podkreślić, że: \\tdla wyrobu medycznego nie ma instytucji podmiotu uprawnionego; \\tuzyskanie decyzji o objęciu refundacją (a następnie jej przeniesienie) nie musi być powiązane z nabyciem praw do wyrobu medycznego; \\tzłożenie powiadomienia do Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych dla wyrobu medycznego nie jest warunkiem wprowadzenia wyrobu medycznego na rynek przez kolejnego dystrybutora (nie ma tym samym takiego waloru jak pozwolenie na dopuszczenie do obrotu leku) – a wręcz w wielu przypadkach nie jest już wymagane ze względu na częściową operacyjność bazy EUDAMED oraz operacyjność wykazu dystrybutorów (który obliguje do rejestracji w wykazie wyłącznie pierwszego dystrybutora udostępniającego wyrób na terytorium Rzeczpospolitej Polskiej).  Zasadne jest więc, aby dostosować konstrukcję przepisu do specyfikacji regulacji właściwych dla wyrobów medycznych (a to Rozporządzenia Parlamentu Europejskiego i Rady (UE) 2017/745 z dnia 5 kwietnia 2017 r. w sprawie wyrobów medycznych, zmiany dyrektywy 2001/83/WE, \\frozporządzenia (WE) nr 178/2002 i rozporządzenia (WE) nr 1223/2009 oraz uchylenia dyrektyw Rady 90/385/EWG i 93/42/EWG i Ustawy  z dnia 7 kwietnia 2022 r. o wyrobach medycznych ).  Zaproponowana zmiana jest uzasadniona tym, że w przypadku wyrobów medycznych ustawodawca posługuje się inną nomenklaturą (podmiot gospodarczy a nie podmiot uprawniony), jak i inaczej skonstruowane są regulacje kształtujące ten rynek. Tym samym adresatem decyzji o objęciu refundacją wyrobu medycznego nie musi być wyłącznie producent – a może być ona wydana również na rzecz innego podmiotu gospodarczego, co oznacza zarówno producenta, upoważnionego przedstawiciela, importera, dystrybutora lub podmiot zestawiający – zgodnie z art. 2 pkt 35 Rozporządzenia 2017/745. Równocześnie, skoro decyzja o objęciu refundacją może dotyczyć również wyrobu medycznego i może zostać wydana na rzecz zarówno producenta, jak i upoważnionego przedstawiciela, importera, dystrybutora lub podmiotu zestawiającego, niezasadne byłoby aby ograniczać tym podmiotom możliwość skorzystania z nowowprowadzonej ścieżki. Zaproponowana zmiana pozwoli ograniczyć wątpliwości co do tego, czy nowa ścieżka będzie dostępna dla wszystkich decyzji o objęciu refundacją i jaki podmiot może z takiej ścieżki realnie skorzystać.  Wyrób medyczny nie jest wprowadzany na rynek na podstawie pozwolenia na dopuszczenie do obrotu (tak jak w \\fprzypadku produktu leczniczego), a wystarczające będzie wyłącznie spełnienie wymogów regulacyjnych co jest potwierdzane deklaracją zgodności wystawianą przez producenta. Tym samym nie ma możliwości, aby dla wyrobu medycznego zostało przedłożone pozwolenie czy też jakakolwiek decyzja administracyjna potwierdzająca rolę konkretnego podmiotu gospodarczego w odniesieniu do konkretnego wyrobu. Na rynku wyrobów medycznych zasadność przeniesienia decyzji o objęciu refundacją wynikać będzie w dużej mierze z umów prywatnoprawnych zawartych między przedsiębiorcami – jednak nie w każdym przypadku umowy takie muszą obejmować postanowienia o przejęciu praw i obowiązków w zakresie konkretnego wyrobu. Takie przejęcie obowiązków dotyczy bowiem tylko producenta wyrobu, natomiast w przypadku transakcji pomiędzy innymi podmiotami gospodarczymi – postanowienia mogą być inne lub dużo bardziej ograniczone.  Dlatego zasadnym będzie przeformułowanie powyższego przepisu w taki sposób, aby nie było konieczne okazywanie umowy o konkretnej treści czy – tym bardziej – powiadomienia do Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych, ponieważ nie są to przesłanki każdorazowo niezbędne, aby uzasadnić, że doszło do zmiany w zakresie podmiotu gospodarczego dla konkretnego wyrobu medycznego (objętego refundacją), a tym samym \\fuzasadnione jest przeniesienie praw i obowiązków wynikających z decyzji o objęciu refundacją na inny podmiot. W związku z szerokim zakresem transakcji i stosunków prawno-gospodarczych, z jakich może wynikać zasadność przeniesienia tych praw i obowiązków, zasadne będzie posłużenie się sformułowaniem bardziej ogólnym przy określaniu niezbędnych dokumentów do wydania takiej decyzji. Pozwoli to dostosować zakres okazywanych dokumentów do konkretnej sytuacji prawnej.\\t\\fUwaga zasadna  W projekcie zmienia art. 25e ust. 2 pkt 3 ustawy o refundacji dotyczący przeniesienia praw i obowiązków z decyzji na inny podmiot dla wyrobów medycznych na proponowane brzmienie: „3) jest podmiotem uprawnionym dla środka spożywczego specjalnego przeznaczenia żywieniowego lub podmiotem gospodarczym w rozumieniu \\fart. art. 2 pkt 35 Rozporządzenia 2017/745 lub art. 2 pkt 28 rozporządzenia 2017/746 dla wyrobu medycznego, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków w zakresie tego środka spożywczego specjalnego przeznaczenia żywieniowego lub umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków wynikających z decyzji refundacyjnej w zakresie wyrobu medycznego, albo powiadomienie Głównego Inspektora Sanitarnego dla środka spożywczego specjalnego przeznaczenia żywieniowego o zmianie podmiotu uprawnionego.” \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 25 projektu dotyczący art. 25e ustawy refundacyjnej\\tArt. 25e. 1. Minister właściwy do spraw zdrowia może, za zgodą podmiotu, na rzecz którego została wydana decyzja o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, przenieść prawa i obowiązki wynikające z tej decyzji na inny podmiot na jego wniosek. Przeniesienie następuje w drodze decyzji administracyjnej.  2. Decyzja o przeniesieniu, o której mowa w ust. 1, jest wydawana na rzecz podmiotu, który: 1) wyraża zgodę na przyjęcie wszystkich praw i obowiązków z niej wynikających; 2) jest podmiotem odpowiedzialnym lub przedstawicielem podmiotu odpowiedzialnego dla leku, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia prawomocną decyzję Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych lub Komisji \\fEuropejskiej o zmianie podmiotu odpowiedzialnego, dotyczącą tego leku lub umowę, o której mowa w art. 35a ust. 2 ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne; 3) jest podmiotem uprawnionym dla środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków w zakresie tego środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, albo powiadomienie Głównego Inspektora Sanitarnego dla środka spożywczego specjalnego przeznaczenia żywieniowego albo Prezesa Urzędu Rejestracji Produktów Leczniczych, Wyrobów Medycznych i Produktów Biobójczych dla wyrobu medycznego o zmianie podmiotu uprawnionego. 3. Decyzja o przeniesieniu następuje na wniosek podmiotu, który ubiega się o to przeniesienie, wyłącznie na okres, na który została wydana decyzja o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego. 4. W przypadku gdy wniosek, o którym mowa ust. 1, dotyczy leku objętego refundacją w zakresie wskazań do stosowania lub dawkowania, lub sposobu podawania odmiennych niż określone w Charakterystyce Produktu Leczniczego, o której mowa w art. 10 ust. 2 pkt 11 ustawy \\fz dnia 6 września 2001 r. – Prawo farmaceutyczne, decyzja, o której mowa w ust. 1, przenosi również prawa i obowiązki wynikające z decyzji o objęciu refundacją wydane na podstawie art. 40 dla tego leku.”;\\t\\fZmiana zaproponowana przez Ministerstwo Zdrowia to bardzo dobra i wyczekiwana zmiana.  Dzięki niej zarówno wnioskodawcy, jak i Ministerstwo Zdrowia unikną wielu problemów organizacyjnych. W tym zakresie zasadnym jest jedynie doprecyzowanie, że zmiana adresata decyzji refundacyjnej jest możliwa także w przypadku zmiany przedstawiciela podmiotu odpowiedzialnego (a nie tylko zmiany samego podmiotu odpowiedzialnego), na dowód czego miałaby być przedkładana nowa umowa przedstawicielska. \\tUwaga zasadna  Zasadnym jest doprecyzowanie, że zmiana adresata decyzji refundacyjnej jest możliwa także w przypadku zmiany przedstawiciela podmiotu odpowiedzialnego (a nie tylko zmiany samego podmiotu odpowiedzialnego), na dowód czego miałaby być przedkładana nowa umowa przedstawicielska. Zapis otrzymuje brzmienie: w art. 25e ust. 2 pkt 2: „lub umowę zawartą pomiędzy podmiotem odpowiedzialnym a przedstawicielem podmiotu odpowiedzialnego, w rozumieniu przepisów ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne”.\\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 25 projektu dotyczący art. 25e ustawy refundacyjnej\\tproponujemy dokonanie w projekcie nowelizacji odpowiedniej zmiany tak, aby zakres zastosowania art. 25e ustawy był szerszy.\\tArt. 25e – procedura przeniesienia decyzji o refundacji na nowy podmiot Rzeczywiście istnieje potrzeba wprowadzenia do przepisów ustawy o refundacji trybu przeniesienia decyzji o refundacji na nowy podmiot. Obecnie bowiem w sytuacji na przykład zmiany podmiotu odpowiedzialnego lub wyznaczenia nowego przedstawiciela podmiotu odpowiedzialnego zachodzi konieczność skrócenia okresu obowiązywania decyzji o refundacji i wystąpienia z nowym wnioskiem refundacyjnym. Zwracamy jednak uwagę na to, że zwłaszcza treść art. 25e ust. 2 pkt 2) ustawy zawęża zakres zastosowania tego przepisu wyłącznie do sytuacji zmiany podmiotu odpowiedzialnego dla leku; podczas, gdy potrzeba przeniesienia decyzji o refundacji na nowy podmiot może zaistnieć również w innych sytuacjach, na przykład w razie wyznaczenia nowego przedstawiciela podmiotu odpowiedzialnego lub rozwiązania umowy z przedstawicielem i konieczności przeniesienia decyzji na podmiot odpowiedzialny.\\tUwaga zasadna  Zasadnym jest doprecyzowanie, że zmiana adresata decyzji refundacyjnej jest możliwa także w przypadku zmiany przedstawiciela podmiotu odpowiedzialnego (a nie tylko zmiany samego podmiotu odpowiedzialnego), na dowód czego miałaby być przedkładana nowa umowa przedstawicielska. Zapis otrzymuje brzmienie: w art. 25e ust. 2 pkt 2 ustawy o refundacji: „lub umowę zawartą pomiędzy podmiotem odpowiedzialnym a przedstawicielem podmiotu odpowiedzialnego, w rozumieniu przepisów ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne”.\\n\\tOrganizacja Pracodawców Przemysłu Medycznego TECHNOMED\\tArt. 1 pkt 25 projektu odnoszący się do art. 25e ustawy refundacyjnej\\tWnioskujemy o usunięcie z przepisu wymogu potwierdzenia z URPL o zmianie podmiotu uprawnionego.\\tTryb informowania URPL o zmianie podmiotu uprawnionego w przypadku wyrobów medycznych nie funkcjonuje. Producenci muszą wprowadzać swoje wyroby do bazy europejskiej a dystrybutorzy sa zobowiązani do zgłaszania puli wyrobów jakie dystrybuują na terenie PR. Brakuje opcji zmiany podmiotu uprawnionego dlatego też wnioskujemy o pozostanie przy umowie w przypadku wyrobów medycznych aby nie tworzyć wymogu, który nie będzie możliwy do spełnienia i będzie niósł za sobą dodatkowe obciążenia urzędu i podmiotu w postaci wydawania zaświadczeń.\\tUwaga zasadna  W projekcie zmienia art. 25e ust. 2 pkt 3 dotyczący przeniesienia praw i obowiązków z decyzji na inny podmiot dla wyrobów medycznych na proponowane brzmienie: „3) jest podmiotem uprawnionym dla środka spożywczego specjalnego przeznaczenia żywieniowego lub podmiotem gospodarczym w rozumieniu art. art. 2 pkt 35 Rozporządzenia 2017/745 lub art. 2 pkt 28 rozporządzenia 2017/746 dla wyrobu medycznego, którego dotyczy decyzja o objęciu refundacją i przedłoży ministrowi właściwemu do spraw zdrowia umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków w zakresie tego środka spożywczego specjalnego przeznaczenia żywieniowego lub umowę z dotychczasowym wnioskodawcą o przejęciu praw i obowiązków wynikających z decyzji refundacyjnej w zakresie wyrobu medycznego, albo powiadomienie Głównego Inspektora Sanitarnego dla środka spożywczego specjalnego przeznaczenia żywieniowego o zmianie podmiotu uprawnionego.” \\n\\tPolska Izba Przemysłu Farmaceutycznego i Wyrobów Medycznych  POLFARMED\\t art. 1 pkt 26 projektu odnoszący się do art. 26 pkt 1 lit. n ustawy refundacyjnej\\tuzasadnienie wniosku i dowód wzrostu kosztów związanych z produkcją leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub analizę ekonomiczną kosztów wytwarzania i działalności wytwórcy uzasadniającą \\t\\fwnioskowane podwyższenie ceny zbytu netto.\\t\\t\\fProponujemy odejście od określenia „analizy ekonomicznej”, które jest zarezerwowane dla jednej z analiz HTA, pozostawiając dookreślenie, że chodzi o koszty wytwarzania i działalność wytwórcy uzasadniającą podwyżkę. Wprowadzenie możliwości wyboru uzasadnienia jest kluczowe, zwłaszcza w \\fsytuacji, kiedy cena progowa objęcia leku refundacją jest poniżej kosztów jego wytworzenia, co jest bardzo częste w przypadku występowania w wykazie jedynego odpowiednika w danym wskazaniu z niską ceną i koniecznością obniżenia ceny kolejnego odpowiednika o 25%.\\t\\fUwaga niezasadna  W projekcie przedstawiono już złagodzone wymogi formalne. Wprowadzona w treści art. 26 pkt 1 lit. n i pkt 2 lit. o ustawy o refundacyji (art. 1 pkt 26 lit. a i b projektu) zmiana, umożliwia Wnioskodawcy przekazanie ministrowi właściwemu do spraw zdrowia uzasadnienia wniosku o podwyższenie \\fceny zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego objętego refundacją oraz wybór formy przekazania dowodów na poparcie powyższego. Dotychczasowe rozwiązanie, obligowało Wnioskodawcę do złożenia dowodów uzasadniających wzrost kosztów związanych z produkcją oraz złożenie analizy ekonomicznej kosztów wytwarzania danego leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego. Wdrażane rozwiązanie, pozwala wnioskodawcy wybrać, czy poprze swój wniosek w formie pisemnego uzasadnienia, w załączeniu którego zostaną przekazane stosowne dowody, czy też przekaże z wnioskiem analizę ekonomiczną, uzasadniającą wnioskowany poziom podwyższenia ceny zbytu netto  Minister Zdrowia pozostaje przy określeniu „analizy ekonomicznej” jako dokumentu uzasadniającego wnioskowany poziom podwyższenia ceny zbytu netto.\\n\\t  Przedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tArt. 1 pkt 26 projektu odnoszący się do art. 25 lit. n i lit. o ustawy refundacyjnej\\tproponujemy dookreślenie:  uzasadnienie wniosku i dowód wzrostu kosztów związanych z produkcją leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego lub analizę ekonomiczną kosztów wytwarzania i działalności wytwórcy uzasadniającą wnioskowane podwyższenie ceny zbytu netto.\\tProponujemy odejście od określenia „analizy ekonomicznej”, które jest zarezerwowane dla jednej z analiz HTA, pozostawiając koszty wytwarzania i działalności wytwórcy uzasadniające podwyżkę. Wprowadzenie możliwości wyboru uzasadnienia jest kluczowe, zwłaszcza w sytuacji, kiedy cena progowa objęcia refundacją jest zbyt niska, często poniżej kosztów wytworzenia leku, co ma miejsce w przypadku konieczności jej obniżenia do poziomu 75% ceny \\fjedynego odpowiednika w danym wskazaniu z bardzo niską ceną zbytu netto. Dotyczy to w szczególności leków, które nie były przedmiotem oceny w AOTMiT, a okres wyłączności rynkowej upłynął wiele lat temu.\\t\\fUwaga niezasadna  W projekcie przedstawiono już złagodzone wymogi formalne. Wprowadzona w treści art. 26 pkt 1 lit. n i pkt 2 lit. o ustawy refundacyjnej (art. 1 pkt 26 lit. a i b projektu) zmiana, umożliwia Wnioskodawcy przekazanie ministrowi właściwemu do spraw zdrowia uzasadnienia wniosku o podwyższenie ceny zbytu netto leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego \\fobjętego refundacją oraz wybór formy przekazania dowodów na poparcie powyższego. Dotychczasowe rozwiązanie, obligowało Wnioskodawcę do złożenia dowodów uzasadniających wzrost kosztów związanych z produkcją oraz złożenie analizy ekonomicznej kosztów wytwarzania danego leku, środka spożywczego specjalnego przeznaczenia żywieniowego, wyrobu medycznego. Wdrażane rozwiązanie, pozwala wnioskodawcy wybrać, czy poprze swój wniosek w formie pisemnego uzasadnienia, w załączeniu którego zostaną przekazane stosowne dowody, czy też przekaże z wnioskiem analizę ekonomiczną, uzasadniającą wnioskowany poziom podwyższenia ceny zbytu netto.  Minister Zdrowia pozostaje przy określeniu „analizy ekonomicznej”, jako dokumentu uzasadniającego wnioskowany poziom podwyższenia ceny zbytu netto.\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 28 lit. b projektu dotyczący art. 30 ust. 1a ustawy refundacyjnej\\t1a. Wniosek składany przez wnioskodawcę będącego importerem równoległym, o którym mowa w art. 24 ust. 1 pkt 1 i 5, dotyczący leku, który ma co najmniej jeden odpowiednik refundowany w danym wskazaniu, jest zwolniony z negocjacji cenowych z Komisją Ekonomiczną, o której mowa w art. 17.\\tNieuzasadnione wydaje się zwolnienie z negocjacji z KE wnioskodawcy będącego importerem równoległym w sytuacji, gdy zmiana przepisów wprowadza do zakresu obowiązków KE negocjacje dotyczące deklaracji dostaw.  \\tObecność leku na liście refundacyjnej wskazuje, że powinien on zapewnić dostępność terapii dla pacjentów. Dotychczas częstą sytuacją było pojawienie się w refundacji leków z \\fimportu równoległego i pozostawanie na liście mimo zerowej sprzedaży leku.\\t\\fUwaga niezasadna Zwolnienie wniosków składanych przez importerów równoległych z obowiązku przeprowadzania negocjacji cenowych z Komisją Ekonomiczną, w sytuacji, gdy dany produkt leczniczy posiada już co najmniej jeden odpowiednik refundowany w danym wskazaniu, stanowi techniczne uproszczenie procesu refundacyjnego i pozostaje spójne z celem importu równoległego.  \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 ust. 28 lit a dotyczący art. 30 ust. 1\\t1. Wymagania, o których mowa w art. 24 ust. 2 pkt 1 i 1a, art. 25 pkt 12 i 13 oraz 14 lit. d, art. 26 pkt 1 lit. g oraz pkt 2 lit. g, art. 28 pkt 7 lit. c, nie dotyczą wniosku, o którym mowa w art. 24 ust. 1, składanego przez wnioskodawcę będącego importerem równoległym.  1a. Wniosek składany przez wnioskodawcę będącego importerem równoległym, o którym mowa w art. 24 ust. 1 pkt 1 i 5, dotyczący leku, który ma co najmniej jeden odpowiednik refundowany w danym wskazaniu, jest zwolniony z negocjacji cenowych z Komisją Ekonomiczną, o której mowa w art. 17. \\tZwiązek zgłasza wyraźny sprzeciw wobec eliminowania kolejnych obowiązków ustawowych w zakresie regulacji dotyczących importu równoległego. Kierunek proponowanych zmian rodzi poważne ryzyko pogarszania warunków ekonomicznych dla podmiotów wytwarzających leki w Polsce lub prowadzących tu działalność badawczo-rozwojową. Dotyczy to w szczególności produktów leczniczych objętych importem równoległym, których rentowność – już obecnie istotnie obniżona – może ulec dalszemu pogorszeniu, prowadząc w skrajnym przypadku do ograniczenia ich dostępności dla pacjentów.  Projektowane regulacje wprowadzają znacząco uprzywilejowaną pozycję importerów równoległych (IR), którzy nie ponoszą żadnych nakładów ani na produkcję, ani na badania naukowe w Polsce. Co więcej, projekt przewiduje całkowite zwolnienie tych podmiotów z obowiązku przedstawiania podstawowych informacji wymaganych od innych wnioskodawców, m.in. opisu działalności naukowo-badawczej lub inwestycyjnej prowadzonej przez wnioskodawcę w Polsce lub na terytorium innych państw UE lub EFTA. W efekcie importerzy równolegli otrzymują automatyczny dostęp do preferencji refundacyjnych, które dla krajowych producentów stanowią premię za ich długoletnie zaangażowanie \\fw produkcje leków na terytorium RP oraz działalność badawczo-rozwojową. Taki model tworzy nierówne warunki konkurowania, ze szkodą dla bezpieczeństwa lekowego kraju i stabilności dostaw. \\t\\fUwaga niezasadna Projektowana zmiana art. 30 ustawy o refundacji nie przewiduje automatycznego objęcia refundacją produktów leczniczych importowanych równolegle, lecz upraszcza katalog dokumentów wymaganych na etapie składania wniosku, przy zachowaniu wszystkich zasadniczych instrumentów wskazanych w art. 13 ustawy o refundacji.  Zaproponowane zmiany nie mają charakteru dyskryminującego, gdyż co należy podkreślić te same przesłanki i zasady obejmowania refundacją oraz ustalania urzędowej ceny zbytu stosowane są jednakowo wobec wszystkich produktów leczniczych, niezależnie od tego, czy są one wytwarzane w kraju, importowane, czy wprowadzane w trybie importu równoległego. \\n\\tStowarzyszenie Importerów Równoległych Produktów Leczniczych\\tArt. 1 ust. 28 lit a dotyczący art. 30 ust. 1 zmiana brzmienia\\t1. Wymagania, o których mowa w art. 24 ust. 2 pkt 1 i 1a, art. 25 pkt 3, 7, 12 i 13 oraz 14 lit. c i lit. d, art. 26 pkt 1 lit. g oraz pkt 2 lit. g, art. 28 pkt 7 lit. c, nie dotyczą wniosku, o którym mowa w art. 24 ust. 1, składanego przez wnioskodawcę będącego importerem równoległym.  \\tProponowane wyłączenia mają na celu ułatwienie procedury administracyjnej dla importerów równoległych oraz zdjęcie z nich obowiązków, których adresatami nie powinni być z uwagi na specyfikę możliwości pozyskiwania produktów leczniczych poprzez import równoległy. \\t\\tUwaga niezasadna W odpowiedzi na zgłoszoną uwagę postulującą zmianę brzmienia art. 30 ust. 1 projektu ustawy, informujemy, że zgłoszona uwaga została oceniona jako niezasadna. Wprowadzone w projekcie ustawy wyłączenia wymagań dotyczących wniosków składanych przez importerów równoległych zostały starannie przemyślane i dobrane z uwzględnieniem specyfiki oraz funkcji importu równoległego w systemie zaopatrzenia w produkty lecznicze. Projektowany katalog wyłączeń jest adekwatny do realiów rynkowych i uwzględnia jednocześnie konieczność zachowania właściwego poziomu kontroli oraz bezpieczeństwa obrotu produktami. Rozszerzenie katalogu wyłączeń, jak proponuje zgłaszający uwagę, na dodatkowe pozycje wymagań zawarte w art. 25 pkt 3 i 7 oraz 14 lit. c, mogłoby prowadzić do obniżenia standardów kontroli jakości oraz bezpieczeństwa produktów leczniczych wprowadzanych na rynek poprzez import równoległy. W szczególności wyłączenie wymagań \\fodnoszących się do określonych aspektów dokumentacji oraz badań mogłoby skutkować utrudnieniami w zapewnieniu równej pozycji wszystkich podmiotów uczestniczących w systemie refundacji oraz ograniczyć możliwość monitorowania spełniania norm jakościowych. Ponadto, proponowana zmiana mogłaby prowadzić do rozmycia odpowiedzialności oraz utrudnić skuteczne wykonywanie obowiązków kontrolnych. W konsekwencji zwiększyłoby to ryzyko wystąpienia nieprawidłowości i zagrożeń dla zdrowia publicznego, co stoi w sprzeczności z nadrzędnym celem ustawy o refundacji, jakim jest zapewnienie pacjentom dostępu do bezpiecznych i skutecznych produktów leczniczych. W świetle powyższego, postulowane rozszerzenie zakresu wyłączeń w art. 30 ust. 1 jest nieuzasadnione, gdyż może negatywnie wpłynąć na bezpieczeństwo i jakość produktów refundowanych oraz na efektywność działania systemu refundacji. Aktualne brzmienie przepisu stanowi wyważone i odpowiednie rozwiązanie, uwzględniające specyfikę importu równoległego, a jednocześnie zachowujące należytą ochronę interesów pacjentów oraz prawidłowe funkcjonowanie systemu\\n\\tStowarzyszenie Importerów Równoległych Produktów \\fLeczniczych/ Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman\\t\\fArt. 1 ust. 28 lit b dotyczący art. 30 ust. 1a \\fzmiana brzmienia\\t\\f1a. Wniosek składany przez wnioskodawcę będącego importerem równoległym, o którym mowa w art. 24 ust. 1 pkt 1  i 5 , dotyczący leku, który ma co najmniej jeden \\fodpowiednik refundowany w danym wskazaniu, jest zwolniony z negocjacji cenowych z Komisją Ekonomiczną, o której mowa w art. 17. \\t\\t\\fZmiana ma na celu wyłączenie z negocjacji z Komisją Ekonomiczną wszystkich leków z importu równoległego, ponieważ są to te same \\fleki, które już uzyskały decyzję refundacyjną. W takim wypadku wystarczy tylko, że importer równoległy zaoferuje cenę niższą od ceny zbytu netto tego samego leku dopuszczonego do obrotu w procedurze innej niż import równoległy. \\t Od Lobbysta Kancelaria Radcy Prawnego Tomasz Dauerman:  Zmiana ma na celu wyłączenie z negocjacji z Komisją Ekonomiczną wszystkich leków z importu równoległego, ponieważ są to te same leki, które już uzyskały decyzję refundacyjną. W takim wypadku wystarczy, że importer równoległy zaoferuje cenę niższą od ceny zbytu netto tego samego leku dopuszczonego do obrotu w procedurze innej niż import równoległy.\\t\\fUwaga niezasadna   Usunięcie z przepisu warunku odnoszącego się do obecności co najmniej jednego refundowanego \\fodpowiednika danego leku oznaczałoby de facto zwolnienie z negocjacji cenowych wszystkich leków wprowadzanych na rynek w ramach importu równoległego, niezależnie od ich charakterystyki i pozycji na rynku. Taka zmiana byłaby nieuzasadniona i mogłaby prowadzić do sytuacji, w której na rynek trafiałyby produkty o cenach nieodpowiednio zweryfikowanych pod kątem ekonomicznym, co mogłoby negatywnie wpłynąć na stabilność i racjonalność wydatkowania środków publicznych. Ponadto, obecny model przewiduje, że importer równoległy, w przypadku leków będących odpowiednikami refundowanych produktów, zobowiązany jest jedynie do zaoferowania ceny niższej od ceny zbytu netto leku dopuszczonego do obrotu w procedurze innej niż import równoległy. W ten sposób zapewnione jest zachowanie konkurencyjności cenowej i ochrona interesu publicznego bez konieczności przeprowadzania odrębnych negocjacji cenowych, które w przypadku tożsamości leków mogłyby być zbędne i nadmiernie wydłużać postępowanie. W świetle powyższego, wyłączenie z negocjacji cenowych leków importowanych równolegle, które mają co najmniej jeden odpowiednik refundowany w danym wskazaniu, \\fstanowi racjonalne i uzasadnione rozwiązanie prawne, dostosowane do specyfiki rynku farmaceutycznego oraz wymogów efektywnego zarządzania środkami publicznymi. \\n\\tAfordable Medicines Europe\\tart. 1 pkt 28 lit. a i b projektu odnoszący się do art. 30 ust. 1 i ust. 1a\\tproponujemy rozszerzenie art. 30 o zaktualizowaną listę wyłączeń dla podmiotów prowadzących handel równoległy, aby w pełni zrealizować zapowiedzi rządu, by wymagać mniej rygorystycznych i bardziej realistycznych warunków formalnych dla wniosków o refundację leków z importu równoległego\\t\\tProponujemy, aby art. 30 zawierał wyłączenia dla podmiotów prowadzących handel równoległy w celu wypełnienia obowiązków wynikających z art. 25 pkt 3, art. 25 pkt 4 i art. 25 pkt 8 oraz art. 25 pkt 14.\\tUwaga niezasadna Obecny katalog wyłączeń zawarty w art. 30 został opracowany z uwzględnieniem specyfiki importu równoległego oraz konieczności zachowania odpowiedniego poziomu kontroli jakości i bezpieczeństwa produktów leczniczych. Propozycja rozszerzenia listy wyłączeń w sposób znaczący obniżyłaby rygory formalne dotyczące wniosków składanych przez importerów równoległych, co mogłoby prowadzić do istotnego obniżenia standardów weryfikacji tych produktów. Należy podkreślić, że system refundacji ma na celu nie tylko usprawnienie dostępu pacjentów do leków, lecz również zapewnienie, aby wszystkie produkty refundowane spełniały wymogi jakościowe i bezpieczeństwa, co jest szczególnie istotne w kontekście leków importowanych równolegle, gdzie istnieje ryzyko większej rozbieżności w zakresie kontroli jakości w porównaniu z lekami wprowadzanymi do obrotu bezpośrednio przez producentów. Zbyt daleko idące uproszczenia formalne mogłyby ograniczyć możliwość skutecznego monitorowania i oceny \\fproduktów wnoszonych na rynek poprzez import równoległy, co mogłoby w konsekwencji negatywnie wpłynąć na ochronę zdrowia publicznego oraz na stabilność finansową systemu refundacji. Ponadto, utrzymanie odpowiedniego poziomu wymagań formalnych wobec wszystkich wniosków, w tym tych składanych przez importerów równoległych, jest konieczne, aby zapewnić równe warunki konkurencji na rynku farmaceutycznym oraz zapobiegać nadużyciom proceduralnym. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 28 lit. c projektu odnoszący się do art. 30 ust. 4-6 ustawy refundacyjnej\\t5.Wniosek, o którym mowa w ust. 4, jest zwolniony z negocjacji cenowych z Komisją.  \\t\\tUstawa nie rozróżnia negocjacji na cenowe i inne.\\tUwaga zasadna W projekcie wyraz „cenowe” został wykreślony z art. 30 ust. 1a i 5, art. 30aa ust. 1 ustawy o refundacji.\\n\\tOgólnopolska Izba Gospodarcza Wyrobów Medycznych POLMED\\tArt. 1 pkt 28 lit. c projektu odnoszący się do art. 30 ust. 4-6 ustawy refundacyjnej\\tdodaje się ust. 4–6 w brzmieniu: „4. Nie podlega opłacie, o której mowa w art. 32, wniosek, o którym w art. 24 ust. 1 pkt 5, dla leku lub wyrobu medycznego zawartego w wykazie, o którym mowa w art. 37 ust. 1, w danym wskazaniu, złożony w celu wydania decyzji o objęciu refundacją i ustaleniu ceny zbytu netto dla tego samego leku lub wyrobu medycznego w tym samym albo szerszym wskazaniu.  5.Wniosek, o którym mowa w ust. 4, jest zwolniony z negocjacji cenowych z Komisją. \\f6.Wymagania, o których mowa w art. 25 pkt 14 lit. a, c tiret pierwsze, drugie oraz lit. d, nie dotyczą wniosku, o którym mowa w art. 24 ust. 1 pkt 1, w odniesieniu do leku dostępnego w aptece na receptę zawierającego więcej niż jedną substancję czynną, jeżeli w dniu złożenia tego wniosku w wykazie, o którym mowa w art. 37 ust. 1, były zawarte leki w kategorii dostępności refundacyjnej, o której mowa art. 6 ust. 1 pkt 1 z tymi substancjami czynnymi i tą samą drogą podania przy braku różnic postaci farmaceutycznej, w danym wskazaniu. Do tego wniosku nie stosuje się przepisów art. 12 pkt 2, art. 13 ust. 1 pkt 2 i ust. 3, art. 16aa oraz art. 35.”; \\t\\t\\fZasadne jest dokonanie w projekcie zmian redakcyjnych pozwalających na zastosowanie mechanizmu skrócenia technicznego nie tylko do leków, ale także do wyrobów medycznych objętych decyzją refundacyjną. Zmiana ma charakter techniczny.\\tUwaga zasadna W nowo zaprojektowanym zapisie art. 30 ustawy o refundacji uwzględniono środki spożywcze specjalnego przeznaczenia żywieniowego oraz wyroby medyczne.\\n\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 30 ust. 3 ust. ref.\\t3. Wymagania, o których mowa w art. 25 pkt 14, nie dotyczą wniosków, o których mowa w art. 24 ust. 1 pkt 1, dla leku zawierającego substancję czynną, który nie ma odpowiednika refundowanego w danym wskazaniu, a który to lek albo jego odpowiednik był zawarty w wykazie, o którym mowa w art. 37 ust. 1, w danym wskazaniu, i w przypadku gdy był oceniany przez Prezesa Agencji otrzymał pozytywną rekomendację Prezesa Agencji. Jeśli lek nie był oceniany przez Prezesa Agencji, minister właściwy do spraw zdrowia może wystąpić do Rady Przejrzystości o opinię dotyczącą tego leku. Przepis ust. 2 zdanie drugie stosuje się.\\tW obecnym kształcie ust. 3 zwalnia z wymogu przedłożenia analiz HTA jedynie te leki, wracające na wykaz, które historycznie otrzymały pozytywną rekomendację Prezesa Agencji. \\tPZPPF proponuje uzupełnić przepis o przypadek, gdy dany lek nie podlegał obowiązkowi oceny ze strony Prezesa Agencji. W takim przypadku Minister Zdrowia mógłby w razie potrzeby zwrócić się o opinię do Rady Przejrzystości.\\tUwaga niezasadna Projektowane brzmienie art. 30a wychodzi naprzeciw proponowanym zmianom. Podmiot odpowiedzialny przedkładając wniosek zgodny z wezwaniem ministra właściwego do spraw zdrowia upoważniony będzie do skorzystania z preferencyjnych warunków procedowania takiego wniosku w tym szybszej ścieżki dla leków w terapii skojarzonej. Preferencje uzależnione zostały od obowiązujących okresów ochronnych danego produktu leczniczego. Opłata za analizę weryfikacyjną dla leków objętych okresem ochronnym, które dotychczas nie były refundowane, będzie zredukowana o połowę, jednocześnie dla leków nie objętych okresami ochronnymi, w stosunku co do których nie istnieją formalne przeciwwskazania do wejścia na rynek ich odpowiedników, nie będzie \\fkonieczności przedkładania kompletu analiz HTA jak ma to miejsce w przypadku standardowej procedury refundacyjnej dla nowych terapii. Proponowana zmiana stanowi de facto rozszerzenie obecnej regulacji określonej w art. 30a o leki chronione patentem lub okresem wyłączności rynkowej, jednocześnie upraszczając istotnie cały proces.\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 30 ust. 5a (nowy)\\t5a. Wymagania, o których mowa w art. 24 ust. 2 pkt 1-2, 5-6 oraz w art. 29 pkt 5 i 6 nie dotyczą wniosku, o którym mowa w ust. 4.\\tProjektowane przepisy ust. 4 i 5 słusznie przewidują zwolnienie z opłaty i negocjacji dla wniosków o „skrócenie techniczne”. Konieczne jest jednak wprowadzenie dodatkowego „ruchu deregulacyjnego”, polegającego na maksymalnym ograniczeniu zakresu takiego wniosku – powinien on ograniczać się wyłącznie do jednoznacznego wskazania leku, identyfikacji decyzji, której czas obowiązywania podlega skróceniu, a także do wykazania umocowania do reprezentacji. Wnioskodawcę ubiegającego się o „skrócenie techniczne” należy natomiast zwolnić z obowiązku dostarczenia dokumentów i informacji, które są zbędne dla dokonania „skrócenia technicznego”, a są dostępne Ministrowi Zdrowia w aktach postępowania o objęcie refundacją, tj. Charakterystyki Produktu Leczniczego, kopii decyzji o dopuszczeniu do obrotu, informacji o wskazaniach refundowanych w innych państwach UE/EFTA, dokumentów przetłumaczonych przysięgle na język polski, potwierdzających aktualną na dzień złożenia wniosku informację dotyczącą produktu leczniczego we wszystkich państwach członkowskich \\fUnii Europejskiej lub państwach członkowskich Europejskiego Porozumienia o Wolnym Handlu (EFTA), umowy z podmiotem odpowiedzialnym oraz dokumentów patentowych (jeżeli dotyczy). \\t\\t\\fUwaga częściowo uwzględniona Minister Zdrowia uznaje za niezasadne zwolnienia z obowiązku przedstawiania umowy, o której mowa w art. 24 ust. 2 pkt 5. Umowa zawartą pomiędzy podmiotem odpowiedzialnym a przedstawicielem podmiotu odpowiedzialnego, w rozumieniu przepisów ustawy z dnia 6 września 2001 r. - Prawo farmaceutyczne jednoznacznie wskazuje na umocowanie przedstawiciela podmiotu odpowiedzialnego do występowania w danym postępowaniu administracyjnym. \\n\\tAlivia - Fundacja Onkologiczna\\tart. 1 pkt 29 projektu odnoszący się do art. 30a ustawy refundacyjnej\\tZ uznaniem przyjmujemy propozycję art. 30a ust. 1, zgodnie z którą Minister Zdrowia będzie mógł wezwać podmiot odpowiedzialny do złożenia wniosku refundacyjnego dla danego wskazania i kategorii dostępności. To rozwiązanie pozwala skutecznie odpowiadać na niezaspokojone potrzeby pacjentów zapewniając dostępność skutecznych terapii również w sytuacjach, gdy wnioskodawcy nie inicjują procedur refundacyjnych.\\t\\t\\tUwaga zasadna \\n\\tPracodawcy RP\\tart. 1 pkt 29 projektu odnoszący się do art. 30a ustawy refundacyjnej\\tW odniesieniu do art. 30a proponujemy, aby w przypadku innowacyjnej terapii skojarzonej z nierefundowanym lekiem generycznym, objęcie refundacją tego ostatniego odbywało się na podstawie przepisów art. 40, a nie w ramach wezwania podmiotu odpowiedzialnego. Ponadto postulujemy o usunięcie obowiązkowego umorzenia postępowania w przypadku, gdy dla leku do skojarzenia z lekiem będącym przedmiotem pierwotnego postępowania nie zostanie złożony w terminie wniosek o objęcie refundacją.\\t\\tStosownie do informacji przekazanych podczas spotkania w dniu 2 czerwca w sytuacji, gdy lek generyczny ma być skojarzony z lekiem będącym przedmiotem postępowania o objęcie refundacją, MZ będzie wzywał podmiot odpowiedzialny do złożenia wniosku zgodnie z przepisem art. 30aa. W ocenie Pracodawców RP takie rozwiązanie nie sprawdzi się w praktyce, ponieważ podmioty odpowiedzialne dla takich leków mogą w ogóle nie być zainteresowane składaniem wniosków. Z tego względu bardziej funkcjonalnym rozwiązaniem byłoby skorzystanie po \\fodpowiednim dostosowaniu z mechanizmu dla leków off-label.\\t\\fUwaga niezasadna Nie można obejmować refundacją z art. 40a ustawy o refundacji leków, które mają w CHPL zarejestrowane wskazanie potrzebne do stworzenia terapii skojarzonej. Tym bardziej niewłaściwej jest uproszczenie procedury m.in. pomijając negocjacje cenowe w sytuacji, w której lek będzie stosowany w szerszej populacji i wnioskodawca musi zagwarantować większą dostępność produktu leczniczego.  Minister Zdrowia uważa za stosowne wprowadzenie umorzenia, o którym mowa w art. 30a ust. 10, gdyż w związku z niezłożeniem wniosku w odpowiednim terminie dla leku do skojarzenia z lekiem \\fbędącym przedmiotem pierwotnego postępowania, dalsze procedowanie niniejszego postępowania jest niezasadne.\\n\\tPrzedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tart. 1 pkt 29 projektu odnoszący się do art. 30a ust. 2 ustawy refundacyjnej\\tW art. Art. 30a ust. 2 (art. 1 pkt 29) proponujemy następujące uzupełninie:  Minister właściwy do spraw zdrowia może wezwać podmiot odpowiedzialny do złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dla leku w danym wskazaniu i danej kategorii dostępności, kierując się w szczególności niezaspokojoną potrzebą zdrowotną oraz racjonalizacją wydatków płatnika.  2. Wezwanie, o którym mowa w ust. 1, publikuje się w Biuletynie Informacji Publicznej urzędu obsługującego ministra właściwego do spraw zdrowia. 2a. Jeśli wezwanie, o którym mowa w ust. 1 dotyczy leku umieszczonego w wykazie, o którym mowa w art. 37 ust.1, Minister Zdrowia przesyła je wnioskodawcy również za pośrednictwem SOLR.\\t\\tPowyższe rozwiązanie umożliwi rozpoczęcie postępowania w tym samym interwale obwieszczeniowym i zapewni równe traktowanie wnioskodawców.\\tUwag niezasadna Zaproponowane przez projektodawcę rozwiązanie zostało utworzone na wzór obecnego art. 30a ustawy o refundacji, gdzie Minister Zdrowia publikuje na swojej stronie internetowej oraz w Biuletynie Informacji Publicznej listę leków o ugruntowanej skuteczności oraz art. 40a ust. 5 dot. publikacji przez Ministra Zdrowia listy technologii o wysokim poziomie innowacyjności. Praktyka pokazała, iż jest to właściwe postępowanie i w całości rozwiązuje problem wskazany w uwadze. Minister Zdrowia nie przewiduje wysyłania wezwań do wnioskodawcy za pośrednictwem SOLR, z uwagi na zbyt dużą czasochłonność.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 29 projektu odnoszący się do art. 30a ust. 9 i10 ustawy refundacyjnej\\tWnioskujemy o zmianę art. 30a ust. 9 w związku z formalnym błędem legislacyjnym – błędnym odesłaniem do ust. 2.   Proponujemy następujące brzmienie art. 30a ust. 9 ustawy:  „9.  Wnioskodawca dla wniosku złożonego na wezwanie, o którym mowa w ust. 4, nie może wybrać preferencji administracyjnej, o której mowa w art. 13a ust. 2 pkt 1 lit. c.”  Proponujemy następujące brzmienie art. 30a ust. 10 ustawy:  \\f„10) Minister właściwy do spraw zdrowia umarza postępowanie wszczęte na podstawie wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dla leku w terapii skojarzonej, jeżeli inny wnioskodawca nie złożył we właściwych terminach, o których mowa w ust. 7 i 8, po wezwaniu, o którym mowa w ust. 1, wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dla leku będącego uzupełnieniem terapii skojarzonej, pod warunkiem, że terapia skojarzona zawiera się w zakresie wskazań do stosowania, określonych w Charakterystyce Produktu Leczniczego, o której mowa w art. 10 ust. 2 pkt 11 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, dla tego leku ”  Ponadto, wnioskujemy o dodanie w art. 30a ust. 11 ustawy w następującym brzmieniu:  „11. Do wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dotyczącego leku będącego uzupełnieniem terapii skojarzonej, dla którego skojarzenie to dotyczy wskazań do stosowania odmiennych niż określone w Charakterystyce Produktu Leczniczego, o której mowa w art. 10 ust. 2 pkt 11 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, zastosowanie mają przepisy art. 40 ustawy.” \\t\\fWnioskowaną zmianę w art. 30a ust.9 argumentujemy błędnym odesłaniem do ust. 2 ustawy.   \\tPonadto, wnosimy o zmianę w art. 30a ust.10 ustawy w związku z brakiem dookreślenia wskazań dla leku będącego uzupełnieniem terapii skojarzonej oraz możliwość zastosowania art. 40 do leków będących uzupełnieniem terapii skojarzonej, dla których skojarzenie to nie zostało określone w ChPL (off label) (dodanie w art. 30a ust. 11 ustawy). \\tUwaga niezasadna  Zmienione brzmienie art. 30a reguluje dodatkowo sposób postępowania z terapiami skojarzonymi, dla których zastosowanie w takim połączeniu zostało ujęte we wszystkich dokumentach Charakterystyki Produktu Leczniczego składników tego skojarzenia. W przypadku obu składowych terapii konieczne będzie złożenie wniosków, o których mowa w art. 24 ust. 1 pkt 1 jednak zakres wymagań w odniesieniu do tych wniosków będzie odmienny dla poszczególnych składowych. Wniosek dla jednego z leków, które zostaną wskazane przez Ministra Zdrowia, \\fbędzie musiał zawierać uzasadnienie kliniczne oraz ekonomiczne dotyczące terapii skojarzonej oraz analizę wpływu na budżet w odniesieniu do tego składnika, zaś wniosek dotyczący drugiej składowej będzie mógł zostać ograniczony jedynie do analizy wpływu na budżet drugiej składowej,  przy czym nie będzie wymagane spełnienie w tym przypadku (drugi składnik, uproszczona dokumentacja) wymagań minimalnych. Na podstawie ww. dokumentacji Agencja przygotowywać będzie wspólną analizę weryfikacyjną dotyczącą terapii skojarzonej. Całość dokumentacji będzie przekazywana przez Ministra Zdrowia Agencji dopiero w przypadku kompletności wniosków dla obu składowych terapii skojarzonej, a postępowania będą zawieszane do momentu uzupełnienia dokumentacji.  W opinii Ministra Zdrowia nie istnieje potrzeba doprecyzowania kwestii sposobu postępowania w odniesieniu do terapii skojarzonych w sytuacji, kiedy terapia taka stanowi wskazanie rejestracyjne tylko dla jednej składowej – została opisana w sekcji 4.1. dokumentu ChPL (proponowane dodanie ust. 11). W takim przypadku, analogicznie jak ma to miejsce aktualnie, Minister Zdrowia może wykorzystać bowiem art. 40 ustawy o refundacji lub art. 155 Kpa. \\n\\tPrzedsiębiorstwo Produkcji Farmaceutycznej HASCO-LEK S.A.\\tart. 1 pkt 29 projektu odnoszący się do art. 30a – \\fdodanie ust. 11\\t\\fPostulujemy również o dodanie do art. 30a ust. 11 w brzmieniu:  11. Leki we wskazaniach objętych refundacją na podstawie ust. 1, jeśli nie posiadają przeciwskazań do stosowania w \\fdanej populacji, umieszcza się w wykazach, o których mowa w art. 37 ust. 2a i 2aa.\\t\\t\\fDodanie tego przepisu zapewni należny dostęp pacjentom uprawnionym tj. powyżej 65. i poniżej 18. roku życia do otrzymywania leków objętych refundacją \\fna podstawie art. 30a bezpłatnie. W naszej ocenie nie ma żadnych podstaw do jakiegokolwiek ograniczania ich dostępności finansowej i tym samym dyskryminowania określonych populacji chorych, zwłaszcza, że ww. leki odpowiadają na niezaspokojone potrzeby zdrowotne.\\t\\fUwaga niezasadna Wykazy bezpłatnych leków 65+, ciąża+ oraz 18-, są tworzone z uwzględnieniem leków, w stosunku do których wydano decyzje administracyjne o objęciu \\frefundacją i ustaleniu ceny zbytu netto. Oznacza to, że nie jest możliwe umieszczenie leku na liście S/DZ/C w przypadku kiedy nie jest on zawarty w wykazie leków refundowanych. Dopiero kiedy lek znajduje się w systemie refundacji możliwa jest ocena skutków finansowych objęcia go refundacją oraz przeprowadzenie racjonalnej i wiarygodnej oceny wpływu na budżet płatnika, w tym również w wyniku wprowadzenia go na ww. bezpłatne wykazy.  Proponowany mechanizm oznaczałby wprowadzenie automatyzacji, która w konsekwencji zwiększałaby wydatki płatnika nie pozostawiając możliwości kontroli wydatków.  Zgodnie z analizą wielkości obrotu w 2024 roku prawie 52% wszystkich refundowanych opakowań w aptece zostało wydanych z uprawnieniem 65+ (lista S), a 3,3% wszystkich refundowanych opakowań w aptece w ramach uprawnienia 18- (Lista DZ).\\n\\tPolska Izba Przemysłu Farmaceutycznego i Wyrobów Medycznych  POLFARMED\\t art. 1 pkt 29 projektu odnoszący się do art. 30a ust. 2 ustawy refundacyjnej\\tMinister właściwy do spraw zdrowia może wezwać podmiot odpowiedzialny do złożenia wniosku, o którym mowa w art. 24 ust. 1 pkt 1, dla leku w danym wskazaniu i danej kategorii dostępności, kierując się w szczególności niezaspokojoną potrzebą zdrowotną oraz racjonalizacją wydatków płatnika. 2. Wezwanie, o którym mowa w ust. 1, publikuje się w Biuletynie Informacji Publicznej urzędu obsługującego ministra właściwego do spraw zdrowia. \\t2a. Jeśli wezwanie dotyczy leku umieszczonego w wykazie, o którym mowa w art. 37 ust.1, Minister Zdrowia przesyła \\fje wnioskodawcy również za pośrednictwem SOLR.\\t\\t\\fProponujemy, aby wezwania podmiotu odpowiedzialnego do złożenia wniosku, w przypadku rozszerzenia zakresu wskazań refundowanego leku były przesyłane wnioskodawcy za pośrednictwem SOLR. Pozwoli to uniknąć sytuacji, w których z powodu przeczenia, wnioskodawca spóźni się ze złożeniem wniosku w terminie lub w określonym interwale obwieszczeniowym i wynikną z tego konsekwencje natury administracyjnej.\\tUwag niezasadna Zaproponowane przez projektodawcę rozwiązanie zostało utworzone na wzór obecnego art. 30a ustawy o refundacji, gdzie Minister Zdrowia publikuje na swojej stronie internetowej oraz w Biuletynie Informacji Publicznej listę leków o ugruntowanej skuteczności oraz art. 40a ust. 5 dot. publikacji przez Ministra Zdrowia listy technologii o wysokim poziomie innowacyjności. Praktyka pokazała, iż jest to właściwe postępowanie i w całości rozwiązuje problem wskazany w uwadze. \\fMinister Zdrowia nie przewiduje wysyłania wezwań do wnioskodawcy za pośrednictwem SOLR, z uwagi na zbyt dużą czasochłonność. \\n\\tPolska Izba Przemysłu Farmaceutycznego i Wyrobów Medycznych  POLFARMED\\t art. 1 pkt 29 projektu odnoszący się do art. 30a ust. 11 ustawy refundacyjnej\\tLeki we wskazaniach objętych refundacją na podstawie ust. 1, jeśli nie posiadają przeciwskazań do stosowania w danej grupie pacjentów, umieszcza się w wykazach, o których mowa w art. 37 ust. 2a, 2aa i 2b \\t\\tPostulujemy dodanie przepisu zapewniającego dostęp pacjentom uprawnionym 65+, 18- i C+ do otrzymywania leków objętych refundacją na podstawie art. 30a bezpłatnie, zwłaszcza, że dotyczą niezaspokojonej potrzeby zdrowotnej i nie ma podstaw do jakiegokolwiek ograniczania ich dostępności i tym samym dyskryminowania określonych populacji chorych.\\tUwaga niezasadna Wykazy bezpłatnych leków 65+, ciąża+ oraz 18-, są tworzone z uwzględnieniem leków, w stosunku do których wydano decyzje administracyjne o objęciu refundacją i ustaleniu ceny zbytu netto. Oznacza to, że nie jest możliwe umieszczenie leku na liście S/DZ/C w przypadku, kiedy nie jest on zawarty w wykazie leków refundowanych. Dopiero kiedy lek znajduje się w systemie refundacji możliwa jest ocena skutków finansowych objęcia go refundacją oraz przeprowadzenie racjonalnej i wiarygodnej oceny wpływu na budżet płatnika, w tym również w wyniku wprowadzenia go na ww. bezpłatne wykazy.  Proponowany mechanizm oznaczałby wprowadzenie automatyzacji, która w konsekwencji zwiększałaby wydatki płatnika nie pozostawiając możliwości kontroli wydatków.  Zgodnie z analizą wielkości obrotu w 2024 roku prawie 52% wszystkich refundowanych opakowań w aptece zostało wydanych z uprawnieniem 65+ (lista S), a 3,3% wszystkich refundowanych opakowań w aptece w ramach uprawnienia 18- (Lista DZ).\\n\\tAmerykańska Izba Handlowa w Polsce\\tArt. 1 pkt 30 projektu dotyczący art. 30aa ust. 1 i2 ustawy \\frefundacyjnej\\t\\fW art. 30aa ust. 1 i 2 proponujemy nadanie następującego brzmienia: 1. Dla leku ujętego w wykazie, o którym mowa w art. 37 ust. 1, i w wykazie, o którym \\fmowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne albo w przypadku uzasadnionego zagrożenia brakiem dostępności leku ujętego w wykazie, o którym mowa w art. 37 ust. 1, wnioskodawca może złożyć wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla tego samego leku w obcojęzycznym opakowaniu w przypadku uzyskania zgody, o której mowa w art. 4b lub 4c ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. Do takiego wniosku  nie stosuje się przepisów art. 24 ust. 2 pkt 1–2 i 6, art. 25 pkt 4, 7, 8, 1214 oraz są zwolnione z negocjacji cenowych z Komisją.  2. Cena zbytu netto oraz cena efektywna leku, o którym mowa w ust. 1, nie mogą być wyższe niż w obowiązującej ostatniej decyzji administracyjnej o objęciu refundacją dla leku ujętego w wykazie, o którym mowa w art. 37, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne.\\t\\fProponujemy, aby możliwe było złożenie wniosku także w sytuacji uzasadnionego zagrożenia brakiem dostępności, które nie zostało jeszcze odzwierciedlone w \\fwykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, ale już na danym etapie można przypuszczać, że zaistnieje problem z dostępnością leku w refundowanych opakowaniach, pozwoli to odpowiednio szybko przeprowadzić procedurę dorefundowania zagranicznego opakowania, docelowo jeszcze zanim nastąpi problem z dostępnością polskiego opakowania. Ponadto, zwracamy uwagę, że w ocenie KF AmCham, zgoda przewidziana w przepisie art. 4b PF również powinna być wskazana w tym przepisie, jak również właściwym byłoby odniesienie poziomu ceny do „obecnie obowiązującej decyzji”, nie „ostatniej decyzji”. Należy zauważyć, że procedura przewidziana w art. 30aa dotyczy problemów z dostępnością dla leków aktualnie objętych refundacją. \\t\\t\\fUwaga niezasadna Intencją Ministra Zdrowia jest dopuszczenie możliwości wprowadzenia opakowań obcojęzycznych wyłącznie na ratunek pacjentom w przypadku braku \\fdostępności do leku dostarczanego przez Wnioskodawcę. Jest to wyłącznie alternatywa dla pacjentów, a nie rozwiązanie dla Wnioskodawców\\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 30 projektu dotyczący art. 30aa ust. 1, 2 i 5 (nowy)\\t1. Dla leku ujętego w wykazie, o którym mowa w art. 37 ust. 1, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, wnioskodawca może złożyć wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla tego samego leku w obcojęzycznym opakowaniu w przypadku uzyskania zgody, o której mowa w art. 4c ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. Do takiego wniosku  nie stosuje się przepisów art. 24 ust. 2 pkt 1–2 i 6, art. 25 pkt 4, 7, 8, \\f12-14 oraz są zwolnione z negocjacji cenowych z Komisją.  2. Cena zbytu netto oraz cena efektywna nie mogą być wyższe niż w ostatniej decyzji administracyjnej o objęciu refundacją dla leku ujętego w wykazie, o którym mowa w art. 37, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. (…) 5. Wniosek, o którym mowa w art. 24 ust. 1 pkt 1, w przypadku, o którym mowa w ust. 1, rozpatruje się w terminie 30 dni. Opłat, o których mowa w  art. 32 ust. 1, nie pobiera się.  \\t\\fProsimy o usunięcie słów „i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne,”. Uzyskanie zgody na wprowadzanie do obrotu leku z obcojęzycznym oznakowaniem na podstawie art. 4c PF nie jest warunkowane umieszczeniem leku na wykazie produktów deficytowych (z art. 37av ust. 14). Taki warunek jest też zbyt ograniczający, bowiem nie pozwala reagować na przejściowe (a nie długotrwałe) braki na rynku, którym \\fmożna byłoby zaradzić za pomocą leków w opakowaniach obcojęzycznych zanim zajdzie konieczność umieszczenia ich na liście produktów deficytowych. Celem nowego przepisu powinno być reagowanie na zagrożenie brakami, a nie oczekiwanie, aż dojdzie do braków odczuwalnych w skali całego kraju.   Co do usunięcia określenia „cenowych” należy wskazać, że ustawa nie rozróżnia negocjacji na cenowe i inne.      Koniecznym jest wprowadzenie trzydziestodniowego terminu na rozpatrzenie wniosku oraz zwolnienie go z opłat, aby uniknąć opóźnień mogących pogłębić problemy z dostępnością produktów leczniczych dla pacjentów.  \\t\\fUwaga niezasadna Intencją Ministra Zdrowia jest dopuszczenie możliwości wprowadzenia opakowań obcojęzycznych wyłącznie na ratunek pacjentom w przypadku braku dostępności do leku dostarczanego przez Wnioskodawcę. Jest to wyłącznie alternatywa dla pacjentów, a nie rozwiązanie dla Wnioskodawców.\\n\\tPracodawcy RP\\tArt. 1 pkt 30 projektu dotyczący art. 30aa ust. 1 i2 ustawy refundacyjnej\\tW odniesieniu do art. 30aa ust. 1 i 2 proponujemy wprowadzenie następujących zmian: 1. Dla leku ujętego w wykazie, o którym mowa w art. 37 ust. 1, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, wnioskodawca może złożyć wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla tego samego leku w obcojęzycznym opakowaniu w przypadku uzyskania zgody, o której mowa w art. 4b lub 4c ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. \\fDo takiego wniosku  nie stosuje się przepisów art. 24 ust. 2 pkt 1–2 i 6, art. 25 pkt 4, 7, 8, 1214 oraz są zwolnione z negocjacji cenowych z Komisją.  2. Cena zbytu netto oraz cena efektywna leku, o którym mowa w ust. 1, nie mogą być wyższe niż w ostatniej obowiązującej decyzji administracyjnej o objęciu refundacją dla leku ujętego w wykazie, o którym mowa w art. 37, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. albo, alternatywnie, w przypadku nieuwzględnienia argumentów w odniesieniu do powyższej propozycji: 1. Dla leku ujętego w wykazie, o którym mowa w art. 37 ust. 1, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne albo w przypadku uzasadnionego zagrożenia brakiem dostępności leku ujętego w wykazie, o którym mowa w art. 37 ust. 1, wnioskodawca może złożyć wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla tego samego leku w obcojęzycznym opakowaniu w przypadku uzyskania zgody, o której mowa w art. 4b lub 4c ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne. Do takiego wniosku  nie stosuje się przepisów art. 24 ust. 2 pkt 1–2 i 6, art. 25 pkt 4, 7, 8, 1214 oraz są zwolnione z negocjacji cenowych z Komisją.  \\f2. Cena zbytu netto oraz cena efektywna leku, o którym mowa w ust. 1, nie mogą być wyższe niż w ostatniej obowiązującej decyzji administracyjnej o objęciu refundacją dla leku ujętego w wykazie, o którym mowa w art. 37, i w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne.\\t\\fW ocenie Pracodawców możliwość refundacji opakowań obcojęzycznych nie powinna być uzależniona od obecności danego leku na tzw. liście antywywozowej. Wprowadzenie takiej możliwości dla wszystkich leków byłoby korzystne z punktu widzenia zapewnienia ciągłości dostaw produktów leczniczych i utrzymania niezakłóconego dostępu do refundowanego leczenia. Zdaniem Pracodawców RP nie ma podstaw aby przewidywać nadużywanie tego rozwiązania. \\fAlternatywnie, jeżeli powyższe argumenty nie uzyskają aprobaty, Pracodawcy RP proponują, aby możliwe było złożenie wniosku także w sytuacji uzasadnionego zagrożenia brakiem dostępności, które nie zostało jeszcze odzwierciedlone w wykazie, o którym mowa w art. 37av ust. 14 ustawy z dnia 6 września 2001 r. – Prawo farmaceutyczne, ale już na danym etapie można przypuszczać, że zaistnieje problem z dostępnością leku w refundowanych opakowaniach. \\t\\fUwaga niezasadna Intencją Ministra Zdrowia jest dopuszczenie możliwości wprowadzenia opakowań obcojęzycznych wyłącznie na ratunek pacjentom w przypadku braku dostępności do leku dostarczanego przez Wnioskodawcę. Jest to wyłącznie alternatywa dla pacjentów, a nie rozwiązanie dla Wnioskodawców\\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 30 projektu dotyczący art. 30aa ustawy refundacyjnej\\tINFARMA dziękuję za wprowadzenie takiego mechanizmu. Prosimy jednak o potwierdzenie, że w zarządzeniach Prezesa NFZ ws. programów lekowych oraz chemioterapii – pomimo wprowadzenia tej instytucji prawnej – utrzymane zostanie rozwiązanie dotyczące odpowiednio załączników 2t oraz 1t do tych zarządzeń.\\t\\t\\tPoza zakresem projektu \\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 30 projektu dotyczący art. 30aa ust. 1a ustawy refundacyjnej\\tnaszym zdaniem zasadne byłoby umożliwienie wnioskodawcom ubiegania się o refundację w uproszczonym trybie opakowań obcojęzycznych wszelkich leków refundowanych, nie tylko tych umieszczonych na liście antywywozowej.\\t\\tArt. 30aa - procedura refundacji opakowań obcojęzycznych leków już refundowanych \\tNowa, szybsza i prostsza procedura obejmowania refundacją opakowań obcojęzycznych leków, które już są refundowane (w polskich opakowaniach), jest bardzo potrzebna – rzeczywiście wobec częstych braków leków w obrocie konieczne jest wprowadzenie szybkiej ścieżki obejmowania refundacją opakowań obcojęzycznych, które mogłyby być wprowadzone do obrotu w Polsce w celu uzupełnienia braków dostępności polskich opakowań. \\tProsimy jednak o rozważenie poszerzenia zakresu zastosowania tej \\fprocedury i objęcia nią potencjalnie innych leków niż tylko te z listy antywywozowej. Jak rozumiemy, powodem ograniczenia zastosowania tej procedury tylko do produktów z wykazu, o którym mowa w art. 37av Prawa farmaceutycznego, jest fakt, że tylko w odniesieniu do takich leków wnioskodawca miałby ponosić odpowiedzialność z tytułu niezachowania ciągłości dostaw lub niespełnienia rocznego zobowiązania w zakresie wielkości dostaw. Jednakże wnioskodawcom zależy na refundacji opakowań obcojęzycznych leków, co do których występują braki, nie tylko z obawy przed nałożeniem na nich kary pieniężnej z art. 34 ustawy o refundacji, ale przede wszystkim po to, by zapewnić pacjentom ciągłość leczenia. Dlatego naszym zdaniem zasadne byłoby umożliwienie wnioskodawcom ubiegania się o refundację w uproszczonym trybie opakowań obcojęzycznych wszelkich leków refundowanych, nie tylko tych umieszczonych na liście antywywozowej.\\t\\fUwaga niezasadna Intencją Ministra Zdrowia jest dopuszczenie możliwości wprowadzenia opakowań obcojęzycznych wyłącznie na ratunek pacjentom w przypadku braku dostępności do leku dostarczanego przez Wnioskodawcę. Jest to wyłącznie alternatywa dla pacjentów, a nie rozwiązanie dla Wnioskodawców\\n\\tAmerykańska Izba Handlowa w Polsce/ Pracodawcy RP\\tArt. 30ab (nowy) ustawy refundacyjnej\\tProponujemy rozważenie wprowadzenia uproszczonej procedury zmiany kodu GTIN w decyzji o objęciu refundacją poprzez wprowadzenie przepisu analogicznego dla nowo dodawanego art. 30aa. Proponujemy dodanie art. 30ab w brzmieniu:  \\f1. W przypadku zmiany numeru GTIN lub innego kodu jednoznacznie identyfikującego wyrób medyczny lub środek spożywczy specjalnego przeznaczenia żywieniowego, o którym mowa w art. 25 pkt 5 lit. c, art. 25a pkt 5 lit. c i art. 25b pkt 5 lit. c, dla leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego ujętego w wykazie, o którym mowa w art. 37 ust. 1, wnioskodawca może złożyć wniosek, o którym mowa w art. 24 ust. 1 pkt 1, dla tego samego leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego w opakowaniu oznaczonym innym numerem GTIN lub innym kodem jednoznacznie identyfikującym wyrób medyczny lub środek spożywczy specjalnego przeznaczenia żywieniowego niż określony w obowiązującej decyzji, o której mowa w art. 11. Do takiego wniosku nie stosuje się przepisów art. 24 ust. 2 pkt 1–2 i 6, art. 25 pkt 4, 7, 8, 12, 14 oraz jest on zwolniony z negocjacji cenowych z Komisją.  2. Decyzję administracyjną o objęciu refundacją dla leku, o którym mowa w ust. 1, minister właściwy do spraw zdrowia wydaje na okres nie dłuższy niż decyzja o objęciu refundacją dla tego leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego ujętego w wykazie, o którym mowa w art. 37 ust. 1 i na warunkach w zakresie ceny zbytu netto oraz instrumentu dzielenia \\fryzyka określonych w obecnie obowiązującej decyzji o objęciu refundacją dla tego leku. 3. Wprowadzone do obrotu jednostkowe opakowania leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego, o którym mowa w ust. 1, w przypadku objęcia refundacją zalicza się na poczet zobowiązania, o którym mowa w art. 11 ust. 2 pkt 9, określonego w decyzji administracyjnej o objęciu refundacją leku, środka spożywczego specjalnego przeznaczenia żywieniowego lub wyrobu medycznego ujętego w wykazie, o którym mowa w art. 37 ust. 1.\\t\\fW związku z wprowadzeniem rozwiązania uregulowanego w art. 25e (przeniesienie praw i obowiązków z decyzji na inny podmiot), art. 30aa (refundacja opakowań obcojęzycznych) oraz art. 30 ust. 4 i 5 (skrócenie techniczne) prosimy o rozważenie wprowadzenia uproszczonej procedury \\fpozwalającej na zmianę kodu GTIN w decyzji o objęciu refundacją. \\tZe względu na wymogi dotyczące nadawania i zmiany kodów GTIN, wytwórcy produktów leczniczych są niejednokrotnie zmuszeni do nadawania nowych kodów w przypadku dokonywania nawet niezbyt istotnych zmian technicznych, jak np. zmiana wyglądu opakowania leku.. Sytuacje takie zdarzają się w odniesieniu do produktów, które są objęte refundacją w Polsce, w efekcie czego konieczne staje się uruchomienie procesu skrócenia obecnie obowiązującej decyzji o objęciu refundacją połączonego z objęciem refundacją w praktyce tego samego opakowania, ale o innym kodzie GTIN. Niestety, ze względu na brak wpływu wytwórców na konieczność dokonywania takich zmian, nie ma możliwości ich uniknięcia, a ze względu na oparcie polskiego systemu refundacji o kody GTIN, każda taka zmiana wiąże się ze wspomnianą powyżej, kłopotliwą procedurą dokonywania zmian. Z tego względu prosimy o rozważenie uproszczenia tego procesu analogicznie jak zaproponowano dla ww. przypadków.\\t\\fUwaga niezasadna Praktyka Ministra Zdrowia w zakresie wymagalności złożenia wniosku o objęcie refundacją nowego GTIN produktu podyktowana jest szczególnym znaczeniem identyfikacyjnym tegoż numeru i nie jest rozważana zmiana podejścia w tym zakresie.  Zmiany określane terminem „technicznych” są aktualnie \\fprzeprowadzanie postępowaniem z art. 155 kpa – na zasadach i zgodnie z przepisami prawa. \\n\\tPolsko-Niemiecka Izba Przemysłowo- Handlowa\\\\ Związek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 31 lit. a projektu odnoszący się do art. 30b ust. 1 ustawy refundacyjnej \\tSkreślić w ust. 1 – w pkt 1 i 2 średnik zastępuje się przecinkiem, – w pkt 4 skreśla się kropkę i dodaje się cześć wspólną w brzmieniu: „– w zakresie, w jakim dotyczą instrumentu dzielenia ryzyka.” Art. 30 ust. 1 powinien otrzymać brzmienie: Art. 30b. 1. Tajemnicą refundacyjną są objęte informacje:  1) zawarte we wniosku, o którym mowa w art. 24 ust. 1, oraz w innych dokumentach składanych przez wnioskodawców lub wytworzonych w postępowaniu wszczętym takim wnioskiem, 1a) przekazywane ministrowi właściwemu do spraw zdrowia na podstawie art. 25d ust. 1, \\f1b) zawarte we wniosku, o którym mowa w art. 16aa, oraz w innych dokumentach składanych przez wnioskodawców lub wytworzonych w postępowaniu wszczętym takim wnioskiem,   2) z posiedzenia Komisji, o których mowa w art. 18 ust. 3, 3) dotyczące negocjacji, o których mowa w art. 19 ust. 1, oraz  4) uzyskane w trakcie prowadzonych negocjacji dodatkowych, o których mowa w art. 18a ust. 2.\\t\\fNie ma żadnych powodów, aby ograniczać tajemnicę refundacyjną tylko do instrumentów dzielenia ryzyka.  Z perspektywy wnioskodawcy tajemnicą są nie tylko ww. informacje, ale także inne informacje dotyczące refundacji np.  wnioskowana cena zbytu netto, informacje o cenach w innych krajach, w tym o instrumentach podziału ryzyka, wyniki nieopublikowanych badań [które czekają na publikację], wyniki raportów i analiz przygotowanych na potrzeby wniosku refundacyjnego [opłacone przez Wnioskodawcę z możliwością ich wykorzystania przez inne podmioty], wnioski z panelu ekspertów, wyniki niepublikowanych badań ankietowych przeprowadzonych w gronie ekspertów klinicznych, \\fzałożenia dotyczące przyjętej strategii cenowej, informacje dot. struktury sprzedaży danego leku na innych rynkach  Uzasadnienie INFARMA: Nie ma żadnych powodów, aby ograniczać tajemnicę refundacyjną tylko do instrumentów dzielenia ryzyka.  Z perspektywy wnioskodawcy tajemnicą są nie tylko ww. informacje, ale także inne informacje dotyczące refundacji np.  wnioskowana cena zbytu netto, informacje o cenach w innych krajach, w tym o RSS, wyniki nieopublikowanych badań [które czekają na publikację], wyniki raportów i analiz przygotowanych na potrzeby wniosku refundacyjnego [opłacone przez Wnioskodawcę z możliwością ich wykorzystania przez inne podmioty], wnioski z Advisory Board, założenia dotyczące przyjętej strategii cenowej, informacje dot. struktury sprzedaży danego leku na innych rynkach. Upublicznienie tych informacji miałoby istotne znaczenie dla firm konkurencyjnych natomiast dla większości pacjentów mają one znaczenie marginalne. Ponadto, brak znajomości EBM i HTA z szerokim udostępnieniem danych z procesu refundacyjnego może prowadzić do niezrozumienia stanowiska i strategii \\ffirmy, a w konsekwencji negatywnych doniesień medialnych (z którymi ciężko walczyć przy jednoczesnym zachowaniu tajemnicy przedsiębiorstwa). Co więcej, kierunkiem nie powinno być ograniczanie, ale rozszerzenie tajemnicy refundacyjnej. Tajemnicą przedsiębiorstwa, a w konsekwencji także tajemnicą refundacyjną powinny być objęte także informacje przekazywane w ramach nowych instytucji proponowanych nowelizacją, tj. „horizon scanning” oraz prekonsultacji. W uzasadnieniu MZ wskazuje na trudności związane z obecnie obowiązującą definicją podając przykład przedstawienia CZN na Obwieszczeniu. Wydaje się to jednak błędną argumentacją. Art. 37 ust. 2 UR to wprost lex specialis, a więc przepis szczególny, wobec art. 30b, co oznacza że wprost wyłącza on zastosowanie w tym przypadku tajemnicy przedsiębiorstwa. Warto wskazać, że z perspektywy wnioskodawcy ujawnienie informacji o potencjalnym rozpoczęciu procesu refundacyjnego jest również istotną informacją, o dużej wartości gospodarczej.\\t\\fUwaga niezasadna Proponowane w uwadze rozwiązanie mogłoby prowadzić do ograniczenia transparentności postępowań refundacyjnych oraz utrudniać obywatelom i podmiotom rynku farmaceutycznego dostęp do wiedzy o toku postępowań administracyjnych. W konsekwencji takie rozwiązanie byłoby sprzeczne z zasadą przejrzystości działania administracji publicznej i mogłoby naruszać prawo do informacji.  Jednocześnie należy podkreślić, że interesy Wnioskodawców są chronione poprzez instytucję tajemnicy przedsiębiorstwa, o której mowa w art. 11 ust. 2 ustawy z dnia 16 kwietnia 1993 r. o zwalczaniu nieuczciwej konkurencji (Dz. U. z 2022 r. poz. 1233, z późn. zm.). Przepis ten gwarantuje ochronę \\finformacji, które nie są powszechnie znane i w odniesieniu do których przedsiębiorca podjął niezbędne działania w celu zachowania ich poufności. Tym samym zaproponowane rozwiązania prawne zapewniają właściwą równowagę pomiędzy prawem obywateli do informacji a ochroną interesów przedsiębiorców. \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 1 pkt 31 lit. a projektu odnoszący się do art. 30b ust. 5 ustawy \\frefundacyjnej \\t\\f5. W przypadku przekazania informacji objętych tajemnicą przedsiębiorstwa w rozumieniu art. 11 ust. 2 ustawy z dnia 16 kwietnia 1993 r. o zwalczaniu nieuczciwej konkurencji (Dz. U. z 2022 r. poz. 1233) innym organom krajowym, zagranicznym organom regulacyjnym, z wyłączeniem \\fsądów lub prokuratury, informacje i dokumenty przekazuje się wraz z zastrzeżeniem i pod warunkiem przestrzegania tej tajemnicy. Przepisy ust. 2-4 oraz art. 35 ust. 4a i 4b stosuje się odpowiednio.  \\t\\fW ust. 1 Projekt bardzo ogranicza tajemnice refundacyjną, zawężając ją do danych o instrumentach dzielenia ryzyka. W tej sytuacji ważne jest, aby zapewnić jasne zasady ochrony informacji na innej podstawie prawnej, jaka jest tajemnica przedsiębiorstwa.  \\fW związku z tym proponujemy, aby w przypadku informacji objętych tajemnicą przedsiębiorstwa, których dotyczy ust. 5, określić: katalog zobowiązanych do jej dochowania, czas obowiązywania oraz wyłączenia ochrony – w sposób analogiczny do ochrony tajemnicy refundacyjnej, zaś zasady zastrzegania tajemnicy – w sposób analogiczny do ochrony tajemnicy przedsiębiorstwa zawartej w analizie weryfikacyjnej AOTMiT. \\t\\fUwaga niezasadna  j.w.\\n\\tFederacja Przedsiębiorców Polskich\\tArt. 1 pkt 31 lit. a projektu odnoszący się do art. 30b ust. 1 ustawy refundacyjnej\\tArt. 30b. 1. Tajemnicą refundacyjną są objęte informacje:   1) zawarte we wniosku, o którym mowa w art. 24 ust. 1, oraz w innych dokumentach składanych przez wnioskodawców lub wytworzonych w postępowaniu wszczętym takim wnioskiem,  1a) zawarte przekazywane do ministra właściwego do spraw zdrowia na podstawie art. 25d ust. 1,  1b) przekazane i uzyskane w ramach procedury wydania wstępnej opinii, o której mowa w art. 16aa;  2) z posiedzenia Komisji, o których mowa w art. 18 ust. 3,  3) dotyczące negocjacji, o których mowa w art. 19 ust. 1, oraz 4) uzyskane w trakcie prowadzonych negocjacji dodatkowych, o których mowa w art.18a ust. 2.\\tRozszerzenie zakresu tajemnicy refundacyjnej o informacje uzyskane w ramach procedury wydania wstępnej opinii.\\tUwaga niezasadna  j.w. \\n\\tIzba Gospodarcza „FARMACJA POLSKA\\tArt. 1 pkt 31 lit. a projektu \\fodnoszący się do art. 30b ust. 1 ustawy refundacyjnej\\t\\fdefinicja tajemnicy przedsiębiorstwa powinna być szersza i powinna obejmować wszelkie niejawne informacje \\fwnioskodawcy, które ten oznaczył jako poufne, zawarte we wniosku, dokumentach załączonych do wniosku lub składanych w toku postępowań refundacyjnych.\\t\\fZaproponowana w projekcie nowelizacji zmiana polegająca na zawężeniu zakresu tajemnicy refundacyjnej tylko do kwestii \\fzwiązanych z instrumentem dzielenia ryzyka wiąże się z istotnym ryzykiem dla wnioskodawców, które może wpłynąć negatywnie na decyzje o ubieganiu się o refundację poszczególnych produktów. Niewątpliwie treść i warunki instrumentu dzielenia ryzyka stanowią informacje poufne wnioskodawcy, będące jego tajemnicą przedsiębiorstwa; i objęcie tych informacji ochroną jako tajemnicy refundacyjnej jest uzasadnione. Jednakże wnioski refundacyjne i inne składane w postępowaniach refundacyjnych przez wnioskodawców dokumenty zawierają więcej informacji niejawnych, które powinny podlegać ochronie prawnej. Są to, przykładowo, dane z nieopublikowanych jeszcze badań klinicznych, czy szczegółowe informacje o cenach  i warunkach refundacji produktów na innych rynkach. Wyłączenie takich informacji z zakresu ochrony jako tajemnica refundacyjna naraża wnioskodawców na ryzyko ujawnienia tych informacji i w efekcie ich wykorzystania bez zgody wnioskodawców przez osoby trzecie.  Co istotne, objęcie poufnych informacji o wartości gospodarczej, dotyczących wnioskodawcy, chroni nie tylko przed ich spontanicznym ujawnieniem przez organ, ale przede wszystkim przed uzyskaniem do nich dostępu przez osoby trzecie w trybie dostępu do informacji publicznej.  W razie odmowy ich udostępnienia z uwagi na tajemnicę przedsiębiorstwa, jeżeli objęcie danej informacji poufnością nie wynika wprost z przepisu ustawy, \\fpodlega ewentualnemu zaskarżeniu do sądu administracyjnego, co w rezultacie może doprowadzić do ujawnienia informacji nawet, jeżeli organ sam nie zamierzał jej ujawniać. Dlatego wprowadzenie do ustawy o refundacji szerszej definicji tajemnicy refundacyjnej, obejmującej nie tylko dane z instrumentu dzielenia ryzyka, ale też inne niejawne informacje wnioskodawcy, które wnioskodawca oznaczył jako tajemnicę, stanowi jedyny pewny sposób na zagwarantowanie wnioskodawcom, że ich poufne informacje (np. dane z nieopublikowanego jeszcze badania) nie zostaną wykorzystane bez ich zgody.  Dlatego uważamy, że definicja tajemnicy przedsiębiorstwa powinna być szersza i powinna obejmować wszelkie niejawne informacje wnioskodawcy, które ten oznaczył jako poufne, zawarte we wniosku, dokumentach załączonych do wniosku lub składanych w toku postępowań refundacyjnych.\\t\\fUwaga niezasadna  j.w. \\n\\tAmerykańska Izba Handlowa w Polsce/Pracodawcy RP\\tArt. 1 pkt 31 lit. a projektu odnoszący się do art. 30b ust. 1 oraz art. 30b ust. 4 ustawy refundacyjnej\\tW art. 30b proponujemy: ust. 1 nadanie następującego brzmienia: „1. Tajemnicą refundacyjną są objęte informacje: 1) zawarte we wniosku, o którym mowa w art. 24 ust. 1, we wniosku oraz opinii, o których mowa w art. 16aa oraz w innych dokumentach składanych przez wnioskodawców lub wytworzonych w \\fpostępowaniu wszczętym takim wnioskiem, 2) z posiedzenia Komisji, o których mowa w art. 18 ust. 3, 3) dotyczące negocjacji, o których mowa w art. 19 ust. 1,  4) uzyskane w trakcie prowadzonych negocjacji dodatkowych, o których mowa w art. 18a ust. 2, oraz 5) przekazywane zgodnie z art. 25d. – w zakresie, w jakim dotyczą instrumentu dzielenia ryzyka. w ust. 4 uchylenie pkt 2.\\t\\f Uzasadnienie Pracodawców RP do pkt 1 Ad. 1) Ograniczenie tak szerokiego katalogu poufnych danych i informacji przekazywanych przez wnioskodawców podczas postępowania o objęcie informacją nie może być ograniczone jedynie w zakresie w jakim dotyczą one instrumentu dzielenia ryzyka. Zmiana ta może spowodować bardzo wysokie ryzyko ujawnienia informacji stanowiących tajemnicę \\fprzedsiębiorstwa i z tego względu należy z niej zdecydowanie zrezygnować. Uzasadnienie Amerykańska Izba Handlowa w Polsce/Pracodawcy RP Ad. a) Ograniczenie tak szerokiego katalogu poufnych danych i informacji przekazywanych przez wnioskodawców podczas postępowania o objęcie refundacją nie może być ograniczone jedynie w zakresie w jakim dotyczą one instrumentu dzielenia ryzyka. Przykładowo, w ramach postępowań wnioskodawcy często przedstawiają w analizach niepublikowane dotąd dane z badań klinicznych lub subanalizy, które przedstawiają wyniki badań w populacjach jak najbardziej zbliżonych do wnioskowanej. Tego rodzaju dane i informacje są wymagane przez AOTMiT w toku oceny dossier refundacyjnego i bez przedstawienia takich danych może dojść do stwierdzenia przez AOTMiT, że nie zostały spełnione minimalne wymagania dla analiz HTA. Wówczas AOTMiT może wydać negatywną rekomendację, co może przełożyć się na wynik całego postępowania refundacyjnego. Takie dane mogą być objęte tzw. embargo, np. w sytuacji, kiedy oczekiwana jest publikacja w czasopiśmie naukowym albo też dane takie są udostępnianie pod warunkiem zapewnienia ich poufności. Jednocześnie, \\fżadne z tych danych nie są bezpośrednio powiązane z instrumentami dzielenia ryzyka, a w konsekwencji, pomimo ich istotnej poufności, w praktyce nie byłyby objęte ochroną. Z tych względów zaproponowana w Projekcie zmiana może doprowadzić do sytuacji, w których dojdzie do ujawnienia informacji stanowiących tajemnicę przedsiębiorstwa. Dlatego też, w ocenie KF AmCham należy zrezygnować z zaproponowanego ograniczenia zakresu tajemnicy refundacyjnej.. Dodatkowo, KF AmCham stoi na stanowisku, że tajemnicą refundacyjną powinny być objęte dane i informacje przekazywane w ramach wniosku o wydanie wstępnej opinii dotyczącej kategorii dostępności refundacyjnej, jak również informacji o planowanych wnioskach o objęcie refundacją, składanych zgodnie z przepisem art. 25d. Ad. b) Duże wątpliwości z punktu widzenia bardzo newralgicznego tematu jakim jest system cen referencyjnych w Europe budzi nowo dodany art. 30b UoR. Uregulowano w nim kwestię tajemnicy refundacyjnej w tym, między innymi, informację nią objętą oraz podmioty zobowiązane do jej przestrzegania. W przepisie ust. 4 określono sytuacje, w których MZ oraz osoby zatrudnione w urzędzie go obsługującym są zwolnieni z \\fobowiązku przestrzegania tajemnicy refundacyjnej. I tak, jedną z tych sytuacji jest realizacja postanowień umów międzynarodowych, bilateralnych lub porozumień w zakresie wymiany informacji dotyczących refundacji. Ustanowienie nowych platform wymiany poufnych informacji dotyczących warunków refundacji poszczególnych produktów w Polsce może stanowić bardzo duże zagrożenie z punktu widzenia stabilności działalności prowadzonej przez spółki z sektora farmaceutycznego o zasięgu międzynarodowym lub globalnym. Z tego względu, wprowadzenie praktycznej możliwości zawarcia umów lub porozumień z dowolnymi państwami, na podstawie których Polska przekazywać będzie sensytywne informacje na temat cen efektywnych lub innych szczegółów instrumentów dzielenia ryzyka, należy ocenić jako niebezpieczne. W skrajnym przypadku, wymiana poufnych informacji z innymi krajami może skutkować obawami niektórych wnioskodawców odnośnie do zawierania instrumentów dzielenia ryzyka, co znowuż przełoży się na odmowę objęcia refundacją. Przyznawana przez centrale polskich wnioskodawców elastyczność cenowa w zakresie ceny efektywnej i innych elementów instrumentu dzielenia ryzyka może zostać ograniczona, ze względu na obawę o wpływ takich poufnych \\finformacji na ceny w innych krajach. Konsekwencją może być nie tylko wzrost cen efektywnych leków w Polsce, ale niekiedy może także skutkować decyzją o odłożeniu złożenia wniosku o objęcie refundacją. Możliwość zaoferowania często najniższych cen w Europie w ramach instrumentów dzielenia ryzyka wynika właśnie z ich poufności.\\t\\fUwaga niezasadna Ad a) Zaproponowane brzmienie wskazanego przepisu jest właściwe i nie wymaga zmiany, bowiem zapewnia możliwość informowania obywateli o toczących się postępowaniach refundacyjnych oraz o etapie ich zaawansowania.  Proponowana modyfikacja mogłaby prowadzić do ograniczenia transparentności. Należy podkreślić, że \\finteresy Wnioskodawców są chronione poprzez instytucję tajemnicy przedsiębiorstwa, o której mowa w art. 11 ust. 2 ustawy z dnia 16 kwietnia 1993 r. o zwalczaniu nieuczciwej konkurencji (Dz. U. z 2022 r. poz. 1233, z późn. zm.). Przepis ten gwarantuje ochronę informacji, które nie są powszechnie znane i w odniesieniu do których przedsiębiorca podjął niezbędne działania w celu zachowania ich poufności. Tym samym zaproponowane rozwiązania prawne zapewniają właściwą równowagę pomiędzy prawem obywateli do informacji a ochroną interesów przedsiębiorców.  Uwaga niezasadna  Ad b) Polska jako członek Unii Europejskiej oraz sygnatariusz licznych umów międzynarodowych uczestniczy w formalnych mechanizmach wymiany informacji dotyczących polityki lekowej i systemów refundacyjnych z innymi krajami. W szczególności, na podstawie przepisów prawa UE. Dane te są wykorzystywane m.in. do analiz referencyjnych oraz kształtowania polityki refundacyjnej co umożliwia efektywne kształtowanie polityki refundacyjnej. \\fPonadto należy wskazać, iż wyjątki od zasady zachowania tajemnicy refundacyjnej zostały precyzyjnie określone i wskazane w tymże przepisie, tj. 1) wykonywanie zadań związanych z refundacją leków, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych przez Fundusz, Agencję lub świadczeniodawcę; 2) realizacja postanowień umów międzynarodowych, bilateralnych lub porozumień w zakresie wymiany informacji dotyczących refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych; 3) wykonanie obowiązków informacyjnych wobec Komisji Europejskiej.  \\n\\tZwiązek Pracodawców  Innowacyjnych Firm Farmaceutycznych INFARMA\\tArt. 1 pkt 31 lit. d projektu odnoszący się do art. 30b ust. 5 ustawy refundacyjnej \\tSkreślenie proponowanej oraz obecnie obwiązującej wersji przepisu. Alternatywnie: 5. W przypadku przekazania informacji objętych tajemnicą przedsiębiorstwa w rozumieniu art. 11 ust. 2 ustawy z dnia 16 kwietnia 1993 r. o zwalczaniu nieuczciwej konkurencji (Dz. U. z 2022 r. poz. 1233) innym organom krajowym, zagranicznym organom regulacyjnym i instytucjom współdziałającym z tymi organami, z wyłączeniem sądów lub prokuratury, informacje i dokumenty przekazuje się wraz z zastrzeżeniem i pod warunkiem przestrzegania tej tajemnicy.\\tZobacz uzasadnienie do art. 30b ust. 4 ustawy refundacyjnej.\\tUwaga niezasadna  Zgodnie z obowiązującym stanem prawnym, przekazywanie informacji uregulowane w art. 30b ust. 5 ustawy o refundacji odbywa się wyłącznie pomiędzy organami publicznymi krajowymi lub zagranicznymi w ramach realizacji ustawowych kompetencji oraz zobowiązań międzynarodowych, których stroną jest Rzeczpospolita Polska, w szczególności w ramach prawa Unii Europejskiej.  Wyjątki od zasady zachowania tajemnicy refundacyjnej zostały precyzyjnie określone i wskazane w tymże przepisie, tj. 1) wykonywanie zadań związanych z refundacją leków, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych przez Fundusz, Agencję lub świadczeniodawcę; 2) realizacja postanowień umów międzynarodowych, bilateralnych lub porozumień w zakresie wymiany informacji dotyczących refundacji leków, środków spożywczych specjalnego przeznaczenia żywieniowego lub wyrobów medycznych; 3) wykonanie obowiązków \\finformacyjnych wobec Komisji Europejskiej.  \\n\\tPolski Związek Pracodawców Przemysłu Farmaceutycznego\\tArt. 31 ust. 3a-3b\\t3a. Do postępowań wszczętych na podstawie wniosku, o którym mowa w art. 24 ust. 1, nie stosuje się przepisów art. 98 ustawy z dnia 14 czerwca 1960 r. - Kodeks postępowania administracyjnego. 3b. Minister właściwy do spraw zdrowia może z urzędu, w drodze postanowienia, zawiesić postępowanie wszczęte na podstawie wniosku, o którym mowa w art. 24 ust. 1, na okres nie dłuższy niż 90 dni, jeżeli wymaga tego interes społeczny. Przepisu art. 102 ustawy z dnia 14 czerwca 1960 r. - Kodeks postępowania administracyjnego nie stosuje się.\\tNowelizacja z dnia 17 sierpnia 2023 r. w znacznym stopniu ograniczyła możliwość zawieszenia postępowania refundacyjnego na wniosek strony, Wyłączono stosowanie art. 98 KPA oraz wprowadzono możliwość zawieszenia postępowania z urzędu na okres nie dłuższy niż 90 dni, jeżeli wymaga tego interes społeczny. Wprowadzone rozwiązanie jest nieuzasadnione z punktu widzenia zasad postępowania administracyjnego. Postępowanie w sprawie objęcia refundacją jest postępowaniem wnioskowym, a więc takim, którego przedmiotem, włącznie z wolą wszczęcia i prowadzenia postępowania, dysponuje strona. W przypadku postępowań wnioskowych prawo do zawieszenia postępowania na wniosek należy do najważniejszych uprawnień strony. Art. 98 KPA przewiduje przy tym możliwość odmowy zawieszenia, jeżeli sprzeciwia się temu interes społeczny, zatem Minister Zdrowia ma instrument przeciwdziałania ewentualnym przypadkom nadużywania tej instytucji.  Produkcja leków jest specyficznym obszarem gospodarczym, skupiającym wokół siebie wiele skoordynowanych procesów, które mogą mieć istotny wpływ na zapewnienie dostępności do leków dla pacjentów. Wobec tego Wnioskodawca powinien mieć możliwość zawieszenia postępowania mając na uwadze nieprzewidziane \\fokoliczności oraz interes gospodarczy i społeczny. Wnioski o zawieszenie postępowań refundacyjnych często służą temu, by wnioskująca firma miała czas na wewnętrzne ustalenia i uzyskanie zgody na korzystniejsze niż dotychczas proponowane warunki cenowe refundacji, co daje szansę na uzyskanie refundacji. Niemożność zawieszenia postępowania oznacza, że w imię szybkości postępowania (której zawieszenia nie służą) więcej wniosków skończy się odmową objęcia refundacją, co będzie niekorzystne dla pacjentów. \\t\\fUwaga niezasadna Wnioskodawca zachowuje możliwość zwrócenia się do Ministra Zdrowia z pismem zawierającym prośbę o czasowe wstrzymanie biegu postępowania refundacyjnego, dotychczas każda tego rodzaju prośba była rozpatrywana indywidualnie i jeśli znajdowała uzasadnienie - uwzględniana. Wyłączenie stosowania art. 98 kpa w omawianym zakresie podyktowane jest natomiast koniecznością przeciwdziałania nadużyciom polegającym na instrumentalnym zawieszaniu postępowań nawet na okres do trzech lat, co obserwowano w praktyce w sytuacjach, gdy rozstrzygnięcia Prezesa a Agencji Oceny Technologii Medycznych i Taryfikacji, Komisji Ekonomicznej czy Ministra Zdrowia były dla strony niekorzystne. Postępowanie refundacyjne realizuje cel publiczny polegający na zapewnieniu pacjentom jak najszybszego dostępu do terapii finansowanych ze środków publicznych. W tym kontekście wykorzystanie przez wnioskodawców mechanizmów zawieszania postępowania w celu odsunięcia w czasie wydania negatywnej decyzji administracyjnej stoi w sprzeczności z zasadą szybkości i sprawności \\fpostępowania oraz narusza interes społeczny.  Celem systemu refundacyjnego nie jest zaspokajanie interesów poszczególnych podmiotów, lecz zapewnienie wszystkim pacjentom szerokiego i terminowego dostępu do opcji. Z tego względu ograniczenie możliwości zawieszania postępowania jedynie do sytuacji, gdy przemawia za tym interes publiczny jest w pełni zasadne.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     