umber\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"9. Stały Komitet Rady Ministrów\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"closure_date\":null,\"passed\":null,\"document\":{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157968/13157969/dokument800294.zip\",\"kind\":\"rcl\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"f80b38830cd42ba5dcec1207547dea96d3a21b7ebd28b1a2dac0a251aea614cb\",\"analysis_revision\":2,\"seen_supplements\":null},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":4,\"category\":\"employment\",\"summary\":\"Проект полностью перестраивает систему регистрации судов и реестра, вводит электронный реестр и сервис на английском. Важное для иностранцев: расширяются правила временного признания дипломов моряков из третьих стран и допуска их к работе на судах под польским флагом до 3 месяцев.\",\"key_changes\":[\"Моряки с документами из третьих стран могут получить признание диплома максимум на 3 месяца\",\"Признание документов стран не из списка ЕС/KE – только если в KE подан запрос о признании этой страны\",\"Моряки с поданным заявлением на признание диплома могут до 3 мес. работать на судах под польской флагом\",\"И то, и другое допускается лишь после проверки подлинности иностранного документа квалификации\",\"За выдачу подтверждения подачи заявления на признание взимается 30 PLN\"],\"affected_groups\":[\"иностранные моряки с дипломами/свидетельствами третьих стран\",\"иностранные члены экипажей, нанимающиеся на суда под польским флагом\",\"иностранные судовладельцы из państw UE/EFTA, регистрирующие суда в польском реестре\"],\"practical_impact\":\"Иностранец‑моряк с дипломом из третьей страны сможет быстрее выйти в рейс на судне под польским флагом: до 3 месяцев на основании временного признания или подтверждения подачи заявления. Нужно пройти проверку подлинности документа и оплатить 30 PLN за подтверждение.\",\"effective_date\":\"Изменения по признанию документов квалификационных (art. 6 pkt 1–3, 5–7, 10) вступают в силу через 14 дней со дня официального опубликования закона.\",\"confidence\":0.86,\"rationale\":\"Проект прямо изменяет правила признания иностранных морских дипломов и допуска иностранных моряков к работе на судах под польским флагом, что существенно для занятости (категория „employment”, важность 4).\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[\"Уточнено, что для документов из стран, не признанных Еврокомиссией, временное признание возможно только после подачи Польшей официального wniosku do KE о признании этой страны (новый ust. 6 art. 67).\",\"Чётко разделены два механизма: краткосрочное признание зарубежного документа (до 3 мес.) и допуск к работе по одному лишь подтверждению подачи заявления (также до 3 мес., ust. 7–8).\",\"В тексте подробно прописано, что и временное признание, и подтверждение подачи заявления выдаются только после позитивной проверки подлинности иностранного документа квалификации.\",\"Сохранена, но теперь явно указана в załączniku фиксированная плата 30 PLN за подтверждение подачи wniosku о признании документа.\"]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-09-v9\",\"input_chars\":288205,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-02T14:56:37Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12402353/13157968/13157969/dokument800294.zip\",\"source_kind\":\"rcl\",\"revision\":2,\"text_sha256\":\"f80b38830cd42ba5dcec1207547dea96d3a21b7ebd28b1a2dac0a251aea614cb\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":\"9905bda2732b2835f7398323ab30026ea480ae68a1f1ab65d544e9a5f1c1d2ab\",\"source_checked_at\":\"2026-10-02T14:56:37Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Трёхмесячный допуск моряков\",\"language\":\"ru\",\"basis\":\"Проект вводит до трёх месяцев временного признания дипломов моряков из третьих стран для работы на судах под польским флагом.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":{\"id\":12402353,\"title\":\"Projekt ustawy o rejestracji statków pod polską banderą\",\"applicant\":\"Minister Infrastruktury\",\"wykaz_number\":\"UDER84\",\"wykaz_url\"