ia, ustawę z dnia 15 lipca 2011 r. o zawodach pielęgniarki i położnej oraz ustawę z dnia 7 października 2020 r. o Funduszu Medycznym. ] )\\nArt. 1\"},{\"kind\":\"draft_date\",\"value\":\"2026-10-14\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12398102/13129966/13129967/dokument803962.zip\",\"text_sha256\":\"f8b3149402ed547503a7465d32b087439decb8c6f1fcb3f7b535e568cabadec9\",\"block_id\":\"part:0\",\"start\":0,\"end\":35,\"quote\":\"Projekt z dnia 14 października 2026\"}],\"limitations\":[\"annex_link_unknown\",\"support_applicability_unknown\",\"missing_evidence\"],\"links\":[{\"kind\":\"supporting\",\"source_part\":1,\"target_part\":0,\"status\":\"unknown\",\"evidence\":[]},{\"kind\":\"supporting\",\"source_part\":2,\"target_part\":0,\"status\":\"unknown\",\"evidence\":[]}],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":151254,\"page_start\":null,\"page_end\":null,\"losses\":[]},{\"part_index\":1,\"stage\":\"extraction\",\"start\":0,\"end\":233140,\"page_start\":null,\"page_end\":null,\"losses\":[]},{\"part_index\":2,\"stage\":\"extraction\",\"start\":0,\"end\":96363,\"page_start\":null,\"page_end\":null,\"losses\":[]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":151254,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"bcf00ae713e589074530354cf2d204251a96e5d9bf021cf1077c1cba9fa0f0ef\"},\"law_sha256\":\"law-v2:c3f62e020dec9c0265543fc2d2db879240161442e856a6f049e047dd9c75e854\",\"source_checked_at\":\"2026-10-26T19:32:49Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Цифровая рефундация лекарств\",\"language\":\"ru\",\"basis\":\"Проект полностью перестраивает правила рефундации лекарств и медизделий и вводит новые ИТ‑системы, влияя на доступ к ним для застрахованных, в том числе иностранцев.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\