INSERT INTO "publications" VALUES(220,10,'1929','message_part','sent','@lex_inform_pl',15,'[]',NULL,'2026-10-27T16:33:10+00:00','2026-10-27T16:33:16+00:00',NULL,0,'card/8/0602438698ce5fbc00d386eddb7855c07c9e59b89626c9a3d03bec6dd332a501-8/1','0602438698ce5fbc00d386eddb7855c07c9e59b89626c9a3d03bec6dd332a501','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"1929\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"projekt dotyczy systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-11-04\",\"document_date\":\"2025-11-04\",\"change_date\":\"2026-10-23T08:51:43Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-188-25\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-188-25\",\"prints_considered_jointly\":[\"316\",\"1933\"],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:uchodzcy\",\"text:obywatelstwo\",\"text:wizy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:ochrona_miedzynarodowa\",\"text:status_uchodzcy\"],\"stages_fingerprint\":\"3a84bc090e4cc025d211a9ae7b0e6892f319a26833aed0237b2fb8f14ead685a\",\"observed_closure_date\":\"2026-10-22\",\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Ассистент независимой жизни\",\"language\":\"ru\",\"basis\":\"Закон создаёт финансируемую государством услугу личной асистенции, позволяющую людям с инвалидностью, включая иностранцев с указанным pobyt, вести более независимую повседневную жизнь.\",\"selected_at\":\"2026-10-17T08:46:39Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":3,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2170.html\",\"title\":\"Ustawa o asystencji osobistej osób z niepełnosprawnościami\",\"print_number\":\"832\",\"received\":\"2026-09-22\",\"committees\":[{\"id\":233,\"name\":\"Komisja Rodziny, Polityki Senioralnej i Społecznej\",\"email\":\"krpss@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-08\",\"2026-10-13\"],\"committee_work_completed\":false,\"review_documents\":[]},\"seen_supplements\":[\"1929-001\",\"1929-002\",\"1929-003\",\"1929-004\",\"1929-005\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-27T16:32:49Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Ассистент независимой жизни · druk nr 1929</b>\n📜 <b>Новый законопроект</b>\n\nO asystencji osobistej osób z niepełnosprawnościami\n<i>Принят Сеймом 18 сент 2026</i>\n\n👥 <b>Кого касается:</b> Иностранцы‑инвалиды с zezwolenie na pobyt stały или pobyt rezydenta długoterminowego UE; Граждане ЕС/ЕЭЗ/Швейцарии и члены их семей с prawem pobytu / stałego pobytu; Иностранцы с pobyt czasowy по ст. 127, 137a, 139a, 139o, 151, 151b, 159 ust.1, 186 ust.1 pkt 3 ustawy o cudzoziemcach; Беженцы и лица с ochroną uzupełniającą в Польше; Британцы и их семьи с правами по Brexit‑соглашению; Иностранцы с kartą pobytu с пометкой „dostęp do rynku pracy” (кроме студентов, сезонных и краткосрочных работников); Иностранные исследователи и стажёры на научных визах и соответствующих zezwoleniach\n\n💡 <b>Что это значит на практике:</b> Иностранец с инвалидностью и одним из перечисленных статусов pobytu сможет подать онлайн‑заявление на личного ассистента и, после решения wojewódzki zespół ds. orzekania, получать ежемесячные часы помощи без оплаты. Нужно иметь miejsce zamieszkania в Польше и приложить документ о праве пребывания; запуск права будет поэтапным в 2028–2030 гг. в зависимости от уровня potrzeby wsparcia.\n\n👉 <b>Что можно сделать сейчас:</b> пока ничего — закон у Президента\n\n🔑 <b>Ключевые изменения</b>\n• Вводится право на бесплатного личного ассистента для людей с инвалидностью 13–65 лет.\n• Иностранцы с указанными разрешениями на pobyt имеют такое же право, как поляки.\n• Ассистент работает по трёхстороннему контракту, ставка 49–55 zł брутто/час.\n• Объём услуги: 20–240 ч/мес (взрослые), 20–80 ч/мес (13–18 лет), часть часов переносится.\n• Заявление подаётся только электронно; иностранец прикладывает документ, дающий право на pobyt.\n\n📅 <b>Вступление в силу:</b> Закон в целом вступает в силу через 14 дней после опубликования, при этом часть норм о системе для przyznawania prawa действует через 12 месяцев, о системе ZUS для obsługi realizacji – через 14 месяцев, а нормы о realizatorach (powiat, NGO, gmina) – с первого дня месяца после 5 месяцев от опубликования.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ✓ → II и III чтение ✓ → Сенат ✓ → Президент ● → Dz.U. → в силе\n⏭ <b>Что дальше:</b> подпись Президента (до 21 дня), затем публикация в Dziennik Ustaw · решение до 17 нояб 2026\n\n🏛 <b>Стадия:</b> Закон передан Президенту (27 окт 2026)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 4 нояб 2025\nРассматривается совместно с druk 316, 1933\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟡 <b>Важность:</b> ●●●○○ 3/5\n🏷 <b>Категория:</b> соцсфера\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=1929\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=1929\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/1929/1929.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-188-25\">Проект на RCL</a>\n\n#kadencja10druk1929 #важность3 #соцсфера #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":8,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-27","still_meets":false,"reply_to":15,"edit_message_id":15,"revision_of":8,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(221,10,'3003','message_part','sent','@lex_inform_pl',13,'[]',NULL,'2026-10-27T16:33:21+00:00','2026-10-27T16:33:26+00:00',NULL,0,'card/6/353d0985129927179f7db4450e51cfeb7ed86e8261b23cf67d679dae83aa63b6-6/1','353d0985129927179f7db4450e51cfeb7ed86e8261b23cf67d679dae83aa63b6','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3003\",\"title\":\"Rządowy projekt ustawy o środkach ograniczających\",\"description\":\"projekt dotyczy określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-08-06\",\"document_date\":\"2026-08-06\",\"change_date\":\"2026-10-23T13:15:21Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":true,\"rcl_num\":\"RM-0610-126-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-126-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obywatelstwo\",\"text:straz_graniczna\",\"text:schengen\",\"text:nieruchomosci_cudzoziemcy\"],\"stages_fingerprint\":\"b76012c755944d2531b7d5dfbb1a123301c2f7b1f5603153fb35eab5d0d18ffd\",\"observed_closure_date\":null,\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Санкционный въездной барьер\",\"language\":\"ru\",\"basis\":\"Иностранец, внесённый в санкционный список МВД, автоматически попадает в wykaz cudzoziemców, których pobyt jest niepożądany, что влечёт запрет въезда и негативные визово‑миграционные решения.\",\"selected_at\":\"2026-10-21T18:29:53Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":\"RCL/12399355\",\"linked_wykaz_number\":\"UC92\",\"act\":null,\"authors\":null,\"senate\":null,\"seen_supplements\":[\"3003-001\",\"3003-002\",\"3003-003\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-07T13:52:14Z\",\"last_checked_at\":\"2026-10-27T16:32:50Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Санкционный въездной барьер · druk nr 3003</b>\n📜 <b>Новый законопроект</b>\n\nO środkach ograniczających\n\n👥 <b>Кого касается:</b> иностранцы, попавшие в санкционный список МВД; иностранцы, которым могут отказать во въезде, визе или ВНЖ из‑за санкций; иностранные работники компаний, попавших под санкции\n\n💡 <b>Что это значит на практике:</b> Если иностранец будет включён в польский санкционный список, его автоматически внесут в реестр нежелательных лиц, что повлечёт запрет въезда и отказы в визе и виде на жительство; обжалование возможно только в административном суде, при этом данные списка будут публичны. Работники санкционированных работодателей (включая иностранцев) смогут требовать выплату задолженной зарплаты из FGŚP.\n\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=ASW\">Komisja Administracji i Spraw Wewnętrznych (ASW)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=ASW\">форма письма</a>), <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=GOR\">Komisja Gospodarki i Rozwoju (GOR)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=GOR\">форма письма</a>), <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=FPB\">Komisja Finansów Publicznych (FPB)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=FPB\">форма письма</a>) до заседания 5 нояб 2026\n\n🔑 <b>Ключевые изменения</b>\n• Единый порядок применения санкций ЕС и польских «środki ograniczające».\n• Новое основание санкций — вмешательство и манипуляция информацией.\n• Внесение в санкционный список МВД ведёт к записи в wykaz cudzoziemców.\n• Запись в wykaz — новое основание отказа во въезде, визе и виде на жительство.\n• За помощь въезду лица под санкциями предусмотрена уголовная ответственность.\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу по истечении 30 дней со дня опубликования, за исключением ст. 73, которая вступает в силу по истечении 6 месяцев со дня опубликования.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ✓ → II и III чтение ● → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> комиссия рассматривает поправки II чтения — Komisja Administracji i Spraw Wewnętrznych (ASW), Komisja Gospodarki i Rozwoju (GOR), Komisja Finansów Publicznych (FPB) (дополнительное sprawozdanie), затем III чтение · 5 нояб 2026, 11:00\n\n🏛 <b>Стадия:</b> II чтение на заседании Сейма (23 окт 2026) · направлен в комиссию Komisja Finansów Publicznych (FPB)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 6 авг 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🔴 <b>Важность:</b> ●●●●● 5/5\n🏷 <b>Категория:</b> легализация пребывания\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3003\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3003\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-126-26\">Проект на RCL</a>\n\n#kadencja10druk3003 #UC92 #важность5 #легализация #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":6,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-27","still_meets":false,"reply_to":13,"edit_message_id":13,"revision_of":6,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(222,10,'3160','message_part','sent','@lex_inform_pl',76,'[]',NULL,'2026-10-27T16:33:32+00:00','2026-10-27T16:33:37+00:00',NULL,0,'card/78/e57fae9bc0661736e4b00c4ea27cb46ec72bc5c72562e00ee42022b3d1a3eb6d-78/1','e57fae9bc0661736e4b00c4ea27cb46ec72bc5c72562e00ee42022b3d1a3eb6d','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3160\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-01\",\"document_date\":\"2026-10-01\",\"change_date\":\"2026-10-23T08:03:34Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-169-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:nieruchomosci_cudzoziemcy\",\"text:praca_sezonowa\"],\"stages_fingerprint\":\"68045e7ffd240c786da70be9db7db542dea0a80db11bfc376dab7c9a7dcc7280\",\"observed_closure_date\":\"2026-10-22\",\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Сделки без 3a\",\"language\":\"ru\",\"basis\":\"Текст проекта прямо предусматривает отмену ст. 3a в законе о nabywaniu nieruchomości przez cudzoziemców, что меняет режим покупки недвижимости иностранцами.\",\"selected_at\":\"2026-10-21T19:11:53Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":{\"name\":\"Сделка без 3a\",\"language\":\"ru\",\"basis\":\"Текст проекта прямо предусматривает отмену статьи 3a в ustawa o nabywaniu nieruchomości przez cudzoziemców, влияя на правила сделок с недвижимостью для иностранцев.\",\"selected_at\":\"2026-10-23T18:21:01Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":5,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2197.html\",\"title\":\"Ustawa o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"print_number\":\"892\",\"received\":\"2026-10-23\",\"committees\":[{\"id\":218,\"name\":\"Komisja Budżetu i Finansów Publicznych\",\"email\":\"kbfp@senat.gov.pl\"},{\"id\":219,\"name\":\"Komisja Gospodarki Narodowej i Innowacyjności\",\"email\":\"kgni@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-26\"],\"committee_work_completed\":true,\"review_documents\":[{\"url\":\"https://www.senat.gov.pl/download/gfx/senat/pl/senatdruki/14798/druk/892a.pdf\",\"title\":\"Druk nr 892 A\",\"body\":\"126. pos. Komisji Budżetu i Finansów Publicznych oraz 96. pos. Komisji Gospodarki Narodowej i Innowacyjności\",\"role\":\"commission_report\",\"date\":\"2026-10-26\"}]},\"seen_supplements\":[\"3160-001\",\"3160-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T18:56:08Z\",\"last_checked_at\":\"2026-10-27T16:32:58Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Сделки без 3a · druk nr 3160</b>\n📜 <b>Новый законопроект</b>\n\nO wspieraniu nowych inwestycji oraz niektórych innych ustaw\n<i>Принят Сеймом 22 окт 2026</i>\n\n👥 <b>Кого касается:</b> иностранцы, покупающие недвижимость в Польше; иностранные инвесторы, пользующиеся поддержкой PSI; иностранные владельцы и со‑владельцы польских компаний в PSI\n\n💡 <b>Что это значит на практике:</b> Покупка недвижимости иностранцами будет регулироваться без ст. 3a, что приведёт к изменению части требований или процедуры сделок. Иностранные инвесторы в PSI столкнутся с новыми правилами расчёта налоговой льготы и обязательной электронной подачей всех документов.\n\n👉 <b>Что можно сделать сейчас:</b> пока ничего — комиссии Сената уже рассмотрели закон, дальше голосование Сената\n\n🔑 <b>Ключевые изменения</b>\n• Отменяется ст. 3a в законе о покупке недвижимости иностранцами.\n• Налоговая льгота PSI чётко привязана к указанной в решении деятельности и территории.\n• Освобождение от налога по PSI начинается после окончания инвестпроекта или начала затрат на новые рабочие места.\n• Заявления, жалобы и переписка по PSI подаются только через электронное индивидуальное konto.\n• Крупные решения о поддержке (от 40 млн zł помощи) требуют мнения Шефа KAS.\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу 1 января 2027 г., при этом ст. 2 (отмена ст. 3a) начинает действовать с 31 декабря 2027 г.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ✓ → II и III чтение ✓ → Сенат ● → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> рассмотрение в Сенате (до 30 дней) · решение до 22 нояб 2026\n\n🏛 <b>Стадия:</b> III чтение на заседании Сейма (22 окт 2026) · голосование в Сейме\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 1 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟢 <b>Важность:</b> ●●○○○ 2/5\n🏷 <b>Категория:</b> косвенное влияние\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3160\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3160\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\">Проект на RCL</a>\n\n#kadencja10druk3160 #важность2 #косвенно #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":78,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-27","still_meets":false,"reply_to":76,"edit_message_id":76,"revision_of":78,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(223,10,'3157','status_update','sent','@lex_inform_pl',143,'[]',185,'2026-10-27T17:33:36+00:00','2026-10-27T17:33:42+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3157\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy uporządkowania zasad zatrudniania i wynagradzania personelu medycznego przez m.in.: wprowadzenie maksymalnych stawek godzinowych i miesięcznych wynagrodzeń za świadczenia finansowane przez NFZ, ograniczenie możliwości zawierania umów za pośrednictwem spółek czy spółdzielni lekarskich,\\nzakaz uzależniania wynagrodzenia pracownika medycznego od wysokości kontraktu placówki z NFZ. Projekt przewiduje też wzmocnienie kontroli NFZ oraz większe kompetencje Agencji Ochrony Technologii Medycznych i Taryfikacji.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-28\",\"document_date\":\"2026-09-28\",\"change_date\":\"2026-10-23T08:06:30Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-160-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-160-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:migracja\",\"text:obywatelstwo\",\"text:przekraczanie_granicy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-28\",\"print_number\":\"3157\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"st