2,\"number\":11,\"name\":\"Potwierdzenie projektu przez Stały Komitet Rady Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13234367,\"number\":12,\"name\":\"Rada Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13234373,\"number\":13,\"name\":\"Notyfikacja\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13234374,\"number\":14,\"name\":\"Skierowanie projektu ustawy do Sejmu\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false}],\"consultation\":{\"letter_url\":\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234325/13234327/dokument804260.pdf\",\"letter_date\":\"2026-10-27\",\"days\":30,\"deadline\":\"2026-11-26\",\"email\":null,\"positions\":0,\"response_published\":false,\"letters_read\":[\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234325/13234327/dokument804260.pdf\",\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234325/13234327/dokument804261.docx\"],\"letter_parser\":2},\"consultation_attempts\":1},\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-27T18:45:57Z\",\"last_checked_at\":\"2026-10-27T18:45:57Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранцы, в отношении которых ведётся уголовное производство в Польше","иностранцы, подающие заявки на разные виды разрешений на пребывание","иностранцы, находящиеся в тюрьме, СИЗО или под электронным арестом"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-27T19:14:11Z","assessed_at":"2026-10-27T19:14:11Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Электронный арест и ВНЖ · UD256</b>\n📜 <b>Правительственный проект (RCL)</b>\n\nKodeks postępowania karnego oraz niektórych innych ustaw\n\n👥 <b>Кого касается:</b> иностранцы, в отношении которых ведётся уголовное производство в Польше; иностранцы, подающие заявки на разные виды разрешений на пребывание; иностранцы, находящиеся в тюрьме, СИЗО или под электронным арестом\n\n💡 <b>Что это значит на практике:</b> Для иностранцев, подозреваемых в преступлении, может применяться домашний арест с браслетом вместо СИЗО, но для миграционных органов он считается тем же лишением свободы. Такой статус может повлиять на получение или продление разрешения на проживание и фиксируется в обмене данными между ведомствами.\n\n🗣 <b>Общественные консультации:</b> до 26 нояб 2026 (30 дн. с даты письма) · <a href=\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234325/13234327/dokument804260.pdf\">письмо о консультациях</a>\n\n👉 <b>Что можно сделать сейчас:</b> <a href=\"https://legislacja.rcl.gov.pl/projekt/12416153/komentarz\">оставить комментарий через форму на RCL</a>; можно заявить интерес к работам над проектом (zgłoszenie zainteresowania) — письмом органу, который готовит проект: Minister Sprawiedliwości · <a href=\"https://www.gov.pl/web/sprawiedliwosc/kontakt\">адреса канцелярии, ePUAP и e-Doręczenia</a>\n\n🔑 <b>Ключевые изменения</b>\n• Появляется новый мер пресечения: электронный арест с браслетом вместо СИЗО.\n• Во всех нормах о cudzoziemcach электронный арест приравнен к тюрьме и СИЗО.\n• При электронном аресте органы сообщают об этом в делах по легализации пребывания.\n• Электронный арест учитывается как негативный фактор при ряде решений по проживанию.\n• За явно незаконный электронный арест можно требовать компенсацию как за СИЗО.\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу по истечении 6 месяцев со дня его официального опубликования.\n\n🗺 <b>Путь:</b> план ✓ → RCL ● → Сейм → комиссии → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> общественные консультации до 26 нояб 2026, затем сбор мнений (opiniowanie), комитеты Совета министров, Rada Ministrów и внесение в Сейм\n\n🏛 <b>Стадия:</b> сбор мнений министерств и партнёров (4. Opiniowanie) (27 окт 2026)\n✍️ <b>Инициатор:</b> правительственный — Minister Sprawiedliwości · номер в wykazie prac RM: UD256\n📄 <b>Опубликован на RCL:</b> 27 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🔴 <b>Важность:</b> ●●●●● 5/5\n🏷 <b>Категория:</b> легализация пребывания\n\n🔗 <a href=\"https://legislacja.rcl.gov.pl/projekt/12416153\">Проект на RCL</a> | <a href=\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804262.docx\">Текст проекта (DOCX)</a> | <a href=\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804263.docx\">Uzasadnienie</a> | <a href=\"https://legislacja.rcl.gov.pl/docs//2/12416153/13234331/13234332/dokument804264.docx\">OSR</a> | <a href=\"https://www.gov.pl/web/premier/wplip-rm\">Wykaz prac RM</a>\n\n#UD256 #важность5 #легализация #консультации #RCL","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-27","still_meets":false,"reply_to":null,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранцы, в отношении которых ведётся уголовное производство в Польше","иностранцы, подающие заявки на разные виды разрешений на пребывание","иностранцы, находящиеся в тюрьме, СИЗО или под электронным арестом"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-27T19:14:11Z","assessed_at":"2026-10-27T19:14:11Z","novelty":"unknown","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(226,10,'WPL/UD492','new_bill','sent','@lex_inform_pl',145,'[]',NULL,'2026-10-27T19:14:22+00:00','2026-10-27T19:14:27+00:00',NULL,0,NULL,'71a786eb0b4c20ed8a0eaae911bfc38f6c8a6aa0aba94a6464a677328c1b3cc7','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"WPL/UD492\",\"title\":\"Projekt ustawy o minimalnym wieku dostępu do internetowych serwisów społecznościowych\",\"description\":\"Usługi społeczeństwa informacyjnego, a w szczególności internetowe serwisy społecznościowe, stały się istotnym elementem codziennego życia dzieci i młodzieży. Mogą one sprzyjać rozwojowi osobowości, edukacji, aktywności obywatelskiej, nawiązywaniu relacji, komunikacji oraz kreatywności, jednak niosą również zagrożenie dla prywatności, bezpieczeństwa i ochrony małoletnich.\\nJak wynika z przedstawionego przez Komisję Europejską w dniu 17 września 2026 r. wniosku legislacyjnego EU Kids Act, jedynie połowa dzieci w wieku 9–16 lat w Europie deklaruje, że czuje się bezpiecznie w internecie. Zagrożenia, na jakie są narażeni małoletni w sieci, są realne i wymagają pilnej reakcji – wpływają bowiem na ich zdrowie, rozwój i dobrostan. Wśród skutków wymienia się między innymi spadek aktywności fizycznej, zwiększone ryzyko krótkowzroczności i zaburzeń snu, objawy depresyjne i lękowe, obniżone poczucie własnej wartości, negatywny wpływ na procesy uczenia się i rozwój poznawczy, zaburzenia odżywiania, osłabienie empatii, poczucie samotności oraz zachowania o charakterze uzależniającym. Nieletni są narażeni ponadto na cyberprzemoc, hejt, dezinformację i manipulację, a także na niegodziwe traktowanie w celach seksualnych i nagabywanie seksualne (grooming), co może prowadzić do poważnych konsekwencji emocjonalnych i społecznych.\\nDzieci w okresie wczesnej i środkowej adolescencji (czyli między 11. a 15. rokiem życia), jak wskazuje Fundacja Dajemy Dzieciom Siłę, dopiero kształtują swoją tożsamość, a obecność w mediach społecznościowych może zakłócać ten proces. Obserwowanie wyidealizowanych obrazów innych osób może utrudniać budowanie realistycznego obrazu siebie [1].\\nChoć większość platform ustala w regulaminach minimalny wiek korzystania z usługi na poziomie 13 lat, w praktyce korzystają z nich także młodsze dzieci. Raport Internet dzieci [2] pokazuje, że z aplikacji formalnie przeznaczonych dla osób w wieku 13 lat i więcej korzystają również użytkownicy w wieku 7–12 lat.\\nCelem projektu ustawy o minimalnym wieku dostępu do internetowych serwisów społecznościowych, zwanego dalej „projektem”, jest ustanowienie minimalnego wieku dostępu do internetowych serwisów społecznościowych na poziomie 15 lat oraz wskazanie możliwych sposobów jego weryfikacji.\\nPodstawa programowa wychowania przedszkolnego oraz podstawa programowa kształcenia ogólnego stanowią fundament do budowania i rozwijania wiedzy dzieci i młodzieży na temat środowiska cyfrowego. Projekt będzie przesądzał, że treści dotyczące rozwijania wiedzy i umiejętności dzieci i uczniów służących bezpieczeństwu cyfrowemu, z uwzględnieniem dostosowanych do wieku dziecka lub ucznia zagadnień takich jak: ochrona urządzeń elektronicznych i treści cyfrowych, świadomość i rozumienie ryzyka w sieci, identyfikowanie zagrożeń w środowisku cyfrowym i środków bezpieczeństwa, ochrona prywatnych danych i prywatności, ochrona zdrowia i dbania o samopoczucie (higiena cyfrowa), reagowanie na cyberprzemoc i przejawy radykalizacji w przestrzeni cyfrowej oraz wpływ technologii i jej stosowania na środowisko, są uwzględniane w ww. podstawach programowych. Minister właściwy do spraw oświaty i wychowania będzie także realizował działania informacyjne i promocyjne, wspierające uczniów i nauczycieli oraz rodziców uczniów w przyswajaniu i praktycznym wykorzystywaniu wiedzy z zakresu bezpiecznego korzystania przez młodych ludzi z nowoczesnych technologii.\\nWspółczesne dzieciństwo i dorastanie przebiegają w środowisku silnie zdominowanym przez nowoczesne technologie. Smartfony, media społecznościowe i stały dostęp do internetu nie tylko zmieniły sposoby uczenia się i budowania relacji, lecz także wprowadziły nowe formy zagrożeń psychospołecznych, takich jak cyberprzemoc i przejawy radykalizacji w przestrzeni cyfrowej, naruszenia prywatności i danych osobowych, kontakt z niepożądanymi treściami, dezinformacja czy uzależnienie od internetu.\\nJak wynika z raportu z pierwszego Ogólnopolskiego Badania Higieny Cyfrowej i Aktywności Fizycznej Młodzieży (Instytut Cyfrowego Obywatelstwa, 2026) 61 % nastolatków uważa, że spędza przed ekranami zbyt dużo czasu, 62,7 % nastolatków słyszało o higienie cyfrowej, a głównym źródłem wiedzy jest szkoła.\\nZ kolei wyniki badania PISA 2025 wskazują, że na tle rówieśników z innych krajów, polskich piętnastolatków szczególnie wyróżnia duża częstotliwość codziennego wykorzystania urządzeń cyfrowych do spędzania czasu wolnego w szkole. Tylko 16 % polskich uczniów wskazało, że „wcale” nie korzysta z nich w tym celu, co stanowiło jeden z najniższych odsetków wśród krajów uczestniczących w badaniu (UE – 34 %, OECD – 36 %).\\nJednocześnie uczniowie wskazywali, że rozpraszają się korzystając z urządzeń cyfrowych w czasie lekcji (Polska – 74 %, UE – 59 %, OECD – 61 %). Na potrzebę bycia online i odpowiadania na wiadomości w czasie lekcji wskazywało aż 62 % polskich piętnastolatków (UE 49 %, OECD 44 %). Dziewczęta częściej niż chłopcy zgłaszały niepokój z powodu braku telefonu oraz potrzebę bycia online.\\nEdukacja cyfrowa musi więc zapewniać nabycie podstawowej wiedzy i umiejętności z zakresu odpowiedzialnego wykorzystywania zasobów cyfrowych i cyfrowego bezpieczeństwa, także ze względu na szeroki dostęp obywateli, w tym dzieci i młodzieży, do przestrzeni cyfrowej oraz wzrost zagrożenia cyberprzestępstwami. Zagrożenia w internecie są coraz bardziej powszechne, a dezinformacja została uznana za jeden z najbardziej destabilizujących czynników dla społeczeństw europejskich. Wskazane jest, aby edukacja w zakresie bezpieczeństwa cyfrowego była dostępna na jak najwcześniejszym etapie dostępu dzieci i młodzieży do przestrzeni cyfrowej. Według raportu „Nastolatki” (NASK-PIB, 2025) 28 %, czyli więcej niż co czwarty nastolatek, miał styczność z co najmniej jedną formą przemocy w przestrzeni cyfrowej motywowaną cechami osobistymi, tożsamością lub przekonaniami.\\nW świetle ostatnich wydarzeń związanych z aktami przemocy fizycznej w szkołach, poważnym zagrożeniem jest zjawisko radykalizacj\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-27\",\"document_date\":\"2026-10-27\",\"change_date\":\"2026-10-27T14:51:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"obywatelstwo\"],\"stages\":[],\"stages_fingerprint\":\"89d648b5baa88fd89f20af3cb7b0ab6804c579d09cb3bc7fa9fa267b1717dd7c\",\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект вводит минимальный возраст 15 лет для доступа к интернет‑соцсетям и общие правила проверки возраста. Планируется также усилить цифровое воспитание и обучение безопасности в сети в школах.\",\"key_changes\":[\"Минимальный возраст доступа к соцсетям будет установлен на 15 лет\",\"Провайдеры соцсетей должны будут проверять возраст пользователей\",\"Будут указаны допустимые способы онлайн‑верификации возраста\",\"В школьные программы включат больше тем цифровой и сетевой безопасности\",\"Министр образования проведёт информкампании о безопасном интернете\"],\"affected_groups\":[\"иностранные дети и подростки, живущие в Польше\",\"родители иностранных детей школьного возраста\",\"иностранные пользователи соцсетей, на которых распространяется польское право\",\"иностранные учителя и кадры в польских школах\"],\"practical_impact\":\"Подростки младше 15 лет, независимо от гражданства, могут столкнуться с блокировкой или ограничением аккаунтов в соцсетях. Школы усилят обучение цифровой безопасности, а родителям придётся учитывать новые возрастные ограничения и возможные проверки возраста детей онлайн.\",\"effective_date\":null,\"confidence\":0.55,\"rationale\":\"Projekt wprowadza ogólny limit wieku i edukację cyfrową dla wszystkich małoletnich w Polsce, co istotnie wpływa także na dzieci cudzoziemców w sferze życia społecznego i szkolnego.\",\"mnemonic_candidate\":\"Сетевой возрастной барьер\",\"mnemonic_fallback\":\"Минимальный возраст соцсетей\",\"mnemonic_basis\":\"Проект прямо заявляет о ustanowieniu minimalnego wieku dostępu do internetowych serwisów społecznościowych na poziomie 15 lat.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v12\",\"input_chars\":0,\"truncated\":false,\"text_source\":\"metadata_only\",\"created_at\":\"2026-10-27T19:14:06Z\",\"computation_id\":\"result-v1:918484969efdcf4dda2372d88b94162ccbca666a97d2cabf0be0f38f7585ab3f\",\"request_sha256\":\"d67f038f04c3f9c485b6c5d32d7e66ea34adf20fa051c13ca97118e200a4dea9\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":null,\"source_kind\":\"metadata\",\"revision\":1,\"text_sha256\":null,\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[],\"observed_parts\":[],\"rejected\":[],\"facts\":[],\"limitations\":[],\"links\":[],\"coverage\":[],\"normative_sha256\":\"\"},\"law_sha256\":null,\"source_checked_at\":\"2026-10-27T19:14:06Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Сетевой возрастной барьер\",\"language\":\"ru\",\"basis\":\"Проект прямо заявляет о ustanowieniu minimalnego wieku dostępu do internetowych serwisów społecznościowych na poziomie 15 lat.\",\"selected_at\":\"2026-10-27T19:14:06Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":true,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":{\"number\":\"UD492\",\"title\":\"Projekt ustawy o minimalnym wieku dostępu do internetowych serwisów społecznościowych\",\"kind\":\"Projekty ustaw\",\"doc_type\":\"D – pozostałe projekty\",\"goals\":\"Usługi społeczeństwa informacyjnego, a w szczególności internetowe serwisy społecznościowe, stały się istotnym elementem codziennego życia dzieci i młodzieży. Mogą one sprzyjać rozwojowi osobowości, edukacji, aktywności obywatelskiej, nawiązywaniu relacji, komunikacji oraz kreatywności, jednak niosą również zagrożenie dla prywatności, bezpieczeństwa i ochrony małoletnich.\\nJak wynika z przedstawionego przez Komisję Europejską w dniu 17 września 2026 r. wniosku legislacyjnego EU Kids Act, jedynie połowa dzieci w wieku 9–16 lat w Europie deklaruje, że czuje się bezpiecznie w internecie. Zagrożenia, na jakie są narażeni małoletni w sieci, są realne i wymagają pilnej reakcji – wpływają bowiem na ich zdrowie, rozwój i dobrostan. Wśród skutków wymienia się między innymi spadek aktywności fizycznej, zwiększone ryzyko krótkowzroczności i zaburzeń snu, objawy depresyjne i lękowe, obniżone poczucie własnej wartości, negatywny wpływ na procesy uczenia się i rozwój poznawczy, zaburzenia odżywiania, osłabienie empatii, poczucie samotności oraz zachowania o charakterze uzależniającym. Nieletni są narażeni ponadto na cyberprzemoc, hejt, dezinformację i manipulację, a także na niegodziwe traktowanie w celach seksualnych i nagabywanie seksualne (grooming), co może prowadzić do poważnych konsekwencji emocjonalnych i społecznych.\\nDzieci w okresie wczesnej i środkowej adolescencji (czyli między 11. a 15. rokiem życia), jak wskazuje Fundacja Dajemy Dzieciom Siłę, dopiero kształtują swoją tożsamość, a obecność w mediach społecznościowych może zakłócać ten proces. Obserwowanie wyidealizowanych obrazów innych osób może utrudniać budowanie realistycznego obrazu siebie [1].\\nChoć większość platform ustala w regulaminach minimalny wiek korzystania z usługi na poziomie 13 lat, w praktyce korzystają z nich także młodsze dzieci. Raport Internet dzieci [2] pokazuje, że z aplikacji formalnie przeznaczonych dla osób w wieku 13 lat i więcej korzystają również użytkownicy w wieku 7–12 lat.\\nCelem projektu ustawy o minimalnym wieku dostępu do internetowych serwisów społecznościowych, zwanego dalej „projektem”, jest ustanowienie minimalnego wieku dostępu do internetowych serwisów społecznościowych na poziomie 15 lat oraz wskazanie możliwych sposobów jego weryfikacji.\\nPodstawa programowa wychowania przedszkolnego oraz podstawa programowa kształcenia ogólnego stanowią fundament do budowania i rozwijania wiedzy dzieci i młodzieży na temat środowiska cyfrowego. Projekt będzie przesądzał, że treści dotyczące rozwijania wiedzy i umiejętności dzieci i uczniów służących bezpieczeństwu cyfrowemu, z uwzględnieniem dostosowanych do wieku dziecka lub ucznia zagadnień takich jak: ochrona urządzeń elektronicznych i treści cyfrowych, świadomość i rozumienie ryzyka w sieci, identyfikowanie zagrożeń w środowisku cyfrowym i środków bezpieczeństwa, ochrona prywatnych danych i prywatności, ochrona zdrowia i dbania o samopoczucie (higiena cyfrowa), reagowanie na cyberprzemoc i przejawy radykalizacji w przestrzeni cyfrowej oraz wpływ technologii i jej stosowania na środowisko, są uwzględniane w ww. podstawach programowych. Minister właściwy do spraw oświaty i wychowania będzie także realizował działania informacyjne i promocyjne, wspierające uczniów i nauczycieli oraz rodziców uczniów w przyswajaniu i praktycznym wykorzystywaniu wiedzy z zakresu bezpiecznego korzystania przez młodych ludzi z nowoczesnych technologii.\\nWspółczesne dzieciństwo i dorastanie przebiegają w środowisku silnie zdominowanym przez nowoczesne technologie. Smartfony, media społecznościowe i stały dostęp do internetu nie tylko zmieniły sposoby uczenia się i budowania relacji, lecz także wprowadziły nowe formy zagrożeń psychospołecznych, takich jak cyberprzemoc i przejawy radykalizacji w przestrzeni cyfrowej, naruszenia prywatności i danych osobowych, kontakt z niepożądanymi treściami, dezinformacja czy uzależnienie od internetu.\\nJak wynika z raportu z pierwszego Ogólnopolskiego Badania Higieny Cyfrowej i Aktywności Fizycznej Młodzieży (Instytut Cyfrowego Obywatelstwa, 2026) 61 % nastolatków uważa, że spędza przed ekranami zbyt dużo czasu, 62,7 % nastolatków słyszało o higienie cyfrowej, a głównym źródłem wiedzy jest szkoła.\\nZ kolei wyniki badania PISA 2025 wskazują, że na tle rówieśników z innych krajów, polskich piętnastolatków szczególnie wyróżnia duża częstotliwość codziennego wykorzystania urządzeń cyfrowych do spędzania czasu wolnego w szkole. Tylko 16 % polskich uczniów wskazało, że „wcale” nie korzysta z nich w tym celu, co stanowiło jeden z najniższych odsetków wśród krajów uczestniczących w badaniu (UE – 34 %, OECD – 36 %).\\nJednocześnie uczniowie wskazywali, że rozpraszają się korzystając z urządzeń cyfrowych w czasie lekcji (Polska – 74 %, UE – 59 %, OECD – 61 %). Na potrzebę bycia online i odpowiadania na wiadomości w czasie lekcji wskazywało aż 62 % polskich piętnastolatków (UE 49 %, OECD 44 %). Dziewczęta częściej niż chłopcy zgłaszały niepokój z powodu braku telefonu oraz potrzebę bycia online.\\nEdukacja cyfrowa musi więc zapewniać nabycie podstawowej wiedzy i umiejętności z zakresu odpowiedzialnego wykorzystywania zasobów cyfrowych i cyfrowego bezpieczeństwa, także ze względu na szeroki dostęp obywateli, w tym dzieci i młodzieży, do przestrzeni cyfrowej oraz wzrost zagrożenia cyberprzestępstwami. Zagrożenia w internecie są coraz bardziej powszechne, a dezinformacja została uznana za jeden z najbardziej destabilizujących czynników dla społeczeństw europejskich. Wskazane jest, aby edukacja w zakresie bezpieczeństwa cyfrowego była dostępna na jak najwcześniejszym etapie dostępu dzieci i młodzieży do przestrzeni cyfrowej. Według raportu „Nastolatki” (NASK-PIB, 2025) 28 %, czyli więcej niż co czwarty nastolatek, miał styczność z co najmniej jedną formą przemocy w przestrzeni cyfrowej motywowaną cechami osobistymi, tożsamością lub przekonaniami.\\nW świetle ostatnich wydarzeń związanych z aktami przemocy fizycznej w szkołach, poważnym zagrożeniem jest zjawisko radykalizacji, której przejawy są widoczne także w przestrzeni cyfrowej. Ma ono realne skutki w prawdziwym życiu, dlatego tak ważne jest, aby dzieci i młodzież potrafili zauważyć pierwsze symptomy niepokojących zachowań i wiedzieli, jak na nie zareagować.\\nNie bez znaczenia pozostaje wpływ korzystania z Internetu na zdrowie psychiczne dzieci i młodzieży. Uzależnienie od mediów społecznościowych czy gier komputerowych jest zjawiskiem powszechnym. Raport „Nastolatki” (NASK-PIB, 2025) wskazuje, że współcześni nastolatkowie spędzają w Internecie średnio 4 godziny i 59 minut w dni powszednie. Średni czas korzystania z mediów społecznościowych wynosi 3 godziny i 49 minut wśród dziewcząt i 2 godziny 59 minut wśród chłopców. Warto zwrócić uwagę na różnicę w wykorzystywaniu Internetu ze względu na płeć. Dziewczęta częściej niż chłopcy korzystają z platform społecznościowych w celach związanych z socjalizacją, zarówno do kontaktów, jak i do wyrażania ekspresji. Chłopcy natomiast wybierają rozrywkę w postaci gier i konsumpcję treści, co może wiązać się z użytkowaniem serwisów związanych w dużym stopniu ze światem gier komputerowych (Discord i Twitch) oraz oglądaniem filmów poświęconych różnym obszarom tematycznym w serwisie YouTube.\\nCelem edukacji szkolnej w zakresie szeroko pojętego bezpieczeństwa cyfrowego jest więc przygotowanie najmłodszych do dokonywania świadomych i odpowiedzialnych wyborów w trakcie korzystania z zasobów dostępnych w internecie, krytycznej analizy informacji, bezpiecznego poruszania się w przestrzeni cyfrowej, w tym nawiązywania i utrzymywania opartych na wzajemnym szacunku relacji z innymi użytkownikami sieci. \\nZadania szkoły oraz obowiązkowe cele kształcenia i treści nauczania dotyczące bezpieczeństwa, w tym priorytety wychowawcze, określa podstawa programowa kształcenia ogólnego.\\nTakże Polityka Cyfrowej Transformacji Edukacji (PCTE), przyjęta uchwałą nr 98 Rady Ministrów z dnia 12 września 2024 r. w sprawie przyjęcia polityki publicznej pod nazwą „Polityka Cyfrowej Transformacji Edukacji” (M.P. poz. 812), wskazuje na niezbędne działania, które powinny zostać podjęte dla pełnego urzeczywistnienia wizji nakreślonej w podstawie programowej kształcenia ogólnego, w dokumentach unijnych i innych dokumentach, w celu przygotowania kolejnych pokoleń obywateli do wyzwań społeczeństwa cyfrowego związanych z rozwojem informatyki i technologii cyfrowej. PCTE ma charakter programu i dokumentu strategicznego, wyznaczającego ramy polityki państwa i działań podejmowanych w obszarze cyfryzacji edukacji w perspektywie krótko, średnio oraz długoterminowej. Opisuje działania niezbędne do przeprowadzenia cyfrowej transformacji edukacji w obliczu rewolucji cyfrowej i wskazuje, że realizacją tych działań powinny zająć się przedszkola, szkoły, uczelnie i instytucje edukacyjne oraz administracja systemu oświaty w ramach cyfrowej transformacji edukacji, jako podstawowych działań cyfrowej transformacji społeczeństwa.\\nStąd potrzeba określenia na poziomie ustawy obowiązku zawarcia w podstawie programowej wychowania przedszkolnego i podstawie programowej kształcenia ogólnego treści nauczania, które obejmują zagadnienia, takie jak: higiena cyfrowa, wpływ nadużywania urządzeń ekranowych na zdrowie psychiczne i fizyczne, uzależnienia od mediów społecznościowych i gier komputerowych, zagrożenia wynikające z korzystania z Internetu, w tym cyberprzemocy i radykalizacji, ochrona prywatności i bezpieczeństwo w cyfrowym świecie, dostosowanych do wieku uczniów. Skuteczne dotarcie z przekazem do wszystkich grup docelowych umożliwi ministrowi właściwemu do spraw oświaty i wychowania realizacja działań informacyjnych i promocyjnych w powyższym zakresie, a także zlecanie tych zadań jednostkom organizacyjnym podległym temu ministrowi lub przez niego nadzorowanym oraz innym podmiotom w formie konkursów.\\n………………….\\n[1] https://domowezasadyekranowe.fdds.pl/zasady/do-15-roku-zycia-bez-mediow-spolecznosciowych/\\n[2] https://higienacyfrowa.pl/publikacje/internet-dzieci/\",\"essence\":\"Projekt zakłada, że dostęp do internetowych serwisów społecznościowych (zgodnie z definicją przyjętą w art. 2 pkt 7 rozporządzenia Parlamentu Europejskiego i Rady (UE) 2022/1925 z dna 14 września 2022 r. w sprawie kontestowalnych i uczciwych rynków w sektorze cyfrowym oraz zmiany dyrektyw (UE) 2019/1937 i (UE) 2020/1828 (akt o rynkach cyfrowych), będzie możliwy po ukończeniu 15 roku życia.\\nInternetowy serwis społecznościowy to platforma, która umożliwia użytkownikom łączenie się i komunikowanie ze sobą oraz udostępnianie i szukanie treści na różnych urządzeniach. W potocznym rozumieniu mówimy w tym przypadku o mediach społecznościowych. Serwisy te posiadają różne funkcje, takie jak czaty, posty, filmy wideo czy rekomendacje. Przykłady takich serwisów to m.in. TikTok, Facebook, Instagram. Internetowy serwis społecznościowy to specyficzny rodzaj platformy online, na której użytkownicy budują relacje społeczne, nawiązują kontakty i dzielą się treściami. W założeniu służyć ma do wymiany informacji o wspólnych zainteresowaniach, kwestiach zawodowych, aktywnościach czy prywatnym życiu. Serwisy te różnią się pod względem formatu i liczby oferowanych funkcji, w tym narzędzi komunikacji i rodzajów udostępnianych treści. Typowymi funkcjami takich platform są możliwość publikacji zdjęć, filmów oraz udostępnianie treści (wpisów, postów). Serwisy społecznościowe umożliwiają użytkownikom tworzenie własnych profili oraz budowanie sieci kontaktów [3].\\nProjekt określi, że weryfikacja wieku przez internetowe serwisy społecznościowe będzie mogła następować za pomocą:\\n1) elektronicznego poświadczenia atrybutów potwierdzającego osiągnięcie ustawowego progu wieku, udostępnianego w ramach europejskiego portfela tożsamości cyfrowej, o którym mowa w rozporządzeniu Parlamentu Europejskiego i Rady (UE) nr 910/2014 z dnia 23 lipca 2014 r. w sprawie identyfikacji elektronicznej i usług zaufania w odniesieniu do transakcji elektronicznych na rynku wewnętrznym oraz uchylającym dyrektywę 1999/93/WE, zwanym dalej „rozporządzeniem eIDAS”;\\n2) usługi w aplikacji mObywatel, która będzie oparta o mechanizm selektywnego przekazywania informacji tylko o osiągnięciu określonego progu wiekowego;\\n3) zaufanego rozwiązania, spełniającego wymogi rozporządzenia eIDAS, wpisanego na listę zaufanych rozwiązań w zakresie weryfikacji wieku, prowadzoną przez ministra właściwego do spraw informatyzacji, pozwalającego na selektywne przekazywanie informacji tylko o osiągnięciu określonego progu wiekowego.\\nKażde z tych rozwiązań będzie oparte o zasadę selektywnego przekazywania informacji użytkownika. W konsekwencji będzie on potwierdzać tylko fakt przekroczenia określonego progu wiekowego bez dodatkowego przekazywania innych informacji, takich jak np. imię i nazwisko. Rozwiązania te zapewnią tym samym prywatność użytkownikom, równocześnie realizując podstawowy cel projektu, czyli ograniczenie dostępu do mediów społecznościowych osobom poniżej ustawowego progu wieku.\\nLista zaufanych rozwiązań obejmie podmioty krajowe oraz z Unii Europejskiej, które spełniają wymagania rozporządzenia eIDAS. Zarówno usługa w aplikacji mObywatel, jak i lista zaufanych rozwiązań będą miały szerokie zastosowanie, które nie będzie ograniczać się tylko do weryfikacji wieku w internetowych serwisach społecznościowych.\\nOrganem odpowiedzialnym za nadzór nad przestrzeganiem przepisów projektowanej ustawy będzie Prezes Urzędu Komunikacji Elektronicznej.\\nW projekcie proponuje się przepis wzmacniający obecność w podstawie programowej wychowania przedszkolnego i podstawie programowej kształcenia ogólnego treści nauczania z zakresu: higieny cyfrowej, wpływu nadużywania urządzeń ekranowych na zdrowie psychiczne i fizyczne, uzależnienia od mediów społecznościowych i gier komputerowych, zagrożeń wynikających z korzystania z Internetu, w tym cyberprzemocy i radykalizacji, ochrony prywatności i bezpieczeństwa w cyfrowym świecie, dostosowanych do wieku uczniów. Zapewni to realizację w przedszkolach i szkołach zagadnień, które są kluczowe z punktu widzenia cyfrowego rozwoju społeczeństwa. \\nKorzystanie z nowych technologii przez uczniów jest powszechne, a brak odpowiedniej edukacji może nieść za sobą poważne konsekwencje w takich obszarach jak:\\n1. Ochrona zdrowia psychicznego i fizycznego (Higiena cyfrowa)\\n- Zapobieganie przebodźcowaniu i uzależnieniom: Szkoła ucząca higieny cyfrowej pomaga uczniom zrozumieć mechanizmy uzależniające (np. algorytmy social mediów) i uczy, jak świadomie kontrolować czas spędzany przed ekranem.\\n- Zdrowy rozwój i sen: Edukacja w tym zakresie zwraca uwagę na negatywny wpływ niebieskiego światła na jakość snu oraz na konieczność zachowania równowagi między światem online a aktywnością fizyczną i relacjami w świecie realnym.\\n2. Bezpieczeństwo osobiste i przeciwdziałanie zagrożeniom\\n- Rozpoznawanie niebezpieczeństw: Młodzi ludzie często nie są świadomi ryzyk, takich jak: cyberprzemoc (hejting, nękanie), zjawiska radykalizacji przejawiającego się także w przestrzeni cyfrowej, grooming (manipulacja przez dorosłych w sieci) czy kontakt z patotreściami.\\n- Budowanie odporności na manipulację: Znajomość zagrożeń pozwala uczniom szybciej reagować na próby oszustwa, wyłudzenia czy dezinformację (fake newsy).\\n3. Świadome zarządzanie własną prywatnością\\n- Cyfrowy ślad (Digital Footprint): Edukacja uświadamia młodym ludziom, że raz zamieszczone w internecie zdjęcie, film czy komentarz mogą pozostać tam na zawsze i wpłynąć na ich przyszłą karierę lub relacje.\\n- Ochrona danych osobowych: Uczniowie dowiadują się, jak tworzyć silne hasła, dlaczego nie należy podawać obcym adresu czy numeru telefonu oraz jak działają uprawnienia aplikacji, które instalują na telefonach.\\n4. Wyrównywanie szans społecznych\\n- Różny poziom wiedzy w domach: Nie każdy rodzic posiada wystarczające kompetencje cyfrowe, aby nauczyć dziecko bezpiecznego poruszania się w przestrzeni cyfrowej. Szkoła staje się miejscem, które gwarantuje każdemu uczniowi – bez względu na pochodzenie – dostęp do wiedzy na równym poziomie.\\nNależy więc zapewnić, aby w ramach obowiązującej podstawy programowej wychowania przedszkolnego i podstawy programowej kształcenia ogólnego uwzględniać aktualną wiedzę naukową oraz kłaść nacisk na rozwijanie wiedzy i umiejętności służących bezpieczeństwu cyfrowemu, z uwzględnieniem zagadnień, takich jak: ochrona urządzeń elektronicznych i treści cyfrowych, świadomość i rozumienie ryzyka w sieci, zagrożenia w środowisku cyfrowym i środki bezpieczeństwa, ochrona prywatnych danych i prywatności, ochrona zdrowia i dbanie o samopoczucie – higiena cyfrowa i reagowanie na cyberprzemoc i przejawy radykalizacji oraz wpływ technologii i jej stosowania na środowisko, dostosowanych do wieku uczniów. \\nMinister właściwy do spraw oświaty i wychowania będzie mógł realizować działania informacyjne i promocyjne w powyższym zakresie, a także zlecać ich realizację jednostkom organizacyjnym podległym temu ministrowi lub przez niego nadzorowanym. Będzie mógł także, w drodze konkursu, zlecać realizację działań informacyjnych i promocyjnych organizacjom pozarządowym, w tym organizacjom harcerskim, instytutom badawczym, instytucjom kultury czy podmiotom prowadzącym statutową działalność w zakresie oświaty i wychowania.\\n\\n………………….\\n[3] K. Drążewski, M. Grochowski, G. Materna, J. Mazur, K. M. Szreder, M. Wilczyńska, B. Wołodkiewicz [w:] M. Grochowski (red.), Akt o rynkach cyfrowych – Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2022/1925 z dnia 14 września 2022 r. w sprawie kontestowalnych i uczciwych rynków w sektorze cyfrowym oraz zmiany dyrektyw (UE) 2019/1937 i (UE) 2020/1828. Komentarz [w:] Rynek cyfrowy. Akt o usługach cyfrowych. Akt o rynkach cyfrowych. Rozporządzenie platform-to-busines, Nb 11–12.\",\"organ\":\"MC/ME\",\"person\":\"Dariusz Standerski Sekretarz Stanu w Ministerstwie Cyfryzacji; Katarzyna Lubnauer Sekretarz Stanu w Ministerstwie Edukacji Narodowej\",\"planned_adoption\":\"I kwartał 2027 r.\",\"status\":\"\",\"resignation\":\"\",\"published_at\":\"2026-10-27T14:51:00Z\",\"web_url\":\"https://www.gov.pl/web/premier/projekt-ustawy-o-minimalnym-wieku-dostepu-do-internetowych-serwisow-spolecznosciowych\",\"rcl_project_id\":null},\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-27T18:45:01Z\",\"last_checked_at\":\"2026-10-27T18:45:01Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранные дети и подростки, живущие в Польше","родители иностранных детей школьного возраста","иностранные пользователи соцсетей, на которых распространяется польское право","иностранные учителя и кадры в польских школах"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-27T19:14:22Z","assessed_at":"2026-10-27T19:14:22Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Сетевой возрастной барьер · UD492</b>\n📜 <b>План правительства</b>\n\nO minimalnym wieku dostępu do internetowych serwisów społecznościowych\n\n⏳ <i>Это пока только намерение: текста проекта ещё нет. Запись в плане работ правительства от 27 окт 2026. Разбор текста придёт ответом в эту же ветку, когда проект опубликуют на RCL и начнутся публичные консультации.</i>\n\n👥 <b>Кого касается:</b> иностранные дети и подростки, живущие в Польше; родители иностранных детей школьного возраста; иностранные пользователи соцсетей, на которых распространяется польское право; иностранные учителя и кадры в польских школах\n\n💡 <b>Что это значит на практике:</b> Подростки младше 15 лет, независимо от гражданства, могут столкнуться с блокировкой или ограничением аккаунтов в соцсетях. Школы усилят обучение цифровой безопасности, а родителям придётся учитывать новые возрастные ограничения и возможные проверки возраста детей онлайн.\n\n👉 <b>Что можно сделать сейчас:</b> можно заявить интерес к работам над проектом (zgłoszenie zainteresowania): закон допускает это с публикации плана — письмом органу, который готовит проект: MC/ME\n\n🔑 <b>Ключевые изменения</b>\n• Минимальный возраст доступа к соцсетям будет установлен на 15 лет\n• Провайдеры соцсетей должны будут проверять возраст пользователей\n• Будут указаны допустимые способы онлайн‑верификации возраста\n• В школьные программы включат больше тем цифровой и сетевой безопасности\n• Министр образования проведёт информкампании о безопасном интернете\n\n🗺 <b>Путь:</b> план ● → RCL → Сейм → комиссии → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> публикация проекта на RCL и общественные консультации, затем комитеты Совета министров, Rada Ministrów и внесение в Сейм · принятие правительством: I кв. 2027\n\n🏛 <b>Стадия:</b> проект внесён в план работ правительства, текста ещё нет\n✍️ <b>Инициатор:</b> правительственный — MC/ME · номер в wykazie prac RM: UD492\n📄 <b>Внесён в план работ:</b> 27 окт 2026\nℹ️ <i>Оценка по описанию из плана работ правительства: текста проекта ещё не существует.</i>\n\n🟡 <b>Важность:</b> ●●●○○ 3/5\n🏷 <b>Категория:</b> соцсфера\n\n🔗 <a href=\"https://www.gov.pl/web/premier/projekt-ustawy-o-minimalnym-wieku-dostepu-do-internetowych-serwisow-spolecznosciowych\">Запись в плане работ</a> | <a href=\"https://www.gov.pl/web/premier/wplip-rm\">Wykaz prac RM</a>\n\n#UD492 #важность3 #соцсфера #wykazRM","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-27","still_meets":false,"reply_to":null,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["иностранные дети и подростки, живущие в Польше","родители иностранных детей школьного возраста","иностранные пользователи соцсетей, на которых распространяется польское право","иностранные учителя и кадры в польских школах"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-27T19:14:22Z","assessed_at":"2026-10-27T19:14:22Z","novelty":"unknown","rule_version":"attention-v1"}');
INSERT INTO "publications" VALUES(227,10,'3231','agenda','sent','@lex_inform_pl',148,'[]',NULL,'2026-10-28T18:57:35+00:00','2026-10-29T19:05:44+00:00',NULL,0,'DER/140/2026-11-05+10:00+sala nr 312, bud. U',NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3231\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-08\",\"document_date\":\"2026-10-08\",\"change_date\":\"2026-10-20T09:04:06Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-170-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-170-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-08\",\"print_number\":\"3231\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania w komisjach\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\"