e\":null,\"children\":[{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"DER\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja do Spraw Deregulacji\",\"children\":[]},{\"stage_name\":\"Skierowanie\",\"stage_type\":\"Referral\",\"date\":\"2026-10-20\",\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":\"ENM\",\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":\"Komisja Edukacji i Nauki\",\"children\":[]}]}],\"closure_date\":null,\"passed\":false,\"document\":{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"kind\":\"print\",\"extra_urls\":[],\"senate\":null,\"alternatives\":[],\"compare_versions\":false,\"normative_urls\":[],\"required_urls\":[],\"amendment_urls\":[],\"version_basis\":[],\"official_link_conflict\":false},\"analysis_sha256\":\"text-v2:cbeb72dab45a6fe6d2941439b13e6dac6816abe9f3dc30fa6b9ba1da034e00f0\",\"analysis_revision\":1,\"seen_supplements\":[]},\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Проект меняет правила приостановки обучения докторантов и их соцстрахование: вводится обязательное страхование по болезни и чёткие права на пособия при болезни, родительстве и несчастных случаях. Выпускникам школ докторантских дают бесплатный доступ к инфраструктуре вуза до защиты.\",\"key_changes\":[\"Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией\",\"Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии\",\"Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS\",\"Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу\",\"Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты\"],\"affected_groups\":[\"иностранные докторанты польских школ докторантских\",\"иностранцы, завершившие обучение в школе докторантской и готовящие защиту\",\"вузы и научные учреждения, ведущие школы докторантские с иностранцами\"],\"practical_impact\":\"Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.\",\"effective_date\":\"Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.\",\"confidence\":0.93,\"rationale\":\"Проект напрямую меняет правила соцстрахования, пособий и организации обучения для всех докторантов, в том числе иностранных, поэтому важен на уровне социальных прав (категория social, оценка 3).\",\"mnemonic_candidate\":\"\",\"mnemonic_fallback\":\"\",\"mnemonic_basis\":\"\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-5.1-2025-11-13\",\"prompt_version\":\"2026-10-v10\",\"input_chars\":68211,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-09T07:38:31Z\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:cbeb72dab45a6fe6d2941439b13e6dac6816abe9f3dc30fa6b9ba1da034e00f0\",\"selection\":{\"question\":\"bill_text\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[\"sejm/10/print/3231\"],\"completeness\":[],\"parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"members\":[],\"container_sha256\":\"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7\",\"sha256\":\"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7\",\"role\":\"bill\",\"text\":\"\",\"pages\":83,\"page_start\":1,\"page_end\":83,\"text_start\":0,\"text_end\":252394,\"text_sha256\":\"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9\",\"losses\":[]}],\"observed_parts\":[{\"url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"members\":[],\"container_sha256\":\"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7\",\"sha256\":\"519b94f07a9b243cc4fbb5c3b40f28c640426b1d7ff3d5ed2d07259e9b85ebb7\",\"role\":\"bill\",\"text\":\"\",\"pages\":83,\"page_start\":1,\"page_end\":83,\"text_start\":0,\"text_end\":252394,\"text_sha256\":\"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9\",\"losses\":[]}],\"rejected\":[],\"facts\":[{\"kind\":\"official_link\",\"value\":\"sejm/10/print/3231\",\"provenance\":\"source_relation\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"text_sha256\":\"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9\",\"block_id\":\"part:0\",\"start\":0,\"end\":0,\"quote\":\"\"},{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"text_sha256\":\"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9\",\"block_id\":\"part:0\",\"start\":0,\"end\":898,\"quote\":\"Druk nr 3231\\n Warszawa, 8 października 2026 r.\\nSEJM\\nRZECZYPOSPOLITEJ POLSKIEJ\\nX kadencja\\n\\nPrezes Rady Ministrów\\nRM-0610-170-26\\n\\n Pan\\n Włodzimierz Czarzasty\\n Marszałek Sejmu\\n Rzeczypospolitej Polskiej\\n\\nSzanowny Panie Marszałku,\\nna podstawie art. 118 ust. 1 Konstytucji Rzeczypospolitej Polskiej przedstawiam\\nSejmowi Rzeczypospolitej Polskiej projekt ustawy\\n\\n - o zmianie ustawy - Prawo o szkolnictwie\\nwyższym i nauce oraz niektórych innych ustaw.\\n\\nProjekt ma charakter deregulacyjny.\\nDo prezentowania stanowiska Rządu w tej sprawie w toku prac parlamentarnych\\nzostał upoważniony Minister Nauki i Szkolnictwa Wyższego.\\n\\n Z poważaniem\\n Donald Tusk\\n /podpisano kwalifikowanym podpisem elektronicznym/\\n\\n                Tłoczono z polecenia  Marszałka Sejmu Rzeczypospolitej Polskiej\\n\\n\\fProjekt\\nU S T AWA\\nz dnia\\no zmianie ustawy – Prawo o szkolnictwie wyższym i nauce oraz niektórych innych\\nustaw1)\\nArt. 1\"},{\"kind\":\"coverage\",\"value\":\"body_through_commencement\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\",\"text_sha256\":\"e170957b3c84615b6e9f7c35d04cbc132dfbc6756ebcb177fbb67832d5170ea9\",\"block_id\":\"part:0\",\"start\":14153,\"end\":14175,\"quote\":\"Ustawa wchodzi w życie\"}],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":252394,\"page_start\":1,\"page_end\":83,\"losses\":[]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":252394,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"08f72a4fdc0a7b856383b8f94fbcd20d3250009a2b255650ca4e9089ee5fb582\"},\"law_sha256\":\"law-v2:8c9f289a9c507825256be59e5306e676356ecd300e9c57646c1ece5096ee9060\",\"source_checked_at\":\"2026-10-20T18:03:44Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Больничный докторанта\",\"language\":\"ru\",\"basis\":\"Проект вводит обязательное страхование и пособия по болезни, родительству и несчастным случаям для докторантов со стипендией.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,