INSERT INTO "publications" VALUES(229,10,'3160','message_part','sent','@lex_inform_pl',76,'[]',NULL,'2026-10-28T18:58:27+00:00','2026-10-28T18:58:33+00:00',NULL,0,'card/78/92980d564ea00ecce1cdc05dc0e3592cc6cafbd54a828af95e19fa33c87b8389-222/1','92980d564ea00ecce1cdc05dc0e3592cc6cafbd54a828af95e19fa33c87b8389','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3160\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-01\",\"document_date\":\"2026-10-01\",\"change_date\":\"2026-10-28T11:16:44Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-169-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:nieruchomosci_cudzoziemcy\",\"text:praca_sezonowa\"],\"stages_fingerprint\":\"05f7455bc5f5a3685f60d19083a291f77f9e755972aec40fd075b2ad7db30806\",\"observed_closure_date\":\"2026-10-22\",\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Сделки без 3a\",\"language\":\"ru\",\"basis\":\"Текст проекта прямо предусматривает отмену ст. 3a в законе о nabywaniu nieruchomości przez cudzoziemców, что меняет режим покупки недвижимости иностранцами.\",\"selected_at\":\"2026-10-21T19:11:53Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":{\"name\":\"Сделка без 3a\",\"language\":\"ru\",\"basis\":\"Текст проекта прямо предусматривает отмену статьи 3a в ustawa o nabywaniu nieruchomości przez cudzoziemców, влияя на правила сделок с недвижимостью для иностранцев.\",\"selected_at\":\"2026-10-23T18:21:01Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":6,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2197.html\",\"title\":\"Ustawa o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"print_number\":\"892\",\"received\":\"2026-10-23\",\"committees\":[{\"id\":218,\"name\":\"Komisja Budżetu i Finansów Publicznych\",\"email\":\"kbfp@senat.gov.pl\"},{\"id\":219,\"name\":\"Komisja Gospodarki Narodowej i Innowacyjności\",\"email\":\"kgni@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-26\"],\"committee_work_completed\":true,\"review_documents\":[{\"url\":\"https://www.senat.gov.pl/download/gfx/senat/pl/senatdruki/14798/druk/892a.pdf\",\"title\":\"Druk nr 892 A\",\"body\":\"126. pos. Komisji Budżetu i Finansów Publicznych oraz 96. pos. Komisji Gospodarki Narodowej i Innowacyjności\",\"role\":\"commission_report\",\"date\":\"2026-10-26\"}]},\"seen_supplements\":[\"3160-001\",\"3160-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T18:56:08Z\",\"last_checked_at\":\"2026-10-28T18:58:11Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Сделки без 3a · druk nr 3160</b>\n📜 <b>Новый законопроект</b>\n\nO wspieraniu nowych inwestycji oraz niektórych innych ustaw\n<i>Принят Сеймом 22 окт 2026</i>\n\n👥 <b>Кого касается:</b> иностранцы, покупающие недвижимость в Польше; иностранные инвесторы, пользующиеся поддержкой PSI; иностранные владельцы и со‑владельцы польских компаний в PSI\n\n💡 <b>Что это значит на практике:</b> Покупка недвижимости иностранцами будет регулироваться без ст. 3a, что приведёт к изменению части требований или процедуры сделок. Иностранные инвесторы в PSI столкнутся с новыми правилами расчёта налоговой льготы и обязательной электронной подачей всех документов.\n\n👉 <b>Что можно сделать сейчас:</b> пока ничего — закон у Президента\n\n🔑 <b>Ключевые изменения</b>\n• Отменяется ст. 3a в законе о покупке недвижимости иностранцами.\n• Налоговая льгота PSI чётко привязана к указанной в решении деятельности и территории.\n• Освобождение от налога по PSI начинается после окончания инвестпроекта или начала затрат на новые рабочие места.\n• Заявления, жалобы и переписка по PSI подаются только через электронное индивидуальное konto.\n• Крупные решения о поддержке (от 40 млн zł помощи) требуют мнения Шефа KAS.\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу 1 января 2027 г., при этом ст. 2 (отмена ст. 3a) начинает действовать с 31 декабря 2027 г.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ✓ → II и III чтение ✓ → Сенат ✓ → Президент ● → Dz.U. → в силе\n⏭ <b>Что дальше:</b> подпись Президента (до 21 дня), затем публикация в Dziennik Ustaw\n\n🏛 <b>Стадия:</b> позиция Сената (27 окт 2026)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 1 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟢 <b>Важность:</b> ●●○○○ 2/5\n🏷 <b>Категория:</b> косвенное влияние\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3160\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3160\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\">Проект на RCL</a>\n\n#kadencja10druk3160 #важность2 #косвенно #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":78,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-28","still_meets":false,"reply_to":76,"edit_message_id":76,"revision_of":78,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(230,10,'3231','message_part','sent','@lex_inform_pl',86,'[]',NULL,'2026-10-28T18:58:40+00:00','2026-10-28T18:58:45+00:00',NULL,0,'card/156/2ca37ef6dad30e6b8c220a7d08f7caeaea9e937c4ae482366f3ca4e1433a7dd5-96/1','2ca37ef6dad30e6b8c220a7d08f7caeaea9e937c4ae482366f3ca4e1433a7dd5','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3231\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy - Prawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach zawieszania kształcenia doktorantów oraz objęcie ich obowiązkowym ubezpieczeniem chorobowym i prawem do świadczeń w przypadku choroby, rodzicielstwa lub wypadku. Nowe przepisy mają również ułatwić osobom, które ukończyły szkołę doktorską, dalsze prowadzenie badań i przygotowanie się do obrony doktoratu. Nowe przepisy realizują działania deregulacyjne rządu.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-08\",\"document_date\":\"2026-10-08\",\"change_date\":\"2026-10-20T09:04:06Z\",\"closure_date\":null,\"passed\":false,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-170-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-170-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:obcokrajowcy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\"],\"stages_fingerprint\":\"ce84531a49b298be4c7ea39e83097baaf00de88b348952a502180b6584011449\",\"observed_closure_date\":null,\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Больничный докторанта\",\"language\":\"ru\",\"basis\":\"Проект вводит обязательное страхование и пособия по болезни, родительству и несчастным случаям для докторантов со стипендией.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":2,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":\"RPW/33929/2026\",\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"senate\":null,\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-20T18:03:37Z\",\"last_checked_at\":\"2026-10-27T19:18:32Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Больничный докторанта · druk nr 3231</b>\n📜 <b>Новый законопроект</b>\n\nPrawo o szkolnictwie wyższym i nauce oraz niektórych innych ustaw\n\n👥 <b>Кого касается:</b> иностранные докторанты польских школ докторантских; иностранцы, завершившие обучение в школе докторантской и готовящие защиту; вузы и научные учреждения, ведущие школы докторантские с иностранцами\n\n💡 <b>Что это значит на практике:</b> Иностранец‑докторант будет автоматически застрахован по болезни и сможет получать zasiłek chorobowy, macierzyński и по несчастным случаям, но в периоды приостановки обучения стипендия часто не платится. После окончания школы докторантской можно бесплатно пользоваться лабораториями и ИТ‑системами вуза до завершения процедуры присуждения степени.\n\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=DER\">Komisja do Spraw Deregulacji (DER)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=DER\">форма письма</a>), <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=ENM\">Komisja Edukacji i Nauki (ENM)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=ENM\">форма письма</a>) до заседания 5 нояб 2026\n\n🔑 <b>Ключевые изменения</b>\n• Обязательное страхование по болезни и несчастным случаям для докторантов со стипендией\n• Приостановка обучения по разным жизненным причинам до 24 мес, без стипендии\n• Оплата болезни: сначала стипендия как «болничный», затем пособие из ZUS\n• Докторанты, ухаживающие за ребёнком, приравниваются к лицам в отпуске по уходу\n• Выпускники школ докторантских бесплатно пользуются инфраструктурой вуза до защиты\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу по истечении 9 месяцев со дня опубликования, за исключением указанных в нём изменений, которые вступают в силу в день опубликования.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ● → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> I чтение в комиссии — Komisja do Spraw Deregulacji (DER), Komisja Edukacji i Nauki (ENM) · 5 нояб 2026, 10:00\n\n🏛 <b>Стадия:</b> направлен на I чтение (20 окт 2026) · направлен в комиссию Komisja Edukacji i Nauki (ENM)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 8 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟡 <b>Важность:</b> ●●●○○ 3/5\n🏷 <b>Категория:</b> соцсфера\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3231\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3231\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3231/3231.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-170-26\">Проект на RCL</a>\n\n#kadencja10druk3231 #RPW_33929_2026 #важность3 #соцсфера #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":156,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-28","still_meets":false,"reply_to":86,"edit_message_id":86,"revision_of":156,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(231,10,'3146','status_update','sent','@lex_inform_pl',147,'[]',189,'2026-10-28T19:18:25+00:00','2026-10-28T19:18:31+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3146\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-23\",\"document_date\":\"2026-09-23\",\"change_date\":\"2026-10-28T11:16:32Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":true,\"rcl_num\":\"RM-0610-143-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:migracja\",\"text:straz_graniczna\",\"text:granica_panstwowa\",\"text:schengen\",\"text:pracownicy_delegowani\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-09-23\",\"print_number\":\"3146\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"