INSERT INTO "publications" VALUES(234,10,'3146','message_part','sent','@lex_inform_pl',88,'[]',NULL,'2026-10-29T07:22:40+00:00','2026-10-29T07:22:46+00:00',NULL,0,'card/99/b7b232933c216669099cd032cc67bc142872ad69c58a28388772cca98fb800bb-232/1','b7b232933c216669099cd032cc67bc142872ad69c58a28388772cca98fb800bb','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3146\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zapewnienia stosowania przepisów rozporządzenia Parlamentu Europejskiego i Rady (UE) 2019/1896; rozszerzenia w sposób istotny zakres działania Europejskiej Agencji Straży Granicznej i Przybrzeżnej, jako podmiotu, który ma dysponować znacznie większymi niż dotychczas zasobami kadrowymi i sprzętowymi. Rozporządzenie 2019/1896, w ramach rozszerzania mandatu Agencji Frontex, tworzy stałą służbę Europejskiej Straży Granicznej i Przybrzeżnej, aby skuteczniej wspierać państwa członkowskie w zakresie ochrony granic zewnętrznych, walki z przestępczością transgraniczną oraz zwiększać skuteczność i trwały charakter powrotów migrantów o nieuregulowanym statusie\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-09-23\",\"document_date\":\"2026-09-23\",\"change_date\":\"2026-10-28T11:16:32Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":true,\"rcl_num\":\"RM-0610-143-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:migracja\",\"text:straz_graniczna\",\"text:granica_panstwowa\",\"text:schengen\",\"text:pracownicy_delegowani\"],\"stages_fingerprint\":\"758cc3cfd5f3f42d5ce873d1e9186cc4ac36ae647edf296e2eebb55de8b89691\",\"observed_closure_date\":\"2026-10-22\",\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Депортации Frontex\",\"language\":\"ru\",\"basis\":\"Проект вводит в закон об иностранцах операции и интервенции по принудительному возвращению с участием Frontex и регулирует их проведение в Польше.\",\"selected_at\":\"2026-10-22T08:26:57Z\",\"origin\":\"backfill\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":9,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":\"RCL/12405005\",\"linked_wykaz_number\":\"UC126\",\"act\":null,\"authors\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2207.html\",\"title\":\"Ustawa o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw\",\"print_number\":\"903\",\"received\":\"2026-10-23\",\"committees\":[{\"id\":228,\"name\":\"Komisja Praw Człowieka i Praworządności\",\"email\":\"kpcp@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-27\"],\"committee_work_completed\":false,\"review_documents\":[{\"url\":\"https://www.senat.gov.pl/download/gfx/senat/pl/senatdruki/14805/druk/903a.pdf\",\"title\":\"Druk nr 903 A\",\"body\":\"153. pos. Komisji Praw Człowieka i Praworządności\",\"role\":\"commission_report\",\"date\":\"2026-10-27\"},{\"url\":\"https://www.senat.gov.pl/download/gfx/senat/pl/senatdruki/14808/druk/903z.pdf\",\"title\":\"Druk nr 903 Z\",\"body\":\"155. pos. Komisji Praw Człowieka i Praworządności\",\"role\":\"commission_report\",\"date\":\"2026-10-27\"}]},\"seen_supplements\":[],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-09-28T15:32:12Z\",\"last_checked_at\":\"2026-10-29T07:22:28Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Депортации Frontex · druk nr 3146</b>\n📜 <b>Новый законопроект</b>\n\nO Straży Granicznej oraz niektórych innych ustaw\n<i>Принят Сеймом 22 окт 2026</i>\n\n👥 <b>Кого касается:</b> иностранцы с решениями о возврате/выдворении; мигранты с неурегулированным статусом, подлежащие депортации; лица, находящиеся в процедурах принудительного возвращения\n\n💡 <b>Что это значит на практике:</b> При решении о принудительном возвращении депортация может проводиться в рамках операций Frontex с участием персонала других стран ЕС. Эти группы получают право действовать и применять принуждение по правилам ЕС, а организация вывозов (в т.ч. чартерных рейсов) может стать более массовой и быстрой.\n\n👉 <b>Что можно сделать сейчас:</b> направить мнение в комиссию — <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/agent.xsp?symbol=KOMISJAST&amp;NrKadencji=10&amp;KodKom=ASW\">Komisja Administracji i Spraw Wewnętrznych (ASW)</a> (<a href=\"https://www.sejm.gov.pl/Sejm10.nsf/contact.xsp?type=ASW\">форма письма</a>) до заседания 6 нояб 2026\n\n🔑 <b>Ключевые изменения</b>\n• В закон об иностранцах вводятся термины «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС\n• Komendant Główny SG сможет запрашивать у Frontex операции/интервенции по возвращению и утверждать их планы\n• Персонал Frontex и погранслужб ЕС при депортациях в Польше действует по правилам ЕС, включая оружие и силу\n• В законе о границе урегулированы быстрые интервенции, совместные операции и hotspot’ы с участием Frontex\n• В законе о оружии вводится режим для служебного оружия персонала постоянной службы Frontex в Польше\n\n📅 <b>Вступление в силу:</b> закон вступает в силу через 14 дней со дня его официального опубликования.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ✓ → II и III чтение ✓ → Сенат ● → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> Сейм рассматривает поправки Сената · 6 нояб 2026, 08:30\n\n🏛 <b>Стадия:</b> позиция Сената (27 окт 2026) · направлен в комиссию Komisja Administracji i Spraw Wewnętrznych (ASW) (28 окт 2026)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 23 сент 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🔴 <b>Важность:</b> ●●●●● 5/5\n🏷 <b>Категория:</b> легализация пребывания\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3146\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3146\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3146/3146.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-143-26\">Проект на RCL</a>\n\n#kadencja10druk3146 #UC126 #важность5 #легализация #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":99,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-29","still_meets":false,"reply_to":88,"edit_message_id":88,"revision_of":99,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(235,10,'3160','status_update','queued','@lex_inform_pl',NULL,'[]',190,'2026-10-29T19:06:28+00:00',NULL,NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3160\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-01\",\"document_date\":\"2026-10-01\",\"change_date\":\"2026-10-28T11:16:44Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-169-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:nieruchomosci_cudzoziemcy\",\"text:praca_sezonowa\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2026-10-01\",\"print_number\":\"3160\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":\"2026-10-01\",\"print_nu