INSERT INTO "publications" VALUES(236,10,'3160','message_part','sent','@lex_inform_pl',76,'[]',NULL,'2026-10-29T19:06:34+00:00','2026-10-29T19:06:40+00:00',NULL,0,'card/78/f6869bc0e295791b1a72259379d853cf0b7ad104a339c9f6863849e65acf5b50-229/1','f6869bc0e295791b1a72259379d853cf0b7ad104a339c9f6863849e65acf5b50','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"3160\",\"title\":\"Rządowy projekt ustawy o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"description\":\"projekt dotyczy zmian w zasadach działania Polskiej Strefy Inwestycji (PSI): zmiana zasad określania dochodu, który może być objęty zwolnieniem w ramach PSI; decyzja o wsparciu będzie obowiązywać od 15 do maksymalnie 20 lat, w zależności od obszaru kraju; przy większych inwestycjach projekt przewiduje opiniowanie decyzji o wsparciu przez Szefa Krajowej Administracji Skarbowe; wnioski o wsparcie w ramach systemu rozpatrywane będą za pośrednictwem Elektronicznej Platformy Polskiej Strefy Inwestycji\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-01\",\"document_date\":\"2026-10-01\",\"change_date\":\"2026-10-28T11:16:44Z\",\"closure_date\":\"2026-10-22\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-169-26\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\",\"prints_considered_jointly\":[],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:nieruchomosci_cudzoziemcy\",\"text:praca_sezonowa\"],\"stages_fingerprint\":\"3a5d7f4d8aafaccfc0f1a9348e0c219f258debf37a948728b5558fa838b6abf1\",\"observed_closure_date\":\"2026-10-22\",\"commission_review\":null,\"committee_documents\":[],\"editorial\":{\"mnemonic\":{\"name\":\"Сделки без 3a\",\"language\":\"ru\",\"basis\":\"Текст проекта прямо предусматривает отмену ст. 3a в законе о nabywaniu nieruchomości przez cudzoziemców, что меняет режим покупки недвижимости иностранцами.\",\"selected_at\":\"2026-10-21T19:11:53Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":{\"name\":\"Сделка без 3a\",\"language\":\"ru\",\"basis\":\"Текст проекта прямо предусматривает отмену статьи 3a в ustawa o nabywaniu nieruchomości przez cudzoziemców, влияя на правила сделок с недвижимостью для иностранцев.\",\"selected_at\":\"2026-10-23T18:21:01Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"priority\":null,\"priority_history\":[],\"announced_version\":1},\"analysis_attempts\":0,\"analysis_generation\":6,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"senate\":{\"url\":\"https://www.senat.gov.pl/prace/proces-legislacyjny-w-senacie/ustawy-uchwalone-przez-sejm/ustawy-uchwalone-przez-sejm/ustawa,2197.html\",\"title\":\"Ustawa o zmianie ustawy o wspieraniu nowych inwestycji oraz niektórych innych ustaw\",\"print_number\":\"892\",\"received\":\"2026-10-23\",\"committees\":[{\"id\":218,\"name\":\"Komisja Budżetu i Finansów Publicznych\",\"email\":\"kbfp@senat.gov.pl\"},{\"id\":219,\"name\":\"Komisja Gospodarki Narodowej i Innowacyjności\",\"email\":\"kgni@senat.gov.pl\"}],\"committee_sittings\":[\"2026-10-26\"],\"committee_work_completed\":true,\"review_documents\":[{\"url\":\"https://www.senat.gov.pl/download/gfx/senat/pl/senatdruki/14798/druk/892a.pdf\",\"title\":\"Druk nr 892 A\",\"body\":\"126. pos. Komisji Budżetu i Finansów Publicznych oraz 96. pos. Komisji Gospodarki Narodowej i Innowacyjności\",\"role\":\"commission_report\",\"date\":\"2026-10-26\"}]},\"seen_supplements\":[\"3160-001\",\"3160-002\"],\"joint\":null,\"discontinued_at\":null,\"observation_mode\":\"full\",\"observation_basis\":\"telegram_thread\",\"first_seen_at\":\"2026-10-01T18:56:08Z\",\"last_checked_at\":\"2026-10-29T19:06:28Z\"}","attention":null,"attention_history":[],"policy_version":"legacy","rendered_text":"<b>Сделки без 3a · druk nr 3160</b>\n📜 <b>Новый законопроект</b>\n\nO wspieraniu nowych inwestycji oraz niektórych innych ustaw\n<i>Принят Сеймом 22 окт 2026</i>\n\n👥 <b>Кого касается:</b> иностранцы, покупающие недвижимость в Польше; иностранные инвесторы, пользующиеся поддержкой PSI; иностранные владельцы и со‑владельцы польских компаний в PSI\n\n💡 <b>Что это значит на практике:</b> Покупка недвижимости иностранцами будет регулироваться без ст. 3a, что приведёт к изменению части требований или процедуры сделок. Иностранные инвесторы в PSI столкнутся с новыми правилами расчёта налоговой льготы и обязательной электронной подачей всех документов.\n\n👉 <b>Что можно сделать сейчас:</b> пока ничего — закон у Президента\n\n🔑 <b>Ключевые изменения</b>\n• Отменяется ст. 3a в законе о покупке недвижимости иностранцами.\n• Налоговая льгота PSI чётко привязана к указанной в решении деятельности и территории.\n• Освобождение от налога по PSI начинается после окончания инвестпроекта или начала затрат на новые рабочие места.\n• Заявления, жалобы и переписка по PSI подаются только через электронное индивидуальное konto.\n• Крупные решения о поддержке (от 40 млн zł помощи) требуют мнения Шефа KAS.\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу 1 января 2027 г., при этом ст. 2 (отмена ст. 3a) начинает действовать с 31 декабря 2027 г.\n\n🗺 <b>Путь:</b> план ✓ → RCL ✓ → Сейм ✓ → комиссии ✓ → II и III чтение ✓ → Сенат ✓ → Президент ● → Dz.U. → в силе\n⏭ <b>Что дальше:</b> подпись Президента (до 21 дня), затем публикация в Dziennik Ustaw · решение до 18 нояб 2026\n\n🏛 <b>Стадия:</b> Закон передан Президенту (28 окт 2026)\n✍️ <b>Инициатор:</b> правительственный\n📄 <b>Дата druku:</b> 1 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟢 <b>Важность:</b> ●●○○○ 2/5\n🏷 <b>Категория:</b> косвенное влияние\n\n🔗 <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/druk.xsp?nr=3160\">Страница проекта в Сейме</a> | <a href=\"https://www.sejm.gov.pl/Sejm10.nsf/PrzebiegProc.xsp?nr=3160\">Ход процесса в Сейме</a> | <a href=\"https://api.sejm.gov.pl/sejm/term10/prints/3160/3160.pdf\">PDF</a> | <a href=\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-169-26\">Проект на RCL</a>\n\n#kadencja10druk3160 #важность2 #косвенно #kadencja10","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":78,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-29","still_meets":false,"reply_to":76,"edit_message_id":76,"revision_of":78,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}',NULL);
INSERT INTO "publications" VALUES(237,10,'RCL/12408601','new_bill','sent','@lex_inform_pl',149,'[]',NULL,'2026-10-29T19:12:08+00:00','2026-10-29T19:12:13+00:00',NULL,0,NULL,'9c35e4b03027061aa1835b22f4bff0b78c56238d4eab017230106f31fb896a6f','{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RCL/12408601\",\"title\":\"Projekt ustawy o zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych innych ustaw\",\"description\":\"RODZINNE I OPIEKUŃCZE PRAWO; rodzina\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-03-26\",\"document_date\":\"2026-03-26\",\"change_date\":\"2026-10-29T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":\"https://legislacja.rcl.gov.pl/projekt/12408601\",\"prints_considered_jointly\":[],\"applicant\":\"government\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:migracja\",\"text:obywatelstwo\",\"text:straz_graniczna\"],\"stages\":[{\"stage_name\":\"2. Uzgodnienia\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"3. Konsultacje publiczne\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"4. Opiniowanie\",\"stage_type\":\"RclStage\",\"date\":null,\"print_number\":null,\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]}],\"stages_fingerprint\":\"b4b6a1d4196e2182309dc514172d5b60ab6b074136e8252708772fb13296c2ca\",\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Меняются правила усыновления и приёмной опеки, в том числе для иностранцев. Предусмотрены переводчики, использование заключений из страны происхождения и проверки иностранных опекунов. Правила приёмной опеки охватывают также несовершеннолетних иностранцев в Польше вне перечисленных законом категорий.\",\"key_changes\":[\"Проверяемые иностранцы представляют сведения о несудимости и отсутствии запретов из реестра страны гражданства; проверки — не реже 24 месяцев.\",\"Министр может выделить центр усыновления для иностранцев; другие центры сохраняют компетенцию и могут использовать заключения из страны происхождения.\",\"При недостаточном польском допускается переводчик, в том числе на обучении; при усыновлении ребёнка из-за рубежа расходы несут кандидаты.\",\"При усыновлении с выездом в страну Гаагской конвенции: согласие на отчёты ежегодно первые 3 года после вступления решения в силу, затем раз в 3 года до 18 лет.\",\"Иностранному представителю зарубежного посредника по усыновлению нужен документ о знании польского; аккредитация посредника — максимум на 2 года.\"],\"affected_groups\":[\"Несовершеннолетние иностранцы, находящиеся в Польше, включая не перечисленных в статье 5, части 1, пунктах 2–6\",\"Иностранцы — кандидаты в усыновители, приёмные родители и руководители семейных детских домов; для приёмных родителей требуется законное пребывание\",\"Иностранцы в поддерживающих семьях, семьях временной подмены опекунов и семьях ухода за взрослыми; сотрудники, исполнители услуг, волонтёры и наставники воспитанников\",\"Совместно проживающие с кандидатами в усыновители, приёмными семьями, руководителями семейных детских домов и семьями ухода; с поддерживающими и подменяющими семьями — при контакте с детьми\",\"Представители зарубежных посредников и кандидаты в усыновители, проживающие за пределами Польши\"],\"practical_impact\":\"При усыновлении ребёнка супруга исключаются общий запрет судимости и проверка совместно проживающих. При ввозе усыновляемого ребёнка расходы на перевод в исключительных случаях, особенно при родстве, свойстве или объединении братьев и сестёр, может принять центр либо центральный орган. Для действующих зарубежных посредников: сведения о ранее отсутствовавшем представителе — за 3 месяца, подтверждение соответствия представителей требованиям — за 6 месяцев со вступления закона в силу.\",\"effective_date\":\"«Закон вступает в силу 1 октября 2026 года, за исключением: 1) статьи 1, пункта 17, и статьи 25 — с 1 января 2027 года; 2) статьи 1, пункта 101, статьи 2, пункта 1, статьи 3, пунктов 3 и 4, статей 8, 10 и 11, а также статьи 12, пункта 2, статей 16, 20–22 и 24 — с 1 января 2028 года; 3) статьи 1, пункта 150, подпункта d, пункта 152, подпункта d, пункта 155, подпункта c, пункта 157, подпункта a, второго и шестого абзацев перечня, а также пункта 158, подпунктов a, f и g, в части использования информационной системы — со дня, определённого в объявлении, предусмотренном статьёй 72».\",\"confidence\":0.93,\"rationale\":\"Оценка 3 и социальная категория обусловлены прямыми изменениями правил усыновления, приёмной опеки и проверки иностранцев, а не легализации их пребывания.\",\"mnemonic_candidate\":\"Переводчик при усыновлении\",\"mnemonic_fallback\":\"Перевод в процедуре усыновления\",\"mnemonic_basis\":\"Добавляемая статья 169a допускает переводчика при недостаточном владении польским и регулирует расходы при усыновлении ребёнка с переездом в Польшу.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-6.1-sol\",\"prompt_version\":\"2026-10-v13\",\"input_chars\":608481,\"truncated\":false,\"text_source\":\"documents\",\"created_at\":\"2026-10-29T19:12:03Z\",\"computation_id\":\"result-v1:7abf53b9cf9baa9408a529918c05ad0692155a5eed622d8b4820582346da4f4d\",\"request_sha256\":\"1fe039ec8ff4e37ff47e5282564600ea8cd4ed4bbdebe0df2f61e311b0364adf\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf\",\"source_kind\":\"rcl\",\"revision\":1,\"text_sha256\":\"text-v2:193ed7229af7dcaf3d276ba2c825d6d03bb37cffe232b5613e8656a3b3a8aac1\",\"selection\":{\"question\":\"bill_text\",\"policy_version\":\"document-selection-v1\",\"state\":\"selected\",\"belonging\":[],\"role\":[],\"version\":[\"rcl/12408601/stage/13194357\",\"Projekt 20.03.2026.\"],\"completeness\":[],\"parts\":[{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf\",\"members\":[],\"container_sha256\":\"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085\",\"sha256\":\"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085\",\"role\":\"bill\",\"text\":\"\",\"pages\":165,\"page_start\":1,\"page_end\":165,\"text_start\":0,\"text_end\":345959,\"text_sha256\":\"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036\",\"losses\":[]},{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769079.pdf\",\"members\":[],\"container_sha256\":\"1df0a054620d8dc2bdfeb38bf61b41734b91bc2d4c1bb10d664274a550e88af9\",\"sha256\":\"1df0a054620d8dc2bdfeb38bf61b41734b91bc2d4c1bb10d664274a550e88af9\",\"role\":\"justification\",\"text\":\"\",\"pages\":73,\"page_start\":1,\"page_end\":73,\"text_start\":0,\"text_end\":185158,\"text_sha256\":\"024ef7a3efd75d5c64a39559503a84ce9183008c6f93142369719d2b2fba0c4b\",\"losses\":[]},{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769080.pdf\",\"members\":[],\"container_sha256\":\"8849709070e4264a5ed1373b2d0fbe3fa39d4b42341c5fd998f699ccc7fb032c\",\"sha256\":\"8849709070e4264a5ed1373b2d0fbe3fa39d4b42341c5fd998f699ccc7fb032c\",\"role\":\"osr\",\"text\":\"\",\"pages\":29,\"page_start\":1,\"page_end\":29,\"text_start\":0,\"text_end\":131304,\"text_sha256\":\"7cfd3b14744a034f650c41ff6ea6480bd4186e42ed406fab76b3db0bdb4951fe\",\"losses\":[]}],\"observed_parts\":[{\"url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf\",\"members\":[],\"container_sha256\":\"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085\",\"sha256\":\"763ac6cd72dbe3e6e45dc93c6f0e3935108d0b4188d750307babf0cb97a89085\",\"role\":\"bill\",\"text\":\"\",\"pages\":165,\"page_start\":1,\"page_end\":165,\"text_start\":0,\"text_end\":345959,\"text_sha256\":\"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036\",\"losses\":[]}],\"rejected\":[],\"facts\":[{\"kind\":\"official_link\",\"value\":\"rcl/12408601/stage/13194357\",\"provenance\":\"source_relation\",\"part_index\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf\",\"text_sha256\":\"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036\",\"block_id\":\"part:0\",\"start\":0,\"end\":0,\"quote\":\"\"},{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194357/13194358/dokument769078.pdf\",\"text_sha256\":\"2fba842d95836d45ad7f4728ac2632ea1015cd608c62bf49a6bd44cb43066036\",\"block_id\":\"part:0\",\"start\":0,\"end\":156,\"quote\":\"Projekt z dnia 20 marca 2026 r.\\nU S T A W A\\nz dnia\\no zmianie ustawy o wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych\\ninnych ustaw 1)\\nArt. 1\"},{\"kind\":\"draft_date\",\"value\":\"2026-03-20\",\"provenance\":\"extracted_text\",\"part_index\":0,\