94360/dokument804710.pdf\",\"created\":\"2026-10-29\",\"author\":\"Minister Rodziny, Pracy i Polityki Społecznej\"}]},{\"id\":13194361,\"name\":\"Odniesienie się wnioskodawcy do uwag\",\"modified\":null,\"documents\":[]}],\"loose_documents\":[],\"catalog_read\":true},{\"id\":13194362,\"number\":5,\"name\":\"Komitet Rady Ministrów do Spraw Cyfryzacji\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194367,\"number\":6,\"name\":\"Komitet do Spraw Europejskich\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194372,\"number\":7,\"name\":\"Komitet Społeczny Rady Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194377,\"number\":8,\"name\":\"Komitet Ekonomiczny Rady Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194382,\"number\":9,\"name\":\"Stały Komitet Rady Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194387,\"number\":10,\"name\":\"Komisja Prawnicza\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194388,\"number\":11,\"name\":\"Potwierdzenie projektu przez Stały Komitet Rady Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194393,\"number\":12,\"name\":\"Rada Ministrów\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194399,\"number\":13,\"name\":\"Notyfikacja\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false},{\"id\":13194400,\"number\":14,\"name\":\"Skierowanie projektu ustawy do Sejmu\",\"state\":\"not_started\",\"started\":null,\"ended\":null,\"modified\":null,\"folders\":[],\"loose_documents\":null,\"catalog_read\":false}],\"consultation\":{\"letter_url\":\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194351/13194353/dokument769093.pdf\",\"letter_date\":null,\"days\":null,\"deadline\":\"2026-05-15\",\"email\":\"sekretariat.dd@mrpips.gov.pl\",\"positions\":87,\"response_published\":false,\"letters_read\":[\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194351/13194353/dokument769093.pdf\",\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194351/13194353/dokument769094.pdf\"],\"letter_parser\":2},\"consultation_attempts\":1},\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-29T19:00:59Z\",\"last_checked_at\":\"2026-10-29T19:00:59Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["Несовершеннолетние иностранцы, находящиеся в Польше, включая не перечисленных в статье 5, части 1, пунктах 2–6","Иностранцы — кандидаты в усыновители, приёмные родители и руководители семейных детских домов; для приёмных родителей требуется законное пребывание","Иностранцы в поддерживающих семьях, семьях временной подмены опекунов и семьях ухода за взрослыми; сотрудники, исполнители услуг, волонтёры и наставники воспитанников","Совместно проживающие с кандидатами в усыновители, приёмными семьями, руководителями семейных детских домов и семьями ухода; с поддерживающими и подменяющими семьями — при контакте с детьми","Представители зарубежных посредников и кандидаты в усыновители, проживающие за пределами Польши"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-29T19:12:08Z","assessed_at":"2026-10-29T19:12:08Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<i>Часть 1/2 · подготовлено 29 окт 2026. Условия и исключения — во всём тексте; прочитайте все части.</i>\n\n<b>Переводчик при усыновлении · UD354</b>\n📜 <b>Правительственный проект (RCL)</b>\n\nO wspieraniu rodziny i systemie pieczy zastępczej oraz niektórych innych ustaw\n\n👥 <b>Кого касается:</b> Несовершеннолетние иностранцы, находящиеся в Польше, включая не перечисленных в статье 5, части 1, пунктах 2–6; Иностранцы — кандидаты в усыновители, приёмные родители и руководители семейных детских домов; для приёмных родителей требуется законное пребывание; Иностранцы в поддерживающих семьях, семьях временной подмены опекунов и семьях ухода за взрослыми; сотрудники, исполнители услуг, волонтёры и наставники воспитанников; Совместно проживающие с кандидатами в усыновители, приёмными семьями, руководителями семейных детских домов и семьями ухода; с поддерживающими и подменяющими семьями — при контакте с детьми; Представители зарубежных посредников и кандидаты в усыновители, проживающие за пределами Польши\n\n💡 <b>Что это значит на практике:</b> При усыновлении ребёнка супруга исключаются общий запрет судимости и проверка совместно проживающих. При ввозе усыновляемого ребёнка расходы на перевод в исключительных случаях, особенно при родстве, свойстве или объединении братьев и сестёр, может принять центр либо центральный орган. Для действующих зарубежных посредников: сведения о ранее отсутствовавшем представителе — за 3 месяца, подтверждение соответствия представителей требованиям — за 6 месяцев со вступления закона в силу.\n\n🗣 <b>Общественные консультации:</b> завершились 15 мая 2026 · <a href=\"https://legislacja.rcl.gov.pl/docs//2/12408601/13194351/13194353/dokument769093.pdf\">письмо о консультациях</a>\n\n👉 <b>Что можно сделать сейчас:</b> публичные консультации уже закрыты, но пока проект в правительстве остаётся: <a href=\"https://legislacja.rcl.gov.pl/projekt/12408601/komentarz\">оставить комментарий через форму на RCL</a>; можно заявить интерес к работам над проектом (zgłoszenie zainteresowania) — письмом органу, который готовит проект: Minister Rodziny, Pracy i Polityki Społecznej · <a href=\"https://www.gov.pl/web/rodzina/kontakt\">адреса канцелярии, ePUAP и e-Doręczenia</a>\n\n🔑 <b>Ключевые изменения</b>\n• Проверяемые иностранцы представляют сведения о несудимости и отсутствии запретов из реестра страны гражданства; проверки — не реже 24 месяцев.\n• Министр может выделить центр усыновления для иностранцев; другие центры сохраняют компетенцию и могут использовать заключения из страны происхождения.\n• При недостаточном польском допускается переводчик, в том числе на обучении; при усыновлении ребёнка из-за рубежа расходы несут кандидаты.\n• При усыновлении с выездом в страну Гаагской конвенции: согласие на отчёты ежегодно первые 3 года после вступления решения в силу, затем раз в 3 года до 18 лет.\n• Иностранному представителю зарубежного посредника по усыновлению нужен документ о знании польского; аккредитация посредника — максимум на 2 года.\n\n📅 <b>Вступление в силу:</b> «Закон вступает в силу 1 октября 2026 года, за исключением: 1) статьи 1, пункта 17, и статьи 25 — с 1 января 2027 года; 2) статьи 1, пункта 101, статьи 2, пункта 1, статьи 3, пунктов 3 и 4, статей 8, 10 и 11, а также статьи 12, пункта 2, статей 16, 20–22 и 24 — с 1 января 2028 года; 3) статьи 1, пункта 150, подпункта d, пункта 152, подпункта d, пункта 155, подпункта c, пункта 157, подпункта a, второго и шестого абзацев перечня, а также пункта 158, подпунктов a, f и g, в части использования информационной системы — со дня, определённого в объявлении, предусмотренном статьёй 72».\n\n🗺 <b>Путь:</b> план ✓ → RCL ● → Сейм → комиссии → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> межведомственные согласования и сбор мнений, затем комитеты Совета министров, Rada Ministrów и внесение в Сейм · обычно 1–3 месяца на этом этапе; весь путь на RCL — 3–12 месяцев\n\n🏛 <b>Стадия:</b> сбор мнений министерств и партнёров (4. Opiniowanie)\n✍️ <b>Инициатор:</b> правительственный — Minister Rodziny, Pracy i P","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[238],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-29","still_meets":false,"reply_to":null,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["Несовершеннолетние иностранцы, находящиеся в Польше, включая не перечисленных в статье 5, части 1, пунктах 2–6","Иностранцы — кандидаты в усыновители, приёмные родители и руководители семейных детских домов; для приёмных родителей требуется законное пребывание","Иностранцы в поддерживающих семьях, семьях временной подмены опекунов и семьях ухода за взрослыми; сотрудники, исполнители услуг, волонтёры и наставники воспитанников","Совместно проживающие с кандидатами в усыновители, приёмными семьями, руководителями семейных детских домов и семьями ухода; с поддерживающими и подменяющими семьями — при контакте с детьми","Представители зарубежных посредников и кандидаты в усыновители, проживающие за пределами Польши"],"action":"wait","deadline":null,"deadline_source":null,"deadline_precision":"unknown","detected_at":"2026-10-29T19:12:08Z","assessed_at":"2026-10-29T19:12:08Z","novelty":"unknown","rule_version":"attention-v1"}');
