INSERT INTO "publications" VALUES(239,10,'RPW/36403/2026','new_bill','sent','@lex_inform_pl',151,'[]',NULL,'2026-10-29T19:12:28+00:00','2026-10-29T19:12:33+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"RPW/36403/2026\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o pomocy społecznej\",\"description\":\"wprowadzenia corocznej weryfikacji kryteriów dochodowych uprawniających do świadczeń z pomocy społecznej, począwszy od 2028 r., ze skutkiem w zakresie wysokości kryteriów od dnia 1 stycznia 2029 r.\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2026-10-28\",\"document_date\":\"2026-10-28\",\"change_date\":\"2026-10-28T00:00:00Z\",\"closure_date\":null,\"passed\":null,\"urgency_status\":null,\"eu_related\":false,\"rcl_num\":null,\"rcl_link\":null,\"prints_considered_jointly\":[],\"applicant\":\"deputies\",\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:uchodzcy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:ochrona_miedzynarodowa\",\"text:status_uchodzcy\",\"text:uznawanie_kwalifikacji\"],\"stages\":[],\"stages_fingerprint\":null,\"observed_closure_date\":null,\"consultation_review\":null,\"commission_review\":null,\"act_application_review\":null,\"review_work\":[],\"committee_documents\":null,\"observed_process\":null,\"analysis\":{\"analysis\":{\"relevant\":true,\"score\":3,\"category\":\"social\",\"summary\":\"Доходные пороги для социальной помощи пересматриваются ежегодно вместо одного раза в три года. Это также касается размеров помощи на содержание и изучение польского для беженцев, получателей дополнительной защиты и обладателей прямо указанного временного ВНЖ.\",\"key_changes\":[\"Доходные пороги социальной помощи пересматриваются ежегодно на основе исследования необходимых расходов.\",\"Минимум и максимум помощи на содержание и изучение польского меняются на 50% суммы прироста двух доходных порогов.\",\"Для расчёта берётся прирост порогов для одиноко проживающего человека и на одного члена семьи.\",\"В те же сроки по той же формуле меняются максимум постоянного пособия и база помощи на самостоятельную жизнь и учёбу.\",\"Первый пересмотр — в 2028 году; пересмотренные пороги и суммы применяются с 1 января следующего года, впервые — 2029 года.\"],\"affected_groups\":[\"Иностранцы, имеющие право на социальную помощь, зависящую от дохода\",\"Иностранцы, получившие в Польше статус беженца\",\"Иностранцы, получившие в Польше дополнительную защиту\",\"Иностранцы с временным ВНЖ по ст. 159 ч. 1 п. 1 подп. c или d ustawa o cudzoziemcach (закона об иностранцах)\"],\"practical_impact\":\"Для имеющих право на помощь иностранцев доходные пороги и связанные с ними суммы пересматриваются каждый год. Для перечисленных получателей интеграционной помощи ежегодно пересчитываются её минимум и максимум; фиксированного процента ежегодного повышения законопроект не устанавливает.\",\"effective_date\":\"Закон вступает в силу 1 января 2028 года.\",\"confidence\":0.99,\"rationale\":\"Оценка 3 и социальная категория обусловлены изменением периодичности пересмотра доходных порогов и размеров выплат, прямо предусмотренных для перечисленных групп иностранцев.\",\"mnemonic_candidate\":\"Ежегодный пересчёт интеграционной помощи\",\"mnemonic_fallback\":\"Ежегодный пересмотр интеграционных выплат\",\"mnemonic_basis\":\"Минимальные и максимальные выплаты на содержание и изучение польского для перечисленных иностранцев меняются в сроки ежегодного пересмотра доходных порогов.\",\"mnemonic_language\":\"ru\",\"changes_since_previous\":[]},\"model\":\"gpt-6.1-sol\",\"prompt_version\":\"2026-10-v13\",\"input_chars\":51065,\"truncated\":false,\"text_source\":\"pdf\",\"created_at\":\"2026-10-29T19:12:03Z\",\"computation_id\":\"result-v1:45ce3e693670caf73d3b4cc5a1d3aa30f0c712feaae7355394d0019d2453e90d\",\"request_sha256\":\"7197fa9f053f0fd1a3d0e42e51235ea96f5b05a147102543de262b9626b7e6ed\",\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0,\"source_url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf\",\"source_kind\":\"print\",\"revision\":1,\"text_sha256\":\"text-v2:ec5f5cd9ba7f09699205920e7723ad7a085f20d30da370bf757ce6197fc22bd5\",\"selection\":{\"question\":\"bill_text\",\"policy_version\":\"document-selection-v1\",\"state\":\"unverified\",\"belonging\":[],\"role\":[],\"version\":[],\"completeness\":[],\"parts\":[{\"url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf\",\"members\":[],\"container_sha256\":\"0465f82b7ac8c54dc0fa30bb433c31a38b489b64e6c68e139217f5409f7fe675\",\"sha256\":\"0465f82b7ac8c54dc0fa30bb433c31a38b489b64e6c68e139217f5409f7fe675\",\"role\":\"bill\",\"text\":\"\",\"pages\":21,\"page_start\":1,\"page_end\":21,\"text_start\":0,\"text_end\":51065,\"text_sha256\":\"4e65ecca9eadf5304fda125ba3f5aa4fc9ccf16436e2aaec8136731231c94c1b\",\"losses\":[]}],\"observed_parts\":[],\"rejected\":[],\"facts\":[{\"kind\":\"bill_structure\",\"value\":\"bill\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf\",\"text_sha256\":\"4e65ecca9eadf5304fda125ba3f5aa4fc9ccf16436e2aaec8136731231c94c1b\",\"block_id\":\"part:0\",\"start\":0,\"end\":85,\"quote\":\"projekt\\nUSTAWA\\nz dnia ……………………….. 2027 r.\\no zmianie ustawy o pomocy społecznej\\nArt. 1\"},{\"kind\":\"coverage\",\"value\":\"body_through_commencement\",\"provenance\":\"extracted_text\",\"part_index\":0,\"source_url\":\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf\",\"text_sha256\":\"4e65ecca9eadf5304fda125ba3f5aa4fc9ccf16436e2aaec8136731231c94c1b\",\"block_id\":\"part:0\",\"start\":4184,\"end\":4206,\"quote\":\"Ustawa wchodzi w życie\"}],\"limitations\":[\"missing_evidence\"],\"links\":[],\"coverage\":[{\"part_index\":0,\"stage\":\"extraction\",\"start\":0,\"end\":51065,\"page_start\":1,\"page_end\":21,\"losses\":[]},{\"part_index\":0,\"stage\":\"analysis\",\"start\":0,\"end\":51065,\"page_start\":null,\"page_end\":null,\"losses\":[]}],\"normative_sha256\":\"b455255ecdafc49d32ba6176010e69657ffbc15ba95dc155eb4aab867d41e3af\"},\"law_sha256\":\"law-v2:af6a1bcdc36ed01168b930bb09045acbd23c7e96ed6318c3a3e3bd7ad8a9b415\",\"source_checked_at\":\"2026-10-29T19:12:03Z\"},\"editorial\":{\"mnemonic\":{\"name\":\"Ежегодный пересчёт интеграционной помощи\",\"language\":\"ru\",\"basis\":\"Минимальные и максимальные выплаты на содержание и изучение польского для перечисленных иностранцев меняются в сроки ежегодного пересмотра доходных порогов.\",\"selected_at\":\"2026-10-29T19:12:03Z\",\"origin\":\"analysis\",\"version\":1,\"provisional\":false,\"command_update_id\":null,\"actor_id\":null,\"author_signature\":null},\"previous\":[],\"proposed\":null,\"priority\":null,\"priority_history\":[],\"announced_version\":0},\"analysis_attempts\":0,\"analysis_generation\":1,\"awaiting_batch_since\":null,\"ready_analysis\":null,\"last_error\":null,\"submission\":{\"term\":10,\"number\":\"RPW/36403/2026\",\"title\":\"Poselski projekt ustawy o zmianie ustawy o pomocy społecznej\",\"description\":\"wprowadzenia corocznej weryfikacji kryteriów dochodowych uprawniających do świadczeń z pomocy społecznej, począwszy od 2028 r., ze skutkiem w zakresie wysokości kryteriów od dnia 1 stycznia 2029 r.\",\"applicant\":\"deputies\",\"status\":\"ACTIVE\",\"submission_type\":\"BILL\",\"date_of_receipt\":\"2026-10-28\",\"print_number\":null,\"eu_related\":false,\"public_consultation\":true,\"consultation_start\":\"2026-10-29\",\"consultation_end\":\"2026-11-28\",\"consultation_results\":false,\"withdrawn_date\":null,\"senders_number\":null},\"linked_number\":null,\"linked_wykaz_number\":null,\"act\":null,\"authors\":null,\"agenda\":[],\"rcl\":null,\"wykaz\":null,\"senate\":null,\"seen_supplements\":null,\"joint\":null,\"discontinued_at\":null,\"observation_mode\":null,\"observation_basis\":null,\"first_seen_at\":\"2026-10-29T19:00:14Z\",\"last_checked_at\":\"2026-10-29T19:00:14Z\"}","attention":{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["Иностранцы, имеющие право на социальную помощь, зависящую от дохода","Иностранцы, получившие в Польше статус беженца","Иностранцы, получившие в Польше дополнительную защиту","Иностранцы с временным ВНЖ по ст. 159 ч. 1 п. 1 подп. c или d ustawa o cudzoziemcach (закона об иностранцах)"],"action":"submit_opinion","deadline":"2026-11-28","deadline_source":"https://opiniowanie.sejm.gov.pl/RPW-36403-2026","deadline_precision":"day","detected_at":"2026-10-29T19:12:28Z","assessed_at":"2026-10-29T19:12:28Z","novelty":"unknown","rule_version":"attention-v1"},"attention_history":[],"policy_version":"attention-v1","rendered_text":"<b>Ежегодный пересчёт интеграционной помощи · RPW/36403/2026 (номер druku ещё не присвоен)</b>\n📜 <b>Новый законопроект</b>\n\nO pomocy społecznej\n\n👥 <b>Кого касается:</b> Иностранцы, имеющие право на социальную помощь, зависящую от дохода; Иностранцы, получившие в Польше статус беженца; Иностранцы, получившие в Польше дополнительную защиту; Иностранцы с временным ВНЖ по ст. 159 ч. 1 п. 1 подп. c или d ustawa o cudzoziemcach (закона об иностранцах)\n\n💡 <b>Что это значит на практике:</b> Для имеющих право на помощь иностранцев доходные пороги и связанные с ними суммы пересматриваются каждый год. Для перечисленных получателей интеграционной помощи ежегодно пересчитываются её минимум и максимум; фиксированного процента ежегодного повышения законопроект не устанавливает.\n\n🗣 <b>Общественные консультации:</b> 29 окт - 28 нояб 2026 · <a href=\"https://opiniowanie.sejm.gov.pl/RPW-36403-2026\">анкета на сайте Сейма</a>\n\n👉 <b>Что можно сделать сейчас:</b> заполнить анкету <a href=\"https://opiniowanie.sejm.gov.pl/RPW-36403-2026\">на сайте Сейма</a> до 28 нояб 2026\n\n🔑 <b>Ключевые изменения</b>\n• Доходные пороги социальной помощи пересматриваются ежегодно на основе исследования необходимых расходов.\n• Минимум и максимум помощи на содержание и изучение польского меняются на 50% суммы прироста двух доходных порогов.\n• Для расчёта берётся прирост порогов для одиноко проживающего человека и на одного члена семьи.\n• В те же сроки по той же формуле меняются максимум постоянного пособия и база помощи на самостоятельную жизнь и учёбу.\n• Первый пересмотр — в 2028 году; пересмотренные пороги и суммы применяются с 1 января следующего года, впервые — 2029 года.\n\n📅 <b>Вступление в силу:</b> Закон вступает в силу 1 января 2028 года.\n\n🗺 <b>Путь:</b> Сейм ● → комиссии → II и III чтение → Сенат → Президент → Dz.U. → в силе\n⏭ <b>Что дальше:</b> консультации до 28 нояб 2026, затем присвоение номера druku и I чтение\n\n🏛 <b>Стадия:</b> проект поступил в Сейм, ожидает присвоения номера druku\n✍️ <b>Инициатор:</b> депутатский\n📄 <b>Поступил в Сейм:</b> 28 окт 2026\n🔎 <i>Найден по тексту проекта: название об иностранцах не говорит.</i>\n\n🟡 <b>Важность:</b> ●●●○○ 3/5\n🏷 <b>Категория:</b> соцсфера\n\n🔗 <a href=\"https://orka.sejm.gov.pl/Druki10ka.nsf/Projekty/10-RPW-36403-2026/$file/10-RPW-36403-2026.pdf\">PDF проекта (сайт Сейма)</a>\n\n#RPW_36403_2026 #важность3 #соцсфера #консультации","render_origin":null,"disable_notification":false,"schedule":null,"destination":"direct","destination_reason":"","proposed_destination":null,"digest_eligible_at":null,"digest_event_ids":[],"effective_rule_refs":[],"continuation_ids":[],"continuation_parent":null,"continuation_root":null,"continuation_index":1,"participation":null,"change_json":"","print_json":null,"primary_json":null,"item_json":null,"moved_from_json":null,"phase_json":null,"hearing_json":null,"today":"2026-10-29","still_meets":false,"reply_to":null,"edit_message_id":null,"revision_of":null,"amendment_key":"","held_change_ids":[],"wait_until":null,"absorbed_by":null,"update_group":[],"sitting_group":[],"digest_parts":[],"digest_ref":"","approve_label":"","group_text":"","with_act":false}','{"importance":"important","urgency":"normal","reasons":["new_anchor"],"explanation":"A new case needs its own reader anchor.","affected_groups":["Иностранцы, имеющие право на социальную помощь, зависящую от дохода","Иностранцы, получившие в Польше статус беженца","Иностранцы, получившие в Польше дополнительную защиту","Иностранцы с временным ВНЖ по ст. 159 ч. 1 п. 1 подп. c или d ustawa o cudzoziemcach (закона об иностранцах)"],"action":"submit_opinion","deadline":"2026-11-28","deadline_source":"https://opiniowanie.sejm.gov.pl/RPW-36403-2026","deadline_precision":"day","detected_at":"2026-10-29T19:12:28Z","assessed_at":"2026-10-29T19:12:28Z","novelty":"unknown","rule_version":"attention-v1"}');
