INSERT INTO "status_changes" VALUES(7,10,'1929','d952ae1bb283a01a45b43c430e34e212760b9360fdb4be41496cf835e1940524','1c9e4e859881e1808d4c32f22994f46b25ad3cceb4193b2a77b024355361d998','[{"stage_name": "Praca w komisjach po II czytaniu", "stage_type": "CommitteeWork", "date": "2026-09-15", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-09-15", "print_number": "2792-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf", "text_after3": null, "position": null, "proposal": "przyjąć część poprawek", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-09-15", "print_number": "2792-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf", "text_after3": null, "position": null, "proposal": "przyjąć część poprawek", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]',0,0,'2026-09-15T11:32:29+00:00',0,0,0,'{"amendments":{"summary":"Комиссия рекомендует принять лишь часть поправок: в основном технические и организационные (доставка уведомлений, координатор по трудовому договору, запрет двойного финансирования асистенции, сдвиг сроков), а поправки Президента РП — в том числе переписывающую перечень иностранцев в ст. 3 — и большинство поправок KP Razem и KP PiS предлагается отклонить.","changes":["Принять: право на асистенцию — при проживании в Польше по смыслу Kodeks cywilny весь период пользования (ст. 3 ust. 2)","Отклонить поправку Президента, переписывающую перечень иностранцев в ст. 3 ust. 1 (сохраняется текущий вариант)","Отклонить снижение порога с 80 до 70 баллов поддержки и отмену возрастного предела 65 лет","Принять: уведомления о документах в профиле — на указанный e-mail или телефон; бумажная доставка (поправки Президента) отклонена","Принять: запрет одновременного пользования асистенцией, финансируемой из Fundusz Solidarnościowy или по закону о реабилитации (новый ст. 83a)","Принять: координатор асистенции — только по umowa o pracę; перенос срока в ст. 118 с 31.12.2027 на 31.12.2028, в ст. 123 — до 31.12.2030"],"affects_foreigners":true,"confidence":0.72},"model":"claude-opus-5","prompt_version":"2026-09-v7","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2792-A/2792-A.pdf","source_kind":"committee_amendments","created_at":"2026-09-15T11:32:47Z","input_tokens":13670,"output_tokens":802,"cache_read_input_tokens":0,"cache_creation_input_tokens":1074}',NULL,0,0);
