INSERT INTO "status_changes" VALUES(52,10,'3039','cb84442d86c41c7859428d34b37b92124473038d0b68849912688cd593427255','895187d55c8ac7496856398c9089f7e4801aaec319494be24ba78a69aa435c5f','[]',0,0,'2026-10-01T20:28:27+00:00',0,0,0,NULL,'[{"number": "3039-005", "title": "Do druku nr 3039 - ocena skutków regulacji", "source_kind": "impact_assessment", "source_url": "https://api.sejm.gov.pl/sejm/term10/prints/3039-005/3039-005.pdf", "digest": {"summary": "Документ описывает, что проект расширяет поддержку для бенефициаров временной защиты со статusem UKR (около 8,5 тыс. людей в оśrodkach zbiorowego zakwaterowania и 176 тыс. вне них) и может стоить сектору финансов общественных свыше 1,2 млрд зł в год. Эксперты указывают на риск завышения/неправильной оценки прав на льготы (в т.ч. медуслуги по одному лишь заявлению), спорные критерии «групп уязвимых» и возможное несоответствие нормам ЕС по zamówienia publiczne при передаче управления центрами без конкурса.", "points": ["Проект охватывает 8 544 жителей OZZ и 176 000 уязвимых лиц вне центров", "Месячный koszt по расчётам MRPiPS – 18,6 млн зł плюс 85,36 млн зł на медпомощь", "Годовой совокупный koszt может превысить 1,247 млрд зł, а не 223 млн зł", "Есть риск дискриминации: проект отдельно защищает только «матерей-одиночек», а не отцов", "Самодекларация для доступа к медуслугам и отсутствие документов могут вести к злоупотреблениям", "Передача OZZ НПО и профсоюзам без конкурса может противоречить dyrektywa 2014/24/UE", "Проект может восприниматься как дающий преференции бенефициарам ochrony czasowej над поляками"], "supports": null, "affects_foreigners": true, "confidence": 0.9}, "model": "gpt-5.1-2025-11-13", "prompt_version": "2026-09-v9", "created_at": "2026-10-01T20:23:30Z", "input_tokens": 0, "output_tokens": 0, "cache_read_input_tokens": 0, "cache_creation_input_tokens": 0}]',0,0);
