INSERT INTO "status_changes" VALUES(145,10,'1929','747b8420383d1ead338059078e0570103dd4a355910b7d4c8ab77da852c231b9','56257e7b6c8a3e3cbcaeed4f4ebf2ba8779ea7ce783b1c3e9d4e1f97b4916b7b','[{"stage_name": "Praca w komisjach nad stanowiskiem Senatu", "stage_type": "CommitteeWork", "date": "2026-10-21", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-21", "print_number": "3255", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf", "text_after3": null, "position": null, "proposal": "przyjąć poprawki", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-21", "print_number": "3255", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf", "text_after3": null, "position": null, "proposal": "przyjąć poprawki", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]',0,1,'2026-10-21T18:53:55+00:00',0,0,0,'{"amendments":{"summary":"Документ комиссии не описывает содержание поправок Сената, а лишь рекомендует Сейму принять все 35 поправок к закону об личной ассистенции лиц с инвалидностью. Неясно, изменяют ли эти поправки объём прав или условия доступа к услуге для иностранцев.\n","changes":["Комиссия Polityki Społecznej i Rodziny рекомендует принять все 35 поправок Сената к закону.","Часть поправок предлагается голосовать совместно с другими (10 с 14; 13 с 15 и 28; 23 с 26; 24 с 29; 31 с 35).","Текст спrawozdania не содержит описания содержания поправок и их материальных последствий."],"affects_foreigners":false,"confidence":0.23,"source_evidence":{"subject":"Sprawozdanie Komisji Polityki Społecznej i Rodziny o uchwale Senatu w sprawie ustawy o asystencji osobistej osób z niepełnosprawnościami","adopted_on":"2026-10-21","decision":"amendments","complete":true,"resolution_page":null,"amendment_pages":[],"amendment_quote":"Komisja Polityki Społecznej i Rodziny ... wnosi: Wysoki Sejm raczy poprawki Senatu zawarte w: pkt 1 – przyjąć ... pkt 35 – przyjąć."}},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3255/3255.pdf","source_kind":"committee_amendments","created_at":"2026-10-21T18:29:52Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,0,0);
INSERT INTO "status_changes" VALUES(146,10,'3157','c6456e71574f1baa6c44feb3ce6d94909fb5c99a3fd97f92d33b1c448c7d2e9f','626842c5aff30a6dcaf32a39a75af4ab2c5ecd6f3b34a048afcd1fd7038f5142','[{"stage_name": "Praca w komisjach po II czytaniu", "stage_type": "CommitteeWork", "date": "2026-10-21", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-21", "print_number": "3193-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf", "text_after3": null, "position": null, "proposal": "przyjąć część poprawek", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-21", "print_number": "3193-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf", "text_after3": null, "position": null, "proposal": "przyjąć część poprawek", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]',0,0,'2026-10-21T18:53:59+00:00',0,0,0,'{"amendments":{"summary":"Комиссия предлагает принять лишь часть поправок: они уточняют новые ограничения по занятости и оплате труда медработников, а также действие переходных норм. Более радикальные изменения (повышение гарантированного финансирования, иная формула расчёта лимитов вознаграждений, расширение их на услуги вне договоров с NFZ) комиссия рекомендует отклонить.","changes":["Время дежурства вне медучреждения и на дому не войдёт в общий лимит занятости медиков.","Стационар и приём в больничной поликлинике должны вести медики с нагрузкой не менее 0,5 ставки.","Из этого требования выведены дежурства, работа вне обычных часов и услуги гериатров, патоморфологов, психиатров.","Процедура второй работы: при кадровом дефиците работодатель сперва предлагает поднять ставку, затем решает о согласии/увольнении.","Льготные лимиты оплаты в трансплантологии уточнены: касаются операций по изъятию и пересадке органов.","Нормы распространены и на служебные/иные отношения; часть переходных правил ст. 4 изменена или исключена, конфликтующие коллективные нормы действуют лишь в несопротиворечащей части."],"affects_foreigners":false,"confidence":0.73,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3193-A/3193-A.pdf","source_kind":"committee_amendments","created_at":"2026-10-21T18:29:54Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,0,0);
