INSERT INTO "status_changes" VALUES(153,10,'3146','3a03726dc6b5d56c938376e625fae40a7107ff0699abc27c0b5c3e7b9d6ffb77','415d07e1427dedbf2837ba4f1e8fff4cd8d03db3f21063af620975b331f503ec','[{"stage_name": "Praca w komisjach po II czytaniu", "stage_type": "CommitteeWork", "date": "2026-10-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-22", "print_number": "3196-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf", "text_after3": null, "position": null, "proposal": "przyjąć część poprawek", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-22", "print_number": "3196-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf", "text_after3": null, "position": null, "proposal": "przyjąć część poprawek", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]',0,0,'2026-10-22T18:17:39+00:00',0,0,0,'{"amendments":{"summary":"Поправки дорабатывают регулирование спецтранспорта Agencji Frontex и исключают один блок изменений (art.9); комиссия рекомендует принять только поправки KO (9–10 и 12), а все поправки KP PiS (1–8 и 11) об удалении частей проекта – отклонить.\nВ результате ключевые положения о сотрудничестве со Strażą Graniczną и об участии Frontex остаются в правительственной редакции, лишь технически уточняется режим для транспортных средств агентства.","changes":["В art.66 добавляется прямое упоминание Agencji Frontex в перечне субъектов, для чьего спецтранспорта задаются техтребования","Вводится новый ust.7a art.66: министр внутренних дел с минтрансом будет в регламенте определять техусловия спецтранспорта Agencji Frontex","Расширяется отсылка в art.66 ust.8 так, чтобы она охватывала также новый ust.7a о транспорте Agencji Frontex","Изменения в art.4 перегруппированы: правка art.66 выделена в отдельный pkt 3a вместо прежнего включения в pkt 3","Полностью исключается art.9 проекта (один из блоков изменений в другом законе)","Поправки KP PiS об удалении отдельных подпунктов и целых статей (1–8,11) отклонены, правительственный текст там не меняется"],"affects_foreigners":false,"confidence":0.62,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3196-A/3196-A.pdf","source_kind":"committee_amendments","created_at":"2026-10-22T18:13:48Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,0,0);
INSERT INTO "status_changes" VALUES(154,10,'3160','11b1f3e9f676a1b927b62217dac29474df607bd4606bec7e61cc70399b09e28d','2d5f7dfe841b4a3842b83930df0d1bc8f046262818bf19defc247c71ac1cc7d7','[{"stage_name": "II czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-10-22", "print_number": null, "sitting_num": 67, "decision": "skierowano ponownie do komisji w celu przedstawienia sprawozdania", "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-10-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "GOR", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-10-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "GOR", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": "Komisja Gospodarki i Rozwoju", "children": []}, {"stage_name": "Praca w komisjach po II czytaniu", "stage_type": "CommitteeWork", "date": "2026-10-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-22", "print_number": "3243-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3243-A/3243-A.pdf", "text_after3": null, "position": null, "proposal": "odrzucić poprawki", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-10-22", "print_number": "3243-A", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3243-A/3243-A.pdf", "text_after3": null, "position": null, "proposal": "odrzucić poprawki", "sub_committee": false, "minority_motions": 0, "voting": null, "committee_name": null, "children": []}]',0,0,'2026-10-22T18:17:41+00:00',0,0,0,'{"amendments":{"summary":"Поправки, внесённые клубом KP PSL, расширяют перечень целей поддержки инвестиций, смягчают новое правило по снижению занятости и меняют переходные нормы для уже начатых дел, а также вычеркивают несколько пунктов и статей проекта. Комиссия Gospodarki i Rozwoju рекомендует Сейму все эти поправки отклонить.","changes":["Добавляется цель поддержки: помощь предпринимателям в доступе к энергии, особенно из возобновляемых источников.","Из одной нормы убираются ссылки на spółka komandytowa и spółka komandytowo‑akcyjna.","Предлагается вычеркнуть два пункта изменений в основной статье, изменяющей базовый закон.","Предлагается полностью удалить из проекта статьи 16 и 23.","Снижение занятости: не более 20% от среднего за 12 мес. до заявки, с исключением на случаи ошибки.","Переходные нормы: для незавершённых и части старых дел о поддержке инвестиций уточняется, какие старые правила применять."],"affects_foreigners":false,"confidence":0.63,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3243-A/3243-A.pdf","source_kind":"committee_amendments","created_at":"2026-10-22T18:13:48Z","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,0,0);
