INSERT INTO "status_changes" VALUES(189,10,'3146','918a1c4ddc7cefbd0c4300f23613071123f39cf017721150ef82366336947525','c0f91391b84f9816d7d4d230715d5a1f34932bfb9761fc67ad2d528e92e3b81f','[{"stage_name": "Stanowisko Senatu", "stage_type": "SenatePosition", "date": "2026-10-27", "print_number": "3275", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": "wniósł poprawki", "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-10-28", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-10-28", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": "Komisja Administracji i Spraw Wewnętrznych", "children": []}]',0,1,'2026-10-28T19:18:25+00:00',0,0,0,'{"amendments":{"summary":"Поправки Сената в основном усиливают контроль за выдачей полномочий на применение силы, оружия и боеприпасов в операциях с участием Frontex и персонала других государств ЕС и уточняют ряд формулировок. Объём и характер операций по возвращению иностранцев не расширяются, меняются лишь процедуры согласования и терминология.","changes":["Полномочия персонала Frontex/ЕС на применение силы и оружия выдаются Komendant Główny SG только с согласия министра внутренних дел.","В нормах о Frontex-операциях прямо упомянуто применение не только оружия, но и боеприпасов.","Уточнено, что льготы при командировках касаются службы за границей на период свыше 30 дней.","В законе о Straży Granicznej введено единое обозначение «Agencja Frontex».","Скорректированы формулировки о финансировании операций и удалены лишние слова в новых статьях."],"affects_foreigners":true,"confidence":0.83,"source_evidence":null},"model":"gpt-5.1-2025-11-13","prompt_version":"2026-10-v12","source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3275/3275-uchwa%C5%82a.docx","source_kind":"senate_amendments","created_at":"2026-10-28T19:12:04Z","computation_id":"result-v1:ac61beabf382607e4fb057cd3b70531f02a44fc1083a25df16b114834ab6c2b8","request_sha256":"b024647583eebcc3ae4b5991249fe836094c7aa78accff4be8210ba2cea8a363","input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}',NULL,0,0);
